local _, ns = ...
ns.Quests = {
  [2] = {n="Skarpklos Klo", l="Tag Skarpklos Klo med til Senani Torduhjerte på Splintertræ-Posten i Askedalen.", d="Den mægtige hippogrif Skarpklo er blevet slået ihjel, og dyrets afhuggede klo står som et vidnesbyrd om din sejr. Senani Torduhjerte på Splintertræ-Posten vil uden tvivl være interesseret i at se denne trofæ som bevis på dine bedrifter."},
  [5] = {n="Rysterens Brølende Mave", l="Tal med Kok Grual.", d="Jeg har siddet gemt i denne spøgelsesby i flere uger, og jeg har ikke spist andet end larver og ukrudt! Jeg har brug for noget ordentligt mad, og jeg er villig til at betale godt for det.\n\nBring mig et festmåltid, så betaler jeg dig fyrstelig.\n\nJeg hørte, at Kok Grual på Skarlagenrød Ravns Kro i Mørkeshire laver meget gode Skumrings-krabbekager..."},
  [6] = {n="Belønning for Garrick Klodsfod", l="Dræb Garrick Klodsfod og før hans hoved til stedfortræder Willem ved Nordshire-klosteret.", d="Garrick Klodsfod - en snigmorder der har plaget vores bønder og købmænd i flere uger - blev set ved en hytte nær vinmarkerne, som ligger øst for klosteret og over broen. Bring mig skurkens hoved, så får du hans dusør!\n\nMen vær på vagt, <Name>. Garrick har samlet en bande af slagsbrødre omkring sig. Han bliver ikke let at komme til."},
  [7] = {n="Oprydning i Kobold-lejren", l="Dræb 10 Kobold-skadedyr, og vend derefter tilbage til Marskal McBride.", d="Din første opgave er en renselse, <Name>. En klan af kobolder har inficeret skoven mod nord. Gå derhen og kæmp mod de kobold-skadedyr du finder. Reducer deres antal, så vi en dag kan drive dem væk fra Nordshire."},
  [8] = {n="En Skurks Handel", l="Lever det Ubeskrivelige Brev til kroværtinde Renee i Tirisfals Lysninger.", d="Hej, makker! Gør en tjeneste for en ung mand, der har kæmpet mod mere end sin rimelige andel af tankeløse zombier og edderkopper?\n\nJeg har fået dette brev, som skal til Gryde-by... til en kroværtinde ved navn Renee noget-eller-andet. Det betyder ikke meget, hvad hendes efternavn er.\n\nUnder alle omstændigheder er det et hyggeligt lille sted, fuldt af pestofre der prøver at finde deres vej i verden. Og det er et godt sted for dig at hvile dig, hvis behovet opstår. Du burde tjekke det ud... gør du det, betaler jeg dig godt."},
  [9] = {n="Drabsmarkerne", l="Bonde Saldeen vil have dig til at dræbe 20 Høstvogtere.", d="Se, hvad der er sket med dette sted! Disse lande var engang beboet af gode landfolk. Men de forbandede tyve har jaget dem alle væk. Ikke mig, dog! Men det ser ud til, at nogle Høstvogtere har overtaget markerne.\n\nHvis du har lyst til arbejdet, vil jeg gerne have dig til at gå derud og dræbe tyve af dem. Kom tilbage, når du er færdig, for din betaling. Hvis du får styr på dem på min mark, så ryd også dem på de nabomarker."},
  [11] = {n="Flodpote-gnoldens Dusør", l="Før 8 Malede Gnoldarmbånd til stedfortræder Rainer i Kasernen.", d="Gnolder, brutale væsner uden nogen anstændig forretning i disse lande, er blevet set langs grænsen til Elwynnskoven. En stor flok af dem, langt flere end vi kan klare alene, har inficeret skoven syd for vagttårnet derovre. En anden gruppe har inficeret områderne nær Stenrøsesøen mod øst.\n\nStormvindsk Hær vil rose enhver, der hjælper med at dræbe dem. Bring mig deres malede gnoldarmbånd som bevis på din bedrift."},
  [12] = {n="Folkemilitsen", l="Gryan Tykfrakke vil have dig til at dræbe 15 Defias-fælder og 15 Defias-smuglere og derefter vende tilbage til ham på Vagtbakken.", d="Folkemilitsen har kun ét mål: At forsvare Vestfalds lande og genskabe freden i vores omgivelser. Desværre er prisen for fred ofte blod.\n\nEn af mine spejdere har bragt nyt om en flok Defias-fælder, der hærger i nærheden. Jeg har rapporter om Defias-fælder set nær Jangolade-minen mod nordvest samt ved Molsens Gård og Furlbrows Græskargård. Hvis du ønsker at slutte dig til vores rækker, så slå 15 Defias-fælder og 15 Defias-smuglere ihjel og vend derefter tilbage til mig."},
  [13] = {n="Folkemilitsen", l="Gryan Tykfrakke vil have dig til at dræbe 15 Defias-hærgere og 15 Defias-plyndrere og vende tilbage til ham på Vagtbakken.", d="En flok ondskabsfulde Defias-hærgere er set plyndre Guldkystens Stenbrud, Månebæk og Alexstons Gård. Folkemilitsen vil ikke finde sig i sådan adfærd. Afsted med dig med det samme, <Name>, og lad Lysets nærvær mærkes i Vestfald.\n\nGuldkystens Stenbrud ligger ved kysten, vest for tårnet. Som næste skridt i din træning vil jeg have dig til at dræbe 15 af de modbydelige Defias-hærgere og 15 Defias-plyndrere."},
  [14] = {n="Folkemilitsen", l="Gryan Tykfrakke vil have dig til at dræbe 15 Defias-røvere, 5 Defias-stisnigere og 5 Defias-knoglebrækkere og derefter vende tilbage til ham på Vagtbakken.", d="Nogle Defias har undsluppet os. Min mest betroede spejder melder, at disse Defias har plyndret og hærget landskabet helt ned til Sydlige Vestfald. Vi tror, de gemmer sig i Dolkebakkerne og planlægger deres næste træk. Slå de elendige ihjel i Folkemilitsens navn."},
  [15] = {n="Undersøg Ekkoryg", l="Dræb 10 Kobold-arbejdere, og rapportér derefter tilbage til Marskal McBride.", d="<Name>, mine spejdere fortæller mig, at kobold-angrebet er større, end vi havde troet. En gruppe kobold-arbejdere har slået lejr nær Ekkoryg-minen mod nord.\n\nGå til minen og fjern dem. Vi ved, at der er mindst 10. Dræb dem, se om der er flere, og rapportér derefter tilbage til mig."},
  [16] = {n="Giv Gerard en Drink"},
  [18] = {n="Tyvenes Broderskab", l="Før 12 Røde Sækkelærreds-halstørklæder til stedfortræder Willem uden for Nordshire-klosteret.", d="For nylig har en ny gruppe tyve holdt til omkring Nordshire. De kalder sig Defias-broderskabet og er set på den anden side af floden mod øst.\n\nJeg ved ikke, hvad de har gang i, men jeg er sikker på, at det ikke er godt! Bring mig de halstørklæder, de bærer, så belønner jeg dig med et våben."},
  [19] = {n="Tharil'hund", l="Bring Tharil'hunds Hoved til Marskal Marris i Rødryg.", d="Sortklippe-løbere og renegater overfalder folk mellem her og Stenvagtsfæstningen. Lederen af løberne er en orker ved navn Tharil'hund--vi vil have netop den orker. Bring mig Tharil'hunds hoved!"},
  [20] = {n="Sortklippe-truslen", l="Bring 10 Slidte Kampøkser til Marskal Marris i Søshire.", d="Sortklippe-orkerne er rejst fra Brændende Stepper og har taget Stenvagtsfæstningen mod nord. Derfra hærger de områderne nord for Søshire og holder byens borgere inde, indhegnet som kvæg.\n\nHjælp med at fjerne denne trussel fra Søshire. Dræb disse Sortklippe-orker og bring mig ti af deres Slidte Kampøkser som bevis.\n\nOg selvom Sortklippe-folket truer os fra nord, har vi modtaget rapporter om flere i den sydøstlige lomme af Rødryg. Hvis du finder nogen dér, skal de også jages."},
  [21] = {n="Træfning ved Ekkoryg", l="Dræb 12 Kobold-håndlangere, og vend derefter tilbage til Marskal McBride ved Nordshire-klosteret.", d="Dine tidligere undersøgelser beviser, at Ekkoryg-minen skal renses. Vend tilbage til minen og hjælp med at rydde den for kobolder.\n\nSpild ikke tiden, <Name>. Jo længere kobolderne får lov at være i minen uforstyrret, jo dybere fodfæste får de i Nordshire."},
  [22] = {n="Blodsnuser-leverpostej", l="Salma Saldeen har brug for 8 Blodsnuser-lever for at lave en Blodsnuser-leverpostej.", d="Løgene er skrællet. Hvidløget er hakket. Rosmarinen er knust. Skorpen er bagt. Dildurten er hakket. Saucen simrer. Nu mangler jeg kun 8 Blodsnuser-lever til min berømte kødpostej!"},
  [23] = {n="Bjørnegusens Pote", l="Før Bjørnegusens Pote til Senani Torduhjerte på Splintertræ-Posten i Askedalen.", d="<Den mægtige bjørn Bjørnegusens pote er dit trofæ for denne del af Askedalen-jagten. På poten er et lille halvmåneformet mærke; mærkets betydning er stadig et mysterium.\n\nPoten skal bringes til Senani Torduhjerte på Splintertræ-Posten for at bevise, at du har overvundet det mægtige væsen og fuldført denne del af jagten.>"},
  [24] = {n="Skyggedrøms Hoved", l="Før Skyggedrøms Hoved til Senani Torduhjerte på Splintertræ-Posten i Askedalen.", d="Den engang så hurtige Skyggedrøm ligger nu stille, mens du tager sejren over den. Hovedet af den dræbte natsabel er et passende trofæ for denne kamp på Askedalen-jagten. Senani Torduhjerte på Splintertræ-Posten vil gerne se et sådant trofæ for at give dig kredit for denne del af Askedalen-jagten."},
  [25] = {n="Stenklippe-stilstanden", l="Slå 12 Forurenede Vandelementaler ihjel ved Mystral-søen, lige øst for Klodsdybe-stien og sydvest for Splintertræ-Posten.\n\nSpejd det lille lysthus ved Mystral-søen, som har udsigt over den nærliggende Alliance-forpost.\n\nVend tilbage til Mastok Snirkelsnor på Splintertræ-Posten i Askedalen.", d="Hvis du vil være nyttig, hvorfor gør du så ikke noget ved situationen nær Klodsdybe-stien?\n\nTransporten mellem Askedalen og Stenklippe står stille, fordi søen er blevet levende og angriber alt, der kommer for tæt på... hvilket vil sige enhver på stien. Det der ville være endnu mere nyttigt end blot at slå vandelementalerne dér ned, er at nogen spejder lysthuset ved Mystral-søen - det med en klar udsigt over Alliance-forposten dér.\n\nEr du klar til at være nyttig?"},
  [27] = {n="En Lektie at Lære", l="Tal med Dendrit Stjerneblus i landsbyen Nathavn, Månelunden.", d="<Name>, jeg har fulgt dine fremskridt med stor glæde. Du udvikler dig bestemt til en værdsat beskytter af naturen.\n\nTiden er kommet til, at du skal lære mere om et af de mange dyreaspekter, som Cenarius har velsignet os med evnen til at forvandle os til - et der giver dig kontrol over og mestring af vandet. Til dette skal du rejse til landsbyen Nathavn i Månelunden og tale med Dendrit Stjerneblus fra Cenarion-kredsen dér. Han vil vejlede dig videre."},
  [28] = {n="Søprøven", l="Find en Helligdoms-pynt i Elune'ara-søen, og tag den med til Remulos' Helligdom i det nordvestlige Månelunden. Når du er der, så brug Helligdoms-pynten.\n\nDu skal tale med Tajarie ved helligdommen bagefter for at fuldføre prøven.", d="Til din første prøve skal du søge i dybderne af Elune'ara-søen for at finde en Helligdoms-pynt. Den forfalder hurtigt, så skynd dig med den til Remulos' Helligdom. Brug pynten ved helligdommen, og tal derefter med Tajarie dér; hun er en af Månelundens mest betroede vogtere.\n\nDu har kun en fastsat mængde tid til at fuldføre opgaven, og du kan komme til at konkurrere mod andre druider, der også leder efter pynt. Mental og fysisk spidsighed vil være afgørende for din succes.\n\nHeld og lykke, <Name>."},
  [29] = {n="Søprøven", l="Find en Helligdoms-pynt i Elune'ara-søen, og tag den med til Remulos' Helligdom i det nordvestlige Månelunden. Når du er der, så brug Helligdoms-pynten.\n\nDu skal tale med Tajarie ved helligdommen bagefter for at fuldføre prøven.", d="Til din første prøve skal du søge i dybderne af Elune'ara-søen for at finde en Helligdoms-pynt. Den forfalder hurtigt, så skynd dig med den til Remulos' Helligdom. Brug pynten ved helligdommen, og tal derefter med Tajarie dér; hun er en af Månelundens mest betroede vogtere.\n\nDu har kun en fastsat mængde tid til at fuldføre opgaven, og du kan komme til at konkurrere mod andre druider, der også leder efter pynt. Mental og fysisk spidsighed vil være afgørende for din succes.\n\nHeld og lykke, <Name>."},
  [30] = {n="Søløve-prøven", l="Find Akvatisk Smidigheds Halve Vedhæng og Akvatisk Udholdenheds Halve Vedhæng. Tal med indbyggerne i Månelunden for at lære, hvor disse genstande kan findes.\n\nLav Søløvens Vedhæng af de to vedhængshalvdele. Du skal befinde dig i nærheden af Remulos' Helligdom for at gøre dette.\n\nBring det samlede vedhæng til Dendrit Stjerneblus i landsbyen Nathavn, Månelunden.", d="Til den anden prøve skal du bruge de to halvdele, der udgør Søløvens Vedhæng. Den ene halvdel henter kraft fra søløve-aspektets smidighed, mens den glider gennem vandet; den anden henter kraft fra søløve-aspektets utrolige udholdenhed. Druider trækker lige meget på begge disse egenskaber for at udtrykke aspektet af deres akvatiske form.\n\nTal med lokalbefolkningen i Månelunden for at lære, hvor delene kan ligge, og bring dem begge hertil for at samle dem. Når vedhænget er dannet, skal du tage det med til Dendrit Stjerneblus."},
  [31] = {n="Akvatisk Form", l="Vend tilbage til Tordenklippe og vis Turak Runetotem Søløvens Vedhæng.", d="Du har fuldført de nødvendige lektioner, alle unge druider lærer, før de kan antage et akvatisk aspekt. Gå nu tilbage til din træner, Turak Runetotem, i Tordenklippe. Vis ham dit vedhæng og bevis over for ham, at du er klar til at lære det, han har at lære dig. Han vil fuldføre din træning, så du kan blive ét med vandet.\n\nFarvel, unge druide. Vi snakkes igen."},
  [33] = {n="Ulve over Grænsen", l="Bring 8 stykker Sejt Ulvekød til Eagan Pelsskinner udenfor Nordshire-klosteret.", d="Jeg hader de ækle tømmerulve! Men jeg elsker da at spise ulvebøffer... Bring mig sejt ulvekød, så bytter jeg det til noget, du kan have gavn af.\n\nSejt ulvekød samles ved at jagte tømmerulvene og de unge ulve, der strejfer rundt i Nordshires landskab."},
  [34] = {n="En Uvelkommen Gæst", l="Martie Rosenlund fra Søshire vil have dig til at dræbe Bulkmave. Bring hans hugtand som bevis.", d="Endnu engang er min have blevet trampet ned og plyndret. Og jeg kender det uhyre, der gør det. Det er den forbandede vildsvin, som Marskal Marris har taget til at kalde Bulkmave.\n\nJeg kan ikke genplante påskeliljerne før næste sæson nu. Ødelagt! Alt er ødelagt af den ene truende vildsvin. Gør ende på den plage! Vis mig hans hugtand, så belønner jeg dig gerne. Han synes at bruge sin tid på at rode i marken sydvest for Søshire, men af og til strejfer han herover og ind i min have."},
  [35] = {n="Yderligere Bekymringer", l="Marskal Dughan vil have dig til at tale med Vagt Thomas.", d="Hvis du er bekymret for, at rygterne om mudderfisk er sande, så gør dette -- rejs til broen i det østlige Elwynn og tal med Vagt Thomas. Han har været stationeret ved broen den sidste uge og ved, hvordan tingene står i området.\n\nBring mig hans rapport."},
  [36] = {n="Vestfald-gryderet", l="Verna Furlbrow vil have dig til at levere hendes opskrift på Vestfald-gryde til Salma Saldeen.", d="Jeg troede aldrig, dagen ville komme, hvor jeg forlod gården. Men markerne er oversvømmet med tyve, og det er alt for farligt for os her nu. Så snart Bonde Furlbrow får vognen repareret, er vi på vej.\n\nMon du kunne gøre mig en tjeneste? Lad mig skrible min opskrift på Vestfald-gryde ned. Vær sød at tage den med til Salma Saldeen på gården derovre. Saldeens gård ligger lige efter vejkrydset."},
  [37] = {n="Find de Forsvundne Vagter", l="Vagt Thomas vil have dig til at rejse nordpå langs floden og lede efter de to forsvundne vagter, Rolf og Malakai.", d="For et par dage siden sendte vi to vagter, Rolf og Malakai, ud for at undersøge langs floden, og de er endnu ikke vendt tilbage. For at fuldføre min rapport må jeg vide, hvad der er sket med de mænd.\n\nRejs nordpå langs floden og find vagterne... eller deres rester."},
  [38] = {n="Vestfald-gryderet", l="Salma Saldeen vil have 3 Sej Gribbekød, 3 Blodsnuser-snuder, 3 Mudderfisk-øjne, 3 Okra.", d="Hjælp mig med at lave noget Vestfald-gryde! Kom tilbage med følgende ingredienser:\n\n3 Sej Gribbekød\n3 Blodsnuser-snuder\n3 Mudderfisk-øjne\n3 Okra"},
  [39] = {n="Aflever Thomas' Rapport", l="Rapportér til Marskal Dughan i Guldshire.", d="Fortæl Marskal Dughan om Malakai og Rolfs død, og rapportér til ham, at mudderfiskene i det østlige Elwynn ikke kan holdes i ave med vores nuværende troppestyrke.\n\nJeg ved godt, at vi ikke har mange tropper at undvære, men forhåbentlig kan Dughan finde nogen."},
  [40] = {n="En Fisket Fare", l="Remy \"Tosidet\" vil have dig til at tale med Marskal Dughan i Guldshire.", d="<Name>, der er en ny trussel i Elwynnskoven! Mudderfisk svømmer op ad åerne i det østlige Elwynn, skræmmer fisken væk og angriber fredelige folk!\n\nJeg advarede Marskal Dughan, men han er mere bekymret for gnolderne og banditterne. Han er ikke overbevist om, at mudderfiskene er en fare.\n\nVær sød, <Name>, tal med Dughan og overtal ham til at sende flere tropper mod øst!"},
  [45] = {n="Opdag Rolfs Skæbne", l="Søg i mudderfisk-landsbyen efter Rolf, eller tegn på hans død.", d="Ved nærmere eftersøgning af området finder du svømmehudede fodspor, der fører østpå langs bredden af Stenrøsesøen. I det fjerne mod øst kan du lige akkurat skimte en mudderfisk-landsby.\n\nMåske endte Rolfs skæbne der..."},
  [46] = {n="Dusør på Mudderfisk", l="Bring 8 Revne Mudderfinner til Vagt Thomas ved broen i det østlige Elwynn.", d="Stormvindsk Hær har sat en dusør på mudderfisk-lurere og -sankere i Elwynn. Slagt dem og bring mig deres revne mudderfinner, så belønner Stormvindsk Hær dig rigeligt.\n\nMudderfiskene har bygget en landsby ved Stenrøsesøen nord herfra og en anden mod syd, hvor åen deler sig."},
  [47] = {n="Guldstøv-byttehandel", l="Bring 10 Guldstøv til Remy \"Tosidet\" i Guldshire. Guldstøv samles fra kobolder i Elwynnskoven.", d="Kobolderne her omkring har nogle gange guldstøv på sig. Jeg kunne virkelig bruge det - bring mig en masse af det, så giver jeg dig den bedste pris i byen... bedste pris i byen!\n\nDu kan finde kobolder i Fjerndyb-minen mod syd og omkring Jaspisåre-minen mod nordøst."},
  [52] = {n="Beskyt Grænsen", l="Dræb 8 Lurere og 5 Unge Skovbjørne, og vend derefter tilbage til Vagt Thomas ved broen i det østlige Elwynn.", d="Hils, <Name>. Vilde dyr bliver mere og mere aggressive, jo længere vi kommer fra Guldshire, og Østdal Tømmerlejr bliver næsten konstant angrebet af ulve og bjørne!\n\nVi kunne bruge din hjælp herude."},
  [54] = {n="Rapportér til Guldshire", l="Tag Marskal McBrides Dokumenter med til Marskal Dughan i Guldshire.", d="<Name>, du er en <Class> med dokumenteret interesse for Nordshires sikkerhed. Du er nu betroet med beskyttelsen af den omkringliggende Elwynnskov.\n\nHvis du accepterer denne pligt, har jeg forberedt papirer, som skal leveres til Marskal Dughan i Guldshire. Guldshire ligger ad den sydlige vej, forbi grænseportene."},
  [55] = {n="Morbent Ondt", l="Brug Morbents Svøbe på Morbent Ondt, dræb Morbent Ondt, og returnér derefter Morbents Svøbe til Sven i hans lejr.", d="Morbent Ondt gemmer sig i sit hi, huset der sidder på toppen af bakken mod øst med udsigt over Ravnehøj-kirkegården. Hans tid i dette land er ved at rinde ud...\n\nBrug Morbents Svøbe mod ham. Den vil gøre hans beskyttende magier magtesløse.\n\nDræb ham. Dræb ham, og frels os fra hans ondskab. Vær mit hævnredskab og en helt fra Skumringsskoven!"},
  [56] = {n="Nattevagten", l="Kommandør Althea Ebenlås fra Mørkeshire vil have dig til at dræbe 8 Skeletkrigere og 6 Skeletmagikere.", d="Som Kommandør for Nattevagten er det min højtidelige pligt at beskytte borgerne i Mørkeshire. Stormvind har trukket sine udstationerede vagter tilbage fra deres poster her og overladt os til os selv.\n\nHvis du mener dig værdig til opgaven, har vi brug for din hjælp! Hjælp Nattevagten ved at begive dig ud i Stille Haver, lige syd for Mørkeshire, og slå 8 Skeletkrigere og 6 Skeletmagikere ihjel. Den udøde trussel må standses!"},
  [57] = {n="Nattevagten", l="Kommandør Althea Ebenlås fra Mørkeshire vil have dig til at dræbe 15 Skeletdæmoner og 15 Skeletgyser.", d="<Name>, jeg får rapporter om en udød plage i skoven! Hvis du er klar til opgaven, så rejs til Ravnehøj-kirkegården og slå 15 af de modbydelige Skeletdæmoner og 15 Skeletgyser ihjel. Der er også rapporter om skeletter lige syd for Mørkeshire, i og omkring Stille Haver-kirkegården. De udøde må drives ud af Skumringsskoven!"},
  [58] = {n="Nattevagten", l="Kommandør Althea Ebenlås fra Mørkeshire vil have dig til at dræbe 20 Pestspredere i det østlige Ravnehøj-mausoleum.", d="Situationen på Ravnehøj er stadig dyster. Mørkeshires sikkerhed ligger i dine hænder, <Name>. Jeg har ikke nok Vagtere til at holde byen sikker. Vi har brug for, at du drager til Ravnehøj endnu engang og renser det østlige mausoleum for 20 Pestspredere!"},
  [59] = {n="Stof- og Læderrustning", l="Giv Sara Tømmerlund Stormvindsk Rustningsmærke.", d="For din snilde og tapperhed har jeg et mærke her, der er godt for ét stykke rustning. Jeg vil have dig til at tage det med til Sara Tømmerlund ved Østdal Tømmerlejr. Giv hende mærket, så vil hun smede rustningen til dig. Og når du har fået den, <Name>, så brug den til at forsvare Elwynn.\n\nØstdal Tømmerlejr ligger hinsides Vagt Thomas' post mod øst."},
  [60] = {n="Kobold-lys", l="Bring 8 Store Lys til William Støder i Guldshire.", d="Hej, god herre/mylady! Har du et øjeblik?\n\nMin bror og jeg driver et apotek i Stormvind, og jeg er her for at samle store lys til deres voks. Kan du hjælpe mig?\n\nDu kan få store lys fra kobolder, og jeg hører rygter om, at kobolder hærger Elwynn-minerne ... Fjerndyb-minen mod syd og Jaspisåre-minen mod øst. Jeg foreslår, at du leder efter lys på et af de steder."},
  [61] = {n="Forsendelse til Stormvind", l="Bring Williams Forsendelse til Morgan Støder i Stormvinds Handelsdistrikt.", d="Min bror Morgan venter i Stormvind på min forsendelse af lys. Jeg har ikke tid nok til selv at tage turen, men hvis du vil tage forsendelsen med til ham, betaler han godt.\n\nJeg har pakket lysene, og du finder Morgan i vores butik, Støders Apotek, i Stormvinds Handelsdistrikt."},
  [62] = {n="Fjerndyb-minen", l="Udforsk Fjerndyb-minen, og vend derefter tilbage til Marskal Dughan i Guldshire.", d="Minen i Nordshire er ikke den eneste med problemer! Jeg har rapporter om, at Fjerndyb-minen i Elwynn også er blevet et tilflugtssted for kobolder.\n\nUdforsk minen og bekræft disse rapporter, og vend så tilbage til mig. Minen ligger næsten lige syd for Guldshire, mellem Stenmark- og Maclure-gårdene."},
  [63] = {n="Vandets Kald", l="Besejr den Korrumperede Vandmanifestation og læg den Korrumperede Manifestations Armbånd sammen med de Resterende Dråber af Reneste Vand på Evigkildes Brasekurv i Sølvfyrreskoven.", d="Langs kysten af Sølvfyrreskoven, vest for Gravkammeret, finder du en helligdom, der er blevet besmittet af pesten. Ånderne dér taler ikke længere til vores folk, og det bliver op til dig at besejre manifestationen og rense bassinet.\n\nTag elementarens armbånd sammen med de resterende dråber af Saltlages eliksir, og læg dem på brasekurven. Ritualet burde være nok til at fremkalde en ren ånd, som du kan kommunikere med.\n\nBring mig bevis på, at opgaven er udført, så belønner jeg dig med din totem."},
  [64] = {n="Den Glemte Arvestykke", l="Bonde Furlbrow vil have dig til at hente hans lommeur fra skabet i hans landhus ved græskargården mod vest.", d="Det var forfærdeligt! Verna vækkede mig, da hun hørte et spektakel ude på markerne. Markerne var fulde af gadedrenge. Vi forlod stedet i en fart, og jeg glemte at pakke mit lommeur. Vernas far gav mig det ur på vores bryllupsdag, og jeg bliver helt syg af at vide, at de tyve har det. Jeg lod lommeuret ligge i skabet i landhuset. Led efter marken med græskar mod vest -- du kan ikke tage fejl af den. Hvis du bringer det tilbage til mig, ville jeg være dig utrolig taknemmelig!"},
  [65] = {n="Defias-broderskabet", l="Gryan Tykfrakke vil have dig til at tale med Snedig i Søshire.", d="Bandet af ynkskabninger, der har drevet de gode folk i Vestfald fra landet, kalder sig Defias-broderskabet. Jeg har brug for, at du infiltrerer denne klan af gangstere. Vi må vide, hvem der står i spidsen for kartellet, og hvor de gemmer sig. I Søshire, i kroen, er der en skurk ved navn Snedig, som skylder mig en tjeneste.\n\nRejs til Søshire i Rødryg-bjergene, øst for Elwynn, og find ud af, hvad du kan."},
  [66] = {n="Stalvans Legende", l="Find Skriver Daltry i Mørkeshires rådhus.", d="I går nat for en forfærdelig uro gennem mine årer. Jeg fornemmede, at mit barnebarn, Alyssa, var i stor fare. Jeg rådførte mig med kortene, og Døden stirrede tilbage på mig fra bordet.\n\nEfter en lang rejse gennem en mørk trance lykkedes det mig at finde et spor til dette skræmmende mysterium. Et navn kom til mig, navnet Stalvan.\n\nSøg skriveren i rådhuset og se, om du kan finde ud af mere om denne karakter. Jeg frygter for os alle."},
  [67] = {n="Sagnet om Stalvan", l="Rejs til Månebæk-skolehuset og bring alle opdaterede oplysninger om Stalvan tilbage til Skriver Daltry.", d="Stalvan, hva'? Lad mig tjekke byens register.\n\nStalvan... Stalvan... lad os se. Ah, der er den! Jeg har en optegnelse over en hr. Stalvan Tågekappe. Den sidst registrerede adresse er Månebæk-skolehuset. Gud, hvor er det forældet!\n\nVil du gøre mig en tjeneste, ven? Hvis du tilfældigvis kommer ud til Månebæk, så lad mig vide, om du får nyt om karen. Jeg kan lide at holde mine optegnelser i orden."},
  [68] = {n="Sagnet om Stalvan", l="Tag det Støvede Ikke-Afsendte Brev til Skriver Daltry.", d="Du finder et Støvet Ikke-Afsendt Brev i den gamle kuffert."},
  [69] = {n="Sagnet om Stalvan", l="Gå til Løvens Stolthed Kro og spørg, om nogen dér har hørt navnet Stalvan.", d="Åh, min! Må have overset det første gang. I registret, lige under Stalvans første adresse, står der endnu en, kun delvist overstreget. Det ser ud til, at han var på vej til Løvens Stolthed Kro i Guldshire. Du bør nok tjekke der, <Name>."},
  [70] = {n="Sagnet om Stalvan", l="Hent Stalvans Uafleverede Brev fra kisten og lever det til Kanalkvarteret i Stormwind.", d="Navnet Stalvan ringer en klokke. Nu husker jeg det.\n\nFor mange år siden kom en budbringer ind en stormfuld nat og bad om ly for natten. Lidt før midnat løb manden ned ad trapperne og skreg, hans ansigt blegt af frygt. Stadig iført sit natlinned forsvandt han ud i regnskylden.\n\nI sin hast glemte han sine breve i kisten deroppe. Han kom aldrig tilbage efter dem. Ét er tilbage fra den Stalvan-karl, beregnet til Kanalkvarteret i Stormwind. Tag dig frit af det."},
  [71] = {n="Rapport til Thomas", l="Lever Rolf og Malakais Medaljoner til Vagt Thomas ved den østlige Elwynn-bro.", d="Nu hvor du har begge medaljoner, så lever dem til Vagt Thomas ved broen, så han kan få at vide, hvad der er sket med hans myrdede vagter."},
  [72] = {n="Sagnet om Stalvan", l="Gennemgå de pakkede ejendele for et spor.", d="Min far var forvalter på godset længe før mig. Han måtte skrubbe blodet op efter massakren. Men det er hverken her eller der.\n\nDe sidste midler fra Flintkammen-fonden er tørret ud. Nu er de sidste af familiens ejendele på vej til auktion. Skyld på skattegribbene. Hvis du virkelig brænder efter at lære mere, er du velkommen til at rode igennem dette skrammel. Hvem ved, hvad du kan finde."},
  [74] = {n="Sagnet om Stalvan", l="Den Revne Dagbogsside, du fandt, giver dig dit næste spor.", d="Inde i kassen finder du forskelligt: muggent arvegods, et familieportræt, et par jagttrofæer og nogle gamle bøger. Nede i bunden, under en keramisk vase, afdækker du en Revet Dagbogsside."},
  [75] = {n="Sagnet om Stalvan", l="Marskal Udmattet vil have dig til at tjekke kisten deroppe for den Falmede Dagbogsside.", d="Der lå en bunke pergamenter i kisten deroppe, da jeg flyttede ind her. Jeg kiggede på dem én gang, da jeg først kom, men gav op, da tågen tilslørede mine øjne.\n\nGør en gammel, næsten blind mand en tjeneste og tjek kisten deroppe for alt, der kan hjælpe dig i din jagt på at finde mere om denne Stalvan-type. Jeg er ret sikker på, at der er en falmet dagbogsside, der kan interessere dig. Bring den til mig, så hjælper jeg på en eller anden måde."},
  [76] = {n="Jaspisåre-minen", l="Udforsk Jaspisåre-minen, og rapportér derefter tilbage til Marskal Dughan i Guldshire.", d="Takket være dig ved vi, at Fjerndyb-minen er invaderet af kobolds. Nu har vi brug for en spejder til at undersøge den fjernere Jaspisåre-mine.\n\nUdforsk Jaspisåre og bekræft eventuel kobold-tilstedeværelse. For at nå minen skal du rejse mod øst ad vejen, indtil du når Azoras Tårn. Fra tårnet går du mod nord, så finder du minen i foden af bjergene."},
  [78] = {n="Sagnet om Stalvan", l="Tag den Falmede Dagbogsside til Krovært Smedsen.", d="Jeg kender en, der måske kan hjælpe dig. Dengang jeg førte Stormwinds Garde, plejede vi at drikke øl i Skarlagenrød Ravns Kro i Mørkeshire. Krovært dér, Smedsen, var en ekspert i lokal folklore. Vis ham denne side og hør, hvad han har at sige om den."},
  [79] = {n="Sagnet om Stalvan", l="Tag den mudrede side til Kommandør Ebenlås.", d="Jeg fulgte legenden om den Stalvan-type i årevis. Da de besøgende adelsmænd blev slagtet for et par år siden, tog jeg med Marskal Udmattet for at undersøge det. Jeg fandt disse mudrede sider, men vi kunne aldrig koble håndskriften til den skøre mand i skoven. Din bevisførelse beviser hans skyld. Tag dette med til Kommandør Ebenlås med det samme, og fortæl hende om det, du har opdaget!"},
  [80] = {n="Sagnet om Stalvan", l="Vis Skriver Daltry den Blodplettede Dagbogsside.", d="Jeg har haft øje på den kryster, Stalvan, i ret lang tid. Men hvis denne side er skrevet af samme hånd, beviser den hans skyld ud over enhver tvivl.\n\nI alle sine dage som vogter af byregistret er Skriver Daltry blevet ekspert i at identificere håndskrifter. Vis ham denne side, og se om skriften matcher underskriften i registret."},
  [83] = {n="Røde Linned-varer", l="Bring 6 Røde Linned-halstørklæder til Sara Tømmerlund i Østdal Tømmerlejr.", d="Defias-banden i Nordshire bærer sækkelærredsmasker, men Defias-folkene i Elwynnskoven bærer linned, som jeg kan bruge til at lave fine linnedvarer.\n\nBring mig røde linned-halstørklæder, så bruger jeg dem til at sy noget til dig.\n\nDefias-medlemmerne har lejre gemt rundt omkring i hele Elwynnskoven."},
  [84] = {n="Tilbage til Billy", l="Bring Flæskesidepajen til Billy Mac-Lure ved Maclures Vingårde.", d="Værsgo. Og når du giver den her paj til den Billy, så fortæl ham, at jeg håber, han kvæler i den!"},
  [85] = {n="Tabt Halskæde", l="Tal med Billy Mac-Lure.", d="Jeg har tabt min halskæde, og jeg tror, at den gadedreng Billy Mac-Lure har taget den! Han plejer at småløbe rundt som en rotte omkring Maclures vingårde herfra mod øst.\n\nFå min halskæde tilbage til mig, så varmer du en gammel enkes hjerte."},
  [86] = {n="Paj til Billy", l="Bring 4 Stykker Vildsvinekød til Tante Bernice Stenmark ved Stenmarks Gård.", d="Måske hvis jeg fik en paj, kunne jeg fortælle dig, hvem der har den halskæde. Og du ved, jeg tror, den gamle Bernice-dame på den anden gård laver fantastiske Flæskesidepajer...\n\nMåske hvis du gav hende nogle stykker vildsvinekød fra vildsvinene, der render rundt om vores gårde, og fortalte hende, hvad det var til, ville hun bage en paj til dig."},
  [87] = {n="Guldtand", l="Bring Bernices Halskæde til \"Tante\" Bernice Stenmark ved Stenmarks Gård.", d="Jeg legede i nærheden af Fjerndyb-minen, og jeg tror, jeg tabte, øh... jeg mener, jeg så, den gamle damens halskæde. Spørg mig ikke, hvordan den kom derhen... det var ikke mig!\n\nNå, i hvert fald så jeg en stor, guldtandet kobold samle halskæden op og løbe ind i minen. Find den kobold, så finder du halskæden, det sværger jeg!"},
  [88] = {n="Prinsessen Må Dø!", l="Dræb Prinsessen, tag hendes halsbånd, og bring det tilbage til Ma Stenmark ved Stenmarks Gård.", d="Brackvold-familien har en præmiegris, Prinsesse. Sogen er ENORM, og hun er blevet sådan ved at snige sig herover og æde mine grøntsager!\n\nSå inden hun kommer til vores marker... må Prinsessen dø! Bring mig hendes halsbånd som bevis på gerningen, så giver jeg dig noget for din tid!\n\nPrinsessen er som regel nede ved Brackvolds Græskarplads, mod øst og længere ud, forbi Maclure-gården. Få fat i hende, før hun bliver sulten og kommer tilbage hertil!"},
  [89] = {n="Den Evigstille Bro", l="Bring 5 Jernspyd og 5 Jernnagler til Formand Oslow i Søshire.", d="Under den sidste orkinvasion var vi nødt til at smelte vores jern ned for at lave kugler, sværd og rustninger. Vi sendte bud til Stormwind om en ny forsyning af materialer, men en flok Rødryg-gnolde kaprede karavanen og løb væk ind i bakkerne bag Søshire.\n\nNu er vi ved at løbe tør for forsyninger til at få denne bro genopbygget. Hvis du kan bringe mig 5 jernspyd og 5 jernnagler, <Name>, så sørger jeg for, at du bliver belønnet.\n\nNu skal vi i gang!"},
  [90] = {n="Krydrede Ulve-kababer", l="Saml 10 Magre Ulvelænd og vend tilbage til Kok Grual i Mørkeshire.", d="Krydrede Ulve-kababer er et stamgæstsfavorit! Jo, jeg kan lave nogle til dig. Men først skal jeg bruge ingredienserne. Bring mig 10 Magre Ulvelænd. Med de mange ulve her i skoven tvivler jeg ikke på, at du finder lænderne uden problemer. Heldigvis for dig har jeg lige modtaget min seneste forsendelse af Stormvindske Krydderurter, så alt, jeg mangler, er lænderne for at komme i gang."},
  [91] = {n="Salomons Lov", l="Bring 10 Skyggeskjul-vedhæng til Fogeden Konacher i Søshire Rådhus.", d="En fjende af Stormwind har slået sig ned i de østlige bakker i Rødryg. Denne onde skurk bruger Arkanen til at sprede rædsel og elendighed over vores by og vores folk. Under navnet Morgant driver han sine ugerninger.\n\nMorgant styrer nu Skyggeskjul-gnoldklanen til at udføre sine ordrer. Som Søshires lov foreskriver, er det en dødsstraf at hjælpe en forbryder mod Kongeriget.\n\nDisse onde gnolde skal dræbes!\n\nAflevér 10 Skyggeskjul-vedhæng til mig, så bliver du belønnet."},
  [92] = {n="Rødryg-gullasch", l="Kok Brenna fra Søshire vil have fem stykker Sejt Kondorkød, fem Store Blodsnuser-snuder og fem portioner Sprødt Edderkoppekød.", d="Intet ville glæde mig mere end at lave Rødryg-gullasch til dig. Men der er et lille problem. Under det seneste orkoprør fodrede jeg hele brigaden af Stormwind-tropper. Mit skab er nu tomt. Men hvis du kan skaffe ingredienserne, vil jeg gerne hjælpe.\n\nBring mig bare fem stykker Sejt Kondorkød, fem Store Blodsnuser-snuder og fem portioner Sprødt Edderkoppekød."},
  [93] = {n="Skumrings-krabbekager", l="Saml 6 Klistrede Edderkoppeben og bring dem til Kok Grual i Mørkeshire.", d="Jeg lader dig i hemmelighed vide noget - Skumrings-\"krabbe\"-kager er faktisk lavet af edderkoppeben! Jeg ved godt, det er lidt ulækkert, men kagerne har en dejlig syrlig smag og er perfekte snacks! Bring mig klistrede edderkoppeben, så laver jeg et par stykker til dig.\n\nJeg hører, at Giftnet-edderkopper er en god kilde - de bygger rede mod nord, mellem bakkerne og floden."},
  [94] = {n="Et Vågent Øje", l="Tag Azoras Glyf til Løvestatuen nær Ilgalars Tårn i Rødryg.", d="Min rival, Morgant, er en ondskabsfuld magiker med stor magt, som bor i Ilgalars Tårn i Rødryg. Jeg har udviklet en metode til at spionere på ham, Azoras Øje, og kan nu se ham på lang afstand.\n\nMen for at studere hans tanker ... har jeg brug for yderligere hjælp.\n\nHvis du er villig, så tag min Azoras Glyf til Ilgalars Tårn. Placér den på Løvestatuen nær tårnet.\n\nNår dette er gjort, vil Azoras kraft give syner af Morgants fremtidige planer."},
  [95] = {n="Svens Hævn", l="Gå til Svens Gård og find, hvad der blev begravet bag den gamle stub.", d="Jeg plejede at arbejde på en af gårdene mod sydøst... indtil Mørke Ryttere fra Dødvinds-passet faldt over min gård og slagtede min familie, mens jeg var væk!\n\nDa jeg vendte tilbage, så jeg en skyggefigur luske rundt nær min lade, mens han begravede noget. Han flygtede, før jeg kunne fange ham, og jeg kunne ikke dvæle, for jeg var lige i hælene på Mørke Ryttere. Så jeg fandt aldrig ud af, hvad der var gemt.\n\nHvis du kan finde det, skyggefiguren begravede, ville jeg være taknemmelig. Gemmestedet er bag den gamle stub nær min lade."},
  [97] = {n="Sagnet om Stalvan", l="Meld nyheden til Kommandør Ebenlås.", d="Lad Kommandør Ebenlås vide med det samme, at håndskriften passede, <Name>! Hendes mistanke var korrekt!"},
  [98] = {n="Sagnet om Stalvan", l="Dræb Stalvan Tågekappe og vis Frue Eva hans familiering.", d="Stalvan Tågekappe førte et liv i fordærvelse. Uskyldige ofre døde for hans hånd. Uden tvivl er han skyldig i utallige forbrydelser. Nu truer galningen Mørkeshire. Lyset alene ved, hvilke beskidte gerninger han planlægger. Rejs til hans hytte lige nord for byen, <Class>, og henret Stalvan én gang for alle.\n\nNår gerningen er udført, skal du rejse til Frue Evas og vise hende hans familiering. Det var trods alt hendes forudsigelse, der førte til denne makabre opdagelse. Men Mørkeshire er tryggere takket være hende."},
  [99] = {n="Arugels Dårskab", l="Bring 6 Brandtræ-lænker til Dalar Morgenvæver i Gravkammeret.", d="Efterhånden som min forståelse af Arugels magi vokser, vokser også min foragt for den uheldige nar. Jeg er tæt på at afslutte min forskning i hans såkaldte kur.\n\nMin viden bliver fuldkommen, når jeg finder ud af, hvilken fortryllelse der forårsager de mærkelige adfærd i Brandtræ-landsbyen. Om dagen ser bønderne ud til at være mennesker. Men når solen går ned, forvandles byboerne til Månevrede Varulve.\n\nJeg må trække energi fra de fortryllede lænker, Arugel lagde på dem. Bring mig seks fortryllede Brandtræ-lænker, <Name>."},
  [101] = {n="Pinetotemet", l="Bring 10 Gul-hugtænder, 10 Skeletfingre og 5 Hætteglas med Edderkoppegift til Frue Eva i Mørkeshire.", d="Når den mystiske besmittelse sniger sig gennem skoven, er behovet for selvbeskyttelse ubestrideligt, <Name>. Vindene hvisker til mig, og de taler om en stor fare, som tålmodigt venter på dig i den nærmeste fremtid.\n\nHvis du ønsker at beskytte dig selv, ædle <Class>, så bring mig 10 gul-hugtænder, 10 skeletfingre og 5 hætteglas med edderkoppegift. For dig vil jeg fortrylle et Pinetotem, der skader dem, som forsøger at udøve vold mod dig."},
  [102] = {n="Patruljering i Vestfald", l="Bring 8 Gnold-poter til Kaptajn Danuvin på Vagtbakken.", d="Stormvind har svigtet os. En led vind af fordærvelse suser hen over Vestfalds sletter. Dette var mit hjemland, og jeg vil ikke vende ryggen til de borgere, der vælger at blive her. Vi, de tidligere bønder, skal gøre modstand.\n\nDin opgave, hvis du vælger at tage den på dig, er at patruljere Vestfalds græsarealer. Spor de modbydelige gnolde op og slå dem ihjel, de der ser ud til at samarbejde med Dødsminernes tyve. Bring mig otte Gnold-poter, så belønner jeg din tapperhed."},
  [103] = {n="Flammens Vogter", l="Bring 5 Flasker med Olie til Kaptajn Gråsen ved Vestfald-fyret.", d="Natten, hvor fyrvogterens familie døde, var forfærdelig. Jeg så hjælpeløst til, mens Gamle Mørkøje ledte angrebet. Men det, der er gjort, er gjort, og nu gælder min bekymring livet for søfolkene på Det Store Hav, hvis skibe kommer tæt på de farlige klipper ud for kysten. Da ingen holder vagt over flammen længere, er ansvaret faldet på mig.\n\nHjælp mig med at holde fakkelen tændt ved at bringe mig 5 flasker olie fra Høstuhyrerne."},
  [104] = {n="Kystens Trussel", l="Bring en skæl fra Gamle Mørkøje til Kaptajn Gråsen ved Vestfald-fyret.", d="Da mit liv endte på klipperne, anede jeg intet om, hvad livet efter døden havde i vente for mig. Fyret var sort den nat, fordi Gamle Mørkøje havde skræmt fyrvogterens familie væk. De vendte tilbage og tændte flammen igen, men Gamle Mørkøje tvang de svagsindede mudderfisk til at plyndre fyret med ham igen. Anden gang var familien ikke så heldig, og for mine øjne døde de hjælpeløst.\n\nDræb Gamle Mørkøje, hvis du ser ham langs kysten, og bring mig en af hans skæl, så belønner jeg dig."},
  [106] = {n="Unge Elskere", l="Giv Majbelles kærlighedsbrev til Tommy Joe Stenmark.", d="Åh, jeg er forbandet! Mit hjerte tilhører Tommy Joe Stenmark, men vores familier er bitre fjender. Så jeg kan ikke se ham, selvom mine øjne længes efter at skue det smukke ansigt!\n\nVær venlig at tage dette brev og give det til Tommy Joe. Han er som regel ved floden vest for Stenmarks Gård, som ligger lige mod vest herfra."},
  [107] = {n="Seddel til William", l="Tag Bedstemor Stenmarks seddel til William Støder.", d="Jeg vil vædde på, at William Støder har en eliksir, der kan forene vores to unge elskere!\n\nSå tag den her seddel med til William. Han bor på Løvens Stolthed Kro i Guldshire."},
  [109] = {n="Rapport til Gryan Tykfrakke", l="Tal med Gryan Tykfrakke. Han er som regel at finde i stentårnet på Vagtbakken, lige ved vejen midt i Vestfald.", d="Det ser ud til, at du har set en del kamp i din tid, <Class>. Hvis du ikke allerede har gjort det, bør du melde dig til Gryan Tykfrakke. Han leder Folkemilitsen, som har til formål at beskytte Vestfalds landbrugsarealer. Jeg vil vædde på, at han kunne bruge din hjælp. Du finder ham som regel i stentårnet på Vagtbakken, lige ved vejen midt i Vestfald."},
  [111] = {n="Tal med Bedstemor", l="Tal med Bedstemor Stenmark.", d="Vær venlig, <Name>, tal med min bedstemor. Hvis nogen kan finde en måde at bringe mig og Majbelle sammen på, så er det hende.\n\nHun er inde i vores hus øst herfra."},
  [112] = {n="Indsamling af Tang", l="Bring 4 krystaltang-blade til William Støder i Guldshire.", d="Jeg kan lave en usynlighedssprit til Majbelle, så hun kan snige sig væk fra Maclures Vingårde og gå hen til Tommy Joe. Men for at lave spriten har jeg brug for noget krystaltang.\n\nSkønt tangen normalt vokser i havet... samler mudderfisk den nogle gange. Se om mudderfiskene nær Krystalsøen har nogen. Krystalsøen ligger lige øst for Guldshire."},
  [114] = {n="Flugten", l="Tag usynlighedsspritten til Majbelle Maclure.", d="Tag denne usynlighedssprit til unge Majbelle. Den burde vare længe nok til, at hun kan besøge Tommy Joe."},
  [115] = {n="Skyggemagi", l="Bring 3 midnatskugler til Marskal Marris i Søshire.", d="Sortklippe-orkerne hvervede skyggekastere til at støtte deres angreb i Rødryg, og de har medbragt apparater med mørk kraft--midnatskugler. Disse kugler har ramt Rødrygs forsvarere hårdt, og det er afgørende, at vi fjerner de dæmonbesmittede genstande fra konflikten.\n\nFind og lever mig midnatskugler fra faldne Sortklippe-skyggekastere. Jeg lader dem så destruere, for verden ville være et bedre sted uden dem!"},
  [116] = {n="Tørre Tider", l="Kroholder Daniels i Søshire har brug for en tønde Tordenbryg-lager, en anker Merlot, en flaske Månebrændevin og en skind-sæk Sød Rom.", d="Jeg befinder mig i en ret trang situation her, <Name>. Flaskerne er tæt på at løbe tør. Den seneste forsendelse af sprit er længe forsinket. Orkeinvasionen har været et helvede.\n\nMåske kan du gå mig til hånde?\n\nJeg har brug for, at du henter en tønde Tordenbryg-lager fra Grimsøl Tordenbryg i Vestfalds bakker, en anker Merlot fra Stormvind, en flaske Månebrændevin fra Mørkeshire og en skind-sæk Sød Rom fra Guldshire. Bring dem tilbage til mig, så sørger jeg for, at du bliver belønnet."},
  [117] = {n="Tordenbryg", l="Bring Grimsøl Tordenbryg 5 humle, så han kan færdiggøre sin specialbryg.", d="Skynd dig, min ven, gør det i en fart\nså vores rige lager får en smag, der er skarp,\nmere øl og mindre gryde-grød,\nhumle skal der til for at brygge det mod."},
  [118] = {n="Hestesko-prisen", l="Tag Verners seddel til Smed Argus i Guldshire.", d="Jeg har brugt så meget jern på at udstyre Stormvindske Vagter, at jeg ikke har nok til at forsyne staldens heste med hestesko!\n\nTag denne seddel til Smed Argus i Guldshire. Den forklarer ham mit problem og anmoder om en forsendelse af hestesko."},
  [119] = {n="Tilbage til Verner", l="Vend tilbage til Verner Osgod i Rødryg. Giv ham Kassen med Hestesko.", d="Ok, jeg giver ham hans 50 hestesko...\n\nVær så venlig, de er alle pakket ind og klar til afsendelse! Sig til Verner, at det var en fornøjelse at handle med ham, og sørg for, at han læser sedlen, der er fastgjort til kassen!"},
  [120] = {n="Budbringer til Stormvind", l="Dommer Salomon har givet dig en rapport, som skal leveres til General Marcus Jonatan i Stormvind. Dommeren ønsker, at du vender tilbage til ham, så snart leveringen er foretaget.", d="Det er prøvende tider, <Class>. Byen er under konstant belejring. Uden forstærkninger vil vi helt sikkert lide nederlag. Budskabet, jeg nu betror dig, er af højeste vigtighed. Få denne rapport til General Marcus Jonatan i Stormvind med det samme. Når leveringen er gjort, skal du vende tilbage til mig øjeblikkeligt med nyheder, både gode og dårlige.\n\nNu skynd dig!"},
  [121] = {n="Budbringer til Stormvind", l="Tag General Marcus Jonatans svarbrev til Dommer Salomon i Søshire.", d="Mens jeg venter på et svar fra Kongen, vil jeg have dig til at bringe dette brev til Dommer Salomon.\n\nAfsted, <Class>!"},
  [122] = {n="Bugskæl", l="Saml 6 bugskæl fra Sortdrageunger, og bring dem til Verner Osgod i Rødryg.", d="Jeg har brug for bugskæl fra sortdrageunger for at betale for de hestesko, Argus sendte mig fra Guldshire. Hvis du kan skaffe 6 af dem til mig, kan jeg betale Argus med nogle af dem... og have nok tilbage til at smede noget til dig.\n\nSortdrageunger flyver tit rundt syd for Søshire, men de elsker at vandre om. Du bliver måske nødt til at holde øje og jage dem, når du ser dem."},
  [124] = {n="Et Gnold-hylen", l="Dræb 10 Rødryg-brutaler og 8 Rødryg-mystikere, og vend derefter tilbage til Verner Osgod.", d="Som om de angribende orker ikke var nok! Nu strejfer gnold-brutaler og -mystikere langs højderyggen nord for min stald og tager mine heste, når de farer vild...\n\nHvis du kan slippe af med de gnolde, vil mine heste og jeg være meget taknemmelige."},
  [125] = {n="De Tabte Værktøjer", l="Formand Oslow fra Søshire vil have dig til at hente hans værktøjskasse fra bunden af Evigstille-søen.", d="Jeg kunne virkelig bruge en hånd her, <Name>. Med byen under belejring har det været svært at skaffe forsyninger. Mit værktøj skulle leveres fra Guldshire med vogn, men broen blev sprængt. Vi lagde værktøjet i en båd, men orkerne ramte den med en katapult. Typisk mig, min værktøjskasse sank lige til bunds i søen.\n\nHent min værktøjskasse, <Name>, så skal jeg nok gøre det umagen værd."},
  [126] = {n="Hyl i Bakkerne", l="Bring Hylerens pote til Verner Osgod i Søshire.", d="<Name>, gnoldene er stadig derude. Jeg kan høre deres hylen, mens de jager i bakkerne over Søshire. Og ét skrig er højere end alle de andre - Hyleren, deres leder.\n\nDræb Hyleren og få hans flok til at spredes! Bring mig hans pote som bevis.\n\nVær forsigtig, denne gnold er deres leder af en grund. Han er ingen Køter..."},
  [127] = {n="Sælger Fisk", l="Bring 10 plettede solfisk til Havnefoged Baren i Søshire.", d="Evigstille-søen er berømt for sine plettede solfisk. Der er altid efterspørgsel efter dem... og jeg er ved at løbe tør!\n\nBring mig en portion på 10, så handler jeg godt for dem. Hvis du ikke selv kan fiske, så... måske kan du skaffe dem fra mudderfiskene!"},
  [128] = {n="Sortklippe-dusøren", l="Dræb 15 Sortklippe-kæmper, og Vagt Hove i Søshire vil belønne dig.", d="Sortklippe-klanen skal udslettes. Fjenden har invaderet vores lande. Disse bjerge hører under Stormvinds konges suveræne ret. Vores kilder fortæller os, at klanens enheds-ledere kaldes Kæmper. I finder dem i deres lejr mod nord, lige vest for vejen til Brændende Stepper.\n\nDommer Salomon vil have disse rådne rødder døde. Slå 15 Sortklippe-kæmper ihjel og vend tilbage til mig."},
  [129] = {n="Gratis Frokost", l="Bring Parkérs frokost til Vagt Parkér. Han patruljerer vejen, der fører til Mørkeshire.", d="Kan du gøre mig en tjeneste? Jeg har tilberedt en frokost til Vagt Parkér, men han er ude på patrulje...han er en stor, stærk Stormvinds-vagt, der kan forsvare sig selv, men det er alt for farligt derude for en almindelig borger som mig.\n\nSå hvis du leverer hans frokost for mig, og så kommer tilbage hertil, giver jeg dig en gratis frokost! Parkér patruljerer stykket af vejen, der fører til Skumringsskoven."},
  [130] = {n="Besøg Urtekyndigen", l="Tal med Rødryg-urtekyndige Martie Rosenlund.", d="Før du går tilbage til Darsy, kan du så tage nogle blomster med til hende for mig? Du kan få dem i urtebutikken tilbage i Søshire, i den vestlige ende af byen.\n\nMen når du har fået blomsterne...så fortæl ikke urtekyndige Martie, hvem de er fra, eller hvem de er til..."},
  [131] = {n="Levering af Påskeliljer", l="Giv Darsy Påskelilje-buketten.", d="Her er din buket. Jeg valgte Påskeliljer til dig. De er mine yndlingsblomster!"},
  [132] = {n="Defias-broderskabet", l="Tag Snedigs Brev til Gryan Tykfrakke i Vestfald.", d="Det jeg er ved at fortælle dig, kunne koste mig livet. Defias-banden har gang i noget stort. Sidst jeg hørte, arbejdede de sammen med diverse gnolde, kobolder og endda goblins.\n\nTag dette brev til Tykfrakke. Det forklarer alt, hvad jeg ved om emnet."},
  [133] = {n="Gulsk Skræmmefigur", l="Saml 7 Gul-ribben og bring dem til Abercrumbie i hans hytte.", d="Jeg bor så langt fra byens beskyttelse, at det er et under, at gulerne og de vandrende døde ikke har spist mig! Faktisk bankede en flok Knoglenagere i går på husets mure!\n\nJeg vil lave en figur - en slags \"skræmmefugl\" for gulerne. For at gøre det har jeg brug for nogle Gul-ribben. Du kan få dem fra Kødædere, Knoglenagere, Hjernespisere, Rådne og Pestspredere.\n\nSkaf ribbenene til mig, så betaler jeg dig med nogle mønter."},
  [134] = {n="Oger-tyve", l="Returner Abercrumbies kasse til Abercrumbie.", d="For et par uger siden plukkede jeg urter langt fra mit hus, da en bande oger angreb mig! Jeg løb min vej og måtte efterlade en kasse med kostbare værktøjer og urter.\n\nEfter at de havde jaget mig væk, traskede ogerne tilbage til Ogrehøjen i det sydlige Skumringsskov. Jeg er sikker på, at min kasse er et sted i nærheden af højen.\n\nVær sød, <Name>, hent denne kasse til mig, for jeg savner den rigtig meget."},
  [135] = {n="Defias-broderskabet", l="Tag Snedigs Brev til Mathias Skaw i Stormvind.", d="Jeg undrer mig over, hvad Snedig mente, da han nævnte Stenhuggerne. Måske var det bare en fejl i ordene. Kunne Defias-banden være i familie med Stenhuggerne? Kun én mand ved det med sikkerhed: Mathias Skaw, chef for SI:Syv. Vis ham Snedigs Brev og se, om han har noget at tilføje til dette voksende mysterium. Hvis du har svært ved at finde Skaw, så kig i Kasernen i Gamlebyen."},
  [136] = {n="Kaptajn Sandersens Skjulte Skat", l="Find Kaptajn Sandersens skibskiste og lede i den efter det næste spor.", d="Hvis I læser dette, betyder det, at Ol' Kaptajn Sandersen ligger i en vådt grav. Så min skat er nu jeres, I skal bare følge sporene.\n\nFørst skal I finde min skibskiste. Den er nok halvt begravet i sand nu, langs Vestfalds vestkyst ved vraget. Der er mange vrag, men kun ét rusten anker på kysten. Find det anker, og I finder min kiste! Kig derinde efter det næste spor."},
  [138] = {n="Kaptajn Sandersens Skjulte Skat", l="Find den gamle tønde nær den faldne skorsten, og lede i den efter dit næste spor.", d="Sporet til skatten lyder: Godt arbejde, makker! Nu skal I gå lige mod øst. Øst op ad klipperne, øst til vejen. Led efter de gamle skorstensruiner ved siden af vejen. Der finder I en gammel tønde med jeres næste spor."},
  [139] = {n="Kaptajn Sandersens Skjulte Skat", l="Undersøg den tomme krukke ved siden af vindmøllen for det næste spor.", d="Da I lede i tønden, fandt I endnu et stykke pergament. Dette lyder: Vend nu jer mod nord fra denne tønde. Lige som en krage flyver, går I, indtil I ser den tomme krukke ved den ensomme vindmølle på havklipperne. Hvis I roder rundt i den krukke, finder I måske det, I leder efter."},
  [140] = {n="Kaptajn Sandersens Skjulte Skat", l="Find Kaptajn Sandersens kiste og åbn den for at få din belønning.", d="Og sandelig, dybt inde i den Gamle Krukke ligger endnu et spor til Sandersens skat. Blækket er løbet flere steder, og papiret lugter af whisky, men I kan tyde noget af teksten: Nu hvor I fandt min gamle whiskykrukke, er I næsten frem til skatten! Vend jer mod vest fra flasken og gå ned til kysten. Når I når vandet, fortsæt! Svøm lige mod vest, indtil I finder øen med min skattekiste!"},
  [141] = {n="Defias-broderskabet", l="Tag Shaws rapport til Gryan Tykfrakke i Vestfald.", d="Stenhuggerklanen blev ledet af en mand ved navn Edwin VanKløft. VanKløft stod for genopbygningen af Stormvind, efter at orkerne havde jævnet byen med jorden i Første Krig. Angiveligt var VanKløft og hans mænd utilfredse med deres behandling af kongen, efter genopbygningen var fuldført. Det kan måske forklare et par ting.\n\nJeg har skrevet en mere detaljeret beretning til jeres Mester i Vestfald. Tag den med til ham med det samme!"},
  [142] = {n="Defias-broderskabet", l="Find Defias-budbringeren i Vestfald og bring hans budskab til Tykfrakke.", d="Vi må finde ud af, hvor Defias-skjulestedet ligger. <Name>, min spejder melder, at en Defias-budbringer er set på vejene mellem Månebæk, Guldkystens Stenbrud og Jangolade-minen. Jeg vil have dig til at fange ham. Hvis han gør modstand, så dræb ham og bring mig det, han har på sig."},
  [143] = {n="Budbringer til Vestfald", l="Dommer Salomon vil have dig til at tage hans skriftlige bøn til Gryan Tykfrakke i Vestfald.", d="Noget underligt foregår i Stormvinds Hær. De skulle have været her i styrke nu. Men tid er et luksus, vi ikke har. Jeg vil ikke stå og se folket i Søshire give deres liv uden at forsøge at skaffe mere hjælp. Jeg har hørt rygter om en folkemilits, der er ved at dannes i Vestfald.\n\nTag denne bøn med til deres leder, Gryan Tykfrakke. Måske kan Tykfrakkes mænd yde støtte her, indtil kongen sender forstærkninger."},
  [144] = {n="Budbringer til Vestfald", l="Vend tilbage til Dommer Salomon med Gryan Tykfrakkes svar.", d="Dommer Salomons brev smerter mig at læse. Men det er tydeligt, at han ikke kender krigen, der føres i Vestfald, ellers ville han vide bedre end at forvente hjælp fra Militsen. Hvis Stormvind ikke også havde svigtet os, ville vi ikke have brug for Militsen.\n\nTag dette svar med til din mester i Rødryg, <Class>. Og fortæl ham, at mit hjerte er tungt over tabet af gode mænd."},
  [145] = {n="Budbringer til Mørkeshire", l="Dommer Salomon vil have dig til at tage et brev til Lord Ebenlås i Mørkeshire.", d="Jeg har brug for din hjælp igen. Jeg har skrevet til Lord Ebenlås og bedt ham sende sine uddannede vagter, Nattevagten, for at hjælpe med at forsvare Søshire. Det er afgørende, at dette budskab når frem hurtigt. Du må udvise ekstrem forsigtighed. Ebenlås er borgmester i Mørkeshire, midt i Skumringsskoven. Forlad ikke vejene."},
  [146] = {n="Budbringer til Mørkeshire", l="Vend tilbage til Dommer Salomon med Lord Ebenlås' svarbrev.", d="Hvis jeg ikke kendte Dommer Salomon personligt, ville jeg sige, at manden er blevet gal. Sende Nattevagten til Søshire, fordi Stormvind nægter at hjælpe? Nattevagten blev dannet, fordi Stormvind forlod os, da denne onde magi sivede ind i landet. Hvis jeg sendte min Nattevagt, ville byen være overrendt af ondskab, før vagterne overhovedet nåede skovkanten.\n\nTag dette svarbrev til din mester i Søshire."},
  [147] = {n="Menneskejagt", l="Find og dræb \"Samleren\", og vend derefter tilbage til Marskal Dughan med Samlerens Ring.", d="Hvis \"Samleren\" tager guld fra vores miner, så stjæler han fra riget! Bring Samleren for retten, og bring mig ringen, der nævnes i afhentningsplanen, du gav mig. Den kan fortælle os, hvem Samleren arbejder for...\n\nAfhentningsplanen siger, at Samleren gemmer sig på Brackvolds Græskarplads. Det er der, du skal lede efter ham."},
  [148] = {n="Forsyninger fra Mørkeshire", l="Tal med Frue Eva.", d="Åh, hvad skal en stakkels gammel mand gøre? Jeg har brug for nogle forsyninger fra Mørkeshire, men landsbyen ligger så langt væk, og jeg er så gammel og skrøbelig...jeg ville aldrig klare turen.\n\nKan du tage til Mørkeshire og bringe mig noget Spøgelseshår-tråd tilbage? Du kan få det af Frue Eva i hendes hjem på Mørkeshires torv."},
  [149] = {n="Spøgelseshår-tråd", l="Bring Spektralkammen til Blinde Mary.", d="Der findes en fattig, trist ånd, Blinde Mary, som hjemsøger et gammelt landhus i bakkerne syd for Mørkeshire.\n\nSå tag denne Spektralkam, og bed Blinde Mary om at kamme sit hår. Bring derefter kammen tilbage, så vil jeg udvinde det Spøgelseshår, jeg skal bruge til tråden.\n\nVær forsigtig, for mørke ting lurer nu nær huset..."},
  [150] = {n="Mudderfisk-krybskytter", l="Bring 8 Mudderfinner til Havnefoged Baren i Søshire.", d="Mudderfisk er ved at blive et problem. Større flokke af fiskemændene kaster anker langs bredden af Evigstille-søen og fisker op en storm! Vi må have dem væk, før de spiser alle fiskene i søen!\n\nJagt mudderfisk! Bring mig otte af deres finner, så har jeg måske noget til dig..."},
  [151] = {n="Stakkels Gamle Blegmule", l="Verna Rynkebryn i Vestfald vil have, at du bringer hende 8 håndfulde havre.", d="Stakkels gamle Blegmule! Sådan et træt dyr efter alt det arbejde, vi har tvunget hende igennem. Jeg fodrede hende, før vi forlod gården, men vi havde ikke regnet med, at vognen ville gå i stykker under os. Hvis du kunne bringe hende et par håndfulde havre fra markerne, ville jeg være taknemmelig.\n\nJeg vil vædde på, at du kan finde noget rundt omkring på alle gårdene i Vestfald, hvis du kan holde dig væk fra de forfærdelige maskiner, der har overtaget. Der er flere gårde sydvest herfra."},
  [152] = {n="Kysten Er Ikke Fri", l="Dræb 7 Tidevandsjægere, 7 Krigere, 7 Orakler og 7 Kystløbere, og vend tilbage til Kaptajn Gråsen ved Vestfald-fyret.", d="I har nok bemærket alle vragene langs kysten. Det Store Hav er sandelig farligt. Vestfalds kyst skal holdes fri, så søfolk, der finder vej til vores strande, er i sikkerhed. Mudderfiskene er dog et problem.\n\nDræb 7 Tidevandsjægere, 7 Krigere, 7 Orakler og 7 Kystløbere, så sørger jeg for, at I bliver belønnet."},
  [153] = {n="Røde Læderbandanaer", l="Bring 15 Røde Læder-halstørklæder til Spejder Galian på Vagtbakken.", d="Defias-fronten flytter sig hele tiden. Jeg har fulgt deres bevægelser i ganske lang tid nu. Som en sidebemærkning har jeg konstateret, at mange af bandens medlemmer kan spores på de røde læder-halstørklæder, de bærer.\n\nBring mig 15 af disse halstørklæder, så sørger jeg for, at I bliver belønnet."},
  [154] = {n="Returner Kammen", l="Returner Spøgelseshår-kammen til Frue Eva i Mørkeshire.", d="NEJ!!!!!\n\nTag den, tag den kam væk fra mig!\n\nJeg er et monster, og ingen vil nogensinde synes om mig igen!"},
  [155] = {n="Defias-broderskabet", l="Eskortér Defias-forræderen til Defias-broderskabets hemmelige skjulested. Når Defias-forræderen har vist dig, hvor VanKløft og hans mænd gemmer sig, skal du vende tilbage til Gryan Tykfrakke med informationerne.", d="Så Tykfrakke sender en skrøbelig <Race> som dig for at beskytte mig? Må jeg så tage imod. Tag gerne nogle venner med.\n\nDu kender reglerne, ikke? Du passer min ryg, og jeg fører dig til Defias-skjulestedet. Men du må holde dig tæt ved min side. Defias-banden vil have mit hoved nu. Hvis de ser mig med dig, vil de prøve at slå mig ihjel.\n\nSig til, når du og de venner, du kan samle, er klar til at tage afsted."},
  [156] = {n="Saml Rådblomster", l="Saml 8 Rådblomster og bring dem til Krovært Smedsen i Mørkeshire.", d="Hvis du bringer mig nogle rådblomster, kan jeg brygge dig et parti zombiesaft.\n\nRådblomster vokser de mærkeligste steder. Især skulle man kunne finde dem inde i kranierne på Skeletgysere og Skeletdæmoner... ikke at jeg er kommet tæt nok på for at kigge!\n\nRavnehøj-kirkegården og Stille Haver vrimler begge med de skeletter. Du kan lige så godt slippe af med dem, mens du leder efter rådblomster. Byen Mørkeshire ville være taknemmelig."},
  [157] = {n="Lever Tråden", l="Bring Spøgelseshår-tråden til Abercrumbie, i hans hytte nord for Ravnehøj-kirkegården.", d="Her er din tråd, <Name>. Den har tusind anvendelser, lige fra at binde onde ånder til at sy liv ind i livløse genstande."},
  [158] = {n="Zombiesaft", l="Tal med Krovært Smedsen.", d="Jeg mangler en flaske af en bestemt spiritus - Zombiesaft. Krovært Smedsen i Skarlagenrød Ravns Kro i Mørkeshire burde have noget.\n\nOg skynd dig venligst, <Name>. Nætterne bliver kolde, og jeg har brug for den drik for igen at få ild i årerne!"},
  [159] = {n="Saftlevering", l="Bring Zombiesaften til Abercrumbie i hans hytte.", d="Her er din zombiesaft...\n\n...og vær forsigtig med den ting. Den er stærk nok til at vække de døde!"},
  [160] = {n="Seddel til Borgmesteren", l="Bring Abercrumbies brev til Ello Ebenlås, Borgmester i Mørkeshire.", d="Tag denne seddel med til Ello Ebenlås, Borgmesteren i Mørkeshire.\n\nHan og jeg er gamle venner... og når han læser den og opdager, hvad du gjorde for mig... er jeg sikker på, at han bliver lige så glad som jeg er! Hahahaha!"},
  [161] = {n="En Mørk Trussel Truer", l="Overingeniør Hinderweir vil have dig til at bringe det underligt lugtende pulver til Ashlan Stenskær, sprængstofekspert i Dun Mødr.", d="Hvis mine mistanker holder, er dette en slags sprængstofpulver. Det skal analyseres af en sprængstofekspert, så vi ved, hvad vi har med at gøre. Ashlan Stenskær blev tildelt regimentet, der vogter Dun Mødr og Thandol-spændet. Jeg har brug for, at du tager på en alvorlig og farefuld rejse, <Name>.\n\nRejs gennem Algaz-porten, følg vejen gennem Vådlandene og find Stenskær i Dun Mødr. Hør mit råd: hold dig til vejene og stop for ingenting!"},
  [163] = {n="Ravnehøj", l="Find ud af, hvad der hjemsøger Ravnehøj.", d="Der er noget galt på Ravnehøj, <Name>. Kalor sværger, at nogen--eller noget--hjemsøger bygningerne dernede. To nætter i træk har han set skyggerne bevæge sig, og natten før det så han lys i et af vinduerne.\n\nHvis du, som du siger, bekymrer dig om Skumringsskovens sikkerhed, så find ud af, hvilket monster der hjemsøger Ravnehøj."},
  [164] = {n="Leverancer til Sven", l="Lever forsyningerne til Sven.", d="Kender du Sven? Ja, der er en mand, der gør Lysets værk! Han og hans følgere holder en lejr i Skumringsskovens nordvestlige udkant.\n\nDesværre er de så få, at de ikke engang kan undvære en mand til at hente forsyninger fra byen. Vil du levere disse forsyninger til ham?"},
  [165] = {n="Eremitten", l="Tjek til den gamle mand i hytten nær Ravnehøj-kirkegården.", d="Der var en gammel mand, der plejede at komme ind til byen og købe forsyninger ganske ofte, men jeg har ikke set ham i et godt stykke tid nu. Han bor ude i en hytte med udsigt over Ravnehøj-kirkegården, hvis jeg husker rigtigt. Måske du skulle tage derud og se, om noget er galt."},
  [166] = {n="Defias-broderskabet", l="Dræb Edwin VanKløft og bring hans hoved til Gryan Tykfrakke.", d="Der er kun én opgave tilbage, du skal fuldføre. Edwin VanKløft skal myrdes. Selvom det sårer mig at dømme nogen til døden, er det til det fælles bedste for Vestfalds folk, at VanKløft bliver lagt i graven en gang for alle. Bring mig skurkens hoved, når gerningen er udført."},
  [167] = {n="Åh, Bror...", l="Bring Formand Tistelnets Opdagelsesrejsende-Liga-mærke til Wilder Tistelnet i Stormwind.", d="Vi var dybt nede i en enorm mine i Vestfald, gemt under en lade i Månebæk. Ingen anelse, hvor de forbandede tyvepak kom fra. Under alt det her styrtede minetunnelen sammen over os. Jeg slap ud, men de andre... ja... de andre er ikke blevet hørt fra.\n\nDu ser ud til at have bedre held derinde. Hvis du kunne lede efter min bror, ville jeg være taknemmelig. Han bar altid sit Opdagelsesrejsende-Liga-mærke. Hvis du ikke kan finde ham, ville mærket i det mindste give mig lidt ro i sindet."},
  [168] = {n="Indsamling af Minder", l="Hent 4 Minearbejderforenings-kort og bring dem tilbage til Wilder Tistelnet i Stormwind.", d="Mange af mine venner omkom den forfærdelige dag, da minetunnelen styrtede sammen. Hvis dine eventyr skulle føre dig ind i den fløj af minen i Månebæk, så hold øje efter ethvert tegn, der kan identificere dem. Hvis du støder på nogle af deres Minearbejderforenings-kort, så bring dem til mig, og jeg sørger for, at deres familier får en vis oprejsning efter denne forfærdelige ulykke."},
  [169] = {n="EFTERLYST: Gath'Ilsnavs", l="Dræb Gath'Ilsnavs og bring hans hoved til Dommer Salomon i Søshire for belønningen.", d="Efterlyst! Gath'Ilsnavs, leder af Sortklippe-angrebene på Stenvagtsfæstningen og plyndringstogterne mod købstaden Søshire.\n\nGath'Ilsnavs er ekstremt farlig. Han skulle gemme sig i den nyligt erobrede fæstning og planlægge Sortklippe-klanens yderligere forbrydelser mod menneskeheden. Orkeplagen skal standses for enhver pris. En generøs belønning vil blive givet til den modige sjæl, der kan bringe Gath'Ilsnavs' hoved til Dommer Salomon."},
  [170] = {n="En Ny Trussel", l="Balir Frostham vil have dig til at dræbe 6 Klippekæbe-troggs og 6 Muskuløse Klippekæbe-troggs.", d="Jeg håber, du er her for at give os en hånd, <Class>. Efter det sidste trogg-angreb kan vi bruge al den hjælp, vi kan få.\n\nJeg hører, at kujonerne har dukket op over hele landet, og det ser ud til, at Kuldekam-dalen ikke er nogen undtagelse. De er blevet set overalt i bakkerne mod sydøst og nær den frosne sø.\n\nOg det er ikke alt, for for blot et par nætter siden angreb de vores lejr mod vest og overmandede den!\n\nVi er lidt underbemandede her, karl / pige, og vi har brug for stærke arme til at hjælpe med at drive troggene tilbage."},
  [173] = {n="Varulve i Skoven", l="Dræb 6 Nattebane Skyggevæver-varulve for Kalor i Mørkeshire.", d="Mørket synes uundgåeligt at blive tiltrukket af Skumringsskoven. Mester Carevins søgen er at udrydde ondskab og kætteri. Takket være vores indsats er Mørkeshires folk i sikkerhed.\n\nTror du, du er værdig til at slutte dig til os?\n\nJeg tænkte engang som dig. Desillusioneret over Vagtens selvtilfredshed sluttede jeg mig til Mester Carevin. Hvis du vil bevise dig selv, sker det ikke med ord.\n\nTest dine evner mod Nattebane Skyggevæver-varulvene i Lysskov-lunden--lys, ha!--og i den Rådnende Frugthave."},
  [174] = {n="Se mod Stjernerne", l="Viktori Prismantras fra Mørkeshire vil have dig til at bringe ham et bronzerør.", d="Min gnomiske ven Tandhjul har lovet at hjælpe mig med at bygge en indretning, der lader mig kigge mod stjernerne. Der findes en sandhed ud over magien, som kan forklare den mærkelige forvandling i skoven.\n\nBring mig et bronzerør lavet af en dygtig ingeniør. Det er første skridt, ifølge Tandhjuls tegninger."},
  [175] = {n="Se mod Stjernerne", l="Find Mary og overtal hende til at give en reflekterende overflade til Viktoris projekt.", d="Ifølge Tandhjuls tegninger er det, jeg har brug for nu, en måde at reflektere lys på. Jeg husker en kvinde ved navn Mary, som blev kendt i disse egne for altid at have et spejl med sig. Måske kan du finde Mary og se, om hun vil låne os en reflekterende overflade til projektet? Jeg tror, hun engang boede i det sydlige Skumringsskoven. . ."},
  [176] = {n="EFTERLYST: \"Hugger\"", l="Dræb gnollen Hugger og bring hans Kæmpe Gnoldklo til Marskal Dughan.", d="Efterlyst: Hugger\n\nEn kæmpe gnoll, Hugger, strejfer rundt i skovene i det sydvestlige Elwynn. Han har overmandet alle forsøg på at fange ham.\n\nStormvindske Hær har sat en generøs dusør på gnollen. For at opnå belønningen skal dusørjægere bringe bevis for Huggers død til Marskal Dughan i Guldshire."},
  [177] = {n="Se mod Stjernerne", l="Hent Blinde Marys Spejl fra den Sindssyge Gul og giv det til Viktori i Mørkeshire.", d="Spejlet var en af mine dyrebareste ejendele, indtil... hændelsen. Efter det skete smed jeg det bag ved laden. Der plejede en Sindssyg Gul at strejfe rundt derude. Måske har han samlet det op. Ryget har det, at det djævelske udyr holder til på Stille Haver-kirkegården."},
  [178] = {n="Teokritos' Hentning", l="Bring det falmede Skyggeskjul-vedhæng til Teokritos Magikeren.", d="<Du hører en stemme uden legeme...>\n\nVær ikke alarmeret. Jeg er Teokritos, Højmagiker ved Azoras Tårn i Elwynnskoven. Vedhænget, du holder i hånden, er et kommunikationsmiddel mellem Skyggeskjul-gnollerne og deres herre, Morgant.\n\nEfter måneders forskning tror jeg, at også jeg kan kommunikere gennem disse vedhæng. Hvis du kan høre denne besked, så var min besværgelse en succes.\n\nBring mig dette vedhæng, så belønner jeg dig for besværet."},
  [179] = {n="Dværgiske Udstyrshandlere", l="Sten Tykarm ønsker 8 stykker Sejt Ulvekød.", d="Hvad har vi her? Du ser ud, som om du kunne bruge noget til at holde hænderne varme, hm?\n\nJeg skal sige dig, hvad der ville hjælpe: et par pæne, varme handsker. Og da jeg er den venlige sjæl, jeg er, ville jeg være mere end glad for at skaffe dig et passende par. Jeg har dog én betingelse.\n\nJeg har brug for, at du henter noget ulvekød til mig. Pænt arrangement, hm? Du bringer mig noget ulvekød, så sørger jeg for, at du ikke mister nogen fingre til forfrysning. Nå, hvad siger du?"},
  [180] = {n="EFTERLYST: Løjtnant Hugtand", l="Dræb Løjtnant Hugtand og vend tilbage til Dommer Salomon i Søshire med hans pote.", d="Efterlyst: Løjtnant Hugtand\n\nKendt leder af Skyggeskjul-gnoldklanen, der arbejder for byens og kongedømmets fjende, Morgant. Efter befaling fra Dommer Salomon er denne modbydelige forræder mod Stormvind eftersøgt død. Vis Dommeren hans pote som bevis på hans død."},
  [181] = {n="Se mod Stjernerne", l="Find Zzarc'Brøl i ogrehøjen i det sydlige Skumringsskoven og bring hans monokel til Viktori i Mørkeshire.", d="Nu mangler der kun én ting for at fuldføre denne indretning. Tandhjuls tegninger kræver en slags linse. Den eneste linse, jeg kender, der ville være stor nok, vil være meget svær at skaffe.\n\nDer er en ogre ved navn Zzarc'Brøl, som holder til i højen i det sydlige Skumringsskoven. Hvis du kan, så bring mig hans monokel, og jeg vil bruge den som vores linse!"},
  [182] = {n="Trolde-hulen", l="Grelin Hvidskæg vil gerne have dig til at dræbe 14 Frostmanke-trollunger.", d="Min bror Senir og jeg blev sendt til forskellige dele af Dun Frostbakke for at undersøge den trussel, trollene udgør. Senatet har fuldt op med troggerne, så de har ikke brug for flere irritationsmomenter.\n\nAf det, jeg har set, er trollene ikke særligt godt placeret her i Kuldekam-dalen--mest den sydlige hule. Jeg vil sige, at hæren ikke bliver nødvendig. Et par stærke arme burde være mere end nok.\n\nMåske har du lyst til at hjælpe med denne opgave? Jeg har bemyndigelse til at tilbyde godtgørelse for din hjælp."},
  [183] = {n="Vildsvinejægeren", l="Talin Skarpøje vil gerne have dig til at dræbe 12 Små Klippevildsvin.", d="Intet slår en dag med vildsvinejagt, hva'?\n\nMen her i Kuldekam-dalen er der så mange vildsvin, at det næsten tager sjovheden af det. Ingen grund til at få dem til at storme. De er alle sure og klar til kamp uden hjælp. Faktisk har der på det seneste været så mange vildsvin i området, at det er blevet farligt for mig at gå på min daglige jagt.\n\nKort sagt: Hvis du kunne hjælpe mig med at dræbe nogle af vildsvinene, ville jeg sætte stor pris på det."},
  [184] = {n="Rynkebryns Skøde", l="Bring Rynkebryns Skøde til Bonde Rynkebryn.", d="Dette er skødet til et stort landbrugsområde i Vestfald. Det er underskrevet af en Theodore Rynkebryn og medunderskrevet af hans kone, Verna. Og på bagsiden af skødet står der hastigt skrevet:\n\n\"Vi lænede os op ad Rynkebryn og fik hans skøde. Tænkte, det kunne være praktisk, hvis du ville forfalske et af disse til dit eget sted.\n\nRynkebrynerne vil ikke give os problemer. Sidst jeg så dem, var de på vej ud af Vestfald, fast med en knækket vogn.\"\n\nDu tror måske, at Rynkebrynerne vil have deres skøde tilbage..."},
  [185] = {n="Tigermesterskab", l="Ajeck Krudtsnor fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Unge Kvælerdorn-tigre.", d="Da jeg var en ung pige, lærte min far mig kunsten at jage tigre.\n\nDe unge kattedyr er meget lettere at spore og nedlægge. Derfor starter vi let. Man finder ofte unge tigre nær ekspeditionslejren.\n\nTest dine sporingsevner og se, om du kan jage nogle af bestierne ned."},
  [186] = {n="Tigermesterskab", l="Ajeck Krudtsnor fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Kvælerdorn-tigre.", d="Du lærer, <Class>. Lad os nu teste dine evner med de modne katte. Dræb 10 Kvælerdorn-tigre denne gang."},
  [187] = {n="Tigermesterskab", l="Ajeck Krudtsnor fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Ældre Kvælerdorn-tigre.", d="Nu hæver jeg indsatsen og tester dine evner for alvor. Bevis for mig, at du kan dræbe 10 Ældre Kvælerdorn-tigre. Hvis du kan det, er du klar til din sidste udfordring, før jeg erklærer dig for en mestertigerjæger i Mester Jagtvarys' nærvær.\n\nÆldre Kvælerdorn-tigre er ikke kun de sværeste at finde, de er også de vildeste at besejre."},
  [188] = {n="Tigermesterskab", l="Ajeck Krudtsnor fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe Syndal og vende tilbage med hendes pote.", d="Her er den sidste udfordring, jeg stiller. Vi har sporet et svært fangbart tigerdyr i flere uger. Vi kalder udyret Syndal. Se, om du kan gøre, hvad ingen <Race> har gjort før: Opspor og dræb Syndal. Bring mig hendes pote som bevis på din bedrift.\n\nAt spore hende op bliver ingen let opgave."},
  [189] = {n="Blodskalp-ører", l="Skaf 15 Blodskalp-ører og bring dem til Kebok i Bytteviken.", d="Forbandede trolde! De har slået vores agenter ihjel i junglen! Jeg har allerede mistet et godt antal af mine bedste vagter i træfninger med dem. Udgifterne hober sig op! Hvordan skal jeg forklare det til Baron Tyranbrand?\n\nBeslutsom handling... Tænk, Kebok... du blev ikke sat på den post, du har i dag, for at sidde på røven... Jeg har det! Dig... <Name>, ikke? Du vil hjælpe mig, ikke? Der er penge at tjene!\n\nHer er aftalen... Bring mig ørerne fra femten Blodskalp-trolde, så belønner jeg dig rigeligt."},
  [190] = {n="Panterens Mesterskab", l="Ridder S. J. Erlgadin fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Unge Pantere.", d="Hvis du vil være en del af jagten med denne skarpe gruppe, Hemmet har samlet, må du bevise dig selv som en dygtig panterjæger. Vi starter let -- du skal ikke bekymre dig. Lad os se dig dræbe 10 unge pantere for at starte.\n\nAt spore dem op er kun halvdelen af udfordringen..."},
  [191] = {n="Panterens Mesterskab", l="Ridder S. J. Erlgadin fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Pantere.", d="Nu er du klar til at skrue op for det. Hvis du vil bevise, at du er værdig til at omgås disse storvildtjægere, må du vise, at du kan dræbe 10 pantere.\n\nDisse store drenge er sejere. De er ikke så lette som de unge, du dræbte tidligere."},
  [192] = {n="Panterens Mesterskab", l="Ridder S. J. Erlgadin fra Jagtvarys' Ekspedition vil gerne have dig til at dræbe 10 Skyggemule-pantere.", d="Nu den svære del. En sand panterjæger kan vise sin dygtighed ved at fælde Skyggemule-pantere, de dødeligste i Kvælerdorn. Bevis for os, at du kan slå 10 af disse udyr ihjel.\n\nHvis du synes, de er svære at spore, så vent, til du forsøger at slå en af dem ihjel...."},
  [193] = {n="Panterens Mesterskab", l="Ridder S. J. Erlgadin fra Jagtvarys' Ekspedition vil have dig til at bringe ham Bhag'tveras Hugtand.", d="Du har næsten bevist, at du er en mesterjæger af pantere. En panter ved navn Bhag'tvera har strejfet rundt i junglen. Indtil videre har den undsluppet vores gruppe. Se, om du kan bruge dine evner til at dræbe den store Bhag'tvera.\n\nBring mig Bhag'tveras Hugtand, så har du fortjent min respekt!"},
  [194] = {n="Raptorens Mesterskab", l="Hemmet Jagtvarys vil have dig til at dræbe 10 Kvælerdorn-raptorer.", d="Så du synes, dine jagtfærdigheder er i topform? Jeg kan sætte dem på prøve på et øjeblik. Gå ud i junglen og dræb 10 Kvælerdorn-raptorer. Vi vil se, hvor stor en storvildtjæger du er.\n\nOg nej, jeg fortæller dig ikke, hvor du kan finde dem! At finde udyrene er halvdelen af udfordringen."},
  [195] = {n="Raptorens Mesterskab", l="Hemmet Jagtvarys vil have dig til at dræbe 10 Piskehale-raptorer.", d="Lad os nu skrue op for udfordringen og se, om du er klar til det. Løb ud i junglen og skaf 10 af de forbandede Piskehale-raptorer. Lad os se, hvad du har!"},
  [196] = {n="Raptorens Mesterskab", l="Hemmet Jagtvarys vil have dig til at dræbe 10 Junglesnigere.", d="Lad os se, hvordan du klarer denne næste udfordring. Der findes en snedig raptorart derude. Vi kalder dem Junglesnigere. De er langt sværere at spore og dræbe end de andre arter, du har prøvet din lykke med. Dræb 10 Junglesnigere, så tipser jeg dig om de bedste jagtmarker endnu."},
  [197] = {n="Raptorens Mesterskab", l="Hemmet Jagtvarys vil have dig til at dræbe Tetis, en svær at fange, farlig raptor i Kvælerdorn.", d="Fordi du har bevist dig selv som sådan en handlekraftig type i junglen, så lad mig fortælle dig om en vild raptor, som selv jeg ikke har formået at dræbe. Ajeck her kalder denne snedige raptor Tetis.\n\nHvis du vil bevise dig selv som en sand mester, så dræb Tetis og bring mig hans klo. Det ville være en bedrift, som ingen anden storvildtjæger har udført."},
  [201] = {n="Undersøg lejren", l="Find jægerlejren og meld dens placering til Krazek i Bytteviken.", d="Jeg har fået rapporter om en gruppe jægere, der har slået lejr opstrøms for Ventureselskabets minelejr ved Nazferiti-søen. Nu ville jeg normalt ikke bekymre mig, men mærkeligt nok hørte jeg, at Hemmet Jagtvarys var en af jægerne derovre? Han har bestemt gode forbindelser, hvis du forstår mig, og man kan aldrig være for forsigtig.\n\nHvorfor tager du ikke ud og tjekker lejren, <Name>, og ser, hvad de går og laver?"},
  [208] = {n="Storvildtjægeren", l="Hemmet Jagtvarys vil have dig til at bringe ham hovedet af Kong Bangalash, den store hvide tiger.", d="<Name>, du er en jæger, der er værdig til vores selskab. Fra slagmarkerne i Herrelande til det dybeste jungle har jeg sjældent set sådan en våbenfærdighed, som du har vist.\n\nDu har dræbt den vilde Syndal, den svært fangbare Bhag'tvera og den forræderiske Tetis. Men den virkelige præmie er hovedet af Kong Bangalash. Den hvide tiger er grunden til, at jeg er her. Jeg har haft mit øje på ham i ret lang tid nu. Dræb Kong Bangalash, så er din jagtevne bevist som uovertruffen."},
  [214] = {n="Røde Silkehalstørklæder", l="Spejder Riell ved Vagtbakke-tårnet vil gerne have dig til at bringe hende 10 Røde Silkehalstørklæder.", d="Det er ingen hemmelighed, at Defias-bandens varemærke er deres røde halstørklæder. Men vi har fundet ud af, at stoffet, de er lavet af, viser medlemmets rang.\n\nDet sagt, vil jeg have dig til at eliminere så mange højtrangerede Defias-medlemmer, som du kan. De højest rangerede medlemmer vil uden tvivl findes i VanKløfts hemmelige skjulested. Når du er færdig, bring mig 10 Røde Silkehalstørklæder som bevis på deres død, så belønner jeg dig. Held og lykke, <Name>."},
  [216] = {n="Mellem en Sten og en Tistelpels", l="Nedlæg 12 Tistelpels-hævnere og 12 Tistelpels-shamaner; de fleste findes øst for Zoram-strandbredden i Tistelpels-landsbyen. Når det er gjort, vend tilbage til Karang Hammerstrøm ved Zoram'gar-forposten, Askedalen.", d="Tistelpels-furbolgerne truer vores ekspansion! Tistelpels-landsbyen mod øst blokerer vejen mellem os her og Splintertræ-Posten. Det er en sti, der ville omgå landsbyen Stjernelund; uden den giver vi Alliancen en ekstra ekspansionssti.\n\n<Name>, vi må ikke tillade... et hul i ekspansionsstien!\n\nTag til Tistelpels-landsbyen og tynd furbolgerne ud. Du vil få godtgørelse for opgaven, men vigtigere er, at du gør din pligt for Horden!"},
  [217] = {n="Til Forsvar for Kongens Lande", l="Dræb Trogg-høvdingen Grumsmug og hans to vagter, Gnaser og Slagsbror, og rapporter tilbage til Kaptajn Rugelfuss i det sydlige vagttårn.", d="<Name>, vores spejdere har identificeret lederen af denne nylige Trogg-indtrængen. Det ser ud til, at disse udyr i Modansøen følger høvdingen ved navn Grumsmug. Grumsmug er dog tungt bevogtet. To af hans mest elitære vagter, Gnaser og Slagsbror, viger aldrig fra hans side.\n\nHvis du føler dig værdig, <Name>, vil jeg have dig til at lede attentatet på Grumsmug og hans to håndlangere. Når Trogg-ledelsen er død, har vi måske en chance for at skubbe disse udyr tilbage i jorden."},
  [218] = {n="Den Stjålne Dagbog", l="Grelin Hvidskæg vil have dig til at dræbe Grik'nir den Kolde og hente hans dagbog.", d="Min dagbog! De tog den med ind i hulen. Ham, der havde den... Det var en stor brute med nogle mærkelige markeringer på huden og ansigtet. Jeg fik ikke et meget bedre kig end det.\n\nDu har haft lidt held med trollene, måske kunne du gå og hente den tilbage til mig?"},
  [219] = {n="Savnet i Kamp", l="Beskyt Korporal Kisen på rejsen tilbage til Rødryg.", d="Endelig, venner af Alliancen!\n\nHjælp... venligst...\n\nDet sidste, jeg husker, er, at disse grimme orker overmandede vores regiment. De fleste af mændene blev dræbt. Jeg fik et hårdt slag i hovedet, og alting blev sort. Nu er jeg fange i denne hule. Hjælp mig, jeg er hårdt såret.\n\nJeg skal have hjælp til at komme tilbage til byen... venligst... du er mit sidste håb..."},
  [221] = {n="Varulve i Skoven", l="Dræb 12 Nattebane Mørkeløber-varulve for Kalor i Mørkeshire.", d="Du har måske bemærket nogle større varulve, der vandrer rundt sammen med Skyggevæverne i skoven? Så vidt vi kan se, udgør disse Mørkeløbere størstedelen af varulvene.\n\nPå mine patruljeture har jeg også bemærket, at de har overrendt Rådnende Frugthave sydvest for byen. Disse varulve er en lille smule sejere end dem, du mødte sidst.\n\nVær på vagt."},
  [222] = {n="Varulve i Skoven", l="Dræb 8 Nattebane Ondskabshugtænder og 8 Nattebane Besmittede varulve for Kalor i Mørkeshire.", d="Dine tidligere bedrifter har overbevist mig om, at du er klar til at tage fat på de sejeste varulve, der hærger skoven.\n\nAf de varulve, der har gjort dette nye hjem til deres, har Ondskabshugtænderne og de Besmittede vist sig at være farligst. De har slået sig ned nær nogle af hulerne og i minen mod syd.\n\nFra langt væk kan man endda se lyset fra deres bål..."},
  [224] = {n="Til forsvar for kongens lande", l="Bjergbestiger Brosten fra det sydlige vagttårn vil have dig til at dræbe 10 Stensplinter-trogg og 10 Stensplinter-spejdere.", d="Vi må beskytte Modansøen, <Name>! Med så mange af kongens soldater, der kæmper tappert på fjerne slagmarker, er vi blevet overvældede på hjemmefronten. Troggerne graver sig op af hver eneste sprække! Trogg-angrebet udgør den største trussel mod Jernsmede. Disse modbydelige mutanter må udslettes.\n\nVi har brug for dig, modige eventyrer, til at drage af sted og lægge trogg-truslen øde. Slå 10 Stensplinter-trogg og 10 Stensplinter-spejdere ihjel og meld tilbage."},
  [225] = {n="Det forvitrede gravsted", l="Tal med Sirra Von'Indig i Mørkeshire.", d="Den forvitrede gravsten står simpelthen:\n\nMORGAN LADIMØRE\n\n<Ved nærmere eftersyn bemærker du, at jorden over graven nys er blevet forstyrret, og at en god del af jorden ser ud til at være flyttet...>"},
  [226] = {n="Ulvene i hælene på os", l="Dræb 12 Sultne Rædselsulve og 8 Rabiate Rædselsulve, og vend derefter tilbage til Lars i Svens Lejr på Skumringsskovens vestlige grænse.", d="Sven og jeg har farlige dage foran os, med Nekromanceren mod øst og alt det. Og når vi er alene herude, må vi selv jage vores mad. Det virker, som om hver gang jeg er på vej tilbage til lejren med noget kød på kroppen, kommer sultne eller rabiate rædselsulve ud af skoven og vil have en bid. Det går uden at sige, at det er farligt arbejde at bo herude!\n\nMen hvis du kan befri os for nogle af de ulve, bliver det lettere for os. De holder mest til nord og øst for her, nær floden."},
  [228] = {n="Mor'Ladhjem", l="Dræb Mor'Ladhjem, og bring derefter hans kranium tilbage til Kommandør Althea Ebenlås i Mørkeshire.", d="Det, mine spejdere fortæller mig, er, at Mor'Ladhjem vandrer rundt i Skumringsskoven og følger en underlig, snoet sti gennem kirkegården. Vi begravede ham ude forbi huset på bakken, ved du, hvor det er?\n\nDer er ikke noget, jeg kan gøre for at hjælpe dig, men jeg ønsker dig held og lykke."},
  [230] = {n="Svens Lejr", l="Bring bogen fra Svens Gård til Sven.", d="Mens du graver i højen, finder du en lille, jordplettet bog.\n\nBogen har ingen titel, men... den indeholder oplysninger, Sven gerne vil kende."},
  [231] = {n="En datters kærlighed", l="Tag Sarah Ladimøres ring til Morgan Ladimøres grav.", d="Her, tag den her og læg den på hans grav. Måske... på en eller anden måde vil han vide, at jeg har det godt, og at ingen af os holder ham ansvarlig for det, der skete.\n\n<Der står tårer i hendes øjne nu, mens hun glider en ring af sin højre hånd og trykker den i dine hænder.>\n\nOg... tak, <Name>."},
  [233] = {n="Post-udbringning i Kuldekam-dalen", l="Lever bunken af breve til Talin Skarpøje.", d="Hm, jeg regner ikke med, at du vil være villig til at gøre mig en tjeneste, knægt / pige? En bunke breve kom gennem passet i dag, men jeg har ikke tid til at sende dem videre.\n\nDe er alle adresseret til Talin Skarpøje. Du finder ham mod vest ad vejen. Han har slået lejr ved den frosne sø.\n\nHvad siger du?"},
  [234] = {n="Post-udbringning i Kuldekam-dalen", l="Lever brevet til Grelin Hvidskæg.", d="Hvis jeg husker rigtigt, ligger Grelins lejr ad vejen mod sydøst. Uden tvivl vil han være ivrig efter at få sin post."},
  [235] = {n="Askedalens jagt", l="Tal med Senani Torduhjerte ved Splintertræ-Posten, Askedalen.", d="Opmærksomhed, unge eventyrere! Vildmarken i Askedalen venter på jer!\n\nHorden har etableret en stærk tilstedeværelse i landene nord for Ødemarken. Vores to forposter - Splintertræ-Posten og Zoram-strandbredden-forposten - stræber efter at bringe ære til Horden! Dem, der vil bevise sig selv, bør søge vejledning der. Værd at bemærke: Senani Torduhjerte på Splintertræ-Posten, lige nord for Ødemarken, søger eventyrere, der er villige til at deltage i en stor jagt i Askedalen!"},
  [237] = {n="Til forsvar for kongens lande", l="Bjergbestiger Grusgaw i det sydlige vagttårn vil have dig til at dræbe 10 Stensplinter-kraniebanker og 10 Stensplinter-synskere og melde tilbage til ham.", d="Bjergbestiger Brosten havde kun gode ord at sige om dig, <Race>. Derfor vil jeg betro dig en opgave af allerstørste vigtighed. Vi må holde trykket på de invaderende trogg-styrker, indtil vores dværgiske brødre vender tilbage fra Alliance-fronten.\n\nDrag ud i de sydlige bakker og dræb 10 Stensplinter-kraniebanker og 10 Stensplinter-synskere. Dine angreb vil købe os lidt tid. Meld tilbage, når din opgave er fuldført."},
  [239] = {n="Vestbæk-garnisonen har brug for hjælp!", l="Gå til Vestbæk-garnisonen og tal med Stedfortræder Rainer.", d="Garnisonen ved vores vestlige grænse sender bud om stigende gnold- og tyveaktivitet. De beder os sende flere Stormvind-soldater... men vi har bare ingen at undvære!\n\nHvis du kan hjælpe, kunne vi godt bruge det. Gå og tal med Stedfortræder Rainer i Vestbæk-garnisonen og se, hvad han har brug for.\n\nGarnisonen ligger ad vejen mod vest. Når du er krydset over broen over den lille bæk, vil den ligge til højre."},
  [240] = {n="Tilbage til Ryster", l="Vend tilbage til Ryster med Skumrings-krabbekagerne.", d="Og så er vi her - \"Krabbe\"-kager à la Grual!"},
  [244] = {n="Invaderende gnolde", l="Meld til Stedfortræder Feldon.", d="Hils, <Class>. Jeg har fået til opgave at patruljere denne vejstrækning. Selvom vejen er tryg lige nu, har jeg set gnold-lejre mod nord og øst herfra.\n\nSøshire må vide om den samlede gnold-styrke! Meld til Stedfortræder Feldon i Søshire og fortæl ham om gnoldene. Gør du det, er jeg sikker på, at Feldon vil tilbyde dig en spejderløn.\n\nFeldon inspicerer normalt området syd for broen til Søshire."},
  [245] = {n="Ottebenede plager", l="Dræb 15 Dværg-giftnet-edderkopper, og meld derefter tilbage til Vagt Dodsen i Skumringsskoven.", d="Hils, <Class>. Har du måske set de edderkopper, der har overtaget den vestlige grænse? De ottebenede plager er for meget for os at klare, og Kommandøren har ikke nok mandskab at undvære så langt fra Mørkeshire.\n\nJeg hader at bede dig om dette, men du virker, som om du måske kan klare dem. Jeg kan ikke love dig noget af stor værdi, men jeg kan belønne dig, hvis du hjælper med at rydde de beskidte insekter væk.\n\nÅh, og et godt råd: Undgå deres gift, hvis du kan."},
  [246] = {n="Vurdering af truslen", l="Dræb 10 Rødryg-køtere og 6 Rødryg-krybskytter, og meld derefter tilbage til Stedfortræder Feldon i Søshire.", d="Vi har ikke mænd at undvære, men noget må gøres ved de gnolde, du har meldt til mig.\n\nSpejd det sydlige Rødryg for gnolde. Plag dem, dræb dem, du kan, og meld tilbage til mig med et antal af dem og en vurdering af den trussel, de udgør. Du kan finde gnoldene lejret langs hele den sydlige vej i Rødryg.\n\nGør dette for Stormvindsk Hær, <Name>, så bliver du belønnet."},
  [247] = {n="Jagten er fuldført"},
  [248] = {n="Ser længere", l="Klatr op i det intakte vagttårn ved siden af Stenvagtsfæstningen.\n\nFind en passende beholder, hvori du kan placere Azoras Glyf.", d="Jeg har holdt øje med Ilgalars Tårn og kan mærke, at Morgant er i konflikt med orkerne i Stenvagtsfæstningen. Jeg kender ikke årsagen til deres strid, men du kan hjælpe mig med at afdække dette mysterium.\n\nTag endnu et Azoras Glyf, og gå derefter til toppen af det intakte vagttårn ved siden af Stenvagtsfæstningen.\n\nFind et passende objekt, hvorpå glyffen kan placeres. En kiste eller en krukke - et sted hvor glyffen ikke bliver bemærket - vil passe til mit formål."},
  [249] = {n="Morgant", l="Besejr Morgant.\n\nBring hans Skyggevedhæng til Teokritos i Azoras Tårn i Elwynnskoven.", d="Efter megen observation har jeg opdaget Morgants planer.\n\nHan leder efter Elunes Le... og han har måske fundet den! Hvis han har, vil Rødryg-bjergene og Stormvinds kongerige snart mærke hans mørke styrke.\n\nJeg er ikke forberedt på at kaste mig op imod Morgant, men jeg frygter, at han må tages hånd om nu. Så du må gå ind i Ilgalars Tårn og stå over for Morgant.\n\nBesejr ham, og bring mig hans Skyggevedhæng. Gør du det, står kongeriget dig i dyb taknemmelighed."},
  [250] = {n="En mørk trussel truer", l="Undersøg området nær dæmningens østlige rampe, og bring Overingeniør Hinderweir et spor, der kan afsløre, hvad Mørkjernsdværgene har gang i.", d="Gud ske lov, at nogen er bekymret for dæmningens velfærd. Først ødelæggelsen af Thandol-spændet og så plyndringen af Dun Mødr! Jeg tvivler ikke på, at dæmningen bliver målet for den næste Mørkjern-trussel. Det meste af sikkerhedsstyrken her blev omfordelt til Alliance-fronten, inklusive min øverste inspektør.\n\nDet er derfor, jeg har brug for dig, <Name>. Jeg så nogle Mørkjerns-minørere rundt om på dæmningens østlige rampe. Undersøg området og bring et spor tilbage."},
  [251] = {n="Oversæt Abercrumbies brev", l="Bring brevet til Ello til Sirra Von'Indig.", d="Tag den seddel, du gav mig, til Sirra Von'Indig. Han er meget lærd i sprog og oldtidskunst - hvis nogen her kan oversætte denne besked, er det ham."},
  [252] = {n="Oversættelse til Ello", l="Bring det oversatte brev til Lord Ello Ebenlås", d="Åh, min! Hvis det, der står på denne seddel, er sandt, så har Abercrumbie gjort noget... usigeligt.\n\nDu må hellere bringe den oversatte seddel tilbage til Ello.\n\nOg gør det hurtigt, for jeg frygter, at en undergang allerede tramper mod vores by..."},
  [253] = {n="Balsamerens brud", l="Find Elizas grav. Hent Balsamerens Hjerte fra hende, og vend derefter tilbage til Ello Ebenlås.", d="Balsameren er et navn, der fortælles i en af vores børnehistorier. Han var en venlig alkymist, drevet til vanvid af sin hustrus død, Eliza. For at genoplive hende brugte han mørk magi til at placere sit eget hjerte i sin døde ægtefælles barm.\n\nDette genoplivede Eliza... men det forbandede hende med en sult efter menneskekød, og tvang Balsameren til at holde hende begravet.\n\nHans hjerte er hans magt. Find hans hustrus grav, hent hans hjerte, og bring det til mig, mens det stadig slår. Gør du det, bliver hans magt brudt."},
  [255] = {n="Lejesoldater", l="Dommer Stumpnæse fra Tælsamar har hyret dig til at dræbe 4 Mo'grosh-oger, 4 Mo'grosh-brutaler og 4 Mo'grosh-håndhævere.", d="To måneder bare for at høre fra Jernsmede, at vi vil få skånet for en håndfuld soldater til vores eget forsvar, og endnu to måneder, før de ankommer! Det er ondt nok, at vores by er ubeskyttet, men udgravningen og dæmningen - dæmningen! - er også åbne for angreb.\n\nJeg har så ingen valg, det ser ud til. Jeg bliver nødt til at leje våben.\n\nHvad med dig? Du virker som en oplagt type, <Class>. En gruppe oger har slået lejr nordøst for søen. Måske kunne du rekruttere nogle andre og hjælpe med at fjerne truslen mod vores by?"},
  [256] = {n="EFTERLYST: Chok'sol", l="Dræb Chok'sol og bring hans hoved til Dommer Stumpnæse fra Tælsamar.", d="Efter ordre fra Dommeren i Tælsamar:\n\nChok'sol, oger der formodes at være leder og koordinator af angrebene mod byen Tælsamar, Stenhugget Dæmning og udgravningsstedet, eftersøges død ved alle midler.\n\nDer vil blive udbetalt pengekompensation, når der fremlægges bevis for Chok'sols død over for Dommeren.\n\nChok'sol blev sidst set ved oger-lejren i den nordøstlige del af Modansøen."},
  [262] = {n="Den skyggefulde skikkelse", l="Tag bogen, du fandt på Svens gård, og vis den til byfolk i Mørkeshire.", d="Jeg må vide, hvem den luskende skikkelse i skyggerne var, jeg så den nat, min familie blev dræbt!\n\nVær venlig, <Name>, du har vist din snarrådighed. Find venligst den skyggefulde skikkelse. Jeg må finde ud af, hvilke hemmeligheder han gemmer på!\n\nJeg har ikke spor, du ikke allerede kender, men tag her - tag bogen, du fandt på min gård. Måske kan nogle af byfolkene forbinde bogen med dens ejer."},
  [263] = {n="I Forsvar af Kongens Lande", l="Bjergbestiger Vægbang i det sydlige vagttårn vil have dig til at dræbe 10 Stensplinter-shaman og 10 Stensplinter-knoglebrækkere.", d="Bjergbestigerne fortæller mig, at du er ret modig og dygtig, <Name>. Vi har brug for en <Race> som dig herude. Trogg-problemet bliver ikke bedre. Reserverne er kaldt til fronten, og vi står helt alene herude. Men nu hvor vi har en garvet <Class> her, lad os se, hvad du kan.\n\nDrag ud og dræb 10 Stensplinter-shaman og 10 Stensplinter-knoglebrækkere. Lad os se, om du lever op til dit ry, Trogg-banemand."},
  [264] = {n="Indtil Døden Skiller Os Ad", l="Placer Clarices Vedhæng på Yurivs Grav i Silverpine.", d="Beskidte skiderik! Forlader mig for sit forbandede korstog. Fordi \"Lyset er det vigtigste, vi har mod de trusler, de udøde udgør.\"\n\nNå, hvad med hans børn?! Hvad med MIG?! Nat efter nat sad jeg tålmodigt og ventede på ham... altid på andenpladsen efter hans forbandede pligt!\n\nNå, se hvad \"retfærdighed\" bringer dig, <Name>! Han er død, og jeg bærer netop det, han forsøgte at standse!\n\nTag denne skrammel og læg den på hans grav i Gravkammeret. Jeg vil ikke have mere med den at gøre... eller ham!"},
  [265] = {n="Den Skyggefulde Eftersøgning Fortsætter", l="Se om andre byfolk har spor om den skyggefulde skikkelse.", d="Her er din bog tilbage, <Name>, og jeg ønsker dig held og lykke med din eftersøgning. Spørger du andre i byen, kan de måske give dig flere spor.\n\nOg her er lige en mere til dig – selvom bogens forfatter er en fremmed i Mørkeshire, blev selve bogen købt her."},
  [266] = {n="Spørg På Kroen", l="Søg i kroen efter spor om den skyggefulde skikkelse.", d="Her er din bog, og held og lykke med dine undersøgelser.\n\nDu vil måske udvide din eftersøgning til kroen. Hvis den person, du leder efter, har tilbragt tid i byen, er der god chance for, at nogen har set ham der."},
  [267] = {n="Trogg-Truslen", l="Bring 8 Trogg-stentænder til Kaptajn Rugelfuss i det sydlige vagttårn.", d="<Class>, du er måske eller måske ikke klar over den trogg-trussel, der hænger over dværgenes lande. Med Jernsmede-reserven kaldt op til Alliancens front står vi tilbage med en brøkdel af de forsvarsstyrker, der skal til for at holde disse lande sikre. Mit regiment er sat til at holde øje med porten her, og vi kan ikke forlade vores post af frygt for invasion.\n\nMen vi må lægge pres på de forbandede trogger, der lurer i bakkerne. Hvis du er til opgaven, så gå til angreb på troggerne. Bring mig 8 Trogg-stentænder som bevis."},
  [268] = {n="Tilbage til Sven", l="Vend tilbage til Sven med Rysters færdige dagbog.", d="Bogen du fandt var kun halvt færdig. Jeg måtte efterlade den på Svens gård, da jeg flygtede derhen...\n\nSå her. Tag min færdige dagbog til Sven. Den beskriver mere fyldestgørende, hvad der skete på hans gård.\n\nSkønt denne dagbog har været mit eneste selskab de sidste uger, gør jeg det gerne, hvis det kan holde mig fra at skulle møde Sven og hans vrede!"},
  [269] = {n="Søgen efter Visdom", l="Giv Rysters færdige dagbog til Biskop Farding i Stormwind.", d="Tag til byen Stormwind og tal med Biskop Farding i Lysets Katedral. Giv ham Rysters dagbog og fortæl ham, at du har tænkt dig at træde op mod Morbent Ondt.\n\nSkønt Stormwind har svigtet Mørkeshire, er Farding en venlig sjæl og meget klog. Han kan måske hjælpe dig på din færd for at redde os.\n\nDin mission er farefuld, men skynd dig, <Name>. For hver time der går, bliver skyggerne i Skumringsskoven mørkere."},
  [270] = {n="Den Dømte Flåde", l="Tag til Menetil-havnen i Vådlandene, og tal med Glorin Stålbryn.", d="For år siden sank Kul Tirasks Tredje Flåde langs Vådlandenes kyster, et vidt morads nord for det dværgiske rige Jernsmede. Om bord på ét af skibene var en last Lysssmede-jern.\n\nDette metal er dyrebart for os, for ting smedet af det rammer med hellig sandhed. Hvis du skal træde op mod Morbent Ondt, får du brug for et sådant våben.\n\nTag til Menetil-havnen og tal med min dværgiske kollega Glorin Stålbryn. Hvis det tabte metal kan findes, ved han, hvor han skal lede."},
  [271] = {n="Vyrins Hævn", l="Dræb Gamle Sodfar og vis dit værk til Daryl Ungkarl ved Fjernvandrer-logen.", d="Jeg regner ikke med, at du er interesseret i lidt betaling for hans Frækhed? Daryl har nogle færdigheder, det smerter mig at sige.\n\nFor et år siden var en stor bjørn målet for Fjernvandrer-logen, men ingen af jægerne havde held med ham. Så Daryl tænkte, at han ville prøve sine kræfter mod ham. Alt, han fik ud af sin indsats, var det grimme ar over øjet.\n\nDræb bjørnen, og jeg er sikker på, at selv Daryl ville blive målløs for en gangs skyld.\n\nBjørnen, Gamle Sodfar, kan findes omkring sit hi i bakkerne over Tælsamar."},
  [272] = {n="Søløvens Prøve", l="Find den halve Vedhæng for Akvatisk Smidighed og den halve Vedhæng for Akvatisk Udholdenhed. Tal med indbyggerne i Månelunden for at få spor om, hvor disse genstande kan være.\n\nSmed Søløvens Vedhæng af de to vedhængshalvdele. Du skal være i nærheden af Remulos' Helligdom for at gøre dette.\n\nBring det samlede vedhæng til Dendrit Stjerneblus i landsbyen Nathavn, Månelunden.", d="Til den anden prøve skal du bruge de to halvdele, der udgør Søløvens Vedhæng. Den ene halvdel trækker kraft fra søløveaspektets smidighed, idet den glider gennem vandet; den anden trækker kraft fra søløveaspektets utrolige udholdenhed. Druider trækker lige meget på begge egenskaber for at legemliggøre aspektet af deres akvatiske form.\n\nTal med de lokale i Månelunden for at lære, hvor delene kan være, og bring dem begge hertil for at samle dem. Når vedhænget er dannet, skal du tage det til Dendrit Stjerneblus."},
  [273] = {n="Forsyninger til Udgravningen", l="Tal med Huldrik.", d="Det er dog ikke for sent, du er velkommen til at lede efter Huldrik. Han kan ikke være nået særlig langt, for stærke som de er, kan Mirran og Saeen ikke bevæge sig hurtigt med de tønder på ryggen.\n\nDe tager den normale rute til stedet, ud af byen mod syd og følger søens krumning.\n\nDu burde ikke have problemer med at finde dem, medmindre de allerede er nået frem."},
  [274] = {n="En Mørk Trussel Truer", l="Ashlan Stenskær vil have dig til at vende tilbage til Overingeniør Hinderweir og informere ham om den nye opdagelse.", d="Det her er ikke almindeligt sprængpulver. Se på de små sølvkrystaller. Og den tydelige lugt! Det er klart som dagslys, at dette er Søforium-pulver. Søforium er harmløst nok. Men når det bliver vådt, kunne det sprænge Jernsmede ud af bjerget.\n\nDen kemiske reaktion kan neutraliseres ved at blande fire komponenter: lurervenom, knust Mo'grosh-krystal, en krokolisk-tåre og denne afvæbnende kolloid. Fortæl nu Hinderweir det, før det er for sent!"},
  [275] = {n="Blærer på Landet", l="Dræb 12 Morads-krybler, og vend derefter tilbage til Rethiel Grønvogteren i Vådlandene.", d="Jeg ved ikke hvorfor, men en byld vokser frem i Vådlandene. Morads-krybler er rejst op. De er betændte, febrilske blærer på landet, og for at feberen skal bryde, må de nedlægges og få lov til at synke tilbage i mosen.\n\nMorads-krylerne skraber rundt blandt Vådlandenes vandveje."},
  [276] = {n="Tramp af Poter", l="Dræb 15 Mosshud-gnolde og 10 Mosshud-køtere, og vend derefter tilbage til Rethiel Grønvogteren i Vådlandene.", d="Mosshud-gnoldene har levet fredeligt i Vådlandene i mange år, men nu vokser de i antal. Deres fødder træder morads-buskene og blomsterne flade, og deres onde økser hugger for meget træ til at brænde deres ild.\n\nDe er ikke længere i balance med landet. For at Vådlandene skal overleve, må gnoldene reduceres.\n\nDræb 15 Mosshud-gnolde og 10 Mosshud-køtere. Jag dem mod syd, nær dværgeporten Algaz. Når du har gjort det, kommer du tilbage til mig."},
  [277] = {n="Ildtabu", l="Bring Rethiel Grønvogteren 9 grove flint.", d="Mosshud'erne fælder træerne i Vådlandene og bruger træernes kød til at varme sig ved ild. Jeg vil ikke lide denne smerte længere!\n\nFrarøv Mosshud'erne deres grove flint, de redskaber de bruger til at lave ild. Flinten bæres af alle Mosshud'er undtagen de mindre Mosshud-gnolde og Mosshud-køtere."},
  [279] = {n="Kløerne fra Dybet", l="Dræb 12 Blågælle-mudderfisk.\n\nSlå Sluger ihjel og tag hans hoved.\n\nBring Slugerens Hoved til Karl Boren i Menetil-havnen.", d="Mudderfisk kravler op af det dybe vand og bygger deres landsbyer langs kysten. De chikanerer vores fiskere og købmænd og må stoppes.\n\nÉn af disse mudderfisk, Sluger, lurer sammen med andre Blågælle-mudderfisk og plager købmænd langs vejen, og trækker sig altid derefter tilbage til sikkerheden i de nærliggende mudderhytter. Vores købmænd er i fare, og vi vil betale for at sikre dem.\n\nSluger driver rundt i flodindløbet nord herfra. Find ham, slå hans slægtninge ihjel, og bring mig hans hoved."},
  [281] = {n="Genopret Varerne", l="Søg i kasserne og tønderne ved kystens mudderfisk-lejre.", d="For ikke længe siden blev et handelsskib, Den Blinde Prinsesse, plyndret af mudderfisk. Selvom skibet slap uskadt, blev meget af dets last slæbt over bord af væsnerne, herunder en meget værdifuld statuette af Terenas Menetil. Vi vil have statuetten genfundet.\n\nSøg i de kystnære mudderhytter efter kasser, tønder og andet bevis på tabt last. Find Menetil-statuetten og bring den til mig."},
  [282] = {n="Senirs Observationer", l="Tal med Bjergbestiger Thalos.", d="Jeg havde planlagt at sende min lærling til min bror Senir med min rapport, men jeg ville have det meget bedre, hvis den blev lagt i mere... pålidelige hænder. Altså, hvis du ikke har noget imod det?\n\nHmm... du bliver nødt til at tage tunnelen for at komme til Kharanøs.\n\nTal med Bjergbestiger Thalos, før du går gennem tunnelen. Den er fuldstændig invaderet af trogger nu.\n\nFølg vejen tilbage til Ambolthøj, og fortsæt så mod øst til tunnelen; Thalos er stationeret i nærheden."},
  [284] = {n="Eftersøgningen Fortsætter", l="Søg efter Menetil-statuetten.", d="Du gennemsøger grundigt denne klynge af mudderhytter og finder ingen spor af Menetil-statuetten.\n\nMåske har en af de to nærliggende hytter mod nord og nordøst flere spor."},
  [285] = {n="Søg i Flere Hytter", l="Fortsæt med at søge i mudderhytterne efter Menetil-statuetten.", d="Denne gruppe af mudderhytter afslører intet efter en grundig undersøgelse.\n\n...men du er sikker på, at det næste spor, du finder, vil bære frugt.\n\nEn af hytterne mod nord må have Menetil-statuetten!"},
  [286] = {n="Bring Statuetten Tilbage", l="Bring Karl Boren Menetil-statuetten.", d="Efter at have trukket tønden fri af mudderet og åbnet den, finder man en sølvfarvet figur pakket ind i fint halm. Den forestiller en ung, langhåret paladin med hammeren hævet.\n\nDette må være Menetil-statuetten! Du skal nu returnere den til Karl Boren i Menetil-havnen."},
  [287] = {n="Frostmanke-fæstningen", l="Udforsk Frostmanke-fæstningen, og dræb 5 Frostmanke-hovedjægere for Senir Hvidskæg i Kharanøs.", d="Jeg er bagud med min rapport og kunne bruge din hjælp, <Name>. Jeg fandt lige ud af, hvor trolderne har slået sig ned, men jeg så så mange trolde, at jeg var bange for at gå ind.\n\nDet er, hvad jeg har brug for... Gå ned i hulen, rod rundt indeni, dræb nogle af trolderne, og kom så tilbage hertil.\n\nTag vejen nord ud af Kharanøs. Når du kommer til broen, følg den frosne flod mod vest, indtil du når Isstrøm-søen. Du finder Brygnall-landsbyen på den vestlige bred. Fæstningen ligger sydvest for landsbyen."},
  [288] = {n="Den Tredje Flåde", l="Køb en krukke Honningmjød til Førstestyrmand Fitzsimmons.", d="Jeg var engang førstestyrmand på Bølgemestreren, et linjeskib i Kul Tirasks Tredje Flåde. Den Dømte Flåde. Dømt, for på dens sidste togt blev flåden angrebet af Røde Drager. Drager kontrolleret af Orker!\n\nVi havde ingen chance mod den ildånde... og vores flåde blev brændt og sank ud for denne kyst. Jeg er den eneste overlevende fra de stakkels skibe...\n\n...åh, mit hoved hamrer og banker! Jeg skal bruge en frisk drink, hvis jeg skal få styr på denne tømmermand og fortsætte min historie."},
  [289] = {n="Den Forbandede Besætning", l="Dræb 13 Forbandede Sømænd, 5 Forbandede Marinesoldater og Førstestyrmand Snellig. Bring Snelligs Snusdåse til Førstestyrmand Fitzsimmons i Menetil-havnen.", d="<Opmuntret, fortsætter Fitzsimmons sin historie...>\n\nJeg er den eneste overlevende fra den ulykkelige Tredje Flåde fra Kul Tirask, forlist ud for kysten mod nord. Men selvom jeg er den eneste i flåden, der stadig trækker vejret, er jeg ikke den eneste, der stadig går rundt! For på et af vores skibe var en stor og forfærdelig skat skjult, og dens uhyggelige kraft holder mine brødres sjæle fanget i skibenes rådne skrog.\n\nMen hvis du kan befri nogle af mine brødre, kan du måske bryde deres forbandelse."},
  [290] = {n="Løft Forbandelsen", l="Få Den Uforfærdedes Pengeskabsnøgle fra Kaptajn Halyndor.\n\nBrug nøglen til at åbne Den Uforfærdedes Låste Pengeskab.", d="For at bryde forbandelsen og befri alle mine brødre skal...tingen...der er gemt på mit skib, hentes og renses! Jeg ved ikke, hvad det var, men jeg ved, at det var sikkert opbevaret i skibets pengeskab, som Kaptajn Halyndor herskede over.\n\nMin gamle kaptajn er stadig i mine drømme. Jeg ved, at han går rundt på mit dømte skib, Den Uforfærdede. Hent nøglen fra ham, og brug den til at åbne Den Uforfærdedes pengeskab.\n\nNår du har den forbandede ting, skal du bringe den til præsten Glorin Stålbryn i byen."},
  [291] = {n="Rapporterne", l="Lever Senirs rapport til senator Barin Rødsten i Jernsmede.", d="Fremragende! Tag min rapport med til senator Barin Rødsten. Han er en surmule, så lad dig ikke slå ud af hans mindre solskinsagtige humør. Han er i Jernsmede, i salen hvor Kong Magni holder hof.\n\nKender du ikke vejen til Jernsmede? Tag vejen ud af Kharanøs mod nord, kryds broen, og følg så vejen mod øst – der står store bannere langs vejen – op ad bjergsiden.\n\nApropos, kunne du lade være med at nævne, hvordan du hjalp mig? Jeg kan ikke lade dem tro, at jeg ikke arbejder hårdt herude, ved du?"},
  [292] = {n="Palets Øje", l="Bring det forbandede Palet-øje til Glorin Stålbryn.", d="Når kisten åbnes, afsløres en sortbrændt kugle, der pulserer med et uhyggeligt lys. Det er skatten, Fitzsimmons talte om: et forbandet Palet-øje.\n\nTag det forbandede Palet-øje med til dværgepræsten Glorin Stålbryn i Menetil-havnen. Spørg ham, hvordan man fjerner øjets forbandelse."},
  [293] = {n="Renselsen af Øjet", l="Bring ærkebiskop Benedictus det forbandede Palet-øje. Benedictus er i Lysets Katedral i byen Stormvind.", d="Jeg kan ikke løfte forbandelsen fra Palet-øjet. Øjnene blev smedet af menneskelige præster, så du bliver nødt til at tage til Stormvind for at finde en, der kan hjælpe dig. Tal med ærkebiskop Benedictus. Han er leder af Lysets Katedral i Stormvind. Han kan hjælpe.\n\nJeg håber det, for din skyld."},
  [294] = {n="Ormers Hævn", l="Ormer Jernflette ved Whelgar-udgravningsstedet vil have dig til at dræbe 10 Plettede Skrigere og 10 Plettede Raptorer.", d="Situationen er alvorlig, det er i hvert fald sikkert. Da vi blottede disse knogler, tiltrak det raptorerne. Disse snavsede bæster dræbte mine brødre og fangede mig, Merrin og den stakkels prospektor her oppe.\n\nHjælp med at rydde Vådlandene for disse raptorer, <Name>. Plettede Raptorer og Plettede Skrigere står lige vest for klippeskrænten dér. Dræb 10 af hver, hvis du kan.\n\nDet bliver en god start på den hævn, jeg har planlagt for dem."},
  [295] = {n="Ormers Hævn", l="Ormer Jernflette vil have dig til at dræbe 10 Plettede Leklo-raptorer og 10 Plettede Barberkæbe-raptorer, og derefter vende tilbage til ham ved Whelgar-udgravningsstedet.", d="Nu er det tid til virkelig at få de frygtede raptorer til at fortryde deres blodtørst. Lige længere nede findes der hundredvis af Plettede Leklo og Plettede Barberkæber. Få de rådne skabninger til at betale ved at slå 10 af hver!"},
  [296] = {n="Ormers Hævn", l="Ormer Jernflette ved Whelgar-udgravningsstedet vil have dig til at dræbe Sarltand og vende tilbage til ham med en af hans kløer, når opgaven er udført.", d="Mens du var dernede, lagde jeg mærke til, at et af de bæster skilte sig ud fra resten. Han var større og mere truende. Jeg vil vædde på, at han er den, der førte de andre hertil for at forstyrre udgravningsstedet.\n\nJeg beder dig nu om en sidste opgave, <Name>. Sørg for, at Sarltand bliver stillet til ansvar. Og al hensyn til forbrydelsernes alvor – retfærdighed betyder i dette tilfælde død! Bring mig en af hans kløer som bevis på hans død."},
  [297] = {n="Indsamling af Idoler", l="Bring Magmar Skindspænd 8 Udskårne Stenidoler.", d="For nylig, lige før Troggerne dukkede op i udgravningen, havde vi afdækket et stort antal mærkelige, udskårne idoler. Men vi fik ikke chancen for at studere dem, for kort efter fundet jagtede Troggerne os væk fra ruinerne! Og disse idoler har en mærkelig virkning på Troggerne. De får dem til at gå amok!\n\nBring mig 8 idoler – jeg vil studere dem, og jeg vil have dem ud af trogg-hænder! Du kan finde idolerne på de troggere, der hærger stedet."},
  [298] = {n="Udgravningens Fremskridtsrapport", l="Bring Jernbånds fremskridtsrapport til Jern Hornhjelm i Thelsamar.", d="Jeg har brug for en fremskridtsrapport sendt til Thelsamar – en fremskridtsrapport og en gentagelse af min anmodning om mere sprængpulver! Her er rapporten. Tag den med til Jern Hornhjelm. Han er vores lokale kontaktperson i Thelsamar.\n\nDet er ikke en svær opgave, men den skal gøres."},
  [299] = {n="Afdækning af Fortiden", l="Prospektor Whelgar vil have dig til at kæmme udgravningsstedet igennem for at finde de 4 manglende tavlefragmenter: Ados, Modr, Golm og Neru.", d="Lige før invasionen afdækkede jeg en stor tavle kaldet Goaz-stenen. Den oversatte tekst stopper flere steder. Teksten taler om en \"guddommelig plan\" og en \"dømt profeti\".\n\nJeg er bange for, at vi løber tør for tid. Jeg er for gammel til at gå derned og trodse de bæster. Men du er stærk.\n\nKæm udgravningsstedet igennem og afdæk de 4 manglende tavlefragmenter: Ados, Modr, Golm og Neru. Led efter dem i gamle artefakter eller der, hvor jorden er løs. Bring dem til mig, så jeg kan begynde at løse mysteriet!"},
  [301] = {n="Rapport til Jernsmede", l="Tag Jernbånds fremskridtsrapport til prospektor Stormspids.", d="Vi skal bruge godkendelse for at få Jernbånd mere sprængpulver. Du bliver nødt til at tage hans rapport med til Opdagelsesrejsende-Ligaens hovedkvarter i Jernsmede.\n\nHer er rapporten. Giv den til prospektor Stormspids, og glem ikke at dukke dig, når du har leveret den. Stormspids er hidsig, og han bliver ikke glad for at høre om Jernbånds langsomme fremskridt på stedet.\n\nDu finder Stormspids i Opdagelsesrejsendes Forsamling."},
  [302] = {n="Pulver til Jernbånd", l="Tal med Jern Hornhjelm i Thelsamar.", d="Hvis Jernbånd stadig har brug for sprængpulver, så skal han ved Magni have det! Jeg sendte godkendelsen i forvejen med en budbringer til Jern Hornhjelm i Thelsamar. Han vil gøre pulveret og andet udstyr klar til at tage med til Jernbånd.\n\nOg en ting mere: Jeg vil have dig til personligt at sørge for, at forsendelsen af pulveret når frem. Den sidste nåede aldrig frem, så hold dit hoved skarpt og øjnene åbne."},
  [303] = {n="Den Mørke Jernkrig", l="Broget Garmason i Dun Mødr vil have dig til at dræbe 15 Mørkjernsdværge, 5 Mørkjerns-tunnelgravere, 5 Mørkjerns-saboterere og 5 Mørkjerns-sprængere.", d="Krigen raser både hjemme og ude. Mens mægtige dværgesoldater ofrer deres liv i fjerne områder i Alliancens navn, falder vores egne lande offer for de mørkjernsdværges onde gerninger. De lagde Thandol-spændet øde. Dun Mødr faldt kort efter.\n\nVi har brug for, at du samler styrke og skubber fronten tilbage. Hvis du kan dræbe 15 Mørkjernsdværge, 5 tunnelgravere, 5 saboterere og 5 sprængere, kan forstærkningerne måske nå frem i tide til at fuldende fremstødet.\n\nNu skal det gå stærkt!"},
  [304] = {n="En Barsk Opgave", l="Dræb Balgaras den Onde og bring hans øre til Langfletten den Barske uden for Dun Mødr.", d="Mange af mine soldater døde i slaget ved Dun Mødr. Min egen bror omkom, da Vestbroen over Thandol-spændet blev ødelagt. Ja, mørkjernsdværgene er en djævelsk race. Ifølge det Rogo kunne samle, er lederen af denne bande af tøjere i Vådlandene en hekseman ved navn Balgaras den Onde. Han er dog en stor kujon. Han sender sine soldater for at udføre hans beskidte arbejde, men holder sig selv skjult og undgår fare.\n\nHvis du kan finde det rygradsløse pak, så dræb ham og bring mig hans øre. Jeg vil belønne dig, <Class>."},
  [305] = {n="På Jagt efter Udgravningsholdet", l="Tarrel Stenvæver vil have dig til at rejse til udgravningsstedet og kontakte Merrin Stenvæver.", d="Du aner ikke, hvor bekymret jeg har været.\n\nMin kone, Merrin, har sendt mig breve hver uge den seneste måned. Hun er med i Whelgar-udgravningsholdet. Men det er næsten to uger siden hendes sidste brev. Der er helt sikkert noget galt!\n\nLangfletten sagde, at han ville sende en spejder for at tjekke op, hvis vi ikke hørte fra holdet snart. Jeg går ud fra, at den spejder er dig, <Name>. Find Merrin ved udgravningsstedet mod øst!"},
  [306] = {n="På Jagt efter Udgravningsholdet", l="Vend tilbage til Tarrel Stenvæver med Merrins seddel.", d="Det var forfærdeligt! Vi blottede nogle sjældne artefakter, og så begyndte vi at finde disse store knogler.\n\nFør vi vidste, hvad der skete, overvældede disse Plettede Raptorer udgravningsstedet. Mange liv gik tabt.\n\nOrmer her – så modig – reddede prospektoren og mig. Han forsvarede os, mens vi løb efter ly. Nu er vi fanget. Og vores hårde arbejde ligger i ruiner.\n\nSå tag den her seddel med tilbage til min søde Tarrel. Den vil forklare ham situationen."},
  [307] = {n="Beskidte Poter", l="Gå til Sølvstrøm-minen og saml 4 læs Minearbejderudstyr.\n\nVend tilbage til bjergbestiger Stormspids.", d="Sølvstrøm-minen mod øst løb tør for længe siden. Den blev omdannet af Minearbejder-Ligaen til et lagerdepot, men nu er kobolder flyttet ind og har lagt deres beskidte poter på gode, dværgiske værktøjer!\n\nVi skal nok få udryddet de skadedyr snart nok, men Ligaen vil have nogen til at hente deres udstyr ud af minen, før vi krigere stamper ind og ødelægger tingene. Det bliver en hård nedstigning – du vil nok have følgesvende ved din side.\n\nUdstyret opbevares i Minearbejder-Ligaens kasser rundt i hele minen. Held og lykke."},
  [308] = {n="Afledningen af Jarvent"},
  [310] = {n="Bitre Rivaler", l="I kælderen under Tordenbryg-destilleriet i Kharanøs skal du udskifte en tønde Tordenøl med en Tønde Byggøl-Skoldeøl.", d="Jeg må indrømme, at Tordenbryg-folkene laver nogle gode drikke. Men de må lære, at deres ikke er det eneste anstændige bryg! Måske kan du hjælpe mig med at lære dem den lektie...\n\nHer, tag denne tønde Byggøl-Skoldeøl. Snig dig ned i kælderen under Tordenbryg-destilleriet i Kharanøs og byt den ud med en af deres tønder Tordenøl. Så må vi se, hvordan deres gæster synes om mit bryg frem for deres!\n\nOg hvis tønderne er vagtet, må du måske aflede vagten..."},
  [311] = {n="Tilbage til Marleth", l="Bring tønden med Tordenøl til Marleth Byggøl i Brygnall-landsbyen.", d="Efter at have indsat en tønde Marleths Skoldeøl i Kharanøs-destilleriets kælder, tager du en tønde Tordenøl med som bevis på bedriften..."},
  [312] = {n="Tundra MacGranns Stjålne Lager", l="Hent Tundra MacGranns tørrede kød fra det stjålne kødkammer i Gamle Isskægs hule.", d="Jeg havde saltet og låst en måneds tørret kød væk til den kolde årstid. Låst inde, så bjørnene ikke skulle få fat i det! Men mens jeg var på jagt efter hjorte, stak det uhyre, Gamle Isskæg, af med kødkammeret. Han kan ikke bryde igennem den thorium, men jeg sulter, hvis jeg ikke får mit kød tilbage.\n\nDu virker lidt mere snigende end mig. Måske kan du hente mit lager? Jeg når aldrig ind og ud af den hule hurtigt nok med dette dårlige ben af mig."},
  [313] = {n="Den Grizzlede Hule", l="Saml 8 Wendigo-man og bring dem til Pilot Stengear.", d="At køre et Belejringsvåben er ikke for alle. Det kræver et jerngreb og nerver af stål... heldigvis har jeg begge dele! Hvad med dig? Hvordan står det til med dit mod? Vil du bevise det for mig?\n\nTja... jeg vil gerne gøre min maskine, Trollpløjen, lidt mere hyggelig. Hvad med at du skaffer mig en bunke Wendigo-man fra Den Grizzlede Hule, vest for Kharanøs? Disse manker ville lave et fint tæppe til Trollpløjens indvendige dæk!"},
  [314] = {n="Beskyttelse af Hjorden", l="Rudra Ambersten vil have dig til at slå Vagash ihjel og bringe hans hugtand til hende ved Væderranchen.", d="Vi hørte skrigene midt om natten. Og i morges, sandelig, manglede hjorden to vædere. Det nedrige uhyre, kendt som Vagash, har hærget vores levebrød. Med det meste af Kong Magnis hær ude i fjerne lande og kæmpe for Alliancen, er der ingen til at holde Vagash i ave.\n\nMåske er du modig nok til at søge bestien op og slå den ihjel. Bring mig en af hans hugtænder, så belønner jeg dig. Vagash lurer lige ovenfor ranchen her, men vær advaret, han er dødbringende."},
  [315] = {n="Den Perfekte Stout", l="Bring 6 Glimmergræs til Rejold Byggøl i Brygnall-landsbyen.", d="Jeg er på en mission, en mission om at lave den perfekte stout. Jeg ved, jeg kan gøre det – brygning går i blodet på mig. Jeg skal bare finde den rette opskrift...\n\nFrostmanke-troldene dyrker en plante, glimmergræs, højt oppe i bakkerne mod øst. De bruger den i deres mærkelige, stammelige ritualer. Vi dværge har ikke fundet meget brug for den, men den har en unik smag... og jeg vil eksperimentere med den i mine bryg!\n\nSkaf mig noget glimmergræs fra Frostmanke-seerne, eller snup det fra troldenes glimmergræs-kurve."},
  [317] = {n="Proviantering af Jetdamp", l="Saml 4 Stykker Vildsvinekød og 2 Tykke Bjørnepelse, og lever dem til Pilot Bælgfiz ved Stålgrills Depot.", d="Jeg forbereder mig på at starte en mission for Belejringsbrigaden. Den er lang, og jeg skal proviantere Jetdamp med en måneds forsyninger. Så mens Stålgrill arbejder på min tank, kan du så ikke jage lidt for mig?\n\nJeg skal bruge noget pels til sengetøj og vildsvinekød til mad. Kød kan du få fra vildsvinene, og pels fra bjørnene... du finder dem begge på snemarkerne syd for Den Grizzlede Hule."},
  [318] = {n="Evigskinne", l="Hent et fad Evigskinne hos Rejold Byggøl i Brygnall-landsbyen.", d="Rejold Byggøl eksperimenterer med sine bryg. Nogle af dem smager godt, nogle dårligt, og nogle... ja, nogle vil fælde alle undtagen de hårdeste dværge.\n\nHan bor i Brygnall-landsbyen, vest for Kharanøs, og en af hans drikke, Evigskinne, er det, jeg vil have. Den holder mig varm, mens jeg er på den kolde vej.\n\nOg... den velsignede sag brænder så hedt, at jeg kan smide den i Jetdampens ovn for et ryk af kraft! Det lille trick har reddet mig ud af mere end én klemme!"},
  [319] = {n="En Tjeneste for Evigskinne", l="Dræb 6 Isklo-bjørne, 8 Ældre Klippevildsvin og 8 Sneleoparder, og vend derefter tilbage til Rejold Byggøl i Brygnall-landsbyen.", d="Jeg har et fad Evigskinne klar, men...kan du gøre mig en tjeneste? Brygnall-landsbyen kunne bruge en hjælpende hånd mod de vilde dyr, der strejfer rundt i de nærliggende sne. Nogle gange kommer de for tæt på.\n\nVi er ikke bange for disse bjørne, katte og vildsvin - ingen selvrespekterende dværg ville være det - men hvis du kan tage dig af dem for os, så får vi mere tid til vores håndværk og bryggeri."},
  [320] = {n="Tilbage til Bælgfiz", l="Giv fadet med Evigskinne til Pilot Bælgfiz ved Stålgrills Depot.", d="Her er dit fad med Evigskinne, <Name>. Og tak igen for jagten før."},
  [321] = {n="Lysssmede-jern", l="Undersøg vraget af Den Flyvende Fiskeørn i Vådlandene.", d="Skibsvragene ud for kysten her er den dødsdømte Tredje Flåde fra Kul Tirask, brændt og sænket af Røde Drager under den sidste Store Krig.\n\nFlåden kom fra Herrelande, men et skib, en alvisk Destroyer: Den Flyvende Fiskeørn, var med. Det fragtede en last Lysssmede-jern og sluttede sig til Tredje Flåde for beskyttelsens skyld. Ironisk nok sank det til de samme drager...\n\nNok historie. Den Flyvende Fiskeørn er forlist syd for Menetil-havnen. Hvis du finder Lysssmede-jernet der, så bring det til mig."},
  [322] = {n="Velsignet Arm", l="Tag kassen med Lysssmede-barrer til Grimand Elmøre i Stormvind.", d="Der er en dværgisk våbensmed i Dværgekvarteret i Stormvind, som kan smede med lysssmede-jern. Hans navn er Grimand Elmøre.\n\nJeg har pakket det jern, du fandt, i en kasse. Tag den med til Grimand og fortæl ham din historie. Jeg er sikker på, at han vil hjælpe en med en opgave som din og smede et våben til dig - et våben, der selv Morbent Ondt vil få til at bekymre sig!"},
  [323] = {n="At Bevise Sit Værd", l="Dræb 15 Skeletplyndrere, 3 Skeletheler og 3 Skeletvogtere, og vend derefter tilbage til Sven.", d="Morbent Ondt er en nekromancer og allieret med mørkeriderne. Jeg ville sætte dig op mod Morbent Ondts magt, men jeg sender ikke dig mod den modbydelige skurk, før jeg kender din styrke.\n\nDu har allerede bevist dit mod over for mig, men hvis du virkelig vil møde nekromanceren, så må du nu bevise din dygtighed over for hans håndlangere."},
  [324] = {n="De Tabte Barrer", l="Saml 5 Lysssmede-barrer, og vend derefter tilbage til Glorin Stålbryn i Vådlandene.", d="Efter at have grebet den ene lysssmede-barre fra den vandfyldte kiste, er det tydeligt, at mudderfiskene har stjålet resten. Jag mudderfisk-plyndrerne nær vraget af Den Flyvende Fiskeørn for at finde det tabte lysssmede-jern."},
  [325] = {n="Våbnet og Klar", l="Bring Morbents Svøbe til Sven i Skumringsskoven.", d="Her er våbnet mod den skurk, du talte om. Du er klar, <Name>. Held og lykke, og jeg glæder mig til din beretning om ære!"},
  [332] = {n="Vinbutiksreklame", l="Gå til Høne-vingården, og giv Suzetta Høna vinbilletten for en gratis flaske vin.", d="Hvis du taler med nogen om vin, så ved du, at vi Hønner sælger den bedste vin i Stormvind. Og vi er ikke langt væk, stadig i Handelsdistriktet langs byens dejlige kanaler.\n\nTag her, tag denne folder. Bring den til min søster Suzetta i vores butik for en gratis flaske af vores berømte pinot noir. Du vil ikke fortryde det!"},
  [333] = {n="Harlan Mangler Forsyninger", l="Gå til Kanal-skrædderens butik og giv Rema Skræder stofbestillingen fra Harlan Pose.", d="Vi har haft meget at lave på det seneste. Det ser ud til, at alle køber rustninger og solide klæder. Næsten, som om de venter en kold, hård årstid...\n\nMen det er fremtidige bekymringer. Min bekymring i dag er, at jeg løber tør for strikkede klæder at sælge. Jeg har brug for endnu et læs fra vores leverandør.\n\nHvis du kan tage denne bestilling med til Rema Skræder hos Kanal-skrædderen og Tilpasningsbutikken, ville jeg være yderst taknemmelig."},
  [334] = {n="Pakke til Thurmann", l="Gå til Larson Klædehandel i Stormvinds Magikerkvarter, og giv Thurmann Skræder hans syesæt.", d="Min søn Thurmann er lærling hos Larson Klædehandel i Magikerkvarteret. Han havde travlt i dag og glemte sine sakse og nåle. Jeg ved, at en dygtig <Class> som dig må have vigtige opgaver, men uden sine redskaber kan Thurmann ikke udføre sit lærlingearbejde!\n\nVær sød, <Name>. Kan du tage min søns syesæt med til ham? Larson Klædehandel er en af to tøjbutikker i Magikerkvarteret - den, der ligger længere inde, nær Magikerens Tårn."},
  [335] = {n="Et Ædelt Bryg", l="Zardeth Sortklo vil have, at du bringer ham en Tilloas Tåre fra Mørkeshire og en Bisamrod fra Vådlandene.", d="Lord Vishock skaber en del røre i Adelshuset. Han har fået øje på vores lille „etablissement” hernede og lobbyer for en fuld undersøgelse. Jeg har en plan for at holde Vishock „optaget”, men jeg får brug for din hjælp.\n\nDer vokser en blomst i Stalvans Have i udkanten af Mørkeshire. Denne lille hvide blomst er kendt som Tilloas Tåre. Jeg får også brug for en Bisamrod, som kun findes nederst ved vandfaldet langt under Stenhugget Dæmning i Vådlandene."},
  [337] = {n="En Gammel Historiebog", l="Returner bogen: Stormvinds Historie, til Stormvinds Bibliotek.", d="Selvom bogens omslag er ridset og overtrukket med mudder, kan ordene „Stormvinds Historie” stadig læses langs ryggen. Når man åbner bogen, er Stormvinds Biblioteks segl tydeligt stemplet på bogens første side.\n\nDet ser ud til, at nogen lånte denne bog og aldrig afleverede den..."},
  [338] = {n="De Grønne Bakker i Kvælerdorn", l="Saml de manglende sider fra manuskriptet De Grønne Bakker i Kvælerdorn. Når alle fire kapitler er færdige, skal de returneres til Barnil Stenkrukke.", d="Mester Jagtvarys bliver så ked af det, hvis han finder ud af det!\n\nHan betroede mig korrekturlæsningen af manuskriptet til sin roman, De Grønne Bakker i Kvælerdorn. Alt gik godt, men en stor vindstød blæste gennem lejren og spredte siderne overalt!\n\nJeg fik samlet de fleste sider, men mange ligger stadig spredt rundt i junglen. Saml siderne for at fuldføre hvert af de fire kapitler.\n\nJeg vil hjælpe dig med at sortere dem. Bring kapitlerne tilbage til mig, når du har alle fire."},
  [339] = {n="Kapitel I", l="Bring side 1, 4, 6 og 8 af Jagtvarys' De Grønne Bakker i Kvælerdorn til Barnil Stenkrukke for at fuldføre Kapitel I.", d="Kapitel I var ret fængslende! Mester Jagtvarys sætter scenen for historien og nævner sine jagtkammerater, inklusive mig!\n\nMen det er ikke det vigtige. Lad mig se, hvilke sider der stadig mangler. Det ser ud til, at side 1, 4, 6 og 8 stadig er derude et sted i junglen!"},
  [340] = {n="Kapitel II", l="Bring side 10, 11, 14 og 16 af Jagtvarys' De Grønne Bakker i Kvælerdorn til Barnil Stenkrukke for at fuldføre Kapitel II.", d="Kapitel II var fyldt til randen med spændende fortællinger om panter- og tigerjagt. Jeg kunne bare sparke mig selv for at lade siderne blæse væk!\n\nDet ser ud til, at jeg fik genfundet alle siderne undtagen side 10, 11, 14 og 16."},
  [341] = {n="Kapitel III", l="Bring side 18, 20, 21 og 24 af Jagtvarys' De Grønne Bakker i Kvælerdorn til Barnil Stenkrukke for at fuldføre Kapitel III.", d="Kapitel III var mit yndlingskapitel. Det fortæller om Ridder S. J. Erlgadin og Lady Krudtsnors første drab med et dværgisk gevær. Og slutningen af Kapitel III, ja, sikke en cliffhanger!\n\nDet ser ud til, at vi stadig mangler side 18, 20, 21 og 24 for at fuldende kapitlet. Disse sider er derude et sted. . ."},
  [342] = {n="Kapitel IV", l="Bring side 25, 26 og 27 af Jagtvarys' De Grønne Bakker i Kvælerdorn til Barnil Stenkrukke for at fuldføre Kapitel IV.", d="Ah, Kapitel IV; det store finale! Og for en slutning det var!\n\nVi mangler kun tre sider til dette kapitel. Vi skal bruge side 25, 26 og 27 for at samle Kapitel IV igen."},
  [343] = {n="Taler om Udholdenhed", l="Gå til Det Kongelige Bibliotek i Stormvinds Fæstning og tal med Milton Neg. Han kan finde den bog om metallurgi, som Broder Kristoff har brug for til sin tale.", d="Jeg holder en tale om Åndens Udholdenhed, og jeg vil gerne citere fra en bestemt bog om metallurgi - „Jernets Spændinger”. Et eksemplar af denne bog burde være i Det Kongelige Bibliotek, inde i Stormvinds Fæstning. Kan du hente den til mig? Hvis du gør det, så må Lysets velsignelser være med dig!\n\nDet Kongelige Bibliotek er meget stort, men hovedbibliotekaren, Milton Neg, kender hver hylde, som var den hans egen søn. Tal med ham, så henter han bogen til dig."},
  [344] = {n="Broder Paxton", l="Tal med Broder Paxton i Nordshire-klosteret.", d="Jernets Spændinger? Ja, jeg kender bogen. Ret god, skrevet af dværgeminearbejderen Margulf Blagg for et par årtier siden. Han brugte det meste af sin tid dybt inde i bjergene i Khaz Mødan og gravede malm. Klog fyr!\n\nMen hvor var jeg? Åh ja, Jernets Spændinger! Jeg er bange for, at bogen blev flyttet til Nordshire-klosteret. Klosterets biblioteksforvalter, Broder Paxton, ville lave en kopi af bogen til sine egne hylder.\n\nMen det var for måneder siden. Jeg undrer mig over, hvorfor det tager ham så lang tid..."},
  [345] = {n="Blækforsyninger", l="Tal med Formand Oslow i Søshire og bed ham om Rethban-jernmalm.", d="Jeg har tænkt på at færdiggøre min kopi af Jernets Spændinger, men...\n\nDu ser, jeg laver mit eget blæk til de bøger, jeg kopierer. Det er min egen opskrift; det løber ikke eller smører, og det tørrer meget hurtigt. Desværre tørrer det for hurtigt! Min sidste portion tørrede op, før jeg kunne færdiggøre kopieringsjobbet, og jeg har ikke haft mulighed for at lave mere blæk!\n\nFor at lave mere har jeg brug for Rethban-jernmalm fra Rødryg-bjergene. Formand Oslow i Søshire er min sædvanlige leverandør."},
  [346] = {n="Tilbage til Kristoff", l="Vend tilbage til Broder Kristoff på Katedralpladsen. Giv ham bogen Jernets Spændinger.", d="Nu hvor jeg er færdig med at kopiere bogen, er her originalen af Jernets Spændinger. Tak for din tålmodighed, og hvis du ser Milton, så sig til ham, at jeg beklager den lange forsinkelse."},
  [347] = {n="Rethban-malm", l="Saml 5 læs Rethban-malm, og bring det til Broder Paxton i Nordshire-biblioteket.", d="Rethban-malm er opkaldt efter manden, der først fandt den, Bart Rethbæk. Når den smeltes, er den ikke så stærk som jern, men dens malm har en mørk, flad farve, som nogle skrivere bruger i deres farvestoffer. Den findes i Rethban-hulerne, nord for her.\n\nVi har normalt en del på lager, men vi har for travlt med at forberede os på orkangreb til at samle noget. Og desuden... Rødryg-gnoldene bor nu i Rethban-hulerne, og deres trælle samler malmen selv.\n\nSå hvis du har brug for noget, må du selv hente det."},
  [350] = {n="Søg en Gammel Ven", l="Tal med Elling Trøsen i Stormvind.", d="At Marzøn ville kontakte et medlem af Defias og have forbindelser til Lescovær...\n\nNu hvor VanKløft og Tredd er dræbt, vil det være svært at se Lescovær bragt til rette, for dine beviser er intet uden deres vidneudsagn. Og det tager ikke engang højde for, at Lescovær er adelsmand og velforbundet. Det gør ham i praksis hævet over loven.\n\nDu får brug for anden hjælp. Jeg hader at gøre det, men der er en, jeg kender, som vil hjælpe os. Du finder Trøsen i byens Handelsdistrikt."},
  [353] = {n="Stormspids' Levering", l="Lever pakken til Stormspids til Bjergbestiger Stormspids i Modansøen.", d="Stormspids-klanen er en respekteret dværgeklan og er kendt for deres fine og kræsne smag. Så det er ingen overraskelse, at Gringer Stormspids, en bjergbestiger fra Jernsmede, bestilte et våben hos mig.\n\nVåbnet er færdigt, men... Bjergbestiger Stormspids er langt væk i det fjerne Modansøen. Hvis du planlægger at rejse nordpå, kan du så levere denne pakke til ham?\n\nMin sidste besked fra Bjergbestiger Stormspids sagde, at han er stationeret ved det nordlige vagttårn i Modansøen."},
  [354] = {n="Dødsfald i Familien", l="Bring Gregors Rester, Nissas Rester og Thurmanns Rester til Coleman Farding i Gryde-by.", d="Agamand-familien var den mest velstående familie i Tirisfals Lysninger. Jeg plejede at arbejde ved deres møller...før Pesten.\n\nDa Svøben først kom, befæstede Agamandene deres hjem og overtalte dem, der var ansat hos dem, til at blive og hjælpe med at forsvare dem. Vi var tåber, men i det mindste var vi loyale tåber.\n\nAgamandene, i deres stolthed, dømte os til de udøde. Og nu er de håndlangere for Svøben!\n\nTjen de Forladte ved at besejre Agamandene, der faldt for Pesten. Tjen mig ved at bringe mig deres rester."},
  [355] = {n="Tal med Sevrin", l="Tal med Dommer Sevrin i Gryde-by.", d="Du har givet mig resterne af Agamanderne, og tilfredsstillet min trang til hævn. Men Agamand-møllerne udgør en trussel mod alle de Forladte, ikke kun mod mig.\n\nJeg har talt med Dommer Sevrin om dine bedrifter mod Agamanderne, og han ønsker at tale med dig."},
  [356] = {n="Bagvagtens Patrulje", l="Dræb 8 Blødende Rædsler og 8 Vandrende Ånder, og rapportér derefter tilbage til Lindea i hendes lejr.", d="Forsvarerne på Bolværket, der beskytter Tirisfal mod Pestlandene, er i konstant alarmberedskab. Men nogle gange smutter Svøben forbi dem.\n\nVores succes ved Bolværket afhænger af en kamp på én front - vi kan ikke tillade et angreb bagfra, og vi kan heller ikke tillade, at forsvarernes forsyningslinje bliver skåret over.\n\nHjælp Bolværket. Patruljér mod øst og slå alle Svøben, du finder. Gør en særlig indsats ved Balnirs Gård mod øst. Den er blevet et tilflugtssted for indtrængende Svøben."},
  [357] = {n="Liskens Identitet", l="Bring Liskens Stavebog til Bethor Isskår i Undergrunden.", d="Der bor en lisk på øen i Klarvandssøen mod nord. Selvom han er en frit tænkende Forladt, mener han, at alle andre Udøde er Svøbe-slaver, og han får sine håndlangere til at angribe enhver, der nærmer sig ham.\n\nMen fordi han er en Forladt, vil dronningen have ham. Og hvis han er dygtig i Nekromanti, ville hans viden...være ret nyttig for os.\n\nFor at finde ud af hans identitet og hans talenter må jeg se hans stavebog. Snig dig ind i hans lejr, skaf den, og vend så tilbage til mig."},
  [358] = {n="Gravrøvere", l="Dræb Rådhud-gravrøvere og Rådhud-køtere.\n\nBring 8 Balsameringsichorer til Dommer Sevrin i Gryde-by.", d="Massegravene, sydvest for Garrens Spøgelseshule mod nord, blev lavet til at rumme det...imponerende...antal døde, Tirisfal led, da Pesten første gang kom.\n\nLegene i disse grave er hidtil blevet skånet for en udødelighed, men Svøben sender nu Rådhud-gnolde af sted for at samle ligene og bruge dem til at styrke deres hære. Dette må ikke tillades!\n\nDin opgave er todelt: Slå Rådhudderne ved Massegraven og Garrens Spøgelseshule, og indsaml fra dem den Balsameringsichor, der holder dem i live."},
  [359] = {n="De Forladtes Pligter", l="Tal med Dødevagt Lindea.", d="Jeg har brug for en frisk rapport fra vores Dødevagt-stationspost mod øst.\n\nJeg må vide, om flere Svøbe-styrker er sluppet forbi Bolværket og ind i Tirisfal. Vores årvågenhed ved grænsen til Pestlandene skal opretholdes - vi kan ikke lade Svøben få et stærkere fodfæste her!\n\nRejs sydpå ad vejen, og drej derefter mod øst ved vejkrydset til stationsposten. Tal med Dødevagt Lindea. Hun har de oplysninger, jeg har brug for."},
  [360] = {n="Tilbage til Dommeren", l="Vend tilbage til Dommer Sevrin i Gryde-by.", d="Vend nu tilbage til Dommer Sevrin med de oplysninger, jeg gav dig. Han vil have dem så hurtigt som muligt, så vær hurtig.\n\nOg hvis du ser Svøben på vejen tilbage, så slå dem ned - vi kan ikke tillade, at de vandrer rundt i vores lande uden modstand."},
  [361] = {n="Et Brev Uafleveret", l="Find Yvette Farding, og lever hende brevet fra Thurmann Agamand.", d="Dette er et brev skrevet af Thurmann, den ældste søn af Gregers Agamand. Det er adresseret til en Yvette Farding, men det ser ikke ud til at være nået frem til hende..."},
  [362] = {n="De Hjemsøgte Møller", l="Dræb Djævlin Agamand, og bring Djævlins Rester til Coleman Farding i Gryde-by.", d="Djævlin Agamand var den yngste af to sønner i Agamand-familien, og i livet kunne de to ikke være mere forskellige. Thurmann var høj og blid, mens hans yngre bror var svag og skarptungen.\n\nDa Agamand-møllerne faldt for Pesten, blev jeg ikke overrasket over at høre, at Djævlin var hurtig til at bukke under. Hans gale snakken kan stadig høres nær vejen, der fører til Agamand-møllerne.\n\nJeg samler resterne af Agamanderne, og jeg vil have stakkels Djævlin. Find ham, tilintetgør ham, og bring mig hans knogler."},
  [363] = {n="Brutal Opvågning", l="Tal med Skyggepræst Sarvin.", d="På tide, at du vågner. Vi var klar til at kaste dig i ilden sammen med de andre, men det ser ud til, at du klarede det.\n\nJeg er Morder, vogteren af graven i Dødsklokken. Og du er ikke længere Liskekongens slave.\n\nTal med Skyggepræst Sarvin i kapellet ved foden af bakken, han vil fortælle dig mere om, hvad du må vide."},
  [364] = {n="De Tankeløse", l="Skyggepræst Sarvin vil have dig til at dræbe 8 Tankeløse Zombier og 8 Elendige Zombier.", d="Vi Forladte er i krig med Liskekongens hær, Svøben: nekromantisk oprejste udøde hære, onde bæster fra nord og pinte spøgelser.\n\nDen nordlige del af landsbyen er blevet overrendt af De Tankeløse, og de må tilintetgøres. Tilintetgør dem, vis dem ingen nåde, uanset hvor vore tidligere brødre og søstre måtte være. De Faldne er intet andet end Liskekongens slaver."},
  [365] = {n="Sorgens Marker", l="Stjæl 10 græskar fra gården mod vest, lige nord for Dødsklokken, og tag dem med til Apoteker Johan i Gryde-by.", d="Hvad har vi her? Du ligner en spæd <Class>. Hvis du håber at bevise dig over for Den Mørke Dame, må du lære de Forladtes måder.\n\nMod vest finder du en gård. Mennesker inficerer landet som skimmel på et rådnende lig. Og endnu værre patruljerer De Skarlagenrøde Korstog i nærheden fra deres tårn. Lær de skum en lektie, og stjæl 10 af deres dyrebare græskar.\n\nNår du har 10, skal du tage dem med til Apoteker Johan i Gryde-by."},
  [366] = {n="Bogen Tilbage", l="Returnér Gunners Stavebog til ham på øen Gunners Tilflugt.", d="For længe siden var Gunner og jeg, sammen med den nu Svøbe-nekromanceren Thule Ravnekloe, venner og elever i Kirin Tårn - et magikersamfund i Dalarn.\n\nGunner og jeg faldt begge for Pesten, men jeg troede, at han enten forblev død, eller blev rejst op i Liskekongens rækker. Det er godt at vide, at han er fri.\n\nVi må have ham. Jeg har lagt en besværgelse på hans bog, som, når han ser den, vil vise ham, at også jeg er fri for Liskekongen. Når han ved dette, er mit håb, at han vil slutte sig til os."},
  [367] = {n="En Ny Pest", l="Apoteker Johan i Gryde-by vil have, at du samler 5 hætteglas med Mørkehund-blod.", d="Lady Silvanas har kaldt Det Kongelige Apotekerselskab til samling. Den Mørke Dame mener, at vores viden, kombineret med den nyfundne magi, vil være nøglen til Arthæus' undergang. Hun har udfordret os til at brygge en ny pest, en pest dødeligere end nogen sygdom på Azeroth. Denne nye sygdom vil bringe Arthæus' Svøbe-hær til ruin.\n\nMine studier viser, at dyrenes blod kan vise sig at være nøglen. Bring mig 5 hætteglas med Mørkehund-blod, så jeg kan teste min teori."},
  [368] = {n="En Ny Pest", l="Apoteker Johan fra Gryde-by har brug for 5 Ondskabsfinne-skæl fra Mudderfisk i Tirisfal Lysninger.", d="Mens du indsamlede prøver til mig, førte mine eksperimenter mig til at indse, at der kræves flere reagenser, for at denne nye sygdom kan sprede sig ordentligt. At forgifte et ulykkeligt offer er børneleg. At plage en hel verden viser sig at være lidt mere kompliceret.\n\nJeg skal bruge 5 Ondskabsfinne-skæl fra Mudderfisk i nærheden. Du finder væsnerne langs kysten mod nord eller mod vest."},
  [369] = {n="En Ny Pest", l="Apoteker Johan i Gryde-by vil have, at du bringer ham 4 prøver af gift fra en Ondskabsfuld Natnet-edderkop.", d="Mens du var ude og samlede, fandt jeg noget gammel tekst i en af mine bøger, som viser, at en gammel pest udslettede tusindvis af uskyldige ofre. Senere opdagede man, at det dødbringende middel i pesten blev bevaret gennem giften fra Natnet-edderkopper.\n\nBring mig noget gift fra en Ondskabsfuld Natnet-edderkop for at fuldføre dette eksperiment. Jeg vil se, om den smitsomme del af giften virker sammen med min nye blanding. Rygtet lyder, at edderkopperne kan findes i de østlige Tirisfal Lysninger."},
  [370] = {n="Krig Mod De Skarlagenrøde Korstog", l="Eksekutor Zygant i Gryde-by vil have, at du dræber Kaptajn Perrinne, 3 Skarlagenrøde Fanatikere og 3 Skarlagenrøde Missionærer.", d="De strategiske dokumenter fra Eksekutor Arrin indeholder alle de detaljer, vi har brug for, for at udrydde menneskeskabelsen fra landene. Ifølge oplysningerne har De Skarlagenrøde Korstog tildelt Kaptajn Perrinne og en brigade det ødelagte tårn sydvest for Gryde-by.\n\nDræb Perrinne sammen med 3 Fanatikere og 3 Missionærer, og rapportér tilbage til mig."},
  [371] = {n="Krig Mod De Skarlagenrøde Korstog", l="Eksekutor Zygant i Gryde-by har sat dig til at dræbe Kaptajn Vaskon og 5 Skarlagenrøde Munke.", d="Vi er stadig i krig, og De Skarlagenrøde Korstog vokser i styrke. Rapporten, Eksekutor Arrin sendte mig, viser, at Skarlagenrøde Korsfarere har plyndret fra det ødelagte tårn i sydøstlige Tirisfal nær Balnirs Gård under Kaptajn Vaskons kommando.\n\nDræb Vaskon sammen med 5 Skarlagenrøde Munke. Det bør blive et ødelæggende slag mod Korstoget!"},
  [372] = {n="Krig Mod De Skarlagenrøde Korstog", l="Eksekutor Zygant i Gryde-by vil have, at du myrder Kaptajn Melrakk og hans to livvagter.", d="Skarlagenrøde Korsfarere har plyndret fra det ødelagte tårn i det nordlige Tirisfal, forbi Faols Hvile. Ifølge de oplysninger, vi har, står en hensynsløs befalingsmand ved navn Kaptajn Melrakk i spidsen for denne onde flok.\n\nJeg betror dig nu en særlig og farlig opgave. Dræb Melrakk og hans to livvagter i Den Mørke Dames navn."},
  [373] = {n="Det Uafsendte Brev", l="Lever brevet til Stadsarkitekt Baros Alexston i Stormvind.", d="Da du ransagede Edwin VanKløfts person, fandt du blandt andre ting et uafsendt brev. Det er adresseret til Baros Alexston, Stormvinds Stadsarkitekt, Rådhuset, Katedralpladsen.\n\nDet ser ud til at være skrevet og forseglet for nylig."},
  [374] = {n="Bevis for Død", l="Bring 10 Skarlagenrøde Insignia-ringe til Dødevagt Burgess i Gryde-by.", d="Eksekutor Zygant fortæller mig, at du har været ude og dræbe Skarlagenrøde Korsfarere. Tirisfal Lysninger vrimler med dem.\n\nVarimatras, løjtnant under Den Mørke Dame, sørger personligt for, at Azeroths skum, menneskeracen, bliver udslettet til intethed. Her i Tirisfal Lysninger står vi over for en særlig irriterende slags mennesker: De Skarlagenrøde Korstog.\n\nDrag ud og før et angreb mod De Skarlagenrøde Korstog, <Class>. Bring mig tilbage 10 Skarlagenrøde Insignia-ringe som bevis på din loyalitet over for Varimatras og Den Mørke Dame."},
  [375] = {n="Dødens Kulde", l="Bring fem Skumringsflagermus-pelse og noget Grov Tråd til Gretchen Dødmar i Gryde-by.", d="Det er så koldt nu. Udødelighedens Pest kryber gennem mine årer som en isslange. Den Tankeløse Tilstand vil snart ramme mig. Men ingen dømt skæbne vil forhindre mig i at tjene vores Mørke Dame. Da kaldet lød, syede jeg ligsække til de faldne soldater i Silvanas' mægtige hær.\n\nNu ryster mine hænder af kulden. Hvis du ville bringe mig fem Skumringsflagermus-pelse og noget Grov Tråd, kunne jeg sy et tæppe til mig selv. Hjælp mig, <Name>, så jeg kan fortsætte med at tjene sagen."},
  [376] = {n="De Fordømte", l="Novice Elret kræver 6 Ådselæder-poter og 6 Skumringsflagermus-vinger.", d="Mine pligter omfatter at passe vores sårede krigere, sy rustninger og tøj og hjælpe Skyggepræst Sarvin med alt andet, han måtte have brug for.\n\nAf det, jeg kan se, bliver du også indkaldt til hans tjeneste... at jage De Tankeløse, hvis jeg kender hans sind. Nå, hvis du gerne vil blive i ét stykke - og jeg tvivler ikke på, at det vil du - kan jeg måske hjælpe. Jeg løber tør for poter og vinger, og hvis du bringer mig nogle, finder jeg noget rustning til dig. Du finder et godt antal ulve og flagermus mod syd."},
  [377] = {n="Forbrydelse og Straf", l="Rådmand Mølleskæg fra Mørkeshire vil have, at du bringer ham hånden af Dekstren Vagt.", d="Som om forsømmelsen af Skumringsskovens indbyggere ikke var slem nok, spytter Adelshuset nu Mørkeshire-rådet lige i øjnene med deres beslutning om at fængsle Dekstren Vagt i Stormvind i stedet for at halshugge skurken, som Lord Ebenlås dømte ham til.\n\nVagt blev taget i at sælge lig fra kirkegården til Morbent Ondt, en forbrydelse, der straffes med døden. Alligevel hævder Stormvind, at Vagt er deres fange.\n\nMyrd Vagt i Fængslet - bring mig hans hånd - og jeg vil belønne dig."},
  [378] = {n="Vreden Løber Dybt", l="Broget Garmason vil have Kam Dybfurors hoved bragt til ham i Dun Mødr.", d="Du har bevist din loyalitet over for Kong Magni, <Class>. Og dit had til Mørkjern-skummet er lige så stort som mit eget.\n\nDer er en opgave, jeg selv ønsker at gennemføre, men jeg er bundet af ære til at blive hos Langfletten. Men Rogo har indsamlet efterretninger, der beviser, at Kam Dybfuror var medsammensvoren i angrebet på Thandol-spændet. Det var efter Dybfurors planer, at Langfletten mistede sin slægt.\n\nDybfuror holdes af politiske årsager fanget i Fængslet. Jeg vil have ham død, <Name>. For Langfletten! Bring mig hans hoved!"},
  [380] = {n="Natnet-Hulen", l="Eksekutor Arrin vil have, at du dræber 10 Unge Natnet-edderkopper og 8 Natnet-edderkopper.", d="En af vores største kampe er at skaffe de naturlige ressourcer, vi har brug for for at overleve. Guld var knapt selv på højdepunktet af Alliancens magt.\n\nDer er en guldmine mod nordvest, som er blevet overrendt af edderkopper. Vi har brug for guld fra minen, men vi kan ikke rigtig hente det, mens edderkopperne kryber rundt derinde. Jeg har ikke meget mandskab at afsætte til opgaven, så vi må bare gøre det lidt efter lidt.\n\nTag derop og se, hvad du kan gøre for os, <Name>."},
  [381] = {n="De Skarlagenrøde Korstog", l="Bring Eksekutor Arrin 12 Skarlagenrøde Armbånd fra Skarlagenrøde Konvertitter og Skarlagenrøde Novicer.", d="Du bliver glad for at høre, at vi tilsyneladende gør fremskridt i minen, og det skyldes i ikke ringe grad dine bestræbelser. Nu kan vi rette blikket mod andre bekymringer.\n\nMine spejdere har meldt, at en afdeling af de Skarlagenrøde Korstog slår læger lidt sydøst herfra. De Skarlagenrøde Korstog er en fordærvelig organisation, der jager os, og de hviler ikke, før hver eneste utøde--Liskekongens Svøbe eller ej--er udslettet. Vi må slå først!\n\nVær forsigtig, for deres unhellige nidkærhed gør dem til farlige modstandere."},
  [382] = {n="Den Røde Budbringer", l="Dræb Meven Kørgal, budbringeren, i Korsfarerlejren, og bring derefter enhver information, du finder, tilbage til Eksekutor Arrin.", d="Rapporter fra mine overordnede i Gryde-by tyder på, at en agent fra de Skarlagenrøde Korstog blev sendt fra Det Skarlagenrøde Kloster og hertil til Dødsklokken. Ifølge rapporterne har budbringeren vigtige oplysninger på sig. Jeg har ikke flere detaljer, men uanset hvad det er, må vi have det!\n\nDu er den mest kvalificerede person, jeg har at sende, <Name>. Find den budbringer og bring mig alle de oplysninger, du kan finde."},
  [383] = {n="Vitale Efterretninger", l="Lever Skarlagenrøde Korstog-dokumenterne til Eksekutor Zygant i Gryde-by.", d="Disse skal bringes til min overordnede, Eksekutor Zygant, i Gryde-by. Med disse oplysninger kan vi give de Skarlagenrøde Korstog et afgørende slag. Dine tjenester har været nyttige her i Dødsklokken, men jeg har brug for nogen til at levere dette til Zygant, og jeg tror, han kan finde mere passende arbejde til dig.\n\nTag vejen nord ud af Dødsklokken. Kort efter at have passeret ind i selve Tirisfal, når du et vejkryds. Tag den østlige gren, og fortsæt mod øst. Undervejs passerer du Koldhjerte-herregården."},
  [384] = {n="Ølbestrøgne Vildsvin-ribben", l="Ragnar Tordenbryg i Kharanøs vil have 6 Klippevildsvin-ribben og en krus Rapsodi-malt.", d="Intet af min kros gæster nyder mere end nogle Ølbestrøgne Vildsvin-ribben! Det eneste problem er, at den lokale fanger, der plejede at bringe mig forsyninger, meldte sig til Kongens Hær for at hjælpe med krigen på Alliancens front.\n\nMon du kan hjælpe mig? Hvis du bringer mig seks klippevildsvin-ribben og en Rapsodi-malt fra kroen her, giver jeg dig familieopskriften på mine berømte Ølbestrøgne Vildsvin-ribben, for ikke at tale om en gratis smagsprøve! Hemmeligheden ligger i malten!"},
  [385] = {n="Krokolisk-jagt", l="Skaf 5 stykker Krokolisk-kød og 6 Krokolisk-skind til Marek Jernhjerte ved Fjernvandrer-logen.", d="Mange jægere lokkes til Modansøen for at jage vores berømte krokodilleøgler. Der er altid handlende, der søger krokolisk-skind til klæder eller rustninger, og der er også nogle, der nyder smagen af kødet.\n\nVi driver en vis handel med det, men ikke en stor en, for krokoliskerne er rovdyriske og har forskanset sig på øerne i søen. Men lad mig ikke afskrække dig, det er en fornøjelse at brydes med bestiens kæber.\n\nJa, en gang..."},
  [386] = {n="Hvad Der Går Rundt...", l="Bring hovedet af Targorr den Frygtede til Vagt Berton i Søshire.", d="Targorr den Frygtede tjente under Gath'Ilsnavs som øverste bøddel. Hans metoder var hensynsløse, selv efter snavsede orkers standarder. Mænd, der kæmpede tappert for at forsvare riget, blev torteret efter hans lune. Nu sidder han i Fængslet og venter på henrettelse. Men noget er galt. En af de bureaukratiske adelsmænd har sat en blokering på hans henrettelse. Jeg er sikker på, at der er snyd på spil.\n\nSæt en stopper for Targorr den Frygtede, <Name>. Rejs til Fængslet og halshug ham, før svindelen rammer os."},
  [387] = {n="Slå Oprøret Ned", l="Fangevogter Thelvand fra Stormvind vil have, at du dræber 10 Defias-fanger, 8 Defias-straffefanger og 8 Defias-oprørere i Fængslet.", d="Oprøret må slås ned! Jeg har brug for din hjælp. Hvis det spreder sig, at fængslet er overrendt, mister jeg mit job! Dette er et tilfælde af snyd, hvis der nogensinde har været ét. Men det vigtigste nu er at tvinge disse fanger til underkastelse for Stormvinds sikkerhed.\n\nStraffen for oprør er døden. Dræb nogle af disse afvigere! Det burde få tingene under kontrol."},
  [388] = {n="Blodets Farve", l="Nikova Oprørsen fra Stormvind vil have, at du samler 10 Røde Uldhalstørklæder.", d="Bitterhed løber gennem mine årer som en kold flod. Mit barnebarn, Mak, var sådan en god dreng. Blot 14 år gammel. Da hæren blev sendt til fronten, greb Mak til våben for at forsvare byen. Han var vagt i Fængslet, hvor Defias-banden sidder inde. Mak irettesatte nogle af fangerne, fordi de flåede deres uldtæpper i stykker for at lave halstørklæder, et symbol på deres bande. For det blev Mak stukket i ryggen.\n\nJeg vil have hævn. Bring mig 10 af deres kostbare Uldhalstørklæder. De har blodets farve."},
  [389] = {n="Bazil Tredd", l="Tal med Fangevogter Thelvand i Fængslet.", d="VanKløft og jeg var medlemmer af Stenhuggerklanen. Vores hovedprojekt var at genopbygge Stormvind efter krigen.\n\nDa vi var færdige med vores pligter, blev vi snydt. Adelsmændene nægtede at betale os for vores arbejde. Nogle af de ældre stenhuggere fik tilbudt statslige job, men VanKløft afslog det af loyalitet over for alle stenhuggerne. Han anstiftede et oprør og forlod byen og svor hævn.\n\nHans løjtnant, Bazil Tredd, ved måske mere om VanKløfts planer. Han sidder fange i Fængslet."},
  [391] = {n="Fængsels-optøjerne", l="Dræb Bazil Tredd og bring hans hoved tilbage til Fangevogter Thelvand i Fængslet.", d="Lad os få én ting på det rene, <Name>: Jeg stoler ikke på dig. Men med situationen, som den er, gør du sikkert ingen forskel.\n\nSå sådan skal det være: Gå derned og tal med Tredd. Hvis du virkelig er på vores side, så dræb ham og bring mig hans hoved, når jobbet er gjort. Og hvis det viser sig, at du er på hans side, og ikke kommer tilbage... når vi finder dig, dør du sammen med resten af maddiker."},
  [392] = {n="Den Nysgerrige Besøgende", l="Bring den Forseglede Beskrivelse af Tredds Besøgende til Baros Alexstøn i Stormvind.", d="I Tredds første fængselsår havde han aldrig nogen besøgende. Jeg regnede med, at han ikke længere var til nytte for Broderskabet, og at de havde forladt ham.\n\nUnder alle omstændigheder ændrede det sig for et par måneder siden; han begyndte at få regelmæssige besøg... en gang, måske to gange om ugen. Det var en mærkelig mand--den stille type. Jeg havde mine mistanker, men alle hans papirer var i orden.\n\nHans dokumenter påstod, at han hed Mælik; her er hans beskrivelse. Jeg tror ikke, han kommer på besøg hos Tredd igen."},
  [393] = {n="Fortidens Skygge", l="Bring den Forseglede Beskrivelse af Tredds Besøgende til Mester Mathias Skaw i Stormvind.", d="Jeg har virkelig ingen anelse, <Name>. Der er en anden, der måske kan hjælpe dig, og det sker, at han skylder mig en tjeneste--ja, lad os ikke komme ind på det. Mester Mathias Skaw fra SI:Syv kan findes i kasernen i Gamlebyen. Skaw har sin tommelfinger på de fleste skumle eller snedige forretninger i byen.\n\nHvis nogen ved det, er det ham."},
  [398] = {n="EFTERSØGT: Maddikøje", l="Dræb Maddikøje og vend tilbage til Eksekutor Zygant i Gryde-by med hans pote som belønning.", d="Eftersøgt: Maddikøje!\n\nEt ondskabsfuldt udyr, selv efter gnold-standarder. Maddikøje er dømt til døden for sine forbrydelser mod De Forladte. Denne foragtelige skurk har stjålet lig til brug for Liskekongens hær. Maddikøje blev senest set plyndre landene nær Garrens Spøgelseshule nord for Gryde-by.\n\nByen Gryde-by udlover hermed en belønning til den dygtige sjæl, der kan gennemføre henrettelsen. Vis Eksekutor Zygant skurkens pote, når gerningen er udført.\n\nNåde er for de svage."},
  [399] = {n="Ydmyge Begyndelser", l="Gå til Baros Alexstøns hus i Vestfald og søg efter hans kompas, og giv det derefter tilbage til ham på Katedralpladsen i Stormvind.", d="Det føles som en evighed siden, jeg var dreng og arbejdede på gården i Vestfald. Man siger, at man aldrig kan vende tilbage, og det er sandt. Dobbelt så sandt i mit tilfælde, for min families hjem er blevet brændt ned og overtaget af tyve.\n\nJeg har talt med min far om skæbnen for nogle af mine ejendele, deriblandt mit første kompas. Han kunne ikke redde dem. Men han siger også, at de burde være gemt væk på gården.\n\nDu finder Alexstons Gård vest for Vagtbakken. Måske kunne du tage derud og hente det til mig?"},
  [400] = {n="Værktøj til Stålgrill", l="Lever Stålgrills Værktøj til Beldin Stålgrill.", d="Beldin Stålgrill ejer det lokale værksted, og han er den bedste belejringsvåben-tekniker, der findes! Men han er ikke tilgivende over for sit værktøj. Jeg sværger, at han næsten knækker flere lysbue-skruenøgler, end vi kan levere til ham!\n\nVi har lige opfyldt hans seneste ordre på værktøj. Hvis du leverer det til ham, er jeg sikker på, at han gør det umagen værd.\n\nHans værksted, Stålgrills Depot, ligger lige nordøst for Kharanøs. Og det er et lokalt tilholdssted for veteran-piloter af belejringsvåben, så hold øjnene åbne for muligheder, mens du er der."},
  [401] = {n="Vent på Sirra", l="Vent et øjeblik, og tal derefter med Sirra Von'Indig igen.", d="Jeg er næsten færdig med at oversætte det brev. Kom tilbage om et par øjeblikke, så burde jeg være færdig."},
  [403] = {n="Bevogtet Tordenbryg-fad"},
  [404] = {n="En Rådden Opgave", l="Bring 7 Råddne Klør til Dødevagt Dillinger i Gryde-by.", d="Liskekongens Svøbe har sivet ind i Tirisfal Lysninger og har inficeret området vest for Gryde-by, nær den gamle bro.\n\nTag derud og slå de rådne døde og hærgede ligene tilbage, du finder. Spred deres knogler og bring deres rådne klør tilbage, så belønner Dødevagterne dig."},
  [405] = {n="Den Fortabte Lich", l="Overrækker Sevrins Ordrer til Bethor Isskår i Undergrunden.", d="Bethor Isskår, en højtstående og magtfuld magiker i Undergrunden mod syd, befaler mig at sende ham en agent med bevist værdi mod Svøben. Du, <Name>, vil være denne agent.\n\nOverræk disse ordrer til Bethor. Han vil så instruere dig i din mission. Jeg kender ikke detaljerne, men den handler om at rekruttere en vildfaren Lich. Og den bliver farlig.\n\nSå gør dig klar, <Class>. Du må ikke fejle.\n\nDu finder måske Bethor i Magikerkvarteret i Undergrunden."},
  [407] = {n="Sorgens Marker", l="Tag det Forgiftede Græskar til den Fangede Skarlagenrøde Fanatiker, der holdes i kælderen på Galgeenden Kro.", d="Harmløse græskar, ikke sandt? Sådan ser det i hvert fald ud. Hvis vi skal besejre Arthæus' fremstød fra nord og menneskenes plage fra syd, må vi begynde at indse de fulde muligheder i vores gave af udødelighed.\n\nMed lidt snilde bliver et simpelt græskar til en agent for vores Mørke Dame. Dette græskar, forgiftet med min nyeste formel, vil vise sig at være en ret god behandling.\n\nEn skarlagenrød fanatiker mere er blevet fanget og holdes i kælderen på Galgeenden Kro. Tag dette græskar til tossen."},
  [408] = {n="Familiekrypten", l="Dræb 8 Klagende Forfædre og 8 Rådnende Forfædre.\n\nDræb Kaptajn Dargol, og bring hans kranium til Dommer Sevrin i Gryde-by.", d="Agamand-møllerne er blevet et fodfæste for Svøben. Deres stærkeste punkt er Agamand-familiens Krypt, hvor deres lokale militære leder, et skelet ved navn Kaptajn Dargol, har sit hovedkvarter. Med nekromanti har han genopvakt Agamands forfædre og planlægger at bruge dem mod os.\n\nDette kan ikke tolereres, og du må stoppe det. Rejs til Agamand-familiens Krypt og besejr de genopvækkede Agamand-forfædre.\n\nOg bring mig Kaptajn Dargols kranium."},
  [409] = {n="Bevis Loyalitet", l="Skaf et Kaldelys.\n\nKald Lilith Nefara frem og dræb hende.\n\nVend tilbage til Gunner på hans ø.", d="Du siger, at du ikke er bundet af Liskekongens vilje, og fortryllelsen Bethor lagde på min bog bekræfter det. Men før jeg tror på dig, må jeg have bevis for, at du er Svøbens fjende.\n\nDer er et gammelt, blodigt alter lige ud for denne øs sydlige kyst. Det bruges af en mægtig Svøben-agent, Lilith Nefara.\n\nTag et Kaldelys fra kassen her. Tænd det på alteret, så vågner Lilith. Dræb Lilith, og jeg vil tro, at du er Liskekongens fjende."},
  [410] = {n="Den Sovende Skygge"},
  [411] = {n="Den Fortabte Lich Vender Tilbage", l="Bring Nether-ædelstenen til Bethor Isskår i Undergrunden.", d="Tag denne Nether-ædelsten med til min gamle kammerat Bethor. Den lader os kommunikere ... og jeg har meget at fortælle ham."},
  [412] = {n="Operation Rekombobulering", l="Bring Razzle Sprydkæde i Kharanøs 8 Restabiliseringshjul og 8 Gyromekaniske Tandhjul.", d="Ved nærmere analyse af situationen i Nisseborgen må det fremgå, at vi ikke blot slog trogg'erne fejl, men også fik de fleste gnomer forvandlet til grufulde, hjernedøde, ondsindede spedalske gnomer.\n\nOzi og jeg planlægger at vende den forfærdelige spedalskhed med vores nyeste opfindelse: Rekombobuleringsmaskinen. Maskinen er næsten færdig, men vi har desperat brug for nogle Restabiliseringshjul og Gyromekaniske Tandhjul. Hent nogle fra de spedalske gnomer uden for Nisseborgen til os."},
  [413] = {n="Glimmer-Stout", l="Tag Tønden med Glimmer-Stout til Bjergbestiger Byggøl.", d="Jeg vil gerne have min bror Velart til at smage min nye Glimmer-Stout. Han er Bjergbestiger og står vagt i det sydlige vagttårn, et af to tårne ved grænsen til Modansøen.\n\nHan er måske ikke bryggermester som resten af os Byggøl'er, men han elsker sine drikke, og jeg ved, at han vil kunne lide denne her.\n\nKan du bringe ham denne Tønde Glimmer-Stout for mig?"},
  [414] = {n="Stout til Kadrel", l="Tag Fadet med Glimmer-Stout til Bjergbestiger Kadrel.", d="Jeg har drukket mere af den Glimmer-Stout min bror lavede - det er fantastisk stof! Jeg vil have en anden Bjergbestiger til at smage den. Han hedder Kadrel, og han patruljerer normalt vejen gennem Tælsamar i Modansøen.\n\nFor at komme til Tælsamar skal du gå sydøst gennem tunnelen, og så dreje mod nordøst, når stien deler sig i en vej. Følg den vej lige ind i Tælsamar.\n\nGiv Bjergbestiger Kadrel dette fad Glimmer-Stout, og hør hvad han synes!"},
  [416] = {n="Rottejagt", l="Bring 12 Tunnelrotte-ører til Bjergbestiger Kadrel i Tælsamar.", d="Vi har et virkelig plageproblem mod vest. Tunnelrotte-kobolder er flyttet ind i forbjergene, har slået lejr i huler og forurener vores land med deres svineri!\n\nVi vil have dem udryddet. Jag dem, bring mig deres ører, og tjen deres dusør.\n\nDu finder tunnelrotte-kobolder og deres huler vest for Tælsamar, spredt langs bjergsiden."},
  [418] = {n="Tælsamar Blodpølser", l="Bring 3 stykker Bjørnekød, 3 Vildsvin-tarme og 3 Edderkoppe-ichor til Vidra Ildsten i Tælsamar.", d="Her i Tælsamar er der aldrig mangel på sultne maver, børn der løber ind og ud, arbejdere fra udgravningen der kommer hjem efter en hård dags arbejde. Vi er berømte for vores blodpølser - jeg regner ikke med, at du nogensinde har smagt dem?\n\nNej? Tja, her omkring må du arbejde for dit måltid, og tro ikke, bare fordi du er en fin <Class>, at du bliver undtaget.\n\nJeg skal bruge bjørnekød, vildsvin-tarme til tarmene og edderkoppe-ichor til krydderi. Skaf mig noget af det, og lad Vidra stå for madlavningen!"},
  [420] = {n="Senirs Observationer", l="Lever Grelins rapport til Senir Hvidskæg i Kharanøs.", d="Troggs i tunnelen er yderst fjendtlige og har ingen betænkeligheder ved at angribe rejsende i tunnelen. Du virker hård nok dog, så du burde nok være i sikkerhed.\n\nVejvisning? Hvis du vil tale med Senir, finder du ham i Kharanøs.\n\nFind vej gennem tunnelen, og når du kommer ud på den anden side, så bare følg vejen - den løber lige ind i Kharanøs."},
  [421] = {n="Bevis Din Værdi", l="Dalar Morgenvæver ved Gravkammeret vil have dig til at dræbe 5 Månevrede Hvidskalpe.", d="Lady Silvanas har betroet Varimatras erobringen af de menneskelige og dværgiske lande mod syd.\n\nMen den tåbe Arugel - kvaksalver fra Dalarn og nu forbandet udyr fra Skyggetandsborgen - lod sin hensynsløse magi hærge den strategiske højborg i Sølvfyrreskoven.\n\nJeg har brug for en, der er dygtig i kampens kunst, til at hjælpe med at rydde op i Arugels rod. Bevis dig selv for mig ved at dræbe 5 Månevrede Hvidskalpe. De ynkelige bæster findes ofte lige uden for vejen, nede ad bakken."},
  [422] = {n="Arugels Dårskab", l="Hent Arugels Middel til Dalar Morgenvæver ved Gravkammeret.", d="Hvordan Arugel fik adgang til Kirin Tårn, er mig en gåde. Hans kendskab til besværgelser var lige så gennemsigtigt som en sprunget glaskugle.\n\nDet vigtige nu er at lære præcis, hvilken magi Arugel brugte, så jeg kan vende den imod ham og sikre Sølvfyrreskoven for Den Mørke Dame.\n\nArugel opholdt sig først på hvedegården lige nord for broen. En af Dødsstalkerne så nogle besværgelsesbøger, men kunne ikke sikre dem. Hent mig den besværgelse, der er mærket Arugels Middel, fra disse bøger."},
  [423] = {n="Arugels Dårskab", l="Bring 6 Glubende Lænker og 3 Mørkesjæl-lænker til Dalar Morgenvæver ved Gravkammeret.", d="Efter at have undersøgt Arugels arbejde blev mine værste mistanker bekræftet. Den gamle klaphat var ikke kvalificeret til at rense natpotter i Dalarn, endsige repræsentere Kirin Tårn i dens mest desperate time. Tåber!\n\nArugel brugte fortryllede genstande til at forstærke sin svage magi. Jeg må undersøge disse genstande på egen hånd. Drag af sted og slå Månevrede Glubende og Månevrede Mørkesjæle ihjel, indtil du har samlet nok af deres fortryllede lænker til min forskning. De onde skabninger er set mod nord og øst."},
  [424] = {n="Arugels Dårskab", l="Dræb Grimson den Blege og bring hans hoved til Dalar Morgenvæver ved Gravkammeret.", d="Det vil faktisk tage længere tid, end jeg havde regnet med, at afdække de mørke hemmeligheder bag de fortryllelser, Arugel brugte.\n\nMen i mellemtiden har jeg brug for, at du tager dig af et mindre problem, vores Mørkestalkere har opdaget. Det ser ud til, at Arugel lod sin magi brede sig til Dybe Elm-minen i bakkerne mod sydøst.\n\nMinen ville vise sig at være en stor ressource for Varimatras' fremrykning.\n\nJeg vil have dig til at halshugge minens besmittede formand, Grimson den Blege. Med hans død skal minen være vores."},
  [425] = {n="Ivar den Ækle", l="Dræb Ivar den Ækle, og bring Ivars Hoved til Rane Yorik ved Ivar-agerlodden.", d="Min bror Quinn og jeg fik til opgave at spejde i Sølvfyrreskoven og rapportere til Højeksekutor Hadrec. Men vi kom ikke langt - da vi bevægede os gennem denne gård, blev vi angrebet af gulen Ivar den Ækle.\n\nVi slap væk fra Ivar, men han lemlæstede Quinn alvorligt. Han heler nu af den eliksir, du gav ham, men Ivar kan vende tilbage, før Quinn er kommet sig.\n\nDræb Ivar, så Quinn får tid til at hele. Ivar opholder sig normalt i laden derhenne og venter på, at min vagt slår fejl."},
  [426] = {n="Møllerne Er Overrendt", l="Saml 5 Takkede Ribben og 3 Sortnede Kranier, og vend derefter tilbage til Dødevagt Dillinger i Gryde-by.", d="Svøben forsøger at etablere en base ved Agamand-møllerne. Hvis de lykkes, kan de iværksætte yderligere angreb inden for Tirisfal.\n\nOrdrene er givet. Svøben i møllerne skal tilintetgøres.\n\nGå til møllerne. Saml Takkede Ribben fra Rasselbur og Revnede Kraniesoldater, og Sortnede Kranier fra Mørkeøje Knoglekastere.\n\nFor at komme til møllerne, følg vejen mod vest. Efter at have krydset broen tager du næste vejkryds mod nord og fortsætter nordpå. Når du ser vindmøllerne, begynder slaget."},
  [427] = {n="I Krig Med Skarlagenrøde Korstog", l="Eksekutor Zygant fra Gryde-by vil have dig til at dræbe 10 Skarlagenrøde Krigere.", d="Dokumenterne Eksekutor Arrin fremskaffede er netop det gennembrud, vi havde brug for i vores kamp mod de elendige Skarlagenrøde Korstog. Vi kender nu deres præcise placeringer i hele Tirisfals Lysninger.\n\nMen Dødevagten har større bekymringer. Liskekongens hær vokser for hver nat. Vi har brug for en med \"initiativ\" som dig selv til at drive Skarlagenrøde Korstog i graven.\n\nBevis over for mig, at du er i stand til at tjene Den Mørke Dame ved at rejse mod vest til tårnet forbi Solliden-gården og dræbe 10 Skarlagenrøde Krigere."},
  [428] = {n="Fortabte Dødsstalkere", l="Find Dødsstalkerne Quinn og Rane Yorik.", d="For et par uger siden blev to af vores Dødsstalkere, Rane og Quinn Yorik, sendt på et spejderhverv gennem det nordlige Sølvfyrreskov. Vi har ikke hørt fra dem.\n\nDe kan være blevet offer for Svøben, men hvis det er tilfældet, vil jeg have det bekræftet. Find disse Dødsstalkere.\n\nDeres første mål var at spejde gårdene i det nordlige Sølvfyrreskov. Du bør begynde din søgen der."},
  [429] = {n="Vilde Hjerter", l="Saml 3 misfarvede varghjerter og bring dem til Apoteker Renferrel ved Gravkammeret.", d="Min bror Quinn blev slemt såret af gulen Ivar den Ækle, og jeg ved ikke, om han kommer sig ordentligt uden alkymisk hjælp. Selvom jeg ikke er apoteker, ved jeg, at vores apotekere kan lave heleeliksirer af misfarvede varghjerter.\n\nSaml sådanne hjerter og tag dem med til Apoteker Renferrel ved Gravkammeret mod syd. Kom så tilbage hertil med eliksiren.\n\nDu kan finde masser af varger mellem her og Maldens Frugthave mod øst."},
  [430] = {n="Tilbage til Quinn", l="Bring Quinns eliksir til Quinn Yorik ved Ivar-agerlodden, nord for Gravkammeret.", d="Her er eliksiren til at hjælpe Quinn Yorik med at komme sig.\n\nNu, hvis du vil undskylde mig, har jeg meget vigtigt arbejde at fortsætte..."},
  [431] = {n="Kaldelysene"},
  [432] = {n="De Forbandede Troggs!", l="Dræb 6 Klippekæbe-kraniebankere for Formand Stenbryn ved Gol'Bolar-stenbruddet.", d="De lys-forbandede troggs, de ødelægger min arbejdsplads og gør den til et vrag! Se nu, dér røg endnu en tønde krudt!\n\nOhhh, jeg ville ønske, jeg kunne gå derned og vride hver eneste af deres spinkle små halse! Jeg vil dræbe dem alle!\n\nDet her kan ikke være godt for mit helbred, al den stress og vrede... Hvad har de efterladt mig med? Intet!\n\nJeg ville dræbe dem selv, men mit sigte er ikke godt mere! Gå ind i stenbruddet og dræb nogle af de beskidte kujoner! Jeg betaler dig! Bare dræb dem, slå dem ned!"},
  [433] = {n="Den Offentlige Tjenestemand", l="Dræb 10 Klippekæbe-knoglebrækkere for Senator Mehr Stenhall ved Gol'Bolar-stenbruddet.", d="Som medlem af Senatet og Opdagelsesrejsende-Ligaen har jeg påtaget mig at tage mig af denne del af trogg-plagen, som har grebet vores lande.\n\nDe har bestemt rodet Gol'Bolar-stenbruddet til uden grund. Da vi gravede dybt i jorden, væltede de frem, ødelagde vores udstyr og drev minearbejderne væk. Der er ikke meget andet at gøre, end at udrydde hele pakket, genopbygge og komme tilbage til arbejdet.\n\nHvis du hjælper mig med trogg'erne, vil jeg gerne belønne dig for din tid."},
  [434] = {n="Angrebet!", l="Bliv i haven, indtil Lord Gregor Lescovær og Marzon Den Tavse Klinge har talt sammen. Dræb dem begge bagefter, før du vender tilbage til Elling Trøsen i Stormvind.", d="Efter jeg har taget Spionbots forklædning på, går han ind for at tale med Lescovær. Vagterne burde lade ham passere uden problemer.\n\nMens du hentede materialer til mig, sørgede jeg for at informere Marzon om, at det var tid til, at han og Lescovær mødtes igen. Jeg gav endda nogle falske oplysninger.\n\nLescovær vil afskedige sine vagter og vente på Marzon derude i haven. Når du fanger snak om Defias, så gør dit træk. Du skal dræbe dem begge, før vagterne vender tilbage! Når du er færdig, skal du tale med Trøsen."},
  [436] = {n="Jernbånds Udgravning", l="Tal med Opdagelsesrejsende Skindspænd.", d="Prospektor Jernbånd leder en udgravning af oldtidsruiner øst for søen. Hans fremskridt har været langsomme på det sidste, især i betragtning af alt det udstyr, vi har sendt ham.\n\nJernbånd er en robust, ærlig dværg, der sætter pris på resultater, hvilket får mig til at bekymre mig om, at kræfter arbejder imod ham.\n\nGå til Jernbånds Udgravning og tal med Magmar Skindspænd. Han styrer detaljerne på stedet og vil vide, hvorfor der er sket en forsinkelse.\n\nFor at komme til udgravningsstedet, gå rundt om søens sydlige spids, og drag så mod øst."},
  [437] = {n="De Døde Marker", l="Dræb rådhud-gnolde på De Døde Marker.\n\nNår Natpisk dukker op, dræb hende.\n\nBring Natpiskens Essens til Højeksekutor Hadrec ved Gravkammeret.", d="Vores indledende spejderrapporter om Sølvfyrreskoven viser, at rådhud'erne har en base på en gammel gård mod nord, De Døde Marker. Vi har sendt små angreb mod dem, men hver gang bliver de forstærket af banshee'en Natpisk, der bruger sin magi til at jage vores styrker på flugt.\n\nVi vil have Natpisk tilintetgjort.\n\nDrag til De Døde Marker og angrib rådhud'erne. Hvis du ikke ser Natpisk, så dræb rådhud'erne, indtil hun dukker op, og besejr hende så.\n\nHendes essens vil forvandles til støv. Bring mig det støv som bevis."},
  [438] = {n="Den Forfaldne Færge", l="Tag til Den Forfaldne Færge.\n\nUndersøg hvorfor Svøben er der.", d="<Name>, vi har opdaget et nyt rede for Svøben: Den Forfaldne Færge. Færgen ligger øst for Gravkammeret og patruljeres tungt af rådhud'er og andre udøde.\n\nDer må være en grund til, at Svøben har besat området. Tag til Den Forfaldne Færge og find ud af, hvorfor Svøben er der."},
  [439] = {n="Rådhud-spor", l="Bring Deliahs Ring til Højeksekutor Hadrec ved Gravkammeret.", d="Blandt ligene stikker en hånd frem, uindpakket. Det er en kvindes hånd, ardet af pesten, men relativt frisk.\n\nPå hånden sidder en ring. Når man fjerner ringen og undersøger den, afslører en indgravering sig:\n\n\"Til Deliah\""},
  [440] = {n="Den Indgraverede Ring", l="Bring Deliahs Ring til Dommer Sevrin i Gryde-by.", d="Hvis du vil finde manden eller den elskede, der gav Deliah hendes ring... så tal med Dommer Sevrin i Gryde-by. Han burde have optegnelser over nylige dødsfald, og med lidt held kan han finde ud af, hvem Deliah er.\n\nMen jeg ville ikke sætte mit håb til det. Hvem end der gav hende ringen, er sandsynligvis død. Eller hvis han er udød, bekymrer han sig nok ikke længere om Deliah."},
  [441] = {n="Raleig og Undergrunden", l="Bring Deliahs Ring til Raleig.", d="Deliah havde en mand, Raleig, der nu bor i Undergrunden. Hvis den Deliah, der boede i Gryde-by, er den, der ejede denne ring, så vil Raleig vide det.\n\nRaleig befinder sig i Undergrundens Handelskvarter."},
  [442] = {n="Angreb på Fenris-øen", l="Bring Thules hoved til Højeksekutor Hadrec i Gravkammeret.", d="Nu er tiden kommet til at angribe Svøbens højborg i Sølvfyrreskoven: Fenris-øen.\n\nDu skal igen tage ud til øen og tilintetgøre Thule Ravnekloe. Jeg vil have hans hoved!\n\nDenne mission er lige så farlig, som den er vigtig, <Name>. Du må ikke fejle."},
  [443] = {n="Rådhud-ichor", l="Bring 8 flasker rådhud-ichor til Apoteker Renfærrel i Gravkammeret.", d="Før vi angriber Fenris-øen, må vi finde ud af, hvem der står bag rådhud-gnoldene. Vores apotekere mener, at oprindelsen ligger i den mærkelige væske, der flyder gennem deres kroppe.\n\nTag til Fenris-øen, øst for Den Forfaldne Færge, og saml rådhud-ichor fra gnoldene, du finder der. Bring det til Apoteker Renfærrel, der står uden for Gravkammeret."},
  [444] = {n="Rådhudens Oprindelse", l="Bring prøve-ichoren til Bethor Isskår i Undergrunden.", d="Jeg har reduceret den ichor, du bragte mig, og adskilt den i dens grundbestanddele. Mine fund er ikke endelige, men jeg har konstateret, at hekseri og nekromantisk magi blev brugt ved ichorens fremstilling.\n\nMens jeg fortsætter med at studere ichoren, vil jeg have dig til at tage en prøve med til Bethor Isskår i Undergrunden. Bethor er ingen apoteker, men hans viden om magi kan måske hjælpe med at løse rådhudernes gåde.\n\nAfsted. Du finder Bethor i Magikvarteret i Undergrunden."},
  [445] = {n="Levering til Sølvfyrreskoven", l="Tag Apoteker Johans fund til Apoteker Renfærrel i Sølvfyrreskoven.", d="Tid er et luksusgode, som ikke tilfalder dem, der er i Lady Silvanas tjeneste. Det ved du sikkert allerede.\n\nSom medlem af Det Kongelige Apotekerselskab er det min pligt at dele min viden med mine kolleger, så vores fælles bestræbelser en dag kan give Den Mørke Dame den Nye Pest, hun så inderligt begærer.\n\nTag disse fund med til Apoteker Renfærrel, der holder til i Gravkammeret i Sølvfyrreskoven. Følg vejene mod syd fra Gryde-by. Fra Undergrunden går du mod sydvest."},
  [446] = {n="Thule Ravnekloe", l="Bring Bethors rulle til Apoteker Renfærrel i Sølvfyrre-gravkammeret.", d="Denne ichor blev skabt af en gammel kollega af mig: Thule Ravnekloe. Han var en ung, lovende magiker før den store krig, men da Liskekongen kom til magten, forrådte han sine brødre og allierede sig med Svøben.\n\nJeg var ikke klar over, at han stadig lever, eller at han leder rådhudene i deres angreb mod os!\n\nJeg kender mange af hans besværgelser og kan hjælpe med at brygge en eliksir, der modvirker dem. Tag denne rulle tilbage til Apoteker Renfærrel. Den indeholder de besværgelser, der er nødvendige for eliksiren."},
  [447] = {n="En Opskrift på Død", l="Saml 6 Gråbrune Bjørnehjerter og 6 prøver af Rislende Blod og lever dem hos Mesterapoteker Faranell i Undergrunden.", d="Arthæus' tal er overvældende. Men med en Ny Pest kunne vi udslette både Svøbens hær og menneskenes plage én gang for alle.\n\nMine studier har vist, at edderkoppeblod kombineret med et gift udvundet af et gråbrunt bjørnehjerte giver en dødbringende elixir. Saml prøver fra edderkopperne i Det Rislende Mørke mod nordvest og fra bjørnene, der vandrer rundt i Sølvfyrreskoven. Lever reagenserne til Mesterapoteker Faranell fra Det Kongelige Apotekerselskab i Undergrunden."},
  [448] = {n="Rapport til Hadrec", l="Aflever rapport til Højeksekutor Hadrec i Gravkammeret.", d="Før du angriber Fenris-øen, skal du melde dig hos Højeksekutor Hadrec. Han kan have yderligere oplysninger eller udstyr, som du får brug for."},
  [449] = {n="Dødsstalkernes Rapport", l="Bring Dødsstalker-rapporten til Højeksekutor Hadrec i Gravkammeret.", d="Selvom Quinns sår heler, vil jeg have vores rapport til Højeksekutor Hadrec så hurtigt som muligt. Den indeholder oplysninger, der er vitale for de Forladtes besættelse af Sølvfyrreskoven."},
  [450] = {n="En Opskrift på Død", l="Hent Apoteker Berards dagbog i Brandtræ-landsbyen og tag den med til Apoteker Renfærrel i Gravkammeret.", d="Du kan yde Det Kongelige Apotekerselskab yderligere tjeneste, <Name>.\n\nDa Arugel kastede sin ussle magi over skoven, forbandede han et af vores mest lovende medlemmer, Apoteker Berard. Nu er Berard en tankeløs tjener for Arugel og til ingen nytte for os. Men hans fund kan vise sig at være af værdi. Han studerede en gammel pest, der for længe siden udslettede alt vandliv i Lordamere-søen.\n\nHent Berards dagbog fra hans studie i Brandtræ-landsbyens Kro og tag den med til Apoteker Renfærrel."},
  [451] = {n="En Opskrift på Død", l="Bring 6 prøver af Søkrybermos, 6 prøver af Søsnigermos og en Hærdet Tumor til Mesterapoteker Faranell i Undergrunden.", d="Ifølge Berards dagbog kan mosset fra Søsnigerne og Søkryberne være nyttigt til vores forsøg på at brygge en ny pest. Disse væsner holder til på øerne i Lordamere-søen mod øst.\n\nHan nævner også en meget sjælden Hærdet Tumor, som han opdagede på en Ondskabsfinne-mudderfisk. Tumoren er tilsyneladende så sjælden, at Berard kun kunne skaffe én.\n\nSaml prøver af mosset samt den sjældne hærdede tumor og tag dem med til Mesterapoteker Faranell i Undergrunden."},
  [452] = {n="Brandtræ-baghold", l="Hjælp Dødsstalker Færleia med at dræbe Brandtræ-rådet.", d="Du kom lige i tide, <Name>!\n\nBrandtræ-rådet vender tilbage et hvert øjeblik. Arugel har andre sager at tage sig af i fæstningen. Han bruger rådet som blotte marionetter for at holde Brandtræs tankeløse håndlangere under sin kontrol. Men jeg tror, at uden Brandtræ-rådets vejledning vil Arugels sønner vende sig mod deres herre.\n\nJeg kan ikke klare dem alene. Jeg har brug for din hjælp. Sammen kan vi lægge Brandtræ-rådet i ruiner for Lady Silvanas skyld."},
  [453] = {n="Find den Skyggefulde Skikkelse", l="Find den Skyggefulde Skikkelse. Dine spor:\n\nHan er ikke hjemmehørende i Mørkeshire.\n\nHan er en nervøs, rastløs person.\n\nHan forlod Mørkeshire og drog mod vest.", d="Held og lykke, <Name>. Jeg håber, du finder karlen, og jeg håber, du finder ham i live.\n\nHvis han har forladt Mørkeshires sikkerhed, kan han være bytte for vildmarkens bæster."},
  [454] = {n="Efter Baghold", l="Tal med Mirran.", d="Vi har slæbt tøndernes krudt frem og tilbage i flere omgange, før denne... affære. Nu må vi dele arbejdet: Mirran tager tøndene, og jeg holder øje med de andre.\n\nJeg har ikke det godt med at lade Mirran slæbe resten af forsendelsen alene. Når han er klar til at gå, kunne du måske ledsage ham på hans næste tur?"},
  [455] = {n="Algaz-udfordringen", l="Gennemkryds Dun Algaz.\n\nDræb 8 Dragemave-spejdere og 6 Dragemave-fodsoldater.\n\nRapportér til Valstag Jernkæbe i Menetil-havnen.", d="Orker af Dragemave-klanen har et tilflugtssted i Vådlandene. Og nu har de bredt sig til Dun Algaz! Vi kan ikke lade dem beholde deres fodfæste her, for ellers bliver Modansøen afskåret fra Menetil-havnen, vores havn og højborg i Vådlandene.\n\nBryd igennem Dun Algaz til Vådlandene dernede og dræb nogle orker for en god ordens skyld! Rapportér til Valstag Jernkæbe i Menetil-havnen.\n\nMenetil ligger gennem Dun Algaz, derefter nordpå ad vejen og vest ved vejgaflen.\n\nVi regner med dig, <Name>. Du må ikke fejle."},
  [456] = {n="Naturens Balance", l="Dræb 7 Unge Natsabler og 4 Unge Tidselvildsvin og vend tilbage til Konservator Ilthalæne.", d="Hilsen, <Name>. Jeg er Konservator Ilthalæne. Mit formål i Skyggedalen er at sikre, at naturens balance bevares.\n\nDe kraftige forårsregnskyl i år var særligt store, hvilket fik nogle af skovens dyr til at trives, mens andre led.\n\nDesværre blev bestandene af natsabler og tidselvildsvin for store. Skyggedalen kan kun producere så meget føde til dyrene. Drag af sted, unge <Class>, og tynd ud i vildsvin- og sabelbestandene, så naturens harmoni kan bevares."},
  [457] = {n="Naturens Balance", l="Konservator Ilthalæne har brug for, at du dræber 7 Skabede Natsabler og 7 Tidselvildsvin.", d="At tynde ud i de yngre skabninger her i Skyggedalen var en god begyndelse, <Name>, men der er stadig arbejde at gøre.\n\nSkovens ressourcer vil blive opbrugt for hurtigt, hvis problemet ikke tages op. At dræbe naturens dyr er et nødvendigt onde til gavn for alle, der deler landet. Gå ind i skoven og slå skabede natsabler og tidselvildsvin ned i balancens navn."},
  [458] = {n="Skovbeskytteren", l="Find dryaden ved navn Tarindrella.", d="Gudskelov, at du er her, <Class>. Mærkelige nyheder er nået frem til mig gennem skovånders hvisken.\n\nDen mystiske skovbeskytter, Tarindrella, er vendt tilbage til Skyggedalen. Dryadens nærvær har ikke været mærkbart i Kalimdors skove i årevis. Der må være noget galt, hvis hun er rejst tilbage til dette land.\n\nFind Tarindrella og se, hvilke ærinder hun har i vores lund. En af vagterne så hende sydvest for Aldrasil."},
  [459] = {n="Skovbeskytteren", l="Saml 8 Ondmos og bring dem til Tarindrella.", d="Noget ondt er ved at brygge i Teldrasils skove. Se længe hen mod højene, hvor de fredelige furbolgs plejede at bo. De har forladt deres hjem og samler sig under navnet Knudefyr-stammen.\n\nKun korruptionen fra det onde Ondmos kunne forvandle dem sådan. Grellerne og grelkinerne har inficeret området og truer beboerne i Skyggedalen.\n\nKonfrontér disse grelle og grelkiner, <Name>, og se, om de faktisk er fanget under forbandelsen fra det onde Ondmos."},
  [460] = {n="Hvilende i Stykker", l="Bring Alarics hoved til hans grav.", d="Du ligner ikke en rådhud. Godt. Jeg havde mistet håbet...\n\nJeg hedder Alaric, og jeg var engang Thules øverste tjener og livvagt. Han brugte sin magi til at \"beskytte\" mig mod Udødhedens Pest, men i stedet gav hans besværgelse mig et udødeliv, som jeg ikke kan slippe fra. Og efter at have skabt de forbandede rådhud-gnolde, halshuggede Thule mig... og gav mit hoved til gnoldene som legetøj!\n\nVær venlig at tage mig til min krop. Jeg tror, gnoldene begravede den her i Fenris-fæstningen, nær stalden, i en umærket grav."},
  [461] = {n="Den Skjulte Niche", l="Tag Alaric til det skjulte alkove.", d="Jeg kender en skjult niche i fæstningen, der gemmer på en genstand, som Thule og hans gamle kolleger holder kær. Den indeholder også noget, du måske finder nyttigt. Tag mig derhen!\n\nAlkoven ligger i fæstningens sydvestlige tårn, bag en støvet hylde.\n\nTag min krop, men lad mine støvler blive. De passede mig aldrig alligevel..."},
  [463] = {n="Grønvogteren", l="Find Grønvogteren.", d="Har du hørt om Grønvogteren? Du leder ikke efter ham, vel? Nå, jeg siger, du er gal, hvis du gør, men hvem er jeg til at forhindre en tosse i at møde sin død?\n\nHvis du søger det udyr, så hører jeg, at han er i sumpen, øst for vejen, hvor den deler sig mod Dun Mødr. Han lurer der blandt krokodillerne... og værre endnu!\n\nOg lad dine penge blive her. Du får ikke brug for dem, hvor du skal hen... og du vil vel ikke ødelægge gamle Grønnies tand på dit guld, når han bider dig over midten, vel?"},
  [464] = {n="Krigsbannere", l="Bring 8 Dragemave-krigsbannere til Kaptajn Tykfist.", d="Dragemave-orkeklanen blev næsten udslettet ved slutningen af Anden Krig, efter de mistede kontrollen over deres røde drage-kæledyr. Dragerne var ikke særlig glade for deres gamle herrer og jagtede Dragemaverne ubarmhjertigt. De få, der var tilbage, flygtede fra Grimbatol og ind i bjergene øst for Whelgars udgravningssted.\n\nNu har de fået styrke igen og har en lejr nordøst for Menetil.\n\nVi vil have dig til at angribe den lejr. Saml deres krigsbannere og bring dem til mig som bevis."},
  [465] = {n="Nekroshs Gambit", l="Ødelæg Dragemave-katapulterne.", d="Dragemaverne er tættere på at iværksætte deres angrebsplaner, end vi troede.\n\nNekrosh har bygget katapulter og sigter mod at belejre Menetil! Og med kampene i Dun Algaz er vi effektivt blokeret for forstærkninger!\n\nDu skal udslette de katapulter. De står i Dragemave-lejren.\n\nTag her, tag denne tinder. Kæmp dig frem til katapulterne og tænd dem med tinderen.\n\nNår du har gjort det, skal du finde og dræbe Nekrosh. Vi må hugge dette Dragemave-udyr ned... lige over halsen."},
  [466] = {n="Søg efter Incendicit", l="Bring 6 læs Incendicit-malm til Pilot Stengear i Dun Frostbakke.", d="Jeg hørte, at en sjælden malm, incendicit, blev fundet i Vådlandene, i en hule nordvest for Algaz-porten. Incendicit er flygtigt stof og svært at bruge uden at sprænge sig selv i luften, men jeg er sikker på, at hvis det smeltes på den rette måde, kan det lave kanonkugler med et mægtigt slag!\n\nSkaf mig incendicit-malmen, så finder jeg nogen modig nok til at eksperimentere med den.\n\nÅh, og for at udvinde malmen fra årebåndet skal du have færdigheder i minedrift. Har du ikke det, så... tag en ven med, der har, ind i hulen!"},
  [467] = {n="Stengears Eftersøgning", l="Tal med Pilot Stengear.", d="Pilot Stengear elsker sit belejringsvåben, som enhver pilot bør! Og han er altid ivrig efter at finde nye måder at forbedre sin tanks ildkraft på!\n\nHan hørte rygter om en sjælden malm og leder efter nogen, der kan jagte den for ham. Hvis dine støvler begynder at klø, så find Stengear ved Stålgrills Depot i Dun Frostbakke og hør, hvad han vil."},
  [468] = {n="Meld dig til Bjergbestiger Klippegrov", l="Tal med Bjergbestiger Klippegrov.", d="Bjergbestiger Klippegrov søger frivillige til en mission gennem Dun Algaz og ud i Vådlandene.\n\nHvis du har lyst til at få dine støvler våde i det sumpede amt mod nord, så tal med Klippegrov i Dun Algaz. Dun Algaz ligger længere op ad vejen, forbi vagttårnet."},
  [469] = {n="Daglig Levering", l="Lever Bundtet med Krokolisk-skind til garveren James Garver i Menetil-havnen.", d="Hilsen, rejsende!\n\nTror du mon ikke, at du er på vej mod Menetil, hva'? Hvis ikke, vil jeg foreslå, at du holder ind der, det er et godt sted at købe varer og endda få en pint og slappe af.\n\nNu, hvis det alligevel tilfældigvis er den retning, du er på vej, har du vel ikke noget imod at tage dette bundt krokolisk-skind med til James Garver, garveren?\n\nJeg ville gøre det selv, men min kone har været i et særligt humør på det seneste, og jeg vil helst udskyde mødet med hende så længe som muligt."},
  [470] = {n="Graven Gennem Slammet", l="En af slimklumperne ved Jernskægs Grav har Sidas taske. Hent den og bring den tilbage til hende i Menetil-havnen.", d="Under mit ugentlige besøg i Jernskægs Grav blev jeg angrebet af frygtelige, dryppende slimklumper! Naturligvis fik jeg panik.\n\nJeg kastede min taske efter en af dem, men det gjorde ingen nytte! Slimklumpen sugede den bare op... Heldigvis gav den mig nok tid til at komme væk.\n\nDen dårlige nyhed er, at jeg virkelig har brug for indholdet af min taske!\n\nJeg ved ikke, hvilken slimklump jeg kastede tasken efter; de så alle sammen ens ud! Jernskægs Grav ligger mod nordøst herfra, nær Dun Mødr. Tusind tak!"},
  [471] = {n="Lærlingens Pligter", l="Saml 6 Kæmpe Krokolisk-skind og bring dem til James Garver i Menetil-havnen.", d="Jeg sendte min lærling ud i sumpene for at flå nogle af vores berømte kæmpe-krokoliske fra Vådlandene. Da han ikke vendte tilbage, gik jeg ud for at lede efter ham... Lad os bare sige, at det ikke var et kønt syn.\n\nJordemoderen siger, at han måske klarer den, men i mellemtiden har jeg stadig brug for mine skind!\n\n...Hvis du har lyst til at slå et par flere af de rå dyr ihjel, har jeg ingenting imod det, efter hvad de gjorde. Du finder krokoliskerne nordpå langs kysten, forbi mudderfiskenes hytter."},
  [472] = {n="Dun Mødrs Fald", l="Led efter Langfletten nær byen Dun Mødr.", d="Dun Mødr er faldet til Mørkjerns-dværgene!\n\nMine sår er alvorlige, <Class>. Det meste af regimentet blev dræbt! Mørkjerns-banditterne angreb os, før vi kunne samle os igen efter baghold ved Thandol-spændet.\n\nVores fører, Langfletten, blæste retræte i hornet. Da vi forlod byen, blev jeg ramt i ryggen af en vildfaren økse. Så blev alt sort.\n\nJeg vågnede her i Menetil, men jeg frygter for mine medsoldater. Håbet brænder stadig i mig. Måske lever Langfletten endnu! Se om du kan finde ham nær Dun Mødr, <Race>!"},
  [473] = {n="Meld dig til Kaptajn Tykfist", l="Tal med Kaptajn Tykfist.", d="<Name>. Dragemave-orkeklanen viser sin styrke i mere end blot Algaz.\n\nKaptajn Tykfist har bedt om at tale med dem, der er villige til at yde hjælp mod disse orker. Han befinder sig inde i fæstningen, i krigsrummet."},
  [474] = {n="Besejr Nekrosh", l="Dræb Høvding Nekrosh.\n\nBring Nekroshs Hoved til Kaptajn Tykfist.", d="Nu hvor katapulterne er brændt, skal du finde og dræbe Høvding Nekrosh."},
  [477] = {n="Grænseoverskridelser", l="Hent indholdet af en af Dalarns troldmænds kasser. Du finder Brandtræ-landsbyen mod syd.", d="Som du måske ved, er byen Ambermølle stadig en kilde til menneskelig modstand, hovedsageligt gennem den støtte, de modtager fra troldmændene i Dalarn.\n\nJeg ved ikke, hvad deres plan er, men at de viser interesse for en afsidesliggende landsby som Ambermølle, tyder på, at den må have en større betydning.\n\nDe har sendt kasser i vognlæs fra Hillsbrad. Meget af forsyningen ender i en lille lejr nord for Brandtræ-landsbyen. Hent indholdet af en kasse og bring det tilbage til mig."},
  [478] = {n="Kort og Runer", l="Bring det runeindgraverede vedhæng til Skyggepræst Allister i Gravkammeret.", d="<Du fjerner hurtigt vedhænget fra kassen og sætter låget på igen.>"},
  [479] = {n="Ambermølle-efterforskningen", l="Skaf 8 Dalarn-vedhæng til Skyggepræst Allister i Gravkammeret.", d="Dalar forsøger at finde kilden til troldmændenes besværgelser. Indtil videre må vi bremse deres fremskridt på enhver måde, vi kan...\n\nBesværgerne, magikerne og beskytterne bærer uden tvivl vedhængene. Tag dem af og hent dem.\n\nTag hovedvejen mod syd og den østlige vej ind i Ambermølle."},
  [480] = {n="Væveren", l="Dræb Dalarns ærkemagiker, og hent derefter hans stav til Skyggepræst Allister i Gravkammeret.", d="En ærkemagiker af stor magt fører tilsyn med genaktiveringen af leylinje-energiknudepunktet. Med de fremskridt, de har gjort, er vores eneste håb om at stoppe dem at dræbe ham. Det bliver svært, han er uden tvivl beskyttet af mange andre magikere og vagter.\n\nDu må gå, og du må nedlægge ham hurtigt. Når han er død, skal du hente hans stav til mig. Gå nu."},
  [481] = {n="Dalars Analyse", l="Tag det runeindgraverede vedhæng til Dalar Morgenvæver i Gravkammeret.", d="Tag vedhænget med til Dalar Morgenvæver, måske kan han kaste lys over troldmændenes planer."},
  [482] = {n="Dalarns Hensigter", l="Tal med Skyggepræst Allister i Gravkammeret.", d="Selvfølgelig! Hvordan kunne jeg glemme det?\n\nAmbermølle var et af de steder, Kirin Tårn havde udpeget, fordi det rummer et sovende leylinje-energiknudepunkt. Troldmændene må planlægge at genaktivere knudepunktet og bruge dets energi til et større formål.\n\nVi må ikke tillade, at det sker...\n\nDer skal en enorm mængde kraft til at aktivere områdets leylinje-energi, men vi kan forsinke dem ved at tage vedhængene fra troldmændene.\n\nVideregiv denne information til Allister, så træffer han en beslutning om, hvad vi skal gøre."},
  [483] = {n="Vækkelsens Relikvier", l="Hent Vækkelsens Relikvier og bring dem til Athridas Bjørnekappe i Dolanaar.", d="Knudefyr-indtrængere blev set hærge i Ban'ethil-gravhulen mod vest.\n\nDe sovende druider vil blive fanget i den Smaragdgrønne Drøm i al evighed, uvidende om deres skæbne, medmindre vi hjælper. Den delikate dvaleritual kan ikke brydes uden Vækkelsens Relikvier.\n\nRejs til hulen og hent Ravnekloe-talismanen, Sortfjer-fjerpennen, Himmelsafiren og Redens Rune. Druiderne opbevarer dem i hellige kister. Bring dem til mig, så forbereder jeg vækkelsesritualet."},
  [484] = {n="Unge Krokolisk-skind", l="Skaf 6 Unge Krokolisk-skind til James Garver i Menetil-havnen.", d="Jeg er James Garver, garveren. Mine tilberedte krokolisk-skind er eftertragtet overalt, og sendinger forlader havnen med skib til byer rundt om i verden.\n\nMødte du Einar? Han er en af jægerne, der bringer krokolisk-skind ind til mig.\n\nJeg løber lidt tør for de bløde skind, der kommer fra krokoliske unger.\n\nDa jeg løber tør, betaler jeg top-pris for en bunke af skindene. Du kan finde de unge krokoliske lige ude i vandet udenfor byen."},
  [491] = {n="Staven til Bethor", l="Tag den Flettede Stav med til Bethor Isskår i Magikvarteret i Undergrunden.", d="Thule fortalte mig engang, at han og to kollegaer for længe siden skabte en magisk stav, flettet sammen af de lærlingestave, hver magiker havde. Denne stav var et symbol på deres venskab, og selvom Thule kom til at foragte den, kunne han ikke skille sig af med den, og han kunne heller ikke lade de andre få den. Så stjal han staven og gemte den i Fenris-fæstningen.\n\nSå her. Tag staven med til Bethor Isskår, en af Thules venner fra gamle dage. Jeg er sikker på, at han vil have den."},
  [492] = {n="En Ny Pest", l="Bring Johans Specialdrik til den Fangede Bjergbestiger.", d="Ifølge Dødevagten er endnu en af de tossede dværgiske bjergbestigere netop blevet fanget. Dødevagten bruger gerne kælderen i Galgeenden Kro som fangehul, indtil fangerne bliver \"ordentligt\" behandlet.\n\nHvorfor går du ikke hen og ser, hvordan den Fangede Bjergbestiger nyder denne specielle drik, jeg har lavet til ham? Den indeholder en subtil antydning af, hvad Den Mørke Dame har planlagt for resten af Azeroth."},
  [493] = {n="Rejsen til Hillsbrad-forbjergene", l="Lever Apoteker Renferrels Fund til Apoteker Lydon i Tarrenmølle i Hillsbrad-forbjergene.", d="Det Kongelige Apotekerselskab er under enormt pres fra Den Mørke Dame for at udvikle en Ny Pest. Vi arbejder flittigt og har gjort store fremskridt. Vi mener, at succes vil komme meget hurtigere, hvis vi deler information inden for Selskabet.\n\nAf den grund vil jeg have dig til at levere mine seneste fund til Apoteker Lydon i Tarrenmølle, en lille by gemt i Hillsbrad-forbjergene. Rejsen bliver lang.\n\nTag mod syd og hold dig til vejene. Følg skiltene nøje!"},
  [494] = {n="Tid til at Slå til", l="Rejs til Tarrenmølle og lever Dødsstalker Leshs besked til Højeksekutor Darthalia.", d="Vær stille og lyt efter, <Class>.\n\nJeg blev sendt til denne position for at undersøge byen Hillsbrad. Min mission er rekognoscering. Det er afgørende, at du straks sender besked til Højeksekutor Darthalia i Tarrenmølle. Fortæl hende, at jeg, Dødsstalker Lesh, sender følgende budskab:\n\n\"Ravnens skrig fra vest kalder.\"\n\nFølg vejen mod øst, og hold godt øje med skiltene. Nu, skynd dig! Af sted til Tarrenmølle, og det haster, skal jeg lige tilføje!"},
  [496] = {n="Lidelsens Eliksir", l="Apoteker Lydon i Tarrenmølle vil have 10 Gråbjørnetunger og noget Krybersaft.", d="Ah, endnu en elendig dag i Tarrenmølle. Al den rene luft gør mig så ondskabsfuld, <Name>.\n\nJo før vi kan plage menneskene her, jo bedre. Jeg har udført intensive studier af mulige dræbende midler, jeg kan bruge i mine koncentrater, men jeg har ikke tid til at samle dem alle.\n\nHvis du vil gøre dig nyttig, så skaf følgende ting til mig: 10 Gråbjørnetunger og det meget sjældne og svært fundne Krybersaft. Du finder både bjørne og krybere lige uden for Tarrenmølle."},
  [498] = {n="Redningen", l="Krusk i Tarrenmølle har brug for, at du befrier Drull og Tog'thar fra Durnholde-fæstningen.", d="Mig og nogle andre krigere blev sendt af Krigshøvdingen for at hente en genstand fra Durnholde og undersøge dette såkaldte Syndikat.\n\nVi gik til Durnholde for at kigge os omkring, men vi blev overrumplet af et stort antal mennesker. Vi kæmpede modigt, men deres blotte antal var nok til at besejre os. De tog nogle af os til fange, men jeg kunne flygte.\n\nDurnholde ligger lige mod sydøst herfra, på tværs af floden. Drull og Tog'thar holdes der, du må af sted og redde dem."},
  [499] = {n="Lidelsens Eliksir", l="Giv Umpi Lidelsens Eliksir.", d="Det tager kun et øjeblik for mig at blande disse ingredienser til det, jeg har besluttet mig for at kalde en Lidelsens Eliksir.\n\nSå var den klar! Ah, intet lyser en dyster dag i disse elendige forbjerge op som at bringe en smule lidelse til verden.\n\nLad os se, om vores lille trylledrik har opnået den ønskede effekt.\n\nGiv min assistent Umpi en smagsprøve på, hvad Den Mørke Dame har planlagt for både mennesker og Svøben."},
  [500] = {n="Knusekam-dusøren", l="Saml 9 Beskidte Knokkelterninger fra Knusekam-oger i Alterac-bjergene. Bring dem til Marskal Rødstig i Sydstranden.", d="Knusekam-oger har gravet en ogrehøj op i Alterac-bjergene nær den ødelagte by Alterac. Og mine spejdere fortæller mig, at de også har overtaget ruinerne.\n\nVi kan ikke lade dem blive hjemmevante deroppe; hvis de tror, de er i sikkerhed, hvor de er, vil deres næste skridt være at bevæge sig ned i forbjergene, og så står de lige ved vores dør!\n\nGå mod nord til Alterac-bjergene og jag ogrer. Bring mig de Beskidte Knokkelterninger, de bærer, så tjener du en fin dusør."},
  [501] = {n="Smertens Eliksir", l="Bring 10 flasker Bjergløvens Blod til Apoteker Lydon i Tarrenmølle.", d="Åh, <Name>. . .blomsterne blomstrer i Hillsbrad, og luften er så frisk og kølig. Jeg kan ikke lade være med at svælge i elendigheden af det hele. Jeg kigger ud af mit snavsede vindue og længes efter dagen, hvor vores Nye Pest bringer verden den død, den fortjener.\n\nSå gerne jeg vil sidde og grave hele dagen, kalder min pligt over for Den Mørke Dame. Vil du hjælpe mig? Min forskning tyder på, at jeg kan lave den mest prægtige dødsdrik med blod fra en bjergløve. Bring mig noget, så får vi lidt sjov."},
  [502] = {n="Smertens Eliksir", l="Giv Eliksiren mod Smerte til Stanley.", d="Ah, intet overgår lugten af friskt blod i forbjergene!\n\nNu blander vi lidt af dette og lidt af hint, og den rigtige sjov begynder! Det, jeg har skabt med dette blod, kalder jeg en Smertens Eliksir. Hvis mine beregninger er korrekte, kan denne koncentrat være begyndelsen på noget meget smukt for Lady Silvanas. Men det, vi har brug for, er en test.\n\nTag denne eliksir med ud til nordgården i Hillsbrad-markerne mod sydvest. Lad os se, hvordan Bonde Rays lille hund Stanley kan lide denne \"godbid.\""},
  [503] = {n="Gulddyr", l="Befri Gulddyr og vend så tilbage til Krusk i Tarrenmølle.", d="Ud fra de dokumenter du skaffede, at dømme, bliver Gulddyr holdt fanget i en stor Syndikat-base mod nord, sandsynligvis i Alterac-bjergene. Han har været fanget alt for længe, og han må befries."},
  [504] = {n="Knusekam-krigsmagerne", l="Slå 15 Knusekam-krigsmagere ihjel, og vend så tilbage til Marskal Rødstig i Sydstranden.", d="Nu hvor du har smagt på Knusekam-ogrene, vil jeg have dig til at blodige deres næser for alvor...\n\nGå ind i Ruinerne af Alterac og led efter Knusekam-krigsmagerne. Jeg vil have dig til at fælde et pænt antal af dem - det er den eneste måde, de brutale kujoner lærer at holde sig væk fra Alliancens territorium."},
  [505] = {n="Syndikat-snigmorderne", l="Dræb 12 Syndikat-gaderøvere og 8 Syndikat-tyve, og vend så tilbage til Dommer Henrik Malebe i Sydstranden.", d="Jeg er den nye dommer i Sydstranden, for nylig udnævnt efter attentatet på den forrige dommer. Snigmorderne er aldrig blevet fundet, men gennem vores undersøgelser er vi næsten sikre på, at de er blevet lejet af Syndikatet - en bande tyve ledet af skurkagtige adelsmænd fra det nu faldne kongerige Alterac.\n\nSyndikatet har en lejr nord for Hordens besatte Tarrenmølle, og vores sidste spor førte til den lejr. Slå de Syndikat-medlemmer ihjel, du finder dér."},
  [507] = {n="Lord Aliden Pæreknold", l="Dræb Lord Aliden Pæreknold og spørg hans elskerinde, Elisa, om Tarettas vedhæng.", d="Det er klart, at Pæreknold må dø, hans snavsethed fjernet fra verden. Hans herregård ligger et stykke nord herfra, ved bredden af Lordamere-søen. Gør din pligt, <Name>, hent så det vedhæng Krigshøvdingen begærer, og vend tilbage hertil."},
  [509] = {n="Smertens Elixir", l="Bring 6 Mudderblomster til Apoteker Lydon i Tarrenmølle.", d="Endnu en dag, endnu et elixir der skal brygges. Havde det stået til mig, ville jeg bare lade de patetiske mennesker og Svøben kæmpe det ud. De synes jo at være opsat på at slå hinanden ihjel alligevel.\n\nDesværre vil vores Mørke Dame gerne fremskynde processen en smule, så hvorfor ikke tilbringe de morbide dage med at sprede lidt død og sygdom ud over landet?\n\nHer er planen, <Name>: du tager ud til Nethander-gården, syd for Tarrenmølle og øst for floden og Sydstranden. Saml 6 Mudderblomster fra marken til mit næste elixir."},
  [513] = {n="Smertens Elixir", l="Bring Mudderblomst-komposit'en til Mesterapoteker Faranell i Undergrunden.", d="Lige da jeg troede, at endnu en dag ville gå uden så meget som en lille glæde, bragte du mig de vidunderlige Mudderblomster.\n\nFørst blander jeg dem til en fin komposit. Så skal vi have Mesterapoteker Faranell i Undergrunden til at påføre sin Forrådnelseskolloid, og så er vi klar til noget rigtig morsomt!\n\nSå tag den her Mudderblomst-komposit og løb med den til Mesterapoteker Faranell med det samme, <Name>."},
  [515] = {n="Smertens Elixir", l="Bring Mudderblomst-blandingen, et Stærkt Trolleblods-elixir, 5 Dolkeryg-skæl og 5 Revetfinne-øjne til Apoteker Lydon i Tarrenmølle.", d="En mudderblomst-komposit? Helt genialt! Hvorfor tænkte jeg ikke selv på det?\n\nLad mig bidrage med min Forrådnelseskolloid til denne djævelske brygning.\n\nFor at aktivere de forurenende stoffer i denne mudderblomst-blanding har Lydon brug for et stærkt trolleblods-elixir samt nogle dolkeryg-skæl og revetfinne-øjne fra Hillsbrads sydkyst. Han ved nok, hvad han skal gøre, når du har samlet alle reagenserne til ham. Og hvor er jeg dog spændt på at høre, hvordan hans eksperiment går!"},
  [516] = {n="Berens Fare", l="Find Berens Fare, dræb så 6 Ravnekloe-slæbere og 6 Ravnekloe-vagter, og vend derefter tilbage til Skyggepræst Allister ved Gravkammeret.", d="Jeg har modtaget rapporter om, at en gruppe udøde gemmer sig for at forberede et angreb mod os. Med denne viden i hånden kan vi vende stillingen og angribe dem først og kvæle deres lille plan i fødslen.\n\nDesværre er mine oplysninger i bedste fald spinkle. De skulle gemme sig på et sted kaldet Berens Fare. Den præcise placering er ukendt, men det ser ud til at være en hule i bakkerne, nær en lomme af Dalarn-troldmænd.\n\nJeg stoler på din snalde. Find dem, og læg dem i graven."},
  [517] = {n="Smertens Elixir", l="Bring en tønde Gildes-stout til Apoteker Lydon i Tarrenmølle.", d="Dette nye elixir er endelig klar til at blive testet. Men hvorfor lade en fuldt ud brugbar, yderst smitsom pest gå til spilde på en simpel frø eller hund? Lad os have lidt rigtig morskab i Lady Silvanas' navn.\n\nTag ned til Garok-bakken. Du kender kasernen, hvor de beskidte små dværge vrimler rundt. Stjæl en tønde af deres Gildes-stout til mig. Når jeg har tønden, får du og jeg en ordentlig fest, <Name>."},
  [527] = {n="Slaget ved Hillsbrad", l="Dræb 6 Hillsbrad-landarbejdere, 6 Hillsbrad-bønder, Bonde Ray og Bonde Getz, og rapportér tilbage til Darthalia i Tarrenmølle.", d="Stå ved attention, når du henvender dig til mig, <Class>.\n\nJeg står under direkte kommando af Varimatras. Vi skal dæmpe menneskehedens plage, indtil vores apotekere kan udvikle den nye pest.\n\nVores efterretninger tyder på, at byen Hillsbrad er sårbar over for angreb. Din første opgave sigter mod at forstyrre deres fødevareforsyning og infrastruktur.\n\nRejs mod vest. Hærg de nordligste gårde i Hillsbrad-markerne. Sørg for, at godsejerne, Bonde Ray og Bonde Getz, også bliver henrettet."},
  [528] = {n="Slaget ved Hillsbrad", l="Dræb 15 Hillsbrad-bondekarle og rapportér tilbage til Darthalia i Tarrenmølle.", d="Nyheden om angrebet på de nordlige gårde har sat byfolket i panik. Fremragende.\n\nVores Dødsstalkere melder om bondekarle, der flygter ud på markerne i det sydlige Hillsbrad. De dumme tror, at de kan gemme sig i frugthaverne og undslippe deres skæbne.\n\nBevis dem forkerte, <Name>. Vend tilbage til Hillsbrad-markerne og opsøg de krybende bondekarle. Læg dem øde i vores Mørke Dames navn.\n\nAfsted!"},
  [529] = {n="Slaget ved Hillsbrad", l="Dræb Smed Værktan og 4 Hillsbrad-smedelærlinge.\n\nHent en forsendelse jern og rapportér tilbage til Darthalia i Tarrenmølle.", d="Menneskene i Hillsbrad har budt på uventet modstand. Problemet ser ud til at være, at byfolket bliver bevæbnet af den lokale smed. Vi må lukke alle forsyningslinjer.\n\nDin mission er at henrette Smed Værktan. Slå også hans lærlinge ihjel. Mens du er der, skal du tage en forsendelse jern med tilbage fra deres lager. Forsyningerne kommer til nytte, når vi er færdige med at erobre Hillsbrad og begynder at jævne Sydstranden med jorden."},
  [530] = {n="En Ægtemands Hævn", l="Dræb Valdred Muræn.\n\nBring hans hænder til Raleig Andreæn i Undergrunden.", d="Valdred, der engang var min gode ven, var min kones morder. Selvom jeg er ude af stand til at sørge, længes jeg dog efter hævn. Hvis du dræber Valdred og bringer mig hans forbandede hænder, belønner jeg dig.\n\nSidst jeg hørte, var han ved Gråmanke-muren i det sydlige Sølvfyrreskoven og forsøgte at flygte ind i kongeriget Gilnæas."},
  [532] = {n="Slaget ved Hillsbrad", l="Dræb Dommer Brændside og 5 Hillsbrad-rådsmedlemmer. Ødelæg Hillsbrad-proklamationen. Stjæl Hillsbrad-byregistret. Rapportér derefter tilbage til Darthalia i Tarrenmølle.", d="Byen Hillsbrad er i opløsning, og vi tror, den snart falder. Vi må dog holde ud i vores hensynsløshed, indtil menneskepakket er udryddet fra forbjergene for evigt.\n\nTrods deres overvældende tab samler menneskene sig om deres ledelse og kæmper videre. Vi må eliminere deres leder, Dommer Brændside, samt byrådet. Ødelæg også deres højt ansete politiske dokument, Hillsbrad-proklamationen. Og når du nu alligevel er i gang, så stjæl byregistret."},
  [533] = {n="Infiltrering", l="Indhent oplysninger om Gulddyrs opholdssted for Krusk i Tarrenmølle.", d="Endelig begynder vi at høre rygter og snak, og vi finder beviser på Gulddyrs opholdssted. Menneskene har flyttet ham rundt, men vi indsnævrer vores søgning og fokuserer på den store Syndikat-lejr lige nord herfra.\n\nTag derhen, <Name>, og bring tilbage, hvad end du kan skaffe af oplysninger."},
  [535] = {n="Valæk", l="Bring et krus Sydstranden-stout til Valæk i Syndikatets lejr.", d="Urrgh... Såret og døende og konfronteret med fjenden.\n\nJeg er ingen tvivl om, at du dræber mig alligevel, men hvis du bringer mig noget Sydstranden-stout -- jeres slags drikker jo, gør de ikke? -- så fortæller jeg dig, hvad du vil vide."},
  [536] = {n="Ned langs kysten", l="Dræb 10 Revetfinne-tidevandsjægere og 10 Revetfinne-orakler for Løjtnant Farren Ørnelle i Sydstranden.", d="Overført fra Stormvinds bygarde til Sydstranden, en by der ser ud til at være forladt... Lugten af havnen dag og nat.\n\nLad være med at nævne gamle Rødstig... Han vil have mig til at tage mig af mudderfiskene. Ha!\n\nJeg kan næsten ikke overvinde mig selv til at tage ud til nogle af de voksede fisk nede ved Vestkysten. Hvis du ville gå i mit sted og tage dig af dem, ville jeg sætte pris på det."},
  [538] = {n="Sydstranden", l="Tal med Vidensmester Nips i Sydstranden.", d="<Name>. Hvis du ikke har noget imod en lang rejse, har jeg en opgave til dig, nemlig at hjælpe Stormvind med at fylde sit bibliotek igen.\n\nDet gamle kongerige Alterac faldt efter den store krig, og det havde en stor samling bøger. Det er en tragedie, at byen er lagt øde, men endnu mere tragisk er al den viden, der gik tabt! Vi må redde det, vi kan.\n\nSydstranden er den nærmeste by til Ruinerne af Alterac. Tag derhen og tal med Vidensmester Nips. Han kan vise dig vej til ruinerne og til, hvilke bøger der måske findes dér."},
  [539] = {n="Slaget ved Hillsbrad", l="Dræb Formand Bånd og 10 Hillsbrad-minearbejdere, og rapportér tilbage til Darthalia i Tarrenmølle.", d="Hillsbrad-byregistret viser, at Azureload-minen er under Alliancens kontrol. Desuden er minen en vigtig kilde til jernmalm for Alliancens våbenlagre.\n\nSelvom vi har givet byen Hillsbrad et afgørende slag, støtter og beskytter Alliancen stadig Azureload-minen med liv og sjæl.\n\nMinen ligger lige syd for Hillsbrad. Tag derhen og slå formanden ihjel, et menneske ved navn Bånd. Dræb også hans minearbejdere. Det burde sende et klart budskab til Alliancen."},
  [540] = {n="Bevarelse af viden", l="Bring 5 genfundne tomer og den slidte læderbog, der indeholder Grimleks Arm, til Vidensmester Nips i Sydstranden.", d="De udyrlige oger holder nu til i Alteracs ruiner, og jeg gyser ved tanken om, hvad de laver med de dyrebare bøger, der stadig er dér. Du må genfinde, hvad du kan!\n\nTræd ind i Ruinerne af Alterac og led efter tomer, som ogrene har plyndret. Find hvad du kan, og bring dem til mig, men led især efter én bog: Grimleks Arm. Den indeholder gammel trollelære, som jeg må lære, og Ruinerne af Alterac var det sidste kendte sted, hvor et intakt eksemplar af denne bog fandtes."},
  [541] = {n="Slaget ved Hillsbrad", l="Rejs til Garok-bakken og dræb 10 Bjergbestigere, 8 Riffelskytter, 4 Præster og Kaptajn Jernbakke, og rapportér tilbage til Darthalia i Tarrenmølle.", d="Dværge, der hjælper menneskene? Pokkers også, de beskidte små bæster.\n\nVi skal teste styrken af den såkaldte Alliance. Vi får se, hvor ivrige de små ankelbankere er efter at hjælpe menneskene, når de mærker vores vrede. Vi ved præcis, hvor deres højborg ligger i dette område.\n\nDe har etableret en kaserne i det sydøstlige Hillsbrad langs Thoradins Mur, kaldet Garok-bakken. Slagets sidste mission er at belejre Garok-bakken, <Class>. Kaptajn Jernbakke, deres leder, må dø."},
  [543] = {n="Pæreknold-tiaraen", l="Bring Pæreknold-tiaraen til Remington Højkilde i Stormvind.", d="Pæreknold-tiaraen er et gammelt arvestykke fra Pæreknold-\"adelen\" - den herskende familie i Alterac, før kongeriget faldt i ruin. Det siges, at den blev skabt af mesterjuvelerer i Jernsmede og påsat de fineste smaragder.\n\nDa Alterac blev ødelagt, gik tiaraen tabt, men der går rygter om, at en Oger-magiker, Grel'borg Gnieren, fandt tiaraen og nu vandrer rundt i Ruinerne af Alterac på jagt efter flere skatte.\n\nVi vil bede dig skaffe tiaraen til os."},
  [544] = {n="Fangeflugt", l="Find forræderne og genfind deres artefakter, og vend så tilbage til mig, <Name>.", d="Jeg kom til Tarrenmølle for at forske, men må nu løse en krise. Se, for et par måneder siden flygtede fire De Forladte fra Undergrunden. De vendte ryggen til deres brødre, men det værste er... de stjal fra Den Mørke Dame.\n\nDisse tyve brød ind i et sikkert hvælving og stjal fire artefakter, genstande vores apotekere havde brug for i visse studier. Silvanas vil have artefakterne tilbage.\n\nTyvene flygtede fra Undergrunden til Dalarn, og disse troldmænd satte dem i karantæne i Lordamere-interneringslejren."},
  [545] = {n="Dalarn-patruljerne", l="Dræb 6 Dalarn-kaldere og 8 Elementar-slaver, og vend så tilbage til Magus Tomglimt i Tarrenmølle.", d="Før den mystisk forsvandt, var der en enorm magisk barriere omkring den nyopbyggede by Dalarn. Jeg er ligeglad med, hvad der fik sådan et magisk vidunder til at svigte, men jeg bryder mig om, at de nyeksponerede udkanter af deres by måske gemmer værdifulde magiske skatte. Rester af ruinerne, som den nye by er bygget på.\n\nMen området patruljeres af troldmændene og deres elementar-slaver.\n\nSå jag dem, og vend tilbage, når antallet er tilstrækkeligt reduceret."},
  [546] = {n="Dødens Souvenirer", l="Dødevagt Samsing i Tarrenmølle vil have 30 Hillsbrad-menneskekranier.", d="Jeg hører, at Darthalia har hvervet dig til at føre krig mod menneskene i Hillsbrad. Hvor er jeg misundelig. . .\n\nMens du har det hele sjovt -- slagter mennesker, plyndrer byen, terroriserer uskyldige -- står jeg fast her i Tarrenmølle og holder vagt.\n\nMon du har medlidenhed med en gammel dødevagt som mig? Se, jeg samler menneskekranier. Og du vil kæmpe mod mennesker i rimelig lang tid. I løbet af din lange kamp kan du bringe mig 30 kranier, så vil jeg sørge for, at det bliver umagen værd."},
  [547] = {n="Humbærts Sværd", l="Hent Dødevagt Humbærts sværd fra Garok-bakken og bring det tilbage til ham i Tarrenmølle.", d="Højeksekutor Darthalia sendte mig for at holde øje med Garok-bakken på afstand. Jeg havde slået lejr lige uden for synsvidde. Men da morgenen kom, og jeg skulle koge vand, gik jeg ud for at samle brænde.\n\nDa jeg vendte tilbage til lejren, opdagede jeg, at mit udstyr var væk.\n\nTilsyneladende var nogle dværgiske spejdere fra Garok-bakken forbi og stak af med det. Jeg har brug for mit sværd! Hvis du kan skaffe det tilbage til mig, ville jeg være så taknemmelig. Der er så mange dværge derinde... det bliver ret svært at finde den beskidte lille tyv, der stjal det."},
  [549] = {n="EFTERLYST: Syndikat-personale", l="Dræb 10 Syndikat-skurke og 10 Syndikat-vagter. Vend tilbage til Højeksekutor Darthalia i Tarrenmølle for din belønning.", d="I Frue Silvanas' navn er alle medlemmer af organisationen kendt som Syndikatet eftersøgt døde. De, der bliver taget i forvaring eller til fange, vil blive henrettet uden videre. De menes for øjeblikket at samle sig i ruinerne af Durnholde-fæstningen, sydøst for Tarrenmølle.\n\nEn flot belønning tilbydes alle, der bringer beviser for deres gerninger til Højeksekutor Darthalia."},
  [550] = {n="Slaget ved Hillsbrad", l="Tag Darthalias Forseglede Anbefaling med til Varimatras i Undergrunden.", d="Fordi du kæmpede med så stor tapperhed og udholdenhed i Slaget ved Hillsbrad, har jeg skrevet denne anbefaling, der priser dine heltegerninger i kamp, så højkommandoen kan anerkende dem.\n\nTag denne forseglede anbefaling med til Varimatras i Undergrunden. Gå med stolthed, <Class>."},
  [552] = {n="Helkulars Hævn", l="Hent Helkulars Stav fra Yetien og bring den tilbage til Novice Taivand i Tarrenmølle.", d="Mester Helkular var næsten færdig med sin forvandling til en Liske, da en menneskelig lynchemob opdagede hans ritualhule i bakkerne og dræbte ham brutalt. For at gøre det værre begravede de hans lig på kirkegården i Sydstranden.\n\nSådan en respektløshed over for den store troldmand er uacceptabel. Som hans lærling vil jeg sørge for, at hævnens regn falder over byen Sydstranden.\n\nVi får først brug for Helkulars Stav. Yetien overtog hans ritualhule. Utvivlsomt har et af udyrene den."},
  [553] = {n="Helkulars Hævn", l="Lad Helkulars Stav blive opladt med kræfterne fra Azels Flamme, Verazs Flamme og Uzels Flamme.\n\nStød den opladede stav ned i Helkulars grav i Sydstranden.", d="Her, tag Helkulars Stav. Du får brug for den.\n\nHelkular lavede 3 seremonielle bål som en del af sin mægtigste besværgelse. Azels Flamme og Verazs Flamme ligger i Forbjergshulerne. Uzels Flamme ligger i en hule over hulerne, længere nord i bjergene.\n\nHelkulars Stav skal oplades fra hver af de tre flammer. Når ritualet er fuldført, skal du støde staven ned i Helkulars grav i Sydstranden, den tungt bevogtede menneskeby mod syd. Hævnen skal være vores!"},
  [555] = {n="Beroligende Skildpaddebisque", l="Bring 10 stykker Skildpaddekød og nogle Beroligende Krydderier til Kok Jessen i Sydstranden.", d="Hvis der er én ting, du vil lære om Sydstranden, så er det, at vi har nogle af de bedste retter nord for Stormvind!\n\nTag min hemmelige opskrift på Skildpaddebisque, for eksempel. Jeg har kendt folk, der har rejst helt fra Mørkeshire bare for at nyde en skål. Apropos har jeg ikke kunnet lave den for nylig. Jeg plejede selv at tage op forbi Dalarn til Lordamere-søen for at jagte Knipsekæbere, men det er bare for farligt nu. Hvis du bringer mig noget Skildpaddekød fra Knipsekæberne mod nord og Beroligende Krydderier, så laver jeg en omgang!"},
  [556] = {n="Stenmærker", l="Bring 10 Slidte Stenmærker til Vogter Bel'varil i Tarrenmølle.", d="Et bemærkelsesværdigt talent hos Dalarns troldmænd er deres fortrolighed med elementarer: mægtige væsener fra andre dimensioner. Troldmændene bruger magiske mærker som middel til at kontrollere disse elementarer. Magus Tomglimt vil gerne have nogle af disse mærker at studere.\n\nGå ind på Dalarns troldmænds territorier, vest for Hillsbrad, og saml mærkerne.\n\nDu kan måske finde mærkerne på enhver borger i Dalarn, men jeg foreslår, at du jager ved interneringslejren. Den er sikrere end Dalarn selv."},
  [557] = {n="Bindende Armbeskyttere", l="Bring 4 Jordbindende Armbeskyttere til Vogter Bel'varil i Tarrenmølle.", d="Magusen vil have travlt med at studere de stenmærker, du samlede, men jeg ved, at han før eller siden vil ønske eksempler på deres modstykke: bindende armbeskyttere. Disse sættes om håndleddene på rigtige elementarer og binder dem til magikerens tjeneste.\n\nJag elementarer i ruinerne af Dalarn, saml deres Jordbindende Armbeskyttere, og Magusen bliver glad."},
  [559] = {n="Farrens Bevis", l="Saml 10 Mudderfisk-hoveder fra mudderfiskene på Vestkysten for Løjtnant Farren Ørnelle i Sydstranden.", d="Kan du tro det, <Name>? Rødstig var ikke tilfreds med alle de mudderfisk, vi dræbte--åh nej, vær nu ikke beskeden, du havde en finger med i spillet. Nu vil han have, at jeg bringer bevis for de døde, hugget af kolde, slimede mudderfisk-hoveder, som han kan godkende."},
  [564] = {n="Dyr Plage", l="Darren Malvev fra Sydstranden vil have dig til at dræbe 8 Bjergløver og 10 Klodsede Bjergløver.", d="Der er intet, der irriterer mig mere end at miste de her smukke heste. Og tro mig, vi har mistet en hel del til de irriterende udøde krybere, den forbandede Syndikat-bande og alle de andre usle skurke, der roder rundt i disse egne.\n\nMen jeg sværger på min gamle bedstefars grav, at der ikke er nogen større plage for vores heste her end de Bjergløver oppe i Alterac-bjergene. De kommer altid ned fra bakkerne og gør mit liv besværligt!\n\nSå du synes, du er en helt? Så gå hen og gør noget ved det!"},
  [565] = {n="Bartolos Yetipelskappe", l="Bring Bartolo Ginsæt fra Sydstranden en Rulle Uld, en Bjergmandens Kappe, Fint Garn og 10 klumper Yetipels.", d="Jeg, den store Bartolo, skal lave til dig den verdensberømte, Alliancen-kendte Yetipelskappe!\n\nRejs rundt på planeten og find dig en bedre kappe, jeg udfordrer dig. Åh vent, hvad er det, lille <Race>? \"Bartolo, der findes ingen finere kappe!\" Ja, ja! Det har jeg hørt før.\n\nBartolo kræver selvfølgelig en Rulle Uld, en Bjergmandens Kappe lavet af en dygtig læderarbejder, Fint Garn og Yetipels! Bring mig disse ting, så bliver du en glad kunde!"},
  [567] = {n="Farligt!", l="Højeksekutor Darthalia fra Tarrenmølle udlover en dusør på Skriver Horrace Hvidhest, Borger Vilkes, Minearbejder Hakkett og Bonde Kalaba.", d="Farligt!\n\nFølgende mennesker fra Hillsbrad er blevet anset for farlige og er markeret til dusør af Højeksekutor Darthalia:\n\nSkriver Horrace Hvidhest. Eftersøgt for mordet på Dødevagt Toma.\n\nBorger Vilkes. Eftersøgt for mordet på Apoteker Eli.\n\nMinearbejder Hakkett. Eftersøgt for mordet på Dødsstalker Stegen.\n\nBonde Kalaba. Eftersøgt for baghold på forsyninger fra Undergrunden.\n\nAlle disse fjender gemmer sig og vil være svære at finde. En belønning udbetales ved meddelelse om deres død."},
  [575] = {n="Udbud og Efterspørgsel", l="Bring 2 Store Flodkrokolisk-skind til Dryppelik i Bytteviken.", d="\"Den fineste læderhåndværker i Sydhavet og i verden, både gammel og ny.\" Sådan kalder de mig. Mig! Dryppelik! Den fineste lædera... Øhm. Nå.\n\nMine lædervarer er kendt vidt og bredt som de mest udsøgte, en kender's valg!\n\nJeg har lige modtaget en ordre fra Direktør Riddlevox fra Tinkerforeningen på et dusin af hans yndlingsstøvler af Excelsior-serien. Faktisk vores bedst sælgende.\n\nFor at komme i gang med grundformen skal jeg bruge krokolisk-skind fra krokodillerne langs floden i det nordlige Kvælerdorn."},
  [579] = {n="Stormvinds Bibliotek"},
  [581] = {n="Jagten på Yenniku", l="Bring 9 Blodskalp-hugtænder til Nimboya i Grom'gol-basislejren.", d="Der er en undergang, ja. En undergang over min høvdings yngste søn, Yenniku. Som skik er hos vores folk, blev han givet til Gurubashi-trollene i Zul'Gurub, men efter at min stamme, Mørkspyd-stammen, forlod med orken Thrall, gik stakkels Yenniku tabt for os. Jeg blev sendt fra det fjerne Orgrimmar, tilbage til Kvælerdorn, for at lede efter min høvdings søn.\n\nOg jeg tror, at Blodskalp-stammen har ham.\n\nHvis du vil hjælpe mig, så jag Blodskalperne. Du finder dem nok mod nord. Saml deres hugtænder og vend tilbage til mig."},
  [583] = {n="Velkommen til junglen", l="Tal med Hemmet Jagtvarys.", d="Velkommen til Kvælerdorn!\n\nMåske er du ikke klar over det, men den dværg derovre er den ene og eneste Hemmet Jagtvarys, berømt krigshelt for Alliancen og mester i storvildtjagt. Han er ikke typen, der byder fremmede velkommen i sin lejr, men du ser ud til at have set en hel del action i din tid, <Class>.\n\nSom veteran fra mange slag selv har Mester Jagtvarys en blød plet for medhelte.\n\nGå og tal med ham. Måske kan han give dig nogle jagttips."},
  [596] = {n="Blodige Knoglehalskæder", l="Bring 25 Blodige Knoglehalskæder til Kin'weelay i Grom'gol-basislejren.", d="Jeg blev sendt til Grom'gol for at hjælpe Nimboya med hans søgen, men... jeg har også mine egne grunde til at være her.\n\nBlodskalp-stammen er vores stammes fjende. At samle trofæer fra vores fjender giver os magt over dem. Du kan hjælpe vores stamme ved at jage vores fjender.\n\nDe holder til mod nord. Slå Blodskalp-troldene ihjel og tag deres blodige knoglehalskæder. Saml mange, så bliver din belønning stor."},
  [600] = {n="Ventureselskabets Minedrift", l="Bring 10 Syngende Blå Krystaller til Crank Brusebob i Bytteviken.", d="Ventureselskabet har en række operationer gennem Kvælerdorn, som forhindrer hårdtarbejdende goblins, som mig, i at tjene ærligt guld! Hjælp mig, du må hjælpe mig!\n\nVentureselskabet graver nord for Krystalåre-minen. De kan ikke komme ind i minen på grund af alle basiliskerne, men de kan stadig grave Syngende Krystaller op fra de omkringliggende bakker.\n\nTag deres krystaller fra dem, og vis dem, at de ikke har frit spil i junglen.\n\nOg... øh... bring mig de krystaller som bevis!"},
  [605] = {n="Syngende Blå Skår", l="Bring 10 Syngende Krystalskår til Crank Brusebob.", d="De Syngende Krystaller er unikke for Kvælerdorn og er meget værdifulde for visse parter. Jeg kan flytte de krystaller, men det forbandede Ventureselskab gør det svært for en ærlig iværksætter som mig selv at samle nogen!\n\nJeg vil gerne ansætte dig.\n\nBasiliskerne i Kvælerdorn spiser krystallen. Det giver dem deres hærdede hud, og nogle gange kan der høstes krystal af ganske god kvalitet fra den.\n\nDu kan få den fra enhver basilisk, men de mindre ondskabsfulde findes langs kysterne syd for Zul'Kunda, mod nord."},
  [606] = {n="Skræmme Shaky", l="Bring 5 Tågedal-indvolde til \"Shaky\" Filippe i Bytteviken.", d="Hvis der er én ting, jeg ikke kan udstå, så er det folk, der ikke betaler deres gæld fra spil! Og der er en masse folk, der skylder mig. Tror du, du kan hjælpe mig med at inddrive den?\n\nFør alt andet er der \"Shaky\" Filippe nede ved havnen. Han skylder mig en masse efter sidste uges spil, og jeg vil have mit! Men for at få det, må vi skræmme ham.\n\nGå ud af byen og jag Ældre Tågedal-gorillaer. Find et pænt udvalg af indvolde, og tag dem så med til Shaky. Lad ikke på, at de er fra et dyr; lad ham tro det værste."},
  [607] = {n="Tilbage til MacKinley", l="Bring Shakys Betaling til \"Havulven\" MacKinley", d="Her, tag denne pung og giv den til Havulven. Og fortæl ham, at jeg havde tænkt mig at betale ham tilbage! Jeg sværger!!\n\nJeg blev bare lidt beruset og faldt ud af kurs, og... du ved, hvordan det er. Han vil forstå det - du behøver ikke at blive grov!"},
  [609] = {n="Voodoo-gælden", l="Bring Maurys Klumpfod, Jon-Jons Gyldne Kikkert og Chuckys Enorme Ring til \"Havulven\" MacKinley i Bytteviken.", d="Min liste bliver kortere, men der er stadig folk, der skylder mig.\n\nNæste er Maury \"Klumpfod\" Vilkins, Jon-Jon Kragen og Chucky \"Ti Tommelfingre.\"\n\nDisse skørbuktige hunde har haft gæld stående i månedsvis, og jeg troede, de var stukket af byen for at undgå at betale! Senere hørte jeg, at de er forbandede og fortryllede og nu vandrer rundt i junglens ruiner. Men jeg er ligeglad med, hvad deres skæbne er - jeg vil have, hvad der er mit!\n\nDe er ved Aboraz-ruinerne og Jubuwal-ruinerne, nordøst herfra. Find dem, og inddriv."},
  [613] = {n="At knække Maurys Klumpfod", l="Bring Maurys Nøgle til \"Havulven\" MacKinley i Bytteviken.", d="Forbandelser! Den tølper Maury satte en lås på sin fod, og jeg kan ikke åbne den! Hans bytte ligger inde i foden, og det er det, han skylder mig!\n\nVi må finde nøglen til at åbne låsen. Maury var kendt for at spille om penge med Mosh'Ogg-ogerne ved deres høj mod nordøst. Og han fortalte mig, da han stadig var i live, at sidste gang han gik til højen, blev han jaget væk, efter at have vundet for meget. Måske har ogerne derovre hans nøgle.\n\nMen hvis de har, må du måske dræbe et læs af dem for at finde den rigtige..."},
  [629] = {n="Det Onde Rev", l="Bring et Tavleskår til Kin'weelay i Grom'gol-basislejren.", d="For længe siden fik et stort jordskælv en gammel trollby til at synke under vandet ved Den Vilde Kyst mod nordvest. Vi kalder stedet Det Onde Rev, for mudderfiskene bor nu i byens ruiner og angriber enhver, der kommer for tæt på.\n\nDer er en gammel tavle blandt disse ruiner, som fortæller den gamle historie om Grimlek, en helt fra trollenes legender. Historien er hellig for Mørkspyd-stammen, og selvom tavlen er for stor til at flytte, vil jeg have et skår af den, der kan helliggøres i vores nye hjem i Orgrimmar."},
  [631] = {n="Thandol-spændet", l="Rhag Garmason vil have dig til at finde Gamle Rustlås.", d="Et voldsomt brag rullede gennem bakkerne. Det var forfærdeligt, siger jeg dig!\n\nGode soldater døde under forsvaret af Thandol-spændet. Langfletten siger, at vi vil hævne os på Mørkjernsdværgene, inden det hele er forbi.\n\nVi er i en stor knibe, men jeg ser ingen forstærkninger i sigte. Langfletten sendte Gamle Rustlås for at spejde den østlige bro og se, om vi kunne sikre den.\n\nDet var for dage siden. Vi har ikke mandskab til at lede efter ham, mens Dun Mødr er under belejring.\n\nMåske kan du finde ham..."},
  [632] = {n="Thandol-spændet", l="Rapportér tilbage til Rhag Garmasøn og vis ham pergamentet du fandt på Rustlås' lig.", d="Det ser ud til at stakkels Gamle Rustlås løb ind i et Mørkjern-baghold. Du bemærker et pergament ved hans krampagtige næve.\n\nRapportér de dystre nyheder til Rhag Garmasøn og vis ham hvad du fandt."},
  [633] = {n="Thandol-spændet", l="Ødelæg sprængstofdepotet.", d="Åh nej! Stakkels Rustlås. Det er i sandhed en tragedie.\n\nVi må ikke lade hans død gå forgæves. Dette pergament du fandt viser at Kam Dybfuror, hjernen bag det oprindelige angreb, fik et lager sprængstoffer gemt lige på den anden side af Thandol-spændet, i Arathi-højlandet.\n\nHvis sprængstofferne når broen, bliver vores vigtigste forsyningslinje mod nord skåret over! Depotet skal ødelægges, <Name>! Vend tilbage til mig når din mission er fuldført.\n\nDu er vores eneste håb."},
  [634] = {n="Bøn til Alliancen", l="Find Kaptajn Nials i Flygtningeodden.", d="Jeg beder dig om endnu en lille tjeneste, <Class>. Vi venter på forstærkningerne fra Jernsmede. Men Rogo ved at der findes en Alliance-lejr mod nord i Arathi-højlandet, i Flygtningeodden.\n\nRejs derhen og find Kaptajn Nials. Spørg den gode kaptajn om Alliancen kan undvære nogle soldater til at hjælpe os med at generobre Dun Mødr og Thandol-spændet."},
  [635] = {n="Krystallen i Bjergene", l="Find krystallen fra din vision.", d="Denne skærv pulserer når du holder den...\n\nDu mærker en bøn fra skærven, som om nogen forsøger at kommunikere, nogen der desperat har brug for din hjælp.\n\nEn vision dukker op i dit sind - af de nordlige bjerge i Arathi, og af en strålende krystal der rager op af jorden dér.\n\nDu føler dig draget mod stedet."},
  [642] = {n="Prinsessen i Fangenskab", l="Saml 12 Myzrael-støvkorn, og bring dem derefter til de Irisserende Skår i Tørhvisker-kløften.", d="Mit navn er Myzrael. Jeg er en jordens prinsesse, og mine fangevogtere, kæmperne, har fanget mig dybt under Arathi-højlandet. Disse krystalskår er den eneste måde jeg kan tale med overfladeverdenen.\n\nVær sød at hjælpe mig. Kæmpernes allierede, Tørhvisker-kobolderne, har et skår som dette i deres Tørhvisker-kløft, mod øst. For at drive klyngen må du samle Myzrael-støvkorn fra kobolderne og anbringe dem på den.\n\nJeg beder dig, <Name>, hjælp mig!"},
  [659] = {n="Tegn på en ny pest?", l="Find Kvæ og Kinelori ved Go'Shek-gården i Arathi-højlandet.", d="Hils, og velkommen, <Name>. Jeg leder en gruppe eventyrere der undersøger mærkelige hændelser i dette område.\n\nMin fætter i Hillsbrad aflivede for nylig sin hund Stanley, fordi dyret magisk var vokset til en enorm størrelse og angreb alle der kom i nærheden.\n\nJeg tror de udøde er involveret, og vi leder efter tegn der kan bevise det.\n\nTo af mine kammerater, Kvæ og Kinelori, tog til Go'Shek-gården i Arathi-højlandet, og de har ikke meldt sig i flere dage. Kan du finde dem til mig? Jeg bliver bekymret."},
  [671] = {n="Ond Magi", l="Skaf 10 Blodsten-amuletter til Tor'gan i Hammerfald.", d="Jeg har mærket en underlig stemning i luften... en fornemmelse der syder i mit blod. Jeg havde mine mistanker. Jeg drog af sted for at finde kilden til min uro og opdagede mod vest, ved Nordfold-herregården, rester af dæmonkaldelse. Da jeg kom tæt på, begyndte mit blod at koge, og vreden i mig voksede.\n\nPå jorden fik jeg øje på en blodsten-amulet, brugt til at hjælpe med dæmonkaldelse. Den jeg fandt var dog opbrugt. Jeg har brug for en ny at undersøge, men jeg tør ikke vende tilbage til herregården. Kan du bringe mig nogle?"},
  [672] = {n="Ånder Løftes", l="Skaf 10 Højlands-raptorojne fra Højlands-skridtere og Højlands-piskere til Tor'gan i Hammerfald.", d="Vi forsøgte at falde til, muntre ham op, fortalte ham historier om vores mægtige by Orgrimgrad i Kalimdør, men intet kunne rykke ham.\n\nHistorier om vores unge krigshøvding Trael, der bærer Orgrims rustning og hammer... men måske, måske! En demonstration af vores nyfundne shamanistiske magi kunne give ham nyt håb. Det er værd at prøve!\n\nEt lille objekt kunne vi lave til ham, ja... Bring mig nogle raptorojne, så skal jeg se hvad jeg kan gøre."},
  [676] = {n="Hammeren Kan Falde", l="Dræb 8 Klippenæve-oger og 10 Klippenæve-håndhævere, og find derefter Drum Ondt i Hammerfald-forposten i Arathi-højlandet.", d="Svagelinger... alle sammen. Du, <Class>, hvad glor du på? Tror du at du er noget særligt, hva'? Hvorfor ikke bevise det?\n\nHammerfald-forposten i Arathi er under angreb. Medmindre vi sender hjælp snart, er deres undergang nært forestående.\n\nMen før du styrter afsted, kan du lige teste dine evner. Nordøst for Strømgård i Arathi ligger en oger-høj, beboet af Klippenæve-stammen. Når du kan klare ogerne og håndhæverne dér, så rapportér til Drum Ondt i Hammerfald."},
  [677] = {n="Til Våben", l="Dræb 10 Visnebark-øksekastere, 10 Hovedjægere og 8 Heksedoktorer, og vend tilbage til Drum Ondt i Hammerfald-forposten.", d="Visnebark-trollene og Klippenæve-ogerne i Arathi arbejder sammen om at drive os fra dette land, men vi skal ikke møde vores skæbne ved deres eller nogen andres hånd. Vi vil slå dem ihjel og vise dem at også vi har et hjem her.\n\nTrollene vendte ryggen til os; ogerne ville bruge os som mad og sengehalm, hvis vi tillod dem det - det må ikke ske.\n\nVi starter vores angreb på Visnebark-trollene sydfor her. Slå dem ihjel i flok, og vend kun tilbage når deres lejre løber tykt af blod."},
  [678] = {n="Til Våben", l="Dræb 10 Klippenæve-brutaler og 4 Klippenæve-magikere, og vend tilbage til Drum Ondt i Hammerfald-forposten.", d="Din styrke er tydelig, <Name>. Nu skal vi se hvordan du klarer dig mod en rigtig fjende.\n\nKlippenæverne har et hi sydvest herfra, mod den dværgiske bro, og hvis jeg ikke tager fejl, vil brutalerne og magikerne dér byde dig en større udfordring - det har de hidtil gjort mod os.\n\nSlå så mange du kan, og kom til mig i legeme når du lykkes, eller kom til mig i ånd når du fejler. Jeg vil rose din udholdenhed i kamp under alle omstændigheder."},
  [679] = {n="Til Våben", l="Dræb 15 Klippenæve-shamaner og 10 Klippenæve-herrer, og vend tilbage til Drum Ondt i Hammerfald-forposten.", d="Bestiens hoved er klar til at blive taget af... med stor kraft, <Name>. Du har vist alle tegn på at du kan hjælpe os med dette sidste mægtige slag. Lederne af disse angreb har gjort deres hule i ruinerne af Strømgård, et skrigende symbol på menneskelig skrøbelighed.\n\nFind og slå de Klippenæve-herrer og deres håndlangershamaner ihjel, de som ville drive os fra disse lande."},
  [680] = {n="Den Virkelige Trussel", l="Slå Or'Kalar ihjel og bring hans hoved til Korin Ondt i Hammerfald-forposten.", d="Du tjener min mand godt, <Class>, men han ved ikke hvorfor Hammerfald er under angreb.\n\nOr'Kalar, Mug'thols brik i Strømgård, har et voldsomt had til min mand og ønsker intet mere end min mands død, fordi han besejrede ham for år siden.\n\nMine varsler fortæller mig at Or'Kalar har lagt en fælde for min mand, så jeg har skjult tegn på ogrens tilstedeværelse for ham.\n\nMin mand vil storme afsted tankeløst, hvis han hører om ogrens opholdssted, og jeg beder dig om hjælp til at slå skabningen ihjel."},
  [682] = {n="Strømgård-mærker", l="Bring Strømgård-mærker til Kaptajn Nials i Flygtningeodden.", d="Syndikatet i Strømgård kæmper mod vores militsenhed dér. For at lokke pøblen til at kæmpe mod vores mere disciplinerede tropper har Syndikatets ledere sat en dusør på vores soldater og belønner med guld for hvert Strømgård-mærke man samler fra dræbte militsfolk.\n\nVi vil have de mærker hentet hjem - vi kan ikke tillade de snigmordere at tage trofæer fra vores modige faldne!\n\nTræd ind i det Syndikat-kontrollerede område i Strømgård, og jag dem efter vores mærker."},
  [684] = {n="EFTERLYST: Marez Hætte", l="Bring Marez' hoved til Kaptajn Nials i Flygtningeodden.", d="Der er sat en dusør på hovedet af Marez Hætte, en højtstående rådgiver og agent for Syndikatet. Hun blev sidst set i det Syndikat-kontrollerede område i Strømgård.\n\nDusøren kan indløses hos Kaptajn Nials.\n\nVær advaret: Marez er en dygtig og listig hekseri-mester, kendt for sin omgang med dæmoner. Der bør udvises yderste forsigtighed når man jager hende."},
  [685] = {n="EFTERLYST: Otto og Falkekrone", l="Bring Ottos hoved og Falkekrones hoved til Kaptajn Nials i Flygtningeodden.", d="Strømgård-militsen har sat dusører på hovedet af Lord Falkekrone og hans livvagt Otto. Falkekrone leder Syndikatets indsats i Arathi-højlandet, og hans død ville skabe store forstyrrelser i den indsats.\n\nHans livvagt Otto er ikke noget strategisk mål, men er en vild modstander og har dræbt snesevis af vores forsvarere.\n\nDeres dusører kan indløses hos Kaptajn Nials."},
  [690] = {n="Malins Anmodning", l="Find Skuerto i Flygtningeodden i Arathi-højlandet.", d="Hilsen, <Name>. Du har en eventyrers udseende over dig, og jeg har en opgave der trænger til at blive passet.\n\nÆrkemager Trelan, min oprindelige mester, flygtede fra Strømgård i Arathi-højlandet for ikke så længe siden, og han har bedt mig hjælpe ham med at genfinde nogle af de ting han efterlod.\n\nByen faldt under belejring, og han forsøgte at forsvare Arathor-tårnet, men forgæves. Jeg har allerede agenter i højlandet, men de har bedt om at jeg sender mere hjælp. Er du interesseret?"},
  [691] = {n="Værd Sin Vægt i Guld", l="Find 10 Visnebark-hugtænder, 4 Visnebark-medicinposer og en Skyggejæger-kniv til Lærling Kryten i Flygtningeodden.", d="Ærkemager Malin sendte Skuerto og mig hertil for at samle reagenser til ham. Jeg var rådvild over hvordan jeg skulle samle tingene, men nu hvor du er her, tror jeg mit problem er løst.\n\nJeg har brug for følgende: Visnebark-hugtænder, Visnebark-medicinposer og en skyggejæger-kniv.\n\nKan du finde dem til mig? Visnebark lever sydøst for Arathi."},
  [705] = {n="Perledykning", l="Bring 9 Blå Perler til Rigglefnug i Ødelandene.", d="Ødelandene er et hårdt sted, fyldt med ondskabsfulde rovdyr og fræk åd. Skræmmende, især for en lille goblin. For at overleve må jeg være snedig!\n\nJeg kender opskriften på blitzbomber. Dem bruger jeg til at skræmme dyrelivet væk. Men jeg er ved at løbe tør for en af ingredienserne: knust blåperle-pulver. Skaf mig noget, så gør jeg det besværet værd.\n\nHeh, og jeg håber du har gode støvler på. De Blå Perler jeg skal bruge findes i muslinger ved Det Onde Rev.\n\nJa, Det Onde Rev i Kvælerdorn!"},
  [707] = {n="Jernbånd Vil Have Dig!", l="Tal med Prospektor Jernbånd ved Jernbånds Udgravningssted i Modansøen.", d="<Name>. Jeg har modtaget rapporter fra Prospektor Jernbånd ved hans udgravningssted i Modansøen - han har brug for noget benarbejde vedrørende en af vores andre udgravninger.\n\nJeg har ikke flere detaljer end det, men hvis du vil strække benene, så gå og tal med Jernbånd."},
  [709] = {n="Løsning på Undergangen", l="Bring Ryun'ei-tavlen til Theldurin den Fortabte.", d="Åh min! Åh min! Der nærmer sig en undergang. Mærk mine ord! En undergang!\n\nNej, jeg kan ikke tale om den...kan ikke udtale deres navne, ellers hører de mig! Men hvis vi lærer, ja, hvis vi lærer mere om dem...så kan vi måske lære hvordan vi forpurrer dem!\n\nMåske.\n\nGå ind i Uldhulen. Nej! Jeg sagde det! Du må finde...finde Ryun'ei-tavlen. Ja, find den! Og tving mig ikke til at sige det navn igen!\n\nDen ligger dybt inde i stedet, i en gammel kiste. Det er dér den gemmer sig...i en kiste bygget før nogen dværg fik lavet noget."},
  [729] = {n="Den Distræte Prospektor", l="Rejs sydpå og tjek til Prospektor Remrejse.", d="Hvilken ære det var, da Mester Gråhvisker tildelte mig arbejde under den store Prospektor Remrejses vejledning. På akademiet i Jernsmede kendte alle til Remrejses store opdagelser.\n\nMen prospektoren er ret... øh... uopmærksom ...over for sine omgivelser.\n\nVi havde afdækket beviser for et stort samfund. Forfærdelige golemer sprang op af jorden og overrendte stedet. Remrejse syntes aldrig at lægge mærke til det. Jeg løb tilbage til Auberdin efter hjælp.\n\nRejs venligst sydpå og se om prospektoren har det godt!"},
  [736] = {n="Stjernen, Hånden og Hjertet", l="Bring genstandene fra Bel'dugurs seddel til Vogter Bel'dugur i Undergrunden.", d="Du behøver Yagyins Fordøjelse? Så din plan er at samle endnu en flok? Naturligvis er den det...og naturligvis vil jeg hjælpe dig, bror/søster.\n\nMen du må hjælpe mig også.\n\nJeg har brug for tre genstande med magt. Bring mig dem, så er fordøjelsen din.\n\nJeg kan ikke udtale navnene på disse genstande, men jeg vil skrive dem ned.\n\nFå mig de ting på denne liste. Kan du gøre det, så er du virkelig værdig til at åbne dit eget kapitel af vores orden."},
  [738] = {n="Find Agmond", l="Find Agmond.", d="Prospektor Agmond havde ansvaret for vores udgravningssteder i Ødelandene, mod sydvest. Jeg siger \"havde\" fordi...tja, jeg har ikke hørt fra ham i uger. Jeg skal bruge at du finder Agmond, så jeg kan få hans rapport.\n\nSidst jeg hørte var Agmond ved det sydligste udgravningssted i Ødelandene - en lille operation forbi Angor-fæstningen. Jeg ville starte din søgning dér."},
  [741] = {n="Den Distræte Prospektor", l="Tag det mystiske fossil med til Hovedarkæolog Gråhvisker i Darnassos.", d="Så prospektoren vil sende det mystiske fossil til Opdagelsesrejsende-Ligaen i Darnassos? Jeg har det ikke godt med at forlade Mørkekysten uden ham.\n\nHer, <Name>, lever det mystiske fossil til Hovedarkæolog Gråhvisker i Darnassos."},
  [742] = {n="Jagten i Askedalen", l="Tal med Senani Torduhjerte ved Splintertræ-Posten i Askedalen.", d="Opmærksomhed, unge eventyrere! Vildmarken i Askedalen venter på jer!\n\nHorden har etableret en stærk tilstedeværelse i landene nord for Ødemarken. Vores to forposter - Splintertræ-Posten og Zoram-strandbredden-forposten - stræber efter at bringe ære til Horden! De, der vil bevise sig selv, bør søge vejledning dér. Værd at bemærke: Senani Torduhjerte i Splintertræ-Posten, lige nord for Ødemarken, søger eventyrere, der er villige til at deltage i en stor jagt i Askedalen!"},
  [744] = {n="Forberedelse til Ceremonien", l="Saml 6 Azurblå Fjer og 6 Bronze-fjer, og bring dem til Eyahn Ørnetalon i Tordenklippe.", d="<Name>, min bror står snart foran Høvding Blodhov, og det er min ære at lave hans hovedbeklædning til ham.\n\nJeg vil bede dig om en tjeneste, mens jeg bliver færdig med at garve disse læderremme. Jeg har ikke tid nok til at finde nok fjer, og jeg tænkte, om du kunne skaffe flere til mig?\n\nDu kan finde fjer af den rette størrelse hos harpyerne, der holder til langt mod nord og nordvest for Tordenklippe. Jeg skal kun bruge 6 azurblå og 6 bronze-fjer for at fuldende designet."},
  [745] = {n="Delingen af Landet", l="Dræb 10 Blegmanke-garvere, 8 Blegmanke-skindere og 5 Blegmanke-krybskytter, og vend derefter tilbage til Baine Blodhov i Blodhov-landsbyen.", d="<Name>, der er mange konflikter, som sårer dette land. Mit håb er, at du ikke må være vidne til lige så mange af dem, som jeg har været. Alligevel er der en, som jeg vil bede dig opsøge. Den vil give dig en fornemmelse af, hvor forfærdelig selv en lille trussel kan være for landet, hvis den får lov at vokse uhindret.\n\nBlegmanke-gnolde har slået sig ned syd for Blodhov og i en hule mod vest. De ringeagter vores forsøg på at kommunikere med dem, og de slagter Mulgorrs dyreliv uden tøven.\n\nOrd er ikke længere svaret."},
  [747] = {n="Jagten Begynder", l="Grull Falkevind i Narache-lejren vil have, at du bringer ham 7 Slettegænger-fjer og 7 stykker Slettegænger-kød.", d="Du har en lovende udstråling, og du vil bevise dig selv over for stammen. Måske bliver du en dag snart budt velkommen i den store by Tordenklippe. Men før det kan ske, må du bevise dig selv over for min far, Høvding Falkevind.\n\nHeroppe på Røde Sky-plateauet er vi stolte af vores skarpe jagtfærdigheder. Taurener jager af nødvendighed og for sportens skyld. Vores forråd af kød er løbet tør, og vi har brug for fjer til tøj. Jag slettegængerne i nærheden og bevis dig selv ved at forsyne landsbyen igen."},
  [752] = {n="En Ydmyg Opgave", l="Høvding Falkevind vil have dig til at lede efter hans mor ved vandbrønden sydøst for Narache-lejren.", d="Alle medlemmer af stammen deler harmonien i livet. Vi lever sammen og arbejder sammen.\n\nVores forpligtelse over for hinanden medfører et stort ansvar. Jeg beder dig nu om en ydmyg opgave.\n\nMin mor drog af sted i morges for at hente vand fra brønden sydøst for Narache. Der er gået ret lang tid nu. Kunne du mon tjekke til hende for mig, mens jeg tager mig af stammens anliggender her?"},
  [759] = {n="Vildmanke-totemet", l="Bring 8 Prærie-alfatænder til Mull Tordenhorn i Blodhov-landsbyen.", d="Der er kun én vandbrønd tilbage at rense, opkaldt efter Vildmanke-klanen. For at denne brønd kan blive ren, må landet give tænderne fra et vildt rovdyr, prærieulvens alfa. Find alfaerne mod nord, og vend så tilbage til mig, når din jagt er slut.\n\nAlfaer strejfer ofte rundt om foden af vores mægtige by, Tordenklippe."},
  [763] = {n="Jordmoderens Riter", l="Tag Falkevinds Totem til Baine Blodhov i Blodhov-landsbyen. Følg vejen ud af Narache-lejren.", d="For at du kan fortsætte med Jordmoderens Riter, må du bestå to prøver mere. Det er tid for dig at udvide din erfaring, <Name>.\n\nRejs til Blodhov-landsbyen og find høvdingen Baine Blodhov, søn af Kærne. Der kan du fortsætte din rejse og opnå de ældres accept i Tordenklippe.\n\nTag dette totem med til Baine. Han vil genkende mine udskæringer og hjælpe dig på din vej.\n\nFølg vejen ud af Narache-lejren, og rejs i hast. Forvild dig ikke, for ellers går du vild."},
  [764] = {n="Ventureselskabet", l="Dræb 14 Ventureselskab-arbejdere og 6 Ventureselskab-tilsynsmænd for Morin Skyjæger i Blodhov-landsbyen.", d="Det forklarer den opbygning af Ventureselskabets ansatte og udstyr, vi har set i Mulgorr. Disse gobliner... deres firma udvider sig alt for hurtigt til deres eget bedste. Som man siger: vis en goblin noget, og du kan høre skillepengene klirre i baggrunden.\n\nGriske små gobliner er de. Desværre for deres forretning kan vi taurener ikke tillade, at de driver deres virksomhed på vores lande. Gå til deres mine nordøst for den hærgede karavane, og send dem en besked."},
  [765] = {n="Tilsynsmand Gnistfix", l="Dræb tilsynsmand Gnistfix og bring hans klembord tilbage til Morin Skyjæger i Blodhov-landsbyen.", d="Ifølge de dokumenter, du bjærgede fra karavanen, lavede Ventureselskabet mange planer for at forsøge at fordrive os fra vores lande her, så de kunne plyndre vores land uden hindringer.\n\nDe dybder, de vil synke til for at nå deres mål, væmmer og forfærder mig. Jeg ønsker, at hjernen bag deres planer bliver dræbt. Hans navn er tilsynsmand Gnistfix; du finder ham ved Ventureselskabets mine øst for den hærgede karavane. Bring mig hans klembord, så ser vi, om vi kan finde noget nyttigt."},
  [770] = {n="Dæmonarret Kappe", l="Find nogen, der kender til Spøgelsesylen.", d="Den flossede hud af Spøgelsesylen bærer stadig et forfærdeligt sår, opnået i ulvens kampe mod den Brændende Legion.\n\nMåske burde nogen i Blodhov-landsbyen vide noget om Spøgelsesylens død...."},
  [772] = {n="Synernes Ritual", l="Indtag Synernes Vand foran stammens bål i Blodhov-landsbyen, og følg synet, når det dukker op.", d="Jeg præsenterer dig nu for Synernes Vand.\n\nNår du er klar, så indtag vandet ved stammens bål. Når du har indtaget det hellige vand, går der et øjeblik, før synet materialiserer sig foran bålet.\n\nPå det tidspunkt er det op til dig at følge det til din skæbne...."},
  [776] = {n="Jordmoderens Riter", l="Kærne Blodhov i Tordenklippe vil have, at du bringer ham Arra'kajas Horn.", d="Du har bestået Jordmoderens Riter og tjent din plads i Tordenklippe.\n\nMen for at bevare den plads, du kæmpede så hårdt for at opnå, må du blive ved med at bevise din værdi over for dit folk.\n\nVi er jægere, <Name>. Nede i Mulgorr findes en mægtig kodo ved navn Arra'kaja. Vis mig dine færdigheder i sporing og jagt ved at bringe mig Arra'kajas Horn."},
  [783] = {n="En Trussel indefra", l="Tal med Marskal McBride.", d="Jeg håber, du har spændt bæltet godt fast, unge <Class>, for der er arbejde at gøre her i Nordshire.\n\nOg jeg mener ikke landbrug.\n\nStormvindske vagter har svært ved at holde freden her, med så mange af os i fjerne lande og så mange trusler, der presser på tæt inde på livet. Og derfor henter vi hjælp fra alle, der er villige til at forsvare deres hjem. Og deres alliance.\n\nHvis du er kommet for at svare på opfordringen, så tal med min overordnede, Marskal McBride. Han er inde i klosteret bag mig."},
  [784] = {n="Sejr over Forræderne", l="Dræb 10 Kul Tirask-sømænd, 8 Kul Tirask-marinesoldater og løjtnant Benedikt, og vend tilbage til Gar'Thok i Barberbakken.", d="Ledet af Admiral Stoltmoor trængte menneskene fra Kul Tirask ind i Durdotar og krænkede Krigshøvdingens pagt, som var indgået med Jaina Stoltmoor for at besejre Archimonde for år tilbage.\n\nMenneskenes angreb blev afvist, og Tiragarde-fæstningen faldt. Men for nylig har admiralens reserver, ledet af løjtnant Benedikt, genindtaget fæstningen og udgør igen en trussel mod vores hjemland. Disse mennesker viser ingen respekt for diplomati.\n\nBevis din ære og rejs sydpå til Tiragarde-fæstningen for at eliminere de menneskelige invasionister."},
  [786] = {n="Stop Kolkar-aggressionen", l="Lar Snigetusk udenfor Sen'jin-landsbyen vil have, at du ødelægger de 3 sæt angrebsplaner, der findes i Kolkar-klippen.", d="Sænk stemmen, <Class>. Kolkar-kentaurerne ligger lige over højdedraget mod vest i Kolkar-klippen.\n\nI nat, mens de var på raid, sneg jeg mig ind i deres landsby og opdagede, at de beskidte bæster har planlagt et angreb i tre led mod trolde og orker i Durdotar.\n\nVi må ikke lade deres invasion gå i opfyldelse. Måske kan du samle den styrke, der skal til for at trænge ind i Kolkar-klippen og ødelægge deres angrebsplaner.\n\nSidst jeg så, havde de delt dem ud blandt tre af deres ledere."},
  [788] = {n="Tænderne Skæres", l="Dræb 10 Plettede Vildsvin og vend derefter tilbage til Gornek ved Hulen.", d="Den første opgave bliver at give dig lidt rygrad. Jeg kunne sende dig ud i Ødemarken for at jage kodoer, men helt ærligt er du mere nyttig for os i live end død.\n\nJeg tror, du vil finde en god kamp med de plettede vildsvin, du finder mod nord herfra."},
  [789] = {n="Skorpidens Stik", l="Skaf 10 Skorpid-arbejderhaler til Gornek ved Hulen.", d="Mægtige krigere og klodsede nykommere er faldet for skorpidens giftige stik. Du finder store mængder skorpider nordvest herfra. Bring mig ti af deres haler som bevis på din kampdygtighed.\n\nModgiften mod deres stik er faktisk lavet af gift udvundet fra deres brodder. Vi har store mængder modgift mod skorpidgift på lager for at helbrede unge blodhoveder som dig...\n\nMen jeg er sikker på, at du ikke får brug for noget af det, vel?"},
  [790] = {n="Sarkot", l="Dræb Sarkot og bring hans klo tilbage til Hana'zoa.", d="<Class>! Jeg troede, jeg ville dø herude uden at nogen vidste det. Mens jeg jagtede skorpiderne i dalen, stødte jeg på en særligt ondskabsfuld en. Jeg kastede mig imod den og fik et kraftigt slag ind i dens klo, før den lukkede sig om mit ben.\n\nJeg var dog ikke forberedt på dens brod, som huggede ned og ind i mit bryst, skar i mit kød og lod mit blod. Du må dræbe skorpiden for mig! Min ære skal oprejses! Jeg kæmpede med den oppe på plateauet mod syd."},
  [792] = {n="Ondskabsfulde Følgesvende", l="Dræb 12 Ondskabsfulde Følgesvende.\n\nVend tilbage til Zureetha Fjernblik udenfor Hulen.", d="Jeg har tillid til, at Prøvernes Dal vil lære dig meget, unge <Class>.\n\nJeg blev sendt til dalen for at vejlede dig, men jeg har opdaget en voksende forurening her...\n\nEn gruppe, der kalder sig Brændende Klinge, har et hekseri her i Prøvernes Dal. De lurer i en hule mod nordøst, og deres ondskabsfulde følgesvende har strømmet ud af dens munding for at skabe kaos.\n\nSom din første opgave mod Brændende Klinge beder jeg dig om at besejre disse følgesvende. Dræb mange, og vend tilbage til mig, hvis du overlever."},
  [794] = {n="Brændende Klinge-medaljonen", l="Bring Brændende Klinge-medaljonen til Zureetha Fjernblik udenfor Hulen.", d="Gennem mine spådomme ser jeg, at en magtfuld genstand gemmer sig dybt inde i Brændende Klinge-hekseriet, vogtet af bæster og sort magi.\n\nDen kaldes Brændende Klinge-medaljonen, og din næste opgave er at finde den og fjerne den fra hekseriet.\n\nMen vær på vagt, for medaljonen kan være besat af en agent fra Brændende Klinge, og i så fald vil agentens magt være større end de følgesvende, du allerede har mødt.\n\nAfsted, <Name>. Du finder hekseriet i en hule mod nord og vest."},
  [804] = {n="Sarkot", l="Bring nyheden om Hana'zoas kår til Gornek ved Hulen.", d="At se den gerning, du har gjort for mig, styrker mit hjerte. Jeg kan ikke falde så let! Jeg må udholde!\n\nMen det er stadig sådan, at jeg ikke kan gøre turen tilbage til Hulen uden hjælp. Vær venlig, <Name>, vend tilbage til Hulen og fortæl Gornek om min situation. Måske kan han hjælpe mig."},
  [805] = {n="Rapporter til Sen'jin-landsbyen", l="Tal med Mester Gadrin i Sen'jin-landsbyen.", d="Dine prøvelser mod Brændende Klinge er færdige... her i dalen. Men jeg vil have, at du rapporterer dine fund.\n\nGå til trolde-landsbyen Sen'jin og find Mester Gadrin. Sen'jin-landsbyen ligger øst for dalen, og så til højre ved vejkrydset.\n\nFortæl Gadrin om Brændende Klinge, og at de er nået til Prøvernes Dal. Find ud af hos ham, om de allerede er nået til Sen'jin.\n\nAfsted, <Name>, og vær hurtig. Jeg frygter, at det onde i Brændende Klinge-hekseriet blot er forløberen for en større trussel..."},
  [806] = {n="Mørke Storme", l="Bring Fizzles Klo til Orgnil Sjælsar i Barberbakken.", d="Vi kan ikke tillade Brændende Klinge at få fodfæste i Durdotar! Vi må ødelægge dem, før deres ondskab hærger!\n\nJeg har selv foretaget undersøgelser og fundet ud af, at en Brændende Klinge-hekseman, goblinen Fizzle Mørkstorm, har slået lejr i Tordenryggen mod nordvest. Der sår han og hans kultistiske håndlangere kaos.\n\nFind og besejr Fizzle, og bring mig hans døde klo!"},
  [808] = {n="Minshinas Kranium", l="Hent Minshinas kranium fra kraftcirklen på Ekkoøerne.\n\nBring det til Mester Gadrin i Sen'jin-landsbyen.", d="Jeg hører min bror Minshinas stemme kalde på mig i mine drømme.\n\nHan blev taget af Zalazan, hekseren på Ekkoøerne mod øst. Og han er død.\n\nMen døden er ingen frihed for min bror. Minshinas ånd blev fanget i hans eget kranium af Zalazans magi. I mine drømme ser jeg den sammen med andre kranier i en kraftcirkel på den største Ekkoø. Så længe den bliver der, er hans sjæl dømt til undergang.\n\nVær venlig, <Name>. Find cirklen og hent Minshinas kranium. Bring det til mig.\n\nBefri ham!"},
  [809] = {n="Ak'Zelot", l="Tal med Ak'Zelot i Ødemarken.", d="Siden den sidste store krig, da den Brændende Legion blev besejret, har jeg søgt efter kilder til dæmonisk korruption i orkesamfundet. Halsbåndet, du bragte mig, bekræfter mine frygt.\n\nDet tilhører Brændende Klinge, en kult, der samler sig om en genstand med dæmonisk magt. Den kaldes Dæmonfrøet, og den befinder sig i Ødemarken på toppen af Rædselståge-toppen. Den skal ødelægges!\n\nGå til Fjernvagtsposten ved Ødemarkens grænse mod vest, og tal med min assistent, Ak'Zelot. Han vil vise dig videre."},
  [815] = {n="Knæk Et Par Æg", l="Bring 3 Halesnapper-æg til Kok Torka i Barberbakken.", d="Bah! Jeg glemte næsten, at jeg skal have morgenmaden klar.\n\n<Name>, kom dig afsted og skaf mig nogle halesnapper-æg. Jeg skal bruge mindst tre, hvis der skal være nok til i morgen.\n\nBlodklo-halesnapperne kan være vilde, og de beskytter deres æg til døden det meste af tiden. Nogle gange graver de æggene for dybt i jorden til at hente dem sikkert, men tager du til Ekkoøerne sydøst for Sen'jin-landsbyen, kan du som regel finde dem over hele øerne."},
  [816] = {n="Fortabt, Men Ikke Glemt", l="Bring et tegn på Krons skæbne til Misha Tor'kren på gården nordvest for Barberbakken.", d="<Name>, vær sød, kan du hjælpe mig? Min søn Kron tog på jagt for flere dage siden, og han er stadig ikke kommet hjem. Han gik mod vest til Ødemarken for at jage krokolisker langs Sydfury-floden. Jeg frygter det værste.\n\nSå stærk som han var, har hans stædige stolthed altid bragt ham i problemer. Jeg advarede ham om, at krokoliskerne var stærke og onde. Han blev vred og stormede af sted.\n\nHvis du ikke kan finde ham, så bring mig i det mindste et tegn på hans skæbne... selv om du må skære maven op på hver eneste krokolisk langs Sydfury-floddens bred."},
  [817] = {n="Praktisk Bytte", l="Bring 4 Durdotar-tigerpelse til Vel'rin Fang i Sen'jin-landsbyen.", d="Mange af de skind, vi bruger, kommer fra Durdotar-tigre, <Name>. Tæpper, rustninger, telte: der er en masse grunde til, at vi jager dyrene, og lige så mange grunde til, at vi lader dem trives.\n\nTiden er kommet til at tynde flokken lidt ud, så at sige. Vores antal vokser, og vores behov begynder at overvælde vores lager. Jeg har brug for flere skind, hvis jeg skal lave ordentlige varer til vores folk.\n\nBring mig 4 Durdotar-tigerpelse, så belønner jeg dig. Du finder dem på øerne syd for her."},
  [818] = {n="En Opløsende Ånd", l="Bring 4 intakte Makrurskrabbe-øjne og 8 flasker Kryberslim til Mester Vornal i Sen'jin-landsbyen.", d="Selv om mine øjne svigter mig, kan jeg stadig se klart nok. Oftere må jeg stole på mine alkymiske evner for at hjælpe mig med magi, der engang kom let. Men jeg nægter at tage en lærling – ingen trold eller ork har endnu været værdig nok til at melde sig.\n\nEr du værdig? Ja, selvfølgelig er du det... selvfølgelig tror du det.\n\nJeg har brug for et par ting. Vil du skaffe dem til mig?\n\nJeg skal bruge intakte makrurskrabbe-øjne og flasker med kryberslim. Du finder dem på enhver makrurskrabbe eller kryber i Durdotar. Vi taler snart igen."},
  [819] = {n="Chens Tomme Tønde", l="Find nogen, der ved noget om Chens Tomme Tønde.", d="En lille skilt på den ene ende af tønden siger:\n\n\"Chen Stormøl-\n\nMåtte din ånd blive løftet og altid løfte dine humør.\""},
  [821] = {n="Chens Tomme Tønde", l="Bring 5 Savannah-løvetænder, 5 Slettegænger-nyrer og 1 Tordenøgle-horn til Bryggemester Drohn i Skralleby.", d="Vil du gerne smage Chens navnebror? Ahh, stormøl er en mægtig brygning. Chen lærte opskriften til min mentor, og min mentor gav den videre til mig. Jeg skal bruge et par ting fra dig, men jeg kan fortælle dig dette: kicket er det værd.\n\nBring mig 5 savannah-løvetænder fra en hvilken som helst savannah-løve, 5 slettegænger-nyrer fra en hvilken som helst slettegænger og 1 tordenøgle-horn fra en hvilken som helst art af tordenøgle. Så burde det gøre det.\n\nDisse ingredienser finder du overalt i Ødemarken."},
  [822] = {n="Chens Tomme Tønde", l="Bring 5 Lynkirtler, 1 Tordenfalke-spytkirtel og 1 Kodo-lever til Bryggemester Drohn i Skralleby.", d="God vare, det stormøl, hva'?\n\nJeg har en anden opskrift, som jeg lærte af Chen. Har du lyst? Den tager ikke lang tid at lave, og den kan være nyttig, hvis du har planer om at eventyre lidt mere.\n\nBring mig 5 lynkirtler fra en hvilken som helst stormhud, 1 spytkirtel fra en stor tordenfalk og en kodo-lever fra en af Ødemarkens kodoer.\n\nSom sagt, den her ting har kraft; det er trogg-brygningen, jeg nævnte for dig før."},
  [823] = {n="Rapport til Orgnil", l="Tal med Orgnil Sjælsar i Barberbakken.", d="Vi i Sen'jin-landsbyen har heller ikke vores egne problemer, og vi takker dig for din hjælp. Men de nyheder, du bringer om Brændende Klinge, kan blive et problem for alle.\n\nDer er en ork stationeret i Barberbakken, Orgnil Sjælsar, som holder vagt over Durdotar mod onde kræfter som Brændende Klinge! Gå til Orgnil og fortæl ham om vores nød, samt dine nyheder fra Prøvernes Dal. Han vil have brug for at vide det.\n\nBarberbakken ligger mod nord."},
  [824] = {n="Je'neu fra Jordringen", l="Bring den forurenede vandkugle til Je'neu Sancrea ved Zoram'gar-forposten i Askedalen.", d="Jordringen er en shamanistisk gruppe, der er viet til at studere og bevare elementerne. De har glemt mere om skøre gamle guder, oldtidslegender og viden, end de fleste lærde nogensinde vil kende.\n\nHeldigvis kender jeg nogen i Jordringen her i Askedalen. Tag til Zoram'gar-forposten ved kysten af Zoram-strandbredden; vis Je'neu Sancrea, hvad du har fundet. Hvis nogen kan finde ud af, hvad den kugle betyder, så er det ham."},
  [825] = {n="Fra Vraget....", l="Gar'Thok fra Barberbakken vil have dig til at hente 3 gnomiske værktøjer fra vraget ud for kysten.", d="En af mine mest opmærksomme spejdere bringer nyheden om, at vraget af Proudmoores flåde stadig ligger ud for kysten af Durdotar, lige øst for Tiragarde-fæstningen.\n\nDet er ingen hemmelighed, at menneskerne, i alliance med de snavsede små væsner kendt som gnomer, har en avanceret viden om mekanik. Vi må have en fuldstændig forståelse af alle vores potentielle fjender. Og vores folk vil også få gavn af denne nye viden.\n\nSvøm gennem vraget, <Name>, og hent mig alliancens værktøjer."},
  [826] = {n="Zalazan", l="Besejr Zalazan.\n\nDræb 8 Voodoo-trolde og 8 Forhekset-trolde.\n\nBring Zalazans hoved til Mester Gadrin.", d="Heksedoktoren Zalazan holder til på Ekkoøerne mod øst. Det er de øer, vi engang kaldte hjem.\n\nDerfra sender han sine trolde til fastlandet for at forhekse vores folk og trække flere af dem under sit herredømme.\n\nHan må stoppes.\n\nBesejr Zalazan og hans håndlangere -- tidligere Mørkspyd-trolde, nu tabt for os. Bring mig hans hoved, så ved jeg, at hans onde styre er forbi."},
  [827] = {n="Kranieklippen", l="Saml Brændehalsbånd fra kultisterne i Kranieklippen.\n\nBring dem til Margoz i hans lejr.", d="<Name>. Brændende Klinge har inficeret hulen øst for Orgrimgrad, kendt som Kranieklippen. Inde i den hule udfører de onde ritualer og brænder deres eget kød med Brændehalsbånd.\n\nVed at bære disse halsbånd tror jeg, at kultisterne stiller sig ind på dæmonisk kraft. Men for at bekræfte det må jeg have en samling af halsbåndene at studere.\n\nTag til Kranieklippen og saml Brændehalsbånd fra de kultister, du finder der. Bring dem til mig, så afslører jeg deres hemmeligheder."},
  [828] = {n="Margoz", l="Tal med Margoz.", d="En af vores shamaner, Margoz, ved mere om Brændende Klingens fordærvelse. Han taler om en hule ved navn Kranieklippen i bjergene – lige uden for Orgrimgrad! – som huser en stor flok Brændende Klinge-kultister.\n\nFør du tager til Kranieklippen, så tal med Margoz. Han er klog, og hans råd er værdifulde.\n\nHan slår lejr mod nordøst, mellem kysten og Drygulch-kløften.\n\nFølg hans råd, men uanset hvad Margoz siger, <Name>, vil jeg stadig have dig til at knuse de kultister!"},
  [829] = {n="Neeru Ildklinge", l="Bring et eksempel-halsbånd til Neeru Ildklinge i Orgrimgrad.", d="De Brændehalsbånd, du bragte mig, er kraftfulde dæmoniske redskaber. Det er desværre uden for mine evner som shaman at finde ud af, hvor de stammer fra. Vi får brug for en warlock til at studere dem.\n\nTag et brændehalsbånd med til Neeru Ildklinge. Selvom han er en dygtig warlock, hævder han at bruge sine kræfter til at forpurre dæmoner, og han påstår, at hans forskning i det okkulte er godartet. Om det er sandt eller falsk, kan vi få brug for hans hjælp mod dæmonkulten i Durdotar.\n\nDu finder Neeru i Orgrimgrad, i Skyggeklyngen."},
  [830] = {n="Admiralens Ordrer", l="Tag Admiral Stoltmoors ordrer til Gar'Thok i Barberbakken.", d="Du åbner den gamle, vejrbidte konvolut og finder et officielt udseende dokument. Du genkender Admiral Stoltmoors segl.\n\nDet her ser vigtigt ud. Måske ville Gar'Thok, chefen for Barberbakken, være interesseret i at få disse oplysninger."},
  [831] = {n="Admiralens Ordrer", l="Lever Admiral Stoltmoors ordrer til Nazgrel i Trals kammer i Orgrimgrad.", d="Mennesker kan ikke stoles på. Vi kæmpede side om side med dem med et trætte hjerte, vidende at de en dag ville forråde os.\n\nAdmiral Stoltmoors død var ikke nok til at standse hans arv af svig. Det menneskelige udskud havde lagt sine planer længe før han mødte sin ende.\n\nHans herredømme dør tilsyneladende heller ikke med Benedikt. Hvem ved, hvor længe det varer, før den næste bølge af Stoltmoors mænd lander på vores kyster.\n\nVi må få disse ordrer til Nazgrel i Orgrimgrad med det samme! Han findes i Trals kammer."},
  [832] = {n="Brændende Skygger", l="Tag dette øje med til Neeru Ildklinge.", d="<Ord strømmer fra vedhænget og ind i dit sind.>\n\nGazz'uz?\n\nGazz'uz... rapportér!\n\nDer er kommet melding om din opdagelse i Kranieklippen. Du må forberede dig på et angreb!\n\nGazz'uz, jeg befaler dig at tale! Tal, ellers sørger jeg for, at Neeru Ildklinge får kendskab til din tilstedeværelse, og han vil komme ned over dig med hurtig brutalitet.\n\nTest ikke dine evner mod Neeru...\n\n...Gazz'uz, er du der...?"},
  [834] = {n="Vinde i Ørkenen", l="Hent 5 sække forsyninger og bring dem til Rezlak nær Orgrimgrad.", d="Jeg er Rezlak, en af Gazlowes drenge. Chefen sendte mig for at hjælpe orkerne her i Durdotar. Tingene har kørt godt, bortset fra karavanerne. Kan ikke holde dem sikre! Gør mit job lidt sværere, ved du vel?\n\nDen sidste forsendelse – de lovede, at den ville komme frem! – blev snuppet af Støvvind-harpyerne fra... hvor var det nu... Barbervinds-kløften?\n\nJeg må have de forsyninger, ellers får jeg aldrig noget gjort! Følg den store kløft mod syd, så finder du rillen, der skærer ind i både vest- og østsiden af klipperne."},
  [835] = {n="Sikring af Linjerne", l="Dræb 12 Støvvind-vildmænd og 8 Støvvind-stormhekse for Rezlak nær Drygulch-kløften.", d="Gazlowe fortalte mig engang: \"Rezlak. Der er én ting, du skal vide i livet, og det er, at hvis du vil have noget gjort ordentligt, så gør du det selv.\"\n\nJeg kan ikke klare at miste alle vores karavaner, så jeg tager sagerne i egen hånd. Drygulch-kløften ligger gennem den østlige del af Barbervinds-kløften. Hvis vi dræber alle harpyerne der, bliver rutene sikre.\n\nDer er dog én anden ting, Gazlowe lærte mig, nemlig at \"man kan få alt gjort for en pris\". Så, vil du hjælpe mig, <Name>?"},
  [837] = {n="Indtrængen", l="Dræb 4 Barbermanke-piggrise, 4 Barbermanke-spejdere, 4 Barbermanke-støvløbere og 4 Barbermanke-krigsvagter for Gar'Thok i Barberbakken.", d="Da vi ankom, besad Barbermanke-piggrisene meget af landet og var en torn i siden på os. Gennem vores indsats har vi drevet den største del af dem ud, men de står stadig velbefæstede i nogle områder.\n\nDet har dog varet længe nok. For vores egen beskyttelse kan vi ikke tillade Barbermanke noget greb i vores lande. Deres lejre findes mod vest herfra. Led efter tornebuskene, så finder du dem. I dag driver vi dem fra Durdotar, i morgen måske fra hele Kalimdør."},
  [840] = {n="Hordens Rekrut", l="Følg den vestlige vej fra Barberbakken til Ødemarken over en bro.\n\nStop ved orkeforposten på den anden side af broen.\n\nAflever din rekrutteringsseddel til Kargal Kampar i Ødemarkens forpost.", d="Hmm, du ser ret stærk ud.\n\nHør nu, min gode ven Kargal har brug for nogle nye rekrutter til tjeneste i Ødemarken. Jeg ved, du vil gøre det rigtige for Horden. Nu har du chancen.\n\nTag denne rekrutteringsseddel med til Kargal og se, om han vil underskrive den."},
  [843] = {n="Gann's Genvinding", l="Gann Stenspir vil have dig til at dræbe 15 Bael'dun-gravere og 5 Bael'dun-formænd.\n\nBring Khazgorms dagbog til Gann Stenspir.", d="I ensomhed vandrer jeg disse veje.\n\nDværgene fra Bael Modan viser ingen respekt for mit land. Frygtelige eksplosioner borer huller dybt i jorden, mens støjende maskiner river bakkerne fra hinanden. Lande, der engang var hjem og forsørger for min stamme, er nu fyldt med destruktive dværge.\n\nForsøg på at finde en diplomatisk løsning er slået fejl. Nu er tiden kommet til handling.\n\nDriv dværgene væk fra Bael Modan-udgravningen med magt, og bring mig dagbogen fra deres leder, Prospektor Khazgorm."},
  [844] = {n="Slettegænger-plagen", l="Saml 7 Slettegænger-næb og aflever dem til Sergra Mørktorn i Korsvejen.", d="Dit første bytte bliver let.\n\nSlettegængerne mod øst har plaget vores madforsyninger og er blevet en ulempe.\n\nNedlæg slettegængerne og kom tilbage til mig med deres næb."},
  [845] = {n="Zhevrøerne", l="Nedlæg Zhevrø-løbere for at samle 4 Zhevrø-hove til Sergra Mørktorn i Korsvejen.", d="Zhevrøerne er, selv om de ikke er den vildeste bæst i Ødemarken, en tand sejere end slettegængerne. Vær ikke bekymret – vi sender dig imod større bytte i tide, men lige nu kunne dine tænder godt bruge lidt mere skarphed.\n\nJag zhevrøerne mod nord og syd, og saml deres hove. Bring dem til mig, så sender vi måske dig imod noget sejere næste gang."},
  [846] = {n="Gann's Hævn", l="Gann Stenspir vil have dig til at bringe ham 6 flasker nitroglycerin, 6 bundter træmasse og 6 prøver natriumnitrat.", d="Det er klart, at prospektoren var afhængig af sprængstoffer og de støjende køretøjer for at rive jorden op. Vi kan forvente, at en ny formand snart overtager.\n\nJeg vil give dværgene en smag af deres egen medicin. Ifølge disse planer kan vi skabe en sprængladning, hvis vi blander nitroglycerin med træmasse og natriumnitrat. Riflemændene, soldaterne og officererne i fæstningen har kendt til forsyningerne.\n\nSaml disse ting og bring dem til mig. Jeg vil smede en ladning, som dværgene aldrig vil glemme!"},
  [848] = {n="Svampesporer", l="Bring 4 Svampesporer til Apoteker Helbrim i Korsvejen.", d="Ødemarkens oaser gemmer på et mysterium. Livsenergi strømmer fra deres vand og giver liv til de planter og dyr, der drikker det.\n\nGiver liv, og forandrer.\n\nDer findes en svamp, der vokser nær disse oaser. Dens sporer har egenskaber, som vi, apotekerne i Herrelande, finder nyttige.\n\nBring mig disse sporer, så vinder du vores taknemmelighed."},
  [849] = {n="Gann's Hævn", l="Ødelæg flyvemaskinen ved Bål Modan og vend tilbage til Gann Stenspir.", d="Med Kasgorms planer burde det ikke være noget problem at fremstille en eksplosiv ladning\n\nAh, der var den.\n\nNu, <Name>, vil jeg betro dig en særlig opgave. Tag denne sprængstav og brug den til at sprænge flyvemaskinen ved Bål Modan i luften.\n\nFlyvemaskinen er ikke blot en nøglekomponent i stedets infrastruktur, den tjener også som krigsvåben. Endnu vigtigere er den et symbol på magt og en fornærmelse mod min stammes minde.\n\nGør mig stolt ved at fuldføre denne heroiske opgave, så skal du få din belønning."},
  [850] = {n="Kolkar-lederne", l="Bring Barak Kodobøfs Hoved til Regthar Dødsporten, vest for Korsvejen.", d="Kentaurerne har plaget taurerne i årevis. Og for nylig er Kolkar-kentaurerne i Ødemarken vokset til en reel trussel. Normalt var de uorganiserede i disse lande, men nye ledere er opstået blandt dem. Og de samler dem.\n\nFor at bevare vores besiddelser her, skal disse kentaur-ledere udslettes.\n\nBring mig hovedet af Barak Kodobøf. Han holder lejr nær De Glemte Pøle mod nord.\n\nBesejr ham, og vend så tilbage til mig."},
  [851] = {n="Verog Dervisen", l="Bring Verogs Hoved til Regthar Dødsporten, vest for Korsvejen.", d="Kentauren Verog Dervisen vandrer rundt i Ødemarken og er svær at finde. Men han har sit hovedkvarter i kentaurernes kommandotelt ved Stillestående Oase mod sydøst. Det kan være muligt at lokke ham frem.\n\nRejs til Stillestående Oase mod sydøst og angrib kentaurer nær kommandotelten. Det bliver farligt, men hvis du kan dræbe nok kentaurer, så slår de alarm. Og Verog vil komme.\n\nBring mig hans hoved, så lægger jeg det sammen med Barak Kodobøfs."},
  [852] = {n="Hezrul Blodmærket", l="Bring Hezruls Hoved til Regthar Dødsporten, vest for Korsvejen.", d="Hezrul Blodmærket er leder af Kolkar-kentaurerne i Ødemarken. Han er vild, brutal og snedig. At besejre ham ville splitte og splintre Kolkarerne og markant mindske deres trussel mod os.\n\nSå dræb ham. Ligesom med Barak og Verog, så bring mig Hezruls Hoved.\n\nHan fører sit folk fra Frodigvand-oasen, mod syd."},
  [853] = {n="Apoteker Zamaa", l="Bring de Udsmeltede Sporer til Apoteker Zamaa i Tordenklippe, inden tidsfristen udløber.", d="Jeg har udsmeltet de sporer, du gav mig, til en emulsion. Jeg må nu sende den til min kollega, Apoteker Zamaa. Hvis du tog den med til hende, kunne hun give dig noget fra vores lager af alkymiske varer.\n\nHun er i Synets Pøle, en hule under shamanerne i Tordenklippe. Stien til hulen er godt skjult, men du finder den måske på Åndsopstigningen.\n\nSkynd dig. Denne emulsion bevarer sin styrke i kort tid, og den skal forsegles og behandles igen før da."},
  [855] = {n="Kentaur-armbånd", l="Bring 15 Kentaur-armbånd til Regthar Dødsporten, vest for Korsvejen.", d="Kolkarerne er en trussel mod Hordens krav i Ødemarken; vi må reducere antallet af deres tropper. Og derfor har jeg en dusørjob til dig.\n\nMens du er på Kolkarnes område, skal du slå deres krigere ihjel og samle kentaur-armbånd. Vend tilbage, når du har en bunke armbånd, så belønner Horden dig godt."},
  [857] = {n="Månernes Tåre", l="Feegly den Forviste vil have dig til at hente Månernes Tåre til ham.", d="Kraften var min! I mine egne hænder! Og jeg vil have den tilbage! Tilbage siger jeg!\n\nDe beskidte udgravere afdækkede den... så smuk den var. Den blev kaldt Månernes Tåre, og det var den første store opdagelse, vi gjorde ved Bål Modan.\n\nDen skulle have været min! Min siger jeg!\n\nGeneral Tvefletten blev jaloux på den magt, den gav mig. Han låste den inde i fæstningen. Kaldte den forbandet, det gjorde han! Narren!\n\nAndre ville have den, og de måtte stoppes! Den bastard Tvefletten jagede mig væk.\n\nNu vil jeg have den tilbage. Tilbage siger jeg!"},
  [862] = {n="Gravrottegryde", l="Bring 8 Gravrotter til Gnav øst for Korsvejen.", d="En <Class> som dig må blive ret sulten herude i Ødemarken. Jeg er sulten hele dagen.\n\nLad mig sige dig, jeg laver en lækker gryde til dig. Mangler bare nogle få gravrotter.\n\nDet ser ud til, at de snavsede dværge ved Bål Modan er oversvømmet med alles yndlingsret. Nu skal du gå sydpå til Bål Modan og bringe mig nogle gravrotter.\n\nDu kan ikke kalde dig selv en garvet eventyrer, før du har brugt tid på at dræbe rotter! Haw!"},
  [863] = {n="Flugten", l="Beskyt Snurrekrank og den stjålne goblin-hakker på vejen til Sprutventil i Skralleby.", d="Jeg må vel lære det undervejs... Kan ikke være så svært. Bare nogle knapper her og en eller to håndtag... Nå, er du klar til at tage af sted?"},
  [865] = {n="Raptor-horn", l="Saml 5 intakte Raptor-horn fra Solskæl-leklo, og bring dem til Mebok Snurrefix i Skralleby.", d="Raptorerne i Ødemarken er klogere end raptorer i andre lande. Og jeg tror, al den klogskab gemmer sig i deres horn! Hvis det er rigtigt, så kan jeg male deres horn til pulver og bruge det til at lave \"kloge drikke.\" Jeg kunne sælge dem for en formue!!!\n\nOg du kan hjælpe mig. Find mig intakte raptor-horn fra Solskæl-leklo. De strejfer rundt i det sydlige Ødemark og i det nordlige Ødemark nær grænsen til Askedalen."},
  [866] = {n="Rodprøver", l="Bring 8 Rodprøver til Mebok Snurrefix i Skralleby.", d="Urterne i Ødemarken er ikke helt som urter i andre lande. Deres egenskaber er for det meste de samme, men oasevandet her forandrer planterne; de er bare lidt anderledes.\n\nJeg vil studere disse forskelle... for at se, om de kan udnyttes!\n\nHvis du er dygtig til urtekundskab, så saml rodprøver fra de urter, du finder i Ødemarken. Bring disse prøver tilbage, så jeg kan sammenligne dem med urter fra andre regioner."},
  [867] = {n="Harpy-angriberne", l="Saml 8 Hekvinge-klør.\n\nAflever dem til Darsok Hurtigdolk ved Korsvejen.", d="De forbandede harpyer har hærget vores karavaneforsyninger alt for længe. Det er på tide, vi skærer et par af deres halse over og mindsker deres antal.\n\nJeg har sneget mig rundt i deres reder og fundet ud af, hvem der leder hvem. Det mest ødelæggende angreb vil ødelægge en god del af deres nederste kommandokæde, og så kan vi arbejde os op til toppen.\n\nJeg starter dig roligt: dræb Hekvinge-harpyer og Hekvinge-skurkefjer i nordvest, og bring mig 8 Hekvinge-klør. Det burde være en god start..."},
  [868] = {n="Æggejagt", l="Bring 12 Silitid-æg og Gravekløen til Korrand ved Korsvejen.", d="Hej, <Name>. Jeg er blevet sendt til Korsvejen for at holde øje med landet og notere, hvad der sker for mine herrer i Orgrimgrad.\n\nEt af mine studieobjekter er de insektlignende væsener, der findes mod syd på Kæmpernes Mark. Vi ved lidt om væsenerne, så jeg har gjort det til en pligt at finde mere ud af det. De synes at have intelligens, mere end noget normalt dyr.\n\nTag denne gravekløe og saml nogle af væsenernes æg fra deres høje, men vær forsigtig: hvis de bliver alarmerede, vil de angribe dig."},
  [869] = {n="Raptor-tyvene", l="Bring 12 Raptor-hoveder til Gazrøg ved Korsvejen.", d="For ikke længe siden blev en forsendelse sølv stjålet fra vores vagttårn. Den var tænkt som lønning til Korsvejens vagter, og vi vil have sølvet tilbage.\n\nDet mærkelige er... vi fangede en af tyvene natten til tyveriet. Og... det var en raptor! Utroligt!\n\nJeg ved ikke, hvad raptorer vil med sølv. Men det er mig ligegyldigt -- jeg vil have raptorerne døde, så de ikke stjæler fra os igen!\n\nJag raptorer i Ødemarken. Saml deres hoveder til mig!"},
  [870] = {n="De Glemte Pøle", l="Rapportér tilbage til Tonja Runetotem med dine fund.", d="For længe siden var Ødemarken et frodigt sted, fyldt med liv. Men krig og kataklysme hærgede landet, brændte det og efterlod et tørt skal. Sådan er tingene, og det gør mit hjerte trist.\n\nMen inden for de seneste år er nye oaser dannet i Ødemarken, og livet vågner. Og dybt nede fornemmer vi druider en kraft, der sive sig op mod overfladen.\n\nVi må finde dens kilde. Rejs til De Glemte Pøle, nordvest for Korsvejen. Søg i vandet efter en kilde til kraft, og vend så tilbage hertil."},
  [871] = {n="Afbryd angrebene", l="Dræb 8 Barbermanke-vandsøgere, 8 Barbermanke-tornevævere og 3 Barbermanke-jægere, og vend derefter tilbage til Tork i Korsvejen.", d="Alle piggrisene er vores fjender, <Name>. Nogle viser sig bare at være mere besværlige end andre.\n\nBarbermanke-stammen har angrebet vores forsyningslinjer fra Durdotar og forvoldt os en uendelig irritation. Jeg har spejdere, der leder efter lederen af disse overfald, men indtil da vil ethvert tab, du kan påføre de snavsede svinemænd, hjælpe os.\n\nBegynd mod nordøst mod Durdotar. Du kan altid genkende deres huler på de enorme tornede ranker, der vokser op af jorden. Find dem, og dræb dem."},
  [872] = {n="Forstyrrelsen ender", l="Dræb 8 Barbermanke-geomancer, 8 Barbermanke-forsvarere og Kreenig Snerresnude.\n\nBring derefter Kreenig Snerresnudes hugtand til Tork i Korsvejen.", d="En af mine spejdere var vidne til et angreb på en karavane fra Durdotar, <Name>. Gerningsmændene er netop Barbermanke-stammen af piggrise. En af piggrisene leder især angrebene: Kreenig Snerresnude. Han blev set nordøst herfra, lige syd for vejen fra Durdotar. Hvis truslen skal stoppes, så må Kreenig dø.\n\nFor at sikre at angrebene ophører, mener jeg dog, at vi skal tilføje hån til deres skade. Dræb Kreenig sammen med flere af deres stamme, og vend tilbage til mig, når du har hans hugtand."},
  [873] = {n="Isha Vågen", l="Bring Isha Vågens Hjerte til Mahren Himmelspåer.", d="Den store Isha Vågen er herre over disse vande. Stor er hans styrke, og højtidelig hans stolthed. Menneskene ved kysten frygter ham, for han har slugt mange af dem.\n\nMen jeg frygter ham ikke. Jeg er taknemmelig for, at han er her. Han er en værdig udfordring og et ærefuldt bytte.\n\nHvis du er klar, så svøm ud og led efter Isha Vågen, Dybets Undergang.\n\nHans ånd bor i hans hjerte, og at høre dets slag er at kende din skæbne."},
  [874] = {n="Mahren Himmelspåer", l="Tal med Mahren Himmelspåer.", d="Du har jagtet Ødemarkens bæster. Din ånd er stærk. Men en jæger må altid være forberedt. En sand jæger kan liste sig efter bytte ad enhver sti. Bjerge og sumpe skal ikke få ham/hende på afveje.\n\nSelv ikke havet.\n\nFind min søster, Mahren. Hun jager de store vandbæster langs kysten. Hun vil lære dig deres veje.\n\nMen vær forsigtig i din søgen efter hende, for Ødemarkens kyst er besat af mennesker."},
  [875] = {n="Harpy-løjtnanterne", l="Saml 6 Harpy-løjtnantringe fra Hekvinge-dræberne, og aflever dem til Darsok Hurtigdolk ved Korsvejen.", d="Hahaha, <Name>. Tilbage for mere? Godt, jeg kan lide at høre det.\n\nDenne gang vil jeg have dig til at myrde nogle af harpy-løjtnanterne i De Tørre Bakker. Kun Hekvinge-dræbere kan være løjtnanter, og du kan kende dem på de ringe, de bærer. De er en ond flok, men de leder nogle af underlingene i området. At tage 6 af dem ud vil være et afgørende slag mod deres matriarkat.\n\nSørg for, at de dør smerteligt, <Name>. Vi vil have de harpyhore til at forstå dumheden i at kævle med Horden."},
  [876] = {n="Serena Blodfjer", l="Dræb Serena Blodfjer og bring hendes hoved tilbage til Darsok Hurtigdolk ved Korsvejen.", d="Du klarede dig så godt mod løjtnanterne og underlingene, at jeg gerne vil have dig til at gøre én sidste ting for mig.\n\nSerena Blodfjer er søster til en harpy ved navn Blodfjer, som blev dræbt af Rexar for en del tid siden. Tilsyneladende er disse angreb på Hordens karavaner hævn for hendes søsters død.\n\nJeg vil have dig til at skære halsen over på hende og bringe mig hendes hoved. Jeg vil placere det på den næste karavane, vi sender af sted... Giv de harpyer noget at tænke over."},
  [877] = {n="Den Stillestående Oase", l="Vend tilbage til Tonja ved Korsvejen, efter at have undersøgt Stillestående Oase.", d="Ligesom den du fandt ved De Glemte Pøle, kan der være revner ved de andre oaser i Ødemarken. Hvis det er tilfældet, så er revnerne måske oasernes kilde til liv.\n\nVi må teste dette.\n\nHer, tag disse frø. De er døde og golde, men tag dem med til Stillestående Oase mod sydøst. Hvis der er en revne der, så læg frøene i den... og observer."},
  [878] = {n="Stammer i krig", l="Dræb 6 Børsterygge-vandsøgere, 12 Børsterygge-tornevævere og 12 Børsterygge-geomancer, og vend tilbage til Kløvtand i Taurajo-lejren i Ødemarken.", d="Du må angribe mine fjender. <snort> Du må hjælpe Kløvtand og Barbermanke ved at svække Børsteryggene. Begge stammer er meget åndelige, knyttet til jorden og dens kraft. <snort> Det giver os styrke i alt... især i krig.\n\nHvis du vil finde ud af, hvem der virkelig forårsager Tork <snort> og Horden så stor lidelse, så hjælp Kløvtand! Du angriber Børsterygge-åndelederne mod nord; svæk dem, så Barbermanke kan besejre dem og herske over Ødemarken."},
  [879] = {n="Svig indefra", l="Dræb Nakk, Kusk og Lokk Orkebane, og bring deres kranier til Kløvtand i Taurajo-lejren i Ødemarken.", d="Tre af mit folk kom ud af Tornekrattet for at lede angrebene mod Horden, <Race>. <snort> De er ubarmhjertige og snedige, og hvis du besejrer dem, så vil Korsvejen og næsten hele Ødemarken lære fred... <snort> i hvert fald fra Barbermanke-stammen. <snort>\n\nNakk, Kusk og Lokk Orkebane er dem, du søger. De er langt mod syd i Ødemarken. En er tryllekunstner, en anden sporer, og deres leder, han der kaldes Orkebane, <snort> en kriger. Dræb dem, <Race>, ligesom de har dræbt mig."},
  [880] = {n="Forandrede Væsner", l="Bring 8 Forandrede Knipsekæbe-skaller til Tonja Runetotem ved Korsvejen.", d="Dine fund er utrolige, <Name>. Disse oaser rummer egenskaber, der må komme fra en ydre kilde. Eller måske en indre.\n\nJeg vil vide, hvordan disse revner påvirker dyrene, der drikker oasernes vand.\n\nJag knipsekæberne i Frodigvand- og Stillestående Oaserne. Bring mig deres skaller, så jeg kan undersøge dem."},
  [881] = {n="Ekeyakee", l="Bring Ekeyakees Hud til Sergra Mørktorn ved Korsvejen.", d="Hvidtågen, Ekeyakee på taurernes sprog, er kongen over savannekattene. Han jager så lydløst, at man siger, han er som en tynd, hvid tåge hen over jorden. Og han dræber så hurtigt, at hans bytte ikke får tid til frygt eller smerte.\n\nTaurerne siger, at han er både nåde og død.\n\nDu får snart at vide, om det er sandt, for nu sender jeg dig ad stien for at jage Ekeyakee. Hans hule ligger nordøst for Korsvejen, blandt knoglerne fra kæmpe-Kodoer\n\nAfsted. Blæs i dette horn, når du når hans hule. Blæs i hornet, og han vil komme."},
  [882] = {n="Isjamuhale", l="Bring Isjamuhales Hugtand til Jørn i Taurajo-lejren.", d="Isjamuhale, Spydtand, er den vildeste solskæl-raptor i Ødemarken. Han jager ikke for sporten, og heller ikke for maden. Han jager, fordi jagten er hans lidenskab. Han dræber, fordi det er hans natur at dræbe.\n\nOg du vil få at vide, hvordan hans natur er, <Name>, for din sti følger nu Isjamuhales kloede spor.\n\nBegynd jagten. Slå hans yndlingsbytte, en zhevrø, og bring dens kadaver til det døde træ nordvest for Skralleby. Isjamuhale vil lugte kadaveret og blive lokket til.\n\nVær klar, når han kommer."},
  [883] = {n="Lakotamani", l="Bring Lakotamanis Hov til Jørn i Taurajo-lejren.", d="Lakotamanis Hov er et symbol på de store kodoers styrke."},
  [884] = {n="Owatanka", l="Bring Owatankas Halespids til Jørn i Taurajo-lejren.", d="Når den berøres, springer gnister fra Owatankas halespids."},
  [885] = {n="Washte Pawne", l="Bring Washte Pawnes Fjer til Jørn Himmelspåer i Taurajo-lejren.", d="Washte Pawnes fjer gør ondt at røre ved."},
  [886] = {n="Ødemarkens Oaser", l="Tal med Tonja Runetotem ved Korsvejen.", d="Druiderne i Tordenklippe fornemmer en mærkelig kraft, der sive ind i Ødemarken, øst for Mulgorr.\n\nTonja Runetotem blev sendt for at finde kilden til denne kraft, men vi frygter, at han får brug for hjælp.\n\nRejs til Ødemarken og tal med Tonja. Han står ved Korsvejen. For at komme derhen, tag vejen mod øst ud fra Blodhov-landsbyen. Gå ind i Ødemarken, drej derefter mod nord, når vejen deler sig. Fortsæt mod nord, så finder du Korsvejen.\n\nOg forlad ikke vejen, <Name>, for Ødemarken er et hårdt land."},
  [887] = {n="Sydhavs-fribyttere", l="Dræb 12 Sydhavs-banditter og 6 Sydhavs-kanonérer for Gazlowe i Skralleby.", d="Jeg skulle så gerne ønske, at Viceadmiral Grusslik gjorde et bedre stykke arbejde med at holde havene sikre for vores handelsskibe. Med alt det guld, handelsprinserne har hældt ned i Handelsflåderne, bliver jeg rasende over at se så mange pirater flagre rundt uden mål og mening, plyndre mine skibe og stjæle mine varer!\n\nJeg har hørt, at Sydhavs-fribyttere har slået lejr lige syd for her. De har været en ægte torn i siden på mig, og hvis Grusslik ikke vil tage sig af dem, ja, så kan du måske hjælpe mig med at slippe af med dem."},
  [888] = {n="Stjålet Bytte", l="Hent forsendelsen med støvler og teleskoplinsen for Gazlowe i Skralleby.", d="Selvom jeg gerne ville have alle mine varer tilbage, er jeg sikker på, at det ikke er muligt. Men der er et par ting, jeg absolut må have!\n\nSom du kan se, er mit observatorium klar til brug, men det mangler den mindste af de to linser. Den første ankom med karavane fra Durdotar, men den anden blev sendt med skib og er aldrig kommet frem. Og jeg fik aldrig min forsendelse af støvler fra Dryppelik i Bytteviken!\n\nTag ned til piratlejren og se, om du kan finde dem."},
  [889] = {n="Vindens Ånd"},
  [891] = {n="Nordvagtens Kanoner", l="Kaptajn Thalo'thas Solskin i Skralleby vil have dig til at samle 10 Theramore-medaljer og slå Kaptajn Fjernbjerg, Kanonér Vessan og Kanonér Smed ihjel.", d="Endnu et skib fra min flåde er gået tabt til de alt for ivrige mennesker i Nordvagt-borgen!\n\nDe skiderikker må få en lektion. Deres paranoia har sat dem i raseri. Skyd-først-spørg-senere-typerne skyder løs på alt, de har i sigtekornet.\n\nRejs sydpå langs Handelskysten til borgen og belejr deres styrker. Bring mig medaljerne fra deres soldater som bevis. Og for min flådes skyld, slå Kaptajn Fjernbjerg og hendes overivrige kanonérer ihjel!"},
  [893] = {n="Våben efter Valg", l="Bring en Barbermanke-dolkestikker, en forkullet Barbermanke-stav og et Barbermanke-krigsskjold til Tatternack Stålsmed i Taurajo-lejren i Ødemarken.", d="Barbermanke-piggrisene mod syd, hinsides Kæmpernes Mark, har ifølge det, jeg har hørt, ingen dygtige smede, men de har tilsyneladende begyndt at lave hårdere våben. Jeg vil gerne få fat i et par forskellige typer for at lære deres teknikker, hvis det er muligt.\n\nHvis du vil bringe ære til Horden, så bring mig eksempler på deres våben. Find mig en dolk fra deres snigmordere, en stav fra deres seere og et skjold fra deres krigsraseri. Det burde gøre det!"},
  [894] = {n="Samoflange", l="Få adgang til kontrolkonsollen på Ventureselskabets forskningssted.", d="Ventureselskabet har sat et lille forskningsanlæg op langt nord for her, sydvest for Slamfennen. Jeg ved ikke meget om, hvad de laver, men jeg fik da fundet ud af, at de eksperimenterer med noget, de kalder en \"samoflange\".\n\nNu, hvad fanden er en samoflange? Ja, hvad det end er, vil jeg undersøge det, så jeg har brug for, at nogen henter det.\n\nJeg fik fat i en kopi af deres betjeningsmanual til kontrolsystemet, så du burde kunne regne ud, hvordan du kobler samoflangen fra det."},
  [895] = {n="EFTERLYST: Baron Langkyst", l="Bring hovedet af Baron Langkyst til Gazlowe i Skralleby.", d="EFTERLYST!\n\nBaron Langkyst, kaptajn på Det Hensynsløse\n\nKaptajn Langkyst fra Gilnæas fører skibe for Sydhavs-fribytterne og er eftersøgt for piratvirksomhed. Resterne skal være genkendelige!\n\n-- Gazlowe"},
  [896] = {n="Minearbejderens Lykke", l="Hent Katteøje-smaragden fra en af Ventureselskabets tilsynsmænd eller håndhævere for Havnemester Svimlig i Skralleby.", d="Som havnemester i en travl havn som Skralleby holder jeg fingeren på informationens puls. Jeg ved alt om udvekslingen af varer og penge mellem her og Bytteviken.\n\nDet seneste nyt, jeg har hørt, handler om Ventureselskabets Stenåre-mine nordøst for Slamfennen. En af minearbejderne fandt en smaragd på størrelse med din næve. Jeg kender et par købere, der ville være interesserede i sådan noget, og jeg ville være villig til at dele salget halvt om halvt."},
  [898] = {n="Fri fra Borgen", l="Eskorter Gilthares Ildbøjle sikkert tilbage til Kaptajn Solskin i Skralleby.", d="Endelig! Nogen, der kan redde mig!\n\nJeg kan ikke tro, du kom forbi vagterne. Disse fanatikere fra Theramøre er fuldstændig fra vid. De sænkede vores skib og fængslede mig, den eneste overlevende. Jeg blev kaldt en fjende og en trussel mod Alliancen.\n\nMig! En trussel mod deres store skuffelse af en Alliance! Jeg var dækmand på en månelys-transport mellem Skralleby og Bytteviken.\n\nNok snak. Hjælp mig tilbage til Skralleby, vil du? Sig til, når du er klar, så bryder vi ud."},
  [899] = {n="Fortæret af Had", l="Bring 60 Børsterygge-piggris-hugtænder til Mankrig i Korsvejen.", d="Måske kender du smerten ved usikkerhed, måske ikke, <Class>. Men vid dette: Jeg står her hver dag, fra solen står op til den går ned, og speder horisonten efter flere af de monstre. Jeg har dræbt hver eneste grisemand, jeg er stødt på siden, men min tørst efter deres blod er langt fra slukket. Måske skulle jeg have taget mod Taurajo i stedet for at gå nordpå til Korsvejen.\n\nDu, <Class> -- du kunne hjælpe mig.\n\nDræb dem. Dræb så mange, du kan. Bring mig deres hugtænder, så fejrer vi deres død sammen."},
  [900] = {n="Samoflange", l="Luk for Brændstofkontrolventilen, Regulatorventilen og Hovedkontrolventilen, og brug derefter kontrolkonsollen igen.", d="De tre kontrolventiler er i øjeblikket åbne. De forskellige aflæsninger på kontrolpanelet får dig til at formode, at de må lukkes, før apparatet kan slukkes."},
  [902] = {n="Samoflange", l="Returner Samoflangen til Sprutventil i Skralleby.", d="Når man åbner kontrolkonsollens front, afslører den en tæt rodet samling af ledninger, slanger og andre mærkelige mekaniske genstande, hvoraf de fleste tilsyneladende ingen praktisk funktion har. Du skubber dem til side, graver dybere ned i konsollen og finder samoflangen. Et ryk, og den løsner sig fra sit hus."},
  [903] = {n="Ødemarkens Lurere", l="Saml 7 Lurer-kløer fra Savannah-lurere for Sergra Mørktorn i Korsvejen.", d="Nu er det tid til at jagte noget, der virkelig bider. Ødemarkens lurere er en sej race. Seje, opfindsomme, snedige ... og dødelige. Du finder dem blandt de høje græsstrå. Du finder mange sydvest for Korsvejen.\n\nVær på vagt, når du jager dem, <Name>, ellers kan du ende med ikke længere at være rovdyret, men byttet."},
  [905] = {n="De Vrede Leklo'er", l="Dræb solskæl-raptorer og saml deres fjer. Læg fjerene på de 3 Leklo-reder. Vend tilbage til Sergra Mørktorn i Korsvejen.", d="Nu, <Name>, bliver jagten dybere. Nu skal du besejre dit bytte og derefter finde vej til dets hule.\n\nJag solskæl-raptorerne mod syd. Slå dem ihjel og fjern de fjer, de bærer. Læg fjerene på leklo-rederne sydvest for Stillestående Oase. Vis deres brødre, at du ikke frygter dem!"},
  [906] = {n="Forræderi Indefra", l="Bring Lokks Kranium til Tork i Korsvejen i Ødemarken.", d="Tag Lokks hoved til Tork i Korsvejen, <Race>. <snort> Han burde vide, hvad der er sket med min stamme uden ord -- ha, ikke at han ville tro, at Kløvtand hjalp til med <snort> sådan noget. Men jeg er sikker på, at han vil belønne dig for at udføre sådan en stor gerning. <snort>\n\nJeg vil blive ved med at velsigne dig med Agamagg'ans kraft, så længe jeg bliver i denne bur, <Race>. Indtil da, farvel."},
  [907] = {n="Rasende Tordenøgler", l="Bring 3 Tordenøgle-blod til Jørn Himmelspåer i Taurajo-lejren.", d="Nu, <Name>, skal du møde de store tordenøgler. Så store er bæstene, at jorden buldrer, når de traver hen over slettene. Pas på, når du kæmper med dem, for ét forkert skridt, og du kan ende under deres fødder.\n\nDu finder tordenøglerne i den sydlige Ødemark. De kaldes Stormsnuder, Stormhuder og Tordenhoveder. Vend tilbage til mig, når du har besejret dem."},
  [913] = {n="Tordenfalkens Skrig", l="Find og slå en Tordenfalk ihjel, og bring dens vinger til Jørn Himmelspåer i Taurajo-lejren.", d="Tordenfalken, <Name>, er et vildt væsen. Nu er det tid for dig at møde dem. Du skal finde, hvor den strejfer, og bringe mig dens vinger som bevis på din vellykkede jagt.\n\nGør du det, nærmer din tid hos mig sig enden."},
  [914] = {n="Fangets Ledere", l="Bring Kobrahns, Anakondras, Pythas' og Serpentis' ædelsten til Nara Vildmanke i Tordenklippe.", d="Druiderne i Jammergrotterne, Fangets Druider, er en misfoster. De var en del af en orden af ædle druider, hvis plan var at hele Ødemarken, men nu stræber de efter at omforme landet til deres egne snoede drømme.\n\nFangets Druider har fire ledere, og hver af dem besidder en drømmeædelsten. Selv nu hjemsøger deres ansigter mig! Besejr lederne og bring mig deres ædelstene, så kan Ødemarken igen kende fred.\n\nAfsted, <Name>. Du finder dem skjult dybt inde i Jammergrotterne."},
  [923] = {n="Tumorer", l="Bring 5 Mosede Tumorer til Rellian Grønspyd i Darnassos.", d="Der gror en ondskab i tømmerlingene. Vi forsøger at finde kilden, men indtil da... for at holde Teldrasil sikkert må vi fælde de tømmerlinge, som er ude over hjælp. De, der vandrer rundt om Brøndsøen i det nordlige Teldrasil, er de mest besmittede. De må fjernes!\n\nTilintetgør de tømmerlinge, du finder der, og saml de mosede tumorer, der gror på dem. Bring tumorerne til mig, så de kan blive brændt."},
  [924] = {n="Dæmonfrøet", l="Tag en Fejlbehæftet Kraftsten. Bring den til Ildalteret, før stenen udløber, og vend så tilbage til Ak'Zelot.", d="Dæmonfrøet er et kraftfuldt redskab for den Brændende Legion. Det hviler i en hule på Rædselståge-toppen, over et dæmonisk ildalter.\n\nJeg har forberedt kraftsten, der, når de placeres nær frøet, vil afbryde dets forbindelse til Legionen.\n\nTag en sten fra bordet og bring den til ildalteret på toppen af Rædselståge-toppen. Rejs mod vest, og når vejen deler sig, mod nord. Toppen vil være til din venstre. Den sikreste bestigning går op ad dens nordside.\n\nOg skynd dig – stenens kraft vil forbruge sig selv med tiden."},
  [942] = {n="Den Distræte Prospektor", l="Tag det mystiske fossil til Arkæolog Krukmaven i Menetil-havnen.", d="Dette fossil ligner slående et, jeg engang så i Jernsmede. En arkæolog ved navn Krukmaven bragte det til vores årlige konference for Opdagelsesrejsende-Ligaen. Han mente, at fossilet havde en kraft, som på en eller anden måde kunne låses op.\n\nSidst jeg hørte, havde Krukmaven slået sig ned i Dybvandskroen i Menetil-havnen og ventede på at blive eskorteret til Whelgar-udgravningsstedet. Find ham og vis ham Remrejses fossil. Måske kan han afsløre fortidens hemmeligheder.\n\nSkibet til Menetil afgår fra Auberdin."},
  [943] = {n="Den Distræte Prospektor", l="Arkæolog Krukmaven i Menetil-havnen vil have dig til at bringe ham Relu-stenen og Krukmavens Fossil.", d="Prospektor Whelgar har nu det originale fossil på sin udgravning i Vådlandene. Da jeg opdagede Relu-stenen, troede jeg, at den var nøglen til at låse fossilets mysterium op.\n\nMens jeg var på vej til at møde Whelgar, blev jeg angrebet af raptorer, og relikvien gik tabt. Jeg ved ikke, hvilken af de plettede bæster der slugte relikvien, men hvis du kan hente den, kan jeg frigøre artefakternes kraft.\n\nBring mig både Relu-stenen og det originale fossil, han har."},
  [945] = {n="Therymånes Flugt", l="Hjælp Therymåne med at flygte, og fortæl så Therysilje ved Aesinas Helligdom, at hendes søster er i sikkerhed.", d="Hjælp!\n\nJeg vandrede rundt i Mesterens Glaive, og de beskidte kultister omringede mig. Heldigvis er jeg god til at gemme mig!!\n\nKan du hjælpe mig herfra? Og jeg må sende bud til min søster Therysilje, at jeg har det godt. Hun er i Askedalen mod syd, ved Aesinas Helligdom."},
  [947] = {n="Hulesvampe", l="Bring 5 Ruskende Stilke og 1 Dødhætte til Barithras Månskygge i Auberdin.", d="Jeg er ved at udvikle en eliksir, der kræver sjældne svampe, svampe der kun vokser i en bestemt hule. Hulen ligger bag Klippefjeder-faldene, mod øst og lidt nordpå langs bjergene.\n\nJeg ville selv tage derhen, men Lunden for de Ældgamle har rådet mig til at holde mig væk fra stedet. Vores ærværdige allierede fornemmer, at hulen er gemmestedet for en ny ondskab i Mørkekysten.\n\nVær så venlig, <Name>, saml svampene til mig. Og mens du gør det, så udforsk hulen for at bekræfte de Ældgamles frygt."},
  [948] = {n="Unu", l="Tal med Unu i Lunden for de Ældgamle.", d="Unu, en Ældgammel Vidensbærer i Lunden for de Ældgamle, kender til din rejse til Klippevands-faldene og ønsker at tale med dig. Lunden ligger mod syd, indbygget i bjergene.\n\nDe Ældgamle er tålmodige og kloge, <Name>. Men hvis Unu søger dit råd om det, du så i faldene, så frygter jeg, at det er hastende."},
  [951] = {n="Matystra-relikvierne", l="Bring 6 Matystra-relikvier til Unu i Lunden for de Ældgamle.", d="Pergamentet, du fandt i Mesterens Glaive, er en side fra en gammel tekst... skrevet af alverne! Den er tungt forbandet og besmittet af Tusmørkets Hammers korruption, men det ser ud til, at kulten bruger gammel alvemagi til at bringe deres gamle herrer tilbage til vores verden.\n\nRejs til ruinerne af Matystra mod nordøst, og søg efter gamle relikvier blandt græsset og de knuste sten. Gennem deres studium kan vi tyde, hvordan Tusmørkets Hammer har tænkt sig at udnytte alvernes magi."},
  [952] = {n="Lunden for de Ældgamle", l="Lever Fandrels besked til Unu i Lunden for de Ældgamle i Mørkekysten, syd for Auberdin.", d="Hvis du havde tid nok til at bære beskeder for Orakeltræet, så er jeg sikker på, at jeg kan få dig til at levere en besked til Lunden for de Ældgamle i Mørkekysten, lige sydpå fra Auberdin.\n\nDu skal sandsynligvis sikre dig transport på en hippogryf, men jeg har nok tillid til dig til, at du kan klare det. Tag dette til Unu, den Ældgamle Vidensbærer. Han har ventet på ord fra mig, ligesom jeg har ventet på nyheder fra Orakellunden."},
  [954] = {n="Bashalhand", l="Find kilden til det mærkelige blå skær i ruinerne af Bashalhand.", d="Ruinerne af Bashalhand mod øst er oversvømmet af dæmoniske håndlangere. Sprites og satyrer, der har slået sig ned i området, lever af områdets magiske energier, og deres kræfter vokser ved fortsat eksponering.\n\nDesuden har jeg bemærket, at der er ét alter, de ikke vil nærme sig. På områdets vestlige side, oven på en lille klippeknold, gennemtrænger et mærkeligt blåt skær... Der må være en forklaring på dæmonernes tøven.\n\nJeg vil gerne have dig til at undersøge det."},
  [958] = {n="Højfødtes Redskaber", l="Hent 7 Højfødt-relikvier til Thundris Vindvæver i Auberdin.", d="<Class>. En opgave, jeg vil bede dig om.\n\nHar du set ruinerne af Amethand? Hvis ikke, finder du dem på den østlige side af hovedvejen, et stykke mod syd. Engang var de hjemsted for mange mægtige Højfødte, nu er de et vidnesbyrd om den ødelæggelse, deres eksperimenter frembragte.\n\nVogterne har fortalt mig, at de Højfødtes ånder består, og at de bruger deres gamle magiske redskaber. Disse relikvier skal konfiskeres, så vi kan ødelægge dem."},
  [959] = {n="Ballade ved havnen", l="Kranfører Storfnug i Skralleby vil have dig til at hente flasken med 99 År Gammel Portvin fra Gal Magglish, som gemmer sig i Jammergrotterne.", d="Ups!\n\nLidt af en ulykke, som du kan se! Morgenens fragtforsendelse fra Bytteviken var enorm. Enorm, siger jeg! Har aldrig set så mange kasser. Nå, jeg prøvede at fremskynde tingene, så jeg begyndte at læsse lidt mere af, end jeg kunne klare. Det var da alting væltede ned.\n\nInden jeg vidste af det, så jeg den plage, Gal Magglish, løbe væk med en flaske 99 år gammel portvin. Jagtede ham hele vejen til Jammergrotterne. Der var ingen chance for, at jeg ville gå derind.\n\nMåske er du modig nok til at finde ham?"},
  [962] = {n="Slangeblomst", l="Apoteker Zamah i Tordenklippe vil have dig til at samle 10 Slangeblomster.", d="Det Kongelige Apotekerselskab, med base i den store Undergrund i Herrelande, har sendt mig hertil for en meget særlig tjeneste, <Name>. Måske ønsker du at hjælpe mig, og dermed Den Mørke Dame i vores bestræbelser på at fremme De Forladte.\n\nFor nylig studerede jeg et sjældent eksemplar af en plante ved navn Slangeblomst. Jeg tror, at denne urt i større mængder har et stort potentiale.\n\nDesværre kan Slangeblomst kun findes i de mørkeste afkroge af Jammergrotterne, et farligt hulesystem i Ødemarken."},
  [963] = {n="For evig kærlighed", l="Befri Anaya Morgenløbers ånd og bring hendes vedhæng tilbage til Cerellean Hvidklo i Auberdin.", d="Efter kampene ved Evighedens Brønd hørte jeg, at Ameth'Aran var blevet ødelagt, dets folk døde, deriblandt min elskede Anaya.\n\nJeg kunne aldrig have troet, at minder om Anaya tusinder af år senere stadig ville hjemsøge mine drømme. Da jeg vandrede i en døs gennem skovene i Mørkekysten, befandt jeg mig i ruinerne af Amethand... hvor jeg så min elskedes hjemsøgte ånd.\n\nHun må befries, men jeg mangler hjertet til at gøre det. Hendes ånd må tilintetgøres."},
  [965] = {n="Althalaxx' Tårn", l="Find Balthule Skyggestød nær Althalaxx' Tårn i Mørkekysten.", d="Hil dig, unge <Race>. Jeg er Elissa Stjernebrise, og det er min opgave at beskytte Auberdin mod skade.\n\nTil dette formål sendte jeg Balthule Skyggestød for at observere de mærkelige begivenheder omkring Althalaxx' Tårn mod nordøst.\n\nDet er længe siden, han skulle være vendt tilbage. Jeg er bekymret for, at han er stødt på en uforudset fare i skoven. Jeg ville sætte stor pris på, hvis du ville finde ham og sørge for, at han har det godt."},
  [967] = {n="Althalaxx' Tårn", l="Lever Balthules brev til Delgren Renseren i Askedalens Skov.", d="Min mester, Delgren Renseren, er en paladin, der nådigt har tilbudt at hjælpe med at forsvare vores skove mod dæmonernes og de udødes styrker. Han har lært mig meget om det Hellige Lys og kunsten at kæmpe.\n\nDelgren må omgående høre om kultens færd.\n\nDu finder ham langt mod syd herfra ved Maestras Post i Askedalens Skov. Vær hurtig, jeg frygter, at Mørkestrandens trussel vokser for hver time, der går."},
  [968] = {n="De Kræfter Nedenunder", l="Bring Bogen: De Kræfter Nedenunder til Gerrig Knoglegreb i Det Forladte Hulrum, Jernsmede.", d="Selvom den er forfærdeligt slidt og ridset, kan titlen på denne bog stadig læses på forsiden:\n\nDe Kræfter Nedenunder\n\nInde i bogen findes en liste over uudtalelige navne med ildevarslende titler, tilbedelsesmetoder og foretrukne ofre... hvoraf mange involverer levende, menneskelignende væsener.\n\nPå bogens indvendige forside står: \"Knoglegrebs Runer og Undergang, Det Forladte Hulrum, Jernsmede. Ejer: Gerrig Knoglegreb.\"\n\nHvis Knoglegreb sælger bøger som denne, køber han måske denne tilbage."},
  [970] = {n="Althalaxx' Tårn", l="Saml en Glødende Sjælsten og returner den til Delgren Renseren ved Maestras Post.", d="Balthules brev er alvorligt. Denne Mørkestrandens Kult er en torn i min side, der må fjernes. Jeg har haft at gøre med noget af Mørkestrandens svineri nordøst herfra ved Ordilhand. Et af dem besidder en sjælsten, som jeg tror rummer hemmeligheden bag kultens magt.\n\nBring den til mig, så kan jeg tyde de hemmeligheder, den gemmer på."},
  [971] = {n="Viden i dybet", l="Bring Lorgalis-manuskriptet til Gerrig Knoglegreb i Det Forladte Hulrum i Jernsmede.", d="Som du måske ved, samler jeg på viden. Gammel viden. Kraftfuld viden. Viden, der åbner døre, og viden, der kan vække Dem Der Sover.\n\nDer går rygter om et gammelt stykke viden, Lorgalis-manuskriptet, på bunden af Den Sorte Afgrund i Askedalen. Stedet er gamle, længst døde alvers boliger. Alver, der besad stor viden, før deres by faldt i ruin.\n\nGennemsøg Den Sorte Afgrund efter manuskriptet. Gør du det, glemmer jeg det aldrig. Ikke engang efter ... de sidste dage."},
  [973] = {n="Althalaxx' Tårn", l="Bring Ilkrud Magtruls Tome til Delgren Renseren ved Maestras Post.", d="Ilkrud Magtrul. Ja, jeg kender til ham. Han er en mægtig ork-warlock, der residerer ved Ildarrets Helligdom, et sted med stor ondskab i det sydvestlige Askedalen.\n\nIndtil nu har han kun været en lille irritation, og jeg har ikke gjort noget ved ham, men det ser ud til, at hans tid er kommet."},
  [976] = {n="Forsyninger til Auberdin", l="Tal med Delgren Renseren ved Maestras Post, efter du har fået Fero sikkert igennem Askedalens Skov.", d="Delgren har bedt mig om at levere beskeder og forsyninger til Vagterinde Stjernebrise i Auberdin, men jeg er tøvende med at tage af sted alene. Farlige fjender færdes i skoven, og jeg har ingen lyst til at risikere, at disse forsyninger og oplysninger havner i de forkerte hænder.\n\nHvis du og andre kunne fungere som mine livvagter, kunne jeg tage af sted nu. Med din beskyttelse tvivler jeg ikke på, at vi kan bringe varerne sikkert til Auberdin."},
  [982] = {n="Dybt hav, vidt hav", l="Hent Sølvdæmrings Låsekasse og Tågeslørets Låsekasse til Gorbold Stålhånd i Auberdin. Begge genstande bør findes i vragene af skibene nord for landsbyen.", d="Ud for Mørkekysten mod nord ligger to skibsvrag – Sølvdæmring og Tågeslør. For et stykke tid siden kom begge skibe i unåde hos de sprængte mudderfisk, da de sejlede over det vidtstrakte hav mod Auberdin. Nu ligger de på havbunden som trofæer for disse svin.\n\nBegge kaptajner kom ikke ud af det den nat, og deres logbøger og andre ejendele ligger stadig nede i låsekasserne. Jeg vil gerne have, at du henter dem for os; det ville betyde meget for de besætningsmedlemmer, der stadig er i egnen."},
  [984] = {n="Hvor stor en trussel?", l="Find en korrupt pelsbolg-lejr i Mørkekysten og vend tilbage til Terentis i Auberdin.", d="Nogle af mine brødre blev reddet fra en korrumperet pelsbolg i Teldrasil, og jeg har svoret at stoppe flere grusomheder, før flere af vores slags bliver såret... eller værre.\n\nJeg har allerede set et par tegn på korruption i Mørkekysten, men jeg har endnu ikke fundet nogen udbredte tegn. Jeg synes, det ville være logisk, hvis undersøgelsen fortsatte med pelsbolgene. Vil du finde en af deres lejre og vende tilbage til mig, hvis du ser tegn på korruption?"},
  [985] = {n="Hvor stor en trussel?", l="Dræb 8 Sortskov-stifindere og 5 Sortskov-vindtalere og vend tilbage til Terentis i Auberdin.", d="Du har allerede vist dig dygtig til at spejde vores fjende, <Name>. Har du, hvad der skal til for også at kæmpe mod dem?\n\nIkke alle eventyrere foretrækker ligefrem kamp frem for snigeri og undvigelse.\n\nHvis du tror, du er klar til opgaven, så er pelsbolglejren syd for Auberdin i øjeblikket den største trussel mod vores folk. Der finder du en del af Sortskov-stammen. Dræb 8 stifindere og 5 vindtalere, og vend tilbage til mig her."},
  [986] = {n="En tabt mester", l="Find 5 Fine Månesnigerpelse og returner dem til Terentis i Auberdin.", d="<Name>, dine evner har allerede hjulpet mig i mit foretagende. Kunne jeg bede dig om at hjælpe igen, denne gang med Grimklo og hans mester Volkor? Desuden kan jeg lave en magisk kappe til dig, så du kan bevæge dig uhindret af Mørkekystens skabninger, mens du leder efter ham.\n\nFor at lave kappen skal jeg bruge fem fine månesnigerpelse fra en månesniger-hanne eller -hun for at få nok materiale. Kattene findes ved Vildbøjningsfloden mod syd, eller endnu længere mod syd nær Askedalen."},
  [990] = {n="Rejsen til Askedalen", l="Find Raene Ulvefører i Askedalen.", d="<Name>, min herskerinde, Raene Ulvefører, venter dig i byen Stjernelund i Askedalen. Med din hjælp kan vi måske i det mindste lindre noget af den korruption, der har grebet fat dér.\n\nGå sydpå herfra og hold dig tæt på vejen--du finder frem uden problemer, hvis du følger de anvisninger."},
  [991] = {n="Raenes Rensning", l="Find Terøn i Askedalen.", d="<Name>, en gammel ven af mig hjælper også vagterne her i Askedalen, men han er endnu ikke vendt tilbage.\n\nHan havde spor om en genstand, som han mente kunne bremse pelsbolgenes angreb på vores folk--en stav skabt af en nu død, ond troldmand.\n\nFør han forlod stedet, nævnte han, at han ville opsøge en ædelsten til staven.\n\nHan nævnte, at ædelstenen muligvis var gemt ved helligdommen i Falathim-søen ved foden af bjerget mod vest. Ædelstenen blev opbevaret dér, før stedet blev overrendt.\n\nFind min ven, <Name>, venligst."},
  [993] = {n="En Fortabt Mester", l="Find Volkor i Mørkekysten og giv ham den Fortryllede Månesniger-kappe.", d="Kappen er færdig, <Name>. Tiden er kommet til at finde Volkor. Jeg kan kun håbe, vi er i tide.\n\nKappens magi varer ikke længe, når den først er aktiveret; måske fem minutter. Det bliver op til dig at vide, hvornår den skal bruges: Jeg vil foreslå, at du venter, til du finder Grimklo.\n\nHvis det, han har fortalt mig, er sandt, finder du sin mester i en hule sydpå herfra. Grimklo vil stå ved siden af vejen og vente på dig. Signalér til ham ved at vinke, når du ser ham, så peger han vej mod sin mester."},
  [1001] = {n="Summekasse 411", l="Indsaml 3 Tærsker-øjne fra Mørkekyst-tærskere i det dybe hav nær Summekasse 411.", d="En lille stemme knitrer dybt inde fra maskinen.\n\n\"Vidunderbang her! Den næste Summekasse står nord for Auberdin, på stranden\n\nSå den Summekasse er nummer 411, og den skal bruge 3 Tærsker-øjne til sin reparation. De ligger lige ud for kysten! Mørkekyst-tærskerne... *Hik*... Undskyld det...\n\nLige som sidste gang, når du giver Summekassen varerne, spytter den din belønning ud. *Hik*... Hvad? Nej, jeg har det fint!\""},
  [1002] = {n="Summekasse 323", l="Indsaml 6 Månesniger-hugtænder og læg dem i Summekasse 323.", d="Summekassen udsender et sprøjt af statisk støj, idet du hører Vidunderbang begynde at tale.\n\n\"Den næste Summekasse er nummer 323. Lidt nor' for Auberdin, men... hvor er øllen? Hva'? Åh, den står ved vejen, så du burde ikke have svært ved at finde den nær broen.\"\n\nVidunderbang mumler noget usammenhængende, før du hører en høj slurpelyd.\n\n\"Den her skal bruge Månesniger-hugtænder... 6 af dem.\""},
  [1008] = {n="Zoram-strandbredden", l="Bring 20 Vredhale-hoveder til Shindrell Hurtigild i Stjernelund.", d="Der lurer ondskab på vores nordvestlige kyst, kendt som Zoram-strandbredden.\n\nDet er hvilestedet for den dømte by Zoram, ødelagt under Sønderrivelsen og sunket under havet. Den har været tabt for nattealferne i evigheder. Tabt og næsten glemt.\n\nNu er nagaerne vendt tilbage, og af hvilken grund, ved vi ikke. Men grunden betyder lidt; vi må slå disse fjender ihjel og kaste dem tilbage i dybet!\n\nKom tilbage til mig, når din mission er fuldført."},
  [1009] = {n="Rutsel", l="Bring Zorams Ring til Talan nær Zoram-strandbredden.", d="Jeg frygter, at den gamle statuettes hemmeligheder vil forblive skjult for evigt, medmindre du finder nøglen til dens gamle lås.\n\nDen nøgle er en ring, Zorams Ring. Den tilhørte byens herskere, før bølgerne fra Sønderrivelsen druknede den.\n\nI årevis var ringen tabt, men nagaerne har for nylig fundet den.\n\nDeres leder, Rutsel, bor på en ø i den nordlige kant af Zoram. Venligst, <Name>, hent ringen til mig!"},
  [1010] = {n="Bathrans Hår", l="Bring 5 Bathrans Hår til Orendil Bredblad i Askedalen.", d="Der var engang en plante, der voksede i de gamle ruiner af Bathrans Hjemsøgte mod nord. Planten kaldtes Bathrans Hår og var kendt for at kurere åndelige lidelser.\n\nDer er et sygt barn i landsbyen, og jeg tror, det er mere end en fysisk sygdom. Vil du tage til Bathrans Hjemsøgte og lede efter Bathrans Hår? Jeg får måske brug for det til at behandle barnet ordentligt.\n\nBathrans Hjemsøgte ligger nord for Maestras Post og lige syd for grænsen til Mørkekysten."},
  [1011] = {n="De Forladtes Sygdomme", l="Bring en Sygdomsflaske til Kayneth Stillevind i Skovsang.", d="De Forladte, den udøde arm af Horden, har sneget sig ind i Askedalen og lurer ved vores ruiner og gravhøje. Vi tror, deres mål er at sprede sygdom blandt nattealfernes lande. Det må vi bekræfte!\n\nDe Forladte har en lejr sydpå herfra, nær Dor'danil-gravhulen, hvor de skaber gifte og sygdomme og hælder dem på flasker. Kæmp dig ind i den lejr og stjæl en sygdomsflaske. Vend tilbage med en sådan flaske. Jeg vil teste den og finde ud af dens formål."},
  [1012] = {n="Sindssyge Druider", l="Dræb druiderne: Taneel Mørkeskov, Uthil Månekald, Mavoris Skysbrud; vend derefter tilbage til Kayneth Stillevind i Skovsang.", d="Mens jeg kæmpede med De Forladtes gifte, havde jeg et syn. Jeg så druiderne i Dor'danil-gravhulen, forgiftet... myrdet af de udøde! De er nu vildfarne spøgelser, revet fra deres legemer og drevet til vanvid.\n\nFor at druidernes ånder en dag kan finde fred, må du gå ind i Dor'danil-gravhulen og nedkæmpe dens engang så store ledere: Taneel Mørkeskov, Uthil Månekald og Mavoris Skysbrud.\n\nGør dette, og vend derefter tilbage til mig."},
  [1013] = {n="Urs Bog", l="Bring Urs Bog til Vogter Bel'dugur i Apotekeriet i Undergrunden.", d="<Name>, Skyggetandsborgen gemmer en bog, Urs Bog, som ville være højt værdsat i min samling. Ur var en stor magiker fra Dalarn før Svøbens komme, og hans studier af andre verdener er af stor værdi for ... visse parter blandt De Forladte.\n\nGå ind i Skyggetandsborgen og find bogen. Bring den til mig, så vil jeg melde din tjeneste til vores Mørke Dame..."},
  [1014] = {n="Arugel Må Dø", l="Dræb Arugel og bring hans hoved til Dalar Morgenvæver i Gravkammeret.", d="Arugel holder stadig til i Skyggetandsborgen. Vi kan ikke gøre krav på Sølvfyrreskoven som strategisk højborg for Den Mørke Dame, før Arugel er slået ihjel.\n\nJeg skal nok sørge for, at hans magi bliver udryddet, <Name>. Men jeg overlader det til dig at sørge for, at Arugel møder den død, han så rigt fortjener.\n\nRejs til Skyggetandsborgen og gør en ende på Arugels onde trylleformularer én gang for alle. Bring mig den ondskabsfulde troldmands hoved!"},
  [1016] = {n="Elementar-armbånd", l="Indsaml 5 intakte Elementar-armbånd og brug Spådomsrullen på dem. Bring derefter den spåede rulle til Vagt Velene Stjernestød i Sølvvindsfristedet.", d="Tag denne spådomsrulle--den kan afgøre, hvem der har skabt disse elementarer. Men du skal bruge noget fra dem som reagens for at fokusere rullens magi--deres armbånd bør gøre det fint.\n\nNogle få intakte armbånd fra skabningerne bør være nok. De andre armbånd vil være ubrugelige til vores formål, men de kan måske være noget værd for en handelsmand, hvis du vil sælge dem. Når du har de intakte armbånd, skal du forsøge at bruge rullen. Vend tilbage til mig med resultatet, så går vi videre derfra."},
  [1017] = {n="Magikerkalderen", l="Slå Sarilus Ondbryg ihjel og bring hans hoved til Vagt Velene Stjernestød i Sølvvindsfristedet.", d="Der er kun én udød magiker i Ødemarken, som er i stand til at besudle så mange vandelementarer. Han er også den eneste, der er dum nok til at forsøge det. Sarilus Ondbryg sidder sikkert på toppen af Rædselståge-toppen og griner ad mig.\n\n<Name>, du må trænge ind på fjendens område og tilintetgøre denne ugerning. Jeg har fået nok af hans idioti, og vi må vise ham, hvad der sker med dem, der irriterer Vagterne.\n\nTilintetgør ham og bring mig hans hoved. Vær dog på vagt, for Horden holder måske øje med dig."},
  [1020] = {n="Orendils Kur", l="Bring Orendils Kur til Pelturas Hvidmåne i Stjernelund.", d="<Name>, jeg har lavet en kur, som jeg tror vil hjælpe det syge barn. Tag den til Stjernelund og giv den til barnets forælder, Pelturas Hvidmåne.\n\nFor at nå Stjernelund følger du vejen sydpå og derefter mod øst."},
  [1023] = {n="Raenes Rensning", l="Find den Glødende Ædelsten og vend tilbage til Raene Ulvefører i Stjernelund med Terøns Dagbog.", d="Mens du roder i Terøns ejendele, finder du en dagbog, der stadig er i god stand.\n\nDu tager dagbogen og lader Terøns lig ligge, som det er.\n\nDet eneste, der er tilbage at gøre, er at finde ædelstenen, som Terøn ledte efter. Raene nævnte, at den var i området. Måske har mudderfiskene den..."},
  [1024] = {n="Raenes Rensning", l="Find Shael'drøn ved månebrønden mod nordøst.", d="Du må selv undersøge det, men ud fra de noter, Terøn har skrevet, lyder det som om, at din næste opgave er at finde de andre dele af den stav, Dartel skabte. Jeg ville starte med at tage til månebrønden øst for Iris-søen. Når du er klar, følger du vejen og drejer mod nord, når du når et lille siddeområde på din venstre side.\n\nEn dryade ved navn Shael'drøn er bedre egnet til at vejlede dig. Opsøg hende.\n\nBehold ædelstenen hos dig--Shael'drøn får brug for den, hvis hun skal hjælpe dig med at genskabe staven."},
  [1025] = {n="Et Aggressivt Forsvar", l="Dræb 1 Hulevagt, 2 Bjørnebeester, 10 Totemister og 12 Krigere af Rådskov-stammen, og vend derefter tilbage til Raene Ulvefører i Stjernelund.", d="Før du rejser til månebrønden, har jeg en anden opgave, som vil hjælpe folket i Askedalen, hvis du har lyst til at prøve dine evner.\n\nLangs vejen mod øst, før Falfarren-floden, har pelsbolge angrebet rejsende. Deres pinte sind lever af frygt, og deres appetit stilles med uskyldiges blod.\n\nHjælp Vagterne med at beskytte landene ved at vise disse monstre den samme nåde, de har vist vores folk.\n\nJeg tror, deres lejre ligger syd for vejen... vær forsigtig."},
  [1026] = {n="Raenes Rensning", l="Find Træ-nøglen og et stykke af Dartels Stav, før du vender tilbage til Shael'drøn ved månebrønden.", d="Jeg ønsker, at dine budskaber var bedre.\n\nRaene har ret, jeg kender til Dartels skabelse og træjætterne i området--i hvert fald gjorde jeg engang. De er blevet korrumperede nu, deres natur forvredet.\n\nHvis dit mål er at finde den næste del af staven, må du finde nøglen til kisten, den ligger i.\n\nTræ-nøglen findes på en af træjætterne nordøst herfra, nær Ondskoven. Når du har den, skal du lede efter en lille lysning vest for vejen ved grænsen til Ondskoven... kisten bør være gemt deromkring."},
  [1027] = {n="Raenes Rensning", l="Find den sidste del af Dartels Stav og vend tilbage til Shael'drøn ved månebrønden.", d="Den sidste del af staven blev givet til druiderne i Dor'danil til opbevaring. Jeg aner ikke, hvor de gemte den. Jeg beklager, at jeg ikke kan hjælpe dig mere end det.\n\nAlt, jeg kan fortælle dig, er at følge vejen, der fører mod Ødemarken. Druiderne søgte ly øst for den vej, men de vil ikke være til megen hjælp for dig: de blev dræbt for nylig... det er noget, jeg ikke bryder mig om at tænke på.\n\nNår du finder den sidste del, skal du bringe den til mig, så hjælper jeg dig med at genopbygge staven."},
  [1028] = {n="Raenes Rensning", l="Find den skjulte helligdom og genforgyld Dartels Stav.", d="Her er den færdige stav, <Name>. Genopbygningen var simpel... det er at finde helligdommen, der har kraften til at genoplade den, som bliver den svære del.\n\nMed lidt koncentration og indsats burde det ikke være for svært for en som dig, der allerede har udrettet så meget.\n\nTag mod sydøst herfra--der er meget få stier, så vær forsigtig--og hold øje mod nord. Helligdommen er gemt inde i bjergene, der omgiver denne lysning.\n\nNår du er der, placerer du staven i helligdommen... resten er magi. Hehe."},
  [1029] = {n="Raenes Rensning", l="Vend tilbage til Raene Ulvefører i Stjernelund.", d="Jeg foreslår, at du finder Raene og fortæller hende, at staven er færdig. Jeg er sikker på, at hun ved, hvad din næste opgave bør være.\n\nHeld og lykke, <Name>."},
  [1030] = {n="Raenes Rensning", l="Find en ukorrumperet pelsbolg, og tal til ham ved hjælp af kraften fra Dartels Forvandlingsstav.", d="Desværre er jeg ikke helt sikker på, hvad han havde i sinde næste gang.\n\nHvis det, han sagde om stavens kraft, er sandt, vil den give dig mulighed for at antage en helt anden form. Hvilken form, ved jeg ikke.\n\nMåske mente han at bruge dens kræfter til at komme tættere på de besmittede pelsbolge, men selv de ukorrumperede væsener ville slagte ham, hvis han ikke var forsigtig. Forvandlet af staven ville Dartel skulle tale til en pelsbolg, der var sikret mod virkningerne af Ondmos.\n\nJeg ville begynde din søgning sydøst for Mystral-søen."},
  [1032] = {n="Jagt på Skovbukke!", l="Bring 16 Skovbuk-horn til Illiyana i Aesinas Helligdom.", d="Jeg kan ikke tro, at Anelia er væk... Vi legede sammen i skovene hele tiden. Jeg føler næsten... trist.\n\nJeg ved noget, der måske kan få mig til at føle mig bedre. Vær venlig at slå de skovbukke ihjel, der tog Anelia fra mig! Bring mig deres horn som bevis på din indsats, så vil du for evigt have min taknemmelighed."},
  [1033] = {n="Elunes Tåre", l="Bring Elunes Tåre til Pelturas Hvidmåne i Stjernelund.", d="Jeg havde håbet, at Orendils kur ville redde Relaria, men jeg frygter, at den kun bremsede sygdommen, der løber gennem mit barn. Vi må finde kraftigere medicin! Heldigvis fortalte Orendil mig om yderligere midler, som jeg kan prøve, hvis hans første ikke virker.\n\nElunes Tåre er en slags sten, der kun findes ét sted: på øen i Iris-søen, øst for Stjernelund. Orendil sagde, at stenen vil skylle korruptionen væk... venligst, <Name>, bring mig Elunes Tåre, og lad os bede om, at den gør ende på mit barns sygdom!"},
  [1034] = {n="Stjernestøvs Ruiner", l="Før 5 Håndfulde Stjernestøv til Pelturas Hvidmåne i Stjernelund.", d="Elunes Tåre vaskede noget af min datters sygdom væk. Hendes mareridt er blevet mindre, og jeg takker gudinden for hendes velsignelse. Men ... feberen raser stadig i hende.\n\nOrendil fortalte mig om et frostet støv, der findes blandt Stjernestøvs Ruiner. Måske kan det dæmpe Relarias feber. Saml noget af støvet, og kom så tilbage til mig, tak.\n\nStjernestøvs Ruiner ligger mod syd, <Name>. Må Elune fremskynde din rejse."},
  [1035] = {n="Faldne Himmelsø", l="Hent et Faldet Månesten fra Skyggekrat-orakelet, og før det så til Pelturas Hvidmåne i Stjernelund.", d="Relarias feber er overstået, men hun er stadig meget svag. Jeg tror ikke, at tiden alene vil give hende den styrke tilbage, hun har mistet. Jeg tror, det vil kræve kraften fra et månesten.\n\nVi plejede at samle månesten ved Faldne Himmelsø mod sydøst ... indtil Skyggekrattene kom.\n\nDeres leder, et Skyggekrat-orakel, samlede alle de faldne månesten og hamstrer dem. Nu skal du hente et månesten fra orakelet.\n\nOg for at gøre det frygter jeg, at du må slå ham ihjel."},
  [1038] = {n="Velindes Ejendele", l="Søg i Velindes kiste efter hendes dagbog, og returner den sammen med nøglen til Thyn'tel Klingevæver i Darnassos.", d="Mel'Thandris' tome viste dig dette? Jeg formoder, at det ikke gør nogen skade at lade dig se hendes ejendele. Denne nøgle åbner kisten, hvor vi opbevarede hendes ting i Vagternes sovesal. Hun førte dagbog over sine pligter; hvis der er noget at lære, står det der.\n\nJeg bør sige dig, at Vagterne mener, hun havde sine egne grunde til at forlade os, og forventer, at hun kan vende tilbage når som helst. Præstinden har gjort meget i fortiden for at fortjene vores tillid."},
  [1045] = {n="Raenes Udrensning", l="Dræb 4 Blodtand-vagter og hent Ran Blodtands kranie til Krolg nær Mystral-søen.", d="Nattealferne er gamle som tiden, men deres arrogance ødelægger deres egen verden. Og nu ødelægger den også vores liv. Men det kan ikke længere kontrolleres ...\n\nJeg giver alferne skylden for meget, men vi er stadig ansvarlige for vores handlinger. Selv ud over korruptionen er vi i stand til stor ondskab.\n\nRan Blodtand er et sådant ondt væsen. Magtsyg, begærlig ... korruptionen har kun gjort ham stærkere. Mit had til alferne brænder, men jeg ønsker ikke onde ting for deres børn, så vi må holde styr på vores egne."},
  [1049] = {n="De Faldnes Kompendium", l="Hent De Faldnes Kompendium fra klosteret i Tirisfals Lysninger, og returner det til Vismand Sandhedssøger i Tordenklippe.", d="Jordringen havde rene intentioner over for vores plagede brødre. Men hvem kender motiverne hos dem, der hvisker i Ældrerådets ører?\n\nDe Forladte, som vi er alliancerede med, har en historie fuld af bedrag. Vores pagt var for forhastet. Måske ville Kærne have været klog nok til at lytte til advarslerne fra Orgrimgrad.\n\nDybt inde i Det Skarlagenrøde Kloster ligger De Faldnes Kompendium, bevogtet af skøre menneskelige fanatikere. Deres metode er smedet af vanvid, men deres forskning kan vise sig nyttig."},
  [1050] = {n="Titanernes Mytologi", l="Hent Titanernes Mytologi fra klosteret, og før den til Bibliotekar Mae Blegstøv i Jernsmede.", d="Fremtiden er uundgåelig! Vi kaster os mod den, som regndråber mod Det Store Hav.\n\nMen måske kan vi, ved at studere fortiden, vide, hvad vi kan forvente, og være bedre forberedt på det ukendte.\n\nFør frygtelige problemer faldt over Herrelande, var der et vidensbolværk gemt væk i Tirisfals Lysninger. Det rygtes, at en bog ved navn Titanernes Mytologi lå i det gamle klosters bibliotek.\n\nBring den til mig, så kan vi måske sammen låse op for fortidens hemmeligheder!"},
  [1051] = {n="Vorrels Hævn", l="Returner Vorrel Sengudsens vielsesring til Monika Sengudsen i Tarrenmølle.", d="Selvom min vilje er fri, kan jeg ikke tjene Den Mørke Dame længere. Jeg føler, at min tid på Azeroth er nået til ende. Min livskraft er knust.\n\nForhørsleder Vishas gjorde dette ved mig! Torturerede mig i ugevis! Tog min vielsesring og gav den til sin kone. Den rådne skiderik!\n\nHævn ... jeg vil have hævn!\n\nDen indbildske tåbe pralede med sin dyrebare kone, Nanna, som boede ved Lordamere-søen. Spor tøsen op, dræb hende, og returner min vielsesring til min kone, Monika i Tarrenmølle.\n\nRet dig efter mine sidste ønsker ...."},
  [1054] = {n="Udryddelse af Truslen", l="Bring Dal Blodklos kranie til Raene Ulvefører i Stjernelund.", d="Direkte nord for Stjernelund ligger Tistelpels-pelsbolgerne. Mine spejdere melder, at deres antal er vokset meget de sidste par måneder. Hvis de bliver for mange, kan de få modet til at angribe Stjernelund direkte.\n\nDræb så mange af deres slags, du kan, men bring mig deres høvdings kranie som bevis på, at deres indsats er kvalt ... for nu.\n\nJeg bliver her i Stjernelund og venter på nyt fra dig. Elune være med dig."},
  [1055] = {n="Raenes Udrensning", l="Vend tilbage til Shael'drøn ved månebrønden.", d="Stangen, nu fuldført, ligger i dine hænder. Shael'drøn vil gerne høre om din succes."},
  [1056] = {n="Rejsen til Stenklippe-toppen", l="Rejs til Vogter Albagorm på Stenklippe-toppen.", d="Skovånderne fortæller mig, at du er modig og villig til at rejse.\n\nMod syd, ikke langt fra Mystral-søen, ligger en tunnel ved navn Klodsdybe-stien. Gennem denne tunnel kommer du til et område kendt som Vindskær-klippen i Stenklippe-bjergene. Når du er der, rejs mod sydvest forbi Klippepøl-søen og derefter nordpå, op ad den stejle skråning, indtil du når Stenklippe-toppen.\n\nDer venter Vogter Albagorm. Lyt til hans befalinger, <Race>.\n\nRejsen bliver farlig."},
  [1057] = {n="Generobringen af den Brændte Dal", l="Vogter Albagorm på Stenklippe-toppen vil have dig til at dræbe 6 Blodraser-harpyjer, 6 Blodraser-bagholdere, 6 Blodraser-dræbere og 6 Blodraser-snigfjer.", d="Som beskytter af skovånderne kan du uden tvivl gætte, hvorfor jeg er alarmeret.\n\nDu har rejst gennem disse bjerge for at nå denne top. Du har sikkert set den ulykke, der er overgået landet. Grådighed har ført til ødelæggelsen af disse hellige bakker.\n\nDen Brændte Dal mod syd blev sat i brand af den grådige, mekaniserede hær af industrifolk. Værre endnu: Blodraserne, der har invaderet landet, nægter os passage, så genvæksten kan begynde.\n\nDriv de ynkelige harpyjer ud, <Name>!"},
  [1058] = {n="Jin'Zils Skovmagi", l="Heksedoktor Jin'Zil i Malaka'jin vil have 5 portioner Stenklippe-harpiks, 5 Tusmørke-knurhår, 30 Løber-øjne og en Fe-drage-skæl.", d="Så begejstret jeg er!\n\nTre små bure til tre små alfer! Men hvad skal vi gøre med vores dejlige træ-kramme-venner? Lad os give dem en smag af ... hvad kalder de det nu ... skovmagi!\n\nJeg skal bruge en god mængde Stenklippe-harpiks. Fra de forfærdelige katte vil jeg have noget tusmørke-knurhår. Der skal masser af løber-øjne til, selvfølgelig -- man kan aldrig have nok øjne. Åh, og for ikke at glemme det: en dyrebar skæl fra en fe-drage.\n\nSkynd dig til Stenklippe-toppen, <Name>, så jeg kan brygge noget skovmagi!"},
  [1059] = {n="Generobringen af den Brændte Dal", l="Rejs til Falfindel Vejvildfarer på grænsen mellem Tusindnåle og Feralas.", d="Blodraserne er blevet tæmmet. Men de vil samle sig igen snart nok, hvis der ikke handles.\n\nLangt syd for Ødemarken ligger et land kendt som Tusindnåle. Hvis du rejser vestpå i Tusindnåle, indtil du når den frodige skovs kant i Feralas, vil du finde en druide ved navn Falfindel Vejvildfarer.\n\nDenne store og kloge druide kan kalde store skovånder frem, som kan hjælpe med generobringen af den Brændte Dal.\n\nBring budskab om vores behov! Opsøg ham med det samme!"},
  [1060] = {n="Brev til Jin'Zil", l="Lever Darsoks brev til Jin'Zil i hans hule i Malaka'jin, i Stenklippe.", d="Du har gjort det så godt for mig, <Name>. Du er en almindelig heldig kaninpote, og der er noget, jeg vil have dig til at se.\n\nHarpyjerne er ikke fra området omkring Ødemarken. De kommer fra et sted kaldet Stenklippe, langt mod nordvest herfra. Selvom det sikkert er et farligt sted for dig, skal dette brev leveres til en gammel ven af mig, som bor der, en heksedoktor ved navn Jin'Zil.\n\nHan vil blive glad for at høre, at Serena Blodfjer er død, og jeg tror, du vil finde Stenklippe en interessant plads."},
  [1061] = {n="Stenklippe-bjergenes Ånder", l="Tal med Seereth Stenbrud i Stenklippe-bjergene.", d="Ånderne i Stenklippe-bjergene er vrede, for nisser og deres tjenere plyndrer og brænder landet. Så landet har råbt om hjælp, og de, der lytter efter sådanne ting ... har hørt det.\n\nSeereth Stenbrud, en lovende shaman fra Horden, blev sendt til Stenklippe. Hun melder om massiv skovrydning begået af nisserne og beder om hjælp.\n\nMød Seereth i Stenklippe. For at nå hende skal du følge vejen vest for Korsvejen i Ødemarken. Hun har slået lejr nær Storskov-dalen."},
  [1062] = {n="Nisse-invasionen", l="Dræb 15 Ventureselskab-skovhuggere, og vend derefter tilbage til Seereth Stenbrud på grænsen mellem Stenklippe og Ødemarken.", d="Det nisse-drevne Ventureselskab rykkede ind i Stenklippe-bjergene, fælder træer og brænder enorme strækninger af skov. Stedets ånder er næsten blinde af smerte og raseri. Vi må stoppe Ventureselskabet!\n\nGå mod nordvest, forbi Storskov-dalen og ind i Vindskær-klippen. Der finder du nisserne og deres tjenere i gang med arbejdet -- vis dem, at Horden ikke vil tillade udnyttelsen af Stenklippe. Vis dem på det sprog, de bedst forstår ...\n\nVold."},
  [1063] = {n="Den Ældre Heks", l="Tal med Magatha i Tordenklippe.", d="For virkelig at tage sig af Stenklippes ånder, må vi rådføre os med taurernes ældste.\n\nJeg kender ikke mange af deres lederes navne, men jeg kender ét: Magatha. Jeg har hørt, at hun er meget gammel, og at hun ved meget. Hvis nogen kan mobilisere åndelig hjælp fra taurerne, er det hende.\n\nMagatha bor i taurernes hovedstad Tordenklippe, på Ældrehøjen -- byens nordøstlige klippe. Tal med Magatha, og fortæl hende om faren for Stenklippe-bjergene."},
  [1064] = {n="De Forladtes Hjælp", l="Tal med Apoteker Zamah i Synets Pøle i Tordenklippe.", d="Taurerne har et bånd til landet, og det smerter mig at høre om Stenklippes elendighed. Men jeg frygter, at vi for at helbrede landet først må fjerne sygdommen fra det.\n\nEr det ikke heldigt, at De Forladte er alliancerede med os? De kender meget til sygdomme. Jeg tror, de kan hjælpe os, og ved at gøre det vil de styrke tilliden mellem vores folk.\n\nTal med Apoteker Zamah. Hun er lærd og udsending for De Forladte. Du finder hende i Synets Pøle under Åndsopstigningen."},
  [1065] = {n="Rejsen til Tarrenmølle", l="Bring Zamahs Notat til Apoteker Lydon i Tarrenmølle.", d="For at rydde Stenklippe for Ventureselskabet må vi tage ekstreme midler i brug. Ekstreme, men uden blodsudgydelse.\n\nEn kollega af mig har måske lige det værktøj, vi har brug for. Han hedder Lydon; han bor i byen Tarrenmølle i Hillsbrad-forbjergene, i det fjerne land Herrelande.\n\nFor at nå Hillsbrad skal du rejse med zeppelin til vores hovedstad, Undergrunden. Derefter nordpå til Tirisfals Lysninger, sydvest til Sølvfyrreskoven og syd til Hillsbrad.\n\nSøg Lydon, og bring ham dette notat. Det beskriver vores behov over for ham."},
  [1066] = {n="Uskyldiges Blod", l="Bring 5 Hætteglas med uskyldigt blod til Apoteker Lydon i Tarrenmølle.", d="Jeg vil lave et gift, der tapper volden ud af Ventureselskabet, så de bliver svage og sløve. Det burde løse Hordens problem i Stenklippe, ikke?\n\nMen for at lave giften skal jeg bruge uskyldigt blod, en vanskelig ingrediens at skaffe.\n\nHeldigvis bruger Syndikatet, en gruppe menneskelige banditter i området, skyggemagikere ... og de magikere samler uskyldigt blod til deres egne, usmagelige formål.\n\nDu kan finde Syndikatets skyggemagikere i Durnholde-fæstningen mod sydøst."},
  [1067] = {n="Tilbage til Tordenklippe", l="Bring Lydons Gift til Apoteker Zamah i Tordenklippe.", d="Her er giften. Hvis du bruger den mod Ventureselskabet, bør det give gunstige, måske endda smittsomme resultater. Jeg må sige, det er ret spændende at se mit arbejde blive brugt i marken!\n\nMen før du bruger den, skal du tage den med til Apoteker Zamah. Hun skal lave en leveringsmetode til giften, så dens effekt bliver maksimal."},
  [1068] = {n="Makulatormaskinerne", l="Dræb makulatorerne XT:4 og XT:9, og vend derefter tilbage til Seereth Stenbrud på grænsen mellem Stenklippe-bjergene og Ødemarken.", d="Der er en forbindelse mellem shamanernes åndelige magi og druidernes naturmagi. Det er derfor, vi shamaner kan høre Stenklippes ånders bønner. Mange af deres hviskerier er gået tabt for mig, men ét budskab, ét syn, er klart ...\n\nJeg så et syn af to menneskeformede maskiner i Vindskær-klippen, nordvest for Storskov-dalen, der fældede træer med umulig hastighed. Disse metalbester må stoppes!\n\nI mit syn var maskinerne mærket med mærkelige symboler:\n\nXT:4 og XT:9."},
  [1069] = {n="Dybmos-edderkoppæg", l="Bring 15 Dybmos-æg til Mebok Snurrefix i Skralleby.", d="Omeletter lavet af edderkoppeæg er en ny trend i Bytteviken! Problemet er ... Bytteviken har ingen æg.\n\nJeg lugter en mulighed!\n\nI Vindskær-klippen og Sishir-kløften, i Stenklippe-bjergene mod nordvest, lever dybmos-edderkoppen. Bring mig dens æg, så betaler jeg en bunke!\n\nI Vindskær-klippen vil æggene ligge samlet under de træer, der stadig står.\n\nI Sishir-kløften ... tja, hvis du har en svag mave, så skal du nok bare samle æggene i Vindskær-klippen ..."},
  [1070] = {n="På Vagt i Stenklippe", l="Find Kaela Skyggespyd, der holder øje med dalen, som fører ind i Vindskær-klippen i Stenklippe-bjergene.", d="Hej, <Name>.\n\nDu virker fuld af vandrelyst, så meget som man kan se. Har du været i Stenklippe-bjergene? Det er et land plaget af Ventureselskabet og andre fjender af nattealferne.\n\nNylig sendte Vagt Ulvefører min ven Kaela Skyggespyd derhen for at undersøge, hvad der sker med landet, men jeg har endnu ikke hørt noget fra hende. Jeg er endnu mere bekymret, fordi Alliancen sendte en gnom-magiker med hende ... et tegn på problemer, helt sikkert.\n\nVil du finde hende og rapportere tilbage til mig?"},
  [1071] = {n="En Gnoms Pusterum", l="Dræb 10 Ventureselskab-skovhuggere og 10 Ventureselskab-skovrydder, og vend tilbage til Gaxim Rustsprut i Stenklippe.", d="Se, <Name>, jeg er medlem af Den Oplyste Forsamling for Arkanologi, Alkymi og Ingeniørvidenskab, og det er mit mål ... nej, min PLIGT! at vise nattealferne, at en blanding af magi, miksturer og mekanismer kan hjælpe med at redde deres skove.\n\nMen det er en hårdt kæmpet krig, og nisserne formerer sig tilsyneladende som kaniner. Jeg har ikke engang haft tid til at bygge mine nyeste opfindelser!\n\nJeg har brug for tid til at planlægge og organisere. Men for at gøre det har jeg brug for din hjælp til at holde nisserne væk i Vindskær-klippen mod øst ..."},
  [1072] = {n="En Gammel Kollega", l="Tal med Lomac Tandstrimmel i Jernsmede.", d="Den maskine, jeg tænker på, er min mest avancerede version til dato. Men vi skal bruge en særlig eliksir, hvis den skal virke. Jeg tænker, at vi lige så godt kan få det gode stads, da denne mission måske er din sidste.\n\nOg til det skal vi bruge nogle kraftige sprængstoffer: Nitromirglyceronium.\n\nDen eneste, der kan lave NG-5, er en gammel ven af mig: Lomac Tandstrimmel. Led efter ham i Tinkerbyen.\n\nFår du ham overtalt til at lave os lidt NG-5, så går jeg i gang med at placere mine maskiner."},
  [1075] = {n="Et Rullebrev fra Mørbrod", l="Find Collin Mørbrod i Stormvind.", d="Okay, nu til fjernudløsningsdelen af min plan... åh, det har jeg ikke forklaret endnu, har jeg?\n\nOkay, kort fortalt: med lidt magi kan jeg få det til, at sprængstofferne eksploderer, mens du ikke er i nærheden. Jeg sætter en maskine sammen, der giver dig mulighed for at trykke på én knap og få NG-5 til at eksplodere, når du er klar.\n\nMen jeg har brug for en besværgelse fra en ven i Stormvind--Collin Mørbrod er hans navn. Du kan finde ham i Stormvinds Magikerkvarter. Han er menneske, så han burde ikke være svær at få øje på."},
  [1078] = {n="Hentning for Mørbrod", l="Bring 8 Krystalliserede Skæl til Collin Mørbrod i Stormvind.", d="Rejsende bliver ved med at spørge mig om Stenklippe-bjergene. Det ser ud til at være et populært sted for eventyr--det er lige meget, om du jagter vyverner, elementarer, eller du har forretninger med Ventureselskabet.\n\nI Den Brændte Dal, dybt inde i Stenklippe, var der engang en art basilisker, hvis skæl, når de blev malet til støv, gav et vidunderligt reagens til nogle besværgelser, jeg har skabt.\n\nHvis de basilisker stadig lever, ville jeg elske at få et par af deres skæl.\n\nTag dig god tid, der er ingen hast, men jeg betaler godt."},
  [1079] = {n="Hemmelige Operationer - Alpha", l="Hent Ventureselskabets Ingeniørplaner fra savværket i Vindskær-klippen.", d="Så er det nu, <Name>. Hold godt øje. Maskinerne er færdige og klar til brug.\n\nTag disse sider--de forklarer mere om detonatorerne og sprængstofferne, og hvor du skal placere dem.\n\nHusk, at din missions succes ikke afhænger af, hvor meget ødelæggelse du forårsager. Plan Alphas succes afhænger af, at du bringer Ventureselskabets ingeniørplaner tilbage fra det indre af savværket syd for Klippepøl-søen."},
  [1085] = {n="På Vagt i Stenklippe", l="Tal med Gaxim.", d="Situationen her i Stenklippe er naturligvis alvorlig, når en nattealf og en gnom arbejder sammen.\n\nVentureselskabet har hærget disse lande, og jeg har brugt det meste af min tid på at sætte en stopper for ødelæggelsen.\n\nDøm ikke Gaxim for tidligt; han forstår, at vi må arbejde sammen.\n\nVil du hjælpe os, så begynd med at tale med Gaxim.\n\nJeg beklager, at jeg endnu ikke kan sende dig tilbage til Tara med gode nyheder. Måske snart."},
  [1086] = {n="Flyvemaskinelufthavnen", l="Bring Giftdamperen til Ventureselskabets luftskibshavn, og vend derefter tilbage til Apoteker Zamah.", d="Giftstoffet er klar. Det eneste, der mangler, er leveringen. Du, <Name>, må foretage den levering.\n\nVentureselskabet må have en måde at sende beskeder og let fragt mellem sit hovedkvarter og sine operationer i Stenklippe. Det er sandsynligvis en lille luftskibshavn -- ikke stor nok til en zeppelin, men måske til en flyvemaskine. Du må undersøge områderne i Stenklippe under Ventureselskabets kontrol og finde denne luftskibshavn, hvis den findes. Finder du den, så placer giftstoffet dér.\n\nPlacer det, og løb."},
  [1087] = {n="Cenarius' Arv", l="Dræb 4 Cenarius' Sønner, 4 Cenarius' Døtre og 4 Cenarion-botanikere for Braelyn Ildhånd nær Solklippe-tilflugtsstedet.", d="Du kan ikke forestille dig, hvor meget had jeg nærer til dette elendige land. Cenarius' slægt og kaldorei-druiderne på toppen bruger deres patetiske kræfter til at kvæle magiens strøm, selv så langt sydpå fra deres patetiske besiddelser... deres elskede skove.\n\nGid jeg kunne vende tilbage til Jaedenar og fryde mig over magiens strøm, men min mester vil ikke lade mig vende tilbage, før mit arbejde er gjort.\n\nJeg tvivler ikke på, at du elsker nattealferne og deres allierede lige så lidt som jeg. Hjælp mig, så kan begge vores mål blive opfyldt."},
  [1088] = {n="Ordanus", l="Bring Ordanus' hoved til Braelyn Ildhånd nær Solklippe-tilflugtsstedet.", d="De troede, at de kunne standse magiens strøm. De tog fejl. De troede, at de kunne skjule Ordanus, men jeg vil have hans hoved!\n\nMagien giver mig sand syn. Ja... dér er han. Et vejkryds... På toppen af et stort træ i Askedalen. Et navn... Raynewood. En af skovgudens ældste sønner. De førte ham væk fra toppen, før jeg kunne finde ham, men hans tid er knap.\n\nBring det til mig, så deler jeg en mægtig gave med dig."},
  [1089] = {n="Hulen", l="Rejs til Hulen på Stenklippe-toppen. Brug Portvagtens Nøgle til at få druidernes skjulte genstande. Brug disse genstande til at åbne Klohulens Skatkammer.", d="Druiderne byggede Klohulen på Stenklippe-toppen, hvor de opbevarer mange kraftfulde genstande.\n\nDe udtænkte en kompleks plan for at forhindre, at de faldt i de forkerte hænder.\n\nHeldigvis lykkedes det mig at... udtrække nogle detaljer fra en af dem.\n\nGemt i en lille lanterne ved indgangen til Hulen finder du Portvagtens Nøgle -- med den kan du åbne skjulesteder rundt om Hulen. Genstandene fra disse skjulesteder vil give dig adgang til deres skatkammer, placeret i et af de centrale områder."},
  [1090] = {n="Gerenzos Ordrer", l="Få den mystiske malm fra Snudrik, når han er færdig med at udgrave den.", d="Du ved, jeg var engang den næstvigtigste person her på stedet. Det ændrede sig, da Gerenzo overtog. Fyrede min chef, Ziz Sprydhjul, og sendte mig ned for at arbejde i minerne. Ziz bad mig dog blive her og indsamle oplysninger. Hans nye chef vil betale os godt, hvis vi kan finde ud af, hvad Gerenzos planer er.\n\nUnder alle omstændigheder ved jeg, at Gerenzo har beordret store mængder af denne guldgrønne malm udgravet. Jeg kan skaffe dig en prøve at tage med til Ziz, men du må holde øje med patruljerne, mens jeg henter den."},
  [1093] = {n="Superhøster 6000", l="Hent Superhøster 6000-tegningerne til Ziz Sprydhjul i Stenklippe-bjergene.", d="Forfærdeligt, hvad Ventureselskabet har gjort her, hva'? Hvad tænkte de på? Et goblin-firma, der ansætter en gnom!\n\nHeldigvis for mig ved Sprutventil, at han genkender et geni, når han ser et. Ansatte mig lige efter, at jeg var blevet smidt ud!\n\nHan fortæller mig, at de har bygget en enorm træfældningsmaskine, og Sprut' vil have mig til at stjæle tegningerne til ham. Desværre vil Gerenzo--forbandet gnom--have mig dræbt på stedet... måske kunne du stjæle tegningerne for mig? Du burde kunne finde dem hos en af deres operatører."},
  [1094] = {n="Yderligere Instruktioner", l="Lever den forseglede konvolut til Sprutventil i Ødemarken.", d="Denne konvolut indeholder al den information, jeg kunne snuppe, da de smed mig ud ad døren... Ventureselskabets interne dokumenter, nogle manualer, tekniske ting... Og selvfølgelig Superhøster 6000-tegningerne.\n\nSprutventil har slået sig ned hos Skralleby i Ødemarken. Du burde ikke have det store problem med at finde ham, han er en lille grøn fyr."},
  [1095] = {n="Yderligere Instruktioner", l="Bring de nye ordrer til Ziz Sprydhjul i Stenklippe-bjergene.", d="Sagen om denne gnom, som Ventureselskabet har ansat, har skabt en del røre i Underminen. Handelsprinserne godkender ikke, at Razdunk omgås denne Gerenzo.\n\nRiddlevox har bedt mig tage mig af problemet, og jeg er sikker på, at han er blevet instrueret i det af en eller flere af handelsprinserne. Naturligvis fortalte direktøren mig ikke det. Lad os bare sige, at jeg har en fornemmelse.\n\nUanset sagen må Gerenzo fjernes, og det ville være en passende prøve at lade Sprydhjul tage sig af ham."},
  [1096] = {n="Gerenzo Skruefløjte", l="Bring Gerenzo Skruefløjtes mekaniske arm til Ziz Sprydhjul i Stenklippe-bjergene.", d="Jeg mødte Gerenzo én gang, men lad mig fortælle dig, han er ikke pæn at se på. Hans kød ser ud, som om det rådner væk, og han har podet metal og tandhjul på sin krop og erstattet nogle af sine lemmer med mekaniske.\n\nNordøst herfra, langt oppe over Klippepøl-søen, ved vandhjulet, er der, hvor Gerenzo holder øje med hele stedet. Der er ingen måde, jeg kunne kæmpe mig op dér, for slet ikke at tale om at tage Gerenzo... Men du ser ud, som om du måske kan klare det.\n\nHvis du dræber ham for mig, så skal jeg nok gøre det umagen værd!"},
  [1097] = {n="Elmores Opgave", l="Tal med Grimand Elmøre.", d="Der er en dværgisk våbensmed i Stormvind, Grimand Elmøre, som har sendt bud om, at han har brug for hjælp til en levering. Jeg tror, han ønsker en pakke sendt til sit hjemland i nord.\n\nDu har et solidt par ben! Så hvis du er interesseret i noget benarbejde, så tal med Grimand. Vi kunne bruge dig her nede, men vi må også holde vores bånd til dværgene stærke.\n\nDu finder Grimand Elmøre i våbenbutikken i Dværgekvarteret i Stormvind, i den nordøstlige del af byen."},
  [1098] = {n="Dødsstalkere i Skyggetand", l="Find Dødsstalker Adamant og Dødsstalker Vincent.", d="Som forberedelse til et angreb på Skyggetand blev to dødsstalkere sendt til fæstningen for at indsamle efterretninger. Der er gået mange dage, og de er ikke vendt tilbage, men vi må modtage deres rapport, hvis vi skal have bare et håb om et vellykket angreb!\n\nSå her er din opgave, <Name>. Gå mod syd til Skyggetandsborgen og find Dødsstalkerne Adamant og Vincent. Find dem, og hvis de har brug for hjælp, så giv den.\n\nDenne mission er lige så farlig, som den er afgørende, <Name>. Svigt ikke."},
  [1101] = {n="Tornekrattets Heks", l="Bring Rasorflankes Medaljon til Falfindel Vejvildfarer i Thalanaar.", d="Stakkels Heralåth! Og denne dværg... Ensbryn. Hvilken modig sjæl han var.\n\nVi må ikke lade deres tapperhed gå til spilde. Denne heks... Charlga Rasorflanke ... må stoppes.\n\nDet er sikkert, at det vil være farligt at infiltrere Tornekrattet. Der er ikke tid til at sende bud til Darnassos. <Name>, saml en gruppe til at slå hekset ihjel.\n\nBring mig Rasorflankes Medaljon som bevis på hendes død."},
  [1102] = {n="En Hævnende Skæbne", l="Bring Rasorflankes Hjerte til Gamle Stenspir i Tordenklippe.", d="Kærne er en ædel leder for at samle vores folk her på Tordenklippe.\n\nMen jeg kan ikke tilgive dem, der drev os fra vores forfædres lande, så let som nogle andre. Mit folk boede i det sydlige Ødemark i årtier. Landet var helligt for os. Men vi blev fordrevet af talrige fjender.\n\nEn hævnende skæbne venter heksen Charlga Rasorflanke, som samler en snavset hær inde i Tornekrattet.\n\nBring mig Rasorflankes hjerte, så kan jeg dø i fred, <Name>."},
  [1103] = {n="Vandets Kald", l="Bring en Vandsapta til Tiev Mørdune i Sølvfyrreskoven, hvis du ikke fik talt med den Mindre Vandmanifestation.", d="Hilsen, broder/søster! Er du også kommet for at rense vandene her og bevise din forståelse over for Islen?\n\nJeg har lige besejret den korrumperede vandånd selv, og jeg er lige ved at lægge armbåndene og de resterende vanddråber på braseren.\n\nHvad siger du? Ahhh. Tiev forstår alt for godt, når noget går galt. Tja, Tiev kan hjælpe dig meget, hvis du har brug for at se den rene vandånd igen.\n\nBring mig en vandsapta fra Islen som bevis på, at du er klar, så venter jeg med at aflevere mine dele."},
  [1104] = {n="Saltflade-gift", l="Bring 6 Saltede Skorpid-gifte til Fizzle Messingbolt i Glimmerflatene.", d="Jeg har så mange designs til vores raketbil! Så mange! Og jeg må prøve dem alle!!\n\nJeg arbejder på en ny type brændstof. Et, der brænder rigtig, rigtig, rigtig varmt!! Jeg har ikke fået blandingen helt rigtig, men jeg tror, jeg ved, hvad jeg mangler...\n\nSkorpiderne, der vandrer rundt på Glimmerflatene, har et gift med masser og masser af salt i sig. Det er helt unikt! Og det er præcis, hvad jeg har brug for!\n\nBring mig giften, og stol på mig -- vores bil vil flyve!!"},
  [1105] = {n="Hærdede Skaller", l="Bring 9 Hærdede Skildpaddeskaller til Wizzle Messingbolt i Glimmerflatene.", d="Min bror arbejder på et nyt brændstof til sin raketbil. Han er genial, det er han virkelig. Så genial at... jeg tror, at det nye brændstof, han designer, er stærkt nok til at æde sig lige igennem bilens chassis!\n\nJeg vil forstærke dens brændstoftanke, før det sker.\n\nSkildpadderne ude på flagerne har meget hårde skaller. Jeg vil bruge dem til at lave nye tanke til vores raketbil. Tanke, der kan rumme min brors nye brændstof.\n\nDu virker ansvarlig nok. Vil du skaffe mig de skaller?"},
  [1106] = {n="Martek den Forviste", l="Bring Fizzle Messingbolts brev til Martek den Forviste i Ødelandene.", d="Jeg udvikler en ny motor, der får bilen til at køre så hurtigt! Hurtigt nok til at flyve, det ved jeg! Jeg mangler bare at lave stempler, der kan klare meget, meget tung belastning. Alle mine forsøg er mislykkedes, fordi jeg ikke kan lave stempler hårde nok!\n\nMen der er nogen, der måske ved hvordan.\n\nHan hedder Martek den Forviste. Han er en stor smed og ved mere om metal end nogen anden. Tag dette brev med til ham, jeg ved, at han kan hjælpe!\n\nMen han er langt, langt væk -- i Azeroth, i Ødelandene, i en lejr, sammen med en goblin!\n\nFind ham!"},
  [1107] = {n="Krustede Halefinner", l="Bring 10 Krustede Halefinner til Wizzle Messingbolt i Glimmerflatene.", d="Vores raketbil er det hurtigste på flagerne! Så hurtig at ... jeg er bange for, at friktionen vil rive den i stykker!\n\nFor at forhindre det må jeg lave en kompositmasse til at dække bilens bevægelige dele. Den skal være hård, men ikke skør, og den skal være modstandsdygtig over for saltkorrosion, ellers vil tiden på Glimmerflatene æde den op.\n\nHar du hørt om Det Onde Rev, <Name>? Det ligger ud for Kvælerdorn. Saltskæl-mudderfisk lever der, og deres halefinner er en afgørende ingrediens i min komposit."},
  [1108] = {n="Indurium", l="Bring 10 Indurium-flager til Martek den Forviste i Ødelandene.", d="Jeg er ikke herude bare for at holde mig væk fra folk. Der er en rigdom af metal i Ødelandene, <Name>, hvis du har mod til at hente det.\n\nMetallet hedder indurium, og heldigvis siges det at have høj modstandsdygtighed over for varme og belastning. Det kunne måske virke til Fizzles bil.\n\nMen lad os være sikre. Skaf mig prøver af indurium, så tester jeg dets egenskaber.\n\nÆgte indurium-malm ligger dybt i Uldhulen, men Stenkælder-trogg'erne i Ødelandene har nogle gange flager af det på sig. Bring mig de flager."},
  [1109] = {n="Gå, Gå, Guano!", l="Bring 1 bunke Tornekrat-guano til Mesterapoteker Faranell i Undergrunden.", d="Som du kan se, <Name>, er vi i gang med nogle meget... interessante eksperimenter i Det Kongelige Apotekerselskab.\n\nSom mester her er det min opgave at overvåge de mest ambitiøse af vores alkymiske forsøg. Så meget arbejde og så lidt tid!\n\nDu ser meget rejst ud for en <Class>. Måske kan du hjælpe mig.\n\nJeg har brug for et sjældent stof. Det er ækelt materiale; det kommer fra en sjælden art flagermus, der kun findes i møggruben kendt som Tornekrattet. Bring mig guanoen fra Tornekrat-flagermusene, så vi kan begynde vores arbejde..."},
  [1110] = {n="Raketbil-dele", l="Bring 30 Raketbil-dele til Kravel Koalskæg i Glimmerflatene.", d="Hi hi, med alle de løb de kører her, er det ingen overraskelse at der sker et par uheld undervejs. Hvis du kigger rundt i Glimmerflatene, vil du se beviser på tidligere styrt -- skrot af raketbil-dele ligger strøet overalt!\n\nOg de dele er pengene værd for gnomerne og kobolderne. De leder altid efter flere sjove konstruktioner at smække på deres biler.\n\nSå tag ud og skaf mig dele. Bring mig en bunke, så betaler jeg godt."},
  [1111] = {n="Havnemester Svimlig", l="Bring Kravels Delebestilling til Havnemester Svimlig i Skralleby.", d="Jeg gør det til mit job at skaffe folk det de har brug for, og gnomerne derovre trænger til at få udfyldt en delebestilling. Delene blev sendt til Skralleby for en uge siden, men jeg har ikke kunnet tage turen.\n\nSå, er du klar til lidt benarbejde? Tag til Skralleby og giv denne delebestilling til Havnemester Svimlig -- han står sikkert nede ved havnen.\n\nGør det for mig, så får jeg flere opgaver til dig.\n\nOpgaver, min ven, med seriøst profitpotentiale..."},
  [1112] = {n="Dele til Kravel", l="Bring Kravels Dele til Kravel Koalskæg i Glimmerflatene.", d="Her er Kravels pakke, <Name>. Og når du leverer den, så sig til ham... hvis han vil have flere specialbestillinger, så må han betale sin regning!"},
  [1113] = {n="Nidkærhedens Hjerter", l="Mesterapoteker Faranell i Undergrunden vil have 20 Nidkærhedens Hjerter.", d="Hvorfor jeg har brug for en sjælden slags guano, spørger du måske. Jo, til dette eksperiment vil jeg se hvilken effekt to diametralt modsatte kemiske stoffer kan have på hinanden, især når begge blandes med et altid giftigt middel for at sikre de mest... rædselsfulde resultater.\n\nI de nordøstlige toppe af Tirisfals Lysninger ligger Det Skarlagenrøde Kloster. Der samles de gale disciple fra Det Skarlagenrøde Korstog. Slå dem ihjel og bring mig deres nidkære hjerter.\n\nVores lille hekseblanding bliver yderst ondskabsfuld!"},
  [1116] = {n="Drømmestøv i Sumpen", l="Bring 10 Drømmestøvskorn til Krazek i Bytteviken. Drømmestøv indsamles fra drageungerne i Sorgens Sump.", d="At få information om Nazz er en stor tjeneste, <Name>. Ja, en stor tjeneste. Men du er kommet hele vejen fra Glimmerflatene for at få den... er du villig til at rejse lidt mere?\n\nMens jeg kontakter mine kilder, hvorfor samler du så ikke lidt for mig, hva'?\n\nHm... hvad skal det være? Hvad med drømmestøv, fra drageungerne i Sorgens Sump. Ja, jeg vil elske lidt drømmestøv til min snusdåse!\n\nHent det til mig, <Name>, så giver jeg dig de oplysninger du søger."},
  [1130] = {n="Melor sender bud", l="Tal med Melor Stenhov i Tordenklippe.", d="<Name>, Melor Stenhov har hørt om dine bedrifter, og har lagt en vej frem for dig.\n\nHvis du vil gå den, så tag til Tordenklippe og tal med Melor. Du finder ham på Jægerens Bakke."},
  [1131] = {n="Stålbid", l="Bring Stålbids Ribben til Melor Stenhov i Tordenklippe.", d="Nogle gange jager vi for mad. Nogle gange jager vi for ære. Og nogle gange jager vi for at fortjene Jordmoderens lærdomme.\n\nMen jagten, jeg nu sætter dig på, er ingen af disse ting. Den går ud på at dræbe et væsen uden for Jordmoderens velsignelse.\n\nHyænen Stålbid strejfer rundt i Tusindnåle, syd for Ødemarken. Han er en tyran, der lokker andre hyæner til sig og sår frygt og blodsudgydelse blandt de fredeligere dyr.\n\nFind Stålbid, <Name>. Find ham, og besejr ham."},
  [1132] = {n="Fiora Langøre", l="Tal med Fiora Langøre i Theramøre.", d="Åh, at være på havet igen! At mærke vindens kys, og at lade bølgerne vugge mig som min velsignede mor, for længe siden!\n\nÅh, jeg ønsker, jeg havde din lykke, gode <Class>, for jeg ser havet i din fremtid!\n\nDet er mit job at fortælle ivrige sjæle om landet Kalimdør, opportunitetens land! Hvis du er villig til at prøve lykken over havet, så tag et skib herfra til den dejlige havneby Theramøre. Tal der med min partner, alven Fiora Langøre.\n\nHun vil sætte dig i gang med dit Kalimdør-eventyr!"},
  [1133] = {n="Rejsen til Stjernelund", l="Tal med Shindrell Hurtigild i Stjernelund.", d="Hvis du lige er kommet i land fra Menetil, så er det første du skal gøre at... tage til Stjernelund. Jeg er sikker på at et ivrigt Alliance-medlem som dig kan gøre rigtig gavn der. Tal med Shindrell Hurtigild og tilbyd dine tjenester.\n\nMen gider ikke nævne hvem der sendte dig. Shindrell kender ikke til mig..."},
  [1134] = {n="Stolthedsvinger fra Stenklippe", l="Bring 12 Stolthedsvinge-giftsække til Shindrell Hurtigild i Stjernelund.", d="Vi er ikke i åben krig med Horden, men vores fred er skrøbelig. Vi støder ofte på deres agenter, der bevæger sig imod os, men de gør det i det skjulte.\n\nEt sådant fremstød blev afsløret for os af skjulte kilder i Theramøre, som påstod at orkerne samler gift fra stolthedsvingerne nær Mirkfallon-søen, i Stenklippe-bjergene mod syd. Ork-snigmordere bruger så giften på deres hemmelige dødsraids mod Alliancen!\n\nHvis det er sandt, så må vi stoppe dem, <Name>. Vi må nægte dem deres giftkilde."},
  [1135] = {n="Højrede-gift", l="Bring 10 Højrede-giftsække til Fiora Langøre i Theramøre.", d="Som du måske ved, bliver wyverner ofte tæmmet af orker og brugt som ridedyr. Men det er mindre kendt at giften fra en wyvern, i visse kredse, er mere værd end selve dyret. Så hvis du ikke er bange for at tage lidt wyvernjagt, så... har jeg et job til dig.\n\nDer er et sted der hedder Højrede i Tusindnåle-landet, vest herfra. Højrede-wyverne har en potent gift. Potent, og værdifuld."},
  [1136] = {n="Frostgab", l="Bring Frostgabs Manke til Melor Stenhov i Tordenklippe.", d="<Name>, nu er det tid for dig at rejse til fjerne lande. Du er klar.\n\nDu skal nu jage Frostgab, en yeti i Alterac-bjergene. Han er svær at få øje på, hans hvide pels smelter sammen med sneen i sit bjerghjem. Han viser sig sjældent.\n\nMen jeg vil vise dig hvordan man lokker et væsen som ham. Her, tag denne rulle. På den har jeg skrevet hvordan Frostgab kan lokkes.\n\nNu af sted, <Name>. Din rejse er lang, og mange udfordringer venter. Først når du vender tilbage med Frostgabs manke, er din opgave fuldført."},
  [1138] = {n="Havets frugt", l="Saml 6 Fine Krabbestykker til Gubber Blump i Auberdin.", d="Jeg elsker krabber. Krabber er havets frugt! Man kan bage dem, grille dem, koge dem og riste dem. De bliver stegt i pande, friteret og stir-fryet. Der er krabbesalat, krabbesuppe, krabbegryde, peberkrabbe, citronkrabbe, pisketrods-krabbe og Jernsmede-overraskelseskrabbe. Det... det er vist det.\n\nJeg fisker lige nu, så jeg kan ikke få fine krabbestykker. Du kan plukke dem ud af rev-krybere og skorpe-tidevandskryber. Man kan lave meget med dem. Man kan bage dem, grille dem, koge dem..."},
  [1140] = {n="Althalaxx' Tårn", l="Befri de fangede Højfødte-sjæle i Nattebanen og Satyrdalen, og vend derefter tilbage til Delgren Renseren ved Maestras Post.", d="Orkernes skrift er knap bedre end et barns kradsen. Mange i min orden hånede, da jeg valgte at lære deres tunge, men jeg har fundet ud af at det gavner at forstå sine fjender bedre.\n\nAf Ilkruds kradsen fremgår det, at Athrikus stadig besidder to sjælesten, og de holdes i Nattebanen og Satyrdalen, satyr-besatte områder i det nordøstlige Askedalen.\n\nVær forsigtig derude, <Name>, satyrernes blodgennemtrukne templer kan være foruroligende selv for en garvet <Class> som dig."},
  [1141] = {n="Familien og fiskestangen", l="Fang 6 Mørkekyst-havaborrer til Gubber Blump i Auberdin.", d="Jeg elsker at fiske. Blump-familien er kendt for at fiske. Jeg hedder Gubber Blump; jeg fisker.\n\nDer er en slags fisk jeg godt kan lide at fange her omkring, kaldet Mørkekyst-havaborre. Jeg plejede at sejle ud for at fiske havaborrer, men der er ikke sejlet ud siden de dumme gamle mudderfisk flyttede ind. Jeg vil vædde på at de også har spist alle havaborrerne.\n\nSig, vil du hjælpe mig med at fange Mørkekyst-havaborrer? Jeg ville give dig en ægte Blump-familiens fiskestang, hvis du gjorde! Det er en rigtig god stang at fange fisk med."},
  [1142] = {n="Dødens nærhed", l="Find og bring Treshalas Vedhæng tilbage til Treshala Brakbryn i Darnassos.", d="Jeg har ikke længe at leve... så... så... svag.\n\n...den m-m-modige dværg, Ensbryn, er blevet sendt for at v-v-advare Falfindel...\n\nMen før jeg... d-d-dør...\n\n...min kone, Treshala... hendes vedhæng af binding til mig... stjålet... af en af de f-f-fule angribere...\n\nFind det v-v-venligst... og bring det tilbage til Treshala i Darnassos...\n\n...sammen med b-b-budskabet om min ensomme... død."},
  [1144] = {n="Willix Importøren", l="Eskortér Willix Importøren ud af Tornekrattet.", d="Endelig er hjælpen kommet!\n\nDu aner ikke hvor længe jeg har været fange her. Jeg kan ikke huske sidste gang jeg så uden for dette sted.\n\nDu ser, jeg er iværksætter. Altid på jagt efter en skilling, som man siger. Jeg fik nys om at Mebok Snurrefix betalte godt for Rødblads-knolde fra denne her svinesti. Jeg regnede med det var en nem ind-og-ud-affære. Som du kan se, tog jeg lidt fejl!\n\nUnder alle omstændigheder, hvis du vil være så venlig at hjælpe mig herfra, så skal jeg nok gøre det umagen værd."},
  [1145] = {n="Sværmen vokser", l="Lever Korrands Forseglede Seddel til Belgrom Klippeknokler i Orgrimgrad.", d="Mange rejsende der er kommet forbi Korsvejen har hjulpet mig med at samle æg fra Kæmpernes Mark, og mange af dem har historier om hvor dødelige væsnerne er. Jeg har hørt nok til at betragte dem som insekter, en langt større trussel end mine herrer først troede.\n\nJeg har brug for en budbringer der kan rejse til Orgrimgrad for at møde Belgrom Klippeknokler. Det er ingen simpel sag, og en der tager opgaven alvorligt bør tage af sted.\n\nBelgrom plejer at kunne findes udenfor krigernes klanen."},
  [1146] = {n="Sværmen vokser", l="Lever Belgroms Forseglede Seddel til Moktar Krinsen i Tusindnåle.", d="Så, Korrand er kommet til en lignende konklusion om disse insekter--de ser ud til at være en større trussel end vi antog.\n\nFor få dage siden vendte en jæger tilbage til mig fra Tusindnåle næsten død. Han var med en plyndringstrup sendt for at drive et dværgisk udgravningshold væk fra Glimmerflatene. Under angrebet kom flere af disse insekter op fra en hule i udgravningsstedet og næsten dræbte trupperne.\n\nDe blev anført af Moktar Krinsen, og de har søgt tilflugt ved grænsen til Glimmerflatene. Bring ham denne seddel."},
  [1147] = {n="Sværmen vokser", l="Dræb 5 Silitid-søgere, 5 Silitid-kupdroner og 5 Silitid-angribere og vend tilbage til Moktar Krinsen i Tusindnåle.", d="Hm. Det ser ud til at Belgrom mener disse monstre er en trussel. Han vil have dem skubbet tilbage til de dybder de kravlede op fra.\n\nJeg gætter på at det ikke var nok at dræbe dværgene sendt af Opdagelsesrejsende-Ligaen--nu skal jeg sende en halvdød krigstrup ud i endnu en kamp. Vi kan ikke gøre det selv; ikke mens vi er i denne tilstand. Udgravningsstedet ligger mod syd herfra. Der burde ikke være flere dværge at tage sig af. Har du lyst til at svinge et sværd eller en stav og gøre din del for at hjælpe os?"},
  [1149] = {n="Troens prøve", l="Hvis du har tro, så spring fra planklerne over Tusindnåle.", d="Så, du har søgt mig op, eller måske fører skæbnen dig til mig? Det gør ingen forskel. Du er her nu, og din rejse begynder derfor på ny.\n\nMange facetter udgør et væsen: ånden, kroppen, sindet. Nogle af disse kan måles ud fra en kulturs traditioner. Andre kan vi kun håbe findes i os selv. Hvis du er enig, vil jeg prøve nogle af facetterne i dig.\n\nHvis du består, så vil du blive stærkere. Hvis du fejler, så vil du indse Nethers enorme vidde.\n\nDen første er en Troens Prøve."},
  [1150] = {n="Udholdenhedens prøve", l="Bring Grenkas Klo til Dorn Slettejæger i Tusindnåle.", d="Jeg er glad for at se dit mod står fast i lyset af det du allerede har gjort. Da din tro er intakt, er tiden kommet til at prøve din krop.\n\nDen første er en udholdenhedsprøve. Tag sammen med venner til Forræderfjer-hulen vest for Frihvind-posten. Find vej til dybderne af deres lair og ødelæg deres madforråd. Da skal du have fremkaldt deres raseri, og hvis du kan overleve længe nok, vil Grenka Blodskrig selv komme efter dig--dræb hende og bring mig hendes klo for at fuldføre din prøve."},
  [1151] = {n="Styrkens prøve", l="Bring Rok'Alims Fragmenter til Dorn Slettejæger i Tusindnåle.", d="I de Gamle Guders tid beboede elementarer en stor del af denne verden. De tilbad de Gamle Guder, og guderne holdt gennem deres magt elementarerne bundet til denne verden. Da de Gamle Guder blev forvist, forsvandt elementarerne fra vores verden og vender nu kun tilbage på mægtige magikeres befaling.\n\nDer findes dog undtagelser. Nogle elementarer var mægtige nok til at blive her på egen hånd. Et sådant elementar er Rok'Alim.\n\nFor at teste din styrke, find Rok'Alim i Tusindnåle og slå ham ihjel."},
  [1152] = {n="Lærdommens prøve", l="Find Braug Dunsånd nær indgangen til Klodsdybe-stien i Stenklippe-bjergene.", d="Din tid hos mig er næsten forbi. Jeg er vidende, men Lærdommens Prøve er ikke min at give. Der er lektioner at lære og steder at besøge, som andre gør krav på.\n\nHvis du er parat, så søg Braug Dunsånd--han er en shaman med stor visdom. Han vil teste dig yderligere, så lyt til hans ord, <Name>.\n\nNår du er klar, så find tunnelen der forbinder Stenklippe-bjergene med Askedalen: Braug holder til der i nærheden. Og vær forsigtig, <Name>, nattealferne kan have lyst til at forhindre din prøve."},
  [1153] = {n="En ny malmprøve", l="Find en uraffineret malmprøve på en Grussnude-graver eller -landmåler og bring den til Tatternack Stålsmed i Taurajo-lejren i Ødemarken.", d="<Class>, du har gjort det godt med at hjælpe mig før. Krigshøvdingen er tilfreds indtil videre med det jeg har udrettet, og beder mig fortsætte med fornyet beslutsomhed. Min ære kræver at jeg giver dig behørig anerkendelse fra krigshøvdingen for alt hvad du har gjort, men først vil jeg bede dig om din hjælp igen.\n\nRejsende er for nylig kommet fra syd, fra et sted der hedder Tusindnåle. Der dræbte de en kobold der havde en usædvanlig malmprøve, men de ville ikke sælge den. Jeg vil have en prøve af den malm til at undersøge."},
  [1154] = {n="Lærdommens Prøve", l="Find Aspekternes Arv og bring det tilbage til Braug Dunsånd nær indgangen til Klodsdybe-stien i Stenklippe-bjergene.", d="Du har bestået Dorne's prøver, og nu søger du efter din næste prøvelse. Meget godt. Men indtil nu har dine udfordringer været barnlige. Det er let at teste din krop--dit sind er en helt anden sag.\n\nJeg forklarer det enkelt: find den bog, jeg nævner, studér den, og svar på mit spørgsmål om dens indhold.\n\nHvilken bog, spørger du sikkert? Aspekternes Arv. Den kan findes på bunden af Dor'danil i det sydlige Askedalen, beskyttet af de døde druider og deres dræbere."},
  [1160] = {n="Lærdommens Prøve", l="Find Begyndelsen til Den Udøde Trussel, og bring den tilbage til Parqual Finttallas i Undergrunden.", d="Jeg vil fortælle dig, hvad du skal lede efter, og jeg stiller endda mit spørgsmål, men ikke fordi du ønsker at bevise dig selv. Viden er langt vigtigere end styrke. Selvom andre tilsyneladende overgår dig i evner, vil din viden om verden være mere værd.\n\nGå til klosteret i det nordlige Tirisfals Lysninger. I biblioteket dér findes en bog ved navn Begyndelsen til Den Udøde Trussel. Den blev brugt af de nu korrupte paladiner dér til at træne dem i at bekæmpe mit folk.\n\nBring den til mig."},
  [1164] = {n="At Stjæle Fra Tyve", l="Bring Kenaffas, Fardøls og Marcel Dabyries hoveder til Genavie Grønskolling i Undergrunden.", d="Luderen! Svinet! Kenaffa lever stadig; hendes familie sund og velstående, mens jeg lider. De Forladte, ganske vist!\n\nMin familie er væk, taget af pesten. Vores gods er også tabt; plyndret og brændt under krigen. Og efter alt det havde hun og hendes ynkelige børn den frækhed at stjæle de eneste dyrebare ejendele, jeg havde tilbage.\n\nJeg bekymrer mig ikke længere om de ting, de stjal. Det jeg vil have nu, er deres hoveder!\n\nDræb dem for mig! Gå til Dabyrie-gården i Arathi-højlandet, nordøst for Flygtningeodden."},
  [1167] = {n="Althalaxx' Tårn", l="Tal med Balthule Skyggestød nær Althalaxx' Tårn.", d="Før du konfronterer Atrikus, ville det nok være klogt at rådføre dig med Balthule. Jeg tvivler ikke på, at han har været årvågen i sin vagt over Tårnet, og han kan have information om nyere udviklinger."},
  [1175] = {n="Et Lille Bump på Vejen", l="Dræb 10 Saltsten-basilisker, 10 Saltsten-krystalhuder og 6 Saltsten-glorøjne for Banemester Zerrin i Glimmerflatene.", d="Efter det store styrt med nisseernes racerbil Rød Torden og en basilisk, hyrede Kronkryster mig til at passe banen. Jeg ved ikke, hvad alle dyrene derude på flatene æder, siden de er blevet så store, men vi må passe på at tynde dem ud, så de ikke vandrer ud på banen, når et løb er i gang.\n\nLad mig sige dig det. Hvis du vil ud og tjene lidt ekstra, så gå ud og fjern basiliskerne fra området."},
  [1179] = {n="Messingbolt-brødrene", l="Bring kassen med styrthjelme til Wizzle Messingbolt i Glimmerflatene.", d="Har du nogensinde hørt om Glimmerflatene? Det er en strækning saltflader langt herovre i Kalimdor, lige syd for Tusindnåle-kløften. Det er et fantastisk sted til væddeløb, for det er jo så fladt!\n\nEt par gnom-brødre er derude, venner af mig, der afprøver deres nye raketbil, og efter sigende er den hurtig! Hæhæ, så hurtig at deres piloter konstant styrter. De får sig selv hjernerystelser.\n\nSå de bad mig om nogle Belejringsvåben-hjelme, men jeg har pligter her. Jeg kan ikke tage turen!\n\nKan du?"},
  [1180] = {n="Nisse-sponsorat", l="Tal med Havnemester Lozgyl i Bytteviken.", d="Tilbage til det, du kom hertil for. Jeg lovede Pozzig, at jeg ville levere en ny brændstofsregulator til ham, men jeg har stadig ikke fået den. Tyranbrand nede i Bytteviken sagde, at han ville få den sendt over, men den kan være gledet mellem fingrene på en eller anden måde.\n\nHvis det er tilfældet, kan vi ikke gøre meget ved det. Vi kan i det mindste finde ud af, om den blev afsendt fra Bytteviken.\n\nTjek ind hos Havnemester Lozgyl derne, han burde kunne tjekke fragtlisterne."},
  [1182] = {n="Nisse-sponsorat", l="Bring brændstofsregulator-tegningerne til Baron Tyranbrand i Bytteviken.", d="Se, Ventureselskabets makulatorer ude i Nazferiti-søen (i det nordlige Kvælerdorn) er blevet udstyret med en ny model brændstofsregulator. Jeg tænkte, at Pozzig kunne drage fordel af den, hvis han kunne få detaljerne. Desværre ser Kozzle, formanden derude, ud til at være lidt snedigere, end jeg gav ham kredit for.\n\nDu virker, som om du måske har mere held med at finde tegningerne. Jeg ved, han opbevarer dem i sit hus, men de er næsten helt sikkert låst inde."},
  [1195] = {n="Den Hellige Flamme", l="Returner et fyldt ætset hætteglas til Zangen Stenhov i Tordenklippe.", d="Gallak-kentaurerne i Tusindnåle beskytter en genstand fra kentaurernes skabelsestid.\n\nVi vil gerne hente den, men vi har brug for et hætteglas vand fra en af nattealfernes måne-brønde.\n\nFor at samle vandet skal du først skaffe dig et af de hætteglas, som dryaderne bærer nær Rayne-skovens Tilflugt i Askedalens hjerte. Der er en måne-brønd ved den vestlige bred af Falfarren-floden, syd for hovedvejen, hvor du kan fylde hætteglasset."},
  [1196] = {n="Den Hellige Flamme", l="Lever det fyldte ætsede hætteglas til Rau Klippeløber ved Frihvind-posten.", d="Bring det fyldte hætteglas til Rau Klippeløber ved Frihvind-posten i det sydøstlige Tusindnåle. Du kommer til Tusindnåle ved at tage Den Store Elevator i den sydlige kant af Ødemarken.\n\nDet ville ikke undre mig, hvis du kan hjælpe os yderligere."},
  [1197] = {n="Den Hellige Flamme", l="Hent den Kløvede Hov til Rau Klippeløber ved Frihvind-posten.", d="Med det vand, du bragte, kan du midlertidigt slukke flammen, der holder kentaur-relikvien. Det virker dog ikke permanent, så du må være hurtig.\n\nDu vil finde Splithov-klippen, kentaurernes højborg, nord for her. Flammen opbevares i Splithov-borgen, en tungt bevogtet del af klippen.\n\nVær dog forsigtig, for Gallak-kentaurerne er talrige her, og de vil være ret tilbageholdende med at give afkald på noget så kært for dem."},
  [1198] = {n="På Jagt Efter Thaelrid", l="Søg efter Sølvvagt Taelrid i Den Sorte Afgrund.", d="Der går mange rygter i disse dage om forbundet mellem Tusmørkets Hammer og nagaerne i Den Sorte Afgrund ved kysterne i Askedalen.\n\nMin rolle her hos Sølvdæmringen er at indsamle så meget information, jeg kan, så vi ved, hvornår og hvor hjælp er nødvendig.\n\nDet er nu flere uger siden, jeg sendte en spejder for at tjekke aktiviteten i Den Sorte Afgrund. Sølvvagt Taelrid har endnu ikke meldt tilbage.\n\nMine andre spejdere har travlt med vigtigere sager.\n\nSøg efter og hjælp Taelrid for mig, <Name>."},
  [1199] = {n="Tusmørkets Fald", l="Bring 10 Tusmørke-vedhæng til Sølvvagt Manadøs i Darnassos.", d="Styrket af de gamle ritualer fra de kaotiske Gamle Guder stræber Tusmørkets Hammers medlemmer efter at genskabe deres mørke herrer og sprede død og rædsel over hele verden.\n\nVi tror, at Tusmørkets Hammer har indgået en alliance med nagaerne og samler styrke i Den Sorte Afgrund på kysten af Askedalen.\n\nUanset hvilken ond plan der bryger i det gamle tempels dybder, må den forpurres.\n\nFør krig mod Hammeren og bring bevis for dine bedrifter tilbage. Din indsats vil blive belønnet rigeligt."},
  [1200] = {n="Den Sorte Afgrunds Skurkeri", l="Bring Tusmørke-lord Kelriks hoved til Daggryvogter Selgorm i Darnassos.", d="Min styrke har forladt mig. Din hjælp er nødvendig!\n\nFor længe siden var dette sted et stort tempel for Elune. Men uheld førte til ruin, da korruptionen fra en Gammel Gud sivede op fra jorden og besmittede den hellige Måne-brønd.\n\nAku'Maj, tjener af den Gamle Gud, rejste sig fra vandet.\n\nTusmørkets Hammer-kultisterne har indgået alliance med nagaerne for at besætte disse grunde. Kultisterne, ledet af Kelrik, ofrer uskyldige til Aku'Maj for magt.\n\nDræb Kelrik og bring hans hoved til Selgorm i Darnassos, <Name>, tak."},
  [1201] = {n="Theramøre-spioner", l="Dræb 9 Theramøre-infiltratorer, og vend derefter tilbage til Nazir Blodspyd i Brakkenmur-landsbyen.", d="Horden og Alliancen har en urolig våbenhvile. Afsides træfninger og skjulte aktioner udføres af den ene side mod den anden, og det er vores pligt at sikre, at Horden står øverst!\n\nNu er chancen der for at gøre netop det.\n\nAlliance-infiltratorer har indtaget positioner øst for Brakkenmur-landsbyen. De spionerer på landsbyen og rapporterer vores bevægelser til Theramøre, hvilket vi ikke kan tillade.\n\nJag infiltratorerne ned og slå dem ihjel. Send et klart budskab til deres overordnede om, at vi ikke vil tolerere deres spioners tilstedeværelse!"},
  [1221] = {n="Blåblads-knolde", l="Tag en Kasse med Huller.\nTag en Snufsenæse-kommandostok.\nTag og læs Snufsenæse-brugsanvisningen.\n\nI Tornekrattet skal du bruge Kassen med Huller til at kalde en Snufsenæse-jordrotte, og bruge kommandostokken på jordrotten for at få den til at lede efter knolde.\n\nBring 6 Blåblads-knolde, Snufsenæse-kommandostokken og Kassen med Huller til Mebok Snurrefix i Skralleby.", d="Blåblads-knolde er en delikatesse over hele verden! Men de er sjældne, meget sjældne. Det eneste sted at finde dem er her i Ødemarken, dybt i jorden, i Tornekrattet.\n\nOg selv da er de umulige at finde, medmindre du ved præcis, hvor du skal lede! Derfor har jeg trænet disse snufsenæse-jordrotter til at finde dem for mig. De har gode næser og kan lugte en knold på halvtreds skridts afstand.\n\nDet bliver ikke let, men hvis du skaffer mig nogle knolde, betaler jeg dig rigeligt."},
  [1241] = {n="Den Forsvundne Diplomat", l="Find Jørgen i Stormvind By.", d="For nylig blev en diplomat sendt til Theramøre for at mødes med Jaina Stoltmoor. Den diplomat ankom aldrig.\n\nJeg tror, at Defias er involveret i denne plan, men jeg er ikke sikker på hvordan. Diplomatens forsvinden undgår stadig offentlighedens opmærksomhed, men det kan ikke vare længe.\n\nKongens agenter gennemsøger allerede byen efter spor, men jeg har mine egne kontakter, som jeg gerne vil have involveret.\n\nI Heltenes Dal findes en gammel ven af mig ved navn Jørgen. Find ham, giv ham denne seddel, og følg hans instrukser."},
  [1242] = {n="Den Forsvundne Diplomat", l="Lever Jørgens forseglede seddel til Elling Trøsen i Stormvind By.", d="Tag denne seddel med til Elling Trøsen. Sig ikke andet til ham. Vær bare høflig og vent på, at han svarer. Og bekymr dig ikke, han vil svare.\n\nJeg vil kun pointere dette én gang mere, <Name>: Tag denne sag alvorligt, og hold din kæft.\n\nDu finder Trøsen i hans ostebutik, Trøsens Ost, i Handelsdistriktet. Held og lykke."},
  [1243] = {n="Den Forsvundne Diplomat", l="Giv den forseglede seddel til Vagt Bakkus i Skumringsskoven.", d="Jørgen, din gamle skiderik.... Så sådan er det, hva'?\n\nSå, det kan jeg håndtere. Jeg håber, han finder Tvistende Nether endnu hurtigere!\n\nSådan her bliver det, <Name>. Jeg begynder at bruge mine kontakter her, men du laver det meste af det praktiske arbejde, så jeg sparer lidt mønter.\n\nTag til Mørkeshire i Skumringsskoven og find Vagt Bakkus--han patruljerer normalt den nordlige vej lige uden for byen. Bare sig, at du undersøger al Defias-aktivitet for mig, så hjælper han dig med alle de oplysninger, han kan."},
  [1244] = {n="Den Forsvundne Diplomat", l="Find Defias-dossieret og returner det til Vagt Bakkus i Skumringsskoven.", d="Defias-aktivitet? Nå, der er altid noget aktivitet; selv hvis de holder sig for sig selv, betragter vi dem som en trussel.\n\nMen nu hvor jeg tænker over det, var der en nylig observation, der virkede underlig. Det må have været for et par uger siden, men nogle af deres agenter havde samlet sig omkring Addles Gård. Ud fra rapporten gætter jeg på, at noget stort er sket.\n\nHvorfor tjekker du ikke der først og bringer mig tilbage, hvad du finder?\n\nGården ligger syd for vejen fra Vestfald, lige når du kommer ind i Skumringsskoven."},
  [1245] = {n="Den Forsvundne Diplomat", l="Bring Defias-dossieret til Elling Trøsen i Stormvind.", d="Whoa, det her ser alt for komplekst ud til bare at være noget, der skal lede dig vild. Jeg burde ikke engang kigge på den slags. Tag det med til Trøsen--han kan finde ud af det. Og LAD IKKE nogen stå i din vej. Det her er større end mig. Det kan endda være større end ham, men vi får at se.\n\nOg gør mig en tjeneste, <Name>, fortæl ikke nogen, at jeg hjalp dig. Hvis mine overordnede fandt ud af, at jeg kendte til noget af dette og ikke delte det med dem, ville de nok hænge mig."},
  [1246] = {n="Den Forsvundne Diplomat", l="Tal med Dashel Stenneve i Stormvind.", d="Ja, nu hvor jeg tænker over det... Dashel... Dashel noget... Hvad hed han nu? NEVE! Dashel Stenneve. I nogle kredse kalder de ham Neve--sikkert fordi han kan lide at blande sig i slagsmål.\n\nDu kan normalt finde ham i Gamlebyen--lige midt i det hele. Gå og tal med ham. Hvis du må, så brug et sværd eller noget tungt og stumpt for at overtale ham til at åbne sig lidt. Og tøv ikke. Hvis han er lige så dybt involveret, som disse papirer antyder, så vil han ikke give dig nogen oplysninger frivilligt."},
  [1247] = {n="Den Forsvundne Diplomat", l="Tal med Elling Trøsen i Stormvind.", d="Så ja... øh... jeg ved måske lidt om det møde ved Addles Gård. Det var for et par uger siden, tror jeg. Jeg havde virkelig ingen del i det. Min del var færdig, da plan A slog fejl... forbandede eventyrere.\n\nFyren, vi havde på indersiden til plan B, kom fra Menetil; en fyr ved navn Slank. Det er alt, hvad jeg ved om deres reserveplan."},
  [1248] = {n="Den Forsvundne Diplomat", l="Tal med Mikail i Vådlandene.", d="En af mine kontakter gik på pension i Vådlandene, i havnebyen Menetil. Han vil gerne hjælpe, bare på dit ord, hvis du fortæller ham, at du arbejder for mig. Hans navn er Mikail. Han nævnte, at han blev barmand, før han forlod Stormvind for et par år siden.\n\nTal med ham, find denne Slank, og find ud af, om der er noget mere at vide om den kidnappede diplomat. Vi må finde ud af, hvor de har taget ham hen, eller i det mindste hvem han er. Dossieret nævner intet om deres planer, efter at han er blevet taget til fange."},
  [1249] = {n="Den Forsvundne Diplomat", l="Overmand Tapoke Jahnsen, før han flygter, og vend derefter tilbage til Mikail i Menetil.", d="Siger du, at Elling sendte dig herhen? Så er den gæstfrihed, jeg udviste, nu ti gange så stor. Alt, hvad du behøver, skal du bare spørge om. Jeg vil gøre mit bedste for at hjælpe dig.\n\nHm, Slank, siger du? Jeg er ikke sikker på, at navnet lyder bekendt, men jeg holder øje efter ham.\n\nKig ikke nu, <Name>, men herren ved udgangen kigger herhen. Han lytter til vores samtale alt for intenst, hvis du forstår mig? Hvis jeg var dig, ville jeg gøre, hvad jeg kan for at overmande ham, før han løber mod døren."},
  [1251] = {n="Det Sorte Skjold", l="Bring det sortbrændte jernskjold til Krøg i Brakkenmur-landsbyen.", d="Et jernskjold, sortbrændt af branden der hærgede kroen, sidder fast på den smuldrende skorsten, en af de få tilbageværende dele af bygningen der engang udgjorde Skyggefuld Hvile-kroen.\n\nSkjoldet kan trækkes ud af skorstenens mursten."},
  [1264] = {n="Den Savnede Diplomat", l="Find Kommandør Samaul i Støvsumpen.", d="Starten på hver måned får Kul Tirask-marinesoldaterne alle udbetalt, og de forlader som regel Theramøre for et andet sted. Mange af dem kommer hertil for at flirte, feste og bare have det hyggeligt. En af de grupper ville jeg betegne som faste gæster her i kroen, og jeg tror, at denne Hændel er blandt dem.\n\nKommandør Samaul i Theramøre kan hjælpe dig med at finde ham, hvis Hændel stadig er stationeret der. Han er fuldstændig loyal over for Stoltmoor, men hvis du nævner Ellings navn, burde han hjælpe dig... diskret."},
  [1265] = {n="Den Savnede Diplomat", l="Undersøg Vagtpunktet for spor af Menig Hændel.", d="Hændel? Jo, jeg kender manden. Men hvorfor skulle du bruge en af mine soldater?\n\nElling sendte dig for at finde ham? Hmm, den lyder ikke godt. Elling ville ikke have sendt dig til mig først, hvis din sag ikke var bekymrende. Jeg forstår, hvis du ikke kan fortælle mig, hvad det drejer sig om, men husk dette: Jeg har en pligt til at beskytte disse lande. Hvis du agter at skabe uro, så foreslår jeg, at du fortæller mig alt, hvad du kan.\n\nJeg tror, Hændel var stationeret i det første tårn uden for Theramøre. Vær forsigtig."},
  [1268] = {n="Mistænkelige Hovaftryk", l="Meld de mistænkelige aftryk ved Skyggefuld Hvile-kroen til Krøg i Brakkenmur-landsbyen.", d="Rækker af hovaftryk fører væk fra det stadig rygende skelet af Skyggefuld Hvile-kroen. Der er mindst et par synlige aftryk, med flere rækker aftryk, der næsten ikke kan ses i sumpens bløde mudder."},
  [1269] = {n="Løjtnant Pavle Rytte", l="Bring Rytte's Mærke til Krøg i Brakkenmur-landsbyen.", d="Et glimt af lys på jorden fanger dit blik under murbrokkerne. Når du børster snavs og aske af genstanden, afslører den et emaljeret insignia med et gyldent anker på hvidt: Theramøres tegn.\n\nUnder ankeret er navnet \"Løjtnant Pavle Rytte\" præget ind."},
  [1273] = {n="Afhøring af Rytte", l="Gå med Ogrøn for at tale med Rytte, og vend derefter tilbage til Krøg i Brakkenmur-landsbyen.", d="Det tog lang tid, men jeg fandt Rytte. Han gemme sig godt for et menneske.\n\nOgrøn bekymre at han måske er blevet tosset af så lang tid i sump. Du komme med mig, for vi skal få svar fra ham."},
  [1274] = {n="Den Savnede Diplomat", l="Find Biskop DeLøvi i Stormvinds Fæstning.", d="Undskyld mig, herre / frue. Biskop DeLøvi bad mig henvende mig til eventyrere, der måske kunne hjælpe ham med en delikat sag.\n\nHvis du roligt kunne begive dig til Stormvinds Fæstning og tale med ham ved første givne lejlighed, er jeg sikker på, at han ville sætte pris på din hjælp. Og igen: Vær diskret, tak. Det er en sag af en vis betydning."},
  [1275] = {n="Forskning i Korruptionen", l="Gershala Natviskning i Auberdin vil have 8 Korrumperede Hjernestængler.", d="Dumme blodalfer slider med dæmonisk magi. Har de ikke set, hvad der skete med nagaerne og med skovbukkene i Kalimdør?\n\nJeg frygter, at blodalferne vil møde en lignende vanskabning. Azerot har ikke råd til at føde endnu en ussel monsterrace.\n\nJeg ønsker at studere skovbukkenes og slangefolkets hjernestængler, så jeg kan udlede, hvilken skæbne alferne er på vej mod. I Den Sorte Afgrund, ved kysten af Askedalen, finder du både Skovbuk og slangefolk.\n\nDet er en lang rejse, <Name>."},
  [1284] = {n="Mistænkelige Hovaftryk", l="Meld de mistænkelige aftryk ved Skyggefuld Hvile-kroen til Kaptajn Garran Vimmes i Theramøre.", d="Rækker af hovaftryk fører væk fra det stadig rygende skelet af Skyggefuld Hvile-kroen. Der er mindst et par synlige aftryk, med flere rækker aftryk, der næsten ikke kan ses i sumpens bløde mudder."},
  [1302] = {n="James Hyl", l="Tal med Skriver Lendri i Theramøre.", d="Min bror James tog med Lady Stoltmoor over havet. Sidst jeg hørte, havde kampene lagt sig deroppe, og James var ved at åbne en kro et sted på kontinentet. Uanset hvor han er, er jeg sikker på, at han gør gode forretninger. Pokkers god kok var han.\n\nJeg har ikke hørt fra ham i noget tid nu--for travlt med sin kro, vil jeg vædde på--men skriveren i Theramøre kan nok pege dig i hans retning."},
  [1322] = {n="Det Sorte Skjold", l="Skaf 6 Syrlige Giftsække til Do'gøl i Brakkenmur-landsbyen.", d="Hmmm, der er skrift lige her på skjoldets kant, men det er svært at læse gennem alt det brændte.\n\nJeg skal bruge syre for at gøre det tydeligt. Gift fra Mørkehugger-edderkopperne i sumpen ville gøre det godt. Skaf mig nogle af deres sække, så kan jeg gøre det rent."},
  [1338] = {n="Stormspids' Ordre", l="Bring Stormspids' Anmodning til Furen Langskæg i Stormvind.", d="Der er en dværgisk rustningssmed, hvis arbejde jeg beundrer meget. Han hedder Furen Langskæg, og hans færdigheder er uovertruffne. Jeg har brug for et nyt skjold, og jeg må have et af hans!\n\nProblemet er... Furen befinder sig langt mod syd, i dværgekvarteret i Stormvind. Midt i menneskenes lande! Jeg kan ikke forestille mig, hvorfor han ville bo der, så langt fra Jernsmede. Menneskene må betale ham en kongelig løsesum for at holde ham der!\n\nSå hvis du har lyst til at rejse og ikke har noget imod at tjene lidt penge, vil du så sende Furen min anmodning om et skjold?"},
  [1339] = {n="Bjergbestiger Stormspids' Opgave", l="Tal med Bjergbestiger Stormspids.", d="Jeg har hørt, at Bjergbestiger Stormspids leder efter en løber. Nogen, der kan rejse lidt rundt for ham. Hvad siger du? Er du den <Race>, der passer til jobbet?\n\nHvis ja, så finder du Stormspids øverst i det nordlige vagttårn."},
  [1358] = {n="Prøve til Helbrim", l="Bring Ulvehjerte-prøven til Apoteker Helbrim i Ødemarken.", d="En kollega i Kalimdør, Apoteker Helbrim, forsker i virkningen af Herrelande-gifte på Kalimdørs udyr. Han ville være meget interesseret i en prøve af de ulvehjerter, Renferrel sendte mig.\n\nHelbrim er stationeret i Ødemarken, i en landsby kendt som Korsvejen. For at nå ham skal du rejse med zeppelin til ork-hovedstaden Orgrimgrad, og derefter rejse sydpå til fods til Durdotar. Tag mod vest ind i Ødemarken, så når du snart Korsvejen."},
  [1361] = {n="Regthar Dødsporten", l="Tal med Regthar Dødsporten.", d="En kriger fra Horden, Regthar Dødsporten, rekrutterer agenter til en mission ind i Forødelse. Tal med ham, hvis du vil melde dig frivilligt. Han er stationeret i Ødemarken, i en række bunkers vest for Korsvejen.\n\nOg slib dine våben. Forødelse er et sted revet itu af krig."},
  [1362] = {n="Kolkarerne i Forødelse", l="Tal med Felgur Tvehugg ved Spøgelsesvandrer-posten i Forødelse.", d="Kolkar-kentaurerne lever i Forødelse, og deres styrker har spredt sig ind i Ødemarken. Det er en velkendt sag, og vi har Horde-agenter, der håndterer dem her.\n\nMen så længe kentaurerne er stærke i Forødelse, vil de altid udgøre en trussel. Det er på tide, vi slipper af med den trussel.\n\nTal med Felgur Tvehugg ved Spøgelsesvandrer-posten i Forødelse. Han blev sendt for at indsamle efterretninger om kentaurerne. Han ved, hvordan man bedst håndterer Kolkarerne i Forødelse."},
  [1365] = {n="Khan Dæs'hepa", l="Bring Khan Dæs'hepas Hoved til Felgur Tvehugg i Forødelse.", d="Kolkarerne er ikke de eneste kentaurer i Forødelse. Mange klaner vandrer over de tørre sletter, kæmper og dør mod hinanden. Og det er godt, at de kæmper indbyrdes, for de er stærke og brutale. Hvis kentaurerne forenede sig mod os, ville de være en farlig fjende.\n\nVi må tage hånd om dem, før de forener sig.\n\nDin første opgave er at forstyrre Kolkar-klanen. Gør det ved at dræbe dens leder, Khan Dæs'hepa.\n\nKolkar-landsbyen ligger nordøst herfra. Af sted med dig, og må lykken følge dig."},
  [1366] = {n="Kentaur-dusøren", l="Bring 15 Kentaur-ører til Felgur Tvehugg i Forødelse.", d="Nu hvor du har skræmt kentaurklanerne, er det tid til at lade dem bløde. Når du rejser i Forødelse, skal du jage kentaurer. Jeg er ligeglad med, hvilken klan du jager. Bare saml ører. En skatkiste fuld af ører.\n\nVed at svække deres antal svækker du deres vilje og udsletter enhver tanke om ekspansion.\n\nGod jagt, <Name>."},
  [1368] = {n="Gellekis-alliancen", l="Opnå et venligt ry hos Gellekis-klanen, og tal derefter med Uthek den Vise.", d="For at besejre kentaurerne må vi bruge deres had mod dem. Vi vil alliere os med en af klanerne, og gennem dem lærer vi, hvordan vi besejrer alle klanerne.\n\nHvis du vælger at alliere dig med Gellekis, så dræb deres mest hadede rival, Magrom. Når du har fortjent Gellekis' respekt, skal du mødes med Gellekis-shamanen Uthek den Vise i udkanten af Gellekis-landsbyen i det sydvestlige Forødelse."},
  [1371] = {n="Krimskrams til Vorrug", l="Bevar dit ry hos Magrom, og bring en Avanceret Målpuppe til Vorrug i Magrom-landsbyen i Forødelse.", d="For længe siden kom en lille gnom til Forødelse. Han havde heste og en vogn, og vognen rummede mærkelige ting. Morsomme ting. Ting der brændte i forskellige farver. Ting der bevægede sig, selvom de ikke var levende. Jeg dræbte den lille gnom, men før det... fik han mig til at more mig.\n\nJeg beholdt min yndlingsting fra hans vogn. Det var et menneske lavet af træ, og det vinkede til mig, indtil jeg slog det i stykker.\n\nJeg vil have en ny. Skaf mig en ny!"},
  [1386] = {n="Angrebet på Kolkarerne", l="Bevar dit ry hos Magrom. Dræb 12 Kolkar-kentaurer, 12 Kolkar-spejdere og 6 Kolkar-lemlæstere, og vend derefter tilbage til Vorrug i Magrom-landsbyen i Forødelse.", d="Kolkarerne tror, de er stærke, men vi griner af dem! Vi griner og dræber dem! Det skal du også gøre. Vis mig, at du kan dræbe Kolkarer, ligesom vi gør. Tag mod nord og slå dem alle ihjel!"},
  [1418] = {n="Neeka Blodsar", l="Tal med Neeka Blodsar.", d="Ødelandene er barske og ligger tæt på det alliancebesatte land Modansøen, så kommunikationen mellem Stenard og Ødelandenes forpost Kargat bliver ofte afbrudt.\n\nBevis dig selv, <Name>. Rejs til Ødelandene og tal med Neeka Blodsar, hovedspejderen ved Kargat-forposten. Tal med hende, og send derefter hendes rapport tilbage til mig."},
  [1419] = {n="Kojote-tyvene", l="Bring 30 Kojote-kæbeben til Neeka Blodsar i Kargat.", d="Har du brugt mange dage i Ødelandene, <Class>? Har du mærket dens hede? Har du mødt de udyr, der vandrer over dens støvede sletter? Det er på tide, at du gør det.\n\nKlippekojoter er en sej race. Seje nok, og dristige nok til at liste ind i Kargat og stjæle fra vores madlager. Hjælp med at rydde forposten for disse tyve!\n\nJag klippekojoter, <Name>. Jag dem og bring mig deres kæbeben. Bring mig nok, og så tror jeg måske på dig, når du siger, at du kender Ødelandene."},
  [1420] = {n="Rapport til Helgrum", l="Bring Neekas Rapport til Helgrum den Hurtige i Stenard.", d="Jeg skrev en frisk rapport til Helgrum i Stenard. Bring den til ham.\n\nOg hvis du betragter dig selv som en løber, så lad være med at fare vild. Eller falde for en fjende."},
  [1431] = {n="Alliance-forbindelser", l="Tal med Keldrun i Orgrimgrad.", d="Stil dig, <Class>, og lad mig dele noget vigtigt for vores folk, men langt fra indlysende.\n\nVi er en stolt race, og krigen med menneskene prøvede selv Traels store tålmodighed. Se, vores Krigshøvding er klog og forsigtig, og han sætter fortsat sit folk først. Til syvende og sidst er han en diplomat, og i sin tid blandt menneskene lærte han meget om deres måder.\n\nHvis historien, jeg er begyndt på, vækker din interesse, så find Keldrun nær byens vestlige udgang. Hans hytte står der."},
  [1432] = {n="Alliance-relationer", l="Tal med Takata Stålklinge i Forødelse.", d="Efterhånden som Alliancen trænger dybere og dybere ind i Kalimdør, kan der drages forkerte konklusioner om, at Horden indgår pagter med den Brændende Legion. Krigshøvdingen kan ikke tillade, at det sker. Og med hans velsignelse overtager jeg tilsynet med dem, fjernet.\n\nJeg har agenter i Forødelse ved Spøgelsesvandrer-posten nord for det store Kodo-kirkegård. Gå sydpå fra den Brændte Dal i Stenklippe-bjergene, så vil du støde på den. Når du ankommer, så led efter Takata Stålklinge."},
  [1433] = {n="Alliance-relationer", l="Tal med Maurin Knoglekløver i Forødelse.", d="Den Brændende Klinge har mange dagsordener, men vid at de er onde til kernen, deres ånder fordærvede, og at deres undergang er den eneste måde at forpurre deres mål på.\n\nKeldrun sendte Maurin med mig på grund af hans kendskab til Klingen og deres hekseri-vis.\n\nHan har kontrol over vores planer mod Klingen, mens jeg tager mig af de andre dæmoniske trusler her i Forødelse.\n\nTal med ham, så vejleder han dig i hans planer."},
  [1434] = {n="Besmittet af Skovbuk", l="Dræb 7 Hadfuror-skurke, 7 Hadfuror-ondsvorne, 7 Hadfuror-forrædere og 7 Hadfuror-helvedeskaldere, og vend tilbage til Takata Stålklinge i Forødelse.", d="En dæmonisk infestation opstår ikke uden andre påvirkninger--noget andet giver det onde fodfæste.\n\nDet kan begynde med en svækket ånd, et unødvendigt begær efter magt; måske er det tørst efter hævn, eller tiltrækningen af endelig retfærdighed. Når vi bliver plaget af smerte, udnytter det onde os--såsom skovbukken.\n\nDer er knyttet bånd mellem dem og Den Brændende Klinge, og Trael ville have dem slået ihjel. Søg dem mod nordøst herfra, og vend tilbage til mig, når du har drevet dem tilbage."},
  [1435] = {n="Åndernes Brænding", l="Returner den Brændende Ædelsten og 15 Infunderede Brændende Ædelsten til Maurin Knoglekløver i Forødelse.", d="Døden er mest ønskelig for de forkastelige skabninger, der vender ryggen til deres herre af så egoistiske grunde. Men døden er ikke nok, når man har at gøre med dem, der har overgivet sig til mørket.\n\nTag denne ædelsten. Når en af Den Brændende Klinge er nær døden, så aktiver dens magi. Besværgelsen trækker den fordærvede ånd ud af dens offer og efterlader en infunderet ædelsten.\n\nBring mig disse infunderede ædelsten, så jeg kan skille mig af med dem på ordentlig vis.\n\nGå nu, og må du undslippe døden."},
  [1442] = {n="Jagten på Kor-ædelstenen", l="Bring en Kor-ædelsten til Thundris Vindvæver i Mørkekysten.", d="Hilsen, <Name>. Hvad kan jeg gøre for den, der følger en hellig vej?\n\nÅh ja, Stilvæg, smeden... fra længst tilbage. Jeg husker ham godt, selvom jeg ikke har hørt hans navn i noget tid.\n\nHan virkede aldrig som en uforskammet mand på mig, så jeg kan kun antage, at hans ønske om en Kor-ædelsten er ædelt.\n\nHvis du virkelig ønsker en af ædelstenene, så må du mod nordvest fra Askedalen. Der finder du Den Sorte Afgrund inde i nogle gamle ruiner. Slangefolkene, som stadig bruger ædelstenene, er dernede. Gå ikke alene, <Class>."},
  [1447] = {n="Den Savnede Diplomat", l="Besejr Dashel Stenneve i Stormvind.", d="Ja, du er tydeligvis ikke den klogeste <Class>, der er kommet til Stormvind, men du er ved at blive en af de dummeste, der aldrig forlader den.\n\nHar du mødt mine venner?"},
  [1453] = {n="Genvindernes Forretning i Forødelse", l="Tal med Kreldig Ungør i Forødelse.", d="Der er arbejde at gøre i Forødelse, <Name>. Det er et grusomt sted, besmittet af kentaurer og andre skadedyr. Men hvis du leder efter en god uges ærlige arbejde, så tag derhen, mød Kreldig Ungør, og fortæl ham, at jeg sendte dig.\n\nDu finder ham gemt op på Nijels Punkt--en lille hyggelig lejr skjult i bjergene i det nordlige Forødelse. Tag blot mod øst, hvis du kommer ind fra Stenklippe-bjergene. Den er let at overse, så hold øje."},
  [1470] = {n="Gennembrydning af Sløret", l="Bring Venya Marthånd 3 Rasselbur-kranier.", d="Hilsen, barn. Jeg kan se, at du stadig er ung i hekseriets veje, og at kraften stadig undslipper dit greb. Jeg kan fornemme din ivrighed efter at lære.\n\nOg du skal lære.\n\nDer er ingen styrke i uvidenhed. Viden er vores største magt. Gennem dens anvendelse kan vi kontrollere tomrummets kaotiske magier og væsener og bøje dem efter vores vilje.\n\nJeg vil vise dig, hvordan man binder en tjener til sin vilje, men først skal du bringe mig tre kranier fra rasselbur-skeletterne ved den forladte smedje."},
  [1471] = {n="Bindingen", l="Brug Kaldsrunerne til at kalde og tæmme en tomgænger, og returner derefter Kaldsrunerne til Carendin Halgaar i Magikvarteret i Undergrunden.", d="Du har sikkert set kaldecirklen under os? Kun der vil du kunne trække en ubundet tomgænger frem.\n\nMed disse runer vil du kunne trække den frem, og så må du dominere den gennem armenes og magiens styrke.\n\nNår den er tæmmet, vil den stå i din gæld. Kom så til mig, og jeg vil forklare kaldelsesbesværgelsen, så den kan tjene dig til hvilken ende du end ønsker."},
  [1473] = {n="Tomrummets Skabning", l="Gendan Egalins Grimoire og bring den til Carendin Halgaar i De Fordømtes Tempel.", d="Det ser ud til, at konsensus er, at du er klar til at lære at kalde en tomgænger.\n\nEn skabning skabt af kaosset hinsides, hvis du kalder en, men ikke kan kontrollere den, vil du blive revet itu.\n\nDen første tomgænger blev kaldt af Egalin, og i hans grimoire står processen forklaret.\n\nDesværre blev den stjålet fra os af en agent for Skarlagenrøde Korstog, som har gemt den væk i hans base i et tårn mod vest. Bring den til mig, så lærer jeg dig kundskaben."},
  [1476] = {n="De Renes Hjerter", l="Bring hjerterne af Dalin Smedeværk og Corma Vildmand til Carendin Halgaar i De Fordømtes Tempel.", d="At lokke en succubus kræver de rene hjerter. Men er nogen dødelig uden last?\n\nGennem stumper af overhørte historier fandt jeg to mennesker, der burde gøre det.\n\nDen første er Dalin Smedeværk, som har viet sig til omsorgen for flygtningene fra Herrelande, som deres egne afvises af ved Gråmanke-muren.\n\nDen anden er Corma Vildmand, en kvinde, der forbliver tro mod sin tabte elskede og vandrer rundt i Vådlandene på jagt efter et tegn fra ham.\n\nLever deres hjerter til Carendin. Men først, lad mig vise dig dit bytte."},
  [1478] = {n="Halgaars Tilkaldelse", l="Tal med Carendin Halgaar i Undergrunden.", d="Ah, <Name>! Jeg har lige modtaget besked fra Carendin Halgaar om, at han gerne vil se dig for yderligere træning.\n\nDu bør være stolt af dig selv, <Name>. Det er ikke hver dag, at Mester Halgaar personligt finder det passende at undervise en ung hekser.\n\nDu finder ham i Magikvarteret i Undergrunden, nær De Fordømtes Tempel."},
  [1480] = {n="Fordærveren", l="Bring den Afskrællede Dæmonhud til Maurin Knoglekløver i Forødelse.", d="Den revne hud lugter råddent og er bemærkelsesværdigt smidig for noget, der ser tør og skrøbeligt ud.\n\nNår du folder den ud, kan du tydeligt se de røde mærker af et slags sprog på den ene side. Nederst på huden står et meget tydeligt symbol, som du gætter er en slags underskrift.\n\nMåske er der noget, Maurin kunne fortælle dig mere om?"},
  [1481] = {n="Fordærveren", l="Bring en Skyggesniger-hovedbund til Maurin Knoglekløver i Forødelse.", d="Jeg tror, jeg kan finde denne dæmonlord, hvis jeg får de rette reagenser.\n\nHvis han virkelig er så mægtig, som jeg mistænker, skal jeg bruge ting indsamlet fra dødelige væsener. Men du handler i krigshøvdingens navn, så jeg er sikker på, at du vil acceptere min opgave.\n\nFørst må jeg bryde eventuelle beskyttelser, han har mod synsforsøg. Til det skal jeg bruge hovedbunden fra en skovbuk--men ikke hvilken som helst skovbuk. Hovedbunden skal komme fra en Hadfuror-skyggesniger.\n\nLed efter dem i de gamle ruiner mod nordøst i Forødelse."},
  [1483] = {n="Ziz Sprydhjul", l="Tal med Ziz Sprydhjul i Vindskær-klippen.", d="Ventureselskabet stjal mange af de bedste goblin-hjerner, men fra tid til anden får vi mulighed for at stjæle nogle tilbage.\n\nFor et stykke tid siden hyrede Ventureselskabets afdeling i Stenklippe-bjergene Gerenzo Skruefløjte--en gnome! Deres anden ingeniør, Ziz Sprydhjul, blev så slået bagover af dette, at han bønfaldt mig om at finde ham nyt arbejde hos Tinkerforeningen. Jeg har sat ham til nogle opgaver, men han har måske brug for hjælp.\n\nMåske kunne du kigge ind til ham for mig? Han er stationeret ved den vestlige kant af Vindskær-klippen."},
  [1485] = {n="Ondskabsfulde Følgesvende", l="Bring 6 Ondskabsfuld Følgesvends-hoveder til Ruzan.", d="De hekser, der kom før os, har fortjent Hordens mistillid, og selvom vi tolereres, er vi ikke elsket.\n\nDette har dog ikke bragt heksene tættere sammen, for mange vælger at leve tilbagetrukket og fingre med deres magier alene. Jeg vil ikke forsøge at lede dig ned ad den ene eller den anden vej, men kun hjælpe dig i din modning.\n\nFør jeg lærer dig kunsten at kalde, så bring mig seks hoveder af de ondskabsfulde følgesvende fra hulen mod nordøst."},
  [1486] = {n="Afviger-huder", l="Nalpak i Jammergrotterne vil have 20 Afviger-huder.", d="Da Naralex sank dybere ned i sit mareridt, opstod en mærkelig race af dyr fra under Ødemarken op i Jammergrotterne.\n\nDisse afvigerskabninger har underlige, andenverdenlige egenskaber. Selvom de er onde af natur, mener jeg, at noget godt kan komme ud af deres eksistens her i Kalimdør. Jeg tror, at deres huder vil være særligt nyttige i lædervarernes kunst.\n\nHvis du føler dig klar til opgaven, så vov dig ned i hulerne nedenunder og hent nogle afviger-huder."},
  [1487] = {n="Udryddelse af Afvigere", l="Ebru i Jammergrotterne vil have dig til at dræbe 7 Afviger-hærgere, 7 Afviger-hugorme, 7 Afviger-traver og 7 Afviger-rædselshugtænder.", d="Naralex havde et ædelt mål.\n\nVores store leder stræbte efter at træde ind i Den Smaragdgrønne Drøm og hjælpe med at gendanne disse barske lande til den frodige skov, de engang var. Men noget gik frygteligt galt.\n\nNaralex' drøm forvandlede sig til et mareridt, og fordærvede skabninger begyndte at bebo hulerne.\n\nMens nogle af Naralex' disciple ønsker at vække vores mester, er min bekymring at rydde disse huler for de onde udyr.\n\nVov dig ind i hulerne, <Name>, og udryd afvigerafkommet."},
  [1489] = {n="Hamuul Runetotem", l="Tal med Hamuul Runetotem", d="Skallerne, du bragte mig, har en forurening, en jeg aldrig har set før. Jeg er sikker på, at vandet i Oasen er årsagen, og jeg kan fornemme den forvirring, de skaber i dette land. Det er, som om landet drømmer og ikke kan vågne.\n\nJammergrotterne må være kilden til forureningen. Men før du går derhen, så tal med Hamuul Runetotem, den ældre druide. Jeg sendte ham besked om hændelserne i Ødemarken. Han er klog og kan give dig råd.\n\nDu finder ham i Tordenklippe, på Ældrehøjen."},
  [1490] = {n="Nara Vildmanke", l="Tal med Nara Vildmanke.", d="Jeg trådte ind i drømmenes land og drømte om en kult af druider, der bor i Jammergrotterne. Jeg så, at deres mål engang var ædle, men at de har mistet vejen. De er nu tjenere af forureningen, der sive ud over Ødemarken.\n\nJeg er gammel, og min styrke svigter. Jeg kunne ikke blive længe i det drømmende sted, og jeg ved kun lidt mere om de forurenede druider. Men Nara er ung, og hendes ånd er vild. Hun blev i drømmen, da jeg flygtede.\n\nTal med Nara. Hun er i teltet derovre."},
  [1491] = {n="Smarte Drikke", l="Bring 6 portioner Klagende Essens til Mebok Snurrefix i Skralleby.", d="Okay, så rovfuglehornene virkede ikke særlig godt. Men det er helt i orden--ingen blev rig ved første forsøg! Og desuden tror jeg, at jeg har fundet noget, der virker endnu bedre i mine smarte drikke!\n\nDer findes et stof kaldet Klagende Essens, og jeg tror, det er årsagen til de mærkelige planter og dyr i Ødemarken. Skaf mig noget, så prøver jeg det i min drik!\n\nJeg har hørt, at essensen samler sig i ektoplasmiske væsener i Jammergrotterne mod vest. Jagt disse væsener og saml essensen."},
  [1492] = {n="Havnemester Svimlig", l="Bring den Sikrede Kasse til Havnemester Svimlig i Skralleby.", d="Jeg må sende en kasse med eliksirer, reagenser og andre ting til mine forbindelser i den Gamle Verden. Jeg har kun lidt tid til at få dem bragt til havnen i Skralleby, og den sidste karavane er allerede taget af sted.\n\nHvis du kunne, så tag denne med til Havnemester Svimlig. Han vil sørge for, at den kommer med næste båd til Sortvandsbugten."},
  [1499] = {n="Ondskabsfulde Følgesvende", l="Tal med Zureetha Fjernblik.", d="Zureetha har sendt nybegyndere som dig for at hjælpe med at udtynde antallet af væsner i hulen nær det sted, hvor du kæmpede mod de ondskabsfulde følgesvende.\n\nJeg tror, det ville være godt for dig at få erfaring ved at hjælpe hende. Sørg for at fortælle hende, at du hjalp med imp-problemet, så har hun sikkert en belønning til dig."},
  [1501] = {n="Tomrummets Skabning", l="Hent Vergas Tavle til Gan'rul Blodøje i Orgrimgrad.", d="Så få hekser er tilbage... Vi risikerer meget, men risiciene er berettigede. Du må hurtigt nå modenhed i dine evner, hvis du skal være til nytte for Horden og krigshøvdingen.\n\nDet er tid til, at du lærer en ny kaldelsesbesværgelse.\n\nFørst skal du hente Vergas Tavle, som blev stjålet af hekser fra Den Brændende Klinge og nu opbevares i deres tilflugt i Kranieklippen mod øst for byen. Med tavlen vil jeg vise dig de runer, der er nødvendige for at kalde en tomgænger."},
  [1510] = {n="Nyheder om Dogran", l="Tal med Ken'zigla ved Malaka'jin.", d="Han var stationeret i Taurajo-lejren, hvor vi har forsøgt at luge ud i piggrisene. Han førte nogle soldater til en af deres lejre, hvor han blev hårdt såret. De andre slap tilbage og forsøgte at redde ham. Han var i dårlig form, hans sår var betændt, så de var bange for at flytte ham uden først at have forbundet ham.\n\nDe sendte et budskab hertil og bad om en helbredende drik fra trolde ved Malaka'jin, ved foden af Stenklippe-bjergene. Vi sendte nogen for at hente den, men de er ikke vendt tilbage endnu."},
  [1511] = {n="Ken'zigla-eliksiret", l="Bring Ken'zigla-eliksiret til Grunt Tømmerstok i Taurajo-lejren.", d="Jeg regnede med, at der kunne komme en mere for at hente eliksiret, så jeg forberedte det alligevel.\n\nVærsgo, <Name>. Husk på, at du kun må give ham halvdelen! Det giver ham nok styrke til at bevæge sig uden at blø sig tør. Vent en nat, og giv ham så den anden halvdel.\n\nNå, under alle omstændigheder skal du tage det her med til Tømmerstok i Taurajo-lejren. Ifølge det, den første fortalte mig, burde han have en idé om, hvor denne Dogran befinder sig."},
  [1525] = {n="Ildens Kald", l="Bring 1 Ildtjære og 1 Ingrediens-pung til Telf Glødsen i Durdotar.", d="Men du kom ikke hertil for at høre en historietime, vel? Du kom for den Evige Flamme og ildtotemet.\n\nDet første skridt er at skabe en sapta og binde dig til flammen.\n\nJeg kan lave ildsaptaen til dig, hvis du bringer mig to ting. Den første er ildtjære, et simpelt stof, som regel medbragt af barbermanke-tryllekunstnere i de østlige Ødemarker.\n\nDen anden ting bliver farligere: en ingrediens-pung fra en af Brændende Klinge-kultisterne. Du finder dem i en hule over kløfterne nordøst for Barberbakken."},
  [1530] = {n="Vandets Kald", l="Find Saltlage i Sydlige Ødemarker.", d="Hvis der er én lektie, du skal lære om vand, er det denne: vand betyder genfødsel.\n\nDets kraft flyder, eroderer og renser alle slags ting. Du vil finde dets evne til at hele og genopbygge uovertruffen, men kun når det er rent.\n\nNår du forstår, at vand, når det er forurenet, kan ødelægge alt, det rører ved, vil du værdsætte, hvor vigtig en ressource det er.\n\nHvis du vil have vandsaptaen, så find Saltlage dybt i Sydlige Ødemarker. Hendes hjem bliver konstant plaget af piggrisene dernede."},
  [1534] = {n="Vandets Kald", l="Fyld den tomme blå vandskind ved Stjernestøvs Ruiner i Askedalen og vend tilbage til Saltlage i Ødemarken.", d="Tag denne vandskind og træng dybt ind i den frodige skov, som nattealferne kalder Askedalen. Den ligger langt mod nord for Ødemarken.\n\nNår du er kommet ind i skoven, så rejs mod vest. Langs bjergene, der adskiller Stenklippe og Askedalen, og forbi Mystral-søen, finder du et helligt sted: Stjernestøvs Ruiner. Midt i søen finder du en lille fontæne.\n\nBring mig en prøve af fontænens vand. Det bliver den sidste ingrediens, du skal bruge, før jeg sender dig tilbage til Isleif."},
  [1536] = {n="Vandets Kald", l="Fyld den tomme røde vandskind ved brønden i Tarrenmølle og vend tilbage til Saltlage i Ødemarken.", d="For længe siden fulgte jeg nogle kammerater ind i Hillsbrad-forbjergene. Vi forsvarede os mod nogle seje mennesker, der har deres hjem der, og vi endte i en lille by, De Forladte havde overtaget: Tarrenmølle.\n\nDer fandt jeg en meget besynderlig ting: midt i byen var en lille brønd med friskt kildevand. Jeg er ikke sikker på, at de pestramte byfolk overhovedet forstår dens værdi – det er en lille hellig rest i et uhelligt hav.\n\nBring mig en prøve af det vand i denne vandskind."},
  [1578] = {n="Forsyninger til Fronten", l="Bring 6 Kobberøkser og 6 Kobberkædebælter til Torvald i det sydlige vagttårn i Modansøen", d="Bjergbestigerne i Modansøen kæmper mod troggerne, og de har travlt! De har brug for konstant forsyning af nye rustninger og våben, hvis vi nogensinde skal få styr på de troggers.\n\nDerfor er min kollega Torvald der og prøver at holde bjergbestigerne i godt udstyr. Så hvis du laver nogle kobberøkser og kobberkædebælter og bringer dem til Torvald, ville han være taknemmelig. Han deler måske endda sin viden med dig.\n\nTorvald er i Modansøens sydlige vagttårn."},
  [1579] = {n="Gaffer-dimser", l="Bring 8 Gaffer-dimser til Vidunderbang Krankstøj i Auberdin.", d="Jeg kom til Auberdin på grund af roen. Jeg vil opfinde mine opfindelser et sted, hvor det er stille, for efter en nat med druk kan jeg ikke lide al larmen i Jernsmede!\n\nSå jeg tog et skib til Auberdin og fik lidt for meget at drikke undervejs. Jeg tabte min kasse med gaffer-dimser over bord! Jeg har brug for mine gaffer-dimser!\n\nJeg ved ikke præcist, hvor jeg tabte dem, men hvis du fisker efter dem i havet, er du måske heldig..."},
  [1580] = {n="Elektropropellere", l="Bring 12 Elektropropellere til Vidunderbang Krankstøj i Auberdin.", d="Vi ved, du er heldig, men... hvor heldig er du egentlig, <Name>?\n\nEn nat vandrede jeg rundt på vejene i Mørkekysten. Jeg ledte efter en god flod eller sø, hvor jeg kunne prøve min nye selvdrevne, eksploderende andelokkeand, og jeg var nok en lille smule beruset... for jeg besvimede og vågnede timer senere i Auberdin. Mit hår var svedet, og min pose med elektropropeller var væk! Jeg må have tabt dem i vandet!\n\nJeg har brug for de elektropropeller! Måske kan du fiske dem op fra en sø eller et vandløb i Mørkekysten..."},
  [1581] = {n="Eliksirer til Klingebladene", l="Bring 6 Løvestyrke-eliksirer og 2 Mindre Forsvars-eliksirer til Syral Klingeblad i Dolanår.", d="Vores urte- og alkymiforretning går strygende, men min mand bruger så meget tid på at blande eliksirer, at vi aldrig har tid til hinanden.\n\nKan du hjælpe os?\n\nHvis du kan bringe mig en forsyning af færdiglavede eliksirer, så vil jeg gerne handle med dig. Jeg har nogle sjældne urter, som du måske finder nyttige."},
  [1582] = {n="Månelysvest", l="Bring 1 Præget Læderhandske, 5 Præget Læderstøvler og 5 Præget Læderkapper til Lotherias i Darnassos.", d="Vi i Darnassos, især vi håndværkere, har travlt. Unge eventyrere er ivrige efter at prøve sig selv i vildmarken og har konstant brug for forsyninger.\n\nHvis du kan hjælpe mig med at opfylde mine ordrer på lædervarer, så kan jeg måske lære dig en avanceret lædersmedeteknik."},
  [1598] = {n="Den Stjålne Tome", l="Hent Tomhedens Kræfter for Drusilla Den Salte.", d="Dig dér! <Name>, ikke sandt?\n\nJeg håber, du er sikker på, at du vil være hekser, for hvis du ikke kan holde dig selv oppe, er du sandsynligvis ved at blive trukket ned.\n\nJeg skal nok lære dig det, men jeg skal sikre mig, at du er stærk nok først.\n\nDer var en novice, der studerede på klosteret, som stak af for at slutte sig til Defias-broderskabet. Hvorfor skulle jeg bekymre mig? Jo, han stjal nogle vigtige bøger.\n\nÉn af dem er en bog, jeg selv har ønsket mig: Tomhedens Kræfter. Stjæl den til mig, de har den gemt i deres telt i vingårdene."},
  [1618] = {n="Udrustning til Rødryg", l="Tormus Dybsmedje vil have dig til at bringe 4 Runemærkede Kobberbælter og 4 Tunge Kobberstødhammere til Verner Osgod i Rødryg.", d="Vi dværge er ikke de eneste, der kæmper. Vores menneskelige allierede har også fulde hænder!\n\nRødryg bliver jævnligt angrebet af sortstens-orker, og deres udstyrsforsyning er altid lav. Hvis du hjælper dem, er jeg sikker på, at deres lokale smed, Verner Osgod, ville lære dig et trick eller to."},
  [1638] = {n="En Krigers Træning", l="Tal med Harry Bulvagt.", d="Du har vist dig at være en dygtig kriger, <Name>. Men du er stadig ung og har meget at lære.\n\nTal med Harry Bulvagt – han er som regel på Gris og Fløjte-kroen i Gamlebyen i Stormvind. Harry er en gammel veteran og en god lærer. Han kan vise dig et par træk, der holder dig i live længere."},
  [1639] = {n="Bartleby Bajer den Fulde", l="Tal med Bartleby Bajer.", d="Ja, jeg kan lære dig det. Men først vil jeg se, hvilke træk du allerede har.\n\nSer du den fulde dér for enden af baren? Bartleby Bajer? Jeg vil have dig til at få fat i hans krus.\n\nHa, og hvis du kender Bartleby Bajer, så ved du, at han ikke bare giver det fra sig."},
  [1640] = {n="Tæv Bartleby Bajer", l="Tæv Bartleby Bajer, og tal derefter med ham.", d="Hvad vil du have?? Du er sindssyg!\n\nDen eneste måde, du får det krus på, er, hvis du pirker det ud af mine kolde, døde fingre..."},
  [1645] = {n="Guddommelighedens Tome"},
  [1646] = {n="Guddommelighedens Tome", l="Tal med Tiza Kampsmed i Jernsmede.", d="I alt skal en paladin afspejle Lyset, som styrker vores kraft. At stræbe efter at være guddommelig for en af vores art betyder ikke, at vi stræber efter gudommelighed – vi stræber efter at være gode i alle vores handlinger.\n\nSelvom vi i disse hårde tider kaldes til at slå det onde ned, skal du altid huske, at det er at hjælpe andre, der virkelig adskiller dig fra borgerne i Azeroth. Medfølelse, tålmodighed, mod – disse ting betyder lige så meget for en paladin som styrke i kamp.\n\nHusk det godt, og glem det aldrig."},
  [1647] = {n="Guddommelighedens Tome", l="Søg den ydre ring af Jernsmede efter John Tørner.", d="Din opgave, <Name>, er så at finde nogen her i Jernsmede, der har brug for hjælp. Nogen, der er ren af hjerte og hensigt. Måske nogen, der hjælper andre. Måske nogen, der har brug for en vejleder. Uanset hvad skal personen have ædle hensigter og være afhængig af din venlighed.\n\nGør det, og vend tilbage til mig, når du er færdig. Så taler vi videre om din vej, og hvad det betyder at være en paladin i Lyset. Jeg bliver her i templet, til du vender tilbage. Andre paladiner har også brug for min vejledning."},
  [1648] = {n="Guddommelighedens Tome", l="Bring 10 Linnedstof til John Tørner i Jernsmede.", d="Min kone og jeg driver et børnehjem i Stormvind, mest for børn, der har mistet forældre på grund af Svøbens angreb i det seneste årti. Jeg kommer til Jernsmede cirka hver måned for at samle flere forsyninger ind fra borgerne her og tale med de forskellige grupper for at se, om de kan gøre noget for at hjælpe.\n\nDenne tur har været pinefuldt langsom og ikke særlig produktiv.\n\nHvis jeg bare kunne få noget mere linned, så min kone kunne sy noget tøj, kunne jeg endelig sende en forsendelse hjem."},
  [1650] = {n="Tapperhedens Tome", l="Find Daphne Stilvæg i Vestfald.", d="Godt! Din manglende tøven er et sikkert tegn på, at du er klar og ivrig efter at teste dig selv. Så være det.\n\nLængst ude ved Vestfalds Langkyst står et lille hus og kigger ud over havet. Der bor et par, Stilvægerne. Jordan er en utrolig smed, og han er taget til Jernsmede for at mødes med dværgene en tid. Men det har efterladt Daphne, hans kone, alene og ubeskyttet.\n\nRapporter tyder på, at Defias næsten har overtaget området, og Daphne har måske brug for beskyttelse mod skurkene. Tag derhen."},
  [1654] = {n="Retfærdighedens Prøve", l="Brug Jordans Våbennoter til at finde noget Hvidstens-egetræ, Bailors Raffinerede Malmlast, Jordans Smedehammer og en Kor-ædelsten, og bring dem til Jordan Stilvæg i Jernsmede.", d="Jeg vil gerne belønne dig, hvis du ville acceptere sådan noget? Misforstå mig ikke, min generøsitet afhænger af, hvor meget hjælp du kan være, men jeg ser os begge drage stor nytte af sådan en alliance.\n\nJeg vil smede et våben til dig, der er værdigt til det, du har opnået, et symbol på paladinskab og Lyset, men du skal samle de ting, jeg har brug for, for at smede det. Jeg har allerede begyndt at notere ned om emnerne, det kræver bare nogen modige og dygtige nok til at hente dem. Hvad siger du, <Class>?"},
  [1655] = {n="Bailors Malmlast", l="Bring Jordans Malmlast til Bailor Stenhånd i Modansøen.", d="Av, du gav mig et chok, mand/kvinde! Kan du ikke se, at jeg var fortabt i tanker?\n\nHvad siger du? Jordans forsendelse... til Jernsmede. Åh, ja, nu ved jeg, hvad du taler om. Mo'grosh-ogre... det er dem, der tog min gamle vens malmlast. Karavanen var på vej herhen fra Vådlandene og blev overfaldet. Vagten, der overlevede angrebet, døde for et par dage siden – healeren kunne ikke nå frem til ham hurtigt nok.\n\nHvis du vil have forsendelsen, må du tage nordøst over søen. Den må være der et sted."},
  [1656] = {n="En Opgave Uden Afslutning", l="Bring Bundt Pelse til Kroværten Kauth i Blodhov-landsbyen.", d="<Name>, vær sød, jeg beder dig, kan du hjælpe mig? Jeg har ikke afsluttet mine opgaver her på højlandet – jeg er midt i mit Styrkens Ritual – og min far bad mig om at levere disse pelse til kroen i Blodhov.\n\nJeg er langt fra udhvilet nok til at fuldføre både mit ritual og denne opgave for min far. Ville du have noget imod at tage afsted i mit sted?\n\nKroen er behagelig og et perfekt sted at hvile under dine lange rejser. Jeg er sikker på, at du vil være enig, når du ser den."},
  [1665] = {n="Bartleby Bajers Krus", l="Bring Bartleby Bajers Krus til Bulvagt", d="Ok, her er mit krus. Vent! Lad mig først drikke det, der er i det... der var den."},
  [1666] = {n="Marskal Udmattet", l="Tal med Marskal Udmattet.", d="Du har lært nogle træk, men du kunne stadig bruge et ordentligt våben. Jeg vædder på, at hvis du talte med Marskal Udmattet, kunne han hjælpe dig.\n\nMarskal Udmattet bor i en herregård i Elwynnskoven, ved Østdal Tømmerlejr. Han er gået på pension nu, men han samlede en masse udstyr gennem sin karriere.\n\nLad ham vide, at jeg sendte dig, og med lidt held har han måske et ekstra våben at tilbyde."},
  [1667] = {n="Døde-tand-Jack", l="Hent Marskal Udmattets mærke fra Døde-tand-Jacks lejr, og vend tilbage til Marskal Udmattet.", d="Bulvagt sendte dig, gjorde han? Jo, jeg har reservevåben rundt omkring her, men først har jeg en opgave til dig...\n\nFor et stykke tid siden blev jeg snydt af en Defias-skurk, Døde-tand-Jack. Det var mørkt, og han bar en Stormvind-tunika, så jeg troede, han var Marskal Dughan. Han sagde, at han havde brug for mit gamle Stormvind-marskalmærke, og jeg gav det til ham... og så lo han og løb væk, før jeg kunne nå at fange ham!\n\nFå mit mærke tilbage! Døde-tand-Jack har sikkert gemt det i sin lejr mod syd."},
  [1681] = {n="Jernbånds Anlæg", l="Bring en last Skyggemalm til Tormus Dybsmedje i Jernsmede.", d="Min mentor, Sturgy Jernbånd, havde et anlæg syd for Helms Seng-søen i det østlige Dun Frostbakke. Der lærte han smedekunst, og han var den bedste.\n\nMen en dag bragte en af hans elever ham en last mærkelig malm. Mester Jernbånd kaldte det skyggemalm og var ivrig efter at arbejde med den, men kort efter den var ankommet... angreb en flok Mørkjernsdværge hans anlæg. De dræbte alle!\n\nTræd ind i Jernbånds anlæg, <Name>, og hævn min mesters død. Og bring mig den last skyggemalm, der forårsagede det."},
  [1685] = {n="Gakins Tilkaldelse", l="Mød op hos Gakin Mørkbinderen i Stormvinds Magikerkvarter.", d="Er det ikke altid sådan? Har ledt efter dig hele dagen uden at finde dig, og nu, når jeg ikke venter det, kommer du og går lige hen til mig.\n\nJeg har spildt nok tid på at lede efter dig, så jeg forsinker dig ikke længere. Mester Gakin har kaldt dig til yderligere træning. Det forekommer mig, at du bør opsøge ham så hurtigt som muligt.\n\nDu finder ham i kælderen under kroen Det Slagtede Lam. Og forresten, du vil nok holde den bestemte placering hemmelig. Vi vil ikke have, at det spreder sig."},
  [1688] = {n="Surena Kaledonsen", l="Hent Surenas halsbånd til Gakin Mørkbinderen i Stormvind.", d="Jeg havde en elev ved navn Surena Kaledonsen. Hun stod, hvor du står nu, ivrig efter at lære om hekselmagi, og med ikke ringe talent. Mere end det var hun ung og tiltalende at se på. Havde jeg set det dengang, den forræderske tøs!\n\nDen tyveagtige kvinde løb væk med en af Defias, Erlan Trælmose. Selvom hendes tab er af ringe betydning, skænkede jeg hende et blodsten-halsbånd, som jeg må have tilbage.\n\nHendes liv betyder intet for mig nu. Du finder hende ved Brackvolds Græskarplads. Hent det, der er mit."},
  [1689] = {n="Bindingen", l="Brug Blodsten-halsbåndet til at fremkalde og tæmme en tomrumsvandrer, og bring derefter Blodsten-halsbåndet tilbage til Gakin Mørkbinderen i Stormvind.", d="Ved at hente mit halsbånd og besejre Surena har du bevist, at du i det mindste er lige så dygtig, som hun var.\n\nIkke desto mindre kan jeg se, at du har desperat brug for træning. Du kan styre magiens strømme, ja, men at være hekseri-mester er langt mere end det.\n\nJeg vil vise dig, hvordan man befaler en tomrumsvandrer, men før jeg kan, skal du fremkalde en ved en fremkaldelsescirkel og tæmme den med de våben, du har til rådighed—både fysiske og magiske. Brug dette halsbånds magi ved fremkaldelsescirklen nedenfor."},
  [1701] = {n="Ildhærdet Ringbrynje", l="Saml de materialer, Furen Langskæg kræver, og bring dem til ham i Stormvind.", d="Så jeg gav dig et fint skjold, men vi behøver ikke stoppe der. Jeg kender hemmelighederne bag at smede ekstremt hård ringbrynje. Det er ikke let, og det kræver meget sjældne materialer, men hvis du er villig til at gå op og ned ad landevejen, så laver jeg et stykke til dig.\n\nHvad siger du, <Name>? Hvis du er med på udfordringen, så giver jeg dig en liste over, hvad du skal skaffe, og hvor du finder det."},
  [1712] = {n="Cyklonianeren", l="Bring de genstande, der står på Bath'rahs pergament, til Bath'rah Vindvogteren i Alterac.", d="Jeg har brugt evigheder på at holde øje med dette sted. Jeg holder øje, så jeg en dag måske kan se den store Cyklonianeren falde. Men jeg har endnu ikke fundet en mester, der kan besejre vindherren.\n\nMåske er du den mester.\n\nBevis det for mig. Saml de ting, jeg har brug for for at fremkalde Cyklonianeren, så ved jeg, at du er en stor kriger. Måske kan du så besejre ham og vinde hans hvirvelvind-hjerte.\n\nHvis det lykkes, vil jeg indgyde hjertets kraft i et våben, og jeg giver dig det våben.\n\nHer er et pergament med de ting, jeg har brug for."},
  [1716] = {n="Sjælenes Ødelægger", l="Tal med Takar Synskeren i Ødemarken.", d="En sayaad er en sjæleædende, viljebeherskende og hjertebedrager. Den kender intet andet end ondskab.\n\nLasterlige fortællinger omtaler dæmonen ved dens almindelige navn: succubus for hunner, incubus for hanner.\n\nDer kræves et stimulus for at kalde væsenet frem. Med et kærlighedssymbol som lokkemad vil det helt sikkert svare på dit kald. Besejr det, og gør det til dit redskab.\n\nDet vil dog blive svært at finde en ting af denne art. Du bør tale med Takar Synskeren. Du finder ham i Ødemarken i Kalimdør nær Taurajo-lejren."},
  [1740] = {n="Soran'ruks Kugle", l="Find 3 Soran'ruk-fragmenter og 1 Stort Soran'ruk-fragment, og bring dem til Doan Karhan i Ødemarken.", d="Når dæmonerne fra Legionen falder i unåde, bliver deres ånder fængslet i kugler og fordelt til deres magikere og hekseri-mestre.\n\nMange blev båret af deres tjenere i Azeroth. Selv i stykker besidder de stadig dæmonernes kræfter, der er fanget indeni.\n\nSoran'ruks kugle blev knust i to stykker. Det ene blev knust yderligere for at blive brugt af Tusmørkets Hammers akolytter i Den Sorte Afgrund. Det andet, større stykke var i besiddelse af en troldmand i Skyggetandsborgen. Find dem, så kan jeg samle den igen."},
  [1778] = {n="Guddommelighedens Tome", l="Tal med Tiza Kampsmed i Jernsmede.", d="Jeg vil se til, om jeg kan lægge planer for at vende hjem snart. Forhåbentlig har Stefanie det godt tilbage i Stormvind. Jeg kan ikke vente med at se hende igen. Til vi mødes igen, <Class>."},
  [1779] = {n="Guddommelighedens Tome", l="Tag Livets Symbol og tal med Muiredon Kampsmed i Jernsmede.", d="Jeg vil have dig til at tage dette, <Name>. Det kaldes Livets Symbol.\n\nDu har vist dig venlig og tålmodig, og nu vil jeg have dig til at bevise, hvor dygtig du er blevet, både i kamp og i kraft.\n\nMin mand Muiredon vendte for nylig tilbage fra et møde med nogle mørkjernsdværge, og han slap næsten med livet i behold—han er derovre og får heelet sine sår af en af vores præster.\n\nTag symbolet og tal med ham. Hvis du kan hjælpe ham, så taler vi snart sammen igen. Må Lyset skinne over dig."},
  [1783] = {n="Guddommelighedens Tome", l="Tag Livets Symbol og genopliv Narm Råddenfolk i Dun Frostbakke.", d="Vi var ude og spionerede på nogle af mørkjernsdværgene, som har gravet sig ned syd for Helms Seng-søen. Vi vidste, de var oppe på noget ondt, så Narm og jeg tænkte, vi kiggede lidt nærmere—fik set deres leder give ordrer til nogle af sine mænd.\n\nNarm og jeg tog chancen og dræbte et par af dem, men de viste sig at være hårdere, end vi troede, og flere af dem overrumplede os. Narm bad mig løbe og hente hjælp, så her er jeg.\n\nNarm har brug for hjælp, og jeg hviler ikke, før han får den.\n\nKan du hjælpe, <Name>?"},
  [1784] = {n="Guddommelighedens Tome", l="Hent et Mørkjern-skriftrulle fra mørkjernsdværgene nær Helms Seng, og vend tilbage til Muiredon Kampsmed i Jernsmede.", d="Før jeg faldt i kamp, havde Muiredon og jeg næsten besejret en af mørkjernsspionerne nær det lille hus. Vi så deres kaptajn give ordrer til dem, og vi ville dræbe ham og tage ordrerne.\n\nNogle af rådet i Jernsmede tror endnu ikke, at mørkjernsdværge overhovedet findes i Dun Frostbakke. Ved at skaffe os et af disse skriftruller har vi ikke blot bevis for deres bevægelser, men muligvis også en idé om, hvad de planlægger.\n\nFå et af skriftrullerne og tag det med tilbage til Muiredon, <Name>."},
  [1785] = {n="Guddommelighedens Tome", l="Tal med Tiza Kampsmed i Jernsmede.", d="Jeg kan se min kones derovre allerede stråle af stolthed. Du må hellere skynde dig derover med det samme. Jeg tror, hun har et par ord til dig.\n\nLyset være med dig, mægtige <Class>. Jeg vil holde øje med dig på slagmarken mod Svøben og de dér Mørkjernsdværgene, når tiden kommer."},
  [1787] = {n="Guddommelighedens Tome", l="Hent et Defias-skriftrulle fra Defias-magikerne i Elwynn, og vend tilbage til Gazin Tonelund i Stormvind.", d="Vi får tid til at tale mere om symbolet på et senere tidspunkt. Det vigtige lige nu er at få fat i de papirer, vi så Defias-folkene gennemgå. Hvis vi kan få fat i dem, kan vi bevise, at Defias har infiltreret Elwynn, og forhåbentlig få indsigt i, hvad deres planer er.\n\nJeg er ikke i form til kamp lige nu, <Name>. Tror du, du er stærk nok til at få de papirer fra Defias-folkene her på øen?\n\nHvis du kan få dem, så bring dem tilbage til Gazin og fortæl ham, at jeg har det godt."},
  [1791] = {n="Vindvogteren", l="Tal med Bath'rah Vindvogteren.", d="Nu hvor du har lært din berserkerholdning, vil du have brug for et godt våben at bruge den med.\n\nTal med Bath'rah Vindvogteren, en troldeeremit, der bor mellem Alterac-bjergene og de Vestlige Pestlande. Han er en dygtig våbensmed og en mægtig shaman.\n\nFor at finde Bath'rah skal du gå til floden, der løber langs Tarrenmølles østlige flanke. Følg den mod nord—Bath'rah har slået lejr nær ruiner, der ligger ved flodens østlige bred."},
  [1798] = {n="Jagten på Strahad", l="Tal med Strahad Farsøn i Ødemarken.", d="Det er på tide, at du lærer at fremkalde fel-jægeren, <Name>. Jeg har ikke de reagenser og genstande, der er nødvendige for at lære dig det her, så du må opsøge en anden, Strahad Farsøn, en anden af vores indre kreds.\n\nHan holder til i gobliner-havnen Skralleby. Jeg sender besked i forvejen for at fortælle ham om din ankomst."},
  [1801] = {n="Kabalens Tome", l="Tal med Jorah Årsen i Undergrunden.", d="Det vil kræve mere end en simpel fremkaldelsescirkel at manifestere en fel-jæger, som du kan udfordre.\n\nMine tre akolytter og jeg vil hjælpe med at skabe de magiske cirkler. Du har brug for en kopi af Kabalens Tome, som har været tabt for os i lang tid. Den blev skrevet af den første gruppe hekseri-mestre, der fremkaldte en fel-jæger uden hjælp.\n\nMåske kan Jorah Årsen hjælpe dig med dette. Han er ansat som kartograf i Undergrunden i disse dage, men kender stadig flere af de gamle tekster end nogen, jeg kender."},
  [1806] = {n="Retfærdighedens Prøve", l="Vent på, at Jordan Stilvæg bliver færdig med at smede et våben til dig.", d="Skal vi ikke gå over til smedjen og komme i gang med det her? Jeg har forberedt mig på din ankomst i lang tid, så det burde ikke tage lang tid.\n\nNår vi er færdige, vil du være langt bedre rustet til at forsvare Lyset, end du har været, det sværger jeg på.\n\nJeg vil være lidt ærlig, <Name>: At se resultaterne af dine bedrifter gør mig lidt misundelig. Men at vide, at jeg kan bidrage til dine eventyr på min egen betydningsfulde måde, giver mig en vis glæde."},
  [1823] = {n="Tal med Ruga", l="Tal med Ruga Vredetotem.", d="Du er en kriger med dygtighed og voksende ry. Måske er du klar til Ruga Vredetotems prøve? Hvis du er det, så find Ruga i Taurajo-lejren i Ødemarken.\n\nHan venter på de krigere, der besvarer hans kald."},
  [1838] = {n="Brutal rustning", l="Bring til Thun'grim Ildblik 15 røgfyldte jernbarrer, 10 pulveriseret azurit, 10 jernstænger og et Phlogiston-hætteglas.", d="Jeg har hørt historier om din styrke og tapperhed, og jeg ønsker at smede en rustning til dig, en ledsager, der kan hjælpe dig, mens historierne om dine store bedrifter vokser.\n\nMen fremstillingen af denne rustning bliver en quest i sig selv, <Name>. Jeg får brug for din hjælp og hjælp fra andre smede af Horden.\n\nSe, tag denne skriftrulle. Jeg brugte mange nætter på, med næsten blinde øjne, at skrive det, jeg har brug for til rustningen. Bring mig de ting, der står på denne skriftrulle, så laver jeg det første stykke af dragten til dig."},
  [1839] = {n="Ula'elek og de brutale handsker", l="Tal med Ula'elek i Durdotar.", d="Trolde-smeden Ula'elek vil smede de brutale handsker til dig. Han bor i Durdotar, i Sen'jin-landsbyen sammen med sine Mørkspyd-brødre, og han venter på din ankomst."},
  [1861] = {n="Spejlsøen", l="Bring en prøve af Spejlsøens vand til Jennea Kanon i Stormvind.", d="Denne verden har været offer for enorme mystiske kampe, som har revet magiske strømme væk fra engang stabile kanaler. Vi kæmper for at finde ud af, hvilke effekter disse forandringer har haft, og nogle af os frygter det værste!\n\nMen jeg vil afsløre mere om dette senere. Lige nu har vi brug for, at du indsamler information.\n\nVær så venlig, tag denne kolbe. Gå til foden af vandfaldet ved Spejlsøen, sydvest for Stormvinds porte, og hent en prøve af vandet der. Bring den til mig, så jeg kan teste den for magiske forureninger."},
  [1880] = {n="Magi-fantastisk Gizmonitor", l="Bring Binke hendes Magi-fantastiske Gizmonitor.", d="Vi magikere gør mere end bare at vifte med fingrene og lave flotte gnister! Vi kontrollerer magi, verdens grundlæggende stof! Og det kræver stor omhu og beslutsomhed. Og viden... så meget viden!\n\nEn af mine apparater, den magi-fantastiske gizmonitor, indsamler og lagrer den viden i enorme mængder! Men den er væk! Da vi flygtede fra vores hjem i Nisseborgen, efterlod jeg den i en kiste i en af vores hytter uden for byen, og nu vrimler stedet med spedalske gnomer!\n\nVær sød, <Name>, hent min gizmonitor!"},
  [1881] = {n="Tal med Anastasia", l="Tal med Anastasia Hjortekilde.", d="<Name>, Anastasia Hjortekilde har en opgave for en person med dine talenter. Tal med hende i Magikvarteret i Undergrunden, og gør dig klar til din første opgave for De Forladtes magikere."},
  [1882] = {n="Balnirs Gård", l="Bring Balnir-løvemunde til Anastasia Hjortekilde i Magikerkvarteret i Undergrunden.", d="Pestlandene mod øst er en afvigelse. Skabt af Liskekongen spreder de deres magi ned i jorden, korrumperer og dræber alt, der lever. Selvom der er en vis charme ved pestens ødelæggende kræfter, mener vi, magikerne fra De Forladte, at den er uregerlig og må stækkes.\n\nMen først må vi måle, hvor langt den har bredt sig ind i Tirisfal. Gå til Balnirs Gård i østlige Tirisfal. I haven er der blomster--løvemunde. Saml dem og vend tilbage."},
  [1883] = {n="Tal med Un'thuwa", l="Tal med Un'thuwa.", d="Un'thuwa, stammemagiker i Sen'jin-landsbyen, opdager en forstyrrelse i Durdotars magiske strømme og beder om hjælp. Tal med Un'thuwa og gør, hvad du kan, for at hjælpe ham.\n\nGør du det, vil flere hemmeligheder med tiden blive afsløret for dig."},
  [1885] = {n="Mennet Carkad", l="Tal med Mennet Carkad i Skurkekvarteret i Undergrunden.", d="<Name>? Ikke helt det, jeg havde forventet, i betragtning af at Carkad selv har fået øje på dig. Udseendet kan dog snyde, ikke sandt?\n\nUanset hvad, bør du opsøge ham så hurtigt som muligt. Du vil ikke vide, hvad der skete med de sidste par, der valgte at ignorere hans kald."},
  [1886] = {n="Dødsstalkere", l="Hent Astors Introduktionsbrev og bring det tilbage til Mennet Carkad i Skurkekvarteret.", d="Hvis du ønsker at slutte dig til Dødsstalkerne, Lord Varimatras' elitegarde, må du bevise din værdi.\n\nJeg vil ikke lyve for dig, <Name>. Denne opgave kan betyde din død.\n\nJeg har nogle ting, der skal tages hånd om. Jeg har brug for de personlige ejendele fra Astor Hadren, en budbringer, der rejser mellem Sølvfyrreskoven og Undergrunden. Jeg overlader valget af fremgangsmåde til dig.\n\nDet vil være bedst for dig, hvis du ved mindre om denne forretnings art. Lykkes du, vil jeg fortælle dig mere."},
  [1918] = {n="Det Forurenede Element", l="Bring den Forurenede Vandkugle til Mastok Snirkelsnor ved Splintertræ-Posten i Askedalen.", d="Det dræbte element har frembragt en intenst lysende vandkugle. Indholdet af kuglen er i bedste fald ækelt. Det er rimeligt at antage, at det, der har forurenet vandet i Mystral-søen, højst sandsynligt også findes i vandet i kuglen.\n\nDet er ikke ligefrem almindelig viden, hvem der kunne være interesseret i sådan et fund; måske kan personen, der oprindeligt sendte dig ud til søen, Mastok Snirkelsnor ved Splintertræ-Posten, have en idé."},
  [1919] = {n="Rapportér til Jennea", l="Tal med Jennea Kanon i Stormvind.", d="Din viden om håndværket vokser, unge <Name>. Er du nu klar til at begynde dine sande lektioner? Er du klar til at tage din plads i den hemmelige krig, vi fører?\n\nHvis ja, så tal med Jennea Kanon i troldmandens helligdom i magikerdistriktet i Stormvind. Hun har en opgave til dig, som vil åbne dit første vindue ind i den usynlige verden."},
  [1920] = {n="Undersøg Den Blå Eneboer", l="Hent en Manifestationsbesværgelse og en Kiste med Indespærringskister bag Jennea Kanon. Bring 3 Fyldte Indespærringskister til Jennea i Troldmandens Helligdom.", d="Der er blevet meldt om en forstyrrelse i kroen Den Blå Eneboer i Magikerkvarteret. Mærkelige, usynlige skabninger vandrer nu rundt i kroen, og jeg frygter, at der er dannet en manarift derinde.\n\nJeg vil have dig til at undersøge kroen og fange disse skabninger. Brug manifestationsbesværgelsen i kroen for at gøre skabningerne synlige, underkuv dem og brug derefter en indespærringskiste til at fange dem. Når du har nok, skal du vende tilbage til mig med dine fyldte kister, dine tomme kister og besværgelsen."},
  [1921] = {n="Indsamling af Materialer", l="Bring 10 Linned og de 6 Ladede Rift-ædelsten til Wynne Larson i Stormvind.", d="Du har tjent dine medmagikere godt, og nu er det tid til at tage din troldmandskjole på. Wynne Larson kan lave din kjole, men du må bringe hende de nødvendige materialer\n\nKjolen skal laves af linned, som er let at finde, men du må også skaffe ladede rift-ædelsten, og det eneste kendte sted, hvor ædelstenene findes, er i Sølvstrøm-minen i Modansøen, efterladt i kasser af dværgenes minearbejderforbund.\n\nSaml linned og ædelstenene og bring dem til Wynne Larson hos Larson Klædehandel i Magikerdistriktet."},
  [1938] = {n="Urs Afhandling om Skyggemagi", l="Bring Urs Afhandling om Skyggemagi til Højsorcerer Andromath i Stormvind.", d="For længe siden studerede tre magikere i dette tårn, indtil en af dem faldt for de mørke kunster. Han blev opfordret til at vende sig væk fra den onde magi, men han kunne ikke modstå. Og så blev han forvist.\n\nDen faldne magikers nye domæne er Ilgalars Tårn i Rødryg, og han tog en mægtig bog med sig--Urs Afhandling om Skyggemagi.\n\nVi, magikerne i Stormvind, ønsker, at bogen bliver givet tilbage. Gå ind i Ilgalars Tårn, find tomen i hans bibliotek, og bring den til mig."},
  [1939] = {n="Højsorcerer Andromath", l="Tal med Højsorcerer Andromath.", d="Højsorcerer Andromath ønsker at tale med dig, <Name>. Han befinder sig øverst i troldmandens helligdom i magikerdistriktet i Stormvind.\n\nDet ville være klogt at tale med ham, for Andromath er en af de mest magtfulde magikere, der ikke er låst inde i Dalarn. Et råd med ham er i sandhed et højt råd."},
  [1940] = {n="Ubesmittet Edderkoppesilke", l="Bring 8 Ubesmittet Edderkoppesilke til Wynne Larson i Stormvind.", d="Din tjeneste har været urokkelig, <Name>. Jeg tror, måske, at det er tid, at du får en finere klædning, en der passer til din stand som dygtig magiker. Hvis du skaffer de nødvendige materialer, så sørger vi for, at kjolen bliver lavet.\n\nDu må tage til Skumringsskoven og jagte ådsels-eneboeredderkopper. Udtræk deres silke, men kun den fineste, mest ubesmittede silke duer. Når du har nok, skal du tage den til Wynne Larson her i magikerdistriktet hos Larson Klædehandel. Hun vil sy din kjole."},
  [1944] = {n="Xavians Vande", l="Bring Xavian-vandprøven til Deino i Orgrimgrad.", d="Den sagnomspundne by Xavian ligger gemt dybt i det østlige Askedalen, og fortællinger om dens gamle viden er velkendte blandt de lærde. Det siges, at Xavians vande rummer enorme magiske kræfter.\n\nJeg ønsker en prøve af vandet fra kilden.\n\nTag denne kolbe og gå til Xavian. Saml vand fra bunden af dens højeste vandfald, og vend tilbage til mig. Og vær forsigtig, når du bevæger dig gennem den gamle by--satyrerne holder nu ruinerne og bryder sig ikke om, at magikere roder i deres anliggender."},
  [1945] = {n="Latterlige Søstre", l="Bring 12 Latterlige Søstres Hår til Kil'hala på Korsvejen.", d="For dine tjenester har jeg arrangeret, at dine nye kjoler bliver lavet, forudsat at du kan skaffe de nødvendige materialer...\n\nTil disse kjoler må du vende tilbage til Askedalen for lokker af hår fra latterlige søstre--dryader, der samles nær Raynewood-tilflugtsstedet.\n\nNår du har deres hår, skal du bringe det til Kil'hala, en trolskrædder på Korsvejen i Ødemarken. Han vil forvente dig og vil sy dine kjoler."},
  [1947] = {n="Rejsen til Sumpen", l="Tal med Tabetha.", d="Nu er det tid for dig at fortjene din magikers stav. For at begynde denne opgave skal du tale med den menneskelige eneboer Tabetha i Støvsumpen. Du finder hendes hytte dybt i sumpen, vest for Theramøre.\n\nTal med hende, for hendes viden er enorm. Du vil finde Tabethas hytte vest for Theramøre og lige nord for Stenknusernes Ruiner."},
  [1948] = {n="Kraftens Genstande", l="Bring 1 Jade og den Lynladede Brombær til Tabetha i Støvsumpen.", d="At bygge en magikers stav er ikke let. Sjældne stoffer er påkrævet, og et kar skal fremstilles, som kan opbevare store mængder magisk energi. Du må skaffe disse ting og bringe dem til mig.\n\nJeg har skrevet på dette pergament, hvad du har brug for, og anvisninger til, hvordan du får det. Bring mig præcis det, der står på listen, og følg mine skrevne anvisninger til punkt og prikke, for hvis du ikke gør det, kan det gå... galt, når vi laver din stav."},
  [1949] = {n="Skjulte Hemmeligheder", l="Tal med Magus Tirth i Glimmerflatene.", d="For at lave din stav er der nøglepassager i en bestemt bog, som jeg må læse. Bogen hedder Kræfternes Riter, skrevet af Magus Tirth.\n\nJeg har ikke et eksemplar af hans bog, og ingen af verdens store biblioteker besidder den. Så du må tale med Tirth og få den af ham.\n\nHeld og lykke. Tirth plejede at være en stor magiker og lærd, men nu bruger han sin tid på gnom- og goblinløbene i Glimmerflatene, drikkende og spillende."},
  [1951] = {n="Kræfternes Riter", l="Bring bogen Kræfternes Riter til Tabetha i Støvsumpen.", d="Hm... nu hvor jeg tænker over det, har jeg ikke min bog! Du ser, jeg havde nogle spillegæld, og for at betale dem af solgte jeg det sidste eksemplar af Kræfternes Riter til en gejstlig....\n\nEt medlem af Det Skarlagenrøde Broderskab. Han må have taget den med til deres bibliotek i Det Skarlagenrøde Kloster i Tirisfals Lysninger!\n\nHvis du vil have den bog, må du tage til klostret for at finde den. Og undskyld alt besværet. Jeg er ikke mig selv for tiden..."},
  [1960] = {n="Undersøg Alkymistbutikken", l="Hent en Manifestationsbesværgelse og en Kiste med Indespærringskister bag Anastasia Hjortekilde. Bring 3 Fyldte Indespærringskister, Kisten med Indespærringskister og Manifestationsbesværgelsen til Anastasia i Undergrunden.", d="Algernons alkymistbutik i Apotekerium er centrum for en mærkelig forstyrrelse. Usynlige skabninger, lavet udelukkende af magi, vandrer rundt i butikken--der må være en grund, og vi må finde den!\n\nUndersøg forstyrrelsen og fang disse skabninger. Tag en kiste med kister og en rulle bag mig. Brug rullen i butikken for at gøre skabningerne synlige, underkuv dem med dine besværgelser, og kast så en kiste ned for at fange dem. Vend tilbage med de fyldte kister, de tomme kister og besværgelsen."},
  [1961] = {n="Indsamling af Materialer", l="Bring 10 Linned og 6 Dalarn-manaædelsten til Josef Gregorian.", d="Det er tid for dig at tage din første magikerkjole på, <Name>. Den er et tegn på din stand og et vidnesbyrd om din værdi.\n\nFor at få kjolen skal du indsamle manaædelstenene fra Dalarn-magikerne i Sølvfyrreskoven. Deres overbevisninger ligner vores, så det er noget ubehageligt at dræbe dem, men hvis de mangler styrken til at modstå os, så fortjener de ikke deres liv.\n\nBring ædelstenene og en forsyning linned til Josef Gregorian i Magikvarterets skrædderbutik."},
  [1998] = {n="Fenwick Thatros", l="Dræb Fenwick Thatros og bring hans hoved tilbage til Mennet Carkad i Skurkekvarteret i Undergrunden.", d="Lord Varimatras har lige sendt mig en skrivelse om en trussel mod De Forladte, som straks må fjernes. Hans navn er Fenwick Thatros, en mand, som Lord Varimatras mener er leder af de udøde, der har slået rod i Sølvfyrreskoven.\n\nDit navn faldt mig straks ind, <Name>. Jeg har tilstrækkelig tro på dine evner til, at du vil udføre denne mission fejlfrit.\n\nDe seneste rapporter fra Dødsstalkerne i Sølvfyrreskoven tyder på, at Thatros kan findes nær den forfaldne mole ved Lordamere-søen."},
  [2038] = {n="Bingles' Savnede Forsyninger", l="Find og bring Bingles' forsyninger:\n\nBingles' Skruenøgle, Bingles' Skruetrækker, Bingles' Hammer og Bingles' Sprængkapsel.", d="Som om det ikke var slemt nok at styrte ned i søen, angreb troggs fra den nærliggende ø og stjal mine værktøjer og mine specielle Blastenheimer-sprængkapsler. Uden gyrokopter og uden sprængstoffer har bevægelsen ingen chance!\n\nFå mine værktøjer tilbage og find mine Blastenheimer-sprængkapsler, <Name>. For Nisseborgen!"},
  [2039] = {n="Find Bingles", l="Find Bingles Blastenheimer i Modansøen.", d="Vi har mistet kontakten til Bingles! Han blev sendt på en spionagemission over Nisseborgen og har ikke meldt tilbage i over en uge. Jeg ved bare, at han er gået ud i luften og er sprunget i luften.\n\nHan blev sidst set flyve over søen. Måske kan du undersøge sagen, <Name>."},
  [2040] = {n="Underjordisk Angreb", l="Hent Gnoam Sprækkekædehjulet fra Dødsminerne og bring det tilbage til Shoni den Tavse i Stormvind.", d="Nisseborgen er faldet under kontrol af de nederdrægtige troggs! Situationen er alvorlig, men måske kan du hjælpe, <Name>.\n\nDybt i Dødsminerne findes en funktionsdygtig goblin-makulator. Find makulatoren og bring den intakte strømforsyning tilbage. Med makulatorens strømforsyning kan vi give vores gyroboremaskine-udgravere den kraft, de behøver, for at bryde gennem Nisseborgens stenede underjordiske grænser og åbne vejen for et gnomisk angreb!"},
  [2041] = {n="Tal med Shoni", l="Tal med Shoni den Tavse i Stormvind.", d="Måske... Måske kan du hjælpe os i kampen om Nisseborgen.\n\nI Stormvind vil du finde chefen for vores underjordiske angrebsmandskab, Shoni den Tavse. Shoni har brug for hjælp med sine gyroboremaskine-udgravere.\n\nDu vil nok finde hende blandt dværgene i Stormvind.\n\nHeld og lykke, <Name>."},
  [2078] = {n="Gyromasts Hævn", l="Find Gelkaks Førstestyrmand, Threshwackonator 4100, og før den tilbage til Gelkak.", d="Landkrabbe, ye skal finde me førstestyrmand.\n\nTag denne'n nøgle, sæt'n i hans gulliver an' bring 'an tilbage hertil for at tjene Kaptajnen.\n\nDem murlocs an' deres høvding bliver ikke for glade, når me førstestyrmand får fat i dem!"},
  [2098] = {n="Gyromasts Hentning", l="Find og bring de tre dele af Gelkaks Nøgle tilbage til Gelkak Gyromast.", d="En pirats liv er ikke let, landkrabbe. Det handler ikke kun om plyndring og brændevin! Ak, mit skib er sunket lige uden for kysten på grund af de irriterende Tærskeldyr.\n\nDet, jeg har brug for, er at min førstestyrmand kommer i gang igen!\n\nDa jeg skyllede i land, gik nøglen til min førstestyrmand itu på klipperne, og den blev stjålet af Mørkekystens bæster. Ud af øjenkrogen så jeg nogle af de Rasende Krybere, den Voldsomme Skovgænger og en murloc rode rundt i vraget...."},
  [2138] = {n="Udrensning af de Smittede", l="Udrens skoven for 20 Rasende Tistelbjørne og vend tilbage til Tharnariun Træpasser i Mørkekysten.", d="Som jeg frygtede, virker kuren ikke.\n\nDet gør mig meget ondt at beordre døden af nogen af naturens dyr, men de syge og besmittede tistelbjørne må lægges i graven.\n\nVend tilbage til skoven og ødelæg 20 rasende tistelbjørne, <Name>. Det vil bestemt ikke stoppe pesten, men det vil bremse den skade, dyrene gør på vores skov og dens indbyggere i en kort tid."},
  [2158] = {n="Hvile og Afslapning", l="Tal med Kroværten Farley i Løvens Stolthed Kro.", d="Enhver eventyrer bør hvile sig, når udmattelsen sætter ind - og der findes ingen bedre sted at få hvile og afslapning end i Løvens Stolthed Kro!\n\nMin bedste ven, Kroværten Farley, driver Løvens Stolthed. Hvis du fortæller ham, at jeg sendte dig, giver han måske dig de særlige rabatpriser på mad og drikke.\n\nFor at finde Løvens Stolthed Kro skal du rejse sydpå ad vejen herfra -- du kan ikke misse den!"},
  [2160] = {n="Forsyninger til Tannok", l="Lever kassen med kroforsyninger til Tannok Frostham i Kharanøs.", d="Hey! Du ser ud som en modig eventyrer. Hvis du har planer om at trodse passet, kunne du så tænke dig at tage en pakke med til kroen i Kharanøs?\n\nDu havde da planlagt at stoppe ved kroen, ikke? Hvis du klarer passet, skal du bestemt tage en pause der.\n\nNå, bring dette til Tannok Frostham, kroværtens assistent. Jeg kan ikke komme igennem passet selv, og det tager dage, før en Bjergbestiger-eskorte kommer forbi!"},
  [2161] = {n="En Trælens Byrde", l="Bring Ukors Byrde til Kroværten Grosk i Barberbakken.", d="Undskyld mig? Kan du hjælpe mig?\n\nJeg har et læs mad her. Jeg gik langs vejen og trodsede skorpider og edderkopper og værre! Jeg bragte maden til Prøvernes Dal, fordi jeg troede, de havde brug for den, og jeg kan godt lide at hjælpe til. Men de har slet ikke brug for mad! Nu må jeg tage den tilbage til Barberbakken, og jeg er bange for alle bæsterne undervejs...\n\nKan du tage den for mig? Jeg er bare en træl, men du er en helt. Du frygter ingenting!\n\nTag den til Kroværten Grosk i Barberbakkens kro. Tak!"},
  [2206] = {n="Snup og Greb", l="Find Defias-havnefogeden og hent forsendelsesplanen for Mester Mathias Skaw.", d="Vores agenter i felten rapporterer om kraftig Defias-aktivitet syd for Guldshire. Rapporterne tyder på, at Defias har overtaget Jerods Landingsplads og nu bruger den til at smugle store mængder smuglergods fra Rødryg til Vestfald.\n\nJeg har brug for, at du infiltrerer havnehuset og skaffer mig den forsendelsesplan, <Name>. Du finder den sikkert begravet dybt i havnefogedens lommer.\n\n...og <Name>, skulle du blive opdaget, vil SI:Syv fornægte alt kendskab til din eksistens."},
  [2359] = {n="Klavens Tårn", l="Stjæl Defias-tårnnøglen, bryd ind i Defias-tårnet og afdæk indholdet af Skumringsskovens Kiste. Tag de oplysninger, du finder, med tilbage til Mathias Skaw i Stormvind. Læs Kjarnens Dagbog for at få indsigt i tårnet.", d="Jeg har holdt øje med dette tårn i ugevis, <Name>. For nylig kom en stor forsendelse fra Skumringsskoven, og med den kom de vagter.\n\nHvad er de? Din gætning er lige så god som min. Jeg kan fortælle dig én ting - de er ikke mennesker.\n\nUnder alle omstændigheder havde forsendelsen en kiste - og det er den, jeg går ud fra, de afskyeligheder vogter. Zombien med piggene har en nøgle, vi får brug for.\n\nFå fat i nøglen, kom ind i tårnet, og afdæk, hvad der er i kisten. Tag dine fund med tilbage til Mathias."},
  [2360] = {n="Mathias og Defias", l="Rejs til Vestfald og find Agent Kjarnen til din debriefing.", d="Ikke et øjeblik for tidligt, <Name>. SI:Syv-spejderne rapporterer usædvanlig kraftig Defias-aktivitet i Vestfald.\n\nDet ser ud til, at Defias har overtaget et forladt Alliance-vagttårn sydøst for Vagtbakken og bruger det som operationsbase til at smugle varer ind fra Rødryg-forsyningsruten.\n\nRejs til Vestfald og kontakt Agent Kjarnen til din debriefing. Du finder hende gemt nær tårnet.\n\n...og <Name>, skulle du blive opdaget, vil SI:Syv fornægte alt kendskab til din eksistens."},
  [2381] = {n="Plyndring af Plyndrerne", l="Bring sydhavsskatten tilbage til Wrenix den Elendige i Skralleby. Glem ikke at hente en E.K.A.K. og Tyvenes Værktøj fra Wrenix' Gizmotroniske Apparat. Du skal bruge begge disse genstande for at fuldføre din mission.\n\nSkulle du blive angrebet af usædvanligt fjendtlige papegøjer, så brug din E.K.A.K.!", d="Jeg mener ikke at skræmme dig, <Name>, men de sidste fem tyve, jeg sendte for at stjæle sydhavsskatten, kom tilbage til mig i stykker.\n\nSydpå langs kysten finder du Tidevandsbarberen, sydhavs-fribytternes skib. Gemt i lasten ligger lønnen - sydhavsskatten. På skibets anden etage ligger piratens hule, et sted hvor de træner alle deres tyve.\n\nGå om bord på skibet, stjæl skatten og bring den tilbage til mig. Brug piratens hule, hvis du vil øve dit tyveri, men vær forsigtig!"},
  [2382] = {n="Wrenix fra Skralleby", l="Rejs til Skralleby og tal med Wrenix den Elendige.", d="Zando'zan har set det! Ja, dagen kommer! Traels død... dolken i hans ryg, giften der sive ind i hver en åre... Zando'zan har sagt for meget.\n\n<Name>! Zando'zan har en opgave til <Name>! <Name> skal rejse til Skralleby, øst for Korsvejen, og tale med Wrenix den Elendige. Afsted!"},
  [2418] = {n="Kraftsten", l="Bring 8 Dentrium-kraftsten og 8 An'Alleum-kraftsten til Rigglefnug i Ødelandene.", d="For et stykke tid siden havde jeg et uheld med Skyggesmedes-dværgene. De bragte mig til Angor-fæstningen for at studere to slags mærkelige sten fra Uldhulen. Jeg opdagede, at stenene var vedvarende, stabile kraftkilder, hvis de blev behandlet rigtigt. Det er utroligt, hvad man kan finde på det gamle udgravningssted!\n\nNå, efter at jeg fortalte dem stenenes hemmelighed, smed de mig ud af Angor-fæstningen og begyndte at grave efter flere i Uldhulen.\n\nJeg vil have de sten for mig selv! Bring mig begge typer, så betaler jeg dig godt!"},
  [2438] = {n="Den Smaragdgrønne Drømmefanger", l="Bring den Smaragdgrønne Drømmefanger til Tallonkai Hurtigrod i Dolanår.", d="Jeg fik engang en smaragdgrøn drømmefanger af Gaerolas Talvethen, druidernes vogter i Ban'ethil-gravhulen. Denne kraftfulde amulet kan suge energi fra Den Smaragdgrønne Drøm og give held til dem, der bærer den.\n\nDesværre har jeg ikke kunnet hente den fra min kommode i Stjernebrise-landsbyen... Selvom Stjernebrise engang var et roligt sted, er det nu bukket under for det fordærv, furbolgerne der bærer.\n\nVil du måske hente min drømmefanger, <Class>?"},
  [2458] = {n="Dyb Dækning", l="Rejs til Ventureselskabets Tårn, nord for Slamfennen, og kontakt Den Splittede Hånds hemmelige agent, Opgaveleder Fizzule.\n\nNår tårnet er i sigte, brug signalpistolen til at melde din ankomst til Opgaveleder Fizzule. Affyr TO signalskud, og nærm dig derefter Opgaveleder Fizzule og udfør den Splittede /Hilsen.\n\nDisse handlinger skal udføres i den rigtige rækkefølge, for Fizzule vil angribe og afslutte enhver person, han ikke genkender.", d="Ventureselskabet... Måske har du hørt om dem?\n\nI et år har vi arbejdet på at plante en agent dybt i deres rækker. Gennem hårdt arbejde og omhyggelig planlægning lykkedes det.\n\nFor nylig fik vi besked om, at Ventureselskabet planlægger noget i stor skala. Gå nord for Slamfennen til Ventureselskabets tårn og kontakt vores undercoveragent, Opgaveleder Fizzule.\n\nNår du finder tårnet, brug denne signalpistol, nærm dig derefter Fizzule og vis ham Den Splittede Hånds hilsen."},
  [2478] = {n="Mission: Mulig, men Ikke Sandsynlig", l="Stjæl Silixiz' tårnnøgle fra Formand Silixiz, og dræb derefter to Muterede Ventureselskab-droner, to Ventureselskab-patruljemænd og to Ventureselskab-udkigsmænd.\n\nMyrd Stor-Formand Gallywix og tag hans hoved, og bryd derefter låsen op på Gallywix' pengekasse og stjæl Beholderen med Zanzils Ændrede Blanding. Tag Beholderen og Gallywix' hoved tilbage til Shenthul i Orgrimgrad for yderligere instruktioner.", d="Du bliver nødt til at stjæle tårnnøglen fra Formand Silixiz, <Name>. Når du har nøglen i din besiddelse, så hold fast i den - jeg får måske brug for den senere.\n\nHusk, giften har svækket alt i dette tårn. Brug dine evner til at bringe kaos og ødelæggelse over dets indbyggere. Slå dem alle ihjel -- vis ingen nåde!\n\nNår alt indenfor ligger i en blodig hob, så bryd Gallywix' pengekasse op og stjæl beholderen med Zanzils blanding, der ligger indeni. Tag både Gallywix' hoved og blandingen til Shenthul i Orgrimgrad."},
  [2498] = {n="Tilbage til Denalan", l="Rellian Grønspyd vil have dig til at tale med Denalan ved Al'Ameth-søen.", d="Jeg har lige modtaget besked om, at Denalan ved Al'Ameth-søen har opdaget, hvad der kan være årsagen til de tumorer, der plager tømmerlingerne. Tal venligst med ham, og fortæl ham, at jeg sendte dig.\n\nSkynd dig, <Name>; han har brug for vores hjælp."},
  [2518] = {n="Månens Tårer", l="Præstinde A'moora i Månens Tempel i Darnassos vil have dig til at bringe hende Lady Sathrahs Sølvfarvede Spindekirtler.", d="Lady Sathrah var engang elsket af Elune. Yndefuld og ren spandt edderkoppen sine sølvtråde gennem månelyset og fangede aftentågen. Sølvduggen havde stærke helbredende kræfter og blev opbevaret her i templet.\n\nMen på det seneste er Sathrah faldet ned i vanvid. Hendes kommende generationer er nu også truet.\n\nFind Lady Sathrah, <Name>, og gør ende på hendes lidelse. Hun holder til langs de nordlige grænser af Teldrasil, nær Brøndsøen. Saml hendes sølvfarvede spindekirtler og bring dem tilbage til mig."},
  [2541] = {n="Den Sovende Druide", l="Bring en Shaman-voodoo-amulet til Oben Vredeklo i Ban'ethil-gravhulen.", d="Knudefyr-shamanerne, der holder til her, har opdaget en måde at adskille en sovende druids ånd fra den fysiske krop. Furbolgerne har animeret min fysiske krop og bruger den til at angribe alle, der forsøger at udforske Ban'ethil-gravhulen. Jeg er nu fanget i Den Smaragdgrønne Drøm, magtesløs til at stoppe det.\n\nDu må hjælpe mig. Knudefyr-shamanerne bærer en mærkelig amulet, der bruges til at udføre dette ritual, og jeg vil gerne undersøge den. Venligst, <Name>, bring mig en."},
  [2561] = {n="Klo-druiden", l="Oben Vredeklo vil have dig til at dræbe hans sjælløse krop og derefter bruge voodoo-amuletten.", d="Efter at have undersøgt denne amulet, <Name>, ser jeg nu, hvad der må gøres. Tag den venligst, og gør som jeg beder.\n\nDu skal udforske de dybeste områder af Ban'ethil-gravhulen. Der vil du finde min sjælløse krop... Selvom jeg beklager det, jeg er ved at fortælle dig, ser jeg ingen anden måde at befri mig fra Knudefyrens kontrol på.\n\nFor at slippe fri af dem må du dræbe min fysiske form. Når det er gjort, så brug voodoo-amuletten på min faldne krop. Når du har udført denne opgave, så vend venligst tilbage til mig."},
  [2609] = {n="Zanzils Berøring", l="Bring Doktor Mixilpixil en bundt Simple Vilde Blomster, et Blyglas, et Bronzerør og en Spole Lys Chartreuse Silketråd. 'Itis' kurerer sig ikke selv, unge ven!", d="Det er enstemmigt, <Name>. Du har 'itis'.\n\nHeldigvis har jeg en kur mod 'itis'.\n\nHer er, hvad jeg har brug for: Et bundt simple vilde blomster, et blyglas, et bronzerør og, sidst men bestemt ikke mindst, en spole lys chartreuse silketråd. Gamle Emma efterlod en spole af den til mig i 'Den Fineste Tråd'. Du finder butikken langs kanalerne.\n\nSkynd dig nu, <Name>, og prøv ikke at røre ved nogen, før du er helbredt. Åh, og Dr. Montgomeri siger, at du har brug for et bad -- hans ord, ikke mine."},
  [2745] = {n="Infiltration af Borgen", l="Tal med Tyrjon i Stormvinds Borg.", d="Hmm, en interessant historie, og ikke en at tage let på. Ja, jeg kan hjælpe dig, men det, du skal gøre, er at uddele en form for retfærdighed, der ikke er... lovlig, hvis du vil se dette til ende.\n\nLescovær og Marzøn skal tages hånd om, og hurtigt. Tror du, du er i stand til sådan noget?\n\nDu må beslutte. Hvis ja, så skynd dig til borgen og find en gammel ven af mig, en gnom ved navn Tyrjon. Han har holdt øje med Lescovær i et par uger nu. Han burde kunne hjælpe dig med at få det til ende."},
  [2746] = {n="Ting af Betydning", l="Bring 3 Silkestof og 2 af Claras Friske Æbler til Tyrjon i Stormvind.", d="Trøsen vil have tidsplanen skubbet lidt op, hva'? Okay, det kan vi godt, men jeg er ikke klar. Og det her skal du vide: Jeg laver det svære arbejde, men det er dig, der skal have snavsede hænder, forstår du? Godt.\n\nOkay, jeg skal bruge, at du skaffer mig et par ting, før jeg kan sætte min plan i værk. Jeg har den perfekte forklædning, der får Spionbotten forbi vagterne.\n\nBring mig noget silke og et par æbler. Silken må du selv om, men Claras lille gård lige uden for byen har de perfekt store æbler."},
  [2841] = {n="Rig-krigen", l="Hent Rig-tegningerne og Thermapluggs safekombination fra Nisseborgen og bring dem til Nogg i Orgrimgrad.", d="Gnomisk teknologi - for to år siden var dens mest almindelige brug en punchline. Tiderne har bestemt ændret sig. Nu har de bygget en ny rig, der er bedre end alle vores shredder-modeller tilsammen. Jeg har brug for tegningerne, <Name>!\n\nDesværre er planerne låst inde i en safe nær Mekgineer Thermaplugg. Hvad værre er, kender kun Mekgineer Thermaplugg kombinationen til safen.\n\nGør hvad som helst for at skaffe den kombination, <Name>. Knæk så den safe op og bring tegningerne tilbage!"},
  [2842] = {n="Chefingeniør Skuti", l="Tal med Skuti i Bytteviken.", d="Så snart vi hørte fra Kernobi om den nye gnomrig, begyndte Skuti og jeg at arbejde på Transpolyporter 6000: Den hurtigste og pålideligste vej til Nisseborgen.\n\nDen er endelig klar til at tage passagerer, <Name>. Hvis du vil prøve den, så tag til Bytteviken og tal med Skuti ved vindrytter-redet. For at komme til Bytteviken tager du båden fra Skralleby.\n\nSelvfølgelig kunne du altid prøve at komme til Nisseborgen gennem de dværgeplagede bjerge i Dun Frostbakke!"},
  [2904] = {n="En Flot Rodet Sag", l="Eskorter Kernobi til udgangen fra Clockwerk-løbet, og rapportér derefter til Skuti i Bytteviken.", d="<Kernobi stønner.> Hv.. Hvad skete der?\n\nDet sidste, jeg husker, er, at jeg blev taget til fange af en gruppe mørkjernsdværge, slået næsten ihjel og så smidt herind sammen med de beskidte troggs.\n\nFør mig ud herfra, <Name>!\n\nHer er planen: Led mig til udgangen; hvis vi kommer levende ud, rejser du til Bytteviken og lader Skuti vide, at jeg tog til Skralleby for at advare Tinkerviz om mørkjernens involvering i fremstillingen af den superrig.\n\nLad os komme i gang!"},
  [2922] = {n="Red Teknobots Hjerne!", l="Bring Teknobots hukommelseskerne til Tinkmester Overgnist i Jernsmede.", d="Da vores elskede by Nisseborgen faldt, må en flygtig gnist have ramt min stakkels skabning, Teknobot. Den hjalp engang mig og mine medarbejdere med sine utallige småting og sin grænseløse informationsmængde, men dens positroniske hjerne er blevet polariseret. Nu er den negatronisk... og Teknobots adfærd er vendt om. Den vanker rundt i Nisseborgen i raseri!\n\nMen måske kan den reddes. Hvis du kan hente Teknobots hukommelseskerne og bringe den til mig, kan jeg måske finde årsagen til polariseringen og fikse min stakkels Teknobot."},
  [2923] = {n="Tinkmester Overgnist", l="Tal med Tinkmester Overgnist i Jernsmede.", d="Tinkmester Overgnist er meget oprevet over skæbnen for hans mekaniske skabning, Teknobot. Jeg husker Teknobot som et venligt og hjælpsomt værktøj for gnomerne, men Overgnist fortæller mig, at den er gået i sort.\n\nMeget trist. Men med lidt held kan den måske repareres!\n\nTal med Tinkmester Overgnist i Tinkerbyen i Jernsmede. Han vil sætte pris på din hjælp."},
  [2924] = {n="Essentielle Kunstigheder", l="Bring 12 Essentielle Kunstigheder til Klockmort Skruespænd i Jernsmede.", d="En nærmest universel mekanisk komponent--den essentielle kunstighed--var til stor gavn for tinkerne og smedene i Nisseborgen. Men under den febrilske udvandring fra vores by huskede ingen at tage nogle af disse apparater med sig! Og jeg har brug for en stor forsyning af dem til det arbejde, jeg snart påtager mig.\n\nVær venlig at gå ind i Nisseborgen og hent mig nogle essentielle kunstigheder. Du finder dem i byens dybere områder, opbevaret i beholdere kaldet kunstige ekstrapolatorer.\n\nTak, <Name>, og skynd dig venligst!"},
  [2925] = {n="Klockmorts Essentialier", l="Tal med Klockmort Skruespænd i Jernsmede.", d="En gnomisk ven, Klockmort Skruespænd, sendte bud til mig fra Jernsmede. Han fortæller mig, at han har brug for hjælp til en farlig, men essentiel mission ind i Nisseborgen, den engang så store gnomby, som nu er forurenet og fyldt med gale gnomer og deres apparater.\n\nJeg må blive her, men mit hjerte værker over at hjælpe min ven. Hvis du kan gå i mit sted, vil jeg stå dybt i gæld til dig.\n\nDu finder Klockmort i Tinkerbyen i Jernsmede."},
  [2926] = {n="Gnoginne", l="Brug den Tomme Blyindsamlingsflaske på Bestrålede Indtrængere eller Bestrålede Plyndrere for at samle radioaktivt nedfald. Når den er fuld, skal du tage den med tilbage til Ozi Skiftevolt i Kharanøs.", d="Siden ulykken tænker Gnåhrn på intet andet og taler om intet andet end at rense Nisseborgen for trolde-plagen og finde en kur mod sygdommen, der hjemsøger den, <Name>.\n\nHeldigvis er Razzle og jeg tæt på en form for kur - enten det, eller opskriften på en virkelig stærk rom. Vi ved det ikke, før vi tester! Naturligvis skal vi bruge nogle få ting for at teste vores teori; nemlig nedfald fra de bestrålede trolde i Nisseborgen. Fyld denne flaske med det grønne lys og bring den tilbage!"},
  [2927] = {n="Dagen Efter", l="Tal med Ozi Skiftevolt i Kharanøs.", d="Tror du ikke, jeg altid har været skaldet, vel? Nej, herre/frue! Det var radioaktivt lækage i Nisseborgen, der forårsagede dette tragiske hårtab. Før den dag havde jeg det eneste gnomhår i hele Azeroth.\n\n<Gnåhrn rækker næven op i luften.>\n\nForbandede, beskidte trolde - forbandet være de alle!!\n\nMåske er det ikke for sent, <Name>. Vi kan stadig redde den - byen mener jeg! Tal med Ozi Skiftevolt i Kharanøs. Han og hans partner Razzle arbejder på en løsning."},
  [2928] = {n="Gyrodrillmatiske Gravemaskiner", l="Bring 24 Robo-mekaniske Indvolde til Shoni i Stormvind.", d="Det er forfærdeligt, <Name>. Vi kommer ikke til at have nok dele til at få vores flåde af gyrodrillmatiske gravemaskiner til Dun Frostbakke.\n\nDet, vi har brug for, er reservedele, <Name>. Hvor er der bedre at få reservedele til vores køretøjer end i Nisseborgen? Jeg hører, at robotter og mekaniske væsner strejfer rundt derinde som kvæg på en åben mark.\n\nDet, jeg vil have dig til, er at tage til Nisseborgen og rive de robotter fra hinanden. Bring mig deres robot-indvolde tilbage. To snese burde være nok."},
  [2929] = {n="Det Store Svigt", l="Begiv dig til Nisseborgen og dræb Mekgineer Thermaplugg. Vend tilbage til Højtinker Mekkatorque, når opgaven er løst.", d="Jeg stolede på Thermaplugg, <Race>. Aldrig havde jeg forventet, at han ville forråde mig og hele det gnomiske folk. Og for hvad? Magt? Rigdom? Ting, som han ville have fået i sin tid. Nu er vi blevet fordrevet fra vores hjem, og den galning har overtaget. Kongen af ingenting....\n\nVi vil generobre Nisseborgen, <Name>. Vi holder ikke op, før byen igen er under vores kontrol. Hvis du vil være med i kampen, beder jeg om en enkel opgave: Dræb forræderen. Ødelæg Mekgineer Thermaplugg."},
  [2930] = {n="Datareddning", l="Bring et Prismatisk Hulkort til Mestermekaniker Kastrør i Jernsmede.", d="Da vi flygtede fra Nisseborgen, efterlod vi så mange data! Yderst vigtige data!\n\nJeg har brug for dataene på et prismatisk hulkort fra en Matrix Punchograph 3005-D højsikkerhedsterminal, dybt inde i Nisseborgen. Du skal have adgang til terminalen, men for at komme dertil skal du først have tilladelse... og for at få den må du gå via terminaler med lavere sikkerhed - modellerne -A, -B og -C. Og for at gøre DET skal du bruge sikkerhedshulkort, begyndende med hvide... og vi efterlod alle hulkortene i byen.\n\nDet er en katastrofe! Kan du hjælpe?"},
  [2931] = {n="Kastrørs Opgave", l="Tal med Mestermekaniker Kastrør i Jernsmede.", d="Mestermekaniker Kastrør i Jernsmede har brug for eventyrere! Han organiserer hold til at vende tilbage til Nisseborgen på en datahentningsmission af højeste sikkerhed og betydning.\n\nKastrør er måske ikke medlem af den Oplyste Forsamling for Arkanologi, Alkymi og Ingeniørvidenskab, sådan som jeg er, men han er stadig en klog gnome, så hvis han mener, det er vigtigt, er der efter mine beregninger en sandsynlighed på fireogfirs procent for, at det virkelig er vigtigt!\n\nDet er gode odds!"},
  [2945] = {n="Skidtbelagt Ring", l="Find ud af en måde at fjerne skidtet fra den Skidtbelagte Ring på.", d="Du har afdækket det, der ser ud til at være en ring fra liget af en af Mørkjernsdværgene. Det er svært at se, hvilken slags ring det er; snavs og hærdede rester har fuldstændigt dækket genstanden, så det er umuligt at bære den. Du tror, du kan skimte den svage glans af ædelmetal og måske endda glimtet fra en ædelsten under resterne.\n\nHvis du vil bruge denne ring, må du finde noget, der kan fjerne de hærdede rester fra den."},
  [2948] = {n="Gnomisk Forbedring", l="Bring den Strålende Guldring, en Sølvbarre, en Mosagat og 30 sølvmønter til Talvash del Kissel i Jernsmede.", d="Lyt, <Name>, ringen er din, javel... men jeg kan lave en bedre til dig! Designet er, som sagt, virkelig simpelt. Jeg er blevet langt dygtigere nu, og for blot tredive sølvmønter pudser jeg den op til dig! Nå, lidt mere end tredive, faktisk...\n\nJeg er i en trang spot lige nu; hele mit materialelager er tørret ud. Hvis du bringer mig en sølvbarre og en mosagat, tilføjer jeg et gitter af sølv og agat på ringen, som giver den lidt mere pizzazz!\n\nStol på mig!"},
  [2950] = {n="Noggs Ring Omarbejdet", l="Bring den Strålende Guldring, en Sølvbarre, en Mosagat og 30 sølvmønter til Nogg i Orgrimgrad.", d="Nej, nej, nej - jeg siger ikke pludselig, at ringen er min. Jeg plejer ikke at gøre sådan noget, men dine oplysninger om Mørkjernsdværgene var meget nyttige. Jeg forbedrer din ring for dig, bedre end nogen, der har lavet denne simple lille ting, nogensinde kunne have gjort. Sikkert en eller anden gnome...\n\nHvis du bringer mig en sølvbarre, en mosagat og tredive sølvmønter for besværet, tilføjer jeg et gitter af sølv og agat til ringen, som vil styrke magien indeni den. Interesseret?"},
  [2962] = {n="Den Eneste Kur er Mere Grønt Lys", l="Rejs til Nisseborgen og bring højpotent radioaktivt nedfald tilbage. Vær advaret, nedfaldet er ustabilt og vil ret hurtigt kollapse.\n\nOzi vil også kræve din tunge Blyindsamlingsflaske, når opgaven er løst.", d="Din prøve var ikke kun utilstrækkelig i mængde, den var også uren.\n\nDet, vi har brug for, er mere grønt lys. Troldene er tydeligvis ikke bestrålet nok til at opfylde vores behov. Du må tage til Nisseborgen og bringe noget radioaktivt nedfald tilbage, direkte fra hanen. Jeg taler om de bestrålede slimvæsner, lurere og rædsler. Vær advaret, indeslutningen af denne type nedfald er vanskelig. Du må gøre flere forsøg med flasken, indtil en brugbar prøve er indsamlet."},
  [2984] = {n="Ildens Kald", l="Find Kranal Fiss i Ødemarken.", d="Længe siden du sidst blev testet, <Name>. Du har vist tålmodighed indtil nu i dine studier, men tiden er kommet til, at du skal lære mere. Tiden er kommet til, at du skal lære om ødelæggelse... og kaos. Ildens element er dit at forstå, hvis du er parat til at betale for det.\n\nSøg Kranal Fiss i Ødemarken. Han bor i et lille hus nord for Korsvejen, men vær opmærksom: Hvis du er nået til natteelvernes lande, er du kommet for langt."},
  [2998] = {n="Guddommelighedens Tome", l="Tal med Dutorian Ralle i Stormvind.", d="Hilsen, bror/søster. Dutorian Ralle, en af vores mest indflydelsesrige paladiner, talte om dig for nylig. Jeg overhørte ham fortælle, at det var på tide, at du blev sat på prøve... sammen med nogle meget smigrende ord om, hvor godt du har klaret dig indtil nu.\n\nHvis jeg var dig, ville jeg tage til Stormvind og tale med ham, når du har tid. Jeg er sikker på, at han er i Lysets Katedral - det er der, han tilbringer det meste af sin tid."},
  [2999] = {n="Guddommelighedens Tome", l="Tal med Tiza Kampsmed i Jernsmede", d="Hej, <Name>. Jeg ved, du har travlt med at hjælpe folkene i Dun Frostbakke, men når du får tid, bør du gå op ad trappen og tale med en af vores mest respekterede slags: Tiza Kampsmed. Hun er den, de yngre paladiner går til, når det er tid til, at de lærer mere om Lyset, og hvad der forventes af dig."},
  [3085] = {n="Helliget Tavle", l="Læs den Helligede Tavle og tal med Ken'jai udenfor Hulen i Prøvernes Dal.", d="Ah, mens du var væk, kom der en tavle til dig, <Name>.\n\nLæs den, når du har tid. Hvis jeg ikke tager fejl, kom den fra præstetræneren Ken'jai. Han vil have et ord med dig, når du er klar."},
  [3098] = {n="Glyfrulle", l="Læs Glyfrullen og tal med Isabella i kirken i Dødsklokken.", d="Ah, mens du var væk og beskæftigede dig med den tankeløse Svøben, ankom denne rulle til dig. Jeg tror, det er en sag af betydning, for den ser ud til at bære seglet fra magi-træneren Isabella. Jeg ville tage mig tid til at læse den, før du giver dig i kast med noget nyt."},
  [3099] = {n="Besmittet Rulle", l="Læs den Besmittede Rulle og tal med Maximillion i Dødsklokken.", d="Ah, mens du var væk og beskæftigede dig med den tankeløse Svøben, ankom denne rulle til dig. Jeg tror, det er en sag af betydning, for den ser ud til at bære seglet fra hekseri-træneren Maximillion. Jeg ville tage mig tid til at læse den, før du giver dig i kast med noget nyt."},
  [3101] = {n="Indviet Brev", l="Læs det Indviede Brev og tal med Broder Sammuel i Nordshire-klosteret.", d="Jeg blev bedt om at gøre dig opmærksom på dette, så snart du var kommet tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med insignien fra Broder Sammuel, vores lokale paladin-træner. Jeg ville ikke tøve med at læse det, før du går i gang med andre ærinder her i klosteret."},
  [3104] = {n="Glyfbrev", l="Læs Glyfbrevet og tal med Khelden Bremen inde i Nordshire-klosteret.", d="Jeg blev bedt om at gøre dig opmærksom på dette, så snart du var kommet tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med insignien fra Khelden, vores lokale magi-træner. Jeg ville ikke tøve med at læse det, før du går i gang med andre ærinder her i klosteret."},
  [3105] = {n="Besmittet Brev", l="Læs det Besmittede Brev og tal med Drusilla Den Salte ved siden af Nordshire-klosteret.", d="Jeg blev bedt om at gøre dig opmærksom på dette, så snart du var kommet tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med insignien fra Drusilla, en af vores lokale trænere. Jeg ville ikke tøve med at læse det, før du går i gang med andre ærinder her i klosteret."},
  [3107] = {n="Indviet Rune", l="Læs den Indviede Rune og tal med Bromos Grummner i Kuldekam-dalen.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du får chancen. Jeg tror, den kom fra paladin-træneren Bromos. Kig på den og find ham inde i Ambolmar, når du får chancen."},
  [3113] = {n="Krypteret Memorandum", l="Læs det Krypterede Memorandum og tal med Solm Hargrin i Kuldekam-dalen.", d="Mens du hjalp mig, blev dette memorandum givet til mig for at videregive til dig. Tag dig tid til at læse det, når du får chancen. Jeg tror, det kom fra lumsk-træneren Solm. Kig på det og find ham inde i Ambolmar, når du får chancen."},
  [3116] = {n="Simpelt Segl", l="Læs det Simple Segl og tal med Alyissia i Skyggedalen.", d="Dette segl blev givet til mig af en budbringer fra vores krigertræner, Alyissia. Det ser ud til, at Alyissia vil have et ord med dig, når du har et øjeblik. Læs det og bring det til hende bagefter."},
  [3261] = {n="Jørn Himmelspåer", l="Tal med Jørn Himmelspåer i Taurajo-lejren.", d="Din tid med mig er forbi, <Name>. For at lære mere skal du gå til Taurajo-lejren mod syd og tale med Jørn Himmelspåer. Han vil fortsætte din vejledning."},
  [3281] = {n="Stjålet Sølv", l="Bring det Stjålne Sølv til Gazrøg i Korsvejen.", d="Du har måske dræbt raptorerne, men sølvet, de stjal, skal hentes tilbage! Jeg har rapporter om, at raptorerne har en stor samling reder syd for Skralleby, kendt som Raptor-områderne. Det er sandsynligt, at de har bragt vores stjålne sølv derhen.\n\nGå til denne raptor-tilflugt og led efter det stjålne sølv. Når du finder det, så bring det tilbage til mig."},
  [3301] = {n="Mura Runetotem", l="Tal med Mura Runetotem i Gravkammeret.", d="Min klanfælle, Mura Runetotem, rejste til Sølvfyrreskoven, så hun kunne hjælpe vores undøde allierede. Sølvfyrreskoven er en syg skov, en døende skov, og Mura håbede på at give den nyt liv. Måske kan det mærkelige liv, man finder her i Ødemarken, hjælpe hende med hendes arbejde i Sølvfyrreskoven.\n\nTag en prøve af de skaller, du har samlet, og bring den til Mura i Sølvfyrreskoven. Hun opholder sig i Gravkammeret. Med lidt held vil studiet af skallen give hende den indsigt, hun har brug for, for at helbrede det døende sted."},
  [3361] = {n="En Flygtnings Dilemma", l="Bring Felix' Kasse, Felix' Kiste og Felix' Spand med Bolte til Felix Vindbolt i Ambolmar.", d="Vi jog trogerne ud af Nisseborgen, men så gik det hele frygteligt galt! Nu er vores hjem fuldstændig forstrålet, og vi gnomer er spredt ud over hele Dun Frostbakke.\n\nI min iver for at komme væk fra strålingen mistede jeg alle mine personlige ejendele og værktøj. Det var trolde, der tog dem. De stjal min kiste, min kasse og min spand med bolte! De bragte dem tilbage til deres lejre sydvest for Ambolmar.\n\nJeg er ingen eventyrer - kunne du finde mine ting og bringe dem hertil til mig, tak?"},
  [3364] = {n="Skoldhed Morgenbrygg-levering", l="Tag en Skoldhed Morgenbrygg til Durnan Pelsskærer inde i Ambolmar, før den bliver kold om fem minutter!", d="Gah! Jeg skulle have leveret denne lækre skoldhede morgenbrygg til Durnan Pelsskærer inde i Ambolmar for et stykke tid siden, men jeg måtte først levere en til Grelin her. Jeg når aldrig frem til Ambolmar, før brygget bliver koldt!\n\nDu ser hurtig ud. Måske kan du nå det. Dette krus holder kun varmen i fem minutter mere, og Durnan bestilte ikke \"lunken\" morgenbrygg, så kom af sted. Ambolmar ligger mod nordøst, en bebyggelse gravet ind i bjerget.\n\nTak, <Name>, og glem ikke at bringe mit krus tilbage!"},
  [3365] = {n="Bring Krusen Tilbage", l="Returner Noris Krus til Nori Stolthed.", d="Nu ramte det plet! Intet er som en dampende - nej, SKOLDHED morgenbrygg på en kold vinterdag for at varme din sjæl op.\n\nVær så venlig, <Name> - vær en ven og tag dette tomme krus tilbage til Nori for mig, vil du nok."},
  [3369] = {n="I Mareridt", l="Bring Mareskården til Hamuul Runetotem i Ældrehøjen.", d="Denne skår rummer store hemmeligheder; den er den rene essens af Den Smaragdgrønne Drøm. Men det, jeg ser i denne skår, er ikke en drøm; man ville kalde denne slags syn for et mareridt.\n\nJeg ønsker ikke at forskrække dig, <Name>, men jeg synes, det er bedst, hvis du leverer denne skår i hænderne på en klog druide så hurtigt som muligt.\n\nHamuul Runetotem i Ældrehøjen er den, du skal finde. Tag til Tordenklippe. Jeg kan ikke sige mere."},
  [3370] = {n="I Mareridt", l="Bring Mareskården til Mathrengyl Bjørnegænger i Darnassos.", d="Denne skår rummer store hemmeligheder; den er den rene essens af Den Smaragdgrønne Drøm. Men det, jeg ser i denne skår, er ikke en drøm; man ville kalde denne slags syn for et mareridt.\n\nJeg ønsker ikke at forskrække dig, <Name>, men jeg synes, det er bedst, hvis du leverer denne skår i hænderne på en klog druide så hurtigt som muligt...\n\nMathrengyl Bjørnegænger i Cenarion-kredsen er den, du skal finde. Tag til Darnassos. Jeg kan ikke sige mere."},
  [3513] = {n="Den Runemærkede Rulle", l="Tag den Runemærkede Rulle til vagttårnet mod nord i Ødemarken.", d="Den officielt udseende rulle er viklet tæt ind i et sølvfarvet bånd. Du er sikker på, at nogen ville være interesseret i at se den, men hvem?\n\nDer er en udpost tæt på Askedalens grænse mod nord, og hvis oplysningerne på denne rulle vedrører nattens alfer, er det dér, den skal bringes hen."},
  [3514] = {n="Hordens Tilstedeværelse", l="Dræb lederen af Klohulen, Rynthariel Nøglevogteren.", d="Denne rulle stammer fra den snedige dryade Rynthariel, Nøglevogter i Klohulen på Stenklippe-toppen.\n\nHun kommer ikke til at have mere kontakt med budbringeren, du plyndrede den fra, hehe, men vi må holde stand her. Horden vil ikke tolerere hendes udsendinge her.\n\n<Name>, rejs til Klohulen. Dræb Rynthariel, og sæt derefter et symbol op, så alle kan se det. Tag dette Horde-flag, <Name>. Sæt det op i Klohulen, så de ikke er så overilede, at de sender endnu en budbringer gennem vores territorium."},
  [3524] = {n="Skyllet i Land", l="Hent havskabningens knogler fra det strandede havdyr lige syd for Auberdin, og vend derefter tilbage med dem til Gwennyth Bly'Sagn i Auberdin.", d="Majestætiske havskabninger er kendt for at kaste sig mod Mørkekystens kyst, hvor de strander og dør. På det seneste er disse bæster skyllet i land i stadigt stigende antal. Jeg er blevet sendt hertil af Månens Tempel for at undersøge sagen, men tilstedeværelsen af murlocs langs vandet har gjort min forskning svær.\n\nDer ligger et kæmpe væsen skyllet i land lige syd for Auberdin, omringet af de onde Gråtåge-murlocs. Kunne du tage derhen og hente knogler fra væsenet til vores undersøgelse?"},
  [3643] = {n="Vis Dit Arbejde", l="Bring 6 Mithrilrør, et Præcist Sigte og 2 Avancerede Målpupper til Oglethorpe Uopdaget i Bytteviken.", d="Som din mentor ønsker jeg nogle prøver af dit arbejde. Du er en dygtig ingeniør; der er ingen tvivl om det, <Name>. Det, jeg håber at gøre, er dog at analysere dit arbejde for at finde måder at fremhæve gnomiske teknikker i dine fremtidige bestræbelser. Jeg har brug for følgende prøver: seks mithrilrør, et præcist sigte og to avancerede målpupper.\n\nIndsend disse genstande til mig, så udsteder jeg dit eget Gnom-ingeniør medlemskort; det kræves for adgang til alle gnomiske ingeniørtrænere!"},
  [3741] = {n="Hildes Halskæde", l="Find Hildes Halskæde, og returner den til Hilde i Søshire.", d="Min ven Hilde har tabt sin halskæde, og vi kan ikke finde den. Vi har fisket hele dagen lige her, og vi har allerede kigget rundt. Det eneste, jeg kan tænke mig, er, at den er faldet i søen. Vores forældre vil ikke have, at vi svømmer i søen... min mor siger, at der er nogle grimme ting under vandet, men du ser ud til ikke at være bange for grimme ting.\n\nKunne du finde den til hende, tak?"},
  [3765] = {n="Korruptionen i Udlandet", l="Rejs til Gershala Natviskning i Auberdin.", d="Stormvind -- sådan et travlt centrum for aktivitet.\n\nJeg er rejst langt for at søge hjælp. Det siges ofte, at modige eventyrere færdes på disse bygader.\n\nMin bror, Gershala, har brug for hjælp i Mørkekysten. Han bor i den kystnære by Auberdin.\n\nRejsen er lang og episk. Det er af den grund, at jeg beder om hjælp fra en erfaren <Class> som dig selv."},
  [3861] = {n="KLUK!", l="Find noget Specialhønsefoder og returner til din venskabelige høne. Når du finder den, skal du /hurra til den, før du forsøger at give den Specialhønsefoderet.", d="\"Kluk... kluk... kluk... BAKAW!\n\nKluk... kluk... kluk.\"\n\nHønen kigger op på dig og begynder så at ridse med sine kløer i jorden. Du tror, den staver et ord, men du er ikke sikker på, hvad det er. Kunne det være... S-A-L-D-E-A-N? Før du kan spørge, vender hønen sig væk og går tilbage til sine gøremål."},
  [3901] = {n="At Rasle med Rasselburene", l="Dræb 12 Rasselbur-skeletter, og vend derefter tilbage til Skyggepræst Sarvin i Dødsklokken, når du er færdig.", d="Du har vist dit potentiale over for De Forladte under normale omstændigheder, <Name> - lad os nu se dig under pres.\n\nRasselbur-skeletterne, endnu flere hjernedøde håndlangere for Liskekongen, er en sejere modstander end de zombier, du hidtil har stået over for. Tynd igen deres rækker og bevis dig over for De Forladte. Dvæl ikke - når du er færdig, så tal med mig igen."},
  [3902] = {n="Plyndring af Dødsklokken", l="Søg i Dødsklokken og omegnen efter 6 stykker Opsamlede Varer, og returner dem til Dødevagt Saltain.", d="Hey, du der! Hvis du leder efter noget at gøre dig nyttig med, så lyt efter!\n\nVi har brug for friske rekrutter lige op af jorden, der skal ud i Dødsklokken og lede efter alt slags nyttigt udstyr. Mest sandsynligt vil det ligge i stakke af kasser. Vi forventer, at flere rekrutter rejser sig snart, og medmindre vi vil have dem til at vralte rundt nøgne, må vi hellere komme i gang med at plyndre!\n\nNu kom så i gang, din elendige knoglepose! Jeg belønner ikke dem, der ikke gider at gøre en indsats."},
  [3903] = {n="Milly Osværd", l="Tal med Milly Osværd.", d="Du har vist dig som en pålidelig <Class>, <Name>. Pålidelig, og ikke bange for at få snavsede hænder, hva'?\n\nJeg har en ven, Milly Osværd, som er i problemer. Hun står med sin vogn på den anden side af klosteret, ved stalden. Jeg er sikker på, at hun kunne bruge et par hænder som dine."},
  [3904] = {n="Millys Høst", l="Bring 8 kasser med Millys Høst til Milly Osværd ved Nordshire-klosteret.", d="En bande røvere, Defias, flyttede ind i Nordshire-vingårdene, mens jeg var i gang med at høste! Jeg rapporterede det til Nordshire-vagterne, og de forsikrede mig om, at de ville tage sig af sagen, men... jeg er bange for min druehøst! Hvis Defias ikke stjæler dem, frygter jeg, at vores vagter vil træde dem ned, når de jager slyngelerne væk.\n\nVær sød, du må hjælpe mig! Jeg samlede det meste af mine druer i spande, men jeg efterlod dem i vingårdene mod sydøst.\n\nBring mig de kasser! Red min høst!"},
  [3905] = {n="Druefragtseddel", l="Bring Druefragtseddelen til Broder Neals i Nordshire-klosteret.", d="Nu er min høst reddet, så tag denne Druefragtseddel med til Broder Neals. Han styrer lageret med mad og drikke i Nordshire, og jeg er sikker på, at han bliver glad for at høre, at han har friske druer.\n\nDu finder Broder Neals i klosteret, i klokketårnet... hvor han kan lide at smage sin vin."},
  [3921] = {n="Wenikee Boltspand", l="Bring det Ødelagte Samophlange til Wenikee Boltspand.", d="Jeg tror, jeg måske har ødelagt det Samophlange. Det er ikke godt, for jeg har allerede fortalt nogle kolleger i Underminen om det, og de var meget interesserede. Vi må finde en måde at reparere det på!\n\nTag det ødelagte samophlange med til Wenikee Boltspand, lige syd for Mor'shan-volden, Hordens forpost mellem Ødemarken og Askedalen. Hun er meget klog og nysgerrig. Hvis du viser hende samophlangen, vil jeg vædde på, at hun ville gribe chancen for at reparere det."},
  [3922] = {n="Klump-snegle", l="Bring 15 Klump-snegle til Wenikee Boltspand i Ødemarken.", d="Jeg vil gerne reparere dette samophlange, men for at gøre det får jeg brug for nogle forsyninger. Jeg er løbet tør for sytten-komma-fem kaliber klump-snegle, og jeg får brug for en masse af dem til arbejdet forude.\n\nDe nærmeste steder at skaffe dem er Slamfennen mod øst. Ventureselskabet plejer at opbevare dem i deres værktøjsspande. Gå til Slamfennen og kig i de værktøjsspande, du finder der, og vend så tilbage til mig, når du har samlet nok klump-snegle."},
  [3923] = {n="Rilli Fedtmule", l="Bring det Ødelagte og Medtaget Samophlange til Rilli Fedtmule i Orgrimgrad.", d="Nå, det virkede ikke. Jeg satte nogle ekstra målere på samophlangen for at måle dens strukturelle integritet, og de viste en integritet på et bundrekord. Jeg kunne tilføje nogle flere skiver og måske et håndtag eller to for at prøve at reparere det, men... jeg tror, at det nok kun gør tingene værre.\n\nDu bør tage samophlangen med til Rilli Fedtmule. Han plejede at arbejde for Ventureselskabet -- hvis nogen ved, hvordan man reparerer det, er det Rilli.\n\nDu finder ham i Noggs Maskinværksted i Orgrimgrad, i Æresdalen."},
  [3924] = {n="Samophlange-manualen", l="Bring Samophlange-manualen til Rilli Fedtmule i Orgrimgrad.", d="Jeg tror, jeg kan reparere samophlangen, men jeg får først brug for brugsanvisningen. Da jeg var i Ventureselskabet, havde jeg en rival, Bossen Kobberplug, som gemte på hemmelighederne om samophlangen og kun gav små stykker viden om apparatet til dem, han stolede på. Jeg var ikke en af de udvalgte få...\n\nBossen Kobberplug plejede at opholde sig i Stenåre-minen i det nordøstlige Ødemarken. Hent manualen fra ham, og hvis han har givet sider fra den til nogen, må du også samle dem ind."},
  [4021] = {n="Modangreb!", l="Bring et Stykke af Krom'zørs Banner til Regthar Dødsporten, vest for Korsvejen.", d="Hordens lovprisning af dine sejre over Kolkar er stor, men kolkarerne selv er rasende. Jeg har rapporter om, at en gruppe Kolkar er rejst fra deres hjem i Forødelse til Ødemarken for at søge hævn. Min seneste rapport var, at de allerede nu bevæger sig mod disse bunkere, fra vest!\n\nTag kolkar-invasorerne op i kamp, og gør ende på deres trussel i Ødemarken. Dræb dem, indtil deres leder, Krigsherre Krom'zør, dukker op. Besejr ham og bring mig et stykke af hans banner som bevis.\n\nVi regner med dig, <Name>."},
  [4181] = {n="Nisse-ingeniørarbejde", l="Hvis du vil lære mere om Nisse-ingeniørarbejde, så tag Manualen for Ingeniørdiscipliner med til Nixx Tandhjulsfjeder i Gadgetbyen.", d="Ekspert-ingeniørarbejde giver to forskellige discipliner: gnom og nisse. Jeg gider kun nævne nisse-ingeniørarbejde, fordi jeg er en retfærdig træner. De kan lide at lave ting, der sprænger i luften, og de bryder sig sjældent om, hvad der står i vejen - selv dem selv.\n\n<Name>, læs denne manual. Hvis du vil lære at sprænge dig selv i luften, så tag den med til Nixx Tandhjulsfjeder i Gadgetbyen. Husk - medlemskab er permanent og forhindrer, at du slutter dig til den anden disciplin, så vær sikker på, at det er det, du vil, før du afslutter hans opgave."},
  [4402] = {n="Galgærs Kaktusæble-overraskelse", l="Bring Galgær 10 kaktusæbler. Du husker, at han sagde, at de kan findes nær kaktusser.", d="Det bliver nu hedt herude i Prøvernes Dal.\n\n<Galgær tørrer sveden af panden.>\n\nHvis bare jeg havde nogle kaktusæbler, kunne jeg lave min berømte kaktusæble-overraskelse! Intet køler dig hurtigere af end et stykke af den lækre godbid.\n\nJeg siger dig hvad, <Name>. Hvis du bringer mig 10 kaktusæbler, laver jeg dig nogle portioner kaktusæble-overraskelse, som du kan tage med på dine eventyr, og en gratis træningsmanual også. Hvis du er interesseret, kan du finde kaktusæbler, der vokser nær kaktusplanterne her omkring."},
  [4495] = {n="En god ven", l="Find Iverrøn ved hulen mod nord.", d="En ven af mig ved navn Iverrøn besøger mig normalt på samme tid hver dag. Det mærkelige er, at han slet ikke har kigget forbi i dag - han er faktisk flere timer forsinket.\n\nJeg indrømmer, at jeg er lidt bekymret, <Name>. Iverrøn bruger meget tid over ved hulen mod nord, og jeg er sikker på, at du ved, hvor farligt der er - edderkopper, overalt!\n\nHvis du tilfældigvis er på vej den vej, så hold dog øje med ham?"},
  [4542] = {n="Besked til Frihvind-posten", l="Bring den Hastende Besked til Klippevagt Langhorn ved Frihvind-posten.", d="Modige rejsende, centaurerne har øget deres angreb i dette område. Frihvind-posten må straks vide om denne fornyede chikane! Find Klippevagt Langhorn ved Frihvind-posten mod sydøst og giv ham denne hastende besked.\n\nVær advaret: undgå Grimtotem-klanen i nærheden... de har opført sig underligt over for os på det seneste."},
  [4581] = {n="Kayneth Stillevind", l="Tag Shindrells Notat til Kayneth Stillevind i Skovsang.", d="Druiden Kayneth Stillevind sendte bud efter mig. Han ønsker en rapport om begivenhederne langs vores kyst og i skovene omkring Stjernelund. Han frygter, at en fordærvelse bevæger sig gennem Askedalen... og han kan have ret.\n\nVær så venlig, tag min rapport med til ham. Du finder ham i helligdommen i Skovsang, i Nattesangsskoven mod øst."},
  [4641] = {n="Din plads i verden", l="Tal med Gornek. Du husker, at Kaltunk markerede dit kort med hans placering og nævnte, at Gornek boede i Hulen, en bygning mod vest.", d="Endelig er du gammel nok, <Name>... gammel nok til at kæmpe i Hordens navn. Til at erobre til Krigshøvdingens ære.\n\nJa...\n\n<Kaltunk betragter dig.>\n\nDu klarer dig nok godt.\n\nUden tvivl ønsker du at finde en stor drage eller dæmon og kvæle den med dine bare hænder, men det ville nok være klogt at starte med noget mindre... farligt.\n\n<Kaltunk griner.>\n\nMeld dig til Gornek, han burde kunne tildele en opgave, der passer bedre til en ung <Class>. Du finder Gornek i Hulen, mod vest."},
  [4681] = {n="Skyllet i land", l="Hent Havskildpaddens Rester fra den Skelet-havskildpadde i farvandet vest for Auberdin, og tal derefter med Gwennyth Bly'Sagn tilbage i Auberdin.", d="Det strandede væsen er ikke en isoleret hændelse her i Mørkekysten. Der er flere langs kysten og endda i vandet. Jeg vil gerne have, at du undersøger et andet, vi kender til; dette blev rapporteret at være i vandet direkte vest for Auberdin, tæt på et sunket skib. Vend tilbage til mig med alt, du kan finde, der kan hjælpe vores forskning.\n\nOg på dine rejser kan du finde andre skabninger. Hvis du opdager noget, så bring det endelig til vores opmærksomhed!"},
  [4740] = {n="EFTERLYST: Mudderdyb!", l="Find og nedlæg murloken ved navn Mudderdyb. Væsenet menes at forsvare murlok-hytterne syd for Auberdin langs vandet.\n\nRapporter Mudderdybs død til Vagt Glynda Nal'Skæl i Auberdin.", d="Opmærksomhed!\n\nDer udbydes en belønning for døden af murloken \"Mudderdyb\". Dette afskyelige udyr vides at være ansvarligt for mindst én Vagts død, og det mistænkes for at have sænket mindst to fragtskibe i farvandet ud for Mørkekysten!\n\nMudderdyb blev sidst set ved en lejr af murlok-hytter syd for Auberdin, og menes at beskytte hytterne der. Belønningskrav for denne dusør skal indløses hos Vagt Glynda Nal'Skæl i Auberdin.\n\nAuberdin Landsbyråd"},
  [4762] = {n="Klippefjeder-floden", l="Rejs nord for Auberdin til det første vandfald langs Klippefjeder-floden og tag en prøve fra bassinet der.\n\nVend tilbage til Thundris Vindvæver i Auberdin med Klippefjeder-flodens prøve.", d="Klippefjeder-floden er begyndt at blive modbydelig og fordærvet. Den munder ud i Dis' Kant, og jeg frygter, at skyllevandet snart rammer Auberdin. Jeg mistænker Sortskov-furbolgerne opstrøms for at være årsagen til forureningen, men jeg mistænker også, at de ikke er den egentlige rod til det.\n\nTag dette prøverør og gå til flodmundingen nord for os. Fortsæt ind i landet til det første vandfald og tag en prøve fra bassinet der. Du vil se en bro hen over hovedet. Når du har en prøve, så vend tilbage til mig i Auberdin."},
  [4763] = {n="De fordærvede fra Sortskoven", l="Fyld den Tomme Renselsesskål ved Auberdins Månebrønd.\n\nSaml en prøve af frugt, nød og korn fra de nordlige Sortskov-furbolgerlejre.\n\nBland skålen og placer den ved bålet tættest på Klippefjeder-floden ved den nordlige lejr, og kald dermed satyr-fordærveren frem.\n\nTag Fordærvelsens Talisman og bring den til Thundris Vindvæver i Auberdin.", d="Vi har erfaret, at en kilde til furbolgernes fordærvelse er satyrerne. De har magt via talismaner, som de kanaliserer magi igennem. Hvis furbolgerne har en chance for frelse, må vi lokke satyr-fordærveren frem og tage den talisman!\n\nFyld denne skål ved vores månebrønd og tag prøver af furbolgernes føde fra deres nordlige lejr. Bland dem og placer skålen ved bålet ved floden; enhver furbolg, der spiser, bliver renset lige længe nok til at lokke satyr-fordærveren frem... som du så skal nedlægge!"},
  [4767] = {n="Vindrytter", l="Bring 10 Højrede-wyvnæg til Ælu ved Frihvind-posten.", d="Jeg er blevet bedt om at hverve flere wyverner til de store vindrytter. Deres antal vokser, og jeg håber selv at blive vindrytter en dag. Men vi kan ikke træne nok wyverner til at følge med efterspørgslen. Måske kan du hjælpe mig, <Name>.\n\nJeg har brug for, at du rejser til Højrede for at samle nogle wyvnæg. Herfra skal du gå nordvest langs kløftens vægge til en rampe, der fører dig ind i Højrede. Vær forsigtig, wyverner er meget beskyttende over deres æg, og de vil ikke være venlige over for indtrængere."},
  [4811] = {n="Den røde krystal", l="Rejs øst for Auberdin og led efter en stor, rød krystal langs Mørkekystens østlige bjergkæde. Rapporter tilbage, hvad du finder, til Vagt Glynda Nal'Skæl i Auberdin.", d="Fjendtlige måne-kin strejfer rundt i stadigt stigende antal mod øst. De blev engang anset for at være milde, næsten mystiske væsner. Selvom nogle stadig viser dem ærbødighed, tvinger Auberdins sikkerhed mig til at have et mere nøgternt syn.\n\nJeg har modtaget rapporter om, at måne-kin tiltrækkes af en stor rød krystal langs Mørkekystens østlige bjergkæde. Ingen aner, hvad krystallen er, eller om den overhovedet findes. Jeg vil have dig til at finde den derovre og rapportere tilbage til mig, hvad du finder."},
  [4812] = {n="Som vandet styrter ned", l="Fyld det Tomme Vandrør ved Auberdins månebrønd, og undersøg derefter den røde krystal langs Mørkekystens østlige bjergvæg.", d="Brug dette tomme hætteglas og fyld det med noget månebrøndsvand her i Auberdin. Sådan kraftig magi burde give et fingerpeg om krystallens sammensætning. For at gøre det skal du hælde væsken over krystallen; den burde klare resten.\n\nJeg forventer ikke, at der sker noget dårligt for dig, men jeg vil stadig have, at du er forsigtig. Mod øst over os ligger Ondskoven; hvis krystallen er forbundet med det sted, som jeg mistænker, så kan den vise sig at være meget farlig."},
  [4821] = {n="Fremmed æg", l="Returner det Fremmede Æg til Hagar Lynhov ved Frihvind-posten.", d="Der er dukket et rygte op om et fremmed æg her i Tusindnåle. De, der har set ægget, er ikke engang lykkedes med at komme tæt nok på til at undersøge det nærmere. Slanger vogter ægget, som om det var en af deres egne.\n\nJeg vil have dig til at finde dette fremmede æg og bringe det til mig, så jeg kan undersøge det. Rygter siger, at ægget ligger i en slangehule, men der er flere slangehuler langs klippevæggens fod syd og nordøst for Frihvind-posten."},
  [4841] = {n="Byd centauren fred", l="Dræb 12 Gallak-spejdere, 10 Gallak-hyrder og 6 Gallak-vindjægere, og vend derefter tilbage til Klippevagt Langhorn ved Frihvind-posten.", d="<Name>, jeg bønfalder dig om at jagte disse centaurer. De skal mærke vor hævns vrede. Angrib centaurlejren nord for Frihvind-posten! Lad vreden styre din hånd!"},
  [4865] = {n="Slangernes vildmark", l="Rapporter dine fund til Motega Ildmanke.", d="Hvis jeg ikke havde set det med mine egne øjne, ville jeg aldrig have troet, at det var sandt. Hævnen er kommet til Tusindnåle!\n\n<Hagar tørrer sig om panden.>\n\n<Name>, du må handle hurtigt! Gå nu og find Motega Ildmanke; han befinder sig ved Hvidrække-posten lige nordvest for Frihvind-posten langs vejen. Han ved, hvad der skal gøres!"},
  [4881] = {n="Attentatplanen", l="Advar Kanati Gråsky ved Hvidrække-posten om planen om at dræbe ham.", d="Taureren Kanati Gråsky er dristig nok til at opstille en jagtlejr i Tusindnåle. Vi må dræbe ham for at rydde denne jagtlejr og alle, der måtte følge efter ham. Vi samles ved den lille post sydvest for Den Store Hejs."},
  [4921] = {n="Tabt i kamp", l="Find Mankriks kone og vend derefter tilbage til ham i Korsvejen.", d="Vi kæmpede i en lille taurer-lejr, da vi blev adskilt - hun holdt tre af Børsterygerne væk på egen hånd. Men overtallet begyndte at overvælde os. Jeg ledte nogle af dem væk, kun for at se hende blive overrumplet af nytilkomne. I min raseri vendte jeg mig mod mine fjender, men de væltede mig let med deres enorme antal.\n\nJeg vågnede op til en taurer-druide, der plejede mine sår - han var faldet over mig på Guldvejen, da jeg faldt.\n\nVær sød, <Class>, find et tegn på min kone."},
  [4966] = {n="Beskyt Kanati Gråsky", l="Beskyt Kanati Gråsky mod centaurernes angreb.", d="Men der kan være flere centaurer, end jeg troede. Jeg beder dig, <Name>, om at kæmpe sammen med mig mod disse onde attentatmænd."},
  [5041] = {n="Forsyninger til Korsvejen", l="Find og returner Korsvejens Forsyningskasser til Tork i Ødemarken.", d="Angrebet på karavanen indeholdt forsyninger, vi desperat havde brug for.\n\nDu har været modig nok til at tage dig af Barbermanke-stammen indtil nu, og jeg vil bede dig om at gøre det igen, men denne gang vil jeg spørge, om du kunne holde øje med nogle af vores tabte forsyninger. Du finder dem sikkert spredt rundt i deres lejre, hvor piggrisene bliver fede af deres uærefulde gerninger.\n\nFolket i Korsvejen vil stå i gæld til dig."},
  [5042] = {n="Agamaggans Styrke"},
  [5043] = {n="Agamaggans Smidighed"},
  [5044] = {n="Agamaggans Visdom"},
  [5045] = {n="Stigende Ånd"},
  [5046] = {n="Barberhud"},
  [5052] = {n="Blodskår fra Agamaggan", l="Tag et Blodskår med til Kløvtand i Taurajo-lejren i Ødemarken.\n\nSaml flere Blodskår, hvis du vil have ham til at velsigne dig med Agamaggans kraft.", d="Sammen med tornene påvirkede blodet <snort> andre aspekter af jorden: blodrøde sten blandet op med andre mineraler. Børsterygge graver disse skår op og bærer dem som totems <snort> for styrke i kamp og som totems til deres magi. <snort>\n\nJeg kender hemmelighederne bag den magi.\n\nTag et af disse blodskår med til Kløvtand, så viser du, at du forstår det. Tag mange af skårene med til Kløvtand, så velsigner han dig med kvilboar-magi, magien fra Agamaggan! <snort>"},
  [5062] = {n="Hellig Ild", l="Saml 10 skæpper Incendia-agave, og konsulter derefter Magatha Gribetotem på Ældrehøjen i Tordenklippe.", d="Arikarra er et dødbringende væsen, der hurtigt må tages hånd om. For at jage hende ned må du tænde livets hellige ild - det vil kalde Arikarra frem.\n\nGå nu og høst den sjældne Incendia-agaveplante. Når du har høstet nok agave, så søg råd hos Magatha Gribetotem på Ældrehøjen i Tordenklippe. Hun er en mægtig shaman, der kan forhekse agaveplanten, så den bliver til et pulver, der kan tænde ilden.\n\nRejs mod nordøst til Det Kogende Bassin og saml Incendia-agave."},
  [5064] = {n="Gribetotem-spionage", l="Find og hent de tre Hemmelige Seddel i Mørkeskye-tinden.", d="<Name>, du har tjent os godt tidligere, så jeg betror dig nu en vigtig mission. Grimtotem-klanen har gang i noget hemmeligt. Tre agenter af ukendt herkomst er set besøge Grimtotem-klanen de seneste uger. Vi har opdaget, at separate kister i Mørkeskye-tinden gemmer disse bevogtede beskeder.\n\n<Name>, hvis du lykkes med denne farlige mission, vil jeg belønne dig tilsvarende."},
  [5088] = {n="Arikarra", l="Dræb Arikarra. Bring hendes rester og Incendia-pulveret til Motega Ildmanke i Hvidrække-posten som bevis på din bedrift.", d="Tag dette raffinerede og rensede Incendia-pulver med til Tusindnåle og kast det på livets hellige ild. Den ligger i Mørkeskye-tinden på en isoleret nål, hvor de begraver deres døde.\n\nBesværgelsen, jeg har vævet ind i Incendia-pulveret, vil kalde Arikarra hen til dig, <Name>.\n\nJeg frygter, at hun lurer på Kærne Blodhov; der er ændret for meget taurisk lære, og jeg frygter, at det har vækket Arikarras vrede. Skynd dig, før alt er tabt, <Class>!"},
  [5147] = {n="EFTERLYST: Arnak Gribetotem", l="Dræb Arnak Gribetotem og bring beviset på din bedrift til Klippevagt Langhorn i Frihvind-posten.", d="Efterlyst: Arnak Gribetotem\n\nArnak den udstødte er eftersøgt for de afskyelige forbrydelser mord og kidnapning. Flotte belønninger vil blive givet til dem, der er modige nok til at bringe denne forbryder for retten.\n\nArnak blev sidst set på klipperne nær Mørkeskye-tinden. Vis beviset på din bedrift til Klippevagt Langhorn i Frihvind-posten for at kræve belønningen."},
  [5151] = {n="Hyperkapacitor-gizmo", l="Dræb udyret og bring Hyperkapacitor-gizmoen og Panterburens Nøgle tilbage til Wizlo Lejeglans.", d="Jeg er den eneste overlevende fra vores karavane, der blev angrebet af kentaurerne! Et sjældent, men mægtigt panter bevogter min bedste gizmo, som hænger om hans hals. Ha! Selv kentaurerne ryster i nærværelse af dette rovdyr!\n\nHer er nøglen til buret. De tog alt derinde, men lod ham være i fred. Dræb dette udyr og bring min hyperkapacitor tilbage, så belønner jeg dig.\n\nDen ødelagte karavane ligger lige nord for her."},
  [5261] = {n="Eagan Pelsskinner", l="Tal med Eagan Pelsskinner.", d="Eagan Pelsskinner leder efter nogen, der kan jage ulve for ham. Det er gode nyheder, for vi ser meget flere ulve i Nordshire-dalen på det seneste.\n\nHvis du er interesseret, så tal med Eagan. Han står rundt om siden af klosteret, til venstre."},
  [5441] = {n="Dovne Træl", l="Brug Formandens Bedøvelseskølle på dovne trælle, når de sover. Væk 5 trælle, og returner derefter Formandens Bedøvelseskølle til Formand Thazz'ril i Prøvernes Dal.", d="Forbandede trælle! De arbejder hårdt med at fælde træ i dalens træer, men de tager altid lure! Jeg har brug for nogen, der kan hjælpe med at holde trællene på plads.\n\nDu ser ud til at være den rette <Race> til min opgave. Her, tag den her bedøvelseskølle og brug den på alle dovne trælle, du finder, der sover på arbejdet. Et godt tæsk får dem straks tilbage til arbejdet! Returner køllen, når du er færdig.\n\nElendige dovne trælle..."},
  [5481] = {n="Storhånds Opgave", l="Saml 3 Mørkeukrudt og lever dem til Juniorapoteker Holland på Brills kirkegård.", d="Mester vil ha' ukrudt. Vi har store hænder og er ikke gode til at plukke. Du hjælpe os, så vi ikke gøre dig fortræd. Vi behøve mørkeukrudt. Masser ukrudt rundt om her og nær vejen.\n\nNår du har mørkeukrudt, du tage til Mester Holland på Brills kirkegård."},
  [5482] = {n="Dommeukrudt", l="Saml 10 Dommeukrudt og lever dem tilbage til Juniorapoteker Holland.", d="Så du kan se den knibe, jeg er i, <Name>. Det ding derude samler det forkerte ukrudt! Jeg vil gøre det umagen værd for dig at samle det, jeg har brug for. Bring mig nok dommeukrudt, så giver jeg dig en passende belønning.\n\nJeg har forstået, at de gerne plager floraen nær massegraven, nord for Brills kirkegård. Skynd dig, og pas på gnolderne i området."},
  [5541] = {n="Ammunition til Rumlskud", l="Bring Rumlskuds ammunition til Hegnar Rumlskud i Dun Frostbakke.", d="Hegnar Rumlskud sælger geværer ud af vejen til Ambolmar. Riffelskytter og mørtelhold bruger meget tid på at øve sig ude nær hans butik, og han mangler altid frisk ammunition.\n\nMen... den sidste kasse ammunition, jeg sendte ham, gik tabt undervejs. Min kurér sagde, at han havde slået lejr nær Den Grizzlede Hule, da en vindigo jagede ham væk... og tossen efterlod Rumlskuds ammunition!\n\n<Name>, kan du hente ammunitionen og tage den med til Rumlskud? Han har ventet på den, og jeg er sikker på, at han er ved at løbe tør."},
  [5545] = {n="Et Bundt Trængsler", l="Bring 8 Bundter Træ til Rælen ved Østdal Tømmerlejr.", d="Jeg har et rigtigt problem på hænderne. Jeg har en deadline, der tårner sig op for en ordre på træ, og jeg løber tør for tid. Ulvene og bjørnene nord herfra har jaget mine arbejdere væk fra de træbundter, de allerede har hugget.\n\nJeg har allerede talt med Stedfortræder Rainer om at rydde dyrene væk, men jeg har brug for nogen, der kan gå hen og samle træet for mig. Hvis du kan samle otte bundter træ til mig, når jeg måske min deadline."},
  [5623] = {n="Til Lysets Fordel", l="Tal med Præstinde Josetta i Elwynnskoven.", d="Hej igen, unge præst/præstinde. Tiden er kommet til, at du skal lære mere om vores religion. Når du har fuldført de opgaver, du har her i Nordshire, så søg Præstinde Josetta i Guldshire. Hun har mere at lære dig og har hørt, at du vokser dig stærk i Lysets veje. Hun ser frem til at undervise dig yderligere."},
  [5625] = {n="Lysets Klæder", l="Find Bjergbestiger Dolf og hel hans sår med Mindre Heal (Rang 2). Derefter giver du ham Kraftord: Sejhed og vender tilbage til Maxan Ambol i Kharanøs.", d="Det er normalt omkring nu, at en af dine kræfter bliver testet for at se, om de er værdige til at bære kapper, der angiver deres plads i kirken. Men for at være ærlig, så har jeg mere presserende sager at kigge på. En borger af Kharanøs kom lige herind og fortalte mig om en såret bjergbestiger lige uden for byen mod syd--hans navn er Dolf.\n\nDu heler Dolf og giver ham Sejhed, så anser jeg dig for at have bevist dig selv. Hvordan lyder det?"},
  [5626] = {n="Til Lysets Fordel", l="Tal med Maxan Ambol i Dun Frostbakke.", d="Hey! <Name>! Har du et øjeblik?!\n\nDu har fulgt Lyset længe nok nu til, at du har fundet vej til Maxan Ambol i Kharanøs. Han vil lære dig mere om den vej, du følger, og hvis du beviser dig værdig, giver han dig dit første sæt kapper, der angiver din stand som præst/præstinde.\n\nNu skal du af sted! Så snart du er færdig her, så gå gennem tunnelen--han venter på dig."},
  [5646] = {n="Mørkt Offer", l="Tal med Aelthalyste i Undergrunden.", d="Aelthalyste viser vores folk stor respekt ved at sende dem tilbage til mig for mere træning, og nu gør jeg det samme for hendes stamme.\n\nDu vender tilbage til Undergrunden, <Name>. Der, i Krigskvarteret, er hun klar til at lære dig mere om dit folk og deres måder. Gå derhen, og vent ikke længe."},
  [5648] = {n="Åndelighedens Klæder", l="Find Grunt Kor'ja og hel hendes sår med Mindre Heal (Rang 2). Derefter giver du hende Kraftord: Sejhed og vend tilbage til Tai'jin ved Barberbakken.", d="Du være klar til din første prøve, <Name>. Syd for Barberbakken, lige uden for byen, er en af vores grunts såret, mens hun kæmpede mod nogle af Stoltmoors gamle tropper. Hun klarer sig ikke så godt, og hun ville få stor gavn af, at en af vores egen kunne hjælpe hende. Find hende--hendes navn er Kor'ja--hel hendes sår, og giv hende vores forfædres velsignelse.\n\nGør du dette, og jeg tror, det er tilstrækkeligt bevis på, at du er klar til at gå videre på vores måder."},
  [5649] = {n="Til Åndelighedens Fordel", l="Tal med Tai'jin i Durdotar.", d="Ja, makker. Vores folk har sluttet sig til Horden, fordi de er gode for os. De er loyale, og de lærer os meget om ting som ære. Men vores gamle måder dør hårdt. Orkerne godkender måske ikke alle vores traditioner, men det betyder ikke, at vi ikke kan fortsætte med at praktisere nogle af dem i hemmelighed.\n\nDet ved du, og det er derfor, jeg sender dig til Tai'jin i Barberbakken. Hun lærer dig mere om vores historie. Hun lærer dig vores stammes måder. Gå til hende, når du er klar."},
  [5654] = {n="Svaghedens Forhekselse", l="Tal med Ur'kyo i Orgrimgrad.", d="Det er tid for dig at møde Ur'kyo, <Name>. Han er i Ånders Dal i orkbyen. Gå derhen og tal med ham. Det er tid for dig at lære mere om vores folks gamle måder. Det er tid, at du bliver optaget i cirklen og gjort til en sand præst for vores stamme."},
  [5673] = {n="Elunes Nåde", l="Tal med Præstinde Alathea i Darnassos.", d="Du ved, at du når som helst kan få adgang til en af vores trænere, <Name>, men der er nogle ting, vi ikke kan give videre til dig. En af dem er læren om din gudinde Elune. Hun giver særlige evner til sine trofaste, og hvis jeg ikke tager fejl, er det tid for dig at vende hjem til dit Månens Tempel for at blive testet.\n\nVend tilbage, når du kan, og tal med Præstinde Alathea."},
  [5722] = {n="Søgen efter den Tabte Taske", l="Søg i Ildsvælget efter Maur Gribetotems lig, og undersøg det for genstande af interesse.", d="Trolde er ikke det eneste, der interesserede Magatha i Ildsvælget. Hun har hørt, at en af hendes tjenere, en Maur Gribetotem, fandt noget besynderligt, mens han var i kløften, men han nåede aldrig at komme ud og vise hende det. Hun vil gerne have Maurs krop fundet--hvis den stadig findes--og alle tegn på, hvad han fandt, mens han forsøgte at tale med trollene.\n\nVend tilbage til Magatha med alle genstande af interesse, og jeg er sikker på, at hun vil være meget generøs i sin belønning.\n\nSøg igen kløften i de mørkeste områder af Orgrimgrad."},
  [5723] = {n="Test af en Fjendes Styrke", l="Søg Ildsvælget fra Orgrimgrad, dræb derefter 8 Ildsvælg-trolde og 8 Ildsvælg-shamaner, før du vender tilbage til Rahauro i Tordenklippe.", d="Under byen Orgrimgrad er de stærke væsner, kendt som trolde, begyndt at komme op til overfladen fra dybt under de lavafyldte tunneler. I sin evige godhed søgte Magatha at skabe fred med væsnerne, men de vendte sig mod hendes diplomater og dræbte dem. Hun vil ikke tillade en sådan behandling af taurernes folk, og nu betragter hun væsnerne som en trussel mod hele Horden.\n\nHun beder dig om at sætte en stopper for denne trolde-trussel, før den overvælder Horden nedefra. Find Ildsvælget og ødelæg dem alle."},
  [5724] = {n="Tilbagelevering af den Tabte Taske", l="Tag Grimtotem-tasken med til Rahauro i Tordenklippe.", d="Du finder en taske under taurens lig. Den er stadig klemt fast i hans arme, som om han prøvede at beskytte den, mens trollene angreb ham.\n\nDu løsner tasken fra hans skruestiks-greb, gemmer den sammen med dit eget udstyr og gør dig klar til at finde vej ud af tunnelerne og tilbage til Rahauro i Tordenklippe."},
  [5725] = {n="Kraften til at Ødelægge...", l="Tag bøgerne Skyggernes Besværgelser og Besværgelser fra Nether med til Varimatras i Undergrunden.", d="Mange indbyggere i Legionen giver gaver til deres følgere, som du sikkert ved. Nogle af disse gaver mener Den Mørke Dame, ville være bedre stillet i hendes hænder end i hænderne på dem med... ringere syn.\n\nEn sekt af Skyggerådet, skjult i huler under Orgrimgrad og kendt som Svidende Klinge, er et oplagt eksempel. Damen fortæller mig, at medlemmer af Svidende Klinge er kommet i besiddelse af to kraftfulde besværgelsesbøger--hun vil gerne “låne” disse bøger af dem. Du skal skaffe dem til hende."},
  [5726] = {n="Skjulte Fjender", l="Bring et Løjtnantens Insignia til Trael i Orgrimgrad.", d="Én ting vil jeg ikke tolerere, og det er forrædere i vores midte, <Name>. Men jeg ville være en tosse at spille mit kort så tidligt--det ville ikke skære korruptionen tilstrækkeligt ud af vores lande og kun få infektionen til at vokse sig værre.\n\nMen du, en ung eventyrer, kunne komme steder, mine agenter ikke kunne... kunne lære sandheden... kunne finde det sande hoved på udyret.\n\nHvis du er modig nok, så gå ind i Kranieklippen øst for Orgrimgrad, find et løjtnantens insignia på en af de Brændende Klinge der, og vend tilbage til mig."},
  [5727] = {n="Skjulte Fjender", l="Tag Løjtnantens Insignia med til Neeru Ildklinge og tal med ham. Mærk efter, om han tror, du er medlem af Brændende Klinge, og vend derefter tilbage til Trael i Orgrimgrad.", d="Lad os nu se, om det insignia, du fandt, er besværet værd.\n\nDer er en heksemester i byen, som tror, han har min tillid. Han aner ikke, at jeg ved, hvor hans sande loyalitet ligger. Han er faktisk lederen af Brændende Klinge. Men skynd dig ikke at kaste dig ud i kamp med ham; han har et formål, og vi skal bruge ham mod vores fjender.\n\nTag dette insignia med til ham i Skyggeklyngen her i Orgrimgrad, tal med ham og se, om han tror, du er en af hans egne, og vend derefter tilbage til mig her."},
  [5728] = {n="Skjulte Fjender", l="Dræb Bazzelan og Jergosh Påkalderen, før du vender tilbage til Trael i Orgrimgrad.", d="Hmm, lederne af Svidende Klinge... det bekymrer mig mest. Hvis det er dem, Neeru sætter pris på, så er det dem, vi må angribe først. Den satyr... Bazzelan, og den anden Neeru nævnte - hvad var han, en heksemester? - skal slås ihjel.\n\nVend tilbage til Skyggeklyngen og gå ind i Ildsvælget, <Name>. Find de to ledere af Svidende Klinge og dræb dem. Men pas på, at Neeru ikke får at vide, at det var dig, der gjorde det. Du skal bevare din identitet som en af hans brødre/søstre i våben."},
  [5729] = {n="Skjulte Fjender", l="Tal med Neeru Ildklinge i Orgrimgrad.", d="Jeg tror, at vores næste skridt bør være at få dig placeret tæt på Neeru. Hvis han er så oprevet, som rapporterne antyder, kan vi opnå to ting. For det første kan du måske få noget større kendskab til Rådet eller i det mindste til Brændende Klinge, og for det andet begynder han måske at stole nok på dig til at bede dig om at hjælpe ham. Han kan meget vel se på dig som en, der kan udfylde tomrummet, nu hvor noget af ledelsen er i uorden.\n\nVend tilbage til Kløften og tal med ham igen, men vær ikke for åbenlys."},
  [5730] = {n="Skjulte Fjender", l="Tal med Trael i Orgrimgrad og fortæl ham, hvad du har lært.", d="Du er en af mine løjtnanter! Gør dig klar, <Class>. Jeg kalder snart på dig.\n\nMin tid brugt på Svidende Klinge kan nu være næsten spildt, men det betyder ikke, at Skyggerådets planer andre steder skal lide. Jeg vil gøre, hvad jeg kan, for at begrænse skaden her i Ildsvælget. I mellemtiden lader jeg mine agenter i Ødemarken og Askedalen begynde arbejdet med vores nyeste dagsorden. Vend snart tilbage til mig."},
  [5741] = {n="Lysets Scepter", l="Find Lysets Scepter og bring det tilbage til Azore Gammelmørk i tårnet i Ethel Rethør.", d="Brændende Klinge i Tordenøkse-fæstningen mod øst siges at have skaffet sig Lysets Scepter fra Slangefolket. Sagnet fortæller, at scepteret kan sænke hele byer under de store have. Brændende Klinge må ikke få lov til at besidde sådan magt.\n\nDerfor skal du selv hente scepteret! Det holdes af en seer fra Brændende Klinge, som studerer scepteret fra toppen af et af Tordenøkse-vagttårnene."},
  [5761] = {n="Bæstets Død", l="Gå ind i Ildsvælget, dræb Taragaman den Sultne, og bring hans hjerte tilbage til Neeru Ildklinge i Orgrimgrad.", d="Den primære opgave, som vores store krigshøvding har givet mig, er at udrydde de væsner, der har forurenet vores herres store by med dæmonisk indflydelse. Brændende Klinge er én trussel, men der er andre; Svidende Klinge for eksempel, som har hjemme i Ildsvælget og i hemmelighed forsøger at underminere uskyldige medlemmer af Horden.\n\nHvis de skal stoppes, må deres leder slås ihjel - en Helvagt ved navn Taragaman den Sultne.\n\nDræb ham, og hans hjerte ville Trael tilfreds, det er jeg sikker på."},
  [5762] = {n="Hemet Jagtvarys", l="Tag Kravels Kasse med til Hemet Jagtvarys i Kvælerdorn.", d="Jeg har en pakke til en gammel kunde af mig, en dværg ved navn Hemet Jagtvarys. Pakken tog flere uger om at komme frem, og Hemet er taget af sted for længst. Han sagde, at han skulle til Kvælerdorn for at jage bæsterne dér, men han efterlod mig nogle penge, så jeg kunne sende hans levering, når jeg fik tid.\n\nHemet er en rig dværg, og det er en god idé at holde forbindelsen til de rige, ikke sandt? Så... vil du levere pakken for mig?\n\nJeg har hørt, at Hemet har en lejr i Kvælerdorn, nord for Grommegol."},
  [5763] = {n="Jagt i Kvælerdorn", l="Bring Roons Kodo-horn til Hemet Jagtvarys i Kvælerdorn.", d="For længe siden kom en dværg til dette land. Hans navn var Hemet, og han ville jage de store bæster. Hans færdigheder med riflen var uhyggelige, og vi tilbragte mange dage på jagt sammen. Selv fjendskabet mellem vores folk blev glemt.\n\nDa han forlod Forødelse for Kvælerdorn, lovede jeg, at jeg en dag ville byde ham velkommen tilbage, så vi kunne jage igen. Nu er tiden kommet.\n\nTag dette kodo-horn med til Hemet. Han vil vide, at det er fra mig. Du finder ham i Kvælerdorn, nord for Grom'gol-basislejren."},
  [5881] = {n="Kalder på Reserverne", l="Mavgran vil have dig til at levere et brev til Grish Langløber ved Den Store Hejs i Ødemarken.", d="Horden klarer sig godt med at holde vores tropper friske... siden Den Store Krig har vi haft fremgang her i Kalimdør.\n\nJeg har brug for, at du gør mig en tjeneste. Jeg har en knægt ved navn Grish Langløber, som vogter Den Store Hejs i de sydlige ødemarker. Giv ham dette brev; brevet vil fortælle ham, at jeg har en reservekriger på vej for at afløse ham, så han kan besøge sin familie. Han bad om det for noget tid siden, og han vil blive glad for at høre nyheden."},
  [6027] = {n="De Ældgamles Bog", l="Find De Ældgamles Bog og bring den tilbage til Azore Gammelmørk i tårnet i Ethel Rethør.", d="<Name>, jeg betror dig Slangens Ædelsten. Placer denne ædelsten i Slangestatuens hånd på Ranazjar-øen, en lille ø mod nordvest herfra. Når den er placeret, vil den kalde på den, der beskytter De Ældgamles Bog. Denne bog indeholder slangefolkets hemmeligheder, hemmeligheder der er blevet bevaret i århundreder. Bring mig bogen, så lærer vi meget om vores skæl-prydede fjender!"},
  [6122] = {n="Den Primære Kilde", l="Brug den tomme Prøvetager fra Klippefjeder-faldene til at tage en vandprøve fra hulens munding ved faldene.\n\nLever den fyldte Prøvetager fra Klippefjeder-faldene til Alanndarian Nattesang i Auberdin, Mørkekysten.", d="Klippefjeder-faldene i Mørkekysten fungerer som regionens primære kilde til drikkevand, og nu mistænker jeg, at de også er den primære kilde til giften, der skader det lokale dyreliv - især hjortene. Brug denne prøvetager til at hente lidt vand fra hulens munding; vær forsigtig, for farlige slanger holder nu til i en hule ved faldene.\n\nNår den er fyldt, skal du levere den til Alanndarian Nattesang i Auberdin. Hun er den, der bad om vores hjælp, og du skal arbejde sammen med hende for at tackle denne plage."},
  [6123] = {n="Samling af Helbredelsen", l="Bring 5 Jordrod og 12 Månesvampe til Alanndarian Nattesang i Auberdin, så hun kan lave en helbredende salve.", d="Vandet bliver grundlaget for den helbredende salve, jeg vil lave til hjortene. Til helbredende egenskaber har jeg brug for noget jordrod. Urtekyndige ved, hvordan man finder det, så hvis vi er uheldige, og du ikke er en af dem, må du finde nogen, der kan hjælpe os.\n\nTil sidst skal jeg bruge noget til styrke: månesvampe. Månesvampeblomster er nemme nok at finde; de er over alt i hulerne lige øst for her. Månekin bor i hulerne, og de har været irritable på det seneste, så vær forsigtig."},
  [6124] = {n="Helbredelse af de Syge", l="Brug den Helbredende Dyresalve på 10 Syge Hjorte, der befinder sig rundt omkring i Mørkekysten; det skulle kurere dem. Syge hjorte er blevet rapporteret fra et sted syd for Klippefjeder-floden, nord for Auberdin, og helt ned i det sydlige Mørkekyst, hvor kanten af Askedalen begynder.", d="Mængden af salve, der er lavet af de ingredienser, du bragte mig, er god nok til ti doser, <Name>. Mens jeg arbejder sammen med landsbyen om at lave mere salve, vil jeg gerne have, at du hjælper os med at komme et skridt foran. Over hele Mørkekysten findes syge hjorte; brug salven på dem og kur deres utilpashed.\n\nDendrit Stjerneblus i Månelunden vil helt sikkert gerne tale med dig, når du er færdig. Giv venligst Auberdins tak videre til Cenarion-kredsen dér... og lad mig selv sige tak til dig for hjælpen!"},
  [6126] = {n="Nye Lektioner", l="Rejs til Månelunden og tal med Dendrit Stjerneblus i landsbyen Nathavn.", d="Du er nu klar til at lære om gift og den magt, vi druider har over den, <Name>. Cenarus har velsignet os med evnen til at rense selv de mest ækle gifte med blot en besværgelse. Denne gave må ikke tages let... og for at sikre, at du lærer denne lektion, skal du arbejde med at håndtere forgiftningers virkninger, som en almindelig mand ville gøre.\n\nRejs til Månelunden og tal med Dendrit Stjerneblus; han venter på din ankomst for at begynde din lektion."},
  [6127] = {n="Den Primære Kilde", l="Brug den tomme Prøvetager fra Rædselståge-toppen til at tage en vandprøve fra en pøl på toppen af bjerget.\n\nLever den fyldte Prøvetager fra Rædselståge-toppen til Tonja Runetotem ved Korsvejen, Ødemarken.", d="Rædselståge-toppen mod nordvest for Korsvejen er sandsynligvis den primære kandidat til kilden til giftens spredning. Dens luftige toppe har søer, der påvirker vejrmønstrene. Jeg mistænker, at vandet nu er forurenet af den dæmonelskende Brændende Klinge.\n\nBrug denne prøvetager til at hente vand fra søen helt øverst på toppen. Når den er fyldt, skal du levere den til Tonja Runetotem ved Korsvejen. Han er den, der bad om vores hjælp, og du skal arbejde sammen med ham for at tackle denne plage."},
  [6128] = {n="Samling af Helbredelsen", l="Bring 5 Jordrod og 5 Kodo-horn til Tonja Runetotem ved Korsvejen, så han kan lave en helbredende salve.", d="Vandet bliver grundlaget for den helbredende salve, jeg vil lave til gaseller. Til helbredende egenskaber har jeg brug for noget jordrod. Urtekyndige ved, hvordan man finder det, så hvis du ikke er fortrolig med den færdighed, må du finde nogen, der kan hjælpe os.\n\nTil sidst skal jeg bruge kodo-horn til styrke - blot splinter og stumper vil ikke være nok. Kodoer, som du kan klare, vandrer rundt i den nordlige del af Ødemarken; bring nogle ned for den større balances skyld <Name>, og hent hornene til mig."},
  [6129] = {n="Helbredelse af de Syge", l="Brug den Helbredende Dyresalve på 10 Syge Gaseller, der befinder sig rundt omkring i den nordlige del af Ødemarken; det skulle kurere dem. Syge gaseller er blevet rapporteret nord for den øst-vest-vej, der går gennem Korsvejen.", d="Jeg har kunnet lave nok salve til ti doser helbredelse, <Name>. Mens jeg arbejder sammen med de lokale myndigheder om at lave mere salve, vil jeg gerne have, at du hjælper os med at komme et skridt foran. Over hele den nordlige Ødemark går syge gaseller; brug salven på dem og kur deres utilpashed.\n\nDendrit Stjerneblus i Månelunden vil helt sikkert gerne tale med dig, når du er færdig. Giv venligst vores tak videre til Cenarion-kredsen dér... og lad mig selv sige tak til dig for hjælpen!"},
  [6130] = {n="Magt over Gift", l="Vend tilbage til Turak Runetotem på Ældrehøjen i Tordenklippe.", d="Du har lært, hvad det betyder at kurere gift uden hjælp fra åndelig styrke. Husk, hvad andre må udholde, når de kæmper mod giftige lidelser, mens du snart omfavner din nyfundne magt over gift.\n\nDu bør nu vende tilbage til Turak Runetotem i Tordenklippe, <Name>. Han har uden tvivl en meget vigtig besværgelse at lære dig, nu hvor eleven har forstået lektionen, han eller hun blev givet.\n\nFarvel, unge druide. Vi ses igen."},
  [6161] = {n="Gør krav på Rackmores Skat!", l="Find Rackmores Sølvnøgle. Find Rackmores Guldnøgle. Find og åbn Rackmores Kiste.", d="Rackmores logbog fortæller, hvordan hans skib sejlede mod Fjermåne-fæstningen, da det blev angrebet af havskabninger. For at forhindre at hans skat faldt i fjendens hænder, gemte han sin kiste på Ranazjar-øen.\n\nFor at åbne kisten kræves to nøgler, en sølv og en guld. Disse nøgler gik tabt, men hvis nøglerne og kisten findes, venter der en skat!"},
  [6181] = {n="Et Hurtigt Budskab", l="Bring Lewys' Seddel til Tor, gryfonmesteren.", d="Selvom vi ikke får meget hjælp fra Stormvind direkte, har jeg en kontakt i byen, der hjælper os med at skaffe rustning. Hans navn er Osric Stræng. Hans butik, Begrænset Immunitet, ligger i Stormvinds Gamleby.\n\nVores forsyning af rustning svinder, og jeg må kontakte Osric for mere. Kan du tage ham denne seddel?\n\nDen hurtigste vej til Stormvind går gennem Tor, vores gryfonmester. Han er bare nede ad bakken; bring ham min seddel, og tag derefter en gryfon til Stormvind."},
  [6261] = {n="Dungar Langdrik", l="Bring Osrics Kasse til Dungar Langdrik, gryfonmesteren.", d="<Name>, jeg har samlet alt, Lewys bad om, i denne kasse. Kan du tage den med til ham?\n\nHvis du allerede har talt med Tor i Vestfald, så kan du tage en gryfon tilbage til ham. Dungar Langdrik er vores gryfonmester, over i handelsdistriktet.\n\nTal med Dungar, og få derefter denne kasse til Lewys så hurtigt som muligt. Vi vil ikke have, at vores kæmpende mænd og kvinder i Vestfald må undvære frisk udstyr!"},
  [6281] = {n="Fortsæt til Stormvind", l="Køb en gryfon-tur af gryfonmesteren Tor, bring derefter Lewys' Seddel til Osric Stræng, i butikken Begrænset Immunitet, i Stormvinds Gamleby.", d="For et lille gebyr kan du tage en gryfon til Stormvind, så du kan levere Lewys' seddel til Osric. Du kommer ikke hurtigere frem på nogen anden måde.\n\nHvis det lyder acceptabelt, så tal bare med mig igen, når du er klar til turen. Jeg tager lidt betaling, men stol på mig; det er det værd!"},
  [6282] = {n="Harpyerne Truer", l="Mavgran Jordbinder i Solklippe-tilflugtsstedet vil have dig til at slå 7 Blodraser-harpyer, 7 Blodraser-baghvaskere, 7 Blodraser-dræbere og 7 Blodraser-forræderfjer ihjel.", d="Taurerne er stolte over at være beskyttere af disse lande. Du kan uden tvivl gætte, hvorfor jeg er alarmeret over antallet af harpyer, der holder til her i Stenklippe.\n\nBlodraserne er kilden til det stigende antal harpyer i Kalimdør; de trænger ind i alt levende og forhindrer de uskyldige i at forlade deres områder.\n\nJeg har brug for, at du udrydder harpyerne, <Name>!"},
  [6283] = {n="Blodraser-blodlinjen", l="Mavgran i Solklippe-tilflugtsstedet vil have dig til at slå Blodraser-Rivekløen ihjel og bringe hendes rester tilbage som bevis på din gerning.", d="At begrænse antallet af Blodraser-harpyer vil ikke være nok. Den eneste sande kur mod deres sygdom ville være at slå deres leder, Blodraser-Rivekløen ihjel!\n\nHun er næsten en dronning for de skidtede væsner. Slå hende ihjel, og deres antal vil helt sikkert falde.\n\nGå tilbage ind i Den Brændte Dal, så finder du hende langs de vestlige bakker. Hun vil ikke være let at besejre, men belønningen bliver stor."},
  [6284] = {n="Edderkoppefobi", l="Dræb Besselet og bring Besselets Hugtand til Mavgran i Solklippe-tilflugtsstedet.", d="Advarsel: Gå ind i Sishir-kløften mod vest på egen risiko.\n\nBesselet og hendes otteben-ede skovbørn har gjort kløften til deres spindelvævs-hule.\n\nMavgran Jordbinder i Solklippe-tilflugtsstedet har sat en dusør på Besselet. Slå hende ihjel og bring bevis på din dræbning til Mavgran; dér vil du modtage din belønning for at have fjernet denne otteben-ede plage."},
  [6285] = {n="Tilbage til Lewys", l="Køb en gribbeflyvetur til Vagtbakken hos gribbemesteren Dungar Langdrik, og tag derefter Osrics Kasse med til Lewys i Vagtbakken.", d="Gribbemesteren i Vestfald er Tor. Hvis du har talt med ham før, kan du tage en af mine gribbe hen til ham.\n\nDet er en god lektie at kende: gribbene er altid trænet til at flyve til deres hovedstad, men de tager dig kun til en fjern gribbemester, efter du allerede har været der.\n\nDu har allerede været hos Tor, så tal bare med mig igen, når du er klar til at tage en gribbe til Vestfald. Når du er der, kan du aflevere Osrics Kasse til Kvartermester Lewys."},
  [6301] = {n="Genfødslens Kredsløb", l="Tammra Vindmark i Solklippe-tilflugtsstedet vil have dig til at samle 10 Gaia-frø.", d="Industriel grådighed og en evig krig har ødelagt Stenklippes lande. Kun Jordmoderens velsignelser kan læge sådan et sår.\n\n<Name>, jeg skal bede dig om at finde et særligt frø, Gaia-frøet. De findes kun her i Stenklippe-bjergene, nord for Solklippe-tilflugtsstedet ved Mirkfallon-søen, nær vandkanten.\n\nNår du bringer mig frøene, vil jeg indgive dem shamansk kraft, så de vokser hurtigere."},
  [6321] = {n="Forsyninger til Gravkammeret", l="Bring Podrigs Bestilling til Karos Razok.", d="Eksekutor Hadrec bad mig om at gøre status over vores udstyr i Gravkammeret. Med Svøben, og noget værre, lurende i skovene, ønsker han ikke, at Dødevagterne skal mangle det udstyr, de måtte have brug for.\n\nJeg fandt ud af, at vi generelt er velforsynede, men vi har virkelig brug for flere våben til at erstatte dem, der er gået tabt i felten.\n\nHer er en rekvisitionsseddel over det, der er brug for, til våbenhandleren Gordon Vendham i Undergrunden. Tag bestillingen med til vores flagermusmester, Karos Razok, og tal med ham om transport til Undergrunden."},
  [6323] = {n="Flyvetur til Undergrunden", l="Køb en flagermusetur til Undergrunden hos flagermusmester Karos Razok, og tag derefter Podrigs Bestilling med til Gordon Vendham i Undergrunden.", d="En af mine flagermus kan tage dig til Undergrunden for et lille gebyr. Tal med mig igen, når du er klar, så vi kan arrangere din transport.\n\nDu finder Gordon Vendham i Handelskvarteret i Undergrunden. Det er netop det kvarter, hvor min flagermus lander."},
  [6324] = {n="Tilbage til Podrig", l="Køb en flagermusetur til Gravkammeret hos flagermusmester Mikael Garrett, og bring derefter Gordons Kasse til Dødevagt Podrig i Gravkammeret.", d="Flagermusmesteren i Gravkammeret er Karos Razok. Hvis du allerede har mødt ham, kan jeg give dig en flagermus, så du kan flyve tilbage til ham.\n\nVores flagermus flyver altid til Undergrunden, men for at rejse til mere afsidesliggende steder må rytteren først besøge området og tale med dets flagermusmester.\n\nDu har mødt Karos i Gravkammeret, så du kan nu flyve med flagermus derhen. Tal med mig igen, når du er klar."},
  [6365] = {n="Kød til Orgrimgrad", l="Bring Zarghs Kød til Devrak i Korsvejen.", d="Jeg har nogle udsøgte stykker kød, som jeg gerne vil sende til en ven. Hun hedder Gryshka og er kroejer i Orgrimgrad. Vil du levere kødet for mig?\n\nDen hurtigste vej til Orgrimgrad er med en vindrytter. Tag kødet med til vindrytter-mesteren i Korsvejen, Devrak, og tal med ham om transport til Orgrimgrad."},
  [6381] = {n="Nyt Liv", l="Plant 10 Gaia-frø i Gaia-jordhøjene, og returner derefter de resterende Fortryllede Gaia-frø til Tammra i Solklippe-tilflugtsstedet.", d="Som du har set, <Class>, er livets kredsløb en mægtig ting, selvom landet lider. Nu må vi gøre vores del for at hjælpe det på vej. Du skal plante disse frø midt i ødelæggelsen, mod vest, i Den Brændte Dal. Pas på, for harpyer og vrede ildelementarer plager stadig det ardrede land.\n\n<Name>, tag disse fortryllede Gaia-frø og plant dem i frugtbare jordhøje. Livets kredsløb må fortsætte!"},
  [6382] = {n="Jagten i Askedalen", l="Tal med Senani Torduhjerte i Splintertræ-Posten, Askedalen.", d="Din styrke imponerer mig, <Class>. Din vilje til at omfavne jagten giver mig tillid til, at du kan gå videre til større vildt... og større udfordringer.\n\nSkovene i Askedalen er en enorm, utæmmet vildmark, som Horden søger at pålægge sin egen vilje, både politisk og åndeligt. Hvis du vil bevise dig selv i et uprøvet land, så søg vejledning hos Senani Torduhjerte i Splintertræ-Posten. Forposten ligger direkte nord for stien, der fører fra Ødemarken."},
  [6383] = {n="Jagten i Askedalen"},
  [6384] = {n="Flyvetur til Orgrimgrad", l="Køb en vindrytter til Orgrimgrad hos vindrytter-mesteren Devrak, og bring derefter Zarghs Kød til Gryshka i Orgrimgrad.", d="For blot få mønter sørger jeg for, at en vindrytter tager dig til Orgrimgrad. Når du er der, kan du tage Zarghs Kød med til Gryshka. Hendes kro ligger i Styrkens Dal, ikke langt fra Himmeltårnet, hvor min vindrytter sætter dig af.\n\nTal med mig igen, når du er klar til rejsen."},
  [6385] = {n="Doras, Vindrytter-mesteren", l="Bring Gryshkas Brev til Doras i Orgrimgrad.", d="Jeg har skrevet et takkebrev til Zargh. Vil du levere det for mig? Hvis du allerede har været i Korsvejen og talt med deres vindrytter-mester, kan du flyve med en vindrytter derhen.\n\nTag mit brev til Doras, vindrytter-mesteren i Orgrimgrad, og tal med ham om transport til Korsvejen."},
  [6387] = {n="Æresstuderende", l="Bring Brocks Liste til Thorgrum Borrelsen i Tælsamar.", d="Jeg ser en masse unge dværge ved min dør, ivrige efter at lære minedriftens håndværk. Og hvis der er én ting, en minearbejder har mere brug for end noget andet, så er det en hakke!\n\nJeg har en liste over minestuderende, der scorede højt i deres lektioner og har fortjent en æreshakke. Tag min liste med til Golnir Klippetå i Jernsmede. Han vil gøre hakkerne klar.\n\nDen hurtigste vej til Jernsmede er på en gribbe, så tag listen med til vores gribbemester, Thorgrum Borrelsen, og tal med ham om transport til Jernsmede."},
  [6388] = {n="Gryth Tordenvold", l="Bring Æreshakkerne til Gryth Tordenvold i Jernsmede.", d="Her er æreshakkerne til Brocks elever. Hvis du allerede har været i Tælsamar, så burde du flyve med en gribbe derhen!\n\nTag hakkerne med til vores gribbemester, Gryth Tordenvold, og tal med ham om en tur tilbage til Tælsamar."},
  [6391] = {n="Flyvetur til Jernsmede", l="Køb en gribbe til Jernsmede hos gribbemesteren Thorgrum Borrelsen, og bring derefter Brocks Liste til Golnir Klippetå i Jernsmede.", d="For blot få mønter tager en af mine gribbe dig til Jernsmede. Derfra skal du aflevere Brocks liste til Golnir Klippetå. Du finder ham i Dybbjergs Mineklan. Det ligger i Det Store Smedjedistrikt i Jernsmede, lige dér hvor min gribbe sætter dig af!\n\nTal med mig igen, når du er klar til rejsen."},
  [6392] = {n="Tilbage til Brock", l="Køb en gribbe til Tælsamar hos gribbemesteren Gryth Tordenvold, og bring derefter Æreshakkerne til Brock Stensøger i Tælsamar.", d="For et lille gebyr kan du købe en gribbetur til Tælsamar... så længe du allerede har været der. Gribbene flyver kun dig til steder, du allerede har været, så sørg for at tale med hver gribbemester, du møder, så du senere kan flyve til ham.\n\nDu har allerede været hos Thorgrum, gribbemesteren i Tælsamar, så nu kan du vende tilbage til ham. Og når du er i Tælsamar, kan du aflevere hakkerne til Brock Stensøger.\n\nTal med mig, når du er klar til at tage afsted."},
  [6393] = {n="Elementarkrigen", l="Bring 10 Incendriter til Tsunaman i Solklippe-tilflugtsstedet.", d="Tidevandets Tribunal har sendt mig for at føre krig mod ildelementarerne her i Stenklippe-bjergene. Neptulon Tidevandsjægeren, herre over alle vandelementarer, har taget et personligt ønske om at se vores flammende fætre slukket.\n\n<Name>, du kan hjælpe mig med at vinde Tribunalets gunst ved at ødelægge ildelementarerne i Den Brændte Dal. Når de er ødelagt, efterlader ildelementarerne Incendriter. Bring dem til mig, så får du din belønning."},
  [6394] = {n="Thazz'rils Hakke", l="Bring Thazz'rils Hakke til Formand Thazz'ril.", d="<Name>, du er en pålidelig <Race>. Kan jeg regne med dig til endnu en opgave?\n\nFor noget tid siden var jeg ude og undersøge hulen mod nord for mineraler, og der glemte jeg min yndlingshakke. Da jeg senere vendte tilbage for at hente den, fandt jeg hulen fyldt med onde bæster! Vil du gå ind i hulen, Brændende Klinge-hekseriet, og hente min hakke?\n\nJeg lod den ligge i et kammer med vandfald. Min hakke har en besværgelse på sig, så du kan se den i mørket, så du ikke behøver bekymre dig om at finde den... bare hvad der vogter den!"},
  [6395] = {n="Marlas Sidste Ønske", l="Bring Samuel Fipps' Rester til Marlas Grav, og vend derefter tilbage til Novice Elret.", d="Min ven Marla Fipps boede sammen med sin mand Samuel før pesten, men da pesten kom, faldt Samuel og sluttede sig til Svøbens rækker.\n\nMarla blev skånet for at blive udød, kun for at dø i hænderne på sin nu sjælløse mand. Hendes kærlighed var dog så stærk, at hendes sidste ønske på dødslejet var at blive begravet sammen med sin elskede Samuel.\n\nSamuel Fipps vandrer rundt i en ødelagt lejr ved vejen nordøst for Dødsklokken. Besejr ham og opfyld Marlas ønske: begrav ham ved hendes grav, i den første række af vores gravplads."},
  [6401] = {n="Kaya Lever", l="Fortæl Tammra Vindmark i Solklippe-tilflugtsstedet de gode nyheder.", d="Fortæl Tammra Vindmark, Kayas moster, som er i Solklippe-tilflugtsstedet, de gode nyheder! Kaya lever! Vi troede, hun var væk efter det brutale angreb på vores landsby. Følg stien mod vest for at komme til Solklippe-tilflugtsstedet."},
  [6421] = {n="Klippeskred-kløften", l="Udforsk dybt inde i hulen i Klippeskred-kløften, og bring 10 Resonit-krystaller tilbage til Mor'rogal i Solklippe-tilflugtsstedet, så han kan undersøge dem.", d="Der er noget galt her i Stenklippe. Kan du mærke spændingen i luften, <Name>?\n\nSydøst herfra ligger en dyb hule i Klippeskred-kløften. Kobolderne dér graver febrilsk efter en sjælden krystal kaldet Resonit. Jeg har brug for, at du bringer nogle malmprøver med tilbage, så jeg kan forstå, hvad der sker i den hule. Jeg har også brug for, at du undersøger, hvor dyb hulen er.\n\nGå af sted, unge <Class>, det er afgørende, at jeg ved, hvilket ondt der lurer under disse bjerge."},
  [6441] = {n="Skovbuk-horn", l="Saml 16 Skovbuk-horn til Pixel i Splintertræ-Posten.", d="Hej! Jeg har rejst gennem Askedalen på vej mod Skralleby, og jeg besluttede mig for at holde en pause her i Splintertræ. Jeg leder altid efter en mulighed, og det ser ud til, at skovbukkehorn er meget eftertragtede i Skralleby i øjeblikket.\n\nEfter at have spurgt lidt rundt her, ser det ud til, at skovbukkene i Nattebanen, Satyrdalen og Xavian alle har den type horn, jeg leder efter. Jeg kan ikke måle mig med de skovbukke... men du ser ud til at kunne det!\n\nHør, saml hornene for mig, så skal jeg nok sørge for, at det er din tid værd."},
  [6442] = {n="Slangefolk ved Zoram-strandbredden", l="Bring 20 Vredhale-hoveder til Marukai langs Zoram-strandbredden.", d="Der lurer noget ondt her langs kysten, <Race>.\n\nDet er hvilestedet for den dødsdømte by Zoram, længe ødelagt og sunket under havet. Tabt og næsten glemt.\n\nNu er slangefolkene vendt tilbage, og af hvilken grund ved vi ikke. Men grunden betyder lidt; vi må forsvare det land, vi har slidt så hårdt for at gøre til vores eget.\n\nKom tilbage til mig med 20 af deres hoveder! Smid slangefolkene tilbage i dybet!"},
  [6461] = {n="Blodsugerne", l="Xen'zilla i Malaka'Jin vil have dig til at dræbe 10 Dybmos-krybler og 7 Dybmos-giftspyddere.", d="Vi trolde her i Malaka'Jin har trives af landet; Stenklippe-bjergene byder på gode jagtmarker, som vi kan leve af.\n\nDesværre har vi fået de forkerte middagsgæster... edderkopperne i disse bjerge har raidet vores lejre om natten for at stjæle vores jagt.\n\nHvis du hjalp os med at udrydde de rædselsfulde bæster, ville vi i Malaka'Jin stå i din gæld. Edderkopper findes overalt i Stenklippe - gå bare nord herfra, så ser du, hvad jeg mener."},
  [6462] = {n="Trolleamulet", l="Bring 8 Trolleamuletter til Mitsuwa i Zoram'gar-forposten.", d="Mine slægtninge var på vej hertil med mange hellige trolleamuletter, men Tistelpels-pelsbolgerne angreb og dræbte dem, før de nåede Zoram'gar! Disse modbydelige Pelsbolge!\n\nJeg savner mine brødre og søstre, der blev dræbt, men vi vil mødes igen i det hinsides. Deres trolleamuletter har dog stor værdi i denne verden. Det er en skandale, at pelsbolgerne har dem!\n\n<Name>, du må hente amuletterne! De ligger i kister i Tistelpels-fæstningen, en hule for enden af Tistelpels-landsbyen, nord for Stjernelund."},
  [6481] = {n="Jordvæsnets Opvågning", l="Åbn Resonit-tønden med den Fortryllede Resonit-krystal, og dræb derefter Goggeroc. Vend tilbage til Mor'rogal med nyheden og den Fortryllede Resonit-krystal.", d="Du har afdækket en mørk trussel mod landet, <Class>. Resonit-tønden, du fandt i hulen, huser et sovende jordvæsen ved navn Goggeroc.\n\nJeg har ændret blandingen af de Resonit-krystaller, du samlede, med mine shamanistiske kræfter. Tag den fortryllede Resonit-krystal og slå Resonit-tønden i stykker, den der huser jordvæsnet.\n\nNår det vækkes, vil Goggeroc være svækket... Dræb ham, <Name>!"},
  [6482] = {n="Frihed for Ruul", l="Eskortér Ruul, og tal derefter med Yama Snefod i Splintertræ-Posten.", d="Hæh? Hvem er du?\n\n<Name>? Du er ingen pelsbolg! De er forbandede! De troede, jeg var en bjørn, og fangede mig, og nu sulter de mig! Mine kræfter svinder...\n\nHjælp mig med at flygte, og tal derefter med min søster Yama ved Splintertræ-Posten mod øst.\n\n<Name>! Jeg må flygte!"},
  [6503] = {n="Askedalen-løberne", l="Dræb 9 Askedalen-løbere, og vend derefter tilbage til Kuray'bin ved Splintertræ-forposten.", d="Vi har fået meldinger om, at Askedalen-løbere forlod Sølvvinge-forposten for ikke længe siden, og nu sniger de sig rundt i skoven tæt på vores territorier. Vi vil ikke have, at de indsamler efterretninger om vores forsvar!\n\nSnig dig gennem skovene syd for vores post her og øst for Alliance-forposten Sølvvinge. Find og slå løberne ihjel, og vend derefter tilbage til mig."},
  [6504] = {n="De Forsvundne Sider", l="Find de 12 manglende sider af Makulatorens Brugsanvisning, og sæt dem sammen, så de danner kapitel 1, 2 og 3. Returner siderne til Gurda Vredesarr nær Splintertræ-Posten.", d="Jeg har lige fået fat i denne makulator fra Skralleby, og jeg var på vej tilbage til Krigssang-tømmerlejren, hvor jeg skal være på vagt. Jeg fik en brugsanvisning til, hvordan man betjener makulatoren, men på turen tilbage blæste en kraftig vindstød den ud af mine hænder. Siderne spredtes over det hele, og alt, jeg havde tilbage, var forsiden.\n\nSiderne kunne vel være næsten hvor som helst nu... men jeg ved ikke, hvordan man bruger makulatoren uden dem! Vil du finde dem til mig?"},
  [6521] = {n="En Unhellig Alliance", l="Bring Ambassadør Malcins Hoved til Varimatras i Undergrunden.", d="Malcin påstår, at han befinder sig uden for Tornehøjene. Denne ambassadør skal slås ihjel—hans mission er en fiasko i Liskekongens øjne.\n\nHans tilstedeværelse dér forklarer en stor del af det, vi har opdaget om området—nogle af Stiftsvinene er blevet frygtindgydende stærke, mens de viser tegn på Pesten på deres egen måde. Det må være tegn på en slags aftale, de har indgået.\n\nFind Malcin og slå ham ihjel, <Name>. Vend tilbage til mig, når gerningen er gjort."},
  [6522] = {n="En Unhellig Alliance", l="Tag den Lille Rulle til Varimatras i Undergrunden.", d="Min Frue,\n\nDu ved meget godt, hvad det er, vi tilbyder. Muligheden for, at du kan tage Ødemarken og landene hinsides den, er stor. Vi ønsker blot din hjælp til gengæld. Med hjælp mener vi intet mere end, at du giver os frihed til at handle i området.\n\nVær venlig at lade os diskutere dette nærmere. Vi har stor magt og er villige til at dele den med dem, der er vise nok til at slutte sig til os. Jeg vil blive uden for Tornehøjene i den nærmeste tid.\n\nDe bedste hilsner,\nAmbassadør Malcin"},
  [6541] = {n="Rapport til Kadrak", l="Aflever rapport til Kadrak ved vagttårnet i det nordlige Ødemarken.", d="Har du nogensinde været i Askedalen, mod nord? Horden har for nylig oprettet en forpost ved Zoram-strandbredden dér, og vi kan altid bruge nye rekrutter til at forsvare vores nye frontlinjer.\n\nHvis du mener, du er klar til det, så find Kadrak i det nordlige Ødemarken, ved vagttårnet. Han leder Askedalen-kampagnen og kan give dig yderligere ordrer."},
  [6542] = {n="Rapport til Kadrak", l="Aflever rapport til Kadrak ved vagttårnet i det nordlige Ødemarken.", d="Har du nogensinde været i Askedalen, mod nord? Horden har for nylig oprettet en forpost ved Zoram-strandbredden dér, og vi kan altid bruge nye rekrutter til at forsvare vores nye frontlinjer.\n\nHvis du mener, du er klar til det, så find Kadrak i det nordlige Ødemarken, ved vagttårnet. Han leder Askedalen-kampagnen og kan give dig yderligere ordrer."},
  [6543] = {n="Krigssang-rapporterne", l="Åbn Rapportbundtet. Tag Krigssang-rapporterne til Krigssang-spejderen, Krigssang-løberen og Krigssang-forriderne. Bring de opdateringer, de giver dig, tilbage til Kadrak ved det nordlige vagttårn i Ødemarken.", d="Jeg har for nylig sendt nogle få spejdere ind i Askedalen, og jeg har brug for en løber, der kan tage deres ordrer med dem og bringe mig en rapport om, hvad de har set.\n\nDit første stop bør være Zoram'gar-forposten, langs kysten mod vest, ved Zoram-strandbredden, for at finde den første løber. Du skal også stoppe ved Splintertræ-Posten mod nord og langs vejen mod øst, nær Azshara. Der finder du en spejder og en forrider.\n\nGiv dem hver en rapport, og hent en opdatering om deres fund."},
  [6544] = {n="Toreks Angreb", l="Eskortér Torek i hans angreb mod Sølvvinge-forposten og Duriel Månebrand, og rapportér derefter til Ertog Vredestand ved Splintertræ-Posten.", d="Hej! <Class>! Kom herhen!\n\nMine krigere og jeg er ved at angribe Sølvvinge-forposten mod vest. Vores mål er dens leder, Duriel Månebrand. Spejderne melder, at forposten er tungt forsvaret med vagter og krigere. Slaget bliver herligt!\n\nVil du dele æren, <Name>, og hjælpe os? Hvis ja, så kan du, når det er forbi, rapportere vores succes til min overordnede, Ertog Vredestand i Splintertræ.\n\nHvad siger du? Er du med os?"},
  [6545] = {n="Krigssang-løberens opdatering"},
  [6546] = {n="Krigssang-forriderens opdatering"},
  [6547] = {n="Krigssang-spejderens opdatering"},
  [6548] = {n="Hævn for Min Landsby", l="Dræb 8 Grimtotem-bøller og 6 Grimtotem-lejesoldater, og vend derefter tilbage til Makaba Fladhov nær den sydøstlige kant af Stenklippe.", d="Grimtotem-klanen overfaldt min landsby og dræbte næsten alle. Jeg dræbte, hvem jeg kunne, men slap næppe med livet i behold.\n\n<Name>, alt, hvad jeg nu ønsker, er, at flere af dem er døde. Du finder dem lige vest for her."},
  [6561] = {n="Den Sorte Afgrunds Skurkeri", l="Bring hovedet af Tusmørkeherre Kelrik til Bashana Runetotem i Tordenklippe.", d="Styrken har forladt mig. Din hjælp er nødvendig!\n\nFor længe siden var dette sted et stort tempel for Elune. Men uheld førte til ruin, da korruptionen fra en af De Gamle Guder sivede op fra jordens dyb og besmittede den hellige Månebrønd.\n\nAku'Maj, en tjener af den Gamle Gud, steg op af vandet.\n\nTusmørkets Hammer-kultisterne har indgået alliance med slangefolket for at besætte disse grunde. Kultisterne, ledet af Kelrik, ofrer uskyldige til Aku'Maj for magt.\n\nSlå Kelrik ihjel og bring hans hoved til Bashana i Tordenklippe, <Name>, vær så venlig."},
  [6562] = {n="Besvær i Dybet", l="Tal med Je'neu Sancrea i Askedalen.", d="Je'neu Sancrea har brug for hjælp. Han befinder sig ved Zoram'gar-forposten i Askedalen. Nattealfernes skov ligger nord for Stenklippe-bjergene. Du kan nå dertil ved at rejse gennem Vindskær-klippen eller ved at gå nordpå gennem Ødemarken. Zoram-strandbredden ligger langt mod vest for skoven. Vær forsigtig, <Name>. Der er kræfter dér, som ikke tager pænt imod din tilstedeværelse."},
  [6563] = {n="Aku'Maj-essensen", l="Bring 20 Aku'Maj-safirer til Je'neu Sancrea i Askedalen.", d="I de tidlige tunneller i Den Sorte Afgrund kan man finde store klynger af safir langs hulevæggene. For nylig blev det bemærket, at slangefolket høstede krystallerne. Indtil vi kan finde ud af hvorfor, mener jeg, at vi bør forhindre slangefolket i at lykkes. Krystallerne har stor elementær kraft, og hvis de bruges forkert, kunne de blive en kraftfuld arkan komponent.\n\nVil du hjælpe mig, <Name>? Den Sorte Afgrund ligger langs Zoram-strandbredden, nord for vores forpost."},
  [6564] = {n="Troskab mod De Gamle Guder", l="Bring den Fugtige Seddel til Je'neu Sancrea i Askedalen.", d="Noget dårligt håndskrift er skrevet på den sammenkrumpede seddel:\n\n\"Ja, sig til alle præstinderne, at de skal bringe krystallerne til mig. Vandelementarånderne er stærke i dem, og de vil hjælpe vores akvamanter meget i deres egne besværgelser.\n\nVed at kontrollere kraften i krystallerne vil vi formilde Aku'Maj. En dag vil vi have magt nok til at bringe Aku'Maj tilbage til os, og verden vil vende tilbage til sin største tidsalder! En tidsalder med De Gamle Guders herredømme!\""},
  [6565] = {n="Troskab mod De Gamle Guder", l="Dræb Lorgus Jett i Den Sorte Afgrund, og vend derefter tilbage til Je'neu Sancrea i Askedalen.", d="Denne følger af Tusmørkets Hammer må ikke få lov til at fuldføre sin plan. Tusmørkets Hammer forstår ikke naturens ånder. De tror på De Gamle Guder—skabninger af kaos og ødelæggelse, der for længe siden blev besejret. Denne Lorgus må ikke få lov til at lykkes. Du må stoppe ham, <Name>. Jeg kan ikke selv—jeg er for svag.\n\nGå ind i Den Sorte Afgrund, find ham og dræb ham. Vend tilbage til mig her ved Zoram'gar, når det er gjort."},
  [6571] = {n="Krigssang-forsyninger", l="Saml Krigssang-forsyningerne: Krigssang-savklinger, Tømmerreb, Krigssang-olie og Krigssang-øksforsendelsen til Locke Okarr i Splintertræ-Posten.", d="Vi er ved at løbe tør for nogle få ting ved Krigssang-tømmerlejren!\n\nPrikken ved Splintertræ-Posten har vores forsendelse af savklinger. Det kræver en tur til Bytteviken for at hente en kasse økser fra Havnemester Lozgyl.\n\nVores forsendelse af olie og reb bliver vanskeligere. Rebet blev stjålet af Tistelpels- og Rådskov-pelsbolgene, og skovbukkene opsnappede leveringen af olien og bruger den nu til afskyelige ritualer i Nattebanen, Satyrdalen og Xavian!\n\nKan du hjælpe mig?"},
  [6581] = {n="Krigssang-savklinger"},
  [6621] = {n="Rådskovens Konge", l="Placér Karangs Banner på Rådskov-totemhøjen. Lad ikke pelsbolgene ødelægge banneret. Besejr Høvding Murgut, og bring Murguts Totem til Karang Hammerstrøm i Zoram'gar.", d="<Name>, en anden stamme af pelsbolge, Rådskov-stammen, lever sydøst for Stjernelund. De er ikke så mange som Tistelpels-stammen, men deres vildskab udgør en fremtidig trussel. Med en demonstration af styrke kan vi fjerne den trussel.\n\nTag dette banner, gå til Rådskov-landsbyen og placér det på deres totemhøj. De vil forsøge at ødelægge banneret, men hold din plads, indtil deres høvding, Murgut, dukker op for at redde stammens ansigt. Bring mig den totem, han bærer.\n\nSaml dine allierede, <Name>. Dette er ingen opgave for én enkelt <Class>."},
  [6626] = {n="Et Ondt Værk", l="Dræb 8 Rasorhegn-krigsvagter, 8 Rasorhegn-tornevævere og 8 Dødningehoved-kultister, og vend tilbage til Myriam Månesanger nær indgangen til Tornehøjene.", d="De Forladte viderefører ikke deres... sygdom... efter, hvad jeg har set. Denne diplomat synes at give dem udødelighed, der vil blive tilhængere. Jeg begynder at tro, at han er en af Svøben.\n\nNu er min bekymring dog ikke med ham, men med de voksende rækker omkring ham. De kryber frem fra skyggerne dagligt og tigger næsten om mere magt.\n\nJeg er ikke mægtig nok til at bekæmpe dem alene, <Name>. Hvad siger du? Er du klar til lidt jagt?"},
  [6629] = {n="Dræb Grundig Mørkeskye", l="Dræb Grundig Mørkeskye og 6 Grimtotem-brutaler, og vend tilbage til Makaba Fladhov nær den sydøstlige kant af Stenklippe.", d="<Name>, du har gjort et fint stykke arbejde med at dræbe Grimtotem. Hvis du tør, er Grundig Mørkeskye og hans personlige bande af brutaler det værste af det hele. Han var den, der ledede det brutale angreb på min landsby.\n\nDu finder ham i Grimtotem-posten lidt længere op ad stien mod vest. Dræb ham, så vil jeg være evigt taknemmelig."},
  [6641] = {n="Vorsha Piskeren", l="Hold Muglash i live, mens han rejser til ildskålen. Hjælp ham ved at slukke ildskålen, og beskyt ham derefter, mens du kæmper mod slangefolket.\n\nHvis det lykkes, så vend tilbage til Zoram'gar-forposten og informér Krigssang-løberen om Vorsha Piskerens død.", d="Vorsha Piskeren... det djævelske hydra, der hærger havene...\n\nHun har angrebet vores forpost, hver gang uden provokation, og lagt alt øde, der falder i hendes vej.\n\nMen jeg er klar, <Name>. Jeg har forberedt mig på at overgå hydraen og få en ende på disse angreb på Zoram'gar.\n\nSlangefolket hylder dette udyrs onde natur med en ildskål, der forbliver tændt på en ø lige ud for kysten. Jeg tror, at hvis vi slukker den, vil Vorsha dukke op i vrede.\n\nVi får brug for hjælp, så sørg for at medbringe nogle stærke allierede."},
  [6661] = {n="Dybløbs-rottejagten", l="Fang 5 Dybløbs-rotter ved hjælp af Rottefængerens Fløjte. Led rotterne tilbage til Monty. Glem ikke at aflevere fløjten, når du er færdig.", d="Hej, din skibsrotte! Arrr... Arrr, leder du efter arbejde? Vi har et alvorligt rotteproblem her nede, og for få hænder på akterdækket.\n\nHvad siger du? Alt, du skal gøre, er at tage denne rottefængerfløjte og spille melodien for skadedyrene. De følger dig til jordens ende!\n\nFang bare fem af de små krabater og bring dem tilbage hertil. Vi har brug for dem levende.\n\nArrrrr..."},
  [6662] = {n="Min Bror, Snusse", l="Tag Kassen med Mysteriekød hen til Snusse ved Stormvinds Dybløbs-sporvognsdepot.", d="Min bror, Snusse, driver en rottekebab-forretning på den anden side af Dybløb. I skal tage den her kasse rotter med til ham, før de bliver dårlige. Skynd jer lidt!\n\nI har vel kørt med sporvogn før, ikke? Det er nemt. Bare træd om bord, når den ankommer, og nyd turen. Og hold jeres arme og ben inde under køreturen, for ellers ender I som træben resten af livet."},
  [6681] = {n="Herregården, Ravnehold", l="Tag Ravnehold-seglet hen til Fårhad ved Ravnehold-herregården, gemt væk i bakkerne i Hillsbrad.\n\nDin snedighed vil blive sat på prøve undervejs. Vær forberedt.", d="<Name>,\n\nRavnehold har fået øje på dig, unge tyv. Vi har holdt øje. Din stil er lidt klodset, men intet vi ikke kan rette op på.\n\nSkulle du være klar til at begive dig ud i en karriere som discipel for Mester Ravnehold og medlem af Snigmorderligaen, skal du blot bringe Ravnehold-seglet (vedhæftet dette brev) til Ravnehold-herregården.\n\nDin første opgave er at finde herregården, gemt væk i bakkerne i Hillsbrad, og vise din snedighed.\n\nMed venlig hilsen\n\nFårhad"},
  [6921] = {n="Blandt Ruinerne", l="Bring Dybkernen til Je'neu Helligkrea ved Zoram'gar-forposten, Askedalen.", d="Tusmørkets Hammer har flyttet ind i Månehelligdoms-ruinerne i Den Sorte Afgrund. Deres tilstedeværelse kan kun tjene til at tvinge elementerne til at arbejde mod os. Hvis det får lov at fortsætte, bliver regionen deres for evigt.\n\n<Name>, gå ned i Den Sorte Afgrund og find ruinens dybdesten; den burde ligge et sted tæt på i vandet. Inde i den ligger en dybkerne - en genstand, som hvis den læses rigtigt, vil fortælle hele historien om alt elementarisk aktivitet. Hvis jeg får den, kan jeg og Jordringen måske gøre noget for at stoppe dem!"},
  [6922] = {n="Baron Akvanis", l="Bring den Mærkelige Vandkugle til Je'neu Helligkrea ved Zoram'gar-forposten, Askedalen.", d="Det besejrede vandelemental har efterladt en mærkelig vandkugle. Du regner med, at genstanden på en eller anden måde gav uhyret energi. Inde i kuglen skvulper en rådden-udseende form af vand rundt. Selve kuglen virker upåvirkelig over for enhver form for fysisk kraft.\n\nHvis nogen kan finde ud af noget ved denne genstand, er det Je'neu Helligkrea fra Jordringen. Han befinder sig ved Hordens Zoram'gar-forpost i Askedalen."},
  [6981] = {n="Det Glødende Skår", l="Rejs til Skralleby for at finde nogen, der kan fortælle dig mere om det glødende skår.\n\nLever derefter skåret, som du bliver anvist.", d="Skåret er et strålende grønt, og selvom det er fast, snor noget, der ligner røg, sig lige under overfladen. Du kan ikke lade være med at stirre ned i krystallens dybder; samtidig ved du, at der er noget yderst foruroligende ved det.\n\nMåske skulle du se, om nogen i Skralleby kan fortælle dig mere om dette mærkelige skår."},
  [7321] = {n="Beroligende Skildpaddebisque", l="Bring 10 stykker Skildpaddekød og noget Beroligende Krydderier til Christoph Frakkesen i Tarrenmølle.", d="Hvem siger, at de døde ikke kan noget med mad? Tag min hemmelige opskrift på skildpaddebisque, for eksempel. Jeg har kendt folk, der ville vende tilbage fra de døde bare for at nyde en skål! Hi, hi...\n\nApropos det, jeg har ikke kunnet lave noget på det sidste. Jeg plejede selv at tage over til Lordamere-søen for at jage snapjaws, de ulækre skabninger, men jeg kan ikke slippe mit arbejde her.\n\nHvis du bringer mig noget Skildpaddekød fra snapjaws og beroligende krydderier, viser jeg dig, hvordan det gøres!"},
  [7383] = {n="Jordens Krone", l="Fyld Ametystfiolen og bring den tilbage til Corithras Månevred i Dolanår.", d="Alt var dog ikke som det skulle være i Teldrasil. Hjorthelms omhyggeligt udtænkte planer for det nye Verdenstræ havde udspillet sig, som han havde håbet, men der var ét lille problem, et problem som mange af vanskelighederne i Teldrasil kan tilskrives.\n\nJeg vil dog ikke komme ind på det endnu. Du må besøge den sidste månebrønd, mod nordvest i Orakellunden. Under grenene på Orakeltræet ligger den første og mest kraftfulde af vores brønde. Hent en fiol med dens vand og vend tilbage til mig."},
  [7802] = {n="En Donation af Uld"},
  [7807] = {n="En Donation af Uld"},
  [7808] = {n="En Donation af Silke"},
  [7813] = {n="En Donation af Uld"},
  [7820] = {n="En Donation af Uld"},
  [8311] = {n="Helligaftens Godter til Jesper!", l="Tal med kroværterne i Stormvind, Jernsmede og Darnassos, samt med Talvash af Kissel i Jernsmede. Udfør de fiduser, de beder dig om, til gengæld for de godter, de tilbyder.\n\nVend tilbage til Jesper i Stormvinds Børnehjem med en Darnassos Marcipan, en Nisseborg-gummibamse, et Stormvinds Nougat og en Jernsmede-mynte.", d="Jeg vil gerne ud og gå i udklædning og tigge slik, men det kan jeg ikke, for jeg er syg. Hvis du går for mig, vil jeg bytte dig det slik, du får, for noget, jeg allerede har! Jeg tror, du vil synes godt om det slik - det får dig til at forvandle dig til ting, som både er sjove og skræmmende!\n\nHver af kroværterne i de store byer har slik, de giver ud til Helligaftens Ende - tal med dem og gør de fiduser, de beder om! Og så uddeler en lille gnom ved navn Talvash i Jernsmede også slik. Når du har alt slikket, så bring det tilbage til mig her!"},
  [65602] = {n="Hvad Er Kærlighed?", l="Hent Træfiguren og bring den til Gakin Mørkbinderen i Magikerkvarteret i Stormvind.", d="Du får brug for et kraftfuldt reagens for at friste en incubus -- en genstand, der repræsenterer stor hengivenhed og kærlighed.\n\nMed min synske kunst har jeg lokaliseret en lille figur, der burde være passende til dit ritual.\n\nFor tusinder af år siden tilhørte figuren et ungt par. De oprindelige ejere er ikke mere, men deres kærlighedsminde har overlevet til i dag.\n\nFølg vejen nordpå ind i Askedalen, derefter mod vest og forbi Maestras Post. Du vil se et hus gemt ind mellem træerne. Der finder du det, du søger."},
  [65610] = {n="Ønsker Du Var Her", l="Undersøg Faldne Himmelsø i Askedalen og rapporter dine fund til Gan'rul Blodøje i Orgrimgrad.", d="Jeg mødte Krillet, mens jeg lavede Månekludetøj i Askedalen. Han var stationeret der for at beskytte civilister mod fare, indtil han forsvandt...\n\nDe har holdt op med at lede efter ham og betragter ham som desertør, men det tror jeg ikke på.\n\nVi plejede at mødes ved Faldne Himmelsø, før den blev overrendt af de aggressive mosevæsener.\n\nJeg er ikke typisk den, der beder om tjenester, men hvis du ville tage til Askedalen og lede efter tegn på ham, ville jeg sætte pris på det."},
