  [78147] = {n="Forbrydelser mod Anatomien"},
  [78148] = {n="Runer fra Troldmandskongerne"},
  [78149] = {n="Landets Raseri"},
  [78150] = {n="Bibliotekets Ven"},
  [78261] = {n="Xelthos-hornet", l="Find Xelthos-hornet inde i Skyggetandsborgen. Returnér det derefter til C's dødbrevkasse nær Brandtræ-landsbyen. Du skal udføre jobbet alene.", d="<En seddel ligger i kisten>\n\nHej, <Name>.\n\nJeg ønsker mig en skat ved navn Xelthos-hornet, som befinder sig et sted inde i Skyggetandsborgen.\n\nAt begive sig ind i fæstningen kræver normalt forstærkninger. Til dette job er en lav profil dog af yderste vigtighed.\n\nDu må gå alene.\n\nJeg har en kontakt ved navn Vænix i Stenklippe-bjergene. Han burde kunne hjælpe dig forbi gårdens portåbning. Resten er op til dig.\n\nReturnér hornet hertil, så bliver din betaling sendt kort efter.\n\n- C"},
  [78676] = {n="Bhossca-øjet", l="Find Bhossca-øjet inde i Det Skarlagenrøde Kloster. Returnér det derefter til C's dødbrevkasse nær Brandtræ-landsbyen. Du skal udføre jobbet alene.", d="<En seddel ligger i kisten>\n\nDejligt at have dig tilbage, <Name>.\n\nMit nyeste ønske er en artefakt kendt som Bhossca-øjet. Mine kilder fortæller mig, at øjet befinder sig et sted inde i Det Skarlagenrøde Kloster. Ligesom med Skyggetandsborgen må du trænge ind i klosteret alene.\n\nDet kan være en god idé at finde en forklædning, inden du går ind. Det gør det lidt lettere at bevæge dig rundt. Jeg er sikker på, at du kan finde noget på klosterets område.\n\nReturnér øjet hertil, så leveres betalingen som før.\n\n- C"},
  [78823] = {n="Ørkenhimlens Rædsel", l="Bring den primitive tegning til Hemmet Jagtvarys i Kvælerdorn.", d="Tegningen er opbygget af grove, brede streger og forestiller tilsyneladende en stor rovfugl. Trods den enkle komposition har kunstneren tydeligvis set dette væsen med frygt og ærefrygt. En ekspert i storvildt kunne sandsynligvis fortælle dig mere."},
  [78830] = {n="Ørkenhimlens Rædsel", l="Hent en Karmosinrød Trofæfjerpen fra Harrik i Ødelandene. Vend derefter tilbage til Hemmet Jagtvarys i Kvælerdorn.", d="Denne tegning minder mig om en historie, jeg hørte på en anden ekspedition for ikke længe siden. Jeg fik fortalt om en stor fugl, Harrik, der hersker over Ødelandene som topprædator.\n\nHun blev sidst set nordøst for Lejr Cagg. Måske er hendes rede et sted i nærheden?\n\nDu skal bruge levende lokkemad for at lokke hende frem. Jeg låner dig et bur, så du kan fange noget. Småt vildt er sjældent i Ødelandene, så du må finde din lokkemad andetsteds.\n\nEn fjer fra Harrik ville være en fin præmie. Du ville helt sikkert blive snakkens emne i lejren."},
  [79007] = {n="... og den seddel du fandt", l="Seddelens forkullede rester er din eneste vejviser.", d="<Glødens svage skær bliver mørkere, og du snubler over resterne af en nylig ild.\n\nMidt i de spredte forsyninger finder du en blærende seddel.>\n\n\"Ikke alt, der brænder, er tabt. Find tvillingland, find stedet.\""},
  [79008] = {n="... og den seddel du fandt", l="Seddelens forkullede rester er din eneste vejviser.", d="<Glødens svage skær bliver mørkere, og du snubler over resterne af en nylig ild.\n\nMidt i de spredte forsyninger finder du en blærende seddel.>\n\n\"Ikke alt, der brænder, er tabt. Find tvillingland, find stedet.\""},
  [79091] = {n="Ærkemager Antonidas: Den Uforkortede Selvbiografi"},
  [79092] = {n="Ærkemager Teokritos' Forskningsdagbog"},
  [79093] = {n="Rumi fra Nisseborgen: Samlede Værker"},
  [79094] = {n="Ta'zos Lektioner"},
  [79095] = {n="Apotekerens Metafysiske Grundbog"},
  [79096] = {n="Ataerik: Om Arkane Kuriositeter"},
  [79097] = {n="Baxtan: Om Destruktiv Magi"},
  [79192] = {n="Trædesten", l="Du river seddelen af planken og læser den kradsede skrift.", d="Seddelen begynder med: \"Missionen sagde, at de begge var i gang med leverancer for Den Nye Pest. Ser ud til simple apoteker-uheld for mig. Find mit hyggelige sted i bjergene mellem Ødemarken og Forødelse, hvis du vil have et sikkert sted at tale.\""},
  [79229] = {n="Landevejsrøveri", l="Find nogen i Forødelse, der kender til den plyndrede lejrplads.", d="Lejrpladsen foran dig er en makaber scene. Døm efter resterne var ofrene to mennesker og en dværg. Mærkerne på knoglerne tyder på et brutalt angreb, men de plyndrede forsyninger viser, at det ikke var et dyr. Sårene passer heller ikke til kentaurernes våben.\n\nMåske ville en erfaren asseplyndrer i disse lande vide, hvad man skal gøre ud af dette."},
  [79242] = {n="Ingen Ære Blandt Tyve", l="Find Illari Skumringsfjer på kysten af Arathi-højlandet, og få adgang til hendes skjulte lager af stjålet bytte.", d="Som jeg sagde...\n\nVores chef var ikke med Horden. Hun var en nattealf ved navn Illari Skumringsfjer. Hun gav os efterretninger om lejrene og lod os endda beholde det meste af byttet. Hun beholdt kun et par af de sjældneste fund.\n\nDa marskalken dog var os i hælene, lod hun os i stikken. Jeg ved ikke, hvad hendes motiver var, men jeg tror, vi blev stillet op som syndebukke.\n\nJeg er ikke den hævngerrige type, men jeg vil ikke stoppe andre i at jage hende. Hvis du leder efter hende, nævnte hun engang et skjulested på kysten af Arathi."},
  [79358] = {n="Storm, Jord og Ild", l="Saml 5 Forvredne Ildtotemer, 5 Forvredne Jordtotemer, 5 Forvredne Luftotemer og 5 Forvredne Vandtotemer til Veyric Tordenhame i Arathi-højlandet.", d="At oversvømme Tusindnåle er ingen lille bedrift, <Name>. Hvis jeg ikke selv havde mærket elementernes vrede, ville jeg aldrig have troet på det. Men her er vi.\n\nKvilboarerne er ikke de første til at bruge elementerne uforsvarligt, og de bliver heller ikke de sidste. Hvis vi vil forberede vores eget modritual, må vi forstå disse forvredne elementer bedre. Tag den her bog. Den beskriver de mange væsener i Azerot, og hvordan de praktiserer shamanisme.\n\nHvis du kan lære af dem, kan vi måske finde en løsning."},
  [79361] = {n="Storm, Jord og Ild", l="Saml 5 Forvredne Ildtotemer, 5 Forvredne Jordtotemer, 5 Forvredne Luftotemer og 5 Forvredne Vandtotemer til Prate Skyseer i Tusindnåle.", d="Så kvilboarerne vil oversvømme Tusindnåle med deres forvredne shamanisme, gør de? Det virker næsten utænkeligt, men du har selv set, at disse væsener ikke skal tages let på.\n\nJeg havde ønsket at fortsætte din træning for alvor, men der er ikke tid til det nu. Disse lande er hjem for mange forskellige væsener, venner og fjender lige meget, og ingen af dem fortjener en sådan skæbne. Vi må handle.\n\nTag denne tome. Den var beregnet til studier, men kan nu måske rumme nøglen til at sprede den kommende storm."},
  [79362] = {n="Grants Skjold", l="Find Grants Stridsklub på et af skeletterne på Ravnehøj-kirkegården, og vend derefter tilbage til Sirra Von'Indig i Mørkeshire for mere information.", d="Et skjold efterladt af spøgelset af Grant Tapper, far til Tapper-familien og helt fra Ravnehøj.\n\nNår Grants ånd stadig kæmper mod de udøde, var hans uafsluttede forretning måske at slå den svøbe ned, der sårede ham på Ravnehøj-kirkegården. Det er sandsynligvis den, hans stridsklub stadig sidder fast i."},
  [79363] = {n="Silvias Sværd", l="Besejr 7 Defias-nattekniver og 7 Defias-fortryllere i Addles Gård, og vend derefter tilbage til Sirra Von'Indig i Mørkeshire for mere information.", d="Et sværd efterladt af ånden af Ravnehøjs vagt, Silvia Tapper, der viede sit liv til at beskytte civile og deres hjem.\n\nNår Silvias ånd stadig besøger gårde, var hendes uafsluttede forretning måske at drive de defias væk, der har slået sig ned i Addles Gård syd for Ravnehøj."},
  [79366] = {n="Hør Mit Kald", l="Brug de Forvredne Totemer til at sætte en stopper for kvilboarernes ritual.", d="Nu hvor du har de forvredne totemer, må vi bruge dem til at fremkalde de korrumperede elementarer, som kvilboarerne kalder på. Besejr dem for at rense disse lande og sætte en stopper for Barbermankens afskyelige ritual, og aflever derefter din succes hos Rau Klippeløber.\n\nDu bør begynde din rensning ved dampbassinerne mod vest. Området er rigt på hvert af elementerne. Men pas på, <Name>. Kvilboarerne vil ikke sidde stille, mens du forstyrrer deres planer.", c="Vend tilbage til Rau Klippeløber i Frihvind-posten og fortæl, hvad der skete."},
  [79535] = {n="Basilisker: Bør Forstening Frygtes?"},
  [79536] = {n="Større Bibliotekets Ven"},
  [79947] = {n="Geomani: Den Stenkolde Sandhed"},
  [79948] = {n="Forsvarsmagi 101"},
  [79949] = {n="Et Spind af Løgne: Afsløring af Myter og Sagn"},
  [79950] = {n="Dæmoner og Dig"},
  [79951] = {n="Mumier: En Guide til de Usmagelige Udøde"},
  [79952] = {n="GrrlGrrlGrrlGrrl!"},
  [79974] = {n="Vådt Job", l="Du støver en budbringertaske af jorden, der stikker op af jorden, og finder et pergament gemt blandt forsyningerne.", d="\"Har altid kunne lide at have en reserveskjult skat i nærheden, for den lille chance at jeg må flygte i en fart.\n\nBjergsidens ansigt er så smukt, at man næsten kunne sige, det er udhugget af tidens vandfald. \r\nDet er ørnereden, det er den, du leder efter.\""},
  [79975] = {n="Ørnens Næve", l="Vandsprøjt dugger luften, og udsigten er fantastisk.", d="<Du finder et omhyggeligt foldet brev inde i værktøjskassen.>\n\n\"Herfra kan du, med de rette værktøjer, bestemme spillereglerne. Et fantastisk sted at starte en faldskærmsglider.\n\nMin loyalitet over for Ørnen og Næven kræver afstand, for at kunne tjene dem bedst. Denne barrikade har set bedre dage, ligesom De Gamle Kongeriger, den engang forsvarede, men jeg vil aldrig forlade den.\""},
  [79976] = {n="Dette Må Være Stedet", l="Hvem end der var her, missede du dem lige.", d="\"Så jeg har besluttet at tage mit arbejde tilbage under jorden. For at forhindre, at det havner i de forkerte hænder.\"\n\n<Papiret er revet præcis stort nok til at passe beskeden. Du er ikke sikker på, om det er de sidste ord, du læser fra forfatteren, eller om de er et spor til det næste skjulested. En dårligt sikret sovepose ruller sig selv ud over dine fødder...>"},
  [79980] = {n="Kravl", l="Find det, der venter dig.", d="\"Ikke så slemt, hva'? Siden du læser dette, betyder det, at mit depot stadig er der. Tag hundrede skridt lige mod nord, og bræk ikke dine ankler, når du går ned ad den stejle klippeside. Der burde være nok til at holde dig i gang.\""},
