  [84402] = {n="Nekromanti 101"},
  [86574] = {n="Stenklippe-forsyningstur", l="Saml 6 Stenklippe-forsyninger fra Stolthedsvinge-vingedrager, og lever dem til Kroværtinde Farlia.", d="<Den uheldige krop her bærer præg af mange hug fra Stolthedsvinge-vingedragerne. Pakken i nærheden er krøllet og smidt væk, med indholdet væk, og kun en lille seddel klemt i budbringerens hånd fortæller, hvad der gik tabt: en forsendelse beregnet til Kroværtinde Farlia på Stenklippe-toppen.>\n\n<Vingedragerne har sikkert båret forsyningsbundtene væk for at fore deres reder.>"},
  [86576] = {n="Blodraser-tingester", l="Bring 15 Glitrende Solsten til Mor'rogal Hønsefar.", d="Ud over at sprede deres skidt ud over Den Brændte Dal, samler Blodraser-harpyerne alt blankt, de kan finde. Jeg har hørt, at de samler på alle mulige gulgyldne solsten til pynt. Jeg har ingen brug for sådan noget tingest, men Mor'rogal Hønsefar har nævnt at bruge dem før.\n\nMens du kæmper mod harpyerne i dalen, så hold øje med Glitrende Solsten. Bring dem, du finder, til Mor'rogal Hønsefar, deroppe på bakkerne over os."},
  [86585] = {n="Banneret for De Faldne", l="Hejs Jernsmedes standart, lok troggen Hovedkløveren frem og dræb den, og meld derefter tilbage til Kaptajn Rugelfuss.", d="Den faldne bjergbestiger bærer en standart fra Jernsmede. Måske spejdede hun, eller gjorde et dømt angreb. Uanset hvad er standarten væltet og trampet ned. Bjergbestigeren fik et så hårdt slag i hovedet, at hendes hjelm blev slået af, og hun blev dræbt på stedet af en trogg, sandsynligvis med en pigget kølle.\n\nTroggen, der dræbte hende, er sikkert stadig i nærheden, og den husker sikkert banneret. Hvis man hejser Jernsmedes banner igen, kan det måske lokke den frem."},
  [86614] = {n="Sølv fra Bølgerne", l="Returner det monogrammerede sølvhårspænde til dens ejer.", d="<Blandt fiskeritingesterne i affaldet ligger nogle rustne kroge, ødelagte viklinger af tråd og et lidt tærende, men pyntet sølvhårspænde med monogrammet \"K.D.\">"},
  [86667] = {n="Snefanget", l="Bring en krukke sne til Norric Søthane i hans hus på Søens nordvestkyst.", d="Min gamle mentor, Norric, sendte et mindre elementar med en underlig anmodning. Han har brug for en krukke sne til nogle af sine shamaniske fremstillinger! Jeg aner ikke, hvad han har tænkt sig at bruge det til, men jeg lærte for længe siden ikke at stille spørgsmål ved hans metoder, når det gælder magi.\n\nJeg har travlt med at lære om de lokale elementarer, så jeg kan ikke tage af sted og hjælpe ham. Gå til tunnelindgangen ved Sydportens Pas, hvor der ligger sne hele året. Skovl noget op i denne keramiske krukke og bring det til ham, før det smelter. Krukken burde holde det koldt."},
  [86776] = {n="Ingredienser til Smedjen", l="Bring 10 Bronzebarrer til Morhan Kobbertunge.", d="Tælsamar er et godt sted at bo, men vi har ikke alle de bekvemmeligheder, Jernsmede har. Jeg løber konstant tør for bronze! Jeg har brug for mere bronze, hvis jeg skal blive ved med at lave værktøj, kedler og gryder!\n\nJeg kan se, du har lidt erfaring ved essen. Tror du, du kunne smelte nogle bronzebarrer til mig? Jeg betaler dig godt for det!"},
  [86784] = {n="Pinde og Knogler", l="Saml 6 Tørre Grene og bring dem til Eleanor Stakkelton.", d="Min kollega Eleanor Stakkelton er stolt af at rejse i det vilde og overleve mod vejr og monstre. Hun har slået lejr ikke langt herfra, i bakkerne mod vest, og jeg husker et råd, hun engang gav mig: \"Når du tror, du har nok brænde, så saml fem gange mere.\"\n\nHvis du har tid til overs, kunne du samle lidt træ i denne kurv og tage det med til hendes lejr. Jeg er sikker på, at hun kunne give dig et par tips om livet som omrejsende eventyrer."},
  [87318] = {n="De Fortabtes Hjerter", l="Led efter Cormas makker Essene.", d="Thandol-spændet har været et farligt sted, siden Mørkjernsdværgene sprængte broen, men jeg regnede ikke med at støde ind i dem der!\n\nJeg slap væk, men jeg mistede min makker, Essene, af syne. Jeg har ledt overalt efter hende, men jeg har ikke fundet et eneste spor. Har Mørkjernsdværgene taget hende til fange? Faldt hun i floden nedenunder? Nåede hun tilbage til den anden side? Jeg ved det ikke! Jeg ved ikke engang, om hun er i live!\n\nVær sød, hvis du ser et spor af hende, så lad mig vide det!"},
  [87760] = {n="Hellig Dykker", l="Find en Stormskæl-dyrebetvingerske, dræb hende, og bring hendes Stav af Dyb Herredømme tilbage.", d="Jeg har fået svar tilbage fra Darnassos, <Name>!\n\nUd fra dyreprøverne har vi fundet ud af, at nagaerne har underlagt disse havskabninger, så de kan bruges som tvangsridt og trækdyr. De, der var for stædige, eller for gamle eller hårdt såret, har de jaget væk for sportens skyld. Monstrøst!\n\nDet er vores hellige pligt at sætte en stopper for dette!\n\nNagaerne har styrker i Matystras Ruiner, og de må være ved at snuppe tærskerhajer fra kysten. Find deres dyrebetvingerske, dræb hende, og bring hendes herredømmeredskaber tilbage!"},
  [88756] = {n="Bring en Smell Tilbage", l="Hent 3 Stjålne Sprængstoffer fra Mørkjernsdværg-lejrene.", d="Mørkjernsdværgene har et par lejre østpå her på Direforge-bakken, og de har stjålet en masse sprængstoffer fra vores byggeplads og slæbt 'em med tilbage til deres telte.\n\nJeg behøver ikke fortælle ya, hvilken slags ballade Mørkjernsdværge kan finde på te med en tønde krudt!\n\nJeg ved godt, at Mørkjernsdværgene er farlige, men vi har brug for de tønder tilbage. Du kan kende 'em fra andre tønder på de røde mærker. Vi kanne ikke lade Mørkjernsdværgene beholde 'em!"},
  [90902] = {n="Genfinding af Lyset", l="Hel 5 sårede Dødevagter med din evne Hellige Lys.", d="Jeg er stolt over at byde endnu en nyoprejst paladin velkommen i vores rækker. Når du begynder at genforbinde dig med lyset, vil du måske opdage, at visse evner, der engang var dig naturlige, nu forårsager dig betydelig smerte, især dem, der går ud på at kanalisere lyset for at hele dig selv eller andre.\n\nDen eneste udvej af dette problem er--desværre--at gå igennem det. Ligesom enhver anden muskel, der er blevet svækket, må du kæmpe dig igennem smerten og træne kødet, for at det kan vende tilbage til fuld funktion."},
  [91208] = {n="At Finde Sig Til Rette", l="Find den forskrækkede paladin i Dødsklokken.", d="Ikke alle vores medpaladiner, der rejser sig igen, er hurtige til at vænne sig til vores nye virkelighed. Nogle har svært ved at forene sig med, at de nu på en måde er præcis det, de brugte hele deres liv på at bekæmpe.\n\nDisse personer har ofte blot brug for en venlig gestus og et medfølende øre. Desværre er mange andre hurtige til at blive voldelige. Find den forskrækkede paladin, der flygtede op i bakkerne lige vest for dette kapel. Række en hånd i venskab. Før dem tilbage til lyset, hvis du kan."},
  [91209] = {n="Fortsæt Din Træning", l="Følg vejen mod øst ud af Dødsklokken for at finde byen Gryde-by. Meld dig til Shari Stilvæg for at fortsætte din træning.", d="Herrelande er måske ikke, hvad det engang var, men vores hjem har stadig brug for beskyttelse mod alle slags trusler, og nu er det tid for dig at ud og møde verden. Dit næste stop bør være byen Gryde-by i det centrale Tirisfals Lysninger. Gå derhen og mød Shari Stilvæg. Hun kan sørge for din videre træning.\n\nEt sidste råd, før du går--vær ekstra forsigtig som paladin, når du rejser gennem De Forladtes lande. Der er mange i Den Mørke Dames tjeneste, som mistror os og vores nærhed til lyset."},
  [91282] = {n="Et Andet Hjem", l="Find fæstningen Bandarion-borgen og meld dig til Breton Samuelsen der.", d="Det er opmuntrende at se mine nyoprejste brødre og søstre trives, som du har gjort. Det er dog kun gennem fællesskab og delt tro, at vi virkelig kan indfri vores fulde potentiale, og til det formål har vi begyndt at danne en ny paladinorden lige her i Tirisfal.\n\nHvis du ønsker at vide mere, bør du besøge vores kloster i udkanten af Hviskeskoven. Det kaldes Bandarion-borgen. Det ligger på klipperne lige nordvest for Solliden-gården, og det burde være svært at overse."},
  [91285] = {n="Mudderfisk ved Portene", l="Dræb 8 Ondskabsfinne-angribere og 8 Ondskabsfinne-seere, og meld tilbage til Breton Samuelsen, når det er gjort.", d="Normalt ville vi vise vores nykomlinge lidt mere gæstfrihed, men vi har lige nu et lille mudderfisk-problem.\n\nEn stamme af mudderfisk plejede at bruge borgen som yngleplads. De har været et problem, siden vi flyttede ind og smed dem ud, men nu er det ved at komme ud af kontrol. Du ser ud, som om du har set en del kamp. Tror du, du kunne hjælpe os med at drive nogle af disse skadedyr tilbage? Du finder dem skjult i klipperne langs vejen mod øst og i lejrene omkring søen mod vest."},
  [91294] = {n="Rundvisning på Området", l="Tal med indbyggerne i Bandarion-borgen.", d="Nu hvor den umiddelbare trussel fra mudderfisk-angrebene er under kontrol, vil jeg opfordre dig til at se dig omkring i vores højborg. Den er ikke meget endnu, men den er vores hjem.\n\nNår du er færdig med at udforske, så find Danitha Mør, vores leder. Hun kan hjælpe dig med at falde til.\n\nJeg er meget glad for at have mødt dig, <Name>. Må lyset vise dig vejen."},
  [91316] = {n="Reparationer", l="Saml 12 stykker Solidt Tømmer fra Skyggedalen i Tirisfals Lysninger.", d="Så langt fra Undergrunden er logistikken udfordrende, og vi har en alvorlig mangel på byggematerialer, der skal bruges til at genoprette denne fæstning. Jeg vil gerne have din hjælp med det.\n\nDen ødelagte landsby Skyggedalen ligger i Hviskeskoven, lige sydvest for her. En af bygningerne har en gammel rodkælder, der blev brugt til at opbevare alle mulige ting. Der er sandsynligvis brugbare materialer dernede. Saml, hvad du kan, og vend tilbage til os."},
  [91317] = {n="De Plettede", l="Dræb 8 Plettede Trælle, 6 Plettede Fanatikere, og saml hovedet af Kommandør Rudolph Gelhårdt i Tirisfals Lysninger.", d="Ikke alle oprejste paladiner har vænnet sig godt til vores nye eksistens, som du måske allerede har set selv. Nogle har båret deres fordomme fra livet med sig og fortsætter med at hærge deres medforladte.\n\nSom sagen står, er vi mistroet af vores folk, som godt husker den forfølgelse, de levende påførte i lysets navn, og disse angreb hjælper ikke. En række af disse plettede har slået sig ned i Skyggedalen mod sydvest. Gør ende på dem og bring mig deres leders hoved."},
  [91723] = {n="Delikate Instrumenter", l="Dræb 8 Kobold-geomanter i Jaspisåre-minen, og vend derefter tilbage til Hamish Bjergurt i Azoras Tårn.", d="Pokkers også! Hver gang jeg forsøger at kalibrere disse følsomme arkane instrumenter, bliver de forstyrret igen af en energibølge.\r\nBølgerne ser ud til at komme fra nord, hvor de primitive kobolder har øvet deres klodsede magi. Kunne du rydde nogle af dem ud, så jeg kan fortsætte mit arbejde?"},
  [91724] = {n="Delikate Instrumenter", l="Dræb 8 Defias-skurkemagikere ved Stenrøsesøen, og vend derefter tilbage til Hamish Bjergurt i Azoras Tårn.", d="Næsten der, og... Ved Nether! Noget forstyrrer stadig mine instrumenter.\n\nDet er yderst frustrerende, <Name>. Jeg har hørt rygter om, at de lokale banditter har øvet sig i besværgelser nær Stenrøsesøen. Måske hvis du standser dem, så ophører disse forstyrrelser endelig, og jeg kan få lavet noget arbejde?"},
  [91725] = {n="Stjålne Fortryllelsesforsyninger", l="Saml 5 Stjålne Fortryllelsesforsyninger fra hyænemand-lejrene omkring Stenrøsesøen, og vend derefter tilbage til Blixie Fitzvink nær Azoras Tårn.", d="Jeg blev sendt af Mester Teokritos for at hente nogle fortryllelsesforsyninger fra handelsposten, men på vejen tilbage blev jeg overfaldet af en flok hyænemænd!\n\nJeg tabte pakken og slap væk, men hvis jeg vender tilbage uden den, bliver jeg straffet med at rydde op efter forvandlingseksperimenterne i flere uger! Tror du, du kunne finde forsyningerne til mig?"},
  [91732] = {n="Godt Stål", l="Saml 4 Minerværktøj fra Jaspisåre-minen, og vend derefter tilbage til Hagar Lav i Østdal Tømmerlejr.", d="Godt stål er en mangelvare efter krigen, og vores værktøj har lidt under det. Jaspisåre-minearbejderne brugte fint udførte hakker, og jeg forestiller mig, at nogle af dem stadig ligger dernede i minens dybder. Kunne du hente nogle til mig, så ser jeg, om jeg kan genbruge stålet?"},
  [91733] = {n="Nedstrøms", l="Saml den Vandmættede Økse, Vandmættede Sav og Vandmættede Værktøjskasse, der er skyllet nedstrøms fra Østdal Tømmerlejr, og vend derefter tilbage til Ormin Pelfert.", d="Jeg var på vej tilbage med en forsyningssending fra handelsposten, men min vogn væltede, og forsyningerne faldt i floden! Før jeg kunne gribe dem, var de allerede skyllet nedstrøms.\r\nMed mudderfisk og ulve dernede har jeg ingen chance for at hente forsyningerne alene. Du virker som en hårdfør type - tror du, du kunne finde dem til mig?"},
  [91741] = {n="Nagget Bog", l="Returner bogen til Broder Paxton.", d="<En af kobolderne tabte denne bog. Det ser ud, som om kobolden måske har forsøgt at spise den.\n\nBroder Paxton inde i klostret har et lille bibliotek, som han passer. Bogen må være kommet derfra.>"},
  [91743] = {n="Snedige Gnavere", l="Hent 8 stjålne bøger fra kobolder i Nordshire-dalen og bring dem tilbage til Broder Paxton.", d="De forfærdelige kobolder spiser mine bøger! Du må få dem tilbage, før de sluger hele mit bibliotek."},
  [91745] = {n="Minekonsulent", l="Tal med Kelsey Fårgo uden for Ekkoryg-minen i Nordshire-dalen.", d="Gå og tal med den nye minelærling, Kelsey Fårgo. Hun arbejder lige udenfor minen og har sikkert set, hvad kobolderne går og laver. Måske kan hun lære dig et par ting om minedrift, mens du alligevel er i gang."},
  [91751] = {n="Grove Ulvepelse", l="Flå ulve i Elwynnskoven for at samle 7 Grove Ulvepelse, og lever dem derefter til Helene Pelsskinner nær Guldshire.", d="Leder du efter en chance for at øve dig i at flå? Min mand hjælper normalt til med at jage ulve, men han har travlt oppe ved klosteret. Jeg kunne bruge en hånd til at samle flere pelse, så jeg kan blive færdig med de ordrer, jeg arbejder på."},
  [91752] = {n="Det Store Billede", l="Hent en Sæk med \"Billede\"-bøger fra Blankfinder Narv. Bring sækken til Marskal McBride lige inde i Nordshire-klosteret.", d="Nu og da kommer en kobold forbi og råber \"Billede til Narv!\" Jeg ved ikke, hvem Narv er. Måske en af hovedkobolderne bagest i minen? Jeg vedder på, at han har en hel sæk med bøger nu.\n\nGå og hent de bøger og bring dem til vores lokale retshåndhævelse, Marskal McBride. Du bør finde en ven til at hjælpe dig. Kobolderne inde i minen er meget mere hidsige."},
  [91753] = {n="En Fortryllende Lektion", l="Kitta Ildvind i Azoras Tårn vil have dig til at samle 3 Lysende Rest.\n\nLysende Rest kan fås ved at afmontere Grove Voksfigurer, som tabes af Kobold-geomanter.", d="Akademisk stringens er selvfølgelig afgørende for fortryllerens håndværk, men et praktisk fundament kan give udbytte. Tænk for eksempel på den ringe Kobold. Uden formel uddannelse viser de alligevel en slags medfødt begavelse for simple trylleformularer og fortryllelser.\n\nSkaf nogle af deres voksfigurer og afmontér de fortryllelser, der er bundet i dem. Du kan finde det oplysende."},
  [91758] = {n="Følg den Kobold!", l="Tal med Tordrin Stjerneklinge nær stalden bag Nordshire-klosteret.", d="Du er ikke færdig med de kobolder endnu. Kelsey sendte lige bud om, at en kobold har forladt minen med en stor sæk bøger. Jeg har brug for, at du sporer denne kobold, så vi kan få bøgerne tilbage til Broder Paxton.\n\nGå og tal med Tordrin Stjerneklinge. Han er den nye jægertræner, der lige er ankommet fra Jernsmede. Du finder ham bag klosteret, nær stalden. Han kan hjælpe dig med at spore denne kobold-tyv."},
  [91772] = {n="Shh! Vi Jager Kobolder", l="Følg kobold-sporene og rapportér til Marskal Dughan i Guldshire med dine fund og Kobold-sporingssættet.", d="Godt. Tag dette kobold-sporingssæt. Det lader dig' spore den kobold, som Marskal McBride er bekymret for.\n\nFølg sporene og bring det, du finder, til Marskal Dughan i Guldshire.\n\nJeg har en fornemmelse af, at de skadedyr er i gang med noget uden for Nordshire. Så du'll have brug for Dughans hjælp."},
  [91775] = {n="Bogretur", l="Find 6 Tabte Bøger og \"Sjov med Elementarer\" og bring dem tilbage til Marskal Dughan.", d="Mens du undersøger Fjerndyb-minen, så se om du kan finde nogen af Broder Paxtons bøger at returnere. Især er Paxton meget bekymret for en bog med titlen \"Sjov med Elementarer\". Han tror, selv en kobold kunne bruge den til at kalde en elementar-tjener frem. Vær advaret, dybderne i minen er ret farlige. Du bør tage venner med.\n\nTag denne bogtaske med for at beskytte bøgerne, når du finder dem!"},
  [91777] = {n="Sjældne Bøger", l="Find \"Geomanti for Nysgerrige Unge Troldmænd\" og \"Arkan Forklarer: Magisk Tingest i Simple Ord\" og bring dem tilbage til Broder Paxton inde i Nordshire-klosteret.", d="Der er kun to bøger tilbage på Broder Paxtons liste: \"Geomanti for Nysgerrige Unge Troldmænd\" og \"Arkan Forklarer: Magisk Tingest i Simple Ord\".\n\nKobolderne må have taget dem med til Jaspisåre-minen. Spor venligst de to bøger op og bring dem tilbage til Broder Paxton.\n\nMen jeg er bange for, at det bliver ret farligt. Hvis \"lærlingen\"-kobolden kaldte en elementar, ved man ikke, hvad mesteren kan. Jeg ville tage nogle venner med, hvis jeg var dig."},
  [91858] = {n="Diplomatisk Episode", l="Rejs til Gravkammeret i Sølvfyrreskoven og tal med Trevan Rulle om de savnede rejsende fra Jordringen.", d="En meget uheldig vending i Sølvfyrreskoven har givet os en enestående mulighed for at bevise vores værdi i hordens øjne.\n\nTo gesandter fra Jordringen forsvandt i Sølvfyrreskoven på vej til Tarrenmølle. Vi ved ikke meget mere, men rygterne siger, at det er ved at udvikle sig til en ret væsentlig diplomatisk episode. Hvis vi kan finde disse savnede personer, kan det hjælpe os med at vinde den legitimitet, vi så desperat har brug for.\n\nVi har en mand ved Gravkammeret, Trevan Rulle. Rejs derhen og tal med ham."},
  [91861] = {n="Ind i Fenris-fæstningen", l="Undersøg Fenris-fæstningen mod nord og forsøg at finde det savnede medlem af Jordringens gruppe.", d="<Det, at du kun fandt ét lig, er et håbefuldt tegn. Måske er den højelver, som Trevan og Hadrec beskrev, stadig i live et sted dybere inde i den nærliggende fæstning?>"},
  [91899] = {n="En Forseglet Kasse"},
  [91904] = {n="En Forseglet Kasse"},
  [91905] = {n="En Forseglet Kasse"},
  [91920] = {n="Vilde Øjne", l="Saml 3 Mudderfisk-øjne og bring dem til Apoteker Renferrel ved Gravkammeret.", d="Jeg ville ikke vove at sætte spørgsmålstegn ved Apoteker Renferrels formler, men jeg ville lyve, hvis jeg sagde, at eliksiren gjorde nogen synlig forskel.\n\nLangs bredden af Lordamere-søen svømmer en flok mudderfisk, og det er værd at bemærke, at mudderfisk har øjne. Jeg mistænker, at apotekerens villighed til at prøve nye ting er undertrykt af hans nylige besættelse af hjerter. Bring ham nogle få.\n\nHvis mit valg er at dø en anden død, eller at Renferrel dræber mig, fordi jeg stiller spørgsmål ved hans metoder, vælger jeg sidstnævnte."},
  [91921] = {n="Tilbage til Quinn (Igen)", l="Bring Quinns eliksir til Quinn Yorik ved Ivar-agerlodden, nord for Gravkammeret.", d="Her er den nye eliksir til at hjælpe Quinns helbredelse, lavet med kærlighed udvundet fra seks hele hjerter.\n\nUndskyld nu, men din tilstedeværelse nødvendiggør flere papirer."},
  [92110] = {n="Min Første Rigtige Eliksir", l="Saml 3 Mudderfisk-øjne til den unge, ambitiøse alkymist i laden i Månebæk i Vestfald.", d="Wow, min allerførste eliksir! Vidste du, at når man blander de to urter sammen, bliver eliksiren knaldrød, da man først begyndte?\n\nDet var sjovt, men at blande et par blomster ser ikke ud til at være den slags alkymi, far laver. Han bruger også andre ingredienser.\n\nJeg ved ikke, hvad jeg ellers skal bruge, så lad os prøve det første, der falder mig ind! Lad os se... måske mudderfisk-øjne? Det lyder så ækelt, men jeg vedder på, at der sker noget."},
  [92124] = {n="Bogbeholdning", l="Tal med Daniel, Broder Paxtons assistent i biblioteket.", d="Vi må gøre status over, hvor mange bøger der mangler!\n\nGå og tal med min ubrugelige assistent, Daniel. Han kan lave en hurtig opgørelse og fortælle os, hvor alvorligt problemet er.\n\nHan er besat af de forskellige håndværk i Elwynnskoven. Drengen bliver ved med at fokusere på dem i stedet for sit vigtige arbejde med at hjælpe mig.\n\nLad ham ikke pludre om erhvervsfag, og find ud af, hvad der er sket med mine bøger!"},
  [92401] = {n="En Forskrækket Anmodning", l="Undersøg forsvinden af Edward Hjertevæver i Herrelande-ruinerne.", d="Det er min mand Edward...\n\nHan er ikke vendt tilbage fra sin ugentlige tur til kirkegården i Herrelande-ruinerne. Vores søn gik tabt, da Arthæus jævnede byen med jorden, og min kære Edward er stadig fyldt med skyld og sorg over, at vi aldrig fandt hans lig. Jeg har forsøgt at advare ham mod at lede i de overvoksede ruiner, men han nægter at give op. Jeg prøver ikke at bekymre mig, men det er gået flere dage.\n\nDer er ting derude, jeg ikke kan klare, men hvis du vil, må jeg vide, hvad der er sket med min mand."},
  [92415] = {n="Husk at Jeg Elsker Dig", l="Bring det Blodplettede Brev til Børnehjemsmoderen Nattergal i Stormvind By.", d="<Et revet og plettet stykke pergament har knap nok overlevet de udøde-trådte jorder på kirkegården. Det nævner et savnet barn fra Hjertevæver-familien. Måske ved børnehjemsmoderen i Stormvind By mere.>"},
  [92421] = {n="Lysets Retfærdighed", l="Saml 25 Intakte Lemmer i Herrelande-ruinerne til Morbin Lysbane i Undergrunden.", d="Som paladin af De Forladte er det min pligt at udføre Den Mørke Dames vilje, mens jeg tager mig af vores folks behov. Vi er heldige at have en mulighed for at opfylde begge dele.\n\nOver Undergrunden hærger geselen stadig umådeligt. Vores styrker svinder ind, mens de forsøger at generobre vores land, og det rådnende kød kan ikke sammensættes igen. Ikke uden erstatninger.\n\nGid vores strålende kaptajn Garek Bandarion stadig var iblandt os, for jeg ved, hvad han ville ønske. At fuldende det, han begyndte, og hele vores slægtninge. For Herrelande!"},
  [92422] = {n="Rath'maels Vrede", l="Dræb Rath'mael i Herrelande-ruinerne for Dødevagt Kristof i Gryde-by.", d="Der er kommet meldinger fra Lordamere-udsigten dybt inde i Herrelande-ruinerne. En uhellig tåge har overtaget gaderne og kirkegården og giver geselen deroppe en vis grad af snigskytte.\n\nVores spejdere indikerer, at de bliver besværget af en ny magt i deres rækker, en nekromant ved navn Rath'mael. Vi har ikke luksus til at vente dette ud, <Name>.\n\nHvis du har allierede, så kald dem og deres hjælp til De Forladte. Driv dette væsen ud af vores lande."},
  [92432] = {n="En Foruroligende Anmodning", l="Rapportér til Ærkemager Moderas billede nær Dalarn-byen.", d="Jeg bringer dårlige nyheder fra Dalarn. Noget har forstyrret vores leylinjer og fået vores konstruktioner i byen til at opføre sig uregelmæssigt og destruktivt.\n\nVi ved endnu ikke, hvad der forårsager dette kaos. Det høje råd har befalet os at holde sagen hemmelig for ikke at bringe skam over vores orden. Men vi kan ikke holde dette skuespil oppe for evigt. Byen bliver overrendt, mens vi taler!\n\nÆrkemager Modera har sendt mig afsted for at søge hjælp udefra. Find hendes billede nær Dalarn ved siden af Lordamere-søen.", c="Rapportér til Ærkemager Moderas billede nær Dalarn-byen."},
  [92434] = {n="Blod på Gaderne", l="Find en vej ind i Dalarn langs Lordamere-søen.", d="Hvad end der fik Dalarns barriere til at sænke sig, har efterladt byen i uro. Med dig som har klaret deres patruljer, er der ingen bedre tid end nu til at finde vej indenfor og opdage deres hemmeligheder.\n\nTag nøglen, du fandt i interneringslejren, og find deres kloakker langs byens nordlige grænse. Med lidt held havde de magikere ingen grund til at lægge en besværgelse over et så... ubehageligt indgangspunkt."},
  [92456] = {n="En Grøn Prøve", l="Saml en Fel-infunderet Blomst fra Dalarn-byen til Shylamiir i Stormvind By.", d="Hvis du alligevel vil forstyrre mig, kan du i det mindste gøre dig nyttig. Jeg har et ærinde, der skal udføres.\n\nFor en by fuld af magikere har Dalarn en overraskende interesse for botanik. Kirin Tårn holder sig for sig selv, men jeg ville elske en prøve af deres manaindfunderede vegetation.\n\nDu er tydeligvis en, der er tryg ved at være der, hvor folk ikke vil have dig. Måske kan du finde en vej ind i byen. Hvis du gør, så bring mig tilbage det, der vokser i deres centrale have."},
  [92457] = {n="Sultende Arkan", l="Besejr 8 Søgende Rester, 8 Mættede Rester og 8 Manaekkoer inde i Dalarn-byen for Ærkemager Modera uden for Dalarn.", d="Bruddet har påvirket mange af vores tjenere og fortryllelser rundt omkring i byen, herunder mange af dem, der passer på vores forsvar. Denne fragmenterede arkane energi har talt til løsrevne elementarer, som ønsker at mætte sig selv i denne frit flydende magi.\n\nMens vi er travlt optaget af besværgelserne og andre store hændelser, ville det være en tjeneste for Kirin Tårn, hvis du kunne udrydde denne elementar-skare."},
  [92458] = {n="Forstyrrelsens Hjerte", l="Saml Arkan-partiklen til Ærkemager Moderas billede nær Dalarn-byen.", d="Hvad end der forstyrrede leylinjerne, begyndte det øverst i Den Violette Citadel. Et tordnende brag lød fra salonerne deroppe, og nu bliver vi overrendt af vildtvoksende arkan magt. Det kræver alt, vi har, bare for at holde besværgelserne på plads.\n\nVi har ikke råd til at dvæle længere. Vi har brug for hjælp.\n\nKirin Tårn er travlt optaget indenfor, men du skal stadig bruge en mindre offentlig tilgang for at komme ind. Tag denne nøgle og mød mig i citadellet, når du har fundet vej ind i byen. Vi må sætte en stopper for denne forstyrrelse."},
  [92459] = {n="Ven af Kirin Tårn", l="Tal med Ærkemager Kelindra i Dalarns by.", d="Rådet vil ikke være glad for at høre om vores snigen, men de kan ikke benægte resultaterne. Byen falder til ro, og vi er frie til at sænke vores beskyttelsesbesværgelser.\n\nJeg synes, det er rimeligt, at du overbringer det gode budskab. Tag denne partikel til Ærkemager Kelindra inde i Den Violette Citadel."},
  [92460] = {n="Voksenalderens Komme", l="Tal med Rorian Dagsøgeren i Thendal-lunden.", d="Se dig selv, lys i øjnene og klar til eventyr! Vi har brug for al den hjælp, vi kan få her i Thendal-landsbyen, og din ankomst er meget velkommen. Jeg forestiller mig, at du er fuld af nervøsitet over det, der venter. Man bliver jo kun voksen én gang i livet.\n\nGå og find vores landsbyleder Rorian Dagsøgeren ved indgangen til storfaderstræet lige vest herfra. Han vil få dig i gang med din rejse."},
  [92461] = {n="Harmoni i Balance", l="Dræb 8 Vuldren-unger i Thendal-lunden.", d="Vi lever i tider med stor usikkerhed for vores folk. Vi står over for enestående udfordringer, der kan kræve dristige løsninger, men vi må også tage os af det almindelige og jordnære her i Thendal-lunden. Tag for eksempel den for nylig uholdbare vækst i vuldrenbestanden.\n\nVuldrenerne er en vigtig del af vores økosystem. Men ubalancer må rettes op for at bevare den skrøbelige harmoni, alle væsner i Thendal-lunden deler.\n\nTag østpå og tyn ud i vuldrenerne dernede."},
  [92462] = {n="Angrebsefterforskning", l="Dræb 8 Irriterende Cirrusfluer i Thendal-lunden.", d="En af vores spejdere har for nylig meldt om et angreb af cirrusfluer her i Thendal-lunden.\n\nCirrusfluer kan være farlige, hvis sværmen får lov at vokse for stor, så tag venligst til lundens østlige ende og udryd så mange, du kan."},
  [92463] = {n="Cirrusflue-dronningen", l="Ødelæg Cirrusflue-dronningen i Thendal-lunden.", d="Hvis skoven er lige så tæt med disse insekter, som det lyder til, så er det ikke nok blot at dræbe arbejderne.\n\nGå dybere ind i skoven og find dronningen. Hun vil være tæt på stokken og omgivet af større og mere aggressive soldater, så vær forsigtig.\n\nFæld hende og vend tilbage hertil, når det er gjort. Så er der ét problem mindre at tænke på her omkring."},
  [92464] = {n="Elementar Uro", l="Tal med Yala Vindvogter i Thendal-lunden.", d="Lige siden vores elementare velgørere forlod os, ser det ud til, at vi blot bevæger os fra én uro til en anden. Problemet, vi står over for nu, er, at manifestationerne af vinden ved de stående sten mod nordøst er oprørte.\n\nIkke egentlig selvbevidste som de følende vindånder, der engang boede her, reagerer disse simple sprites på de kræfter, følelser og hensigter, som væsnerne omkring dem har.\n\nMin lærling Yala Vindvogter gik for at observere dem. Find hende og hør, hvad hun har lært."},
  [92465] = {n="Oprørerne", l="Dræb 6 Bølgende Vinde og 7 Al'Aketh-konvertitter i Thendal-lunden.", d="Al'Aketh-kulten er en pest på denne ø. Disse kultister er helt sikkert de skyldige i, at de simple vindsprites, der bor her, bliver ophidsede og voldelige.\n\nDesværre må vi sprede disse bølgende vinde, før de skader nogen. Vi må også sende kulten en klar besked om, at de ikke er velkomne i lunden.\n\nVil du hjælpe mig, <Class>?"},
  [92466] = {n="Jordens Kald", l="Bring et Akirs Signet til Vindformer Boro.", d="Selvom vi skylder meget af vores velstand vindens elementer, kræver vejen, vi går, at vi adlyder kaldet fra alle fire primære elementer og gennemgår en prøvelse for hvert. Før du begynder din første prøvelse for alvor, må du dog bevise styrken af din vilje.\n\nRejs til de stående sten mod øst. En styrke af Al'Aketh-konvertitter er set ddér, og de må drives væk. Konfronter kultisterne dér og bring mig et af deres signeter som bevis på dine gerninger."},
  [92467] = {n="Jordens Kald", l="Find Åndernes Rejsning og drik Jordsapta.", d="En sapta er en drik, der er skabt til at binde vores ånder til elementerne. Smeltet sammen med magi giver drikken de stærkviljede mulighed for at se elementerne, som ingen anden kan. Din ånd vil blive forbundet med det element, saptaen blev skabt for, og kun en lille håndfuld shamaner kender opskriften.\n\nSaptaen drikkes altid på et hellig sted og aldrig andre steder--husk det.\n\nSøg Åndernes Rejsning op ad passet mod nordøst herfra. Drik din sapta dér, og... ja, du vil se, hvad du behøver at se."},
  [92468] = {n="Jordens Kald", l="Bring den Grove Kvarts til Vindformer Boro i Thendal-lunden.", d="Tag denne Grove Kvarts fra mig og bring den til ham, du kalder Vindformer Boro, som bevis på vores møde. Han vil forme en totem til dig, og denne skærv vil være dens hjerte. Så lille den end kan virke, vil du opdage, at størrelse ikke betyder noget, og at selv de mindste ting kan overleve mange andre.\n\nVær tålmodig, <Name>. Forbliv stærk. Og søg visdom. Det er, hvad elementerne kræver af dig. Til sidst skal du blive ét med jorden--respektér den, så den vil respektere dig."},
  [92469] = {n="Tilbage til Rorian", l="Bring nyt om Al'Aketh til Rorian Dagsøgeren i Thendal-lunden.", d="Du har gjort nok her, <Class>. Jeg bliver og rydder op i de efterladte dernede.\n\nVend tilbage til landsbyen og fortæl Rorian om kultens tilstedeværelse. Han vil ikke være glad."},
  [92470] = {n="Den Modbydelige Matriark", l="Dræb 8 Bjørnsera-ådselædere og saml hovedet af hulemoderen, Bjørn'anah i Thendal-lunden.", d="Rorian har fortalt dig, at jeg har holdt øje med dig. Jeg tilbyder dig nu en prøve af viljestyrke. Vær dog advaret--den vil sende dig i stor fare.\n\nGå til hulerne mod vest. Tynd bjørnseraernes antal dér ud, og find deres matriark, en som rangerne kalder \"Bjørn'anah\". Fæld hende og bring mig bevis for hendes død. Når du har gjort det, har du taget et vigtigt skridt på din vej."},
  [92471] = {n="Aetheen fra Stormene", l="Tal med Aetheen fra Stormene i Thendal-lunden.", d="Du er måske ikke klar over det, men alt, du har gjort, har været en slags prøvelse. En test af, hvad der venter dig. Der er en stor ø derude, og Vindras har brug for ivrige unge eventyrere som dig, hvis vi skal overleve de prøvelser, vores folk står over for.\n\nDen, der kaldes Aetheen fra Stormene, er en af lederne af vores folk her på Vindras-øen, og hun har holdt øje med dig. Hun har en opgave, du skal løse. Tal med hende for at lære mere."},
  [92472] = {n="Det Næste Skridt", l="Meld dig til konstabel Aonda i Shen'dar-landsbyen.", d="En af de mest udbredte trusler på Vindras-øen er Al'Aketh-kulten. De er religiøse fanatikere, hengivne til tilbedelsen af den påståede elementare hersker over Himmelmuren, Al'Akir Vindherren. De er brutale, énsporede, og deres magt og ambitioner bliver dødbringende for hver dag.\n\nDin vej vil snart føre dig til Shen'dar-landsbyen mod syd. Mød op hos konstabel Aonda, når du ankommer. Kulten truer Shen'dar, og de har brug for hjælp. Fortæl Aonda, at jeg sendte dig."},
  [92473] = {n="Aggressivt Indgreb", l="Saml 6 Magre Bjørnsera-kløer fra magre Bjørnseraer i Thendal-lunden.", d="Bjørnsera-hulen mod sydvest er hurtigt ved at blive et problem. Forleden måtte rangerne dræbe en ung bjørnsera, der vandrede for tæt på landsbyen og forsøgte at angribe en dreng, der legede nær foden af ældretræet i landsbyens centrum.\n\nVi var heldige, at drengen slap med livet i behold. Sult og desperation gør disse udyr for farlige til at lade dem være uden kontrol. Gå sydpå og fæld de magreste blandt bjørnseraerne. Bring mig deres kløer som bevis, når det er gjort."},
  [92474] = {n="Faldende med Stil", l="Hop fra toppen af vagttårnet i Thendal-lunden og brug din evne Gå på Luft for at bremse dit fald.", d="Hej dér, <Name>! Vil du lege?\n\nDet eneste, du skal gøre, er at træde op på den syld dér... og så hop! Brug din medfødte evne til at gå på luften for at bremse dit fald og se, hvor langt frem du kan flyde.\n\nReglerne er opdigtede, og pointene betyder ikke noget, men du får bonuspoint, hvis du kan lande lige foran Rorian Dagsøgeren og give ham et chok! Han bryder sig ikke om det, men jeg vil sandelig få et godt grin, hvis du kan få ham helt op i det! Hah!"},
  [92481] = {n="En Arkan Elev", l="Undersøg den Glødende Tilbagekaldskrystal og tal derefter med Dorii Lysviske i Thendal-lunden.", d="Mens du var væk og tog dig af vores vuldrenproblem, efterlod vores faste magilærer--Dorii Lysviske--denne tilbagekaldskrystal til dig. Den indeholder en slags besked til dig, så kig på den. Bagefter kan du finde Dorii i bygningen lige bag mig."},
  [92482] = {n="Jægerens Vej", l="Læs den Kradsede Seddel og tal derefter med Tai'ree Langsyn i Thendal-lunden.", d="Mens du var væk og tog dig af vores vuldrenproblem, efterlod vores faste jægerlærer--Tai'ree Langsyn--denne seddel til dig. Du kan finde hende lige derovre nær landsbyens centrum. Læs seddelen og søg hende derefter op."},
  [92483] = {n="Hjemme i Skyggerne", l="Læs den Simple Seddel og tal derefter med Akeri Skumringsklinge inde i vagttårnet i Thendal-lunden.", d="Mens du var væk og tog dig af vores vuldrenproblem, har vores faste snigerlærer--Akeri Skumringsklinge--bedt om at tale med dig. Han efterlod en seddel, så læs den først, og søg ham derefter op inde i vagttårnet, her i landsbyen.\n\nHan er en skummel fyr, men så er du jo også. Jeg tror, I kommer godt ud af det med hinanden."},
  [92484] = {n="Omfavnelse af Elementerne", l="Undersøg den Summende Tilbagekaldskrystal og tal derefter med Vindformer Boro i Thendal-lunden.", d="Mens du var væk og tog dig af vores vuldrenproblem, efterlod vores faste shamanlærer--Vindformer Boro--denne tilbagekaldskrystal til dig. Undersøg den venligst, og tal derefter med Boro lige derovre nær landsbyens centrum."},
  [92485] = {n="En Naturens Elev", l="Læs det Foldede Pergament og tal derefter med Xyton Sølvvind i Thendal-lunden.", d="Mens du var væk og tog dig af vores vuldrenproblem, efterlod vores faste druidlærer--Xyton Sølvvind--denne seddel til dig. Læs den så hurtigt du kan, og søg derefter Sølvvind op på stueetagen i dette store træ lige bag mig.\n\nLyt til hans ord og hans råd, han kan lære dig meget."},
  [92489] = {n="Kraftovervældelse", l="Dræb Manaelementaren i Dalarns by for Højtryllekunstner Andromath i Stormvind.", d="Kirin Tårn har længe været allieret med Alliancen. Efter deres by blev ødelagt af ærkedæmonen Archimonde, er den engang stolte magikerby blevet tilbagetrukket og mistroisk over for udefrakommende.\n\nI de senere år har de påbegyndt genopbygningsarbejder for at bringe Dalarn tilbage til sin fordums herlighed. Rapporter viser dog, at de kæmper for at holde et udbrud af afvigende arkane energier i tømme.\n\nVi må hjælpe dem med at sprede disse angreb, for ellers mister vi en af vores mest magtfulde allierede."},
  [92514] = {n="Velkommen til Shen'dar-landsbyen", l="Tal med Illaya Rafvind og Coriella Stilvind i Shen'dar-landsbyen.", d="Du har den der \"Vindformer\"-luft over dig. Noget ved, at jeg kan mærke lidt statisk elektricitet på min hud, når jeg er i nærheden af en åndsberørt person, der afslører det. Før jeg ordentligt sætter dig i arbejde her omkring, bør du tjekke ind hos vores faste vindformer-ældste, Illaya Rafvind. Hun står lige udenfor, nær byens centrum.\n\nÅh, og tjek også ind hos Coriella Stilvind, hun driver det lokale kro og kan skaffe logi og forsyninger, hvis du får brug for dem."},
  [92515] = {n="Problemet med Stolkløerne", l="Saml 10 Stolkløe-pelse fra Stolkløerne i Shen'dar-højlandet.", d="Som om bandit og gale kultister ikke var nok, er bakkerne også tykt besat af stolkløer lige nu. De begynder at trænge ind på landsbyens grænser og bliver dristigere for hver dag. Det er kun et spørgsmål om tid, før nogens kæledyr eller barn bliver taget. Det ville være en nåde for os at udtynde deres antal nu, i stedet for efter en eller anden tragedie er sket.\n\nBring mig et dusin af deres pelse. Jeg kan lave alle slags varer af dem, der vil hjælpe landsbyen."},
  [92516] = {n="Hippogryf-chikane", l="Dræb 8 Hippogryf-unger, 6 Hippogryf-beskyttere og et Hippogryf-matriark i Shen'dar-højlandet.", d="En flok hippogryfer har for nylig etableret redeområder sydøst for Shen'dar-landsbyen, og de har skabt kaos for rejsende på vejen. Jeg har brug for, at nogen tager derned og tynder dem ud for os."},
  [92517] = {n="Det Kriminelle Element", l="Dræb 10 Højlands-banditter og deres leder, \"Dårligvind\" Bennic i Shen'dar-højlandet.", d="Der er en hule ikke langt mod nord, skjult bag et vandfald. Det er mig velbekendt, at en flok banditter opererer fra den hule. De var et problem for os, før kulten ankom, men nu er de en ren rædsel. Jeg kan desværre ikke undvære folk til at gå derud og rydde dem ud.\n\nJeg har brug for, at du tager derud og tager dig af dem for mig. Dræb så mange, du kan, og hvis det er muligt, så fjern deres leder, ham de kalder \"Dårligvind\" Bennic. Hulen er farlig, så pas på dig."},
  [92528] = {n="Blandt de Troende", l="Kig rundt i Falaath-landsbyen for at lære om kultens hensigter i Shen'dar-højlandet.", d="De troende til Al'Akir bliver stadig stærkere med hver ivrig ny rekrut som dig selv. Som du kan se, giver vores styrke selve stormen form!\n\nNormalt ville jeg sende dig direkte til Skypræst Aanders til vurdering, men han er i øjeblikket optaget af at tage imod en gæst på kroen i den nordlige ende af byen. Hold dig venligst væk fra det sted for nu. En ubarberet rekrut som dig i nærværelse af sådan en gæst ville være upassende.\n\nVær bare ikke i vejen for nogen indtil videre."},
  [92529] = {n="Falaath-landsbyen", l="Meld dig til missionær Jasaan nær indgangen til Falaath-landsbyen.\n\nHvis du mister dit Akir-mærke, så tal med Sania Sølvstrøm i Shen'dar-landsbyen for at få effekten tilbage.", d="Det glæder mit hjerte, at du ønsker at tjene Al'Akir. Vores nuværende prøvelser som folk stammer fra vores egen selvtilfredshed. Vi blev stolte og tog vindens gavmildhed for givet. Stagnationen, der fulgte, er grunden til, at vindens ånder forlod os.\n\nKun gennem angrende handlinger kan vi igen mærke vindens kærtegn. Hvis du søger fællesskab med ligesindede shen'dorei, så gå til Falaath-landsbyen og find missionær Jasaan der. Jeg vil markere dig, så de troende kan kende dig som rekrut."},
  [92532] = {n="Krigerens Vej", l="Læs den krøllede seddel, du har fået, og søg derefter Klingemester Ren inde i vagttårnet i Thendal-landsbyen.", d="Mens du var væk, bad vores krigertræner--Klingemester Ren--om, at vi sendte dig hen til dem, når du vendte tilbage. Hun afleverede også denne seddel til dig.\n\nLæs den, og find så Klingemester Ren inde i landsbyens vagttårn."},
  [92544] = {n="Al'Aketh-ruffianerne", l="Nedlæg 6 Al'Aketh-brutaler, 4 Al'Aketh-neofytter og Malduko Skysmadder i Thendal-lunden.", d="En flok ruffianer fra Al'Aketh-kulten har slået sig ned nær tempelruinerne lige sydvest for her, ledet af et rigtigt monster ved navn Malduko Skysmadder. Den pøbel er uden tvivl blevet sendt hertil af Højpræstinde Lorthuna ved Akirs Helligdom for at overfalde rejsende og tvinge vores folk til at slutte sig til kulten.\n\nJeg må blive ved min post for at advare de rejsende, der forlader lunden, om faren, men jeg ville sætte pris på, hvis du kunne gøre noget ved de kultister og deres leder for mig."},
  [92550] = {n="Kaos i Højlandet", l="Rejs til ruinerne af Falaath-landsbyen og dræb 6 Al'Aketh-stormkaldere, 4 Levende Lyn og tag hovedet af Kommandør Cyclas.", d="Vores bedste forsvar her kunne lige så godt være et stærkt angreb. Fordelen, vi nu har, er, at vi venter, at et angreb er på vej. Det, de ikke venter, er, at vi slår først.\n\nJeg har allerede bedt dig om meget, men vær venlig at tage tilbage til Falaath-landsbyen. Dræb så mange kultister, du kan, og hvis du kan komme tæt nok på, så dræb kommandøren og bring mig hans hoved. Jeg bliver her og organiserer borgerne og vores få fredsbevarere, så vi kan forberede et forsvar... bare for en sikkerheds skyld, hvis du ikke vender tilbage."},
  [92551] = {n="Stjålne Forsyninger", l="Saml 10 pakker med stjålne Shen'dar-forsyninger fra Falaath-landsbyen i Shen'dar-højlandet.", d="Jeg hørte, at du måske skal til Falaath-landsbyen? Mens du er der, så hold øje med vores stjålne forsyningsdepoter.\n\nAl'Aketh har i månedsvis plyndret vores forsyningskaravaner, der bærer alt muligt såsom mad og vindsten til og fra lavlandet. De har selvfølgelig givet banditterne skylden, men vi ved alle sammen, at det hele ender det samme sted. Hvis der er noget af det tilbage i Falaath, ville det være en stor hjælp, hvis du kunne hente det tilbage."},
  [92553] = {n="Genopfyldning af Spisekamrene", l="Saml 3 Små Æg og 8 Vandrerkød fra væsner, der findes i hele Shen'dar-højlandet.", d="Har du lyst til lidt arbejde? Jeg kunne bruge lidt muskelkraft fra en stærk eventyrertype som dig. Med hvor farlige tingene bliver herude, har ingen haft meget tid til at jage eller samle foder på det seneste, og jeg har brug for, at nogen tager ud og skaffer mig friske æg og vandrerkød, så landsbyen kan holdes mæt.\n\nJeg ville med glæde lære dig en af mine berømte opskrifter, hvis du kan bringe mig det, jeg har brug for. Hvad siger du?"},
  [92579] = {n="Til Valanaar", l="Lever Aondas Skrevne Rapport til Valennia Stormnæve i Valanaar.", d="Indtil videre ser det ud til, at pylonen og landsbyen er i sikkerhed, så jeg vil gerne have, at du leverer denne rapport til Valennia Stormnæve i Valanaar, i øens sydøstlige kant. Valennia er leder af fredsbevarerne på øen, og hun skal vide, hvad der er sket her.\n\nKulten breder sig hurtigt, og fredsbevarerne har undgået direkte konflikt indtil nu, men de dage er forbi. Valanaar må gøre sig klar til en kamp.\n\nUnder alle omstændigheder, tak. Du vil altid have venner i Shen'dar, <Name>."},
  [92595] = {n="Vindformerne", l="Lyt til hvad Illaya Rafvind har at sige.", d="<Illaya smiler varmt til dig.>\n\nJeg er glad for, at du vendte tilbage for at tale med mig, vindens barn. Jeg vidste det det første øjeblik, du trådte ind i min nærhed, at du var stærk i himmelsynet. Undrer det dig? Selv dem, der ikke har trænet som shaman, kan besidde gaven.\n\nKom, lad os tale om Vindformernes mandat, arten af vores kampe på Vindras og vores folks nød."},
  [92596] = {n="Den Høje Orden", l="Tag plads og tal med Rathiril Solsvinge.", d="Den arkane energi, der omgiver dig, er stærk, selvom du ikke er indviet som magiker. Jeg er ganske sikker på, at du bliver en dygtig eventyrer, og din forbindelse til vores gamle magi vil kun nogensinde være en gave for dig, selv hvis du aldrig udtaler et eneste kraftord i en besværgelse.\n\nKom, lad os sætte os og tale lidt om min orden, den arkane kraft her på Vindras og vores folks nød."},
  [92597] = {n="Læsning af Ley-linjerne", l="Brug din racerevne Læs Ley-linje ved ley-linjen i Thendal-lunden.", d="Her i det elementære plan udleder vi meget af vores arkane styrke fra ley-linjer, der stadig løber gennem jorden under vores fødder. For nylig er disse linjer begyndt at bryde overfladen og give os mere direkte og kraftfuld adgang til disse skjulte arkane energier.\n\nGå til stenringene mod nordøst. Der er en ley-linje. Tap ind i din fødselsret og træk dens energi ind."},
  [92598] = {n="Himmelsynets Gave", l="Brug din racerevne Himmelsyn ved det elementære konvergenspunkt i Thendal-lunden.", d="Som Vindformer har du evnen til at bruge det hellige himmelsyn, som de elementære ånder har skænket os. Rejs til stenringene mod nordøst for landsbyen. Find det elementære konvergenspunkt der og brug din gave.\n\nDu vil opdage, at du kan trække på himmelsynet hvor som helst, men dets gunst er meget stærkere, hvis du gør det i nærværelse af et elementært konvergenspunkt. Du kan til tider også modtage andre stykker visdom fra ånderne, der tiltrækkes af sådanne magtsteder."},
  [92640] = {n="Desperate tider", l="Tal med Valennia Stormnæve i Valanaar og følg hendes instrukser.", d="Da det ikke er muligt at angribe kulten i det åbne, er vores bedste chance at udnytte denne mulighed til at angribe selve helligdommen. Vi kan tage Lorthuna selv af brættet, før hun kan fuldende sin del af denne plan.\n\nDet sker, at Valennia har forberedt en strategi for et muligt angreb på helligdommen i noget tid nu. Det eneste problem er, at vi får brug for hjælp.\n\nTal med Valennia for detaljerne."},
  [92642] = {n="Forstyrrelse af Logistikken", l="Dræb 4 Al'Aketh-healere og 8 Al'Aketh-slagsbrødre i Gustbær-lavlandet.", d="Valennia sendte kun én person for at hjælpe med at afvise et angreb i fuld skala... af vinden.\n\nDu ser ikke ud af meget, men jeg tager, hvad jeg kan få. Vi må påføre så stor skade som muligt for at stoppe dette snart. Mit folk kan ikke holde ud meget længere.\n\nGå ned ad bakken og forstyr deres logistik. Deres healere holder angriberne i gang, og hvis vi tager dem ud, kan vi måske samle os og skubbe dem tilbage. Alle andre kultister, du dræber, mens du er derude, er også til hjælp."},
  [92643] = {n="Overløberen", l="Find kultoverløberen i huset lige inde i højlandet nordvest for Valanaar.", d="Der er en overløber blandt Al'Aketh. De påstår at kende kultens sande hensigter for øen og vil komme ind, men vil kun gøre det med forsikringer om beskyttelse.\n\nDenne overløber gemmer sig i en afsides bolig lige nordvest for Valanaar inde i højlandet. Jeg har brug for en, der diskret kan tage derhen, finde forræderen og eskortere ham tilbage til os. Det kan være en fælde, men hvis oplysningen er så vigtig, som denne forræder hævder, er den en risiko værd."},
  [92644] = {n="Uheldige Nyheder", l="Lever den lysende krystal til Talanaanis Skyggesang i Valanaar.", d="<Du rækker ned under den stadig varme krop af overløberkultisten og finder en lille, lysende blå krystal. Den ser beskadiget ud, men den kan stadig være vigtig. Højældste Skyggesang kan være interesseret i denne.>"},
  [92645] = {n="At Bryde Brekeren", l="Dræb Kommandør Belguilos i Gustbær-lavlandet.", d="Dette angreb bliver svært at afvise, medmindre vi kan tage kultkommandøren ud. Belguilos \"Brekeren\" kalder de hende, og hun er en ægte rædsel. Hun plejede at være fredsbevarer, før kulten kom ud af kontrol, og selv dengang var hun... skæv. Som kultist kan jeg kun forestille mig, hvor meget værre hun kan være nu.\n\nJeg sender måske dig direkte i døden, men nogen må tage Belguilos ud, hvis vi skal overleve her. Du finder hende i villaen ved bakkens fod. Held og lykke, <Class>."},
  [92646] = {n="Konfrontation med Lorthuna", l="Tag portalen til Rohashi-tårnene oven over og slut dig til Elaadrin Aftenvind og Ayessa Morgensang i deres konfrontation med Højpræstinde Lorthuna.", d="Lorthuna flygtede op til tårnene ovenover ved hjælp af en slags portal. Ayessa og Elaadrin gik efter hende. Det var for få øjeblikke siden.\n\nJeg er bange for, at jeg tog et hit for mange, og her bliver jeg. Gå gennem portalen, find Ayessa og hjælp dem med at stoppe Lorthuna.\n\nMedmindre den hjælp, som Elaadrin og Ayessa sagde, de havde sendt efter, ankommer snart, er du på egen hånd herfra. Held og lykke, <Class>."},
  [92679] = {n="Blodtiende", l="Lyt til hvad Alvarion Vindmark har at sige, og find Aamelia Vindmark i Vindmark-frugthaven.", d="H--Hej, fremmede. Du har udseendet af en dygtig eventyrer over dig. Jeg...\n\n<Den himmelfødte mand krymper sig, tydeligt plaget af frygtelig smerte>\n\n...jeg undrede mig over, om du søgte arbejde? Jeg kom hertil til Valanaar for at rekruttere kæmpere til at redde min gård. Hvis du er interesseret, så gå og find min kone Aamelia Vindmark i vores frugthave vest for Valanaar, i lavlandet."},
  [92682] = {n="Gør Dig Nyttig", l="Saml 10 Modne Stormæbler og dræb 5 Sultne Banditter i Vindmark-frugthaven.", d="Åh, så du har mere mod end fornuft, altså? Fint, jeg vil ikke diskutere.\n\nFerauu og hans håndlangere skal ikke hente deres andel af høsten endnu, så jeg vil sætte dig i arbejde for dine måltider, indtil de ankommer.\n\nGå udenfor og saml dagens parti stormæbler til mig. Å, og banditterne, der lurer rundt om stormæbletræerne... De tror, de er snedige. Det er de ikke. Dræb dem for mig.\n\nLad os se, hvad du kan i en kamp."},
  [92683] = {n="Flagrefly-støv", l="Saml 5 Flagrefly-støv fra flagreflyene i Gustbær-lavlandet.", d="Jeg er sikker på, at du har bemærket de gigantiske flagreflyer ude på de yderste marker nær frugthaven? De er behagelige at se på, men de har også andre fordele, nemlig deres vingestøv. Det kan give et rod, men hvis du kan samle det op i store mængder, har det nyttige husholdningsanvendelser.\n\nTag denne Flagrefly-smækker og giv de store bæster et godt smæk for mig. De bliver som regel bare bange og flygter, men nogle gange tager de anstød. Uanset hvad, så vil de ryste deres bagdele og smide en bunke støv."},
  [92684] = {n="Gnavne Gnavne Stormvandrere", l="Saml 7 Lavlands-stormvandrer-mørbrad fra de gnavne stormvandrere, der findes i hele Gustbær-lavlandet.", d="Som om høsten ikke allerede er mager nok i år, har stormvandrerne i området taget til at trænge ind i frugthaven og stjæle mine stormæbler. Tror du, du kan tage ud på markerne og nedlægge dem for mig?\n\nVær dog forsigtig, fremmede. Disse lavlands-stormvandrere er større og vredere end højlands-udgaven. Pas på dig selv. Et velplaceret spark er alt, der skal til for at lægge dig ned for altid, hvis du ikke er opmærksom.\n\nBring mig noget af deres kød, så kan jeg lave et varmt måltid af det også."},
  [92685] = {n="Bakkerne Har Øjne", l="Plyndr 7 Blodplettede Banditmasker fra landevejs-banditter i Gustbær-lavlandet.", d="Banditterne har lejre overalt, og der er en lille én i bakkerne lige nord for her. Tag derop og begynd at knække kranier. Hvis vi kan overraske dem og tage dem ud, før de kommer efter os, kan vi måske udjævne oddsene nok til at have en chance.\n\nBring mig deres masker. Jo blodigere, jo bedre."},
  [92693] = {n="Holder Stand", l="Tal med Aamelia Vindmark, når du er klar til at konfrontere banditlederen.", d="Du har gjort meget for at give os en kampchance. Selvom vi dør i dag, ved vi i det mindste, at vi gav det vores bedste forsøg.\n\nDette er din sidste chance, fremmede. Hvis du vil vende tilbage til Valanaar og leve en dag mere, ville jeg ikke bebrejde dig.\n\nPå den anden side, hvis du virkelig har en forkærlighed for tabte sager, så lad mig vide, når du er klar til at gå. Vi går derud med hovedet højt, og uanset hvad der sker, så sker det."},
  [92698] = {n="Hvad Er Mit Formål?", l="Tal med Aamelia Vindmark om den defekte Cyklon-konstruktion.", d="<Du lener dig tæt ind for at prøve at høre ordene, der kommer fra under konstruktionens panser.>\n\n...Funktionsfejl...\n\n...Spørgsmål...\n\n...Hvad er....\n\n...Funktion...\n\n<Disse brudstykker af ord og sætninger ser bare ud til at gentage sig. Måske ved nogen i nærheden mere om denne konstruktion?>"},
  [92699] = {n="Den Højeste Magister", l="Find Elaadrin Aftenvind i Valanår.", d="Nu hvor du er ankommet til Valanår, vil du sikkert gerne hilse på de andre medlemmer af Den Høje Orden her. Den nuværende Højeste Magister, Elaadrin Aftenvind, og hans folk holder til i logen helt ude i det sydøstlige hjørne af Valanår.\n\nPas også på. Den Høje Orden og Vindformerne kommer ikke særlig godt ud af det her. Vær forsigtig, og hold god, bred afstand til Vindformerne. Vi har nok at bekymre os om med kulten, og jeg tolererer ikke fraktionsvold på Valanårs gader."},
  [92700] = {n="Den Store Himmelspåer", l="Find Ayessa Morgensang i Valanår.", d="Nu hvor du er ankommet til Valanår, vil du sikkert gerne hilse på de andre medlemmer af Vindformerne her. Den nuværende Store Himmelspåer og hendes folk holder til i logen tæt på midten af Valanår.\n\nVær også opmærksom på, at Vindformerne og Den Høje Orden ikke kommer særlig godt ud af det i disse egne. Vær forsigtig, og hold god, bred afstand til Den Høje Orden. Vi har nok at bekymre os om med kulten, og jeg tolererer ikke fraktionsvold på Valanårs gader."},
  [92701] = {n="Til Valanår", l="Lever Aondas Skrevne Rapport til Valennia Stormnæve i Valanår.", d="Lige nu ser det ud til, at pylonen og landsbyen er i sikkerhed, så jeg vil gerne have, at du leverer denne rapport til Valennia Stormnæve i Valanår, helt ude i den sydøstlige udkant af øen. Valennia er leder af fredsbevarerne på øen, og hun skal vide, hvad der er sket her.\n\nKulten breder sig hurtigt, og fredsbevarerne har undgået direkte konflikt indtil nu, men de dage er forbi. Valanår må gøre sig klar til kamp.\n\nUnder alle omstændigheder: tak. Du vil altid have venner i Shen'dar, <Name>."},
  [92703] = {n="Lever Nyheden", l="Tal med Alvarion Vindmark i Valanår.", d="Det føles vist ikke helt rigtigt at kalde dig fremmed efter alt det her, så... tak, <Name>.\n\nHvis du ikke har noget imod det og er på vej tilbage den vej, så lad venligst Alvarion vide, hvad der er sket her. Og fortæl ham også, at når han er på benene igen, skal han hente en vindformer tilbage hertil for at se på det konstrukt for os, så vi kan være sikre på, at det er trygt at have rundt om vores... vores familie.\n\n<Aamelia rører blidt ved sin mave.>\n\nHan ved ikke noget om den del. Lad os holde det mellem os to for nu."},
  [92706] = {n="EFTERLYST: Brus", l="Bring Brus' Rygfinne til Gazlowe i Skralleby.", d="Alle fiskere, hør efter!\n\nEn kæmpe haj har kredset rundt i vandet ved fragtkajen og angrebet søfolk og små både. Havnearbejderne har givet den kaldenavnet \"Brus\". En hæftig belønning gives til den, der bringer mig dens finne!\n\n-- Gazlowe"},
  [92708] = {n="Et Stort Eventyr", l="Hør efter, hvad Ayessa Morgensang har at sige.", d="Vindformerne har arbejdet hårdt på at håndtere den nuværende krise på Vindras-øen. Vi har gjort flere overraskende opdagelser i vores søgen efter de savnede vindånder, og vi er ved at udvikle en handlingsplan, der kan give os midlerne til at redde øen.\n\nVi får dog brug for stærke unge eventyrere som dig, for at det kan lykkes. Vær venlig, hvis du har et øjeblik, så lad os tale mere om det."},
  [92709] = {n="Et Stort Eventyr", l="Hør efter, hvad Elaadrin Aftenvind i Valanår har at sige.", d="Din højfødte afstamning skinner lige så klart i dine øjne som himlen over os. Du er en af os, og det er unge som dig, der skal hjælpe os med at redde vores hjem. Men først lad mig fortælle dig mere om vores mission og planer her på Vindras... og videre."},
  [92727] = {n="Den Savnede Lærde", l="Find ud af, hvad der er blevet af Fillion Flammebrise.", d="At søge efter viden er Den Høje Ordens vigtigste opgave, men dette arbejde har aldrig været farligere, end det er nu på Vindras.\n\nEn af vores lærde—Fillion Flammebrise—var på vej til Shen'dar-højlandet for at indsamle data om den vindbårne magi, der samler sig visse steder dér. Desværre er han ikke vendt tilbage, og vi frygter, at der er sket noget med ham på vejen.\n\nHvis du kan, så find ham for os. Han blev sidst set på vejen mod vest fra Valanår mod Shen'dar-højlandet."},
  [92741] = {n="Uvelkomne Gæster", l="Rejs til Skyggestormsskoven og saml 8 Skrigelingeklør for Iaadaria Bitvind i Valanår.", d="Skyggestormsskoven er yderst farlig og er normalt forbudt område for almindelige eventyrere. I de seneste måneder er skrigelingebestanden eksploderet, og de er begyndt at udvide deres område uden for skoven, hvilket er et potentielt problem. Jeg har en interesse i de alkymistiske egenskaber ved skrigelingeklør, så en stærkt tiltrængt udtynding byder også på en chance for lærd gevinst.\n\nRejs til Skyggestormsskoven og jag bestierne. Bring mig så mange af deres klør, som du kan."},
  [92742] = {n="Afprøvning af Brøndene", l="Brug Brøndvandsprøve-sættet til at indsamle prøver fra brøndene på Jansens Gård og Molsens Gård.", d="Vi må finde ud af, hvor giften, der korrumperer dette land, stammer fra, og hvad den består af. Lad os begynde med grundvandet under gårdene i området.\n\nGå til Jansens Gård mod nord og Molsens Gård nordvest herfra, og indsaml prøver fra brøndene dér."},
  [92743] = {n="Erobrerens Krone", l="Oprethold dit ry hos Magrom, og bring en Erobrerens Krone fra Ødelandene til Vorrug i Magrom-landsbyen.", d="Som den stærkeste kentaurklan i hele landet fortjener vi rustninger med en vildskab, der matcher vores styrke!\n\nVorrug har mest brug for én. En hjelm... nej, en krone! En erobrerens krone! Jeg har hørt sagn om en frygtindgydende erobrer hinsides havet. Tag til et sted, de kalder Ødelandene, og led efter et gravkammer dér. Vend kun tilbage til mig, når du har fundet kronen.\n\nGør dette for mig, så afslører jeg Magroms største styrke."},
  [92744] = {n="Mudderfisk-gæller", l="Alba Skønmåne vil have, at du samler 7 Langkyst-mudderfisk-gæller langs Vestfalds kyst.", d="Den forurening, der rammer Vestfalds afgrøder, kan også have sivet ud i havet. Hvis fiskene lokalt også er ramt, kan det dømme Stormvind til hungersnød.\r\nSaml gæller fra mudderfiskene langs kysten, og bring dem til mig. Mudderfisk er ret hårdføre, men deres fysiologi er ekstremt følsom over for forurening. Enhver gift i havvandet vil være tydelig i de gæller, du finder."},
  [92745] = {n="Minernes Tilstand", l="Slå 4 Kobold-gravere i Jangolade-minen og 6 Flodpote-minearbejdere i Guldkystens Stenbrud.", d="De brøndprøver, du indsamlede, indeholder giftige metaller! Hvis vi ikke hurtigt får en ende på denne korruption, går der årtier, før der igen kan vokse afgrøder i denne jord.\r\nDefias har overtaget Vestfalds miner og bruger skabninger som arbejdskraft til at tømme dem for ressourcer. Forstyr dem ved at slå deres minearbejdere ned i Jangolade-minen mod nord og Guldkystens Stenbrud mod vest."},
  [92747] = {n="Spionage i Månebæk", l="Saml 8 Mistænkelige Industriforsyninger fra Månebæk.", d="Mærkeligt - giften ser ikke ud til at stamme fra de miner, du undersøgte.\n\nJeg har fået at vide, at Dødsminerne under byen Månebæk er Vestfalds største og dybeste miner, men de har været forladt siden Første Krig. Kunne Dødsminerne være aktive igen?\n\nRejs venligst til Månebæk, <Name>, og led efter tegn på minedrift eller industriel aktivitet. Det er vores sidste spor!"},
  [92748] = {n="Eksplosiv Konsultation", l="Rejs til Dværgekvarteret i Stormvind og find en ingeniør, der kan hjælpe.", d="Forsyningerne, du fandt, peger på en massiv industriel operation et sted i Dødsminerne. Der er ingen tvivl om, at det er kilden til giftene, der plager Vestfalds landbrugsjord. Vi må stoppe den hurtigt.\n\nDet, der er dernede, vil være svært at ødelægge. Gå til Dværgekvarteret i Stormvind, og find en ingeniør, der kan skaffe os nogle sprængstoffer."},
  [92749] = {n="En Dynamitplan", l="Skaf 10 Grov Dynamit ved håndværk, handel eller på auktionshuset, og vend derefter tilbage til Sprite Springfjeder i Dværgekvarteret i Stormvind.", d="Industrisabotage? Nu har du min opmærksomhed!\r\nVi starter med noget dynamit..."},
  [92751] = {n="Detonation på Afstand", l="Bring Fjernudløser-sættet til Sprite Springfjeder i Dværgekvarteret i Stormvind.", d="Har du brug for noget ødelagt? Har det noget at gøre med dine aktiviteter i Månebæk? Lad være med at se overrasket ud. SI:Syv holder øje med alt, der foregår på Stormvinds områder.\n\nHvis du har planer om at sprænge noget i hulerne under Vestfald, vil du gerne være langt væk på forhånd. Tag denne fjernudløser—det er en nylig prototype fra vores egne ingeniører.\n\nÅh—og det ville være bedst, hvis du ikke nævnte min involvering over for din alvekammerat."},
  [92752] = {n="Eksplosiv Konsultation", l="Vend tilbage til Alba Skønmåne i Vestfald.", d="Sådan—bomben er klar til at gå! Pas nu på den udløser."},
  [92753] = {n="Ødelæggelse i Dødsminerne", l="Find smedjen gemt i Dødsminerne, og plant de Ekstra-Ødelæggende Sprængstoffer i nærheden. Mød derefter Alba Skønmåne ved Dødsminernes udgang.", d="Giftens kilde er sandsynligvis en stor metallurgisk smedje af en slags. Find en vej ind i Dødsminerne, lokaliser smedjen, og placer derefter sprængstofferne.\r\nJeg venter på dig i bakkerne bag Månebæk. Når du er tilbage, kan vi detonere sprængstofferne. Forhåbentlig kan landet begynde at hele, når smedjen er væk."},
  [92754] = {n="Et Nyt Behov for Skyggebeskyttelse", l="Oprethold dit ry hos Magrom, og bring 3 Større Skyggebeskyttelseseliksirer til Mirda i Magrom-landsbyen i Forødelse.", d="Vores klanfæller bliver ved med at vove sig længere sydpå, til og forbi den forbandede Knoglernes Dal.\n\nTrods dit ry hos vores klan stoler jeg ikke nok på dig til at dele detaljerne om deres færd. De ville alligevel kede dig, udenforstående.\n\nDet, der betyder noget for dig, er vores behov for Større Skyggebeskyttelseseliksirer i store mængder for at sikre deres fortsatte overlevelse. Bring nogle til mig, så siger jeg et godt ord for dig."},
  [92818] = {n="Store, Nej, ENORME Jernøkser", l="Oprethold dit ry hos Magrom, og bring 2 Massive Jernøkser til Grolkar i Magrom-landsbyen i Forødelse.", d="VI HAR BRUG FOR FLERE VÅBEN.\n\nFLERE. VÅBEN.\n\nHVORDAN SKAL MAGROM ELLERS KNUSE PIVSVAGE GELLEKIS?\n\nJEG VIL SE, HVAD DU KAN LAVE, UDENFORSTÅENDE. BRING MIG ØKSER. STORE, NEJ, ENORME.\n\nSKYND DIG."},
  [92834] = {n="Hævnet Tifold", l="Saml 10 Al'Aketh Vindsten-amuletter fra Al'Aketh-kultister fundet nord for Valanår, enten på Gustbær-markerne eller ved Akirs Helligdom.", d="Da kulten indledte sin voldskampagne, reagerede fredsbevarerne og vindformerne med dumme demonstrationer. Jeg så det som tåbelig eskalering, så jeg talte for fredelig dialog. I går sendte jeg min ven Belathaan Lysønske til Akirs Helligdom i håb om at etablere den dialog.\n\nEn kasse er lige ankommet med Belathaans tunge, dyppet i sølvpigment.\n\nDet står nu klart for mig, at der ikke er nogen grund til at ræsonnere med kulten. Dræb de kultister, du ser, og bring mig de bønneamuletter, de bærer."},
  [92840] = {n="Fange Vinden", l="Tag Indeks Esoteria til Udsigtens Rejsesten i Shen'dar-højlandet, og brug den på vindstensformationerne i området for at indsamle data.", d="Fillion blev sendt til Udsigtens Rejsesten med en særlig enhed, der bruges til at måle og studere den elementære energi dér.\n\nTag denne—et Indeks Esoteria—og brug den til at udtrække data fra de massive vindstensformationer, der står dér. Vær dog på din vagt, for vindformerne vil sandsynligvis vogte stedet nidkært nu.\n\nHvis nogen forsøger at forhindre dig, så... gør hvad du skal. Jeg har ikke mere tålmodighed med deres indblanding."},
  [92849] = {n="Den Savnede Lærde", l="Bliv ved med at lede efter Fillion Flammebrise.", d="<Ud fra det, du lige har fundet, er det meget sandsynligt, at Fillion er kommet ud for et uheld her. Han kan stadig være i nærheden, og han har måske brug for hjælp. Du bemærker en hule lige nord for din nuværende position. Du bør fortsætte med at lede efter ham dér.>"},
  [92850] = {n="Den Savnede Lærde", l="Dræb Skrigeling-matriarken i Skrigelingernes Hule, og bring dens hoved tilbage til Fillion Flammebrise i Valanår.", d="Jeg har det allerede meget bedre. Jeg har en vis fingerfærdighed med de arkane kunster, og vi er kun en kort gåtur fra Valanår. Jeg klarer den selv. Men vigtigere end min egen sikkerhed er, hvor tæt på Valanår disse skrigelinger har slået sig ned, og hvilken fare de udgør. Var I så venlig at gå tilbage derind og tage hovedet af det udyr!\n\nNår det er gjort, finder I mig tilbage i Valanår. Jeg må rapportere til Den Højeste Magister, hvad der er sket her, og hvordan min mission står."},
  [92860] = {n="I Vindras' Tjeneste", l="Rapportér til Valennia Stormnæve, og lad hende vide, at Den Høje Orden står ved deres side i kampen mod Al'Aketh.", d="Den Høje Orden har gjort vores bedste for at undgå direkte konflikt med kulten, men det er tydeligvis ikke længere en mulighed. Deres fjendtlighed er klart demonstreret, og nu går der rygter om kultbevægelser i større skala rundt omkring på øen. De gør sig tydeligvis klar til noget, og uanset hvad det er, kan det ikke være godt for Vindras-folket.\n\nRapportér til Valennia Stormnæve, og oplys hende om, at Den Høje Orden tilbyder vores fulde støtte til Valanårs indsats mod Al'Aketh, hvis behovet skulle opstå."},
  [92871] = {n="I Vindras' Tjeneste", l="Rapportér til Valennia Stormnæve, og lad hende vide, at Vindformerne står ved deres side i kampen mod Al'Aketh.", d="Valennia Stormnæve og hendes fredsbevarere har altid været Vindras' beskyttere, og vi har gjort vores bedste for at yde hjælp, hvor vi kunne. Der går rygter om kultbevægelser i større skala rundt omkring på øen, og de gør sig tydeligvis klar til noget.\n\nRapportér til Valennia, og gentag over for hende, at Vindformerne tilbyder deres fulde støtte til Valanårs indsats mod Al'Aketh, hvis behovet skulle opstå."},
  [92880] = {n="Tilbage til Valanår", l="Bring Yornas Rapport til Valennia Stormnæve i Valanår.", d="Jeg regner med, at det vil tage en stund at rydde op i det, der er tilbage af angriberne, men vores chancer er langt bedre nu. Tag tilbage til Valanår og lad dem vide, at vi nu er stabile her.\n\nJeg kan ikke takke dig nok for din hjælp. Vi ville være i langt værre form uden dig. Jeg bad om forstærkninger, og det viser sig, at jeg i stedet fik en spirende helt. Den tager jeg gerne imod.\n\nMåtte de fire vinde velsigne dig, <Class>."},
  [92881] = {n="Den Høje Ældstes Anmodning", l="Tal med Talaanis Skyggesang i Valanår.", d="Angrebene på både de vestlige og østlige vagttårne er ikke en tilfældighed. Ud fra det, I fortalte os om, hvad der skete ved det vestlige vagttårn med den himmelpræst, er vores bedste gæt, at kulten forsøger at gøre noget ved ankerpylonerne.\n\nTal venligst med Højelder Skyggesang. Han vil fortælle dig om et spor, der kan vise sig at være lovende."},
  [92909] = {n="At Høste Høsterne", l="Ozwin Jernspiral ved Saldeans Gård vil have, at du bringer ham 14 Golem-isospring og 5 Høster-gyrostabilisatorer.", d="Åh nej... nu er jeg havnet i en knibe!\n\nJeg hørte om høsterne, der terroriserer markerne i Vestfald, så jeg rejste hele vejen fra Jernsmede for at se, om jeg kunne rekalibrere dem. Men de er langt mere aggressive, end mine beregninger forudsagde, og de jagtede mig ind i denne stald!\n\nHvis jeg havde nogle isospring og gyrostabilisatorer fra høsterne, kunne jeg bygge en indretning, der kunne dække min flugt. Kunne du samle delene til mig?"},
  [92911] = {n="At Høste Høsterne", l="Ozwin Jernspiral ved Saldeans Gård vil have, at du bringer ham 8 Golem-isospring, 4 Kobbermodulatorer og et Groft Sigte.", d="Jeg forstår... det giver mig et indblik i, hvad der får de monstre til at tikke. Jeg har en idé om, hvordan vi kunne overstyre deres systemer, i hvert fald midlertidigt.\n\nJeg fortsætter med at tinkere med samlingen, du bragte mig. Imens, kunne du så skrabe nogle dele sammen til indretningen?"},
  [92947] = {n="Vi Gør Vores Træk", l="Dræb 7 Al'Aketh-vogtere, 7 Al'Aketh-åndekaldere og 7 Al'Aketh-klingemestre, og rapportér derefter til Hyusaa Hurtigbrise ved Akirs Helligdom.", d="Alle er her, godt. Jeg har lige sendt nogle af mine bedste krigere ind gennem helligdommens forside for at skabe lidt ballade og tjene som afledning, mens jeg fører hovedparten af vores styrke ind fra siden.\n\nHvis alt går vel, burde vi kunne bryde igennem hurtigt og slå højpræstinden ud. Hvad dig angår, så gå derind og begynd at knække kranier. Mød min næstkommanderende, Hyusaa Hurtigbrise, nær trappen til helligdommen, når du har skabt lidt ravage.\n\nVindene vejlede dig, <Class>."},
  [93036] = {n="Infiltrér Kulten", l="Tal med Sania Sølvstrøm i Shen'dar-landsbyen.", d="Du er måske klar over det, men Sania Sølvstrøm derovre er en \"missionær\" for Al'Aketh. De kan lide at lege en almindelig religiøs orden og sender ufarlige udsendinge rundt for at rekruttere. Vi har tålt Sania indtil nu for at undgå direkte konflikt med kulten, men det er tydeligt, at fredens illusion ikke varer meget længere.\n\nDu er ny her og ukendt for de fleste, så jeg vil gerne se, om du kan bruge Sania til at komme tæt på kulten og finde ud af, hvad deres planer er for landsbyen."},
  [93065] = {n="Gør Dig Klar til Kamp", l="Tal med Valennia Stormnæve i Gustbær-lavlandet.", d="Fredsbevarerne mobiliserer, og vi gør alle klar til at rykke ud. Tag de forberedelser, du har brug for, og mød os ved den østlige vej, der fører nordpå ud af byen. Vi har et sidste tjek med alle, før vi bryder op."},
  [93066] = {n="Børsterygge-tilflugtsstedet", l="Oprethold dit ry hos Magrom, og dræb pigsvin ved Børsterygge-tilflugtsstedet. Rapportér derefter til Hagjak ved Magrom-fronten på den anden side af Knoglernes Dal i Forødelse.", d="På den anden side af dalen har vi etableret et lille fodfæste for at gøre os klar til at marchere ind i skoven i nærheden. Før du tager direkte derhen, vil jeg have, at du tager dig af et nyligt Børsterygge-indfald undervejs. De synes at være ankommet omtrent samtidig med os, men de formåede at sikre sig en genstand fra det nærliggende tempel, som har holdt os på afstand.\n\nOpgaven er enkel. Led efter tornene og grisene. Dræb en hel masse, uden forskel. Rapportér derefter til Hagjak i lejren, jeg nævnte."},
  [93089] = {n="Hvad Der Kommer Næste", l="Tal med Elaadrin Aftenvind, når du er klar til at forlade Vindras-øen.", d="Vær venlig at give min tak videre til Elaadrin for alt, Den Høje Orden og jeres nye venner fra dette \"Kirin Tårn\" har gjort for Vindras-øen. Jeg er klar over Den Høje Ordens planer om at forlade øen, og jeres orden har min velsignelse og mine gode ønsker for denne ekspedition.\n\nJeg kan kun håbe, at den arkane løsning, Den Høje Orden finder, virkelig kan give os den stabilitet, vi har manglet de sidste år. Hvis du planlægger at tage med dem... ja, så bliver denne mission kun stærkere af det.\n\nVindene være med dig, <Name>."},
  [93090] = {n="Hvad Der Kommer Næste", l="Tal med Ayessa Morgensang, når du er klar til at forlade Vindras-øen.", d="Vær venlig at give min tak videre til Ayessa for alt, Vindformerne og jeres nye venner fra denne \"Jordringen\" har gjort for Vindras-øen. Jeg er klar over planen om at tage Vindformernes skamaner med og forlade øen, og jeres orden har min velsignelse og mine gode ønsker for denne ekspedition.\n\nJeg kan kun håbe, at den løsning, Vindformerne finder, virkelig kan give os den stabilitet, vi har manglet de sidste år.\n\nVindene være med dig, <Name>."},
  [93159] = {n="Den Mærkelige Eremit", l="Tal med Den Mærkelige Eremit i Skyggestormsskoven, og lær mere om ham.", d="Øh, um... h-hej, jeg mener at sige, hej! Hilsner, endda! Jeg er ked af det... det er, um, så længe siden, jeg sidst har talt med et andet menneske. Jeg er bange for, at jeg er lidt rusten til det her.\n\n<Den mærkelige hætteklædte figur flytter sig ubehageligt foran dig.>\n\nSå øh, um... hvordan går din dag?"},
  [93160] = {n="Skovens Gaver", l="Saml 8 Skyggestorms-agern i Skyggestormsskoven.", d="Jeg sætter virkelig pris på, at du stopper op for at snakke med mig! H-hvis du gerne vil hjælpe, kunne jeg bruge lidt hjælp til at samle agern fra skovbunden. Jeg har samlet de fleste af dem i nærheden, men der er bestemt en masse rovfugle-agtige ting i skoven. Det er farligt derude, og jeg vil helst ikke ende som en gigantisk fugls frokost!\n\nSå hvis du vil, kunne du måske samle dem til mig? Jeg laver noget lækkert til os, hvis du gør!"},
  [93165] = {n="Nåde Falder for Døve Ører", l="Saml 5 Al'Aketh-kultisters ører fra Al'Aketh-kultisterne i Skyggestormsskoven, Akirs Helligdom eller Gustbær-lavlandet.", d="Al'Aketh har forårsaget stor tragedie over vores enklave, og blod må betales med blod.\n\nJeg har et tilbud til dig, fremmede. Hvis du støder på konflikt med disse forbandede kultister, så bring mig ørerne af dem, du dræber. Jeg vil belønne dig for hver enkelt, du bringer, både med mønter og, med tiden, adgang til Nattekloens hemmeligheder, hvis du viser dig at være en sand ven."},
  [93172] = {n="Befri Hulerne", l="Ødelæg 10 Vindhuler i Skyggestormsskoven.", d="De fleste af alverne på denne ø synes, at disse skove er hjemsøgte, og de tager ikke fejl.\n\nVed de gamle ruiner mod nordøst samler der sig en særlig slags spøgelsesagtige ånder. Nogle nætter kan man næsten høre dem \"synge\". Det er ikke som nogen sang, jeg har hørt før, men det er klart en sang, og den er... bare så trist.\n\nJeg er ikke sikker på hvorfor, men jeg tror, at der er sket noget frygteligt der på et tidspunkt, og at ånderne er fanget der på en eller anden måde. Hvis du føler dig modig, kan du måske hjælpe med at befri dem?"},
  [93176] = {n="Mine Små Venner", l="Brug tingene i Entomologi-startsættet til at finde og fange en Træ-tarantel, et Hø-snudebille-specimen og et Kødplukker-specimen.", d="Beundrer du min lille menageri? Det er mit unlivs livsværk. Jeg har brugt utallige timer på at studere dem: deres anatomi, deres kost, endda deres sociale ritualer.\n\nVil du være med i hobbyen? Her, tag denne pakke. Noterne og materialerne indeni burde få dig i gang. Hvis du mister den, må du købe en ny hos mig for et lille gebyr."},
  [93225] = {n="Udskårne Kentaur-totemer", l="Skaf 5 Udskårne Kentaur-totemer ved at dræbe kentaurer af enhver klan i hele Forødelse, og bring dem derefter til Gurda Vildmanke ved Spøgelsesvandrer-posten.", d="Jeg har bemærket, at kentaurer fra forskellige klaner nogle gange samles væk fra bosættelser og handler med hinanden. Det har jeg set over mange nætter og tilsyneladende hos alle klaner; vigtigst af alt har jeg set den valuta, de bruger: udskårne totemer.\n\nJeg tror, vi kan vende tidevandet til vores fordel med enten Gellekis eller Magrom, hvis vi leverer en tung bundt totemer lige til dem. Jeg er allerede begyndt at udskære nogle, men jeg tvivler på, at de let lader sig narre uden nogle få ægte."},
  [93317] = {n="Krabbesæson", l="Saml 6 stykker Vindsang-kryberkød.", d="Kender du Vindsang-krybere? Ser du, disse krabber findes kun i Vindsang-søen her på Vindras, og de kan kun høstes et par uger om året.\n\nMed al den kultaktivitet på det sidste har jeg ikke kunnet komme ud til søen for at høste dem, og vores tidsvindue lukker hurtigt. Jeg ville sætte pris på, hvis du kunne tage derud og samle nogle til mig. De findes som regel langs bredderne rundt om søen og i floderne.\n\nVær dog forsigtig, de er værre, end de ser ud!"},
  [93318] = {n="EFTERLYST: Vulgara den Umættelige", l="Dræb Vulgara den Umættelige i Shen'dar-højlandet, og bring hendes hoved til Danarii Brølslør.", d="Efter ordre fra Konstabel Aonda fra Fredsbevarerne udlodes hermed en dusør på højlandets plage, Vulgara den Umættelige. Sidst set på en bakketop lige sydvest for Shen'dar-landsbyen er det vingede vuldren-rædsel yderst farligt og bør nærmes med forsigtighed.\n\nLever udyrets hoved til Danarii Brølslør for at modtage din belønning."},
  [93319] = {n="Stjålne Vindsten", l="Saml 10 Stjålne Vindsten fra Højlands-banditterne i Shen'dar-højlandet.", d="Vi er mere og mere afhængige af vindsten til dagligdags liv her på Vindras, så vi forsøger at holde et lager af dem i reserve til nødsituationer. For nylig har jeg bemærket, at nogle forsvinder fra vores lagre.\n\nVi har fundet vindsten på banditter, vi for nylig har taget til fange, og jeg mistænker dem for at stå bag vores mangel.\n\nHvis du befinder dig nær banditgrotten mod nord, må du gerne banke nogle hoveder sammen og genvinde nogle af vores stjålne vindsten til mig?"},
  [93320] = {n="Tårnforsvar", l="Rapportér til Yorana Vindrør ved det østlige vagttårn i Gustbær-lavlandet.", d="Jeg har lige fået besked om, at kulten angriber pylon-vagttårnet lige uden for byen! Jeg har sendt de få ekstra fredsbevarere, vi har her, for at forsøge at bryde igennem fjendens bagerste linje og lette forsvarerne, men enhver ekstra hjælp kan være forskellen på, om vores folk dør eller lever derovre.\n\nTag venligst øjeblikkeligt til det østlige vagttårn og yd den hjælp, du kan.\n\nMin løjtnant, Yorana Vindrør, førte aflastningsstyrken. Hvis hun stadig lever, kan hun fortælle dig, hvordan du bedst hjælper."},
  [93459] = {n="Flere Al'Aketh-ører", l="Saml 10 Al'Aketh-kultisters ører fra Al'Aketh i Skyggestormsskoven, Akirs Helligdom eller Gustbær-lavlandet, og bring dem til Vayn Månekløer i Skyggestormsskoven.", d="Al'Aketh-kulten holder normalt en god afstand til denne skov af frygt for rygterne om, at den er hjemsøgt... rygter, vi er glade for at opretholde. Mine ordens druider ønsker blot at leve stille og fredfyldte liv her i Skyggestorm, og det truer de med.\n\nMange blandt os er bange.\n\nJeg kommer med et tilbud. Kæmp mod kultisterne for os, og bring os ørerne af dem, du dræber. Vi vil belønne dig for hver enkelt, du bringer, både med mønter og, med tiden, adgang til vores hemmeligheder, hvis du viser dig at være en sand ven."},
  [93461] = {n="Velkommen til Shen'dar-landsbyen", l="Tal med Rathiril Solsvinge og Coriella Stilvind i Shen'dar-landsbyen.", d="Du har det der \"Høje Orden\"-udseende over dig. Dem med højfødt afstamning har altid et lille glimt i øjnene, der røber det. Før jeg rigtigt sætter dig i arbejde her omkring, bør du tjekke ind hos vores lokale ældste i Den Høje Orden, Rathiril Solsvinge. Du finder ham her i hovedlogen, lige rundt om hjørnet fra mig.\n\nÅh, og tjek også ind hos Coriella Stilvind, hun driver den lokale kro og kan give logi og forsyninger, hvis du har brug for dem."},
  [93552] = {n="Høstning af Vindsten", l="Saml 15 Vindsten-klynger fra Rå Vindsten i Thendal-lunden.", d="Vindsten er en kritisk ressource på Vindras-øen, for de indeholder vindenes egen rå, koncentrerede energi. Vindelementarerne, som engang boede her på Vindras sammen med os, forsvandt for en del år siden, og siden da er magien, der holder denne ø i live, langsomt ved at dø hen. Ikke uden begrænsninger, men vindstenene er stadig en pålidelig energikilde, og de er uhyre værdifulde for os.\n\nDu finder rå vindsten spredt rundt i lunden. Tror du, du kan hjælpe mig med at høste dem?"},
  [93663] = {n="Tabt Undervejs", l="Find den savnede kurer, og sørg for, at Dårs forsendelse bliver leveret til Havnelyet.", d="Draenierne i Havnelyet er dygtige fiskere, og de er villige til at trawle farligere farvande end jeg. Vi handler en gang imellem. De giver os noget af deres fangst, og jeg tilbyder noget af vores ekstra forsyninger.\n\nJeg sendte en kobold-kurer af sted med min seneste forsendelse, men han kom aldrig tilbage. En krokolisk har nok gjort ham til et måltid.\n\nVigtigere er det, at mit forretningsry står på spil. Forsendelsen må findes og leveres til Havnelyet. Find den venligst, hvis du kan. Kig efter ved vandet langs vejen."},
  [93680] = {n="Nøglen til Byen", l="Skaf Dalarn-kloakkens Nøgle til Magus Ordeen Tomglimt i Tarrenmølle.", d="Alliancen havde en hær af magikere kendt som Kirin Tårn. Selvom de var mægtige, viste den dæmoniske Brændende Legion sig at være endnu mægtigere. Med ét slag jævnede ærke-dæmonen Archimonde deres by med jorden, som om den var et barns legetøj. Dem, der blev tilbage, blev reduceret til blot fordrevne landevejsrøvere.\n\nSådan var det, indtil de genopbyggede Dalarn. Og lige på Den Mørke Dames dørtrin, endda!\n\nMens I er i deres lejre, så led efter noget, der kan få os ind i byen uden at blive set. Jeg må vide mere."},
  [93735] = {n="Det Knuste Konstrukt", l="Find Riaani Natvind på Valanårs vestside.", d="Historisk set har Vindformerne stået for plejen af de magiske instrumenter og apparater, som vindens ånder gav os. Dette omfatter den utallige mængde magiske konstrukter rundt om øen. Siden ånderne forlod os, er kun en sparsom håndfuld af disse stadig funktionsdygtige.\n\nEt af de få tilbageværende fungerende konstrukter i Valanår er blevet beskadiget. En af vores håndværkere blev sendt for at hjælpe, men han kan have brug for hjælp. Rejs til byens vestlige ende og tilbyd den assistance, du kan."},
  [93736] = {n="Uvelkomne Ånder", l="Saml 10 Vindhule-essenser fra Vindhuler i Skyggestormsskoven.", d="Vindformernes største bekymring er at forstå bedre, hvorfor ånderne forlod os, og hvad vi kan gøre for at få dem tilbage. Et mærkeligt træk ved Skyggestormsskoven mod nord er tilstedeværelsen af en særegen form for vindsprite, som nogle kalder \"hulere\". Vi ved lidt om dem og om, hvorfor de er der, men vi ved, at de første begyndte at dukke op, efter vindens ånder forlod os.\n\nJeg har brug for, at du tager derhen og spreder dem. Saml resterne og bring dem tilbage hertil."},
  [93737] = {n="Det Knuste Konstrukt", l="Tal med Riaani Natvind og hør, hvad han har at sige.", d="Å, hej. Ayessa sendte dig for at hjælpe mig? Fint nok.\n\nJeg er ikke sikker på, hvad en åbenlys novice som dig kan udrette, men hvis du giver mig et øjeblik til at trække hovedet ud af dette konstrukts indvolde, har jeg måske et par idéer til ting, du kan gøre for at hjælpe."},
  [93738] = {n="Det Knuste Konstrukt", l="Rapportér tilbage til Ayessa Morgensang i Valanår.", d="Lysønske, hva? Så Den Høje Orden ville fjerne disse dele af en eller anden grund. Men hvorfor egentlig?\n\nDen Høje Orden har altid været påtrængende og konstant ivrig efter at eksperimentere med vindånders magi. De er alt for dristige, og vi har strengt forbudt dem at blande sig i viden under Vindformernes ansvarsområde, men på det seneste har de sat vores tålmodighed på prøve.\n\nJeg synes, du skal rapportere, hvad du har fundet ud af, tilbage til Ayessa Morgensang. Hun kan vejlede dig videre om, hvad du skal gøre."},
  [93739] = {n="Udforskning af Horden", l="Tal med Nazgrøl i Grommash-borgen for at få yderligere instrukser. Brug de instrukser, du modtager, til at finde og tale med Vol'dzjin, Kærne Blodhov og Frue Silvanas Vindløber.", d="Azerot er en stor verden, og Hordens område er enormt. Undergrunden, Orgrimgrad og Tordenklippe har alle meget særegne folk og kulturer.\n\nHvis du skal være Hordens gæst her på Azerot, vil det gøre dig godt at besøge hver af vores hovedstæder i rækkefølge. Tal med min rådgiver Nazgrøl for vejvisning."},
  [93740] = {n="Blod for Blod", l="Saml 10 Al'Aketh Vindsten-amuletter fra ligene af Al'Aketh-kultister i Gustbær-lavlandet.", d="Et antal af vores Vindformer-noviser blev fundet døde i højlandet i morges. Vi kan ikke være sikre, men der er en stærk chance for, at Al'Aketh står bag. Vindformerne tager blod for blod, hver gang.\n\nTag mod nord og dræb enhver Al'Aketh, du støder på. Bring mig deres vindsten-bønneamuletter som bevis på gerningen. Vi tilgiver ikke, og vi glemmer ikke."},
  [93746] = {n="Et Fast Svar", l="Konfrontér Belathaan Lysønske på vejen til Akirs Helligdom.", d="Den Høje Orden er blevet advaret om følgerne af at blande sig i Vindformernes anliggender. Jeg synes, vi må statuere et eksempel med Belathaan og sende ham tilbage til Den Høje Orden med et par blå øjne og en sund respekt for de grænser, vi har sat.\n\nBelathaan blev set forlade byen og rejse mod nord mod Akirs Helligdom. Jeg ved ikke, hvorfor han skulle derhen, men at konfrontere ham alene på vejen er det sikreste valg. Find ham, og bang lidt skræk ind i hans hjerte."},
  [93791] = {n="Tal med Belann", l="Tal med Belann Vindskov i Valanår.", d="<Name>, det står klart, at din magiske dygtighed vokser, og jeg mener, det er på tide, at du deltager i en af Den Høje Ordens ældste traditioner for unge og ambitiøse magikere. Det er tid til, at du skaber et fokus for dine besværgelser.\n\nSøg Belann Vindskov i Valanår. Han har fremstillet stave og tryllestave for Den Høje Orden i over et århundrede, så du er i gode hænder."},
  [93797] = {n="Grene i Vinden", l="Bring en Vindgennemsyret Gren til Belann Vindskov i Valanår.", d="Det er en traditionsrig skik, at unge magikere skaber deres eget besværgelsesfokus, når de har vist en vis grad af magisk færdighed. Det gøres typisk ved at samle en faldet gren fra vores ældste træer, for de har nogle resterende spor af elementar vind.\n\nJeg har fundet de mest ideelle nær vindhelligdommen, lige syd for Falaath-landsbyen. Gå og bring mig en stor gren tilbage, så lærer jeg dig traditionerne, mens vi skaber dit besværgelsesfokus."},
  [93835] = {n="Konfrontation med Lorthuna", l="Tag portalen op til Rohashi-tårnene oven over og slut dig til Elaadrin Aftenvind og Ayessa Morgensang i deres konfrontation med Højpræstinde Lorthuna.", d="Lorthuna flygtede op til tårnene ovenover ved hjælp af en slags portal. Ayessa og Elaadrin gik efter hende. Det var for få øjeblikke siden.\n\nJeg er bange for, at jeg fik et slag for meget, og her bliver jeg. Gå gennem portalen, find Elaadrin og hjælp dem med at stoppe Lorthuna.\n\nMedmindre den hjælp, som Elaadrin og Ayessa sagde, de havde sendt efter, ankommer snart, er du alene herfra. Held og lykke, <Class>."},
  [93836] = {n="Vindras' Skæbne", l="Tal med Talaanis Skyggesang i Valanår.", d="Muln har fortalt mig meget om elementarherrerne, og jeg er bange for, at vi har god grund til at frygte Al'Akir. Nu hvor de beskyttelser, der har skjult Vindras for hans blik, er nede, er vi fuldstændig værgeløse. Hvis han vælger at angribe os, har vi ingen chance mod ham her i hans eget domæne.\n\nHøjelder Skyggesang må vide, hvilken fare vi befinder os i, og endnu vigtigere, hvad vores hensigter er med vores mission til Azerot. Vi vil finde måden at redde vores hjem på. Det sværger jeg."},
  [93926] = {n="Den Vestlige Vagt", l="Find Fredsbevarer Vaaniel ved det vestlige vagttårn.", d="Uanset hvilken grund kulten har til at angribe tårnet, er den ikke værd at miste vores folk for.\n\nJeg vil gerne bede dig tage sydvest på og tjekke vagttårnet for os. Find fredsbevarerne der og bed dem vende tilbage til landsbyen. At holde det tårn er ikke de liv værd, det ville koste, og jeg vil hellere koncentrere de forsvarere, vi har her, om at beskytte vores borgere.\n\nFredsbevarer Vaaniel har ansvaret; sig til ham, at han skal vende tilbage hertil så hurtigt som muligt. Skynd dig!"},
  [93927] = {n="En Sidste Anmodning", l="Saml seddelen, du fandt nær den døde fredsbevarer, og læs den for at fastslå dine næste skridt.", d="<Mens du undersøger den døde fredsbevarers lig, falder en blodplettet seddel løs fra hans hænder. Hvis du samler den op og læser den, kan den give dig et fingerpeg om, hvordan du skal komme videre herfra.>"},
  [93928] = {n="Om Mus og Mælk", l="Giv musen en småkage.", d="Jeg har brug for en småkage, ser du?\n\nNyeah!"},
  [93948] = {n="Lever Signetet", l="Lever Skyggesang-familiens Signet til Talaanis Skyggesang i Valanår.", d="Da du alligevel skal til Valanår, så vær venlig at levere signetringen, du fandt i tårnet, til Talaanis Skyggesang i Valanår.\n\nHan vil have den tilbage, og endnu vigtigere vil han gerne vide, hvad der er sket med hans nevø. Talaanis er Højelder på Vindras-øen, og endnu vigtigere er han en god mand, som folket holder meget af på trods af vores nuværende prøvelser. Det gør ondt at tænke på, hvordan han vil reagere på denne nyhed. Vær venlig at udtrykke min medfølelse for hans tab."},
  [93949] = {n="Bugget", l="Dræb Himmelspringere i Valanår, indtil du har udryddet 8 Fortryllede Himmelspringere.", d="Vi er blevet bugget.\n\nDet er himmelspringer-sæson i lavlandet, hvilket betyder, at skadedyrene er overalt. En af magikerne i Den Høje Orden meldte, at et af de insekter, de dræbte, havde fået en slags fortryllelse påsat. Da vi undersøgte det nærmere, så det ud til at være en slags aflytningsbesværgelse.\n\nVi mistænker, at kulten bruger disse fortryllede insekter som spioner. Gå og udryd dem for os. Du kan ikke se, hvilke der er fortryllede, bare ved at kigge på dem, så du må simpelthen dræbe dem alle."},
  [93951] = {n="En Lille Skønhed", l="Saml 8 Hippogryf-dunfjer i Shen'dar-højlandet.", d="Hippogrypherne, der har slået sig ned sydvest for landsbyen, kan være til besvær, men de byder også på en ganske særlig mulighed for at skaffe deres fjer. Mange himmelbårne elsker at pryde deres hår med mangefarvede fjerbuske, og hippogryfens dunfjer er usædvanligt farverige og, endnu vigtigere, silkeblødte.\n\nHvis du er på vej den vej, så prøv at samle så mange af de faldne fjer, du kan, omkring deres redeområder. Vær forsigtig, for vilde hippogryffer tåler ikke gæster."},
  [93958] = {n="Det Indre Sanktuarium", l="Tal med Valennia Stormnæve inde i det indre sanktuarium ved Akirs Helligdom.", d="Valennias styrker har lige brudt ind i det indre sanktuarium. Kampene var voldsomme derinde i starten, men det er blevet... urovækkende stille. Gå derind og gør dit bedste for at forene dig med Valennia og hendes styrker... hvis nogen af dem er tilbage.\n\nJeg bliver her og holder øje med din ryg."},
  [93963] = {n="Udforskning af Alliancen", l="Tal med Randal Emersen i Stormvinds Fæstning for at få yderligere instrukser. Brug de instrukser, du modtager, til at finde og tale med Kong Magni Bronzeskæg, Højtinker Mekkatorque og Tyrande Hviskevind.", d="Stormvind, Jernsmede og Darnassos har alle unikke folk og kulturer. Som gæst i Alliancen her på Azerot bør du tage dig tid til at besøge hver af vores hovedstæder i rækkefølge.\n\nTal med Randal Emersen i det sydlige forkammer for vejvisning, så du kan komme i gang."},
  [94003] = {n="Himmelbryderens Bolværk", l="Genvind Himmelbryderens Bolværk fra Zaal Stormskjold ved Akirs Helligdom.", d="Jeg er alt, hvad der er tilbage af Himmelbryder-slægten her på Vindras-øen. Resten blev myrdet af Al'Aketh.\n\nDet eneste, der vejer tungere end min sorg, er min skam. Min families arvede skjold--Himmelbryderens Bolværk--er nu i hænderne på en kultist ved navn Zaal Stormskjold. Familiens overlevering siger, at ingen skade kan ramme en værdig bærer af dette skjold.\n\nZaal er ikke værdig, det er jeg sikker på. Find manden ved Akirs Helligdom, og genvind mit skjold fra ham. Gør du det, lærer jeg dig Himmelbryder-forsvaret."},
  [94006] = {n="Den Store Ursera-ånd", l="Tal med Urs'endris ved vandfaldet nordøst for Valanår.", d="Hilsen, <Name>. Du er nået så langt i dine druidestudier, at jeg mener, det er tid til, at du møder en af de store ånder, der bor her på Vindras. Urs'endris er en vis og ædel ånd, som i generationer har lært druider at antage bjørnsera-skikkelsen. Desværre er hans domæne begyndt at visne hen og falde ud i himlen ligesom mange andre områder på Vindras.\n\nFor at finde ham, rejs mod nordøst nær vandfaldet i skyggen af Akirs Helligdom. Han burde kunne vejlede dig yderligere."},
  [94007] = {n="At Tæmme Bæstet", l="Rapportér til Quel'ana Hurtigvind i Valanår.", d="Nu hvor du har fået en vis tryghed i højlandets vildmark, mener jeg, det er tid til, at du søger din helt egen dyrefælle.\n\nTag til havnen i Valanår mod sydøst, og tal med Quel'ana Hurtigvind dér. Han vil lære dig kunsten at tæmme bestier."},
  [94013] = {n="Tæmning af Udyret", l="Brug Tæmmestaven til at tæmme en Vuldren-alfa i Gustbær-lavlandet. Øv dine færdigheder, og vend derefter Tæmmestaven tilbage til Quel'ana Hurtigvind i Valanår.", d="Du er vendt triumferende tilbage efter at have tæmmet to udyr. Nu er det tid til din sidste prøve. Vindene fra Vindras hvisker om større udfordringer forude.\n\nTag denne Tæmmestav og rejs til Gustbær-lavlandet. Der skal du tæmme en Vuldren-alfa og bevise din mestring.\n\nFuldfør denne lektion, så er du klar til at lære jægerens dybere veje."},
  [94050] = {n="Træning af Udyret", l="Tal med Quel'dora Hurtigvind i Valanår.", d="Du har nu magten til at tæmme et kæledyr, men du må også lære at træne det. Til det findes der ingen bedre end min søster, Quel'dora. Hun vil give dig evnen til at træne dit nye kæledyr.\n\nGå med vindene, unge <Class>."},
  [94214] = {n="Håndværkerens Brev: Skyggebeskyttelseseliksir", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet markeret på dit kort. Dette brev skal være i din besiddelse for at fuldføre handelen.", d="<Med falmet blæk er seddelen skrevet og beder om 1 Skyggebeskyttelseseliksir, samt oplysninger om leveringssted og betaling. Nederst står der tekst, der angiver, at dette brev kan overdrages.>"},
