  [94254] = {n="Håndværkerens Brev: Større Adeptkappe", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet markeret på dit kort. Dette brev skal være i din besiddelse for at fuldføre handelen.", d="<Med falmet blæk er seddelen skrevet og beder om 1 Større Adeptkappe, samt oplysninger om leveringssted og betaling. Nederst står der tekst, der angiver, at dette brev kan overdrages.>"},
  [94369] = {n="Skæbnen for Vindras", l="Tal med Talanaanis Skyggesang i Valanår.", d="Ansirem har fortalt mig meget om elementarherrerne, og jeg frygter, at vi har god grund til at frygte Al'Akir nu, hvor beskyttelsesmurene, der har skjult Vindras, er faldet. Hvis Vindherren vælger at angribe os, har vi ingen chance for at forsvare os, mens vi er her i hans rige.\n\nHøjelder Skyggesang må få at vide, hvilken fare vi befinder os i, og endnu vigtigere, hvad vores hensigter er med vores mission til Azerot. Vi vil finde midlerne til at redde vores hjem. Det sværger jeg."},
  [94373] = {n="Jordens Kald", l="Bring 2 Frostmanke-bjørnevedhæng til Teo Hammerdyn i Ambolmar.", d="Ja, tiden er kommet, unge sjaman. I er blevet stærke og robuste, ligesom stenen under vores støvler. At tage sjamanens sti viser, at I har bjergets visdom, selv før I har bevist jer selv... I har stenens sejhed til at gå jordens vej.\n\nMen for at opnå dens gunst skal I møde den ordentligt. Syd for her bor Frostmanke-trolde i en hule.\n\nBring mig to af de halskæder, de bærer, lavet af Isklo-bjørnene. Så taler vi mere om jeres fremtid."},
  [94374] = {n="Jordens Kald", l="Find Åndsstenen og drik Jordsapta.", d="Ja, sapta er en brygget med magi, der binder vores ånd til elementerne. Kun få sjamaner kender opskriften, og den er ikke for de svage af vilje. Drik den, og I vil se, hvad andre ikke kan. Hold fast – den må kun drikkes på et helligt sted.\n\nGå nordpå til Åndsstenen, gemt for enden af en skjult sti op ad bjerget. Drik den der... se, hvad jorden har at vise jer."},
  [94375] = {n="Jordens Kald", l="Bring Grov Kvarts til Teo Hammerdyn i Ambolmar.", d="Tag denne grove kvarts fra mig og bring den til Teo Hammerdyn som bevis på vores møde. Han vil smede en totem til jer, og denne sten bliver dens hjerte. Så lille den end ser ud, vil I komme til at se, at størrelse ikke er det afgørende, og at selv de mindste ting kan overleve mange andre.\n\nVær tålmodig, <Name>. Forbliv stærk. Og søg visdom. Det er, hvad jorden kræver af jer. Til sidst skal I blive ét med jorden – respektér den, ligesom den vil respektere jer."},
  [94411] = {n="Pågående Magikere", l="Dræb 6 Den Høje Ordens Lærlinge i Shen'dar-højlandet.", d="Vær advaret: Medlemmer af Den Høje Orden er set i nærheden af de stående sten nord for landsbyen. Vi har advaret dem gang på gang om ikke at blande sig på vores hellige steder, men de bliver mere og mere frække i deres forsøg på at skubbe os. Bevis din beslutsomhed over for os ved at gå til de stående sten og sprede dem.\n\nJeg har ingen lyst til at billige direkte blodsudgydelse, men gør, hvad du må for at drive dem væk. Vend tilbage til mig, når det er gjort."},
  [94413] = {n="En Magisk Fornærmelse", l="Dræb 6 Vindformer-novicesynsker i Shen'dar-højlandet.", d="Den nylige fremkomst af ley-linjerne på Vindras' overflade har været enorm for vores orden. Vi har nu mere direkte og håndgribelig adgang til de energier, der gennemtrænger dette sted, og det har øget vores forståelse af magien betydeligt.\n\nVindformerne derimod ser disse fremkomster som ar i landskabet, der skal \"helbredes\". Det er en fornærmelse mod vores orden, og det er noget, vi simpelthen ikke kan tåle.\n\nGå til ley-linjen i skoven mod sydvest og jag de Vindformere, du finder der, på flugt."},
  [94414] = {n="Vindras' Ankre", l="Tal med Halaan Falkeøje og lån hans gave for at se ankertårnet i det fjerne.", d="Hilsen, unge <Name>. Jeg kommer ofte hertil for at betragte det gamle ankertårn. Gaver fra vindens ånder binder og opretholder vores ø. Men på det seneste er deres magi blevet ustabil og inkonsekvent.\n\nJeg kan ikke se, at de lider nød. Deres pragt har ikke ændret sig.\n\nHvis du vil, kan jeg låne dig min gave, så du selv kan betragte dem."},
  [94427] = {n="En Lektion i Guddommelighed", l="Tal med Tanis Ellertræ i Undergrunden.", d="En central egenskab ved at være paladin er stræben efter guddommelighed. Ikke stræben efter gudedom, men blot stræben efter det gode i sig selv, for det godes skyld. Vi er alle endt her på grund af tragedie af den ene eller anden slags, og det ville være let at miste den nåde, der definerede os som paladiner i livet.\n\nGå til Undergrunden og søg Tanis Ellertræ i Handelskvarteret. De er i nød, og de kunne have stor gavn af lidt nåde."},
  [94434] = {n="En Lektion i Guddommelighed", l="Bring 10 Linnedstof til Tanis Ellertræ i Undergrunden.", d="Vent, vil du... hjælpe? Hvorfor skulle en paladin ønske at hjælpe en tigger som mig?\n\nNå, jeg antager, at du kunne være til en vis hjælp.\n\nDet er min kone, ser du. Hun er, tja... hun går i stykker. Jeg mener det bogstaveligt. Apotekerne kan sy hende sammen igen, så godt som nyt, men de har travlt med Den Mørke Dames ærinde, og ingen er ledige til at hjælpe. Hvis du måske kunne bringe mig noget friskt stof, kunne jeg i det mindste lave hende et forbinding, der kan holde hende samlet, mens vi venter på apotekerne."},
  [94435] = {n="En Lektion i Guddommelighed", l="Vend tilbage til Danitha Mør i Bandarion-borgen.", d="Jeg ved ikke, hvorfor du gider gå ud af din vej for at hjælpe mig, men jeg sætter pris på det. Hvis nogen sendte dig min vej, så fortæl dem, at jeg også sætter pris på dem. Du vil altid have en ven i Tanis Ellertræ, <Class>."},
  [94436] = {n="En Lektion i Guddommelighed", l="Tal med Dødevagt Billmod i Bandarion-borgen.\n\nSkulle du miste dit Livets Symbol, så vend tilbage til Danitha Mør for et nyt.", d="Det er tid til at demonstrere din evne til at kanalisere et af lysets største gaver.\n\nDen genstand, jeg lige gav dig, kaldes Livets Symbol. Pas på, for det kan forårsage dig noget ubehag at håndtere en talisman af lyset som denne. Lyset kan være en forbandelse for kraften, der skabte os, men det er stadig vores vejleder og allierede. Smerten minder os om det.\n\nGå og se Dødevagt Billmod nedenunder. Han er lige ankommet, og han har bedt os om hjælp. Vis ham og De Forladte, hvad en ægte paladin kan.", c="Tal med Dødevagt Billmod i Bandarion-borgen."},
  [94438] = {n="En Lektion i Guddommelighed", l="Tag Livets Symbol og brug det til at genoplive Dødevagt Falgan i Giftspindel-dalen.\n\nSkulle du miste dit Livets Symbol, så vend tilbage til Danitha Mør for et nyt.", d="Falgan og jeg blev sendt på en mission for at spejde skarlagenrød aktivitet i Giftspindel-dalen. Vi lykkedes med at snige os tæt nok på en af deres lejre til at høre om nye ordrer om et angreb på Gryde-by. Før vi kunne beslutte, hvad vi skulle gøre næste, trådte jeg på en kvist, og larmen alarmerede dem om os.\n\nFalgan råbte, at jeg skulle løbe, så det gjorde jeg. Da jeg indså, at han ikke var med mig, var jeg halvvejs til Gryde-by. Den modige idiot er nok blevet tilbage for at holde dem væk fra mig.\n\nVær venlig, find min ven og hjælp ham, hvis du kan.", c="Tag Livets Symbol og brug det til at genoplive Dødevagt Falgan i Giftspindel-dalen."},
  [94440] = {n="En Lektion i Guddommelighed", l="Hent Skarlagenrøde Korstogs Angrebsplaner fra de Skarlagenrøde Korsfarere i Giftspindel-dalen, og vend tilbage til Dødevagt Billmod i Bandarion-borgen.", d="Disse skarlagenrøde korsfarere bærer ofte tasker med deres udsendelsesordrer. Vi ved, at et angreb er på vej, men hvis vi kan få fat i deres ordrer, kan vi advare resten af Dødevagterne og forberede et baghold.\n\nDu er tydeligvis en imponerende paladin. Dræb disse skarlagenrøde dyr, hent en kopi af deres ordrer og bring dem tilbage til Dødevagt Billmod. Han tager det derfra."},
  [94441] = {n="En Lektion i Guddommelighed", l="Tal med Danitha Mør i borgen i Bandarion-borgen.", d="Giv venligst min tak til Danitha Mør og fortæl hende, at resten af Dødevagterne vil høre om den tjeneste, paladinerne i Bandarion-borgen har udført for os.\n\nDu har meget potentiale som paladin, og jeg er stolt over at have dem som dig i De Forladtes rækker. Den Mørke Dame våger over dig, <Name>."},
  [94449] = {n="Ildens Kald", l="Find Bruegs Ildfødt i Dun Frostbakke.", d="Det er længe siden, du sidst blev prøvet, <Name>. Du har vist tålmodighed, ja -- men nu er det tid til, at du lærer om kaos... om ødelæggelse. Ildens kald er højt, og hvis du er klar til at betale dens pris, vil den tale til dig.\n\nSøg Bruegs Ildfødt, langt mod øst i bjergene. Han bor i en hule over Sydportens Forpost. Han vil vide, om du virkelig er klar."},
  [94465] = {n="Ildens Kald", l="Bring Den Hvilende Flammes Fakkel til Braldir Askekappe i Modansøen.", d="Ja, du har styrken til at bære ildtotemet, dreng -- men styrke alene gør dig ikke klar.\n\nUden for Kongernes Dal, i klipperne ved Modansøen, ligger en skjult sti til et af vores hellige tinder. Der vogter Braldir Askekappe Den Hvilende Flammes Helligdom.\n\nTag denne fakkel med til ham -- den viser din hensigt. Bring den tilbage brændende ved helligdommens ildbækken, så skal jeg se til, at du fortjener totemet ordentligt."},
  [94466] = {n="Ildens Kald", l="Bring 1 Ildtjære og 1 Ingrediens-pung til Braldir Askekappe i Modansøen.", d="Bah, du har ikke gået hele den vej for historier, gjorde du, <Name>? Du søger Den Evige Flamme og ildtotemet.\n\nFørst skal du have en jordsapta til at binde din ånd til flammen.\n\nJeg laver den -- men jeg skal bruge to ting: ildtjære fra Tunnelrotte-geomanterne i kobold-hulerne mod nord, og en ingrediens-pung fra en Stensplinter-synsker, der lurer i de sydlige bakker. Farligt arbejde, men værd for flammen."},
  [94467] = {n="Ildens Kald", l="Besejr den Mindre Manifestation af Ild, og læg den Glødende Gnist i ildbækkenet oven på Den Evige Flammes Helligdom.", d="Ildsaptaen er klar, <Name>. Nu står du over for flammen. Brug den ved helligdommen, og klatr så op til toppen. Der vil du se ånden -- han slår ikke til, før du gør det, men han ved, at du ser ham.\n\nSlå hurtigt, dreng. Jo længere du venter, jo stærkere brænder han. Når han falder, tag hans glødende gnister og læg dem i ildbækkenet. Tænd fakkelen og fortjen ildens gunst."},
  [94468] = {n="Ildens Kald", l="Bring Den Evige Flammes Fakkel til Bruegs Ildfødt i Dun Frostbakke.", d="Med fakkelen fast i hånden vender du dig væk fra ildbækkenet og kigger ud over Modansøen. Du mærker en spænding trække i din ånd, da vinden tager til og får flammen til at danse voldsomt.\n\nDu begynder at gå ned ad stien tilbage mod Dun Frostbakke på jagt efter Bruegs Ildfødt."},
  [94472] = {n="Jordsapta", l="Tal med Teo Hammerdyn for en ny Jordsapta."},
  [94484] = {n="Urolig Stilhed", l="Find og tal med Elegael Tornpote i den nordøstlige del af Skyggestormsskoven.", d="Et øjeblik, hvis du vil, <Name>. Er du på vej mod Skyggestormsskoven? Der er et druidekonklave dér i en hule mod nordøst. Jeg har ventet på nyt fra dem, men deres korrespondance er længe forsinket.\n\nMed Ban'aethall i ruiner og al den uro på det seneste bekymrer jeg mig om, at noget frygteligt kan være sket. Vær venlig, hvis du kan, og søg Elegael Tornpote op, og berolig mit sind."},
  [94485] = {n="Tårer fra Damen", l="Saml 8 Damens Tåre-mos.", d="Hvis vi skal redde mine kammerater i Nattekloen-hulen, får jeg brug for nogle ingredienser til en omslag. Den første og vigtigste er et spinkelt mos kaldet Damens Tåre. Det vokser typisk ved bunden af træerne her i Skyggestorm.\n\nDette mos udskiller et klistret stof, der virker som et antiseptisk middel og er perfekt til at binde åbne sår. Jeg har samlet, hvad lidt jeg kan nå, men jeg ved, at der er mere i denne skov.\n\nAf sted, og vær hurtig. Vi får brug for meget, hvis de sårede, jeg efterlod, stadig lever."},
  [94486] = {n="Fjer til Forbinding", l="Saml 20 fjer fra Skyggestorms-skrigelingerne i Skyggestormsskoven.", d="Den anden ingrediens, jeg har brug for til omslaget, er fjer fra Skyggestorms-skrigelingerne, der strejfer rundt i denne skov. I deres unge form har skrigelingerne isolerende fjer, som ville være ideelle at lægge over mosset. Fjerene vil forhindre den antiseptiske saft i at tørre ud og give i det mindste en vis beskyttelse mod elementerne.\n\nVær advaret: skrigelingerne er normalt fredelige, men de har været usædvanligt fjendtlige på det seneste. Deres store klør kan nemt tømme dig for indvolde, hvis du ikke er forsigtig."},
  [94487] = {n="Uønsket og Uværdig", l="Saml 10 Blodplettede Arvestykker fra Al'Aketh-fodsoldaterne og Al'Aketh-stormjægerne i Skyggestormsskoven.", d="Al'Aketh-kultisterne overfaldt os uden nogen advarsel, selvom deres motiver stadig er et mysterium for mig. Jeg vidste, at disse kultister havde skyer mellem ørerne, men jeg havde aldrig forestillet mig, at de ville forstyrre den skrøbelige balance her på Vindras med sådan brutalitet. Gå, slå så mange, du kan, og tag deres arvestykker, hvis de bærer nogen.\n\n<Elegael spytter.>\n\nDisse storm-forbandede kultister fortjener ikke at blive kaldt shen'dorei. Skovens dyr kan få deres kroppe. Deres aske fortjener ikke vindene."},
  [94488] = {n="Båndene, Der Binder", l="Dræb Kommandør Haalien og bring hans hoved til Elegael Tornpote i Skyggestormsskoven.", d="Grunden til kultisternes tilstedeværelse her forbløffer mig stadig, men jeg kan lugte en velkendt duft over blodsudgydelsen.\n\nEn af vores kreds-druider, Haalien, forsvandt for måneder siden. Det ser ud til, at han har smidt sit elendige skind i med kultisterne.\n\nVis ham, hvad der sker, når han udgyder blodet fra sin egen slægt! Tag hans hoved og bring det tilbage til mig."},
  [94489] = {n="Forræderiets Sår", l="Gå ind i Nattehugger-hulen, hel 7 druider og find Jorel Vindsang i Skyggestormsskoven.", d="Jeg er færdig med omslagene. Skynd dig, tag dem med til druiderne i hulen, nord for lysningen. Jeg ved, at mine brødre er i langt værre tilstand end mig. De er sandsynligvis for såret til at læge deres egne sår. Der er så få af os shen'dorei-druider, at hvert liv er dyrebart.\n\nFør du tager afsted, har jeg en egoistisk anmodning. Min makker, Jorel Vindsang, var i yderst kritisk tilstand, da jeg forlod ham. Se til hans sår, hvis han stadig lever."},
  [94490] = {n="Revet Brev", l="Bring det revne brev til Elegael Tornpote i Skyggestormsskoven.", d="<Gemt bag et af Haaliens armbeskyttere er en seddel, der er lidt revet og blodplettet i kampen. Det ser ud til, at den indeholder nyttige oplysninger om kultisternes motiver for angrebet på druidernes hule. Elegael ville være interesseret i disse efterretninger.>"},
  [94491] = {n="Hulens Skæbne", l="Giv brevet til Lotheluum i Valanår og fortæl ham, hvad der er sket.", d="Det synes, at der er en korrespondent, der gemmer sig et sted i Valanår og giver kulten information. Jeg er klart ikke i stand til rejsen, men Lotheluum må vide, hvad der er sket her.\n\nHan bør også kende skæbnen for dem, der ikke længere er iblandt os. Takket være din hjælp tror jeg, vi kan klare resten af situationen herfra, selvom skaden er sket.\n\nSkynd dig venligst, <Name>. Jeg håber, vores veje krydser hinanden igen en dag. Indtil da har jeg kultister at slå ihjel."},
  [94568] = {n="Kultens Sande Planer", l="Tal med Talanaanis Skyggesang og overvær samtalen.", d="Overløberen var tydeligvis bange for, hvad kulten havde planlagt, så meget, at han hoppede af og søgte vores hjælp. Det er virkelig uheldigt, at han er død og tog sine hemmeligheder med sig i graven.\n\nVi må drøfte dette yderligere for at afgøre vores næste skridt."},
  [94638] = {n="Styrke og Barmhjertighed", l="Find og dræb Ur'endra i Shen'dar-højlandet.", d="Du er kommet til mig i håb om at lære at tage en form af styrke. Jeg har en opgave til dig, men den tynger mit hjerte.\n\nMin makker, Ur'endra, har mistet sig selv til vanvid og er begyndt at angribe sin egen slægt. Uden vindene er mange skabninger begyndt at miste sig selv, og med Ur'endras store kraft udgør hun en alvorlig trussel mod den skrøbelige balance. Hun strejfer rundt i Shen'dar-højlandet mod nordvest herfra.\n\nVis mig, at du har modet til at ende hendes lidelse, så giver jeg dig min velsignelse."},
  [94774] = {n="Guddommelig Nåde", l="Tal med Højpræstinde Laurena i Stormvind.", d="Du har vakt vores overordnedes opmærksomhed, <Name>. De har bedt dig om at rejse til Lysets Katedral i Stormvind så hurtigt som muligt. Tilsyneladende mener de, at du allerede har bevist dig selv, og de er klar til at udvide din oplæring. Når du kommer frem, skal du finde Højpræstinde Laurena. Hun vil kunne vejlede dig videre. Held og lykke, og må Lyset være med dig."},
  [94789] = {n="Luftens Kald", l="Find Veyric Tordenvin på Arathi-højlandet.", d="Azerots vinde byder dig velkommen, og snart står du blandt nogle af vores mægtigste slægtninge. Jeg er stolt over at se, hvor langt du er kommet--din fremtid ser lys ud, det må jeg sige.\n\nLuftens element er et vanskeligt at mestre, men jeg har tillid til, at dine evner vil bringe dig igennem enhver udfordring.\n\nBegiv dig mod nord ind i Arathi-højlandet. I dets nordlige bakker finder du Veyric Tordenvin. Han vil lære dig mere."},
  [94819] = {n="Reserveplanen", l="Tal med Højpræstinde Mimse i Jernsmede.", d="<Name>, din Højpræstinde Mimse ønsker en audiens hos dig i Jernsmede. Skynd dig, min kloge ven, din næste prøve nærmer sig hurtigt. Selvom jeg gerne ville være vidne til din races egne særlige riter, er min plads her. Men må Lyset følge dig på dine rejser. Mimse skulle stadig være i den Mystiske Afdeling, når du når byen. Hun venter på dig."},
  [94824] = {n="Forvirrende Glimt", l="Tal med Højpræstinde Mimse i Jernsmede.", d="Det er på tide, at du tager til Stormvind, <Name>. Højpræstinde Mimse i Mysteriernes Hal befaler dig at komme og tale med hende. Det må være noget rigtig godt eller rigtig skidt, siden Højpræstinden personligt ønsker dig dertil, men jeg gætter på, at du kun har gjort det godt for dig selv, og det er en god ting, at hun vil tale med dig.\n\nMen spild ikke for meget tid herude. Jeg ville tage derhen, så snart du kan."},
  [94896] = {n="Hjælp til Flygtningene", l="Saml 8 Forladte Ejendele fra ruinerne af Ban'æthal.", d="Du ser ud som en dygtig eventyrer. Mon du er på vej mod Skyggestormsskoven? Ban'æthal ligger dybt inde i skoven; det er der, vi alle kommer fra.\n\n<Ealåne gestikulerer mod de andre flygtninge.>\n\nVi har for nylig måttet evakuere Ban'æthal, for den begyndte at falde op i himlen. Det skete pludselig og midt om natten. Hvis du er på vej derhen, vil du så llede efter eventuelle ejendele, der er blevet efterladt? Skoven og landsbyen er alt for farlige for os at vende tilbage til nu."},
  [94897] = {n="Den Elskedes Skæbne", l="Find Resån i Ruinerne af Ban'æthal.", d="Hvis du rejser til Ban'æthal, har jeg en egoistisk bøn. Min elskede, Resån... Jeg tror, at han ikke længere er en del af denne verden. Han prøvede at vende tilbage efter forsyninger, selvom jeg bad ham blive. Det er allerede over en uge siden, og jeg frygter det værste.\n\nHvis du finder ham, så tag ham venligst med hjem. Hvis han er omkommet, beder jeg dig om at bringe mig hans arvestykke."},
  [94911] = {n="Naturens Barn", l="Tal med Turak Runetotem i Tordenklippe.", d="Hilsen, unge <Race>. Jeg kan se, at du har meget potentiale i druidekunsterne. Der er en, du måske vil tale med i byen Tordenklippe, ved navn Turak Runetotem. Han vil lære dig, hvordan du når Cenarion-kredsens fæstning på Kalimdør, Månelunden.\n\nDer vil du blive budt velkommen, og druiderne i kredsen vil overføre deres viden til dig.\n\nSom dit folk ville sige--gå med vindens velsignelse, unge. Jeg ønsker dig held og lykke på dine eventyr."},
  [94913] = {n="Månelunden", l="Brug besværgelsen \"Teleportér: Månelunden\" for at rejse til Månelunden. Når du ankommer, skal du tale med Dendrit Stjerneblus i landsbyen Nathavn.", d="Alle druider er velkomne i Månelundens hellige lande. Vogter Remulos--Månelundens beskytter--holder øje med alle druider, der overvintrer der. Jeg vil lære dig den besværgelse, der lader dig transportere dig selv derhen. Brug den, når du søger Månelundens viden eller trøst.\n\nSom din første lektion her på Azerot skal du rejse til Månelunden og tale med Dendrit Stjerneblus i Nathavn om den vej, du nu er på. Held og lykke, unge druide."},
  [94946] = {n="Dalarns Magiske By", l="Tag skærer-skibet fra Vindras-øen til Dalarn By, og tal med Danaaris Stjernestorm, når du ankommer.", d="Jeg havde tænkt mig at være den første af os, der satte fod på Azerot, men nylige begivenheder med sekten har ændret mine planer. Derfor bliver jeg her i Valanår i noget tid. Vær ikke bekymret, for vi har flere magikere, der venter på vores folks ankomst i Dalarn. Jeg vil opfordre dig til at udforske Azerot, mens vi bringer vores anliggender i orden her. Vi vil kalde på agenter som dig, når der er brug for dig.\n\nNår du er klar, skal du gå hen til kajen lige uden for dette hus og gå om bord på skæreren der."},
  [94947] = {n="Velkommen til Azerot", l="Tag Himmelportalen til Stormvind, og mød op hos Bolvar Fordrågon i Stormvinds Fæstning.", d="Det er en stor verden her nede, og vores folk må begynde at brede sig ud og udforske den. Det er der, du kommer ind i billedet.\n\nKirin Tårn er medlem af en \"Alliance\" af ligesindede nationer. Alliancens de facto-hjerte er byen Stormvind mod syd. Elaadrin har bedt mig finde en person, der kan rejse til Stormvind og mødes med regentlordet der, en menneskemand ved navn Bolvar Fordrågon.\n\nNår du er klar, har Kirin Tor-magikerne oprettet et særligt portal, som Den Høje Orden kan bruge til at komme til Stormvind."},
  [94978] = {n="Tæmning af Udyret", l="Brug Tæmmestaven til at tæmme en Vindsang-kryber fundet i nærheden af vandområder. \r\nØv dine færdigheder, og returnér derefter Tæmmestaven til Quel'ana Hurtigvind i Valanår.", d="Enhver jæger begynder med at lære båndet mellem dyr og mester. Dette er din første udfordring. Med tiden vil du tæmme skabninger fra alle verdens hjørner, men lad os for nu starte med vores floder og søer på Vindras.\n\nTag denne Tæmmestav og led efter en Vindsang-kryber.\n\nVis, at du kan vinde dens tillid, og begynd din vej mod ægte mestring."},
  [94979] = {n="Tæmning af Udyret", l="Brug Tæmmestaven til at tæmme en Gnavn Stormvandrer i Gustbær-lavlandet. \r\nØv dine færdigheder, og returnér derefter Tæmmestaven til Quel'ana Hurtigvind i Valanår.", d="Du har bevist, at du kan tæmme floddens kryber. Nu er det tid til at teste dine evner på åbent terræn. Vindras' sletter genlyder af stormvandrerens skrig, en stolt, vingeklædt jæger, der løber som vinden.\n\nTag denne Tæmmestav og led efter en af dem. Rejs til lavlandet og vind dens tillid.\n\nVis, at du er klar til de prøvelser, der venter."},
  [95034] = {n="Gælden", l="Tal med Lumina Vindsang i Gravkammeret.", d="Jeg synes, du bør vide, at det faktisk ikke var gnolderne, der angreb os på vejen.\n\nVi blev angrebet af en gigantisk, ulvelignende skabning, som jeg nu ved hedder en \"varg\". Den slog vores vagter ned og kom efter mig, men Banon kastede sig foran den. Jeg nåede at kaste en besværgelse, der skræmte skabningen, så den flygtede, men Banon var allerede slemt bidt. Han insisterede på, at jeg skulle lade ham ligge, men jeg nægtede.\n\nVi haltede tilbage hertil, da gnolderne fandt os. Det, der skete derefter, var skrækkeligt..."},
  [95036] = {n="Et Månekysset Blad", l="Tal med Trevan Rulle i Gravkammeret, og bring ham de materialer, han har brug for.", d="Trevan fortæller mig, at vargene er en stor trussel mod borgerne i Sølvfyrreskoven. Trods deres styrke og sejhed kan de dræbes, men der er en enkelt, der bare ikke ser ud til at blive død på grund af en ukendt magi.\n\nDet er ham, der angreb os. Han kaldes Gammel Ildøje og er den største og mest ondsindede af deres slags. For at fælde ham har vi brug for en særlig slags våben.\n\nTal med Trevan, så giver han dig en liste over, hvad der skal til for at smede sådan et våben."},
  [95041] = {n="Datasamlerne", l="Saml 7 Nisseborg-arkivdatakort rundt om i Nisseborgen, og aflever dem derefter til Jemma Hurtigskifte i Jernsmede.", d="Før vi flygtede fra Nisseborgen, lavede jeg en hård kopi af min families arkiver. Arkanoteknologiske feltligninger, ubådsskrog-tegninger fra Anden Krig, bedstemor Hurtigskifte's chili-opskrift... vores største præstationer er i de filer.\n\nDet var først, da vi nåede Jernsmede, at jeg opdagede et hul i min rygsæk! Flere hulkort er væk, og uden dem er dataene for rodet til at kunne gendannes.\n\nKortene må være begravet i sneen et sted uden for Nisseborgen. Kunne du finde dem? Jeg ved, det er et langskud..."},
  [95042] = {n="Jagten på Kor-ædelstenen", l="Bring en Kor-ædelsten til Ulric Frostslør i Askedalen.", d="En Forladt paladin... her i Askedalen? Morsomt.\n\nSå du søger en Kor-ædelsten? Ikke overraskende, for de bruges nogle gange af Alliancens paladiner til at styrke magiske våben og redskaber. Hvorfor skulle en faldet paladin som dig være anderledes?\n\nHvis du virkelig ønsker en af ædelstenene, så må du rejse nordpå til ruinerne kendt som Den Sorte Afgrund. Nagaerne, der stadig bruger ædelstenene, er dernede. Gå ikke alene, <Class>."},
  [95065] = {n="Fiskerkonkurrence-tid", l="Bring 1 Blank Pynt og 3 Natkravlere til Gilbert Grå ved havnen i Stormvind.", d="Hvilken udsigt... Det bedste en gammel mand kan ønske sig.\n\nFiskene bider godt nu, men jeg er nede på mit sidste agn. Du har vel ikke nogle reservefiskeredskaber på dig? Nej, selvfølgelig ikke, undskyld mig. Jeg bliver så ophidset ved tanken om at kaste en ny line ud, at det ikke gik op for mig, at jeg nok er en af de få, der altid har udstyr på sig.\n\nKunne du hjælpe med at fylde mit lager op? Catherine Leland har et udvalg af fiskeudstyr lige vest for Handelsdistriktet langs kanalerne. Fortæl hende, at gamle Grå sendte dig."},
  [95140] = {n="Gammel Ildøje", l="Brug Månesølvsklingen til at tilintetgøre Gammel Ildøje i Sølvfyrreskoven.", d="Jeg kan se, at du har dit våben nu, <Class>. Jeg beder til, at det ikke svigter dig.\n\nDe lokale fortæller mig, at Gammel Ildøje jager i et stort område syd for her, og at du normalt kan finde ham nær portene til Gilnæas. Find ham, og brug dit nye blad til at gøre ende på ham. Når det er gjort, skal du vende tilbage, og du vil have Vindformernes taknemmelighed."},
  [95161] = {n="Husk at Jeg Elsker Dig", l="Aflever det Blodplettet Brev til Avette Ødetræ i Skumringsskoven.", d="Hvis du leder efter Jeremy Hjertevæver, er din bedste chance at tale med hans nyligt adoptive mor, Avette Ødetræ, derude i Skumringsskoven. Sød kvinde. Hun har nok brug for et par ekstra hænder til sit arbejde, men det er bedre end at blive på børnehjemmet.\n\nHvis du ser lille Jeremy, så husk at fortælle ham, at vi alle tænker på ham, ikke sandt?"},
  [95189] = {n="Herrelandenes Våbenskjold", l="Returnér Herrelandenes Våbenskjold til Lady Dena Kennedi i Stormvind By.", d="<Et forvitret våbenskjold med Herrelandenes mærke. Med så få relikvier tilbage efter kongedømmets fald, ville nogen i Stormvind være meget interesserede i at få fat i dette.>", c="Returnér Herrelandenes Våbenskjold til Lady Dena Kennedi i Stormvind By."},
  [95195] = {n="Blodige Insignier", l="Saml 10 Blodige Insignier, og tag dem med til General Marcus Jonatan i Stormvind By.", d="<Det gamle Alliance-insignia ser ud til at have tilhørt en soldat fra Herrelandene. Disse ruiner er sandsynligvis fyldt med lignende medaljer, som levende pårørende ville være taknemmelige for at få tilbage.>"},
  [95204] = {n="Herrelandenes Våbenskjold", l="Bring Herrelandenes Våbenskjold til Oran Slangevrid i Undergrunden.", d="<Et forvitret våbenskjold med Herrelandenes mærke. Med så få relikvier tilbage efter kongedømmets fald, ville nogen i Undergrunden være meget interesserede i at få fat i dette.>"},
  [95212] = {n="Aldrig Sadel på Kvalitet", l="Saml 6 Ubesmittede Leopardpelse, og aflever dem til Ambersten-ranchen.", d="Vi gør os klar til at sende et hold væddere for at forstærke Alterac-ekspeditionen, men vi er løbet tør for materiale til at lave deres sadler.\n\nSaml pelse fra de største, vildeste leoparder mod øst, og bring dem til mig. Det er bidende koldt deroppe, og vores styrker fortjener intet mindre end de fineste pelse for at holde sig varme!"},
  [95213] = {n="Stjålet Sprængkrudt", l="Bring den Tomme Krudttønde til Stenbrudsmester Thesten ved Gol'Bolar-stenbruddet.", d="Tønden er stemplet:\n\nSPRÆNGKRUDT - FARE - MÅ IKKE HÅNDTERES - FARE - KUN TIL STENBRUDSMESTERENS BRUG - FARE\n\nDu får en synkende fornemmelse af, at troggerne ikke burde have den her. Det ville være bedst at rapportere dette til stenbruddet snarere end senere."},
  [95214] = {n="Stjålet Sprængkrudt", l="Gendan 16 Stjålet Sprængkrudt fra troggerne øst for Gol'Bolar-stenbruddet, og vend derefter tilbage til Stenbrudsmester Thesten.", d="Denne tønde indeholdt krudt nok til at gøre Kong Magnis tronsal til en åben gårdhave. Vi må få det tilbage fra troggerne, før de finder ud af, hvordan de kan antænde det."},
  [95216] = {n="Den Nye Pest", l="Saml den Yderst Giftige Stamme fra Visnetand i Ruinerne af Herrelande for Theodore Klo i Undergrunden.", d="Velkommen til Undergrundens vigtigste organ: Apotekerium! Her eksperimenterer vi på de mest virulente af Azerots eksotiske eksemplarer.\n\nDu har fanget mig i godt humør, så jeg lader dig være med i min seneste undersøgelse. Det ser ud til, at der lurer en særligt giftig leddyr i ruinerne over vores skønne by. Dens gifte siges at æde sig gennem selv udødt kød. Hvor er det spændende!\n\nJeg ønsker at bekræfte disse påstande. Skulle du visne bort efter et bid, vil jeg gerne have en prøve."},
  [95250] = {n="Afskyelige Skabninger", l="Saml Baronens Hoved i Ruinerne af Herrelande og bring det tilbage til Kaptajn Truman.", d="Hvad vil du, <Race>? Kan du ikke se, at der er en krig at vinde?\n\nMin herre har allerede kastet sig ud i kampen og har befalet mig at holde min post. Det er dog længe siden.\n\nJeg tvivler på, at du overlever ti minutter i kamp, men hvis det holder dit simple sind travlt, så hvorfor ikke søge Storemarskalen op? Han er den højeste, mest statelige helt, du nogensinde har set. Du vil kende ham, når du ser ham."},
  [95314] = {n="Den Der Grønne Skyggedal-eliksir", l="Saml 8 Flasker Hviskende Eliksir fra Skyggedalen, og vend derefter tilbage til Carolai Anis i Brill.", d="Før Svøben-invasionen var den tilbagetrukne landsby Skyggedalen kendt for sin Hviskende Eliksir. Den blev destilleret af urter, der kun findes i Tyrs Fald, og eliksiren var eftertragtet af apotekere, mystikere og giftblandere – selv efter at den var blevet forbudt i byen.\n\nJeg har fået henvendelser fra en række købere, der er ivrige efter at få fat i noget eliksir. Rejs til ruinerne af Skyggedalen dybt i Hviskeskoven mod vest. Jeg er klar til at tilbyde en betydelig kompensation, hvis du kan skaffe nogle flasker til mig."},
  [95328] = {n="Hviskende Rædsels Rester", l="Lever Hviskende Rædsels Rester til Fader Lankester i Krigskvarteret i Undergrunden.", d="Imod din bedre dømmekraft skraber du de krybende rester af uhyret sammen. Nogen i Undergrunden kan måske have brug for dem."},
  [95349] = {n="Jordringen", l="Tag Himmelskærer-skibet fra Vindras-øen til Mulgorr og tal med Alaana Stormvandrer, når du ankommer.", d="De seneste hændelser med kulten har forsinket mine planer om at rejse til Azeroth, og jeg må blive her i Valanår en tid. I stedet bliver du og en håndfuld andre Vindformer vores forhånd. Alaana Stormvandrer vil vente på at modtage vores Vindformer, når de ankommer til Mulgorr, og jeg vil opfordre dig til at udforske Azeroth, mens vi afslutter vores forretninger her. Vi slutter snart til dig.\n\nNår du er klar, så gå hen til havnen lige uden for dette logi og gå om bord på himmelskærer-skibet der.\n\nVindhilsen, <Name>."},
  [95350] = {n="Velkommen til Azerot", l="Rejs til Orgrimmar og tal med Trael i Visdommens Dal.", d="Det er en stor verden herned, og vores nye allierede er nøglen til vores overlevelse.\n\nJordringen er medlem af \"Horden\", en stolt samling af ligesindede folkeslag. Den nærliggende by Tordenklippe er en del af Horden, og længere mod øst ligger hovedstaden Orgrimmar.\n\nSøg flyvemesteren i midten af Tordenklippe. De flyver dig til Orgrimmar, hvor du vil få kontakt med Horde-krigshøvdingen – Trael, på vegne af Vindformerne. Må vinden lede dig, <Name>."},
  [95494] = {n="Såret Stolthed og Løveskind", l="Saml 6 Savannah-løveskind fra Savannah-matriarkerne og Savannah-patriarkerne i Ødemarken.", d="Jeg har brug for en med en stærk sværdarm og lidt ekstra tid, til at hjælpe mig med at samle nogle løveskind. Det stikker i min stolthed at bede en fremmed om hjælp, men jeg fik for nylig en skade i benet. Indtil jeg er helbredt, er jeg ikke i form til at gå på jagt selv, men jeg har forpligtelser, jeg må holde.\n\nDe største i området har generelt de bedste skind, så start med dem først."},
  [95507] = {n="Skævs Vildt", l="Saml 8 Fangede Vildt fra fælder, der findes i Sprungne Fælder i Ødemarken.", d="Mens du er derude, ville det være til stor hjælp for mig, hvis du kunne tjekke mine fælder. Jeg har spredt dem ud over hele dalen.\n\nBring alt småvildt tilbage, som jeg har fanget. Hold dog øje med det andet dyreliv. Dette område kan være farligt, hvis du ikke er opmærksom."},
  [95621] = {n="Problemer i Dalen", l="Rejs til det vragede karavaneri og find ud af, hvorfor Kul Tiraskerne er her.", d="I morges så jeg en gruppe mennesker lede efter noget i dalen nedenfor. Jeg fik brugt mit geværs sigte til at kigge bedre, og det var tydeligt, at det var soldater i Kul Tirasks livré.\n\nHvis du vil tage et job fra mig, så rejs derhen, hvor disse soldater slog lejr nær det vragede karavaneri mod syd. Dræb dem, du finder, og prøv at finde ud af, hvorfor de er her."},
  [95646] = {n="Rædsler i Højlandet", l="Dræb en Højlands-rædsel i Udgravningsstederne og bring dens rodkerne til Rethiel Grønvogteren i Vådlandene.", d="Disse brakke vådlande rummer en større kilde til usaltet sydligt vand. Det smerter mig, men i mine rødder fornemmer jeg en korruption, der sive ind gennem den bjergkløft.\n\nSkabningerne, ligesom dem i vores lavland, reagerer mere bittert på forureningen. Uden havets hærdende salt siden livets gry har de ringe styrke mod sådan ondskab.\n\nGå op i højlandet og bring mig Højlands-rædslens rodkerne."},
  [95647] = {n="Forvildet i Krattet", l="Find Ardin Græsmand i Udgravningsstederne.", d="Min mand, Ardin, har en sjælden evne til at fornemme naturen. Han klatrer op på enhver top for at samle de urter og blomster, jeg har brug for til min alkymi, så vores hylder og spisekammer altid er fyldt op.\n\nMen jeg frygter, at han er havnet i problemer. Et udgravningshold gik forbi for at søge forsyninger. De talte blandt andet om høje græsser, ulig noget de nogensinde havde set. Det var dem, han fortalte mig, han måtte gå og se med egne øjne. Han har været væk alt for længe!\n\nHvis du får noget at vide om ham, ville jeg være taknemmelig."},
  [95663] = {n="Dragemave-rygter", l="Rejs til Vådlandene og mød Dødsstalker-agenten i bakkerne over Dragemave-lejren.", d="Dragemave er en formidabel klan.\n\nDe er kendt for bindingsmagi stærk nok til at få drager til at tjene, og rygtet siger, at de forbereder en form for opvisning af den i Vådlandene. Om det er sandhed eller pral, kan Dødsstalkere ikke handle på halvfærdige hvisken. Knækkede symboler bar kun så meget til mig.\n\nEn dødsstalker-agent har brug for en hjælpende hånd i bakkerne over Dragemave-lejren. Mød hende der. Hun vil afsløre de næste skridt."},
  [95664] = {n="Ældrenes Viden", l="Tag Titan-relikken til Ældrehøjen i Tordenklippe og led efter nogen, der kan fortælle dig mere om den.", d="Denne usædvanlige sammensatte skærv spreder lys som et levende prisme. Dens natur er usikker, men dens kraft føles gammel. De kyndigste hjerner til artefakter fra denne forgangne tidsalder må holde til på Ældrehøjen i Tordenklippe."},
  [95682] = {n="Åbn Gabet", l="Slå Dragemave-styrkerne i Udgravningsstedet ned og vend tilbage til Dødsstalker-agenten udenfor med alt, du finder.", d="Dragemave. <Hun udstøder et tørt, morsomt fnys.>\n\nResterne af den dragetæmmende klan tror, de har fundet noget, der kan føre dem til at rejse sig til deres tidligere magt. I hvis øjne... deres falske krigshøvding?\n\nRyd deres broget samlede klan ud i Udgravningsstederne, så vores Dødsstalkere kan rykke ind uopdaget.\n\nHvis Dragemave bærer noget af værdi på sig, så bring det til mig – denne information skal forblive mellem os og vores kongelige kommando."},
  [95697] = {n="Skiftende Smag", l="Gå ind i Udgravningsstederne i Vådlandene og bring Krat-raptorkød tilbage.", d="Sjamja fortæller mig, at vi har brug for mere hjemmelavet madlavning.\r\nHvis vi begynder at sælge raptor, tror hun, at det vil lokke kunder, der ikke normalt besøger Brændstans Bålsted.\n\nHendes idé er ikke så ringe. Men jeg vil have noget, der hæver sig over lugtene fra vores fødselslandsbyer. Vi er i Orgrimmar! Brændstan bør servere en storslået udgave af deres velkendte favoritter.\n\nEn jæger kom for nylig tilbage fra Vådlandene med en gigantisk klo fra krat-raptorerne i Udgravningsstederne.\n\nEr du klar til et job?"},
  [95737] = {n="På Jagt efter Caitlin", l="Tal med Caitlin Græsmand i Menetil-havnen.", d="Fra tid til anden korresponderer jeg med andre i mit håndværk – urtekyndige eller særlinge, der studerer sjældne planter og lokale særheder. Vi bytter opdagelser og til tider advarsler om, hvad der ligger forude.\n\nEn alkymist i Vådlandene skrev om et udgravningshold, hendes mand var en del af, som afdækkede tegn på en længe tabt urtidsgræs... men hun sendte aldrig besked om, hvor rigeligt eller tilgængeligt det var.\n\nHvis du kan, så tjek til Caitlin Græsmand i Menetil-havnen."},
  [95772] = {n="Sangklinge-eftersøgningen", l="Led efter Dorin Sangklinges bror, Dæwyn, i Whelgars udgravningssted.", d="Min bror prøvede at slæbe mig med ud til Vådlandene sammen med et gravehold fra Modansøen. Sagde, de skulle ind i nogle bakker, ingen dværg nogensinde har sat fod i, for en eller anden slags udgravning.\n\nJo, jeg havde taget med, hvis jeg ikke allerede var bagud med denne bunke bæltespænder, jeg skal reparere.\n\nDæwyn plejer dog at skrive, når han er taget af sted. Jeg har ikke hørt en lyd, og det giver mig en mærkelig fornemmelse denne gang.\n\nHvis du marcherer den vej, kan du så gide at tjekke ind på min bror?"},
  [95774] = {n="Hendes Navn Er Olgra", l="Dræb piggrisene og saml 4 af Olgras Pynt til Mankriks mindesmærke.", d="Healeren, der reddede mig, kunne ikke redde hende, og hun er død i kamp. Hendes navn er Olgra, og jeg vil aldrig glemme hende.\n\nFandt du ikke hendes pynt på hendes krop? Hun bar mange juveler af poleret ben.\n\nDræb Barbermanke-plyndrerne nær det sted, hvor hun faldt, og find hendes dyrebare kunstværker!\n\nJeg vil placere dem ved mindesmærket, som jeg bygger til hendes minde."},
  [95795] = {n="Faldet i Kæret", l="Vend tilbage til Dorin Sangklinge.", d="<Du dækker dværgens krop med hans kappe.>\n\nRejs til Søshire og informer Dorin Sangklinge personligt om, hvad der blev af hans bror i Udgravningsstederne."},
  [95803] = {n="Et Tegn på God Tro", l="Bring Rudolph Gelhårdts hoved til Silvanas Vindløber i Undergrunden.", d="Nu hvor vi har taget hovedet af den plettede kommandant, skal jeg have dig til at levere det til Undergrunden. Silvanas Vindløber mistror os meget og nedgør os næsten åbenlyst.\n\nLever Rudolph Gelhårdts hoved til Den Mørke Dame. Vis hende, at vi tager os af vores eget hus og er hengivne til de forladtes velstand."},
  [95809] = {n="Hjertevævet", l="Vend tilbage til Caitlin Græsmand i Menetil-havnen.", d="Jeg har brug for et øjebliks hvil, før jeg finder min egen vej ud.\n\n<Han trækker nogle siv op af sin pakke og flætter og bøjer dem hurtigt til et hjerte.>\n\nTag det her og bring det til Caitlin. Lad hende vide, at jeg snart er hjemme! Nu hvor vi har en rydning takket være dig, samler jeg mine bundter og følger din sti.\n\nTak."},
  [95810] = {n="Bæring af Den Tabte Relikvie", l="Bring Titan-relikken til Prospektor Whelgar i Vådlandenes udgravningssted.", d="Du samler et brækket stykke af den stenmekaniske automat op. Det har en tekstur, ulig noget, du nogensinde har rørt, et sammensat materiale af ukendt sammensætning. Det er helt sikkert mere 'apparat' end 'affald'.\n\nProspektor Whelgar selv ved sit udgravningssted har måske noget nyttigt at dele om relikvien."},
  [95883] = {n="Den Pinte Sjæl", l="Saml en Pint Sjæl fra de nærliggende udøde i Berens Fare i Sølvfyrreskoven.", d="<Forberedelserne til et hastigt samlet ritual er uceremonielt lagt frem på alteret. Ifølge papirlappen er alt blevet samlet. Det eneste, der mangler, er blodofferet og den Pinte Sjæl.\n\nDe udøde omkring dig ser pinte nok ud. De har måske, hvad du søger.>"},
  [95884] = {n="Offerstenen", l="Find Offerstenen i Berens Fare i Sølvfyrreskoven.", d="<Papirlappen er for det meste ulæselig. Det, der stadig kan læses, er dog noter om forberedelser til et offer.\n\nEn offersten nævnes, ligesom et ritual.\n\nMåske kan du finde denne offersten i nærheden.>"},
  [95885] = {n="Blodofferet", l="Brug den Pinte Sjæl til at give et blodoffer ved Offerstenen i Berens Fare.", d="<Alt, der er tilbage nu, er blodofferet.\n\nPapirlappen nævnte et 'villigt offer'.\n\nEn intens følelse af frygt skyller over dig.>"},
  [95981] = {n="Holder øje med vejene", l="Dræb 8 Dalarn-troldmænd og 8 Dalarn-vagter for Skyggepræst Allister i Gravkammeret.", d="At tage deres vedhæng fra dem er kun første skridt. Hvis Kirin Tårn virkelig sender et jævnt flow af relikvier fra Dalarn, må vi stoppe dem ved kilden.\n\nSøg vejene omkring Ambermølle efter Dalarns troldmænd og vagter. Deres tilstedeværelse har givet fri adgang over vores grænser i alt for lang tid. Hvis vi kan tynde deres rækker ud, burde det stoppe disse vedhæng i at nå Sølvfyrreskoven overhovedet."},
  [95998] = {n="Det Store Udendørsliv", l="Sæt dig nær Sams Simple Lejrbål og vent, til du modtager Forstærket Hvile-buffen.", d="Hej med dig, <Class>. Jeg kan se, du har en eventyrers udtryk over dig. Godt for dig. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDet er en stor, vid verden derude, og du må lære at trives i det vilde for at lykkes. Ikke sikker på, hvordan dine udendørsfærdigheder står, men jeg regner med, at jeg kan lære dig et par ting, hvis du er villig til at lære.\n\nSæt dig ved bålet og gør dig hyggelig. Jeg viser dig det hele."},
  [95999] = {n="EFTERLYST: Forbrænder Gar'im", l="Lever Forbrænder Gar'ims knækkede stav til Dommer Salomon i Søshire.", d="Efterlyst! Forbrænder Gar'im, leder af et orkisk indfald i Rendas Dal. Angiveligt i samarbejde med Sortklippe-folket fra Stenvagtsfæstningen.\n\nVær på vagt over for Forbrænder Gar'im. Han og hans Sortklippe-skyggekastere er yderst farlige. En flot dusør vil blive givet til enhver modig sjæl, der kan levere bevis for Forbrænder Gar'ims død til Dommer Salomon."},
  [96031] = {n="Camping 101: Læderarbejde", l="Tal med Gretta Fintspinder i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Du er blevet læderarbejder. Godt for dig, <Class>. Jeg regner med at kende en, der kan lære dig at lave et telt, der holder dig kølig på varme dage og tørt på regnfulde dage.\n\nMed et godt telt over hovedet sikrer du, at du får al den hvile, du behøver, for at holde skarp på dine rejser."},
  [96045] = {n="Camping 101: Alkymi", l="Tal med Vosur Brækthel i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Nu hvor du har kastet dig over alkymi, kan jeg også lære dig at fremstille en Manabrønd til din lejr, når du har lært lidt mere. Byg en af disse, og alle healere og tryllekunstnere vil komme løbende for at få en forfriskende smag."},
  [96046] = {n="Camping 101: Minedrift", l="Tal med Yarr Hammersten i Kharanøs for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Minedrift er ikke det mest glamourøse, men det er godt, ærligt arbejde og et fint erhverv for dig at udforske.\n\nJeg regner med at kende en, der kan lære dig at fremstille en Magnetsten til din lejr. Byg en af disse, og alle, der har lyst til at svinge et sværd, vil ivrigt samle sig om dit bål og suge den ekstra \"pif\" til sig, den kan give til at øge deres kampdygtighed."},
  [96047] = {n="Camping 101: Førstehjælp", l="Tal med Thamner Pol i Kharanøs for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Så du har kastet dig over førstehjælp? Det er en hæderlig... og pragmatisk beskæftigelse som <Class>.\n\nJeg regner med at kende en, der kan lære dig at fremstille en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og at tilbyde noget tiltrængt healing i din lejr kunne endda redde liv."},
  [96050] = {n="Camping 101: Fiskeri", l="Tal med Paxton Ganter nær Isstrøm-søen i Dun Frostbakke for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme til nytte i lejren.\n\nJeg regner med at kende en, der kan lære dig at fremstille en Fiskeskål til din lejr. Du kan bruge dette inventar til at skabe lidt glæde for dig selv og dine medeventyrere. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [96055] = {n="Camping 101: Urtekundskab", l="Tal med Reyna Stenkvist i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Det ser ud til, at du har fået noget færdighed i urtekundskab. At plukke blomster er ikke kun til dovenskab, ved du. Det kan være nyttigt... og rentabelt.\n\nJeg regner med at kende en, der kan lære dig at fremstille et Røgelseslys til din lejr. Høj ånd er en nøglekomponent i at holde healere og tryllekunstnere i kampen, og et Røgelseslys kan give et boost, som magibrugere helt sikkert vil sætte pris på."},
  [96056] = {n="Camping 101: Flåning", l="Tal med Balthus Stenflåer i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="At kunne dygtigt høste skind og hud fra faldne bæster er en af de mere værdifulde færdigheder, en eventyrer kan besidde.\n\nJeg regner med at kende en, der kan lære dig at fremstille en Lejrstol til din lejr. Nogle gange er det vigtigt bare at tage en byrde af, og du kan bruge nogle af de skind, du har samlet, til at lave en hyggelig stol at sidde i. Lidt afslapning kan hjælpe med at sikre, at du er i topform og kan slå til, hvor det tæller, næste gang du finder dig selv i et tumult."},
  [96057] = {n="Camping 101: Skrædderi", l="Tal med Uthrar Trådsen i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Skrædderi er et overraskende stærkt håndværk at investere i, og jeg er sikker på, at det vil gavne dig godt.\n\nJeg kender en, der kan lære dig at fremstille et Fraktionsbanner til din lejr, forudsat at du har færdigheden til det. Inspiration og moral er en nøgledel af succes på ethvert slagmark, og et inspirerende banner kan gøre meget for at holde dig energisk."},
  [96059] = {n="Camping 101: Fortryllelse", l="Tal med Thonys Søjlesten i Jernsmede for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Nu hvor du er begyndt din rejse som fortryller, regner jeg med, at jeg kan lære dig at fremstille en Fortryllet Lut til din lejr, når du har lært det grundlæggende.\n\nDet er så vigtigt at finde underholdning i din fritid, og denne lille smule magi kan hjælpe med at sikre, at du er klar til at trodse alle slags udfordringer, når du igen rammer den gamle, støvede sti."},
  [96101] = {n="Det Store Udendørsliv", l="Sæt dig nær Raans Simple Lejrbål og vent, til du modtager Forstærket Hvile-buffen.", d="Hilsen, <Class>. Jeg kan se, du har en eventyrers udtryk over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu må lære at trives i det vilde for at lykkes i dette arbejde. Ikke sikker på, hvordan dine udendørsfærdigheder står, men jeg kan nok lære dig et par ting, hvis du er villig til at lære.\n\nSæt dig ved bålet og gør dig komfortabel. Jeg viser dig det hele."},
  [96102] = {n="Camping 101: Skrædderi", l="Tal med Snang i Orgrimgrad for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist din færdighed.", d="Skrædderi er et overraskende stærkt håndværk at investere i, og jeg er sikker på, at det vil gavne dig godt.\n\nJeg kender en, der kan lære dig at fremstille et Fraktionsbanner til din lejr, forudsat at du har færdigheden til det. Inspiration og moral er en nøgledel af succes på ethvert slagmark, og et inspirerende banner kan gøre meget for at holde dig energisk."},
  [96135] = {n="Hør Mit Kald", l="Brug de forvredne totemer til at sætte en stopper for piggrisenes ritual.", d="Puha, bare det at være rundt om disse forbandede totemer giver mig gysen - men det er godt. Denne mængde forvredet korruption er præcis, hvad vi har brug for, for at kalde barbermanke-piggrisenes elementarer frem.\n\nGå til Tusindnåle og find et passende sted til dine forsvarsværker. Dampbassinerne bør fungere. De er rige på ild, jord, vand og luft, alle sammen. Placer disse totemer og vær klar til kamp. Barbermanke vil ikke tage for venligt imod din indblanding."},
  [96137] = {n="Iras Dolk", l="Besejr 10 Unge Sorte Hærgere og 7 Sorte Hærgere, og vend så tilbage til Sirra Von'Indig i Mørkeshire for mere information.", d="En lille dolk, der tilhørte den selvudnævnte jægerinde Ira, som holdt skovene sikre ved at forhindre bæsterne i dem i at angribe rejsende.\n\nMed Iras ånd stadig vandrende i skovene, var hendes ufærdige forretning måske at rydde de ulvelignende vargs, der fortsat tager ofre i hele skoven."},
  [96138] = {n="Merricks Bue", l="Besejr 8 Splinterknytnæve-krigere og 4 Splinterknytnæve-opgaveledere, og vend så tilbage til Sirra Von'Indig i Mørkeshire for mere information.", d="En bue efterladt af Merrick Tapper, den berømte vagt, der var stolt af at holde vejene sikre mod fremrykkende fjender.\n\nMed Merricks ånd stadig vandrende på vejene, var hans ufærdige forretning måske at rydde indtrængere ud nær hans hjem i Ravnehøj. Ogrerne syd for byen kan være det, der plager hans ånd."},
  [96139] = {n="Tapper-familien", l="Søg i Ravnehøj efter noget interessant, og vend tilbage til Sirra Von'Indig i Mørkeshire.", d="I mørke tider som disse er det vigtigt, at vi husker vores helte lige så meget som vores fjender. Mørkeshire ville ikke stå endnu, hvis det ikke var for modet hos folk som den gode Frue Althea eller dem, der mistede livet i Ravnehøj.\n\nHar du læst meget om Ravnehøj? Nej, selvfølgelig ikke. Dens historie blev udslettet sammen med dens folk. Mit bibliotek, så imponerende det end er, har kun lidt om emnet.\n\nHvis du tilfældigvis finder noget, vil jeg sætte pris på, hvis du bringer det hertil. De folk fortjener at blive husket."},
  [96222] = {n="Khanen Hratha", l="Bring Plyndrer-nøglefragmentet til Umarak i Desolace.", d="Mens krig hærger i regionen, står Plyndrer-kentaurerne ubestridt i Spydenes Dal. Jeg er bekymret for, at de med tiden vil blive hårdhjertede og vække yderligere uro, hvis de andre klaner fortsat lukker øjnene for deres tilstedeværelse.\n\nKhanen Hratha besidder et Plyndrer-nøglefragment, og jeg ønsker at have det som en forhandlingstaktik. Find et krigshornsmundstykke hos kentaurerne dér og brug det til at udfordre ham på den højeste top.\n\nBring nøglen til mig, så har jeg et forslag til dig."},
  [96241] = {n="Snak om gift, mon", l="Brug Giftudsugeren til at samle 5 Mørkerejsning-giftprøver fra de gnavede kroppe i Mørkerejsning.", d="Der sker noget sjovt derovre i Mørkerejsning. Ol' Mazu'kon har hørt alt om de nye, grimme bæster, der sitrer rundt omkring dér.\n\nNogle siger, at de krybende små kryb har et gift med nogle unikke egenskaber, og det gør mig nysgerrig. Tag min udsuger. Brug den på de døde kroppe, der ligger rundt omkring, for at høste giften. Gør du det, står jeg i gæld til dig, mon."},
  [96243] = {n="Jordens Kald", l="Find Teo Hammerdyn i Dun Frostbakke.", d="Det er på tide, at du lytter til jorden, modige shaman. Elementerne prikker allerede i din hud, men når du taler med stenen, vil selve jorden stå fast under dine såler - og i din sjæl.\n\nSøg Teo Hammerdyn i Kuldekam-dalen. Du finder ham inde i Ambolmar, en fæstning smedet af hammer, ild og vilje."},
  [96259] = {n="Forsvar de døde", l="Dræb 10 Mørkerejsning-yngel og 5 Mørkerejsning-soldater.", d="Der er en gammel taurenbegravelsesplads på stedet kaldet Mørkerejsning, lige nordvest for denne lejr. For nylig er den blevet hjemsøgt af en særligt ondskabsfuld yngel af edderkopper. Disse edderkopper udgør ikke kun en trussel mod folket i Mulgorr, de beskadiger også et sted, som de fleste tauren anser for helligt.\n\nDet ville være en stor tjeneste, hvis du kunne rejse til Mørkerejsning og gøre ende på denne plage. Forfædrene vil helt sikkert smile til dig, hvis du ser det gennemført."},
  [96260] = {n="Stærkere end stål", l="Saml 3 tråde Krystalsilke fra Mørkerejsning-spindere.", d="Har du hørt, hvad der overgik begravelsespladsen i Mørkerejsning? Gigantiske edderkopper - rygtes at have et gift så stærkt, at det kan vække de døde - har spredt sig som en steppebrand. Grimt forretning, hvis du spørger mig.\n\nEn af spejderne, der blev sendt ud for at undersøge, vendte tilbage halvt død og dækket af en utrolig modstandsdygtig, krystallinsk edderkoppesilke. Jeg høstede, hvad jeg kunne, men jeg ville sætte stor pris på flere prøver af denne silke til yderligere studier.\n\nBring mig mere af denne krystallinske silke, så belønner jeg dig."},
  [96261] = {n="Yngelmoderen", l="Dræb Yngelmoder Valraxx i Mørkerejsning.", d="Som ofte er tilfældet med angreb som det, vi står over for i Mørkerejsning, fører en enkelt kraftfuld matriark ofte til hurtig spredning af en fjendtlig edderkoppebestand.\n\nHvis vi vil drive disse bæster væk for altid, må vi finde ophavsmoderen og gøre ende på hende. Når du går til Mørkerejsning, skal du opsøge yngelmoderen dér og ødelægge hende. Jeg vil råde dig til at tage allierede med dig og være klar til alt. Disse ser ikke ud til at være almindelige edderkopper."},
  [96264] = {n="Elementær hjælp", l="Besejr Charlga Rasorflanke i Tornekrattet og indsaml information om piggrisenes planer.", d="Så du er en stor shaman nu, hva'? Du har mestret elementerne og vil sætte dem til god brug? Jeg tror, jeg har lige det, du søger.\n\nHvis du vil have elementernes respekt, må du betale din gæld til dem. De hjælper dig, og du hjælper dem. Og lige nu har de brug for al den hjælp, de kan få fra dem, der ville misbruge deres magt.\n\nJorden rumler, <Name>. Den taler om, at barbermanke-piggrisene samler sig til et ritual med forfærdelig magt. Vi må undersøge deres kraul og se, hvad de har gang i. Bring mig tilbage, hvad du finder.", c="Bring den forrevne seddel til Veyric Tordenhame i Arathi-højlandet."},
  [96294] = {n="En Mørkere Sandhed", l="Bær det brev, du hentede fra Yngelmoder Valraxx, hen til Muln Jordvrede på Himmelvagtens Plateau.", d="<Yngelmoderen, du lige har dræbt, er slet ingen edderkop, men en natteelv-druide, der har antaget en snoet dyreform. En masse spørgsmål flyder gennem dit hoved om spindlernes natur--og formål--i Mørkerejsning.\n\nDu bemærker et brev, der titter frem fra den døde elvers kappe. Måske kan dette dokument besvare nogle af de spørgsmål, der fylder dit hoved.>"},
  [96390] = {n="Knæk Dem i Spiren", l="Dræb 10 Mørkejern-spioner i Dun Frostbakke.", d="Mørkejern-spioner har infiltreret Dun Frostbakke. Til hvilken ende, det kan jeg ikke helt sige, men det er et problem, vi må knække i spiren, før det får lov at vokse.\n\nTag østpå til Jernbånds Kompleks og dræb de Mørkejern-spioner, du finder der."},
  [96391] = {n="Underjordisk Kort", l="Lever Mørkejern-kortet til Jordseer Farsen i Dun Frostbakke.", d="<Kortet, du holder, ser ud til at vise et komplekst net af underjordiske tunneler og motorveje, der alle synes at mødes i et punkt lige under Jernsmede selv.\n\nDu kan ikke være sikker på, hvad runerne siger, for de er skrevet i det grimme, takkede runesprog fra Mørkejern-dværgene, men du kan gætte formålet med tunnelerne. Mens du læser kortet, skyller et vindstød over dig, og du kan svagt høre en dværgestemme, der bæres med den. Jordseer Farsen må se dette.>"},
  [96392] = {n="Farsens Vagt", l="Tal med Jordseer Farsen og bed ham om at låne dig sit langsyn, så du kan observere Mørkejern-truslen.", d="Hilsen til dig, ven. Mit navn er Jordseer Farsen, og jeg besøger Dun Frostbakke fra Ørnerede-toppen. Mens jeg rejste, kunne jeg ikke lade være med at bemærke, at vi har, tja... en lille smule et Mørkejern-dværge-problem.\n\nHar du et øjeblik, kan jeg vise dig, hvad jeg mener. Jeg har en smule magi, der burde klare tricket."},
  [96393] = {n="Indfaldet i Gamle Jernsmede", l="Gå ind i Thanernes Hal under Gamle Jernsmede og tag Durgen Klagehammers hoved.", d="Saml nogle allierede og tag ned i hulerne under Gamle Jernsmede. Gå ind i Thanernes Hal dér og tryk dig frem til de nederste hvælvinger.\n\nMit Mørkejern er lidt rustent, men jeg kan tyde et navn--en Durgen Klagehammer. Det er sandsynligvis ham, der er anfører. Tag hans hoved og lever det til Kong Magni Bronzeskæg.\n\nOg når du gør det, så fortæl ham, at hans gamle ven Farsen sender sine hilsner!"},
  [96394] = {n="De Rastløse Døde", l="Dræb 15 Rasende Genfærd, 10 Pinte Sjæle og læg Ambolmars ånd til hvile.", d="Noget har forstyrret gravene nede i Thanernes Hal, og der er hørt mærkelige lyde fra dybt inde i hvælvingerne. De dødes ånder er lette at vække, og det, der foregår dernede, synes at have skræmt dem.\n\nTag derned og se, hvad du kan gøre ved det for os. Hvis nogen af de døde er vågne--ja, så læg dem tilbage!"},
  [96395] = {n="Et Gammelt Nag", l="Læg Faldrim Ambolmars ånd til hvile og vend derefter tilbage til den Spøgelsesagtige Tjener i Thanernes Hal.", d="Thanen... min mægtige... Thanen... han... han skal... hvile.\n\nVær venlig... hjælp ham... hjælp ham... med at hvile...\n\nOpslugt... af... et gammelt... nag... Ingen... hvile..."},
  [96403] = {n="Vigtige Arvestykker", l="Saml 8 Dværgiske Arvestykker fra Thanernes Hal.", d="Dig dér, eventyrer... Jeg kunne virkelig bruge din hjælp.\n\nJeg var ude og sneg--øh... 'patruljerede' i hvælvingerne, da en styrke af Mørkejern-dværge kom op fra dybet i muldvarpemaskiner! Jeg ved ikke, hvad de vil her, men der er uvurderligt bytte dernede--øh, eller rettere... jeg mener, 'vigtige kulturelle arvestykker'! Saml alle sådanne relikvier, du ser, og bring dem hertil.\n\nJeg forsikrer dig om, at alt, du finder, vil blive katalogiseret og bragt tilbage til sin rette plads i ære."},
  [96408] = {n="En Gæst i Dun Frostbakke", l="Undersøg lejrpladsen med udsigt over Gol'Bolar-stenbruddet.", d="I går aftes så en af vores bjergbestigere et lejrbål på en skråning mod øst. Det ser ud til at ligge ret højt oppe med udsigt over Gol'Bolar-stenbruddet.\n\nDet er nok ingenting, men jeg vil gerne have, at du tjekker lejren. Hvis de er venlige, er der ingen skade sket. Hvis de ikke er venlige... ja, så ved du, hvad du skal gøre."},
  [96604] = {n="Det Store Udendørsliv", l="Sid ved Brakks Simple Lejrbål, og vent, indtil du får buffen Forstærket Hvile.", d="Lokk-tar, <Class>. Jeg kan se, du har en eventyrers look over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu skal lære at trives i vildmarken for at få succes i dette job. Jeg ved ikke, hvordan dine udendørsfærdigheder er, men jeg kan nok lære dig et par ting, hvis du har lyst til at lære.\n\nSæt dig ved bålet, og gør dig tilpas. Jeg guider dig igennem det."},
  [96605] = {n="Det Store Udendørsliv", l="Sid ved Kagas Simple Lejrbål, og vent, indtil du får buffen Forstærket Hvile.", d="Hilsen, <Class>. Jeg kan se, du har en eventyrers look over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu skal lære at trives i vildmarken for at få succes i dette job. Jeg ved ikke, hvordan dine udendørsfærdigheder er, men jeg kan nok lære dig et par ting, hvis du har lyst til at lære.\n\nSæt dig ved bålet, og gør dig tilpas. Jeg guider dig igennem det."},
  [96607] = {n="Det Store Udendørsliv", l="Sid ved Eleanors Simple Lejrbål, og vent, indtil du får buffen Forstærket Hvile.", d="Hilsen, <Class>. Jeg kan se, du har en eventyrers look over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu skal lære at trives i vildmarken for at få succes i dette job. Jeg ved ikke, hvordan dine udendørsfærdigheder er, men jeg kan nok lære dig et par ting, hvis du har lyst til at lære.\n\nSæt dig ved bålet, og gør dig tilpas. Jeg guider dig igennem det."},
  [96608] = {n="Det Store Udendørsliv", l="Sid ved Erics Simple Lejrbål, og vent, indtil du får buffen Forstærket Hvile.", d="Hilsen, <Class>. Jeg kan se, du har en eventyrers look over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu skal lære at trives i vildmarken for at få succes i dette job. Jeg ved ikke, hvordan dine udendørsfærdigheder er, men jeg kan nok lære dig et par ting, hvis du har lyst til at lære.\n\nSæt dig ved bålet, og gør dig tilpas. Jeg guider dig igennem det."},
  [96626] = {n="Camping 101: Madlavning", l="Tal med Tomas i Guldshire for at lære at blive kok.", d="Så du vil lære mere om camping, hva'? Godt for dig, <Class>. Det første, enhver eventyrer skal gøre, er at blive kok og lære at lave et lejrbål.\n\nMadlavning handler ikke kun om at lave lækre retter. Det er også fundamentet for din lejr."},
  [96627] = {n="Eventyreren", l="Tal med Sam Hyldebrus nær Guldshire.", d="<Name>, du har hidtil bevist din dygtighed som beskytter. Derfor betror jeg dig nu en usædvanlig opgave.\n\nJeg har hørt om en ny eventyrer nede ad vejen ved Guldshire. Gå hen og se, hvad han laver."},
  [96628] = {n="Eventyreren", l="Lever forsyningsbundtet til Eric Lysthammer nær Kharanøs.", d="Vent, <Name>. Jeg har en ting mere at bede dig om, før du tager den tunnel.\n\nMine bjergbestigere har meldt om en eventyrer, der er dukket op lige uden for Kharanøs. Kunne du levere disse forsyninger til ham?"},
  [96629] = {n="Camping 101: Madlavning", l="Tal med Gremlock Pilsnerø i Kharanøs for at lære at blive kok.", d="Så du vil lære mere om camping, hva'? Godt for dig, <Class>. Det første, enhver eventyrer skal gøre, er at blive kok og lære at lave et lejrbål.\n\nMadlavning handler ikke kun om at lave lækre retter. Det er også fundamentet for din lejr."},
  [96638] = {n="Eventyreren", l="Tal med Raan Vildvind nær Shen'dar-landsbyen.", d="Flere og flere eventyrere som dig selv har søgt ære og lykke uden for sikkerheden i Thendal-lunden. Der er én sådan eventyrer, der har slået lejr uden for Shen'dar-landsbyen, langs vejen, der fører sydvest ud af Thendal-lunden.\n\nSøg ham op og se, hvad du kan lære af ham, der kan hjælpe dig på dine egne rejser."},
  [96646] = {n="Camping 101: Madlavning", l="Tal med Zerril Blødbrise i Shen'dar-landsbyen for at lære at blive kok.", d="Så du vil lære mere om camping, hva'? Godt for dig, <Class>. Det første, enhver eventyrer skal gøre, er at blive kok og lære at lave et lejrbål.\n\nMadlavning handler ikke kun om at lave lækre retter. Det er også fundamentet for din lejr."},
  [96652] = {n="Eventyreren", l="Bring dagbogen til Brakk nær Barberbakken.", d="<Dagbogen virker ret almindelig og beskriver livet og eventyrene for en, du aldrig har hørt om.\n\nDer er flere poster, der nævner camping. Den ser ud til at være ret... sjov.>"},
  [96655] = {n="Camping 101: Madlavning", l="Tal med Kok Torka i Barberbakken for at lære at blive kok.", d="Så du vil lære mere om camping, hva'? Godt for dig, <Class>. Det første, enhver eventyrer skal gøre, er at blive kok og lære at lave et lejrbål.\n\nMadlavning handler ikke kun om at lave lækre retter. Det er også fundamentet for din lejr."},
  [96656] = {n="Eventyreren", l="Tal med Eleanor Stakkelton nær Gryde-by.", d="<Name>, du har hidtil vist dig pålidelig i dine bestræbelser mod Det Skarlagenrøde Korstog. Derfor betror jeg dig nu en usædvanlig opgave.\n\nJeg har hørt om en ny eventyrer nede ad vejen ved Gryde-by. Gå hen og se, hvad hun laver."},
  [96658] = {n="Camping 101: Madlavning", l="Tal med William Plukmand i Gryde-by for at lære at blive kok.", d="Så du vil lære mere om camping, hva'? Godt for dig, <Class>. Det første, enhver eventyrer skal gøre, er at blive kok og lære at lave et lejrbål.\n\nMadlavning handler ikke kun om at lave lækre retter. Det er også fundamentet for din lejr."},
  [96659] = {n="Eventyreren", l="Lever forsyningsbundtet til Kaga Vildhov nær Blodhov-landsbyen.", d="Vent, <Name>. Jeg har en ting mere at bede dig om, før du forlader os.\n\nDer er en eventyrer ved navn Kaga Vildhov, der har slået lejr lige uden for Blodhov-landsbyen. Hun har hjulpet mig meget i fortiden, og nu ser jeg min chance for at betale hende tilbage. Kunne du levere disse forsyninger til hende?"},
  [96774] = {n="Oldtidens Gurubashi-idol", l="Hent et Oldtidens Gurubashi-idol fra Den Druknede By.", d="De gamle Gurubashi i Kvælerdorn var dengang mestre i mørk blodmagi. Rygterne siger, de brugte idoler af rent sandsølv til at kanalisere det dér onde, onde voodoo.\n\nOl' Mazu'kon ville elske at få fat i en af de idoler... til videnskabelige formål, ser du. Hvad med at samle nogle venner og lave lidt smæk-og-grib på den druknede by, der stikker op af havet ud for Kvælerdorns kyst? Dræb den flotteste præst, du kan finde derinde, og de har helt sikkert det, jeg leder efter."},
  [96781] = {n="Hvad er den store idé?", l="Stjæl Bartøns Spejderrapport ved at lommetyve den fra ham. Bring derefter rapporten til Myrokos Tavskikkelse i Ravnehold-herregården.", d="Vi har bemærket en spejderstyrke fra Syndikatet, der sniger sig rundt om Alteracs ruiner, ledet af en mand ved navn Bartøn.\n\nDe leder helt klart efter noget, men jeg kan ikke vide hvad uden at læse deres spejderrapporter.\n\nJeg beder dig om at lommetyve rapporten fra ham i stedet for at dræbe ham på stedet. Bartøns død vil tippe Syndikatet om, at vi er dem på sporet, og de vil helt sikkert tage modforanstaltninger for at dække deres spor.\n\nHvis du håber at finde ham, er han højst sandsynligt blandt Syndikatet i Strahnbrad."},
  [96783] = {n="En Vej Ind", l="Stjæl en Syndikat-uniform fra Nordfold-herregården for at snige dig ind i Strømgård-fæstningen.", d="Strømgård-fæstningen er et af Syndikatets største højborge. Mange af organisationens vigtigste forretninger foregår bag dens mure.\n\nJeg har fået besked om en bestemt handel mellem medlemmer af Syndikatet et sted i Arathi-højlandet, og jeg er sikker på, at detaljerne om denne handel kan findes et sted i Strømgård.\n\nFor at snige dig ind i fæstningen uden at vække mistanke, skal du bruge en forklædning. Se om du kan finde en blandt Syndikatet udenfor fæstningen, i Nordfold-herregården."},
  [96800] = {n="Forfalden Gæld", l="Hent bogen Runemestrenes Tabte Magi fra Det Skarlagenrøde Kloster.", d="Hej dig, <Class>. Jeg har en sag, hvor jeg kunne bruge lidt hjælp.\n\nJeg skriver tilfældigvis en afhandling om de gamle Vildhammer-runemestre i Grimbatol, og der er en bestemt tome, jeg skal bruge for at fuldføre min forskning. Ifølge vores protokoller lånte en magiker ved navn Doan bogen fra det gamle Dalarn-bibliotek før Den Tredje Krig og afleverede den aldrig tilbage!\n\nArkanist Doan har nu gemt sig i Det Skarlagenrøde Kloster i Tirisfals Lysninger. Hent denne bog til mig, så bliver du rigeligt belønnet."},
  [96821] = {n="Benene på Nakken", l="Dræb 6 Ryggeskygge-krybler og 6 Ryggeskygge-lurere i det sydlige Durotar, og rapporter derefter til Gar'thok i Barberbakken.", d="Vi ser færre og færre rejsende fra Barberbakken i disse dage. Skorpiderne var aldrig særlig sjove, men nu hører jeg, at der er edderkopper, der bygger rede langs vejen.\n\nHvis dine rejser fører dig op mod nord, så dræb nogle af edderkopperne på vejen. Lad derefter Barberbakken vide, at stien er lidt tryggere for dem."},
  [96822] = {n="For Ære", l="Saml Plyndrerens Kampøkse, Plyndrerens Bue og Plyndrerens Skjold fra udkanten af Tiragarde-fæstningen, og returner dem derefter til Turroc i Barberbakken.", d="Vi mistede mange modige krigere fra Horden, da vi plyndrede Tiragarde-fæstningen. Nu hvor menneskerne har forstærket ruinerne, kan vi ikke hente deres levninger for at ære deres død ordentligt.\n\nGå til ruinerne omkring fæstningen, og led efter de våben, som vores faldne slægtninge har efterladt. Vi vil udstille dem på et æresfuldt sted."},
  [96825] = {n="Denne Frugt Kan Bide Igen", l="Kok Torka i Barberbakken vil have dig til at samle 8 Stikkende Kaktusfigen fra Barbermanke-områderne vest for byen.", d="Vores jægere og fiskere bringer masser af velsmagende mad tilbage til vores tropper - men det er sjældent, at de får en sød godbid.\n\nJeg har set en kaktus, der producerer en stikkende, lækker frugt. Men den vokser kun i bakkerne mod vest, hvor de elendige pindsvinetryner slår deres lejre. Find vej forbi pindsvinetrynerne og bring mig nogle af frugterne. Og vær forsigtig - frugterne er lige så tornede som pindsvinetrynerne!"},
  [96873] = {n="En Pine i Nakken", l="Pa'zula i Sen'jin-landsbyen vil have dig til at samle 3 Lysende Rest. Lysende Rest kan fås ved at afbetøve Forhekset Vedhæng, der falder fra trolde på Ekkoøerne.", d="Trollene øst herfra har mistet deres vilje til hekselægen Zalazan. Han bruger mange grusomme magier til at holde fast i sine fangers sind, men et af hans yndlingstricks er at få dem til at bære vedhæng viklet ind i onde bindingsbesværgelser.\n\nØv dine fortryllingsevner ved at fratage vedhængene deres magi, og bring mig resultatet. Og hæng ikke et af dem om halsen ved en fejl, hvis du sætter pris på din frihed!"},
  [96874] = {n="Det Her Er Rygradsøksen", l="Ug'thok i Orgrimgrad vil have dig til at samle 5 Forvitrede Rygsøjler fra udyr i Tordenryggen, sammen med 5 Grove Slibesten.", d="Har du set de enorme udyr i Tordenryggen? Jeg tænker hele tiden på, at ryggens pigge ville være perfekte til at lave hovedet på en mægtig økse. Saru grinede, da jeg fortalte ham det... men hvad ved han så!?\n\nSom en del af dine smedelektioner kan du hjælpe mig! Bring mig nogle af de pigge, sammen med slibesten til at skærpe dem."},
  [96875] = {n="Udyrene i Tordenryggen", l="Kamari i Orgrimgrad vil have dig til at samle 5 Grov Øgle-hud fra udyr i Tordenryggen, sammen med 2 Garvede Lette Huder.", d="Orgrimgrad udvider sig altid, <Class>. Og når arbejderne har brug for huder til at beklæde væggene og tagene på vores nye bygninger, kommer de til mig!\n\nHudene fra øglerne i Tordenryggen er typisk for tykke til rustninger, men de er fremragende byggemateriale. Bring mig nogle af deres huder, sammen med et par lettere garvede huder. Lad os se, hvor dygtig du er med læder!"},
  [96895] = {n="Sølvdæmringens Udsending", l="Find et medlem af Sølvdæmringen nær indgangen til Undergrunden.", d="Ved ikke, om du har hørt det, men to udsendinge fra Sølvdæmringen var lige forbi her. Jeg har ikke noget imod Sølvdæmringen, men jeg kan heller ikke lide, at de roder rundt i Tirisfal uden opsyn. Begge var De Forladte... men det gør mig ikke mindre nervøs.\n\nEn af dem gik lige forbi her på vej mod sydøst. Der er en flok Svøben-kultister, der sniger sig rundt i byens udkant i den retning. Hvis de to har hørt om dem, er der ingen tvivl om, at det ville have fanget deres opmærksomhed."},
  [96896] = {n="En Retfærdig Sag", l="Overvær samtalen mellem Danitha Mør og Leonid Barthalomæus den Ærede.", d="Danitha og jeg kæmpede mod Svøben for at forsvare Undergrunden, da Naxxramas angreb. Vi mistede mange gode venner den dag, heriblandt helten, som denne fæstning er opkaldt efter - Garek Bandarion.\n\nHan var måske den første De Forladte, der genopdagede, hvordan man bruger Lyset som paladin. Det glæder mig at se hans arv og potentiale leve videre her hos Danitha og hendes kammerater.\n\nHvis bare resten af De Forladte følte det samme..."},
  [96897] = {n="De Fordømtes Kult", l="Dræb 8 Mørke Neofyter og 8 Mørke Håndhævere i Tirisfals Lysninger.", d="Svøben er en pest over vores lande, og deres levende tjenere er det værste af det hele. Folket i Tirisfal har nok at slås med mellem de tankeløse døde og Det Skarlagenrøde Korstog. Hvis du vil gøre en god gerning, så hjælp mig med at gøre ende på dette pak."},
  [96898] = {n="Krigens Rester", l="Saml 12 Nekrotiske Krystalfragmenter i Tirisfals Lysninger.", d="Det er ikke længe siden, at citadellet Naxxramas væltede ned over denne by, fast besluttet på at udslette De Forladte fra kortet. Både De Forladte og Sølvdæmringen mistede meget den dag for at sikre De Forladtes fremtid.\n\nUnder slaget blev den store nekrotiske fokuskrystal, der sad på toppen af Naxxramas, knust, og dens fragmenter spredt over hele dette område. Jeg formoder, at det er derfor, kultisterne er her. Hjælp mig med at samle fragmenterne og berøve Svøben dem."},
  [96899] = {n="Bandarion-borgen", l="Mød Leonid Barthalomæus ved Bandarion-borgen i Tirisfal.", d="Du har gjort en stor gerning for Sølvdæmringens sag i dag, og jeg takker dig. Jeg ved ikke, hvor godt du kender borgen Bandarion, men min kommandør og jeg var på vej derhen for at mødes med paladinerne, der bor der. Det var før, vi erfarede tilstedeværelsen af De Fordømtes Kult.\n\nHvis du vil vide mere om Sølvdæmringen og vores mission, så søg min kommandør i Bandarion-borgen, nordvest herfra. Jeg bliver her og rydder op i resten af dette rod."},
  [96984] = {n="Forstyrrelsens Hjerte", l="Saml Arkan-partikler i Dalarn By for Magus Ordeen Tomglimt i Tarrenmølle.", d="Du har måske ikke vores bedste i tankerne, men jeg vil ikke afvise en ekstra hånd. Og hvis Dalarn falder, tager det alt med sig - inklusive din Undergrund.\n\nSå din velgører vil være med? Fint. Jeg vil fortrylle din nøgle, så den kan komme forbi mine værn, så du kan komme ind i byen. Når du er derinde, så mød mig i Den Violette Citadel, hvor det hele begyndte. Med alt det, der foregår, vil Kirin Tårn være for travlt optaget til at stoppe dig.\n\nSaml, hvad du vil, men uanset hvad sker, er vores første prioritet at forhindre en katastrofe."},
  [96986] = {n="Gravridderen", l="Besejr Atrexis Gravridderen i Dalarn By for Melisara i Tarrenmølle.", d="I magikerbyens underliv mod nord findes en forræder mod vores art. En nekromanter med urovækkende talent. Han rejser en hær af udød lige under Kirin Tårns næse.\n\nJeg bekymrer mig ikke om magikerbyens skæbne, <Name>, men denne gravridder spytter i ansigtet på alt, hvad vi De Forladte står for. Gør ende på ham. Vis ham, at ingen er uden for Den Mørke Dames rækkevidde."},
  [96987] = {n="Opportunistisk Uddannelse", l="Saml Dalarns Grundlæggelse fra Dalarn By for Rexxie Kobberklo ved kloakindgangen.", d="Nå, hvis det ikke er en ligesindet iværksætter. Sniger du dig ind i Dalarn under sådan nogle besværlige tider? Tsk tsk.\n\nMin slags <Race>!\n\nMens vores magikervenner her er optaget, kunne vi måske finde os nogle 'fejlplacerede' skatte. De har hele biblioteker dedikeret til fine arkane magier. Hvis du kan bringe mig en af deres hemmelige tomer, kan jeg sælge den for en pæn skilling. Vi deler overskuddet med dig.\n\nHej hej, se ikke sådan på mig. Du er jo heller ikke her på en udflugt selv. Vil du med eller hvad?"},
  [96988] = {n="Kildens Kraft", l="Saml 6 Revnede Vagtkerner i Dalarn By for Doktor Martin Felben i Undergrunden.", d="Med byen Dalarn belejret af deres egne konstruktioner er dette det perfekte tidspunkt til, lad os sige, at låne et par prøver.\n\nForestil dig en hær af arkanedrevne afskyeligheder. Den Mørke Dame ville ikke have noget valg andet end at anerkende min alkymiske ekspertise. Måske endda give mig ledelsen af Det Kongelige Apotekerselskab?\n\nGå til byen og find konstruktionernes kerner. De er usandsynlige at give dem frivilligt, så gør, hvad du må."},
  [97003] = {n="Chol'aruk Ådseleren", l="Bring Chol'aruks hoved til Gur'ak i Ødemarken.", d="Hej dig, <Class>. Jeg har brug for din hjælp. Der går rygter om et udyr, der har sit hule dybt inde i en grotte ved Tornehøj, nordøst herfra. Barbermanke kalder det Chol'aruk eller \"Ådseleren\". Det siges at være fem gange så stort som en almindelig pindsvinetryne med en tørst efter blod, der aldrig kan slukkes.\n\nDe fleste tror ikke på historierne. Men jeg gør - for jeg har kæmpet mod dets lige før.\n\nSøg dets hule og slå Chol'aruk ihjel. Bring mig dets hoved. Jeg advarer dig dog - forbered dig godt, og gå ikke alene.\n\nBlod og torden, <Class>."},
  [97005] = {n="Chol'aruk Ådseleren", l="Bring Chol'aruks Hoved til Bainham i Ødemarken.", d="Der går rygter om et kolossalt misfoster, der har sit hule i en grotte nordvest herfra, på plateauet kendt som Tornehøj. Barbermanke kalder det Chol'aruk eller \"Ådseleren\", og dem, der har set det, siger, at det er så enormt, at det kan sluge en ork hel.\n\nFå tror på sådanne historier, men jeg gør... for jeg har kæmpet mod et lignende væsen selv. Af respekt for dem, jeg har mistet til disse væsener, skal dette udyr dø.\n\nSaml stærke allierede og find Chol'aruks hule. Dræb afskyeligheden og bring mig dens hoved."},
  [97222] = {n="Portvagtens Varer", l="Bær Portvagtens Forsendelse op ad trappen i Trøsens butik og læg den udenfor døren.", d="Ja, det er kun en trappe, men hvis det er en så lille opgave, så burde det ikke være noget problem for dig at klare leveringen selv!\n\nTrøsens Ost er ikke en del af Portvagten eller deres lagerbeholdning, men vores bygninger deler en etage.\n\nLæg kassen udenfor deres lagerdør - vagten sender nogen efter en fast afhentning. De vil se pakken ankomme og bære den ind, når de vender tilbage til posten."},
  [97223] = {n="Blodklo-matriarken", l="Bring Æggene fra Blodklo-matriarken til Xar'Ti i Sen'jin-landsbyen.", d="Alle raptorerne, du ser her, er dem, jeg selv har trænet. De kommer fra hele Kalimdør, men nogle af de bedste kommer fra Blodklo-raptorerne på øerne ud for vores kyst.\n\nÉn raptor blandt dem, Blodklo-matriarken, er særlig brutal og har dræbt mange fra vores landsby og er blevet for farlig at lade være ved vores grænser. Hvis du kan slå hende ned, så kom tilbage med hendes æg, så vi kan opdrage kyllingerne som allierede i stedet for fjender."},
  [97225] = {n="Glemte Loa-idoler", l="Saml 8 Glemte Loa-idoler fra Ekkoøerne. Bring dem til Mester Gadrin i Sen'jin-landsbyen.", d="Da vi flygtede fra øerne, som Zalazan og hans slags nu beboer, efterlod vi mange dyrebare idoler, der hjælper os med at kommunikere med de ånder, vi tilbeder: vores loaer. De er af stor betydning for vores stamme.\n\nZalazans tilhængere viser ingen ærbødighed over for vores loaer og har spredt disse idoler ud over de største af øerne.\n\nDette er en handling, der ikke vil blive overset, hvis vi ikke kan samle disse idoler, og at krænke en loa er en alvorlig sag.\n\nGå, find så mange loa-idoler, du kan, og bring dem tilbage til mig."},
  [97242] = {n="Yelmaks Blanding", l="Tag nogle stiklinger af Dunhammer og Spydgræs, der vokser omkring vandløbene i Æresdalen, og returner til Kor'geld i Yelmaks Alkymi og Eliksirer.", d="Yelmak vil ikke have, at hans lærling ødelægger noget. Nåja, noget mere end han allerede har.\n\nHan fortalte mig, at den unge blander i træning har for meget stolthed til at bede om hjælp, når han virkelig har brug for det. Yelmak vil gerne give ham en smag af en bestemt hjemmebrygget opskrift.\n\nSaml en blanding af dunhammer- og spydgræs-stiklinger fra planterne, der vokser omkring vandet i Æresdalen. Jeg ville selv hente dem, men hvis jeg forlod butikken, ville Whuut helt sikkert vide, at vi er ude på at imødekomme hans humør."},
  [97243] = {n="Ildens Kald", l="Bring Fakklen fra den Hvilende Flamme til Olariaan Hurtigbrand ved Flammernes Helligdom i Gustbær-lavlandet.", d="Selvom vi er i skyvæggens rige, er dette stadig det elementære plan. Ånderne fra alle fire elementer taler til os, hvis vi gider at lytte. En af os Vindformere er især i harmoni med ildens element. En shen'dorei ved navn Olariaan Hurtigbrand.\n\nBring dette til ham ved Flammernes Helligdom i Gustbær-lavlandet. Du finder den gemt langs øens kant, vest for Valanår."},
  [97244] = {n="Ildens Kald", l="Dræb Himmelpræst Fladderiel i Gustbær-lavlandet og saml Fladderiels Hjerte.", d="Der er en Al'Aketh-himmelpræst ved navn Fladderiel. Han var engang en kalder af flammen og en standhaftig Vindformer. Ligesom så mange Al'Aketh pantsatte han sin loyalitet for magt, og hans hænder er nu plettet af blodet fra hans tidligere brødre og søstre.\n\nDu finder Himmelpræst Fladderiel på gården mod nordøst forbi Valanår, lige syd for Akirs Helligdom. Dræb forræderen. Bring mig hans hjerte. Det er en ulækker opgave, men det er nødvendigt for ritualet, vi skal udføre."},
  [97245] = {n="Ildens Kald", l="Find Kuramaas hjem i Shen'dar-højlandet, og besejr ånden i kamp. Bring Kuramaas Maske til Olariaan Hurtigbrand i Gustbær-lavlandet, når du har sejret.", d="Beboerne i Shen'dar-højlandet taler om en gammel skovånd ved navn Kuramaa. De siger, at den bor inde i en vridet stub på toppen af en bakke nær højlandets Ankerpylon.\n\nTag op i højlandet og find denne stub. Bank din knytnæve mod barken, så vil Kuramaa vise sig. Besejr ånden i kamp, og bring mig dens træmaske.\n\nVær dog advaret: Dette væsen vil være usædvanligt modstandsdygtigt over for meget af din magi. Kun ildens berøring kan fælde ånden."},
  [97246] = {n="Madappetit", l="Besøg Brændstans Bålsted og fortæl ham, at Tykmave vil have dig til personligt at levere Mumles frokost til ham.", d="Min søn, Mumle, tager altid af sted for at lege med sine venner hele dagen. Jeg siger til ham, at han skal hente en frokost hos Brændstan, men jeg ved, at han næsten aldrig gør det, for han kommer hjem sulten. Disse unger synes, deres lege er vigtigere end deres egne kroppe!\n\nVær sød at stoppe ved Brændstans Bålsted og fortæl ham, at du er der for at levere Mumles frokost. Du kan næsten helt sikkert finde Mumle bag Grommash-borgen sammen med resten af hans venner.\n\nPligterne holder mig her om dagen, og jeg kan ikke holde øje med hvert eneste måltid, han spiser."},
  [97249] = {n="Yndlingsmad", l="Bring Mumles Frokost til ham bag Grommash-borgen.", d="Nu hvor jeg ved, at hans forældre bekymrer sig om, hvor meget han faktisk fylder sin mave, har jeg en idé.\n\nDe fik mig til at love ikke at pakke det samme måltid hver dag, så Mumle lærer at sætte pris på mere end én ting. Men når røgeren er fuld, og vi laver sukkerglaserede svinemavesandwiches, dukker han altid op til frokost. Vi er begyndt at smuldre de resterende sprøde glaserede stykker over som topping--noget vi kan tilføje dagligt.\n\nTag det her med til ham. Måske begynder han at dukke op tidligt og tage venner med!"},
  [97250] = {n="Fejlagtigt Beskyldt, Retfærdigt Rettet", l="Dræb Alliance-soldaterne, der trænger ind i Ødemarken ved grænsen til Støvsumpen, og vend derefter tilbage til Grunt Tømmerstok i Taurajo-lejren.", d="Rejsende, har du planer om at tage mod Støvsumpen? Jeg har hørt hviskerier om, at nogle få menneskelige soldater har taget stilling ved grænsen og væltet de vartegn, vores tauren-pionerer efterlod.\n\nRygtet siger, at en yndet kro er brændt ned til grunden, og på typisk Alliance-manér har de straks skudt skylden over på Horden! Jeg kan ikke vide, om deres påstand har noget om sig, men deres indtrængen på VORES land må ikke stå.\n\nDræb først, undersøg bagefter!"},
  [97253] = {n="Dele og Stykker", l="Saml 5 Håndfulde Komplicerede Dele fra den øvre piratlejr syd for Skralleby, og vend derefter tilbage til Wrenix den Elendige i Skralleby.", d="Hej, har du et sekund?\n\nDet er sådan, at ingen, jeg har sendt for at tage hånd om det seneste piratproblem, er kommet levende tilbage. Efter fem eller seks forsøg tænkte jeg: \"Hvad hvis jeg sendte en maskine i stedet?\" Det viser sig, at skimitarer fungerer som skruetrækkere i en klemme, og før jeg kunne få den sendt hjem igen, var den allerede i stykker og spredt ud over deres lejr!\n\nJeg har brug for de dele tilbage, og da dette er en hurtig lille hentemission, vil jeg vædde på, at dine overlevelseschancer er MEGET højere end de andres. Hvad siger du?"},
  [97257] = {n="Ildens Kald", l="Vent på, at Olariaan begynder ritualet ved Offerbrasen og følg hans anvisninger.\n\nDu skal levere Den Evige Flamme til Valanår, før tiden løber ud.", d="Nu udfører vi ritualet.\n\nJeg vil placere materialerne på alteret og kalde ildens ånder frem. Hvis offeret accepteres, vil de vise sig og tænde Den Evige Flamme. Du skal så holde din fakkel frem og fange flammen.\n\nBær den tændte fakkel til Valanår og placer den i Den Evige Flammes Brasen. Det skal gøres hurtigt, for ildene fra Ildlandene forsvinder hurtigt her i Himmelmuren."},
  [97263] = {n="Din Pakke Er Ankommet", l="Lever Eldruns forlagte pakke.", d="<Flere forlagte pakker er efterladt ved postkassen. Du bemærker, at en af dem er mærket til levering fra Ørnerede-toppen, til Jernsmede, til Eldrun Stormbryder. Den er mærket \"hastende\".>"},
  [97265] = {n="Had til Hadfuror", l="Besejr en række Hadfuror-satyrer i Sargeron i Forødelse, og vend derefter tilbage til Aka'rei i Skyggebytte-landsbyen.", d="Har du nogensinde indgået en aftale med en satyr, mon?\n\nDet har jeg. Hvordan kunne jeg modstå? Løftet om magt, viden langt ud over hvad enhver almindelig bog kunne tilbyde... alt sammen ledsaget af en ivrig og karismatisk håndlanger. Hvad mere kunne jeg ønske mig?\n\nBah, selvfølgelig ville de aldrig bøje knæet for et dødeligt væsen. Jeg forhandlede, da jeg intet havde, kun for at blive kasseret med endnu mindre.\n\nNu vil jeg have hævn. Hævn over Hadfuror. Plyndr deres lejr mod nordøst! Plet jorden med deres ondskabsfulde blod."},
  [97277] = {n="Grumle og Gozvig", l="Find Grumles og Gozvigs lejr i bakkerne mod nordvest. Hent Gozvigs Mekanikerlog, og dræb Sneleopard-lureren.", d="Hov, jeg havde ryggen til, mens jeg gjorde klar til vildsvinestegen, da jeg hørte min kammerat Gozvig skrige for sit liv!\n\nSkarpe hugtænder og et glimt var alt, jeg så, da jeg vendte mig. Sådan nogle enorme poter! En sneleopard slæbte sit gnomiske bytte væk. Jeg greb min haglgevær og skød over bestien. Den slap ham og satte i løb.\n\nHeldigvis havde den ikke gjort mere end at give ol' Goz nogle dybe ridser.\n\nTag tilbage til lejren i bakkerne mod nordvest og hent Gozvigs Mekanikerlog. Dræb sneleoparden også, hvis du ser den!"},
  [97279] = {n="Vildfarne Våben", l="Saml 6 Forladte Træningsvåben, og vend derefter tilbage til Kzan Tornhugger i Hulen.", d="Med en tilstrømning af nye rekrutter som dig selv har det været svært at holde vores våben forsynet. Vores våbensmed, Kzan, løber tør for træningsvåben, og jeg vil gerne se, hvilke færdigheder du besidder, for at få en idé om, hvad jeg har at arbejde med. Heldigvis for dig har jeg en løsning på begge dele.\n\nMens du er derude og bider tænder over vildsvin, skal du finde seks forladte træningsvåben. Vores mislykkede rekrutter lod dem ligge på jorden. Når du har gjort det, skal du returnere dem til vores våbensmed Kzan bag mig i Hulen."},
  [97281] = {n="En Snigende Storm", l="Bring den Sløve Stormkugle til Rezlåk nær Drygulch-kløften.", d="<Foran dig ligger en mærkelig kugle med en mat overflade. Når du samler den op, synes en lille elektrisk strøm at vibrere indefra. Ved nærmere eftersyn ser det ud til, at en mørk tåge hvirvler inde i den, og fra tid til anden kan man se en lille elektrisk gnist.\n\nDet er klart, at harpyen brugte den til et eller andet formål. Måske ville Rezlåk være interesseret i dette objekt?>"},
  [97282] = {n="Stormende Potentiale", l="Bring 5 Ladede Tordenøgle-organer til Rezlåk nær Drygulch-kløften.", d="\"Rezlåk, når en mulighed banker på, så sørg for at være klar til at gribe den.\" Det er endnu en perle, Gazlowe lærte mig, og det er præcis, hvad jeg har tænkt mig at gøre.\n\nDenne kugle virker ikke beskadiget, den ser bare ud til at være løbet tør for strøm, men jeg har en idé om at lade den op til fuld styrke igen!\n\nDer er en masse tordenøgler i en kløft vest for her. De har organer, der indeholder en kraftig elektrisk ladning, som ville være perfekte til dette.\n\nTag derud og høst nogle og bring dem tilbage til mig!"},
  [97287] = {n="Snedige Forhandlinger", l="Tal med Billedet af Ærkemager Modera nær Dalarn.", d="Du har gjort det godt ved at infiltrere magikernes by, men jeg tror, det er tid til, at vi bliver mere... forhandlingsvillige.\n\nSå smertefuldt det er for mig at indrømme, findes der intet andet sted på Azerot med så stor viden om det arkane. Mit geniale arbejde blegner stadig i sammenligning med den gamle visdom, Kirin Tårn har samlet gennem årene. Jeg synes, det er højst på tide, vi får adgang til denne eksklusive orden, synes du ikke?\n\nTag partiklen, du skaffede dig. De vil helt sikkert give alt for at få den tilbage. Alt."},
  [97288] = {n="Uendelig Pine", l="Lever det Afskyelige Hoved til Mesterapoteker Faranell i Undergrunden.", d="<Da skabningen falder, vælter dens hoved af. Det ser ud til, at det har været genfastgjort flere gange, og forbindelsen bliver svagere med hver gang.\n\nNogen i Undergrunden ville vide mere om denne unikke afskyelighed.>"},
  [97289] = {n="Uendelig Pine", l="Bring Baronens Hoved til Oddmars krop i Undergrunden.", d="Vi laver afskyelige hoveder hele tiden, men dette her er særligt. Det tilhørte engang en Storemarskal fra Alliancen. En særlig ubehagelig en. Den Mørke Dame havde fornøjelsen af selv at sende denne her af sted.\n\nÅh, de hemmeligheder det kunne fortælle, hvis det kunne tale. Og det kan! Hvis vi fastgør det på en passende vært.\n\nVær så venlig at placere det ved siden af den tilgængelige krop i næste rum. Men fastgør det ikke. Ikke endnu."},
  [97290] = {n="Uendelig Pine", l="Rapporter dine fund til Mesterapoteker Faranell i Undergrunden.", d="Du... afskyelighed...\n\nHvorfor skulle... jeg hjælpe dig...\n\nFor væk med dig..."},
  [97291] = {n="Uendelig Pine", l="Saml en Giftig Dødningehætte fra Gulbrun Grisette i Handelskvarteret, Blærelugt nær Urtekundskabslæreren og Smertens Essens fra giftsælgeren i Skurkekvarteret til Mesterapoteker Faranell i Undergrunden.", d="Med hovedet genfastgjort er alt, vi nu behøver, at binde det til Den Mørke Dames vilje. Det burde ikke være et problem. Udyret har knap nok hjerne tilbage efter alle de tæskeoplevelser, det har haft.\n\nVi må blot motivere det.\n\nHent mig en Giftig Dødningehætte fra Frøken Grisette i Handelskvarteret. Åh, og lidt Blærelugt fra vores lokale urtekundskabslærere, Alliestjernerne. Tag gerne bare noget, de skylder mig. Og til sidst lidt Smertens Essens. Enhver gammel giftsælger burde kunne klare det.\n\nVi har en eliksir at lave!"},
  [97292] = {n="Uendelig Pine", l="Injicer det Hvæsende Serum i systemet over Oddmars krop for Mesterapoteker Faranell.", d="Jeg har brygget et dejligt serum, som vores nye gæst helt sikkert vil finde ganske... stimulerende.\n\nTag det her. Før det ind i maskineriet, der drypper ned fra oven over ham. Lad os se, om vi ikke kan vise ham, hvorfor det er i hans egen interesse at tjene loyalt.\n\nOg prøv ikke at tabe det. Jeg har ikke råd til en ny assistent."},
  [97326] = {n="Sten til Hvil", l="Returner 8 Glatte Klippeblokke til Tråa bag Grommash-borgen.", d="Hej! Du har tid til at hjælpe os! Det ved jeg, for jeg kan se det på, hvordan du smilede, da du så på spillet, vi spiller.\n\nDette sted bag Grommash-borgen er rart, for det er klart nok til, at vi kan stille vores figurer op. Men det, der er elendigt, er, at vi ikke har nok sten til stole eller borde.\n\nDu er stor og stærk... synes du, du kunne bære nogle mellemstore sten hjem, glatte nok til at sidde på, hvis vi trænger til en pause?"},
  [97328] = {n="Alt af Værdi", l="Hent 8 Stjålne Forsendelser fra Ruinerne af Zul'Kaffe i Kvælerdorn-dalen, og returner dit bytte til nogen i Bytteviken.", d="<Mens du sigter gennem affaldet efterladt af et forfærdeligt zeppelinstyrt lige over dig, finder du tegn på en tyk forsendelse af forsyninger, som for længst er blevet plyndret for al sin værdi. Selv forsendelsesetiketterne er revet og strimlet, og kun ordene 'Bytteviken' er knap læselige på en af dem.\n\nUtallige totåede fodspor og flere pletter med opgravet jord fører alle hen mod ruiner i nordvest.>"},
  [97485] = {n="Traditioner fra Klippen", l="Køb en Bundt Urter hos Nidda Urtekvinden, en Bundt Cedertvigge hos Nattet Fortryllelsesleverandøren, Senetråd hos Mahug Læderleverandøren og Ceremoniel Flint og Tinder hos Nåle Madleverandøren.\n\nKombiner tingene og drys røgelsen fra Jægerens Bakke.", d="Ånd'shes velsignelser, ven.\n\nVi tauren har en tradition med at sprede røgelse for vinden, og jeg håbede, at du ville være interesseret i at ære denne tradition.\n\nDu skal fremstille røgelsen ved at købe urter hos Nidda, ceder hos Nattet, senetråd hos Mahug i midterhøjden og ceremoniel flint og tinder hos Nåle på den øverste højde. Når du har disse ting, skal du kombinere dem og sprede dem fra den sydvendte klippe på Jægerens Bakke.\n\nDu finder en måtte og røgelse ved den ceremonielle plads."},
  [97538] = {n="Pigmenter til Malerier", l="Tah Vinterhov i Tordenklippe vil have 30 Mirkurt-bælge fra Mirkfallon-søen.", d="Hilsen, ven. Må jeg bede dig om en tjeneste? Jeg er netop løbet tør for rødt pigment til mine malerier, og jeg leder efter en med yngre hove til at tage den lange rejse ind i Stenklippe-bjergene på mine vegne.\n\nMidt i bjergpasset ligger en stor cirkulær sø, Mirkfallon-søen, der har en unik plante, som vokser i dens vande. Bælgene fra denne plante, mirkurt, bliver livligt røde, når de tørres. Saml bælgene fra denne plante for mig, så belønner jeg dig generøst for din indsats."},
  [97539] = {n="Silkede Suturer", l="Returner 12 Kirurgisk Edderkoppesilke til Doktor Gregor Viktor i Hammerfald, Arathi-højlandet.", d="Denne lejr er ved at forfalde. Belejringsskaderne står stadig uden reparation, som om forsømmelse var en politik. Det tillader jeg ikke her. Infirmeriet står under mit ansvar, og jeg har tænkt mig at holde det funktionsdygtigt.\n\nVi er næsten løbet tør for forsyninger. Jeg får brug for mere udstyr - nok til at holde arbejderne og vagterne på benene.\n\nUnder pres kan vi lave en ret effektiv feltsutur af snoet edderkoppesilke.\n\n<Class>, bring mig noget fra edderkopperne, der lurer i disse højland."},
  [97558] = {n="Huder til De Forladte", l="Bring Shelene Rabarber 8 Skumringsflagermus-vingemembraner, 6 Mørkehund-huder og 3 Ondskabsfinne-mudderfisk-hud.", d="En del af udødeligheden, som ingen nævner, er, hvad der sker, når vi kommer til skade. Hvordan heler de udødes hud sig selv?\n\nTja, det gør den ikke.\n\nVores er et forbandet liv, <Name>. Vi må tage fra de levende for at fremme vores egen eksistens.\n\nNår vi pådrager os en skade, må vi erstatte vores hud, og det betyder som regel dyrehud. Da forskellige hudtykkelser er bedre til forskellige steder på vores kroppe, er variation nøglen!\n\nBring mig vingemembraner fra en skumringsflagermus, huder fra en mørkehund og hud fra en Ondskabsfinne-mudderfisk."},
  [97583] = {n="VRIGGEL.", l="Køb Næringsrigt Slimslam og vend tilbage til din venlige, ophidsede slim. Hvis den virker træt, så prøv at danse med den igen for at fange dens opmærksomhed.", d="<Den lille slim virker begejstret og forsøger at spejle dine bevægelser, mens du danser. Den begynder dog at se træt ud.\n\nDen lille slim svæver hen over et stykke slam og suger det op, og ser en smule forynget ud.\n\nDet ser ud til, at al dansen har slidt den op. Måske er der nogen i Undergrundens kanaler, der sælger mere af dette næringsrige slam?>"},
  [97891] = {n="Hurtig Eliksirløber", l="Bring den Ustabile Eliksir til Doktor Martin Felben i Apotekerium inden for tidsgrænsen.", d="Du! Hurtigt, jeg har brug for, at du bringer denne eliksir over slimkanalen til Doktor Martin Felben i Apotekerium!\n\nDen har en meget begrænset holdbarhed, og nej, jeg kan ikke gå selv, mine knæ rasler og springer ud af led, hvis jeg prøver at løbe.\n\nBare en anden dejlig bivirkning ved at være udød, tilsyneladende.\n\nMen vi spilder tid! Her, tag den og løb!\n\n<Alessandro laver en viftende bevægelse.>"},
  [97894] = {n="Forretning i Auberdin", l="Tjek til Gorbold Stålhånd i Auberdin i Mørkekysten.\n\nBorgus nævnte en båd ved den sydligste mole i Stormvind Havn, som kan tage dig derhen.", d="Fornøjelse at gøre bekendtskab! Navnet er Borgus, af den ene og eneste Stålhånd-familie. Man kan altid regne med en Stålhånd for en rimelig handel!\n\nFor et par uger siden sluttede min bror Gorbold sig til en handelsbod i Auberdin. Der er masser af guld at tjene på at forsyne skibene derovre, kan jeg fortælle dig! Heldig pjok.\n\nJeg har ikke hørt fra ham siden--vil du tjekke til ham, hvis du alligevel er på vej derhen?\n\nDer er et nyt skib i havnen, som kan føre dig direkte derhen. Sejl til den sydligste mole; du kan ikke overse den!"},
  [97899] = {n="Lejrliv 101: Alkymi", l="Tal med Vuut i Orgrimgrad for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du valgte at koge brygge og eliksirer som Alkymist. Jeg er sikker på, at det kommer til nytte på dine rejser.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Manabrønd til din lejr. Byg en af dem, og alle healere og tryllekunstnere vil løbe til for at få en forfriskende smag."},
  [97901] = {n="Lejrliv 101: Fortryllelse", l="Tal med Jhæg i Orgrimgrad for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Fortryllere gør alting bedre og er altid velkomne i enhver lejr ude i det vilde.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fortryllet Lut til din lejr. Det er så vigtigt at finde underholdning i din fritid, og dette lille stykke magi kan sikre, at du er klar til at trodse alle slags udfordringer, når du igen begiver dig ud ad den gamle støvede sti."},
  [97903] = {n="Lejrliv 101: Førstehjælp", l="Tal med Rårk i Barberbakken for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du har kastet dig over førstehjælp? Det er en ærefuld... og pragmatisk beskæftigelse for en <Class>.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og et tiltrængt helbred i din lejr kunne endda redde liv."},
  [97904] = {n="Lejrliv 101: Fiskeri", l="Tal med Lau'Tiki nær Sen'jin-landsbyen for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme godt med i lejren.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skabe lidt glæde for dig selv og dine medeventyrere. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97905] = {n="Lejrliv 101: Urtekundskab", l="Tal med Jandi i Orgrimgrad for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det ser ud til, at du har tilegnet dig lidt færdighed i urtekundskab. At plukke blomster er ikke kun til dovne tidsfordriv, ved du. Det kan være nyttigt... og lukrativt.\n\nJeg tror, jeg kender en, der kan lære dig at lave et Røgelseslys til din lejr. Høje humør er en nøglekomponent for at holde healere og tryllekunstnere i kampen, og et Røgelseslys kan give et løft, som magibrugere sikkert vil sætte pris på."},
  [97914] = {n="Udvidede Horisonter", l="Bring Thundris' Brev til Baros Alexstøn i Stormvind.\n\nThundris nævnte et skib i Auberdin, som kan tage dig derhen.", d="Auberdin er et ydmygt sted, <Class>. Du vil ikke høre dets navn nævnt i Darnassos' grene. For det meste henvises der kun til det, Sønderrivelsen tog fra os--de blomstrende byer Amethand, Bashalhand og... Lathar'Lazal.\n\nAlligevel står Auberdin i deres skygge.\n\nJeg ønsker, at vores arbejde her bliver anerkendt. Et nyt fartøj forbinder os med kongeriget Stormvind og bringer liv og forsyninger til vores kyster. Jeg beder dig om at deltage i dens næste rejse og bringe dette brev til et menneske ved navn Baros Alexstøn.\n\nGør vores hjem kendt."},
  [97916] = {n="Lejrliv 101: Smedekunst", l="Tal med Smed Argus i Guldshire for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du er blevet smed. Det er et godt valg, hvis du vil sikre, at dine klinger aldrig bliver sløve.\n\nJeg tror, jeg kender en, der kan hjælpe med det ved at lære dig at lave en Slibesten. Tag en af disse med ud til din lejr, og alle krigere og lømler i området vil stå i kø for at slibe deres våben."},
  [97918] = {n="Lejrliv 101: Ingeniørvidenskab", l="Tal med Sprite Springfjeder i Stormvind for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Ingeniører som dig kan koge alle slags dimser, robotter og bomber op for sjov og profit.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Ingrediensrobot til din lejr. Denne hjælpsomme automat kan hjælpe med at holde dig godt forsynet, så du og dine allierede aldrig løber tør for de materialer, I skal bruge til at brænde jeres besværgelser."},
  [97919] = {n="Lejrliv 101: Førstehjælp", l="Tal med Michelle Bella i Guldshire for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du har kastet dig over førstehjælp? Det er en ærefuld... og pragmatisk beskæftigelse for en <Class>.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og et tiltrængt helbred i din lejr kunne endda redde liv."},
  [97920] = {n="Lejrliv 101: Fiskeri", l="Tal med Lee Brun nær Guldshire for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme godt med i lejren.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skabe lidt glæde for dig selv og dine medeventyrere. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97921] = {n="Lejrliv 101: Urtekundskab", l="Tal med Urtekyndig Pomeroy i Elwynnskoven for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det ser ud til, at du har tilegnet dig lidt færdighed i urtekundskab. At plukke blomster er ikke kun til dovne tidsfordriv, ved du. Det kan være nyttigt... og lukrativt.\n\nJeg tror, jeg kender en, der kan lære dig at lave et Røgelseslys til din lejr. Høje humør er en nøglekomponent for at holde healere og tryllekunstnere i kampen, og et Røgelseslys kan give et løft, som magibrugere sikkert vil sætte pris på."},
  [97923] = {n="Lejrliv 101: Minedrift", l="Tal med Gelman Stenhånd i Stormvind for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Minedrift er ikke det mest glamourøse, men det er godt, ærligt arbejde og en fin beskæftigelse for dig at udforske.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Magnetsten til din lejr. Byg en af disse, og alle, der har lyst til at svinge et sværd, vil ivrigt samle sig om dit bål og suge det ekstra \"hej\", den kan give, til sig for at øge deres kampkraft."},
  [97924] = {n="Lejrliv 101: Lædergarveri", l="Tal med Helene Pelsskinner i Guldshire for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="At kunne høste skind og huder fra faldne bæster på en dygtig måde er en af de mest værdifulde færdigheder, en eventyrer kan besidde.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Lejrstol til din lejr. Nogle gange er det vigtigt bare at tage byrden af, og du kan bruge nogle af de huder, du har samlet, til at lave en behagelig stol at sidde i. En smule afslapning kan hjælpe med at sikre, at du er i topform og kan slå til, hvor det tæller, næste gang du havner midt i et slagsmål."},
  [97925] = {n="Lejrliv 101: Skrædderi", l="Tal med Eldrin i Østdal Tømmerlejr i Elwynnskoven for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Skrædderi er et overraskende stærkt håndværk at investere i, og jeg er sikker på, at det vil tjene dig godt.\n\nJeg kender en, der kan lære dig at lave et Fraktionsbanner til din lejr, forudsat at du har evnerne til det. Inspiration og moral er en central del af succes på ethvert slagmark, og et inspirerende banner kan gå langt i at holde dig energisk."},
  [97926] = {n="Man Må Nøjes", l="Bring Alexstons Svar til Thundris Vindvæver i Auberdin i Mørkekysten.", d="Jeg ville ønske, det var så nemt at hjælpe, <Class>. Det ville jeg virkelig.\n\nHvis du vælger at bruge mere tid i vores lande, vil du opdage, at mange mangler alt. Stormvinds kasse er ikke, hvad den engang var, og det, der er tilbage, er tyndt spredt.\n\nGiv dette svar til ældste, næste gang du ser ham. Det er ikke, hvad han håber på, men det er alt, jeg har at tilbyde lige nu."},
  [97931] = {n="Lejrliv 101: Førstehjælp", l="Tal med Vira Ungbuk i Blodhov-landsbyen for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du har kastet dig over førstehjælp? Det er en ærefuld... og pragmatisk beskæftigelse for en <Class>.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og et tiltrængt helbred i din lejr kunne endda redde liv."},
  [97932] = {n="Lejrliv 101: Fiskeri", l="Tal med Uthan Stillvand i Blodhov-landsbyen for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme godt med i lejren.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skabe lidt glæde for dig selv og dine medeventyrere. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97933] = {n="Lejrliv 101: Urtekundskab", l="Tal med Komin Vinterhov i Tordenklippe for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det ser ud til, at du har tilegnet dig lidt færdighed i urtekundskab. At plukke blomster er ikke kun til dovne tidsfordriv, ved du. Det kan være nyttigt... og lukrativt.\n\nJeg tror, jeg kender en, der kan lære dig at lave et Røgelseslys til din lejr. Høje humør er en nøglekomponent for at holde healere og tryllekunstnere i kampen, og et Røgelseslys kan give et løft, som magibrugere sikkert vil sætte pris på."},
  [97940] = {n="Lejrliv 101: Fortryllelse", l="Tal med Alanna Ravenøje i Orakellunden i Teldrasil for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Fortryllere gør alting bedre og er altid velkomne i enhver lejr ude i det vilde.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fortryllet Lut til din lejr. Det er så vigtigt at finde underholdning i din fritid, og dette lille stykke magi kan sikre, at du er klar til at trodse alle slags udfordringer, når du igen begiver dig ud ad den gamle støvede sti."},
  [97942] = {n="Lejrliv 101: Førstehjælp", l="Tal med Byancie i Dolanår for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du har kastet dig over førstehjælp? Det er en ærefuld... og pragmatisk beskæftigelse for en <Class>.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og et tiltrængt helbred i din lejr kunne endda redde liv."},
  [97943] = {n="Lejrliv 101: Fiskeri", l="Tal med Astaia i Darnassos for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme godt med i lejren.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skabe lidt glæde for dig selv og dine medeventyrere. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97951] = {n="Lejrliv 101: Alkymi", l="Tal med Carolai Anis i Gryde-by for at lære at lave en lejrgenstand til dit erhverv, når du har vist dygtighed i dit fag.", d="Så du valgte at koge brygge og eliksirer som Alkymist. Jeg er sikker på, at det kommer til nytte på dine rejser.\n\nJeg tror, jeg kender en, der kan lære dig at lave en Manabrønd til din lejr. Byg en af dem, og alle healere og tryllekunstnere vil løbe til for at få en forfriskende smag."},
  [97953] = {n="Lejrliv 101: Fortryllelse", l="Tal med Vance Underdunkel i Gryde-by for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Fortryllere gør alting bedre og er altid velkomne ved enhver lejr ude i det vilde.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Fortryllet Lut til din lejr. Det er så vigtigt at finde underholdning i din fritid, og denne lille smule magi kan hjælpe med at sikre, at du er klar til at klare alle slags udfordringer, når du igen kaster dig ud på den gamle støvede sti."},
  [97955] = {n="Lejrliv 101: Førstehjælp", l="Tal med Sygeplejerske Neela i Gryde-by for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Så du har kastet dig over førstehjælp? Det er en hæderlig... og pragmatisk beskæftigelse som <Class>.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og at tilbyde lidt tiltrængt healing i din lejr kunne endda redde liv."},
  [97956] = {n="Lejrliv 101: Fiskeri", l="Tal med Clyde Fiskesen i Gryde-by for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme til nytte i lejren.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skaffe dig selv og dine medeventyrere lidt glæde. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97957] = {n="Lejrliv 101: Urtekundskab", l="Tal med Farusa i Gryde-by for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Det ser ud til, at du har tilegnet dig lidt færdighed i urtekundskab. Blomsterplukning er ikke bare til dagdriveri, ved du. Det kan være nyttigt... og lukrativt.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave et Røgelseslys til din lejr. Høj stemning er en vigtig komponent i at holde healere og besværgere i kampen, og et Røgelseslys kan give et løft, som magibrugere sikkert vil sætte stor pris på."},
  [97959] = {n="Lejrliv 101: Minedrift", l="Tal med Brom Dræberen i Undergrunden for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Minedrift er ikke det mest glamourøse, men det er ærligt arbejde og et fint fag for dig at udforske.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Magnetsten til din lejr. Byg en af disse, og alle, der vil svinge et sværd, vil ivrigt samle sig om dit bål og suge den ekstra \"oomph\", den kan give, til sig for at øge deres kampdygtighed."},
  [97960] = {n="Lejrliv 101: Flåning", l="Tal med Rand Rabarber på vejen til Undergrunden fra Gryde-by for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="At kunne flå skind og huder af faldne bæster på en dygtig måde er en af de mere værdifulde færdigheder, en eventyrer kan besidde.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Lejrstol til din lejr. Nogle gange er det vigtigt bare at tage et læs af skuldrene, og du kan bruge nogle af de huder, du har samlet, til at lave en behagelig stol at sidde i. Lidt afslapning kan hjælpe med at sikre, at du er i topform og kan slå til, hvor det batter, næste gang du befinder dig midt i et slagsmål."},
  [97963] = {n="Lejrliv 101: Alkymi", l="Tal med Nyassa Hurtigdrik i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Så du valgte at koge brygge og eliksirer som alkymist. Jeg er sikker på, at det kommer til nytte på dine rejser.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Manabrønd til din lejr. Byg en af disse, og alle healerne og besværgertyperne vil komme løbende for at få en forfriskende smag."},
  [97964] = {n="Lejrliv 101: Smedning", l="Tal med Aedi Trefoldsmedet i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Så du er blevet smed. Det er et godt valg, hvis du vil sikre, at dine klinger aldrig bliver sløve.\n\nJeg regner med, at jeg kender en, der kan hjælpe med det ved at lære dig at lave en Slibesten. Tag en af disse frem i din lejr, og alle krigere og tyve i området vil stå i kø for at skærpe deres våben."},
  [97965] = {n="Lejrliv 101: Førstehjælp", l="Tal med Naleeia Kludelapper i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Så du har kastet dig over førstehjælp? Det er en hæderlig... og pragmatisk beskæftigelse som <Class>.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Førstehjælpskasse til din lejr. Skader er en realitet i eventyrernes verden, og at tilbyde lidt tiltrængt healing i din lejr kunne endda redde liv."},
  [97967] = {n="Lejrliv 101: Fiskeri", l="Tal med Fenn Godvejr i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Det tror du måske ikke, men dine evner som fisker kan faktisk komme til nytte i lejren.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Fiskeskål til din lejr. Du kan bruge denne indretning til at skaffe dig selv og dine medeventyrere lidt glæde. En glad eventyrer er en stærk eventyrer, og jeg er sikker på, at dine kampevner vil afspejle det."},
  [97968] = {n="Lejrliv 101: Urtekundskab", l="Tal med Syriel Natregn i Valanår for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Det ser ud til, at du har tilegnet dig lidt færdighed i urtekundskab. Blomsterplukning er ikke bare til dagdriveri, ved du. Det kan være nyttigt... og lukrativt.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave et Røgelseslys til din lejr. Høj stemning er en vigtig komponent i at holde healere og besværgere i kampen, og et Røgelseslys kan give et løft, som magibrugere sikkert vil sætte stor pris på."},
  [97969] = {n="Lejrliv 101: Læderarbejde", l="Tal med Indari Solsøm i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Du er blevet læderarbejder. Godt gået, <Class>. Jeg regner med, at jeg kender en, der kan lære dig at lave et telt til dig selv, der holder dig kølig på varme dage og tørt på regnfulde dage.\n\nMed et godt telt over hovedet sikrer du, at du får al den hvile, du behøver for at forblive skarp på dine rejser."},
  [97970] = {n="Lejrliv 101: Minedrift", l="Tal med Messana Kammevind i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Minedrift er ikke det mest glamourøse, men det er ærligt arbejde og et fint fag for dig at udforske.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Magnetsten til din lejr. Byg en af disse, og alle, der vil svinge et sværd, vil ivrigt samle sig om dit bål og suge den ekstra \"oomph\", den kan give, til sig for at øge deres kampdygtighed."},
  [97971] = {n="Lejrliv 101: Flåning", l="Tal med Mendalass Kludelapper i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="At kunne flå skind og huder af faldne bæster på en dygtig måde er en af de mere værdifulde færdigheder, en eventyrer kan besidde.\n\nJeg regner med, at jeg kender en, der kan lære dig at lave en Lejrstol til din lejr. Nogle gange er det vigtigt bare at tage et læs af skuldrene, og du kan bruge nogle af de huder, du har samlet, til at lave en behagelig stol at sidde i. Lidt afslapning kan hjælpe med at sikre, at du er i topform og kan slå til, hvor det batter, næste gang du befinder dig midt i et slagsmål."},
  [97972] = {n="Lejrliv 101: Skrædderi", l="Tal med Taleen Glimtråd i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Skrædderi er en overraskende kraftfuld håndværksfærdighed at investere i, og jeg er sikker på, at den vil tjene dig godt.\n\nJeg kender en, der kan lære dig at lave et Fraktionsbanner til din lejr, forudsat at du har færdighederne til det. Inspiration og moral er en central del af succes på ethvert slagmark, og et inspirerende banner kan gå langt i at holde dig energisk."},
  [97973] = {n="Lejrliv 101: Skrædderi", l="Tal med Taleen Glimtråd i Shen'dar-landsbyen for at lære at fremstille en lejrting til dit fag, når du har vist din færdighed.", d="Skrædderi er en overraskende kraftfuld håndværksfærdighed at investere i, og jeg er sikker på, at den vil tjene dig godt.\n\nJeg kender en, der kan lære dig at lave et Fraktionsbanner til din lejr. Inspiration og moral er en central del af succes på ethvert slagmark, og et inspirerende banner kan gå langt i at holde dig energisk."},
  [97977] = {n="Naturens Kald", l="Saml 4 Knudefyr-totemer og bring dem til Tarindrella.", d="Knudefyr-pelsbolgerne ville ikke vende sig mod deres gamle allierede så let. Vi må lære mere om deres kår.\n\nSøg i deres forladte hjem efter totemer. Hvis nogen overlevede kaosset ved deres afrejse, kan deres indgraveringer fortælle os mere om, hvad der skete her.\n\nDu finder deres lejre langs dalens vestlige kant, selvom grellerne og grellingerne måske har spredt dem længere væk."},
  [97979] = {n="Gudinden Sørger for Os", l="Kast Elunes Lys og Skyggeopløsning.", d="Du er født kaldorei--stjernernes børn--og har arvet en fødselsret, der er ulig noget andet i denne verden. Elunes nåde kan oplyse vores styrker, så vores angreb rammer præcist, eller den kan hjælpe med at skjule os, ligesom månen kan formørke solen.\n\nVores Lange Vagt efter forsvaret af Hyjal-bjerget er forbi, og vi har sluttet os til Alliancen af andre--som du vil møde til sin tid. Indtil videre ligger du i grenene af Teldrasil.\n\nDemonstrer Moder Månes gaver, og bad dig i hendes velsignelser."},
  [97985] = {n="Tordnende Hjerter", l="Dræb Stormhjerte i Tusindnåle og skaf dets hjerte.", d="Fascinerende, er de ikke? Dette er første gang, jeg nogensinde er blevet indviet i hemmelighederne bag monstrumskabelse.\n\nJeg har studeret disse noter, og det ser ud til, at vi har brug for et hjerte. Et enormt et!\n\nJeg hører, at der er en tordenøgle af imponerende størrelse dér, kaldet Stormhjerte, som patruljerer langs kløftens kant i Tusindnåle. Med et navn som det må den have det perfekte hjerte. Jeg må have det hjerte!\n\nÅh, og jeg foreslår også, at du tager venner med. Stormhjerte er ikke kendt for at være fredelig."},
  [98013] = {n="Svulmende Styrker", l="Eliminér 12 Stormskæl-myrmidoner, 8 Stormskæl-tryllekvinder og 6 Stormskæl-krigere for Arbal ved Lunden for de Ældgamle.", d="Stål dig selv til din tid i ruinerne, unge... du vil ikke få fri passage dér.\n\nAdskillige forbandede Højfødte, nu kendt som nagaer, strejfer rundt i den engang så store by. Rejs mod nordøst og fjern dem fra dette land.\n\nHvad de engang var... er ikke mere. Hvis de hjælper Tusmørkets Hammer, kan de kun bringe yderligere smerte til de skove, der engang gav dem ly.\n\nKrig er, hvad de søger, <Class>. Krig... er, hvad vi vil bringe."},
  [98021] = {n="Rejsen til Vagtbakken", l="Rapporter til Gryan Tykfrakke på Vagtbakken i Vestfald.", d="Hvis du gerne vil begynde at gøre noget godt i vores verden, vil jeg anbefale, at du melder dig hos en mand ved navn Gryan Tykfrakke i Vestfald mod syd, i bosættelsen kendt som Vagtbakken. Hans folk har brug for hjælp.\n\nEfter at have rejst hertil fra et andet eksistensplan, kan de problemer, vores lande står over for, virke små. Jeg forsikrer dig, at den hjælp, du yder til dem, der rammes af sådanne problemer, betyder alt for dem, og du vil vokse i styrke af dit arbejde.\n\nHeld og lykke derude, eventyrer!"},
  [98024] = {n="Rejsen til Korsvejen", l="Rapporter til Tork ved Korsvejen i Ødemarken.", d="Efter at have rejst hertil fra det elementære plan, kan de problemer, vores lande står over for, virke små. Vær sikker på, at farerne, Horden står over for, er meget virkelige, og du vil blive formidabel, hvis du overlever din tjeneste.\n\nHvis du gerne vil begynde at gøre noget godt i vores verden, så rejs mod sydvest til de vidtstrakte lande kendt som Ødemarken. Der findes en bosættelse kendt som Korsvejen. Dens stolte borgere er altid i behov for hjælp.\n\nDrag afsted med ære, eventyrer!"},
  [98025] = {n="EFTERLYST: Jai'vhanøl", l="Find og dræb uglen kendt som Jai'vhanøl, og tag en af hendes fjer. Den sorte ugle blev sidst set nord for Amethand-ruinerne nær bjergets fod. Meld Jai'vhanøls død til Vagt Glynda Nal'Skæl i Auberdin.", d="Opmærksomhed!\n\nDer er udlovet en belønning for døden af uglen \"Jai'vhanøl\", også kendt som \"Sværdfjer\".\n\nDesværre er denne ugle blevet gal og er begyndt at angribe rejsende, mens de færdes ad vejen nær Auberdin.\n\nJai'vhanøl blev sidst set nord for Amethand-ruinerne nær bjergets fod. Bring en af hendes kulsorte fjer tilbage som bevis på hendes død.\n\nBelønningen for denne eftersøgning skal kræves hos Vagt Glynda Nal'Skæl i Auberdin.\n\nAuberdin-landsbyens råd"},
  [98027] = {n="Skinnende Halvmånehalskæde", l="Lever Halvmånehalskæden til Maliyn i Stjernelund.", d="<Sølvhalskæden i dine hænder skinner blidt, mens du undersøger den. Den lille halvmåneform ligner andre natteelvesymboler, du har set før.\n\nNår du vender halskæden om, er der en lille indskrift: \"Alor'lormå, Maliyn\". Tilhører den måske Maliyn i Stjernelund?>"},
  [98059] = {n="Hillsbrads Skjulested", l="Læg den forseglede kompagniforespørgsel, du fik, på bogholderbordet inde i Hillsbrads rådhus.", d="Hillsbrad-rådet har ikke svaret på vores nye dommers breve. Det sidste ord, jeg fik ud af en forbipasserende købmand fra byen, retfærdiggjorde ikke synderligt deres tavshed.\n\nVi beder kun om en lille tropp--men jeg får at vide, at flere belejringsballistaer hviler i pæn stand inden for et afspærret område.\n\nGå ind i deres rådhus som en borger, der afleverer en folketællingsanmodning, og læg dette pænt på bogholderbordet.\n\nVend tilbage til mig, når gerningen er udført."},
  [98067] = {n="Vagternes Øjne", l="Placér Vagtugler ved indgangen til Cenarion-fæstningens dybder, Darnassos Bank, Håndværkerterrassens Kro og Byporten for Vagt Dalia Solklinge i Månens Tempel i Darnassos.", d="General Fjermåne sørger for, at alle vagterne får tid til at bede til Elune. En rigtig jægerinde fører ikke kun klinge, men også gudindens gaver for at overvinde vores fjender.\n\nDu kan hjælpe med mine daglige pligter. Placér vagter rundt om byen--start med tunnelerne, der fører under Cenarion-fæstningen mod nord, banken midt i byen, kroen i Håndværkerterrassen mod nordøst og byporterne. Vagterne kan hjælpe dig.\n\nNoget er galt i Teldrasil--vi må forblive årvågne."},
  [98069] = {n="Stjålne Frihvind-forsyninger", l="Bring 8 Stjålne Frihvind-forsyninger til Jandia i Frihvind-posten.", d="De elendige harpyer! De angreb den sidste karavane, jeg havde planlagt til at levere forsyninger til Frihvind-posten. Vi har nok forsyninger lige nu, men uden flere vil vi snart løbe tør.\n\nJeg er ikke sikker på, hvad harpyerne har tænkt sig at gøre med de ekstra forsyninger, men jeg ville sætte pris på, hvis du kunne hente dem for mig. De har deres rede mod vest herfra. De kan findes både ved foden af klippevæggen og inde i en hule øverst oppe."},
  [98070] = {n="Stop Skrigene", l="Dræb 5 Skrigende Harpyer, 5 Skrigende Forræderfjer og 5 Skrigende Vindkaldere.", d="Skrigekløften er hjemsted for en lokal flok harpyer, kendt for deres voldsomme natur og plyndringstaktikker. De har overfaldet de sidste par forsyningskaravaner, der har været modige nok til at krydse dette sted.\n\nJeg frygter, at hvis der ikke gøres noget snart, vil ingen karavaner turde tage turen til Frihvind-posten.\n\nAf sted med dig, og dræb så mange af disse harpyer, som du kan. Kom tilbage til mig, når det er gjort, så belønner jeg dig godt for din indsats."},
  [98071] = {n="Bryggerens Handel", l="Lever flaskerne med Faldrøg-varietet til Dun Garok i det sydøstlige Hillsbrad-forbjerge, og bring en sæk Hjemmebryggede Humle tilbage.", d="Fik lavet en lille handel med Dun Garok-brygmændene, ja! Vi er ikke de eneste, der savner Faldrøg-familiens vingårde, det viser sig! De fleste af de bedste flaskeårgange er for længst drukket op, men vi har stadig kasser med vinen i kælderen.\n\nTag denne kasse Faldrøg-varietet med til Dun Garok i sydøst, og læg den fra dig ved deres samlingsbål nederst i fortet.\n\nTil gengæld skal du tage en sæk Hjemmebryggede Humle med tilbage.\n\nDen fæstning er det nærmeste, vi har til hjemmet her omkring!"},
  [98072] = {n="Krokoliskerne i Himlen", l="Saml 8 Ubesmittede Karmosinrøde Skæl og bring dem til James Garver i Menetil-havnen.", d="Du er ret driftig! Jeg har lige en tjeneste mere at bede om, hvis du har lyst til noget lidt farligere.\n\nKrokolisk-handelen giver en jævn indtægt, men de er små fisk sammenlignet med, hvad drageunge-skæl indbringer. Folk betaler topkroner for en sæk af dem.\n\nKrokoliskerne i himlen, kalder jeg dem! Min lærling kunne aldrig skaffe dem--men det lyder lige til din smag!\n\nDu finder drageungerne langt mod øst, langs Grønbæltet. Men pas på, der er ondskabsfulde orker i de bakker!"},
  [98093] = {n="Mark der Skal Ryddes", l="Sulhasa i den sydlige Ødemark vil have dig til at rydde 7 Stormhud-øgler og 7 Hånetand-stalkere i området, så hun sikkert kan forlade træet.", d="Jeg er så glad for, at du så mig!\n\nVejret var dejligt i morges, så jeg gik fra Taurajo-lejren ned ad den gyldne vej. Da det blev tid til at vende tilbage, kunne jeg ikke--en flok hyæner begyndte at kredse, og Stormhud-øgler spærrede min eneste flugtvej.\n\nSå klatrede jeg op i dette træ, og nu er der for mange fjender i omegnen på denne time til, at jeg kan løbe hjem gennem markerne.\n\nVil du have noget imod at rydde Stormhud-øglerne og Hånetand-stalkerne for mig?"},
  [98094] = {n="Spejderstøtte", l="Højeksekutor Darthalia vil have dig til at levere opdaterede ordrer til Dødsstalker Masoj, syd for Tarrenmølle, uden for Dun Garok.", d="Nu hvor vi kan stole på dig til at levere kritisk information til vores forreste spioner, er der en ekstra opgave til dig.\n\nTag dette med til Dødsstalker Masoj næsten direkte syd for os. Han har mere til dig, når du når derhen og giver ham dette. Han er placeret på forhøjet terræn nord for den rådne vingård, de kalder Nethander-gården.\n\nVores plan om at tage kontrol over disse lande skrider støt frem."},
  [98095] = {n="Værdifulde Udsigtspunkter", l="Dødsstalker Masoj har brug for, at du placerer de tre Apotekerglas på toppe rundt om i Hillsbrad-forbjergene og vender tilbage til ham.", d="Vores højere kommando indsætter strategiske tropper med flagermusryttere. Nøglepunkter omkring forbjergene har mistet deres signalbaner.\n\nTag disse glas. Åbn dem på tre steder: bakkerne ved Dun Garok, plateauet med udsigt over Dunholde-fæstningen, og det sidste på højderyggen over byen Hillsbrad. Dampene, der stiger op, vil virke som en kraftig stemmegaffel for flagermusenes sanser og lokke dem tilbage til de ønskede afleveringspunkter.\n\nLed efter knuste tomme glas og forny vores mærker."},
  [98189] = {n="Returner Statuetten", l="Bring Menetil-statuetten til Kaptajn Tykfist i Menetil-fæstningen.", d="Herregud, den er--den er smuk!\n\nDen Blinde Prinsesse skulle levere denne til Menetil-havnen, før tragedien ramte. Vi var så tæt på!\n\nJeg tror, den skulle kvitteres for af Kaptajn Tykfist i Menetil-fæstningen lige bag os. Hvorfor gør du ikke æren af at færdiggøre jobbet?"},
  [98190] = {n="En Ven af Familien", l="Bring Menetil-statuetten til Højlord Bolvar Fordrågon i Stormvinds Fæstning.", d="Du vil gerne tage dette med til Stormvind med det samme. Så stolt jeg end er over, at denne fæstning og havn bærer Kong Terenas Menetil II's navn, er vi en rolig havn i en meget grim storm af fjender. Det er bare ikke trygt her.\n\nDragemave-folkene i særdeleshed ville ofre meget for at plyndre noget som dette... og jeg gyser ved tanken om, hvad de ville gøre med det.\n\nGå ikke om ad kommandokæden med denne, min ven. Gå lige til Højlord Fordrågon med den. Han ved, hvor den bedst opbevares."},
  [98191] = {n="En Ven af Familien", l="Bring Menetil-statuetten til Lord Gråsen Skyggebryder i Lysets Katedral.", d="Kong Terenas var en god mand. En from mand. Elsket af sit folk, og virkelig grunden til, at vi overhovedet har denne Alliance.\n\nIronien er, at han var ydmyg--han hadede den slags mindesmærker, og derfor findes der næsten ingen. Og af dem overlevede få Lordaerons fald.\n\nDet ser ud til, at Lyset har samlet sig i denne statuette. Den bør opbevares i Lysets Katedral på Katedralpladsen, midt i byen. Bring den til Lord Gråsen Skyggebryder for sikker opbevaring."},
  [98197] = {n="Krigsbytte", l="Hent 6 Khaz Mødan-træ og 30 Khaz Mødan-jern fra Menetil-havnen til Valstag Jernkæbe.", d="Denne havn blev først bygget af den Gamle Horde som udgangspunkt for deres søinvasion af Hillsbrad. Den omgik fuldstændigt Lordaerons forsvar!\n\nSå mange liv gik tabt...\n\nVærst af alt er, at flåden blev bygget af netop de ressourcer, de stjal fra Khaz Mødan!\n\nDer er masser tilbage i havnen, efter Admiral Stoltmoor jagede brutalerne væk og byggede dette sted til Alliancen. Vi får brug for det til at styrke byens forsvar, nu hvor Dragemave er på fremmarch."},
  [98208] = {n="Himlenes Blomst", l="Hent Nord'el til Sylessa Skumringsviske i Menetil-havnen.", d="Jeg kom til Menetil-havnen fra Auberdin, fra det store træ Teldrasil, for at hente en blomst af stor betydning for mit folk.\n\nMit folks skib, Den Flyvende Fiskeørn, styrtede her for mange måner siden og gik sammen med Kul Tiranske Tredje Flåde. Blandt dets last var blomsten kendt som Nord'el--Himlenes Blomst på dit sprog--som blomstrede under en fuldmåne på toppen af Hyjal-bjerget, vores tidligere hjem.\n\nHjælp mig venligst med at hente den! Vraget ligger lige syd for byen, men det er befolket af vilde murloc-plyndrere!"},
  [98209] = {n="Himlenes Blomst", l="Bring Nord'el til Thundris Vindvæver i Auberdin i Mørkekysten.\n\nDu husker, at Sylessa nævnte en båd i Menetil-havnen, der kan tage dig dertil.", d="Vil du venligst levere Nord'el til ældste Thundris Vindvæver i Auberdin?\n\nBåden herfra burde kunne få dig derhen hurtigt.\n\nJeg beklager anmodningen, det gør jeg virkelig. Jeg er stadig udmattet efter min rejse hertil--og efter at have flygtet fra de murloc-djævle, da jeg første gang forsøgte at hente den hellige blomst!"},
  [98216] = {n="Forståelse af Nutiden", l="Brug Goaz-stenen nær Goaz-vogteren og bring dens Titanisk Nøglesten tilbage til Prospektor Whelgar.", d="De Gamle Guder?! Det kan ikke være gode nyheder!\n\nJeg har fundet en ny del på stenen, der taler om en slags vogter. Hvad det end er, må det være forbundet med stenen!\n\nTag den med dig og se, om du kan finde en stor Titan-konstruktion af en slags i udgravningen. Læs dette sidste afsnit på stenen og se, hvad der sker!\n\nHvis jeg har ret, vil du aktivere tingen. Tag den ud, hvis det er tilfældet, men prøv at bevare alt interessant! Vi må simpelthen vide mere!"},
  [98219] = {n="Den Skamfulde Løjtnant", l="Tal med Løjtnant Farren Ørnelle i Sydstranden i Hillsbrad-forbjergene.", d="Tak igen for at have leveret statuetten sikkert, <Name>.\n\nJeg kunne bruge din hjælp til noget andet. Der er et medlem af bygvagten, som blev overflyttet til tjeneste i Sydstranden ude i Hillsbrad-forbjergene.\n\nHans far var en ven af mig, og selvom jeg ikke er uenig i, at han godt kunne bruge lektien... vil jeg stadig gerne se ham lykkes. Han ville virkelig have gavn af, at nogen som dig hjalp ham.\n\nDer er en båd, der kan tage dig derhen fra Menetil-havnen, hvis du er på vej tilbage."},
  [98221] = {n="Fra Asken", l="Kaptajn Tykfist i Menetil-fæstningen vil have dig til at ødelægge de 4 sæt Angrebsplaner i Vredeshugger-lejren.", d="I den Anden Krig byggede Dragemave en flåde, hvor vi nu står, med det formål at tage Hillsbrad. De var tæt på at lykkes!\n\nDe blev slået tilbage af de røde drager og efterladt som blot udkantsgængere dybt i bjergene. Der har dog været en stigning i aktiviteten i deres lejr nordøst for Menetil.\n\nAlgaz-bakken beviser, at de har planer om at marchere i krig igen og genvinde dette land. Find deres angrebsplaner, notér enhver kritisk information og ødelæg dem. Vi må vide, hvor de vil slå til næste gang!"},
  [98223] = {n="Gamle Vaner", l="Bring den Tøset Tryllebog til Kaptajn Tykfist i Menetil-havnen.", d="Denne bog er slemt brændt--måske af dragildden, der ødelagde meget af Dragemave-klanen.\n\nAf det lille, der stadig kan læses, ser det ud til at beskrive ritualer knyttet til brugen af Dæmonsjælen, som klanen brugte til at kontrollere drager.\n\nDen er alt for ufuldstændig til at være til reel nytte, men ud fra de groft indsatte sider af dyrehud ser det ud til, at Nekrosh har forsøgt at redde den. Nyligt tørret blæk nævner et \"Skyggeråd\".\n\nKaptajn Tykfist i Menetil-havnen vil gerne vide besked om dette."},
  [98230] = {n="Dette Land Var Deres Land", l="Find Howin Venligfjer øst for Menetil-havnen, langs vejen.", d="Efter Krigen om De Tre Hamre, der rev dværgenes liv, som vi kendte det, fra hinanden, bosatte Vildhammerne sig her og grundlagde bjergfæstningen Grimbatol.\n\nDet var et vidunderligt sted. Gryfoner svævede overalt, du kiggede hen, og dykkede ned gennem vådområderne for at snappe en fisk.\n\nDet varede desværre ikke længe.\n\nHowin Venligfjer er en af de første Vildhammere, der er vendt tilbage i årtier. Holder sig for sig selv, langt uden for byen. Følg vejen mod øst--du finder ham til sidst. Han kunne helt sikkert bruge en hjælpende hånd."},
  [98240] = {n="Karmosinrød Kasse-levering", l="Bring den Karmosinrøde Kasse til Howin Venligfjer, væk fra vejen øst for Menetil-havnen.", d="Ordet om de drageunger er officielt ude, <Name>. Vi har allerede fået en ordre!\n\nJeg pakker dem pænt ind til dig, så tager du dem med ud til kunden. Jeg ved det, jeg ved det; det er bare en sidste tjeneste, det lover jeg!\n\nDisse er til en \"Howin Venligfjer\". Han sendte sin gryfon ind til byen af alle steder med et brev til ordren! Han siger, at han bor lige væk fra vejen mod øst, lidt forbi Whelgars Udgravningssted, hvis du kender det."},
  [98245] = {n="Barberkæbe-stikkeri", l="Saml 10 Barberkæbe-hugtænder til Howin Venligfjer.", d="Jeg ved ikke, hvem jeg hader mest: de forbandede Mørkjerns-dværge, Dragemave eller de drager, de red på.\n\n<Howin spytter.>\n\nJeg har tænkt mig at gøre tingene godt igen. Men vi får brug for nogle forsyninger.\n\nDisse drageunge-skæl beskytter ganske godt mod drageild, men de er et helvedes besvær at væve sammen.\n\nBarberkæbe-raptorerne oppe i Raptorkammen mod nordøst og Saltsprøjtedalen mod nordvest er opkaldt efter deres spidse tænder--de burde kunne gennembryde skællene.\n\nBring mig en håndfuld hugtænder."},
  [98246] = {n="Prøvende Tider", l="Saml 12 Perfekte Barberkæbe-æg til Howin Venligfjer.", d="Jeg får brug for nogle æg, hvis min plan skal lykkes. Bassnæb skal have en god, mæt mave--jeg har ikke tænkt mig at hoppe op på ryggen af en surt gryfon.\n\nDe skal være perfekte--ingen revner eller noget.\n\nTag nogle fra Barberkæbe-raptorerne--de er kendt for at have blommer på størrelse med en gnomes hoved. Du finder dem i Raptorkammen mod nordøst og Saltsprøjtedalen mod nordvest.\n\nLad os gøre det til et pænt, jævnt dusin, bare for en sikkerheds skyld."},
  [98247] = {n="Forsendelsesmærkat", l="Lever Forsendelsesmærkaten til en i Azeroth Handelsmyndigheds handelshub i Rødryg-bjergene.", d="<En revet forsendelsesmærkat kan findes på siden af den nu fuldt lagerførte kasse. Selvom den tilsigtede modtager er revet af, er oplysninger om dens oprindelse stadig tilbage.\n\n\"Ejendom tilhørende Azeroth Handelsmyndighed. Venligst returnér tomme kasser eller uopfyldte forsendelser til vores lokale handelshub ved Tre Hjørner-korsvejen i Rødryg-bjergene. Kurérer vil blive kompenseret for deres tid og rejse.\"\n\nVed siden af teksten er et groft tegnet kort over området nær den nævnte destination.>"},
  [98248] = {n="Forsendelsesmærkat", l="Lever Forsendelsesmærkaten til en i Durdotar Forsyning og Logistiks handelshub nær Korsvejen i Ødemarken.", d="<En revet forsendelsesmærkat kan findes på siden af den nu fuldt lagerførte kasse. Selvom den tilsigtede modtager er revet af, er oplysninger om dens oprindelse stadig tilbage.\n\n\"Returnér beskadigede forsendelser eller tomme kasser til Durdotar Forsyning og Logistiks handelsfilial, nu praktisk placeret direkte vest for Korsvejen i Ødemarken. Din tid er værdifuld, og vi vil kompensere dig for din indsats!\"\n\nVed siden af teksten er et groft tegnet kort over området nær den nævnte destination.>"},
  [98251] = {n="Aldrig Kommer Tilbage", l="Dræb 6 Skyggehorn-hjorte og 6 Askedalen-bjørne og vend tilbage til Va'xug Ildfjer nordvest for Faldne Himmelsø.", d="Gaaah!\n\nJeg er så vred. De sagde, at Askedalen var let at følge. Let for hvem? Dyrene? Fuglene?\n\nDet ene øjeblik samlede jeg urter, og det næste sidder jeg fast i denne kløft. Skal jeg virkelig gå halvdelen af skoven rundt for at nå dér, hvor jeg stod for få øjeblikke siden?\n\nNår jeg er sådan her, bliver mine besværgelser ustabile og opfører sig... anderledes.\n\nKunne du tynde ud i dyrelivet i nærheden? Selv deres dumme hove irriterer mig. Jeg afskyr denne forbandede skov."},
  [98252] = {n="En Tom Sti", l="Vis Va'xugs Kilroggs Øje vejen tilbage til hovedvejen i Askedalen.", d="Vis mit Kilroggs Øje vejen ud af denne kløft og tilbage til Askedalen-vejen. Hold det i gang, så følger jeg efter, når jeg ser en klar sti.\n\nJeg bliver her--en af os må holde styr på retningen. Hvis du mister vejen, kan jeg guide dig tilbage gennem øjet. Jeg vil ikke have, at vi begge vandrer blindt rundt i denne ondskabsfulde skov.\n\nJeg kan holde kanalen i fire minutter. Ikke længere. Nå vejen, før synet brister, eller vend tilbage til mig, så prøver vi igen."},
  [98282] = {n="Alkymiske Farer", l="Saml en Uudsprunget Sniglerkirtel fra Thelgen-klippen til Caitlin Græsmand i Menetil-havnen.", d="Visse alkymiske opskrifter kræver ingredienser fra, tja, meget farlige steder. Og det er ofte bare de basale urter! De andre ingredienser er endnu værre!\n\nJeg må lave mere modgift, før jeg kan tage afsted igen. Jeg sværger, alt i denne sump er giftigt. Det er, som om det løber gennem selve jorden!\n\nKan du hjælpe mig? Jeg skal bruge en giftkirtel fra edderkopperne i Thelgen-klippen mod det fjerne sydøst. Men den skal være uudsprunget, ellers løber for meget gift ud, før du når hertil. Undskyld!"},
  [98283] = {n="Massakren", l="Bring Massakrens Hoved til Rethiel Grønvogteren i Grønbæltet.", d="Dette lands naturlige orden bryder sammen. Engang holdt Barberkæbe-raptorerne landet fri for tilgroning. Nu lever de i frygt for deres alfa, der kun er navngivet efter den massakre, den efterlader sig.\n\nJeg frygter, at uhyret er blevet gal af den sygdom, vi endnu ikke har fået helt udryddet.\n\nDet vil reagere på det ondartede kød fra de syge bjørne under Raptorkammen, mod nordøst. Læg deres indvolde i dens hule.\n\nMassakren vil komme. Bring mig dens hoved."},
  [98284] = {n="Lejrliv 101: Fortryllelse", l="Tal med Nasalanna Vindsang i Shen'dar-landsbyen for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist dygtighed i din færdighed.", d="Fortryllere gør alting bedre og er altid velkomne ved ethvert lejrbål ude i naturen.\n\nJeg regner med, at jeg kender en, der kan lære dig at fremstille en Fortryllet Lut til din lejr. Det er så vigtigt at finde underholdning i din fritid, og denne lille smule magi kan hjælpe med at sikre, at du er klar til at trodse alle slags udfordringer, næste gang du begiver dig ud ad den støvede gamle sti."},
  [98285] = {n="Lejrliv 101: Ingeniørkunst", l="Tal med Den Mærkelige Eremit i Skyggestormsskoven for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist dygtighed i din færdighed.", d="En ingeniør er altid opfindsom, og hvis du er alene i naturen, er det altid godt at kunne bruge dit håndværk. Ingen god lejr er komplet uden et par nyttige konstruktioner!\n\nJa, kom tilbage og find mig, når du har fået lidt erfaring som ingeniør, så kan jeg vise dig, hvordan man laver noget specielt!"},
  [98286] = {n="Lejrliv 101: Fortryllelse", l="Tal med Nasalanna Vindsang i Shen'dar-landsbyen for at lære at fremstille en lejrgenstand til dit erhverv, når du har vist dygtighed i din færdighed.", d="Fortryllere gør alting bedre og er altid velkomne ved ethvert lejrbål ude i naturen.\n\nJeg regner med, at jeg kender en, der kan lære dig at fremstille en Fortryllet Lut til din lejr. Det er så vigtigt at finde underholdning i din fritid, og denne lille smule magi kan hjælpe med at sikre, at du er klar til at trodse alle slags udfordringer, næste gang du begiver dig ud ad den støvede gamle sti."},
  [98291] = {n="Død over Dragemaverne", l="Dræb 8 Dragemave-genvindere, 5 Dragemave-sjælebindere og 3 Dragemave-infiltratører i Dragemave-tilflugtsstedet for Howin Venligfjer.", d="Jeg har tænkt mig at komme tilbage til Grimbatol og gøre den til Vildhammernes igen, <Name>. Eller i det mindste lære et par ting.\n\nSe ikke sådan på mig nu. Jeg kender risiciene. Jeg har ikke tænkt mig at storme ind med hammeren svingende, ved du nok.\n\nUanset hvad, får jeg først brug for din hjælp. Dragemave-orkerne marcherer, mens vi taler. De er spredt op og ned ad Dragemave-tilflugtsstedet, hvor de røde drager tidligere sprængte dem.\n\nJeg må have dem tyndet ud, før jeg har en chance for at komme tæt på. Du kan ikke misse dem, hvis du følger vejen mod øst."},
  [98293] = {n="Tvangsafvæbning", l="Saml 30 Dragemave-våben i Dragemave-tilflugtsstedet, og bring dem til Kaptajn Tykfist i Menetil-fæstningen.", d="Dragemaverne oplagrer alle slags våben. Det ville være klogt at fratage dem disse, før flere soldater bliver bevæbnet.\n\nKaptajn Tykfist i Menetil-fæstningen ville helt sikkert være interesseret i disse."},
  [98297] = {n="Stop Cyklussen", l="Dræb det Dæmpede Drageafkom ved Dragemave-portene for Howin Venligfjer.", d="Jeg tog en hurtig testflyvning, mens du var væk. Den gode nyhed er, at rustningen, du hjalp mig med at lave til Bassnæb, virker perfekt!\n\nDen meget dårlige nyhed er, at jeg så en flok af dem Dragemaverne i færd med at slavebinde en rød drageafkom.\n\nAbsolut ikke. Ikke igen.\n\nDu er nødt til at tage den ud. Du skal helt sikkert bruge venner til det. Dræb hekseriterne, der holder den nede, først--det burde frigøre den. Så må du få den ud af sin elendighed.\n\nIngen af dem vil stå i vejen for Vildhammeren."},
  [98298] = {n="Arugels Dårskab", l="Bring 6 Varulvestykker til Dalar Morgenvæver i Gravkammeret.", d="Ah, det er blevet så pinligt tydeligt! Arugal havde næsten ingen magi overhovedet, endsige nok til at skabe varulvene. 'Arugels Forbandelse.' Pyha! Knap nok potent nok til at vare i et par sekunder.\n\nDisse lænker beviser, at han kan binde bestierne, ikke skabe dem. Varulvene har tydeligvis spredt deres forbandelse på en anden måde. Jeg ville vide hvordan.\n\nGå til Gråmanke-muren mod syd. Varulvene ser ud til at sprede sig til menneskerne i nærheden. Riv bestierne i stykker og bring mig det, du finder. Dette kræver en mere direkte tilgang."},
  [98299] = {n="Stands Spredningen", l="Dræb 5 Sygelige Flygtninge og 5 Udmattede Flygtninge for Dalar Morgenvæver i Gravkammeret.", d="Hvis der er én ting, vi ved, så er det, at Arugal er ansvarlig for varulvene i Sølvfyr--hvad enten det er hans egne ænker eller ej. Det, vi ikke ved, er, hvordan det spredes.\n\nMens jeg researcher en måde at stoppe forbandelsen, er vores første prioritet at inddæmme den. Det ser ud til, at denne lidelse ikke kan smitte de forladte, men en stor gruppe mennesker har samlet sig ved Gråmanke-muren.\n\nGå til muren og nedlæg disse flygtninge, før de får en chance for at blive tjenere for Arugal. Og prøv ikke at blive bidt, <Race>."},
  [98310] = {n="At Høste Vores Fremtid", l="Brug Goaz-stenen nær Adøs, Mødr, Gulm og Næru og bring deres hjerter tilbage til Prospektor Whelgar.", d="Der er andre, større golemer rundt om i Vådlandene. De bærer alle inskriptioner, der markerer dem som Adøs, Mødr, Gulm og Næru--og passer til de manglende stykker af Goaz-stenen, du fandt!\n\nJeg vil vædde på, at hvis vi kan bringe stykker af dem også, afslører vi mere af Goaz-stenen!\n\nDu finder Adøs ved Dragemave-portene mod øst, nær Grimbatol. Mødr er lige udenfor Dun Mødr mod nord. Gulm ligger under Grimbatol, øst for Algaz-bakken. Næru er bag Direforge-bakken, mod nordøst."},
  [98313] = {n="Til Videre Studier", l="Bring Whelgar-relikpakken til Historiker Karnik i Jernsmede.", d="Hvad det end handler om, <Name>, så er det episk stof, det er sikkert.\n\nJeg pakker alt pænt ind til dig. Tag det med til Historiker Karnik i Opdagelsesrejsendes Hal i Jernsmede. Du finder ham normalt bagerst, næse dybt begravet i en eller anden tyk bog i biblioteket.\n\nDet vil kræve en hel hær at løse sagen her, men hvis det, vi har set indtil nu, er nogen indikation, vil det være det hele værd!"},
  [98319] = {n="Sikr Bjerget", l="Find Bjergbestiger Cornelius i Den Grizzlede Hule for Bjergbestiger Gretchen.", d="Det er slemt nok at have et trolde-problem, men bjergene er fyldt til randen med vindgoer! De holder normalt til i deres egne huler, men de ser ud til at brede sig som kaniner. Nu har de fyldt Den Grizzlede Hule nord herfra.\n\nHvis vi vil have Hvidskægs rapport, må vi finde min partner Cornelius. Klodsen blev lidt for ivrig og stormede ind med hovedet først. Modigt, men dumt.\n\nGå ind i hulen og se, hvor han er. Og du er velkommen til at tage nogle af bestierne med, mens du er i gang."},
  [98321] = {n="Flintilds Forsendelse", l="Saml 8 Flintilds Forsendelser fra Den Grizzlede Hule for Tongus Flintild i Kharanøs.", d="Hoha! Godt at se en <Race>, der ikke er bange for at få hænderne snavsede.\n\nHvis du leder efter arbejde, er jeg bange for, at jeg er lidt løbet tør for forsyninger lige nu. Vores pålideligste kilde til malm er blevet overrendt af vindgoer, og nu er hulen forladt. Minearbejderne måtte smide alt, da de flygtede!\n\nHa, hvorfor stikker du ikke hovedet rundt i Den Grizzlede Hule mod vest og ser, om du kan finde nogle af vores savnede forsendelser? Det ville spare os for en masse besvær."},
  [98322] = {n="Sikr Bjerget", l="Tjek ind hos Bjergbestiger Gretchen vest for Kharanøs.", d="At udforske mørke huler er eventyrernes arbejde. Mit job er bare at skrive rapporter og sende dem til Jernsmede.\n\nProblemet er, at en af mine rapporter ikke har... ja, meldt sig tilbage. Jeg bad nogle bjergbestigere om at lære mere om vindgo-problemet, vi har herude, men jeg har ikke hørt fra dem.\n\nHvis du alligevel er ude og gå, hvad siger du så til at tjekke ind hos Bjergbestiger Gretchen lige vest for byen? Jeg er allerede for sent på den!"},
  [98323] = {n="Sikr Bjerget", l="Lever Bjergbestiger Gretchens rapport tilbage til Senir Hvidskæg i Kharanøs.", d="Forhåbentlig fik du nedlagt et pænt antal af køterne, mens du var derinde. Det er ærgerligt med Cornelius dog.\n\nUd fra det, du beskriver, er der ikke meget at rapportere, andet end at hulen er en tabt sag. Hvidskæg vil ikke kunne lide det svar, men jeg vover ikke at sende nogen andre ind i den dødsfælde.\n\nDu er velkommen til at videregive beskeden, <Name>. Jeg forlader ikke dette sted, før bjerget er sikret."},
  [98326] = {n="Frosthyl", l="Dræb Frosthyl og saml Fiskesækken for Gretta Gåsemand i Brygnall-landsbyen.", d="Ved du, hvor svært det er at fiske på en frossen sø? Min stakkels mand, Paxton, har været ude midt i den i flere dage, og vi har knap nok én sæk at vise for det.\n\nJa, vi HAVDE en sæk at vise for det. Indtil den tre gange forbandede vindgo angreb mig og stak af med vores fangst. Det vil tage os uger at fiske alt det op igen! Hvis den højtråbende Frosthyl ikke har skræmt dem alle væk, altså.\n\nGør os en tjeneste og få den tilbage, vil du? Den sabbrende brute gemmer sig et sted dybt i Den Grizzlede Hule mod sydøst."},
  [98340] = {n="Den Store Kattaand", l="Tal med Dendrit Stjerneblus i landsbyen Nathavn, Månelunden.", d="Det ser ud til, at du er klar til næste skridt på din rejse, unge druide. Dendrit Stjerneblus har sendt bud efter dig og ønsker, at du opsøger ham i Månelunden endnu en gang.\n\nDu har allerede lært at kalde magien frem, der kan føre dig til Månelunden, så du burde kunne tage afsted med det samme, hvis du vælger det. Jeg vil foreslå, at du tager afsted snart, hvis du vil fortsætte din druideuddannelse."},
  [98341] = {n="Den Store Vindbårne Kattaand", l="Opsøg Sæyleenans Avatar i den sydlige del af Månelunden og lær, hvad den har at dele med dig om den vindbårne kat.", d="En ånd fra dit hjemland er for nylig dukket op her og har bedt mig om at guide dig til den. Denne vindbårne kattaand er kommet for at undervise og vejlede dig, så du kan tage kattedyrsformen fra ånden på Vindras.\n\nAlle druider søger til sidst denne visdom, selvom det ser ud til, at dit hjemland har en lidt anden form end vores traditionelle. Hvis du ønsker at tage denne ånds kattedyrsform, skal du gennemgå vores prøve.\n\nDen kan findes i den sydlige del af Månelunden, syd for de tvillingebroer."},
  [98342] = {n="Den Store Kattaand", l="Hent Hugtandens Relikvie, Kloens Relikvie og Den Tavse Skygges Relikvie fra Stormrage-gravhulen, og bring dem tilbage til Den Store Kattaand.", d="For at trække på min ånd skal du mere end nogle få ord. For at forstå og respektere min form må du bevise, at du kan rumme snilde, snigen, og hvis du bliver klemt op i et hjørne, vildskab.\n\nI gravhulerne lige øst for her ligger tre relikvier af min gunst, som du skal skaffe. De bliver vogtet af mægtige, rasende ånder, der vil angribe dig ved øjesyn. En statue ved indgangen vil velsigne dig med midlertidig snigen, så du kan komme forbi dem.\n\nVend disse relikvier tilbage til mig. Så ser vi, om du er klar til at tage min form."},
  [98362] = {n="Til Tordenklippe", l="Vend tilbage til Tordenklippe og tal med Turak Runetotem på Ældrehøjen.", d="Tiden er kommet til, at vi skal skilles igen, unge, da anvendelsen af dine lektioner tager dig tilbage til den, der sendte dig til mig. Det ser ud til, at din instruktør, Turak Runetotem, har fundet en værdig elev i dig. Jeg tror, jeg ser en i dig også. Lyt til hans lektioner, så vil du snart kunne kalde den Store Kattaand frem for at tage dens form.\n\nGå tilbage derhen, hvor du kom fra. Når tiden er den rette, mødes vi igen."},
  [98372] = {n="En Uheldig Ende"},
  [98386] = {n="Alters Mølle", l="Slå 12 Større Tarantler og ødelæg 6 Tarantel-æg i Alters Mølle for Formand Oslow i Rødryg.", d="Orker, gnolde, murlokker. Alt synes at være ude på at forhindre mig i at få den bro færdig til tiden. Nu har vi fået besked om, at der er et angreb af tarantler ved vores savmølle!\n\nHvis du er klar til at tjene lidt flere mønter, kunne du så ikke tage over til Alters Mølle mod øst og rydde op i deres edderkoppeproblem? Stedet er ikke meget værd for mig, hvis jeg ikke kan sende arbejdere sikkert af sted for at hente forsendelser.\n\nÅh, og hvis du ser gamle Alter, så fortæl ham, at han skylder mig, fordi jeg har ryddet op i hans rod."},
  [98387] = {n="Sortklippe-blokaden", l="Bring 8 Stjålne Våben og 10 Sortklippe-forsyninger til Marskal Marris i Søshire.", d="Man kan ikke føre krig uden våben.\n\nSelvom Sortklippe-orkerne har trængt ind i disse lande, er deres frække bestræbelser ikke uden visse sårbarheder.\n\nTag mod sydøst forbi Stenvagtsfæstningen, find deres lejre, og sigt efter deres våben og forsyninger.\n\nVi får se, hvor stor en trussel de er uden deres krigsværktøj."},
  [98389] = {n="Et Lys i Mørket", l="Befri 6 indspundne ofre i Natnet-Hulen for Aramis Hammerhånd i Dødsklokken.", d="Hils, <Class>. Ja, jeg er paladin. Selv døden kan ikke stoppe Lyset.\n\nDet er noget, mit folk har tilfælles med alle De Forladte--vi har overvundet det, de levende ser som deres ende. Dog frygter nogle blandt vores egne os; de mistænker, at vi vil slå dem ned som en eller anden monstrøsitet.\n\nSandt nok er vores forhold til de dødes tilstand komplekst, men jeg er ikke her for at såre vores egne. Hjælp mig med at vise de andre dette. Begiv dig mod nordvest til Natnet-Hulen og befri de nyoprejste tåber, der er fanget af edderkopperne dér."},
  [98393] = {n="Den Store Katteånd", l="Tal med Dendrit Stjerneblus i landsbyen Nathavn i Månelunden.", d="Det lader til, at du er klar til næste skridt på din rejse, unge druide. Dendrit Stjerneblus har sendt bud efter dig og ønsker, at du søger ham op i Månelunden igen.\n\nDu har allerede lært at kalde magien frem, der kan føre dig til Månelunden, så du burde kunne begive dig af sted med det samme, hvis du vælger det. Jeg vil foreslå, at du tager afsted snart, hvis du vil fortsætte din druidiske træning."},
  [98397] = {n="Til Darnassos", l="Vend tilbage til Darnassos og tal med Mathrengyl Bjørnegænger i Cenarion-enklaven.", d="Tiden er kommet til, at vi igen må skilles, unge ven, for anvendelsen af dine lektioner fører dig tilbage til den, der sendte dig til mig. Det lader til, at din lærer, Mathrengyl Bjørnegænger, har fundet en værdig elev i dig. Jeg tror også, at jeg ser en sådan. Lyt til hans lektioner, så vil du snart kunne kalde på Den Store Katteånd og tage dens skikkelse.\n\nVend tilbage ddér, hvor du kom fra. Når tiden er inde, mødes vi igen."},
  [98403] = {n="Snoet Had", l="Dræb 8 Forurenet Vævskov og bring Modent Ondmos fra Xethorr den Onde til Tallonkai Hurtigrod i Dolanår.", d="Herre Melenas handlede ikke alene; han var andres håndlanger. Den, du søger, er Xethorr den Onde. Det ser ud til, at han har snoet de edderkopper, der kalder Teldrasil hjem, med henblik på deres gift til en snedig plan.\n\nHan har slået sig ned dybt i skoven, i området mod nordvest herfra, kendt som Klyngen. Vær forsigtig, og tag allierede med, for Xethorr er ikke en modstander, man bare tager let på.\n\nSend hans yngel afsted, og bring mig alt, der kan fortælle os mere om skovbukkens værk her."},
  [98404] = {n="Den Store Vindbårne Katteånd", l="Hent Relikvien af Hugtanden, Relikvien af Kloen og Relikvien af Den Tavse Skygge fra Stormrage-gravhulen, og returner dem til Sæyleenans Avatar.", d="For at kunne kalde på min ånd må du gennemgå en prøvelse. For at forstå og respektere min skikkelse skal du bevise, at du kan rumme snedighed, lusken og, hvis du skulle komme i klemme, vildskab.\n\nI gravhulerne lige øst herfra findes tre relikvier, du må skaffe dig. De bevogtes af mægtige, rasende ånder, der angriber dig straks, de ser dig. En statue ved indgangen vil velsigne dig med midlertidig usynlighed, så du kan komme forbi dem.\n\nBring disse relikvier tilbage til mig for at bestå de druidiske prøvelser i disse lande."},
  [98405] = {n="Den Store Katteånd", l="Søg Den Store Katteånd i den sydlige del af Månelunden og lær, hvad den har at dele med dig om kattens natur.", d="I den sydlige del af Månelunden, på en bakke med udsigt over broen, bor et klogt og snedigt væsen, vi kalder Den Store Katteånd.\n\nLigesom Den Store Bjørneånd har denne ånd fungeret som vejleder og mentor for druider, der ønsker at antage kattens skikkelse. Alle druider søger til sidst dens visdom, og hvis du ønsker at tage kattens form, vil du også gøre det.\n\nGå hen og mød Den Store Katteånd, og lær det, den vil lære dig."},
  [98407] = {n="Magtdemonstration", l="Saml 5 Piggede Krave fra Rødryg-piskere for Stedfortræder Feldon ved Søshire.", d="Hvis gnoldene bliver så frække, at de vil slå lejr så tæt på mennesker, er der ingen at sige, hvor langt de vil gå. Vi må afskrække dem.\n\nUdyrene er næppe organiserede, men de ser ud til at respektere styrke over alt andet. Hvis vi kan slå de værste af dem ihjel, måske tage nogle af deres trofæer, kan vi minde disse gnolde om, hvorfor de bør blive i bakkerne, hvor de hører til.\n\nHvis du ser nogen af deres piskere, så bring mig deres krave. Det burde jage Alliancens frygt tilbage i dem."},
  [98417] = {n="Hævnens Spor", l="Maseara Efterårsmåne vil have dig til at lede vest for Skovsang, blandt Satyrdalens dæmoner. Rapportér eventuelle tegn på hendes mand Kurothel, når du vender tilbage.", d="I det øjeblik, hvor vores skæbner var mest sårbare, ramte tragedien vores landsbyer. Skovbukke besudlede vores templer, deres profane berøring plettede hellige grene, og de slagtede de uskyldige uden nåde.\n\nKurothel blev opslugt af vrede. Druiderne tager kampen op mod skovbukken, og han er fulgt efter.\n\nVores bånd består. Jeg mærker min mand mod vest, inde i disse skove. Kom venligst tilbage til mig med nyt om hans skæbne."},
  [98418] = {n="Delt Raseri", l="Dræb 5 Xavianske Skurke, 5 Xavianske Ondsvorne, 5 Xavianske Forrædere og 5 Xavianske Helkaldere.\r\nVend derefter tilbage til Maseara Efterårsmåne i Skovsang.", d="Kurothel nævnte iagttagelser af det, de kalder ulvemænd. Dem fra flokken, der nu lurer i større antal i vores skov. Sidst vi talte sammen, forsøgte druiderne at kommunikere med dem af udyrhjertet, der viste målt kontrol over deres dyriske instinkter.\n\nHans skrevne ord viser en mørkere kamp. Hvis der er noget, vi kan gøre for at se HAM igen, vil det sikkert hjælpe hans pinte sjæl at dæmpe dæmontruslen, der driver ham til denne brændende forvandling.\n\nDræb de xavianske, <Name>."},
  [98423] = {n="Forståelsens Traktat", l="Lever Forståelsens Traktat til Magni Bronzeskæg i Jernsmede.", d="Inde i hvælvingen finder du en tavle, der beskriver vilkårene i en fredstraktat mellem dværgeklanerne Bronzeskæg og Vildhammer. Den synes at stamme fra tiden lige efter Krigen om De Tre Hamre og er med stor sandsynlighed et bemærkelsesværdigt stykke dværgisk historie. Kongen af Jernsmede ville uden tvivl være interesseret i denne artefakt."},
  [98427] = {n="Driften Standses", l="Bring Skovrydder-nøglen til Morin Skyjæger uden for Blodhov-landsbyen.", d="Flishuggeren, som en af siderne taler om--jeg har set dem før på mine rejser. De kan nedlægge en skov på en brøkdel af den tid, som hånd og økse kan.\n\nHele lysninger--hjem for Jordmoderens børn i årtusinder--udslettet på få dage.\n\nVi vil ikke tillade, at det sker i vores hjem, et stenkast fra dér, hvor vores unge tager deres første skridt.\n\n<Name>, jeg må bede dig samle andre, gå tilbage ind i minen mod nordøst og sørge for, at den ikke fælder et eneste træ mere."},
  [98459] = {n="En Mangel på Dyd", l="Lever Toms Gave til Bart Tidevand i Menetil-havnen i Vådlandene.", d="Bart Tidevand er en uduelig gnier, siger jeg dig!\n\n\"Kaptajn på Jomfruens Dyd\" kalder han sig selv. Det skib er sejlet så langt som til en sten i Tanaris! Han er ingen kaptajn, han er en skuespiller, der vandt nok runder poker til at købe Dyden i første omgang!\n\nHvis du nogensinde kommer til Menetil-havnen i Vådlandene, så giv ham dette og fortæl ham, at det er fra gamle Halvfisk.\n\nDer er i øvrigt en båd herfra, der kan føre dig lige til havnen. Det bliver det andet stop!\n\nOg han snyder i poker!"},
  [98461] = {n="Ubesvaret Kærlighed", l="Lever Hulles Seddel til Tarrel Stenvæver nær Menetil-havnen i Vådlandene.", d="Hvis du er på vej ud fra Auberdin, kunne jeg bruge din hjælp!\n\nMin kære ven Tarrel og jeg var klassekammerater i skolen. Åh, han var sådan en hurtigtænkende på alt, der hed udgravning! Vi blev adskilt efter eksamen--han til Vådlandene, og jeg hertil i Mørkekysten.\n\n<Hulle sukker, og så rynker hendes pande let.>\n\nUndskyld, og hans kone... Merrin.\n\nDet betyder ikke noget. Hvis du tager til Vådlandene, kunne du så sørge for, at han har det godt? Og måske give ham dette her? Han er sikkert nær Menetil-havnen. Der er en båd lige derhen."},
  [98463] = {n="Snak i Byen", l="Besøg Nixxrax Krusfylder i Salte Sømandskro i Bytteviken i Kvælerdorn.", d="Se, jeg er glad for at have dig i min bar, og netop derfor fortæller jeg dig det her.\n\nDet rigtige selskab? Det foregår nede i Salte Sømandskro i Bytteviken. Ja, i Kvælerdorn-dalen--den Bytteviken.\n\nKig ikke sådan på mig. Jeg ved, at den drives af goblins. Bartendere snakker, og baggæster snakker MEGET. Alt, hvad jeg siger, er, at hvis du vil se tingene blive helt vilde, så tag derhen.\n\nNixxrax Krusfylder holder dig påfyldt, bare rolig."},
  [98512] = {n="Al'Aketh-snigmordere", l="Dræb 10 Al'Aketh-snigmordere i Shen'dar-højlandet.", d="Du dér, fremmede. Hold dig lavt og hold mund. Vi er ikke alene her.\n\nJeg var på patrulje nær grænsen og bemærkede, at der er et antal Al'Aketh, der sniger rundt om huset lige oppe ad bakken dér mod nord. Jeg ved ikke, hvad de laver her, men det kan ikke være godt.\n\nHvis du vil gøre dig nyttig, så gå derind og tag dem ud. Jeg venter her og holder øje med din ryg."},
  [98545] = {n="Leonids Brev", l="Lever det Forseglede Brev til Glix Klikklak i Undergrunden.", d="Når du nu er her, vil jeg gerne have, at du leverer dette brev til en gammel ven af mig i Undergrunden. Jeg ville selv levere det, men jeg har en noget farverig historie med Den Mørke Dame, og det ville være bedre, hvis en neutral tredjepart stod for leveringen.\n\nDu leder efter en goblin ved navn Glix Klikklak i Handelskvarteret i Undergrunden. Jeg er sikker på, at han gerne vil betale dig for din tid.\n\n<Leonid udstøder en lav latter, mens han rækker dig brevet.>"},
  [98574] = {n="Helliget Memorandum", l="Læs det Helliget Memorandum og tal med Brandstok Khalder i Ambolmar.", d="Mens du hjalp mig, blev dette memorandum givet til mig, så jeg kunne videregive det til dig. Tag dig tid til at læse det, når du har lejlighed. Jeg regner med, at det kom fra præsteinstruktøren Brandstok. Kig lidt på det, og find ham inde i Ambolmar, når du har tid."},
  [98575] = {n="Besmittet Tavle", l="Læs den Besmittede Tavle og tal med Nartok inde i Hulen i Prøvernes Dal.", d="Ah, mens du var væk, kom der en tavle til dig, <Name>.\n\nJeg holder mig normalt fra hekseri, hvis jeg kan undgå det, men jeg synes, du bør læse den, når du har tid. Hvis jeg ikke tager fejl, kom den fra din nyudnævnte instruktør, Nartok. Han vil gerne tale med dig, når du er klar."},
  [98581] = {n="Arkaisk Rune", l="Læs den Arkaiske Rune og tal med Teo Hammerdyn i Ambolmar.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du har lejlighed. Ud fra Vildhammer-stilen i disse indskrifter regner jeg med, at den kom fra shamaninstruktøren Teo Hammerdyn. Kig lidt på den, og find ham inde i Ambolmar, når du har tid."},
  [98601] = {n="En Svær Vej", l="Læs den Indviede Rulle og tal med Aramis Hammerhånd i kirken i Dødsklokken.", d="Mens du var ude og tog dig af den tankeløse Svøben, ankom denne rulle til dig. Den udstråler lyset, så jeg forestiller mig, at den er af en vis betydning for en paladin som dig selv.\n\nLæs den, før du drager af sted igen. Bare vær venlig--træd et skridt væk, når du gør det. Paladiner gør mig ret urolig."},
  [98738] = {n="Velsignelser fra Den Store Vindbårne Katteånd", d="Nu hvor du har modtaget min velsignelse, så vend tilbage til Dendrit. Han vil instruere dig yderligere.\n\nDesværre har jeg lidt tilbage at lære dig for øjeblikket. Jeg håber virkelig, du kommer og besøger mig i Vindras igen en dag. Jeg ser løfte i dig, unge shen'dorei.\n\nMåtte skyggerne skjule dig for evigt, dine fjender falde let for dine klør, og vinden lede dine skridt."},
  [98739] = {n="Velsignelser fra Den Store Katteånd", l="Tal med Dendrit.", d="Nu hvor du har modtaget min velsignelse, så vend tilbage til Dendrit. Han vil instruere dig yderligere. Jeg håber, vi mødes igen en dag.\n\nMåtte skyggerne skjule dig for evigt, og dine fjender falde let for dine klør, unge ven."},
  [98815] = {n="Højlandshuder", l="Returnér 4 Krat-raptor-huder til James Garver, garveren, i Menetil-havnen.", d="Højlandene er hjemsted for en slags ruiner, hemmeligheder som nu udforskes af et ekspeditionshold. Det, jeg ved, er, at de har deres eget dyreliv og bæster, der lurer i den bjergagtige mosesump. Hvad med, at du tager en tur derind med nogle veludrustede venner, så laver vi en handel?\n\nJeg er ligeglad med, om de gemmer sig, jeg vil have deres huder! Bring mig skindene fra fire af Krat-raptorerne, så får jeg en handel i stand, der gør det umagen værd."},
  [98823] = {n="Jordens Ekko", l="Bring Titan-relikvien til Muln Jordvrede på Himmelvagtens Plateau i det nordvestlige Mulgorr.", d="Sandelig, dette er et fascinerende objekt.\n\nDet viser tegn på at være langt mere end et simpelt udskåret værk eller en skulptur.\n\nMens vores ældste måske er interesserede i at iagttage denne artefakt, er det Jordringen, der bedst kan rumme visdommen om vores begravede ruiner og glemte lande. Find Muln Jordvrede; en direkte tilgang passer til alvoren i det, du bærer.\n\nDu kan finde ham og andre ældste fra Jordringens råd på Himmelvagtens Plateau i det nordvestlige Mulgorr."},
  [98824] = {n="Forhistorisk Prisme", l="Bring Titan-relikvien til Høj Opdagelsesrejsende Magellas i Opdagelsesrejsendes Hal i Jernsmede.", d="Med titanlignende indskrifter som dem på dens facetter er intet mindre end Opdagelsesrejsendes Hal i Jernsmede det rette sted at bringe den.\n\nJeg vil gerne tro, at du vil blive nævnt i historien for det i kataloget--\"Fundet af <Name>! Bekræftet af Prospektor Whelgar...\" Ah, jeg lader mig rive med.\n\nHøj Opdagelsesrejsende Magellas vil tage imod dig, og givet den udsøgte natur af det, du bærer, vil han sikkert være meget taknemmelig, hvis du donerer den til museet.\n\nFint fund!"},
  [98887] = {n="Konflikt ved Mørkspyd-øerne", l="Bring 3 Mørkspyd-øernes Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Theramore-ekspeditionsstyrken er seje og bliver ved med at sende forstærkninger for at styrke deres position på Mørkspyd-øerne.\n\nGå hen og vis dem Hordens magt! Bring mig beviset på din sejr på dette afgørende slagmarksområde, så bliver du rigeligt belønnet."},
  [98895] = {n="Sammenstød på Mørkspyd-øerne", l="Bring 3 Mørkspyd-øernes Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Kampen mod Mørkspyd-plyndrerne bliver hedere. Uden hurtig hjælp vil Mørkspyd-øerne gå tabt for os.\n\nDet er din pligt som stolt medlem af Alliancen at sikre, at det ikke sker. Bring mig bevis på dine bidrag på frontlinjen, så bliver du æret som en helt for Alliancen!"},
  [98896] = {n="Sammenstød på Mørkspyd-øerne"},
  [98903] = {n="Slaget om Mørkspyd-øerne!", l="Vind et slag på Mørkspyd-øerne og vend tilbage til Brelinda Makfarri på Nordvagt-borgen.", d="Gå frem og repræsentér Theramore-ekspeditionsstyrken i kamp på Mørkspyd-øerne, <Name>! Opnå sejr og vis de Horde-hunde Alliancens magt!"},
  [98906] = {n="Slaget om Mørkspyd-øerne!", l="Vind et slag på Mørkspyd-øerne og vend tilbage til Nizook Bøf på Handelskysten.", d="Slaget på Mørkspyd-øerne er kørt fast i en patthed, <Class>. Vis de Alliance-tosser, hvilken styrke der er den overlegne.\n\nBær hovedet højt i Mørkspyd-tjeneste og gør krav på sejren i kamp. Loaerne vil helt sikkert give dig deres velsignelse, <Class>!"},
  [99046] = {n="Den Tabte Løber", l="Søg efter Vagt Eralya Bladskygge på vejen mod Orakellunden.", d="Skovrådet sendte for et stykke tid siden en lille gruppe vagter til Orakeltræet. Træet sender beskeder til vores ældste, og det er vores opgave at bringe dem sikkert til Darnassos.\n\nJeg har fået besked om, at vores seneste løber endnu ikke er ankommet. Orakelets beskeder varierer i hyppighed, men denne gang har der gået usædvanligt lang tid.\n\nTag venligst mod vest ad vejen mod Orakellunden og tjek til hende. Det skulle have været Eralya Bladskygges tur, og hun er stadig under oplæring. Må Elune lede dig."},
  [99048] = {n="En Savnet Hånd", l="Find Heglan Skyggeøje nord for Tiragarde-fæstningen.", d="Et medlem af Den Splittede Hånd, en gruppe af mere... subtile kæmpere, holdt øje med Tiragarde-fæstningen på afstand. Hendes rapporter stoppede pludselig med at komme.\n\nJeg tvivler på, at menneskerne ville have fanget hende, så jeg er bekymret for, at noget farligere er på spil. Se om du kan finde hende. Forhåbentlig er beskederne bare forsinkede."},
  [99049] = {n="Trussel fra Undergrunden", l="Find tegn på hvad der angreb Heglan Skyggeøje.", d="Området i nærheden er ødelagt med tydelige tegn på et sammenstød. Det, der overfaldt Heglan, slap ikke ustraffet. Der er sikkert tegn i nærheden på, hvad der skete.\n\nOrgnil vil nok gerne se alt det bevis, angriberne har efterladt."},
  [99051] = {n="Trussel fra Undergrunden", l="Saml 9 Slangefolk-rygfinner.", d="Det ville ikke være første gang, de slanger generede os. De skal lære, at deres tilstedeværelse ikke tolereres her.\n\nFind hvor deres spejdere slår lejr, og slagt dem. Bring mig deres finner tilbage som bevis. Vi må handle hurtigt for at sikre, at de forstår det."},
  [99052] = {n="Trussel fra Undergrunden", l="Dræb havjætten langs Durdotars nordkyst og bring bevis på din bedrift tilbage.", d="En af mine spejdere har rapporteret, at en havjætte fulgte slangefolkene herned. Ved ikke, om de bragte ham med vilje eller hvad, men han er under alle omstændigheder farlig.\n\nDet er en ung en, men den kunne rive en ork midt over på et øjeblik, hvis den blev overrumplet. Jeg skal have ham væk. Men jeg vil foreslå, at du finder noget hjælp til at klare ham."},
  [99123] = {n="Tabt i Skyggerne", l="Hjælp Pal'jøh med at flygte fra Kolkar-klippen og bring nyheden om din succes til Mester Vornal i Sen'jin-landsbyen.", d="Jeg besluttede at lave lidt spejderarbejde i klippen på egen hånd. Desværre løb min magi tør på det forkerte tidspunkt, og jeg har været fanget her og gemt mig lige siden.\n\nHvis du kunne hjælpe mig med at flygte, ville jeg sætte stor pris på det."},
  [99127] = {n="En Net-katastrofe", l="Tjek fiskegarnene i Krystalsøen.", d="Fiskene bider bare ikke i dag, og der er noget galt med dem. Det er ikke bare tomme kroge. Jeg har ikke set en eneste lille fisk oppe i vandet overhovedet.\n\nLii herovre satte nogle fælder op i nat. Gå og tjek, om vi i det mindste har fået noget lager dér. Hvis du finder noget mærkeligt, så sørg for at vise mig det."},
  [99128] = {n="Slimet Trussel", l="Dræb 7 Mudderfisk og 4 Mudderfisk-bækløbere ved Krystalsøen, og vend derefter tilbage til Jason Mætters.", d="Det kan kun være mudderfiskenes værk på den anden side af søen. De er afskyelige små væsner med et ondskabsfuldt temperament og tænder til at matche.\n\nHvis vi lader det fortsætte, vil der ikke være nogen fisk at tale om nogen steder i denne sø. Hvis du kunne rydde dem lidt ud, ville det hjælpe mig enormt."},
  [99129] = {n="En Mand Om en Mudderfisk", l="Tal med Remy \"Tosidet\" om Jasons mudderfisk-problemer.", d="Remy nævnte mudderfisk den anden dag... Jeg er ret sikker på, at han hader de små skiderikker lige så meget som jeg gør.\n\nHan har måske nogle idéer til, hvordan vi kan holde dem væk fra min fisk fremover. Jeg vil gerne bede dig om at gå og snakke med ham og se, om han kan komme i tanke om noget."},
  [99130] = {n="Et Fristende Tilbud", l="Saml 6 Glas med dyreblod og 18 Skumringsukrudtsblade til mudderfisk-agn, og vend derefter tilbage til Remy \"Tosidet\" i Guldshire.", d="Jeg har et par idéer til, hvordan vi kan tackle mudderfisk. Og en af dem hjælper også nogle andre i processen.\n\nDer er et ukrudt, der ofte findes på gårde i området, kaldet skumringsukrudt, og i store mængder er bladene giftige for de fleste dyr. Hvis vi laver mudderfisk-agn af planten, kan vi forhåbentlig lære disse væsner at holde sig væk.\n\nOg nogle bønder får ryddet deres marker i processen. Virkelig en win-win... virkelig en win-win."},
  [99134] = {n="Disciplin", l="Straf 5 Dødevagter for Eksekutor Zygant.", d="Du er ikke medlem af Dødevagten, og derfor har du endnu ikke skuffet mig.\n\nSom belønning for din relative mangel på inkompetence skal du straffe dem, der har vist sådanne evner i overskud.\n\nSkynd dig nu--<Name>, hedder du?--ellers tilføjer jeg dit navn til min protokol, så en anden kan få belønningen."},
  [99141] = {n="Tålmodighed", l="Hent rapporter fra Dødevagt Dillinger, Dødevagt Kristof og Storhånd til Eksekutor Zygant.", d="Lad ingen tvivl herom, <Class>--Den Mørke Dame kræver den perfekte udførelse af hendes vilje. Som Eksekutor er det min pligt at sikre, at dette sker.\n\nRapporter fra flere af mine Dødevagter er forsinkede. Det er unødvendigt at sige, at min tålmodighed er ved at være opbrugt. Hent deres rapporter og bring dem til mig i Den Mørke Dames navn.\n\nDu finder Dødevagt Dillinger lige vest for her, ved kirkegården. Dødevagt Kristof er stationeret ved rastestedet mod øst. Og tjek til abominationen Storhånd; han vandrer mod vest nær Stillevandsdammen."},
  [99142] = {n="Gravukrudt", l="Saml 5 Gravukrudt og lever dem tilbage til Juniorapoteker Holland.", d="Hvis du er på vej mod øst, mod Balnirs Gård, har jeg mere, du kunne gøre for mig. Gode hjælpere er så svære at finde i disse dage, som dit sammenstød med Storhånd så tydeligt illustrerer.\n\nNår jeg skaffer dommeukrudt, udfører jeg nogle mindre alkymistiske ændringer og genplanter dem på gården for at dyrke min ultimative skabelse. Jeg kalder den gravukrudt, og den skal være herold for min herlige skæbne.\n\nHold øje med Svøben i området, mens du er der. De virker... tiltrukket... af ukrudtet. Nysgerrigt."},
  [99143] = {n="Flasker og Fnuller", l="Saml 6 stykker blankt skrammel fra den nærliggende mudderfisk-lejr.", d="De fiskemænd må tænke som rigtige fisk, ikke? Hvilket betyder, at alt, hvad de kan lide, vil fisk også kunne lide!\n\nHvis du roder lidt i deres skrammel og vender tilbage til mig med noget, der virker som god agn, belønner jeg dig."},
  [99144] = {n="At Søge Tilflugt", l="Hjælp Bareth Morgensten med at flygte fra Korsfarer-forposten, og rapportér hans sikkerhed til Shari Stilvæg i Gryde-by.", d="Lys velsigne dig, fordi du fandt mig. Jeg var på vej fra Bandarion-borgen for at levere en besked til Shari Stilvæg i Gryde-by, da disse monstre tog mig til fange. De bruger Lyset med et had i hjerterne, der får det, der er tilbage af mit blod, til at syde. Det går imod alt, jeg mediterer over... alt, jeg stræber efter at beskytte!\n\n<Bareth Morgensten stabiliserer sig selv.>\n\nJeg ved, at nogle stadig har et problem med mit folk, men jeg forsikrer dig om, at vores hensigter er rene. Hvis du vil hjælpe mig med at flygte herfra, vil jeg være dig evigt taknemmelig."},
  [99152] = {n="Som Ovenover, Så Nedenunder", l="Saml 6 svagt lysende knogler til Hilda Knuseren.", d="Mens de Plettede i Skyggedalen mod sydvest helt bestemt er et problem, kan vi ikke tillade, at kældrene under byen vokser sig til et fuldskala Svøbe-oprør på Bandarion-borgen.\n\nJeg må gøre disse elever klar, hvis det sker. Men du skal få, hvad jeg kan lide at kalde et crashkursus.\n\nRejs under Skyggedalen og hent nogle af deres ussle knogler, så vi kan studere dem nærmere. Jeg har brug for dem, der stadig beholder noget af den oprindelige genoplivningsmagi--dem der lyser."},
  [99153] = {n="Den Der Slap Væk", l="Find det Skjulte Krystalfragment under Skyggedalen til Efram Barbaro.", d="Hey, du! Ordet spreder sig hurtigt blandt vores rækker. Jeg hørte om det arbejde, du udførte med kultisterne omkring resterne af slaget med Naxxrammas.\n\nProblemet er, at en af kultisterne slap væk med et stykke af fokuseringskrystallen. Den ser ud til stadig at have noget saft i sig. Vores bedste gæt er, at den er et sted under Skyggedalen. Enten rejser den dem fra de døde eller gør dem stærkere, og du vil ikke have nogen af delene.\n\nFind krystallen, før det her udvikler sig for meget."},
  [99156] = {n="Bagvagtspatrulje", l="Bring Rivtands Hjerte til Dødevagt Lindea.", d="Pokker også! En ny rapport kom ind, mens du var på patrulje. Der er set en udisciplineret abomination, der vandrer rundt i de østlige Tirisfals Lysninger, nær Giftspindel-dalen.\n\nNoget er galt. Abominationer sniger sig ikke bare forbi Bolværket uopdaget.\n\nHold denne sag på et strengt behov-for-at-vide-grundlag. Når det er sagt, vil sådan et væsen ikke falde let; du får brug for allierede, hvis du vil være mere end dets næste måltid.\n\nFør dette til ende, og du bliver behørigt belønnet. Bring mig dets hjerte som bevis på gerningen."},
  [99158] = {n="Daggry i Bjergene", l="Bring kassen med stearinlys til Fader Gavin ved Tågefyr-fristedet.", d="Der er en præst derude i bjergene, som hører til en organisation, der kaldes Sølvdæmringen. De er en hellig gruppe, dedikeret til at finde og ødelægge det uhellige og unaturlige.\n\nFader Gavin derimod er mest den type, der søger at hjælpe og helbrede alle i stedet for at tage et våben. Han har sat en gammel bygning i stand til at tjene som hvilested for rejsende og kaldt den Tågefyr-fristedet. Jeg har en forsendelse hellige stearinlys, som jeg skal have til ham. Kunne du bringe dem til ham, hvis du alligevel skal den vej?"},
  [99159] = {n="At Finde Varme", l="Saml 14 stykker brænde.", d="Mit pejsested står åbent for at varme enhver sjæl, men jeg vil gerne bede dig om at hjælpe mig, hvis du kunne.\n\nJeg har simpelthen brug for mere brænde. Det er noget, jeg normalt ville gøre selv, men jeg har været optaget af andre opgaver."},
  [99160] = {n="Rimfrostens Vrede", l="Dræb 10 mindre iselementarer.", d="Du har sikkert bemærket elementarerne i nærheden. En klippe af sten og is faldt ned fra bjergtoppene for et par dage siden og vækkede dem.\n\nDisse frosne bjerge er allerede farlige for den gennemsnitlige dværg eller menneske, uden at elementerne har antaget form. Jeg er ikke en kriger længere--så enhver af de ånder, du kan dræbe, vil hjælpe med at gøre vejen tryggere."},
  [99161] = {n="Rimfrostens Vrede", l="Dræb Isgyden og hent dens kerne.", d="Jeg har bemærket, at det første elementar, der dukkede op efter stenskredet, var større end sine artsfæller. Og så vidt jeg kan se, har det været kilden til lejlighedsvise vejrskift og andre mindre skred.\n\nJeg har kaldt det 'Isgyden'. Hvis du dræber det og henter kernen som bevis, vil jeg belønne dig."},
  [99162] = {n="Forræderisk Kulde", l="Saml geværerne fra faldne bjergbestigere.", d="Selv bjergbestigere fra Jernsmede må holde hovedet koldt, når de krydser toppene i Dun Frostbakke. Faldende sne og is betyder ofte enden for nogle af de mere uerfarne medlemmers liv.\n\nEfter et skred prøver jeg normalt at finde tegn på overlevende eller ofre--mens jeg beder til Lyset om, at der ikke er noget at finde. Men med elementerne i oprør har jeg holdt mig fra at vandre for langt væk. Hvis du kunne lede efter nogle af de fortabte bjergbestigere og bringe mig deres geværer, vil jeg returnere dem til Jernsmede."},
  [99191] = {n="En Uldgave"},
  [99196] = {n="En Uldgave"},
  [99197] = {n="En Silkegave"},
  [99260] = {n="Filøns Missionen", l="Tal med Elaadrin Aftenvind i Valanår.", d="Jeg fik til opgave at hente vigtige data om strømmen af elementar-energi fra Udsigtens Rejsesten. Disse data er afgørende for vores planer om at rejse sikkert mellem Himmelmuren og Azerot. Uden de data til at hjælpe vores beregninger vil vores forsøg på at styre vores skæresejlskibe gennem elementarplanet mislykkes.\n\nDataene er sandsynligvis tabt nu, og jeg er ikke i stand til at forsøge at samle dem igen. Jeg fortalte Den Højeste Magister om din rolle i at redde mig, og han ønsker at tale med dig igen."},
  [99411] = {n="Kjeld er forsvundet!", l="Ahab Hvedehov i Blodhov-landsbyen i Mulgorr vil have dig til at fodre hans elskede hvalp, Kjeld den Rasende.\n\nFodr Kjeld med mørt Vandrerkød, og vend tilbage til Ahab Hvedehov.", d="Hjælp, <Name>! Min elskede hvalp, Kjeld, er løbet væk! Jeg ved bare, at han løber rundt i Blodhov-landsbyen, fortabt og sulten.\n\nVil du finde ham og fodre ham? Når han har spist, vil han falde til ro og komme hjem.\n\nFor at fodre ham skal du finde mad. Hans yndlingsmåltid er mørt vandrerkød. Tag bare østpå, så burde du finde masser af vandrere. Jag en af dem, og tag dens saftige kød til Kjeld. Når du ser Kjeld i byen, så læg kødet fra dig, og han vil helt sikkert komme hen til dig."},
  [26] = {n="En Lektie at Lære", l="Tal med Dendrit Stjerneblus i landsbyen Nathavn, Månelunden.", d="<Name>, jeg har fulgt dine fremskridt med stor glæde. Du er med sikkerhed ved at udvikle dig til en værdsat beskytter af naturen.\n\nTiden er kommet til, at du lærer mere om et af de mange dyreaspekter, som Cenarus har velsignet os med evnen til at skifte til – et, der giver dig herredømme over vandet. Til dette skal du rejse til landsbyen Nathavn i Månelunden og tale med Dendrit Stjerneblus fra Cenarion-kredsen dernede. Han vil vejlede dig videre."},
  [257] = {n="En Jægers Brag", l="Dræb 6 Bjergmusvåger og vend tilbage til Daryl Ungkarl i Fjernvandrer-logen inden for 15 minutter.", d="Tror du, du kan måle dig med Daryl den Modige, hva'? Det tror jeg ikke! Selvfølgelig er du mere end velkommen til at prøve. Her er en udfordring, der burde vise sig at være over dine evner, så tag det ikke for hårdt, hvis du ikke tør kaste dig ud i den.\n\nEn flok musvåger har slået sig ned her i Modansøen. Hvorfor prøver du ikke at fælde nogle af dyrene? Sådan er det: Klarer du min udfordring på femten minutter, giver jeg dig min bue eller mit gevær.\n\n<Han kigger dig nedladende over.>\n\nDet ser ud til, at du alligevel ikke har meget at tabe."},
  [309] = {n="Beskyttelse af Forsendelsen", l="Sørg for, at Mirran og forsendelsen når frem til udgravningsstedet, og informer derefter Prospektor Jernbånd.", d="Klar til at gå, <Name>?\n\nFørst skal vi have det her pulver til Jernbånd. Det bliver for meget for mig at bære, og disse dele kan være farlige -- og hvem ved, hvad Mørkjernsdværgene ellers har planlagt for mig.\n\nJeg vil få det meget bedre, hvis du kommer med."},
  [486] = {n="Ursal Lemlæster", l="Dræb Ursal Lemlæster og vend tilbage til Athridas Bjørnekappe i Dolanår.", d="Nu er tiden kommet til at redde Klo-druiderne. Hvis vi fejler nu, <Name>, vil de for evigt gå tabt i søvnen.\n\nJeg skal forberede Vækkelsens Relikvier og udføre ritualet. For at mit arbejde kan virke, skal det forbandede udyr, der står bag denne forfærdelige situation, slås ihjel. Først da er ritualet fuldendt.\n\nDet var Ursal Lemlæster, der blandede sig i vores brødres kaldelse, og det er Ursal Lemlæster, der nu må betale, så de kan blive befriet. Rejs til Knudefyr-fæstningen i sydvest og slå ham ihjel."},
  [931] = {n="Den Glimtende Vifte", l="Bring en Glimtende Vifte til Denalan ved Al'Ameth-søen", d="Viftene på denne plante glimter i skovens lys og giver den en snoende, pulserende glorie.\n\nDu tror, at Denalan vil ønske et eksemplar af dette."},
  [935] = {n="Jordens Krone", l="Bring det Fyldte Kar til Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Uden Alexstraszas, Livbinderens, og Nosdormus, den Tidløses, velsignelser har Teldrasils vækst ikke været uden fejl. Der er blevet rapporteret om underlige udyr, der dukker op af trærnes egen jord, og gale pelsbolge angriber rejsende.\n\nJeg kan kun håbe, at løsningen, Ærkedruiden leder efter, bliver fundet hurtigt. Jeg hælder alle fiolerne, du bragte, i dette kar, så du kan levere det til Darnassos.\n\nBring det til Fandrel Hjorthelm; du finder ham i druidelunden."},
  [940] = {n="Teldrasil", l="Lever den Indgraverede Bark til Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Skoven hvisker om dine heltedåd, <Name>. Da jeg mærkede harpyerne blive drevet fra deres reder, spredte en større ro sig over skoven, og dens skabninger følte sig igen trygge. Jeg har frygtet at sende endnu en budbringer til Ærkedruiden, men jeg ved, at du vil bringe min besked sikkert frem til ham.\n\nLever dette til ham, og vid at skoven vil følge dig sikkert ad sine stier til stenskoven."},
  [955] = {n="Bashalhand", l="Skaf 8 Grelle-ørering til Asterion i Bashalhand.", d="Hvis jeg skulle fortælle om mit liv, tvivler jeg ikke på, at det ville overgå grænserne for dit tålmod. Lad os sige, at mit har været et langt og smertefuldt liv, og denne spøgelsesagtige skikkelse er måske den værste pine af dem alle.\n\nJeg holdes fanget her ved hjælp af magi. Selvom mine ord måske virker uoprigtige, forsikrer jeg dig om, at jeg ville være utrolig taknemmelig, hvis du ville hjælpe mig med at finde en måde at komme ud af min fængsling på. Et segl binder mig, og ved at undersøge fe-væsnernes og grellernes ørepynt kan jeg måske finde et spor af det."},
  [956] = {n="Bashalhand", l="Skaf det Oldtidens Månestensegl og bring det til Asterion i Bashalhand.", d="Hvis grellerne er kommet i tæt kontakt med seglet, der binder mit evige fængsel, har jeg en fornemmelse af, hvad årsagen er. Uden tvivl er seglet havnet i besiddelse af satyren, der førte dem an.\n\nJeg tror stærkt på, at dette må være sandt, <Name>. En af satyrerne må helt sikkert have det. Hvis du kan skaffe det, bringer du mig så tæt på at komme gennem mit fængsels stænger, at tårerne ville springe mig i øjnene."},
  [983] = {n="Summekasse 827", l="Saml 6 Kryberben og placer dem i Summekasse 827.", d="Hej! Hjælp mig med min seneste opfindelse, summekassen. Du kan tale med folk langt væk!\n\nDe har måske allerede set dem, de er kasser med håndtag på. Det eneste problem er, at de kræver konstant vedligeholdelse.\n\nHver enkelt har et andet problem, men jeg tog en virkelig klog beslutning. Jeg placerede hver enkelt i nærheden af væsner, der har de rette dele til at reparere netop den maskine. Lige nu er Summekasse 827 i stykker. Den ligger lige syd for Auberdin, rigtig tæt på. Det kræver 6 Kryberben at reparere den. Jeg betaler dig ..."},
  [1073] = {n="Inkompetence + Kemikalier = Sjov", l="Bring 4 Mindre Manaeliksirer og 2 Eliksirer af Mindre Sejhed til Lomac Tandstrimmel i Jernsmede.", d="Hahaha... du skal bruge Nitromirglycerium for at stoppe goblinerne i at ødelægge en skov?!\n\nJeg er ligeglad med, om du kender Gaxim eller ej... Jeg giver dig tingene, bare for at se dig eller dem eksplodere i små-bitte stykker.\n\nDer er bare et problem: Jeg er helt tør.\n\nMen jeg siger dig, bring mig de rigtige eliksirer, så laver jeg nogle til dig med det samme.\n\nDet mindste, du kan gøre, er at bevise, at du har en vis dygtighed som alkymist, før jeg bare giver dig en prøve af mit største mesterværk."},
  [1076] = {n="Djævle i Vestfald", l="Bring Støvdjævl-skrammel til Collin Mørbrod i Stormvind.", d="Ah, jeg tror, jeg har det. En besked-besværgelse... Jeg tror, det er den effekt, han leder efter.\n\nJeg bliver nødt til at lave en rulle med besværgelsen indprentet på. Til det skal jeg bruge skrammel fra en støvdjævl.\n\nMens jeg samler resten af komponenterne, hvorfor tager du så ikke til Vestfald og finder en af de onde skabninger? De er farlige, men jeg er sikker på, at det ikke er noget, du ikke kan klare, hvis du er villig til at underkaste dig et af Gaxims eksperimenter.\n\nJeg venter her, når du kommer tilbage."},
  [1143] = {n="Althalaxx' Tårn", l="Dræb Atrikus Narassin og bring hans hoved til Balthule Skyggestød nær Althalaxx' Tårn.", d="Jeg forstår. Nå, hvis det, du siger, er sandt, så er tiden kommet til at slå til. Jeg tror, at Atrikus holder til øverst i tårnet. Vær dog forsigtig, han er omgivet af mange mægtige hekseriksere, langt farligere end dem, du mødte før."},
  [1658] = {n="Brasende ind i Kurvemand-festivalen", l="Find De Forladtes Kurvemand-festival i Tirisfal-lysningen. Vend tilbage til Sergent Hartman i Sydstranden, når du har gjort det.", d="Jeg har brug for modige individer, der kan tage op til Tirisfal-lysningen og undersøge Kurvemand-festivalen. Jeg vil ikke lyve – at tage derop vil være farligt. Vagterne ved festivalen vil være usædvanligt ondskabsfulde. Alligevel har vi brug for at vide, hvor stor festivalen er i år, og hvor meget ballade De Forladte vil forårsage os under Helligaftens Ende.\n\nHvis du har lyst, så tag til Tirisfal og spejd festivalen af. Vend tilbage til mig med oplysningerne, så sørger jeg for, at du bliver godt belønnet."},
  [1698] = {n="Yorus Byggøl", l="Tal med Yorus Byggøl.", d="Yorus Byggøl har udfordret alle dygtige krigere i Alliancen. Han venter på Søshire-kroen i Rødryg og lover en stor belønning til den, der kan klare hans prøve."},
  [2118] = {n="Pestplagede Lande", l="Erobr en levende Rasende Tistelbjørn og bring den tilbage til Tharnarium.\n\nSkulle du undlade at erobre en Rasende Tistelbjørn og miste din fælde, så vend tilbage til Tharnarium Træpasser og bed om en ny fælde.", d="En sygdom breder sig over Mørkekysten og griber fat i sindet og kroppen på alt, den rører ved.\n\nTistelbjørnene er blevet hårdest ramt af denne pest. De engang ædle dyr er nu et redskab for ødelæggelse – rasende og ophidsede. Jeg har måske en kur mod denne lidelse.\n\nTag denne fælde med ud i skoven og læg den på jorden. Enhver Rasende Tistelbjørn, der krydser lyset, bliver fredelig i et kort stykke tid. Når bjørnen er fredelig, vil den følge dig. Bly den tilbage hertil, <Name>."},
  [2281] = {n="Stævnemøde i Rødryg", l="Begiv dig til Søshire i Rødryg-bjergene og tal med Lusius.", d="At sende dig ud i felten nu ville være selvmord. Renzik har ikke brug for endnu en død kriminel på sine hænder. Bare rolig, <Name> – Renzik skal nok få dig op i tempo.\n\nBegiv dig til Rødryg-bjergene og tal med en medarbejder af SI:Syv ved navn Lusius. Du vil finde ham hængende ved havnen i Søshire sammen med de andre tvivlsomme nytteløse typer."},
  [2282] = {n="Alters Mølle", l="Åbn Lusius' Låsekasse, find Tyveriets Mærke og bring det tilbage til Lusius i Søshire.", d="Vi har trænet tyve her i årevis! For ikke alle slyngler bliver født med den nåde og finesse, som gamle Lusius har.\n\nOppe fra vejen her finder du Alters Mølle. Jeg har en kiste deroppe med noget vigtigt indeni. Gå og hent den til mig! Bring mærket tilbage, så får du dit Certifikat for Tyveri!"},
  [2499] = {n="Egetrutz", l="Denalan ved Al'Ameth-søen vil have dig til at indsamle den gigantiske tumor fra Egetrutz.", d="I en hule langs søens sydlige bred spreder en træling ved navn Egetrutz korruption til alle de væsner, der har Al'Ameth-søen som hjem.\n\nJeg turde ikke komme for tæt på, men selv på afstand er det tydeligt: Egetrutz bliver forgiftet af den største tumor, jeg nogensinde har set... Jeg ville endda kalde den gigantisk.\n\n<Name>, du har allerede gjort meget for at hjælpe mine bestræbelser, men jeg beder dig om én opgave mere. Jag Egetrutz ned og indsaml tumoren; fjern denne kilde til korruption fra mit hjem."},
  [2520] = {n="Sathrahs Offer", l="Præstinde A'moora vil have dig til at placere Lady Sathrahs sølvglinsende spindeorganer ved springvandet inde i templet og derefter vende tilbage til hende.", d="Nu skal du færdiggøre den opgave, du er blevet tildelt. Tag spindeorganerne og offer Lady Sathrahs offer til Elunie; læg den store edderkop til hvile.\n\nInde i dette tempel skal du finde det centrale springvand. Det er dér, du kan efterlade offeret. De hellige vande vil rense og udrense korruptionen, der drev Sathrah til vanvid.\n\nNår du har gjort dette, så vend tilbage til mig."},
  [2607] = {n="Zanzils Berøring", l="Tal med Doktor Mixilpixil i kælderen under Kasernen.", d="Det ser ud til, at du har bragt mere information tilbage, end selv jeg havde forventet. Dette er bestemt en mærkelig vending, <Name>.\n\nEn kur? Hm... Gå ned i kælderen og tal med Doktor Mixilpixil – han kan måske hjælpe."},
  [2608] = {n="Zanzils Berøring", l="/Læg dig ned, så Doktor Mixilpixil kan undersøge dig. Hvordan skal han finde kuren, hvis han ikke kan finde årsagen?", d="Åh nej, du ser ud som døden selv. Rettelse – jeg har set døden, og du ser værre ud end døden. Du, herre/frue, ville være det, døden hostede op ved sin sidste lægetjek.\n\nHa! Hører du det, Uarm? Skriv det ned!\n\n*Host* Hm, ja, for at jeg kan hjælpe dig, bliver jeg nødt til at tappe lidt blod. Bare rolig, det gør kun ondt de første... halvtreds gange eller deromkring... /Læg dig ned, når du er klar til behandlingen, <Name>."},
  [4761] = {n="Thundris Vindvæver", l="Tal med Thundris Vindvæver i Auberdin.", d="Din spejding af pelsbolgelejren er information, som Thundris Vindvæver bør få at vide. Han tjener nådigt som Auberdins ældste og tilbyder klog og retfærdig forvaltning af landsbyens daglige anliggender. Del venligst dine fund indtil nu om pelsbolg-situationen med ham.\n\nJeg tror, at han har sine egne idéer om årsagerne til deres korruption. Måske kan du arbejde sammen med ham om at iværksætte en plan for at genoprette naturens balance her!"},
  [6121] = {n="Lektioner på Ny", l="Rejs til Månelunden og tal med Dendrit Stjerneblus i landsbyen Nathavn.", d="Du er nu klar til at lære om gift og den magt, vi druider har over det, <Name>. Cenarus har velsignet os med evnen til at rense selv de mest grumme giftstoffer med blot en besværgelse. Denne gave må ikke tages let... og for at sikre, at du lærer denne lektion, skal du arbejde med at håndtere virkningerne af forgiftninger, som en lægmand ville.\n\nRejs til Månelunden og tal med Dendrit Stjerneblus; han venter på din ankomst for at begynde din lektion."},
  [8373] = {n="Fyrkraften", l="Brug et Stinkbombe-rensemiddel til at fjerne enhver De Forladtes Stinkbombe, der er blevet tabt i Sydstranden. Vend tilbage til Sergent Hartman i Sydstranden, når du er færdig.", d="Det, jeg hader mest ved Helligaftens Ende, er de stinkbomber, De Forladte bruger i Sydstranden. Hvem kunne vide, at fejringen af befrielse skulle indebære sådan et stinkende rod?\n\nUnder Helligaftens Ende skal du bruge dette rensemiddel til at fjerne enhver ubehagelig stinkbombe, Horden måtte slippe her i landsbyen. Det bruger fyrrens kraft til at bekæmpe skumle lugte.\n\nGør din del for at holde Sydstranden ren, så giver jeg dig nogle Helligaftens Ende-lækkerier, som jeg er sikker på, du vil nyde. Er vi enige?"},
  [86758] = {n="Vrid Kniven", l="Find og besejr krokoliskken Dolkfang, og bring Marks kniv tilbage.", d="Har jeg nogensinde fortalt dig, hvordan jeg næsten mistede min hånd til en krokolisk? Fik proppet min kniv ned i dens kæbe og kravlede hurtigt ud. Jeg troede, at jeg havde kniven liggende et sted herude, men jeg kan ikke finde den.\n\nUnder alle omstændigheder er den krokolisk sikkert stadig derude og jager langs søens kant. Det hidsige udyr må nok væk, af hensyn til de andre jægere, hvis ikke af andet.\n\nJeg har fundet på at kalde den Dolkfang. Hvis du ser den, så giv den en venlig hilsen fra mig! Og med \"hilsen\" mener jeg \"stik.\""},
  [96044] = {n="Lejrliv 101: Smedning", l="Tal med Tognar Flintild i Kharanøs for at lære at fremstille et lejrudstyr til dit erhverv, når du har vist din dygtighed i færdigheden.", d="Så, du er blevet smed. Det er et fint valg, hvis du vil sikre, at dine klinger aldrig bliver sløve.\n\nJeg regner med, at jeg kender en, der kan hjælpe med det ved at lære dig at fremstille en slibesten. Tag en af dem med ud til din lejr, så står alle krigere og lystyve i området i kø for at slibe deres våben."},
  [96606] = {n="Det Store Udendørs", l="Sid nær Lyrinas Simple Lejrbål, og vent, til du modtager Forstærket Hvile-buffen.", d="Hilsen, <Class>. Jeg kan se, at du har et eventyrerudseende over dig. Det er godt. Verden har brug for flere af os rastløse sjæle, der søger lykke og ære.\n\nDu skal lære at trives i vildmarken for at få succes i dette job. Jeg ved ikke, hvordan dine udendørsfærdigheder er, men jeg kan nok lære dig et og andet, hvis du er villig til at lære.\n\nSæt dig ved bålet og gør dig komfortabel. Jeg viser dig vej."},
  [96779] = {n="Syndikat-sabotage", l="Find Lord Tomat inde i Durnholde-fæstningen i Hillsbrad-forbjergene, og dræb ham. Vend derefter tilbage til Myrokos Tavskikkelse.", d="Nogle gange, <Race>, kan et enkelt snit på det rigtige sted fælde en fjende. Det samme gælder ofte for organisationer.\n\nVores agenter har identificeret et nøglemål blandt Syndikatets rækker: en mand ved navn Lord Tomat.\n\nHan spiller en afgørende rolle i driften af Durnholde-fæstningen i Hillsbrad-forbjergene. Hvis du ønsker at være til nytte for Ravnehold, så tag til Durnholde og eliminér ham. Jo hurtigere, og jo mere stille, desto bedre."},
  [96782] = {n="Hemmelig Udtrækning", l="Find Klingen fra Hus Pæreknold og den Kongelige Ægis fra Pæreknold blandt ruinerne af Alterac. Bring dem derefter til Myrokos Tavskikkelse.", d="Det ser ud til, at vores ven Bartøn her har gjort det meget nemt for os. Han er ude efter to arvestykker fra Pæreknold-familien inde i ruinerne af Alterac. Klingen fra Hus Pæreknold, et sværd, og den Kongelige Ægis fra Pæreknold, et skjold.\n\nIfølge rapporten ligger disse våben i to tårne blandt ruinerne. Det er bedst, at vi får fat i dem, før Syndikatet gør.\n\nOgrerne, der holder til i ruinerne, er vilde, men jeg stoler på, at du kan snige dig forbi dem uden at skulle sætte dit blad i blod overhovedet."},
  [96785] = {n="Ingen Anelse", l="Find noget i Strømgård-fæstningen, der kan overbevise Anastasia om at afgive detaljerne om den hemmelige aftale.", d="Hvem tror du, at du er? At dukke op og stikke næsen ind i officielle anliggender.\n\nJeg fortæller ikke en nybegynder noget om de højerestående folks forretninger uden god grund. Medmindre du har noget vigtigt eller værdifuldt til mig, har jeg intet at sige til dig."},
  [96786] = {n="Syndikatets Brod", l="Bryd den hemmelige aftale op, og tag varen, der handles, med til Syndikatet. Vend derefter tilbage til Myrokos Tavskikkelse i Ravnehold-herregården.", d="Falkekrone sendte nogle fyre for at lave en overlevering ved den sydlige del af Torradins mur. Jeg ved ikke, hvad de henter. Må være godt, for alle involverede har holdt det en fuldstændig hemmelighed. Jeg tror ikke engang, at fyrene, der henter det, ved, hvad det er.\n\nDet er alt, jeg ved. Gør mig ikke ked af, at jeg fortalte dig det."},
  [98046] = {n="Jordens Krone", l="Bring det Drænede Kar til Larina i Månens Tempel i Darnassos.", d="<Ærkedruide Fandrel Hjorthelms blik smalner.>\n\nEr du stadig her?\n\nTag fiolen og forsvind fra mit syn, <Class>. Det er klart, at mine svar ikke ligger i vandet, ligesom de ikke gjorde før.\n\nMåske kan en af præstinderne i Månens Tempel mod syd gøre sig af med den.\n\n<Fandrel ser væk og taler ikke længere til dig.>\n\nJeg må lede andetsteds, hvis dette skal lykkes..."},
  [98065] = {n="Jordens Krone", l="Bring Månebrøndsresterne til Tyrande Hviskevind i Månens Tempel i Darnassos.", d="Du skal bringe dette til Tyrande med det samme! Jeg overfører det til en mere ceremoniel beholder til dig.\n\nVær ikke bange. Elunies Højpræstinde er fast, men venlig. Hun beskytter alle, der træder ind i Darnassos, og bærer vores gudindes lys ud til alle.\n\nHun vil være glad for at modtage dette hellige vand. Du finder hende lige over os."},
  [98731] = {n="Velsignelser fra den Store Katteånd", l="Tal med Dendrit.", d="Nu hvor du har modtaget min velsignelse, så vend tilbage til Dendrit. Han vil instruere dig yderligere. Jeg håber virkelig, at vi møder hinanden igen en dag.\n\nMåtte skyggerne skjule dig for evigt, og må dine fjender let falde til dine klør, unge."},
  [99050] = {n="Det Store Træ Forsyner", l="Saml 6 Duggede Pisker-vifter, et Tomt Hætteglas og et Forfriskende Kildevand til Byanzie i Dolanår.", d="Jeg får brug for din hjælp til at skaffe de ingredienser, jeg skal bruge for at standse sygdommen længe nok til, at Eralya kan vende tilbage hertil for yderligere behandling.\n\nHeldigvis er vores levende hjem stadig rigt, og det vil forsyne os i vores nødstid.\n\nDen centrale ingrediens er duggede pisker-vifter. Du finder dem omkring Al'Ameth-søen lige syd for her, eller Brøndsøen og dens flod mod nordvest.\n\nDertil skal jeg bruge et tomt hætteglas og noget kildevand. Begge dele kan købes her i byen eller byttes til."},
  [99053] = {n="Flugten fra Ban'ethil", l="Hjælp Vagt Lynessa Skumringsblomst med at flygte fra Ban'ethil-gravhulen, og rapporter hendes sikkerhed til Vagt Kyra Stjernesang i Dolanår.", d="Mine bønner er blevet besvaret! Jeg er taknemmelig for, at du har kæmpet dig vej herned.\n\nJeg blev sendt hertil af Orakeltræet for at levere en besked til de sovende druider her, kun for at finde stedet fuldstændig overrendt af pelsbolge! De overfaldt mig, før jeg kunne vende tilbage, og bragte mig hertil ned--jeg frygter for deres næste måltid.\n\nJeg ved ikke med dig, men jeg afskyr dette sted. Under jorden er ikke et sted for kaldorei."},
  [99073] = {n="Lindring af Lidelse", l="Tag Piskevandssalven til Vagt Eralya Bladskygge på vejen til Orakeltræet.", d="Salven er klar. Tag den med til Eralya med det samme.\n\nJeg ved ikke, om den virkelig vil kurere hende. Råden spreder sig hurtigt og vokser i styrke, jo mere den breder sig.\n\nDen vil i hvert fald lindre hendes lidelse. Og det er stadig din hast værd."},
  [99131] = {n="Lokket til Succes", l="Vend tilbage til Jason Mætters.", d="Fortæl Mætters, at han kan komme og hente lokkemaden senere i dag. Jeg giver ham en gennemgang af den rette brug.\n\nForhåbentlig kan han snart sælge sin fisk igen. Og så får vi færre mudderfisk i verden."},
  [10] = {n="Skrimshank-forløsningen", l="Find ud af skæbnen for Junior-landmåler Skrimshank, og bring enten ham eller hans landmålingsudstyr til Senior-landmåler Snurrebrus i Gadgetbyen.", d="Åh, det her er bare forfærdeligt! Jeg sendte min bedste assistent, Junior-landmåler Skrimshank, ud i ørkenen sydøst herfra. Det er et område, vi kalder Den Gabende Kløft. Nå, han er forsvundet, og hans sidste rapport havde flere af de mærkelige biller, der var dér, hvor han var. Kan det være, at de nu har inficeret to store områder af ørkenen?\n\nJeg har brug for, at du tager ind i Den Gabende Kløft og leder efter Skrimshank, tak! Det... eller i det mindste find hans landmålingsudstyr. Jeg frygter, at det kan være alt, der er tilbage af den stakkels fyr.", p="Nå, hvilke nyheder har du? Du ser ud, som om du har været i en ordentlig kamp... er Skrimshank i live?", c="Han var en god kobold, unge Skrimshank. Lad os håbe, at hans død ikke var forgæves, med det han kunne optegne med sit landmålingsudstyr.\n\nDet ser ud til, at vi har en ret vanskelig situation på hånden her med disse biller. De er alt for snedige til deres eget bedste, og den forskning, vi har lavet indtil nu, tyder på, at de måske endda er under kontrol af en tredje part! Hvis det er tilfældet, så varsler det ikke godt for kun Gadgetbyen, men for hele ørkenen!"},
  [17] = {n="Uldaman-reagensløbet", l="Bring 12 Magentafarvede Svampehætter til Ghak Helbredsberøring i Thelsamar.", d="Jeg har hørt om en nyopdaget plante, der kaldes magentafarvede svampehætter. De vokser i klynger, dybt inde i Uldaman-udgravningen; de kan måske findes andre steder, men lige nu er det det eneste sted, jeg kender til. Jeg vil undersøge deres potentiale i alkymi, og det er her, du kommer ind i billedet.\n\nFind klyngerne af magentafarvede hætter og bring mig et dusin af dem. Vær advaret, klyngerne kan sprøjte giftige sporer ud, hvis de bliver rystet.\n\nGør det for mig, så laver jeg en omgang af en af mine berømte helbredende eliksirer til dig!", p="Har du fået de magentafarvede svampehætter, jeg har brug for til mit alkymiske arbejde? Ingen hætter - ingen belønning!", c="Godt gået, <Name>, du har endnu engang bevist din værdi! Hætterne bliver et interessant studie, sandelig!\n\nOg nu, som lovet, nyd en smag af en af mine kraftigere helbredende brygninger fra mit personlige lager...\n\nHvis du er en dygtig alkymist, så har vi måske noget mere forretning at gøre. Uanset hvad, takker jeg for din hjælp!"},
  [32] = {n="Silitidernes Opstigning", l="Tag rapporten med til Zilzibin Trommelærdom i Orgrimgrad.", d="Her er din rapport. Jeg opfordrer dig til at tage den med til en, der måske har praktisk viden om den slags ting.\n\nJeg kender en trolde-lærd ved navn Zilzibin Trommelærdom. Han har brugt en masse tid på at studere livsformer, der er unikke for Azeroths økologi; han er desuden historiker! Hvis du vil have nogen til at hjælpe med at finde ud af, hvad denne trussel præcis er, og hvordan man stopper den, så giv ham denne rapport. Vi får brug for al den hjælp, vi kan få.\n\nZil bor i et hus på den anden etage af Drag'en i Orgrimgrad.", p="Jeg beklager, jeg kender dig ikke... men ud fra udseendet har du i det mindste hørt noget om mig. Hvad kan jeg hjælpe dig med? Har du noget til mig?", c="Denne rapport... jeg har tidligere haft med disse udyr at gøre. Snurrebrus var klog, da han sendte denne og dig til mig.\n\nDisse væsener vil hurtigt fortære Tanarisørknen; de er uden tvivl en af de største trusler, vi nogensinde vil stå over for. Gør dig bekendt med dette navn, <Name>: silitid. Insekterne, der nævnes her, er silitiderne, og de er redskaberne for en af de største trusler, både Horden og Alliancen står over for.\n\nHvis vi bare havde været kloge nok til at se det før."},
  [48] = {n="Sød Rav", l="Bring Hellig Kildevand til Grimsøl Tordenbryg.", d="I landet mod syd, hvor ranker snor sig og slynger\nLigger en skjult brønd, hvor vandet er dybt og tynger\nRent som Lysets hellige Datter\nBring mig nu noget Hellig Kildevand.", p="Hik! Ho ho! Vil du have en ekstra runde?\n\nI landet mod syd, hvor ranker snor sig og slynger\nLigger en skjult brønd, hvor vandet er dybt og tynger\nRent som Lysets hellige Datter\nBring mig nu noget Hellig Kildevand.", c="Hik! Ho ho!"},
  [49] = {n="Sød Rav", l="Grimsøl Tordenbryg vil have en sæk Byg, en sæk Rug og en sæk Majs.", d="Rav er nuancen af mit livs længste kærlighed\nSom skumringens sidste gløder på himlen ovenfor\nHent det for mig, så min kærlighed kan fødes\nEn sæk af hver: byg, rug og majs.", p="Ekstra? Ja, selvfølgelig!\n\nRav er nuancen af mit livs længste kærlighed\nSom skumringens sidste gløder på himlen ovenfor\nHent det for mig, så min kærlighed kan fødes\nEn sæk af hver: byg, rug og majs.", c="Hik! Ho ho!"},
  [50] = {n="Sød Rav", l="Grimsøl Tordenbryg vil have Ægte Sølv.", d="Jeg blander og blander, til vi har en mæskning\nDet her skal blive vores eget private lager\nEt destilleringsapparat skal smedes af stærkt metal\nBring mig noget Ægte Sølv, så jeg kan fuldende denne sang.", p="En ekstra runde til dig? Ja da, ven!\n\nJeg blander og blander, til vi har en mæskning\nDet her skal blive vores eget private lager\nEt destilleringsapparat skal smedes af stærkt metal\nBring mig noget Ægte Sølv, så jeg kan fuldende denne sang.", c="Hik! Ho ho!"},
  [51] = {n="Sød Rav", l="Bring en Platangren til Grimsøl Tordenbryg.", d="Endnu ikke filtreret, men friskt destilleret\nSom ubesået jord, der venter på at blive harvet.\nNæste gang vil jeg lave vores bunke træ-kul\nLever en platangren, det er dit næste mål.", p="En ekstra runde? Hvorfor ikke for dig, alt!\n\nEndnu ikke filtreret, men friskt destilleret\nSom ubesået jord, der venter på at blive harvet.\nNæste gang vil jeg lave vores bunke træ-kul\nLever en platangren, det er dit næste mål.", c="Hik! Ho ho!"},
  [53] = {n="Sød Rav", l="Bring Grimsøl Tordenbryg et bundt Forkullet Eg.", d="Melodiøs væske, klar som et barns tårer\nBliver over årene til en smuk, dyb rav\nMen før vi går videre for at blive helt fuld\nSkal der bygges en tønde af forkullet eg.", p="Selvfølgelig synger jeg den igen for dig, ven!\n\nMelodiøs væske, klar som et barns tårer\nBliver over årene til en smuk, dyb rav\nMen før vi går videre for at blive helt fuld\nSkal der bygges en tønde af forkullet eg.", c="Lagret i tønden, filtreret gennem kul\nDen glider over dine læber og ned i din sjæl.\nSå lad os drikke nu, en skål for dig\nOg for mig, mens vi er i gang, Grimsøl Tordenbryg!"},
  [77] = {n="Et klistret problem", l="Hent 10 flasker Bagland Honningrippel fra kasserne, der ligger rundt om den forladte Horde-base i Lurerklippen.", d="Jeg har originale emballagematerialer til den rippel, Dran Droffers søger. Jeg vil hjælpe dig med at pakke rippelen til Maltons irriterende far... for et gebyr på to ekstra flasker af nævnte rippel. De ligger i kasser, der findes i den forladte Horde-base nær Lurerklippen.\n\nDet bliver en besværlig opgave, nemlig: ulækre slimer og slimvæsener vil klæbe til ruinerne; ryget har det, at de er ledet af en slags mester-slimvæsen. Uanset hvad, så skaf rippelen og kom tilbage til mig her for indpakning.", p="Jeg går ud fra, at din ankomst her til vores lejr skyldes, at du leverer de flasker rippel, der er afgørende for opgaven, ikke sandt?", c="Fint udført, <Name>. Jeg er glad for, at du var klog nok til ikke at ramme delikatessen af rippel. Der er intet værre end aromaen af rippel, der unødigt er blevet rystet rundt.\n\nDet vil tage et øjeblik, før magien er udført over denne dyrebare last. Egentlig er der ingen magi involveret; jeg har blot nogle tomme emballager til Bagland Honningrippel. Vores snyderi skal forvandle disse flasker til en alkoholisk skat for tidernes øjne.\n\nFremad - for god sprut!"},
  [81] = {n="Rippel-leverancen", l="Lever tønden til Dran Droffers i Orgrimgrad.", d="Jeg har taget det ekstra skridt at sikre ikke kun Drans indpakkede rippel i tønden, men også de ekstra flasker rippel, han sniger sig til. Selvom jeg ikke har så høj en mening om Dran, er der intet værre end rystet rippel. Det var så lidt.\n\nLever nu den tønde dér til Dran Droffers i hans bjærgningsemporium i Orgrimgrad. Sig venligst, at jeg sender mine varmeste hilsner til Malton; lad ham vide, at hvis han nogensinde tørster efter fin drik og endnu finere drikkekammerater, ville vi være i ære ved hans besøg.", p="Hvis du ikke er her for at købe noget, og du ikke er her for at levere noget, så spilder du min tid! Du må hellere have den rippel!", c="Nå, lad os se, hvad der er i tønden!\n\nJa, ja, det ser ud til, at det hele er her. Her er din betaling for pakken, godt gået med den. Jeg tjener fem gange det beløb, når jeg sælger den til kroen! Har har!\n\nDisse ekstra flasker Bagland Honningrippel skal gemmes til en særlig lejlighed. Jeg tror, jeg drikker nogle med champagne. Jeg kalder den... champirippel."},
  [82] = {n="Undersøgelsen af Den Giftige Hule", l="Bring fem Hundredepar-insektdele fra Den Giftige Hule til Alkymist Pestlezugg i Gadgetbyen.", d="Nå ja, disse rapporter om billerne... det, vi ved, er, at de dræner vandpytterne, der engang lå dér, hvor Den Giftige Hule er nu. Det, vi IKKE ved, er, ja, alt det andet.\n\nLad os finde ud af, hvem vores fjende er først! Jeg vil have dig til at tage ind i Den Giftige Hule og hente nogle dele fra de skabninger. Hent fem fra Hundredeparret dér og bring dem til Alkymist Pestlezugg, så han kan tøffe med dem. Når han har fat i sagen, finder vi ud af, hvad de er!", p="Du er Junior-landmåler <Name>, ikke? Skynd dig nu, der er en alvorlig situation på hånden! Har du de insektdele, som Snurrebrus sagde, du ville have?!", c="Godt arbejde - jeg går i gang med min analyse af dem nu! Jeg kan dog med det samme fortælle dig, at de ligner ingen insektform, jeg nogensinde har set. Det er næsten, som om disse biller bliver styret af en udefra kommende kraft eller noget.\n\nDu skal gå og tale med Snurrebrus med det samme; der er tilsyneladende en nødsituation, han har brug for din hjælp til, på stedet! Jeg er ikke sikker, men jeg tror, det drejer sig om flere af billerne i Tanarisørknen!"},
  [96] = {n="Vandets Kald", l="Bring Vandskåret til Isleif Vandseer i Ødemarken.", d="Tag skåret. Tag skåret og giv liv.\n\nGiv liv og forstå. Forstå, at vand er liv... fordærvelse standser liv.\n\nDu beskytter og giver liv med vandets kraft.", p="Du er vendt tilbage. Storartet!\n\nHvordan gik din rejse til Sølvfyrreskoven? Tog det lang tid?\n\nDet er svært for mig at afgøre, om du var succesfuld derude, for så meget af landet er blevet fordærvet. Dens stank overvælder al det gode, du måske har gjort. Men små sejre er nogle gange lige så vigtige som store. At rense vandet derude var afgørende for dig og for alle shamaner.", c="Dette er beviset, jeg bad om. Du har gjort det godt, <Name>.\n\nJeg er glad for at være den første til at lykønske dig og give dig dette... din vandtotem.\n\nBrug den godt, og held og lykke.\n\nDin næste prøve kommer ikke om lang tid, så lær dine lektioner godt. Rent vand vil ikke bare give liv tilbage til dem, der er såret, men kan have mange andre effekter. Jeg foreslår, at du opsøger en shamanlærer, når du har tid. De har måske andre besværgelser, du kan lære."},
  [100] = {n="Vandets Kald", l="Tal med den Mindre Manifestation af Vand i Sølvfyrreskoven.", d="Lys eksploderer, da du fuldender besværgelsen. Lyden af vanddråber, der rammer ilden, har lagt sig, og dine sanser overvældes, mens de fordærvede ånder omkring dig bliver ødelagt.", c="Takket være dig. Takket være shamanerne.\n\nFordærvelsen ebber ud, men livet visner stadig. Det er op til shamanerne at beskytte livet."},
  [105] = {n="Ak, Andorhøj", l="Bring Arajs Phylakteriskår til Over-eksekutor Derrington ved Bolværket, Vestlige Pestlande.", d="Ak, tiden er kommet til at angribe Andorhøj og drive den liche ud, der kontrollerer den!\n\nInde i byens ruiner er det, at liche - Araj Fremkalderen - har herredømme. Han er bevogtet af talrige fra Pesten, der omringer rester af byens centrum, og hans personlige følge af vagter, der er knyttet direkte til ham, er formidabel. Du får brug for talrige allierede for overhovedet at have en chance for at møde ham med succes.\n\nDræb Araj, <Name>, og bring mig et skår fra hans phylakteri som bevis!", p="Din opgave er blevet givet til dig, <Name>. Har du et skår fra likets phylakteri som bevis på, at opgaven er udført?", c="Du har gjort det! Araj... liche er endelig besejret!\n\nDu har gjort en enorm tjeneste for Horden på denne dag, <Name>. Dit mod og din udholdenhed er et vidnesbyrd om, hvad det betyder at være en sand helt. Vær venlig at tage imod dette, så alle kan se og vide, at du har givet Horden en sejr for tidernes øjne!"},
  [110] = {n="Insektdelanalyse", l="Tjek i Gadgetbyen hos Alkymist Pestlezugg og hans analyse af insektdelene.", d="Jeg vil bruge noget tid på at kigge på Snurrebrus' landmålingsudstyr... og på at bringe hans personlige ejendele i orden. Jeg har en snigende fornemmelse bag ørerne, at dette ikke er det sidste tab, vi vil lide i kampen mod disse biller.\n\nJeg vil gerne have, at du tjekker ind hos Alkymist Pestlezugg for at se, om han har haft mulighed for at bearbejde de insektdele, vi sendte ham. Hvis de er klar, så bring dem til mig.", c="Ja, jeg har resultaterne lige her. De er... foruroligende, for at sige det mildt\n\nVores indledende mistanke om, at billerne styres af en udefra kommende kraft, mener vi, er korrekt. Hvis det er tilfældet, så har vi at gøre med ikke kun en meget kraftfuld, ukendt magt, men også en ondartet én. Disse biller er blevet ændret til rene hærgere. Jeg har aldrig set noget lignende."},
  [113] = {n="Insektdelanalyse", l="Lever rapporten til Senior-landmåler Snurrebrus i Gadgetbyen. Sørg for, at han giver dig en kopi af rapporten, som Alkymist Pestlezugg har bedt om.", d="Senior-landmåler Snurrebrus skal se denne rapport med det samme. Faktisk... alle, der kan læse, skal se denne rapport. Vi står over for en alvorlig og kritisk trussel, ikke kun mod Tanarisørknen og Gadgetbyen, men hvis den ikke bliver standset, hele det sydlige Kalimdor. Ja, muligvis endda hele Azeroth; denne ting har ikke vist tegn på at aftage.\n\nLad Snurrebrus lave en kopi af rapporten til dig, så du frit kan uddele den til dine allierede. Alle må vide om denne trussel!", p="Nå, Junior-landmåler <Name>, har den gamle Pestlezugg fået rapporten klar endnu?", c="Tak for at levere rapporten, Junior-landmåler <Name>; her er din løn for din flittige tjeneste for Gadgetbyens Vandselskab.\n\nSelvom jeg normalt ikke er begejstret for at give vores værdifulde information uden videre til dem, der ellers ville betale god mønt for den, har jeg kendt Pestlezugg i en del år nu. Hvis han anbefaler, at alle får at vide det, så lad det være. Giv mig et øjeblik, så laver jeg en kopi til dig."},
  [123] = {n="Samleren", l="Gå til Marskal Dughan i Guldshire og giv ham Samlerens Tidsplan", d="Dette notat er en tidsplan med en liste over dage og tidspunkter, hvor en person -- kun beskrevet som \"Samleren\" -- vil modtage en forsendelse af guld fra minerne i Elwynnskoven.\n\nUd fra tidsplanen ser det ud til, at Samleren bor nær Brackvolds Græskarplads i det østlige Elvendal.\n\nDette lyder vigtigt. Du bør rapportere det til Marskal Dughan i Guldshire.", p="Hvad?!? Vi har ikke haft vores folk til at arbejde i Elwynn-minerne i flere måneder!\n\nLad mig se det notat, du har...", c="Hm... jeg har hørt om denne \"Samler\", men jeg ved ikke, hvem han arbejder for. Tak for tidsplanen. Den vil hjælpe os med at løse denne gåde."},
  [162] = {n="Silitidernes Opstigning", l="Tag Insektanalyserapporten til Gracina Åndsmagt i Darnassos.", d="Jeg opfordrer dig til at tage denne rapport til en, der har praktisk viden om den slags ting.\n\nJeg kender denne nattenisse-lærde ved navn Gracina Åndsmagt. Hun har brugt en masse tid på at studere livsformer, der er unikke for Azeroths økologi; hun er desuden historiker! Hvis du vil have nogen til at hjælpe med at finde ud af, hvad denne trussel præcis er, og endnu vigtigere, hvordan man stopper den, så giv hende rapporten. Vi får brug for hjælpen.\n\nSidst jeg hørte, boede hun i Månetemplet i Darnassos.", p="Fred og ro være med dig, fremmede. Hvorfor har du opsøgt mig i dag?", c="Denne rapport... vi nattealfer kender til den rædsel, der nævnes her. Snurrebrus var klog, da han sendte denne og dig til mig.\n\nDisse væsener vil hurtigt fortære Tanarisørknen; de er uden tvivl en af de største trusler, vi nogensinde vil stå over for. Gør dig bekendt med dette navn, <Name>: silitid. Insekterne, der nævnes her, er silitiderne, og de er redskaberne for en af de største trusler, både Horden og Alliancen står over for.\n\nHvis vi bare havde været kloge nok til at se det før."},
  [171] = {n="En Vogter af Alliancen", l="Returner din beskyttede til Stormvindsbørnehjemmet ved at aflevere den Menneskelige Forældreløsfløjte til Børnehjemsmoderen Nattergal i Katedralkvarteret.", d="Du har været så utrolig venlig mod mig, <Name>. Jeg havde aldrig drømt om, at jeg ville have så meget sjov under Børnenes Uge. Tak. Jeg vil ikke være ked af det, der er sket med mig og det hele - mine forældre fortalte mig altid, at jeg skulle komme over alt det dårlige, der sker. Du ved, når jeg bliver stor, vil jeg være en helt... ligesom dig.\n\nDet er trist at sige, men det er tid for mig at tage hjem. Lad os gå tilbage, så fortæller jeg matronen, hvilken fantastisk person du er!", p="Det er en fornøjelse at se dig igen, <Name>. Har du passet de opgaver, du meldte dig til under Børnenes Uge?", c="Må himlen velsigne dig, <Name>. Du har gjort mere for Randis, end de fleste nogensinde ville drømme om at gøre for ham. Tak - du er en lysende stjerne på Alliancens himmel.\n\nVær sød - hvis du kan undvære tiden, så kom tilbage og besøg os. Jeg ved, at Randis gerne vil det, og det vil jeg også.\n\nRandis havde så meget sjov med dig, <Name>. Han ville gerne give dig et af sine yndlingskæledyr, så du husker ham."},
  [172] = {n="Børnenes Uge", l="Brug den Orkiske Forældreløsfløjte til at tale med barnet, du skal passe under Børnenes Uge.", d="Vil du gerne hjælpe os her på børnehjemmet? Velsign dig, ven; din hjælp under Børnenes Uge vil være uvurderlig.\n\nTag denne fløjte. Du vil kun kunne bruge den i kort tid - typisk ikke længere end selve Børnenes Uge. Når du bruger den, kan du tale med barnet, du har accepteret at passe. Bruger du den igen, vil barnet blive afskediget.\n\nVær så god, <Name> - brug fløjten og mød din beskyttede! Jeg er sikker på, at barnet vil være ivrigt efter at møde dig.", c="Zug zug! Jeg hedder Grunth, og jeg gætter på, at du passer på mig? Du er en eventyrer, ligesom min mor og far var. Min matrone siger, at de døde med ære i kamp. Jeg er glad for at møde dig.\n\nJeg håber, vi kommer til at lave en masse ting sammen. Jeg har nogle ting, jeg gerne vil lave, og matronen siger, at du bliver som en storebror for mig i denne uge. Det vil jeg rigtig gerne."},
  [198] = {n="Forsyninger til Menig Thorsen", l="Lever de Diverse Nisse-forsyninger til Menig Thorsen.", d="Hmm. Ja, jeg har faktisk noget, du kunne gøre. Løjtnant Døren og hans folk oppe i nord har brug for deres regelmæssige forsyninger fra os.\n\nDe er ikke blevet leveret, og med trolderne i angreb får jeg brug for nogen til at gøre det. Dørens lejr ligger nordvest for vejen ved indgangen til Kvælertorn fra Skumringsskoven. Giv forsyningerne til Menig Thorsen; hvis han ikke er i lejren, så patruljerer han sydpå. Han tager sig af dem.\n\nHusk, hvis du fejler, skylder du mig erstatning.", p="Ja? Hvad vil du? Åh, forsyninger fra kobolderne. Mærkeligt at se en <Race> levere dem, normalt sender de deres egne. Det gør ikke noget... du rørte dem vel ikke? Godt, godt... vi ville ikke have, at noget skete med vores landminer, åh nej.", c="Disse landminer vil hjælpe os med at forsvare os mod det dyr Kortsen og hans mænd. Tak fordi du bragte dem. Hvis du har brug for mere arbejde, kan jeg nok finde noget til dig. Og du behøver ikke at have med de kobolder at gøre, hm?"},
  [199] = {n="En mørk trussel truer", l="Vend tilbage til Overingeniør Hinderweir og vis ham det spor, du har opdaget.", d="Du tager en prøve af det mærkeligt lugtende pulver.", p="Opdagede du nogen spor, <Name>?", c="Dette er en alarmerende opdagelse, for at sige det mildt!"},
  [200] = {n="Bookmager Herod", l="Find Bookmager Herods Optegnelser.", d="Hvis Kortsen kender Thorsens hemmelighed, så har vi en spion blandt os. Vi må finde ud af, hvordan hemmeligheden blev lækket!\n\nThorsens kontakt i Kortsens lejr var Bookmager Herod. Herod er Kortsens logistikofficer og ved alt om driften af Kortsens Blanding. Hvis du kan få fat i Herods noter eller optegnelser, kan vi måske finde ud af, hvordan Thorsen blev opdaget.\n\nDa vi stadig var sammen med Kortsen, lå bookmagerens kontor på øverste etage i lejrens eneste to-etagers hus. Hans optegnelser er sikkert stadig der.", c="Dette er Bookmager Herods noter og optegnelser.\n\nBlandt dem er: en liste over forsyninger i lejren, materialeanmodninger fra Oberst Kortsen og forskellige breve og korrespondancer."},
  [202] = {n="Oberst Kortsen", l="Dræb 6 Kortsen Elite, 4 Kortsen-underhøvdinge, og bring Kortsens Hoved til Løjtnant Døren i Oprørslejren.", d="Du har bevist dig selv igen og igen, og din opfindsomhed synes at kunne måle sig med selveste Kortsens. Du kan være vores bandes frelse... hvis du kan måle dig med Kortsen og sejre!\n\nHan kommanderer sine mænd fra dybt inde i Lagerhulen. Du skal gå ind i den hule, trodse hans forsvarere og møde Kortsen og hans ledere.\n\nFarvel, <Name>. Mit håb og mændenes skæbne følger med dig.", p="Tør jeg håbe, at Kortsen og hans forsvarere er døde, <Name>?", c="Jeg turde ikke tro rapporterne, men du bringer os bevis på, at... Kortsen og hans ledere er besejret. Du har reddet os!\n\nDisse jungler er fyldt med trusler af alle slags, men ingen havde Kortsens grusomme intellekt. Vi kan alle trække vejret lettere nu, hvor han er væk."},
  [203] = {n="Det Andet Oprør", l="Dræb 15 Kortsen Vildnis-kæmpere.\n\nVend tilbage til Sergent Yohwa i Oprørslejren.", d="Vi kæmper en tabt kamp mod Oberst Kortsen. Han er ikke kun en genial taktiker, han overgår os mindst 10 mod 1! For at overleve må vi bruge hans egne, hemmelige taktikker imod ham.\n\nGå ind i hans lejr mod øst og dræb hans mænd. Masser af dem. Og kom ud, før forstærkningerne kan lukke sig om dig.", p="Jeg håber, du har haft succes med din jagt, <Name>. Vi holder ikke længe mod ham uden din hjælp.", c="Godt gået. Tabet af de Vildnis-kæmpere vil lette noget af presset på vores lejr.\n\nMen nu hvor du har smagt de styrker, vi står over for, vil du stadig slå dig sammen med os??"},
  [204] = {n="Ringe Medicin", l="Bring 7 Vildnis-kurmidler og 1 Giftbregne-ekstrakt til Sergent Yohwa i Oprørslejren.", d="For at have en chance mod Kortsen, må vi få neutraliseret hans helende støtte. Han har samlet et stort antal Medicinmænd omkring sig, som heler hans styrker med Vildnis-kurmidler og forgifter vores kæmpere med Giftbregne-ekstrakter.\n\nVi har brug for disse kurmidler til at kurere vores eget folk, og vi har brug for en prøve af ekstrakterne til at studere, så vi kan lave vores egne kurmidler. Søg i Kortsens Blanding efter begge dele - hans Medicinmænd vil have kurmidlerne, og ekstrakterne er sikkert gemt i nogle af lejrens forsyningskasser.", p="Jeg venter på de kurmidler og den ekstrakt, <Name>.", c="Godt gjort, <Name>. Disse kurmidler vil holde flere af os i live og kampdygtige. Og ekstrakterne vil hjælpe os med at lave vores egne kurmidler."},
  [205] = {n="Trolde-hekseri", l="Bring 4 Kranieknuser-fetisher til Broder Nimetz i Oprørslejren.", d="Mens jeg studerer de legender, du har skaffet, så saml for mig redskaber til ond trollemagi. Gå ind på Kranieknuser-trollenes område, en anden stamme længere mod syd, og skaf Kranieknuser-fetisher fra deres Hekselæger og Mystikere.", p="Har du de fetisher, <Name>? De kan indeholde hemmeligheden bag Kortsens forfald... Jeg må vide det!", c="Tak. Jeg vil studere disse fetisher og se, om de rummer hemmeligheden bag Kortsens fald ind i ondskaben."},
  [206] = {n="Mai'Ondt", l="Bring Sindets Øje til Broder Nimetz i Oprørslejren.", d="Kortsen er måske død, men...det, der drev ham til ondskab, lever stadig! Gennem mine studier har jeg opdaget dette: En Oger-magiker - Mai'Ondt - bor i Ogrehøjen i de østlige bjerge i Kvælertorn. Man siger, at han bruger sindskontrollerende magi, og jeg er overbevist om, at han fordærvede Kortsen.\n\nHvis Mai'Ondt får lov at leve, kan hans ondskab påvirke andre og endda få endnu en Kortsen til at dukke op.\n\nDræb ham, og bring mig hans Sindets Øje, artefakten han bruger til at fordærve andre.", p="Jeg giver dig min velsignelse. Mai'Ondts styrke står kun mål med hans ondskab.", c="Aha! Du har gjort det! Du er en stor kraft for det gode, <Name>, og måtte din styrke aldrig svinde!\n\nJeg vil studere dette Sindets Øje og afgøre, om det kan bruges til noget godt. Hvis ikke... så må det ødelægges."},
  [207] = {n="Kortsens Gåde", l="Find de 4 tavler og bring deres legender tilbage til Broder Nimetz.", d="Oberst Kortsen var engang en stor, ædel mand - jeg må finde ud af, hvad der forårsagede hans fald ind i fordærvelse! Han kan være under trolde-magiens indflydelse. For at bekræfte dette må jeg studere nogle af deres legender.\n\nDer er 4 tavler gemt i trolderuinerne i Kvælertorn. Jeg må se, hvad der står på disse tavler! Aftegn deres mærker og bring aftegningerne tilbage til mig.\n\nDen første tavle er i Bal'lal-ruinerne, den anden er i Det Onde Rev, og den tredje og fjerde er i Zul'Bunke-ruinerne.", p="<Name>! Har du trolde-legenderne? Jeg må kende deres hemmeligheder!", c="Tak, <Name>. Jeg vil studere disse legender for at se, om der er en forbindelse mellem trollene og den ondskab, der har besat Oberst Kortsen."},
  [209] = {n="Kranieknuser-hugtænder", l="Skaf 18 Kranieknuser-hugtænder og bring dem tilbage til Kebøg.", d="Det er dyrt og besværligt at dræbe nok tigre til at forsyne eksporten af tigertænder til øerne i Sydhavet. Heldigvis har vi udviklet en teknik, der gør os i stand til at tage almindelige hornagtige genstande og forvandle dem til uopdagelige forfalskninger.\n\nDet nærmeste match, vi har fundet, er utroligt nok hugtænderne fra Kranieknuser-trollene.\n\nHør, inden du siger noget, så det køber ikke, hvad køberen ikke ved, skader dem ikke, vel? Bring mig et stort antal af dem, så vi kan gå i gang med den månedlige forsendelse!", p="Seje skiderikker, ikke? Nå, har du haft held? Undskyld, at jeg virker utålmodig, men det her har været en kæmpe torn i mit øje! Nå?", c="Åh, godt arbejde, godt arbejde! Pyh, selvom du kunne have gjort et bedre stykke arbejde med at rense af-- Nå, det gør ikke noget, det gør ikke noget! Mange tak, <Name>, vores virksomhed vil uden tvivl se øget produktion og produktivitet takket være din hjælp! Godt, godt, nu til andre sager..."},
  [210] = {n="Kraseks Madlavning", l="Bring Kraseks Krukkegryde til Krazek kobolden.", d="Jeg laver det meste af maden i lejren. Og det var engang en masse arbejde, indtil jeg købte en mekanisk kogegryde af en kobold-købmand i Bytteviken. Gryden er et vidunder! Den sparede mig for utallige timer... indtil den gik i stykker!\n\nKan du tage gryden med tilbage til kobolden, så han kan reparere den? Hans navn er Krazek.", p="Hej! Har du bragt mig noget?", c="Åh, jeg kan se, det er en Kraseks Krukkegryde! Et genialt stykke arbejde, men den kan af og til springe en fjeder eller smide et tandhjul. Lad mig se, hvad der er galt med denne...\n\nAha! Dens dampladeoplader er rusten igennem, den har en revnet knæ-pakning, og dens fobulator mangler tænder. Jeg er forbløffet over, at gryden overhovedet kan koge en majroe i denne tilstand!\n\nKan jeg reparere den? Selvfølgelig kan jeg reparere den!\n\nMen der er en pris. Åh ja, der er altid en pris..."},
  [211] = {n="Ak, Andorhøj", l="Bring Arajs Phylakteriefragment til Kommandør Ashlam Tapperhedsnæve i Kuldevind-lejren, Vestpestlandene.", d="Ak, tiden er kommet til at angribe Andorhøj og drive liken ud, der kontrollerer den!\n\nInde i byens ruiner er det, hvor liken - Araj Fremkalderen - har herredømme. Han er bevogtet af talrige af Pesten, der omkranser resterne af byens centrum, og hans personlige følge af vagter, der er knyttet direkte til ham, er formidabel. Du får brug for talrige allierede for overhovedet at have en chance for at møde ham med succes.\n\nDræb Araj, <Name>, og bring mig et fragment fra hans Phylakterie som bevis!", p="Din opgave er blevet tildelt dig, <Name>. Har du et fragment fra likens Phylakterie som bevis på, at opgaven er udført?", c="Du har gjort det! Araj... liken er endelig besejret!\n\nDu har gjort en enorm tjeneste for Alliancen i dag, <Name>. Dit mod og din udholdenhed er et bevis på, hvad det betyder at være en sand helt. Modtag venligst dette som et tegn, så alle kan se og vide, at du har givet Alliancen en sejr for tidernes skyld!"},
  [212] = {n="Et Måltid Serveret Koldt", l="Dræb en Kold Øje-basilisk, skaf et nedkølet basilisklår og bring det til Angus Strenge i Den Blå Eneboer.\n\n<Du må ikke slippe din ånd for at lykkes med denne opgave.>", d="En af mine mest berømte retter er nedkølet basilisk i limevinaigrette. Men problemet er... kødet er umuligt at holde friskt, og jeg må servere retten i aften til en adelsmands fødselsdag!\n\nSå hvis du hurtigt kan bringe mig et nedkølet basilisklår fra en nydræbt Kold Øje-basilisk, så står jeg i gæld til dig med et kongeligt gilde!\n\nKolde Øje-basilisker er kendt for at flakke rundt langs strandklitterne i det nordvestlige Kvælertorn, så du har meget rejse foran dig. Og vær hurtig!", p="<Name>! Har du det låret? Jeg må snart begynde at tilberede det, ellers bliver banketten ødelagt!", c="Ah, det her duer fint! Mange, mange tak!\n\nUndskyld mig, men nu må jeg få låret hakket, marineret og pyntet til banketten."},
  [213] = {n="Fjendtlig Overtagelse", l="Hent 8 Slebne Krystaller og bring dem tilbage til Kebøg i Bytteviken.", d="Han har gjort det denne gang! Nok ondt, at Gelris skubber magnaterne væk, som handelsprinserne havde udnævnt, nu prøver han også at skære sig ind på den berygtede pirat!\n\nRevilgas vil ikke have det, og han har bedt mig tage mig af problemet på min egen måde.\n\nMin måde? Tyveri. Venture A/S' geologer ved Nazferiti-søen er dybt interesserede i de mærkelige blå krystaller, de har fundet i minerne. Bring mig prøver af stenen fra deres geologer, jeg er ligeglad med, hvad du må gøre for at skaffe dem.", p="Jeg har brug for de sten, <Name>. Ved alle midler nødvendige! Gør det bare, og giv mig ikke detaljerne!\n\nDet handler om resultater, <Name>, intet mere, intet mindre.", c="Fascinerende. At krystallerne er blevet slebet med denne proces kan kun tyde på, at de planlægger at bruge dem som en slags brændstof eller anden katalysator. Jeg ved ikke meget mere end det. Prøverne må sendes videre til Hovedkemiker Fnisefont."},
  [215] = {n="Vildnisets Hemmeligheder", l="Tal med Løjtnant Døren i Oprørslejren.", d="Tak, fordi du reddede mig, <Name>. Jeg ved, hvordan det ser ud, men...lad mig forklare.\n\nJeg blev sat til opgave af Løjtnant Døren til at genindrulle hos Kortsens mænd, så jeg kunne spionere på dem og bringe oprørerne højst tiltrængt efterretning. Du så her, hvad jeg havde troet ville være min chance for at infiltrere Kortsens Blanding. Jeg tog fejl, og tak igen, fordi du reddede mig.\n\nDette var en strengt hemmelig mission, så du må ikke fortælle nogen om det. Men hvis du taler med Døren, vil han forklare det.", c="Ja, det Torsten fortalte dig, er sandt. Du må være diskret med dette. Engang var vi oprørere fanatisk loyale over for Oberst Kortsen. Men sådan var Kortsens fordærvelse, at vores lidenskab forvandlede sig til raseri. Hvis det blev kendt, at Menig Torsten for nylig har haft forretninger med Kortsens mænd, ville han en nat finde sig selv med en overskåret strube.\n\nSå vidt jeg ved, var kun Sergent Yohwa, Torsten og jeg indviet i Torstens mission. Men der må være en til. En forræder."},
  [220] = {n="Vandets Kald", l="Bring Hætteglasset med Det Reneste Vand til Isleif Vandseer i Ødemarken.", d="Isleif har en opgave mere til dig, før hun belønner dig med din næste totem. Hætteglasset med vand, jeg har givet dig, er nødvendigt for den opgave, uanset hvad den måtte være.\n\nGå nu og find hende. Vi må mødes igen en dag.", p="Hej igen, <Name>. Du ser godt ud.\n\nHvad fører dig tilbage til mig så hurtigt?", c="Ah, et hætteglas med vand skabt og velsignet af Saltlage, og endda indsamlet af dig.\n\nVæsken i dette hætteglas bliver nøglen til at skabe en vandamulet til dig, men den bruges også i en anden opgave.\n\nVandamuletten, jeg skaber til dig, skal bruges til at se vandånderne ved helligdommen i Sølvfyrreskoven, syd for Underbyen. De resterende dråber, ja, dem vil jeg fortælle dig om, hvis du føler dig klar.\n\nEr du forberedt på endnu en rejse, <Name>?"},
  [223] = {n="Varulve i Skoven", l="Bring Kalors seddel til Jonatan Carevin.", d="Værsgo, <Name>. Bring denne besked til Mester Carevin.\n\n<Han fjerner hurtigt et stykke falmet pergament og rækker det til dig.>\n\nEn lille håndfuld som dig mere, så overgår vi Nattevagten i antal! Måske kunne vi så fuldføre det arbejde, vi få i dag fører videre.", p="Ja, hvad er det? Vær hurtig, jeg har presserende sager at tage mig af.", c="Undskyld min kolde modtagelse, <Name>, men som du sikkert kan se, er jeg en overordentlig travl mand. Jeg kan se, at du har imponeret Kalor--og jeg forsikrer dig, at det er ingen lille bedrift--og at han har givet sin anbefaling.\n\nDer går usympatiske typer rundt, <Name>, og vi kan bruge hjælp fra alle, der har bevist sig. Vi kæmper mod dæmoner, de udøde og dem, der yder dem hjælp. Vær årvågen, vær på vagt, og stol ikke på nogen, der ikke vil yde hjælp til vores sag.\n\nHerlighed under Lyset."},
  [227] = {n="Morgan Ladimøre", l="Tal med Kommandør Althea Ebenlås i Mørkeshire.", d="<Han søger gennem hylderne og finder en læderindbundet bog.>\n\nHvis du vil vide mere, kan du spørge Althea, hun har været den, der har taget sig af... besværet... med ham på det sidste.", c="Morgan Ladimøre? Har aldrig hørt om...\n\nÅh, du mener Mor'Ladhjem! Jeg regner med, at du ikke har hørt historien?\n\nNå, jeg giver dig den korte version. En omvandrende udød, der kalder sig selv Mor'Ladhjem, har vandret rundt i Skumringsskoven. Ud fra det, vi har samlet, ser det ud til at være den udøde krop af Morgan Ladimøre, som du tilsyneladende kender. Han har forårsaget os alle mulige problemer, angrebet vagter på patrulje og dræbt folk.\n\n<Hun måler dig med blikket.>\n\nDu virker dygtig nok, måske kunne du lægge ham til hvile."},
  [229] = {n="Datteren, Der Overlevede", l="Tal med Vagtinden Sarah Ladimøre i Mørkeshire.", d="Jeg burde have fortalt dig dette tidligere...\n\nHvordan siger jeg det...\n\nMorgan har måske troet, at hans familie var død, men faktisk er hans datter Sarah Ladimøre nu Vagtinde. Hun har altid været plaget af... omstændighederne... omkring sin fars død. Måske kunne du tage hen og bringe hende nyheden.", c="Ja? Min far...\n\n<Hendes øjne falder.>\n\nJeg ville ønske... at der var noget, jeg kunne have gjort for ham... Bare jeg havde talt med ham, før han..."},
  [232] = {n="Ærinde for Apoteker Sinje", l="Tag indkøbsordren med til Alessandro Lukas i Underbyen.", d="Det Kongelige Apotekerselskab har brug for din hjælp. Lyt nøje, og vi kan begge tjene på min plan.\n\nApoteker Kiver i det næste rum er måske... berørt... men hans forskning kan potentielt bære frugt, hvis den blev forfulgt af en snedig forsker. Heldigvis er jeg netop sådan en forsker. Jeg vil have dig til at tage denne indkøbsordre med til Alessandro Lukas, ejeren af Blå Måne Rariteter og Småting; han giver dig et testsæt. Når du har det, skal du bringe det tilbage til mig, så gennemgår jeg din opgave i detaljer.", p="Ja, og hvad kan jeg hjælpe dig med? Er du her i ærinde for Det Kongelige Apotekerselskab, eller er du kommet her blot for at lyse op i min dag?", c="Ah, Sinje har brug for et sæt, siger du? Det gør mig ondt, at Sinje ikke vælger at bevære mig med sin søde tilstedeværelse.\n\nVel, lad mig skaffe et sæt til dig."},
  [238] = {n="Ærinde for Apoteker Sinje", l="Bring Feltprøvesættet til Apoteker Sinje i Underbyen.", d="Sættet er klar, <Name>. Der er ingen tvivl om, at Apoteker Sinje vil have det så hurtigt som muligt. Tag det med til hende uden forsinkelse, og lad hende vide, at jeg vil lægge prisen på sættet på Selskabets regning. Og overbring hende venligst mine varmeste hilsner.\n\nNå, stå ikke bare der. Sådan er en simpel kurérs liv, ikke?", p="Ja, jeg synes, Lukas er lige så forstyrrende, som du gør. Det betyder ikke noget - giv mig feltprøvesættet. Jeg bliver nødt til at foretage nogle justeringer for at undersøge de rette basismaterialer.\n\nDu har sættet, ikke?", c="Godt - det glæder mig at arbejde sammen med nogen, der er stolt af ikke at spilde min tid.\n\nNår jeg har lavet nogle justeringer på dette sæt, er du klar til at drage ud i felten. Du skal bruge det til at indsamle nogle vitale data til den opgave, der ligger foran os.\n\nDet tager kun et øjeblik for mig at færdiggøre ændringerne. Mens du venter, bør du nok begynde at tænke over, hvad du gerne vil have med dig til ørkenen.\n\nJa, jeg sagde ørkenen."},
  [243] = {n="Ud i Felten", l="Tal med Overingeniør Lensevits i Gadgetbyen om at få en strømkilde til testsættet.", d="Du skal ud til Tanarisk-ørkenen og teste vævets konsistens hos basiliskerne, skorpiderne og hyænerne, der lever der. Indsaml vævsprøver og brug dem sammen med testsættet, du har med dig; forvent, at en del af prøverne fejler. Jeg har brug for otte acceptable prøver fra hver skabningstype.\n\nDerudover har kobolderne i Gadgetbyen en strømkilde, der skal bruges sammen med denne slags modificeret sæt. Tal med Overingeniør Lensevits og skaf en til sættet.\n\nVend kun tilbage til mig, når du har succes.", c="Åh, vores strømkilder model 4711-FTZ! Vi bruger normalt dem til at drive vandbrøndene, men TAKKET VÆRE DE NEDRIGE NOMADER har vi lige nu en overflod af strømkilder.\n\nJo, jeg kan skaffe dig en strømkilde til hvilket som helst skumlet videnskabeligt eksperiment, du tror, du prøver at skjule for mig. Det bliver dog ikke gratis, <Race>. Intet er gratis i Gadgetbyen."},
  [258] = {n="Jægerens Udfordring", l="Dræb 5 Ældre Bjergvildsvin og vend tilbage til Darl Ungkarl i Fjernvandrer-logen inden for 12 minutter.", d="<Name>ath, hedder du det? Jeg kan se, du syder af stolthed over at have bestået den første prøve, hva'? Som jeg sagde før, er det ingen stor bedrift.\n\nDu bør prøve dig med vildsvinejagt. Stol på mig, det er ingen Kuldekam-dal vildsvinejagt, så du må passe godt på dem. Denne gang giver jeg dig kun tolv minutter.\n\nLad dig ikke slå ned, hvis du fejler. Jeg ville give dig skjorten af ryggen, hvis du lykkedes!\n\nHar jeg nogensinde fortalt dig historien om, hvordan jeg fik mit berømte ar? Nej? Det var for to år siden...", p="Det er kun naturligt at synes synd om sig selv, når man bliver overgået af nogen, der er så ny i denne verden. Du bør ikke have det dårligt, <Name>ah.\n\nHva'? Fik jeg dit navn forkert?", c="Du ser lidt medtaget ud. Uden tvivl gav vildsvinene dig noget besvær, hva'? Ingen bekymring, jeg vil være diskret omkring din kamp, jeg kan forestille mig, hvor svært det må være for dig uden anklager fra klikkende tunger.\n\nÅh! Du klarede at dræbe vildsvinene? Jeg... ja, det er... det vil sige, jeg er ikke overrasket! Ethvert barn kunne have—satset?\n\nHvilket væddemål?"},
  [261] = {n="Ned ad den Skarlagenrøde Vej", l="Ødelæg 30 Udøde Hærgere, og vend så tilbage til Broder Anton ved Nijels Punkt.", d="Jeg vil være ærlig. Vi er i krig med Pesten. Det er et ondskab, der fordærver vores folk og inficerer vores land. Det må standses, før det overvælder os og trækker vores verden ind i skyggerne. Vi fra det Skarlagenrøde Korstog har svoret at kæmpe mod Pesten med krop og sjæl.\n\nHvis du står på vores side, så saml dit mod og bevis din loyalitet--ødelæg de udøde hærgere i Forødelse, i Knoglernes Dal mod syd.\n\nGør dette, og Korstoget vil omfavne dig.", p="Pesten vokser i styrke for hver eneste dag. Hvis du virkelig ønsker at standse dens fremmarch, så vis mig det.", c="Du har bevist din beslutsomhed, og det Skarlagenrøde Korstog roser dig.\n\nHvis du ikke skyr retfærdig slagtning, så ligger din vej måske hos os..."},
  [278] = {n="En Mørk Trussel Tårner Sig Op", l="Overingeniør Hinderweir vil have dig til at samle Lurergift, en Mo'Grøsh-krystal og en Krokolisk-tåre.", d="Begynd straks at samle afvæbningsmaterialerne, <Name>. Lurergift kan findes på de hjemmehørende edderkopper i Modansøen. Krokolisk-tårer findes også her i søen. Men en Mo'Grøsh-krystal vil være meget svær at skaffe. Ogrene mod nordøst udvinder dem, men krystallerne er en meget sjælden vare.\n\nVi må være klar til at afværge et Mørkejern-angreb! Vend tilbage til mig, når du har samlet de nødvendige ting, så tilbereder jeg blandingen.", p="Har du de nødvendige ting? Tiden er af afgørende betydning!!", c="Lige i tide, <Name>!"},
  [280] = {n="En Mørk Trussel Tårner Sig Op", l="Overingeniør Hinderweir vil have dig til at svømme ned til skadens fod, finde krudttønden og røre Afvæbningsblandingen i for at forhindre en eksplosion.", d="Tidligere i dag så jeg nogle Mørkejern-oprørere svømme mod Skaden med en stor tønde. Der var ingen Bjergbestigere til stede for at stoppe dem! Jeg er bange for, at de har placeret Havforium ved skadens fod, og den kan sprænge når som helst! Lad mig blande alle disse ingredienser til Afvæbningsblandingen. Der var den.\n\nNu skal du tage denne blanding og røre den i tønden, før det er for sent! Skynd dig!", p="Tøndens låg drejer langsomt af.", c="Tønden sprutter lidt, mens Afvæbningsblandingen sætter sig."},
  [283] = {n="En Mørk Trussel Tårner Sig Op", l="Afvæbningsblandingen ser ud til at have virket. Vend tilbage til Overingeniør Hinderweir for at melde de gode nyheder.", d="Tønden sprutter lidt.", c="Tusind tak, <Name>!! Du har reddet den Stenbyggede Skade! Uden din hjælp ville Mørkejern-terroristerne helt sikkert have sørget for dette mægtige vartegns undergang. Du har gjort Riget og Alliancen stolte, modige <Class>.\n\nSkaden er igen i sikkerhed. . . i hvert fald for nu. . . ."},
  [328] = {n="Den Skjulte Nøgle", l="Brug den lille messingnøgle til at åbne Bookmager Herods pengeskab.", d="Selvom der ikke findes nogen omtale af Menig Torsten i disse optegnelser, er en lille messingnøgle skjult i bindet af en af Herods hovedbøger.\n\nOg efter yderligere studier af hans noter er der flere henvisninger til et \"sikkert pengeskab\" blandt diverse papirer. Kassen står et sted i Lageret - hulekomplekset bag Kortsens Blanding.\n\nHvis dette sikre pengeskab findes, og den lille messingnøgle kan åbne det, vil måske mysteriet bag Torstens opdagelse blive afsløret.", p="Pengeskabet er beslået med bronze, meget solidt og meget tungt.", c="Når man åbner pengeskabet, er det tydeligt, at det er her, Herod opbevarer sine mere værdifulde mønter og genstande."},
  [329] = {n="Spionen Afsløret!", l="Tag den Snavsede Seddel med til Løjtnant Døren i Oprørslejren.", d="Blandt pengeskabets værdigenstande ligger en mudret, klodset skrevet seddel. Selvom den knap er læselig, ser den ud til at være en rejseplan for Menig Torsten. Den beskriver hans patruljeruter, hvem han taler med, og hvordan han bruger sin tid sammen med oprørerne. Den er kun underskrevet med ét bogstav: -M.\n\nMen den, der skrev denne seddel, må have holdt sig meget tæt på Torsten. Den, der skrev denne seddel, er forræderen i oprørslejren.", p="Opdagede du, hvem der kendte Torstens hemmelighed? Er der en forræder iblandt os?", c="Tak, <Name>. Denne seddel er det spor, vi har brug for for at udrydde forræderen!"},
  [330] = {n="Patruljeplaner", l="Tal med Korporal Sedmann.", d="Seddelen, du gav mig, er underskrevet med et \"-M\"...Jeg aner ikke, hvad det kan betyde.\n\nMen...seddelen siger også, at denne person delte patruljeruter med Torsten i sidste uge. Så den, der delte patrulje med Torsten i sidste uge, må være forræderen!\n\nGå hen til Korporal Sedmann. Han har ansvaret for patruljeplanerne og kan fortælle dig, hvem der var sammen med Torsten.", c="Åh, ja, det kan jeg tjekke for dig. Lad os se... sidste uge var det...\n\n...ja da, det var Menig Solsort, der var sat sammen med Torsten. De havde de samme patruljetider hele sidste uge."},
  [331] = {n="Meld til Døren", l="Tal med Løjtnant Døren.", d="Ville Løjtnant Døren have, at du meldte tilbage til ham med den patruljeinformation?", c="Det smerter mig at finde ud af, at det var Solsort, der forrådte os. Han har altid været en modig soldat, og jeg troede, hans hjerte var ærligt. Men det er en stor lettelse at have afsløret ham - med en spion som ham blandt os... ville vi ikke holde længe mod Oberst Kortsen."},
  [336] = {n="En Ædel Brygning", l="Tag Sort Klo-stouten med til Lord Vishock i Andragernes Hal.", d="Lord Vishock har, ligesom alle mænd, sine svagheder. Hans er en forkærlighed for brændevin. Hykleriet er forbløffende. Den kedelige tåbe bruger sine dage på at forsøge at lukke vores lille \"kro\", mens hans nætter går med at løbe en regning op, han aldrig betaler. Nå, lad os se, hvordan Vishock kan lide denne særlige brygning, jeg har lavet til ham: Sort Klo-stout. Den har et godt sæt, <Name>.\n\nTag den med til ham og se, hvordan han kan lide den. Den gamle tåbe slentrer sikkert rundt i Andragernes Hal.", p="Kan du ikke se, at jeg er optaget? Mine ord må høres! Jeg er af stor betydning for rigets fremtid!\n\nÅh... hvad har du dér? Det ligner da en forfriskende drik...", c="Ah, tak, fine tjener, for den flotte stout. Her er en kobbermønt til dig. Nu, væk med dig, og lad mig nyde min drik!"},
  [348] = {n="Stranglethorn-feber", l="Find Heksedoktor Unbagwa og få ham til at kalde Mokk den Vilde frem. Bring Mokks Hjerte til Finne Fizracket.", d="Syg...så...meget s-s-syg....\n\n...har fået Stranglethorn-feber...dødelig v-v-virus...\n\n...eneste kur...er...er at spise hjertet af M-m-m-m-mokk den Vilde...unddragende hvidt udyr...\n\n...Heksedoktor Unbagwa...den eneste, der kan s-s-kalde ham....\n\n...søg Unbagwa i en skjult hule på den sydlige halvø...\n\n...skynd dig...døende...døende....", p="....mor?\n\n...så koldt...\n\n...på vej ind i det Snoede Nether...h-h-h-hold mig, mor....", c="...føler styrken vende tilbage....\n\nHvor er jeg? Bytteviken? Åh gud! Jeg havde den mærkeligste drøm...\n\n...svagheden har ikke helt forladt mig...."},
  [351] = {n="Find OOX-17/TN!", l="Bring nødsignalbøjen til Oglethorpes hjemvendingsrobot.", d="Du har afdækket en slags mærkelig, æggeformet anordning lavet af metal. Når du fikler ved en af dens knapper, springer ægget til live og åbner sig til en slags gnomisk robotapparat! En stemme inde fra det robotiske æg knitrer til live.\n\n\"Jeg hedder Oglethorpe, og min hjemvendingsrobot er forsvundet! Jeg belønner dig for at finde den! Tag venligst denne nødsignalbøje med til robotten. Fremragende, nu har jeg beregnet koordinaterne til dig! Den styrtede ned nær Den Gabende Kløft i Tanaris-ørkenen!\"", p="Du ser ud til at have afdækket vraget af... en robotkylling? Stemmen inde fra ægget knitrer til live igen:\n\n\"Ja, fremragende arbejde! Det er faktisk min hjemvendingsrobot, selvom mine sensorer viser, at den har brug for et startskub, før den kan flyve tilbage til Bytteviken for reparationer. Gå så videre og placér bøjen inde i køretøjet. Bøjen klarer resten!\"", c="Du placerer ægget... nødsignalbøjen... inde i kyllingen... hjemvendingsrobotten.\n\nSummen og surren høres inde fra robotten, mens den kæmper for at rejse sig. Efter robotten er kommet til live, høres Oglethorpes stemme igen, men nu inde fra robotten:\n\n\"OOX-17/TN virker i det mindste, men den har brug for store reparationer! Den er alt for tung for dig at bære... men jeg tror, jeg har en idé. Har du lyst til at holde øje med den lidt endnu?\""},
  [379] = {n="Slæk Tørsten", l="Bring 5 Spildevandsnomadernes vandposer til Overingeniør Lensevits i Gadgetbyen.", d="Du vil have en energikilde. Det kan jeg hjælpe dig med. Ved du, hvad jeg vil have? Jeg vil have noget at drikke! Bring mig fem Spildevandsnomadernes vandposer, så giver jeg dig 4711-FTZ.\n\nNu... gæt, hvor du kan finde Spildevandsnomadernes vandposer! Hvorfor går du ikke hen til en af nomaderne øst for her og beder dem om en. Lad mig vide, hvordan det går for dig.", p="Nå, ville nomaderne \"frivilligt\" give dig de vandposer?", c="Fremragende, energikilden er din. Den er ikke helt designet til et videnskabssæt som dette, så du har kun begrænset tid, før alle de data, du indsamler, går kablamm!\n\nNår du har samlet alt, hvad du behøver til det, du nu laver, så bring det til mig, og jeg lukker det ned ordentligt. Du har højst to timer til at få det gjort, du skal have gjort.\n\nHvis du ikke når det i tide, kan jeg altid sælge dig en ny energikilde, så du kan prøve igen. Du hørte rigtigt - sælge!"},
  [394] = {n="Udyrets Hoved", l="Tal med Mathias Skaw i Stormvind.", d="Find Skaw i Gamlebyen. Lad ham vide, at Lescovær-truslen er klaret, og om din rolle i lordens rænker mod byen. Jeg er sikker på, at han vil være stolt over endnu en helt blandt Stormvinds borgere.\n\nHan sender dig sandsynligvis videre for at møde prinsen eller en anden adelsmand. Lad det ikke gå dig til hovedet, <Name>. Adelen kan tro, de styrer byen, så meget de vil, men nogle ting ligger uden for deres hænder.", c="Er han død, så? Din retfærdighed var hurtig, <Name>. Jeg beder til Let, at jeg aldrig må blive dit bytte!\n\n<Han griner og klapper dig på skulderen.>\n\nJeg mener ikke at kritisere, <Name>. Hvordan skulle jeg kunne, når jeg er mester over alle snigmordere? Men i sandhed har du gjort Stormvinds borgere en stor tjeneste, og for det takker jeg dig."},
  [395] = {n="Broderskabets Ende", l="Tal med Baros Alexstøn i Stormvind.", d="Ah, jeg glemte næsten det. Alexstøn kom, mens du var væk, og han ville tale med dig. Uden tvivl vil han rapportere om Defias-broderskabets færden til adelen.\n\nEt lille råd, <Name>: Hvis nogen spørger, så giv alle detaljerne, undtagen at det var din hånd, der slog Lescovær ihjel. Stol på mig. Jeg er... bekendt... med den slags ting.\n\nOg for så vidt angår Trias, så tal med ingen om ham... nogensinde... hvis du kan undgå det.", c="Det er godt at se dig, <Name>. Jeg har hørt, at Lord Gregor Lescovær blev fundet død for nylig.\n\nDet lader til, at din mission lykkedes. Du har min taknemmelighed, fordi du har reddet mig og mange andre fra Vankliffs hævn."},
  [396] = {n="En Audiens hos Kongen", l="Aflever Baros Alexstøns rapport om Defias-broderskabet til Kong Varian Skævsen i Stormvinds Fæstning.", d="Jeg har forberedt en rapport til kongen. Jeg mener, at du bør være den, der leverer den til ham sammen med en beretning om dine fund. Frygt ikke, der er ingen tvivl om, at han vil rose dig for at have gjort din pligt over for Stormvinds borgere.\n\nDin audiens er planlagt snart, så du gør klogt i at skynde dig, for det er et stykke vej til Stormvinds Fæstning.", p="<Name>, ja? Baros Alexstøn fortalte mig, at du ville komme. Jeg må sige, at jeg er meget interesseret i, hvad du har at sige.", c="Du skal have ros for den tjeneste, du har gjort for Stormvind, <Name>. Hvis Vankliff var lykkedes med sine rænker, ville han uden tvivl have gjort betydelig skade på riget - noget vi naturligvis må undgå.\n\nTag dette, <Class>, som et tegn på kongens påskønnelse. Jeg er kun ked af, at han ikke selv kan overrække det til dig, men han er på en diplomatisk mission og vender ikke tilbage på et stykke tid."},
  [397] = {n="Du Har Tjent Os Godt", l="Tal med Zjuggi, tjeneren af Zardeth Sortklo, for at få din belønning.", d="Jeg hører, Lord Vishock nød sin drik.\n\nDu har tjent os godt, <Name>. Stormvinds Hekser vil kunne udøve vores veje uden forstyrrelse, takket være dig. For din indsats har jeg forberedt en særlig gave til dig. Tal med min tjener, Zjuggi, og få din belønning.", c="Mester siger, giv gave til <Name>. Zjuggi vil gerne beholde den fine gave, men Zjuggi ved bedre end at forråde Mester."},
  [415] = {n="Rejolds Nye Brygning", l="Tal med Rejold Bygbrygger.", d="Rejold Bygbrygger i Brygnall-landsbyen har spurgt efter dig.\n\nHan vil tale med dig om en ny drik, han har brygget... sagde noget om, at du kunne hjælpe ham med den. Du bør nok vende tilbage til Brygnall-landsbyen og høre, hvad han har at sige.\n\nDer kan være noget gratis sprut i den til dig...", c="<Name>! Ved du, at Glimmerukrudtet du bragte mig? Nå, jeg brugte det i et par opskrifter, jeg har arbejdet på, og en af dem blev fantastisk!\n\nHer, prøv den og fortæl mig, hvad du synes..."},
  [417] = {n="En Pilots Hævn", l="Dræb Mangeklo.\n\nBring hans Skabbet Klo og Hildelvs dagbog til Pilot Hammerfod.", d="Hildelv skrev i sin dagbog, at han blev angrebet af Mangeklo, en \"kæmpestor Isklo-bjørn\". Han drev udyret væk, men ikke før det havde lemlæstet ham brutalt.\n\nAt dømme ud fra Hildelvs krop må Mangeklo senere være vendt tilbage og dræbt ham.\n\nDog skrev Hildelv i sin dagbog sit ene, sidste ønske:\n\nHævn over Mangeklo.", p="Hej, <Name>. Har du nyt om min ven Hildelv?", c="Dette er dystre nyheder, for Hildelv var en god ven. Og jeg ville ønske, jeg havde været der sammen med dig, da du fandt udyret, Mangeklo!\n\nTak, <Name>. Din bedrift vil blive husket af pilotene i Jernsmede Belejringsbrigade."},
  [419] = {n="Den Tabte Pilot", l="Find Pilot Hildelv.", d="Min ven og kollega, Belejringsmaskine-piloten Mori Hildelv, er faret vild i bakkerne. Vi ledte efter en sjælden malm, der skal bruges til et krudt af høj kvalitet, og under vores søgen kørte han sin maskine op ad en stejl bakke og ødelagde den!\n\nStadig overbevist om, at malmen lå i disse bjerge, bad Hildelv mig om at vogte vores maskiner, mens han fortsatte til fods og ledte.\n\nDet er gået flere dage, og jeg har hørt nogle udyriske brøl i bakkerne om natten. Mori er sej som sømmet, men jeg er bekymret.\n\nVær sød, <Name>. Find ham.", c="Her ligger liget af en dværg - lemlæstet, frosset og renset for kød af bjergaasene. I hånden holder den en bog med Mori Hildelvs groft nedskrevne noter. Og om dens krop, stadig i fin stand, er en Brigadérens vest.\n\nDenne grusomme scene må være, hvor Belejringsmaskine-piloten mødte sin ende."},
  [435] = {n="Eskortering af Erland", l="Eskortér Erland gennem ulvene til Rane Yorik.", d="Ulvene derude vil ikke gå væk, og de stirrer ondt på mig, hver gang jeg sætter foden uden for den dør. De må være utrolig sultne, hvis de tror, jeg er værd at spise.\n\nJeg skal rapportere til min holdkammerat, Dødsstalkeren Rane Yorik. Og for at komme til Rane får jeg brug for hjælp mod de ulve.\n\nVær venlig at eskortere mig! Og der er mange ulve derude, så vi har bedre chancer, hvis du har venner, der kan hjælpe...", p="Vær venlig at være kortfattet. Der er megen fare i nærheden, og vi kan ikke stå her og snakke.", c="Tak for hjælpen, <Name>. Jeg frygtede, at Erland var blevet overvældet af farerne i Sølvfyr. Med din hjælp ser jeg, at det ikke er sket."},
  [475] = {n="En Urolig Brise", l="Find Gaerolas Talvethren i Stjernebrise-landsbyen.", d="En urolig brise blæser gennem skoven.\n\nGaerolas Talvethren fungerer som Stor Vogter over dvaledruiderne fra Klodruiderne i Ban'ethil-gravhulen. Hans pligt som de sovendes udvalgte beskytter er at sikre deres sikkerhed, så deres pagt med Ysera forbliver opfyldt.\n\nMen nyt fra Gaerolas er nu forsinket, og jeg bliver nervøs. Rejs mod øst til Stjernebrise-landsbyen og bring en rapport tilbage fra Gaerolas, så jeg kan falde til ro og vide, at mine drømmende brødre sover trygt.", c="Tak naturåndene, at du er her! Jeg vidste, at Athridas ville mærke uroen og sende hjælp."},
  [476] = {n="Knudefyr-fordærvelsen", l="Vend tilbage til Athridas Bjørnekappe i Dolanår.", d="Knudefyr-stammen er blevet fordærvet!\n\nDe engang fredelige pelsbjørne har vendt sig mod skovens beskyttere. De overfaldt mig, da jeg var på vej til Ban'ethil-gravhulen, og plyndrede Stjernebrise-landsbyen. Ursal Lemlæster, deres høvding, bruger de ondes kræfter fra Ondmos til at drive dem fra forstanden.\n\nJeg er for såret til at vende tilbage til Athridas og bringe ham denne alvorlige nyhed. Opgaven er overladt til dig, unge <Class>. Vi kan kun håbe, at de vanvittige knudefyr ikke har nået Ban'ethil endnu!", c="Ved stjernerne! Det her er faktisk meget foruroligende!"},
  [485] = {n="Find OOX-09/HL!", l="Tag nødsignalbøjen til Oglethorpes hjemvendingsrobot ved flodens udspring i Bagland, nær Sniger-klippen.", d="Du har afdækket en slags mærkelig, æggeformet anordning lavet af metal. Når du fikler ved en af dens knapper, springer ægget til live og åbner sig til en slags gnomisk robotapparat! En stemme inde fra det robotiske æg knitrer til live.\n\n\"Jeg hedder Oglethorpe Uopdaget, og min hjemvendingsrobot er styrtet ned! Jeg belønner dig for at finde den; vær venlig at tage denne nødsignalbøje med til robotten!\"\n\n\"Jeg har nu beregnet robottens koordinater til dig; den styrtede ned ved flodens udspring nær Sniger-klippen!\"", p="Du ser ud til at have afdækket vraget af... en robotkylling? Stemmen inde fra ægget knitrer til live igen:\n\n\"Ja, fremragende arbejde! Det er faktisk min hjemvendingsrobot, selvom mine sensorer viser, at den har brug for et startskub, før den kan flyve tilbage til Bytteviken for reparationer. Placér bøjen inde i køretøjet - bøjen klarer resten!\"", c="Du placerer ægget... nødsignalbøjen... inde i kyllingen... hjemvendingsrobotten.\n\nSummen og surren høres inde fra robotten, mens den kæmper for at rejse sig. Efter robotten er kommet til live, høres Oglethorpes stemme igen, men nu inde fra robotten:\n\n\"OOX-09/HL virker i det mindste, men den har brug for store reparationer! Den er alt for tung for dig at bære... men jeg tror, jeg har en idé. Har du lyst til at holde øje med den lidt endnu?\""},
  [487] = {n="Vejen til Darnassos", l="Dræb 6 Knudefyr-baghold-angribere og vend tilbage til Vogter Amara Natvandrer uden for Dolanår.", d="Vejen til Darnassos skal holdes sikker. Rejsende fra Dolanår til Darnassos har rapporteret om hensynsløse angreb fra fordærvede pelsbjørne fra Knudefyr-stammen.\n\nVigtige nyheder og handel rejser dagligt til og fra Darnassos ad denne vej. Vi har ikke råd til, at en flok hedninge terroriserer folk.\n\nTag til våben i det helliges skovs navn, <Class>. Deres hule ligger et sted under dette udsigtspunkt. Dræb 6 af disse Knudefyr-baghold-angribere og rapportér tilbage til mig.", p="Vejen er stadig ikke sikker, <Class>. Drag af sted, dræb 6 Knudefyr-baghold-angribere og vend tilbage til mig.", c="Du har tjent Dolanårs og Darnassos' gode folk godt, modige <Class>. Som medlem af Teldrassils Vogterstyrke hylder jeg din indsats."},
  [488] = {n="Zenns Ordre", l="Bring Zenn Stinkhov uden for Dolanår 3 Natsabel-hugtænder, 3 Strigide Uglefjer og 3 stykker Vævsskov-edderkoppesilke.", d="Ivrig efter arbejde, ser jeg. Heldigt for dig, at der ikke går en dag, uden at jeg ønsker, at jeg havde en ung <Class> til at udføre mine ordrer.\n\nDu ser, <Name>, jeg kan gøre dig meget glad og give dig ting, du aldrig havde drømt om at have. Men for at det kan ske, skal du bringe mig visse ting.\n\nMin virksomhed i skoven kræver ofte visse... reagenser. Hent til mig 3 Natsabel-hugtænder, 3 Strigide Uglefjer og 3 stykker Vævsskov-edderkoppesilke.\n\nLad os holde det her vores lille hemmelighed, <Race>.", p="Har du været en travl lille bi, <Name>? Jeg har ventet på, at du bringer mig det, jeg har brug for.", c="Ha ha! Nå, udført, ja.\n\nHvem skulle have gættet, at jeg, Zenn Stinkhov, ville få en <Race> til at udføre mine ordrer? Bestemt ikke mig! Men sådan er det... denne elskede verden af vores er fuld af overraskelser.\n\nTre hurra for de naive og godtroende!"},
  [489] = {n="Søg Forløsning!", l="Saml 3 Ondkogler og giv dem til Zenn Stinkhov uden for Dolanår.", d="Skovrådet har fået nyheder om, at du hjalp Zenn Stinkhov. Satyren er en fjende af skoven. Som <Race> burde du vide bedre end at besudle skoven ved at dræbe Naturens væsener.\n\nDu må forløse dig selv i rådets øjne, hvis du vil forblive en ven af Teldrassil.\n\nLær Stinkhov en lektion, så er du forløst. Ondkogler er fordærvede frø, der falder fra træerne. De bølger af grøn røg.\n\nGiv noget til Stinkhov. Han tror, du har bragt ham en uskadelig snack.", p="Hvad har du til mig, <Name>? En dejlig snack, formoder jeg?", c="Ah, sikke en sød <Race>! Jeg vidste, du ville komme til nytte!"},
  [495] = {n="Viljens Krone", l="Rapportér til Melisara i Tarren Mølle i Hillsbrad-forbjergene.", d="Krus'Thol og hans ogre-krigsflok blev sendt til Alterac for at hente Viljens Krone til Frue Silvanas. Desværre besluttede tåben i stedet for at returnere den at prøve den på... Jeg formoder, at oger ikke kan modstå noget klart og blankt.\n\nHans klodsede handlinger er dog blevet noget af et problem. Viljens Krone gjorde det muligt for ham at modstå den besiddelse, der var lagt over ham for at tjene Frue Silvanas.\n\nDen Mørke Dame ønsker et eksempel statueret. Rejs til Tarren Mølle i Hillsbrad og rapportér til Melisara, min løjtnant.", c="Shalindra sendte dig? Meget godt, så vil du opdage, at jeg ikke spilder megen tid på tom snak.\n\nKrus'Thol er en irritation, og vi tager os af ham hurtigt, grundigt og uden besvær."},
  [506] = {n="Sortmoors Arv", l="Returnér de oplysninger, Gulddyr har indsamlet, til Krusk i Tarren Mølle.", d="For et døgn eller to siden blev jeg besøgt af lederen af dette Syndikat. Hans navn var Aliden Pæreknold, og han kaldte sig selv herre over dette land. Han betroede mig sine planer om at tage de orker, der stod imod ham, som slaver, ligesom hans far og hans mentor, den foragtede Sortmoor, havde planlagt.\n\nDet vigtigste var, at han havde taget sin elskerinde med, en tynd, lille pige ved navn Elisa. Om hendes hals hang det vedhæng, Krigshøvdingen ønsker.\n\nNu, gå. Jeg tager min egen vej, når jeg har afsluttet min forretning her.", c="Den frækhed af de overmodige mennesker! Vi viser dem, at orkerne aldrig vil bøje sig for deres vilje!\n\nDette bliver nu vores mission, ud over at hente den tingest, Krigshøvdingen ønsker. Det lader til, at vi med én opgave også opfylder den anden."},
  [508] = {n="Tarethas Gave", l="Returnér Tarethas vedhæng til Krusk i Tarren Mølle.", d="Vedhænget? Selvfølgelig må du have det... Tag det! Jeg vil ikke have nogen erindring om ham... bare, bare lad mig være i fred...", p="Du er vendt tilbage, <Name>. Succes at rapportere?", c="Det er mærkeligt, at Krigshøvdingen ville bruge så meget på sådan en lille ting. Jeg påstår ikke at forstå ham, men jeg vil følge ham, uanset hans ordrer. Du gjorde det godt, <Name>, og uden tvivl vil Krigshøvdingen være glad for at høre om din succes."},
  [510] = {n="Uhyggelige Tegninger", l="Bring de Uhyggelige Tegninger til Dommer Maleb i Sydstranden.", d="Blandt disse dokumenter er en liste over efterspurgte forsyninger. Disse omfatter almindelige ting (mad, våben, tøj) såvel som mere eksotisk udstyr (masker, olie, gift).\n\nMen det mest bemærkelsesværdige er hastværket i anmodningen - disse forsyninger var nødvendige snart, for at man kunne gennemføre det, der beskrives i dokumentet som en \"vigtig mission mod Sydstranden.\"", p="<Name>, du ser ængstelig ud. Er der noget, du vil fortælle mig?", c="<Maleb læser dokumenterne.>\n\nDisse er meget foruroligende, <Name>. Ud fra oplysningerne i disse dokumenter og Syndikatets handlinger i fortiden må vi antage, at den bagholdsflok har ført krig mod Sydstranden."},
  [511] = {n="Krypteret Brev", l="Bring det Krypterede Brev til Vidensmester Nips i Sydstranden.", d="Et af brevene på dette bord er krypteret og uudgrundeligt.", p="Ja, herre? Har du et ærinde hos mig?", c="Hvad er dette? Vent et øjeblik... lad mig se nærmere på det.\n\n...\n\nHm, jeg har aldrig før set denne form for kryptering, men jeg må indrømme, at min viden på det område på ingen måde er fuldkommen."},
  [512] = {n="Adelige Dødsfald", l="Bring 7 Alterac-seglringe til Dommer Maleb i Sydstranden.", d="Jeg frygter, at lederskabet bag Syndikatet er opsat på Sydstrandens undergang. Vi må slå hårdt mod disse ledere, før deres planer bliver til virkelighed.\n\nTræd ind i ruinerne af Strahnbrad i Alterac-bjergene mod nord. Vi tror, at Syndikatet bruger området som hovedkvarter.\n\nVi ved, at denne bande af bagholdsrøvere ledes af tidligere Alterac-adelige. De kan skjule sig som almindelige Syndikat-agenter, men du vil kunne kende, at du har dræbt en adelsmand på seglringen, han bærer.\n\nBring mig de seglringe.", p="Har du jagtet Syndikatet? Har du de ringe?", c="Når Syndikatet berøves sin adel, fjernes dets evne til at handle beslutsomt, og det reduceres til intet mere end en flok bøller.\n\nDu tjener din Alliance godt, <Name>."},
  [514] = {n="Brev til Stormspids", l="Tag det snedigt krypterede brev til Prospektor Stormspids i Jernsmede.", d="Jeg har en kollega i Jernsmede, som måske kan hjælpe med at dekryptere dette brev. Gå til Biblioteket i Opdagelsesrejsendes Hal i Jernsmede og tal med Prospektor Stormspids. Sig at jeg sendte dig, og vis ham brevet. Hvis der er nogen nord for Sortklippe-spiret, der kan læse det her, så er det ham.", p="Nips fra Sydstrand sendte dig, gjorde han? Hvordan har den gamle bogorm det?", c="Ah, kryptering! Mit speciale. Lad mig se her..."},
  [518] = {n="Viljens Krone", l="Dræb 14 Knusekam-kværnere for Melisøra i Tarrens Mølle.", d="Krus'Thol og hans Knusekam-oger har overrendt ruinerne af Alterac. Det bliver svært at give ham en ordentlig straf, medmindre vi tynder ud i ogernes rækker.\n\nNår de er blevet mørbankede, går vi videre.\n\nForstået? Godt. Nu af sted med dig.", p="Jeg bemærker, at din opgave ikke er færdig, <Name>. Skal jeg fortælle Sjarlindra om din udueligheds?", c="Sneen blomstrer rød af ogernes blod, men vi kan ikke holde op med vores indsats, før Knusekams ånd og tal er knust og smadret ned i jord og sne."},
  [519] = {n="Viljens Krone", l="Dræb Tarv, Møgrage og Klumpus, og bring deres hoveder til Melisøra i Tarrens Mølle.", d="Tarv, Møgrage og Klumpus er Krus'Thols løjtnanter. De er loyale over for ham, men hvem kan sige, hvad der driver en oger til loyalitet?\n\nBring mig deres hoveder, <Name>, og så er det eneste, der står tilbage, at fjerne Krus'Thols hoved, krone og det hele.", p="Jeg vil have deres hoveder, <Name>, ikke undskyldninger.", c="...og jeg troede, at oger lugtede slemt nok i forvejen.\n\nNår du bringer mig Krus'Thols hoved, vil jeg få alle fire monteret på pigge over Alterac. Et passende monument for dem, der går imod Den Mørke Dames ønsker."},
  [520] = {n="Viljens Krone", l="Dræb Krus'Thol, og bring hans hoved sammen med Viljens Krone tilbage til Melisøra i Tarrens Mølle.", d="Med Krus'Thols løjtnanter døde er det eneste, der er tilbage, at dræbe Krus'Thol og hente Viljens Krone. Jeg tvivler ikke på, at han er tilbageholdende med at skille sig af med den. Han forventer nok også dig, givet... afgangen... af hans kammerater.\n\nFind Krus'Thol, og lever hans hoved og kronen til mig. Knusekam-modstanden vil være ovre.", p="Tre hoveder har jeg, et fjerde mangler. Det bliver Krus'Thols, eller også bliver det dit, <Name>. Det lover jeg.", c="Du har gjort din pligt godt, <Name>. Krus'Thols hoved skal pryde den højeste top i ruinerne af Alterac, og Dødevagten vil feje resterne af Knusekam ned i jorden."},
  [521] = {n="Viljens Krone", l="Lever Viljens Krone til Sjarlindra i Underbyen.", d="Det eneste, der er tilbage, er at levere Viljens Krone til Sjarlindra i Underbyen. Hun vil sørge for, at den bliver leveret til Frue Silvanas. Jeg vil advare dig mod at tænke på at bruge den til dine egne formål, <Name>. Krus'Thols skæbne bør være illustration nok.", p="Ja? Har du noget at melde?", c="Så det er den relikvie, ogeren brugte til at snyde Den Mørke Dames vilje...\n\nDet er mærkeligt, at noget så simpelt kan udøve så stor magt. Og at havne i så klodsede hænder som dem. Godt gået, <Name>. Jeg vil levere kronen til Frue Silvanas og sørge for, at hun hører om din bedrift."},
  [522] = {n="Snigmorderens kontrakt", l="Bring Snigmorderens kontrakt til Dommer Malebe i Sydstrand.", d="Dette er en kontrakt om snigmord på Dommer Henrik Malebe. Den blev forseglet og stemplet med rød voks, ved hjælp af en karakteristisk signetring.", p="Du ser forpustet ud! Har du noget at melde?", c="<Malebe undersøger kontrakten.>\n\nDet forklarer det seneste angreb på Sydstrand. Syndikatet må være ude efter mig, ligesom de var efter den sidste dommer!"},
  [523] = {n="Barons undergang", l="Bring Baron Vardøs' hoved til Dommer Malebe i Sydstrand.", d="Kontrakten, du fandt, var underskrevet af Baron Vardøs, en adelsmand fra det tidligere kongerige Alterac, kendt for et koldt hjerte og brutale metoder. Jeg er ikke overrasket over, at en mand som baronen stod bag dette.\n\nFind denne mand. Find ham, og før ham for retten. Han må være blandt Syndikatets tilholdssteder – måske i ruinerne af Strandbrad, eller måske i dalen nord for dem.", p="Baron Vardøs kan ikke tro, at Sydstrand vil tillade ham at sende sine handlangere mod os uden konsekvenser. Jeg vil have hans hoved!", c="Tak, <Name>. Mit hoved hviler lidt lettere, nu hvor skurken har mistet sit."},
  [524] = {n="Smertens Elixir", l="Placér den besmittede tønde på måtten for de tilfangetagne bønder.", d="Ved siden af holder Dødevagterne nogle tilfangetagne bønder som gidsler. Højeksekutor Darthalia mistænkte en af de militære strateger fra Stormvind for at gemme sig blandt dem. Tilsyneladende blev den militære fyr fundet død i Pestlandene i nat. Darthalia, der altid tænker på mig, besluttede, at fangerne skulle stilles til min rådighed.\n\nJeg synes, det er på tide, vi holder et gilde for de bønder. Lyder som en stor, gammel fest!\n\nPlacér denne besmittede tønde på måtten i deres rum. Pestplaget brygg til alle!", p="En muggen lugt stiger op fra måtten.", c="Du sætter den besmittede tønde ned på det støvede tæppe."},
  [525] = {n="Flere mysterier", l="Bring det dekrypterede brev til Dommer Malebe i Sydstrand.", d="Jeg dekrypterede brevet, men jeg ved ikke, hvad jeg skal stille op med det. Fandt du det blandt tyve i Alterac-foden? Meget mærkeligt...\n\nDu bør tage dette til dommeren i Sydstrand. Selvom dette brev er gådefuldt, er hans by den nærmeste til Alterac; hvis en trussel er under opsejling, bør han vide det.", p="<Name>. Har du været ude og vandre i foden og bjergene igen? Hvilke nyheder bringer du?", c="<Malebe læser brevet.>\n\nDet er oversat fra et brev, du fandt i et Syndikat-lejr? Dette er ikke skrevet af en tyv, eller engang af en adelsmand fra Alterac.\n\nDet ser ud til, at Syndikatet har bånd til en anden magt, og jeg gyser ved tanken om, hvad det kan være."},
  [526] = {n="Lysssmede-barrer", l="Saml 5 lysssmede-barrer, og vend derefter tilbage til Glorin Stålbryn i Vådlandene.", d="Du fandt måske én lysssmede-barre i den kiste, men det er ikke nok til at fremstille noget ordentligt!\n\nDu bør gå tilbage derhen og lede efter flere. Måske har mudderfiskene omkring det forliste skib lysssmede-barrer på sig.", p="Fandt du det lysssmede-jern, du har brug for?", c="Nå, du fandt dem! Nu skal vi have hamret dette lysssmede-jern til noget nyttigt, hvad?"},
  [531] = {n="Vyrins hævn", l="Bring Gamle Sodfars hoved til Vyrin Hurtigvind i Fjernvandrer-logen.", d="Lys! Bring ikke sådan noget ind i Hytten... det er usanitært, ubeskriveligt, uu... uu... usanitært!\n\nFå det bare ud herfra, vil du? Ingen vil se din blodige lille trofæ, virkelig!", p="Godt gået, <Name>! Vi viste ham virkelig! Her, giv mig hovedet, så tager jeg mig af det.", c="Tak for hjælpen med min lille plan, <Name>. Jeg har kløet i månedsvis efter at få hævn over den snobbede, opblæste dreng, og jeg vil sige, vi gjorde et ret godt stykke arbejde! Her, tag det her, du har fortjent det."},
  [537] = {n="Mørkt råd", l="Dræb 4 Argus-skyggemagikere.\n\nBring Nagås' hoved til Dommer Malebe i Sydstrand.", d="Brevet, du bragte mig, var skrevet af et væsen, der kalder sig Nagås, et medlem af Argus-kølvandet. Jeg ved ikke, hvad dette Argus-kølvand er, men hvis de er i alliance med Syndikatet, så må de være en trussel.\n\nJeg vil have dig til at finde Nagås og Argus-skyggemagikerne, der nævnes i det brev. Jeg vil have dig til at finde dem og dræbe dem.\n\nSøg i Højlandene, hvor Syndikatet er stærkest. Det ligger nord for Strandbrad.\n\nMed lidt held finder du disse udsendinge fra Argus-kølvandet der.", p="Fandt du udsendingene fra Argus-kølvandet?", c="Godt gået, <Name>. Argus-kølvandet lyder ikke som en gruppe, vi ønsker at styre Syndikatet.\n\nOg selvom du måske har knust deres leder her, var Nagås blot en tjener for en anden. Argus-kølvandet kan løbe dybt gennem Azeroths kontinent.\n\nEller endda hele verden."},
  [542] = {n="Tilbage til Milton", l="Bring Alterac-tomerne til Milton Neg i Stormvind.", d="Jeg har brug for at bruge noget tid på at studere Armen af Grimlek-bogen, du bragte mig, selvom jeg er sikker på, at Milton er ivrig efter at få de andre fundne bøger ind i Stormvinds samling.\n\nHer er bøgerne, du samlede fra Ruinerne af Alterac, pakket og katalogiseret. Tag dem med tilbage til Milton Neg i Stormvind, så er jeg sikker på, at han vil være taknemmelig.", p="<Name>, du er tilbage! Hvordan gik din tur til Alterac? Bragte du noget med dig?", c="Hold da op! Se på dem! Jeg kan ikke tro, at de overlevede Alteracs ødelæggelse. Og alle de oger også!\n\nTak, <Name>. Tusind tak! Du har hjulpet med at bevare menneskelig viden, og du tilføjer storhed til Det Kongelige Bibliotek i Stormvind."},
  [551] = {n="Det besjælede pergament", l="Tag det besjælede pergament til Vidensmester Nips i Sydstrand.", d="Dette pergament er fortryllet med en besværgelse, der gør det uforståeligt. Men ét ord øverst på papiret kan læses:\n\n\nNagås", p="Åh. Har du noget, du vil have mig til at kigge på? Et stykke viden samlet op i bjergene, håber jeg...", c="Flere krypterede noter?\n\nJeg ville ønske, jeg havde evnerne til at dekryptere alle de mærkelige skriftstykker, der sive ned fra Alterac. Men jeg er bange for, at jeg mangler kundskaberne."},
  [554] = {n="Stormspids' dechifrering", l="Tag det besjælede pergament til Prospektor Stormspids i Jernsmede.", d="Prospektor Stormspids er en mester i dekryptering og tydning. Hvis du tager det pergament, du fandt, med til ham, så kan han med lidt held få det til at give mening. Stormspids studerer i øjeblikket i Prospektor-hovedkvarteret i Jernsmede.\n\nOg når du ser ham, så fortæl ham, at du har talt med mig – jeg har sendt ham en hel del forretning på det seneste.", p="Flere afbrydelser?\n\nAh, dette pergament er dækket af en meget indviklet, fint vævet besværgelse. Jeg kan selvfølgelig løse den op, men det vil tage tid. Og tid er meget værdifuldt for mig...\n\nMåske køber jeg den bare af dig?", c="En klog beslutning. Jeg tror ikke, der findes en lærd ved siden af mig selv med færdighederne til at oversætte denne rulle. Og hvis dets indhold viser sig at være interessant, så frygt ikke. Jeg sender bud efter dig."},
  [558] = {n="Jainas autograf", l="Rejs til Theramøre for at få Frue Jaina Stoltmoors autograf til din myndling.", d="De siger, at Frue Jaina Stoltmoor i Theramøre er en af de største helte, Alliancen nogensinde har haft. Når jeg bliver stor, vil jeg også være en helt for Alliancen!\n\nKender du Jaina, <Name>? Kunne du gøre mig en tjeneste, tak? Kunne du få hendes autograf til mig? Jeg ved ikke, hvordan jeg skal spørge hende, og hun ville nok være alt for travl til en som mig... men du! Du er eventyrer ligesom hende! Jeg vil vædde på, at hun nemt ville give dig sin autograf!\n\nVær sød?", p="Engang vil jeg være en helt ligesom Jaina... nå, en drenge-helt altså.", c="WOW! Du fik Frue Jainas autograf til mig! Tusind tak! Og wow... hun skrev en personlig hilsen herpå - til mig! Jeg vidste, at hun ville være helt vild cool, og måske vil jeg en dag takke hende selv... når jeg bliver en helt for Alliancen!\n\nDu er den bedste, <Name>. Tak fordi du var så sød ved mig."},
  [560] = {n="Farrens bevis", l="Lever sækken med mudderfisk-hoveder til Marskal Rødsti i Sydstrand.", d="Du ved, <Name>, jeg vil helst ikke tage de her hoveder... Da du alligevel har styr på dem, vil du så være sød at levere dem til Rødsti for mig?", p="Hilsen, borger. Er du kommet for at låne en arm til at beskytte Sydstrand?", c="Farrens løbedreng, er du?\n\nHvis du hjalp Farren med at skaffe disse hoveder, så tak. Sydstrand har brug for hårdtarbejdende folk og indsats for at opretholde sit forsvar."},
  [561] = {n="Farrens bevis", l="Tal med Løjtnant Farren Ørnelle i Sydstrand.", d="Sig venligst til Løjtnant Ørnelle, at jeg ønsker, at han fokuserer sin indsats på slangefolket, der hærger den Østlige Strand. Når han har resultater, skal han rapportere til mig personligt.", c="Slangefolket, hva'? Rødsti må lige have fået de samme oplysninger som mig... Ha! Han får ingen forfremmelse fra mit arbejde. Lad mig forklare."},
  [562] = {n="Stormvind, ho!", l="Dræb 10 Dolkeryg-strandjægere og 10 Dolkeryg-sirener for Løjtnant Farren Ørnelle i Sydstrand.", d="Min tidligere mentor i Stormvinds bygardehær sendte mig en besked om, at Alliancens overkommando bliver bekymret over truslen fra slangefolket. Ifølge det, han har hørt, er der gode chancer for forfremmelse – eller i det mindste omplacering – for enhver, der beviser sit værd i den henseende.\n\nDer er bare ét lille problem... Jeg kan ikke klare slangefolket, <Name>. Jo, jeg kunne sagtens stoppe et fuldt barslagsmål eller slæbe en gnaven tigger væk, men slangefolket er for meget for mig. Du må hjælpe mig, <Name>!", p="Jeg har et brev klar til at sende til Major Samuelsen i Stormvind. Alt, jeg mangler, er resultaterne.", c="Når slangefolket er nedlagt i Sydstrand, bliver jeg en sikker kandidat til omplacering. Jeg får lov at se Stormvind igen... komme væk fra denne Lys-forladte havn."},
  [563] = {n="Omplacering", l="Lever Farrens rapport til Major Samuelsen i Stormvind Fæstning.", d="Det burde ikke være et problem at få min rapport set. Den nye kaptajn for vagten, Major Samuelsen, var min mentor, da jeg var stationeret i Stormvind. Det burde give ham mere end nok grund til at få mig overført tilbage til byen. Jeg får brug for, at du bærer min rapport til ham, dog... vi vil ikke have, at gamle Rødsti får nys om det.", p="Hilsen, borger. Må Stormvinds bygardehær være til hjælp?", c="Hvad er dette? Ah... så min opmærksomme elev har kastet sig over problemet med slangefolket i Sydstrand. Tak fordi du bragte mig dette, jeg vil helt sikkert tage det med i betragtning, når jeg gennemgår personaletildelingerne den næste måned."},
  [566] = {n="EFTERLYST: Baron Vardøs", l="Dræb Baron Vardøs og lever hans hoved til Højeksekutor Darthalia i Tarrens Mølle.", d="Efter ordre fra Højeksekutor Darthalia er mennesket kendt som Baron Vardøs efterlyst for forbrydelser mod De Forladte. Vardøs er kendt for at være et højtstående medlem af organisationen kendt som Syndikatet.\n\nHan blev sidst set i Højlandene i Alterac-bjergene, nord for Tarrens Mølle.\n\nHan er efterlyst død. Bring bevis på hans undergang til Højeksekutor Darthalia for at få belønningen.", p="Ah, <Name>. Er du måske kommet for at inddrive dusøren på hovedet af Baron Vardøs?", c="Produktivt arbejde, du udfører, <Name>. Med Baron Vardøs død bliver antallet af Syndikatets ledere mindre. Deres modstand og irritation vil være kortvarig."},
  [568] = {n="Forsvaret af Grommegol", l="Kommandør Angrebsgosh fra Grommegols basislejr vil have dig til at dræbe 15 Pisk-hale raptorer.", d="Hilsen, <Class>!\n\nDin ankomst til Grommegol er i sandhed belejlig. Som kommandør for Krigshøvdingens basislejr her i junglen er jeg bundet af ære til at sikre alle medlemmers sikkerhed i Horden. Vores mission om at sikre en tryg forsyningskæde til Stonard hindres af nogle af de lokale indbyggere.\n\nJeg giver dig ansvaret for at tynde ud i raptorbestanden uden for Grommegol. Når du har gjort væsentlige fremskridt, skal du vende tilbage til mig for omplacering.", p="Vores forsyningsindsats hindres stadig af den oprindelige raptorbestand, <Class>.", c="Din pligt blev udført med ære, <Class>."},
  [569] = {n="Forsvaret af Grommegol", l="Kommandør Angrebsgosh fra Grommegols basislejr vil have dig til at dræbe 10 Oger-brutter og 5 Oger-heksedoktorer.", d="Da vi første gang ankom til denne jungle, havde vi ikke planer om at føre krig mod de lokale stammer. Vores mission om at forsyne Stonard har højeste prioritet. Men der er opstået komplikationer. En lokal flok oger har besat Mizjah-ruinerne sydøst for Grommegol. Trods advarsler fortsætter de med at overfalde vores forsyningskaravaner.\n\nJeg giver dig ansvaret for at håndtere disse uforsonlige oger.\n\nRejs til ruinerne og forsøg at drive dem væk fra området. Det vil i det mindste sende et fast budskab.", p="Har du gjort fremskridt med ogerne i Mizjah-ruinerne endnu, <Class>?", c="Godt gået. Du har tjent Krigshøvdingen med ære."},
  [570] = {n="Mok'hårdins fortryllelse", l="Den Fjerne Seer Mok'hårdin i Grommegols basislejr vil have 8 Skyggekæbe-klør og en Upåklagelig Tigerinde-hugtand.", d="Junglens magi skal erkendes og tæmmes af Horden. Mine ritualer har vist sig succesfulde indtil nu. Jeg kan besværge meget kraftfulde fortryllelser. For dig, modige <Class>, skal jeg lave en helt særlig genstand.\n\nBring mig nogle Skyggekæbe-panterklør sammen med en tigerindes hugtand. Ikke enhver hugtand duer. Den skal være i upåklagelig stand.\n\nBæstene lurer i hele junglen, men du vil finde nogle tæt på, lige på den anden side af floden fra Mizjah-ruinerne mod sydøst.", p="Hvilke nyheder bringer du?", c="Din viden om junglen er stærk, <Name>. Disse prøver vil være perfekte. Jeg vil takke åndene for at ofre så fine bæster for Hordens sag."},
  [571] = {n="Mok'hårdins fortryllelse", l="Bring en gammel gorilla-sene til Den Fjerne Seer Mok'hårdin i Grommegol.", d="Det, jeg har brug for fra dig nu, vil være meget svært at skaffe.\n\nFor at holde alle disse fjer, klør og den upåklagelige hugtand på plads, kræver jeg et magisk bånd. Kun en gammel gorilla-sene vil virke.\n\nDu vil kun kunne finde en på en Ældre Tågedal-gorilla. De er kendt for at fouragere øst for Bytteviken.\n\nSenen skal være perfekt. Det kan tage en del drab, før du finder præcis det, jeg har brug for, men det vil være jagten værd.", p="Har lykken været på din side, <Name>? Var du i stand til at skaffe en gammel gorilla-sene?", c="En helt ideel sene, <Name>. Din indsats vil snart betale sig."},
  [572] = {n="Mok'hårdins Fortryllelse", l="Bring 10 Vildnis-snigerfjer til Den Fjerne Seer Mok'hårdin i Grom'gol-basislejren.", d="De ting du samlede fra kattebæsterne i Dalen er kun det første krav til en kraftfuld fortryllet genstand. Disse vildnis-smykker kombineret med mit shamanistiske ritual vil give dig et meget nyttigt redskab til at hjælpe Horden og Krigshøvdingen.\n\nMen nu skal du samle nogle Vildnis-snigerfjer til mig. Fjerene bæres traditionelt af bæsterne på deres armbånd. Du finder en stamme af raptorer lige syd for Grom'gol, ikke langt fra den store arena.", p="Bar din indsamling frugtbar?", c="Helt fortræffeligt. Jeg gør dem klar med det samme."},
  [573] = {n="Mok'hårdins Fortryllelse", l="Den Fjerne Seer Mok'hårdin fra Grom'gol behøver Hellig Kildevand. Han vil også have dig til at dræbe 10 Slangefolk-opdagere.", d="Der mangler kun ét sidste reagens for at fuldende fortryllelsen.\n\nI syd, mod den vestlige kyst, højt oppe over klipperne, ligger en Hellig Kilde. Denne kilde er genstand for stor strid blandt religiøse og mystiske lærde. Hver eneste race på Azeroth hævder, at kildevandet blev gjort guddommeligt for netop deres folk.\n\nMit sidste ønske til dig: bring mig Hellig Kildevand. Vær advaret. En ekspedition af Slangefolk-opdagere er rykket frem mod kilden. De må også tages hånd om.", p="Jeg er næsten klar til at fuldende fortryllelsen. Har du udført mit ærinde?", c="Med dette Hellige Kildevand er den seremonielle halskæde klar til fortryllelse.\n\nBær den med stolthed, <Name>, i Krigshøvdingens navn og til forsvar for den mægtige Horde."},
  [574] = {n="Særstyrker", l="Dræb 10 Kortsen-kommandoer og 6 Kortsen-krympehovedere.\n\nMeld dig hos Løjtnant Døren i Oprørslejren.", d="Nu hvor mange af hans almindelige tropper er reduceret, må du møde hans højt trænede styrker. Når de ikke er ude i vildmarken og slagter vore oprørssoldater, findes de dybt bagest i Kortsen-blandingen, i en hule de kalder Lagerhullet.\n\nJeg kender mange af Kortsens tropper personligt, og jeg ved, at de er dygtige, loyale og grusomme. Dette er ingen let opgave, jeg stiller dig, <Name>.\n\nNår du har besejret dem, skal du melde dig hos Løjtnant Døren, min befalingsmand. Han vil høre din rapport direkte fra dig.", p="Sergent Yohwa fortæller mig, at du er dygtig og modig, <Class>. Har du noget at melde?", c="<Name>. Sergent Yohwa stolede på dine evner, og jeg stoler på hende. Det nederlag, du har påført Kortsens styrker, er næsten for godt til at håbe på. Jeg havde frygtet, at vi oprørere stod alene, og alene kunne vi aldrig stå op imod Oberstens genialitet.\n\nMåske består håbet om vor overlevelse endnu."},
  [576] = {n="Hold Øje Med Den", l="Svimmel Enøje i Bytteviken vil have dig til at hente hans øje tilbage fra Blodsejl-fribytterne.", d="Avast! Hvem er der?\n\nArgh, jeg er intet værd uden mit specielt fortryllede øje. Nok er det slemt nok at have mistet mine øjne i kamp i første omgang! Men ved et held lagde vi til i Menetil, hvor en rejsende troldmand fortryllede et specielt glasøje, så jeg kunne se igen.\n\nI går aftes blev jeg overfaldet af nogle Blodsejl-fribyttere på vej ud. Tog mit øje, de gjorde! Det lader til, at de fyre har fundet vej til Bytteviken.\n\nVil du hjælpe en gammel søhund ved at hente mit øje tilbage?", p="Ahoj, min ven! Kan måske ikke se, men jeg kan lugte dig halvvejs over havnen.\n\nJeg kunne virkelig bruge mit øje tilbage. Kaptajnen kommer til at strigle mig, når han finder ud af, at mit øjeæble er i hænderne på de beskidte Blodsejl-fribyttere.\n\nHvad gavn er en udkigsmand, der ikke kan se? Udkigstønden var engang mit hjem...uden mine dødslamper ville jeg være heldig, hvis jeg kunne skrubbe bundvandet.", c="Lad mine tømmer ryste, og mine rystelser tømres! Du fandt mit smukke øje! Lad os se, om hun stadig passer.\n\n<Name> ahoj! Gudskelov, jeg kan se igen!!"},
  [577] = {n="Noget Skal Samles", l="Bring 5 Snapjaw-krokolisk-skind til Dryppelik i Bytteviken.", d="Nå, jeg har fået den grundlæggende form af støvlerne på plads, og de er ved at gå fint, men skindene, du bragte, er ikke helt nok til de indre lag.\n\n\"Hvad skal vi gøre, Dryppelik?\" Uden tvivl det spørgsmål, der ligger på dine læber, og ja, er det ikke heldigt, at du taler med Dryppelik, for han skal fortælle dig, hvad vi gør!\n\nDe indre lag bliver aldrig rigtig set, så vi får bare nogle af de tykkere, billigere skind fra krokoliskerne omkring Nazferiti-søen til at fylde støvlerne ud.", p="Dryppelik's Excelsior-læderstøvler, fineste håndværk, hundrede procent højkvalitets saltvands-krokolisk-skindstøvler. Ingen finere!\n\nDer er ikke meget at sætte ud på sådan en beskrivelse, vel?\n\nBortset fra måske, hvis du har de skind til mig?", c="Mine støvler... de er ligesom pølser, <Name>. Ser fantastiske ud, smager fantastisk. Jeg siger dig, de er fyldt med intet andet end de fineste ingredienser og kød, og du spiser det, og du elsker det.\n\nDet er sikrere--og mere behageligt--hvis du bare stoler på mig og ikke spørger for nøje, hvad der egentlig er indeni."},
  [578] = {n="Tidevandets Sten", l="Find den hjemsøgte ø for Baron Tyranbrand i Bytteviken.", d="Hvis der virkelig er en kobold-magiker og vandelementarer, der hjemsøger øen, kan det betyde, at Tidevandets Sten kan blive min!\n\nJeg vil have dig til at finde denne hjemsøgte ø... find ud af, hvad der foregår. Og hvis du måske vil vide mere om Tidevandets Sten, så tag denne skrivelse til Stormvindens Bibliotek, de burde kunne finde dig en kopi af bogen, hvor jeg første gang stødte på legenden.\n\nKan det være, at Gazbanne faktisk opdagede Stenen...?", p="Trollene besad virkelig nogle fantastiske magiske genstande, <Name>. Og nu har jeg måske chancen for at tilføje en til min store samling. Har du haft held med at finde kilden til rygtet?", c="Så historierne var sande! Utrolig!\n\nDog må vi finde ud af, hvordan vi besejrer forbandelsen over Tidevandets Sten, hvis vi skal hente den. Forbandelsen er magisk affære, vi får brug for en af de der troldmænd til at hjælpe os."},
  [580] = {n="Whiskey Tynds Tabte Grog", l="Whiskey Tynd i Bytteviken vil have dig til at bringe ham de flasker Pupellyverbos Portvin, han tabte.", d="Vi var ved at splejse hovedbraset af helvedes til ude ved Udsigtsklipperne, og Bagland lå lige i det fjerne. Troede havet ville sluge os hele.\n\nGamle Tynd ved alt om flydende mod! Kap'n havde en kasse Pupellyverbos Portvin, vi havde beslaglagt fra en kaper på vej til Stormvind.\n\nSå da stormen ude fra Bagland ramte, brød jeg ind i grogen. En stor bølge ramte og slyngede flaskerne over bord. Kap'n vil give mig en smag af katten, hvis du ikke hjælper mig med at få dem tilbage!", p="Synk mig! Jeg er næsten tør for sprut her! Kap'n vil lette anker, og Gamle Tynd bliver fanget tør som Tanaris-ørkenen. Og når han opdager, at hans portvin mangler... gudhjælpemig!", c="Lad mine tømmer ryste! Du fandt Kap'nens grog!\n\nJeg skylder dig stort, ven.\n\nDet ser ud til, at der brygger en storm udenfor. Måske holder jeg mig bare varm med en af de her flasker, mens vi venter på, at den går over...."},
  [582] = {n="Hovedjagt", l="Bring 20 Krympede Hoveder til Nimboya i Grom'gol-basislejren.", d="Vi må finde ud af, om Yenniku er død.\n\nDræb Blodskalp-hovedjægerne og tag deres Krympede Hoveder. Du må samle mange, mange hoveder, og jeg vil inspicere dem for at sikre, at Yennikus hoved ikke er blandt dem.\n\nOg hvis Yenniku blev dræbt af Blodskalperne, så må en 600 år gammel forbandelse falde over deres høvdings ånd, Gan'zulla!\n\nGå, <Name>. Du vil måske finde mange hovedjægere ved ruinerne af Zuuldaja og Zul'Kundo, langs kysten mod nord.", p="<Name>. Jeg frygter for vores høvdings søn. Har du de krympede hoveder, så jeg kan inspicere dem?", c="Tak, <Name>. Jeg vil inspicere disse hoveder for at sikre, at stakkels Yenniku blev skånet for hovedjægerens økse."},
  [584] = {n="Blodskalp-klanens Hoveder", l="Bring Gan'zullas Hoved og Nezzlioks Hoved til den boblende gryde i Grom'gol-basislejren.", d="Yenniku var ikke blandt hovederne, og jeg takker den Store Slange for det. Men vi er ikke tættere på at finde ham.\n\nVi må kende sandheden, og jeg frygter, at kun Blodskalp-høvdingen og hans hekselæge kender den. De er Mørkspyd-stammens fjender og vil ikke tale frit, så vi må tvinge sandheden ud af deres døde læber!\n\nBring mig hovederne af Gan'zulla og Nezzliok den Frygtindgydende, og læg dem i denne gryde.\n\nDe findes dybt i Zul'Kundo. Bring deres hoveder...så får vi dem til at tale.", p="Den grønlige bouillon i gryden bobler.", c="Du lægger hovederne af Gan'zulla og Nezzliok i gryden..."},
  [585] = {n="Samtale med Nezzliok", l="Bring et Balia'mah-trofæ, et Ziata'jæi-trofæ og et Zul'Mamve-trofæ til den boblende gryde i Grom'gol-basislejren.", d="<Nezzlioks hoved taler.>\n\nDet er sandt. Jeg ved, hvor Mørkspydernes barn blev ført hen. Du har besejret mig og bundet min ånd, men jeg siger intet uden forsoning!\n\nBlodskalperne er i krig med Kraniespalterne. For at vinde min gunst skal du stjæle 3 af deres trofæhovedkranier fra Kraniespalterne og placere dem her hos os, så min ånd får slaver i Nether. Ét kranie skal komme fra deres trofébunke i Balia'mah, et andet fra Ziata'jæi, og det sidste fra Zul'Mamve.", p="Jeg venter på kranierne...", c="Ja. Disse vil tjene mig godt. Når min ånd er befriet, vil jeg træde ind i Nether med tre gode tjenere!\n\nDu er en ære for din <Race>-klan, og du har forsonet mig."},
  [586] = {n="Samtale med Gan'zulla", l="Dræb 8 Kraniespalter-jægere, 6 Kraniespalter-hovedjægere og 4 Kraniespalter-berserkere.\n\nBring Ana'tæks Knuste Rustning til den boblende gryde i Grom'gol-basislejren.", d="<Gan'zullas hoved taler.>\n\nDe forbandede dig! Og forbandet være dine forfædre!!\n\nKun blod og hævn kan køle mit raseri, så hvis det er dit ønske, så... gør dette:\n\nKast dig ind i Kraniespalternes hjerte mod øst. Dræb de voldsomste blandt dem, og hvis du overlever...så knæk dig selv mod deres høvding, Ana'tæk den Grusomme. Ha! Bring mig hans knuste rustning, hvis du kan!\n\nMåtte han rive dine lemmer af og lade dig rådne og blive spist af ådselædere.", p="Selvom mit eget kød koger af min kranie, kan jeg stadig lugte din frygt.\n\nHa! Du vil aldrig fuldføre min opgave...", c="Jeg vil ikke tro det, men jeg kan ikke benægte det, du har gjort. Og mit raseri lindrer nu, hvor Ana'tæk er besejret.\n\nDin styrke vil drive dig til store gerninger, <Name>. Men en dag...vil jeg se dig i Nether, og vi vil igen måle kræfter.\n\nJeg vil vente."},
  [587] = {n="Op til Snus", l="Dæg i Bytteviken vil have dig til at bringe ham 15 portioner snus.", d="Ah, sølivet. Jeg siger ikke, at det er det gode liv, men det er mit liv.\n\nNår jeg kommer i havn, kan jeg godt lide at finde mig en god flaske grog og noget snus af høj kvalitet. Grimme vaner, men hvad er en pirat uden sine laster, ikke sandt?\n\nSå du kan forestille dig, hvor knust jeg blev, da jeg fandt ud af, at urtekyndigen her i byen er gået hen og har solgt op. Siger, at hans forsendelse blev kapret af de forbandede Blodsejl-raiderne.\n\nJeg vætter på, at en modig <Class> som dig kunne overtale dem til at dele varerne, hva'?", p="Har du haft held med at finde varerne, makker?", c="Godt gået, <Name>! Og lige før jeg skal sejle ud også! Kan ikke takke dig nok, gamle ven."},
  [588] = {n="Yennikus Skæbne", l="Tal med Kin'weelay.", d="<Nezzliok taler.>\n\nDu har forsonet mig selv og min høvding, så jeg vil fortælle dig det, du søger at finde ud af...\n\nUng Yenniku er tabt for sin klan.\n\nHan blev taget af hekselægen Zanzil den Udstødte. Nu kontrollerer Zanzil ham, krop og sjæl, og kun den mest potente magi kan befri ham.\n\nEn magi, du ikke har, <Class>.\n\nMåske kan dine Mørkspyd-allierede tilbyde et håb om Yennikus frelse. Men det tvivler jeg på.", c="Zanzil den Udstødte??\n\nHvis Yenniku holdes fanget af den troldmand, en ond og mægtig hekselæge, så frygter jeg, at kun et svagt håb er tilbage. Svagt. Og lille som det mindste insekt.\n\nMen alligevel er det håb."},
  [589] = {n="De Syngende Krystaller", l="Bring 3 Pulserende Blå Skår til Kin'weelay i Grom'gol-basislejren.", d="Legender fortæller om en juvel, skjult dybt i Kvælertorns hjerte. Vi kalder den Sindets Øje, og den har store kræfter. Hvis du får dette Øje, kan vi måske bruge det til at bringe den tabte Yenniku tilbage fra mørket.\n\nJeg vil rådføre mig med junglens ånder for at finde Sindets Øje. Imens går du ind i Krystalåre-minen, sydøst herfra, og samler Pulserende Blå Skår fra Jernkæbe-basilisker. Skårene er sjældne, men vi får brug for deres magi for at bøje Sindets Øje efter vores vilje.", p="Har du skårene, <Name>? De er nødvendige for mit sidste ritual, når vi har Sindets Øje.", c="Du har gjort det godt, <Name>. Disse skår er velformede. Allerede hører jeg dem synge for mig.\n\nOg mens du var væk, talte jeg med junglens ånder. Jeg ved, hvor Sindets Øje hviler...\n\n...Og hvem der vogter det."},
  [590] = {n="En Skurks Aftale", l="Besejr Calvin Montague i Dødsklokken.", d="Hvad?\n\nHvad?!\n\nDu vil have penge? Jeg skylder dig ingen penge.\n\nBrev? Hvilket brev? Åh, du vil kæmpe så? Fint, makker... lad os gøre det! Skylder dig penge....", c="Utroligt! Hvilken dygtighed!\n\nTænkte du ville være et let bytte, <Name>. Fik mig godt, det gjorde du.\n\nHer er mønten, jeg lovede... ikke så meget, som jeg sagde, men det skyldes, at jeg løj for dig i første omgang."},
  [591] = {n="Sindets Øje", l="Bring Sindets Øje til Kin'weelay i Grom'gol-basislejren.", d="Sindets Øje holdes af en oger-magiker, øst herfra og dybt inde i Mosh'Ogg-ogervolden. Hans navn er Mai'Ondt. Jeg kender ham fra dengang Mørkspyddene boede i Kvælertorn - han er ondskabsfuld, og hans magi er stærk.\n\nOg hvis han har Sindets Øje, så bliver hans magi endnu stærkere.\n\nDu må møde Mai'Ondt og rive Sindets Øje fra ham. Det er en farefuld opgave, men det er vores eneste håb om at redde Yenniku.", p="Hilsner, <Name>. Åndene synger din tapperhed lov, men de fortæller mig ingen historier om din færd mod Mai'Ondt.\n\nHar du Øjet?", c="Du hentede øjet! Din styrke er stof til legender, <Name>!\n\nOg ved at hente Øjet må du have besejret Mai'Ondt og sendt ham til Nether. Det er derfor, åndene ikke ville nævne ham før.\n\nDet er godt, at han er væk fra kødets og knoglernes verden, men nu hvor han er i åndernes rige...frygter jeg, at han vil begynde et nyt herredømme.\n\nMen det er en bekymring til en anden gang. Nu må jeg udføre et ritual for at bøje Sindets Øje til vores behov..."},
  [592] = {n="Redning af Yenniku", l="Bring den Fyldte Sjælssten til Nimboya.", d="Jeg har omformet Sindets Øje til en Sjælssten. Dens formål er todelt: du skal bruge den til at bedøve Yenniku, og når han er bedøvet, skal du placere den på hans hoved for at fange hans sjæl.\n\nBring derefter stenen til Nimboya.\n\nYenniku opholder sig hos Zanzil den Udstødte, ved Aborazs Ruiner, langs Krystalkysten på det fjerne Kvælertorns Forbjerg.", p="<Name>. Kin'weelay fortalte mig, at du drog ud for at fange Yenniku.\n\nEr det sandt? Har du ham?", c="Du har gjort det! Du befriede Yenniku fra Zanzils vilje og fuldførte den mission, jeg havde troet var så desperat.\n\nVores stamme vil huske dit navn i sange, <Name>, og vi vil meisle din historie i sten, så den lever evigt."},
  [594] = {n="Besked i en Flaske", l="Find forfatteren til beskeden i flasken.", d="Seddelen læser, i ret pæn håndskrift:\n\nTil enhver, der kan hjælpe mig-\n\nVær venlig, mit behov for hjælp er akut. En stor Himmelmanke holder mig fanget på en ø i Sydhavet.\n\nStjernerne om natten er fremmede for mig og skjult af junglens træer, men på de klareste dage ser jeg Vildkysten mod nordvest, og hvad der synes at være store sejlskibe mod sydvest.\n\nJeg beder dig, min kommende redder, venligst hjælp mig.", c="Er du kommet for at befri mig?"},
  [595] = {n="Blodsejl-fribytterne", l="Første Styrmand Crazz vil have dig til at undersøge bugten nord for Bytteviken.", d="Du lyder ivrig efter at arbejde, makker. Ikke sikker på hvorfor en landkær <Race> <Class> tilbyder hjælp til Sortvands-raiderne, men jeg vil ikke vende dig væk.\n\nVores skib lagde lige til her i Bytteviken, og ordet går, at vores rivaler--de forbandede, beskidte Blodsejl-fribyttere--er blevet set over hele det sydlige Kvælertorn.\n\nAlle drengene har travlt med at tømme grogen og lede efter damer! Det, jeg har brug for, er en spejder.\n\nUndersøg bugten lige nord for Bytteviken langs Vildkysten og se, hvad du finder.", c="Oven på tønden finder du et kort med noget hastigt skrevet tekst på sammen med nogle mønter."},
  [597] = {n="Blodsejl-fribytterne", l="Rapporter dine fund til Første Styrmand Crazz i Bytteviken.", d="Kortet viser Bytteviken med et rødt \"X\" tegnet præcist på det sted, hvor du står.\n\nDen skrevne tekst lyder:\n\n\"I mænd skal sikre en lejr på dette sted og holde jer stille. Vent på signalet fra den sydlige kommandopost, før I angriber. Hvis nogen nærmer sig jer, så dræb dem.\"", c="Jo, jeg husker dig, <Class>. Tilbage fra spejding ser jeg...."},
  [598] = {n="Kløvet Knoglehalskæde", l="Bring 25 Kløvede Knoglehalskæder til Kin'weelay i Grom'gol-basislejren.", d="Nu hvor du har samlet Blodskalp-trofæer, har jeg en anden opgave til dig. Kraniespalterne, en trollestamme, bor mod sydøst, og i årevis har vi kæmpet mod dem. Selvom Mørkspyddene ikke længere bor i Kvælertorn, er vi bundet til vores konflikt med Kraniespalterne.\n\nSå jag dem. Saml deres Kløvede Knoglehalskæder og vend tilbage til mig. Hjælp os i vores krig, og du vil opnå Mørkspyddenes venskab.", p="Kraniespalterne vil forbande dagen, de førte os i krig! Er din opgave fuldført?", c="Din styrke er stor, <Name>, som du har skaffet disse halskæder. Kraniespalterne falder for dig som unge træplanter, der trampes ned af en basilisk!\n\nDine gerninger er en gave til os."},
  [599] = {n="Blodsejl-fribytterne", l="Rapporter det planlagte Blodsejl-angreb til Flådemester Søhest.", d="Lad mine tømmer ryste! Så Blodsejl-fribytterne planlægger et slags angreb på Bytteviken? Hvilken frækhed af de skurke. Bytteviken vil altid blive styret af Sortvands-raiderne!\n\nDette er større, end jeg troede. Rapporter det, du har lært, til Flådemester Søhest med det samme! Den gamle søhund er et sted i byen....", c="Blodsejl-fribytterne angriber Bytteviken? De kunne lige så godt kaste sig ud fra Udsigtsklipperne. Alligevel har du ved at bringe mig disse oplysninger gjort min flåde af kaptajner en stor tjeneste. Sortvands-raiderne takker dig."},
  [601] = {n="Vandelementarer", l="Skaf 6 Vandelementar-armbånd til Baron Tyranbrand i Bytteviken.", d="Vandelementarerne blev uden tvivl fremkaldt af Gazbanne, kobold-troldmanden, der ryges for at have opdaget Tidevandets Sten. Som du måske ved, forbander Tidevandets Sten sin bærer og får ham til at blegne ind og ud af eksistens...\n\nMåske kan vi finde en måde at modvirke forbandelsen på. Vi kan få en magiker fra Dalarn til at analysere de magiske rester på et af vandelementarens armbånd. Jeg har brug for, at du tager tilbage til øen og henter nogle få prøver.", p="Har du haft held, <Name>?", c="Hm, jeg har ikke øjet til at undersøge disse armbånd for at se, om nogen af dem kan være til nytte, men jeg er sikker på, at mindst ét af dem kan hjælpe. Tag dem til Dalarn og få en magiker til at kigge på dem.\n\nEfter alt kan jeg ikke bare forlade Bytteviken for at snakke med de trættende gamle magikere.\n\nIkke at jeg er bekymret for, at nogen vil forsøge at skubbe sig ind i rollen som ny baron. Ingen krydser Tyranbrand og lever for at fortælle om det."},
  [602] = {n="Magisk Analyse", l="Bring vandelementar-armbåndene til Ærkemager Ansærem Runevæver i Dalarn.", d="Fra det jeg har hørt, er magikerne i Dalarn travlt optaget med genopbygningen af deres ødelagte by, jeg er sikker på, at du kan finde en af dem, der vil spare lidt tid til at kigge på armbåndene. Hvis der er noget, jeg ved om magikere, så kan de ikke modstå en magisk gåde.\n\nTag posen med vandelementar-armbånd og se, om de kan kaste lys over Stenens forbandelse. Led især efter Ærkemager Ansærem Runevæver. Jeg har haft med ham at gøre før, og hans viden er enorm.", p="Hvis du ikke har noget imod det, er jeg ret travlt optaget lige nu.", c="Tidevandets Sten? Meget interessant. Det kan overraske dig at vide, at jeg for flere år siden skrev en lærd afhandling om legenderne om Gurubashi-imperiet. Jeg ved en del om Stenen.\n\nMindst ét af disse armbånd ser ud til at have nogle magiske rester, som jeg kan analysere.\n\nLad os se, hvad jeg kan se..."},
  [603] = {n="Ansærems Nøgle", l="Tal med Kattelyn i Bytteviken.", d="Magikeren, der er i besiddelse af Stenen, forstærker dens kraft gennem et fokuspunkt... et slags alter. Du burde kunne forstyrre det ved at overmande det.\n\nSom det sker, ved jeg præcis, hvad der skal til: en gammel dolk, endnu en troldrelikvie. Der er bare ét... lille problem.\n\nDu ser, jeg fandt dolken, mens jeg forskede i Kvælertorn, men jeg gav den til min viljestærke datter, Kattelyn, som løb af sted til Bytteviken for at blive pirat.", c="Min dolk? Hvad er du, en slags komiker?\n\nHvad? Vil du bare have mig til at gentage historien om, hvordan jeg gik fra at være den bedste knivkæmper i Bytteviken til piratdomenes latterliggjorte?\n\nJeg tabte en knivkamp til en af Blodsejl-fribytterne--et bundt rigtige bastarder er de!--og han tog mit blad som bytte.\n\nDet er ikke, som om jeg kan klare mig som knivkæmper med fornærmelser og en skarp tunge alene..."},
  [604] = {n="Blodsejl-fribytterne", l="Flådemester Søhorn i Bytteviken vil have, at du dræber 10 Blodsejl-sabelsvingerne og bringer Blodsejl-kortene og Blodsejl-ordenerne tilbage.", d="Skørbuk taler højt om din hengivenhed over for Sortvands-razziaerne. Jeg vil betro dig en mission af yderste vigtighed for flåden.\n\nTræng ind i den såkaldte sydlige kommandopost, som Blodsejl-fribytterne har etableret på Vildstranden. Razziér lejren. Bring mig deres kort sammen med deres skriftlige ordener. Så skal vi se præcis, hvad de skiderikker har gang i.", p="Ahoy, <Name>. Hvilke nyheder bringer du fra Blodsejl-lejren mod syd?", c="Perfekt, <Name>. Nu hvor vi kender deres plan, er det bare et spørgsmål om tid.\n\nOg tænk sig, dunderhovederne har kastet anker lige uden for kappen...."},
  [608] = {n="Blodsejl-fribytterne", l="Flådemester Søhorn i Bytteviken vil have, at du dræber Kaptajn Stillevand, Kaptajn Kølhaling og Flådemester Firallon.", d="Hvor har Firallon nogle nerver! Han kunne ikke sejle en skiff gennem Krystalsøen, endsige lede en hel flåde mod os.\n\nBlodsejl-fribytterne skal betale for deres skødesløshed. Nu hvor vi kender deres angrebsplan, kan vi slå til først, før de ved, hvad der ramte dem.\n\nMen hvorfor sende hele flåden for at udføre en enkelt modig eventyrgruppes arbejde? <Name>, tag nogle af dine dygtigste kammerater med ud til Firallons landingsplads og snig jer ind og myrd Blodsejl-ledelsen. Deres flåde synker snart efter....", p="Hvad er problemet, <Name>? Vi må angribe, før Blodsejl-fribytterne gør det!", c="Ah, for en fantastisk dag for Sortvands-razziaerne! Tre hurraer for dig, <Name>!"},
  [610] = {n="\"Pæne Dreng\" Dunkan", l="Hent Katrines dolk fra \"Pæne Dreng\" Dunkan.", d="Min FAR sendte dig? Jeg troede, den gamle krukke havde givet op på mig nu.\n\nDet var ikke rigtig hans skyld, at jeg stak af, han skulle bare ikke have forventet, at jeg ville være villig til at leve et kedeligt liv med at læse støvede bøger og omgås gråhårede, stive, pedantiske magikere!\n\nHvis du har brug for min dolk, må du hente den tilbage fra \"Pæne Dreng\" Dunkan, en af Blodsejl-fribytterne. Stik noget mellem hans skuldre, så er jeg sikker på, at han giver den fra sig.", p="Jeg er aldrig blevet slået før, ved du nok, <Name>? Jo, jeg er blevet skåret, det kan man jo ikke undgå i en knivkamp, men han slog mig bare i hovedet, så jeg blev bevidstløs. Da jeg vågnede, var min klinge væk.\n\nSå meget som mit øgenavn måske antyder, har jeg stadig brug for en kniv til at kæmpe, og for mig skal det være lige præcis den.", c="Du slog Dunkan? Jeg regner med, at du ikke er så grøn bag ørerne, som du så ud til ved første øjekast.\n\nJeg antager, at det også betyder, at jeg ikke skal udfordre dig til en kamp lige foreløbig!"},
  [611] = {n="Tidevandets Forbandelse", l="Ødelæg Tidevandets Alter med Katrines Klinge, dræb Gazbøn og bring Tidevandets Sten og Katrines Klinge tilbage til Baron Tyranbrand.", d="Så du leder efter et slags alter? Nå, jeg er ingen ekspert i trolderuiner som min far, men jeg har hørt om en sunket trolde-by ude ved den ø, du leder efter. Måske skulle du prøve der.\n\nDu fik min kniv tilbage til mig, så jeg regner med, at du kan låne den... men jeg vil have den tilbage, når du er færdig!", p="Har du hentet Tidevandets Sten til mig, <Name>? Jeg har allerede ryddet en plads og købt et fint stativ til den.", c="Fantastisk! Tidevandets Sten! Den skal have en fremtrædende plads i min samling af gamle trold-artefakter. Så du, hvordan det næsten ser ud, som om et tidevand er fanget i dens overflade? Storslået!"},
  [614] = {n="Kaptajnens Kiste", l="Bring Smudders Kiste til Hylebury Smudder i Bytteviken.", d="Jeg plejede at sejle et skib herfra helt til Skralleby i Kalimdør. Jeg var en succesfuld kaptajn med et fejlfrit ry.\n\nIndtil...\n\nDe forbandede havgiganter ødelagde mig! De knuste mit skib, dræbte mit mandskab og satte mig i en redningsbåd mod Bytteviken. Og en af giganterne, Gorlask, stjal min Kaptajnens Kiste. Han sagde, at han ville have den som snusdåse. Den frækhed!\n\nJeg hører, at Gorlask vandrer langs kysten øst herfra. Find ham og få min kiste tilbage! Gør du det, har du fortjent en kaptajns taknemmelighed.", p="Ahoy, <Name>! Fandt du Gorlask? Den kiste var min yndlings, og det har et skjult rum, der gemte mine største skatte!", c="Du fandt det! Åh, en lykkedag, det her er! Tak, <Name>. At få min kiste tilbage slukker noget af ilden i mig.\n\nMen min hævn er ikke fuldført..."},
  [615] = {n="Kaptajnens Kutlas", l="Tal med Sprøgge.", d="Efter jeg mistede mit første skib til de giganter, købte jeg et andet. Jeg døbte det Smudders Hævn, fyldte det med forsyninger og mandskab og drog ud for at finde skurkene. Jeg fandt dem, men...de besejrede mig. De knuste Smudders Hævn, dræbte mit andet mandskab og satte mig i endnu en redningsbåd.\n\nDenne gang stjal en anden af giganterne, Negolask, min kutlas.\n\nKonfronter Negolask og bring mig min kutlas!\n\nTal med Sprøgge. Han var min kok på Smudders Hævn og overlevede det sidste angreb. Han kan hjælpe dig med at finde kæmpen.", c="Hej hej, <Name>. Kaptajnen fortalte mig, at du er på vej efter Negolask, hva'?"},
  [616] = {n="Den Hjemsøgte Ø", l="Tal med Baron Tyranbrand i Bytteviken.", d="Baron Tyranbrand har fået mig til at holde øjnene åbne for rygter om det mærkelige og malplacerede i Bytteviken og Stranglethorn. Jeg plejer ikke at tro meget på spøgelseshistorier, men jeg hørte nogle søfolk i kroen snakke om en hjemsøgt ø ud for kysten. Vandelementarer og et rasende kobold-spøgelse, siger de.\n\nHvis du skal over og tale med Tyranbrand, kunne du så fortælle ham den historie?", c="Interessant. For noget tid siden husker jeg, at jeg læste en bog, der antydede...\n\nAh, selvfølgelig, det var en trolde-legende. Hvis det Krazek rapporterer er sandt, kan jeg måske snart tilføje Tidevandets Sten til min samling af gamle artefakter og relikvier."},
  [617] = {n="Akirs af Bundt", l="Bring 10 bundter Akirs-siv til Kaper Blodsen i Bytteviken.", d="Leder du efter arbejde, <Name>? Jeg har måske noget, hvis du er klar til en lille udfordring.\n\nJeg har en ven ved navn Groy, som tjener en formue på at sælge det, slangefolket kalder akirs-siv: det er en slags værdifuldt havsiv. Jeg er ikke helt sikker på, hvad det bruges til, men han betaler godt for bundter af varen.\n\nBring mig ti stængler af det, så har vi forretninger at gøre. Slangefolket er sidst set langs stranden nord for her.", p="Hvis du ikke har noget ærinde hos mig, så gå din vej, <Name>.", c="Godt gået, <Name>. 10 stængler akirs-siv var vel ikke så stor en udfordring, hva'? Ikke for at være uforskammet over for slangefolket, men hey, alle skal jo tjene til livets ophold."},
  [618] = {n="Mød Negolask", l="Bring 10 grillede musvågevinger og 5 flasker jungleranke-vin til Kaptajn Smudders redningsbåd.\n\nDræb Negolask, og bring Smudders Kutlas til Kaptajn Smudder i Stranglethorn.", d="Negolask er en sulten kæmpe.\n\nDa giganterne ødelagde vores skib, gik Negolask direkte efter mit køkken. Han var ikke sulten efter mandskab som de andre giganter. Negolask ville have vin... og mine grillede musvågevinger. De er min specialitet, og jeg måtte helt til Ødelandene for opskriften!\n\nHvis du vil lokke kæmpen, så skaf noget vin og en bunke musvågevinger. Læg dem i vores gamle redningsbåd, sydøst herfra langs kysten. Når Negolask lugter al den mad, kommer han helt sikkert!", p="Fik du min kutlas, <Name>?", c="Du fik min kutlas fra Negolask! Jeg kan ikke tro min lykke, <Name>! At møde dig har vendt min held til det bedre, det er der ingen tvivl om!\n\nTak! Og hvis jeg nogensinde får et nyt skib, og du har lyst til at sejle på havet, vil du være min æret gæst."},
  [620] = {n="Den Monogrammerede Sjærp", l="Returner den monogrammerede sjærp til dens ejer.", d="Denne fine sjærp har bogstaverne \"HS\" broderet langs kanten.", p="Hej. Har du et ærinde med mig?", c="Du har fundet min sjærp? Så...må du have dræbt havgiganten Mok'rask! Hurra!\n\nJeg er glad for, at den skumle skurk er død - Mok'rask var en af tre havgiganter, der knuste mine skibe og dræbte mit mandskab.\n\nTre gange.\n\nDu er en <Class> af værdi, <Name>."},
  [621] = {n="Sanzils Hemmelighed", l="Bring 12 prøver af Sanzils Blanding til Crank Brusebob i Bytteviken.", d="Sanzil den Udstødte bor sammen med sine følgere i Jubuvai- og Aborass-ruinerne, nordøst for Bytteviken. Han er forvist fra sin stamme. Hvorfor? Ja...\n\nSanzil har metoder til at bøje andres sind, og hans ledere frygter ham. Han bruger en blanding af junglens planter på sine følgere for at undertrykke deres vilje og styrke deres kroppe.\n\nHans blanding ville være meget værd for dem, der ønsker at kontrollere andre.\n\nBring mig prøver af hans blanding, så finder jeg en anvendelse for dem.", p="Har du prøverne af Sanzils Blanding??", c="Ah, meget godt! Her er din løn.\n\nOg her er en lille ekstra ting... for din diskretion."},
  [622] = {n="Vend tilbage til Korporal Kalæb", l="Bring Krazeks lappede gryde til Korporal Kalæb i Oprørslejren.", d="Mens du var væk, lappede jeg den gryde, du bragte mig. Jeg tilføjede endda en ekstra damplyd, og se! Der er en ny hakker i bunden, der kan skære igennem lårben!\n\nJa ja, Krazeks Lergryde er en 100% kokke-glæde! Jeg er sikker på, at dens ejer bliver tilfreds.", p="Hej, <Name>. Nåede du til Bytteviken? Fik kobolden Krazek lappet min gryde??", c="Den er lappet! Det er fantastisk, nu kan jeg få middagen i gang! Tusind tak, <Name>.\n\nJeg håber, du havde det godt i Bytteviken. Det sted kan blive ret voldsomt, og... jeg har hørt rygter om, at kobolderne nogle gange slæber berusede søfolk hen til deres slavebåde og tager dem med til ved-ikke-hvor... for at gøre ved-ikke-hvad..."},
  [623] = {n="Akirs af Bundt", l="Bring et bundt Akirs-siv til Kaper Groy i Theramør.", d="<Name>, siden du er her, fik jeg en besked fra Groy, mens du var væk. Han nævnte, at han var tilfreds med den sidste forsendelse, der ankom, og at han har en kunde, der vil have mere af varen med det samme.\n\nJeg tager ikke til Theramør om en uge, men hvis du vil påtage dig rejsen, er der ingen grund til, at du ikke kan tage varen med for mig.\n\nHar du lyst til eventyr? Du ved vel, hvor Støvsumpen ligger, ikke? Jeg ville dog være forsigtig, Theramør kan være farligt, hvis du er i den forkerte slags selskab.", p="Ja?", c="Hvad?! Jeg har meget bedre ting at lave end at snakke med sådan en som dig, <Class>. Gør det det umagen værd, eller forsvind fra mit ansigt.\n\nHva'? Blodsen sendte dig, hva'? Nå, hvad har du til mig?\n\n<Kaper Groy undersøger bundtet omhyggeligt.>\n\nIkke dårligt, slet ikke dårligt. Endnu et bundt vil gøre min kunde ganske tilfreds.\n\nJeg regner med, at dit næste spørgsmål handler om penge, hva', <Class>? Det gør det jo altid!\n\nVær så god, tag denne mønt og et råd: kom væk fra mine kajer."},
  [624] = {n="Kortellos Gåde", l="Løs gåden!", d="Der er en udsmykket, flittigt brugt bro\nØst for Dødevind og syd for Rødryg\nDer under venter noget på dig\nNogle kalder det et vink, andre et spor\nDer vil det ligge i endeløse morgendage\nVentende på sin tid i Sorgernes Sump", c="Den våde pergament indeholder den næste ledetråd...."},
  [625] = {n="Kortellos Gåde", l="Løs gåden!", d="Et fjernt land i Kalimdør venter\nHvor fare har knust håb og skæbner\nØst for Ødemarken er vejret barskt\nMørke og fare hærger Støvsumpen\nMen der ligger et spor for dem, der står distancen\nVentende på at blive fundet i en hule i sydvest", c="Du finder en muggen rulle."},
  [626] = {n="Kortellos Gåde", l="Løs gåden!", d="Til Herrelande! Det store land af uro\nHvor modige soldater slider med døden\nFind din vej gennem den store ufred\nDer finder du enden på denne opgave\nLangs kysten af Bagland, ved foden af de store vandfald\nUnder vandet kalder din skat på dig!", c="Du åbner kisten og opdager...."},
  [627] = {n="Tjeneste for Krazek", l="Bring 4 læs Mindre Blodsten-malm til Krazek i Bytteviken.", d="Der er en bjerghule i Tørhvisker-kløften, langt mod nord i Arathi-højlandet. I den hule findes sjælden malm: blodsten. Blodstenen i denne hule er ikke af højeste kvalitet, men selv blodsten af lav kvalitet er værdifuld... for dem, der har viden til at bruge den.\n\nJeg vil gerne have noget.\n\nJeg vil reparere din lergryde, men mens jeg arbejder på den... bring mig prøver af blodsten. Bring nok, så giver jeg dig endda en bonus.\n\nÅh, og hvis du ikke har evnerne til at udvinde den... find en, der har!", p="Hej, <Name>. Fik du held med at skaffe blodstenen?", c="Nåh, herligt! Det var en stor tjeneste, du gjorde mig.\n\nHer er din betaling..."},
  [628] = {n="Excelsior", l="Bring en Ældre Krokolisk-hud til Dryppelik i Bytteviken.", d="Med det indre færdigt er alt, der mangler, det ydre lag. Til det bruger jeg kun de bedste ældre krokolisk-skind. De er mere holdbare og et bedre lærred – om man vil – til at tilføje de mønstre og accenter, der gør Dryppeliks Excelsior-linje til noget særligt.\n\nDet er svært at finde det perfekte skind dog; det eneste, der passer til min plan, er huden fra en ældre saltvands-krokolisk. De ældre kommer kun frem for at forsvare de andre saltvandskrokoliskerne, så du må nok dræbe et par stykker for at lokke en frem.", p="Jeg har læst et sted, at saltvandskrokoliskerne langsomt uddør... dårlige nyheder for min forretning, ikke?\n\nUnder alle omstændigheder håber jeg, du har det ældre saltvands-krokolisk-skind til mig!", c="Fantastisk! Takket være din hjælp får jeg denne ordre udfyldt og sendt til Direktør Riddlevox med næste båd til Undergrunden. Endda før tid!\n\nFor al dit hårde arbejde, her, jeg lavede nogle ekstra, så tag et par. Det er på Dryppelik.\n\nOg husk, der findes ingen støvle så fin som en fra Dryppeliks Excelsior-linje!"},
  [630] = {n="Besked i en flaske", l="Dræb Kong Mukkel og vend tilbage til Prinsesse Poobah med nøglen for at befri hende.", d="<Name>, jeg sætter min lid til dig og enhver, du kan samle for at hjælpe med at befri mig. Den store Himmelmanke-konge Mukkel er min fangevogter. Han befaler øens dyr, og de holder mig her mod min vilje med hjælp fra denne kæde. Hvis du kan slå ham ihjel og finde nøglen til denne lænke, står jeg dybt i gæld til dig.\n\nJeg hører ham ofte mod sydøst på øen, men vær venligst forsigtig: han er ikke at spøge med.", p="Jeg takker mine forfædre for, at nogen er kommet for at hjælpe mig. Har du nøglen, der kan befri mig?", c="<Name>, du har reddet mig fra en stor vanære. Havde det været inden for min magt, ville jeg tilbyde dig en plads blandt min stamme. Men lige nu kan jeg kun tilbyde dig dette tegn for det mod og den ædelhed, du har vist."},
  [637] = {n="Sulle Ballons Brev", l="Lever Sulle Ballons Brev til Sara Ballon.", d="Den vandlogte og krigshærgede konvolut opløses i dine hænder og efterlader dig med nogle få sider af et brev i din hånd, skrevet med omhyggelig pleje.\n\nBrevet er adresseret til en Fru Sara Ballon af Jernsmede og begynder med \"Min kære Sara....\"", p="Du ser ud, som om du har rejst en lang vej og set meget uro i din tid, <Class>. Disse tider, vi lever i, sætter sjælen på prøve. Hvad nyheder bringer du mig nu?", c="Siger du, at du så min Sulle klemt fast under det iskolde vand? Sig det ikke!\n\nLad mig læse, hvad han skrev...."},
  [638] = {n="Trollebane", l="Rejs til Hammerfald i Arathi-højlandet og tal med Zangu.", d="Med Torås Trollebane død og Strømgarde i ruiner har Vol'dyn givet besked om, at vi skal gøre alt for at snuppe det legendariske sværd Trolledræberen fra menneskenes hænder, så vi kan bruge det i de kommende kampe mod trolderne i Zul'Gorbø.\n\nZangu, en af vores erfarne jægere, blev sendt til Hammerfald i det nordøstlige Arathi-højland for at føre tilsyn med dens anskaffelse.", c="Hvordan går det, <Class>? Opgaven, som Vol'dyn har sat os, bliver svær, og enhver hjælp, du kan yde, vil blive værdsat og være nødvendig."},
  [639] = {n="Strøm-sigillet", l="Hent Strøm-sigillet til Zangu i Hammerfald.", d="I oldtiden kæmpede trolde mod det Arathoriske Imperium og vores dygtigste modstander, Lord Ildæus af Strøm, kaldet Trollebane. Han red i kamp med Trolledræberen i hånden, på deres gamle tunge kaldet Trol'kalar.\n\nMen nu er Trollebanes sønner svækket, deres højborg bragt til ruin.\n\nSværdet er beskyttet af flere sigiller, der blev delt blandt de overlevende fra Strømgarde, og dem må vi hente.\n\nDet første blev taget af Syndikatet; en af deres mænd i Strømgarde burde have det.", p="Har du fundet det første sigil endnu? Det bæres sandsynligvis af en af Syndikatets agenter i Strømgarde.", c="Fremragende, makker. Det er en god start på at samle de sigiller, vi skal bruge for at fjerne Trolledræberen fra Trollebanes grav."},
  [640] = {n="Det Brudte Sigil", l="Hent de 11 sigil-fragmenter fra forsvarerne i Strømgarde og bring dem til Tor'gon i Hammerfald.", d="Torås Trollebanes grav er beskyttet af tre sigiller – hvoraf det første du hentede fra Syndikatet. De to andre vil være sværere at få, da de holdes af den fast forankrede Strømgarde-milits.\n\nTorradins sigil blev delt i elleve stykker af Torås' søn, Galæn, og spredt blandt Strømgardes forsvarere. Hent stykkerne og bring dem til Tor'gon, trolde-shamanen, så kan han binde dem sammen til det komplette sigil.", p="Throm'ka, <Class>. Zangu fortalte mig, at du havde brug for min hjælp?", c="Ah, du skal have mig til at rekonstruere dette sigil? Det burde ikke være for svært... alle stykkerne ser ud til at være her, og den magiske struktur vil være nem at genskabe.\n\nDu vil måske lukke øjnene."},
  [641] = {n="Torradin-sigillet", l="Bring det genskabte Torradin-sigil til Zangu i Hammerfald.", d="Rekonstruktionen lykkedes fejlfrit. Sigillet kan nu bruges til at låse seglet på Trollebanes grav op. Bring det tilbage til Zangu; han har sikkert flere opgaver til dig.", p="<Name>! Har du det andet sigil?", c="Vi er halvvejs til at kunne fjerne Trolledræberen fra Trollebanes grav. Vi er ikke helt sikre på, hvor det tredje sigil er, da dets holdere ser ud til at flytte rundt i Arathi ganske meget, men jeg har tillid til, at du kan finde det."},
  [643] = {n="Arator-sigillet", l="Hent Arator-sigillet og bring det tilbage til Zangu i Hammerfald.", d="Selvom de næppe kan siges at kontrollere Strømgarde, endsige hele Arathi-højlandet, så kører menneskenes prins rundt med resterne af sin kavaleri over landskabet. Jeg forstår ikke, hvorfor han gør det, men hvem forstår egentlig menneskenes tankegang, hm?\n\nUanset hans grund, og endnu vigtigere, han har givet et af sigillerne til Løjtnant Modkald, deres kavalerileder. Find ham og bring hans sigil tilbage til mig.", p="Modkald vil ikke være let at spore, <Name>. Til hest kan han hurtigt dække terræn. Ikke desto mindre må vi have hans sigil.", c="At miste deres kavalerileder vil blive et stort slag for Strømgarde-forsvarerne. Endnu bedre er det, at vi kun er ét sigil fra at kunne få Trolledræberen for os selv."},
  [644] = {n="Trollebanes Segl", l="Dræb Prins Galæn Trollebane og bring Trollebanes Segl til Zengu i Hammerfald.", d="Det sidste af de segl, der skal til for at låse Thoras Trollebanes grav op, holdes personligt af hans søn. Han holder til dybt inde i Strømgård, i et kapel i de distrikter, som militsen har. Prins Galæn er godt beskyttet og er selv ingen kujon som kriger, så denne opgave kan vise sig at være yderst vanskelig.", p="Du er vendt tilbage, <Name>. Er Ildæus Trollebanes linje brudt?", c="Det har været en dag, <Class>. Trollebanes blod skal ikke længere hjemsøge mit folk, og de segl, der skal til for at tage Trolddræberen, er nu i vores besiddelse. Snart, meget snart, slår vi til mod de forhadte trolde i Zul'Gurub."},
  [645] = {n="Trolddræberen", l="Hent Trolddræberen fra Trollebanes grav i Strømgård.", d="Hvad er det her? Med de fire segl samlet er de gået sammen og har dannet ét segl. Der kan ikke være tvivl om, at det vil kunne bryde de besværgelser, der er lagt over Trollebanes grav.\n\nTrollebanes rester er indmuret i helligdommen bag kapellet i Strømgård. Hent Trolddræberen.", p="Ristninger i stenen på Trollebanes gravs forside matcher de lysende linjer i Ildæus' segl...", c="Da linjerne på Trollebanes gravs forside passer med Ildæus' segls lysende linjer, opslugs seglet af et lysglimt, og det legendariske sværd Trolddræberen frigøres fra de stenhænders greb."},
  [646] = {n="Trolddræberen", l="Lever Trolddræberen til Zengu i Hammerfald.", d="Lyset falmer langsomt. Sværdet Trolddræberen, der var holdt i en stenskede, er blevet frigjort.", p="<Name>! Har du taget sværdet?", c="I generationer hærgede Strøms og Arators styrker trollene. Nu er deres største våben i vores hænder. Vores krybende fremskridt i de dampende skove i Zul'Gurub er forbi.\n\nDin hjælp har været enorm, <Name>, og Mørkspyd-trollene står i gæld til dig.\n\nJeg sørger for, at sværdet bliver leveret til Nimboya i Grom'gol."},
  [647] = {n="MakKreels Månebrændevin", l="Bring MakKreels Månebrændevin til Brygmester Bilger i Sydkysten.", d="Fik godt fat i det gamle Månebrændevin i går aften! Langfletten ville have mit hoved, hvis han vidste, at jeg faldt om under min vagt.\n\nHovedet gør ondt på en voldsom måde. Det føltes, som om en hel brigade belejringsmaskiner var passeret over hovedet, al den rumlen.\n\nÅh gud, se hvad klokken er! Jeg lovede Brygmester Bilger i Sydkysten, at jeg ville betale min gæld til ham ved at sende noget Månebrændevin.\n\nMen der er kun 15 minutter tilbage, før jeg er for sent på den! Tag den her portion til ham, vil du være sød? Og skynd dig!", p="Hvad er den gode nyhed, <Race>?", c="Ah, intet varmer en op på en bidende kold dag som MakKreels Tågede Månebrændevin! Og der troede jeg, at den lille slyngel ville være for sen med sine regninger igen. Tak, ven! Mange tak, virkelig!"},
  [648] = {n="Red OOX-17/TN!", l="Eskorter OOX-17/TN til Damphjulshavn, og rapportér derefter til Oglethorpe Uopdaget i Bytteviken.", d="Gnomens stemme knitrer endnu en gang fra robotten:\n\n\"Jeg må flytte OOX-17/TN til et åbent, sikkert sted, så den kan begynde en lang opstigningsprocedure. Den har indbygget tilsløring, men jeg har brug for tid i min ende for at gøre den funktionsdygtig igen. Jeg har brug for, at du eskorterer robotten fra dens nuværende placering til, lad os sige, Damphjulshavn! Det burde være et perfekt sted, og lang nok tid, til at få tingene i gang!\"\n\n\"Eskorter den sikkert til havnen, og kom så og tal med mig i Bytteviken! Oglethorpe Uopdaget - over og ud!\"", c="Åh, DU er den store redder af OOX-17/TN! Jeg kan slet ikke begynde at udtrykke min taknemmelighed for din hjælp! Min målsøgende robotserie trænger til mere udvikling, men din redning har sparet mig for utallige timers genopbygningstid, samt mange guldstykker i genbindingsomkostninger!\n\nVær venlig at tage dit valg af en af de ting, jeg har. Forhåbentlig får du god brug af en af dem. Tak igen for din generøse hjælp, mine robotter og jeg står i gæld til dig!"},
  [649] = {n="Rippel-genopretning", l="Tal med Mallond Droffers i Orgrimgrad.", d="Jeg har noget bjærgningsarbejde til dig, og hvis du er lige så glad for fin rippel som jeg er, så vil du elske denne opgave. Rippel!\n\nDet er en drik, din attrap.\n\nEn forladt forpost tilhørende Horden har et lager af Bagland Honningrippel fra dengang, de var i gang. Sådan fin rippel kan man ikke få længere! En af Mallonds attrap-medarbejdere kender stedet, så du tager derud og henter mig en kasse pakket rippel og to til min egen samling! Tal med Mallond, han giver dig detaljerne.", c="Åh ja, om den rippel far vil have! Han vil sælge rippelen til en kro her i Orgrimgrad, men vi får flere penge, hvis den er i sin originale emballage. Jeg kender en, der kan gøre det, og han er i Bagland, hvor rippelen er. Men han er øh, en højalf.\n\nNå, han er en god højalf, for han er ikke en del af Alliancen. Nja, han er ikke så meget en god højalf, som han er en beruset højalf. Han elsker, og jeg mener ELSKER, brændevinen."},
  [650] = {n="Rippel-genopretning", l="Tal med Gilveradin Solsøger; hans lejr ligger i Bagland.", d="Alfen du skal tale med, er Gilveradin Solsøger. Han kan navngive enhver vin, årgang og det hele, blot ved at lugte til den! Han kan pakke den rippel, vi har brug for, så du skal tale med ham. Vi skal bruge seks flasker til emballering, to til far, og så mange han vil have... og tro mig, han vil have nogle. Når du har pakket rippelen og fået fars to flasker, så kom tilbage her!\n\nGilveradins lejr ligger tæt på højalfernes logehus i Bagland, og de højalfer er ikke gode. Stol på mig.", c="Nå, så du kender Mallond? Han er en gammel drikkekammerat af mig. Du ser, jeg har fundet noget, der overskrider grænserne for kunstige traktater og alliancer - alkohol. Skulle vi alle slukke vores tørst på dens salige egenskaber, ville vi alle være i en meget bedre åndelig tilstand.\n\nDesværre fortæller noget mig, at dit besøg her ikke handler om at lære alkoholens forløsende værdier, er det nu?"},
  [651] = {n="Bindingsstenene", l="Indsaml den Brændende Nøgle, den Bølgende Nøgle og den Tordnende Nøgle fra Vestbindingens Sten, Østbindingens Sten og Ydre Bindingssten.\n\nBring dem til Indre Bindingssten.", d="Fire Bindingsstene er spredt ud over Arathi. Disse sten holder mig fasthæftet under jorden.\n\nFor at låse dem op skal du låse den stærkeste op: Indre Bindingssten. Og for at gøre det skal du indsamle nøgler fra de tre andre.\n\nDisse sten bliver vogtet af vogtere, men hvis du er snedig eller heldig, kan du måske finde måder at forvise dem på.", p="Dette er Indre Bindingssten. Den er den stærkeste af bindingsstenene, og den skal låses op, før de andre kan åbne sig.", c="<Myzrael taler gennem stenen.>\n\nDu har gjort det! Du åbnede Bindingsstenene! Jeg kan mærke lænkerne løsne sig omkring mig, og friheden kommer stadig nærmere.\n\nDu er en ædel <Class>, <Name>. Min redningsmand!"},
  [652] = {n="Brydning af Nøglestenen", l="Find og dræb Fozruk. Bring Ordenens Stav til Nøglestenen i Arathi-højlandet.", d="At åbne Bindingsstenene løsnede meget af min fængsling, men en lås holder mig stadig lænket. Det er nøglestenen, du ser blandt denne kreds af sten. Og nøglen holdes af en af mine fangevogtere, stenvogteren Fozruk.\n\nDu skal skaffe den nøgle, som stenvogterne kalder Ordenens Stav, fra Fozruk og bruge den til at åbne nøglestenen.\n\n<Name>, du har gjort så meget for at hjælpe mig. Bare lidt mere... så skal min taknemmelighed ryste selve jordens fundament!", p="Nøglestenen er ladet med enorm geomantisk energi.", c="Du placerer staven i nøglestenen. Og et rys mærkes under dig..."},
  [653] = {n="Myzraels Allierede", l="Tal med Gerrig Knoglegreb i Det Forladte Hulrum i Jernsmede.", d="<Myzrael taler.>\n\nFri! JEG ER FRI! Jeg er fri til at samle styrke, skjult for mine fangevogtere. For hvis de stod over for mig nu, ville de helt sikkert overmande mig og fængsle mig igen.\n\nMen med tiden vil jeg konfrontere kæmperne, og de vil fortryde deres vogtertjeneste af mig!\n\nDu er en ædel allieret, <Name>. Jeg får brug for din hjælp igen på et tidspunkt. Når jeg er klar, får jeg brug for, at du kalder mig op til overfladen.\n\nTal med Gerrig Knoglegreb. Han er i Jernsmede, i en butik i Det Forladte Hulrum. Han ved, hvordan jeg kan kaldes.", c="Damen fortalte mig om din ankomst, <Class>. Du er velkommen i min bolig, for ligesom mig tjener du en højere sag."},
  [654] = {n="Markprøvetagning i Tanarisørken", l="Indsaml brugbare prøver fra 8 basilisker, 8 hyæner og 8 skorpioner. Bring testsættet tilbage til Overingeniør Lensevits i Gadgetbyen, før strømkilden løber tør.", d="Når strømkilden aktiveres, begynder markforsøgssættet at lyse og vibrere. Det lader til at virke efter planen.\n\nIfølge Overingeniør Lensevits har du nu to timer til at indsamle de data, du har brug for i Tanarisørkenen. Hvis du ikke indsamler dem inden for to timer, går alle data tabt, og du må købe en ny strømkilde af ham.\n\nVend tilbage til ham, når du har udført opgaven.", p="Nå, fik du alt det, du havde brug for? Hvis ikke, og strømmen løber tør, bliver alt indeni ødelagt, og du må starte forfra.\n\nHey, søg ikke sympati hos mig; jeg går kun op i, at Gadgetbyens Vandselskab tjener penge, og hvis det betyder, at vi sælger dig strømkilder, indtil vi har råd til at importere vand fra de iskolde kilder i Dun Frostbakke, så være det!", c="Fint så, det tager mig lige et øjeblik at fjerne strømkilden. Derefter kan du gøre med den, hvad du vil, uden at skulle bekymre dig om at miste dataene indeni."},
  [655] = {n="Hammerfald", l="Tal med Tor'gan i Hammerfald.", d="Det er stadig klart for mig, som var det i går... Så mange år uden håb, med træ og stål til at binde mig til dette forfærdelige sted. Så endelig, endelig! Der var Krigshøvdingen. Dømmehammer i sin midnatsrustning, hans krigshammer løftet højt.\n\nDet var... for forfærdeligt... At en kujons slag skulle fælde vores største helt. Bagfra angreb han på sin hest, og så gennemborede hans lanse ham... Jeg faldt på knæ. Hvilket håb var der? Hvilket håb er der...", c="Ah, Gor'mul, ja. Ud fra hvad han siger, lader det til, at han aldrig er kommet sig over Dømmehammers død.\n\nGor'mul var fange her, da Thrall og Orgrum kæmpede for at befri lejren, men da jorden rystede, og vores brødre slap væk, blev han efterladt. Han vandrede alene og fortabt i årevis uden retning eller håb, indtil vi vendte tilbage for at etablere os her i Hammerfald."},
  [656] = {n="Fremkaldelsen af Prinsessen", l="Gå til Myzraels Skår, kald hende frem og besejr hende.\n\nSaml hendes Overnaturlige Lænker og bind dem til Myzraels Skår.", d="Du skal besejre Myzrael, før hun vokser i styrke. Hvis du ikke gør det, vil hun, når hun har samlet nok kraft, udfordre sine fangevogtere! Der er nogle, der tror, de kan kontrollere hende, men hvis hun kan kontrolleres, hvorfor lænkede kæmperne hende så i første omgang??\n\nGal logik, hva'?\n\nFor at besejre hende, kald hende frem ved Myzraels Skår, hvor du første gang talte med hende. Besejr hende, saml hendes Overnaturlige Lænker og bind dem til Myzraels Skår.\n\nGør du det, vil hun blive fanget igen.", p="Myzraels Skår er nu mærkeligt stille.", c="Da de overnaturlige lænker bliver lagt om skårene, høres et umenneskeligt hyl langt nede fra. Skriget efterfølges af et brøl.\n\nMyzraels Skår fremkalder ikke længere den varme og tryghed, de engang gjorde. Nu pulserer de med en åben trussel... som om det, der ligger under dem, nærer ond vilje over for overfladen."},
  [657] = {n="Spor af en Ny Pest?", l="Tal med Kinelori.", d="<Kvæ begynder at gennemgå mappen.>\n\nDET her er interessant. Det lader til, at Apoteker Jorell har arbejdet på nogle dødelige eksperimenter her i Go'Shek. Ved ikke, hvad det har med Bakkebrad at gøre, men Phin ville ikke bryde sig om, at vi lod det fortsætte.\n\nVi havde et sammenstød med nogle orker, mens du var væk, og jeg er ikke i god nok form til at hjælpe Kinelori. Hvis du er til det, får hun brug for beskyttelse, når hun går ned til gården for at stjæle den forskning, som Jorell stadig ikke har sendt til Tarren Mølle.", c="Hvis det bringer Phin fred, vil jeg personligt udrydde hver eneste af De Forladte. Han har gjort så meget for os siden pesten. Vi troede aldrig, at vi ville finde venner eller familie igen.\n\nNår du er klar, så kom og sig til. Så går vi i gang med det samme."},
  [658] = {n="Spor af en Ny Pest?", l="Find den Forladte Kurer og bring hendes Forseglede Mappe tilbage til Kvæ nær Go'Shek-gården.", d="Så Phin sendte dig for at tjekke op på os? Ikke overraskende - han bekymrer sig for meget.\n\nVi har holdt øje med gården i flere dage, og Kin påstår, hun så en kurer komme ud af det lille hus mod syd for ikke længe siden.\n\nHun snakker meget, men jeg kan altid stole på hendes sanser, når vi er i farlige områder.\n\nDu er vel ikke en dygtig sporer? Vi tror, kureren bærer noter til Tarren Mølle. Hvis vi kunne få fat i de dokumenter, kunne det måske kaste lys over, hvad der sker i Bakkebrad.", p="Vi sætter pris på din hjælp med at lede efter den kurer, <Name>.\n\nMens du var væk, så Kin en apoteker komme ud af det samme hus mod syd herfra. Jeg er overbevist om, at de laver noget uhæderligt - jeg skal bare bruge bevis, før vi går i gang med noget overilet.\n\nHar du haft held endnu?", c="Fremragende!\n\nLad os se, hvad det her handler om..."},
  [660] = {n="Spor af en Ny Pest?", l="Beskyt Kinelori, indtil hun vender tilbage til Kvæ.", d="Fint, <Name>. Jeg er klar, hvis du er.\n\nSkal vi?", p="Tiden for snak er forbi. Beskyt Kinelori, hvis du overhovedet bekymrer dig om folkene i Bakkebrad.", c="Du har gjort os en stor tjeneste, <Name>. Tak.\n\nJeg håber, Kin ikke var for meget besvær dernede. Hun er meget venlig, men kan være lige så dødbringende, når du er hendes fjende."},
  [661] = {n="Spor af en Ny Pest?", l="Find Phin Odelic i Sydkysten.", d="Jeg har set Kinelori se langt værre ud efter en nat i kroen, end hun gør nu. Du har tydeligvis gjort et godt stykke arbejde med at beskytte hende.\n\nDe ting, hun bragte tilbage fra gården, bør i det mindste give Phin en idé om, hvad der foregår herude i Arathi. For at sikre, at der ikke kommer gengældelse efter dit angreb, bliver vi her en lille stund endnu. Ville du være villig til at tage tilbage til Sydkysten og tale med Phin?", c="Så de to urostiftere har det alligevel godt? Haha, jeg er glad for at høre det. Jeg takker dig for at bringe mig nyheder om deres opholdssted og status - det glæder mig enormt, at de stadig lever; de to er uerstattelige som venner og rejsefæller.\n\nMen... det er vigtigere, at jeg takker dig ordentligt for din hjælp. Her. Tag dette med min gruppes tak.\n\nMed lidt held finder vi ud af, hvad De Forladte har gang i, og får sat en stopper for det."},
  [662] = {n="Dybhavsbjærgning", l="Første Styrmand Nilzlix vil have dig til at hente Kortene og Logbøgerne fra Jomfruens Dårskab og Sølvfyrens Ånd.", d="O'Brise førte skibene ind i vigen. Vi var sikre på, at det var her, skatten kunne findes. Varsleren lagde sikkert til, men da Jomfruens Dårskab og Sølvfyrens Ånd nærmede sig, begyndte tidevandet at falde. Det mærkeligste, jeg nogensinde har set!\n\nDe to skibe løb på grund i noget... en slags tempel i revet. De sank så hurtigt, det var en stor tragedie.\n\nVi må hente deres Logbøger såvel som deres Kort, før vi forlader stedet. Vi kan ikke lade den information ligge tilbage for nysgerrige øjne!", p="Hvordan går eftersøgnings- og bjærgningsmissionen, <Name>? Vi har virkelig brug for at få Logbøgerne og Kortene tilbage fra Jomfruens Dårskab og Sølvfyrens Ånd.\n\nHvis informationen fra kilderne skulle falde i fjendens hænder, ville Flådemester Søhest få os til at gå planken.\n\nSå længe vi ellers kommer ud af det her rod...", c="At vide, at denne information er sikker, vil give lidt ro til kommandoen i Bytteviken. Godt gjort, <Name>."},
  [663] = {n="Land i sigte!", l="Tal med Kaptajn O'Brise i Faldirs Vig.", d="Lolle ser en lille <Race>! Lolle er altid på udkig, det er Lolle!\n\nVelkommen til Faldirs Vig. Kaptajn O'Brise sagde, at vi kun ville være her i et par timer. Lige lang nok tid til at samle skatten og komme tilbage til Bytteviken.\n\nMen Lolle tror, vi bliver her meget længere end det. Vi mistede de to andre skibe fra vores formation. Stakkels Sølvfyrens Ånd og Jomfruens Dårskab. På havbunden hviler de nu!\n\nLolle foreslår, at du taler med Kaptajn O'Brise, hvis du har planer om at blive her.", c="Ahoi, makker.\n\nDet var et forfærdeligt rod. Søhest får mit skib, hvis han finder ud af, hvad der skete.\n\nEn af Professorens opfindelser viste, at den tabte skat var nær denne vig. Jeg førte Varsleren ind for at lægge til og signalerede, at Sølvfyrens Ånd og Jomfruens Dårskab skulle følge trop.\n\nSå rumlede havet. Tidevandet faldt, og de to skibe smadrede ind i revet.\n\nDet er ikke bare et rev. Der er noget dernede...\n\nHjælp min besætning, så bliver du belønnet rigeligt."},
  [664] = {n="Druknede sorger", l="Kaptajn Stålmave i Faldirs Vig vil have dig til at dræbe 10 Dolkeryg-razziaer og 3 Dolkeryg-heksekvinder.", d="Argh, det er et forfærdeligt liv. Jeg burde ligge i en vandgrav lige nu, ikke sidde her ved bålet og indånde frisk luft.\n\nBesætningen prøvede så hårdt at redde min smukke Jomfruens Dårskab. Velsign drengene, velsign deres hjerter.\n\nO'Brise nåede sikkert i land, men vi var ikke så heldige. Havet sank os bare, det sværger jeg.\n\nÉt øjeblik flyder vi, og det næste strømmer vandet ind. Og de bæster! Dræbte alle overlevende. Forfærdeligt slangefolk-pak. Jeg besvimede og endte her, reddet.\n\nJeg vil have de bæster døde.", p="Bah, måske burde jeg selv gå og dræbe det slangefolk-pak. Det er åbenlyst, at du ikke har tænkt dig at gøre det.\n\nMåske kan jeg finde nogle strikkepinde, så du kan holde dig selv beskæftiget.", c="Godt arbejde derude, <Name>.\n\nDe skiderikker fik, hvad de fortjente. Intet vil nogensinde bringe mit skib eller min besætning tilbage, men slangefolkets død giver mig lidt trøst."},
  [665] = {n="Sunket skat", l="Eskorter Professor Sprøthorpe til hulen og tilbage igen.", d="Nu hvor vi er fuldgyldige Sortvands-razziaer, er det vores opgave at hjælpe Hr. O'Brise med at finde den tabte alveskat.\n\nDet er næsten umuligt at finde ædelstenene i det mørke hav uden hjælp. Doktoren har konstrueret nogle briller, der kan hjælpe. Han har brug for brillerne ladet op med energien fra den fortryllede sten i hulen lige oppe ad bakken.\n\nMen hulen er forbandet! Når vi kommer tæt på, bliver vi overfaldet. Forsvar mig, så kan jeg udnytte stenens energi i brillerne.", p="Nu er der ikke tid til snak! Brillerne skal ladet op med stenens kraft!", c="Brillerne virker perfekt nu! Godt gjort, <Name>."},
  [666] = {n="Sunket skat", l="Doktor Draxlemåler i Faldirs Vig vil have dig til at samle 10 Alveædelsten og returnere Brillerne til Ædelstensjagt, når du er færdig.", d="Skatten har ligget på havbunden så længe, at ædelstenene er forstenet til tyk sten. Men kraften i disse briller vil gøre det muligt for dig at finde dem nemt.\n\nEn lille gnomisk snilde rækker langt!\n\nSå lån Brillerne til Ædelstensjagt, <Name>, og se, om du kan samle noget af den tabte skat til Kaptajn O'Brise.\n\nJeg ville selv svømme derned, men... øh... jeg har vigtig videnskabelig virksomhed at tage mig af oppe på det sikre, tørre land... øh, ja.", p="Hvordan fungerede brillerne? Virkede alt ordentligt? Justeringer kan foretages, hvis det er nødvendigt.\n\nÅh, og jeg skal bruge brillerne tilbage, når du er færdig. Jeg er sikker på, at Kaptajn O'Brise får mange anvendelser for dem senere.", c="Fortræffeligt, <Name>! Kaptajnen bliver meget glad! Og bare vent, til nyheden når Flådemester Søhest!"},
  [667] = {n="Døden nedefra", l="Beskyt Ryster O'Brise under angrebet.", d="Det her er slemt. Det ser ud til, at Dolkerygene samler sig til et angreb.\n\nSlangefolk er kendt for deres hensynsløshed i kamp. De vil blive ved med at angribe, indtil jeg er død.\n\nJeg sætter ikke mit eget liv over mine besætningsmedlemmers, men du må hjælpe med at forsvare mig. Besætningen vil ikke kunne nå tilbage til Bytteviken uden min viden om havene.\n\nSlangefolket kommer fra havet. Jeg har brug for, at du bliver her oppe hos mig for at afværge angrebet. Bemand kanonen og driv dem tilbage.\n\nEr du klar, <Name>?", c="Vi overlevede angrebet!\n\nVi kunne ikke have gjort det uden dig, <Name>.\n\nVi tager af sted, så snart tidevandet stiger. Hvis du ikke var sådan en lovende helt, ville jeg tilbyde dig en plads i min besætning. Men jeg kan se, at du har større fisk at stege.\n\nSelvom du er en ynkelig lille <Race>...."},
  [668] = {n="Sunket skat", l="Tag alveædelstenene til Kaptajn O'Brise.", d="Lad os ikke lade Kaptajn O'Brise vente. Han vil gerne se dem med egne øjne. Det er trods alt derfor, vi er her!\n\nOg efter et par uger sammen med disse pirater har professoren og jeg indset, at det sidste, der er godt for vores helbred, er at blive fanget med at holde fast i deres skat.\n\nHer, <Name>, tag dem til O'Brise.", p="Ahoi, <Class>. Hvad bringer dig til broen?", c="Så de små gnomer beviste deres værd alligevel? Jeg vidste, at vi havde de små ankelbidere af en grund!"},
  [669] = {n="Sunket skat", l="Tag prøve-alveædelstenen til Flådemester Søhest i Bytteviken.", d="Flådemester Søhest vil gerne høre om vores fund med det samme.\n\nMen som du kan se, er vi ikke i en position til at komme herfra. Ikke nok med at tidevandet er for lavt, de forbandede væsner, vi forstyrrede, holder øje med vores bevægelser.\n\nDu kan være en stor hjælp for Sortvands-razziaerne, hvis du kan sende besked til Flådemester Søhest i Bytteviken om, at vi har fundet skatten og arbejder på at udvinde mere. Tag ham denne prøve som bevis.", p="Hvad bringer dig til Bytteviken, <Class>?", c="Ah, lad det være op til gode gamle Ryster O'Brise! Jeg vidste, at han var den rette kaptajn til opgaven!"},
  [670] = {n="Sænket skat", l="Lever Søhorns brev til Ryster O'Breen i Arathi-højlandet.", d="Hør her, <Name>, du lyder som en eventyrlysten type. Min flåde sidder fast i Bytteviken, indtil vi kan proviantere igen.\n\nDer brygger noget tungt her og ude i verden, og jeg må have en tophemmelig korrespondance over til Ryster O'Breen, som ligger bundet op ud for Arathi-kysten.\n\nKan jeg stole på, at du leverer denne besked sikkert og fortroligt?", p="Så blev Søhorn imponeret? Jeg vedder på, at hans smil nåede hele vejen fra Bytteviken til Rakkerhavn.", c="Tak, fordi du tog sådan en lang og farefuld rejse. Du har Sortvands-razziaernes taknemmelighed."},
  [673] = {n="Snavset magi", l="Hent Marez Hættes Blodsten-kugle og bring den til Tor'gaard i Hammerfald.", d="Der er ingen tvivl i mit sind om, at en mægtig trolddomsmand holder til inden for Stormgårds mure. Fra tid til anden har denne trolddomsmand, ved hjælp af en arkan magisk relikvie, kaldt frygtelige dæmoner frem i store mængder. Vi må fjerne kilden til hans energi.\n\nFind trolddomsmanden og dræb ham. Bring mig det magiske objekt, du finder på hans person, så skal jeg sørge for at ødelægge det og se til, at dets magt ikke bliver brugt til at besmitte dette land længere.", p="Brændingen i mit blod... den vokser for hver dag. Trolddomsmanden må stoppes.", c="Mine rastløse nætter vil blive til fredfuld søvn, når jeg har ødelagt denne kugle. Tak, <Name>. Den er en isnende påmindelse om den frygtelige magt, dæmonerne havde over orkerne, før Helskrig befriede dem fra deres forbandelse."},
  [674] = {n="Vækkelse af ånder", l="Giv Raptorklo-amuletten til Gor'mølle.", d="Her, tag denne amulet med til Gor'mølle, og se om raptorernes styrke kan vække krigerens flamme, der engang brændte gennem hans årer.", p="Hvad håb er der, når en kujon kan slå de stærkeste af de stærkeste? Hvad håb, spørger jeg dig!", c="Hvad er det her? Poleret knogle. Hvad skal jeg med poleret knogle? Kan en tingest genoprette Horden til sin herlighed?"},
  [675] = {n="Vækkelse af ånder", l="Tal med Tor'gaard.", d="<Gor'mølle kaster amuletten ned på jorden.>\n\nTor'gaard sendte dig, gjorde han ikke? Pah! Hvorfor han føler en vis nåde over for mig, ville jeg ikke forstå. Nåde blev nægtet mig, da jeg ikke fik lov at dø sammen med min krigshøvding i slaget. Et grusomt slag, skæbnen har givet mig...", c="Det virkede ikke, kan jeg se. Ikke desto mindre mener jeg, at det at vise ham shamanernes magt med tiden vil få Gor'mølle tilbage til sit engang stolte jeg. Amuletens kraft var ikke stor nok til at vise ham vores nyfundne magt."},
  [681] = {n="Nordfold-herregården", l="Dræb 10 Syndikat-landevejsrøvere og 6 Syndikat-lejesoldater.\n\nVend tilbage til Kaptajn Nials ved Tilflugtsodden.", d="Vi kæmper en krig for Stormgård, og vi taber. Oger, Syndikatet og os har delt vores engang så store by, og hver fraktion kæmper mod de andre i et blodigt dødvande.\n\nMen vores styrker svinder ind, mens vores fjende vokser.\n\nVi har brug for hjælp fra byen Sydstrand, men forsyninger er svære at få, mens Syndikatet holder territorium mellem os.\n\nGå til Syndikatets base i Nordfold-herregården og slå dem ihjel. Så lettes presset på vores forsyningskolonner måske, og flere kan komme igennem.", p="<Name>, for hver time der går, bliver vores greb om Stormgård mere skrøbeligt. Du må skynde dig, ellers falder vores by med sikkerhed.", c="Meget godt, <Name>. Med de Syndikat-medlemmer døde burde vi have lettere ved at modtage forsyninger fra Sydstrand.\n\nMåske har vores sag endnu håb."},
  [683] = {n="Sara Ballonsens bøn", l="Tag Sara Ballonsens seddel til Kong Magni Bronzeskæg i Jernsmede.", d="<Name>, jeg har blot en lille bøn at bede dig om.\n\nTag denne seddel, jeg har forberedt, til vores store monark i Jernsmede, Kong Magni Bronzeskæg. Det er en lille opgave at bede om af én som dig, nogen der indtil nu har vist stor tapperhed for Alliancens sag.\n\nFor mig at træde frem for Kongen i min sorgtyngede tilstand ville ikke tjene min sags formål. Du forstår sikkert.", p="Så du er <Name> den <Class>? Nyheder om dine bidrag til Alliancen er nået ganske langt, ved du vel?\n\nHvilken sag bringer dig for mig i dag?", c="Det tager kun et øjeblik for mig at læse dette brev..."},
  [686] = {n="En konges hyldest", l="Kong Magni Bronzeskæg vil have dig til at tale med Storslået Murer Marmorsten.", d="Jeg forventer ikke, at gode dværge som Fru Ballonsen forstår, hvorfor krigens rædsler må udholdes til gavn for vores folk. Tabet af hendes mand, og tabet af hver eneste dværg, der kæmper i Alliancens navn, tynger min sjæl.\n\nMens jeg ikke kan bringe hendes mand tilbage fra Snoede Nether, kan jeg hylde ham.\n\nJeg vil bestille et mindesmærke over Sully Ballonsen, som skal bygges af Storslået Murer Marmorsten.\n\nSend ham bud nu, <Class>. Du skal være forvalter af min vilje.", c="Så Kong Magni Bronzeskæg selv sendte jer?\n\nMin, min! Det må være vigtigt!"},
  [687] = {n="Tyldurin den Tabte", l="Find Tyldurin den Tabte.", d="Tyldurin den Tabte var engang medlem af vores orden, Tusmørkets Hammer. Men han tabte forstanden og foragtede vores læresætninger. Og før han flygtede fra os, stjal han Myzraels rulle! Vi kunne ikke fange ham, men rygter siger, at han gemmer sig i Ødelandene, pludrende og gal.\n\nFor at bringe Damen tilbage til os, må du finde rullen. Og for at gøre det, må du finde Tyldurin.", c="Hej. Hej, hej hej hej hej, HEJ!\n\nJeg beklager - vent, nej, det gør jeg ikke! Vær ikke uhøflig!\n\nÅh nej... det var sindssyge snak.\n\nMen... nogle gange er det at være gal min eneste trøst."},
  [688] = {n="Myzraels allierede", l="Tal med Zarrak i Hammerfald.", d="<Myzrael taler.>\n\nFri! JEG ER FRI! Jeg er fri til at samle styrke, skjult for mine fangevogtere. For hvis de stod over for mig nu, ville de med sikkerhed overmande og fængsle mig igen.\n\nMen med tiden vil jeg træde op mod kæmperne, og de skal fortryde deres varetægt over mig!\n\nDu er en ædel allieret, <Name>. Jeg får brug for din hjælp igen med tiden. Når jeg er klar, får jeg brug for, at du kalder mig op til overfladen.\n\nTal med Zarrak i Hammerfald. Han ved, hvordan jeg kan kaldes frem.", c="Velkommen, <Class>. Damen har informeret mig om din ankomst, og hvis vi skal bringe hende tilbage til overfladen, har vi meget at drøfte..."},
  [689] = {n="En konges hyldest", l="Storslået Murer Marmorsten i Jernsmede vil have 5 stykker Alterac-granit.", d="Så vores gode konge ønsker et mindesmærke bygget til ære for en soldat ved navn Sully Ballonsen? Og du siger, at den stakkels karl døde under tragedien ved Thandol-broen?\n\nBah, vil der nogensinde komme fred på Azeroth?\n\nIkke desto mindre er enhver bestilling fra kongen af yderste vigtighed. For at bygge et virkelig episk og varigt værk vil jeg arbejde med en af de fineste sten, der findes. Rejs til Darrow-bakken i Bakkebrad og saml noget Alterac-granit til mig.", p="<Name>, <Name>, <Name>! Fortæl mig, at du har nok Alterac-granit til, at jeg kan begynde mit mesterværk til ære for Sully Ballonsen.", c="Perfekt! Bedre end jeg kunne have forestillet mig!\n\nOg jeg har en ganske god fantasi, ved du nok..."},
  [692] = {n="De tabte fragmenter", l="Bring det revne rullefragment, det krøllede rullefragment og det svedne rullefragment til Tyldurin den Tabte.", d="Myzraels rulle... Myzraels rulle?! Det vil du ikke have! Dens magi kan trække Myzrael op til overfladeverdenen, og hvis du gør det, er vi i problemer!\n\nEller... måske er det for sent. Måske er hun allerede fri. Måske samler hun bare styrke, før hun løsner sig og slår ned over os. Hvis det er tilfældet, så får du BRUG for rullen!\n\n...ærgerligt, den er ødelagt. Rasende elementarer stjal den og rev den i stykker, og nu kæmper de om fragmenterne.\n\nMen hvis du kan samle fragmenterne, kan vi måske reparere den...", p="Fandt du de fragmenter?!?! Du får brug for Myzraels rulle, hvis du vil fange hende igen, før det er for sent!", c="Ah, du fandt dem! Godt arbejde, <Name>! Disse er måske vores eneste chance mod Myzraels ondskab!\n\nLad mig bare finde min skrot-ratchet og se, om jeg kan sætte disse fragmenter sammen igen..."},
  [693] = {n="Stav over næve", l="Find Trølanes påkaldelsesstav og returner den til Skruerto ved Tilflugtsodden.", d="Hej, <Name>. Undskyld, at jeg var så kortfattet med dig før... og nej, det er ikke et ordspil.\n\nJeg har fundet ud af, hvor Trølanes første genstand endte: Kor'grash har den i Klippenæve-hallen. Og efter måden han slyngede isstød mod sine egne for at holde dem på plads, må han være tæt på at finde ud af, hvordan man bruger alle dets kræfter.\n\nKlippenæve-hallen ligger syd herfra og så øst for Thandol-broen. Find oger'en og hent staven tilbage.\n\nMens du er væk, finder jeg ud af, hvad vi skal gøre ved Stormgård.", p="Vores mål er staven, <Name>. Fokuser på den for nu.", c="Strålende, <Name>. En genstand klar og tre tilbage, ifølge min liste. De tre andre genstande er alle i Stormgård.\n\nTag en pause og saml kræfterne igen - næste fase af min plan kræver lidt mere tid og indsats. Kom tilbage til mig, når du har fået et varmt måltid og lidt hvile."},
  [694] = {n="Trølanes forsvar", l="Find en Azurblå Agat og bring den til Lærling Kryten ved Tilflugtsodden.", d="Helt udhvilet?\n\nHer er vores næste skridt: Der er oger overalt omkring Arator-tårnet i Stormgård. Vi bliver nødt til at aktivere tårnets forsvar, hvis du skal have en chance mod dem og stadig nå genstandene i live. For at gøre det skal vi bruge nogle ædelsten, som Klippenæve-shamanerne har fået smag for. De tog dem fra tårnet, men de bliver ikke i deres besiddelse længe.\n\nFå fat i en af disse ædelsten og bring den til Kryten - han kender besværgelsen til at fortrylle dem, så de virker som en nøgle.", p="<Name>, hej igen. Har du fundet en azurblå agat endnu?", c="Du overrasker mig, <Name>. Godt gået igen.\n\nGiv mig et øjeblik til at besværge den rette besværgelse over ædelstenen, så er du klar."},
  [695] = {n="En lærlings fortryllelse", l="Tal med Skruerto.", d="Her er du, <Name>. Ædelstenen skal blot trykkes mod en af soklerne nær tårnets grund for at aktivere dets forsvar. Brug den, når du er klar til at gå ind i tårnet og finde Trølanes resterende genstande.\n\nHeld og lykke. Jeg venter på din tilbagekomst her i lejren. Åh, og tal med Skruerto, før du tager afsted. Han giver dig resten af de detaljer, du får brug for.", c="Godt, godt.\n\nHvis der ikke er flere forsinkelser, hvad med at vi går i gang?"},
  [696] = {n="Angreb på tårnet", l="Find Trølanes fylakterium, Trølanes kugle og Trølanes glødagat, og returner dem til Skruerto ved Tilflugtsodden.", d="Her er det, du leder efter: Trølanes fylakterium, Trølanes kugle og Trølanes glødagat.\n\nAlle tre burde være i kister inde i tårnet, og du burde ikke have problemer med at åbne kisterne selv; du skal bare passe på oger'erne.\n\nTårnets forsvar tager ikke sig af dem på egen hånd; du bliver nødt til at have dine våben klar. Når ogerne opdager, at du er der og stjæler fra dem, vil de helt sikkert give dig tæsk.\n\nVær forsigtig, og held og lykke.", p="Gør du det her, er jeg sikker på, at Malin bliver mere end tilfreds med dig.", c="Malin kunne ikke have bedt om en mere værdig person til at komme herud og hjælpe os, <Name>. Du har gjort et storslået stykke arbejde!\n\nHan bliver glad for at se, hvor overvældende en succes vores mission har været."},
  [697] = {n="Malins anmodning", l="Tag det forseglede brev til Ærkemager Malin i Magikerkvarteret i Stormvind.", d="Tag dette brev tilbage til Stormvind og lad Malin vide, at Kryten og jeg snart er hjemme. Han vil belønne dig rigeligt for at hjælpe os her, <Name>, det tvivler jeg ikke på.\n\nRejs sikkert.", p="Ja? Du ser en smule bekendt ud. Jeg beklager, men har vi mødtes? Jeg er så travl, at jeg mister overblikket.", c="<Ærkemager Malin åbner brevet, og hans øjne bliver store.>\n\nVed Let, du har gjort det. Hvor vidunderligt. Trølane vil blive så glad. Jeg er sikker på, at Kryten og Skruerto er lige så begejstrede som jeg for at have dem på vej tilbage til Stormvind.\n\nTak, <Name>. Tag venligst dette med, det vil hjælpe dig på dine rejser."},
  [698] = {n="Mangel på overskud", l="Bring 8 uforberedte savtakkede flanker til Tok'Karr i Sorgens Sump.", d="Jeg er i gang med at samle nogle forsyninger til vores forpost nær stranden mod øst - Tok'Karr gør, hvad han kan, men mellem vagtskift og madlavning til sine soldater er der ikke meget tid tilbage af dagen.\n\nDe nyder at tilberede savtakket kød, når de kan, men jeg har ikke haft tid til at få dem endnu en forsendelse. Vil du hjælpe dem?\n\nDe unge savtakkede er ikke så velsmagende som de ældre, så hold dig væk fra dem; giv dem et år eller to til at blive fuldvoksne.", p="Lokk'tar, <Class>. At rejse gennem sumpene er ikke en risiko, man tager let på. Du er modig, at du tester din styrke her.", c="Ah! Fantastisk. Frisk kød til bålet i aften. Tak, <Name>.\n\nDu har hjulpet med at gøre de kommende nætter mere udholdelige. Ilden brænder klart, og vores maver bliver fulde.\n\nDet er en behagelig overraskelse, at du bringer os en forsendelse; Dår er ikke den mest tiltrækkende ork, nogen nogensinde har set, men hans attitude lugter i det mindste langt mindre end hans lugt."},
  [699] = {n="Mangel på overskud", l="Bring 6 savtakkede snapper-klør til Tok'Karr i Sorgens Sump.", d="Med truslen fra mudderfisk langs kysten er vi stationeret herude for at beskytte - eller advare, hvis styrken er for stor - mod enhver kommende trussel mod Stenhård. Det giver os ikke meget tid til afslapning, og vi kunne bruge noget mere hjælp, hvis du er i stand til det.\n\nDe savtakkede snappers klør laver fine våben, når de er ordentligt tilberedt. Bring mig nogle af deres klør, så sørger jeg for, at du bliver belønnet med et af vores våben som tak for det friske kød og det gode selskab.", p="God mjød, et varmt bål, en hær af orker og et arsenal af våben... det er alt, hvad vi egentlig behøver herude ved kysten. Jeg fortryder ikke min post herude, hvor jeg beskytter Stenhård, men det ville være dejligt, hvis vi en dag kunne få en hule eller i det mindste et tårn.", c="Dejligt at se, at du er i live og rask, <Name>.\n\nDisse klør bør gøre det fint. Jo flere våben vi har klar til angreb mod os, jo bedre stiller vi os.\n\nJeg går i gang med dit våben så hurtigt som muligt. Det tager kun kort tid. Jeg er blevet ganske dygtig og hurtig til at fremstille dem."},
  [700] = {n="En konges hyldest", l="Meld dig til Kong Magni Bronzeskæg.", d="Ah, sådan fin sten kommer fra Herrelande. Det er bare en skam, at landet er i så stor ruin.\n\nMen mindesmærket blev ganske godt! Jeg forestiller mig, at kongen bliver mest tilfreds med det.\n\nHvis du nu vil, så send bud til Hans Majestæt, at mindesmærket er fuldført som anmodet.", c="Granitten virker blot som en lille gestus sammenlignet med en stor dværgs liv. Men ingen dværg skal leve på denne planet i evighed.\n\nLad os blot håbe, at mindesmærket står som en påmindelse for dem, der vil træde på det store Azeroth i fremtiden. For vi må ikke glemme, at det er for dem, at modige soldater som Sully Ballonsen så tappert gav deres liv."},
  [701] = {n="Raptorens snedighed", l="Skaf 12 raptorhjerter fra Højlands Kødsmyger til Tor'gaard.", d="Med nogle ekstra genstande vil jeg kunne skabe et objekt, der indgyder Gor'mølle raptorens snedighed! Med raptorens kraft strømmende gennem ham vil Gor'mølle kende vores nye magt og genfinde krigeren, der ligger i dvale!\n\nJeg får brug for raptorhjerter til at smede genstanden og besværgelsen.", p="Mine forberedelser er klar, alt jeg behøver er raptorhjerterne.", c="Ja, disse vil fungere perfekt. Jeg vil overføre deres kraft og raptorernes ånd til denne kugle. Denne kugle vil give Gor'mølle raptorens ildfulde styrke og intelligens."},
  [702] = {n="Raptorens snedighed", l="Giv Tor'gaards kugle til Gor'mølle.", d="Tag denne kugle og brug dens energi til at give Gor'mølle raptorens essens. Det vil helt sikkert styrke hans ånd og give ham nyt formål i livet. Når han er vendt tilbage til det normale, kan vi forklare ham den nuværende tilstand i Horden, og vi får en stor krigers hjælp i vores uophørlige kampe.", p="Er du kommet tilbage igen? Der er faktisk intet, jeg kunne ønske mig mere nu, end mere af Tor'gaards medlidenhed.\n\nHvad har du til mig denne gang? Måske et stykke farverigt snor? Eller et stykke reb til at ende min elendighed...", c="Det er i det mindste noget interessant, du bringer mig denne gang. En underlig kraft den udsender..."},
  [703] = {n="Grillede musvågevinger", l="Bring 4 musvågevinger til Rigglefnug.", d="Åh ja, mine grillede musvågevinger er en favorit! Saucen er rig, og kødet er syrligt. Og lugten vil få de sultne til at løbe fra mil væk!\n\nJeg har alt, hvad jeg behøver for at lave en omgang. Alt... undtagen musvågevingerne!\n\nHvis du vil have nogle, så skaf mig musvågevingerne. Bring nok, og jeg deler måske endda opskriften med dig!", p="Hej, <Name>. Har du bragt mine vinger?", c="Ah, jeg går straks i gang med de vinger. Jeg kan næsten smage dem allerede!\n\nOg her er opskriften, hvis du vil lave dem selv!"},
  [704] = {n="Agmunds skæbne", l="Bring 4 udskårne stenurner til Prospektor Jernbånd i Modansøen.", d="Den sidste rapport, jeg modtog fra Agmund, er bekymrende, især nu hvor han er død! Han nævnte, at hans gravere afdækkede \"oldgamle urner\" på udgravningsstedet uden for Uldhaven. Jeg frygter, at de urner, han fandt på det sted, opildnede troggerne, ligesom de idoler, jeg fandt her, gjorde.\n\nJeg har brug for, at du henter de urner til vores studier. Gå til Uldhaven-stedet, saml urnerne, og vend så tilbage til mig.", p="Fandt du urnerne, <Name>? Vi må finde forbindelsen mellem dem og troggerne!", c="Godt gjort! Med held og flid finder vi den forbindelse, der måtte være mellem troggerne og disse oldgamle artefakter.\n\nDu har gjort en stor gerning for Prospektorerne, <Name>. Din indsats bliver ikke glemt. Og Agmund heller ikke."},
  [706] = {n="Ildende Flammeild-fortryllelser", l="Skaf et sort drakehjerte til Sigrun Jernhugger.", d="Som lærling til Feranor Stålspids lærte jeg hans særlige teknik til at indgyde våben med ildfortryllelser. Sidst jeg hørte om ham, arbejdede han i en smedje sammen med en jagtgruppe oppe i Herrelande.\n\nJeg kan ikke fortælle dig for mange detaljer om processen, men jeg kan sige, at det kræver blod fra et sjældent, stadig bankende hjerte fra en sort drakeunge. Jeg har ikke meget at lave, mens jeg venter på nyt fra Jernsmede. Hvis du bringer mig et hjerte fra ungerne i Lethlor-kløften, så viser jeg dig mine evner!", p="Hvordan går jagten, <Class>?", c="Ah ja, det her vil gøre det fortræffeligt. Det vil få dine våben til at ramme med brændende hede!"},
  [708] = {n="Den sorte kasse", l="Tag den tærede sorte kasse til Våbenhallen i Jernsmede.", d="Overfladen af denne metalliske sorte kasse er kraftigt hullet, som om den har været dyppet i syre - den må have ligget i kæmpekondorens mave i lang tid.\n\nNår man vender kassen om, findes et symbol præget på dens bund. Under symbolet står ordene:\n\n\"Motor #19 - Jernsmede Belejringsbrigade\""},
  [710] = {n="Studiet af Elementerne: Sten", l="Find 10 Små Stenskår og bring dem til Lotvil Sandsikker i Ødelandene.", d="Her i Ødelandene er jeg holdt op for at arbejde på mit seneste projekt: mine lænker af elementarbinding.\n\nNår de er færdige, vil de gøre det muligt for magikere at fremkalde endnu kraftigere elementarer til endnu større formål. For at komme i gang har jeg brug for små stenskår til at teste nogle af mine nyeste offensive besværgelser sammen med et par småting, jeg har sat sammen.\n\nSkårene er nemme at samle op fra de ringere stenelementarer mod vest herfra. Kunne du bringe mig nogle?", p="Dette område er perfekt til-- Kunne du holde disse på plads et øjeblik? Ja, lige sådan, langs normalvektoren. Nu, hvad var det nu jeg... Ja. Perfekt til at teste mit seneste projekt. Råmaterialerne, det åbne rum... hvad mere kunne en intelligent og oplyst udøver af kunsten ønske sig?", c="Disse gør det fint, <Name>. Tak. Hmm, lidt mere sand end jeg havde regnet med. Må justere friktionskoefficienten. Nej, vent; den burde stadig være ubetydelig med frostolien.\n\n<Mumlende for sig selv lægger Lotvil den ene næve i håndfladen på sin anden hånd og stirrer på dem, som om han var fascineret.>"},
  [711] = {n="Studiet af Elementerne: Sten", l="Bring 3 Store Stenplader til Lotvil Sandsikker i Ødelandene.", d="<Name>, du har allerede bevist, at du er dygtigere end alle mine lærlinge tilsammen.\n\nDe næste dele, jeg har brug for, kræver lidt mere styrke. Store stenplader kan findes på stenelementarer, hvis du er forsigtig nok. Deres kroppe er stærkere og større, og derfor er de mere tilbøjelige til at have stykker store nok til mine forsøg. Du kan finde dem længere mod vest herfra eller sydøst langs bjergenes kanter.\n\nTag dig god tid; jeg skal bruge et stykke tid på at teste de mindre stykker, du bragte mig.", p="Jeg er meget tilfreds, <Name>. Mine besværgelser påvirkede de mindre stykker præcis, som jeg havde forudsagt. Hvis dette eksperiment er lige så vellykket, som jeg forudser, så vil de elementarer, jeg kan kontrollere, gøre alt, der er fremkaldt før dette, til skamme.", c="<Name>, simpelthen fantastisk! Jeg havde troet, det ville tage et halvt dusin taurener at bringe mig alle disse."},
  [712] = {n="Studiet af Elementerne: Sten", l="Bring 5 Armbeskyttere af Stenbinding til Lotvil Sandsikker i Ødelandene.", d="<Name>, der er endnu en del, jeg har brug for fra elementarerne her i Ødelandene: armbeskytterne af stenbinding fra de større stenelementarer. Efter mine beregninger burde disse armbeskyttere være nok til at måle styrken af mine egne lænker.\n\nMine forsøg på at spejlskue de større stenelementarer viste en flok af dem sydvest herfra, nær nogle oger, hvis jeg husker rigtigt.\n\nBring mig 5 af deres armbeskyttere, bare så jeg har ekstra. Servo er berygtet for at flytte rundt på mine reagenser og min forskning.", p="Stenpladerne, du fandt, var ideelle, <Name>. Lusien tager de ekstra med tilbage til Kharanøs, når vi er færdige her. For de kan jo vise sig nyttige igen.\n\nDe ville for eksempel være et godt grundlag for et praktisk lille ly, når jeg begynder at undersøge en tværfaglig tilgang til højtydende sprængstoffer...\n\n<Lotvils stemme dør hen, mens han vender tilbage til sit eksperiment.>", c="<Name>, har du nogensinde overvejet at blive forskningsassistent? Nej? Jeg ved ikke, hvad jeg skal gøre uden dine evner her. Intelligens, nysgerrighed og styrke--alt samlet i én pakke."},
  [713] = {n="Kølevæsken Sejrer", l="Find Frostolie og bring den til Lotvil Sandsikker i Ødelandene.", d="Lad mig fortælle dig noget om Frostolie: intet kan holde en motor eller tandhjul fra at overophedes lige så godt som den.\n\nDens kølende egenskaber er ekstraordinære, og dens holdbarhed som smøremiddel er uden sidestykke. Og det er ikke alt: den hjælper også med at fastholde fortryllelser på magiske genstande.\n\nJeg har brug for et hætteglas af den for at øge mine lænkers magiske kapacitet og gøre dem kraftige nok til at stoppe vores fremkaldte ven fra at dræbe os alle.\n\nBro'knæk, en kobold-ven af mig, kan lære dig at lave den. Han er i Alteraz.", p="Har du fundet den olie, jeg har brug for? Det ville være så hjælpsomt, hvis du kunne finde noget.", c="Storartet! Dette burde være den perfekte kølevæske til mine nye armbeskyttere. Hvis fortryllelserne ikke holder et århundrede, så giver jeg alle mine ejendele til Tjener.\n\nAlle magikerne i Forsamlingen vil blive så målløse, når jeg er færdig med dette, <Name>. Du må bare vente og se."},
  [714] = {n="Gyro... Hvad?", l="Bring en Gyrokronatom til Lotvil Sandsikker i Ødelandene.", d="<Name>, du har gjort dit arbejde langt ud over alle standarder.\n\n<Lotvil er tydeligvis distraheret af sit arbejde.>\n\nHvis vi nogensinde mødes i Kharanøs, så er du velkommen til at søge arbejde.\n\nOps! Hurtigt, tag fat i... ja, den. Tak.\n\nNu mangler jeg bare én ting mere. Det er en lille del, men ret afgørende, er jeg bange for: en gyrokronatom.\n\nHvis du bare kunne tage ud og hente en og bringe den til mig, burde jeg være klar til at afslutte dette.", p="Ja, ja, ja. Lige et øjeblik.\n\n<Lotvil fortsætter med at arbejde på en slags konstruktion.>", c="HA!\n\n<Lotvil griber gyrokronatomen fra dig.>\n\nPerfekt... næsten færdig. Nej, virkelig. Jeg ER næsten færdig nu. Dette projekt er min højeste prioritet... lige nu. Lad mig sætte denne på plads, så kan du selv se, hvad du har hjulpet mig med at skabe. Det tager mig bare et par minutter mere... måske... muligvis længere. Nåja, måske en hel del længere. Vi får se..."},
  [715] = {n="Flydende Sten", l="Bring en Helbredelseseliksir og en Mindre Usynlighedseliksir til Lusien Skruenøgle i Ødelandene.", d="Jeg tænker, at de ting, du har skaffet til Lotvil, bliver det mindste af vores bekymringer, <Name>. Til gengæld har du vist, at du er mere end dygtig i de videnskaber, Lotvil holder hellige, så hvad med at hjælpe mig?\n\nJeg har brug for en usynlighedseliksir og en helbredelseseliksir; begge kan vise sig nyttige meget snart, hvis han gennemfører dette.\n\nTil gengæld giver jeg dig opskriften på en eliksir, jeg har udviklet, mens jeg lærte af Lotvil. Den er baseret på noget af den forskning, han har lavet her i Ødelandene.", p="Han er tættere på at blive færdig. Hvordan går det på din side?", c="JA!\n\nJeg mener, tak, <Name>. Disse vil være nyttige, mens vi rejser gennem Ødelandene."},
  [716] = {n="Sten er Bedre end Stof", l="Bring nogle Mønstrede Bronzearmbeskyttere til Lusien Skruenøgle i Ødelandene.", d="Jeg ved, hvor billig Lotvil kan være, <Name>, så lad mig lave noget til dig for alle dine besvær. Måske hjælper det endda med at beskytte dig mod den kommende rædsel, som Lotvils nyeste opfindelse er.\n\nJeg har arbejdet med alle de ekstra sten, du samlede til ham, og jeg kan lave nogle flotte armbeskyttere, som du måske vil bruge. De er naturligvis fortryllede.\n\nJeg skal bare bruge mønstrede bronzearmbeskyttere smedet af en smed, så jeg kan færdiggøre de armbeskyttere, jeg laver til dig.", p="Jeg ville ikke vente for længe med at hente den armbeskytter, <Name>.\n\nHvem ved, hvad der sker næste gang?", c="Værsgo, <Name>. Prøv disse på."},
  [717] = {n="Jordens Rystelser", l="Brug Jordens Tegn til at aktivere Ametyst-, Opal- og Diamantsøjlerne og skaf Runestenene.\n\nPlacér runestenene i Jordens Segl for at befri Sortpisk og Hematus.\n\nDræb dem og bring Sortpiskens Lænker, Hematus' Kæder og Jordens Tegn tilbage til Garek.", d="Det er blevet tydeligt, at vi ikke kan sikre, at Sortpisk og Hematus forbliver fængslet i Lethlor. At sorte drager har slået sig ned der, og at ogerne formåede at stjæle Tegnet, viser, at mere drastiske midler må tages.\n\nDragernes fængsel vedligeholdes af tre runestene, som kun kan hentes ved hjælp af Jordens Tegn. Disse runestene kan så bruges til at bryde seglet, der fængsler dem.\n\n<Name>... sørg for, at deres drømme forbliver evige.", p="Stærk magi og kræfter holdt dragernes fængsel så længe, men vi kan ikke tillade nogen mulighed for, at Sortpisk og Hematus kan blive løsladt.", c="Kirin Tårn behøver ikke længere bekymre sig om fangerne i Lethlor. Jeg vender tilbage for at rapportere succes til min herre. Krasus vil uden tvivl være tilfreds."},
  [718] = {n="Luftspejlinger", l="Hent Forsyningskassen for Sigrun Jernhugger.", d="I vores hast for at forlade udgravningsstedet i Uldaman måtte vi forlade mange vogne og kasser med forsyninger undervejs. Ogerne fra Lejr Kosh har været over vores forladte udstyr som gribbe over et rådnende lig. Og de lugter heller ikke meget bedre. End ligene, mener jeg.\n\nUnder alle omstændigheder tog de vognen, der bar alle vores våben og den slags... så--dette er lidt pinligt--vi har ikke kunnet få noget mad.\n\nVi er i lidt af en klemme her, kunne du tænke dig at hjælpe os?", p="Ørkenen er et dårligt sted at være sulten, min ven, lad mig sige dig det.\n\nHej... hvad er det derovre...", c="Tusind tak, <Name>. Mens du var væk, slugte jeg... øh... en mundfuld sand. Det...\n\nNå, nok om det, vi går ud og henter noget mad i aften. Spis som konger!"},
  [719] = {n="En Dværg og Hans Værktøj", l="Find Ryedols Heldige Hakke og bring den tilbage til Prospektor Ryedol syd for Hammertås Udgravningssted.", d="Hej, <Name>. Vær forsigtig herude. Der er Mørkjernsdværge overalt--så ud til at være Skyggesmede-klanen.\n\nDe angreb lige netop den udgravning, jeg arbejdede på--dræbte næsten alle derinde, inklusive min chef Hammertå. Jeg slap knap nok med livet.\n\nUdgravningen ligger lige nord herfra, og jeg prøver at planlægge en måde at få noget af vores forsyninger tilbage, især min heldige hakke.\n\nKunne du tænke dig at hjælpe mig lidt? En af de forbandede Mørkjern må have min hakke! Det kunne være hvem som helst af dem.", p="Ved ikke, hvad Skyggesmederne ledte efter, men de havde helt sikkert et formål.", c="I er min redningsmand, <Class>. Jeg er glad for, at nogen kunne lære de Skyggesmede en lektie eller to. Tak for din hjælp."},
  [720] = {n="Et Håbets Tegn", l="Find Prospektor Ryedol og fortæl ham, at Hammertå Grez er i live.", d="<Der er tekst groft skrevet med kridt på kortet.>\n\n\"Ryedol,\nDe tager mig til Uldaman. Send hjælp.\n-Hammertå\"", c="Hammertå er i live?! Det her er fantastisk, <Name>!"},
  [721] = {n="Et Håbets Tegn", l="Find Hammertå Grez i Uldaman.", d="<Name>, kan du finde ham? Kan du finde Hammertå i Uldaman?\n\nHvis de beskidte Skyggesmede holder ham som gidsel for at finde ud af, hvad han ved om titanudgravningerne, så kunne hele Jernsmede være i stor fare.\n\nI lang tid nu har de Mørkjern været på jagt efter magi til at lave kraftigere golemer. Hammertå gjorde det samme, selvfølgelig, men kun for at stoppe dem.\n\nDe holder ham nok i live, indtil de finder ud af, hvad han ved. Du må skynde dig, hvis du skal redde ham!", c="Ja? Jeg er ked af... <hoste> Føler mig så svag. Kan du komme tættere på, <Class>?\n\nRyedol sendte dig? Muradin være lovpriset, den dreng er ikke så langsom i hovedet, som jeg engang troede. <hoste>"},
  [722] = {n="Amuletten af Hemmeligheder", l="Find Hammertås Amulet og bring den tilbage til ham i Uldaman.", d="Du er modig... <hoste>... at komme ind i Uldaman for min skyld, <Class>.\n\nHvis du virkelig er her for at hjælpe... gamle Hammertå, så... <hoste>... skal du finde... min amulet.\n\nDybskyggen har den... Magregan Dybskygge. Han er et sted herude... i ruinerne, helt sikkert. Den amulet fører dem... <hoste>... lige hen til skrifterne, hvis han ikke bliver stoppet. Det er op til dig, <Name>. Vær venlig... hent den amulet.\n\nSkrifterne vil helt sikkert hjælpe Mørkjern med at lave endnu kraftigere golemer. Det ved jeg bare. Jeg kan mærke det i mine knogler.", p="Skyggesmede-klanen... <hoste> er farlig. Vær forsigtig. <hoste> Du må finde amuletten.", c="Ha! <hoste hoste>\n\nJeg vidste, du ville finde min amulet, <Name>.\n\n<pibende> Godt gået, <Name>. <hoste>"},
  [723] = {n="Troens Udsigt", l="Tag Hammertås Amulet med til Prospektor Ryedol i Ødelandene.", d="<Hammertå holder sine sår og tager et øjeblik til at samle sig, før han taler igen.>\n\nFind Ryedol, <Name>. Bring ham min amulet. <hoste hoste> Han vil... <hoste> finde ud af, hvad der skal gøres. Han ved, at jeg søgte vores folks oprindelse, og han... <hoste>... ved også, at det var min mission at stoppe Skyggesmede-klanen. De må ikke få lov til at finde skrifterne... <hoste>", p="Jeg ville sige, det var en dårlig dag, men dette er Ødelandene: hver dag er en dårlig dag.", c="Hammertås amulet? Jeg tror, mit humør var højere, da jeg troede, han var død. Når man ved det sikkert, gør det kun smerten værre. Denne amulet var hans livsværk. Jeg kan ikke lade hans død være forgæves."},
  [724] = {n="Troens Udsigt", l="Tag Hammertås Amulet med til Historiker Karnik i Jernsmede.", d="Okay, okay... hvem ved, hvad man skal gøre?\n\nHistoriker Karnik! Det er det!\n\nHan er i Jernsmede. Han kan hjælpe. Han og Hammertå arbejdede sammen om at finde de tabte artefakter i Uldaman.\n\nJeg gætter på, at Skyggesmederne fandt ud af, at de to vidste mere, end de lod som.\n\nFortæl Karnik, hvad der er sket med Hammertå, og giv ham amuletten--han vil fortælle dig, hvad der skal gøres nu.", p="Ah, ja. Endnu en rejsende, der søger noget fra dværgene.\n\nSir, jeg er virkelig ked af det, men jeg har ingen tid til meningsløse spørgsmål lige nu.", c="Åh! Nå, dette er en helt anden sag. Du forstår nok ikke alvoren i dette endnu, gør du?\n\nJeg sørger dybt over Hammertås død, men hvis han sendte dig her med sin amulet, så forstod han, hvad der stod på spil.\n\nVi må tage os tid til at sørge over hans død senere.\n\nLad mig vise dig en af grundene til, at denne amulet er så værdifuld."},
  [725] = {n="Ord om en Trussel Bliver Båret", l="Find Rådgiver Bælgrum og giv ham hans seddel.", d="<Name>, løb og find Rådgiver Bælgrum så hurtigt du kan. Fortæl ham, hvad du har set, og spørg ham, hvordan han vil have, at vi skal gå videre. Denne seddel vil forklare ham mere.\n\nI mellemtiden vil jeg tage mig tid til at tale med Hammertås ånd. Måske ved han noget, der kan hjælpe os med at stoppe de Skyggesmede-skiderikkers aktiviteter i Ødelandene. Vi kan kun bede.", p="Hmm? Ja, <Class>.", c="Ah, nyt fra Historiker Karnik. Fremragende.\n\nJeg har altid tid til hans sager.\n\n<Rådgiver Bælgrum åbner seddelen og begynder at læse.>"},
  [726] = {n="Ord om en Trussel Bliver Båret", l="Tal med Historiker Karnik.", d="<Rådgiver Bælgrum når til enden af seddelen, og hans øjne vidner et øjeblik.>\n\nOch, dette er onde budskaber.\n\n<Name>, vend venligst tilbage til Historiker Karnik og fortæl ham, at han på kongens myndighed skal handle hurtigt og bestemt på denne information. Han må stoppe Skyggesmedenes aktiviteter i Ødelandene.", c="Du behandler denne sag med en hast, jeg ville forvente af kongen selv, <Name>.\n\nNå, så. Jeg ved, hvad der vil bringe Skyggesmederne ned.\n\nDeres tilstedeværelse i Uldaman kan bremses, hvis vi angriber dem ved deres operationsbase: Angor-fæstningen."},
  [727] = {n="Til Jernsmede for Jagyins Uddrag", l="Giv Hammerens Segl til Gerrig Knoglegreb i Det Forladte Hulrum i Jernsmede.", d="Tavlen fortæller meget. Men ikke nok! Slet ikke nok!\n\nDer findes en bog, et uddrag som Jagyin skrev for længe siden. ...de folk jeg flygtede fra... de gemmer denne bog mange steder. Og deres lærdeste studerer den. Den rummer enorm viden. Viden til at beskytte os!\n\nGå til Gerrig Knoglegreb. Han er i en butik i Jernsmede, i Det Forladte Hulrum. Vis ham dette segl, så tror han, du er en af dem. Bed ham om Jagyins Uddrag ... og bring det til mig!", p="Hej. Velkommen til min butik, men pas på, hvad du rører ved.\n\nViden kan være dødbringende.", c="Åh. Hilsen, bror.\n\nOg lov til dem under jorden."},
  [728] = {n="Til Underbyen for Jagyins Uddrag", l="Bring Hammerens Segl til Vogter Bel'dugur i Underbyen.", d="Tavlen fortæller meget. Men ikke nok! Slet ikke nok!\n\nDer findes en bog, et uddrag som Jagyin skrev for længe siden. ...de folk jeg flygtede fra... de gemmer denne bog mange steder. Og deres lærdeste studerer den. Den rummer enorm viden. Viden til at beskytte os!\n\nGå til Vogter Bel'dugur i Underbyen i Herrelande. Vis ham dette segl, så tror han, du er en af dem. Bed ham om Jagins Uddrag... og bring det til mig!", p="Ah, vi har en ivrig <Class>, ser jeg. Er du her for at lære af min samling? Godt!\n\nMen vær advaret: ligesom viden giver magt til de stærke... vil den drive de svage til vanvid.", c="Vær diskret med dine tegn, <Class>. Der er dem, der ikke tror på rigtigheden af vores løfte.\n\nOg der er dem, der ville se os fejle, hvis de kendte til os.\n\nVi må altid være forsigtige. Og årvågne. Og tålmodige."},
  [730] = {n="Problemer i Mørkekysten?", l="Rejs til Auberdin og led efter tegn på det dværgiske udgravningshold.", d="Hvor er det dejligt at se en <Class>, der er interesseret i vores verdens store arkæologiske underværker.\n\nOfte bliver vores arbejde afvist som blot en hobby af vores venner i Alliancen. Men det, mange ikke indser, er, at nylige opdagelser i Khaz Mødan har vist, at en stor og mægtig magt truer hele Azerot, fra Herrelande til Kalimdør.\n\nJeg er mest bekymret for mit mandskab, som jeg sendte til Mørkekysten. De har ikke sendt bud i uger.\n\nRejs til Auberdin og led efter et spor til, hvor de befinder sig.", c="Jeg er så glad for, at Chefarkæolog Gråhvisker sendte bud efter os...."},
  [731] = {n="Den Distræte Prospektor", l="Beskyt Prospektor Remrejse, mens han leder efter det mystiske fossil, og vend derefter tilbage til Arkæolog Hulle i Auberdin.", d="Så, Hulle... åh, det er rigtigt, du er ikke Hulle. Hvor er Hulle?\n\nBah, det er ligegyldigt. Vi må finde den stenbørste... jeg mener det mystiske fossil! Vi må finde det fossil. Opdagelsesrejsende-Ligaen i Darnassos vil gerne have en indikation af, hvad jeg har lavet.\n\nFortæl mig, når du er klar, så jagter vi den børste.... jeg mener fossilet! Vi finder noget skriftligt, der kan tilfredsstille Ligaen.\n\nEr du klar endnu?", p="Er prospektoren i live?", c="Stjernerne være lovet, Prospektor Remrejse er i sikkerhed! Jeg sagde jo, at han var distræt. Jeg kan ikke tro, at han insisterede på at blive derude med alle de forfærdelige væsner, der lurer rundt."},
  [732] = {n="Jordens Rystelser", l="Hent Jordens Tegn til Garek.", d="Jeg hørte fra Sigrun, at du har været en stor hjælp for ham. Måske kunne jeg få din hjælp. Jeg blev sendt hertil af min herre, Krasus fra Kirin Tårn, for at sætte en stopper for uroen, der ulmer i Lethlor-kløften.\n\nJeg kan ikke røbe den præcise karakter af min opgave her eller de opgaver, jeg må udføre, men vær sikker på, at det er af afgørende betydning.\n\nEn flok omstrejfende oger, som nogle gange ses nær Lejr Boff, stjal en genstand kaldet Jordens Tegn; jeg må have det. Bring det til mig, så fortæller jeg dig mere.", p="Den nomadiske flok oger rejser mellem deres lejre på tværs af Ødelandene; hedebølgerne fra den tørre jord og de hvirvlende vinde gør det svært at spore deres færd. Jeg har hørt, at de nogle gange rejser gennem Lejr Boff. Hvis du fortaber dig, kan du prøve at lede der.", c="Gode nyheder, du bringer med dig Tegnet, <Name>. Jordens Tegn blev skabt af Mørkjernsdværgene i Angor-fæstningen for at binde to af Dødsvinges hensynsløse løjtnanter, tvillingerne Sortpisk og Hematus."},
  [733] = {n="Samle Skrot", l="Skaf 7 stykker Skrotmetal til Sigrun.", d="Det bliver hårdt her, hvis jeg ikke kan få samlet nogle materialer til at bygge forsvar og andre nødvendigheder. Jeg har bemærket, at ogerne i området ser ud til at være godt udrustet med skrotmetal. Måske var historierne om belejringsmaskiner i Ødelandene ikke så langt ude alligevel...\n\nUnder alle omstændigheder har Prospektoren været bekymret for vores lille lejrs tilstand, så jeg vil gerne i gang snart, hvis jeg kan.\n\nDen største ogerlejr er ved Støvrøgs-grotten, en god tur mod vest herfra.", p="Nå, jeg har klaret mig med det, jeg kunne, men... det er ikke meget. Har du fundet flere forsyninger?", c="Det er en begyndelse, <Name>, og det må gøre det, indtil vi hører noget fra Jernsmede eller Opdagelsesrejsende-Ligaen.\n\nNu, hvis bare jeg kunne finde noget salt et sted til min slukningstønde..."},
  [734] = {n="Det Bliver Svært", l="Tal med Lusien Skruenøgle i Ødelandene.", d="Vidunderligt, vidunderligt.\n\n<Lotvil kigger op på dig et øjeblik, før han vender tilbage til sine lænker.>\n\nGå og tal med Lusien, <Name>. Jeg har brug for et tandhjul nr. 5. Bring det til mig, vil du?", c="Tandhjul nr. 5, hva'? Ja, det her bliver ikke godt."},
  [735] = {n="Stjernen, Hånden og Hjertet", l="Returnér genstandene på Knoglegrebets Seddel til Gerrig Knoglegreb i Jernsmede.", d="Jagyins Uddrag, hva'? Begynder du et nyt kapitel af os, et sted? Glem det, det er ikke min plads at spørge.\n\nJeg vil hjælpe dig, for jeg har et ekstra eksemplar. Vi må hjælpe hinanden, ikke sandt? Sådan trives vi.\n\nJeg kræver tre genstande med magt. Bring dem til mig, så giver jeg dig uddraget.\n\nJeg vil ikke sige deres navne. Ører kan være på os. Men her vil jeg skrive dem ned.", p="Har du de relikvier, jeg bad om?", c="Du er opfindsom, <Class>. Hvis det virkelig er din opgave at begynde et nyt kapitel af vores orden, så tror jeg, du vil lede det godt."},
  [737] = {n="Forbudt Viden", l="Bring Yagyins Uddrag til Tyldrin.", d="Jeg har uddraget til dig, <Name>. Jeg behøver ikke fortælle dig, at du skal passe rigtig godt på det. Og holde det langt væk fra uvenlige hænder.\n\nDenne bog rummer mange sandheder...\n\n...Og sandheden kan brænde.", p="Hov! Du var væk længe. Fik du uddraget?", c="Du fik det! Åh, håbet blinker!\n\nDine bestræbelser kan endnu redde os, <Name>. De burde lave et monument over dig! De burde bygge en helligdom! Må dit navn blive priset, til dine børnebørn har børnebørn!\n\nMedmindre...DE bliver befriet og stiger op til overfladen. Hvis det sker, kan du glemme alt om børn.\n\nHvis DE bliver befriet, er vi alle ormefoder."},
  [739] = {n="Mordfisk", l="Dræb Agmunds morder, Mordfisk.\n\nDræb 12 Stenkælder-Benknækkere.\n\nRapportér til Prospektor Jernbånd i Modansøen.", d="Agmunds spor fører fra vest. Det er let at se på de blodige striber over sten og sand, at dværgen kravlede en vis strækning.\n\nOg her døde han.\n\nVed nærmere eftersyn er ordet „Mordfisk“ klodset kradset ind i en plet af Ødelandenes sandsten.\n\nKradset ved siden af Agmunds døde hånd.", p="Har du nyt om Agmunds skæbne? Fandt du ham?", c="Det er nedslående nyheder, <Name>. Men Agmund havde en stærk arm og et voldsomt hammerhug, og hans kranie var så tyk, som de kommer! Selvom han blev dræbt af de forbandede dyngtrolde, er jeg sikker på, at han tog en hel masse af dem med sig."},
  [743] = {n="Farerne ved Vindraseriet", l="Bring 8 Vindraseri-klør til Ruul Ørneklo i Blodhov-landsbyen.", d="Tak fordi du tog dig tid til at tale med mig, <Name>. Jeg er Ruul, kriger og lærer.\n\nDu har tydeligvis nået en alder, hvor du må forberede dig til dine prøvelser, hvis du skal eventyre meget længere ude af Mulgorr.\n\nHvis du ønsker en prøve af din styrke, så start med at søge efter Vindraseri-harpyerne mod sydøst. De holder til langs bjergenes kanter, væk fra vejen.\n\nDe er en af vores naturlige fjender her i Mulgorr og vil være en god målestok for din dygtighed.", p="Vindraserierne er dødbringende fjender. Deres styrke i kamp matches kun af deres trang til frisk kød.", c="Du har klaret dig godt, <Name>. Du virker godt rustet til at rejse videre. Må vinden altid være i ryggen på dig."},
  [746] = {n="Dværgisk Graven", l="Saml 5 Prospektorens Hakker.\n\nSmid Brudte Redskaber ved en esse ved at knuse Prospektorens Hakker.\n\nBring 5 Brudte Redskaber til Baine Blodhov i Blodhov-landsbyen.", d="Der er dværge, der forbereder en udgravningsplads mod nordvest. De tror, at hemmeligheder ligger gemt i jorden, og det er sandt, men at hule og besudle landet er ingen vej til at tjene dets lærdomme.\n\nSaml dværgenes gravende redskaber, knus dem, og vend tilbage til mig med dværgenes brudte redskaber.\n\nDu kan knuse redskaberne ved en esse. Du finder en i Tordenskrænt, men enhver esse – selv en esse i dværgenes lejr – vil gøre det.", p="Hej, <Name>. Har du de Brudte Redskaber? Dværgenes graven vil gøre kodo-oksene i Mulgorr rasende. Denne vanhelligelse må stoppes!", c="Tak, <Name>. Dette vil berolige Mulgorrs udyr. Og hvis ånderne vil det, vil det lære dværgene, at udhuling af landet ikke er vejen til viden."},
  [748] = {n="Giftvand", l="Bring 6 Prærieulv-poter og 4 Slettegænger-klør til Mull Tordenhorn i Blodhov.", d="Goblinere og deres håndlangere har besmittet vores hellige vandbrønde! Det kan vi ikke tillade.\n\nFor at rense hver brønd må jeg skabe et renselsestotem, og så må du bringe totemet til brønden og udføre en renselsesritual.\n\nFørst skaber vi et renselsestotem til Vinterhov-vandbrønden. Til det må landet yde sin hjælp. Jag prærieulve for deres poter og voksne slettegængere for deres klør. De findes mod sydvest.\n\nVend tilbage til mig med poterne og klørne, <Name>.", p="Har du poterne og klørne, <Name>?", c="Du har klaret dig godt, <Name>. Jeg tager disse og binder deres kraft ind i et renselsestotem."},
  [749] = {n="Den Hærgede Karavane", l="Morin Skyjæger vil have dig til at undersøge indholdet af en forsyningskasse ved den Hærgede Karavane.", d="For nogle dage siden fandt vi en Venture A/S-karavane, der rejste under vagt på den nordlige bred af Stentyr-søen. Vi havde mistet to af vores i et tidligere slag, så vi var hurtige til at angribe og lægge karavanen øde.\n\nVi lod forsyningskasserne ligge, fordi vi troede, at vores fakler ville ødelægge alt af værdi, men eftersom Venture A/S' bjærgere er set nær de brændte vogne, tager vi måske fejl.\n\nMåske kunne du gå til karavanen og undersøge indholdet af kasserne.", c="Alle sider af kassen er stemplet med Venture A/S' Mineafdelings segl. Omhyggeligt trykte noter på siden af kartonen viser, at indholdet skal behandles på et af deres centrale anlæg."},
  [750] = {n="Jagten Fortsætter", l="Grull Falkevind i Narache-lejren vil have dig til at bringe ham 10 Bjergpuma-pelse.", d="En tauren, der er dygtig i jagtens veje, ved, at hans bytte ikke kun er til trofæ. Udyrene på sletterne giver os et middel til overlevelse. Du vil gøre et stort indtryk på de ældste, hvis du kan bringe nogle højt værdsatte Bjergpuma-pelse tilbage. Du finder udyrene lurende i bakkerne mod syd.\n\nVores børn har brug for tøj, og vores telte skal lappes.", p="Hvis du kan skaffe pelse til stammen, vil jeg give besked til min far, Høvding Falkevind, om dine generøse gerninger.", c="Taurenerne i Narache takker dig for disse forsyninger, <Name>. Med din dygtighed i jagtens veje vil du sikkert en dag blive æret i Tordenskrænt."},
  [751] = {n="Den Hærgede Karavane", l="Returnér Venture A/S' Dokumenter til Morin Skyjæger nær Blodhov-landsbyen.", d="Når låget åbnes, afsløres en tæt pakket blanding af malm og mineraler – endnu et bevis på Venture A/S' mineoperation i Mulgorr. Oven på malmen og mineralerne fjerner du en tæt bundet bunke papirer.\n\nOppe i foden af bjergene mod øst kan du knap høre lyden af arbejde, og du kan se røg stige op fra et stort bål.", p="Hilsen, <Name>. Har du lært noget nyt om Venture A/S' planer og aktiviteter i vores hjemland?\n\nHvis de planlægger at udnytte vores lande, som de har gjort andre steder, vil Udløberne hurtigt gøre en ende på det.", c="Det ser faktisk ud til, at Venture A/S forsøger at berøve os vores naturressourcer. Godt at vide det med sikkerhed, og nu synes vi, at vi må gøre noget ved det."},
  [753] = {n="En Ydmyg Opgave", l="Tag en Vandkande fra vandbrønden.\n\nReturnér kanden til Høvding Falkevind i Narache-lejren, som ligger nordvest for vandbrønden.", d="Jeg har fulgt mange stier gennem livet, og disse gamle ben mangler den kraft, de engang havde. Jeg kan stadig udføre mine pligter over for stammen. Nogle gange tager det bare en gammel kvinde lidt længere tid at udføre opgaven.\n\nMen du ser ud som en ivrig <Class>. Lad os sætte lidt af den ungdommelige vitalitet på prøve. Tag en vandkande fra brønden og bring den til min søn, Høvdingen, i Narache-lejren.\n\nHusk, at selv den mest ydmyge opgave kan vinde de ældstes anerkendelse.", p="Du ser ud, som om du er vendt tilbage fra sletterne. Har du nyt fra Storemoder Falkevind?", c="Du bar denne kande tilbage efter Storemoderens ønske, kan jeg se.\n\nDin villighed til at hjælpe andre og sørge for taurenerne i Narache-lejren får mig til at tro, at du en dag vil gøre stammen stolt i Tordenskrænt."},
  [754] = {n="Vinterhov-renselsen", l="Brug Vinterhov-renselsestotemet ved Vinterhov-vandbrønden, og vend derefter tilbage til Mull Tordenhorn.", d="Jeg har skabt totemet til at rense Vinterhov-vandbrønden. Nu skal du bringe det til brønden og udføre en renselsesritual. Du finder den mod sydøst, bevogtet af onde goblinere!\n\nDette bliver ikke en let opgave, men du må gøre det, hvis vi nogensinde skal bruge dens vand igen.\n\nHeld og lykke, <Name>.", p="Vent ikke, <Name>. Vinterhov-brøndens besmittelse skal fjernes!", c="Nyheden om din bedrift nåede mig for et øjeblik siden – allerede drikker udyrene nær brønden ivrigt af den.\n\nDu har gjort en stor gerning for landet, <Name>. Og du har gjort en stor gerning for taurenerne."},
  [755] = {n="Jordmoderens Salvelser", l="Rejs til Seer Gråtunge, der bor i bakkerne lige syd for Narache-lejren.", d="Din villighed til at udføre en ydmyg opgave for taurenerne i Narache og din iver efter at lære er ædle træk, <Name>. Jeg tror, at du en dag vil blive hyldet i Tordenskrænt som en <Class> af storhed.\n\nFør det må du begive dig ud på Jordmoderens Salvelser, hvoraf der er tre.\n\nDen første prøve er Styrkens Ritual. Rejs til Seer Gråtunge og fortæl ham, at Høvding Falkevind har sendt dig.\n\nDu finder seerens bolig direkte syd for Narache-lejren, gemt væk i bakkerne.", c="Høvding Falkevind sendte dig? At begive sig ud på Jordmoderens Salvelser er ingen lille opgave..."},
  [756] = {n="Tordenhorn-totemet", l="Bring 6 Sniger-klør og 6 Puma-klør til Mull Tordenhorn.", d="For at skabe Tordenhorn-renselsestotemet må du samle klørne fra Mulgorr-slettens rovdyr. Jag prærie-snigere for deres sniger-klør og slettepumaer for deres puma-klør, og vend derefter tilbage til mig.\n\nDu finder prærie-snigerne og slettepumaerne mod øst og vest.", p="<Name>, har du klørne, jeg sendte dig for at samle? Tordenhorn-vandbrønden bliver mere besmittet for hver time, der går!", c="Tak, <Name>. Den renhed, hvormed disse udyr jager, er afgørende for skabelsen af det næste renselsestotem.\n\nGoblinerne vil aldrig lære forskellen mellem at kæmpe mod landet og at leve i harmoni med det."},
  [757] = {n="Styrkens Ritual", l="Dræb Børsterygerne i Brombærklinge-kløften og bring 12 Børsteryg-bælter til Høvding Falkevind i Narache-lejren.", d="Jordmoderens Salvelser er de skridt, en ung tauren må tage for at opnå respekt i Tordenskrænt.\n\nFørst skal du bestå Styrkens Ritual. I denne prøve må du bevise dit mod ved at slå stammens fjender ihjel.\n\nBørsterygerne i Brombærklinge-kløften mod øst trænger ind på vores stammeland. De overfalder vores jagtgrupper og stjæler fra landsbyen om natten.\n\nVis din tapperhed ved at slå disse skurke ihjel, og vend tilbage til Høvdingen i Narache-lejren med deres bælter som bevis på dine bedrifter.", p="Har du gennemført Styrkens Ritual, <Name>? Jeg kræver bevis på din tapperhed mod stammens fjende, Børsterygerne.", c="Du har bestået den første prøve i Jordmoderens Salvelser. Stammen vil være stolt."},
  [758] = {n="Tordenhorn-renselsen", l="Brug Tordenhorn-renselsestotemet ved Tordenhorn-vandbrønden, og vend derefter tilbage til Mull.", d="Totemet er klar, <Name>. Og igen er det din opgave at udføre renselsesritualen.\n\nGå til Tordenhorn-vandbrønden, nord for landsbyen, og brug Tordenhorn-renselsestotemet i din ritual. Når du har gjort det, vender du tilbage til mig.\n\nMåtte ånderne lede dig.", p="Tordenhorn-vandbrønden er stadig besmittet, <Name>. Du må udføre ritualet!", c="Forfædrene til Tordenhorn-klanen talte til mig i en drøm og roste dig for dine gerninger ved deres brønd.\n\nAf taknemmelighed ønsker de at give dig dette..."},
  [760] = {n="Vildmane-renselsen", l="Brug Vildmane-renselsestotemet ved Vildmane-vandbrønden, og vend derefter tilbage til Mull Tordenhorn.", d="Din renselse af Vinterhov- og Tordenhorn-brøndene tales der om blandt ånderne, unge <Name>. Vildmane-totemet er lavet, og din sidste opgave venter.\n\nVildmane-vandbrønden ligger nord for Tordenskrænt. Udfør ritualet! Helbred landet for goblinernes gifte! Lad rent vand flyde igen!", p="Den sidste vandbrønd er stadig stinkende og giftig, <Name>. Du må ikke tøve!", c="Du har gjort det. Du har renset brøndene og helbredt vores land. Blodhov-landsbyen er taknemmelig, <Name>.\n\nMåtte vinden hviske om dine bedrifter i hundrede årstider, og må Mulgorrs vande forblive rene for evigt."},
  [761] = {n="Svæv-jagt", l="Bring 8 Trofæ-svævefjer til Harken Vindtotem i Blodhov-landsbyen.", d="Svæven er en snedig fugl, og den er svær at finde og jage. En samling Svævefjer er et mærke for en jægers snilde og beslutsomhed.\n\nHvis du er villig til at påtage dig denne opgave, så begiv dig ud på sletterne og jag svæven.\n\nBring mig deres fjer, og bring ære til din klan.\n\nSvæverne kan findes overalt i Mulgorr, men dine øjne må være skarpe for at få øje på dem, og dine hove må være hurtige til at fange dem.", p="Har du fundet svæverne, <Name>? Har du deres fjer?", c="Jeg ved, at det ikke var en let opgave at samle disse fjer, <Name>. Med dette beviser du, at du er en <Class> af fortjeneste. Det er godt at have dig i Blodhov-landsbyen."},
  [762] = {n="En Ambassadør for Det Onde", l="Dræb Ambassadør Infernus i Angor-fæstningen og bring bevis på hans død til Rådgiver Bælgrum i Jernsmede.", d="Ambassadør Infernus blev sendt til Angor-fæstningen af Ragnaros selv for at holde øje med Skyggesmedjen, der leder efter tabte artefakter i Ulddalen.\n\nDet har allerede betydet enorme tab for vores folk, men det er tydeligvis blevet værre. Jeg tøver med at gætte, hvor mange artefakter de ville kunne finde og bruge mod Jernsmede.\n\nVores mål er simpelt, <Class>. Vend tilbage til Ødelandene og tilintetgør Ambassadør Infernus. Når truslen er elimineret, skal du vende tilbage til Rådgiver Bælgrum med bevis for din sejr.\n\nDet ligger nu i dine hænder.", p="Tiden er afgørende, <Name>. Ragnaros vil ikke vente på, at vi forbereder os.", c="<Name>, din hengivenhed over for Jernsmede og det dværgiske folk kan ikke afvises. Jeg takker dig for din hjælp i denne sag.\n\nJeg sender besked til Historiker Karnik om, at du har lykkedes, og jeg sørger også for, at der bliver sendt hjælp til Ødelandene så hurtigt som muligt for at hjælpe med at genvinde udgravningsstedet. Tak igen.\n\nFør du går, er der én ting mere, jeg vil bede dig om i Kong Bronzeskægs navn."},
  [766] = {n="Mazzranakke", l="Bring et Prærieulvehjerte, et Slettepuma-lårben, et Slettegænger-skæl og en Svæv-kråse til Maur Regnkalder i Blodhov-landsbyen.", d="Min bedstefar fortalte mig historier om sine kampe med en slettegænger ved navn Mazzranakke. Han fortalte mig om dens dæmoniske røde øjne, skarpe klør og giftige bid.\n\nSom skæbnen ville have det, mødte jeg den, mens jeg rejste over sletterne, og den tog et grimt bid i min skulder. Den var lige så forfærdelig, som min bedstefar havde beskrevet. Jeg skal bruge nogle vanskeligt fundne dyredele til at rense infektionen fra dens bid: et prærieulvehjerte, et slettepuma-lårben, et slettegænger-skæl og en svæv-kråse.\n\nSkynd dig, tiden er afgørende.", p="Min feber bliver værre, og mine tanker driver ind i delirisk mareridt... Jeg burde have vidst, at jeg ikke kunne klare et udyr, som min bedstefar ikke kunne besejre...\n\nHar du ingredienserne til kuren? Jeg frygter, at hvis jeg ikke renser infektionen snart, bliver den min død.", c="Ah, tak, <Name>. Med de ting, du bragte mig, kan jeg lave den kur, jeg har brug for, for at stoppe infektionens spredning og til sidst helbrede den helt. Jeg skylder dig mit liv.\n\nMen jeg vil aldrig glemme det skrigende kald, da Mazzranakke kom over mig, og farvepragten da dens næb faldt ned...\n\nVær på vagt på dine rejser."},
  [767] = {n="Synens Ritual", l="Tal med Zarlman Tomåne i Blodhov-landsbyen.", d="Synens Ritual, en af Jordmoderens Salvelser, vil hjælpe dig med at opnå de ældstes respekt i Tordenskrænt.\n\nVores folk har lært, at landet er vores helligste forsørger. For at deltage i den ritualistiske vision skal du tale med landsbyens åndelige leder, Zarlman Tomåne.", c="Jeg fornemmede, at du ville komme til mig, <Class>. Jeg kan altid genkende en, der forsøger at bestå Jordmoderens Salvelser."},
  [768] = {n="Samling af Læder", l="Bring 12 stykker Let Læder til Veren Højgænger i Tordenskrænt.", d="Hilsen, unge. Der er et glimt i dit øje; jeg kan se, at du er ivrig efter at vende tilbage til sletterne for jagten. Må du bringe ære til din klan!\n\nJeg arbejder med dyrenes skind og syr dem til tøj og rustninger til folket i Tordenskrænt.\n\nHvis du jager udyr og bringer mig deres skind, så vil jeg sy noget til dig.", p="Hej igen. Har du været på jagt? Har du skind til mig?", c="Ah, disse er meget fine stykker. De bliver til fint læderarbejde.\n\nVær så venlig, <Name>. Tag dette i bytte..."},
  [769] = {n="Kodo-skindtaske", l="Bring 4 Let Læder og 4 Grov Tråd til Veren Højgænger i Tordenskrænt.", d="Mulgorrs kodo-udyr er stærke og robuste – egenskaber, der er meget respekteret blandt os. Hvis du er dygtig til lædersløjd og ønsker at lære at lave en Kodo-skindtaske, så bring mig forsyninger til min handel.\n\nGør du det, deler jeg min viden med dig.", p="Har du mine forsyninger, <Name>?", c="Ah, godt. Tak, <Name>. Mit hjerte svulmer af stolthed over at se unge interesserede i lædersløjdens håndværk."},
  [771] = {n="Synens Ritual", l="Saml 2 Brøndsten og 2 Rav-korn og bring dem tilbage til Zarlman Tomåne i Blodhov-landsbyen.", d="For at komme igennem Synens Ritual må du samle de reagenser, der skal bruges til at lave Seernes Vand.\n\nJeg skal bruge brøndsten, som kan findes rundt om vandbrøndene i Mulgorr. Med dem vil jeg blande Rav-korn, som falder ned under de mægtige træer i vores land.\n\nDisse reagenser indeholder magiske elementer, og når de brygges og indtages foran stammens bål, vil du opleve en vision. Følg den, og den vil lede dig til næste trin i denne hellige søgen.", p="Når du har samlet nok brøndsten fra rundt om vandbrøndene og Rav-korn fra under træerne, vil jeg tilberede Seernes Vand til dig.", c="Jeg ser, at du har lært at samle fra vores hellige land, <Name>. Det tager kun et øjeblik for mig at brygge Seernes Vand."},
  [773] = {n="Visdommens Ritual", l="Rejs til De Røde Klipper øst for Tordenskrænt og tal med Forfædres Ånd.", d="For at opnå accept blandt de ældste i Tordenskrænt skal du dernæst gennemføre Visdommens Ritual.\n\nNu hvor du har bestået Synens Ritual, vil forfædrenes ånder ved De Røde Klipper give dig vores forfædres velsignelse. Kun dem, der har drukket af Seernes Vand, kan opnå velsignelsen.\n\nRejs øst for Tordenskrænt, til De Røde Klipper, og søg efter Forfædres Ånd, <Name>.", c="Du har vist stor flid i din higen efter at bestå Jordmoderens Salvelser, <Name>.\n\nVi, Forfædres Ånder, repræsenterer de mægtige taurener, der modigt gav deres liv for at grundlægge og beskytte vores store by Tordenskrænt. Jeg overdrager hermed ansvaret for denne beskyttelse til dig.\n\nDu har bestået Visdommens Ritual, unge <Class>. Gå ind i Tordenskrænt med stolthed."},
  [775] = {n="Rejsen til Tordenskrænt", l="Tal med Cairne Blodhov i Tordenskrænt.", d="Du vil nu blive æret i vores store by. Enhver <Race>, der er værdig til at fuldføre Jordmoderens Salvelser, opnår den ære.\n\nTil din sidste opgave skal du søge vores ædle leder, Cairne Blodhov, der bor på toppen af det højeste bjergplateau i Tordenskrænt.", c="Hilsen, unge <Class>. Jeg ser, at du fandt vej til min dørtærskel."},
  [777] = {n="Det Her Bliver Svært", l="Bring Tandhjul #5 til Lotvil Sandfærdig.", d="Okay, her er den.\n\nJeg står lige herovre... bag dækning.\n\nKan være, du vil slutte dig til mig.", p="<Uden at se op fra lænkerne rækker Lotvil en hånd frem og vifter utålmodigt med fingrene.>\n\nTandhjulet, <Name>, tandhjulet!", c="Ah, perfekt. Træd tilbage, mens jeg gør mig klar til at skabe mere historie!\n\n<Lotvil arbejder videre febrilsk.>"},
  [778] = {n="Dette Bliver Svært", l="Besejr Fam'retor-vogteren og bring Lotvils Elementarbindingens Lænker tilbage til Lotvil Sandfærdig.", d="Haha! Færdig! Lænkerne er klar!\n\nTiden er inde, Lusien. Tiden er inde, Servo!\n\nEr du klar til at overvære den perfekte blanding af alkymi, ingeniørkunst og det arkane, <Name>?\n\nJeg vil nu fremkalde en mægtig elementar. Dette er en banebrydende dag for os alle.", p="Ikke helt det resultat, jeg havde forventet. Kunne du skaffe mine lænker tilbage?", c="Tak, <Name>. Det var en ret prøvelse, ikke?\n\nJeg er ikke sikker på, hvad der kan have gået galt. Det var godt, at mine magier var her til at sende skabningen tilbage til dens hjemplan.\n\nMåske en lille tak for alt dit hårde arbejde..."},
  [780] = {n="Kampsvinene", l="Grull Falkevind i Narache-lejren vil have dig til at dræbe Kampsvin og bringe 8 Kampsvinesnuder og 8 Kampsvinesider tilbage.", d="Kampsvinene i Brombærklinge-kløften mod øst trænger ind på vores stammes jagtmarker. De er trænet til at være ondskabsfulde af Børsterygge-kvilsvinene, som vi er i krig med.\n\nTag af sted, slå de modbydelige væsener ihjel og bring nogle snuder og sider med, så vi kan lave gryderet til vores unge.", p="Kampsvinenes aggressivitet vokser. Har du sendt dem et klart budskab og bragt nogle snuder og sider tilbage endnu?", c="Fortræffeligt. Disse ingredienser bliver til en fin gryde, og tabet af de svin burde være en rimelig lektie for de modbydelige Børsterygerne."},
  [781] = {n="Angrebet på Narache-lejren", l="Bring Børsterygge-angrebsplanerne til Høvding Falkevind i Narache-lejren.", d="Efter omhyggelig gennemgang af kortet indser du, at det, du har opdaget, er planerne, som Børsterygge-krigshøvdingen har lavet til en langvarig belejring af Narache-lejren.\n\nHøvding Falkevind kan sikkert bruge denne information!", p="Du ser bekymret ud, <Name>. Hvad for nyheder bringer du?", c="Dette er da yderst alarmerende! Men med disse oplysninger kan vi kalde på vores brødre fra Blodhov-landsbyen for at hjælpe med at forhindre angrebet. Du har reddet mange taurener, <Name>."},
  [782] = {n="Brudte Alliancer", l="Dræb Chef Tho'grøn og bring Jordens Tegn til Gorn i Kargat.", d="Fra Hordens alliance med dragen Dødsvinge under den Anden Krig ved vi, at to af hans løjtnanter, Sortpisk og Hæmatus, blev fængslet i Lethlor-kløften langt mod øst. Vi må få tavshed på vores fordærvede gamle allierede for at genoprette æren for Horden!\n\nVi lejede Tho'grøn og hans bande af ogremercenarer til at hjælpe os med at skaffe Jordens Tegn, en nøgle der skal bruges til at låse drakernes fængsel op. Tho'grøn forrådte os dog, overmandede os og tog det for sig selv. Gå til Lejr Boff og tag det tilbage!", p="Tho'grøns forræderi... er der nogen undren over, hvorfor ogrerne ikke længere er en del af Horden? Jeg vil være glad for at se ham død og Jordens Tegn returneret.\n\nHvis du ikke har sendt ham afsted endnu, så spild ingen tid på at tage til Lejr Boff. Den ligger sydøst for Kargat.", c="Med Tho'grøn død, hans lig renset af ørkenvindene og ådselgribbene, vil ogrerne blive kastet ud i kaos. Det er en lille sejr, men den fører til en meget større\n\nJordens Tegn er nu i vores besiddelse, og vi kan åbne de sorte drakers fængsel i Lethlor. Vi skal befri dem fra evig fængsling, om end til deres undergang!"},
  [785] = {n="En Strategisk Alliance", l="Søg efter Lar Snigetusk på den vestlige flanke af Sen'jin-landsbyen.", d="Trall er en meget klog og ædel leder. Hans udholdenhed på slagmarken matches kun af hans diplomatiske takt.\n\nMørkspyd-trollene har vist sig at være uvurderlige allierede for orkkinden. Af loyalitet og ære har vi svoret dem en beskyttelsespagt.\n\nHøvdingen har sendt ordre om, at vores Mørkspyd-venner i Sen'jin-landsbyen ikke må være under nogen direkte trussel. En af deres mest betroede spejdere, Lar Snigetusk, holder et vågent øje med deres vestlige flanke.\n\nSøg Lar og assister, hvor det er nødvendigt."},
  [787] = {n="Den Nye Horde", l="Mød op hos Gornek i Hulen.", d="Throm'ka, <Class>. Jeg er Eitrig, betroet af Trall til at føre tilsyn med rekrutternes træning.\n\nHorden er ikke længere, hvad den engang var. Der var en tid, hvor jeg forlod Horden, desillusioneret over de magtsyge håndlangeres voksende indflydelse fra den Brændende Legion. Under min landflygtighed blev jeg taget til fange af en gruppe mennesker, men blev reddet af Høvdingen. Da jeg hørte hans vision om en Horde befriet for dæmonisk indflydelse, styret af shamanerne, vendte jeg tilbage.\n\nGornek vil have flere instrukser til dig.", c="Endnu en af Eitriggs rekrutter, hm?\n\nEn ussel tilstand, vi befinder os i, hvis dette er det bedste, Horden kan frembringe. Lige meget. Når vi mener, du er klar til at forlade dalen, vil du være en stolt kriger i Horden."},
  [791] = {n="Bær Din Vægt", l="Furl Hånbryn i vagttårnet på Barberbakken vil have 8 Lærredsstykker.", d="Alderen har gjort mig ubrugelig i kamp. Nu gør jeg mig nyttig på andre måder.\n\nFra dette udsigtspunkt holder jeg øje med indtrængere. Efterhånden som vores styrke her vokser, finder jeg mig selv i at blæse i signalhornet mindre og mindre.\n\nFor at fordrive tiden laver jeg ting, der kan hjælpe yngre, dygtigere krigere med at forsvare vores hjemland.\n\nFor din skyld kan jeg sy en taske til dine ejendele. Hvis sådan en genstand ville være nyttig for dig, så bring mig noget lærred, et materiale som er almindeligt hos menneskene og centaurerne.", p="Jeg kæmpede stolt side om side med Høvdingen, da disse lande blev erobret. Kampens ar præger min hud.\n\nHordens ære blev opretholdt med hjælp fra min økse og mit krigsskrig under nederlaget for Archimonde, da den uhellige alliance med menneskene og elverne blev dannet af nødvendighed.\n\nMen min stilling som vagtmand og forsørger har givet mig en ny følelse af værdi.", c="Fortræffeligt, <Name>. Enhver god <Class> vil helt sikkert finde en brug for denne taske på slagmarken.\n\nJeg hilser din kraft og din villighed til at dø i Hordens navn!"},
  [793] = {n="Brudte Alliancer", l="Brug Jordens Tegn til at aktivere Diamant-, Opal- og Ametystsøjlerne og få Runestenene.\n\nPlacer runestenene i Jordens Segl for at befri Sortpisk og Hæmatus.\n\nDræb dem og bring Sortpiskens Lænker, Hæmatus' Kæder og Jordens Tegn tilbage til Gorn.", d="Jordens Segl holdes af tre runestene, placeret i Diamant-, Opal- og Ametystsøjlerne i Lethlor-kløften. Med Jordens Tegn vil du kunne fjerne runestenene og låse Jordens Segl op.\n\nVær dog på vagt, <Name>, for de sorte drager Sortpisk og Hæmatus er ikke til at spøge med. Slå dem ihjel og bring mig deres lænker.\n\nFor at nå kløften skal du rejse til den fjerne østlige del af Ødelandene. Vær dog forsigtig, for kløften er hjemsted for utallige drager.", p="Der er få fjender, der er farligere end drageslægten, og få drager kæmpede så rasende som Sortpisk og Hæmatus.", c="Den sorte drageflugt fortsætter med at alliere sig med de affaldne Sortklippe-orker, og begge må bringes på linje eller fjernes. Nu hvor Sortpisk og Hæmatus er døde, kan vi rette vores opmærksomhed mod vest, mod Sortklippe-spiret."},
  [812] = {n="Behov for en Kur", l="Find Kor'gaan i Orkgrimmar og hent Giftstjert-modgiften. Bring derefter modgiften til Rhinag nær Durdotars nordvestlige grænse.", d="<Name>... dit timing er perfekt. Jeg håber bare, at jeg kan gengælde din hast.\n\nJeg var uforsigtig, mens jeg kæmpede mod nogle giftstjerter i nærheden, og en af dem stak mig dybt. Jeg kan mærke, hvordan giften svækker mig, lige nu. I dette tempo har jeg måske en time tilbage at leve. Men jeg får brug for din hjælp, hvis jeg skal overleve...\n\nKor'gaan i Orkgrimmar ved, hvordan man laver modgiften. Find ham... og skynd dig, <Name>. Jeg kan ikke holde meget længere. Han burde være i Skyggeklyngen.", p="Jeg er næsten glad for, at jeg ikke kan vende tilbage til Sen'jin, som jeg er nu. Min svaghed og dumhed ville helt sikkert blive hånet.", c="<Name>, du har reddet mit liv. Tak.\n\nTag venligst dette; jeg håber, det i det mindste kan hjælpe dig på dine rejser, hvis ikke det kan give dig nogle mønter. Ud fra hvad du siger, får jeg ikke brug for det lige med det samme. Kor'gaan vil lade mig gennem flere af hans ritualer, indtil jeg beviser mig selv. Mere svinedrabbing, mere indsamling af skorpionhaler... <suk>"},
  [833] = {n="En Hellig Begravelse", l="Vidensvogter Regnstolpe vil have dig til at dræbe 8 Børsterygge-indtrængere ved Røde Klipper.", d="Kun de mest tapre taurener bliver lagt til hvile ved Røde Klipper, vores hellige begravelsesplads. Det er en ære, der tilfalder de store krigere, som var med til at grundlægge og forsvare Tordenskrænt, og dem der har givet deres liv for stammernes og høvdingernes fælles bedste.\n\nMen det ser ud til, at en ond trussel har fundet vej til vores hellige land. En flok Børsterygge-indtrængere hærger gravpladsen, og jeg er for gammel og forbi min storhedstid til at drive dem væk.\n\nDe må fordrives med magt, <Name>.", p="Børsterygge-indtrængerne skal fordrives fra vores hellige begravelsesplads, <Name>.", c="Velgjort. Du har sendt de modbydelige Børsterygerne et klart budskab. De vil tænke sig om to gange, før de forsøger at blande sig i dette hellige sted igen."},
  [836] = {n="Redning af OOX-09/HL!", l="Eskorter OOX-09/HL til kysten bag Overlook-klippen, og rapportér derefter til Oglethorpe Ubemærket i Bytteviken.", d="Gnomens stemme knitrer endnu en gang fra robotten:\n\n\"Jeg er nødt til at flytte OOX-09/HL til et åbent, sikkert sted, så den kan begynde en lang startprocedure. Den har indbygget camouflage, men jeg skal bruge tid på min ende til at gøre den driftsklar igen. Eskorter robotten fra dens nuværende placering til, lad os sige, kysten bag Overlook-klippen! Det burde være et perfekt sted, og langt nok til at få tingene i gang!\"\n\n\"Eskorter den sikkert til kysten, og kom så og tal med mig i Bytteviken! Oglethorpe Ubemærket - slut!\"", c="Åh, DU er den store redder af OOX-09/HL! Jeg kan slet ikke begynde at udtrykke min taknemmelighed for din hjælp! Min serie af hjemsøgende robotter trænger til mere udvikling, men din redning har sparet mig for utallige timers ekstra genopbygningstid og mange guldstykker i produktionsomkostninger!\n\nVær venlig at tage dit valg af en af de genstande, jeg har. Tak endnu en gang for din generøse hjælp, <Name>, mine robotter og jeg står i gæld til dig!"},
  [838] = {n="Skolomancen", l="Tal med Apoteker Tøvers ved Bolværket, Vestlige Pestlande.", d="På øen Kær Darrow ligger Skolomancen - en skole, der tjener som højborg for Svøben. Vores fjende bor derinde, sikkert tilladt at forfølge forskning, der styrker deres magt. En dør spærrer vejen, og uanset hvor meget vi prøver, er der ingen adgang uden en ordentlig nøgle.\n\nApoteker Tøvers er velbevandret i Skolomancen og har en idé om, hvordan man kan skaffe en nøgle. Du har bevist din værdi over for mig som en, der kan få ting gjort; jeg betror nu denne opgave til dig. Tal med ham om sagen.", c="Ja, <Class>, Overeksekutoren nævnte, at du måske er den, man kan stole på i sagen om nøglen. Jeg har dedikeret en god del af mine seneste studier til Skolomancen, og jeg tror, jeg kender en måde, hvorpå du kan skaffe en nøgle, der lader dig passere hoveddøren når som helst.\n\nDenne opgave bliver ikke let, men sådanne opgaver er sjældent det. Du ser helt sikkert ud som den type, der ved dette som en kendsgerning."},
  [842] = {n="Værnepligt ved Korsvejen", l="Følg den vestlige vej fra Kargals Fjerne Vagtpost.\n\nVed T-krydset drejer du til venstre og følger vejen mod syd.\n\nFind Sergra Mørktorn ved vejkrydset inde i Korsvejen.", d="Tag dette underskrevne hvervebrev med til Korsvejen.\n\nSergra Mørktorn, forbandet være hendes skind, har ansvaret der. Hun er en ond shaman, der får dit hoved til at snurre rundt, før hun lader dig gøre noget nyttigt. Thrall er overbevist om, at hun er noget særligt, men det er jeg ikke så sikker på.\n\nDu bliver nødt til selv at beslutte dig, unge hvalp...", p="Nå, nå, nå, hvad har vi her? Har Kargal fundet mig værdig til endnu en rekrut?", c="Fint, <Name>. Du vil tjene dit ophold hos Horden? Der er rigeligt at lave her, så lyt godt efter og gør, hvad du får besked på.\n\nJeg ser det blik i dine øjne, tro ikke, jeg vil tolerere nogen frækhed. Thrall selv har erklæret, at Hordens kvinder står på lige fod med jer mænd. Respektløshed over for mig, selv i mindste grad, og du vil lære, hvad ægte smerte er."},
  [847] = {n="Raptorens List", l="Tal med Tor'gon.", d="Denne... denne kraft.... Er det shamanernes kraft, som Tor'gon forsøgte at vise mig? Jeg må sige, det er interessant. Fortæl Tor'gon, at han har overbevist mig... for nuværende. Jeg vil lytte til, hvad han har at sige.", c="Når fortryllelsen fortager sig, vil jeg tale med Gor'mølle. Tak for din hjælp med at bringe Gor'mølle tilbage til de levendes land. Jeg tvivler ikke på, at han også takker dig meget."},
  [854] = {n="Rejsen til Korsvejen", l="Tal med Thork i Korsvejen i Ødemarken.", d="Jeg har forudset din ankomst, unge <Class>. Måske er du ikke så ung længere.\n\nJeg tror, det er på tide, at du bevæger dig dybere ind i dette land. Jeg kan mærke, at du er forudbestemt til store ting.\n\nDet er Korsvejen, du skal finde, for vores liv er blevet sammenflettet med orkernes, og de har brug for hjælp. Fortsæt ad denne vej mod øst, og følg den nordpå til Korsvejen. Find Thork inden for dens mure; han har Jordmoderens velsignelse.", c="Det er godt at se, at flere af vores <Race>-allierede er kommet for at hjælpe os fra så langt væk som Tordenskrænt. Igen, jeg byder dig velkommen."},
  [858] = {n="Tænding", l="Hent Tændingsnøglen og bring den til Snurrekrank.", d="Jeg går ud fra, at Sprudleventil sendte dig? Jeg er i klemme her. Jeg hoppede med uden at indse, at jeg skal bruge en nøgle for at låse makulatorens bevægelseskolonne op. En af de andre makulatoroperatører spurgte mig, om alt var i orden, og jeg fik panik! I stedet for at fortælle ham, at jeg manglede min nøgle, sagde jeg, at der var en form for mekanisk problem.\n\nVi må væk herfra på dobbelt hurtighed! Gå op til kontrolrummet øverst på boretårnet, supervisoren burde have en nøgle til denne makulator.\n\nHjælp mig lige her!", p="Hurtigt, vi må væk herfra, før nogen bliver mistænksomme!", c="Ja, det her ser ud til at være den rigtige nøgle. Lad mig lige sørge for, at jeg ved, hvordan den her ting virker...\n\nHmm... rotationskontrol... Den regulerer hastighed og stabilitet... fin armbevægelseskontrol. Se lige det her! Jeg kan ikke tro, at Ventureselskabet kunne konstruere noget så meget bedre end vores. Jeg må få det her tilbage til Skralleby!"},
  [860] = {n="Sergra Mørktorn", l="Tal med Sergra Mørktorn i Korsvejen.", d="Hvis du vil følge jægerens sti, så fører din rejse til Ødemarken. Dens dyr er stædige og vilde. Du vil lære meget ved at jage der, og din ånd vil vokse.\n\nTal med Sergra Mørktorn. Hun bliver din første guide i Ødemarken.\n\nSergra er i Korsvejen. For at nå hende skal du rejse øst fra Blodhov-landsbyen ind i Ødemarken, derefter nordpå, hvor vejen deler sig. Og vær forsigtig under rejsen - Ødemarken rummer stor fare for de uforberedte og uopmærksomme.", c="Du vil jage i Ødemarken?\n\nDine øjne er ivrige og unge. De er endnu ikke sammenknebne efter at have sporet dit bytte over denne lands tørre sletter.\n\nMen vær ikke bekymret. Vi vil hærde din krop og dit sind. Og vi vil lære dig, at der er mere ved jagt end at finde og dræbe dit bytte.\n\nGør dig klar. Din rejse begynder. Nu."},
  [861] = {n="Jægerens Vej", l="Bring 4 Slettesnigerklør til Melor Stenhov i Tordenskrænt.", d="Du er ivrig efter at udforske, det kan jeg se. Også jeg havde engang lysten til at vandre...\n\nVandre, og jage. For jagt er en taurens største ære.\n\nHvis du virkelig ønsker at følge jægerens veje, så kan Melor Stenhov vise dig stien. Han er i Tordenskrænt, på Jægerens Bakke.\n\nOg for at vise ham dine evner og din beslutsomhed, så bring ham klørne fra slettesnigerne i Mulgorr. De er seje og snedige - et passende bytte for en ung <Class> på jægerens sti.", p="Hilsner. Der er noget ved dig, som fortæller mig meget. Har vi forretninger, du og jeg?", c="Skorn Hvidsky er en klog taurens. Han har jaget i årevis, og selvom hans krop er gammel, brænder hans ånd stærkt. Vi er stolte af at have ham hos os.\n\nHvis Skorn sendte dig til mig, så må du også have jægerånden. Og at have samlet disse klør viser dine voksende færdigheder.\n\nMåske er du klar til at gå stien."},
  [864] = {n="Tilbage til Apoteker Zinge", l="Bring det forseglede marktestningssæt til Apoteker Zinge i Underbyen.", d="\"Her har du det, kraftkilden er sikkert fjernet, og dataene er bevaret. Nå, gode rejser og alt det der. Håber, at det onde videnskabelige eksperiment gik godt for dig og alt.\"\n\nKobolden vender sig væk fra dig for at tage sig af kravene fra Gadgetbyens Vandselskab. Du sikrer det forseglede testsæt til rejsen tilbage til Underbyen. Apoteker Zinge venter på dig og det forseglede marktestningssæt der.", p="Velkommen tilbage. I det mindste velkommen tilbage, hvis du er vendt tilbage med et forseglet testsæt. Ellers vil jeg lade som om, jeg ikke bemærker din fuldstændige inkompetence, og jeg skåner dig for min vrede, indtil du gør, som du har fået besked på, og udfører min opgave.", c="Jeg analyserer disse data med det samme. Måske viser Kivers vanvid sig at være min genialitet alligevel.\n\nMed hensyn til dig... du er nyttig for mig, og jeg belønner ganske godt dem, der forbliver nyttige. Tag denne genstand, denne mønt og, vigtigst af alt, min tak sammen med dem.\n\nTjek tilbage hos mig nu og da - jeg vædder på, at vores samarbejde om dette projekt ikke er slut."},
  [890] = {n="Den Savnede Forsendelse", l="Bring Gazlowes Regnskabsbog til Kajmester Svimlevig.", d="Jeg har ventet evigt på min sidste forsendelse af varer fra Bytteviken! Jeg er ret sikker på, at den må være blevet stjålet af Fribytterne, men for at være sikker, vil du så gå ned til kajen og spørge Svimlevig, om mine varer allerede er blevet lagt i mit lager uden min viden?\n\nHer, tag min regnskabsbog med ned til Svimlevig, og lad ham dobbelttjekke min beholdning mod hans logbøger.", p="Varer til at sende med næste skib, <Name>?", c="Nå, Gazlowe sendte dig, gjorde han? Et øjeblik, lad mig kigge her og tjekke mine egne logbøger og sikre mig, at jeg ikke fik Gazlowes forsendelse sendt til det forkerte sted.\n\nJeg vædder på, at han venter på de støvler fra Dryppek..."},
  [892] = {n="Den Savnede Forsendelse", l="Returner Gazlowes Regnskabsbog til Gazlowe i Skralleby.", d="Alt ser rent ud fra mine optegnelser, <Name>. Gå tilbage og fortæl Gazlowe, at han er uheldig. Jeg ville ikke blive overrasket, hvis det var piraterne, der snuppede hans varer.\n\nDer er ikke mere, jeg kan gøre for ham. Åh... men du kunne fortælle ham, at jeg har nogle ting fra Undergraven til ham, når han har tid til at komme og hente dem.", p="Nå, hvad sagde Svimlevig?", c="Ingen held, hva'? Jeg må gætte, at det så var Fribytterne... Svimlevig er på den rene, jeg er sikker på, at han ikke ville snyde mig sådan. Han er jo på lønningslisten.\n\nDet ser ud til, at jeg har nogle varer at hente tilbage, <Name>. Hvad siger du?"},
  [897] = {n="Høsteren", l="Bring Høsterens Hoved til Jorn Himmelspåer.", d="Dette mærkelige, insektlignende væsen ser ud, som om det står uden for den naturlige orden, som om det ikke hører hjemme i Ødemarken.", p="Du virker bekymret, <Name>. Hvordan går det med dine lektioner i Ødemarken? Har du fundet noget, der forstyrrer dig?", c="Jeg kan ikke sige noget om dette udyrs natur, for dets ånd er flygtet. Men som du gættede, hører det ikke hjemme i Ødemarken. Jeg frygter, at det kan varsle en dyster fremtid for vores folk...\n\nMen for nu, gør dig klar, og lad os håbe, at tiden afslører dette væsens mysterium."},
  [901] = {n="Samofonen", l="Hent konsolnøglen fra Bastler Snigles og brug den på kontrolkonsollen.", d="Når apparatet er deaktiveret, kan kontrolpanelet åbnes, og samofonen fjernes fra konsollen. Når alt andet er på plads, er det eneste tilbageværende at skaffe nøglen til at låse konsollen op.", p="Konsollens lys er dæmpet, og målerne og skiverne står alle på nul, alt er i tomgang.", c="Da nøglen drejes i låsen, låses kontrolkonsollen op. Et rødt lys øverst på konsollen slukkes, og al strøm løber ud af terminalen."},
  [908] = {n="Blandt Ruinerne", l="Bring Dybkernen til Je'neu Helligkrea ved Zoram'gar-forposten, Askedalen.", d="Tusmørkes Hammer har flyttet ind i Månehelligdoms-ruinerne i Den Sorte Afgrund. Deres tilstedeværelse kan kun tjene til at tvinge elementerne til at arbejde imod os. Hvis det ikke stoppes, vil denne region være deres for altid.\n\n<Name>, gå ind i Den Sorte Afgrund og find ruinens favnsten; den burde være et sted tæt på i vandet. I den er en dybkerne - en enhed, som når den læses korrekt, vil fortælle en historie om al elementar aktivitet. Hvis jeg har den, kan jeg og Jordringen måske gøre noget for at stoppe dem!", p="Har du haft held med at finde dybkernen? Uden den har vi ingen anelse om, hvad Tusmørkes Hammer egentlig har gang i dernede.", c="Det er præcis, hvad jeg har brug for! En dybkerne er en utrolig kilde til information, som vi vil kunne hente meget godt ud af. Uanset hvad Tusmørkes Hammer har gang i deroppe - og tro mig, når jeg siger, at det ikke er godt - vil mine kammerater og jeg nu afdække det.\n\nDu har klaret dig godt her i dag; Jordringen ser venligt på dig, fordi du hjalp os. Du har også hjulpet Horden som helhed, og for det burde du være stolt."},
  [909] = {n="Baron Akvanis", l="Bring den mærkelige vandkugle til Je'neu Helligkrea ved Zoram'gar-forposten, Askedalen.", d="Det besejrede vandelementar har efterladt en mærkelig vandkugle. Du regner ud, at genstanden på en eller anden måde gav udyret energi. Inde i kuglen sjasker en modbydelig udseende form af vand rundt. Selve kuglen virker upåvirket af enhver form for fysisk kraft.\n\nHvis nogen kan finde mening i denne genstand, er det Je'neu Helligkrea fra Jordringen. Han befinder sig på Hordens Zoram'gar-forpost i Askedalen.", p="Ah, hej igen <Name>. Jeg læste lige havets bølger, sådan som jeg altid gør. Hvad fører dig til forposten?", c="Dette... dette er et ganske fund, <Name>.\n\nDu fik det fra Baron Akvanis i Den Sorte Afgrund, siger du? Baron Akvanis har længe været anset for at være en fordærvet elementarkraft; denne kugle vil bevise, hvad der præcist fordærvede ham. Det ville ikke komme som nogen overraskelse, hvis det viser sig at være Tusmørkes Hammer, men vores studier vil også vise, hvordan de gjorde det.\n\nDu gjorde klogt i at bringe mig dette. Værsgo - tag det her, sammen med Jordringens varmeste hilsner."},
  [910] = {n="Nede ved Kajerne", l="Tag din vogter med til kajerne i Skralleby i Ødemarken.", d="Jeg har hørt historier om de mægtige skibe, der sejler mellem Skralleby og Bytteviken! Det må være så fedt at sejle på havet og kæmpe i mange store søslag. Måske bliver jeg en mægtig Horden-sømand, når jeg bliver stor! Ja!\n\nVil du tage mig med for at se kajerne i Skralleby, tak? Jeg lover, at jeg ikke går i vandet eller laver ballade - jeg vil bare se de store både og lugte det salte havvand! Ja!", p="Er vi der snart?", c="Wow, havet er ENORMT! Der var en masse mågerne og sådan noget - det er lige så støjende og travlt, som jeg troede. Der er også pirater i nærheden - så fedt!\n\nTak fordi du tog mig med til Skralleby, <Name>. Det var så fantastisk!"},
  [911] = {n="Porten til Grænsen", l="Tag din vogter med til Mor'shan-volden i den nordlige del af Ødemarken, lige før man går ind i Askedalen.", d="De siger, at Askedalen er den nye grænse, og at Mor'shan-volden i Ødemarken er porten til den. Det må være så fedt at være pioner og skære alt, man har brug for, ud af den utæmmede vildmark! De siger, at det er her, Horden og Alliancen kommer til at slås mest i fremtiden, og jeg vil være der, <Name>!\n\nVil du tage mig med til Mor'shan-volden, så jeg kan se, hvordan grænsen ser ud, tak? Jeg vil se, hvor Horden jager de stinkende nattealfer væk!", p="Er vi der snart?", c="Wow, Askedalen er der, hvor det virkelige eventyr sker! Har du nogensinde kæmpet i Askedalen, <Name>? Når jeg bliver en helt, når jeg bliver stor, vil jeg komme til Askedalen og kæmpe for Hordens herlighed!\n\nTak fordi du tog mig med til grænsen, <Name>. Du er den bedste!"},
  [912] = {n="Stenspliterens Trogg-forklædning"},
  [915] = {n="Du skriger, jeg skriger...", l="Hent noget jordbærisfløde til din vogter. Drengen forekommer at foretrække Tigule og Forørs mærke af is.", d="IS! Åh, vær nu sød, vær sød, vær sød, kunne du hente noget is til mig?! Jordbær er min yndlingssmag, og der findes ingen bedre jordbærisfløde i hele verden end Tigule og Forørs jordbærisfløde! Det er min yndlingsis i hele den vide verden!\n\nJeg fik den engang for længe siden, da jeg var på væddeløbsbanen i Skimrende Sletterne, men jeg hørte, at de måske sælger dem i byen nu! Vær sød? Pænt vær sød? Med Tigule og Forørs jordbærisfløde på toppen??!?!", p="Jeg ville ønske, de lavede flere smage is end jordbær, men jeg regner nok med, at jeg er heldig, at jordbær er min yndlingssmag!", c="Mmmmmmmm! Jeg elsker deres jordbærisfløde! Hvis der er én ting, Tigule og Forør ved at gøre, så er det at lave is!\n\nTusind tak, <Name> - dette er den bedste godbid nogensinde!"},
  [916] = {n="Vævskovgift", l="Bring 10 Vævskovgiftsække til Gilshalan Vindgænger i Aldrassil.", d="Jeg kom til Skyggedalen for at observere de vævskovedderkopper, der holder til i Skyggetrådshulen. De er i familie med en meget mindre art af edderkopper; jeg tror, at Verdenstræet har haft en dyb effekt på dem, og jeg vil gerne have prøver til at studere for at bekræfte det.\n\nFørst vil jeg gerne have noget af deres gift. Saml giftsækkene fra edderkopperne i og omkring Skyggetrådshulen, mod nord. Jeg kan så undersøge dem for ligheder med giften fra deres mindre slægtning.", p="Har du samlet giftsækkene, <Name>?", c="Tak, <Name>. Når jeg vender tilbage til Darnassos, vil jeg sammenligne giften i disse sække med giften fra andre edderkopper. Jeg tror, at den vil have egenskaber, der er knyttet til den nylige vækst af vores nye verdenstræ."},
  [917] = {n="Vævskovæg", l="Bring et Vævskovæg til Gilshalan i Aldrassil.", d="Nu hvor jeg har edderkoppernes gift, vil jeg gerne have nogle levende prøver at studere. Desværre er det mere, end jeg kan bede dig om, unge <Class>, at fange en levende, gigantisk edderkop. Og en gigantisk edderkop er mere, end jeg selv kunne klare!\n\nMen hvis du kan finde et uklækket æg, bliver det meget nemmere at levere prøver, og jeg kan så sørge for, at de uklækkede edderkopper bliver indespærret.\n\nDer må være et rede dybt inde i Skyggetrådshulen. Søg venligst efter et æg i reden og bring det tilbage til mig.", p="Har du været inde i Skyggetrådshulen, <Name>? Fandt du et edderkoppeæg?", c="Ah, meget godt. Jeg vil få dette æg og giften transporteret til Darnassos og så vende tilbage dertil, når mine studier her er færdige. Jeg forventer at finde ud af meget af disse prøver, <Name>. Du har været en stor hjælp for mig."},
  [918] = {n="Tømmerlingefrø", l="Bring 8 Tømmerlingefrø til Denalan ved Al'Ameth-søen.", d="Tømmerlingerne på Teldrasil er naturens elementarer. På nogle måder afspejler de den naturlige orden af planter og dyr på vores store træ.\n\nDerfor er det foruroligende at se, hvor vrede tømmerlingerne er blevet.\n\nJeg tror, det har noget at gøre med jorden. Jeg har arbejdet med forskellige metoder til at pleje planter, og jeg vil gerne prøve dem på tømmerlingefrø. Vil du være sød at samle frø fra tømmerlinger omkring Al'Ameth-søen og bringe dem til mig?", p="Har du frøene? Jeg er ivrig efter at plante dem.", c="Du fik dem. Det er godt!\n\nJeg vil plante disse frø i en speciel jord, som jeg har forberedt. Jeg tror, at frøene vil spire til tømmerlinger, der er meget mere fromme. Måske kan du senere se resultaterne!"},
  [919] = {n="Tømmerlingespirer", l="Bring 12 Tømmerlingespirer til Denalan ved Al'Ameth-søen.", d="Små tømmerlinger spirer omkring vandet ved Al'Ameth-søen. Jeg er bange for, at disse spirer er ude af hjælp - vi bør forsøge at fjerne dem fra landet, før de vokser sig store nok til at skabe problemer.\n\nNår du vandrer rundt ved søen, og du ser tømmerlingespirer, så tag dem venligst. Hjælp med at holde vores land rent!", p="Hej, <Name>. Har du fundet nogen spirer nær vandet?", c="Det er mange! Jeg er bange for, at de breder sig med en farlig hastighed. Jeg håber, at jeg kan løse gåden om, hvad der besmitter dem.\n\nTak for din hjælp, <Name>. Landet er et renere sted takket være din indsats."},
  [920] = {n="Tenarons Kaldelse", l="Tal med Tenaron Stormgreb øverst i Aldrassil i Skyggedalen.", d="<Name>, hedder du det? Jeg hørte, at Tenaron har spurgt efter dig. Du finder ham i det højeste rum øverst i Aldrassil.\n\nVi kan leve lange liv, men det er bedst, at du ikke lader ham vente for længe.", c="Ah, <Name>. Jeg havde håbet, at du ville være hurtig til at svare på min kaldelse. Jeg har en vigtig opgave, som jeg gerne vil have dig til at udføre."},
  [921] = {n="Jordens Krone", l="Fyld Krystalfiolen og bring den tilbage til Tenaron Stormgreb øverst i Aldrassil.", d="Det er tid for dig at drage ud for at søge din skæbne, <Name>. Men før du er klar til at drage ud i verden hinsides vores fortryllede skove, er der meget, du må lære om vores nylige historie.\n\nMeget har forandret sig for vores folk siden Kampen ved Hyjal-bjerget. Nordrassil ligger som en bleg skygge af det, det engang var, dets kraft brugt til at besejre Archimonde og drive den Brændende Legion tilbage...\n\nDer er en opgave, du må udføre. Gå til månebrønden nord for Aldrassil og bring mig en fiol med dens vand.", p="Månebrøndene rummer vandet fra Evighedens Brønd, den gamle kilde til magi, der har forvoldt så mange rædsler over vores verden.\n\nDruiderne udnytter dens egenskaber, og Vagterne ærer brøndene som helligdomme for Elune, men trolddom er forbudt for alle.", c="Så du har hørt den første del af efterspillet efter Kampen ved Hyjal-bjerget. Der er meget mere at fortælle, og den opgave, du har påbegyndt her, vil fortsætte gennem resten af din rejse gennem Teldrasil og ind i Darnassos."},
  [922] = {n="Rellian Grønspiir", l="Bring et Tømmerlingefrø til Rellian Grønspiir i Darnassos.", d="<Name>, kan du tage et af de frø, du bragte mig, hen til min ven Rellian Grønspiir? Han er druide i Darnassos, og da vi sidst talte sammen, afslørede han sin interesse for mit arbejde med tømmerlingerne. Han havde selv nogle ideer, og han vil sætte pris på et prøvefrø at arbejde med.\n\nTak, <Name>. Du har været en stor hjælp for mig. Jeg håber, at du en dag vil se frugten af mit arbejde.\n\nDu vil som regel finde Rellian gående ad stierne i Cenarion-enklaven i Darnassos.", p="Hej...\n\nOg hvordan kan jeg hjælpe dig?", c="Ah, et tømmerlingefrø? Jeg ville prøve at dyrke et af disse for at hjælpe Denalan med hans studier.\n\nMen jeg er bange for, at jeg har opdaget, at en korruption har bredt sig i mange af tømmerlingerne, og frø fra sådanne væsener bærer deres forælders besmittelse. De er uden for mine evner at reparere.\n\nDenalan er meget dygtig til ting, der vokser. Han kan måske finde en kur til fremtidige tømmerlinger. Han kan være deres eneste håb."},
  [925] = {n="Kærnes Hovaftryk", l="Rejs til Tordenskrænt for at hente Kærne Blodhovs hovaftryk til din vogter.", d="Man siger, at Kærne Blodhov er en af de største helte, Horden nogensinde har set. Når jeg bliver stor, vil jeg også gerne være en helt for Horden!\n\nKender du Kærne, <Name>? Kunne du gøre mig en tjeneste, tak? Kunne du hente hans hovaftryk til mig? Jeg aner ikke, hvordan jeg skal spørge ham, og han er nok for travl til nogen som mig... men du! Du er en eventyrer ligesom ham! Jeg vætter, at han nemt giver dig sit hovaftryk!\n\nVær sød?", p="Da orkerne var alene og uden venner, bød taurerne dem velkommen til et fremmed land og delte med dem uden at forlange noget til gengæld. Det er ære, <Name>.", c="WOW! Du fik Kærnes hovaftryk til mig! Mange tak! Og wow... han skrev en personlig besked her på - til mig! Jeg vidste, at han var fuldstændig sej, det vidste jeg bare! Måske takker jeg ham selv en dag... når jeg bliver en helt for Horden!\n\nDu er den bedste, <Name>. Tak fordi du har været så flink ved mig."},
  [927] = {n="Det Mosviklede Hjerte", l="Bring det Mosviklede Hjerte til Denalan ved Al'Ameth-søen.", d="Hjertet af Sortmos den Stinkende er dækket af et mørkt, oliefilmet mos. Faktisk er den eneste måde at se, at det er et hjerte, på dets langsomme, rytmiske slag... Et slag, der fortsat lyder, selv nu.\n\nMåske vil Denalan gerne se dette hjerte.", p="<Name>! Har du noget til mig?", c="...Hvad er det her? Et tømmerlingehjerte?? Det er dækket af et ækelt mos!\n\nTak for at bringe mig dette, <Name>. Jeg vil undersøge hjertet og, hvis lykken er med mig, bestemme arten af mosset omkring det."},
  [928] = {n="Jordens Krone", l="Bring det Delvist Fyldte Kar til Corithras Månevred i Dolanår.", d="Selvom der er mere, jeg kunne fortælle dig om månebrøndene og Teldrasil, må jeg sende dig af sted. Corithras Månevred venter på dig. Jeg har hældt den fiol med vand, du bragte mig, i dette kar for at bringe det til ham.\n\nSøg Corithras. Du finder ham ved månebrønden i Dolanår. Følg vejen sydpå fra Aldrassil ud af Skyggedalen, og fortsæt med at følge brostenene, når vejen drejer mod vest.\n\nHold dig dog på vejen, <Name>. Der er farlige bæster i skovene på det seneste.", p="Hilsen, <Class>. Hvad er grunden til, at jeg har fornøjelsen af dit besøg?", c="Ah, jeg forstår. Du blev sendt af Tenaron. Nå, så ser det ud til, at vi har meget at tale om, meget at gøre og lidt tid til at gøre det i.\n\nJeg tror, vi bedst går i gang."},
  [929] = {n="Jordens Krone", l="Fyld Jadefiolen og bring den tilbage til Corithras Månevred i Dolanår.", d="Først lad mig fortælle dig mere om den opgave, du skal løse. Druiderne i Darnassos bruger vandet fra månebrøndene i Teldrasil, og deres månebrønd må fyldes op fra tid til anden. Ved hjælp af disse specialfremstillede fioler kan du indsamle vandet fra månebrøndene.\n\nTag dette kar til månebrønden uden for Stjernebris-landsbyen mod øst, fyld det med noget af dets vand, og vend så tilbage til mig. Når du har fuldført din opgave, vil jeg fortsætte historien, hvor Tenaron slap den...", p="Hej igen, <Name>. Har du fuldført din opgave?", c="Efter Kampen ved Hyjal-bjerget var vi uden retning. Nordrassil røg af ilden, den udløste, og vores udødelighed - selve essensen af vores væsener! - var tabt.\n\nDet var i denne prøvende tid, at Forræderen blev befriet fra sit fængsel, og Shan'do Stormraseri forsvandt. En mørk tid for alle."},
  [930] = {n="Den Lysende Frugt", l="Bring den lysende frugt til Denalan ved Al'Ameth-søen.", d="Hængende under bladene af denne lysende plante hænger en stor, rund frugt.\n\nDenalan vil helt sikkert gerne studere denne frugt, er du sikker på.", p="<Name>, du ser ud, som om du har noget at fortælle mig. Har du nyheder om tømmerlingerne?", c="Du fandt denne på Teldrasil? Spændende... denne frugt er eksotisk. Måske er dens frø bragt hertil fra langt væk. Måske endda helt fra Azerot! Og der er noget ved denne frugt... det ser ud til at have reageret meget mærkeligt med Teldrasils jord.\n\nTak, <Name>. Nu må du undskylde mig, for jeg må studere dette nærmere..."},
  [932] = {n="Vrangt Had", l="Dræb Herre Melenas og bring hans hoved til Tallonkai Hurtigrod i Dolanår.", d="Jeg må advare dig, <Name>, denne sag må forblive mellem os. Satyrerne er allerede en tilstrækkelig skam for os, og denne er alt for tæt på hjemmet.\n\nHan hedder Herre Melenas. Han residerer i den nærliggende hule Ondsten, hvor han har samlet en stor flok grel-krigere. Hans hjerte er sort som natten, og han planlægger noget yderst ondt.\n\nDu skal finde ham i hans hule lige nord for her, og bringe mig hans hoved.", p="Har du dræbt Herre Melenas endnu? Det er vigtigt, at han bliver taget hånd om hurtigt og stille, <Name>. Hans fortsatte eksistens er en skam for os alle.", c="Med Herre Melenas hvilende kan jeg endelig gå videre til andre sager. Tak, <Name>."},
  [933] = {n="Jordens Krone", l="Fyld Turmalinfiolen og bring den tilbage til Corithras Månevred i Dolanår.", d="Der er en anden månebrønd sydøst for indgangen til Darnassos, på bredden af Arlithrien-pytterne. Vagterne har problemer med at patruljere området på grund af angreb og de voksende vredladne Knudefyr-pelsbjørne.\n\nVær på vagt, når du søger efter brønden, og hold dine våben tæt ved hånden.", p="I begyndelsen blev rapporterne om vanvittige pelsbolg-angreb afvist. Hvem kunne have tænkt, at de fredelige bjørnemænd ville vende sig til meningsløst raseri? Endnu et af de problemer, der plager os her i vores nye hjem.", c="Shan'do Stormraseri vendte aldrig tilbage, og druiderne var i uorden, og den dag i dag ved vi stadig ikke, hvad der blev af ham. Da Malfurjon var forsvundet, overtog Ærkedruide Fandrel Hjorthelm lederskabet af druiderne og overbeviste De Ældgamles Kreds i Mørkekysten om, at det var tid for vores folk at genopbygge, og at det var tid for vores folk at genvinde deres udødelighed.\n\nMed Kredsens godkendelse dyrkede Hjorthelm og de mest magtfulde druider Teldrasil, det nye Verdenstræ."},
  [934] = {n="Jordens Krone", l="Fyld Ametystfiolen og bring den tilbage til Corithras Månevred i Dolanår.", d="Alt var dog ikke godt med Teldrasil. Hjorthelms omhyggeligt udarbejdede planer for det nye Verdenstræ havde udfoldet sig, som han havde håbet, men der var ét lille problem, et problem som mange af Teldrasils vanskeligheder kan tilskrives.\n\nDet vil jeg dog ikke komme ind på endnu. Du må besøge den sidste månebrønd, mod nordvest i Orakellunden. Under grenene af Orakeltræet ligger den første og mest magtfulde af vores brønde. Hent en fiol med dens vand og vend tilbage til mig.", p="Sammen med druiderne har Orakeltræet og Ærkedruiden omhyggeligt overvåget Teldrasils vækst. Men selvom vi har et nyt hjem, er vores udødelige liv ikke blevet genoprettet.", c="At være i nærværelse af Orakeltræet... det er næsten, som om visdommen tager form. Lad mig fortsætte fortællingen...\n\nDa Teldrasil var vokset frem, nærmede Ærkedruiden sig dragerne for deres velsignelser, sådan som dragerne engang havde lagt over Nordrassil. Men Nozdormu, Tidens Herre, nægtede at give sin velsignelse og irettesatte druiden for hans arrogance. I enighed med Nozdormu nægtede også Alexstrasza at give Hjorthelm sin, og uden hendes velsignelse har Teldrasils vækst været fejlbehæftet og uforudsigelig..."},
  [936] = {n="Hjælp til Ærkedruide Runetotem", l="Tal med Ærkedruide Hamuul Runetotem i Tordenskrænt.", d="Undskyld mig <Class>, men jeg vil gerne have et øjebliks tid, hvis det er muligt.\n\nDen Cenarion-kredsen i Tordenskrænt er meget interesseret i erfarne eventyrere som dig, der kan yde dem hjælp i et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg fortælle dig, at ingen andre end Hamuul Runetotem står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte på Ældrehøjen inde i Tordenskrænt.", c="Hilsen, <Class>; jeg er glad for, at du er interesseret i at hjælpe vores forskning. Der er meget at gøre, og jeg ville gøre dig en bjørnetjeneste, hvis jeg fortalte dig, at arbejdet ikke er farligt. Forhåbentlig skræmmer dette dig ikke væk... men ud fra dit udseende går jeg ud fra, at fare er noget, du har mødt før."},
  [937] = {n="Den Fortryllede Lysning", l="Skaf 6 Blodfjerbælter og bring dem til Vagter Arynia Skysbrud i Orakellunden.", d="Jeg blev sendt hertil med en lille gruppe Vagter for at beskytte Orakeltræet mod harpyerne, der har bygget reder rundt om lysningen. Lidt efter lidt forsøger vi at skubbe dem tilbage.\n\nDa Orakeltræet forsøgte at sende en løber til Darnassos med en rapport, blev budbringeren angrebet og dræbt af en flok harpyer.\n\nHvis du føler dig klar til opgaven, så gå til deres reder, slå dem ihjel og bring mig deres bælter som bevis på dine gerninger.", p="Deres kløende klør og gennemborende næb kan vise sig at være en svær modstander for dine evner, <Name>, men jeg har tillid til, at du ikke vil fejle i denne opgave.", c="Jeg er imponeret over, hvad du har udrettet her på så kort tid, <Name>. Gid jeg kunne bede dig blive her og hjælpe mig med mine pligter... men jeg ved i mit hjerte, at større opgaver venter dig.\n\nJeg har bemærket, at Orakeltræet netop har tabt et stykke af sin bjæffe. Uden tvivl har det en opgave, det ønsker udført. Du bør tale med det."},
  [938] = {n="Tåge", l="Eskorter Tåge til Vagter Arynia Skysbrud ved månebrønden nær Orakeltræet.", d="Sabelkattens pels har en karakteristisk grå farve, som smelter sammen med den omgivende skov. Mens hun ligger der, ser du, at hun er hårdt såret, med dybe rifter over ryggen og maven.\n\nHun løfter hovedet og stirrer på dig, med klar intelligens i blå øjne. Hun ser ud til at ville følge dig.", p="Tåge... Det var min skyld! Hekserne overrumplede mig... Jeg burde aldrig have ladet dem tage dig...", c="Åh, tak, <Name>! Jeg var bange for, at jeg aldrig ville se Tåge igen, kun kendte hendes død i mit hjerte, aldrig at blive genforenet med min trofaste ledsager. Jeg skylder dig mere, end du kan vide, og du har min evige taknemmelighed."},
  [939] = {n="Xavariks Fløjte", l="Bring Xavariks Fløjte og 5 prøver af Jadeild-Ondbinding til Eridan Blåvind i det sydlige Ondskoven.", d="Du studerer den simple trææfløjte, du samlede op efter at have besejret Xavarik.\n\nDet knudrede træ føles solidt, men det synes, som om spiraler og mønstre i overfladen begynder at snurre og bevæge sig, når du vender den rundt i dine hænder. Pludselig mærker du en fornemmelse af rædsel...\n\nDu ryster på hovedet, sikker på at din hjerne driller dig.\n\nDet er muligt, at andre satyrer bærer spor om det, du har fundet. Bring dine fund til druiden Eridan Blåvind, som bor i det sydlige Ondskoven.", p="Hvad er det, <Class>? Du ser bekymret ud.", c="Jeg fornemmer de gamle væseners lidelse, <Name>...\n\nAt holde disse genstande er næsten uudholdeligt..."},
  [941] = {n="Plantning af Hjertet", l="Plant det Besmittede Hjerte i Denalans Planter.", d="Jeg har fjernet det ækle mos fra hjertet, men det er stadig besmittet...\n\nPrøv at lægge hjertet i min planter. Den er fyldt med en næringsrig jord, som måske kan rense og hele hjertet.", p="Denne planter er fyldt med jord, specielt fremstillet af Denalan.", c="Du lægger hjertet i planteren, og det graver sig hurtigt ned!\n\nEt par sekunder senere vrider det sig ud igen, renset. Det pulserer svagt... og kalder på dig om at tage det."},
  [944] = {n="Mesterens Hellebard", l="Saml information, brug derefter Spejlfiolen til at skabe en Spejlskål. Brug skålen til at tale med Unu.", d="Det er mærkeligt, at slangefolket er her, i Mørkekysten. Men endnu mærkeligere... er Tusmørkets Hammer. Den kult tilbeder de gamle, gamle jordens herrer. Herrer, der blev besejret for længe siden.\n\nMesterens Hellebard, mod syd, er et sted, hvor en sådan gammel herre faldt.\n\nGå derhen og led efter flere af Tusmørkets Hammer-kultisterne.\n\nTag denne spejlfiol. Brug den til at skabe en spejlskål, når du har søgt i Mesterens Hellebard. Tal derefter til mig gennem skålen.", p="Mesterens Hellebard, <Name>.\n\nGå derhen, og tal så med mig igen.", c="Tusmørkets Hammer er ved Mesterens Hellebard?\n\nUheldigt.\n\nDen gamle herre, der blev gennemboret af bladstaven, er længe død, men det betyder ikke, at splinter af hans magt ikke stadig findes.\n\nTusmørkets Hammer må være på jagt efter denne magt."},
  [949] = {n="Tusmørkelejren", l="Find et spor i Tusmørkets Hammers lejr ved Mesterens Glaive.", d="Tusmørkets Hammers formål ved Mesterens Glaive er ukendt. Men det må være mørkt.\n\nSøg igennem deres lejr ved Glaiven... Led efter noget, der kan fortælle os deres hensigter.\n\nFor vi må finde ud af deres hensigter, før en plan bliver lagt.", c="Denne bog er håndtrykt på et oldgammelt sprog og illustreret af en mesterkunstner."},
  [950] = {n="Vend tilbage til Unu", l="Bring Unu de fundne Sindssyge Kradserier.", d="At stirre ind i Tusmørkebogen er rasende frustrerende. Teksten begynder at flyde og danse efter blot et øjebliks blik, og engang så smukke snirkler vrider sig til groteske former.\n\nAt rive én side med sindssyge kradserier løs er alt, hvad der er muligt, før et svimmelhedsanfald overmander dig.", p="<Name>. Du er vendt tilbage.", c="Et kaotisk, primalt tryllekraft omgiver dette pergament med kradserier. Jeg kan fornemme de gamles værk i det.\n\nLad os håbe, det afslører Tusmørkets Hammers formål i Mørkekysten..."},
  [953] = {n="Amethands fald", l="Studér tavlerne, der fortæller om Amethand og dets fald, og vend derefter tilbage til Vagt Tysha Månesværd i Mørkekysten.", d="Mod øst finder du ruinerne af Amethand. Det er nu beboet af de rastløse ånder fra de Højfødte, der engang boede inden for dets mure, men engang var det et sted, hvor Azsyras tjenere frit udøvede deres kraftfulde magier.\n\nJeg blev sendt for at udforske ruinerne og fandt to store tavler, skrevet fulde af historierne om Amethand og dets fald. Mens jeg læste runerne, blev jeg angrebet af ånderne og flygtede.\n\nVær venlig, hvis du kan, og tag til ruinerne og tyd tavlerne i mit sted.", p="Når du har studeret tavlerne og lært om Amethands fald, vil jeg tage viden med til Auberdin og informere De Ældgamles Kreds.", c="Vi har få optegnelser fra tiden omkring De Ældgamles Krig, især nær ødelæggelsen af Evighedens Brønd. Givet det oprør og de katastrofale begivenheder, der fandt sted, er det ingen stor overraskelse.\n\nTak, <Name>. Med din hjælp er mit arbejde her færdigt, og jeg vil kunne levere en fuld rapport til Kredsen."},
  [957] = {n="Bashalhand", l="Ødelæg Oldtidens Månestensegl ved den oldtidens flamme i Amethand, og vend derefter tilbage til Stjerneion i Bashalhand.", d="Det var en af de mægtigste blandt de Højfødte, der fremstillede seglet, som dannede mit fængsel. I Amethand, ruinerne mod syd, der er tvillinger til disse, findes endnu i dag en oldtidens flamme, blå af farve. I denne flamme kan dette segl ødelægges.\n\nVær på vagt i ruinerne, <Name>...", p="Sandheden, <Name>, er at jeg er bange... Bange for at din ankomst--alt dette--blot er et hjernespind fra et forvirret sind. Kan du forstå, hvilken tortur dette er? Jeg... Vær venlig, du må gå hurtigt.", c="Jeg er fri, <Name>! Nu kan jeg se med mine egne øjne de forandringer, der er kommet over vores verden... Kun stykker og dele har jeg kendt. At tænke på, at da jeg sidst gik frit, stod Brønden endnu, og de Højfødte holdt hof hos Azsyra, vores elskede dronning.\n\nJeg fornemmer, at min fangevogter, min tidligere herre, Atrikus, stadig lever... Allerede nu vil mine følelser af håbløshed vige for tanker om hævn."},
  [964] = {n="Skeletfragmenter", l="Bring 15 Skeletfragmenter til Apoteker Tøvers i Bolværket, Vestlige Pestlandene.", d="Nøglen til Skolomance kaldes en Skeletnøgle. Den skal smedes af skelettets rester - faktisk flere - og hærdes af de stærkeste metaller i en passende form. Et kraftsegl fra et væsen, der naturligt kan åbne portalen til Skolomance, vil få nøglen til at virke i sidste ende.\n\nMen først og fremmest, <Name>. Vi skal bruge skeletfragmenter til smedningen af nøglen. Skeletter inde i Andorhøj burde give os det, vi skal bruge, men dem uden for murene kan måske også duge.", p="Dræb mange og dræb ofte, <Class> - vi skal bruge en god forsyning af passende skeletfragmenter til at lave nøglens ydre lag. De kalder den ikke en Skeletnøgle for ingenting, ved du.", c="Det her duer, <Name>! Nu er det min tur - jeg vil indgyde disse med et passende temperament, der lader dem overleve den intense smedeproces, de senere skal igennem.\n\nDet næste skridt bliver at skaffe en passende form til nøglen. Jeg kender en kobold-smed i Tanarisørknen, der tidligere har lavet former til lignende makabre genstande. Han arbejder for dem, kobolder plejer at arbejde for - den højest bydende."},
  [966] = {n="Althalaxx-tårnet", l="Saml 4 Slidte pergamenter til Balthule Skyggestød ved Althalaxx-tårnet.", d="En flok hexenmestre har slået sig ned omkring og inde i tårnet. Jeg ville have vendt tilbage til Auberdin for at rapportere til Elissa tidligere, men jeg var bange for at gå glip af noget, mens jeg var væk.\n\nDelgren mistænkte, at sådan et selskab måske samledes ved tårnet, men vidste ikke hvorfor.\n\nNogle få stumper pergament, som hexenmestrene bærer, er havnet i mine hænder, men jeg har brug for mere for at fuldende puslespillet. Jeg advarer dig dog mod at vove dig ind i tårnet, for hexenmestrene derinde er langt mere magtfulde!", p="Har du fundet flere af deres skrifter? Jeg burde kunne sætte et større billede af kulten sammen, hvis du kan finde dem.", c="Mange tak, <Name>. Det her burde kaste lys over hexenmestrenes samlinger...\n\nHm... Mørkestrandens Kult... Jeg har aldrig hørt om denne gruppe før. Uden kendskab til deres historie er det næsten umuligt at sige, hvad deres planer må være.\n\nDer er ikke mere tid til at vente. Advarslen skal leveres til Delgren med det samme."},
  [969] = {n="Held være med dig", l="Saml 10 frostslæggen-skår til Hekselæge Mo'ari i Evigblik.", d="Ah, det kan jeg se bare ved at kigge på dig -- du vil lave en lykkeamulet. Mo'ari ved altid!\n\nMod syd, der finder I en kløft, og kæmper har lavet massiv is. Kæmperne bærer dem nogle gange, men du kan altid samle skårene selv fra kløften. Disse skår har en kraftig reflekterende egenskab.\n\nBring 10 frostslæggen-skår tilbage, så bliver min lykkeamulet din.", p="Bring skårene tilbage, så fortæller jeg dig mere!", c="Ahh, ja... Jeg laver amuletten til dig nu. Bare vent!"},
  [974] = {n="At finde kilden", l="Krakle i Un'Gorokrateret vil have dig til at finde det varmeste område på Ildfjer-højderyggen.\n\nHver gang du finder et varmt sted, skal du højreklikke på termometeret for at tjekke temperaturen. Bliv ved med at lede, indtil du finder det varmeste.", d="De varme kilder her er et mysterium for mig. Hvor kommer varmen fra?\n\nNår jeg ser, hvor tæt pøllerne er på Ildfjer-højderyggen, undrer jeg mig virkelig over, om vulkanen har noget med det at gøre. Jeg har lavet et termometer til at tage målinger af temperaturerne ved vulkanen, og jeg vil gerne finde den varmeste del. Det giver målinger i grader Krakkenhed!\n\nVær så venlig, tag det, og tag målinger af temperaturerne på højderyggen, når du ser et varmt sted!", p="Jeg ville selv gå derhen, men... jeg er lidt bange for ildelementarerne der!", c="Ja, jeg ser helt bestemt sammenhængen her mellem vulkanens temperatur og de varme kilder. Jeg må dobbelttjekke mine ligninger for præcision, men det ser ud til, at afstanden og den hastighed, varmen overføres med... Hmm..."},
  [975] = {n="Mo'aris Lager", l="Tal med Hekselæge Mo'ari igen om et øjeblik for at modtage lykkeamuletten.", d="Nu, før jeg giver dig denne amulet, må jeg hellere forklare, hvordan du bruger den.\n\nHvis du bærer amuletten med dig, vil du opdage, at visse genstande falder fra skabninger, du kæmper mod. Hvis du ikke har amuletten med dig, finder du dem ikke. Forstået?\n\nDu vil kende disse særlige genstande på navnet -- de kaldes Ekko. Hvis du finder nogen af disse genstande, skal du bare bringe dem til gamle Mo'ari, og hun hjælper dig.\n\nVent her, mens jeg reparerer din amulet.", c="Her er den, <Name>. Husk, du skal have den på dig. Hvorfor tager du ikke tilbage ud i vildmarken og ser, hvad du finder der?"},
  [977] = {n="Er vi der snart, yeti?", l="Saml 2 Upåklagelige yetihorn til Umi Rumpleknaser i Evigblik.", d="Nu hvor jeg har det, jeg skal bruge til at dække de mekaniske bevægelige dele, mangler jeg kun én ting. Nå, faktisk to. To horn!\n\nIsdistel-patriarkerne og -matriarkerne har de største horn, så selvfølgelig er det dem, jeg vil have. Den type yeti holder til i en hule mod sydøst. Der er masser af dem derinde; du burde ikke have problemer med at finde dem.\n\nHusk, jeg vil kun have de bedst udseende -- ingen slidte eller knækkede horn, tak!", p="Jeg er næsten færdig med at sætte pelsen på, <Name>. Vær venlig at skynde dig tilbage med de horn!", c="Jeg kan ikke vente med at vise mine venner! Vent lige et øjeblik, mens jeg sætter disse på...\n\nPerfekt!"},
  [978] = {n="Månerørt Vildkin", l="Saml 10 Månerørte fjer fra Vintervåren, og vend derefter tilbage til Erelas Ravhimmel i Rutteran-landsbyen.", d="Vildkin-fjer fra Bagland ser ud til at indeholde spor af magiske egenskaber. Disse kræfter... de ser ikke ud til at blive brugt af væsnerne, det er snarere, som om de simpelthen er iboende for arten -- en del af deres selve essens.\n\nUnder mine studier hørte jeg, at en stor bestand af vildkin lever i de snedækkede lande i Vintervåren. Kunne disse væsener have de samme kræfter? Hjælp mig venligst med at finde et svar, <Name>. Tag til Vintervåren og saml fjer, der er faldet til jorden, og vend derefter tilbage til mig.", p="Hvor kunne disse kræfter stamme fra? Jeg tror, vi er på rette spor for at finde svaret, <Name>.", c="Nu kan jeg sammenligne fjerene... Lad os se..."},
  [979] = {n="Find Ranshalda", l="Find Ranshalda i det østlige Vintervåren.", d="Ja, ja, disse fjer ser ud til at rumme den samme magiske fortryllelse, som jeg bemærkede tidligere... Selvom jeg ikke er sikker på, hvad vi måske finder, opfordrer jeg dig til at fortsætte med at lede efter svar, <Name>.\n\nEn kollega af mig rejste for nylig ind i Vintervåren for at observere vildkinen der i deres eget habitat. Hvorfor tager du ikke og indhenter hende og ser, hvad hun har fundet?", c="Hej! Erelas sendte dig? Fantastisk, jeg var lige ved at gøre mig klar til at rejse op til hulerne nu, og jeg ville ikke have noget imod selskab."},
  [980] = {n="De nye kilder", l="Rejs til Vintervåren og tal med Donova Snedal.", d="Nu har jeg hørt om andre varme kilder på et sted kaldet Vintervåren, langt mod nord herfra. Det mærkelige er, at der ingen vulkaner er i nærheden af dem. Interessant, ved jeg.\n\nNu, hvis du vil finde ud af mere, skal du tage til Vintervåren og tale med en ven af mig. Hendes navn er Donova Snedal, og hun opholder sig i øjeblikket ved de varme kilder der.\n\nTak igen for at hjælpe mig med mit termometer! Vi ses senere!", c="Hej der, <Name>. Ja, det Krakle fortalte dig, er sandt..."},
  [981] = {n="Althalaxx-tårnet", l="Tal med Delgren Renseren ved Maestras Post.", d="For alt det arbejde, du har udført, fortjener du at blive godt belønnet. Vend tilbage til Delgren og fortæl ham, at Atrikus Narasin ligger stille af din hånd, og at Mørkestrandens Kult er slået og spredt.", c="Jeg vidste, du ville være til opgaven, <Name>.\n\nJeg fornemmer store gerninger foran dig, og at du vil rette mange af de uretfærdigheder, der plager vores lande. Bær mine velsignelser, <Name>, samt denne gave."},
  [992] = {n="Gadgetbyens Vandundersøgelse", l="Brug den uanboret vandrutnings-tingest ved vandpølen ved Sandsorg-vagten. Når du har indsamlet prøven, skal du returnere den anborede vandrutnings-tingest til Senior-landmåler Snurrebrus i Gadgetbyen.", d="Vi har en ledig stilling som midlertidig junior-landmåler i Gadgetbyens Vandselskab, hvis du er interesseret!\n\nNu hvor nomaderne har beslaglagt alle vores brønde, må vi udnytte flere frie vandkilder! Der er vand at hente i ørkenen, men kun for dem, der er smarte nok til at undersøge dem først.\n\nTag denne vandrutnings-tingest og bor en prøve af vandet ved vandpølen nær Sandsorg-vagten. Den er lige i synsvidde for trolderne derovre. Bring den anborede tingest tilbage til mig, når du er færdig!", p="Velkommen tilbage, Junior-landmåler <Name>! Har du gennemført din opgave endnu?", c="Hvad er det her? Du blev overfaldet af en slags ond magi-krybdyr? Åh, det lover ikke godt for Gadgetbyens Vandselskab, nej da...\n\nJeg burde nok have fortalt dig om rapporterne om nogle skøre bille-væsner, der ser ud til at suge alt vandet op i ørkenen. Først troede jeg, det bare var noget sludder. Vi har nok problemer med nomaderne, som det er; jeg troede, det bare var endnu et af deres kneb. Nå, nu ved vi i det mindste besked!"},
  [994] = {n="Flugt med kraft", l="Beskyt Volcor, indtil I når vejen, og tal derefter med Terenthis i Auberdin.", d="Fint, <Name>, kraft er det så. Lad os komme væk herfra, så snart du er klar. Vi kæmper os vej ned til vejen -- Grimklo burde stadig være der. Når vi er der, kan vi skilles.\n\nTerenthis vil gerne høre din version af historien med det samme, så tag til Auberdin, når vi er kommet ud herfra.", c="<Name>! Jeg er glad for at se, at du er vendt tilbage i god behold. Din hjælp til Volcor har givet mig tro på, at vi kan overvinde de udfordringer, der venter os her i Mørkekysten og videre."},
  [995] = {n="Flugt ved snig", l="Flygt fra pelsbolgens hule og mød Terenthis i Auberdin.", d="Fint så... hvis du er sikker, sniger vi os ud herfra. Lad os forlade stedet, når du er klar.\n\nHusk, når du er flygtet, skal du mødes med Terenthis tilbage i Auberdin. Jeg tager derhen alene, da jeg nok bevæger mig hurtigere end dig.", p="Ja, <Name>?", c="<Name>! Jeg er glad for at se, at du er vendt tilbage i god behold. Din hjælp til Volcor har givet mig tro på, at vi kan overvinde de udfordringer, der venter os her i Mørkekysten og videre."},
  [997] = {n="Denalans jord", l="Bring pakken med Sjælden Jord til Denalan ved Al'Ameth-søen.", d="Er du på vej mod syd? Til Al'Ameth-søen? Hvis ja, har jeg en opgave, jeg måske vil bede dig om...\n\nMin kollega Denalan har en lejr langs søens østlige ende, hvor han studerer og eksperimenterer med plantelivet på Teldrassil. Han bad om en pakke sjældne jordarter fra Darnassos, og den var forsinket og ankom først for nylig her til Dolanår.\n\nKan du tage pakken med til ham?", p="Har du noget til mig?", c="Ah, den er her! Jeg har ventet på denne sjældne jord i ganske lang tid. Jeg håber, den stadig er frisk...\n\nTak fordi du bragte den til mig, <Name>. Du er en <Race>, der er generøs med sin tid."},
  [1000] = {n="Den Nye Grænse", l="Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger raske individer til at hjælpe dem med at udforske Kalimdørs vidtstrakte nye grænser! En forbudt ødemark med ubeskrivelige farer ligger langt mod vest for Tanarisørknen og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt for mere information!", c="Hilsner, <Class>.\n\nJeg er glad for at se folk som dig interessere sig for naturens velfærd; historierne om dine mægtige bedrifter er kommet forud for dig, og du er velkommen her. At se dig stå foran mig giver mig tillid til, at Cenarion-kredsen vil få den rette hjælp, den har brug for.\n\nVores forbindelse til Cenarion-kredsen i Månelunden overskrider racemæssige og politiske skel. Husk dette, når du arbejder på kredsens vegne, så klarer du dig godt."},
  [1003] = {n="Summekasse 525", l="Saml 4 Gråhårede skalpe fra Gråhårede tidselbjørne syd for Auberdin, og læg dem i Summekasse 525.", d="Over de kogende lyde og dryppende lyde fra maskinen hører du Tryllebangs vaklende stemme råbe.\n\n\"Næsht onesh langt sydpå nede ad vejen. Burde ikke være svært at finde... bare ude til sjiden... ved et hegn. Jeg tror, jeg gemte den i nogle busshesh... Busshesh. Hehehe... Jasj, Summekasse 525 tager gråhårede skalpe fra de der gråhårede tidselbjørne. Dreng, det er en mundfuld. Gråhårede... Hehehe...\"\n\nDu hører flere sluk-lyde, mens maskinen går i stå. Så, pludselig, spræller den tilbage til live.\n\n\"4!\"", p="Du hører sang fra Summekasse 525.\n\n\"Selv om krybervin er sødt, og tærskerøl er fint, og månesnigermåneskin er storslået. Der er intet så kært som en tidselbjørne-øl, og jeg skal snart have noget ved hånden!\"\n\nLågen er åben og venter på de 4 gråhårede skalpe, mens du hører sangen gentaget igen og igen.", c="\"Så jasj, har du fået skalpene med? Det er sjå godt... Hva'? Nå, ja, jeg går ud fra, du har regnet ud, at jeg kan snakke med dig uden materialerne i maskinen. Men jeg sagde sandheden, da jeg sagde, de var ødelagte!\n\nSe, ud over at være kommunimationsværktøjer, brygger og destillerer Summekasserne også fin spiritus. Undskyld for enhver vildledning, men nattealferne værdsætter ikke min spiritushandel i deres byer. Jeg har lagt noget specielt i denne kasse for at vise min taknemmelighed for din indsats. Nyd det!\""},
  [1004] = {n="Den Nye Grænse", l="Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger raske individer til at hjælpe dem med at udforske Kalimdørs vidtstrakte nye grænser! En forbudt ødemark med ubeskrivelige farer ligger langt mod vest for Tanarisørknen og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt for mere information!", c="Hilsner, <Class>.\n\nJeg er glad for at se folk som dig interessere sig for naturens velfærd; historierne om dine mægtige bedrifter er kommet forud for dig, og du er velkommen her. At se dig stå foran mig giver mig tillid til, at Cenarion-kredsen vil få den rette hjælp, den har brug for.\n\nVores forbindelse til Cenarion-kredsen i Månelunden overskrider racemæssige og politiske skel. Husk dette, når du arbejder på kredsens vegne, så klarer du dig godt."},
  [1007] = {n="Oldtidens Statuette", l="Bring Oldtidens Statuette til Talen, i hans lejr nær Zoram-strandet.", d="Jeg ville give dig en opgave, <Name>.\n\nJeg var på mit lille fartøj og skimtede over de nedsænkede ruiner af Zoram, da naga angreb mig, de væltede op af vandet og rev i mig med deres kløer! Jeg flygtede og bar de forsyninger, jeg kunne, for at bygge denne magre lejr.\n\nMen da jeg nåede kysten og løb... var min dyrebareste ejendel tabt.\n\nVær venlig, <Name>, find stedet for mit baghold, langs kysten mod nord, og led efter en oldtidens statuette. Det er grunden til, at jeg har trodset farerne på Zoram-strandet.", p="Har du fundet statuetten, <Name>?", c="Du fandt den! Tak, <Name>!\n\nDen gamle by Zoram gemmer på mange hemmeligheder, og denne statuette kan være nøglen til mange af dem."},
  [1015] = {n="Den Nye Grænse", l="Tal med Ærkedruide Fandrel Hjorthelm ved Cenarion-enklaven i Darnassos om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger raske individer til at hjælpe dem med at udforske Kalimdørs vidtstrakte nye grænser! En forbudt ødemark med ubeskrivelige farer ligger langt mod vest for Tanarisørknen og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruiden i Darnassos, Fandrel Hjorthelm, for mere information!", c="Hvad får dig til at tro, at jeg ønsker at blive plaget af folk som dig, <Class>? Vent - lad mig stoppe de vigtige pligter, jeg varetager dagligt, så jeg kan hjælpe dig med at finde en tingest et sted. Naturligvis bør Darnassos' velfærd - nej, hele Teldrassils - komme før anskaffelsen af en lille pynteting til din samling.\n\nNarrene i Månelunden spilder min tid med deres opråb om hjælp, og nu må jeg tåle dette?"},
  [1018] = {n="Den Nye Grænse", l="Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger raske individer til at hjælpe dem med at udforske Kalimdørs vidtstrakte nye grænser! En forbudt ødemark med ubeskrivelige farer ligger langt mod vest for Tanarisørknen og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruide Hamuul Runetotem på Ældrehøjen i Tordenskrænt for mere information!", c="Hilsner, <Class>.\n\nJeg er glad for at se folk som dig interessere sig for naturens velfærd; historierne om dine mægtige bedrifter er kommet forud for dig, og du er velkommen her. At se dig stå foran mig giver mig tillid til, at Cenarion-kredsen vil få den rette hjælp, den har brug for.\n\nVores forbindelse til Cenarion-kredsen i Månelunden overskrider racemæssige og politiske skel. Husk dette, når du arbejder på kredsens vegne, så klarer du dig godt."},
  [1019] = {n="Den Nye Grænse", l="Tal med Ærkedruide Fandrel Hjorthelm ved Cenarion-enklaven i Darnassos om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger raske individer til at hjælpe dem med at udforske Kalimdørs vidtstrakte nye grænser! En forbudt ødemark med ubeskrivelige farer ligger langt mod vest for Tanarisørknen og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruiden i Darnassos, Fandrel Hjorthelm, for mere information!", c="Hvad får dig til at tro, at jeg ønsker at blive plaget af folk som dig, <Class>? Vent - lad mig stoppe de vigtige pligter, jeg varetager dagligt, så jeg kan hjælpe dig med at finde en tingest et sted. Naturligvis bør Darnassos' velfærd - nej, hele Teldrassils - komme før anskaffelsen af en lille pynteting til din samling.\n\nNarrene i Månelunden spilder min tid med deres opråb om hjælp, og nu må jeg tåle dette?"},
  [1021] = {n="Onde Satyr! Dryader i Fare!", l="Find Anilia i Xavjan.", d="Hør her, jeg ved ikke, hvem du er, men jeg har brug for din hjælp. Mine søstre gik for at tage Cenarus' Gren tilbage fra satyren. De sagde, de snart ville være tilbage, men det er to hele dage siden!\n\n<Name>, du skal finde dem! De ledte efter ruinerne af et nattenisse-tempel i Xavjan mod nordøst. Jeg ved ikke, hvad jeg skal tro. Led efter Anilia, hun førte dem på jagt.", c="Ud fra det gabende sår i hendes side at dømme, er Anilia lige ved at dø."},
  [1022] = {n="Den Hylende Dal", l="Gå til Den Hylende Dal og studer Mel'Tandrås' Bog, og vend derefter tilbage til Vagt Melyra Frostskygge ved Aesinas Helligdom.", d="Selvom vi har brugt mange ressourcer og megen indsats på at drive de resterende dæmoner fra Ondskoven mod nord, har vores succeser været få. Vi har kunnet holde en stor del af den dæmoniske tilstedeværelse væk fra Askedalen.\n\nMod nord, nær grænsen til Ondskoven, er den ruinerede helligdom for Mel'Tandrås blevet overtaget af mystiske ulvemænd. Deres gysende hyl har fået området til at blive kendt som Den Hylende Dal. Bogen om Mel'Tandrås, som opbevares i helligdommen, kan måske kaste lys over, hvorfor disse ulvemænd er kommet.", p="Helligdommens bog er en mystisk genstand. Den er ikke en bog i traditionel forstand. Bladene i bogen blev velsignet af Mel'Tandrås selv, og den optegner begivenheder af betydning på sine sider.\n\nDet er svært for mig at forklare. Hvis du tager til helligdommen, vil du forstå det.", c="Mel'Tandrås' Bog virker på mærkelige måder. De begivenheder den optegner, de begivenheder den viser... Ingen forstår egentlig, hvorfor den gør, som den gør.\n\nIkke desto mindre er det tydeligt, at det, Præstinde Stjernesang modtog--denne Elunies Le--fortjener yderligere undersøgelse."},
  [1031] = {n="Cenarus' Gren", l="Dræb Geltharis og bring Cenarus' Gren tilbage til Ilijana ved Aesinas Helligdom.", d="Anilia lægger hænderne på dine skuldre og trækker dig tæt til sig. Gispende peger hun mod buen mod nord, før hendes øjne lukker sig, og hendes sidste hvæsende åndedræt forlader kroppen. \"Han har taget den... Gelthåris...\" Du ved i dit hjerte, at Anilias døende ønske er at se Cenarus' Gren vende tilbage til dryadernes hænder.", p="Har du fundet dem? Hvad sagde Anilia? Hvor er hun?", c="Anilia døde? Nej... det kan ikke passe! Det var først i går, at vi løb og legede sammen i skoven.\n\nJeg regner med, at de dage er forbi..."},
  [1036] = {n="Hold op, din Slyngel", l="Tal med Flådemester Ildallon om bord på Karmosinrød Dal ud for kysten af Kvælertorn-dalen.", d="<Name>... ja, jeg har hørt om dig. Jeg har hørt, at du ikke er nogen ven af Bytteviken - ligesom os Blodsejl-fribytterne. Flådemester Ildallon leder efter robuste og raske mænd som dig til en særlig opgave.\n\nHvis du er interesseret, så tag ud til Karmosinrødt Slør og tal med ham nede under dækket. Hun ligger for anker ud for Den Vilde Kyst øst herfra, ved siden af Modstrøm og Jomfruens Held.", c="Hold op, din slyngel. Jeg hører, at du er den type, der godt kan lide lidt snedigt bedrageri. Nå, hvis du ikke er nogen ven af Bytteviken, så har du måske en særlig plads hos Blodsejl-fribytterne.\n\nArrrrr..."},
  [1037] = {n="Velinde Stjernesang", l="Tal med Thyn'tel Klingevæver på Krigerens Terrasse i Darnassos.", d="Velinde Stjernesang var min forgænger her i Askedalen. Først så det ud til, at hun havde situationen i Ondskoven under kontrol, men lidt efter lidt svigtede hendes indsats. En dag forsvandt hun simpelthen.\n\nJeg blev sendt hertil for at fortsætte hendes arbejde. Jeg er bange for, at jeg ikke ved noget om præstinden. Måske ved Thyn'tel Klingevæver, en af Vagternes kommandører, mere om detaljerne i hendes forsvinden, end jeg har været involveret i.\n\nHun vil helt sikkert forstå vigtigheden af sådanne oplysninger.", c="Velinde Stjernesang? At præstinden forsvandt for et stykke tid siden, er næsten helt sikkert almen viden. Hvad angår yderligere detaljer om begivenhederne omkring hendes afrejse... så ville der skulle være en god grund for mig til at videregive sådanne oplysninger."},
  [1039] = {n="Ødemarkens Havn", l="Tal med Havnemester Svimsnurr i Knirk.", d="Knirk er den eneste havn i Ødemarken. Velinde har højst sandsynligt fundet et handelsskib i Knirk, der tog hende til Sortvandsbugten i Azerot. Vi har haft begrænsede forbindelser med kobolderne, der driver havnen, men havnefogeden burde have oplysninger om kommen og gåen for skibspassagererne.\n\nFølg vejen mod sydøst gennem Askedalen, så kommer du til Ødemarken. Pas på, hvor du træder, <Name>, krigere af Horden patruljerer landet. Du vil dog være i sikkerhed i havnen.", c="<Race>, hva'? Må indrømme, vi ser ikke mange af din slags herude. Leder du efter nogen, hva'? Giv mig lige et øjeblik, jeg er sikker på, at jeg har det skrevet i en af mine protokoller.\n\nDer er mange, der rejser igennem her, så giv mig bare lige et øjeblik."},
  [1040] = {n="Passagen til Bytteviken", l="Tag en båd til Bytteviken og tal med Karavanefører Ruzgot.", d="Ah ja, endelig fundet den. Burde have fortalt mig, at hun var her for så længe siden. Lad os se.\n\nVelinde. Booket passage til Bytteviken med Sort Fiskeørn. Jeg har intet her, der siger noget andet, så jeg må antage, at den kom sikkert i havn.\n\nJeg kan ikke hjælpe dig meget mere, men hun spurgte om landrejser over på den side af verden, og jeg nævnte Ruzgot, en karavanefører baseret i Bytteviken. Måske har denne Velinde rejst med ham.\n\nSå, flyt dig nu. Jeg har ikke hele dagen til dig.", c="Ja? Nu ser det ikke ud til, at du er den type med varer, der skal fragtes, så enten leder du efter et job med min karavane--og der er ingen job at få nu--eller også taler du sandsynligvis med den forkerte kobold.\n\nSå hvilken er det?"},
  [1041] = {n="Karavanevejen", l="Tal med Skriver Daltry i Mørkeshire.", d="Det viser sig, at jeg tog fejl af dig, og det sker ikke hver dag.\n\nDet passer lige til, at jeg husker den Velinde, du leder efter. Det er ikke hver dag, at en nattenisse-præstinde ønsker at rejse med en beskidt gammel--men god til dine fragtbehov!--karavane som min egen.\n\nVi delte os på vejen nordpå; hun var på vej mod Mørkeshire. Skriveren dér fører alle slags protokoller. Måske kan der være noget nyttigt.\n\nVær forsigtig i junglen, den er et dødbringende sted, selv på de bedste tider.", c="Med alle de mærkelige hændelser de sidste par år fører jeg så gode optegnelser over fremmede, som jeg kan. Man ved aldrig, hvornår de kan komme til nytte... selvom det som regel ikke er behageligt, når de gør. Jeg vil ikke antyde noget om denne Velinde, du leder efter."},
  [1042] = {n="Carevin-familien", l="Tal med Jonatan Carevin i Mørkeshire.", d="Nej, jeg har ingen optegnelser om, at Velinde Stjernesang har boet i Mørkeshire... selvom jeg, hvis du ikke har noget imod, at jeg siger det, næppe kan forestille mig en nattenisse-præstinde, der tager et værelse på kroen, hvis du forstår, hvad jeg mener?\n\nDisse ulvemænd, du nævnte, det er dog noget, jeg har hørt om. Netop den anden dag kom Kalor til byen med en snor af deres hoveder. Han arbejder for Carevin-familien. Jægere af dæmoner, udøde og andre rædsler. Tal med Jonatan, han er husets overhoved.", c="Mørke tider er det. Dårlige nyheder hviskes fra hver svajende gren, og ondskab kan findes under hver sten.\n\nOg i sådanne tider træder en ukendt fremmed ind i mit hjem og spørger om varulve... Jeg vil ikke bede om tilgivelse for min mistanke, kun svar.\n\nOg svar, dem vil jeg have."},
  [1043] = {n="Elunies Le", l="Led efter tegn på Elunies Le, og vend derefter tilbage til Jonatan Carevin i Mørkeshire.", d="Din historie lyder sand... Jeg forstår ikke helt dine motiver, men hvis din forretning her i Skumringsskoven indebærer at rydde skoven for et hvilket som helst antal varulve, så kan jeg se bort fra forståelsen til fordel for resultaterne.\n\nDer er en mine mod syd, som er blevet overrendt af varulve... De dukkede op ud af den blå luft, men fra det, vi ved, er det dér, de først blev fundet.\n\nFortsæt din færd, men jeg vil bede dig om, at hvis du finder noget af betydning, så del det med mig. Vi tager imod enhver hjælp i vores krig mod det onde.", p="Skovene er farlige for de uforberedte. Hold dine våben tæt ved hånden og dit hoved endnu tættere, ellers kan din næste rejse ind i den hjemsøgte skov blive din sidste.", c="Det er en interessant historie, du fortæller, <Name>. Selvom Carevin-familiens indflydelse ikke er stor nok til, at vi kan finde roden til disse problemer og gøre ende på dem én gang for alle, vil vi gøre, hvad vi kan, for at inddæmme varulvenes antal i Skumringsskoven.\n\nJeg har allerede instrueret Kalor om at gøre dette til hans første prioritet."},
  [1044] = {n="Besvarede Spørgsmål", l="Vend tilbage til Thyn'tel Klingevæver i Darnassos.", d="Vi skal nok tæmme varulveproblemet, vær ikke bekymret for det. Den ondskab, din ven førte ind i vores skove, vil blive inddæmmet, og jeg bærer hende ingen ondt for hendes handlinger. Mærkelige begivenheder er på færde i disse tider, <Name>, og mørket kender ingen hvile.\n\nJeg vil ikke holde dig længere. Jeg formoder, at der er andre, der bør høre om det, du har fundet i minerne i Skumringsskoven.", c="Så det er Velindes skæbne, er det? Den høje præstinde vil blive skuffet over at høre dette, de var gode venner før hendes forsvinden. Alligevel må Elunies Le være blevet givet hende som en gunst af vores gudinde, og det er foruroligende for mig, at den er faldet ud af hendes tjeneres hænder.\n\nEn anden sag til en anden tid dog. Jeg skylder dig en stor tak for det, du har udrettet."},
  [1046] = {n="Raenes Renselse", l="Bring Ran Blodtands kranie og Dartels Forvandlingsstav til Raene Ulvelober i Stjernelund.", d="Vend tilbage til din egen stamme og fortæl dem om din sejr her.\n\nVis dem din trofæ, og bad dig i æren...", p="Vagterne gør, hvad de kan her i Askedalen, men det er takket være <Race>s som dig, at vi har vundet den grund, vi har.", c="Så, dette er kraniet fra den mest frygtindgydende pelsbolg-trussel i Askedalen?\n\nJeg er mere end tilfreds med dine evner, <Name>. Vagterne kan ikke takke dig nok. Jeg håber, at vi kan regne med dig igen i fremtiden, når du skal hjælpe vores folk.\n\nJeg vil sætte dette kranie og Dartels Stav et sted med ærbødighed, så andre kan se dem.\n\nTeronis ville være stolt. Tak igen."},
  [1047] = {n="Den Nye Grænse", l="Tal med Ærkedruide Fandrel Hjorthelm i Cenarion-enklaven i Darnassos om Cenarion-kredsens opfordring til at udforske Kalimdørs grænser.", d="Opmærksomhed, helte!\n\nCenarion-kredsen søger kropsligt dygtige personer til at hjælpe dem med at udforske Kalimdørs enorme nye grænser! Et forbudt ødeland fuld af usigelige farer ligger langt mod vest for Tanarhis og Gadgetbyen, og kredsen har brug for villige og ærefulde stedfortrædere til at handle på deres vegne.\n\nAlle interesserede personer bør søge audiens hos Cenarion-kredsen. Tal med Ærkedruiden i Darnassos, Fandrel Hjorthelm, for mere information!", c="Hvad får dig til at tro, at jeg ønsker at blive plaget af din slags, <Class>? Vent - lad mig stoppe de vigtige pligter, jeg varetager dagligt, så jeg kan hjælpe dig med at finde en eller anden prylesag. Under alle omstændigheder skal Darnassos' velfærd - nej, hele Teldrasils - komme i anden række i forhold til anskaffelsen af en lille fidus til din samling.\n\nDe tossede i Månelunden spilder min tid med deres bønner om hjælp, og nu skal jeg finde mig i det her?"},
  [1048] = {n="Ind i Skarlagen-klosteret", l="Dræb Over-Inkvisitor Hvidmane, Skarlagen-kommandør Mørkrøn, Herod, Skarlagen-mesteren og Hundemester Loksøj, og rapportér derefter tilbage til Varimathras i Underbyen.", d="Mens Den Mørke Dame tager sig af det presserende spørgsmål om Liskekongens fremrykning mod nord, sørger jeg for, at sagerne tættere på hjemmet bliver passet, som de bør.\n\nUden tvivl er de menneskelige skadedyr, der kalder sig Skarlagen-korstoget, den skarpeste torn i vores side herhjemme. Tirisfal-engene vrimler bogstaveligt talt med de små røde myrer.\n\nRejs til klosteret, <Class>, og læg alt øde under over-inkvisitor Hvidmane og hendes øverste løjtnanter.", p="Måske var jeg ikke eksplicit i mine ordrer, <Class>. Jeg vil have over-inkvisitor Hvidmane dræbt én gang for alle. Og mens du er i gang, så tag også hendes top-officerer.\n\nDræb den fanatiker, Skarlagen-kommandør Mørkrøn. Læg Herod, Skarlagen-mesteren, øde. Og slagt Hundemester Loksøj og hans beskidte køtere også.\n\nNu, skrid!", c="Du har tjent Den Mørke Dame godt, <Class>. Det var ingen lille opgave, jeg bad dig om.\n\nDin loyalitet over for De Forladte er blevet noteret. Og din sejhed i kamp vil blive husket."},
  [1052] = {n="Ned ad Skarlagen-stien", l="Tag Broder Antons Anbefalingsbrev til Ralf den Hengivne i Sydhavn.", d="Vi i Skarlagen-korstoget gør krav på højborge fra Hjertedal til Tirisfal-engene. Vi er ret stolte af vores bastioner for renselse over hele Herrelande.\n\nDu har bevist dig selv mod de udøde i Forødelse. Men den virkelige trussel fra pesten ligger i Herrelande.\n\nRejs til byen Sydhavn i Østkongerigerne. Søg en korsfarer ved navn Ralf den Hengivne. Giv ham dette anbefalingsbrev med mit segl, så vil han eskortere dig til et hædersted i vores Skarlagen-kloster.", p="Hvem er der? Hvad vil du have af mig?", c="Broder Anton forkynder stadig Skarlagen-korstogets budskab? Åh gud...."},
  [1053] = {n="I Lysets Navn", l="Dræb Over-Inkvisitor Hvidmane, Skarlagen-kommandør Mørkrøn, Herod, Skarlagen-mesteren og Hundemester Loksøj, og rapportér derefter tilbage til Ralf den Hengivne i Sydhavn.", d="Jeg tjente engang Skarlagen-korstoget med ære, loyalitet og stolthed. Jeg troede på deres sag som værende ædel: at udrydde de udøde fra Azerot.\n\nMen da jeg tilbragte tid i klosteret i Tirisfal-engene, indså jeg, at deres greb om virkeligheden var ved at glide. De tror nu, at alle, der ikke bærer korstogets tabard, er smittet. Uskyldige mænd og kvinder blev torteret, fordi de angiveligt var smittet.\n\nSkarlagen-korstoget må knuses i Lysets navn. Du, <Name>, må ødelægge det vanvittige regime.", p="Korruptionen i klosteret vil ikke ophøre, før de højest rangerede embedsmænd er fjernet.\n\nI Lysets navn skal over-inkvisitor Hvidmane, Skarlagen-kommandør Mørkrøn, Herod, Skarlagen-mesteren og Hundemester Loksøj slås ned. Når de er faldet, kan den sande sag måske genoplives. Indtil da er enhver, der krydser korstogets vej, i fare.\n\nBegiv dig ud fra Sydhavn og gør det til virkelighed!", c="Selvom disciple af Lyset aldrig frydes over tab af liv, må vi acceptere, at sådanne ofre af og til må ske for det større gode for riget og planeten.\n\nGennem dine gerninger i klosteret har du skånet mange uskyldige liv, <Name>. Jeg hylder din sejhed."},
  [1074] = {n="Inkompetence + Kemi = Sjov", l="Bring Nitromirglycerium tilbage til Gaxim Rustsprut i Stentalon.", d="Værsgo, fremmede. Tag dig dog i agt med den... det er flygtigt stof.\n\nHvis du virkelig er en ven af Gaxim, så sig, at jeg hilser ham. Hvis du ikke er det, så må du have det sjovt med at sprænge dig selv i luften.", p="Ah, godt, godt, du er tilbage.", c="Din opgave er udført fejlfrit, <Name>.\n\nNG-5 er den utvetydige komponent i opskriften til at antænde dynamitvognene.\n\nHvad? Ja, dynamit... vogne fulde af det. Det er den perfekte afledning, siger jeg dig... bare vent og se."},
  [1077] = {n="Særlig Levering til Gaxim", l="Bring Beskedrullen til Gaxim Rustsprut i Stentalon.", d="Værsgo, <Name>. Det her burde gøre det godt.\n\nHusk at hilse Gaxim fra mig, næste gang du ser ham. Jeg ser frem til at høre om dette eventyr, når det når sin afslutning.\n\nFarvel.", p="Haha! Du er tilbage! Har du den? Har du besværgelsen?", c="Dette er perfekt, <Name>! Godt gået.\n\nDenne besværgelse, blandet med NG-5, skal lave den perfekte fjernudløste sprængladning.\n\nVi kan skabe den perfekte afledning for dig, så du kan snige dig ind og stjæle Venture A/S' breve og ingeniørplaner.\n\nDet vil helt sikkert sinke deres skovrydning."},
  [1080] = {n="Hemmelige Operationer - Beta", l="Hent Venture A/S' breve fra Vindskær-minen i den østlige ende af Vindskær-klippen.", d="Plan Beta er ligesom Plan Alfa, <Name>.\n\nVi skaber en afledning og stjæler så deres dyrebare breve.\n\nNøglen er at få deres breve... husk det.\n\nSiderne, jeg allerede gav dig, vil fortælle dig, hvor du skal placere sprængstofferne. Bare kom tilbage hertil i live og med de breve....", p="Hvordan gik det, <Name>?", c="Utrolig, <Name>! Kaela og Vagterne vil blive så glade. Med din dygtighed og mine opfindelser er vi uovervindelige."},
  [1081] = {n="Modtagelse hos Tyrande", l="Find Tyrande Hviskevind i Darnassos.", d="<Name>, jeg er sikker på, at Tyrande Hviskevind selv gerne vil takke dig for at have deltaget i denne mission.\n\nDet ser måske ikke sådan ud på overfladen, men det, du har hjulpet med at sætte i gang, kan meget vel styrke vores fodfæste i Stentalon-bjergene.\n\nHvis du betragter dig selv som vores allierede mod disse grusomheder, så gå og se Tyrande i Månens Tempel i Darnassos.", c="Hej, <Name>. Jeg har faktisk hørt dit navn før, og selvom du stadig er fuld af ungdom, glæder jeg mig over at se den vej, du har sat dig selv på.\n\nDu ville gøre mig en stor ære, hvis du ville modtage dette som en gave til påskønnelse."},
  [1082] = {n="Opdatering til Vagt Tenysil", l="Vend tilbage til Vagt Tenysil i Askedalen.", d="<Name>, du har gjort en stor gerning ved at række en hjælpende hånd her.\n\nVagterne i Askedalen vil belønne dig godt, hvis du fortæller dem, at Gaxim og jeg er i live. Fortæl dem, at vi er godt på vej til at standse Venture A/S og hele landets helbredelse.\n\nFind Tara Tenysil i Stjernelund; hun vil blive glad for at se, at du er vendt tilbage med gode nyheder.", c="Tak, <Name>. Du har gjort en tjeneste for Vagterne.\n\nJeg er glad for at se, at Kaela... og endda Gaxim har det godt.\n\nDu har fortjent vores påskønnelse."},
  [1083] = {n="Rasende Ånder", l="Bring 8 Ulmende Glør fra en hvilken som helst ildelementar i Den Brændte Dal til Kaela Skyggespyd i Stentalon.", d="Jeg er usikker på, hvad Venture A/S gjorde ved dalen, men det er indlysende, at de blev overmandet af væsnerne derinde.\n\nDe satte skoven i brand og brugte deres opfindelser til ødelæggelse for at decimere så meget af dalen, som muligt.\n\nMen i deres uvidenhed løsnede de også noget andet: brændende ånder, elementarer af ild, sten og raseri.\n\nLandet har ingen chance for at se Elunes smil, mens disse væsener løber frit omkring.\n\nBring mig deres ulmende glør, så du kan vise, at du har reduceret deres antal.", p="Første gang jeg så Den Brændte Dal, næsten græd jeg, <Name>.", c="Resterne af vores fjende... din styrke gavner os, <Name>. Tak."},
  [1084] = {n="Sårede Oldtidens Folk", l="Bring et stykke Tærede Granatsplint til Kaela Skyggespyd i Stentalon.", d="Det forekommer mig åbenlyst, at dalens beskyttere--træanterne--havde noget med Venture A/S' tilbagetrækning at gøre. Desværre er selv de engang så store vogtere nu blevet korrupte.\n\nGaxim mener, at deres korruption på en eller anden måde er forbundet med de våben, kobolderne brugte under deres tilbagetog.\n\nJeg fortalte ham, at jeg ville indsamle en prøve fra et såret træant og lade ham studere den for at finde ud af, om det er sandt.\n\nBring mig noget af granatsplinterne, så gnomen kan fortælle mig mere...", p="Jeg har en fornemmelse af, at Gaxim vil finde en anvendelse for granatsplinterne, uanset hvordan Venture A/S har brugt dem tidligere.", c="Tak, <Name>.\n\nDette bør være mere end tilstrækkeligt for Gaxim til at finde ud af, hvordan træanterne blev korrupte. Jeg giver ham det med det samme."},
  [1091] = {n="Kaelas Opdatering", l="Bring Venture A/S' breve til Kaela Skyggespyd.", d="<Name>, tag disse breve til Kaela. Jeg er sikker på, at hun vil vide om dette. Eller i det mindste vil Vagterne.\n\nSørg for at fortælle hende, hvor succesfulde vi var, og at vi ikke kunne have gjort det uden en lille smule magi.", p="Ja, <Name>? Hvad kan jeg gøre for dig?", c="Det er faktisk interessant.\n\nDu og Gaxim har gjort det meget godt, <Name>. Tak."},
  [1092] = {n="Gerenzos Ordrer", l="Lever den Uidentificerede Malm til Ziz Sprudlesprut i Stentalon-bjergene.", d="Jeg tror nok, jeg skal tænke over at komme væk herfra også. Det vil ikke tage lang tid, før ordet om, hvad der er sket her, spreder sig til de højere oppe, og jeg er sikker på, at de ikke ville tage særlig pænt imod at møde mig igen.\n\nJeg vil liste ud og mødes med Ziz. Forhåbentlig kan han finde mig et nyt job!\n\nJeg vil prøve at rydde lidt op i dette rod, men du bør tage malmprøven til Ziz med det samme. Han fortalte mig, at han ville slå lejr et sted på den vestlige side af Vindskær-klippen. Held og lykke.", p="Er der noget, jeg kan hjælpe dig med?", c="Ahhh, jeg vidste, at jeg gjorde det rigtige ved at bede Snudrik om at blive tilbage. Jeg er sikker på, at ingeniørerne i Undergrunden vil være særligt interesserede i at se på dette...\n\nSelvfølgelig vil jeg beholde et lille stykke til mig selv, men det, de ikke ved, kan jo ikke skade dem, vel?"},
  [1100] = {n="Ensbryns Dagbog", l="Læs Henrik Ensbryns Dagbog.", d="Du åbner langsomt den forvitrede dagbog tilhørende Henrik Ensbryn....", p="Ud fra dit bekymrede udtryk kan jeg se, at noget er galt....", c="Siger du, at du fandt denne dagbog på en død dværg? Giv mig lige et øjeblik til at kigge siderne igennem..."},
  [1114] = {n="Levering til Gnomerne", l="Bring de Skrøbelige Vogndele til Fizzle Messingbolt i Skimrende Sletterne.", d="Nu hvor jeg har det, jeg skal bruge, så giv disse dele til Fizzle Messingbolt. Han har ventet længe på dem -- jeg er sikker på, at han ikke savner den lille del, jeg fjernede fra hans ordre...\n\nOg jeg ville ikke nævne det for ham. Den var lille og værdiløs.\n\nStol på mig.", p="Har du noget til mig? Det er fantastisk! Lad os se det!", c="Der er de! Mine hydro-rallehjul og gentagelsesbolte! De duer fint. Tak!"},
  [1115] = {n="Rygtesmedden", l="Tal med Krazek i Bytteviken.", d="Nu hvor vi har gjort en tjeneste for gnomerne, er det tid til at gøre kobolderne en tjeneste!\n\nJeg hører, at kobold-racerpiloten Nazz Dampkedel ikke altid brugte det navn. Jeg undrer mig over, hvorfor han skiftede det. Jeg undrer mig over, om det er en hemmelighed, og... jeg undrer mig over, om han sætter pris på den hemmelighed.\n\nHvis nogen kender sandheden, så er det Krazek fra Bytteviken, på den sydlige spids af Kvælertorn. Tal med Krazek og spørg ham om vores kobold-pilot.\n\nHvis du kan få brugbare oplysninger ud af ham, så kan vi måske tjene penge på det.", c="Vil du vide noget om Nazz Dampkedel? Han er racerpilot ude på Skimrende Sletterne, ikke?\n\nJa, måske kan jeg finde noget ud om ham... men det bliver ikke let. Eller hurtigt.\n\nEller billigt."},
  [1117] = {n="Rygter til Kravel", l="Bring Kobold-rygterne til Kravel Koalskæg i Skimrende Sletterne.", d="Jeg måtte bruge nogle af mine tjenester, gav en sjælden flaske alvevin væk og lavede selv en del tungt detektivarbejde! Men jeg har fundet de oplysninger, du søger.\n\nHer, jeg har skrevet et brev med nogle meget interessante detaljer om vores ven, Nazz Dampkedel. Gør med det, hvad du vil -- det er for farligt for mig at bruge.\n\nBare fortæl ikke nogen, hvor du fik det fra!", p="Fik du noget om Nazz Dampkedel? Noget han måske helst vil holde hemmeligt??", c="Nå nå! Det her er interessant... meget interessant. Heh, måske burde jeg bukke for kobold-piloten, næste gang jeg møder ham.\n\nDet her er mange penge værd, <Name>. Jeg er sikker på, at Nazz vil betale en lille formue for at holde sin hemmelighed... en hemmelighed."},
  [1118] = {n="Tilbage til Bytteviken", l="Bring Kravels plan til Crank Brusebob i Bytteviken.", d="<Name>, du er en <Class>, jeg kan stole på, både til at få jobbet gjort og til at holde mund, mens du gør det.\n\nJeg har brygget en ny plan. Den er risikabel, men hvis den virker, kan vi begge tjene en pæn skilling! Og jeg tror, at du netop er den rette til at føre den ud i livet.\n\nTil at begynde med skal du tage tilbage til Bytteviken. Jeg beklager, gode <Name>. Jeg ved, at min sidste opgave førte dig derhen. Men denne gang skal du tale med Crank Brusebob.\n\nGiv ham dette brev. Og hvis han har brug for hjælp, så gør dit bedste for at hjælpe ham. Det vil være det værd.", p="Hej hej. Og hvad fører en ædel <Race> som dig ned til Bytteviken?", c="Jeg forstår. Kravel har en stor plan på hjul. Han har et snedigt sind -- det kan jeg lide ved ham.\n\nSå du får brug for noget til at forvirre hovederne, hva'? Noget kraftigt...\n\nJeg undrer mig over, om blandingen Zanzel giver sine zombier, kunne bruges..."},
  [1119] = {n="Zanzels Blanding og en Tåbens Mørkøl", l="Bring Tåbens Mørkøl tilbage til Kravel i Skimrende Sletterne.", d="Jeg har fundet ud af, hvordan man bruger Zanzels blanding sammen med mørkøl til at lave en kraftig drik. En Tåbens Mørkøl. Jeg tror, at den er præcis, hvad Kravel har brug for, men prøv den og lad mig vide, hvordan den virker.\n\nOg <Name>, hold ikke på den her ting for længe, uden at du bruger den. Zanzels blanding har en mærkelig effekt på mørkølens gær og sætter den i højeste gear. Så den holder sig ikke frisk for evigt.", p="Hej, <Name>. Kunne Brusebob hjælpe os?", c="Dejligt! Brusebob klarede det! Det husker jeg næste gang, jeg ser ham.\n\nOg tak, <Name>. Du gør et fantastisk stykke arbejde, og vi står begge til at tjene en masse penge på det..."},
  [1120] = {n="Få Gnomerne Fulde", l="Bring Tåbens Mørkøl til Gnom-grubechefen.", d="Vi må prøve Tåbens Mørkøl på et af grubeholdene. Hvis du vil prøve det på gnomerne, så værsgo -- tag mørkølen og giv den til gnom-grubechefen.\n\nOg vent ikke for længe. Den mørkøl går nok dårlig før eller siden.", p="Hej! Har du noget til mig?", c="Mørkøl? Hvor opmærksomt! Tak!\n\nVi burde ikke drikke, når væddeløbet nærmer sig, men... måske kan mine drenge tåle en lille én. Det kan da ikke være så stærkt, vel?"},
  [1121] = {n="Få Kobolderne Fulde", l="Bring Tåbens Mørkøl til Kobold-grubechefen.", d="Vi må prøve Tåbens Mørkøl på et af grubeholdene. Hvis du vil prøve det på kobolderne, så værsgo -- tag mørkølen og giv den til kobold-grubechefen.\n\nOg vent ikke for længe. Den mørkøl går nok dårlig før eller siden.", p="Hvad kigger du på?", c="Hvad har vi her? Sprut, hva'?\n\nTja, jeg har ikke noget imod, at vi tager en lille én..."},
  [1122] = {n="Rapportér til Brusebob", l="Bring rapporten om Tåbens Mørkøl til Crank Brusebob i Bytteviken.", d="Den Tåbens Mørkøl virkede fantastisk! Jeg satsede på næste væddeløb, og... lad os håbe, at kobolderne, du fik fulde, har gjort en masse ved deres vogn!\n\nDer er kun én opgave tilbage til dig -- tag denne seddel med tilbage til Crank Brusebob i Bytteviken. Han vil gerne vide om den vellykkede test.\n\nOg forhåbentlig kan vi få mere af den Tåbens Mørkøl til fremtidige væddeløb!", p="Hej <Name>. Hvordan gik det med mørkølen? Det er stærkt stads, ikke?", c="Der står her, at tåbens mørkøl var en succes. Det er gode nyheder!\n\nHvis du nogensinde vil have mere af varen, så lad mig vide, så får du mig til at samle mere af Zanzels blanding."},
  [1123] = {n="Rabine Saturnus", l="Tal med Rabine Saturnus i landsbyen Nathavn, Månelunden. Månelunden ligger mellem Ondskoven og Vinterkilde og er tilgængelig via en sti ud fra Tømmerkæbe-Greb.", d="Til denne opgave søger Vogter Remulos' majordomus i Månelunden - Rabine Saturnus - hjælp til at udforske de vidtstrakte ødemarker langt mod vest for Tanaris og Un'Gorø. Han befinder sig i Nathavn, Månelundens hovedlandsby.\n\nJeg vil gerne indprente dig, hvor vigtig din tilstedeværelse er. Der er voksende spændinger mellem nattealferne fra Darnassos og Cenarion-kredsen i Månelunden. Se bort fra racemæssige grænser og træk på dine forfædres visdom i din omgang med kredsen dér, <Name>. Held og lykke.", c="Jeg er Rabine Saturnus, og på vegne af Vogter Remulos og alle indbyggerne i denne hellige lund byder jeg dig velkommen.\n\nJeg sætter pris på din interesse og iver efter at hjælpe Cenarion-kredsen. Taurenerne har vist en utrolig tilbøjelighed til Cenarius' læresætninger, og gennem dem er Horden velkommen i denne lunds tryghed. Bevarelsen af Azerot er et fælles mål, vi begge deler.\n\nDu er blandt venner her, <Name>."},
  [1124] = {n="Ødemark", l="Tal med Lajo Stjerneslag ved gravpladsen Tapperhedens Hvilested i Silitus, og vis ham Rabines Brev.", d="Vest for Un'Gorø-krateret, via den nordvestlige højderyg, ligger en barsk ødemark - Silitus. Få ved, at der for længe siden blev ført en krig dér mellem nattealferne og en ond, fremmed magt. Ondskaben blev forseglet, men nu har vi mistanke om, at kræfter arbejder på at vække denne... usigelige rædsel.\n\nSøg Lajo Stjerneslag, en af vores agenter i Silitus; find ham ved Tapperhedens Hvilested, de faldnes sidste hvilested i ødemarkerne. Giv ham dette brev, så vil han give dig sin tillid til gengæld.", p="Dette er et farligt land at færdes så ligegyldigt i, <Class>. Hvad fører dig til Silitus' ødemarker?", c="Rabine sendte dig, gjorde han det? Nå, så betragt dig selv som velkommen her... så godt som dette øde og forladte land kan byde nogen velkommen.\n\nJeg var ikke født under de store prøvelser, der fandt sted her, men der er dele af denne ørken, der lige så godt kunne være uhyggelige billeder af den glemte fortid. Med din hjælp kan Cenarion-kredsen måske bringe endelig afslutning på en trussel, der skulle være død for generationer siden."},
  [1125] = {n="Sydvindens Ånder", l="Befri ånderne fra 8 Torturerede Druider og 8 Torturerede Vagtposter i Sydvinde-landsbyen, og vend derefter tilbage til Lajo Stjerneslag ved gravpladsen Tapperhedens Hvilested i Silitus.", d="Mod vores sydvest ligger et tragisk sted - ruinerne af Sydvinde-landsbyen. Her bør vores arbejde begynde, <Name>.\n\nAf det, vi har lært, var denne landsby engang en nattealf-basis for Silitus. Den er for længst overrendt af silitid-bistokkene, der plager ødemarkerne. Jeg kan kun forestille mig rædslen ved landsbyens første undergang...\n\nDe torturerede ånder fra faldne druider og vagtposter vandrer planløst rundt i ruinerne. Udforsk stedet, og befri sjælene fra disse ynkelige væsener, når det er nødvendigt.", p="Alliancen eller Horden, det er lige meget -- intet væsen fortjener at blive fanget i denne verden som en torturert ånd. Befrielsen af disse sjæle vil bringe tingene på plads, <Name>.", c="Jeg havde troet, at den enorme hvirvlende bistok nær landsbyens ruiner måske havde spillet en rolle i dens undergang. Det ser ud til, at dit arbejde beviser, at jeg har ret; bistokkens nærhed udgør en trussel mod alt fremtidigt arbejde, vi måtte udføre her.\n\nJeg takker dig for din godhed i at befri de faldnes sjæle; sådant arbejde er aldrig let, det ved jeg. Men når du er klar, vil jeg gerne bede om din hjælp endnu en gang..."},
  [1126] = {n="Bistokken i Tårnet", l="Klatr op i tårnet i Sydvinde-landsbyen og find en måde at sætte silitid-bistokken i gang. Bring alt usædvanligt, du måtte opdage under det, tilbage til Lajo Stjerneslag ved gravpladsen Tapperhedens Hvilested i Silitus.", d="Bistokken skal tages hånd om i Sydvinde-landsbyen, og jeg tror, jeg kender en måde at komme til dem på. Det har min erfaring vist, at silitid-bistokkene er meget følsomme over for deres omgivelser; det forklarer deres angreb, når de hører ånderne jamre deres død.\n\nSilitiderne er stærkest i tårnet -- det med masserne af hvepse, der kredser om det. Klatr op i tårnet og ryst bistokken i gang. Rapportér tilbage, hvad du opdager, men vær forsigtig! Hvis du finder noget, der kan hjælpe, så bring det til mig.", p="Nå, virkede det? Du er stadig i ét stykke, hvilket er gode nyheder. Fandt du noget?", c="Hvad i... hvad er det?\n\nDet har formen af en... kasse, måske? Den er tilgroet af noget frygteligt. Vent, der er en del her, der er blottet... er det en bog under al den klamme klidder?\n\nJeg tror, du har snublet over et ret stort fund her, <Name>... i hvert fald håber jeg, at det er det. Måske er det en dagbog eller en logbog fra oldtiden, bevaret i denne skal.\n\nJeg tror, jeg kender en måde at finde ud af, hvad det er."},
  [1137] = {n="Nyheder til Fizzle", l="Tal med Fizzle Messingbolt i Skimrende Sletterne.", d="Indurit har en utrolig modstandsdygtighed over for varme! Jeg er sikker på, at det vil virke til Fizzles stempler. Men han skal bruge ægte indurit-malm, ikke bare flager.\n\nFor at få malmen skal den udvindes dybt inde i Uldamaan, på de nordlige grænser af Ødelandene. Det er indurits sande kilde.\n\nHils Fizzle Messingbolt fra mig, og fortæl ham, hvad jeg har fortalt dig.\n\nGod rejse, <Name>. Og det vil ikke overraske mig, hvis vi ses igen -- når Fizzle hører om indurit, sender han dig nok til Uldamaan for at skaffe det!", c="<Name>, du er tilbage! Fandt du Martak? Talte du med ham? Hvad sagde han? Kan han hjælpe??\n\nFortæl mig, fortæl mig, fortæl mig!!"},
  [1139] = {n="De Tabte Tavler af Viljen", l="Find Viljens Tavle, og bring den tilbage til Rådgiver Bælgrum i Jernsmede.", d="Vi har bremset Skyggesmedje-klanen ved at afskære dem fra Sortklippe-spiret, men Hammertås' opgave er stadig uløst. Hans død må ikke være forgæves. Han drømte om at finde Viljens Tavle: en stenskive indgraveret med magi af titanerne selv, for at give deres skabninger liv -- så de skulle have en vilje af egen, eller så siger legenderne.\n\nVi må stadig hente tavlen, før Skyggesmedje-klanen finder den.\n\nVend tilbage til Uldamaan, find tavlen, og kom straks tilbage hertil.", p="Hammertås' opgave må gennemføres, <Name>. Det skylder jeg ham.\n\nDin tilbagevenden til Uldamaan er afgørende, ikke kun for det mål, men også for alle dværges sikkerhed. Med tavlen i Mørkjernsdværgenes hænder, ved nogen, hvor stærk deres hær af golemer ville blive?", c="<Rådgiver Bælgrum ryster på hovedet i vantro, mens du rækker ham stenskiven.>\n\n<Name>, dette er utroligt. Jeg lader straks kongens magikere få den. De vil gerne studere den for at finde ud af, om legenderne er sande. Men det er en diskussion til en anden gang: du har hjulpet vores folk mere, end jeg nogensinde havde forventet -- tak."},
  [1148] = {n="Dele af Sværmen", l="Bring 1 Silitidhjerte, 5 Silitidklør og 3 Intakte Silitidpanser til Korrand ved Korsvejen.", d="Du undersøger panseret omhyggeligt. Mens du vender det i hænderne, indser du, at kitinpladerne er sammenflettet på en måde, der gør dem utroligt stærke. Det er ikke som noget, du nogensinde har set. Du undersøger resten af kadaveret yderligere og indser, at disse skabninger er meget kraftfulde og højt udviklede.\n\nKigger du ned på panseret igen, tænker du, at Korrand ville nyde at studere flere af disse skabninger. Det kunne hjælpe ham med at finde ud af, hvad disse væsener er, og hvor de kommer fra.", p="Ah, det er længe siden, du kom og så mig, <Name>. Hvad kan jeg gøre for dig i dag? Du ser ud, som om du for nylig har set kampens ansigt. Godt... godt for Horden og godt for dig. Jo mere kamp du har set, jo mere hjælpsom vil du være; stærkere også.", c="Ahh, har du set Moktor for nylig? Han holder altid øje med mig. Jeg er ked af at høre, at han bruger sin tid på at holde øje med sit lille krigsselskab i stedet for at se kamp, men jeg er sikker på, at han har stor fornøjelse af at dræbe medlemmer af Opdagelsesrejsende-Ligaen.\n\nDu er klog at bringe mig disse prøver, <Name>. Sammen med æggene, vi finder på Kæmpernes Mark, burde disse give mig en god start på at finde ud af, hvad disse insekter er, og hvad de vil."},
  [1159] = {n="Vidensprøven", l="Find Parqual Finttallas i Underbyen.", d="Godt gjort, <Name>. Du har bestået første del af Vidensprøven, men der er endnu et spørgsmål, der skal besvares. Men det spørgsmål er ikke mit at stille.\n\nSøg Parqual Finttallas i Herrelande By. Han var en stor historiker for menneskerne, før Pesten overvældede ham. Nu fortsætter han med at søge oplysning, men af en anden art.\n\nHan vil stille endnu et krav til dig, før han spørger dig om noget, men du har klaret dig mesterligt indtil nu -- jeg er sikker på, at du vil overvinde hans forhindring.", c="Brauk sendte dig? Umuligt.\n\n<Parqual måler dig op og ned.>\n\nTrodsede Dor'Danik, tog et spring i tro, kæmpede og overvandt en mægtig elementar? Bah! Du er sikkert en farce; en eventyrer, der hørte snak i en kro. Og nu tror du, at du har det, der skal til for at bestå min prøve. Så være det... <Class>."},
  [1166] = {n="Overherre Mok'Mørkeknokkes Bekymring", l="Overherre Mok'Mørkeknokke i Brakkenmur-landsbyen vil have dig til at hente hans grog, snus og pengekasse i Støvsumpen.", d="Bøj dig for Overherre Mok'Mørkeknokke!\n\nRekkar gjorde mig til mægtig leder af Stenknuser-klanen!\n\nMig god leder. Mig holder klanen i sikkerhed.\n\nStore drager kommer og laver ild i gammelt hjem. Mig klog oger. Find nyt hjem til klanen her.\n\nForlad gammelt hjem så hurtigt, mig glemmer ting. Lille <Race>, gå og hent mine ting. Gå sydpå og find min lækre grog, mit snus og min pengekasse. Så kan jeg lide dig, når du har gjort det. Kig i Flammehulen og Stenknuser-ruinerne... de er der, det er jeg sikker på!", p="Mig tørstig efter grog. Mig savner snus også. Hvor er pengekassen? Du gå hent for Overherre Mok'Mørkeknokke.\n\nGå find sydpå i gammelt hjem. Mig for travl med at lede oger til at hente den.", c="Du god <Race>. Mig savner ting meget. Mig kan lide dig nu."},
  [1168] = {n="Den Sorte Drages Hær", l="Targ i Brakkenmur-landsbyen vil have dig til at dræbe 15 Ildmanke-spejdere, 10 Ildmanke-askehaler og 5 Ildmanke-vagter.", d="Mok'Mørkeknokke blev gjort til overherre af Rekkar. Han bekymrer sig mere om magt end om oger.\n\nSorte drager dræber mange oger. Dræb Targs kone. Mok'Mørkeknokke bad os løbe. Fik os til at komme hertil.\n\nOger burde kæmpe. Oger er ikke gode til at løbe. Mok'Mørkeknokke bekymrer sig kun om Mok'Mørkeknokke.\n\nMig kalder Stenknuser-ruinerne hjem. Mig kan godt lide det i syd. Dette sted er ikke hjem.\n\nHjælp ogerne med at kæmpe mod den sorte drages hær. Mig vil have hævn. Mig vil hjem.", p="Mok'Mørkeknokke siger til alle oger, at de skal blive og passe på stedet. Mig tror, oger må dræbe den sorte drages hær og få det gamle hjem tilbage.\n\nDu hjælper ogerne med at få hjemmet tilbage. Hjælp ogerne med at få hævn.", c="Du dræbte mange af den sorte drages hær. Du modige <Race>.\n\nGjorde Targ glad."},
  [1169] = {n="Identificering af Yngelen", l="Dras'Zilb i Brakkenmur-landsbyen vil have dig til at bringe ham 15 Brændende Tunger og 15 Brændende Hjerter.", d="Mens den kujonerede tølpe Mok'Mørkeknokke vælter sig i magt, og Targ kæmper med sorgens og hævnens dæmoner og stiler efter lederskabet i klanen, er jeg tilsyneladende den eneste, der er optaget af at finde kilden til aggressionen mod vores gamle hjem.\n\nHvorfor det forvirrede blik, <Name>? Forventer du, at jeg taler som en uhøflig tølper, bare fordi jeg er en oger?\n\nNu tilbage til sagen: bring mig hjerterne og tungerne fra ungerne og de nyklækkede. Jeg vil spore ondskabens rod...", p="Med hjerterne og tungerne fra de forbrændte afkom af den sorte drages hær kan jeg tyde, hvilket ussel udyr der har indført sit afkom i vores hjem. Måske kan vi med en større viden om vores angribere endelig tilintetgøre dem og genvinde Stenknuser-landsbyen fra ruinerne.\n\nSelvfølgelig er det en episk opgave i sig selv at overtale Mok'Mørkeknokke til at flytte sin dovne, fede masse ud af dette mudderhul...", c="Det var uden tvivl en farlig affære at samle alle disse hjerter og tunger. Jeg vil dykke ned i det arkane for at spore oprindelsen af det sorte uhyre, der er faldet over vores tidligere hjem."},
  [1170] = {n="Onyksias Yngel", l="Tal med Overherre Mok'Mørkeknokke i Brakkenmur-landsbyen.", d="Stenknuser-landsbyen blev invaderet af Onyksias yngel. Men hvorfor skulle datteren af den sorte drageherre, Dødsvinge, nedstige over vores lande?\n\nDette er yderst bekymrende. Onyksia er bestemt blevet drevet hertil med et formål, der går ud over at belejre en lille flok oger.\n\nUnderret Mok'Mørkeknokke med det samme! Der må handles.", c="Hvorfor du fortæller mig om drager? Mig kan ikke lide drager. Mig kan lide her. Ingen drager her."},
  [1171] = {n="Onyksias Yngel", l="Tal med Dras'Zilb i Brakkenmur-landsbyen.", d="Du lader mig være nu. Gå og fortæl Dras'Zilb, at vi bliver her. Ingen sort drage her.", c="Den dovne kujon!\n\nMok'Mørkeknokke viste styrke, da Rekkar var vores leder. Men kort efter Rekkars afgang faldt Mok'Mørkeknokke for fristelserne ved magt. I stedet for at lede, krævede han. Han tjener ikke sit folk, men forventer, at vi tjener ham.\n\nNoget må gøres."},
  [1172] = {n="Onyksias Yngel", l="Dras'Zilb i Brakkenmur-landsbyen vil have dig til at tilintetgøre 5 Onyksias Æg.", d="Onyksias yngel er spredt ud over Drageskumringen. Det er afgørende, at ikke flere unger får lov til at klække.\n\nSkynd dig til Ormesumpen i den sydlige del af Støvsumpen. Hun har sikkert lavet sit hi dér. Spor den onde drages æg op og ødelæg dem.\n\nVi vil aldrig genvinde Stenknuser-landsbyen, hvis området omkring den forbliver en yngleplads.\n\nSå til Mok'Mørkeknokke... jeg har andre planer for det fjols.", p="Du må skynde dig til Drageskumringen, <Name>. Med Onyksias æg spredt rundt om Ormesumpen står vi over for en overvældende overmagt, medmindre der gøres noget hurtigt.\n\nTilintetgør hendes æg! Lad ikke den sorte drages pest brede sig over vores hjemland!", c="Storartet! Der vil gå noget tid, før Onyksia kan producere flere æg.\n\nPå mit folks vegne takker jeg dig, <Name>.\n\nJeg har bedt meget af dig indtil nu. Måske kan du gøre Stenknuser-klanen en sidste tjeneste.\n\nMok'Mørkeknokke er ikke egnet til at lede os. Targ ville være en fortræffelig leder, men er hæmmet af sine skader og alder. Driv Mok'Mørkeknokke væk fra dette sted med magt. Først da kan vi udpege en ny leder, der kan føre os tilbage til vores rette hjem i syd."},
  [1173] = {n="Udfordring af Overherre Mok'Mørkeknokke", l="Besejr Mok'Mørkeknokke, og fortæl nyheden til Dras'Zilb i Brakkenmur-landsbyen.", d="Tør du udfordre Overherre Mok'Mørkeknokke?\n\nHaw!\n\nMig knuse lille <Race>!\n\nFortæl mig, når du er klar til en god tæsk.", p="Jeg troede, du skulle forsøge at drive Mok'Mørkeknokke ud af landsbyen. I stedet er du kommet til mig for at snakke?", c="Den kujonagtige fede masse Mok'Mørkeknokke flygtede som et skræmt barn. Du har gjort en stor tjeneste, <Name>.\n\nNu kan mit folk udpege en ny leder, en der vil hjælpe os med at genvinde vores gamle hjem en gang for alle."},
  [1176] = {n="Lastens Lettelse", l="Skaf 10 Hulte Gribbeknogler til Pozzig i Skimrende Sletterne.", d="Når det kommer til væddeløb, tæller hver lille smule! Om det er en mindre justering af effektudgangen, en lille slappelse af spændingsspolerne eller at gøre rammen lettere, skal du tage alt med i betragtning.\n\nVi bruger gribbeknogler til mange af de mindre strukturelle justeringer, vi laver på vores racere, for de giver den perfekte balance mellem styrke og vægt. Endnu bedre er det, at det er nemt for os at få flere, for saltsletterne er fulde af gribbe.\n\nBring mig nogle, så giver jeg dig en god pris på dem.", p="Har du de knogler til mig? Jeg var lige ved at begynde at lette styretøjet, men jeg vil ikke åbne hende, før jeg har alle de dele, jeg skal bruge.", c="Fantastisk! Jeg kan få holdet til at arbejde på det med det samme. Tak, <Name>!"},
  [1177] = {n="Sultne!", l="Mudderknusen Snavsefod i den nordlige Støvsump vil have 12 Mosefin-hoveder.", d="Mudder stor oger.\n\nMig sulten.\n\nGå bank fisk. Bring Mudder mad.\n\nDu fodre Mudder eller Mudder spise dig.", p="Giv mig mad ellers spiser jeg dig.", c="Mig elske fisk-hoved!\n\nMig ikke spise dig nu."},
  [1178] = {n="Nisse-sponsorat", l="Tal med Gazlowe i Skralleby.", d="Vores væddeløbshold er nissernes stolthed overalt. Du ville blive overrasket over nogle af de folk, der på den ene eller anden måde bidrager til vores hold.\n\nKender du Gazlowe? Han opsporer dele fra hele verden for os. Han kom endda ned og arbejdede på en af vores rigge engang!\n\nFor et par uger siden sagde han, at han ville sende os en ny prototype på brændstofregulator, men den er ikke kommet endnu. Han plejer at være meget punktlig... Ville du måske gide tage til Skralleby og spørge ham om det? Jeg ville ikke være så pågående, men gnomerne er ved at indhente os!", c="Pozzig sendte dig, hva'? Ved du hvad, Pozzig var en af de mest respekterede tinkerere i Undergrunden, før han trak sig tilbage for at begynde at arbejde på væddeløbsbilerne.\n\nDet første han gjorde, da han kom på holdet, var at udvikle de to motormodel-racere. Det kan være, at forretningerne lider uden ham, der arbejder sammen med Tinkerforeningen, men hvem bryder sig, ikke? Der er intet som væddeløbene!"},
  [1181] = {n="Nisse-sponsorat", l="Tal med Baron Tyranbrand i Bytteviken.", d="Jeg er bange for, at jeg ikke kan hjælpe dig meget mere, <Name>. Hvis du vil følge det op, foreslår jeg, at du går og banker på Baronen selv. Hvis der er nogen, der kender Tyranbrands forretninger, så er det Tyranbrand.\n\nDu finder ham på kroen på den anden side af havnen, øverste etage.", c="Åh, selvfølgelig ved jeg, hvad du taler om. Nej, jeg kan desværre ikke hjælpe dig. Nogle af mine folk skulle spore tegningerne til brændstofregulatoren op, men de kom tilbage med tomme hænder."},
  [1183] = {n="Nisse-sponsorat", l="Aflever brændstofregulatorens tegninger til Pozzig i Glimmerflatene.", d="Du burde være klar til at gå. Hils Pozzig fra mig, og sig til ham, at hvis han nogensinde har brug for noget, så tøv ikke med at spørge. Jeg venter på nyheden om, at han snart slår banerekorden!", p="<Name>! Lykkedes det dig at spore brændstofregulatoren op?", c="Jeg havde håbet, at den allerede var samlet, men det giver os en enestående mulighed for at forbedre designet fra bunden. Tak, <Name>. Jeg kan skitsere nogle forbedrede skemaer, bygge den og få den installeret rigtig snart."},
  [1184] = {n="Dele fra Sværmen", l="Vend tilbage til Belgrom Klippeknokler i Orgrimgrad.", d="Tag tilbage til Belgrom i Orgrimgrad og sig til ham, at Muktar gør sit arbejde godt ude i Tusind Nåle. Sig også til ham, at mig studerer fremskridt, og jeg håber at have lært mere snart. Det burde glæde ham meget.", c="Jeg sætter pris på din indsats, <Class>. Krigshøvdingen vil nyde at høre, hvor seje du har været i dine pligter.\n\nÅh, selvfølgelig vil jeg nævne dit navn for ham. Han taler ofte med mig og værdsætter mine meninger meget.\n\nGå nu, jeg har meget at lave. Og hvis du taler med Korrand snart, og han har nyt om disse væsener, så vend tilbage til mig – jeg synes, de er en trussel, der skal tages alvorligt."},
  [1185] = {n="Under Kitinen var...", c="Hej, det er dig igen! Altså, jeg mener dig – altså den dig, der er <Name>! Ja – den dig!\n\nHej, lad mig starte forfra!\n\nDet objekt du fandt i Silitus – det var faktisk en bog. Det var en dagbog skrevet på en meget gammel dialekt af det, vi nu kalder darnassisk. Det vil tage en stund, men jeg vil gennemgå den meget grundigt. Jeg syntes, du skulle vide, at det, du fandt, var yderst værdifuldt for Kredsen.\n\nHulemoderen er helt oppe at køre og det hele!"},
  [1186] = {n="Den attende pilot", l="Tal med Rasseric i Glimmerflatene.", d="Jeg kommer til at være travl med at integrere den nye brændstofregulator i vores racerdesigns, men hvis du vil hjælpe holdet lidt mere, så tal med Rasseric. Han er vores pilot – nå, vores attende pilot, for at være præcis – og han kan lide at tilføje sine egne små modifikationer til racerne.\n\nHan er lidt skruet forkert sammen, så prøv ikke at virke for overrasket.", c="Du er den <Race>, der har hjulpet Pozzig, ikke? Jeg var engang ligesom dig, løb rundt i pitområdet og hjalp med alt det arbejde, mekanikerne ville lade mig lave.\n\nSe nu på mig! Nisse-væddeløbsholdets pilot ekstraordinaire!"},
  [1187] = {n="Rasserics finjustering", l="Hent havium-forstærkeren til Rasseric i Glimmerflatene.", d="Pozzig er en god mekaniker, det ved jeg, men han er bange for bare at lade ildkraften køre og holde fast under turen. Ikke mig dog.\n\nNår Pozzig er færdig med en racer, tager jeg mig lidt tid til at sætte mine egne modifikationer på – du ved, løsne op for styringen, fjerne dele af rammen og tilføje mere saft!\n\nJeg bestilte en havium-forstærker hos Skruev i Gizmoriet i Gadgetbyen, men tilsyneladende styrtede luftskibet, den blev sendt med, ned i Støvsumpen! Jeg må have den, <Name>!", p="Hvordan skal jeg vise mit ansigt på banen uden et lille ekstra spark til at få mig i gang? Det er en skandale, siger jeg dig.", c="Bare se på denne skønhed! Femten pund massiv havium-kraft! Når jeg får den spændt fast på siden af min racer, er jeg rundt om banen så hurtigt, at jeg slår gnomerne to gange!"},
  [1188] = {n="Sikkerhed først", l="Bring havium-forstærkeren til Skruev i Gadgetbyen.", d="Men vent, hvad er dette? Skruev lod sikkerheden være på. Det vil begrænse den mængde kraft, jeg kan trække fra forstærkeren til enhver tid. Jeg sagde til ham, at jeg ville have den slået fra! Det her er ikke godt.\n\nDu skal tage det her med til Gizmoriet i Gadgetbyen i Kedelørkenen og få Skruev til at fjerne det her.", p="Som du sikkert ved, kan Gizmoriet tilfredsstille alle dine tinkerbehov! Hvordan kan jeg hjælpe dig?", c="Kun Rasseric ville kigge på den her og sige, at jeg på en eller anden måde havde sat en slags sikkerhedslås på den. Forstærkeren er næsten helt havium-sprængstof. Jeg har allerede modificeret den, så mere af dens last bliver leveret ved brug, men Rasseric er aldrig tilfreds, medmindre han går op til elleve!"},
  [1189] = {n="Sikkerhed først", l="Aflever den modificerede havium-forstærker til Rasseric i Glimmerflatene.", d="Der, jeg gjorde, hvad Rasseric ville have. Bare sig til ham, at han skal være forsigtig, når han udløser den her. Hvis han begår den mindste fejl, kommer han ikke videre, han bliver bare en brændt plet på banen.\n\nDet ville også være ærgerligt, hvis det skete. Hvem ved, om vores nittende kører overhovedet ville være god?", p="Kan du tro, at Pozzig satte en spand sand på racerne? Hvordan skal jeg nå min maksimale hastighed med en spand sand under sædet?", c="Nu er det mere som det! Jeg ville ønske, jeg kunne se blikket i gnomernes øjne, når de ser mig sætte denne baby i gang.\n\nSynd, at jeg bliver for travl med at slå en ny banerekord!"},
  [1190] = {n="At holde tempoet", l="Få Zamik til at skabe en afledning, og stjæl så Rizzels planer til Pozzig i Glimmerflatene.", d="Messingbolt-brødrene har opdaget et nyt byggemateriale, det er den eneste forklaring, der giver mening. Deres biler har kørt hurtigere end før, men deres designs og alle de andre data, vi har indsamlet fra deres løb, er identiske.\n\nVi ved, at Rizzel Messingbolt næsten konstant har været optaget af planerne for denne nye opdagelse.\n\nZamik kan skabe en afledning for dig, så du kan stjæle planerne fra dem.", c="Skrevet i hastig, hektisk hånd, en rulle med noter og tegninger til raffinering af et råmateriale."},
  [1194] = {n="Rizzels skemaer", l="Bring prøven af indurit-malm til Pozzig i Glimmerflatene.", d="Rizzels skemaer beskriver processen for raffinering af indurit-malm. Ud fra hans krummelurer er det tydeligt, at indurit-malm hentes fra den dværgiske udgravningsplads Uldhulen i Ødelandene.\n\nMeget af de øvrige noter handler om de varmebestandige egenskaber.\n\nSom papirvægt for planerne bruges en klump af, hvad der ser ud til at være uraffineret indurit-malm.", c="Indurit? Interessant... Hvis det kan modstå varme i den grad, du siger, ville det forklare den præstationsforøgelse, gnomerne har vist på det sidste.\n\nDenne prøve, du har bragt til mig, bliver også uvurderlig. Jeg kan udføre nogle tests på den, men jeg får brug for mere, før den rent faktisk er til nogen nytte for os."},
  [1202] = {n="Tørremores kajer", l="Bring kaptajnens dokumenter til Nazir Blodspyd i Brakkenmur-landsbyen.", d="<Name>, to af vores spioner blev sendt for at stjæle dokumenter fra et skib ved Tørremores kajer. De fik papirerne, men blev opdaget og måtte smide dokumenterne i havet.\n\nDen ene spion slap senere væk, men kunne ikke hente præmien. Han meldte sin fiasko til mig, og nu overdrager jeg opgaven til dig.\n\nDokumenterne ligger i en kuffert, i vandet et sted under Tørremores kajer. Find dokumenterne, <Name>, og bring dem til mig.", p="Fandt du dokumenterne, <Name>? De indeholder oplysninger, der er afgørende for Alliancens stabilitet og dermed afgørende for Hordens sikkerhed.", c="Jeg roser dig, <Name>. Det var ikke en let opgave. Men dokumenterne, du fik fat i, værdsættes meget af vores overordnede."},
  [1203] = {n="Jarl har brug for et blad", l="Bring et Månestål-bredsværd til Jarl i Støvsumpen.", d="Jeg har noget at skære. Jeg kan ikke fortælle dig, hvad jeg skal skære, men... jeg har brug for et blad. Et bestemt blad...\n\nNogle kalder det et månestål-bredsværd. Jeg kalder det et svingblad.\n\nHjælper du mig? Måske finder du et i byen, måske taler du med en smed, og han laver et specielt til mig.\n\nMen sov ikke på det. Det, jeg skal skære, holder ikke evigt...", p="Har du mit blad??", c="Det er et godt blad. Det har en god sving. Det er et godt svingblad. Tak. Tak, tak, tak!!! Nu vil jeg prøve det....\n\nSenere. Jeg prøver det senere. Men som jeg sagde... tak."},
  [1204] = {n="Mudderstens-suppe og insekter", l="Bring 8 gaflede Mudderstens-tunger til Morgen Stjerne i Tørremore.", d="Jeg arbejder på en ret, jeg kalder \"Mudderstens-suppe og insekter.\" Jeg mangler stadig hovedingredienserne, og... ja, jeg tror ikke, jeg ville holde længe ved at traske gennem Støvsumpen!\n\nSå, <Name>, kan du gå på jagt for mig? For det første har jeg brug for tungerne fra Mudderstens-skildpadder. Du finder Mudderstens langs kysten, mest omkring bugten.\n\nMen jeg vil ikke have hvilke som helst tunger! Jeg har hørt, at tungerne fra nogle Mudderstens er gaflede...\n\nDe siger, at de gaflede tunger har en særpræget smag, og den smag vil jeg have i min ret...", p="Fik du de gaflede tunger?", c="De her duer fint! Tak, <Name>!\n\nNu vil jeg prøve forskellige kogeteknikker på disse tunger for at finde den bedste måde at udtrække deres smag på.\n\nTil sidst får jeg en ret, der er værdig til at blive serveret hos Den Blå Eneboer i Stormvind!"},
  [1205] = {n="Dødmire", l="Bring Dødmires tand til Melor i Tordenbjerg.", d="Dødmire er en gammel krokolisk i Støvsumpen. Og nu er det hans tid til at dø.\n\nGamle knogler knirker, mens han trækker sin enorme krop gennem sumpen, og selvom han stadig bevæger sig med ungdommens styrke og fart, pine hans aldrende krop den store ånd indeni den, en ånd, hvis flamme ikke vil blafre.\n\nAlligevel lever han nu i konstant, rasende smerte. Du må gøre ende på dette ædle væsens liv, <Name>. Du må lede Dødmire til fred.", p="Har du Dødmires tand, <Name>? Har du gjort ende på skabningens lidelse?", c="Meget godt, <Name>.\n\nJeg er sikker på, at jagten ikke var let, men det er godt at vide, at udyrets smerte endelig er forbi."},
  [1206] = {n="Jarl har brug for øjne", l="Bring 40 uspringede Mørketåge-øjne til \"Sumpøje\"-Jarl på Sumplys Herregård.", d="Øjensaft er god saft at drikke. Ærgerligt, at de fleste krible-krable kun har to øjne.\n\nMen edderkopper har masser af øjne. Masser og masser. Og Mørketåge-øjensaft er lækker. Glat og salt! Uspringede edderkoppeøjne... Jeg smager dem allerede.\n\nMørketåge-edderkopperne er vest herfra, i Mørketåge-hulen. Man kunne tro, at edderkopperne er opkaldt efter hulen... eller er det omvendt?", p="Hvor er de øjne?", c="Du fik øjnene! Du fik øjnene! Lækre, lækre edderkoppeøjne!\n\nNogle øjne... når du stirrer på dem, stirrer de tilbage. Spis dem sidst. De holder dig med selskab... ude i sumpen.\n\nHej, små edderkoppeøjne. Hej! Du smager af kylling. Klistret, salt kylling!\n\nMmmh."},
  [1218] = {n="Beroligende Krydderier", l="Bring 3 Beroligende Krydderier til \"Sumpøje\"-Jarl i Støvsumpen.", d="Jeg kan godt lide at lave mad. God sumpmad. Stegte grønne frøben og lignende.\n\nOg til madlavning har jeg brug for krydderi. Beroligende krydderi. Så laver jeg en gryderet, og så koger jeg den op og slurper den i mig, og du får også lidt.\n\nKan du lide gryderet?", p="Krydderi. Vi kunne alle bruge lidt krydderi i livet. Er du enig?", c="Ah, det er krydderiet! Så er der lidt sumpet, godt gryderet."},
  [1219] = {n="Orkens rapport", l="Bring spionens rapport til en løjtnant i Tørremore.", d="Ved at sigte gennem den løse jord findes en afhugget ork-hånd. Og i hånden holdes et knoglesnittet rør. Og i røret ligger et jordplettet pergament.\n\nPergamentet er skrevet på orkisk... og det ser vigtigt ud.", p="Har du en rapport at aflevere?", c="Hm... jeg kan ikke læse orkisk særlig godt, men dette ligner en rapport... skrevet af en ork-spion!"},
  [1220] = {n="Kaptajn Vimmes", l="Bring spionens rapport til Kaptajn Garran Vimmes.", d="Kaptajn Vimmes bør se den ork-rapport, du fandt, <Name>. Han kender orkisk bedre end de fleste. Og han bør vide, at der er Horde-spioner nær Tørremore!\n\nKaptajnen er i kasernen på den nordøstlige side af Tørremore Ø.", p="Har du noget til mig?", c="En rapport fra en ork-spion! Hvordan fandt du den her? Det er lige meget -- lad os se, hvad der står..."},
  [1222] = {n="Stinkes flugt", l="Eskorter \"Stinke\" Ignatz, og tal derefter med Morgen Stjerne i Tørremore.", d="Fantastisk, endelig noget, der ikke vil spise mig!\n\nJeg har brug for hjælp til at håndtere krible-krablerne her omkring, og du passer til formen, makker.\n\nKokken Morgen Stjerne forsker i en ny opskrift, og han sendte mig herud for at samle kærmyntebladene. Jeg regner med, at han synes, de er lækre.\n\nUnder alt det, mens jeg ledte efter en kærmynteplante... blev jeg omringet! Kan du hjælpe mig herfra og holde øje med mig, mens jeg leder efter kærmyntebladet?", p="Har du set Hr. Ignatz? Jeg sendte ham ud i sumpen for noget tid siden, og han er ikke vendt tilbage!", c="Hr. Ignatz var lige her med kærmyntebladene, og han fortalte mig, at du hjalp ham ud af nogle virkelige problemer.\n\nTak, <Name>. Jeg vil bede min onkel om at bespise dig med et gilde, næste gang du besøger Den Blå Eneboer i Stormvind."},
  [1238] = {n="Den tabte rapport", l="Bring spionens rapport til Nazir Blodspyd i Brakkenmur-landsbyen.", d="Ved at sigte gennem den løse jord findes en afhugget ork-hånd. Og i hånden holdes et knoglesnittet rør. Og i røret ligger et jordplettet pergament.\n\nPergamentet er en rapport lavet af en ork, der brugte uger på at spionere på byen Tørremore.\n\nEfter at have gennemgået pergamentet er det klart, at det må bringes til ork-spionmesteren i Brakkenmur-landsbyen.", p="Har du noget til mig?", c="Godt arbejde, <Name>. Vores agent, Grete Nathøje, var stationeret uden for Tørremore. Han fik til opgave at spionere på byen.\n\nDette er hans seneste rapport, og det kan være hans sidste -- ud fra dit vidnesbyrd frygter jeg, at Grete mødte sin ende i sumpen..."},
  [1239] = {n="Det afhuggede hoved", l="Bring det trodsige ork-hoved til Nazir Blodspyd i Brakkenmur-landsbyen.", d="Energisk gravning afdækker hovedet af en mandlig ork, grimt afhugget ved nakken. Hans læber er frosset i et hånligt grin, og dens mørke øjne stirrer trodsigt.", p="Har du endnu en sag at melde, <Name>?", c="Dette er hovedet af Grete Nathøje! Som jeg frygtede, er han død.\n\nSe på såret på hans nakke! Kunne et våben have lavet det grimme snit, eller har et udyr dræbt vores agent?\n\nDette er et mysterium, vi må løse, <Name>. Vi må finde ud af, om Gretes død var Alliancens værk!"},
  [1240] = {n="Trolden Hekselæge", l="Tag det trodsige ork-hoved til Kin'weelay i Grommegol-basislejren i Kvælerdorn-dalen.", d="Vi må kende begivenhederne omkring Gretes død! Og den eneste måde at gøre det på, <Name>, er gennem trollenes hekseri.\n\nBring Gretes hoved til Kin'weelay i Kvælerdorn-dalen, ved Grommegol-basislejren.\n\nKin'weelay er den mest magtfulde hekselæge blandt Mørkspyd-trollene. Hvis nogen kan tale med Grete Nathøjes ånd, er det ham.", p="Der er en vred ånd omkring dig, bror. Hvad fører dig til Kin'weelay?", c="Ah, nu forstår jeg. Denne orks ånd er bundet til vores verden, kogende af raseri over en opgave, der endnu ikke er gjort færdig.\n\nNå, lad os tale med denne vrede ork..."},
  [1250] = {n="Den savnede diplomat", l="Tal med Mikail i Vådlandene.", d="Defias betalte mig ikke godt nok til at dø for deres sag. De tog kongen. Ja, kongen af Stormvind, ikke en eller anden ringe diplomat. Han var på vej til Tørremore for at mødes med Jæina Stoltemor – det var tilsyneladende en stor sag og en stor hemmelighed. Men det er ikke kun Defias, der er involveret. De arbejder sammen med nogen. Jeg tror, de vidste, at det her var større end dem.\n\nMin del var bare at få deres mand om bord på kongens skib, mens det lå i havnen. Fyren hed Hendel. Det er alt, jeg ved. Det sværger jeg!", c="KONGEN?! Altså... kongen? Den rigtige konge? Laver du sjov? Du nævnte ikke, at du ledte efter kongens kidnappere. Jeg hørte ikke engang, at han var savnet – det ville forklare, hvorfor hans søn er blevet kronet, lidt.\n\nJeg sender straks bud til Elling. Han vil gerne vide, at du er på sporet.\n\nJeg havde aldrig troet, at Jahn ville forråde Stormvind for nogle elendige mønter. Selv en snigmorder må have ære, når det gælder visse ting.\n\nNøglen nu er at finde denne Hendel. Og jeg tror, jeg kan hjælpe med det."},
  [1252] = {n="Løjtnant Pavle Rytte", l="Bring Ryttes Mærke til Kaptajn Garran Vimmes i Theramøre.", d="Et glimt af lys på jorden fanger dit øje under murbrokkerne. Når du børster affald og aske væk fra genstanden, afsløres et emaljeret mærke i hvid med et guldanker på overfladen: Theramøres kendetegn.\n\nUnder ankeret er navnet \"Løjtnant Pavle Rytte\" præget ind.", p="Har du fundet noget interessant ved Skyggefuld Hvile-kroen?", c="Det er aldrig godt nyt, når en vagts mærke bliver bragt til mig.\n\nSommetider er det en mand eller kvinde, der er faldet i slag, og så må jeg bringe de sørgende familier budskabet. Andre gange får vi aldrig at vide, hvad der skete med dem. Og andre gange er det endnu værre end det."},
  [1253] = {n="Det Sorte Skjold", l="Bring det Sortbrændte Jernskjold til Kaptajn Garran Vimmes i Theramøre.", d="Et jernskjold, sortbrændt af ilden der hærgede kroen, sidder fast på den smuldrende skorsten, en af de få dele af bygningen, der engang udgjorde Skyggefuld Hvile-kroen.\n\nSkjoldet kan tages løs fra skorstenens mursten.", p="Har du fundet beviser fra stedet, hvor Skyggefuld Hvile-kroen stod?", c="Hm, jeg er ingen ekspert i fremstilling af våben og rustninger. Brugen, ja, men ikke fremstillingen.\n\nDette skjold ser lige så almindeligt ud som alle andre, bortset fra skaderne efter branden, der slugte kroen."},
  [1258] = {n="... og Kryb", l="Bring 12 Upåklagelige Kryberben til Morgen Stjerne i Theramøre.", d="En anden del af min nye opskrift er det skallede ben fra en kæmpekrabbe. Og krabberne i Støvsumpen -- Mudderskaller kalder de dem -- duer bare ikke! Jeg er bange for, at de eneste brugbare krabber lever langt væk, i Sorgens Sump.\n\nSkallen på krabbebenet er en vigtig del af rettens præsentation, så jeg har brug for upåklagelige, uskadte ben. En voksen krabbe har måske kun et eller to sådanne ben, og jeg har brug for en masse for at kunne udforske min ret.\n\nSå, <Name>... er du villig til at rejse?", p="Min forskning i Mudderstens-tungerne skrider fint frem. Går din krabbejagt godt?", c="Disse er vidunderlige eksemplarer, <Name>! Skallerne er i perfekt stand, og kødet er lyserødt og mørt. Der flyder en kokkes blod i dine årer, det er jeg sikker på!"},
  [1259] = {n="Løjtnant Pavle Rytte", l="Find ud af mere om Rytte fra Adjudant Skatteran i Theramøre.", d="Jeg kender ikke navnet Løjtnant Pavle Rytte. Dit bedste bud er at spørge Adjudant Skatteran. Han holder styr på alle optegnelserne for Theramøre-vagten, fra personale til udstyr.\n\nHan burde kunne fortælle dig, hvem denne Rytte er, med et hurtigt blik i sine bøger.", c="Hej, <Name>. Du vil gerne have oplysninger om et bestemt medlem af Theramøre-vagten? Rytte, var det?\n\nGiv mig lige et øjeblik til at finde den rigtige bog."},
  [1260] = {n="Morgen Stjerne", l="Tal med Morgen Stjerne i Theramøre.", d="Jeg er ved at udvikle en ny menu til restauranten. Den vil være fyldt med landlige retter med et \"sumpet\" tema. Jeg tror, mine gæster på Den Blå Eneboer vil elske dem!\n\nJeg sendte min nevø Morgen til Theramøre, en by i udkanten af Støvsumpen. Han er der for at samle opskrifter fra de lokale, og jeg må vide, hvad han har fundet indtil nu.\n\nTuren til Theramøre er lang. For lang for mig. Men jeg vædder med, at en ung <Class> som dig ville springe til for at rejse, ikke?", c="Åh, min onkel sendte dig, gjorde han?\n\nNå, jeg har forsket i opskrifter, og jeg har nogle spor, men jeg har brug for hjælp.\n\nHjælp fra en, der er villig til at få fødderne våde."},
  [1261] = {n="Grete Taler", l="Bring det Juvelbesatte Vedhæng til Nazir i Brakkenmur-landsbyen.", d="Forbandet mudderskal! Du kan ikke dræbe Grete! Ah, men jeg er død. Så det må være den, der har dræbt mig...\n\nMen min mission! Min mission! Du, <Name>, må fuldføre den.\n\nMens jeg var i nærheden af Theramøre, så jeg en gruppe Alliance-soldater, der havde slået lejr på stranden. Og en soldat bar et vedhæng... et vedhæng prydet med flere ædelsten, end nogen soldat kunne have råd til!\n\nDen nat sneg jeg mig ind i deres lejr og stjal vedhænget, men da jeg var på vej tilbage til basen, dræbte en mudderskal-krabbemand mig!\n\n<Name>, du må finde den mudderskal og genskaffe vedhænget!", p="<Name>, fandt du ud af, hvad der blev af Grete?", c="Dette vedhæng blev båret af en soldat fra Stormvind??\n\nTak, <Name>. Du har afsløret hemmeligheden bag Gretes død. Men dette vedhæng er et nyt mysterium at løse, et der måske får alvorlige konsekvenser for Alliancen og Horden."},
  [1262] = {n="Rapport til Zor", l="Bring det Juvelbesatte Vedhæng til Zor Ensetræ i Orgrimgrad.", d="Det er underligt, at vedhænget, Grete stjal, var i hænderne på almindelige soldater. Måske var dens ejer forklædt, eller også stjal soldaterne det selv!\n\nUanset hvad der er sandt, er dette et adelsvedhæng, og vi må finde ud af, hvem dets sande ejer er, hvis vi skal løse dets mysterium.\n\nTag vedhænget med til Zor Ensetræ i Orgrimgrad. Han er velbevandret i Alliancens politik og vil vide, om dette vedhæng har en historie blandt Stormvinds adel.", p="Du rejste fra Brakkenmur-landsbyen i Støvsumpen? Hvordan har Nazir det, og hvordan går hans indsats i sumpen?", c="Dette vedhæng er lavet med stor dygtighed og præcision, <Name>. Ingen ork ville begære sådan et juvel...\n\nMen mange mennesker ville.\n\nJeg vil få dette vedhæng undersøgt. Lad os håbe, at dets mysterier i tide bliver afsløret for os."},
  [1266] = {n="Den Savnede Diplomat", l="Find Menig Hændel i Støvsumpen.", d="Menig Hændel er vest for her. Han har vagt i øjeblikket og beskytter nogle af Theramøres infiltratorer, mens de hviler. De har holdt øje med Horde-basen, Brakkenmur, og ledt efter alt andet, der kunne true vores grænser.\n\nDu bør ikke have problemer med at finde ham; led bare efter teltene langs vejen.\n\nJeg har en anden sag at tage mig af, men jeg indhenter dig snart nok. Du kan altid finde mig i Frue Stoltmoors tårn, hvis du får problemer.", c="Hej, borger. Dette er et farligt sted at vandre rundt på. Jeg ville ikke hænge for længe ved, hvis du sætter pris på dit liv.\n\nHolder du dine spørgsmål korte, skal jeg se, om jeg kan hjælpe. Bare hold øje med de beskidte oger. Ryget har det, at der er en Horde-base et sted i sumpene. Infiltratorerne gør, hvad de kan for at finde den, men det går langsomt, og vi har gjort lidt fremskridt."},
  [1267] = {n="Den Savnede Diplomat", l="Tal med Jaina Stoltemor i Støvsumpen.", c="Lad mig være den første til at takke dig for alt, du har gjort, <Name>. Du har været en utrolig velsignelse for mit folk og for folkene i Stormvind. Jeg beklager, at jeg ikke kunne gøre din bekendtskab under bedre omstændigheder.\n\nVær også klar over, at jeg ikke åbenlyst kan takke dig for din indsats, men jeg forsikrer dig igen om, at den værdsættes.\n\nNår du besøger Theramøre fremover, så søg mig op, så skal jeg forsøge at holde dig orienteret om situationen.\n\nTak igen, <Name>."},
  [1270] = {n="Stinkes Flugt", l="Eskortér \"Stinke\" Ignaz, og tal derefter med Mebok Snurrefix i Skralleby.", d="Fantastisk, endelig noget, der ikke vil spise mig!!\n\nJeg har brug for hjælp til at håndtere kryberne herude, og du passer lige til opgaven, makker.\n\nEn kobold fra Skralleby ved navn Mebok Snurrefix har brug for nogle sumpbønneblade til en eliksir, eller noget. Jeg bekymrer mig ærlig talt ikke om, hvorfor -- hans penge var gode, og jeg kender denne sump, så her er jeg.\n\nHøjst upraktisk, at jeg blev omringet, før jeg fandt sumpbønnen! Kan du hjælpe mig ud herfra og holde øje med mig, mens jeg leder efter Meboks plante?", c="Stinke var her med de urter, jeg bad ham om, og han fortalte mig, at du hjalp ham ud af en klemme. Godt arbejde! En ven af Stinke er en ven af mig!\n\nHan bad mig give dig dette, hvis jeg nogensinde så dig, lige før han gik tilbage sydpå mod sumpen."},
  [1271] = {n="Festmåltid hos Den Blå Eneboer", c="Min nevø sagde, at du hjalp ham med hans forskning i Støvsumpen, og at du hjalp hans medarbejder ud af en trang situation. Nå, vi Stjerner holder sammen, og vi ignorerer ikke vores venner!\n\nSå vask dine hænder, <Name>, for vi er ved at holde et festmåltid til ære for dig!"},
  [1276] = {n="Det Sorte Skjold", l="Vis det Sortbrændte Jernskjold til Mosgarn i Tordenklippe.", d="Ah, nu husker jeg! Mosgarn er en velrenommeret smed i Tordenklippe. Jeg vidste, at jeg havde hørt hans navn et sted før.\n\nSom tak tildelte Jordringen mig et sæt rustning fremstillet af Mosgarn. Meget godt arbejde.\n\nMåske kan han fortælle dig mere om skjoldet, han fremstillede.\n\nDet er ikke meget af et spor, men da vi ikke fik noget brugbart ud af Rytte, er det alt, vi har.", p="Hej dér, <Class>. Er der noget, jeg kan hjælpe dig med?", c="Ja, du har bestemt ret. Det er et skjold, jeg har lavet.\n\nDesværre er der ikke meget mere, jeg kan fortælle dig, <Name>. Jeg laver så mange forskellige skjolde og rustningssæt, at jeg ikke kan holde styr på dem alle."},
  [1282] = {n="De Kalder Ham Smilende Jim", l="Tal med Kaptajn Garran Vimmes i Theramøre.", d="Jeg kan ikke lade være med at have ondt af gamle Jim dér. Han var ikke altid sådan. Drev en kro ude i sumpen i et stykke tid, et vidunderligt sted.\n\nSe, jeg har ikke lyst til at tale om det. Tag det op med Kaptajn Vimmes, hvis du absolut må.", c="James Hyl er hans rigtige navn. Han åbnede en kro i kanten af Ødemarken. Ville lave et pænt sted, hvor rejsende kunne holde pause...\n\nMåske tænkte han for stort, men kroen klarede sig godt i et stykke tid. Så mistede vi kontrollen over vejene i sumpen, og ogerne tog over.\n\nJames var for stædig til at opgive sin drøm for sikkerhed bag vores mure, og Skyggefuld Hvile-kroen blev brændt ned til grunden. Vi undersøger sagen, men har ikke haft meget held. Hvis du vil hjælpe til, så se, hvad du kan finde i ruinerne."},
  [1285] = {n="Dælins Mænd", l="Returner oplysningerne om Rytte til Kaptajn Garran Vimmes i Theramøre.", d="Rødon... Rødsti... Ah, her er den! Løjtnant Pavle Rytte.\n\nSluttede sig til Theramøre-vagten sammen med de fleste af rekrutterne, der kom over havet med Frue Stoltmoor. Indtrådte i Kul Tirask-marinen i en alder af seksten. Fremragende tjeneste, forfremmelser...\n\nFørt som savnet.", c="Savnet? Det ville være Skatterans venlige måde at sige forræder på.\n\nUtvivlsomt er han en af de tosser, der er så blindt loyale over for Admiral Dælin, at han blev forræder. Er det ikke en lækker ironi? Desertørerne anklager os for at svigte Alliancen."},
  [1286] = {n="Desertørerne", l="Få oplysninger om Rytte fra Balos Jakken og desertørerne i Støvsumpen.", d="Det har været en kamp at holde fast i sumpen, men gennem vores urokkelige vilje har vi kunnet vedligeholde flere forsvarstårne i området.\n\nDe seneste oplysninger og spejderrapporter, jeg har modtaget, tyder på, at en gruppe desertører har slået sig ned i vores forladte tårn ved Tabt Peg, sydøst for kroen.\n\nDesertørernes leder er en mand ved navn Jakken. Se, om du kan få nogle oplysninger ud af ham.\n\nVær advaret, <Name>. Han kan være en hård nød at knække.", c="Sendte Vimmes dig? Kunne ikke selv klare det beskidte arbejde, kunne han..."},
  [1287] = {n="Desertørerne", l="Tal med Kaptajn Garran Vimmes i Theramøre om Rytte.", d="Rytte? Den kujon?\n\nVi smed ham ud af lejren, fordi han insisterede på at plyndre ogernes forsyninger oppe i Brakkenmur-landsbyen. Vi er ikke så mange, at vi kunne stå imod de tankeløse brutale.\n\nHan gik over stregen én gang for meget, så vi lod ham klare sig selv.\n\nNu hjalp jeg dig... Så hvorfor hjælper du ikke os og glemmer, at du stødte ind i os?", c="Jeg vil sende Løjtnant Koldvæld til at tage sig af desertørerne i Tabt Peg. Desuden vil jeg instruere ham i at finde Rytte. Sumpen er ikke så stor og sporløs, at han burde være ude af stand til at finde ham."},
  [1288] = {n="Vimmes' Rapport", l="Bring Vimmes' Rapport til Frue Jaina Stoltmoor i Theramøre.", d="Du har udført noget godt arbejde, <Name>, det bedste jeg har set fra en amatør.\n\nFrue Stoltmoor bad mig holde hende orienteret om denne delikate situation, og jeg har ikke talt med hende i nogen tid nu.\n\nJeg havde tænkt mig at levere min rapport til hende senere, men det virker mere passende, at det er dig, der taler med hende om den. Du kan sikkert svare på hendes spørgsmål bedre, end jeg kunne."},
  [1289] = {n="Vimmes' Rapport", l="Vend tilbage til Kaptajn Garran Vimmes i Theramøre.", d="Nå. ud fra Kaptajn Vimmes' rapport, har du været en enorm hjælp for hans efterforskning. Og for det takker jeg dig.\n\nJeg kan slappe mere af, når jeg ved, at sagen er i så dygtige hænder. Hvis du vil være så venlig, vil jeg bede dig om at vende tilbage til Kaptajn Vimmes og hjælpe ham med at komme til bunds i dette mysterium."},
  [1301] = {n="James Hyl", l="Tal med Vincens Hyl i Menetil-havnen.", d="Før jeg arbejdede her på Den Blå Eneboer, blev jeg oplært af en af de bedste kokke og kroværter, jeg nogensinde har mødt. Han hed James Hyl. Alt, hvad jeg har, og alt, hvor jeg er kommet hen i livet, skyldes ham.\n\nJeg spekulerer på, hvordan han har det. Hans bror Vincens og han tog arbejde i en krostue i Menetil-havnen, men jeg har ikke hørt fra ham for nylig.\n\nHvis du nogensinde kommer den vej, kunne du måske sige hej til ham for mig?", c="James? Åh, han forlod for et godt stykke tid siden.\n\nFik nok en ny omgang patriotisme, må jeg antage. Ikke svært at se, hvorfor han ville. Med al galskaben i Herrelande sluttede mange sig til Jaina Stoltmoor, da hun drog over havet."},
  [1318] = {n="Uafsluttet Gordøk-forretning", l="Find Gordøk-Magtens Handske og returner den til Kaptajn Krømknus i Rædselshammeren.\n\nIfølge Krømknus siger den \"gamle historie\", at Tortelderin - en \"uhyggelig\" alv, der kaldte sig selv for en prins - stjal den fra en af Gordøk-kongerne.", d="Nu du konge, så måske du kan få den værdifulde Gordøk-artefakt tilbage fra den uhyggelige alv, der kalder sig prins! Kongen før dig fejlede, ligesom alle de andre konger siden Tortelderin - den uhyggelige alv - stjal den fra den gamle Gordøk-konge!\n\nArtefakten kaldes Gordøk-Magtens Handske. Gamle historier siger, at kun den ene sande Gordøk-konge kan få den tilbage. Gamle historier siger også, at den uhyggelige alv stadig er her omkring - find den, og den vil blive til en mægtig handske, du bærer for evigt! Jo, jeg viser dig!"},
  [1319] = {n="Det Sorte Skjold", l="Vis det Sortbrændte Jernskjold til Caz Tohjul i Theramøre.", d="Jeg beklager, at jeg ikke kan være til stor hjælp, <Name>, men jeg kan henvise dig til en, der kan. Caz Tohjul, en af vores bedste smede, arbejder ved essen i smedjen.\n\nTag skjoldet med til ham, og se hvad han kan fortælle dig.", p="Noget for mig at kigge på?", c="Hm... interessant jernstykke, du har her. Bestemt ikke lavet af nogen af de smede, jeg kender på denne side af havet, og det er bestemt ikke mit arbejde."},
  [1320] = {n="Det Sorte Skjold", l="Tal med Kaptajn Garran Vimmes i Theramøre.", d="Ah, jeg havde næsten overset dette... Læderremmen på bagsiden må være brændt af, men det ser ud til, at den var lavet til at passe en stor person. Jeg vil gætte på en tyrefolk, faktisk.\n\nDet er stort set alt, hvad jeg kan fortælle dig. Fortæl Kaptajn Vimmes, at jeg beklager, at jeg ikke kunne være til mere hjælp.", c="Det er ikke meget information at arbejde med, men vi må huske det. Forhåbentlig falder nogle af de andre brikker i dette mysterium på plads og tegner et mere hjælpsomt billede af, hvad der skete."},
  [1321] = {n="Det Sorte Skjold", l="Vis det Sortbrændte Jernskjold til Do'gøl i Brakkenmur-landsbyen.", d="Hmm... Jeg kan ikke se noget usædvanligt ved dette skjold. Vi bør få Do'gøl, smeden, til at kigge på det og se, om han kan fortælle os mere om det, men jeg ville ikke sætte mit håb til det...", p="Noget til mig, <Class>?", c="Dette er godt skjold. Meget stærkt, tungt, godt. Men Do'gøl har ikke brug for det. Jeg laver skjolde, jeg køber dem ikke, <Name>.\n\nDet burde du vide."},
  [1323] = {n="Det Sorte Skjold", l="Tal med Krøg i Brakkenmur-landsbyen.", d="Åh, jeg tror, jeg måske har hældt for meget syre på skjoldet. Lad mig lige gnide lidt...\n\nHm, lidt svært at læse, men det ser ud til at være navnet Mosgarn. Har aldrig hørt om ham. Måske Krøg ved det. Krøg kender mange mennesker.", c="Mosgarn? Lyder bekendt... Jeg kan ikke sætte fingeren på det. Måske kommer det til mig senere.\n\nDet er nok ikke vigtigt. Et skjold kan komme fra hvor som helst og betyde ingenting..."},
  [1324] = {n="Den Savnede Diplomat", l="Besejr Menig Hændel i Støvsumpen.", d="Hvad?! Du kommer her og anklager mig for at alliere mig med Defias, og tror, jeg bare vil stå her, mens du fornærmer mig?! Noget siger mig, at du har haft det coming i lang tid.", p="Hej igen, <Name>. Jeg håber, du ikke har noget imod hjælpen, men vi kunne ikke have Hændel løbende væk, eller værre, ende død.", c="Jeg forsikrer dig, vi er alle ret oprørte over de aktuelle begivenheder, men lad os tage ham med tilbage til Theramøre til forhør, så finder vi nok Kongen.\n\nJeg er sikker på, at min frue Stoltemor gerne vil takke dig for din hjælp. Tal med hende, når du har et øjeblik."},
  [1359] = {n="Zinges Levering", l="Bring Ulvehjerte-prøverne til Apoteker Zinge i Underbyen.", d="Ulvehjerterne, du skaffede, besidder en kvalitet, man ikke ser hos lignende prøver. Der er en giftighed i dem, som burde være dødbringende for selve ulvene, hvori hjerterne slår!\n\nDet er helt utroligt, og vi må studere det nærmere. Jeg beholdt nogle få prøver af de skaffede hjerter. Tag dem med til min kollega, Apoteker Zinge. Du finder hende i vores hovedkvarter i Underbyen.", p="Har du noget til mig?", c="Ah ja, hjerteprøverne, som Renferrel talte om. Jeg glæder mig til at eksperimentere med dem... Det Kongelige Apotekerselskab har altid interesse, når nye former for gift opdages."},
  [1360] = {n="Genvundne Skatte", l="Hent Krom Tykarms dyrebare ejendel fra hans kiste i den nordlige Almindelige Hal i Uldaman, og bring den til ham i Jernsmede.", d="Jeg havde selv et fint job som gravemand på udgravningsstedet i Uldaman i Ødelandene... indtil de forbandede trogger dukkede op. Jeg slap med huden nogenlunde hel, og ikke meget andet. I kaosset efterlod jeg min mest dyrebare ejendel. Den er sikker for troggerne i min kiste, javel, men den ligger lige midt i dem.\n\nJeg ville stå i gæld til dig, både i ære og mønter, hvis du kunne hente den til mig! En kiste med mit navn på står for enden af den nordlige Almindelige Hal. Det er den, du skal komme ind i.", p="Nå, fik du slået de trogger hen længe nok til at komme ind i min kiste og snuppe min skat?", c="Ah, nu føler jeg mig hel igen - tak skal du have.\n\nNogle dværge skatter måske metallets glans, og andre måske gnisten fra ædelsten... men en Tykarm uden en dyrebar krus i hånden er knap nok en Tykarm!"},
  [1363] = {n="Mazæns Befaling", l="Tal med Akolyt Dellis i Stormvind.", d="Som vogter af værkerne her i biblioteket på Akademiet for Arkane Kunster og Videnskaber er det mit ansvar at sikre, at alle de magiske bøger og ruller altid er til stede. Hvem ved, hvilken dårskab der kunne udfolde sig, hvis nogle af disse fortryllede tekster faldt i de forkerte hænder?\n\nHvilket minder mig om... min assistent, Dellis, begik en forfærdelig fejl i sidste uge. Han er ganske dygtig i biblioteket, men inkompetent, så snart han forlader portene til Stormvind. Vær en helt, og hjælp gamle Dellis ud af det, vil du?", c="Det var ikke min skyld. Virkelig, det var det ikke."},
  [1364] = {n="Mazæns Befaling", l="Hent Khadgars Afhandlinger om Dimensional Konvergens, og lever dem til Vogter Mahar Ba i Underverdensgarden-fæstningen.", d="Mester Mazæns anvisninger var ganske klare: Lever en meget vigtig afhandling til Vogter Mahar Ba i Underverdensgarden-fæstningen.\n\nMen jeg havde aldrig været i Det Sønderrevne Land før! Rejsen var skræmmende!\n\nDa jeg kom til Sorgens Sump, tog jeg en forkert vej og endte omringet af forfærdelige plantelignende sumpvæsener. De væltede frem, som om de ville angribe mig, så jeg løb. Men i min hast tabte jeg afhandlingen. Et af udyrene tog den, er jeg sikker på.\n\nKunne du venligst prøve at hente den og lever den til Mahar Ba?", p="Hvad fører dig til Underverdensgarden-fæstningen, <Race>?", c="Ah, udmærket!\n\nI lang tid havde jeg frygtet, at min anmodning om Khadgars Afhandlinger om Dimensional Konvergens var blevet overset af Mester Mazæn fra Akademiet for Arkane Kunster og Videnskaber.\n\nHan må være druknet i anmodninger, i betragtning af de mange mærkelige hændelser, der foregår.\n\nNu, hvis du vil undskylde mig, må jeg straks begynde min forskning. At endelig få et glimt af indsigten hos en så stor som Khadgar begejstrer mig uden grænser."},
  [1367] = {n="Magrom-alliancen", l="Opnå et Venligt ry hos Magrom, og tal derefter med Warug.", d="For at besejre kentaurerne må vi bruge deres had imod dem. Vi vil alliere os med en af klanerne, og gennem dem lærer vi, hvordan vi besejrer alle klanerne.\n\nHvis du vælger at alliere dig med Magrom og derefter slå deres fjender, Gellekis'erne, optjener du respekt blandt Magrom. Når du har optjent nok, så mød Magrom-talsmanden Warug i udkanten af Magrom-landsbyen, i det sydøstlige Forødelse.", p="Væk! Magrom taler ikke med de svage. Vi dræber dem!\n\nHvis du vil tale med mig, så vis mig, at du er stærk. Kom tilbage, når du har slået mange Gellekis ihjel.", c="Gellekis'erne græder, når de hører dit navn, <Name>. De frygter dig, og de hader dig. De hader dig, ligesom de hader Magrom!\n\nMåske er du stærk som Magrom. Det får vi at se..."},
  [1369] = {n="Brudte Tårer", l="Oprethold dit ry hos Magrom, og bring 3 Brudte Tårer til Warug i Magrom-landsbyen.", d="Gellekis tror, at vores kentaur-moder, Terradras, beskytter os. De er dumme. Ingen beskytter kentaurerne. Magrom har ikke brug for beskyttelse! Vi er de stærkeste!\n\nVis Gellekis, at de er dumme. Gå til hulen i deres landsby. De gemmer krystaller i den hule, Terradras' tårer. Ødelæg tårerne og bring mig de knuste stykker!", p="Hvis du ikke er vores fjende, så gør du, hvad jeg beder om!", c="Du fik tårerne! Nu vil Gellekis vide, at Terradras ikke vil hjælpe dem. Hun vil ikke græde, når vi knuser dem! Magrom skal herske!\n\nDu er klog at hjælpe os, <Name>. Vi er de stærkeste."},
  [1370] = {n="Stjæling af Forsyninger", l="Bring 6 poser Grovt Tørret Kød til Uthek den Vise i Gellekis-landsbyen.", d="Når vi ikke er i krig, jager vi efter kød. Kød giver os styrke, og fulde maver kæmper hårdere end tomme.\n\nDet er det samme med Magrom. De gemmer ekstra kød, så de kan kæmpe længere mellem jagterne. Hvis du angriber deres landsby mod øst og tager deres kødlager, så vil deres styrke svigte.", p="Kom tilbage, når du har bevist din værdi over for Gellekis endnu en gang!", c="Godt. Jeg kan høre Magroms høje maver rumle fra deres landsby, langt væk!\n\nJeg vil give dette kød til Gellekis. Og vi vil kæmpe i mange dage uden hvile.\n\nDet, du gjorde, er godt for Gellekis, <Name>."},
  [1372] = {n="Intet Andet End Sandheden", l="Tal med Apoteker Faustin i Tiggerens Hjemsøgte.", d="Vores ekspeditionsstyrke blev sendt efter Varimathras' befaling for at kortlægge det lavere Azeroth.\n\nMens jeg var ude og spejdede, bemærkede jeg en menneskelig Infiltratør, der spionerede på Tiggerens Hjemsøgte. Før jeg kunne pågribe ham, fangede nogle af vores orkiske... brødre... ham og førte ham til Stenard, deres højborg i Sorgens Sump.\n\nJeg vil... hjælpe... vores orkiske allierede. De så ikke vores lejr her, men ikke desto mindre vil jeg række en hjælpende hånd.\n\nArbejd sammen med Faustin her for at udvikle et... sandhedsserum til vores ven i Stenard.", c="Zraedus fortalte mig lige om den nysgerrige lille Infiltratør, før du kom.\n\nDet er et ret stort problem. Det sidste, vi har brug for, er en nysgerrig snushane, der roder rundt i Tiggerens Hjemsøgte.\n\nJeg er sikker på, at orkerne i Stenard ville være ret ivrige efter at høre, hvad vores ven har at sige. Da de er vores allierede, ehm, må vi hjælpe dem med at få enhver information, de kan, ud af mennesket.\n\nArbejd sammen med mig, <Name>, så leverer vi et sandhedsserum til Stenard.\n\nFor Horden!\n\n...fik jeg det rigtigt?"},
  [1373] = {n="Ongeku", l="Oprethold dit ry hos Gellekis, og bring en Draenetyst-skår til Uthek den Vise i Gellekis-landsbyen i Forødelse.", d="Du har mere at bevise, og din næste opgave vil føre dig langt væk, så i mellemtiden kæmper Gellekis mod Magrom uden dig.\n\nJorden hvisker mange hemmeligheder til dem, der lytter. En hemmelighed, jeg hører, handler om en rød krystal. Den kaldes draenetyst, og den er ny for vores jord. Den kommer fra et sted, hvor bjerge flyver, og hvor dæmoner hersker.\n\nBring mig en skår af draenetyst, så gør den min magi stærk! Skåret findes i et sted, der kaldes Sorgens Sump, bevogtet af den fortabte Ongeku.", p="Vis mig, at du er en ven af Gellekis, <Name>.", c="Ja, dette er skåret, som jorden hviskede om. Jeg kan mærke stærk magi i det! Jeg vil bruge denne magi mod Gellekis' fjender.\n\nDu har gjort endnu en opgave for os, <Name>. Måske kalder vi dig snart ven."},
  [1374] = {n="Khanen Jehn", l="Bring Khanen Jehns hoved til Uthek den Vise i Gellekis-landsbyen i Forødelse.", d="Jorden taler til mig, og den siger, at Magrom bliver svage. Nu er det tid til at dræbe deres Khan!\n\nBring mig hovedet af Magrom-khanen, Jehn!", p="Vis mig, at du er en ven af Gellekis, <Name>.", c="Khanen Jehn var stærk, men dum. Han troede, at hans egen styrke var stor. Han så ikke, at jordmagi er stærkere. Magrom-kentaurerne vil nu falde uden deres leder, og Gellekis skal én dag herske!"},
  [1375] = {n="Khanen Shaka", l="Oprethold dit ry hos Magrom, og bring Khanen Shakas hoved til Warug i Magrom-landsbyen i Forødelse.", d="Du hjælper Magrom, og jeg kan lide dig. Nu skal du dræbe Gellekis' Khan! Han er Khanen Shaka, og jeg vil have hans hoved! Jeg vil stirre på hans hoved og le af ham!", p="Udfør opgaver for Magrom, så hjælper jeg dig.", c="Khanen Shaka er død! Jeg vil sætte hans hoved på en pæl og beholde det hos mig, så Shaka kan se Magroms styrke!"},
  [1380] = {n="Khanen Hratha", l="Oprethold dit ry hos Gellekis, og bring Plyndrer-nøglefragmentet til Uthek den Vise i Gellekis-landsbyen.", d="<Name>, du hjalp os mod Magrom. Nu skal du hjælpe os med at besejre Plyndrerne! Dræb deres klans leder, Khanen Hratha!\n\nFor at møde ham skal du blæse i Plyndrernes Krigshorn. Det står på en høj klippeknold i Spydenes Dal.\n\nMen for at blæse i hornet må du skaffe et krigshornsmundstykke. Disse er sjældne og bæres kun af betroede Plyndrer-kentaurer.\n\nEfter hornet er blæst, vil kentaurer komme. Dræb dem, indtil Hratha dukker op.\n\nKhanen Hratha har et stykke af en... nøgle. Bring det til mig...", p="Er Khanen Hratha død? Har du nøglefragmentet?", c="Han er død! Khanen Hratha er død! Og nu vil Plyndrerne falde! Når Gellekis hersker over dette land, <Name>, vil vi huske dig. Og jordens ånder skal synge dit navn for evigt."},
  [1381] = {n="Khanen Hratha", l="Oprethold dit Magrom-ry, og bring Plyndrer-nøglefragmentet til Warug i Magrom-landsbyen i Forødelse.", d="Gellekis-khanen er død, og nu vil Plyndrerne falde! Dræb Plyndrer-khanen, Hratha!\n\nFor at møde ham skal du blæse i hornet på den høje klippeknold i Spydenes Dal. Men for at blæse i hornet har du brug for et mundstykke. For at få et mundstykke skal du dræbe Plyndrer-kentaurer. Bliv ved med at dræbe, indtil du finder et mundstykke. Blæs så i hornet.\n\nGør dette, og Plyndrer-kentaurerne vil komme til tårnet. Dræb dem, indtil Khanen Hratha dukker op. Hratha har et stykke af en nøgle. Giv mig dette stykke...", p="Gør, hvad jeg beder om. Bevis over for mig, at du er en allieret af Magrom!", c="Khanen Hratha er død! Nu er Magrom de stærkeste af kentaurerne! Vi knuser de andre og hersker over Forødelse!\n\nVi vil huske dig, <Name>, og du skal skånes for vores hove, når alle andre er trampet ned."},
  [1382] = {n="Mærkelig Alliance", l="Opnå et Venligt ry hos Gellekis, og tal derefter med Uthek den Vise.", d="Vi er heldige, at kentaurklanerne kæmper indbyrdes, for hvis de gik sammen i én styrke, ville de være ustoppelige. Ja, vi er heldige, og vi bør presse vores fordel.\n\nÉn af kentaurklanerne, Gellekis-klanen, er i brutal krig med Magrom-klanen. Hvis vi angriber Magrom, så kan der måske indgås en alliance med Gellekis.\n\nTal med Uthek den Vise i udkanten af Gellekis-lejrene i det sydvestlige Forødelse. Gennem hende kan vi måske indgå en alliance med Gellekis.", p="Væk med dig! Gellekis vil ikke have dig her. Forsvind nu!!\n\nKom tilbage, når du har dræbt mange Magrom, så vil jeg tale med dig.", c="Dit navn hviskes blandt Gellekis. Du har meget Magrom-blod på dine hænder. Det er godt.\n\nMåske er det også godt, hvis vi taler sammen. Tal om, hvad du kan gøre for Gellekis, og hvad vi kan gøre for dig."},
  [1383] = {n="Intet Andet End Sandheden", l="Apoteker Faustin i Tiggerens Hjemsøgte har brug for 5 Skyggepanter-hjerter, Mosens Herres svamp og en Dybgænger-tumor.", d="Jeg har lige det rette serum i tankerne. Det vil håndtere sandheden præcis, som sandheden bør håndteres.\n\nTil denne koncentrat skal jeg bruge flere Skyggepanter-hjerter fra sumpen. Jeg kræver også den fortryllede svamp fra Mosens Herre, der bor der. Jeg er sikker på, at en så dygtig som du, <Name>, kan overtale ham til at afgive noget.\n\nNu bliver det svære at skaffe en Dybgænger-tumor fra det fjerntliggende Forødelse. Meget sjældent bliver kæmperne der syge, og så dannes en tumor.\n\nNu, af sted med dig!", p="Den Infiltratør i Stenard vil helt sikkert... åbne sig... efter han har drukket mit specielle serum. Haha!\n\nIngredienserne er på ingen måde lette at skaffe. Skyggepanterne er almindelige i sumpen, men det kan være skræmmende at samle nok hjerter til vores formål. Og Mosens Herre kan være et så kræsent udyr.\n\nHvad angår Dybgænger-tumoren, er de utroligt svære at finde. Men den kemiske reaktion, jeg kan udlede af den, er uden sidestykke.", c="Fremragende, <Name>! Og lige til tiden. Ifølge Zraedus er Infiltratøren kommet sig over sine sår og er klar til at blive forhørt af orkerne.\n\nGiv mig lige et øjeblik til at forberede gif-- jeg mener forberede sandhedsserummet."},
  [1384] = {n="Razzia mod Kolkarerne", l="Oprethold dit ry hos Gellekis, og bring 10 Grove Amuletter til Uthek den Vise i Gellekis-landsbyen i Forødelse.", d="Kolkar-kentaurerne tror, at deres magi er stærk. De kender ikke til magi! De ville ikke kende magi, selvom den bed dem!\n\nDu skal vise dem, at deres magi er svag. Gå til Kolkarerne mod nordøst og dræb dem. Tag deres amuletter. Bring mig amuletterne, så kaster jeg dem i ilden og griner!", p="Har du amuletterne? Viste du Kolkarerne, at de er svage?", c="Du gør en god gerning for Gellekis. Kolkarerne er svage og vil dø. Deres magi er ynkelig, og den vil ikke redde dem. Du viste dem dette, og deres frygt vil gøre dem endnu mere kraftløse!\n\nOg i vores lande dør de kraftløse snart."},
  [1385] = {n="Brutal Politik", l="Opnå et Venligt ry hos Magrom, og tal derefter med Warug.", d="Forødelse er et land i krig. Kentaurerne fører krig med hinanden, og vi tror, at sejrherren blandt dem vil brede sig ud og true vores højborge. Det kan vi ikke tillade\n\nVi må lære at besejre kentaurerne, og for at gøre det... må vi alliere os med en af klanerne. Magrom-kentaurerne fører krig med Gellekis. Hvis du kæmper mod Gellekis, så overvejer Magrom måske en alliance.\n\nVind Magroms gunst, og tal derefter med Warug i Magrom-landsbyen i det sydøstlige Forødelse.", p="Du går nu, ellers knuser Magrom dig! For at blive vores ven må du dræbe Gellekis.", c="Mange Gellekis falder for dig. Det kan jeg lide. Måske kan du gøre flere ting, jeg kan lide. Måske kan du og Magrom blive venner."},
  [1387] = {n="Kentaur-dusør", l="Bring 15 Kentaur-ører til Korporal Melkins ved Nijels Punkt i Forødelse.", d="Mange klaner udgør kentaurracen. Hver har sin egen leder og dagsorden, men alle klanerne har én ting til fælles. Grusomhed.\n\nHvis vi nogensinde skal finde fred, så må kentaurerne fjernes. Og derfor sætter jeg dig til netop den opgave.\n\nMens du vandrer rundt i Forødelse, skal du jage kentaurer og tage deres ører. Bring mig mange, mange ører.\n\nGør dette i Alliancens tjeneste, <Name>, så kommer vi et skridt tættere på krigens ende.", p="Har du en rapport, <Name>?", c="Ah, ørerne. Godt gjort.\n\nDin tjeneste for Alliancen er ubestridt, <Name>. Blodet, du har spildt i Forødelse, vil uden tvivl redde utallige liv."},
  [1388] = {n="Intet Andet End Sandheden", l="Giv Faustins Sandhedsserum til Dødsstalker Zraedus i Tiggerens Hjemsøgte.", d="Alt forløber efter planen, <Name>. Jeg vil have dig til at give dette sandhedsserum til Dødsstalker Zraedus, og han vil vise dig, hvordan man administrerer det... ordentligt.\n\nHaha!", p="Jeg håber, du har bevist din nytte for vores kære ven, Apoteker Faustin.", c="Jeg vidste, at gamle Faustin ville finde på noget godt! Du var en fremragende hjælp, uden tvivl.\n\nNu lad os få det gjort, skal vi?"},
  [1389] = {n="Draenetyst-krystaller", l="Bring 6 draenetyst-krystaller til Magtoor i Havnelyet i Sorgens Sump.", d="De fortabte, der bor i Brakkernes Fristed, ser ud, som vi ser ud, men de er monstre... drevet til vanvid af rejsens strabadser til Azeroth. Engang var de vores brødre, men nu bor de i Brakkernes Fristed mod øst og fanger eller dræber enhver, der vandrer i nærheden.\n\nOg de har stjålet noget helligt fra os - draenetyst-krystaller.\n\nVi mangler styrken til at trænge ind i Brakkernes Fristed og hente vores stjålne draenetyst fra blandt deres hytter og lejrbål, men uden disse krystaller... kan også vi miste vejen.", p="Har du krystallerne?", c="Tak, <Name>. Vi står i din gæld."},
  [1391] = {n="Intet Andet End Sandheden", l="Tag Zraedus' Brygg med til Infiltratør Marksen i Stenard.", d="Vi må operere med en vis mængde diskretion. Når alt kommer til alt, er det vel ikke sådan, at du bare skal spadsere derind og overtale tølpen til at drikke Faustins koncentrat her?\n\nMen hvis der er én ting, de mennesker ikke kan benægte, så er det spiritus. Jeg tager Faustins serum og blander det i denne øl. Jeg garanterer, at den stakkels tølpe ikke vil vise nogen modvilje, når det gælder om at slubre en bryg.\n\nSkynd dig til Stenard i Sorgens Sump, <Name>. Og hold vores lille mission pæn og stille...", p="Vær venlig at have barmhjertighed med mig! Jeg har oplysninger, der rækker ud over alliancens grænser. Selvom jeg ikke er nogen sympatisør for Horden, foregår der politisk forræderi, som må afsløres!", c="En drink til mig? Hvor venligt. Det er flere dage siden, de har tilladt mig at drikke. Lad mig tømme den her, så fortæller jeg dig, hvad jeg har lært...."},
  [1392] = {n="Noboru Køllen", l="Bring Noborus Kølle til lederen af Havnelyet i Sorgens Sump.", d="Noboru har plaget Draenæerne i Havnelyet i månedsvis, og hans kølle er et symbol på den brutalitet, de har lidt under de fortabtes hænder.", p="Hilsner. Og velkommen til Havnelyet.", c="Har du fået den frygtede Noborus våben? Er han så død?\n\nDette er en glædelig dag for Havnelyet. Noboru og hans bande var en rædsel for os, de vandrede rundt i sumpene og dræbte enhver Draenæ, der krydsede deres vej. Han var en direkte trussel mod vores overlevelse, og vi havde ikke styrken til at møde ham.\n\nVi er heldige at have en ven i dig, <Name>."},
  [1393] = {n="Galæns Flugt", l="Eskortér Galæn ud af fare, og find derefter hans lejr i Sorgens Sump og åbn hans stærkskrin.", d="Hjælp venligst! Disse væsner vil spise mig!\n\nHjælp mig væk herfra, så giver jeg dig en stor skat! Den er i min lejr i sumpen nord for Stenard, men den er låst inde i et stærkskrin, som kan åbnes med et trick, som kun jeg kender.\n\nHvis du hjælper mig med at flygte, så lærer jeg dig det.", p="Nøglehullet i dette stærkskrin er fyldt med sort harpiks. Det er umuligt at åbne.", c="Nøglehullet i dette stærkskrin er fyldt med sort harpiks. Det er umuligt at åbne.\n\nMen Galæn fortalte dig om en skjult lås på bunden af kassen...\n\n...Efter en hurtig eftersøgning findes låsen. Låsen vippes, og stærkskrinet åbner sig..."},
  [1394] = {n="Sidste Passage", l="Tal med Dorn Slettejæger i Tusindnåle.", d="Du har gjort det godt, <Name>. Du har bestået min prøve og prøverne før min. Vend tilbage til Dorn i Tusindnåle. Han vil mærke forandringen i dig og se, at dit sind, din krop og din ånd er stærke nok til, at du bør belønnes for din indsats.\n\nForbliv tro mod balancen, du har vist gennem disse prøvelser, <Name>. Dorn vil teste dig igen i fremtiden, hvis du gør.", c="Ah, <Name>. Det er længe siden, du sidst trådte ind i mit hjem. Det forekommer, som om mange måner er gået, siden du tog dit første spring, der satte dig på din vej.\n\nOg nu vender du tilbage til mig stærkere, end du engang var... mere oplyst. Dette glæder mig. Og du bør retfærdigt belønnes for at have set mine prøver til ende."},
  [1395] = {n="Forsyninger til Underverdensgarden", l="Bring Kassen med Kraftsten til Kvartermester Lungertz, før kraftstenene udløber.", d="Denne kasse med kraftsten skal til Underverdensgarden-fæstningen i Det Sønderrevne Land. De holder ikke deres kraft længe, så vi kan ikke sende dem med næste karavane.\n\nDu må tage dem, og du må tage dem hurtigt.\n\nBring dem til Kvartermester Lungertz i Underverdensgarden-fæstningen. For at nå fæstningen skal du rejse mod øst gennem Dødvinds-passet, derefter mod øst gennem Sorgens Sump og så mod syd gennem Det Sønderrevne Land.\n\nVær forsigtig, <Name>. Du vil rejse gennem farlige lande, og alligevel må du ikke fejle.", p="Hej! Tag dig ikke af alt postyret, det er bare almindelig forretning som sædvanligt i Underverdensgarden-fæstningen.\n\nHar du noget til mig?", c="Ah, kraftstenene! Magikerne bliver glade for at se dem!\n\nTusind tak, <Name>. Jeg ved, at din rejse fra Mørkeshire ikke var let."},
  [1396] = {n="Indtrængende dyreliv", l="Dræb 8 unge Savtand-krokolisker, 10 Sorgspindere og 10 Sumpjaguarer og vend derefter tilbage til Vogter Bigge i Sorgernes Sump.", d="Min karavane var på vej til østkysten, men vi nåede aldrig vores mål. De Fortabte angreb os, dræbte vagterne og spredte forsyningerne.\n\nKun jeg overlevede overfaldet. Jeg har svoret at beskytte de forsyninger, der er tilbage, men vilde skabninger lurer i nærheden. Hjælp mig venligst med at forsvare min lejr mod bæsterne!", p="Sumpvæsnerne presser sig tættere på, <Name>. Du må forsvare lejren!", c="Dyrenes lyde er nu svage, fjernere. Tak, <Name>. Lad os nu håbe, at de ikke vender tilbage!"},
  [1398] = {n="Drivtræ", l="Bring 8 stykker Solttørret Drivtræ til Vogter Bigge i Sorgernes Sump.", d="Jeg står dybt i gæld til dig, <Name>. Et ærefuldt hjerte banker i dig. Og nu har jeg en anden opgave, som jeg ydmygt beder om din hjælp til.\n\nSkal jeg nogensinde nå Underverdensgarden, må jeg reparere denne vogn. Og til det... har jeg brug for træ. Stærkt, tørt træ--ikke det svampede, snørklede træ fra sumpens træer.\n\n<Name>, rejs østpå til kysten og led efter drivtræ, som solen har tørret. Bring det til mig.", p="Fandt du noget drivtræ, <Name>?", c="Dette træ er let, men sejt. Tak, <Name>. Det vil passe fint."},
  [1421] = {n="Den tabte karavane", l="Find Karavanekisten i Brakkernes Fristed, skaf Troldmændenes Reagenser og bring dem til Vogter Bigge.", d="Jeg var målløs under De Fortabtes angreb, men før mit syn blev sort, så jeg en af vores vogne blive slæbt mod Brakkernes Fristed, den tabte landsby mod nord.\n\nI den vogn var en karavanekiste med værdifulde reagenser, reagenser der er vitale for troldmændene i Underverdensgarden Fæstning. Find kisten og hent disse reagenser, <Name>. Hent dem og bring dem til mig.", p="Har du troldmandens reagenser, <Name>?", c="Ah, du fandt dem! Med dem kan troldmændene i Underverdensgarden fortsætte deres arbejde. Jeg ved ikke, hvad de laver, men det er forbundet med Den Mørke Portal i Det Sønderrevne Land, og det er vitalt for Alliancens sikkerhed."},
  [1422] = {n="Trussel fra havet", l="Tal med Kadar i Sorgernes Sump.", d="Mens jeg begynder på dit våben, hvorfor så ikke tale med Kadar? Han nævnte, at han havde brug for hjælp til patruljerne langs stranden, og jeg vil hellere se dig holde hovedet koldt og våbnene klar, end at du drikker dig fuld sammen med nogle af de andre lopper, jeg deler denne lejr med.", c="Vær stille et øjeblik, <Class>. Selv over havets dumpe brøl kan du stadig høre de modbydelige gurglelyde fra fiskemændene."},
  [1424] = {n="Tårernes Pyt", l="Fel'zerøl i Stenard vil have dig til at samle 10 Atal'aj-artefakter.", d="Krigshøvdingen sendte os for at undersøge mærkelige hændelser ved Det Sunkne Tempel.\n\nAtal'aj-trolderne er en stamme af mørke magikere, kendt for at praktisere forbudt magi. Du kan forestille dig, hvor forbavsede vi blev, da vi kom hertil og opdagede, at templet var sunket.\n\nDe grønne drager vagter nu stedet og påstår, at de er Azerots beskyttere.\n\nVi må finde ud af, hvad der skete. Udforsk området omkring Tårernes Pyt og saml Atal'aj-artefakter. Ud fra dem kan jeg begynde at samle brikkerne i dette puslespil.", p="Ingen ved, hvilke mørke praksisser der foregik inde i Det Sunkne Tempel. Men vi ved, at der blev brugt stor og mægtig magi.\n\nVi må lære så meget om sådan magi, som vi kan. Måske vil Atal'aj-trollenes besværgelser vise sig nyttige for Horden.\n\nNår du har samlet nok Atal'aj-artefakter fra omkring Tårernes Pyt, kan jeg begynde at forstå, hvad trollene håbede at opnå, og hvad der gik så frygteligt galt.", c="Din flid med at samle Atal'aj-artefakterne er værd at rose, <Class>."},
  [1425] = {n="Lever forsendelsen", l="Bring forsendelsen til Nethergarde til Kvartermester Lungerts i Underverdensgarden Fæstning.", d="Mens jeg reparerer denne vogn, <Name>, har jeg én sidste opgave til dig.\n\nJeg har pakket de vigtigste forsyninger, der blev reddet fra ogrernes angreb. Tag dem med til Underverdensgarden Fæstning. Fæstningen ligger i de nordlige bakker i Det Sønderrevne Land og holder øje med Den Mørke Portal.\n\nFor at nå Underverdensgarden skal du følge vejen mod øst. Når den forgrener sig, skal du gå mod syd ind i Det Sønderrevne Land og derefter dreje til venstre ved næste vejkryds. Følg vejen, <Name>, og vær på vagt.", p="Har du noget at ordne med mig?", c="Hvad? En pakke fra Bigges karavane? Vi troede, at både den og ham var tabt.\n\nTak, <Name>. Forhåbentlig vil disse forsyninger bringe det stærkt tiltrængte reagens, Azoran-krystaller. Vores lager er ved at være tomt..."},
  [1426] = {n="Trussel fra havet", l="Dræb 10 Sumpmudderfisk, 10 Sumpblækspyder og 10 Sumpkødædere, og vend derefter tilbage til Kadar i Sorgernes Sump.", d="Jeg har ingen kærlighed til havet, ej heller til nogen skabning, jeg har set komme fra dets dybder. Det er en mægtig, men blind herskerinde; kynisk og brutal. Det ville give mig stor glæde at slagte fiskemændene med hundredvis, hvis det stod i min magt. Men jeg nyder en vis tilfredsstillelse ved at se dem dø for hænderne på dem, der gør Hordens vilje.\n\nHvilket bringer os til dig, <Class>. Hvor mange kan du slagte? Vil du måle dig med deres stærkeste slags?", p="Jeg er tålmodig. Tålmodig og evig som en gammel kank-sten fra Draenør. Fiskemændene skal ikke komme forbi vores grænser--ikke mens jeg stadig står. Havde vi en hær til rådighed, ville jeg rense denne verden og alle andre for deres tilstedeværelse. Jeg føler mit had syde, bare ved at tale om dem.", c="Havet virker vidstrakt og ubarmhjertigt, men du har plettet hende med blodet fra hendes egne afkom. Fiskemændene kender smerte. Deres dumhed vil tvinge dem til at genopbygge deres rækker efter ødelæggelsen, du har forårsaget, og det er godt.\n\nLad deres gurglende skrig overdøve havets brøl langt ud i natten. Jeg vil smile, hver gang jeg hører en af dem blive tavs.\n\nVend tilbage til mig, hvis du vil slå flere af fiskemændene ihjel. Jeg vil gerne belønne dig igen."},
  [1427] = {n="Trussel fra havet", l="Tal med Tok'Kær i Sorgernes Sump.", d="Før du hviler dig, så tal med Tok'Kær igen. Mens du var væk, tror jeg, han blev færdig med et par våben. Som tak for din hjælp her vil han tilbyde dig et af dem. Du gør klogt i at teste dets styrke mod fiskemændene, når du er klar... men kun for at behage mig yderligere.", c="Ah, <Name>, du er vendt tilbage. Godt. Jeg er færdig med at smede flere våben til vores kamp mod mudderfiskene. Som tak for at bringe os frisk savtandkød, og for at få et lille smil frem på Kadars ansigt, tilbyder jeg dig et af dem."},
  [1428] = {n="Vedvarende trussel", l="Dræb 10 Sumpblækspyder, 10 Sumpkødædere og 10 Sumporakler, og vend derefter tilbage til Kadar i Sorgernes Sump.", d="Det glæder mig at se, at dit had til fiskemændene vokser i takt med mit.\n\nFind flere af deres slags langs stranden, og når du har fået nok af kamp, så vend tilbage til mig. Vi taler så om en belønning for din flid.", p="Først når havet og alle dets børn er tavse, vil jeg være tilfreds... især de modbydelige fiskemænd.", c="Godt gjort, <Class>. Jeg kræver mere af deres blod. Lad alle fiskemænd gå til grunde."},
  [1429] = {n="Den forviste Atal'aj", l="Bring Bundtet med Atal'aj-artefakter til den forviste Atal'aj i Bagland.", d="Mens du var ude og trodsede farerne ved Tårernes Pyt, vendte en af mine spejdere tilbage med en rulle skrevet med blod på tørret kød. Det lader til at være en retslig dom over en præst fra Atal'aj-stammen.\n\nDenne præst blev dømt til en skæbne, der var værre end døden blandt Atal'aj.\n\nHan blev forvist til at leve langt mod nord i Bagland, sammen med Visnebark-trollene.\n\nJeg vil samle disse artefakter i et bundt. Du skal opsøge den forviste og finde ud af, hvad de virkelig bruges til. Vend tilbage til mig, når din rejse er fuldendt.", p="Du er modig at komme hertil. Modig eller tosset...", c="Bringer du mig Atal'ajernes kaldeartefakter?\n\nJeg ser, at Jammal'an Profeten fører disciplene fra Blodkammeret mod deres valgte skæbne. Mon Hakar er vendt tilbage til templet? Er deres skæbne nået?"},
  [1430] = {n="Frisk kød", l="Bring 10 Monstrøse Kryberben til Dår i Sorgernes Sump.", d="Der er stor efterspørgsel efter kryberkødets saftige smag blandt mine kunder; især kødet fra de monstrøse kryber.\n\nHvis du har planer om at tage til kysten, kunne jeg nemt gøre det umagen værd at bringe mig nogle af deres ben, som kan transporteres tilbage til Orgrimgrad.\n\nKysten ligger mod øst herfra, og du vil ikke have problemer med at finde væsnerne, der skvulper rundt langs stranden og under havet.", p="Jeg har en tønde vin, der venter på din succes, <Name>. Det er kun rimeligt, at jeg smager varerne, før jeg sender dem til mine kunder.", c="Ah, det her bør være perfekt. Jeg kan ikke vente med at smage dem, efter de er tilberedt ordentligt over et åbent bål. Du bør tage en prøve med dig på din rejse. Det er virkelig lækkert."},
  [1436] = {n="Alliancens relationer", l="Tal med Keldrun i Orgrimgrad.", d="Kampen går godt, <Name>. Måske vil Krigshøvdingen lade os vende hjem, før årstiderne skifter, hvis vi fortsætter med at gøre så store fremskridt i vores kamp mod dæmonerne og deres undersåtter.\n\nVend tilbage til Keldrun og fortæl ham, hvad vi har gjort. Jeg er sikker på, at han vil belønne dig for din indsats her. Hans sag betyder meget for ham, og han vil være stolt over at vide, at Krigshøvdingen respekterer hans bekymringer.", c="Du er vendt tilbage fra Forødelse mere end succesfuld, <Name>. Tak.\n\nTak for din indsats, din tid og din forståelse for min anmodning. Trall forstår og ønsker fred mellem Horden og Alliancen, og ved at tage skridt til at sikre, at vores udseende er acceptabelt, vil vi ikke provokere yderligere unødvendig vold.\n\nJeg står i gæld til dig."},
  [1437] = {n="Vahlarriels eftersøgning", l="Find og undersøg Tyranis' og Dalinda Malems vogn i Forødelse.", d="Jeg er Vahlarriel, <Name>. Jeg er kommet hertil for at finde ud af, hvor to savnede adelige fra en darnassisk købmandsfamilie--Huset Malem--befinder sig. Familiens overhoved frygter det værste, og det er min opgave at gøre alt for at finde hans savnede børn. Jeg har endnu ikke påbegyndt min eftersøgning efter Tyranis eller Dalinda, men jeg håber, at jeg ikke bliver her længe.\n\nDet seneste ord fortalte om, at de passerede Stenklo-bjergene for et par uger siden.\n\nHvis du finder deres vogn, så kom venligst straks og find mig.", c="Mens du roder rundt i vognens rester, bliver det tydeligt, at den var blevet angrebet både med besværgelser og våben. Kampen virkede ensidig og hurtig; der er intet blod at finde og ingen rester af kroppe.\n\nDen, der angreb vognen, var effektiv og hurtig."},
  [1438] = {n="Vahlarriels eftersøgning", l="Find Dalinda Malem i Forødelse.", d="Find både Dalinda og Tyranis, hvis du kan, og kom tilbage til mig med dine fund. Start din eftersøgning ved denne fæstning. Jeg vil straks kontakte mine overordnede i Darnassos og lade dem vide, hvordan situationen er.\n\n<Name>, der er en anden ting, jeg vil have dig til at forstå. Mine overordnede har vist en vis bekymring over Tyranis' og hans motiver for at komme hertil. Det er vigtigere for dem, at Dalinda bliver fundet og bragt sikkert hjem. Tyranis skal... vurderes, før han bliver taget med hjem.", c="Tak Elunie, nogen er endelig kommet for at hjælpe. Vær venlig, <Class>, jeg har brug for din hjælp. Min bror Tyranis og jeg blev taget til fange og bragt hertil af Brændende Klinge. Jeg tror, de har tænkt sig at ofre mig til deres dæmonherrer!\n\nJeg vidste, at det var en fejl at komme til Forødelse, men Tyranis har for nylig begyndt at tørste efter viden om alt arkant--selv imod vores folks ønsker. Han besluttede at tage denne rejse, selv efter at have hørt historierne om dette lands dæmoniske plage.\n\nJeg frygter det værste for ham."},
  [1439] = {n="Eftersøgningen efter Tyranis", l="Find Tyranis Malem i Forødelse.", d="Vi blev bragt hertil, efter orkerne havde slagtet alle vores vagter og tjenere. Åh, de forfærdelige ting, de gjorde ved dem! Jeg troede helt sikkert, at de ville dræbe os på stedet, men det blev hurtigt tydeligt, at de havde andre planer.\n\nTyranis forsøgte at tale med dem. Jeg tror, han ville imponere dem med sin viden om det arkane... Jeg er ikke sikker på, hvorfor.\n\nVær venlig, jeg kan ikke forlade dette sted, før jeg ved, hvad der er sket med min bror. Find ham, og kom så tilbage efter mig, når hans skæbne er kendt.", p="Jeg frygter, at Tyranis vil forsøge at lære Brændende Klinges hemmeligheder og regne sig selv blandt deres slags, hvis de tillader det--han har altid elsket den magt, magi giver dem, der lader sig forføre af den.\n\nJeg er ikke sikker på, at jeg kunne holde ud at vende hjem til min familie med nyheder om Tyranis' sjæl, der flirter med sådanne farer. Det er forbrydelse nok blandt mit folk at søge sådanne ting, men at blive det, vi forsøger at beskytte os selv mod, ja, det er uacceptabelt.", c="Det er forfærdeligt! Men jeg antager, at det var nødvendigt. Hvis det ikke var din hånd, ville det helt sikkert have været mit folks. Jeg antager, at jeg bør takke dig--tilgiv mig, hvis det ikke virker oprigtigt. Jeg mener ingen krænkelse.\n\nMed kendskabet til min brors skæbne i hånden synes tiden til min flugt at være kommet. Hvis du stadig er villig, vil jeg modtage din hjælp til at flygte fra dette forfærdelige sted.\n\nNår du er klar, kan vi finde vej til sikkerheden."},
  [1440] = {n="Tilbage til Vahlarriel", l="Eskorter Dalinda Malem fra Tordenøkse-fæstningen og vend derefter tilbage til Vahlarriel Dæmonbaneren i Forødelse.", d="Så tiden er nu? Jeg sætter pris på din indsats, og hvis situationen ikke tillader det, så lad mig takke dig nu for alt, du har gjort for mig og min familie. Hvis du er klar, er der intet andet for mig her--vi kan tage af sted, når du mener, tiden er den rette.", c="Tak, <Name>. Dalinda kom sikkert tilbage hertil til Nijels Punkt, og i langt bedre form, end jeg havde turdet håbe på. Det, at hun ankom her på egen hånd, var et godt tegn. Jeg håber, du har det godt?\n\nDet smerter mig at vide, at hverken Tyranis eller Dalinda vendte tilbage, men flovheden over Tyranis' beslutninger er hendes at bære. Det er noget, hun må håndtere, når hun vender tilbage til Darnassos."},
  [1444] = {n="Tilbage til Fel'zerøl", l="Vend tilbage til Fel'zerøl i Stenard.", d="Jammal'an Profeten dømte mig til forvisning fra Det Sunkne Tempel. Jeg følte engang, at ypperstepræsten var en værdig leder.\n\nHans ubøjelige tro på hans profeti vil føre til Atal'ajernes undergang. Hvis det ikke allerede er sket.\n\nDa jeg udtrykte mine bekymringer, blev jeg kaldt en vantro og smidt ud af templet.\n\nDe artefakter, du bragte mig, er harmløse. Men hvis Jammal'an har fundet den rette fetisch-fortryllelse til kalderitualet, ligger verden i stor fare....", c="Det er gået lang tid, siden vi talte sammen, <Class>. Jeg håber, din rejse var en succes.\n\nHvilken viden fik du fra de forviste Atal'aj i Bagland?"},
  [1445] = {n="Det Sunkne Tempel", l="Saml 20 Hakars fetisher og bring dem til Fel'zerøl i Stenard.", d="Så han talte om Jammal'ans profeti?\n\nÅndslederen for Atal'aj-stammen tror, at når Hakar vender tilbage til Azerot fra Nether, vil guden give Atal'aj-stammen udødelighed.\n\nDumt bedrageri, der skal fremskynde en for tidlig dommedag, hvis du spørger mig.\n\nMen du siger, at den forviste talte om fortryllede fetisher? Det bekymrer mig meget. Hvis disse virkelig er nøglen til Atal'aj-ritualet, der forårsagede dette rod, må vi forstå deres iboende kræfter.\n\nBegiv dig ind i Templet, og tag fetisherne!", p="Hvis Atal'aj-fetisherne rummer kraften til at kalde Hakar og opfylde Jammal'ans profeti, skal de tages. Sådanne kræfter må Horden forstå!", c="Modige <Class>, du har vist dig selv at være en stor mester for Horden.\n\nNu skal denne samling af Hakars fetisher håndteres med det samme!"},
  [1446] = {n="Jammal'an Profeten", l="Den forviste Atal'aj i Bagland vil have Jammal'ans hoved.", d="Mine Visnebark-kammerater tager ikke pænt imod fremmede omkring deres hjem.\n\nMig? Jeg har ikke noget hjem mere. Jeg blev forvist fra mit folk, den store Atal'aj-stamme i Sorgernes Sump.\n\nVores åndelige leder, Jammal'an, havde det, han kaldte en profeti. Han tror, at kaldelsen af guden Hakar vil give Atal'aj udødelighed.\n\nMen jeg opfordrede til forsigtighed. Hvad nu, hvis profetien ikke var andet end manipulation?\n\nJeg ønsker hævn for min forvisning. Bring mig Jammal'ans hoved. Måske vil mit folk så blive frie.", p="Når Jammal'an er fjernet, har jeg en chance for at vende tilbage til mit folk.\n\nMed Jammal'an som deres åndelige leder står Atal'aj over for sikker undergang.", c="Jammal'ans hensynsløse tillid til falske visioner førte mit folk til deres evige undergang.\n\nJeg takker dig, <Class>, for at hævne min forvisning. Jeg sørger over mit folk. Jeg har intet hjem at vende tilbage til."},
  [1448] = {n="På jagt efter Tempelet", l="Brohann Tøndemave i Stormvind vil have dig til at lede efter Det Sunkne Tempel.", d="Der var en tid, hvor jeg var ung og fuld af kraft ligesom dig, <Class>.\n\nMen nu er jeg gammel og ude af stand til at udforske verden, som jeg engang gjorde. Åh, de ting, jeg så!\n\nMen der var ét mysterium, der undslap mig. Til min sidste opgave sendte Opdagelsesrejsende-Ligaen mig ud for at lede efter Det Sunkne Tempel. Det rygtedes, at det lå i Sorgernes Sump.\n\nPå grund af min skrøbelige tilstand rejste jeg over himlen på en gryfon for at finde det, men fandt det aldrig.\n\nVil du hjælpe en gammel dværg? Måske har du bedre held til fods.", p="Jeg har rejst verden rundt, fra Azerots jungler til Khaz Mødans snedækkede tinder.\n\nAldrig før har jeg bedt om hjælp på mine eventyr. Men mine gamle knogler er trætte.\n\nIntet ville efterlade mig mere tilfreds end at vide, at jeg har fuldført min sidste opgave for Opdagelsesrejsende-Ligaen\n\nHvis du vil være så venlig at hjælpe mig med at lede efter Det Sunkne Tempel, <Class>, ville jeg sætte stor pris på det.\n\nGennemsøg Sorgernes Sump og rapporter tilbage med dine fund!", c="Det Sunkne Tempel er sunket under Tårernes Pyt? Og er omringet af den grønne drageflugt?\n\nEn fantastisk opdagelse, <Class>. Men der er tydeligvis gået noget frygteligt galt."},
  [1449] = {n="Til Bagland", l="Tal med Højthane Falstad Vildhammer ved Ørnerede-toppen i Bagland.", d="Som jeg nævnte tidligere, forsøgte jeg at spejde tempelet på egen hånd fra luften. Nå, jeg var ikke helt alene.\n\nJeg rejste til det berømte gryfonvolie ved Ørnerede-toppen i Bagland. Der hvervede jeg hjælp fra en af deres fineste flyvere. Flyveren faldt af sit ridedyr, ned i sumpen...\n\nI min høje alder undslipper den stakkels fyrs navn mig. Mesteren for volieren vil nok huske det.\n\nRejs derhen og søg Falstad Vildhammer.\n\nVi må finde ud af, hvad der skete med den flyver.", c="Hvad vil du, lille ven? Kan du ikke se, at jeg har problemer, der skal tages hånd om her? Hvem har tid til at stå og pludre med en <Race>-ladderkæft?\n\nDer kommer trolde ud af alle revner! Skynd dig."},
  [1450] = {n="Gryfonmester Talonøkse", l="Tal med Gryfonmester Talonøkse inde i Ørnerede-toppens volie.", d="Så du er en fornemmet ærindedreng for en gammel Opdagelsesrejsende-Liga-kujon, hva'?\n\nNå, hør efter, <Class>. Jeg ved ikke, hvem din gamle ven fløj rundt med nede på Azerot. Ligner jeg Gryfonmester Talonøkse for dig? Gør jeg?\n\nHvis du er så interesseret i flyveopgaverne, hvorfor spørger du så ikke gryfonmesteren? Hvis jeg fanger dig i at drive rundt her meget længere, sætter jeg dig til at lave noget rigtigt arbejde.\n\nNu skal du komme i gang.", c="Ah, ja. Selvfølgelig husker jeg, at jeg sendte en af mine gryfonryttere for at give Brohann Tøndemave en hjælpende hånd.\n\nJeg har altid haft en blød plet i hjertet for Opdagelsesrejsende-Ligaen. Min far hjalp faktisk med det første udgravningshold, der opdagede Uldaman.\n\nJeg sendte den, jeg dengang troede var min bedste gryfonrytter, med Brohann. Han var en karl ved navn Rhapsody Hyggemand.\n\nOg for en gryfonjockey han var! Indtil..."},
  [1451] = {n="Rhapsody Hyggemand", l="Søg efter Rhapsody Hyggemand i Bagland.", d="Rhapsody kastede sig ret begejstret over spiritus. Nu må du ikke misforstå--alle os dværge oppe ved volien elsker en god øl, når tiden er den rette.\n\nMen gamle Hyggemand tog til sprutten, ligesom en gryfon tager til himlen. Og det var også en forbandet skam. Ingen kunne flyve som Rhapsody.\n\nDet første tegn på problemer var, da han kom snublende tilbage fra den mission med din ven, Brohann. Alt gik hurtigt ned ad bakke derfra. Vi måtte lade ham gå.\n\nSidst jeg hørte, har han slået en bryggerlejr op øst herfor...", c="Hik!\n\nJeg kigger lige på dig, men du bliver ved med at hoppe op og ned. Det gør mig svimmel. Hoho!\n\nHik!\n\nVuha! Mærkede du det? Jorden ryster, min ven. Jeg har brug for en drink.\n\nHik!"},
  [1452] = {n="Rhapsodys Kalimdør-kokteil", l="Rhapsody Hyggemand i Bagland vil have dig til at bringe ham 3 Rok-muskelmaver, 3 Grødoc-lever og 3 Jernpels-lever.", d="Hik!\n\nSå den skøre tosse Brohann sendte dig? Vi havde sgu da et eventyr... Hik!\n\nHvis du vil have mig til at fortælle, hvad der skete nede i sumpen, så har jeg brug for noget stærkt at drikke. Det var ikke et pænt syn, ser du. Hik!\n\nJeg siger dig hvad... bring mig det, jeg har brug for til at piske en Kalimdør-kokteil, så fortæller jeg dig alt om det.\n\nJeg skal bruge nogle Rok-muskelmaver fra Tanaris... og lad mig se... nogle Grødoc- og Jernpels-lever fra Vildalas...\n\nEn dejlig stærk Kalimdør-kokteil... det får mig til at snakke!", p="Har du nogensinde smagt en Rapsodi-malt? En af mine fineste bryg, hvis jeg selv siger det. Hik!\n\nMen hvis jeg skal genopleve gruerne fra den skæbnesvangre flyvetur over... hik... sumpen, så har jeg brug for noget lidt stærkere. Hik!\n\nJeg antager, at du ikke fandt de muskelmaver og lever, jeg har brug for, for at tilføre min Kalimdør-kokteil det ekstra gift?\n\nHik!", c="Jeg kan se, du ikke havde det mindste besvær med at skaffe mig det, jeg har brug for! Det må have været en ordentlig omgang, du havde derovre i det fjerne Kalimdør.\n\nDet vil ikke tage længere end et øjeblik at udtrække det, jeg har brug for, fra disse muskelmaver og lever. Hik!\n\nSå kan jeg destillere en gal gammel drik og endelig fortælle dig, hvad du vil vide.\n\nHik!\n\nJeg får gåsehud bare af at tænke på den gamle sump.\n\nHik!\n\nLad mig blande en drink hurtigt."},
  [1454] = {n="Karnitols skibsvrag", l="Find Karnitols kiste i Forødelse.", d="Min første opgave drejer sig om magikeren Karnitol--en slags adelsmand i Stormvind. Hans skib blev angrebet af havgiganter, mens det lå ud for kysten i det nordvestlige Forødelse. Han og hans tjenere forsøgte at bringe en af hans mest værdifulde kister i land, men da havgiganterne angreb i mængder, valgte han at efterlade den og teleportere sig selv og sine tjenere til sikkerhed.\n\nHan ønsker, at vi finder kisten og dens indhold og bringer det tilbage til ham i Stormvind.", c="Du bemærker, at kisten ikke ser ud til at have nogen vandskader.\n\nDen anden ting, du bemærker, er, at låget er blevet brudt op, og de magiske fælder, der var sat for at beskytte den, er for længst udløst--det er tydeligt af brændemærkerne langs kanterne."},
  [1455] = {n="Karnitols Skibsvrag", l="Vend tilbage til Kreldig Ungør i Forødelse.", d="Du bruger et øjeblik på at finde ud af, hvad der har revet kisten op, og du bemærker langs siderne og toppen af kisten lange, dybe ridser, der afslører, at noget andet end et menneske eller en kæmpe har haft interesse i den. Mærkerne ser ikke ud til at være lavet af en dolk eller et sværd.\n\nEfter at have gennemsøgt kisten finder du ud af, at den er fuldstændig tom.\n\nDa du ikke har nogen anden plan, lukker du kisten og gør dig klar til at gå. Kreldig vil blive skuffet.", c="Velkommen tilbage til Nijels Punkt, <Name>. Så, fortæl mig, hvad du fandt.\n\nHvad!? Ingenting? En tom kiste får os ikke betalt, er jeg bange for.\n\nFortæl mig mere om de mærker, du så... de ridser."},
  [1456] = {n="Karnitols Skibsvrag", l="Find Karnitols taske og bring den tilbage til Kreldig Ungør i Forødelse.", d="Spændende.\n\nNå, vi er måske ikke helt uden håb endnu.\n\nLangs samme kyst, men længere mod nord ved Ranazjar-øen, ligger nattenisse-ruiner på havbunden. En stamme af slangefolk, Snigeklingerne, har gjort dem til deres hjem. Jeg tror, det er vores bedste chance.\n\nHvis en speiderpatrulje var så langt sydpå, må de have været ret magtfulde. Hvis du vil finde Karnitols ejendele, ville jeg starte med de mere magtfulde slangefolk: tidevandsjægerne eller havhekse.", p="Ikke fornærmelse mod Nijel, hvem end han er, men denne lejr er ikke det mest komfortable sted, jeg har tilbragt en nat, hvis du forstår mig, <Name>.", c="Det er fantastisk, <Name>! Du fandt Karnitols ejendele!\n\nDe forbandede slangefolk, altid til besvær. Jeg tror, jeg hellere ville tilbringe mit liv i krig med Horden end skulle gå op imod deres slags. Du har gjort en stor tjeneste for Genvinderne."},
  [1457] = {n="Karnitols Skibsvrag", l="Bring Karnitols taske til Roetten Stenhammer i Jernsmede.", d="Tag Karnitols ting tilbage til Roetten i Jernsmede, så betaler han dig for et veludført stykke arbejde.\n\nHaha, hvis du ikke er forsigtig, bliver han så glad for dig, at han beder dig slutte dig til os på fuld tid.\n\nIgen, flot arbejde, <Name>.\n\nVær forsigtig på vej tilbage, og tag ikke for lang tid – Karnitol er ikke den mest tålmodige mand, men han er meget gavmild alligevel.", p="Forretningerne går strygende, <Name>, og jeg har ikke meget tid til spørgsmål. Hvis du har ærinde hos Genvinderne, så lad os høre det. Hvis ikke, må jeg bede dig tale med en af mine underordnede – de er dygtige nok til at klare tingene her omkring.", c="Ah, Karnitol-sagen i Forødelse. Fremragende!\n\nAltså, kisten blev ødelagt, men tingene er her alle sammen, hva'? Nå, jeg lader ham afgøre det. En god ting ved denne forretning, jeg har kørende her, er, at hvis de ikke er tilfredse, kan jeg bare sige, at de kan rende mig! De stoler på, at vi finder deres ting... ikke på, at vi sørger for, at alt er pænt og i god stand, når de får det tilbage.\n\nGodt arbejde, <Name>. Lad os se til, at du bliver betalt."},
  [1458] = {n="Reagenser til Genvinderne A/S", l="Bring 10 Hadfuror-klør og 10 Hadfuror-horn til Kreldig Ungør i Forødelse.", d="En af mine opgaver herude går ud på at hente nogle reagenser til Venstrekvik, en gnom-magiker i Kharanøs. Roetten synes, det er let tjent i banken, eftersom vi alligevel er herude. Han er ligeglad med, at vi er underbemandede.\n\nDe første par ting på hans liste burde være lette nok at skaffe, og det ville være en god sum penge for enhver, der hjælper mig.\n\nJeg har brug for nogle horn og klør fra Hadfuror-satyrerne øst for her. Bring dem tilbage til mig, så går vi i gang med resten af listen.", p="Foragtelige væsener, satyrerne. Historien siger, at de på en eller anden måde er forbundet med nattealferne, men jeg er ikke så sikker på, at jeg tror på det.\n\nJeg tror, de har fået det på grund af den ene alf, der bragte dem med i krigen for få år siden. Verden har aldrig været den samme siden. Meget farligere, og meget mere skræmmende.", c="Godt, godt, <Name>. Jeg er ikke sikker på, om de er af god kvalitet, men hvis Venstrekvik ville have en bestemt type, skulle han have specificeret det, før han sendte Genvinderne herud i første omgang.\n\nHvad siger du til at gå videre til den næste ting på hans liste?"},
  [1459] = {n="Reagenser til Genvinderne A/S", l="Bring 7 hætteglas Skorpashi-gift og 3 Gammel Kodo-huder til Kreldig Ungør i Forødelse.", d="Næste på Venstrekviks liste er... lad os se... hmm. Åh, der er den.\n\nSimpelt nok, men ret eksplicit i hans anvisninger. Han har brug for gift fra skorpashierne og hud fra nogle kodo'er. Det fine print siger, at begge skal komme fra bestemte skabninger: giften skal komme fra en hvilken som helst af skorpashierne, og huden skal komme fra en gammel kodo, ikke de døende eller ældgamle.\n\nMagikere, siger jeg dig, nogle af de ting, de vil have... det er bare underligt.", p="Undskyld, at jeg ikke kunne fortælle dig, hvor man finder kodoen eller skorpashierne. Jeg kender ikke området særlig godt, og jeg har ikke haft tid til at udforske det.", c="Din hjælp her er en gave, <Name>. Du halverer i det mindste min tid her i Forødelse. Jeg vil være tilbage i Jernsmede og varme mine fødder på et øjeblik med din hjælp.\n\nNår vi får denne liste klaret, og jeg er hjemme igen, så opsøg mig, så køber jeg helt sikkert en øl til dig.\n\nMen indtil da, lad os få samlet de resterende reagenser."},
  [1465] = {n="Vahlarriels Eftersøgning", l="Returner Malem-vedhænget til Vahlarriel Dæmonbane i Forødelse.", d="Mens du fortsætter din eftersøgning af vognen, finder du ikke kun et vedhæng, men også fodspor, der fører mod syd. I det fjerne kan du se røg stige op fra et stort fort. Røgen stammer fra et holdt ild, ikke fra brændende bygninger, og din intuition fortæller dig, at Malemerne, hvis de stadig er i live, blev ført i den retning.\n\nDu synes, at Vahlarriel i Nijels Punkt ikke blot bør se det vedhæng, du har fundet, men også få at vide om tegnene på liv mod syd.", c="Rasende! Hele denne fiasko!\n\nDe to blev advaret om, hvor farligt det ville være at komme her. Nu er de begge savnet... eller værre.\n\nSiger du, at du så spor, der førte mod et fort i nærheden? Det er måske vores bedste chance.\n\nUd fra, hvad lokalbefolkningen har sagt, er fæstningen besat af medlemmer af Brændende Klinge--orker, som har viet sig til dæmoniske formål. De repræsenterer måske ikke flertallet af Hordens overbevisninger, men de er onde og vil slagte dig på stedet, hvis du bliver taget som spion."},
  [1466] = {n="Reagenser til Genvinderne A/S", l="Bring 10 Ondhund-hjerner, 10 Tomrumsvinger og 10 hætteglas Domvogter-blod til Kreldig Ungør i Forødelse.", d="Dette er den sidste af tingene, og jeg lyver ikke, det er ikke pænt. Jeg forventer også, at det tager dig lidt længere end de andre ting.\n\nSå, nok med advarslerne, lad os komme i gang. Venstrekvik siger, at han har brug for ti hjerner fra enten manaædere, magijægere eller liniejægere. Ti tomrumsvinger fra en tomrumsjomfru, søster eller troldkvinde. Og... ti hætteglas Domvogter-blod fra en domvogter-kaptajn eller -herre.\n\nSimpelt nok, ikke? Puha... hvis du vil give slip på denne, ville jeg forstå det.", p="Jeg var ikke engang klar over, at disse dæmon-ting fandtes i Forødelse. Sidst jeg læste, havde kentaurerne stort set ejet landet, efter nattealferne tog af sted for år tilbage.\n\nJeg undrer mig over, hvorfor de slog sig ned her, og hvordan.", c="Ærligt talt? Det havde jeg ikke troet. Du er fantastisk, <Name>. At tage kampen op med dæmoner til en magikers eksperimenter, og komme tilbage i ét stykke oveni. Godt gået!\n\nJeg vil personligt fortælle Roetten om dig, når jeg kommer tilbage til Jernsmede."},
  [1467] = {n="Reagenser til Genvinderne A/S", l="Bring Venstrekviks pakke tilbage til Roetten Stenhammer i Jernsmede.", d="For at få betaling, må du tilbage til Jernsmede og tale med Roetten selv. Han vil elske at få Venstrekviks pakke ud af vejen alligevel. Giv ham bare denne, så burde den være nok til at få din skat.\n\nOg bare rolig, jeg vil stadig sige et godt ord for dig, når jeg kommer tilbage. Jeg burde ikke være i Forødelse meget længere.", p="Velkommen, <Name>. Forretningerne går strygende, lyden af ambolte, der bliver slået, runger gennem hele Jernsmede, blæsebælgene blæser ilden hed, og min kone bager en tærte til mig til dessert efter aftenens middag. Kunne livet være bedre?", c="Ah, pakken til Venstrekvik fra Forødelse. Fremragende. Jeg sætter pris på arbejdet og din punktlighed, <Class>. Dejligt at have dig med om bord, i det mindste til denne lille opgave.\n\nJeg har din betaling lige her. Lad det være kendt, at Genvinderne A/S altid betaler godt for en hård uges arbejde."},
  [1468] = {n="Børnenes Uge", l="Brug Menneskelige Forældreløsfløjte til at tale med barnet, du skal passe under Børnenes Uge.", d="Du vil gerne hjælpe os her på børnehjemmet? Velsign dig, ven; din hjælp under Børnenes Uge vil være uvurderlig.\n\nTag denne fløjte. Du kan kun bruge den i kort tid - typisk ikke længere end selve Børnenes Uge. Når du bruger den, kan du tale med barnet, du har sagt ja til at passe. Brug den igen, og barnet bliver sendt væk.\n\nBrug endelig fløjten, <Name>, og mød dit plejebarn! Jeg er sikker på, at barnet er meget ivrigt efter at møde dig.", c="Øh... hej. Jeg hedder Randis, og jeg gætter på, at du passer mig? Du er en eventyrer, ligesom min mor og far var. Jeg er glad for at møde dig.\n\nJeg håber, vi får en masse sjov sammen. Jeg har nogle ting, jeg gerne vil lave, og matronen siger, at du bliver som en storebror for mig i løbet af ugen. Det ville jeg kunne lide helt vildt, ja, det ville jeg."},
  [1469] = {n="Rhapsodys Fortælling", l="Bring Atal'ai-tavlefragmentet til Brohann Tøndemave i Stormvind.", d="Før flyvningen drak jeg mig en hel tønde stout. Hik!\n\nOg hvilken flyvning det var. Suste rundt med Brohann i hælene på mig. Så ingen tempel dog. Hik!\n\nNå, jeg så ikke noget tempel, før jeg blev lidt for beruset og faldt af mit ridedyr. Jeg styrtede lige i vandet og blev suget ned. Befandt mig omringet af en flok uhyggelige trolde. Jeg svømmede da hurtigt væk derfra! Stak endda af med dette trolde-souvenir. Her, tag det med til Brohann, og lad ham vide, at hans tempel er dernede, ja da. Hik!", p="Endelig er du tilbage, <Name>. Det er gået ret lang tid, siden vi sidst talte sammen. Jeg troede måske, du havde glemt min opgave.\n\nFandt du den snedige gryfferytter? Havde han noget at melde?", c="Rhapsody Festlig! Det er rigtigt... hvordan kunne jeg glemme sådan et navn?\n\nSå han vidste om templets synkning hele tiden? Nå, det ville helt bestemt have sparet dig for noget benarbejde.\n\nMen denne Atal'ai-artefakt! Ja, det er da et stort fund!"},
  [1472] = {n="Sjælenes Sluger", l="Tal med Godrick Farsøn i Den Fordømtes Tempel.", d="En sukkubus er en sjælesluger, hjertenes ødelægger, fristeren af mænd. En skabning af dyb ondskab og enkeltsindet tankegang.\n\nDen kan ikke bringes ind i vores verden uden en stimulus.\n\nDerfor bruger vi dens egen styrke imod den. Med de gode mænds, de rene mænds, de kærlige mænds hjerter vil sukkubussen ikke kunne modstå og krydse over til vores verden. Så kan du dominere den og gøre den til din egen.\n\nTal med min assistent, Godrick Farsøn, i Templet. Han vil hjælpe dig med at finde dit lokkemiddel.", c="Du blev sendt af Carendin? <Name>, altså.\n\nTænk ikke lavt om mig, fordi mit syn er væk. Jeg ser ting, der ligger bagved nu, med en klarhed, jeg aldrig har kendt. Det, jeg engang troede var en forbandelse, er nu en gave."},
  [1474] = {n="Det Bindende", l="Brug de Rene Hjerter til at fremkalde og nedkæmpe en sukkubus, og returner derefter de Rene Hjerter til Carendin Halgaar i Magikvarteret i Underbyen.", d="Brug disse hjerter og besværg besværgelsescirklen for at åbne en dør, så sukkubussen kan komme igennem. Dine kræfter er større nu, og du får brug for dem alle for at besejre sukkubussen.\n\nVær på vagt over for dens charme, <Name>, mange et stærkt sind er blevet bundet til dens vilje. Når den er overvundet, vil sukkubussen blive returneret til tomrummet, og jeg vil lære dig besværgelsen til at fremkalde den på dit kommando.", p="Af kræfterne fra ud over tomrummet er sukkubussen en af de farligste, for de svage bliver lettest viklet om dens fingre.\n\nHusk det nu og i fremtiden.", c="Igen har du gjort det godt, <Name>. Det er gået ret lang tid, siden jeg har set en ung hekseklog med så meget potentiale som dig. Vær sikker på, at jeg vil fortsætte med at følge dine fremskridt og forberede og hjælpe dig i dine fremtidige prøvelser.\n\nLad mig nu vise dig fremkaldelsesbesværgelsen for din nyligt dominerede sukkubus."},
  [1475] = {n="Ind i Det Sunkne Tempel", l="Saml 10 Atal'ai-tavler til Brohann Tøndemave i Stormvind.", d="Ifølge legenden er Det Sunkne Tempel en hellig helligdom viet til den gamle gud Hakar Sjælefileren. Vedligeholdt af en ondskabsfuld stamme af trolde ved navn Atal'ai, siges templet at være uigennemtrængeligt.\n\nNu sunket under Tårernes Pyt er det endnu sværere at hente artefakter fra templet. Men det er netop det, jeg har brug for, at du gør, <Name>.\n\nHjælp mig ved at samle de intakte Atal'ai-tavler. Bring dem til mig, så vender jeg tilbage til Opdagelsesrejsende-Ligaen som en helt. Sammen skal vi dele æren.", p="Mens aftenen langsomt sænker sig over min karriere, henvender jeg mig til dig, <Name>, for at hjælpe mig i min sidste søgen efter Opdagelsesrejsende-Ligaen. Hvis mine gamle knogler kunne samle styrken til at trodse Sorgens Sump og det sunkne tempel, ville jeg kæmpe side om side med dig.\n\nStolthed gør det svært for mig at bede om din hjælp til at samle Atal'ai-tavlerne. Men alderdommen tvinger nødvendigheden frem.\n\nHjælp mig, <Name>. Jeg vil gerne trække mig fra Opdagelsesrejsende-Ligaen efter at have fuldført deres sidste ønske.", c="Atal'ai-tavlerne! Tak, <Name>!\n\nNår jeg har leveret dem til Opdagelsesrejsende-Ligaen, vil vores navne gå over i historien sammen. Du har hjulpet en gammel dværg med at opfylde sin sidste pligt i livet. For det er jeg evigt taknemmelig."},
  [1477] = {n="Vitale Forsyninger", l="Tal med Vagtmester Sorigal.", d="Vores magikere udfører forskning i Underverdensgarden i Det Sønderrevne Land, forskning der er vital for vores forståelse af Mørke Portaler. De har brug for næsten konstante forsyninger, men vores forsyningslinje til Underverdensgarden er skrøbelig.\n\nDu skal hjælpe med at sikre, at forsyningerne når frem til Underverdensgarden. Mød op hos Vagtmester Sorigal i Mørkeshire, og gør som han beder. Denne opgave vil føre dig ind i fjendtlige lande, <Name>. Gør dig klar.", c="Andromat sendte dig? Meget godt. Jeg har en vigtig opgave til dig..."},
  [1479] = {n="De Evigtes Gren", l="Tag den forældreløse til banken i Darnassos. Banken er selv udhulet fra et træ kendt som De Evigtes Gren.", d="Jeg har hørt historier om, hvordan nattealferne har deres bank i et træ - et der ligner en bjørn! Det er så fedt! Nattealferne er sjove, hvordan de elsker naturen og sådan noget, men bjørne er bare fuldstændig fantastiske!\n\nKunne du tage mig med for at se bjørnetræet i Darnassos, tak? Der er en båd, der kan tage os tæt på, og det burde ikke tage lang tid. Vær sød, vær sød, vær sød!", p="Er vi der snart?", c="Wow, det var endnu federe, end jeg overhovedet havde forestillet mig - De Evigtes Gren! Jeg troede ikke, det ville være så stort, men det var det! Så du fuglen oven på den også?! Jeg undrer mig over, hvordan de fik grenene til at se sådan ud!\n\nTak fordi du tog mig med til Darnassos, <Name>. Du er fantastisk!"},
  [1482] = {n="Fordærveren", l="Bring en Orakelkrystal til Maurin Knoglekløver i Forødelse.", d="En orakelkrystal ville gøre det fint. Den er fremstillet af slangefolkene, så deres orakler kan bruge den.\n\nNordvest for her, langs kysten, ligger et vidtstrakt koralrev, som slangefolkene har taget som deres hjem, når de er så tæt på kysten. Du kan finde deres orakler der. Snigeklingerne er dødbringende og vil ikke reagere venligt på dine indtrængen, så vær forsigtig og skynd dig.\n\nNår du vender tilbage, skal vi se, hvordan vi finder denne dæmonherre Azrethok.", p="Jeg venter på orakelkrystallen, <Class>. At finde og ødelægge denne Herre Azrethok ville vinde os begge en stor gunst hos Krigshøvdingen. Vi gør klogt i at arbejde sammen og gøre det hurtigt, så vi kan fremme vores egne mål og vinde Krigshøvdingens gunst.", c="En dyrebar orakelkrystal... fejlfri... smuk. Helt sikkert.\n\nVi går i gang med det samme. At finde denne dæmonherre bør være vores primære bekymring, og dens nedkæmpelse kræver al vores opmærksomhed.\n\nTræd et skridt tilbage, <Class>, og lad os se, hvad denne dæmon er, og hvor den kan findes."},
  [1484] = {n="Fordærveren", l="Tal med Takata Stålklinge i Forødelse.", d="Dette væsen er langt farligere, end jeg havde forventet. Uden tvivl sætter Takata spørgsmålstegn ved mine evner til at tage kampen op med sådan et væsen, og det ville fornærme hans ære, hvis han ikke blev informeret om, hvad der lige er sket.\n\nTal med sværdkæmperen, sig, at du er villig til at dræbe dæmonen, hvis han tillader det, men pres ikke for hårdt. Det er bedre, hvis han tror, det er hans egen idé.", c="Jeg så, hvad der netop skete med Maurin og dæmonherren. Det væsen ser ud til at have mere magt end min hekseklog-ledsager, selv som et spøgelse. Jeg undrer mig over, om han er op til opgaven med at besejre monsteret? Det ville tjene Krigshøvdingen bedre, hvis jeg selv gik, men med mine ansvar her ville jeg vanære min klan, hvis jeg vendte ryggen til mine pligter her for at kæmpe mod det onde for min egen ære."},
  [1488] = {n="Fordærveren", l="Dræb Herre Azrethok og Jugkar Dyster'rod og returner til Takata Stålklinge i Forødelse.", d="Selvom jeg ikke kender denne Herre Azrethok, er jeg enig med Maurin i, at han må stoppes; især hvis han forsøger at opnå indflydelse over Brændende Klinge for at fremme sine mål.\n\nDu har allerede vist, at du ønsker at hjælpe Krigshøvdingen, og jeg ville stole på dig til at samle en gruppe til at dræbe dæmonherren og hans hekseklog-tjener.\n\nNår du er klar, så gå direkte mod syd, og vend tilbage til mig, når truslen er ophørt.", p="Ære til Horden, og død over vores fjender, <Name>!\n\nDæmonerne i Forødelse udgør en større trussel end nogensinde før. Mit håb om at vende tilbage til Krigshøvdingen aftager, efterhånden som flere og flere af de skumle væsener ser ud til at dukke op.\n\nNogle gange ønsker jeg, at det kun var kentaurerne, vi skulle håndtere.", c="En mægtig sejr for os alle, <Name>. Lad os glæde os over din succes. Jeg tror nu, at vores fremtid her ikke er så dyster, som jeg engang troede.\n\nDæmonerne vil blive slået ihjel, Brændende Klinge vil fejle i deres bestræbelser, og vi kan en dag få et sted, vi trygt kan kalde hjem igen."},
  [1498] = {n="Forsvarets Vej", l="Bring 5 forkullede skæl til Uzzæk ved Fjernvagtsposten i Ødemarken.", d="Som kriger er en af vores vigtigste opgaver... beskyttelse. Vi er Hordens skjold, og vi holder vores svagere brødre i sikkerhed. Hvis du skal slutte dig til vores rækker, må du bevise din mod over for mig.\n\nGå til Tordenkammen i Durdotar, hvor lyn-huderne og torden-øglerne lever. Jag bæsterne! Vis mig, at du er sejere end dem! Tål deres angreb og bring mig en stak af deres forkullede skæl som bevis.\n\nGør dette, og så vil jeg lære dig.", p="Har du skællene, <Name>? Medmindre du kan modstå torden-øglernes angreb, vil du ikke få gavn af min undervisning.", c="Ah. Jeg ser, at du har besejret torden-øglerne, hvilket beviser, at du er sej. Nu vil jeg vise dig, hvordan hård hud og snedige bevægelser kan danne en uigennemtrængelig forsvarsmur.\n\nLær din lektie godt, <Name>. Og vær klar til fremtidig undervisning."},
  [1502] = {n="Thun'grim Ildblik", l="Tal med Thun'grim Ildblik i Ødemarken.", d="Det er vigtigt, at en krigers våben er af høj kvalitet. Og hvis der er en ork, der kan smede kvalitetsvåben, så er det Thun'grim Ildblik. Han er en eneboer, der bor på toppen af bakkerne øst for Korsvejen.\n\nHvis du søger et våben, kriger, så bør du søge Thun'grim. For at finde ham, rejs først til Korsvejen mod vest, og gå derefter mod øst ind i bakkerne. Hans lejr ligger højt på en bakketop.", c="Mine øjne er længe blevet tørre af at stirre ind i smedeildens flamme, men nogle ting kan jeg stadig se. Jeg kan se, at du ønsker noget.\n\nOg hvis du har fundet vej hertil, kan jeg gætte, hvad du ønsker."},
  [1503] = {n="Smedet Stål", l="Bring de Smedede Stålstænger til Thun'grim Ildblik i Ødemarken.", d="Jeg vil give dig et våben, <Name>, men først må du hjælpe mig. Barbermanerne nordvest for her kom ind i min lejr for et par nætter siden. De ville ikke møde mig i kamp, men de ved, at mine øjne er dårlige - nogle få distraherede mig med snøft, mens andre stjal fra mig! Kujonerne!\n\nDe tog en jernkiste, og i den var nogle smedede stålstænger. Hvis du kan finde dem, så giver jeg dig det våben, du søger.\n\nLed efter jernkassen i kvilbor-lejrene, og vend tilbage med stålstængerne.", p="Har du mine stålstænger?", c="Du fandt dem! Og alle stængerne er her, hvilket ikke overrasker mig. Jeg troede ikke, Barbermanerne ville vide, hvad de skulle gøre med fint stål som dette.\n\nTak, <Name>. Her er din belønning. Må den tjene dig godt."},
  [1504] = {n="Det Bindende", l="Brug Fremkaldelsesglyfferne til at fremkalde og nedkæmpe en tomrumsvandrer, og returner derefter Fremkaldelsesglyfferne til Gan'rul Blodøje i Orgrimgrad.", d="Nu, observer Verga-tavlen, for den indeholder de glyffer, du skal bruge til fremkaldelsen. Tag dem til cirklen i Neeru Ildklinges telt på den anden side af hulen. Der vil du kunne kalde på tomrumsvandreren.\n\nDu må besejre den med alle de fysiske og magiske midler, du har til rådighed. Når dette er gjort, så vend tilbage til mig med fremkaldelsesglyfferne, og jeg vil vise dig, hvordan du kan binde væsenet til din vilje.", p="Tomrumsvandreren er et kraftfuldt væsen. Jeg husker, da det var mig, der stod i dine sko, <Name>. Gennem årene er min egen tomrumsvandrer blevet mindre tilbøjelig til at kæmpe imod mig, selvom jeg mistænker, at det kun er, fordi den håber, at jeg vil sænke min vagtsomhed.\n\nHusk det, <Name>.", c="Du har gjort det godt, <Name>. Jeg vil vise dig, hvordan du fremkalder en tomrumsvandrer, der ligner den, du lige besejrede.\n\nDu bør vide, at vi har høje forventninger til dig, og det har du hidtil levet op til.\n\nLad det dog ikke gå dig til hovedet, for de opgaver, der stadig ligger foran dig, vil få dette til at virke så simpelt som at vågne om morgenen."},
  [1505] = {n="Veteranen Uzzæk", l="Tal med Uzzæk ved Fjernvagtsposten.", d="Hordens krigere ærer, fordi deres styrke aldrig er i tvivl. Men de virkelig store krigere er også gode elever.\n\nSøg Uzzæk. Han er veteran fra mange slag og underviser nu unge krigere i kampens kunst. Du finder ham syd for Fjernvagtsposten, orkegarnisonen på grænsen mellem Ødemarken og Durdotar mod øst.", c="Hej, unge. Er du her for at få undervisning?"},
  [1506] = {n="Gan'ruls Tilkaldelse", l="Tal med Gan'rul Blodøje i Orgrimgrad.", d="Dig dér. <Name>, ikke?\n\nJeg håber, din kalender ikke er travl, for Gan'rul vil se dig med det samme. Du finder ham sammen med de ældre hekseklogs i Skyggeklyngen.\n\nUd fra mine tidligere erfaringer med Gan'rul er din tilkaldelse enten en meget god eller en meget dårlig ting.", c="Godt. Jeg var bange for, at Ofek ikke ville nå dig.\n\nDet er tid til, at jeg videreudvikler din hekseklog-træning. Alle dine nuværende forpligtelser må vente.\n\nJeg regner med, at der ikke er noget problem med dette?"},
  [1507] = {n="Sjælenes Sluger", l="Tal med Kasul i Skyggeklyngen.", d="Tiden er kommet for, at du lærer mere om fremkaldelsesmagi. Du vil lære at fremkalde en sukkubus, et væsen med utrolige mentale kræfter. Den kan vugge dem med svage sind ind i sin tjeneste - men frygt ikke! Jeg er helt sikker på, at du vil være på højde med udfordringen.\n\nEn sukkubus kan kun fremkaldes, når den lokkes med en genstand, der repræsenterer stor hengivenhed og kærlighed. Jeg overlader det til dig at finde sådan en genstand.\n\nEt forslag? Tal med Kasul... Der ser ud til at være lidt, som den gamle hekseklog ikke ved.", c="Hm... <Name>. Du er stadig ny på din vej, men jeg fornemmer muligheden for storhed i dig.\n\nDu blev født med gaver, <Name>. Sørg for, at de ikke går til spilde."},
  [1508] = {n="Blænd Kazul", l="Tal med Sankaja i Orgrimgrad.", d="Hmm... Men selvfølgelig er det ikke derfor, du er kommet for at tale med mig.\n\nHvis Gan'rul har sendt dig til mig, må det betyde, at du skal fremkalde en sukkubus og har brug for et objekt at lokke den med.\n\nHmm... Hvis du stoler på en blind mand til at lede dig, <Name>, så lyt. I klipperne ved Orgrimgrad, vest for vindrytertårnet, bor Sankaja. Hun venter på sin makkers tilbagekomst.\n\nGå til hende.", c="Har du kommet med nyt om Dogran? Han skulle være vendt tilbage for flere dage siden, og jeg har ikke hørt noget..."},
  [1509] = {n="Nyheder om Dogran", l="Tal med Gazrøg ved Korsvejen.", d="Min makker, Dogran, blev for nylig sendt til Korsvejen i tjeneste. Det var en forfremmelse, og han var meget stolt.\n\nJeg var selvfølgelig ked af det, men det lod jeg ham ikke mærke. Og bekymret, også. Ødemarken er et farligere sted end Orgrimgrad, og jeg frygtede det værste.\n\nNu er der gået en uge, siden han skulle være vendt tilbage, og jeg har ikke hørt et ord fra ham...\n\nMon du kunne tage til Korsvejen og se, om de har nogen nyheder? Han arbejdede sammen med Gazrøg, som burde være stationeret der endnu.", c="Sankaja? Det er Dograns makker, ikke?\n\nJa, jeg har hørt fra ham, men det er ikke den slags nyheder, vi skal lade komme tilbage til hende...\n\nNej, han er ikke død. Men han er såret og fange hos tornesvinene."},
  [1512] = {n="Kærlighedens Gave", l="Bring det jordklistrede vedhæng til Gan'rul Blodøje i Orgrimgrad.", d="Sankaja er ung og smuk. At være lænket til en invalid... Den uretfærdighed vil jeg ikke lade hende lide.\n\nForlad mig, <Name>. Og tak. Jeg kan ende mit liv i glorværdig kamp i stedet for som et livløst skal.\n\nOg venligst, jeg vil bede dig om ikke at fortælle min makker om dette... Jeg ønsker ikke, at hun skal have skyld på sin samvittighed.", p="Du er vendt tilbage. Er du klar til at kæmpe mod en sukkubus?", c="Hvis du siger, at dette er tilstrækkeligt, så stoler jeg på dig, <Name>. Lad mig dog rense det... Upåklageligt og skinnende kan det være endnu mere fristende for en sukkubus."},
  [1513] = {n="Bindingen", l="Brug Dograns Vedhæng til at fremkalde og tæmme en sukkubus, og returner derefter Dograns Vedhæng til Gan'rul Blodøje i Orgrimgrad.", d="Tag dette med til fremkaldelseskredsen i Neerus telt, <Name>. Fremkald en ussel sukkubus, og vis den din mesterskab. Jeg tror på din magis styrke. Men vær som altid på vagt, for stolthed og overmod har overvundet mange lovende hekse.\n\nNår du har besejret den, så bring vedhænget tilbage til mig, så jeg kan overbringe nyheden til Sankaja.", p="Når jeg ser på en sukkubus, begynder mit hjerte at svæve... Men samtidig kan jeg næsten fornemme min sjæls ebbe, der driver væk som tidevandet.\n\nVær på vagt, min ven.", c="Succes! Vær sikker på, at jeg ikke forventede mindre af min stjerneelev.\n\nDu har bevist din værdi, og gerne vil jeg vise dig metoden til at fremkalde din tæmmede sukkubus. Gå nu, du har meget at lære, og næste gang jeg ser dig, forventer jeg, at du har fundet sand mestring over din sukkubus.\n\nLad sorgen over Dogran og Sankaja være til os, der er ældre, men husk den, og hold den som beskyttelse mod den mørke magts list, du har lært at fremkalde i dag."},
  [1515] = {n="Dograns Fangenskab", l="Bring Ken'zigla-eliksiret til Dogran i Ødemarken.", d="Du er kommet så langt, så hvis du vil se dette til ende, vil jeg ikke stoppe dig. Jeg kan ikke undvære yderligere mandskab, så du står alene.\n\nDogran holdes fange i en tornesvinelejr nord for her. Led efter en gruppe af to hytter. Han vil være hårdt bevogtet--hvis de altså ikke har dræbt ham endnu, eller han ikke er bukket under for sine sår.\n\nHeld og lykke.", p="Urrrghhhh...", c="Snavset smag...\n\nJeg kan mærke styrken i mig nu, nok til at halte væk... Men mit ben, det har jeg mistet resten af livet. Min arm også."},
  [1516] = {n="Jordens Kald", l="Bring 2 Ondsnigerhove til Kanaga Jordkalder i Prøvedalen.", d="Tiden er nu, unge <Class>. Du er blevet stærk, og din ånd holder ud ligesom jorden. At følge shamanens vej viser, at du har visdom, før du overhovedet har bevist dig selv.\n\nJordens element vil guide din skæbne og blive en del af dig, hvis du er klar. Men du må stå foran selve jorden. Hvis du er klar, vil du se ting, som kun shamaner kender til.\n\nSøg Ondsnigerne mod nord, og tag to af deres hove fra dem. Vend tilbage til mig, så taler vi mere om din fremtid.", p="Tålmodighed er jordens største dyd. Jorden overværer alle tings kredsløb: bjergene, der bliver til ørkener; floderne, der bliver til kløfter. Jorden er den mest stædige og vise af alle elementerne, og den tolererer ikke utålmodighed.\n\nJorden kalder på dig nu, fordi en konfliktens tid nærmer sig. Når du vender tilbage til mig med succes, vil du være så meget tættere på at blive hel.\n\nAndre vil misunde din visdom og hade dig for deres uvidenhed.", c="Fremragende. Din succes viser, at du er parat.\n\nAf alle elementerne repræsenterer jorden fundamentet for alle ting. Den er din styrke, din udholdenhed og din tålmodighed. Jorden vil beskytte dig, men kun hvis den vises behørig respekt. Ligesom de andre elementer kan selv jorden være ustadig. Jorden er grundlaget for livet, og ved at iagttage dens love vil du opnå større visdom. Glem aldrig de hemmeligheder, jorden deler med dig.\n\nJeg skal lave en jordsapta til dig nu, og ved at acceptere den vil du indse din vej."},
  [1517] = {n="Jordens Kald", l="Find Åndesten og drik jordsaptaen.", d="En sapta er en drik, skabt for at binde vores ånder til elementerne. Smeltet sammen med magi vil eliksiren lade de stærkviljede se elementerne, som ingen anden kan. Din ånd vil være forbundet med det element, saptaen blev skabt til, og kun en udvalgt håndfuld shamaner kender opskriften.\n\nSaptaen drikkes altid på et helligt sted, og aldrig andetsteds--husk det.\n\nSøg Åndesten sydvest herfra--den findes ved enden af den Skjulte Sti. Drik din sapta der, og... ja, så skal du se.", c="Ah... <Name>... jorden er glad for at have dig her.\n\nSammenbundet i krop og ånd vil du gå frem i vished om, at bjergene er din styrke; sletterne, din tålmodighed; og verden selv din essens.\n\nAt stå ydmygt foran jorden er alt, hvad der kræves af dig for at bestå denne rite. Men de andre er ikke så passive. De kan være kaotiske og ofte voldsomme, men sådan er elementernes natur. Med dobbelte naturer, der modarbejder hinanden, må du lære disse ting indgående."},
  [1518] = {n="Jordens Kald", l="Bring den Grove Kvarts til Kanaga Jordkalder i Prøvedalen.", d="Tag denne grove kvarts fra mig og bring den til Kanaga Jordkalder som bevis på vores møde. Han vil fremstille et totem til dig, og denne sten vil være dens hjerte. Så lille som den end kan synes, vil du finde ud af, at størrelse ikke har betydning, og at selv de mindste ting kan overleve mange andre.\n\nVær tålmodig, <Name>. Forbliv stærk. Og søg visdom. Det er, hvad jorden kræver af dig. Til sidst skal du blive ét med jorden--respekter den, som den skal respektere dig.", p="Jeg ønsker at være den første til at byde dig fuldt velkommen til den første af fire veje, der for altid vil lede dig mod din skæbne.\n\nHvis du har stenen, som jorden gav dig, vil jeg give dig totemet, den lovede.\n\nHvis ikke, så væk med dig, indtil du har fundet din vej.", c="Fremragende!\n\nTotemet, jeg vil fremstille til dig, er mere end et symbol på din status blandt <Class>--det har evner ud over det. Én anvendelse af totemet er som fokus for besværgelser. Disse besværgelser er knyttet til jorden, og efterhånden som du opnår større og større visdom, vil flere af jordens evner blive tilgængelige for dig.\n\nLærerne vil vide, når du er klar til større viden.\n\nMen indtil videre, tag dette jordtotem og en rulle, der lærer dig din første evne."},
  [1519] = {n="Jordens Kald", l="Bring 2 påføringer af Ritual-salve til Seer Ravnefjer i Narache-lejren.", d="Tiden er kommet, unge <Class>. Din krop ældes og bliver stærk, og din ånd holder ud ligesom jorden. Jeg ser det i dig--du har allerede visdom.\n\nJorden guider vores folk, og den taler til os, ligesom den vil tale til dig med tiden. Men du må prøves. Hvis du er klar, vil du se ting, som kun vores slags kender til.\n\nSøg Børseryggens shamaner i deres kløft mod øst, og tag fra dem en salve, de bruger i deres ritualer. Kom kun tilbage, når du har nok til din egen eliksir.", p="Jorden er tålmodig og vil vente på dig, til du er klar, for hun ved, at alt med tiden eroderer og genfødes. Det er tingenes kredsløb. Bjerge bliver til ørkener. Floder bliver til kløfter. Jorden er den mest stædige og vise af alle elementerne.\n\nDu må lære tålmodighed og udholdenhed frem for alt. Jorden kalder på dig nu, fordi hun mener, du er klar. Betragt dette som din genfødsel, hvis du lykkes. Du vil aldrig kunne vende tilbage til uvidenhed bagefter.", c="Godt, <Name>. At du vender tilbage hertil, betyder, at du faktisk er klar til næste skridt.\n\nAf alle elementerne repræsenterer jorden fundamentet for alle ting. Den er din styrke, din udholdenhed og din tålmodighed. Moder Jord vil beskytte dig, men kun hvis du viser hende behørig respekt. Hun er grundlaget for livet, og ved at iagttage hendes love vil du opnå større visdom. Glem aldrig de hemmeligheder, hun deler med dig.\n\nJeg skal lave din sapta nu, og ved at acceptere den åbner en ny vej sig for dig."},
  [1520] = {n="Jordens Kald", l="Find Kodosten og drik jordsaptaen.", d="En sapta er en drik, skabt for at binde vores ånder til elementerne. Smeltet sammen med magi vil eliksiren lade de åbensindede se elementerne, som ingen har set dem før. Din ånd vil for evigt være bundet til det element, saptaen blev skabt til, og kun en udvalgt håndfuld af vores slags kender hemmelighederne bag dens skabelse.\n\nSaptaen indtages altid på et helligt sted, og aldrig andetsteds.\n\nSøg shamanens helligdom mod øst herfra og drik af saptaen.", c="Ah... <Name>... jorden er glad for at have dig her.\n\nSammenbundet i krop og ånd vil du gå frem i vished om, at bjergene er din styrke; sletterne, din tålmodighed; og verden selv din essens.\n\nAt stå ydmygt foran jorden er alt, hvad der kræves af dig for at bestå denne rite. Men de andre er ikke så passive. De kan være kaotiske og ofte voldsomme, men sådan er elementernes natur. Med dobbelte naturer, der modarbejder hinanden, må du lære disse ting indgående."},
  [1521] = {n="Jordens Kald", l="Bring den Grove Kvarts til Seer Ravnefjer i Narache-lejren.", d="Tag denne grove kvarts fra mig og bring den til Seer Ravnefjer som bevis på vores møde. Hun vil fremstille et totem til dig, og denne sten vil være dens hjerte. Så lille den end synes, vil du finde ud af, at størrelse ikke har betydning, og at selv de mindste ting kan overleve bjerge.\n\nVær tålmodig, <Name>. Forbliv stærk. Og søg visdom. Det er, hvad jorden kræver af dig. Til sidst skal du blive ét med jorden--respekter den, som den skal respektere dig.", p="Hilsen, <Name>. Du ville ikke vende tilbage til mig, hvis du ikke havde udført din opgave. Må jeg være den første til at byde dig fuldt velkommen til den første af fire veje, der for altid vil styre dine rejser.\n\nHvis du har stenen, som jorden gav dig, vil jeg give dig totemet, den lovede. Hvis ikke, så må jeg synes synd om dig. Der er meget stolthed at hente, når man helt har viet sig til elementerne.", c="Storartet.\n\nTotemet, jeg vil fremstille til dig, er mere end et symbol--det har evner ud over det. Én anvendelse af totemet er som fokus for besværgelser. Disse besværgelser er knyttet til jorden, og efterhånden som du opnår større og større visdom, vil flere af jordens evner blive tilgængelige for dig. Lærerne i hele Kalimdør vil vide, når du er klar til større viden, og de vil lade dig vide det, når du besøger dem.\n\nMen indtil videre, tag dette jordtotem..."},
  [1522] = {n="Ildens Kald", l="Find Kranal Fis i Ødemarken.", d="Ild være med dig, mon. Jeg ser, du er stærk i jordens veje allerede, og mig tænker, du er klar til at snakke med Kranal.\n\nKranal bor nord for Korsvejen i Ødemarken. Han er stærk i elementernes veje og kan lære dig ildens veje... hvis du tænker, du er klar.\n\nHan er let at finde, bare gå ikke for langt--går du for langt, finder du dig selv i nattenissernes lande.", c="Hmmm, Sørn sendte dig til mig, gjorde han det?\n\nTja, Sørn kunne altid stoles på, så det må betyde, at du er klar til at tage del i den næste sapta--ildsaptaen.\n\nJeg kan allerede se det i dine øjne, brændingen, begæret. Du har smagt magt, og nu er du klar til mere af den. Tålmodighed, <Name>. Husk, hvad jorden lærte dig. Magt og ødelæggelse vil komme let, men du må stadig vide, hvornår du skal holde hånden tilbage."},
  [1523] = {n="Ildens Kald", l="Find Kranal Fis i Ødemarken.", d="Længe er det siden, du sidst blev prøvet, <Name>. Du har vist tålmodighed indtil nu i dine studier, men tiden er kommet til, at du lærer mere. Tiden er kommet til, at du lærer om ødelæggelse... og kaos. Ildens element er din at forstå, hvis du er parat til at betale for det.\n\nSøg Kranal Fis i Ødemarken. Han bor i en lille bolig nord for Korsvejen, men vær opmærksom på, at du er gået for langt, hvis du er nået til nattenissernes lande.", c="Hmmm, Narm sendte dig til mig, gjorde han det?\n\nTja, Narm kunne altid stoles på, så det må betyde, at du er klar til at tage del i den næste sapta--ildsaptaen.\n\nJeg kan allerede se det i dine øjne, brændingen, begæret. Du har smagt magt, og nu er du klar til mere af den. Tålmodighed, <Name>. Husk, hvad jorden lærte dig. Magt og ødelæggelse vil komme let, men du må stadig vide, hvornår du skal holde hånden tilbage."},
  [1524] = {n="Ildens Kald", l="Bring Fakkelen fra den Hvilende Flamme til Telf Jolam i Durdotar.", d="Du er stærk nok til at bære ildtotemet, men det betyder ikke, at du er klar.\n\nLangs Sydfury-floden i Durdotar, før Det Store Hav, ligger en skjult sti til en af de højeste toppe i landet. Find vej til toppen, og du vil finde et af vores hellige helligdomme, passet af Telf Jolam--Den Hvilende Flammes Helligdom.\n\nTag denne fakkel med til ham--den viser, at du forsøger at tæmme ilden. Bring den tilbage til mig antændt ved bålskålen i helligdommen, så vil jeg sørge for, at du får ildtotemet.", p="Hilsen, <Name>. Du har fundet vej til Den Hvilende Flammes Helligdom. Kun dem, der er vidende nok i shamanistiske kunster, vil nogensinde lære hemmelighederne bag dette sted og den magt, det rummer. Jeg beklager, at du har gjort turen hele vejen herop, kun for at blive vendt om nu--rejsen herop er jo langt fra sikker--men jeg er helligdommens vogter, og jeg kan ikke tillade, at hvem som helst vandrer rundt her.", c="Ah, min fejl, <Name>. Jeg beklager. Jeg var ikke klar over, at du havde fakkelen. Det glæder mig at gøre din bekendtskab.\n\nMange eventyrere finder vej hertil på jagt efter tabt skat eller løftet om mytiske skabninger at slå ihjel, kun for at blive vist bort fra en tilsyneladende tom helligdom. Men vi kender sandheden, gør vi ikke, <Name>?\n\nDenne helligdom rummer en større hemmelighed, som de verdslige medlemmer af Horden ikke kender til. For os er den hellig."},
  [1526] = {n="Ildens Kald", l="Besejr den Mindre Manifestation af Ild, og læg den Glødende Gnist i bålskålen på toppen af Den Evige Flammes Helligdom.", d="Ildsaptaen er færdig. Tiden er kommet til, at du skal stå over for flammen. Brug saptaen ved helligdommen, og gå op til toppen af bjerget for at møde manifestationen dér. Han vil ikke angribe, før du er klar, men han vil indse, at du kan se ham.\n\nSlå ham hurtigt ned, <Name>, for han vokser i kraft, jo længere du tøver med at dræbe ham. Når han er besejret, skal du placere hans glødende gnister i bålskålen og tænde fakkelen.", p="Bålskålen er omkring en tredjedel af din højde og ser normal ud, bortset fra indskrifterne langs dens glatte metalskinner. Metallet viser ingen tegn på slid fra vejret, og skålen øverst føles kølig at røre ved.", c="En hvidglødende flamme antænder i skålen, da du placerer gnisten deri. Du kan mærke saptaens magiske virkninger strømme gennem din krop, og ilden danser rytmisk foran dig.\n\nDu stiller fakkelens top i bækkenet, og den tager straks ild."},
  [1527] = {n="Ildens Kald", l="Bring Fakkelen fra den Evige Flamme til Kranal Fis i Ødemarken.", d="Med fakkel i hånden vender du dig væk fra bålskålen og kigger ud over Durdotar. Du kan mærke en spænding trække i din ånd, da vinden tager til og får flammen til at danse voldsomt.\n\nDu begynder at gå ad stien tilbage mod Ødemarken for at finde Kranal Fis.", p="Ja, <Name>? Hvad har du dér?", c="Din ånd brænder klarere end nogen fakkel, jeg nogensinde har set, <Name>, og det bør du være stolt af.\n\nFortsætter du ad denne vej, vil elementerne være dine at kommandere, og vores brødre vil søge din vejledning og visdom. Lad mig være den første til at lykønske dig og præsentere dig for dit nyeste totem."},
  [1528] = {n="Vandets Kald", l="Find Isleif Vandseer i Ødemarken.", d="Vand er i din fremtid, mon. Jeg ser, du er stærk i ildens veje allerede, og mig tænker, du er klar til at snakke med Isleif.\n\nIsleif bor langs kysten af Ødemarken. Hvis du går sydpå langs Sydfury-floden, kan du ikke misse hende--led efter den store haj! Hun er stærk i elementernes veje og kan lære dig vandets veje... hvis du tænker, du er klar.\n\nHun er let at finde, bare gå ikke for langt sydpå--hun er lige forbi Skralleby.", c="Vinden nærmer sig dig hurtigt fra horisonten; jorden er stadig under dine fødder; og din ånd er allerede varmet af ild--jeg vil sige, at det er tid for dig at lære om vandets renhed.\n\nDin vej har ført dig hertil, og din ånd vil give dig styrke til at fortsætte endnu længere. Men det første skridt er din at tage."},
  [1529] = {n="Vandets Kald", l="Find Isleif Vandseer i Ødemarken.", d="Længe er det siden, du sidst blev prøvet, <Name>. Du har vist tålmodighed indtil nu i dine studier, men tiden er kommet til, at du lærer mere. Tiden er kommet til, at du lærer om vandets renhed.\n\nSøg Isleif Vandseer i Ødemarken. Hun er langs østkysten, syd for Sydfury-floden og Skralleby. Du finder hende der ved hendes fiskerhytte. Held og lykke, <Name>.", c="Vinden nærmer sig dig hurtigt fra horisonten; jorden er stadig under dine fødder; og din ånd er allerede varmet af ild--jeg vil sige, at det er tid for dig at lære om vandets renhed.\n\nDin vej har ført dig hertil, og din ånd vil give dig styrke til at fortsætte endnu længere. Men det første skridt er din at tage."},
  [1531] = {n="Luftens Kald", l="Find Prate Skyseer i Tusind Nåle.", d="Du gør fremskridt nu, mon. Du er klar til at bevise dig selv værdig til luft-totemet, men først skal du finde Prate Skyseer i Tusind Nåle. Hun vil gerne fortælle dig, hvordan du får dit luft-totem, hvis du behandler hende med nok respekt.\n\nGå sydpå gennem Ødemarken, og når du når Tusind Nåle, så gå mod øst. Du finder hende gemt i et hul sammen med sin kæreste--haha, sig ikke til hende, at jeg på nogen måde har forhånet hende, for hun tager det ikke særlig pænt.", c="Indtil videre skal jeg give dig det, du behøver for at fokusere dine besværgelser og påkalde luftens ånder. Tag dette totem, og når du er klar, så træn med mig igen."},
  [1532] = {n="Luftens Kald", l="Find Prate Skyseer i Tusind Nåle.", d="Kalimdørs vinde skynder sig at møde dig, og du skal regnes blandt nogle af vores mest magtfulde brødre. Jeg er stolt over at se, at du er kommet så langt og har en lovende fremtid.\n\nLuftelementet er svært at kontrollere, men jeg har tillid til, at dine færdigheder vil overvinde enhver forhindring, der placeres foran dig.\n\nTag til den yderste sydlige del af Ødemarken, og gå ind i Tusind Nåle. Det er der, langt mod øst, at du finder Prate Skyseer. Hun vil lære dig mere.", c="Indtil videre skal jeg give dig det, du behøver for at fokusere dine besværgelser og påkalde luftens ånder. Tag dette totem, og når du er klar, så træn med mig igen."},
  [1535] = {n="Vandets Kald", l="Fyld det tomme brune vandskind ved vandhullet under Saltlages hytte, og bring det tilbage til hende i Ødemarken.", d="For at finde forståelse og opnå saptaen fra mig, må du søge efter kun de reneste former for vand. Mens du henter prøver til mig, så læg mærke til dine omgivelser. Vær opmærksom på de væsener, der er afhængige af vandet, og som beskytter det. Se, hvordan det påvirker skove og ørkener. Overvær, hvordan den substans, der opretholder livet, også vil tvinge væsener til at tage liv.\n\nVi starter med en simpel opgave: nedenfor min hytte er der en dam med den dyrebare væske. Fyld dette skind med den og vend tilbage til mig.", p="Jeg er næsten klar til at sende dig af sted på dine andre opgaver. Har du fyldt skindet endnu?\n\nJeg ved, hvor beskyttende tornesvinene kan være. Selv en så lille vandkilde er en enorm skat for dem. De holder store gilder, når selv det mindste regnskyl kommer til Ødemarken. Vand er helligt for deres art, fordi det er så knapt. Forstår du?", c="Jeg troede, at noget blodsudgydelse kunne opstå, hvis du forsøgte at tage vand fra dammen. Det er en skam, at tornesvinene ikke indser, at alle levende ting er forbundet; at deres grådighed kun forlænger smerten og lidelsen i deres folk. Hvor meget kunne de udrette, hvis de lagde deres uenigheder til side, og deres klaner samlede sig.\n\nIgen, en skam, men mere end sandsynligt en gevinst for de andre racer i Ødemarken."},
  [1558] = {n="Den Stenbyggede Skade", l="Tag forældreløsen til Den Stenbyggede Skade i Modansøen. Du bør tage ham til midten af dæmningen, så han kan se ud over det enorme vandfald.", d="Jernsmede er der, hvor alle dværgene og gnomerne bor. Nær ved ligger et sted, der hedder Modansøen, og dværgene byggede en ENORM skade dér. De siger, det er en af de største ting, nogen nogensinde har lavet. Wow!\n\nKunne du tage mig til Modansøen og se dæmningen dér, tak? Jeg tror, den hedder Stene... øh... Stenbyggede? Stenhuggede? Den er stor - det er sikkert. Jeg vil gerne kigge ud over det store vandfald. Jeg lover, at jeg ikke lener mig for langt ud!", p="Er vi der snart?", c="WOW - dæmningen var MEGET større, end jeg troede! Jeg kunne næsten ikke høre mig selv tale for lyden af alt det strømmende vand! Hey, tror du, den nogensinde ville løbe tør for vand? Mand, hvad ville der ske, hvis den dæmning nogensinde brød! WOW, det ville være skræmmende!\n\nTak, fordi du tog mig med til at se dæmningen. Det var meget venligt af dig. Jeg sagde jo, at jeg ikke ville lene mig for langt ud!"},
  [1559] = {n="Blitzbombe-opskrift", c="Så du er ingeniør, hva'? Nå, for din hjælp med at skaffe mig de perler, her er opskriften på blitzbomber.\n\nHeld og lykke, og prøv at undgå at blænde dig selv!"},
  [1560] = {n="Tøggas Quest", l="Vis Tøgga vejen tilbage til hans kone, Tærte.", d="Jeg er så faret vild!\n\nMin kone, Tærte, sendte mig ud for at hente aftensmad, og jeg må have taget en forkert vej et sted.\n\nVil du være så venlig at lede mig tilbage til Tærte? Hun venter på mig lige syd for Dampsnurre Portvin.", p="Hvor er Tøgga?", c="Så han kunne ikke finde vej tilbage af sig selv? Det var jo til at forudse.\n\nTja, jeg gætter på, du fortjener noget for dit besvær...."},
  [1599] = {n="Begyndelser", l="Bring 3 Fjer-amuletter til Alamar Grum i Ambolmar.", d="Du må være den nye hekser, alle har hvisket om. Må være, at nogen har taget en skarp interesse i dig, hvis de har bedt mig om at tage tid væk fra min forskning for at starte din oplæring.\n\nBekymr dig ikke, jeg vil ikke tage det imod dig.\n\nDen simpleste af de fremkaldelsesbesværgelser, du vil lære, er den for drillingen. Før jeg giver dig den, må du dog bevise, at du har den nødvendige magiske og fysiske evne.\n\nBring mig tre fjer-amuletter fra frostmanke-novicerne i hulen mod sydvest.", p="De fjer-amuletter, novicerne bærer, har en slags magisk kraft i sig. Det bliver interessant at undersøge dem. Jeg havde ikke forventet det fra trolde.", c="Meget godt, meget godt! Du har klaret dig godt, <Name>. Måske er den interesse, der vises i dig, alligevel fortjent.\n\nDet må de andre afgøre--forudsat at din drilling ikke overmander dig og kvæler din karriere i fødslen. Indtil videre er jeg tilfreds med, at du nok overlever dine første par måneder som <Class>.\n\nEt ord om drillingen, <Name>. Som en <Race> ved, må du ikke lade dens størrelse narre dig, for dens magi kan være meget farlig."},
  [1642] = {n="Guddommelighedens Bog", l="Tal med Dutorian Ralle i Stormvind.", d="I alle ting må en paladin afspejle Lyset, som styrker vores kræfter. At stræbe efter at være guddommelig for en af vores slags betyder ikke, at vi stræber efter gudhed--vi stræber efter at være gode i alle handlinger.\n\nSkønt vi kaldes til at straffe det onde i disse hårde tider, må du altid huske, at det er at hjælpe andre, der virkelig adskiller dig fra Azerots borgere. Medfølelse, tålmodighed, mod--disse ting betyder lige så meget for en paladin som styrke i slaget.\n\nVid det godt, og glem det aldrig.", c="Hej igen, <Name>. Hvordan går dine studier af Guddommelighedens Bog?\n\nSå må du være klar til at blive sat på prøve. Der er altid opgaver at løse i hele byen og vores lande; handlinger af medfølelse og forståelse; folk, der har brug for hjælp; væsener, der skal slagtes.\n\nVed at bevise, at du har tålmodighed til at hjælpe andre, især dem, der er mindre heldige, beviser du, at du er en tjener for Lyset og et sundt sind."},
  [1643] = {n="Guddommelighedens Bog", l="Søg i Stormvinds Handelsdistrikt efter Stefanie Tørner.", d="Din opgave er da, <Name>, at finde nogen her i Stormvind, som har brug for hjælp. Nogen, der er ren af hjerte og hensigt. Måske nogen, der hjælper andre. Måske nogen, der har brug for en guide. Uanset hvad, skal personen have ædle hensigter og stole på din venlighed.\n\nGør det, og vend tilbage til mig, når du er færdig. Så skal vi tale mere om din vej, og hvad det betyder at være en paladin for Lyset.", c="Åh, hej, skat. Hvordan går dine eventyr? Åh, jeg er så glad for at høre, at du har det godt.\n\nÅh, mig? Tak for at spørge--jeg har det godt, alt taget i betragtning.\n\nFlere håndværkere har lidt sat en prop i salget af læder og klæde, folk er villige til at skille sig af med for tiden, så det har været sværere at sy tøj til børnene på børnehjemmet, men vi klarer den. Med \"vi\" mener jeg min mand og mig. Han er oppe i Jernsmede og prøver at få hjælp fra byens borgere."},
  [1644] = {n="Guddommelighedens Bog", l="Bring 10 Linnedstof til Stefanie Tørner i Stormvind.", d="Velsignede hjerter, de fleste af dem har ingen familie på grund af Svøbens angreb i det sidste årti.\n\nMin mand John samler materialerne, så jeg kan sy skjorter og bukser til børnene, men jeg har ikke engang haft tid til det. Jeg har været for optaget af at holde mad på deres tallerkener og et tag over deres hoveder.\n\nHvad siger du? Du vil gerne hjælpe? Åh, tak Lyset, og tak, <Name>.\n\nHvis du kunne bringe mig noget linnedstof, så jeg kan sy tøj til børnene, ville det hjælpe mig så meget.", p="Jeg håber, at min John har mere held i Jernsmede. Han bryder sig ikke om sine rejser derop, for det efterlader børnene og mig alene, men han ved, at det skal gøres. Han har så et venligt hjerte.\n\nNogle år har været lettere end andre, men dette har været langt hårdere. Det er næsten, som om noget i luften signalerer en stor forandring. Hvem ved dog?", c="Tak, <Name>, tusind tak!\n\nBørnene vil blive så glade, og du har sparet mig for så meget tid. Nu kan jeg fokusere på børnenes andre behov, og forhåbentlig vil min John kunne vende hjem hurtigere, end vi troede.\n\nTak igen, <Name>. Jeg vidste, at jeg kunne stole på andres velgørenhed. Lyset være med dig."},
  [1649] = {n="Tapperhedens Bog", l="Tal med Dutorian Ralle i Stormvind.", d="Tapperhed og alle de dyder, der følger med den, er som sjældne mineraler: du må værne om dem, når du finder dem, for deres værdi, men du må også tage dig tid til at høste dem... raffinere dem. Blandes de rigtigt, dannes en stærk legering, som nogle gange er ubrydelig selv for de stærkeste slag.\n\nDenne styrke, din tro, dit mod, må prøves. Du må lære aldrig at miste troen og indse, at du med Lysets kraft kan overvinde ting, som de fleste andre ikke kan.", c="Ah, du ønsker at bede mig om en prøve af tapperhed. Fortrinligt.\n\nDer er mange opgaver i hele byen og de omkringliggende lande, som byder på stor udfordring, og de kunne bruge en mand med dine evner.\n\nDenne prøve må ikke tages let på, <Name>. Den kan, ligesom mange ting på vores vej, koste os livet. Kirken ønsker altid at styrke sine rækker, men den forstår de ofre, der skal til for at sikre, at paladinerne, som tjener den, er værdige.\n\nEr du klar?"},
  [1651] = {n="Tapperhedens Bog", l="Forsvar Daphne Stilvæg mod Defias' angreb.\n\nIngen af jeres ånder må blive frigivet fra deres dødelige kroppe, hvis du vil lykkes.\n\nNår du har lykkedes, skal du tale med Daphne Stilvæg igen.", d="Nu kommer de snart igen, vil jeg vædde på, så gør dig klar.\n\nJeg har et gevær i huset. Jeg henter det og er klar til at hjælpe dig, men for det meste må du klare dig selv.\n\nJeg aner ikke, hvor mange de sender, men jeg er sikker på, at det bliver flere end de få, de sendte tidligere.\n\nBed Lyset om alle de velsignelser, du kan få, for... hørte du det? Jeg tror, de kommer.\n\nVi står fast ved huset!", p="Vi står fast ved huset!", c="Vi har gjort det, <Name>! Tak for din hjælp. Du var virkelig fantastisk derude. Jeg troede aldrig, at en paladin kunne klare så mange fjender på én gang.\n\nDu har virkelig vist mod over for overvældende odds."},
  [1652] = {n="Tapperhedens Bog", l="Tal med Dutorian Ralle i Stormvind.", d="Vær venlig at vende tilbage til Dutorian og fortælle ham, at jeg er i sikkerhed for nu. Det har jeg dig og Kirken at takke for.\n\nHan sender bud til Jernsmede for at fortælle min Jordan, at han intet har at frygte.\n\nÅh, hvor savner jeg min mand. Jeg kan ikke vente, til han vender tilbage.", c="Så, vi ses igen, <Name>, og du er i godt humør, kan jeg se.\n\nStilvægs hjem er sikkert endnu en dag, og ud fra din fortælling kan jeg se, at der ikke manglede fare. Godt gjort.\n\nDaphne og Jordan har hjulpet Kirken enormt, og at du har beskyttet deres ejendom--og deres liv--var det mindste, vi kunne gøre for dem.\n\nFor din tapperhed skal du belønnes."},
  [1653] = {n="Retfærdighedsprøven", l="Tal med Jordan Stilvæg i Jernsmede", d="Faktisk tvivler jeg ikke på, at Jordan selv gerne vil takke dig, og eftersom jeg har brug for en budbringer til at sende ordet om, at hans kone er i sikkerhed, tror jeg, du ville være et perfekt valg.\n\nJordan skulle have været en paladin for Lyset, før hans hengivenhed over for sin fars håndværk førte ham ad en anden vej--han kender vores livsstil til bunds og regnes blandt vores mest trofaste.\n\nHan burde stadig være i Jernsmede--han kan lide at arbejde udenfor portene om dagen, noget med den kølige bjergluft.", c="Goddag, <Name>. Lyset er med dig, tror jeg?\n\nHvad siger du? Du blev sendt af Duthorian!? Min kone, hvordan har hun det? Jeg vidste, at der ville opstå problemer, hvis jeg tog af sted. Sig mig venligst, at hun er... åh, gudskelov. Jeg er så glad for, at hun er i sikkerhed. Defias var en trussel længe før disse angreb, men nu kan kongens rådgivere ikke længere nægte det.\n\nHvad mere sagde Duthorian?\n\nDu er den, der blev sendt for at beskytte min kone? Så takker jeg dig igen, <Name>. Jeg kunne ikke tænke mig en bedre prøve af tapperhed end den."},
  [1657] = {n="Stinkende Sydstranden", l="Kast tre Forladte Stinkbomber ind i hjertet af Sydstranden i Bakkebrad, og vend tilbage til Mørkeråbet Yanka ved Halmmandsfestivalen i Tirisfal-lysningen.", d="Fejr Helligaftens Ende med stil... ved at bringe sorg til vores fjender i Sydstranden!\n\nTag en af disse specialfremstillede stinkbomber. Den er fyldt med en ildelugtende stank, som intet menneske - eller noget svagsindet udyr for den sags skyld - kan holde ud at lugte. Du må kaste den lige ind i hjertet af Sydstranden, for at den kan gøre sit arbejde, så vær forberedt på en kamp mod Alliancen!\n\nNår du har fuldført denne opgave... denne hyldest til vores befrielse, skal du vende tilbage til mig!", p="Har du leveret vores \"gave\" til folkene i Sydstranden?\n\n<Mørkeråbet Yanka ler ondskabsfuldt.>", c="Ah, godt gjort! Jeg håber, at Alliancen kvæles af den onde gave, vi har givet dem, ligesom vi selv måtte kvæles i trældommens åg under Svøben!\n\nDu har holdt Helligaftens Ende i live, <Name>, og for det hylder jeg dig. Som en ekstra bonus vil jeg dele nogle af de Helligaftens Ende-lækkerier, jeg har, med dig. Jeg tror, du vil finde dem til at være en ganske behagelig afveksling!"},
  [1661] = {n="Adelens Bog", l="Tal med Dutorian Ralle i Stormvind.", d="Jeg hilser dig endnu en gang, <Name>. Jeg er stoltere over at kalde dig bror end nogensinde før--din hengivenhed er en hyldest til os alle.\n\nTiden er kommet, til at jeg skal skænke dig en stor gave. Men vid dette: Nu giver jeg dig den frit, men senere, når tiden tillader det, vil dette blive en langt større udfordring for alle paladiner, der vælger at påtage sig min opgave.\n\nTal til mig igen, så skal jeg give dig en stor velsignelse.", c="Tillykke, og må Lyset beskytte dig."},
  [1678] = {n="Vejrøg", l="Bring Vejreks hoved til Muren Stormspids i Jernsmede.", d="Hvis du vil stige i graderne blandt krigerne, så må du være hård. Jeg kan lære dig nye træk, men først skal du bevise over for mig, at du kan klare dig mod rigtige fjender.\n\nVejrøg er den hårdeste trold, du finder i disse egne, og det er ham, du skal besejre. Han har en hytte i foden af bjergene lige syd for Frostmanke-fæstningen.\n\nBring mig Vejreks hoved, så ved jeg, at du har mod.", p="Har du været i Vejreks hytte, <Name>? Er det <Race>-stank, jeg lugter på dig?", c="Vejrøg var da en styg en, hva'? Godt gjort, <Name>! Du har det, der skal til, og nu lad os begynde din lektion...\n\nDu ved måske ikke det, men et stærkt forsvar er meget vigtigt for en <Class>. Det holder ham stående over for fjender, der ville fælde andre, og det er præcis det, dine allierede har brug for."},
  [1679] = {n="Muren Stormspids", l="Tal med Muren Stormspids.", d="Hej, kriger! Du viser en masse løfte, men du skal stadig lære nogle kneb, og Muren Stormspids er lige den dværg til at lære dig dem.\n\nDu finder Muren i Våbenhallen i Militærværnet i Jernsmede. Tal med ham, når du er klar til at lære, hvad det vil sige at være kriger.", c="Ah, <Name>. Jeg hørte krigerne i Dun Frostbakke slynge dit navn rundt. Jeg håber ikke, du har brugt al din tid i bryggerierne!"},
  [1680] = {n="Tormus Dybsmed", l="Tal med Tormus Dybsmed.", d="Nu hvor du har lært nogle træk, er det tid til at skaffe dig et ordentligt våben. Tal med Tormus Dybsmed. Han kan lave et våben til dig, som jeg er sikker på, du vil kunne lide.\n\nDu finder Tormus her i Jernsmede, ved Den Store Smedje.", c="Muren sendte dig, gjorde han? Ja, jeg kan lave et flot våben til dig... men før jeg gør det, har jeg en tjeneste at bede dig om.\n\nBare rolig. Den er farlig nok, og den kan betyde din død; det er præcis den slags job, en <Class> ønsker."},
  [1682] = {n="Grå Jernvåben", c="Her er nogle våben, lige fra ambolten og lavet af den nye umbralmalm, du bragte mig!\n\nVær venlig, <Name>, vælg dit!"},
  [1683] = {n="Vorlus Ondhov", l="Bring Vorlus' Horn til Elanaris i Darnassos.", d="Før jeg kan lære dig, må du vise mig din beslutsomhed.\n\nSatyren Vorlus Ondhov har fundet en af vores fjerntliggende månebrønde, sydøst for Ban'ethil-gravhulen. Nu plasker han i den og besudler dens rene vand med sit snavs.\n\nFind Vorlus ved månebrønden og tilintetgør ham. Bring mig hans horn som bevis, så begynder jeg din avancerede træning som kriger.\n\nVejen til månebrønden er godt skjult, <Name>, men hold fokus og vær på vagt, så finder du den.", p="Har du hornet, <Name>? Er vores månebrønd fri for udyret Vorlus?", c="Godt gjort, <Name>. Det er godt at vide, at Vorlus er besejret, og at vores månebrønd er renset, og det er godt at se unge krigere ivrige efter at holde vores elskede Teldrasil fri for korruption.\n\nNu lad os begynde din træning..."},
  [1684] = {n="Elanaris", l="Tal med Elanaris.", d="Hilsner, kriger. Dine færdigheder vokser, men der er mere til dit erhverv, end du måske tror. For at komme videre må du snart finde en lærer.\n\nKrigeren Elanaris bor i Darnassos, ved Krigerens Terrasse. Hun kan undervise dig.", c="Jeg hilser dig, <Name>. Dit navn klinger højt i Darnassos, for du viser løfte. Men vi får snart at se, om du har viljestyrken til at følge <Class>'ens vej."},
  [1686] = {n="Elyras Skygge", l="Bring 8 læs Elunitmalm og Elyras Medaljon til Elanaris i Darnassos.", d="Du har lært meget, <Name>. Nu skal vi smede et våben til dig. En krigers våben.\n\nFor at gøre det må du rejse til Mørkekysten.\n\nFor længe siden stødte et skib mod klipperne ved Auberdin-fyrtårnet og spredte mange kasser med elunitmalm ud over havbunden.\n\nFørst må du besejre elunitmalmens vogter, Elyras Skygge. Engang var hun skibets kaptajn, og hun forbandede sig selv til at vandre i dybet og beskytte sin last for evigt. Besejr hende, tag hendes medaljon og saml kasserne med den tabte elunit.", p="Har du besejret Elyras Skygge, <Name>? Og har du den tabte elunitmalm?", c="Modigt gjort, <Name>.\n\nDu har givet Elyras Skygge den fred, hun fortjener, og vi vil bruge den samlede elunit til at smede et fint våben til dig."},
  [1687] = {n="Uhyggeligt Fyrtårn", l="Tag forældreløsen med til fyrtårnet ud for kysten af Vestmarken.", d="Nogle gange sent om aftenen fortæller vores moderfigurer på børnehjemmet os uhyggelige historier. Dem ELSKER vi! Der er en om et spøgelse, der hjemsøger et fyrtårn i Vestmarken. Man siger, at han var en pirat-kaptajn, der fik sit skib taget fra sig af andre pirater. Wow!\n\nKan du ikke tage mig med til fyrtårnet i Vestmarken? Jeg vil se, om kaptajnens spøgelse er der! Jeg lover at holde mig tæt på dig; jeg løber ikke væk eller noget!", p="Er vi der snart?", c="WOW, det var et rigtigt spøgelse! Det var så fantastisk - jeg kan ikke vente med at fortælle alle tilbage på børnehjemmet. Kaptajn Gråsen... han så endda ud som en pirat! Når jeg bliver stor, vil jeg også være et spøgelsespirat!\n\nTak fordi du tog mig med til Vestmarken, <Name>. Jeg ved, at der er skumle ting derude i Vestmarkens vildmark, og jeg håber, jeg ikke var for meget besvær. Du er fantastisk!"},
  [1690] = {n="Ødevandrernes Retfærd", l="Nedkæmp 10 Ødevandrer-banditter og -tyve øst for Gadgetbyen, og rapportér derefter til Overingeniør Lensevits.", d="Hør her! Nu er det tid til, at du bliver en stor hjælper for Gadgetbyens Vandselskab.\n\nØdevandrerne derude i Tanaris-ørkenen har grebet næsten alle vandbrøndene! Uden adgang til dem tørrer vores vandforsyning ud på et øjeblik. Hvis du vil i vores gode nåde, så hjælp os med at skaffe retfærd over for de nomader!\n\nGå østpå herfra og fæld ti Ødevandrer-banditter og -tyve, og rapportér så tilbage til mig på stedet. Retfærd venter ikke på nogen mand... kobold... bah, bare kom i gang!", p="Tilbage så hurtigt? Jeg håber, du har været i stand til at bringe noget kobold-retfærd til Ødevandrer-banditterne og -tyvene, som jeg bad dig om!", c="Det kalder jeg effektivitet! Du har hjulpet med at tynde nomadernes rækker ud nok til, at vi kan begynde at tænke over, hvordan vi kan vinde vandbrøndene tilbage.\n\nGadgetbyens Vandselskab takker dig for din hjælp, men vi er langt fra færdige med at håndtere de skumle nomader. Lyt godt efter - her er, hvad vi har brug for næste gang..."},
  [1691] = {n="Mere Ødevandrernes Retfærd", l="Nedkæmp 10 Ødevandrer-skyggemagikere, 8 Ødevandrer-skurke og 6 Ødevandrer-snigmordere for Overingeniør Lensevits i Gadgetbyen.", d="Vi har brug for, at du tager fat på nomadernes stærkere rækker nu. Du har gjort et godt stykke arbejde indtil videre, men hvis vi skal tage vandbrøndene tilbage, giver det kun mening at gøre det med så få nomader som muligt!\n\nDenne gang har vi brug for, at du fælder deres skurke, snigmordere og skyggemagikere. Du finder dem øst og sydøst herfra.\n\nJeg vil ikke lyve for dig - de er et grimt hold. Gør det for os, så er vi på vej til at tage tilbage, hvad der retmæssigt er vores!", p="Nå, kunne du få ryddet de nomader ud, som jeg bad dig om? Gadgetbyens Vandselskab udvikler planer på baggrund af din succes her! Svigt os ikke nu...", c="Topklasse arbejde, <Name>... topklasse! Du har tyndet nomadebefolkningen ud til et punkt, hvor vi faktisk kan gå i kamp med dem!\n\nHvis du ikke allerede har gjort det, så tal med Tappeoperatør Luglunket herovre; han giver en præmie for alle de Ødevandrer-vandposer, du måtte have stødt på, mens du bragte de nomader til retfærd!"},
  [1692] = {n="Smed Matiel", l="Bring Etuiet med Elunit til Smed Matiel.", d="Jeg har lagt den elunit, du samlede, i et etui. Tag det med til smeden Matiel, så smeder han et elunitvåben til dig.\n\nMatiel er mod syd, på den anden side af denne bygning.", p="Hilsner, unge <Class>. Hvordan kan mine færdigheder tjene dig?", c="Ah, elunitmalm. Det er et fint metal at arbejde med, for det er velsignet af gudinden Elune selv. Det vil være en ære at smede våben af det.\n\nVent venligst, mens jeg arbejder..."},
  [1693] = {n="Elunit-våben", c="<Name>, jeg har smedet disse våben af den elunit, du bragte mig. Vær venlig at tage det, der passer dig bedst.\n\nOg jeg må takke dig. At arbejde med elunit er både en ære og en fornøjelse."},
  [1699] = {n="Rethban-handsken", l="Gå ind i Rethban-hulerne, nå til den første gaffel, og vend tilbage til Yorus Byggøl inden for den tilladte tid.\n\nDu må ikke dø og frigive din ånd.", d="Min udfordring kalder jeg Rethban-handsken. For at bestå prøven skal du blot gå ind i Rethban-hulerne, til den første gaffel, og så vende tilbage hertil. Let! Bortset fra at der er et par rynker...\n\nDu skal vende tilbage inden for en time.\n\nDer er hele hobe af Rødryg-gnolde i vejen.\n\nFør du starter, skal du tage en tår af min families kendingsdrik: Byggøl-Skoldeøl!\n\nSå hvad siger du? Rethban-hulerne ligger i foden af bjergene nord for Søshire. Er du klar til at løbe Rethban-handsken?", p="Tiden går, <Name>. Hvis jeg var dig, ville jeg komme i gang...", c="Du klarede det! Godt gjort! Tre hurra for <Name>!"},
  [1700] = {n="Grimand Elmøre", l="Bring Furens noter til Grimand Elmøre.", d="Jeg lavede en kopi af mine noter om teknikkerne, jeg lærte, mens jeg lavede din rustning, og de skal sendes til Grimand Elmøre. Han er her i Dværgekvarteret, i våbenbutikken.\n\nOg duk dig, når du giver ham disse. Han er vildt stolt af sine færdigheder og bryder sig ikke om tanken om at lære noget af mig...", p="Hej, og velkommen. Hvordan kan jeg være til tjeneste?", c="Furen skrev dette? Hvordan vover han! Jeg lærte ham jo alt, hvad han kan! At tænke sig, at han kunne lære mig noget er ude af enhver tænkelig proportion! Ude af proportion!\n\nHm... men der er noget i hans noter, som jeg gerne vil prøve..."},
  [1702] = {n="Skjoldsmeden", l="Bring Tønden med Skoldeøl til Furen Langskæg.", d="Du viste virkelig, hvad du var lavet af, da du løb Rethban-handsken, <Name>. Og jeg holder mit ord. Jeg skaffer dig belønningen, jeg lovede...\n\nBortset fra at den er i Stormvind.\n\nTal med min ven, Furen Langskæg, i Dværgekvarteret i Stormvind. Han er den bedste skjoldsmed, du nogensinde vil møde, og han skylder mig en stor tjeneste.\n\nTag Furen denne tønde Byggøl-Skoldeøl, og bed ham om et skjold. Han giver dig et fint et.", p="Hej! Tørre tider, ikke sandt?", c="Ah, Byggøl-Skoldeøl. Godt stads! Så du har været hos Yorus, hva'?\n\nJeg kan skaffe dig et skjold, javel! Du finder ikke et bedre, og det er ingen løgn!"},
  [1703] = {n="Matiel", l="Bring Furens noter til Matiel.", d="Jeg lavede en kopi af mine noter om teknikkerne, jeg lærte, mens jeg lavede din rustning, og de skal sendes til smeden Matiel. Han bor i Darnassos, som er en lang vej herfra, men jeg er sikker på, at han vil være meget taknemmelig for at lære, hvad jeg har lært.", p="Jeg hilser dig, <Class>.", c="Disse er interessante, meget interessante i sandhed. Min dværgiske kollega Furen har gjort en stor opdagelse!\n\nTak, <Name>. Det vil være en ære at anvende hans nye teknikker på mine egne smedearbejder."},
  [1704] = {n="Klockmort Skruespænd", l="Bring Furens noter til Klockmort Skruespænd.", d="Jeg har lavet en kopi af mine noter om de teknikker, jeg lærte, mens jeg lavede din rustning, og jeg har brug for nogen, der kan tage dem med til Klockmort Skruespænd. Han er en gnomisk smed i Jernsmede, og når han hører, hvad jeg har lært... så vil jeg vædde på, at han river sit eget skæg af i begejstring.", p="Godt, god dag, eller morgen eller aften. Jeg kan ikke se det herfra nede. Så har du noget ærinde til mig?", c="Ih, min Gud! Disse noter er fantastiske! Og hvad mere er... de er utrolige, og de er storslåede, og de får mine knæ til at blive helt vakkelvorne!\n\nFuren har haft et gennembrud! Et rigtigt gennembrud! Jeg kan ikke vente med at prøve hans nye teknik af!"},
  [1705] = {n="Brændende Blod", l="Bring 20 hætteglas Brændende Blod og 1 Brændende Sten til Grimand Elmøre i Stormvind.", d="Det hader jeg at indrømme, men Furen har nok virkelig fundet på noget. Men for at være sikker bliver jeg nødt til at prøve hans teknikker på en ny rustning. Hvis du hjælper mig med materialerne, <Name>, så må du have rustningen.\n\nFor at lave denne rustning har jeg brug for prøver af brændende blod og en brændende sten.\n\nDet eneste sted, jeg kender, hvor man kan få dem, er Skumringsskoven. Nattebane-worgerne, der holder til i Rolands Dom-minen, har brændende blod, og deres leder Tarmspild har stenen.\n\nMå lykken give dig fart, <Name>.", p="<Name>, har du det brændende blod og stenen? Jeg skal bruge dem for at færdiggøre rustningen.", c="Flot arbejde! Og nu, hvis du vil undskylde mig, har jeg selv noget arbejde at tage fat på..."},
  [1706] = {n="Grimands rustning", c="Jeg kan knap tro det! Furens teknik lykkedes, og denne rustning burde kunne holde til enorme belastninger.\n\nDer er den, <Name>. Og tak. Jeg ville ikke have troet på Furens opdagelse, hvis du ikke havde skaffet de materialer, jeg havde brug for, så jeg selv kunne teste den."},
  [1707] = {n="Dusør på vandpunge", l="Bring 5 Spildevandsvandrer-vandpunge til Tapningsoperatør Luglunket i Gadgetbyen.", d="Hilsen <Name> - jeg hedder Luglunket, og vi har et vigtigt job til dig, hvis du er med på den! Hurra!\n\nIntet ville glæde mig mere som erfaren tapningsoperatør end at tage de Spildevandsvandrer-vandpunge, du måske finder ude i ørkenen. Det er nemlig vores vand – nomaderne har bare stjålet det, det er alt! Gadgetbyens Vandselskab tilbyder dig en officiel plejepakke for hver fem, du afleverer. Men vigtigst af alt: Du hjælper Gadgetbyen med at hjælpe sig selv!", p="Har du de fem Spildevandsvandrer-vandpunge, vi skal bruge? Hvis du har, så bliver Gadgetbyens Vandselskabs plejepakke, Model 103-XB, din!", c="Fremragende – jo flere vandpunge vi kan generobre, jo længere væk fra katastrofen er vi alle sammen! Bliv ved med at komme med dem, så sørger jeg for at belønne dig for hver fem vandpunge, du bringer mig."},
  [1708] = {n="Jernkoral", l="Bring 20 læs Svidende Koral til Klockmort Skruespænd i Jernsmede.", d="Jeg vil gerne prøve Furen Langskægs nye teknikker på min egen rustning. Og fordi du hjalp Furen, og han hjalp mig, må du gerne have rustningen, når jeg har lavet den!\n\nFor at færdiggøre stykket har jeg brug for en særlig koral, svidende koral. Den vokser kun ét sted – langs kysten syd for Menetil-havnen i Vådlandene.\n\nBring mig nok svidende koral, så går jeg straks i gang med rustningen. Og skynd dig, <Name>. Jeg er så ivrig efter at komme i gang, at det får tæerne til at krølle sig!", p="Hej hej, <Name>! Har du den svidende koral? Jeg kan ikke vente med at komme i gang!", c="Sådan! Flot klaret! Lad mig nu få den smeltet og hamret, så jeg kan anvende Furens teknik sammen med min egen, og så ser vi, hvad der sker!\n\nÅh, jeg siger dig, jeg ved bare, at rustningen bliver meget, meget, meget hård!"},
  [1709] = {n="Klockmorts Skabelse", c="Her er din rustning, <Name>. Furens metode virkede strålende! Perfekt! Mirakuløst, virkelig!\n\nDu kunne køre over denne rustning med et belejringsvåben, og den ville springe lige tilbage i form!"},
  [1710] = {n="Solsvidede Granater", l="Bring 20 Solsvidede Granater til Matiel i Darnassos.", d="Min kollega, Furen Langskæg, har gjort en opdagelse, som jeg er ivrig efter at teste. Jeg vil prøve den på en ny rustning, jeg er ved at forske i, for jeg tror, at Furens teknikker vil give bedre resultater.\n\nVil du hjælpe mig? Hvis du samler det, jeg skal bruge til at lave rustningen, så laver jeg et ekstra stykke til dig.\n\nJeg har brug for de solsvidede æggegranater fra Højredes Wyverner, som bor i Højrede i Tusindnåle. Led efter granaterne under deres reder, og kom tilbage til mig, når du har en tilstrækkelig mængde.", p="Har du granaterne, <Name>? De er ret stærke og kan omdannes til en lak, som jeg vil bruge til at dække ringene i mit nye kædepanser.", c="Ah, tak. Disse vil fungere glimrende!\n\nJeg begynder straks at smede rustningen..."},
  [1711] = {n="Matiels rustning", c="Jeg er færdig med din rustning, og jeg er ganske tilfreds. Furens nye teknikker smeltede perfekt sammen med mine egne, og jeg er sikker på, at denne rustning vil vise sig at være ganske modstandsdygtig.\n\nTak, <Name>. Og må den tjene dig godt i fremtidige slag."},
  [1713] = {n="Fremkaldelsen", l="Bring Hvirvelvindshjertet til Bath'rah Vindvogteren.", d="Jeg er klar til at udføre ritualet for at fremkalde Cyklonianeren. Når han er fremkaldt, skal du besejre ham og tage hans hvirvelvindshjerte. Det vil jeg bruge til at give et våben Cyklonianerens kraft.\n\n<Name>, er du klar til at møde vindherren?", p="<Name>, jeg skal have hvirvelvindshjertet!", c="Du klarede det! Du besejrede Cyklonianeren og fik Hvirvelvindshjertet!"},
  [1715] = {n="Det Slagtede Lam", l="Mød op hos Gakin Mørkbinderen i Magikerkvarteret i Stormvind.", d="Hmpf. Tidligere blev alle hekser i Khaz Modan uddannet under Nisseborgens magikere, men nu hvor vi alle er blevet tvunget til at flytte ind i denne rottehule i Jernsmede, og Magni har besluttet at holde et vågent øje med os, er vi nødt til at sende vores novicer til Stormvind for at blive uddannet.\n\nHeldigvis er Gakin ingen dumrian, så du lærer stadig det, du skal vide, men det koger mit blod!\n\nUnder alle omstændigheder finder du Gakin i kælderen under Det Slagtede Lam i Stormvind.", c="Sendt af Sortnøgle, var du? Pokkers hekser i Jernsmede må få styr på tingene. Der er kun så meget plads og så mange lærere i Stormvind. Med al den øgede trafik vil vi helt sikkert tiltrække opmærksomhed før eller siden."},
  [1717] = {n="Gakins Indkaldelse", l="Mød op hos Gakin Mørkbinderen i Magikerkvarteret i Stormvind.", d="<Name>! Havde ikke ventet at se dig i disse egne, men jeg fik besked på at holde øje med dig.\n\nDet er på tide, at du får noget mere træning, så du bør stikke forbi Gakin, næste gang du er i Stormvind. Han venter på dig.", c="Jeg er glad for, at nogen fik fat i dig, <Name>. Jeg var ved at frygte det værste. Det ville være en skam at miste dig, efter al den tid, vi har investeret i dig.\n\nVi kan tale sammen senere. Din træning er det eneste vigtige nu."},
  [1718] = {n="Øboeren", l="Tal med Klannoc Macløv.", d="Din berømmelse som kriger vokser, <Name>. Nu er det tid til at måle dig med dine jævnaldrende og se, hvor du står.\n\nDer er en ø ud for Ødemarkens kyst, syd for Skralleby. Den hedder Slagmark Ø, og det er et sted, hvor krigere mødes.\n\nMødes, og kæmp.\n\nTal med Slagmark Øs øverste kriger, Klannoc Macløv. Hvis han finder dig værdig, så fører Klannoc dig længere ned ad krigerens vej.\n\nFor at nå Slagmark Ø skal du lede efter sandbankens lavvande langs Handelskysten.", c="Hej, kriger. Det er godt at se, at du nåede Slagmark Ø. Jeg håber, du finder den til din smag..."},
  [1719] = {n="Slagsmålet", l="Dræb Store Will, og tal derefter med Klannoc Macløv på Slagmark Ø.", d="Hvis du vil lære af mig, så skal du først bestå Slagsmålet. Det er en udfordring, vi på Slagmark Ø gerne byder opadstræbende krigere, der tror, de er hårde, og hvis du kan bestå denne prøve, så ved jeg, at du er det.\n\nFor at begynde skal du gå ind midt i menneskemængden derovre og træde på risten. Det fortæller Kvistie Fladhoved, at du er klar, og så sender han udfordrere mod dig.\n\nSlå alle udfordrerne, og så kalder han Store Will frem. Dræb Store Will, og kom tilbage til mig inden for den tid, vi giver dig.", p="Har du gennemført din udfordring?", c="Godt klaret, <Name>. Du har bestået Slagsmålet!\n\nDu er en værdig kriger, og det er mig en ære at undervise dig..."},
  [1738] = {n="Hjertetræet", l="Hent Hjertetræet fra Askedalen og bring det til Gakin Mørkbinderen i Magikerkvarteret i Stormvind.", d="I forberedelse til din ankomst brugte jeg mit blik til at betragte verden og gennem tidens tåger. Jeg har fundet det, du søger.\n\nI Oldtidens Folks Krig faldt to elskende sammen i kamp. Der, hvor de tog deres sidste åndedrag, voksede et træ, kendt som hjertetræet, et symbol på deres uudslukkelige kærlighed.\n\nDet burde være nok til at friste en succubus. Du finder det i ruinerne af Ordilhand i den nordvestlige del af skoven Askedalen.", p="Var din eftersøgning en succes, <Name>?", c="Ja, jeg kan se, at det her vil gøre det fint. Lad mig lige arbejde med det et øjeblik...\n\nTykar er en pålidelig fyr at have omkring sig, ikke sandt? Hvis bare jeg kunne overtale ham til at flytte tilbage til civilisationen."},
  [1739] = {n="Det Bindende", l="Brug Hjertetræets Kerne til at fremkalde og tæmme en succubus, og bring derefter Hjertetræets Kerne tilbage til Gakin Mørkbinderen i Det Slagtede Lam.", d="Med hjertetræets kerne kan du kaste en besværgelse ved fremkaldelsescirklen i krypten nedenunder for at åbne en portal, som succubussen kan passere igennem.\n\nVær forsigtig, <Name>, succubi har overmandet selv de stærkeste sind.\n\nNår du har besejret den og sendt den tilbage til tomrummet, skal du komme tilbage til mig, så viser jeg dig, hvordan man kalder den og styrer den.", p="Nogle gange undrer jeg mig over, om Sørina ikke var en succubus i forklædning, sendt for at vride og forvrænge mit sind... Ha! Jeg tror, jeg giver hende for meget kredit.", c="Godt gået, godt gået, <Name>. Jeg kan se, at vi gjorde det rigtigt, da vi besluttede at uddanne dig. Din præstation skuffer bestemt ikke.\n\nJeg har ingen betænkeligheder ved at vise dig, hvordan du styrer din nybundne succubus. Hold godt øje."},
  [1758] = {n="Kabalens Foliant", l="Tal med Krom Stærkarm i Jernsmede.", d="Det kræver mere end en simpel fremkaldelsescirkel at fremtrylle en felhugger, som du kan udfordre.\n\nMine tre disciple og jeg vil hjælpe med at skabe de magiske cirkler. Du har brug for en kopi af Kabalens Foliant, som er gået tabt for os for længe siden. Den blev skrevet af den første gruppe hekser, der fremkaldte en felhugger uden hjælp.\n\nMåske kan Krom Stærkarm hjælpe dig med dette. Han er i disse dage en omvandrende hekser, og han bruger sine dage på at hamstre gamle tekster og luske rundt i biblioteket i Jernsmede.", c="Kabalens Foliant? Hmm... det lyder bekendt. Jeg har dog aldrig set den her før – og tro mig, jeg husker hver eneste bog, jeg har læst.\n\nHmm...\n\nAh, ja! Jeg har set henvisninger til den i bibliotekets katalogbøger."},
  [1780] = {n="Guddommelighedens Foliant", l="Tal med Dutorian Ralle i Stormvind.", d="Jeg tager dem med til børnene i dag. Pas godt på dig selv, gode <Class>. Det er ikke ofte, at mænd af din karakter viser sig i byen, men du har bevist, at paladinerne her i Stormvind aldrig vender ryggen til dem, der har brug for hjælp.\n\nFarvel.", c="Du er kommet tilbage så hurtigt, <Name>. Og hvad har du udrettet i din tid væk fra Katedralen?\n\nHar du hjulpet en ædel sag? Måske har du lært værdien af barmhjertighed eller noget mere om dine forpligtelser over for Azerots borgere. Fortæl mig, hvem du har hjulpet, og hvordan... Nå, jeg er imponeret, <Name>. Det er bestemt gerninger fra en, der følger Let og sætter andre over sig selv.\n\nSådant et offer bliver altid belønnet med tiden."},
  [1781] = {n="Guddommelighedens Foliant", l="Tag Livets Symbol med til Gazin Tonelund i Stormvind.", d="Tag den her, <Name>. Den hedder Livets Symbol.\n\nDu har vist dig barmhjertig og tålmodig, og nu er tiden kommet til at se, om du er stærk nok til at fokusere en af Lysets største gaver.\n\nMin ven Gazin vendte for nylig tilbage fra et møde med nogle Defias i Elvendal nær Heltevagten – han slap næsten med livet i behold. Han er ved alteret og får læget sine sår af vores præster.\n\nTag Symbolet og tal med ham. Hvis du kan hjælpe ham, så taler vi snart igen. Må du bade i Lysets herlighed.", c="*host*\n\nDet var en fornøjelse at møde dig, <Class>. Tænk ikke på mine sår, den gode præst her kan tage sig af gamle Gazin denne gang. Jeg får ikke brug for kraften i det Livets Symbol, du har der... ikke endnu i hvert fald.\n\nSå Duthorian sendte dig for at tale med mig, hva'? Fair nok. Jeg fortæller dig præcis, hvad der gik for sig med mig og min ven Henze. Og med lidt held og lidt dygtighed fra din side kan du måske stadig hjælpe os alle."},
  [1782] = {n="Furens rustning", c="Der er din rustning, <Name>. Den her vil holde til de stærkeste angreb, ellers hedder jeg ikke Furen Langskæg!\n\nOg jeg må takke dig. Jeg lærte meget, mens jeg arbejdede med de materialer,\ndu bragte mig. Jeg tror, jeg får endnu et gennembrud en dag!\n\nJeg vil sende det, jeg har lært, til de andre\nsmede i Alliancen.\n\nJeg fortæller dem, at du var en stor hjælp, og måske vil de gerne gengælde tjenesten."},
  [1786] = {n="Guddommelighedens Foliant", l="Tag Livets Symbol og genopliv Henze Rådnesen i Elvendal.", d="Henze og jeg var nået til Heltevagten, en ø midt i Stenrøsesøen i det nordøstlige Elvendal. Vi havde hørt, at Defias var trængt ind over vores grænser, og vi ville have bevis at tage med til kongens rådgivere.\n\nVi fik øje på et par af skurkene, der gennemgik nogle dokumenter, og vi angreb. Desværre blev vi hurtigt overvældet af flere af magikerne.\n\nHenze holdt dem hen, mens jeg slap væk... den fjollede tåbe, der skulle være modig.\n\nHan er derude nu, Henze. Kan du hjælpe os, <Name>?", c="Tak, bror.\n\nNår jeg ser dig bære Livets Symbol, må jeg så antage, at Duthorian eller Gazin sendte dig?\n\nJeg faldt for Defias' besværgelseskastere, mens Gazin og jeg prøvede at få deres planer ud af dem: Jeg kunne holde ud længe nok til, at Gazin kunne slippe væk, men til sidst overvældede deres magi mig.\n\nMen du kunne bringe mig tilbage: Evnen til at bruge Symbolet tilfalder ikke bare hvem som helst, <Name>. Det lover godt for dig, at du kunne styrke det med din egen tro."},
  [1788] = {n="Guddommelighedens Foliant", l="Tal med Dutorian Ralle i Stormvind.", d="Jeg tager manuskriptet med til kongens rådgivere, når Duthorian har kigget på det, men i mellemtiden bør du gå og tale med Duthorian nu. Han vil helt sikkert gerne klappe dig på ryggen!\n\nTak igen, <Name>. Jeg håber, at vi møder hinanden igen. Du er bestemt en allieret, jeg er stolt over at kalde ven.", c="Du har klaret dig godt i dag, <Name>. Du bør være stolt af det, du har udrettet.\n\nEndnu mere bør du være stolt af dine evner. Ikke alle kan bruge Livets Symbols kraft. At kalde på Let for at bringe de døde tilbage betyder, at du er forberedt på en af paladinens største æresbevisninger: genoplivningens kraft.\n\nDu skal have kraften til at bringe faldne kammerater tilbage, ligesom du gjorde for Henze.\n\nHav det godt, <Name>. Let skinner over dig, og du bør byde det velkommen helhjertet."},
  [1792] = {n="Hvirvelvindsvåben", c="Jeg har hvirvelvindshjertet og er klar til at placere det i dit foretrukne redskab.\n\nVælg dit våben, <Name>, og vid, at dets kraft er Cyklonianerens kraft."},
  [1795] = {n="Det Bindende", l="Brug Kabalens Foliant til at fremkalde og tæmme en felhugger, og bring derefter Kabalens Foliant tilbage til Strahad Farsøn i Skralleby.", d="Hvis du er tilstrækkelig forberedt, så bør vi begynde. Lad mig forklare dig processen.\n\nJeg vil begynde med at skabe den grundlæggende fremkaldelsescirkel. Når den er færdig, bruger mine disciple kanaliseringsstavene til at skabe den større cirkel.\n\nNår det er gjort, læser du besværgelsen fra Kabalens Foliant, og felhuggeren vil blive trukket frem. Vær forsigtig, <Name>. En felhugger er en magtfuld fjende, og jeg vil gerne se dig beholde hovedet på skulderen.", p="Enhver hekser bør have en felhugger til sin rådighed. Selvom den er svær at tæmme, overgår de kræfter, den giver sin herre, langt omkostningen.", c="Jeg må sige, jeg er imponeret, <Name>. Da jeg stod over for min felhugger, slap jeg knap nok med livet i behold. Jeg fornemmer, at du har potentialet til at blive en af denne tidsalders mægtigste hekser."},
  [1796] = {n="Komponenter til den Fortryllede Guldblodkåbe", l="Bring Kåber af Arkana til Menara Tomrumsrivet i Ødemarken.", d="Den første genstand, jeg vil hjælpe dig med at skabe, er en kåbe. Du skal samle tingene til mig, og så sætter vi dem sammen. Bagefter, hvis du lykkes, har du den første af mange genstande, der vil gøre dig stærkere og hjælpe dig i dine kampe.\n\nTil at begynde med skal du have fremstillet Kåber af Arkana. En skrædder kan lave dem til dig, eller du kan måske købe en fra en anden – jeg ville være mest imponeret, hvis du selv kunne lave den – men uanset hvad, bring mig kåberne, så tager vi derfra.", p="Hvordan går det med din eftersøgning efter kåberne, <Name>? Har du lavet dem selv? Sådanne personlige præg gør, synes jeg, indgydelsen af magi endnu sødere. Det giver en større følelse af præstation. Men jeg forstår, hvis du vælger den hurtigere vej og får dem lavet til dig – der er noget at sige til sådan... ambition.", c="Det her duer, <Name>.\n\nAlle magiske genstande skal begynde med en genstand af høj kvalitet. Jo mere anstrengelse og dygtighed, der lægges i en genstand, desto større magi kan den rumme. Sjældne og dyrere komponenter holder magien bedre. Du vil ikke fortryde, at kåberne bliver sat sammen til dem, vi senere laver til dig."},
  [1799] = {n="Fragmenter af Orahels Kugle", l="Tal med Menaras akolytter inde i tårnet over Skralleby, og vælg en af deres veje at følge.\n\nBagefter skal du bringe en Helvedes Kugle til Tabæta i Støvsumpen.", d="Godt, så lad os begynde.\n\nDet første, du skal gøre, er at tale med mine akolytter derinde. Vælg en af deres veje at følge – de vil forklare mere.\n\nDernæst skal du rejse til Forødelse og finde en Helvedes Kugle fra en af hekserne i Mannorok-hekseriet. Det er den kugle, du skal rense med hjælp fra en magiker ved navn Tabæta dybt i det sydlige Støvsump. Hun vil hjælpe dig på grund af vores fælles historie.\n\nKom endelig ikke tilbage, før du har gjort begge de ting, jeg har bedt om.", p="Og da du jo ikke er magiker, undrer jeg mig over, om jeg overhovedet kan stole på dig. Jeg kan lugte arkanmagien på dig, men du ser ud til at have undgået korruptionens stank, som så villigt følger med dit slags.\n\nJa, en <Class>... en <Class> er kommet for at bede om min hjælp.\n\nNå, hvad kan jeg gøre for dig, <Name>?", c="Å, så Menara sendte dig. Fair nok... jeg antager, at du kan blive som min gæst et stykke tid. Men du må have et vigtigt ærinde – måske søger du tabt magt? Måske tager jeg fejl. Måske er korruption ikke så langt væk fra dig alligevel."},
  [1800] = {n="Herrelandes Tronrum", l="Tag dit plejebarn med til det gamle Herrelandes Tronrum, der ligger lige før man træder ned i Underbyen.", d="Forældreløsehjemmets matroner fortæller vilde historier om slag og lærdom om aftenen, hvis vi er gode og laver vores pligter. En historie handlede om, hvordan Herrelande faldt, og om hvordan den onde Arthæus tog sin egen fars liv for at blive hersker.\n\nHan havde ingen ære, <Name>! Når jeg bliver stor og bliver en mægtig Horde-kriger, skal mit sværd styres af ære - aldrig af ondskab!\n\nVil du tage mig med hen og se tronsalen, tak? Den ligger lige før det sted, hvor man skal ned i Underbyen.", p="Er vi der snart?", c="Den tronsal var skræmmende, <Name>! Selvom den var tom, føltes det, som om en stor ondskab havde fundet sted der. Jeg blev gal... men jeg blev også trist. Jeg forstår, hvorfor matronerne fortæller os sådanne historier; jeg vil aldrig svige mit folk på den måde!\n\nTak fordi du tog mig med til tronsalen, <Name>. Jeg lærte meget."},
  [1802] = {n="Kabalens Tykke Bog", l="Hent den muggne tykke bog og det frynsede manuskript til Krom Tykarm i Jernsmede.", d="Den blev væk, men der er en vis idé om, hvor den måske kan findes.\n\nDer blev kun lavet ét eksemplar, og det blev hærget på et tidspunkt, og en stor del af det blev revet ud af bindet. Rygtet siger, at det på en eller anden måde endte i hænderne på kentauren fra Tusindnåle.\n\nResten gik tabt ud for kysten vest for Sydstranden, hvor den skulle fragtes til Menetil-havnen med båd. Den kom aldrig frem.\n\nSom gengæld for denne viden beder jeg om blot dette: Finder du den, så tag den med til mig, så jeg kan se den.", p="Viste rygterne sig at være sande, <Name>?", c="Fantastisk! Nu kan jeg slutte mig til de få, der har spioneret dens indhold.\n\nJeg kan ikke vente med at studere denne tekst yderligere. Dette er en stor dag, <Name>! Hvis du bare lader mig kigge på den, før du går. Jeg er sikker på, at Strahad Farsøn vil være villig til at sende mig en kopi."},
  [1803] = {n="Kabalens Tykke Bog", l="Hent den muggne tykke bog og det frynsede manuskript til Jorah Årsen i Underbyen.", d="Ah! Jeg ser, at du er en hekser med lignende smag som min. Ja, at skaffe Kabalens Tykke Bog er et værdigt mål. Vidste du, at den engang lå inden for Herrelandes mure? Den blev dog hærget, næsten halvdelen af sidene revet ud. Hvem ville begå en så afskyelig handling?\n\nDen halvdel er tabt, men rygtet siger, at den endte i hænderne på kentauren fra Tusindnåle.\n\nResten af teksten skulle overføres til Jernsmede, men gik tabt under transporten ud for kysten vest for Sydstranden.", p="Det kan være, at du jagter eventyr, <Name>, men sandheden kan findes midt i selv de vildeste rygter.", c="Nå nå nå! Hvad har vi her?\n\nDet er imponerende, <Name>. Jeg havde ikke troet det muligt, men her er den i mine egne hænder, den komplette Kabalens Tykke Bog.\n\nLad mig bladre i dens sider et øjeblik, før du drager af sted igen."},
  [1804] = {n="Kabalens Tykke Bog", l="Bring den rekonstruerede tykke bog og 3 kanaliseringsstave til Strahad Farsøn i Skralleby.", d="Tja, øh, det er svært at give slip på den. Men du fandt den, og du har selvfølgelig vigtigere ting at gøre med den. Bare vær venlig og nævn over for Strahad, at jeg gerne ville have en kopi.\n\nMens du var ude, sendte han en besked til dig. Han ville have mig til at fortælle dig, at for at hans disciple kan hjælpe med fremkaldelsen, skal du skaffe tre kanaliseringsstave.\n\nHan ved måske ikke, hvor de findes, men jeg gør! De blev sidst brugt af orkerne i Dragemave-klanen i Sumpene. Jeg ville tjekke deres tryllekunstnere!", p="Har ikke set dig i de kanter i et stykke tid. Har du fundet bogen og stavene?", c="Velgjort! Kabalens Tykke Bog og tre upåklagelige--lidt ridsede, skal jeg vist sige--kanaliseringsstave.\n\nDet her bliver interessant. Det er længe siden, en ung hekser tog sig an af en felhugger for at skabe sin egen."},
  [1805] = {n="Kabalens Tykke Bog", l="Bring den rekonstruerede tykke bog og 3 kanaliseringsstave til Strahad Farsøn i Skralleby.", d="Dette er en af de mest interessante tekster, jeg har studeret de seneste par år. Udvalget her er magert--mest bøger om geografi--og jeg har allerede læst dem alle. Jeg må håbe, at Strahad vil sende mig en kopi af denne tykke bog, når han får chancen.\n\nApropos ham, han sendte bud til mig, mens du var væk. Til din opgave skal du skaffe tre kanaliseringsstave.\n\nFor at du må kigge på denne tekst, vil jeg dele en hemmelighed: Du kan finde stavene hos orkerne i Dragemave-klanen i Sumpene.", p="Ja, <Name>? Hvordan kan jeg være dig til tjeneste?", c="Velgjort! Kabalens Tykke Bog og tre upåklagelige--lidt ridsede, skal jeg vist sige--kanaliseringsstave.\n\nDet her bliver interessant. Det er længe siden, en ung hekser tog sig an af en felhugger for at skabe sin egen."},
  [1818] = {n="Tal med Dillinger", l="Tal med Dødevagt Dillinger i Gryde-by.", d="Jeg har fået at vide, at Dødevagt Dillinger har et job til en som dig. Hvis du er villig til at vise din værdi over for Den Mørke Dames styrker, så mød op hos Dillinger med det samme.\n\nDødevagt Dillingers post ligger i den vestlige ende af Gryde-by, nær kirkegården.", c="Er du her for et hverv? Godt. Jeg har et vigtigt et, og et der vil prøve dine færdigheder i kamp... og din beslutsomhed i forsvaret af De Forladte."},
  [1819] = {n="Ulag Hakkekniv", l="Dræb Ulag Hakkekniv, og tal derefter med Dødevagt Dillinger.", d="Da Svøben fejede gennem Tirisfals Lysninger, fangede vi en for at studere den. Han havde et frit sind, og han kaldte sig selv Ulag Hakkekniv. Men selvom hans vilje var fri, var han stadig fortryllet af Liskekongen.\n\nVi håbede at finde en måde at bryde kongens kontrol over Ulag, men det lykkedes ikke. Nu er det endelig tid til at befri ham.\n\nBefri ham, og dræb ham.\n\nAktivér kraniestens-udløseren nær mausoleet mod nord. Dette vil løfte den magiske forsegling, der binder ham.\n\nSå... vær klar, <Name>.", p="Din opgave er endnu ikke løst, <Name>. Det er ikke klogt for en kriger at vise frygt...", c="Velgjort, <Name>. Ulag var ingen ringe agent for Svøben. Du har vist Dødevagterne, og dermed Den Mørke Dame, at du er en kriger med færdigheder og beslutsomhed, og at du er værdig til videre undervisning."},
  [1820] = {n="Tal med Coleman", l="Tal med Coleman Farding.", d="Du har bevist din værdi over for Den Mørke Dame, nu kan du måske bevise dig selv over for en af hendes undersåtter.\n\nColeman Farding venter på en kriger, der er villig til at være hans redskab til hævn over De Forladtes fjender.\n\nDu finder ham i Galgeenden Kro i den østlige del af Gryde-by.", c="Ja, det er sandt. Jeg har brug for dine færdigheder i kamp. Mine midler er små, men min opgave gavner både mig og De Forladtes sag. Gør det, og din belønning vil være dobbelt."},
  [1821] = {n="Agamand-arvestykker", l="Bring Coleman Farding Agamand-familiens økse, Agamand-familiens sværd, Agamand-familiens kølle og Agamand-familiens dolk.", d="Agamand-familien var mine arbejdsgivere i livet, og de var årsagen til min død! Det passer, at Agamanderne nu er hjernedøde håndlangere for Liskekongen.\n\nNu vil jeg have deres sidste rester af ære. Gå ind i deres familiekrypt og plyndr dem for deres familiearvestykker: et sværd, en økse, en dolk og en kølle. Bring dem til mig!\n\nAgamand-familiens krypt ligger i den nordlige ende af Agamand-møllerne, bevogtet af lurende Svøbe-skabninger og døde Agamander.", p="Har du arvestykkerne, <Name>?", c="Ah! Du fik dem! Nu er den sidste rest af ære og erindring stjålet fra de forbandede Agamand-lande. Familien er virkelig ikke mere!"},
  [1822] = {n="Arvestykkevåben", c="Jeg vil beholde tre af de våben, du bragte tilbage til mig, som minder om min smerte og mit tab. Men vælg venligst, <Name>, din yndlingsarvestykke og behold den for dig selv.\n\nMåtte den tjene dig bedre, end den tjente sine forbandede, tidligere ejere."},
  [1824] = {n="Prøven på Kæmpernes Mark", l="Bring 5 sprællende antenner til Ruga Vredetotem i Taurajo-lejren", d="For at bestå denne prøve skal du rejse sydpå til Kæmpernes Mark. Der vil du finde en hærskare af krybende insektskabninger. De er nye i Ødemarken, og jeg kan ikke lide, hvad de varsler.\n\nBring mig deres stadig sprællende antenner, og spild ikke tiden, <Name>, for afskårne antenner spræller ikke længe. Bring mig antennerne inden for den tid, der er givet, så består du prøven.", p="Har du antennerne? Hvis du har, så giv dem til mig hurtigt, for sprællende antenner spræller ikke evigt...", c="Flot gjort, <Name>! Ved at bestå prøven på Kæmpernes Mark tager du endnu et skridt ad <Class>'ens vej."},
  [1825] = {n="Tal med Thun'grim", l="Tal med Thun'grim Ildblik i Ødemarken.", d="Thun'grim Ildblik, en berømt orkisk smed, har hørt om dine fortsatte heltedåd i Hordens tjeneste. Han vil gerne smede en rustning til dig og beder dig tale med ham med det samme.\n\nThun'grim har slået lejr øst for Korsvejen i Ødemarken.", c="Ja, du er kommet. Det er godt, for vi har meget at tale om, du og jeg."},
  [1840] = {n="Orm Stenhov og den brutale hjelm", l="Tal med Orm Stenhov i Tordenklippe.", d="Orm Stenhov er meget respekteret for sine færdigheder. Han vil lave den brutale hjelm til dig.\n\nSøg ham op i Tordenklippe, nær pølen ved byens store, centrale totem.", c="Hilsner, <Class>. Jeg er Orm, og Thun'grim fortæller mig, at du ønsker en hjelm lavet?"},
  [1841] = {n="Velora Nattesen og de brutale benskinner", l="Tal med Velora Nattesen i Underbyen.", d="Man siger, at Velora Nattesen før sin død var en af de fineste rustningssmede i Herrelande. Døden har tilsyneladende ikke svækket hendes talent. Tal med Velora--hun vil lave dine brutale benskinner.\n\nVelora udøver sit håndværk i Underbyen i Herrelande, i handelskvarteret.", c="Du er her for benrustning? Godt!\n\nÆh... er det mig, der laver rustningen til dig, eller er det dig, der laver den til mig?\n\nDet var en joke. Var den sjov? Jeg kan ikke afgøre det... Jeg mistede min sans for humor samme tid, som jeg mistede min lugtesans. Hvilket var omtrent samtidig med, at jeg holdt op med at ånde."},
  [1842] = {n="Skovbukkehove", l="Bring 7 ukløvede skovbukkehove til Ula'elek i Sen'jin-landsbyen i Durdotar", d="Jeg kan lave dig et par brutale handsker, og stor magi vil de rumme. Men først skal du indsamle denne magi og bringe den til mig.\n\nSatyrerne bor i det nordøstlige Askedalen på grund af skovens kraft. De lever af dens renhed og suger og korrumperer. Du kan se, hvilke Satyrer der har trukket mest af Askedalens magi til sig, på deres opsvulmede, ukløvede hove.\n\nDisse hove rummer stor kraft. Jeg får brug for dem til fremstillingen af dine handsker.", p="Har du hovene, <Name>? Magien i dem er stærk.", c="Ah, du har dem! Nu, ligesom Satyrerne udsugede styrken i Askedalen, vil jeg udsuge kraften, der er i disse hove, og tæmme den til min fremstilling..."},
  [1843] = {n="Brutale Handsker", c="Tak, <Name>. Disse handsker er mit bedste arbejde. Tag dem. Når du bærer dem, bringer du ære til mig og mine forfædre."},
  [1844] = {n="Kimæra-horn", l="Bring et Galvaniseret Horn til Orm Stenhov i Tordenklippe.", d="Jeg vil lave hjelmen til dig, men du må vise mig, at du er værdig til den.\n\nI de nordvestlige udkanter af Stenklippe-bjergene ligger Den Brændte Dal. Den var engang et grønt sted, men nu er den besmittet og askegrå, og de væsner, der er tilbage der, er gale af smerte og fortvivlelse.\n\nDet er ddér, jeg sender dig hen, <Name>.\n\nDu skal tage til Den Brændte Dal og finde en kimæra-matriark. Slå hende ihjel, befri hende for hendes elendighed. Bring mig hendes galvaniserede horn som bevis, så laver jeg hjelmen til dig.", p="Har du hornet? Er matriarken befriet for smerte?", c="Du har fuldført din opgave, <Name>, og vist mig din værdi og beslutsomhed. Hjelmen skal være din..."},
  [1845] = {n="Brutal Hjelm", c="Jeg giver dig denne hjelm.\n\nStore gerninger bragte dig til mig, <Name>, og med Jordmoderens velsignelse... venter endnu større gerninger forude."},
  [1846] = {n="Dragemave-skinneben", l="Bring 8 kraftige Dragemave-skinneben til Velora Nattesen i Underbyen.", d="For at lave de brutale benskinner har jeg brug for et par kraftige skinneben. Dragemave-orkerne i Sumpene har fine, tykke skinneben. Dem får jeg brug for.\n\nMen de skal være kraftige. Husk at teste skinnebenene, mens du samler dem ind. Kan du knække dem med dine bare hænder, er de ikke kraftige nok til at arbejde med.", p="Jeg venter på de skinneben, <Name>. De bliver en god ramme til dine benskinner.", c="Velgjort! Disse ser alle stærke ud. Jeg tror, de vil gøre det helt fint. Hvordan tog orkerne imod, at du tog deres skinneben, <Name>? Klagede de meget?\n\nDet var også en joke. Du griner ikke.\n\nJeg er ikke særlig morsom for tiden, er jeg vel..."},
  [1847] = {n="Brutale Benskinner", c="Her er dine benskinner, <Name>. Lad mig vide, hvordan de passer, eller om du har brug for justeringer. Jeg sigter efter at behage! I hvert fald før i tiden.\n\nI disse dage bekymrer jeg mig ikke meget om mit håndværk. Men det er bedre end at være en hjernedød håndlanger for Svøben!\n\nTror jeg."},
  [1848] = {n="Brutal Brynje", c="Jeg er sikker på, at du udholdt megen modgang og udgød meget blod i min opgave, <Name>. Her er resultatet af dit slid.\n\nMåtte du bære den godt, og måtte du en dag vende tilbage hertil med historier om dens tjeneste for dig."},
  [1858] = {n="Den Splittede Hånd", l="Stjæl Tazaans nøgle, og brug den derefter til at åbne hans Taske og aflever dens indhold til Tyrzok i Skyggeklyngen i Orgrimgrad.", d="Jeg overlader det til dig at få Tazaans taske op og vende tilbage til mig med indholdet. Låsemekanismen er kompleks, så det er nok lettest, hvis du skaffer nøglen.\n\nSiden du ikke fandt den på Tazaans lig, kan jeg kun gå ud fra, at han overlod nøglen til en anden... Ah, ja, det er rigtigt. Han havde en assistent ved navn Gamon. En drankerøv, du finder ham sikkert på krostuen. Måske kunne du stille og roligt aflaste ham for nøglen.", p="Er det ikke irriterende at have genstanden for dit begær inden for rækkevidde, men ingen måde at komme til den på?", c="Hmmm, nu er det interessant. Du har mere end bevist din værdi med dette, <Name>. Jeg er ganske imponeret. Betragt dig selv som Den Splittede Hånds nyeste medlem. Og tag dette, det vil være en stor hjælp for dig i fremtiden, tror jeg."},
  [1859] = {n="Tyrzok", l="Tal med Tyrzok i Skyggeklyngen i Orgrimgrad.", d="Sænk din stemme, <Name>. Jo, jeg kender dit navn. Fik besked på at holde øje med en ork, der passede på din beskrivelse.\n\nAf det, vi har hørt om dig, kan du klare dig i kamp, og du er ikke afvisende over for lidt snigeri fra tid til anden.\n\nHar jeg ret?\n\nUnder alle omstændigheder bør du gå og se Tyrzok i Orgrimgrad. Han har et tilbud, du bør høre.", c="Meget godt, jeg er glad for, at Kaplag fik fat i dig.\n\nVi har nogle ting at tale om, ikke mindst din fremtid med Hånden."},
  [1860] = {n="Tal med Jeneia", l="Tal med Jennea Kanon i Stormvind.", d="Vi magikere har en opgave, der skal udføres. En, der er afgørende for sikkerheden i Stormvind og Elvendal.\n\nJennea Kanon har detaljerne. Hun studerer i troldmandens helligdom i magikerdistriktet i Stormvind. Du bør skynde dig hen til hende.", c="Du er blevet sendt for at hjælpe mig i min opgave, <Name>? Godt. Det er opmuntrende at se unge magikere ivrige efter at hjælpe vores sag...\n\nHvilken sag, spørger du? Med tiden, unge. Du skal få at vide det... med tiden."},
  [1879] = {n="Tal med Bink", l="Tal med Bink i Jernsmede.", d="<Name>! Bink, min gnom-kollega i Jernsmede, sender bud. Hun har en opgave, der skal udføres, og hun vil ikke stole på andre end en magiker til at gøre det! Er du den magiker, <Name>?\n\nHvis du er, så tal med Bink. Hun tilbringer sin tid i Mysteriernes Hal i Jernsmedes Mystiske Afdeling.", c="Åh, jeg kan se, du har løfte, ja, det har du! Men det kræver mere end løfte at være en god magiker. Og er du ikke en god magiker, så er du en dårlig magiker. Og dårlige magikere er en del af problemet, ja, det er de!\n\nOps, jeg løber i forvejen. Lad os begynde fra begyndelsen!"},
  [1884] = {n="Ju-Ju-Dynger", l="Ødelæg 4 Ju-Ju-Dynger, og vend derefter tilbage til Un'thuwa i Sen'jin-landsbyen.", d="Hekseren Zalazane fra Ekkoøerne har forstyrret magiens normale strøm i Durotar. Det gør han gennem besmittede fetisher, ju-ju-dynger, som han har placeret blandt sine hytter på hovedøen Ekko.\n\nDisse dynger korrumperer vores dyreliv og giver kraft til hekseriets mestre og helvedesvæsnerne, der lurer i landets mørke hjørner.\n\nDu må ødelægge ju-ju-dyngerne, <Name>, før magiens strøm bliver ændret for altid.", p="Du må skynde dig, <Name>. Ødelæg ju-ju-dyngerne!", c="Jeg fornemmer, at Zalazanes ju-ju-dynger er blevet ødelagt, og med tid og held vil magiens strøm i Durotar vende tilbage til det normale.\n\nDet er en stor gerning, du har udført for dit folk, <Name>. Og du har vist os din værdi, os magikerne i Horden."},
  [1898] = {n="Dødsstalkerne", l="Tal med Andron Gant i Underbyen.", d="Introduktionsbrevet burde være nok til at overbevise Andron om, at du er den budbringer, han har ventet på. Jeg har mødt Andron før, han har ikke helt den mentale kapacitet til at være så mistænksom.\n\nHerre Varimathras mistænker, at Andron har ydet bistand til en anden gruppe. Han vil gerne vide, hvilken organisation det er, og kræver bevis for det.\n\nJeg vil have dig til at tale med Andron og skaffe disse oplysninger. Du finder ham i hans butik nær Apotekerium.", p="Hej. Kan jeg gøre noget for dig?", c="Ah, ja, jeg har ventet dig. Jeg tvivler ikke på, at vores fælles bekendte er glade for de oplysninger, jeg hidtil har givet?\n\nJeg antager, der er ingen mening i at spørge dig, de ville nok ikke belaste dig med denne viden. Hvorfor sætte så megen tillid til budbringeren, hm?"},
  [1899] = {n="Dødsstalkerne", l="Bring Astors regnskabsbog til Menet Carkad i Skurkekvarteret i Underbyen.", d="Regnskabsbogen med de oplysninger, dine arbejdsgivere søger, finder du på bogreolen bag mig. Lever den med mine hilsner, og fortæl dem, at jeg foretrækker, at de sender dig, hvis de finder nok værdi i at ville fortsætte vores aftale.", p="Lykkedes det, <Name>?", c="Nu, dette er bestemt mere information, end jeg havde regnet med at få ud af Andron. Giv mig et øjeblik til at gennemgå den, før jeg sender dig videre til din næste opgave."},
  [1941] = {n="Manavævskappe", c="Her er din kappe. Det er en af mine bedste lavet indtil nu! Bær den med stolthed, og når folk spørger... så fortæl dem, at du fik den hos Larson Klædehandel!"},
  [1942] = {n="Astral-knudedragt", c="Din dragt er klar! Og den silke, du samlede, var så fin... har du noget imod, at jeg lavede den lidt kort, så jeg kunne have noget silke tilbage til mig selv, ikke?\n\nJeg laver bare sjov. Den passer dig perfekt og vil være ideel både til eventyr og til fine middage. Nyd den!"},
  [1943] = {n="Tal med Deinos", l="Tal med Deinos.", d="Trolmagikeren Deinos har brug for din hjælp, <Name>. Hun bor i Orgrimgrad, i Mørktorn-hytten.", c="Godt, du er kommet. Min opgave er ikke let, men den er vital for magikernes samfund. Hvis du hjælper mig, er jeg sikker på, at du vil finde det umagen værd."},
  [1946] = {n="Nether-blondedragt", c="Her er din nether-blonde, <Name>. Den er både behagelig og holdbar, og den rummer magien fra de lattermilde søstres hår.\n\nNyd den, og hvis du synes godt om den, så nævn det over for Deinos. Hun er en magiker, hvis gunst jeg ønsker at bevare..."},
  [1950] = {n="Få scoopet", l="Find frasen til Tirths kassekiste, og vend derefter tilbage til Tirth.", d="Jeg kan hjælpe dig med bogen, men først må du hjælpe mig!\n\nBogen, du søger, ligger i min magisk låste kassekiste. For at åbne den skal en særlig frase udtales, og jeg kan ikke huske frasen! Normalt hjælper min assistent mig med at huske sådan noget, men han er ingen steder at finde.\n\nHvis du vil have min bog, så find min lærling! Spørg rundt ved væddeløbsbanen—hvis du er heldig, har nogen set ham. Enten slæber du ham tilbage hertil, eller også henter du i det mindste min magiske frase fra ham, så vi kan åbne min kasse!", p="Hvad venter du på? Jeg har brug for min magiske frase!", c="Ah, nu husker jeg...\n\nJeg havde glemt den lille forbandelse, jeg lagde på Jensen. Jeg kan ikke huske, hvorfor jeg gjorde det, men jeg er sikker på, at det var fortjent, den lille utaknemmelige kryster!"},
  [1952] = {n="Magikerens tryllestav", l="Tal med Tabetha efter hendes ritual.", d="Jeg går og laver staverne nu.", c="Her er de tryllestave, jeg har lavet. Vælg den, du vil have!"},
  [1953] = {n="Tilbage til Sumpen", l="Tal med Tabetha.", d="Det er tid, <Name>, for dig at tale med Tabetha... eremitten fra Støvsumpen. Hun vil instruere dig i fremstillingen af et kraftfuldt magikerredskab.\n\nTabethas hytte ligger dybt i Støvsumpen, vest for Theramore.", c="Ah, ja. Er du her for en kugle eller en stav, <Name>? Meget godt. Jeg vil hjælpe dig med at fremstille den.\n\nMen vær advaret—processen er farlig og kan betyde din død.\n\nEller min død. Helt bestemt nogens død...\n\nMen lad os håbe, det er en andens død, hva'?"},
  [1954] = {n="Den Helvedes Kugle", l="Bring en helvedeskugle til Tabetha i Støvsumpen.", d="Det første skridt er at skaffe en kugle med kraft. Hekse fra Brændende Klinge har fine kugler af høj kvalitet... det er en skam, at de har bundet dæmoner i dem! Men det kan vi ordne, det kan vi godt.\n\nGå til Forødelse og snup en helvedeskugle fra en besværger i Brændende Klinge. Du finder besværgere ved Mannorok-hekseriet.\n\nNår du har kuglen, skal du vende tilbage til mig.", p="Har du en helvedeskugle, <Name>?", c="Åh, den er da en flot en! Nej, jeg mener ikke, at den er \"flot\" på samme måde som kold saft er lækkert på en varm dag.\n\nFaktisk er den slet IKKE flot, når jeg tænker over det. Ikke saften. Kuglen!\n\nFokus, <Name>! Vi har brug for, at du er koncentreret, hvis vi skal blive færdige med vores opgave!"},
  [1955] = {n="Eksorcismen", l="Dræb dæmonen i kuglen, og tal derefter med Tabetha.", d="Nu hvor vi har en besværgers kugle, må vi uddrive dæmonen i den. Det kan jeg gøre. Det er den nemme del.\n\nDet er dig, der har det svære job. Det er dig, der skal dræbe dæmonen, når den er ude.\n\nOg du bliver nødt til at være hurtig. Hvis du tager for lang tid, så springer han tilbage i kuglen, og så må vi starte forfra!\n\nSå gør dig klar. Forbered dine stærkeste besværgelser, hold dine eliksirer ved hånden, og find en ven, hvis du har en. For det her bliver ikke pænt.", p="Du bliver nødt til at dræbe den dæmon for at fjerne dens besmittelse fra kuglen, <Name>.", c="Velgjort, <Name>! Du gav den dæmon en lektie, han ikke glemmer lige med det samme.\n\nHan tænker sig nok om to gange, før han stikker sit grimme hoved tilbage i denne verden for at lede efter det dødelige væsen, der slog ham. Sandsynligvis med venner denne gang. Store, skællede venner, der intet hellere ville end at rive dig i små <Race>-stykker.\n\nJeg skræmte dig ikke, gjorde jeg... <Name>?"},
  [1956] = {n="Kraft i Uldaman", l="Hent en kraftkilde af sortglas og bring den til Tabetha i Støvsumpen.", d="Nu hvor dæmonen er fjernet, må vi skaffe en kraftkilde. Desværre er de bedste kraftkilder normalt de ældste og de sværeste at få fat i. Det er underligt, hvordan skæbnen nogle gange kan lide at bide dig, ikke?\n\nSå du bliver nødt til at tage til Uldaman og besejre sortglas-vagtposten derinde. Han er stor, han er sej, og hans kraftkilde rammer hårdt!\n\nJeg ønsker dig held og lykke, <Name>. Og hvis du ikke har held, så ja... det var hyggeligt at kende dig.", p="Har du været i Uldaman, <Name>? Besejrede du sortglas-vagtposten?", c="Gjorde du det? Godt klaret!\n\nJeg snakkede med nogle af mine kolleger, og da dit navn kom på tale, sagde de: \"Du ved, at <Name> da fungerer godt under pres!\"\n\nMen da jeg fortalte dem, at jeg havde sendt dig til Uldaman for at tage fat i sortglas-vagtposten, sagde de, at jeg var tosset! De sagde: \"Tabetha, du er tosset! Der er ingen måde, <Name> kunne klare den vagtpost!\"\n\nOg jeg sagde: \"Vi får se,\" og så sagde de: \"Ja, vi får se...\"\n\nVel viste vi dem da, ikke sandt!"},
  [1957] = {n="Manaudbrud", l="Dræb 12 manaudbrud inden for den tilladte tidsgrænse.", d="Vi er næsten færdige, men dette sidste skridt er det farligste, <Name>.\n\nJeg har den tomme besværgerkugle og er klar til at give den kraft. Det gør vi ved at udnytte energien fra en manarift. Jeg fremkalder en besværgelse, der midlertidigt åbner en rift, hvorfra væsner, manaudbrud, vil strømme ud. Du skal besejre manaudbrudene, og deres kraft vil blive frigivet, hvorefter jeg vil samle den op.\n\nDræber du nok manaudbrud, før riften lukker, vil jeg placere al deres samlede energi i din kugle.", p="Du har ikke dræbt det krævede antal manaudbrud, <Name>.", c="Du gjorde det! Jeg tvivlede aldrig på dig et sekund! Okay, måske kun et sekund, eller to... men i bund og grund tvivlede jeg ikke meget.\n\nÆrligt talt."},
  [1958] = {n="Himmelsk kraft", c="Du burde være stolt af dig selv, <Name>. Mange magikere er faldet for de væsner, du stod over for.\n\nDen Himmelske Kugle er klar. Eller hvis du vil, kan jeg sætte den oven på en stav. Det er op til dig. Jeg foretrækker kuglen, men hvem er jeg til at dømme?"},
  [1959] = {n="Rapportér til Anastasia", l="Tal med Anastasia Hjortekilde.", d="Magikerne i Underbyen har bemærket en magisk forstyrrelse i byen og har sendt bud efter magikere fra Horden for at undersøge sagen.\n\nAnastasia Hjortekilde kan fortælle dig mere. Tal med hende i Magikvarteret i Underbyen.", c="Det er sandt. En magisk forstyrrelse er blevet registreret i vores by. Vi er endnu ikke sikre på dens oprindelse, eller om den er ond eller god. Vi må først samle mere information...\n\nOg det, <Name>, fører os til din opgave."},
  [1962] = {n="Besværgelsesildskapper", c="Her er dine kapper, <Name>. Bær dem godt."},
  [1963] = {n="Den Splintrede Hånd", l="Dræb Tazan og bring hans taske til Therzok i Skyggeklyngen i Orgrimgrad.", d="Krigshøvdingen er for subtil i sine metoder. Han er forsigtig med at udløse Hordens styrke. Engang var vi stærkere, alle mægtige erobrere. Den stolthed må vi genvinde, og Den Splintrede Hånd vil gøre det.\n\nVi bygger styrke fra skyggerne og slår mod de udsatte, og lægger i al hemmelighed vores fjender ned. En opgave, du må udføre for mig for at bevise din værdi.\n\nTrolden Tazan handler med pirater nær Skralleby. Han har information, jeg må have. Dræb ham og bring mig hans taske.", p="Det er en tosse, der tror, at et angreb med øksen fremme er farligere end en kniv i mørket.", c="Hm, selvom jeg er glad for at høre, at Tazan ikke længere er iblandt os, gør en låst taske ingen nytte. Vi har brug for den information, der er gemt indeni.\n\nDette bør vise sig at være en værdig anden prøvelse for den, der ønsker at slutte sig til Den Splintrede Hånd."},
  [1978] = {n="Dødsstalkerne", l="Lever Androns regnskabsbog til Varimathras i Den Mørke Damens Hal i Underbyen.", d="Syndikatet? Det havde jeg aldrig mistænkt. Det ser ud til, at Alteraz' herrer er faldet langt i årene efter deres forræderi.\n\nHerre Varimathras vil glæde sig over at høre dette, og da du var så afgørende for denne opdagelse, ville det passe, hvis det var dig, der leverede det til ham.\n\nÅh, og hvordan kunne jeg glemme det?\n\nVelkommen til Dødsstalkerne.", p="Ja?", c="Hmm, det her er interessant. Dødsstalkerne har udført deres pligter prisværdigt med at grave dette frem.\n\nSå vidt jeg forstår, fortjener du også anerkendelse for din indsats. Jeg håber, at dette bliver rutine for dig, <Name>, mine Dødsstalkere har altid brug for en god mand."},
  [1999] = {n="Fagets værktøj", l="Find Dalarns statusrapport og bring den tilbage til Menet Carkad i Skurkekvarteret i Underbyen.", d="Troldmændene fra Kirin Tårn i Ambermølle har gemt vigtige dokumenter om Dalarns nuværende tilstand væk. Det ved vi fra en af vores fangers tilståelser. Herre Varimathras har lagt opgaven med at hente dem i Dødsstalkernes hænder.\n\nDenne opgave falder på dig, <Name>. Du får dog brug for noget udstyr og kendskab til låseoplukning. Tal med Estelle Gendry, vores udstyrsmand, og bed hende om et sæt værktøj, før du drager af sted.", p="Har du fundet dokumenterne, <Name>?", c="Meget godt, <Name>! Du har lært låseoplukningens fine kunst godt, og hurtigere, end jeg nogensinde havde forventet.\n\nJeg kan se, at jeg havde ret i at sætte min lid til dig. Tro mig, knægt, jeg kan se, at du vil nå langt i denne branche."},
  [2139] = {n="Tharnariuns Håb", l="Find og dræb Hulemoderen.", d="Vores folks og landes overlevelse kommer med uheldige omkostninger, <Name>.\n\nDu har udgydt naturens tjeneres blod; mange syge dyr har du fældet. Folket i Auberdin står i gæld til dig, for skovens smerte er lindret - om blot for et øjeblik.\n\nJeg har en sidste opgave til dig, men vær advaret, du bliver nødt til at dræbe igen. Mit håb er, at dette bliver sidste gang, jeg kalder på dig, <Name>.\n\nI en hule mod nordøst, nær Bashalhand, residerer Hulemoderen. Slå hende ihjel.", p="Med den smittede Hulemoder slået ihjel, bliver bestanden af Rabiate Tidselbjørne, der kommer ind i vores land, mindre. Spild ingen tid, <Name>.", c="Du har kæmpet for Auberdin med mod og ære, <Name>. I vores krigshærgede lande er død og fortvivlelse almindeligt. Mange vil ikke rejse sig for at møde udfordringerne i vores nye hjem, og vælger i stedet at gemme sig i deres huse eller flygte til de mere befæstede lande i Alliancen.\n\nTak, <Name>. Måske kæmper vi snart side om side som kammerater mod en anden fjende."},
  [2159] = {n="Dolanår-leveringen", l="Bring Dolanår-leveringen til Krovært Kildemyr.", d="Hilsner, unge <Class>. Kan du tilbyde mig din hjælp? Jeg har en pakke urter, som jeg må levere til byen Dolanår. Men jeg har stadig forretninger med druiderne i Skyggedalen og kan endnu ikke forlade stedet.\n\nKan du levere denne pakke for mig? Den skal sendes til Krovært Kildemyr, på kroen i Dolanår. Den ligger langs vejen, mod syd.", p="Hvordan kan jeg være dig til tjeneste, unge ven? Er du her for at hvile dig på kroen? Har du brug for en hjemsten?", c="Ah ja, leveringen af urter fra Skyggedalen. Det er en skam, at Porthannius ikke selv kunne bringe dem, for vi har meget at drøfte, han og jeg. Men jeg er glad for at få urterne alligevel, og jeg er glad for, at du kom.\n\nMens du er her, så vær venlig at hvile dig. Helte må holde deres styrke og humør oppe, og må finde hvile og trøst, når de kan. For at forsømme ens fred for krop og sind er en sikker vej til fiasko.\n\nSå... hvil dig."},
  [2178] = {n="Nemt Løberliv", l="Bring 5 løberkød tilbage til Alanndarian Nattesang i Auberdin.", d="Kan du lugte den dejlige aroma? Det er min hemmelige opskrift, <Name>--frisk løbergryde. Lækkert!\n\nMåske har du lyst til at lære opskriften?\n\nFør jeg lærer dig opskriften, må du bevise, at du kan håndtere bæsterne.\n\nNu forventer jeg ikke, at du tæmmer en og rider den tilbage til mig, men hvis du kan dræbe nogle få og bringe noget af deres saftige kød tilbage, kan jeg måske lade mig overtale til at vise dig løbergrydens veje.", p="Gryden er tom, og jeg er sulten! Hvad er det, der tager så lang tid?", c="Fantastisk! Prøv den og fortæl mig, hvad du synes, <Name>!"},
  [2198] = {n="Den Splintrede Halskæde", l="Søg efter den oprindelige skaber af den splintrede halskæde for at lære om dens potentielle værdi.", d="Du har fundet en anløben halskæde, men anløbningen skjuler intrikat og magisk håndværk. Halskæden er splintret, da dens indfatning ser ud til at mangle tre ædelsten. På undersiden af halskæden er det svage aftryk af Jernsmedes bysegl. Under seglet står tre små, indgraverede bogstaver: \"TdK\".\n\nHvis der er noget at hente fra halskæden, må du lære om dens oprindelse. Måske er seglet og initialerne en begyndelse...", p="Du har fat i den forkerte gnom, makker! Jeg var aldrig der! Du kan ikke bevise noget!\n\nVent lige et øjeblik... hvem er du? Hvad... hvor fandt du den halskæde henne?", c="Ja... jeg er juvelerer, der lavede denne halskæde. Jeg driver heller ikke forretning med at give information ud, som om den var gratis. Information er aldrig gratis, ven. Hvis jeg skal hjælpe dig, må du hjælpe MIG først."},
  [2199] = {n="Viden for en pris", l="Bring fem sølvbarrer til Talvash del Kissel i Jernsmede.", d="Jeg er en juvelerer med stor berømmelse her i Jernsmede! Nå, tidligere berømmelse da... jeg er havnet i hårde tider på grund af en konkurrents spidsfindigheder! Et dårligt ry i denne branche betyder økonomisk katastrofe. Derfor står jeg nu uden en eneste kobber til mit gode, men nu besudlede navn.\n\nJeg vil have, at du skaffer mig fem sølvbarrer, så jeg kan færdiggøre en ordre, jeg har fået - den første i, hvad der synes at være en evighed.\n\nHvis du skaffer mig de fem sølvbarrer, så besvarer jeg dine spørgsmål om halskæden.", p="Har du de fem sølvbarrer, jeg bad om? Jeg vil dele min triste historie om den halskæde, du nu har... men først efter jeg har fået de barrer! Vær sød, hjælp en gnom, vil du ikke?", c="Du er okay i min bog; jeg er ligeglad med, hvad alle andre har sagt... jeg driller! Seriøst, tak, min ven.\n\nNu, halskæden, du har, er et af mine fineste værker, men den mangler tre ædelsten, der hjælper med at binde magisk kraft til den. Jeg lavede den til en paladin for noget tid siden. Han var på en selvvalgt mission for at rydde den \"onde besmittelse\" væk fra en udgravningsplads i Ødelandene kaldet Uldaman.\n\nNå... den paladin døde i Uldaman, og det var kun begyndelsen på mine problemer."},
  [2200] = {n="Tilbage til Ulddaman", l="Søg efter spor om, hvor Talvashs halskæde befinder sig lige nu i Ulddaman. Den dræbte paladin, han nævnte, var den sidste, der havde den.", d="En konkurrent af mig startede et rygte om, at min halskæde forbandede paladinen. Det siger sig selv, at ingen vil købe forbandede smykker hos en juveler.\n\n<Name>, jeg foreslår en handel - find ædelstenene, så sætter jeg halskæden sammen igen, bare du reklamerer for, at jeg IKKE laver forbandede genstande!\n\nProv at lede efter spor i Ulddaman; måske ligger paladinens lig dernede, for han er jo den, vi ved havde den sidst! Når du finder ædelstenene, skal du bruge dette; det gør det muligt at kontakte mig her i Jernsmede.", c="Rester af en paladin: Dagbogen afslører, at paladinen efter megen møje havde fundet placeringen af alle tre savnede ædelsten:\n\nSkyggesmedjens dværge gemte rubinen i deres barrikaderede område, mens de kæmpede mod Gravkryberne om kontrollen over Ulddaman.\n\nGravkryberne gemte topasen i en urne placeret ved nogle usædvanlige indbyggere i Ulddaman - Alliancens dværge!\n\nTil sidst tog gravkryber-ældsten selv safiren som sin egen."},
  [2201] = {n="Find Ædelstenene", l="Find rubinen, safiren og topasen, der er spredt rundt i Ulddaman. Når du har dem, skal du kontakte Talvash del Gelé på afstand ved hjælp af Spejlfiolen, som han tidligere gav dig.\n\nFra dagbogen ved du...\n* Rubinen er gemt i et barrikaderet Skyggesmedje-område.\n* Topasen er gemt i en urne i et af Gravkrybernes områder, nær nogle Alliance-dværge.\n\n* Safiren er blevet taget af Grumlok, gravkryber-lederen.", d="Paladinens dagbog har måske givet de eneste spor, Ulddaman vil give om halskædens ædelstenes placering. Hvis paladinens nedskrevne oplysninger stadig er korrekte, må Skyggesmedjens dværge og gravkryberne, der kæmper om kontrollen over udgravningsstedet, tages i opløbet.\n\nMed denne viden i hånden begynder jagten på ædelstenene for alvor. Når alle ædelstenene er fundet, skal Talvash i Jernsmede underrettes via Spejlfiolen, som han har instrueret.", p="Talvashs billede træder frem af vandet i spejlskålen.\n\n\"Wow, du er stadig i live! Fik du fat i ædelstenene? Er du virkelig den frelser for mit ry, jeg har håbet på? Fortæl mig venligst, at du ikke spildte en ladning på fiolen bare for at snakke; de ting er IKKE billige, og jeg er allerede i alvorlig økonomisk nød.", c="Jep, det er de tre ædelsten. Godt arbejde! Desværre er dit arbejde ikke helt færdigt endnu.\n\nNej, jeg prøver ikke at snyde dig her, dumme <Class>. Det her handler om at lave magiske smykker - smykker af Talvash del Gelé-kvalitet! Du skal bruge en stærk energikilde for at give dem lidt mere kraft. Ja, og den halskæde har ikke mere kraft at give."},
  [2202] = {n="Ulddaman-reagensløbet", l="Bring 12 magentafarvede svampehætter til Jarkal Mosgrød i Kargat.", d="Jeg har hørt om en nyopdaget plante ved navn magentafarvede svampehætter. De vokser i klynger, dybt inde i Ulddamans udgravningsplads; de findes måske andre steder, men indtil videre er det det eneste sted, jeg kender til. Jeg vil studere deres potentiale i alkymi, og det er der, du kommer ind i billedet.\n\nFind klyngerne af magentafarvede hætter og bring mig et dusin hætter. Vær advaret, klyngerne kan sprøjte giftige sporer ud, hvis de bliver rystet.\n\nGør dette for mig, så mikser jeg en portion af en af mine berømte genoprettende eliksirer til dig!", p="Har du fået de magentafarvede svampehætter, jeg har brug for til mit alkymiske arbejde? Ingen hætter - ingen belønning!", c="Velgjort <Name>, du har endnu engang bevist din værdi! Hætterne bliver et interessant studieobjekt, det kan du tro.\n\nOg nu, som lovet, så smag på en af mine kraftigere genoprettende brygge fra mit eget lager...\n\nHvis du er en dygtig alkymist, så har vi måske noget mere forretning at tage os af. Uanset hvad, takker jeg dig for din hjælp!"},
  [2203] = {n="Reagensløbet i Ødelandene II", l="Brug de tomme thaumaturgiske kar på forkullede vogterdrager, der findes i Ødelandene. Når du har fyldt dem, skal du bringe dem til Jarkal Mosgrød i Kargat.", d="Du har været meget hjælpsom over for mig, <Class>. Jeg ville belønne dig med selve opskriften på den brygge, jeg gav dig tidligere... men jeg vil bede dig om en opgave, der er ganske farlig. Hør min anmodning.\n\nDenne låsbare kasse indeholder tre tomme thaumaturgiske kar; de er gennemsyret af en afstemningsglorie, der vil tappe blodet fra en forkullet vogterdrage. Hvis du bruger et på uhyret, vil det blive meget vredt, så vær advaret. Når du har fyldt alle tre, skal du bringe dem til mig.\n\nGør dette, og opskriften er din.", p="Har du brugt karrene til at skaffe mig det forkullede vogterdrageblod, jeg har brug for? Ja, jeg ved godt, det er en farlig opgave... men opskriften på min genoprettende brygge venter på din succes. Risiko og belønning, min ven... risiko og belønning...", c="Fra en alkymist til en anden, hylder jeg dig. Her, tag denne opskrift og indprent den i din viden. Må den bringe dig den succes og de belønninger, den har bragt mig gennem årene."},
  [2204] = {n="Genopretter Halskæden", l="Skaf en energikilde fra den kraftigste konstruktion, du kan finde i Ulddaman, og lever den til Talvash del Gelé i Jernsmede.", d="Du skal finde noget \"kraft\" til halskæden, og Ulddaman er nok det bedste sted til det, faktisk. Jeg regner med, at der løber en masse konstruktioner rundt derinde, ikke? Nå, tag den største, værste konstruktion i det sted og tag dens energikilde! Jeg er ret sikker på, at jeg kan smelte den kilde ind i halskæden.\n\nUden den energikilde er det umuligt at reparere halskæden. Kom tilbage til mig her i Jernsmede, når du har den, så får vi det hele fikset til dig!", p="Du nåede ikke engang at gøre dig præsentabel, efter du forlod Ulddaman, vel? Du kom bare lige herhen, og kældrenes lugt må du bare tåle. Lad os håbe, at dette besøg kun er lugtende og ikke også ubrugeligt.\n\nHar du energikilden til halskæden?", c="Nå, jeg må sige - jeg er glad for at se dig og denne energikilde i god behold. Det vil tage mig et øjeblik at smelte energikilden sammen med halskæden magisk, nu hvor ædelstenene er blevet genforenet med den. Når det er gjort, bliver halskæden din!\n\nDu er spændt, ikke? Helt prikkende af forventning? Hvor lagde jeg nu den besværgelsesfokus..."},
  [2205] = {n="Søg EF:7", l="Lever Keryn Skovius' pakke til Mester Mathias Skaw i Stormvind-kasernen.", d="Mærket? Åh, det er ingenting, fisk - intet du kunne klare alligevel. Ud fra dit udseende ville jeg sige, at Mathias sandsynligvis vil tage dig for at være ostebuddet frem for en ordentlig snigmorder. Uanset hvad, er jeg blevet tildelt et job, og jeg har lovet at levere på det job.\n\nApropos, lever denne pakke til Mathias, så giver han dig måske en lille opgave eller to.\n\nSkynd dig.", p="Kan jeg hjælpe dig, <Class>?", c="Du fandt mig - og ud fra dit udseende ville jeg sige, at løbeturen og den efterfølgende søgning må have været en stor belastning for dit system, både mentalt og fysisk.\n\nVil du have, at Renzik viser dig vej til en kro, eller er du klar til noget arbejde?"},
  [2218] = {n="Vejen til Frelse", l="Tal med Hulfdan Sortskæg i Jernsmede.", d="Endnu en tabt sjæl, der leder efter vejledning, hva'? Jeg regner med, at du vil finde et formål - dit formål. Jeg har set det tusind gange, endnu en helt på jagt efter arbejde.\n\nNå, i dag er din heldige dag, ven. Hogrål har kuren mod din plage.\n\nSådan gør du: Tag vejen herfra op til Jernsmede og gør dig vej til Det Forladte Hulrum. Når du er der, skal du finde tyvenes lav og tale med Hulfdan Sortskæg. Han sætter dig på vejen til frelse.", c="Så du tror, du er en rigtig skurk? Bestemt til at være en af Sortskægs udvalgte - en officer i Den Skjulte Kreds?\n\nKun en god-for-intet kujon ville tænke så højt om sig selv.\n\nPræcis det, vi leder efter! Velkommen om bord, <Name>!"},
  [2238] = {n="Simpel Underfundighed'", l="Find Onin Hammersen ved Nisseborgen.", d="Se, kongen minedriver stenbruddet efter malm og ædelsten. Mere rigdom, end nogen dværg burde se på ti levetider.\n\nDen Skjulte Kreds har værdier, <Name>. Vi værdsætter værdisager. Kan du forstå det?\n\nNu mener vi, at kongen burde dele noget af det bytte, men vi vil ikke have gamle 'Stinkeskæg' til at vide, at han deler - hvis du forstår mig.\n\nVi har brug for, at du taler med Onin Hammersen nede ved Nisseborgen og bringer en rapport tilbage. Den snedige dværg har gemt sig blandt spedalskhedsgnomerne. Vær forsigtig.", c="Shhh! Hold lige din mund, din tossede tølper. De kan høre os."},
  [2239] = {n="Onins Rapport", l="Tag Onins Rapport med tilbage til Hulfdan i Jernsmede.", d="Stenbruddet? Jep, jeg ser de enorme pansrede dampvogne køre forbi denne post næsten hver dag.\n\nMine kontakter mod øst fortæller mig, at vognen starter i Jernsmede, henter last ved Gol'Bolar-stenbruddet, stopper i Kharanøs for at tanke op og tager så af en eller anden forbandet grund den lange vej rundt forbi Nisseborgen, før den når Jernsmede for at aflevere forsendelsen.\n\nDet står alt sammen i rapporten, <Race>. Tag den med tilbage til Hulfdan, så han kan planlægge næste skridt.", p="Nød du lugten af spedalsk gnom? Jeg spørger kun, fordi du har et skørt smil på læben.\n\nHvilke nyheder bringer du fra Onin?", c="Lang vej? I mit eget skæg!\n\nDu klarede det godt, <Name>. Tag denne dolk og forsvind. Cirklen vil kalde på dig igen, når trin tre er klar til at blive sat i gang.\n\nHvad er trin tre? Det kommer lige efter trin to - at jeg sætter min støvle i din bagdel.\n\nInteresseret?"},
  [2240] = {n="Det Skjulte Kammer", l="Læs Bælogs dagbog, udforsk det skjulte kammer, og rapportér derefter til Prospektor Stormspids.", d="Nu til den opgave, der ligger foran os.\n\nDer er et hemmeligt kammer, Khaz'møls Kammer, som skal udforskes. Problemet er, at kammeret er bag en enorm, låst dør! Det er heldigt, at jeg ved, hvordan man åbner den.\n\nJeg har beskrevet alt i min dagbog, her på bordet. Mit band og jeg sidder fast her indtil videre... så du, <Name>, må finde Khaz'møls kammer for os!\n\nLæs min dagbog, udforsk kammeret, og rapportér derefter til Prospektor Stormspids i Opdagelsesrejsende-Ligaen i Jernsmede.", p="Har du noget at rapportere?", c="Har du set Khaz'møls Kammer? Fantastisk! Bælog var sikker på, at det eksisterede, men jeg må indrømme, at jeg havde mine tvivl.\n\nTak, <Name>. Forhåbentlig vil din opdagelse få vores ledere til at fornye bestræbelserne på at generobre Ulddaman. Og hvis det nogensinde igen står under Jernsmedes kontrol, så vil hemmelighederne i Khaz'møls Kammer være vores!"},
  [2241] = {n="Æblet Falder", l="Tag Janoks Rose til Syrna i Darnassos.", d="De siger, at jeg er 'forelsket', hvad det så end betyder.\n\nJo, jeg bruger hvert vågent øjeblik på at tænke på Syrna. Jo, mit hjem er fyldt med malerier og tegninger af Syrna. Jo, jeg går ofte flere dage uden at spise, sove eller drikke, mens jeg sørger over den kærlighed, vi kunne have haft. Er det så forkert?\n\nNu vil hun ikke se mig! MIG! Jeg har prøvet at sende hende beskeder, men hun vil ikke engang tale med andre, medmindre de er snigmordere.\n\nKunne du levere denne blomst til hende? Glem ikke at fortælle hende, at den er fra Janok.", p="Åh, er det ikke vidunderligt. Du har bragt blomster til din egen begravelse.", c="Havde jeg gemt hver eneste blomst, den tølpe Janok har sendt mig, havde jeg haft midlerne til at åbne en butik. Men uanset hvad, ser det ud til, at Janoks seneste kurer måske viser sig at være nyttig.\n\nInteresseret i noget arbejde, <Class>?"},
  [2242] = {n="Skæbnen Kalder", l="Find Sethir den Oldtidige og bring alle spor, du måtte opdage, tilbage til Syrna.", d="Vi tror, at der findes ét væsen, der kan hjælpe os med at forstå, hvad der sker med skovene i Tældrassil. Desværre har det vist sig katastrofalt at få skabningen til at samarbejde.\n\nHan gemmer sig på en gren i udkanten af Orakellunden. Alle, der hidtil har nærmet sig satyren, hvad enten med magt eller diplomati, er mødt med død. Måske er snigenhed svaret, <Name>.\n\nFind ud af, hvad Sethir den Oldtidige bærer i sine tasker, og rapportér tilbage til mig.", p="Har du noget at rapportere fra Sethir den Oldtidige, <Name>?", c="Det er dystre nyheder, <Name>. Det ser ud til, at sygdommen, der har grebet skovene og floderne i Mørkekysten, er begyndt at forgifte vores hjem.\n\nDu har tjent os godt, men der er intet mere, du kan gøre her. Tag dette blad som belønning for din tjeneste for Tældrassil."},
  [2258] = {n="Reagensløbet i Ødelandene", l="Bring 5 musvågemuskelmaver, 10 Klippekojote-hugtænder og 5 stenelementar-skår til Jarkal Mosgrød i Kargat, Ødelandene.", d="<Name>, jeg kunne bruge din hjælp, hvis du er med på det. Jeg er en alkymist af en vis betydning, og jeg søger din hjælp til at skaffe nogle reagenser, der findes ude i Ødelandene.\n\nJeg har brug for følgende ting for at genopfylde mine lagre: fem musvågemuskelmaver, ti klippekojote-hugtænder og fem stenelementar-skår. Naturligvis kan du få dem fra selve udyrene; hvis du ikke er den kæmpende type, så find venner, der er det.\n\nSkaf mig disse ting, så får du lidt mønter ud af handlen. Hvad siger du?", p="Har du fået de ting, jeg skal bruge endnu? Du får ikke betaling, medmindre du bringer mig de reagenser.", c="Ah, godt klaret! Disse burde række mig lidt, i hvert fald for en stund. Her er din betaling, som lovet.\n\nHvis du er interesseret, har jeg nogle flere reagenser, jeg kunne bruge. Disse findes dog kun i dybet af Ulddamans udgravning. De bliver ikke nemme at skaffe, men jeg vil gøre det umagen værd, hvis du er interesseret i at hjælpe mig igen.\n\nMåske noget mere end nogle blanke mønter, ja?"},
  [2259] = {n="Erion Skyggehvisker", l="Kontakt Erion Skyggehvisker i Darnassos.", d="Vær ikke bekymret, <Name>, jeg sender dig ikke for at se Syrna. Erion kræver din tilstedeværelse i Cenarion-enklaven. Skynd dig!", c="Det er tid til at brede dine vinger, <Race> - verden venter."},
  [2260] = {n="Erions Befaling", l="Rejs til Stormvind By og søg råd hos Renzik \"Kniven\".", d="Nyheden om dine bedrifter har spredt sig vidt og bredt, <Name>. Så vidt faktisk, at Stormvinds Efterretning har bedt om dig ved navn.\n\nRejsen er krævende og ikke uden fare, men en mulighed for at træne under EF:7 bør ikke tages let på.\n\nEn ny verden venter dig, <Name>. Gør dig vej til Gamlebyen i Stormvind og tal med Renzik \"Kniven\" i EF:7's hovedkvarter.", c="Du har svaret på EF:7's kald, <Name>, og rejst fra fjerne kyster for at slutte dig til vores rækker, men der er meget, du skal lære."},
  [2278] = {n="Platinskiverne", l="Tal med stenvagten og lær, hvilken oldtidsviden den gemmer på. Når du har lært, hvad den har at byde på, skal du aktivere Norgannøns Skiver.", d="Centrum i dette skatkammer er fire enorme platinskiver, hver prydet med talrige sigiler af ukendt oprindelse. Når man rører ved dem, prikker det i hånden. Lige efter at have rørt skiverne springer et stort stenvagtansigt frem.\n\n\"Hilsen. Jeg er en vogter af viden. Skabernes syntese af Jordvæsnerne er blevet nedskrevet og gemt her for denne verden i Norgannøns Skiver.\"\n\nDu har afdækket en rigdom af hidtil ukendt verdensviden!", p="Stenvagtens stemme synes at genlyde i dit inderste væsen:\n\n\"Du må først opfylde Norgannøns Skivers forudsætning om dataassimilation; når du har opfyldt dette krav, får du lov til at få en bærbar version af de lagrede data. Sørg for, at du har udforsket informationen i dette arkiv grundigt først.\"", c="Efter stenvagtens instrukser får du endnu engang adgang til Norgannøns Skiver nu, hvor du har lært om Jordvæsnernes, gravkrybernes og dværgenes historie. Et svagt, kort summen høres inde fra skiverne. Stenvagten taler så:\n\n\"Skiverne er nu syntetiseret. Få adgang til Norgannøns Skiver endnu en gang for at modtage din personlige kopi.\""},
  [2279] = {n="Platinskiverne", l="Tag den miniature udgave af Norgannøns Skiver til Opdagelsesrejsende-Ligaen i Jernsmede.", d="Når man rører ved Norgannøns Skiver endnu en gang, prikker det i hånden. Denne gang høres dog en mærkelig knasende lyd inde fra skiverne.\n\nDin rygsæk bliver pludselig tungere end før. Inde i den opdager du en miniature-udgave af skiverne!\n\nUtvivlsomt ville en genstand af denne slags være uvurderlig for nogen, der er interesseret i Azerots oldtidshistorie. Opdagelsesrejsende-Ligaen i Jernsmede er en sådan gruppe, kendt i hele Alliancen; måske kan de gøre god brug af den.", p="Ja, kan jeg hjælpe dig med noget? Jeg forsikrer dig om, at jeg er meget travl lige nu. Hvis det er af stor vigtighed for Opdagelsesrejsende-Ligaen, så er jeg helt øre!", c="Hvad har du dér... åh, min. Hvor fandt du den?\n\nNej, virkelig?\n\nHvem talte du med om hvad?\n\nNEJ, VIRKELIG?!\n\nMin gode <Class>, du har måske lige gjort årets arkæologiske fund! Ved Guderne, hvem er jeg til at tage fejl - århundredets fund! Hvis disse skiver er, hvad jeg tror, så kunne dette være den nøgle, vi har ledt efter! Det kan meget vel endegyldigt bevise dværgenes fortryllede skabelses legitimitet!"},
  [2280] = {n="Platinskiverne", l="Tag den miniature udgave af Norgannøns Skiver til en af vismændene i Tordenskrænten.", d="Når man rører ved Norgannøns Skiver endnu en gang, prikker det i hånden. Denne gang høres dog en mærkelig knasende lyd inde fra skiverne.\n\nDin rygsæk bliver pludselig tungere end før. Inde i den opdager du en miniature-udgave af skiverne!\n\nUtvivlsomt ville en genstand af denne slags være uvurderlig for nogen, der er interesseret i Azerots oldtidshistorie. Vismændene i Tordenskrænten er sådanne historikere, kendt i hele Horden; måske kan de gøre god brug af den.", p="Ja, unge du, jeg ser dig marchere ind i mit telt med intensitet i skridtet... med beslutsomhed i dit formål. Søger du mit råd i en sag af stor vigtighed for Horden? Eller ønsker du måske, at et mysterium i universet åbenbares for dig?", c="Hvad er det her så?\n\nImponerende, unge du! Disse skiver - i dem fornemmer jeg hemmeligheder, som jorden har holdt fast i gennem mange år. Du var meget klog til at bringe dem hertil til mig."},
  [2283] = {n="Halskædebjærgning", l="Find en værdifuld halskæde i Ulddamans udgravningsplads og bring den tilbage til Dran Droffers i Orgrimgrad. Halskæden kan være beskadiget.", d="Vi har et job til dig, hvis du har mod nok til at gøre det!\n\nDybt inde i Ødelandene ligger Ulddamans udgravningsplads. Vi har hørt en historie om en idiotisk paladin, der døde der for nylig. Grunden til, at vi overhovedet bekymrer os, er, at han havde en meget værdifuld halskæde på sig. Den skulle have tre store ædelsten: en rubin, en safir og en topas.\n\nSagen er den: Vi vil have den, og vi betaler TOP-SØLV for at få den. Den kan være beskadiget, men det er hverken her eller der; vi reparerer alle ridser på den.", p="Nå, har du halskæden? Du får ikke en kobberskilling fra os, hvis du ikke har den halskæde!", c="Mmmm, bjærgning! Jeg kan lugte halskæden herfra. Lad os nu se på den skønhed...\n\nHov, hvad tror du, du laver her? Denne halskæde mangler ædelstenene! Tror du, vi ikke ville bemærke det? Selv Mallond kunne se, at ædelstenene er væk.\n\nNå, måske stjal du dem ikke... men denne halskæde er værdiløs uden de ædelsten! Dit job er ikke færdigt endnu, langt fra!"},
  [2284] = {n="Halskædebjærgning, Gang 2", l="Find et spor til ædelstenenes opholdssted i dybet af Ulddaman.", d="Lige så sikkert som Mallond er en tølpe, så er ædelstenene stadig et sted i Ulddaman. Du bliver nødt til at tage tilbage derhen og lede efter dem.\n\nSom jeg sagde før: Hvis de oplysninger, vi har, er korrekte, så er der en rubin, en safir og en topas, der hører til halskæden. Find dem og sæt dem i halskæden.\n\nHvor ædelstenene er, ved ingen - måske får du held og finder paladinens lig. Hvis han ikke allerede er blevet plyndret, så har han måske stadig dem på sig.", c="Du ser ud til at have fundet resterne af den paladin, Dran nævnte tidligere. Ved at undersøge resterne opdager du, hvad der ser ud til at være hans dagbog. Bogen er i dårlig stand, da tørret blod har plettet det meste af teksten. Det, du kan læse, er dog volapyk; det er skrevet på menneskenes modersmål, så vidt du ved.\n\nDu skal have bogen oversat, hvis du skal udlede nogen viden af den."},
  [2298] = {n="Kongelig Rystelse", l="Rejs til Stormvind og søg Renzik \"Kniven\".", d="Så der var vi, klar til at begynde at planlægge fase III, da et par af Magnis tosser kom stormende herind og snakkede om et eller andet kup og anholdelsen af nogle af Den Skjulte Kreds.\n\nNå, ingen sætter jernene på gamle Sortskæg! Diskussionen blev hed og tyk, og på en eller anden måde blev dit navn udslynget!\n\nMit råd? Tag den første gryfon ud af Jernsmede og kom til Stormvind. Kom dig til Gamlebyen, og når du er der, så tal med en gammel ven af mig, ved navn Renzik \"Kniven\".", c="Det er altid godt at have en af Hulfdans snigmordere blandt vores rækker!"},
  [2299] = {n="Til Hulfdan!", l="Rejs til Jernsmede og tal med Hulfdan Sortskæg.", d="Hvor har du været, <Name>? Hulfdan har kigget overalt efter dig. Vi troede, at kongen måske havde sat dig i jern.\n\nKom til Jernsmede så hurtigt som muligt og tal med Hulfdan!", c="Hold lige stemmen nede, <Name>, vagterne kan høre dig."},
  [2300] = {n="EF:7", l="Rejs til Stormvind og søg Renzik \"Kniven\".", d="Renzik ledte efter dig, fisk.\n\nJeg ville ikke lade Mathias' næstkommanderende vente, hvis jeg var dig.", c="Er du klar til at gå i gang med arbejdet, eller skal du have en lur, før vi begynder?"},
  [2318] = {n="Oversættelse af Dagbogen", l="Find nogen, der kan oversætte paladinens dagbog. Det nærmeste sted, der måske har nogen, er Kargat i Ødelandene.", d="Du står lidt i en blindgyde og ved, at du får brug for at få bogen oversat til et sprog, du kan forstå. Der er bestemt et antal mennesker i verden, der kunne gøre det; det nærmeste sted, der måske har nogen, der kunne, er dog Kargat-forposten i Ødelandene. Måske er det et godt sted at starte.", c="Mægtige <Class>, jeg ved, hvad du laver her ude i Ødelandene. Jeg ved, at du søger min tungetalegave. Du er efter delene til den halskæde, du fandt i Ulddaman.\n\nOverrasket? Det skal du ikke være - det er mit job at vide sådanne ting. Lad os i stedet tale om, hvad du skal gøre for en oversat dagbog. Stol på mig - jeg er den eneste, du kan finde, der kan oversætte den.\n\nEndnu bedre, lad mig give dig et bedre tilbud end Dran Droffers', og det lader dig stadig gennemføre din aftale med dem. Interesseret nu, ja?"},
  [2338] = {n="Oversættelse af Dagbogen", l="Lad Jarkal låne halskæden. Til gengæld oversætter han dagbogen for dig.", d="Droffers og Søn Bjærgning er ikke kloge nok til at genoprette magien i halskæden, men det er jeg. Alt, hvad jeg ønsker, er at studere halskæden, så jeg kan lære at lave dem selv. For at gøre det får jeg brug for din halskæde. Lad mig låne den, og til gengæld for den tid, jeg får til at studere den, oversætter jeg dagbogen for dig. Mens du leder efter ædelstenene, burde jeg have tid nok til at lære, hvad jeg har brug for.\n\nDet er en simpel handel, og ingen andre vil blive klogere. Hvad siger du?", p="Du har tænkt over det, ikke? Du er en klog <Class>, hvis du tager denne handel - du og jeg får begge det, vi ønsker, og Droffers og Søn Bjærgning tror, at de får, hvad de vil have.", c="Du kan genkende en god handel, når du ser en - jeg vidste, at jeg kunne regne med dig.\n\nDet tager lige et øjeblik, mens jeg kaster en besværgelse for hurtigt at oversætte menneskenes tunge til en form, du vil forstå. Jeg er en trold af mit ord; spørg hvem som helst i Horden om Jarkal Mosgrød. Nu, lad os få det i gang..."},
  [2339] = {n="Find Juvelerne og Kraftkilden", l="Genvind alle tre juveler og en kraftkilde til halskæden fra Ulddybet, og bring dem derefter til Jarkal Mosgrød i Kargat. Jarkal tror, at en kraftkilde måske kan findes på det stærkeste konstrukt i Ulddybet.\n\nFra dagbogen ved du...\n* Rubinen er gemt væk i et spærret område i Skyggesmedjen.\n* Topasen er gemt i en urne i et af Troggeområderne, nær nogle Alliance-dværge.\n* Safiren er blevet taget af Grumlok, troggelederen.", d="Her er dagbogen, oversat så du kan læse den selv. Kernen er, at dværgene gemte rubinen, troggerne gemte topasen, og en trogg ved navn Grumlok har safiren.\n\nSe, du skal bruge en kraftkilde for at få halskæden til at virke igen. Dran Droffers ved ikke det her. For at finde en, så gør jeg sådan her: Gå så dybt du kan ned i Ulddybet og dræb det konstrukt, der er stærkest. Der er ingen tvivl om, at det har den.\n\nNår du har samlet alt, så kom tilbage hertil!", p="Så venter der dig en ny tur ned i dybet af Ulddybet, hvis du ikke har juvelerne og en kraftkilde, der er i stand til at kanalisere magisk kraft tilbage i halskæden.\n\nDu får juvelerne tilbage, så du kan levere dem til slyngelerne i Orgrimgrad; jeg beholder kraftkilden, for den er jo det, der får halskæden til at virke overhovedet...", c="Meget godt klaret, <Class>. Nu vil frugterne af vores omdirigering betale sig rigeligt. Jeg er færdig med selve halskæden, og jeg er sikker på, at jeg kan gentage konstruktionsprocessen igen og igen.\n\nMen først vil jeg bruge en specielt forberedt besværgelse til hurtigt at analysere de juveler, før du tager dem og halskæden tilbage til Orgrimgrad. Det tager lige et øjeblik."},
  [2340] = {n="Lever juvelerne", l="Lever halskæden og ædelstensbjærgningen til Dran Droffers i Orgrimgrad.", d="Enhver halskædeindfatning og ædelsten virker, så længe de er af samme materiale. Denne kraftkilde er dog det, der vil bringe magien tilbage i halskæden... håber jeg.\n\nJeg leverer gladeligt de ædelstene, der skal bruges til din udgave af halskæden, så længe kraftkilden faktisk virker.\n\nTag til Orgrimgrad og hold din side af aftalen med Droffers og Søn Bjærgning. Bare hold mund om vores aftale, og når du kommer tilbage, har jeg måske en vidunderlig overraskelse til dig.", p="Nå, se hvem det er! Du har taget dig god tid til at komme herhen, kan jeg se. Lad os håbe, at det her ikke er spildt tid for mig! Du får ikke betaling, medmindre du har alt, hvad jeg bad om. Og stol på mig - vi tjekker alt to gange og tre gange!", c="Jep, det hele er her. Siger du, har du noget imod, at vi også beholder tasken? Nej? Tak, det sætter vi pris på! Har!\n\nDenne halskæde bliver vores største fangst nogensinde! Føl dig dog ikke for ringe; jeg er sikker på, at halskæden alligevel ikke ville passe dig. Har igen!\n\nEn aftale er en aftale, så her er din betaling for bjærgningen. Vores forretning er færdig her for nu; kig forbi senere for at se, om vi har mere arbejde. Indtil da, så skrid!"},
  [2341] = {n="Halskædebjærgning, Forsøg 3", l="Besøg Jarkal Mosgrød i Kargat for at se, om han lykkedes.", d="Mens Dran og Mallond Droffers begynder at skændes om deres nye bjærgning, er halvdelen af aftalen nu fuldført. En tur til Ødelandene er nu på sin plads for at gøre det færdigt, for Jarkal Mosgrød i Kargat har måske en særlig belønning klar til dig dernede.", c="Kraftkilden, du gav mig, overgik alle mine forventninger. Jeg kunne lave en halskæde til både dig og mig, og jeg har nok tilbage til at lave mindst tre mere. De vil indbringe ret så en pæn sum, uden at Droffers og Søn Bjærgning aner noget.\n\nVær så god, min ven. Jeg takker dig for et glimrende stykke arbejde... og noget ganske særligt for besværet."},
  [2342] = {n="Genvundne Skatte", l="Hent Patrik Garrats familieskat fra deres familiekiste i Sydfællessalen i Ulddybet, og bring den til ham i Underbyen.", d="At feje flagermusenes folde med denne kost er ikke værdigt for en Garrat! Jeg har tjent lidt mønter på dette forbandede job, og jeg er villig til at bruge dem på dig, for at forbedre min stand.\n\nGarrat-familiens foretrukne våben er låst inde i vores kiste i Sydfællessalen i Ulddybet, fra dengang vi Garrater slæbte rundt der som gravere. Uden det vil jeg sidde fast her for evigt - bogstaveligt talt - og feje op efter disse djævelske flagermus.\n\nGenvind min families skat og bring den til mig! Hjælp mig med at genoprette min føderet!", p="Fejningen holder aldrig op... disse flagermus er ret så flittige i deres hån mod mig og min kost. Sig mig venligst, at du har genvundet min families skat! Jeg har tilbudt dig mit sølv - er det ikke nok?!", c="Endelig - en kost, der er værdig for en Garrat. Du er pokker så meget hvert sølv værd, jeg brugte på dig, siger jeg!\n\nHører I mig, I beskidte flagermus? Nu svinger jeg Garrat-familiens foretrukne våben! Ryst, flagermus, ryst!!"},
  [2358] = {n="Nezras Horn", l="Returner Nezras Horn til Arantérs Skygge i Søshire.", d="For mange år siden blev Nezras horn stjålet fra Ravnehold herregård. Over kontinenter og have har jeg søgt, kun for at opdage, at disse ubetydelige bæster har haft det i deres besiddelse hele tiden.\n\nDræb hver eneste Sortklippe-ork, du støder på, indtil Nezras horn er genvundet. Hvis du genvinder hornene, så find mig i Søshire.\n\nGør dette for mig, så skal dit navn blive kendt i Ravnehold, <Name>.", p="Har du dæmonprinsens horn?", c="At nægte Ravnehold artefaktet ville være at nægte ens egen eksistens. Godt gået, snigmorder. Du kan endnu gå blandt Ravnehold-snigmorderne.\n\nSom ung snigmorder på eventyr i Mørkekysten, opdagede jeg en te, der genopfylder energi i kamp. Den har tjent mig godt gennem årene, og nu giver jeg dig en smag af tidsel-te. Drik af den, når du bliver træt, <Name>, og kæmp med fornyet kraft!"},
  [2361] = {n="Genoprettelse af halskæden", c="Jeg giver dig gladeligt denne halskæde, mægtige <Class>. Du har gjort mig en uvurderlig tjeneste, og for det takker jeg dig. Bær den med stolthed, og sørg for at nævne højlydt og gentagne gange, hvem der lavede den til dig!\n\nHvis du også kunne nævne, at den virkelig ikke er forbandet, ville det være fint."},
  [2378] = {n="Find Den Knuste Hånd", l="Rejs til Orgrimgrad og tal med Shentul i Skyggeklyngen.", d="Du har tjent Dødsstalkerne godt, <Name>, men måske er det tid for dig at drage udad. Selvom du har vist evner i snigen og bedrageri, har du stadig brug for meget træning.\n\nDødsstalkerne har allierede inden for Den Knuste Hånd. Søg dem, der vil hjælpe os - find Shentul i Orgrimgrad.", c="Så, du er det, vores mægtige allierede har sendt til Shentul? Hvor uinspirerende...."},
  [2379] = {n="Zandozan", l="Tal med Zandozan i Skyggeklyngen.", d="Din beslutsomhed alene er ikke nok til at overvinde de forhindringer, der venter os.\n\nTal med Zandozan for at begynde din træning som agent i Den Knuste Hånd.\n\nDet er først, når du har mestret snigens og tyveriets kunst, at du kan tage næste skridt mod din skæbne.", c="Måske tog Zandozan fejl. Zandozan beklager."},
  [2380] = {n="Til Orgrimgrad!", l="Tal med Shentul i Skyggeklyngen i Orgrimgrad.", d="En mester i snigen og bedrageri er du ikke, men alt det kan og vil ændre sig. Du har tydeligvis imponeret dem i ledelsen med dine magre færdigheder, for den store Shentul har bedt om dig ved navn.\n\nTag vejen nord herfra til Orgrimgrad og tal med Shentul i Skyggeklyngen.", c="Det er vigtigt, at Den Knuste Hånd forbliver på vagt over for de forandringer, Trall ønsker at bringe over Horden. Vores antal alene vil ikke være nok til at overvinde hans styre - snigen og bedrageri skal mestres."},
  [2383] = {n="Simpelt Pergament", l="Læs det simple pergament og tal med Frang i Prøvedalen.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nLæs det, når du har tid. Hvis jeg ikke tager fejl, kommer det fra krigertræneren Frang. Han vil gerne tale med dig, når du er klar. Du finder ham uden for Hulen, hvor han søger ly i skyggen.", p="Hvad er det, du har dér? Et pergament? Du er da ikke en lærd, håber jeg...", c="Ah, det er mit pergament. Jeg hørte, at du ville komme til dalen, <Name>. Jeg er glad for at se, at du klarede turen - lad os håbe, du overlever prøvelserne forude. Som sagt, når du vinder i styrke, så kom til mig - jeg vil gøre, hvad jeg kan, for at træne dig i <Class>ens veje.\n\nHeld og lykke, <Name>, og vend tilbage til mig, når du føler dig klar."},
  [2398] = {n="De Tabte Dværge", l="Find Bælog i Ulddybet.", d="Udgravningsstedet i Ulddybet var ikke altid overrendt. Vi dværge fra Jernsmede plejede at kontrollere området, men... det var før troggerne kom. De kom så hurtigt og i så stort antal, at ikke engang dværgisk styrke kunne stoppe dem!\n\nFaktisk var deres angreb så pludseligt, at jeg frygter, at nogle af vores folk kan være fanget bag fjendens linjer.\n\nMin ven Bælog ledede en lille flok dværge dybt inde i udgravningen, lige før troggerne dukkede op. Hvis han og hans følge er i live, så vil jeg have dig til at finde dem.", c="Det var også på tide, at du dukkede op! Jeg var lige ved at tabe et væddemål til Olaf!\n\nHan vædder med, at hans skæg ville vokse ned til knæene, før han så endnu en levende <Race>. Nå, her er du, og som du kan se, mangler Olafs skæg et par tommer endnu.\n\nTak, <Name>. Jeg deler gevinsten med dig."},
  [2399] = {n="De Spirede Bregner", c="Bregnerne, Denalan plantede i sin have, er spiret og vokset. De dirrer, ivrige efter at blive plukket...."},
  [2439] = {n="De Platinskiver", l="Tag din belønningsseddel til Dinita Stenkappe i Hvælvet i Jernsmede.", d="Dette objekt er et utroligt fund. De gamle titanere, eller Skaberne, som disse skiver kalder dem, er forbindelsen til vores fortryllede skabelse, hvis lærdommen gemt her er korrekt! Vi må investere så meget forskningstid i det som muligt.\n\nMen for dig, heroiske <Class>, så tag denne seddel til Dinita Stenkappe i hvælvet. Den giver dig det, jeg synes passer til sådan et enormt fund!\n\nVend straks tilbage til mig, når du er klar; der er meget mere at gøre for Opdagelsesrejsende-Ligaen!", p="Velkommen til Hvælvet i Jernsmede, <Name>. Hvad kan jeg gøre for dig i dag?", c="Ah ja, en seddel fra Opdagelsesrejsende-Ligaen... og en ganske værdifuld en, må jeg tilføje.\n\nOpdagelsesrejsende-Ligaen giver mig autoriteten til at tilbyde dig et valg i din kompensation direkte fra deres hvælving. Du skal modtage denne genstand, og du kan vælge mellem fem overlegne helbredende eliksirer eller fem større manaeliksirer som din belønning."},
  [2440] = {n="De Platinskiver", l="Tag belønningsseddelen til Bøna Vinterhov i Tordenskrænt.", d="Jeg vil koncentrere mine kræfter på disse skiver; de vil åbenbare deres sande virkemåde for mig til sin tid.\n\nNu til dig <Name>, jeg vil belønne dig for din flid i at gøre mig opmærksom på dette. Tag denne seddel til Bøna Vinterhov, alkymitræneren i Tordenskrænt. Hun vil give dig en særlig genstand, som jeg tror, du vil finde tiltalende, og hun vil skaffe dig et valg af eliksirer fra mit personlige lager.\n\nVend snart tilbage til mig, for jeg fornemmer, at der er meget mere, vi må gøre i forbindelse med dette fund.", p="Hilsner, <Class>! Er du her for alkymitræning, eller måske noget andet?", c="Nå <Name>, du må have behaget Vismand Sandhedssøger meget, siden han giver dig denne genstand. Du skal også have en gave fra hans lager af eliksirer; du kan vælge mellem 5 overlegne helbredende eliksirer eller 5 større manaeliksirer som din belønning."},
  [2459] = {n="Ferositas Drømmeæderen", l="Tallonkai Hurtigrod i Dolanår vil have dig til at dræbe 7 Knudefyr-mystikere og finde den Savnede Juvel.", d="Smaragden... Den er væk! Min drømmefanger er blevet beskadiget!\n\nDer er en flok Knudefyr-mystikere nord for Stjernebrise. Jeg har hørt rygter om, at deres leder, Ferositas Drømmeæderen, har båret en halskæde, der lyser grønt om natten. Nu, da jeg ser min drømmefanger, er jeg sikker på, at han har stjålet min smaragd... Han ville aldrig indse, at dens kraft er ubrugelig for ham.\n\nFind denne savnede juvel, <Name>. Og mens du er der, så ryd også nogle af de fordærvede mystikere.", p="Ferositas og Knudefyr-mystikerne må returnere, hvad der er mit. Hent venligst smaragden, så jeg kan reparere min smaragd-drømmefanger.", c="Nu kan jeg reparere min drømmefanger. Tak, <Name>."},
  [2460] = {n="Den Knuste Hilsen", l="Udfør den Knuste Hilsen over for Shentul.", d="Som snigmorder i Den Knuste Hånd er det afgørende, at du lærer den Knuste Hilsen. Det er den eneste måde at identificere et andet medlem af Hånden på.\n\nSe, lær, gentag.", p="Øvelse!", c="Godt gjort, <Name>. Du er nu klar til at fortsætte."},
  [2479] = {n="Hinotts Bistand", l="Rejs til Tarren Mølle i Hillsbrad-forbjergene og lever Prøven af Zanzils Blanding til Sergé Hinot.\n\nFor at komme til Tarren Mølle, tag zeppelinen til Underbyen og følg vejen sydpå gennem Sølvfyr og mod Bakkebrad. Følg skiltene!", d="Tag en prøve af blandingen til Sergé Hinot i Tarren Mølle.\n\nHvis nogen kan kurere dig, så er det Sergé. Lev længe nok, så vil Sergé vise dig giftfremstillingens og -brugens veje.", p="Hvad er dette???", c="Du ser lækkert bleg ud, <Class>. Og hvad er den beskidte duft, du udsender? Jeg må vide det!"},
  [2480] = {n="Hinotts Bistand", l="Vent, til Sergé Hinot har fuldført helbredelsen.", d="Jeg har aldrig set så vidunderlige resultater fra et gift! Zanzil siger du? Har aldrig hørt om ham, men jeg må rose ham for udarbejdelsen af denne brygning.\n\nAltså skal jeg kurere dig for dette og derefter lære dig at bruge giften?\n\nGiv mig et øjeblik til at undersøge giftstoffet, <Name>.", c="Helbredelsen er klar! Drik dette modgift, så stopper den krybende vanvid, men jeg kan ikke gøre noget ved lugten."},
  [2500] = {n="Ødelandenes Reagenstur", l="Skaf de reagenser, Ghak Helbredsberøring har brug for fra Ødelandene, og vend derefter tilbage til ham i Tælsamar.", d="<Class>, jeg vil gerne gøre brug af dine tjenester. Jeg er en alkymist af en vis anseelse, og jeg søger din hjælp til at skaffe nogle reagenser, der findes ude i Ødelandene.\n\nJeg har brug for følgende genstande for at genopfylde mine lagre: fem musvågemaver, ti klippecoyote-hugtænder og fem klippeelementar-skår. Naturligvis kan du få dem fra selve dyrene; hvis du ikke er den kæmpende type, så find venner, der er det.\n\nSkaf disse genstande til mig, så får du nogle mønter ud af handlen.\n\nNå, hvad siger du så?", p="Har du fået de ting, jeg har brug for endnu? Du får ikke betaling, medmindre du bringer mig de reagenser.", c="Ah, godt gået <Name>. Disse burde række mig i hvert fald en lille stund. Her er din betaling, som lovet.\n\nHvis du er interesseret, har jeg nogle flere reagenser, jeg kunne bruge. Disse findes dog kun i dybet af Ulddybet-udgravningen. De bliver ikke nemme at skaffe, men jeg vil gøre det umagen værd, hvis du er interesseret i at hjælpe mig igen.\n\nMåske noget mere end nogle blanke mønter, hva'?"},
  [2501] = {n="Ødelandenes Reagenstur II", l="Brug de tomme thaumaturgikar på forkullede vogterdrager i Ødelandene. Når du har fyldt dem, så bring dem til Ghak Helbredsberøring i Tælsamar.", d="Du har været meget hjælpsom for mig, <Name>. Jeg vil gerne belønne dig med selve opskriften på brygningen, jeg gav dig tidligere, men jeg må bede dig om en tjeneste, der er ganske farlig.\n\nDenne låsekasse indeholder tre tomme thaumaturgikar; de er gennemsyret af en afstemningsaura, der vil dræne blodet fra en forkullet vogterdrage. At bruge en på bæsten vil gøre den meget vred, så vær forsigtig. Når du har fyldt alle tre, så bring dem til mig.\n\nGør dette, så bliver opskriften din.", p="Har du brugt karrene til at skaffe mig det forkullede vogterdrageblod, jeg har brug for? Ja, jeg ved, det er en farlig opgave... men opskriften på min genoprettende brygning venter på din succes. Risiko og belønning, min ven... risiko og belønning...", c="Fra en alkymist til en anden hilser jeg dig. Her, tag denne opskrift og lær den udenad. Må den bringe dig den succes og de belønninger, den har bragt mig gennem årene!"},
  [2519] = {n="Månetemplet", l="Søster Akvinne vil have dig til at tale med Præstinde A'moora i Månetemplet.", d="Et engang storslået skovens væsen trænger til hjælp, <Race>.\n\nDer er en svær opgave, som må udføres.\n\nSøg venligst Præstinde A'moora; hun vil forklare dig tingene. Find hende mod sydøst herfra, inde i Månetemplet.", c="Så, Søster Akvinne sendte dig?"},
  [2521] = {n="At Tjene Kumisha", l="På dine rejser gennem Det Sønderrevne Land, skulle du nogensinde støde på en Fejlfri Draenetyst-kugle, så tag genstanden tilbage til Kumisha Samleren.\n\nVær advaret, denne ædelsten er en af de sjældneste krystaller i hele Azerot. Ethvert væsen i disse lande kunne have en Fejlfri Draenetyst-kugle.\n\nDu vil blive belønnet for hver Fejlfri Draenetyst-kugle, du har samlet.", d="<Race>, kan din lille hjerne begribe sjældenheden af en fejlfri kugle af draenetyst? Draenæ har brugt hele livet på at lede efter blot en af disse krystaller, kun for at møde forfærdelige skæbner, deres formål uopfyldt.\n\nSå du står foran Kumisha, vidende hvad Kumisha har bedt om, og ønsker stadig at hjælpe? Meget godt, <Race>... Når som helst under dine rejser gennem disse lande, hvis du finder en fejlfri draenetyst-kugle, så bring den tilbage til mig, og jeg vil belønne dig med rigdomme ud over dine vildeste drømme.", p="Jeg har viet mit liv til jagten på fejlfri draenetyst-kugler. Et helt liv, <Race>!", c="Narrer mine øjne mig? Umuligt! Hvor fik du... Hvordan...\n\nMåske kan der nu åbnes en revne, der sender os tilbage til vores hjemland."},
  [2581] = {n="Snerrehuggerkæberne", l="Bring tre Snerrehuggerkæber, to Sønderrevne vildsvinelunger og én Skorpok-klo til Blodmager Drasial.", d="Det er en velkendt kendsgerning, at hyæner har enorm styrke i deres kæber, men styrken til at bide igennem tre tommer thoriumstål? Umuligt, usandsynligt, og alligevel har jeg set det demonstreret med egne øjne.\n\nDrag ud i Det Sønderrevne Land, og bring mig tre snerrehuggerkæber. Mens du leder efter snerrehuggeren, så hold øje med vildsvin og skorpokker: Den indledende analyse kræver også to sønderrevne vildsvinelunger og én skorpok-klo for at blive fuldført.", p="Du lugter grimt, <Name>. Har du traskket rundt på svovlmarker? Og hvor er mine komponenter?!", c="Hvordan har du det, <Name>? Du udstråler snerrehuggerens aura - din styrke, uovertruffen af dødelige!\n\nDesværre kunne jeg med de komponenter, du bragte mig, kun lave nok af analysen til én tablet. Jeg skal bruge flere komponenter, hvis du ønsker endnu en tablet."},
  [2583] = {n="Et Vildsvins Livskraft", l="Bring tre sønderrevne vildsvinelunger, to skorpok-klør og én basiliskhjerne til Blodmager Drasial.", d="Inden for disse sønderrevne lande findes to arter af vildsvin: askemanke-vildsvinet og helvildsvinet.\n\nDet synes, at udholdenheden hos disse bæster gør dem næsten immune over for skade, da de andre dyr finder dem for svære at dræbe og følgelig ikke besværet værd.\n\nVi må udføre yderligere analyse, <Name>. Hvis du bringer mig tre sønderrevne vildsvinelunger, to skorpok-klør og én basiliskhjerne, så skaber jeg et guddommeligt elixir af restene fra analysen. Du bliver min første forsøgsperson!", p="Hvor er organerne, <Name>!?", c="Vildsvinets ånd oplyser dit væsen, <Name>! Jeg undrer mig, tror du, at du er lige så usårlig som disse bæster?"},
  [2585] = {n="Den Afgørende Angriber", l="Bring tre skorpok-klør, to gribbemaver og én sønderrevet vildsvinelunge til Blodmager Drasial.", d="Har du nogensinde set dem i kamp, <Name>? Skorpokkerne, mener jeg. Har du set den nåde og smidighed, de bevæger sig med? Afgørenheden i deres angreb?\n\nHvis vi bare på en eller anden måde kunne isolere den smidighed og indkapsle den, ville vi være rige ud over vores... altså... det ville være en gevinst for det videnskabelige samfund.\n\nHjælp mig, <Name>, og jeg vil lade dig få en prøve af analysen.\n\nFor at skabe en stabil prøve får jeg brug for tre skorpok-klør, to gribbemaver og én sønderrevet vildsvinelunge.", p="Hvor er organerne, <Name>!?", c="Fascinerende. Dette har været den vanskeligste analyse af alle.\n\nTag en knivspids af dette restsalt og læg det under tungen. Du bør opleve en let følelse af eufori efterfulgt af en tilstand af hidtil uset smidighed og hurtighed."},
  [2601] = {n="Basiliskens Bid", l="Bring ti basiliskhjerner og to gribbekråser til Blodmager Lynnore.", d="Disse ødemarker vrimler med rødstensbasiliskere, <Name>. Basiliskerne har tilpasset sig og trives, mere end noget andet dyreliv i regionen.\n\nJeg har set på lang afstand, mens de jager og går om deres daglige gerninger - bæsterne udviser en tankegang, der er mere kompleks end selv nogle menneskelignende væsener.\n\nJeg må studere deres hjerner!\n\nHent ti af deres hjerner til mig, <Name>. Forbindelsen kan dog ikke blive færdig uden to gribbekråser, der skal danne grundlaget for løsningen.", p="Er du kommet tilbage med de ønskede organer?", c="Det er vidunderligt, <Name>! Mit tilbud til dig er en smagsprøve på det indre af rødstensbasiliskeren.\n\nSkulle forbindelsen falde i din smag, kan der altid laves mere... for en pris."},
  [2603] = {n="Gribbens Vitalitet", l="Bring ti gribbekråser og to fnisetand-kæber til Blodmager Lynnore.", d="Døden har jo vinger i disse sønderrevne lande, <Race>. Jeg har set de sorte dræbere og knoglepikkerne feste på liget af mangen faldet opdagelsesrejsende - nogle gange på de mest modbydelige og sygdomsramte ådsler. Det er et under, at deres indre systemer kan overvinde den pest, der hjemsøger disse lande.\n\nHjælp mig i mine studier, <Name>! Kråser er det, jeg skal bruge! To fnisetand-kæber skal også bruges som grundlag for blandingen.\n\nDu skal belønnes dobbelt for din indsats.", p="Spild ikke min tid, <Name>. Vi har intet at tale om, medmindre du har skaffet de ting, jeg bad om.", c="Fortræffeligt! Jeg går straks i gang. Måske findes der en kur mod mange af verdens lidelser!\n\nAh ja, din belønning - selvfølgelig, skulle du have brug for mere af gummien, så kom tilbage til mig, så får du en ny opgave."},
  [2605] = {n="Den Tørstige Nisse", l="Saml en lastede dugkirtel og bring den til Marin Nøggenfogger i Gadgetbyen.", d="Jeg har fået en idé, ser du. Jeg har hørt om nogle mærkelige væsener, der kaldes dugsamlere, og som lever mod sydvest... og at de kan opbevare vand i særlige kirtler.\n\nJeg tror, at hvis jeg kunne få fat i en af de kirtler, kunne jeg lave en drik, der slukker min forfærdelige tørst! Tror du, du kunne hjælpe mig, <Name>?\n\nLed efter kaktushaven, <Name>; det er der, du finder dugsamlerne.", p="Vil du være sød at fortælle mig, at du fandt dugsamlerne?", c="Åh, herligt! Giv den her - lad mig drikke den!"},
  [2606] = {n="I God Smag", l="Marin Nøggenfogger vil have dig til at tale med Drys i Gadgetbyen.", d="Bæh! Det her smager forfærdeligt! Så meget for den idé...\n\nVent, hvad er det? Åh, jeg ved, jeg ved, du synes, jeg ikke skal give op med det her. Nå, jamen okay så.\n\nUhhhh, jeg har en idé! Genialt! Tag den her dug med til min ven Drys - hun er en fremragende kok. Fortæl hende, hvad vi har gang i, og at vi gerne vil have det til at glide lidt lettere ned.\n\nJeg mener, hvis det skal smage så ildelugtende, bør der i det mindste være lidt krydderi i... Og jeg kan bare ikke føle det...", p="Så er gamle Marin i gang igen, hva'? Hvad er det for en blanding?", c="Marin er en god fyr, misforstå mig ikke - bare lidt... særegen, vil jeg sige.\n\nOg selvfølgelig har han brug for min hjælp, endnu en gang."},
  [2621] = {n="Den Udstødte", l="Tal med Udsendelseskommandør Ruag i Stenard.", d="Anger. Det er alt, jeg har tilbage nu. En dårlig beslutning med flere forfærdelige følger. Hvis bare jeg havde ventet på de ordrer! Måske ville de have beskrevet rædslerne, der ventede os i de forbandede lande! Måske skulle de have sendt os til en anden opgave? I sidste ende var det min skyld. Alt sammen var min skyld.\n\nSå her står jeg og venter på ordrer. Jeg må vide det. Jeg må have de ordrer.\n\nUdsendelseskommandør Ruag holder til i Stenard. Find ham og find ud af, hvad der blev af ordrerne.", c="Trald's Greb... Historien står stadig klart i min hukommelse.\n\n<Kommandør Ruag rister på hovedet.>\n\nEt forfærdeligt man kan kalde det, det der skete med det regiment. Horden mistede nogle af sine bedste soldater, da bataljonen blev ødelagt."},
  [2622] = {n="De Savnede Ordrer", l="Tal med Bengør.", d="Ordrerne? Hvad kunne du overhovedet ønske dig med ordrerne?\n\nHvad mener du, <Name>? Selvfølgelig har jeg videregivet de ordrer! Soldaterne, jeg sendte med ordrerne, blev bagholdt og brutalt tævet af mudderfisk. Kun én overlevede, hvis man kan kalde det at overleve. Han kan næppe tale, kan ikke gå og må fodres gennem et rør. Hvis du vil vide, hvad der skete med de ordrer, så tal med Bengør. Jeg er sikker på, han er her et sted... Og <Name>, vær forsigtig med, hvad du stikker næsen i - den kan blive bidt af.", c="Sump tal... tal.. talter..."},
  [2623] = {n="Sumptaleren", l="Hent Krigshøvdingens ordrer og bring dem tilbage til Hordens Faldne Helt.", d="Ordrerne blev givet af udsendelseskommandøren. Vi tog... tog ordrer. På vej til Det Sønderrevne Land, baghold.\n\nMudderfisk... Mange mudderfisk... En af dem hed Sumptaleren. Tog ordrer fra mine hænder, da spyd stødte gennem min kranie. Øst... hule....\n\n<Bengør besvimer.>", p="Venter på ordrer.", c="Det er værre, end jeg frygtede. Nitten af mine mænd kunne have været skånet for den smerte, de led. Hvis bare jeg ikke havde handlet så irrationelt.\n\nDu må hjælpe dem, <Name>! Jeg er magtesløs."},
  [2641] = {n="Drys' Hemmelige Ingrediens", l="Drys i Gadgetbyen vil have dig til at samle en Violet Tragansvamp og bringe den tilbage til hende.", d="Da jeg var barn, plejede min søster at lave al maden. Det var forfærdeligt! Jeg kunne næsten ikke holde nogle af hendes blandinger nede - indtil jeg fandt det, jeg kalder min \"hemmelige\" ingrediens! Tilsæt den til hvad som helst, og... WOW! Det smager fantastisk!\n\nHvad er det, spørger du? Det er en svamp, der kaldes Violet Tragansvamp. Hvis du vil have mig til at hjælpe dig med at gøre denne forfærdelige brygning spiselig, så tag til Bagland og led efter en lille sø der.\n\nÅh, og husk, Violet Tragansvampen kan kun findes under vand.", p="Under vandet i den sø - det er det eneste sted, hvor Violet Tragansvampen kan findes. Håber du er god til at holde vejret!", c="Det er det, <Name>!\n\nDen ser så lækker ud, at jeg næsten... Haha, narret!"},
  [2661] = {n="Levering til Marin", l="Drys vil have dig til at tage det violette pulver med til Marin Nøggenfogger i Gadgetbyen.", d="Her er det violette pulver, <Name>. Tag det med til Marin og fortæl ham, at han skylder mig en tjeneste!", p="Åh, <Name>, du er endelig tilbage. Hvad har du med?", c="Violet pulver, hva'? Lad os prøve det - det kan i hvert fald ikke gøre det værre, det er helt sikkert!"},
  [2662] = {n="Nøggenfogger-eliksiret", l="Marin Nøggenfogger vil have, at du taler med ham igen, når han har lavet sin eliksir.", d="Nu skal dette pulver blandes op i dugget.\n\nKom tilbage og tal med mig om et øjeblik... når jeg har perfektioneret den fabelagtige Nøggenfogger-eliksir!", c="Drik den her! Den er helt vidunderlig!!!\n\nJeg vidste, at jeg havde det i mig... Åh tak igen, <Name>, for din hjælp, men stå lidt til side, vil du? Du blokerer for min forretning! Jeg skal tjene millioner på den fabelagtige Nøggenfogger-eliksir, millioner!\n\nHvad er det? Drys siger, at jeg skylder hende en tjeneste? Åh, den Drys, sådan en drillepind!"},
  [2681] = {n="Stenene, Der Binder Os", l="Befri ni tjenere af Razelikh, tre tjenere af Sjælefald, tre tjenere af Allistarj og tre tjenere af Grol. Vend tilbage til den Faldne Helt, når din opgave er fuldført. Du skal blive i nærheden af stenene, ellers mislykkes processen.", d="Det vil kræve mere end dig alene at overvinde Razelikhs og hans undergivnes styrker.\n\nSaml en passende gruppe eventyrere og befri mine mænd fra deres evige pine! Atten sten skal du knuse.\n\nKæmp hårdt og dø med ære, <Name>.", p="Det er ingen let opgave, <Name>. Giv ikke op!", c="Du har klaret det, <Name>! De stakkels, pinte sjæle kan endelig hvile.\n\nVores arbejde er ikke færdigt endnu, <Name>. Vi har meget at drøfte og meget mere at udrette."},
  [2701] = {n="Helte fra Fortiden", l="Åbn kisten og tag din belønning.", d="Tag venligst en relik fra gamle dage. Vi har ikke længere brug for genstanden.\n\nMåtte den tjene dig godt i din kamp mod legionen.", c="Du er midlertidigt blændet af glimten og skinnet."},
  [2702] = {n="Helte fra Fortiden", l="Tal med Korporal Thund Splithov.", d="Du har æret mig med din adel og heltemod, <Name>.\n\nDu har også æret dem...", c="Sandelig, du har æret os alle. Vores tak alene er ikke nok."},
  [2721] = {n="Kirit", l="Find ud af, hvad der blev af Løjtnant Kirit.", d="Mens et kapitel af dit eventyr slutter, begynder et andet, <Name>.\n\nEn af mine mænd er stadig uden for rækkevidde, fortabt et sted i Det Sønderrevne Land. Jeg taler selvfølgelig om Løjtnant Kirit.\n\nSom jeg nævnte tidligere, blev vi begge fængslet og torteret af Allistarj, men stakkels Kirit, hans viljestyrke svigtede. Jeg kunne høre eksperimenterne fra min bur; de torterede skrig rungede gennem hulens gange. Det var sidste gang, jeg så eller hørte til Kirit.", c="Trebør? Trebør sendte dig?"},
  [2741] = {n="Den Super Æg-O-Matic", p="Den Super Æg-O-Matic er Kurgle Krængelhops nyeste opfindelse. Det er en imponerende maskine.\n\nDen Super Æg-O-Matic sprutter vildt, når du nærmer dig kontrolpanelet.", c="Du lægger hippogryfægget i maskinen. En række bip efterfølges af nogle mærkelige mekaniske lyde.\n\nDet ser ud til, at Æggometeret har vejet, målt og pakket dit æg. Det kalder jeg hurtig betjening!"},
  [2742] = {n="Rin'skold er fanget!", l="Eskorter Rin'skold ud af Quel'Dånil-hytten, og find derefter hans skjulte hemmelighed ved Udsigtsklipperne mod øst.", d="Hej <Race>!\n\nRin'skold mistede øksen og blev fanget! Venligst, hjælp Rin'skold flygte. Mig vide at <Race> som dig ikke kan lide Rin'skolds slags, men Rin'skold beder! Må komme væk herfra!\n\nHar noget til flink <Race>, hvis han hjælper Rin'skold væk herfra...\n\nRin'skold gemmer noget hemmeligt ved Udsigtsklipperne.", p="Rin'skold er bange!", c="Denne trolltavle må være den \"hemmelighed\", Rin'skold talte om.\n\nDækket af mærkelige mærker kan du ikke tyde, hvad tavlen siger."},
  [2743] = {n="Mørkets Dække", l="Vend tilbage til Hordens Faldne Helt med dine fund.", d="Lad os ikke gå som katten om den varme grød, <Race>; min tid her er begrænset.\n\nDu må ødelægge magttrekanten, der beskytter dæmonlorden Razelikh. Det bliver ikke så simpelt en opgave som at befri en fordømt sjæl.\n\n<Kirit grinér.>\n\nDu ser, hver af Razelikhs undergivne bærer en tredjedel af en amulet, som Razelikh selv skabte, om halsen. Den samme amulet, du skal bruge for at kalde ærkedæmonen.\n\nVend tilbage til Trebør og fortæl ham, hvad der kræves for at kalde Razelikh. Han kan give dig flere instrukser.", c="Dæmonlorden viser en list næsten lige så beregnet som hans brutalitet, <Name>."},
  [2744] = {n="Dæmonjægeren", l="Tal med Lorumus Talipedes i Azsyra.", d="Trekanten er beskyttet af Razelikh.\n\nTil gengæld for deres trældom gav Razelikh hver af dem næsten ubegrænset magt i Det Sønderrevne Land. Amuletstykkerne er hver indstillet til deres ejers livskraft, hvilket giver dem udødelighed. Så længe de bliver i Det Sønderrevne Land, kan de ikke dræbes, og deres levetid er forlænget til tidernes ende.\n\nDer er én, der måske kan hjælpe dig yderligere, <Name>. Rejs til Azsyra og find dæmonjægeren Lorumus Talipedes. Søg på øerne.", p="Hvad laver du her?", c="Jeg vil hjælpe dig. Dog tror jeg ikke, du helt forstår, hvad du står over for."},
  [2751] = {n="Barbariske Brystværn", l="Bring to mønstrede bronze-armbeskyttere, to bronze-storsværd og to skarpe klør til Orokk Hammersen i Orgrimmar.", d="Tyve generationer af Hammersen har holdt denne hammer, <Name>. Hundredtusinde tons metal har vi formet. Tragisk nok ender det hele med Orokk, Hammersen-slægtens fiasko: uden familie og ude af stand til at få børn.\n\nJeg kan ikke lade Hammersens hemmelige opskrifter dø med mig! Nogen må føre arven videre, Hammersen eller ej!\n\nBevis over for Orokk, at du er i stand til det, <Name>. Bring Orokk følgende: to mønstrede bronze-armbeskyttere, to bronze-storsværd og to skarpe klør. Bring dem til Orokk, så fortsætter vi.", p="Bronze, <Name>! Mere bronze!!", c="Blodlinjen vil dø ud, men måske lever Hammersen-legenden videre!\n\nDu har bevist, at du er smed, <Name>. For smeden er belønningen tilfredsheden ved at se deres våben og rustninger dækket af deres fjenders blod!\n\nMåtte de brystplader, du skaber til de kommende generationer, væde i dine fjenders blod!"},
  [2752] = {n="Om Jernskulderplader", l="Bring fire bronze-stridsøkser og fire bronze-krigshammere til Orokk Hammersen i Orgrimmar.", d="Orokk ser ivrigheden i dine øjne, <Name>. Som en svamp suger du visdommen fra Hammersen til dig.\n\nTre lektioner skal jeg lære dig!\n\nVend tilbage til ambolten, badet i smedjens hede, og skab til Orokk fire bronze-stridsøkser og fire bronze-krigshammere. Først da lærer du om jernskulderpladen.", p="Vis mig din hengivenhed, <Race>.", c="Du gør Orokk stolt, <Name>. Læs, lær om jernskuldre!"},
  [2753] = {n="Trampet under Fod", l="Bring fire grønjernshjelme, fire grønjernsarmbeskyttere og to grønjernsbenbeskyttere til Orokk Hammersen i Orgrimmar.", d="Kun to lektioner mere vil Orokk lære dig, <Name>. Dine muskler værker, det ved jeg, men fortsæt for Hammersens skyld!\n\nBring Orokk fire grønjernshjelme, fire grønjernsarmbeskyttere og to grønjernsbenbeskyttere - for dette lærer du, og dine fjender lider!", p="Deres kranier vil knække under trykket fra dine støvler!", c="Du minder Orokk om hans bedstefar, Høvding Gorokk af Hammersen! Læs, lær om jernstøvlen."},
  [2754] = {n="Raseriets Horn", l="Bring to massive jernstridshammere, to forsølvede bronzestøvler og to forsølvede bronzehandsker til Orokk Hammersen i Orgrimmar.", d="Den sidste lektion Orokk lærer dig, <Name>. Til den hellige ambolt og smedjen vender du tilbage! Bring Orokk to massive jernstridshammere, to forsølvede bronzestøvler og to forsølvede bronzehandsker.\n\nSe frygten i deres øjne, når du nærmer dig!", p="Vis jernet, hvem der bestemmer, <Name>!", c="Forbløffende! Du har lært Hammersen-vejen, <Name>!"},
  [2755] = {n="Hammersens Glæder", l="Se på og lær Hammersen-glædesdansen.", d="Orokk græder ikke, <Name>. Der er sod i øjet.\n\n<Orokk tørrer en tåre væk.>\n\nDer er én sidste Hammersen-familiehemmelighed, Orokk vil lære dig. Orokk vil dø glad, takket være <Name>.\n\nLær Hammersen-glædesdansen, og så lærer du jernets knytnæve!", c="<Orokk gisper.>\n\nDet er gået meget lang tid, siden Orokk sidst dansede Hammersen-glædesdansen. Lær nu, <Name>!"},
  [2756] = {n="De Gamle Veje", l="Bring fire stålbrystplader og fire stålpladehjelme til Aturk Ambolten i Orgrimmar.", d="I legendernes tid ville Aturk knuse sine fjenders kranier og male knoglerne til et fint pulver til brug i filamentet. Længst borte er de dage, <Race>. Krigshøvdingen kræver fred mellem klanerne. Gamle fjender ses nu kun med trætte øjne!\n\nUfattelig, ved jeg, men sådan er Trald's vilje.\n\nNok klagen! Du er her for at lære, og lære skal du! Bring mig fire stålbrystplader og fire stålhjelme, så får du en smag af krig!", p="Aturk venter ikke på nogen, ligesom tiden! Skynd dig, tosse!", c="Du lader til at være endnu en tilfreds lemming af Krigshøvdingen, <Name>. Hvor skuffende.\n\nHvor jeg længes efter en herlig død på slagmarken. I stedet sidder jeg fast her på Trald's ordre og lærer spædbørn at håndværke! Se og lær, barn!"},
  [2757] = {n="Bytteviken eller Undergang!", l="Tal med Makgavan i Bytteviken.", d="Hør her, unge, du lærer ikke noget ved at hænge rundt her.\n\nJeg kender en fyr, der kender en fyr. Han hænger rundt ved smedjen i Bytteviken. Hvis du viser ham denne emblem, vil han fortælle dig alt om mithril.\n\nSå hvad siger du? Lad de babyer i ble klare børnestoffet, <Name> - det er tid til at komme videre.\n\nHvis du er interesseret, hedder han Makgavan. Vis ham denne lille nipsting, så genkender han din hengivenhed.", p="En sjælden race er dine slags, makker. Lad mig se den emblem.", c="Ved Sortehovs ryghår - endelig en, der er værdig til Mithril-orden!"},
  [2758] = {n="Smedens Oprindelse", l="Bring seks gyldne skælarmbeskyttere til Hank Hammeren i Stormvind.", d="Da jeg var nogenlunde på din alder, tog en dværg ved navn Galvan mig under sine vinger og oplærte mig i rustningssmedens vej. Inden han rejste til Bytteviken, fik han mig til at love, at jeg ville oplære alle dem med lysten og beslutsomheden til at avancere i smedningens håndværk -- så her er jeg -- alle disse år senere.\n\nNu er det din tur til at lære lidt. Lav mig seks gyldne skælarmbeskyttere, så skal du lære, hvor smedningen kommer fra, <Name>.", p="Kunne du mon være Galvans næste protegé?", c="Meget godt, <Name>! Lyt og lær.\n\nSmedning kommer aldrig herfra! <Hank peger på sin hammer.>\n\nSmedning kommer aldrig herfra! <Hank peger på ambolten.>\n\nSmedning kommer kun herfra! <Hank peger på sit hjerte.>\n\nOg nu kender du smedningens oprindelse."},
  [2759] = {n="På Jagt efter Galvan", l="Tal med McGavan i Bytteviken.", d="Selvom Galvan forlod Bytteviken for mange år siden, er medlemmer af ordenen stadig i byen og håber en dag at finde en anden, der er værdig til Galvans lærdom.\n\nTag dette emblem og overrak det til McGavan i Bytteviken.\n\nHvis du faktisk når så langt, vil han vide, at du er værdig. Jeg har tro på dig, <Name>!", p="En sjælden race er din slags, matros. Lad mig se det emblem.", c="Ved Sortehovs ryghår -- endelig en, der er værdig til Mithril-orden!"},
  [2760] = {n="Mithril-orden", l="Tal med Galvan den Gamle i Kvælerdorn-dalen.", d="De fleste af vores rekrutter når aldrig til Bytteviken, <Name>. Emblemets glans er nok til at udløse plyndringsbegæret selv hos de mest standhaftige smede. Tosser er de, for emblemet er en dråbe i havet sammenlignet med rigdommen af genstande, du vil se!\n\nFind Galvan den Gamle og vis ham denne nål. Hans bolig ligger langt mod nord, mellem Zul Gurub og Mosh'Ogg-ogervolden.", p="Hilsen! Kom nærmere; vis Galvan, hvad du har.", c="Ah, mange år er gået, siden nogen sidst var værdig til Mithril-ordens indvielse. Vi begynder nu!"},
  [2761] = {n="Smelt På, Smelt Af", l="Bring fyrre Mithril-stænger og fyrre Jern-stænger til Galvan den Gamle i Kvælerdorn.", d="Mange smede tror, at minedrift og smedning er adskilte, uafhængige jobs; men kan der være smedning uden minedrift? Ahaa -- det er umuligt! Den dygtige smed må også være en dygtig minearbejder.\n\nVis Galvan, at du er i stand til det, <Name>. Bring mig fyrre stænger jern og fyrre stænger mithril. Til gengæld vil Galvan lære dig de udsmykkede mithrilbukser!", p="Efter sådan et minearbejde bule dine muskler, og din krop værker!", c="Din arbejdsmoral er upåklagelig, <Name>! Du begynder at forstå Galvans mineralogi! Tag dette og lær af det, alt hvad du kan."},
  [2762] = {n="Den Store Sølvbedrager", l="Bring fyrre Mithril-stænger og fem Sandsølv-stænger til Galvan den Gamle i Kvælerdorn.", d="Det siges, at sandsølv er stærkere og mere holdbart end mithril. Galvan er ikke uenig i denne vurdering af mineralerne, men i modsætning til sit navn er sandsølv ikke sandt! Mithril er et langt ædlere mineral! HA! Uanset hvad skal du, <Name>, i denne lektion finde den store sølvbedrager.\n\nBring mig fyrre stænger mithril og fem stænger sandsølv. Til gengæld vil du lære hemmeligheden bag de udsmykkede mithrilhandsker og, endnu vigtigere, lære at sandsølv er en løgnehals!", p="Efter sådan et minearbejde bule dine muskler, og din krop værker!", c="Hun er en grusom elskerinde, ikke sandt, <Name>? Jeg taler selvfølgelig om sandsølv. Ja, Galvan brugte over et årti i bjergene i Alteraz på at lære denne lektie. Tag dette og lær af det, alt hvad du kan!"},
  [2763] = {n="Kunsten at Indgyde", l="Bring fyrre Mithril-stænger og fire Citriner til Galvan den Gamle i Kvælerdorn.", d="Indsamlingen af ædle ædelsten er af yderste vigtighed for vores håndværk, <Name>. Få ædelsten er mere ædle end citrinen. De magiske egenskaber, vi indgyder i vores varer, forstærkes kraftigt af citrinens tilstedeværelse.\n\nI denne lektion vil vi styrke fyrre stænger mithril med fire citriner. Resultatet bliver en bedre forståelse af magisk ædelstensvidenskab og viden til at skabe de udsmykkede mithrilskuldre.", p="Efter sådan et minearbejde bule dine muskler, og din krop værker!", c="Man kan knap nok holde øjnene fra dens pragt, <Name>. Ja, citrin er en herlig ædelsten.\n\nVær opmærksom og lær, hvad sådan en opdagelse kan lære os!"},
  [2764] = {n="Galvans Fineste Elev", l="Tal med Trenton Lysehammer i Gadgetbyen.", d="Hvis du er klar til at afslutte din træning hos Galvan, bør du rejse til Gadgetbyen.\n\nDer finder du min fineste elev: Trenton Lysehammer. Han har meget at lære dig om de udsmykkede mithrilvarer. Ellers kan du blive her og lære!\n\nÅh, Gadgetbyen ligger selvfølgelig i Tanaris!", c="Galvan den Gamle sendte dig??\n\n<Trenton bukker.>\n\nDet er en stor ære at møde endnu en af mesterens elever!"},
  [2765] = {n="Ekspert Smed!", l="Modtag din belønning fra Galvan den Gamle!", d="Da du første gang kom til mig, vidste jeg, at du ville blive en af mine fineste elever! Uden tøven gav du en tingest med en vis kraft til McGavan. Det gjorde du kun for at kunne møde mig. En sådan blind tro og hengivenhed over for håndværket bør belønnes.\n\nDu har opnået ekspertise i smedning, <Name>. Høst frugterne!", c="Det er kun passende, at du får en tingest med langt større kraft end den, du ofrede for at komme hertil. Brug den ved godt helbred, <Name>."},
  [2766] = {n="Find OOX-22/FE!", l="Tag nødsignalet til Oglethorpes hjemvendende robot i en hule nær Vild Ar-dalen.", d="Du har afdækket en slags mærkelig, æggeformet indretning lavet af metal. Når du fingrer ved en af dens knapper, springer ægget til live, og det åbner sig til en slags gnomisk robotapparat! En stemme inde fra den robotiske æg knitrer til live.\n\n\"Mit navn er Oglethorpe Uopdaget, og min hjemvendende robot er styrtet ned! Jeg belønner dig for at bjærge den; vær venlig at tage dette signal til robotten!\"\n\n\"Jeg har nu udregnet robottens koordinater til dig; den ligger i en hule nær Vild Ar-dalen!\"", p="Du ser ud til at have afdækket vraget af... en robotkylling? Stemmen inde fra ægget knitrer til live igen:\n\n\"Ja, fremragende arbejde! Det er faktisk min hjemvendende robot, selvom mine sensorer viser, at den har brug for en startboost, før den kan flyve tilbage til Bytteviken for reparationer. Gå videre og placer signalet inde i roveren - signalet klarer resten!\"", c="Du placerer ægget... nødsignalet... inde i kyllingen... hjemvendende robotten.\n\nDer høres summen og hvirvlen inde fra robotten, mens den kæmper for at rejse sig. Efter robotten kommer til live, høres Oglethorpes stemme endnu en gang, men nu inde fra robotten:\n\n\"OOX-22/FE virker i hvert fald, men den trænger til store reparationer! Den er alt for tung til, at du kan bære den... men jeg tror, jeg har en idé. Vil du passe på den lidt endnu?\""},
  [2767] = {n="Red OOX-22/FE!", l="Eskorter OOX-22/FE til havnen langs Glemte Kyst, og rapportér derefter til Oglethorpe Uopdaget i Bytteviken.", d="Gnomens stemme knitrer endnu en gang fra robotten:\n\n\"Jeg må flytte OOX-22/FE til et åbent, sikkert sted, så den kan begynde en lang startprocedure. Den har indbygget camouflage, men jeg skal bruge tid i min ende for at gøre den funktionsdygtig igen. Eskorter robotten fra dens nuværende placering til, lad os sige, havnen langs Glemte Kyst! Det burde være et perfekt sted, og langt nok til at få tingene op at køre!\"\n\n\"Eskorter den sikkert til havnen, og kom så og tal med mig i Bytteviken! Oglethorpe Uopdaget - ude!\"", p="Ja, jeg er Oglethorpe Uopdaget, mesteropfinder til din tjeneste! Er der noget, jeg kan hjælpe dig med?", c="Åh, DU er den store redningsmand for OOX-22/FE! Jeg kan ikke engang begynde at udtrykke min taknemmelighed for din hjælp! Min serie af hjemvendende robotter trænger til mere udvikling, men din redning har sparet mig for utallige timers ekstra genopbygningstid og mange guldmønter i fremstillingsomkostninger!\n\nVær venlig at tage dit valg af en af de genstande, jeg har. Tak igen for din generøse hjælp, <Name>, mine robotter og jeg står i din gæld!"},
  [2768] = {n="Divino-matisk Stang", l="Bring den divino-matiske stang til Overingeniør Lensevits i Gadgetbyen.", d="Sergent Blæk stjal fra mig! Han sagde, at han kun ville låne den, men han stjal min kære divino-matiske stang!! Uden den stang, hvordan skal jeg vide, hvor jeg skal grave nye vandhuller??\n\nFind Blæk og bring mig min stang! Jeg hørte, at han førte sin flok af berygtede eventyrere på skattejagt i Zul'Farrak mod vest. Jeg vætter, at du finder ham der.\n\nLad os håbe, at trollene tog sig af ham, for hvis du skal kæmpe mod ham om stangen, så står du over for en alvorlig kamp.", p="Fandt du Sergent Blæk? Fik du min divino-matiske stang?", c="Du fandt den! Godt gået, <Name>! Måtte du kæmpe mod Blæk for den? Jeg håber, du slog ham og hans flok godt og grundigt ned!"},
  [2769] = {n="Messingbolt-brødrene", l="Tal med Wizzle Messingbolt i Glimmerflatene.", d="Har du mødt Messingbolt-brødrene? De er derovre i Glimmerflatene, i Kalimdør, hvor de kører væddeløb med deres raketbil mod kobolderne. De vinder normalt, hvilket ikke er overraskende--kobolderbilen eksploderer så tit, at den næsten aldrig når målstregen!\n\nMen selv da er Messingbolt-brødrene altid på udkig efter nye måder at få deres bil til at køre hurtigere, og Wizzle fortalte mig, at han har brug for en meget sjælden komponent til sit næste eksperiment.\n\nHan har sikkert brug for hjælp til at skaffe delen. Tal med ham og find ud af det.", c="Ah, vil du hjælpe mig? Fantastisk!\n\nDer er en del, jeg vil have til et eksperiment, jeg arbejder på, og jeg har brug for en modig <Class> som dig til at hjælpe mig med at skaffe den!"},
  [2770] = {n="Gahz'rilla", l="Bring Gahz'rillas elektrificerede skæl til Wizzle Messingbolt i Glimmerflatene.", d="Dybt i Zul'Farrak, sandtrolde-byen i Tanaris, ligger en hellig pøl. Fra den pøl kalder trollene et enormt udyr frem! Gahz'rilla! Han er så vild, at selv hans skæl knitrer af energi. Det er den energi, jeg vil udnytte til min bil!\n\nBring mig Gahz'rillas elektrificerede skæl!\n\nMen fremkaldelsen af Gahz'rilla er en velbevaret hemmelighed blandt trollene. For at møde ham må du først rive hemmeligheden ud af dem.", p="Har du skællet? Jeg kan ikke vente med at prøve forskellige måder at udnytte dets energi på!", c="Vildt, du fik skællet! Tak, <Name>. Jeg kan ikke vente med at gå i gang med det her!\n\nSå du Gahz'rilla? Var han lige så stor, som de siger??"},
  [2771] = {n="Et Godt Hoved på Dine Skuldre", l="Bring to Mithril-hætter og en udsmykket mithrilskulder til Trenton Lysehammer.", d="Det ser ud til, at mesteren havde planlagt det fra starten. Jeg blev ikke lært at lave de ting, som du lærte at lave, og du blev ikke lært de ting, som jeg lærte at lave.\n\nMesteren er klog, <Name>. Vi skal lære hinanden!\n\nVis mig, hvordan man laver en mithril-hætte og udsmykkede mithrilskuldre, så skal jeg vise dig, hvordan man laver en udsmykket mithrilhjelm.", p="Har du fuldført fremstillingen af tingene, <Name>?", c="Fremragende! En rimelig byttehandel, om jeg selv må sige det. Se og lær, <Name>!"},
  [2772] = {n="Verden ved Dine Fødder", l="Bring to tunge mithrilstøvler og en udsmykket mithrilbukser til Trenton Lysehammer.", d="Ved sidste års Hele Dalens Smedemesterskab så alle, der så på, hvordan mit ben blev fejet væk under mig af en kujon af en hund fra Venture A/S' Støberi. Det, de ikke vidste, var dog, hvorfor jeg kunne fortsætte og til sidst vinde turneringen: Det er rigtigt, udsmykkede mithrilstøvler!\n\nJeg bliver nødt til at lære at fremstille udsmykkede mithrilbukser til årets turnering, da Hakkeren fra Venture A/S er deltager! Lær mig bukserne, og lær støvlens vej!", p="Har du fuldført fremstillingen af tingene, <Name>?", c="Verden vil ligge for dine fødder, <Name>! Lad dem alle komme efter dine ben, for nu er du ufejebar!"},
  [2773] = {n="Mithril-drengen", l="Bring to tunge mithrilbrystpanser og en udsmykket mithrilhandsker til Trenton Lysehammer.", d="Her omkring er jeg kendt som Mithril-drengen. Jeg leverer udsmykket mithril til eventyrere fra hele verden.\n\n<Trenton hvisker.>\n\nDe aner lidt, at jeg ikke kender teknikken til at smede udsmykkede mithrilhandsker. Shhh! Dette bliver vores lille hemmelighed.\n\nLær mig teknikken til at lave udsmykkede mithrilhandsker, <Name>, og til gengæld viser jeg dig resultatet af kulminationen af min træning hos Galvan: det udsmykkede mithrilbrystpanser.", p="Har du fuldført fremstillingen af tingene, <Name>?", c="Tak for alt, du har lært mig, <Name>. Mesteren og anføreren af det udsmykkede mithrilsæt vil snart være i din besiddelse.\n\nSe!"},
  [2781] = {n="EFTERLYST: Kalif Skorpidstik", l="Bring hovedet af Kalif Skorpidstik til Overingeniør Lensevits i Gadgetbyen.", d="EFTERLYST: Kalif Skorpidstik!\n\nGadgetbyens Vandselskab i Gadgetbyen, Tanaris, betaler en høj dusør for hovedet af Kalif Skorpidstik, leder af Spildevandsvandrerne-banditterne. Hans forbrydelser omfatter:\n\n1. Mord på Gadgetbyens Vandselskabs ansatte!\n2.Tyveri af Gadgetbyens Vandselskabs ressourcer!\n3.Beslaglæggelse af Gadgetbyens Vandselskabs ejendom!\n\nBring bevis på Kalif Skorpidstiks død til Overingeniør Lensevits for en øjeblikkelig belønning!", p="Ja <Class>, jeg er embedsmand ved Gadgetbyens Vandselskab. Hvad kan jeg hjælpe dig med?", c="Endelig - retfærdigheden har sejret! Du har givet et mægtigt slag mod de onde nomader! Med Skorpidstiks død kan dette måske endelig være det, der skubber de hjemløse væk fra Gadgetbyens vandhuller!\n\nPå Gadgetbyens Vandselskabs vegne tildeler jeg dig gerne denne dusør. Du har gjort en stor tjeneste for os alle."},
  [2782] = {n="Rin'skolds Hemmelighed", l="Oran Slangevrid, en kendt lærd i sager om Visnebark-trollene, kan måske tyde tavlen. Hun menes at opholde sig i Magikvarteret i Underbyen.", d="Tavlen er dækket af Visnebark-trollenes mærker. Rin'skolds hemmelighed er virkelig et mysterium...\n\nDet er muligt, at du har noget ret værdifuldt i hænderne her. Omvendt er det modsatte også muligt. En Visnebark-troll i nød ville sikkert gøre alt for at finde en vej ud af besværet...", p="Nå, hvad er det her?", c="Denne tavle... Ret usædvanlig... Hvor fandt du den, <Name>?"},
  [2783] = {n="Små Stridigheder", l="Tal med Hordens Faldne Helt ved grænsen mellem Det Sønderrevne Land og sumpen.", d="Vi kæmper mod den forkerte fjende, <Name>.\n\nDe sande magter i disse lande vokser fortsat i styrke og antal, mens vi skændes om brændt jord med orker.\n\nSkal vi fortsætte med at føre krig i disse lande mod Horden, kun for en dag at blive slået ud af Brændende Legions hære? Det er forgæves.\n\nLæg dine forskelle til side, <Name>, og tal med Hordens faldne helt. Han kender sandheden bag Det Sønderrevne Land.", c="Alliancen ønsker at hjælpe?\n\nJeg troede aldrig, at jeg ville se denne dag igen. En dag, hvor Alliancen kæmper side om side med Horden mod en fælles fjende.\n\nDet skal blive... vi vil forenes."},
  [2784] = {n="Fald Fra Nåde", l="Lyt til Hordens Faldne Helt fortælle sin historie.", d="Hør min historie, <Race>.", p="Lyt til, hvad jeg har at sige.", c="Som en ånd er jeg magtesløs, <Name>. Hjælp mig. Lad mig genvinde min ære."},
  [2801] = {n="En Sorgens Fortælling", l="Lyt til Hordens Faldne Helt fortælle sin historie.", d="Før vi kan fortsætte, må du høre min historie.", p="Lyt til, hvad jeg har at sige, <Name>.", c="Tiden til at handle er nu, <Name>."},
  [2821] = {n="Kvalitetens Mærke", l="Bring 10 tykke yetihuder til Pratt McGrubben i Fjermåne-fæstningen.", d="Min filosofi om læderarbejde er, at arbejdet skal være af bedst mulig kvalitet - ingen kompromisser. Enhver, der siger, at kvalitet ikke betyder noget, prøver at sælge dig havnefront-ejendom i Dun Frostbakke!\n\nI min seneste jagt på materialer af høj kvalitet er jeg stødt på tykke yetihuder. Yetierne er hjemmehørende i Vildalas, og mange findes i Vild Ar-dalen. Jeg vil have nogle, og jeg giver dig et valg af et af mine læderprodukter for en bunke på ti. Hvis det lyder rimeligt for dig, så er vi i gang.", p="En bunke på ti tykke yetihuder giver dig et valg af et af mine fremstillede varer. Fordi jeg holder af kvalitet, kan jeg sikre, at du får en god genstand!\n\nHvis du ikke kan finde yetierne, ved jeg, hvor nogle måske er. Prøv at lede lige indenfor Glemte Kyst, omkring Vild Ar-dalen.", c="Undersøgte du hudens tekstur? Ordentligt behandlet kunne disse huder meget vel være stærkere end jern. Ikke mange kender til disse huder, og det sammen med de store behandlingsopløsninger, jeg kender, vil give mig mulighed for at lave genstande med et ægte kvalitetsmærke... takket være dig, selvfølgelig!\n\nVælg nu venligst fra, hvad jeg kan tilbyde dig for din tjeneste!"},
  [2822] = {n="Kvalitetens Mærke", l="Bring 10 tykke yetihuder til Klangdor Hurtigskrider i Lejr Mojasje.", d="Jeg er stolt af mit læderarbejde, og jeg synes, det viser sig; kvalitet bør aldrig gå på kompromis. Enhver, der siger, at kvalitet ikke betyder noget, ville også få dig til at tro, at jorden ikke gemmer på hemmeligheder!\n\nI min seneste jagt på materialer af høj kvalitet har jeg opdaget tykke yetihuder. Yetierne er hjemmehørende i Vildalas, ofte fundet vest for her i Vild Ar-dalen. Jeg giver dig et valg af et af mine læderprodukter for en bunke på ti. Hvis det passer dig, så er vi enige!", p="Fik du en bunke på ti tykke yetihuder? Mine læderprodukter er uovertrufne, og jeg deler gerne en prøve med dig, hvis du har huderne.\n\nHvis du ikke kan finde yetierne, ved jeg, hvor nogle måske er. Prøv at lede vest for her, lige indenfor Glemte Kyst omkring Vild Ar-dalen.", c="Ah, fortræffeligt! Disse huder er, når de får en særlig behandling, lige så modstandsdygtige som jern, siger jeg dig! Det vil tage mange forsøg at finde den rette blanding til garvningen, men jeg er sikker på, at de vil bringe mit kvalitetsmærke til næste niveau.\n\nDig, <Name>... din hjælp har vist sig uvurderlig for mig. Vær venlig at vælge fra de genstande, jeg har fremstillet."},
  [2843] = {n="Gnomer-væææk!", l="Vent på at Skuti kalibrerer kobold-transponderen.", d="Så længe du har transponderen i din besiddelse, skal du bare træde på pladen, så bliver du teleporteret til Nisseborgen.\n\nDu kan opleve nogle usædvanlige bivirkninger, men ingen af dem burde være permanente... længere.\n\nJeg glemte næsten den vigtigste del - at komme tilbage. Når du er klar til at vende tilbage, skal du bare træde på transpolyporter-pladen i Nisseborgen!\n\nNu skal transponderen kalibreres til din størrelse og vægt.", p="Den er klar!", c="Alt klaret! Når du er klar, skal du bare træde på pladen."},
  [2844] = {n="Kæmpe-vogteren", l="Find den tabte nattenisse-pige.", d="Jeg er ikke god nok, <Name>. Jeg skulle 'a' holde øje med min lille ven, Skæ, og på en eller anden måde slap hun væk fra mig. Jeg er ikke helt sikker på, hvad der skete, men sidst jeg så hende, gik vi gennem ruinerne lige nord for her.\n\nAlt var gået fint, men så vendte jeg mig om, og... hun var væk.\n\nNu kan jeg bare ikke helt finde ud af, hvad jeg skal gøre. Har du nogle idéer, <Name>? Jeg er frygtelig bekymret.\n\nHey, hvad med at du går og leder efter Skæ? Dine ben kan bevæge sig meget hurtigere end mine.", c="Åh, jeg er så glad for, at du fandt mig! Jeg må indrømme, at jeg er lidt faret vild... Men er det ikke et smukt sted?"},
  [2845] = {n="Vandrende Skæ", l="Saml Skæs Klokke op fra kisten.\n\nEskortér Skæ Bladløber til Stenbiders lejr.", d="Tror du, du kunne hjælpe mig med at finde vej tilbage til min ven, Stenbider? Han skulle have holdt øje med mig... Men jeg har en tendens til at vandre væk nu og da. Der er bare så mange ting at se, og jeg bliver så distraheret.\n\nDer er dog én ting, der altid virker til at få min opmærksomhed.\n\nInde i denne kiste finder du en klokke, som er meget dyrebar for mig. Jeg elsker simpelthen lyden af den. Du har mit ord: Hvis jeg vandrer væk, skal du bare ringe med den, så løber jeg tilbage med det samme.", p="Jeg var ved at blive bekymret for dig! Tusind tak, fordi du bragte Skæ hjem, <Name>.", c="Hvad? Siger du, at den klokke virker, når Skæ løber væk? Nå, det var da noget!\n\nFordi du gjorde så meget for mig, så værsgo, <Name>."},
  [2846] = {n="Dybets Diadem", l="Bring Dybets Diadem til Tabæta i Støvsumpen.", d="For længe siden ejede jeg et smukt smykke, Dybets Diadem. Og ikke nok med at det var pænt – det rummede også stor magt for dem, der havde viden om at bruge det.\n\nDa rygtet om diademet nåede Hydromanter Velrasta, måtte hun have det. Hun sendte agenter til mit hjem, og de stjal det, mens jeg var væk. Tyvene!\n\nJeg vil have mit diadem tilbage! Gå til Zul'Skrald, trolbyen i Tanaris, find Velrasta og vrid diademet ud af hendes hænder. Bring det tilbage til mig, så fortjener du min gunst.", p="Har du diademet, <Name>? Har Velrasta lært, hvad det koster at krydse mig?", c="Vidunderligt! Du fandt det! Og lige så vigtigt – Velrasta har det ikke mere! Tak, <Name>. Jeg står i evig gæld til dig!\n\nHvis jeg lød en smule... gnaven før, så tænk ikke mere over det. Du vil finde mig til at være en meget venligere person over for dem, der ikke har stjålet fra mig."},
  [2847] = {n="Vildt læderrustning", l="Bring 10 Tykt læder til Pratt McGrubbe i Fjermåne-fæstningen.", d="<Name>, du bliver ret dygtig som læderarbejder! Jeg kender nogle mønstre, du måske er interesseret i... Rustning af vildt læder! Vildt læder udnytter de potente og kaotiske egenskaber i vildranker, som findes i områder med frodig vegetation og på nogle af væsenerne dér. Rustningen, der laves af det, er uovertruffen for folk med dine evner, garanteret.\n\nJeg vil lære dig det, men du kommer til at arbejde for mig i noget tid. Første udgift er blot ti stykker tykt læder. Herefter taler vi om detaljerne.", p="Som jeg sagde, du vil arbejde for mig, mens du lærer om rustning af vildt læder. Fordi vildranker både er potente og kaotiske, giver de en tilfældig, men stærk fordel til den allerede stærke rustning, du kommer til at lave. Denne viden var dog ikke let for mig at komme i besiddelse af.\n\nDen første udgift for at begynde denne proces er ti stykker tykt læder.\n\nNår det er gjort, kommer vi til det arbejde, du skal udføre for at skaffe mønstrene.", c="Nå, <Name>, jeg er glad for, at du er med om bord. Du har truffet en klog beslutning som læderarbejder; dem, der bærer læderrustning, vil stå i kø for at få dig til at lave dem, når du har lært at fremstille et af stykkerne af vildt læder.\n\nLad os komme i gang – hvor vil du begynde?"},
  [2848] = {n="Vildt læder-skulderbeskyttere", l="Bring 6 tykke rustningssæt og en vildranke til Pratt McGrubbe i Fjermåne-fæstningen.", d="Skulderbeskyttere af vildt læder støtter bærerens krop ekstremt godt og yder førsteklasses beskyttelse af overarmene og selve skuldrene. Som ved al rustning af vildt læder bliver en potent, men tilfældig fordel påført genstanden, mens vildranken sys ind.\n\nTil dette mønster skal jeg bruge seks tykke rustningssæt og en vildranke. Det burde ikke være en for stor ordre for dig at udfylde.", p="Har du de seks tykke rustningssæt og vildranken, jeg skal bruge?\n\nTænk ikke på rustningssæt som monotont arbejde; den jævne fremstillingsmetode, du udvikler, mens du udøver dit håndværk på disse sæt, hjælper med at udvikle dine færdigheder til det indviklede arbejde, der kræves for at lave rustning af vildt læder.\n\nSe – der er en reel grund til det, du laver for mig...", c="Disse rustningssæt er af solid kvalitet, <Name>. Hvis der er én ting, jeg kræver, ikke kun i mit eget arbejde, men også i arbejdet hos dem, jeg har i tjeneste, så er det kvalitet.\n\nDu har gjort det godt nok til at fortjene dette mønster; jeg håber, det bringer dig de belønninger, det har bragt mig."},
  [2849] = {n="Vildt læder-vest", l="Bring 2 Skildpaddeskæl-brystplader, 2 Skildpaddeskæl-handsker og en vildranke til Pratt McGrubbe i Fjermåne-fæstningen.", d="Vestene af vildt læder er grundstenen i ethvert sæt rustning af vildt læder. Vestens ramme smelter sammen med vildranken og skaber et produkt, der yder maksimal beskyttelse af torsoen, mens den potente magi kan arbejde sig gennem beklædningen.\n\nTil dette mønster skal jeg bruge to skildpaddeskæl-brystplader, to sæt skildpaddeskæl-handsker og en vildranke. Det er en høj ordre, men en, du burde have let ved at udfylde for mig.", p="Har du de to skildpaddeskæl-brystplader og handskerne, jeg bestilte? Glem også ikke vildranken!\n\nAllerede med de tidligste mønstre lærer vi, at fundamentet i formen oversætter godt til mere vanskelige beklædningsstykker. Selvom det er forskellige genstande, forbereder formen på skildpaddeskæl-brystpladerne dig til den detaljering, der kræves for at lave en vest af vildt læder.\n\nOg handskerne... de er bare til min egen fordel. Husk, du arbejder for mig!", c="Dette er nogle meget flotte stykker her, <Name>. Håndværket og omhyggeligheden, der er lagt i at lave disse alene, ville indbringe flere sølvmønter mere end et gennemsnitligt stykke.\n\nDu har opfyldt min ordre, og med det kommer din belønning. Kendskabet til at lave vest af vildt læder er nu dit!"},
  [2850] = {n="Vildt læder-hjelm", l="Bring 2 Natlandskab-tunikaer, 2 Natlandskab-pandebånd og en vildranke til Pratt McGrubbe i Fjermåne-fæstningen.", d="En hjelm af vildt læder giver bæreren overlegen beskyttelse af hovedets vitale områder uden at ofre komfort. Som ved al rustning af vildt læder giver den integrerede vildranke en kraftfuld, men tilfældig forbedring af hjelmens ramme. Læderbærere vil helt sikkert have dette stykke!\n\nTil dette mønster skal jeg bruge to natlandskab-tunikaer, to natlandskab-pandebånd og en vildranke. Udfyld denne ordre, så er mønstret dit!", p="Jeg skal have de tunikaer og pandebånd lavet, og jeg skal også bruge den vildrankestump, før jeg deler kendskabet til hjelme af vildt læder med dig.\n\nHovedbeklædning er meget eftertragtet blandt eventyrere, være sig et afvæbnende simpelt pandebånd eller en fuldt dækkende hjelm. Grundlaget for at lave værdifuld hovedbeklædning forbliver det samme, uanset hvordan beklædningens udseende er.", c="Dette natlandskabs-udstyr, du har leveret, udfylder ordren perfekt, <Name>. Jeg forventer intet mindre af en læderarbejder af din kaliber.\n\nDu har helt bestemt fortjent dette mønster. Jeg giver det til dig frit og håber, du får udbytte af det."},
  [2851] = {n="Vildt læder-støvler", l="Bring 2 Natlandskab-bukser, 2 Natlandskab-støvler og 2 vildranker til Pratt McGrubbe i Fjermåne-fæstningen.", d="Du har lært en del nu, <Name>; alligevel er der mere, du skal lære. Næste er støvler af vildt læder, hjørnestenen i ethvert sæt.\n\nDisse støvler er lavet til at vugge foden i komfort, mens de støtter den mod farerne ved at drage på eventyr. De bløde såler er en velsignelse for dem, der søger lydløs bevægelse i fodtøj.\n\nTil dette mønster skal jeg have en ordre med to par natlandskab-bukser og to par natlandskab-støvler udfyldt. Jeg skal også bruge to vildranker... ikke bare én. Når du har alt dette, så giv mig besked.", p="Ordren på bukserne, støvlerne og vildrankerne skal være udfyldt, før du får mønstret, <Name>. Er du færdig?\n\nFra det tidligste par støvler, vi lærer at lave, begynder vi at forstå, at en god støvle skal balancere på en knivsæg mellem komfort og funktion. Med begge dele kan vi skabe genstande, der lader bæreren ignorere træthed, som ville lamme dem, der bærer varer af lavere kvalitet.", c="Endnu engang har du udfyldt en kompleks ordre med en garvet professionels dygtighed. Du har fortjent dette mønster og min tak."},
  [2852] = {n="Vildt læder-benbeskyttere", l="Bring 2 Skildpaddeskæl-hjelme, 2 Skildpaddeskæl-armbeskyttere og 2 vildranker til Pratt McGrubbe i Fjermåne-fæstningen.", d="Nu hvor det grundlæggende er på plads, er du klar til at mestre mere komplekst stads, <Name>. Benbeskyttere af vildt læder er noget af det stærkeste og mest kraftfulde læderudstyr, der findes. Taljen, lårene, kalvene og de vitale områder – alle får enorm beskyttelse. Sammen med forbedringen, vildranken yder, vil eventyrere, der ejer dem, takke dig, hver gang de ser dig.\n\nTil dette mønster skal jeg have en ordre med to skildpaddeskæl-hjelme, to skildpaddeskæl-armbeskyttere og to vildranker udfyldt.", p="Har du skildpaddeskæl-armbeskytterne og hjelmene klar? Glem ikke de to vildranker, jeg skal bruge!\n\nNu begynder du at indse den potentielle kraft, der ligger i rustning af vildt læder. En rustning, der ingen grænser har i anvendelsen, er næsten uvurderlig for en læderarbejder. Begrænsningerne ligger kun i mængden af ressourcer til at lave genstandene – ikke i kvaliteten af de færdige produkter!", c="Igen har du udfyldt en ordre uden fejl. Måske kommer jeg en dag hen til DIG for at søge viden, hva' <Name>?\n\nHer er mønstret til benbeskytterne, sammen med min tak. Gem denne lære i din viden, og lad dine færdige produkter udnytte dine imponerende evner!"},
  [2853] = {n="Mester i vildt læder", l="Giv Pratts brev til Telonus, Darnassos mester-læderarbejder.", d="Nå, <Name>, du er definitionen på flittighed. Der er ét mønster tilbage for rustning af vildt læder; de andre har du mestret. Jeg vil ikke kræve, at du slider unødigt for mønstret. Du har fortjent det helt og aldeles, og lidt til... men jeg kan ikke give det til dig selv. Min lærer, den, der bragte mig ind i håndværket, er den, der skal belønne dig.\n\nTag dette brev til Telonus; han underviser i læderarbejde i Darnassos. Vis ham brevet, og lad ham anerkende dig som en ligemand, ligesom jeg gør.", p="Hilsner, <Race>... ud fra dit ydre kan jeg se, at du er en læderarbejder, ligesom jeg er. Er du kommet for at trække på mine færdigheder, eller har du måske andre ærinder hos mig?", c="Ah ja, Pratt sendte dig. Selvom han er et menneske, minder han mig nogle gange om os nattealfer. Hans hengivenhed og hans talent med læder er imponerende. At han roser dig så i dette brev, er et tegn på respekt, som jeg anerkender.\n\nJeg er klar over, at han har lært dig kunsten at lave vildt læder. Lad mig afslutte din oplæring med dette mønster. Brug det godt; få i verden kender hemmelighederne bag kapper af vildt læder."},
  [2854] = {n="Vildt læderrustning", l="Bring 10 Tykt læder til Klangdor Hurtigskrider i Lejr Mojasje.", d="<Name>, din dygtighed som læderarbejder går dig i forvejen. Jeg besidder viden om læderarbejde, som du ville være klog at tilegne dig... rustning af vildt læder! Vildt læder udnytter de potente og kaotiske egenskaber i vildranker, som findes i områder med frodig vegetation og på nogle af væsenerne dér. Rustning lavet med det er uovertruffen for en håndværker af din dygtighed, garanteret.\n\nJeg vil lære dig det, men du kommer til at arbejde for mig i noget tid. Første udgift er blot ti stykker tykt læder. Herefter taler vi om detaljerne.", p="Vi må være klare: Du skal være min lærling, mens du lærer kunsten at lave rustning af vildt læder. Fordi vildranker både er potente og kaotiske, giver de en tilfældig, men stærk fordel til den allerede stærke rustning, du kommer til at lave. Denne viden var dog ikke let for mig at tilegne mig.\n\nDen første udgift for at begynde denne proces er ti stykker tykt læder.\n\nNår det er gjort, kommer vi til det arbejde, du skal udføre for at skaffe mønstrene.", c="Nå, <Name>, jeg er glad for, at du er med om bord som min lærling. Du har truffet en klog beslutning som læderarbejder; dem, der bruger læderrustning, vil stå i kø for at få dig, når du har lært at mestre kunsten at lave vildt læder.\n\nLad os komme i gang – hvor vil du begynde?"},
  [2855] = {n="Vildt læder-skulderbeskyttere", l="Bring 6 tykke rustningssæt og en vildranke til Klangdor Hurtigskrider i Lejr Mojasje.", d="Skulderbeskyttere af vildt læder støtter en bærers krop ekstremt godt og yder fremragende beskyttelse af overarmene såvel som skuldrene. Som ved al rustning af vildt læder indgydes genstanden en tilfældig, men meget potent forbedring, mens vildranken sys ind.\n\nTil dette mønster skal jeg bruge seks tykke rustningssæt og en vildranke. Det burde ikke være en for stor ordre for dig at udfylde.", p="Har du de seks tykke rustningssæt og vildranken, jeg skal bruge?\n\nTænk på at lave rustningssæt som en lektion i jævn og pålidelig fremstilling; den konsekvente fremstillingsmetode, du udvikler, mens du udøver dit håndværk på disse sæt, hjælper med at udvikle dine færdigheder til det indviklede arbejde, der kræves for at lave rustninger af vildt læder.\n\nHver lektion har et formål, <Name>. Det er vigtigt at omfavne hver enkelt på den rette måde.", c="Disse rustningssæt er af solid kvalitet, <Name>. Hvis der er én ting, jeg kræver, ikke bare i mit arbejde, men også i arbejdet hos dem, jeg giver undervisning, så er det kvalitet.\n\nDu har gjort det godt nok til at fortjene dette mønster; jeg håber, det bringer dig de belønninger, det har bragt mig."},
  [2856] = {n="Vildt læder-vest", l="Bring 2 Skildpaddeskæl-brystplader, 2 Skildpaddeskæl-handsker og en vildranke til Klangdor Hurtigskrider i Lejr Mojasje.", d="Vestene af vildt læder er grundstenen i ethvert sæt rustning af vildt læder. Vestens ramme og den vildranke, der er vævet ind i den, skaber et produkt, der yder maksimal beskyttelse af torsoen, mens den potente magi kan arbejde sig gennem beklædningen.\n\nTil dette mønster skal jeg bruge to skildpaddeskæl-brystplader, to sæt skildpaddeskæl-handsker og en vildranke. Dette er ingen let lektion, men en du helt sikkert har evnerne til at gennemføre.", p="Har du de to skildpaddeskæl-brystplader og handskerne? Glem også ikke vildranken!\n\nAllerede med de tidligste mønstre lærer vi, at fundamentet i formen oversætter godt til mere vanskelige beklædningsstykker. Selvom det er forskellige genstande, forbereder formen på skildpaddeskæl-brystpladerne dig til den detaljering, der kræves for at lave en vest af vildt læder.\n\nNår du skrider frem i dine lektioner, vil de færdigheder, jeg lærer dig, blive til kunst.", c="Det er nogle meget flotte stykker her, <Name>. Håndværket og omhyggeligheden, der er lagt i at lave disse, viser, at du har valgt at vie dig fuldt ud til disse opgaver.\n\nDu har opfyldt mine krav, og med det kommer din belønning. Kendskabet til at lave vest af vildt læder er nu dit!"},
  [2857] = {n="Vildt læder-hjelm", l="Bring 2 Natlandskab-tunikaer, 2 Natlandskab-pandebånd og en vildranke til Klangdor Hurtigskrider i Lejr Mojasje.", d="En hjelm af vildt læder giver bæreren overlegen beskyttelse af hovedets vitale områder uden at ofre komfort. Som ved al rustning af vildt læder giver den integrerede vildranke en kraftfuld, men tilfældig magisk indgydelse til hjelmens ramme. Læderbærere vil helt sikkert have dette stykke!\n\nTil dette mønster skal jeg bruge to natlandskab-tunikaer, 2 natlandskab-pandebånd og en vildranke. Gennemfør denne lektion, så er mønstret dit!", p="Jeg skal have de tunikaer og pandebånd lavet, og jeg skal også bruge den vildrankestump, før jeg deler kendskabet til hjelme af vildt læder med dig.\n\nHovedbeklædning er meget eftertragtet blandt eventyrere, være sig et afvæbnende simpelt pandebånd eller en fuldt dækkende hjelm. Grundlaget for at lave værdifuld hovedbeklædning forbliver det samme, uanset hvordan beklædningens udseende er.", c="Dette natlandskabs-udstyr, du har leveret, opfylder de krav, jeg har stillet, perfekt, <Name>. Jeg forventer intet mindre af en læderarbejder af din kaliber.\n\nDu har fortjent æren af at lave hjelme af vildt læder. Jeg giver dette mønster til dig frit og håber, du får udbytte af det."},
  [2858] = {n="Vildt læder-støvler", l="Bring 2 Natlandskab-bukser, 2 Natlandskab-støvler og 2 vildranker til Klangdor Hurtigskrider i Lejr Mojasje.", d="Din viden om rustning af vildt læder vokser, <Name>; alligevel er der mere, du skal lære.\n\nStøvler af vildt læder er hjørnestenen i ethvert sæt. Sådanne støvler er lavet til at vugge foden i komfort, mens de støtter den mod farerne ved at drage på eventyr. De bløde såler er en velsignelse for dem, der søger lydløs bevægelse i fodtøj.\n\nTil dette mønster skal jeg have to par natlandskab-bukser og to par natlandskab-støvler lavet. Jeg skal også bruge to vildranker... ikke bare én. Når du har disse genstande, går vi videre.", p="Bukserne, støvlerne og vildrankerne skal leveres til mig, før du lærer mønstret, <Name>. Har du gjort, som jeg bad om?\n\nFra det tidligste par støvler, vi lærer at lave, begynder vi at forstå, at en god støvle skal balancere på en knivsæg mellem komfort og funktion. Med begge dele kan vi skabe genstande, der lader bæreren ignorere træthed, som ville lamme dem, der bærer varer af lavere kvalitet.", c="Endnu engang har du produceret genstande med en garvet professionels dygtighed. Du har fortjent dette mønster og mine lykønskninger."},
  [2859] = {n="Vildt læder-benbeskyttere", l="Bring 2 Skildpaddeskæl-hjelme, 2 Skildpaddeskæl-armbeskyttere og 2 vildranker til Klangdor Hurtigskrider i Lejr Mojasje.", d="Du er klar til at mestre mere komplicerede lektioner, <Name>. Benbeskyttere af vildt læder er noget af det stærkeste og mest kraftfulde læderudstyr, der findes. Taljen, lårene, kalvene og de vitale områder – alle får enorm beskyttelse. Sammen med forbedringen, vildranken yder, vil eventyrere, der ejer dem, takke dig, hver gang de ser dig.\n\nFor at du kan opnå dette mønster, skal jeg bruge to skildpaddeskæl-hjelme, to skildpaddeskæl-armbeskyttere og to vildranker.", p="Har du skildpaddeskæl-armbeskytterne og hjelmene klar? Glem ikke de to vildranker, jeg kræver!\n\nNu begynder du at indse den potentielle kraft, der ligger i rustning af vildt læder. En rustning, der ingen grænser har i anvendelsen, er næsten uvurderlig for en læderarbejder. Begrænsningerne ligger kun i mængden af ressourcer til at lave genstandene – ikke i kvaliteten af de færdige produkter!", c="Igen har du fuldført min opgave uden fejl. Måske kommer jeg en dag hen til DIG for at søge viden, hva' <Name>?\n\nHer er mønstret til benbeskytterne, sammen med min tak. Gem denne lære i din viden, og lad dine færdige produkter udnytte dine imponerende evner!"},
  [2860] = {n="Mester i vildt læder", l="Giv Klangdors brev til Ula, Tordenklippes mester-læderarbejder.", d="<Name>, du har lært alt, hvad jeg er i stand til at lære dig. Der er dog ét mønster tilbage for rustning af vildt læder. Jeg vil ikke kræve, at du slider unødigt for dette; du har fortjent det helt og aldeles, og lidt til. Dette mønster er dog et, jeg ikke frit kan dele med dig.\n\nMin lærer, den, der bragte mig ind i håndværket, er den, der skal belønne dig. Tag denne note til Ula; hun underviser i læderarbejde i Tordenklippe. Vis hende brevet, og lad hende anerkende dig som en ligemand, ligesom jeg gør.", p="Hilsner, <Race>... ud fra dit ydre kan jeg se, at du er en læderarbejder, ligesom jeg er. Er du kommet for at trække på mine færdigheder, eller har du måske andre ærinder hos mig?", c="Ah ja, Klangdor sendte dig. Jeg er glad for at se, at en af mine fineste elever nu har en elev af sin egen.\n\nHans hengivenhed og hans talent med læder er imponerende. At han roser dig så i dette brev, er et tegn på respekt, som jeg anerkender.\n\nJeg er klar over, at han har lært dig kunsten at lave vildt læder. Lad mig afslutte din oplæring med dette mønster. Brug det godt; få i verden kender hemmelighederne bag kapper af vildt læder."},
  [2861] = {n="Tabætas opgave", l="Tal med Tabæta i Støvsumpen.", d="Ryget går om, at Tabæta, en magikerkollega, der bor dybt i Støvsumpen, har en knogle at gnave med en bestemt sandtroldmand i Zul'Skrald. Hvis du taler med Tabæta, kan hun fortælle dig mere.\n\nOg tag nogle venner med, <Name>. Hvis Tabæta sender dig til Zul'Skrald, vil du ikke ønske at gå alene.\n\nDu finder Tabætas hytte vest for Theramøre og lige nord for Stenknuser-ruinen.", c="Det er rigtigt. Jeg har en knogle at gnave med en trold. Et par knogler. Alle hendes knogler!\n\nVil du hjælpe mig?"},
  [2862] = {n="Krig mod Træpoterne", l="Bring 10 Træpote-gnoldmanker til Hadoken Hurtigskrider i Lejr Mojasje.", d="Gnoldene... de er mere end en plage. De er en konstant trussel mod selve denne lejrs eksistens! Det er ligegyldigt, om de er oprindelige til Vildalas eller ej; hvis vi ikke styrker vores beslutsomhed mod dem, vil vi finde os selv drevet ud af hele regionen.\n\nGnoldenes angreb mod lejren er blevet mere hidsige på det seneste. Vi har brug for din hjælp til at tynde deres rækker; bring mig ti af deres manker, og jeg vil belønne dig rigeligt for din indsats.\n\nAfsted!", p="Vi driver dem tilbage, og alligevel angriber de stadig! Nogen eller noget må drive dem til raseri... å, du er vendt tilbage, hva' <Name>? Har du de manker, jeg skal bruge, så dusøren kan blive indfriet?", c="Dette er bevis på en god start, <Name>. Dine færdigheder som soldat fortjener ros.\n\nDu er ikke den eneste, jeg giver den opgave. Mange før dig har kæmpet mod dem, og i fortiden har vores indsats holdt dem fra døren. Men på det seneste er deres forsøg på at skubbe nordpå ind i vores indflydelsesområde steget dramatisk. Deres angreb er også blevet mere brutale... næsten, som om de var desperate.\n\nJeg har dog en plan, <Name>, der måske kan afgøre sagen mod dem én gang for alle..."},
  [2863] = {n="Alfa-slaget", l="Dræb 5 Træpote-alfaer og vend tilbage til Hadoken Hurtigskrider inden for én time.", d="Planen er, at forskellige ledere blandt gnoldene – Alfaer, kalder de sig selv – skal nedlægges i hurtig rækkefølge. Hvis vi kan udføre denne slags hurtige og præcise ødelæggelse mod dem, vil det skabe kaos i deres rækker. Måske vil det også hamre en besked ind i deres tykke, lopperiddede hjerner, at vi kan og vil tilintetgøre dem!\n\nJeg vil have dig til at være bærer af min vilje; eliminér fem af deres alfaer inden for én time, for at dette kan virke, <Name>, ellers står vi fast i dette dødvande!", p="Tiden løber ud, <Name>! Hvis du ikke er her for at melde, at du har slået alfaerne ihjel, så spilder du din tid!", c="Du har gjort, som jeg bad om, og for det hilser jeg dig. Tag denne lille belønning som kompensation for din indsats, <Name>.\n\nNu hvor deres rækker er tyndet ud, og deres ledere er faldet, vil gnoldene tænke sig om to gange, før de stormer lejren. Dette afslutter dog ikke sagen...\n\nDer må være en grund til, at gnoldene er blevet piskede op i sådan en rasende tilstand. Før de får chancen for at samle sig igen, vil jeg finde ud af, hvad der forårsager det."},
  [2864] = {n="Tran'Snusk", l="Tal med Tran'Snusk i Gadgetbyen.", d="Min fætter Tran'Snusk er i en svær situation. Han lovede mig en læsset mængde bassesskaller for flere uger siden, og han har ikke leveret. Han er min fætter, så jeg ville hade at skulle sende nogen til Gadgetbyen for at knække noget på ham.\n\nKan du tale med Tran'Snusk for mig? Lad ham vide, at han skal få den leverance samlet, før jeg gør noget overilet?\n\nGadgetbyen ligger i det nordlige Tanaris, i Kalimdør.", c="Hej!\n\nÅh, du talte med min fætter Krazek? Hvordan har han det? Jeg håber, Bytteviken behandler ham godt...\n\nBassesskaller, siger du? Nå... lad mig fortælle dig en historie..."},
  [2865] = {n="Bassesskaller", l="Bring 5 uknækkede bassesskaller til Tran'Snusk i Gadgetbyen.", d="Bassene i Tanaris har meget hårde skaller! Hårde nok til at bruge som byggemateriale til mange ting. Så mange ting!\n\nFaktisk er de skaller så nyttige... at bassene næsten blev jagtet til udryddelse!\n\nJeg ved, hvor der er flere basser, og hvis du lover at bringe mig deres skaller, så fortæller jeg dig, hvor de er. Lover du det?\n\nOkay, bassene har en koloni i Zul'Skrald. Jeg gætter på, at trolde ikke jager dem for deres skaller.\n\nMen det kan du! Gå til Zul'Skrald og hent mig uknækkede skaller!", p="Har du skallerne? Min fætter i Bytteviken venter på en læs af dem, og han bliver utålmodig!", c="Å, dejligt! Du fik dem!\n\nTak, <Name>. Du er en virkelig redningsmand!"},
  [2866] = {n="Solsalens ruiner", l="Udforsk Solsalens ruiner og undersøg tilstedeværelsen af slangefolket dér.", d="Mod syd ligger Solsalens ruiner; dette er et område, der er langt ældre end moderne tid. Vi udforskede ruinerne i første omgang og fandt intet bemærkelsesværdigt; derfor lod vi dem være i fred.\n\nFor nylig har Hadkam-slangefolket besat disse ruiner i alarmerende antal. Til at begynde med anså vi det for at være forløberen til et angreb. Selvom den trussel stadig er mulig, tror vi, at der måske foregår noget andet.\n\nGå derhen, udforsk ruinerne og led efter alt, der skiller sig ud for dig. Held og lykke, <Name>.", c="Når man undersøger lysthuset, afsløres nogle interessante og usædvanlige ting i kontrast til de omkringliggende ruiner.\n\nFor det første er lysthuset tydeligvis en nyere konstruktion end de andre genstande i ruinerne. For det andet har lysthuset en lille række glyffer indgraveret i siderne; glyfferne gentager sig i deres mønster, men ellers er deres oprindelse og betydning ukendt. For det tredje er stenen i selve lysthuset varm at røre ved.\n\nDette kvalificerer helt sikkert som at 'skille sig ud' i eftersøgningen af ruinerne!"},
  [2867] = {n="Tilbage til Fjermåne-fæstningen", l="Vend tilbage til Shandris Fjermåne i Fjermåne-fæstningen og rapportér dine fund.", d="Med opdagelsen af det mærkelige lysthus i hjertet af Solsalens ruiner er tiden kommet til at vende tilbage til Fjermåne-fæstningen og rapportere til General Shandris Fjermåne, hvad der er blevet opdaget her.", c="Velkommen tilbage, <Name>. Din rapport om dette lysthus er... ret foruroligende. Det ser ud til, at selv om slangefolket der ikke planlagde et angreb, bebuder deres vedvarende tilstedeværelse ikke godt for vores fremrykning ind i Vildalas. Under alle omstændigheder er her kompensation for din undersøgelse.\n\nDet ser ud til, at Fjermåne-fæstningen har desperat brug for yderligere hjælp vedrørende Hadkam-slangefolket. Jeg vil gerne tilbyde dig opgaven, hvis du har lyst. Der er meget at gøre."},
  [2869] = {n="Mod Hadkam", l="Bring 10 Hadkam-slangeskæl til Latronicus Månespyd i Fjermåne-fæstningen.", d="Den bedste fremgangsmåde på dette tidspunkt er at antage, at slangefolket, uanset hvad de har gang i, til sidst vil flytte for at sikre øen for sig selv. Vi må tage aggressive skridt for at modvirke den trussel, før det er for sent.\n\nBring mig ti Hadkam-skæl, der er i god stand; det burde være indlysende for dig, hvordan du skaffer dem. Du får dine tænder i slangefolket for første gang, og vi får en svækket slangefolks tilstedeværelse på Sardor Ø – begge dele er udsigter, der spiller os i hænde.", p="<Name>, hvis du er her for at bekræfte opgaven, du fik, så er det fortrinligt – det er ti Hadkam-skæl, jeg søger. Hvis du er her for småsnak, er jeg i øjeblikket ikke tilgængelig for sådanne trivialiteter.\n\nVid dette – vi nattealfer er ikke krigsmagere. Vores folk er dedikeret til at bevare fred og harmoni. Det betyder dog ikke, at vi ikke vil beskytte vores egne interesser proaktivt. Dette er min pligt over for General Fjermåne og fæstningen.", c="Ja, ja, disse skæl er mere end tilfredsstillende. Faktisk tror jeg, jeg sender dem ned til Pratt, så han kan kigge på dem. Måske kan han lave noget nyttigt ud af dem.\n\nHvad dig angår, har jeg en anden mission, jeg gerne vil sende dig på. Men først, her er din dusør for skællene. Din fortsatte tjeneste for generalen og Fjermåne-fæstningen som helhed er en velsignelse i modgang."},
  [2870] = {n="Mod Herre Shalzarn", l="Eliminér Herre Shalzarn, og bring derefter den mystiske relikvie, han har fundet, til Latronicus Månespyd i Fjermåne-fæstningen.", d="<Name>, nye spejderrapporter har givet os en god idé om slangefolkets kommandostruktur. Kongelige er til stede blandt deres rækker, og det er dem, der bestemmer alt.\n\nKonkret har vi identificeret en af de grusommere kongelige som Herre Shalzarn. Spejdere rapporterer, at han selv har fundet en mærkelig relikvie under en nylig udgravning af slangefolket i en hule syd for hovedruinerne, på tværs af vandet på Rædsels Ø.\n\nStop det ved at stoppe ham, og bring mig hans relikvie, så vi kan studere den.", p="At nedlægge Herre Shalzarn vil helt sikkert sætte deres planer tilbage i flere uger, hvis ikke måneder. Derudover er relikvien, han har fundet, af klar interesse for os.\n\nHar du udført den opgave, du fik, <Name>?", c="Velspillet, <Name>! Herre Shalzarns fald vil kaste slangefolket ud i uorden i et stykke tid, hvis ikke permanent. Den trussel, de udgør, er nu under større kontrol end nogensinde, og det har vi dig at takke for.\n\nHer er mere dusørpenge fra fæstningens skatkammer – du har fortjent hver eneste skilling. Du og dine er altid velkomne i Fjermåne-fæstningen, min ven.\n\nÉn ting mere, før du går, <Name>... hvis du kunne..."},
  [2871] = {n="Afleveringen af relikvien", l="Lever den mystiske relikvie til Vestina Månespyd i Fjermåne-fæstningen.", d="Hvis du så venligt ville levere relikvien til min kone Vestina, ville jeg sætte stor pris på det. Hun er ikke kun en fin præstinde for vores fællesskab, men også en af de mest velbelæste lærde, du kan finde hvor som helst. Jeg kunne ikke få hoved eller hale i denne apparat, selv om der var en vædde i spil. Min kone derimod, hvis nogen kan regne ud, hvad det her ting er, så kan hun... og vi må vide det!\n\nHun er lige rundt om hjørnet, uden tvivl i gang med at studere. Tak, <Name>.", p="Ja, må jeg hjælpe dig?\n\nVent lidt, du er den <Class>, der har hjulpet General Fjermåne og Latrø med slangefolk-truslen, ikke? Jeg er Vestina, Latrøs - øh, rettere sagt Latronikus' kone. Det er en fornøjelse at møde dig!\n\nJeg beklager, du er her i ærinde, selvfølgelig. Har du noget til mig - fra ham, måske?", c="Interessant... den her kom fra Solsals ruiner, siger du? Nå, Latrø har ret i, at jeg må kigge på den. Ved første øjekast virker det som om, den ikke er hjemmehørende i ruinerne. Men så igen, den her er ikke af slangefolk-design... ikke noget så fremmedartet som dette.\n\nDet vil tage noget tid at researche denne genstand. Når min research er færdig, vil jeg måske gøre brug af dine talenter, hvis du er i nærheden.\n\nHer, tag en af de ekstra ting, vi har; jeg håber, du kan finde en brug for den!"},
  [2872] = {n="Stollis gæld", l="Tal med Stolli i Dampsmiger Portvin.", d="Min gamle makker Stolli skylder mig en meget speciel flaske rom. Han står bag baren i Dampsmiger Portvin i Tanarisørknen, Kalimdør, og han lovede mig, at rommen dér er stærkere end noget, vi kan finde i Bytteviken. Han er så sikker på sig selv, at han siger, at hvis jeg prøver rommen og ikke er enig med ham, så fordobler han pengene, han skylder mig!\n\nNu tror jeg nok, han ikke er lige så sikker, som han var, da vi sidst talte sammen, og nu er han bange for at give mig den rom. Men jeg trækker mig ikke fra væddemål, så hvorfor taler du ikke med ham for mig...", c="Ah, så du har talt med Makkinlæj, har du?\n\nDet er ikke, hvad han tror! Jeg er ikke bange for at give ham noget Dampsmiger Bundrom...\n\nJeg har bare ikke noget rom at give ham!"},
  [2873] = {n="Stollis forsendelse", l="Bring Stollis forsendelse til Stolli i Dampsmiger Portvin.", d="Jeg skylder „Havulven“ Makkinlæj i Bytteviken noget rom for at afgøre et væddemål, men jeg er helt tom for rom! Kaptajn Kuergo stjal min sidste forsendelse, og han har gemt den i den befæstede pirat-by mod syd.\n\nHvis du kan finde min forsendelse med rom og returnere den til mig, så kan jeg bevise over for Makkinlæj, at Kalimdørs sprut slår Bytteviken i gulvet!", p="Fandt du min forsendelse med rom, <Name>?", c="Super, tak for forsendelsen! Nu kan Makkinlæj og jeg endelig afgøre vores væddemål."},
  [2874] = {n="Levering til Makkinlæj", l="Bring Stollis flaske til „Havulven“ Makkinlæj i Bytteviken.", d="Tak igen for din hjælp, <Name>. Her er en flaske Dampsmiger-bundrom. Tag den med til Makkinlæj, så kan han endelig lægge sine skøre forestillinger om Bytteviken-sprut til hvile.", p="Fik Stolli spyttet min sprut ud?", c="Hm, lad os prøve det her...\n\nJeg kan ikke tro det! Det her er... forfærdeligt! Det er fantastisk!\n\nNå, jeg gætter på, at Stolli kan beholde de penge, han skylder mig. Han holder ord om Dampsmiger-bundrommen. Den er tyk som grus og brænder som lava!"},
  [2875] = {n="EFTERLYST: Andrø Ildskæg", l="Bring Andrøs hoved til sikkerhedschef Bundsnurr i Dampsmiger Portvin.", d="Den nederdrægtige pirat Andrø Ildskæg efterlyses for forbrydelser mod Dampsmiger og Gadgetbyen.\n\nVed beslutning fra det styrende råd har enhver, der læser dette, hermed tilladelse til at bruge dødelig magt under anholdelsen af Andrø og hans medsammensvorne.\n\nVed yderligere beslutning gælder det, at hvis Andrø er død eller på anden måde ude af stand til at møde op under sin høring, kan hans hoved fungere som stedfortræder, og aflevering af et sådant hoved til sikkerhedschef Bundsnurr udgør en bindende og indfrielig kontrakt.", p="Du ser lidt omtåget ud. Har du læst vores juridiske dokumenter?", c="Ah, Andrøs hoved. Så han får vel alligevel sin retssag!\n\nSat pris på, <Name>. Hvis du lige vil skrive under her, kan jeg udbetale din betaling for ydede tjenester.\n\nBekymr dig ikke om det med det små. Det er harmløst, og... jeg tror ikke, der findes et forstørrelsesglas lille nok til at læse det alligevel."},
  [2876] = {n="Skibsplaner", l="Aflever skibsplanerne til en myndighed i Dampsmiger Portvin.", d="Denne rulle indeholder skibsplanerne for forsendelser mellem Dampsmiger Portvin og Bytteviken. Både tidligere og kommende forsendelser er medtaget, sammen med skibsnavne, med store „X“er ved siden af nogle skibes rejser, og noter som „STOR BYTTE“ og „HÅRD KAMP“ ved siden af andre.\n\nNogen i Dampsmiger Portvin ville gerne se dette dokument.", p="Du ser forpustet ud. Har du noget at fortælle mig?", c="Åh, min. Dette ser ud til at være en liste over skibsafgange og -ankomster, med nøjagtige datoer og klokkeslæt og det hele! Hvis en piratkaptajn fik fingrene i dette, kunne han have sig selv en gylden dag!\n\nSiger du, du fik det fra en pirat? Ja, det er foruroligende nyheder...\n\nTak, <Name>. Jeg er glad for, at du tog det fra ham, og jeg er glad for, at den pirat spiser jord lige nu!"},
  [2877] = {n="Oprydning i Snigeklippe", l="Dræb 10 grønne slam og 10 jadesliger, og rapportér derefter tilbage til Fraggar Tordenkappe i Ørnerede-toppen.", d="Vi Vildhammere husker fortiden, mere end vores brødre i Jernsmede. Hvis du vil gøre dig venner her, så må du tage fat for os!\n\nHorden forlod deres positioner i Bagland omkring Snigeklippe; nu er området oversvømmet af ækle slam og sliger. Vi har planer for området, men først skal vi have et oprydningshold til at lave en åbning for os.\n\nDet er her, du kommer ind i billedet, Solskin! Tag derned og fjern ti grønne slam og ti jadesliger, og rapportér så tilbage til mig her. Afsted med dig!", p="Gør ikke noget forsøg på at forhandle den opgave, der ligger foran dig, <Race>! Hvis guderne havde ønsket, at sligerne skulle dø, havde de allerede fået det gjort med et mirakel, ikke sandt?!", c="Se lige dig, der hjælper Vildhammerne! Du er en <Class> med handlekraft, og handling er det, vi respekterer her omkring.\n\nDin lille oprydningsmission er langt vigtigere, end du måske tror. Når folk tynder ud i sligerne og slammet, kan vi udvide vores indflydelsessfære på ingen tid. Her - tag en lille ekstra ting med, udover bare at få nye venner her i Ørnerede-toppen!"},
  [2879] = {n="Equinex-stavet", l="Energisér Trojas' stav og find Equinex-monolitten.", d="Denne stav er måske Equinex-staven! Equinex-staven er faktisk en nøgle, der bruges til at låse Equinex-monolitten op i Ruinerne i Ravnevinden, på fastlandet vest for Drømmegrenen.\n\nFind de fire flammer, der stadig brænder i ruinerne: Samma, Imbeld, Bylten og Lahasse. Hent deres essens, og mens du står ved Equinex-monolitten, skal du bruge essenserne til at energisere staven. Hvis dette virkelig er Equinex-staven, vil du kunne låse monolitten op og hente en hellig genstand fra den.", p="Equinex-monolitten står tavst blandt ruinerne. Hvad mon den holder på?", c="Det er næsten umuligt at holde den energiserede stav. Dens kraft buldrer gennem din krop.\n\nDu rækker ud mod Equinex-monolittens kolde overflade...\n\nEn lille dør åbner sig, så du kan række ind og tage genstanden derinde.\n\nLysstråler fylder området omkring Equinex-monolitten."},
  [2880] = {n="Dusør på trolde-halskæder", l="Bring 5 trolde-stammehalskæder til Fraggar Tordenkappe i Ørnerede-toppen.", d="Forstå det klart, <Race> - vi er IKKE en del af Alliancen! Vildhammerne er uafhængige, og vi stoler på handling og bedrifter for at bevise ens værd, snarere end vrøvlet fra dem, der bruger pralesnak til at støtte deres ingenting-gør-holdning!\n\nHvis du leder efter venner her, så bevis først dit værd over for os! De grimme trolde, der kvæler skråningerne i Bagland, bærer nogle gange stammehalskæder. Bring mig fem af dem, så noterer vi det som et skridt i den rigtige retning for dig.", p="Jeg vil have fem af de stammehalskæder, trollerne bærer på sig. Hvis du har brug for det uddybet, så er der god chance for, at du får en, hvis du dræber en af dem!\n\nBevis dit værd over for Vildhammerne!", c="Nu taler vi! Se - disse halskæder beviser, at du er villig til at tage fat. Vi Vildhammere sætter pris på det hos dem, vi omgås med.\n\nFortsætter du sådan, står du snart på god fod hos os."},
  [2902] = {n="Træpote-undersøgelsen", l="Find hyænemændenes kampplaner et sted i hyænemandslejrene syd for Lejr Mojasje.", d="Hyænemænd er ikke de skarpeste værktøjer i skuret, men de har uden tvivl en slags dokumenteret strategi for deres seneste aktivitet. Hvis vi kunne finde disse planer, ville vi have et klarere billede af, hvad der får dem så oprevede.\n\nJeg vil have dig tilbage til Træpote, og finde noget, der minder om deres kampplaner. De må have noget; deres angreb har været for koordinerede til at være udført uden dem. Find dem, og kom tilbage til mig, når du har dem.", c="Kortet viser sig at være de kampplaner, Hadoken Hurtigstrider ønsker. Adskillige pile, der måske repræsenterer troppebevægelser, er tegnet på kortet, selvom de fleste ser ud til at pege mod syd i stedet for mod nord, hvor Lejr Mojasje ligger.\n\nEt andet afsnit af kortet har et billede af, hvad du tror er et stort insekt af en slags, med forskellige tællestreger under sig. Ud fra hyænemændene at dømme forestiller det måske deres tab mod de ukendte insekter..."},
  [2903] = {n="Kampplanerne", l="Bring Træpote-kampplanerne til Hadoken Hurtigstrider i Lejr Mojasje.", d="Nu hvor hyænemændenes kampplaner er fundet, er det eneste tilbageværende at bringe planerne tilbage til Hadoken Hurtigstrider i Lejr Mojasje. Måske kan han, eller nogen dér, få mening ud af, hvad hyænemændene har gang i.", p="Velkommen tilbage, <Name> - fandt du nogle håndgribelige beviser på hyænemændenes planer?", c="Ah, dette er præcis, hvad vi havde brug for. Selvom jeg ikke er særlig dygtig til at tyde det meste af krydset på dette kort, har jeg set nok kampplaner i min tid til at forstå, hvad der sker med hyænemændene. Det ser ud til, at de lige nu fører krig på to fronter. Den ene er mod os... men det virker til, at deres hovedkraft har været rettet mod en fjende mod syd.\n\nDer er mere på spil her, end man umiddelbart ser. Måske er det på tide at finde ud af, hvem denne anden fjende de står over for virkelig er."},
  [2932] = {n="Dyster besked", l="Saml Vissenbark-kranier og placér dem på Nimboyas pike. Placér Nimboyas lastede pike i en af Vissenbark-landsbyerne i Bagland, og vend derefter tilbage til Nimboya i Kvælertorn.", d="Vissenbark-trollene var engang allierede med Horden, men de forrådte Trall... og det må straffes!\n\nHer, tag min pike og tag til Bagland, langt mod nord. Du finder den nordøst for Tarrenmølle, en landsby holdt af vores allierede, De Forladte.\n\nNår du kommer ind i Bagland, skal du jage Vissenbark-trolde. Saml deres kranier, og bank min pike ned i jorden ved en af deres mindre landsbyer, Hiri'vatha eller Zun'vatha.\n\nVis dem, at deres ondskabsfulde handlinger har konsekvenser!", p="Du har ikke fuldført min opgave, <Name>.", c="Nyheden om din gerning nåede mig. En dyster gerning, men en gerning af ære. Lad os håbe, at Vissenbarkerne tager din besked til sig."},
  [2933] = {n="Giftflasker", l="Bring en giftflaske til en apoteker i Tarrenmølle.", d="Disse flasker indeholder et ondt, grønt gift.\n\nUd fra antallet af flasker i denne landsby må Vissenbarkerne anse det for meget vigtigt. Måske ville en apoteker i nærliggende Tarrenmølle gerne have en prøve.", p="Hej, venlige <Class>. Dagen har været lang, og ikke et eneste eksperiment er lykkedes... Jeg håber, du bringer mig gode nyheder.", c="Ah, og hvad er dette? Det ser ud til at være gift... fra et edderkoppelignende væsen, vil jeg vurdere. Og hvor fik du det fra?"},
  [2934] = {n="Uskadt giftsæk", l="Bring en uskadt giftsæk til Apoteker Lydon i Tarrenmølle.", d="Jeg må have en frisk prøve af det gift, du bragte mig. Edderkopperne, som det blev indsamlet fra, må bo i Bagland - jag dem, indtil du finder en uskadt giftsæk, og bring den til mig. Du finder mange edderkopper nær trollebyen Shadra'Alør.\n\nVent ikke, <Name>, for giftsækken skal være frisk, når du leverer den.", p="Har du den uskadte giftsæk, <Name>? Jeg længes efter at lave eksperimenter med dens friske gift, og jeg har bestilt en samling af små, forfærdeligt søde dyr, som jeg kan teste den på!", c="Åh, storartet! Giften er ganske frisk, og jeg er sikker på, at den er meget dødelig. Tak!"},
  [2935] = {n="Rådfør dig med Mester Gadrin", l="Tal med Mester Gadrin i Sen'jin-landsbyen.", d="Giften fra yngelvogterne var ikke så kraftig som den gift, du bragte oprindeligt. Den må være kommet fra en anden edderkop.\n\nJeg vil have en frisk prøve af den gift. For at finde ud af, hvor den kom fra, må du rådføre dig med en troll, der kender Vissenbarkerne godt - Mester Gadrin i Sen'jin-landsbyen. Rejs til Durdotar og tal med Gadrin. Med lidt held ved han, hvor Vissenbarkerne får deres gift.", c="Ah, så du vil have frisk gift fra Vissenbarkernes edderkop, ja? Nå, sæt dig... du kommer ikke til at kunne lide, hvad jeg har at fortælle dig."},
  [2936] = {n="Edderkoppegudinden", l="Læs fra Tekas tavle for at lære navnet på Vissenbarkernes edderkoppegud, og vend derefter tilbage til Mester Gadrin.", d="Vissenbarkerne tilbeder en edderkoppegud, og fra hende indsamler de deres mest kraftfulde gift. Så hvis du vil have giften, må du kalde deres gud frem!\n\nFor at gøre det må du kende hendes sande navn, og det navn står på en tavle begravet i Tanarisørknen, i trollebyen Zul'Ferrak, i en gravkammer, som bevogtes af Teka Martyren.\n\nBesejr Teka, og find og læs hans tavle for at opdage edderkoppegudens navn. Når du kender det, så vend tilbage til mig.", p="Kender du edderkoppegudens navn?", c="Ah, Elorta af Skyggra... sig dette navn kun i hviskende toner, for dets udtale bærer stor vægt i åndernes riger.\n\nJeg vil skrive det ned på pergament og lave en kaldelsesbesværgelse til dig..."},
  [2937] = {n="Kaldelsen af Skyggra", l="Besejr Shadra ved alteret i Shadra'Alør, og bring derefter hendes gift til Apoteker Lydon i Tarrenmølle.", d="Tag hans pergament, og læs det ved alteret i Shadra'Alør, dybt inde i Vissenbarkernes rige i Bagland. Dette vil kalde Shadra, edderkoppegudinden, frem.", p="Fik du giften?", c="Sådan, du fik den!"},
  [2938] = {n="Gift til Underbyen", l="Bring Faranells pakke til Mesterapoteker Faranell i Underbyen.", d="Giften, du indsamlede fra Vissenbarkernes edderkoppegud, er et virkeligt fund! Jeg har været i stand til at dræbe næsten to snese kaniner med blot en dråbe af stoffet. Riktignok var nogle af kaninerne meget unge og små nok til at passe i håndfladen, så jeg er sikker på, at deres modstandsdygtighed over for toksiner var lav, men det kan ikke benægtes, at dette gift er kraftigt!\n\nJeg vil gerne have en prøve sendt til min overordnede, Apoteker Faranell i Apotekeriet i Underbyen. Jeg er sikker på, at han gerne vil teste den selv.", p="Der er sendt besked om din ankomst, <Name>. Har du en pakke til mig?", c="Ah, meget godt. Lydon nævnte, at giften i denne pakke er den mest potente, han har stødt på, og han er travlt optaget af at finde nye anvendelser for den.\n\nMed lidt held finder vi mange.\n\nTak, <Name>. Din tjeneste for Det Kongelige Apotekerselskab er ubestridelig."},
  [2939] = {n="På jagt efter viden", l="Tal med Daryn Lysvind i Rutteran-landsbyen.", d="Selvom ruinerne i Vildalas kan være ganske farlige, har de meget at fortælle om, hvad der er sket her.\n\nDa jeg for et par dage siden søgte gennem murbrokkerne mod syd, opdagede jeg, hvad der ser ud til at være en almindelig stav. Jeg kan dog ikke ryste følelsen af, at der er mere ved den. Angelia og jeg har gransket i vores bøger her, men vi kan ikke finde noget om den.\n\nJeg har en kollega i Darnassos, som måske kan fortælle os, hvad dette er, <Name>. Hvorfor ikke tale med hende og se, om hun kan hjælpe os?", c="Åh, så Trojas Månebris sendte dig?\n\n<mumler>...altid til at plage mig med hans vilde ideer om, at han har fundet noget vigtigt...\n\nSe, <Name>, jeg vil være ligefrem. Trojas tror altid, han har fundet noget vigtigt i de ruiner. Sandheden er, at alt, der virkelig var værdifuldt, nok for længst blev gemt væk af ogrerne eller harpyerne, der nu bor der.\n\nDu er velkommen til at kigge dig omkring, men jeg ved ikke, om du finder nogen bøger her, der kan hjælpe dig."},
  [2940] = {n="Vildalas: En Historie", l="Spørg Daryn Lysvind, om du må låne hendes bog.", d="Denne bog ser ud til, at ingen har åbnet den i lang tid. Omslaget er ganske slidt, og siderne er gulnede, men efter at have undersøgt den, bemærker du, at den måske netop er det, Trojas leder efter.\n\nDu tager den op, men indser, at du nok burde spørge, før du låner den.", c="Så du vil gerne låne Vildalas: En Historie?\n\nLad mig tænke...\n\nJeg vil lade dig låne denne bog, <Name>, men kun hvis du gør noget for mig først."},
  [2941] = {n="Låneren", l="Tag brevet til Kurgle Krængelhop i Tanarisørknen.", d="Jeg har studeret mange emner i min tid, og min seneste fascination er med knipsekæberne, der besætter stranden i Bagland. Der er én særlig, jeg gerne vil se, en kæmpe knipsekæbe ved navn Gamlerita. Jeg ville selv gerne derhen, men min forskning holder mig her. Jeg tror, et billede af hende ville være det næstbedste.\n\nTag dette brev til Kurgle Krængelhop i Tanarisørknen. Hun har skabt en opfindelse til mig, der kan fange et billede. Hun kaldte den et „øjebliksbillede“, tror jeg...", p="Et brev - til mig?", c="Er du en af Daryns praktikanter? Hun er en yderst vidende historiker, <Name>. Du bør være taknemmelig for at studere under hendes ledelse.\n\nNu, lad mig hente Super Knipser Effekten. Du kommer til at elske den!"},
  [2942] = {n="Morgenstenen", l="Returnér den glitrende sten og Equinex-staven til Trojas Månebris i Fjermåne-fæstningen.", d="Øjeblikket artefakten blev fjernet fra monolitten, mærkede du, hvordan energien i Equinex-staven begyndte at aftage.", p="Jeg er glad for, at du er vendt tilbage, <Name>. Jeg er ivrig efter at høre om dine fund.", c="Jeg har læst, siden du gik, <Name>. Denne sten, du har fundet, kaldes Morgenstenen. Selvom jeg ikke helt er sikker på, hvad dens formål er endnu, kan du være sikker på, at den er noget af stor betydning, at den var gemt væk inde i Equinex-monolitten på den måde.\n\nJeg vil fortsætte mine studier, og jeg håber, at jeg kan regne med dig i fremtiden, <Name>. Tak for al din hjælp."},
  [2943] = {n="Tilbage til Trojas", l="Aflever bogen til Trojas Månebris i Fjermåne-fæstningen.", d="Her er den, <Name>. Vær sød at passe godt på min bog.\n\nNu, skynd dig afsted. Jeg er sikker på, at Trojas er ivrig efter at se dig igen.", p="Hej, <Name>. Har du været i Darnassos?", c="Du har bragt en bog med dig. Fremragende!"},
  [2944] = {n="Super Knipser Effekten", l="Brug Super Knipser Effekten til at tage et øjebliksbillede af Gamlerita, og vend derefter tilbage til Daryn Lysvind i Rutteran-landsbyen.", d="Få det første kig på min nye opfindelse, <Name>. Alt, du skal gøre, er at sigte mod det, du gerne vil tage et billede af, og trykke på knappen.\n\nHvad var det for et væsen fra Bagland, du nævnte? Gamlerita? Nå, held og lykke med at finde hende. Jeg er sikker på, at Daryn bliver ganske glad for det øjebliksbillede, du bringer hende tilbage.\n\nUnder alle omstændigheder, her er Super Knipseren. Hav det sjovt!", p="Så er du endelig kommet tilbage, <Name>. Og du har bragt den konstruktion, Kurgle byggede til mig - perfekt.", c="Nå! Kurgles opfindelse levede op til forventningerne.\n\nBliv ikke for begejstret, men vid, at jeg er tilfreds med dit arbejde, <Name>.\n\nNu, hvor lagde jeg lige den bog..."},
  [2946] = {n="Vi ser, hvad der sker", l="Bring de miniature platinskiver til portene til Ulddal i Tanarisørknen, og led efter spor om forbindelsen mellem de to.", d="Vi vil have dig til at tage de miniature skiver, du fandt, til de forseglede porte til Ulddal. Vi... vi er ikke sikre på, hvad der vil ske, når du gør dette.\n\nDet lyder jo risikabelt, det anerkender vi. Det kan dog også slet ikke gøre noget. Du skal måske bruge skiverne på noget. Måske låses dørene op, når du har skiverne i din besiddelse. Vær åben over for at prøve alt, og vær parat til, at alt kan ske.\n\nNår du har fundet ud af, hvad der sker, skal du vende tilbage til Jernsmede. Vi får meget at analysere, når du er færdig!", p="Dette bekendt udseende fodstykke stikker op af den varme sand. Måske er der noget ved dens tilstedeværelse her...", c="Da du rørte ved soklen, begyndte de miniature skiver fra Ulddaman at summe og gløde i din rygsæk. En velkendt, prikkende fornemmelse skyllede over dine hænder, da billedet af en anden Stenvogter sprang til live foran portene til Ulddal.\n\n„Hilsen. Jeg er en indgangsvogter. Skiverne, der har været brugt til adgang, mangler de korrekte indgangsskiver, Ulddal-pladerne. Venligst integrér disse plader med skiveststrukturen og gentag din adgangssekvens. Tak.“"},
  [2947] = {n="Ringens Retur", l="Du kan enten beholde ringen, eller du kan finde personen bag aftrykket og graveringerne på indersiden af ringbæltet.", d="Da du åbnede kassen fra Gnistrematic 5200, viste der sig det, du havde mistænkt - en skinnende ring! Når du tager ringen på, føler du magisk kraft strømme gennem din krop.\n\nInde i ringbæltet er et lille, men alligevel tydeligt aftryk af Jernsmedes segl. Ved siden af er tre små initialer indgraveret: \"TdK\". Det kan betyde enten den tidligere ejers initialer, eller måske ringsmedens initialer. Behold ringen... eller returner den til denne person. Beslutninger, beslutninger...", p="Hey, rolig nu, makker - jeg er en meget vigtig forretningsmand! Jeg er sikker på, at budet bare er forsinket med huslejen... vent... du er ikke min udlejer.\n\nNej, selvfølgelig er du ikke - hvor er jeg dum! Du er kommet for at søge den fineste juveler i hele Jernsmede, en der IKKE laver FORBANDEDE genstande! Ja!\n\nØh... hvad har du brug for?", c="En ring, siger du? Lad mig se... jo, den ring har jeg lavet, ved gud.\n\nFør Nisseborgen gik under, havde jeg en lille butik deroppe. Måske er det en, jeg efterlod, da jeg løb for bjergene; det er et simpelt design, og jeg lavede flere lignende. Måske stammer den fra en, der ikke kom ud i tide.\n\nMørkjernsdværgene havde den her? Nå, det lægger et nyt lag af sammensværgelse oven på de ni forskellige lag, der allerede svæver rundt. Måske ville myndighederne gerne vide det; det er spildt på folk som mig.\n\nNu, tilbage til ringen..."},
  [2949] = {n="Ringens Retur", l="Du kan enten beholde ringen, eller du kan finde personen bag aftrykket og graveringerne på indersiden af ringbæltet.", d="Da du åbnede kassen fra Gnistrematic 5200, afslørede den en skinnende ring! Når du tager ringen på, føler du magisk kraft strømme gennem din krop.\n\nInde i ringbæltet er et lille, men alligevel tydeligt aftryk af Orgrimgrads segl. Der er gravéret bogstaver ved siden af, men kun de første tre træder frem, selv efter rengøring: \"NOG...\"\n\nDet kan betyde enten den tidligere ejers initialer, eller måske ringsmedens initialer. Behold ringen... eller find \"NOG\" - beslutninger, beslutninger...", p="Man skulle tro, at vi selv kunne finde en måde at overgå de beskidte små gnomer på. Jeg ville endda vædde på, at de stjal det rigg fra os i første omgang! Bah, de fedtede, snavsede... øh, ja? Har du brug for noget?", c="En ring fra Nisseborgen? Lad mig se... ikke min, men interessant.\n\nNisseborg-sagen - de kunne ikke have fortjent det mere, den flok kvababbere. I årevis har de været en spøg, og nu laver de pludselig bedre rigge end os, næsten fra den ene dag til den anden?\n\nMørkjernsdværgene havde ringen? Det er endnu mere interessant! Du ved, måske stjal gnomerne deres skøre golem-planer og ændrede dem. De Mørkjern-dværge vil helt sikkert have en ordentlig hævn. Det er bestemt værd at undersøge.\n\nJa, og så er der den ring..."},
  [2951] = {n="Gnistrematic 5200!", l="Indsæt en skidt-indkrystalliseret genstand i Gnistrematic 5200, og sørg for at have tre sølvmønter til at starte maskinen.", d="Denne opfindelse skiller sig ud blandt gnomerne, der holder stand mod galskaben udenfor rummet. En lille plade på apparatet lyder \"Gnistrematic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester der ødelægger dine glimmerting? Gnistrematic 5200 sætter glimten tilbage i det glimtende - skinnende skinnetastisk! Indsæt den genstand, du vil rense, og læg tre sølvmønter i møntriften. Giv Gnistrematic 5200 et øjeblik til at arbejde, og voilà! Dine værdigenstande kommer frem rene og skinnende!\"", p="Det ser ud til, at apparatet har brug for et skidt-indkrystalliseret objekt at rense og tre sølvmønter for at få den sære maskine i gang. Så længe begge dele er til stede, burde Gnistrematic 5200 virke...", c="Du indsætter den skidt-indkrystalliserede genstand og tre sølvmønter i Gnistrematic 5200. Maskinen kommer til live i et rasende forsøg på at rense skidtet af den ukendte genstand. Høje, voldsomme knasende lyde bulrer fra maskinens hjerte. Apparatets metalramme knirker og stønner, mens den vipper fra side til side..."},
  [2952] = {n="Gnistrematic 5200!", c="Lige så hurtigt som den startede, stopper Gnistrematic 5200 brat op. Maskinen giver en simpel \"klink\" fra sig, og maskinens mund snor sig opad. Inde i Gnistrematic 5200 ligger en lille æske pakket ind med en lille sløjfe. Maskinen ser ud til at pakke en genstand ind, efter den har fjernet dens skidt-indkrystalliserede tilstand. Selvom maskinen ikke virkede, er genstanden i det mindste nu pakket ind i en pæn æske.\n\nNå, der er kun én måde at finde ud af, om den har renset genstanden eller ej..."},
  [2954] = {n="Stenvogteren", l="Lær formålet med Norgannøns Stenvogter, og interager derefter med Ulddal-soklen i Tanarisørkenen.", d="\"Hilsener - jeg er en portvogter. Medmindre du allerede har integreret Ulddal-pladerne i dit diskssæt, tillader jeg ikke adgang til Ulddal-komplekset.\"\n\nDen Norgannøn-stenvogter, der nu står foran dig, må være den reaktion, man håbede på, da du blev sendt ud i Tanarisørkenen med platindiskene. Som instrueret skal du finde ud af, hvad historien bag Stenvogteren er, før du fortsætter.", p="Stenvogterens formål må forstås, før du fortsætter...", c="Stenvogterens stemme genlyder med kraft og autoritet:\n\n\"Dine skiver vil blive returneret til dig, når du har adgang til soklen. Når du har fået Ulddal-pladerne og integreret dem i dit eksisterende diskssæt, kan du træde ind i komplekset.\""},
  [2963] = {n="Varsler fra Ulddal", l="Tal med Historiker Karnik i Opdagelsesrejsendes Hal i Jernsmede.", d="Hilsen igen, <Name>! Din opdagelse inde i Ulddaman har sat Opdagelsesrejsende-Ligaen i en voldsom opstandelse af begejstring. Ligaen har arbejdet på at låse hemmelighederne op bag de miniature platinskiver, du fandt. Din heldige ankomst her i Hallen lader mig dele med dig, at vi muligvis er på sporet af noget!\n\nHistoriker Karnik har afdækket nogle vigtige spor om de sande oprindelser af Vogternes Dal i Tanarisørkenen. Han vil gerne tale med dig så hurtigt som muligt!", c="Jeg er glad for, at du bevarer din interesse for udforskning, <Name>! Med dit naturlige talent og mod kunne vi knække hemmeligheder, vi aldrig troede var mulige!\n\nNorgannøns skiver i Ulddaman var et lager af enorme mængder information; du fik kun lov til at tilgå de øverste lag af den information, der var lagret der. Skaberne rygtedes at have flere lagre spredt rundt omkring i Azerot. Det bringer os nu til Ulddal..."},
  [2964] = {n="En Fremtidig Opgave", l="Tal med Overopdagelsesrejsende Magelas i Jernsmede.", d="Nå <Name>... vi ser ud til at være havnet i en midlertidig blindgyde her. Vi ved, hvad vi har brug for - Ulddal-pladerne - men vi har ingen anelse om, hvor de kan være. Vi bliver nødt til at forske en hel del i dette for at komme frem til en solid angrebsplan. Jeg har et par ideer om, hvor vi kan begynde at lede; jeg håber inderligt, at vi snart beder dig om at tage ud og hente dem.\n\nOveropdagelsesrejsenden skal orienteres om dette, <Name>; uden tvivl vil han også takke dig personligt for endnu en gang at have hjulpet Ligaen.", c="Så er vi alle enige - den bedste plan er at sætte det på pause, indtil vi kan indsnævre de områder, hvor pladerne måske ligger skjult. Du har bragt os så langt, <Name>, og jeg håber, at du bliver den, der vender tilbage i marken for at låse Ulddal op for os alle!\n\nLad mig i mellemtiden give dig denne æresgave; den bør dække eventuelle udgifter, du har haft i forbindelse med at hjælpe os, og så lidt ekstra. Husk at tjekke ind hos os snart... Ulddal kalder!"},
  [2965] = {n="Varsler fra Ulddal", l="Tal med Nara Vildmane på Ældrehøjen i Torden Skrænt.", d="Ah, <Name>, det er heldigt, at du er kommet til mig igen. Dine åbenbaringer ved udgravningen i Ulddaman har bestemt givet os vismænd meget at diskutere. Det var netop det, jeg gjorde med en af druiderne, Nara Vildmane, da det gik op for mig, at hendes tidligere eventyrerfaringer muligvis har stor betydning for det næste skridt, vi skal tage.\n\nJeg vil gerne have, at du taler med hende om hendes rejser til Vogternes Dal i Tanarisørkenen. Hun venter på dig på Ældrehøjen.", c="Der er et sted dybt inde i Tanarisørkenen, kaldet Vogternes Dal. Skiverne, du fandt... deres oversatte glyffer nævner et sted ved navn Ulddal. De fleste mener, at stedet er en myte.\n\nJeg ved, at det er falsk; Ulddal eksisterer. Jeg har været der. Nå... udenfor, i hvert fald.\n\nKernen er denne, <Name>: vi tror, at der er en forbindelse mellem skiverne og Ulddal, og vi vil have dig til at tage derhen."},
  [2966] = {n="Se Hvad Der Sker", l="Bring de miniature platinskiver til portene til Ulddal i Tanarisørkenen og led efter spor om forbindelsen mellem de to.", d="Vismand Sandhedssøger og jeg vil gerne have, at du tager de miniature skiver, du fandt, til de forseglede porte til Ulddal. Vi... vi er ikke sikre på, hvad der sker, når du gør det.\n\nDet lyder ganske vist farligt, det erkender vi. Men det kan også være, at det ikke gør noget. Måske skal du bruge skiverne på noget. Måske låser dørene op, når du har skiverne i din besiddelse. Vær åben over for at prøve alt, og vær klar på, at hvad som helst kan ske.\n\nLær, hvad du kan, og kom så tilbage til mig. Vi har meget at drøfte.", p="Denne velkendte sokkel rager op af den varme sand. Måske er der noget på spil med dens tilstedeværelse her...", c="Idet du rører soklen, summer og gløder de miniature skiver fra Ulddaman i din rygsæk. En velkendt, prikkende fornemmelse skyller over dine hænder, mens billedet af endnu en Stenvogter springer til live foran portene til Ulddal.\n\n\"Hilsener. Jeg er en portvogter. Skiverne, der er blevet brugt til adgang, mangler de korrekte indgangsskiver, Ulddal-pladerne. Integrer venligst disse plader i skivestrukturen, og gentag din adgangssekvens. Tak.\""},
  [2967] = {n="Retur til Torden Skrænt", l="Tal med Nara Vildmane i Torden Skrænt.", d="Du tilgår soklen igen; platinskiverne dukker pludselig op i din rygsæk igen.\n\nMed kendskabet til stenvogteren lært og skiverne returneret til din besiddelse, er tiden kommet til at vende tilbage til Torden Skrænt og fortælle Nara Vildmane om din opdagelse.", p="Velkommen tilbage <Name>. Var du i stand til at bruge skiverne til din fordel, eller var det forgæves?", c="Manglede du nogle skiver? Interessant nok viser det sig, at Norgannøns skiver kun er dele af det komplette sæt - ligesom nøgler på en nøglering, om man vil.\n\nHvis vi kan finde Ulddal-pladerne, kunne vi faktisk få adgang til selve Ulddal-komplekset. Jeg ved ikke, om jeg skal være spændt på den udsigt eller være skrækslagen.\n\nVi må måske risikere alt for at sikre, at de hemmeligheder, jorden gemmer, som ville tilintetgøre os alle, forbliver netop det - hemmeligheder."},
  [2968] = {n="En Fremtidig Opgave", l="Tal med Vismand Sandhedssøger i Torden Skrænt.", d="Nå <Name>... vi ser ud til at være havnet i en uheldig blindgyde. Vi ved, hvad vi har brug for - Ulddal-pladerne - men vi har ingen anelse om, hvor de kan være. Vi vil undersøge dette og derefter udtænke en solid angrebsplan. Jeg har et par ideer om, hvor vi kan begynde at lede; jeg håber inderligt, at vi snart beder dig om at slutte dig til vores bestræbelser på at finde sandheden.\n\nVismand Sandhedssøger skal orienteres om dette, <Name>; uden tvivl ønsker han også at takke dig personligt for endnu en gang at have hørt kaldet.", c="Så er vi alle enige - den bedste fremgangsmåde er at vente, indtil vi kan indsnævre de områder, hvor disse plader måske ligger skjult. Du har bragt os så langt, <Name>, og jeg håber, at du bliver den, der vender tilbage i marken for at konfrontere Ulddals hemmeligheder.\n\nLad mig i mellemtiden give dig denne æresgave; den bør dække eventuelle udgifter, du har haft i forbindelse med at hjælpe os, og så lidt ekstra. Husk at tjekke ind hos os snart... Ulddal kalder os alle, unge."},
  [2969] = {n="Frihed for Alle Væsener", l="Brug Bambusbur-nøglen til at befri Sprite-pileskytterne fra folden i Grumtotem-lejren. Mindst 6 Sprite-pileskytter og Kindål Månevæver skal overleve.\n\nDu har 6 minutter, før Kindål beslutter, at det er tid til at trække sig tilbage, og du fejler opgaven.", d="De snavsede Grumtotem-klan fanger feendragerne, <Name>. Jer'kaj og jeg har ingen anelse om, hvad de har planer om med dem, men de er åbenbart oppe på noget ondt.\n\nVi er ikke mægtige nok til at kæmpe os ind i lejren og befri de fangede drager, men måske med din hjælp...\n\nHvis du er villig, og du har nogle stærke venner, så slip væsnerne ud af deres bur med denne nøgle, og sørg for, at de slipper væk med livet i behold. Jeg vil være ved din side hele tiden. Jer'kaj vil forblive her.", p="Vi kan ikke tillade Grumtotem-klanen at ødelægge disse smukke væsener. De skal befries fra fangenskabet!", c="Tak, Elunie, <Name>! Du er en stor velsignelse for os og for sprite-pileskytterne, du reddede. Jer'kaj og jeg ville aldrig have været i stand til at hjælpe dragerne selv - din indblanding i Grumtotemernes anliggender vil blive husket.\n\nTal med Jer'kaj nu... Jeg må forberede vores gengældelse. Bare fordi feendragerne er fri, betyder det ikke, at de vil forblive det. Jer'kaj og jeg vil nu gå til offensiven."},
  [2970] = {n="Uddeling af Retfærd", l="Dræb 12 Grumtotem-naturforskere, 10 Grumtotem-raidere og 6 Grumtotem-shamaner, før du vender tilbage til Jer'kaj Månevæver i Vildalas.", d="Som hun allerede har fortalt dig, vil Kindål og jeg nu tage kampen op mod Grumtotemerne. Sammen burde vi stadig kunne plukke nogle af taurerne af uden for meget fare for os selv, men vi ville elske lidt hjælp, hvis du er villig og i stand til det.\n\nDu har set lejren nedenfor os, men der er flere mod øst. Brug dine egne taktikker, og påfør taurerne så meget skade, du kan. Vi kan alle mødes her igen, når de har mærket Kindåls pile og dine egne våben.", p="Kindål har brug for tid til at forberede sig, men vores drab tæller allerede i dusinvis. Grumtotem-klanen er mere end bevidst om vores tilstedeværelse i området, og de søger os frem som hugorme.\n\nDe vil gøre alt i deres magt for at tage vores hoveder fra vores kroppe. Du bør være på vagt... de kommer også efter dig nu, hvor du har blandet dig.", c="Kindål havde ret om dig, <Name> - du har virkelig et talent for dette. Du er en mere erfaren eventyrer end os begge to, og for det takker vi dig.\n\nGrumtotem-klanen er langt mere fjendtlig end de fleste taurer... Jeg undrer mig over, om deres egne artsfæller ser skævt til deres handlinger. Det ville ikke overraske mig. Som du sikkert er klar over, har mange racer på Azerot bånd til mindre venlige modparter.\n\nMen det er en diskussion til en anden dag."},
  [2972] = {n="Uddeling af Retfærd", l="Tag Jer'kajs signetring til Højpræstinde Tyrande Hviskevind i Darnassos.", d="Herude i vildmarken har Kindål og jeg kun beskedne midler til at belønne din hjælp, men vi vil ikke have, at du føler dig uværdsat. Tag min signetring. Hvis du nogensinde befinder dig i Teldrasils grene, så gå til Månetemplet i hjertet af Darnassos. Der vil du finde min højpræstinde, Tyrande Hviskevind. Ringen vil lade hende vide, at vi har det godt, og give din historie troværdighed.\n\nVi takker dig begge, <Name>.", p="Hej, barn. Det glæder os at have flere mægtige eventyrere her i templet. Hvis du har tid, vil du så dele en historie eller to med de yngre eventyrere? Jeg ved, at mange af dem ville have gavn af din visdom.\n\nJeg beklager, se hvor uhøflig jeg er. Du er kommet til templet for at søge vores hjælp, og jeg pålægger dig besvær. Undskyld mig. Fortæl mig, hvad Lysets tjenere kan gøre for dig.", c="Det er en fantastisk historie, <Name>. Det glæder os, at du ikke kun har hjulpet dragefolket, men også en af vores egne præstinder. Jer'kaj havde ret i at sende dig til mig. Jeg vil sørge for, at hun får sin ring tilbage - jeg har spejdere på vej mod Vildalas snart. Dette bliver én ting mere, de kan undersøge under deres mission.\n\nTak igen, og værsgo, gør dig hjemme, mens du er her."},
  [2973] = {n="Glansen på en Ny Kappe", l="Bring 10 Irisserende Sprite-pileskyttevinger til Krueg Kraniespalter i Lejr Mojasje.", d="Velkommen, <Class>. Jeg er rejst med mine ledsagere ned til Vildalas på et hverv for vores herrer i Orgrimgrad.\n\nMin livsledsager Korrin finder stor glæde i nyt tøj, så jeg har tænkt mig at lave hende en ny kappe pyntet med feendragernes tynde vinger. Kunne du hjælpe mig? Sprite-pileskytter med de smukke vinger, jeg vil have, findes vest for Lejr Mojasje.", p="Sprite-pileskytterne kan være farlige små skabninger, når de bliver provokeret. Vær forsigtig, når du har med dem at gøre, <Class>. Og vær endnu mere forsigtig med nattenisserne i området. De irriterende tosser har en tendens til at holde til i skovene også.\n\nNår du har fået nok vinger, så lad mig vide det, så skal jeg nok belønne dig godt!", c="Vidunderligt, <Class>! Disse duer fint. Der er nok her til at lave en kappe til Korrin, og måske endda mere! Tak.\n\nHåber rejsen ikke var for farlig? Vildalas er ikke kendt for at være tilgivende, men du har tydeligvis klaret dig godt nok.\n\nTak igen, <Class>."},
  [2974] = {n="En Dyster Opdagelse", l="Bring 20 Grumtotem-horn til Krueg Kraniespalter i Lejr Mojasje.", d="Hvad!? Du mødte taurer i området? Du tager pis på mig! Hvordan så de ud!?\n\nGrumtotem-klanen! Du fandt nogle af dem? Belgrom, en af vores herrer, har en interesse i deres slags... han har endda sat en dusør på dem.\n\nDu må tilbage, <Class>. Gå tilbage og bring mig deres horn... bunker af dem, hvis du kan. Grumtotemerne skal ikke tages let på eller undervurderes. Gå tilbage og slå dem ihjel; lad floderne i Vildalas flyde røde af deres mørke blod.", p="Tag mine ord alvorligt, <Class>, Grumtotem-klanen er ond. Hvis du har fundet deres opholdssted, så er det op til dig at vende tilbage og slå det første slag mod deres klan... før de kan komme ind i vores egne lande og jævne vores landsbyer med jorden, eller plyndre vores land.", c="Det er gode horn, <Class>. Godt gjort. Jeg tager dem fra dig og sørger for at fortælle Belgrom, så snart vi er tilbage i Orgrimgrad. Du har hjulpet mig to gange nu, og for det har du mit mærke. Måske kan jeg hjælpe dig i fremtiden! Held og lykke til dig."},
  [2975] = {n="Ogerne fra Vildalas", l="Rok Orhan i Lejr Mojasje ønsker, at du dræber 10 Gordønni-oger, 10 Gordønni-oger-magikere og 5 Gordønni-brutale.", d="Gordønni-ogerstammens virkninger kan næppe gå ubemærket hen i dette område. Se dig omkring, <Name>; deres blotte tilstedeværelse sårer dette land. Vi må skubbe dem tilbage, før de udvider sig endnu længere ind i Vildalas.\n\nFølg floden mod nord, så finder du deres forpost. Mindsk deres antal, <Name>. Vi må vise dem, at deres slags ikke er ønsket her.", p="Bevæg dig hurtigt, <Name>. Eller er opgaven, jeg bad dig om, for svær?", c="Fortræffeligt, <Name>. Med tiden vil landet hele. Vi må ikke give op."},
  [2976] = {n="En Dyster Opdagelse", l="Bring kassen med Grumtotem-horn til Belgrom Klippeknokler i Orgrimgrad.", d="Hvad?!\n\nÅh, så jeg nævnte en dusør, gjorde jeg? Nå, det må lære mig at åbne munden, ikke sandt?\n\nDu har gjort arbejdet, så jeg må vel sige, at det er rigtigt, at du høster den største belønning af det. Tag hornene, jeg får dem lagt i en kasse til dig. Find Belgrom Klippeknokler i Æresdalen; han vil gerne vide, hvad du så, og han vil belønne dig for dit hårde arbejde.\n\nVær sød, <Class>, og tak igen for alt, hvad du har gjort.", p="Vær hurtig, <Class>, jeg har meget at få gjort i dag.", c="Grumtotemerne!? Det er interessant. Siger du, at du stødte på dem, mens du jagtede i Vildalas? Virkelig?\n\nMine jævnaldrende vil gerne høre dine nyheder, <Class>. Fortæl mig mere, så tæller jeg din mønt, mens du gør det.\n\nOg inden du går, så ved, at jeg takker dig for de oplysninger, du har givet mig i dag."},
  [2977] = {n="Retur til Jernsmede", l="Tal med Historiker Karnik i Jernsmede.", d="Du tilgår soklen igen; platinskiverne dukker pludselig op i din rygsæk igen.\n\nMed kendskabet til stenvogteren lært og skiverne returneret til din besiddelse, er tiden kommet til at vende tilbage til Jernsmede og fortælle Opdagelsesrejsende-Ligaen om din opdagelse.", p="Velkommen tilbage <Name>. Var du i stand til at bruge skiverne til din fordel, eller endte det med at være en vild gåsejagt?", c="Manglede du nogle skiver? Interessant nok viser det sig, at Norgannøns skiver kun er dele af det komplette sæt - ligesom nøgler på en nøglering, om man vil.\n\nHvis vi kan finde Ulddal-pladerne, kunne vi faktisk få adgang til selve Ulddal-komplekset! Forestil dig at udforske stedet, hvor Skaberne arbejdede, uden at skulle medbringe en kæmpe skovl!\n\nIkke at der er noget galt med skovle... eller med at grave..."},
  [2978] = {n="Gordønni-rullen", l="Bring Gordønni-rullen til Rok Orhan i Lejr Mojasje.", d="Da du samlede den snavsede rulle op, bemærkede du, at den ser ud til at skildre en slags møde eller ceremoni. Rok Orhan ville være interesseret i denne rulle og i, hvad den kan betyde for Gordønnierne.", p="Hvad er dette?", c="Denne rulle... Fandt du den i Gordønni-forposten?"},
  [2979] = {n="Mørk Ceremoni", l="Rok Orhan i Lejr Mojasje vil have dig til at finde en Gordønni-kugle.", d="Det ser ud til at være planer for en slags mørk ceremoni, <Name>. Så vidt jeg kan se, udføres dette ritual af Gordønnis magiker-herrer.\n\nFind en af disse magiker-herrer, og hent en kugle fra ham.\n\nEn magikers kugle indeholder stor kraft, og den vil hjælpe os med at finde ud af mere om denne ceremoni og den magi, Gordønnierne behersker.", p="Vi må finde ud af mere om, hvorfor Gordønnierne er her, <Name>.", c="Denne kugle vil give os mere information om Gordønnierne... som vi derefter vil bruge til at planlægge deres undergang, <Name>."},
  [2980] = {n="Ogerne fra Vildalas", l="Rok Orhan i Lejr Mojasje vil have dig til at dræbe 10 Gordønni-shamaner, 10 Gordønni-hekseklækkere og 5 Gordønni-lemlæstere.", d="Nu hvor du har bevist, at du er en sand kæmper, stoler jeg på, at du har modet til at fortsætte med den opgave, der ligger foran dig.\n\nRejs til Højvildmarken, sydvest herfra. Der ligger nogle forladte og ødelagte bygninger, på land der engang tilhørte nattenisserne. Led efter disse ruiner, og når du ser de visne træer og den vanhelligede jord, vil du finde Gordønnierne. Skub dem tilbage.\n\nDisse oger er meget stærkere end dem, du mødte tidligere, <Name>. Vær opmærksom.", p="Har du fundet ruinerne, <Name>?", c="Du har bevist dig selv som en pålidelig og troværdig allieret, <Name>."},
  [2981] = {n="En Trussel i Vildalas", l="Belgrom Klippeknokler vil have dig til at tale med Rok Orhan i Lejr Mojasje.", d="Vildalas er et ideelt sted for en erfaren <Class> til at bevise sig selv. En stamme af oger ved navn Gordønnierne er den dominerende militære magt der, og deres antal vokser. De må stoppes, før de truer vores tilstedeværelse i Vildalas.\n\nEn kriger, jeg kender, ved navn Rok Orhan, holder til i Lejr Mojasje i Vildalas; gå til hende. Hun vil fortælle dig mere om situationen, når du kommer frem.", c="Så Belgrom sendte dig. Du kommer lige til tiden, <Race>.\n\nLad mig forklare situationen, så kan du selv beslutte, om du er klar til udfordringen... Men hvis Belgrom sendte dig, er jeg sikker på, at dit mod er uomtvisteligt."},
  [2982] = {n="Højvildmarken", l="Angelas Månebris vil have dig til at dræbe 8 Gordønni-hekseklækkere, 8 Gordønni-shamaner og 8 Gordønni-brutale.", d="Selvom det er farligt, har Troyas og jeg undersøgt ruinerne, der dækker Vildalas' skove.\n\nDog har Troyas for nylig begyndt at gå alene til Højvildmarken, og jeg er virkelig bekymret for ham. Gordønni-ogerne har overtaget det område, og de tager ikke venligt imod nogen, der træder ind på deres territorium.\n\nJeg håbede, at du måske ville være villig til at rejse til ruinerne mod sydøst og rydde nogle af ogerne ud. Gør det lidt mere sikkert for min Troyas, så vil jeg være ekstremt taknemmelig.", p="Vær på vagt over for Gordønnierne, <Name>. Deres magi synes at hærge det land, de står på.", c="Jeg er meget taknemmelig for, at du var i stand til at gøre dette for mig.\n\nNu, vær venlig, nævn ikke et ord til Troyas om dette..."},
  [2983] = {n="Ildens Kald", l="Find Kranal Fis i Ødemarken.", d="Det er gået et stykke tid, siden du sidst blev testet, <Name>. Du har været tålmodig indtil nu i dine studier, men det er tid til, at du lærer om større kræfter... det er tid til, at du lærer ægte kraft. Ildens element er dit, hvis du er parat til at betale for det.\n\nSøg Kranal Fis i Ødemarken. Han bor i en lille bolig nord for Korsvejen, men vær opmærksom på, at hvis du har nået de sprængte nattenisse-lande, er du gået alt for langt.", c="Hmmm, Svart sendte dig til mig, gjorde han?\n\nNå, Svart kunne altid stoles på, så det må betyde, at du er klar til at tage del i den næste sapta--ildens sapta.\n\nJeg kan allerede se det i dine øjne, brændingen, begæret. Du har smagt magt, og nu er du klar til mere af den. Tålmodighed, <Name>. Husk, hvad jorden lærte dig. Kraft og ødelæggelse vil komme let, men du skal stadig vide, hvornår du skal holde din hånd tilbage."},
  [2985] = {n="Vandets Kald", l="Find Isleif Vandseer i Ødemarken.", d="Du ser klar ud til din næste prøve, <Name>. Du har været tålmodig i dine studier, men tiden er kommet til, at du skal lære mere. Tiden er kommet til, at du skal lære om vandets renhed.\n\nSøg Isleif Vandseer i Ødemarken. Hun står langs østkysten, syd for Sydfury-floden og Skralleby. Du finder hende der ved sin fiskerhytte. Held og lykke, <Name>.", c="Vinden nærmer sig dig hurtigt fra horisonten; jorden er fast under dine fødder; og din ånd er allerede opvarmet af ild--jeg vil sige, at det er tid for dig at lære om vandets renhed.\n\nDin vej har ført dig hertil, og din ånd vil give dig styrken til at fortsætte endnu længere. Men det første skridt er din at tage."},
  [2986] = {n="Vandets Kald", l="Find Isleif Vandseer i Ødemarken.", d="Det er længe siden, du sidst blev prøvet, <Name>. Du har vist tålmodighed indtil nu i dine studier, men tiden er kommet til, at du skal lære mere. Tiden er kommet til, at du skal lære om vandets renhed.\n\nSøg Isleif Vandseer i Ødemarken. Hun står langs østkysten, syd for Sydfury-floden og Skralleby. Du finder hende der ved sin fiskerhytte. Held og lykke, <Name>.", c="Vinden nærmer sig dig hurtigt fra horisonten; jorden er fast under dine fødder; og din ånd er allerede opvarmet af ild--jeg vil sige, at det er tid for dig at lære om vandets renhed.\n\nDin vej har ført dig hertil, og din ånd vil give dig styrken til at fortsætte endnu længere. Men det første skridt er din at tage."},
  [2987] = {n="Gordønni-kobolt", l="Orwin Snurremik i Lejr Mojasje vil have 12 prøver af Gordønni-kobolt.", d="Jeg er lige ankommet her til Vildalas, og jeg har hørt, at Gordønni-ogrerne, der lever i vildmarken her, har nogle interessante mineraler. Hvem ved, hvad de har gang i, men de er bestemt beskyttende over for det! De lader det ikke ligge rundt; nej, de graver det ned for at beskytte folk som mig mod at komme i nærheden af det.\n\nHvis du vil være sød, giver jeg dig min spade. Gå til Gordønni-forposten nord for her og grav mig noget Gordønni-kobolt op. Led efter det blå skær, og begynd så at grave!", p="Kom så derop og begynd at grave!\n\nJeg har steder at være og folk at besøge -- tid er penge!", c="Perfekt! Jeg tager disse med, mens jeg fortsætter mine rejser, <Name>. Jeg er sikker på, at jeg kan finde en, der betaler en pæn skilling for koboltten.\n\nVær så venlig, tag det her for besværet."},
  [2988] = {n="Visnebark-burene", l="Tjek burene i de to Visnebark-landsbyer, og vend derefter tilbage til Gryfonmester Talonøkse.", d="Den største af vores gryfoners søn er forsvundet! Hurtigvinds arving, Skarpnæb, gik tabt, mens han jagtede sammen med sine forældre for et par dage siden, og vi tror, det var trolde, der tog ham.\n\nDu må hjælpe os! Eftersøg burene i de to Visnebark-trold-landsbyer for at se, om Skarpnæb er der.", p="Har du undersøgt burene, <Name>? Vi må finde Skarpnæb!", c="Skarpnæb var ikke i landsbyerne? Hm... det er dystre nyheder. Den gryfon er bestemt til at lede den næste generation af gryfoner. Hvis han er tabt, vil vores flådes styrke og ånd lide enormt."},
  [2989] = {n="Zul-alteret", l="Tjek toppen af Zul-alteret, og vend derefter tilbage til Gryfonmester Talonøkse.", d="Skarpnæb var ikke hos Visnebark-trolde. Måske tog Ondgrenen-trolde ham. Gå til Zul-alteret på den vestlige kant af Ondgrenen-territoriet og led efter gryfon-barnet.", p="Skynd dig, <Name>! Hvis Ondgrenen-trolde har Skarpnæb, ved man ikke, hvad de kunne finde på at gøre med ham!", c="Skarpnæb var ikke der? Det er dårlige nyheder, men også gode nyheder...\n\nDet er godt, at han ikke var ved Zul-alteret, for Ondgrenen-trolde er kendt for at udføre ofringer.\n\nJeg takker dig for al din hjælp, men jeg er bange for, at jeg har en endnu større opgave foran mig."},
  [2990] = {n="Thadius Grimskygge", l="Bring Skarpnæbs Fjer til Thadius Grimskygge i Det Sønderrevne Land.", d="Tag denne fjer til Thadius Grimskygge, spåmanden. Han forlod Ørnerede-toppen for år siden for at forfølge mørkere viden, men i sit hjerte er han stadig en Vildhammer!\n\nOg måske kan hans talenter hjælpe os med at finde Skarpnæb.\n\nDenne fjer blev taget fra reden, hvor gryfon-barnet sover. Hvis du giver den til Thadius, kan han med held bruge sin spådomsmagi til at finde Skarpnæb.\n\nHeld og lykke, <Name>. Du finder Thadius i Det Sønderrevne Land, i magikertårnet på Underverdensgarden Fæstning.", p="<Name>, du kommer med en gave?", c="Ah, ja. Denne fjer tilhører en fin gryfon. En der er bestemt til store ting... hvis han kan overleve til voksenalderen uskadt.\n\nVil du finde ham? Så lyt godt efter, modige <Class>..."},
  [2991] = {n="Nekrums Medaljon", l="Bring Nekrums Medaljon til Thadius Grimskygge i Det Sønderrevne Land.", d="Jeg finder ud af, hvor din gryfon er, men først skal du gøre noget for mig. Der er en trold i Zul'Stenbrud, Nekrum Tarmtygger, som har et medaljon, jeg meget gerne vil studere. Bring mig det medaljon, så bruger jeg mine kræfter til at finde Skarpnæb.\n\nZul'Stenbrud ligger på den anden side af havet mod vest, i ørkenen Tanaris.", p="Har du Nekrums Medaljon, <Name>? Der er kræfter gemt i det, som jeg er ivrig efter at opdage.", c="Ah, Nekrums medaljon. Det rygtes, at det har givet trolden et unaturligt langt liv, men til en pris. Jeg håber at finde en måde at høste medaljonens kraft på, samtidig med at jeg undgår dens... ubehagelige bivirkninger.\n\nDu har gjort mig en tjeneste, <Name>. Nu vil jeg holde min ende af aftalen."},
  [2992] = {n="Spådommen", l="Vent, til Grimskygge udfører spådomsritualet.", d="Giv mig plads, mens jeg udfører et spådomsritual. Jeg vil finde forbindelsen mellem fjeren, du bragte mig, og dens ejer, og følge den forbindelse til Skarpnæb selv.\n\nDet vil sige... jeg vil, hvis alt går efter planen. Hvis ikke, så... må du hellere lukke øjnene.", c="Ritualet lykkedes. Jeg har set Skarpnæb og kan fortælle dig, hvordan du finder ham."},
  [2993] = {n="Tilbage til Bagland", l="Tal med Gryfonmester Talonøkse.", d="Skarpnæb holdes i et bur, højt oppe på en klippe på toppen af Jintha'Alør i Bagland. Nøglen til buret besidder den høje præstinde for Ondgrenen-trolde, Ond Præstinde Hekse.\n\nDer. Jeg har gjort min del. Jeg ønsker dig held på din færd, <Name>.", c="Har du talt med Grimskygge? Hvad sagde han?\n\n...Hvad? Ondgrenen-trolde har Skarpnæb? Det er ulideligt! Vi må organisere en styrke for at hente ham tilbage!"},
  [2994] = {n="Redningen af Skarpnæb", l="Kæmp dig op til toppen af Jintha'Alør, dræb Ond Præstinde Hekse for nøglen til Skarpnæbs bur, og red Skarpnæb.", d="Vi må redde Skarpnæb!\n\nKæmp dig op til toppen af Jintha'Alør i hjertet af Ondgrenen-territoriet, få nøglen til Skarpnæbs bur fra den onde Præstinde Hekse, og find derefter og red Skarpnæb!", p="Red Skarpnæb!", c="Hurtigvind og Skarpklo vendte tilbage med deres barn for få øjeblikke siden, og de gør sig umage med at forkæle ham som nybagte forældre. At se dem sammen igen er nok til at få selv denne gamle dværg til at blinke en tåre væk...\n\nVi kan ikke betale dig nok tilbage for det, du har gjort, <Name>. Gryfonerne fra Ørnerede-toppen og deres ryttere vil synge dit navn i lang, lang tid."},
  [2995] = {n="Kommunikationslinjer", l="Oran Slangevrid i Underbyen vil have dig til at rejse til Bagland og brænde Højdal-optegnelserne, Højdal-rapporten og Højdal-noterne.", d="Quel'Dånil-hytten er et kommunikationscenter for højalferne i Bagland. Deres ambassadører arbejder på at etablere relationer med andre racer, som de deler deres viden om Visnebark-trolde med, der lever i det sydlige Bagland. Alle dokumenter vedrørende kommunikationen opbevares i hytten.\n\nVi har ikke brug for, at Højdal bygger alliancer med andre, <Name>.\n\nØdelæg Højdal-dokumenterne. Vi må brænde deres kommunikationslinjer... bogstaveligt talt.", p="Det er nøglen at holde Højdal-alferne isoleret. Har du fundet hytten?", c="Perfekt, <Name>. Mens Højdal arbejder på at genvinde deres tabte oplysninger, vil vi kunne lukke linjerne endnu mere af..."},
  [2996] = {n="Søger Strahad", l="Tal med Strahad Farsøn i Skralleby.", d="Jeg har lært dig færdigheder før, men tiden er kommet til, at en anden skal lære dig. Han er i Skralleby, og hans navn er Strahad. Han er menneske, men lad dig ikke narre til at tro, at han er svag. Han er mægtig, selvom han måske er lille. Han kan lære dig om kraftigere fremkaldelser -- jeg føler, du er klar. Gå til ham nu. Han er i Skralleby... over havnebyen ved siden af sit tårn.", c="En travl dag i Skralleby, ikke? Hvor nyder jeg at se en havneby slide. Så meget mysterium, så meget eventyr... så meget uvidenhed.\n\nEr det had, jeg ser i dine øjne, <Name>? Godt, vi skal nok få det brugt godt."},
  [2997] = {n="Guddommelighedens Foliant", l="Tal med Tiza Kampsmed i Jernsmede.", d="Hej, <Name>. Jeg ved, at du har travlt med at hjælpe folket i Dun Frostbakke, men når du har tid, bør du tage op til Jernsmede og tale med en af vores mest respekterede slags: Tiza Kampsmed. Hun er den, de yngre paladiner går til, når det er tid for dem at lære mere om Lyset, og hvad der forventes af dem.\n\nDu finder hende oppe i Mysteriernes Hal. Hvis du aldrig har været der, ligger den i Mystiske Afdeling. Held og lykke, <Name>.", c="Velkommen, <Name>. Jeg håber, Lyset viser dig den sande vej og holder dig sikker fra det onde."},
  [3000] = {n="Guddommelighedens Foliant", l="Tal med Tiza Kampsmed i Jernsmede.", d="Hej, <Name>. Jeg ved, at du har travlt med at hjælpe folket i Azerot, men når du har tid, bør du vende tilbage til Jernsmede og tale med en af de mest respekterede paladiner i dit hjem: Tiza Kampsmed. Hun er den, de yngre dværgiske paladiner går til, når det er tid for dem at lære mere om Lyset, og hvad der forventes af os alle.\n\nDu finder hende oppe i Mysteriernes Hal, som ligger i Mystiske Afdeling.", c="Jeg hilser dig og byder dig velkommen, <Name>."},
  [3001] = {n="Søger Strahad", l="Find Strahad Farsøn i Skralleby.", d="Jeg har lært dig færdigheder før, men tiden er kommet til, at en anden skal lære dig. Han er i Skralleby, og hans navn er Strahad. Han er menneske, men lad dig ikke narre til at tro, at han er svag, og heller ikke at han er din fjende... i hvert fald foreløbig. Han er mægtig og bør respekteres. Han kan lære dig om større fremkaldelser, fremkaldelser jeg føler, du er forberedt på. Gå til ham nu.\n\nDu finder ham i Skralleby... over havnebyen ved siden af tårnet der.", c="En travl dag i Skralleby, ikke? Hvor nyder jeg at se en havneby slide. Så meget mysterium, så meget eventyr... så meget uvidenhed.\n\nEr det had, jeg ser i dine øjne, <Name>? Godt, vi skal nok få det brugt godt."},
  [3002] = {n="Gordønni-kuglen", l="Bring Gordønni-kuglen til Uthel'nej i Mørktorn-hytten i Orgrimmar.", d="Selvom jeg kender min fjende godt, er jeg en kriger, <Name>. Jeg kan ikke begynde at fortælle dig, hvad denne kugle er i stand til.\n\nJeg kender en magiker i Orgrimmar, der vil kunne fortælle os mere om kuglen. Tag den med til ham.", p="Hvad har du bragt mig, <Race>?", c="Fascinerende, <Name>...\n\nDenne kugle er meget kraftfuld, men også meget farlig."},
  [3022] = {n="Håndter med omhu", l="Bring den forsigtigt pakkede kasse til Erelas Ravhimmel i Rutteran-landsbyen.", d="<Name>, jeg kan se, at du længes efter at hellige dig min værdige sag. Ja, selvfølgelig kan du gøre noget for mig!\n\nTag denne kasse med æg til Erelas Ravhimmel. Han er en druide, der passer på disse æg, hjælper dem med at klække og derefter træner de unge hippogryffer. Du finder ham på Teldrasil, i en lille landsby mod syd kaldet Rutteran.", p="Endnu en forsendelse fra Kurgle, antager jeg?", c="Tak for din hjælp, <Name>. Hippogryf-bestanden ville simpelthen ikke trives, hvis det ikke var for os. Men jeg er sikker på, at du forstår det alt for godt, efter at have rejst til Vildalas selv og set ødelæggelsen forårsaget af Gordønnierne der.\n\nNå, som du kan se, har jeg travlt med arbejdet her, så du må hellere komme videre.\n\nTak igen, <Name>."},
  [3042] = {n="Trolde-hærdning", l="Bring 20 hætteglas med Trolde-hærdning til Trenton Lysehammer i Gadgetzan.", d="De Sandraseri-trolde i Zul'Stenbrud laver et hærdningsmiddel af sandsten, og det kan jeg bruge til at hærde de ting, jeg fremstiller, ja, det kan jeg! Det er højt værdsat af kendere, så hvis du bringer mig en god forsyning af hærdningen, belønner jeg dig rigeligt.\n\nZul'Stenbrud ligger nordvest for Gadgetzan. Held og lykke.", p="Bragte du mig hærdningen, <Name>?", c="Ah, dette er virkelig fin hærdning! Og så meget af den! Jeg vil være i arbejde i flere dage, før jeg bruger det hele!\n\nTak, <Name>. Værsgo, tag dette som betaling."},
  [3062] = {n="Mørkt Hjerte", l="Talo Tornhov i Lejr Mojasje vil have Edana Hadklos mørke hjerte.", d="Edana Hadklo er dronningen af Nordkilde-harpyerne, der bor i ruinerne mod vest. Hun er ren ondskab; jeg har hørt, at hendes hjerte er af krystal. Hun er tom for enhver følelse ud over det had, hun nærer mod alle andre. Du må stå over for Edana og bringe mig hendes mørke hjerte tilbage.\n\nJeg har hørt om et horn, som harpyerne bærer -- blæser man i det ved Hadklo-stenene i den nordlige del af ruinerne, vil det kalde dronningen.\n\nForestil dig hendes overraskelse, når det ikke er hendes slægtninge, der kalder på hende, men hendes død.", p="Det had, Edana sprer over landet, må standses.", c="Nu ved jeg, at Edana virkelig er død. Dette hjerte vil jeg beholde som minde om det, du gjorde her for mig, <Name>. Tak."},
  [3063] = {n="Hævn over Nordkilde", l="Talo Tornhov vil have dig til at dræbe 4 Nordkilde-harpyer, 4 Nordkilde-snigfjer, 4 Nordkilde-vindkaldere og 4 Nordkilde-dræbere.", d="I min tid var jeg en erfaren jæger. Der var ikke et væsen i nærheden, jeg frygtede. Indtil...\n\nJeg var ude i skoven og slibede mit sværd efter et hårdt slag, da jeg blev overfaldet. Harpyer omringede mig, og jeg kunne knap nok slæbe mig selv i sikkerhed.\n\nEndnu nu kan jeg stadig høre deres skrig ekko...\n\nJeg har aldrig været den samme siden. Men hadet koger inde i mig -- jeg må hævne mig, efter alle disse år.\n\nNordkilde-harpyerne findes mod vest herfra. <Name>, hævn mig.", p="Nordkilde-harpyernes vinger er sorte som natten; tag ikke øjnene fra dem, for ellers forsvinder de i mørket.", c="Tak, <Name>. Du har bragt en gammel taurens sind til ro."},
  [3065] = {n="Simpel Tavle", l="Læs den Simple Tavle og tal med Brask i Prøvernes Dal.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nLæs det, når du har tid. Hvis jeg ikke tager fejl, kom det fra våbentræneren Brask. Han vil gerne tale med dig, når du er klar. Du finder ham uden for Hulen, hvor han søger skygge.", p="Endnu en <Race> til at styrke rækkerne. Godt nok for mig.\n\nDu vil nok få svært ved at løfte et godt våben som en økse, men et spyd er lige så godt som noget andet.\n\nVelkommen til Prøvernes Dal.", c="Du vil finde dette sted passende, mens du fortsætter med at træne på <Class>-vis. Hvis du har spørgsmål, så spørg frit alle omkring dig, og når du føler dig klar, så kom tilbage til mig for træning. Jeg har mestret lige så meget som enhver <Class> her i Dalen og kan give den viden videre til dig... for en pris."},
  [3082] = {n="Ætset Tavle", l="Tal med Jen'shæn i Prøvernes Dal.", d="Ah, mens du var væk, kom en tavle til dig, <Name>.\n\nLæs den, når du har tid. Hvis jeg ikke tager fejl, kom den fra jægertræneren Jen'shæn. Hun vil gerne tale med dig, når du er klar.", p="Jen'shæn ser en mægtig jæger foran sig, og da åndene godkender det.\n\nDa vej af da jæger er en af vores ældste livsveje. Horden vendte sig til os, da de bare kæmpede for at overleve på Azerot, og de bad os lære dem, vise dem hemmelighederne bag mange ting. De var stærke allerede: stærke på sjamanernes vis; stærke på krigernes vis. Men jægerens vej var ikke deres vej... dengang.", c="Nu lærer vi dem da ting, og de lærer os andre. Vi bliver ét folk... næsten. Vi har været allierede i lang tid nu. Så husk at hjælpe dem. Og Jen'shæn husker at hjælpe dig.\n\nJen'shæn lærer dig da jægerens veje -- lærer dig godt. Glem aldrig, at jægere bliver respekteret meget i stammen. Du kommer til at spille en stor rolle i fremtiden... glem aldrig dæt.\n\nNår du føler behovet, så kom til Jen'shæn. Hun lærer dig så meget, hun kan, når hun føler, du er klar."},
  [3083] = {n="Krypteret Tavle", l="Læs den Krypterede Tavle og tal med Rvag i Prøvernes Dal.", d="Ah, mens du var væk, kom en tavle til dig, <Name>.\n\nLæs den, når du har tid. Hvis jeg ikke tager fejl, kom den fra snigmordertræneren Rvag. Han vil gerne tale med dig, når du er klar.", p="Velkommen til Prøvernes Dal, <Name>. Du ville ikke være her, hvis du ikke havde fået min tavle, så jeg går direkte til sagen.\n\nJeg er Rvag, og jeg er ansvarlig for at træne snigmordere, tyve og lommetyve her i Dalen. Jeg er den, Hånden vender sig til, hvis du ikke er klar til det, der kommer. Men bare rolig, Hånden vil ikke styre alt, du gør, men det ville være klogt at arbejde sammen med dem, hvis de har brug for dine talenter.", c="Indtil den tid kommer, står du under min vejledning. Jeg vil vise dig tricks, som nogle siger. Når du føler dig klar, så kom til mig, og jeg vil se på at træne dig yderligere. Indtil da, øv dine færdigheder og hold dem barberskarpe. Du ved aldrig, hvornår du får brug for selv den mest ubetydelige evne."},
  [3084] = {n="Runeindgraveret Tavle", l="Tal med Skrikrik i Prøvernes Dal.", d="Ah, mens du var væk, kom en tavle til dig, <Name>.\n\nLæs den, når du har tid. Hvis jeg ikke tager fejl, kom den fra sjamantræneren Skrikrik. Hun vil gerne tale med dig, når du er klar.", p="Ah, velkommen, <Name>. Jeg er glad for, at du er ankommet. Mine dage er blevet lange og endda travle med så mange elever at undervise, men ankomsten af en af din slags giver mig en stor følelse af præstation -- jeg husker dagene, hvor jeg blev undervist af en af dine sjamaner.", c="Som du sikkert ved, giver elementerne os vores kraft. Ild, jord, vand og luft -- disse er vores redskaber.\n\nVores styrke kommer fra vores forfædres ånder. Vi er vores folks ledere. Ligesom Trael er for Horden, skal vi være for de landsbyer og byer, vi besøger. De vil søge vores visdom og beskyttelse. For at være bedre forberedt skal du træne ofte. Når du føler, at du har opnået mere kraft, så kom til mig, så lærer jeg dig, hvad jeg kan."},
  [3086] = {n="Glyfisk Tavle", l="Læs den Glyfiske Tavle og tal med Mai'aa nær indgangen til Hulen i Prøvernes Dal.", d="Ah, mens du var væk, kom en tavle til dig, <Name>.\n\nLæs den, når du har tid. Hvis jeg ikke tager fejl, kom den fra magitræneren Mai'aa. Hun vil gerne tale med dig, når du er klar.", p="Du ser ud til at behage Mai'aa allerede, <Name>. Dæt er godt. Du viser Mai'aa respekt, og Mai'aa giver måske respekt tilbage. Men nok om dæt, du er her for at lære om magi, ikke for at høre Mai'aa snakke.\n\nDer er kun én ting, Mai'aa ikke kan lære dig om magi, <Name>, og dæt er, hvordan man stopper da fordærvelsen.", c="Du er blandt da mest mægtige væsner på planeten, <Name>... der er ingen diskussion om dæt. Og alle ved dæt... ved dæt godt, også!\n\nMen du skal være på vagt! For det er ikke ork, eller alf, eller dværg, du skal være bange for... det er da ting, du ikke kan se. Magi er mægtig. Den får dig til at gøre ting, du måske ikke vil gøre. Den får dig til at tro, du er mægtigere, end du virkelig er. Vær tålmodig. Vær klog.\n\nNår du tror, du er klar til træning, så kom tilbage til Mai'aa. Hun lærer dig, hvad du er klar til at lære, uden problem."},
  [3087] = {n="Ætset Pergament", l="Læs det Ætsede Pergament og tal med Jen'shæn i Prøvernes Dal.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nLæs det når du har tid. Hvis jeg ikke tager fejl, kom det fra jægertræneren Jen'shæn. Hun vil gerne have et ord med dig, når du er klar.", p="Ah, så du kommer endelig. Godt. Jen'shæn venter på dig.\n\nMange tror, det er en let vej, men Jen'shæn siger dig, at det ikke er sandt. At mestre bestierne i Durdotar og videre kræver lige så meget dygtighed som at mestre de arkane kunster eller at tale med vore forfædre.\n\nAt affyre en bue eller riffel er måske ikke lige så farligt for dig som at kaste en besværgelse, men det er bestemt lige så farligt for din fjende.", c="Når vi er færdige med at snakke, bør du tale med resten af borgerne i Dalen. De beder dig om at gøre ting for dem... ting der vil prøve dine evner og lære dig nogle af farerne i dette land.\n\nNår du vokser i erfaring og visdom, får du brug for Jen'shæn til at vise dig bedre teknikker og færdigheder. Kom tilbage til Jen'shæn ofte. Jeg vil lade dig vide, hvad jeg kan lære dig."},
  [3088] = {n="Krypteret Pergament", l="Læs det Krypterede Pergament og tal med Rvag i Prøvernes Dal.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nLæs det når du har tid. Hvis jeg ikke tager fejl, kom det fra snigmordertræneren Rvag. Han vil gerne have et ord med dig, når du er klar.", p="Shhh, ikke så højt. Jeg stoler ikke på Nartøk derovre. Den, der skal gemme sig dybere i en hule end jeg gør, skal ikke tages let på.\n\nJeg regner med, at du ikke havde problemer med at finde rundt?", c="Nu hvor du ved, hvor jeg holder til, skal jeg lade dig vide: Den Knuste Hånd har bedt mig holde øje med dig. De vil have mig til at træne dig og holde dig underrettet om alt, de måtte få brug for. Selvom du ikke er interesseret i at hjælpe dem endnu – hvilket du ville være en tosse at lade være med – vil jeg gøre, hvad jeg kan for at træne dig... for en lille betaling. Kom tilbage til mig når som helst, du mener, du er klar, så ser vi, hvad du er klar til at lære."},
  [3089] = {n="Runeindskrevet Pergament", l="Læs det Runeindskrevne Pergament og tal med Skrigrik i Prøvernes Dal.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nLæs det når du har tid. Hvis jeg ikke tager fejl, kom det fra shamantræneren Skrigrik. Hun vil gerne have et ord med dig, når du er klar.", p="Så, du er ankommet. Jeg begyndte at undre mig over, hvornår du ville vise dig. Jeg sendte pergamentet for et stykke tid siden – jeg var ikke sikker på, om det var kommet frem.\n\nMen nok snak... du er her, fordi du er blevet udvalgt, udvalgt til at lede vores folks åndelige liv.", c="Du vil være den kanal, hvorigennem vore forfædre kommunikerer. Du vil have elementernes kraft til din rådighed. At knuse dine fjender vil være en leg; at hele dine allierede lige så let som at trække vejret. Husk disse ting, når du møder nye udfordringer, og kom tilbage til mig så ofte du vil. Jeg bliver her for at lære dig nye besværgelser og sætte dig på den rette vej, når du er klar."},
  [3090] = {n="Besmittet Pergament", l="Læs det Besmittede Pergament og tal med Nartøk inde i Hulen i Prøvernes Dal.", d="Ah, mens du var væk, kom der et pergament til dig, <Name>.\n\nJeg plejer at undgå at have med hekseemestre at gøre, hvis jeg kan, men jeg synes, du skal læse det når du har tid. Hvis jeg ikke tager fejl, kom det fra din nyudnævnte træner Nartøk. Han vil gerne have et ord med dig, når du er klar.", p="Endelig er du ankommet... og diskret også. Godt.\n\nVores verden er fuld af tosser, <Name>. Selv den mægtige Træl har større fejl, end de fleste kan se. Han vender ryggen til den magt, der skal til for at gøre dette land helt til vores! Vi er ikke de samme mennesker, der blev manipuleret og brugt af væsener fra Nether. Vi er vores eget folk. Vi er stolte... og vi er stærke.", c="Og nu har du også sluttet dig til vores rækker. Misforstå mig ikke, <Name>. Bare fordi du har adgang til en magt, som mange vil misunde dig, betyder det ikke, at du vil blive accepteret let. Træl lukker vores slags ind i Orgrimgrad, fordi vi stadig er hans frænder – han kan ikke vende ryggen til os, for ellers ville vi blive lige så patetiske som de mennesker, der slavebandt ham. Min pointe er: vær forsigtig. Du kan være mægtig, men hvis du er tosset, så er du lige så godt død.\n\nHvis du har brug for træning i besværgelser, så kom tilbage til mig."},
  [3091] = {n="Simpel Seddel", l="Læs den Simple Seddel og tal med Harrut Tordenhorn i Narache-lejren.", d="For et øjeblik siden ledte en budbringer efter dig, <Name>. Jeg tror, hun blev sendt af krigertræneren Harrut. Hvis denne seddel er fra Harrut, ville jeg ikke tøve længe med at læse dens indhold.", p="Ah, endelig er du ankommet, <Class>. Jeg løj ikke i min seddel, <Name>. Vi er også en særlig race, ikke ulig druiderne eller shamanerne i vores stamme. Du er lige så vigtig. Vi er dem, der kaldes til at forsvare vores grænser, jage Kentaurerne og drage i krig.", c="Hver af os spiller en rolle i vores stamme. Hver af os må også gennemgå de samme ritualer. Lad aldrig din stolthed fortælle dig andet.\n\nJeg bliver her for at træne nye krigere, der søger krigens herlighed og følger vores ældste forfædres veje. Når du føler dig klar, så kom tilbage til mig, og jeg vil gøre, hvad jeg kan for at træne dig yderligere. Gå med stammens velsignelse, <Name>."},
  [3092] = {n="Ætset Seddel", l="Læs den Ætsede Seddel og tal med Lanka Fjernskud i Røde Sky-plateauet.", d="For et øjeblik siden ledte en budbringer efter dig, <Name>. Jeg tror, hun blev sendt af jægertræneren Lanka. Hvis denne seddel er fra Lanka, ville jeg ikke tøve længe med at læse dens indhold.", p="Velkommen til Narache-lejren, <Name>. Jeg hører gode ting om dig. Din blodlinje er stærk, og mange af de ældste anser dig allerede for dygtig. Men det vil vi teste.\n\nSletterne i Mulgorr vil være dit hjem i et stykke tid – du bør gøre dit bedste for at lære dem rigtig godt at kende. En dag vil du rejse til fremmede lande for at mestre større færdigheder. Du må være klar.", c="Og det er min opgave at sikre, at du er forberedt, ved at lære dig det grundlæggende i vores erhverv – hvordan du tæmmer dit kæledyr, hvordan du affyrer din riffel og mange andre færdigheder, der vil blive nødvendige.\n\nJægere er en stærk del af vores tradition og historie, <Name>. Du gør klogt i at huske, hvor vigtig du er for stammen. Du vil blive respekteret og æret, hvis du tjener vores folk godt."},
  [3093] = {n="Runeindskreven Seddel", l="Læs den Runeindskrevne Seddel og tal med Meela Daggrysgænger i Narache-lejren.", d="For et øjeblik siden ledte en budbringer efter dig, <Name>. Jeg tror, hun blev sendt af shamantræneren Meela. Hvis denne seddel er fra Meela, ville jeg ikke tøve længe med at læse dens indhold.", p="Så hurtigt som vand falder fra himlen, står du her foran mig. Jeg er glad for din hast. Det betyder, at du forstår både vigtigheden af vores møde og det, at du er her. Jeg er ingen leder, men jeg forstår elementerne, og jeg kan tale til vore folks ånder. Jeg vil lære dig at gøre det samme.", c="Vi vil mødes mange gange i dagene fremover. Hver gang vil du forhåbentlig forlade min selskab lidt stærkere... lidt bedre rustet. Ligesom den Evige Flamme vil din ånd brænde klart og varmt.\n\nGå nu, <Name>. Gå og prøv dig selv. Jeg vil være her for dig, når du har brug for mig."},
  [3094] = {n="Grønne Seddel", l="Læs den Grønne Seddel og tal med Gart Tågeløber i Narache-lejren.", d="For et øjeblik siden ledte en budbringer efter dig, <Name>. Jeg tror, hun blev sendt af druidetræneren Gart. Hvis denne seddel er fra Gart, ville jeg ikke tøve længe med at læse dens indhold.", p="Du er ankommet. Det er godt. Vores forfædres ånder er blevet urolige over hele Mulgorr og videre, men jeg kan ikke sige hvorfor. Det vil for evigt være din pligt at lære at lytte til naturens ånder og handle som deres talsmand. Vær opmærksom på det.", c="Selvom vi deler et fælles bånd, må du ikke forvente megen velkomst fra nattealferne. Deres stolthed begrænser stadig deres syn, men det er ikke vores bekymring. Jordmoderens lære er alt, du behøver at bekymre dig om, og jeg vil lære dig, hvad jeg ved, mens du vokser i visdom.\n\nVend tilbage til mig ofte, <Name>. Du vil opdage, at Jordmoderen giver utrolige evner til dem, der er mest hengivne."},
  [3095] = {n="Simpel Rulle", l="Læs den Simple Rulle og tal med Dannal Stjerne i Dødsklokken.", d="Ah, mens du var ude og håndterede den tankeløse Svøbe, ankom denne rulle til dig. Jeg tror, det er en sag af betydning, for den ser ud til at bære krigertræner Dannals segl. Jeg vil tage mig tid til at læse den, før du drager ud igen.", p="Ah, så du er ankommet. Godt. Jeg hørte, at nogle få andre var i stand til at undslippe \"døden\", og at de var på vej ind i byen. Måske vil den modstandskraft betale sig i fremtiden også.\n\nDu kan takke Silvanas for din frihed... frihed for sind og krop. Selvom du stadig er plaget af pesten og dens virkninger, er du nu fri til at komme og gå, som du finder passende.", c="Jeg vil være her for at træne dig, mens du vokser i erfaring... find mig så ofte du vil. Jeg tager en minimal betaling, men du vil finde alt, hvad jeg kan lære dig, værdifuldt.\n\nGå nu og prøv din dygtighed. Mange flere ting vil blive kendt for dig, når du får erfaring, og nogle af dem kan jeg ikke diskutere med dig her. Bare vid, at Silvanas får brug for krigere med din slags styrke i fremtiden. Du vil blive rygraden i vores frelse. Glem det ikke."},
  [3096] = {n="Krypteret Rulle", l="Læs den Krypterede Rulle og tal med David Trøsen i Dødsklokken.", d="Ah, mens du var ude og håndterede den tankeløse Svøbe, ankom denne rulle til dig. Jeg tror, det er en sag af betydning, for den ser ud til at bære snigmordertræner David Trøsens segl. Jeg vil tage mig tid til at læse den, før du drager ud igen.", p="Så du er kommet frem? Godt, vi får brug for flere snigmordere, efterhånden som tiden går. Skyggesmygerne vil sikkert finde dig, når de synes, tiden er inde, så lad være med at snuble eller gøre noget, du måske vil fortryde. De har brug for talentfulde agenter... ikke lommetyve og tosser.", c="Jeg bruger det meste af min tid her på kroen på at holde øje med nye ansigter og bare følge med i de lovende nye. Hold dig ren, så skal jeg gøre, hvad jeg kan for at lære dig et par ting. Bare kom tilbage til mig, når du vil, så ser vi, om du er klar til en ny færdighed eller to."},
  [3097] = {n="Helliget Rulle", l="Læs den Helligede Rulle og tal med Mørk Gejstlig Dyssten i kirken i Dødsklokken.", d="Ah, mens du var ude og håndterede den tankeløse Svøbe, ankom denne rulle til dig. Jeg tror, det er en sag af betydning, for den ser ud til at bære præsttræner Dysstens segl. Jeg vil tage mig tid til at læse den, før du drager ud igen.", p="Ah, så mellem ild, pest, optøjer og meget værre, kommer endnu en af de \"troende\" til min dør. Lad mig byde dig velkommen, <Class>. Og lad mig forklare et par ting, før du beslutter, at det er tid for dig at søge det, der driver dig fremad: Det Hellige Lys betyder ikke længere noget for dig, dine forfædres ånder er eventyr, og væsener fra Nether vil ikke have dig.\n\nForstår du mig indtil nu?", c="Der er kun én ting, du skal vide: Vi har overlevet på viljestyrke alene. Det er tro på os selv, der adskiller os fra andre, og med vores kræfter vil vi skabe stor forandring i hele Azeroth. De svage vil lene sig op ad dig. De spedalske vil kalde dig Herre. Og de uvidende vil søge vejledning hos dig. Det er min pligt at sikre, at du har de nødvendige værktøjer, så du er klar, når tiden kommer. Når du vokser i erfaring, så søg mig op. Jeg vil lære dig større kræfter, hvis du er klar."},
  [3100] = {n="Simpelt Brev", l="Læs det Simple Brev og tal med Lane Beskære i Nordshire-klosteret.", d="Jeg blev bedt om at henlede din opmærksomhed på dette, så snart du vendte tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med insignierne fra Lane, vores lokale krigertræner. Jeg ville ikke tøve med at læse det, før du går i gang med andre forretninger her i klosteret.", p="Ah, du fik mit brev, <Name>... godt.\n\nDer har været en tilstrømning af krigere i Elvendal på det seneste – hvilket er godt for Stormvind, men dårligt for koboldene og Defias i området.", c="Gør dig klar, lær landets layout at kende, og kom tilbage til mig, når du har brug for træning. Jeg er her, nat og dag.\n\nSølvhåndens Riddere har gjort et godt stykke arbejde med at gøre dette sted nogenlunde sikkert, men når du møder de andre borgere, tror jeg, du vil opdage, at de alle har problemer, de kunne bruge lidt hjælp til – hjælp en <Class> kan give dem. Held og lykke."},
  [3102] = {n="Krypteret Brev", l="Læs det Krypterede Brev og tal med Jorik Kærridan i stalden bag Nordshire-klosteret.", d="Jeg blev bedt om at henlede din opmærksomhed på dette, så snart du vendte tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med Jorik Kærridans insignier, en af vores lokale trænere. Jeg ville ikke tøve med at læse det, før du går i gang med andre forretninger her i klosteret.", p="Du kom herhen i ét stykke, og det ser ikke ud til, at for mange så dig. Godt nok for mig. Jeg kan ikke lide, at der bliver henledt for meget opmærksomhed på mig herude... pænt og stille. Jeg er sikker på, at du kan forstå det.\n\nHar du haft problemer endnu? Jeg er glad for at høre, at det ikke er tilfældet. Det vil ændre sig snart nok.", c="Du vil finde en række grupperinger, der higer efter vores færdigheder, <Name>. Eventyrere, SI:7... ja, selv Defias-broderskabet ville ikke have noget imod en spion eller to inde i Stormvind. Men husk dette: Du er din egen mand. Lad ingen mobbe dig til at gøre noget, du ikke har lyst til! Desuden har vi alle kortene... i hvert fald, det har vi, før spillet er forbi. Forstår du, hvad jeg mener?\n\nUnder alle omstændigheder ville jeg bare præsentere mig selv og lade dig vide, at jeg er her, hvis du har brug for træning. Kom forbi når som helst."},
  [3103] = {n="Helliget Brev", l="Læs det Helligede Brev og tal med Præstinde Anetta i Nordshire-klosteret.", d="Jeg blev bedt om at henlede din opmærksomhed på dette, så snart du vendte tilbage fra kobold-lejrene, <Name>. Det ser ud til at være et brev forseglet med Præstinde Anettas insignier, vores lokale præsttræner. Jeg ville ikke tøve med at læse det, før du går i gang med andre forretninger her i klosteret.", p="Ah, endelig er du kommet. Jeg vidste, du ville finde vej til mig. Det Hellige Lys skinner på dig og den vej, du har valgt. Tiderne er hårde – den Brændende Legion har stadig en tilstedeværelse på Azeroth, hele Kalimdør søger nye måder at forsvare sig selv mod sine egne prøvelser, og det er op til dig at hjælpe så mange, du kan.", c="Når du vokser i erfaring, så kom tilbage til mig, og jeg vil gøre, hvad jeg kan for at give dig min viden. Indtil da, gå med medfølelse i hjertet, og lad visdom være din vejleder. Husk, verden bliver kun et bedre sted, hvis du gør den til det."},
  [3106] = {n="Simpel Rune", l="Læs den Simple Rune og tal med Thran Kormand i Kuldekam-dalen.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du har chancen. Jeg tænker, den kom fra krigertræneren Thran. Kig på den og find ham inde i Ambolmar, når du har chancen.", p="Sprængt, hvor er det koldt i dag, ikke sandt? Det er, som om sneen aldrig forsvinder, <Name>.\n\nDu har nok allerede bemærket det, men der bor gnomer nu i vores by. Det er fordi, de gik og fik sig selv sprængt ud af deres eget hjem. Sig det ikke videre, men jeg kan næppe bebrejde dem – jeg tror, jeg også ville have grebet til sprængstoffer, hvis Jernsmede var plaget af Mørkjernsdværgene eller lignende.", c="Andre ting, du nok også vil se, bare så du er orienteret: dværge, der bruger magi i kamp i stedet for en riffel. Nogle af os er begyndt at dyrke det Hellige Lys ligesom nogle af menneskene, og sidst men ikke mindst troggerne. Du vil lære mere om dem senere, men det, du skal vide nu, er, at jeg er her for at hjælpe dig.\n\nJeg er her for at lære dig, hvordan du bliver en rigtig <Class>. Når som helst du synes, du har brug for mere træning, så kom tilbage til mig, og jeg skal se, hvad jeg kan gøre."},
  [3108] = {n="Ætset Rune", l="Læs den Ætsede Rune og tal med Thorgas Grumsøn i Kuldekam-dalen.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du har chancen. Jeg tænker, den kom fra jægertræneren Thorgas. Kig på den og find ham inde i Ambolmar, når du har chancen.", p="Du kom! Godt at høre! Du behøvede vel heller ikke at spore mig for at finde stedet. Haha!\n\nVores erhverv er ret gennemsyret af tradition, <Name>. At lære landets veje. At lære at spore en bjørn gennem bjergene. Selv bare at overleve på ren snilde kræver en stor mængde mod og snilde. Tror du, du er i stand til det?", c="Én ting, du altid skal huske, er, at du skal respektere den verden, du lever i. Dyrene, der vælger at kæmpe ved din side; glansen på dit våben; vægten af din ammunition; bidet fra en bitter vind; alle disse ting skal du kende indgående.\n\nJeg gør, hvad jeg kan for at hjælpe dig, men det meste af arbejdet er op til dig. Når du synes, du er klar, så kom tilbage og tal med mig. Jeg vil træne dig, når jeg kan."},
  [3109] = {n="Krypteret Rune", l="Læs den Krypterede Rune og tal med Solm Hårgrin i Kuldekam-dalen.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du har chancen. Jeg tænker, den kom fra snigmordertræneren Solm. Kig på den og find ham inde i Ambolmar, når du har chancen.", p="Du kom! Super!\n\nDer har været en tilstrømning af aktivitet på det seneste, så jeg er glad for at kunne tælle endnu en af Jernsmede-klanen blandt vores rækker. Alt for mange af os kigger på det arkane og det guddommelige, efter min smag. Intet imod dem og deres overbevisninger, men der er intet som et koldt sværd i din hånd og en skygge til at holde dig fra lyset, ved du hvad jeg mener?", c="Når du alligevel begynder at kigge rundt i Kuldekam, vil du sikkert få brug for træning på et tidspunkt. Du skal bare komme tilbage til mig, når du føler, du har brug for det, så lærer jeg dig det, jeg ved – et trick her, et manøvre der. Du ved, tingene der holder dig i live og tjener lidt ekstra penge.\n\nHold også øje med vores gnomiske venner... de fik lidt den korte ende af pinden med Nisseborgen, der blev... ødelagt. De får brug for vores hjælp for at føle sig velkomne."},
  [3110] = {n="Helliget Rune", l="Læs den Helligede Rune og tal med Branstock Khalder i Ambolmar.", d="Mens du hjalp mig, blev denne rune givet til mig for at videregive til dig. Tag dig tid til at læse den, når du har chancen. Jeg tænker, den kom fra præsttræneren Branstock. Kig på den og find ham inde i Ambolmar, når du har chancen.", p="Ak! Du kom, <Name>! Vidunderligt!\n\nJeg var lige ved at sige, at jeg var ved at miste troen på, at du overhovedet ville komme... forstår du, miste troen? Det er en vittighed, pige... åh, glem det. Du kom ikke her for mine dårlige vittigheder alligevel.", c="Jeg er den, der kan træne dig, mens du begynder at finde rundt i Kuldekam-dalen. Når du føler dig klar, så kom tilbage til mig, så ser vi, om vi kan lære dig en ny besværgelse eller to for at forsvare dalen mod de forbandede troggs.\n\nDu har Lyset på din side, sammen med hele Jernsmede, <Name>... ingen pres på dig for at blive noget særligt."},
  [3111] = {n="Glyfisk Rune", l="Tal med Gifte Nurribit inde i Ambolmar.", d="For længe siden lærte højalferne os magiens hemmeligheder sammen med vores menneskelige allierede. De prædikede for os om regler, og hvordan magi kan gøre dig gal! Men tro det ikke. Vi er ikke som alferne; vi har ikke de samme svagheder. Hold dig bare på den rigtige vej, så vil du finde ud af, at magi er lige så kraftfuldt et værktøj, som det er et våben.\n\nNår du er klar, så kom og find mig inde i Ambolmar. Jeg venter på dig!"},
  [3112] = {n="Simpelt Memorandum", l="Læs det Simple Memorandum og tal med Thran Kormand i Kuldekam-dalen.", d="Mens du hjalp mig, blev dette memorandum givet til mig for at videregive til dig. Tag dig tid til at læse det, når du har chancen. Jeg tænker, det kom fra krigertræneren Thran. Kig på det og find ham inde i Ambolmar, når du har chancen.", p="Ah, nå, endnu et memorandum fra en <Race> på en mission... er det ikke hyggeligt.\n\nNej, nej, jeg driller dig ikke, lille en. Du må respektere din sejhed, det er helt sikkert. Jeg ville være lige så sur, hvis Jernsmede var blevet overtaget af Mørkejern-dværge, så tænk ikke, at jeg ikke føler med din situation...", c="Nå, når nu det er din hovedopgave, eller hvad du nu kalder det i dag, gav jeg mit ord på, at jeg ville gøre alt, hvad jeg kan, for at sikre, at du og dine var klar til at tage jeres hjem tilbage... og det er netop, hvad jeg vil gøre.\n\nNår som helst du føler dig klar, så kom tilbage til gode gamle Thran, så deler jeg gerne min viden med dig. Der er nogle omkostninger for mig ved at træne dig, men de bliver ikke for dyre. Held og lykke."},
  [3114] = {n="Glyfisk Memorandum", l="Læs det Glyfiske Memorandum og tal med Gifte Nurribit inde i Ambolmar over Kuldekam-dalen.", d="Mens du hjalp mig, blev dette memorandum givet til mig for at videregive til dig. Tag dig tid til at læse det, når du har chancen. Jeg tænker, det kom fra magikertræneren Gifte. Kig på det og find ham inde i Ambolmar, når du har chancen.", p="Ja, hvad er det, <Race>? Tal højere, hvis du ikke har noget imod det. Jeg hører ikke så godt efter et par øl.", c="Åh, ja! Arkane Kunster... selvfølgelig.\n\nDet her skal du vide, <Name>: Kom ikke i for meget ballade. Spar nogle penge til at købe en øl til mig... eller nogle af de besværgelser, du måske vil have. Og hold dig for pokker væk fra Nisseborgen. Ellers, hav en god dag! Jeg er her, hvis du har brug for mig eller vil træne... eller hvad som helst."},
  [3115] = {n="Besmittet Memorandum", l="Læs det Besmittede Memorandum og tal med Alamar Grum inde i Ambolmar over Kuldekam-dalen.", d="Mens du hjalp mig, blev dette memorandum givet til mig for at videregive til dig. Tag dig tid til at læse det, når du har chancen. Jeg tænker, det kom fra hekseemestertræneren Alamar. Kig på det og find ham inde i Ambolmar, når du har chancen.\n\nOg pas på dig selv, <Name>, din slags er ikke særlig betroet her omkring.", p="Vidunderligt! Du fik åbenbart mit memorandum.\n\nIgnorer tosserne omkring dig, <Name>. Det Hellige Lys?! Sværdet og skjoldet?! Det er ikke veje for nogen så åbensindede som os. Se hvad \"normal\" magi gjorde ved vores hjem. Sammen med de forbandede tekniknisser var vores race næsten udryddet. Og nu må vi stole på dværgene – de vil hellere bruge tid på at alliere sig med menneskene end at hjælpe os med at genopbygge vores eget hjem. Vi er som andenrangsborgere. Har du set, hvordan de ser på os?", c="Men intet af det betyder noget. Det der betyder noget er, at du har set dit eget Hellige Lys! Du ved, hvor magten virkelig kommer fra. Du indser, at det at have vores egne allierede er langt mere... klogt. Særlige allierede. Allierede der, uanset opgaven, vil adlyde til deres sidste åndedræt.\n\nOg det er der, jeg kommer ind i billedet, <Name>. Jeg kan træne dig i begyndelsen af de særlige kræfter. Søg mig ofte, så vil jeg gøre, hvad jeg kan for at lære dig flere besværgelser."},
  [3117] = {n="Ætset Signet", l="Læs det Ætsede Signet og tal med Ayanna Evervandrer øverst på Aldrasil i Skyggedalen.", d="Dette signet blev givet til mig af en budbringer fra vores jægertræner, Ayanna. Det ser ud til, at Ayanna gerne vil have et ord med dig, når du har et øjeblik. Læs det og bring det til hende bagefter.", p="Du er ankommet, og ikke en dag for tidligt, <Name>. Velkommen til Skyggedalen.\n\nJeg håber, mit signet fandt dig i godt humør og godt helbred?\n\nSom jeg sagde før, er jeg her for at træne dig som jæger; for at tæmme dyr, der kan hjælpe dig i kamp; for at bruge en bue med ufejlbarlig præcision; for at respektere de lande, vi kalder hjem, og også landene derude.", c="Når du oplever, hvad Skyggedalen har at lære dig, så kom og se mig – jeg kan hjælpe dig med at forstå mere om din rolle som jæger, og hvad du er i stand til.\n\nDette er farlige tider, <Name>. Tag ikke dine kæledyrs færdigheder for givet – der er ting i denne verden, der er farligere, end du kan forestille dig. Gå med Elunie og kom tilbage til mig igen."},
  [3118] = {n="Krypteret Signet", l="Læs det Krypterede Signet og tal med Frahun Skyggehvisker i Skyggedalen.", d="Dette signet blev givet til mig af en budbringer fra vores snigmordertræner, Frahun. Det ser ud til, at Frahun gerne vil have et ord med dig, når du har et øjeblik. Læs det og bring det til ham bagefter.", p="Hej, <Name>. Jeg er glad for, at du fandt mig. Jeg tænkte, at du måske var faret vild på vejen hertil.\n\nIntet nyt er egentlig sket i Skyggedalen, siden jeg sendte dig mit signet, men jeg overlader al informationsindsamling til dig. Tal med resten af folkene omkring Aldrasil, hvis du vil.", c="Indtil da, vid at vores slags er mere nødvendige end nogensinde i denne skrøbelige tid. Freden med de andre racer kan briste når som helst, og der er meget snak om, at medlemmer af Horden forsøger at så endnu større mistillid. Husk det.\n\nNår du vinder i styrke og føler dig mere forberedt, så kom tilbage til mig her, så skal jeg sørge for, at du får noget træning. Det er vigtigt, at du ved, hvordan du håndterer dit valgte våben, blandt andre ting."},
  [3119] = {n="Helliget Signet", l="Læs det Helligede Signet og tal med Sjanda i Aldrasil.", d="Dette signet blev givet til mig af en budbringer fra vores præsttræner, Sjanda. Det ser ud til, at Sjanda gerne vil have et ord med dig, når du har et øjeblik. Læs det og bring det til hende bagefter.", p="Det glæder mig at se, at du er ankommet så hurtigt, <Name>. Velkommen.\n\nSom du nok har hørt, er hele Teldrasil i bevægelse med de rejsendes kommen og gåen. Selv medlemmer af Alliancen har fået adgang til Teldrasils grene for at mødes med andre Kaldoriske folk, der forbereder sig på eventyrene forude.", c="Bekymr dig ikke om verdenen under Teldrasil for nu. Der vil være tid til det senere. Gå nu og tal med de andre i Skyggedalen – de kan fortælle dig mere om, hvilke begivenheder der har fundet sted. Hjælp dem på enhver måde, du kan, og når som helst du føler, du har brug for mere træning, så kom tilbage til mig, og jeg vil lære dig, hvad jeg kan."},
  [3120] = {n="Frodigt Segl", l="Læs det Frodige Segl og tal med Mardant Stærkeeg, i træet Aldrasil i Skyggedalen.", d="Dette segl blev givet til mig af en budbringer fra vores druidelærer, Mardant. Det ser ud til, at Mardant gerne vil have et ord med dig, når du har et øjeblik. Læs det og bring det til ham bagefter.", p="Ah, unge <Class>. Jeg kan se, at du er ivrig efter at fortsætte dine studier. Godt.\n\nJeg undrer mig: har du allerede brugt meget tid i Den Smaragdgrønne Drøm? Måske er du ikke klar til det endnu... Med tiden, er jeg sikker på det.\n\nMen indtil da bør vi tale om andre sager.", c="Jeg bliver din mentor og vejleder indtil videre. Det er min pligt at lære dig at tolke ikke kun det, ånderne fortæller os, men også den Smaragdgrønne Drøms komplekse og hemmelige ting.\n\nNår du lærer og vokser i kraft, vil du lære mere om vores sovende trance. Men indtil da, kom tilbage til mig så tit du vil, så lærer jeg dig, hvad jeg kan, om vores slags måder."},
  [3121] = {n="En Underlig Anmodning", l="Tag det Krympede Hoved til Neeru Ildklinge i Orgrimgrad.", d="Neeru Ildklinge i Orgrimgrad har det, jeg skal bruge for at komme i gang her! Han har blandet et brygget, som jeg har brug for til min... ja, det ser du nok.\n\nVæk med dig nu -- til Orgrimgrad. Her, tag det med. Det er et krympet hoved, som jeg lovede Neeru i bytte for urterne. Det er hovedet af en stakkels dværg, jeg stødte på i skoven. Jeg er sikker på, at Neeru bliver glad.\n\nDu finder Neeru i Skyggeklyngen.", p="Ja?", c="Jeg har ventet på, at Uzer'i skulle levere dette...\n\nLad mig give dig urteblandingen, jeg tilberedte til hans... ja, eksperimenter..."},
  [3122] = {n="Tilbage til Heksedoktor Uzer'i", l="Lever Neeru's Urtepung til Heksedoktor Uzer'i i Vildalas.", d="Her er urterne, <Name>. Tag dem med til Heksedoktor Uzer'i.\n\nLad ham venligst vide, at jeg er tilfreds med det krympede hoved.", p="Har du talt med Neeru?", c="Det er netop det, jeg har brug for til at forberede musikkaret, <Name>. Snart vil vi se, om mine nyeste besværgelser er lige så kraftfulde, som jeg håbede.\n\nVent venligst et øjeblik. Jeg må udføre riten og anvende urterne."},
  [3123] = {n="Afprøvning af Karet", l="Rejs til Bagland og find Vildkinene. Dræb 10, og brug Muisik-karet til at krympe og fange de faldne Vildkin.\n\nBring 10 Vildkin-muisiker og Muisik-karet til Heksedoktor Uzer'i i Vildalas.", d="Dette bliver en prøve; både på riten, jeg udførte, og på dine evner. Tag dette kar, <Name>. Med det får du magten til at krympe og fange et væsen inde i det.\n\nRejs til Bagland og led efter væsener kendt som Vildkin, der engang var kæledyr for nattealfernes gudinde Elunie. De voldsomme, primitive eller vilde uglebæster er dine mål, <Name>. Dræb 10, og brug musikkarret til at krympe og fange dem, før deres ånder kan slippe væk.", p="Kunne du fange vildkinene?\n\nHvis du lykkes, er vi klar til at krympe og fange musikken fra væsenerne i Vildalas.", c="Når et væsen dør voldsomt, kan dets musik slippe væk og søge hævn. At krympe væsnerne, som du gjorde, <Name>, forhindrer musikken i at slippe væk. Nu kan vi bruge den, som vi vil!"},
  [3124] = {n="Hippogryf-musikken", l="Dræb 10 Slagfjer-hippogryffer af enhver slags, og brug derefter Muisik-karet til at krympe og fange dem.", d="Da du har vist, at du er både pålidelig og begavet med evnen til at bruge musikkarret, vil jeg nu have dig til at fange et andet væsen.\n\nHippogryffer har været loyale følgesvende for nattealferne i mange år; deres ånder er loyale og standhaftige.\n\nDin opgave er at dræbe 10 slagfjer-hippogryffer, og hurtigt krympe og fange dem med karet, så deres musik kan bevares. Du finder hippogryfferne i Højvildmarken, mod syd herfra.", p="Kunne du fange hippogryfferne?", c="Hvis vi lod musikken slippe væk, efter et dyr er dødt, kan den tage form af et endnu større væsen. Vi ville aldrig være sikre for dens hævn.\n\nDet er et farligt job, jeg har givet dig, <Name>. Endnu engang har du klaret det godt."},
  [3125] = {n="Fe-drage-musikken", l="Dræb 8 Sprite-pilere eller Sprite-drager. Brug Muisik-karet til at krympe og fange de faldne Fe-drager.", d="<Name>, næste gang må du fange et væsen, der i udseende måske virker ret skrøbeligt, men det er dets kraftfulde ånd, vi virkelig er ude efter. Fe-dragerne, jeg taler om, har tjent nattealferne som deres allierede. Vi må fange en, så hordens også kan drage nytte af denne åndens styrke.\n\nHer er musikken, <Name>. Dræb 8 sprite-pilere eller sprite-drager, og fang deres musik. De kan findes mod vest herfra.", p="Kunne du fange musikken fra fe-dragerne?", c="Tak, <Name>. Nu vil fe-dragernes åndelige kræfter være til rådighed for os.\n\nJeg håber, du vil udføre endnu en opgave for mig."},
  [3126] = {n="Trælding-musikken", l="Dræb 3 Vandrende Skovgængere. Brug Muisik-karet til at krympe og fange de faldne Trælding.", d="De vandrende skovgængere, man kan finde slentrende rundt i skoven, er vores næste mål, <Name>. Nattealferne har hvervet trælding som allierede til at kæmpe mod hordene. Deres bevægelser kan være langsomme, men deres rolle som beskyttere kan ikke benægtes.\n\nSnart vil vi kunne bruge denne kraft til vores egen fordel.\n\nFind 3 vandrende skovgængere; dræb dem, og brug musikkarret til at krympe og fange dem.", p="Kunne du fange de vandrende skovgængere?", c="Tak, <Name>. Vores musiksamling er næsten færdig."},
  [3127] = {n="Bjergkæmpe-musikken", l="Dræb 7 Landgængere eller Klippekæmper. Brug Muisik-karet til at krympe og fange de faldne Bjergkæmper.", d="Den sidste opgave, jeg vil kræve af dig, er at rejse mod nordvest og finde den sidste fjende.\n\nBjergkæmperne forlod bjergene for at hjælpe nattealferne, da den brændende legion dukkede op i verden. Du kender dem på deres enorme størrelse og på måden, jorden begynder at ryste, når du rejser over deres klippefyldte terræn.\n\nJeg er ivrig efter at udnytte kraften fra en størrelse som den. Dræb 7 bjergkæmper, og brug derefter musikkarret til at fange deres kraftfulde musik.", p="Kunne du fange bjergkæmperne?", c="Forestil dig blot mulighederne i det, vi nu besidder, <Name>. Sammen med de materialer, du har samlet, kan jeg for evigt fange musikken fra disse væsener i hvad som helst, jeg ønsker."},
  [3128] = {n="Naturlige Materialer", l="Bring 2 Splintrede Træstammer, 6 Indkrystalliserede Mineraler, 20 stykker Modstandsdygtige Sener og 40 Metalliske Fragmenter til Heksedoktor Uzer'i i Lejr Mojasje.", d="Jeg skal bruge visse materialer for at fuldføre mit værk... Du kan gøre det sammen med de andre opgaver, jeg giver dig.\n\nJeg skal bruge en splintret stamme fra en trælding i Vildalas. Indkrystalliserede mineraler kan findes på bjergkæmperne og fe-dragerne mod vest. Find også nogle modstandsdygtige sener fra uglebæsterne i Bagland eller hippogryfferne i Vildalas. Til sidst skal jeg bruge en stor mængde metalliske fragmenter fra et af de væsener, jeg har nævnt.", p="Kunne du samle de materialer, jeg skal bruge?", c="Fremragende! Disse materialer, sammen med musikken, bør give præcis de resultater, vi har ønsket."},
  [3129] = {n="Åndens Våben", l="Heksedoktor Uzer'i vil have dig til at vente et øjeblik, mens han forbereder våbnene.", d="At indgyde musikken i våbnene er en vanskelig proces. Nu hvor jeg har alle de nødvendige materialer og musikken fra de væsener, du fangede, kan jeg begynde. Vent venligst; jeg kommer tilbage om et øjeblik.", c="Som lovet har du dit valg, <Name>. Musikken fra væsenerne er for evigt forseglet i disse våbnes kraft.\n\nDu kan nu bruge deres energi som din egen. Brug den godt."},
  [3130] = {n="Mod Hadkam", l="Meld dig til Latronicus Månespyd i Fjermåne-fæstningen.", d="På dette tidspunkt vil jeg sende dig videre til min næstkommanderende, Latronicus. Han har holdt et vågent øje med slangefolkets styrker indtil nu. Jeg vurderer den generelle situation her med hensyn til slangefolket; selvom jeg gerne vil sætte en fuld styrke ind mod dem, virker det mindre optimalt at efterlade fæstningen åben for direkte angreb fra Horden - eller værre.\n\nUnder alle omstændigheder venter Latronicus. Godt arbejde indtil nu, <Name>. Bliv ved.\n\nDu er afskediget.", c="Fremragende, <Name> - jeg sætter pris på en \"det kan jeg\"-attitude hos dem, jeg arbejder med.\n\nGeneral Fjermåne har bedt mig om at tage slangefolket op på en direkte måde. Mine planer er todelte: For det første vil vi svække deres styrker, både i antal og i ledelse, og for det andet vil vi afdække, hvad de laver i ruinerne. Med din hjælp vil vi modvirke slangefolkets tilstedeværelse uden at ofre fæstningens generelle sikkerhed."},
  [3141] = {n="Lorumus", l="Lyt til Lorumus Talipedes fortælle sin historie.", d="Så du vil kæmpe mod dæmoner? Du gør klogt i at lytte til min fortælling.", p="Afbryd mig ikke, <Race>.", c="Så være det..."},
  [3161] = {n="Gahz'ridisk", l="Marvin Nitsøger i Tanarisørknen vil have dig til at samle 30 Gahz'ridiske Ornamenter.", d="<Name>, jeg er videnskabsmand, men også skatjæger i hjertet!\n\nFor længe siden, da trolde boede i dette land, skabte de store mængder ornamenter formet efter Gahz'hydra, en hydra de tilbad som en gud. Disse ornamenter er udskåret af et element, som jeg kalder \"Gahz'ridisk\", efter hydragudden.\n\nJeg fandt selv nogle, men jeg vil gerne have flere at studere -- måske kan du finde nogle?\n\nJeg har endda opfundet en detektor, der gør det til en leg at finde Gahz'ridisk! Bare tag den på, så begynder jagten!", p="Har du problemer?\n\nDu kan finde Gahz'ridisk næsten hvor som helst i Tanarisørknen, <Name>, så bliv ved med at lede!", c="Perfekt; disse ornamenter er ideelle til mine studier. Mange tak for hjælpen, <Name>.\n\nÅh, kan jeg få min hjelm tilbage?"},
  [3181] = {n="Hornet af Udyret", l="Tag Margols Gigantiske Horn til Bjergbestiger Stenbider.", d="Det gigantiske horn har mange ridser og revner. Et usædvanligt metalobjekt sidder fast i den ru overflade.\n\nVed nærmere undersøgelse opdager du, at metallet faktisk er et ødelagt øksehoved. På metallet er følgende ord indgraveret:\n\nEjendom tilhørende Bjergbestiger Stenbider.\n\nNår du forsøger at løsne det ødelagte øksehoved, splitter det i en million stykker.\n\nUps!", p="Nej, jeg åbner ikke porten.", c="Hvad har du dér? En falsk, åbenbart!\n\nJeg har stået ansigt til ansigt med Margol, og jeg ved med sikkerhed, at hendes horn er mindst otte gange større end det, du har i hænderne, <Name>. Du har sikkert fået det af en stormsnude i Ødemarken. Nej, du kan ikke narre Stenbider!"},
  [3182] = {n="Bevis for Skøde", l="Tag Margols Gigantiske Horn til Kurator Torius i Jernsmede.", d="Du forventer, at jeg tror på sådan en historie? Det rigtige horn ville have haft mit ødelagte øksehoved siddende i overfladen.\n\nLyt, tag den åbenlyse falske til Kurator Torius i Jernsmede. Hvis han kan bekræfte din påstand, får du et skødebevis. Bring det bevis tilbage til mig, så giver jeg dig nøglen til Brændende Kløft.\n\nVæk med dig!", p="Hej der, unge mand. Vil du have en rundvisning i museet?", c="Hvad er dette?\n\nÅh, jeg kan ikke tro det! Ved du, hvad du har fået fat i, <Race>? Dette er hornet fra Margol den Rasende! Margol, plageånden for enhver arkæolog, der nogensinde satte fod i Brændende Kløft.\n\nMå jeg beholde det?"},
  [3201] = {n="Endelig!", l="Tag Skødebeviset tilbage til Bjergbestiger Stenbider.", d="Jeg kan ikke tro, at Stenbider tvivlede på hornets ægthed. Mellem os to tror jeg, at hun bare er jaloux. Jeg ved, at hun virkelig ville dræbe det udyr selv, med 'hændelsen' og det hele.\n\nSå du har brug for et skødebevis? Efter det bidrag, du lige har givet til museet, er det ikke noget problem.\n\n<Kurator Torius begynder at udfylde et stort dokument.>\n\nSå var det! Du kan tage det med tilbage til Stenbider.", p="Jeg kan ikke tro det.", c="Jeg forstår ikke, hvordan nogen så svag som dig overvandt Margol, men en aftale er en aftale. Her er nøglen.\n\nHvis der sker noget med dig efter dette, er det din egen skyld."},
  [3221] = {n="Tal med Renferrel", l="Tal med Apoteker Renferrel ved Gravkammeret.", d="Mens du var ude og hjalp vores dødsstalkere, sendte Apoteker Renferrel dig en indkaldelse. Han gav mig ikke detaljer, men han ville tale med dig om ulvehjerterne, du havde givet ham.", c="Ah, meget godt. Der er en sag angående de ulvehjerter, du bragte til mig tidligere, som kræver vores opmærksomhed."},
  [3321] = {n="Har Du Tabt Dette?", l="Vent på, at Trentun bliver færdig med sit arbejde.", d="Du har gjort meget for Ordenen, <Name>. Den rene hengivenhed, det kræver at komme så langt, ville have afskrækket enhver almindelig person. Der er ingen tvivl i mit sind, eller i Galvins sind, om at du er en af os.\n\nDerfor synes jeg, du fortjener en lille belønning. Det er ikke noget særligt, bare en lille ting. Du kender måske dens egenskaber, for jeg tror, det er det, der bragte dig til os fra starten.", p="I dag afslutter vi vores fejring af din hengivenhed over for Ordenen.", c="Rejs dig og bliv anerkendt, <Name>, smed i Mithril-orden."},
  [3341] = {n="Afslutningen", l="Andrew Brunell vil have dig til at dræbe Amnenar Koldebringer og bringe hans kranie tilbage.", d="I Ødemarken ligger et forfærdeligt rod af sammenfiltrede ranker kaldet Barberfen-heden. Mens vores første observationer af stedet afslørede lidt trussel, er vores seneste fund meget mere alvorlige...\n\nPindsvinebasserne i Barberfen-heden har alliereret sig med Pesten. En Liske ved navn Amnenar Koldebringer hersker nu over dem og bruger kraften i sit enorme bevidsthed til at kontrollere hver eneste af deres bevægelser.\n\nAmnenar har en direkte telepatisk forbindelse til Ner'zhøl; vi må afbryde dette bånd, <Name>. Der må komme en ende på Koldebringeren.", p="Denne sag er af højeste vigtighed, <Name>. Vi må stoppe ethvert forsøg fra Pesten på at styrke deres rækker.", c="En Liskes loyalitet er urokkelig, <Name>. Lad dem vide, at sådan loyalitet kun vil bringe dem til undergang."},
  [3362] = {n="Tistelbuskdalen", l="Tran'rik i Gadgetbyen vil have dig til at dræbe 8 Knudrede Tistelbuske og 8 Tistelbusk-rodformere.", d="Har du nogensinde set Tistelbuskdalen? Det er et vældigt farligt sted, <Name>.\n\nDe mærkelige væsner dér, jeg stoler ikke på dem et øjeblik! Knudrede tistelbuske og tistelbusk-rodformere, det var vist det, de hed...\n\nUnder alle omstændigheder vil jeg ind i dalen, men med så mange af de tistelbuske rundt omkring er der ingen måde, jeg vender tilbage dertil. Men her er der, hvor du kommer ind i billedet -- hvis du rydder nogle af dem ud, tænker jeg måske på at vende tilbage. Hvad siger du, <Name>? Hjælper du mig?", p="Jeg vil gerne kigge nærmere på den kaktus i dalen... Så lad noget af den stå hel, vil du?", c="De er så store? Jeg må nok genoverveje min plan...\n\nMen du har holdt din side af aftalen, så her er, hvad jeg lovede."},
  [3366] = {n="Det Glødende Skår", l="Rejs til Rakhjul for at finde betydningen bag Mareskåret.", d="Skåret er en strålende grøn, og selvom det er fast, hvirvler det, der ligner røg, lige under overfladen. Du kan ikke lade være med at stirre ned i krystallens dybder; samtidig ved du, at der er noget meget foruroligende ved det.\n\nMåske skulle du se, om nogen i Rakhjul kan fortælle dig mere om dette underlige skår."},
  [3367] = {n="Solstara-stenene", l="Hjælp Dorius Dorsk med at komme tilbage til Jernsmede.", d="<Dorius stønner.>\n\nJeg er slemt såret, <Race>. Føler mig... svimmel... Verden snurrer... Blør... indvendigt.\n\nJeg må komme tilbage til Jernsmede. Hjælp mig, <Name>.", p="Jeg kommer ikke til at klare det...", c="Dette brev blev tabt af Dorius Dorsk, da han blev skudt."},
  [3368] = {n="Solstara-stenene", l="Tag det Svedne Brev til Torius i Jernsmede. Han er i Opdagelsesrejsendes Hal.", d="Bror,\n\nHvis du læser dette brev, er jeg ikke længere. Hvordan det nåede dig, ved jeg ikke, men tak og belønn dem, der er ansvarlige.\n\nOm stenene: De findes, og Mørkjernsdværgene har dem i deres besiddelse. Deres leder, Lathorik den Sorte, bruger stenenes kraft til at gøre mit udgravningshold til slaver. De blev taget til kedlen. Deres sind er vredet, og de arbejder dag og nat på at fuldende noget, der kaldes Obsidiøn.\n\nHjælp dem, bror. Det er en død mands sidste ønske.\n\n-Dorius Dorsk", p="<Torius hulker.>", c="<Torius tørrer sit ansigt.>\n\nI Letts navn skal han få sit ønske. Dette sværger jeg."},
  [3371] = {n="Dværgisk Retfærd", l="Vend tilbage til Brændende Kløft og find Dorius Dorsks arkæologiske enhed.", d="Der er et tomt, hulet hul, hvor mit hjerte plejede at være, <Name>. Tabet af Dorius Dorsk er ikke noget, jeg snart kommer over. Jeg må føre hans sidste ønske igennem - gerningsmændene bag dette koldblodige mord må stilles for retten.\n\nVend tilbage til Brændende Kløft og opfyld hans sidste anmodning: Befri hans mænd.", c="Glem mig, hjælp de andre."},
  [3372] = {n="Frigør Dem", l="Find den Mystiske Artefakt, som Tusmørkets Hammers Afgudsdyrkere bevogter i det nordvestlige kvarter af Brændende Kløft.", d="Frigør dem, <Race>. Selv efter deres kroppe er brugt op, tvinger Solstaras kraft dem til at fuldføre deres opgaver.\n\nSolstaras alter er nøglen. Gå mod nordvest; i bakkerne over hulen... Tusmørkets Hammer vogter en relikvie. Hent den og placer den på Solstaras alter.\n\n<Den døende arkæolog kollapser.>", p="Alteret er tomt.", c="Du placerer den mystiske artefakt på Solstaras alter."},
  [3373] = {n="Essensen af Eranikas", l="Placér Essensen af Eranikas i Essens-døbefonten, der ligger i denne hule i Det Sænkede Tempel.", d="Da du rører ved ædelstenen, genlyder en dyb stemme i dit sind.\n\n\"Dødelig, lyt til denne anmodning. Jeg er Eranikas fra Grøn Drageflugt, vogter af dette forbandede tempel. Min pligt om at sikre, at trolde aldrig igen frembringer deres vederstyggelige gud, er indtil videre endt i fiasko. Mens jeg indgyder denne ædelsten med en del af min essens, mærker jeg, at mit greb om Drømmen vrider sig ud i kaos. Venligst - placér denne ædelsten i essens-døbefonten i min hule, og lad vores magi dér rense besmittelsen fra mit sind, så jeg kan hvile.\"", p="Da du nærmer dig essens-døbefonten, som Eranikas fortalte dig om, rører hans stemme atter ved dit sind.\n\n\"Ja dødelige, denne essens-døbefont vil frelse den ubesmittede del af mit sind, der stadig er indgydt i denne ædelsten. Placér ædelstenen i døbefonten, og lad Grøn Drageflugts magi rense korruptionen og besmittelsen fra mit væsen. Først da vil jeg finde ægte forløsning, og først da vil Drageflugten igen kunne gøre krav på sit forvalterskab over Atal'aj.\"", c="Du placerer ædelstenen i essens-døbefonten.\n\n\"Tak dødelige, du har - nej... dette, dette kan ikke være! Nej! Denne forbandede guds korruption besmitter endda helligheden i en Grøn Drageflugts essens-døbefont! Nej, værsgo, jeg mærker min essens rives ud af mig! SMERTEN! Jeg mærker et evigt mareridts greb tage fat i mig...\"\n\n\"Dødelige, jeg bønfalder dig! Find en fra Grøn Drageflugt, der kan stoppe dette... hjælp mig... jeg er lænket i mørket... evigt i pine... venligst, pines ikke...\""},
  [3374] = {n="Essensen af Eranikas", l="Bring Yseras Drageflugts Edsten og den Lænkede Essens af Eranikas til Itharius i Sorgernes Sump. Det er der, du skal træffe dit valg om at hjælpe Yseras Drageflugt eller ej.", d="Du aktiverer Edstenen, og Itharius taler direkte til dit sind gennem stenen.\n\n\"Ved at acceptere pligten, der er lagt i denne Edsten, indvilliger du i at hjælpe min sag og Yseras Drageflugts sag med at forløse den fordærvede sjæl Eranikas. Det første offer, et af mange, du og jeg uden tvivl vil bringe, er at overdrage mig den ædelsten, der har lænket den fri-viljede del af Eranikas' sind, der stadig består.\"\n\n\"Gør dette <Name>, så arbejder vi sammen om at forløse en sjæl, der er værdig til forløsning.\"", p="Her er vi <Name>, ved endnu et vejkryds. Tiden er kommet til at træffe endnu et valg. Hvilket valg træffer du, dødelige?", c="Du har truffet dit valg, og således begynder det. Dine valg har hidtil været, hvad jeg ville anse for de rigtige; dine handlinger og gerninger herefter vil afgøre, om dette fortsætter."},
  [3376] = {n="Knæk Skarptand!", l="Bring hovedet af Høvding Skarptand Tornemantel til Modig Vindfjer i Røde Sky-plateauet.", d="<Name> - jeg har hørt om dig, nykomling. Måske er det dig, der vil hjælpe os, hvor andre har fejlet.\n\nVi taurener har udhugget et hjem i dette land, men ikke uden en pris. Børsterygge-quilboarerne i Brombærklinge-kløften, anført af Høvding Skarptand Tornemantel, har gjort vores liv svært med deres vedvarende krig mod os. Jeg pålægger dig at bringe mig høvdingens hoved!\n\nHan vil findes i kløften mod øst, i deres provisoriske landsby.", p="Skarptand vil ikke volde os flere problemer, når du har bragt mig bevis for hans død. Det er hans hoved, jeg søger, <Name>.\n\nVi taurener lever for jagten, og der findes ingen større jagt end en mod en, der er snedig nok til måske selv at jage os tilbage. Hvis du lykkes med denne opgave, unge, vil du begynde at forstå, hvad jeg mener.", c="Retfærden er skredet frem på denne dag ved din hurtige handling, <Name>. Lad denne gerning tjene som en advarsel til alle, der ville true vores hjem.\n\nDu har fortjent denne belønning til at hjælpe dig på din rejse, unge <Class>."},
  [3377] = {n="Bøn til Elunie", l="Hør Zamael fortælle sin historie.", d="Vil du hjælpe mig, dødelige? Hør min historie.", p="Lad mig få fortalt min historie færdig.", c="Jeg har accepteret min skæbne her i dette bur, men bønnen skal findes."},
  [3378] = {n="Bøn til Elunie", l="Find Bønnen til Elunie og bring den til Astarii Stjernesøger i Darnassos.", d="Vil du hjælpe mig, dødelige? Vil du finde bønnen til Elunie?\n\nSom jeg har sagt, var bønnen ridset ind i en gylden tavle. En af disse afgudsdyrkende skurke må have den på sig.\n\nHvis du gendrager min bøn, så bring den til Astarii Stjernesøger i Darnassos. Det betyder lidt, at min tro er blevet genoplivet efter de utallige ondskabsfulde handlinger, jeg har begået mod denne verden og dens indbyggere, men min bøn må høres. Forsoning er det sidste, jeg forventer.", p="Hvad fører dig til Månens Tempel, <Name>?", c="Elunie smiler til dig i aften, <Name>. Du har bragt en fortabt sjæl tilbage til hende. Modtag venligst dette som et tegn på vores taknemmelighed."},
  [3379] = {n="Skyggevæver", l="Dræb flokken af Skyggesilke-krybskytter, der vandrer rundt i Brændende Kløft. Nilit har grund til at tro, at der er fem af dem, der skal udryddes. Vend tilbage til Nilit i Brændende Kløft, når opgaven er fuldført.", d="Edderkopperne i Brændende Kløft er en uvurderlig kilde til skyggesilke. Som du ved, er skyggesilke meget eftertragtet af håndværkerne i vores fag.\n\nFor nylig har en flok krybskytter trængt ind på disse lande og dræbt edderkopper i massevis uden så meget som en tanke for deres handlingers langsigtede effekt. Den første opgave, jeg beder dig om, er derfor en enkel en: Find dem... og gør ende på dem.\n\nBegynd din søgning mod nord.\n\nHvis du har brug for hjælp, så tal med Hærger.", p="Hvilke oplysninger har du?", c="Fremragende arbejde, <Name>.\n\nJeg er sikker på, at dette er et stykke skyggevæv, du endnu ikke har set."},
  [3380] = {n="Det Sænkede Tempel", l="Find Marvin Nitsøger i Tanarisørknen.", d="Der findes rastløse ånder i denne verden, <Name>. Der findes ånder, der er blevet besmittet af deres isolation, bundet til en gammel ondskab...\n\nJeg har hørt om et sted, der ligger dybt under jordens overflade -- forvist dertil af magter større end nogen, jeg nogensinde har set.\n\nHvis du ønsker at lære mere om dette sted, Det Sænkede Tempel, så søg en kobold ved navn Marvin Nitsøger. Han har studeret mange gamle områder i verden, og han blev sidst set forlade sit hjem i Skralleby for at studere trolderuinerne i Tanarisørknen.", c="Ja, Det Sænkede Tempel, jeg kan sige, at jeg har set det med mine egne øjne. Vil du måske gerne høre mere om det?\n\nDu ligner den eventyrlystne type -- jeg kender ting, der kan interessere dig..."},
  [3381] = {n="Et Møde med Mesteren", l="Bring 2 Uskadte Hippogryf-fjer til Sanath Lim-jo i Azshara, hvis du ønsker at tale med hans herre.", d="Ah, en ung <Race>, der er kommet for at tale med Sanath. Hvilken vidunderlig dag! Jeg er så beæret over, at du nåder mig med din tilstedeværelse. Tak!\n\nVær venligst ikke så arrogant at antage, at min sarkasme var et kompliment. Lad os få én ting på plads: Jeg kan ikke lide dig. Men denne lille samtale har intet med os at gøre -- den handler om min herre.\n\nBring mig et par hippogryf-fjer til mine pile, så giver jeg dig lov til at se ham. Han har bedt mig sende eventyrere til ham, hvis de har vist sig værdige nok.", p="Jeg bliver her efter min herres befaling. Jeg har fået lov til at kræve enhver pris, jeg ønsker, for transport op til hans tårn. Indtil videre beder jeg kun om de to fjer fra hver rejsende, så jeg kan fortsætte med at lave mine signaturpile.\n\nHvis du ikke er forsigtig, hæver jeg prisen. Hvordan lyder et halvt dusin guld?\n\nJa, det tænkte jeg nok. Pas bare på dig selv, så holder jeg prisen, hvor den er.", c="To fjer, præcis som jeg bad om. Og slet ikke dårlige.\n\nKlar så? Bare sig ordet, så er du på vej.\n\nÅh, og igen, pas på dig selv... min herre tager ikke venligt imod tossede, men han er meget generøs over for dem, der behager ham."},
  [3382] = {n="Et Mandskab Under Ild", l="Forsvar Kaptajn Vanessa Beltis, hendes mandskab og Horisont-spejderens passagerer mod slangefolkenes angreb. Kaptajn Vanessa Beltis må ikke dø.", d="Vi lå lige ud for kysten og ledte efter et sikkert havnested til at kaste anker. Solen var ikke gået ned i mere end en time, da de angreb... de forbandede slangefolk!\n\nJeg er ikke sikker på, hvad de ledte efter, men det er klart, at de ikke fandt det -- de er allerede vendt tilbage én gang. Et par af mine spejdere holder vagt ved indgangen til dalen for at give os rettidig advarsel, når næste angreb kommer.\n\nJeg beklager, at du er kommet med nu, <Name>, men det er uden for min kontrol.\n\nEr du klar til kampen om dit liv?", p="Dette bliver et hårdt slag...", c="Du har klaret det! Tak! Dette var helt sikkert et af de brutaleste slag, jeg nogensinde har deltaget i. Jeg kan ikke takke dig nok.\n\nJeg ønsker blot, at flere af mit mandskab havde overlevet denne prøvelse.\n\nJeg vil bede dig om at tale med eventuelle overlevende passagerer fra Horisont-spejderen. Nogle af dem havde forretninger i området og har måske en anmodning eller to til dig, hvis du er villig. Endnu en gang tak for al din hjælp."},
  [3385] = {n="Undermarkedet", l="Slå Handelsmester Kovik og hans håndlanger Klunk ihjel. Hent Handelsmandens Taske fra hans lig og bring den til Nilit.", d="De kalder sig Undermarkedet: Halsafskærer-handlere, der vil sælge, flytte, handle og gøre næsten alt for den rette pris.\n\nDet bliver værre, <Name>. De har etableret et operationscenter her i Brændende Kløft. Handelsmester Kovik står i spidsen for operationen og har tætte bånd til Mørkejern-dværgene i regionen.\n\nVi må slå hårdt til og sende et budskab til deres ledelse. Slå Handelsmester Kovik og hans håndlanger Klunk ihjel. Bring hans handelsmandstaske tilbage, når opgaven er udført.\n\nTil Gryden!", p="Lever Handelsmesteren stadig?", c="Du har givet Undermarkedet et afgørende slag. Deres ledere vil tænke sig om to gange, før de sender flere håndlangere ind i kløften.\n\nÅh, og jeg fandt heller intet nyttigt i handelsmandens taske. Du må beholde, hvad du end finder indeni."},
  [3402] = {n="Undermarkedet", l="Tal med Vizzklik i Gadgetbyen.", d="Jeg vil have dig til personligt at overbringe nyheden om Koviks nederlag til Vizzklik i Gadgetbyen. Han vil blive så glad for at høre, at Kovik er død, at jeg er sikker på, at han giver dig en storslået belønning.", c="Kovik slået ihjel??! Dette er en herlig dag, <Name>! I årevis har den skurk drevet skumle undermarkedshandler og underbudt ærlige, hårdtarbejdende handlere over hele verden.\n\nDu fortjener en fin belønning for denne bedrift! Og en fin belønning skal du få!"},
  [3441] = {n="Guddommelig Gengældelse", l="Lyt til, mens Kalaran Vindklinge fortæller sin historie.", d="Hør min historie, eventyrer.", p="Lad mig få fortalt min... <Race>.", c="Har du hørt nok? Er du klar til at handle?"},
  [3442] = {n="Den Fejlfri Flamme", l="Saml 4 Flammehjerter og 4 kugler Golemolie, og bring genstandene til Kalaran Vindklinge.", d="Du har truffet den rigtige beslutning, <Name>.\n\nVi må slå, hvor vi gør størst skade: de fire vagttårne.\n\nNår de fire tårne står i flammer, kan vi indlede et offensiv, før de når at reagere.\n\nDu skal bruge det rette værktøj for at sætte tårnene i brand. At lave værktøjet kræver nogle materialer.\n\nBring mig fire flammehjerter og fire golemolie, så smeder jeg fakklen af den fejlfri flamme.\n\nGolemerne og elementarerne i disse lande bør være dit første mål.", p="Har du samlet materialerne?", c="Godt gjort, <Name>. Vi er næsten klar."},
  [3443] = {n="Smedning af Skaftet", l="Bring 8 Thoriumpladerede Dolke til Kalaran Vindklinge.", d="For at holde den fejlfri flamme får vi brug for et skaft og et hylster. Du må først finde et passende skaft.\n\nMørkejern-pisket og slaverne i Gryden bruger våben af fortryllet thorium, en ekstremt robust legering. Hvis du bringer mig otte thoriumpladerede dolke, kan jeg nedbryde legeringen og omsmede et skaft.", p="Otte, <Name>. Jeg har brug for otte!", c="Du er en enestående arbejder, <Name>. Har du nogensinde overvejet et skifte af erhverv? Måske detektiv? Skraldesamler? Åh, jeg ved det, en af de dumme gnomer, der kravler rundt på Azeroths strande med deres metaldetektor-kramme og leder efter tabte skatte. Ja, det ville være en ideel stilling for dig."},
  [3444] = {n="Stenkredsen", l="Hent Stenkredsen fra Marvin Nitsøgers værksted i Skralleby.", d="Jeg trådte engang ind i Det Sænkede Tempels uhyggelige kamre. Ondskaben på det sted gennemtrænger alle, der træder ind; jeg formåede knap at finde vej ud, vadende gennem slimvæsenet, der nu dækker gulvene. Alt, hvad jeg husker, er at snuble gennem et stort, cirkulært rum, fyldt med slangestatuer...\n\nFor nylig opdagede jeg en rund sten, der tilsyneladende havde det samme slangesymbol indgraveret i sig. Jeg fik den pakket og sendt til mit værksted i Skralleby. Hent den, så kan jeg måske fortælle dig mere.", p="Skralleby er ikke langt herfra, <Name>. Rejsen burde ikke tage lang tid.", c="Ja... Dette er stenen.\n\nDet hele kommer tilbage til mig nu, <Name>..."},
  [3445] = {n="Det Sænkede Tempel", l="Find Marvin Nitsøger i Tanarisørknen.", d="Jeg har hørt om et sted, der ligger dybt under jordens overflade -- forvist dertil af magter større end nogen, jeg nogensinde har set.\n\nHvis du ønsker at lære mere om dette sted, Det Sænkede Tempel, så søg en kobold ved navn Marvin Nitsøger. Ligesom Trojas og jeg har han studeret mange gamle områder i verden. Han blev sidst set forlade sit hjem i Skralleby for at studere trolderuinerne i Tanarisørknen.\n\nHeld og lykke med at finde ham; man har ikke hørt fra ham i nogen tid.", c="Ja, Det Sænkede Tempel, jeg kan sige, at jeg har set det med mine egne øjne. Vil du måske gerne høre mere om det?\n\nDu ligner den eventyrlystne type -- jeg kender ting, der kan interessere dig..."},
  [3446] = {n="Ind i Dybderne", l="Find Hakars Alter i Det Sænkede Tempel i Sorgernes Sump.", d="Inde i templet fandt jeg et cirkulært rum med seks altaner, hver med en slangestatue ved kanten. Nysgerrig skubbede jeg til en af dem for at se, hvad der ville ske, og det var en fælde! Jeg faldt næsten til min død i eksplosionen. Da jeg lå der på syllen, kiggede jeg ned og bemærkede, at der var en anden statue ved bunden af rummet; en slags alter... Hakar, tror jeg, det hed.\n\nJeg tror, at dette alter er hemmeligheden -- du skal bringe dette symbol til alteret i Det Sænkede Tempel.", p="Ved undersøgelse af statuen bemærker du en fordybning i dens side, lige stor som symbolet, Marvin gav dig...", c="Du skubber stenkredsen ind i åbningen, og du hører den låse sig fast.\n\nNu hvor stenen er på plads, kan du fortsætte... men hvad skal du gøre næste gang?\n\nMåske bør du undersøge dette alter nærmere..."},
  [3447] = {n="Kredsens Hemmelighed", l="Rejs ind i Det Sænkede Tempel og opdag hemmeligheden skjult i statuernes kreds.", d="Mine minder er tågede, men jeg vil fortælle dig, hvad jeg kan. Statuernes kreds i Det Sænkede Tempel er farlig, men jeg tror, at den rummer hemmeligheden bag en endnu større skat.\n\nFra hovedalteret var jeg i stand til at aktivere en række lys. Jeg tror, at hvis du kan finde ud af, hvad disse lys betyder, kan du måske låse op for de hemmeligheder, der gemmer sig i dette rum.\n\nJeg advarer dog dig, <Name>. Stor ondskab bor i templet. Det er sandsynligt, at alt, der har værdi, vil blive vogtet hidsigt...", c="Idolens øje glimter klart, selv i templets halvmørke. Dets gennemsigtighed afslører noget skinnende bagved. Du skubber det til siden, rækker ind og griber fat i det, der ligger inde i statuen.\n\nAtal'aj-skatten er nu din."},
  [3448] = {n="Byrdens Overdragelse", l="Tal med Tymer i Jernsmede.", d="Jeg har for nylig fået ansvaret for at undersøge Azshara -- et engang smukt område, som alferne kaldte hjem. Dette var dengang, de praktiserede magi. Det er nu et farligere sted end det er smukt, men det holder os ikke fra at vende hver sten for svar på vores fortid.\n\nEn af mine ledsagere ved navn Tymer tilbød at hjælpe mig med at undersøge området, da han har en særlig interesse for sådanne ting.\n\nHan ejer et lille sted til højre for Mysteriernes Hal her i byen.", c="Ah, Karnik sendte dig, gjorde han? Jeg havde forventet at høre fra ham snart. Jeg har opdaget så vidunderlige ting om Azshara.. Jeg ved, at nattealferne har utrolige levetider, men alle glemmer nogle gange nogle af de mere... uheldige begivenheder i deres liv. Det er ikke ment som en kritik, bare en iagttagelse.\n\nLænge siden var der byer skabt af alferne, fyldt med viden om magi og andre tabte kunster. Da jeg er student af sådanne ting, begyndte jeg min undersøgelse. Det, jeg fandt, var ganske spændende."},
  [3449] = {n="Arkane Runer", l="Brug Tegnesættet til at lave aftryk af Runen af Beth'Amara, Runen af Jyn'yael, Runen af Markri og Runen af Sael'haj, før du tager til den lille ø ud for den sydlige halvø i Azshara og signalerer til Pilot Xiggs Lunteantænder, så han henter dem.", d="Magi var engang lige så højt ansete som Elunie selv for nogle alfer. Nogle af deres mest magtfulde magikere skabte runer og tavler, der angav arkanens regler og indsigter i deres opdagelser. De ville efterlade disse, så alle kunne grundes over dem på offentlige steder.\n\nJeg ville meget gerne have aftryk af disse runer fra Ruinerne af Eldarath. Jeg har et sæt til dig, som du kan lave aftrykkene med, men det bliver op til dig at finde dem. Vær forsigtig dog, for Opdagelsesrejsendes Liga er ikke den eneste, der er interesseret i Eldarath.", p="Nå, nå, nå, godt at se, at du kom hertil, <Name>. Fik du aftrykkene til Tymer?\n\nFarligt som dette sted er, har der ikke været meget handling langs kysten. Det kan skyldes, at slangefolkene svømmer under vandet, men det er ikke mit problem... Jeg patruljerer himlen.", c="Godt at se dig i sikkerhed, <Name>. Jeg håber, at tingene ikke var for hårde for dig.\n\nJeg får disse til Tymer med det samme. Han bliver begejstret for at kigge på dem.\n\nSmid endelig signalpistolen... den bliver sikkert ikke noget værd for dig længere alligevel, og jeg har allerede fået en ny."},
  [3450] = {n="Et Nemt Afhentning", l="Tal med Xiggs Lunteantænder i Jernsmede.", d="Jeg vil have aftrykkene leveret til mit tårn, men du behøver ikke tage hele vejen derhen. Jeg lader dem bare hente ud af Azshara med luftfragt.\n\nXiggs Lunteantænder skylder mig en tjeneste eller to og vil være i området snart -- han har meldt sig til at patruljere kysten. Tal med ham, før du tager afsted. Han kan give dig en signalpistol at signalere til ham med. Når du har aftrykkene, skal du bare tage hen, hvor han siger, og så give dem til ham, så han kan få dem sikkert til mit tårn. Han burde være i hangaren i Militærværnet.", c="Hvad kan jeg gøre for dig, <Name>? Lidt travlt lige nu med at gøre mit skib klar til en lang rejse. Jeg kom lige over for at se nogle af tankpiloterne -- jeg har brug for nogle wendigo-manker til at beklæde mit cockpit, og de har som regel ekstra.\n\nJeg kan give dig et minut, hvis du er kortfattet... en af drengene er lige fløjet til Stålgrillens Depot for at se, om pilotene dér har ekstra manker til mig."},
  [3451] = {n="Signal til Afhentning", l="Tal med Xiggs Lunteantænder og få en Standardudstyrs-signalpistol af ham i Jernsmede.", d="Ah, så Tymer sendte dig, hva'? Ja, jeg skylder ham en tjeneste eller to. Hvad siger du? Hvorfor, den lille djævel. Ja, jeg kan hjælpe ham med det. Så du skal bruge en signalpistol og en lokation... let nok.\n\nDer er en lille ø ud for den sydlige halvø i Azshara, hvor vi har lavet en landingsplads. Du tager denne signalpistol og bruger den der. Jeg vil se dit signal og komme forbi for at hente det her... hvad det nu er, han vil have.", c="Her er min standardudstyrs-signalpistol, og vær tålmodig, efter du har affyret pistolen -- der er kun et par ladninger i en af disse, og det kan tage mig et minut at nå frem, afhængigt af hvor langt ude på havet jeg er. Kig bare ud mod havet, efter du har affyret signalet."},
  [3452] = {n="Flammens Hylster", l="Find og bring et Ragnarøs-symbol til Kalaran Vindklinge.", d="Vi mangler ét sidste stykke for at danne fakklen.\n\nI bjergene mod nordvest finder du en stor lejr for Tusmørkets Hammer. Det siges, at de bærer symboler og afguder, der hylder deres gud. Disse symboler og afguder kan have tilstrækkelig fortryllelse til at danne et magisk hylster. Bring mig et enkelt Ragnarøs-symbol, så forsøger jeg at udvinde magien fra genstanden for at skabe hylsteret.", p="Uden en passende kilde til arkan energi kan Gengældelsens Fakkel ikke fuldføres.", c="Symbolet udstråler ond magi; perfekt egnet til vores opgave."},
  [3453] = {n="Gengældelsens Fakkel", l="Vent, til Kalaran Vindklinge har fuldført Gengældelsens Fakkel.", d="Giv mig et øjeblik til at kombinere stykkerne og anvende de nødvendige fortryllelser.", p="Afbryd ikke kanaliseringsprocessen.", c="Der er én sidste opgave, du skal udføre."},
  [3454] = {n="Gengældelsens Fakkel", l="Tag Gengældelsens Fakkel.", d="Fakklen skal nu bindes til sin ejer. Tag fakklen, <Name>.", c="Du griber fakklen med begge hænder; bølger af had og vrede pulserer gennem dit væsen."},
  [3461] = {n="Returner til Tymer", l="Returner Tymers Tegnesæt til ham i Jernsmede.", d="Tymer gav mig ikke noget at betale dig med, så jeg foreslår, at du tager det op med ham, når du er tilbage i Jernsmede. Jeg er sikker på, at han stadig står på sin plads i den Mystiske Afdeling. Bare gå hen og bank på, og sørg for, at han betaler dig godt. Det her sted er ingen børnelege... det er sikkert.\n\nTak igen, fordi du hjalp ham, og held og lykke.\n\nÅh, og jeg har ikke brug for tegnesættet. Hvorfor tager du det ikke bare med tilbage til Tymer, når du går hen for at se ham?", p="Du er tilbage! Fremragende. Har du også mit tegnesæt?", c="Vidunderligt! Jeg er så glad for at høre det.\n\nJeg glæder mig virkelig til at komme op i mit tårn og gennemgå de gnidningsbilleder. Jeg er så misundelig på dig... at du skal til et sted som Azsyra. Det er vel enhver elev af det arkane's drøm, må jeg gætte.\n\nTja, vi talte aldrig om nogen form for belønning, da du jo kun arbejdede for Opdagelsesrejsendes Liga, men du fortjener noget."},
  [3462] = {n="Væbner Maltrække", l="Tal med Væbner Maltrække.", d="Tal med min udsending, Væbner Maltrække. Han vil instruere dig yderligere i brugen af Hævnens Fakkel.", c="Er du klar til at slå til?"},
  [3463] = {n="Sæt Dem i Brand!", l="Sæt Nord-, Syd-, Øst- og Vest-vagttårnene i brand ved at bruge Hævnens Fakkel inde i hver af bygningerne.", d="Lyt godt efter, <Name>. Selvom de fire tårne aldrig kan ødelægges, kan du bruge hævnens fakkel til at sætte dem i brand i meget lang tid: En ild, som intet element eller nogen kraft kan dæmpe.\n\nMens de står i brand, kan ingen vagt eller vagtenhed beboe udkigsposterne, og derfor er deres første forsvarslinje ugyldiggjort.\n\nDu skal gå ind i hvert tårn og bruge Hævnens Fakkel inde i deres befæstninger. Pas på Mørkjernsdværgenes elite-vagtenheder, <Name>.", p="Er du faret vild, <Name>?", c="Det er herligt! Er det ikke herligt, herre?"},
  [3481] = {n="Småting...", l="Åbn kisten.", d="Kisten virker låst.", c="Kisten åbner sig ved din berøring. Hvor meget ost kan der mon være i den her? Der er kun én måde at finde ud af det på."},
  [3501] = {n="Alt Tæller i Store Mængder", l="Bring Kumishas ufuldkomne Draenetyst-fragmenter og bliv belønnet for hvert et, du afleverer.", d="Selvom du måske aldrig finder en fejlfri kugle af draenetyst, vil du uden tvivl opdage forskellige ufuldkomne fragmenter af draenetysten under din udforskning af disse lande.\n\nSelvom det er tvivlsomt, at Kumisha vil kunne bruge de fejlbehæftede fragmenter til at vende hjem, kan stykkerne måske tjene andre nyttige formål for draeneierne.\n\nAflever alle stykker af fejlbehæftede draenetystfragmenter, du måtte finde, så belønner jeg dig.", p="Har du haft held i din udforskning?", c="Du får mig virkelig til at væmmes, <Race>. En voksen mand, der sluber over en bunke skrot? Patetisk! Tag din belønning og forsvind mig af syne."},
  [3504] = {n="Forrådt", l="Lever det forseglede brev til Ag'tor til Ag'tor Blodnæve i Azsyra.", d="Forræderisk, tyvagtig kvinde! Det er, hvad jeg kalder hende--det er alt, hun nogensinde bliver!\n\nJeg har måske begået en alvorlig fejl, <Name>. Jeg stolede på en blodalf. Det værste er, at jeg stolede på en kvinde!\n\nHun påstod, at Azsyra ville rumme store rigdomme... kraftfulde genstande. Jeg sendte simpelthen nogle krigere med hende for at beskytte hende, så ville jeg blive belønnet. Nå, se hvem der er narren--hun har dræbt dem alle.\n\nJeg vil have hævn, <Name>, men jeg har ikke råd til at sende nogen andre. Find Ag'tor ved Valormokk, nord for Haldarr-lejren. Han vil fortælle dig mere.", p="Ah, Belgrom blev endelig klog og sendte nogen, der ikke var i hans rækker, for at hjælpe os, gjorde han?\n\nDenne lejr plejede at have et dusin krigere, <Name>, men nu er de alle døde. Den magiker, Rimtorri, har slagtet dem alle. Hun spillede Belgrom som en lut... forførte ham endda. Det er ikke min sag, men mellem os: hun er en ret fristerinde. Det er nok derfor, jeg stadig er herude og hjælper Belgrom--jeg ville nok have gjort det samme.", c="Vi har sendt alt, hvad vi havde, mod hende og hendes arbejdere, men de er stærke i kamp. Ingen har gidet vende tilbage. Jeg går ud fra, at nogle er døde, men jeg er sikker på, at andre bare flygtede... kujoner.\n\nMen nu hvor forstærkningerne er ankommet, er der måske stadig noget, vi kan gøre. Måske kan vi stadig straffe hende for at lyve og forråde Belgrom.\n\nHvad siger du, er du med?"},
  [3505] = {n="Forrådt", l="Dræb 10 Blodalf-genvindere og 10 Blodalf-landmålere, før du søger efter Magus Rimtorris lejr. Når du har fundet den, så led efter noget, der kan være vigtigt for hende, og som kan bruges til at lokke hende ind i en kamp.", d="Det troede jeg nok.\n\nVi starter vores korstog mod hendes arbejdere langs de sydlige skrænter på den nordlige halvø i Azsyra. Dræb dem med blodig raseri--lad dem vide, at de har forrådt de forkerte allierede.\n\nBekymr dig ikke om hende endnu--hun bruger det meste af sin tid med sine livvagter på at lede efter Azsyra. Det vil være klogt, når du har slået hendes arbejdere ihjel, at finde hendes personlige lejr. Det vil være klogt at undersøge, hvor vi kan angribe hende. Måske er der noget derinde, vi kan bruge til at provokere hende.", p="Titlen på bogen er præget med guldblad på det sorte læderomslag--Kaldorisk Besværgelsesbog. Når du slår siderne op, kan du se, at bogen er meget gammel, men i fremragende stand.\n\nDu går ud fra, at teksten er på et gammelt sprog... måske kaldorisk?\n\nDin intuition siger dig, at du bør vende tilbage hertil, når du er færdig med at uddele hævn over blodalferne for deres forræderi.", c="Du begynder at blade i nogle af siderne, indtil du når en side, der er markeret med en tynd, sort silkestrimmel.\n\nMens du forsøger at tyde skriften, ser du et diagram nederst på en af siderne. Et hurtigt blik rundt om scenen foran dig, og du indser, at krystallerne, cirklen og endda nogle af de andre dele på jorden er sat op i et mønster, der ligner diagrammet."},
  [3506] = {n="Forrådt", l="Ødelæg den arkane fokuseringskrystal, der er bundet til Magus Rimtorri, og dræb hende derefter. Tag derefter Magus Rimtorris hoved med til Ag'tor Blodnæve i Azsyra.", d="Et par flere øjeblikke med eftertanke bringer nogle idéer frem, hvoraf den ene får dig til at smile: Måske ville det gøre blodalfen, der er ansvarlig for slagtningen af så mange orker og forræderiet mod Belgrom, rasende, hvis krystallerne blev ødelagt?\n\nDu fortsætter med at tyde mere af skriften og billederne og indser, at en af krystallerne er bundet til cirklens skaber--de andre er bundet til noget langt mere ondskabsfuldt.\n\nDu lukker bogen og begynder at beslutte, hvilken krystal der skal ødelægges.", p="Hvordan går det med din slagtning af blodalf-forræderne, <Name>? Har du gjort nogen fremskridt?\n\nJeg håber, at du er den, der er stærk nok til at tvinge det hunde på knæ! Hun fortjener intet andet end en smertefuld død for alt, hvad hun har gjort!", c="RAR!! Utroligt!\n\nDet er lykkedes dig! Belgrom vil være glad! Endelig kan ånderne fra dusinvis af vores krigere få fred. Tak, <Name>."},
  [3507] = {n="Forrådt", l="Tal med Belgrom Klippeknokler i Orgrimgrad.", d="Vend tilbage til Belgrom i Orgrimgrad. Han vil selv se hendes hoved! Vi vender snart tilbage dertil.\n\nAh, dette er virkelig en god dag. Tak for din hjælp, <Name>.", p="Jeg husker dig, <Class>. Jeg bad dig tage til Azsyra for at tilintetgøre den kvinde, der forrådte mig! Det virker, som om det er mange måneder siden. Fortæl mig ikke, at Ag'tor og de andre også er døde!", c="HAHA! Se på dig nu, patetiske kvinde! Jeg spytter på dine rester!\n\nTak, <Name>. Tak fra bunden af mit hjerte! Dette er virkelig en stor dag!\n\nJeg ville give dig et kongerige, hvis det stod i min magt! Men måske vil du nøjes med dette.\n\n<Belgrom kigger ned på hovedet af magikeren, som havde forrådt ham.>\n\nHaha! Dumme blodalf, se på dig nu... i en jutesæk og uden krop! Du skulle aldrig have forrådt Belgrom!"},
  [3508] = {n="Brydning af Beskyttelsen", l="Vent på, at Lorumus fuldfører oplysningsbesværgelsen.", d="Du er dumdristig, <Name>. Det er en beundringsværdig egenskab hos dit folk--at gå blindt ind i kamp, når du har ringe eller ingen chance for succes. Jeg vil hjælpe dig, bare for at se en af Razelikhs håndlangere falde.\n\nFor at bryde beskyttelsen, der er lagt over Razelikhs undergivne, vil det tage tid og kræve anskaffelse af sjældne artefakter.\n\nVær stille, jeg må først udføre oplysningsritualet. Den information, jeg indsamler, vil hjælpe mig med at smede våben med stor kraft.", c="Udyrets navn må findes."},
  [3509] = {n="Udyrets Navn", l="Tal med Lord Arkkorok i Azsyra. Begynd din søgen ved vandkanten for at finde Arkkorok-templet.", d="Der er kun én måde at skade dæmonherren og hans håndlangere på. Et kraftfuldt våben må smedes, der bærer hans sande navn.\n\nNår et sådant våben er smedet, er dæmonen og alle under hans kommando sårbare.\n\nEn mindre gud bor i Azsyra: Lord Arkkorok. Du må søge ham, men vær advaret: hans håndlangere vil ikke stoppe ved noget for at ødelægge dig, hvis du bliver opdaget.\n\nUtvivlsomt vil du være nødt til at betale en pris for sådanne oplysninger.", c="En dæmonherre?\n\n<Lord Arkkorok ler.>\n\nMåske kan den ene hjælpe dig med denne information; men først må du hjælpe den ene."},
  [3510] = {n="Udyrets Navn", l="Dræb Hetæra og bring Hetæras Blodige Hoved, Hetæras Tæskede Hoved og Hetæras Blåmærkede Hoved tilbage til Lord Arkkorok.", d="Hun dræber mine børn, dødelige. Hun, der kalder sig oceanernes hersker. En falsk gud, ikke mere. Knus hende og bring alle hendes hoveder tilbage.\n\nFor det vil du få det navn, du søger, og noget andet af lige så stor betydning.\n\nHun hærger klyngen... Hetæra kaldes hun.\n\n<Lord Arkkorok peger mod sydvest.>\n\nAf sted!", p="<Lord Arkkorok bøjer sig ned for at inspicere dig.>\n\nHvor er de?", c="Endelig én, der er værdig Arkkoroks visdom!"},
  [3511] = {n="Udyrets Navn", l="Tag hærdevæsken tilbage til Loramus Thalipedes.", d="Som lovet vil jeg afsløre navnet på dæmonherren, Razelikh Skænderen. Først må jeg dog forberede noget af yderste vigtighed til din rejse.\n\nDet våben, du søger at skabe, kræver en hærdevæske. Giv mig et øjeblik til at tømme blodet fra disse hoveder.\n\n<Lord Arkkorok klemmer hovederne mellem sine gigantiske næver og tapper dem for blod.>\n\nTag hærdevæsken tilbage til Loramus sammen med udyrets navn: Rakh'lig.", p="Du er tilbage! Forbløffende, <Race>. Opdagede du det sande navn?", c="Hærdevæsken vil tilføje den ætsevæske, vi har brug for til smedningen af våbnene. Der er kun ét trin tilbage i deres fremstilling."},
  [3512] = {n="Med Eranikas' Egne Ord", l="Rejs til den østlige del af Vinterkilden og tal med Umbrans Åndetaler.", d="<Name>, vores første skridt vil være at finde en metode til at tale med Eranikas gennem ædelstenen. Han befinder sig nu i en farlig tilstand mellem søvn og død, snoet ind i et væv af mareridt. Selvom essensen, du har givet mig, er stærkt forurenet, er der en chance for, at vi kan nå ham.\n\nRejs langt til de isede lande i det østlige Vinterkilden og søg en af vores dødelige allierede, Umbrans Åndetaler. Han er en menneskelig medium, der taler for de døde. Selvom Eranikas ikke er død i ægte forstand, kan han stadig være til hjælp for os.", c="Itharius var klog, da han sendte dig til mig. Selvom han ikke er død, som du forstår død, vil Eranikas snart give os råd med sine egne ord. Men lige nu kan jeg ikke direkte hjælpe dig... i hvert fald ikke endnu.\n\nJeg vil lære dig min færdighed i dødstale, men først har jeg brug for hjælp fra én, der--i modsætning til mig--ikke er begrænset af alderdommens skrøbeligheder. Mit kraftfuldeste varselsapparat er blevet taget fra mig imod min vilje, og medmindre jeg får det tilbage, står vi uden midler til at hjælpe Eranikas."},
  [3517] = {n="Stjæler Viden", l="Find Bet'Amaras Tavle, Jyn'yaels Tavle, Markris Tavle og Sel'hais Tavle, før du vender tilbage til Jedika i Azsyra.", d="Jeg indrømmer, <Name>, at jeg har gjort det bedste ud af min situation i Azsyra. Belgroms straf har haft sine fordele.\n\nFør jeg forlod stedet, foretog jeg lidt research, og du ville blive overrasket over, hvor mange værdifulde genstande der ligger og flyder rundt.\n\nJeg vil fortælle dig mere om mine handler og endda give dig en del af overskuddet, hvis du hjælper mig med at samle nogle af dem.\n\nDer er tavler over hele Eldarath-ruinerne mod øst, som jeg har brug for. Alle fire er opkaldt efter Højfødte magikere. Find dem til mig, så taler vi videre.", p="Tavlerne, jeg får dig til at samle, burde indbringe et pænt beløb til de rette parter. Jeg fortæller dig, hvem vi skal levere dem til, når du har fundet dem. Men jeg er ingen dåre... du får din andel, når jeg har bevis for, at de er leveret.\n\nSå kom i gang--vi har ikke hele dagen. Jeg må måske finde en anden til at hjælpe mig.", c="Perfekt, <Name>, og også i god stand. Disse burde skaffe os en god pris fra alle de involverede parter.\n\nLad os ikke dovne rundt her længere end nødvendigt. Vi har nogle penge at tjene."},
  [3518] = {n="Levering til Magata", l="Bring Bet'Amaras Tavle til Magata i Tordenklippe.", d="Den første tavle går til en taurenkvinde... en der hedder Magata. Hun er blandt de ældste i Tordenklippe og er en af fortalerne for alliancen mellem taurenerne og De Forladte. Mere end nogen anden blandt de ældste mener hun, at taurenerne og deres måder kan hjælpe De Forladte med at finde vejen tilbage til at være mennesker.\n\nBring hende Bet'Amaras Tavle. Tavlen kan være det led, hun behøver for at finde en måde at hjælpe De Forladte på... eller det påstår hun i hvert fald.", p="Ja, <Name>. Hvad kan jeg gøre for dig? Jeg har mange sager, jeg må tage mig af, så vær venlig at være hurtig.", c="Ah, endelig, Bet'Amaras Tavle. Jeg undrede mig over, om mit samarbejde med Jedika var mislykkedes, eller om den stakkels orkinde var død i Azsyra. Jeg er glad for, at hun lykkedes.\n\nBet'Amara var en af de Højfødtes mest indflydelsesrige alkymister. Det siges, at magikeren alene havde mestret transmutation af metaller blandt andre ting."},
  [3519] = {n="En Ven i Nød", l="Tal med Dirania Sølvglans i Skyggedalen.", d="Åhh... Jeg blev bidt meget slemt af en edderkop ved navn Githyiss den Usle, mens jeg udforskede edderkoppehulen meget tæt på her. Jeg er sikker på, at jeg er alvorligt forgiftet; du må hjælpe mig.\n\nFortæl venligst Dirania Sølvglans. Hun vil kunne hjælpe mig.\n\nSkynd dig... jeg er så svimmel...", c="Åh kære; jeg undrede mig over, hvorfor jeg ikke havde set Iverrøn endnu i dag. Og jeg har altid advaret ham om de edderkopper..."},
  [3520] = {n="Dalskrigeråndene", l="Fang ånderne fra 3 dalskrigere i Vildalas, og vend derefter tilbage til Ye'kinya i Damphjulshavn.", d="Jeg søger ånderne fra Vildalas' dalskrigere. De er fætre til en gammel, gammel gud, og deres ånder er forbundet med ham.\n\nTag denne tornekvist-stav og tag til Vildalas. Find og besejr dalskrigere i det sydlige og centrale Vildalas, og vift derefter min tornekvist over deres faldne kroppe. Det vil lokke deres ånd frem. Rør ånden og saml dens essens.\n\nVend tilbage til mig med min tornekvist og den samlede essens, så fortæller jeg dig mere om den gamle gud, jeg talte om.", p="Har du samlet essensen fra dalskrigeråndene, <Name>?", c="Du har gjort det godt, <Name>. Måske er det nu tid til at afsløre mere...\n\nDer er en gammel profeti blandt trolde, hvor den døde gud Hakar, Sjælflåeren, en dag vil vende tilbage til denne jord. Nogle siger, at Hakars komme vil bringe glæde og herlighed til trollefolket, mens andre mener, at hans genopstandelse markerer tingenes ende.\n\nJeg tror ikke på denne myte, men jeg ved, at Hakars essens rummer stor kraft, og denne kraft bør holdes væk fra dem, der ville misbruge den..."},
  [3521] = {n="Iverrøns Modgift", l="Saml 7 Hyacintsvampe, 4 Månekronliljer og 1 Vævsskov-saft til Dirania Sølvglans i Skyggedalen.", d="Vi kan måske hjælpe Iverrøn, for jeg kender en modgift, der bør hjælpe mod giften. Den kræver dog nogle ingredienser, før jeg kan lave den.\n\nJeg skal bruge Hyacintsvampe. Du kan finde dem vokse under træer, eller du kan samle dem fra grellerne sydpå herfra; de ser ud til at have taget en forkærlighed for dem. Jeg skal også bruge Månekronliljer, som kun vokser omkring vandpytter.\n\nDen sidste ingrediens er måske den sværeste. Fra de samme edderkopper, der forgiftede Iverrøn, skal du samle Vævsskov-saft.", p="Saml venligst ingredienserne, <Name>. Iverrøn har brug for vores hjælp.", c="Lov Elunie, at du har samlet disse ingredienser så hurtigt!\n\nOm et øjeblik vil jeg have modgiften klar."},
  [3522] = {n="Iverrøns Modgift", l="Bring Iverrøns Modgift til Iverrøn, før tidsgrænsen er udløbet. Iverrøn findes ved hulen mod nord.", d="Modgiften er klar, <Name>. Sørg for, at Iverrøn drikker den.\n\nDer er noget, du bør vide -- modgiften -- den forbliver kun virksom i 5 minutter. Du skal bringe den til ham i tide.\n\nMå hastigheden være med dig, <Name>.", p="Åh... <Name>, jeg er så glad for, at du er vendt tilbage.", c="Hvad er dette, <Name>?\n\nÅh, jeg vidste, at Dirania kunne hjælpe mig!\n\n<Iverrøn drikker modgiften.>\n\nJeg kommer altid i problemer, og Dirania, ja, hun plejer altid at hjælpe mig ud af dem.\n\nJeg har det meget bedre, men jeg tror, jeg vil sidde her lidt længere, indtil jeg har det helt godt. Nå, og så håbede jeg også, at du ville rydde en vej for mig gennem de onde Vævsskov-edderkopper..."},
  [3523] = {n="Svøben over Slettene", l="Hvis du accepterer at hjælpe Bælnistrasz, så tal med ham igen og giv ham Edstenen, han gav dig, tilbage.", d="Fremragende! Jeg hedder Bælnistrasz, og jeg takker dig for at redde mig. Jeg havde givet mig selv op for død... eller værre, som et måltid for disse Svøbe-plagede skadedyr. Ja - jeg sagde Svøben, helt rigtigt; de har indgået en slags aftale med Piggrisene her, og dette mareridt er resultatet.\n\nLyt... i stedet for blot at flygte, vil jeg gøre en forskel for alles skyld. Kunne du tænke dig at hjælpe mig med det? Det er sikkert farligt, men du virker til at være den type, der ikke bekymrer sig for meget om det.", p="Jeg er ikke til politik; jeg er ligeglad med, om dine tilknytninger er til Horden eller Alliancen. Jeg er mere interesseret i at knuse direkte og alvorlige trusler mod alle racer... og vi har en ret stor en herinde.\n\nHvis du er villig til at være en sand helt for alle folk, så giv mig Edstenen, jeg har givet dig som tegn på engagement. Jeg er... ikke herfra; en edsten er vigtig for folk af min slags som et bånd af enighed.", c="Fantastisk, jeg troede, du så ud til at være den heroiske type! Vi har en del arbejde foran os, <Name>, jeg vil ikke lyve for dig. Hvis vi holder fokus på opgaven, bør vi kunne komme ud på toppen.\n\nLad mig nu give dig et hurtigt overblik over, hvad der er sket..."},
  [3525] = {n="Slukning af Idolen", l="Eskortér Bælnistrasz til Piggrisenes idol i Razorfen-slettene.\n\nBeskyt Bælnistrasz, mens han udfører ritualet for at lukke idolen ned.", d="Nær indgangen står et idol, der fungerer som en makaber ovn for Piggrisene; udyrene... de fortærer bogstaveligt talt deres bortførte fra Ødemarken. Jeg kan lukke idolen ned og forhindre dem i at bruge den igen, men jeg har brug for din hjælp til det. Min plan: eskortér mig til idolen. Når vi kommer frem, begynder jeg ritualet. Jeg vil knap kunne kommunikere med dig, endsige forsvare mig selv. Beskyt mig, mens jeg lukker idolen ned. Hvis de tager mig, så er det hele forbi for os.\n\nEr du med mig?!", c="Bælnistrasz' pludselige afgang har efterladt en brændende glød. Mens du stirrer ind i flammen, fylder billedet af en stor rødvinget drage dit sind. En mere skurrende version af Bælnistrasz' stemme taler direkte til dig.\n\n\"Ja, dødelige, I er de helte, jeg håbede, I ville være. Takket være jer er slagtningen, som disse udyr begik, noget af fortiden. Min tro på dødelige som jer er endnu en gang blevet fornyet. Tag dette som en belønning, der passer til en helt.\""},
  [3526] = {n="Nisse-ingeniørarbejde", l="Hvis du ønsker at lære mere om Nisse-ingeniørarbejde, så tag Ingeniørdisciplinernes Håndbog med til Nixx Tandhjulsfjeder i Gadgetbyen.", d="Ekspert-ingeniørarbejde giver to tydelige discipliner: gnom og nisse. Det er klart, at nisse-ingeniørarbejde er alle geniale ingeniørers valg. Lær at mestre verden gennem den kloge brug af højeksplosive stoffer og fantastisk udstyr!\n\n<Name>, læs denne håndbog. Hvis du vil lære om nisse-ingeniørarbejde, så tag den med til Nixx Tandhjulsfjeder i Gadgetbyen. Husk--medlemskabet er permanent og forhindrer, at du tilslutter dig den anden disciplin, så sørg for, at det er det, du ønsker, før du fuldfører hans opgave.", p="Jeg kan lugte friske rekrutter, ligesom jeg kan lugte et fremragende sprængpulver - på en kilometers afstand. Er du kommet for at lære om mestringen af eksplosionen?", c="Nå, <Name>, du var klog nok til at søge min vejledning! Enhver tølper kan blive ekspert i ingeniørarbejdets grundprincipper - gnomerne og deres stråleforgiftede hjem Nisseborgen er bevis for det. Det kræver dog et stærkt sind og en stabil hånd (VIGTIGT: STABIL) at mestre disciplinen Nisse-ingeniørarbejde.\n\nHold ørerne spidse, <Name>, så lærer du måske noget."},
  [3527] = {n="Mosh'arus Profeti", l="Bring Mosh'arus Første og Anden Tavle til Ye'kinya i Tanaris.", d="Den gamle profeti om Mosh'aru taler om en måde at begrænse guden Hakars essens på. Den blev skrevet på to tavler og taget til trollebyen Zul'Farrak, vest for Gadgetbyen.\n\nBring mig Mosh'aru-tavlerne!\n\nDen første tavle holdes af den længe døde troll Theka Martyren. Det siges, at hans forfølgere blev forbandet til skarabæer, og nu kravler de rundt om hans helligdom.\n\nDen anden tavle holdes af hydromanceren Velrata, nær den hellige pøl Gahz'hydra.\n\nNår du har tavlerne, så bring dem til mig.", p="Har du tavlerne fra Mosh'arus Profeti, <Name>?\n\nNår jeg får tavlerne, vil jeg studere dem og lære, hvordan man begrænser Hakars essens!", c="Ah, dette er godt. Jeg kan smelte disse gamle tavler sammen og derefter studere deres skjulte hemmeligheder.\n\nMin gæld til dig vokser, <Name>. Og den vil vokse endnu mere."},
  [3528] = {n="Guden Hakar", l="Bring det Fyldte Æg fra Hakar til Ye'kinya i Tanaris.", d="Nu er det tid til at fange essensen fra Hakars avatar.\n\nTag Hakars Æg til Den Faldne Guds Helligdom i Det Sunkne Tempel i Azerot. Påkald æggets kraft for at vække den døde gud.\n\nHan vil sende sine håndlangere imod dig. Besejr hans blodsugere og tag deres Håkkari-blod, og brug derefter blodet til at slukke de evige flammer, der holder Hakars ånd fast. Når alle flammer er slukket, vil Hakars avatar træde ind i vores verden.\n\nBesejr ham, og læg hans essens i Hakars æg.", p="Har du besejret Hakars avatar, <Name>? Har hans essens endnu givet kraft til det æg, jeg gav dig?", c="Hakars essens er blevet samlet! Selv nu bevæger ægget sig med liv! Kunne Hakars myter være sande?\n\nDet må ikke være sandt, for det er da, jeg frygter, hvad Hakar kan gøre, hvis han fødes igen. Jeg vil holde dette æg sikkert og sørge for, at det ikke falder i onde hænder.\n\nDit arbejde for mig er færdigt, <Name>. Du har rørt ved en legende, og dine handlinger kan en dag ændre vores verdens ansigt."},
  [3541] = {n="Levering til Jes'rimmel", l="Bring Tavlen af Jyn'yael til Jes'rimmel i Orgrimgrad.", d="Jeg har en hæler i Orgrimgrad. Han holder til i Trækket. Han er svær at få fat i, hvis man ikke ved, hvor man skal lede, men hvis du leder i en af de højeste bygninger dernede, skulle du ikke have problemer med at finde ham.\n\nGør mig dog en tjeneste, og råb ikke ud til hele Kalimdør, at han er der, og hvad hans forretning er - det ville være skidt for os begge.\n\nHan vil give os mere end en rimelig pris for Tavlen af Jyn'yael. Jeg ved ikke hvorfor, men du skulle have set, hvor ivrig han blev, da han hørte om, hvor den befandt sig.", p="Ja, hva' er det du skal bruge, makker? Jeg har masser af ting at passe i dag, og du står ikke på min liste over dem. Plag mig, så sørger jeg for, at det ændrer sig.", c="Ahhh, Jediga sender sin pakke hele vejen fra Azsyra. Godt. Jeg har ventet på den.\n\nJediga, hun er en flot kvinde... dødbringende også. Hvad kunne være bedre?\n\nSe lige her... tavlen er i perfekt stand. Du er en god budbringer, <Name>."},
  [3542] = {n="Levering til Andron Handske", l="Bring Tavlen af Mærkri til Andron Handske i Underbyen.", d="Andron Handske er min næste kontakt. Han holder sig som regel til i Underbyen... lige ved Apotekeriet.\n\nHan var lidt mere snakkesalig, da det kom til, hvad han ville bruge tavlen til. Tilsyneladende vil nogle af magikerne i Underbyen studere nogle af de arkane besværgelser, højfødte brugte. De tror, at denne tavle vil hjælpe dem. Mærkri var dygtig til at kalde væsener frem; især elementarer.\n\nTag Tavlen af Mærkri og vend tilbage til mig for din del af belønningen.", p="Nå... <hic>... er det ikke en overraskelse? En eventyrerrrer... <hic>!\n\nHvad kan jeg gøre for dig... <hic>?", c="Her, tag nogle mønter... køb dig... <hic>... en ny rustning eller noget....\n\nDet her skal nok give et par blanke guldstykker til de rigtige... <hic> folk."},
  [3561] = {n="Levering til Ærkemager Vedsaft", l="Bring Tavlen af Sael'hæj til Ærkemager Vedsaft i Azsyra.", d="Denne sidste tavle skal til en meget farlig person, <Name>. Lyt til mig, når jeg siger, at jeg har langt mindre tillid til denne person end til nogen anden, jeg har bedt dig møde.\n\nÆrkemager Vedsaft har et tårn oppe i bakkerne med udsigt over Azsyra. Han er menneske, men han opfører sig ikke som noget menneske, jeg har mødt... eller dræbt. Han udstråler magt, og jeg tør ikke spørge ham, hvad han har planer om med tavlen.\n\nHan kom til mig, men fortalte, at hans livvagt Sanat ville hjælpe mig op til tårnet, når jeg var klar til at møde ham. Se efter Sanat mod nord.", p="Hvad kan jeg hjælpe dig med, <Name>?", c="Ah, Tavlen af Sael'hæj... hvor har jeg længe ønsket at studere den.\n\nTak, <Name>. Du kan fortælle Jediga, at hun har gjort det godt. Det her vil helt sikkert være den betaling værd, hun bad om."},
  [3562] = {n="Magathas Betaling til Jediga", l="Aflever Magathas Seddel til Jediga i Azsyra.", d="Tag denne seddel med til Jediga. Fortæl hende, at betalingen venter på hende, når hun vender tilbage. Og fortæl hende, at jeg er tilfreds med hendes arbejde.\n\nSkynd dig, <Name>. Fortæl din herre, at jeg venter hende her.", p="Nå, hvad sagde Magathe så? Den gamle heks... jeg vætter, at hun ikke var særlig høflig.", c="Ah, godt. Hun var langt mere rimelig, end jeg havde forventet... i hvert fald over for dig. Jeg regnede halvt med, at hun ville få dig straffet for min frækhed ved at sende en anden i mit sted. Hun må virkelig ville have den tavle. Interessant.\n\nNoget at grubler over en anden gang."},
  [3563] = {n="Jes'rimmels Betaling til Jediga", l="Aflever Jes'rimmels Seddel til Jediga i Azsyra.", d="Tag dette brev med til Jediga. Lad hende vide, at vores aftale har været til gavn, og at jeg er tilfreds med hendes arbejde.\n\nFortæl hende, at hun skal vende hurtigt tilbage til Orgrimgrad, og at Jes'rimmel nok skal sørge for at passe godt på hende.\n\nFortæl hende det, og måske får jeg brug for dine tjenester igen i fremtiden, <Name>.", p="Har du talt med Jes'rimmel endnu?\n\nHan er et vildsvin blandt trolde, men hans informationer er som regel præcise, og hans jobs betaler godt.\n\nKan du holde ud med hans attitude, kan du tjene nogle gode penge på hans forretningsforetagender.", c="Jeg kan se, at han var mere end tilfreds, døm selv efter hans seddel.... lidt for tilfreds.\n\nMåske finder jeg en dag tid til at sørge for, at han ved, hvor meget jeg også sætter pris på hans tilnærmelser. Nå, i hvert fald er der én grund til at glæde sig til at bruge mere tid i Azsyra.\n\nHer er din andel af vores betaling."},
  [3564] = {n="Androns Betaling til Jediga", l="Aflever Androns Seddel til Jediga i Azsyra.", d="Her... tag... <hic> dette til Jediga. Held og lykke til dig!", p="Har du mødt Andron endnu? Han forlader sjældent Underbyen, så jeg tror ikke, det bliver svært at finde ham.", c="Perfekt... vent lidt.\n\nHa! Hvad sagde du til ham, da du afleverede tavlen, <Name>? Han betalte alt for meget! Ikke at jeg klager. Fortalte du ham, at aftalen var ændret? Eller var han fuld igen?\n\nDet gør ikke noget... her, tag også en ekstra andel."},
  [3565] = {n="Vedsafts Betaling til Jediga", l="Aflever Vedsafts Seddel til Jediga i Azsyra.", d="Hvad er det? Å ja, din betaling. Selvfølgelig.\n\nTag den her og skrid. Jeg er sikker på, at Jediga venter så tålmodigt på din tilbagekomst.", p="Nå, hvad havde Vedsaft at sige? Han gjorde vel ikke noget ved dig? Støbte en besværgelse over dig? Overtalte dig til at arbejde for ham?", c="Ingen problemer? Slet ingen? Nå, det må man sige... jeg havde regnet med, at han ville vise en eller anden modvilje eller i hvert fald svige vores aftale. Hmm, måske kan han alligevel stoles på.\n\nNå, der er ingen grund til at dvæle for meget over det. Her er din andel. Tak for din hjælp."},
  [3566] = {n="Rejs dig, Obsidiøn!", l="Dræb Lathorik den Sorte og Obsidiøn, og vend tilbage til Tornius i Jernsmede med Lathoriks hoved og Obsidiøns hjerte.", d="Det... Det... Det var en fælde.\n\nTilgiv... mig.\n\nDræb svinet... Dræb ham for os... for Tornius.", p="Jeg tror dig ikke! Vis mig beviser!", c="<Tornius' ansigt bliver hvidt.>\n\nDet... det kan ikke være sandt. Min egen bror? Han har planlagt det hele?\n\n<Tornius' ansigt forvrides af vrede.>\n\nHan har forrådt mig, han har forrådt Jernsmede! Det ser ud til, at De Gamle Guders indflydelse stadig er stærk i disse lande. Jeg frygter, at hvis min bror - en engang ædel og ærefuld mand - så let kunne vendes til Ragnarøs' vilje, er ingen i sikkerhed."},
  [3568] = {n="Sivende Fordærvelse", l="Fyld alle 4 Tomme Hætteglas ved tidevandspytterne langs kysten af Ruinerne af Eldarath i Azsyra, før du vender tilbage til Kemiker Cuelig.", d="Se den tauren bag mig - hende der ser ud, som om hun når at blive syg når som helst? Hun var i Azsyra for nylig. Hun påstår, at hun blev såret af nogle slangefolk, da hun kæmpede sig gennem Ruinerne af Eldarath.\n\nEfter at have slået nogle af dem ned, tog hun en pause på stranden og drak af en af tidevandspytterne. Nu føler hun sig kvalm... blandt andet.\n\nJeg vil gerne finde ud af, hvad hun drak. Tag denne kasse, i den er nogle tomme hætteglas, som jeg har mærket. Fyld hvert af dem ved forskellige pytter og kom tilbage.", p="Du ved nok, hvor det her fører hen, <Name>? Der er ingen måde, hun kan overleve... se på hende. Det bedste, hun kan gøre nu, er at hjælpe os med at finde en kur mod pesten. Vandet, hun drak, har måske en ledetråd, der kan hjælpe os med at finde ud af hvordan. Hun dør alligevel - hun kan lige så godt dø og gøre noget ædelt for vores folk, før hun gør det. Er du ikke enig?", c="Vidunderligt. Du er tilbage, før hun døde. Godt, godt.\n\nLad os så gå i gang med det her, skal vi?\n\nJeg har studeret hendes symptomer i nogen tid nu, og det er ret grimt. Jeg er overrasket over, at hun stadig står op. Hun har kastet op tre eller fire gange over det hele... en ret behagelig lugt.\n\nGiv mig et øjeblik til at samle noget, vi kan teste på vores... ven."},
  [3569] = {n="Sivende Fordærvelse", l="Giv Cueligs Eliksir til Thersa Vindsang i Underbyen.", d="Giv dette til Thersa. Måske kurerer det hende... måske ikke. Vi får først at vide det, når hun har drukket det.", p="Jeg er kommet til Underbyen, fordi jeg hørte, at deres alkymister har studeret længe og hårdt for at finde en kur mod deres egen sygdom. Det blev foreslået, at de måske også kunne hjælpe mig.\n\nSelvom dette sted får mig til at føle mig langt fra velkommen, havde jeg intet valg - sygdommen, der fandt mig, river mig op indefra, og jeg havde brug for deres hjælp med det samme.", c="Kemiker Cuelig har været meget imødekommende... foruroligende så. Men hvis han siger, at det her vil hjælpe mig, har jeg intet andet valg. Jeg har ikke tid til at finde nogen anden løsning. Jeg har allerede talt med præster og shamanner, og ingen af dem kunne hjælpe.\n\nLad os håbe, at Jordmoderen vogter over min ånd."},
  [3570] = {n="Sivende Fordærvelse", c="Jeg havde aldrig drømt om, at eliksiret ville virke så hurtigt. Tak, <Name>. Jeg går straks i gang med resten af prøverne. Jeg er sikker på, at Frue Silvanas og De Forladte snart kan bruge dem."},
  [3601] = {n="Kim'jæl, sandelig!", l="Søg i Thalassiansk Basislejr efter Kim'jæls Kompas, Sigte, Stoppet Kylling og Vrisselpuddeg, og bring dem tilbage til ham i Azsyra.", d="Kim'jæl, sandelig!! Ved du, hvad Kim'jæl betyder for blodalferne, <Name>? Lille rotte... eller noget i den stil. De store mobbere!\n\nDe hyrede mig til at hjælpe dem med at spejde området efter nogle slags tabte skatte. Selvfølgelig hoppede jeg med ombord, så snart de sagde \"skat\", og beløbet de var villige til at betale, men naturligvis vendte de sig mod mig og prøvede at dræbe mig... MIG!\n\nDet viser dig, at man ikke kan stole på en blodalv.\n\nProblemet er, at de stadig har mit udstyr, og jeg kan ikke få det tilbage. Vil du hjælpe mig?", p="De stinkende blodalfer. Jeg siger dig, hvis jeg var lige så stærk som dig, ville jeg selv gå derned og lære dem et par ting! Men jeg må nøjes med at betale dig for at tage dem for mig.", c="Haha! Du fik dem godt, ikke?!\n\nDet er fantastisk! Det lærer blodalferne at forråde deres partnere... især en så loyal som en nisse-købmand! Bah, blodalfer...!\n\nNå, det mindste, jeg kan gøre for dig, er at betale dig for din tid... ligesom jeg sagde, at jeg ville.\n\nSå værsgo... de burde være nyttige."},
  [3602] = {n="Azsharstål", l="Hent tyve Krystalliseret Azsharstål fra det sydlige Azsyra. Du må bruge Ondhunden til at hjælpe dig med at 'snuse' dig frem til de snedigt skjulte aflejringer.\n\nVend tilbage til Lorumus, når opgaven er løst.", d="De gamle klippejætter i Azsyras sydlige region æder klippen og bygningerne i landet for at overleve. Afføringen fra deres fordøjelse er et meget formbart og ekstremt stærkt krystal kendt som Azsharstål.\n\nFormationerne ligger spredt over den sydlige bue, men få bliver nogensinde hentet på grund af klippejætternes ekstremt voldelige natur.\n\nDu skal begive dig sydpå og hente nok Azsharstål til at lave våbnets krop. Mine ondhunde vil hjælpe med at finde krystallen.", p="Ondskaben sover aldrig, tosse. Du får tid til hvile, når du endelig er død. Nu, bring mig de krystaller.", c="Dine opgaver i Azsyra er fuldført, dødelige. Jeg må nu smede de nødvendige komponenter til næste trin i dit eventyr."},
  [3621] = {n="Dannelsen af Dæmonbane", l="Tag Forsendelsen til Galvan den Gamle i Kvælertjørns Dal.", d="Våbnene er klar til at blive smedet. Du skal tage det hærdede azsharstål til en, der kan udnytte ond energi.\n\nI Kvælertjørns Dal findes sådan en smed. Galvan den Gamle, leder af Mithril-orden, vil smede våbnene efter dine specifikationer. Du finder hans lejr mellem Zul'Gurrub og Mosh'Ogg-ogervolden.\n\nMåtte din beslutsomhed og tro bære dig gennem denne prøvelse. Skulle du fejle, så vid, at din gud smiler ned til dig, dødelige.", p="Lorumus, hva'? Det er mange år siden, jeg har hørt det navn.", c="Hold da op, jeg kan kun forestille mig, hvad du har været igennem for at skaffe disse materialer. Få vender levende tilbage fra Azsyra, endsige dem der møder halvguder og klippejætter!"},
  [3625] = {n="Fortryllede Azsharstål-Ondvåben", l="Vent på at Galvan bliver færdig med at smede våbnene.", d="<Name>, det tager noget tid at smede hvert våben.\n\nDesuden kan du kun bruge Fel-forbandelsens kraft én gang hvert tredje minut. Dens svækkende egenskaber over for Razelikh Skænderen og hans håndlangere kan variere i varighed. Derfor skal du kun slippe Fel-forbandelsen løs, når øjeblikket er rigtigt!\n\nNu, giv mig et øjeblik til at smede dit våben, <Name>.", p="At afbryde smedningen kan resultere i et ufuldkomment våben. Vær tålmodig, <Name>.", c="<Galvan tørrer sveden af panden.>\n\nEn bedre dæmonslagter har aldrig eksisteret, <Name>."},
  [3626] = {n="Tilbage til Det Sønderrevne Land", l="Vend tilbage til Den Faldne Helt af Horden.", d="Forløsningens time er nær, <Name>. Du skal vende tilbage til Det Sønderrevne Land med dine nye våben og tale med Den Faldne Helt af Horden for at modtage dit sidste mål.", c="Du ser hærdet ud, <Name>. Er du klar til at møde Razelikh og hans håndlangere?"},
  [3627] = {n="Forening af den Splintrede Amulet", l="Dræb Grol Ødelæggeren, Frue Sjælefald og Ærkemager Allistarj. Tag Amuletten af Grol, Amuletten af Sjælefald og Amuletten af Allistarj fra deres lig.\n\nHusk at BRUGE dine Fortryllede Azsharstål-Ondvåben til at svække triaden. De kan ikke dræbes på anden vis - men brug dem klogt...", d="For at nå Skænderen må du først ødelægge magttriaden og genvinde amuletstykkerne. Når du har genvundet alle tre stykker, skal du vende tilbage til mig, så giver jeg dig yderligere instruktioner.\n\nAf sted, <Name>! Til Det Sønderrevne Land! Sjælefald, Allistarj og Grol må falde!", p="De tre skal forme den ene, og den ene skal lyse vejen.", c="Amuletten af Razelikh Skænderen er igen komplet, men han fornemmer forstyrrelsen i sin kommandokæde. Han ved, du kommer efter ham..."},
  [3628] = {n="Du er Rakh'lik, dæmon", l="Dræb Razelikh Skænderen og returner Skænderens Afhugne Horn til Den Faldne Helt af Horden. Du skal også returnere Skænderens Værn, så Den Faldne Helt kan ødelægge det, så det aldrig havner i de forkerte hænder.", d="Razelikhs hule ligger på toppen af det højeste bjerg i Det Sønderrevne Land. Den eneste vej til hulen er gennem teleporteringsrunerne nær bjerget. Så længe du har amuletten, kan du frit transportere dig op til hulen. Når du når hulen, skal du fremkalde udyret. Amuletten er din nøgle, <Name>. Brug den på Skænderens Alter.\n\nHvis du besejrer Skænderen, skal du bringe hans horn tilbage. Det vil blive et symbol på håb for alle, der ser det - et bevis på, at helte findes i denne krigshærgede verden.", p="Der er intet tilbage at frygte.", c="I dag er en dag, der vil blive husket i evighed. Den dæmoniske overherre over Det Sønderrevne Land er endelig faldet!"},
  [3629] = {n="Nisse-ingeniørarbejde", l="Hvis du vil lære mere om Nisse-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Nixx Tandhjulsfjeder i Gadgetbyen.", d="Ekspertingeniørarbejde deler sig i to forskellige discipliner: gnome og nisse. Jeg gider kun nævne nisse-ingeniørarbejde, fordi jeg er en retfærdig instruktør. De kan lide at lave ting, der springer i luften, og de bryder sig sjældent om, hvad der står i vejen - heller ikke dem selv.\n\n<Name>, læs denne håndbog. Hvis du vil lære at sprænge dig selv i luften, så tag den til Nixx Tandhjulsfjeder i Gadgetbyen. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så sørg for, at det er det, du vil, før du udfører hans opgave.", p="Jeg kan lugte friske rekrutter ligesom jeg kan lugte et fremragende sprængstof på en mils afstand. Er du kommet for at lære om eksplosionens mesterskab?", c="Nå <Name>, du var klog nok til at søge min vejledning! Enhver tølper kan blive ekspert i grundlæggende ingeniørarbejde - gnomerne og deres bestrålede hjemby Nisseborgen er bevis på det. Det kræver dog et stærkt sind og en stabil hånd (understreget STABIL) at mestre disciplinen Nisse-ingeniørarbejde.\n\nHold ørerne spidse, <Name>, så lærer du måske noget."},
  [3630] = {n="Gnome-ingeniørarbejde", l="Hvis du vil lære mere om Gnome-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Lappemester Overgnist i Jernsmede.", d="Ingeniørarbejde på ekspertniveau deler sig i to discipliner: gnome og nisse. Gnome-ingeniørarbejde er langt det bedste af de to! Det handler om at konstruere vidunderlige gadgets og apparater, der gør livet bedre!\n\n<Name>, læs denne håndbog. Hvis du vil lære mere om gnome-ingeniørarbejde, så tag den håndbog til Lappemester Overgnist i Jernsmede. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så vær sikker, før du udfører hans opgave!", p="Ja, ja, hvad har du brug for i dag? Jeg har tid nok til det, for jeg gør jo ikke andet end at stå her, mens vores elskede by ligger i en sky af bestrålet død.", c="Ah, en ung ingeniør, der vil forfølge den ene, sande ingeniørdisciplin! Tilgiv min melodramatik, ven. Selvom vores situation stadig er prekær, er det altid en god dag, når en anden ingeniør svarer på den sande ingeniørkunsts kaldelse!"},
  [3631] = {n="Tilkald Ondhingst", l="Tal med Strahad Fasan i Ødemarken.", d="Hmph. Jeg siger, at du ikke er klar, men det er ikke min beslutning. Strahad mener noget andet, og det er hans beslutning at træffe... denne gang.\n\nHan ønsker at tale med dig, og hurtigt. Du finder ham stadig over Skralleby i Ødemarken, ved hans lille tårn med sine akolytter.\n\nLad være med at dovne for længe.", c="Så, du har besluttet dig for at nåde mig med din tilstedeværelse igen. Hvor venligt af dig.\n\nMine akolytter spekulerede på, om du nogensinde ville dukke op. Jeg sagde, at der ingen tvivl var. Når det gælder magt, bliver du draget ind som en møl til flammen."},
  [3632] = {n="Gnome-ingeniørarbejde", l="Hvis du vil lære mere om Gnome-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Lappemester Overgnist i Jernsmede.", d="Ingeniørarbejde på ekspertniveau deler sig i to discipliner: gnome og nisse. Gnome-ingeniørarbejde er langt det bedste af de to! Det handler om at konstruere vidunderlige gadgets og apparater, der gør livet bedre!\n\n<Name>, læs denne håndbog. Hvis du vil lære mere om gnome-ingeniørarbejde, så tag den håndbog til Lappemester Overgnist her i Jernsmede. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så vær sikker, før du udfører hans opgave!", p="Ja, ja, hvad har du brug for i dag? Jeg har tid nok til det, for jeg gør jo ikke andet end at stå her, mens vores elskede by ligger i en sky af bestrålet død.", c="Ah, en ung ingeniør, der vil forfølge den ene, sande ingeniørdisciplin! Tilgiv min melodramatik, ven. Selvom vores situation stadig er prekær, er det altid en god dag, når en anden ingeniør svarer på den sande ingeniørkunsts kaldelse!"},
  [3633] = {n="Nisse-ingeniørarbejde", l="Hvis du vil lære mere om Nisse-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Nixx Tandhjulsfjeder i Gadgetbyen.", d="Ekspertingeniørarbejde deler sig i to forskellige discipliner: gnome og nisse. Nisse-ingeniørarbejde er tydeligvis alle geniale ingeniørers valg. Lær at mestre verden gennem klog brug af højeksplosive stoffer og fantastisk udstyr!\n\n<Name>, læs denne håndbog. Hvis du vil lære om nisse-ingeniørarbejde, så tag den til Nixx Tandhjulsfjeder i Gadgetbyen. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så vær sikker på, at det er det, du vil, før du udfører hans opgave.", p="Jeg kan lugte friske rekrutter ligesom jeg kan lugte et fremragende sprængstof på en mils afstand. Er du kommet for at lære om eksplosionens mesterskab?", c="Nå <Name>, du var klog nok til at søge min vejledning! Enhver tølper kan blive ekspert i grundlæggende ingeniørarbejde - gnomerne og deres bestrålede hjemby Nisseborgen er bevis på det. Det kræver dog et stærkt sind og en stabil hånd (understreget STABIL) at mestre disciplinen Nisse-ingeniørarbejde.\n\nHold ørerne spidse, <Name>, så lærer du måske noget."},
  [3634] = {n="Gnome-ingeniørarbejde", l="Hvis du vil lære mere om Gnome-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Lappemester Overgnist i Jernsmede.", d="Ingeniørarbejde på ekspertniveau deler sig i to discipliner: gnome og nisse. Selvom jeg synes, det er spild, bør du være klar over gnome-specialiseringen. De laver ting og gadgets, der påstår at ændre verden, men som sjældent virker.\n\n<Name>, læs denne håndbog. Hvis du vil lære at lave metalbrevvægte, så tag den håndbog til Lappemester Overgnist i Jernsmede. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så vær sikker, før du udfører hans opgave!", p="Ja, ja, hvad har du brug for i dag? Jeg har tid nok til det, for jeg gør jo ikke andet end at stå her, mens vores elskede by ligger i en sky af bestrålet død.", c="Ah, en ung ingeniør, der vil forfølge den ene, sande ingeniørdisciplin! Tilgiv min melodramatik, ven. Selvom vores situation stadig er prekær, er det altid en god dag, når en anden ingeniør svarer på den sande ingeniørkunsts kaldelse!"},
  [3635] = {n="Gnome-ingeniørarbejde", l="Hvis du vil lære mere om Gnome-ingeniørarbejde, så tag Håndbogen i Ingeniørdiscipliner til Oglethorpe Uopdaget i Bytteviken.", d="Ingeniørarbejde på ekspertniveau deler sig i to discipliner: gnome og nisse. Selvom jeg synes, det er spild, bør du være klar over gnome-specialiseringen. De laver ting og gadgets, der påstår at ændre verden, men sjældent virker.\n\n<Name>, læs denne håndbog. Hvis du vil lære at lave metalbrevvægte, så tag håndbogen til Oglethorpe Uopdaget i Bytteviken. Husk - medlemskabet er permanent og forhindrer, at man går ind i den anden disciplin, så vær sikker, før du udfører hans opgave.", p="Goddag! Hvis du er kommet angående en hjemsøgende robot, der måske er smadret gennem en væg i dit hjem, så henviser jeg dig på forhånd til min advokat. Ellers, hvad kan jeg gøre for dig i dag?", c="Du er kommet for at lære om gnome-ingeniørarbejde, hva'? Nå, så er du kommet til den rette gnome. Mens den herskende fraktion i Nisseborgen måske bruger politik til at udstøde dem, de ser som en intellektuel trussel, ved de, at viden er noget, de ikke kan kontrollere.\n\nDe og jeg ved begge, at da jeg forlod Nisseborgen, mistede de en af deres største gnome-ingeniører, der stadig er i live. Hvis du er en dygtig elev, vil jeg lære dig, hvad jeg ved."},
  [3636] = {n="Bring Lyset", l="Ærkebiskop Bendictus vil have dig til at slå Amnenar Koldebringer ihjel i Tornehøjene.", d="Svøben er en vedholdende trussel mod Alliancen, noget jeg er sikker på at du kender godt. For nylig er vi stødt på nogle meget mærkelige fund, <Name>.\n\nI Ødemarken ligger et rædselsfuldt virvar af brombær kaldet Tornehøjene. Det var engang hjemsted for simple tornesvin, men nu er det blevet tydeligt, at der er indgået en pagt med Svøben, som har skabt væsener langt værre... De styres nu af liget, Amnenar Koldebringer.\n\nStil dig på Lysets side, <Name>; sæt en stopper for denne onde forening.", p="Amnenar må udryddes. Af sted, og hurtigt.", c="Tak , <Name>. Svøben vil nu tænke sig om to gange, før den forsøger at styrke sine rækker igen.\n\nMåtte Lyset velsigne dig."},
  [3637] = {n="Gnome-ingeniørarbejde", l="Hvis du vil lære mere om Gnome-ingeniørarbejde, så tag Håndbog i ingeniørdiscipliner med til Oglethorpe Uopdaget i Bytteviken.", d="Ingeniørarbejde på ekspertniveau deler sig i to discipliner: gnom og nisse. Selvom jeg synes det er spild, bør du vide noget om gnomernes specialisering. De laver genstande og gadgets, der påstår at ændre verden, men som sjældent virker.\n\n<Name>, læs denne håndbog. Hvis du vil lære at lave metalbrevvægte, så tag håndbogen med til Oglethorpe Uopdaget i Bytteviken. Husk - medlemskabet er permanent og forhindrer dig i at slutte dig til den anden disciplin, så vær sikker, før du afslutter hans opgave.", p="Hej dér! Hvis du er kommet angående en styrbar robot, der måske har smadret sig gennem en væg i dit hjem, så henviser jeg dig på forhånd til min advokat. Ellers, hvad kan jeg gøre for dig i dag?", c="Så du er kommet for at lære om gnome-ingeniørarbejde, hva'? Nå, så er du kommet til den rette gnom. Mens den herskende fraktion i Nisseborgen måske bruger politik til at ekskludere dem, de ser som en intellektuel trussel, ved de, at viden er noget, de ikke kan kontrollere.\n\nDe og jeg ved begge, at da jeg forlod Nisseborgen, mistede de en af deres største gnome-ingeniører, der stadig er i live. Hvis du er en dygtig elev, så lærer jeg dig, hvad jeg ved."},
  [3638] = {n="Tavshedens Løfte", l="Hvis du accepterer at blive nisse-ingeniør, så højreklik på Tavshedens Løfte og tal endnu en gang med Nixx Tandhjulsfjeder i Gadgetbyen.", d="Nisse-ingeniørarbejde handler om praktisk brug til høj profit og endnu højere eksplosiv kraft! Vores skemaer gør os i stand til at lave kraftige bomber og mægtige våben; håndbogen du læste dækkede dette.\n\nHåndbogen dækkede også vores gamle ed om tavshed om vores skemaer. Når du først er blevet nisse-ingeniør, er det den sag. Der er slet ingen adgang til gnome-ingeniørarbejde.\n\nHvis du stadig vil være nisse-ingeniør, så underskriv dette dokument, der lover livslang tavshed, og tal med mig igen. Tænk dig godt om, <Name>.", p="Hvis du har underskrevet dokumentet og er klar til at give det til mig, så er den sag. Du har fået at vide, at det her er en envejsrejse. Hvis du er klar, så hop om bord!", c="Velkommen om bord, nisse-ingeniør <Name>! Du får snart adgang til de mest kraftfulde ingeniørskemaer, der findes på Azerot.\n\nNu hvor du har forpligtet dig til at forfølge denne viden, er det tid til at se nærmere på dit nisse-orienterede ingeniørarbejde. Derfra hjælper vi dig med at lægge en plan, så dine nisse-ingeniørtalenter bliver maksimeret!"},
  [3639] = {n="Vis dit arbejde", l="Bring 20 Store Jern-Bombarderer, 20 Massiv Dynamit og 5 Eksplosive Får til Nixx Tandhjulsfjeder i Gadgetbyen.", d="Som din mentor vil jeg have prøver af dit arbejde. Du er en dygtig ingeniør; der er ingen tvivl om det, <Name>. Det, jeg håber at gøre, er dog at analysere dem for at finde måder at fremhæve nisse-orienterede teknikker i dine fremtidige bestræbelser. Jeg har brug for følgende: tyve store jern-bombarderer, tyve pinde massiv dynamit og fem eksplosive får - og sørg for at sikkerhederne er skarpe!\n\nAflever disse genstande til mig, så udsteder jeg dit eget Medlemskort som nisse-ingeniør; det kræves for adgang til alle nisse-ingeniørtrænere!", p="Når jeg har modtaget dine fremstillede ingeniørgenstande til min gennemgang, giver jeg dig et ægte Medlemskort som nisse-ingeniør! Så længe kortet er gyldigt, har du ubegrænset adgang til enhver nisse-ingeniørtræner hvor som helst i verden.", c="Her er dit første Medlemskort som nisse-ingeniør!\n\nDette kort har kontingentet betalt på forhånd for fjorten dage; alle kort udløber efter to ugers aktivitet. Når det sker, så betal dit næste kontingent til en hvilken som helst nisse-ingeniørtræner for at få et nyt kort; uden kortet bliver dit medlemskab midlertidigt inaktivt, og du kan ikke få adgang til nye skemaer.\n\nDette påvirker aldrig det, du allerede kender; når du først er nisse-ingeniør, så er du altid nisse-ingeniør."},
  [3640] = {n="Tavshedens Løfte", l="Hvis du accepterer at blive gnome-ingeniør, så højreklik på Tavshedens Løfte og tal endnu en gang med Tinkmester Overgnist i Jernsmede.", d="Gnome-ingeniørarbejde handler om ingeniørteori formet til at tjene vores behov! Vores skemaer gør os i stand til at lave apparater, der styrer verden omkring os; håndbogen du læste dækkede dette.\n\nHåndbogen dækkede også vores gamle ed om tavshed om vores skemaer. Når du først er blevet gnome-ingeniør, er det den sag. Der er slet ingen adgang til nisse-ingeniørarbejde.\n\nHvis du stadig vil være gnome-ingeniør, så underskriv dette dokument, der lover livslang tavshed, og tal med mig igen. Tænk dig godt om, <Name>.", p="Hvis du har underskrevet dokumentet og er klar til at give det til mig, så er den sag.\n\nDe hemmeligheder, jeg vil dele med dig, er af en sådan størrelse, at underskrivelsen af Tavshedens Løfte er helt afgørende. Jeg underskrev et, ligesom min bror og søster gnome-ingeniører. Du kommer til at slutte dig til en ganske prestigefyldt flok, Ingeniør <Name>!", c="Velkommen om bord, <Name>! Du får snart adgang til de mest avancerede ingeniørskemaer, der findes på Azerot.\n\nNu hvor du har forpligtet dig til at forfølge denne viden, er det tid til at se nærmere på dit gnome-orienterede ingeniørarbejde. Derfra hjælper vi dig med at lægge en plan, så dine gnome-ingeniørtalenter bliver maksimeret!"},
  [3641] = {n="Vis dit arbejde", l="Bring 6 Mithril-rør, et Præcist Sigte og 2 Avancerede Mål-Dumrianer til Tinkmester Overgnist i Jernsmede.", d="Som din mentor vil jeg have nogle prøver af dit arbejde. Du er en dygtig ingeniør; der er ingen tvivl om det, <Name>. Det, jeg håber at gøre, er dog at analysere dit arbejde for at finde måder at fremhæve gnome-orienterede teknikker i dine fremtidige bestræbelser. Jeg har brug for følgende prøver: seks mithril-rør, et præcist sigte og to avancerede mål-dumrianer.\n\nAflever disse genstande til mig, så udsteder jeg dit eget Medlemskort som gnome-ingeniør; det kræves for adgang til alle gnome-ingeniørtrænere!", p="Når jeg har modtaget dine fremstillede ingeniørgenstande til min gennemgang, giver jeg dig et ægte Medlemskort som gnome-ingeniør! Så længe kortet er gyldigt, har du ubegrænset adgang til enhver gnome-ingeniørtræner hvor som helst i verden.", c="Her er dit første Medlemskort som gnome-ingeniør!\n\nDette kort har kontingentet betalt på forhånd for fjorten dage; alle kort udløber efter to ugers aktivitet. Når det sker, så betal dit næste kontingent til en hvilken som helst gnome-ingeniørtræner for at få et nyt kort; uden kortet bliver dit medlemskab midlertidigt inaktivt, og du kan ikke få adgang til nye skemaer.\n\nDette påvirker aldrig det, du allerede kender; når du først er gnome-ingeniør, så er du altid gnome-ingeniør."},
  [3642] = {n="Tavshedens Løfte", l="Hvis du accepterer at blive gnome-ingeniør, så højreklik på Tavshedens Løfte og tal endnu en gang med Oglethorpe Uopdaget i Bytteviken.", d="Gnome-ingeniørarbejde handler om ingeniørteori formet til at tjene vores behov! Vores skemaer gør os i stand til at lave apparater, der styrer verden omkring os; håndbogen du læste dækkede dette.\n\nHåndbogen dækkede også vores gamle ed om tavshed om vores skemaer. Når du først er blevet gnome-ingeniør, er det den sag. Der er slet ingen adgang til nisse-ingeniørarbejde.\n\nHvis du stadig vil være gnome-ingeniør, så underskriv dette dokument, der lover livslang tavshed, og tal med mig igen. Tænk dig godt om, <Name>.", p="Hvis du har underskrevet dokumentet og er klar til at give det til mig, så er den sag.\n\nSelvom jeg måske kraftigt uenig med Nisseborgen - især den tåbe Tinkmester Overgnist - politisk set, står Tavshedens Løfte over alt andet! Du skal love at følge én vej og blive tro mod den hele dit liv.", c="Velkommen om bord, <Name>! Du får snart adgang til de mest avancerede ingeniørskemaer, der findes på Azerot.\n\nNu hvor du har forpligtet dig til at forfølge denne viden, er det tid til at se nærmere på dit gnome-orienterede ingeniørarbejde. Derfra hjælper vi dig med at lægge en plan, så dine gnome-ingeniørtalenter bliver maksimeret!"},
  [3661] = {n="Elunies Yndling?", l="Saml 15 Vildkin-fjer i Bagland til Erelas Ravhimmel i Rutteran-landsbyen.", d="Vildkin er ganske uforudsigelige væsener, <Name>. De er i stand til utrolig mildhed, men de viser ekstrem vildskab, hvis noget, de anser for vigtigt, bliver truet.\n\nDisse bæster rygtes at være skabt af Elunie, og jeg er interesseret i at finde ud af, om det virkelig er sandt.\n\nFor nylig hørte jeg om en bestand af vildkin, der lever i Bagland -- Onde, Primitive og Vilde Uglebæster. De kan findes blandt dyrelivet dér. Vil du samle nogle vildkin-fjer til mig?", p="Prøv at undgå dem, hvis du kan, <Name>. Vildkin kan misforstå din interesse som en hensigt om at skade dem...", c="Tak fordi du bragte disse til mig, <Name>.\n\nHvad lærte du om Vildkin?\n\nMåske vil disse fjer fortælle os mere. Voldsomme monstre, eller blot vildledte kæledyr? En dag vil jeg gerne vide sandheden...\n\nJeg vil fortsætte min forskning -- kom venligst tilbage og tal med mig igen, når noget tid er gået."},
  [3681] = {n="Tomo om Guddommelighed", l="Tal med Dutorian Ralle i Stormvind.", d="Undskyld, at jeg forstyrrer din rejse, <Race>, men jeg tænkte, at du burde vide, at der for nylig er sendt bud fra Stormvind om, at paladiner skal melde sig dér for træning.\n\nHvis jeg ikke vidste bedre, ville jeg sige, at du nærmer dig en særlig tid, og det er på tide, at du begynder at studere Tomoerne.\n\nSe efter Dutorian Ralle i Stormvind. Han plejer at træne paladiner i Lysets Katedral.", c="Velkommen til Lysets Katedral, <Class>."},
  [3701] = {n="Tårissans Udbrændte Ruinerne", l="Begiv dig til Ruinerne af Tårissan i Brændende Stepper og indsaml oplysninger fra Tårissans Relikvier. Vend tilbage til Kongelig Historiker Arkesonus, når du har indsamlet oplysningerne.", d="Begiv dig til de ulmende ruiner af Tårissan i Brændende Stepper og indsaml så meget information, du kan.\n\nDet siges, at mystiske relikvier ligger spredt i ruinerne. Måske skulle du starte din søgning der, <Name>. Pas på Tårissans vogtere: Attentatmænd, der vogter ruinerne og holder de hemmeligheder, der måske stadig er begravet der, beskyttet.", p="Har du nye oplysninger med?", c="Åh, min! Denne information forklarer ganske meget om Tårissan.\n\nDer er meget mere at lære!"},
  [3702] = {n="Tårissans Udbrændte Ruinerne", l="Lyt til Kongelig Historiker Arkesonus fortælle om Tårissans historie.", d="Vil du gerne høre en kort historie om Mørkejern-dværgene?", p="Lad mig få lov at færdiggøre fortællingen om Tårissan.", c="Skal vi fortsætte?"},
  [3721] = {n="En OOX af din egen", c="Du har genfundet tre af mine OOX-styrbare robotter! Du har gjort mere, end du behøvede, så jeg giver dig noget specielt for al din hjælp. Det er en miniatureversion af den nøjagtig samme robot, som du er kommet til at kende og elske, OOX'en!\n\nJeg ville normalt aldrig lade nogen have sådan en potentielt dødbringende enhed, men du har været en virkelig hjælp. Desuden - kampmekanismerne og styrbar-logikken på denne er blevet deaktiveret.\n\nUd over det, så er det en OOX, for pokker da!"},
  [3761] = {n="Un'Goro-jord", l="Bring 20 prøver af Un'Goro-jord til Gede på Ældrehøjen i Tordenklippe.", d="Jorden i Un'Goro-krateret er angiveligt beriget med stærke magiske egenskaber. Cenarion-kredsen vil gerne studere denne jord i store mængder; begiv dig ud i Un'Goros vildmark og skaf nok af den til vores fortsatte forskning.\n\nDen rige jord vil stikke op i dynger fra tid til anden, og nogle af bæsterne har måske brugbare prøver på sig. Tag dem alle med ud til Gede; led bare efter dyngerne af snavs og tyrefolket, der råber ordrer. Han mener det godt, bare ikke gør ham vred!", p="Stille, menig. Hvis du er her for at læsse jord af fra Un'Goro - så fremragende! Ellers, forsvind.", c="Åh, det er rigtigt, menig <Name>, gør ikke nogen anstrengelse for at hjælpe mig med at læsse denne jord op på dyngerne! Hvis de Store Ånder havde ønsket, at det skulle gøres, så ville de have mirakuleret den derop, ikke sandt?!\n\nÆrkedruide Runetotem vil gerne tale med dig igen, men til hans næste opgave finder du, at en svends forståelse af Urtekundskab ville være nyttig. Hvis du ikke kender det, så finder han dog stadig en brug for dig."},
  [3762] = {n="Assisterer Ærkedruide Runetotem", l="Tal med Ærkedruide Hamuul Rune-Totem i Tordenklippe.", d="Undskyld mig <Class>, men jeg vil gerne have et øjeblik af din tid, hvis det er muligt.\n\nCenarion-kredsen i Tordenklippe er meget interesseret i erfarne eventyrere som dig, der kan hjælpe dem med et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg fortælle dig, at ingen andre end Hamuul Rune-Totem står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte på Ældrehøjen inde i Tordenklippe selv.", c="Hilsner, <Class>; jeg er glad for, at du er interesseret i at hjælpe vores forskning. Der er meget at gøre, og jeg ville gøre dig en bjørnetjeneste, hvis jeg fortalte dig, at arbejdet ikke er farligt. Forhåbentlig skræmmer dette dig ikke væk... men ud fra dit udseende går jeg ud fra, at fare er noget, du har mødt før."},
  [3763] = {n="Assisterer Ærkedruide Hjorthelm", l="Tal med Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Undskyld mig <Class>, men jeg vil gerne have et øjeblik af din tid, hvis det er muligt.\n\nCenarion-kredsen i Darnassos leder efter erfarne eventyrere som dig, der kan hjælpe dem med et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg fortælle dig, at ingen andre end Ærkedruide Fandrel Hjorthelm står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte i Cenarion-enklaven inde i Darnassos selv.", c="Nå nå, <Class>... da du blev informeret om, at jeg selv ledede denne forskning, kom du naturligvis så hurtigt, du kunne.\n\nNu hvor du er her, så sørg for at være opmærksom, første gang jeg fortæller dig detaljerne; jeg har ingen lyst til at gentage mig selv."},
  [3764] = {n="Un'Goro-jord", l="Bring 20 prøver af Un'Goro-jord til Jenaal i Cenarion-enklaven i Darnassos.", d="Jorden i Un'Goro-krateret er angiveligt beriget med stærke magiske egenskaber. Jeg vil vide fakta fra falskheder; begiv dig ud i Un'Goros vildmark og skaf nok kvalitetsprøver af jord til vores fortsatte studier.\n\nDu synes måske, at indsamlingsopgaver er under din værdighed; den slags holdning gør dig ikke sympatisk for mig eller Cenarion-kredsen. Bring prøverne til Jenaal, som uden tvivl spilder tiden udenfor bag dette træ; led bare efter dyngerne af snavs. Han klarer logistikken - ikke jeg.", p="Ja, snavset. Ærkedruiden vil have tyve læs pr. eventyrer, og tyve læs skal han få. Lad dem, der konspirerer imod os, falde til siden!", c="Læs din dyrebare last af her, ædle <Class>. Den må have været en ret byrde... ikke ulig den byrde, jeg bærer ved at være en visionær. Her er en honorar for dit arbejde, som diktieret af ærkedruiden selv.\n\nÆrkedruide Hjorthelm vil gerne tale med dig igen <Name>, men til hans næste opgave vil du have gavn af at have en svends forståelse af Urtekundskab. Hvis du ikke kender det, så kan du dog stadig hjælpe kredsen!"},
  [3781] = {n="Morgendagsgræs-forskning", l="Tag Ærkedruidens Frøkupon med til Mathrengyl Bjørnegænger i Cenarion-enklaven i Darnassos.", d="Med det, vi kalder en Evergrøn-pung, har vi dyrket Tarvelendris-frø i jorden fra Un'Goro-krateret. Disse frø blomstrer til en række tilfældige, stærke urter. Et resultat er morgendagsgræs, en mystisk urt, vi ved lidt om; jeg har til hensigt at afsløre denne gåde.\n\nTag dette med til Mathrengyl nedenunder, og han giver dig nogle frø, så du kan komme i gang. Hvis du løber tør, må du købe flere af ham.", p="Fred og ro være med dig, ven. Du er her i ærinde fra ærkedruiden selv, ja?", c="Ja, denne kupon er god til tyve pakker frø. Hvis du løber tør, har vi flere, der kan skaffes. Desværre er Tarvelendris-frø ganske dyre at producere i betydelige mængder. Derfor beder Cenarion-kredsen dem, der hjælper os, om at dække en del af omkostningen.\n\nDem, der vender tilbage med morgendagsgræs, finder, at belønningen fra ærkedruiden langt opvejer omkostningen."},
  [3782] = {n="Morgendagsgræs-forskning", l="Tag frøkuponen med til Bashana Rune-Totem i Tordenklippe.", d="Med det, vi kalder en Evergrøn-pung, har vi dyrket Tarvelendris-frø i jorden fra Un'Goro-krateret. Disse frø er blomstret til en række tilfældige, stærke urter. Et resultat er morgendagsgræs, en mystisk urt, vi ved lidt om; jeg håber meget på at afsløre denne gåde for kredsen.\n\nTag denne kupon over til min datter Bashana, så giver hun dig nogle frø, så du kan hjælpe os. Hvis du løber tør, må du købe flere af hende.", p="Fred være med dig, ven. Du er her i ærinde fra ærkedruiden selv, ja?", c="Ja, denne kupon er god til tyve pakker frø. Hvis du løber tør for frø, har jeg flere, som jeg kan sælge til dig.\n\nDesværre <Name>, Tarvelendris-frø er ganske dyre at producere i betydelige mængder. Derfor beder Cenarion-kredsen dem, der hjælper os, om at dække en del af omkostningen. Dem, der vender tilbage med morgendagsgræs, finder, at belønningen fra ærkedruiden langt opvejer omkostningen."},
  [3783] = {n="Er vi der snart, Yeti?", l="Saml 10 Tykke Yeti-pelse til Umi Rumpleknaser i Evigblik.", d="Mine venner kommer altid med gode ideer. Jeg har aldrig følt, at jeg kunne måle mig med dem... før i dag! Jeg har lige tegnet planerne til noget stort! Hvis du lover ikke at fortælle det, så lader jeg dig være med til hemmeligheden...\n\nJeg vil lave en mekanisk yeti! Ikke bare vil mine venner med sikkerhed blive skræmt, når de ser den, men når de kommer over det, ved jeg, at de vil blive imponerede!\n\nJeg har brug for tyk yeti-pels fra isdistel-yetierne for at begynde. Vil du hjælpe? Du finder dem mod sydøst.", p="Jeg har masser at tage fat på her. Skaf mig de pelse, så hurtigt du kan!", c="Disse pelse er perfekte, <Name>. Vi er kommet godt fra start her!"},
  [3784] = {n="Assisterer Ærkedruide Runetotem", l="Tal med Ærkedruide Hamuul Rune-Totem i Tordenklippe.", d="Undskyld mig <Class>, men jeg vil gerne have et øjeblik af din tid, hvis det er muligt.\n\nCenarion-kredsen i Tordenklippe er meget interesseret i erfarne eventyrere som dig, der kan hjælpe dem med et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg fortælle dig, at ingen andre end Hamuul Rune-Totem står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte på Ældrehøjen inde i Tordenklippe selv.", c="Hilsner, <Class>; jeg er glad for, at du er interesseret i at hjælpe vores forskning. Der er meget at gøre, og jeg ville gøre dig en bjørnetjeneste, hvis jeg fortalte dig, at arbejdet ikke er farligt. Forhåbentlig skræmmer dette dig ikke væk... men ud fra dit udseende går jeg ud fra, at fare er noget, du har mødt før."},
  [3785] = {n="Morgendagsgræs-forskning", l="Brug en Evergrøn-pung med en Pakke Tarvelendis-frø og to prøver Un'Goro-jord for at forsøge at dyrke prøver af Morgendagsgræs.\n\nBring 10 Morgendagsgræs til Mathrengyl Bjørnegænger i Darnassos.", d="Her er din Evergrøn-pung, som du skal bruge til Tarvelendis-frøene. Du skal også have Un'Goro-jordprøver klar til at bruge som gødning til frøene. Brug bare pungen, når du har alt; pungen klarer resten.\n\nNår du har nok morgendagsgræs, så bring det til mig her i enklaven. Vær venlig ikke at forstyrre ærkedruiden; han er en meget travl mand, og han har ikke brug for at blive forstyrret, hver gang nogen vender tilbage med endnu et parti morgendagsgræs!", p="Ja <Name>, har du dyrket noget morgendagsgræs til ærkedruidens vigtige forskning? Arbejdet, han udfører for Cenarion-kredsen, er meget vigtigt, og din hjælp vil ikke gå ubemærket hen!", c="Godt gået <Name>, jeg vil sørge for at give disse til ærkedruiden selv, når han har brug for dem. I mellemtiden, så accepter venligst dette som et tegn på Cenarion-kredsens påskønnelse.\n\nVores behov for morgendagsgræs er konstant; hvis du ønsker at blive ved med at hjælpe os, så vend venligst tilbage til mig, når du har dyrket mere morgendagsgræs til os."},
  [3786] = {n="Morgendagsgræs-forskning", l="Brug en Evergrøn-pung med en Pakke Tarvelendis-frø og to prøver Un'Goro-jord for at forsøge at dyrke prøver af Morgendagsgræs.\n\nBring 10 Morgendagsgræs til Bashana Rune-Totem i Tordenklippe.", d="Her er din Evergrøn-pung, som du skal bruge til Tarvelendis-frøene. Du skal også have Un'Goro-jordprøver klar til at bruge som gødning til frøene. Brug bare pungen, når du har alt; pungen klarer resten.\n\nNår du har nok morgendagsgræs, så bring det til mig her på Ældrehøjen. Vær venlig ikke at forstyrre ærkedruiden; han bliver meget travl med forskningen og alle de andre bekymringer, han har!", p="Ja <Name>, har du dyrket noget morgendagsgræs til ærkedruidens vigtige forskning? De mystiske egenskaber ved Un'Goro-krateret bliver tydeligere for hver dag, der går, takket være din hjælp, du giver os.", c="Godt gået <Name>, jeg vil sørge for at give disse til ærkedruiden selv, når han har brug for dem. I mellemtiden, så accepter venligst dette som et tegn på Cenarion-kredsens påskønnelse.\n\nVores behov for morgendagsgræs er i øjeblikket konstant; hvis du ønsker at blive ved med at hjælpe os, så vend venligst tilbage, når du har dyrket mere af det."},
  [3787] = {n="Jonesilds Anmodning", l="Tal med Quintis Jonesild i Fjermåne-fæstningen.", d="Undskyld mig, ven...\n\nEn kollega af mig vil gerne tale med dig om den forskning, du udfører i samarbejde med Cenarion-kredsen. Han er en druide ved navn Quintis Jonesild, og han holder til i Fjermåne-fæstningen i Vildalas. Han vil gerne drøfte morgendagsgræs med dig... og han vil meget gerne have, at du holder vores samtale fra den Ærkedruides ører.\n\nHvis du er interesseret, så tal med ham; uden tvivl bliver alt afsløret, når du gør det.", c="Jeg takker dig for at komme, trætte rejsende! Lad mig præsentere mig selv - jeg er Quintis Jonesild, druide og ydmyg tjener af Malfurjon og Cenarion-kredsen. Mine kolleger (General Shandris Fjermåne og Beskyttelsen - måske har du hørt om os) og jeg ville tale med dig om det arbejde, du udfører for Fandrel Hjorthelm i Darnassos.\n\nFør vi kommer længere, vil jeg gerne bede om, at vores samtale forbliver mellem os to. Hvis du ikke har noget imod det, så kan vi fortsætte."},
  [3788] = {n="Jonesilds Anmodning", l="Tal med Quintis Jonesild i Fjermåne-fæstningen.", d="Undskyld mig, ven...\n\nEn kollega af mig vil gerne tale med dig om den forskning, du udfører i samarbejde med Cenarion-kredsen. Han er en druide ved navn Quintis Jonesild, og han holder til lige her i Fjermåne-fæstningen. Han vil gerne drøfte morgendagsgræs med dig... og han vil meget gerne have, at du holder vores samtale fra den Ærkedruides ører.\n\nHvis du er interesseret, så tal med ham; uden tvivl bliver alt afsløret, når du gør det.", c="Jeg takker dig for at komme, trætte rejsende! Lad mig præsentere mig selv - jeg er Quintis Jonesild, druide og ydmyg tjener af Malfurjon og Cenarion-kredsen. Mine kolleger (General Shandris Fjermåne og Beskyttelsen - måske har du hørt om os) og jeg ville tale med dig om det arbejde, du udfører for Fandrel Hjorthelm i Darnassos.\n\nFør vi kommer længere, vil jeg gerne bede om, at vores samtale forbliver mellem os to. Hvis du ikke har noget imod det, så kan vi fortsætte."},
  [3789] = {n="Assisterer Ærkedruide Hjorthelm", l="Tal med Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Undskyld mig <Class>, men jeg vil gerne have et øjeblik af din tid, hvis det er muligt.\n\nCenarion-kredsen i Darnassos leder efter erfarne eventyrere som dig, der kan hjælpe dem med et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg fortælle dig, at ingen andre end Ærkedruide Fandrel Hjorthelm står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte i Cenarion-enklaven inde i Darnassos selv.", c="Nå nå, <Class>... da du blev informeret om, at jeg selv ledede denne forskning, kom du naturligvis så hurtigt, du kunne.\n\nNu hvor du er her, så sørg for at være opmærksom, første gang jeg fortæller dig detaljerne; jeg har ingen lyst til at gentage mig selv."},
  [3790] = {n="Hjælpende Ærkedruide Hjorthelm", l="Tal med Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Undskyld <Class>, men jeg vil gerne have et øjeblik af din tid, hvis det er muligt.\n\nCenarion-kredsen i Darnassos søger erfarne eventyrere som dig selv til at yde dem bistand i et vigtigt forskningsprojekt. Selvom jeg ikke kender detaljerne, kan jeg oplyse, at ingen andre end Ærkedruide Fandrel Hjorthelm står i spidsen for denne forskning.\n\nHvis du er interesseret, så tal med ham direkte i Cenarion-enklaven inde i selve Darnassos.", c="Nå ja, <Class> ... da du fik at vide, at jeg selv ledede forskningen, kom du naturligvis så hurtigt du kunne.\n\nNu hvor du er her, så sørg for at lytte godt efter første gang jeg fortæller dig detaljerne; jeg har ingen lyst til at gentage mig selv."},
  [3791] = {n="Morgengræssets Gåde", l="Bring 10 Morgengræs til Quintis Jonsspyre i Fjermåne-fæstningen.", d="Lad mig være ærlig over for dig, <Name>. Jeg er interesseret – nej, bekymret – over hvorfor Ærkedruiden i Darnassos bruger navnet på Cenarion-kredsen samt kredsens ressourcer til at skaffe enorme mængder morgengræs. Jeg er forsker – forbandelser er min specialitet. Jeg har hørt, at morgengræs under de rette forhold udsender egenskaber ligesom de urter, der bruges i primitive forbandelser.\n\nJeg vil gerne vide mere, og jeg beder om din hjælp. Bring mig ti morgengræs, så skal jeg nok tage mig godt af dig.", p="Jeg leder efter ti morgengræs – det burde være nok til i det mindste at få min forskning i gang. Jeg vil uden tvivl brænde en masse af dem af på forkerte veje, men sådan er forskning nu engang.", c="Pyt, disse morgengræs får mig til at føle mig... underlig. Hvad i Elunies navn har Hjorthelm gang i med disse ting?\n\nUnder alle omstændigheder, tak igen for din hjælp. Her er en lille ting... du ved, for indsatsen. Min forskning i morgengræs kommer til at tage et stykke tid, og jeg har uden tvivl brug for mere. Når jeg nu er i gang, kunne jeg vel også tage mig tid til at se, om morgengræs har nogle relevante alkymiske anvendelser. Alligevel føler jeg mig utilpas selv ved at være i nærheden af dem."},
  [3801] = {n="Mørkejernets Arv", l="Tal med Franklorn Smedeværk, hvis du er interesseret i at skaffe hovednøglen til byen.", d="Hilsen, <Name>. Jeg er Franklorn Smedeværk. Ja, den Franklorn Smedeværk, der står bag stenbygningsmetoden. Du er uden tvivl gået igennem eller har stået på en af mine skabelser under dine eventyr i vores krigshærgede verden.\n\nDu undrer dig sikkert over, hvorfor jeg er her, og hvad det er, jeg vil have af dig – begge spørgsmål er berettigede.\n\nJeg har naturligvis brug for din hjælp. Som gengæld for din hjælp vil jeg give dig nøglen til dybderne i min forbandede by.", c="Hvad end det er grådighed, der har bragt dig hertil, eller en handling af uegennyttig hengivenhed, så er det, du er ved at give dig i kast med, til gavn for os alle."},
  [3802] = {n="Mørkejernets Arv", l="Dræb Fineous Mørkvinge og hent den store hammer, Jernfel. Tag Jernfel til Thaurisans helligdom og læg den på statuen af Franklorn Smedeværk.", d="Du finder Fineous Mørkvinge hinsides Lovens Ring, i Håndværkshallen. Dræb den elendige køter og hent Jernfel.\n\nTag Jernfel til Thaurisans helligdom og læg hammeren på dens rette plads: i hænderne på statuen rejst til min ære.\n\nNår dette er gjort, åbner rummet, hvor jeg opbevarede hovednøglen. Endnu vigtigere: Jernfel vil for evigt forblive i min besiddelse. Skulle nogen forsøge at fjerne hammeren, vil både statuen og hammeren splintres og gå tabt for evigt.", p="Statuen tårner truende op over dig.", c="Hammeren glider fast på plads, i grebet af det enorme Mørkejern-monument. Et lille rum åbner sig ved statuens fod. Indeni finder du..."},
  [3821] = {n="Rædselsslæggen-stenen", l="Begiv dig til Brændende Stepper og find ud af, hvad der blev af Sja'ni Stoltstødder.", d="Sja'ni blev sendt for at undersøge rapporter om mærkelig rituel aktivitet fra Ildmave-ogrerne i Brændende Stepper for over tre uger siden.\n\nGoretooth fortæller mig, at han ikke har hørt fra nogen i den tropp, og at det er bedst, at jeg går videre og fokuserer på opgaven. Kan du tro det? Det er min kone!\n\nJeg kan ikke forlade min post, <Name>, men jeg må vide, hvad der er blevet af Sja'ni. Rejs til Brændende Stepper og led efter hende.", c="Min stakkels Thal'træk.\n\nVi havde planlagt at flytte ind hos min mor og far i Bagland, når vores tjenestetid var forbi. Nu er de planer ødelagt!"},
  [3822] = {n="Krom'Grøl", l="Hent Sja'nis næsering fra Krom'Grøl og bring den tilbage til Thal'træk i Kargat. Gennemsøg de forskellige huler og miner i Rædselsslæggen-stenen.", d="Hele min tropp blev taget til fange, <Name>. Alle blev dræbt – undtagen mig.\n\nDeres leder, Krom'Grøl, ville redde mig til en eller anden form for ritual.\n\nJeg var lænket til dette alter og brutaliseret af udyret. Min fysiske krop holdt op med at fungere efter en time med denne tortur. Udyret rev så min bryllupsnæsering af mit ansigt og stak den på sin finger. Jeg havde aldrig set sådan en vildskab!\n\nFind Krom'Grøl og dræb ham! Tag min ring tilbage til Thal'træk.\n\nOg <Name>, sig til ham, at vi vil mødes igen... i et andet liv.", p="Fandt du Sja'ni? Har hun det godt?", c="<Thal'træk bryder sammen.>\n\nVi skulle flytte til Bagland. Fortalte hun dig det? Det her skulle have været hendes sidste mission.\n\n<Thal'træk hulker.>\n\nJeg vil ikke have den, <Name>. Behold den, smid den væk, jeg er ligeglad! Ringen betyder ikke noget for mig nu. Ikke uden hende..."},
  [3823] = {n="Udslet Ildmaven", l="Dræb 15 Ildmave-oger-magikere, 7 Ildmave-oger og 7 Ildmave-oger-brutter, og vend tilbage til Oralis, når du er færdig.", d="Vi må ramme vores fjender, før de rammer os!\n\nJeg skal gøre det kort, soldat.\n\nIldmave-ogrerne i Brændende Stepper er allierede med Sortklippe-orkerne. De samarbejder tæt med de onde orker og holder den mineralrige Rædselsslæggen-sten bevogtet og forsyningslinjerne åbne til enhver tid.\n\nEfterlad dit mærke, <Name>. Lam deres styrker og vend tilbage til mig, når jobbet er gjort.\n\n<Oralis griber efter luften og laver en kvælende bevægelse.>\n\nJEG VIL SLÅ DIG IHJEL, BLINKE!", p="Der er slet ikke nok blod på din uniform, soldat!", c="Fremragende, soldat! Orkerne og ogrerne vil vakle af dette slag i flere minutter, måske endda i timevis!"},
  [3824] = {n="Gor'tæsh Brutal-herren", l="Find Gor'tæsh, et sted vest for Rædselsslæggen-stenen. Dræb Gor'tæsh og tag derefter Gor'tæshs afhugne hoved tilbage til Oralis i Brændende Stepper.", d="De er ved at vakle, siger jeg dig! Vores næste angreb skal være afgørende.\n\nBrutal-herren Gor'tæsh skal dø. Endnu vigtigere: hans hoved skal bringes til mig, så jeg kan forberede tredje fase af vores angreb på Ildmave-ogrerne.\n\nVær advaret, soldat: Gor'tæsh hersker ikke fra Rædselsslæggen-stenen, men fra en Sortklippe-ork-konstruktion vest for Rædselsslæggen-stenen.\n\nDine ordrer er derfor enkle. Find Gor'tæsh og hug hans fede hoved af. Vend tilbage til mig, når jobbet er gjort.\n\nHOLD KÆFT, BLINKE!", p="Å herlige dag! Er du vendt tilbage med hovedet?", c="Se bare på det, soldat. Ækelt! Når de resterende Ildmave-oger ser dette fede fjæs sat på en pæl på toppen af deres bjerg, vil der bryde massehysteri ud!\n\n<Oralis skraldgriner vildt.>"},
  [3825] = {n="Oger-hoved på en pind = Fest", l="Tag Gor'tæshs afhugne hoved og placer det øverst på Rædselsslæggen-stenen. Led efter en blød jordvold at plante pælen i.", d="Der er lige en sidste ting, du skal gøre, soldat.\n\nJeg har taget mig den frihed at sætte Gor'tæshs hoved på en pæl. Nu skal du bare tage dette hoved op til toppen af Rædselsslæggen-stenen og stikke det ned i jorden. Når du har gjort det, så se på, hvordan de kujonagtige ogre løber for livet! Når du har haft din fornøjelse, så kom tilbage til mig, så belønner jeg dig for alt dit hårde arbejde.\n\n<Oralis synes at miste forbindelsen til virkeligheden.>", p="Nå? Malede du nogen billeder af begivenheden?", c="Fremragende arbejde, soldat! Simpelthen fantastisk! Åh, jeg får medaljen for mod for det her, øh, jeg mener, du bliver belønnet rigeligt for det her!"},
  [3841] = {n="En forældreløs på jagt efter et hjem", l="Tal med Kwentin i Tusind Nåle.", d="Åh, hej, <Name>. Jeg er så glad for at se dig igen. Hvordan gik din rejse til Darnassos?\n\nJa, du vil blive glad for at høre, at vi har gjort ganske store fremskridt, mens du har været væk. Vi fik endda reddet et rede fuld af æg. Desværre døde moderen, før vi nåede frem til hende.\n\nSig, vil du have et til kæledyr? De ser ud til at klække snart, så de skal bruge en god far. Hvad siger du?\n\nHvis du virkelig er interesseret, så tag et af æggene til Kwentin ved væddeløbsbanen i Skimrende Sletterne. Han vil fortælle dig mere.", p="Hej der, <Class>.\n\nLad ikke min placering narre dig, jeg er virkelig ikke her for væddeløbene... hvor underholdende de end måtte være.\n\nJeg er faktisk her i Tusind Nåle for at undersøge alt, hvad jeg kan, for at finde ud af, hvor brugbart landet er. Det er blevet en slags korstog for mig at genoplive og genopfylde området med ny, frugtbar jord. Måske finder jeg en vandkilde i nærheden.\n\nFortæl mig, at du ikke har bemærket, hvor mærkelig overgangen mellem Vildalas og Tusind Nåle er. Der var underlig magi på spil, da det skete.", c="Ah, et pilespringer-æg, og et der er tæt på at modne, hvis jeg ikke tager fejl. Bemærkelsesværdigt, at du har fundet et, og endnu mere i så god stand. De ses sjældent i Vildalas i dag. Jeg forstår, at der var forskellige krybskytter i området, der forsøgte at fange og dræbe dem af mange grunde. Synd egentlig... så smukke væsener, når de når voksenalderen.\n\nHvordan kom du over sådan et fund?"},
  [3842] = {n="En kort inkubation", l="Bring 2 Eliksirer af Udholdenhed til Kwentin i Tusind Nåle.", d="Månevæverne, hm? Meget interessant. Jeg ønsker, at pilespringerne virkelig kunne værdsætte, hvad det betyder at have de to til at passe på dem. De er begge ganske dygtige.\n\nSå de gav dig ægget som en gave. Nå, så bør du være ansvarlig for det, så længe du ønsker det. Det ser ud til at være næsten klar til at klække, men vi bør sikre os, at det er sundt, og at der ikke er sket skade på det.\n\nJeg har kun brug for to eliksirer af udholdenhed til en lille besværgelse, der skal beskytte ægget. Resten af ingredienserne har jeg med mig her.", p="Jo længere jeg bliver her, jo mere fristet er jeg til at deltage i disse væddeløb, <Name>. Helt forunderligt...\n\nHar du fundet eliksirerne endnu? Når jeg kan se, om ægget bliver sundt eller ej, får du det tilbage, så du kan passe på det, indtil det er klar til at klække.\n\nLad mig vide det.", c="Vidunderligt. Disse duer fint. Giv mig et øjeblik til at blande mine ingredienser sammen, så ser vi, hvordan dette æg klarer sig."},
  [3843] = {n="Den nyeste familiemedlem", l="Tag dit skrøbelige pilespringer-æg til Bagland og tal med Agnar Udyrstyrer, men skynd dig, du har kun 1 time til at finde ham, før udklækningen i ægget dør.", d="Et storslået eksemplar, <Name>. Hvis dette væsen overlever drægtigheden, så bliver det et sundt kæledyr!\n\nDer er én sidste ting, jeg vil foreslå, hvis du har tænkt dig at følge det til ende: Tag til Ørnerede-toppen i Bagland. Tal med en dværg der ved navn Agnar Udyrstyrer; han er en mester i dyrehåndtering og bør kunne vejlede dig i de sidste trin af inkubationen.\n\nMen skynd dig, <Name>, dette æg er skrøbeligt og vil ikke holde længe uden ordentlig pleje.", p="Hej'ser, <Name>. Hvordan kan jeg være dig til tjeneste?", c="Nå, nå, nå... Jeg har ikke set en af dem i en drages tid. Fe-drage, hvis jeg ikke tager fejl... ser ud til at være af pilespringer-sorten. Fremragende, virkelig fremragende.\n\nNå, hvis denne lille fyr skal klække og leve, stærk og sund, så bør vi skaffe lidt mad til den. Godt du fik den til mig i tide."},
  [3844] = {n="Det er en hemmelighed for alle", l="Kig rundt i dammen efter et spor om, hvem denne vragede flåde kan tilhøre.", d="En ødelagt flåde ligger langs bredden. Eftersom dette kun er en lille dam, er det ikke klart, hvordan den endte her, selvom træerne tyder på, at vandstanden måske ikke er konstant.\n\nMåske kan lidt udforskning af området afdække flere spor...", c="En vandfyldt pakke ligger på bunden af dammen."},
  [3845] = {n="Det er en hemmelighed for alle", l="Undersøg tingene i pakken og bring dem til deres ejer.", d="Du griber fat i den og trækker pakken tilbage til bredden. Måske kan du, hvis du undersøger tingene i pakken, finde ud af mere om, hvem den tilhører.\n\nDer er nogle få omstrejfende rejsende ved Marskalkens Fristed. Måske kan du finde ud af mere der.", p="Hej der. Jeg har set dig før... Har jeg ikke?", c="Åh... Ja, disse ting ser da bekendte ud... nå, nogenlunde..."},
  [3881] = {n="Ekspeditionens redning", l="Bring en kasse med fødevarer og forskningsudstyr til Vilden Marskal i Un'Gorø-krateret.", d="Jeg ved ikke, hvordan du er kommet hertil, men du er et velkomment syn for trætte øjne! Jeg er Vilden Marskal, og jeg leder en ikke-alliereret ekspeditionstrup. Vores seneste og bedste foretagende har mødt det, der virker som utallige katastrofer, hvoraf den alvorligste er, at vi undervurderede vildskaben i Un'Gorø-krateret!\n\nDa vi flygtede fra vores basislejre i kraterets sydvestlige og nordøstlige dele, efterlod vi vigtige forsyninger. Du ser ud til at være dygtig nok. Kan du hjælpe os med at hente dem?", p="Hvis vi skal have nogen chance for at komme herfra i live, får vi brug for vores store kasse med fødevarer. Og at få i det mindste noget af vores forskningsudstyr tilbage ville være en velsignelse i et hav af elendighed.", c="Du fik både vores fødevarer OG vores forskningsudstyr tilbage! Du har ikke bare reddet ekspeditionen, du har også reddet vores liv. Jeg og resten af mit hold kan ikke takke dig nok; takket være dig kan vi måske blive her et stykke tid nu.\n\nSelvom vi ikke har meget, vil jeg bestemt ikke svigte dig for den uvurderlige hjælp, du har givet os. Tak, <Name> – du har en ven i Marskal-ekspeditionerne!"},
  [3882] = {n="Kast knoglerne", l="Bring 8 Dinosaurus-knogler til Gnist Nilminer i Un'Gorø-krateret.", d="Man skulle tro, at det at være chefgraver for Marskal-ekspeditionerne betød, at jeg kan lide at grave. Der findes måske værre ting at lave i denne verden... men ingen rigtig falder mig ind.\n\nVi skulle grave i Rædselsløbet – FANTASTISK navn i øvrigt – efter døde stegodonter og diemetradoner. Nå, der er også masser af levende af dem dernede! Vil og Hul studerer stadig denne dødsfælde, så vi har brug for disse dinosaurusknogler. Men mellem dig og mig, så vil det at tage nogle fra levende væsner fungere lige så godt.", p="Tænk, hvad du vil om mig, men de bryder sig ikke om, om knoglerne, de får til forskning, stammer fra gamle stegodonter og diemetradoner eller fra dem, der næsten opslugte os hele, da vi forsøgte at slå vores lejre op. Jeg bliver bare glad, hvis vi kommer herfra i live...", c="Fremragende, disse burde gøre det. Og nu, hvis du tillader mig...\n\nTAK FOR AT GRAVE ALLE DISSE KNOGLER UD AF JORDEN FOR OS OG IKKE SKADE DE INDFØDTE BÆSTER PÅ NOGEN MÅDE.\n\nOm du virkelig gjorde det eller ej, vil jeg ikke vide. Lad os holde det sådan, ikke? Her – måske holder det din mund om det hele. Alt for at komme herfra i live, siger jeg!"},
  [3883] = {n="Fremmed økologi", l="Brug Skrabehætteglasset til at indsamle en Bikube-vægprøve fra et af de gorisjiske bikube-klækkerier i Un'Gorø-krateret. Led efter kamrene med de hængende larvebørn.\n\nBring Bikube-vægprøven til Hol'anøje Marskal i Un'Gorø-krateret.", d="Bare fordi vi har lidt et tilbageslag, betyder det ikke, at forskningen skal stoppe! Vi undersøgte gorisjisk-insekterne i den sydlige del af krateret, før vi endte her. Deres tilstedeværelse er fremmed for Un'Gorøs økologi, og vi vil gerne finde ud af hvorfor.\n\nI deres bikubenetværk må der være larveklækkerier. Du kan genkende disse steder på de hængende larvebørn. Brug dette hætteglas til at tage en prøve af bikubevæggen nær et af klækkerierne. Bring det tilbage til mig til studier, men vær forsigtig!", p="Har du prøven af den gorisjiske bikube til mig at studere, <Name>?", c="Ja, dette duer fint. Du har været en stor hjælp... Jeg ville ønske, jeg kunne give dig mere end dette, men at være praktisk talt strandet midt i et vildt land begrænser, hvad jeg kan og ikke kan give. Vær dog rolig – forskningen her ville ikke have været mulig uden din hjælp!"},
  [3884] = {n="Vildens dagbog", l="Returner dagbogen til Vilden Marskal et sted i Un'Gorø-krateret.", d="Du har afdækket en medtaget dagbog. Dele af den er stadig læselige, og en Vilden Marskal gør krav på indholdet. Hvis dagbogen er korrekt, kan Vilden måske findes et sted i den nordlige del af krateret; ifølge dagbogen søgte han og hans kammerater højere terræn væk fra krateret vilde bæster, da deres basislejre blev overrendt.", p="Hej der! Jeg og mine kammerater er glade for at se nogle levende væsner her, bortset fra tilvoksede vilde bæster! Hvad fører dig ind i Un'Gorø-krateret?", c="Nå, se lige her – min dagbog! Jeg troede, den var tabt, ligesom næsten alt andet, vi bragte med til Un'Gorø. Tusind tak, fordi du returnerede den til mig!"},
  [3906] = {n="Flammens disharmoni", l="Rejs til stenbruddet i Sortklippebjerget og dræb Overmester Pyrøn. Vend tilbage til Tordenhjerte, når du har fuldført denne opgave.", d="De ældste har mærket en forstyrrelse blandt elementerne. Mørkjernsdværgene har fremmanet en ond ånd ind i vores verden, der truer med at plage vores lande med en evig tørke. Denne flammens disharmoni må undersøges.\n\nRejs til Sortklippebjerget, gennem Flammekløften, og ind i stenbruddet. Det er der, du vil finde denne ildherre: Overmester Pyrøn.\n\nStands forstyrrelsen og vend tilbage til mig.", p="Elementerne er stadig i uorden, <Name>.", c="Det kan ikke være... det må ikke være. Ødelæggelsen af Pyrøn har kun løftet et slør. Dybt inde i Sortklippe findes en langt mere snigende kilde til korruption."},
  [3907] = {n="Ildens disharmoni", l="Gå ind i Sortklippe-dybderne og spor Herre Brandius op. Dræb ham og bring alle informationskilder, du måtte finde, tilbage til Tordenhjerte.", d="Jeg kan smage ondskaben i luften omkring dig, <Name>. Der er en anden, skjult i Sortklippes dybder, som kontrollerer denne ondskab.\n\nVind og jord råber hans navn: Herre Brandius... men nogen... noget... styrer dette væsen. Han er blot en udsending.\n\nFind ham og opdag, hvor hans herre gemmer sig. Vend tilbage til mig, når du har indsamlet denne information.", p="Flammerne vil snart overtage disse lande. Skynd dig, <Name>!", c="<Tordenhjerte griber Kurnijas tavle.>\n\nRagnarøs... her...\n\nDe ældste havde ret i at frygte korruptionen, der udgik fra Sortklippebjerget. En general fra De Gamle Guder! I VORES VERDEN! Vi må genvurdere vores position her i Kargat. Vi må beslutte, om vi bliver og kæmper, eller flygter af frygt for en ny splittelse.\n\nVær forsigtig med yderligere udforskning af Sortklippebjerget, <Name>. En langt større ondskab end noget, der findes i denne verden, residerer i de flammende dybder."},
  [3908] = {n="Det er en hemmelighed for alle", l="Tag Lænkens sværd til Donova Snedal i Vinterkilde.", d="Ser du, jeg har ingen anelse om, hvordan jeg endte her. Ingen ved det rigtigt – det er en hemmelighed for alle! Jeg kan bare ikke huske noget...\n\nDisse ting, du bragte til mig, dog... de får mig til at huske noget.\n\nMit sværd. Jeg skal på en eller anden måde styrke det, men jeg er ikke helt sikker på hvorfor. Undskyld, at jeg ikke kan fortælle dig mere, men jeg kan bare ikke huske det!\n\nHursomhelst, jeg ved i hvert fald, hvor du kan tage det hen: til Donova Snedal i Vinterkilde. Du finder hende ved de varme kilder. Hun kan hærde sværdet ved bassinerne dér.", p="Nå, nå... Så Lænken fik endelig sendt mig sit sværd.", c="Nå, selvfølgelig kan jeg hærde dette sværd. Mens jeg arbejder, kan du forklare, hvad der fik Lænken til at tage så lang tid om at få det her til mig. Han plejer ikke at glemme ting..."},
  [3909] = {n="Videre-eliksiren", l="Søg Gregor Bryggespyt i det nordlige Vildalas. Lær af ham, hvordan du kan skaffe Videre-eliksiren, og vend derefter tilbage til Donova Snedal i Vinterkilde.", d="Hvad er det her? Lænken... GLEMT?\n\nÅh, jeg forstår... Har mistet sin hukommelse...\n\nNå, her er hans sværd. Det er dog ikke komplet. Jeg kender den, der kan færdiggøre det, men... at tale med ham kan vise sig at blive svært.\n\nLyt, jeg kender nogen, der kan hjælpe dig. Det er for meget at forklare lige nu, men du må på en eller anden måde skaffe en Videre-eliksir. Den eneste jeg kender, der kan hjælpe dig med det, er Gregor Bryggespyt. Han er svær at finde, men sidst jeg vidste det, slog han lejr i Vildalas' vildnis.", p="Allerede tilbage?", c="Jeg skal bruge et hætteglas for at sikre, at dette virkelig er eliksiren... Ja... Det er den rigtige."},
  [3911] = {n="Det sidste element", l="Rejs til Sortklippe-dybderne og hent 10 Elementernes Essens. Din første tanke er at lede blandt golemerne og golem-skaberne. Du husker, at Vivian Lagrav også mumlede noget om elementarer.", d="Der er arbejde at hente for dem, der vover sig ned i dybderne, <Name>.\n\nMørkjernsdværgene har mestret skabelsen af ekstremt kraftfulde golemer.\n\nForeløbige rapporter fra vores spioner tyder på, at dværgene bruger en unik energikilde til at give deres skabninger uforlignelig dræbeevne.\n\nForestil dig, hvad vi kunne gøre med vores abominationer, hvis vi kunne få fat i denne elementernes essens! Vend den by på hovedet, hvis du må, men vend ikke tilbage, før du har fundet essensen! Betalingen vil være risikoen værd."},
  [3912] = {n="Mød ved graven", l="Gå til kirkegården uden for Gadgetbyen og brug Videre-eliksiren. Følg resten af Donovas instruktioner for at finde Gæriyan.", d="Denne eliksir vil give dig mulighed for at tale med en, du normalt aldrig engang ville kunne se...\n\nTag Videre-eliksiren sammen med Lænkens sværd til kirkegården lige uden for Gadgetbyen i Tanarisørkenen. Når du er der, så drik trylledrikken. Du bliver måske ganske overrasket over resultatet, men lad dig ikke skræmme.\n\nI din \"andre\" skikkelse skal du gå direkte mod nord, indtil du når bjergene. Du vil finde den, du skal tale med, i en af klippespalterne. Han hedder Gæriyan.\n\nHusk, han vil kun tale med dig i den skikkelse...", c="Det er længe siden, nogen har kommet for at tale med mig..."},
  [3913] = {n="En gravsituation", l="Genopstå, og led derefter efter gravstenen, som Gæriyan fortalte dig at finde.", d="Hvis du vender tilbage til kirkegården, <Name>, vil du finde en gravsten der... Ikke en hvilken som helst gravsten; denne vil skille sig ud fra de andre. Hemmeligheder gemmer sig i den.\n\nTryk på stenen, så vil du få at vide om disse hemmeligheder...", p="Dette må være gravstenen, som Gæriyan nævnte...", c="Du trykker fast på stenen, og den glider væk og afslører en lille fordybning under den.\n\nNår du placerer Lænkens sværd i fordybningen, indser du, at det passer perfekt..."},
  [3914] = {n="Lænkens sværd", l="Lever Lænkens Overlegne Sværd til Lænken i Un'Goro-krateret.", d="Efter et kraftigt lysglimt kan du igen samle sværdet op. Det er blevet forvandlet!", p="Åh! Jeg kender dig! Du er... Nej, sig det ikke!", c="Mit sværd... Det er færdigt!\n\nNu, hvis bare jeg kunne huske hvorfor jeg havde brug for det...\n\nHer, lad mig i det mindste betale dig for dit arbejde."},
  [3941] = {n="En gnoms hjælp", l="Find J.D. Hyrdehund i hulen ved Marskalkens Fristed.", d="Tænker... Tænker... Jeg ved, at jeg kom hertil for noget vigtigt...\n\nJeg har en idé, <Name>. I hulen derovre bor en gnom ved navn J.D., som var meget venlig mod mig, da jeg først kom hertil. Måske har jeg i min desorienterede tilstand nævnt noget for hende.\n\nHvorfor går du ikke hen og spørger hende, om hun ved noget? Men pas på -- hun roder altid rundt med de skøre lysende krystaller, jeg har set i krateret. Jeg er ikke helt sikker på, hvad hun laver derinde!", c="Bliv lige stående et øjeblik... Jeg tester en ny kombination af krystaller..."},
  [3942] = {n="Lænkens minde", l="Find Eridan Blåvind i det sydlige Ondskov.", d="Åh... Linken? Ja, han er en underlig en. Da han første gang kom hertil, mumlede han om alle mulige mærkelige ting. Han er nok blevet slået hårdt i hovedet, tror jeg.\n\nNoget af det, han sagde, blev dog hængende hos mig -- at han lavede en slags totem; at han skulle tale med en ved navn Eridan Blåvind... et sted kaldet Ondskoven, tror jeg?\n\nJeg tvivler på, at han kan fortælle dig meget nu. Hvis du vil vide mere, må du hellere lede efter Eridan selv?", c="Hej, <Class>. Er der noget, jeg kan hjælpe dig med?"},
  [3961] = {n="Lænkens eventyr", l="Tag Akvementas' Sølvtotem til Lænken i Marskalkens Fristed.", d="Og tænk, at grunden til, at Linken kom hertil, hele tiden har været at gøre os fri for Flammeløber... Han virker som sådan en almindelig fyr, men jeg har bemærket, at han slet ikke er interesseret i nogen af mine eksperimenter eller apparater, sådan som de fleste gnomer ville være. Han må være en sand kriger i sit hjerte.\n\nBring totemet til ham. Se om det hjælper ham med at huske, hvorfor han kom hertil.", p="Hej igen, <Name>!", c="Hjalp J.D. dig overhovedet?"},
  [3962] = {n="Det er farligt at gå alene", l="Rejs til Ildfjer-højderyggen, syd for Marskalkens Fristed.\n\nFind Flammeløber og brug totemet til at fjerne hans beskyttende glorie. Når han er besejret, skal du hente den Gyldne Flamme fra hulen.", d="<Name>, nu husker jeg endelig... Jeg kom faktisk hertil for at bekæmpe Flammeløber. Jeg var på en rejse, og dette skulle have været det sidste skridt.\n\nMen jeg er ikke længere helten... Det er du. Alt det, du har gjort -- det er dig, der nu må fuldføre det, ikke mig.\n\nFlammeløber vogter en artefakt ved navn den Gyldne Flamme. Den giver en kraft, der er større end noget, jeg nogensinde har kendt, og den er farlig i hænderne på en med et ondt hjerte.\n\nDu vil ønske at tage andre med dig -- det er farligt at gå alene. Tag dette som mit råd.", p="Flammeløber er næsten uovervindelig bag den glorie, han har skabt med den Gyldne Flamme. Kun du har magten til at fjerne den med Akvementas' Sølvtotem.", c="Tak, <Name>.\n\nDen Gyldne Flamme vil nu blive bragt tilbage til mit hjemland, hvor den kan beskyttes, så den aldrig igen bruges til ondt.\n\nUden dig ville jeg stadig ingen anelse have om, hvem jeg er! Eftersom du har gjort så meget for mig, vil jeg gerne give dig noget særligt...\n\nVælg en hvilken som helst, du vil have!"},
  [3981] = {n="Kommandør Gor'skak", l="Find Kommandør Gor'skak i Sortklippe-dybderne.\n\nDu husker, at det grovt tegnede billede af orken havde søjler tegnet hen over portrættet. Måske bør du lede efter et slags fængsel.", d="Stakkels Gargøl... så det ikke engang komme. WHAM! Pilen ramte lige midt i toppen af hans hoved. Han var ikke nogen genial hjerne før, men nu...\n\n<Galamøv grimasserer.>\n\nDa vi fik pilen løsnet, lagde vi mærke til en sammenrullet seddel fastgjort til skaftet. På seddlen var en grovt tegnet tegning af en ork bag tremmer, med Kommandør Gor'skaks underskrift.\n\nHvis han stadig er i live i dybderne, må du finde ham.\n\nEn fælde siger du? Ja, det var da lige til at se, dumme hove! Derfor skal du jo af sted!", c="Vi har ikke meget tid. Lyt nøje, <Race>. Det, jeg har at fortælle dig, er fortroligt og kun til dine ører."},
  [3982] = {n="Hvad foregår der?", l="Forsvar Gor'skak.", d="Jeg blev sendt hertil under Thralls ordre. Tror du virkelig, at disse tosser kunne fange mig? Jeg lod mig fange, så jeg kunne indhente efterretninger.\n\n<Gor'skak hvisker.>\n\nPrinsessen fra Jernsmede er blevet kidnappet af Kejser Tårissan. Prinsesse Bronzeskæg er i denne by! Jeg vedder på, at gamle Magnie næsten fik et hjertestop, da han hørte den nyhed.\n\n<Gor'skak griner.>\n\nShh! Hører du det? Vagterne kommer! FORSVAR DIG SELV!", p="Forsvar dig selv, tosse!", c="Det var et tæt på-kald. De er blevet underrettet om din tilstedeværelse... flere vil helt sikkert komme."},
  [4001] = {n="Hvad foregår der?", l="Tal med Hårdan Mægtighammer og saml oplysninger om Prinsesse Moira Bronzeskægs kidnapning. Tag oplysningerne med til Thrall i Orgrimgrad.\n\nDu husker, at Gor'skak nævnte, at Hårdan holdes fanget i en celle i nærheden.", d="Indtil nu har min kommunikation med dværgen Hårdan i cellen over for gangen været begrænset. Jeg har dog formået at overbevise ham om, at jeg, eller rettere -vi- ikke har nogen ond hensigt med ham.\n\nGå og tal med ham, og saml så mange oplysninger som muligt om prinsessen og hendes fangevogtere. Tag disse oplysninger med tilbage til Krigshøvdingen.\n\nThrall ønsker ikke, at prinsessen kommer til skade, men har i stedet en stor plan, som indebærer, at hun bliver sikkert bragt tilbage til Jernsmede. Hårdan ved allerede alt dette... Af sted!", p="Hvad fører dig til disse hellige grunde?", c="Dette er en chance for Horden til for altid at ændre den politiske situation i vores krigshærgede verden. Lyt nøje, <Name>.\n\nFiasko i denne mission er ikke en mulighed."},
  [4002] = {n="Østkongerigerne", l="Tal med Thrall, hvis du er klar til at tage missionen, han har planlagt.", d="Du bringer fremragende oplysninger, <Name>.\n\nSom Krigshøvding er det min pligt at gøre, hvad der er bedst for Horden. For at sikre, at de generationer, der kommer efter os, ikke tvinges til en håbløs tilværelse.\n\nMuligheden for at forme vores fremtidige alliancer er faldet os i skødet. Et træk for at hjælpe dværgene kunne styrke vores forhold i Østkongerigerne betydeligt. Derfor må du ikke fejle!\n\nEr du klar?", c="Der er ingen vej tilbage efter dette punkt, <Name>."},
  [4003] = {n="Den kongelige redning", l="Dræb Kejser Dagrøn Tårissan og befri Prinsesse Moira Bronzeskæg fra hans onde forbandelse.", d="Dette angreb mod Mørkjernsdværgene vil, hvis det lykkes, sende en chokbølge gennem hele deres rige.\n\nPrinsesse Bronzeskæg er under Kejser Tårissans kontrol. For at befri hende må du dræbe kejseren. Vær advaret, din opgave er dobbelt farlig, for Bronzeskæg vil angribe dig uden spørgsmål, mens hun er under kejserens kontrol.\n\nSKAD HENDE IKKE!", p="<Prinsesse Moira krymper sig af frygt.>", c="Hvad har du gjort!"},
  [4004] = {n="Prinsessen reddet?", l="Vend tilbage til Thrall!", d="Du har dræbt min mand, <Race>! Mit barn vil blive født ind i denne verden uden en far.\n\n<Prinsesse Moira peger direkte på dig.>\n\nJeg forsikrer dig om, at dette barn bliver den næste hersker over Jernsmede-riget. Du og dine lige skal jages, til dagene ender, for denne uretfærdige handling.\n\n<Du tror, at Prinsesse Moira måske lider under de resterende virkninger af Tårissans forbandelse.>\n\nLad mig være, <Race>. Jeg er sikker på, at din krigshøvding vil være ivrig efter at høre resultaterne af hans indblanding.", c="<Thrall bliver slået bagover af de oplysninger, du har præsenteret for ham.>\n\nEn ny trussel tårner sig nu op i horisonten. Når Magnies år dvindler, vil vejen blive åbnet for, at dette ufødte Mørkejern kan blive hersker over Jernsmede.\n\nDu har udført det, jeg bad dig om, og for det skal du belønnes.\n\nNu skal du gå, <Name>! Jeg må rådføre mig med Skovanas og Kærne."},
  [4005] = {n="Akvementas", l="Tag Akvors Bog, de Sølvagtige Klør og Jerntræets Hjerte til Tanarisørknen.\n\nBrug Akvors Bog til at fremkalde Akvementas.\n\nNår du har det færdige totem, skal du tage det til J.D. Hyrdehund i Marskalkens Fristed.", d="Tag denne pose med forsyninger med dig til Tanarisørknen. Rejs til Tabt Takkelmester-vig, og led efter en cirkel af sten.\n\nDen østligste halvø er hemmeligheden...\n\nFra denne cirkel alene skal du læse fra Akvors bog; fremkald det eneste væsen, der kan forvandle de genstande, du har samlet, til et totem til at kæmpe mod Flammeløber.\n\nAkvementas vil ikke være glad for at blive vækket, men husk, du skal blive i cirklen, for at han kan forvandle genstandene.", p="Så du er tilbage, hva'? Hmm... Lad mig se på det, <Name>.", c="Flammeløber, siger du...\n\nJa, jeg er klar over, at et stærkt elementar holder til i krateret's brændte centrum. Vi holder alle bare vores afstand; ingen har kunnet trænge igennem den kraftfulde glorie, der omgiver ham. Mange er blevet slynget fra stierne i klipperne ned på jorden nedenunder, når de har forsøgt at møde ham."},
  [4022] = {n="En smag af ild", l="Vis Cyrus Terepentøs det Sorte Drageflugt-skifte, du modtog fra Kalarén Vindklinge.", d="Flyveflokken er bekendt med dit arbejde i Svidende Kløft.\n\nVis det til mig, <Race>. Skiftet, tosse.", p="<Cyrus' øjne danner to flammende kugler.>", c="<Cyrus undersøger skiftet.>\n\nDu har bevist, at du ikke er helt ubrugelig, dødelige."},
  [4023] = {n="En smag af ild", l="Vis Cyrus Terepentøs bevis på din værdi.\n\nDu har en fornemmelse af, at Cyrus allerede ved, at du er uværdig.", d="Du søger Flyveflokken? Fremvis for mig et bevis på din værdi, dødelige.", p="<Cyrus' øjne danner to flammende kugler.>", c="<Cyrus undersøger skiftet.>\n\nDu har bevist, at du ikke er helt ubrugelig, dødelige."},
  [4024] = {n="En smag af ild", l="Rejs til Sortklippe-dybderne og dræb Bæl'Gar.\n\nDu ved kun, at kæmpen holder til inde i Sortklippe-dybderne. Husk at bruge det Ændrede Den Sorte Drageflugt-skifte på Bæl'Gars rester for at fange den Ildende Essens.\n\nReturnér den Indkapslede Ildende Essens til Cyrus Terepentøs.", d="Jeg ønsker at smage den brændende ild fra ildbjerget. At lade Sortklippes smeltede ild løbe gennem hele mit væsen. Den essens, den glødende hede, er det, jeg higer efter.\n\nBæl'Gar holder til i Sortklippes dybder: Et væsen af ren ild, født af Ragnarøs' ild. Dræb Bæl'Gar, og bring mig et stykke af hans indre ild fra hans osende rester.\n\nBrug skiftet på hans rester for sikkert at udvinde den indre flamme.\n\nLykkes du, skal du blive belønnet.", p="Er kæmpen blevet fældet?", c="<Cyrus snupper den ildende essens ud af dine hænder.>\n\nJA!\n\nTag din præmie og forsvind! Væk fra mit syn, øjeblikkeligt!"},
  [4061] = {n="Maskinernes opstandelse", l="Begiv dig til Brændende Stepper og indsaml 10 Brækkede Elementarskår til Hierofant Teodora Mulvadanie.\n\nDu husker, at Teodora nævnte, at golemerne og elementarerne i den region er kilden til disse skår.", d="Maskinerne gjorde sig først kendt for os under vores første togter ind i Svidende Kløft. Ved nærmere undersøgelse opdagede vi, at de blev importeret fra Brændende Stepper, muligvis fra Sortklippe-dybderne. Det er dér, vi har brug for dig, <Name>.\n\nDin første opgave er at begive dig til Brændende Stepper og indsamle elementarskår fra stenautomaterne og de mindre stenskabninger i regionen. Når du har samlet nok, skal du vende tilbage til mig, så vil jeg afgøre, hvor de stammer fra.", p="Tag ikke denne opgave let, <Name>!", c="<Teodora lægger fragmenterne ud foran sig.>\n\n<Teodora undersøger omhyggeligt fragmenterne gennem et enormt monokel.>\n\nInteressant. Ind i det strukturelle fundament af hvert af disse fragmenter er der... initialer."},
  [4062] = {n="Maskinernes opstandelse", l="Tag elementarskår-prøven til Lotvil Sandfærdig.\n\nDu husker, at Teodora sagde, at Lotvil var stationeret i en lejr mod øst.", d="G.L.A.\n\nDet er de 'initialer', der er prentet på elementarskårene. Under initialerne er der et slags rangmærke. Maskinerne, du ødelagde i Brændende Stepper, var af 'Rang IV'. Jeg går ud fra, at det er en ringe rang.\n\nTag denne skårprøve med til Lotvil Sandfærdig i lejren mod øst. Han er en lærd med stort renommé inden for elementarvidenskaberne. Han kan måske hjælpe os i vores søgen.", p="Hvad har du dér, <Race>?", c="<Lotvils ansigt bliver hvidt.>\n\nJeg... jeg kender disse mærker."},
  [4063] = {n="Maskinernes opstandelse", l="Find og dræb Golemherre Argelmakk. Bring hans hoved til Lotvil. Du skal også indsamle 10 Intakte Elementarkerner fra Vredesrøver-golemerne og Krigsbringer-konstruktionerne, der beskytter Argelmakk. Du ved dette, fordi du er synsk.", d="Dette kan ikke være Argelmakk! Argelmakk blev dræbt for ti år siden. Hvordan kan jeg være sikker? Jeg var den, der dræbte ham.\n\nHan var en foragtelig dværg, besat af at vride mit livs værk, så det passede til hans djævelske behov. Det ser ud til, at de onde altid finder en måde at undslippe retfærdigheden på.\n\nHvis dette er Argelmakks værk, så må han tilintetgøres. Jeg får brug for prøver af hans seneste skabninger. Med de rette prøver kan jeg måske stoppe dette oprør. Skabningerne vogter Argelmakk i Sortklippe-dybderne.", p="Var det ham? Var han virkelig i live?", c="Hvad er dette?!? Dette hoved er ikke kød. Dette er en slags mørkejern-skabning: En skygge af Argelmakk - ENDNU en maskine! Jeg mistænker, at din tilintetgørelse af Argelmakk vil være kortvarig, for en anden vil snart rejse sig for at tage 'dens' plads."},
  [4081] = {n="DRÆB VED SYN: Mørkjernsdværge", l="Begiv dig til Sortklippe-dybderne og tilintetgør de modbydelige angribere!\n\nKrigsherre Goretooth vil have dig til at dræbe 15 Ambolt-vrede-vagtsoldater, 10 Ambolt-vrede-vogtere og 5 Ambolt-vrede-fodsoldater. Vend tilbage til ham, når din opgave er fuldført.", d="Efter ordre fra Krigsherre Goretooth, chef for Kargat Ekspeditionskraften:\n\nAlle og enhver af General Vredessmeds styrker i Sortklippe-dybderne skal udslettes.\n\nVredessmeds mænd er ubarmhjertige mordere, ansvarlige for massemordet på K.E.K.s 109. division. Helte advares om at udvise yderst forsigtighed, når de konfronterer disse rå kræfter.\n\nEnhver, der ødelægger den første linje af General Vredessmeds styrker i Sortklippe-dybderne, skal modtage en hyldest.", p="Hvad er der, <Race>? Kan du ikke se, at jeg har en deling at kommandere?", c="Dette første angreb burde give Vredessmed en skavank i bukserne. Nu, afsted, soldat. Jeg har arbejde at udføre, slag at planlægge, fjender at knuse!\n\nTjek efterlysningsplakaterne for mere arbejde."},
  [4082] = {n="DRÆB VED SYN: Højtstående Mørkjern-embedsmænd", l="Begiv dig til Sortklippe-dybderne og tilintetgør de modbydelige angribere!\n\nKrigsherre Goretooth vil have dig til at dræbe 10 Ambolt-vrede-medicinere, 10 Ambolt-vrede-soldater og 10 Ambolt-vrede-officerer. Vend tilbage til ham, når din opgave er fuldført.", d="Efter ordre fra Krigsherre Goretooth, chef for Kargat Ekspeditionskraften:\n\nChefen for K.E.K.s spejderdivision, Stormester Lekslort, er vendt tilbage med nyt om, hvor højtstående Mørkejern-embedsmænd befinder sig. Gennem en låst port nær byens hjerte træner de deres styrker til at slukke vores mænd. Rejs til Sortklippe-dybderne og tilintetgør dem!\n\nFuldførelse af denne mission vil give en hyldest.", p="Dig igen? Jeg må give dig det, <Name>, du er stædig.", c="Vredessmed er uden tvivl... vred. Kom tilbage til mig, når du har modtaget en tredje hyldest, så går vi videre med Operation: Død over Vredessmed. Jeg kan ikke gå i detaljer om, hvad det indebærer, men vær tryg, det involverer, at nogen dør."},
  [4083] = {n="Det Spektrale Bæger", p="Det spektrale bæger svæver i luften, langsomt stigende og faldende... som i takt med et døende hjerte.", c="Ædelstenene laver ingen lyd, når de falder ned i bægerets dybder..."},
  [4084] = {n="Sølvhjerte", l="Indsaml 11 Sølvagtige Klør og 1 Jerntræets Hjerte til Eridan Blåvind i Ondskoven.", d="Jeg kender ikke den, du taler om, <Name>.\n\nMen vær ikke bekymret; hvis din ven var på en rejse for at finde mig, ved jeg godt, hvad han ønskede.\n\nI hjertet af Un'Goro-krateret bor ondskab i sin reneste form. Denne ondskab tager form af et elementar ved navn Flammeløber... beskyttet af en glorie, som ingen kan fjerne...\n\nIngen... undtagen dem med nok magt til at gøre det. Jeg kan lære dig om denne magt, <Name>.\n\nFørst skal du gøre, som jeg beder. Indsaml 11 Sølvagtige Klør og 1 Jerntræets Hjerte fra skabningerne i Ondskoven, og vend så tilbage.", p="Jeg kan fortælle dig mere om den magt, der kræves for at besejre Flammeløber, men først skal du samle de ting, jeg har brug for.", c="Meget godt, <Name>. Jeg kan se, at du er alvorlig omkring at hjælpe din ven."},
  [4101] = {n="Renselse af Ondskoven", l="Bring 15 Blodrav til Arathandris Sølvhimmel i Ondskoven.", d="Planter giver liv til Ondskoven, men selv de lider under fordærvelsens plet. Jeg kender måder at rense dem på, men jeg kan ikke give sådan viden til dem, jeg ikke kender eller stoler på. Bevis over for mig, at du virkelig vil hjælpe Cenarion-kredsens sag!\n\nMod nord ligger Jerntræ-hulerne. Vridetræ-elementarerne, der findes der, er nu hinsides håb om rensning. Jeg beder dig bringe mig deres safte - kaldet blodrav - så jeg kan studere den i håbet om at redde andre former for liv her.", p="Jeg ved, Ondskoven lider, <Name> - jeg lider sammen med den! Jeg må forblive standhaftig i min overbevisning; hvis den viden, jeg besidder, faldt i de forkerte hænder, ville det betyde katastrofe for hele Ondskoven.\n\nBring mig det blodrav, der er hentet fra de dræbte Vridetræ-elementarer, så vil jeg stole nok på dig til at hjælpe mig med at iværksætte en måde at bekæmpe fordærvelsen på.", c="Dette blodrav vil blive brugt til at finde en måde at besejre fordærvelsen, der findes i Ondskoven. Du har bevist for mig, at du er villig til at gøre alt for Cenarion-kredsen. Jeg stoler nu på dig, ven.\n\nDet kan virke underligt, at det at dræbe elementarerne beviste din værdi over for mig, men målet om at redde utallige væsener må retfærdiggøre de midler, vi tager i brug. Du og jeg kan nu fokusere på bevarelsen af liv gennem de salver, jeg kan lave.\n\n<Name>, nu er tiden kommet til at rense Ondskoven."},
  [4102] = {n="Renselse af Ondskoven", l="Bring 15 Blodrav til Majbess Flodbris i Ondskoven.", d="Planter giver liv til Ondskoven, men selv de lider under fordærvelsens plet. Jeg kender måder at rense dem på, men jeg kan ikke give sådan viden til dem, jeg ikke kender eller stoler på. Bevis over for mig, at du virkelig vil hjælpe Cenarion-kredsens sag!\n\nMod nord ligger Jerntræ-hulerne. Vridetræ-elementarerne, der findes der, er nu hinsides håb om rensning. Jeg beder dig bringe mig deres safte - kaldet blodrav - så jeg kan studere den i håbet om at redde andre former for liv her.", p="Jeg ved, Ondskoven lider, <Name> - jeg lider sammen med den! Jeg må forblive standhaftig i min overbevisning; hvis den viden, jeg besidder, faldt i de forkerte hænder, ville det betyde katastrofe for hele Ondskoven.\n\nBring mig det blodrav, der er hentet fra de dræbte Vridetræ-elementarer, så vil jeg stole nok på dig til at hjælpe mig med at iværksætte en måde at bekæmpe fordærvelsen på.", c="Dette blodrav vil blive brugt til at finde en måde at besejre fordærvelsen, der findes i Ondskoven. Du har bevist for mig, at du er villig til at gøre alt for Cenarion-kredsen. Jeg stoler nu på dig, ven.\n\nDet kan virke underligt, at det at dræbe elementarerne beviste din værdi over for mig, men målet om at redde utallige væsener må retfærdiggøre de midler, vi tager i brug. Du og jeg kan nu fokusere på bevarelsen af liv gennem de salver, jeg kan lave.\n\n<Name>, nu er tiden kommet til at rense Ondskoven."},
  [4120] = {n="Fordærvelsens styrke", l="Talo Tornehov ved Lejr Mojasje i Vildalas vil have dig til at dræbe 12 Vredeklo-grizzlyer og 12 Ondpote-hærgere i Ondskoven.", d="Som jæger stræber jeg efter at efterligne de styrker, jeg ser hos mine modstandere. Det er muligt at vende kampen til din fordel ved blot at kende din fjende godt, <Name>.\n\nPå et sted kaldet Ondskoven, nord for Askedalen, er skabningerne blevet forgiftet af et stof kaldet dæmonisk. Bjørnene og ulvene er blevet gjort gale af det, men jeg tror, at de også er blevet endnu stærkere.\n\nAf sted, <Name>. Rejs til Ondskoven og træd disse bæster i møde. Lær selv, om de virkelig er så stærke, som jeg tror.", p="Alt, der rører ved det dæmoniske, udsender et mærkeligt grønt skær... Jeg fornemmer, at det er ondt, men samtidig meget kraftfuldt.", c="Det lyder på dine beskrivelser, som om væsnerne viser en hjernedød vildskab...\n\nVær på vagt, <Name>. Det ville være i din egen interesse at lære mere om fordærvelsen. Kend altid din fjende."},
  [4121] = {n="Prekær Predikament", l="Eskortér din fange, Grumbark Lorkrøv, gennem Brændende Stepper og gennem Sortklippebjerget til Svidningskløften.\n\nDu husker, at Lekslort nævnte, at han ville have sine mænd ventende på den anden side for at tage Grumbark i forvaring.\n\nDu skal også aflevere dine Thorium-lænker til Lekslort.", d="Tror du virkelig, at du kommer frem til dit mødested med mig med en fange i hånden? Forventede du virkelig at bryde ind i en tungt befæstet Sortklippe-fæstning for at fange en eftertragtet genstand af dem uden at advare nogen eller noget om din tilstedeværelse?\n\nDu vil blive ødelagt!", p="Jeg tager dette forræderiske skidt, <Name>.", c="Dine heltedåder vil ikke gå ubemærket hen, <Name>. Du har fortjent denne hyldest. Krigsherren vil tale med dig nu angående den sidste mission."},
  [4122] = {n="Grumbark Lorkrøv", l="Rejs til Brændende Stepper og find Grumbark Lorkrøv. Du husker, at Lekslort nævnte, at han sidst blev set i en enorm Sortklippe-fæstning.\n\nNår du finder Grumbark Lorkrøv, brug Thorium-lænkerne til at binde ham og før ham derefter tilbage gennem Sortklippebjerget til Svidningskløften. Lekslort vil have sine mænd ventende på den anden side for at tage Grumbark i forvaring.", d="Jeg sporede ham over Svidningskløften, gennem bjerget og ind i Brændende Stepper. Den forræder blev taget på fersk gerning, da han gav Sortklippe-orkerne vitale oplysninger om vores daglige drift. Jeg taler om Grumbark Lorkrøv.\n\nHan sidder nu i Brændende Stepper, sikkert under deres beskyttelse - eller det tror han i hvert fald.\n\nTag disse lænker, <Name>. Find Grumbark, læg lænkerne på ham og før ham gennem Sortklippebjerget. Gør du det, er en hyldest din.", c="Kan du ikke se, hvilken magt vi vinder ved at slutte os til Sortklippes legion?"},
  [4123] = {n="Bjergets Hjerte", l="Bring Bjergets Hjerte til Maxwort Overglint i Brændende Stepper.", d="I årevis har jeg eftersøgt en bestemt ædelsten. Den kaldes Bjergets Hjerte, og den er på størrelse med din knytnæve! Mørkjernsdværgene har den låst inde i deres hvælv, og hvor meget jeg end prøver, vil de ikke lade mig købe den.\n\nSå jeg må tage til tvang.\n\nKæmp dig vej til Det Nedre Hvælv i Sortklippe-dybderne, bryd dets hemmelige pengeskab op og tag hjertet. For at gøre det skal du besejre Vagtmand Dødsgreb, og han dukker ikke op, før du har åbnet hver eneste relikkiste i hvælvet!\n\nHeld og lykke.", p="Har du Bjergets Hjerte? For mig er dets værdi uden grænser.", c="Du har hjertet! Fantastisk! Det er endnu smukkere, end jeg forestillede mig!\n\nVær sød, <Name>, tag dette som betaling!"},
  [4124] = {n="Den Savnede Kurer", l="Tal med Ginro Hjertevarm i Fjermåne-fæstningen.", d="En kollega af mig, Ginro Hjertevarm, søger hjælp vedrørende placeringen af en kurer og de pakker, han bar. Det er omkring en uge siden, at kureren forsvandt; vores egne eftersøgninger har været frugtesløse, og vi er kommet i en blindgyde. Desværre har jeg måttet erklære kureren for savnet i aktion.\n\nHvis du har tid og ressourcer til overs, så tal venligst med Ginro. Han burde være her i Stærkefæstet - måske i sine kvarterer.", c="Latro sendte dig til mig, formoder jeg. Selvom jeg tror, at det er en tabt sag på dette tidspunkt, tager jeg imod enhver hjælp, du kan tilbyde. Jeg må indrømme... Jeg bliver glad, når jeg kan falde til ro over denne sag. Hver dag drager jeg ud i Vildalas' vildmark for at lede efter tegn på Rasjal, og hver nat er jeg vendt tilbage med intet at vise for mit arbejde andet end gnoldtænder og skuffelse."},
  [4125] = {n="Den Savnede Kurer", l="Find kurerens båd et sted langs kysten af Vildalas.", d="Det er omkring en uge siden, at Rasjal, kureren, drog af sted mod Thalanår. Han kender Vildalas godt; han har været hos os, siden General Fjermåne førte ekspeditionsstyrkerne hertil. Jeg ved, at hans plan var at tage en robåd ned langs kysten og forsøge at krydse det sydlige Vildalas for at undgå Hordens lejr.\n\nJeg kunne ikke finde hans båd, men måske kan du. Måske er den skjult, eller måske er den sunket. Uanset hvad kan den rumme et spor om, hvor han er. Hvis du finder noget, så lad mig det vide.", c="Du har fundet, hvad der ser ud til at være en forlist robåd. Gennem det lidt mudrede vand ser du huller, der hærger bagbords side; båden er næsten revet i stykker ned til sin simple trækonstruktion. Det, der ødelagde denne båd, forsøgte højst sandsynligt at knække den over. Et lille våbenskjold fra Fjermåne-fæstningen er malet på styrbords side.\n\nI mudderet ved bunden af båden fanger et glimt af noget metallisk dit øje..."},
  [4126] = {n="Hurley Sortånde", l="Bring den tabte Tordenbryg-opskrift til Ragnar Tordenbryg i Kharanøs.", d="Mørkjernsdværgene, anført af skurken Hurley Sortånde, stjal en af Tordenbryggens bedste opskrifter, Tordenbryg Lagerøl. Skurkene! De fortjener ikke sådan et fint brygget øl!\n\n<Name>, jeg har en svær opgave til dig. Gå til Sortklippe-dybderne i Brændende Stepper, ødelæg alle tønder med Tordenbryg Lagerøl, du finder, og bring vores opskrift på Tordenbryg Lagerøl tilbage!\n\nVær venlig at få den opskrift tilbage, selv hvis du må vende Sortklippe-dybderne på hovedet for at gøre det!", p="Har du opskriften, <Name>? Jeg kan ikke holde ud tanken om, at de Mørkejern-dværge drikker min families drik!", c="Du fandt den! Godt gjort! Og jeg håber, at du gav Mørkejern-dværgene og Hurley Sortånde en ordentlig omgang tæsk!\n\nTordenbrygerne står til din tjeneste, <Name>. Du er en helt blandt helte!"},
  [4127] = {n="Bådvrag", l="Vend tilbage til Fjermåne-fæstningen og vis Ginro Hjertevarm den Kasserede Kniv, du har fundet.", d="Når du stryger din hånd hen over mudderet, rører dine fingre ved en knivs hank. Den ser velplejet ud, og det er nok sikkert at antage, at den, der var i båden, måske har tabt den. Måske har det store stykke af den forsvundne båd noget med tabet at gøre.\n\nDu tager kniven og husker, at Ginro Hjertevarm i Fjermåne-fæstningen bad dig vende tilbage til ham med alle fundne spor. Du har dog en fornemmelse af, at du ikke er helt alene i vandet...", p="Velkommen tilbage, <Name>. Jeg håber, at du har fundet et spor om Rasjals endelige skæbne, hvor tragisk den end måtte være.", c="Interessant... Jeg tror, at dette er Rasjals kniv. Siger du, at du fandt den på bunden af vandet sammen med hans båd? Nå, knivens fund alene er måske ikke nok til at forbinde dette med Rasjals forsvinden; vi har dog en ukonventionel mulighed til rådighed for at lære mere.\n\nHar du nogensinde hørt om psykometri?"},
  [4128] = {n="Ragnar Tordenbryg", l="Tal med Ragnar Tordenbryg.", d="Hej, <Name>. Jeg hørte, at Ragnar Tordenbryg er rasende over, at nogen har stjålet hans øl. Han leder efter tapre eventyrere og er villig til at betale rigeligt.\n\nTal med Ragnar, hvis du er interesseret. Han er på Tordenbryg-destilleriet i Kharanøs, i Dun Frostbakke.", c="Du har ret, jeg er rasende! Jeg er blevet røvet! Røvet for en af vores familieopskrifter! Hvordan tør de! Som om jeg ikke havde nok grund til at hade mørkjernsdværgene! Nu... åh... nu skal de have det!"},
  [4129] = {n="Kniven Afsløret", l="Tag den Kasserede Kniv til Quintis Jonesild i Fjermåne-fæstningen.", d="Fæstningens residerende druide, Quintis Jonesild, har nogle... usædvanlige evner. En af dem involverer psykometri - evnen til at afsløre en genstands historie ved berøring. Spørg mig ikke, hvordan han gør det; jeg tilskriver det magi, som jeg hverken forstår eller vil forstå. Jeg ved dog to ting: For det første har jeg set det virke, og for det andet skylder den fyr mig penge.\n\nTag kniven op til Quint i hans lille trætophus her, og sig til ham fra mig, at hans Kalimdør Hold 'Em-gæld bliver betalt, hvis han bruger sin mojo på den kniv.", p="Ginro sendte dig, hva'?\n\nMine psykometriske aflæsninger er ret tærende for psyken... men det er mine tab ved Kalimdør Hold 'Em også. De kalder mig \"Kongen af de Dårlige Beats\" her i Stærkefæstet. Uheldig med kortene... heldig med at mestre naturens hemmeligheder, tror jeg.\n\nUnder alle omstændigheder vil jeg selvfølgelig gøre det. Dette kan være det gennembrud, vi har brug for, for at afdække Rasjals skæbne. Hvis du vil give mig kniven, kan vi komme i gang.", c="Tak, <Name>.\n\nSelvom psykometri ikke er en nøjagtig kunst i nogen forstand, har jeg brugt den tidligere til at give indsigt i situationer, som andre har afskrevet som tabte sager. Jeg tror, at det at bruge den på kniven, du har fundet, vil give os et glimt af, hvad der skete med Rasjal.\n\nDet tager kun et øjeblik, men det er ikke, hvad jeg vil kalde en magi-venlig opgave. Hav tålmodighed med mig her."},
  [4130] = {n="Psykometrisk Aflæsning", l="Tal med Ginro Hjertevarm i Fjermåne-fæstningen.", d="Jeg er stadig lidt ustadig, undskyld. Under alle omstændigheder modtog jeg nogle nyttige syner.\n\nRasjal tager to store læderrygsække fra sin båd og går ind i landet; men han vender tilbage til båden. Jeg ser gnoldskalpe... han løb ind i nogle gnolde - Skovpoterne tror jeg, de kaldes. Han er meget bekymret - næsten angst - over noget. Så meget, at han ikke er opmærksom på vandelementarer, der dannes bag ham. Billederne... stopper der.\n\nJeg må hvile mig, undskyld <Name>. Fortæl Ginro, hvad jeg har set. Han må vide det.", c="Tak for at videregive Quints syner til mig, <Name>. Jeg vil prøve at huske at være lidt mildere over for ham, næste gang vi spiller kort.\n\nRasjal kan holde sine egne i en kamp, og gnolde er ikke noget, der ville gøre ham bekymret - nej, angst. Alligevel kan du og dine måske handle på denne nye information og skabe det gennembrud, vi desperat har brug for."},
  [4131] = {n="Skovpote-gnoldene", l="Søg i Skovpote-gnoldenes lejre i det sydlige Vildalas efter tegn på kurerens ejendele eller kureren selv.", d="Vores \"venner\" Skovpoterne har måske fået Rasjal til sidst, men noget fortæller mig, at det ikke var det, der skete. Alligevel er de det bedste sted at begynde at lede.\n\nJeg ønsker, jeg havde klarere indsigt i, hvad jeg skal gøre, men alt, jeg har lige nu, er 'Søg i Skovpote-lejrene - gå.' Jeg ved, at gnolde beholder de genstande, de finder, og slås om dem; måske fandt de rygsækkene, Quint nævnte. Jeg havde ikke risikeret et frontalt angreb under tidligere eftersøgninger, men med Quints syn på dette siger jeg: gå løs på dem.", c="Fastgjort på et nærliggende træ hænger to store læderrygsække. Hver bærer et lille våbenskjold fra Fjermåne-fæstningen på forsiden af rygsækken..."},
  [4132] = {n="Operation: Død over Vredessmed", l="Rejs til Sortklippe-dybderne og slå General Vredessmed ihjel! Vend tilbage til Krigsherre Goretooth, når opgaven er fuldført.", d="Du har udført et eksemplarisk stykke arbejde, <Name>. Nu er det tid til at sende dig på din sidste mission.\n\nGeneral Vredessmed, Mørkejern-dværgen, der er ansvarlig for at koordinere angrebene på 109. division af K.E.K. og den massive slagtning af vores styrker, skal stilles til ansvar.\n\nDette bliver uden tvivl din hårdeste mission, men lykkes det dig, vil du blive rigt belønnet.", p="Er Sortklippes Slagter blevet gjort af med?", c="Endelig! Skurken er blevet stillet til ansvar! Du er et bemærkelsesværdigt individ, <Name>. Bær denne medaljon som et symbol på din urokkelige hengivenhed over for Horden og K.E.K."},
  [4133] = {n="Vivian Lagrav", l="Tal med Skyggemester Vivian Lagrav i Kargat.", d="Skyggemester Vivian Lagrav har brug for dine tjenester. Hun er i Ødelandene, i orkfæstningen Kargat, og efterforsker rygter om en bestemt brygning, som mørkjernsdværgene i Sortklippe-dybderne har fremstillet.\n\nTal med Vivian. Hun venter på dig.", c="Tak, fordi du kom, <Name>. Dette sted er ikke uden en barsk charme, men det mangler faciliteterne i Apotekeriet.\n\nNok med høfligheder. Til sagen, ikke sandt?"},
  [4134] = {n="Tabt Tordenbryg-opskrift", l="Bring den Tabte Tordenbryg-opskrift til Vivian Lagrav i Kargat.", d="Der går rygter om, at Mørkejern-dværgen Hurley Sortånde har stjålet en opskrift på øl. Dette øl, Tordenbryg Lagerøl, siges at give sin drikker stor styrke og mod. Vi ønsker at studere drikken. Måske finder vi andre anvendelser for dens dyder... anvendelser mere i tråd med De Forladtes mål.\n\nDyk ned i Sortklippe-dybderne, find Hurley, tag opskriften på Tordenbryg Lagerøl fra ham og bring den til mig.\n\nOg for at finde ham må du måske friste ham ved at true hans dyrebare øl.", p="Har du opskriften på Tordenbryg Lagerøl, <Name>?", c="Meget godt. Jeg sender denne opskrift til Apotekeriet for at blive studeret, og med tiden vil vi låse dens hemmeligheder op. En dag kan dværgene i Alliancen opdage, at denne drikkes dyder bliver brugt imod dem!\n\nJeg finder det frygteligt morsomt. Måske har døden en effekt på ens sans for humor... synes du?"},
  [4135] = {n="Det Vridende Dyb", l="Nu hvor Rasjals sidst kendte opholdssted er blevet opdaget, så fortsæt din eftersøgning efter ham eller hans rester i Det Vridende Dyb. Ifølge sedlen ligger det syd for Skovpote-gnoldenes lejre.", d="Inde i rygsækkene er to genstande: den første er en pakke varer, der skulle til Thalanår, og den anden er en hastigt nedskrevet seddel til en ukendt modtager.\n\nSedlen fortæller om opdagelsen af snigende billelignende skabninger syd for gnoldlejrene, på et sted kaldet Det Vridende Dyb. Forfatteren følte behov for at undersøge dem personligt, som om de var en alvorlig trussel mod hele Vildalas. Sedlen er underskrevet \"Rasjal fra Fjermåne\".\n\nDet ser ud til, at du har fundet, hvor Rasjal endte.", c="Du har opdaget en stor kapsel af udenjordisk natur. Kapslens tekstur virker slimet, men hårde fremspring stikker ud fra tilfældige steder på den. Kapslen har højde og bredde nok til nemt at omslutte et humanoide væsen indeni... og ud fra den svage humanoide form, der er synlig gennem kapslens hud, formoder du, at det netop er det, den omslutter."},
  [4136] = {n="Ribbly Skruesprøjt", l="Bring Ribblys Hoved til Yuka Skruesprøjt i Brændende Stepper.", d="Min bror Ribbly har altid været en belastning for sin familie, idet han tager vores penge og spilder dem på den ene plan efter den anden.\n\nNå, hans seneste plan må have været hans værste, for Baron Tyranbrand af Bytteviken har lige sat en pris på stakkels Ribblys hoved. Jeg kan ikke fortælle dig, hvor glade det gør Skruesprøjterne! Vores lille Ribbly er endelig noget værd!\n\nMen nu gemmer han sig dybt nede i Sortklippe-dybderne. Find ham venligst og bring ham til mig!\n\nEller, hvis han ikke vil komme, så er det også fint... bare bring mig hans hoved.", p="Har du Ribbly? Eller i det mindste en del af ham?", c="Aha! Du fandt ham! Og... det ser ud til, at min lille bror ikke ville komme stille og roligt. Det er synd. Jeg ville have elsket at se hans ansigt, da jeg fortalte ham vores planer om at udlevere ham til Tyranbrand.\n\nTak, <Name>. Du har gjort min familie meget glad. Og Ribbly har aldrig set så fredfyldt ud, som han gør nu."},
  [4141] = {n="Muigen og Lariøn", l="Saml 15 Blodblade og vend tilbage til Muigen.", d="Ser du Lariøn derovre? Det er HANS skyld, at vi er her!\n\nJeg sagde til ham, at vi gik den forkerte vej, men ville han lytte? Og kan du tro, at det er ham, der nægter at tale med mig? Nå, indtil han skifter mening, så lad os more os lidt med ham.\n\nHar du lagt mærke til de mærkelige plantelignende skabninger her omkring? De er bare besvær, egentlig, men jeg tror, at hvis de blev trænet ordentligt, kunne jeg få dem til at adlyde kommandoer.\n\nMen først skal jeg bruge nogle prøver til at studere. Tror du, du kunne samle nogle?", p="Lariøn har fået, hvad han fortjener, det er sikkert!", c="Jeg håber, at de ikke voldte dig for store problemer, <Name>. Jeg prøver at holde mig væk fra dem -- de er vilde!\n\nJeg forsøgte at hoppe over en... og blev angrebet! Planter burde bare ikke opføre sig sådan!"},
  [4142] = {n="Et Besøg hos Gregor", l="Tag et Blodblad med til Gregor Bryggespyt i Vildalas.", d="Jeg er ikke helt sikker på, hvad jeg skal mene om dette, <Name>. Planterne... de synes at have en minimal intelligens.\n\nJeg er dog ingen ekspert. Men jeg kender nogen, der er det!\n\nTag mod det nordlige Vildalas, og led efter en gammel ven af mig, Gregor Bryggespyt. Han er ekspert i den slags ting.\n\nJeg er sikker på, at Gregor kan hjælpe os her. Du finder ham ude i vildmarken; han er ikke typen, der bor i en stor by.", p="Jeg bor her ude i skoven... Fredfyldt.\n\nNå, i hvert fald troede jeg, at det ville være. Jeg får flere besøgende herude, end jeg nogensinde fik, da jeg boede i Jernsmede!", c="Blodblad, hva'? Hmmm... Nå, du må hellere forklare planen, så fortæller jeg dig, om jeg kan hjælpe eller ej."},
  [4143] = {n="Ondskabens Dis", l="Saml 5 prøver af Atal'aj-dis, og vend derefter tilbage til Muigen i Un'Goro-krateret.", d="For at sige dig sandheden, <Name>, har jeg aldrig set nogen planter som disse på mine rejser. Måske burde jeg tage en tur til dette krater...\n\nUnder alle omstændigheder tror jeg, at jeg ved præcis, hvad Muigen leder efter -- Atal'aj-dis. Det er forfærdeligt stads, svært at samle, men det er netop, hvad han har brug for for at kontrollere de små monstre.\n\nDu må besøge Det Sunkne Tempel i Sorgmyren. Atal'aj-disen kan samles fra de dybe lurere, mørkeormene eller slimvæsnerne, der findes der. Held og lykke, <Name>!", p="Lariøn taler stadig ikke til mig! Han ved sandelig, hvordan man holder på en vrede.", c="Jeg indrømmer, at jeg er lidt tøvende med at røre ved det stads, <Name>! Men hvis Gregor siger, at det vil virke, så er jeg villig til at prøve!"},
  [4144] = {n="Blodbladsskud", p="Her er planen, <Name>: Gå ud og saml nogle blodbladsskud -- du ved, planterne, der endnu ikke er fuldt udspirede -- og bring dem hertil. Så vil jeg se, hvad Atal'aj-disen kan udrette.\n\nDu tror måske, at jeg er hævngerrig... Faktisk har du ret i det!\n\nSandheden er, at jeg kender vejen ud herfra, men indtil Lariøn vil indrømme, at jeg har ret, bliver jeg lige her!\n\nSå af sted med dig, find de blodbladsskud, og lad os more os!", c="Her går det ikke galt, <Name>! Det her vil få Lariøns opmærksomhed!"},
  [4145] = {n="Lariøn og Muigen", l="Jag 5 Blodbladspiskere, 5 Blodbladstærskere, 5 Blodbladsflåere og 5 Blodbladsfangere for Lariøn i Marskalkens Fristed.", d="Ser du Muigen derovre? Det er HANS skyld, at vi er faret vild!\n\nJeg er den, der kendte vejen, men han insisterede på, at han kendte en genvej, og så endte vi her!\n\nFor at gøre det værre sender han nu sine skøre plantepest hen for at genere mig. Jeg er så vred, at jeg ikke har planer om at tale med ham foreløbig, men disse pester er for meget at klare.\n\nLad os prøve at begrænse hans forsyning først. Gå ud og jag nogle Blodblade, og vend derefter tilbage til mig.", p="Muigen skal undskylde først, før jeg taler med ham igen!", c="Tak for din hjælp, <Name>, men jeg er bange for, at jeg har nogle dårlige nyheder..."},
  [4146] = {n="Knitrer-brændstof", l="Lever den Ulæssede Knitrer og 5 prøver af Atal'aj-dis til Lariøn i Marskalkens Fristed.", d="Du er heldig, <Name>! Jeg har arbejdet på nogle af mine egne eksperimenter, mens Marvin har været væk, og et af dem er en kortrækkende billeknitrer. Med få justeringer burde den være god til at befri dig selv for de Blodbladspester.\n\nJeg kan give dig en af mine knitrer-prototyper, men du skal stadig samle brændstoffet. Du kan få den nødvendige Atal'aj-dis, som knitreren har brug for, i Det Sunkne Tempel. Det er de dybe lurere, mørkeormene eller slimvæsnerne, du skal hente den fra.", p="Det er udmattende, <Name>. De ting vil bare ikke lade mig være i fred!", c="Så Marvin var ikke her? Nå, vis mig alligevel, hvad du har med."},
  [4147] = {n="Marvins Værksted", l="Rejs til Marvin Nitsøgers værksted i Skralleby.", d="Jeg fik et øje på, hvad Muigen lavede, og han dyrker de forbandede ting derovre!\n\nJeg tror, den eneste løsning her er at... nej, ikke gå og tale med ham... Hvad tænker du på? Løsningen er at slå tilbage!\n\nVi får brug for min ven Marvins hjælp, han har et værksted i Skralleby. Jeg er sikker på, at han kan skabe en slags gadget, der kan hjælpe os.", c="Marvin har været væk i meget lang tid nu, <Name>. Han rejste til Tanarisørkenen for at studere nogle af de gamle trolderuiner.\n\nNu, hvad var det, du sagde, du havde brug for?"},
  [4148] = {n="Blodblads-knitreren", p="For at knitreren kan virke, skal den have en prøve af målskabningen. Gå ud i krateret og saml et blodblads-skud. Så kan jeg kalibrere den til at virke på Muigens små venner...\n\nHvis han ikke var så stædig, kunne vi allerede være på vej hjem... Men indtil da må jeg bare vise ham, at hans lille fjollestreg slet ikke generer mig!", c="Det ser ud til, at det her vil virke perfekt, <Name>. Husk nu, hvis du ser nogen af de pester omkring, så tøv ikke med at bruge knitreren!"},
  [4161] = {n="Kaldorisk Opskrift", l="Saml 7 Lille Edderkoppeben til Zarrin i Dolanår.", d="For længe siden blev nattealferne kaldt kaldorei, et navn, der betyder \"stjernernes børn\". At lære om fortiden er et vigtigt skridt på din vej som <Class>, <Name>, så lyt godt efter, hvad jeg har at fortælle dig.\n\nKaldorei har altid været meget stolte af deres harmoniske forhold til naturen. Det betyder, at vi kun tager fra naturen det, der er nødvendigt, og at vi giver tilbage af samme slags. Denne balance har givet os meget, <Name>.\n\nGå ud og saml syv lille edderkoppeben -- ikke mere end det -- og vend tilbage til mig.", p="Husk balancen, <Name>. Jeg ønsker, at du udvikler en forståelse og en stærk empati for de levende skove.", c="Husk altid det, jeg har vist dig i dag, <Name>. Du er en del af den balance, som nattealferne stræber efter at bevare intakt, selv i urolige tider."},
  [4182] = {n="Drageslægtningens Intimidering", l="Dræb 15 Sorte Kuldlinger, 10 Sorte Drageafkom, 4 Sorte Ormeslægtninge og 1 Sort Drake. Vend tilbage til Helendis Flodhorn, når opgaven er fuldført.", d="Livet på Brændende Stepper er gennemsyret af konflikter.\n\nSe bare på dette sted! Vi ved meget lidt om, hvad der skete med disse bygninger, men vi ved, at dette engang, før den store eksplosion, var en del af Rødryg-bjergkæden.\n\nNok klagesang! Vi har et problem, <Name>. Du har måske bemærket drageslægtningene under denne højderyg. Vi har brug for hjælp til at skubbe dem tilbage. Dræb så mange, du kan, og vend tilbage til mig. Lykkes det dig, kan vi måske tale om andre ting.", p="Hvordan går det med drage-jagten?", c="Fremragende slagtning, <Name>. Nu hvor vi ved, at du kan klare dig blandt drageslægtninge, kan vi tale om mere presserende sager."},
  [4183] = {n="De Sande Mestre", l="Rejs til Søshire og lever Helendis Flodhorns Brev til Dommer Salomon.", d="Vi har altid antaget, at sortklippe-orkerne var et produkt af deres barske opvækst. Det, vi har fundet her i deres hjemland, fortæller en anden historie.\n\nDet er faktisk blodtørst og konfliktlyst, der giver dem kraft, men det er den sorte drageflugt, der styrer orkerne fra Sortklippe. Vi mistænker, at det er den sorte drageflugt, der nærer deres raseri og fjendtlighed.\n\nTag dette brev til Dommer Salomon. Han ved, hvad der skal gøres.\n\n<Helendis giver dig et forseglet brev.>", p="Hilsner, <Name>. Har vi mødt hinanden før? Du ser vagt bekendt ud.", c="<Dommer Salomon åbner det forseglede brev fra Helendis og begynder at læse.>"},
  [4184] = {n="De Sande Mestre", l="Rejs til Stormvind og lever Salomons Bønfald til Højlord Bolvar Fordrågon.\n\nBolvar residerer i Stormvind-fæstningen.", d="Dette er dystre nyheder, <Name>. At opdage, at vores dødsfjender blot er brikker i et langt større trusselsbillede, er nedslående. Der er ingen mulighed for, at Søshire kan overleve et angreb fra både sortklippe-orkerne og den sorte drageflugt. Falder Søshire for denne trussel, falder Mørkeshire næste, og hvad så? Guldshire? Stormvind selv?\n\nDu må tage denne information til Højlord Bolvar Fordrågon i Stormvind med det samme! Hvis dette ikke fortjener Stormvinds hjælp, gør intet det, og alt er tabt.", p="Hvad fører dig til Stormvind-fæstningen?", c="Drager? Umuligt!"},
  [4185] = {n="De Sande Mestre", l="Tal med Højlord Bolvar Fordrågon efter at have talt med Dame Katrina Prestør.", d="Salomon tegner et dystert billede. Vi har dog ikke råd til at sende vores tyndt spredte tropper til Søshires undsætning på grund af spekulation. Jeg får brug for beviser for disse påstande, før jeg kan handle.\n\nTal med Dame Prestør, <Name>. Hun er en lærd kvinde og ved meget om drager og drageslægtninge. Hun kan måske kaste lys over denne situation.", p="<Bolvar betragter dig intenst.>", c="<Bolvar støtter hagen i sin hånd, som i dyb tanke.>\n\nSelv om jeg respekterer Dame Prestørs holdning, mener jeg, at der findes en løsning på dette dilemma, som kan berolige os alle."},
  [4186] = {n="De Sande Mestre", l="Tag Bolvars Dekret til Dommer Salomon i Søshire.", d="Jeg vil bemyndige dig som konstitueret stedfortræder for Stormvind, <Name>.\n\nVend tilbage til Dommer Salomon i Søshire og lever dette dekret.", p="Nogen nyheder fra Bolvar?", c="Det kunne have været værre, må jeg sige...\n\n<Dommer Salomon ser dig op og ned.>\n\nDet ser ud til, at Søshires skæbne hviler helt og holdent på dine skuldre.\n\n<Du bemærker, at Dommer Salomon blinker hurtigt. Han ser ud til at græde.>"},
  [4201] = {n="Kærlighedseliksiren", l="Bring 4 Gromsblod, 10 Kæmpesølvårer og Nagmaras Fyldte Hætteglas til Dame Nagmara i Sortklippe-dybderne.", d="Åh, kærlighedens smerter! Min kære Menig Stenkvist er immun over for mine charme. Jeg er afvist! Det er rasende!\n\nDu må hjælpe mig! Vi succubi ved en hel del om kærlighed, og jeg kan lave en eliksir, der kan nedbryde jernmurene omkring Stenkvists hjerte. For at lave den har jeg brug for disse ting: urten gromsblod, kæmpesølvårer fra klippekæmperne i Azsyra og vand fra Golakka-kildernes krater i Un'Gøro. Du kan hælde vandet i dette hætteglas.\n\nVær sød, <Name>, hjælp en stakkels sjæl i hendes jagt på lykke!", p="Har du ingredienserne? Hullet i mit hjerte truer med at sluge mig!", c="Åh, du har gjort det! Nu kan jeg lave min eliksir og bruge den på Stenkvist. Endelig falder han for mine charme!\n\nTak, <Name>. Du er en kærlighedens mester!"},
  [4223] = {n="De Sande Mestre", l="Tal med Marskal Maksvel på Brændende Stepper.", d="<Dommer Salomon sukker.>\n\nDu må vende tilbage til Brændende Stepper, <Name>. Som stedfortræder for Stormvind skal du rapportere til Marskal Maksvel. Held og lykke.", c="<Marskal Maksvel griner.>"},
  [4224] = {n="De Sande Mestre", l="Tal med Lasede John for at høre om Marskal Windsors skæbne, og vend tilbage til Marskal Maksvel, når du har fuldført denne opgave.\n\nDu husker, at Marskal Maksvel bad dig lede efter ham i en hule mod nord.", d="Hvad? Troede du, at du var den første? Hvor mange soldater skal vi miste, før Stormvind handler?\n\nVi havde samlet enorme mængder efterretninger om Sortklippe-truslen, før vi mistede vores øverstbefalende, Marskal Windsor. Med Marskal Windsor forsvandt alle vores dyrebare oplysninger.\n\nDet, vi har brug for, er den dokumentation. Tal med Lasede John, <Name>. Han var sammen med Windsor, da de blev angrebet af et sortklippe-raidparti. Han blev sidst set i en hule mod nord.", p="Har du talt med John endnu?", c="Jeg kunne have advaret dig, men hvad er det sjove ved det?"},
  [4241] = {n="Marskal Windsor", l="Rejs til Sortklippebjerget mod nordvest og gå ind i Sortklippe-dybderne. Find ud af, hvad der blev af Marskal Windsor.\n\nDu husker, at Lasede John fortalte om, at Windsor blev slæbt væk til et fængsel.", d="Så den ubrugelige kujon siger, at Windsor er i live, hvad?\n\nRust dig, stedfortræder, for du skal ud og finde ham. Hvis Windsor er i live, skal du bringe ham tilbage. Er han død, vil jeg have beviser.\n\n<Maksvel griner.>\n\nJeg vædder med, at du er ved at blive træt af at høre det, ikke?", c="Hvor er han! Jeg myrder ham!"},
  [4242] = {n="Forladt Håb", l="Giv Marskal Maksvel de dårlige nyheder.", d="Bolvar er et fjols. Jeg samlede hans dyrebare 'beviser', så jeg kunne proppe dem ned i halsen på ham.\n\nHan er en blind tølpert. Beviset står to fod fra ham, og han ser det ikke.\n\nMine data er tabt. Væk. Uigenkaldeligt.\n\nSkulle jeg nogensinde finde Jernfjende og komme ud af denne labyrint, bliver mit første stop Stormvind, hvor jeg vil placere min hammer mellem det krybdyrs øjne.\n\nLad mig være, <Name>.", c="Han er vist blevet gal.\n\n<Maksvel sænker hovedet i sorg.>\n\nDet er beklageligt, at en engang stolt og adelig kriger er blevet forvandlet til et tossede fjols. Jeg TROR, vi er nået til en blindgyde...\n\nJeg må belønne dig for din indsats indtil nu, <Name>."},
  [4243] = {n="Jagten på A-Mig 01", l="Find A-Mig 01 i Un'Gøro-krateret.", d="Desværre er der sket noget med en af mine største opfindelser. Har du set mekaniske egern? Ja vel. For at komme tættere på aberne i Un'Gøro-krateret skabte jeg en mekanisk ape, der kunne blande sig med dem – jeg kalder hende A-Mig 01.\n\nHun har sigtesten som øjne, så jeg kunne se alt, hvad hun så. Hun nåede Svampeklippen – aberne's hule – lige øst herfra, og der mistede jeg forbindelsen. Det sidste, jeg så, var en af deres alfahanner, der skyndte sig hen for at sige hej til hende!\n\nKan du hjælpe mig med at finde hende?", c="Mens du kigger A-Mig 01 over, ser du to store buler, der skæmmer det, Karna tydeligvis anser for at være et veludført stykke ingeniørarbejde. Den ene bule pynter A-Mig 01's skulder, den anden sidder på hendes hoved.\n\nDer ser ikke ud til at løbe nogen strøm gennem hendes komponenter, da du undersøger yderligere."},
  [4244] = {n="Jagten på A-Mig 01", l="Find et Mithril-hylster og vend tilbage til A-Mig 01 i Un'Gøro-krateret.", d="Et lille nærmere eftersyn afslører et panel, der kan skydes op. Tydeligt skrevet over nogle ledninger står der: \"Udskift Mithril-hylster og sluk, og tænd derefter igen.\"\n\nDu tager et øjeblik på at udskifte panelet og undrer dig over, om det mon er så simpelt at reparere A-Mig 01 og få hende tilbage til Karna Rejsfred ved Marskalkens Fristed.\n\nKun et forsøg vil vise det.", p="Panelet, hvor Mithril-hylsteret skal sidde, er stadig lukket. Resten af A-Mig 01 er stadig inaktiv.", c="Du fjerner panelet fra A-Mig 01's ryg endnu en gang og tager forsigtigt det gamle Mithril-hylster ud, som ser ud til at være brændt ud. Det nye glider nemt på plads. Det eneste, der står tilbage at gøre – forudsat at Mithril-hylsteret var problemet – er at slå kontakten til \"Fra\" og derefter tilbage til \"Til\"."},
  [4245] = {n="Jagten på A-Mig 01", l="Eskortér A-Mig 01 tilbage til Karna Rejsfred i Un'Gøro-krateret.", d="For at kontrollere, om du er klar til at lede A-Mig 01 tilbage til Karna Rejsfred, slår du kontakten til \"Fra\". Du kigger rundt endnu en gang for at sikre dig, at ingen af gorillaerne kommer, og gør dig klar til at se, hvad der sker, når du slår kontakten tilbage til \"Til\".\n\nDette er din sidste chance... er du sikker på, at det er det, du vil gøre?", p="Har du kunnet hjælpe A-Mig? Det Mithril-hylster, du nævnte, der var ødelagt, var et godt gæt på, hvad der var galt. Jeg er sikker på, at hvis du udskifter det, vil hun genaktiveres og kunne komme hjem.", c="Åh, du har gjort det! Vidunderligt! Tak, <Name>.\n\nÅh, min stakkels A-Mig. Se alle de buler. Vi får hende i gang igen og helt i orden med lidt arbejde.\n\nTak igen, <Name>. Jeg sætter virkelig pris på det."},
  [4261] = {n="Oldtidens Ånd", l="Eskortér Arei i sikkerhed, og tal derefter med Kayneth Stillevind i Skovsang, i det østlige Askedalen.", d="Ondskoven var engang et fredfyldt og stille land... Indtil Legionen fik fat. Infernalerne, ødelæggelsen, kaosset...\n\nGul'dæns kranie sørgede for, at ingen blev skånet her. Alle faldt for fordærvelsen.\n\nSelv nu, som en ånd, finder jeg mig selv fanget og bærer på dette lands lidelse. Hjælp mig med at finde vej hjem. Vær så venlig, <Name>, fortæl mig, at du vil lede en oldtidens ånd væk herfra, hvor jeg endelig kan hvile.\n\nNår jeg er fri, så led efter Kayneth Stillevind, en druide, der bor i Skovsang mod øst.", p="Hvad har du set i dette fordærvede land?", c="Ja, <Name>. Ondskoven har været igennem meget modgang. Tak for det, du har gjort.\n\nEn dag kan vi måske genvinde Ondskoven fra fordærvelsen; hver venlig handling hjælper."},
  [4262] = {n="Overmester Pyron", l="Dræb Overmester Pyron og vend tilbage til Jalinda Kvist.\n\nDu husker, at Jalinda talte om, at Pyron vogtede stenbruddet. Måske bør du lede der?", d="De sidste fem af mine magikere, der snusede rundt i Sortklippebjerget, kom tilbage ekstra sprøde med en permanent orange gnomefrost – eller værre.\n\n<Jalinda samler noget aske op fra jorden og slipper det ud i luften.>\n\nEt særligt grimt bæst, Overmester Pyron, ser ud til at skabe en del problemer. Vi må have det elementar udryddet, så vores ekspeditionsbesætning kan komme ind i Sortklippe-dybderne!\n\nHan vogter indgangen ved Sortklippe-stenbruddet.", p="<Jalinda ser ud til at stirre på dit hoved.>", c="Brandius? Åh kære..."},
  [4263] = {n="Brandius!", l="Find Herre Brandius i Sortklippe-dybderne, og tilintetgør ham!", d="Er du sikker på, at Pyron sagde 'Brandius', da han døde?\n\n<Jalinda synker en klump.>\n\nHerre Brandius skulle være en håndlanger for Ragnarøs! Åh kære, åh kære... hvad skal vi dog gøre?\n\nTror du, at du kan klare endnu en mission? Jeg har ingen andre at sende, <Name>!\n\nVi får aldrig et hold ind, hvis Brandius bliver ved med at rejse Pyron fra asken.\n\nDu må finde og tilintetgøre Herre Brandius!", p="Er djævlen død??", c="Åh kære! Er du sikker på, at Brandius sagde 'Ragnarøs'?\n\n<Jalinda rækker dig noget og klapper dig på håndleddet, mens hun glider hen i dyb tankevirksomhed.>"},
  [4264] = {n="En Krøllet Seddel", l="Du er måske lige snublet over noget, Marskal Windsor ville være interesseret i at se. Der er måske alligevel håb.", d="Seddelen er plettet over hele overfladen. Teksten er knap læselig, men du kan tyde følgende:\n\n...sød ironi...\n\n...det faldne Alliances undergang...\n\n...hvis det ikke var for General Vredessmeds flid, havde vi måske aldrig opdaget mønsteret i krypteringen...\n\n...Argelmakk er næsten færdig med at afkode Windsors noter.\n\nVores herre skal stige op af dybderne og knuse enhver, der er tilbage...\n\n-Kejser Dagran Thaurissøn.", p="<Marskal Windsor kigger på seddelen i din hånd.>\n\nHvad har du dér, <Name>?", c="<Marskal Windsor tager seddelen og begynder at læse.>"},
  [4265] = {n="Befriet fra Bistokken", l="Befri Raschel fra Zukk'asch-bistokken.\n\nVend tilbage til Ginro Ildtænd i Fjermåne-fæstningen, og lad ham vide, at Raschel er i live og har det godt.", d="Kapslen åbner sig lidt, da du rører ved den, og afslører en natteelvermand, der overraskende nok stadig er i live. Han ser ud til at være ved godt helbred, men er dybt chokeret. Mens du hjælper ham ned fra kapslen, vågner han op.\n\n\"Tak, Elunie – du har reddet mig, ven! Jeg... jeg er Raschel, og jeg vågnede lammet inde i denne kapsel, efter at disse insekter overmandede mig. Blev du sendt af fæstningen?\"\n\nDet ser ud til, at du har fundet den savnede kurer!", p="Har du noget at rapportere, <Name>?", c="Velkommen hjem, <Name>. Raschel meldte sig for lidt siden og fortalte mig, hvad der skete.\n\nJeg... nej, hele fæstningen kan ikke engang begynde at takke dig for din store gerning; Raschel ville være død uden din rettidige hjælp, og din assistance kom til os uden så meget som hvisken om et lejesoldat-honorar. Du bærer en sand helts mærke. Vid, at du altid vil have en ven i Ginro Ildtænd."},
  [4266] = {n="En Helts Velkomst", l="Tal med Shandris Fjermåne i Fjermåne-fæstningen.", d="<Name>, General Shandris Fjermåne ønsker at tale med dig personligt. Ingen tvivl om, at hun vil takke dig for din tjeneste for fæstningen, men jeg ved også, at hun vil tale med dig om de insektvæsener, du og Raschel mødte i det sydlige Vildalas. Rapporterne om disse Zukk'asch-insekter er... skræmmende, for at sige det mildt.\n\nGeneral Fjermåne venter på dig i hovedkomplekset.", c="<Name>, jeg takker dig af hjertet for den hjælp, du har givet os. Din tapperhed over for overvældende odds fortjener en belønning, der er tusind gange større. Ikke desto mindre håber jeg, at du modtager denne på hele fæstningens vegne.\n\nNu, hvis jeg må... Jeg vil gerne bede dig om din hjælp endnu en gang. I lyset af opdagelsen af Zukk'asch-bistokken her i Vildalas, mener jeg, at du er det bedste valg til denne mission."},
  [4267] = {n="Silitidernes Opstandelse", l="Bring Raschels Rapport til Gracina Åndsmagt i Darnassos.", d="Jeg betror dig en kopi af rapporten, Raschel skrev om angrebet i det sydøstlige Vildalas. Mens hovedrapporten bliver indgivet i Darnassos, vil jeg have, at du giver denne kopi til en medarbejder i Beskyttelsesrådet. Hendes navn er Gracina Åndsmagt; hun er en præstinde, der bor i Månens Tempel i Darnassos. Hun har bred viden om disse slags væsener, og at hun modtager denne rapport, vil gavne os alle.\n\nDu er afskediget – held og lykke, <Name>; må Elunie vogte over os alle.", p="Velkommen til dette velsignede tempel, ven. Din ankomst hertil fra Fjermåne-fæstningen er blevet forudsagt for mig. Har du den rapport, Shandris Fjermåne bad dig tage med?", c="Vi natteelfer kender til rædslen, der beskrives i denne rapport. Shandris var klog, da hun sendte denne – og dig – til mig.\n\nDisse væsener vil fortære Vildalas hurtigt; de er uden tvivl en af de største trusler, vi alle nogensinde kommer til at stå over for. Insekterne, du og kureren stødte på, kaldes silitider. De er blot redskaber for en af de største trusler, både Horden og Alliancen nogensinde vil stå over for.\n\nJeg beder til, at vi har viljen til at besejre dem, før de ødelægger os."},
  [4281] = {n="Thalanår-leveringen", l="Bring den uleverede pakke til Falfindel Vejvildfarer i Thalanår.", d="Denne pakke med varer, du fandt i Træpote-hyænemandslejrene, skulle leveres til den lille rastestation Thalanår i det sydøstlige Vildalas. Uanset den savnede kurers skæbne er opgaven med at levere pakken stadig uafsluttet.\n\nNår man undersøger pakken nøje, ses et håndskrevet navn \"Falfindel Vejvildfarer\" på ydersiden af emballagen. Måske er dette pakkens endelige modtager.", p="Velkommen til Thalanår, <Class>. Har du brug for hjælp af en art?", c="Elunie være lovet, leveringen fra Fjermåne-fæstningen er endelig ankommet!\n\nDin tilstedeværelse her indikerer for mig, at en ond skæbne måske har ramt Raschel, vores sædvanlige kurer. Jeg håber, at alt går godt. Jeg ved, at Træpoterne for nylig er blevet meget oprørte af en kilde mod deres syd. Måske er han faldet for vildmarken derovre; vær forsigtig, ven.\n\nUanset hvad, tak igen. Her er betaling for denne pakkes levering."},
  [4282] = {n="Et Skår af Håb", l="Returner Marskal Windsors Tabte Information.\n\nMarskal Windsor mener, at informationen holdes af Golemlord Argelmakk og General Vredessmed.", d="<Marskal Windsor ryster seddelen begejstret.>\n\nForstår du, hvad det betyder, <Name>?\n\nMåske er alt ikke tabt! Så vidt jeg kan se, holdes informationen af to Mørkejern-dværge: General Vredessmed og golemlorden Argelmakk. Jeg har en fornemmelse af, at de ikke bare giver informationen fra sig, hvis vi spørger pænt.\n\nJeg håber, du er klar til kamp.\n\nDrag afsted og find disse to skurke! Tilintetgør dem og returner mine tabte oplysninger.", p="Snart er denne store skjulte operation forbi.", c="<Marskal Windsor snupper de to tavler fra dine hænder.>\n\nVi må komme herfra!"},
  [4283] = {n="FEMTI! JA!", l="Oralus vil have 50 Sortklippe-medaljer. Der er stor chance for, at disse medaljer kan findes på orkerne i Brændende Stepper.", d="Jeg vil fortælle dig en lille hemmelighed, soldat. Kom lidt tættere på.\n\nJEG ER DEN ENESTE NORMALE HER!\n\nSe på disse mennesker! Kan du tro, at de alle er skøre!? Det er de! GALE! SINDSSYGE!\n\n<Oralus sænker stemmen.>\n\nLad os holde det mellem dig, mig og min ven Kaptajn Blinke.\n\n<Oralus griber fat i luften og klemmer.>\n\nAnyhoooo... Jeg samler mærker til at passe sammen med min oger-øresamling. Ork er dagens smag. Femti. KOM AFSTED!\n\n<Oralus blæser i et horn.>\n\nAFSENDT!", p="<Oralus taler ind i et ret stort, afhugget oger-øre.>\n\nBrændende Stepper til kontrol, kom ind, kontrol.", c="Du har gjort det! Din belønning er: GNID MIG PÅ MAVEN! KOM NU! GNID DEN!"},
  [4284] = {n="Kræfternes Krystaller", l="Saml 7 Kraftkrystaller i hver farve: rød, blå, gul og grøn. Bring dem til J.D. Hyrdehund ved Marskalkens Fristed.", d="Jeg er sikker på, at du har lagt mærke til dem, <Name>. De er overalt!\n\nHvad taler jeg om? Jo, krystallerne, selvfølgelig!\n\nKrystallerne... De findes over hele krateret. De fleste ignorerer dem, men jeg har en underlig fornemmelse af, at de rummer magt. Jeg har lavet eksperimenter med dem her i et stykke tid, men jeg kan ikke finde noget. Nå, det har jeg endnu ikke, i hvert fald.\n\nSig, jeg løber lidt tør for de krystaller, jeg har her -- tror du, du kunne samle lidt flere til mig?", p="Jeg ved bare, at jeg er på sporet af noget her, <Name>!", c="Nu fortsætter jeg mine eksperimenter! Tak, <Name>."},
  [4285] = {n="Det Nordlige Pylon", l="Find ud af, hvor det nordlige krystalpylon ligger i Un'Gøro-krateret.", d="Hvad kan de mon være til? Jeg kan ikke få tanken ud af hovedet!\n\nDet gør mig gal -- at de rygter, jeg har hørt om krystalpylonerne, alle er sande. Kald mig godtroende, men jeg tror som regel på alt, folk fortæller mig.\n\nUnder alle omstændigheder har jeg hørt, at der er et af krystalpylonerne ret tæt på. Et sted mod nord... Find det venligst, <Name>. Jeg ved bare, at de findes.", p="Har du besøgt pylonen, <Name>?", c="Jeg ved, at historierne er sande, <Name>."},
  [4286] = {n="Det Gode Grej", l="Rejs til Sortklippe-dybderne og hent 20 Mørkejern-hoftetasker. Vend tilbage til Oralis, når du har fuldført opgaven. Du går ud fra, at mørkjern-dværgene i Sortklippe-dybderne bærer rundt på disse 'hoftetaske'-opfindelser.", d="Kaptajn Blinke fortæller mig, at Mørkjernsdværgene i Dybderne fik alt det gode grej. Ikke sandt, Blinke?\n\n<Oralis forsøger sit bedste at efterligne en pirat.>\n\nARRR MAKKER! DET ER DET JO!\n\nSå forstår du hvad jeg mener? Du skal derind og bringe mig nogle prøver af det gode grej.\n\nSkynd dig derind og ryst dit pengeskrin!", p="Jeg gider ikke lige nu, <Name>. Blinke og jeg har et møde at deltage i.", c="<Oralis begynder at rode i den bjergstore bunke hoftetasker.>\n\nÅH HERLIGT!\n\n<Oralis stikker sin store næse ned i bunken og snuser.>\n\nLÆKKERT! Se alle de godter!\n\nTag en til dig selv, <Name>. Der er nok til alle."},
  [4287] = {n="Den Østlige Pylon", l="Find placeringen af den østlige krystalpylon i Uengoro-krateret.", d="Under mit ophold her har jeg hørt mærkelige rygter om mystiske pylonner, der findes ude i kraterets vildmark, <Name>. Jeg regner med, at de er ret store, med krystaller, der beklæder deres indvendige sider.\n\nSelvom jeg aldrig har set en, kan jeg ikke lade være med at tro, at rygterne er sande -- og at pylonerne har noget med alle de krystaller at gøre, vi fandt\n\nSå hvorfor hjælper du mig ikke med at stille min nysgerrighed? Angiveligt findes der en i kraterets østlige område. Tror du, du kan finde den?", p="Har du besøgt pylonen, <Name>?", c="Uengoro er et så mærkeligt sted, <Name>. Når du træder ind i krateret, er det, som om du er i en helt anden verden..."},
  [4288] = {n="Den Vestlige Pylon", l="Find placeringen af den vestlige krystalpylon.", d="Mine eksperimenter indtil videre har ikke givet nogen positive resultater, <Name>. Jeg kan ikke lade være med at håbe, at du kan finde en løsning ved at lede efter en af de pylonner, som jeg har hørt findes.\n\nMåske hvis vi kombinerer bestemte farver ved dem... men jeg løber foran mig selv. Lad os først finde dem!\n\n<Name>, undersøg kraterets vestlige område; en pylon skulle befinde sig et sted i det område.", p="Har du besøgt pylonen, <Name>?", c="Der er mange skjulte områder i krateret langs siderne. Prøv at udforske de snoede stier, hvis du ikke kan tænke på andre steder at lede, <Name>."},
  [4289] = {n="Abene i Uengoro", l="Bring 2 Uengoro-gorillapelse, 2 Uengoro-stampepelse og 2 Uengoro-torden-brølerpelse til Stifinder Torva ved indgangen til Uengoro-krateret.", d="Dette krater har mange mærkelige skabninger -- de synes at være ædlere udgaver af de væsener, der findes over hele min hjemegn og videre. Jeg kan ikke forklare det, men dette sted råber om Moder Jord. Jeg hylder hende, hver gang jeg sporer et af hendes smukke væsener over dets dal.\n\nHvis du også ønsker at opleve den oplysning, der følger med en sådan storslået bedrift, så tag mod nord. Der finder du store aber, som er en prøve for enhver dødelig styrke. Bring mig deres pelse... bevis din styrke.", p="Har skabningerne her allerede besejret dig, <Name>?\n\nLad dig ikke afskrække så nemt. At spore og besejre Uengoros aber er ingen simpel opgave, selv for en stor jæger.", c="Så, du har vist dig stærk, stærk nok til at besejre Uengoros store aber -- det er godt. Udfordringen var lille sammenlignet med Lar'korvi, men jeg vil ikke tage en så stor sejr fra dig.\n\nDisse pelse vil lave fine klæder til min stamme. Du har hjulpet mig og vist dig værdig.\n\nFør du begiver dig ud på en ny opgave, lad os hylde Moder Jord og takke ånderne fra de aber, du dræbte -- de må vide, at deres død ikke vil være spildt."},
  [4290] = {n="Lar'korvis Føde", l="Find kadaveret af Lar'korvis friskeste bytte og stjæl et Stykke Tærskadon-kadaver, før du vender tilbage til Stifinder Torva i Uengoro-krateret.", d="Engang for længe siden tog en af mine brødre noget kød fra et af Lar'korvis byttedyr. Han vidste det ikke på det tidspunkt, men Lar'korvi så ham fra skoven. Lar'korvi fulgte min bror i flere dage og ødelagde alt, han rørte ved. Min bror, bange, besluttede sig endelig for at flygte fra krateret og efterlade Lar'korvi bag sig.\n\nLar'korvi dræbte ham ikke langt fra dette sted.\n\nHvis du vil provokere Lar'korvi, så find et friskt bytte af hans og tag noget kød fra det.\n\nVend tilbage til mig bagefter.", p="Tag ikke mine ord let, <Name>. Hvis du virkelig ønsker at møde dette væsen, så skal du være forsigtig... og klog. Det vil kræve en stor styrke og indsigt at lokke Lar'korvi frem og besejre ham.", c="Det her duer fint, <Name>. Det ser ud til, at Lar'korvi spiser godt for tiden. Dog undrer jeg mig over, hvor han fandt et tærskadon i dette område. Mærkeligt.\n\nUanset hvad, jeg vil gemme det her, indtil du er klar til konfrontationen med udyret. Vær ikke bekymret for min sikkerhed -- jeg er sikker på, at du har gjort Lar'korvi så vred, at han ikke vil dræbe mig, før han har smagt dit kød."},
  [4291] = {n="Lar'korvis Duft", l="Bring 2 Ravsaur-feromonkirtler til Stifinder Torva nær indgangen til Uengoro-krateret.", d="Jeg er faktisk overrasket over, at han ikke er kommet efter dig endnu, <Name>. Men det er alt sammen godt, for jeg har en sidste plan, der vil få monsteret til os.\n\nDa Lar'korvi er den dominerende han, har han ret til at parre sig med enhver hun, han vælger -- og han vælger mange af dem. Du vil finde mange ravsaur-æg mod vest herfra. Kom tæt på dem, og du bør provokere et angreb fra hans makker. Hunnerne udsender en forfærdelig lugt fra en kirtel i hovedet, som gør det muligt for hannerne at vide, at de er klar til at parre sig. Bring mig to af disse kirtler.", p="Pas på, <Name>. At komme tæt på en af rederne med æg vil helt sikkert provokere mødrene... selv hvis du allerede har sikret dig en kirtel fra en af dem. Mødrene kan være lige så dødelige som Lar'korvi selv, når de kæmper for at beskytte deres unger. Men hvis du lykkes, så har vi en endelig måde at lokke Lar'korvi ud af skjul på.", c="Ah, fine eksemplarer, <Name>. De to stykker, du har fundet, burde være perfekte til at lokke Lar'korvi ud i det åbne. Jeg kan ikke vente med at se udfaldet af din kamp med monsteret. Han er et enormt væsen med klør skarpe som de fineste klinger. Du vil se ind i hans øjne, og du vil kende døden."},
  [4292] = {n="Lokkemad til Lar'korvi", l="Brug indholdet af Torvas Pung, kald Lar'korvi frem og besejr ham. Bring derefter Lar'korvis Hoved til Stifinder Torva nær indgangen til Uengoro-krateret.", d="Dette bliver den sværeste del, for der er en vis kompleksitet i planen. Mod nord herfra finder du en lille sti ind i bjergene. Det var her, jeg sidst så Lar'korvi. Du vil vide, at du er i det rigtige område, på grund af alle knoglerne fra enorme skabninger, der engang vandrede rundt i nærheden. Tag det kød, du fandt, og læg det der. Gnid derefter denne blanding, jeg har lavet, på kødet. Hvis begge lokkemidler blandes sammen og ikke får Lar'korvi til at komme til dig, så ved jeg ikke, hvad andet der vil.", p="Lad ikke frygten overmande dig, <Name>. Frygt er den store forræder... du skal forblive stærk!\n\nTag kødet, læg det i den lille dal, og brug så kirtlen på det. Først da vil døden komme for dig.", c="Moder Jord være lovet! Du har gjort det! Godt spillet, <Name>. Du har vist dig at være en stor jæger i din egen ret. Din ånd er stærk. Din tapperhed uovertruffen. Og din styrke er blevet forstærket. Jeg bøjer mig for dine evner.\n\nKun de største af mine forfædre kunne have opnået noget så utroligt. Tillykke."},
  [4293] = {n="En Prøve af Dynd...", l="Indsaml Ondskoven-dyndprøver fra et hvilket som helst dynd i Ondskoven. Brug derefter Testudstyret ved siden af Kemiker Fyrig i Underbyen for at se, hvilke af dine prøver der er mest korrumperede. Bring 5 af de Korrumperede Ondskoven-prøver, du finder, til Kemiker Fyrig.", d="Ondskoven er en skov langt mod nord for Ødemarken, endnu længere væk end Askedalen. Der findes dynd overalt omkring vandpytter velsignet af Ondes berøring. Svøben hærgede området med angreb fra Infernaler og andre dæmoniske magier -- dyndet kravlede angiveligt op gennem jorden under disse angreb.\n\nIndsaml prøver af Ondskoven-dynd, så bruger vi testudstyret ved siden af mig til at lave en kontrolgruppe til vores tests mod andre prøver, du indsamler.", p="Jeg skal bruge mindst fem korrumperede prøver til vores kontrolgruppe, <Name>. Fortsæt med at indsamle Ondskoven-dynd, indtil du kan give mig det, vi har brug for. Frue Silvanas har befalet det...", c="Ah, udmærket. Disse prøver vil gøre det fint. Jeg takker dig for din hjælp.\n\nNår vi har indsamlet alle prøverne af dynd, kan vi afgøre mere. Jeg begynder at mistænke, at Frue Silvanas' fornemmelse ikke kun var korrekt, men mere indsigtsfuld, end selv hun kunne have forudsagt. Disse prøver er meget interessante. Bare at se, hvordan de har reageret med mine stoffer... hmm, ja, vi må absolut undersøge det nærmere."},
  [4294] = {n="... og en Omgang Slim", l="Indsaml Uengoro-dyndprøver fra et hvilket som helst dynd i Uengoro-krateret. Brug derefter Testudstyret ved siden af Kemiker Fyrig i Underbyen for at se, hvilke af dine prøver der er renest. Bring 5 af de Rene Uengoro-prøver, du finder, til Kemiker Fyrig.", d="Har du hørt om Uengoro-krateret, <Name>? Det ligger nær Tanarisørkenen, og det er et storslået sted: frodigt, livligt, fyldt med væsener og plantelivet.\n\nDet er dertil, du skal tage hen. Der er nået frem til mig, at stedet ser ud til at være helt uberørt af fremmede hænder. Opdagere er først nu ved at afdække dets hemmeligheder.\n\nJeg vil gerne teste dyndet eller slimen dér. Hvis det er sandt -- at de er ukorrumperede -- så vil jeg gerne se, hvordan sådanne væsener har udviklet sig.", p="Ja, <Name>? Hvordan går søgningen?", c="Virkelig fantastisk, <Name>. Dette Uengoro-krater gemmer på mange flere hemmeligheder, end jeg forventede. Jeg undrer mig over, hvad vi ellers vil opdage, mens vi tester videre.\n\nSimpelthen fantastisk... se på renheden af disse prøver. Jeg undrer mig over, hvad det kan betyde. De synes at være elementare i deres natur, men... noget mere. De minder mig om... om De Gamle Guder. Vi har fundet spor af dem over hele Azerot, og nu undrer jeg mig over, om disse væsener ikke på en eller anden måde er beslægtet med dem.\n\nVi må teste videre."},
  [4296] = {n="De Syvs Tavle", l="Bring Tavleudskriften til Maxwort Overglint i Brændende Stepper.", d="Jeg kom til Brændende Stepper, efter legenderne om De Syv. De var dværge med stor viden og magt, og hvis du har viden og magt, så vil rigdom helt sikkert følge med.\n\nDet er det, jeg vil have. Rigdom!\n\nHvis vi kan lære mere om De Syv, så kan vi måske blive rige sammen. Thaurissøns ruiner skulle angiveligt gemme De Syvs Tavle, som rummer viden om de gamle dværge. Find denne tavle, kopier teksten og bring den til mig. Lad os opdage dens hemmeligheder sammen!", p="Har du skrifterne fra De Syv, <Name>? Har du lært hemmelighederne fra deres tavle?", c="Ah, du fandt tavlen! Og din afskrift er fortrinlig! Er du sikker på, at du er en <Class> og ikke en skriver?\n\nDer er den, <Name>. Her er betalingen, jeg lovede."},
  [4297] = {n="Mad til Lille", l="Bring 5 Sølvmanke-snigerflanker til Agnar Udyrstyrer i Bagland.", d="Sprite-pilere er altædere -- det betyder, at de spiser både kød og planter. Hvis dit æg her skal udklækkes, må vi gøre os klar. Nogle gode lækkerier til disse små fyre er flanker af kød, rå og saftige, tro det eller ej. Jeg har aldrig fundet ud af hvorfor, men det har noget at gøre med Elunes plan for alferne... måske skulle de være beskyttere eller noget, jeg ved ikke.\n\nJeg tager mig af ægget for nu, så hvorfor henter du ikke nogle gode Sølvmanke-snigerflanker til dem, som han kan spise, når han er udklækket.", p="Har du fundet kødet endnu, <Name>? Dit lille æg er næsten klar til at klække. Hvis han ikke får et godt første måltid, så klarer han måske ikke sin første uge, og det ville jeg hate at se ske.\n\nJeg kan ikke lyve for dig, <Name>. Jeg er jaloux på, at du har fået dette æg til at begynde med. Lad være med at få mig til at fortryde, at jeg hjalp dig sådan her.", c="Det her duer fint, og hvis jeg ikke tager fejl, er dit lille æg næsten klar til at klække. Hvordan føles det? Du skal jo være far, ikke? Haha, du troede vel ikke, at du skulle håndtere sådan et ansvar, vel?"},
  [4298] = {n="At Blive Forælder", l="Tal med Agnar Udyrstyrer i Bagland.", d="Åh, han var meget mere klar, end jeg troede...", c="Her, tag ægget... det er bedre, at du har det, så det binder sig til dig og ser op til dig som sin far.\n\nTillykke, <Name>. Du er forælder... på en måde."},
  [4300] = {n="Knogleklingede Våben", l="Bring 8 Hvide Ravsaur-klør til Jes'rimmel i Orgrimgrad.", d="Hmm, måske der være noget, du kan gøre for Hånden, nu da jeg tænker over det. Ja, Jes'rimmel kunne helt bestemt bruge din hjælp.\n\nI Uengoro-krateret er der raptorer med dødbringende klør. Nogle af dem har hvide klør i stedet for sorte som døden. Hånden har... kunder... der kan lide våben smedet af disse klør. Bring mig mange af de hvide klør, så betaler jeg dig godt. Gør du det hurtigt nok, så hjælper jeg dig måske på andre måder.", p="Mine kunder er ikke så tålmodige, <Name>. Har du fået nogen af klørne endnu?", c="Ah, de her duer fint. Tak, <Name>. Og du er her længe, før de har brug for dem... det er godt.\n\nMåske får vi fremstillet et våben til dig af klørene. Hvad siger du?"},
  [4301] = {n="Den Mægtige U'kaa", l="Bring U'kaas Pels til Stifinder Torva ved indgangen til Uengoro-krateret.", d="Mens du har udforsket Uengoro, har jeg set andre ting, som en mægtig jæger som dig ville nyde. Et af dem var et enormt aber blandt de andre gorillaer mod nord. Du har været i den hule før, men denne gang undrer jeg mig over, om du overlever mødet, hvis du accepterer min opgave.\n\nJeg kalder ham U'kaa, og han er en af Moder Jords største sønner, det kan du være sikker på. Besejr U'kaa og bring mig hans pels. Gør du det, så vil jeg forsvare din ret til at kalde dig en stor jæger.", p="U'kaa... udyret var storslået. Enormt og rødt, med tænder på størrelse med dolke. Hans arme tykke som træstammer og hurtige som den bjergløve, jeg nogensinde har set. Du bør anse dig selv for heldig at finde en sådan prøve af tapperhed -- mit folk ville gå generationer uden at se sådan en skabning.", c="Velgjort, <Name>. Jeg er tilfreds. Du har gjort en stor gerning her i dag.\n\nU'kaa var en af de største aber, jeg nogensinde har set. At du har besejret hans styrke, taler godt om din egen styrke... og mod.\n\nDet er kun passende, at jeg giver dig dette som et tegn på respekt. Du har fortjent det."},
  [4321] = {n="At Give Mening", l="Tal med J.D. Hyrdehund om et øjeblik.", d="Oplysningerne, du har givet mig om pylonerne, er meget interessante...\n\nGiv mig et øjeblik til at lave nogle beregninger, <Name>. Tal med mig igen om et øjeblik, og jeg burde kunne give dig svaret, vi har ledt efter.", c="Fint nok, <Name>. Det her er fascinerende... Jeg kan kun håbe, at mine diagrammer er korrekte! Jeg har samlet alt i denne håndbog, som du kan få.\n\nJeg tror, jeg nu kan besvare alle dine spørgsmål om krystallerne, <Name>."},
  [4322] = {n="Fængselsbrud!", l="Hjælp Marskal Windsor med at få sit udstyr tilbage og befri hans venner. Vend tilbage til Marskal Maksvel, hvis du lykkes.", d="Vi må komme herfra, <Name>. Hjælp mig med at få mit udstyr tilbage fra forsyningsområdet og befri mine venner. Hvis vi kommer ud herfra, skal du tage til Morgans Vagt og tale med Marskal Maksvel. Han vil give dig yderligere instrukser.", p="Du ser udmattet ud, <Name>. Måske skulle du tage plads ved bålet og slappe af.", c="Forbløffende, <Name>. Simpelthen forbløffende. Windsor stormede forbi her for ikke fem minutter siden. Han fremsætter nogle store påstande, men hævder, at de er støttet af hans beviser. Han er på vej til Stormvind nu for at konfrontere Bolvær og ... Dame Prestør."},
  [4324] = {n="Yuka Skruetap", l="Tal med Yuka Skruetap i Brændende Stepper.", d="Selvom min lillebror Ribbli har været uduelig hele sit liv, tror jeg, at han endelig har en vis værdi! Men... vi kan få brug for din hjælp til at udnytte Ribblis nyfundne værdi.\n\nMin søster Yuka har ledt efter ham i flere uger og sporet ham til Brændende Stepper. Hun sendte bud til mig og bad om nogle lejede hænder.\n\nSå, hvad siger du? Vil du hjælpe? Hvis ja, så tal med min søster. Du finder hende gemt i Flammevåbenskjold, en hule nordvest for Rædselsslæggen-stenen.", c="Ja, jeg leder efter min bror. Vi må finde ham og hente ham, Gud velsigne hans hjerte.\n\nMen hvis vi ikke kan bringe alt af ham tilbage... så må hans hoved være nok."},
  [4341] = {n="Hårdan Mægtighammer", l="Rejs til Sortklippe-dybderne og find Hårdan Mægtighammer.\n\nKongen nævnte, at Hårdan blev holdt fange dér -- måske skulle du prøve at lede efter et fængsel.", d="Du har været i Thaurissøns smøgende ruiner? Mødte du tilfældigt en elendig tølper ved navn Hårdan Mægtighammer? Dværgen, der angiveligt holdt øje med min lille pige!\n\n<Kongen hulker.>\n\nOg nu er hun væk, <Name>!\n\nJeg har fået mine mænd til at vende Stepperne på hovedet. Den eneste ledetråd, de har om min datters opholdssted, er, at hun måske er inde i Dybderne. For alt, jeg ved, kan hun være død!\n\nHårdan holdes angiveligt fange dér... find ham! Jeg vil have svar!", c="Lad mig forklare."},
  [4342] = {n="Hårdans Historie", l="Lyt til Hårdan Mægtighammer, mens han fortæller sin historie.", d="Hør mig venligst, før du dømmer!", p="Lad mig afslutte min historie.", c="Som du kan se, var der intet, jeg kunne have gjort."},
  [4361] = {n="Bæreren af de Dårlige Nyheder", l="Vend tilbage til Jernsmede og lever de dårlige nyheder til Kong Magni Bronzeskæg.", d="Du skal tage disse oplysninger med tilbage til Kong Magni, <Name>. Han ved, hvad der skal gøres!", c="<Kong Magni slår sin knytnæve ned i vrede.>"},
  [4362] = {n="Rigets Skæbne", l="Vend tilbage til Sortklippe-dybderne og red Prinsesse Moira Bronzeskæg fra kejser Dagran Thaurissøns onde kløer.", d="Det ser ud til, at min gamle modstander, Dagran Thaurissøn, har mig og Jernsmedes rige i sin nåde.\n\nDu er måske mit sidste håb, <Name>. Du skal redde min kære datter, Moira!\n\nDer er kun én måde at sikre sig, at den besværgelse, Thaurissøn har lagt på Moira, bliver brudt: Dræb ham.\n\nOg <Name>, skad hende ikke! Husk, at hun bliver kontrolleret af Thaurissøn! De ting, hun måske gør eller siger, er et resultat af Thaurissøns onde besværgelse!", c="<Prinsesse Bronzeskæg græder over tabet af kejser Dagran Thaurissøn.>\n\nHvorfor???"},
  [4363] = {n="Prinsessens Overraskelse", l="Vend tilbage til Jernsmede og tal med Kong Magni Bronzeskæg.", d="Thaurissøn var en stor og ærefuld dværg. Du ødelagde mit liv og mit ufødte barns liv!\n\n<Du tror, at Prinsesse Bronzeskæg måske stadig lider under kejserens besværgelses restvirkninger.>\n\nVend tilbage til Jernsmede og fortæl min far, at arvingen til Jernsmedes rige bliver en Mørkejern-dværg.\n\nOm han godkender det eller ej, skal det være.", c="<Kong Magni Bronzeskæg er synligt oprørt.>\n\nDet ser ud til, at Thaurissøn selv i døden har vundet.\n\nDu er afskediget, <Name>. Før du går, kan du vælge din belønning fra det kongelige hvælv.\n\n<Kong Bronzeskæg synker ned i sin trone for at overveje denne bizarre vending af begivenhederne.>"},
  [4421] = {n="Jadeildens Fordærvelse", l="Dræb 11 Jadeild-ondsvorne, 9 Jadeild-skyggesnigere, 9 Jadeild-skurke og Xavatrås. Vend tilbage til Eridan Blåvind i Ondskoven, når opgaven er udført.", d="Ikke mange søger eventyr her... Ondskovens fordærvelse er udbredt og vilkårlig.\n\nSom medlem af Smaragdkredsen søger jeg at hele dette land, men der er nogle, der ønsker, at det skal ulme.\n\nDem, jeg taler om, er Jadeild-satyrerne, der bor mod nordvest herfra, ved Konstellas-ruinerne. Ledet af en særligt grusom satyr ved navn Xavatrås fortsætter de med at sprede sygdommen til alle skabninger, de møder.\n\nVi må forsvare dette land, der engang var vores. Besejr Xavatrås og ødelæg hans håndlangere.", p="Fordærvelsen her driver skabningerne til vanvid...", c="At rydde Ondskoven for Xavatrås er kun det første skridt i en lang proces. Det vil kræve meget arbejde at reparere den skade, der er blevet forvoldt her.\n\nJeg fornemmer, at der er noget langt større end blot satyrerne på spil her, men vi vil kun kende sandheden med tiden..."},
  [4441] = {n="Ondbundne Oldtidsfolk", l="Rejs til Darnassos og brug Eridans hætteglas til at samle et Hætteglas med velsignet vand fra Månens Tempel. Vend tilbage til Eridan med det fyldte hætteglas.", d="Fløjten, du fandt, var udskåret af en gammel beskytter, de loyale trækæmper, der altid har beskyttet nattealferne.\n\nSatyrerne har været i stand til at korrumpere alt, de kommer i kontakt med, herunder de oldtidsfolk, der gjorde Ondskoven til deres hjem. Ved brug af onden er oldtidsfolkets ånd blevet bundet og torteret og aldrig helt frigivet. Ondbindingen, du fandt, er uden tvivl relateret.\n\nVi må prøve at rense fløjten, <Name>. Bring mig velsignet vand fra Månens Tempel i Darnassos.", p="Vandet vil forhåbentlig frigive oldtidsfolkets ånd og give den fred.", c="Tak, <Name>. Nu må vi bede om, at vi kan gøre skaden ugjort..."},
  [4442] = {n="Renset!", l="Tal med Eridan igen om et øjeblik.", d="Ved hjælp af Elunes vand vil jeg forsøge at rense fløjten. Vi må få ende på denne lidelse...\n\nMå Elunie lede mine hænder og mit hjerte.\n\nTal med mig igen om et øjeblik.", c="Med det velsignede vand kunne jeg bryde forbindelsen mellem fløjten og oldtidsånden. Jeg tror dog, at hvis du brugte denne fløjte på et helligt sted, kan du måske kalde oldtidsåndene frem.\n\nMåske skulle du prøve ruinerne i den sydlige del af Jerntræ-skoven. Mange fordærvede trækæmper boede engang her, og det er muligt, at de stadig opholder sig der, selv i åndeform."},
  [4449] = {n="Fanget!", l="Dræb 8 Mørkjerns-geologer og bring 15 stykker Silkestof til personen låst inde i latrinen i Svidningskløften.", d="Hey! Hey, du der! Kom herover!\n\nDu må hjælpe mig lidt. Jeg var på flugt fra Mørkjernsdværgene, og jeg gemte mig herinde for at komme ude af syne. Pokkers forbandede geologer og deres magiske krumspring! De må have set mig gemme mig, for næste ting jeg vidste, så låste de døren og stak mig herind.\n\nLær de geologer en lektie! Åh... og kan du skaffe mig nogle stykker silkestof til... til... ingenting.", p="Jeg har ikke hele dagen! Skaf mig de stykker silkestof! Altså geologerne. Fat de geologer! De fortjener at mærke min, øh... din vrede.", c="Åh, det her er fantastisk! God fornemmelse i det også!\n\nHva'? Åh, ja... geologerne. Fik du fat i dem, hva'? Jeg kan ikke takke dig nok, <Name>. Det giver mig noget tid til at gøre færdig herinde... Tak igen, <Name>."},
  [4450] = {n="Hovedbogen fra Tanaris", l="Tag kopien af Godståls Regnskabsbog og find de genstande, der står opført i den, før du søger Krinkle Godstål i Tanaris.", d="Åh, ved du hvad? Det minder mig om noget.\n\nVil du gerne færdiggøre et lille job, jeg påtog mig, mens jeg var i Tanaris? Det er nemt...\n\nKrinkle Godstål i Gadgetbyen ledte efter nogle sager, der findes her i Svidningskløften og et par andre steder. Kunne du måske kigge på listen og så bringe det hele til ham?\n\nJeg skubber bare hans regnskabsbog ind under døren, hvis du er interesseret. Tag den, og de ting han vil have, tilbage til ham, når du har samlet det hele.", p="Ja, ja? Hvad kan jeg gøre for dig, <Race>? Jeg har alt for travlt, og jeg har mange kunder, der beder om mine tjenester. Måske kan du få tingene til at gå hurtigere. Jeg mener ikke at være uhøflig, men jeg har bare ikke tid, hvis jeg skal nå at indhente alt mit arbejde.", c="Åh, du har set dig nødt til at udføre noget af det arbejde, jeg bad om. Fremragende. Og jeg troede, du ville bede mig fremstille noget til dig.\n\nDet her er alt sammen perfekt... og alting er her. Tak, <Class>.\n\nDet ville måske ikke skade at belønne dig lidt... hmm, hvad ville du synes var nyttigt?"},
  [4451] = {n="Nøglen til friheden", l="Søg i Svidningskløften og find en anvendelse for Snavsesilt-latrinnøglen, du har fundet.", d="Den lille messingnøgle ser simpel nok ud... Det eneste, der ser ud til at få den til at skille sig ud, er nogle ord ridset ind i hovedet på den:\n\n\"Mørkjern-latrin - Må ikke kopieres.\"\n\nDu aner ikke, hvad det betyder, eller hvad det fører til.", p="*hoster*\n\nHvem er det? Kan du ikke se, at jeg har travlt?", c="Jamen, dog! Hvor i alverden!? Du har fundet nøglen! Jeg vidste, at de forbandede Mørkjernsdværgene gemte den, efter at de havde låst mig inde her! Tusind tak, <Name>. Du er den bedste! Nu skal du bare dreje nøglen og lade gamle Locheed komme ud herfra!"},
  [4485] = {n="Adelens Tomus", l="Tal med Dutorian Ralle i Stormvind.", d="Hej, <Name>. Jeg ser, at din hengivenhed stadig er stærk, ligesom din tro.\n\nJeg synes, det er på tide, at du taler med Dutorian Ralle i Stormvind. Der er nogle flere lektioner, du skal lære, og jeg føler, at du er klar.\n\nFind ham i Lysets Katedral, og <Name>, tag disse lektioner alvorligt. Du har opnået din status gennem ydmyghed og hårdt arbejde, så skuffe os ikke ved at blive arrogant.\n\nVær velsignet.", c="Ah, du er vendt tilbage til katedralen, <Name>. Godt. Der er sket meget for nylig, og jeg vil bede om din hjælp, hvis du beviser din værdighed.\n\nMange forræderiske fjender er på færde. Jeg får brug for din hjælp til at stoppe dem."},
  [4486] = {n="Adelens Tomus", l="Tal med Dutorian Ralle i Stormvind.", d="Nå, nå, nå, se på den mægtige paladin i al sin majestæt.\n\nUndskyld, <Name>, jeg mente ingen krænkelse... Jeg bliver bare lidt jaloux nogle gange, når jeg ser nogle af de bedrifter, du har udført. Tiza siger, at det er min svaghed, og jeg lovede hende, at jeg ville arbejde på det. Det er bare svært nogle gange, ved du?\n\nMen grunden til, at jeg ville tale med dig, var, at Dutorian Ralle i Stormvind sendte bud om, at du skulle møde ham i Lysets Katedral, når du er klar. Lød vigtigt. Lød som om, at der er noget på spil.", c="Ah, du er vendt tilbage til katedralen, <Name>. Godt. Der er sket meget for nylig, og jeg vil bede om din hjælp, hvis du beviser din værdighed.\n\nMange forræderiske fjender er på færde. Jeg får brug for din hjælp til at stoppe dem."},
  [4487] = {n="Tilkald Ondhingsten", l="Tal med Strahad Farsøn i Skralleby.", d="Ah, godt, du er her. Jeg sendte en succubus efter dig for at få din opmærksomhed, men det ser ud til, at du nåede herhen, før den fandt dig. Det gør ikke noget.\n\nDer har været noget snak på det seneste om din voksende magt - det er godt for dig, måske dårligt for andre. Men de punkter er irrelevante. Pointen er, at jeg synes, du har bevist dig selv og derfor fortjener... hehe... en slags velsignelse.\n\nOver Skralleby i Ødemarken finder du en mand ved navn Strahad. Jeg tror, I har krydset veje før.", c="Nå, så har du besluttet at nåde mig med din tilstedeværelse igen. Hvor venligt af dig.\n\nMine disciple undrede sig over, om du nogensinde ville dukke op. Jeg sagde dem, at der ikke var nogen tvivl. Når det drejer sig om magt, bliver du draget ind som en møl mod flammen."},
  [4488] = {n="Tilkald Ondhingsten", l="Tal med Strahad Farsøn i Skralleby.", d="Ah, <Name>, du har set dig nødt til at nåde os med din tilstedeværelse. Hvor dejligt!\n\nJeg håber ikke, du forventer, at vi også venter på dig med hånd og fod. Du vokser måske hurtigt i magt, men du er stadig en unghund, når det gælder ægte viden og forståelse. Hvis du ikke passer på, vil korruptionen overvælde dig og din svage vilje.\n\nMen jeg burde komme til sagen: Strahad vil tale med dig. Han opholder sig stadig i sit tårn med udsigt over Skralleby i Ødemarken. Jeg foreslår, at du ikke tøver for længe.", c="Nå, så har du besluttet at nåde mig med din tilstedeværelse igen. Hvor venligt af dig.\n\nMine disciple undrede sig over, om du nogensinde ville dukke op. Jeg sagde dem, at der ikke var nogen tvivl. Når det drejer sig om magt, bliver du draget ind som en møl mod flammen."},
  [4489] = {n="Tilkald Ondhingsten", l="Tal med Strahad Farsøn i Skralleby.", d="Du, <Race>! Kom herhen!\n\nDu er den, de kalder <Name>, ikke?\n\nDet tænkte jeg nok. Jeg holder det kort: du vokser i magt, og det er blevet anerkendt. Og nu er tiden kommet til, at du belønnes for din indsats.\n\nGå til Ødemarken. Der, over Skralleby, finder du Strahad Farsøn - måske husker du ham? Han vil gerne have et ord med dig. Jeg ville ikke tage lang tid om det.", c="Nå, så har du besluttet at nåde mig med din tilstedeværelse igen. Hvor venligt af dig.\n\nMine disciple undrede sig over, om du nogensinde ville dukke op. Jeg sagde dem, at der ikke var nogen tvivl. Når det drejer sig om magt, bliver du draget ind som en møl mod flammen."},
  [4490] = {n="Tilkald Ondhingsten", l="Tal med Strahad Farsøn i Skralleby for at lære evnen til at tilkalde en Ondhingst.", d="Jeg ville give dig en belønning for din tålmodighed og hårde arbejde. Men vid dette: evnen til at tilkalde en Ondhingst bliver meget sværere i fremtiden. Du bliver nødt til at fortjene den... og det bliver ikke let.\n\nNu går du med kraften til at kalde sådan en skabning, og brug den, som du finder passende.", c="Held og lykke, <Name>. Jeg ser frem til at se dig i fremtiden."},
  [4491] = {n="En lille hjælp fra mine venner", l="Før Ringlo til Sprælle Frakke ved Marskalkens Fristed.\n\nHvis Ringlo besvimer, så brug Sprælles feltflaske til at genoplive ham.", d="Uf... Det er så varmt...\n\nJeg udforskede dette område, da varmen pludselig blev uudholdelig. Jeg må lide af hedeudmattelse.\n\nVær sød at hjælpe mig tilbage til min ven Sprælle ved Marskalkens Fristed. Jeg tror, jeg er rask nok til at følge med dig derhen.\n\nJeg har det lidt udenfor, så hvis jeg skulle besvime igen, så stænk bare lidt vand på mig fra Sprælles feltflaske. Det burde virke, håber jeg...", p="Jeg har været så bekymret for Ringlo...", c="Ringlo er ikke i den bedste form, <Name>, men jeg er glad for at have ham tilbage i ét stykke!\n\nTak, fordi du fandt ham."},
  [4492] = {n="Væk!", l="Find Ringlo ved Ildfjer-højderyggen.", d="Du må hjælpe mig, <Name>! Min ven Ringlo tog af sted tidligere for at udforske vulkanen syd for her, og han har været væk alt for længe. Jeg er virkelig bekymret for ham.\n\nTror du, du kunne finde ham? Hvorfor tager du ikke min feltflaske med dig? Hvis du finder Ringlo, er jeg sikker på, at han får brug for den!", p="Hva... Hvad?", c="Åh... Jeg er så glad for, at nogen fandt mig..."},
  [4493] = {n="Silitidernes march", l="Tal med Alkymist Pestlezugg i Gadgetbyen.", d="Det ser ud til, at silitidernes hensigt, nej - formål med at eksistere, er at fortære alt på deres vej, som ikke er en del af deres økologi. Deres fokus er enkelt, og netop derfor er de en alvorlig trussel mod alt liv på Azeroth.\n\nDet, vi har set indtil nu, er kun de første stadier. Jeg har en mistanke om, at deres styrke kommer fra dybere inde i Kalimdør: Un'Goro-krateret. Tag til Gadgetbyen i Tanaris-ørkenen og tal med Alkymist Pestlezugg. Fortæl ham om min teori; han vil helt sikkert hjælpe os med at bekæmpe silitiderne.", c="Ja, jeg forstod på Gracina, at det var dig, hun sendte til mig. Din erfaring med at bekæmpe disse bæster er uvurderlig; så vidt jeg ved, har ingen nogensinde før stået over for deres slags. Hvad Gracinas idé angår, at Un'Goro-krateret er deres hjerte... måske er det. Un'Goro er en mystisk og farlig jungle mod vest herfra. Måske er den også et skridt tættere på at finde ud af, hvad silitiderne går og laver."},
  [4494] = {n="Silitidernes march", l="Tal med Alkymist Pestlezugg i Gadgetbyen.", d="Det ser ud til, at silitidernes hensigt, nej - formål med at eksistere, er at fortære alt på deres vej, som ikke er en del af deres økologi. Deres fokus er enkelt, og netop derfor er de en alvorlig trussel mod alt liv på Azeroth.\n\nDet, vi har set indtil nu, er kun de første stadier. Jeg har en mistanke om, at deres styrke kommer fra dybere inde i Kalimdør: Un'Goro-krateret. Tag til Gadgetbyen i Tanaris-ørkenen og tal med Alkymist Pestlezugg. Fortæl ham om min teori; han vil helt sikkert hjælpe os med at bekæmpe silitiderne.", c="Ja, jeg forstod på Zilzibin, at det var dig, han sendte til mig. Din erfaring med at bekæmpe disse bæster er uvurderlig; så vidt jeg ved, har ingen nogensinde før stået over for deres slags. Hvad Zils idé angår, at Un'Goro-krateret er deres hjerte... måske er det. Un'Goro er en mystisk og farlig jungle mod vest herfra. Måske er den også et skridt tættere på at finde ud af, hvad silitiderne går og laver."},
  [4496] = {n="Rod i junglen", l="Bring en Gorisjisk duftkirtel og 5 prøver af Un'Goro-jord til Alkymist Pestlezugg i Gadgetbyen.", d="Min forskning har vist mig, at silitiderne er ligesom bier; ødelæg dronningen i bistokken, og resten burde blive kastet ud i kaos. Jeg vil brygge et lokkemiddel, som vi kan bruge til at lokke dronningen frem; når hun er tilkaldt, skal du nedlægge hende.\n\nMen først har vi brug for nogle reagenser; vi vil ikke have, at du roder rundt i junglen uforberedt. Gå mod vest for at finde silitidbistokken i Un'Goro-krateret og skaf en duftkirtel fra et af insekterne. Jeg skal også bruge nogle prøver af den hjemmehørende Un'Goro-jord.", p="Det kan tage lidt tid at finde en egnet duftkirtel - kirtlen må ikke beskadiges, og processen med at få fat i en sådan lader sig bestemt ikke gøre let. Hvad jorden angår, må jeg formode, at den burde være let nok at finde.\n\nUnder alle omstændigheder, har du de ting, jeg skal bruge til lokkemidlet?", c="Duftkirtlen, ja. Membranen ser intakt ud - fremragende. Jorden, ja, det her burde gå helt perfekt. Med mine særlige tilsætninger burde jeg kunne male det hele til det perfekte lokkemiddel.\n\nGiv mig et øjeblik til at fremstille lokkemidlet, <Name>. Når det er klar, kan vi sætte det næste trin i værk, som forhåbentlig kan stoppe silitiderne, før de overvælder Gadgetbyen... og resten af Kalimdør."},
  [4501] = {n="Pas på Pterrordaks", l="Dræb 10 Pterrordaks og 15 Rasende Pterrordaks, og tal derefter med Sprælle Frakke ved Marskalkens Fristed.", d="Eftersøges: En dygtig kriger til at tage sig af truslen fra Pterrordaksene, der lever i Un'Goro-krateret. Deres antal vokser, og de er ved at blive en plage for de rejsende i området.\n\nNedsæt bestanden ved at slå 10 pterrordaks og 15 rasende pterrordaks ihjel.\n\nTal med Sprælle Frakke, når du har gennemført opgaven, for at få en belønning.", p="For at sige dig sandheden var jeg egentlig ikke så bekymret over de mærkelige væsener... Indtil dagen, hvor jeg så det skrevet på siden af en stor sten.\n\nPAS PÅ PTERRORDAKS\n\nHvem kan have skrevet det? Jeg ved det ikke, men det er for uhyggeligt til bare at ignorere!", c="Jeg er helt forfærdet over pterrordaksene her! Tak for at nedsætte deres antal, <Name>. Nu føler jeg mig måske tryg nok til at vove mig ud af Marskalkens Fristed."},
  [4502] = {n="Vulkansk aktivitet", l="Saml 9 prøver af Un'Goro-aske fra ildelementarerne omkring vulkanen i Un'Goro-krateret, og bring dem til Liv Rizzlefiks i Skralleby.", d="Som lærling hos Marvin Nitsøger har jeg lært så meget. Men han har været væk i så lang tid nu, så jeg tror, jeg vil gå i gang med nogle eksperimenter på egen hånd.\n\nJeg har for nylig læst om Un'Goro-krateret og den mærkelige vulkanske aktivitet, der foregår midt i krateret. Jeg tror, at man kunne lære meget, hvis jeg bare kunne få noget af asken fra elementarerne dér.\n\nVil du have noget imod at samle nogle til mig, hvis du alligevel er på vej den vej?", p="Er det sandt, at vulkanen i Un'Goro er aktiv? Jeg er sikker på, at jeg kunne lære meget med noget aske fra vulkanen, <Name>.", c="Disse prøver bliver perfekte til mine studier! Tak, <Name>! Jeg lover, at du bliver den første, jeg fortæller om mine opdagelser."},
  [4503] = {n="Shizzles flyvemaskine", l="Saml 8 Spindede Dødemetradonskæl og 8 Spindede Pterrordakskæl til Shizzle i Marskalkens Fristed.", d="Jeg bygger en flyvemaskine!\n\nJeg er strandet her, og jeg er helt forfærdelig til at finde rundt. Jeg ville tage en gryphon eller vindrytter tilbage til Gadgetbyen, men de dyr skræmmer mig fra vid og sans.\n\nSå vil du hjælpe mig? Det eneste, jeg mangler at bygge, er vingerne, og jeg tænkte, at de spindede skæl fra pterrordaksene og dødemetradonen ville være perfekte. Der er ingen måde, jeg vil kaste mig ud i kamp mod en af dem, men du ser ganske tough ud. Hvorfor prøver du ikke?", p="Ethvert stort køretøj har brug for et navn... Jeg tænkte, at jeg ville kalde den... Pwnet!", c="Ja, de her skæl er perfekte. Jeg burde kunne få denne flyver op at flyve med netop disse skæl, helt sikkert!\n\nTak!"},
  [4504] = {n="Superklistret", l="Saml 12 prøver af Superklistret tjære til Tran'rek i Gadgetbyen.", d="Jeg leder altid efter en hurtig måde at tjene en guldmønt på, <Name>. Hvis du hjælper mig med min nyeste idé, giver jeg dig en lille del af overskuddet. Hvordan lyder det for dig?\n\nDet troede jeg nok!\n\nTag til tjæregravene i det nordlige Un'Goro-krater og saml lidt tjære til mig. Ikke hvilken som helst tjære, nu - du skal hente den fra de væsener, der lever omkring tjæregravene. Almindelig tjære er bare ikke klistrende nok.\n\nDe plantelignende væsener har klorofyl i huden, og blandet med tjæren bliver det superklistret!", p="Tran'rek har gjort det igen -- denne superklistrende lim bliver alle tiders!", c="Ja, den her tjære er lige det rigtige...\n\nHey, vent lidt, mine hænder... Jeg kan ikke få dem fra hinanden...\n\nMåske var det ikke en særlig god idé. Men vent! Superklistret tjærefjerner! Der er de rigtige penge!"},
  [4505] = {n="Korruptionens brønd", l="Saml en prøve af korrumperet vand fra Jadeild-satyrernes månebrønd og bring det til Winna Hasard ved Blodgift-posten.", d="Nogle vil måske sige, at jeg er usædvanlig grusom... Men det er virkelig kun et stærkt ønske om at se Horden opnå en fordel over Alliancen, på enhver tænkelig måde.\n\nMin nyeste interesse er en månebrønd ved Constellas-ruinerne, syd herfra, passet af Jadeild-satyrerne. Månebrønden, der engang var et symbol på fornyelse for de utålelige nattealfer, er nu korrumperet og bruges til at frembringe flere satyrer.\n\nJeg har en idé, <Name>, og jeg vil gerne have en prøve af vandet... til min lille kattevens her.", p="Dette er af største vigtighed. Gør dig nu klar til at komme af sted.", c="Meget godt. Vi må finde en måde at bruge denne korruption mod vores fjender..."},
  [4506] = {n="Korrumperede sabler", l="Tag Winnas killing til den korrumperede månebrønd, slip den løs, og bring den derefter tilbage til Winna.\n\nNår du er vendt tilbage til Winna, skal du klikke på katten for at slippe den løs over for Winna.", d="Dette korrumperede vand kan bruges til vores fordel, <Name>. Med blot en lille smule af vandet blev min killing dobbelt så stor, og den virker stærkere... på en eller anden måde. Disse katte kan vise sig nyttige...\n\nHer, <Name>. Tag denne kattebærer og slip killingen løs ved siden af månebrønden i Constellas-ruinerne. He, he... Jeg er sikker på, at du bliver tilfreds med resultatet!\n\nBring katten tilbage til mig, og jeg er sikker på, at jeg kan gøre det umagen værd for dig.", p="Sig mig ikke, at du ikke kan gå tilbage dertil! Kom nu af sted!", c="Fremragende!\n\nDe Forladte vil ty til alle midler for at knuse Alliancen! Brugen af det korrumperede vand vil uden tvivl vise sig nyttig i vores fremtidige indsats..."},
  [4507] = {n="Bonde slår dronning", l="Besejr Gorisjisk Bistokdronning, når hun er tilkaldt.\n\nBring Gorisjisk-dronningens hjerne til Alkymist Pestlezugg i Gadgetbyen.", d="Her er lokkemidlet. Inde i bistoknetværket burde der være en slags krystal. Vi tror, at silitiderne bruger krystallen som en slags bistokdækkende indstillingsanordning. Med hensyn til, hvor denne krystal måske er, vil jeg sige, at du skal prøve yngelkamrene inde i bistokken.\n\nHvis du bruger lokkemidlet på krystallen, bør det lokke dronningen frem, men vær advaret - hun vil sandsynligvis være beskyttet af flere vagter. Fjern dronningen og tag hendes hjerne. Så ækelt det end lyder, må vi desperat studere den. Held og lykke, <Name>!", p="At skaffe dronningens hjerne til vores forskning er absolut afgørende. Ud fra det, vi har lært, tror vi, at disse silitider meget muligt styres af en ondsindet intelligens. Jeg gyser ved tanken om, hvad der kunne kontrollere noget så snigende som silitiderne, <Name>.", c="Fantastisk, <Name>! Vi har vundet en ganske stor sejr her i dag. Det vil tage noget tid, før vi fuldt ud forstår, hvad vi har her; vi vil dog bruge det godt, det skal du ikke bekymre dig om.\n\nMed hensyn til silitiderne tvivler jeg oprigtigt på, at dette var hele omfanget af deres tilstedeværelse. Det her er alt for en ren løsning, må jeg desværre sige."},
  [4508] = {n="Ro før stormen", l="Bring Pestlezugg's Un'Goro-rapport til Gracina Åndsmagt i Darnassos.", d="Mine seneste fund og den viden, vi har fået her i dag, skal nå hænder, der muligvis kan gøre noget med den. Så dygtige, som vi er her i Gadgetbyen, kan vi ikke gøre dette alene.\n\nTag min seneste rapport tilbage til Gracina Åndsmagt i Darnassos; hun er stadig ved Månetemplet, er hun ikke? Hun har venner, der er store skikkelser i Alliancen; hvis vi kan få dem involveret i dette, <Name>, så kommer vi måske helskindede ud af det.", p="De er tosser, <Name>! De kan ikke engang finde på at se sig omkring efter en større trussel; deres irrationelle had til Horden bliver vores undergang. Jeg ved ikke, hvor meget mere bevis jeg kan give dem om silitidtruslen, medmindre jeg smider dem ned i en af bistokkene, så de kan se det selv!\n\nJeg beklager, bringer du nyheder, der kræver min opmærksomhed?", c="Selvom jeg oprigtigt sætter pris på dette, er jeg ikke sikker på, hvad godt det vil gøre os. Alliancen ignorerer trusler fra alle kilder undtagen Horden, og selv vores egne ledere her i Darnassos kan ikke blive enige om, hvad præcist denne trussel er. Tosser som Fandrel Hjorthelm teoretiserer, at silitiderne slet ikke ligner den trussel fra fortiden, som jeg hævder, de er. Hans uvidenhed overgås kun af hans arrogance.\n\nDu har set truslen selv, <Name>. Vi må forblive forpligtet til at besejre silitiderne!"},
  [4509] = {n="Ro før stormen", l="Bring Pestlezugg's Un'Goro-rapport til Zilzibin Trommelore i Orgrimgrad.", d="Mine seneste fund og den viden, vi har fået her i dag, skal nå hænder, der muligvis kan gøre noget med den. Så dygtige, som vi er her i Gadgetbyen, kan vi ikke gøre dette alene.\n\nTag min seneste rapport tilbage til Zilzibin Trommelore i Orgrimgrad; han står stadig på sin plads i den øvre del af Dragen, ikke? Han har venner, der befinder sig højt oppe i Horden; hvis vi kan få dem involveret i dette, <Name>, så kommer vi måske helskindede ud af det.", p="De er tosser, <Name>! De kan ikke engang finde på at se sig omkring efter en større trussel; deres irrationelle had til Alliancen bliver vores undergang. Jeg ved ikke, hvor meget mere bevis jeg kan give dem om silitidtruslen, medmindre jeg smider dem ned i en af bistokkene, så de kan se det selv!\n\nJeg beklager, bringer du nyheder, der kræver min opmærksomhed?", c="Selvom jeg oprigtigt sætter pris på dette, er jeg ikke sikker på, hvad godt det vil gøre os. Horden ignorerer trusler fra alle kilder undtagen Alliancen. Selvom Thrall selv måske ville handle, hvis fakta blev forelagt ham, er han omringet på alle sider af modstridende råd. Disse tosser ville få os til at jagte vores egne indbildte haler, hvis de troede, det kunne fange Alliancen uforberedt!\n\nDu har set truslen selv, <Name>. Vi må forblive forpligtet til at besejre silitiderne!"},
  [4510] = {n="Ro før stormen", l="Bring bankbeviset til Idriana i banken i Darnassos.", d="<Name>, din hjælp har været uvurderlig. Tiden vil uden tvivl komme, hvor jeg beder om din hjælp mod silitiderne igen. Vi må tage ved lære af det, vi har lært i Un'Goro; jeg frygter, at mine antagelser om, at silitiderne stammer fra Un'Goro, nu er forkerte... at der faktisk er en langt stærkere tilstedeværelse et sted.\n\nTag denne seddel til Idriana i banken. Hun giver dig noget fra mit hvælving, som bør ses som et tegn på min taknemmelighed. Tak for din hjælp, modige <Class>.", p="Elune'adore, <Class>. Hvad kan jeg gøre for dig i dag?", c="Denne bankseddel giver mig tilladelse til at hæve en genstand fra Gracina Åndsmagts konto hos os og overrække den til dig. Tillykke synes at være på sin plads!"},
  [4511] = {n="Ro før stormen", l="Bring bankbeviset til Karus i banken i Orgrimgrad.", d="<Name>, vi kunne ikke være kommet så langt uden dig. Tiden vil uden tvivl snart komme, hvor jeg beder om din hjælp mod silitiderne igen. Vi må tage ved lære af det, vi har lært i Un'Goro; jeg frygter, at mine antagelser om, at silitiderne stammer fra Un'Goro, nu er forkerte... at der faktisk er en langt stærkere tilstedeværelse et sted.\n\nTag denne seddel til Karus i banken. Han giver dig noget fra mit hvælving, som bør ses som et tegn på min taknemmelighed. Tak for din hjælp, mægtige <Class>.", p="Zug zug! Hvad kan jeg hjælpe dig med i dag, <Class>?", c="Denne bankseddel giver mig tilladelse til at hæve en genstand fra Zilzibin Trommelores konto hos os og overrække den til dig. Tillykke synes at være på sin plads!"},
  [4512] = {n="En Lille Smule Slim Rækker Langt", l="Bring 6 Fyldte Forbandede Slim-krukker og 6 Fyldte Forurenede Slim-krukker til Larsen Tandhjulsdøvl i Jernsmede.", d="Men det, jeg har studeret mest, er slimvæsener. Jeg ved, det lyder mærkeligt, men de er overalt!\n\nJeg hjalp en dame i Menetil med at finde sin taske for ikke længe siden--den var blevet spist af slimvæsener. Jeg har set medlemmer af Det Kongelige Apotekerselskab fra Undergrunden indsamle prøver af stoffet. Jeg vil vide hvorfor! Hvor kommer det fra?\n\nJeg har hørt om flere i Ondskoven. Det, jeg har brug for, er prøver af slimvæsenerne derovre, så jeg kan fremme min forskning. Jeg giver dig beholdere, og du bruger dem til at tage en prøve fra de døde skabninger.", p="Nogle af de eksperimenter, jeg har lavet, er fascinerende. Jeg tror, at jeg med lidt mere arbejde kan finde ud af, hvad disse skabninger består af, og hvordan de spiller ind i, hvordan livet udviklede sig på Azerot... hvis de overhovedet har noget med det at gøre.\n\nEn af mine største teorier, som ikke er særlig populær, er ideen om, at slimvæsener og slimer er knyttet til skabelsen af denne planet... næsten som om de er en udsondring fra den.\n\nMen jeg kan hverken bevise eller modbevise det, før jeg får flere prøver.", c="Fantastiske resultater, <Name>! Du kom tæt nok på til at tage en prøve af de fordærvede ting, og du slap uskadt fra det! Tak. Åh, disse prøver bliver perfekte. Jeg kan ikke vente med at begynde at teste dem.\n\nHvis jeg har ret, kan jeg blive en af Opdagelsesrejsendes Ligas største videnskabsmænd!\n\nDet vil bevise over for alle dværgene, at det ikke var en fejl at lade os gnomer komme ind i Jernsmede efter Nisseborg-hændelsen."},
  [4513] = {n="En Lille Smule Slim Rækker Langt", l="Bring 10 Fyldte Rene Prøvekrukker til Larsen Tandhjulsdøvl i Jernsmede.\n\nHvis du har svært ved at finde dem, så prøv måske at få flere spor fra Larsen.", d="Jeg får brug for flere prøver, <Name>. Men--og jeg ved ikke, hvordan jeg skal sige det--de skal være rene prøver. Jeg ved, jeg ved det. \"Hvad betyder 'ren', Larsen?\" Det ved jeg ikke helt. Jeg ved kun, at disse er forurenede... ligesom Ondskoven. Og netop derfor er min erkendelse så vigtig. Slimvæsenerne ser ud til at tilpasse sig... at tage på sig træk fra det område, de befinder sig i. Jeg må finde prøver, der ikke er blevet forurenet. Men hvor? Hvor?!\n\nBah! <Name>, tag disse beholdere, for en sikkerheds skyld, hvis du finder nogen selv.", p="Så mange ting at tage i betragtning. Men hvad betyder det? Og hvordan påvirker det livet for Azerots folk?", c="Har du fundet den? <Name>, du er en skat i dig selv. Din hengivenhed og hjælp har været fantastisk, og jeg kan ikke takke dig nok.\n\nVær venlig at tage dette for besværet. Jeg har noget arbejde at gøre, men jeg er sikker på, at jeg får brug for dine tjenester igen, hvis du kommer tilbage på et senere tidspunkt.\n\nTak. Tusind tak."},
  [4521] = {n="Vilde Vogtere", l="Trull Fejlbane i Ondskoven vil have dig til at dræbe 15 Rasende Ugleudyr og 15 Trævlede Ugleudyr.", d="Vinterkilde ligger lige hinsides Tømmergab, nordøst for Ondskoven. Har du været der?\n\nJeg har hørt, at området er fyldt med væsener, der kaldes vildfolk. Disse udyr har været kendt for at vogte hemmeligheder; hemmeligheder fra Nattealferne.\n\nVi må finde ud af, hvad der kan være skjult i Vinterkilde.\n\nJeg har hørt, at de trævlede ugleudyr kan findes lige syd for vejen, og at der er andre, kaldet rasende ugleudyr, som kan findes midt i Vinterkilde. Ryd dem ud, og få adgang til landet.", p="Rapporter tilbage til mig, når du har udført den opgave, jeg gav dig.", c="Det er fremragende nyheder, <Name>. Med disse udyr ude af vejen kan vi begynde at bevæge os længere ind i Vinterkilde. Er du klar til mere?"},
  [4601] = {n="Glimmatic 5200!", l="Indsæt en Skidt-indkrystalliseret genstand i Glimmatic 5200, og sørg for at have tre sølvmønter for at starte maskinen.", d="Denne opfindelse skiller sig ud blandt gnomerne, der holder stand mod galskaben uden for rummet. En lille plade på apparatet lyder \"Glimmatic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester, der ødelægger dine glimmerier? Glimmatic 5200 får glansen tilbage i det skinnende-fantastiske! Indsæt den genstand, du vil rense, og læg tre sølvmønter i møntsprækken. Giv Glimmatic 5200 et øjeblik til at arbejde, og voilà! Dine værdigenstande vil komme ud rene og skinnende!\"", p="Det ser ud til, at apparatet har brug for en skidt-indkrystalliseret genstand at rense og tre sølvmønter for at få opfindelsen til at virke. Så længe begge er til stede, bør Glimmatic 5200 virke...", c="Du indsætter den skidt-indkrystalliserede genstand og tre sølvmønter i Glimmatic 5200. Maskinen vågner til live i et rasende forsøg på at rense skidtet fra den ukendte genstand. Høje, voldsomme knasende lyde buldrer fra maskinens hjerte. Apparatets metalramme knirker og stønner, mens den vipper fra side til side..."},
  [4602] = {n="Glimmatic 5200!", l="Indsæt en Skidt-indkrystalliseret genstand i Glimmatic 5200, og sørg for at have tre sølvmønter for at starte maskinen.", d="Denne opfindelse skiller sig ud blandt gnomerne, der holder stand mod galskaben uden for rummet. En lille plade på apparatet lyder \"Glimmatic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester, der ødelægger dine glimmerier? Glimmatic 5200 får glansen tilbage i det skinnende-fantastiske! Indsæt den genstand, du vil rense, og læg tre sølvmønter i møntsprækken. Giv Glimmatic 5200 et øjeblik til at arbejde, og voilà! Dine værdigenstande vil komme ud rene og skinnende!\"", p="Det ser ud til, at apparatet har brug for en skidt-indkrystalliseret genstand at rense og tre sølvmønter for at få opfindelsen til at virke. Så længe begge er til stede, bør Glimmatic 5200 virke...", c="Du indsætter den skidt-indkrystalliserede genstand og tre sølvmønter i Glimmatic 5200. Maskinen vågner til live i et rasende forsøg på at rense skidtet fra den ukendte genstand. Høje, voldsomme knasende lyde buldrer fra maskinens hjerte. Apparatets metalramme knirker og stønner, mens den vipper fra side til side..."},
  [4605] = {n="Glimmatic 5200!", c="Lige så hurtigt som den startede, går Glimmatic 5200 pludselig i stå. En simpel \"klink\" lyder fra maskinen, og maskinens mund snor sig opad. Inde i Glimmatic 5200 ligger en lille kasse pakket ind i en lille sløjfe. Maskinen ser ud til at pakke en genstand ind, efter at have fjernet dens skidt-indkrystalliserede tilstand. Selvom maskinen ikke virkede, er genstanden i det mindste nu pakket ind i en flot kasse.\n\nNå, der er én måde at finde ud af, om den renser genstanden eller ej..."},
  [4606] = {n="Glimmatic 5200!", c="Lige så hurtigt som den startede, går Glimmatic 5200 pludselig i stå. En simpel \"klink\" lyder fra maskinen, og maskinens mund snor sig opad. Inde i Glimmatic 5200 ligger en lille kasse pakket ind i en lille sløjfe. Maskinen ser ud til at pakke en genstand ind, efter at have fjernet dens skidt-indkrystalliserede tilstand. Selvom maskinen ikke virkede, er genstanden i det mindste nu pakket ind i en flot kasse.\n\nNå, der er én måde at finde ud af, om den renser genstanden eller ej..."},
  [4621] = {n="Hold ind, Admiral!", l="Dræb Flådemester Søhest og Baron Tyranbrand fra Bytteviken, og vend derefter tilbage til Flådemester Ildallon om bord på Karmosinrødt Slør ud for Kvæltornsdalens kyst.", d="Lyt godt efter, søhund... Bytteviken-magten er det, der holder os Blodsejl fra at sejle, hvor vi vil, og tage, hvad vi vil, som vores ret til plyndring. Havde du stukket en kniv i Flådemester Søhest, ville vi aldrig løbe ind i en af Bytteviken-skibene. Havde du stukket en kniv i Baron Tyranbrand, ville vi aldrig stå over for loven på deres præmisser.\n\nHvis du skal være en æresadmiral blandt os - ja, ADMIRAL, du skal stikke en kniv i dem begge, som jeg har sagt. Gå nu, knægt, og vend tilbage til mig, når du har gjort gerningen.", p="Du er allerede tilbage, din forbandede tjærepind! Har du gjort, som jeg har befalet? Svigter du os, kommer du til at gå planken.\n\nArrrrr...", c="Hold ind... Admiral <Name>! Du er en pirat blandt piraterne, pige!\n\nDet varmer mit hjerte at give dig denne hat. Du vil aldrig finde en lignende et andet sted, og alle, der ser på dig, vil se, at du er en Admiral i Blodsejl-flåden!"},
  [4642] = {n="Sammensmeltning af Påvirkninger", l="Bring en Sammensmeltet Slimprøve til Kemiker Fyrig i Undergrunden.", d="Her er noget indkapslet slim skabt af de Ondskoven-prøver, du hentede. Tag kassen med til Un'Goro-krateret og find et rent slimvæsen... den primitive type vil gøre det fint. Når du kommer tæt nok på, skal du slippe slimvæsenet løs fra kassen og lade os se, hvad de to synes om hinanden.\n\nNår eksperimentet er slut, så bring mig en prøve af det, der er tilbage. Jeg venter her i Apotekerium.", p="Hvordan går eksperimentet, <Name>? Jeg vil fortsætte med at studere de prøver, du har hentet til mig--jeg begynder at se, hvorfor Frue Silvanas er så interesseret i disse skabninger. Hvis de virkelig er en del af De Gamle Guder, hvem ved så, hvordan det kan bruges til vores fordel.", c="Åh, så fremragende, <Name>. Det er virkelig fremragende.\n\nEn sådan historie. Hvem skulle have troet, at de to ville reagere med hinanden på den måde... Jeg må bruge mere tid på at undersøge de miljømæssige forhold, der forårsager ændringer i disse skabninger.\n\nJeg vil fortsætte min forskning for nu. Måske taler vi sammen igen snart. Indtil da ønsker jeg dig alt det bedste."},
  [4701] = {n="Sæt Hende Ned", l="Rejs til Sortklippe-spiret og ødelæg kilden til ulvedyr-plagen. Da du forlod Helende, råbte han et navn: Halykon. Det er det, orkerne henviser til, når de taler om ulvedyret.", d="Du har uden tvivl set de ulvedyr, som Sortklippe-orkerne kommanderer.\n\nDet er mærkeligt - uanset hvor mange vi ødelægger, bliver deres antal aldrig mindre. Mine spejdere har rapporteret, at ulvedyrene bliver avlet, trænet og i sidste ende eksporteret fra Sortklippe-spiret: hovedstaden for Sortklippe-orkerne. Du skal rejse til Sortklippe-spiret og finde kilden til denne plage. Find den... og ødelæg den.\n\nHeld og lykke, <Name>. Må Cenarus beskytte dig...", p="Har du opdaget og taget dig af kilden til ulvedyr-plagen?", c="Dvæl ikke ved hendes lidelse, <Name>. Udyret var fordærvet - et produkt af mørk magi. Du har gjort Alliancen en stor tjeneste, og du skal belønnes."},
  [4721] = {n="Vilde Vogtere", l="Trull Fejlbane i Ondskoven vil have dig til at jage 10 Berserk Ugleudyr i Vinterkilde.", d="Løbere er vendt tilbage fra Vinterkilde med rapporter om, at der er en række små huler i det sydlige område af Vinterkilde. Det ser ud til, at der er vildfolk placeret i området omkring disse huler. Hvis der er noget værdifuldt, som de vogter, tror jeg, at det er her, vi finder det.\n\nDu vil finde disse væsener mere udfordrende end de tidligere typer, <Name>. Skabningerne ser ud til at være blevet gale af at være udsat for netop det, de kæmper for at beskytte.", p="Du kender dine ordrer, <Name>.", c="Hårdt arbejde er noget, jeg har stor respekt for, <Name>. Nu kan vi komme videre med vores planer for Vinterkilde."},
  [4722] = {n="Strandet Havskildpadde", l="Tag Havskildpaddens Rester til Gwennyth Bly'Sagn i Auberdin.", d="Du finder liget af en havskildpadde, der for noget tid siden var strandet på Mørkekystens kyst. Den er blevet plyndret af fiskefolkene, som har slået lejr omkring dyrets rester. Der ser dog stadig ud til at være nogle brugbare prøver tilbage på skabningens rester, som Gwennyth Bly'Sagn i Auberdin måske kan gøre brug af.", p="Hej <Name> - har du nogle opdagelser af skabninger, der er skyllet i land, som du vil rapportere om?", c="Endnu en opdagelse for os at forske i - godt gået, <Name>! Disse rester vil blive ordentligt undersøgt, når de kommer til Darnassos. Modtag venligst dette lille honorar til gengæld for de rester, du har leveret til vores undersøgelse."},
  [4723] = {n="Strandet Havskabning", l="Tag Havskabningens Knogler til Gwennyth Bly'Sagn i Auberdin.", d="Resterne af en kæmpetærsker - meget større end en, man ville forvente at finde ved Mørkekysten - ligger strandet på kysten af Dis' Kant. Hvordan dette væsen er kommet hertil, er ukendt; flokken af fiskefolk, der nu lever af dets kadaver, ser ud til at være alt for svage, selv i store antal, til at have fældet udyret.\n\nSelvom noget af det er blevet pillet rent, er der nok tilbage til at tage en prøve til Gwennyth Bly'Sagn i Auberdin at studere.", p="Måske finder vi en dag en måde at forhindre disse stakkels skabninger i at afslutte deres liv unødvendigt på Mørkekystens kyst. Indtil da må vi fortsætte vores forskning!\n\nHilsner <Name> - hvilke nyheder bringer du?", c="Endnu en opdagelse - godt gået, <Name>! Disse rester vil blive ordentligt undersøgt, når de kommer til Darnassos. Modtag venligst dette lille honorar til gengæld for de rester, du har leveret til vores undersøgelse."},
  [4724] = {n="Flokdamen", l="Dræb Halykon, flokdamen for Blodøkse-ulvedyret.", d="Nogle siger, at ulvedyrene, som Sortklippe-orkerne kontrollerer, er skabt af en overnaturlig kraft. Andre siger, at de ikke er ægte ulvedyr, men i stedet en race af dæmonhunde, givet til orkerne af en faldet dybdeherre.\n\nSandheden er langt mindre tilrettelagt, men lige så skræmmende. Ulvedyrene fra Sortklippe kommer fra Halykon og hendes makker. Halykon er den gigantiske hulemor for ulvedyrene. Hendes makker? Ingen har nogensinde levet for at fortælle den historie.\n\nRam hjertet af ulvedyrene. Ødelæg Halykon... og <Name>, pas på dig selv.", p="Med flokdamen slået ihjel kan vi begynde at udtynde ulvevagterne i Spiret og til sidst gøre fremskridt ind i byen.", c="Rabiate hvalpe? Gizrul Slavehandleren? Og du lever for at fortælle historien?! Utroligt! En velfortjent belønning!"},
  [4725] = {n="Strandet Havskildpadde", l="Tag den Mærkeligt Mærkede Kasse til Gwennyth Bly'Sagn i Auberdin.", d="Flere havskildpaddeskeletter ligger strandet langs kysten. Dette særlige sæt har en forladt vogn fastgjort til skildpaddens skal. Måske blev dette væsen drevet til kysten af ukendte væsener i stedet for at strande selv, som nogle af de andre rester antydede. Gråtåge-fiskefolkene har nu gjort dette væsens rester til deres hjem og lever af ådslet.\n\nI vognen finder du en kasse med mærkelige mærker på; måske kan Gwennyth Bly'Sagn i Auberdin finde mening i det.", p="Det er en fornøjelse at se dig igen, <Name>. Vi gør store fremskridt med at afdække mysteriet om, hvorfor majestætiske havskabninger strander på Mørkekystens kyst, men for hvert spørgsmål, der besvares, rejses der tilsyneladende to nye.\n\nEr du her for at tilbyde os mere hjælp til vores forskning?", c="Jeg har hørt om den slags vogne, der findes på ryggen af den skildpadde, du fandt. Dem tror jeg virkelig er slangefolkvogne, brugt både i kamp og til transport af deres forsyninger op på land. Mærkerne på kassen, du fandt, er slangefolkenes; det ville forklare deres invaderende tilstedeværelse i det fjerne nord for Mørkekysten.\n\nJeg vil sende denne kasse til Darnassos sammen med resten af dine opdagelser. Dette er til dig - tak igen for din hjælp."},
  [4726] = {n="Ynglingessens", l="Bring 8 Ynglingessens og Draco-Fangeren 900 til Tinkee Dampkedel ved Flammevåbenskjold i Brændende Stepper.", d="Jeg har studeret drageslægtningene i Brændende Stepper i flere uger, og jeg tror, jeg endelig har fået et gennembrud! Jeg har lavet en enhed - jeg kalder den Draco-Fangeren 900. Den kan fange essensen af drageynglinger!\n\nEller i det mindste tror jeg, den kan.\n\nSå tag enheden her og affyr en stråle mod en yngling i Brændende Stepper med den. Mens den er under enhedens påvirkning, besejr ynglingen, og dens essens skulle blive frigivet.\n\nHvis den gør det, så er det fantastisk! Bring mig prøver tilbage, så jeg kan studere dem!", p="Har du ynglingessensen, <Name>? Jeg kan ikke vente med at studere den.\n\nOg desuden... min velgører er ikke den slags person, du vil skuffe.", c="Det virkede! Du fik essensen! Godt gået, <Name>! Godt gået!\n\nDenne essens vil være uvurderlig for min forskning. Jeg håber en dag at lære at fange levende drageunger, eller måske deres æg. Hvis jeg kunne finde en måde at gøre det på, ville jeg være misundt af drageforskere over hele verden!\n\nMin arbejdsgiver ville også blive glad, og som jeg sagde før, er han en, du vil holde glad..."},
  [4727] = {n="Strandet Havskildpadde", l="Tag Havskildpaddens Rester til Gwennyth Bly'Sagn i Auberdin.", d="Havskildpaddens skelet ligger i sandet på de nordlige strande ved Mørkekysten. Gråtåge-fiskefolkene har enten ikke fundet dette kadaver, eller også har de, og de holder sig væk fra det af en ukendt grund. Uanset hvad, er der nok af skildpadden tilbage til at tage en prøve med tilbage til Gwennyth Bly'Sagn i Auberdin, så Månetemplet kan studere den.", p="Hej igen <Name> - har du fundet flere strandede skabninger, som Månetemplet bør vide om?", c="Det er interessant, at fiskefolkene ikke var til stede på dette sted; det vil vi huske, når vi studerer dette væsens rester! Tak for din indsats, <Name>; Månetemplet vil gerne have, at jeg giver dig dette som kompensation for din tid."},
  [4728] = {n="Strandet Havskabning", l="Tag Havskabningens Knogler til Gwennyth Bly'Sagn i Auberdin.", d="Liget af det, der ser ud til at være en slags kæmpe havpattedyr, ligger delvist udtømt på stranden. En trillebør og diverse værktøj ligger forladt efter dette enorme strandede væsen, som om der tidligere var gjort et forsøg på at studere det. Selvom fiskefolkene har plyndret dette udyr, er der nok tilbage til at samle en passende prøve til Gwennyth Bly'Sagn i Auberdin.", p="Hilsner endnu en gang, <Name>! Hvad bringer dig tilbage til Auberdin? Er du her for at rapportere om en anden opdagelse, måske?", c="Ah, jeg tror, du har opdaget en, som Opdagelsesrejsendes Liga oprindeligt undersøgte. De har en tilstedeværelse her i Mørkekysten, og de nævnte, at de studerede et af de strandede væsener, indtil fiskefolkene jog dem væk. Det ser ud til, at du har lykkedes, hvor vi begge ikke har. Vær venlig at modtage dette honorar på vegne af Månetemplet."},
  [4729] = {n="Kiblets Eksotiske Kæledyr", l="Rejs til Sortklippe-spiret og find Blodøkse-ulvehvalpe. Brug buret til at bære de voldsomme små udyr. Bring en Indburet Ulvehvalp tilbage til Kiblet.", d="Du undrer dig sikkert over, hvad jeg laver herude. Se på burene! Er det ikke indlysende?\n\nJeg er en dyreven frem for alt, men sælger af profession. Jeg opsporer eksotiske dyr for de rige og berømte og tæmmer udyrene, så de opfører sig som ordentlige kæledyr.\n\nNu undrer du dig sikkert over: \"Hvad kan jeg gøre for dig, Kiblet?\" Svaret er enkelt: Tag dette her udyrebur og find mig nogle ulvehvalpe. Til gengæld tæmmer jeg en ulv til dig!", p="<Kiblet er optaget med at skændes med Opus.>", c="Du fik dem på det perfekte tidspunkt, <Name>. Senere ville de være utæmmelige! Giv mig et øjeblik, så har jeg den lille fyr klar til, at du kan tage hjem."},
  [4730] = {n="Strandet Havskabning", l="Tag Havskabningens Knogler til Gwennyth Bly'Sagn i Auberdin.", d="Liget af det, der måske har været et kæmpe havpattedyr, ligger halvt fortæret på stranden. En flok fiskefolk, stærkere end dem man finder tættere på Auberdin, har slået sig ned omkring det faldne væsen. Der er nok af skabningen tilbage til, at en passende prøve af dens knogler kan leveres til Gwennyth Bly'Sagn i Auberdin.", p="Hej igen, <Name>! Er du her for at rapportere om en anden opdagelse?", c="Knoglerne, du har, stammer fra milde havpattedyr, som vides at leve i vandene omkring foden af Teldrasil. De har aldrig været kendt for at strande voldsomt, sådan som tærskerne har været kendt for. Hvorfor skulle disse væsener gøre dette, undrer jeg mig? Måske vil studiet af deres rester bære frugt af den viden, vi søger.\n\nIgen, tak for din hjælp. Vær venlig at modtage dette honorar fra Månetemplet."},
  [4731] = {n="Strandet Havskildpadde", l="Tag den Mærkeligt Mærkede Kasse til Gwennyth Bly'Sagn i Auberdin.", d="Endnu et sæt havskildpaddeskeletter ligger strandet på kysten. Dette sæt rester har en forladt vogn halvt spændt fast på skildpaddens skal. Måske blev dette væsen drevet til kysten af ukendte væsener i stedet for at strande selv, som nogle af de andre rester antydede. Mægtige Gråtåge-fiskefolk har gjort dette væsens kadaver til deres nuværende hjem.\n\nI vognen finder du en kasse med mærkelige mærker på; måske kan Gwennyth Bly'Sagn i Auberdin finde mening i det.", p="Hej igen, <Name>. Det arbejde, du har udført på vegne af Månetemplet, har været enestående. Skal vi velsignes med mere af din indsats på vores vegne?", c="Jeg har hørt om den slags vogne, der findes på ryggen af den skildpadde. Dem tror jeg virkelig er slangefolkvogne, brugt både i kamp og til transport af deres forsyninger op på land. Mærkerne på kassen, du fandt, er slangefolkenes; måske blev det væsen, du opdagede, dræbt, mens det var på vej længere sydpå... måske til Askedalen?\n\nJeg vil sørge for at sende denne kasse til Darnassos sammen med resten af dine opdagelser. Dette er til dig - tak igen for din hjælp."},
  [4732] = {n="Strandet Havskildpadde", l="Tag Havskildpaddens Rester til Gwennyth Bly'Sagn i Auberdin.", d="Du finder liget af en havskildpadde, der for noget tid siden var strandet på Mørkekystens kyst. Det er næsten blevet pillet rent af Gråtåge-fiskefolkene, de samme, der nu har slået lejr omkring dyrets rester. Der ser dog stadig ud til at være nogle brugbare prøver tilbage på skabningens rester, som Gwennyth Bly'Sagn i Auberdin måske kan gøre brug af.", p="Hilsner endnu en gang <Name> - har du flere opdagelser at rapportere til Månetemplet?", c="Har du fundet endnu flere strandede væsener, <Name>? Havskildpadder blev almindeligt set boltre sig langs foden af Nordrassil, før det blev ødelagt. Med Teldrasils fødsel er disse væsener dog blevet set i stadigt færre antal. Nogle, som vi har opdaget, afslutter deres liv her af en ukendt grund.\n\nDin hjælp vil måske afsløre mysteriet foran os. Vær venlig at modtage dette til gengæld for de rester, du har leveret til vores undersøgelse."},
  [4733] = {n="Strandet Havskabning", l="Tag Havskabningens Knogler til Gwennyth Bly'Sagn i Auberdin.", d="Resterne af det, der ser ud til at være en kæmpetærsker, er skyllet i land i den klippefyldte vig ved Tusmørkekysten. Tærskeren er flere gange større end nogen af de andre tærskere, der er set i disse egne. Uanset hvor den kom fra, synes dette væsen ikke at have været hjemmehørende i Mørkekysten.\n\nSelvom væsenet er blevet pillet fra hinanden de fleste steder, er der nok tilbage til at samle en passende prøve til Gwennyth Bly'Sagn i Auberdin.", p="Lovet være Elunie - jeg er glad for at se dig igen, kære <Name>. Månetemplets arbejde med det mærkelige strandingsfænomen fortsætter her i Mørkekysten. Har du måske noget yderligere at tilbyde os?", c="Dimensionerne af den tærsker, du nævner, er svimlende. Selv de ældste tærskere i denne region vokser kun til en brøkdel af den størrelse. Selvom nogle større var kendt for at være tæt på Teldrasil, er deres antal faldet støt. Jeg kan ikke lade være med at undre mig over, om disse væsener, der strander sig selv her, på en eller anden måde hænger sammen med dette.\n\nMens vi analyserer de knogler, du har bragt os, så vær venlig at modtage dette på vegne af Månetemplet. Tak, <Name>."},
  [4734] = {n="Æggefrysning", l="Brug Æggeskilloskop-prototypen på et æg i Rokkeriet.", d="<Name>, jeg har arbejdet hårdt på en ny opfindelse, æggeskilloskopet! Den er designet til at udsende et udbrud af kold energi mod et sort drageæg... og fryse det helt fast! Kan du teste den for mig?\n\nJeg har hørt, at højt oppe i Sortklippe-spiret har dragerne et rokkeri, hvor de klækker deres æg. Der skal du hen for at teste æggeskilloskopet, og så fortæller du mig, hvordan det virkede!\n\nOg bare rolig. Frosne drageæg burde være harmløse. Det er de ufrosne, du skal passe på!", p="<Name>, testede du æggeskilloskopet?", c="Det virkede? Fantastisk! Jeg vidste, det ville!\n\nMens du var væk, arbejdede jeg på en ny version af æggeskilloskopet. Denne har en meget længere rækkevidde.\n\nHer, du kan få et, hvis du tager tilbage til Sortklippe-spiret."},
  [4735] = {n="Æggeindsamling", l="Bring 8 Indsamlede Drageæg og Samlertronisk Modul til Tinkee Dampkedel ved Flammevåbenskjold i Brændende Stepper.", d="<Name>, jeg er endelig klar til rigtige prøver af drageæg! Her, tag dette samlertroniske modul. Det er designet til at udtrække et drageæg og gøre det klar til transport. Gå tilbage til Rokkeriet og brug modulet til at indsamle æg.\n\nOg glem ikke at fryse dem først, ellers klækker de måske, før du kan indsamle dem!\n\nNår du har nok æg, så bring dem til mig!", p="Har du æggene, <Name>? Min velgører hørte, at du indsamlede dem til mig, og han er meget ivrig efter at få fat i dem!", c="Wow, du fik dem! Det samlertroniske modul virkede! Jeg er et geni!\n\nTak, <Name>. Min velgører vil blive meget glad for at få disse æg..."},
  [4736] = {n="På jagt efter Menara Tomrumsrivet", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Ah, hej, <Name>. Du gør gode fremskridt i din oplæring. Så gode, faktisk, at jeg synes, du bør belønnes for dit hårde arbejde – og for at du endnu ikke er blevet fordærvet af arkanen.\n\nHvis du er interesseret, så søg Menara Tomrumsrivet i Skralleby. Hun opholder sig lige nu i Strahad Fjernsens tårn, som kigger ud over byen.\n\nHun er ikke særlig venlig, <Name>, så forvent ingen ros. Men hvis du arbejder hårdt, sørger hun for, at du bliver passet på.", c="Ah, Tjørnetorn sendte dig. Godt. Så når ordet langt nok til at finde kommende elever. Det glæder mig.\n\nDet er typisk for vores slags, <Name>, at stå sammen, uanset race. Det er særligt vigtigt, for dem vi har mest med at gøre skelner ikke i deres ondskab, hvis vi ikke formår at formilde eller kontrollere dem ordentligt.\n\nJeg føler, at du har lært en masse, og hvis du er villig, vil jeg hjælpe dig med at skabe redskaber, der supplerer dine evner."},
  [4737] = {n="På jagt efter Menara Tomrumsrivet", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Hmpf, stadig stræber du efter at blive stærkere. Jeg siger, at det kun er et spørgsmål om tid, før korruptionen og afhængigheden tager fat i dig, og du bliver en slave af det, du søger at få magt over.\n\nPfah! Et fjols er du! Tiden vil bevise, at jeg har ret – intet andet … kun tiden.\n\nMen det ser ud til, at ikke alle er enige med Zevrost. Det ser ud til, at Menara vil skabe redskaber, så du kan blive stærkere og udnytte din styrke. Hvis du er interesseret, så tag til Skralleby i Ødemarken. Hun er der og holder øje med byen fra oven.", c="Ah, Zevrost sendte dig. Godt. Så når ordet langt nok til at finde kommende elever. Det glæder mig.\n\nDet er typisk for vores slags, <Name>, at stå sammen, uanset race. Det er særligt vigtigt, for dem vi har mest med at gøre skelner ikke i deres ondskab, hvis vi ikke formår at formilde eller kontrollere dem ordentligt.\n\nJeg føler, at du har lært en masse, og hvis du er villig, vil jeg hjælpe dig med at skabe redskaber, der supplerer dine evner."},
  [4738] = {n="På jagt efter Menara Tomrumsrivet", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Lad os være klare over én ting, <Name>: Jeg synes ikke, du er klar til sådanne ansvar. Jeg synes ikke, at en novice nogensinde bør være involveret i skabelsen af en genstand med magt; især ikke en så uprøvet.\n\nMen det er ikke min beslutning. De magtfulde, eller i hvert fald dem, der ønsker at give dig sådanne gaver, er dem, der bestemmer det.\n\nHvis du er interesseret i at lære mere, foreslår jeg, at du søger Menara Tomrumsrivet i Skralleby. Hun opholder sig som regel i tårnet over havnebyen.", c="Ah, Demisette sendte dig. Godt. Så når ordet langt nok til at finde kommende elever. Det glæder mig.\n\nDet er typisk for vores slags, <Name>, at stå sammen, uanset race. Det er særligt vigtigt, for dem vi har mest med at gøre skelner ikke i deres ondskab, hvis vi ikke formår at formilde eller kontrollere dem ordentligt.\n\nJeg føler, at du har lært en masse, og hvis du er villig, vil jeg hjælpe dig med at skabe redskaber, der supplerer dine evner."},
  [4739] = {n="På jagt efter Menara Tomrumsrivet", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="<Class>! Ja, dig!\n\nDu har ikke alt tilbehøret, men det er tydeligt, at du er klar – luften omkring dig udstråler større selvtillid. Ja, nu kan jeg se det.\n\nMenara Tomrumsrivet vil lære dig et par ting, hvis du føler dig klar. Hun bruger sin tid på at undervise yngre elever i arkanen. Hun giver endda gaver til dem, der består hendes prøver.\n\nTag til Skralleby i Ødemarken, hvis du er interesseret. Hun opholder sig over byen i Strahads tårn.", c="Ah, Kaal sendte dig. Godt. Så når ordet langt nok til at finde kommende elever. Det glæder mig.\n\nDet er typisk for vores slags, <Name>, at stå sammen, uanset race. Det er særligt vigtigt, for dem vi har mest med at gøre skelner ikke i deres ondskab, hvis vi ikke formår at formilde eller kontrollere dem ordentligt.\n\nJeg føler, at du har lært en masse, og hvis du er villig, vil jeg hjælpe dig med at skabe redskaber, der supplerer dine evner."},
  [4741] = {n="Vilde Vogtere", l="Trull Fejlbane i Ondskoven vil have dig til at jage 13 Månerørte Ugleudyr.", d="I de nordlige områder af Vintersol bliver Vildfolkene endnu mere voldsomme. Vi må fortsætte vores foranstaltninger dér.\n\nJag de månerørte ugleudyr i Vintersol, og udforsk området, de holder til i.\n\nDet er farligt terræn, men jeg ved, at du kan klare udfordringen. Vend tilbage til mig, når du har slået 13 af vildfolkene ihjel.", p="Fortæl mig ikke, at du er for bange! Af sted med dig!", c="Jeg fornemmer, at du nyder dit arbejde. Og jeg tror, at vi er på sporet af noget her."},
  [4742] = {n="Ascensionens segl", l="Find de tre befalingsædelsten: Smolderthorns Ædelsten, Spirestones Ædelsten og Bloodaxes Ædelsten. Bring dem sammen med det Usmykkede Ascensionens Segl tilbage til Vælan.\n\nGeneralerne, som Vælan har fortalt dig om, er: Krigsmester Voone fra Smolderthorn; Højlord Omkrog fra Spirestone; og Overherre Ormethalak fra Bloodaxe.", d="Som du kan se, har det usmykkede segl tre tomme indfatninger. Hver af disse indfatninger skal fyldes med en ædelsten, der repræsenterer ledelsens befaling. Til sidst skal Overherre Ormethalak, mester over den nedre citadel, smede seglet i flammerne fra Den Sorte Drageflugt.\n\nForstå dette, dødelige: Chancen for, at en af de tre generaler i den nedre citadel til enhver tid bærer en ædelsten, er sjælden. Du må være årvågen i din søgen. Hold dig fast på din beslutsomhed!", p="Mod og tålmodighed frem for alt andet, <Name>!", c="<Vælans billede slører sig et øjeblik.>\n\n<De stykker, du havde samlet, er forsvundet.>\n\nDet ufærdige Ascensionens segl er nu klar. Tiden er inde til det sidste trin."},
  [4743] = {n="Ascensionens segl", l="Rejs til Ormemosen i Støvsumpen. Find den gamle drage, Glødestrid, og slå ham uden nåde, til hans vilje er brudt.\n\nDet er i det øjeblik, at du skal placere det ufærdige Ascensionens segl foran det store udyr. Derefter skal du være hurtig til at bruge Drakonisk Energis Kugle på hans svækkede skikkelse og tage herredømme over hans sindsevner. Kontrollér udyret og tving Den Sorte Drageflugts flammer ned over det ufærdige Ascensionens segl!", d="Få af de sorte drageslægtninge uden for den øvre citadel har evnen til at smede seglet med deres egen flammende ånde. Ormethalak er en af dem, men hans vilje kan ikke brydes.\n\nDu må rejse til Ormemosen i Støvsumpen. Det er der, du vil finde en gammel drage kendt som Glødestrid. Du må bryde hans vilje, <Name>. Bryd den og brug denne kugle på hans svækkede skikkelse. Du vil have få sekunder til at kontrollere hans sind og puste til de flammer, der skal smede seglet.", p="Spild ikke tiden, <Name>. Nefarian arbejder febrilsk på at udløse sin ondskab over vores verden.", c="Stå stille, mens jeg udfører den sidste beskyttelsesbesværgelse.\n\n<Vælans øjne bliver til tvillingekugler af ild.>\n\nAscensionens segl er fuldført …\n\nVid dette: Jeg har indgydt artefakten nogle kraftfulde beskyttelsesbesværgelser. I din mørkeste time, når alt synes tabt, vil den røde flyvnings styrke stå til din rådighed."},
  [4764] = {n="Dommeriggerens spænde", l="Bring Dommeriggerens spænde til Mayara Lysvinge i Brændende Stepper.", d="Højt oppe i Sortklippe-spiret findes et kammer, der engang blev kaldt Lykkens Hal. Det var her, Mørkejernsdværgene opbevarede deres relikvier, trofæer og kunstgenstande.\n\nDet er længe siden. Det siges, at hallen er styrtet sammen, og nu bruges den til … mindre behagelige opgaver. Men jeg tror, at nogle gamle dværgiske relikvier stadig kan findes der.\n\nÉn sådan relikvie er Dommeriggerens spænde, hvis overflade er så dækket af sjældne ædelstene, at det siges at få enhver dværg, der ser på det, til at græde.\n\nDet spænde, <Name>, er dit mål.", p="Har du spændet, <Name>? Min velgører vil betale meget generøst for det.", c="Du fandt det! Så rygterne var sande!\n\nTak, <Name>. Min velgører, Greve Remington Højkilde, vil blive meget glad for at se denne tilføjelse til hans samling."},
  [4765] = {n="Levering til Højkilde", l="Bring Højkildes kasse til Remington Højkilde i Stormvind.", d="Jeg har pakket Dommeriggerens spænde i en kasse, egnet til forsendelse til Stormvind. <Name>, du har været ekstremt hjælpsom – må jeg bede dig om en sidste tjeneste?\n\nLever kassen til Greve Remington Højkilde. Du finder ham i Stormvinds fæstning. Jeg er sikker på, at han vil blive meget glad for at se, hvad du har med til ham.", p="Jeg fik besked på, at en budbringer ville komme. En med en gave fra Sortklippe-spiret.\n\nEr det dig?", c="Ah, så det er dig! Du har min tak, <Name>. Og … hvis du ikke allerede vidste det … så er en adelsmands taknemmelighed i Højkildes hus næsten en kongelig løsesum værd."},
  [4766] = {n="Mayara Lysvinge", l="Tal med Mayara Lysvinge i Brændende Stepper.", d="En af mine agenter, Mayara Lysvinge, blev sendt til Brændende Stepper for at spejde i den ødelagte by Thaurissan. Den ødelagte by for Mørkejernsdværgene gemmer måske på genstande af stor værdi … genstande, der passer fint ind i vores families museum.\n\nMayara siger, at hun har fundet noget og får brug for hjælp til at hente det, men det er ikke i Thaurissan. I stedet kræver det et togt ind i Sortklippe-spiret.\n\nJeg kender ikke detaljerne, men hvis du er interesseret, så tal med Mayara i Brændende Stepper.", c="Du kommer fra Stormvind? Vidunderligt – jeg kender til en kunstgenstand, som Remington ville slå ihjel for at have i sit museum, men den er ikke let at udvinde.\n\nDet er der, du kommer ind i billedet."},
  [4768] = {n="Mørkestens-tavlen", l="Bring Mørkestens-tavlen til Skyggemagiker Vivian Ligrave i Kargath.", d="Mørkestens-tavlen rummer skrifterne fra den længe døde dværg Urheld Mørkesten. Han var en alkymist af stor dygtighed, men hans samtidige mente, at han var sindssyg, og derfor delte han ikke sin forskning.\n\nMen han ætsede den ind i tavler, og jeg tror, at en sådan tavle ligger i Sortklippe-spiret, i et kammer, der engang hed Lykkens Hal. Jeg ved ikke, hvad det hedder nu, for få går ind i Sortklippe og vender tilbage.\n\nMen hvis du er villig til at trodse dets farer og vende tilbage til mig med tavlen, vil din belønning være stor.", p="Har du fundet tavlen, <Name>? Jeg længes efter at dykke ned i dens hemmeligheder.", c="Fremragende. Formlerne ætset ind i denne tavle vil kræve dage af forskning, men jeg er sikker på, at forskningen vil bære søde frugter.\n\nTak, <Name>. Du har været uvurderlig for os."},
  [4769] = {n="Vivian Ligrave og Mørkestens-tavlen", l="Tal med Skyggemagiker Vivian Ligrave.", d="Vivian Ligrave sendte mig besked fra Kargath i Ødelandene. Gennem sine studier mener hun, at der findes en gammel tekst i Sortklippe-spiret, som vil gavne vores forskning. For at bekræfte dette får hun brug for nogen, der kan udtrække teksten fra spiret. Ingen let opgave.\n\nHvis du er interesseret, så tal med Vivian i Kargath.", c="Det er sandt. Jeg tror, at der ligger en tavle i Sortklippe-spiret, en tavle med gamle alkymiske opskrifter. Jeg er glad for, at du er her, for jeg har brug for hjælp til at hente tavlen.\n\nFind dig til rette, så forklarer jeg nærmere."},
  [4770] = {n="Hjemad", l="Eskortér Pao'ka Hurtigbjerg fra Højrede, og tal derefter med Motega Ildmanke i Hvidrækkevidde-forposten.", d="Hjælp mig, <Class>! Jeg har gemt mig her i Højrede i noget tid nu, og det er gået mange dage, siden jeg har set et venligt ansigt. Jeg kom hertil for at studere wyvernerne, og jeg tror, at jeg kom for tæt på. Efter at være blevet jaget væk fra en af rederne, faldt jeg på afveje.\n\nJeg må tilbage til Hvidrækkevidde-forposten! Motega ved ikke, at jeg er savnet, og hun bliver rasende over, at jeg har vovet mig ind i Højrede alene.\n\nHvidrækkevidde-forposten ligger lige øst herfra … tag mig dertil, tak!", c="Hvad!? Hvis jeg havde vidst, at Pao'ka Hurtigbjerg ville snuse rundt i Højrede, havde jeg lænket ham fast til en totem! Hans far var tøvende med at lade ham følge med mig til Tusind Nåle. Vi kom hertil for at studere de forskellige væsener, der lever i disse smukke egne.\n\nJeg sætter pris på den hjælp, du har vist Pao'ka. Jeg håber, at dette dækker de uheld, denne gerning har kostet dig."},
  [4771] = {n="Gryderne fra Morgengryet", l="Placér Gryderne fra Morgengryet i visningsrummet i Scholomance. Besejr Vektus, og vend derefter tilbage til Betina Stortrold.", d="Jeg har placeret Gryderne fra Morgengryet i beholderen, du bragte til os, den, der holdt drageæggene. Din opgave er at bringe den dybt ind i Scholomance.\n\nDen udøde magiker Vektus fører an for en trup af hjemsøgelsens lærde … placér Gryderne fra Morgengryet i deres kammer, kaldet „visningsrummet“. Den vil så reagere med de udøde, der findes der, og med lidt held udslette dem!\n\nDerefter burde det ikke være noget problem at besejre Vektus. Ikke?", p="Husk, <Name> – vi må være tolerante, men faste i vores overbevisninger!", c="Du klarede det! Vektus er besejret! Og Gryderne fra Morgengryet … virkede de?\n\nHm … måske var min apparat ikke den succes, jeg havde håbet på, men jeg er glad for, at du alligevel kunne klare tingene. Godt gået, <Name>!\n\nSølvdæmringen og Azerots gode folk står i din gæld."},
  [4781] = {n="Komponenter til den fortryllede guldblodkappe", l="Bring en guldbarre til Xizk Godsyning i Kvælertornsdalen.", d="Din næste opgave er lige så enkel som din første, men den kræver, at du søger hjælp.\n\nJeg har brug for guldtråd til broderiet af kappen, men guldtråd er ikke let at få fat i, og meget få ved, hvordan den laves. Heldigvis kender én, der er loyal over for vores sag, dens hemmeligheder, og vedkommende er villig til at hjælpe dem, der stiger i vores rækker.\n\nBring en guldbarre til Xizk Godsyning i Bytteviken. Han er en mester-skrædder og vil gerne spinde tråden for dig. Guldbarrer smeltes af dygtige minearbejdere. Spørg en minearbejder om hjælp.", p="Guldbarrer, ja … ja. Bring mig en, så ser vi, hvad vi kan gøre ved at spinde noget tråd til dig. Indtil da vil jeg foreslå, at du koncentrerer dig om at blive stærkere. Dine hårdeste prøver venter stadig. Og stol på mig … du vil ønske, at du var bedre forberedt, uanset hvor stærk du tror, du er.", c="Perfekt, <Name>. Jeg er glad for, at du kunne finde en minearbejder til at hjælpe dig så hurtigt. Eller gjorde du selv dette arbejde? Uanset hvad, har du klaret dig godt. Dette bliver perfekt til tråden.\n\nDet vil tage noget tid at lave tingene, så du må komme tilbage – jeg sender faktisk det til en prinsesse, som vi har låst inde i et tårn, og hvis eneste opgave er at spinde guldtråd … nej, seriøst. Det mener jeg … okay, ikke helt."},
  [4782] = {n="Komponenter til den fortryllede guldblodkappe", l="Vend tilbage til Menara Tomrumsrivet i Ødemarken.", d="Vend tilbage til Menara, fortæl hende, at det vil tage noget tid, men at jeg nok skal levere for hende … og for dig. Sig til hende, at hun skal lade dig færdiggøre indsamlingen af de resterende komponenter – jeg burde have tråden færdig dengang. Du kan vende tilbage og hente den da.\n\nHeld og lykke, <Name>. Og sig hej til Strahad fra mig, mens du er der. Den gamle skrulle … at bygge et tårn lige ved siden af Skralleby … helt vanvittigt.", c="Godt, du er vendt tilbage, <Name>. Og hvor er tråden?\n\nAh, jeg forstår. Det er acceptabelt. Goblinen og hans bror har ikke svigtet os endnu – jeg regner med, at det er forståeligt, at han ikke havde den klar lige dér. Så må det være … vi har andre ting, vi kan tage os af i mellemtiden.\n\nEr du klar til næste trin?"},
  [4783] = {n="Komponenter til den fortryllede guldblodkappe", l="Bring 10 Phials med Hadfuror-blod og 1 Mindre Helvedessten til Menara Tomrumsrivet i Ødemarken.", d="De næste komponenter findes i Forødelse, langt mod vest for Ødemarken og endda Stenklobjergene.\n\nDer hersker kaos stadig efter Sønderrivningen. Både din styrke og din snilde vil blive sat på prøve dér – du vil møde væsener af had og også fra Den Brændende Legion.\n\nFra Hadfuror-satyren i nordøst skal du bringe mig deres blod. Fra de mindre helvedesvæsner i Mannorok-hekseriet skal du bringe mig en mindre helvedessten.\n\nVi skal bruge begge dele i konstruktionen af din kappe.", p="Forødelse er ikke et venligt område: slangefolk, kæmper, satyrer, Den Brændende Legion … alle disse og krigende kentaurklaner gør landet farligt, hvis du ikke er forsigtig.\n\nSom jeg sagde før, vil det ikke kun sætte din styrke og snilde på prøve, men også dit tålmod. Vær på vagt i de lande, <Name>.", c="Fremragende, <Name>. Disse vil gøre det godt. Jeg vil forberede dem nu, mens du går videre til dine sidste to komponenter. Er du klar?"},
  [4784] = {n="Komponenter til den fortryllede guldblodkappe", l="Bring noget Fint Guldgarn, 2 Ulmende Gløder og en Sjælesplint til Menara Tomrumsrivet i Ødemarken.", d="Jeg behøver kun tre ting nu, <Name>, så kan vi færdiggøre din kappe.\n\nFor det første det fine guldgarn, som Xizk laver til dig. Vend tilbage til ham i Bytteviken og hent det.\n\nFor det andet skal du bringe mig to ulmende gløder fra ildelementarerne i Arathi-højlandet. Hvis jeg husker rigtigt, ligger de mod vest, nær Thoradins Mur.\n\nEndelig en sjælesplint skabt af dig selv.\n\nNår du har alle komponenterne, skal du vende tilbage hertil til tårnet, så fuldender jeg kappen for dig.", p="Snart, <Name>. Det lover jeg dig. Kappen vil være mere end tilstrækkelig til dine behov og give dig et forspring over dine modstandere.", c="Fremragende, <Name>! Komponenterne er samlet, og vi er klar.\n\nJeg er sikker på, at du vil være tilfreds."},
  [4786] = {n="Den færdige kappe", l="Vent på, at Menara Tomrumsrivet fuldender din kappe, og tal derefter med hende igen.", d="Jeg vil sætte kappen sammen for dig nu. Det tager kun et øjeblik. Gå ikke langt væk.", p="Et øjeblik, <Name> …", c="Så er den klar, <Name>. Her har du den. Bær den med stolthed.\n\nDu har arbejdet hårdt, og jeg ser store ting i din fremtid. Husk, at det kræver stor vilje og udholdenhed at trodse den korruption, der følger med vores vej. Så længe din vilje er din egen, vil du få stor succes."},
  [4787] = {n="Det Gamle Æg", l="Bring det Gamle Æg til Yeh'kinja i Tanaris.", d="Mosh'arus profeti taler om et gammelt æg. Det er en relikvie fra en tid, hvor trolde herskede over store imperier, og det har magten til at rumme essensen af Hakar. Det kan være den eneste måde at holde vores verden sikker fra hans ondskab.\n\nBring mig det gamle æg, <Name>. Det siges at ligge gemt dybt i Jintha'Alør i Bagland, i en hule bag amfiteatret øverst i byen.", p="Har du det gamle æg? Jeg fornemmer store kræfter, der er i bevægelse, og jeg frygter, at tiden er ved at løbe ud.", c="Ah, du har ægget! Jeg bøjer mig for dig, <Name>. Din styrke og tapperhed vil blive husket længe."},
  [4788] = {n="De Sidste Tavler", l="Bring den Femte og Sjette Mosh'aru-tavle til Prospektor Jernstøvle i Tanaris.", d="Mens jeg gennemgår den tredje og fjerde af Mosh'arus tavler, må du finde den femte og sjette! Det bliver ikke let, for de holdes af Smolderthorn-trolde inde i Sortklippe-spiret. Spiret er et mørkt bjerg af ild mellem Brændende Stepper og Svidende Kløft.\n\nHeld og lykke, <Name>. Sortklippe-spiret er ikke noget sted for anstændige folk …", p="Har du været i spiret, <Name>? Har du den femte og sjette tavle?", c="Utroligt! Du fandt dem! Du er virkelig en helt, <Name>!\n\nDet er en god ting, for jeg har læst de tavler, du bragte mig før, og ud fra det, jeg har samlet … får vi brug for en helt til at stoppe det, der er på vej …"},
  [4808] = {n="Felnøk Stålfjeder", l="Giv Tinkees brev til Felnøk Stålfjeder.", d="Jeg har endnu en tjeneste, jeg vil bede dig om.\n\nMit indledende studie af den essens, du indsamlede, viser, at det måske er muligt at fryse drageunger og bevare dem! Jeg vil teste denne teori, men først har jeg brug for specialfremstillede ingeniørkomponenter. Min kollega, Felnøk Stålfjeder, kan lave dem.\n\nHer, tag dette brev med til Felnøk. Det fortæller ham, hvad jeg har brug for. Du finder Felnøk i Vintersol, i byen Evigblik.", p="Det er koldt herovre! Jeg håber, du har medbragt et tæppe til mig!", c="Det er ikke noget tæppe! Men hvad har vi her? Et brev fra Tinkee? Jeg undrer mig over, hvad hun har at sige …\n\nAh, hun studerer i Brændende Stepper. Det giver mening – det er en god kilde til drageslægtninge. Men se! Der står, at hun har brug for nogle dele til en apparat, hun vil bygge. Jeg gætter på, at det er der, jeg kommer ind i billedet, hva'?"},
  [4809] = {n="Kuldevindshorn", l="Bring 8 Uknækkede Kuldevindshorn til Felnøk Stålfjeder.", d="Jeg har det meste af det, Tinkee har brug for, men jeg mangler én vigtig komponent, og det er kuldevindshorn. Hornene fra kuldevindskimæraen i Vintersol er en koncentreret kilde til kulde, men kun upletterede, uknækkede horn duer! Jeg får brug for en forsyning af dem for at fuldende Tinkees bestilling.\n\nBring mig de uknækkede kuldevindshorn, så forbereder jeg en pakke til Tinkee.", p="Har du kuldevindshornene, <Name>?", c="Det er gode eksemplarer. De er fulde af kulde! Lad mig få nogle handsker på, og så pakker jeg dem sammen med de andre ting, Tinkee har brug for …"},
  [4810] = {n="Tilbage til Tinkee", l="Bring Felnøks pakke til Tinkee Dampkedel i Brændende Stepper.", d="Okay, alt er klargjort og pakket og klar til transport! Held og lykke på din rejse, og sørg for at fortælle Tinkee, at hun skylder mig!", p="<Name>! Talte du med Felnøk? Bragte du de komponenter, jeg har brug for?", c="Du bragte dem! Fantastisk! Jeg går straks i gang! Mange tak, <Name>!\n\nDu har været så hjælpsom for mig, at jeg måske får brug for dig til endnu vigtigere opgaver senere …"},
  [4813] = {n="Fragmenterne indeni", l="Rapportér, hvad du har fundet, til Vagt Glynda Nal'Skæl i Auberdin.", d="Månebrøndens vand har afsløret, at der inde i krystallen er nogle få små fragmenter af knogle samt en halv kæbeknogle. Kæbeknoglen ser ud til at stamme fra et humanoide, men det er uklart uden at knække krystallen op – en bedrift, som selv den stærkeste magi ville finde næsten umulig.\n\nNår opgaven er fuldført, er alt, hvad der er tilbage, at rapportere tilbage til Vagt Glynda Nal'Skæl i Auberdin.", c="Nå, det ser ud til, at vi ved mere om denne krystal, men det har også givet os flere ubesvarede spørgsmål!\n\nJeg tager de oplysninger, du har afdækket, med til rådet her i Auberdin. Måske ved de, hvilken fremgangsmåde man skal følge med denne krystal. Nå, hvis der overhovedet er én at følge; indtil videre er truslen langt nok mod øst til at være ude af fare.\n\nVær så venlig at tage dette. Betragt det som en belønning for et veludført stykke arbejde, <Name>."},
  [4822] = {n="Du skriger, jeg skriger...", l="Hent noget Jordbæris til din skyldling. Drengen ser ud til at foretrække Tigule og Forørs mærke-is.", d="IS! Åh, vær nu sød, vær sød, vær sød, kunne du hente noget is til mig?! Jordbær er min yndlingssmag, og der findes ikke bedre jordbæris i hele verden end Tigule og Forørs Jordbæris! Det er min yndlingsis i hele den vide verden!\n\nJeg fik den engang for længe siden, da jeg var ved væddeløbsbanen i Skimrende Sletter, men jeg hørte, at de måske sælger den i byen nu! Er du snild? Pænt, pænt, er du snild? Med Tigule og Forørs Jordbæris på toppen??!?!", p="Jeg ønsker, de ville lave flere smagsvarianter end jordbær, men jeg må vel have været heldig, at jordbær er min yndlingssmag!", c="Mmmmmmmmm! Jeg elsker deres jordbæris! Hvis der er én ting, Tigule og Forør kan, så er det at lave is!\n\nTak skyldigst <Name> - dette er den bedste godbid nogensinde!"},
  [4842] = {n="Mærkelige kilder", l="Følg Donova Snedals instrukser, og rapportér derefter tilbage.", d="For at sige dig sandheden, selvom der ingen vulkaner er her i Vinterkilde, tror jeg, at der er langt mere truende grunde til disse varme kilder...\n\nNå, jeg tror, du vil have lyst til at se det selv. Du skal rejse hele Vinterkilde på langs og tage helt sydpå. Når luften bliver tyk og klam, og himlen bliver mørk, har du fundet det, jeg tror er kilden til de varme kilder.\n\nKig dig omkring. Jeg er sikker på, at du får mange spørgsmål, når du vender tilbage.", p="Vandet i kilderne ser ud til at have nogle meget underlige egenskaber... Jeg er stadig usikker på, hvad det betyder...", c="Ja, dæmonerne dernede i Mørkehviskerkløften; jeg tror, det er deres tilstedeværelse, der påvirker landet på denne måde. Jeg vil fortsætte med at holde øje med de varme kilder her og se, om jeg lærer mere.\n\nJeg ville vente, til du er lidt stærkere, hvis du har planer om at begive dig længere ind i Mørkehviskerkløften."},
  [4861] = {n="Rasende vildkin", l="Find Jaron Stenformers ødelagte lejr og forsyninger i det sydlige Vinterkilde.", d="Hej der, dreng! Jeg blev jagtet væk fra min lejr i det sydlige Vinterkilde af nogle blodtørstige vildkin! Nå, jeg må nok være kommet for tæt på noget, som vildkinene vogtede.\n\nJeg slap knap nok væk i sikkerhed; jeg frygter, at en ven af mig ikke var lige så heldig. Ville du have noget imod at trodse vildkinene og tage hen til lejren? Jeg har virkelig brug for mit udstyr, og jeg vil også gerne have amuletten tilbage, som jeg gravede op i går ved udgravningsstedet.", c="En alvorligt beskadiget kasse skiller sig ud blandt de andre knuste ejendele i lejren..."},
  [4862] = {n="Ækelt", l="Rejs til Sortklippe-spiret og saml 15 Spiret-edderkoppeæg til Kiblet.\n\nEfter det at dømme skulle disse æg kunne findes i nærheden af edderkopper.", d="Tro det eller ej, der er folk derude, som er villige til at betale for det mest ækle af tamme dyr!\n\nJeg sendte Bijou ind i spiret for at prøve at samle nogle af de spiret-edderkoppeæg, men jeg har ikke hørt fra hende i flere uger. Måske kan du hjælpe mig?\n\nLad mig sige dig, <Name>. Tag til Sortklippe-spiret og saml nogle spiret-edderkoppeæg til mig. Bring dem tilbage hertil, og så giver jeg dig ikke bare en skilling, jeg tæmmer endda et til dig!", p="Er de edderkoppeæg i din rygsæk, eller er du bare glad for at se mig?", c="For en belastning! Jeg mener, se alle de æg! Dem her burde indbringe en pæn bunke guld.\n\nSom lovet, her er dit eget lille kryb. Pas på, at det ikke bider dig!"},
  [4863] = {n="Rasende vildkin", l="Find Jaron Stenformers ødelagte vogn.", d="Når du kigger dig omkring, kan du ikke se meget, som Jaron kunne ønske sig her. Men du bemærker, at kassen, du fandt, er blevet sprængt op, næsten som om det var det, vildkinene var ude efter...\n\nMod øst kan du lige præcis skimte en forladt vogn. Måske finder du Jarons ting der. Det er værd at kigge efter.", c="Da du nærmer dig vognen, ser det ikke ud til, at der er meget mere til Jaron her. Men da du kigger ned på jorden, bemærker du nogle kasser, der ser uskadte ud, selvom de er halvt begravet i sneen."},
  [4864] = {n="Rasende vildkin", l="Saml Jarons forsyninger op fra sneen, og find derefter vildkinene, der stjal amuletten, som Jaron talte om.\n\nBring Jarons forsyninger og den blåfjerede amulet til Jaron Stenformer i logen i Vinterkilde.", d="Efter at have inspiceret indholdet af kassen, har du besluttet, at Jaron kunne have glæde af værktøjet og de andre ting indeni. Men der er ingen tegn på amuletten.\n\nDet ser ud til, at vildkinene holder til i landene mod nord og øst herfra, så du beslutter, at næste skridt er at konfrontere væsenerne og få amuletten tilbage fra dem.", p="Ja... Fortæl mig nyhederne.", c="Nå, det havde jeg regnet med at høre, dreng. Jeg gætter på, at de gale udyr ødelagde alle mine ejendele...\n\nMen du fandt mit værktøj, og vigtigst af alt, amuletten! Jeg undrer mig over, hvorfor vildkinene forsvarede denne genstand så voldsomt... Under alle omstændigheder vil jeg tænke mig om to gange, før jeg begiver mig derop igen!"},
  [4866] = {n="Moders Malk", l="I hjertet af Sortklippe-spiret finder du Moder Smøgerspind. Angrib hende og få hende til at forgifte dig. Der er god chance for, at du også må dræbe hende. Vend tilbage til Lasede John, når du er forgiftet, så han kan 'malke' dig.", d="Det er nok et af de kraftigste gifte i verden, <Race>!\n\nJeg har overhørt Sortklippe-folkene tale om dens dødelighed, når jeg har været på vandring i spiret. De kalder det 'Moders Malk', opkaldt efter Moder Smøgerspind, den store, ækle edderkop i Skitterspind-hulen.\n\nNu er her, hvad jeg har brug for fra dig: En levende prøve af Malken, der flyder gennem DINE årer! Det er ikke nok bare at bringe mig kirtlen! Få hende til at forgifte dig, og kom tilbage til mig!\n\nSå... så får jeg lov at malke dig!\n\n<Gnider hænderne sammen i forventning.>", p="<Lasede John knibser dig.>", c="Det her bliver den bedste øl nogensinde!\n\nEh, hvad troede du, jeg skulle bruge det til? Gift eller noget??\n\nSkøre unger..."},
  [4867] = {n="Urok Undergangsylen", l="Læs Warosh' rulle. Bring Warosh' magi til Warosh.", d="Argh! Så svært at tale!\n\nTag denne seddel! Hent mig min magi!", p="Ah! Har du min magi?", c="Aha! Jeg kan allerede mærke mine kræfter vende tilbage til mig. Og mit sind er ikke længere plaget af Uroks forbandelse.\n\nTak, <Name>! Ydmyghed er under mig, men jeg må anerkende din hjælp.\n\nOg jeg ønsker dig held på dine rejser gennem Sortklippe-spiret. Du er tosset, hvis du tror, du kan nå toppen, men din tapperhed er uden tvivl."},
  [4882] = {n="Bevogtede hemmeligheder", l="Tag den blåfjerede halskæde til Trull Fejlbane ved Blodgift-posten.", d="Du er usikker på betydningen af halskæden, der faldt fra halsen på det nyligt dræbte vildkin. Den lyser kraftigt og bliver langsomt svagere og stærkere igen.\n\nTrull Fejlbane kunne måske fortælle dig mere, for hans viden om vildkinene synes omfattende. Måske skulle du spørge ham om den.", p="Rapporterer du for en ny opgave?", c="En vigtig opdagelse?"},
  [4883] = {n="Bevogtede hemmeligheder", l="Tag den blåfjerede halskæde til Nara Vildmane.", d="Selvom jeg besidder megen viden om ugleudyrene, du besejrede i Vinterkilde, er jeg ikke særlig belæst om de magier, de benytter. Men jeg tror, jeg kender en, der kunne undersøge halskæden og sandsynligvis fortælle dig, hvad den er.\n\nNara Vildmane i Tordenklippe er ekspert på dette område; gå og se hende. Held og lykke, <Name>.", p="Hvordan kan jeg hjælpe dig, <Name>?", c="Energien i denne halskæde, <Name>. Jeg tror, den kun har ét udspring.\n\n<Nara lukker øjnene og er stille et øjeblik.>\n\nVildkinene, nu vildledte og forvirrede, var engang ikke sådan. De havde engang et formål og blev styret til at tjene. Natteelvergudinden Elunie skabte disse væsener for at vogte hendes mest hellige områder.\n\nSelvom dette måske virker af ringe værdi, opfordrer jeg dig til at se dybere.\n\nDu vil lære det med tiden. Tak, fordi du bragte dette til mig, <Name>."},
  [4901] = {n="Vogterne af alteret", l="Beskyt Ranshalda, mens hun forsøger at genaktivere Elunies alter. Rapportér dine fund til Erelas Ravhimmel i Rutteran-landsbyen.", d="Helt oppe på højdedragets top ligger, hvad jeg tror er et alter for gudinden Elunie. Så vidt jeg kan se, skal vi tænde de fem fakler i hver hule, og så kan vi få direkte adgang til alteret.\n\nJeg har nedskrevet nogle besværgelser, der er indhugget i stenen i de gamle ruiner i Kel'Thæril, og jeg tror, de er nøglen til at låse alteret op. Jeg skal bruge din hjælp til at tænde hver fakkel, mens jeg rejser besværgelsen.\n\nHvis vi lykkes, kan du rapportere vores fund til Erelas!", c="Mødte du Ranshalda?"},
  [4902] = {n="Vildkin af Elunie", l="Tal med Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Det er fascinerende!\n\nJeg har altid undret mig over sandheden... Nå, du skal bestemt dele denne viden! Gå straks til Ærkedruide Fandrel Hjorthelm -- du finder ham i Darnassos, i Cenarion-kredsen. Fortæl ham, hvad der skete, præcis som du fortalte mig. Jeg er sikker på, at han vil være lige så interesseret!\n\nDette er vigtige oplysninger, <Name>!", c="Tøv ikke; fortæl mig, hvorfor du er kommet.\n\nÅh, ja? Hmm. Nå.\n\nTak, fordi du bragte dette direkte til mig; det er altid bedst at gå lige til toppen... Men... Ja. Druiderne i Cenarion-kredsen har kendt til vildkinene i lang tid. At de er Elunies kæledyr, og at de blev udvalgt til at vogte de mest hellige steder.\n\nSå selvom dette ikke er nyt, roser jeg bestemt din indsats. Her, tag denne -- den synes passende for sådan en bedrift."},
  [4903] = {n="Krigsherrens befaling", l="Dræb Højlord Omkrog, Krigsmester Voone og Overherre Ormethalak. Genvind vigtige Sortklippe-dokumenter. Vend tilbage til Krigsherre Goretooth i Kargat, når missionen er fuldført.", d="På Krigsherre Goretooths befaling skal følgende indbyggere i Sortklippe-spiret udslettes:\n\nDen tykke trussel, Højlord Omkrog.\n\nDen grusomme og ubarmhjertige troll, Krigsmester Voone.\n\nOverherre Ormethalak, pisker af den mindre by.\n\nDu skal også aflevere eventuelle vigtige dokumenter, du måtte finde.\n\nLykkes du, skal du hædres.\n\nMislykkes du, skal du glemmes.", p="<Krigsherre Goretooth hilser.>", c="<Krigsherre Goretooths kedelige grønne hud bliver et øjeblik kridhvid.>"},
  [4904] = {n="Fri endelig", l="Eskortér Lakota Vindsang fra Mørkeskye-tinden, og tal derefter med Thalia Ravhud i Frihvind-posten.", d="Arnak tror, vi skal giftes... men efter at jeg afslog hans tilbud, kom han tilbage den nat og kidnappede mig. Min bror forsøgte at stoppe ham, men Arnak var for stærk. Han... han dræbte min bror og tog mig så med hertil. Min stakkels bror...\n\n<Name>, kunne du eskortere mig ud af Mørkeskye-tinden? Vær sød... Jeg må tilbage til Thalia! Hun må være dødsensbange for mig.", p="Thalia Ravhud:", c="Tak, <Name>. Helt inde i mine knogler vidste jeg, at hun ville finde tilbage til mig. Hun fortalte mig om din tapperhed, og hvordan du hjalp hende med at flygte. Disse ting tilhørte hendes bror. Jeg ved, hun ville ønske, at du skulle have dem."},
  [4906] = {n="Yderligere fordærvelse", l="Eridan Blåvind i Ondskoven ønsker, at du dræber 8 Jadeild-helvedeskaldere, 8 Jadeild-forrædere, 8 Jadeild-narrer og Xavaric. Vend tilbage til Eridan, når opgaven er fuldført.", d="En anden lejr af satyrer truer landet Ondskoven mod nord, ledet af den grusomme Xavaric. De onde forrædere og narrer lever af fordærvelsen hos Ondskovens oprindelige væsener.\n\nXavathras og hans håndlangere var kun en del af en større plan -- at dyrke en fordærvet månebrønd og derefter give udbyttet til Xavaric.\n\nNu hvor Xavathras er ude af vejen, skal du fuldføre denne opgave, <Name>. Tag mod nord og besejr Xavaric.", p="Vær venlig at sætte en stopper for lidelserne hos Ondskovens væsener.", c="Tak for alt, hvad du har gjort, <Name>. Må Elunie beskytte dig og guide dig på vejen forude."},
  [4907] = {n="Tinkee Dampkedel", l="Tal med Tinkee Dampkedel.", d="Hej, <Name>. Husker du Tinkee Dampkedel? Nå, hun husker dig! Hun sendte mig en besked om at holde øje med dig, for... hun har brug for din hjælp igen. Jeg tror, det har noget at gøre med hendes studier af drager.\n\nDu skal tale med hende i Brændende Stepper, ved Flammevåbenskjold.", c="Felnøk havde ret! Jeg har brug for din hjælp igen, og denne gang... det bliver virkelig farligt.\n\nEr du klar??"},
  [4941] = {n="Eitrigs visdom", l="Tal med Eitrig i Orgrimgrad. Når du har drøftet sagerne med Eitrig, så søg råd hos Thrall.\n\nDu husker at have set Eitrig i Thralls kammer.", d="Flænse lever?\n\nUmuligt!\n\nMan havde troet, at Flænse blev dræbt for årtier siden.\n\nSøg visdommen hos Eitrig, <Name>. Ingen kender Sortklippens virke bedre end ham, og hvis det, der står skrevet her, er sandt, bør Eitrig informeres. Ingen person bør nægtes retten til hævn.\n\nDu finder ham i Orgrimgrad.\n\nNår du har talt med Eitrig, så konsulter krigshøvdingen for at finde ud af, hvad han ønsker at gøre ved dette problem.", p="Kan du ikke se, at jeg ikke må forstyrres?", c="<Thrall virker forfærdet over nyheden, du bringer.>"},
  [4961] = {n="Renselse af Orahels kugle", l="Dræb dæmonen i kuglen, og tal derefter med Tabetha.", d="Ah, en besværgerkugle -- det er her, fordærvelsen må komme fra. Vi må uddrive dæmonen indeni, hvis du skal bruge den. Det kan jeg let klare.\n\nDu er den, der har det svære job. Du skal dræbe dæmonen, når jeg har løsladt den.\n\nOg du må være hurtig. Hvis du tager for lang tid, vender han tilbage til kuglen, og så må vi starte forfra!\n\nSå gør dig klar, <Name>. Forbered dine stærkeste besværgelser, hold dine eliksirer ved hånden, og find en ven, hvis du har en. For dette bliver ikke pænt.", p="Du må dræbe den dæmon for permanent at fjerne dens tilstedeværelse fra kuglen, <Name>.", c="Flot gjort, <Name>! Du gav den dæmon en lektie, han ikke glemmer med det samme. Du har vist stor kraft og dygtighed. Nu er det vel tid for dig at vende tilbage til Menara med din rensede kugle, så du kan bruge den til noget godt.\n\nHeld og lykke, <Class>. Måske krydser vores veje hinanden igen."},
  [4962] = {n="Splint af en ondhund", l="Tag Ondhas-rubinen og brug den på en af ondhundene i Forødelse. Når det er lykkedes, skal du bringe Ondhas-rubinen og den fængslede ondhund-ånd tilbage til Menara Tomrumsrivet i Ødemarken.", d="Så du har valgt at fange en ondhunds sjæl, godt.\n\nTag denne rubin -- med den vil du kunne fange skabningens sjæl. Det fungerer meget ligesom de besværgelser, du allerede kender: Når skabningen er tæt på at dø, så brug ædelstenen, og den klarer resten af arbejdet for dig.\n\nJeg vil foreslå, at du tager til Forødelse og prøver din hånd med en af ondhundene dér. De burde klare sig fint.\n\nNår det er lykkedes, skal du tage både den fangede ånd og din rubin til Menara.", p="Ja, <Name>? Har du valgt? Helvedesvæsen eller ondhund?\n\nHvert valg er personligt og bør afspejle dine styrker og svagheder. Det er ikke ukendt, at en hekser forbedrer sig selv yderligere i stedet for at kompensere for de områder, de mangler. Nogle gange er det at overvælde en fjende lige så stærk en taktik som at blive en mere balanceret besværgelsesudøver.", c="Ah, ondhundens ånd. Godt gjort, <Name>.\n\nNår jeg har både ånden og den rensede kugle, vil jeg smelte de to sammen for dig, men ikke før da."},
  [4963] = {n="Splint af et helvedesvæsen", l="Tag Infus-smaragden og brug den på et af helvedesvæsnerne i Forødelse. Når det er lykkedes, skal du bringe Infus-smaragden og den fængslede helvedesvæsen-ånd tilbage til Menara Tomrumsrivet i Ødemarken.", d="Så du har valgt at fange et helvedesvæsens sjæl, godt.\n\nTag denne smaragd -- med den vil du kunne fange skabningens sjæl. Det fungerer meget ligesom de besværgelser, du allerede kender: Når skabningen er tæt på at dø, så brug ædelstenen, og den klarer resten af arbejdet for dig.\n\nJeg vil foreslå, at du tager til Forødelse og prøver din hånd med et af helvedesvæsnerne dér. De burde klare sig fint.\n\nNår det er lykkedes, skal du tage både den fangede ånd og din smaragd til Menara.", p="Ja, <Name>? Har du valgt? Helvedesvæsen eller ondhund?\n\nHvert valg er personligt og bør afspejle dine styrker og svagheder. Det er ikke ukendt, at en hekser forbedrer sig selv yderligere i stedet for at kompensere for de områder, de mangler. Nogle gange er det at overvælde en fjende lige så stærk en taktik som at blive en mere balanceret besværgelsesudøver.", c="Ah, et helvedesvæsens ånd. Godt gjort, <Name>.\n\nNår jeg har både ånden og den rensede kugle, vil jeg smelte de to sammen for dig, men ikke før da."},
  [4964] = {n="Den færdige Dar'Orahels kugle", l="Vent på, at Menara Tomrumsrivet færdiggør Dar'Orahels kugle, og tal derefter med hende igen.", d="Jeg går straks i gang med at fremstille din kugle og indgyde din nye dæmon i den. Når det er færdigt, får du valget mellem en stav eller en kugle. Jeg har altid syntes, det var vigtigt at tilgodese en heksers valgte våben... Jeg ser ingen grund til ikke at fortsætte den praksis.", c="Det er færdigt, <Name>. Sig blot, hvilken du foretrækker: en stav, der kræver, at du bruger begge hænder, eller en kugle, så du kan bruge en dolk eller et sværd som våben.\n\nAt tackle en ondhund var en stor bedrift fra din side. Jeg er sikker på, at din genstand vil tjene dig godt i fremtiden. Bliv ved med at arbejde hårdt med kunsterne, <Name>. Jeg vil afvente detaljer om dine bedrifter."},
  [4965] = {n="Viden om Orahels kugle", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Nå, nå, nå... dejligt at se, at du vokser i styrke, <Name>. Jeg vil vædde på, at du er ret klar til at tale med Menara Tomrumsrivet i Ødemarken. Hvis du ikke har talt med hende før, så lad mig fortælle dig, at jeg ikke tror, jeg nogensinde har mødt en anden ekspert i fremstilling af genstande -- kugler specifikt -- der kan fængsle selv en dæmon, så den tjener vores vilje så let.\n\nHvis du er interesseret, er hun i Strahads tårn over Skralleby i Ødemarken.", c="Ah, du søger noget mere... betydningsfuldt. Det kan jeg hjælpe dig med, hvis du virkelig er parat.\n\nDet er en velkommen forandring at se en af vores slags søge mere magt i andre former end blot viden.\n\nSå, føler du dig klar, <Name>?"},
  [4967] = {n="Viden om Orahels kugle", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Stadig et fjols, og stadig på jagt efter dødelige tings pynt. Ja, jeg taler til dig med arrogance. Jeg ser dig foran mig og ler. Du er patetisk!\n\nMen det betyder ikke noget, hvad jeg mener. Det er kun, hvad de, der er villige til at handle med dig, mener! Og i dette tilfælde mener nogle med en vis magt, mod min bedre vurdering, at du fortjener mere.\n\nHvis det er noget, du stræber efter, så bør du tale med Menara Tomrumsrivet i tårnet over Skralleby. Jeg tror, du har mødt hende før for nogen tid siden.", c="Ah, du søger noget mere... betydningsfuldt. Det kan jeg hjælpe dig med, hvis du virkelig er parat.\n\nDet er en velkommen forandring at se en af vores slags søge mere magt i andre former end blot viden.\n\nSå, føler du dig klar, <Name>?"},
  [4968] = {n="Viden om Orahels kugle", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Hmm, du er nået så langt... virkelig forbløffende. Jeg havde troet, at fordærvelsen fra at kanalisere arkane kræfter ville have sivet ind i din sjæl og drevet dig gal nu. Hvad med at vi prøver at presse dig længere?\n\nHvis du vil teste dine evner, så søg Menara Tomrumsrivet over Skralleby i Strahads tårn. Hun vil guide dig.", c="Ah, du søger noget mere... betydningsfuldt. Det kan jeg hjælpe dig med, hvis du virkelig er parat.\n\nDet er en velkommen forandring at se en af vores slags søge mere magt i andre former end blot viden.\n\nSå, føler du dig klar, <Name>?"},
  [4969] = {n="Viden om Orahels kugle", l="Tal med Menara Tomrumsrivet i Ødemarken.", d="Haha! Du klarer dig meget godt for dig selv, unge <Class>.\n\nMed tiden vil helvedesvæsner og frygtherrer bøje sig for dig!\n\nMen indtil den tid kommer, må du stadig stole på våben smedet af de dødelige folkeslags hænder.\n\nDu virker klar til endnu en sådan skabelse, og hvis du er villig, vil Menara Tomrumsrivet gerne tale med dig! Hun er nær Strahads tårn, der ser ud over havnebyen Skralleby. Tag derhen, når du er klar.", c="Ah, du søger noget mere... betydningsfuldt. Jeg kan hjælpe dig, hvis du virkelig er parat.\n\nDet er en velkommen forandring at se en af vores slags søge mere magt i andre former end blot viden.\n\nSå, føler du dig klar, <Name>?"},
  [4971] = {n="Et Spørgsmål om Tid", l="Brug Tidsforskyderen ved et af Andorhøjs siloer og afdæk Tidsparasitter.\n\nDræb 15 Tidsparasitter, og returner derefter Tidsforskyderen til Kromie i Andorhøj-kroen, Vestlige Pestlande.", d="Tidslinjen er blevet manipuleret af en ond kraft - højst sandsynligt Svøben - i Andorhøj! Jeg kan forsøge at holde tidens gang intakt her og reparere det, der er gået i stykker, men jeg har brug for din hjælp for at kunne gøre det uafbrudt.\n\nTidsparasitter - ådsler, der lever af tidens ændrede strømme - inficerer nu Andorhøjs siloer. En blå puls af forvrængning er deres eneste synlige kendetegn. De forstyrrer mine varsler; <Name>, hjælp mig venligst ved at bruge denne tidsforskyder til at rydde op i disse parasitter.", p="Tidsparasitter er en almindelig plage, der findes overalt, hvor tidens strøm er blevet manipuleret. Jeg fornemmer, at der er mange af dem, og det er foruroligende.\n\nAt rydde op i dem, du kan finde, vil hjælpe mig med at få et bedre tag i den forværrede tidssituation her. Jeg vil kunne mærke, når det er lykkedes.", c="Tiden føles nemmere at reparere nu, tak <Name>. Selvom du måske ikke helt forstår konsekvenserne af en splittet tidslinje, sætter jeg pris på, at du forstår hastværket i at modarbejde det, jeg mere og mere mistænker er en Svøben-drevet misgerning.\n\nJeg ser ingen skade i at belønne dig for din hjælp, dødelige. Dine største bedrifter er endnu til at komme, og en lille smykkesten vil bestemt ikke ændre din fremtidige skæbne. Din fortsatte hjælp er dog noget, både jeg og drageflugten kunne bruge..."},
  [4972] = {n="Tiden Tælles Ud", l="Find 5 Andorhøj-ure, der findes i låseskrin blandt byens ruiner. Vend tilbage med dem til Kromie i Andorhøj-kroen, Vestlige Pestlande.", d="Jeg har brug for, at du rækker ind i verden uden for dette rum, <Name>. Lad mig forklare.\n\nDu ser forskellen på dette rum sammenlignet med resten af Andorhøj. Min drageflugt arbejder på mange forskellige måder og i mange forskellige tidslinjer. For at reparere Andorhøjs skade handler jeg nu fra en anden tidslinje, for ikke at forurene den for meget. For at fortsætte dette har jeg dog brug for tidstrinkler, sådanne der blev fanget, da pesten ramte. Find dem i låseskrinene i de ødelagte bygninger, der udgør denne engang så stolte by.", p="Tidstrinklerne, jeg søger, er simple genstande. Det er mest ure, og deres visere blev fanget for evigt, da pesten første gang hærgede Andorhøj.\n\nTiden har ingen ende, og urene, du bringer mig, vil uundgåeligt tælle sig selv tilbage til deres hjem... altså så længe forstyrrelserne fortsætter her.", c="Præcis det, jeg har brug for, <Name>. Tak.\n\nLad mig belønne dig passende med dette. Du ved måske ikke, hvad du skulle bruge sådan en genstand til. Du ved måske ikke engang helt, hvad den egentlig er. Desværre kan jeg ikke fortælle dig, hvornår du vil få mest glæde af den; bare vid, at du på et tidspunkt i fremtiden kan finde denne genstand yderst nyttig og virksom, når den indtages. Om du vælger at beholde den indtil da... det er op til dig, min ven."},
  [4974] = {n="For Hordens Skyld!", l="Rejs til Sortklippe-spiret og dræb Krigshøvding Flænse Sortehånd. Tag hans hoved og vend tilbage til Orgrimgrad.", d="Rend tør fremsætte så store påstande, fordi den sorte drageflugt beskytter ham.\n\nDu, <Name>, finder en vej gennem Opstigningens Haller. Derefter finder du 'Krigshøvding' Flænse Sortehånd, og du vil ødelægge ham - FOR HORDEN!\n\n<Trall slår en knytnæve ned på sin trone.>\n\nNæste gang du vender tilbage til mine kamre, skal du holde hans hoved højt i triumf, og derefter skal du overrække det til din Krigshøvding. Gør du det, vil du blive hædret som en helt for Horden.", p="<Trall grynter.>", c="Du har givet Sortklippe-styrkerne et lammende slag, <Name>. Med deres krigshøvding dræbt, er Sortklippe-legionen endnu en gang kastet ind i kaosets gab.\n\nTil ære for dine heltedåd skal Kalimdørs folk belønnes!"},
  [4975] = {n="Den Færdige Kugle fra Noh'Orahel", l="Vent på, at Menara Tomrumsrivet fuldender Noh'Orahels kugle, og tal derefter med hende igen.", d="Jeg går straks i gang med at fremstille din kugle og indgyde din nye dæmon i den. Når det er færdigt, får du valget mellem, at den tager form som en stav eller en kugle. Jeg har altid syntes, det var vigtigt at tilgodese en hekseklods' valgte våben... og jeg ser ingen grund til ikke at fortsætte den praksis.", c="Den er færdig, <Name>. Fortæl mig blot, hvilken du foretrækker: en stav, der kræver begge hænder, eller en kugle, så du kan bruge en dolk eller et sværd som våben.\n\nAt tage hul på helvedesvæsenet var en stor bedrift fra din side, og denne belønning vil passe dig godt. Jeg ønsker dig yderligere succes i kunsterne, <Name>."},
  [4976] = {n="Den Renskede Kugle Returneres", l="Returner den renskede helvedeskugle til Menara Tomrumsrivet i Ødemarken.", d="Tag den renskede kugle tilbage til Menara i Skralleby, <Name>. Hils hende fra mig og pas på dig selv. Jeg håber virkelig, at du kan modstå fristelsen og fordærvelsen, som helt sikkert vil komme, når du følger din vej.\n\nHeld og lykke.", p="Hvordan går det med din eftersøgning efter Tabitha og kuglen, <Name>?\n\nTabitha har været mere end nyttig, når det gælder det arkane. Jeg er sikker på, at hun ikke vil have noget imod at hjælpe dig, hvis du kan finde hende.", c="Godt gjort, <Name>. Det her duer fint.\n\nDet eneste, der er tilbage for dig, er at beslutte, hvilken dæmon du vil have mig til at fængsle i den renskede kugle. Gør det, og du får en prægtig ny genstand at svinge."},
  [4981] = {n="Agent Bijou", l="Rejs til Sortklippe-spiret og find ud af, hvad der er sket med Bijou.", d="Stol aldrig på en kobold. Det er det hele, <Name>.\n\nBijou hedder hun - en af vores glatteste agenter. Jeg fandt ud af, at hun arbejdede for en tvivlsom eksotisk kæledyrshandler fra Brændende Stepper ved navn Kiblet, med andre ord spillede hun dobbeltspil mod os. Værre endnu, hun brugte Hordens midler til at finansiere sine operationer.\n\nJeg vil have hende bragt tilbage hertil i live.\n\nHun blev sidst set gå ind i Sortklippe-spiret. Find hende og bring hende tilbage.\n\nOg <Name>, lad hende ikke overtale dig med sin søde snak.", c="Jeg vil ikke lyve for dig, <Race>. Jeg havde brug for pengene! Kiblet betaler meget, meget godt - langt bedre end K.E.K. nogensinde kunne.\n\nMen tvivl ikke på min loyalitet! Hvorfor tror du, jeg er hernede? For at skaffe den skøre kobold nogle eksotiske dyreæg eller noget lige så åndssvagt? Nej, kun nogen, der er virkelig tossede, ville komme til Sortklippe-spiret for at samle kæledyr. Jep, jeg tror ikke, der findes ret mange mennesker som dem i denne verden.\n\n<Bijou ler.>\n\nDet sidste, vi har brug for, er, at den slags mennesker formerer sig."},
  [4982] = {n="Bijous Ejendele", l="Find Bijous ejendele og returner dem til hende. Du husker, at hun nævnte, at hun gemte dem på byens nederste etage.", d="Om natten, når dette sted er let bevogtet, sniger jeg mig rundt i byen, skriver noter og noterer alt, jeg ser, der kunne have en strategisk værdi for K.E.K.\n\nI går gik det dog frygteligt galt. Jeg snublede over en snubletråd og udløste en alarm. Jeg gemte mit spionudstyr og løb efter dækning! Desværre kan jeg ikke komme tilbage til det udstyr. De har fordoblet og tredoblet patruljerne! Al den information er tabt.\n\nFå mine ejendele tilbage, så vender jeg fredeligt tilbage til K.E.K.", p="Har du held?", c="Du har klaret det! Når Lekslort har disse planer, vil han glemme alt om de grimme ting, han ville gøre ved mig.\n\n<Name>, du er min helt!"},
  [4983] = {n="Bijous Efterretningsrapport", l="Tag Bijous efterretningsrapport tilbage til Stormester Lekslort i Kargat.", d="Tag denne rapport tilbage til Lekslort. Den vil genoprette mit gode navn og vil helt sikkert give K.E.K. en strategisk fordel i håndteringen af disse orker.\n\nKomme med dig? Jeg har alt for meget arbejde at lave. Af sted med dig, de har brug for disse rapporter så hurtigt som muligt!", p="Hvor er kobolden???", c="Jeg må hilse, at hun har formået at snirkle sig ud af endnu en klæbrig situation! Disse rapporter vil vise sig at være uvurderlige i vores håndtering af Sortklippe-orkerne.\n\nSelvfølgelig bliver du belønnet for dit hårde arbejde."},
  [4984] = {n="Dyrelivet Lider Også", l="Dræb 8 sygdomsramte ulve, og vend derefter tilbage til Mulgris Dybfloden ved Vridende Hjemsøgelse, Vestlige Pestlande.", d="Selvom jeg alene kunne gøre lidt for at standse Svøben, kom jeg til disse lande for at forsøge at hele naturen for den skade, der er gjort. Dyr lider under pesten, der fortsat kvæler disse lande, og de kan ikke finde nåde og fred. Jeg beder dig om at fortsætte, hvad jeg ikke kunne fuldende her.\n\nDer er ingen frelse for de lidende dyr, undtagen en sød og barmhjertig udfrielse. Søg de sygdomsramte ulve i nærheden og gør ende på dem. Gør det, <Name>, gør ende på deres lidelse - det vil sikkert også lindre min.", p="De ulve, der er smittet med pesten, skal nedlægges, <Name>. Sygdommen, de bærer, kan ikke kureres. Jeg prøvede... jeg prøvede, indtil jeg selv bukkede under for pesten.", c="Jeg... jeg fornemmer, at sjælene hos de ulve, du har nedlagt, nu har hvile. De - og jeg - takker dig for en barmhjertig udfrielse.\n\nUlvene er ikke de eneste, der lider på dette forbandede sted, <Name>. Venligst, jeg har brug for dig endnu en gang."},
  [4985] = {n="Dyrelivet Lider Også", l="Dræb 8 sygdomsramte grizzlybjørne, og vend derefter tilbage til Mulgris Dybfloden ved Vridende Hjemsøgelse, Vestlige Pestlande.", d="Mod øst herfra, hvor de Østlige Pestlande begynder, vandrede engang stolte og majestætiske grizzlybjørne rundt i landskabet. Pesten, som Svøben har sluppet løs, har også splittet disse dyr. De vandrer rundt i landskabet, plaget af deres muskler, der stivner, og deres pels og kød, der rådner.\n\nJeg beder dig om at gøre ende på deres lidelse også. Den eneste kur mod deres lidelse er en hurtig død, som må leveres af din hånd.", p="Jeg hører dine fodtrin, <Name>. Mit syn har svigtet mig, men jeg kan stadig fornemme ting omkring mig. Har du gjort ende på de sygdomsramte grizzlybjørnes lidelse?", c="\"Jeg ved, at grizzlybjørnene er blevet nedlagt, deres pine er ovre. Jeg... jeg har en ting mere til dig. Jeg skrev det ned på... på denne gren, da jeg fornemmede, at min tid i denne verden var kommet til ende.\n\nJa... jeg er ved den ende. Tak igen, ven... skabningerne i dette forbandede land må hvile... og nu må jeg også.\"\n\nMed det udstøder druiden en tung suk, efterfulgt af, hvad der lyder som et dødsrallen. Hans krop ligger ubevægelig på hyttens gulv."},
  [4986] = {n="Glyferet Egegren", l="Ud fra magien fortryllet i den glyferede egegren er dens levering til Cenarion-kredsen i Darnassos det næste skridt, som taurendruiden ønskede. Søg en af druiderne der for hjælp.", d="Den livløse hånd fra taurendruiden klemmer om en overraskende sund udseende egegren. Ved nærmere undersøgelse af grenen ses glyffer af druidisk natur indskåret i barken.\n\nNår du tager fat i grenen, bemærker du, at den er varm at røre ved, mere end den burde være. Billedet af Teldrassøl-træet dukker op i dit sind - specifikt Darnassos - og ordene \"Cenarion-kredsen\" ligger på tungen af dig. Det virker til, at forslaget om, hvor grenen skal bringes hen, er blevet placeret i den.", p="På vegne af Cenarion-kredsen byder jeg dig velkommen til denne enklave, <Class>. Hvad er dit ærinde her hos os?", c="Det... det her er ret mærkeligt. Denne druide - denne taurendruide ligefrem - betroede dig en masse værdifuld information om omfanget af Svøbens pest. Jeg er overrasket over, at en taurer ville give en <Race> sådan information, og endda frit, hvis det, du siger, er sandt. Vi vil gøre godt brug af det, det lover jeg dig. Måske er taurerne ikke faldet så langt fra Cenarus, som Fandrel ville tro...\n\nØh, ja, værsgo - accepter dette som et tegn på tak fra Cenarion-kredsen."},
  [4987] = {n="Glyferet Egegren", l="Ud fra magien fortryllet i den glyferede egegren er dens levering til Cenarion-kredsen i Tordenskrænt det næste skridt, som taurendruiden ønskede. Søg en af druiderne der for hjælp.", d="Den livløse hånd fra taurendruiden klemmer om en overraskende sund udseende egegren. Ved nærmere undersøgelse af grenen ses glyffer af druidisk natur indskåret i barken.\n\nNår du tager fat i grenen, bemærker du, at den er varm at røre ved, mere end den burde være. Billedet af Tordenskrænt i Mulgorr dukker op i dit sind - specifikt Ældrehøjen - og ordene \"Cenarion-kredsen\" ligger på tungen af dig. Det virker til, at forslaget om, hvor grenen skal bringes hen, er blevet placeret i den.", p="På vegne af Cenarion-kredsen byder jeg dig velkommen til denne enklave, <Class>. Hvad er dit ærinde her hos os?", c="Det her er fra Mulgris, siger du? Vi havde hørt, at han søgte at tage sig af skabningerne, der led i Pestlandene, men dette er meget uventet... og meget bedrøveligt. Mulgris er... var en god ven. Jeg vil sørge dybt over hans bortgang.\n\nHans bestræbelser har ikke været forgæves, takket være din flid. I denne gren er der gemt megen viden om pesten, som Svøben udbreder over landet. Vi vil studere den flittigt. Og du, accepter venligst dette. Det er det mindste, vi kan gøre for din ædle indsats."},
  [5001] = {n="Bijous Ejendele", l="Find Bijous ejendele og returner dem til hende. Held og lykke!", d="Normalt beskæftiger jeg mig ikke med <Race>er, men det ser ud til, at jeg sidder klemt mellem Skylla og Karybdis. Se, min opgave her er af højeste vigtighed for Horden. Oplysningerne, jeg har opdaget, gælder dog også for Alliancens velfærd. Tro mig, jeg er ingen Alliance-sympatisør, men Sortklippe-truslen er større end blot en flok orker.\n\nHjælp mig med at finde mine ejendele, så hjælper jeg dig med nogle oplysninger, der kan vise sig nyttige for din slags.\n\nAftale?", p="Har du held?", c="Nå, da være det sagt! Hvor var de nu??"},
  [5002] = {n="Besked til Maksvel", l="Rejs til Brændende Stepper og giv Bijous efterretninger til Marskal Maksvel.", d="Jeg er en kobold af mit ord, <Race>. Lyt nu godt efter:\n\nDisse orker bruges primært som trækdyr og kanonfoder for den sorte drageflugt!\n\nDeres sande leder er ingen anden end Nefarian, Dødsvinges yngel. Jeg har også opdaget, hvor Nefarians undergivne befinder sig i denne del af citadellet.\n\nTag dette kort med til Marskal Maksvel i Brændende Stepper. Det har placeringen af disse djævle markeret, så de let kan identificeres.", p="Ah, <Name>. Det er længe siden.", c="Dette stemmer overens med meget af det, vi allerede vidste. Uanset hvad, er det interessant og temmelig uheldig information.\n\nMarkeringerne på dette kort vil vise sig at være værdifulde, når det gælder om at tynde ud i Sortklippe-truslen."},
  [5021] = {n="Bedre Sent End Aldrig", l="Spøgelseskvindens vrøvl antydede, at hun havde brug for, at en pakke blev leveret. Hun påstod, at den var, hvor hendes hest var. Hvor hesten er, eller hvor pakken skulle leveres hen - det forbliver spøgelset ubegribeligt.", d="\"Pakken skal leveres... leveret, før jeg bliver fanget her!\"\n\nDen panikslagne kvindes skrig lyder næsten som en hvisken, der flyder gennem huset. Krøbet i det øverste hjørne er spøgelsesbilledet af en kvinde. Hun virker ikke helt bevidst om sine omgivelser, og hun er kun svagt opmærksom på dig.\n\n\"Er du her for at levere min pakke? Vær venlig, før det bliver meget værre! Jeg skulle til at ride væk herfra. Den burde stadig være ved min hest... eller er jeg for sent på den?\"", c="En pakke i laden, som du ellers måske havde overset, træder nu frem midt i forfaldet og ruinen. Måske er det den, som spøgelset af Janis Felsten har skreget om..."},
  [5022] = {n="Bedre Sent End Aldrig", l="Tjek hos de Kongelige Faktorer i Stormvind for at finde ud af, hvor en Emma Felsten befinder sig. Der er normalt en folketællingsembedsmand placeret i rådhuset.", d="Du samler pakken op og tørrer et tyndt lag støv og snavs af, der havde lagt sig på den. Den er adresseret i en hastig hånd til en Emma Felsten fra Stormvind; leveringen af pakken er dateret for over fire år siden.\n\nSelvom det er uklart, om Emma Felsten overhovedet er i live, er det almindeligt kendt, at Stormvind Rådhus fører optegnelser over byens borgere. Dette håndteres af de Kongelige Faktorer i Stormvinds folketælling.", p="Velkommen til Stormvinds folketællings kontor. Hvis du har brug for oplysninger om vores befolkning, kan jeg hjælpe dig.", c="En pakke til en Emma Felsten, siger du? Sidste kendte adresse var Stormvind, for fire år siden? Lad mig lige se her...\n\nIfølge det, vi ved, var der en Emma Felsten i byen for omkring fire år siden. Nå, jeg bør nok sige muligvis - denne folketælling, jeg henviser til, er fra for fem år siden, og jeg har ingen rapport om, at hun har forladt byen. Det betyder dog ikke, at hun stadig er her.\n\nVent et øjeblik... kan denne pakke ikke være til Gamle Emma?"},
  [5023] = {n="Bedre Sent End Aldrig", l="Tjek hos de Kongelige Tilsynsførere i Underbyen for at finde ud af, hvor en Jeremias Felsten befinder sig. Der er normalt en folketællingsembedsmand placeret nær gilde- og tabardregistreringen.", d="Du samler pakken op og tørrer et tyndt lag støv og snavs af, der havde lagt sig på den. Den er adresseret i en hastig hånd til en Jeremias Felsten fra Herrelande; leveringen af pakken er dateret for over fire år siden.\n\nSelvom det er uklart, om Jeremias Felsten overhovedet er i live, er det almindeligt kendt, at Underbyen, tidligere kendt som Herrelande, fører optegnelser over byens borgere. Dette håndteres af de Kongelige Tilsynsførere i Underbyens folketælling.", p="Er du her for at søge hjælp hos Underbyens folketælling, eller bare for at spørge mig, om en du kendte er død? Det bliver jeg tit spurgt om.", c="En pakke til en Jeremias Felsten, med hans sidst kendte adresse som Herrelande... Jeg burde kunne hjælpe dig.\n\nJeremias Felsten var i byen før pesten. Nå, jeg bør nok sige den tidligere Jeremias Felsten - nogle af de Forladte har ændret deres efternavne for at blive af med deres tidligere ansigt. Denne sag er ingen undtagelse; den tidligere Jeremias Felsten kendes nu som Jeremias Betalsen.\n\nVent et øjeblik... er han ikke kakerlakhandleren?"},
  [5047] = {n="Finkle Enhjørning, til Deres Tjeneste!", l="Tal med Malifus Mørkhammer i Evigblik.", d="Du finder Malifus Mørkhammer i Evigblik, <Class>. Fortæl ham, at 'Finkle er A-OK', og at dragten virker perfekt.\n\nRæk ham derefter dette:\n\n<Finkle rækker dig et lysende stykke kød.>\n\nJeg snuppede det fra bæstets indvolde under min 'ferie.'\n\nJeg vætter på, at Malifus kan give dig en ret præcis vurdering af, hvad han kan gøre med dele fra sådan et uhyre!\n\nÅh, jeg antager, at du ikke ved, hvor Evigblik ligger, gør du? Til Vinterkilde, makker!", p="Ja?", c="I live? Dragten virkede? Og hvad har vi her?"},
  [5048] = {n="Den Godmodige Emma", l="Find Gamle Emma i Stormvind og se, om hun faktisk er Emma Felsten. Hvis hun er, vil hun måske gerne have pakken, Janis Felsten lavede til hende.", d="Hun er en smule gnaven og måske ganske skør... men optegnelserne viser, at Gamle Emma passer til billedet af, hvem Emma Felsten kunne være.\n\nMåske har du set Gamle Emma vandre rundt i byen - hun taler med sig selv, oftest i meningsløst pludder. Men hun gør ikke noget ondt mod nogen, så folk lader hende for det meste være i fred.\n\nSamlet set vil jeg sige, at Gamle Emma faktisk er Emma Felsten. Du kunne spørge hende, om hendes efternavn virkelig er Felsten.", p="Jeg ville bede dig om at forlade min græsplæne, men som du kan se, har jeg ingen.", c="Mit navn er faktisk Emma Felsten - du er den første person i årevis, der kalder mig det. Hvem... hvem er du?\n\nDu siger, at du kendte... min søster?! Er hun stadig i live? Hvem vil jeg narre, selvfølgelig er hun ikke. Da pesten brød ud i Herrelande, havde jeg forventet det værste. Så mange af min familie døde... eller værre. Her står jeg nu, skøre Gamle Emma, helt alene. Hvad er du, en gravrøver eller sådan noget? På jagt efter dit næste offer?\n\nHvad... har du en pakke til mig fra min søster?"},
  [5049] = {n="Jeremias-blues", l="Find Jeremias Betalsen i Underbyen og se, om han faktisk er Jeremias Felsten. Hvis han er, vil han måske gerne have pakken, Janis Felsten lavede til ham.", d="Ud fra de beviser, jeg kan samle, er den person, du leder efter - og den tiltænkte modtager af pakken - Jeremias Betalsen, kakerlakhandleren fra Underbyen.\n\nJeg har altid været af den opfattelse, at det kræver en særlig gave at sælge... kakerlakker. Utvivlsomt er du på en ret episk odysse nu, mægtige <Class>. Jeg vil lade dig være til dine verdensskabende bestræbelser. Lad mig dog få lov til at være en del af dit mesterværk og afsløre, at han befinder sig nær banken, passende krybende under en af gangbroerne.", p="Hver gang nogen træder på en kakerlak, græder jeg. Vær venlig at lade være med at få mig til at græde.", c="Jeg har ikke brugt det navn i årevis... men ja, på et tidspunkt i mit liv - før dette glorværdige udliv - var det mit efternavn.\n\nDu påstår, at du kendte min søster... eller rettere, at du for nylig har talt med min søster.\n\nSom er død.\n\nI fire år.\n\nVed du hvad, hvis mine knogler ikke allerede var skøre nok, ville jeg være fristet til at brække min fod af på din bagdel. Du er ret en gribbe, ikke sandt?\n\nHvad... har du en pakke til mig fra min søster?"},
  [5050] = {n="Lykkeamulet", l="Vend tilbage til Janis Felsten i Vestlige Pestlande med hendes Halve Lykkeamulet.", d="Det ser ud til, at jeg tog fejl af dig, <Name>, og for det skylder jeg dig en undskyldning. Min søster sendte mig en række personlige effekter, deriblandt humoristisk nok skødet til Felsten-gården. Jeg tror, jeg vil lade være med at gøre krav på den lige nu.\n\nHvis min søsters ånd forbliver bundet til gården og ikke kan hvile, så vil du venligst returnere dette til hende? Det er halvdelen af et lykkeamulet, hun havde, mens hendes mand havde den anden halvdel.\n\nMåske vil hendes viden om, at jeg har disse ting, nu sætte hendes sjæl til hvile.", p="Johan, skat... er det dig? Jeg er så kold pludselig...", c="Du rækker det halve amulet tilbage til spøgelset. Hun ser på det og derefter på dig, forventningsfuldt.\n\n\"Skat, hvor lagde du din halvdel af amuletten? Vi kan ikke være sammen, medmindre vi har begge halvdele. Skat... kan du se mig?\""},
  [5051] = {n="To Halvdele Bliver Til Én", l="Find den anden halvdel af Lykkeamuletet et sted på Felsten-gården i Vestlige Pestlande og sæt det sammen igen.\n\nGiv Lykkeamuletet til Janis Felsten på Felsten-gården, Vestlige Pestlande.", d="Den fattige ånds vrøvl fortsætter:\n\n\"Jeg er så kold, Johan. Giv mig din amulet, så bliver vi sammen! Hurtigt Johan, før pesten kommer og forvandler os til grimme bæster! Jeg kan ikke se dig Johan... men jeg ved, du er i nærheden. Jeg fornemmer dig tæt på mig.\"\n\nMåske, hvis den anden halvdel af amuletten blev fundet og samlet igen, ville det udgøre det, som Janis Felstens ånd søger.", p="Johan, lad ikke ghouler'ne få dig... lad ikke ghouler'ne få mig... ondskabsfulde ghouler... vores amulet vil holde os i sikkerhed.", c="Du rækker det samlede lykkeamulet til Janis Felstens spøgelse. Så snart hun griber det, bemærker du en næsten øjeblikkelig forandring i hende. Hendes ætheriske skikkelse skimrer, og hun ser på dig med klare, men triste øjne.\n\n\"Du har befriet mig... jeg behøver ikke længere dette amulet. Tag det venligst, og måske vil det give dig den trøst, det har givet mig.\""},
  [5054] = {n="Ursius fra Skårtanden", l="Storm Skyggehov i Evigblik i Vinterkilde ønsker, at du dræber Ursius.", d="I de snedækkede bjerge i Vinterkilde, mod nordvest, lurer en dygtig jæger på sit bytte... jeg taler om Ursius fra skårtandbjørnene, et smidigt og snedigt udyr.\n\nJeg sender dig nu imod ham. Han strejfer rundt i de skrånende bakker nordvest for Evigblik. Find og jag ham, før han opdager dine hensigter.\n\nAlle, der har stillet sig op mod Ursius, har hurtigt fundet sig selv som byttet, og ham som jægeren. Vær på vagt.", p="Gå nu, <Class>. Søg efter Ursius.", c="Dette var ingen let opgave, og alligevel har du excelleret. Men skynd dig ikke at tro, at du har imponeret mig, <Name>."},
  [5055] = {n="Brumeran fra Kuldevind", l="Storm Skyggehov i Evigblik i Vinterkilde ønsker, at du dræber Brumeran.", d="Hurtig og snedig glider Brumeran lydløst hen over det snedækkede landskab i det sydlige Vinterkilde. Men lad ikke hendes yndefulde fremtoning overbevise dig om, at hun er harmløs. Alle, der krydser hendes vej, betaler dyrt, og ofte med deres eget liv.\n\nSøg Brumeran fra Kuldevind blandt kimærerne. Besejr hende, og vend derefter tilbage til mig.", p="Brumeran kalder på dig, <Name>.", c="Ja. Du er vendt tilbage. Jeg tror nu, at du er en sand jæger af natur. Du har stået over for de mest rasende af skabninger og er vendt tilbage og har overgået mine forventninger.\n\nDu er nu klar til min sidste anmodning."},
  [5056] = {n="Blyg-Rotam", l="Storm Skyggehov i Evigblik i Vinterkilde ønsker, at du besejrer Blyg-Rotam.", d="I det nordlige Vinterkilde samler store katte sig omkring et stort vartegn kaldet Frostsabel-klippen. Lederen af disse katte kendes ved navnet Blyg-Rotam. At besejre frostsablernes matriark ville give dig megen respekt i dine artsfællers øjne, <Race>.\n\nGå igen ud i de barske vildnis, og når du er der, så saml hellig kød fra frostsablerne. Find Blyg-Rotams sten, og placer den der. Ved at placere kødet fra hendes slægtninge foran hende, vil du kalde Blyg-Rotam frem i vrede.\n\nVær klar til hendes raseri, og besejr hende.", p="Blyg-Rotam er dristig og ubarmhjertig; hun vil forsvare sit folk med brændende iver.", c="Du har bevist både din styrke og din beslutsomhed. Mange flere udfordringer venter dig, men jeg har allerede vist dig så meget, som jeg er i stand til."},
  [5057] = {n="Tidligere Bestræbelser", l="Bring Storm Skyggehovs markør til Melor Stenhov i Tordenskrænt.", d="Før du talte til mig, <Name>, havde jeg hørt om dine bestræbelser... at du havde en ubøjelig trang til at bevise dig selv, at du havde en enestående evne som <Class>, og nu ved jeg, at det er sandt.\n\nDem, der udmærker sig som du, er værdige til anerkendelse. Tag denne markør med til en ven af mig i Tordenskrænt ved navn Melor Stenhov. Jeg er sikker på, at han vil huske dig og hvad du udrettede for så længe siden. Fortæl ham om dine nylige sejre, og glem aldrig, hvad du har udrettet i dag.", c="Vi lærer af vores livserfaringer, <Name>. Jeg er sikker på, at du kun er blevet stærkere og klogere af dine. Du er vokset meget, siden vi første gang talte sammen.\n\nTag dette som en erindring om de svære opgaver, du har udført som <Race> <Class>, og vid, at du altid vil have min respekt og beundring."},
  [5058] = {n="Fru Dalsens Dagbog", c="En dagbog med gulnede sider ligger åben ved den sidste indtastning:\n\n\"Jeg ved ikke, hvad der skal ske nu, hvor Harald er blevet forvandlet. Det tog alt, hvad jeg havde, at slæbe ham ind på det eneste sted, jeg kunne finde, der kunne låse ham inde og holde ham fast. Jeg gemte nøglen på mig, og jeg beder til, at den virker...\n\nJeg håber, jeg kan komme herfra, men jeg har brug for penge til det. Vores ting står vist alt sammen i skabet... og nu hvor jeg tænker over det, har Harald vel ikke nøglen på sig?\n\nJeg hviler mig lidt, jeg er dødtræt nu.\""},
  [5060] = {n="Låst Væk", p="Et yderst robust skab står foran dig, sikkert låst med en indbygget lås. Skabets forside er dybt ridset og mærket. Det kunne tyde på talrige og voldsomme mislykkede forsøg på at afsløre de hemmeligheder, skabet lige nu skjuler for synet.\n\nHvis du vil åbne dette skab, skal du finde nøglen.", c="Nøglen, der blev taget fra Bonde Dalsens ghoul-agtige rester, passer perfekt i låsen. Skabets døre svinger op og afslører flere genstande, der stadig er intakte og ser ganske værdifulde ud."},
  [5061] = {n="Akvatisk Form", l="Vend tilbage til Darnassos og vis Mathrengyl Bjørnegænger Søløvens Vedhæng.", d="Du har gennemført de nødvendige lektioner, alle unge druider lærer, før de kan antage en akvatisk skikkelse. Gå nu tilbage til din læremester, Mathrengyl Bjørnegænger, i Darnassos. Vis ham dit vedhæng og bevis over for ham, at du er klar til at lære det, han har at lære dig. Han vil fuldføre din træning, så du kan blive ét med vandet.\n\nFarvel, unge druide. Vi ses igen.", p="Din tilbagevenden til Darnassos bliver ikke uden fanfare, men jeg får brug for bevis for de lektioner, du har lært i Månelunden, før jeg vil lære dig din akvatiske form.\n\nHar du Søløvens Vedhæng?", c="Meget imponerende, <Name>. Du er klar til at lære din akvatiske form, og det er en fornøjelse for mig at lære dig den.\n\nSom anerkendelse af din præstation under de to prøver giver jeg dig også denne genstand. Jeg håber, du vil finde den som en velkommen tilføjelse til dit udstyr som naturens beskytter og balancens vogter."},
  [5065] = {n="De Tabte Tavler fra Mosh'aru", l="Bring den tredje og fjerde Mosh'aru-tavle til Prospektor Jernstøvle i Tanaris-ørkenen.", d="Trolden, du talte med, fortalte ikke sandheden. De to tavler, du fik for ham, talte om at indeholde essensen af Hakar, men der er mere til legenden. Jeg har studeret længe og fundet ud af, at der er seks Mosh'aru-tavler, ikke to! Seks!\n\nOg jeg frygter, at vi ikke kommer til at kunne lide de hemmeligheder, de andre gemmer på..\n\nFind den tredje og fjerde Mosh'aru-tavle. De er i de østlige Pestlande, holdt af mosflåer-trolde. Find dem, og bring dem til mig.", p="Har du tavlerne? Jeg frygter, at deres tekster vil afsløre en stor trussel mod vores verden.", c="Du fandt dem! Storartet!\n\nTak, <Name>. Jeg vil gennemgå disse tekster og tyde deres betydning.\n\nDu har dog en anden opgave..."},
  [5066] = {n="Kald til Våben: Pestlandene!", l="Søg Kommandør Ashlam Tapperhedsnæve. Hans hovedlejr ligger i Kuldevind-lejren, nord for Alterac-bjergene.", d="Hør, hør! Alle helte opfordres til at lytte til disse ord!\n\nDer er udstedt et kald til våben af Stormvinds Rige! Alle raske individer opfordres til at tage våben op mod Svøbens mørke trussel i de nordlige lande i Østkongerigerne! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Pestlandene!\n\nHeltene i riget - søg Kommandør Ashlam Tapperhedsnæve, som har slået sin hovedlejr op i Kuldevind-lejren, nord for Alterac-bjergene!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, især med den truende Svøbe mod vores nord og nordøst. Jeg er glad for at høre, at pligtens og tjenestens klare kald til det større gode ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5081] = {n="Maksvels Missionen", l="Rejs til Sortklippe-spiret og ødelæg Krigsmester Vuun, Højlord Omkrog og Overherre Ormethalak. Vend tilbage til Marskal Maksvel, når opgaven er udført.", d="Denne information udfylder hullerne i vores ellers upåklagelige efterretninger om Sortklippe-spiret.\n\nAngrebet skal være afgørende, <Name>.\n\nFørst skal deres krigsmester, trolden Vuun, ødelægges. Uden hans slagplaner vil Sortklippe-orkerne blive kastet ud i kaos.\n\nDerefter skal du tage oger-højlorden Omkrog. De kujonagtige oger fra Sortklippe er magtesløse uden hans lederskab.\n\nTilsidst citadellets overherre: Ormethalak. Når Ormethalak er død, er deres centrale kommandoenhed uden en forbindelse.", p="Status?", c="Fremragende arbejde, <Name>. I det mindste har du købt os mere tid - dyrebar, dyrebar tid."},
  [5082] = {n="Vinterfaldets Trussel", l="Donova Snedal i Vinterkilden vil have dig til at dræbe 8 Vinterfald-stifindere, 8 Vinterfald-hulevagter og 8 Vinterfald-totemikere.", d="Jeg kom til Vinterkilden for at undersøge Frostild Varmekilder. Jeg har bemærket, at vandet ser ud til at have ...mærkelige egenskaber. Jeg har endnu ikke kunnet finde kilden, og for at fortælle dig sandheden har jeg haft lidt besvær på det seneste på grund af Vinterfald-pelsbolgene.\n\nDe ser ud til at blive tiltrukket af kilderne, ligesom jeg er. De er blevet ekstremt beskyttende over for vandet og lader mig ikke komme i nærheden af de to største kilder nord for her.\n\nJeg vil gerne fortsætte mine studier, så vil du ikke hjælpe mig?", p="Jeg sætter pris på din hjælp!", c="Mange tak, <Name>! Nu kan jeg vende tilbage til mit arbejde her.\n\nFandt du noget interessant i Vinterfald-lejren?"},
  [5083] = {n="Vinterfald-ildvand", l="Bring den tomme Ildvand-kolbe til Donova Snedal i Vinterkilden.", d="Dette hætteglas, du tog fra Vinterfald-pelsbolgen, er tomt, men du kan registrere et par dråber af en mærkelig grøn væske indeni; den lyser næsten.\n\nEr det noget vigtigt?\n\nDonova Snedal ville sikkert kunne fortælle dig mere, da hun har campet ved varmekilderne i Vinterkilden i et stykke tid nu.", p="Hvad er det, du har fundet?", c="Fik du dette fra Vinterfald-pelsbolgen?"},
  [5084] = {n="Falden til Fordærvelse", l="Undersøg Dødtræ-pelsbolgenes lejr i det nordlige Ondskoven for et spor.", d="Denne grønlige væske... den minder mig lidt om slammet, jeg så, da jeg rejste gennem Ondskoven. Og jeg har set nogle Vinterfald-løbere passere ind i Tømmerkæft... Måske har disse ting noget at gøre med kolben, du fandt, <Name>.\n\nDer er en stor flok pelsbolge lige forbi Tømmerkæft Greb i Ondskoven. Kaldet Dødtræ-stammen er de blevet fordærvet og drevet til vanvid af det dæmoniske. Hvorfor kigger du ikke rundt der og ser, om du kan finde spor af forbindelser mellem Vinterfald og Dødtræ?", c="Inde i gryden bobler en rådden, frastødende lugtende substans..."},
  [5085] = {n="Gådeklister", l="Rapporter tilbage til Donova Snedal med dine fund.", d="Den grønne substans inde i gryden ser ud til at ligne det, du fandt i kolben. Dette mærkelige klistrede stof kunne være lige så fordærvet som pelsbolgen, der skabte det...\n\nHvis Vinterfald-pelsbolgene bruger det, betyder det så, at de snart vil være lige så fordærvede som Dødtræ-stammen?\n\nDet ville være bedst at rapportere tilbage til Donova med dine fund sammen med en prøve af væsken i gryden.", p="Jeg håber, du fandt noget, <Name>. Vinterfald bliver stadig mere aggressive!", c="Du er meget snarrådig, <Name>. Tror du, at Vinterfald-pelsbolgene har været i Dødtræ-lejren?"},
  [5086] = {n="Giftige Rædsler", l="Saml 3 Giftig Rædsel-dråber til Donova Snedal i Vinterkilden.", d="Jeg har studeret prøven, du kom tilbage med, og selvom jeg ikke kan sige det med sikkerhed, tror jeg, den indeholder spor af giftige elementer. Den eneste måde at vide det med sikkerhed på er dog at samle nogle til sammenligning.\n\nJeg tror, at Dødtræ-pelsbolgen måske samler disse elementer fra andre fordærvede væsener i Ondskoven; især elementarerne, der lever i Jerntræ-skovene, kaldet giftige rædsler.\n\nSaml nogle prøver til mig, så jeg kan sammenligne, men vær forsigtig -- det er meget farligt der!", p="Jeg tror, vi begynder at afdække, hvad der foregår her, <Name>.", c="Jeg skal sammenligne dette med stoffet, du fandt i gryden, og så er jeg sikker på, at vi ved mere."},
  [5087] = {n="Vinterfald-løberne", l="Find Vinterfald-løberne og stop dem i at levere deres forsendelse til Vinterfald-landsbyen.", d="Meget interessant, <Name>...\n\nNår dette giftige stof blandes med vandet fra varmekilderne, mister det sin giftighed og beholder kun evnen til midlertidigt at påvirke dem, der indtager det. Det må være grunden til, at Vinterfald beskytter varmekilderne så ivrigt -- de har brug for dem til at rense deres ildvand.\n\nVi må stoppe dette -- afbryde forbindelsen mellem Vinterfald og Dødtræ. En gruppe løbere går strækningen mellem deres landsby og Ondskoven. Find og besejr dem, og stjæl deres forsendelse.", p="Vi må se, hvad der sker, når Vinterfald ikke får deres ildvand!", c="<Donova undersøger indholdet af kassen.>\n\nJeg undrer mig over, om indtagelse af dette stof gør pelsbolgene mere aggressive. De virker jo meget større..."},
  [5089] = {n="General Drakkisats Kommando", l="Tag General Drakkisats Kommando til Marskal Maksvel i Brændende Stepper.", d="Fra den besejrede slanges lig finder du, hvad der ser ud til at være et vigtigt brev: Et brev fra hans overordnede, General Drakkisat, om protokol.\n\nDin instinkt fortæller dig, at du bør tage det med til Marskal Maksvel.", p="Hvad har du dér, <Name>?", c="Plottet tykner..."},
  [5090] = {n="Kald til Våben: Pestlandene!", l="Søg Kommandør Ashlam Tapperhedsnæve. Hans hovedlejr ligger i Kuldevind-lejren, nord for Alterac-bjergene.", d="Hør, hør! Alle helte opfordres til at lytte til disse ord!\n\nDer er udstedt et kald til våben af Stormvinds Rige! Alle raske individer opfordres til at tage våben op mod Svøbens mørke trussel i de nordlige lande i Østkongerigerne! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Pestlandene!\n\nHeltene i riget - søg Kommandør Ashlam Tapperhedsnæve, som har slået sin hovedlejr op i Kuldevind-lejren, nord for Alterac-bjergene!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, især med den truende Svøbe mod vores nord og nordøst. Jeg er glad for at høre, at pligtens og tjenestens klare kald til det større gode ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5091] = {n="Kald til Våben: Pestlandene!", l="Søg Kommandør Ashlam Tapperhedsnæve. Hans hovedlejr ligger i Kuldevind-lejren, nord for Alterac-bjergene.", d="Hør, hør! Alle helte opfordres til at lytte til disse ord!\n\nDer er udstedt et kald til våben af Stormvinds Rige! Alle raske individer opfordres til at tage våben op mod Svøbens mørke trussel i de nordlige lande i Østkongerigerne! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Pestlandene!\n\nHeltene i riget - søg Kommandør Ashlam Tapperhedsnæve, som har slået sin hovedlejr op i Kuldevind-lejren, nord for Alterac-bjergene!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, især med den truende Svøbe mod vores nord og nordøst. Jeg er glad for at høre, at pligtens og tjenestens klare kald til det større gode ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5092] = {n="Ryd Vejen", l="Dræb 10 Skelet-flåere og 10 Savlende Ådselædere i Sorgbakken.\n\nVend tilbage til Kommandør Ashlam Tapperhedsnæve i Kuldevind-lejren, Vestlige Pestlande.", d="Med Andorhøjs vestlige og nordlige veje ind i byen godt befæstet, vil jeg angribe fra den mindre forsvarede østlige vej. Svøben er afhængig af bufferzonen af udøde, der hærger Sorgbakken, som en første forsvarslinje. Hvis vi skal rykke frem mod Andorhøj, må vi gøre det gennem Sorgbakken.\n\nDin første opgave bliver at rydde vejen gennem Sorgbakken. Tynd ud i skeletterne og ådselæderne, der hjemsøger området; rapportér tilbage til mig, når det er gjort!", p="Jeg vil have dig til at forberede dig på det værste, <Name> - grav dybt. Opgaven foran os bliver ikke let. Mens vi samler vores styrker her for til sidst at slå ud mod Svøben, bliver du en del af vores fremrykningsindsats, der tager kampen til dem! Din tildelte mission i Sorgbakken vil starte vores vej mod sejr!", c="Mission udført, <Name>! Vel spillet, vel spillet.\n\nLad mig belønne dit arbejde indtil nu med lidt guld fra Stormvinds kister. Jeg vil anbefale at bruge det på materiel, der vil hjælpe dig i din næste mission... en, der vil føre dig ind i ruinerne af Andorhøj selv.\n\nVær parat! Vær på vagt!"},
  [5093] = {n="Kald til Våben: Pestlandene!", l="Søg Overeksekutor Derrington. Hans hovedlejr ligger ved Bolværket, øst for Tirisdal-lysningen og Underbyen.", d="Riges helte, hør mig - Horden kalder på jer til hurtig handling!\n\nDer er udstedt et kald til våben for alle raske individer til at tage våben op mod Svøben! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Østkongerigerne. De truer øst for Underbyen, i de nordlige egne af landene, der nu kaldes Pestlandene!\n\nHeltene i riget - søg Overeksekutor Derrington, som har slået sin hovedlejr op ved Bolværket, øst for Tirisdal-lysningen!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, med den truende Svøbe mod vores øst, og så endnu længere mod øst derfra. Jeg er glad for at høre, at pligtens og tjenestens kald til Horden ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5094] = {n="Kald til Våben: Pestlandene!", l="Søg Overeksekutor Derrington. Hans hovedlejr ligger ved Bolværket, øst for Tirisdal-lysningen og Underbyen.", d="Riges helte, hør mig - Horden kalder på jer til hurtig handling!\n\nDer er udstedt et kald til våben for alle raske individer til at tage våben op mod Svøben! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Østkongerigerne. De truer øst for Underbyen, i de nordlige egne af landene, der nu kaldes Pestlandene!\n\nHeltene i riget - søg Overeksekutor Derrington, som har slået sin hovedlejr op ved Bolværket, øst for Tirisdal-lysningen!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, med den truende Svøbe mod vores øst, og så endnu længere mod øst derfra. Jeg er glad for at høre, at pligtens og tjenestens kald til Horden ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5095] = {n="Kald til Våben: Pestlandene!", l="Søg Overeksekutor Derrington. Hans hovedlejr ligger ved Bolværket, øst for Tirisdal-lysningerne og Underbyen.", d="Riges helte, hør mig - Horden kalder på jer til hurtig handling!\n\nDer er udstedt et kald til våben for alle raske individer til at tage våben op mod Svøben! Rygter flyver om nye trusler, der rejser sig fra ruinerne i Østkongerigerne. De truer øst for Underbyen, i de nordlige egne af landene, der nu kaldes Pestlandene!\n\nHeltene i riget - søg Overeksekutor Derrington, som har slået sin hovedlejr op ved Bolværket, øst for Tirisdal-lysningerne!", c="Velkommen til Pestlandene, helt. Dette er en af de farligste grænseegne i Azerot, med den truende Svøbe mod vores øst, og så endnu længere mod øst derfra. Jeg er glad for at høre, at pligtens og tjenestens kald til Horden ikke faldt på døve ører hos dig!\n\nHvis du er klar til at tage fat, er der nok at lave for villige og dygtige helte her på kanten af Pestlandene."},
  [5096] = {n="Skarlagenrøde Afledninger", l="Tag til Skarlagenrøde Korstogs hovedlejr mellem Felsten-marken og Dalsens Tårer og ødelæg deres kommandotelt.\n\nPlacér Svøbens banner ved lejren, og vend derefter tilbage til Overeksekutor Derrington ved Bolværket, Vestlige Pestlande.", d="Før Andorhøj må vi tage fat på den fremrykkende Skarlagenrøde Korstog-trussel fra Hjertedal. De har slået lejr mellem Felsten-marken og Dalsens Tårer, og det tvinger os til at risikere konflikt med både Svøben og Korstoget på én gang.\n\nMin plan er at spille dem ud mod hinanden ved at sende dig for at ødelægge kommandoteltet, de har sat op; brug noget Flamme i en Flaske fra denne kasse med brandbomber. Når det er jævnet med jorden, plant dette Svøbens banner ved teltet. Med lidt held vil de ignorere os og fokusere på Svøben af hævn.", p="Et overraskelsesangreb på Skarlagenrøde Korstogs skrøbelige forpost vil give os en buffer af tid til at marchere mod Andorhøj. Jeg stoler på, at du er her for at rapportere succes!\n\nNår dette er gennemført, må vi arbejde flittigt og hurtigt. Vi har ikke materiel og mandskab til at kæmpe mod både Svøben og Skarlagenrøde Korstog på samme tid, hvis de ikke køber vores lille list.", c="Fint udført, <Name>. Dit angreb på Skarlagenrøde Korstog vil købe os tid. Jeg har sendt en af mine bedste spejdere ud for at holde øje med lejren og sikre, at Korstogets styrker, der kommer for at forstærke positionen, bider på krogen.\n\nNår presset er lettet, skulle vi nu endelig kunne risikere en mission ind i Andorhøj selv, og en vigtig en af slagsen. Jeg ville meget gerne, hvis du også ville udføre denne, baseret på din succes indtil nu."},
  [5097] = {n="Overalt ved Vagttårnene", l="Brug Fyrtårn-fakkelen til at markere hvert tårn i Andorhøj; du skal stå i døråbningen til tårnet for at markere det korrekt.\n\nNår alle fire tårne er markeret, skal du returnere Fyrtårn-fakkelen til Kommandør Ashlam Tapperhedsnæve i Kuldevind-lejren, Vestlige Pestlande.", d="Gennem brugen af en magisk genstand kaldet en fyrtårn-fakkel kan vi markere mål, vi selv vælger, til fremtidige handlinger for vores tropper. Derfor mener vi, at Svøben bruger Andorhøjs vagttårne som et middel til at kontrollere deres troppebevægelser.\n\nDin mission: bryd igennem Andorhøjs forsvar for at placere fyrtårne ved alle fire vagttårne. Du skal stå i døråbningen til hvert tårn for at placere fyrtårnet; det vil derefter markere tårnet. Der er kun fem ladninger på fyrtårn-fakkelen, så brug dem klogt!", p="Når tårnene er markeret, bliver de topprioriterede mål for vores angreb på Andorhøj. Jeg mistænker, at når vi neutraliserer tårnene, vil Andorhøjs hovedtrussel vise sig. Fra det øjeblik får vi en ren kamp om kontrollen over byen!\n\nDu er tilbage for at rapportere succes, ikke? Glem ikke fyrtårn-fakkelen; vi skal have styr på vores materiel.", c="Mine præster rapporterer, at vores fyrtårns-sporere opfanger ekstremt stærke signaler fra alle fire tårne! Tør jeg sige det, men jeg tror, at du har udført endnu en mission med fuldstændig succes! Vel spillet igen, <Name>!\n\nMed tårnene markeret er vores forberedelser til angrebet nu på plads. Tiden er kommet til at tage kampen til Svøben!"},
  [5098] = {n="Overalt ved Vagttårnene", l="Brug Fyrtårn-fakkelen til at markere hvert tårn i Andorhøj; du skal stå i døråbningen til tårnet for at markere det korrekt.\n\nNår alle fire tårne er markeret, skal du returnere Fyrtårn-fakkelen til Overeksekutor Derrington ved Bolværket, Vestlige Pestlande.", d="Gennem brugen af en magisk genstand kaldet en fyrtårn-fakkel kan vi markere mål, vi selv vælger, til fremtidige handlinger for vores tropper. Derfor mener vi, at Svøben bruger Andorhøjs vagttårne som et middel til at kontrollere deres troppebevægelser.\n\nDin mission: bryd igennem Andorhøjs forsvar for at placere fyrtårne ved alle fire vagttårne. Du skal stå i døråbningen til hvert tårn for at placere fyrtårnet; det vil derefter markere tårnet. Der er kun fem ladninger på fyrtårn-fakkelen, så brug dem klogt!", p="Når tårnene er markeret, bliver de topprioriterede mål for vores angreb på Andorhøj. Jeg mistænker, at når vi neutraliserer tårnene, vil Andorhøjs hovedtrussel vise sig. Fra det øjeblik får vi en ren kamp om kontrollen over byen!\n\nDu er tilbage for at rapportere succes, ikke? Glem ikke fyrtårn-fakkelen; vi skal have styr på vores materiel.", c="Mine hekseriddere rapporterer, at vores fyrtårns-sporere opfanger ekstremt stærke signaler fra alle fire tårne! Du har udført mine ordrer med en veteranes dygtighed og præcision. Din tjeneste for Horden er endnu engang noteret, <Name>!\n\nMed tårnene markeret er vores forberedelser til angrebet nu på plads. Tiden er kommet til at tage kampen til Svøben!"},
  [5102] = {n="General Drakkisats Undergang", l="Rejs til Sortklippe-spiret og ødelæg General Drakkisat. Vend tilbage til Marskal Maksvel, når opgaven er udført.", d="Vi kæmper mod disse udyr på to fronter: Fra vores hovedstad Stormvind bekæmper vi dem indefra og ud, og her i Brændende Stepper tager vi kampen til deres dørtrin. Vi må være årvågne, <Name>. Ingen skal skånes for vores vrede, da ingen af vores egne blev skånet, da de angreb vores hjem og familier.\n\nFind denne General Drakkisat og ødelæg ham!\n\nOpgaven bliver bestemt ikke enkel, men belønningen vil være overdådig.", p="Er det gjort?", c="Vi vil helt sikkert slå mod deres drageherrer næste gang. Godt gået, modige soldat i Alliancen! Godt gået, i sandhed."},
  [5103] = {n="Hed Ildende Død", l="Nogen i denne verden må vide, hvad man gør med disse handsker. Held og lykke!", d="Det eneste, der er tilbage af dette menneske, er nogle forkullede knogler. Han ser ud til at være død inden for rækkevidde af det, han var ude efter - ubrændte pladehandsker.\n\nMåske skulle du tage handskerne og komme ud af ilden?", c="Hvad i...?"},
  [5121] = {n="Overhøvding Vinterfald", l="Donova Snedal i Vintersæt vil have dig til at besejre Overhøvding Vinterfald.", d="Selvom vi stadig ved meget lidt om, hvorfor pelsbolgene har spist dette mærkelige stof, mener jeg, at det er bedst, at vi stopper det, før det løber helt af sporet.\n\nVinterfald-pelsbolgene er ikke en normalt aggressiv stamme, og denne ændring i deres adfærd får mig til at tro, at de må have fået ordre fra deres høvding. Vi kan nok ikke gøre skaden, der allerede er sket, ugjort, men jeg tror, at hvis deres leder bliver slået ihjel, bliver de ikke værre.\n\nTag mod østen til Vinterfald-landsbyen.", p="Måske finder du mere ud af det i Vinterfald-landsbyen, <Name>.", c="Mange tak, <Name>. Jeg håber at kunne vende tilbage til mine studier uden bekymring for at blive overfaldet. Venligst modtag dette som belønning."},
  [5123] = {n="Det Sidste Stykke", l="Bring den klodset-skrevne logbog til Donova Snedal i Vintersæt.", d="Logbogen, du fandt på overhøvdingen, ser omfattende ud, men efter at have kigget igennem et par af siderne, opdager du, at du ikke kan læse teksten. Markeringerne er så primitive og dårligt formede, at du ikke er sikker på, om nogen overhovedet kunne læse dem.\n\nMen måske kan Donova fortælle dig, hvad der står...", p="Nå, hvad er det nu, <Name>?", c="Jeg undrer mig over, hvad det hele betyder... Jeg kan ikke tyde noget af det..."},
  [5124] = {n="Ildende Pladehandsker", l="Bring Malifus Mørkhammer 6 fortryllede Torium-Stænger, 2 Ildens Essens og 4 Stjerne-rubiner. Du skal også aflevere dine uaffyrede Pladehandsker.", d="Ved Thaurisans skæg!\n\nHvor fandt du dem?\n\nEller rettere: er du villig til at skille dig af med dem? Naturligvis ville jeg betale dig for en så ædel gestus.\n\nJeg vil sige dig hvad, <Name>. Hvis du giver mig de uaffyrede handsker, vil jeg lære dig at lave et helt sæt til dig selv. Alt du skal gøre er at samle delene til mig, så jeg kan indsnævre den præcise opskrift.\n\nHar vi en aftale??\n\nHer er listen over, hvad jeg har brug for. Jeg vil selv forstrække pengene til den ikke-fortryllede torium, da du leverer handskerne.", p="Tid er penge, <Name>, og jeg har ikke meget af nogen af delene.", c="Som lovet, <Name>, her er din opskrift! Jeg vil også give dig en lille ekstra ting for alt dit hårde arbejde og din dedikation. Hvad skal jeg egentlig stille op med de her???"},
  [5125] = {n="Guldius' Opgør", c="<Name>, jeg dør... men min sjæl er frelst. Det skylder jeg dig mere, end ord kan sige. Tag venligst dette... og kæmp videre, modige <Class>!"},
  [5126] = {n="Lorakas' Historie", l="Tal med Lorakas. Lyt til hvad han har at sige.", d="Skovbukken går rundt og taler med sig selv. Ønsker du at spørge ham?", p="...", c="<Lorakas griner.>"},
  [5127] = {n="Dæmonsmedjen", l="Rejs til Sortklippe-spiret og find Gorahammer Ambolt-revne. Dræb ham og brug derefter den blodplettede pike på hans lig. Når hans sjæl er blevet udsuget, vil pikeen være sjælplettet.\n\nDu skal også finde den ubearbejdede runedækkede brystplade.\n\nAflever både den sjælplettede pike og den ubearbejdede runedækkede brystplade til Lorakas i Vintersæt.", d="Lorakas laver aftaler, men han accepterer dem ikke fra ubetydelige dødelige.\n\nEn aftale vil jeg dog lave med dig... tag denne pike, den er gennemsyret af stærke onde energier. Når du finder Gorahammer Ambolt-revne, skal du dræbe ham og drive denne pike gennem hans døende hjerte. Hans sjæl byttede han væk, og hans sjæl skal jeg have. Returner pikeen og returner brystpladen, som tyven stjal, så lærer jeg dig, hvad det var, han skulle lære.", p="Friste ikke...", c="Vores pagt brød du ikke. Sjælen tog jeg. Belønningen skal jeg give."},
  [5128] = {n="Overhøvdingens Ord", l="Tag den klodset-skrevne logbog til Kelek Himmelvogter i det sydlige Ondskoven.", d="Vinterfald udgør ikke længere nogen trussel for mig, men hvis du stadig vil finde ud af, hvad der drev pelsbolgene til at skabe og indtage dette mærkelige ildvand, mener jeg, at du bør opsøge Kelek Himmelvogter.\n\nHan er en del af en gruppe kendt som Smaragdkredsen, druider der er dedikeret til deres arbejde i Ondskoven, hvor de helbreder landet fra fordærvelsen.\n\nKelek har stor erfaring med pelsbolgene i Ondskoven og kan måske fortælle dig mere om logbogen.\n\nTak igen, <Name>.", p="Smaragdkredsen er venlig over for alle, <Race>. Hvad kan jeg gøre for dig?", c="Ja, hvis du lader mig undersøge dette et stykke tid, kan jeg måske oversætte det for dig.\n\n<Kelek bladrer igennem siderne.>\n\nNår jeg har kigget det helt igennem, sender jeg dig besked.\n\nTak fordi du delte dette med mig, <Name>. Der vides meget lidt om Vinterfald-pelsbolgene."},
  [5141] = {n="Drageskæl-læderarbejde", l="Bring 2 seje Skorpid-brystplader, 2 seje Skorpid-handsker og 10 slidte Drageskæl til Peter Galæn i Azsyra.\n\nAt gennemføre denne opgave giver dig adgang til Drageskæl-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Elementar-læderarbejde og Stamme-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="Drageskæl-læderarbejde er ikke let, men det er ekstremt givende. Jeg vil lære dig at lave denne fine kædepanser, men kun hvis du accepterer visse betingelser.\n\nVed at vælge denne vej accepterer du aldrig at lære elementar- eller stamme-læderarbejde; der er kun plads til en af de tre ved håndværkets top. Desuden skal jeg bruge nogle prøver af dit bedste arbejde med skorpid-rustning. Til sidst skal jeg have bevis på, at du kan skaffe handelens grundstof: skæl fra drageslægtninge.", p="Hvis du er klar til at forpligte dig til en permanent beslutning ved at blive drageskæl-læderarbejder, så er jeg klar til at tage dig som elev. Bare bring mig de ting, jeg har bedt om, så begynder din uddannelse.", c="Jeg må sige, at det kræver en stærk vilje at træffe en permanent beslutning, som du lige har gjort. Jeg forsikrer dig, at drageskæl-læderarbejde vil vise sig at være en profitabel og givende vej for dig at følge.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5142] = {n="Lille Pamela", l="Find Pamela Rødsti.", d="Så mange af os døde i slaget ved Dårshire. Så mange døde... og værre.\n\nDa slaget begyndte, gemte jeg min niece Pamela, og jeg ved ikke, hvad der skete med hende. Jeg er kun en vandrende ånd, men mit hjerte længes stadig efter at vide, hvad der er blevet af Pamela.\n\nVær venlig, gode <Class>. Vil du tage til Dårshire og lede efter hende? Det ligger mod øst, forbi Gorrons Visnende.", c="Hej. Jeg er Pamela, hvad hedder du?"},
  [5143] = {n="Stamme-læderarbejde", l="Bring en Vild Læder-vest og en Vild Læderhjelm til Caryssia Månejæger i Vildalas.\n\nAt gennemføre denne opgave giver dig adgang til Stamme-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Drageskæl-læderarbejde og Elementar-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="At lære stamme-læderarbejde kræver en forståelse af, hvordan den primitive natur virkelig er; jeg ved, at du allerede har mestret kunsten at lave vild læderrustning, og jeg er villig til at fuldende din oplæring.\n\nVed dette, <Class>: ved at vælge denne vej accepterer du aldrig at lære drageskæl- eller elementar-læderarbejde; der er kun plads til at øve en af de tre kunster. Desuden skal du bringe mig de fineste prøver af din vilde læderrustning. Derfra begynder vi din mestring.", p="Naturen er en kraft, der må formildes, før du kan håbe på at lære, hvordan du bøjer dens vilje ind i dine læderbeklædninger. Bring mig dit offer til denne kraft, så sørger jeg for, at det bliver hørt.", c="Du har givet dine fineste offergaver, og naturen vil snart tillade dig at bøje hende efter din vilje. Når jeg er færdig med min vejledning, bliver dit arbejde en naturkraft i sig selv.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5144] = {n="Elementar-læderarbejde", l="Bring 2 Ildens Hjerte, 2 Vandets Kugle, 2 Jordens Kerne og 2 Vindens Ånde til Sarah Garver i Svidende Kløft.\n\nAt gennemføre denne opgave giver dig adgang til Elementar-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Drageskæl-læderarbejde og Stamme-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="Elementar-læderarbejde er det, jeg kender, og hvis du er villig til at åbne dit sind for substansens større kræfter, vil jeg dele alt, der er at lære, med dig.\n\nVed dette, <Class>: ved at vælge denne vej accepterer du aldrig at lære drageskæl- eller stamme-læderarbejde; der er kun plads til at øve en af de tre kunster. Desuden skal jeg bruge tilstrækkeligt bevis på, at du er i harmoni med naturens elementer; derfor skal du bringe mig de reneste essenser af ild, vand, jord og vind.", p="At lave denne slags læderrustning kræver tålmodighed og dedikation. Når du først har kastet dit lod i elementernes favn, er der ingen vej tilbage. Bring mig bevis på din værdighed, så går vi i gang.", c="Du har kastet dit lod, og elementerne accepterer dig. Når jeg er færdig med min vejledning, vil du have magten til at skabe de fineste læderklæder.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5145] = {n="Drageskæl-læderarbejde", l="Bring 2 seje Skorpid-brystplader, 2 seje Skorpid-handsker og 10 slidte Drageskæl til Thorkaf Drageøje i Ødelandene.\n\nAt gennemføre denne opgave giver dig adgang til Drageskæl-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Elementar-læderarbejde og Stamme-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="Drageskæl-læderarbejde er ikke let, men det er ekstremt givende. Jeg vil lære dig at lave denne fine kædepanser, men kun hvis du accepterer visse betingelser.\n\nVed at vælge denne vej accepterer du aldrig at lære elementar- eller stamme-læderarbejde; der er kun plads til en af de tre ved håndværkets top. Desuden skal jeg bruge nogle prøver af dit bedste arbejde med skorpid-rustning. Til sidst skal jeg have bevis på, at du kan skaffe handelens grundstof: skæl fra drageslægtninge.", p="Hvis du er klar til at forpligte dig til en permanent beslutning ved at blive drageskæl-læderarbejder, så er jeg klar til at tage dig som elev. Bare bring mig de ting, jeg har bedt om, så begynder din uddannelse.", c="Jeg må sige, at det kræver en stærk vilje at træffe en permanent beslutning, som du lige har gjort. Jeg forsikrer dig, at drageskæl-læderarbejde vil vise sig at være en profitabel og givende vej for dig at følge.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5146] = {n="Elementar-læderarbejde", l="Bring 2 Ildens Hjerte, 2 Vandets Kugle, 2 Jordens Kerne og 2 Vindens Ånde til Brumn Vinterhov i Arathi-bjergene.\n\nAt gennemføre denne opgave giver dig adgang til Elementar-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Drageskæl-læderarbejde og Stamme-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="Elementar-læderarbejde er det, jeg kender, og hvis du er villig til at åbne dit sind for substansens større kræfter, vil jeg dele alt, der er at lære, med dig.\n\nVed dette, <Class>: ved at vælge denne vej accepterer du aldrig at lære drageskæl- eller stamme-læderarbejde; der er kun plads til at øve en af de tre kunster. Desuden skal jeg bruge tilstrækkeligt bevis på, at du er i harmoni med naturens elementer; derfor skal du bringe mig de reneste essenser af ild, vand, jord og vind.", p="At lave denne slags læderrustning kræver tålmodighed og dedikation. Når du først har kastet dit lod i elementernes favn, er der ingen vej tilbage. Bring mig bevis på din værdighed, så går vi i gang.", c="Du har kastet dit lod, og elementerne accepterer dig. Når jeg er færdig med min vejledning, vil du have magten til at skabe de fineste læderklæder.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5148] = {n="Stamme-læderarbejde", l="Bring en Vild Læder-vest og en Vild Læderhjelm til Sæ'Jib i Kvælletorn-dalen.\n\nAt gennemføre denne opgave giver dig adgang til Stamme-læderarbejdets kunst.\n\nAt gennemføre denne opgave forhindrer dig i at lære Drageskæl-læderarbejde og Elementar-læderarbejde; vær sikker på, at det er den vej, du ønsker at følge, før du gør det.", d="At lære stamme-læderarbejde kræver en forståelse af, hvordan den primitive natur virkelig er; jeg ved, at du allerede har mestret kunsten at lave vild læderrustning, og jeg er villig til at fuldende din oplæring.\n\nVed dette, <Class>: ved at vælge denne vej accepterer du aldrig at lære drageskæl- eller elementar-læderarbejde; der er kun plads til at øve en af de tre kunster. Desuden skal du bringe mig de fineste prøver af din vilde læderrustning. Derfra begynder vi din mestring.", p="Naturen er en kraft, der må formildes, før du kan håbe på at lære, hvordan du bøjer dens vilje ind i dine læderbeklædninger. Bring mig dit offer til denne kraft, så sørger jeg for, at det bliver hørt.", c="Du har givet dine fineste offergaver, og naturen vil snart tillade dig at bøje hende efter din vilje. Når jeg er færdig med min vejledning, bliver dit arbejde en naturkraft i sig selv.\n\nFor at træne i kunsten fremover skal du blot tale til mig, så vil jeg gøre al den viden, du endnu ikke har tilegnet dig, tilgængelig for dig."},
  [5149] = {n="Pamelas Dukke", l="Find Pamelas dukke.", d="Min tante Marlene sagde, at jeg skulle blive her i huset, fordi min far måtte af sted og kæmpe. Min far er den modigste mand i hele verden!\n\nMen jeg har været her længe, og han er ikke kommet efter mig. Nogle gange kommer dårlige mennesker og hvisker til mig, og jeg vil have, at min far skal få dem til at gå væk, men han er ikke her!\n\nOg nogle gange, når det bliver mørkt, vil jeg lege med min dukke, men det kan jeg ikke, for jeg har glemt den i byen.\n\nVil du finde min dukke til mig?", p="Fandt du min dukke?", c="Du fandt den! Du fandt min dukke! Åh, tak!"},
  [5152] = {n="Tante Marlene", l="Tal med Marlene, syd for Andorhøj-ruinerne.", d="Åh, jeg er så ensom! Hvor er min familie? Tante Marlene sagde, at jeg skulle blive her, men så gik hun, og hun kom aldrig tilbage! Og min far... har du set ham?\n\nMåske ved Tante Marlene, hvor han er. Hun bor nær Andorhøj, i et hus mod syd. Jeg tror, det lå på en bakke... hun sagde, det lå på en bakke.\n\nVær venlig, <Name>. Du er min nye ven! Vil du tale med min tante for mig?", c="Du så Pamela? Hvordan har hun det? Er hun i live?? Åh nej! Stakkels Pamela! Hun var så ung, og sådan et glad barn...\n\nHun ved ikke, hvad der skete med hendes far, gør hun? Min bror, Josef?\n\nNej... hun kunne ikke forstå, hvad der skete med Josef. Og selv hvis hun kunne, har jeg ikke hjertet til at fortælle hende det..."},
  [5153] = {n="En Mærkelig Historiker", l="Bring Josefs Vielsesring til Kromie.", d="Jeg ønsker, at Josef igen kunne være sammen med sin datter, men det kan ikke være sådan. Hans sjæl blev vredet af Svøben, og han blev til et monster. Åh, han er dømt!\n\nMen måske kan vi ændre hans skæbne.\n\nLed efter Josefs mindesten blandt gravene udenfor. Hans krop er ikke der, for den blev trampet ned og ødelagt for år siden, men under mindestenen ligger hans vielsesring. Tag den ring til Kromie... en mærkelig gnom med meget mærkelige kræfter.\n\nKromie opholder sig i den ødelagte kro i det nordvestlige hjørne af Andorhøj.", p="Der er noget tidsbestemt over dit besøg. Du er ikke fra fremtiden, vel?", c="Hvad er det her? En vielsesring? Lad mig se...\n\nAh! Denne ring var engang på hånden af en stor mand, men der er megen tragedie i den mands fortid.\n\nEr du her for at hjælpe ham? Det er alt for sent for ham nu... men måske kan vi hjælpe ham i fortiden!"},
  [5154] = {n="Annalerne fra Dårshire", l="Bring Annalerne fra Dårshire til Kromie i Andorhøj.", d="For at redde Josef Rødsti må vi først opdage hans fortid. Vi kan lære den i Annalerne fra Dårshire, en bog, der opbevares i rådhuset i Andorhøj.\n\nBring mig den bog. Så kan vi finde ud af Josefs skæbne, og med lidt held... ændre den!", p="Fandt du bogen, <Name>?", c="Godt gået, du fandt den!\n\nLæste du den? Er Josef Rødsti nævnt? Hvis han er, så kan vi måske redde ham!\n\nAh. Annalerne fra Dårshire fortæller en meget foruroligende historie. Der står, at Josef Rødsti under slaget blev fordærvet og sluttede sig til Svøbens rækker! Derefter forrådte han Dårshires forsvarere.\n\nDet er en ond skæbne. Hvis vi kan, bør vi prøve at ændre den skæbne, synes du ikke?"},
  [5155] = {n="Jaedenars Kræfter", l="Gå ind i Jaedenar og dræb 4 Jaedenar-hunde, 4 Jaedenar-vagter, 6 Jaedenar-adepter og 6 Jaedenar-kultister, før du vender tilbage til Greta Mosshov i Ondskoven.", d="Hvis jeg skal stole på dig i denne sag, må du først bevise dig selv.\n\nJeg må vide, at du er fjende af Skyggerådet--dem, der er ansvarlige for mange onde ting her og andre steder.\n\nRejs dybere ind i Ondskoven. Mod vest vil du se en sti, der fører til Jaedenar. Det er der, Rådet planlægger sammen med den Brændende Legion.\n\nGå ind i dybet af en af de fordærvede Gravhøj-huler, de holder til i, og slå deres slags ihjel. Vend tilbage til mig, når du har gjort dette. Så vil jeg vide, at du virkelig søger at hjælpe os.", p="Hvordan går kampen, <Name>? Jeg ved, at udgydelse af blod som bevis på ære kan være ækelt for nogle, men du må forstå, at det tjener to formål: du gør min opgave lettere ved at skade deres antal, og vi opnår en respekt for hinanden, som kun vil gøre os stærkere i fremtiden.\n\nJeg håber, du forstår.", c="Godt, <Name>! Med deres antal svækket kan vi presse dem yderligere.\n\nHvordan var din første smag af deres magt? Var de så stærke, som du havde regnet med? Stærkere? Eller var de måske ingen udfordring for dig overhovedet? Ville det ikke være noget?\n\nVi kan tale om detaljerne i dine bedrifter senere. Der er andre ting, vi må fokusere på nu."},
  [5156] = {n="Bekræftelse af Fordærvelsen", l="Søg og ødelæg 2 Entropiske Udyr og 2 Entropiske Rædsler, mens du udforsker Splinterarrets Dal. Efter at have tjekket, om kraterne der stadig er fyldt med korrumperet ond vand, vend tilbage til Taronn Rødfjer i Ondskoven.", d="Mod nord, langs østsiden af vejen i det, der kaldes Splinterarrets Dal, er der et område, hvor helvedesvæsner blev kaldt ned under den sidste store krig--kraterne skæmmer stadig landet, ligesom helvedesvæsnerne selv.\n\nJeg er nysgerrig efter to ting. For det første: findes der stadig entropiske elementarer, der strejfer rundt i området? Og for det andet: er kraterne stadig fyldt med det korrupte, rådne vand, der samlede sig der for år tilbage? Vil du hjælpe mig og tjekke det, <Name>? Vær dog forsigtig, helvedesvæsnerne ødelægger alt på deres vej.", p="Jeg håber, din søgning går godt, <Name>. Jeg er ikke begyndt at bevæge mig så langt nordpå, men jeg må indrømme, at tanken om at krydse et helvedesvæsens vej på et hvilket som helst tidspunkt skræmmer mig en lille smule. Væsnerne er hjernedøde, men stadig ret skræmmende.", c="Godt, at du er i live, <Name>. Dårligt, at vandet stadig eksisterer. Jeg havde håbet at finde mindst én ren vandkilde her i Ondskoven. Det ser ud til, at min søgning er mislykkedes. Processen med at hele landet kunne have været meget lettere med den.\n\nJeg må bekymre mig om at redde de skovskabninger, jeg kan, mens jeg ødelægger dem, der er blevet så fordærvede, at de udgør en fare for sig selv lige så meget som for de rejsende gennem denne engang så mægtige skov."},
  [5157] = {n="Indsamling af det Korrumperede Vand", l="Tag den tomme feltflaske til Månebrønden i midten af Jaedenar og fyld den, før du vender tilbage til Greta Mosshov i Ondskoven.", d="Dybt inde i Jaedenar ligger Skyggeborgen--hovedfæstningen for deres fordærvelse og ondskab.\n\nSkyggerådet har beskyttende besværgelser omkring deres hule i form af bækkener med ild. Hvis jeg skal finde ud af mere om vores fjende gennem spejlskuning, så må disse bækkener slukkes. Ved at gøre det burde jeg kunne spionere på Rådet og finde ud af, hvem der leder dem.\n\nHvis du kan, så tag denne feltflaske og fyld den ved Månebrønden i midten af Jaedenar. Vend tilbage til mig bagefter.", p="Når vi har vandet fra Månebrønden, renser vi det og bruger det til at slukke beskyttelsesbækkenerne i Skyggeborgen. Det burde give mig rigelig tid til at se endnu dybere ind i kamrene og finde ud af, hvem der faktisk leder denne... sekt.\n\nJeg beder til, at Jordmoderen er med os.", c="Det vil gøre det godt, <Name>.\n\nNu er alt, vi skal gøre ud over at anvende vandet på bækkenerne, at få det renset. Det burde ikke være svært--det burde kun kræve lidt rejse.\n\nForhåbentlig kan vi gøre det hurtigt."},
  [5158] = {n="Søgen efter Åndelig Hjælp", l="Tag det fordærvede Månebrøndsvand til Isleif Vandseer i Ødemarken.", d="Tag det korrupte vand til Ødemarken, <Name>. Syd for Skralleby, gemt langs bredden, er en gammel ven af mig, en shaman ved navn Isleif Vandseer. Hun er en mægtig shaman, der vil hjælpe os. Hendes forhold til vandets ånder har altid været stærkt. Vores opgave er ædel, og det burde være nok til at overbevise hende og vandets ånder om at hjælpe os med denne opgave.\n\nDu finder hende i en lille lejr lige ved vandkanten. Og, <Name>, ignorér piraterne... de er blot en irritation og ingen trussel for dig.", p="Jeg fornemmer, at du ikke bare er en almindelig rejsende, der leder efter vejen til Skralleby. Kom, sæt dig og hvil i vores lejr. Tal til mig, når du er klar.", c="Ah, du har brug for vandet fra denne Månebrønd renset. At stoppe denne ondskabsfulde kraft i Ondskoven virker ædel nok, men det er ikke op til mig at afgøre, om vandet skal renses. Jeg vil spørge vandets ånder--det bliver op til dem at afgøre, om sagen er retfærdig.\n\nGiv mig et øjeblik, så fortæller jeg dem om din anmodning. Jeg håber, de er lige så sympatiske over for din sag, som jeg er."},
  [5159] = {n="Renset Vand Vender Tilbage til Ondskoven", l="Tag det renede Månebrøndsvand til Greta Mosshov i Ondskoven.", d="Tak ånderne, <Name>. Det er dem, der er kommet dig til hjælp, ikke mig.\n\nJeg giver dig dette rensede vand nu. Hils Greta, og giv hende mine bedste ønsker. Hun kæmper med noget, der er større end mange af os... som jeg er sikker på, at hun snart vil finde ud af.\n\nSkyggerådet er ikke en kraft, man skal lege med, <Name>. Husk det.\n\nGå nu. Tag vandet og vend tilbage til Greta.", p="Ah, jeg ser, du er vendt tilbage, <Name>. Godt. Fandt du Isleif i Ødemarken? Eller må vi finde en anden vej til at nå vores mål?", c="Dette burde være mere end nok vand til vores formål.\n\nDet glæder mig at høre, at Isleif kunne hjælpe os. Hendes styrke med vandånderne har altid været stærk. Hun er også klog, og det er sjældent, at ånderne ikke er enige i hendes formål. At de begge har velsignet vores opgave, giver mig håb om, at vi er på den rette vej."},
  [5160] = {n="Matronebeskyttelsen", l="Rejs til Vintersæt og find Hale. Giv hende Awbis skæl.", d="Rejs til Kalimdør, <Race>. Vores flugt har hjemsted i Vintersæts frostbidte landskab. Når du når Vintersæt, skal du finde Mazthorøls grotter.\n\nPå Mazthorøls iskolde gulve finder du kobolt-runer. Hold et af mine skæl og stå på en rune, så bliver du transporteret til Hale, vores matronebeskytter.\n\nGiv hende skællet, så hun kan spejle det, jeg har set og følt her på dette dødsdømte sted.", p="Det er godt at se dig, <Name>.", c="Aspekterne insisterer på, at vi holder os ude af dødelige anliggender. I denne verden er det dog ikke altid muligt, især ikke når en af vores egne foragtende ignorerer sådanne påbud."},
  [5161] = {n="Den Blå Flyvnings Vrede", l="Tal med Hale, hvis du ønsker at fortsætte.", d="Vi forstår, hvad Dødsvingens forbandede yngel forsøger at gøre, og vi ved, at det ikke må tillades.\n\nPå grund af den beskyttelse, Sortklippe-bjerget giver Nefarian, er det blevet stadig sværere for os at gribe ind.\n\nVi kan dog give dig kræfter, dødelige - hvis du vælger det.\n\nDen vej, der ligger foran dig, er fuld af fare. Du må beslutte, om du vil acceptere vores hjælp. Overvej dette, og tal med mig igen, når en beslutning er truffet.", c="Så skal det være..."},
  [5162] = {n="Den Blå Flyvnings Vrede", l="Tal med Jezibba i Pestlandene. Han holder til i Andorhøj.", d="Det er den arkane kraft jeg kontrollerer, og det er den arkane kraft der sender dig til din næste destination.\n\nNår du er klar, begynder rejsen. Til Pestlandene skal du gå, og til Jezibba skal du tale.\n\nHan er et dødeligt væsen lige så klog som de gamle og lige så tålmodig som den ubevægelige jord. Find ham i Andorhøj.", c="Jeg er Jezibba, kendt af mange som Billedhuggeren. Det jeg former er dog ikke statuer, men helte."},
  [5163] = {n="Er Vi Der Snart, Snemand?", l="Tag Ummas Mekaniske Snemand og skræm hendes venner med den:\n\nLegakki i Evigblik (Vinterkilde)\nStænk i Gadgetbyen (Tanarisørknen)\nKvixxil i Marskalkens Fristed (Un'Goro-krateret)\n\nNår du er færdig, tag den mekaniske snemand tilbage til Umma.", d="Alt er klar, <Name>!\n\nNu har jeg allerede sendt post til mine venner og fortalt dem, at jeg har en overraskelse til dem. Det er her du kommer ind i billedet!\n\nJeg vil give dig min mekaniske snemand, og du skal overraske dem ved at besøge hver af mine venner, tænde snemanden og sende den mod dem.\n\nNår du har vist Legakki i Evigblik, Stænk i Gadgetbyen og Kvixxil i Marskalkens Fristed, så kom tilbage og fortæl mig hvad der skete!\n\nBring også min snemand tilbage til mig.", p="Jeg kan ikke vente med at høre hvordan mine venner reagerer!\n\nDe vil aldrig se det komme!", c="Haha! De vil tænke sig om to gange, før de driller mine idéer igen!\n\nTak for hjælpen, <Name>. Jeg kunne aldrig have haft så meget sjov uden dig!"},
  [5164] = {n="Katalog over de Vildfarne", l="Læs fra Katalog over de Vildfarne.", d="Et finere redskab for retfærdighed kunne Hale ikke have valgt. Læs fra katalogen over de vildfarne og bliv oplyst.\n\nSkulle du blive ved... skulle du gøre hvad der bliver bedt om... skulle du overleve... så vil en helt du blive.", c="Hundredvis af sider fyldt med forvrænget tekst og symboler udgør hovedparten af denne bog."},
  [5165] = {n="Slukningen af Beskyttelsens Flammer", l="Slukk flammerne i de fire beskyttelseskulbækken i Skyggeborgen i Ondskoven med Renset Månebrøndsvand, og vend derefter tilbage til Greta Mosshov i Smaragd Fristed.", d="Nu må du vende tilbage til Jaedenar. Kulbækkene er sandsynligvis spredt ud over hele Skyggeborgen. Slukk hver af deres flammer, så falder rådets beskyttelser i det mindste for en kort stund. Jeg vil vente på at det sker. Når det gør, vil jeg kigge dybt ind i borgen og forsøge at finde ud af hvem der står i spidsen for dette udyr. Først da, og kun da, vil vi overveje at angribe dem direkte.", p="Kulbækkene skal slukkes, hvis vi skal have det mindste håb om at være forberedt på et langt større slag. At gå ind i dragens hule uden nogen viden er et nars ærinde. Og dette er langt værre end en drage. Skyggerådet er alene ansvarlig for et stort antal forbrydelser og grusomheder. Vi må handle hurtigt, hvis vi skal stoppe dem.", c="Jeg kunne se dig med mine besværgelser, så snart den sidste kulbækkes flammer døde. Godt gjort, <Name>.\n\nJeg lærte et par ting, før Skyggerådets hekseknægte kunne genbesværge deres besværgelser. Forhåbentlig er det nok.\n\nNu må du hvile. Jeg vil fortælle dig hvad jeg har lært om et øjeblik."},
  [5166] = {n="Brystpladen fra Den Kromatiske Flyvning", l="For at smede Brystpladen fra Den Kromatiske Flyvning skal du bringe følgende genstande til Jezibba 'Billedhuggeren':\n\n1 Det Kromatiske Skal.\n\n10 Strålende Kromatiske Skæl.\n\n10 Heltenes Blod.\n\n10 Frynsede Afskyelighedssting.", d="Smedningen af en kraftig brystplade til at beskytte mod den ubarmhjertige kromatiske flyvnings angreb er bygget på ironi.\n\nSkællene fra selve de udyr vi kæmper mod skal sys på det rene skal fra en ældre kromatisk drage eller drage. Ingen kendes på nuværende tidspunkt, og vi må håbe at ingen nogensinde vil eksistere.\n\nTil sidst, måske den vanskeligste af alle komponenter: heltenes blod.\n\nBilledhuggeren må i sidste ende smede denne skabelse.", p="Du har valgt klogt, <Race>.", c="Forstår du det ikke endnu? Rejsen var målet. Kan du ikke mærke kampens ar? Smerten du gennemgik?\n\nNu hvor du har overlevet prøvelsen, er du et mere magtfuldt væsen. Meget mere magtfuldt. Denne brystplade er blot en afspejling af dine egne medfødte evner."},
  [5167] = {n="Benpladerne fra Den Kromatiske Trodser", l="For at smede Benpladerne fra Den Kromatiske Trodser skal du bringe følgende genstande til Jezibba 'Billedhuggeren':\n\n1 Det Kromatiske Skal.\n\n10 Strålende Kromatiske Skæl.\n\n10 Heltenes Blod.\n\n5 Skyggeskind.", d="Skallen fra en moden kromatisk drage er nødvendig for at danne fundamentet for benklæderne. Strålende kromatiske skæl lægges derefter på rammeværket af tråd og fortryllet i heltenes blod. Til sidst skal det smidige skyggeskind påføres de indvendige benskinner.", p="Sådan en genstand er aldrig blevet smedet!", c="De vil lugte deres slægtninge, når du træder ind i deres haller, <Name>. Knus dem med deres egen frygt!"},
  [5168] = {n="Helte fra Dårshire", l="Bring Davils Libram og Rødstis Skjold til Karlin Rødsti.", d="Helte fra Dårshire har en plads i mit hjerte, og bogen du bragte mig, Dårshires Annaler, fortæller deres historier.\n\nDen fortæller om paladinen Davil Lysild, og hvordan Korstoget tog hans Libram til rådhuset i Hjertedal.\n\nDens passager taler også om min bror, Kaptajn Rødsti. Efter hans forræderi blev hans skjold knækket og kasseret, og nu ligger det på de mest usandsynlige steder -- nær laden i Gorrons Visnende.\n\nSaml disse relikvier, <Name>. For skæbne og tragedie omgiver dem.", p="Har du relikvierne, <Name>?", c="Du har Libram'en og skjoldet!\n\nDeres historie er sammenvævet med Dårshires historie, og på en eller anden måde ved jeg, at skæbnen vil bringe dem sammen igen."},
  [5181] = {n="Skurkene fra Dårshire", l="Bring Hørgus' Kranie og Mardoks Knuste Sværd til Karlin Rødsti ved Lysets Håb-kapellet.", d="Dårshires Annaler fortæller om skurkene fra det slag. Den fortæller hvordan gravgyser-herren Hørgus Hærgeren blev tilintetgjort af Alliancens styrker under slaget. Hans legeme blev kastet i en sø nordvest for Corins Kryds, og hans kranie ligger der stadig.\n\nMardok den Sorte blev aldrig besejret, men hans legendariske sværd blev knust og tabt. Det ligger på bunden af klippekløften vest for Corins Kryds.\n\nHent disse genstande, <Name>. Jeg ved ikke hvorfor, men jeg er sikker på at deres skæbne ligger hos dig.", p="Fandt du kraniet og sværdet, <Name>?", c="Du fandt dem! Godt gjort, <Name>! Disse relikvier har en kraft jeg ikke helt forstår, en kraft du en dag vil udnytte.\n\nDe bringer også mørke minder frem i mit sind, minder om død og forræderi, og om Dårshires sidste nat..."},
  [5202] = {n="En Mærkelig Rød Nøgle", l="Søg gennem Jaedenar for at finde ud af hvad den Blodrøde Nøgle bruges til.", d="Den lille røde nøgle ser ud til at være lavet af en slags knoglemateriale. Den er tung i din hånd, men virker meget skrøbelig. Hvorfor skulle et medlem af Skyggerådet have sådan en ting? Måske er der noget i Jaedenar, som denne mærkelige nøgle låser op.", p="Jeg begynder at undre mig over, om jeg nogensinde slipper ud af dette bur.\n\nDet er kun et spørgsmål om tid, før de ofrer mig til hvilke dæmoner de end tilbeder. Monstrene!", c="Nøglen, du har fundet den! Vær venlig at give den til mig, så kan jeg endelig slippe væk!"},
  [5203] = {n="Redning fra Jaedenar", l="Eskorter Arko'narinsen til stedet hvor Lysssmede og hendes udstyr holdes, og beskyt hende derefter, mens I flygter fra Skyggeborgen. Find bagefter Jessir Månebue i Ondskoven og fortæl hende, hvad der er sket med hendes venner.", d="Men så meget det end smerter mig, er der én ting der skal gøres først: Jeg skal finde Trejs sværd Lysssmede og flygte fra Skyggeborgen for at fortælle mine overordnede, hvad der foregår her. Kan du hjælpe mig, <Name>?\n\nVores udstyr er ikke langt herfra, og du har allerede bevist, at du kan overleve vejen til toppen.\n\nEfter vi er flygtet, tager jeg til Darnassos, hvis du kan finde min ven Jessir nær grænsen til Askedalen. Hun skulle have mødt os ved Smaragdkredsens lejr dér i nærheden.\n\nHvad siger du, <Name>? Kan du hjælpe mig igen?", p="Du ser forpustet ud, <Name>. Har du det godt, eller er der noget galt?", c="Var det dig, der hjalp Arko med at flygte? Jeg er så glad for, at du fandt mig. Hun gik forbi her for ikke længe siden på vej til Darnassos. Hun havde Lysssmede med sig og ville ikke engang tage sig tid til at tale med druiderne om at blive helbredt. Hun sagde, at det var alt for hastende.\n\nMen hun fortalte mig om dit møde med Trejs ånd. Sikke en skæbne for en Ridder af Sølvhånden. Hun viste det ikke, men jeg ved, at det river hende i stykker indeni, tanken om at miste en af sine nærmeste venner."},
  [5204] = {n="Lysets Retribution", l="Vend tilbage til Jaedenar og dræb sukkubussen Rakaia, før du finder Trej Lysssmedes Levninger.", d="Hun vil gerne lade som om, at hun har det fint. Hun ville elske, at jeg troede hun var stærk nok til at klare alt dette på egen hånd, men jeg ved bedre end det. Trejs død og at høre om den tortur han blev udsat for, vil hjemsøge hende i lang tid, og der er intet vi kan gøre for at stoppe det. Men vi kan give hende lidt fred!\n\n<Name>, vend tilbage til Skyggeborgen, dræb Trejs torturist og find hans levninger. Der er ingen grund til, at vi ikke kan binde alle disse løse ender, mens Arko'narin sørger på sin egen private måde.", p="Du undersøger liget, og der er ingen tvivl om, at det er levningerne af Ridderen af Sølvhånden, Trej Lysssmede. Et øjeblik tænker du på Arko'narin og spørger dig selv, om nogen i dit liv betød lige så meget for dig, som denne mand betød for nattelven-fangen du for nylig hjalp med at flygte fra Skyggeborgen.\n\nEfter at have taget et øjeblik mere til at samle dine tanker, ved du, at du ikke kan tage paladinens levninger tilbage til Jessir uden først at dræbe hans torturist.", c="Du samler paladinens levninger så forsigtigt som muligt og husker, at i det mindste er hans ånd løst fra enhver smerte eller lidelse, der måtte være blevet påført ham."},
  [5206] = {n="Plyndrere fra Dårshire", l="Bring 5 Resonerende Kranier og den Mystiske Krystal til Karlin Rødsti i Østlige Pestlande.", d="Kromie sagde, at de relikvier du har samlet, er reagenser til en kraftfuld besværgelse, og der kræves endnu en: kranier fra Geisslen der deltog i slaget ved Dårshire.\n\nTag denne krystal og jag Geisslens mestre efter deres kranier. Krystallen er fortryllet; hvis en mester deltog i slaget, vil den resonere, når du fører krystallen hen over dens kranie. Bring mig de resonerende kranier.\n\nAf sted, <Name>. Du finder Geisslens mestre i Giftig Lysning mod nord og i Svampedalen mod vest.", p="Har du kraniene? Kromie sagde, at de bliver afgørende for hendes besværgelse, og den besværgelse vil give os chancen for at redde Dårshire.", c="Du fandt dem! Vidunderligt!\n\nSkønt jeg ikke helt forstår, hvordan de kan hjælpe os, mærker jeg deres kraft, og jeg ved i mit inderste, at de er forbundet med min hjemby Dårshire."},
  [5210] = {n="Bror Carlin", l="Bring Dårshires Udvidede Annaler til Karlin Rødsti i Østlige Pestlande.", d="Dårshires Annaler har gennem min magi fået sider til sidst, og nu udvider den sin historie ud over slaget. Et af de ekstra afsnit fortæller om en anden Rødsti, Carlin, som overlevede Josefs forræderi. Carlin er nu i Pestlandene mod øst, ved Lysets Håb-kapellet.\n\nTag bogen og tal med ham.", p="Du er kommet fra vest? Hvordan står det til med resten af Herrelande? Jeg ved, at Andorhøj er tabt, men er Geisslen nået til det smukke Tirisdal endnu?", c="Hvad er denne bog? Dårshires Annaler? Det var mit hjem før krigen... mit hjem før slaget, der ødelagde det! Hvorfor bragte du mig denne bog?\n\nMen se her! Til sidst er der sider, der fortæller historier om dagene efter slaget! Her er et afsnit om mig! Og et om min bror Josef! Er denne bog sand?\n\nVi må finde ud af sandheden!"},
  [5211] = {n="Forsvarerne fra Dårshire", l="Befri 15 Dårshire-ånder og vend tilbage til Karlin Rødsti.", d="Mange af forsvarerne faldt i slaget ved Dårshire. Og mange vandrer igen som de grufulde tjenere for Geisslen! Find disse stakkels sjæle og gør ende på deres elendighed!\n\nJag kannibal-gravgysere, pludrende gravgysere og sygdomsramte flåere. Mange af disse ondskaber var engang de gode folk fra Dårshire, og at ødelægge deres skikkelser nu vil befri deres sjæle.\n\nDu finder dem i Pestskoven og Corins Kryds og i andre Geisslen-højborge i Østlige Pestlande.", p="De stakkels forsvarere af Dårshire råber til mig i mine drømme, <Name>. Du må befri dem!", c="Det er godt at høre, at du fandt mine brødres pinte sjæle og befriede dem. Mit hjerte vil græde mindre, når jeg ved, at i det mindste nogle af Dårshires forsvarere ikke længere sukker under Geisslens vederstyggelige underkastelse."},
  [5212] = {n="Kødet Lyver Ikke", l="Indsaml 20 Pestsmittede Kødprøver fra Strathholme og bring dem til Betina Stortrold. Du mistænker, at ethvert væsen i Strathholme ville have givet denne kødprøve.", d="De Forladtes apotekere er ikke de eneste væsener i denne verden, der er skolet i videnskab.\n\nJeg har studeret pesten i årevis, <Race>. Vi troede tidligere, at pestens styrke aftog, men det jeg har opdaget her i Pestlandene, er forbløffende. Pesten ser ud til at vokse i styrke!\n\nJeg må lave flere tests! Pestens mest potente kilde er det smittede kød fra de nyligt inficerede. Rejs til Strathholme og bring mig prøver, <Name>.", p="Nogle siger, at jeg bekymrer mig for meget - til dem siger jeg: 'I bekymrer jer ikke nok!'", c="Der er noget, der har ændret sig i pestens aktive stoffers kemiske struktur. Der kræves flere data."},
  [5213] = {n="Det Aktive Middel", l="Rejs til Strathholme og undersøg zigguraterne. Find og bring nye Geisslen-data tilbage til Betina Stortrold.", d="Du må dykke dybere ned i Strathholme, <Name>.\n\nBag de første porte finder du zigguraterne. Vi ved, at Geisslen henter stor kraft fra disse strukturer. Undersøg zigguraterne og vend tilbage med alle de oplysninger du måtte opdage.", p="Vi er på nippet til at opdage, hvad dette nye aktive pestmiddel kan være!", c="Forbløffende! Det vil tage måneder at dissekere og analysere. Sølvdæmringen takker dig for din indsats, <Name>.\n\nMed vores velsignelse må du vælge mellem enten dette Dagningens Segl eller denne Dagningens Rune. Du kan bruge en af dem i stedet for et almindeligt Sølvdæmringens Hverv til at indsamle gyselsten på vores vegne. Hvis du mister din, så tal med mig, så skaffer jeg dig en erstatning."},
  [5214] = {n="Den Store Fras Røgsen", l="Find Fras Røgsens røgbutik i Strathholme og hent en kasse Røgsens Premium Tobak. Vend tilbage til Smøg LaRue, når jobbet er gjort.", d="Forfærdeligt... det der skete med Fras. Ser du, byen blev plyndret, og Fras ville ikke efterlade sine dyrebare varer. Det sidste jeg husker, at han sagde, var: 'Jeg brænder hvert eneste blad, før de får deres forbandede, beskidte hænder på dem!'\n\nJeg kan godt lide en god cigar, men jeg er ingen tosse. Jeg forlod Fras og hans dejlige butik den dag. Jeg går ud fra, at han gik op i flammer, men hvis der er en chance for, at blot én kasse af hans berømte tobak stadig er intakt...\n\nHvad siger du, <Name>? Finder du en kasse til gamle Smøg?", p="Jeg kan ikke klare det, <Name>! Du må hjælpe mig! Jeg dør!", c="Åh søde, søde cigar, hvor har jeg savnet dig..."},
  [5215] = {n="Geisslen-gryderne", l="Tal med Højpræstinde MacDonnel ved Kuldevind-pegen i Vestlige Pestlande.", d="Inden for de tidligere Herrelande findes otte gryder - fire her i vest og fire mere gemt i øst. Disse gryder udspyr gifte ud i luften og udbreder pesten over hele landet for Geisslen.\n\nDen nekromantiske magt fra Kel'Tuzad er for stærk til at lukke disse gryder ned direkte, men vi tror, at vi måske har en måde at underminere dem til vores fordel. Min næstkommanderende, Højpræstinde MacDonnel, vil være din kontakt i denne opgave; hun vil fortsætte briefingen herfra.", c="Må Lysets kraft skinne over dig i disse mørke tider, <Class>. Jeg er glad for at tjene som din koordinator for vores plan om at sabotere Geisslens gryder.\n\nVores mål er at ændre sammensætningen af den pest, gryderne skaber, til noget der har en negativ virkning på Geisslen. For at gennemføre denne ændring skal du sikre adgang til hver af de fire gryder i Vestlige Pestlande.\n\nVær klar, helt, for et herligt slag mod den nederdrægtige Geisslen venter dig!"},
  [5216] = {n="Mål: Felsten-marken", l="Gå til Felsten-marken i Vestlige Pestlande for at finde og besejre Gryde-herren der. Han har måske en nøgle, der giver adgang til gryden. Du skal have den Tomme Felsten-marks-flaske med dig for at sikre en prøve af giftstofferne brugt i gryden.", d="Af de fire gryder her i vest er den på Felsten-marken måske den letteste at få adgang til. Geisslen har grønnere tropper stationeret her, men de bør ikke undervurderes.\n\nGå til Felsten-marken, nordvest for Andorhøj, og engager gryde-herren der. Vi tror, at den har en nøgle, der låser op for adgang til gryden. Når den er låst op, brug denne flaske til at få en prøve af giftstofferne inde i gryden; vi får brug for den til studier i udviklingen af et modgift.", p="En adgangsluge til gryden sidder stadig fast. For at åbne den skal du finde nøglen.", c="Nøglen taget fra Gryde-herren Galdegab passer perfekt i låsen til adgangslugen. En ildelugtende stank strømmer ud fra den åbnede luge, mens en ukendt blanding af koncentrerede stoffer hvirvler rundt inde i gryden.\n\nDer er en lille hane, som flasken passer tilpas under, så du kan tappe en prøve til Højpræstinde MacDonnel tilbage ved Kuldevind-pegen."},
  [5217] = {n="Tilbage til Kuldevind-lejren", l="Bring den Fyldte Felsten-marks-flaske til Højpræstinde MacDonnel i Kuldevind-lejren, Vestlige Pestlande.", d="Du fylder flasken med nok af gryderens giftige blanding til en passende prøve, der kan studeres.\n\nMed giften i hånden er det tid til at vende tilbage til Højpræstinde MacDonnel i Kuldevind-lejren for at fuldføre missionen.", p="Velkommen tilbage til den relative sikkerhed i Kuldevind-lejren, <Name>. Hvilke fremskridt med gryderne har du at rapportere?", c="Godt gjort, <Name> - Alkymist Arbinton skal ikke bruge lang tid på at analysere dette og udtænke et modgift, der kan indføres i gryden. Hvis vi kan pumpe nok af det ud i luften, kan vi måske svække alle Geisslen, der er til stede her.\n\nDette bliver uden tvivl en vedvarende prøvelse; vi bliver nødt til konstant at ramme disse gryder og indføre vores reagenser i deres blanding. Men hvis vi kan holde det ved, har vi en stor fordel over Geisslen, når tiden kommer til slaget!"},
  [5219] = {n="Mål: Dalsens Tårer", l="Gå til Dalsens Tårer i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den Tomme Dalsens Tårer-flaske med dig for at sikre en prøve af giftstofferne brugt i gryden.", d="En af pestgryderne ligger på marken af en tidligere landejendom, der nu kaldes Dalsens Tårer. Nå, vi skal ikke fælde nogen tårer i dag, mens vi forpurrer Geisslen og lader dem kvæles i deres egen røg!\n\nGå til Dalsens Tårer, næsten lige nord for Andorhøj, og eliminer gryde-herren der. Den bør have en nøgle ligesom den sidste gjorde, så du kan komme ind i gryden. Brug denne flaske til at få en prøve fra indersiden af gryden; hver gryde har sin egen særlige brygning af giftstoffer.", p="En adgangsluge til gryden sidder stadig fast. For at åbne den skal du finde nøglen.", c="Den makabre nøgle fundet på gryde-herren glider let ind i et nøglehul og forsvinder derefter, så du får permanent adgang til den. Grove, tykke ichorer pulserer gennem snoede rør inde i gryderens underbygning.\n\nDer er en lille hane, som flasken passer tilpas under, så du kan tappe en prøve til Højpræstinde MacDonnel tilbage ved Kuldevind-pegen."},
  [5220] = {n="Tilbage til Kuldevind-lejren", l="Bring den Fyldte Dalsens Tårer-flaske til Højpræstinde MacDonnel i Kuldevind-lejren, Vestlige Pestlande.", d="Du fylder omhyggeligt flasken med nok af gryderens ichorer til, hvad du anser for en passende stor prøve.\n\nMed giften i hånden er det tid til at vende tilbage til Højpræstinde MacDonnel i Kuldevind-lejren for at fuldføre missionen.", p="Vi ved, at hver gryde bruger en forskellig blanding af reagenser til at frembringe sit pestinducerende toksin; ligeledes ved vi, at vi bliver nødt til at udvikle et modgift, der er unikt for hver gryde. Din prøve fra Dalsens Tårer bliver nøglen til at finde ud af den gryderes særlige reagenskrav.", c="Ah, der er masser her til studier. Godt gjort, <Name>!\n\nNu er det næste trin i vores hænder. Vi skal udarbejde en liste over reagenser, som, når de blandes med det der allerede er i gryden, vil virke som dens modgift.\n\nDen eneste måde vi kan indføre dette på, er ved at placere reagenserne direkte i gryden. Alkymist Arbinton har mere information om det, så sørg for at tale med ham ved første lejlighed."},
  [5222] = {n="Mål: Det Vridende Hjemsøgelse", l="Gå til Det Vridende Hjemsøgelse i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den Tomme Vridende Hjemsøgelse-flaske med dig for at sikre en prøve af giftstofferne brugt i gryden.", d="To gryder er blevet åbnet med succes; selvom du vil kunne få adgang til dem på ubestemt tid, vil vi stadig gerne åbne de to resterende. Det vil give os alle flere muligheder for at indføre modgiften!\n\nDenne gang rammer du Det Vridende Hjemsøgelses gryde. Den ligger næsten lige øst for Andorhøj, relativt tæt på de ødelagte bymure; eliminer igen gryde-herren der for dens nøgle. Brug denne flaske til at få prøven fra gryden.\n\nGod jagt, <Name>!", p="En adgangsluge til gryden sidder stadig fast. For at åbne den skal du finde nøglen.", c="Gryde-herrens nøgle låser adgangslugen til denne gryde op og forsvinder derefter, ligesom de andre nøgler gjorde for de to gryder du har klaret før. Et rådnende lugtende stof bruser voldsomt under gryderens platform.\n\nDer er en lille hane, som flasken passer tilpas under, så du kan tappe en prøve til Højpræstinde MacDonnel tilbage ved Kuldevind-pegen."},
  [5223] = {n="Tilbage til Kuldevind-lejren", l="Bring den Fyldte Vridende Hjemsøgelse-flaske til Højpræstinde MacDonnel i Kuldevind-lejren, Vestlige Pestlande.", d="Du fylder den tomme flaske forsigtigt; en prøve af det hæslige stof, der bruser under gryderens platform, flyder nu frem og tilbage inde i den skrøbelige glasbeholder.\n\nMed giften i hånden er det tid til at vende tilbage til Højpræstinde MacDonnel i Kuldevind-lejren for at fuldføre missionen.", p="Når vi har analyseret prøven fra Det Vridende Hjemsøgelses gryde, vil den give os en tredje vej til at levere et ødelæggende modgift mod Geisslen!", c="Endnu en fint udført mission, <Name>! Det gør tre gryder tilgængelige for os at vende mod Geisslen. Hvis Kel'Tuzads nekromantiske dominans over disse lande ikke var så stærk, som den er nu, ville jeg vove at påstå, at du ville lukke dem helt ned!\n\nAlkymist Arbinton vil have en rapport om, hvad denne gryde - samt de andre underminerede gryder - vil kræve for at levere vores modgift til pesten. Med det er tiden kommet til at bringe den sidste gryde i vest under vores indflydelse!"},
  [5225] = {n="Mål: Gorrons Visnende", l="Gå til Gorrons Visnende i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den Tomme Gorrons Visnende-flaske med dig for at sikre en prøve af giftstofferne brugt i gryden.", d="Den sidste gryde, der er tilbage, ligger på en gård, der nu kaldes Gorrons Visnende. Den bevogtes af Geisslens hårdeste håndlangere - nemlig genfærd og spøgelser. De skal ikke tages let på, <Name>.\n\nGorrons Visnende ligger nordøst for vores position her, tæt på hvor de Østlige Pestlande begynder; eliminer igen gryde-herren der for dens nøgle. Her er din tomme prøveflaske; bring den til mig fyldt. Må Lyset beskytte dig i denne farlige mission, <Class>.", p="En adgangsluge til gryden sidder stadig fast. For at åbne den skal du finde nøglen.", c="Gryde-herre Sjælevredes nøgle opløses, når den rører låsen på adgangslugen ved bunden af gryderens platform. En svag klirrende lyd høres indefra, og adgangslugen svinger op og afslører mere tyktflydende gifte inde i gryderens konstruktion.\n\nDer er en lille hane, som flasken passer tilpas under, så du kan tappe en prøve til Højpræstinde MacDonnel tilbage ved Kuldevind-pegen."},
  [5226] = {n="Vend tilbage til Kuldevind Lejr", l="Bring den fyldte Gorrons Visnende Flaske til Overpræstinde MakDonnel i Kuldevind Lejr, Vestlige Pestlande.", d="Du lukker omhyggeligt hanen på kontrolpanelet og ser grydens råddenskabelige ichorer dryppe ned i den tomme flaske.\n\nMed giften i hånden er det tid til at vende tilbage til Overpræstinde MakDonnel i Kuldevind Lejr for at fuldføre missionen.", p="Gorrons Visnende huser den sidste gryde her i vest, som vi skal have adgang til. Når vi har en prøve af pesten, den spyr ud, kan vi introducere vores reagenser i miljøet gennem fire separate kar! Svøben vil få svært ved at holde os ude af alle fire, selv med Kel'Tuzads magt bag sig.", c="Tillykke <Name>, du har låst den sidste gryde op for os! Alkymist Arbinton vil snart vide, hvad denne gryde kræver af reagenser til blandingen.\n\nHvad dig angår, er jeg sikker på, at Kommandør Modnæve vil gerne takke dig personligt for den hjælp, du har givet os. Uden dig ville vores kamp mod Svøben have været næsten uovervindelig. Tak, helt!"},
  [5228] = {n="Svøbens Gryder", l="Tal med Skyggepræstinde Vanddis ved Bolværket, Vestlige Pestlande.", d="Inden for de tidligere Herrelande findes otte gryder - fire i vest og fire mere forankret i øst. Disse gryder spyr gifte op i luften og udbreder pesten over hele landet for Svøben.\n\nKel'Tuzads nekromantiske magt er for stærk til at lukke disse gryder helt ned, men vi tror, vi har en måde at underminere dem til vores fordel. Min næstkommanderende, Skyggepræstinde Vanddis, vil være dit kontaktpunkt i denne opgave; hun vil fortsætte briefingen herfra.", c="Fra skyggerne, bror <Race>, hilser jeg dig. Jeg skal tjene som din koordinator i vores plan om at sabotere Svøbens gryder.\n\nVores mål er at ændre sammensætningen af den pest, gryderne skaber, til noget, der skader Svøben. For at gennemføre denne ændring skal du sikre dig adgang til hver af de fire gryder her i Vestlige Pestlande.\n\nTiden er kommet til, at du leder angrebet mod Svøben, helt."},
  [5229] = {n="Mål: Felsten-marken", l="Gå til Felsten-marken i Vestlige Pestlande for at finde og besejre Gryde-herren der. Den kan have en nøgle, der giver adgang til gryden. Du skal have den tomme Felsten-marken-flaske med dig for at sikre en prøve af giftene i gryden.", d="Af de fire gryder i Vestlige Pestlande er den ved Felsten-marken måske den nemmeste at få adgang til. Svøben har grønnere tropper placeret her, men de bør ikke undervurderes.\n\nTag til Felsten-marken, lige østpå herfra og nordvestpå fra Andorhøj, og gå i kamp med gryde-herren der. Han har en nøgle, der låser adgang til gryden op. Når den er låst op, brug denne flaske til at få en prøve af grydens giftstoffer; vi skal bruge den til at studere og udvikle et modgift.", p="Et adgangspanel til gryden sidder stadig fast skruet. For at åbne det skal du finde nøglen.", c="Nøglen taget fra Gryde-herren Galdekæft passer perfekt til at låse adgangspanelet op, selvom den forsvinder, efter du har brugt den. Alligevel tror du, du kan åbne panelet nu uden nøgle. En modbydelig stank strømmer ud fra det åbnede panel, mens en ukendt blanding af koncentrerede stoffer hvirvler rundt i gryden.\n\nDer er en lille hane, som flasken passer nogenlunde under, så du kan tappe en prøve til Skyggepræstinde Vanddis tilbage ved Bolværket."},
  [5230] = {n="Vend tilbage til Bolværket", l="Bring den fyldte Felsten-marken-flaske til Skyggepræstinde Vanddis ved Bolværket, Vestlige Pestlande.", d="Du fylder flasken med nok af grydens giftige brygning til en passende prøve, der kan studeres.\n\nMed giften i hånden er det tid til at vende tilbage til Skyggepræstinde Vanddis ved Bolværket for at fuldføre missionen.", p="Velkommen tilbage til Bolværkets relative sikkerhed, <Name>. Hvad fremskridt har du at rapportere om gryderne?", c="Godt gået <Name> - Apoteker Tøvers burde ikke tage lang tid om at analysere dette og udtænke et modgift, der kan indføres i gryden. Hvis vi kan pumpe nok af det ud i luften, kan vi måske svække hele Svøben, der er til stede her.\n\nDette bliver uden tvivl en vedvarende prøvelse; vi bliver nødt til konstant at ramme disse gryder og indføre vores reagenser i deres blanding. Men hvis vi kan holde det ved, får vi en enorm fordel over Svøben, når slaget kommer!"},
  [5231] = {n="Mål: Dalsens Tårer", l="Gå til Dalsens Tårer i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den tomme Dalsens Tårer-flaske med dig for at sikre en prøve af giftene i gryden.", d="En af pestgryderne ligger på marken ved et tidligere landhus, der nu kaldes Dalsens Tårer. Der bliver ikke fældet tårer i dag, <Class>; vi må angribe denne gryde og få adgang til den!\n\nTag til Dalsens Tårer, næsten direkte nord for Andorhøj, og udslet gryde-herren der. Han bør have en nøgle, ligesom den sidste gjorde, så du kan komme ind i grydens indre. Brug denne flaske til at få en prøve fra indersiden af gryden; hver gryde har sin egen unikke brygning af giftstoffer.", p="Et adgangspanel til gryden sidder stadig fast skruet. For at åbne det skal du finde nøglen.", c="Den skeletagtige nøgle fundet på gryde-herren glider let ind i et nøglehul og forsvinder derefter, hvilket giver dig permanent adgang til den. Grove, tyktflydende ichorer pulserer gennem snoede rør i grydens underbygning.\n\nDer er en lille hane, som flasken passer nogenlunde under, så du kan tappe en prøve til Skyggepræstinde Vanddis tilbage ved Bolværket."},
  [5232] = {n="Vend tilbage til Bolværket", l="Bring den fyldte Dalsens Tårer-flaske til Skyggepræstinde Vanddis ved Bolværket, Vestlige Pestlande.", d="Du fylder omhyggeligt flasken med nok af grydens ichorer til det, du anser for en passende stor prøve.\n\nMed giften i hånden er det tid til at vende tilbage til Skyggepræstinde Vanddis ved Bolværket for at fuldføre missionen.", p="Vi ved, at hver gryde bruger en anden blanding af reagenser til at generere sit pestfremkaldende gift; ligeledes ved vi, at vi bliver nødt til at udvikle et modgift, der er unikt for hver gryde. Din prøve fra Dalsens Tårer bliver nøglen til at finde ud af den grydes særlige reagenskrav.", c="Ah, der er rigeligt her til studier. Godt gået, <Name>!\n\nNu ligger næste skridt i vores hænder. Vi skal producere en liste over reagenser, som, når de kombineres med det, der allerede er i gryden, vil virke som dens modgift.\n\nDen eneste måde, vi kan indføre dette på, er ved at placere reagenserne direkte i gryden. Apoteker Tøvers vil have mere information om det, så sørg for at tale med ham så hurtigt som muligt."},
  [5233] = {n="Mål: Vridende Hjemsøgelse", l="Gå til Vridende Hjemsøgelse i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den tomme Vridende Hjemsøgelse-flaske med dig for at sikre en prøve af giftene i gryden.", d="To gryder er blevet åbnet med succes; selvom du vil kunne få adgang til dem uendeligt, vil vi stadig gerne åbne de to andre, der er tilbage. Det vil give os alle flere muligheder for at indføre modgiftet!\n\nDenne gang skal du ramme Vridende Hjemsøgelses gryde. Den ligger næsten direkte øst for Andorhøj, relativt tæt på de ruinerede bymure; eliminer igen gryde-herren der for dens nøgle. Brug denne flaske til at få prøven fra gryden.\n\nGod jagt, <Name>!", p="Et adgangspanel til gryden sidder stadig fast skruet. For at åbne det skal du finde nøglen.", c="Gryde-herrens nøgle låser adgangspanelet til denne gryde op og forsvinder derefter, ligesom de andre nøgler har gjort ved de tidligere, du har håndteret. En råddenskabsfuld lugtende substans svirrer voldsomt under grydens platform.\n\nDer er en lille hane, som flasken passer nogenlunde under, så du kan tappe en prøve til Skyggepræstinde Vanddis tilbage ved Bolværket."},
  [5234] = {n="Vend tilbage til Bolværket", l="Bring den fyldte Vridende Hjemsøgelse-flaske til Skyggepræstinde Vanddis ved Bolværket, Vestlige Pestlande.", d="Du fylder omhyggeligt den tomme flaske; en prøve af den modbydelige substans, der svirrer under grydens platform, vælter nu frem og tilbage inde i den skrøbelige glasbeholder.\n\nMed giften i hånden er det tid til at vende tilbage til Skyggepræstinde Vanddis ved Bolværket for at fuldføre missionen.", p="Når vi med succes har analyseret prøven fra Vridende Hjemsøgelses gryde, giver det os en tredje vej til at levere et ødelæggende modgift mod Svøben!", c="Endnu en fint udført mission, <Name>! Dette gør tre gryder tilgængelige for os, så vi kan vende dem mod Svøben. Hvis Kel'Tuzads nekromantiske herredømme over disse lande ikke var så stærkt, som det er nu, ville jeg vove at påstå, at du ville have lukket dem helt ned!\n\nApoteker Tøvers vil have en rapport om, hvad denne gryde - samt de andre underlagte gryder - vil kræve for at levere vores modgift til pesten. Med det er tiden kommet til at bringe den sidste gryde i vest under vores indflydelse!"},
  [5235] = {n="Mål: Gorrons Visnende", l="Gå til Gorrons Visnende i Vestlige Pestlande for at finde og besejre Gryde-herren der, og brug dens nøgle til at få adgang til gryden. Du skal have den tomme Gorrons Visnende-flaske med dig for at sikre en prøve af giftene i gryden.", d="Den sidste gryde, der er tilbage, ligger på en gård, der nu kaldes Gorrons Visnende. Den bevogtes af nogle af Svøbens sejeste håndlangere - nærmere bestemt genfærd og spøgelser. De skal ikke tages let på, <Name>.\n\nGorrons Visnende ligger langt øst for Bolværket, tæt på hvor Østlige Pestlande begynder; eliminer igen gryde-herren der for dens nøgle. Her er din tomme prøveflaske; bring den til mig fyldt. Må skyggerne hylle dig i sikkerhed under denne farlige mission, <Class>.", p="Et adgangspanel til gryden sidder stadig fast skruet. For at åbne det skal du finde nøglen.", c="Gryde-herren Sjælevredes nøgle opløses, idet den rører ved låsen på adgangspanelet ved bunden af grydens platform. En svag klirrende lyd høres indefra, og adgangspanelet svinger op og afslører mere tyktflydende gift inde i grydens konstruktion.\n\nDer er en lille hane, som flasken passer nogenlunde under, så du kan tappe en prøve til Skyggepræstinde Vanddis tilbage ved Bolværket."},
  [5236] = {n="Vend tilbage til Bolværket", l="Bring den fyldte Gorrons Visnende-flaske til Skyggepræstinde Vanddis ved Bolværket, Vestlige Pestlande.", d="Du lukker omhyggeligt hanen på kontrolpanelet og ser grydens råddenskabelige ichorer dryppe ned i den tomme flaske.\n\nMed giften i hånden er det tid til at vende tilbage til Skyggepræstinde Vanddis ved Bolværket for at fuldføre missionen.", p="Gorrons Visnende huser den sidste gryde, vi skal have adgang til her i vest. Når vi har en prøve af pesten fra den gryde, kan vi introducere vores reagenser i miljøet gennem fire separate kar! Svøben vil få svært ved at holde os ude af alle fire, selv med Kel'Tuzads magt bag sig.", c="Tillykke <Name>, du har låst den sidste gryde op for os! Apoteker Tøvers vil snart vide, hvad denne gryde kræver af reagenser til blandingen.\n\nHvad dig angår, er jeg sikker på, at Overeksekutoren Derrigton vil gerne takke dig personligt for den hjælp, du har givet os. Uden dig ville vores kamp mod Svøben have været næsten uovervindelig. Jeg takker dig, mægtige <Class>."},
  [5237] = {n="Missionen Fuldført!", c="<Name>, din vellykkede ombygning af gryderne er en enorm sejr for os!\n\n<Kommandøren rydder halsen og begynder at brøle højlydt.>\n\nLad alle i min nærhed høre: for tjeneste til Stormvinds rige og til Alliancen, ud over hvad pligten kræver - over for overvældende odds og usædvanlig fare, må jeg tilføje - giver jeg <Name> dette, og jeg udvider vores evige taknemmelighed til ham som en sand helt for Alliancen. Skål, siger jeg!"},
  [5238] = {n="Missionen Fuldført!", c="<Name>, din vellykkede ombygning af gryderne er en enorm sejr for os!\n\n<Overeksekutoren rydder halsen og begynder at brøle højlydt.>\n\nLad alle i min nærhed høre: for tjeneste til De Forladte og til Horden som helhed, ud over hvad der var forventet - over for overvældende odds og usædvanlig fare, må jeg tilføje - giver jeg <Name> dette, og jeg udvider vores evige taknemmelighed til ham som en sand helt for Horden. Hurra!"},
  [5241] = {n="Onkel Karlin", l="Find Karlin Rødsti.", d="Nogle gange, når det er nat, kan jeg høre min onkel Karlin græde. Det lyder, som om han er langt væk, mod øst.\n\nJeg håber, han ikke græder for mig! <Name>, vil du finde min onkel og fortælle ham, at jeg har det godt?\n\nHvis du finder ham, så sig, at jeg venter på ham, og at jeg vil høre den historie, han plejede at fortælle... den om kaninerne og bærsylten! Den historie er så sjov!", c="Har du set Pamela? Hun er i live?\n\nHun er død? Nej! Å, Pamela! Hvorfor lider din ånd stadig i denne verden. Hvorfor er du omkommet, mens lykken holder mig i live? Øjeblikkeligt ville jeg bytte plads med dig og vandre rundt i døde Dårshire, et spøgelse og alene!\n\nAh, men denne nyhed kan ikke ændre skæbnen. Tak, <Name>. Nu brænder min pligt, min pligt til hævn, lige så hedt som altid."},
  [5242] = {n="Et Sidste Slag", l="Dræb Mora og Salja, og bring Skyggeherre Ond'dans Hoved til Greta Mosshov i Ondskoven.", d="Desværre ser jeg kun en måde at stoppe denne trussel mod Ondskoven på, og det er et frontalangreb. Der er ingen andre veje ind i Skyggegrebet, og jeg har ingen måde at teleportere dig ind på. Den lige vej ned til bunden er den eneste vej... og jeg ved også, hvem du skal opsøge. Hans navn er Ond'dan... Skyggeherre Ond'dan. Han er den dødelige med magten dernede... han er hovedet på slangen. Dræb ham og hans to sukkubus-tjenere, og vend tilbage til mig. Ond'dan er den, der laver pagter med Legionen. Han må stoppes.", p="Uden Ond'dan vil Skyggerådet forhåbentlig miste fokus og begynde at splitte sig selv. De vil kæmpe med hinanden om kontrollen og gemme på ressourcer til fremtidige planer. Det vil være et gunstigt øjeblik til at knuse dem og deres dæmoniske slaver.", c="Jordmoderen være lovet, <Name>! Tak! Det er en stor dag, sandelig!\n\nSkyggerådet vil få svært ved at nå de samme magtniveauer, som de engang havde, efter dette slag mod deres hierarki. Du har gjort en stor gerning i dag!"},
  [5243] = {n="Det Helliges Huse", l="Rejs til Stratholm, mod nord. Eftersøg forsyningskasserne, der ligger spredt i byen, og hent 5 Stratholm-helligvand. Vend tilbage til Leonid Barthalomæus den Respekterede, når du har samlet nok af den velsignede væske.", d="Jeg ser på min udødelighed som en sygdom, <Race>. En sygdom, der blot kræver behandling; men det er også en stor velsignelse for Sølvdæmringen. Hvilket bedre redskab til at udslette Svøbens hedninge end gennem de udøde?\n\nJeg er respekteret af mine kolleger på grund af de ofre, jeg har bragt, men hædersbevisningerne betyder intet for mig.\n\nHvis du er interesseret i at hjælpe Sølvdæmringen, så kan jeg tilbyde et job.\n\nTag til Stratholm og hent vores overskud af helligt vand. Eftersøg forsyningskasserne.", p="Vær på vagt, ikke alle forsyningskasser har overlevet byens ødelæggelse. Svøben vover ikke at røre vandet, men det helligede vand vil sikkert ikke forhindre skadedyrsplager.", c="Godt gået, <Race>. Du har vist, at selvom du er tolerant over for andre, vil du ikke stoppe ved noget for at ødelægge Kel'Tuzads håndlangere."},
  [5244] = {n="Ruinerne af Kel'Thæril", l="Tal med Jaron Stenformer i Stjernefald Landsby.", d="Historien bag Kel'Thæril handler om en forbandet race, bundet til stedet, hvor de forsøgte et uheldigt ritual...\n\nDe højfødte, du vil finde der, stjal engang en hellig genstand, i troen på at de kunne suge dens magt til sig selv og blive endnu mægtigere. I deres bestræbelser splintredes relikvien i en stor eksplosion og drev stykkerne ned under isen på søen...\n\nTal med Jaron Stenformer, hvis du gerne vil lære mere; han har for nylig besøgt området og kan fortælle dig mere.", c="Jamen, selvfølgelig kan jeg fortælle dig mere om Kel'Thæril. Men husk, jeg er ingen historiker, men jeg kan fortælle dig om, hvad jeg så dér..."},
  [5245] = {n="Plagede Ånder fra Kel'Thæril", l="Brug Jarons Hakke til at finde de fire Højfødte Relikfragmenter. Bring dem til Aurora Himmelkalder i Østlige Pestlande.", d="De højfødte ånder er ynkelige væsener, det er sikkert. De leder stadig efter stykker af netop den ting, der har forbandet dem til Kel'Thæril for evigt -- den stjålne relikvie.\n\nHvis du er så interesseret, så tag min hakke og gå sydpå til søen; se, om du kan samle stykkerne af den op fra isen.\n\nNu kan jeg ikke fortælle dig noget om det, du finder, men jeg kender en, der måske kan... Aurora Himmelkalder; hun bor nær Nordpas-tårnet i den nordlige del af Østlige Pestlande.", p="Hvorfor er du kommet hertil?", c="De højalfers fortid er noget, jeg ikke ønsker at diskutere, <Name>. Det smerter mig at tænke på alt, hvad der er sket... Og på, at der ingen måde er at gøre tingene godt igen."},
  [5246] = {n="Fragmenter af Fortiden", l="Find de Hellige Højfødte Skrifter i Zin-Malørs Tempel i Azsyra, og bring dem til Aurora Himmelkalder nær Nordpas-tårnet i Østlige Pestlande.", d="Jeg indså det ikke... Tilgiv mine hårde ord, <Class>.\n\nMine forfædres fejltagelser er ikke, hvad jeg ønsker at dvæle ved, men hvis din anmodning er virkelig oprigtig, så vil jeg hjælpe dig.\n\n<Aurora undersøger fragmenterne.>\n\nJeg tror, at dette er Zin-Malørs Krystal, en genstand, der kan indeholde og kontrollere stærke arkane kræfter. Den kunne være blevet brugt til gode formål, men de onde hensigter hos dem, der stjal den, fik den til at splintres.\n\nTag til Zin-Malørs Tempel i Azsyra - jeg kan kun håbe, at bogen stadig er der.", p="Det er kun i de hellige skrifters sider, at jeg vil kunne afgøre, om jeg kan hjælpe dig...", c="Siderne har ligget urørte i mange, mange år..."},
  [5247] = {n="Fragmenter af Fortiden", l="Bring en Fortryllet Thoriumstang, 5 Krystalgenopretning og et Hætteglas Frygtindgydende Vand til Aurora Himmelkalder nær Nordpas-tårnet i Østlige Pestlande.", d="Jeg kan hjælpe dig, hvis det virkelig er det, du ønsker, at genskabe artefakten.\n\nFor at samle stykkerne igen har jeg brug for genstande med stærke magiske egenskaber. En fortryllet thoriumstang og fem krystalgenopretninger... Du skal også hente vand fra et sted, der måske virker usandsynligt... Find den frygtindgydende pøl langs Ældreth-rækken ved Rædselshammeren i Vildalas, og fyld dette hætteglas.\n\nMens du er væk, vil jeg forsøge at udlede af disse sider den viden, jeg har brug for, for at reparere skaden på relikvien.", p="Relikvien må kun placeres i hænderne på de mest pålidelige. Den må ikke stjæles igen...", c="Ved hjælp af disse elementer kan jeg smelte fragmenterne sammen... forhåbentlig til det, de engang var."},
  [5248] = {n="Plaget af Fortiden", l="Tag Zin-Malørs Krystal til Kel'Thæril-søen i Vinterkilde og find en højfødt ånd, der vil tale til dig.", d="<Name>, jeg græder over det, der er sket i fortiden. Ligesom denne krystal er alferne som race blevet splintret. Jeg ved ikke, om stykkerne nogensinde vil blive forenet til ét, men min sorg er blevet lindret ved at kunne hjælpe dig med denne lille opgave.\n\nVi må ikke glemme fortiden, <Name>...\n\nTag venligst Zin-Malørs Krystal tilbage til Kel'Thæril-søen. Du skal finde en højfødt ånd, der indser fejlen i det, der blev gjort for så længe siden. Vis ånden, at vi har rettet tingene op igen.", p="Forbaaaandet... Evvvviggg...", c="Snaaa... lad meeeeg væææære..."},
  [5249] = {n="Til Vinterkilde!", l="Find Stjernefald Landsby i Vinterkilde og tal med Vind Natjager.", d="I Vinterkilde, nord for her, findes mange gamle alfiske ruiner. Det er et barskt land, men det gemmer på mange hemmeligheder og steder at udforske.\n\nMed alt mit arbejde at tage fat på her i Ondskoven har jeg ikke haft mulighed for at rejse til Vinterkilde. Men der er ingen grund til, at du ikke skulle!\n\nMens du er der, så led efter Vind Natjager. Han tilbringer det meste af sin tid i Stjernefald Landsby, og han ved meget om området.", c="En ven af Efeu Bladløber? Hyggeligt at møde dig, <Name>."},
  [5250] = {n="Stjernefald", l="Find Stjernefald i Vinterkilde og tal med Vind Natjager.", d="I Vinterkilde, nord for Ondskoven, findes mange gamle alfiske ruiner. Det er et barskt land, men det gemmer på mange hemmeligheder og steder at udforske.\n\nMine studier her holder mig så travlt optaget, at jeg ikke har haft mulighed for at rejse til Vinterkilde i nogen tid. Men der er ingen grund til, at du ikke skulle rejse dertil og studere ruinerne.\n\nMens du er der, så led efter Vind Natjager. Han tilbringer det meste af sin tid i Stjernefald og ved meget om området.\n\nFortæl ham, at du er en af mine elever...", c="En elev af Daryn Lysvind? Hyggeligt at møde dig, <Name>."},
  [5251] = {n="Arkivaren", l="Rejs til Stratholm og find Arkivar Galfærd af Skarlagenrøde Korstog. Tilintetgør ham og brænd Skarlagenrødt Arkiv ned.", d="Alt, der tages til et ekstremt, er farligt for vores verden, <Name>. Tag for eksempel Skarlagenrøde Korstog. Tror du, at deres blinde fanatisme tjener et større gode? Hvor mange uskyldige har de ødelagt i Lysets navn?\n\nKættere, hver og en!\n\nÉn i særdeleshed interesserer mig dog; Arkivar Galfærd af Stratholm: en mand, der holder øje med korstogets mest værdifulde dokumenter. Tilintetgør ham og brænd hans arkiver ned! Hvis du lykkes, så vend tilbage til mig og bliv belønnet.", p="Husk, <Name> - vi må være tolerante, men faste i vores overbevisninger!", c="Fremragende, <Name>! Års efterretninger, tabt! Skarlagenrøde Korstog vil uden tvivl mærke dette slag i de kommende uger."},
  [5252] = {n="Angrende Højfødte", l="Tal med Vind Natjager i Stjernefald Landsby, og spørg om det rette sted for Zin-Malørs Krystal.", d="Den... krystallen...\n\nDe højfødte her er tilsløret af deres egen elendighed...\n\nJeg er sorrrrigfuld, men jeg indser fejlllen ved det, der skete for så længe siden. Selvom der ingen veeej er til at ændre fortiden, er jeg nu i freeed, og ved at du har genfundet Zin-Malørs krystal...\n\nDu skaaal returnere den...\n\nDen skaaaal returneeeeres.", p="Det er gået noget tid, siden du forlod os, <Name>. Hvordan har du klaret dig?", c="Er det... det, jeg tror, det er?"},
  [5253] = {n="Zin-Malørs Krystal", l="Lever Zin-Malørs Krystal til Ærkedruide Fandrel Hjorthelm i Darnassos.", d="Ganske imponerende, <Name>.\n\nZin-Malørs krystal kan aldrig returneres til templet, som, som du ved, ligger i ruiner. Men jeg tror, at din indsats for at ophæve fortidens ondskab ikke bør forblive ubelønnet.\n\nSøg Ærkedruide Fandrel Hjorthelm i Darnassos, og bring krystallen til ham, <Name>. Den bør være i hænderne på dem, der ikke vil misbruge dens magt. Ud fra det, jeg kan se, kan kun en håndfuld af de stærkeste magibrugere kontrollere en sådan kraft.", p="Ja, <Race>?", c="Jeg har hørt om Zin-Malørs Krystal; brugeren af krystallen bliver i stand til utrolig arkan kraft, men kun hvis man er virkelig værdig. Jeg er imponeret over, at du ikke blot har genfundet krystallen, men også erkender dine egne grænser og ikke forsøgte at bruge krystallen selv.\n\nTak for at bringe den til mig, <Name>. Vi vil passe godt på den, og må de forbandede ånder, der engang vogtede den knuste krystal, endelig få fred."},
  [5262] = {n="Sandheden Styrter Ned", l="Bring Balnazars hoved til Hertug Nikolaj Zverenhoff i de Østlige Pestlande.", d="Du forsøger at samle tankerne, mens støvet lægger sig over kammeret. Du gennemgår de begivenheder, der lige har fundet sted, og kan stadig ikke forstå situationens alvor.\n\nSkarlagen-korstogets Storslåede Korsfarer en dæmon? Og ikke bare en hvilken som helst dæmon, men bror til Varimatras, ærkeherren fra Underbyen?\n\nDu stopper omhyggeligt rædselsherrens afhuggede hoved ned i din rygsæk. Ingen ville sikkert tro på historien, du fortæller, uden bevis.\n\nHertug Nikolaj Zverenhoff skal have det at vide med det samme!", p="Hvad har du dér, <Name>?", c="Hvad betyder det her for Korstoget? Er det muligt, at de har været under denne dæmons kontrol? Uden at vide det har de været brikker i en større ondskabs tjeneste?"},
  [5263] = {n="Og Endnu Mere", l="Tag til Stratholm og ødelæg Baron Flodfarer. Tag hans hoved og vend tilbage til Hertug Nikolaj Zverenhoff.", d="Du viser et naturligt talent for ødelæggelse, og du følger ordrer. Det er sjældent at se de to i samme person. Jeg begynder at tro, at du kan blive et fortrinligt redskab for guddommelig retfærdighed.\n\n<Zverenhoff folder hænderne foran ansigtet.>\n\nKel'Tuzads løbedreng hersker over Stratholm. Bevis for mig, at du er en helt - min helt. Ødelæg Baron Flodfarer og vend tilbage til mig med hans hoved.", p="Baronen har myrdet flere mennesker, end du sandsynligvis nogensinde har set i dit liv.", c="Det er mange år siden, jeg sidst har ført en helt ind i vores rækker. Du er den første i årevis, der har fået audiens hos Herre Maksvel."},
  [5264] = {n="Herre Maksvel Tyrosus", l="Tal med Herre Maksvel Tyrosus. Han er inde i kirken.", d="Jeg er ved at give dig en stor ære, <Name>.\n\nHerre Maksvel ønsker at belønne dig for din tjeneste for Sølvdæmringen!\n\nDet er år siden, Maksvel sidst gav udenforstående audiens.", c="Du er en værdig allieret, <Name>. Du skal høste belønningen for din standhaftige hengivenhed."},
  [5265] = {n="Sølvholdet", l="Åbn Sølvholdet og hent din belønning.", d="Gennem årene har Sølvholdet forblevet låst. Ingen har været værdige nok til at række ind og tage Sølvdæmringens kraft derfra - før i dag.\n\nSølvholdet er nu åbent for dig, <Name>.", c="Hov..."},
  [5281] = {n="De Rastløse Sjæle", l="Find Egon. Du ved kun, at han sidst blev set omkring Stratholm.", d="Der er dem, der døde tragisk under Stratholms fald. Mange tog deres eget liv ved at kaste sig ind i de utallige flammer fra den smoldrende by, i stedet for at blive en del af Geislen.\n\nNu vandrer de rundt på Stratholms gader som rastløse ånder.\n\nVi må hjælpe dem, <Name>!\n\nJeg har en medarbejder ved navn Egon, der har udrettet mirakuløst arbejde med spøgelser og sjæle. Opsøg ham. Han færdes på de østlige Pestlande nær Stratholm og tester sine opfindelser.", c="Alen har endelig fundet nogen modige nok, hvad?"},
  [5282] = {n="De Rastløse Sjæle", l="Brug Egons Blaster på Stratholms spøgelsesagtige og spektrale borgere. Når de rastløse sjæle bryder fri af deres spøgelseskabyller, skal du bruge blasteren igen - så får de frihed!\n\nBefri 15 rastløse sjæle og vend tilbage til Egon.", d="Jeg henter min kraft - min vilje til at fortsætte med at leve og trække vejret - fra det ubændige had, jeg bærer til Geislen og alt, hvad den har gjort. Jeg er dog ingen fanatiker. Der er dem, som Skarlagen-korstoget, der hellere vil ødelægge de uskyldige udøde, end give dem blot en snert af medfølelse.\n\nHvilket fører mig til dette: Min blaster. Den vil løse de pinte sjæle fra Stratholm.\n\nBrug den på spøgelserne, der hjemsøger de plyndrede gader. Befri deres sjæle.", p="Medfølelse er det, der adskiller os fra dyrene, <Name>. Husk det...", c="<Egon tørrer en tåre væk fra sit øje.>\n\nSå du min mor, <Name>? Befriede du hende?\n\nDu er et strålende eksempel på anstændighed. Som tak for besværet..."},
  [5283] = {n="Kunsten at Blive Rustningssmed", l="For at blive Rustningssmed skal du lave følgende genstande og returnere dem til Grumsnus: 4 Forzirede Mithrilhjelme, 2 Forzirede Mithrilstøvler, 1 Forziret Mithril-brystplade.", d="Så du tog den kloge beslutning.\n\nDer er ikke gået mistet af kærlighed mellem mig og en gammel Jernus her. Den gode-til-ingenting legetøjsmager ved godt, hvem der er de sande håndværkere her omkring.\n\nDe virkelig store krige vindes med et godt forsvar. Når det bliver tid til at gå i kamp, vil ingen offensiv hjælpe dig.\n\nRigtigt, lad os komme i gang. Alt du skal gøre er at vise mig, at du har noget rå talent. Derefter river jeg alle urenheder, der måtte være tilbage i dig, ud og former dig til en rustningssmed. Du ved vel nok at lave forziret mithril, ikke?", p="Ah, der er intet som en god smedebrænding. Man kan se, hvem der har de virkelig flotte brændinger ud fra forklædets linjer.", c="Nu er det, <Name>. Efter dette er der ingen vej tilbage. Det er ikke for sent at blive legetøjsmager, øh, våbensmed.\n\nJeg stoler på, at du træffer den rigtige beslutning."},
  [5284] = {n="Vejen til Våbensmeden", l="For at blive Våbensmed skal du lave følgende genstande og returnere dem til Jernus: 4 Månestål-bredsværd, 4 Massive Jernøkser, 2 Tunge Mithriløkser og 2 Store Sorte Køller.", d="Som våbensmed vil du opdage, at det oftere end ikke er helte og eventyrere, der kommer til dig efter udstyr. Selvom arbejdsbyrden til tider kan være utålelig, opvejer rigdommene mere end nok for rygsmerterne og askelungen.\n\nÅh ja, <Name>, våbensmedene er dem med alt guldet!\n\nHvis du ønsker at slutte dig til vores rækker, må du vise mig, at du kan lave mig en sølvmønt eller to - jeg mener, vise mig, at du har, hvad der skal til for at være den, folk henvender sig til, når de har brug for førsteklasses våben. Gå i gang!", p="<Jernus er travlt optaget af at stable guldmønter i pæne små bunker.>", c="Om tide! Jeg har kunder, der venter.\n\nGiv dem her og hold godt øje. Du skal tage det første skridt i din karriere som våbensmed."},
  [5301] = {n="Kunsten at Blive Rustningssmed", l="For at blive rustningssmed skal du lave følgende genstande og returnere dem til Okotos: 4 Forzirede Mithrilhjelme, 2 Forzirede Mithrilstøvler, 1 Forziret Mithril-brystplade.", d="Tilfredsstillelse. Det er det, jeg henter fra hammeren og ambolten. At se en stolt Horden-kriger beskyttet under mit stål minder mig om, hvad det vil sige at være i live. Det er en afhængighed, jeg aldrig tør give slip på, <Name>.\n\nJeg kan ikke give dig denne tilfredsstillelse, jeg kan blot sætte dig på vejen. Ligesom med alle livets bestræbelser er rustningssmedens vej en rejse.\n\nHvis du ønsker at være en af de udvalgte få, skal du blot spørge, så vil jeg træne dig, men en opgave må du først fuldføre.", p="Jeg vil banke på stålet, indtil selve åndedrættet er taget fra mig.", c="Dette er det sidste skridt, før du begynder din nye karriere som rustningssmed, <Name>. Skulle du vælge at trække dig, er nu din sidste chance. Ellers skal du gøre dig klar til et liv i herlighed."},
  [5302] = {n="Vejen til Våbensmeden", l="For at blive Våbensmed skal du lave følgende genstande og returnere dem til Borgøsj: 4 Månestål-bredsværd, 4 Massive Jernøkser, 2 Tunge Mithriløkser og 2 Store Sorte Køller.", d="Én dag vil jeg skabe en legendarisk hammer. En hammer, der er værdig en Stammeleder!\n\nDet er mit livs værk, <Name>. Min passion. Jeg kan se, at du har potentialet til at være blandt os, en af os - en våbensmed. Jeg er den, der kan hjælpe dig med at udnytte det potentiale.\n\nEn enkel opgave er alt, du skal fuldføre. Enkel for en med din usædvanlige dygtighed.", p="For Hordens ære!", c="Dette er det sidste skridt, før du begynder din nye karriere som våbensmed, <Name>. Skulle du vælge at trække dig, er nu din sidste chance. Ellers skal du gøre dig klar til at blive opslugt af viden!"},
  [5305] = {n="Sød Ro", l="Rejs til Stratholm og dræb den Karmosinrøde Hammersmed. Hent den Karmosinrøde Hammersmeds forklæde og vend tilbage til Lilit.", d="Inden for Skarlagen-bastionens mure ligger den søde ro. Den Karmosinrøde Hammersmed vogter opskriften med sit liv. Besejr ham og bring mig hans forklæde. Til gengæld vil jeg lære dig at blive smed.\n\nForstå dette: Når du har valgt smedens vej, vil sværdsmedens og øksesmedens veje ikke længere være tilgængelige.", p="Hans forklæde! Hvor er det?", c="Måtte du banke mange hjerner ind, <Name>!"},
  [5306] = {n="Slangestenen fra Skyggejægerinden", l="Rejs til Sortklippe-spiret og dræb Skyggejæger Vosh'gajin. Hent Vosh'gajins slangesten og vend tilbage til Kilrem.", d="Lad dig ikke narre af hendes skønhed, <Class>. Skyggejægerinden Vosh'gajin er dødbringende og forrykt.\n\n<Kilrem peger på arret i sit ansigt.>\n\nJa, hun gav mig det - et kærlighedsslag, kaldte hun det.\n\nHævnens tid er endelig kommet.\n\nDu kan finde Vosh'gajin i Sortklippe-spiret. Dræb hende og vend tilbage til mig med hendes slangesten. Gør du det, lærer jeg dig øksesmedenes veje.", p="Legenden siger, at ét brug af Vosh'gajins slangesten vil holde en økse skarp i 1000 år!", c="Viden er magt!"},
  [5307] = {n="Fordærvelse", l="Find Sortgardens Sværdsmed i Stratholm og ødelæg ham. Hent Sortgardens Insignie og vend tilbage til Seril Geislebane.", d="Hvis jeg er kort for hovedet over for dig, er der en grund til det. Planerne til det store sværd, Fordærvelse, er blevet stjålet af Sortgarden: elitære skeletenheder under Baron Flodfarer.\n\nJa, Baron Flodfarer fra Stratholm.\n\nSortgardens sværdsmed vogter nu disse planer med sin... udødelighed.\n\nDræb ham og vend tilbage med bevis for din bedrift, så vil jeg lære dig sværdsmedens veje.", p="Har du glemt, hvad det var, du fik til opgave, <Name>?", c="Det burde være indlysende, at et sværd altid er det bedste valg."},
  [5321] = {n="Den Sovende Er Vågnet", l="Eskorter Kerlonian Evigskygge til Lilladris Månefloden ved Maestras Post i Askedalen.", d="Jeg var på vej til Maestras Post for at møde Lilladris Månefloden, men jeg besluttede at stoppe her og tage en kort lur. Lige siden jeg vågnede fra den smaragdgrønne drøm, har jeg været så søvnig...\n\n<gaber>\n\nVil du mon vise mig vejen? Jeg forstår, at Maestras Post ligger syd for her, langs vejen i Askedalen. Det kan være farligt, så jeg håber, du har nogle venner, der vil følge med os.\n\nTilsidst: Jeg kan falde i søvn, så hvis du nogensinde skal vække mig, så brug mit horn. Du finder det i kisten her.", p="Er Kerlonian ankommet?", c="Åh, jeg er så glad for, at Kerlonian klarede den! Og jeg er sikker på, at jeg finder ham sovende et sted her i nærheden, ikke sandt?\n\nTak, fordi du viste ham vejen, <Name>."},
  [5341] = {n="Barov-familiens Formue", l="Tag til Skolomancen og hent Barov-familiens formue. Fire skøder udgør denne formue: Skødet til Kær Darrow; Skødet til Gryde-by; Skødet til Tarren Mølle; og Skødet til Sydhavn. Vend tilbage til Aleksi Barov, når du har fuldført opgaven.", d="Inde i Skolomancen ligger Barov-familiens formue. Jeg, Aleksi Barov, er en af de to sidste tilbageværende arvinger til huset Barov. Min bror, Veldon, er den anden.\n\nVeldon, den elendige kujon, flygtede under krigen og beholdt dermed sin værdiløse eksistens som menneske.\n\nNu leder han efter skøderne, så han kan gøre formuen til sin egen. Hent skøderne, før min bror gør det, så vil jeg gøre dig rig ud over dine vildeste drømme!", p="Bøj dit hoved i min nærværelse, <Race>. Jeg er trods alt en adelsmand, og du er en skillingsløs bonde.", c="Fremragende arbejde, <Race>. Nu skal min arv sikres..."},
  [5342] = {n="Den Sidste Barov", l="Rejs til Kuldevind-lejren - Alliancens område - og myrd Veldon Barov. Tag hans hoved og vend tilbage til Aleksi Barov.\n\nVær advaret: Veldon vil sandsynligvis være godt beskyttet af Alliancens pøbel.", d="Naturligvis kan der, så længe min bror stadig lever, være uenighed om, hvem der er familiens primære arving. Dette kan ikke tillades.\n\nJeg håber, at en lumsk gadeknægt som dig ikke er for fin til et lille koldblodigt mord.\n\nDet er en simpel opgave, og en jeg forventer, du klarer - altså hvis du ønsker at hæve din belønning.\n\nVeldon sidder under Alliancens beskyttelse i Kuldevind-lejren, mod øst. Dræb ham og bring mig hans hoved.\n\n<Aleksi gaber.>\n\nSkynd dig nu.", p="Sikr min formue og del i byttet.", c="Vidunderligt! Nu har kun jeg magten og formuen i huset Barov!\n\n<Aleksi kaster en stor pose mod dig.>\n\nBehold resten, din beskidte dyr."},
  [5343] = {n="Barov-familiens Formue", l="Tag til Skolomancen og hent Barov-familiens formue. Fire skøder udgør denne formue: Skødet til Kær Darrow; Skødet til Gryde-by; Skødet til Tarren Mølle; og Skødet til Sydhavn. Vend tilbage til Veldon Barov, når du har fuldført opgaven.", d="Min kære bror Aleksi. For en tåbe jeg var, da jeg skånede hans liv. Jeg så fjenden i øjnene, en af de udøde, og lod ham leve.\n\n<Veldon spytter.>\n\nNu leder han efter MIN arv. Det må simpelthen ikke ske.\n\nFind min families skøder, før den modbydelige stodder får sine knoglede hænder på dem, så vil jeg belønne dig med enorme rigdomme. De ligger i ruinerne af Skolomancen. Skynd dig!", p="Sikr min fremtid, så sikrer jeg din.", c="Der er kun én opgave mere, som jeg må bede dig om, <Name>."},
  [5344] = {n="Den Sidste Barov", l="Rejs til Bolværk - Hordens område - og myrd Aleksi Barov. Tag hans hoved og vend tilbage til Veldon Barov.\n\nVær advaret: Aleksi vil sandsynligvis være godt beskyttet af Horde-snavs.", d="Med skøderne genvundet er der kun én ting tilbage at gøre. Aleksi må dø. Med ham død behøver jeg aldrig bekymre mig om en skrupelløs bande lejesoldater, der vil have mit hoved.\n\nDet er en simpel opgave. Aleksi gemmer sig under Hordens beskyttelse - på Bolværk.\n\nNej, jeg forventer ikke, at du bare går hen og dræber ham, jeg vil have hans hoved! Hvordan du får det... tja, den del er op til dig. Den slags opførsel er under en mand af min adelige opdragelse.", p="Du vil da have betaling, ikke?", c="En strålende dag! Endelig er huset Barovs pletter fjernet, og min formue er sikret!\n\nTag dette og forsvind af min sigte, bonde."},
  [5361] = {n="Stamtræet", l="Lever Klippevagt Langhorns rapport til Natakka Langhorn ved Spøgelsesvandrer-posten i Forødelse.", d="Min bror Natakka er stationeret ved Spøgelsesvandrer-posten derovre i Forødelse. Jeg vil gerne spørge dig... kunne du give ham denne rapport for mig? Et år er gået, siden jeg sidst skrev. Der har været usædvanlig kentaur-aktivitet siden da, og han bør få besked.\n\nRejs til Stenstemmebjerget nord for Korsvejen, og drag derefter vestpå ind i Den Brændte Dal. Derfra skal du gå sydpå ind i Forødelse; der finder du en vej, der fører sydpå til Spøgelsesvandrer-posten.", p="Hvilke nyheder har du, <Class>! Ah - en besked fra min bror, siger du? Nå, så giv mig rapporten!", c="Jeg ved ikke, hvilken forbindelse du har til min bror, men det lader til, at han har tillid til dig, <Class>.\n\nJeg er Natakka Langhorn, og jeg vil gerne byde dig velkommen til Spøgelsesvandrer-posten. Vi har mange behov for en <Class>! Tal med de andre - måske er der brug for dig her."},
  [5381] = {n="Irukos' Hånd", l="Hent Dæmonkassen fra Tordenøksefæstningen, og returner den sammen med Dæmonhakken til Taiga Vismand i Skyggebytte-landsbyen.", d="Brændende Klinge besidder Dæmonkassen. Inde i den ligger den mægtige Irukos' Hånd. Brændende Klinge bruger den til at åbne dæmoniske portaler ved Mannorok-hekseriet. Vi må stoppe strømmen af dæmoner, der trænger ind i vores verden, <Name>!\n\nBrug denne dæmonhakke på den røde krystal i Tordenøksefæstningen for at få adgang til Dæmonkassen.", p="<Name>, har du Dæmonkassen?", c="Ah, Dæmonkassen. Giv den til mig, <Class>, så åbner jeg den... og afslører dermed Irukos' Hånd for dig."},
  [5382] = {n="Læge Theolen Krastinov, Slagteren", l="Find Læge Theolen Krastinov inde i Skolomancen. Ødelæg ham, brænd derefter Eva Surhoffs levninger og Lusien Surhoffs levninger. Vend tilbage til Eva Surhoff, når opgaven er fuldført.", d="Krastinov er ansvarlig for tusindvis af dødsfald. Han skal straffes, retfærdigheden skal ske.\n\nFind ham og påfør ham den smerte, han har tilføjet utallige uskyldige. Når han er ødelagt, skal du brænde vores levninger. Gør dem til aske, <Name>.", p="Slagteren skal stoppes!", c="Jeg kan mærke, at min ånd heler, <Name>. Du har gjort min mand og mig en stor tjeneste, men jeg er sikker på, at der er mere at gøre."},
  [5383] = {n="Krastinovs Rædselspose", l="Tag Rædselsposen til Eva Surhoff på Kær Darrow.", d="Du åbner posen og opdager diverse tortur-redskaber. Blandt tingene fanger et mærkeligt objekt din opmærksomhed: Et glas blod - stadig lunt at røre ved.\n\nDu tror, at Surhoffs måske er interesserede i din opdagelse."},
  [5384] = {n="Kirtonøs Herold", l="Vend tilbage til Skolomancen med Uskyldiges Blod. Find verandaen og placér Uskyldiges Blod i glødekummen. Kirtonøs vil komme for at fortære din sjæl.\n\nKæmp tappert, giv ikke en tomme efter! Ødelæg Kirtonøs og vend tilbage til Eva Surhoff.", d="Så er det nu, <Name>.\n\n<Eva peger på glasset inde i posen.>\n\nUskyldiges blod. Det reneste blod, brugt til at formilde Krastinovs herre.\n\nDet er med dette blod, at Kirtonøs kan kaldes frem. Det er altså med dette blod, at Kirtonøs skal ødelægges.\n\nTag blodet med til verandaen. Placér det på glødekummen. Kirtonøs vil komme - han kan ikke modstå det. Når han viser sig, skal du udløse raseriet og vreden fra tusind uskyldige dødsfald over ham.\n\nLykkes det dig, vil du fortjene mere end blot vores taknemmelighed.", p="Vær på vagt, Kirtonøs er en garvet kæmper.", c="Med Kirtonøs' død er et kapitel i Skolomancens rædselsfulde historie slut. Der er dog stadig mere at gøre. Andre her er nu blevet bekendt med dine modige gerninger. Tag dette, <Name>. Det er et stykke af vores egen essens. Den vil gøre det muligt for dig at kommunikere med de andre tabte sjæle på Kær Darrow."},
  [5385] = {n="Levningerne efter Trey Lysssmede", l="Lever Trey Lysssmedes levninger til Jessir Månebue i Ondskoven.", d="Du samler sækken forsigtigt op og gør dig klar til at vende tilbage til Jessir Månebue på grænsen mellem Ondskoven og Askedalen. Forhåbentlig vil paladinen blive behørigt æret, når du har overbragt hans levninger til hans venner.", p="Hvordan gik det i Jaedenar, <Name>?", c="Du har klaret det! Lovet være Elunie og de magter, du end tilbeder, <Name>. Du har gjort noget ærefuldt og ædelt i dag. Jeg er sikker på, at Arko'narinsen vil glæde sig over, at du ikke blot tog dig tid til at redde hende, men også til at slå ned på det væsen, der torturerede en af hendes bedste venner.\n\nJeg ønsker, jeg kunne gøre mere for dig, men tag venligst dette."},
  [5386] = {n="Dagens Fangst", l="Tal med Jinar'Zillen i Skyggebytte-landsbyen, og bring derefter Natakka Langhorn 2 Blodmavefisk.", d="Lugten af stegt fisk har længe været fraværende her ved Spøgelsesvandrer-posten. Trolde i Skyggebytte-landsbyen er de bedste til at fange fisk... men desværre har jeg med al kentaur-aktiviteten kun lidt tid til at tage ned til trollene. Hrm...\n\nGør mig en tjeneste og rejs til Skyggebytte-landsbyen. Tal med den lokale fisker Jinar'Zillen og bring mig tilbage min yndlingsfisk, Blodmavefisk. Vejen syd for her fører dig mod vest til trollenes landsby.", p="Min hov prikker, og munden begynder at løbe i vand, når jeg tænker på stegt Blodmavefisk... Har du nogen på dig?", c="Du er en frelser, <Name>! Disse Blodmavefisk ser næsten gode nok ud til at spise rå.\n\n<Natakka begynder at savle.>\n\nVær så venlig - vælg en af disse genstande som betaling for fiskene."},
  [5401] = {n="Sølvdæmringens Hverv", c="Alle, der bekæmper ondskab på Sølvdæmringens vegne, skal bære vores hverv. Den, der bærer det, opnår retten til at kræve de belønninger, vores kvartermestre har at tilbyde.\n\nMens du er under hverv, kan du skaffe Geislesten fra faldne fra Geislen; det er insignier, de nogle gange bærer. Skaf disse insignier og bring dem til mig. For hvert sæt du afleverer, får du vores tegn på tapperhed - Sølvdæmringens Tapperhedsmærke.\n\nOpfyld din skæbne, <Class> - slut dig til kampen i dag!"},
  [5405] = {n="Sølvdæmringens Hverv", c="Alle, der bekæmper ondskab på Sølvdæmringens vegne, skal bære vores hverv. Den, der bærer det, opnår retten til at kræve de belønninger, vores kvartermestre har at tilbyde.\n\nMens du er under hverv, kan du skaffe Geislesten fra faldne fra Geislen; det er insignier, de nogle gange bærer. Skaf disse insignier og bring dem til mig. For hvert sæt du afleverer, får du vores tegn på tapperhed - Sølvdæmringens Tapperhedsmærke.\n\nOpfyld din skæbne, <Class> - slut dig til kampen i dag!"},
  [5461] = {n="Mennesket Ras Frostviske", l="Rejs til Arathi-højlandet, til ruinerne af Stromgård. Søg i Stromgård efter et Mindesmærke for Erindring. Hvis du finder en sådan genstand, skal du vende tilbage med den til Dommer Marduk.", d="De udøde frygter livet, ligesom de levende frygter døden. Det er ikke usædvanligt, at et sanseligt udødt væsen fuldstændig udsletter alle rester af sit tidligere liv, efter at det er blevet vendt.\n\nDesværre må vi, for at skabe et artefakt, der kan forvandle Ras Frostviske tilbage til et dødeligt væsen, have et mindesmærke fra hans år blandt de levende.\n\nDu skal drage til den ødelagte by Stromgård, Frostviskes hjem, og lede efter en sådan genstand. Må held være med dig, <Name>.", p="Et mindesmærke for erindring er et sjældent fund, <Name>.", c="Jeg havde tvivlet på, at en sådan genstand fandtes. Dette åbner helt sikkert en utrolig mulighed - en vi ikke må spilde.\n\nForbered dig, <Name>, på det, jeg er ved at bede dig om, for det vil føre dig ned i helvedes dybder."},
  [5462] = {n="Den Døende, Ras Frostviske", l="Rejs til Lysets Håb i Østlige Pestlande og søg Leonid Barthalomæus den Ærværdige. Vis ham Mindesmærket for Erindring og fortæl ham alt, du har opdaget.", d="På besmittet jord skal mindesmærket indstilles.\n\nDet siges, at Stratholm er stedet, hvor Frostviske bukkede under for Liskekongen. På de blodplettede grunde gav han sit liv - frit og med motiv - for at blive en af de udøde.\n\nDet er de grunde, der må findes.\n\nDer er én, en udød oprører mod Geislen, befriet af Dødsånd-dronningen, men loyal over for Sølvdæmringens sag. Find ham: Leonid Barthalomæus den Ærværdige. Han kan måske vide mere. Søg Lysets Håb, <Name>.", p="Stil ikke spørgsmål, du ikke ønsker svar på.", c="<Leonid ser på mindesmærket.>\n\nDit dilemma vækker minder, som jeg havde håbet aldrig ville dukke op igen."},
  [5463] = {n="Menetils Gave", l="Rejs til Stratholm og find Menetils Gave. Placer Mindesmærket for Erindring på den uhellige jord.", d="Jeg så, da mennesket Ras Frostviske lovede sin udøde sjæl til Liskekongen. Han trak dolken mod sin egen hals og skar med et smil fra øre til øre. Hans legeme faldt sammen inden for pentagrammets grænser. Liskekongen stod over den faldne magiker, og med en enkelt bevægelse blev Ras Frostviske, Liske, født.\n\n<Leonid stirrer ned i jorden og ser så op på dig.>\n\nJa, <Race>, jeg husker. Det, du søger, har et navn - Menetils Gave: Jorden velsignet af Liskekongen - hellig jord for Geislen.", p="Området omkring Menetils Gave er usædvanligt koldt.", c="Du placerer mindesmærket på den besmittede jord."},
  [5464] = {n="Menetils Gave", l="Tag det Sjælebundne Mindesmærke til Leonid Barthalomæus i Østlige Pestlande.", d="De faldnes sjæl klamrer sig til det, der repræsenterer dens tidligere liv, og forvandler genstanden til et sjælebundet mindesmærke. Du samler genstanden op og placerer den i din rygsæk.", p="<Leonid ryster.>", c="Ligesom sjælen klamrede sig til mindesmærket, skal den også klamre sig til Ras Frostviskes fysiske skikkelse."},
  [5465] = {n="Sjælebundet Mindesmærke", l="Vend tilbage til Dommer Marduk i Caer Darrow. Vis ham det Sjælebundne Mindesmærke.", d="Vend tilbage til Marduk med mindesmærket, <Name>. Han vil instruere dig i dets brug.", p="Har du gjort det umulige?", c="Jeg var sikker på, at du ville slutte dig til mig som en anden hjælpeløs ånd."},
  [5466] = {n="Liske Ras Frostviske", l="Find Ras Frostviske i Skolomancen. Når du har fundet ham, skal du bruge det Sjælebundne Mindesmærke på hans udøde skikkelse. Hvis du lykkes med at forvandle ham tilbage til et dødeligt væsen, skal du slå ham ned og hente Ras Frostviskes menneskehoved. Tag hovedet med tilbage til Dommer Marduk.", d="Der er kun én opgave tilbage, <Name>. Konfronter liske Ras Frostviske i hans hule.\n\nBrug mindesmærkets kraft mod udyret - vær ubarmhjertig i dine handlinger! Hold stand mod de slag, det flailende udyr med sikkerhed vil lande på dig. Lad dig ikke knække af smerten!\n\nNår ritualet er fuldført, vil Ras atter være dødelig. Det er på det tidspunkt, han skal slås ihjel. Slå ham ned og tag hans menneskehoved.", p="Du bærer byrden af ti tusinde rastløse sjæle, <Name>.", c="Ti tusinde sjæle skriger i kor, <Name>! Du har dealt et dødeligt slag mod Geislen og deres herrer."},
  [5501] = {n="Knoglesamleren", l="Bring 10 Kodo-knogler fra Kodo-kirkegården til Bibbly Fjuzbukkel hos Kormegs Hytte.", d="Vi sidder på en guldgrube her, siger jeg dig - en guldgrube! Kodo-knogler vil forandre verden for altid... Jeg har kunder, der laver møbler, musikinstrumenter og endda sprængstof af dem.\n\nDer kommer en karavane forbi, som henter mine kodo-knogler og så sælger dem i Skyggebytte-landsbyen. Hvis du kan rejse til kodo-kirkegården syd for her og bringe mig ti kodo-knogler, giver jeg dig noget til gengæld. Er det en aftale?", p="Har du knoglerne? Karavanen er her når som helst. Jeg mangler bare ti kodo-knogler mere for at nå en karrierehøjde. En karrierehøjde, siger jeg dig!", c="Ah, herligt! Mine knogler!\n\nJeg kan ikke vente, til drengene derhjemme ser mit ansigt på forsiden af Nissepreneur. Jeg bliver den rigeste nisse i verden... og min gymnastiklærer sagde, at jeg aldrig ville blive til noget."},
  [5502] = {n="En Hordens Værge", l="Aflever din værge i Orgrimgrads børnehjem ved at give det Orkiske Forældreløsfløjte til Børnehjemsmoderen Krigsklage i Æresdalen.", d="Du har været så utrolig venlig mod mig, <Name>. Jeg havde aldrig drømt om, at jeg ville more mig så meget under Børnenes Uge. Tak. Jeg vil ikke være ked af det, der er sket med mig - mine forældre sagde altid, at jeg skulle hæve mig over alt det dårlige, der sker. Jeg bliver en helt... ligesom dig.\n\nDet er trist at sige, men det er tid for mig at tage hjem. Lad os gå tilbage, så fortæller jeg moderen, hvilken fantastisk person du er!", p="Det er en fornøjelse at se dig igen, <Name>. Har du udført de pligter, du meldte dig til under Børnenes Uge?", c="Må ånderne velsigne dig, <Name>. Du har gjort mere for Grunth, end de fleste nogensinde ville have tænkt på at gøre for ham. Tak - du er det ypperste billede på, hvad det vil sige at være en helt for Horden.\n\nVær venlig - hvis du kan undvære tiden, så kom tilbage og besøg os. Jeg ved, at Grunth ville ønske det, og det ville jeg også.\n\nGrunth havde så meget sjov med dig, <Name>. Han ville gerne give dig et af sine yndlingskæledyr, så du husker ham."},
  [5503] = {n="Sølvdæmringens Hverv", c="Alle, der bekæmper ondskab på Sølvdæmringens vegne, skal bære vores hverv. Den, der bærer det, opnår retten til at kræve de belønninger, vores kvartermestre har at tilbyde.\n\nMens du er under hverv, kan du skaffe Geislesten fra faldne fra Geislen; det er insignier, de nogle gange bærer. Skaf disse insignier og bring dem til mig. For hvert sæt du afleverer, får du vores tegn på tapperhed - Sølvdæmringens Tapperhedsmærke.\n\nOpfyld din skæbne, <Class> slut dig til kampen i dag!"},
  [5504] = {n="Daggryets Skulderkapper", l="Bring 10 Tapperhedsmærker til Kvartermester Hasana på Bulværket, Vestlige Pestlande.", d="Din tjeneste for Sølvdæmringen skal roses, <Name>. Du er virkelig æret blandt os. Jeg er blevet bemyndiget til at gøre en af Daggryets mest værdsatte genstande tilgængelig for dig at købe - vores skulderkapper mod magi.\n\nNår en kappe påsættes din eksisterende skulderbeskytter, vil den styrke din modstand mod magiens kræfter på en af fem mulige måder. Som tegn på fortsat hengivenhed over for vores sag beder jeg om ikke mindre end ti af vores tapperhedsmærker i bytte for adgang til disse kapper.", p="Ah, ædle <Class>! Har du bragt de tapperhedsmærker, der blev bedt om? Når du har givet dem til mig, gør jeg vores forskellige kapper tilgængelige for dig at købe.", c="Fremragende - din hyldest til Daggryet er behørigt noteret, <Name>. Med dette udført er jeg glad for at gøre vores kapper tilgængelige for dig at købe. Så længe du bevarer din nuværende status hos os, kan disse kapper købes hos enhver autoriseret kvartermester i Sølvdæmringen.\n\nFor Daggryet, min bror!"},
  [5505] = {n="Nøglen til Skolomancen", c="Nå, her er du <Name> - den færdige Skeletnøgle. Jeg er så sikker, som jeg kan være, at denne nøgle vil lukke dig ind i Skolomancens mure. Der er dog kun én måde at være helt sikker på, at den virker. Spild ikke tid på at prøve den, siger jeg.\n\nHeld og lykke, mægtige helt. Må du fortsat bringe lys ind i mørket!"},
  [5507] = {n="Daggryets Skulderkapper", l="Bring 10 Tapperhedsmærker til Kvartermester Lysgnist i Kuldevind-lejren, Vestlige Pestlande.", d="Din tjeneste for Sølvdæmringen skal roses, <Name>. Du er virkelig æret blandt os. Jeg er blevet bemyndiget til at gøre en af Daggryets mest værdsatte genstande tilgængelig for dig at købe - vores skulderkapper mod magi.\n\nNår en kappe påsættes din eksisterende skulderbeskytter, vil den styrke din modstand mod magiens kræfter på en af fem mulige måder. Som tegn på fortsat hengivenhed over for vores sag beder jeg om ikke mindre end ti af vores tapperhedsmærker i bytte for adgang til disse kapper.", p="Ah, ædle <Class>! Har du bragt de tapperhedsmærker, der blev bedt om? Når du har givet dem til mig, gør jeg vores forskellige kapper tilgængelige for dig at købe.", c="Fremragende - din hyldest til Daggryet er behørigt noteret, <Name>. Med dette udført er jeg glad for at gøre vores kapper tilgængelige for dig at købe. Så længe du bevarer din nuværende status hos os, kan disse kapper købes hos enhver autoriseret kvartermester i Sølvdæmringen.\n\nFor Daggryet, min bror!"},
  [5511] = {n="Nøglen til Skolomancen", c="Nå, her er du <Name> - den færdige Skeletnøgle. Jeg er så sikker, som jeg kan være, at denne nøgle vil lukke dig ind i Skolomancens mure. Der er dog kun én måde at være helt sikker på, at den virker. Spild ikke tid på at prøve den, siger jeg.\n\nHeld og lykke, mægtige helt. Må dine sejre fortsat bringe dig ry og magt, mens du hærger Skolomancen!"},
  [5513] = {n="Daggryets Skulderkapper", l="Bring 10 Tapperhedsmærker til Kvartermester Bagladslås i Lysets Håb-kapellet, Østlige Pestlande.", d="Din tjeneste for Sølvdæmringen skal roses, <Name>. Du er virkelig æret blandt os. Jeg er blevet bemyndiget til at gøre en af Daggryets mest værdsatte genstande tilgængelig for dig at købe - vores skulderkapper mod magi.\n\nNår en kappe påsættes din eksisterende skulderbeskytter, vil den styrke din modstand mod magiens kræfter på en af fem mulige måder. Som tegn på fortsat hengivenhed over for vores sag beder jeg om ikke mindre end ti af vores tapperhedsmærker i bytte for adgang til disse kapper.", p="Ah, ædle <Class>! Har du bragt de tapperhedsmærker, der blev bedt om? Når du har givet dem til mig, gør jeg vores forskellige kapper tilgængelige for dig at købe.", c="Fremragende - din hyldest til Daggryet er behørigt noteret, <Name>. Med dette udført er jeg glad for at gøre vores kapper tilgængelige for dig at købe. Så længe du bevarer din nuværende status hos os, kan disse kapper købes hos enhver autoriseret kvartermester i Sølvdæmringen.\n\nFor Daggryet, min bror!"},
  [5514] = {n="Skimmel rimer på...", l="Bring de Indgydte Skeletfragmenter og 15 guldmønter til Krinkle Godstål i Gadgetbyen.", d="Nissen, du skal tale med, er Krinkle Godstål. Han sælger sine færdigheder til den højestbydende i Gadgetbyen, inde i Tanaris-ørkenen. Han er sandsynligvis den eneste, der kan fremstille den form, vi har brug for, og hans tjenester er ikke billige. Vi beder dig nu om at grave dybt ved at betale det gebyr, han vil tage.\n\nJeg er apoteker, ikke bankmand. Hvis jeg havde guld liggende, ville jeg bestemt ikke være her.\n\nJeg tror, jeg sagde den stille del højt igen. Ups.\n\nGadgetbyen venter på dig! Held og lykke!", p="Ja, jeg ved, hvem du er, og jeg ved, hvorfor du er her. Tøvers sendte besked til mig, før du ankom. Lad os nu komme til sagen, skal vi?\n\nJeg har en form, du kan bruge til skeletnøglen, men den koster dig - femten guld, på forskud, ingen forhandling. Jeg pakker skeletfragmenterne ned i formen for dig, og jeg lærer dig også at smede nøglens stilk, uden nogen smedekundskab overhovedet... helt gratis, vel at mærke.\n\nSiger nogen, at lejesoldater ikke tilbyder konkurrencedygtige aftaler!", c="Tøvers sagde, at du ville levere varerne, og det har du jo gjort! En aftale er en aftale; lad mig pakke fragmenterne ned i formen for dig.\n\nHar Tøvers allerede indgydt dem? Fremragende... ellers ville det have været en lang tur tilbage til Bolværket for dig."},
  [5515] = {n="Krastinøvs Rædselspose", l="Find Jandis Barov i Skolomancen og tilintetgør hende. Fra hendes lig skal du hente Krastinøvs Rædselspose. Aflever posen til Eva Surhoff.", d="En stor vægt er løftet fra vores hjerter, <Name>, men din opgave er endnu ikke fuldført. Krastinøvs herre, Kirtonøs, lever stadig.\n\nFør du kan møde Kirtonøs, må du dog først sikre en metode, hvorpå du kan kalde ham frem.\n\nDet siges, at Jandis Barov forvalter de uskyldiges blod fra Krastinøv til Kirtonøs.\n\nFind hende i Skolomancens sunkne katakomber og slå hende ned. Bring tilbage de spor, du måtte finde.", p="<Eva toner ind og ud af fokus.>", c="Rædselsposen!"},
  [5517] = {n="Kromatisk Skulderkappe fra Daggryet", l="Bring 25 Tapperhedsmærker til Kvartermester Bagladslås i Lysets Håb-kapellet, Østlige Pestlande.", d="Bror <Name> - dine gerninger for Sølvdæmringen er alt for talrige til at blive genfortalt let. Som en passende hyldest vil jeg skille mig af med en af vores særlige Kromatiske Skulderkapper fra Daggryet - en version, der beskytter bæreren mod alle former for modståelig magi på én gang. Kromatiske Skulderkapper fra Daggryet er forbeholdt kun de mægtigste af Daggryets helte!\n\nBring mig femogtyve tapperhedsmærker som tegn på hyldest, så giver jeg dig den fineste af alle vores skulderkapper.", p="Hilsen, mægtige præst! Har du bragt de tapperhedsmærker, jeg bad dig om? Når du har givet dem til mig, udsteder jeg dig din egen Kromatiske Skulderkappe fra Daggryet.", c="Meget imponerende, <Name> - din Kromatiske Skulderkappe fra Daggryet er nu din!\n\nSå længe du bevarer Ophøjet status hos Sølvdæmringen, kan du købe yderligere Kromatiske Skulderkapper. De bliver straks gjort tilgængelige for dig hos enhver af Daggryets kvartermestre."},
  [5518] = {n="Gordøk-oger-dragten", l="Bring 4 Skruer af Runeklæde, 8 Robust Læder, 2 Runetråde og Oger-garvestof til Knude Fingerbøl. Han er for øjeblikket lænket inde i Gordøk-fløjen i Rædselshammeren.", d="Hvis du skal kæmpe mod dette dyngs konge - og jeg tror, at det er det, du er nødt til - så må du forbi Kaptajn Krømknus. Nu kan du komme forbi ham ved at dræbe ham, javist. Du vil måske faktisk gerne lade ham leve.\n\nHvordan, spørger du? Siden jeg har været her, tror jeg, jeg ved, hvordan man laver en oger-dragt, der varer længe nok til at narre disse tossede. Det eneste problem er stabiliteten - ti minutter højst. Bring mig det, jeg har brug for, så laver jeg en til dig. Jeg går ingen steder...", p="Oger-garvestoffet er nok det sværeste at finde til det, jeg skal bruge for at lave dragten - jeg tror, de har noget ovenpå? Det er svært at sige, for denne kugle og kæde gør det ikke let at bevæge sig...\n\nUnder alle omstændigheder, bring mig de ting, jeg har brug for, så tryller jeg dig en oger-dragt, der vil narre Kaptajn Krømknus til at tro, at du er en af hans mænd.", c="Ja, det her gør tricket. Bare et lille snit her, og en tuck her... hehe - det her kommer til at gå fint! <Et bredt smil stråler fra den lænkede nisses ansigt.>\n\nSå er du klar. Husk - dette er ikke den mest sikkert fremstillede genstand i verden. Du får ti minutters brug, før den falder fra hinanden, og så narrer du ikke nogen! Prøv at bruge den lige før du nærmer dig ham, og husk... den får ham kun til at tro, at DU er en allieret - ikke dine gruppekammerater!"},
  [5521] = {n="Kromatisk Skulderkappe fra Daggryet", l="Bring 25 Tapperhedsmærker til Kvartermester Lysgnist i Kuldevind-lejren, Vestlige Pestlande.", d="Bror <Name> - dine gerninger for Sølvdæmringen er alt for talrige til at blive genfortalt let. Som en passende hyldest vil jeg skille mig af med en af vores særlige Kromatiske Skulderkapper fra Daggryet - en version, der beskytter bæreren mod alle former for modståelig magi på én gang. Kromatiske Skulderkapper fra Daggryet er forbeholdt kun de mægtigste af Daggryets helte!\n\nBring mig femogtyve tapperhedsmærker som tegn på hyldest, så giver jeg dig den fineste af alle vores skulderkapper.", p="Hilsen, mægtige <Class>! Har du bragt de tapperhedsmærker, jeg bad dig om? Når du har givet dem til mig, udsteder jeg dig din egen Kromatiske Skulderkappe fra Daggryet.", c="Meget imponerende, <Name> - din Kromatiske Skulderkappe fra Daggryet er nu din!\n\nSå længe du bevarer Ophøjet status hos Sølvdæmringen, kan du købe yderligere Kromatiske Skulderkapper. De bliver straks gjort tilgængelige for dig hos enhver af Daggryets kvartermestre."},
  [5522] = {n="Leonid Barthalomæus", l="Bring de Frosne Æg til Leonid Barthalomæus i Østlige Pestlande.", d="Jeg modtog en besked fra min herre, Vektus. Nå, beskeden var faktisk ikke fra Vektus... den var fra en vis Leonid Barthalomæus. Jeg kender ikke Leonid, men han kendte min herre, og ingen kender min herre, medmindre han tillader det.\n\nLeonid siger, at Vektus ønsker drageæggene. Han vil have, at du leverer dem til ham i Lysets Håb-kapellet i Østlige Pestlande.\n\nDet gør ondt! Hvorfor dig? Stoler Vektus ikke på mig? Åh, glem det... bare tag æggene og fortæl Leonid, at jeg gjorde, hvad vores herre befalede.", p="Du er den, der laver ballade i Sortklippe-spiret, ikke? Har du det, jeg bad om?", c="Ah, meget godt. Du kender ikke den onde magt, for hvem du har slidt, men nu skal du kende sandheden. Og frygt ikke - jeg er ingen tjener for den herre. Jeg er Leonid Barthalomæus, kendt som \"den Ærværdige\" blandt mine brødre i Sølvdæmringen.\n\nJeg narrede Klinkee til at sende dig og drageæggene til mig. Og det er godt, at mit trick lykkedes, for havde disse æg nået deres tiltænkte bestemmelsessted, ville en stor magt være faldet i fjendens hænder."},
  [5524] = {n="Kromatisk Skulderkappe fra Daggryet", l="Bring 25 Tapperhedsmærker til Kvartermester Hasana på Bulværket, Vestlige Pestlande.", d="Bror <Name> - dine gerninger for Sølvdæmringen er alt for talrige til at blive genfortalt let. Som en passende hyldest vil jeg skille mig af med en af vores særlige Kromatiske Skulderkapper fra Daggryet - en version, der beskytter bæreren mod alle former for modståelig magi på én gang. Kromatiske Skulderkapper fra Daggryet er forbeholdt kun de mægtigste af Daggryets helte!\n\nBring mig femogtyve tapperhedsmærker som tegn på hyldest, så giver jeg dig den fineste af alle vores skulderkapper.", p="Hilsen, mægtige <Class>! Har du bragt de tapperhedsmærker, jeg bad dig om? Når du har givet dem til mig, udsteder jeg dig din egen Kromatiske Skulderkappe fra Daggryet.", c="Meget imponerende, <Name> - din Kromatiske Skulderkappe fra Daggryet er nu din!\n\nSå længe du bevarer Ophøjet status hos Sølvdæmringen, kan du købe yderligere Kromatiske Skulderkapper. De bliver straks gjort tilgængelige for dig hos enhver af Daggryets kvartermestre."},
  [5525] = {n="Befri Knude!", p="Den hedder Gordøk-lænkenøglen - i hvert fald er det, hvad disse \"masser af sjov\" bliver ved med at kalde den. Jeg tror, at nogen af ogerne måske har den, men jeg er ikke sikker på, om nogen bestemte gør. Måske har vagterne en bedre chance for at have en...\n\nHvad taler jeg om - du har den allerede, gør du ikke?! Er det den dér??!", c="Du - rangeret nummer et. Alle andre - rangeret nummer to eller lavere. Åh, tak fordi du befriede mig!\n\nJeg vidste, at mit liv var skæbnet til mere end blot at være forret for en eller anden oger!"},
  [5526] = {n="Skår af Ondranken", l="Find Ondranken i Rædselshammeren og skaf et skår fra den. Chancen er, at du kun kan skaffe ét, når Alzzin Vildformeren er faldet. Brug Renhedens Relikvie til at forsegle skåret sikkert indeni, og aflever det til Rabine Saturnus i Nathavn, Månelunden.", d="Din viden om Eldre'Thalas - Rædselshammeren - i Vildalas vil nu komme til nytte, <Name>. I den østlige del af den ødelagte by er der, hvor Alzzin Vildformeren har udøvet sit korrupte herredømme. Gå derhen med al mulig hast og trods de udfordringer, der måtte vente dig.\n\nFrugtbarhedens Frugt, nu fordærvet som Ondranken, bør være tæt på Alzzin. Når han falder, skal du fange, hvad essens af Ondranken du kan. Forsegl den i Relikviet, og bring den til mig.\n\nHeld og lykke, og må Cenarions hurtighed følge dig.", p="Med det forseglede Renheds-relikvie i vores besiddelse vil det være muligt ikke blot at fjerne en fordærvende trussel fra verden, men også at studere den under vores forsigtige opsyn. Måske kan vi endda finde nye midler til at bekæmpe den korruption, der altid truer Azerot.\n\nJeg ved, at Milli ikke ville have haft det anderledes...", c="Det er gjort, modige <Class>, og dermed står Cenarion-kredsen i din gæld. Selvom krigen langt fra er slut, er et stort slag vundet mod dem, der ville bringe vores undergang.\n\nVær venlig - modtag dette som et tegn på vores varige taknemmelighed. Vid, at du er velkommen her som en helt fra Cenarion-kredsen for din store gerning, <Name>. Tak."},
  [5527] = {n="Et Relikvieskrin af Renhed", l="Rejs til Silitus og led efter et Relikvieskrin i ruinerne af Sydvindslandsbyen. Finder du det, skal du tage det med tilbage til Rabine Saturna i Nathavn, Månelunden.", d="Første skridt er at finde en beholder, der kan rumme et yderst fordærveligt stof, uden at den, der håndterer det, lider men. Der er kun ét apparat, jeg kender til, der muligvis kan indeholde noget så ondt som Ondranken: et Relikvieskrin af Renhed.\n\nDybt i ørkenen Silitus ligger resterne af nattenisse-landsbyen kaldet Sydvind. Jeg ved, at der var en dengang for mange, mange år siden. Skal vi lykkes, har jeg brug for, at du gennemsøger ruinerne i håbet om at genvinde det.", p="Et Relikvieskrin af Renhed er et artefakt i sig selv. Der blev kun lavet få, og næsten alle menes at være gået tabt med tiden.\n\nJeg indrømmer, at jeg har kendt til det i Sydvind et stykke tid nu. Med al uroen i Silitus tænkte jeg dog, at vi skulle holde vores hemmeligheder for os selv. At rode rundt ville kun vække fjendernes mistanke.\n\nDesværre er tiden for selvtilfredshed forbi, især med situationen i Eldre'Thalas.", c="Du er sandelig så opfindsom, som mange påstår. Cenarion-kredsen er velsignet med, at du arbejder i vores sted.\n\nNu hvor Relikviet igen er i vores hænder, har jeg ro i sindet. Jeg føler mig mere tryg ved at bede dig om ikke blot at trodse en ondskabsfuld dæmon, men også at bringe en farlig genstand tilbage på købet..."},
  [5528] = {n="Gordøk-smagsprøven", c="Du er da den store boss nu, så du får en gratis smagsprøve på mine bedre brygge! Disse drikke gør dig stærkere OG giver dig en fin rus! Det er dem, der er de gode, chef... prøv at sige det til Kræg selv!"},
  [5529] = {n="Pestbefængte Unger", l="Dræb 20 Pestbefængte Unger, og vend derefter tilbage til Betina Stortrold ved Lysets Håb-kapellet.", d="Sølvdæmringen har for nylig fundet ud af, at Pesten skaber deres egen pestbefængte drageflugt! Vi må standse dem – hvis Pesten får en styrke af drager, feger de hen over Azeroth uden modstand!\n\nDeres nekromanter avler pestbefængte drager i Skolomancen, midt i Darrowmere-søen.\n\nTag til Skolomancen og dræb så mange unger, du kan... før de bliver større!", p="Kom til Skolomancen, <Name>. Tag dig af de pestbefængte unger, før de vokser!", c="Godt gået, <Name>! Der går længe, før de kan udklække endnu en kuld drager.\n\n...I hvert fald håber jeg, at det bliver sådan!"},
  [5531] = {n="Betina Stortrold", l="Bring de frosne æg til Betina Stortrold.", d="Ægene, du bragte, skulle bruges i Pestens eksperimenter til at skabe en pestbefængt drageflugt. Disse frosne sorte drageæg ville have været uvurderlige i deres studier og ville sikkert have fremskyndet deres tidsplan.\n\nNu er det tid til at få ende på deres forskning.\n\nTag de frosne æg med til Betina Stortrold udenfor. Hun er velbevandret i videnskab og alkymi og har lavet et våben, vi kan bruge mod Pesten. Med din hjælp vil vi give dem et hårdt slag.", p="Hej, <Name>! Jeg hørte, du var her med nogle drageæg? Lad os da se dem!", c="Der er de! Og i så fin en beholder. Den perfekte størrelse!\n\nVi gemmer ægene et sikkert sted, så vi kan studere dem senere, men lige nu har vi brug for den ting, du bragte dem i.\n\nJeg har lavet en indretning med et meget specifikt formål: at ødelægge de utøde lærde i Skolomancen. De studerer drager i deres forsøg på at skabe en pestbefængt drageflugt, og vi må standse deres fremskridt.\n\nJeg kalder indretningen Gryderne fra Morgengryet, for... jeg er ikke sikker på, at den virker!\n\nVil du finde ud af det for os?"},
  [5533] = {n="Skolomancen", l="Tal med Alkymist Arbinton ved Kuldevind-pegen i Vestlige Pestlande.", d="På øen Kær Darrow ligger Skolomancen – et elendigt centrum for Pestens nekromanti og ondskab. Vores fjende holder til derinde og udfører usigelige fordærvelser på uvidende ofre... i hvert fald gætter vi os til det. En dør spærrer vejen, og uanset hvor meget vi prøver, kan ingen komme ind uden en ordentlig nøgle.\n\nAlkymist Arbinton kender Skolomancen godt og har en idé om, hvordan man kan skaffe en nøgle. Du har bevist din værdi over for mig, og nu betror jeg dig denne opgave. Tal med ham om sagen.", c="Velkommen, <Class>. Jeg har viet en stor del af mine seneste studier til Skolomancen, og jeg tror, jeg kender en måde, hvorpå du kan skaffe en nøgle... en der lader dig komme forbi hovedindgangen.\n\nJeg kan kun forestille mig, hvilke grufulde syn der er at se indenfor, <Name>. Jeg ved ikke, hvordan I heltetyper nogle gange gør det..."},
  [5534] = {n="Kim'jæls \"Savnede\" Udstyr", l="Find en Rune, som slangefolkene har i deres besiddelse i Eldarath-ruinerne, og bring den til Kim'jæl i Azsyra.", d="Hvad?! Hvad?!\n\nDet var ikke godt nok for dig? Ved du, hvor dyre de sprængstoffer er? De koster... åh, det er lige meget. Fint, du vil tjene nogle rigtige penge? For sådan driver man forretning: Du beviser, at du er en værdifuld medarbejder, og så bliver du belønnet ordentligt, når du har holdt ud en stund.\n\nHvis du er en \"værdifuld\" medarbejder, så tag til Eldarath-ruinerne og find mig en rune, som de dér Blodalfer ledte efter. Slangefolkene har den angiveligt i deres besiddelse.", p="Nå, <Name>? Hvor er runen? Du er en god medarbejder, ikke? Du er her for at hjælpe?\n\nGør mig ikke i tvivl om at betale dig det, vi blev enige om. Hvad? Åh, vi blev ikke enige om noget? Åh, flot... så tag dig bare tid – bare vid, at det bliver meget mindre, hvis du tager lang tid.", c="Haha! Vidunderligt!\n\nJeg skal nok finde ud af, hvad det her skal bruges til, og hvorfor Magus Rimtorri – hun er den ko, der hyrede mig – ville have den. Haha! Nu har jeg jer, stinkende Blodalfer! Kim'jæl! Ha! Jeg skal lære dem, hvem rotterne er!\n\nDu gjorde det godt, <Name>. Mange tak. Her, tag den mønt og skrid – jeg har nogle ting at finde ud af."},
  [5535] = {n="Åndelig Uro", l="Ødelæg 6 Højfødte Genfærd og 6 Højfødte Liche-unger, før du vender tilbage til Loh'atu i Azsyra.", d="For længe siden var de Højfødte blandt de mest magtfulde elever af det arkane, nattenisserne nogensinde frembragte. Den korruption, der følger med sådanne studier, forvoldte stor skade på nattenisse-samfundet og påvirkede hele Azeroth... det ved du sikkert godt.\n\nJeg lovede Vagterne, at jeg ville befri åndene fra deres dødelige bånd, når jeg fandt dem. Hvis du gør det samme, er jeg sikker på, at jeg kan belønne dig en del.\n\nÅndene hjemsøger Skyggesangs Helligdom mod nordøst herfra.", p="Hvordan går din jagt på de Højfødte ånder, <Class>?\n\nMange ting har forvoldt stort lidelse for alle Azeroths racer, men af en eller anden grund synes disse ånder at være en pest for alle folkeslag. Måske skyldes det deres vedvarende begær efter arkan magi – og et sådant begær er et varsel om Den Brændende Legion, og vi ved, hvad det kan føre til.", c="Godt gået, <Class>. Tak for din hjælp. Åndene har fundet fred, og de trusler, som deres begær efter det arkane har skabt, er blevet mindre.\n\nJeg er sikker på, at begge sider af konflikten, der hærger Azeroth, vil se, at du står hævet over sådanne ting."},
  [5536] = {n="Et Land Fyldt med Had", l="Dræb 6 Haldarr-satyrer, 2 Haldarr-skælme og 2 Haldarr Ondsvorne, og vend derefter tilbage til Loh'atu ved grænsen til Askedalen.", d="Satyrerne, en vanskabt, ond skikkelse af nattenisserne, plager nu de hellige lande, som engang blev færdes af Cenarus. Jeg kan ikke tale for nattenisserne, hvad angår alle de grusomheder, de dæmoniske væsener har begået, men jeg har svoret Jordmoderen en ed om at hjælpe alferne med at rense landet for sådan en plage.\n\nJeg er sikker på, at du ville bevise dig selv, hvis du hjalp mig med at rense dem.\n\nMod nordøst herfra finder du Haldarr-klanen. Vend tilbage til mig, når du har prøvet dig selv mod deres magt.", p="Hvordan går kampen mod satyrerne, <Class>?\n\nEr de så stærke, som du troede? Stærkere? Eller var de måske intet for din egen styrke?", c="Godt gået, <Class>. Jeg ser, at du ikke blot er dygtig, men også snedig. At besejre sådanne væsener er et vidnesbyrd om din loyalitet over for Jordmoderens lærdomme, selvom du ikke anerkender hende som din egen gudinde. Hun er i alle ting på denne planet og ud over den. Hendes øjne, det ene mørkt og det andet lyst, bevæger sig altid over himlen og ser ned på os.\n\nTag venligst denne lille mængde mønter som tak for det, du har gjort."},
  [5537] = {n="Skeletfragmenter", l="Bring 15 Skeletfragmenter til Alkymist Arbinton ved Kuldevind-pegen i Vestlige Pestlande.", d="Nøglen til Skolomancen kaldes en Skeletnøgle. Den skal smedes af et skeletts rester – faktisk flere – og hærdes af de stærkeste metaller i en passende form. Et magtsegl fra et væsen, der naturligt kan åbne portalen til Skolomancen, vil få nøglen til at fungere til sidst.\n\nMen først og fremmest, <Name>. Vi skal bruge skeletfragmenter til nøglens smedning. Skeletter i Andorhøj burde give det, vi har brug for, men dem uden for murene kan måske også gøre det.", p="Så makabert det end lyder, skal vi bruge en god forsyning af passende skeletfragmenter til at lave det ydre lag af nøglen. De kalder den jo ikke en Skeletnøgle for ingenting, ved du.", c="Det her skal nok virke, <Name>! Nu er det min tur – jeg vil indgyde dem en passende hærdning, så de kan overleve den intense smedningsproces, de senere skal igennem.\n\nDet næste skridt bliver at skaffe en passende form til nøglen. Jeg kender en kobold-smed i Tanaris, som tidligere har lavet former til lignende makabre ting. Han arbejder for, hvem koboldere normalt arbejder for – den højeste bydende."},
  [5538] = {n="Skimmel rimer på...", l="Bring de indgydte skeletfragmenter og 15 guldmønter til Krinkle Godstål i Gadgetbyen.", d="Kobolden, du skal tale med, er Krinkle Godstål. Han sælger sine evner til den højeste bydende i Gadgetbyen, inde i Tanaris-ørkenen. Han er sandsynligvis den eneste, der kan lave den form, vi har brug for, og hans tjenester er ikke billige. Vi beder dig nu om at tage dybt op af lommen og betale det gebyr, han vil opkræve.\n\nJeg er alkymist, ikke bankmand. Havde jeg guld liggende, var jeg bestemt ikke her.\n\nJeg tror, jeg sagde den stille del højt igen. Ups.\n\nGadgetbyen venter på dig! Held og lykke!", p="Ja, jeg ved, hvem du er, og jeg ved, hvorfor du er her. Arbinton sendte mig besked, før du ankom. Lad os komme til sagen, skal vi?\n\nJeg har en form, du kan bruge til skeletnøglen, men den koster dig – femten guld, betalt på forhånd, ingen forhandling. Jeg pakker skeletfragmenterne ned i formen til dig, og jeg lærer dig også at smede nøglens skaft uden nogen kendskab til smedekunst... alt sammen gratis, vel at mærke.\n\nSig så, at lejesoldater ikke tilbyder konkurrencedygtige aftaler!", c="Arbinton sagde, at du ville levere varen, og det har du gjort! En aftale er en aftale; lad mig pakke fragmenterne ned i formen til dig.\n\nHar Arbinton allerede indgydt dem? Fortræffeligt... ellers ville det have været en lang tur tilbage til Kuldevind-pegen for dig."},
  [5542] = {n="Dæmonhundene", l="Slå 20 Pestjagthund-unger, 5 Pestjagthunde og 5 Rasende Pestjagthunde. Vend tilbage til Tirion Fordring, når opgaven er løst.", d="Hvis du vil blive her, beder jeg dig kun om at fortjene dit ophold. Der er mange plager, der trænger til en smule 'disciplin'.\n\nDu kan starte med pestjagthundene og deres unger.\n\nJeg kan ikke tilbyde meget igen, men du er garanteret et varmt måltid og lidt samvær, hvis du lykkes.", p="Ha' ikke medlidenhed med dæmonhundene, <Race>. De er vederstyggeligheder!", c="Godt gået, <Name>. Kom. Hvil dig. Lad os spise og tale om forgangne dage!"},
  [5543] = {n="Blodtonede Himle", l="Slå 30 Pestflagermus og vend tilbage til Tirion Fordring.", d="Ve dem, der tåbeligt vandrer ind i Pestlandene. Alle slags ufyr bor i disse skove – fra de fanatiske Skarlagenrøde Korstog, som vil dræbe enhver, der ikke bærer Korstogets mærke, til den morderiske Pest, der kun ser til at forøge deres rækker med flere udøde.\n\nSelv dyrelivet er blevet forvandlet til glubske, menneskeædende udyr. Jeg beder dig om at tilintetgøre dem, der vil slå ned fra himlen: Pestflagermusene.", p="Undervurder ikke de vingede skadedyr, <Race>. Pesten har givet dem overnaturlige evner.", c="Du er et lysende eksempel på anstændighed, <Race>! Det er længe siden, jeg har mærket heltes blod pulsere gennem mine årer. Dine modige handlinger er opmuntrende!"},
  [5544] = {n="Ådselslarvemad", l="Søg efter Ådselslarverne og Fortærerne i egnen. Dræb dem og høst deres kød. Vend tilbage til Tirion Fordring, når du har samlet 15 skiver ådselsormekød.", d="Mine madforsyninger er ved at slippe op, <Race>. Jeg skammer mig over at indrømme, at jeg måske ikke har nok mad til at dele med dig.\n\nKan du hjælpe en gammel mand med en simpel opgave? Her omkring er den eneste slags dyr, som pestens hærgen ikke har påvirket, ådselsormene. Selvom kødet er ret smagløst, kan det nemt konserveres, så det holder i månedsvis. Jeg skal bruge flere hundrede pund for at fylde op til den kommende vinter!", p="Du vil vænne dig til smagen, <Race>.", c="Må Lyset vogte over dig! Velsignet være du, unge."},
  [5561] = {n="Kodo-indsamlingen", l="Bring fem tæmmede kodoer og Kodo-omkombobulatoren tilbage til Smeed Skrabbelskrue ved Skrabbelskrues Lejr.", d="Bibbly tror, han er den eneste kobold i Desolace, der ved, hvordan man tjener penge. Nå, den eneste karavane, der er modig nok til at rejse i disse egne, er afhængig af mig. Siden jeg lærte at forynge og kontrollere gamle og døende kodoer med min kodo-omkombobulator, har karavanens ejer Kork, Tovmanden og jeg indgået et partnerskab.\n\nTag omkombobulatoren og brug den på enhver gammel, aldret eller døende kodo; den vil chokere dyret til en tæmmet kodo og tvinge det til at følge dig. Når du har fået tæmmet en kodo, skal du bringe den tilbage til mig.", p="Karavanen kommer snart; har du de fem nye tæmmede kodoer, jeg bad om?", c="<Smeed Skrabbelskrue begynder at tælle.>\n\nTre, fire og fem... fremragende, jeg bad om fem tæmmede kodoer, og jeg får fem tæmmede kodoer... Jeg skal være rig... ja, meget rig! Jeg håber at se Bibblys grønne ansigt, når han hører om min succes!"},
  [5581] = {n="Legionens Portaler", l="Forvis 6 Portaler i Mannorok-hekseriet, og vend tilbage til Taiga Klogmand i Skyggebytte-landsbyen.", d="Se – Irukos' Hånd. En makaber syn i sandhed.\n\nDu må besidde den, hvis dæmonportalerne i Mannorok-hekseriet skal forvises... hvilket er, hvad jeg nu beder dig om. Dæmontruslen vokser, og vi må lukke disse portaler for at standse strømmen af dæmoner til denne verden. Held og lykke, <Name>... og vær på vagt over for portalvogterne.", p="Har du forvist dæmonportalerne i Mannorok-hekseriet?", c="Du skal have ros, <Name>. Din indsats har hjulpet meget i kampen mod dæmontruslen, og hele Azeroth er tryggere takket være den."},
  [5601] = {n="Søster Pamela", l="Find Pamela Rødsti i Dårshire.", d="Jeg flygtede fra Herrelande under den store krig og var heldig at slippe væk, før Pesten fejede gennem mit hjemland og forvandlede det til en pestbefængt mare! Jeg var heldig, men min familie var det ikke. Jeg frygter, at de alle blev dræbt i slaget ved Dårshire.\n\nDårshire er en landsby i Østkongerigerne, indlejret i de sydlige bakker i det, der nu er de Østlige Pestlande. Vil du tage derhen og lede efter min familie? Jeg savner dem så meget, især min lillesøster Pamela.\n\nVær venlig at finde hende for mig!", c="Hvor er min søster Jessika? Hun forlod os for så længe siden, dengang jeg bare var en lille pige. Hun græd så meget, da hun gik. Jeg ved ikke, hvorfor hun græd! Måske faldt hun og ramte tåen.\n\nNår Jessika var her, legede vi lege og dansede og plukkede smukke blomster rundt om huset. Og nogle gange gemte vi os, når vi så far komme hjem, og så sprang vi frem og overraskede ham!\n\nKom tilbage, Jessika! Hvis du kommer tilbage, kommer far måske også, så vi kan lege sammen igen..."},
  [5621] = {n="Månens Beklædning", l="Find Vogter Shaya og hel hendes sår med Mindre Helbred (Rang 2). Derefter skal du give hende Kraftord: Sejhed og vende tilbage til Laurna Morgenlys i Dolanår.", d="Jeg har brug for din hjælp, <Name>. Jeg er nødvendig her for at træne de andre elever, men du kan hjælpe en af vores sårede vogtere lige syd for Dolanår. Hun blev såret under patruljering af byen og kunne bruge vores hjælp. Hendes navn er Shaya.\n\nNår du finder hende, skal du hele hendes sår og derefter styrke hendes krop med dine besværgelser. Det vil i det mindste beskytte hende mod skade i længere tid, hvis hun støder på problemer. Vend tilbage til mig her, når du har gjort din pligt over for Elunie.", p="Vores styrkende besværgelser er meget kraftfulde, Delor. De gør det muligt for vores ledsagere at tage yderligere skade fra alle slags angreb og overleve i situationer, hvor de ellers ville falde. Men det er intet sammenlignet med vores evner til at hele. Der er ingen større healere end en præst – husk det. Din kraft alene kan let vende kampens gang.", c="Du har gjort det godt, og du har tjent Elunie. For det takker jeg dig.\n\nVær venlig at tage denne kappe som tegn på min tak. Den betyder, at du har fortjent din plads blandt vores orden. Hvis du ønsker det, så bær den med stolthed, men uanset hvad vil vi altid anerkende dig som en af vores egne.\n\nGå med Elunie, <Name>, og tak."},
  [5622] = {n="Til Elunies Ære", l="Tal med Laurna Morgenlys i Teldrassil.", d="<Name>, du skal rejse til Dolanår, når dine ærinder her i Skyggedalen er gjort. Der finder du Laurna Morgenlys. Hun vil lære dig mere om Elunies veje, og det er hos hende, at du vil tjene din første beklædning, der markerer din stilling som præst af Elunie.\n\nVær forsigtig, og må du være beskyttet på dine rejser.", c="Jeg er glad for at se, at Shanda har sendt dig for at finde mig, <Name>. At lære unge præster Elunies veje giver mig stor tilfredsstillelse."},
  [5624] = {n="Lysets Beklædning", l="Find Vagt Robertsen og hel hans sår med Mindre Helbred (Rang 2). Derefter skal du give ham Kraftord: Sejhed og vende tilbage til Præstinde Josepa i Guldshire.", d="Normalt stiller jeg en lille udfordring for tilhængerne af Lyset for at teste deres evner. Jeg vil se, om de er værdige til at bære deres første kåber – et tegn på, at kirken udadtil godkender præsten og støtter ham.\n\nMen denne situation er lidt anderledes. En af Guldshires borgere så en såret vagt ved søen øst for her. Hans navn er Robertsen. Find ham, hel ham, styrk hans krop og vend tilbage hertil. Hvis du kan gøre det for mig, vil jeg anse din prøve for bestået.", p="Som du måske allerede har lært, er vores helende magi afgørende for vores folks overlevelse i disse hårde tider – især for eventyrere og helte, der tager til våben og magi for at kæmpe mod så mange forskellige trusler.\n\nDu vil gøre klogt i altid at huske, hvor vigtig den færdighed er. Det, sammen med Sejhed, gør dine ledsagere langt dygtigere i kamp, da de kan holde til et større antal slag.\n\nLad ingen afvise, hvor kraftfulde dine magier er.", c="Fortræffeligt, <Name>! Med endnu en sund vagt derude til at hjælpe byen bliver vi endnu tryggere. Jeg er glad for at se, at du allerede lærer at bruge dine evner klogt. Hvis du føler dig klar til mere træning på et hvilket som helst tidspunkt, så kom tilbage til mig. Men for nu: tag denne kåbe. Den lader andre vide, at du er en af vores orden. Hvis du ikke ønsker at bære den, er det fint. Senere vil der være flere prøver, og til dem er kåben ikke nødvendig."},
  [5627] = {n="Elunes Stjerner", c="Du har bevist dig værdig til Elunies opmærksomhed, <Name>. Hvis du føler dig klar, vil jeg meget gerne lære dig en af hendes besværgelser, som er unik for vores folk."},
  [5628] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="Ah, ja, hej, <Name>? Jeg er glad for, at du standsede op for at tale et øjeblik. Du er langt hjemmefra i så ung en alder – jeg beundrer den ambition. Jeg ønskede, at jeg dengang, da jeg var yngre, havde haft modet til at rejse verden rundt.\n\nDer var for nylig en præstinde af din orden her og ledte efter dig. Hun sagde, det var meget presserende, at du vendte tilbage til Månens Tempel i Darnassos og talte med Præstinde Alathea – det havde noget at gøre med din træning. Jeg ville ikke tøve for længe, hvis du kan undgå det.", c="Vidunderligt, du er vendt hjem, <Name>. Det glæder altid Tyrande og mig, når dem, vi har trænet, drager ud i verden og vender sikkert tilbage til os. Hvordan har det været med dig? Velsigner Elunie stadig dine rejser? Måske kan du, efter vi har talt mere om den sag, der er på færde, fortælle mig mere om dine rejser."},
  [5629] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="Hej igen, <Name>. Jeg ved, du har været travl med at hjælpe vores folk, men du må også tage dig lidt tid til dig selv. Præstinde Alathea sendte nogen her for at lede efter dig. Det ser ud til, at du har fanget vores ældstes opmærksomhed, og de mener, at du er klar til større ting. Gå til Månens Tempel i Darnassos og led efter Alathea der. Hun vil vente. Held og lykke, og må Elunie være med dig.", c="Vidunderligt, du er vendt tilbage, <Name>. Det glæder altid Tyrande og mig, når dem, vi har trænet, drager ud i verden og vender sikkert tilbage til os. Hvordan har det været med dig? Velsigner Elunie stadig dine rejser? Måske kan du, efter vi har talt mere om den sag, der er på færde, fortælle mig mere om dine rejser."},
  [5630] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="Hej der, lille ven. Godt at se dig rejse vidt og bredt til fjerne lande. Ikke at det skal lyde ondt, men mange af jeres slags tåler ikke disse kolde klimaer særlig godt. Dejligt at se, at du er lavet af hårdere stof.\n\nFor ikke længe siden var en af dine præstinder herinde og ledte efter dig – sagde noget om, at du skulle finde en Præstinde Alathea i Månens Tempel tilbage i Darnassos. Sagde, det var vigtigt, og at du skulle tage tilbage dertil snart.", c="Vidunderligt, du er vendt hjem, <Name>. Det glæder altid Tyrande og mig, når dem, vi har trænet, drager ud i verden og vender sikkert tilbage til os. Hvordan har det været med dig? Velsigner Elunie stadig dine rejser? Måske kan du, efter vi har talt mere om den sag, der er på færde, fortælle mig mere om dine rejser."},
  [5631] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="En præstinde besøgte for nylig vores haller og ledte efter dig, unge <Race>. Hun sagde, at hun var på en mission for at finde dig, og at du skulle vende tilbage til Månens Tempel i Darnassos så hurtigt som muligt. Når du kommer frem, så led efter en Præstinde Alathea – hun vil fortælle dig mere.\n\nLyset være med dig, <Name>.", c="Vidunderligt, du er vendt hjem, <Name>. Det glæder altid Tyrande og mig, når dem, vi har trænet, drager ud i verden og vender sikkert tilbage til os. Hvordan har det været med dig? Velsigner Elunie stadig dine rejser? Måske kan du, efter vi har talt mere om den sag, der er på færde, fortælle mig mere om dine rejser."},
  [5632] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="Åh, ja, selvfølgelig. Hej, <Name>. En budbringer fra vores orden var her for ikke så længe siden og ledte efter dig. Hun nævnte, at noget vigtigt var ved at ske i Darnassos, og at du skulle vende tilbage til Månens Tempel, så snart du kan. Når du kommer frem, så tal med Præstinde Alathea. Jeg tror, det har noget at gøre med, at du gør så gode fremskridt på vores måder.\n\nVend tilbage til Darnassos, når du kan.", c="Vidunderligt, du er vendt hjem, <Name>. Det glæder altid Tyrande og mig, når dem, vi har trænet, drager ud i verden og vender sikkert tilbage til os. Hvordan har det været med dig? Velsigner Elunie stadig dine rejser? Måske kan du, efter vi har talt mere om den sag, der er på færde, fortælle mig mere om dine rejser."},
  [5633] = {n="Hjemkomst", l="Tal med Præstinde Alathea i Darnassos.", d="Hilsner, lille ven. Godt at se dig her i vores store haller. Må velsignelsen være med dig og dit folk.\n\nMens du rejste gennem vores lande, kom en præstinde fra dit tempel hertil og ledte efter dig. Hun sagde, at du skulle vende tilbage til Månens Tempel så hurtigt som muligt. Jeg beklager, at jeg ikke kan fortælle dig mere, men det lød vigtigt. Når du kommer til templet, så tal med en Præstinde Alathea.", c="Dejligt, du er vendt hjem, <Name>. Det glæder altid Tyrande og mig, når dem vi har oplært drager ud i verden og vender sikkert tilbage til os. Hvordan har det været for dig? Velsigner Elune stadig dine rejser? Måske kunne du, efter vi har talt mere om det forestående ærinde, fortælle mig mere om dine rejser."},
  [5634] = {n="Desperat Bøn", c="Du har gjort Let en stor tjeneste ved at blive et lysende eksempel for dem, der rejser i disse farlige lande og videre. Modtag venligst denne lektion som tak for alt, du har gjort."},
  [5635] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="Du har fanget vores overordnedes opmærksomhed, <Name>. De har bedt dig om at rejse til Lysets Katedral i Stormvind så hurtigt som muligt. Tilsyneladende mener de, at du allerede har bevist dig selv og er klar til at videreudvikle din oplæring. Når du kommer frem, skal du finde Højpræstinde Laurena. Hun kan vejlede dig videre. Held og lykke, og må Let være med dig.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5636] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="Elune velsigne dig, gode <Race>. Jeg håber, dit Let finder dig og beskytter dig godt i dag.\n\nEn af dine præster var her for ikke længe siden og ledte efter dig. Han nævnte, at du skulle vende tilbage til Lysets Katedral så hurtigt som muligt for at tale med Højpræstinde Laurena. Det lader til, at du har gjort det godt, siden du har fanget sådan en opmærksomhed. Jeg ville ikke bruge for meget tid her – dit folk har brug for dig.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5637] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="Tiden er kommet, til du skal af sted til Stormvind, <Name>. Højpræstinde Laurena i Lysets Katedral vil tale med dig. Der må være noget virkelig godt eller virkelig skidt på færde, siden Højpræstinden personligt vil have dig derhen, men jeg gætter på, at du kun har gjort det godt for dig selv, og det er en god ting, at hun vil tale med dig.\n\nMen spild ikke for meget tid her omkring. Jeg ville tage derhen, så snart du kan.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5638] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="For et kort stykke tid siden var en af dine præster her og ledte efter dig, <Race>. Han sagde, at hvis jeg så dig, skulle jeg henvise dig til Lysets Katedral. Han sagde, det var meget vigtigt, men jeg skulle ikke være alt for bekymret, hvis jeg var dig. Hans væsen virkede positivt... som om det var gode nyheder. Jeg ville ikke tage for lang tid om at komme derhen, hvis jeg var dig.\n\nMåtte Elune være med dig, gode <Race>.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5639] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="Du er efterspurgt i Stormvind, <Name>. Højpræstinden dér, Laurena, siger, at det er tid for dig at bevise, at du er værdig til næste niveau af din oplæring. Spild ikke for meget tid på at finde vej dertil. Du finder hende i Lysets Katedral midt i byen. Hils hende fra mig, og bevis, hvor værdig du er til et sådant kald. Må Let være med dig, <Name>.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5640] = {n="Desperat Bøn", l="Tal med Højpræstinde Laurena i Stormvind.", d="Lov være Elune og dit Let, <Name>.\n\nOmkring nu lærer mange af vores orden evner, der afspejler deres tro på Elune. Hvis jeg husker rigtigt, gælder det samme for din orden også.\n\nNår dine ærinder i Darnassos er afsluttet, ville jeg søge en af dine Højpræstinder for videre oplæring.", c="Jeg er glad for, at du er ankommet, <Name>. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring i Lettets veje.\n\nDer er lektioner, alle Lettets tjenere må lære. Hvis du er klar, begynder vi at tale om nogle af dem nu."},
  [5641] = {n="En Mangel på Frygt", c="Du har det i dig til at blive en stor <Class>, <Name>. Bliv ved med det gode arbejde!\n\nDu har allerede vist, at du er klar til kamp. Måske er det på tide, vi lærer dig lidt mere, din knægt."},
  [5642] = {n="Skyggevagt", l="Tal med Ur'kjo i Orgrimmar.", d="Noget vigtigt er på færde i Orgrimmar, <Name>.\n\nDe sædvanlige budbringere, der kommer forbi her og leder efter trollepræster, plejer at være meget afslappede. Denne gang virkede de langt mere travlt optaget. Dvæl ikke for længe i Tordenklippe. Jeg ville vende tilbage til Ånders Dal så hurtigt som muligt.", c="Dine riter kommer snart nok. Indtil da lærer jeg dig en besværgelse, der vil være af stor nytte, når du kæmper mod dine fjender."},
  [5643] = {n="Skyggevagt", l="Tal med Ur'kjo i Orgrimmar.", d="Ligesom mange af vores egne præster sætter din egen stamme dig igennem overgangsriter. Disse riter lærer ofte præster særlige evner, som er afgørende for deres overlevelse. Jeg fornemmer, at tiden er ved at være inde, selv mens vi taler. Du skal vende tilbage til Ånders Dal i Orgrimmar og tale med Ur'kjo. Det, han lærer dig, kan være meget vigtigt for fremtiden.", c="Dine riter kommer snart nok. Indtil da lærer jeg dig en besværgelse, der vil være af stor nytte, når du kæmper mod dine fjender."},
  [5644] = {n="Fortærende Pesten", l="Tal med Æltalyste i Undergrunden.", d="Ah, en vidunderlig dag for dig, <Name>. Jeg kan se på de lektioner, du har lært, at tiden er kommet til at sende dig tilbage til Æltalyste. Der er ting, kun hun kan lære dig, og selv da kun hvis du beviser din værdi.\n\nJeg vil ikke fortabe overraskelsen for dig, men jeg husker, da jeg var en ung præst, der lærte om ægte kraft... guddommelig kraft. Ja, det var dage.\n\nGå tilbage til Æltalyste i Undergrunden, <Name>. Hun venter på dig i Krigskvarteret.", c="Jeg ville lære dig Fortærende Pesten, hvis du føler dig klar, <Name>. En besværgelse med ikke ringe kraft, den vil hjælpe dig i de kommende slag. Øv dig med den – der kommer prøver senere."},
  [5645] = {n="Mangel på Frygt", l="Tal med Højpræst Rolandsen i Jernsmede.", d="<Name>, din Højpræst Rolandsen ønsker en audiens hos dig i Jernsmede. Skynd dig, min stærke ven, din næste prøve nærmer sig hastigt. Selvom jeg ønsker, at jeg kunne overvære dit eget væddeløbs særlige riter, er mit sted her. Men må Let følge dig på dine rejser. Rolandsen burde stadig være i Mystiske Afdeling, når du når byen. Han venter.", c="Godt, du er kommet, <Name>. Vores væddeløb er stolt og stærkt, og det er tid til, at du lærer ikke blot selv at være sådan, men også at vække samme følelse og tillid hos andre. Er du klar, knægt?"},
  [5647] = {n="Mangel på Frygt", l="Tal med Højpræst Rolandsen i Jernsmede.", d="Dit væddeløb er så utroligt stærkt, <Name>. Vi er stolte af at kalde jer allierede. Og for hver dags solnedgang kommer du og dine frænder tættere på ikke blot at finde jeres sande oprindelse, men også på stor tillid til, at I er på den rette vej i så mange ting. Den følelse må få dig til at føle dig så triumferende.\n\nBudskabet kom fra Jernsmede for nylig. Det bad om, at du vendte tilbage dertil og talte med Højpræst Rolandsen i Mystiske Afdeling. Jeg ville ikke lade ham vente. Må Elune guide dine rejser.", c="Du har det i dig til at blive en stor <Class>, <Name>. Bliv ved med det gode arbejde!\n<Name>Du har allerede vist, at du er klar til kamp. Måske er det på tide, vi lærer dig lidt mere, din knægt."},
  [5650] = {n="Mørkets Beklædning", l="Find Dødevagt Kjel og helbred hans sår med Mindre Helbred (Rang 2). Derefter skal du give ham Kraftord: Sejhed og vende tilbage til Mørk Gejstlig Beryl i Gryde-by.", d="Vores magt kommer fra mørke og skygge, <Name>, men det er ikke din eneste rolle. Du har erkendt, at der er værdi i at kende helbredelseskunsten. Det er klogt. Men før du kan kende mørket, må du også kende lyset. Og til dette har jeg en prøve til dig.\n\nNord for kirkegården ligger en såret Dødevagt – Dødevagt Kjel. Han har beskyttet os mod gnoller i nogen tid og har brug for heling. Men du må også styrke hans krop, før han kan vende tilbage til tjeneste. Gør begge dele med dine besværgelser, og vend derefter tilbage til mig.", p="Vores kræfter gør os ideelle til så mange situationer, <Name>. Du vil opdage, at uanset hvad, er vores evne til at hele sår og øge den skade, vores kammerater kan tåle, altid de mest eftertragtede talenter, vi har adgang til. Lad dig ikke afskrække fra at forfølge andre veje som en <Class> – du kan være effektiv på mange måder. Men... hvis du virkelig ønsker at tilintetgøre dine fjender med magisk energi, er det måske arkanet, du foretrækker.", c="Du har bestået min prøve med lethed. Godt.\n\nSnart vil du være klar til at tage mere ansvar, og den vej fører til mørkere kræfter – kræfter, som ingen <Class> af en anden race har.\n\nTag denne kåbe som et tegn på din stand. Du har fortjent den. Hvis du ikke ønsker at bære den, så være det, du må gøre med den, som du vil. Jeg og andre som os vil altid anerkende dig for det, du har opnået i vores rækker."},
  [5651] = {n="I Mørkets Gunst", l="Tal med Mørk Gejstlig Beryl i Tirisfals Lysninger.", d="Der er mange lektioner, som De Forladte har lært gennem erfaring – ting, som nogle racer kun begynder at fatte. Og selvom vores vej ligger i mørket, vil du opdage, at rigtig mange ting hviler på både lyset og mørket. Dine lektioner skal lære dig at bruge begge... og med omtanke. Men hør mine ord: glem aldrig, at vi blev smedet i korruption og efterladt til at rådne som et lig. Mørket er vores hjem.\n\nSøg Mørk Gejstlig Beryl i Gryde-by, når du er klar til at lære mere.", c="Endelig er du kommet. Din tro alene vil ikke lade dig passere de prøvelser, der venter dig, unge. En følelse af hastværk og lidt ambition vil også hjælpe."},
  [5652] = {n="Forbandelse af Svaghed", c="Du gør klogt i at tage denne lektion til dig, unge. Forbandelse af Svaghed vil blive en stor fordel for dig i kamp. Senere har jeg prøver til dig, så du kan udvikle dig selv og bevise din værdi for stammen."},
  [5655] = {n="Forbandelse af Svaghed", l="Tal med Ur'kjo i Orgrimmar.", d="Jeg er sendt her for at sikre, at du ikke vandrer for langt hjemmefra, <Name>. De sender mig for at sikre, at du vender hjem, for Ur'kjo, vores største præst, vil tale med dig. Du går derhen. Du går til Ånders Dal i ork-byen og taler med Ur'kjo. Han venter på dig nu.", c="Du gør klogt i at tage denne lektion til dig, unge. Forbandelse af Svaghed vil blive en stor fordel for dig i kamp. Senere har jeg prøver til dig, så du kan udvikle dig selv og bevise din værdi for stammen."},
  [5656] = {n="Forbandelse af Svaghed", l="Tal med Ur'kjo i Orgrimmar.", d="Det varmer altid mit udøde hjerte at se præster fra alle kulturer vandre rundt i verden. At vide, at der findes kraft, som ikke er arkan, og som ligger inden for vores rækkevidde. Derfor er det min ære at lede dig hjem, <Name>.\n\nUr'kjo, din store præst i Orgrimmar, har bedt om din tilstedeværelse. Du finder ham i Ånders Dal.", c="Du gør klogt i at tage denne lektion til dig, unge. Forbandelse af Svaghed vil blive en stor fordel for dig i kamp. Senere har jeg prøver til dig, så du kan udvikle dig selv og bevise din værdi for stammen."},
  [5657] = {n="Forbandelse af Svaghed", l="Tal med Ur'kjo i Orgrimmar.", d="Hjem. Vend hjem, unge <Race>.\n\nDin åndelige leder Ur'kjo beder dig vende tilbage til ham og tale om den vej, du rejser.\n\nGå til Ånders Dal i den store Horde-by Orgrimmar. Du vil finde ham der.", c="Du gør klogt i at tage denne lektion til dig, unge. Forbandelse af Svaghed vil blive en stor fordel for dig i kamp. Senere har jeg prøver til dig, så du kan udvikle dig selv og bevise din værdi for stammen."},
  [5658] = {n="Svaghedens Berøring", c="Ah, unge <Class>, jeg er glad for, at du er vendt tilbage hertil. Jeg vil lære dig en lektion, du gør klogt i ikke at glemme. Er du klar?"},
  [5659] = {n="Svaghedens Berøring", l="Tal med Æltalyste i Undergrunden.", d="Dette er ikke stedet for dig, <Name>. Du bør tage til Krigskvarteret i Undergrunden så hurtigt som muligt. Æltalyste har kaldt alle sine præster og præstinder dertil, så snart de er klar. Det er tid, at de lærer mere om deres kraft, og hvordan de tæmmer den.\n\nHun vil ikke tolerere sen ankomst eller undskyldninger, så du gør klogt i at komme af sted.", c="Ah, godt, endnu en er ankommet. Tid betyder måske ikke noget for mig, men for dig er den af afgørende betydning. Der er meget, du skal lære, og der er meget, jeg ønsker at lære dig. Du må blot bevise din værdi. Gør du det, vil du blive rigeligt belønnet."},
  [5660] = {n="Svaghedens Berøring", l="Tal med Æltalyste i Undergrunden.", d="Du er langt hjemmefra, <Class>. Du er brug for dernede, tilbage i din by under jorden. Din herskerinde, hende du kalder Æltalyste, har brug for dig dér. Ligesom min stamme er der ting, du kun må lære af hende. Bliv ikke her for længe. Du bør tage til Krigskvarteret så hurtigt som en zeppelin kan føre dig.", c="Ah, godt, endnu en er ankommet. Tid betyder måske ikke noget for mig, men for dig er den af afgørende betydning. Der er meget, du skal lære, og der er meget, jeg ønsker at lære dig. Du må blot bevise din værdi. Gør du det, vil du blive rigeligt belønnet."},
  [5661] = {n="Svaghedens Berøring", l="Tal med Æltalyste i Undergrunden.", d="Du er langt hjemmefra her ude i Blodhov-landsbyen, <Name>. Jeg er sendt hertil for at finde præster af min egen stamme og sende dem tilbage for at tale med vores ledere, men det betyder ikke, at jeg ikke også kan hjælpe dig.\n\nJeg hører, at din øverste præstinde-ånd ønsker, at alle De Forladte kommer til hende – der er ting, du må lære.\n\nGå og mød Æltalyste i Krigskvarteret i den by af din.", c="Ah, godt, endnu en er ankommet. Tid betyder måske ikke noget for mig, men for dig er den af afgørende betydning. Der er meget, du skal lære, og der er meget, jeg ønsker at lære dig. Du må blot bevise din værdi. Gør du det, vil du blive rigeligt belønnet."},
  [5662] = {n="Svaghedens Berøring", l="Tal med Æltalyste i Undergrunden.", d="Min respekt til dig og dit folk, <Name>. Jeg lærer normalt kun dem af min egen stamme. Dine lektioner kommer fra Æltalyste i byen, der engang hed Herrelande.\n\nDu bør vende tilbage til hende, hvis du skal lære de evner, der adskiller dig fra andre trosretninger.\n\nGå til Krigskvarteret i Undergrunden og find din herskerinde der.", c="Ah, godt, endnu en er ankommet. Tid betyder måske ikke noget for mig, men for dig er den af afgørende betydning. Der er meget, du skal lære, og der er meget, jeg ønsker at lære dig. Du må blot bevise din værdi. Gør du det, vil du blive rigeligt belønnet."},
  [5663] = {n="Svaghedens Berøring", l="Tal med Aelthalyste i Underbyen.", d="Aelthalyste har sendt bud til alle sine præster. Vi skal sende de yngre af vores orden til Underbyen for mere træning. Hvis du virkelig regner dig blandt de trofaste, så bør du også vende tilbage dertil.\n\nDu kan finde Aelthalyste i Krigskvarteret dybt nede i Underbyen.", c="Ah, godt, endnu en er ankommet. Tid betyder måske ikke noget for mig, men for dig er den af største vigtighed. Der er meget, du skal lære, og meget, jeg gerne vil lære dig. Du må simpelthen bevise din værdi. Gør du det, skal du få en stor belønning."},
  [5672] = {n="Elunes Nåde", c="Ved at hengive dig til Elune og vores folk har du opnået en tilstand, som ikke alle af os kan nå. Det er tradition, at du derefter lærer endnu større evner som belønning for din hengivenhed. Vil du acceptere?"},
  [5674] = {n="Elunes Nåde", l="Tal med Præstinde Alathea i Darnassos.", d="En herlig dag er oprundet, <Name>. Du er nået dertil, hvor vores præster bliver oplært i evner, som kun nattealferne kender. Men det er ikke op til mig at oplære dig. Du skal vende tilbage til Månetemplet og tale med Præstinde Alathea, så snart dit ærinde her er afsluttet. Hun vil prøve dig for at sikre, at du er klar, og først da vil hun lære dig Elunes Nåde.", c="Ved at hengive dig til Elune og vores folk har du opnået en tilstand, som ikke alle af os kan nå. Det er tradition, at du derefter lærer endnu større evner som belønning for din hengivenhed. Vil du acceptere?"},
  [5675] = {n="Elunes Nåde", l="Tal med Præstinde Alathea i Darnassos.", d="Tiden løber, knægt. Det er tid for dig at vende hjem til Darnassos. Præstinde Alathea har sendt bud hertil om, at du skal vende tilbage dertil for at blive oplært. Det ser ud til, at de mener, du er klar til at blive prøvet ligesom dem, der tjener Lyset. Du bør tage afsted, så snart du kan. Alatheas budskab sagde, at hun vil vente på dig i Månetemplet. Held og lykke.", c="Elune velsigne dig, fordi du vendte tilbage til os så hurtigt. Dette er en vigtig tid i din oplæring, og en tid som hele vores orden tager meget alvorligt. Når du har hvilet efter din rejse hertil, så lad mig venligst vide det. Så kan vi drøfte fortsættelsen af din oplæring, og hvor din vej fører dig hen herefter."},
  [5676] = {n="Arkan Tilbagekobling", c="Vi var nødt til at lære nogle magier for at beskytte os mod det, man almindeligvis kalder vores største fjende: det arkane.\n\nJeg vil lære dig en besværgelse, der kan hjælpe dig med at forsvare dig selv og dine ledsagere mod dem, der ville svinge sådan en magt."},
  [5677] = {n="Arkan Tilbagekobling", l="Tal med Højpræstinde Laurena i Stormvind.", d="Så gerne som jeg vil vise dig vores egne særlige lærdomme om Lyset, så er det ikke vores sted. Dit sted er tilbage i Stormvind hos dine egne, <Name> ... for nu. Tro mig, jeg mener ingen krænkelse. Når du vender tilbage til Højpræstinde Laurena i Lysets Katedral, vil du forstå, hvad jeg taler om - tiden er kommet, til at din race forbereder dig på fremtiden; til at skille dig ud fra andre, der følger en lignende vej.", c="Ah, du har et herligt timing, <Name>. Jeg begyndte at undre mig over, om alle mine budbringere havde haft succes. Jeg er glad for at se, at de havde det, for ellers ville jeg vædde på, at du stadig var ude i verden og lærte mere om alle de trusler, der findes mod vores folk.\n\nEr du klar? Klar til mere træning, mener jeg. Du vokser i kraft hurtigere, og jeg føler, at du er klar til at lære mere om vores tro."},
  [5678] = {n="Arkan Tilbagekobling", l="Tal med Højpræstinde Laurena i Stormvind.", d="Det er tid for dig at vende tilbage til Stormvind, unge. Dine overordnede dernede har kaldt dig tilbage til mere træning. Og selvom det forstyrrer mig en smule, så er din race og min allierede, og jeg vil ikke svigte det.\n\nJeg mener ikke at være så hemmelighedsfuld over for dig - min mistillid til arkane magier, uanset om de er guddommeligt inspirerede eller ej, sidder stadig dybt i mig.\n\nDu vil forstå, hvad jeg taler om, når du er vendt tilbage til din Lysets Katedral. Tal med Højpræstinde Laurena, når du ankommer.", c="Ah, du har et herligt timing, <Name>. Jeg begyndte at undre mig over, om alle mine budbringere havde haft succes. Jeg er glad for at se, at de havde det, for ellers ville jeg vædde på, at du stadig var ude i verden og lærte mere om alle de trusler, der findes mod vores folk.\n\nEr du klar? Klar til mere træning, mener jeg. Du vokser i kraft hurtigere, og jeg føler, at du er klar til at lære mere om vores tro."},
  [5679] = {n="Fortærende Pesten", c="Jeg ville lære dig Fortærende Pesten, hvis du føler dig klar, <Name>. En besværgelse af ikke ringe kraft, den vil hjælpe dig i de kommende kampe. Øv dig med den - der kommer prøver senere."},
  [5680] = {n="Skyggevagt", c="Dine ritualer kommer snart nok. Indtil da lærer jeg dig en besværgelse, der vil være af stor nytte for dig, når du kæmper mod dine fjender."},
  [5713] = {n="Ét Skud. Ét Dræb.", l="Beskyt Vagt Aynasja, og tal derefter med Onaja ved Maestras Post i Askedalen.", d="Jeg var på rejse til Auberdin med et vigtigt budskab, da jeg blev angrebet af pelsbolgen Marosj og hans sporere. Under angrebet blev jeg forgiftet, og det efterlod mig knap nok i stand til at stå. Jeg kan lave et modgift, men det vil tage tid, før det er klar.\n\nJeg vil bede dig om at forsvare mig, indtil jeg kan tage modgiften. Jeg vil hjælpe dig så godt jeg kan med min bue.\n\nHvis vi overlever, kan jeg levere mit budskab til Auberdin, mens du taler med Onaja ved Maestras Post og fortæller hende om denne hændelse.", p="Har du set Vagt Aynasja på vejen? Hun tog af sted på en vigtig mission, men hun er endnu ikke vendt tilbage.", c="Du bringer de allerbedste nyheder, <Class>. Det er godt at høre, at Aynasja er i live og vel, takket være dig. Jeg håber, at du vil acceptere en belønning for din tapperhed. Må Elune våge over dig og lyse din vej."},
  [5721] = {n="Slaget ved Dårshire", l="Placér Relikviebundtet på Dårshires torv.\n\nForhindr Davil Lysilds død, indtil Hørgus dør.\n\nForhindr Kaptajn Rødstis død, indtil Rødsti den Korrumperede dukker op.\n\nBesejr Rødsti den Korrumperede.\n\nTal med Josef Rødstis ånd, når han dukker op på torvet, og tal derefter med Pamela i hendes hjem.", d="Nu, <Name>, skal du deltage i slaget ved Dårshire, og du skal redde Josef Rødsti.\n\nPlacér dette relikviebundt på Dårshires torv, så vil Dårshires ånder rejse sig. Deltag i deres kamp og sørg for, at disse to ting sker: Davil må overleve Hørgus' død, og Rødsti må overleve, indtil han bliver korrumperet og derefter besejret.\n\nEfter at have besejret den korrumperede Rødsti, vil hans ånd blive frelst. Tal med ham, og vend derefter tilbage til hans datter Pamela.", p="Jeg tror, jeg hørte spøgelser udenfor. De hvisker skumle ting til mig ...", c="Kampen er forbi! Jeg hørte min far hviske til mig. Han skræmte alle spøgelserne væk, og han siger, at han er på vej hjem! Jeg er så glad!\n\nHan sagde også, at jeg skulle byde dig velkommen, hvis du kom til vores hus, så jeg lavede te!\n\nJeg håber, du kan lide masser af sukker!"},
  [5742] = {n="Forløsning", l="Lyt til, hvad Tirion Fordring har at sige.", d="Du har arbejdet hårdt, ven. Hvil dine trætte knogler, og lad mig præsentere mig ordentligt.", p="Værsgo, ven; sid ned og hør min historie.", c="Fordring-forløsningen bliver en svær opgave. Er du klar?"},
  [5781] = {n="Om Glemte Minder", l="Rejs til Underkrypten - i den sydligste del af de østlige Pestlande - og hent Taelans Hammer. Vend tilbage til Tirion Fordring, når dit mål er opnået.", d="For at hjælpe Taelan med at genvinde det, han har mistet, må du samle genstande fra hans fortid.\n\nDen første sådan genstand er et legetøj, som jeg gav ham på hans 7. fødselsdag. Det var hans mest elskede eje: en miniature-krigshammer, en nøjagtig kopi af min egen!\n\nEfter at jeg var blevet forvist for forræderi, fortalte hans mor ham, at jeg var død. Han blev ført til min falske grav i Underkrypten, hvor han begravede hammeren sammen med min erindring - for altid.\n\nDu må drage til Underkrypten og hente Taelans hammer.", p="Han må forløses.", c="<Tirion blinker for at holde tårerne tilbage.>\n\nDet var skæbnen, at vi mødtes, <Name>. Du har velsignet mig med din venlighed."},
  [5801] = {n="Smedet i Ildfjer", l="Tag Skeletnøgle-støbeformen og 2 Thoriumstænger til toppen af Ildfjer-højderyggen i Un'Goro-krateret. Brug Skeletnøgle-støbeformen ved lavasøen for at smede den ufærdige Skeletnøgle.\n\nBring den ufærdige Skeletnøgle til Alkymist Arbinton ved Kuldevind-pegen i de vestlige Pestlande.", d="Du har brug for to stænger thorium og en kraftigt varm varmekilde for at smede nøglestilken. Thoriumet må du selv skaffe, men varmen kan jeg hjælpe med.\n\nMod vest i Un'Goro-krateret ligger Ildfjer-højderyggen - en pulserende vulkan. Lavasøen deroppe er varm nok til at smelte thorium og knogle sammen. Dit guld har købt dig en støbeform, som blot kræver, at du dypper den i søen deroppe; lavaen klarer resten.\n\nDet er alt fra min side. For at færdiggøre din nøgle må du tale med Arbinton igen.", p="Har du den færdige stilk til skeletnøglen? Jeg er ked af, at du måtte bære det meste af udgiften til støbeformen, men vi må alle gøre vores del for at modarbejde Svøben. Når du rækker mig den ufærdige nøgle, er du klar til den sidste genstand, der skal til for at fuldende den.\n\nDet bliver slet ikke let, men det arbejde, du har udført indtil nu for at forberede et angreb på Andorhøj, vil nu begynde at betale sig selv. Du får se.", c="Vi har fået en ganske dyr skeletnøgle dér, ikke sandt, <Name>? Alligevel er den stadig ufærdig; nu er tiden kommet til at lægge kraft bag vores skabelse. Til det formål skal du møde den ultimative fjende, som vi har arbejdet hen imod at møde i Andorhøj ... det skumle væsen, der trækker trådene inde i de ruinerede bymure.\n\nJeg taler om Araj Fremkalderen - en lich og et af de mest magtfulde væsner, som Svøben kalder sit eget."},
  [5802] = {n="Smedet i Ildfjer", l="Tag Skeletnøgle-støbeformen og 2 Thoriumstænger til toppen af Ildfjer-højderyggen i Un'Goro-krateret. Brug Skeletnøgle-støbeformen ved lavasøen for at smede den ufærdige Skeletnøgle.\n\nBring den ufærdige Skeletnøgle til Apoteker Tøvers ved Bolværket i de vestlige Pestlande.", d="Du har brug for to stænger thorium og en kraftigt varm varmekilde for at smede nøglestilken. Thoriumet må du selv skaffe, men varmen kan jeg hjælpe med.\n\nMod vest i Un'Goro-krateret ligger Ildfjer-højderyggen - en pulserende vulkan. Lavasøen deroppe er varm nok til at smelte thorium og knogle sammen. Dit guld har købt dig en støbeform, som blot kræver, at du dypper den i søen deroppe; lavaen klarer resten.\n\nDet er alt fra min side. For at færdiggøre din nøgle må du tale med Tøvers igen.", p="Har du den færdige stilk til skeletnøglen? Jeg er virkelig ked af, at du måtte bære det meste af udgiften til støbeformen, men vi må alle gøre vores del for at modarbejde Svøben. Når du rækker mig den ufærdige nøgle, er du klar til den sidste genstand, der skal til for at fuldende den.\n\nDet bliver slet ikke let, men det arbejde, du har udført indtil nu for at forberede et angreb på Andorhøj, vil nu begynde at betale sig selv. Du får se.", c="Vi har fået en ganske dyr skeletnøgle dér, ikke sandt, <Name>? Alligevel er den stadig ufærdig; nu er tiden kommet til at lægge kraft bag vores skabelse. Til det formål skal du møde den ultimative fjende, som vi har arbejdet hen imod at møde i Andorhøj ... det væsen, der trækker trådene inde i de ruinerede bymure.\n\nJeg taler om Araj Fremkalderen - en lich og et af de mest magtfulde væsner, som Svøben kalder sit eget."},
  [5803] = {n="Arajs Basse", l="Dræb Araj Fremkalderen og bring Arajs Basse til Alkymist Arbinton ved Kuldevind-pegen i de vestlige Pestlande.", d="Araj Fremkalderen hersker over Andorhøj fra den ruinerede bys hjerte. Vi ved, at han var den tidligere leder af Skolomance, før han gjorde byen til sin egen. For at færdiggøre nøglen skal vi bruge hans signet - kaldet en basse - monteret som nøglens hoved.\n\nBan dig vej ind i hjertet af Andorhøj, og bryd hans greb om byen nu, hvor han er lokket ud i det åbne. Når han er ødelagt, skal du rive hans basse ud af hans faldne fylakterium!\n\nNøglen til Skolomance venter, <Name>!", p="Du er kommet så langt, <Name> - kun ødelæggelsen af Araj Fremkalderens fysiske skikkelse vil give os midlerne til at færdiggøre nøglen. Skaf Arajs basse på enhver tænkelig måde, og bring den til mig - jeg vil smelte den fast som nøglens hoved.", c="Ja, det er den! Jeg ... igen, jeg er helt forbløffet over dit heltemod. Det får næsten hjernen til at kortslutte, hvilke længder du er villig til at gå for at opnå sejr over mørkets styrker.\n\nLad mig nu spille min lille rolle i dette. Jeg har forberedt et særligt opløsningsmiddel, som skulle gøre det muligt for mig at fastgøre bassen som nøglens hoved, så den bliver fyldt med kraften til at bryde den låste dør til Skolomance.\n\nNu går det løs ..."},
  [5804] = {n="Arajs Basse", l="Dræb Araj Fremkalderen og bring Arajs Basse til Apoteker Tøvers ved Bolværket i de vestlige Pestlande.", d="Araj Fremkalderen hersker over Andorhøj fra den ruinerede bys hjerte. Vi ved, at han var den tidligere leder af Skolomance, før han gjorde byen til sin egen. For at færdiggøre nøglen skal vi bruge hans signet - kaldet en basse - monteret som nøglens hoved.\n\nBan dig vej ind i hjertet af Andorhøj, og bryd hans greb om byen nu, hvor han er lokket ud i det åbne. Når han er ødelagt, skal du rive hans basse ud af hans faldne fylakterium!\n\nNøglen til Skolomance venter, <Name>!", p="Du er kommet så langt, <Name> - kun ødelæggelsen af Araj Fremkalderens fysiske skikkelse vil give os midlerne til at færdiggøre nøglen. Skaf Arajs basse, med gode eller onde midler, og bring den til mig - jeg vil smelte den fast som nøglens hoved.", c="Ja, det er den! Jeg ... igen, jeg er helt forbløffet over dybden af din snilde og tapperhed. Det får næsten hjernen til at kortslutte, hvilke længder du er villig til at gå for at opnå sejr.\n\nLad mig nu spille min lille rolle i dette. Jeg har forberedt et særligt opløsningsmiddel, som skulle gøre det muligt for mig at fastgøre bassen som nøglens hoved, så den bliver fyldt med kraften til at bryde den låste dør til Skolomance.\n\nDet tager kun et øjeblik ..."},
  [5805] = {n="Velkommen!", l="Bring Nordshire-gavekortet til Merissa Stilvel.", d="Velkommen til Verden af Krigsværk!\n\nSom en særlig tak for at købe Samlerudgaven af Verden af Krigsværk, skal du aflevere dette gavekort til Merissa Stilvel i Nordshire-dalen. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigsværk!", p="Hilsner! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekort. Giv mig det, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5821] = {n="Livvagt til Leje", l="Eskortér Dimsby Karavanen forbi Kolkar-kentaurernes landsby. Tal med Smidt Skrableskrue ved Skrabbelskrues Lejr for din belønning.", d="Under normale omstændigheder ville Takkelmester og jeg føre vores kodo forbi Kolkar-kentaurerne. Nu og da hører vi kentaurernes krigstromler, og når vi hører dem, stopper vi. Det er ikke godt for forretningen at være død!\n\nJeg skal sige dig noget, <Class>: Hvis du beskytter os forbi Kolkar-landsbyen, skal vi nok gøre det umagen værd for dig.\n\nDet er bare en kort strækning. Alt du skal gøre er at holde karavanen intakt, så kan du hente din belønning hos Smeed Skrableskrue - han er et stykke nede ad vejen. Vi laver lidt forretning sammen.", p="Hvorfor står jeg og venter på den forbandede karavane?\n\n<Smeed ser oplyst ud.>\n\nÅh ja, det er dem, der betaler regningerne. Har du set dem?", c="Du ved, det virker ikke særlig lukrativt at betale nogen som dig for at vagte Dimsby Karavanen. <Class>, hvis jeg var en smule højere, kunne jeg tage et ekstra job og sidde kodo-sidesadel med det største gevær, mine hænder kunne bære ... og så ville jeg vise de forbandede kentaurer, hvem der er deres far."},
  [5841] = {n="Velkommen!", l="Bring Kuldekam-dalens gavekort til Yori Knækhjelm.", d="Velkommen til Verden af Krigsværk!\n\nSom en særlig tak for at købe Samlerudgaven af Verden af Krigsværk, skal du aflevere dette gavekort til Yori Knækhjelm i Kuldekam-dalen. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigsværk!", p="Hej! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekort. Giv mig det, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5842] = {n="Velkommen!", l="Bring Skyggedalens gavekort til Orenthil Hviskevind.", d="Velkommen til Verden af Krigsværk!\n\nSom en særlig tak for at købe Samlerudgaven af Verden af Krigsværk, skal du aflevere dette gavekort til Orenthil Hviskevind i Skyggedalen. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigsværk!", p="Hilsner! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekort. Giv mig det, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5843] = {n="Velkommen!", l="Bring Prøvernes Dal-gavekortet til Magga.", d="Velkommen til Verden af Krigsværk!\n\nSom en særlig tak for at købe Samlerudgaven af Verden af Krigsværk, skal du aflevere dette gavekort til Magga i Prøvernes Dal. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigsværk!", p="Hej! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekort. Giv mig det, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5844] = {n="Velkommen!", l="Bring Narache-lejrens gavekort til Vorn Himmelseer.", d="Velkommen til Verden af Krigsværk!\n\nSom en særlig tak for at købe Samlerudgaven af Verden af Krigsværk, skal du aflevere dette gavekort til Vorn Himmelseer i Narache-lejren. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigsværk!", p="Hilsner! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekort. Giv mig det, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5845] = {n="Om Tabt Ære", l="Rejs til Nordedal i den nordøstlige del af de østlige Pestlande, og find Symbolet på Tabt Ære. Vend tilbage til Tirion Fordring, når dit mål er opnået.", d="Sølvhåndens Orden blev fuldstændig decimeret, da Uther blev dræbt.\n\nDrengen holdt stand, så længe han kunne. Presset tilbage til den krigshærgede landsby Nordedal tog han sit sidste standpunkt.\n\nVar der nogen af ordenen tilbage i live, tænkte han - og betød det noget?\n\nDet var med den tanke, at Taelan kastede ordenens banner til jorden og afsværgede alt, han havde kendt. Hans ære efterlod sig på den blodgennemvædede jord i Nordedal.\n\nDu må rejse til Nordedal og hente det symbol på tabt ære.", p="Min tro vil guide dig, <Name>. Lyset kender ingen grænser.", c="Det er lige så herligt nu - selv i sin slidte tilstand - som den dag, jeg så det og aflagde min troskabsed.\n\nHans forløsning kommer, og måske min med den ..."},
  [5846] = {n="Om Kærlighed og Familie", l="Rejs til øen Kær Darrow i den sydcentrale del af Pestlandene, og led efter spor af, hvor malerværket er blevet af.", d="Da Taelan var barn, besøgte vi ofte Kær Darrow på familieudflugter. Ved vores sidste besøg malede en kunstner ved navn Renfray et portræt af os, stillet op ved stranden. Det er min kæreste erindring om både Taelan og Karandra. For det var i det øjeblik, med min kone og søn i mine arme, at jeg følte et bånd af kærlighed og familie, som jeg aldrig ville kende igen.\n\nHvis dette maleri stadig eksisterer, må du finde det.\n\nRejs til den ruinerede ø Kær Darrow og se, om maleriet eller kunstneren stadig er der.", c="Hvordan kunne jeg glemme? Mange af ånderne på denne ø er forbandet til at genopleve deres sidste lykkelige erindring, før de mødte deres tragiske ende.\n\nJeg er også forbandet, men ikke som de - jeg er en af de få, der husker alt ...\n\nMåske er det netop dette, du spørger mig om, der får mig til at hjemsøge disse ruiner. Måske er det, jeg fortæller dig nu, det, der vil befri mig."},
  [5847] = {n="Velkommen!", l="Bring Dødsklokkens Gavekupon til Klare Vilgower i Dødsklokken.", d="Velkommen til Verden af Krigshåndværk!\n\nSom en særlig tak for at købe Krigshåndværk Samlerudgave, skal du aflevere dette gavekupon til Klare Vilgower i Dødsklokken. Så får du en gave: en lille ledsager, der kan følge dig på dit eventyr og i din jagt på herlighed.\n\nTak igen, og nyd dit ophold i Verden af Krigshåndværk!", p="Hilsner! Det er en fornøjelse at møde dig!\n\nJeg kan se, at du har et særligt gavekupon. Giv det til mig, så tilbyder jeg dig noget til gengæld.", c="Du er faktisk en særlig helt, <Name>. Vi byder dig velkommen til Azerot og tilbyder dig en af disse unikke gaver!"},
  [5848] = {n="Af kærlighed og familie", l="Rejs til Stratholm i den nordlige del af Pestlandene. Det er i Skarlagen-Bastionen, at du finder maleriet 'Af kærlighed og familie', gemt bag et andet maleri, der forestiller vores verdens to måner.\n\nAflever maleriet til Tirion Krav.", d="Maleriet... Det hang på væggen i mit værksted - inde i Ordenens kaserne - i årevis.\n\nEfter Tirions retssag vidste jeg, at jeg ikke længere kunne lade maleriet hænge synligt. Jeg gemte det et sted, hvor de aldrig ville tænke på at lede.\n\nRejs til Stratholm og tag dig vej dybt ind i det, der nu er Skarlagen-Bastionen, og led efter et maleri af vores to måner. Hug maling væk, indtil du afdækker mit mesterværk, 'Af kærlighed og familie'.\n\nMåtte Let vejlede dine handlinger.", p="Maleriet, <Name>. Har du maleriet?", c="<Tirion næsten bryder sammen, når han ser maleriet.>\n\n<Han begynder at hulke på en næsten rasende måde.>"},
  [5861] = {n="Find Mirenda", l="Rejs til Uthers grav, som ligger i det sydlige Pestlande. Vis Mirenda Heksen Tirions Gave.", d="<Name>, du har gjort alt, hvad jeg har bedt om indtil nu. Kun ét skridt står tilbage i din opgave om forløsning.\n\nDu skal aflevere de genstande, du har samlet, til Taelan. Desværre vil Taelan og hans Skarlagenrøde Korsfarere angribe dig på syn.\n\nDer er kun én måde at levere min besked på, og det er gennem en forklædning af svig.\n\nMod syd finder du Uthers grav. En gammel og pålidelig fortrolig af mig, Mirenda, bor der nu - søg hende op. Vis hende genstandene, så hjælper hun dig.", p="Jeg vidste, at den dag ville komme.", c="Jeg var Tirions mest betroede rådgiver, da han bar titlen Herre af Mardenhold. Jeg tog åbent afstand fra dommen, som Sølvhåndens Orden afsagde, og blev forvist for min frækhed.\n\nHan har været igennem meget hjertesorg og skuffelse i sit liv, <Race>. Er du rede til at rette de uretfærdigheder, der er begået mod Krav-familien?"},
  [5862] = {n="Skarlagen-skjulespil", l="Tal med Mirenda for at få Skarlagen-Illusionen. Rejs til Hjertedal, mens du er under Skarlagen-Illusionen, og aflever Tirions Gave til Højlord Taelan Krav.\n\nHjertedal ligger mod nord, Taelan burde være inde i Mardenhold-fæstningen.", d="Jeg er det, man vil kalde en illusionist. Selvom jeg måske kan skabe en illusion, der lader dig komme ind i Hjertedal, så vær advaret; mine kræfter har deres begrænsninger.\n\nHvis du rejser for langt væk fra disse lande, ophører illusionens virkning. Besværgelsen kræver en stor mængde koncentration og kraft fra mig, og derfor kan jeg kun opretholde effekten i kort tid.\n\nTal til mig igen, når du er klar.", p="Er du forstærkningerne fra Tyrs Hånd?", c="Hvad er dette, soldat?\n\n<Taelan åbner kassen og begynder at undersøge indholdet.>\n\nDet... det kan ikke være sandt. Men alt, hvad du har vist mig...\n\n<Taelan falder på det ene knæ, hans hjerte slår hurtigere. Århundreders raseri er ved at blive løsnet over denne by.>"},
  [5863] = {n="Dunestødhammer-Blandingen", l="Andi Lyng i Gadgetbyen vil have dig til at ødelægge Dunestødhammer-Blandingen ved at dræbe 10 Dunestødhammer-Brutaler, 10 Dunestødhammer-Håndhævere og Gor'marok Hærgeren.", d="For nylig ankom en stor flok nomadiske oger til Tanaris. Sydpå herfra har de overtaget et stort område i ørkenen og dannet en blanding. Flere mindre bander vandrer i øjeblikket rundt i ørkenen, og nogle af dem har invaderet de gamle trolderuiner.\n\nDunestødhammer-Blandingen må ødelægges! Vi kan ikke tillade, at disse oger opbygger en styrke.\n\nLederen af denne bande hedder Gor'marok Hærgeren; jeg tror, at hvis vi får en ende på hans lederskab, bliver det begyndelsen på enden for ogerne.", p="Jeg er så bekymret! Vær venligst forsigtig!", c="Jeg er så glad for, at du kunne gøre dette for mig, <Name>! Tak for din hjælp!"},
  [5882] = {n="Salve via Jagt", p="At besidde et Cenarion-fyrtårn gør det muligt at se et fordærvet sjæle-fragment på de besmittede bæster, der nedlægges til det større gode. Jeg maler fragmenterne til en brugbar reagens, der går i Cenarion-plantesalven. Vi bruger den salve til at forvandle fordærvede planter tilbage til sunde.\n\nTil gengæld for disse fragmenter giver jeg dig nogle Cenarion-plantesalver, som jeg allerede har tilberedt.", c="Meget godt, så. Her er dine Cenarion-plantesalver. Afsøg Ondskoven for fordærvede planter, <Name>! Uanset hvor de er, så brug den salve, jeg har givet dig, til at rense dem."},
  [5883] = {n="Salve via Minedrift", p="Hvis du har et Cenarion-fyrtårn, mens du bryder malm i Ondskoven, vil du kunne se besmittet vitriol, der korrumperer en åre af råmetal. Jeg ved, hvordan man renser den vitriol og gør den til en reagens, der går i Cenarion-plantesalven. Derefter bruger du salven på planter, du finder i naturen, som trænger til hjælp.\n\nHvis du har samlet nogen besmittet vitriol, giver jeg dig noget Cenarion-plantesalve, som jeg allerede har tilberedt.", c="Meget godt, så. Her er lidt Cenarion-plantesalve. Hvis du finder mere vitriol, når du bryder malm i Ondskoven, så husk at gemme den til mig! Jo mere du finder, jo mere salve kan jeg lave."},
  [5884] = {n="Salve via Samlende", p="Et Cenarion-fyrtårn gør det muligt for en erfaren urtekyndig at opdage snigende dæmonisk krybning - et ondsindet produkt af Ondskovens fordærv. Mit arbejde her har lært mig at rense dæmonisk krybning til en renselsesreagens... der bruges i det, vi nu kalder Cenarion-plantesalve.\n\nNår du samler urter i Ondskoven, bør du støde på den dæmoniske krybning, så længe du har fyrtårnet. Til gengæld for det, du bringer mig, giver jeg dig færdiglavet Cenarion-plantesalve.", c="Fremragende arbejde, <Name> - alt dette vil, når vi har renset det, hjælpe os med at generobre Ondskoven. Her, tag nogle doser Cenarion-plantesalve og bevæg dig ind i skoven. Genvindingen af landet fra fordærvet venter ikke på nogen <Race>!"},
  [5885] = {n="Salve via Flåning", p="Et Cenarion-fyrtårn vil gøre en veluddannet flåer i stand til at opdage pletter af besmittet hud fra byttet, der samles i Ondskoven. Jeg omdanner disse tilsyneladende ubrugelige pletter til en tyk pasta, der fungerer som et fremskyndende middel for Cenarion-plantesalven. Når du flår dine dræbninger her i Ondskoven, så sørg for at have et fyrtårn på dig!\n\nNår du samler besmittede pletter, skal du bringe dem til mig, så giver jeg dig nogle Cenarion-plantesalver, som jeg allerede har lavet.", c="Det er præcis, hvad jeg har brug for. Her - tag disse plantesalver og brug dem til at generobre Ondskoven fra fordærvet. Vi må holde ud, <Name>!"},
  [5886] = {n="Salve via Afmagisering", p="Kraften fra en afmagiseret magisk genstand mærkes i den essens, den skaber. Jeg har udtænkt en måde at omdanne rå essens, som fortryllere bruger, til en passende reagens til at lave Cenarion-plantesalve. Du behøver ikke et Cenarion-fyrtårn til dette; enhver passende afmagiseret genstand, der giver mindre tomrums-essenser, vil fungere.\n\nJeg har kun brug for en enkelt mindre tomrums-essens; til gengæld giver jeg dig Cenarion-plantesalver. Essensen er ekstremt kraftfuld - en lille smule rækker meget langt!", c="Her er nogle Cenarion-plantesalver - jeg har kun brug for én mindre tomrums-essens til dette, <Name>. Essens er langt det mest kraftfulde, jeg kan bruge til at smede sværd om til plovjern, så to sige. Hvis du har brug for mere salve, så find mig her!"},
  [5887] = {n="Salve via Jagt", p="At besidde et Cenarion-fyrtårn gør det muligt at se et fordærvet sjæle-fragment på de besmittede bæster, der nedlægges til det større gode. Jeg maler fragmenterne til en brugbar reagens, der går i Cenarion-plantesalven. Vi bruger den salve til at forvandle fordærvede planter tilbage til sunde.\n\nTil gengæld for disse fragmenter giver jeg dig nogle Cenarion-plantesalver, som jeg allerede har tilberedt.", c="Meget godt, så. Her er dine Cenarion-plantesalver. Afsøg Ondskoven for fordærvede planter, <Name>! Uanset hvor de er, så brug den salve, jeg har givet dig, til at rense dem."},
  [5888] = {n="Salve via Minedrift", p="Hvis du har et Cenarion-fyrtårn, mens du bryder malm i Ondskoven, vil du kunne se besmittet vitriol, der korrumperer en åre af råmetal. Jeg ved, hvordan man renser den vitriol og gør den til en reagens, der går i Cenarion-plantesalven. Derefter bruger du salven på planter, du finder i naturen, som trænger til hjælp.\n\nHvis du har samlet nogen besmittet vitriol, giver jeg dig noget Cenarion-plantesalve, som jeg allerede har tilberedt.", c="Meget godt, så. Her er lidt Cenarion-plantesalve. Hvis du finder mere vitriol, når du bryder malm i Ondskoven, så husk at gemme den til mig! Jo mere du finder, jo mere salve kan jeg lave."},
  [5889] = {n="Salve via Samlende", p="Et Cenarion-fyrtårn gør det muligt for en erfaren urtekyndig at opdage snigende dæmonisk krybning - et ondsindet produkt af Ondskovens fordærv. Mit arbejde her har lært mig at rense dæmonisk krybning til en renselsesreagens... der bruges i det, vi nu kalder Cenarion-plantesalve.\n\nNår du samler urter i Ondskoven, bør du støde på den dæmoniske krybning, så længe du har fyrtårnet. Til gengæld for det, du bringer mig, giver jeg dig færdiglavet Cenarion-plantesalve.", c="Fremragende arbejde, <Name> - alt dette vil, når vi har renset det, hjælpe os med at generobre Ondskoven. Her, tag nogle doser Cenarion-plantesalve og bevæg dig ind i skoven. Genvindingen af landet fra fordærvet venter ikke på nogen <Race>!"},
  [5890] = {n="Salve via Flåning", p="Et Cenarion-fyrtårn vil gøre en veluddannet flåer i stand til at opdage pletter af besmittet hud fra byttet, der samles i Ondskoven. Jeg omdanner disse tilsyneladende ubrugelige pletter til en tyk pasta, der fungerer som et fremskyndende middel for Cenarion-plantesalven. Når du flår dine dræbninger her i Ondskoven, så sørg for at have et fyrtårn på dig!\n\nNår du samler besmittede pletter, skal du bringe dem til mig, så giver jeg dig nogle Cenarion-plantesalver, som jeg allerede har lavet.", c="Det er præcis, hvad jeg har brug for. Her - tag disse plantesalver og brug dem til at generobre Ondskoven fra fordærvet. Vi må holde ud, <Name>!"},
  [5891] = {n="Salve via Afmagisering", p="Kraften fra en afmagiseret magisk genstand mærkes i den essens, den skaber. Jeg har udtænkt en måde at omdanne rå essens, som fortryllere bruger, til en passende reagens til at lave Cenarion-plantesalve. Du behøver ikke et Cenarion-fyrtårn til dette; enhver passende afmagiseret genstand, der giver mindre tomrums-essenser, vil fungere.\n\nJeg har kun brug for en enkelt mindre tomrums-essens; til gengæld giver jeg dig Cenarion-plantesalver. Essensen er ekstremt kraftfuld - en lille smule rækker meget langt!", c="Her er nogle Cenarion-plantesalver - jeg har kun brug for én mindre tomrums-essens til dette, <Name>. Essens er langt det mest kraftfulde, jeg kan bruge til at smede sværd om til plovjern, så to sige. Hvis du har brug for mere salve, så find mig her!"},
  [5901] = {n="En pest over dig", l="Brug den tomme termitkrukke på termithøjene i Østlige Pestlande. Når du har samlet 100 Pestlands-termitter, skal du vende tilbage til Mikke Levine ved Bolværket i Tirisfal-sletterne.", d="Så for at bringe smerte og strid over Skarlagenrøde Korstog, vil jeg tage deres dyrebare savværk fra dem. Jeg er sikker på, at tabet af en sådan ressource vil volde dem stor skade, når de forsvarer og genopbygger byen af deres egne grunde. Vil du hjælpe mig, <Name>?\n\nBegynd med at tage denne krukke til Pestskoven i Østlige Pestlande. Fyld den med de termitter, du finder i deres høje rundt omkring i skoven. Kom tilbage, når du har nok.", p="Har du termitterne endnu, <Name>? Jeg er sikker på, at det er indlysende for en klog <Class> som dig selv.\n\nNår vi har nok af dem, sørger vi for, at ingen nogensinde kan bruge savværket igen!", c="Disse dur fint, <Name>. Tak.\n\nHvis du er klar, kan vi gå videre til næste trin."},
  [5902] = {n="En pest over dig", l="Find et egnet sted midt i Nordkamm-tømmermøllen i Vestlige Pestlande, hvor du kan placere Tønden med Pestlands-termitter.", d="Nu hvor vi har masser af termitter, skal du tage denne stålforstærkede tønde til Nordkamm-tømmermøllen syd for Hjertedal - du finder den vest for vejen, der fører op til byen.\n\nNår du er der, skal du placere tønden midt i savværket; et sted højt, f.eks. oven på en kasse eller lignende.\n\nNår du har åbnet den, klarer resten sig selv. Kom bare tilbage hertil, så belønner jeg dig for din hjælp.", c="Termitterne bliver tydeligvis urolige, når du placerer tønden oven på kassen."},
  [5903] = {n="En pest over dig", l="Brug den tomme termitkrukke på termithøjene i Østlige Pestlande. Når du har samlet 100 Pestlands-termitter, skal du vende tilbage til Nathaniel Dumøh i Kuldevind-lejren i Vestlige Pestlande.", d="Jeg har forsøgt mange gange at fordrive Skarlagenrøde Korstog med ren magt, men uden held. Så i stedet har jeg besluttet at gøre deres liv vanskeligere.\n\nHvis du er villig til at hjælpe, vil jeg invadere det savværk med de frygteligste termitter, der nogensinde er fundet.\n\nI Pestskoven, nær det engang så store Stratholm, findes en art, der overlevede både pesten og Svøben i forening. Find deres høje og fyld denne krukke med dem, så vi kan gøre dem klar til at blive sluppet løs på Korstoget.", p="Fandt du termithøjene, <Name>? Jeg har hørt, at de findes overalt i Pestskoven.", c="Disse dur fint, <Name>. Tak. Se bare på dem... så mange, der klumper sig sammen. Jeg føler næsten medlidenhed med Korstoget, men alligevel - det var jo aldrig deres savværk at tage, vel?"},
  [5904] = {n="En pest over dig", l="Find et egnet sted midt i Nordkamm-tømmermøllen i Vestlige Pestlande, hvor du kan placere Tønden med Pestlands-termitter.", d="Nu hvor vi har termitterne, skal du tage denne stålforstærkede tønde til Nordkamm-tømmermøllen syd for Hjertedal - du finder den vest for vejen, der fører op til byen.\n\nNår du er der, skal du placere tønden midt i savværket; find et passende sted, f.eks. oven på en kasse, og åbn den derefter. Termitterne skulle gøre deres arbejde derfra og gøre savværket ubrugeligt for Korstoget.", c="Termitterne bliver tydeligvis urolige, når du placerer tønden oven på kassen."},
  [5921] = {n="Månelunden", l="Brug besværgelsen \"Teleportér: Månelunden\" for at rejse til Månelunden. Når du ankommer, skal du tale med Dendrit Stjerneblus i landsbyen Nathavn.", d="Alle druider er velkomne i Månelundens hellige lande, uanset de nuværende spændinger i Cenarion-kredsen mellem Ærkedruide Hjorthelm og Vogter Remulos - Månelundens vogter. Nu hvor du lærer Klo-vejene, vil jeg lære dig besværgelsen, der lader dig transportere dig selv derhen. Støb den, når du søger Månelundens viden eller trøst.\n\nTil din første lektion: rejs til Månelunden og tal med Dendrit Stjerneblus i Nathavn om den vej, du nu er på. Held og lykke, unge druide.", c="\"Og så begynder det, Fader Cenarus. Og så begynder det.\"\n\nDendrit laver en hurtig, usynlig bevægelse i luften over sig. En svag glorie af kraft falder over ham.\n\n\"Det første perspektiv af naturen, du må tilpasse dig, er bjørnens. Jeg vil sætte dig på vejen til at forstå dette aspekt af druidelivet, men det er dig, der skal omfavne det og udbrede det - nu og for evigt!\""},
  [5922] = {n="Månelunden", l="Brug besværgelsen \"Teleportér: Månelunden\" for at rejse til Månelunden. Når du ankommer, skal du tale med Dendrit Stjerneblus i landsbyen Nathavn.", d="Alle druider er velkomne til Månelundens hellige lande, både taurener og nattenisser. Vogter Remulos - Månelundens vogter - holder øje med alle druider, der overvintrer der. Nu hvor du lærer Klo-vejene, vil jeg lære dig besværgelsen, der lader dig transportere dig selv derhen. Støb den, når du søger Månelundens viden eller trøst.\n\nTil din første lektion: rejs til Månelunden og tal med Dendrit Stjerneblus i Nathavn om den vej, du nu er på. Held og lykke, unge druide.", c="\"Og så begynder det, Fader Cenarus. Og så begynder det.\"\n\nDendrit laver en hurtig, usynlig bevægelse i luften over sig. En svag glorie af kraft falder over ham.\n\n\"Det første perspektiv af naturen, du må tilpasse dig, er bjørnens. Jeg vil sætte dig på vejen til at forstå dette aspekt af druidelivet, men det er dig, der skal omfavne det og udbrede det - nu og for evigt!\""},
  [5923] = {n="Hør Kaldet", l="Tal med Mathrengyl Bjørnegænger i Cenarion-enklaven i Darnassos.", d="Undskyld mig, ven...\n\nDet er kommet til min kendskab, at Mathrengyl Bjørnegænger har meldt ud, at han ønsker at tale med dig. Det lader til, at din uddannelse som druide er ved at tage en ny vending, og at han selv vil træne dig. Mathrengyl er den direkte assistent for Ærkedruiden selv og er en af de mest vise og ophøjede druider, du vil finde i Teldrasil.\n\nHan befinder sig i Cenarion-enklaven i Darnassos, på anden etage i Fandrel Hjorthelms træ.", c="Jeg er glad for, at du fandt vej hertil i dag, unge druide. Tiden er kommet til, at du skal tage et stort skridt ind i en meget større verden.\n\nInde i hvert af Cenarus' børn lever kaldet til at tjene naturen. Dyr og planter er vore venner såvel som vore ansvar. Vi vælger at vie vores liv som bevarere af balancen, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden vil være at lære bjørnens veje og at lære styrke af krop og hjerte.\n\nGør dig klar!"},
  [5924] = {n="Hør Kaldet", l="Tal med Mathrengyl Bjørnegænger i Cenarion-enklaven i Darnassos.", d="Undskyld mig, ven...\n\nDet er kommet til min kendskab, at Mathrengyl Bjørnegænger har meldt ud, at han ønsker at tale med dig. Det lader til, at din uddannelse som druide er ved at tage en ny vending, og at han selv vil træne dig. Mathrengyl er den direkte assistent for Ærkedruiden selv og er en af de mest vise og ophøjede druider, du vil finde i Teldrasil.\n\nHan befinder sig i Cenarion-enklaven i Darnassos, på anden etage i Fandrel Hjorthelms træ.", c="Jeg er glad for, at du fandt vej hertil i dag. unge <Class>. Tiden er kommet til, at du skal tage et stort skridt ind i en meget større verden.\n\nInde i hvert af Cenarus' børn lever kaldet til at tjene naturen. Dyr og planter er vore venner såvel som vore ansvar. Vi vælger at vie vores liv som bevarere af balancen, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden vil være at lære bjørnens veje og at lære styrke af krop og hjerte.\n\nGør dig klar!"},
  [5925] = {n="Hør Kaldet", l="Tal med Mathrengyl Bjørnegænger i Cenarion-enklaven i Darnassos.", d="Undskyld mig, ven...\n\nDet er kommet til min kendskab, at Mathrengyl Bjørnegænger har meldt ud, at han ønsker at tale med dig. Det lader til, at din uddannelse som druide er ved at tage en ny vending, og at han selv vil træne dig. Mathrengyl er den direkte assistent for Ærkedruiden selv og er en af de mest vise og ophøjede druider, du vil finde i Teldrasil.\n\nHan befinder sig i Cenarion-enklaven i Darnassos, på anden etage i Fandrel Hjorthelms træ.", c="Jeg er glad for, at du fandt vej hertil i dag, unge druide. Tiden er kommet til, at du skal tage et stort skridt ind i en meget større verden.\n\nInde i hvert af Cenarus' børn lever kaldet til at tjene naturen. Dyr og planter er vore venner såvel som vore ansvar. Vi vælger at vie vores liv som bevarere af balancen, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden vil være at lære bjørnens veje og at lære styrke af krop og hjerte.\n\nGør dig klar!"},
  [5926] = {n="Hør Kaldet", l="Tal med Turak Rune-Totem på Ældrehøjen i Tordenskrænt.", d="Undskyld mig, ven...\n\nDet er kommet til min kendskab, at Turak Rune-Totem har meldt ud, at han ønsker at tale med dig. Det lader til, at din uddannelse som druide er ved at tage en ny vending, og at han selv vil træne dig. Turak er en af Ærkedruidens assistenter; han er kendt som en klog og tålmodig druide, og han vil lære dig godt.\n\nHan befinder sig i Tordenskrænt, inde i Cenarion-kredsens hovedtelt på Ældrehøjen.", c="Jeg er glad for, at du fandt vej hertil i dag, unge druide. Tiden er kommet til, at du skal tage et stort skridt ind i en meget større verden.\n\nInde i hvert af Cenarus' børn lever kaldet til at tjene naturen. Dyr og planter er vore venner såvel som vore ansvar. Vi vælger at vie vores liv som bevarere af balancen, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden vil være at lære bjørnens veje og at lære styrke af krop og hjerte.\n\nGør dig klar!"},
  [5927] = {n="Lyt til Kaldet", l="Tal med Turak Runestav på Ældrehøjen i Tordenskrænten.", d="Undskyld mig, ven...\n\nDet er kommet til min kundskab, at Turak Runestav har meldt ud, at han ønsker at tale med dig. Det ser ud til, at din træning som druide er ved at få et nyt liv, og han vil træne dig personligt. Turak er en af Ærkedruidens assistenter; han er kendt som en klog og tålmodig druide, og han vil nok lære dig godt.\n\nHan befinder sig i Tordenskrænten, inde i Cenarion-kredsens hovedtelt på Ældrehøjen.", c="Jeg er glad for, at du fandt vej hertil i dag, unge <Class>. Tiden er kommet til, at du skal tage et stort skridt ind i en langt større verden.\n\nI hvert af Cenarus' børn bor kaldet til at tjene naturen. Dyr og planter er vores venner såvel som vores ansvar. Vi vælger at vie vores liv som balancens bevarere, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden bliver at lære bjørnens veje og at lære styrke i krop og hjerte.\n\nGør dig klar!"},
  [5928] = {n="Lyt til Kaldet", l="Tal med Turak Runestav på Ældrehøjen i Tordenskrænten.", d="Undskyld mig, ven...\n\nDet er kommet til min kundskab, at Turak Runestav har meldt ud, at han ønsker at tale med dig. Det ser ud til, at din træning som druide er ved at få et nyt liv, og han vil træne dig personligt. Turak er en af Ærkedruidens assistenter; han er kendt som en klog og tålmodig druide, og han vil nok lære dig godt.\n\nHan befinder sig i Tordenskrænten, inde i Cenarion-kredsens hovedtelt på Ældrehøjen.", c="Jeg er glad for, at du fandt vej hertil i dag, unge <Class>. Tiden er kommet til, at du skal tage et stort skridt ind i en langt større verden.\n\nI hvert af Cenarus' børn bor kaldet til at tjene naturen. Dyr og planter er vores venner såvel som vores ansvar. Vi vælger at vie vores liv som balancens bevarere, for deres skyld såvel som vores egen. Dit første skridt ind i denne verden bliver at lære bjørnens veje og at lære styrke i krop og hjerte.\n\nGør dig klar!"},
  [5929] = {n="Den Store Bjørneånd", l="Søg Den Store Bjørneånd i den nordvestlige del af Månelunden og lær, hvad den har at dele med dig om bjørnens natur. Når du er færdig, skal du vende tilbage til Dendrit Stjerneblus i Nathavn, Månelunden.", d="I den nordvestlige del af Månelunden bor hjemmet for et klogt og ædelt væsen, som vi kalder Den Store Bjørneånd. For alle druider har den fungeret som lærer og mentor i den første sande naturlige forståelse af bjørnen. Alle druider søger på et tidspunkt åndens visdom, og du skal ikke være nogen undtagelse.\n\nGå nu til Den Store Bjørneånd og lær, hvad den vil lære dig. Når den er tilfreds med dig, skal du vende tilbage til mig her i Nathavn. Så ser vi, om du virkelig har taget lektionerne til dig.", p="Vend kun tilbage, når Den Store Bjørneånd har sluppet dig tilbage til mig. Din træning kan ikke fortsætte uden dens velsignelse.", c="Dendrit laver endnu et usynligt håndtegn i luften over sig, da du nærmer dig. Endnu en kraftaura falder over ham, og han smiler lidt.\n\n\"Jeg fornemmer visdom i dig, unge, som ikke var der, da vi første gang mødtes. Du ser på mig med styrke og vidende hensigt, selvom denne hensigt endnu ikke er fokuseret. Du vil nu lære at fokusere din styrke og tage bjørnens natur med ind i dit arbejde.\""},
  [5930] = {n="Den Store Bjørneånd", l="Søg Den Store Bjørneånd i den nordvestlige del af Månelunden og lær, hvad den har at dele med dig om bjørnens natur. Når du er færdig, skal du vende tilbage til Dendrit Stjerneblus i Nathavn, Månelunden.", d="I den nordvestlige del af Månelunden bor hjemmet for et klogt og ædelt væsen, som vi kalder Den Store Bjørneånd. For alle druider har den fungeret som lærer og mentor i den første sande naturlige forståelse af bjørnen. Alle druider søger på et tidspunkt åndens visdom, og du skal ikke være nogen undtagelse.\n\nGå nu til Den Store Bjørneånd og lær, hvad den vil lære dig. Når den er tilfreds med dig, skal du vende tilbage til mig her i Nathavn. Så ser vi, om du virkelig har taget lektionerne til dig.", p="Vend kun tilbage, når Den Store Bjørneånd har sluppet dig tilbage til mig. Din træning kan ikke fortsætte uden dens velsignelse.", c="Dendrit laver endnu et usynligt håndtegn i luften over sig, da du nærmer dig. Endnu en kraftaura falder over ham, og han smiler lidt.\n\n\"Jeg fornemmer visdom i dig, unge, som ikke var der, da vi første gang mødtes. Du ser på mig med styrke og vidende hensigt, selvom denne hensigt endnu ikke er fokuseret. Du vil nu lære at fokusere din styrke og tage bjørnens natur med ind i dit arbejde.\""},
  [5931] = {n="Tilbage til Darnassos", l="Vend tilbage til Darnassos og tal med Mathrengyl Bjørnegænger i Cenarion-enklaven.", d="Tiden er kommet til, at vi skal gå hver til sit, unge, for anvendelsen af dine lektioner tager dig tilbage til den, der sendte dig til mig. Mathrengyl Bjørnegænger færdes virkelig i balance med naturen, selvom han bor farligt tæt på, hvor balancen er slået fejl. Lyt til hans anvisninger, så fuldender du snart dine første lektioner i din rolle som balancens beskytter.\n\nGå nu, unge. Vi ses igen.", c="Velkommen tilbage, <Name>. Jeg fornemmer, at dit første møde med Den Store Bjørneånd er det samme, som det er for alle druider, når de først træder ind på Klo-vejen... lidt forvirrende, men meget intenst. Jeg ved, at det var sådan for mig.\n\nDen Store Bjørneånd har været en del af Azerot, lige så længe Azerot har eksisteret på himlen. Vi er kommet til at stole på dens visdom og dens kraft til at drive vores formål. Nu er tiden kommet til din første prøve af dette formål. Lyt nøje..."},
  [5932] = {n="Tilbage til Tordenskrænten", l="Vend tilbage til Tordenskrænten og tal med Turak Runestav på Ældrehøjen.", d="Tiden er kommet til, at vi skal gå hver til sit, unge, for anvendelsen af dine lektioner tager dig tilbage til den, der sendte dig til mig. Selvom taurenerne menes at være unge i Cenarus' veje, går Turak Runestav med stor balance i naturens nærvær. Lyt til hans anvisninger, så fuldender du snart dine første lektioner i din rolle som balancens beskytter.\n\nGå nu, unge. Vi ses igen.", c="Velkommen tilbage, <Name>. Jeg fornemmer, at dit første møde med Den Store Bjørneånd er det samme, som det er for alle druider, når de først træder ind på Klo-vejen... lidt forvirrende, men meget intenst. Jeg ved, at det var sådan for mig.\n\nDen Store Bjørneånd har været en del af Azerot, lige så længe Azerot har eksisteret på himlen. Vi taurener lytter nøje til sådanne ånder, og vi trives alle af dens formål. Nu er tiden kommet til din første prøve af dette formål. Lyt nøje..."},
  [5941] = {n="Tilbage til Kromie", l="Bring Bundtet af Relikvier til Kromie i Andorhøj.", d="Du har samlet mange relikvier fra slaget ved Dårshire. Hver gang du kom tilbage med flere, længtes mit hjerte efter min landsby... længtes efter at beskytte den mod dens skæbne.\n\nJeg ved, at det ikke kan være, men Kromie, den underlige gnom i Andorhøj, fortæller mig, at det er muligt. Hun siger, at du kan redde Dårshire!\n\nHun bad mig samle relikvierne og få dig til at bringe dem til hende. Hun sagde, at hun venter på dig i Andorhøjs ruinerede kro.", p="Jeg har været i kontakt med din ven Karlin. Han føler stor smerte over sin landsbys undergang, men han taler meget højt om dig og ved, at du kan få tingene til at gå godt igen.\n\nÅh, men jeg kommer vist væk fra emnet... <Name>, har du de relikvier, jeg bad om?", c="Ah ja, der er de. Sammen væver de en kraftfuld besværgelse, en der vil løfte Dårshires ånder.\n\nMed den besværgelse og med lidt held kan vi redde Josef Rødsti!"},
  [5942] = {n="Skjulte Skatte", l="Bring Josefs Nøgle til Josefs Kiste.", d="Far sagde, at jeg skulle give dig denne nøgle. Han sagde, den åbner en kiste ude bag huset.\n\nHan ville også have mig til at takke dig. Gjorde du en tjeneste for ham? Fortalte du ham, at du havde fundet min dukke?\n\nNå, her er nøglen. Og tak, <Name>. Tak! Du er en meget flink mand!", p="Denne kiste er gammel og dækket af snavs.", c="Nøglen passer i låsen, og kisten åbner sig..."},
  [5943] = {n="Dimsby-karavanen", l="Eskorter Dimsby-karavanen gennem Mannorok-hekseriet. Tal med Smedd ved Skrueskrabs Lejr for din belønning.", d="Du ser ud som en dygtig <Race>. Måske leder du efter at tjene nogle penge? Kork og jeg startede denne karavane for at tjene en masse penge; vi anede ikke, hvilke farer der var ved at tjene en skilling!\n\nForude ligger Mannorok-hekseriet... normalt ignorerer dæmonerne os, men noget har fået kæmpeokserne til at blive nervøse denne gang. Jeg betaler dig for at beskytte karavanen forbi Mannorok-hekseriet. Når vi er sikkert forbi, kan du få din belønning af vores forretningsforbindelse Smedd ved Skrueskrabs Lejr.", p="Du ved, hvis den karavane nogensinde forsvandt, ville jeg være ruineret! Du er ikke bærer af dårlige nyheder om karavanen, vel?\n\n<Smedd tørrer sig om panden.>\n\nTak gudinden for grådighed!", c="Jeg er ikke sikker på, at det er et velstående forslag at betale så mange penge for at beskytte Dimsby-karavanen. Kork og Takkel tjener kun en guldmønt om ugen, men så længe de bliver ved med at betale for mine kæmpeokser, er det mig ligegyldigt, hvordan de driver deres forretning."},
  [5944] = {n="I Drømme", l="Eskorter Taelan Krav ud af Hjertedal.", d="I så lang tid har jeg været en marionet for Storslået Korsfarer. Hvilken grund var der til at kæmpe mod det, Skarlagenrøde Korstog var blevet? Det er årtier siden, men mindet om min far; de dyrebare minder, de er det, der har holdt mig i live.\n\nJeg har drømme, fremmede. I disse drømme er min far hos mig. Han står stolt ved min side, mens jeg optages i Ordenen. Vi kæmper mod Svøbens legioner side om side. Vi bringer ære til Alliancen, til Herrelande.\n\nJeg vil ikke drømme mere.\n\nTag mig til ham.", p="<Tiron genvinder fatningen.>", c="Min søns død ved hænderne på disse monstre vil ikke gå upåagtet hen. Find trøst i at vide, at Ordenen er genfødt.\n\nJeg tager nu min plads som Højlord for den nye Sølvhåndens Orden.\n\nDisse ejendele fra min fortid - de er alt, hvad jeg har at tilbyde for alt, hvad du har gjort. Tag venligst disse som et symbol på min taknemmelighed; alle har tjent mig godt gennem årene.\n\nMåtte vi mødes igen, under bedre tider, og mindes dage fra længst siden... hårdt kæmpede slag... genvundne drømme."},
  [5961] = {n="Dødsånd-dronningens Mester", l="Tal med Nathanos Pestkalder i Østlige Pestlande. Han siges at have slået sig ned ved Marsk-gården.", d="Det glæder mig meget at se de hærdede slutte sig til vores sag. Vores antal vokser i størrelse og styrke for hver dag, der går. Måske er du klar til at prøve dit mod, <Class>?\n\nBlandt mine første mestre var Nathanos, nu kendt som Pestkalderen. Få findes med mere hengivenhed eller kraft blandt vores rækker.\n\nSøg ham op i Østlige Pestlande. Han holder til i Marsk-gården; af og til strejfer han rundt i de ødelagte ørkener og slagter al Svøben og Alliance-pakket, der krydser hans vej.", c="Den Mørke Dame tror sikkert ikke, at du er værdig til at møde hendes mester. Du er her for at fodre mine hunde, ikke? Der kan ikke være nogen anden grund til denne forstyrrelse."},
  [6001] = {n="Krop og Hjerte", l="Brug Cenarion Månestøvet på Månekinstenen i Auberdin for at fremkalde Måneklo. Derfra skal du møde Måneklo og opnå den styrke i krop og hjerte, den besidder.\n\nTal med Mathrengyl Bjørnegænger i Darnassos, når du er færdig.", d="Direkte øst for Auberdin ligger mange månekin-huler. Den, der ligger tættest på Auberdin, har en Månekinsten inde i sig. Måneklo, stenens forsvarer, vil kun møde dig, når Cenarion Månestøv er påført den. Måneklo besidder en styrke i sig, som du skal bruge som en af Klo-folket.\n\nDu har fortjent retten til at bruge dette Cenarion Månestøv, <Name>... vis mig nu, at du har fortjent retten til at besidde styrken i krop og styrken i hjerte, som kræves af en druide!", p="Når du har mødt den udfordring, der ligger foran dig, vil din forståelse af styrke i krop og styrke i hjerte være fuldt udfoldet. Indtil da kan jeg ikke hjælpe dig yderligere.", c="Du har endelig taget dit store skridt ind i en langt større verden, <Name>. Jeg fornemmer Den Store Bjørneåndens lærdom i dig, og jeg fornemmer, at du har modtaget den styrke, Måneklo besad.\n\nDer er ingen forhindringer tilbage på din vej... lad mig nu lære dig, hvad det betyder at være en Klo-druide!"},
  [6002] = {n="Krop og Hjerte", l="Brug Cenarion Lunarstøvet på Månekinstenen mellem Mulgorr og Ødemarken for at fremkalde Måneklo. Derfra skal du møde Måneklo og opnå den styrke i krop og hjerte, den besidder.\n\nTal med Turak Runestav i Tordenskrænten, når du er færdig.", d="På landet vest for Tauraj i Ødemarken - lige før det bliver til Mulgorr - ligger en Månekinsten. Månekinerne er særlige bæster, der ikke er hjemmehørende i disse egne. Måneklo, stenens forsvarer, vil møde dig, når Cenarion Lunarstøv er påført den. Måneklo besidder en styrke i sig, som du skal bruge som en af Klo-folket.\n\nDu har fortjent retten til at bruge dette Cenarion Lunarstøv, <Name>... vis mig nu, at du har fortjent retten til at besidde styrken i krop og styrken i hjerte, som kræves af en druide!", p="Når du har mødt den udfordring, der ligger foran dig, vil din forståelse af styrke i krop og styrke i hjerte være fuldt udfoldet. Indtil da kan jeg ikke hjælpe dig yderligere.", c="Du har endelig taget dit store skridt ind i en langt større verden, <Name>. Jeg fornemmer Den Store Bjørneåndens lærdom i dig, og jeg fornemmer, at du har modtaget den styrke, Måneklo besad.\n\nDer er ingen forhindringer tilbage på din vej... lad mig nu lære dig, hvad det betyder at være en Klo-druide!"},
  [6004] = {n="Uafsluttet Forretning", l="Dræb 2 Skarlagenrøde Medicinere, 2 Skarlagenrøde Jægere, 2 Skarlagenrøde Magier og 2 Skarlagenrøde Riddere, før du vender tilbage til Kirsta Dybskygge i Vestlige Pestlande.", d="Jeg blev sendt som spejder for at gøre skade og vurdere styrken i Hjertedals forsvar. Nogle i Alliancen mener, at den lille by har mere end historisk betydning. Det er ikke min opgave at spørge, hvad den betydning er, men uanset hvad er jeg ikke i form til at fortsætte, før jeg har hvilet mig.\n\nHvis du er villig, betaler jeg rundhåndet for lidt hjælp. Start syd for her, ved deres lejr nær det lille bolværk, de har opstillet. Hvis du beviser, at du er stærk nok, kan jeg måske få din hjælp med mit hovedformål.", p="Hvordan går det, <Name>? Er de stærkere, end du troede? Det håber jeg ikke. Hvis jeg skal følge det her igennem, kræver det en pokkers masse mere styrke, end hvad jeg allerede har bedt dig om.", c="Godt gået, <Name>. Jeg er forbløffet over, at du klarede dem så hurtigt. Tak.\n\nJeg har endnu ikke mødt nogen, der går ind for Skarlagenrøde Korstog og deres metoder. Jeg tror på Lyset lige så meget som alle andre i Stormvind, men de har vist, at de kun vil dræbe alle, der ikke er loyale over for deres bevægelse... selv uskyldige."},
  [6021] = {n="Zældarr den Udstødte", l="Bring Zældarrs hoved til Plejer Alen ved Lysets Håb-kapellet.", d="Kan du tro det? Efter alle besværlighederne i pestlandene... skal vi også bekymre os om tyve? Og ikke bare almindelige tyve, trolltyve.\n\nOg ikke bare almindelige trolltyve. Døde trolltyve!\n\nDe ledes af en stor, død troll ved navn Zældarr den Udstødte, og de kommer hertil om natten og stjæler lig fra graven nedenunder og tager dem med tilbage til deres onde, døde trolle-skjulested - Underkrypten mod vest.\n\nGå derhen og tag Zældarr af dage, <Name>. Jeg er dødsensyg af hans ugerninger!", p="Fandt du skjulestedet, <Name>? Fik du taget hånd om Zældarr?", c="Fantastisk, du fik ham! Og jeg håber, du også lærte hans bande en lektion!"},
  [6022] = {n="At Dræbe Med Formål", l="Rejs mod øst til Corins Kryds og slagt Svøben, der holder til i byen. Saml 7 stykker Levende Rådne på under 10 minutter. Brug Morter og Stødel til at male det Levende Rådne til Koaguleret Rådne.", d="Du dræber med formål, mens du bliver på min gård.\n\nDin første opgave er at fodre mine hunde.\n\nTag denne morter og stødel og rejs til Corins Kryds. Når du er der, finder du et rigt udvalg af Svøben at slagte. Fra deres friske kroppe har jeg brug for levende rådne. Tag det levende rådne og mal det i morteren, og lad det så stivne. Bring det stivnede rådne tilbage hertil.\n\nOg tosse, forstå at levende rådne fra de døde ikke forbliver 'levende' ret længe. Du må dræbe hurtigt!", p="Græder du? Hvis det her er for 'kedeligt' for dig, 'helt', så anbefaler jeg, at du går tilbage til Den Mørke Dame og fortæller hende om den forfærdelige behandling, du har fået på min gård.\n\nNu skal du komme ud af mit syn!", c="Skuffende. Jeg håbede, at jeg i stedet ville fodre dig til mine hunde.\n\n<Nathanos sukker.>\n\nTja, i det mindste får de noget at spise."},
  [6023] = {n="Uafsluttet Forretning", l="Dræb Jægermester Radley og Kavaler Durgen, før du vender tilbage til Kirsta Dybskygge i Vestlige Pestlande.", d="Min egentlige mission var at svække Skarlagenrøde Korstogs udposter og derefter infiltrere Hjertedal for at vurdere deres styrke. Jeg er stadig ikke i form til at gøre det alene, så måske kunne jeg bede dig om at hjælpe mig igen, <Name>? Ud fra de oplysninger, jeg indsamlede, før jeg blev opdaget, har Korstoget to vigtige medlemmer, som er rygraden i deres styrker uden for byen: Jægermester Radley og Kavaler Durgen. Dræb dem, så gør vi fremskridt. De bør være langs Hjertedal-passet uden for selve byen.", p="Har du fundet dem endnu, <Name>? Når de to er taget af dage, kan jeg gå ind i Hjertedal og tage et nærmere kig på deres opstilling. Det kan jeg ikke gøre uden din hjælp. Find venligst Radley og Durgen for mig.", c="Tak, <Name>. Du har været mere hjælp, end jeg havde håbet på. Luften her ser ud til at suge min vilje ud af mig. Jeg føler mig træt, og jeg kan mærke, at jeg ikke bliver bedre, jo længere jeg er her.\n\nJeg er ikke helt sikker på, hvordan jeg skal infiltrere Hjertedal selv og rapportere om, hvor stærk Skarlagenrøde Korstogs tilstedeværelse er.\n\nMen det er en anden sag. Før du går, så tag dette... som betaling for din hjælp. Tak igen."},
  [6024] = {n="Hamejas Bøn", l="Dræb Infiltratør Hameja. Brug hans nøgle på Jordhøjen bag Underkrypten.", d="Dræb mig. Før det er for sent.\n\nJeg er Hameja. Mens jeg rejste til Zul'Maskar, spiste mine brødre og jeg noget dårligt kød... og vi forandrede os. Vi er smittet.\n\nJeg kan nu høre liskens ord, der opfordrer mig til at nå Zul'Maskar og smitte flere af mit folk. Jeg kan ikke modstå, og derfor skrev jeg denne rulle, før min vilje forlod mig.\n\nJeg begravede en kiste i jorden ved siden af en vogn bag denne krypt, men kun min nøgle kan åbne den. Jeg har nøglen. Hvis du vil have min skat, så find mig.\n\nDræb mig. Før det er for sent.", p="Denne begravede kiste er sikkert låst.", c="Hamejas kiste er åbnet!!"},
  [6025] = {n="Uafsluttet Forretning", l="Gå ind i Hjertedal og find et højt udsigtspunkt, hvorfra du kan se byen og vurdere Skarlagenrøde Korstogs styrke. Vend derefter tilbage til Kirsta Dybskygge i Vestlige Pestlande.", d="Hvad? Virkelig? Vil du vide mere? Men du har allerede gjort så meget for mig, <Name>. Jeg kunne umuligt bede dig om at gå ind i Hjertedal selv på mine vegne.\n\nEr du sikker, <Name>? Hjertedal er meget farligere end passet - jeg kan hverken give dig nogen beskyttelse eller engang information om, hvad du kan møde.\n\nNå, hvis du virkelig er villig til at hjælpe, så gå ind i byen og find et højt sted, hvorfra du kan få et godt overblik. Derfra kan du vurdere deres antal og rapportere dem tilbage til mig. Men vær forsigtig....", p="Det er en farlig opgave, <Name>. Jeg misunder dit mod.", c="Du har gjort det, <Name>! Tak!\n\nJeg vender tilbage til Elling... altså Stormvind, så snart jeg kan. Her, tag denne mønt, det er det mindste, jeg kan gøre for dig. Du er en ære for dit folk, <Name>. Tak, og held og lykke."},
  [6026] = {n="Det Er At Bede Om Meget", l="Røgy LaRue vil have, at du skaffer 2 Thoriumstænger, 1 Gylden Stang, 8 Højeksplosive Bomber og 8 Ustabile Udløsere.\n\nDu må finde en smed og en ingeniør for at få fat i disse ting.", d="Disse her Sølvdæmringen-folk har bestilt gamle Røgy til at lave lidt nedrivningsarbejde for dem. Røgys mor har ikke opdraget en dum knægt. Når guldmønter bliver slået på bordet, står Røgys tjenester til rådighed. Det er mit motto!\n\nNu ville jeg være villig til at dele provisionen med dig, hvis du er villig til at løbe lidt rundt. Sådan er aftalen: Jeg tager over til Pestskoven og markerer de bygninger, der skal ødelægges. Du samler komponenterne til bomberne. Mød mig her igen, når du har alt. Aftale?", p="Stol på gamle Røgy, <Race>. Belønningen vil være det værd. Disse Sølvdæmringen-folk tøver ikke, når det gælder betaling.", c="Jeg kan betale halvdelen på forhånd og halvdelen, når jobbet er gjort."},
  [6028] = {n="Evigblik-rapporten", l="Lever Evigblik-rapporten til Sølvdæmringens Officer Renhjerte i Kuldevind-lejren, Vestlige Pestlande.", d="Jeg leder efter en ansvarlig person, der kan hjælpe mig med en lille, men ikke desto mindre vigtig sag. Jeg er her som repræsentant for Sølvdæmringens interesser over for Evigblikkets lokale styre. Jeg skal have en fremskridtsrapport til Sølvdæmringens Officer Renhjerte i Kuldevind-lejren; det er et stykke væk herfra, placeret langs den sydlige kant af Vestlige Pestlande.\n\nHvis jeg må være så fræk - dette ville være en perfekt måde at præsentere dig selv for min foresatte og måske tjene noget arbejde fra hende!", p="Hilsner, <Class>. På vegne af Sølvdæmringen tilbyder jeg dig sikkerhed og ly, mens du er her i Kuldevind-lejren. Jeg har måske også noget arbejde til dig...", c="Meget snalde, Gregor er. Han har beskæftiget sig med Dampsnedige Kartellet i nogen tid nu og er blevet ekspert i kobold-forhandlingernes 'kunst'. Det er rigtigt, at koboldernes primære loyalitet ligger hos dem med de største pengepunge, men de kender også og respekterer værdien af diplomati. Hvis noget, giver det dem gengangere...\n\nUnder alle omstændigheder anerkender Sølvdæmringen din indsats. Tag venligst dette, med vores tak."},
  [6029] = {n="Evigblik-rapporten", l="Lever Evigblik-rapporten til Sølvdæmringens Officer Grusch ved Bolværket, Vestlige Pestlande.", d="Jeg leder efter en ansvarlig person, der kan hjælpe mig med en lille, men ikke desto mindre vigtig sag. Jeg er her som repræsentant for Sølvdæmringens interesser over for Evigblikkets lokale styre. Jeg skal have en fremskridtsrapport til Sølvdæmringens Officer Grusch ved Bolværket; det er et stykke væk herfra, placeret langs den vestlige kant af Vestlige Pestlande, øst for Tirisfal-slettene.\n\nHvis jeg må være så fræk - dette ville være en perfekt måde at præsentere dig selv for min foresatte og måske tjene noget arbejde fra ham!", p="Hilsner, <Class>. På vegne af Sølvdæmringen tilbyder jeg dig sikkerhed og ly, mens du er her ved Bolværket. Jeg kan også give dig chancen for at kæmpe for en sag, der er værd at kæmpe for!", c="Snalde for at være et menneske, Gregor er. Han har beskæftiget sig med Dampsnedige Kartellet i nogen tid nu og er blevet ekspert i kobold-forhandlingernes 'kunst'. Det er rigtigt, at koboldernes primære loyalitet ligger hos dem med de største pengepunge, men de kender også og respekterer værdien af diplomati. Hvis noget, giver det dem gengangere...\n\nUnder alle omstændigheder anerkender Sølvdæmringen din indsats. Tag venligst dette, med vores tak."},
  [6030] = {n="Hertug Nikolaj Zverenhoff", l="Lever bogen \"Studier i Åndetale\" til Hertug Nikolaj Zverenhoff ved Lysets Håb-kapellet, Østlige Pestlande.", d="En tilbagetrukken medium, der holder til i disse egne, ved navn Skyggranse, har forsynet Sølvdæmringen med et litterært mesterværk... et, der nok er den største samling af vrøvl, jeg nogensinde har set skrevet.\n\nEn af Sølvdæmringens mest respekterede ledere, Hertug Nikolaj Zverenhoff, er en genial sprogkender. Kunne du tage dette til ham for mig - for en belønning, selvfølgelig? Lysets Håb-kapellet - det er der, han befinder sig lige nu, langt ude i den østlige del af Østlige Pestlande.", p="Må Lyset guide dig i disse urolige tider, <Class>. Hvad bringer dig hertil, til dette håbets fyrtårn midt i mørke og fortvivlelse?", c="Dette... dette er en meget speciel bog, du har bragt mig. Jeg vil gerne sige, at \"speciel\" i dette tilfælde betyder \"unik og muligvis oplysende\", men det må tiden vise.\n\n\"Ooooooo?\" Hvem i sin rette besindelse finder på sådan noget?\n\nNå, jeg har hørt om denne Skyggranse, som Gregor nævnte, så det er ikke uden værdi. Jeg vil gøre mit bedste for at tyde den. Og til dig... vær venlig at tage dette - med Sølvdæmringens hilsen. Mens du er her, er der måske nogle andre ting, du kan hjælpe os med."},
  [6031] = {n="Runeklæde", l="Bring 30 Runeklæde til Mejlosh i Tømmermave Greb.", d="I Tømmermave er vi tilfredse. Vi bryder os ikke om fremmede. Det er godt for os, men dårligt for handelen.\n\nFor ikke længe siden kom en sjælden nattenisse-ven til Tømmermave, og hun bar en kappe af runeklæde. Runeklæde er sjældent blandt os, men kappen var så fin, at mit folk vil have mig til at lave mere runeklædning.\n\nVil du bringe mig runeklæde? Hvis du bringer nok, så giver jeg dig noget til gengæld.", p="Har du runeklædet? Mit folk er ivrige efter flere ting af runeklæde!", c="Ah, du bragte klædet. Sådan et fint materiale!\n\nTak, <Name>. Du er en sand ven. Tag venligst dette til gengæld."},
  [6032] = {n="Helligt Klæde", l="Bring 2 Månestof til Mejlosh i Tømmermave Greb.", d="Selvom folket i Tømmermave nyder følelsen af runeklæde, er det ikke helligt for os. Men månestof er helligt.\n\nBring mig en lille forsyning af dette hellige klæde, så lærer jeg dig en hemmelig syteknik.", p="Har du bragt månestoffet, <Name>?", c="Ah, meget godt. Dette månestof vil blive brugt til klæder, der er hellige for vores folk. Tak, <Name>. Nu vil jeg træne dig."},
  [6041] = {n="Når Røgeren synger, bliver jeg voldsom", l="Rejs til Pestskoven, nordvest for Lysets Håb. Ødelæg 8 Svøben-konstruktioner ved at bruge Røgerens Special-blanding ved Detonationsmærket, der er plantet inde i hver bygning. Røgeren har fået markeret Ziggurater og Slagterhuse.\n\nNår du har plantet bomben, skal du forlade bygningen og undre dig over dit håndarbejde.\n\nForresten er Røgerens Special-blanding temmelig... ustabil.", d="Mens du samlede forsyningerne, fik jeg nogle af mine folk til at markere de Svøben-bygninger, vi skal have revet ned.\n\nHer er planen: Jeg vil give dig ti pinde af min specielle blanding. Du skal tage dem med til Pestskoven og plante dem inde i de Svøben-konstruktioner, som jeg har fået markeret til detonation.\n\n<Røgeren klikker med fingrene.>\n\nBing! Det er bare så nemt.", p="Jeg har forsyninger tilbage til at lave et par flere pinde af den specielle blanding. Lad bare gamle Røgeren vide, hvis du får brug for flere.", c="Du er meget mørkere, end jeg husker dig. Du har fået det look, der siger: 'Jeg er blevet svedet af en eksplosiv bombe.'\n\n<Røgeren griner.>\n\nUnder alle omstændigheder! Her er din andel af byttet. Jeg har lagt en lille ekstra ting i for at lindre brandsårene."},
  [6042] = {n="Un-Livets små irritationer", l="Dræb 20 Giftige Pestflagermus og 10 Monstrøse Pestflagermus. Vend tilbage til Nathanos Pestkalder, når du er færdig.", d="Du kan ikke tage to skridt uden for denne gård uden at løbe ind i en af de irriterende flagermus. Jeg vil kunne tage hundene med ud og slagte Svøben uden at blive generet af nogle forbandede, beskidte flagermus. Naturligvis har jeg bedre ting at tage mig til end at dræbe flagermus dag ud og dag ind. Det har du dog.\n\nHvad? Din træning? Det er din træning! Nu skal du komme mig af syne og ikke vende tilbage, før du har dræbt et ordentligt antal af de vingede dæmoner. Undlad at skuffe mig.", p="Det kunne have været værre. Jeg kunne have fået dig til at samle flagermus-guano.\n\n<Nathanos stirrer eftertænksomt på dig.>\n\nHrm... Hov! Vent lige. Hvor skal du hen?", c="Det er utroligt, hvad lidt vrede og raseri kan udrette."},
  [6061] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Voksen Slettegænger. Øv dine færdigheder, og returner derefter Tæmmestaven til Yaw Skarpmanke i Blodhov-landsbyen.", d="Som medlem af tyrefolket er det vigtigt at følge vore forfædres traditioner ved at bekæmpe mægtige væsener. Ved at besejre disse væsener kan vi optage deres ånder og komme tættere på Jordmoderen.\n\nPå samme måde hjælper det os med at blive ét med naturen omkring os at tæmme et udyr, der kæmper ved vores side. Til sidst lærer du at tæmme et udyr efter eget valg. Men alt kræver øvelse, og du har meget at lære. Begynd med at tage denne tæmmestav; du skal tæmme en voksen slettegænger.", p="Øv dine færdigheder, <Name>. Tæm den voksne slettegænger.", c="Jordmoderen har sendt mig tegn; du har gjort det godt."},
  [6062] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme et Frygtindgydende Plettet Vildsvin. Øv dine færdigheder, og returner derefter Tæmmestaven til Tottar i Barberbakken.", d="Det er en beundringsværdig færdighed at have sin autoritet over naturen. Som jæger skal du stræbe efter at lære at bruge kraften og styrken, der findes i ethvert væsen, du selv vælger.\n\nAt få kontrol over et dyr er ingen let bedrift; det er en opgave, du må påtage dig med megen beslutsomhed.\n\nTil din første opgave skal du tage denne tæmmestav og bruge den til at tæmme et frygtindgydende plettet vildsvin. Du finder dem ganske tæt på Barberbakken. Øv dine færdigheder i kamp med vildsvinet ved din side, og vend derefter tilbage til mig.", p="Held og lykke, unge jæger.", c="Du har gjort det godt, <Name>. Jeg tror, du er klar til din næste opgave."},
  [6063] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Spindelvævsskov-lurer. Øv dine færdigheder, og returner derefter Tæmmestaven til Dasalar i Dolanår.", d="Som jæger er det vigtigt at huske det ansvar, du har i dine hænder. Naturen er ikke en kraft, der kan bøjes til at adlyde vores ønsker; den skal respekteres og anerkendes som noget stærkere end din egen eksistens.\n\n<Name>, du må bevise, at du forstår dette, før du får evnen til at tæmme et dyr, der kan blive din ledsager.\n\nDin første opgave er at tage denne tæmmestav. Med den vil du kunne tæmme en spindelvævsskov-lurer. Tæm den, og øv dine færdigheder som jæger.", p="Du vil lære, <Name>, og en dag bliver du en stor jæger.", c="Fremragende, <Name>! Du lærer hurtigt."},
  [6064] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme et Stort Klippevildsvin. Øv dine færdigheder, og returner derefter Tæmmestaven til Grib Vildthjerte i Kharanøs.", d="Hej der, knægt! Så du vil gerne vide, hvordan du kan få et kæledyr?\n\nNu skal vi i gang. Der er intet vigtigere end dit udstyr, når det gælder jagt, men vi kan snakke om min nye Granatsplinter-Blaster en anden gang. For nu lad os fokusere på noget, jeg er sikker på, du er ret interesseret i: et kæledyr!\n\nDen bedste måde at lære på er, at du prøver flere væsener som ledsagere og ser, hvad du kan lide. Så find et stort klippevildsvin, og brug derefter tæmmestaven til at tæmme det.", p="Bare rolig, pige! Du får lov at prøve et par stykker, før du skal vælge kun ét.", c="Jeg ved det, jeg ved det; du spekulerer på, hvad der er næste, ikke sandt?!"},
  [6065] = {n="Jægerens Vej", l="Tal med Yaw Skarpmanke i Blodhov-landsbyen.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Yaw Skarpmanke i Blodhov-landsbyen. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror virkelig, du er klar..."},
  [6066] = {n="Jægerens Vej", l="Tal med Yaw Skarpmanke i Blodhov-landsbyen.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Yaw Skarpmanke i Blodhov-landsbyen. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror virkelig, du er klar..."},
  [6067] = {n="Jægerens Vej", l="Tal med Yaw Skarpmanke i Blodhov-landsbyen.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Yaw Skarpmanke i Blodhov-landsbyen. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror virkelig, du er klar..."},
  [6068] = {n="Jægerens Vej", l="Tal med Tottar i Barberbakken.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Tottar i Barberbakken. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, nu er det tid for dig at begynde din træning."},
  [6069] = {n="Jægerens Vej", l="Tal med Tottar i Barberbakken.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Tottar i Barberbakken. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror, du er klar til at blive trænet..."},
  [6070] = {n="Jægerens Vej", l="Tal med Tottar i Barberbakken.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Tottar i Barberbakken. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, nu er det tid for dig at begynde din træning."},
  [6071] = {n="Jægerens Vej", l="Tal med Dasalar i Dolanår.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Dasalar i Dolanår. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, nu er det tid, <Class>."},
  [6072] = {n="Jægerens Vej", l="Tal med Dasalar i Dolanår.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Dasalar i Dolanår. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror, at nu er det tid..."},
  [6073] = {n="Jægerens Vej", l="Tal med Dasalar i Dolanår.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Dasalar i Dolanår. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, nu er det tid, <Class>."},
  [6074] = {n="Jægerens Vej", l="Tal med Grib Vildthjerte i Kharanøs.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Grib Vildthjerte i Kharanøs. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror også, du er klar...."},
  [6075] = {n="Jægerens Vej", l="Tal med Grib Vildthjerte i Kharanøs.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Grib Vildthjerte i Kharanøs. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror også, du er klar...."},
  [6076] = {n="Jægerens Vej", l="Tal med Grib Vildthjerte i Kharanøs.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal opsøge Grib Vildthjerte i Kharanøs. Han kan sætte dig på vejen til at få et kæledyr af din egen.", c="Ja, jeg tror også, du er klar...."},
  [6081] = {n="Træning af udyret", l="Tal med Ormak Grimskud i Orgrimgrad.", d="Du har nu evnen til at tæmme et kæledyr, men du må også opnå færdighederne til at træne det.\n\nRejs til Orgrimgrad. Der skal du tale med en af vores mest respekterede jægere, Ormak Grimskud. Han vil give dig evnen til at træne dit nye kæledyr. Du finder ham nær Modighedens Hal.\n\nHeld og lykke, <Name>.", c="En ung jæger, ser jeg. Ja, jeg vil give dig de færdigheder, du skal bruge for at træne og lede dit kæledyr. Du vil ikke kun kunne lære dit kæledyr nye evner, du vil nu også kunne fodre det og genoplive det, hvis det falder i kamp.\n\nNu, af sted, jæger. Vi taler sammen igen på et senere tidspunkt."},
  [6082] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Pansret Skorpid. Øv dine færdigheder, og vend derefter tilbage til Tottar i Barberbakken.", d="Det sidste væsen, du skal tæmme, er et, du bør stræbe efter at efterligne: den pansrede skorpid. Den angriber hurtigt og selvsikkert; at kontrollere en kraft som denne er din skæbne som jæger.\n\nNår du vender tilbage, vil jeg give dig de færdigheder, du skal bruge til at tæmme et dyr efter eget valg; dette væsen vil være dit at befale. Under din kontrol vil dit kæledyr få erfaring sammen med dig. Jeg vil også vise dig, hvordan du kalder det og afskediger det, som du ønsker.", p="Lykkedes det dig at tæmme skorpiden?", c="Du har lært alt, hvad jeg kan lære dig, <Name>. Nu er det tid for dig at tage det, du har lært her, og vælge et kæledyr af din egen.\n\nVær så god, <Name>. Nu giver jeg dig evnen til at tæmme et udyr, samt at kalde det og afskedige det, som du finder passende. Brug dine nye færdigheder med stolthed; du har fortjent dem."},
  [6083] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Brænding-kryber. Øv dine færdigheder, og returner derefter Tæmmestaven til Tottar i Barberbakken.", d="Den fordel, et kæledyr giver dig over for dine rivaler, er noteret, <Name>. Når du får kontrol over et andet væsen, styrker du din egen styrke. Dit kæledyr må blive en forlængelse af dig selv.\n\nDen næste opgave kræver, at du vender ryggen til landjorden; du finder det næste væsen i vandet ud for kysten. Lige over for Sen'jin-landsbyen, nær Ekkoøerne, skal du lede efter en livlig krabbe ved navn brænding-kryber. Brug tæmmestaven til at tæmme den, og øv derefter dine færdigheder.", p="Du skal øve dig for at få de færdigheder, du skal bruge for at kontrollere dit kæledyr effektivt. Har du tæmt en brænding-kryber?", c="Du er en hurtig lærling, <Name>. Du har gjort det godt."},
  [6084] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Sneleopard. Øv dine færdigheder, og vend derefter tilbage til Grib Vildthjerte i Kharanøs.", d="De klippevildsvin er ret kraftige; måske vil du have noget med lidt mere finesse? Fint nok, så har jeg lige det rigtige. Syd og øst herfra finder du store hvide katte, der kaldes sneleoparder. Ligesom en elegant udskåret riffel gemmer der sig bag deres smukke ydre en kraftfuld kæmper, der er i stand til at forvolde ekstrem skade. Du vil synes, de er meget smidigere og hurtigere end vildsvinet, du tæmmede.\n\nTag denne tæmmestav og se, hvad du synes om sneleoparden.", p="Hvad synes du om sneleoparden, <Name>?", c="Når jeg føler, du har lært nok, vil jeg give dig evnen til at vælge ethvert kæledyr efter din smag."},
  [6085] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Isklo-bjørn. Øv dine færdigheder, og returner derefter Tæmmestaven til Grib Vildthjerte i Kharanøs.", d="Måske vil du have et væsen, der kun besidder rå styrke. Isklo-bjørnen er en fremragende ledsager for en spirende jæger som dig og kan findes øst for Kharanøs. Her er tæmmestaven; prøv dette dyr som kæledyr, og se, om du kan lide det!\n\nNår du vender tilbage, giver jeg dig de færdigheder, du skal bruge for at tæmme et dyr efter eget valg; dette væsen vil møde de udfordringer, du møder, og få erfaring sammen med dig. Jeg vil også vise dig, hvordan du kalder det og afskediger det, som du ønsker.", p="Har du tamt isklo-bjørnen endnu?", c="Her er du, <Name>. Nu giver jeg dig evnen til at tæmme et udyr, samt at kalde det og afskedige det, som du ønsker.\n\nFind dig selv en god, loyal ledsager, og nyd jagten!"},
  [6086] = {n="Træning af udyret", l="Tal med Belia Tordengranit i Jernsmede.", d="<Name>, du har nu evnen til at tæmme et kæledyr, men du må også opnå færdighederne til at træne det.\n\nRejs til Jernsmede og find Våbenhallen. Der skal du tale med en af vores mest respekterede dyretrænere, Belia Tordengranit. Hun vil give dig evnen til at træne dit nye kæledyr, så kom afsted, knægt!\n\nBelia er en venlig type; du bør ikke have problemer med at vinde hendes godkendelse. Held og lykke, <Name>.", c="En ny rekrut, hva'? Du er på vej til at blive en stor <Class>, kan jeg se.\n\nJa, jeg kan give dig de færdigheder, du skal bruge for at træne og lede dit kæledyr. Du vil ikke kun kunne lære dit kæledyr nye evner, du vil nu også kunne fodre det og genoplive det, hvis det falder i kamp.\n\nHusk, at nøglen til at få mest muligt ud af dit nye kæledyr er at respektere det og behandle det godt. Til gengæld vil dit kæledyr blive din mest loyale ven."},
  [6087] = {n="Tæmning af udyret", l="Brug Tæmmestaven til at tæmme en Prærie-sniger. Øv dine færdigheder, og returner derefter Tæmmestaven til Yaw Skarpmanke i Blodhov-landsbyen.", d="Du har en livlig ånd, jæger, og venter ivrigt på din næste udfordring.\n\nDin næste opgave er at vinde selskab af en ulv, der kaldes prærie-sniger. Dette væsen er hurtigt og frygtløst; når du tager dette udyr som kæledyr, må du også tage disse egenskaber på dig.\n\nUnder en kamp vil du lære, hvordan du og dit kæledyr bliver et hold. Til sidst må I arbejde som ét, muskel mod muskel.\n\nHer er tæmmestaven, <Name>. Tæm en prærie-sniger og øv dine færdigheder.", p="Har du fundet en prærie-sniger?", c="Ja... Jordmoderen mener, at du er klar til den næste lektion."},
  [6088] = {n="At tæmme udyret", l="Brug Tæmmestaven til at tæmme en Svæver. Øv dine evner, og giv derefter Tæmmestaven tilbage til Yaw Skarpmanke i Blodhov-landsbyen.", d="Den sidste opgave, jeg har til dig, kræver, at du tæmmer en skabning, der holder til på himlen. Svæveren er en svær modstander, men som din allierede vil du få dens skarpe angreb og truende nærvær.\n\nVed Jordmoderens vilje vil jeg, når du vender tilbage, give dig de evner, du skal bruge for at tæmme et dyr efter eget valg som din ledsager; dette væsen vil stå over for de udfordringer, du står over for, og opnå erfaring sammen med dig. Jeg vil også vise dig, hvordan du kalder det og afskediger det, som du ønsker.", p="Du bliver snart klar, <Name>.", c="Du har lært alt, hvad jeg kan lære dig, <Name>. Må Jordmoderens velsignelser lede dig i valget af et kæledyr.\n\nVær så god, <Name>. Jeg giver dig nu kraften til at tæmme et udyr, samt til at kalde det og afskedige det, som du finder passende. Brug dine nye evner med stolthed, og ær Jordmoderen."},
  [6089] = {n="At træne udyret", l="Tal med Holt Tordenhorn på Jægerhøjen i Tordenskrænt.", d="Du har nu kraften til at tæmme et kæledyr, men du må også lære at træne det.\n\nRejs til Tordenskrænt. Der skal du tale med en af vores mest respekterede jægere, Holt Tordenhorn. Hvis han finder dig værdig, vil han give dig evnen til at træne dit nye kæledyr.\n\nHolt har besejret de mest magtfulde og frygtede udyr i Azeroth, og han befaler selv mange stærke væsener. Hans bånd til Jordmoderen er stærke, og du kan lære meget af ham. Held og lykke, <Name>.", c="En ung <Class>, ser jeg. Ja, jeg kan give dig de færdigheder, du skal bruge for at træne og lede dit kæledyr. Du vil ikke kun kunne lære dit kæledyr nye evner, du vil nu også kunne fodre det og genoplive det, hvis det falder i kamp.\n\nNu, drag afsted. Må Jordmoderen lede dig på din vej. Vi taler sammen igen på et senere tidspunkt."},
  [6101] = {n="At tæmme udyret", l="Brug Tæmmestaven til at tæmme en Natsabel-snigeren. Øv dine evner, og giv derefter Tæmmestaven tilbage til Dasalar i Dolanår.", d="Naturens variation er noget, man kan stole på, <Name>. Den er forudsigelig på den måde, at den aldrig forbliver den samme; den er altid under forandring.\n\nDe opgaver, jeg giver dig, vil hjælpe dig med at se og værdsætte de enorme forskelle mellem de væsener, du kan vælge som din ledsager.\n\nTag denne tæmmestav og brug den til at tæmme en natsabel-sniger, som findes mod syd. Øv dine evner som jæger. Så begynder du at forstå ligheder og forskelle i naturen.", p="At forstå balancen mellem naturen og en selv er en livsstil for hver eneste nattenisse.", c="Jeg ser din hengivenhed, og at du har forstået det, jeg har lært dig, <Name>."},
  [6102] = {n="At tæmme udyret", l="Brug Tæmmestaven til at tæmme en Strigid-skriger. Øv dine evner, og giv derefter Tæmmestaven tilbage til Dasalar i Dolanår.", d="Du har tæmmet to væsener, der lever på landjorden, nu må du tæmme et, der svæver over himlen. Brug tæmmestaven til at tæmme en strigid-skriger, der findes vest for her. Øv dine evner med denne mægtige ugle ved din side.\n\nNår du vender tilbage, vil jeg give dig de evner, du skal bruge for at tæmme et dyr efter eget valg som din ledsager; dette væsen vil stå over for de udfordringer, du står over for, og opnå erfaring sammen med dig. Jeg vil også vise dig, hvordan du kalder det og afskediger det, som du ønsker.", p="Jeg er stolt af dine bedrifter, <Name>. Har du fuldført den sidste opgave, jeg gav dig?", c="Du har lært alt, hvad jeg kan lære dig, <Name>. Må jeg give dig ét råd mere: vær kritisk, når du vælger dit første kæledyr. Vil du vælge et væsen fra landjorden, fra vandet eller fra himlen? Uanset hvad, vil dit kæledyr uden tvivl være hos dig i ganske lang tid.\n\nVær så god, <Name>. Jeg giver dig nu kraften til at tæmme et udyr, samt til at kalde det og afskedige det, som du finder passende. Brug dine nye evner med stolthed; du har fortjent dem."},
  [6103] = {n="At træne udyret", l="Tal med Jokaste i Cenarion-enklaven i Darnassos.", d="Du har nu kraften til at tæmme et kæledyr, men du må også lære at træne det.\n\nRejs til Darnassos. Der skal du tale med en af vores mest respekterede jægere, Jokaste. Hun vil give dig evnen til at træne dit nye kæledyr, så skynd dig.\n\nSelvom Jokaste kan virke streng, er hun altid glad for at se en anden jæger stige i graderne. Vis hende respekt, så vil hun gengælde det. Held og lykke, <Name>.", c="En spirende jæger, ser jeg. Ja, jeg kan give dig de færdigheder, du skal bruge for at træne og lede dit kæledyr. Du vil ikke kun kunne lære dit kæledyr nye evner, du vil nu også kunne fodre det og genoplive det, hvis det falder i kamp.\n\nHusk, <Name>, respekter altid balancen og lev i ærefrygt for naturen omkring dig. Nu, drag afsted. Vi taler sammen igen på et senere tidspunkt."},
  [6125] = {n="Magt over gift", l="Vend tilbage til Mathrengyl Bjørnegænger i Cenarion-enklaven, Darnassos.", d="Du har lært, hvad det betyder at kurere gift uden hjælp fra åndelige kræfter. Husk, hvad andre må udholde, når de kæmper mod giftige sygdomme, mens du snart omfavner din nyfundne magt over gift.\n\nDu bør nu vende tilbage til Mathrengyl Bjørnegænger i Darnassos, <Name>. Han har uden tvivl en meget vigtig besværgelse at lære dig nu, hvor eleven har forstået lektionen, der blev givet ham.\n\nFarvel, unge druide. Vi taler sammen igen.", c="Velkommen tilbage - jeg har fulgt dine fremskridt med denne lektion, siden du forlod os, og jeg må indrømme, at jeg blev overrasket over at høre om situationen i Auberdin. Dette fortjener yderligere undersøgelse, for indførelsen af sådanne gifte i miljøet er yderst foruroligende for balancen.\n\nDu klarede dig med ynde under pres. Der findes ingen bedre belønning, end evig magt over gift. Brug den godt, <Name>... brug den godt."},
  [6132] = {n="Hent mig herfra!", l="Eskortér Melisa Brumbuzzle, og tal derefter med Hornsnurr Brumbuzzle ved Kodo-kirkegården i Forødelse.", d="Hent mig herfra!\n\nJeg kom op til Spydenes Dal for at tale med Marodørerne. Jeg troede, jeg kunne lave lidt forretning med dem... men de vil ikke tale! Jeg tror, de vil spise mig!\n\nHent mig herfra, så betaler min bror Hornsnurr dig godt! Han er i vores lejr ved siden af kodo-kirkegården, mod øst.\n\nLad os skynde os, <Name>. For ikke to minutter siden hørte jeg nogle kentaurer tale om at skaffe træ til deres gryde...", p="Har du set min søster Melisa? Hun er altid på farten, og det får hende i problemer hele tiden.", c="Min søster Melisa sagde, at du ville komme. Tusind tak, fordi du hjalp hende ud af klemmen, hun var i; det er en skam, at hun sikkert allerede har fundet sig selv i en ny!"},
  [6133] = {n="Skovvogterlordens befaling", l="Rejs til de nordlige grænser af de Østlige Pestlande, og hent Quel'Thalas-registret. Genstanden befinder sig et sted i Quel'Lithien-logen.\n\nDu skal også nedslå 8 Skovvogtere, 8 Stigløbere og 8 Skovmænd.", d="De høje alfer i Quel'Lithien-logen har noget, der tilhører mig, <Class>: Et dokument, der beskriver mit liv som dødelig.\n\nFør du spørger; nej, du er bestemt ikke indviet i sådanne oplysninger. Gør bare, som jeg siger, orm: Hent registret.\n\nOg tøsedreng, sørg for at efterlade så megen splid og sorg som muligt i din kølvand. Lad dem lide...", p="Lad mig ikke vente, <Class>.", c="Jeg går ud fra, at du ikke læste registret. Ikke engang du ville gøre noget så idiotisk..."},
  [6134] = {n="Spøgelses-o-plasma-indsamling", l="Bring 8 Spøgelses-o-plasmaer og Kassen med Spøgelsesmagneter til Hornsnurr Brumbuzzle i Forødelse.", d="Der er en dal mod sydøst, Knoglernes Dal, hjemsøgt af Magrom-spøgelser. Lyder skræmmende, ikke sandt? Nå, tænk bare, hvor skræmmende det er for Magrom! Hvis vi fangede spøgelsesenergi fra det sted, vætter jeg, at det ville være mange penge værd for de kentaurer.\n\nVær så god, tag denne kasse med spøgelsesmagneter. Hvis du placerer en mellem de to store skeletter i dalen, De Døde Goliather, så vil spøgelserne vandre hen til den. Hold dig på afstand, fjern spøgelserne og saml deres spøgelses-o-plasma - det er det, vi skal sælge til Magrom.", p="Hvor er min spøgelses-o-plasma, <Name>?", c="Der er den! Ser ud til, at du også fik noget af det på dig. Lidt slimet, hva'?\n\nNå, tusind tak for alt besværet, <Name>. Det her er en formue værd... hvis jeg kan overbevise kentaurerne om, hvad det er!"},
  [6135] = {n="Skumringsvinge, åh hvor jeg hader dig...", l="Find Skumringsvinge og nedslå ham. Hent et Stykke af Skumringsvinges Pels fra kadaveret, og bring det til Nathanos Pestkalder.\n\nDet siges, at Skumringsvinge hærger landskabet nord for Marsk-gården.", d="Indtil nu har du fuldført de missioner, jeg har givet dig; selvom ikke altid i rettidig stand.\n\nJeg antager, at du tror, du er klar til en udfordring. Ja... ja, tøsedreng, måske er du klar til en mere omfattende række missioner.\n\nDen albino dæmon-flagermus, Skumringsvinge, hærger landskabet lige nord for her. Spor ham op og tilintetgør ham. Vend tilbage til mig med et stykke af hans hvide pels, så skal du blive belønnet.", p="Jeg vil ikke anbefale, at du påtager dig denne udfordring alene, <Class>.", c="Fremragende arbejde, tøsedreng. Jeg skal smede denne pels til noget, du kan bruge."},
  [6136] = {n="Den Korpulente", l="Find Borelmadden i de nordlige ødemarker i de Østlige Pestlande, og tilintetgør ham. Vend tilbage til Nathanos Pestkalder, når missionen er fuldført.", d="Forbi Sølvdæmringens lejr Lysets Håb og vest for Nordedal finder du den korpulente maddike-bæst, Borelmadden.\n\nJeg har mistet hele regimenter til det uhyre! Hans størrelse kender ingen grænser! Jo mere han æder, jo større bliver hans omfang...\n\nSelvom jeg ikke ville lide følelsesmæssig skade, hvis udyret fortærer dig, ville jeg foretrække, at du var sejrherren. Jeg anbefaler, at du henter hjælp fra andre til denne mission. Borelmadden har været kendt for at fortære små bataljoner, der var tåbelige nok til at angribe ham.", p="Har jeg fortalt dig for nylig, at jeg hader dig?", c="Bliver du ved sådan her, må jeg måske forfremme dig fra tøsedreng til åndssvag, første klasse."},
  [6141] = {n="Broder Anton", l="Tal med Broder Anton i Forødelse.", d="Min broder i våben, Broder Anton, hørte rygter om en udød-plage i det fjerne Kalimdør, i et land kendt som Forødelse. Anton bookede straks passage til stedet for at søge og tilintetgøre den udøde trussel!\n\nHan leder efter dem med modet og besluttsomheden til at hjælpe ham. Hvis dit hjerte er ærligt, så tal med Anton. Han er i Forødelse, i den alliancevenlige by Nijels Punkt.", c="Jeg har fået besked om hjælp, der ankommer fra øst. Er du kilden til disse rygter? Er du kommet hertil for at hjælpe Skarlagen-broderskabet i dets korstog?\n\nHvis det er tilfældet, så lyt godt efter..."},
  [6142] = {n="Musling som lokkemad", l="Find 10 stykker Blødskallet musling-kød, og bring dem tilbage til Mai'Lahii i Skyggejagt-landsbyen.", d="Du har en fiskers udseende, <Class>! Jeg elsker at fiske - har fisket hele mit liv. Den bedste lokkemad er blødskallet musling-kød; fiskene kan simpelthen ikke modstå den, ved du, hvad jeg mener?\n\nOppe mod nord finder du et forlist skib ud for kysten. Blødskallede muslinger ligger spredt over hele området. Hvis du bringer mig 10 stykker blødskallet musling-kød tilbage, giver jeg dig noget til gengæld.", p="Jeg kan ikke vente med at tage ud at fiske med noget frisk blødskallet musling-kød; bragte du de 10 stykker, jeg har brug for?", c="Perfekt, mon, det er præcis, hvad heksedoktoren sagde, jeg skulle gøre for min hovedpine. Han siger: \"Mai'Lahii - tag ud og fisk. Det får dig til at føle dig bedre\"\n\nNå, jeg har det allerede bedre, tak, mon!"},
  [6143] = {n="Andre fisk at stege", l="Nedslå 7 Slangeblad-myrmidoner, 7 Slangeblad-nagaer og 5 Slangeblad-heksekvinder, og tal derefter med Drulzegar i Skyggejagt i Forødelse.", d="Måske har du hørt det, eller måske ikke... mit mandskab og jeg var ude at fiske nær Ranazjar-øen, nord for det forliste skib ud for kysten mod nord. Vi plejede at fiske der hele tiden; nu er alt, hvad jeg gør, at tænke på en måde at søge hævn for mine faldne kammerater.\n\nNagaerne angreb os en morgen og dræbte alle undtagen mig.\n\nMit samvittighed kan ikke klare skylden, <Class>; jeg har brug for, at du går og steger dem, nagaerne, for mig. Jeg vil gøre indsatsen umagen værd; tror du, at du kan hjælpe mig med det?", p="Jeg hører stadig deres stemmer råbe om hjælp, da nagaerne løsnede deres kaos over os. Havde jeg ikke dette dårlige knæ, ville jeg gå og hjælpe dig med at dræbe de forbandede naga!\n\nDu kan som regel være sikker på at finde dem dybt nede i korallerne under overfladen... lurende... planlæggende...", c="Det er lige så sødt at høre nyheden om, at nagaerne er blevet besejret, men mit hjerte føles stadig tomt. Resten af mit liv vil jeg vie mig til at få dem alle dræbt.\n\nVær så god, mon, din belønning, som jeg lovede. Den er lille i forhold til tilfredsstillelsen ved at vide, at nagaerne blev stegt for deres hadefulde handling mod mit mandskab."},
  [6144] = {n="Kaldet til kommando", l="Rejs til Underbyen og tal med Varimatras.", d="Ordren er kommet, <Class>. Varimatras selv har bedt mig om at sende mine 'dygtigste' agenter tilbage til Underbyen for en yderst følsom taktisk operation.\n\nDesværre blev mine dygtigste agenter dræbt for over tre år siden. I deres sted har jeg en samling hjerneløse gadedrenge.\n\n<Nathanos stirrer koldt på dig.>\n\nRejs til Underbyen med det samme og meld dig til Varimatras. Gør mig ikke til grin, <Class>!", c="Den Storslåede Korsfarer sidder sikkert i Skarlagen-bastionen, mens hans styrker strømmer ind i dine lande, ødelægger dine bygninger og monumenter og myrder dit folk.\n\nDen Mørke Dame har befalet mig at tage hånd om dette insekt en gang for alle. Du bliver redskabet for De Forladtes retsopgør."},
  [6145] = {n="Den Karmosinrøde Kurer", l="Vend tilbage til de Østlige Pestlande, og spor Den Karmosinrøde Kurer op. Dræb kureren, og hent den Storslåede Korsfarers Befaling.\n\nBring befalingen til Nathanos Pestkalder for yderligere instruktion.", d="Ligesom kroppen ikke kan overleve uden hovedet, kan hovedet ikke overleve uden kroppen. Skarlagen-korstogets forsvar inde i Stratholm er næsten uigennemtrængeligt. Vi må i stedet skære kroppen væk under hovedet.\n\nMine Dødsstalkere har indsamlet data om korstogets aktivitet uden for Stratholm. Hver dag bliver der sendt en rapport fra deres centrale kommando til Tyrs Hånd. Denne rapport er nøglen, <Race>! Find Den Karmosinrøde Kurer, og hent den rapport. Bring den tilbage til Nathanos.", p="Lykkes du nu, har du næsten fortjent min respekt, <Class>.", c="<Nathanos ler.>\n\nFremragende! Endelig! En mulighed for at tilintetgøre Skarlagen-oraklet!"},
  [6146] = {n="Nathanos' list", l="Rejs til Tyrs Hånd, sydøst for Marsk-gården. Når du er der, skal du tage en bid af det Rådne Æble. Under dække af Skarlagen-korstoget skal du aflevere den Storslåede Korsfarers Befaling til Korsfarer-lord Valdelmar.", d="Jeg har lavet nogle justeringer til denne befaling. Skulle vores lille list lykkes, vil de afsløre Skarlagen-oraklet, og så slår vi til!\n\nNu, hør efter, <Class>. Du skal aflevere denne befaling til Korsfarer-lorden, Valdelmar.\n\nHvordan? Du skal række den til ham, tøsedreng.\n\nTag befalingen og dette rådne æble med til Tyrs Hånd. Når du træder ind i byen, skal du spise æblet. Du vil forvandles til noget mere... spiseligt for menneskene. Tag befalingen og overrække den til Korsfarer-lord Valdelmar.", p="Dette er uacceptabelt, soldat!", c="Hvor har du været? Vi troede, Geisslen havde taget dig til fange."},
  [6147] = {n="Tilbage til Nathanos", l="Vend tilbage til Nathanos Pestkalder med de nye oplysninger.", d="Den Storslåede Korsfarer fremsætter en usædvanlig anmodning. Hrm, uanset... det, han beder om, skal gøres. Vend tilbage til Skarlagen-bastionen, og underret ham om, at Oraklet snart er på vej.\n\nVi vil tage alle forholdsregler for at sikre, at hun når Stratholm ubeskadiget.", c="Tølperne! Mit bedrag blev ikke opdaget! Gør dig klar, <Class>. Vi må slå til med kold snedighed!"},
  [6148] = {n="Skarlagen-oraklet, Demetra", l="Skarlagen-korstoget er på farten. Et sted langs vejen fra Tyrs Hånd til Stratholm finder du Oraklet, Demetra, og hendes følge. Jag hende ned og dræb hende. Vend tilbage til Nathanos Pestkalder, hvis du lykkes.", d="Demetra er chefrådgiver for den Storslåede Korsfarer. Hun kaldes Oraklet på grund af sine 'overjordiske' sanser. Hun har med succes hjulpet korstoget i flere sejre over Geisslen.\n\nSelvom dette list var vellykket i at afsløre hende, vil hun uden tvivl, hvis hun virkelig besidder psykiske kræfter, forvente en form for problemer. Det er dig, der skal levere dette 'problem'.\n\nSpor Oraklet op og gør en ende på hende. De burde være ved at bevæge sig ud fra Tyrs Hånd, mens vi taler. Gør mig stolt, orm.", p="Hvad er din status, <Name>?", c="De vil kvæles af dette slag i årevis! Velgjort, <Name>! Du har fortjent ikke kun min respekt, men også denne belønning."},
  [6162] = {n="En ægtemands sidste kamp", l="Dræb Overherre Ror, og bring hans klo til Dreka'Sur ved Blodgift-posten i Ondskoven.", d="Min mand rejste gennem Ondskoven for vores klans ære og kæmpede mod Skyggerådet og andre korrupte gruer!\n\nEfter at han flere gange slap fra døden, modtog jeg et brev fra ham, hvori der stod, at en druide havde bedt ham om hjælp mod en stor besmittet pelsbolg ved navn Overherre Ror - de to blev aldrig hørt fra igen.\n\nJeg vil have denne Rors klohånd, <Name>. Jeg vil have, at den skal betale for, at den gjorde mig til enke! Jeg tror, skabningen befinder sig mod syd... nær Askedalens grænse.", p="Har du udyrets klo endnu, <Name>? Den skal betale for sine forbrydelser. Jeg er ligeglad med, om den er korrupt eller bare vred over at bo i sådan en dyster skov. Ingen pelsbolg vil leve længe efter at have begået sådanne forbrydelser mod min familie!", c="Du bringer ære til mig ved at følge dit ord til dørs. Min mand døde i kamp - han ville have været stolt af det. Men jeg kunne ikke hvile, før jeg vidste, at det væsen, der tvang mig til at leve mit liv alene, betalte for det, det havde gjort.\n\nTak igen, <Name>."},
  [6163] = {n="Ramstein", l="Rejs til Stratholm, og slå Ramstein Frådser ihjel. Tag hans hoved som en souvenir til Nathanos.", d="Jeg var overvældet. På netop denne gård stod jeg... holdt min grund til forsvar af Herrelande. Gården og alt på den blev overrumplet af en gigantisk bølge af Geisslen.\n\nUdskuddet. Skidtet. Det svævede over mig, med tarmene hængende ud af dens gabende brystkasse.\n\nJeg vågnede som Geissel. I så lang tid var jeg hjælpeløs. Mit sind var smeltet sammen med Liskekongens.\n\nHun kom efter mig... et sted, på en eller anden måde vidste jeg, at hun ville. Fri.\n\nOg nu må jeg have min hævn - min hævn over det, der tog mit liv fra mig. Tilintetgør det.", p="Efter at Sylvanas befriede mig, jagtede jeg udyret over disse ødemarker i månedsvis. Det flygtede til sikkerheden i Stratholm. Den umage...", c="Jeg undrer mig... bad den om nåde? Kunne den vide, hvad nåde er?\n\n<Nathanos spytter.>\n\nJeg vil hænge dette udyrs hoved op på min mur.\n\nDu har fortjent en plads blandt en af mine mestre, <Name>.\n\n<Nathanos hilser.>"},
  [6164] = {n="Augustus' kvitteringsbog", l="Bring Augustus' kvitteringsbog til Augustus den Berørte i Rystedal.", d="Jeg er klar til forretning! Hvad vil du have?\n\nÅh vent... jeg kan ikke åbne butikken uden min kvitteringsbog. Hvordan skal jeg holde styr på tingene uden min kvitteringsbog?\n\nJeg må have ladt den ligge et sted i byen. Jeg havde et værelse i kroen... bogen må være der.\n\nHent min bog. Vær venlig at bringe den til mig! Hent min bog, så skal du se! Jeg åbner butikken, og du vil se, at mine priser er GALE!", p="Har du min kvitteringsbog? Jeg kan ikke vente med at komme i gang med forretningen igen!", c="Der er den! Og åh, hvor jeg havde glemt, hvor fuld den var!\n\nDet er en herlig dag, <Name>! Fantastisk! Sindssygt godt, siger jeg!"},
  [6182] = {n="Den første og den sidste", l="Tal med Mathias Skaw i Gamlebyen Stormvind. Han holder til i Kasernen.", d="Nathanos Marsk var den første og sidste af de menneskelige skovvogterlorder. En discipel af Sylvanas Vindløber, nu Dødsånd-dronningen af De Forladte.\n\nVi havde troet, at Nathanos var blevet dræbt i kamp under forsvaret af Herrelande for fem år siden. Selvom hans lig aldrig blev fundet, antog man, at han ikke slap ud af de Østlige Pestlande.\n\nMathias Skaw har undersøgt forsvinden og har måske nogle nye oplysninger. Mød ham øjeblikkeligt. Han holder til i Gamlebyen, ved Kasernen.", c="Efter nogle rapporter om usædvanlig aktivitet fra De Forladte i de Østlige Pestlande blev SI:7-agenter sendt ud for at undersøge. Resultaterne af den undersøgelse er urolige."},
  [6183] = {n="Ær de døde", l="Tal med Mathias Skaw igen, hvis du ønsker at tage imod hans opgave.", d="Fem af mine bedste feltagenter blev sat på Marsk-sagen. Én vendte tilbage, kun for at ende død i sin søvn tre dage senere.\n\nDet lille, vi formåede at få ud af ham, var sammenhængende vrøvl. Vi kunne tyde to ord: \"Nathanos\" og \"Pestkalder\".\n\nJeg har ikke den nødvendige bemanding til at fortsætte denne efterforskning, og Ravnsholdt vil ikke hjælpe os. Vi må komme til bunds i dette; om ikke andet for at give de afdødes familier en afslutning. Vil du hjælpe?", c="<Mathias nikker.>\n\nJeg havde tro på, at Bolvær ville sende mig mænd og kvinder af ære - de mest hengivne soldater i Alliancen."},
  [6184] = {n="Flint Skyggemoor", l="Rejs til Kuldevind-lejren i de Vestlige Pestlande, og mød din kontakt, Flint Skyggemoor.", d="Den eneste information, vi har indtil nu, er altså, at Nathanos Marsk måske er blevet dræbt af denne Pestkalder. Vi går ud fra, at Pestkalderen er samme djævel, der fjernede mine agenter.\n\nFlint Skyggemoor, en anden SI:7-operativ, er stationeret i Alliancens lejr Kuldevind-pegen i de Vestlige Pestlande. Søg ham op; han vil orientere dig om den aktuelle situation i Pestene og give dig en opgave.\n\nHeld og lykke, <Name>.", c="Den første mission bliver ligetil, <Name>. Du går ind, du kommer ud. Spejderarbejde..."},
  [6185] = {n="De Østlige Pester", l="Gennemsøg de Østlige Pestlande for spor om \"Pestkalderen\" og de savnede SI:7-agenter. Hvis du finder nogen SI:7-emblemer, skal du bringe dem tilbage til Flint Skyggemoor i Kuldevind-lejren.", d="Som jeg sagde, er din første mission en rekognoscering. Intet fancy, <Name>. Du skal rejse til de Østlige Pestlande og lede efter spor om denne Pestkalder.\n\nHold øje med information om vores savnede agenter. Vi må antage, at de er døde, og er de døde, må de have et lig... et sted.\n\n<Flint synker en klump i halsen.>\n\nAlle SI:7-agenter bærer dette emblem.\n\n<Flint viser dig sit SI:7-emblem.>\n\nBring de emblemer, du måske finder, tilbage til mig.", p="En... Er der nogen held??", c="Rutger. Fredo. Turyen. Alle... døde...\n\n<Flint klemmer emblemerne hårdt.>\n\nHvor var de? Fandt du nogen mere information om den lort, Pestkalderen?"},
  [6186] = {n="Pestkalderen Kommer", l="Vend tilbage til Stormvind og informer Højlord Bolvar Fordrågon om skæbnen for Nathanos Marsk.", d="<Blodet synes at være forsvundet helt fra Flints ansigt.>\n\nN-nej... Nathanos gjorde dette? Nathanos er Pestkalderen?\n\nHvorfor? Han var... var så ædel - en skovløber-lord, respekteret af alle. Det eneste menneske, der nogensinde fik lov til at træne under højalferne. Nu en hensynsløs agent for De Forladte?\n\nJeg... jeg er ked af at bede dig om dette, <Name>, men Højlord Fordrågon må underrettes om denne vending med det samme. Vend venligst tilbage til Stormvind og bring nyheden.", c="Nej. Det... NEJ! Hvordan? En agent for De Forladte? MESTEREN for Dødsånd-dronningen???\n\n<Højlord Bolvar Fordrågon synker sammen i nederlag.>"},
  [6187] = {n="Ordenen Må Genoprettes", l="Saml en hær og rejs til de Østlige Pestlande. Indled et fuldt angreb på Nathanos Pestkalder og alt Horde-møg, der måtte forsøge at beskytte ham.\n\nHold dig skarp, <Name>. Horden vil forsvare skovløber-lorden med deres liv.", d="Ved du, hvor mange skovløber-lords der findes i denne verden? Hvor mange menneskelige skovløber-lords der nogensinde har eksisteret?\n\nNathanos' bedrifter var enestående. Han var et taktisk geni, ansvarlig for Alliancens sejre gennem et årti af konflikt.\n\nOg nu... De Forladtes mester.\n\nNej. Dette kan ikke være. Ordenen må genoprettes.\n\nSaml en hær, <Name>. Vend tilbage til Pestlandene med din hær og ødelæg Pestkalderen.\n\nJeg ønsker dig held, <Name>. Du får sandelig brug for det i dette slag.", p="<Højlord Bolvar Fordrågon er fortabt i tanker.>", c="Det er en tragedie. Jeg tror... jeg mener, at vores slægt er forbandet, <Name>. Vi er forbandet til at miste vores største krigere, vores ædleste helte, vores mest begavede lærde.\n\nVi står i gæld til dig, og jeg forsikrer dig, <Name>: Hvor end Nathanos Marsk nu er, smiler han ned til dig."},
  [6322] = {n="Mikael Garrett", l="Bring Gordons Kasse til Mikael Garrett.", d="Jeg har lagt Gravkammerets forsyninger i denne kasse. Hvis du allerede har besøgt Gravkammeret og talt med deres flagermusmester, så kan du ride en flagermus tilbage til ham.\n\nTal med Underbyens flagermusmester, Mikael Garrett. Han kan skaffe dig en flagermus til Gravkammeret.", p="Hvis du må rejse en lang strækning, så er en flagermus dit bedste valg.", c="Skal denne kasse nå Gravkammeret i Sølvskoven? Det er let klaret; vores flagermus flyver derhen dagligt."},
  [6341] = {n="Teldrasils Rigdom", l="Bring Nessies Samling til Vesprystus.", d="Fiskerne i Rutteran-landsbyen har det rigtig godt, for fiskene her er ekstremt store og rigelige. Jeg vil gerne sammenligne rigdommen her med den på fastlandet.\n\nJeg har en samling fiskeben og skæl, som jeg gerne vil have bragt til en kollega af mig i Mørkekysten. Hans navn er Laird, han er fiskehandler i landsbyen Auberdin.\n\nBring min samling til vores hippogryfmester, Vesprystus, og tal med ham om at rejse til Auberdin.", p="Hvordan kan jeg hjælpe dig? Har du brug for transport?", c="Ah, du vil have det her til Auberdin? Meget godt..."},
  [6342] = {n="Flyvning til Auberdin", l="Ri en hippogryf til Auberdin fra hippogryfmesteren Vesprystus, og bring derefter Nessies Samling til Laird.", d="Fra Rutteran findes der to rejsemetoder til Auberdin: med færge og med hippogryf. Begge er hurtige og pålidelige, men hvis du endnu ikke har fløjet til Auberdin med hippogryf, så foreslår jeg, at du gør det.\n\nDet er et godt råd at tale med hippogryfmesteren i hver by, der har en. Når du har talt med mesteren, kan du flyve derhen fra andre byer.\n\nHer er Nessies samling. Tal med mig igen, når du er klar til at flyve til Auberdin og levere Nessies samling til Laird.", p="Er du kommet fra Teldrasil? Fortæl mig, hvordan fisket er dernede?", c="En pakke fra Nessie? Tak, <Name>! Hun sagde, at hun ville sende mig prøver af fisken fanget nær Rutteran-landsbyen. Hun tror, de kan være meget anderledes end fiskene her...\n\nMin! Denne kæbeben er næsten dobbelt så stor som den samme fisk fundet her. Og disse skæl er store som en lukket næve! Fantastisk!"},
  [6343] = {n="Tilbage til Nessie", l="Bring Lairds Svar til Nessie Skyggesang.", d="Jeg må sende et svar til Nessie. Hun vil være meget interesseret i at vide, hvor forskellig fisken her er fra dem langs Teldrasils kystlinje. Vi kan kun gætte på årsagen, men jeg mistænker, at verdenstræet selv påvirker dyrelivet omkring det!\n\nVær venlig at tage dette svar med til Nessie. Hvis du ønsker at tage en hippogryf tilbage til Rutteran, så tal med hippogryfmesteren Caylais Månefjer. Hvis du ønsker at tage færgen, så afgår der regelmæssigt en fra havnen mod nordvest.", p="<Name>, er du tilbage fra Auberdin? Talte du med Laird?", c="Det her er meget interessant. Fiskene her er store, men jeg troede ikke, forskellen i fangst mellem her og fastlandet var så stor. Der må være en grund til det...\n\nTak, <Name>. Jeg vil drøfte de nyheder, du bragte, med landsbyboerne. Måske finder vi en dag roden til denne besynderlighed. Men indtil da skal vi høste fordelene!"},
  [6344] = {n="Nessie Skyggesang", l="Tal med Nessie Skyggesang.", d="En ven af mig, Nessie Skyggesang, er fiskehandler i Rutteran-landsbyen. Hun har brug for en pakke bragt til Mørkekysten og leder efter nogen, der kan hjælpe hende.\n\nHvis du er interesseret, så skal du, for at nå Nessie, tage portalen i Darnassos til Rutteran-landsbyen. Du finder portalen vest for Tempelhaverne.", c="Ja, jeg har brug for en kurér, der vil tage en pakke til Mørkekysten. Vil du hjælpe mig?"},
  [6361] = {n="Et Bundt Huder", l="Bring Bundtet med Huder til vindrytter-mesteren Dævrak i Korsvejen.", d="Jeg har et bundt huder fra dyrene i Ødemarken, og de skal bringes til Tordenskrænt. En kollega dernede, Ahanu, vil bruge hudene til at lave lædervarer.\n\nVil du tage hudene med til ham for mig?\n\nDen hurtigste vej til Tordenskrænt er på ryggen af en vindrytter. Bring bundtet med huder til Dævrak, vores vindrytter-mester i Korsvejen, og tal med ham om transport til Tordenskrænt.", p="Er du her for en vindrytter? Har du noget, der skal transporteres?", c="Hvis du skal tage disse huder til Tordenskrænt, så taler du til den rette ork!"},
  [6362] = {n="Ridt til Tordenskrænt", l="Køb en vindrytter til Tordenskrænt hos vindrytter-mesteren Dævrak, og bring derefter Bundtet med Huder til Ahanu i Tordenskrænt.", d="For et lille gebyr giver jeg dig en vindrytter til Tordenskrænt. Der findes ingen hurtigere vej til byen!\n\nHvis det er acceptabelt, så tal med mig igen, når du er klar til at tage afsted.\n\nHvis du tager de huder til Ahanu, så tror jeg, han er i Hewas Våbenkammer ved foden af vindrytter-tårnet i Tordenskrænt. Og netop der lander du!", p="Der er støv på dine skuldre, som må stamme fra Ødemarken. Har du talt med min ven Jahan?", c="Ah, et nyt bundt huder. Jeg går straks i gang med dem!\n\nTak, bror. Du har gjort mig en stor tjeneste. Her er nogle mønter til at betale for din tid og rejseudgifter."},
  [6363] = {n="Tal, Vindrytter-mesteren", l="Bring Ahanus Lædervarer til Tal i Tordenskrænt.", d="Jeg har fremstillet lædervarer, som Jahan skal sælge i Korsvejen. Vil du bringe dem til ham?\n\nHvis du allerede har været i Korsvejen og talt med deres vindrytter-mester, så kan du flyve en af vores vindrytter fra Tordenskrænt tilbage til ham.\n\nTag lædervarerne til Tal, vores vindrytter-mester i Tordenskrænt, og tal med ham om at arrangere transport til Korsvejen.", p="Hilsen, <Class>. Hvad kan jeg gøre for dig?", c="Du skal have det her til Korsvejen, hva'? Det er ikke noget problem. Hvis du allerede har været der og talt med Dævrak, så kan du tage en af mine vindrytter tilbage til ham."},
  [6364] = {n="Tilbage til Jahan", l="Køb en vindrytter til Korsvejen hos vindrytter-mesteren Tal, og bring derefter Ahanus Lædervarer til Jahan Høgvinge.", d="For at flyve til en by skal du have været der og have talt med byens vindrytter-mester. Du har været i Korsvejen og talt med deres vindrytter-mester Dævrak, så for et lille gebyr kan du tage en vindrytter derhen til ham herfra.\n\nTal med mig igen, når du er klar. Når du er i Korsvejen, kan du levere lædervarerne til Jahan Høgvinge.", p="<Name>, er du tilbage fra Tordenskrænt? Leverede du hudene til Ahanu?", c="Ahanu sendte mig færdige varer? Meget godt. Der er mange jægere og eventyrere i Korsvejen nu, og forretningen går livligt. Jeg er sikker på, at jeg sælger disse varer meget snart.\n\nTak for al din indsats, <Name>. Jeg står i din gæld."},
  [6386] = {n="Tilbage til Korsvejen.", l="Køb en vindrytter til Korsvejen hos vindrytter-mesteren Dorus, og bring Gryshkas Brev til Zargh i Korsvejen.", d="Mine vindrytter er trænet til at flyve til mange forskellige steder, så længe du allerede har været der og talt med vindrytter-mesteren.\n\nDu har været i Korsvejen og talt med deres vindrytter-mester Dævrak, så nu kan du flyve direkte til ham herfra. Når du er i Korsvejen, kan du levere Gryshkas brev til Zargh.\n\nTal med mig, når du er klar til at tage afsted.", p="Er du kommet tilbage fra Orgrimgrad? Kunne Grydeska lide det kød, jeg sendte hende?", c="Haha! Jeg gætter på, at hun kunne lide det! Intet får en dames kinder til at rødme som en stor, saftig bøf!\n\nTak, <Name>. Du har gjort mig en stor tjeneste. Her er nogle penge for besværet, og bliv ikke overrasket, hvis jeg inviterer dig til mit bryllup!"},
  [6389] = {n="En Pest Over Dig", l="Slip Pestlands-termitterne løs i Nordkamm-tømmermøllen, og vend derefter tilbage med Tønden med Pestlands-termitter til Nathaniel Dumøh i Kuldevind-lejren i Vestlige Pestlande.", d="Du kigger rundt i tømmermøllen efter noget, der kan åbne tønden med. Du finder en koben, der ser ud til at gøre nytten.\n\nDu sætter fødderne og beder til, at du kan komme ud af møllen, før termitterne når dig.", p="Har du gjort det, <Name>? Har du sluppet termitterne løs? Lyset hjælpe os, hvis Skarlagenkorstoget formår at holde fast i både møllen og Hjertedal. De burde ikke have nogen af dem. De profiterer blot på ofrene fra den sidste krig og burde nedlægges som rasende dyr!", c="Haha! Tak, <Name>! Du har gjort det! Min fars ånd kan nu hvile, og jeg kan leve i fred.\n\nTak igen. Hvis der er noget, jeg kan gøre for dig, så bare spørg."},
  [6390] = {n="En Pest Over Dig", l="Slip Pestlands-termitterne løs i Nordkamm-tømmermøllen, og vend derefter tilbage med Tønden med Pestlands-termitter til Mikke Levine ved Bolværket i Tirisfalskoven.", d="Du kigger rundt i tømmermøllen efter noget, der kan åbne tønden med. Du finder en koben, der ser ud til at gøre nytten.\n\nDu sætter fødderne og beder til, at du kan komme ud af møllen, før termitterne når dig.", p="Har du gjort det, <Name>? Har du sluppet termitterne løs i tømmermøllen?\n\nDet var slemt nok, at min familie mistede deres job og liv, men så at se stedet, hvor min barndom blev tilbragt, overtaget af de modbydelige såkaldte hellige mænd... pfah!!", c="Tak, <Name>. Her, tag denne mønt. Jeg beklager, at den ikke er mere, men prøv at finde glæde i at hjælpe med at ødelægge Skarlagenkorstogets bestræbelser!"},
  [6402] = {n="Stormvind-Stævnemødet", l="Rejs til Stormvind By og gå hen til byporten. Tal med Væbner Række, så han kan lade Marskal Windsor vide, at du er ankommet.", d="Du skal mødes med Windsor ved portene til Stormvind.\n\nDet, Windsor er ved at afsløre, vil ryste kongerigets grundvold!\n\nForsøg ikke at begive dig derhen alene, <Name>. Du skal samle en hær! Saml dine kammerater. Til våbnene!", c="Før vi begynder, beder jeg dig først om at samle en hær. Vi står trods alt over for en drage!"},
  [6403] = {n="Den Store Maskerade", l="Følg Reinhold Windsor gennem Stormvind. Beskyt ham mod skade!", d="Det har været et ganske eventyr, ven. Jeg står i din store gæld. Måske, når alt er sagt og gjort...\n\nSom du uden tvivl har gennemskuet nu, er Dame Prestør Onyksia: Dødsvinges yngel, tvillingesøster til tyrannen i spiret, Nefarian.\n\nAlt for længe har hun holdt vores kongerige i sit fortryllende blik. Selv Højlorden er styret af hendes snedighed - en marionet. Det hele ender i dag... Besværgelsen vil blive brudt.\n\nFrygt ikke, for sammen skal vi sejre!\n\nEr du klar?", p="Jeg... jeg... jeg var magtesløs.", c="<Bolvar holder den knuste medaljon.>\n\nMagien, der er indeholdt i den, må tændes igen. Drageøjet skal stilles ind.\n\nWindsors offer har befriet vores kongerige, men truslen fra Onyksia og hendes slægt hænger stadig over os.\n\nDenne medaljon er det, der holdt mit sind og legeme fanget. Det er også det, der gav mig adgang til Onyksias eget sind - til hendes hemmeligheder. Selvom synene nu er uklare, husker jeg visse ting."},
  [6501] = {n="Drageøjet", l="Du skal lede verden efter et væsen, der er i stand til at genoprette kraften i Fragmentet af Drageøjet. Den eneste information, du har om et sådant væsen, er, at det findes.", d="Et fragment af den knuste medaljon er alt, jeg kan tilbyde.\n\nDu skal finde en anden med drageblod, der er villig til at hjælpe dig med at smede en ny nøgle. Når du har sikret nøglen, skal du rejse til Ormesumpen i Støvsumpen. Det er der, du finder hendes hule, <Name>.\n\nHvor finder man andre flyvninger, der er villige til at hjælpe? Desværre ved jeg det ikke... Det siges, at de findes. Nogle lever måske endda blandt os og skjuler sig som en af de humanoide racer. Jeg ønsker dig held.", p="Jeg fornemmer et ondt skær udstråle fra dig, <Race>. Hvad kan du have, der udsender sådan et skær?", c="Jeg burde have vidst det - et stykke af den sorte drageyngelmor, Onyksia. Hvor afskyeligt..."},
  [6502] = {n="Drakeild-amuletten", l="Du skal hente Blodet fra den Sorte Drages Mester hos General Drakkisat. Drakkisat findes i sin troneværelse bag Opstigningens Haller i Sortklippe-spiret.", d="Det er et stykke af dragen; en skæl - fortryllet og forvandlet. Helt, kunne den have givet adgang til udyrets hule. Knust er den ubrugelig.\n\nDet er muligt at reparere genstanden, men det ville kræve blodet fra en sort drages mester. Der er én... Han er kendt som General Drakkisat, hersker over hærene af drageafkom under Nefarian. Måske har du hørt om ham?\n\nVend tilbage med hans blod, <Race>, og jeg vil fortrylle fragmentet til noget, der giver dig adgang til Onyksias rede.", p="Tiden standser ikke og bremser ikke, <Race>. Mens mit liv er evigt, er dit ikke. Spild ikke den tid, du har...", c="Denne amulet giver dig den adgang, du søger. Onyksias rede findes i Støvsumpen. Så længe du har amuletten, kan hendes værger ikke forhindre dig i at komme ind.\n\nDen Blå Flyvning ønsker dig held, <Name>."},
  [6523] = {n="Beskyt Kaya", l="Eskorter Kaya Fladhov til Lejr Aparaje, og vend derefter tilbage til Makaba Fladhov nær den sydøstlige kant af Stenstemme-bjergene.", d="Tak, fordi du reddede mig! Vi må skynde os væk, før de opdager, at jeg er fri. Eskorter mig venligst til Lejr Aparaje. Derfra kender jeg vejen.\n\nMin far, Makaba Fladhov, vil være desperat efter at vide, at jeg er i sikkerhed.", c="Kaya er i live! <Name>, jeg har dig at takke for, at du reddede hende."},
  [6566] = {n="Hvad Vinden Bærer", l="Lyt til Træl.", d="Det er godt at se dig igen, <Name>. Vinden bærer nyheder fra østkongeriget med sig.\n\nSid, lyt.", p="Tålmodighed, <Name>. Hav opmærksomheden på dig!", c="Er du klar til at påtage dig denne opgave?"},
  [6567] = {n="Hordens Mester", l="Find Rexar. Krigshøvdingen har fortalt dig, hvor han befinder sig. Søg Forødelsens stier mellem Stenstemme-bjergene og Vildalas.", d="Jeg har modtaget besked fra en af mine mestre om, at der kan findes en vej ind i dragens hule. Du skal opsøge ham.\n\nRexar vandrer i ørkenvildmarken Forødelse og rejser mellem Stenstemme og Vildalas. Han venter på din ankomst.", c="Der er kun én vej ind i dragens hule, <Race>.\n\nSe, kun de stærkeste fra Den Sorte Drageflugt må træde ind i yngelmoderens hule. Mange prøvelser skal bestås, og nøglen til at komme ind skal ceremonielt fortrylles af General Drakkisat selv!\n\nDa du ikke er af sort drageslægt, kan du få lidt besvær med at opnå adgang.\n\n<Rexar smiler.>"},
  [6568] = {n="Rexars Testamente", l="Lever Rexars Testamente til Myranda Heksen i Vestlige Pestlande.", d="Hvad ved du om illusioner, <Name>? For det er en illusion, du skal skabe for at omgå Den Sorte Flyvnings forsvar.\n\nJeg kender til én, der måske er villig til at hjælpe dig i din bedragerske søgen. Hun har hjulpet vores slægt før, når hun har fundet sagen værdig.\n\nI Vestlige Pestlande vil du finde Myranda Heksen, mesterillusionist - en udstødt fra Herrelande-alliancen. Rejs derhen og tag denne besked med dig.", p="Det er ikke ofte, jeg ser en fra Horden i disse egne af Herrelande. Hvad har du til Myranda?", c="<Myranda holder seddelen, standser op og smiler.>\n\nHvordan har han det? Rexar, mener jeg. Åh, kom nu, se ikke så forvirret ud. Brevet var med vilje tomt. Det bar med sig skaberens hensigter og tanker. Set i lyset af dets indhold er det ikke underligt, at Rexar lod det stå sådan. Forestil dig, hvis du var blevet fanget eller dræbt, og denne information var blevet opdaget!\n\nÅh, glem det! Myranda vil hjælpe dig, <Race>. Jeg skylder Krigshøvdingen en tjeneste eller to.\n\n<Myranda smiler.>"},
  [6569] = {n="Øjen-illusionerne", l="Rejs til Sortklippe-spiret og saml 20 Sorte Drageafkomøjne. Vend tilbage til Myranda Heksen, når opgaven er fuldført.", d="Så <Race> ønsker at blive en af Den Sorte Flyvning, hva'?\n\nSkabelsen af den illusion, du har brug for, er banal, men ingredienserne til besværgelsen er ret svære at skaffe. Rexar og Krigshøvdingen har betroet dig denne mission, så Myranda må antage, at du er i stand til det.\n\nRejs til den øverste citadel i Sortklippe-spiret, og slå nok af de sorte drageafkom ihjel til at fylde en af dine tasker med deres øjne.\n\nVend tilbage til Myranda, når du har samlet nok af reagensen.", p="Øjnene fra det, vi ønsker at efterligne, er den vigtigste ingrediens i enhver illusion, <Name>.\n\n<Myranda peger på en pose, der næsten flyder over med øjeæbler mærket 'Skarlagenkorstoget.'>\n\n<Myranda griner.>", c="Lad Myranda kigge, <Race>.\n\nÅh ja, de her vil gøre det fint.\n\nMed disse reagenser vil Myranda skabe en medaljon til dig, der giver en illusion i stand til at narre Den Sorte Drageflugts portvagt."},
  [6570] = {n="Glødestrid", l="Rejs til Ormesumpen i Støvsumpen og find Glødestrids Hule. Når du er indenfor, skal du bære Amuletten for Drakonisk Undergravelse og tale med Glødestrid.", d="Jeg har tilpasset denne medaljon med den magi, der er nødvendig for at skabe og opretholde en illusion inden for rammerne af Glødestrids hule.\n\nGlødestrid er en gammel drage; en gammel portvagt for Nefarian, belastet med pligten til at teste de drageafkom, der ønsker at stige i graderne til elitevagt for Onyksia.\n\nRejs til Ormesumpen i Støvsumpen og træd ind i Glødestrids hule. Når du er der, så tag amuletten på og følg, hvor din skæbne måtte føre dig!", c="Er vi løbet så tør for dygtige soldater, at Nefarian sender mig killinger? Du vil aldrig bestå mine prøver, yngel."},
  [6582] = {n="Kraniernes Prøve, Spejder", l="Du skal finde den blå drageflugt-mester, Spejder, og slå ham ihjel. Pil hans kranie ud af hans lig og bring det tilbage til Glødestrid.\n\nDu ved, at Spejder kan findes i Vinterkilde.", d="Vi er Dødsvinges børn, unge. Vores herredømme over de mindre Aspekter skal håndhæves.\n\nHvis du virkelig er værdig til opstigning, vil de mindre drageflugter visne i din nærhed.\n\nFind deres mestre og hærg dem i vores Fars navn!\n\nRejs til Vinterkilde og spor den mægtige blå drage, Spejder. Knus ham og enhver fra Den Blå Flyvning, der står i din vej. Riv hans kranie ud og bring det tilbage til mig.", p="<Glødestrid fnyser.>", c="En af ssseveral færdige..."},
  [6583] = {n="Kraniernes Prøve, Sømnus", l="Ødelæg Den Grønne Flyvnings drage-mester, Sømnus. Tag hans kranie og bring det til Glødestrid.", d="Ligesom vores Far knuser Aspekterne selv, skal vi stræbe efter at bringe kaos og ødelæggelse over deres børn.\n\nDu må teste din kampdygtighed mod de søvnløse drømmere: Den Grønne Flyvnings børn.\n\nRejs til Sorgens Sump og spor Sømnus op, drage-mesteren for Den Grønne Flyvning. Lad dit had flyde; dominér insektet... Vend tilbage til mig med hans kranie...", p="Vend ikke tilbage hertil, før du har badet i vores fjenders blod og drukket deres lidelse.", c="En anden færdig..."},
  [6584] = {n="Kraniernes Prøve, Kronalis", l="Vogtende over Tidens Huler i Tanaris-ørkenen er Kronalis, Nosdormus barn. Ødelæg ham og bring hans kranie til Glødestrid.", d="Tidens vogtere, Nosdormus børn - Århundredernes Herre...\n\nDet er tre, der vogter Tidens Huler, men kun én, der varetager Den Sorte Flyvnings interesser: Tidsforskyderen, Kronalis, Nosdormus' yndlingsdrageunge.\n\nSsslå til denne mester, et slag der får selv tidens stoiske sand til at græde. Bring hans kranie tilbage til mig.", p="Ironisk nok, unge, tiden er af yderste vigtigheddd.", c="De mest hadede resssterne..."},
  [6585] = {n="Kraniernes Prøve, Aksroz", l="Rejs til Grimbatol og spor Aksroz op, drage-mesteren for Den Røde Flyvning. Ødelæg ham og tag hans kranie. Bring kraniet til Glødestrid.", d="Det var over bjergene ved Grimbatol, at vores Far raserede mod Aspekternes forenede styrke. Forræderen Alexstraszas feje handling gav de andre Aspekter tid nok til at undslippe Faderens vrede.\n\nSsådan en skamfuld handling...\n\nDen Røde Flyvning vogter nu Grimbatol, og deres løjtnant, Aksroz, skal ødelægges. Bring Aksrozs kranie til mig. For Faderen, unge!", p="Forandringsss... Jeg fornemmer dem ske i dig, unge. Bestå denne prøve, og kun ceremonien er tilbage.", c="Jeg havde tvivlet på din hengivenhed, unge. Du holdt ud, dominerede vores fjender og bragte ære til vores flyvning.\n\nJeg må nu forberede kranierne til din opstigning."},
  [6601] = {n="Opstigning...", l="Det ser ud til, at komedien er forbi. Du ved, at Amuletten for Drakonisk Undergravelse, som Myranda Heksen skabte til dig, ikke vil virke inde i Sortklippe-spiret. Måske bør du finde Rexar og forklare din situation. Vis ham den Sløve Drakeild-amulet. Forhåbentlig ved han, hvad der skal ske næste.", d="Af vores fjenders kranier formes en medaljon. Du kender denne medaljon, ja? Du har uden tvivl set den båret af dine ældste.\n\nTag den, unge. Vend tilbage til spiret og præsenter den for general Drakkisat. Generalen vil lægge den sidste fortryllelse på medaljonen og stemme tingesten efter din ånd.\n\nDu vil bære den færdige medaljon som et æresmærke, der symboliserer din opstigning til en af vores mest bevogtede rækker: Vogter for yngelmoderen.\n\nAf sted!", p="Bliv ikke panisk, <Name>!", c="Det er blot drage-snak, <Name> - mere varm luft end egentlig væsentlig information. Opblæst, aggressiv opførsel må forventes fra deres slags."},
  [6602] = {n="Den Sorte Drage-mesters Blod", l="Rejs til Sortklippe-spiret og slå general Drakkisat ihjel. Saml hans blod og bring det tilbage til Rexar.", d="Du skal besøge generalen, ja, men ikke som en af Den Sorte Drageflugt.\n\nDu ser, en ceremoni er blot et andet ord for blodudtapning for Den Sorte Flyvning.\n\nDen latente amulet behøver blot generalens blod for at blive aktiv. En af deres grove sikkerhedsmekanismer.\n\nVend tilbage til Sortklippe-spiret og ødelæg Drakkisat. Bring hans blod hertil, så aktiverer jeg nøglen til Onyksias rede.", p="Jeg tror ikke, jeg behøver at fortælle dig, at Drakkisat ikke skal tages let på.\n\nJeg lader de tusindvis døde af hans hånd tale for sig.", c="En sejr, der vil huskes i mange år, <Name>. Drakeild-amuletten vil åbne Onyksias rede. Saml dine allierede og bring sejr til Horden."},
  [6603] = {n="Problemer i Vinterkilde!", l="Find Donova Snedal nær de varme kilder i Vinterkilde.", d="Der er problemer i Vinterkilde!\n\nJa, jeg bruger da tid ude i vildmarken og ved en del om sådan noget... Jeg er altid meget stolt over at sige det. Jeg betragter timerne, jeg tilbringer derude i bakkerne, som guld værd. De hjælper dig med at dyrke hurtige reflekser, et køligt hoved og et skarpt øje...\n\nDet kræver dømmekraft, hjerne og modenhed at værdsætte vildmarken, sådan som jeg gør.\n\nNu, hvad var det, jeg talte om?\n\nÅh ja, problemer. Søg Donova Snedal ved de varme kilder, så kan hun fortælle dig mere.", c="Nå, hej dér! Så Mægi fortalte dig om de problemer, jeg har fundet her?"},
  [6604] = {n="Rasende Vildnisvæsen", l="Tal med Jaron Stenformer i Stjerneskudsbyen.", d="Har du bemærket den forladte lejr sydpå herfra? Det ser ud til, at vildnisvæsnerne blev gale og ødelagde næsten alt, de kunne finde!\n\nJeg hørte et rygte om, at en af de overlevende fra angrebet hviler i Stjerneskudsbyen, vest herfra. Jeg er sikkert nysgerrig efter, hvad der skete... er du ikke?", c="Ja, hvad kan jeg gøre for dig?"},
  [6605] = {n="En Mærkelig En", l="Tal med Winna Hasard i Ondskoven.", d="Jeg er lige kommet tilbage fra Ondskoven, <Name>. På vejen igennem stoppede jeg ved Blodgift-posten, og jeg mødte en meget underlig person... Hun virkede opsat på én ting, og jeg kunne vel fortælle dig, hvad det er, men jeg tror, hun gerne vil forklare det selv.\n\nHvis du er interesseret, så tag til Blodgift-posten i det vestlige Ondskoven og led efter Winna Hasard.\n\nHvem ved, måske har hun brug for din hjælp...", c="Ah, <Class>. Jeg ser, at der er håb endnu. Er du her for at assistere mig?"},
  [6606] = {n="Lidt Held", l="Tal med Hekselæge Mo'ari i Evigblik.", d="Vi kan altid bruge lidt held, ikke? En lille fordel er alt, der skal til for at vende tingene til din fordel...\n\nJeg havde engang fornøjelsen af at møde en ret excentrisk hekselæge. Hun lavede mig en heldbringende amulet... mod betaling. Tro mig, det var det værd!\n\nMåske er du interesseret i en egen? Find Hekselæge Mo'ari i Evigblik. Jeg giver ikke min fra mig!", c="Ah, så Harlø har sendt dig? Nå, hvem være du så? Jeg gætter på, du vil have min hjælp?"},
  [6607] = {n="Nat Lommetyv, Ekstrem Fisker", l="Nat Lommetyv vil have dig til at fange følgende fisk:\n\nTågesiv-Mahi Mahi fra Tågesiv-strandbredden i Sorgens Sump.\n\nEn Sar'theris-Stikker fra Sar'theris-tråden i Forødelse.\n\nFeralas-Tun fra Verdantis-floden i Vildalas.\n\nBlå Sejlfinne fra Den Vilde Kyst i Stranglethorn-dalen.\n\nVend tilbage til Nat Lommetyv, når du har trukket dem alle ind!", d="Kan ikke sige, jeg rigtig nyder fiskeri. Regner med, at jeg har holdt på det i 20 eller 30 år nu.\n\nJeg tror, folk drives til at gøre, hvad de gør, af forskellige grunde.\n\nNu siger jeg ikke, at du skal fiske i 30 år eller fange hver eneste fisk i havet for at blive en mester-fisker. Jeg regner med, at du blot behøver at være bestemt - bestemt nok til at sidde på bagdelen i timevis og lave ingenting.\n\nJeg siger dig hvad, fang mig et par sjældne fisk, så lærer jeg dig et par ting. Her er en liste:", p="Noget der bider i dag?", c="Nu var det en fin fangst!\n\nKom herover, lad mig vise dig, hvordan man sætter et par liner."},
  [6608] = {n="I Er For Gode.", l="Du tror, Lumæk prøver at fortælle dig, at han ikke længere kan hjælpe dig med at forbedre dine fiskeevner. Du vil måske prøve at finde hans ven, Nat Lommetyv, et menneske, der fisker fra en af øerne syd for Theramøre (i hvert fald tror du, at det var, hvad Lumæk sagde).", d="Lumæk kan ikke lære <Name> mere. I for gode! Find Lumæks ven, Nat Lommetyv. Er menneske men spiser ikke! Er Lumæks ven! Nat lære dig fisk bedre.\n\nDu finder Nat i Støvsumpen, syd for Menneskeby, Theramøre-noget-lignende-det. Nat fisker nok. Af sted nu!", c="Selvfølgelig, du må være en ven af Lumæks.\n\nFiskeri? Jeg kan fortælle dig alt om fiskeri."},
  [6609] = {n="Jeg Har Intet Tilbage!", l="Rejs til Kalimdør, til kystbyen Theramøre. Derfra skal du lede efter en ø syd for hovedbyen. Nat Lommetyv venter på din ankomst!", d="Jeg er en dværg for pokker, knægt! Jeg er ikke skabt til at fiske! Jeg mener, se på mig! Jeg er praktisk talt lavet af sten.\n\nJeg har intet tilbage - du tømte mig. Jeg har lært dig alt, jeg ved, flipflop!\n\nFatter du det ikke? Ah, fint. Jeg har en gammel ven på Kalimdør, der kan hjælpe dig. Hans navn er Nat Lommetyv, en fin fyr. Find ham på øerne syd for Theramøre. Kom afsted!", c="Jeg har altid plads på min ø til besøgende... tror jeg..."},
  [6610] = {n="Muslinglette-Overraskelse", l="Klagesang Hurtighugger vil have dig til at skaffe følgende ting:\n\n12 Kæmpeæg. Dem finder du hos Rokkerne, der vandrer rundt i Tanaris, eller hos enhver anden art af stor fugl.\n\n10 stykker Krydret Musling-kød. Dem kan du finde i muslinger, naturligvis!\n\n20 stykker Alteraz-ost. Tag dig til en ostebutik!\n\nSaml alle tingene og vend tilbage til Klagesang.", d="Har du nogensinde hørt om en muslinglette? Selvfølgelig ikke! Det er mit nyeste og bedste kulinariske mesterværk. Åh, <Name>, bare tanken om en muslinglette får min mund til at løbe i vand.\n\nDesværre er jeg løbet tør for forsyninger til at lave nogen! Hvad med, at jeg laver en aftale med dig? Du skaffer de forsyninger, jeg behøver for at lave en muslinglette, så lærer jeg dig de fine detaljer i eksotisk køkken, og jeg smider endda et par muslinglettere med oveni! Aftale??\n\nDet her er, hvad jeg behøver:", p="Mine lyster bliver min undergang! Skynd dig, <Name> - før jeg dykker ned i mit eget lager.", c="Du står over for en særlig godbid, <Name>. Se og lær!\n\n<Klagesang begynder at tilberede muslinglette-overraskelsen.>"},
  [6611] = {n="Til Gadgetbyen Du Går!", l="Rejs til Gadgetbyen i Tanaris-ørkenen og tal med Klagesang Hurtighugger om at fremme din kulinariske karriere.", d="Hvordan forventer du, at Samja lærer dig noget? Du har al Samjas madlavnings-mojo, og alligevel længes du efter mere!\n\nSamja kan ikke hjælpe. Fed <Race> skal til Gadgetbyen. Der finder du en lille kobold ved navn Klagesang - han hjælper dig, fedtebolle.\n\nNår du bliver stor kok i kvarteret, kommer du tilbage og lærer Samja, ok? Nu af sted!", c="<Klagesang spytter nogle læderstykker ud.>\n\nPfftøj...\n\n<Klagesang harker højlydt.>\n\nHvad? Jeg vil have dig til at vide, at læder overraskende nok er rigt på protein og lavt på kulhydrater."},
  [6612] = {n="Jeg Kender En Fyr...", l="Rejs til Gadgetbyen i Tanaris-ørkenen og tal med Klagesang Hurtighugger om at fremme din kulinariske karriere.", d="Jeg kan se på din kogeske, at du ved, hvad du laver. Desværre kan jeg ikke lære dig noget.\n\nHeldigvis for dig kender jeg en fyr. Han er en kobold og sandsynligvis den bedste kok på Kalimdør.\n\nJo, det er de dårlige nyheder, knægt - du må rejse til Kalimdør. Tag til Gadgetbyen og find Klagesang Hurtighugger. Han retter dig op.", c="<Klagesang spytter læder ud.>\n\nPfftøj...\n\n<Klagesang harker højlydt.>\n\nHvad? Jeg vil have dig til at vide, at læder overraskende nok er rigt på protein og lavt på kulhydrater, <Race>."},
  [6622] = {n="Triagering", l="Red patienter ved at bruge Triageringsbandager til at pleje deres sår. Du skal redde 15 patienter, før 6 af dem dør af deres skader.\n\nHusk triageringens rækkefølge! Kritisk Sårede Soldater dør hurtigst, efterfulgt af Hårdt Sårede Soldater. Let Sårede Soldater tager længst tid om at dø og bør reddes EFTER dine Kritisk og Hårdt Sårede Soldater er blevet triageret.", d="Goddag, doktor. Du bliver testet i din evne til at triagere patienter korrekt i eftermiddag. Består du din eksamen, slutter du dig til de prestigefyldte rækker i Horden Trauma.\n\nNu gælder det! De kritisk sårede skal behandles først. Efter de kritiske kommer de hårdt sårede. De lettere sårede behandles til sidst. Du skal redde 15 patienter for at bestå denne eksamen. Du dumper, hvis 6 af dine patienter dør under triageringen.\n\nTriageringsbandager udleveres.\n\nHeld og lykke, doktor.", p="Mirakuløst arbejde, doktor. Simpelthen mirakuløst.", c="Doktor <Name>, velkommen til Horden Trauma."},
  [6623] = {n="Horden Trauma", l="Rejs til Hammerfald i Arathi-højlandet og tal med Doktor Gregor Viktor om at slutte dig til rækkerne i Horden Trauma.", d="Doktor <Name>, formoder jeg. Det er en fornøjelse at se dig igen.\n\nJeg har nogle vidunderlige nyheder til dig! Doktor Gregor Viktor, chefslæge i Horden Trauma, har udtrykt et personligt ønske om, at du slutter dig til ham i Hammerfald. Det her kan være livets chance! Jeg ville give alt for at få lov til at studere under den store Doktor Gregor Viktor! Spild ikke denne mulighed!", c="Vidunderligt. Tag din kittel på, vi starter med det samme!"},
  [6624] = {n="Triagering", l="Red patienter ved at bruge Triageringsbandager til at pleje deres sår. Du skal redde 15 patienter, før 6 af dem dør af deres skader.\n\nHusk triageringens rækkefølge! Kritisk Sårede Soldater dør hurtigst, efterfulgt af Hårdt Sårede Soldater. Let Sårede Soldater tager længst tid om at dø og bør reddes EFTER dine Kritisk og Hårdt Sårede Soldater er blevet triageret.", d="Goddag, doktor. Du bliver testet i din evne til at triagere patienter korrekt i eftermiddag. Består du din eksamen, slutter du dig til de prestigefyldte rækker i Alliancens Trauma.\n\nNu gælder det! De kritisk sårede skal behandles først. Efter de kritiske kommer de hårdt sårede. De lettere sårede behandles til sidst. Du skal redde 15 patienter for at bestå denne eksamen. Du dumper, hvis 6 af dine patienter dør under triageringen.\n\nHeld og lykke, doktor.", p="Mirakuløst arbejde, doktor. Simpelthen mirakuløst.", c="Doktor <Name>, velkommen til Alliancens Trauma."},
  [6625] = {n="Alliancens Trauma", l="Rejs til Theramøre i Støvsumpen og tal med Doktor Gustaf VanHvordan om at slutte dig til rækkerne i Alliancens Trauma.", d="Doktor <Name>, formoder jeg. Det er en fornøjelse at se dig.\n\nJeg har nogle vidunderlige nyheder til dig! Gustaf VanHvordan, chefslæge i Alliancens Trauma, har udtrykt et personligt ønske om, at du slutter dig til ham i Theramøre. Det her kan være livets chance! Jeg ville give alt for at få lov til at studere under den store doktor, Gustaf VanHvordan! Spild ikke denne mulighed, doktor!", c="Vidunderligt. Tag din kittel på, vi starter med det samme!"},
  [6627] = {n="Vidensprøven", l="Besvar Braug Dunsånds spørgsmål korrekt og tal derefter med ham igen. Han vil blive i Stenhøj-bjergene, når du er klar.", d="Du har bragt mig bogen, og nu er det tid til dit spørgsmål. Er du klar?\n\nTiden er ikke et problem, <Class>, så lad dig ikke presse. Du må tage så lang tid, du vil, til at svare.", p="Livet er fyldt med spørgsmål, <Class>. Du vil aldrig kunne besvare dem alle, men med lidt tid og studier bliver du måske en smule mere vidende.", c="Godt gået, <Class>. Du har studeret teksten, jeg bad dig om, og nu har du bestået endnu en af vores prøver."},
  [6628] = {n="Vidensprøven", l="Besvar Parqual Finttallas' spørgsmål korrekt og tal derefter med ham igen. Han bliver i Underbyen, indtil du er klar.", d="Så er tiden atter kommet. Som en viden-studerende har du vist stor udholdenhed ved at påtage dig min opgave.\n\nOg nu tilbyder jeg dig dit spørgsmål. Hvis du er klar, så tal til mig igen, og tag al den tid, du behøver, <Name> - der er intet pres for at svare hurtigt.", p="Der er kun én regel, jeg mener, du må kende, hvis du vil overleve i denne verden: Jo mere du ved, desto mere ser du.\n\nHvis du studerer, hvis du observerer, så begynder du at se ting i verden, som ingen anden <Race> vil se.", c="Godt gået, <Name>. Jeg tvivlede på, om du havde studeret teksten, jeg bad dig hente, men du har svaret korrekt."},
  [6721] = {n="Jægerens Vej", l="Tal med Dazalar i Dolanår.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal besøge Dazalar i Dolanår. Han kan sætte dig på vejen til at få et kæledyr af dit eget.", c="Ja, det er tid, <Class>."},
  [6722] = {n="Jægerens Vej", l="Tal med Dazalar i Dolanår.", d="Hej, unge jæger. Du virker for mig til at være dygtig nok til at håndtere et udyr og træne det som din ledsager.\n\nDu skal besøge Dazalar i Dolanår. Han kan sætte dig på vejen til at få et kæledyr af dit eget.", c="Ja, det er tid til at træne dig..."},
  [6761] = {n="Den Nye Grænse", l="Tal med Mathrengyl Bjørnegænger ved Cenarion-enklaven i Darnassos.", d="Jeg har overdraget min næstkommanderende, Mathrengyl Bjørnegænger, at tage sig af Månelundens opfordring om hjælp. Tal med ham om denne sag - IKKE med mig.\n\nLad mig give dig nogle... venlige... råd. Det er mig, der førte os ud af mørket - IKKE Cenarion-kredsen i Månelunden - da alt var tabt for vores race. Teldrassal giver os alle nyt liv! De vil have dig til at tro noget andet, og at tro på deres propaganda ville være en dåres opgave.\n\nJeg overlader det til dig at afgøre, om du er en dåre eller ikke.", c="Ja <Class>, tak fordi du kom. Jeg beklager misforståelsen... luften er tyk af mistillid mellem ærkedruiden her og Vogter Remulos i Månelunden. Hver mistænker den anden for kneb, og at mærkelige fordærvelser af Teldrassal stadig fortsætter uden ophør, er fortsat et problem her. Det gør ikke meget for at dæmpe mistilliden.\n\nUanset hvad består vores pligt over for Cenarion-kredsen... selvom dem, der leder den, måske er uenige med hinanden."},
  [6762] = {n="Rabine Saturnus", l="Tal med Rabine Saturnus i landsbyen Nathavn i Månelunden. Månelunden ligger mellem Ondskoven og Vintervår, og man kommer derind ad en sti ude fra Tømmerkæft-fæstningen.", d="Til denne opgave søger Vogter Remulos' hofmester i Månelunden - Rabine Saturnus - hjælp til at udforske de enorme ødemarker langt mod vest for Tanarys... og endnu længere mod vest end Un'Gorø. Du finder ham i Nathavn, Månelundens hovedlandsby.\n\nDit arbejde vil uden tvivl være til enorm gavn for os alle, men jeg råder dig til at træde varsomt. Der er spændinger mellem Darnassos og Månelunden... spændinger, der måske vokser sig større med tiden.", c="Jeg er Rabine Saturnus, og på vegne af Vogter Remulos og alle indbyggerne i denne hellige lund byder jeg dig velkommen.\n\nJeg sætter pris på din interesse og iver efter at hjælpe Cenarion-kredsen. Jeg ved også, at Ærkedruiden fra Darnassos har givet udtryk for sin misbilligelse over, at du hjælper os. Vær tryg ved, at det er til det gode, og at du vil være sikker mod alle ubetænkte gengældelser, du måtte blive udsat for.\n\nDu er blandt venner her, <Name>."},
  [6804] = {n="Forgiftet vand", l="Brug Neptunors Aspekt på forgiftede elementarer i de østlige Pestlande. Bring 12 Disharmoniske armbeskyttere og Neptunors Aspekt til Hertug Hydraksis i Azsyra.", d="En styrke af elementarspejdere blev sendt til Lordaerons østlige pestlande, og sygdommen dér vred og smittede dem. Vandherrerne kan ikke tillade denne krænkelse af vores renhed!\n\nTag denne phiol. I den er en mængde af ét Neptunors Aspekt. Hvis den bruges på de pestramte elementarer, vil den bekæmpe giften i deres kroppe og kurere dem! Men deres indre konflikt vil drive dem ud i en bølgende galskab.\n\nBesejr de disharmoniske bølger og bring mig deres bindende armbeskyttere.", p="Har du armbeskytterne?", c="Du har klaret dig godt, <Class>. De fordærvede elementarer, du kurerede, var en fornærmelse mod alle vandmasser. Vores styrke ligger i vores renhed, og hvis vi skal vinde vores krig mod de andre, må vi forblive stærke."},
  [6805] = {n="Storme og Rumlere", l="Dræb 15 Støvstormere og 15 Ørkenrumlere, og vend derefter tilbage til Hertug Hydraksis i Azsyra.", d="Vi, vandets elementarer, fører krig mod væsener af de lavere elementer. Hvis du virkelig er vores allierede i denne konflikt, så vis mig din overbevisning!\n\nLangt mod syd, i ørkenlandet Silitus, skurrer tjenerne af luft og jord rundt i et hjørne af klippen ved navn Krystaldalen. De beskytter magtgenstande mod mindre væsener, dødelige, og selvom jeg ikke ved, hvorfor de gør det, ønsker jeg at forpurre deres bestræbelser.\n\nTag til Krystaldalen i Silitus og besejr vores fjender, og vend derefter tilbage til mig.", p="Fejhed er ikke noget, vi ser med gode øjne, <Class>. Tag til Silitus og bevis dit mod.", c="Dit mod er bevist, ligesom din værdi for os. Måske har jeg fremtidige opgaver til dig, opgaver mere passende for en værdsat allieret af Vandherrerne."},
  [6821] = {n="Glødeseerens Øje", l="Bring Glødeseerens Øje til Hertug Hydraksis i Azsyra.", d="Du har vist mig, at du kan besejre vores fjender og udføre missioner, der fremmer Vandherrernes sag. Men indtil nu har du kun mødt mindre fjender... hvis du stilles over for en mægtig fjende, kan du så sejre?\n\nDet er din nye opgave.\n\nHøjt oppe i Sortklippe-spiret har orkerne fanget en tjener af ild, Pyrovagten Glødeseer. Find hans fangehul, slå hans fangevogtere ihjel, og dræb derefter glødeseeren. Bring mig hans øje, og det vil vise mig din værdi.", p="Har du Øjet, <Class>? Har du styrken til at træde ind i Sortklippe-spiret?", c="Ah, så du har styrken. Og du har også snilden, for Sortklippe-spiret er mere end en match for rå styrke alene.\n\nJa, <Name>, du kan endnu vise dig at være en værdifuld allieret for os..."},
  [6822] = {n="Lavakernen", l="Dræb 1 Ildherre, 1 Smeltende Kæmpe, 1 Oldtidens Kerne-Hund og 1 Lavasurrer, og vend derefter tilbage til Hertug Hydraksis i Azsyra.", d="<Name>, måske er det tid til at give dig en rigtig prøvelse. Er du klar?\n\nPå bunden af Sortklippe-dybderne findes en passage til Lavakernen. Det er en fæstning for vores fjende, holdt af de mægtigste ildtjenere på denne verden.\n\nTag til Lavakernen, <Name>. Vis mig, at du har styrken og viljen til at besejre det, du finder dér.\n\nOg hvis du har allierede blandt dit folk, så saml dem. Intet mindre end en hær kan håbe på at træde ind i Lavakernen og overleve.", p="Din succes i Lavakernen venter, <Name>.", c="Du har gjort, hvad de fleste af dit slags ville anse for umuligt. Du har stået over for væsnerne i Lavakernen og triumferet!\n\nFor et så lille væsen har du vist stor ressourcefuldhed.\n\nEn dag kan vi måske indgå en ægte alliance mellem dit folk og Vandherrerne."},
  [6823] = {n="Hydraksis' agent", l="Opnå et Æret ry hos de Hydraksiske Vandherrer, og tal derefter med Hertug Hydraksis i Azsyra.", d="Hvis du virkelig ønsker en alliance med os, så inviterer jeg dig til at føre krig mod vores fjender, tjenerne af luft, jord og ild. Hvert nederlag, du påfører dem, vil svække deres fodfæste her og yderligere bevise din troskab til vores sag.\n\nKampagnen vil være lang, men hvis du holder ud, vil din herlighed og ære være stor.", p="Din kampagne er ikke færdig endnu, <Name>. Tag ud og besejr vores fjender, tjenerne af luft, jord og ild, og en dag får du måske en plads i Vandherrernes hal.", c="Dine bedrifter mod vores fjender runger gennem Vandherrernes kamre, <Name>. Nogle mente, at din skikkelse er for lille og skrøbelig til at kæmpe i vores krig, men du har gjort store fremskridt. Du har fortjent respekt blandt os, en ufattelig bedrift."},
  [6824] = {n="Fjendens hænder", l="Bring Lysfrons, Svovlrons, Helvedas' og Shazzras hænder til Hertug Hydraksis i Azsyra.", d="<Name>, din tjeneste er af stor værdi for os, så vi er tøvende med at sende dig på denne sidste mission, for vi ønsker ikke at miste en så nyttig agent.\n\nMen dens succes ville fremme vores krigsindsats enormt, og... det blev vurderet som værd at risikere dig for.\n\nVi ønsker, at disse kaptajner i Lavakernen bliver tilintetgjort: Lysfron, Svovlron, Helvedas og Shazzra. Dræb dem og bring mig deres hænder!\n\nDenne opgave vil kræve alle de ressourcer, du råder over, <Name>, men hvis du kan gøre det, vil Ildherrerne få et forfærdeligt slag.", p="Har du besejret Lysfron og de andre, <Name>? Har du fjendens hænder?", c="Du har hænderne! Du besejrede ildkaptajnerne! Det havde jeg ikke troet muligt, hvis jeg ikke kendte dig og det, du er i stand til.\n\n<Name>, dine bedrifter er talløse, men ordet om denne sidste bedrift vil sende bølger gennem Vandherrerne. Dit navn kan en dag blive en legende for os.\n\nTal med mig igen, <Name>. Jeg har måske endnu en opgave..."},
  [6844] = {n="Umber, Arkivar", l="Tag det Indkrystalliserede Silithid-objekt til Umber - Cenarion-kredsens arkivar - i landsbyen Nathavn i Månelunden.", d="Der er stadig meget at lave her, men jeg synes, det er nøglen at tage dette tilbage til kredsen for analyse. Stol på mig - arbejdet vil stadig være her, når alt dette er overstået. Hvis det er en dagbog inde i denne klistrede kitin, så ville kredsen endelig få et vindue til fortiden!\n\nTag dette til kredsens arkivar i Nathavn. Han hedder Umber, og manden er genial. Lidt skør, ja, men alligevel genial! Umbers redningsbøger er i langt værre stand end denne. Hvis det kan reddes, kan han gøre det.", p="Nå, hej dér! Hrmm...\n\nLad mig være lidt ærlig over for dig, ven... du lugter lidt harsk. Lidt af en slem stank, kan man sige. Nu fornærmer jeg ikke dit væsen personligt. Jeg siger bare... i fremtiden vil du måske gerne friske dig lidt op, efter du kommer ind fra marken. Så gør du lidt mere positivt indtryk ved første møde!\n\nUanset... hvad kan jeg gøre for dig?", c="Store abe-tudser! Hvad har du dér? Det er lidt bogformet, tror jeg... Jeg prøver at knække denne skal med den.\n\nLayo sendte dig til mig fra Silitus? Jeg har kun hørt meget dæmpede rygter - som jeg vel ikke er så dæmpede, når man tænker over det - om rædslerne, der foregår derude. Læg dertil min manglende lyst til alt insektagtigt, og så har du opskriften på, at jeg må blive her hos bøgerne!"},
  [6845] = {n="Afdækning af fortidens hemmeligheder", l="Tal med Rabine Saturnus i landsbyen Nathavn i Månelunden.", d="Under alle omstændigheder bør du kigge forbi igen hurtigt... hvis du vil vide, hvad der var derinde. Så snart jeg finder ud af, hvad det er, og om det faktisk er en bog, vil jeg med glæde dele informationen med dig.\n\nI mellemtiden ville jeg tjekke ind hos hulemoderen i denne lille bjørnelejr, Rabine. Uden tvivl vil han gerne vide, hvilke skøre krumspring du har været i gang med. Lad aldrig hulemoderen vente, <Name>... medmindre du vil overhældes med honning.\n\nDet er sket, stol på mig.", c="Ah, <Name> - jeg håbede, du ville kigge forbi. Det glæder mig at se dig frisk.\n\nJeg har fået besked om, at du ville komme ind fra marken, og jeg ville personligt udtrykke Cenarion-kredsens taknemmelighed for den hjælp, du hidtil har ydet os. Der er uden tvivl flere hemmeligheder at afdække fra Silitus; din levering til Umber bør vise sig at være meget interessant, når den er afdækket. Modtag venligst dette som et tegn på vores fortsatte påskønnelse for din hjælp.\n\nTak, generøse <Class>."},
  [6961] = {n="Storfaderen Vinter er her!", l="Tal med Storfaderen Vinter; han befinder sig nær Røgskovs Græsgange-handelsområdet i Orgrimgrad.", d="Hav en vidunderlig Vinterslør, ven! Husk at sige hej til Storfaderen Vinter! Hvis du har været flink i år, vil du modtage vidunderlige godbidder på Vinterslørets festmåltids dag. Husk at fortælle ham, hvad du håber at få i år!\n\nHusk også at lægge lager af godbidder til dem, der har været flinke i år. Vi har et godt udvalg at vælge imellem. Frisk fra vores gård til din tallerken - det er Røgskovs Græsgange-sund godhed!", c="Ho ho hej. Jeg er Storfaderen Vinter, og jeg - med venlig hilsen fra de fine folk hos Røgskovs Græsgange... \"Frisk fra vores gård til din tallerken, det er Røgskovs Græsgange-sund godhed\" - vil gerne ønske dig et fantastisk Vinterslørets festmåltid.\n\nHvis du har været god i år, får du måske godbidder fra Røgskovs Græsgange som din godbid til Vinterslørets festmåltid. Hurra."},
  [6962] = {n="Godbidder til Storfaderen Vinter", l="Bring 5 Ingefærskiver og en Iskold malk til Storfaderen Vinter i Orgrimgrad.", d="Hey, kan du gøre Storfaderen Vinter en tjeneste, øh, lille dreng?\n\nIkke for at tale unødigt om mig selv i tredje person, men Storfaderen Vinter har været i gang hele dagen, og han kunne godt bruge en godbid selv. Nogle ingefærskiver og iskold malk at skylle dem ned med ville virkelig gøre det godt. Tror du, du kunne være en ven af Storfaderen og hente nogle til mig?", p="Al snakken om godbidder har givet mig lyst til nogle selv. Mmmm... ingefærskiver og malk...", c="Du er en rigtig hjælper for gamle Storfaderen Vinter dér, <Name>. Hav et godt Vinterslørets festmåltid.\n\nHer er lidt noget... du ved, for indsatsen."},
  [6963] = {n="Stjålne Vinterslør-godbidder", l="Find Røgskovs Græsgange-efterforskeren, der er forsvundet i de snedækkede egne af Alterac-bjergene.", d="Hør... ikke for at knuse sæsonens magi her, men Røgskovs Græsgange kunne bruge noget hjælp - den slags, I eventyrertyper er kendt for at give.\n\nVi mangler en vigtig forsendelse af godbidder, der skulle genopfylde vores lager til sæsonen, og nu mangler vi også agenten fra Røgskovs Græsgange, som vi sendte ud i marken for at finde den! Vær venlig - forsendelsen blev sidst set i Alterac-bjergene, og det er dér, vores mand tog hen for at lede efter den.\n\nSe om de begge er derude, sikre og velbehold!", c="D-d-du kan h-h-høre mig! Tak til b-b-bundlinjen!\n\nJeg er ikke rigtig en s-s-snemand - mit n-n-navn er Sække, og jeg a-a-arbejder for Orgrimgrad-a-a-filialen af Røgskovs Græsgange... J-j-jeg blev sendt herud for at lede efter en m-m-forsvundet pakke, da jeg blev angrebet af et v-v-væsen, jeg aldrig har s-s-set før!\n\nSå m-m-meget kold..."},
  [6964] = {n="Årsagen til højtiden", l="Tal med Sagorne Kammarsti i Visdommens Dal i Orgrimgrad om Vinterslørets festmåltid.", d="Gaver, godbidder, presents... bah, siger jeg!\n\nDisse kobolder forurener den sande betydning af denne sæson - Vinterslørets festmåltid. Det er en tid for fornyelse; landet sover under et tæppe af sne, bragt af Storfaderen Vinter, som IKKE er den klodsede tåbe derovre i den røde dragt!\n\nHvis du er interesseret i at lære, hvad festmåltidet handler om, så spørg Sagorne Kammarsti. Jeg er sikker på, at han bliver overrasket over, at nogen interesserer sig for historie frem for at få gaver.", c="Vinterslørets festmåltid, siger du? Desværre havde det i fortiden en mere betydningsfuld mening for os taurener. I dag ser det ud til, at andre har forvandlet legenden om denne fornyelsessæson til noget, der hjælper med at sælge slik og gaver.\n\nDet er ikke overraskende, at Pelsmund er bitter over den slags forandring. Han og andre taurener som ham klamrer sig til vores fortid som et krigsbanner. Selvom jeg synes, at lidt festlighed altid er godt, er det vigtigt at huske festmåltidets oprindelse."},
  [6983] = {n="Du er en ond en...", l="Find og bring de Stjålne Godbidder tilbage til Kaymard Kobbernyp i Orgrimgrad. Sidst kendt i besiddelse af den Afskyelige Grinebider, som menes at befinde sig et sted i de snedækkede egne af Alterac-bjergene.", d="Et væsen kaldet \"Den Afskyelige Grinebider\" er den, d-d-der stjal vores forsendelse af t-t-godbidder, <Name>. Vær d-d-forsigtig dog! Han er d-d-den, der forvandlede mig til dette s-s-snedækkede rod!\n\nDu kommer til at få brug for hjælp til at f-f-konfrontere ham. Jeg har set ham v-v-vandre rundt overalt, hvor y-y-yetierne er; han er s-s-sikkert her et s-s-sted! F-f-find godbidderne, <Name>, tag dem t-t-tilbage til Røgskovs Græsgange i Orgrimgrad, og f-f-fortæl dem, at jeg h-h-har brug for at blive optøet!", p="<Name> - vores Vinterslørets festmåltid vil være ødelagt uden de godbidder til at genopfylde lageret! Graccu selv vil gå glip af at dele sine dejlige kødpaier med alle de gode drenge og piger i sæsonen...", c="Du fandt den! Du har reddet Røgskovs Græsgange's Vinterslørets festmåltid!\n\nStakkels Sække... vi sørger for at sende et hold derud og finde ud af, hvordan vi kan optø ham. Forhåbentlig er han tilbage i tide til festmåltidets dag; han bliver dog nødt til at indhente den tabte tid i arbejdet. Alligevel ville dette slet ikke have været muligt, hvis det ikke var for dig!"},
  [6984] = {n="En tak fra Røgskovs Græsgange!", l="Tal med Storfaderen Vinter i Orgrimgrad.", d="Vi hos Røgskovs Græsgange sætter pris på, at de stjålne godbidder er blevet fundet, <Name>. Som tak vil vi gerne tilbyde dig en særlig gave... præsenteret af ingen ringere end Storfaderen Vinter selv!\n\nTal venligst med Storfaderen Vinter, så vil han give dig din Vinterslørets festmåltid-gave fra os her hos Røgskovs Græsgange. Fra vores gård til din tallerken er det altid Røgskovs Græsgange-sund godhed... takket være dig, selvfølgelig!", c="Ho ho hej, eventyrer!\n\nKobolderne fortalte mig, at du har fortjent en særlig gave i denne højtid, og jeg er glad for at give den til dig. Værsgo - hav et vidunderligt Vinterslørets festmåltid i år og i alle sæsoner fremover."},
  [7003] = {n="Zappede kæmper", l="Brug Zorbins Ultra-Krymper til at zappe enhver form for kæmpe, der findes i Vildalas, om til en mere håndterlig form. Bring 15 Miniaturiseringsrester, fundet på de zappede versioner af disse kæmper, til Zorbin Fjolleri ved havnen i Glemte Kyst, Vildalas.", d="Jeg bliver nødt til at gøre noget ved kæmperne, hvis jeg bliver her ude! De er bestemt ikke gode for forretningen, vel?\n\nJeg har arbejdet på en variant af en gnomisk krympestråle, men jeg bruger overlegne kobold-teknologiske fremskridt i dens konstruktion! I et forsøg på at undgå ulejligheder for mig selv, såsom død, vil jeg gerne have, at du prøver den på en af kæmperne i Vildalas. Du bør finde miniaturiseringsrester på dem, når du har krympet dem - bring mig nogle tilbage!", p="Miniaturiseringsrester, kan jeg forsikre dig, er en værdifuld vare, når det kommer til ingeniørarbejde! Nå, det er værdifuldt, fordi det hjælper mig med at sikre, at zapperen ikke gør noget så skuffende som at eksplodere på brugeren.\n\nJeg mener, for de zappere, der ikke er den, jeg gav dig. Helt bestemt!", c="Splendifimøst! Ikke alene er jeg glad for at se, at du er vendt tilbage med resterne, men også med alle dine store lemmer intakte! Det vil sige, der var jo aldrig nogen fare ved at bruge Ultra-Krymperen, var der vel!\n\nJeg sætter stor pris på din indsats på mine vegne, <Name>. Du er virkelig en ven af kobolder overalt. Modtag dette som et tegn på min påskønnelse!"},
  [7021] = {n="Storfaderen Vinter er her!", l="Tal med Storfaderen Vinter; han befinder sig nær Røgskovs Græsgange-handelsområdet i Orgrimgrad.", d="Hav en vidunderlig Vinterslør, ven! Husk at sige hej til Storfaderen Vinter, som lige nu er i Orgrimgrad! Hvis du har været flink i år, vil du modtage vidunderlige godbidder på Vinterslørets festmåltids dag. Husk at fortælle ham, hvad du håber at få i år!\n\nHusk også at lægge lager af godbidder til dem, der har været flinke i år. Vi har et godt udvalg at vælge imellem. Frisk fra vores gård til din tallerken - det er Røgskovs Græsgange-sund godhed!", c="Ho ho hej. Jeg er Storfaderen Vinter, og jeg - med venlig hilsen fra de fine folk hos Røgskovs Græsgange... \"Frisk fra vores gård til din tallerken, det er Røgskovs Græsgange-sund godhed\" - vil gerne ønske dig et fantastisk Vinterslørets festmåltid.\n\nHvis du har været god i år, får du måske godbidder fra Røgskovs Græsgange som din godbid til Vinterslørets festmåltid. Hurra."},
  [7022] = {n="Storfaderen Vinter er her!", l="Tal med Storfaderen Vinter; han befinder sig nær Røgskovs Græsgange-handelsområdet i Jernsmede.", d="Hav en vidunderlig Vinterslør, ven! Husk at sige hej til Storfaderen Vinter! Hvis du har været flink i år, vil du modtage vidunderlige godbidder på Vinterslørets festmåltids dag. Husk at fortælle ham, hvad du håber at få i år!\n\nHusk også at lægge lager af godbidder til dem, der har været flinke i år. Vi har et godt udvalg at vælge imellem. Frisk fra vores gård til din tallerken - det er Røgskovs Græsgange-sund godhed!", c="Ho ho hej. Jeg er Storfaderen Vinter, og jeg - med venlig hilsen fra de fine folk hos Røgskovs Græsgange... \"Frisk fra vores gård til din tallerken, det er Røgskovs Græsgange-sund godhed\" - vil gerne ønske dig et fantastisk Vinterslørets festmåltid.\n\nHvis du har været god i år, får du måske godbidder fra Røgskovs Græsgange som din godbid til Vinterslørets festmåltid. Hurra."},
  [7023] = {n="Storfaderen Vinter er her!", l="Tal med Storfaderen Vinter; han befinder sig nær Røgskovs Græsgange-handelsområdet i Jernsmede.", d="Hav en vidunderlig Vinterslør, ven! Husk at sige hej til Storfaderen Vinter, som lige nu er i Jernsmede! Hvis du har været flink i år, vil du modtage vidunderlige godbidder på Vinterslørets festmåltids dag. Husk at fortælle ham, hvad du håber at få i år!\n\nHusk også at lægge lager af godbidder til dem, der har været flinke i år. Vi har et godt udvalg at vælge imellem. Frisk fra vores gård til din tallerken - det er Røgskovs Græsgange-sund godhed!", c="Ho ho hej. Jeg er Storfaderen Vinter, og jeg - med venlig hilsen fra de fine folk hos Røgskovs Græsgange... \"Frisk fra vores gård til din tallerken, det er Røgskovs Græsgange-sund godhed\" - vil gerne ønske dig et fantastisk Vinterslørets festmåltid.\n\nHvis du har været god i år, får du måske godbidder fra Røgskovs Græsgange som din godbid til Vinterslørets festmåltid. Hurra."},
  [7024] = {n="Storfaderen Vinter er her!", l="Tal med Storfaderen Vinter; han befinder sig nær Røgskovs Græsgange-handelsområdet i Orgrimgrad.", d="Hav en vidunderlig Vinterslør, ven! Husk at sige hej til Storfaderen Vinter, som lige nu er i Orgrimgrad! Hvis du har været flink i år, vil du modtage vidunderlige godbidder på Vinterslørets festmåltids dag. Husk at fortælle ham, hvad du håber at få i år!\n\nHusk også at lægge lager af godbidder til dem, der har været flinke i år. Vi har et godt udvalg at vælge imellem. Frisk fra vores gård til din tallerken - det er Røgskovs Græsgange-sund godhed!", c="Ho ho hej. Jeg er Storfaderen Vinter, og jeg - med venlig hilsen fra de fine folk hos Røgskovs Græsgange... \"Frisk fra vores gård til din tallerken, det er Røgskovs Græsgange-sund godhed\" - vil gerne ønske dig et fantastisk Vinterslørets festmåltid.\n\nHvis du har været god i år, får du måske godbidder fra Røgskovs Græsgange som din godbid til Vinterslørets festmåltid. Hurra."},
  [7025] = {n="Godbidder til Storfaderen Vinter", l="Bring 5 Ingefærskiver og en Iskold malk til Storfaderen Vinter i Jernsmede.", d="Hey, kan du gøre Storfaderen Vinter en tjeneste, øh, lille dreng?\n\nIkke for at tale unødigt om mig selv i tredje person, men Storfaderen Vinter har været i gang hele dagen, og han kunne godt bruge en godbid selv. Nogle ingefærskiver og iskold malk at skylle dem ned med ville virkelig gøre det godt. Tror du, du kunne være en ven af Storfaderen og hente nogle til mig?", p="Al snakken om godbidder har givet mig lyst til nogle selv. Mmmm... ingefærskiver og malk...", c="Du er en rigtig hjælper for gamle Storfaderen Vinter dér, <Name>. Hav et godt Vinterslørets festmåltid.\n\nHer er lidt noget... du ved, for indsatsen."},
  [7028] = {n="Snoede ondskaber", l="Saml 25 Theradriske krystalskulpturer til Pil i Desolace.", d="Krystalhulerne i Terramoks ligger mod vest, dybt inde i Marodon... Det er et gammelt sted med megen historie. Og jeg er ude efter at få fat i noget af den, <Class>. Relikvier fra de gamle guder ligger skjult bag de gigantiske døre.\n\nHvis du er villig til at trodse de snoede ondskaber, der findes i Marodon, tror jeg, at jeg kan gøre det tiden værd for dig. Saml de theradriske krystalskulpturer, du finder, og bring dem til mig.\n\nNår jeg har skulpturerne, vil jeg kunne... studere dem. Disse kræfter har hvilet alt for længe...", p="Stil ikke spørgsmål!\n\nDu har min anmodning.", c="Ha ha ha! Jeg vidste, du ville komme tilbage.\n\n<Pil mumler.>\n\n...Så let at overtale.\n\n...Gør alt for den rette pris. He he he..."},
  [7029] = {n="Ækeltunge-fordærvelse", l="Fyld den Belagte Himmelblå Phiol ved den orange krystalpøl i Marodon.\n\nBrug den Fyldte Himmelblå Phiol på Ækelstængel-rankerne for at tvinge den fordærvede Giftige Afkom frem.\n\nHel 8 planter ved at dræbe disse Giftige Afkom, og vend derefter tilbage til Vark Kampar i Skyggebytte-landsbyen.", d="En satyr ved navn Ækeltunge har fordærvet Marodons huler og hæmmet væksten af mange af de planter, der findes derinde.\n\nTag denne phiol, <Name>. Fyld den ved den orange krystalpøl, der findes inde i hulerne; belægningen inde i phiolen vil modvirke giftstofferne og gøre den til et helbredende middel.\n\nFind Ækelstængel-rankerne inde i de orange huler, og brug den rensede væske på dem. Fordærvelsen vil blive fjernet fra planten, men vær opmærksom på, at Ækeltunge stadig vil kontrollere den. Han kan finde på at bruge den mod dig...", p="Hvis du kan helbrede planten, vil den begynde at gro igen. Vi må gøre, hvad vi kan, <Name>...", c="Tak for at returnere dette, <Name>. Med den resterende væske, du bragte mig, kan jeg fortsætte mine studier.\n\nSelvom der stadig er meget at gøre, har du hjulpet med at helbrede noget af den fordærvelse, som Ækeltunge spredte gennem Marodon. Modtag venligst dette med min taknemmelighed."},
  [7041] = {n="Ækeltunge-fordærvelse", l="Fyld den Belagte Himmelblå Phiol ved den orange krystalpøl i Marodon.\n\nBrug den Fyldte Himmelblå Phiol på Ækelstængel-rankerne for at tvinge den fordærvede Giftige Afkom frem.\n\nHel 8 planter ved at dræbe disse Giftige Afkom, og vend derefter tilbage til Talendra i Nijels Punkt.", d="En satyr ved navn Ækeltunge har fordærvet Marodons huler og hæmmet væksten af mange af de planter, der findes derinde.\n\nTag denne phiol, <Name>. Fyld den ved den fordærvede orange pøl, der findes inde i hulerne; belægningen inde i phiolen vil modvirke giftstofferne og gøre den til et helbredende middel.\n\nFind Ækelstængel-rankerne inde i de orange huler, og brug den rensede væske på dem. Fordærvelsen vil blive fjernet fra planten, men vær opmærksom på, at Ækeltunge stadig vil kontrollere den. Han kan finde på at bruge den mod dig...", p="Hvis du kan helbrede planten, vil den begynde at gro igen. Vi må gøre, hvad vi kan, <Name>...", c="Tak for at returnere dette, <Name>. Med den resterende væske, du bragte mig, kan jeg fortsætte mine studier.\n\nSelvom der stadig er meget at gøre, har du hjulpet med at helbrede noget af den fordærvelse, som Ækeltunge spredte gennem Marodon. Modtag venligst dette med min taknemmelighed."},
  [7042] = {n="Stjålne Vinterslør-godbidder", l="Find Røgskovs Græsgange-efterforskeren, der er forsvundet i de snedækkede egne af Alterac-bjergene.", d="Hør... ikke for at knuse sæsonens magi her, men Røgskovs Græsgange kunne bruge noget hjælp - den slags, I eventyrertyper er kendt for at give.\n\nVi mangler en vigtig forsendelse af godbidder, der skulle genopfylde vores lager til sæsonen, og nu mangler vi også agenten fra Røgskovs Græsgange, som vi sendte ud i marken for at finde den! Vær venlig - forsendelsen blev sidst set i Alterac-bjergene, og det er dér, vores mand tog hen for at lede efter den.\n\nSe om de begge er derude, sikre og velbehold!", c="D-d-du kan h-h-høre mig! Tak til b-b-bundlinjen!\n\nJeg er ikke rigtig en s-s-snemand - mit n-n-navn er Sække, og jeg a-a-arbejder for Jernsmede-a-a-filialen af Røgskovs Græsgange... J-j-jeg blev sendt herud for at lede efter en m-m-forsvundet pakke, da jeg blev angrebet af et v-v-væsen, jeg aldrig har s-s-set før!\n\nSå m-m-meget kold..."},
  [7043] = {n="Du er sådan en gemen en...", l="Find og bring de stjålne godter tilbage til Wulmort Klingelomme i Jernsmede. Han menes sidst at have været i besiddelse af den Afskyelige Grinebider, som man har set et sted i de snedækkede egne af Alterac-bjergene.", d="En s-s-skabning ved navn \"Den Afskyelige Grinebider\" er den, s-s-som stjal vores forsendelse af g-g-godter, <Name>. Vær d-d-forsigtig! Det er h-h-ham, der gjorde mig til dette s-s-snedækkede rod!\n\nDu k-k-kommer til at have brug for h-h-hjælp til at k-k-konfrontere ham. Jeg har s-s-set ham v-v-vandre rundt, hvor yetierne er; han er s-s-sikkert her et s-s-sted! F-f-find godterne, <Name>, t-t-tag dem med t-t-tilbage til Røgskovens Græsgange i Jernsmede, og s-s-sig til dem, at j-j-jeg skal t-t-tøs op!", p="<Name> - vores Vinterslørets Festmåltid bliver ødelagt uden de godter, vi skal bruge til at fylde op igen! Graccu selv går glip af at dele sine lækre kødpaier med alle de gode drenge og piger i år...", c="Du fandt den! Du har reddet Røgskovens Græsganges Vinterslørets Festmåltid!\n\nStakkels Sack... vi sørger for at sende et hold derud for at finde en måde at tø ham op på. Forhåbentlig er han tilbage til festdagen; han bliver dog nødt til at indhente den tabte arbejdstid. Men det her ville slet ikke være muligt, hvis det ikke var for dig!"},
  [7044] = {n="Legender om Marodon", l="Gendan de to dele af Fejrebras' scepter: Fejrebras-stangen og Fejrebras-diamanten.\n\nFind en måde at tale med Fejrebras på.", d="En mørk satyr ved navn Herre Vyletunge spredte sin ondskab gennem disse snoede huler og forgiftede sindet på alle indenfor. Han holder stadig til bag de lilla krystaller.\n\nVyletunge skabte også et levende symbol på sin fordærvelse ved navn Gifxion, som bor bag de orange krystaller. Sammen har de stjålet de to dele af min brors scepter. Fejrebras, min bror... han vandrer blindt rundt derinde, forbandet af korruption.\n\nDu må hjælpe ham! Find stykkerne, og tal med min bror... på en eller anden måde.", p="Jeg er vågnet fra et mareridt, der syntes at aldrig ville ende...", c="Nu hvor du har gendannet de to dele af min scepter, har jeg håb om, at Marodon en dag kan blive befriet for den vyle fordærvelse."},
  [7045] = {n="Et tak fra Røgskovens Græsgange!", l="Tal med Storfaderen Vinter i Jernsmede.", d="Vi i Røgskovens Græsgange sætter stor pris på, at de stjålne godter er fundet, <Name>. Som tak vil vi gerne give dig en særlig gave... overrakt af ingen ringere end Storfaderen Vinter selv!\n\nTal venligst med Storfaderen Vinter, så vil han give dig din Vinterslørets Festmåltid-gave fra os her i Røgskovens Græsgange. Fra vores gård til din tallerken er det altid Røgskovens Græsgange-sund godhed... takket være dig, selvfølgelig!", c="Ho ho hej, eventyrer!\n\nKoboldene fortalte mig, at du har fortjent en særlig gave i julesæsonen, og jeg er glad for at kunne give den til dig. Vær så god - hav et vidunderligt Vinterslørets Festmåltid i år og i alle sæsoner fremover."},
  [7046] = {n="Fejrebras' scepter", l="Hjælp Fejrebras den Genløste, mens han skaber Fejrebras' scepter.\n\nTal med ham, når ritualet er fuldført.", d="Min scepter var engang en kilde til håb for mig. Dens kraft gav mig friheden til hurtigt at rejse gennem disse huler. Jeg havde håbet at bringe fred til min onkels ånd... Det er en opgave, jeg nu overlader til dig.\n\nFor at de to dele igen kan blive til én, får jeg brug for din hjælp til at udføre ritualet. Følg venligst efter mig, og lyt til mine instrukser, mens jeg kanaliserer den energi, der kræves for at genforene stangen med diamanten.\n\nSammen skal vi skabe Fejrebras' scepter igen!", p="Hvis du vil genstarte ritualet, så opgiv venligst vores første forsøg og tal så med mig igen.", c="Tag venligst dette, og vid at den kraft, der nu er tildelt dig, skal bruges til det gode. Fortsæt din rejse gennem hulerne, og med håb vil du finde min onkels levn. Der venter stor fare på dig, <Name>.\n\nTal med mig igen, hvis behovet opstår."},
  [7061] = {n="Vinterslørets Festmåltid", l="Læs gerne bogen \"Vinterslørets Festmåltid\" for at lære mere om højtiden. Når du er færdig med bogen, skal du aflevere den til Kærne Blodhov i Tordenklippe.", d="Her - hvis du er interesseret i at lære mere om Vinterslørets Festmåltid, så læs denne bog. Selvom jeg mener, at vores anerkendelse af legenden er den rette, er jeg lærd nok i legender til at værdsætte samlingen af al information i én enkelt kilde.\n\nNår du er færdig, så tag bogen med til Kærne Blodhov i Tordenklippe. Jeg ved med sikkerhed, at han vil blive glad for at høre, at andre har fået interesse for vores folks overleveringer.", p="Jeg byder dig velkommen til Mulgorr og vores ydmyge samfund i Tordenklippe, ven. Jeg interesserer mig altid for dem, der vælger at interessere sig for riget, dets folk og dets overleveringer. Er det derfor, du står foran mig?", c="Legenderne og overleveringerne om Vintersløret er dem, der over årene er forsvundet fra offentlighedens søgelys. Ja, jeg ved godt, at koboldene hjælper med at genoplive sæsonen for deres egne formål, men at vores folk i det mindste på en eller anden måde reflekterer over den, gør godt for at holde sådan en overlevering i live.\n\nDit ønske om at komme ud over det materielle og lære om vores fortid er et beundringsværdigt træk, unge <Class>. Jeg hylder din visdom."},
  [7062] = {n="Årsagen til højtiden", l="Tal med Historiker Karnik i Opdagelsesrejsendes Liga i Jernsmede om Vinterslørets Festmåltid.", d="Gaver, godter, gaveæsker... bah, siger jeg!\n\nDe koboldene besudler denne sæsons sande betydning - Vinterslørets Festmåltid. Det er en tid for fornyelse; landet sover under et tæppe af sne, bragt af Storfaderen Vinter, som IKKE er den klodsede tølpe derovre i den røde dragt!\n\nHvis du er interesseret i at lære, hvad Festmåltidet handler om, så spørg Historiker Karnik i Opdagelsesrejsende-Ligaen. Jeg er sikker på, at han bliver overrasket over, at nogen interesserer sig for historie frem for at få gaver.", c="Vinterslørets Festmåltid, siger du? Ak, i fordums tid havde det en mere væsentlig betydning for os dværge. I dag virker det, som om andre har gjort legenden om Storfaderen Vinter til noget, der hjælper med at sælge slik og gaver.\n\nDet er ikke overraskende, at Goli er bitter over den slags forandring. Han og andre dværge som ham holder fast i vores fortid som et krigsbanner. Selvom jeg synes, at en lille fejring altid er god, er det vigtigt at huske Festmåltidets oprindelse."},
  [7063] = {n="Vinterslørets Festmåltid", l="Læs gerne bogen \"Vinterslørets Festmåltid\" for at lære mere om højtiden. Når du er færdig med bogen, skal du aflevere den til Kong Magni Bronzeskæg i Jernsmede.", d="Her - hvis du er interesseret i at lære mere om Vinterslørets Festmåltid, så læs denne bog. Selvom jeg mener, at vores anerkendelse af legenden er den rette, er jeg lærd nok til at værdsætte samlingen af al information i én enkelt kilde.\n\nNår du er færdig, så tag bogen med til Kong Magni Bronzeskæg. Jeg ved med sikkerhed, at han vil blive glad for at høre, at andre har fået interesse for de ældre legender.", p="Jeg byder dig velkommen til Jernsmedes Rige, ven. Jeg interesserer mig altid for dem, der vælger at interessere sig for riget, dets folk og dets overleveringer. Er det derfor, du står foran mig?", c="Legenderne og overleveringerne om Vintersløret er dem, der over årene er forsvundet fra offentlighedens tanker. Selvom jeg er klar over, at koboldene hjælper med at genoplive sæsonen for deres egne formål, gør det godt, at borgerne i det mindste på en eller anden måde tænker over den, for at holde sådan en overlevering i live.\n\nDit ønske om at komme ud over det materielle og lære om vores fortid er et beundringsværdigt træk, unge <Class>. Jeg hylder din lærde natur."},
  [7064] = {n="Jordens og frøets fordærvelse", l="Dræb Prinsesse Theradras og vend tilbage til Selendra nær Skyggebytte Landsby i Forødelse.", d="Dybt inde i Marodon lever et ondt kaosvæsen--Prinsesse Theradras er en elementær jordkraft med forbindelse til De Gamle Guder. For længst siden indledte hun og Zaetar, Cenarius' førstefødte søn, et forhold. Afkommet fra deres tid sammen blev kendt af Kalimdørs folk som kentaurer. Evigt taknemmelige væsener, kentaurerne dræbte Zaetar og har nu hans levn i deres varetægt. Min opgave her er at finde dem, der er stærke nok til at dræbe Theradras, så vi kan genvinde Zaetars levn, før vi vender tilbage til Stenkløften.", p="Jeg ville helst kæmpe denne kamp alene, men vi står uden andre muligheder--vi har brug for dem, der er stærkere, og Azerots racer har uden tvivl vist, at de kan overvinde sådanne ting, når de arbejder sammen. Så det er til dig, vi vender os for hjælp.\n\nJeg håber blot, at det er nok.\n\nZaetar, bror til Remulos, bragte mange smerter over denne verden, og det endte til sidst med hans egen død. Jeg håber blot, at jeg ikke har forårsaget flere dødsfald ved at bede dig om at hjælpe os.", c="Dette er de mest vidunderlige nyheder, <Name>! Tak!\n\nJeg vil tale med Marandis og bede om hans visdom om Zaetars levn, men du har i det mindste overvundet den sværeste opgave.\n\nJeg fik at vide, at hvis vi lykkedes med vores mission, havde jeg tilladelse til at belønne dem, der hjalp os. Jeg fik disse genstande som tegn fra vores folk--du må vælge én."},
  [7065] = {n="Jordens og frøets fordærvelse", l="Dræb Prinsesse Theradras og vend tilbage til Vogter Marandis ved Nijels Punkt i Forødelse.", d="Dybt inde i Marodon lever et væsen af kaos og ondskab, <Name>. Prinsesse Theradras er en elementær jordkraft, på en eller anden måde beslægtet med De Gamle Guder. For længst siden blev hun opsøgt af Zaetar, Cenarius' førstefødte søn. Afkommet af deres... forhold er de væsener, der kendes som kentaurer. Evigt taknemmelige væsener, kentaurerne dræbte Zaetar, og nu holder Theradras hans levn. Min opgave her er at finde dem, der er stærke nok til at dræbe Theradras, så vi kan genvinde Zaetars levn, før vi vender tilbage til Stenkløften.", p="Jeg føler vægten af at pålægge de dødelige racer min bøn, men vi står uden andre muligheder. Azerots racer har uden tvivl vist, at de kan overvinde sådanne ting, når de arbejder sammen, så det er til dem, jeg beder om hjælp.\n\nJeg håber blot, at det er nok.\n\nZaetar, bror til Remulos, bragte mange smerter over denne verden, og det endte til sidst med hans egen død. Der ligger en lektie i det for os alle, hvis vi er kloge nok til at se den.", c="Dette er de mest vidunderlige nyheder, <Name>! Tak!\n\nSelvom det bekymrer mig, at du ikke kunne bringe Zaetars levn tilbage, hvem er jeg så til at stille spørgsmålstegn ved viljen hos Cenarius' førstefødte? Måske vil kentaurernes vilje nu bryde, og deres tørst efter blod aftage--vi kan kun håbe det.\n\nHvis vores mission lykkedes, fik jeg disse genstande til at belønne alle, der hjalp os. Du må vælge én som tegn på taknemmelighed."},
  [7066] = {n="Livets frø", l="Søg Remulos i Månelunden og giv ham Livets frø.", d="De vanskabte kentaurer--mine sønner og døtre--har brug for deres far.\n\nSe dig omkring--dette sted emmer af håb og alt, hvad min far Cenarius prædiker. Det er opstået fra mig! Og jeg kan ikke tage det fra dem... ikke engang for deres forbrydelser mod mig.\n\nMen der er én ting, jeg vil bede dig om for at berolige min brors sind. Tag dette... det er det første frø, der faldt fra det liv, mine levn nærede. Fortæl ham, at min ånd bliver her, og at jeg lever videre. Jeg er sikker på, at han vil forstå det.", p="Du har fordærvelsens lugt over dig, <Name>... ligesom mange eventyrere i dag. Men der er noget ved dig, der er anderledes. Er der noget, du er kommet for at tale med mig om? Du har en glorie omkring dig, der virker bekendt, men jeg kan ikke placere den.\n\nJeg beder dig indtrængende: fortæl mig, hvorfor du har søgt en audiens hos mig.", c="Så har min bror endelig fundet fred? Jeg er stolt over at have levet til at se denne dag. I al hans arrogance og vrede troede jeg virkelig, at han var tabt for os, men dette... dette symbol på hans offer beviser blot, at han ikke er tabt--han er blot blevet genfødt. Han indtager sin plads i naturen, som det var hans pligt.\n\nTak, <Name>. Ved at bringe mig dette har du sikret en lille smule håb, som jeg troede, jeg engang havde mistet. Dette frø vil en dag blive vigtigt for folket i dette krigshærgede land... det kan jeg fornemme."},
  [7067] = {n="Pariaens vejledning", l="Læs Pariaens vejledning. Skaf derefter Unionsamuletten fra Marodon og returnér den til Kentaur-Pariaen i det sydlige Forødelse.", d="Selvom jeg er forvist som kætter, er mine overbevisninger stadig sande--det alene driver mig fremad. Men for at min skæbne kan blive fuldendt, har jeg brug for hjælp fra en udenforstående... en, der ikke tilhører nogen kentaurstamme.\n\nOpgaven kræver, at nogen træder ind i Marodons hellige haller--en gravplads, mit folk beskytter, og kun de mest fromme får nogensinde lov til at træde indenfor.\n\nHvis du vil hjælpe mig, behøver du kun at nikke. Jeg vil give dig et pergament med min vejledning på. Læs det igennem og overvej mine ord.", p="Hvad har du besluttet, <Name>? Kan du hjælpe mig? Vil du sætte din fod på hellig grund for at hjælpe mig med at smede én stor kentaurstamme!?", c="Det er det, <Race>! Det er det! Nu kan jeg begynde den store opgave med at forene stammerne. Tak.\n\nTag venligst dette for din indsats. Jeg håber, at når vi mødes næste gang, vil det være på meget andre vilkår."},
  [7068] = {n="Skyggeskår-fragmenter", l="Saml 10 Skyggeskår-fragmenter fra Marodon og returnér dem til Uthel'nay i Orgrimgrad.", d="Stærk magi findes på kentaurernes hellige sted... Marodons hellige sted. Forødelses-stammerne beskytter stedet med deres liv, men de ka' ikke stoppe os i at tage det, vi har brug for.\n\nDu, du tager hen til det der Marodon-sted og finder stenvæsnerne lavet af skyggeskår. Du bringer mig de lilla krystaller, og Uthel'nay laver noget til dig for din tid.\n\nStedet er farligt, så måske ta'r du nogle venner med.", p="Har du fundet krystallerne endnu? Kraftritualer, besværgelser af stor styrke--de skyggeskår kan måske være meget nyttige i alle slags arkane magier.", c="Ah, de her er perfekte til min magi. Her, tag en af de her smykker og vær på vej... jeg ha' en masse studerin' at lave."},
  [7070] = {n="Skyggeskår-fragmenter", l="Saml 10 Skyggeskår-fragmenter fra Marodon og returnér dem til Ærkemager Tervosh i Theramøre på kysten af Støvsumpen.", d="Jeg har for nylig begyndt at teste forskellige krystaller og deres arkane egenskaber. Dame Stoltmoor har givet mig lov til at bede rejsende på vej ind i Forødelse om at søge efter et sted kaldet Marodon. Inde i det forfaldne tempel findes store elementarer sammensat af lilleagtige sten, som jeg har kaldt skyggeskår.\n\nHvis du beslutter dig for at tage den vej og finder nogle af krystallerne, ville jeg være meget taknemmelig. Jeg kunne endda smede dig et smykke af dem, hvis du ønskede det.", p="Har du taget turen endnu? Jeg er klar over, at det ville være ganske farligt, men hvis du lykkes, ville det være meget umagen værd.", c="Disse er perfekte, <Name>. Jeg fik faktisk også andre eventyrere til at vende tilbage derfra, og af dem kunne jeg smede disse... vær så venlig at tage en for dit hårde arbejde. Og tak igen for flere prøver at studere."},
  [7081] = {n="Alterac-dalens kirkegårde", l="Angrib en kirkegård, og vend derefter tilbage til Sergent Durgen Stormspids i Alterac-bjergene.", d="Kirkegårdene i Alterac-dalen er eftertragtede områder. Både Horden og Alliancen kæmper voldsomt om disse hellige grunde. Er du, <Name>, klar til at deltage i kampen?\n\nJeg vil have dig til at angribe en fjendtlig kirkegård. Find en kirkegård med Hordens banner midt i, og træk det op af jorden! Gør det, og din opgave er fuldført....\n\nMen hvis du også kan holde kirkegården i et par minutter, så vil vores tropper snart komme og afløse dig.", p="<Name>, du har endnu ikke angrebet en kirkegård. Vend tilbage til mig, når opgaven er fuldført!", c="Godt gjort! Kirkegårde er afgørende for vores kontrol over Alterac-dalen. Når du erobrer en, hjælper du med at sikre Alliancens suverænitet her.\n\nGå nu, <Name>. Vend tilbage til slagmarken, og hvis du ser en kirkegård under Hordens kontrol... så ved du, hvad du skal gøre!"},
  [7082] = {n="Alteracs kirkegårde", l="Angrib en kirkegård, og vend derefter tilbage til Korporal Teeka Blodsnerre i Alterac-bjergene.", d="Frontlinjerne i Alterac-dalen flytter sig hele tiden. Territorierne skifter hånd frem og tilbage, mens vi møder vores modstandere i dødelig kamp. Og kirkegårde, <Name>, er der, hvor kampene raser voldsomst.\n\nJeg vil have dig til at angribe en kirkegård, som Alliancen holder! Find en kirkegård med et Alliance-banner midt i og træk det op af jorden.\n\nGør det, og din opgave for mig er fuldført, men... hvis du holder kirkegården i et par minutter, så bliver den vores, og tropper kommer og afløser dig.", p="Angrib en kirkegård, som Alliancen holder!", c="Godt gjort, <Name>! Med hver kirkegård under vores kontrol vil vores fjenders ånder vandre rundt, mere fortabte og målløse."},
  [7101] = {n="Tårne og bunkere", l="Erobr et fjendtligt tårn, og vend derefter tilbage til Korporal Teeka Blodsnerre i Alterac-bjergene.", d="Tårne og bunkere er vigtige positioner, og vi må erobre og holde dem alle! Så med det for øje vil jeg have dig til at angribe en bunker, der kontrolleres af fjenden.\n\nFor at gøre det skal du gå ind i en med et Alliance-banner. Du vil se et andet banner indenfor. Træk det banner ud, og et hvidt Horde-banner vil dukke op i dets sted. Godt gjort!\n\nPå det tidspunkt er din opgave for mig fuldført, men hvis du holder stedet længe nok, og hvis Alliancen ikke tager det tilbage, så bliver det ødelagt!", p="Du har endnu ikke angrebet en bunker, <Name>! Venter du på, at andre tager din ære?", c="Jeg hørte om din missions succes! Det glæder mig...\n\nVores tropper kan nu storme frem uden straf og vise Alliancen, at Alterac-dalen ikke er et sted for dem!"},
  [7102] = {n="Tårne og bunkere", l="Ødelæg banneret ved et fjendtligt tårn eller en bunker, og vend derefter tilbage til Sergent Durgen Stormspids i Alterac-bjergene.", d="Tårne og bunkere er nøglepositioner i forsvaret, så vi må holde så mange som muligt! Jeg vil have dig til at angribe et tårn eller en bunker i Alterac-dalen.\n\nFor at gøre det skal du gå ind i et tårn med et Horde-banner på toppen. Du vil se et andet fjendtligt banner indenfor. Træk det banner ud, så dukker et hvidt Alliance-banner op i dets sted. Godt gjort!\n\nPå det tidspunkt er din mission for mig fuldført, men hold området længe nok, og hvis Horden ikke tager det tilbage, så bliver det ødelagt!", p="Du har endnu ikke angrebet et tårn, <Name>! Hvad venter du på?", c="Jeg modtog en felt-rapport om, at du hjalp med at sikre et fjendtligt banner. Godt gjort, <Name>! Med deres distancetropper ude af position kan vi rykke slagfronten frem!"},
  [7121] = {n="Kvartermesteren", l="Tal med Stormspids-kvartermesteren.", d="<Name>, vores kvartermester har pålagt mig at sende nye rekrutter til ham. Han har brug for forsyninger fra depoter, der er gemt i minerne i Alterac, og han vil sikkert sende dig for at hente dem.\n\nFølg vejen. Du finder vores kvartermester mod vest.", c="Det er godt at se friske tropper her, <Name>, men med lidt held kommer du i kamp og bliver ikke frisk længe!\n\nTal med mig igen. Der er opgaver, jeg må drøfte med dig...."},
  [7122] = {n="Erobr en mine", l="Erobr en mine, som Stormspidserne ikke kontrollerer, og vend derefter tilbage til Sergent Durgen Stormspids i Alterac-bjergene.", d="Minerne i Alterac-dalen gemmer mere end bare mineraler. Både Frostulven og Stormspidserne har gemt overskydende forsyninger i Jerndyb- og Koldtand-minerne... det er ikke en dum idé, hvis vi bare kunne holde kontrollen over dem!\n\nErobr en mine, og vend derefter tilbage til mig. For at erobre en mine skal du gå ind i en, som vi ikke kontrollerer, og dræbe dens leder. Når du gør det, bliver minen vores, og vi sender tropper til at beskytte den!", p="Du har endnu ikke erobret minen, <Name>!\n\nNår vi kontrollerer en mine, bliver det meget lettere at samle mineraler og forsyninger fra den.", c="Du gjorde det! Godt gjort, <Name>!\n\nNår vi kontrollerer en mine og har tropper stationeret der, bliver det meget lettere at samle mineraler og forsyninger fra den."},
  [7123] = {n="Tal med vores kvartermester", l="Tal med Frostulv-kvartermesteren.", d="<Name>, Frostulv-kvartermesteren leder efter rekrutter til opgaver, der fører ind i minerne i Alterac-dalen. Tal med ham; han vil fortælle dig mere.\n\nFølg vejen mod vest ind i bunkeren, og tag så udgangen mod vest, så finder du vores kvartermester.", c="Hil dig, <Name>! Det er godt at se en <Class> som dig, ivrig efter at gøre sin del for Horden. Tal med mig igen, for jeg har vigtige opgaver til dig..."},
  [7124] = {n="Erobr en mine", l="Erobr en mine, og vend derefter tilbage til Korporal Teeka Blodsnerre i Alterac-bjergene.", d="Mens kampen raser over Alterac-dalens landskab, raser den også gennem Koldtand- og Jerndyb-minerne. Begge er rige kilder til mineraler, og begge bruges til at opbevare forsyninger; det er ingen undren, at de er så højt værdsat!\n\nHjælp vores krigsindsats, <Name>! Erobr en af minerne for Horden! For at erobre en mine skal du gå ind i en, som vi ikke kontrollerer, og dræbe dens leder. Når det er gjort, bliver minen vores, og vi sender tropper til at beskytte den!", p="Du har endnu ikke erobret en mine, <Name>! Find en, som vi ikke kontrollerer, og besejr dens leder!", c="Du erobrede en mine! Med vores egne krigere til at beskytte den bliver det meget nemmere at udvinde mineraler fra dens dybder eller samle forsyninger, der er gemt der.\n\nGodt gjort, <Name>>. Din gerning er en stor hjælp til vores kampindsats."},
  [7141] = {n="Slaget om Alterac", l="Gå ind i Alterac-dalen, besejr Hordens general Drek'Tår, og vend derefter tilbage til Prospektor Stenhugger i Alterac-bjergene.", d="Opdagelsesrejsende-Ligaen mener, at der findes artefakter i Alterac-dalen, men Frostulv-orkerne lader os ikke udforske området. Vi kan ikke lade Horden stoppe vores videnskabelige stræben! Besejr Frostulv-generalen, Drek'Tår. Når han er død, mister orkerne deres overtag.\n\nDrek'Tår befinder sig i Frostulv-fæstningen, i den sydlige del af Alterac-dalen. Besejr ham, og vend derefter tilbage til mig.", p="Af sted, <Name>. Tag til Alterac-dalen og besejr orkgeneralen!", c="Godt gjort, <Name>! Nu hvor Horden har fået en næse efter deres generals død, får vi det spillerum, vi behøver for at udforske området!"},
  [7142] = {n="Kampen om Alterac", l="Gå ind i Alterac-dalen og besejr den dværgiske general, Vanndar Stormspids. Vend derefter tilbage til Voggah Dødsgreb i Alterac-bjergene.", d="Stormspids-dværgene og deres allierede har invaderet Alterac-dalen, og vi må drive dem ud! For at vinde kampen om Alterac må vi besejre deres general, Vanndar Stormspids!\n\nDu finder Vanndar i Dun Baldrian, i den nordlige del af Alterac-dalen.\n\nØdelæg ham, <Name>, og vend derefter tilbage til mig.", p="Vi vil ikke lide dværgene i vores hjem! Fald over vores fjender og besejr deres leder, general Stormspids!", c="Godt gjort, <Name>! Stormspidserne har intet håb i denne tåbelige invasion.\n\nHa! Indtil videre har de kun fået deres general dræbt!"},
  [7161] = {n="Prøvepladsen", l="Rejs til Vildpote-hulen, der ligger sydøst for hovedbasen i Alterac-dalen, og find Frostulv-banneret. Returnér Frostulv-banneret til Krigsmester Laggrønd.", d="Hil dig, <Class>. Det er længe siden, vi har haft chancen for at svare på kampens kald. De gamle følelser vender langsomt tilbage, men når de først er vækket, flyder blodet hurtigt. Kampraseriet vender tilbage...\n\nAlle nykommere i dalen må først gennemføre kampritualet.\n\nDybt inde i Vildpote-hyænemændenes hule er et Frostulv-banner. Tag af sted og hent banneret. Bring det tilbage til mig, og jeg vil tildele dig Frostulv-indvielsens emblem.", p="Vågn op! Vågn op, <Name>! Dette er ikke en drøm. Du er virkelig fanget midt i en rasende kamp!", c="Den brændende fornemmelse, du føler, er din sjæl, der vækkes. Din ånd har accepteret opfordringen til at tage til våben.\n\nDu er nu en af Frostulvene, <Name>. Tillykke.\n\nBær dette emblem med dig til enhver tid. Når du avancerer i Frostulvenes rækker, vil jeg erstatte emblemet med andre, mere kraftfulde emblemer.\n\nMåske vil du en dag blive ophøjet blandt Frostulv-klanen. Skulle den dag nogensinde komme, vil du blive tildelt Kommandoens Øje."},
  [7162] = {n="Prøvepladsen", l="Rejs til Isvinge-hulerne, der ligger sydvest for Dun Baldrian i Alterac-dalen, og hent Stormspids-banneret. Returnér Stormspids-banneret til Løjtnant Hakkerdin i Alterac-bjergene.", d="Du er kommet lige til tiden, <Class>. Disse Frostulv-vildmænd vil bare ikke give op! Vi må vise dem Stormspidsernes styrke. De må bøje sig for vores overlegenhed.\n\nFør du begiver dig ud på slagmarken, bør du indtræde i Stormspidsernes rækker.\n\nSydvest for Dun Baldrian finder du Isvinge-hulerne. Dybt inde i hulerne er et Stormspids-banner plantet. Tag af sted og hent banneret. Bring det tilbage til mig, så har du fortjent et Stormspids-indvielsesemblem.", p="Pas på harpyerne i regionen, <Class>. De tøver ikke et øjeblik med at rive din strube ud!", c="Tag og bær dette emblem med stolthed, <Name>. Efterhånden som din rang blandt Stormspidserne vokser, vokser emblemet også. Vend tilbage til mig, når du opnår ære hos Stormspidserne, så erstatter jeg dit emblem med andre, mere kraftfulde emblemer.\n\nMåske bliver du en dag en legende på denne slagmark. Skulle den dag nogensinde komme, vil du blive tildelt Kommandoens Øje."},
  [7163] = {n="Opstig og bliv anerkendt", p="<Krigsmester Laggrønd hilser dig.>\n\nDet er din tid, <Name>. Du har gjort meget for Frostulv-klanen, og det har gjort dig til ikke blot en soldat i Frostulv, men også en ven.\n\nVelgjort! Fremvis dit begynderemblem.", c="Dette nye emblem afspejler din rang blandt Frostulverne. Bær det på dig til enhver tid.\n\nOg <Class>... Dø med ære!"},
  [7164] = {n="Æret blandt klanen", p="Det er godt at se dig igen, <Class>. Jeg havde ikke forventet, at du ville vende tilbage. Ak, du har bevist dig selv som en modig og ærefuld soldat i Frostulv.\n\nDin tid er atter kommet, <Name>. Du har opnået en ny rang og dermed et nyt emblem, der markerer denne stigning i anseelse.\n\nFremvis dit emblem.", c="<Krigsmester Laggrønd hilser.>\n\nAf sted, <Name>! Fortsæt dit forsvar af Frostulv. Denne krig skal vindes! For Drek'Tår! For Krigshøvdingen!"},
  [7165] = {n="Opnået ærefrygt", p="Så mange faldne. Blod væder markerne. Men... du lever... Du har holdt ud. Du har ført vores hære til mange sejre. For dette, soldat, har du fortjent en ny rang.\n\nFremvis dit emblem.", c="<Krigsmester Laggrønd brøler.>\n\nDe er allerede begyndt at fortælle historier om dine bedrifter, soldat. Stormspidsen ryster af frygt, når dit navn nævnes. Fortsæt!"},
  [7166] = {n="Legendariske helte", p="Din strålende kommando og kraft, <Class>. Ophøjet i Frostulvenes øjne - fjenden krymper sig ved omtalen af dit navn.\n\nRejs dig, Frostulvs Helt. Rejs dig og bliv hædret!\n\nFremvis dit emblem.", c="Snart vil alle på slagmarken stå under dit vågne øje. Kommandoen over dalen og dens tropper vil være din!"},
  [7167] = {n="Kommandoens Øje", p="Drek'Tår synger dine lovprisninger. Kalimdør summer af fortællinger om dine heltedåd. Krigshøvdingen stråler - dit standhaftige forsvar af vores klan har glædet ham meget.\n\nDu har fortjent Kommandoens Øje.\n\nFremvis dit emblem, Kommandør <Name>.", c="Kanalisér emblemets kraft. Lad fjenden høre dine ord. Hordens magt er uomtvistelig!"},
  [7168] = {n="Opstig og bliv anerkendt", p="De fleste lever ikke længe nok til at hæve sig over deres egen middelmådighed. Du har bevist dig selv som en mønstersoldat, <Class>. Tiden er kommet.\n\nFremvis dit emblem.", c="Lad vores fjender se, at en soldat med rang har slået dem ned! Kæmp for Stormspidsens ære!"},
  [7169] = {n="Æret blandt vagten", p="Basen summer af nyheder om dine bedrifter på Kampens Mark! Du har uddelt mægtige slag mod vores fjende - og knust deres moral! For dette har du fortjent en æresrang blandt Stormspidserne.\n\nFremvis dit emblem.", c="Kongen er blevet gjort bekendt med dine heltedåd på slagfronten, <Class>. Fortsæt dit standhaftige forsvar af Stormspids-vagten!"},
  [7170] = {n="Opnået ærefrygt", p="Jeg må vide, <Name>. Når du ser direkte ind i fjendens øjne, ser du så frygt? Krymper de sig nu i din nærvær? De må indse, at de er besejrede!\n\nDu har opnået ærefrygt blandt vagten. Fremvis dit emblem!", c="Da vi første gang mødtes, ville jeg aldrig have gættet, at der var en helt under opsejling. Fortsæt, soldat!"},
  [7171] = {n="Legendariske helte", p="Foran mig står en ophøjet helt fra Alliancen.\n\n<Løjtnant Hakkerdin hilser.>\n\nFå har opnået en sådan rang blandt Stormspidserne. Jeg har set fjenden falde for dig. Jeg har set deres besluttsomhed smuldre i din nærvær. Når du træder ind i kampen, bliver du håbets fyrtårn for vores styrker!\n\nFremvis dit emblem.", c="Det må da være dig, der bærer Kommandoens Øje!"},
  [7172] = {n="Kommandoens Øje", p="Lad dem høre din stemme, Kommandør <Name>! Lad dem kende frygt. Vis dem, hvilken magt Stormspidserne har i deres rækker!\n\nFremvis dit emblem.", c="Det er dig, der må føre vores tropper til sejr, Kommandør! Soldaterne står under din kommando. De vil følge dine direkte ordrer. Led dem.... Knus Frostulven."},
  [7181] = {n="Legenden om Korrak", l="Ifølge legenden dukker lederen af de mægtige Vinterøks-trolde op efter behag for at skabe kaos blandt indbyggerne i Alterac-dalen.\n\nSkulle Korrak vise sig, skal du tilintetgøre ham og vende tilbage til Krigsmester Laggrønd.", d="Stormspidserne er ikke den eneste trussel i regionen, soldat. Krigen i dalen føres på to fronter. De kannibalistiske Vinterøks-trolde kæmper også om magten.\n\nDe anføres af Korrak Blodraser - et grusomt og listigt udyr.\n\nEt angreb mod Korrak kunne vise sig at blive et knusende slag mod Vinterøks-klanen. Slå udyret og bliv belønnet!"},
  [7201] = {n="Det sidste element", l="Rejs til Sortklippe-dybderne og hent 10 Elementernes essens. Din første indskydelse er at søge i golemerne og golemskaberne. Du husker, at Vivian Ligrave også mumlede noget om elementarer.", d="Der er arbejde at hente for dem, der vover sig ned i dybderne, <Name>.\n\nMørkjernsdværgene har mestret skabelsen af yderst kraftfulde golemer.\n\nFørste rapporter fra vores spioner tyder på, at dværgene bruger en unik energikilde for at give deres skabninger uovertruffen dræbekraft.\n\nForestil dig bare, hvad vi kunne gøre med vores abominationer, hvis vi fik fat i denne elementernes essens! Vend den by på hovedet, hvis du må, men vend ikke tilbage, før du har fundet essensen! Betalingen vil være risikoen værd.", p="Vis mig dem!", c="Vidunderligt! Jeg får dem sendt med kurer til Undergrunden med det samme!\n\nOg for dig - her er betalingen, som lovet. Behold resten, din beskidte bæst!"},
  [7202] = {n="Korrak Blodraser", l="Ifølge legenden dukker lederen af de mægtige Vinterøks-trolde op efter behag for at skabe kaos blandt indbyggerne i Alterac-dalen.\n\nSkulle Korrak vise sig, skal du tilintetgøre ham og vende tilbage til Løjtnant Hakkerdin i Alterac-bjergene.", d="De hjemmehørende Vinterøks-trolde i regionen er hensynsløse barbarer, der intet hellere vil end at føje vores knogler til deres stinkende gryderet.\n\nVi må vise dem vores styrke!\n\nVi har bjerget tavler fra deres huler, der beskriver deres lederhierarki. Artefakterne tyder på, at deres leder, Korrak Blodraser, har tendens til at holde sig skjult, indtil han får en grund til at vise sin tilstedeværelse.\n\nDøden over Korrak ville betyde døden for Vinterøks-klanen! Slå ham og vend tilbage."},
  [7221] = {n="Tal med Prospektor Stenhugger", l="Tal med Prospektor Stenhugger i Dun Baldrians garnison.", d="Nå, <Name>, melder du dig til tjeneste? Fantastisk, Stormspidserne kan bruge alle, vi kan samle!\n\nTal med Prospektor Stenhugger i Dun Baldrian. Hun rekrutterer til en vital mission ind i fjendens område. Du finder Stenhugger nederst i Dun Baldrians garnison.\n\nOg hold øje, mens du bevæger dig gennem Dun Baldrian. Der er masser at lave for en hårdtarbejdende <Class>, som ikke er bange for at blive snavset om hænderne."},
  [7222] = {n="Tal med Voggah Dødsgreb", l="Tal med Voggah i Frostulv-fæstningen.", d="En <Class>? Godt! Vi er glade for at se dig i Alterac, <Name>. Indtrængende dværge og deres allierede invaderer vores dal, og vi byder alle i Horden velkommen til at slutte sig til os i retfærdigt slagteri!\n\nTal med Voggah Dødsgreb. Han leder efter agenter til en vigtig mission ind i Alliancens højborg i Alterac-dalen!\n\nDu finder Voggah i Frostulv-fæstningen."},
  [7223] = {n="Panserrester", l="Bring 20 panserrester til Murgot Dybsmed i Dun Baldrian.", d="Der raser konstant kamp i Alterac-dalen, og de forsyninger, vi får fra Jernsmede, er ikke nok til at udstyre vores erfarne tropper.\n\nHvis du finder panserrester fra slagmarken, så hjælp krigsindsatsen og bring resterne til mig!", p="Bragte du nogen panserrester, <Name>?", c="Dette er nogle gode stykker, <Name>. Jeg kan bruge dem til at smede nyt udstyr til vores tropper.\n\nHvis min forsyningsbeholdning bliver stor nok, så tør vores erfarne kampenheder måske komme på banen!"},
  [7224] = {n="Fjendens bytte", l="Bring 20 panserrester til Smed Regzar i Frostulv-landsbyen.", d="Når du kæmper mod fjenden, så saml resterne af deres rustning og bring dem til mig. Jeg vil bruge resterne til at lave rustning til vores egne tropper!", p="Hvordan går jagten, <Name>? Har du nogle panserrester til mig?", c="Disse dur fint. Jeg smelter dem om og lapper dem, og du vil aldrig kunne se, at de stammer fra de Stormspidsiske kujoner!\n\nTak, <Name>. Og lad mig pudse den rustning af dig..."},
  [7241] = {n="Til forsvar for Frostulv", l="Rejs til Alterac-dalen, placeret i Alterac-bjergene. Find og tal med Krigsmester Laggrønd - som står udenfor tunnelindgangen - for at begynde din karriere som soldat i Frostulv. Du finder Alterac-dalen nord for Tarrenmølle ved foden af Alterac-bjergene.", d="Krigstromlerne lyder fra et fjernt land, <Class>. Krigshøvdingens yndlingsklan er under angreb fra den onde Stormspids-vagt fra Jernsmede.\n\nAt dømme ud fra dit udseende kan jeg se, at du faktisk er krigshærdet og klar til at tage fat i Frostulvenes sag.\n\nDet er dig, der nu må tage næste skridt i din udvikling.\n\nNord for Tarrenmølle, i Alterac, finder du indgangen til Alterac-dalen. Det er der, du finder Krigsmester Laggrønd. Skynd dig, <Class>, for slaget er over os!", c="For at blive soldat i Frostulv må man først prøves..."},
  [7261] = {n="Den suveræne imperativ", l="Rejs til Alterac-dalen i Hillsbrad-forbjergene. Udenfor tunnelindgangen skal du finde og tale med Løjtnant Hakkerdin.\n\nFor Bronzeskæg's ære!", d="Vi kæmper et brutalt slag i Alterac-dalene. De kannibalistiske Vinterøks-trolde angriber os fra den ene side og den barbariske Frostulv-klan fra den anden. Begge må udryddes i Kong Magni Bronzeskæg's navn! Erobringen, udtyndingen og omdannelsen af det land er en suveræn og territorial imperativ for kongeriget Jernsmede.\n\nAk, soldater vokser ikke på træer! Mød op hos Løjtnant Hakkerdin udenfor Alterac-dalen for at begynde din tjeneste og opnå ære blandt Stormspidserne.", c="Lad os komme i gang!"},
  [7281] = {n="Broderlig kærlighed", l="Rejs ind på Stormspids-territoriet og slå Kommandør Karl Filips. Vend tilbage til Kommandør Louis Filips, når opgaven er løst.", d="Tragisk... Min bror står over for mig på slagmarken: en kommandør for Stormspidserne.\n\nAf de fire Stormspids-kommandører er han uden tvivl den farligste. Måske kan Dødsånd-dronningen, hvis han slås ihjel, forvandle ham, ligesom hun gjorde med mig - vise ham fejltagelsens vej...\n\nDybt inde på fjendens område finder du min bror. Slå ham og vend tilbage til mig. Jeg stoler på, at du er i stand til at fuldføre denne mission, soldat.\n\nOg soldat, gå ikke alene.", p="Hvor må det smerte ham at forblive blandt de levende, mens hans elskede bror er steget op til fuldkommenhed.", c="Dine heltedåd vil ikke gå ubemærket hen, <Name>.\n\nJeg må ikke spilde tid, hvis han skal reddes. Sylvanas må kontaktes!"},
  [7282] = {n="Broderlig kærlighed", l="Rejs ind på Frostulv-territoriet og slå Kommandør Louis Filips. Vend tilbage til Kommandør Karl Filips, når opgaven er løst.", d="Han må have fred, soldat! Han ved ikke, hvad han gør. Han er blevet en tankeløs tjener for den frygtede Dødsånd-dronning.\n\nDrag afsted over Kampens Mark, til dybet af Frostulv-territoriet. Find min bror og tilintetgør ham. Hans pine må få en ende.", p="Det er med tungt hjerte, at jeg giver en sådan ordre, soldat.", c="Huskede du at brænde liget, ikke?"},
  [7301] = {n="Faldne himmelherrer", l="Rejs til Frostulv-territoriet og led efter Vingekommandør Slidoré, Vingekommandør Vipør og Vingekommandør Ichman. Vend tilbage til Kommandør Dafi, når du har fuldført din mission.", d="Vi har dem fanget som fanger, <Race>. Jeg taler om deres vingekommandører. Det var et rasende luftslag, men de faldt til sidst! Desværre blev vores bedste piloter skudt ned under et modangreb mod Frostulv-fæstningen. Du må finde ud af, hvad der skete med dem.\n\nUndersøg Tårnpegen Vest og Frostulv-fæstningen. Dette var deres sidst kendte steder. Undersøg områderne grundigt.", p="Er der noget, jeg gerne vil høre?", c="Utroligt! Du befriede dem, ikke? Ikke? Ikke??? Nå, i det mindste ved vi, hvor de blev holdt fanget."},
  [7302] = {n="Faldne himmelherrer", l="Find ud af, hvad der blev af Vingekommandør Gusse, Vingekommandør Jeztør og Vingekommandør Mulverik. Vend tilbage til Kommandør Mulfort, når du har fuldført din mission.", d="Vores luftstøtte ligger i ruiner, <Name>. Vingekommandørerne blev skudt ned over fjendens territorium. Du må finde ud af, hvad der skete med dem, så vi kan forsøge en redningsaktion!\n\nGusse blev sidst set flyve over Isvinge-bunkeren. Jeztørs krigsrytter blev set nær Stormspidsernes savværk. Mulverik... den hensynsløse tølpe blev set styrte ned nær Dun Baldrian Nordbunkeren.\n\nDet er alle de oplysninger, jeg har. Afsted! Undersøg områderne grundigt.", p="Hvordan går jagten, soldat?", c="Velgjort! Oplysningerne, du har indhentet, vil være uvurderlige for vores sag."},
  [7361] = {n="Gunst blandt Mørkspyd", l="Du har fået til opgave at slå modstanderens nattenisse-spillere i Alterac-dalen.\n\nDræb en nattenisse og vend tilbage til Najak Hekseren ved Frostulv-fæstningen med et afhugget nattenisse-hoved.", d="<Najak snerrer.>\n\nFør nattealferne eksisterede, var der trolde. Det var fra trolde, at nattealferne kom.\n\nDeres oprørske angreb mod mit folk vil ikke blive tolereret. Hjorthelm sigter efter at udslette os - at efterlade ingen spor af dem, der bar ham og hans slags. Det vil ikke ske!\n\nFor hver nattenisse, du slår og halshugger, vil Najak give dig gunst blandt Mørkspyd. Dine bedrifter vil blive spredt over hele Kalimdør og Østkongerigerne. Gå nu og tjen Mørkspyd!", p="De søger at udrydde os? Det er dem, der skal udryddes.", c="<Name>, det er blot én af tusindvis. Ikke desto mindre et veludført stykke arbejde."},
  [7362] = {n="Allieret med taurerne", l="Du har fået til opgave at slå modstanderens gnom-spillere i Alterac-dalen.\n\nDræb en gnom og vend tilbage til Ravak Grumtotem ved Frostulv-fæstningen med en dusk gnomhår.", d="Den Ældre Heks har sendt mig til denne krigszone for at undersøge de andre væddeløb. Mere specifikt skal jeg indsamle gnom-prøver. Magata er primært interesseret i deres overlevelsesevne. Ja, gnomerne - selvom de er jammerligt svage og ubetydelige - udviser stor modstandskraft både i og uden for kamp.\n\nHeldigvis for dig leder jeg efter lejesvende til at udføre Magatas ærinder. Vend tilbage til mig med dusker af gnomhår, så skal du være kendt af taurerne som en allieret.", p="Jeg er ligeglad med, hvor håret kommer fra, <Race>.", c="Ja, dette er bestemt gnom. Velgjort, <Race>, men der er mere arbejde at gøre."},
  [7363] = {n="Den Menneskelige Tilstand", l="Du har fået til opgave at slå de modstandende menneskelige spillere ihjel i Alterac-dalen.\n\nDrep et menneske og vend tilbage til Kommandør Louis Filips (der vandrer mellem frontlinjerne og Frostulv-fæstningen) med en Menneskeknogleflis.\n\nEn kur mod den menneskelige tilstand er lige om hjørnet!", d="Mennesker er så fuldstændig afskyelige.\n\n<Kommandør Filips grimaserer.>\n\nDet er sandt, at jeg er soldat i Frostulv, men jeg forbliver en tjener for Sylvana.\n\nUnder min tjenestetid laver jeg ekstra arbejde på siden for de Mørke Apotekere i Underbyen.\n\nJeg har fået til opgave at samle menneskelige knogleflis, der skal bruges til at kurere den menneskelige tilstand.\n\nJeg har tilladelse til at overdrage opgaven til mine underordnede.\n\nFind dem. Dræb dem. Bring mig deres knogleflis.", p="Ja, det er sandt. Min bror er et menneske. Skammeligt... En plet på min nærmest pletfri rekord.", c="Det ville være nemmere, hvis de bare accepterede deres sygdom og gav sig til din helende berøring. Det ville nok også være mindre sjovt. Fortsæt! Vi kurerer dem, på den ene eller anden måde."},
  [7364] = {n="Nisseborg-dusør", l="Du har fået til opgave at slå de modstandende tyre-spillere ihjel i Alterac-dalen.\n\nDrep en tyr og vend tilbage til Dolk Svindel ved Dun Baldrian med en Tyrehov.", d="Den Høje Bastler selv har sendt mig til dette slagmark for at forsvare mine gnomiske brødre og søstre. Vi har fået besked om, at tyrerne udpeger og dræber gnomer. Værst af alt fjerner de flotte totter af gnom-hår fra de faldnes lig. Disse grusomheder må standses. Vi må gengælde dem!\n\nJeg vil have dem afhovet, <Class>. Bring mig deres hove! Vis, at du er gnomernes allierede.", p="Giv dem en halt, <Name>. De må lære, at gnomfolket ikke lader sig mobbe!", c="*Dolk kaster hoven i en bunke bag sig.*"},
  [7365] = {n="Hjortehjelms Requiem", l="Du har fået til opgave at slå de modstandende troldspillere ihjel i Alterac-dalen.\n\nDrep en trold og vend tilbage til Athrasmæn ved Dun Baldrian med Mørkspyd-trold-magi.", d="Hjortehjelm har givet ordren. Alle trolde på slagmarken skal udryddes. Deres absurde påstande om at have født nattealfer skal mødes med vold og behørig fordom.\n\nSlå dem ihjel og vend tilbage til mig med deres magi. For at gentage mig: Jeg vil have dig til at stjæle deres magi.", p="Jeg kan stadig lugte de stinkende trolde.", c="Tak, <Name>. Luften er lidt renere nu."},
  [7366] = {n="Ærkebiskoppens Nåde", l="Du har fået til opgave at slå de modstandende Forladte-spillere ihjel i Alterac-dalen.\n\nDrep en Forladt og vend tilbage til Kommandør Karl Filips (der vandrer mellem savværket og minen) med et Forladt-hjerte.", d="Ærkebiskoppen er lige så venlig, som han er klog. At en mand kan se så nådigt på sådan et ussel pak...\n\n<Kommandør Filips rister forundret på hovedet.>\n\nFor venlig... Bare alt for venlig.\n\nÆrkebiskoppen beder os have medlidenhed med de udøde og give dem hurtig og varig død. For dette store nådesbevis kræver vi blot deres sorte, sygdomsplagede hjerter.\n\nBring mig de Forladtes hjerter, så de med pomp og pragt kan brændes op i Lysets Katedral. Skynd dig, <Name>!", p="Lovet være Benedikt! Jeg er blot et støvkorn i skyggen af hans storhed. Pris ham!", c="Lovet være Benedikt! Endnu en tabt sjæl, snart reddet af Lysets hvidglødende flammer!\n\nGå afsted, o soldat af Lyset! Flere skal reddes!"},
  [7367] = {n="Afvæbning af Truslen", l="Find Frostulvenes eksplosivekspert og dræb ham. Vend tilbage til Stormspids-eksplosiveksperten, når opgaven er løst.", d="Frostulven har deres frontlinjer og baser fyldt med fælder, <Class>. Du skal holde øje med hvert skridt, når du invaderer fjendens territorium.\n\nHvis du vil slå et solidt slag mod dem, skal du ødelægge deres kilde til antipersonelminer – jeg taler om deres eksplosivekspert. Hvis du slår ham ihjel, kan du trygt afvæbne minerne. Så længe han holdes nede, forbliver minerne også nede.\n\nDu finder ham sandsynligvis i et tårn nær Isblod-garnisonen. Held og lykke!"},
  [7368] = {n="Afvæbning af Truslen", l="Find Stormspids-eksplosiveksperten og dræb ham. Vend tilbage til Frostulvenes eksplosivekspert, når opgaven er løst.", d="Jeg ved alt om landminer. Det er mig, der lægger alle minerne på frontlinjerne her, trods alt.\n\nHvis du vil afvæbne Stormspidsernes minefelter, skal du blot slå deres eksplosivekspert ihjel. Den dværgiske kujon gemmer sig utvivlsomt i det første tårn på Kampens Mark. Tag ham ud, så vender landminerne ikke tilbage, når de først er afvæbnet.\n\nHvis du faktisk slår ham ihjel, så kom tilbage hertil og lad mig vide det. Ingen god gerning bør forblive ubelønnet."},
  [7401] = {n="Efterlyst: DVÆRGE!", l="Du har fået til opgave at slå de modstandende dværgspillere ihjel i Alterac-dalen.\n\nDrep en dværg og riv rygraden ud af vedkommende. Tag dværgerygraden med til Sergent Yazra Blodsnerrer ved Frostulv-fæstningen.", d="Efter ordre fra Sergent Yazra Blodsnerrer skal alle dværge på slagmarken dræbes på stedet.\n\nHvis du slår en dværg ihjel i kamp, skal du rive rygraden ud af vedkommende og efterlade en rygradsløs bunke af stank og forrådnelse som advarsel til enhver, der vover at modsætte sig Frostulvens magt.\n\nVend tilbage til Sergent Yazra Blodsnerrer med bevis for din heltedåd.", p="Jeg handler med engros-ironi, soldat.", c="Du har nu licens til at decimere dværge i dusinvis, <Class>!\n\n<Yazra stirrer ud i den fjerne horisont et øjeblik.>\n\nMan glemmer aldrig sin første afrygning..."},
  [7402] = {n="Efterlyst: ORKER!", l="Du har fået til opgave at slå de modstandende ork-spillere ihjel i Alterac-dalen.\n\nDrep en ork og tag deres Orketand med tilbage til Korporal Norreg Stormspids ved Dun Baldrian.", d="Efter ordre fra Korporal Norreg Stormspids skal alle sunde soldater fra Stormspids dræbe enhver modstandende ork, de møder på slagmarken.\n\nSoldaterne skal fjerne en hjuvel eller tand fra fjendens gab og fremvise tanden som bevis på deres bedrift.\n\nBrug beskyttelseshandsker.", p="Har du brug for en tang til at trække tænderne ud?", c="Godt, <Name>. Jeg forventer de små mus."},
  [7441] = {n="Bitteline og Ældre Tordinsen", l="Rejs til Rædselshammeren og find dæmonlingen Bitteline. Overtal Bitteline til at give dig Tordinsens Bog om Besværgelser ved alle midler nødvendige.\n\nVend tilbage til Tordinsen ved Lariss-pavillonen i Vildalas, hvis du finder Bogen om Besværgelser.", d="Jeg slappede kun af et øjeblik, fremmede. I min hast for at undslippe den faldne prinses greb blev jeg røvet. En yderst ond dæmon, dæmonlingen Bitteline, stjal min besværgelsesbog og nøglen til de engang så store haller i Eldre'Thalas.\n\nJeg har ikke længere interesse i nøglen, for jeg har byttet min udødelighed for frihed, men jeg har desperat brug for min besværgelsesbog.\n\nFind dæmonlingen Bitteline og hent min bog.\n\nLed efter Bitteline i Krumtræ-kvarteret i Rædselshammeren.", p="Jeg fortryder intet, fremmede. Dronningen er for længst borte. Shen'dralarernes værker er blevet skæmmet af Prins Torturholdts galskab. Jeg søger kun frihed... Flugt...", c="Du har fundet den! Forbandelse over den elendige dæmonling. Ak, mine materielle ejendele er i bedste fald magre. Du må vælge blandt det, jeg har at tilbyde."},
  [7461] = {n="Galskaben Indefra", l="Du skal ødelægge vogterne omkring de 5 Pyloner, der driver Brænd'thars fængsel. Når Pylonerne er slukket, er kraftfeltet omkring Brænd'thar forsvundet.\n\nGå ind i Brænd'thars fængsel og udryd den onde dæmon, der står i dets hjerte. Til sidst skal du konfrontere Prins Torturholdt i Athenæum.\n\nVend tilbage til Shen'dralar-Oldtidens i gården, når du har gennemført denne opgave.", d="Har du hørt nok? Er du en handlingens mand?\n\nDenne galskab må få en ende. De udødeliges tidsalder er for længst forbi. Ødelæg vogterne omkring pylonerne for at sænke kraftfeltet. Når det er gjort, skal du ødelægge Brænd'thar. Med prinsens magt stærkt reduceret skal du angribe og gøre ende på ham. Hvil byens ånder til ro, eventyrer.", p="Vær på vagt, eventyrer. Prinsen er... overtalende.", c="Vi takker dig, helt."},
  [7462] = {n="Shen'dralarnes Skat", l="Vend tilbage til Athenæum og find Shen'dralarnes Skat. Hent din belønning!", d="I biblioteket, Athenæum, finder du en gammel kiste gemt under trappen. Tag fra den det, du ønsker.", c="Du åbner kisten og finder..."},
  [7463] = {n="Arkan Forfriskning", l="Rejs til Krumtræ-kvarteret i Rædselshammeren og slå vandelementaren Vandavl ihjel. Vend tilbage til Vidensvogter Lydrøs i Athenæum med Vandavl-essensen.", d="En <Race>-magiker! Hvor vidunderligt. Jeg har ikke set nogen af jeres slags i... åh, hvad foregår der nu? 500 år!\n\nJeg har noget, der kan slukke din tørst, men først skal du udføre en opgave for mig.\n\n<Lydrøs flirer.>\n\nDer er en anomali i Eldre'Thalas. En vandelementar har slået sig ned i østfløjen. Hans tilstedeværelse må katalogiseres!\n\nTag til Krumtræ-kvarteret og udvind en portion af Vandavls elementaressens. Bring den til mig, så lærer jeg dig en nyttig lille tryllekunst.", p="Ja? Kender jeg dig?", c="Vidunderligt! Hvem er du nu igen? Åh, det betyder ikke noget. Hvad skulle jeg give dig? Hrm... nå, du er magiker, så måske finder du dette nyttigt."},
  [7481] = {n="Alvelegender", l="Søg i Rædselshammeren efter Kariel Vintalus. Rapportér tilbage til Vismand Krollusk i Mojasje-lejren med de oplysninger, du måtte finde.", d="For nogle år siden flygtede en ensom alvisk mester ved navn Kariel Vintalus fra ødelæggelsen af sit hjemland med flere gamle alviske artefakter i slæbet.\n\nVores søgen efter denne tabte mester førte os fra ruinerne af Quelthalas, gennem Brændende Stepper og over havets store vidder til Vildalas.\n\nVi mistænker, at alfen søgte tilflugt i Eldre'Thalas' haller (det, der nu kendes som Rædselshammeren).\n\nDu skal finde ham, eventyrer. Hvad enten han er i live eller død, skal den viden, han bar, hentes tilbage!", p="Min medarbejder, nattealfe-lærden Runetorn, rekrutterer hendes allierede til denne opgave.", c="En skam... en tragedie. Genstandene er tabt, siger du? Intet spor af ham, hvad?"},
  [7482] = {n="Alvelegender", l="Søg i Rædselshammeren efter Kariel Vintalus. Rapportér tilbage til Lærd Runetorn i Fjermåne med de oplysninger, du måtte finde.", d="For nogle år siden flygtede en ensom alvisk mester ved navn Kariel Vintalus fra ødelæggelsen af sit hjemland med flere gamle alviske artefakter i slæbet.\n\nVores søgen efter denne tabte mester førte os fra ruinerne af Quelthalas, gennem Brændende Stepper og over havets store vidder til Vildalas.\n\nVi mistænker, at alfen søgte tilflugt i Eldre'Thalas' haller (det, der nu kendes som Rædselshammeren).\n\nDu skal finde ham, eventyrer. Hvad enten han er i live eller død, skal den viden, han bar, hentes tilbage!", p="Min medarbejder, tyre-vismanden Krollusk, rekrutterer sine allierede til denne opgave.", c="En skam... en tragedie. Genstandene er tabt, siger du? Intet spor af ham, hvad?"},
  [7486] = {n="En Heltes Belønning", l="Hent din belønning fra Hydraksis' Kiste.", d="<Name>, dine tjenester for Krigsherrerne overgik alt, hvad vi kunne forvente af denne verdens indbyggere.\n\nVi forstår ikke jeres folks begreber om taknemmelighed eller om at belønne gode gerninger, men i dette tilfælde... måske er en belønning berettiget.\n\nUnder brændingen ved denne øs sydlige base finder du en kiste. I den finder du din... belønning.\n\nGå, <Name>. Hent din belønning.", c="Hydraksis' stemme stiger op fra vandets overflade...\n\n\"Vælg det, der bedst passer dig, <Name>. Må det beskytte dig mod Vandherrernes fjender.\""},
  [7487] = {n="Indstilling til Kernen", l="Rejs til indgangsportalen til Lavakernen i Sortklippe-dybderne og hent et Kernefragment. Vend tilbage til Lothøs Revnevogter i Sortklippebjerget, når du har hentet Kernefragmentet.", d="Revner rører sig, rives op og kollapser alle vegne omkring os, <Race>. Ikke to skridt fra, hvor jeg står, er der en revne, der fører gennem dybderne i Sortklippebjerget og ind i Ildherrens gab.\n\nOverrasket? Synd... De dødelige racer kan ikke forstå det, de ikke kan se, røre eller mærke.\n\nJeg forsikrer dig, at portalen er der, og at adgang er mulig.\n\nHar jeg vakt din interesse? Indstillingen er simpel. Tag ned i Sortklippe-dybderne og hent et kernefragment. Bring det til mig, så indstiller jeg din essens til portalen.", p="At springe gennem åbningen nu kunne ende i katastrofe... for dig.", c="Træd gennem åbningen til min højre, så befinder du dig inde i Lavakernen."},
  [7488] = {n="Lethtendris' Væv", l="Bring Lethtendris' Væv til Latronicus Månespyd i Fjermåne-fæstningen i Vildalas.", d="Magikeren Lethtendris, en ondskabsfuld blodalf, hvis brutalitet kun overgås af hendes fordrejede afhængighed af magi, er flygtet ind i Rædselshammeren. Hun har skabt en indretning, et væv, der skal fange de magiske energier på det sted, og vi frygter, at hun, hvis ingen stopper hende, vil forvolde uoprettelig skade på vores verden!\n\nStop hende, <Name>. Find hende og hent hendes væv. Hun er sandsynligvis i nærheden af satyrerne i Krumtræ-kvarteret i Rædselshammeren. Bring vævet til mig, så dets kraft kan frigives sikkert tilbage i vildmarken...", p="Har du vævet, <Name>? Dets koncentrerede magiske energi må spredes!", c="Du har hentet vævet! Godt gjort, <Name>! Lethtendris er ligesom mange alver af hendes slags blind over for de farer, misbrug af magi kan forvolde vores verden. De tror, de er magiens herrer; de indser ikke, at de er slaver under deres egen afhængighed. Hendes død gør mig ondt, men den var nødvendig.\n\nTak, <Name>. Jeg lader energierne i vævet frigøre sikkert over et stort område, og så ødelægger jeg det for at forhindre fremtidige magiske misbrug."},
  [7489] = {n="Lethtendris' Væv", l="Bring Lethtendris' Væv til Talo Tornhov i Mojasje-lejren i Vildalas.", d="Blodalfen Lethtendris er gået over stregen. Så ivrig var hun efter at samle magisk kraft, at hun trodsede sine brødre og skabte en indretning af lumsk design, et væv beregnet til at sive de forurenede magiske energier fra Rædselshammeren. Selv nu samler hun disse energier og planlægger at udløse dem mod sine fjender.\n\nLethtendris må stoppes. Find hende i Krumtræ-kvarteret i Rædselshammeren, besejr hende og bring mig hendes væv, så det kan returneres til mere klartænkende blodalfer til studier.", p="<Name>, har du Lethtendris' Væv?", c="Du har gjort det godt, <Name>. Dette væv indeholder enorme mængder af Rædselshammerens magi, og jeg frygter, hvilken skade der kan blive sluppet løs, hvis disse energier blev udnyttet af en så uansvarlig person som Lethtendris. Jeg er ked af hendes død, men jeg ved, at hun aldrig ville have skilt sig af med sit væv, mens hun levede.\n\nTak, <Name>. Jeg vil sende vævet til magiske studerende, der er mere ansvarlige end Lethtendris. De bliver de nye vogtere af dets kraft."},
  [7490] = {n="Sejr for Horden", l="Tag Onyksias hoved med til Træl i Orgrimgrad.", d="Du har udført det umulige. Yngelmoderen for Den Sorte Drageflugt ligger død for dine fødder. Tag hendes hoved og præsenter det for din Krigshøvding.", p="<Træls stoiske væsen ændrer sig et øjeblik, da han ser Onyksias enorme hoved. Den mægtige Dømmehammer blev næsten draget.>", c="Dette er en stor sejr for Horden, <Name>. Så mange gange har du æret din Krigshøvding. Nu er det tid for Krigshøvdingen at ære dig."},
  [7491] = {n="For Alle at Se", l="Søg Overherre Runtak i Styrkens Dal.", d="Overherre Runtak venter på din ankomst i Styrkens Dal.\n\n<Træl hilser dig.>\n\nLad ikke din offentlighed vente, helt.", c="Vælg din belønning, og lad fejringen af din strålende sejr begynde."},
  [7492] = {n="Mojasje-lejren", l="Tal med Talo Tornhov i Mojasje-lejren i Vildalas.", d="Talo Tornhov, en tyre-ældste i Vildalas, sender en anmodning om hjælp. Han gav få detaljer, men han sagde, at han har brug for agenter til en sag, der er både delikat... og dyster.\n\nTjen Horden, <Name>. Tag til Mojasje-lejren i Vildalas og tal med Talo.", c="Ah, det er godt at se en <Class> adlyde min tilkaldelse. Jeg har brug for dine tjenester, <Name>, og frygter, at de vil føre dig ad en farlig vej...\n\nEn vej ind i Rædselshammeren."},
  [7493] = {n="Rejsen Er Lige Begyndt", c="En drageslagter og en øvet læderarbejder? Du holder op med at forbløffe, helt. Jeg er ydmyg.\n\nVær venlig at modtage det, jeg straks vil lære dig. Denne viden vil vise sig uvurderlig, hvis du skal ødelægge, hvad der er tilbage af Den Sorte Drageflugt.\n\nSkab kappen af yngelmoderens skæl. Den vil beskytte dig og dine allierede mod den brændende ånde fra Sortklippes Herre... Nefarian."},
  [7494] = {n="Fjermåne-fæstningen", l="Tal med Latronicus Månespyd i Fjermåne-fæstningen i Vildalas.", d="<Name>! Din hjælp er nødvendig i Vildalas!\n\nEn fredløs magiker, Lethtendris, er flygtet til de gamle alviske ruiner Eldre'Thalas, nu kaldt Rædselshammeren. Det menes, at hun har en genstand med farlig magisk energi, som må hentes tilbage.\n\nLatronicus Månespyd beder om agenter, der skal gå ind i Rædselshammeren og hente genstanden fra Lethtendris.\n\nTjen Alliancen! Søg Latronicus i Fjermåne-fæstningen i Vildalas.", c="Hil dig, <Name>. Jeg er glad for at se dig, men beklager, at vores møde ikke foregår under bedre forhold.\n\nLyt godt efter, for jeg har en vital opgave til dig..."},
  [7495] = {n="Sejr for Alliancen", l="Tag Onyksias hoved med til Højlord Bolvar Fordrågon i Stormvind.", d="Du har udført det umulige. Yngelmoderen for Den Sorte Drageflugt ligger død for dine fødder. Tag hendes hoved og præsenter det for Højlorden.", p="Ved Uthars skæg!", c="I så mange år var jeg fanget under hendes betagende blik. Endelig at se retfærdigheden skredet frem og Stormvinds ære genoprettet! I dag fejrer vi denne strålende sejr!"},
  [7496] = {n="At Fejre Gode Tider", l="Søg Stor Mattsen i Heltenes Dal.", d="Søg Stor Mattsen i Heltenes Dal, <Name>. Han vil forvente dig...", c="Få bliver hædret med sådan en ceremoni, <Name>. Vær venlig at vælge din belønning, så vi kan begynde fejringen."},
  [7497] = {n="Rejsen Er Lige Begyndt", c="En dragedræber og en garvet læderarbejder? Du holder op med at forbløffe mig, helt. Jeg er ydmyg.\n\nVær venlig at modtage det, jeg nu vil lære dig. Denne viden vil vise sig uvurderlig, hvis du skal udslette det, der er tilbage af Den Sorte Drageflugt.\n\nSkab kappen af skællene fra yngelmoderen. Den vil beskytte dig og dine allierede mod Sortklippe-herrens brændende åndedræt... Nefarian."},
  [7498] = {n="Garona: Et Studie i Snigen og Forræderi", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7499] = {n="Kodeks for Forsvar", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7500] = {n="Arkanistens Kogebog", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7501] = {n="Let og Hvordan Man Svinger Det", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7502] = {n="Tæmning af Skygger", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7503] = {n="Den Største Race af Jægere", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7504] = {n="Hellig Pølse: Hvad Let Ikke Vil Fortælle Dig", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7505] = {n="Frostchok og Dig", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7506] = {n="Den Smaragdgrønne Drøm...", l="Returner bogen til dens rette ejere.", d="Bindet bærer Athenæums mærke.", p="Du har genvundet et bind!", c="Fremragende arbejde, <Race>. Skulle du finde flere bind, så tøv ikke med at returnere dem til os.\n\nNår tiden går, har vi en tendens til at skifte rundt og endda tilføje nye belønninger for returnering af manglende bind."},
  [7507] = {n="Forørs Kompendium", l="Returner Forørs Kompendium om Dragedrab til Athenæum.", d="Du har afdækket noget af stor betydning. Denne bog er ulig nogen, du har set.\n\nDet ser ud til, at nogen eller noget har formået at knække Athenæums segl. Teksten indeni er forvansket og knap læselig.", p="Ah, et af vores største kompendier. Denne har været savnet i evigheder.", c="Du kunne have fået en hel del guld for denne bog på det sorte marked, <Name>. Især eftersom den beskyttende segl er brudt, hvilket efterlader dragedræbningens hemmeligheder synlige for enhver med den nødvendige intellekt til at fortære kundskaben i de hellige sider.\n\nMåske er en stor belønning på sin plads... Tja, en belønning der vil kræve enorm indsats at opnå.\n\n<Lydrøs grinner.>"},
  [7508] = {n="Smedningen af Quel'Klingen", l="Giv det sløve og flade alve-sværd til Vidensvogter Lydrøs.", d="Hvis du vil tage denne opgave på dig, så præsenter Lydrøs for det sløve sværd.", p="Fortræffeligt, lad os begynde...", c="Hvis du formår at trænge ind i dragens hule, opvarme klingen under hendes ildagtige åndedræt og til sidst hærde den i hendes blod, vil jeg binde klingen til din brug."},
  [7509] = {n="Smedningen af Quel'Klingen", l="Du skal få Onyxia til at åndedrætte ild på den uaffyrede Oldtidens Klinge. Når dette er gjort, tag den nu opvarmede Oldtidens Klinge. Vær advaret: En opvarmet Oldtidens Klinge vil ikke forblive opvarmet for evigt - tiden er afgørende.\n\nDet sidste trin, før du vender tilbage til mig, er at dræbe udyret og drive den opvarmede Oldtidens Klinge ned i hendes lig.\n\nGør dette, og Quel'Klingen vil være din.", d="Tag den uaffyrede Oldtidens Klinge med til Onyxias hule, og indled kamp med hende.\n\nNoget snedighed må bruges til at opvarme klingen. Under kamp vil hun sikkert forsøge at forbrænde dig med sit ildagtige åndedræt. Du må plante den uaffyrede Oldtidens Klinge i nærheden og håbe, at det ildagtige åndedræt opvarmer klingen. Hvis du overlever dette, tag den nu opvarmede Oldtidens Klinge og gør færdig med dragen.\n\nDyk den opvarmede Oldtidens Klinge ned i hendes rygende lig for at smede den behandlede Oldtidens Klinge.", p="Måske en dag vil en anden svinge det prismatiske sværd.", c="<Lydrøs mumler noget uforståeligt.>\n\nSom lovet, <Class>, Quel'Klingen selv."},
  [7521] = {n="Thunderaan Vindsøgeren", l="For at befri Thunderaan Vindsøgeren fra hans fængsel skal du præsentere højre og venstre halvdel af Bindinger af Vindsøgeren, 10 stænger Elementium og Ildherrens Essens for Højlord Dæmitrian.", d="Jeg har fortalt dig alt, hvad jeg ved, <Name>. Det er dig, der skal finde elementium. Det er dig, der skal udslette Ildherrens legemlige form.\n\nGør dette, og få Thunderaans velsignelse.", p="Bring verden på knæ, hvis du må!", c="Selv i drømme turde jeg ikke forudse denne dag.\n\nSkue, dødelige.\n\nSKUE HAN, DER ER ÆLDRE END EKSISTENSEN!\n\nSKUE HAN, DER HAR MØDT TITAN OG GUD LIGE SÅ!\n\nRejs dig, min herre! Bryd løs fra dine lænker!"},
  [7541] = {n="Tjeneste for Horden", c="Det vil tage tid for vores lærde at studere det vedhæng, du bragte os. Men for din tjeneste for Horden vil jeg gerne tilbyde dig et lille tegn.\n\nTak, <Name>. Dine gerninger bringer ære til dig og til os."},
  [7562] = {n="Mor'zul Blodbringer", l="Tal med Mor'zul Blodbringer i Brændende Stepper.", d="<Name>, dine dykken ned i de mørke kunster er dybe. Din herredømme over overnaturlige væsener er vokset så stærkt... måske er du klar til at binde en af de berømte Frygtrosser til dig.\n\nRitualet til at fremkalde udyret fra dets hjem kræver stor magt og store ressourcer, men hvis du ønsker at dominere det episke ridedyr, så tal med Mor'zul Blodbringer. Han har slået lejr nær Stormenes Alter i Brændende Stepper.\n\nGå, <Name>. Denne opgave vil være farlig, men en Hekser af din kaliber viger ikke for fare!", c="Hilsner, <Name>, og velkommen. Er du her for at studere ved Stormenes Alter, ligesom jeg er, måske for at udnytte dets energi til et skjult formål...\n\nEller... er du her for at tale med mig? Ja, jeg tror, du er.\n\nVil du tæmme en Frygtros? Det er ingen let opgave. Det vil koste dig ikke så lidt blod, sved... og selvfølgelig guld. Men en Frygtros fra Xorot er en præmie, der er vel værd at vinde, så hvis du er interesseret, så lyt med..."},
  [7563] = {n="Blodets Vrede", l="Bring 30 flasker Rasende Udyrs Blod til Mor'zul Blodbringer i Brændende Stepper.", d="Frygtrosserne bor på en anden verden, på de brændende Sletter i Xorot, og for at binde et af de berømte udyr må du påkalde kraftfulde glyffer. Jeg kan skrive glyfferne på et pergament til dig, men først har jeg brug for et særligt blæk.\n\nI det fjerne Vinterkilde bor et slags ugle-udyr. Engang rene væsener, blev de gjort gale af de dæmoniske udstrålinger fra Mørkehviskerkløften, og nu strejfer de rundt i sneen i raseri.\n\nDeres blod er, hvad jeg behøver til at blække dit pergament. Bring det til mig.", p="Har du set de rasende ugle-udyr, <Name>? Magien hos disse væsener er stærk, og den koncentrerer sig i det blod, der flyder gennem deres torturerede skikkelser.", c="Ah, meget godt. Jeg vil lade dette blod destillere til et blæk og bruge det til det pergament, jeg lovede dig. Og måske gemmer jeg lidt til mig selv, for jeg har hørt, at dens smag er ganske euforisk..."},
  [7564] = {n="Vildøjne", l="Bring Etuiet med Blod til Gorsdeki Vildøjne i Brændende Stepper.", d="Min tjener, Gorsdeki, er en alkymist med en vis dygtighed. Han kan tilberede det blæk, jeg skal bruge til dit pergament. Jeg samlede det blod, du fik fat i; tag det til Gorsdeki, så han kan begynde sit arbejde.", p="Har du noget til mig? Det er ikke en stor, saftig edderkop, vel? Eller måske en kakerlak? Jeg håber, den stadig er i live... Jeg elsker så meget at tygge på dem, mens de stadig er i live...", c="Åh, det er blod. Det må være fra mester Mor'zul så. Han er så betaget af det og elsker at se det blive spildt. Jeg foretrækker dog, at det flyder gennem en lille gnavers årer. Så holder det sig varmt... indtil du har brug for det.\n\nDette er kraftfuldt blod. Mor'zul må være ved at lave endnu et pergament for at fremkalde en Frygtros! Hvor spændende!\n\nHvis det er tilfældet, og du skal udføre ritualet, så... får du brug for langt mere end blod, min ven."},
  [7581] = {n="Fængslets Bindinger", l="Rejs til Rædselshammeren i Vildalas og genvind 15 Satyrblod fra de vildfødte satyrer, der holder til i Krumtræ-kvarteret. Vend tilbage til Daio i Det Besmittede Arr, når dette er gjort.", d="Du må hente bindinger til Domvagtens fængsel fra mindre dæmoner.\n\nBlodet fra de vildfødte satyrer, der holder til i Rædselshammeren, bør gøre det fint. Det størknede blod vil binde Hederin-fragmenterne og drive krystalfængslet.", p="Kun blodet fra vildfødte satyrer vil gøre det.", c="Ah, en særdeles fremragende genvinding. Blodet vil undertrykke Domvagtens magiske forsvar."},
  [7582] = {n="Fængslets Hylster", l="Rejs til Mørkehviskerkløften i Vinterkilde og genvind 5 Hederins Tårer fra Hederin-dæmonerne, der besætter kløften. Vend tilbage til Daio i Det Besmittede Arr, når du har fuldført denne opgave.", d="Hederin-dæmonerne, der besætter foden af Hyjal-bjerget, udskiller kraftige dæmoniske gifte, som hvis de får lov at modnes, hærder til en tæt antimagisk krystal. Disse krystaller er kommet til at blive kendt som Hederins Tårer.\n\nSelv den enorme magt hos en Domvagt kunne ikke bryde murene i et fængsel bygget af dette materiale.\n\nRejs til Mørkehviskerkløften i Vinterkilde og hent tårerne.", p="Hederinerne vil ikke give deres dyrebare ædelsten fra sig uden kamp, <Name>.", c="Jeg skal blot kombinere de vildfødtes blod med disse krystaller, så er fængslet klar til brug."},
  [7583] = {n="Undertrykkelse", l="Begiv dig ud i Det Besmittede Arr og find en Domvagtkommandant.\n\nBrug det Lysende Krystalfængsel på Domvagtkommandanten. Vær forberedt på et voldsomt anstormning af angreb, da dæmonen forsøger at undslippe fangenskab.\n\nLykkes det dig, returner den Fængslede Domvagt til Daio i Det Besmittede Arr.", d="Fængslet er klart. Nu til den sværeste del af denne opgave.\n\nDu må finde og fange en Domvagtkommandant i Det Besmittede Arr ved hjælp af dette krystalfængsel.\n\nVær advaret! En Domvagt er en snedig og dødbringende modstander, og den vil søge at udslette dig, når du begynder fængslingsritualet. Den vil slå vildt omkring sig i forsøget på at undslippe fængslet.\n\nDen vil kun fokusere på dig, <Name>. Derfor må jeg anbefale dig at tage følgesvende med, der kan holde dig i live!", p="Hrm? Nå?", c="Du har gjort, som jeg bad om. Du er klar til at få kundskaben til at fremkalde og kontrollere udyret."},
  [7601] = {n="Hvad Nibby Befaler", l="Tal med Dæmonsen i Ondskoven.", d="Hvis jeg skal lære dig hemmelighederne bag at fremkalde et helvedesvæsen, må du udslette Krosjius og bringe mig helvedes-kernen fra hans brændende rester. Dette er dog ikke så let, som det lyder. Krosjius er næsten helt udbrændt. Du må genoplive hans lig og rejse ham fra murbrokkerne. For at gøre dette må du dog samle nogle komponenter fra andre dæmoniske væsener.\n\nMin drilling, Dæmonsen, skal sætte dig på vej.", c="Åh, må jeg sige. Her går vi igen."},
  [7602] = {n="Fejlfri Ond Essens", l="Impsy i Ondskoven har bedt dig om at bringe ham tre Fejlfri Onde Essenser fra tre forskellige steder.\n\nLegashi-satyrerne i Azsyra har den Fejlfri Onde Essens i deres region. Jaedenar-legionærerne i Jaedenar har den Fejlfri Onde Essens i deres region. Helvagt-vagterne i Det Sønderrevne Land har den Fejlfri Onde Essens i deres region.\n\nHent de Fejlfri Onde Essenser og returner til Dæmonsen i Ondskoven.", d="Hvis du vil genoplive Krosjius, skal du bruge Ond ild. Jeg kan lave Ond ild, men det kræver nogle komponenter.\n\nDu skal bringe mig fejlfri Onde Essenser fra tre forskellige egne af verden.\n\nLegashi-satyrerne i Azsyra vil have den første essenstype; Jaedenar-legionærerne i Jaedenar den anden type og Helvagt-vagterne i Det Sønderrevne Land den tredje.\n\nBring mig tilbage en af hver essenstype, så laver jeg Ond ild, så du kan genoplive Krosjius.", p="Fortæl ikke nogen det her, men Nibby er tosset.", c="Giv mig et øjeblik, så kombinerer jeg essenserne til Ond ild."},
  [7603] = {n="Krosjius' Helvedes Kerne", l="Søg i Splinterarrets Dal i Ondskoven efter resterne af Krosjius. Når du finder resterne, brug Ond ild nær dem og afvent Krosjius' tilbagekomst. Når helvedesvæsenet er vågnet, dræb det og tag Krosjius' Helvedes Kerne fra hans lig.\n\nReturner Krosjius' Helvedes Kerne til Nibby den Almægtige i Ondskoven.", d="Krosjius ligger i en bunke mod nordøst, i Splinterarrets Dal. Tag denne Ond ild og brug den på hans rester. Ilden burde genoplive det faldne helvedesvæsen.\n\nPå dette tidspunkt forventer jeg fuldt ud, at han dræber dig og alle de venner, du måske har taget med - og stol på mig, du vil gerne tage nogle venner med.\n\nHvis du ved et mirakel skulle dræbe Krosjius, så tag hans helvedes kerne og returner den til Nibby.", p="Gik du vild?", c="En aftale er en aftale! Skynd dig, tag det her og skriv det ned. Jeg har ikke tid! Min største fremkaldelse er ved at finde sted!"},
  [7604] = {n="En Bindende Kontrakt", l="Aflever Thorium-Broderskabets Kontrakt til Lokhtøs Mørkhandler, hvis du gerne vil modtage planerne for Svovlron.", d="Den undertegnede erklærer hermed, at Svovlron-barren, de leverer til Thorium-Broderskabet (TB ApS), er ægte og ikke en efterligning heraf. Den undertegnede anerkender ligeledes, at enhver skade, der måtte ramme ham som følge af forsøg på at bygge, smede, finde, skabe, sælge eller spise Svovlras, ikke er TB ApS' ansvar eller skyld.\n\nVed at underskrive denne kontrakt accepterer du alle vilkår, der er anført heri.\n\n_________________\n\nUnderskrift", p="Har vi en aftale?", c="Det har været en fornøjelse at handle med dig, <Name>!\n\nPå vegne af TB ApS ønsker jeg dig held og lykke i din søgen efter Svovlras!"},
  [7621] = {n="En Advarsel", c="Præst, du er ved at gennemgå en streng række begivenheder, der vil sætte alle dine evner på prøve.\n\nJeg foreslår, at du lytter til den historie, jeg har at fortælle.\n\nVær advaret, du skal fuldføre denne opgave alene. Det anbefales, at dine allierede holder sig på afstand. Indblanding fra udefrakommende agenter vil medføre en yderst alvorlig straf.\n\nSkæbnen har ført dig hertil, og kun dig. Kæmp med ære. Tag Lyset i seletøj."},
  [7622] = {n="Balancen mellem Let og Skygge", l="Red 50 bønder, før 15 bliver slået ihjel. Tal med Æris Havenfire, hvis du gennemfører denne opgave.\n\nDu kan se Dødsstolpen for at se, hvor mange bønder der er blevet slået ihjel.", d="Du må gøre, hvad jeg ikke kunne: Red de bønder, der blev nedhugget under flugten fra Stratholm.\n\nDe vil gå mod lyset, og du skal sikre deres overlevelse. Falder for mange, vil vores forbandede eksistens fortsætte - og du vil have fejlet.\n\nHver evne, bøn og besværgelse, du har lært, vil blive sat på prøve. Må Lyset beskytte dig, <Name>.", c="Din seighed og mod er forbløffende, præst. Du har fortjent retten til at holde Nordrassils Splint. Kun én opgave står tilbage: Skyggens Øje skal genfindes. Gennemsøg verden."},
  [7623] = {n="Herre Banehulen", l="Køb Skyggeeliksirer hos Gorsdeki i Brændende Stepper.\n\nBrug eliksirerne til at rejse gennem Jaedenar og tal med Herre Banehulen.", d="Mor'zøl siger, at du vil åbne en portal til Xorot. For at gøre det skal du bruge xorotisk stjernestøv. Det er ikke let at finde på Azerot!\n\nDer er ét væsen, der måske har noget: Herre Banehulen i Jaedenar, Skyggerådets sæde! Tal med ham, så giver han måske stjernestøvet fra sig.\n\nMen hvis du skal til Jaedenar, må du hylle dig i Skyggerådets egen slags ondskab. Det kræver nogle af mine skyggeeliksirer, og det vil koste dig...", c="Mit tålmod spænder over årtusinder, <Class>. Men tro ikke, at det giver dig mere end et øjeblik af min tid..."},
  [7624] = {n="Ulathæk Forræderen", l="Konfronter Ulathæk, og bring derefter Forræderens Hjerte til Herre Banehulen i Jaedenar.", d="Du ønsker at vinde min gunst? Så dræb for mig.\n\nMin tjener Ulathæk er patetisk, sådan som han krybet for mig, mens han hele tiden lægger planer med Hel'nurat på Xorot. Hel'nurat planlægger at tilrane sig min magt her, og Ulathæk er hans spion...\n\nBevis, at du tjener mig og ikke mine rivaler. Konfronter Ulathæk i hans kvarterer i Skyggeborgen mod vest. Fortæl ham, at jeg kender hans hemmelighed, og se frygten gribe ham. Bring mig så forræderens hjerte!", p="Jeg kan allerede smage Ulathæks hjerte på mine læber. Så sød er en forræders kød...", c="Åh, hvor herligt! Efter at have rådnet en uge, vil dette hjerte blive en saftig godbid! Måske sender jeg efter Ulathæks hoved og stiller det foran mig, mens jeg spiser...\n\nDu har gjort mig en tjeneste, <Class>, og derfor er mit tålmod med dig vokset. Marginalt."},
  [7625] = {n="Xorotisk Stjernestøv", l="Køb Xorotisk Stjernestøv af Ur'dæn. Bring det til Gorsdeki Vildøjne i Brændende Stepper.", d="Så du kommer til mig for at søge xorotisk stjernestøv? Du vil åbne en portal til Xorot, domænet tilhørende Hel'nurat, min rival? Måske planlægger du at stjæle en af hans dyrebare rædselsroser?\n\nVel. Min tjener Ur'dæn har et lager af xorotisk stjernestøv. Du kan få det af ham... hvis du kan betale prisen.", p="Har du været i Jaedenar, <Name>? Fik du stjernestøvet af Herre Banehulen?", c="Der er det! Jeg kan næsten ikke tro, du fik det! Du må have indgået en stor handel med den Rædselsherre, eller også har du betalt en stor sum, eller begge dele!\n\nMor'zøl får snart sit blæk, og så kan han endelig lave glyfpergamentet, så du kan åbne en portal til Xorot og trække en af de berømte Rædselsroser igennem den!"},
  [7626] = {n="Dødmoora-klokken", l="Bring 10 Eliksirer af Skyggekraft til Gorsdeki Vildøjne i Brændende Stepper.", d="En Dødmoora-klokke, opkaldt efter den afdøde hekser Dødmoora Mørkøje, er et af de tre redskaber, der kræves for at skabe en Større Fremkaldelseskreds. Når den er rigtigt afstemt med Hjulet og Lyset, leder disse genstande enorme mængder arkan kraft.\n\nMin tjener Gorsdeki kan konstruere sådan en klokke, men for at gøre det har han brug for en stor mængde eliksirer af skyggekraft. Skaf eliksirerne fra en alkymist og bring dem til Gorsdeki.", p="Har du de eliksirer, <Name>? Mor'zøl fortalte mig, at du har brug for en Dødmoora-klokke, og at det tager en masse skyggekraft at lave en af dem!", c="Meget godt! Jeg håber, at disse eliksirer ikke var for svære at skaffe. Nogle gange kan alkymister være så gnavne med deres kreationer...\n\nJeg laver klokken og gemmer den, indtil du er klar til dit ritual."},
  [7627] = {n="Hjulet fra Den Sorte Marsch", l="Bring 6 Store Strålende Skår og 25 Mørkejernsmalm til Gorsdeki i Brændende Stepper.", d="Et Hjul fra Den Sorte Marsch indeholder og styrer de voldsomme energier, der kræves for Den Større Fremkaldelseskreds. For at Gorsdeki kan lave et hjul, har han brug for både store strålende skår fra en fortryller og mørkejernsmalm fra en minemester.\n\nSkaf disse og bring dem til min tjener.", p="Hjulet fra Den Sorte Marsch er ikke let at lave, og det kræver en masse materialer. Har du samlet dem endnu?", c="Der er de! Jeg hører, at mørkejernsmalm kun findes i dybet af Sortklippe, og jeg er sikker på, at disse skår heller ikke var lette at finde. Jeg er ofte forbløffet over den hengivenhed, I warlocks har. Hvis du i stedet havde brugt al den energi på billefangst, åh... for et gilde du ville nyde!\n\nUndskyld, en lille sidebemærkning. Jeg laver hjulet og gemmer det til dig, indtil du er klar til dit ritual."},
  [7628] = {n="Dommedagslys", l="Bring 35 Sorte Drageskæl til Gorsdeki Vildøjne i Brændende Stepper.", d="Et Dommedagslys gemmer ild og retter den mod dem, der vil forstyrre dit ritual. Når du skaber din Større Fremkaldelseskreds, vil eventuelle afvigende dæmoner blive brændt af dets flammer, hvis dit lys er tændt!\n\nAt indespærre den ild er ikke let, og det kræver essensen i en sort drages skæl. Skaf disse skæl fra en skinner og bring dem til Gorsdeki Vildøjne.", p="Har du bragt drageskællene, <Name>? Jeg vil ikke begynde på lyset, før jeg har dem... ellers kan jeg komme til at sprænge hele lejren i luften!", c="Ah, meget godt. Jeg skal bruge dem til at indespærre lysets ild. Nu hvor jeg har skællene, laver jeg lyset og holder det, indtil du er klar til at begynde dit ritual for Den Større Fremkaldelseskreds."},
  [7629] = {n="Dæmonlingens Levering", l="Bring Dæmonlingen i en Krukke til alkymilaboratoriet i Skolomance. Når pergamentet er skabt, skal du returnere krukken til Gorsdeki Vildøjne.", d="Der er endnu en proces, der kræves for Mor'zøls pergament; jeg har brug for papir gennemsyret af xorotisk stjernestøv. Og... jeg er bange for, at jeg ikke kan gøre det her. Jeg har ikke udstyret!\n\nDer er dog et alkymilaboratorium med alt, der kræves. Det ligger i Skolomance, på øen Kær Darrow i Pestlandene.\n\nJeg kan ikke tage turen, men her - tag denne krukke. Der er en dæmonling indeni, der er ganske snu. Lad ham ud i alkymilaboratoriet, så imprægnerer han pergamentet.", p="Har du været i Skolomance, <Name>? Har dæmonlingen allerede gennemsyret pergamentet med stjernestøvet?", c="Ah, godt. J'iivi har skabt pergamentet. Hvordan var Skolomance? Charmerende, synes du ikke? Og billerne dér... jeg hører, de er lækre!\n\nVel gjort, <Name>, og tak for at returnere min krukke. Jeg har haft den i lang tid... og den er ikke til salg!"},
  [7630] = {n="Arkanit", l="Bring 3 Arkanitstænger til Gorsdeki i Brændende Stepper.", d="Nu hvor Klokken, Hjulet og Lyset er lavet, bør jeg lave en sort magnetsten. Under dit ritual får du brug for den magnetsten for at holde de andre ritualgenstande i gang, hvis de skulle svigte.\n\nFor at lave magnetstenen kræver jeg arkanit. Har du noget? Hvis ikke, så... må du hente arkanit hos en alkymist.\n\nVend tilbage til mig, når du har arkanitten, så laver jeg den sorte magnetsten.", p="Har du arkanitten, <Name>? Når jeg har den, kan jeg lave dig den sorte magnetsten.", c="Du fik den! Godt gjort! Nu kan jeg lave magnetstenen. Når du endelig er klar til dit ritual for at skabe Den Større Fremkaldelseskreds, vil du have brug for en magnetsten, så ritualet ikke fizzer ud!"},
  [7631] = {n="Rædselsros fra Xorot", l="Læs Mor'zøls Vejledning. Fremkald en Xorotisk Rædselsros, besejr den, og bind derefter dens ånd til dig.", d="Alle forberedelser er gjort. Nu skal du udføre ritualet for at skabe en Større Fremkaldelseskreds og derefter bruge pergamentet imprægneret med xorotisk stjernestøv... til at åbne en portal til Xorot.\n\nJeg har skrevet vejledningen til ritualet på en rulle. Studér den nøje, for du skal udføre hvert trin præcis, hvis du vil lykkes.\n\nHeld til dig, <Name>. Og må dine fjenders sjæle hurtigt finde vej ind i din skårpung.", c="Xorotisk Rædselsros' ånd er besejret. Selvom raseri pulserer gennem dens spøgelsesagtige flanker, ved du, at dyrets sjæl er din...\n\nDen hvisker mørk magi ind i dit sind og indpoder dig viden om at fremkalde en Rædselsros."},
  [7632] = {n="Oldtidens Blad", l="Find ejeren af det Forstenede Oldtidsblad. Held og lykke, <Name>; det er en stor verden.", d="Bladets overhud lyser klart grønt. Overfladen er ekstremt rynket og blotlægger flere årer og rynker.\n\nHvis du skulle gætte, ville du sige, at dette blad stammer fra noget gammelt og mægtigt.\n\nMåske skulle du finde bladets oprindelige ejer?", p="<Vartrøs stønner.>", c="Selvfølgelig genkender jeg mine egne blade. Se lige der! Det er i perfekt stand.\n\nHvor er det godt af dig at returnere det, <Class>.\n\nMåske kunne du gøre tjeneste for os, og vi for dig."},
  [7633] = {n="En Introduktion", c="Din flid og integritet er blevet bemærket, <Class>.\n\nVi er Oldtidsfolket: Beskyttere af denne engang så store skov. Vores fysiske former blev ødelagt for 10.000 år siden, da Archimonde og den Brændende Legion marcherede mod Hyjal-området. Vores ånder er dog intakte.\n\nDer er opgaver, vi kan tilbyde. Opgaver, der, hvis de gennemføres, vil åbne Oldtidsfolkets hemmeligheder for dig.\n\nVid dette: Hvis du gennemfører disse opgaver, skal du blot vende tilbage til denne sten, så vil vi svare på kaldet."},
  [7634] = {n="Oldtidens Senesvøbte Lamel", l="Haståt Oldtidsfolket har bedt dig bringe ham en Modent Blå Dragesene. Hvis du finder denne sene, skal du returnere den til Haståt i Ondskoven.", d="Hilsen, <Class>. Jeg er Haståt, Oldtidsfolk af Viden. Jeg besidder viden, der gik tabt for æoner siden.\n\nMed den rette bindning kan et af mine blade tjene som et kogger af en slags, der ikke er set i 10.000 år. Et kogger, som, når det ledsages af Oldtidsfolkets bue, kunne give uanede kræfter.\n\nKom tilbage hertil med sene fra en voksen blå drage, så skal dette kogger være dit.", p="Velkommen tilbage, unge <Class>.", c="Må mine blade beskytte dine pile mod skade. Må dine pile ramme sandt. Må verdens fjender blive slået ned."},
  [7635] = {n="En Ordentlig Buesnor", l="Stoma Oldtidsfolket har bedt dig bringe ham en Modent Sort Dragesene. Hvis du finder denne sene, skal du returnere den til Stomma i Ondskoven.", d="Vartrøs kan tilbyde dig stokken til at lave en Oldtidsfolkets bue, men kun jeg kan fortrylle snoren, der kræves for at fuldende buen.\n\nDet er en simpel opgave, din lille stakkel. Slå en modnet sort drage ihjel og fjern dens sene fra dens knogler. Bring den sene tilbage til mig, så fortryller jeg materialet til en næsten uforgængelig buesnor.", p="Jeg er sikker på, at du ikke vil have svært ved at finde og dræbe en sort drage, <Name>. Spild ikke min tid med tomt snak.", c="Det var en yderst ond drage. Senen stinker af ondskab.\n\nGiv mig et øjeblik til at rense urenheden fra dette kød og påføre de rette fortryllelser."},
  [7636] = {n="Oldtidens Stav", l="Du skal finde og ødelægge disse fire dæmoniske fordærvere:\n\nSimone Forføreren.\n\nKlinfran den Vanvittige.\n\nSolenor Dræberen.\n\nArtorus Dommebringeren.\n\nØdelæg disse væsener og vend tilbage til Vartrøs Oldtidsfolket i Ondskoven med deres hoveder.\n\nSe på det Forstenede Bark i din beholdning for at få ledetråde til, hvor de befinder sig.\n\nDu SKAL fuldføre denne opgave alene.", d="Agenter fra den Brændende Legion er stadig aktive i vores verden, <Class>. Disse agenter fordærver alt, hvad de rører ved. Naturen visner og græder i deres nærvær.\n\nDu skal opspore disse dæmoniske fordærvere og ødelægge dem, <Name>. Vær advaret: du skal konfrontere dem alene, ellers flygter de. Så længe du er alene, vil de forsøge at ødelægge dig. Du skal slå til mod dem og gøre deres arrogance til elendighed.\n\nJeg giver dig et stykke af min bark; inskriptionerne vil lede dig til dine mål. Hent deres hoveder.", p="Lad dig ikke narre af deres forklædninger!", c="Du har tjent os godt, <Name>! Tag denne stav og kombiner den med buesnoren, som Stomma kan lave. Sammen danner de et yderst formidabelt våben."},
  [7637] = {n="Vægt på Offer", l="Rejs til Jernsmede og hent Ypperstepræst Rohens Eksorcismerøgelseskar. Du skal donere 150 guld for at sikre det.", d="For at forberede dig til denne opgave må du først vise rette offer og dom... med vægt på offer.\n\nDu skal skaffe Ypperstepræst Rohens eksorcismerøgelseskar til din opgave. Selvom det vil blive brugt til gode og retfærdige formål, skal der gives rimelig kompensation for det.\n\nTag til Jernsmede og tal med ypperstepræsten. Ved at medbringe rigelige mønter for at afhjælpe tabet af hans røgelseskar vil du vise dit rette offer.\n\nGå nu, <Name>, tiden er knap.", p="Hilsen, ædle paladin! Jeg har forberedt mit betroede røgelseskar med de friskeste rygelser og velsignet det tre gange til din brug. Din donation vil hjælpe os i Jernsmede, ikke blot med at skabe et nyt røgelseskar, men også med at styrke de sultne lagre af mad til vores trængende.", c="Velsignelser over dig, ven <Class>! Din donation rækker langt ud over det, der var nødvendigt. Dit offer vil ikke blot hjælpe os med at genvinde det, vi har mistet, men også hjælpe os med at hjælpe dem, der har mest brug for det her i Jernsmede.\n\nNu skal jeg sørge for, at jeg har gjort dette røgelseskar klar til dine fremtidige behov..."},
  [7638] = {n="Lord Gråsen Skyggebryder", l="Tal med Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter.", d="Tiden er kommet, <Name>, for at du skal lære, hvad det kræver at skaffe dig noget, du uden tvivl har ventet på i længere tid... din krigshest.\n\nTal med Lord Gråsen Skyggebryder her i Stormvinds Katedralkvarter. Det er ham, der vil vejlede dig, ikke blot gennem en paladins mest betroede ridedyrs fingerfærdighed, men også gennem de opgaver, der venter, for at skaffe dig din egen.\n\nJeg ønsker dig det bedste i denne prøvelse. For Lyset, ædle bror!", c="Jeg er glad for at se dig, <Name>. Jeg ved, at du har ventet på besked om, hvordan du skaffer din krigshest, og nu er tiden kommet.\n\nDu vil helt sikkert blive sat på prøve på mange forskellige måder, men mest af alt i din vilje til at rejse dig over talrige forhindringer, der stilles op foran dig. Disse er ikke gjort som en læringsøvelse - din statur er hævet over simple uddannelsestests. Du skal redde din fremtidige ledsager fra det onde, du har brugt hele dit liv på at bekæmpe.\n\nTag ved lære, din tid er kommet!"},
  [7639] = {n="At Vise Rette Dom", l="Returnér Eksorcismerøgelseskarret til Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter.", d="Med mine velsignelser, tag skarret. Jeg har selv brugt det i flere eksorcismer, og det bør tjene dig godt til de strabadser, der venter.\n\nVend nu tilbage til Lord Gråsen Skyggebryder i Stormvind, <Name>. Din quest fortsætter hos ham.", p="Velkommen tilbage, <Name>. Har du skaffet eksorcismeskarret?", c="Ja, dette vil gøre det. Du vil blive kaldt mere end én gang under denne proces for at udføre ofringshandlinger; jeg er glad for at se, at du er villig til netop det. Ofring er en nøglekomponent i, hvad der kræves for at opretholde pligterne som paladin... men jeg behøver ikke belære dig om det.\n\nNu <Name>, skal du vise rette dom i dine handlinger. Til dette formål vil dette skar fungere som dit kar til at udøve sådan dom over pinte ånder fra lande, vi har mistet."},
  [7640] = {n="Eksorcisme i Rædseldalen", l="Brug Eksorcismerøgelseskarret til at drive de ånder ud, der plager Rædseldalen. Når du har slået 25 Rædseldalsånder ihjel, skal du vende tilbage til Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter.", d="Jeg har tilføjet en knivspids jord fra den forurenede jord i Rædseldalen i de Østlige Pestlande til skarret. Du vil nu bruge dette skar til at finde områder dér, der viser tegn på åndelig uro og forstyrrelse. Led efter grønne auraer, der gennemtrænger jorden, når den fysiske verden bøjer sig under åndeverdenens pinsel, og brug skarret til at drive de onde ånder ud.\n\nNår du har udøvet tilstrækkelig dom over ånderne dér, vil du være klar til at fortsætte.", p="Det er godt at se dig igen, <Name>. Er dit arbejde udført i Rædseldalen?", c="Godt gået, <Name>. At udøve Lysets dom over dem, der bor i mørket, er en opgave, vi må gribe an med kraft og nidkærhed; det har du netop gjort med dit offer i Jernsmede og dine domme over ånderne i Rædseldalen.\n\nDine næste skridt vil igen kalde på både offer og dom, når du nu stræber efter at genvinde en faldet krigshests ånd, som nu tjener en Dødsridder ved navn Mørkehøster."},
  [7641] = {n="Grimand Elmøres Arbejde", l="Tal med Grimand Elmøre i Stormvinds Dværgekvarter.", d="En paladins krigshest er intet andet end et pakdyr uden ordentlig hesterustning. Hesterustningen, som din krigshest bruger, skal ikke blot være af de fineste materialer, der findes, men på grund af omstændighederne skal den også være tilstrækkeligt afstemt med åndeverdenen.\n\nFørst og fremmest, <Name> - lad os få lavet din hesterustning. I Stormvinds Dværgekvarter bor en af de bedste håndværkere i dag, Grimand Elmøre. Hans arbejde bliver ikke billigt, men det er kvaliteten, vi søger. Tal med ham.", c="Hej der - Lord Skyggebryder sendte mig besked i forvejen om, at du ville komme forbi for at se mig. Jeg er villig til at lave den hesterustning, du har brug for, men den bliver hverken billig eller let; lad os få det på bordet først og fremmest.\n\nJeg siger dette ene, og Gråsen vil bakke mig op, når jeg påstår det... du finder ikke bedre hesterustning lavet nogen steder i hele Azerot end lige her."},
  [7642] = {n="Samling af Varer", l="Bring 40 Runestof, 6 Arkanitstænger, 10 Arthas' Tårer, 5 Stratholm-hellige vandflasker og 150 guld til Grimand Elmøre i Stormvinds Dværgekvarter.", d="Du skal bruge fire ting til hesterustningen - runestof til foringen, arkanitstænger til pladerne, Arthas' Tårer til den åndelige afstemning og Stratholm-hellige vand til den åndelige indgydelse. Faktisk skal du bruge fem ting... guld til mit honorar. Det honorar dækker alt arbejde samt en håndlavet sadel og stigbøjler.\n\nNår du har alt det, kan jeg færdiggøre din hesterustning. Indtil da er der nogle ting, jeg kan gå i gang med for dig, mens du samler din samling af varer.", p="Ah, <Class>. Jeg kan ikke færdiggøre din hesterustning uden de ting, jeg nævnte. Har du fået alt samlet?", c="Dette... ja, præcis dette var, hvad jeg havde brug for. Du er en ret snarrådig <Class>, ikke?\n\nSå lad os få hesterustningen færdig til dig!"},
  [7643] = {n="Oldtidens Ækvine Ånd", l="Skaf særligt hestefoder, der bruges til at fodre en åndehest. Meridet Carlson i Sydkyst er åbenbart kilden til sådan mad.\n\nRejs til fangehullet Rædselshammeren i Vildalas og slå Tendris Krogtræ ihjel. Det vil befri den Oldtidens Ækvine Ånd. Fodr den med det særlige hestefoder, og berolig dermed ånden. Til sidst skal du give den Arkanitrustningen, så den kan velsigne den.", d="Din hesterustning har brug for en særlig form for velsignelse, en fra en passende ånd. I Rædselshammeren findes en sådan ånd, den Oldtidens Ækvine Ånd. Den holdes i øjeblikket fanget af en korrupt træfolk, Tendris Krogtræ. Døm dette hæslige udyr, <Name>.\n\nVid dette - frihed alene er ikke nok. Du skal berolige ånden, før du kan modtage dens velsignelse. Til det er særligt hestefoder nødvendigt. Rejs først til Sydkyst og tal med Meridet Carlson om dette... og gør dig klar til mere ofring.", p="Den Oldtidens Ækvine Ånd ser forventningsfuldt på dig, som om den vil have noget fra dig.", c="Den Oldtidens Ækvine Ånd accepterer tilbuddet om det Mannaberigede Hestefoder, nusser til beholderen, mens den hjælper sig selv til de særlige havrer og korn. Efter at have spist lidt, ser den på hesterustningen, du har, og stiller sig op, som om den vil have dig til at placere den på sin ryg..."},
  [7644] = {n="Velsignet Arkanit-hesterustning", l="Vend tilbage med den Velsignede Arkanit-hesterustning til Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter.", d="Mens hesterustningen hviler på den Oldtidens Ækvine Ånds ryg, lyser den lige så svagt. Luften er tyk af kraft et øjeblik, og så forsvinder hesterustningen fra hestens ryg og er nu sikkert i din rygsæk.\n\nDet lader til, at hesterustningen er blevet velsignet. Efter Lord Skyggebryders instruktioner skal du nu vende tilbage med den til ham i Stormvind.", p="<Name>, du er tilbage! Lykkedes det dig at klare Meridet Carlson og Tendris Krogtræ? Ærligt talt, jeg ved ikke altid, hvem der er den største trussel...", c="Du er kommet langt, min ven. Din hesterustning er nu passende forberedt til den sidste opgave.\n\nDu vil bruge denne hesterustning til at tæmme din krigshest, når forløsningens opgave er fuldført. Men før det skal du overvinde en monumental kamp. Din tid nærmer sig - hurra!\n\nDer er ét sidste emne, der skal laves, før vi begynder dette, <Name>. Forhåbentlig har din snarrådighed ikke forladt dig, siden du fik lavet din hesterustning..."},
  [7645] = {n="Mannaberiget Hestefoder", l="Hent 20 Berigede Mannakiks - nøgleingrediensen i Mannaberiget Hestefoder - til Meridet Carlson i Sydkyst i Hillsbrad-forbjergene. Sølvdæmringen er kendt som den eneste forhandler af kiksene.\n\nDu skal også give hende 50 guld for at berolige hendes krøllede sensibiliteter.", d="Sølvhånden troede, jeg var GAL, da jeg fortalte dem, at jeg kunne lave et særligt hestefoder, der kunne nære åndelige heste. ALLE troede, jeg var gal! Nu er det så betalingens tid!\n\nJeg laver det, du har brug for, PALADIN... såkaldt MESTER... men det koster dig. Jeg har brug for særlige kiks - Berigede Mannakiks, kun solgt af Sølvdæmringen - til denne blanding. Jeg kræver også, ja KRÆVER, guld som kompensation for den elendighed, jeg har måttet udstå!\n\nVis mig det offer, du så højt prædiker, PALADIN.", p="Ja, nu har jeg bevist, at du tog fejl, har jeg ikke? Jeg har bevist dem alle forkerte! JEG HAVDE RET HELE TIDEN!!!", c="JA, NU HVEM - vent - giver du mig også guldet? Du var ikke den, der kaldte mig gal (de kaldte mig faktisk en kagemand og nar)... alligevel er du villig til at vise offer selv for uretfærdigheder, du ikke har begået?\n\nJeg... jeg tog fejl af dig, <Name>. Skulle du have brug for mere hestefoder, så kom og se mig. Jeg giver dig det gratis. Tak... ædle <Class>.\n\nJeg beholder dog pengene - jeg er ikke så meget af en nar, at jeg opgiver en formue."},
  [7646] = {n="Spådomsskueren", l="Bring en azerothisk diamant og en upåklagelig sort diamant til Lord Gråsen Skyggebryder i Katedralkvarteret i Stormvind.", d="Vi må nu samle en Spådomsskuer - dette vil begynde prøvelsen, der gør det muligt for dig at genløse den faldne krigshest. Din skuer er faktisk næsten færdig. Eksorcismerøgelseskarret, der bruges i Rædselsdalen, er katalysatoren for den, og jeg vil smede et passende hus til apparatet.\n\nDe sidste komponenter, der mangler, er dog to diamanter. De skal være lige så kontrastfyldt strålende i glans, som de er i formål - en azerothisk og en upåklagelig sort. Disse to vil være fyrtårnet, hvormed skueren vil gennemborer skyggerne!", p="Du er nået så langt, <Name>. Din sidste handling med at ofre jordiske genstande vil være startskuddet til en af dine største bedrifter. Jeg kan mærke det i hver fiber af min væren!", c="Det er fine eksemplarer, <Name> - de sidste brikker er nu på plads. Endelig er din tid kommet!\n\nI dybderne af Det Store Ossuarium i Skolomance ligger de skeletterne af mange væsener. Blandt dem er en engang adelig krigshest. Denne krigshests udhulede sjæl tjener nu som ridedyr for Dødsridder Mørkehøster. Det er ham, du skal møde, og det er dette ridedyr, du skal dømme. Kun du, <Name>, kan genløse dets sjæl og redde den fra pinslerne i dets trældom."},
  [7647] = {n="Dom og Forløsning", l="Brug Spådomsskueren i hjertet af Det Store Ossuariums kælder i Skolomance. Det vil fremkalde de ånder, du skal dømme. At besejre disse ånder vil fremkalde Dødsridder Mørkehøster. Besejr ham og genvind den tabte sjæl fra den faldne krigshest.\n\nGiv krigshestens genløste sjæl og den velsignede fortryllede hesterustning til Mørkehøsters faldne krigshest.", d="Tag denne taske - i den er de ting, du skal bruge til din opgave.\n\nBrug spådomsskueren i hjertet af Det Store Ossuariums kælder til at fremkalde forbandede ånder, der skal dømmes. Brug dine domme klogt under denne prøvelse - de vil vise sig at være mere kraftfulde, end du forstår. Efter åndene vil dødsridderen træde frem; besejr ham og genvind krigshestens tabte sjæl. Først da, <Name>, vil du kunne genløse den og placere din hesterustning på dit nye ridedyr!\n\nHeld og lykke!", p="Den faldne krigshests ånd betragter dig med et sørgmodigt blik. Triste, næsten tomme øjne ser på dig, som om alt håb var gået tabt for den.", c="Et glimt af liv - længe fraværende fra det stakkels væsen - skinner i dets øjne, når du rækker dets dømte sjæl tilbage til det. Du mærker en hellig kraftbølge strømme om dig, da du placerer hesterustningen på dets ryg, idet krigshesten er dømt genløst. Krigshesten nusser din hånd, mens fortidens byrder løftes fra dyret. Du føler nu, at du kunne kalde på dette væsen til at tjene som dit ridedyr, skulle behovet opstå.\n\nDu har gjort din episke krigshest til din, <Class>! Tillykke!"},
  [7648] = {n="Grimmunds Fineste Værk", l="Tag den Arkanit-hesterustning til Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter til hans inspektion.", d="<Grimmund tørrer sveden af panden, strålende af stolthed.>\n\nDer er du, min ven. Dette er noget af mit fineste arbejde - lige så godt som den hesterustning, jeg personligt lavede til Lord Skyggebryder, da han drog ud på sin egen krigshest. Jeg takker dig for din tillid til, at jeg leverer det bedste til dig.\n\nIngen tvivl om, at Gråsen også vil ønske at se værket med egne øjne. Tag din hesterustning til ham, og giv ham min tak for hans hæderlige forretning.", p="Du gør det fint, <Name>. Når du har lavet din hesterustning, er du godt på vej til den næste opgave.", c="Dette er særdeles imponerende arbejde. Det virker, som om Grimmunds håndværk bliver bedre, jo ældre han bliver. Det er en bedrift, når hans arbejde allerede dengang, han lavede min hesterustning, var noget af det fineste, man kunne finde overalt.\n\nMens denne hesterustning ville være en fin tilføjelse til ethvert almindeligt ridedyr, har vi ikke at gøre med sådan et jordnært væsen. Du skal have denne hesterustning velsignet af en passende kilde, før den er værdig til at hvile på en <Class>s krigshest. Jeg gemmer den til dig, indtil da."},
  [7649] = {n="Fortryllet Thoriumpladerustning: Bind I", l="Returner bogen til dens retmæssige ejere.", d="Tomen bærer Athenæums mærke.", p="Du har genfundet en bog!", c="Godt gået, min dreng.\n\n<Vidensvogter Lydrøs river en side ud af bogen.>\n\nJeg er sikker på, at du kan bruge denne opskrift."},
  [7650] = {n="Fortryllet Thoriumpladerustning: Bind II", l="Returner bogen til dens retmæssige ejere.", d="Tomen bærer Athenæums mærke.", p="Du har genfundet en bog!", c="Godt gået, min dreng.\n\n<Vidensvogter Lydrøs river en side ud af bogen.>\n\nJeg er sikker på, at du kan bruge denne opskrift."},
  [7651] = {n="Fortryllet Thoriumpladerustning: Bind III", l="Returner bogen til dens retmæssige ejere.", d="Tomen bærer Athenæums mærke.", p="Du har genfundet en bog!", c="Godt gået, min dreng.\n\n<Vidensvogter Lydrøs river en side ud af bogen.>\n\nJeg er sikker på, at du kan bruge denne opskrift."},
  [7652] = {n="Et Blåt Let Tilbud", c="Jaså, mister, jeg har en hed handel til dig.\n\nJeg vil gerne af med nogle af disse kejserlige pladerustnings-opskrifter, og jeg har brug for en, der vil tage byrden på sig. Alt, jeg vil have til gengæld, er nogle thoriumstænger. Lyder godt?"},
  [7653] = {n="Kejserligt Pladebælte", p="Til bælteplanerne skal jeg bruge 20 thoriumstænger.", c="En fornøjelse at gøre forretninger med ya.\n\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7654] = {n="Kejserlige Pladestøvler", p="Til støvleplanerne skal jeg bruge 40 thoriumstænger. Jep, 40. Skal du græde? Vil du have et lommetørklæde?\n\n<Derotan griner.>", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7655] = {n="Kejserlig Pladearmbeskytter", p="Til armbeskytterplanerne skal jeg bruge 20 thoriumstænger.\n\nEr du okay, sønnike? Du bliver helt rød i hovedet.", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7656] = {n="Kejserligt Pladebryst", p="Til brystpladeplanerne skal jeg bruge 60 thoriumstænger.\n\n\nÅh nej, der går du igen. Skal du løbe hen til dine blå Guder og spørge, hvorfor de har forladt dig?!? Tag dig sammen, Nanna! Ingen har nogensinde sagt, at livet er retfærdigt.", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7657] = {n="Kejserlig Pladehjelm", p="Bare aflever 50 thoriumstænger, så er hjelmplanerne dine.", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7658] = {n="Kejserlige Pladebenbeskyttere", p="Bare aflever 60 thoriumstænger, så er benplanerne dine.\n\nJeg ved godt, jeg driver dig til fallit! Jeg har hørt det hele før, så du kan spare mig for din sørgehistorie, svagling.", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7659] = {n="Kejserlige Pladeskulderbeskyttere", p="Til skulderplanerne skal jeg bruge 20 thoriumstænger.", c="En fornøjelse at gøre forretninger med ya.\n\nOg <Name>, tør det væmmede udtryk af dit fjæs."},
  [7667] = {n="Materialehjælp", l="Hvis du er interesseret i at hjælpe Sagorne Kammarsti i Orgrimgrads Visdommens Dal, så bring ham en azerothisk diamant og en upåklagelig sort diamant.", d="<Name>, der er en presserende sag, jeg håber, du kan hjælpe med... både materielt og åndeligt. Lad mig forklare.\n\nI dybderne af Skolomance i Herrelande ligger et kammer kaldet Det Store Ossuarium. Jeg skal færdiggøre et apparat, der kan gennemborer skyggerne i dette forfærdelige rum. For at fuldføre det, jeg har påbegyndt, har jeg brug for to diamanter: en azerothisk og en upåklagelig sort. Det er ikke trivielle ting, det ved jeg - jeg har bare ikke ressourcerne selv.\n\nKunne du skaffe mig en af hver?", p="Jeg føler mig underlig tilpas med at bede om materiel hjælp, men min spådomsskuer - apparatet, jeg håber at færdiggøre - kræver én af hver. Hvis du ikke kan hjælpe, vil jeg helt sikkert forstå det.", c="Din generøsitet er uovertruffen, <Name>. Jeg takker dig for din venlighed.\n\nJeg kan nu færdiggøre min spådomsskuer, og jeg burde kunne fremstille flere uden yderligere behov for diamanter... måske kunne du have lyst til at hjælpe mig med at bruge den? Den er til en yderst vigtig opgave, det forsikrer jeg dig... en opgave, der, hvis den ikke bliver kontrolleret, kunne varsle en ufattelig katastrofe for åndsriget!"},
  [7668] = {n="Mørkehøsterens Intimidering", l="Brug Spådomsskueren i hjertet af Det Store Ossuariums kælder i Skolomance. Det vil fremkalde ånder, du skal bekæmpe. Besejr disse ånder, og Dødsridder Mørkehøster vil blive fremkaldt; besejr ham.\n\nBring Mørkehøsters Hoved til Sagorne Kammarsti i Visdommens Dal, Orgrimgrad.", d="Dødsridder Mørkehøster hersker over Det Store Ossuarium i Skolomance. Han truer med at vride åndsriget til sin egen fordel, og han skal stoppes! Her er det, at skueren, du var med til at lave, kommer i spil.\n\nBrug spådomsskueren i hjertet af Det Store Ossuariums kælder til at kalde Mørkehøsters åndelige håndlangere frem. Besejr ånderne, så vil dødsridderen selv dukke op. <Name>, bring mig hans hoved! Kun hans undergang kan vende den skade, der er gjort på åndsriget!", p="Tiden er kritisk, <Name> - er det lykkedes dig at stoppe Dødsridder Mørkehøsters trussel?", c="Dette er en sejr at nyde, <Name>! Mørkehøsters undergang bør genoprette de skrøbelige lænker, der forankrer åndsriget.\n\nDu har langt overgået, hvad der blev bedt om, selv da du ikke havde den mindste tanke om belønning eller kompensation. Du er virkelig en <Class> af værdi, min ven.\n\nJeg ved, at det at handle for at bevare åndsriget burde være tak nok, men vær så venlig - accepter denne simple gave med min tak."},
  [7670] = {n="Lord Gråsen Skyggebryder", l="Tal med Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter.", d="Tiden er kommet, <Name>, for dig at lære, hvad der skal til, for at du kan skaffe dig noget, du uden tvivl har ventet på i nogen tid... din krigshest.\n\nTal med Lord Gråsen Skyggebryder i Stormvinds Katedralkvarter. Det er ham, der vil vejlede dig, ikke blot gennem den snedige fingerfærdighed bag en paladins mest betroede ridedyr, men også i opgaverne foran dig for at skaffe dig din egen.\n\nJeg ønsker dig held i denne prøvelse. For Lyset, ædle broder!", c="Jeg er glad for at se dig, <Name>. Jeg ved, at du har ventet på besked om, hvordan du skaffer din krigshest, og nu er tiden kommet.\n\nDu vil helt sikkert blive sat på prøve på mange forskellige måder, men allervigtigst i din vilje til at rejse dig over talrige forhindringer, der stilles foran dig. Disse er ikke øvelser i at lære - din statur er hævet over simple uddannelsesprøver. Du skal redde din fremtidige ledsager fra det onde, du har brugt hele dit liv på at bekæmpe.\n\nTag dig i agt, din tid er kommet!"},
  [7701] = {n="EFTERLYST: Tilsynsmand Maltorius", l="Dybt i Slaggruben i Gryden, i Svidningskløften, finder du det forræderiske Mørkejern-dværg ved navn Tilsynsmand Maltorius.\n\nDræb Tilsynsmand Maltorius og tag hans hoved. Bring hovedet til Udkigskaptajn Lolle Langstriber i Svidningskløften for din belønning.", d="Efter ordre fra 'hans eminens', Tilsynsmand Oljefist, den snigende Thoriumbroderskab-agent og nyudnævnte chef for Mørkejern-besætningen i Slaggruben i Gryden, Tilsynsmand Maltorius, skal dræbes, og hans hoved bringes tilbage som bevis på gerningen.\n\nSe Udkigskaptajn Lolle Langstriber for belønningen på denne efterlysning.", p="Kan'ke se, jeg er tjavset? Hva' *hik* er det, du vil ha'? *hik*", c="Jeg troede aldrig, jeg skulle se det grimme fjæs igen!\n\nHan ser faktisk bedre ud uden resten af kroppen hæftet på.\n\nHer er din belønning *hik*, <Race>."},
  [7703] = {n="Uafsluttet Gordøk-forretning", l="Find Gordøk-Magtens Handske og returner den til Kaptajn Krømknus i Rædselshammeren.\n\nIfølge Krømknus siger den \"gammeldags historie\", at Tortheldrin - en \"uhyggelig\" elf, der kaldte sig selv for en prins - stjal den fra en af Gordøk-kongerne.", d="Nu du bli'r konge, så måske kan du få den værdifulde Gordøk-genstand tilbage fra den uhyggelige elf, der kalder sig prins! Den forrige konge fejlede, ligesom alle de andre konger siden Tortheldrin - den uhyggelige elf - stjal den fra den gamle Gordøk-konge!\n\nGenstanden hedder Gordøk-Magtens Handske. Gamle historier siger, at kun den ene sande Gordøk-konge kan få den tilbage. Den gamle historie siger også, at den uhyggelige elf stadig er her - find ham, og den bliver til den mægtige handske, du bærer for evigt! Jo, jeg viser dig!", p="Ha, du finder den ikke, hva' boss? Måske er den gamle historie en dårlig historie... svært at tro, at den uhyggelige elf kan stjæle fra en Gordøk-konge!", c="Wow... du ER den sande konge! Jeg troede aldrig, jeg skulle se denne handske i mit liv! Den ser ud, som om den ikke har nogen magi tilbage... måske har den uhyggelige elf prøvet at ødelægge handsken. Nå, jeg siger HAR HAR til ham!\n\nSe - dette mærke på handsken er et gammelt, gammelt, GAMMELT magisk mærke, ældre end Gordøk, siger de. Nå, som kaptajn for Gordøk lærer vi én ting igen og igen - hvordan man får mærket til at blive levende og giver kraften tilbage til handsken!\n\nJeg gør det for dig, konge! Her, tag handsken og hersk EVIGT!"},
  [7704] = {n="Se på Størrelsen!", l="Tag Stuepige Pudeklemmers Hovedpude til Evonike Sodrøger i Svidningskløften.", d="Nå, nå, nå... Er det ikke en overraskelse. Stuepigen havde en gigantisk, pyntet hovedpude, og nu er den din. Evonike Sodrøger vil helt sikkert gerne have sine beskidte små hænder på denne genstand. Tag den med til hende og se, om hun vil give dig nogle godter for besværet."},
  [7721] = {n="Brændstof til Zappingen", l="Saml 10 Vandelementarkerner fra Havelementarer og Havsprøjt langs Glemte Kyst i Vildalas, og bring dem tilbage til Zorbjørn Fjolleri, der står nær kajen dér.", d="Hvis jeg satser mod min egen bedre dømmekraft og bliver for at drive en ingeniørbutik langs Glemte Kyst, må jeg tage mig af disse irriterende elementarer. Forbandelse over elementalismens ukontrollerede kræfter, siger jeg!\n\nHeldigvis for mig, og nu for dig, mit håbefulde agent provocateur, er elementarerne en ideel kilde til rå kraft til min Ultra-Krymper-raffinering - giv dem det, de fortjener, siger jeg! Men husk nu at spare mig for vandelementarkernerne, når du gør det!", p="Selvom jeg kunne kede dig med de tekniske detaljer bag kernernes nytte, vil jeg i stedet friste dig til at fuldføre denne vigtige opgave ved at tilbyde værdifulde penge og præmier. Sig mig, er du færdig?", c="Skrumdelligt! Disse kerner vil holde mig i gang i noget tid. Dertil kommer fordelen ved, at der nu er færre elementarer langs kysten, og jeg behøver måske ikke længere at græde mig i søvn over at have slået mig ned på måske det værst tænkelige sted!\n\nTak, <Name>, for din indsats på mine vegne. Selvom det vist nok lægger en økonomisk byrde på mig, så lad mig vise dig en taknemmelighed, du måske forstår og sætter pris på... plyndring!"},
  [7722] = {n="Hvad med Fluxen?", l="Et sted i Slaggruben i Gryden finder du de Hemmelige Tegninger: Ildende Fluks, som Tilsynsmand Maltorius stjal. Find tegningerne og returner dem til Mestersmed Brændinate i Svidningskløften.", d="Da den satans Maltorius forlod vores klan, tog han noget mere værdifuldt med sig end en upåklagelig arkan krystal: Vores opskrift på ildende fluks! Jeg ville vædde på, at opskriften var en del af handelen i hans nye forfremmelse blandt Mørkejernene.\n\nJeg vil have, at du henter vores hemmelige tegninger tilbage, <Name>. Jeg er sikker på, at de er et sted i nærheden af Maltorius, dybt inde i Slaggruben.", p="Fandt du tegningerne?", c="Jeg håber, du slog ham tænderne ud også, <Name>. Ragnarøs ved det, han fortjente det.\n\nNu kan vi komme til forretningerne."},
  [7723] = {n="Forbandede Fede Fingre", l="Hansse Tungehænder vil have, at du dræber 20 Tunge Krigsgolemer.\n\nDe Tunge Krigsgolemer vandrer rundt i områderne omkring Gryden i Svidningskløften. Når du har dræbt nok, skal du vende tilbage til Hansse i Svidningskløften.", d="Desværre kan jeg ikke uddele klø, som jeg plejede, på grund af dette her fede finger-problem. Ser du, klimaet herude sammen med det lave lufttryk får mine fingre til at svulme op. De er som gigantiske Thelsamarske blodpølser, de er...\n\nDu bliver nødt til at udføre mine forretningsordrer og sådan noget.\n\nFørst på min dagsorden: Tæv livet ud af de tunge krigsgolemer i Kløften. Skynd dig.", p="Fik du dem tævet?", c="Du er en god dreng, det er du. Jeg har en lille gave til dig for besværet."},
  [7724] = {n="Brændende Trussel!", l="Hansse Tungehænder vil have, at du dræber 20 Større Lavaspindere i Svidningskløften. Du kan finde Større Lavaspindere på plateauerne og i lavapytterne i Svidningskløften.\n\nVend tilbage til Hansse Tungehænder i Svidningskløften, når du har dræbt nok Større Lavaspindere.", d="Vidste du det ikke, hver gang gamle Hansse vil tage et øjeblik til at slappe af og reflektere over sit liv, giver magterne ham endnu et job.\n\nJeg må tænke, kom nu! Ved du, hvad jeg mener? Kom. Nu.\n\nSå disse større lavaspindere forårsager en slags ballade. Oljefist siger, at de skyder ild ud af deres... øh, ja, i hvert fald, sådan noget oprører børnene.\n\nJeg gætter på, vi må dræbe dem. Rettere sagt, du må dræbe dem.", p="Havde han ret? Kommer det ud af deres bagdele?", c="<Hansse nyser.>\n\nJeg tror, jeg er ved at få en forkølelse. Forbandet være dette iskolde klima!"},
  [7727] = {n="Ildosaurer? Hvadsomhelst-osaurer er mere det rigtige", l="Hansse Tungehænder vil have, at du dræber 20 Ildosaurer.\n\nDu vil finde Ildosaurer, der holder til i lavapytterne inde i Slaggruben. Slaggruben findes i Gryden i Svidningskløften.\n\nVend tilbage til Hansse Tungehænder i Svidningskløften, når du har dræbt nok Ildosaurer.", d="Ligtæer, dreng. Mine ligtæer har ligtæer. Hvordan skal jeg kunne udføre nogen form for dræbning med mine fødder i sådan en uorden? Det er derfor, du skal hjælpe.\n\nSkrange og Brændinate gav mig opgaven med at dræbe disse ting, så de kan sende nogle ekspeditionshold ned i lavapytterne i Slaggruben for at udforske. Angiveligt er der nogle ildosaurer eller sådan noget vrøvl dernede, der forårsager alle mulige problemer. Nu flytter du dig, og du kommer ikke tilbage, før ildosaur-bestanden er udryddet.", p="<Hansse gnider flittigt sine ligtæer.>\n\nStå ikke bare der, tag noget olie og en luffasvamp og gå i gang med at skrubbe disse ligtæer.\n\nDu har ingen luffasvamp? Nå, så! Måske er det på tide, jeg sender dig ud for at finde en luffasvamp?\n\nHov, hvor skal du hen?", c="Åh, mine smertende fødder.\n\nJeg regnede med, at siden du ikke havde en luffasvamp..."},
  [7728] = {n="STOLEN: Smedeblæser og Udkigsmandens Kikkert", l="Find og bring Smedeblæseren og Udkigsmandens Kikkert tilbage til Pisker Skrange i Svidningskløften.\n\nDe eneste oplysninger, du har om disse genstande, er følgende: De blev helt sikkert stjålet af Mørkejern-dværge. Smedeblæseren er et smedeværktøj, som smede bruger, og Udkigsmandens Kikkert er et uvurderligt overvågningsværktøj for udkigsmænd.", d="Følgende genstande er blevet stjålet:\n\n*En Mørkejern-smedeblæser.\n\n*En Udkigsmandens Kikkert.\n\nDer er sat en belønning ud til de personer, der finder og bringer disse tyvegods tilbage.\n\nThorium-Broderskabet er sikker på, at disse genstande blev stjålet af skrupelløse og misundelige Mørkejern-dværge, der holder til i Svidningskløften.\n\nKikkerten i spørgsmålet var et fremragende værktøj for udkigsmændene, og blæseren var et uerstatteligt smedeværktøj.\n\nFinder du de savnede genstande, så bring dem tilbage til Skrange.", p="Hvis du er her for belønningens skyld, bliver du nødt til at give mig de stjålne varer.", c="Fantastisk arbejde! Og nu din belønning."},
  [7729] = {n="JOBMULIGHED: Udrensning af konkurrencen", l="Slå 15 Mørkejern-pisker og 15 Mørkejern-slavehandlere ihjel. Vend tilbage til Pisker Skrange i Svidningskløften, når du har udført opgaven.", d="Pisker Skrange søger nogle få gode mænd og kvinder til at 'rydde konkurrencen' i Svidningskløften.\n\nHvis du er interesseret i stillingen, så drag ud i Svidningskløften og slagt hver eneste Mørkejern-pisker og Mørkejern-slavehandler, du ser.\n\nVend tilbage til Pisker Skrange, når dit tøj er blodigt nok.\n\nDu vil vide, hvornår de er blodige nok, så spørg ikke.", p="Vi bliver nødt til at veje dig med og uden tøj for at være sikre.", c="15,9 pund! Det kan være en ny rekord for blod- og tarmvægt på klæder! Tillykke, <Class>!"},
  [7730] = {n="Zukk'asj-invasionen", l="Bring 20 Zukk'asj-panser til Hadoken Hurtigskrider i Lejr Mojasje, Vildalas.", d="Ud fra den spejdning, vi har kunnet samle sammen, tror vi, at fjenden syd for hyænemændene er en insektlignende race. Det er ærlig talt irrelevant, om de er bevidste eller ikke. Hvis de driver hyænemændene til raseri mod os, er de lige så stor en trussel - om ikke større - end hyænemændene.\n\nTræng dybt ind, hvor disse Zukk'asj-insekter holder til; det er kendt som den Vridende Dybde. Tynd deres rækker ud, og rapportér tilbage til mig, hvad du finder, og bring deres panser med som bevis på dit værk.", p="Hvordan går jagten, <Name>? Er du her for at melde om din succes?", c="Godt gået, <Class>. Selvom Zukk'asj-tilstedeværelsens omfang ikke kan standses med mindre end en fuldskala-invasion, har du købt os noget tid, så vi kan udtænke en ordentlig strategi.\n\nJeg vil sørge for, at panserne bliver analyseret; vi bliver nødt til at lære alt om dem, før vi tager fat på det, der desværre er blevet et langt større problem, end vi havde forventet."},
  [7731] = {n="Stikpisker", l="Besejr Stikpisker i den Vridende Dybde, og bring dens kirtler tilbage til Hadoken Hurtigskrider i Lejr Mojasje, Vildalas.", d="Under kortlægningen af den Vridende Dybde så en af vores spejdere et gigantisk insekt - langt større end de andre insekter, vi har set - vandre rundt i det snoede terræn. Ikke alene er det større, det ser også ud til at udskille en slags glorie, som de andre insekter ikke gør. Vi har givet det et navn - Stikpisker.\n\nDette uhyres indvolde ville være uvurderlige at studere, mens vi finder ud af, hvordan vi bedst håndterer denne nye trussel. Skær dets udskillelseskirtler ud og bring dem til mig med det samme!", p="Er det lykkedes dig at fælde Stikpisker endnu?", c="Imponerende, <Class>... meget imponerende! Hvis Stikpisker virkelig er et af deres stærkeste væsener, vil studiet af uhyret vise sig at være ret værdifuldt på sigt. Det er nu min opgave at sørge for, at vi forsvarer os længe nok til at drage fordel af det.\n\nModtag venligst denne mønt-dusør som et tegn på hele lejrens taknemmelighed, <Name>. Godt gået."},
  [7732] = {n="Zukk'asj-rapporten", l="Lever Lejr Mojasjes Zukk'asj-rapport til Zilzibin Trommelære. Han holder til i Dragen i Orgrimmar.", d="Du har klaret dig dobbelt så godt med at tage fat på den trussel, som Zukk'asj-insekterne udgør for Lejr Mojasje. Truslen fra disse ting er langt fra forbi, og jeg vil gerne bede dig om en sidste opgave på Hordens vegne.\n\nDette er et dokument, der beskriver al den information, vi har indsamlet om disse Zukk'asj-insekter. Jeg vil have dig til at levere det til Zilzibin Trommelære i Dragen i Orgrimmar. Han er ekspert i fremmede væsener som disse; jeg håber, han kan gøre noget med den viden, vi har fået.", p="Hilsner, ven... du ser ud, som om du har et hastende ærinde. Er der noget, jeg kan hjælpe dig med?", c="Ah, jeg har ventet på dette. De væsener, du stod overfor... de er en gammel trussel, som Horden fortsat vælger at ignorere. Hadoken var klog nok til at bringe dette - og dig - til mig.\n\nZukk'asj er ikke andet end væsener, der kaldes silitider. Nogle vil mene, at de er en tankeløs plage, men lad mig forsikre dig - de er en langt, langt værre trussel end noget, Alliancen kunne mønstre.\n\nHvis du er villig og stærk nok, kunne jeg bruge din bistand til at bringe denne trussel frem i lyset."},
  [7733] = {n="Forbedret Kvalitet", l="Bring 10 Vredesarr-yetihuder til Pratt McGrubbe ved Fjermåne-fæstningen, Vildalas.", d="Jeg har fået et tip om en endnu BEDRE kilde til huder, hvis det overhovedet er til at tro! I Vildalas' nordlige dele - dybt inde i Vredesarrets Greb - er der en ny flok yetier. De er meget sejere end dem, du har mødt før, så hvis du er klar til en større udfordring, må du passe godt på!\n\nJeg ville belønne dig rigeligt for en bunke på ti af deres huder; bring dem til mig her, så gør vi færdig med vores forretning.", p="Hvis disse Vredesarr-yetihuder er bare nogenlunde af samme kvalitet som deres Vild Arr-modstykker, kan de meget vel være lige så modstandsdygtige som thorium!\n\nTænk lige engang!", c="Fremragende, fremragende! Det her bliver fantastisk - jeg kan allerede se, at de bliver meget hårdere, når de er ordentligt garvede.\n\nTak igen for din hjælp, <Name>. Her - tag venligst en af mine nyeste kreationer."},
  [7734] = {n="Forbedret Kvalitet", l="Bring 10 Vredesarr-yetihuder til Jangdor Hurtigskrider i Lejr Mojasje, Vildalas.", d="Jeg har fået et tip om en endnu BEDRE kilde til huder, hvis det overhovedet er til at tro! I Vildalas' nordlige dele - dybt inde i Vredesarrets Greb - er der en ny flok yetier. De er meget sejere end dem, du har mødt før, så hvis du er klar til en større udfordring, må du passe godt på!\n\nJeg ville belønne dig rigeligt for en bunke på ti af deres huder; bring dem til mig her, så gør vi færdig med vores forretning.", p="Hvis disse Vredesarr-yetihuder er bare nogenlunde af samme kvalitet som deres Vild Arr-modstykker, kan de meget vel være lige så modstandsdygtige som thorium!\n\nTænk lige engang!", c="Fremragende, fremragende! Det her bliver fantastisk - jeg kan allerede se, at de bliver meget hårdere, når de er ordentligt garvede.\n\nTak igen for din bistand, <Name>. Her - tag venligst en af mine nyeste kreationer."},
  [7761] = {n="Sortehånds Kommando", l="Det er en utrolig dum ork. Det ser ud til, at du skal finde dette brandmærke og opnå Drakkisats Mærke for at få adgang til Kommandokuglen.\n\nBrevet antyder, at General Drakkisat vogter brandmærket. Måske du bør undersøge sagen.", d="Idiot,\n\nJeg har meget lidt tro på din evne til at forhindre udefrakommende i at komme ind i mesterens hule. I det meget sandsynlige tilfælde af din død har denne kugle et indbygget sikkerhedssystem, der forhindrer udefrakommende i at teleportere direkte ind i Sortvinge.\n\nKun dem med Drakkisats Mærke brændt ind i hånden kan gøre brug af denne kugle. Heldigvis er Drakkisat langt fra så inkompetent som dig, kvartermester! Han vogter selv mærket!\n\n-Krigshøvding Flænse Sortehånd\n\nP.S. Ødelæg dette brev, idiot.", c="Du blinker ikke engang, mens det rygende brandmærke trykkes ind i dit kød. Du er så sej!\n\nDu bærer nu Drakkisats Mærke. Hav det sjovt med at storme borgen."},
  [7781] = {n="Herren over Sortklippe", l="Bring Nefarians hoved tilbage til Højlord Bolvar Fordrågon i Stormvind.", d="Den gamle følelse vender tilbage. Sejrens velkomne smerter gennemstrømmer hele din krop. Foran dig ligger Nefarians monolitiske, kampsvedne hoved. Bring det tilbage til din højlord, mester.", p="Utænkeligt!", c="Du behøver ikke få fortalt, hvad det, du har gjort, betyder, <Name>. Denne dag vil blive indskrevet i historiens annaler. En sejr af den slags, Alliancen ikke har set i årevis - hvis nogensinde!"},
  [7782] = {n="Herren over Sortklippe", l="Begiv dig til Heltenes Dal i Stormvind By og tal med Feltmarskal Afrasiabi.", d="Gå til Heltenes Dal og tal med Feltmarskal Afrasiabi.", c="<Feltmarskal Afrasiabi bukker.>\n\nVælg din belønning, lad festlighederne begynde!"},
  [7783] = {n="Herren over Sortklippe", l="Bring Nefarians hoved tilbage til Træl i Orgrimmar.", d="Den gamle følelse vender tilbage. Sejrens velkomne smerter gennemstrømmer hele din krop. Foran dig ligger Nefarians monolitiske, kampsvedne hoved. Bring det tilbage til din krigshøvding, mester.", p="Jeg ville ønske, at jeg havde været der for at se udtrykket i uhyrets ansigt, da du gav det dødsstødet, <Name>.", c="Du har endnu en gang æret Horden, <Name>. Dødsvingens søn ligger død. Det onde vågner helt sikkert."},
  [7784] = {n="Herren over Sortklippe", l="Tal med Højoverherre Øglefang i Orgrimmar. Han venter på dig i Styrkens Dal.", d="Søg Højoverherre Øglefang i Styrkens Dal.", c="Vælg din belønning, så jeg kan montere uhyrets hoved, så alle kan se det."},
  [7785] = {n="Undersøg Karret", l="Undersøg Genfødelseskarret og vend tilbage til Højlord Dæmitrian.", d="Undersøg karret med hans genfødsel, dødelige. Det er herfra, at Vindsøgeren skal genfødes!", p="Vil du løsne ham fra hans evige fængsel?", c="Må du blive beskyttet på dit korstog. Må Mesteren velsigne dine bestræbelser."},
  [7786] = {n="Tordenaan Vindsøgeren", l="For at befri Tordenaan Vindsøgeren fra hans fængsel skal du fremvise den højre og venstre halvdel af Vindsøgerens Bindinger, 10 stænger elementium og Ildherrens Essens til Højlord Dæmitrian i Silitus.", d="Jeg har fortalt dig alt, hvad jeg ved, <Name>. Det er dig, der skal finde elementium. Det er dig, der skal ødelægge Ildherrens legemlige form.\n\nGør dette og få Tordenaans velsignelse.", p="Bring verden på knæ, hvis du må!", c="Selv i drømme turde jeg ikke forudse denne dag.\n\nSe, dødelige.\n\nSE HAN, DER ER ÆLDRE END EKSISTENSEN!\n\nSE HAN, DER HAR STÅET OVER FOR TITANER OG GUDER!\n\nRejs dig, min mester! Bryd fri af dine lænker!"},
  [7787] = {n="Rejs dig, Tordenvrede!", l="Fremvis det sovende vindkyssede sværd til Højlord Dæmitrian.", d="Du har besejret Vindsøgeren. Tag det sovende sværd og tving den løgnagtige udskud, Dæmitrian, til at bruge de materialer, du leverede til hans forræderi, til at vække Tordenvrede.", p="<Dæmitrian krymper sig i din nærvær.>", c="Skån mig venligst! Tag det! Tag sværdet! Lad Dæmitrian omforme sit patetiske liv!"},
  [7788] = {n="Knus invaderne!", l="Gå ind i Krigssangskløften og besejr Horden, opnå et Krigssangskløftens Æresmærke, og vend tilbage til Vagt Fjernsang ved Sølvvinge-lunden.", d="Bag denne tunnel finder du en slagmark af strid og uro, unge <Class>. Horden fortsætter med at decimere vores hellige skov og fælder det grønne løv for at drive deres krigsmaskiner.\n\nGå ind i Krigssangskløften og forsvar Sølvvingegrebet. Skub de invaderende hordestyrker tilbage!\n\nGør dette, og optjen et Æresmærke. Bring det til mig, <Name>, så belønner jeg dig.", p="Har du kæmpet i Krigssangskløften og forsvaret Sølvvingegrebet?", c="Du har bevist din værdi for vores indsats i Krigssangskløften. Fortsæt med at bistå sagen og bring mig flere Æresmærker. Gør du dette, vil du opnå endnu større tillid fra os."},
  [7789] = {n="Undertryk Sølvvinge-tronranerne", l="Gå ind i Krigssangskløften og besejr Alliancen, opnå et Krigssangskløftens Æresmærke, og bring det til Kaptajn Knuskranie ved Mor'sjan Basislejr.", d="Askedalens vildmark skal bukke under for Hordens styrke, <Race>. Intet, Sølvvinge siger eller gør, kan stoppe vores suveræne pligt. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste det, der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger deres svage forsøg på at bremse vores fremskridt ned. Ødelæg Sølvvinge-vagterne og optjen et Æresmærke. Vend tilbage til mig med sådan et mærke, <Name>, så bliver du belønnet.", p="Fjendernes blod er et æresmærke. Har du sådan et mærke?", c="<Kaptajn Knuskranie brøler i triumf>\n\nHvor meget mere kan de holde til? Hvor mange flere Alliance-skarn må dø for Hordens hånd, før de trækker sig tilbage? Kun tiden vil vise det, <Race>..."},
  [7791] = {n="En Uldgave", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Stormvind for dine generøse handlinger. Vores lager af uld er sådan, at vi kun skal bruge tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsats.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7792] = {n="En Uldgave", p="Vi modtager i øjeblikket donationer af uldklæde. En donation på tres stykker uldklæde vil give dig fuld anerkendelse fra Darnassos for dine generøse handlinger. Vores lager af uld er sådan, at vi kun skal bruge tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at støtte vores indsats.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7793] = {n="En Silkegave", p="Ligesom de fleste andre stoffer er vores lager af silke på det laveste nogensinde. Vores lager er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med støtte fra andre.\n\nEn velvillig gave som silke, kan jeg tilføje, ville helt sikkert øge din lokale status i samfundet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7794] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lager op igen! Ved at regne med samfundet som helhed skal vi kun bruge en donation på 60 stykker magevæv fra dig for at nå vores mål. Sådan en generøsitet ville ikke gå ubemærket hen hos Stormvind, det kan jeg forsikre dig om!\n\nHvis du har de tres stykker magevæv på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7795] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type klæde stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, som du har gjort tidligere!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi vil først modtage en enkelt donation på tres, og så går vi derfra.", c="Fantastisk - de her går lige i brug, det kan jeg forsikre dig om. Tak igen for din hjælp! Vi ville helt sikkert være fortabt uden dig.\n\nMed alle de donationer, du har givet, vil jeg helt bestemt behandle alle yderligere runestofdonationer, du måtte ønske at give i fremtiden. Bare sørg for at melde dig hos mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver ubemærket!"},
  [7798] = {n="En Silkegave", p="Ligesom de fleste andre stoffer er vores lager af silke på det laveste nogensinde. Vores lager er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med støtte fra andre.\n\nEn velvillig gave som silke, kan jeg tilføje, ville helt sikkert øge din lokale status i samfundet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7799] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lager op igen! Ved at regne med samfundet som helhed skal vi kun bruge en donation på 60 stykker magevæv fra dig for at nå vores mål. Sådan en generøsitet ville ikke gå ubemærket hen hos Darnassos, det kan jeg forsikre dig om!\n\nHvis du har de tres stykker magevæv på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse donation, <Name>!"},
  [7800] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type klæde stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, som du har gjort tidligere!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi vil først modtage en enkelt donation på tres, og så går vi derfra.", c="Fantastisk - de her går lige i brug, det kan jeg forsikre dig om. Tak igen for din hjælp! Vi ville helt sikkert være fortabt uden dig.\n\nMed alle de donationer, du har givet, vil jeg helt bestemt behandle alle yderligere runestofdonationer, du måtte ønske at give i fremtiden. Bare sørg for at melde dig hos mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver ubemærket!"},
  [7803] = {n="En Silkegave", p="Ligesom med de fleste andre stoffer er vores lager af silke nede på et alletiders bundniveau. Vores beholdninger er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med hjælp fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale status i fællesskabet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7804] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen i Jernsmede, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7805] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7809] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen hos Nisseborg-gnomerne, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7810] = {n="Arenamester", l="Tal med Kort Johan Mithril i Kvælerdorn-arenaen.", d="Der må være mere til at være arenaens mester end dette! Måske ved piraten, der står for begivenheden hos Gurubashi, det!", c="Arr, mit hjertebarn! At vinde et enkelt Smykke er ikke nok til at gøre dig til arenaens mester! Nu er det tid til virkelig at bevise dit stål."},
  [7811] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7814] = {n="En Silkegave", p="Ligesom med de fleste andre stoffer er vores lager af silke nede på et alletiders bundniveau. Vores beholdninger er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med hjælp fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale status i fællesskabet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7815] = {n="Knipsekæbere, mon!", l="Katoom Fiskeren i Hævnhugtand-landsbyen i Bagland vil have dig til at dræbe 15 saltvands Knipkæbe-skildpadder. Vend tilbage til ham, når du har udført denne opgave.", d="Lad dig ikke narre af deres store øjne, mon! De saltvands-knipsekæbere er en rigtig plage. Jeg kan ikke fiske i fem minutter uden at få en knækket line fra en af de der overdimensionerede fiskestøvsugere, som stjæler min madding.\n\nGør mig og folkene i Hævnhugtand-landsbyen en tjeneste og dræb dem, mon.\n\nDræb hele flokken!", p="Hvordan går jagten?", c="Åh, mon! Jeg kan ikke takke dig nok! Forhåbentlig er den her fiskestang belønning nok for jobbet."},
  [7816] = {n="Gamlerita, mon!", l="Katoom Fiskeren i Hævnhugtand-landsbyen i Bagland vil have dig til at dræbe Gamlerita og hente Katooms Bedste Lokkemiddel fra hendes lig.\n\nKatoom nævnte, at Gamlerita hænger ud ved kysten sammen med de andre skildpadder.", d="Yo! Der er en skildpadde derude, som ikke er som de andre. Hun er Gamlerita, lederen af saltvands-knipsekæberne - en ordentlig beskidt, tyvagtig krybdyr.\n\nMon, hun stjal mit bedste lokkemiddel! Knækkede det lige af min line! Siden da bider fiskene ikke på det samme.\n\nFind Gamlerita og få mit lokkemiddel ud af hendes mave.", p="Har du fået det endnu?", c="MON! Det her er fantastisk! Med mit bedste lokkemiddel og knipsekæbe-bestanden nede vil fiskene hobe sig op."},
  [7817] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen i Undergrunden, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7818] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7821] = {n="En Silkegave", p="Ligesom med de fleste andre stoffer er vores lager af silke nede på et alletiders bundniveau. Vores beholdninger er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med hjælp fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale status i fællesskabet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7822] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen i Tordenklippe, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7823] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7824] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7826] = {n="En Uldgave", p="Vi modtager i øjeblikket gaver af uldklæde. En gave på tres stykker uldklæde vil give dig fuld anerkendelse fra Orgrimgrad for dine generøse handlinger. Vores lager af uld er sådan, at vi kun skulle bruge tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at understøtte vores indsamling.\n\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7827] = {n="En Silkegave", p="Ligesom med de fleste andre stoffer er vores lager af silke nede på et alletiders bundniveau. Vores beholdninger er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med hjælp fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale status i fællesskabet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7828] = {n="Forfølg Forfølgerne", l="Jægermester Bjergged i Hævnhugtand-landsbyen i Bagland vil have dig til at dræbe 15 Sølvmanke-forfølgere og 15 Sølvmanke-hylere. Vend tilbage til ham, når opgaven er udført.\n\nBjergged nævnte, at ulvene gemmer sig i Baglandets vildmark.", d="Mange modige trolde er gået tabt i Baglandets barske vildmark, <Race>. Sølvmanke-ulvene er en af de største trusler mod vores jægere. De ligger på lur, gemmer sig blandt buske og landskab og slår til, når muligheden byder sig.\n\nDen slags vildskab lader vi ikke gå ustraffet!\n\nDu må tænke som en Sølvmanke. Forfølg forfølgerne! Slå dem alle ihjel!", p="Vis dem Hævnhugtands styrke!", c="Et veludført stykke arbejde, <Race>. Hævnhugtand takker dig for dit bidrag."},
  [7829] = {n="Jagt på de Vilde", l="Jægermester Bjergged i Hævnhugtand-landsbyen i Bagland vil have dig til at dræbe 20 vilde Uglebæster. Vend tilbage til ham, når opgaven er udført.\n\nBjergged nævnte, at de vilde Uglebæster holder til i Baglandets vildmark.", d="Blandt de mere gnavne dyr i Baglandet er de vilde uglebæster. Mange en god Hævnhugtand-kriger er gået til grunde under bæsternes rasende kløer og næb.\n\nDræb hver eneste vilde uglebæst, du ser, <Race>. Vend tilbage til mig, når du ikke kan holde mere blodsudgydelse ud. Dit bidrag vil så blive vejet, målt og dømt.", p="Rens dit hoved for urene tanker, <Race>. Bliv ét med vildmarken!", c="Du har vist dig at være en værdig allieret for Hævnhugtand, <Name>. Godt gået."},
  [7830] = {n="Hævn over de Faldne", l="Jægermester Bjergged i Hævnhugtand-landsbyen i Bagland vil have dig til at dræbe en Barbernæb Himmelherre og hente dens Himmelherre-fane. Vend tilbage til ham, når opgaven er udført.\n\nBjergged nævnte, at Barbernæb Himmelherrerne er en sjælden race, der har en tendens til at holde til i Baglandets vildmark.", d="Møget, der kalder sig Vildhammer, træner gryfoner til at slå trolde ihjel. Forfærdeligt, jeg ved det, men frygt ikke, retfærdigheden skal nok komme.\n\nLige nu vil jeg have dig til at fokusere på at udrydde regionens ældre gryfoner. De kaldes Himmelherrer.\n\nDræb en og vend tilbage til mig med dens fane.", p="Barbernæb Himmelherren er en langt sjældnere gryfon-race: En, der er ansvarlig for at parre sig og skabe morderiske afkom.", c="<Bjergged undersøger fanen.>\n\nJeg spekulerer på, hvor mange af vores jægere dette udyr fik opslugt, før du bragte det til retfærdighed."},
  [7831] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen i Orgrimgrad, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7833] = {n="En Uldgave", p="Vi modtager i øjeblikket gaver af uldklæde. En gave på tres stykker uldklæde vil give dig fuld anerkendelse fra Mørkspyd-trolde for dine generøse handlinger. Vores lager af uld er sådan, at vi kun skulle bruge tres stykker fra dig i alt; vi burde kunne skaffe nok fra andre i riget til at understøtte vores indsamling.\nHvis du har de tres stykker uldklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7834] = {n="En Silkegave", p="Ligesom med de fleste andre stoffer er vores lager af silke nede på et alletiders bundniveau. Vores beholdninger er sådan, at vi kun skal bruge tres stykker silke fra dig i alt; vi burde kunne nå vores mål med hjælp fra andre.\n\nEn velvillig gave som silke, må jeg tilføje, vil helt sikkert øge din lokale status i fællesskabet! Hvis du har de tres stykker silkeklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7835] = {n="En Magevævsgave", p="Magevæv er ved at løbe tør, og vi kunne bruge din hjælp til at fylde vores lagre op igen! Ved at regne med fællesskabet som helhed ville vi kun have brug for en gave på 60 stykker magevævsklæde fra dig for at nå vores mål. Sådan generøsitet ville ikke gå ubemærket hen hos Mørkspyd-trolde, det kan jeg love dig!\n\nHvis du har de tres stykker magevævsklæde på dig og er klar til at donere dem, kan jeg tage dem fra dig nu.", c="Vidunderligt! Vi takker dig for din generøse gave, <Name>!"},
  [7836] = {n="En Runestofgave", p="<Name>, du har været en enorm bidragyder til vores stofindsamling. Mens vi arbejder hårdt på at fylde vores reserver op, er én type stof stadig kritisk lav - runestof. Vi har et absolut desperat behov for det, og vi håber, at du kan hjælpe os, ligesom du har gjort før!\n\nHvis du er villig, så bring mig det runestof, du kan undvære. Vi tager først imod en enkelt gave på tres, og så ser vi, hvor vi går herfra.", c="Fantastisk - de her kommer straks i brug, det kan jeg love dig. Tak igen for din hjælp! Vi ville helt sikkert være fortabte uden dig.\n\nMed alle de gaver, du har givet, ville jeg bestemt behandle eventuelle yderligere runestofgaver, du måtte ønske at give i fremtiden. Bare sørg for at kigge forbi mig, så sørger jeg personligt for, at dine gode gerninger ikke bliver glemt!"},
  [7839] = {n="Ondskabsgren-rølpene", l="Smed Slagtræ i Hævnhugtand-landsbyen i Bagland ønsker, at du finder Slagtræs Tabte Værktøj. Retur til ham, når opgaven er fuldført.\n\nDu husker, at Smed Slagtræ nævnte, at værktøjet måske var ved et af Ondskabsgren-templerne i den nordøstlige region af Bagland. Du bør også tjekke Snigeklippe.", d="Ondskabsgren-pakket invaderede vores landsby og har stjålet mit værktøj! Jeg har reservværktøj, men sættet de stjal var en gave fra en venlig gnom, som reddede mit liv, dengang jeg var en ung ork.\n\nJeg vil have mit værktøj tilbage, <Name> - det betyder alt for mig.\n\nBjergged rapporterede, at værktøjet blev set nær Agol'vatha- og Shaol'vatha-templerne.\n\nDisse templer ligger i den nordøstlige region af Bagland.\n\nGenvind mit værktøj!", p="Pas på Ondskabsgren-trolde i området, <Name>. De er hensynsløst, mordisk pak.", c="Mit værktøj! Du fandt det! Åh, herlige dag! Tak, <Name>."},
  [7840] = {n="Flæsk Tabte Sin Frokost", l="Flæsk i Hævnhugtand-landsbyen i Bagland ønsker, at du finder Flæsks Frokost. Retur til ham, når opgaven er fuldført.\n\nFlæsk nævnte, at han efterlod den på øen mod nord. Pas på Ondskabsgren-trolde.", d="Flæsk var på hemmelig særlig plet og holdt piknik, da grim gemen Ondskabsgren angreb Flæsk med da store kæp. Flæsk løb tilbage til Hævnhugtand, men glemte Flæsk frokost. Flæsk sulten. Måske du gå tilbage til hemmelig særlig plet og hente Flæsk frokost? Flæsk bange. Gå nort! Øen der mod nort er da hemmelig særlig plet.", p="<Flæsk gnider sin enorme mave.>\n\nFlæsk så sulten.", c="<Flæsk tager det store kødstykke fra dig og proppede det op i ansigtet.>\n\nDis ramte da plet! Tak lille én.\n\nFlæsk laver dig en særlig picnickurv for hjælp Flæsk."},
  [7841] = {n="Besked til Vildhammeren", l="Otho Mojibrøl i Hævnhugtand-landsbyen i Bagland ønsker, at du slagtrer 15 Højdal-udløbere, 15 Højdal-spejdere, 15 Højdal-skarpskytter og 15 Højdal-skovvogtere. Retur til ham, når opgaven er fuldført.\n\nDu kan finde Højdal-højalferne ved Quel'Dånil-hytten i den nordvestlige region af Bagland.", d="Vildhammeren be' i gang med at lave aftaler med vores fjender, smede nye alliancer, mon. Denne gang samarbejder de med højalferne.\n\n<Otho spytter.>\n\nVi må sende de vildhammer-dværge en besked - en besked i vores fjenders blod. Slagt hver eneste Højdal-højalf, du støder på, og lad deres kroppe ligge som en advarsel.\n\nRør aldrig ved trolde!", p="Du er for ren, mon. Du skal blande det lidt op - kom ned i mudderet og bliv beskidt sammen med fjenden.", c="Det ser ud til, at Hævnhugtand også smeder nye alliancer, mon! Du gjorde det godt."},
  [7842] = {n="Endnu en Besked til Vildhammeren", l="Otho Mojibrøl i Hævnhugtand-landsbyen i Bagland ønsker, at du bringer ham 10 Lange Elegante Fjer fra gryffonerne, der lever i Bagland. Retur til ham, når opgaven er fuldført.\n\nGryffoner menes at leve i alle regioner af Bagland.", d="De siger, at Vildhammeren og gryffonen er lige så tætte som trold og makker. Modbydeligt, men vi kan bruge det til vores fordel, mon. Vi sender dem en besked til.\n\nDræb alle gryffonerne, du ser i Bagland, og saml deres fjer. Af dem laver vi den sidste besked.", p="Den sidste besked vil skræmme dem væk, det er sikkert. Eller også gør den dem meget, meget vrede.", c="Åh, mon, det her bliver godt. Ét skridt endnu, så ser Vildhammeren, at de ikke kan rode med trold!"},
  [7843] = {n="Den Sidste Besked til Vildhammeren", l="Otho Mojibrøl i Hævnhugtand-landsbyen i Bagland ønsker, at du rejser til Ørnerede-toppen i den vestlige region af Bagland og placerer den Sidste Besked til Vildhammeren ved brønden midt i byen. Retur til ham, når opgaven er fuldført.\n\nVær på vagt over for vrede Vildhammer-dværge og uregerlige medlemmer af Alliancen.", d="<Otho rækker dig et langt, blodgennemtrukket spyd, indpakket i flere gryffonfjer.>\n\nDu tager det her, mon. Du tager det til Ørnerede-toppen, lige midt i byens centrum ved brønden. Du planter det! Drift det lige ned i jorden! Vis dværgene, at trold mener forretning! Kom tilbage, når du har gjort det. Forhåbentlig kommer du tilbage i live.", p="Hvad er der i vejen, mon?", c="Jeg ville ønske, jeg havde været der for at se deres ansigter, mon. Pakker de deres tasker? Forlader de byen?\n\nDu gjorde det godt, <Name>. Virkelig godt. Otho belønner dig med den store mojo."},
  [7844] = {n="Kannibalske Fætre", l="Mystisk Jajo'jin i Hævnhugtand-landsbyen i Bagland ønsker, at du dræber 30 Ondskabsgren-skalpere og 15 Ondskabsgren-spåkoner. Retur til hende, når opgaven er fuldført.\n\nJajo'jin har angivet, at disse trolde kan findes nær Shaol'vatha- og Agol'vatha-templerne i den nord-nordøstlige region af Bagland.", d="Tre forskellige stammer af trolde lever i Bagland, <Name>. Så langt rækker ligheden mellem stammerne: Vi er alle trolde, og vi lever i Bagland.\n\nOndskabsgren - passende navngivet - er et fordærvet folk; de lever af andre trolde og humanoider.\n\nHvis Zul'jin havde været her, havde han udslettet hele flokken med et vink af sit håndled - desværre er Zul'jin ikke vendt tilbage endnu, og vi er overladt til os selv.\n\nDet er op til dig at ødelægge områdets møg!", p="Ondskabsgren-spåkonerne og -skalperne holder til i den nord-nordøstlige region af Bagland.", c="Godt gået, <Class>. Zul'jin selv kunne ikke have gjort et bedre stykke arbejde!"},
  [7845] = {n="Bortført Ældre Tornhugtand!", l="Urtids Tornhugtand i Hævnhugtand-landsbyen i Bagland ønsker, at du redder hendes make, Ældre Tornhugtand, fra Jintha'alør.\n\nDu har fået at vide, at han holdes fange øverst på Jintha'alør, Ondskabsgren-hovedstaden i den sydlige region af Bagland.", d="Min make blev bortført af Ondskabsgren-vildmænd i et dristigt midnatsangreb på vores landsby. Vores spioner har fortalt mig, at han stadig er i live og holdes fange øverst på Jintha'alør. Ond Præstinde Hekse siges at forberede ham til et offer til det ansigtsløse blodgud, Hakar.\n\nDu må redde ham, <Name>! Vores landsby kunne ikke klare et så stort tab.", c="Du må handle hurtigt, <Name>. Vagterne er sikkert blevet advaret om din tilstedeværelse."},
  [7846] = {n="Genvind Nøglen!", l="Ældre Tornhugtand i Jintha'alør ønsker, at du dræber Hitah'ja Vogteren for at få Lænkenøglen til hans bindinger. Retur til Ældre Tornhugtand, når du har genvundet nøglen.", d="Nøglen til mine bindinger holdes af Hitah'ja Vogteren. Hun befinder sig i den nærliggende hule. Vær forsigtig, <Class>, for hun er godt vogtet.\n\nDræb hende og bring nøglen tilbage, så mine lænker løsner sig. Først da kan jeg vende hjem igen.", p="Du må skynde dig!", c="Endelig fri! Tak, <Name>. Hævnhugtand vil kende til dine gerninger!"},
  [7847] = {n="Retur til Urtids Tornhugtand", l="Ældre Tornhugtand i Jintha'alør ønsker, at du vender tilbage til Urtids Tornhugtand i Hævnhugtand-landsbyen med nyheder om hans redning.", d="Retur til min make, Urtids Tornhugtand i Hævnhugtand-landsbyen. Fortæl hende, at jeg er på vej hjem! Hun vil sikkert belønne dig.", c="Du har gjort Hævnhugtand en stor tjeneste, <Name>! Vi står i enorm gæld til dig."},
  [7848] = {n="Indstilling til Kernen", l="Begiv dig til portalen til Lavakernen i Sortklippe-dybderne og genvind et Kerne-fragment. Retur til Lothøs Revnevogter i Sortklippebjerget, når du har genvundet Kerne-fragmentet.", d="Revner rører sig, sprækker og kollapser omkring os, <Race>. Ikke to skridt fra hvor jeg står, er der en revne, der fører gennem dybderne i Sortklippebjerget, ind i Ildherrens gab.\n\nOverrasket? Synd... De dødelige racer kan ikke forstå det, de ikke kan se, røre eller føle.\n\nJeg forsikrer dig, portalen er der, og adgang er mulig.\n\nHar jeg vakt din interesse? Indstilling er enkel. Begiv dig ind i Sortklippe-dybderne og hent et Kerne-fragment. Bring det til mig, så vil jeg indstille din essens på portalen.", p="Du må indstille din sjæl på Lavakernen, før adgang gives.", c="Jeg kan nu transportere dig til Lavakernen. Bed, og det skal ske."},
  [7849] = {n="Adskillelsesangst", l="Jægermester Bjergged i Hævnhugtand-landsbyen i Bagland ønsker, at du genvinder rester efter sin tvillingebror. Find og retur Jægermester Malbjerggeds Kranium og Jægermester Malbjerggeds Knogler til Jægermester Bjergged.\n\nBjergged nævnte, at hans brors rester blev givet til slimene og ulvene i Ondskabsgren. Han nævnte også, at der er en affaldsgrav fuld af slim i Jintha'alør samt et ulvehi. Begge disse steder er nær toppen af templet.", d="Ligesom mange i vores landsby har jeg også mistet en kær til vildmarken. Ak, det var min tvillingebror Malbjergged - bortført i det samme overfald som Tornhugtands make af Ondskabsgren.\n\nDesværre var han ikke skæbnebestemt til at leve, og han fik en hurtig, brutal henrettelse; hans rester blev givet til slimene og ulvene i Ondskabsgren.\n\nDet er for sent at redde hans liv, men ikke for sent at redde hans sjæl. Genvind hans rester, <Name>.", p="Når jeg har hans rester, tager jeg dem med til Jajo'jin, og de bliver gjort klar til en ordentlig begravelse.", c="Min kæreste bror, hvor jeg kommer til at savne dig...\n\nTak for din bistand, <Name>. Du er virkelig en helt i mine øjne."},
  [7850] = {n="Mørke Kar", l="Urtids Tornhugtand i Hævnhugtand-landsbyen i Bagland ønsker, at du genvinder 10 Kar med Besmittet Blod fra Jintha'alør. Retur til Urtids Tornhugtand, når opgaven er fuldført.", d="Ondskabsgren kæmper med overnaturlig vildskab. Det skyldes de onde magiske vævninger fra Ond Præstinde Hekse.\n\nOver hele Jintha'alør vil du finde mørke kar med besmittet blod. Karrene udstråler det ansigtsløse blodguds onde magi, som styrker Ondskabsgren og samtidig driver dem til vanvid.\n\nStjæl disse kar og bring dem til mig, så jeg kan fjerne fordærvet og til sidst løsne blodgudens greb.", p="Vær forsigtig, når du kæmper mod Ondskabsgren, <Name>. Deres sind er formørkede - de kæmper til døden.", c="Den mørke energi, der driver Ondskabsgren, er blevet fjernet - for nu. Vi må altid være årvågne i kampen mod det onde, for selv hvis Ond Præstinde bliver ødelagt, tager en anden snart hendes plads."},
  [7861] = {n="Eftersøgt: Ond Præstinde Hekse og Hendes Håndlangere", l="Du er blevet beordret til at slå Ond Præstinde Hekse og 20 Ondskabsgren Amanzasi-vagter ihjel. Se Urtids Tornhugtand i Hævnhugtand-landsbyen i Bagland, når opgaven er fuldført.\n\nOnd Præstinde Hekse og Amanzasi-vagterne kan findes øverst på Jintha'alør i Bagland.", d="Efter ordre fra Urtids Tornhugtand skal Ond Præstinde Hekse og hendes håndlangere bringes for retfærdighed!\n\nEn stor belønning tilbydes enhver, der dræber Ond Præstinde Hekse og hele hendes Amanzasi-elitevagt.", p="Har du nyheder fra Jintha'alør?", c="Et lammende slag mod Ondskabsgren, sandelig. Du vil blive rigt belønnet, <Name>."},
  [7862] = {n="Jobåbning: Vagtkaptajn i Hævnhugtand-landsbyen", l="Du har fået til opgave at decimere 20 Ondskabsgren-berserkere, 20 Ondskabsgren-skyggejægere, 20 Ondskabsgren-blodsugere og 20 Ondskabsgren-sjæleædere.\n\nSkulle du fuldføre denne opgave, så Retur til Urtids Tornhugtand i Hævnhugtand-landsbyen i Bagland.", d="Med tabet af Vagtkaptajn Malbjergged er stillingen som Vagtkaptajn i Hævnhugtand igen ledig. Hvis du er interesseret i at blive Vagtkaptajn for Hævnhugtand, skal du fuldføre følgende opgaver og indsende din ansøgning til Urtids Tornhugtand:\n\nUdryd Ondskabsgren-berserkere.\n\nUdryd Ondskabsgren-skyggejægere.\n\nUdryd Ondskabsgren-blodsugere.\n\nUdryd Ondskabsgren-sjæleædere.", p="Er du her vedrørende jobåbningen?", c="Du er da en værdig kandidat til den nye stilling, <Name>. Acceptér denne lille pynt som tegn på vores taknemmelighed for dit hårde arbejde. Jeg vil gennemgå alle ansøgninger næste år."},
  [7863] = {n="Vagt Simpel Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7864] = {n="Vagt Standarte-plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7865] = {n="Vagt Avanceret Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7866] = {n="Rytter Simpel Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7867] = {n="Rytter Standarte-plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7868] = {n="Rytter Avanceret Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, tag venligst denne plejepakke! Indeni finder du rationer og bandager, som kun kan bruges inde i Krigssang-Gulch.\n\nNår du fortsætter med at bevise dig inde i Gulch, vil du opdage, at disse genstande bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig med os, og bandager, når du er Æret."},
  [7871] = {n="Besejr Angriberne!", l="Skriv ind i Krigssang-Gulch og besejr Horden, skaf et Krigssangskløftens Æresmærke, og retur til Vagt Fjernsang i Sølvvinge-lunden.", d="Bag denne tunnel finder du et felt af strid og uro, unge <Class>. Horden bliver ved med at udrydde vores hellige skov og fælder det grønne løv for at drive deres krigsmaskiner.\n\nSkriv Krigssang-Gulch og forsvar Sølvvingegrebet. Tryk de invaderende Horde-styrker tilbage!\n\nGør du det, og fortjen et Æresmærke. Bring det til mig, <Name>, så belønner jeg dig.", p="Har du kæmpet i Krigssang-Gulch og forsvaret Sølvvingegrebet?", c="Du har bevist din værdi for vores indsats i Krigssang-Gulch. Bliv ved med at yde bistand til sagen og bring mig flere Æresmærker. Gør du det, vil du fortjene endnu mere af vores tillid."},
  [7872] = {n="Besejr Angriberne!", l="Skriv ind i Krigssang-Gulch og besejr Horden, skaf et Krigssangskløftens Æresmærke, og retur til Vagt Fjernsang i Sølvvinge-lunden.", d="Bag denne tunnel finder du et felt af strid og uro, unge <Class>. Horden bliver ved med at udrydde vores hellige skov og fælder det grønne løv for at drive deres krigsmaskiner.\n\nSkriv Krigssang-Gulch og forsvar Sølvvingegrebet. Tryk de invaderende Horde-styrker tilbage!\n\nGør du det, og fortjen et Æresmærke. Bring det til mig, <Name>, så belønner jeg dig.", p="Har du kæmpet i Krigssang-Gulch og forsvaret Sølvvingegrebet?", c="Du har bevist din værdi for vores indsats i Krigssang-Gulch. Bliv ved med at yde bistand til sagen og bring mig flere Æresmærker. Gør du det, vil du fortjene endnu mere af vores tillid."},
  [7873] = {n="Besejr Angriberne!", l="Skriv ind i Krigssang-Gulch og besejr Horden, skaf et Krigssangskløftens Æresmærke, og retur til Vagt Fjernsang i Sølvvinge-lunden.", d="Bag denne tunnel finder du et felt af strid og uro, unge <Class>. Horden bliver ved med at udrydde vores hellige skov og fælder det grønne løv for at drive deres krigsmaskiner.\n\nSkriv Krigssang-Gulch og forsvar Sølvvingegrebet. Tryk de invaderende Horde-styrker tilbage!\n\nGør du det, og fortjen et Æresmærke. Bring det til mig, <Name>, så belønner jeg dig.", p="Har du kæmpet i Krigssang-Gulch og forsvaret Sølvvingegrebet?", c="Du har bevist din værdi for vores indsats i Krigssang-Gulch. Bliv ved med at yde bistand til sagen og bring mig flere Æresmærker. Gør du det, vil du fortjene endnu mere af vores tillid."},
  [7874] = {n="Dæmp Sølvvinge-tronranerne", l="Skriv ind i Krigssang-Gulch og besejr Alliancen, skaf et Krigssangskløftens Æresmærke, og bring det til Kaptajn Knuskranie ved Mor'sjan Basislejr.", d="Vildmarken i Askedalen vil bukke under for Hordens styrke, <Race>. Intet, som Sølvvinge siger eller gør, kan stoppe vores suveræne imperativ. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste det, der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger deres svage forsøg på at bremse vores fremskridt ned. Ødelæg Sølvvinge-vagterne, og fortjen et Æresmærke. Retur til mig med et sådant Æresmærke, <Name>, så bliver du belønnet.", p="Blodet fra vores fjender er et Æresmærke. Har du et sådant?", c="<Kaptajn Knuskranie brøler i triumf>\n\nHvor meget mere kan de udholde? Hvor mange flere Alliance-møg skal gå til grunde for Hordens hænder, før de indleder et tilbagetog? Kun tiden vil vise det, <Race>..."},
  [7875] = {n="Dæmp Sølvvinge-tronranerne", l="Skriv ind i Krigssang-Gulch og besejr Alliancen, skaf et Krigssangskløftens Æresmærke, og bring det til Kaptajn Knuskranie ved Mor'sjan Basislejr.", d="Vildmarken i Askedalen vil bukke under for Hordens styrke, <Race>. Intet, som Sølvvinge siger eller gør, kan stoppe vores suveræne imperativ. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste det, der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger deres svage forsøg på at bremse vores fremskridt ned. Ødelæg Sølvvinge-vagterne, og fortjen et Æresmærke. Retur til mig med et sådant Æresmærke, <Name>, så bliver du belønnet.", p="Blodet fra vores fjender er et Æresmærke. Har du et sådant?", c="<Kaptajn Knuskranie brøler i triumf>\n\nHvor meget mere kan de udholde? Hvor mange flere Alliance-møg skal gå til grunde for Hordens hænder, før de indleder et tilbagetog? Kun tiden vil vise det, <Race>..."},
  [7876] = {n="Knus Sølvvinge-tronrøverne", l="Gå ind i Krigssang-Gulch og besejr Alliancen, få et Krigssang-Gulch-Æresmærke, og bring det til Kaptajn Knuskranie ved Mor'sjan Basislejr.", d="De vilde skove i Askedalen skal bukke under for Hordens magt, <Race>. Intet Sølvvinge kan sige eller gøre noget for at stoppe vores suveræne bydende nødvendighed. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste, hvad der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger deres svage forsøg på at bremse vores fremskridt ned. Ødelæg Sølvvinge-vagterne, og optjen et Æresmærke. Kom tilbage til mig med sådan et Mærke, <Name>, så bliver du belønnet.", p="Hedningens blod er et æresmærke. Har du sådan et mærke?", c="<Kaptajn Knuskranie brøler triumferende>\n\nHvor meget mere kan de holde til? Hvor mange flere Alliance-skarn skal falde for Hordens hænder, før de trækker sig tilbage? Kun tiden vil vise det, <Race>..."},
  [7877] = {n="Shendralarens Skat", l="Vend tilbage til Athenæum og find Shendralarens Skat. Gør krav på din belønning!", d="I biblioteket, Athenæum, finder du en gammel kiste gemt under trappen. Tag fra den, hvad end du begærer.", c="Du åbner kisten og finder..."},
  [7905] = {n="Mørkemånens Marked", l="Aflever det Fri Billet-Gavekort til Gelvas Grimport, som befinder sig inde i Mørkemånens Marked-cirkuset.", d="Mørkemånens Marked kommer! Sørg for at opleve alle dets undere og spænding, når det kommer til byen!\n\nHvis du handler lige nu, kan du indløse dette gavekort til gratis præmiebilletter! Bare giv dit gavekort til Gelvas Grimport, som befinder sig inde i cirkuset.\n\nLige nu står Marked uden for Guldshire, i Elwynnskoven. Gå ikke glip af det! Tag afsted i dag!", p="Ja ven, må jeg hjælpe dig? Har du et gavekort, der skal indløses?", c="Velkommen til Mørkemånens Marked! Dette gavekort gælder for FEM, ja, FEM præmiebilletter!\n\nNår du samler præmiebilletter, vil du gerne tale med mig om at indløse dem til værdifulde præmier. Jo flere billetter du får, jo flere præmier kan du vinde. Hurra!"},
  [7908] = {n="Arenamester", l="Tal med Kort Johan Mithril i Kvælerdorn-arenaen.", d="Der må være mere til at være arenamester end det her! Måske ved Piraten, der driver begivenheden i Gurubashi, det!"},
  [7926] = {n="Mørkemånens Marked", l="Aflever det Fri Billet-Gavekort til Gelvas Grimport, som befinder sig inde i Mørkemånens Marked-cirkuset.", d="Mørkemånens Marked kommer! Sørg for at opleve alle dets undere og spænding, når det kommer til byen!\n\nHvis du handler lige nu, kan du indløse dette gavekort til gratis præmiebilletter! Bare giv dit gavekort til Gelvas Grimport, som befinder sig inde i cirkuset.\n\nLige nu står Marked lige uden for Tordenklippe, i Mulgorr. Gå ikke glip af det! Tag afsted i dag!", p="Ja ven, må jeg hjælpe dig? Har du et gavekort, der skal indløses?", c="Velkommen til Mørkemånens Marked! Dette gavekort gælder for FEM, ja, FEM præmiebilletter!\n\nNår du samler præmiebilletter, vil du gerne tale med mig om at indløse dem til værdifulde præmier. Jo flere billetter du får, jo flere præmier kan du vinde. Hurra!"},
  [7961] = {n="Vaskelige Vabbitter!", l="Dræb 5 kaniner og vend tilbage til Jon Snedig ved smedjen på Designer-øen.", d="Disse kaniner formerer sig ukontrolleret. Noget må gøres!\n\nHjælp os, <Name>, du er vores eneste håb."},
  [7962] = {n="Vabbit-pelse", l="Bring 3 Snedige Kanin-pelse til Jon Snedig.", d="Jeg vil have snedige kanin-pelse. Skaf mig nogle fra Snedige Kaniner.\n\nDet her er vigtigt!"},
  [8041] = {n="Styrken fra Mugmøre-bjerget", c="Hil dig, <Class>. Jeg er Jyn'rokh Knuseren, trold fra Mugmøre. Vi i Sandalar-stammen anerkender dine bedrifter. Vi hylder din udholdenhed og din viljestyrke.\n\nBær denne talisman om halsen, <Class>. Lad styrken fra Mugmøre-bjerget strømme gennem dit væsen. Bliv styrket, mens du slår vores fjender ned!"},
  [8042] = {n="Styrken fra Mugmøre-bjerget", p="Det er godt at se dig ved godt helbred, <Name>. De herlige slag, du har kæmpet, påvirker alt liv på denne planet. Hakar må aldrig forlade Zul'Skrubs grænser, for verden vil uden tvivl kollapse under hans enorme sult.\n\nGiv mig din talisman, så forstærker jeg dens styrke. Brug Mugmøres styrke til at straffe vores fjender!", c="Vores veje vil krydse hinanden igen, <Class>."},
  [8043] = {n="Styrken fra Mugmøre-bjerget", p="Mester <Name>, du vender tilbage! Mølthor har sendt bud om dine gerninger til kongen. Dit navn er kendt selv i Sydhavet. Måske bliver du en dag en legendarisk <Class> – en historie for evigheden.\n\nGiv mig din talisman, så jeg igen kan forstærke dens kraft.", c="Brug din nyfundne styrke til at ødelægge Gurubashierne!"},
  [8044] = {n="Mugmøres Vrede", p="Kong Rastakhan sender sine hilsener, Mester <Name>. En sådan ære er aldrig blevet givet til nogen uden for Sandalar-stammen.\n\n<Jyn'rokh bukker.>\n\nGiv mig din talisman, så jeg kan forstærke den endnu en gang. Vid, at Mugmøres Vrede nu er uløseligt forbundet med din sjæl.", c="Zul'jyn ville være misundelig, <Class>. Drag afsted og erobr!"},
  [8045] = {n="Hedningens Mærke", c="Vid dette, hedning: En katastrofe har bragt os sammen. Dine hedenske veje forstås hverken eller værdsættes af Sandalar, men vi er et retfærdigt folk. Bær dette mærke om halsen. Det skal tjene både som en advarsel til vores fjender og som et symbol på dit venskab med Sandalar.\n\nFortsæt med at tjene vores folk, så forstærker jeg mærkets kraft."},
  [8046] = {n="Hedningens Mærke", p="Jeg har måske været for hastig i min dom, <Class>. Det ser ud til, at din blinde tro på dette Let har en vis værdi alligevel.\n\nGiv mig dit mærke, så forstærker jeg dets kraft.", c="Gør hvad du må for at besejre vores fjender, <Class>. Selv hvis det betyder at kanalisere Lyset.\n\n<Jyn'rokh gyser.>"},
  [8047] = {n="Hedningens Mærke", p="Jeg må indrømme, at jeg ikke troede, du havde beslutsomheden til at føre denne sag til ende, <Class>. Sandalar anser dig nu for en uvurderlig allieret. Godt gjort, helt bestemt.\n\nGiv mig dit mærke, så forstærker jeg dets kraft endnu en gang.", c="Vores overbevisninger er forskellige, men vores sag er retfærdig. Slå vores fjender ned, ædle <Class>."},
  [8048] = {n="Heltens Mærke", p="Kongen har anerkendt din eksistens, <Class>. Du er den første af din slags, der er blevet accepteret af Rastakhan som en sand allieret af Sandalar.\n\nDu vil blive rigt belønnet for din indsats. Fremvis dit mærke, så anvender jeg den endelige forstærkning.", c="Årvågenhed, ære, loyalitet, mod... Du legemliggør alle disse egenskaber, og det samme skal dit mærke."},
  [8049] = {n="Zuldazars Øje", c="Modtag denne talisman som et tegn på vores taknemmelighed, præst.\n\nZuldazars Øje vil vokse i styrke, i takt med at dit bånd til trollene i Sandalar styrkes. Vend tilbage til mig med jævne mellemrum, så indgyder jeg juvelen kraft."},
  [8050] = {n="Zuldazars Øje", p="Velkommen, præst. Zuldazars Øje pulserer af energi. Du er klar til at tage det næste skridt. Giv mig talismanen, så udfører jeg indgydelsen.", c="Fortsæt din kamp mod Sjælsflåeren og hans håndlangere, <Name>. Han må aldrig tillades at forlade Zul'Skrubs grænser."},
  [8051] = {n="Zuldazars Øje", p="Fortællinger om dine kampe mod Gurubashierne hviskes i vinden, præst. Selv kongelige begynder at tale om dine gerninger. Det ryges, at kong Rastakhan endda har nævnt dig ved navn.\n\nTiden er kommet til at indgyde Øjet. Giv mig talismanen, så udfører jeg tjenesten.", c="Vær fast i dine bestræbelser, <Name>. Sjælsflåeren vil forsøge at sluge din livsvilje."},
  [8052] = {n="Zuldazars Alseende Øje", p="Hvis vi bare havde ti tusind flere som dig, <Name>. Hakars hære ville blive spredt for vinden på et øjeblik.\n\n<Al'tadøm sukker.>\n\nDesværre er Øjet klar til at realisere sit fulde potentiale. Giv det til mig.", c="Straf dem alle og lad Hakar sortere dem ud..."},
  [8053] = {n="Kraftens Mønstre: Frisindets Armskinner", l="Bring Jyn'rokh Knuseren Urtids Håkkari-bindinger. Du skal desuden have et ry, der er lig med eller større end Venlig hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="Du er en hedning. Hedninge har en plads i stammen. Hedninge er frisindede af Sandalar. Frisindede frygter ikke undertrykkelse. Frisindede dør for det, de tror på. Vi ved, at du ville dø for det, du tror på. Dette opnår vores anerkendelse. Dette giver dig en chance for at bevise dig selv yderligere.\n\nVi må have Kraftens Mønstre. Gå til Zul'Skrub. Dræb Hakars håndlangere. Vend tilbage, når du har det, jeg søger. Gør krav på den første kampudrustning fra en frisindet af Sandalar.\n\nAf sted.", p="Er du vendt tilbage? Har du Kraftens Mønstre? Spilder du min tid?\n\nDet håber jeg ikke, hedning.", c="Du gør meget for at ære os. Dine hænder drypper af blodet fra Hakars håndlangere. Du er en ven af stammen.\n\nBær disse armskinner. De er frisindetens armskinner. Det er det, jeg mener med ægte kraft."},
  [8054] = {n="Kraftens Mønstre: Frisindets Bælte", l="Bring Jyn'rokh Knuseren et Urtids Håkkari-sjal. Du skal desuden have et ry, der er lig med eller større end Æret hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="Dine overbevisninger er fremmede for os, hedning. Gamle Sandalar blev engang brændemærket som kættere. Det var dengang, Gurubashi-imperiet var stærkt. Hedninge turde udfordre Hakars præst. Hedningene blev dengang jagtet og dræbt som skadedyr. Disse hedninge vaklede aldrig i deres kamp mod Blodguden. Vi ærer den pris, de betalte. De er frisindede.\n\nDræb Hakars håndlangere i Zul'Skrub. Bring mig de Kraftens Mønstre, jeg søger. Held vil blive rigt belønnet.\n\nAf sted.", p="Din tilstedeværelse betyder sejr? Har du Mønstrene? Drypper du af dine fjenders rester?", c="Din ære er sikret i stammen. Du gør krav på mange dødsfald i Zul'Skrub. Fjender falder for din overbevisning. Fjender falder for din kraft.\n\nDette er frisindetens bælte. Det er et symbol på ære. Det er kraftfuld mojo. Det er nu dit."},
  [8055] = {n="Kraftens Mønstre: Frisindets Brystplade", l="Bring Jyn'rokh Knuseren en Urtids Håkkari-kjortel. Du skal desuden have et ry, der er lig med eller større end Respekteret hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="Kampudrustning giver dig magt i stammen. Frisindede er hædret på denne måde. De er nidkære. De forsyner deres brystplader med kraftfuld mojo. Hvis deres overbevisninger vakler over for fjenden, vil deres brystplade ikke.\n\nDu skal være respekteret blandt os for at eje sådan en brystplade. Gå til Zul'Skrub. Tag de Kraftens Mønstre, jeg har brug for. Tag Mønstrene med smerte fra dårerne indenfor. Bring dem til mig. Bevis din værdi som frisindet en gang for alle.", p="Har du Mønstrene? De har mojo inde i sig. Vi må have dem. Du vil hjælpe os.", c="Du har gjort, hvad få nogensinde kunne. Du har bragt Hakars håndlangere på knæ. Du har vist dem, hvad en frisindet kan gøre. Du har vist os, hvordan en kætter kunne blive respekteret i stammen. Du har mere end ægte magt. DU ER ægte magt.\n\nTag brystpladen, frisindede. Knus dem, der står dig imod."},
  [8056] = {n="Kraftens Mønstre: Spåmandens Armbeskyttere", l="Bring Majvikki fra Zuldasar en Urtids Håkkari-armskinne. Du skal desuden have et ry, der er lig med eller større end Venlig hos Sandalar-stammen.\n\nMajvikki fra Zuldasar befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="Stammens spåmænd er hædret for deres gaver til det guddommelige syn, ja mon. De er ikke nogen heksedoktor; de bruger deres tid på at kaste knogler eller læse i bladene for indsigt – ikke at forhekse folk. Som shaman ved du allerede noget om augurens kraft; vi i Sandalar prisen den indsigt, de giver stammen.\n\nBring mig et offer af Kraftens Mønstre fra indeni Zul'Skrub og bevis din værdi for os. Gør det for os, så giver jeg dig nogle armbeskyttere, som vores spåmænd sætter højere end alle andre!", p="Fik du de Kraftens Mønstre fra Zul'Skrub, jeg har brug for? Disse armbeskyttere er det værd at gøre en indsats for!", c="Det ser ud til, at du har lidt af en Sandalar-spåmand i dig. Vi ved om de bedrifter, du har udført i Zul'Skrub på vores vegne, mon. Disse Kraftens Mønstre vil gå langt i at hjælpe Sandalar-stammen – en stamme, jeg kan tilføje, du kan kalde på som venner. Tag disse armbeskyttere, <Name>; du har fortjent dem og lidt til!"},
  [8057] = {n="Kraftens Mønstre: Indvoldsspåmandens Armbeskyttere", l="Bring Majvikki fra Zuldasar en Urtids Håkkari-støtte. Du skal desuden have et ry, der er lig med eller større end Venlig hos Sandalar-stammen.\n\nMajvikki fra Zuldasar befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="En indvoldsspåmand er et nøglemedlem af vores stamme; du gør klogt i at lytte til deres varsler. Ved at kommunikere med dyr og ofre dem til ånderne, når det er nødvendigt, giver de os guddommelig vejledning. I svundne tider gav indvoldsspåmandens indsigt og visdom os en fordel i krigene mod de splittede Gurubashi-stammer.\n\nBring mig et offer af Kraftens Mønstre fra indeni Zul'Skrub og bevis din værdi for os. Gør dette, så giver jeg dig armbeskyttere, som enhver indvoldsspåmand blandt Sandalar ville ønske sig.", p="Har du fået Kraftens Mønstre fra Zul'Skrub? Disse armbeskyttere er umagen værd, <Name>. Stol på mig, mon!", c="Ah, jeg kan fornemme kraften fra disse Kraftens Mønstre, <Name>. Du beviste at være en, vi i stammen kan kalde „ven“. En aftale er en aftale, <Name>... se nu kraften i indvoldsspåmandens armbeskyttere!"},
  [8058] = {n="Kraftens Mønstre: Hævnerens Armskinner", l="Bring Jyn'rokh Knuseren en Urtids Håkkari-armskinne. Du skal desuden have et ry, der er lig med eller større end Venlig hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen, Kvælerdorn-dalen.", d="Hævn er magt. Sandalar-hævneren er en sådan magt. Stammen har mange fjender. Hævneren udøver gengældelse over for dem. Ingen forbrydelse mod os forbliver ustraffet. Hævneren leverer denne straf. Vores fjender frygter vores hævn. Det bør de. De vil altid gøre det.\n\nBliv en af vores hævnere. Søg Kraftens Mønstre i Zul'Skrub. Slå Hakars håndlangere ihjel og gør krav på hævn i stammens navn. Du vil blive belønnet.", p="Har du bragt Kraftens Mønstre? Er hævn blevet taget i Sandalars navn?", c="Du har udøvet meget hævn i dag. Du har antaget hævnerens skikkelse. Du har bragt Blodgudens håndlangere på knæ.\n\nTag dette. Det vil nære din hævn i fremtiden. Du er nu en ven af Sandalar."},
  [8059] = {n="Kraftens Mønstre: Den Besattes Bind", l="Bring Al'tadøm den Alseende en Urtids Håkkari Støtte. Du skal også have et ry lig med eller større end Venlig hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Hexenmestre træder på farligt grund, når de handler med dæmoner, men vores besatte tager det et skridt videre. Gennem et gammelt og arkant ritual lader de en dæmon komme ind i deres væsen. I stedet for at lade den besidde dem, slaver de dæmonen indefra og optager udyrets kraft til deres egen kommando. Det er en bedrift, som få nogensinde formår at mestre.\n\nFor at du skal lære om den besattes kraft, må jeg have Kraftens Mønstre fra Zul'Gurub-hulen. Gå derhen og hent det, vi søger.", p="Er du vendt tilbage med Kraftens Mønstre? Ved at besejre Hakars djævelske håndlangere beviser du ikke blot dig selv over for os, men også din villighed til at lære den besattes veje.", c="Godt gjort... der er ingen tvivl om, at de blev tvunget til at betale på pinefulde måder, før de gav slip på Kraftens Mønstre. Tag her - den besattes bind. Lavet af stærk magi, der bruges til at kalde den besattes bytte frem, er det et kraftfuldt redskab i din jagt på magt."},
  [8060] = {n="Kraftens Mønstre: Synsbedragerens Bind", l="Bring Al'tadøm den Alseende Urtids Håkkari Bindinger. Du skal også have et ry lig med eller større end Venlig hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Magikere i vores stamme kaldes synsbedragere. De bruger stærk magi i deres besværgelser og forvirrer ofte stammens fjender til ukendelighed!\n\n<Al'tadøm ler ondskabsfuldt.>\n\nDet er et syn for guder at se en mægtig synsbedrager i aktion, der bringer vores fjender på knæ med deres egen galskab!\n\nFor at du skal kende vores synsbedrageres vej, skal du gå til Zul'Gurub-hulen og bringe mig udvalgte Kraftens Mønstre. Til gengæld giver jeg dig de armbind, vores synsbedragere bruger til at væve deres besværgelser.", p="<Name> - er du allerede tilbage? Fik du fat i de Kraftens Mønstre, jeg har brug for?", c="Imponerende... kunne du mærke magien flyde gennem dem? Kraftens Mønstre blev brugt som en slags valuta, dengang Gurubashi-imperiet herskede over disse lande. Nu vil vi Sandalarerne bruge den skjulte magi i dem til at bekæmpe Blodguden Hakars anden opstandelse!\n\nDu har klaret dig godt i dag - betragt dig selv som en ven af Sandalarerne. Som tak er her synsbedragerens bind, som jeg lovede!"},
  [8061] = {n="Kraftens Mønstre: Skriftefaderens Bind", l="Bring Al'tadøm den Alseende en Urtids Håkkari Støtte. Du skal også have et ry lig med eller større end Venlig hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Vi Sandalar giver magt til dem, der taler med det guddommeliges autoritet. Vores præster er mere end blot healere - de er vores skriftefædre. Ondskab kommer både udefra - som Hakar - og indefra stammen. Vores skriftefædre fungerer som dommere iblandt os og beskytter os mod den samme ondskab, der fortærede Gurubashierne indefra.\n\nGå til Zul'Gurub-hulen og bring Kraftens Mønstre tilbage fra Gurubashierne. Lær, hvad det vil sige at være skriftefader, og bevar os fra ondskab.", p="Tilbage fra Zul'Gurub-hulen, er du? Er det lykkedes dig at hente Kraftens Mønstre fra Hakars håndlangere?", c="Enestående, <Name>! Det var ingen lille bedrift at bringe dem til mig. Ingen tvivl om, at du i dag har optrådt som vores stammes skriftefader ved at beskytte os mod Hakars trussel. Disse bind passer til en ven af stammen som dig!"},
  [8062] = {n="Kraftens Mønstre: Rovdyrets Armbeskyttere", l="Bring følgende Kraftens Mønstre fra Zul'Gurub-hulen til Falthør den Blinde: En Urtids Håkkari Bindinger. Du skal også have et ry lig med eller større end Venlig hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="I de mørke tider efter Gurubashi-imperiets fald brugte Sandalarnes rovdyr deres dygtighed til at skaffe stammen føde. Jægere påstår, at de minder meget om vores stammes rovdyr - at søge jagten er ja, at legemliggøre rovdyrets essens. Din jagt i Zul'Gurub-hulen vil dog vise os, hvordan du virkelig står mål med vores fineste rovdyr.\n\nBring mig en prøve af Kraftens Mønstre fra Zul'Gurub-hulen. Gør du det, tager du de første skridt mod at blive det næstsidste rovdyr.", p="Jag dem i Zul'Gurub-hulen, som vil besidde Kraftens Mønstre, <Name>. De er dit bytte; de har det, vi begge må have.", c="Ja... jeg har ikke brug for syn for at fornemme Kraftens Mønstres nærvær. Din succes i Zul'Gurub-hulen har imponeret mange i stammen. Vi anser dig ikke blot for at være en ven af Sandalarerne, men også værdig nok til at eje rovdyrets armbeskyttere - kraftfulde genstande og et symbol på, hvad det vil sige at være rovdyr. Godt gjort, <Name>."},
  [8063] = {n="Kraftens Mønstre: Galningens Armbeskyttere", l="Bring Falthør den Blinde en Urtids Håkkari Armskinne. Du skal også have et ry lig med eller større end Venlig hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Sandalarnes galninger ligner skurke, men frem for alt omfavner de galskaben... kaosset... tilværelsens uforudsigelighed. En rædsel at skue på slagmarken såede de forvirringens og kaosets frø blandt vores fjender i de barske tider, efter stammerne splittedes. Vi var ikke her i dag uden dem.\n\nBring mig Kraftens Mønstre fra Zul'Gurub-hulen, som jeg søger, så giver jeg dig den første af galningens værdsatte rustninger. Omfavn galskaben!", p="Søg galskaben i Zul'Gurub-hulen og overskygge den med din egen, <Name>! Det betyder succes, og succes betyder belønning! Lad ikke Blodguden herske igen!", c="Godt gjort, <Name>... dine bedrifter i Zul'Gurub-hulen har fortjent dig retten til at kalde Sandalar-stammen for en ven. Jeg vil sørge for Mønstrenes skæbne; for din indsats, så accepter venligst denne belønning!"},
  [8064] = {n="Kraftens Mønstre: Indvoldsspåmandens Bælte", l="Bring Majvikki fra Guldazar en Urtids Håkkari Sjærp. Majvikki fra Guldazar befinder sig på Yojamba-øen i Kvælerdorn-dalen. Du skal også være Æret hos Sandalarerne.", d="Vi Sandalar kender ikke til druidiske veje; naturen skal formes efter vores behov, ikke omvendt. Alligevel er en indvoldsspåmand den af os, der er mest i takt med naturen, og det med rette. At give slip på et udyrs ånd er at vide, hvad det vil sige at være et af dem. Det er naturens sande kraft.\n\nBring mig et offer af Kraftens Mønstre fra inde i Zul'Gurub-hulen, så beviser du dig over for os. Gør du det, giver jeg dig et kraftfuldt bælte - et, som mange af Sandalarernes indvoldsspåmænd har båret.\n\nStærk magi, ja, min ven!", p="Har du fået de Kraftens Mønstre fra Zul'Gurub-hulen, jeg skal bruge? Indvoldsspåmandens bælte bliver dit, hvis du har dem.", c="Jeg takker dig - den skjulte kraft i disse genstande vil være skatte i sig selv, ja da. Du har ikke blot gjort, som jeg bad om, men du har også vist dig værdig over for os her i stammen. Som lovet, her er din belønning!"},
  [8065] = {n="Kraftens Mønstre: Indvoldsspåmandens Tunika", l="Bring Majvikki fra Guldazar en Urtids Håkkari Kjortel. Majvikki fra Guldazar befinder sig på Yojamba-øen i Kvælerdorn-dalen. Du skal også være Respekteret hos Sandalarerne.", d="Det ultimative symbol på en indvoldsspåmands kraft er det, de bærer, <Name>. Af disse symboliserer tunikaen forbindelsen mellem dem selv og den guddommelige visdom, de søger. Den væver ofte dele af de udyr, de ofrer, ind i tunikaen; det minder dem om forbindelsen til deres gaver.\n\nBring mig et offer af Kraftens Mønstre fra inde i Zul'Gurub-hulen, og bevis din værdi over for os. Gør du det, bliver en tunika, der drypper af indvoldsspåmandens sande kraft, din.", p="Har du de nødvendige Kraftens Mønstre fra Zul'Gurub-hulen? Indvoldsspåmandens tunika er al den besvær værd, du må gøre dig.", c="Imponerende... du har med succes samlet de krævede Kraftens Mønstre, <Name>. Dine bedrifter i Zul'Gurub-hulen for Sandalarerne er legendariske; derfor vil du fra nu af være respekteret blandt stammen. Her er din tunika, mægtige <Class>!"},
  [8066] = {n="Kraftens Mønstre: Rovdyrets Bælte", l="Bring følgende Kraftens Mønstre fra Zul'Gurub-hulen til Falthør den Blinde: En Urtids Håkkari Sjal. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Et rovdyr ved, hvordan det skal liste sit bytte, men et succesfuldt rovdyr ved, hvordan det skal slå til, når det har lukket rækkerne. Du må mestre begge dele for at have nogen chance for succes i Zul'Gurub-hulen... og nogen chance for at ligne Sandalarernes rovdyr.\n\nBring mig de bedste dele af Kraftens Mønstre fra inde i Zul'Gurub-hulen. Min belønning bliver den kraft, tilbehøret giver, mens din bliver Sandalarnes rovdyrsbælte - udstyr, der er hver en handel værd.", p="Slå til mod Hakars vanvittige håndlangere i Zul'Gurub-hulen - det er dem, der har Kraftens Mønstre, <Name>. Bevis din succes over for dem - og over for stammen - som en aspirant til rovdyret.", c="Jeg fornemmede din ankomst lige før, <Name>, men ikke uden besvær. Det, der afslørede dig for mig, var de Kraftens Mønstre, du bragte. Jeg kan mærke kraften uden at behøve at se tilbehøret; deres skjulte magi - rå magi, om man vil - vil blive ved med at brænde vores kamp mod Blodguden Hakars djævelske planer.\n\nDu skal roses - og belønnes - for din succes. Du er æret blandt stammen, og du er værdig til at bære rovdyrets bælte."},
  [8067] = {n="Kraftens Mønstre: Rovdyrets Skulderkappe", l="Bring følgende Kraftens Mønstre fra Zul'Gurub-hulen til Falthør den Blinde: En Urtids Håkkari Ægis. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Vi Sandalar værdsætter det, vi bærer, som et symbol på præstation. Du behøver ikke kunne se, hvad man bærer, for at mærke, hvad der udstråler fra det - kraft overskrider synet. Rovdyret fra Sandalar er sådan, og mest værdsat af dem er skulderkappen, de bærer. Den hjælper med at skjule dem for synet... og gøre deres nærvær kendt, når de ønsker det.\n\nKraftens Mønstre venter på din indsamling i Zul'Gurub-hulen. Bring mig det, jeg søger, og rovdyrets skulderkappe skal være din.", p="Har dine angreb i Zul'Gurub-hulen givet succes, <Name>? Først når du har bragt mig det, jeg søger - og bevist dig fuldt over for stammen - vil du fortjene en kappe, der står over alle andre blandt Sandalarerne.", c="Succes... du skal respekteres blandt stammen, <Name>. Det var ingen lille bedrift at skaffe de Kraftens Mønstre, der var nødvendige for skulderkappen, men du klarede det på de dødeligste af vores rovdyrs maner. Du har fortjent din plads blandt dem, og du har bestemt fortjent retten til at bære deres skulderkappe."},
  [8068] = {n="Kraftens Mønstre: Synsbedragerens Skulderkappe", l="Bring Al'tadøm den Alseende en Urtids Håkkari Sjal. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Magi er en rå, urtidskraft, der skal formes af dem, der er stærke nok til at gøre det. Stærk magi er vores forlængelse af denne kraft; en af de mest potente manipulationer af den er i form af illusion. Hvordan kan man virkelig håbe på at vinde mod en fjende, der slet ikke er der? Vi Sandalar kender kraften i dette, og derfor har synsbedragere en æret plads i stammen.\n\nTag de nødvendige Kraftens Mønstre fra Zul'Gurub-hulen - for dette bliver æren fra stammen og en mægtig skulderkappe, som vores bedste synsbedragere bruger, din!", p="Hvordan gik dit ophold i Zul'Gurub-hulen? Fik du dine fjender til at blive gale af illusionens kraft? Illusion eller ej, deres død - og de Kraftens Mønstre, der blev taget fra dem - vil hjælpe med at forpurre Hakars opstandelse.", c="Succes! Fra nu af skal du æres i stammen! Zul'Gurub-hulen har sandelig smagt Sandalarnes styrke i dag, takket være dig <Name>.\n\nMed stammens velsignelse, tag Sandalarernes synsbedragers skulderkappe. Må den tjene dig godt."},
  [8069] = {n="Kraftens Mønstre: Synsbedragerens Kapper", l="Bring Al'tadøm den Alseende en Urtids Håkkari Kosak. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Stammen anerkender rang og magt gennem det, vi bærer. Vores ornater er lavet af de fineste materialer og vævet sammen med den magi, vi bruger til at gøre os stærke. Synsbedragere er ingen undtagelse; deres kapper siges at legemliggøre illusionens essens i deres udseende. Legenden fortæller, at deres gamle kapper aldrig så ens ud to gange.\n\nJeg vil give dig en synsbedragers kappe, <Name>... men du må først fortjene din plads i ærefrygt blandt stammen! Bring mig Kraftens Mønstre fra Zul'Gurub-hulen!", p="Er du vendt tilbage med de Kraftens Mønstre, vi har brug for? Jeg ved, det ikke bliver let... men jeg har længe forudsagt, at en udenforstående ville komme og hjælpe os i kampen mod Hakar. Lad det være dig, siger jeg!", c="Endelig, nogen, der er værdig til at bære synsbedragerens kapper! Din succes i Zul'Gurub-hulen har sikret din ærefrygt blandt stammen i generationer fremover. Bær dem med stolthed, <Name>!"},
  [8070] = {n="Kraftens Mønstre: Skriftefaderens Bindinger", l="Bring Al'tadøm den Alseende en Urtids Håkkari Sjærp. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Kort efter Gurubashiernes fald var vi Sandalar næsten ved at lide et endeligt nederlag på grund af ondskab inde i vores egen stamme. Det var dengang, skriftefaderne iblandt os rejste sig og bevarede stammen ved at forvise dem, der ville ødelægge deres egne. De holder os ikke blot i takt med ånderne, men beskytter også kødet.\n\nGå ind i Zul'Gurub-hulen og overvær med egne øjne Hakars og Gurubashiernes fordærvelse. Riv de Kraftens Mønstre, vi søger, fra dem; succes vil blive belønnet!", p="Kraftens Mønstre... har du dem? Først når vi har dem, kan vi udnytte den skjulte kraft, der er lagret i dem. Det bliver godt at vende bordet mod Blodgudens håndlangere...", c="Succes! Disse vil føre os langt i at opbygge vores magt mod Hakars opstandelse. Med din hjælp har vi taget et betydeligt skridt til at sikre, at Blodguden ikke udsletter os alle.\n\nDu har fortjent ære hos stammen i dag, <Name>. Tag dette - skriftefaderens bindinger - som et symbol på vores tak."},
  [8071] = {n="Kraftens Mønstre: Skriftefaderens Skulderkappe", l="Bring Al'tadøm den Alseende en Urtids Håkkari Ægis. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Sandalarernes skriftefædre bærer alle en karakteristisk skulderkappe, der markerer dem som stammens bevarere. Disse kapper er vævet med kraftfuld magi, der hjælper dem med at dømme dem, der ville true vores stamme. Som præst må du også bruge din tid på at dømme, hvem der er værdig, og hvem der ikke er; en sådan kappe ville helt sikkert være en velsignelse for dig.\n\nTil gengæld for at kæmpe mod Hakars håndlangere i Zul'Gurub-hulen og bringe mig de Kraftens Mønstre, jeg søger, giver jeg dig en kappe, der er værdig til vores fineste skriftefædre.", p="Har du Kraftens Mønstre fra Zul'Gurub-hulen?", c="Godt gjort, <Name> - Hakars håndlangere har sikkert mærket Sandalarnes gengældelse i dag, takket være dig. Dine handlinger har givet dig en permanent plads i ærefrygt inden for stammen. Med vores velsignelse, tag venligst denne skriftefaders skulderkappe som din egen!"},
  [8072] = {n="Kraftens Mønstre: Galningens Skulderkappe", l="Bring Falthør den Blinde en Urtids Håkkari Bælte. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="En af Sandalarernes legendariske galninger var Khar'vaxal den Revnede. Legenden fortæller, at da han for første gang stod over for stammens fjender, brugte han sin skulderkappe, specielt vævet med \"galskabens væv\". Hans skikkelse var skjult ikke blot af kappen, men også af hans tvillingedolkes blændende hastighed. Galninger i dag værdsætter deres skulderkappe som et tegn på deres plads i stammen.\n\nBring mig de Kraftens Mønstre, jeg søger, så bliver en sådan kappe din, til at væve galskab over dine egne fjender.", p="Du er vendt tilbage - har du de Kraftens Mønstre, jeg skal bruge?\n\nSagnet om Khar'vaxal den Revnede tjener os i dag som en påmindelse om, at ingen fjende - uanset hvor stor en trussel de er - er umulig at besejre. Kaos vil bringe alle på knæ, det er helt sikkert... og måske de mindst kaotiske elementer af kaos.", c="Sejren er vores i dag, takket være den galskab, du har sået blandt vores fælles fjender! Du skal æres blandt Sandalarerne, og der er ingen bedre måde at vise taknemmelighed for dine gerninger end ved at tilbyde dig galningens skulderkappe!"},
  [8073] = {n="Kraftens Mønstre: Galningens Tunika", l="Bring Falthør den Blinde en Urtids Håkkari Ægis. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nFalthør den Blinde befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Mine øjne svigtede mig for længe siden, men jeg savner dem ikke. Selv i en stamme som vores - hvor ens ornater viser rang og formål - udstråler den mest magtfulde beklædning kraft, som simple øjne ikke kan se. Galningens eftertragtede tunika fra Sandalar er ingen undtagelse og udstråler den rå kraft af kaos og galskab, som de er i stand til at kanalisere.\n\nDe Kraftens Mønstre, jeg har brug for, ligger i Zul'Gurub-hulen; bring mig det, jeg søger, så belønner jeg dig med din egen legendariske tunika... en, der passer til en vævre af galskab.", p="Velkommen tilbage til øen, <Name>... er du vendt triumferende tilbage med Kraftens Mønstre i hånden?", c="Imponerende... du har i dag udført, hvad få troede var muligt. Din ærefrygt i stammen er sikret for livet, <Name>. Du har fortjent retten til at tage galningens tunika på - gør det med vores velsignelse."},
  [8074] = {n="Kraftens Mønstre: Spåmandens Bælte", l="Bring Majvikki fra Guldazar et Urtids Håkkari Bælte. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nMajvikki fra Guldazar befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Spåmænd kender elementernes magi, mand. De bruger den som et middel til at lede stammen til ære. I de mørke dage efter Gurubashi-imperiet rev sig selv op, førte vores spåmænd os til vores sikre tilflugt på Sydhavet. De har også ledt os tilbage hertil til dalen, lige ind i hjertet af det onde, der bryger i Zul'Gurub-hulen.\n\nBring mig et offer af Kraftens Mønstre fra inde i Zul'Gurub-hulen og bevis din værdi over for os. Gør du det, giver jeg dig et bælte, som vores spåmænd bruger - et med stærk magi indeni!", p="Kraftens Mønstre er, hvad jeg har brug for, mand - vi vil tappe kraften direkte ud af dem i kampen mod ondskaben fra Zul'Gurub-hulen. Har du dem til mig?", c="Jeg kan lugte duften af besejret ondskab på dig, <Name>. Det er en sød duft, mand... en, jeg tror, du kender godt.\n\nJeg ved, det ikke har været nogen let bedrift at bringe mig de Kraftens Mønstre, der kræves til bæltet. Dine gerninger har ikke blot æret stammen, men også dig selv blandt min stamme. Her er det - tag spåmandens bælte og bær det som din egen!"},
  [8075] = {n="Kraftens Mønstre: Spåmandens Brynje", l="Bring Majvikki fra Guldazar en Urtids Håkkari Kjortel. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nMajvikki fra Guldazar befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Sandalarernes spåmænd bærer alle et karakteristisk bryststykke kaldet en brynje. Den er forsynet med de fineste silke og stoffer, vævet sammen med stærk kæde. Den er et symbol ikke blot på deres guddommelighed, men også på deres autoritet, mand. Det er aldrig klogt at krydse en, hvis liv er viet til at tale med ånderne...\n\nBring mig et offer af Kraftens Mønstre fra inde i Zul'Gurub-hulen og bevis din værdi over for os. Gør du det, giver jeg dig en af de fineste brynjer, vores spåmænd nogensinde kunne håbe på at bære!", p="Kraftens Mønstre er en nøglekilde til magisk kraft - samme slags kraft, der går i at lave spåmandens brynje. Bring mig det, jeg behøver, så kan jeg dele de fineste ornater, enhver Sandalar-spåmand ville ønske sig som sin egen.", c="Jeg ved, hvad du måtte igennem for at bringe mig Kraftens Mønstre, <Name>. Det var ikke let, mand - at besejre ondskaben, der sive ud af Zul'Gurub-hulen som et ækelt slimvæsen - men nu hvor det hele er sagt og gjort, kan jeg roligt sige, at du vil blive respekteret blandt Sandalarerne i generationer!\n\nSå - tag spåmandens brynje og bær den med stolthed!"},
  [8076] = {n="Kraftens Mønstre: Den Besattes Skulderkappe", l="Bring Al'tadøm den Alseende en Urtids Håkkari Sjærp. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Den besatte stræber efter at legemliggøre magt fuldt ud, ikke blot besidde den. Mere end én af vores besatte har tabt en kamp mod en dæmon; med vores fjender, der truer os - især i Zul'Gurub-hulen - er den kraft, en besat kan løslade mod vores fjender, ofret værd. Vores overlevelse afhænger af at knuse dem, der ville ødelægge os; Gurubashi-imperiets fald lærte os det.\n\nRejs til Zul'Gurub-hulen og skaf os de Kraftens Mønstre, vi har brug for. Gør du det, skal en værdifuld genstand fra den besatte være din.", p="Hentet Kraftens Mønstre fra Zul'Gurub-hulen? Mens vi vil tage den skjulte kraft fra disse genstande og gøre dem til vores egne, vil vi give dig din egen belønning i kraft, hvis du lykkes...", c="Godt gjort, <Name>. Kraftens Mønstre fra Zul'Gurub-hulen bør fungere som en påmindelse om spildt kraft. Gurubashierne var stærke på deres højdepunkt, men de lod sig fortære af den. En besat ved, at spillet de spiller minder meget om det, men den løsladte kraft er ofte præcis det, der er nødvendigt for overlevelse.\n\nBrug denne skulderkappe som en æret allieret af Sandalarerne... den vil tjene dig godt."},
  [8077] = {n="Kraftens Mønstre: Den Besattes Kapper", l="Bring Al'tadøm den Alseende en Urtids Håkkari Kosak. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nAl'tadøm den Alseende befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Det ultimative symbol på magt blandt stammen er den klædning, vi bærer i kamp. En besattes kapper har smeltet fint runestof og ødelæggende stærk magi sammen til ét stof. Kappens skikkelse siges at indgyde frygt i sindet hos alle, der ser den... især de dæmoner, den besatte til sidst vil dominere.\n\nFra Zul'Gurub-hulen skal du bringe mig et meget bestemt sæt Kraftens Mønstre. Det bliver svært... men din succes vil sikre dig en kappe til dig selv.", p="Kraftens Mønstre... er du vendt tilbage med dem? Først når vi har dem, deler vi det ultimative symbol på besat magt med dig, <Name>.", c="Imponerende - din sejr i Zul'Gurub-hulen har sikret os - ja, verden - at Hakar ikke vil sejre. Der kan komme en tid, hvor du står over for Blodguden direkte... og skulle det ske, så vid, at din ærefrygt er sikret blandt Sandalarstammen.\n\nÅh, og denne simple kappe burde også hjælpe lidt, tror jeg.\n\n<Al'tadøm blinker vidende til dig.>"},
  [8078] = {n="Kraftens Mønstre: Hævnerens Bælte", l="Bring Jyn'rokh Knuseren en Urtids Håkkari Bælte. Du skal også have et ry lig med eller større end Æret hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Den ultimative hævn venter i Zul'Gurub-hulen. Hakar må ikke rejse sig igen. Hakar ødelagde Gurubashi-imperiet indefra. Intet offer var nok. Trollene er kun en skygge af tidligere herlighed. Jeg ved, at det skyldes Hakar.\n\nBliv den hævner, du var skabt til at være. Hærg blandt ondskabens håndlangere. Zul'Gurub-hulen skal smage Sandalarnes hævn. Bring mig beviset i form af Kraftens Mønstre. Du vil modtage hævnerens bælte. Du vil modtage ægte magt.\n\nAfsted.", p="Har du bragt Kraftens Mønstre? Har du slået stammens fjender ned? Hakar må lære vredens hævner at kende!", c="Hævnerens vej er nu kendt for dig. Du har bragt ære til stammen. Du har bragt ære til dig selv. Du har bragt smerte til vores fjender.\n\nHævnerens bælte er din. Du er helt sikkert ved at blive ét med hævnerens vej."},
  [8079] = {n="Kraftens Mønstre: Hævnerens Brystplade", l="Bring Jyn'rokh Knuseren en Urtids Håkkari Kosak. Du skal også have et ry lig med eller større end Respekteret hos Sandalar-stammen.\n\nJyn'rokh Knuseren befinder sig på Yojamba-øen i Kvælerdorn-dalen.", d="Hævnerens symbol på magt er brystpladen. Den er smedet med stærk magi. Den betros kun dem, vi respekterer. Den er Sandalarnes symbol på hævn.\n\nAt blive hævner er at blive hævn. Tag de Kraftens Mønstre, vi har brug for, fra Zul'Gurub-hulen. Bring dem til os. Vi tager den magi, der er stjålet fra os. Vi får Hakars håndlangere til at betale. Vi belønner dig med hævnerens brystplade.\n\nAfsted. Vær vores hævn, <Name>.", p="Din tilstedeværelse betyder sejr? Har du Kraftens Mønstre? Fortæl mig om den hævn, du har vævet i dag!", c="Du skal respekteres for dine gerninger. Stammen belønner sine helte. Zul'Gurub-hulen har smagt Sandalarnes hævn som aldrig før.\n\nDine gerninger vil varsle andres gerninger, der kommer. De vil se op til dig som et tegn på ægte magt. De vil se op til dig som hævnen personificeret!"},
  [8080] = {n="Arathi-bækkenets Æresmærke!", l="Vind slaget om Arathi-bækkenet, skaf et Arathi-bækkenets Æresmærke, og bring det tilbage til Sergent Maclear ved Flygtningeodden.", d="Krig skal kæmpes med soldater, siger enhver soldat. De vil også sige, at et slag kæmpet med dårligt udstyr eller på en tom mave er tabt, før det begynder!\n\nDet er derfor, Arathi-bækkenet er vigtigt. Der er nøgleområder i bækkenet, der rummer essentielle ressourcer. Metaller, våben, mad, træ - alt det er nødvendigt, og alt kan vindes der.\n\nDet er det, jeg ønsker af dig, <Name>. Træd ind i Arathi-bækkenet, vind slaget ved at holde flere baser end fjenden, og vend tilbage til mig med et Æresmærke.", p="Har du Æresmærkerne, <Name>? Arator-ligaen kan ikke kæmpe et ordentligt slag uden dem...", c="Du har fået mærket! Godt klaret! Jeg sender ressourcerne til vores kvartermestre, som hurtigt kan fordele dem til vores tropper.\n\nTak, <Name>. Det er faktisk sådan, krige virkelig vindes - ved succesfulde missioner som den, du netop har gennemført."},
  [8101] = {n="Kajarøs Småsten", c="<Race>, småstenen, der sidder i rammen af denne talisman, kommer fra Bjerget Kajarø i Sydhavet. Bjerget Kajarø er et område plaget af uro - præget af voldsomme og ofte magiske vulkanudbrud.\n\nNår dit bånd med trollene fra Sandalar vokser, vokser også kraften i denne småsten. Udnyt småstenens kraft til at slå vores fjender ned. Vær som bjerget: Hurtig, eksplosiv, dødbringende..."},
  [8102] = {n="Kajarøs Småsten", p="Velkommen tilbage, <Class>. Jeg kan se, at småstenen har været meget i brug. Mange af vores fjender er faldet for dine oversanselige evner. Deres lidelse har været stor. Det er tid til, at jeg forstærker småstenens kraft. Giv den til mig.", c="Vær ustoppelig, som Kajarøs smeltende fronter."},
  [8103] = {n="Kajarøs Småsten", p="Håkkari frygter dig, <Name>. De taler om rædsler, som de troede kun deres ansigtsløse gud kunne begå. Du har brændt dem med Kajarøs kraft. De kender nu frygt to steder.\n\nDet er tid til at styrke småstenen yderligere. Giv mig talismanen.", c="Fortsæt din udryddelse af Zul'Gurub-hulens trolde. Hakar må se, at verden ikke vil bøje sig under hans ubøjelige vilje."},
  [8104] = {n="Juvelen fra Kajarø", p="Giv mig talismanen, <Name>. Jeg må vise dig noget.", c="<Al'tadøm knuser småstenen med en kraftig, usynlig kraft.>\n\nSer du? Småstenen er det, vi kalder en geode. Inde i småstenen sidder kraftige krystaller, som har badet i verdens latente energier. Ved at skære småstenen over på midten har jeg endelig givet dens fulde potentiale mulighed for at blive realiseret. Brug den til at lægge vores fjender øde."},
  [8105] = {n="Slaget om Arathi-bækkenet!", l="Angrib minen, savværket, smedjen og gården, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, slaget om Arathi-bækkenet er en kamp om ressourcer og territorium. Nøglepunkterne i området skal holdes og drives, for at vores styrker kan forsynes med tiltrængte råmaterialer og forsyninger. Jeg pålægger dig at angribe de punkter, der ligger længst fra vores Arathi-bækken-grund.\n\nAngrib gården, minen, savværket og smedjen, når fjenden kontrollerer dem. Find fjendens banner og riv det ned fra dets flagstang!\n\nNår du har gjort dette ved alle fire punkter, så vend tilbage til mig.", p="<Name>, du har endnu ikke angrebet de fire baser. Vend tilbage til mig, når dine mål er nået.", c="Jeg har modtaget rapporter om dine bedrifter i Arathi-bækkenet, <Name>. Godt gået! Med folk som dig, der slutter sig til kampene her, har jeg tro på, at vi en dag vil generobre vores hjemlande."},
  [8106] = {n="Kæsans Plet", c="Accepter denne talisman, <Class>. Accepter den, og brug dens kraft til at slå vores fælles fjender ned.\n\nVid, at du bærer en brik af historien om halsen. Kæsan var engang et stort territorium i Zandalar-imperiet. Ak, pletten fra kobold-handelsprinserne tvang mine stolte brødre og søstre ud.\n\nKæsan er nu hjemsted for kobold-hovedstaden Underminen; men vid, at der før pletten var storhed. Den dag i dag betragtes Kæsan stadig som helligt land for mit folk."},
  [8107] = {n="Kæsans Plet", p="Ære opnås blandt Zandalar-trollene, <Name>. Med ære følger belønning - venskab, alliance...\n\nGiv mig talismanen, så jeg kan forstærke dens kraft.", c="Træk fra mørket, <Class>. Omfavn skyggerne. Lad Kæsans Plet supplere dit mørke rodearbejde."},
  [8108] = {n="Kæsans Plet", p="Jeg er klar til dig, <Class>. Endnu en gang vil jeg forstærke din talisman. Jeg beder kun om, at du fortsætter med at udslette Hakar og hans håndlangere.\n\nGiv mig talismanen.", c="Det er kun gennem vores fælles indsats, at vi kan stoppe Sjælsflåeren."},
  [8109] = {n="Kæsans Ustoppelige Plet", p="Kald dine dæmoner frem, <Class>. Lad dem bade i energien fra Kæsans Plet. Befal dem på slagmarken! Decimér fjenden!\n\nJa... Tiden er kommet til at give Kæsans Plet den sidste forstærkning. Giv mig talismanen.", c="Flå kødet af deres lig. Se på, mens skyggerne opsluger Håkkarierne. Hent kraft fra deres frygt, <Class>. Lad Kæsans Plet forøge denne kraft..."},
  [8110] = {n="Fortryllet Tang fra Sydhavet", c="Se den her tang, mon? Den kommer fra Sydhavet. Vi tilsætter bare lidt mojo og lidt magi, og så får den de egenskaber, der passer bedst til dens ejer.\n\nDu er en <Class>, så det er nemt, mon. Bare vikl den om halsen og tænk på natur eller egern eller hvad det nu er, I folk kan lide."},
  [8111] = {n="Fortryllet Tang fra Sydhavet", p="Hej mon! Det er godt at se dig igen. Stammen taler om dit drab på Håkkarierne og alt det der. Molthor gav mig besked om at tilføje mere mojo til din talisman. Bare giv den her, så gør Majvikki den bedre.", c="Halsstykket er ikke til at ryge, mon! Du skal bruge det til at bekæmpe ondskab."},
  [8112] = {n="Fortryllet Tang fra Sydhavet", p="Hvordan er den talisman, mon? Det ser ud til, at det er tid til at tilføje lidt mere magi og mojo til dens blade. Den mangler lidt blomstring i sin visnen. Giv den her, så fikser Majvikki den helt.", c="Nu tager du de onde trolde i Zul'Gurb og viser dem, hvad dine naturkræfter kan, mon!"},
  [8113] = {n="Upåklagelig Fortryllet Tang fra Sydhavet", p="<Name>! Det er længe siden, jeg så dig. Vidste du, at Kong Rastakhan selv gav mig ordren om at tilføje den sidste bit mojo og magi til din talisman? Det er sandt, mon! Jeg ville ikke have troet det, hvis jeg ikke havde set det med mine egne øjne. Giv den her.", c="<Name> mon, det har været en god rejse. Bliv ved med at dræbe og undertrykke Hakar og hans håndlangere."},
  [8114] = {n="Kontrollér fire baser", l="Gå ind i Arathi-bækkenet, erobr og kontrollér fire baser på samme tid, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, du har ført slaget om Arathi-bækkenet ud til vores fjender og tjent stor ære på slagmarken. Du har vist os din værdi som <Class>, og du har vist vores fjender, at vi ikke vil bøje os for deres skurkagtighed!\n\nPå grund af din beviste værdi for os har jeg en svær opgave til dig. Jeg vil have dig til at tage og holde mindst fire af baserne i Arathi-bækkenet. Kan du gøre det, sikrer vi ikke blot kritiske ressourcer, vi viser også Horden vores overlegenhed!\n\nAf sted, <Name>, og held og lykke.", c="Meget godt arbejde, <Name>! En ivrig spejder kom til mig med en rapport om dine bedrifter. Vi i Arator-ligaen er meget glade!\n\nDu er hastigt ved at blive en lokal helt blandt soldaterne i Ligaen, og dagens bedrift beviser endnu en gang dit fremragende ry."},
  [8115] = {n="Kontrollér fem baser", l="Kontrollér 5 baser i Arathi-bækkenet på samme tid, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, at kæmpe om ressourcerne i Arathi-bækkenet er en blodig affære. Dine tjenester for Arator-ligaen er nødvendige, og de værdsættes.\n\nOg vi har endnu en opgave til dig.\n\nLigaen ønsker at lave et stærkt angreb mod Skænderne og deres besættelse af Arathi-bækkenet. Vi vil have dem drevet ud af hvert eneste strategiske punkt på slagmarken!\n\nDet bliver ikke let, men hvis nogen kan klare det, er det dig."},
  [8116] = {n="Vudress' Syn", c="Du og Majvikki har noget til fælles, mon. I er begge shamaner! Dog er Majvikki mere en mystiker, og du er mere en ynkelig amatør. Alligevel ved vi begge, hvad de store ånder bringer.\n\nSom gave giver jeg dig denne kugle, så du kan bære den om halsen. Kig dybt ind i den og se landsbyen Vudress i Sydhavet! Lad den løfte din ånd!"},
  [8117] = {n="Vudress' Syn", p="Gode nyheder, <Name>. Molthor synger dine ros for tiden. Han siger, at du er ved at blive en rigtig helt for Zandalar.\n\nHan siger også, at Majvikki skal pudse din kugle lidt mere! Giv den her, så Majvikki kan gøre synet klarere.", c="Vær på vagt over for de onde Håkkari-ånder, mon. Ærligt talt, de er uhyggelige."},
  [8118] = {n="Vudress' Syn", p="Sha-mon! Majvikki laver en joke!\n\n<Majvikki griner.>\n\nSå, du har brugt ånderne og elementerne mod vores fjender i Zul'Gurb, hva'? Ånderne være lovet!\n\nMajvikki vil gøre din kugle klarere. Giv den her, <Name>.", c="Kig nu på den, <Name>. Vudress træder tydeligere frem nu, ja? Lad den primitive kraft strømme gennem dig, mon."},
  [8119] = {n="Det Uplettede Syn af Vudress", p="<Majvikki peger på din talisman.>\n\nSe på den, <Name>! Den er blevet levende. Ånderne danser om kuglen.\n\nGiv den til Majvikki, så hun kan lave én sidste justering.", c="En dag, <Name>, vil du kunne bruge denne kugle til at kommunikere direkte med mig. Når denne kamp mod Hakar er forbi, og Majvikki tager hjem. Lad os kalde på ånderne og bede dem om, at den dag må komme snart."},
  [8120] = {n="Slaget om Arathi-bækkenet!", l="Angrib Arathi-bækkenets mine, savværk, smedje og stald, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="Som du sikkert har hørt, sender Arator-ligaen store mængder tropper ind i Arathi-bækkenet. Ivrige efter mad og forsyninger er disse Alliance-tosser fast besluttet på at tage og kontrollere de rige ressourcer dér. Vi må vise dem, at Arathi aldrig igen vil være et hjem for mennesker!\n\nGå til Arathi-bækkenet og angrib minen, savværket, smedjen og stalden. Riv fjendens banner ned, og erklær disse territorier for Horden.\n\nAf sted, <Name>. Vend tilbage og rapportér til mig, når denne opgave er fuldført.", c="En Skænder-spejder kom til mig med en rapport om din succes, <Name>. Godt gået.\n\nSom du vil lære, skal vi være årvågne og knuse ethvert forsøg på Alliance-ekspansion for at vinde slaget om Arathi-bækkenet. Gør dette, og vores sejr her er sikret."},
  [8121] = {n="Tag fire baser", l="Hold fire baser på samme tid i Arathi-bækkenet, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="<Name>, mens kampene om Arathi-bækkenet raser, er nyheden om dine handlinger nået mange ører. Du er højt anset blandt os, hvilket giver mig tillid til, at du vil klare den mission, jeg nu har til dig.\n\nDet er tid til at sende et budskab til Arator-ligaen. Vi må vise dem, at deres besiddelser i Arathi-bækkenet er skrøbelige og hurtigt tabt. Det vil vi vise dem ved at holde fire strategiske punkter i Arathi-bækkenet på én gang.\n\nLykkes du med dette, <Name>, og vinder stor respekt blandt Skænderne."},
  [8122] = {n="Tag fem baser", l="Hold fem baser i Arathi-bækkenet på samme tid, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="Det er svært at se, så dybt er vi inde i konflikten, men vores spioner melder om en svækkelse i Arator-ligaens beslutsomhed. Vi må udnytte dette vindue og slå et brutalt slag mod dem! Vend tilbage til Arathi-bækkenet og kast dig over vores fjender. Forband dem, dræb dem og kontrollér alle fem strategiske baser! Send deres soldater skrigende og blødende fra frontlinjen, med historier om din grusomhed på deres pivende læber.\n\nGør dette, og vind en stor sejr for Skænderne."},
  [8123] = {n="Skær Arathors forsyningslinjer over", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og returner det til Dødsstalker Mortus i Hammerfald.", d="Arator-ligaen sparer ingen udgifter i sin bestræbelse på at generobre Arathi. De, og alle Alliancens racer, strømmer nu til denne fjerne region, fast besluttede på at udvide deres greb fra Flygtningeodden. Vi må stoppe dem, og den bedste måde at stoppe dem på er at tage deres forsyninger.\n\nDu kan hjælpe os, <Name>. Gå ind i Arathi-bækkenet, kendt for sine rige miner, frugtbare land og dygtige håndværkere. Erobr og kontrollér hver base, du kan, vind slaget, og vend tilbage til mig med det Æresmærke, du opnår.", p="Hvad er der, <Race>? Har du æresmærkerne? Gå tilbage til Arathi-bækkenet, slå Alliance-utøjet ihjel og tag dets ressourcer i besiddelse for Den Mørke Dame!", c="<Dødsstalker Mortus smiler>\n\nEndnu et afgørende slag er blevet påført vores fjender, <Name>. Takket være dine bedrifter vil Arathi-bækkenet snart blive grebet af Skænderne."},
  [8141] = {n="Zandalarisk Skyggetalisman", c="Du skrider hurtigt frem, unge <Class>. Måske er det tid til at indvie dig i Skyggernes Ali'kh - Zandalari for Dødens Hånd. I tusinder af år har vi spillet rollen som snigmorder for Zandalar-imperiet. For længe har vi siddet passivt og ladet Håkkarierne vokse i styrke. Endnu en gang står vi over for Hakar, men denne gang uden støtte fra en samlet <Race>-front. Det er dig og dine allierede, der må hjælpe med at besejre Blodguden og hans håndlangere!\n\nBær denne talisman, og lad den hjælpe dig på dine rejser."},
  [8142] = {n="Zandalarisk Skyggetalisman", p="Imponerende, <Name>. Du har en gave til at dræbe, som jeg ikke har sanset hos nogen anden i mange år. Selv Molthor er klar over det arbejde, du har udført for Zandalar. Det er tid til at forstærke din talisman yderligere. Giv den til mig.", c="Der er kun én forstærkning tilbage, der kan lægges på talismanen, <Class>. Når tiden er rigtig, vil jeg anvende den."},
  [8143] = {n="Zandalarisk Skyggetalisman", p="Jeg fornemmer, at du har påført Håkkarierne utallige dødsfald, <Name>. Du bærer lugten af deres mojo.\n\nJeg antager, at skyggetalismanen har hjulpet med udrensningen? Giv den til mig, og lad mig forstærke dens kraft.", c="En snigmorder af din kaliber bør holdes på god afstand. Dine fjender må lære respekt! Det får du, når fjenden ser glimtet fra Dødens Hånd - alt for sent..."},
  [8144] = {n="Zandalarisk Skyggemestringstalisman", p="Den higer efter at vokse, <Name>. Talismanen har suget til sig alt, hvad du har gjort. De tusindvis af trollekroppe, der ligger spredt over Zul'Gurb, har næret dens kraft. Giv den til mig, så laver jeg den sidste forstærkning.", c="Dette er sidste gang, vi taler under Skyggernes Ali'kh' beskyttelse. Du ved alt, hvad du skal vide. Tag talismanen og fortsæt dit drab. Hakar må aldrig få lov til at forlade Zul'Gurb."},
  [8145] = {n="Malstrømmens Ranke", c="Blandt zandalarerne er erhvervet som jæger højt æret. Vores største jægere rejser til kanten af Malstrøm for at bevise deres beslutsomhed.\n\nFra havets hjerte trækker de strenge af tang, kendt som Malstrømsranker. Tangen væves derefter ind i en talisman, der er fortryllet til at forbedre deres præcision og kraft.\n\nJeg giver dig nu en enkelt væv af Malstrømmens Ranke. Efterhånden som dit bånd til Zandalar vokser, vil jeg væve mere kraft ind i talismanen."},
  [8146] = {n="Malstrømmens Ranke", p="Ah, <Name>, det er godt at lugte dig igen.\n\n<Falthør flirer.>\n\nDu må undskylde min sans for humor. Den kan til tider være yderst ildelugtende.\n\nJeg fornemmer, at du har voldt vores fjender stor kval. Hakars styrker råber dit navn i vrede. Det er yderst fortrinligt.\n\nDu har fortjent endnu en flettet snor til din amulet. Giv den til mig.", c="Lad dem søge bod ved enden af din ammunition."},
  [8147] = {n="Malstrømmens Ranke", p="Ah, <Name>, det er godt at lugte dig igen.\n\n<Falthør flirer.>\n\nDu må undskylde min sans for humor. Den kan til tider være yderst ildelugtende.\n\nJeg fornemmer, at du har voldt vores fjender stor kval. Hakars styrker råber dit navn i vrede. Det er yderst fortrinligt.\n\nDu har fortjent endnu en flettet snor til din amulet. Giv den til mig.", c="Lad dem søge bod ved enden af din ammunition."},
  [8148] = {n="Malstrømmens Vrede", p="Mølthor bringer bud fra Konge Rastakhan, <Name>. Hoffet er yderst imponeret over din decimering af Hakkari-styrkerne. Jeg skal tildele dig den sidste flettede snor til din amulet. Giv den til mig.", c="Din rejse har kun lige begyndt, unge <Class>. Måske besøger du en dag Malstrømmen og kigger ind i verdens hjerte.\n\nJeg ønsker dig styrke og udholdenhed!"},
  [8149] = {n="At Ære en Helt", l="Rejs til Uthers Grav i Vestpestlandene og brug Uthers Hyldest ved hans statue, og vend derefter tilbage til Wagner Hammerslag uden for Jernsmede, før Høstfestivalen er forbi.", d="Under Azeroths Høstfestival takker vi helte for de ofre - i nogle tilfælde de ultimative ofre - de har bragt på vores vegne. Alliancen anerkender mange helte, men ingen fortæller en mere tragisk historie end Uther Lysbringer.\n\nHjælp os med at ære Uther ved at bringe denne gave til hans grav i Vestpestlandene. Læg den ved hans statue, og vend derefter tilbage til mig. Jeg er kun her til festivalens afslutning, så spild ikke tid på at give Uther hans hyldest.", p="Har du gjort turen til Uthers grav og lagt hyldesten der?\n\nDet kan være en farlig rejse for mindre erfarne eventyrere; en sikrere måde at rejse derhen på, relativt set, kan være at rejse nordpå fra floden, der løber gennem Bakkebrad, ind i Pestlandene. Den strømmer fra en sø, der grænser op til Sorgbakken; rejs vestpå op gennem bakkerne og hold dig væk fra den nærliggende grav... en der er hærget af Svøben.", c="Han var en helt blandt helte, Uther var. Jeg kan ikke engang forestille mig den kval, han må have følt, da Arthæus - hans største elev og en han elskede som sin egen søn - forrådte hele menneskeheden. Alligevel rejste han sig for at forsøge at stoppe Arthæus, og for det vil han for evigt blive husket som en sand paladin. Hans kamp var til den bitre ende, og han tænkte kun på dem, han måske kunne redde.\n\nTak, <Name>. Du har i dag hyldet en stor helt og ædret hans ånd og Høstfestivalens ånd."},
  [8150] = {n="At Ære en Helt", l="Rejs til Groms Monument i Dæmonfald-kløften i Askedalen og brug Groms Hyldest ved monumentets fod. Vend tilbage til Javnir Næsestak uden for Orgrimgrad, før Høstfestivalen er forbi.", d="Under Azeroths Høstfestival takker vi helte for de ofre - i nogle tilfælde de ultimative ofre - de har bragt på vores vegne. Horden anerkender mange helte, men ingen eksemplificerer styrke og offer mere end Grom Helskrig.\n\nHjælp os med at ære Grom ved at bringe denne gave til hans monument i Dæmonfald-kløften i Askedalen. Læg den ved foden, og vend derefter tilbage til mig. Jeg er kun her til festivalens afslutning, så spild ikke tid på at give Grom hans hyldest.", p="Har du gjort turen til Groms monument og lagt hans hyldest der?\n\nStedet hvor monumentet står, er stadig berørt af Brændende Legions fordærv. Hvis du er mindre erfaren i eventyrernes veje, så vær på vagt, når du nærmer dig monumentet.", c="Groms fulde navn - Grummash - betyder \"Kæmpens Hjerte\"; det krævede det og mere at stå alene mod Mannorot. Jeg synes, Krigshøvdingen sagde det bedst, da forbandelsen over orkerne begyndte og endte med Grom. Det passer, at Groms offer - og måske forløsning - ville blive kilden, hvorfra Horden flyder i dag.\n\nTak, <Name>. Du har i dag hyldet en stor helt og ædret hans ånd og Høstfestivalens ånd."},
  [8151] = {n="Jægerens Amulet", l="Tal med Ogtink i Azsyra.", d="Ogtink fra Azsyra har udsendt et kald til erfarne jægere som dig selv. Han er en pelsbolg-jæger, der har forladt sin stamme for at hjælpe Cenarion-kredsen. Hans lærdomme er ment til at berige visdommen hos andre, der deler hans håndværk, og lede dem mod at opretholde balancen. Du gør klogt i at tale med ham.\n\nOgtink holder til oppe på klipperne i Azsyra, nordøst for Ruinerne af Eldarath.", c="Det er ikke længere mit formål at jage, men at lære jægeren. Det er det, skæbnen har givet mig.\n\nFremstil sammen med mig en jægerfortryllelse - en samling trofæer fra faldne bytte, som vil minde dig om dine tidligere prøvelser og triumfer. Til sidst beholder jeg fortryllelsen, men belønner dig med noget andet."},
  [8153] = {n="Løbergevirer", l="Bring et par Perfekte Løbergevirer til Ogtink i Azsyra. Ogtink holder til oppe på klipperne nordøst for Ruinerne af Eldarath.", d="Løberen bærer de mægtigste gevirer i de kendte lande. Sådanne gevirer bruges til at forsvare løberen, idet den stanger en angriber og ofte beskadiger spidserne. Perfekte, naturlige gevirer er tegnet på et dyrs ånd med overlegen selvtillid.\n\nAt bære sådanne gevirer vil give dig den samme selvtillid.\n\nJag mosshov-løberen, find de perfekte gevirer og bring dem til mig.", p="Har du fundet gevirerne?", c="Du må have skarpt blik og stor tålmodighed for at have skaffet disse. Godt gået."},
  [8154] = {n="Arathi-bækkenets Æresmærke!", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Sergent Maclear i Flygtningeodden.", d="Krig må udkæmpes med soldater, siger enhver soldat dig. De vil også sige, at et slag udkæmpet med dårligt udstyr eller på en tom mave er tabt, før det begynder!\n\nDet er derfor, Arathi-bækkenet er vigtigt. Der findes nøgleområder i bækkenet, der rummer væsentlige ressourcer. Metaller, våben, mad, tømmer - alt er nødvendigt, og alt kan indhentes der.\n\nDet er, hvad jeg vil have fra dig, <Name>. Gå ind i Arathi-bækkenet, vind slaget ved at holde flere baser end fjenden, og vend tilbage til mig med et Æresmærke.", p="Har du Æresmærkerne, <Name>? Arator-ligaen kan ikke udkæmpe et anstændigt slag uden dem...", c="Du fik mærket! Godt gået! Jeg sender ressourcerne til vores kvartermestre, som hurtigt kan fordele dem til vores tropper.\n\nTak, <Name>. Det er netop vellykkede missioner som din, der virkelig vinder krige."},
  [8155] = {n="Arathi-bækkenets Æresmærke!", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Sergent Maclear i Flygtningeodden.", d="Krig må udkæmpes med soldater, siger enhver soldat dig. De vil også sige, at et slag udkæmpet med dårligt udstyr eller på en tom mave er tabt, før det begynder!\n\nDet er derfor, Arathi-bækkenet er vigtigt. Der findes nøgleområder i bækkenet, der rummer væsentlige ressourcer. Metaller, våben, mad, tømmer - alt er nødvendigt, og alt kan indhentes der.\n\nDet er, hvad jeg vil have fra dig, <Name>. Gå ind i Arathi-bækkenet, vind slaget ved at holde flere baser end fjenden, og vend tilbage til mig med et Æresmærke.", p="Har du Æresmærkerne, <Name>? Arator-ligaen kan ikke udkæmpe et anstændigt slag uden dem...", c="Du fik mærket! Godt gået! Jeg sender ressourcerne til vores kvartermestre, som hurtigt kan fordele dem til vores tropper.\n\nTak, <Name>. Det er netop vellykkede missioner som din, der virkelig vinder krige."},
  [8156] = {n="Arathi-bækkenets Æresmærke!", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Sergent Maclear i Flygtningeodden.", d="Krig må udkæmpes med soldater, siger enhver soldat dig. De vil også sige, at et slag udkæmpet med dårligt udstyr eller på en tom mave er tabt, før det begynder!\n\nDet er derfor, Arathi-bækkenet er vigtigt. Der findes nøgleområder i bækkenet, der rummer væsentlige ressourcer. Metaller, våben, mad, tømmer - alt er nødvendigt, og alt kan indhentes der.\n\nDet er, hvad jeg vil have fra dig, <Name>. Gå ind i Arathi-bækkenet, vind slaget ved at holde flere baser end fjenden, og vend tilbage til mig med et Æresmærke.", p="Har du Æresmærkerne, <Name>? Arator-ligaen kan ikke udkæmpe et anstændigt slag uden dem...", c="Du fik mærket! Godt gået! Jeg sender ressourcerne til vores kvartermestre, som hurtigt kan fordele dem til vores tropper.\n\nTak, <Name>. Det er netop vellykkede missioner som din, der virkelig vinder krige."},
  [8160] = {n="Skær Arator-forsyningslinjerne over", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Dødsstalker Mortus i Hammerfald.", d="Arator-ligaen sparer ingen udgifter i deres træk for at generobre Arathi. De, og alle Alliancens racer, strømmer nu til denne fjerne region, fast besluttet på at udvide deres greb fra Flygtningeodden. Vi må stoppe dem, og den bedste måde at stoppe dem på er at tage deres forsyninger.\n\nDu kan hjælpe os, <Name>. Gå ind i Arathi-bækkenet, kendt for sine rige miner, frugtbare land og dygtige håndværkere. Indtag og kontrollér hver eneste base, du kan, vind slaget, og vend tilbage til mig med det Æresmærke, du får.", p="Hvad er der, <Race>? Har du Æresmærkerne? Tag tilbage til Arathi-bækkenet, slå Alliancens skadedyr ihjel og tag dets ressourcer i besiddelse for Den Mørke Dame!", c="<Dødsstalker Mortus smiler>\n\nEndnu et afgørende slag er blevet ført mod vores fjender, <Name>. Takket være dine bedrifter vil Arathi-bækkenet snart blive overtaget af Skænderne."},
  [8161] = {n="Skær Arator-forsyningslinjerne over", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Dødsstalker Mortus i Hammerfald.", d="Arator-ligaen sparer ingen udgifter i deres træk for at generobre Arathi. De, og alle Alliancens racer, strømmer nu til denne fjerne region, fast besluttet på at udvide deres greb fra Flygtningeodden. Vi må stoppe dem, og den bedste måde at stoppe dem på er at tage deres forsyninger.\n\nDu kan hjælpe os, <Name>. Gå ind i Arathi-bækkenet, kendt for sine rige miner, frugtbare land og dygtige håndværkere. Indtag og kontrollér hver eneste base, du kan, vind slaget, og vend tilbage til mig med det Æresmærke, du får.", p="Hvad er der, <Race>? Har du Æresmærkerne? Tag tilbage til Arathi-bækkenet, slå Alliancens skadedyr ihjel og tag dets ressourcer i besiddelse for Den Mørke Dame!", c="<Dødsstalker Mortus smiler>\n\nEndnu et afgørende slag er blevet ført mod vores fjender, <Name>. Takket være dine bedrifter vil Arathi-bækkenet snart blive overtaget af Skænderne."},
  [8162] = {n="Skær Arator-forsyningslinjerne over", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Dødsstalker Mortus i Hammerfald.", d="Arator-ligaen sparer ingen udgifter i deres træk for at generobre Arathi. De, og alle Alliancens racer, strømmer nu til denne fjerne region, fast besluttet på at udvide deres greb fra Flygtningeodden. Vi må stoppe dem, og den bedste måde at stoppe dem på er at tage deres forsyninger.\n\nDu kan hjælpe os, <Name>. Gå ind i Arathi-bækkenet, kendt for sine rige miner, frugtbare land og dygtige håndværkere. Indtag og kontrollér hver eneste base, du kan, vind slaget, og vend tilbage til mig med det Æresmærke, du får.", p="Hvad er der, <Race>? Har du Æresmærkerne? Tag tilbage til Arathi-bækkenet, slå Alliancens skadedyr ihjel og tag dets ressourcer i besiddelse for Den Mørke Dame!", c="<Dødsstalker Mortus smiler>\n\nEndnu et afgørende slag er blevet ført mod vores fjender, <Name>. Takket være dine bedrifter vil Arathi-bækkenet snart blive overtaget af Skænderne."},
  [8166] = {n="Slaget om Arathi-bækkenet!", l="Angrib minen, savværket, smeden og gården, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, slaget om Arathi-bækkenet er et slag om ressourcer og territorium. Nøglepunkterne i området skal holdes og drives for at forsyne vores styrker med tiltrængte råmaterialer og forsyninger. Jeg pålægger dig at angribe de punkter, der ligger længst fra vores base i Arathi-bækkenet.\n\nAngrib gården, minen, savværket og smeden, når de er kontrolleret af fjenden. Find fjendens banner og riv det ned fra sin flagstang!\n\nNår du har gjort dette ved alle fire punkter, vend tilbage til mig.", c="Jeg har modtaget rapporter om dine bedrifter i Arathi-bækkenet, <Name>. Godt gået! Med dem som dig, der slutter sig til kampene her, har jeg tro på, at vi en dag vil generobre vores hjemlande."},
  [8167] = {n="Slaget om Arathi-bækkenet!", l="Angrib minen, savværket, smeden og gården, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, slaget om Arathi-bækkenet er et slag om ressourcer og territorium. Nøglepunkterne i området skal holdes og drives for at forsyne vores styrker med tiltrængte råmaterialer og forsyninger. Jeg pålægger dig at angribe de punkter, der ligger længst fra vores base i Arathi-bækkenet.\n\nAngrib gården, minen, savværket og smeden, når de er kontrolleret af fjenden. Find fjendens banner og riv det ned fra sin flagstang!\n\nNår du har gjort dette ved alle fire punkter, vend tilbage til mig.", c="Jeg har modtaget rapporter om dine bedrifter i Arathi-bækkenet, <Name>. Godt gået! Med dem som dig, der slutter sig til kampene her, har jeg tro på, at vi en dag vil generobre vores hjemlande."},
  [8168] = {n="Slaget om Arathi-bækkenet!", l="Angrib minen, savværket, smeden og gården, og vend derefter tilbage til Feltmarskal Oslys i Flygtningeodden.", d="<Name>, slaget om Arathi-bækkenet er et slag om ressourcer og territorium. Nøglepunkterne i området skal holdes og drives for at forsyne vores styrker med tiltrængte råmaterialer og forsyninger. Jeg pålægger dig at angribe de punkter, der ligger længst fra vores base i Arathi-bækkenet.\n\nAngrib gården, minen, savværket og smeden, når de er kontrolleret af fjenden. Find fjendens banner og riv det ned fra sin flagstang!\n\nNår du har gjort dette ved alle fire punkter, vend tilbage til mig.", c="Jeg har modtaget rapporter om dine bedrifter i Arathi-bækkenet, <Name>. Godt gået! Med dem som dig, der slutter sig til kampene her, har jeg tro på, at vi en dag vil generobre vores hjemlande."},
  [8169] = {n="Slaget om Arathi-bækkenet!", l="Angrib Arathi-bækkenets mine, savværk, smed og Stabil, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="Som du utvivlsomt har hørt, sender Arator-ligaen store antal tropper ind i Arathi-bækkenet. Ivrige efter mad og forsyninger er disse Alliance-tosser fast besluttet på at tage og kontrollere de rige ressourcer dér. Vi må vise dem, at Arathi aldrig igen må være et hjem for mennesker!\n\nGå til Arathi-bækkenet og angrib minen, savværket, smeden og stabilerne. Riv fjendernes banner ned, og erklær disse områder for Horden.\n\nAf sted, <Name>. Rapportér tilbage til mig, når opgaven er løst.", c="En Skænder-spejder kom til mig med en rapport om din succes, <Name>. Godt gået.\n\nSom du vil lære, skal vi for at vinde slaget om Arathi-bækkenet altid være på vagt og knuse ethvert forsøg på Alliancens udvidelse. Gør du dette, er vores sejr her sikret."},
  [8170] = {n="Slaget om Arathi-bækkenet!", l="Angrib Arathi-bækkenets mine, savværk, smed og Stabil, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="Som du utvivlsomt har hørt, sender Arator-ligaen store antal tropper ind i Arathi-bækkenet. Ivrige efter mad og forsyninger er disse Alliance-tosser fast besluttet på at tage og kontrollere de rige ressourcer dér. Vi må vise dem, at Arathi aldrig igen må være et hjem for mennesker!\n\nGå til Arathi-bækkenet og angrib minen, savværket, smeden og stabilerne. Riv fjendernes banner ned, og erklær disse områder for Horden.\n\nAf sted, <Name>. Rapportér tilbage til mig, når opgaven er løst.", c="En Skænder-spejder kom til mig med en rapport om din succes, <Name>. Godt gået.\n\nSom du vil lære, skal vi for at vinde slaget om Arathi-bækkenet altid være på vagt og knuse ethvert forsøg på Alliancens udvidelse. Gør du dette, er vores sejr her sikret."},
  [8171] = {n="Slaget om Arathi-bækkenet!", l="Angrib Arathi-bækkenets mine, savværk, smed og Stabil, og vend derefter tilbage til Dødsmester Dwire i Hammerfald.", d="Som du utvivlsomt har hørt, sender Arator-ligaen store antal tropper ind i Arathi-bækkenet. Ivrige efter mad og forsyninger er disse Alliance-tosser fast besluttet på at tage og kontrollere de rige ressourcer dér. Vi må vise dem, at Arathi aldrig igen må være et hjem for mennesker!\n\nGå til Arathi-bækkenet og angrib minen, savværket, smeden og stabilerne. Riv fjendernes banner ned, og erklær disse områder for Horden.\n\nAf sted, <Name>. Rapportér tilbage til mig, når opgaven er løst.", c="En Skænder-spejder kom til mig med en rapport om din succes, <Name>. Godt gået.\n\nSom du vil lære, skal vi for at vinde slaget om Arathi-bækkenet altid være på vagt og knuse ethvert forsøg på Alliancens udvidelse. Gør du dette, er vores sejr her sikret."},
  [8181] = {n="Konfrontér Yeh'kinja", l="Tal med Yeh'kinja.", d="Mine undersøgelser af Mosh'aru-tavlerne bringer dystre nyheder, <Name>. Hakars sande skikkelse, guden selv, kan genfødes gennem det samme æg, hvori du fangede ham. Yeh'kinja fortalte dig, at det skulle indeholde hans ondskab, men det er for at genskabe den! Trolden har ført dig vild!\n\nGå til Yeh'kinja og kræv ægget af ham. Bed om, at det ikke er for sent at stoppe Hakars tilbagevenden!", c="Så du har talt med den gamle dværg Jernstøvle og afdækket de tabte Mosh'aru-tavler, har du? Den blandende prospektør...\n\nUanset. Det er for sent at redde denne verden. Hakar er blevet genfødt, og vokser allerede i magt... dybt i den gamle trolde-kongerige Zul'Grumle! Han er kommet! Og han vil herske i blod og rædsel!\n\nTak, <Name>. Din hjælp har fremskyndet Sjælsflåerens tilbagevenden!"},
  [8182] = {n="Rastakhans Hånd", l="Tal med Mølthor i Kvælerdorn.", d="<Name>, vores værste frygt er indtruffet. Legenden fortæller om Sjælsflåeren, der hersker over den gamle trolde-verden gennem ondskab og rædsel, og hans magt var absolut. Hvis han ikke kan stoppes nu, kan hans nye herredømme brede sig over hele Azeroth!\n\nDer er en kontingent af zandalariske trolde, der måske kan hjælpe os med at dæmme op for dette mørkes tidevand. De har slået lejr på Yojamba-øen, ud for kysten af Kvælerdorn, vest for ruinerne af Zul'Kunde. Tal med deres leder, Mølthor, og bed om, at han ved, hvordan man besejrer Hakar.", c="Du blev sendt af prospektøren Jernstøvle? Hans slags er kloge, og endnu klogere er de til at bringe dig til mig, for jeg og de zandalariske trolde kender måske en måde at besejre Sjælsflåeren.\n\nTal med trolden på denne ø, lyt til deres ord, og forbered dig, <Name>, for opgaven foran dig er gennemblødt af blod."},
  [8183] = {n="Hakars Hjerte", l="Bring Hakars Hjerte til Mølthor på Yojamba-øen.", d="Hakars Hjerte brænder indefra. Selvom Sjælsflåeren er besejret, består kernen af hans magt stadig i dette forbandede organ.", p="<Name>, ondskabens stank omgiver dig. Er du blevet forbandet af Sjælsflåeren?", c="Ah, Hakars Hjerte. Så Sjælsflåeren er blevet dræbt! Vores verden er reddet!\n\n<Name>, din tjeneste for os kan ikke overvurderes. Du er virkelig en helt i dette rige!"},
  [8193] = {n="Mesterfisker", p="I dag mellem kl. 14 og 16 har vi en konkurrence om at afgøre, hvem der er den største fisker af dem alle! Bare vær DEN FØRSTE PERSON til at bringe mig 40 Lækkerfisk, fisket fra Lækkerfisk-stimerne langs kysten af Kvælerdorn, før nogen anden gør det, så bliver du udråbt til Mesterfisker!\n\nHvis du ikke er den første person til at bringe mig 40 fisk, vil min lærling her stadig belønne dig med penge for hver 5 Lækkerfisk, du bringer hende.\n\nOg lad være med at dvæle, for Lækkerfisk fordærves hurtigt!", c="Skynd dig og aflever dem, hvis du vil udråbes til Mesterfisker! Jeg har stået her i TIMER uden noget at spise! Læg de fisk over her!"},
  [8201] = {n="En Samling Hoveder", l="Snor 5 Kanalisatorens hoveder, og aflever derefter Samlingen af Trolde-hoveder til Eksjal på Yojamba-øen.", d="Det er sandt. Hakar bor nu i Zul'Grumle og bader i vores guders kraft. Forhekset ypperstepræster kanaliserer nu energierne fra vores helligste guddomme ind i Sjælsflåeren, som snart vil have en styrke, der overgår ethvert væsen på Azeroth. Han må stoppes!\n\nTag denne hellige snor, og træk gennem den hovederne af de ypperstepræster, der står for at kanalisere vores guders energi.\n\nNår du har gjort dette, vend tilbage til mig.", p="Har du samlingen af hoveder, <Name>? Vi må stoppe Hakar i at vinde mere magt!", c="Du fik hovederne! Du har standset plyndringen af vores guders magt og svækket Hakar!\n\nDine handlinger er virkelig heroiske, <Name>. Må hovederne af disse troldetrælle bede dig om nåde længe efter deres blod er løbet koldt."},
  [8227] = {n="Nats Målebånd", l="Returnér Nats Målebånd til Nat Lommetyv i Støvsumpen.", d="Blandt de knuste fiskeagn og fiskeudstyr ligger et oprullet, silkeagtigt målebånd. Fastgjort til båndet er en mærkat, der lyder:\n\n\"Nat Lommetyv, Støvsumpen.\"", p="Hej der, knægt. Er du her for at fiske?", c="Hvorfor, du fandt mit yndlingsmålebånd! Jeg elsker dette bånd! Jeg har målt nogle af de største fisk, jeg nogensinde har fanget med det...\n\nMen jeg tabte dette bånd i Zul'Grumle... har du været i Zul'Grumle? Så du den berømte Gahz'knipsen?\n\nNå... vil du gerne fange ham?"},
  [8231] = {n="Bølgehamring", l="Bring 6 Bølgehamrer-skæl til Ogtink i Azsyra. Ogtink holder til på klipperne nordøst for Ruinerne af Eldarath.", d="Bølgehamreren er et amfibisk udyr, der kun lever her i Azsyra. De er kraftfulde og sejlivede.\n\nDe seje, reflekterende skæl fra en bølgehamrer spejler jægerens styrke.\n\nSpor og jag bølgehamrere langs Azsyras kyst, og bring mig deres skæl.", p="Har du haft succes?", c="Bølgehamrerne er ikke let at besejre, endnu mindre i deres vandige omgivelser.\n\nDu har bevist, at du er klar til at jage endnu farligere bytte."},
  [8232] = {n="Den Grønne Drake", l="Bring Morfazs Tand til Ogtink i Azsyra. Ogtink holder til på klipperne nordøst for Ruinerne af Eldarath.", d="Nu sætter jeg dig på en farlig jagt for at slå den grønne drake, Morfaz, ihjel og bringe mig hans tand. Morfaz holder til dybt inde i Det Sunkne Tempel, hvis indgang ligger i Sorgernes Sump.\n\nHvis du vil besejre ham, må du ikke gå alene. Denne drake er mange en fjende -- søg andre, der også vil ødelægge ham.\n\nDrakens tand symboliserer den styrke, en jæger finder i andres selskab. Bring den til mig, så har du lært meget.", p="Jeg ser visdom i dine øjne, <Name>. Er din jagt slut?", c="Du har lært de gamle veje, <Name>, og for det tilbyder jeg dig en gave fra mine dage som <Class>."},
  [8233] = {n="En Simpel Anmodning", l="Tal med Herre Jorak Ravnehold på Ravnehold-herregården.", d="Herre Jorak Ravnehold har bedt om din tilstedeværelse. Sagen er hemmelig, og jeg kan ikke sige mere.\n\nRavnehold-herregården ligger i Hillsbrad-forbjergene -- led efter en sti i bjergene nordvest for Dørnhold-fæstningen.", c="Velkommen, velkommen, velkommen! Sæt dig, <Name>, og lad os drøfte en simpel sag.\n\nDu ser, <Name>, at jeg for nylig har mistet noget kært for mig, og for at sige det lige ud, vil jeg have det tilbage for enhver pris. Der er noget i den til dig, bare rolig med det! Åh ja, noget rigtig pænt.\n\nNu, hvad siger du, <Name>... har du lyst til lidt eventyr?"},
  [8234] = {n="Forseglet Azurblå Taske", l="Hent den forseglede azurblå taske fra Tømmergab-shamanen i Azsyra. Tag derefter tasken til Ærkemager Xylen, som også findes i Azsyra.", d="Først og fremmest. Det, jeg har mistet, er en lille blå taske, hvis indhold er en privat sag.\n\nGid du ikke gider jagte tyvene, for de er allerede døde. Det, vi ved, er, at tossedumperne ikke kunne få tasken op, så de solgte den til en eller anden tømmergab-shaman i Azsyra som et helligt relik. Snedigt.\n\nJeg har brug for, at du rejser til Azsyra og henter den fra shamanen med finesse... eller magt. Held og lykke med den første metode, vil jeg vædde på. Når den er i din besiddelse, så tag den med til Ærkemager Xylen.", p="Kender jeg dig?", c="Jeg ser, du har Herre Ravnehold's taske. Hvorfor sagde du det ikke, knægt?"},
  [8235] = {n="Kodede Fragmenter", l="Bring 10 kodede fragmenter til Ærkemager Xylen i Azsyra.", d="Herre Ravnehold har bedt os begge om en tjeneste. Han ønsker at fjerne fortryllelsen fra denne taske.\n\nDesværre blev nogle af mine bøger om afmagi for nylig taget fra mig og smadret af vildmænd. Resterne af mine bøger er stadig værdifulde for mig.\n\nHvis du kan bringe mig nok af de kodede fragmenter, kan jeg sætte dem sammen igen. Din bedste chance er at dræbe skovslimer, for de har en tendens til at samle næsten alt op. Du finder dem i det nordøstlige Azsyra.", p="Har du fundet nok fragmenter til at fortsætte mit arbejde?", c="Det ser ud til, at du har samlet nogle af de bedre fragmenter. Måske er du alligevel ikke værdiløs."},
  [8236] = {n="Den Azurblå Nøgle", l="Returner den Azurblå Nøgle til Herre Jorak Ravnehold.", d="Det vil tage lidt tid at tyde fragmenterne og fjerne fortryllelsen. Når jeg er færdig, leverer jeg personligt tasken til Herre Ravnehold.\n\nDer er stadig spørgsmålet om nøglen, som siges at være i besiddelse af en grøn drake ved navn Morfaz. Drakken har gjort sit hjem dybt i Det Sunkne Tempel, hvis indgang ligger i Sorgernes Sump.\n\nIndsaml dine venner og tag ud til hans hule. Herre Ravnehold venter på din tilbagekomst med nøglen.", p="Tasken er allerede ankommet fra Ærkemager Xylen, har du fundet nøglen?", c="Nøglen! Jeg troede, den var tabt for altid. Vær venlig at tage et fortryllet klædningsstykke fra mit lager -- de er forbeholdt snigmordere med usædvanlig dygtighed og loyalitet. Det bør være kendt, at <Name> ikke skal tages let på!\n\n<Jorak åbner tasken og bades i et gyldent skær indefra. Hans øjne bliver store, og han stirrer...>"},
  [8240] = {n="En Bijou til Zanza", l="Ødelæg en af de Håkkari-bijouer, du finder i Zul'Grub ved Zanzas Alter på Yojamba-øen. Når du er færdig, så tal med Vinkaksa i nærliggende område.", d="Ødelæggelsen af de forskellige Håkkari-bijouer er af yderst stor betydning for os, så meget at vi byder fremmede fra stammen velkommen til selv at gøre det!\n\nTag en af de bijouer, du finder i Zul'Grub, til Zanzas Alter og ødelæg den. Kun denne ene gang giver jeg dig et ekstra Æresmærke fra vores stamme; dette er langt ud over, hvad du normalt ville få.\n\nVær selv vidne til Zanzas velsignelser!", p="Har du ødelagt bijouen ved Zanzas Alter? Gør det, og så vil du være dobbelt velsignet af Zanza!", c="Fremragende... hver bijou, vi rykker fra Blodgudens håndlangere, bringer os alle et skridt nærmere til endelig at besejre dem én gang for alle. Du bringer ære til Zandalarerne - og til dig selv - gennem dine ædle handlinger.\n\nHusk, <Name>, at du altid kan ødelægge de bijouer, du finder i Zul'Grub, ved alteret. For hver en får du anerkendelse og et Æresmærke! Husk blot at have en ledig plads i din beholdning, hvis du ikke allerede har et af mærkerne."},
  [8249] = {n="Skraldekasser Påkrævet", p="Mine snigmordere skal slibe deres låseknæk-færdigheder, og jeg har brug for låse med passende sværhedsgrad -- det Zan laver til os, er uegnet for andet end de fattigste nybegyndere.\n\nSiger jeg dig hvad, hvis du bringer mig 5 tunge skraldekasser, skal jeg give dig nogle af de fineste kastekniver, som snigmorderne kender til.\n\nDu kan låse kasserne op og rode i dem, men du må efterlade i det mindste nogle mønter i dem... selv en snigmorder under uddannelse har brug for motivation.", c="Må disse knive finde et hjem i nogens hjerte.\n\nBogstaveligt talt."},
  [8250] = {n="Magikunst", l="Søg Sanath Lim-jo og få adgang til at se Ærkemager Xylen.", d="Ærkemager Xylen har for nylig spurgt rundt... efter nogen med din erfaring.\n\nHvis du vil søge ham op, finder du ham i Azsyra. Hans tårn er bygget højt oppe på klipperne, og den eneste vej op er en teleportbesværgelse, fremkaldt af hans arrogante tjener, Sanath Lim-jo.\n\nSanath slår lejr under sin herres tårn. For at finde ham skal du rejse dertil, hvor Azsyras hovedvej deler sig ved indgangen til Ruinerne af Eldarath. Fra det sted går du direkte mod nord, indtil du når klipperne.", c="<Sanath skæver hånligt til dig.>\n\nÆrke<Class> Xylen venter på din ankomst."},
  [8251] = {n="Magisk Støv", l="Bring 10 Glitrende Støv til Ærkemager Xylen.", d="Blodalferne i Azsyra har udviklet en metode til at pulverisere de magiske genstande, de skaffer sig. Det glitrende støv, de producerer, adskiller sig fra de komponenter, man normalt får ved en afmagiseringsbesværgelse.\n\nDa jeg sendte min lærling for at handle om støvet, blev han dræbt uden tøven. For det skal de betale.\n\nTiden til snak er forbi, <Name>. Find blodalferne langs Azsyras klipper, og brug mere \"overtalende\" metoder til at skaffe dem det glitrende støv.", p="Har du støvet?", c="Velgjort, <Name>! Det holder aldrig op med at forbløffe mig, hvor overtalende en salve arkan projektiler kan være."},
  [8252] = {n="Sirenens Koral", l="Saml 6 fortryllet koral og returner dem til Ærkemager Xylen.", d="Se dig omkring. Ruinerne og strandene er oversvømmet af spyttepisk. For nylig har de elendige væsner lært at genkende de sjældne komponenter, der er hjemmehørende i Azsyra.\n\nJeg taler specifikt om fortryllet koral -- de tiltrækkes af den af grunde, jeg ikke kender. Der er nu kun lidt koral tilbage i bugten, og det er afgørende for min forskning. Jeg har brug for, at du udskiller noget fortryllet koral fra spyttepisk-sirenerne og bringer det til mig.", p="Spyttepisk-sirenerne er overraskende dygtige magikere. Ikke lige så dygtige som dig, håber jeg?", c="Dette er et fremragende koraleksemplar, <Name>. Dine færdigheder er uden tvivl præcise og dødbringende.\n\nTro ikke, at din indsats er gået ubemærket hen. Måske er du værdig til en ægte prøve på dine færdigheder..."},
  [8253] = {n="Ødelæg Morfaz", l="Hent det arkan skår fra Morfaz og returner til Ærkemager Xylen.", d="Der findes en grøn drake dybt inde i Det Sunkne Tempel ved navn Morfaz.\n\nFor år siden overmandede han mig i et dristigt baghold og opslugte min lærling helt. Selvom tabet af en lærling ikke er ukendt for mig, bar denne ene et arkan skår af usædvanlig størrelse og kvalitet.\n\nDu må samle mægtige allierede og trænge ind i tempelet. Ødelæg Morfaz og hent det arkane skår fra hans tidløse mave.", p="Har du dræbt min gamle nemesis?", c="Utroligt. Skåret er vokset, efterhånden som det absorberede drakens energi gennem de lange år.\n\nDer er ikke mere, jeg kan bede dig om nu. Min fulde evne til at smede det arkane er vendt tilbage med dette skår. Min første skabelse er din, <Name>, og du skal blot vælge..."},
  [8254] = {n="Cenarion-bistand", l="Søg Ogtink i Azsyra.", d="Det er det guddommeliges vej at hjælpe dem, der har brug for det. Hvordan er ubetydeligt -- kun hvorfor betyder noget.\n\nCenarion-kredsen har netop et sådant behov. Tal med Ogtink for at yde bistand i deres nød. Han holder til på klipperne nordøst for Ruinerne af Eldarath i Azsyra.", c="Din ankomst har løftet en byrde fra mine skuldre. Vi har meget at gøre."},
  [8255] = {n="Om Løbere Vi Kender", l="Skaf 4 sunde løberkirtler og bring dem til Ogtink i Azsyra. Ogtink holder til på klipperne nordøst for Ruinerne af Eldarath.", d="Mosshov-løberne i Azsyra er prægtige dyr, der engang levede i Ondskoven. De modstår naturligt smitte og gift og blev ikke påvirket af korruptionen dér. I deres forfædres visdom valgte de simpelthen at forlade det sygnede sted.\n\nDet gør mit hjerte ondt, men jeg må bede dig om at jage disse mægtige bæster for mig. Saml fire løberkirtler som den første ingrediens til en genoprettende salve -- en salve vi vil bruge til at hele Ondskoven.", p="Du er vendt tilbage. Var du succesfuld?", c="Det er godt, at den guddommelige vej har ført dig til os, <Name>. Dine overbevisninger står ikke i vejen for opgaverne i at skabe denne salve.\n\nDu ser, løberen er hellig for Cenarion-kredsen, og at dræbe dem af en hvilken som helst grund, uanset hvor nødvendig, svækker deres ånd."},
  [8256] = {n="Undødens Saft", l="Skaf en ikor af undød til Ogtink i Azsyra. Ogtink holder til på klipperne nordøst for Ruinerne af Eldarath.", d="Til denne genoprettende salve skal du bruge en simpel formel: én del gift, to dele kur. Du har skaffet én kur, nu må du samle giften.\n\nMægtige udøde, såsom de efterladte højfødte, der vandrer rundt i Ruinerne af Eldarath, er nogle gange så gennemsyret af ondskab, at det størkner til en syg grønlig klump. For de levende er dette stof kendt som ikor af undød.\n\nPå grund af styrken i dette nedrige element kræver jeg kun en enkelt ikor.", p="Vi må skaffe ikoren hurtigt. Har du fundet den?", c="Jeg kan ikke sige, at jeg er glad for at modtage sådan et elendigt stof, men det er et nødvendigt onde. Tak, <Name>."},
  [8257] = {n="Morfaz' Blod", l="Dræb Morfaz i Det Sunkne Tempel, og returner hans blod til Greta Mosshov i Ondskoven. Indgangen til det sunkne tempel findes i Sorgernes Sump.", d="Nu den sidste del, den anden kur.\n\nDen grønne drake Morfaz er kendt for at være immun over for alle former for gift og smitte -- mange druider døde for at bringe os denne viden. Der er ingen tvivl om, at hans blod er potent nok til vores behov.\n\nEt bud fra Cenarion-kredsen vil tage de dele, du allerede har samlet, mens du indsamler den sidste. Kald dine allierede og søg drakens hule i det sunkne tempel i Atal'Hakar. Bring hans blod til Greta Mosshov i Ondskoven.", p="Har du Morfaz' blod?", c="Du har dræbt Morfaz og båret hans blod til os... Jeg kan næsten ikke tro denne gode nyhed!\n\nVi vil straks blande ingredienserne og begynde at hele træerne og væsnerne i Ondskoven. Det vil tage et helt liv at fortryde det, der er sket her, men du har givet os midlerne til at gøre det."},
  [8258] = {n="Mørkehøster-intimideringen", l="Brug Spådomsskueren i hjertet af Det Store Ossuariums kælder i Skolomance. Det vil fremkalde ånder, du må bekæmpe. Besejrer du disse ånder, vil det fremkalde Dødsridder Mørkehøster; besejr ham.\n\nBring Mørkehøsters hoved til Sagorne Kammarsti i Visdommens Dal, Orgrimgrad.", d="Dødsridder Mørkehøster hersker over Det Store Ossuarium i Skolomance. Han truer med at vride åndeverdenen, så den adlyder hans egne ønsker, og han må stoppes! Her kommer den Spådomsskuer ind i billedet, som du hjalp med at skabe.\n\nBrug Spådomsskueren i hjertet af Det Store Ossuariums kælder til at kalde Mørkehøsters åndelige håndlangere frem. Besejr ånderne, så vil dødsridderen selv dukke op. <Name>, bring mig hans hoved! Kun hans undergang vil vende den skade, der er gjort på åndeverdenen!", p="Tiden er kritisk, <Name> - har du lykkedes med at stoppe Dødsridder Mørkehøsters trussel?", c="Dette er en sejr at nyde, <Name>! Mørkehøsters undergang bør genoprette de skrøbelige lænker, der forankrer åndeverdenen.\n\nDu har langt overgået, hvad der blev bedt om, selv da du ingen forestilling havde om belønning eller godtgørelse. Du er virkelig en værdig shaman, min ven.\n\nJeg ved, at det at handle for at bevare åndeverdenen burde være tak nok, men vær så venlig - modtag denne enkle gave med min tak."},
  [8259] = {n="En Mere Passende Belønning", c="Ah, <Name>... din indsats mod Mørkehøster var ekstraordinær - en indsats, skal jeg tilføje, der fortjente en langt bedre belønning, end du fik. Vær venlig at modtage denne hjelm som en ekstra gave for dine bedrifter i Skolomance.\n\nIgen, tak."},
  [8260] = {n="Arator Simpel Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig over for os, og bandager, når du er Æret."},
  [8261] = {n="Arator Standarte Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig over for os, og bandager, når du er Æret."},
  [8262] = {n="Arator Avanceret Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig over for os, og bandager, når du er Æret."},
  [8263] = {n="Skænders Simpel Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig over for os, og bandager, når du er Æret."},
  [8264] = {n="Skænders Standarte Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Venlig over for os, og bandager, når du er Æret."},
  [8265] = {n="Skænders Avanceret Plejepakke", c="Du har bestemt begyndt at bevise dig over for os, <Name>. Som belønning, så tag venligst denne plejepakke! Inde i den finder du rationer og bandager, som kun kan bruges inde i Arathi-bækkenet.\n\nNår du fortsætter med at bevise dig inde i Bassinet, vil du opdage, at disse varer bliver tilgængelige for dig at købe. Rationer bliver tilgængelige, når du er Æret over for os, og bandager, når du er Respekteret."},
  [8266] = {n="Offerbånd", p="Jeg forstår, at det nogle gange kan være svært at komme på toppen i Krigssang-kløften. Alligevel er din indsats på vores vegne - selv når sejren ikke opnås - vigtig.\n\nHvis du gennemfører en af prøvelserne inde i Krigssang-kløften og ikke opnår sejren, vil du stadig modtage et offerbånd. Bring det til mig, så Vagterne kan belønne dig for at handle på vores vegne... selv hvis du ikke kunne vinde denne gang.", c="Nå, du flygtede ikke i mødet med nederlag. Du stod din mand, <Name>, og når det kommer til stykket, er det det, der gør en ægte helt. Ingen tvivl om, at du vinder næste gang... men ikke desto mindre takker vi dig for din indsats."},
  [8268] = {n="Offerbånd", p="Jeg forstår, at det til tider kan være svært at komme på toppen i Krigssangskløften. Din indsats på vores vegne - også når sejren udebliver - er dog vigtig.\n\nSkulle du fuldføre en af prøverne inde i Krigssangskløften uden at opnå sejr, får du stadig et Offerbånd. Bring det til mig, så Udrykkerne kan belønne dig for at handle på vores vegne... selvom du ikke kunne vinde denne gang.", c="Nå, du flygtede ikke ved nederlaget. Du holdt stand, <Name>, og når det kommer til stykket, er det sådan en sand helt bliver til. Du vinder sikkert næste gang... men vi takker dig alligevel for din indsats."},
  [8271] = {n="Helt fra Stormspids", c="Som helt fra Stormspids må du vælge én genstand fra disse nyligt plyn... øh, genvundne skatte."},
  [8272] = {n="Helt fra Frostulv", c="Hvordan føles det, <Name>? Hvordan føles det at knuse sine fjender og se deres linjer briste? Det føles godt, ikke sandt?\n\nDu bør belønnes for denne heroiske bedrift, soldat."},
  [8273] = {n="Orlas Taknemmelighed", c="Nu er det da interessant! Du siger, at du fandt denne tavle på en lille, øde ø ved Udsigtsklipperne i Bagland, <Class>? Meget interessant, ja. <Orla lægger omhyggeligt tavlen væk og gnider hænderne sammen.>\n\nJeg takker dig for din indsats i denne sag. Den Mørke Dame vil blive meget glad for denne opdagelse. Lad mig belønne dig efter fortjeneste."},
  [8275] = {n="Generobring af Silitus", l="Tal med Vindkalder Stolthorn i Cenarion-fæstningen i Silitus.", d="Opmærksomhed, Alliancens helte! Silitid-truslen er blevet ignoreret alt for længe. Uden nogen reel modstand har de hele tiden forberedt sig på en storstilet udvidelse.\n\nCenarion-kredsens styrker samler sig i Silitus for at tage kampen til disse elendige skabninger, og alle raske eventyrere opfordres hermed til at slutte sig til os!\n\nVent ikke, til det er for sent! Hjælp os med at forsvare Azerot! Meld dig hos Vindkalder Stolthorn i Cenarion-fæstningen for specifikke instruktioner!", c="Fremragende, en ny rekrut, der svarer på kampens kald mod silitiderne. Velkommen til Cenarion-fæstningen, <Class>. Det glæder mig at se, at vores udsendinges ord når helte af dit kaliber. Du vil ikke mangle muligheder for at hjælpe os i vores bestræbelser her, og jeg forventer, at du hurtigt vil vise dig at være en værdifuld allieret i vores sag."},
  [8276] = {n="Generobring af Silitus", l="Tal med Vindkalder Stolthorn i Cenarion-fæstningen i Silitus.", d="Opmærksomhed, Hordens mestre! Der er en trussel, vi har ladet stå uimodsagt alt for længe. Jordskælv nær silitid-bikuber over hele Azerot har advaret os om store bevægelser i deres rækker, mens de forbereder sig på udvidelse.\n\nCenarion-kredsens styrker samler sig i Silitus for at tage kampen til silitiderne, før det er for sent! Ingen skal længere besudle vores lande!\n\nAlle raske kæmpere skal melde sig hos Vindkalder Stolthorn i Cenarion-fæstningen! Silitiderne skal besejres!", c="Fremragende, en ny rekrut, der svarer på kampens kald mod silitiderne. Velkommen til Cenarion-fæstningen, <Class>. Det glæder mig at se, at vores udsendinges ord når helte af dit kaliber. Du vil ikke mangle muligheder for at hjælpe os i vores bestræbelser her, og jeg forventer, at du hurtigt vil vise dig at være en værdifuld allieret i vores sag."},
  [8277] = {n="Dødbringende ørkengift", l="Bitix Lunefuldspræg i Cenarion-fæstningen i Silitus vil have dig til at samle 8 Stenpisk-skorpidbrod og 8 Sandskridser-hugtænder. Vend tilbage til hende, når opgaven er fuldført.", d="Bitix Lunefuldspræg til tjeneste! Min fætter Noggel tjener til livets ophold ved at samle sjældne urter til alkymisterne i Cenarion-fæstningen. Eller det gjorde han, i hvert fald. Han kom hjem fra sin sidste tur med et stærkt gift løbende i årerne.\n\nJeg har formået at bremse giften, men for at neutralisere den helt har jeg brug for giftprøver fra det, der stak ham.\n\nNoggel kom fra nord, så jeg vil vædde min skjorte på, at stenpisk-skorpiderne eller sandskridserne gjorde det. Bring mig nogle brodder og hugtænder, så prøver jeg at lave et modgift til ham.", p="Er du færdig med at samle prøverne? Vi kan miste Noggel når som helst!", c="Hold tommelfingrene, ven! Lad os håbe, vi kan redde Noggel!"},
  [8278] = {n="Noggels sidste håb", l="Bitix Lunefuldspræg i Cenarion-fæstningen i Silitus vil have dig til at samle 3 Stenpisk-klobrodder, 3 Stenpisk-flåerbrodder og 3 Klippestalker-hugtænder.", d="Pokkers! Modgiften virkede ikke. Noggel må være blevet stukket af et af de stærkere væsener i det fjerne syd.\n\nJeg har brug for, at du tager derned og henter flere prøver til mig, <Name>. Det gode er, at da deres gift er stærkere, skal jeg ikke bruge så mange. Det dårlige er, at der kryber flere slags giftige væsener rundt i det sydlige område, så du må hente fra flere kilder.", p="Dette er vores sidste chance for at redde Noggel! Skynd dig!", c="Ja! Det ser ud til at virke, Noggel er ved at komme til. Vi står i din gæld, og det i den grad!"},
  [8279] = {n="Tusmørkeleksikonet", l="Bring de tre kapitler af Tusmørkeleksikonet til Eremit Ortel i Silitus.", d="Tusmørkets Hammer er ikke venlig over for dem, der forlader deres rækker. De jager mig den dag i dag, som om jeg var et slags udyr! Det er unødvendigt at sige, at en fjende af dem er en ven af mig!\n\nFor at tyde denne tavle har jeg brug for den bog, deres skrivere brugte til at kode hemmelige beskeder: Tusmørkeleksikonet. Det er et så vigtigt redskab, at de opbevarer dets tre kapitler på forskellige steder! Officererne, der har fået betroet leksikonet, kaldes Tusmørkevogtere; led efter dem i Tusmørkets Hammers lejre.", p="Hvem er der? Åh, det er dig! Har du fundet alle leksikonets kapitler endnu?", c="Ja! Det er bogens dele! Lad os så begynde, <Name>.\n\nByt hvert tredje ord med ord fra andet kapitel... byt så hvert andet ord med ord fra første kapitel... Vent, gjorde jeg det baglæns?"},
  [8280] = {n="Sikring af forsyningslinjerne", l="Vindkalder Stolthorn i Cenarion-fæstningen i Silitus vil have dig til at dræbe 15 Mudderslagtere.", d="Cenarion-fæstningen er et sted af yderste strategisk betydning. Jeg er overbevist om, at så længe vi holder den, er vores sejr over silitiderne garanteret. Forudsat at vores tilførselsforsyninger kan opretholdes, altså.\n\nØrmene i ørkenen har vist sig at være en større trussel mod vores forsyningskaravaner end selve silitiderne. Netop i morges blev en stor forsendelse morgenkorn hærget af en flok mudderslagtere. Jeg har brug for, at du tynder ud i deres rækker, så vores forsyninger ikke bringes i fare.", p="Mudderslagterne er en alvorlig trussel og skal håndteres hurtigt!", c="Du har min oprigtige taknemmelighed. Din indsats for at hjælpe Cenarion-fæstningen har vist sand mod."},
  [8281] = {n="Skærpet sikkerhed", l="Vindkalder Stolthorn i Cenarion-fæstningen i Silitus vil have dig til at slagte 20 Mudderknusere.", d="Din indsats har været virkelig eksemplarisk indtil nu, <Name>. Vores forsyningslinjer er dog ikke helt sikre endnu. Når mudderslagterne er væk, vil deres større sydlige fætre helt sikkert flytte ind og tage deres plads i nord.\n\nDu bliver nødt til at dræbe en hel del mudderknusere for at holde dem stangen, men vi kan ikke overlade sikkerheden af vores forsyningslinjer til tilfældighederne.", p="Mudderknuserne er en alvorlig trussel og skal håndteres med det samme!", c="Fremragende! Du har vist dig at være en værdifuld allieret i forberedelserne til krigen mod silitiderne."},
  [8282] = {n="Noggels tabte taske", l="Hent Noggels taske i bjergene i syd i Silitus og bring den tilbage til ham i Cenarion-fæstningen.", d="Hvor er jeg? Hvor er min taske? *gisp* Jeg må have tabt den, mens jeg flygtede fra Dødsspænde, den kæmpestore skorpid. I min hast for at slippe væk løb jeg lige ind i en rede af stenpisk-flåere.\n\nTasken, jeg bar på, havde alle slags sjældne reagenser i sig. Uden dem kan Bitix og jeg ikke lave de eliksirer, Cenarion-fæstningen har brug for. Jeg er for svag til at komme op endnu, men jeg kan gøre det umagen værd, hvis du bringer mine reagenser tilbage.\n\nJeg løb ind i Dødsspænde i de sydlige bjerge, bag Bronzeskægs lejr.", p="Har du stadig ikke fundet min taske? Nå, jeg bør vel tælle mine lykkestjerner, i hvert fald er giften blevet renset ud.", c="Ja! Du bragte min taske tilbage. Og mine sjældne reagenser er alle her! Jeg vil stå i din gæld i lang tid."},
  [8283] = {n="Eftersøgt - Dødsspænde, Ørkenens Rædsel", l="Bring Dødsspændes klo til Vagtkaptajn Vish Kozusk.", d="Den forfærdelige skorpid, Dødsspænde, menes at have trukket sig tilbage til de sydlige bjerge, da silitid-aktiviteten er steget. Hun udgør en stor trussel mod patruljer og ekspeditioner i de sydlige egne. Enhver, der deltager i hendes undergang, vil blive belønnet rigeligt. Spørg Kaptajn Vish Kozusk, øverst i Cenarion-fæstningens vagttårn, om en belønning.", p="Jeg har brug for skabningens klo som bevis for bedriften. Ingen klo, ingen belønning.", c="Fremragende! Nu hvor Dødsspænde er væk, kan vi bruge de sydlige bjerge som en strategisk rute uden om silitidernes boer. Dit arbejde værdsættes meget."},
  [8284] = {n="Tusmørkemysteriet", l="Geolog Lærkebane i Cenarion-fæstningen i Silitus vil have dig til at samle 8 Tusmørke-tavlefragmenter.", d="En lejr af Tusmørkets Hammers kultister trivedes engang nordvest herfra. Hvis du skulle begive dig derhen nu, ville du finde området fyldt med elementarer og intet andet end spredte stykker træ og lærred, der markerer stedet, hvor lejren lå.\n\nJeg har fundet nogle få fragmenter af en lertavle på stedet, men jeg har for få af dem til at samle noget brugbart. Se om du kan finde de resterende tavlefragmenter, så vi kan kaste lys over Tusmørkets Hammers tilstedeværelse her i Silitus.", p="Den hærgede lejr ligger nordvest herfra. Kom tilbage, når du har alle fragmenterne.", c="Præcis som jeg mistænkte. Jeg kan tyde enkelte ord på tavlerne, men de synes at være blottet for enhver logik eller mening. Det er ikke ukendt, at Tusmørkets Hammers sekter bruger en kode til at skjule betydningen af deres tekster; vi må gå til en, der ved mere om den slags."},
  [8285] = {n="Desertøren", l="Tag den restaurerede tavle til Eremit Ortel i Silitus.", d="Der går rygter om, at et medlem af Tusmørkets Hammer ved navn Ortel har forladt sin sekt. Det lyder til, at han gemte sig i bjergene syd for Sydvindsbyen, hvor han lever som eremit. Måske kan du få hans hjælp til at tyde tavlen.\n\nTag den restaurerede tavle med dig og find Ortel.", p="Dig! Hvordan fandt du mig? Hvem er du? Du blev ikke fulgt, vel? Tal!", c="Jeg ser, at du kender min gamle organisation. Du må være fra Cenarion-fæstningen.\n\nDu søger oplysninger, du kan bruge mod dem? Kom tættere på, måske kan vi være til gensidig hjælp."},
  [8286] = {n="Hvad i morgen bringer", l="Begiv dig til Tidens Huler i Tanarisørknen og find Anakronos, Nosdormus Yngel.", d="Dødens favn havde næsten overvundet mit væsen, da han greb ind. Han åndede kun én gang over mit lemlæstede legeme og ventede derefter tålmodigt på, at tidens sand skulle rense mine sår.\n\n\"For evigt vil du blive, hvis du må,\" sagde han, og med disse ord blev jeg bundet som Vogter.\n\nSe nu mod ørkenen. Den anden krig er over os. Du må finde hvilestedet for Bronze. Begiv dig til Tidens Huler og se, om mesteren er vendt tilbage. Jeg må være sikker, før jeg kan gå videre.", p="Er Anakronos vendt tilbage?", c="Sådan skal det være - den store er rejst. Min vagt er ved at ende..."},
  [8287] = {n="En frygtelig hensigt", l="Tag det afkodede tavleperkament til Kommandør Mar'alit.", d="Ok, her er vi... en ret værdifuld informationsbid, må jeg sige! Jeg har set Cenarion-kredsens styrker ankomme til Silitus. De planlægger at drive Tusmørkets Hammer ud, ikke? Det her vil hjælpe.\n\nTag dette perkament til deres leder, Kommandør Mar'alit. Snart vil Tusmørkets Hammer være besejret, og jeg vil være uden for deres greb for altid!", p="Hvad er det, du bringer mig, <Name>?", c="Dette er meget interessant information, <Name>. Det kaster lys over Tusmørkets Hammers tilstedeværelse i Silitus og vil uden tvivl hjælpe os i kampen mod dem. Dine bestræbelser vil blive belønnet rigeligt, <Class>."},
  [8288] = {n="Kun én kan rejse sig", l="Bring hovedet af Yngelherre Pisk-lægger til Barostolt fra De Flydende Sande i Cenarion-fæstningen i Silitus.", d="Der er ingen tid at spilde! En helt må findes! Opgaven, jeg giver, kræver en hel hær at udføre, men kun én kan træde frem af mængden af kommende mestre for at tage byrden og ansvaret som allieret til Yngelen.\n\nI Sortklippes Herres hule findes et yderst grusomt udyr. Yngelherre Pisk-lægger vogter Stridens Haller og blokerer vejen ind til Nefarians indre helligdom. Slå det afskyelige væsen ihjel og bring mig hovedet. Gør du det, kan du begynde det næste skridt på din rejse.", p="Det er Nosdormus Yngels gunst, du må fortjene.", c="Kunne du være den første til at vinde gunst hos Den Bronze Flyvning på tusind år?"},
  [8290] = {n="Fordriv de invaderende", l="Gå ind i Krigssangskløften og besejr Horden, opnå et Krigssangskløftens Æresmærke, og vend tilbage til Vogter Fjernsang i Sølvvingelunden.", d="Bag denne tunnel finder du en slagmark af strid og uro, unge <Class>. Horden bliver ved med at hærge vores hellige skov og fælder de stedsegrønne træer for at drive deres krigsmaskiner.\n\nGå ind i Krigssangskløften og forsvar Sølvvinge-fæstningen. Skub de invaderende hordestyrker tilbage!\n\nGør du det, og optjen en meritamulet. Bring mig en sådan amulet, <Name>, så belønner jeg dig."},
  [8291] = {n="Fordriv de invaderende!", l="Gå ind i Krigssangskløften og besejr Horden, opnå et Krigssangskløftens Æresmærke, og vend tilbage til Vogter Fjernsang i Sølvvingelunden.", d="Bag denne tunnel finder du en slagmark af strid og uro, unge <Class>. Horden bliver ved med at hærge vores hellige skov og fælder de stedsegrønne træer for at drive deres krigsmaskiner.\n\nGå ind i Krigssangskløften og forsvar Sølvvinge-fæstningen. Skub de invaderende hordestyrker tilbage!\n\nGør du det, og optjen et Æresmærke. Bring det til mig, <Name>, så belønner jeg dig.", p="Har du kæmpet i Krigssangskløften og forsvaret Sølvvinge-fæstningen?", c="Du har vist din værdi for vores indsats i Krigssangskløften. Bliv ved med at støtte sagen og bring mig flere Æresmærker. Gør du det, vil du opnå endnu mere af vores tillid."},
  [8294] = {n="Knus Sølvvinge-usurpatorerne", l="Gå ind i Krigssangskløften og besejr Alliancen, opnå et Krigssangskløftens Æresmærke, og bring det til Kaptajn Knuskranie i Mor'sjan Basislejr.", d="Askedalens vildmark vil bukke under for Hordens styrke, <Race>. Intet, Sølvvingerne siger eller gør, kan standse vores suveræne imperativ. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste det, der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger ned deres svage forsøg på at bremse vores fremmarch. Ødelæg Sølvvingevogterne, og optjen et Æresmærke. Vend tilbage til mig med et sådant mærke, <Name>, og du vil blive belønnet.", p="Dine fjenders blod er et æresmærke. Har du et sådant mærke?", c="<Kaptajn Knuskranie brøler i triumf>\n\nHvor meget mere kan de udholde? Hvor mange flere af Alliancens skarn må falde for Hordens hånd, før de trækker sig? Kun tiden vil vise det, <Race>..."},
  [8295] = {n="Knus Sølvvinge-usurpatorerne", l="Gå ind i Krigssangskløften og besejr Alliancen, opnå et Krigssangskløftens Æresmærke, og bring det til Kaptajn Knuskranie i Mor'sjan Basislejr.", d="Askedalens vildmark vil bukke under for Hordens styrke, <Race>. Intet, Sølvvingerne siger eller gør, kan standse vores suveræne imperativ. Kalimdør tilhører Horden. Hvordan tør de forsøge at forhindre os i at høste det, der retmæssigt er vores!\n\nLad stoltheden svulme i dit bryst, mens du hugger ned deres svage forsøg på at bremse vores fremmarch. Ødelæg Sølvvingevogterne, og optjen et Krigssangskløftens æresmærke. Vend tilbage til mig med et sådant mærke, <Name>, og du vil blive belønnet."},
  [8297] = {n="Arathi-bækkenets Æresmærke!", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Sergent Maklær i Flygtningeodden.", d="Krig må udkæmpes af soldater, siger enhver soldat dig. De vil også sige, at et slag udkæmpet med dårligt udstyr eller på en tom mave er tabt, før det begynder!\n\nDet er derfor, Arathi-bækkenet er vigtigt. Der er nøgleområder i bækkenet, som rummer væsentlige ressourcer. Metaller, våben, mad, tømmer - alt er nødvendigt, og alt kan hentes der.\n\nDet er, hvad jeg vil have fra dig, <Name>. Gå ind i Arathi-bækkenet, vind slaget ved at holde flere baser end fjenden, og vend tilbage til mig med et Æresmærke.", p="Har du Æresmærkerne, <Name>? Arator-ligaen kan ikke udkæmpe et ordentligt slag uden dem...", c="Du fik mærket! Godt gået! Jeg sender ressourcerne til vores kvartermestre, som hurtigt kan fordele dem til vores tropper.\n\nTak, <Name>. Det er netop den slags vellykkede missioner, som du har udført, der virkelig vinder krige."},
  [8299] = {n="Skær Arator-forsyningslinjerne", l="Vind slaget om Arathi-bækkenet, få et Arathi-bækkenets Æresmærke, og bring det til Dødsstalker Mortus i Hammerfald.", d="Arator-ligaen sparer ikke på noget i deres forsøg på at generobre Arathi. De og alle Alliancens racer strømmer nu til denne fjerne region, fast besluttet på at udvide deres greb fra Flygtningeodden. Vi må standse dem, og den bedste måde at gøre det på er at tage deres forsyninger.\n\nDu kan hjælpe os, <Name>. Gå ind i Arathi-bækkenet, kendt for sine rige miner, frugtbare land og dygtige håndværkere. Indtag og kontrollér hver base, du kan, vind slaget, og vend tilbage til mig med det Æresmærke, du opnår.", p="Hvad er det, <Race>? Har du Æresmærkerne? Gå tilbage til Arathi-bækkenet, slå Alliancens skadedyr ihjel og tag deres ressourcer i besiddelse for Den Mørke Dame!", c="<Dødsstalker Mortus smiler>\n\nEndnu et afgørende slag er blevet givet vores fjender, <Name>. Takket være dine bedrifter er Arathi-bækkenet snart ved at blive grebet af Skænderne."},
  [8301] = {n="Den retfærdiges vej", l="Saml 200 Silitid-skalfragmenter og vend tilbage til Barostolt.", d="Nosdormus Yngel er af natur mistroisk over for de mindre racer. Det er rigtigt, at du har bevist over for mig, at du har potentialet til at blive en helt, men tiden er kommet til at bevise det over for min herre.\n\nBikube'Ashi, Bikube'Zora, Bikube'Regal: Alle myldrer af aktivitet, og alle er en trussel mod vores eksistens. Slå silitiderne ihjel i disse bikuber, og tag et fragment af deres skal med dig. Når du ikke kan bære mere, skal du vende tilbage til mig, så styrker jeg din beslutsomhed.", p="Der er megen historie rodfæstet i deres mistillid til de dødelige racer; men ak, en sådan fortælling er bedst at lade Yngelen fortælle, når tiden er rigtig.", c="Du er ikke alene, helt. Jeg vil nu give dig evnen til at udpege andre, der kan hjælpe dig i din opgave. Hvis du skal være dit folks mester, vil du have brug for hjælp til dine opgaver og pligter."},
  [8303] = {n="Anakronos", l="Søg Anakronos ved Tidens Huler i Tanarisørken.", d="Tiden er inde, <Name>.\n\nJeg må undskylde, at jeg har holdt så meget hemmeligt. Fjender findes overalt, selv lige under vores næser. Læs venligst fra denne tome og lær. Tag den viden, jeg giver dig, og søg vores herre.", c="Du er Kalimdørs håb, <Name>."},
  [8304] = {n="Kære Natasja", l="Kommandør Mar'alit ved Cenarion-fæstningen i Silitus ønsker, at du forhører indbyggerne i Bronzeskæggets Lejr. Du finder Bronzeskæggets Lejr syd for Cenarion-fæstningen.\n\nNår du har indsamlet de ønskede oplysninger, skal du vende tilbage til Kommandør Mar'alit.", d="Min kære Natasja er forsvundet.\n\nSandt at sige har hun opført sig mærkeligt i ugevis op til sin forsvinden. Jeg har mere end én gang set hende tale med sig selv, når ingen var i nærheden. Hun insisterede på, at alt var i orden, og at hun skulle have lov til at fortsætte sin forskning.\n\nHun blev sidst set på vej mod Bronzeskæggets lejr i syd.\n\nMine soldater er for tyndt spredt, <Name>. Jeg har brug for, at du går til Bronzeskæggets lejr og forhører de dværge.", p="Spild ikke tiden, <Name>!", c="<Kommandør Mar'alit sænker hovedet i eftertanke.>\n\nOm hun er i live eller død, må jeg gøre, hvad der er rigtigt. Hun skal findes. Ak, jeg er bundet af pligt til denne forpost. Vil du hjælpe mig endnu en gang, <Name>?"},
  [8305] = {n="Længe Glemte Minder", l="Find den krystallinske tåre i Silitus, og stir ned i dens dybder.", d="I ørkenen i det sydlige Silitus, nær den hellige barriere, findes en enkelt krystallinsk tåre. Denne tåre er et symbol på de store tab, der ramte os under Krigen om de Skiftende Sande. Find tåren, og stir ned i dens dybder for at opnå oplysning.", c="Du kan mærke en stor sorg, der kredser om denne krystal. Kraften er så stærk, at du føler, at du kan falde sammen og dø af sorg."},
  [8306] = {n="Ind i Galskabens Gab", l="Kommandør Mar'alit ved Cenarion-fæstningen i Silitus ønsker, at du finder hans elskede Natasja. De oplysninger, du har samlet, peger på Bikube'Regal i syd som det område, hvor du kan finde Dame Natasja Mar'alit.\n\nGlem ikke at besøge dværgene i Bronzeskæggets lejr, før du begiver dig ind i bikuben. De kan have yderligere opgaver og råd til dig.\n\nOg <Name>, husk Kommandørens ord: \"Gør, hvad du må ...\"", d="Jeg vil have dig til at tage ind i Bikube'Regal og finde ud af, hvad der er blevet af min kære Natasja, <Name>. Det bliver ingen let opgave at klare alene. Jeg anbefaler, at du tager nogle venner med. Før du styrter hovedkulds ind i galskabens gab, så sørg for at gå tilbage og tale med dværgene. De kan måske give dig nogle gode råd om, hvordan du håndterer silitiderne, der bor i den bikube.\n\nOg <Name>, hvis hun virkelig er så gal, som de siger ... så gør, hvad du må.\n\n<Kommandør Mar'alit vender sig væk fra dig.>", p="Natasja?", c="<Kommandør Mar'alit griber sig til brystet.>\n\nCe'Tun? HVAD betyder det hele? Hvad er Ce'Tun? Hvordan kunne dette udyr have forvandlet min søde Natasja til det monster, du beskrev?"},
  [8307] = {n="Ørkenopskrift", l="Led efter information om tilberedning af sandormekød i Tusmørkets Hammers lejr vest for Cenarion-fæstningen.", d="At tilpasse sig livet i ørkenen har været svært, for at sige det mildt. Ikke kun savner jeg fuglene og træerne i Auberdin, men vores madvalg er også stærkt begrænset af dette tørre miljø. Jeg prøver at lære om ørkenurter, men der er ikke mange.\n\nJeg har set grupper fra Tusmørkets Hammer i lejren herfra jage sandorme til mad. Sandormekød er dog så bittert, at jeg ikke kan forstå, hvordan de gør det spiseligt. Hold øje, hvis du går til deres lejr, og lad mig vide, hvis du lærer noget.", c="Denne bog indeholder flere almindelige opskrifter og nogle få usædvanlige. Efter at have bladret i den et par sekunder, får du øje på en opskrift, der indeholder sandormekød."},
  [8308] = {n="Brand Bronzeskægs Tabte Brev", l="Tag Brand Bronzeskægs brev til Bronzeskæggets lejr i det sydlige Silitus.", d="Til den det måtte vedrøre:\n\nHvis du læser dette, er jeg enten død eller snart død. Det er svært at sige. Størstedelen af mandskabet er alligevel død.\n\nFandt information om en Titan. Et stort slag mellem ham og en Den Gamle Gud. Ja, en ægte Den Gamle Gud. Fandt en gammel tunnel, der fører til Ahn'Kiraj. Tager den.\n\nTag dette brev med til min gamle lejr. Sørg for, at min abe får passende mad, vand og kram.\n\n-Brand Bronzeskæg, Ekstrem Opdagelsesrejsende\n\nP.S. Hold øje med den skøre nattenisse, der dyrker Den Gamle Gud.", p="Åh nej.", c="Nå, det forklarer en hel del. Hvis du nogensinde finder en vej ind i Ahn'Kiraj, så hold øje med gamle Brand. Jeg er bange for, at han bliver magtesløs uden sin abe."},
  [8309] = {n="Glyfjagt", l="Rudgar Glyfformer ved Bronzeskæggets Lejr i Silitus ønsker, at du drager til Bikube'Ashi, Bikube'Zora og Bikube'Regal og henter Glyferede Aftryk fra de Glyferede Krystaller i hver bikube.\n\nBrug Geologens Transskriptionssæt til at lave en rimelig kopi af de gamle glyffer. Vend tilbage til Rudgar Glyfformer, når du har fuldført opgaven.", d="Efter vores første indtrængen i bikuberne og Dame Mar'alits efterfølgende galskab har de tre bikuber spyttet insekter ud! Den øgede aktivitet kan hænge sammen med glyfferne, der dækker de mærkelige krystaller.\n\nVi må få et aftryk fra krystallerne i alle tre bikuber. Hvis vi kan få disse aftryk, kan vi måske give mening i denne galskab.\n\nTag dette transskriptionssæt og nogle kammerater, og slå til mod de bikuber, <Name>. Kom ikke tilbage, før du har fået kopier fra hver bikube.", p="Hvis du finder en skør nattenisse-pige i en af bikuberne, så giv hende et spark bagi fra os.", c="Jeg kan ikke få hoved eller hale på disse glyffer. Jeg har aldrig set noget lignende! Jeg håber, at Frankels forskning kan kaste lys over dette rod."},
  [8310] = {n="Brydning af Koden", l="Frankel Stenbro ved Bronzeskæggets Lejr i Silitus ønsker, at du henter en Bikube'Zora-silitidhjerne, en Bikube'Ashi-silitidhjerne og en Bikube'Regal-silitidhjerne. Vend tilbage til Frankel, når du har fuldført opgaven.", d="Jeg tror, jeg kan formulere en elixir, der gør det lettere for os at tyde glyfferne og sproget hos silitiderne og Qiraji! Hvad har jeg brug for? Godt du spørger! Jeg har brug for hjerner! Mere specifikt en hjerne fra hver silitidtype, der bor i bikuberne. Bring mig hjerner, så er Rudgars arbejde måske ikke forgæves.", p="Gå og leg med aben, knægt. Jeg har ikke tid til det her.", c="Fremragende! Gå ikke for langt væk, knægt. Vi har måske brug for, at du påtager dig en opgave eller to mere."},
  [8312] = {n="Helligaftens Ende-godter til Spøgs!", l="Tal med kroværterne i Orgrimgrad, Underbyen og Tordenskrænt samt med Kaja Remik i Sen'jin-landsbyen. Udfør de kunster, de beder dig om, til gengæld for de godter, de tilbyder.\n\nVend tilbage til Spøgs i Orgrimgrads børnehjem med en Tordenskrænt-marcipan, en Mørkspyd-gummibamse, en Orgrimgrad-nougat og en Underby-mønthus.", d="Jeg vil gerne gå rundt og banke på døre, men det kan jeg ikke, fordi jeg er syg. Hvis du går for mig, vil jeg bytte dig den slik, du får, for noget, jeg allerede har! Jeg tror, du ville kunne lide det slik – det får dig til at forvandle dig til ting, der er både sjove og skræmmende!\n\nHver af kroværterne i de store byer har slik, de giver ved Helligaftens Ende – tal med dem og gør de kunster, de beder om! Og en troll ved navn Kaja Remik i Sen'jin-landsbyen deler også slik ud. Når du har alt slikket, så bring det tilbage til mig her!", p="Er du færdig med at gå slik-eller-stik endnu? Jeg er ked af, at jeg ikke kan gå med, fordi jeg er syg, men at du hjælper mig, får mig til at have det lidt bedre ...", c="Wow, du fik dem alle! Du er fantastisk!\n\nTak, fordi du gik slik-eller-stik for mig. Her, tag disse græskar-godter – jeg tror, du kommer til at synes godt om dem!\n\nGlædelig Helligaftens Ende, <Name>!"},
  [8313] = {n="Deling af Viden", l="Bring den Revne Opskriftsside til Kalandrath på kroen i Cenarion-fæstningen.", d="Selvom opskriften på tilberedning af sandormekød er læselig, indeholder den henvisninger til urter og krydderier, som du aldrig har hørt om. Kalandrath har måske nok viden om de planter, der vokser i ørkenen, til at give det mening.", p="Lærte du opskriften? Du kommer vel ikke til at beholde den for dig selv, håber jeg!", c="Lad os se på den ...\n\nDet virker simpelt nok. De har deres egne navne for nogle af urterne, men dem er det simpelt nok at finde ud af. Her, lad mig vise dig!"},
  [8314] = {n="Løsning af Gåden", l="Rudgar Glyfformer ved Bronzeskæggets Lejr ønsker, at du leverer det Glyferede Krystalprisme til Geolog Lærkebane ved Cenarion-fæstningen i Silitus.", d="Vi er på nippet til et gennembrud, <Name>! Aftrykkene, du hentede, har gjort det muligt for os at genskabe glyfferne på dette krystalprisme. De er tilsyneladende et middel for Qiraji og andre ukendte væsener til at kommunikere forskellige budskaber til silitiderne.\n\nDesværre er det alt, vi kunne få ud af glyfferne. Vi må finde en måde at låse de budskaber op, der er skjult i krystallerne.\n\nTag det glyferede krystalprisme til Geolog Lærkebane i Cenarion-fæstningen. Hun kan måske hjælpe.", p="Åh mig! Hvad har du dér, <Name>?", c="Grunden til, at dværgene ikke kunne tyde glyfferne, er, at der ikke er noget at tyde. Prismets skiftende ydre lag skal flugte rigtigt med krystallens indre markeringer, for at budskabet kan overføres. Snedigt ...\n\nSelvom vi burde kunne oversætte disse data, må vi først låse koden op. Der er kun ét spor på prismets overflade – forudsat at aftrykkene blev overført korrekt – og det ser dystert ud."},
  [8315] = {n="Kaldet", l="Geolog Lærkebane ved Cenarion-fæstningen i Silitus ønsker, at du henter Krystallens Oplåsningsmekanisme fra Qiraji-udsendingen.\n\nDu har fået besked på at tage Kaldets Glyffer til Grakkaronds Knogler, syd for Cenarion-fæstningen, og tegne dem i sandet. Hvis Qiraji-udsendingen dukker op, skal du dræbe den og hente Krystallens Oplåsningsmekanisme. Vend tilbage til Geolog Lærkebane, hvis du lykkes.\n\nSaml en hær til denne opgave, <Name>!", d="Glyfferne illustrerer en Qiraji-udsending, der møder tre silitider ved knoglerne af en stor drage. Over glyfferne er der, hvad jeg kun kan antage er en slags kode. Denne kode kan meget vel være nøglen til at tilkalde udsendingen.\n\nJeg vil lave en kopi af glyfkoden, som du skal bruge i sandet ved Grakkaronds Knogler. Hvis jeg har ret, vil Overherrerne komme og tro, at nye data er klar til overførsel. Slå dem ned, og konfronter udsendingen. Han har nøglen til krystallerne ...", p="Du må gribe chancen, når den viser sig, og slå til!", c="Jeg holder 20.000 års historie i mine hænder, <Name>!"},
  [8316] = {n="Krigens Oprustning", c="Krigen kommer, <Name>, og med den kommer utallige rædsler. Du har gjort alt, hvad der kunne forlanges af dig, og for det bør du belønnes.\n\nSkulle denne ... denne profeti nogensinde gå i opfyldelse ...\n\n<Geolog Lærkebane bliver bleg.>\n\nFremtiden for os alle kunne være ved at ende.\n\nDisse våben vil vise sig uvurderlige for din kampagne i denne ørken."},
  [8317] = {n="Køkkenhjælp", l="Kalandrath ved Cenarion-fæstningen har brug for en portion på 10 Røgede Ørkenboller.", d="Den opskrift kommer da til at være nyttig. Jeg må hellere komme i gang, så jeg har nogle røgede ørkenboller klar til i dag. Jeg kunne bruge en hånd med at lave nogle, og jeg vil gøre det umagen værd for dig.", p="Hvordan skrider bollerne frem?", c="Fremragende! Du er en livredder. Bollerne blev ganske gode. Havde egentlig ikke forventet så god smag fra Tusmørkets Hammer."},
  [8318] = {n="Hemmelig Kommunikation", l="Bring 10 Krypterede Tusmørketekster til Bor Vildmane i Cenarion-fæstningen.", d="Nogle af kultisterne i Tusmørkets Hammer bærer rundt på små papirer med vrøvl skrevet på. Jeg vil have dig til at bringe mig en bunke af dem, <Class>.\n\nJeg kan ikke regne ud, hvad vrøvlet betyder, men det er ikke pointen! Disse papirer er, hvordan deres forskellige grupper kommunikerer hemmeligt. Jo flere tekster vi tager ud af omløb, jo mindre kan de kommunikere!", p="Har du bragt mig nogle tekster?", c="Fremragende! Jeg gemmer dem væk, måske kommer de til nytte senere."},
  [8320] = {n="Tusmørkets Geoherrer", l="Dræb 10 Tusmørke-geoherrer, og vend derefter tilbage til Hum Vildmane i Cenarion-fæstningen.", d="Tusmørkets Hammer, en sindssyg kult, der er indstillet på ødelæggelse, har slået lejr i Silitus og udfører ritualer dag og nat. Vi ved endnu ikke, hvad deres planer er, men vi tror, at de på en eller anden måde er forbundet med de pulserende røde krystaller, der er spredt ud over ørkenen.\n\nSelvom deres mysterium en dag måske bliver løst, må vi først tage os af den umiddelbare trussel. Gå til deres lejre mod vest, og find Tusmørke-geoherrerne. De er hovedet på disse slanger; det er dér, vi må slå til!", p="Gå ud i ørkenen og find Tusmørke-geoherrerne, <Name>. Vend tilbage til mig, når de er slået ihjel.", c="Det var en veludført opgave, <Name>. Din nedslagtning af Tusmørke-geoherrerne må have tilføjet kulten et alvorligt slag. Lad os håbe, at deres planer bliver bremset ..."},
  [8321] = {n="Vyral den Onde", l="Bring Vyrals Signetring til Hum Vildmane i Cenarion-fæstningen.", d="Vi har opdaget endnu en base for Tusmørkets Hammer. Den kaldes Tusmørkets Løb; det er en hule gemt i det nordøstlige hjørne af Silitus. Kultens lokale leder, Vyral den Onde, hjemsøger den hule – det er ham, du næste gang må besejre. Når du har gjort dette, skal du bringe mig hans signetring.\n\nHeld og lykke, <Name>. Rædslerne i Tusmørkets Løb er faktisk formidable.", p="<Name>, har du så besejret Vyral den Onde endnu? Har du hans signetring?", c="Du har gjort det! Vyral er dræbt! Det kan kun betyde undergang for Tusmørkets Hammers operationer i Silitus. Der kan være flere af dem, der flitrer rundt, men det slag, du i dag har tilføjet kulten, er et, de ikke let vil komme sig over."},
  [8322] = {n="Rådne Æg", l="Læg de Rådne Æg i hovedbryggerfadet inde i Sydstrandens Kro.", d="Menneskene i Sydstranden elsker deres øl, og derfor sætter de pris på ølet, der serveres i Sydstrandens Kro. Med Helligaftens Ende nu over dem kan vi bruge det til at ødelægge deres seneste parti drikkevarer i ugevis – hvis ikke måneder!\n\nTag disse rådne æg, og læg dem i hovedbryggerfadet inde i Sydstrandens Kro. Din blotte tilstedeværelse vil skabe uro, så vær forberedt på at forsvare dig selv!\n\nNår du har givet Sydstranden en smag, de ikke snart glemmer, skal du vende tilbage til mig her ved festivalen!", p="Fadet er fyldt med øl.", c="Efter at have kæmpet dig vej ind i kroen med held, placerer du nu æggene i fadet. Du kan lugte den ækle stank, der gennemsyrer luften ..."},
  [8323] = {n="Sande Troende", l="Eremit Ortel ønsker, at du bringer ham 10 Krypterede Tusmørketekster", d="Nu hvor jeg har Tusmørkeleksikonet i min besiddelse, er der en lille tjeneste, jeg gerne vil bede dig om.\n\nMin tidligere organisation har en hemmelig kodet bulletin, som de cirkulerer en gang om måneden.\n\nHvis de gør fremskridt i deres eftersøgning efter mig, eller hvis de afblæser eftersøgningen, vil det blive offentliggjort i De Sande Troende.\n\nSelvom denne information naturligvis er værdifuld for mig, indeholder publikationen andre nyttige oplysninger, som jeg kan dele. Bring mig alle kodede tekster, du finder om Tusmørkets Hammers medlemmer.", p="Har du fundet nogle krypterede tekster? Jeg er ret nysgerrig efter at læse denne måneds Sande Troende.", c="Fremragende! Jeg vil begynde at dekode dem så hurtigt som muligt. Hvis jeg finder noget interessant, skal jeg nok finde en måde at få informationen til dig på."},
  [8331] = {n="Aurel Guldblad", l="Tal med Aurel Guldblad i Cenarion-fæstningen.", d="<Name>, selvom vi havde håbet, at Tusmørkets Hammers operationer i Silitus var ved at bremse ... tog vi beklageligvis fejl. Gennem fortsatte angreb mod kulten har vi erfaret, at en endnu mørkere magt, Afgrundsrådet, styrer Hammeren gennem de arkane vindsten, der er spredt blandt kultens lejre. Din næste handling, <Name>, vil være rettet mod Afgrundsrådet.\n\nTal med håndværkeren Aurel Guldblad i den østlige del af Cenarion-fæstningen. Hendes færdigheder vil være nødvendige for dette næste træk.", c="<Name>, god dag. Jeg har fået at vide, at du vil måle dig med Afgrundsrådet? Hvis det er tilfældet, så lyt nøje til mine næste ord ..."},
  [8332] = {n="Rådets Hertuger", l="Bring 1 Stort Strålende Skår og 3 Afgrundskamme til Aurel Guldblad i Cenarion-fæstningen.", d="Vi tror, det er muligt at bruge en vindsten til at overraske en hertug fra Afgrundsrådet. For at gøre det må man dog kommunikere gennem vindstenen og overbevise rådet om, at man er en mellemrangerende leder i Tusmørkets Hammer.\n\nEt sådant træk kræver en kopi af kultens statsmedaljon. Jeg kan lave medaljonen, men jeg får brug for et stort strålende skår og de kamme, som Afgrundstemplerne bærer.\n\nBring disse til mig, så klarer jeg resten.", p="Har du skåret og kammene, <Name>? Jeg får brug for dem til at lave tusmørkekultistens statsmedaljon.", c="Ah, meget godt. Jeg har arbejdet på medaljonen – nu med disse sidste ingredienser er jeg færdig om et øjeblik ...\n\nSå var den der. Her er medaljonen, <Name>.\n\nDu skal bære denne, når du aktiverer en af Tusmørkets Hammers vindsten. Tag den på sammen med resten af tusmørkeudstyret, så vil Afgrundsrådet se dig som en af deres kultunderlige."},
  [8341] = {n="Rådets Herrer", l="Bring 5 Store Strålende Skår og 3 Afgrundssignetter til Aurel Guldblad i Cenarion-fæstningen.", d="Herrerne i Afgrundsrådet kan kun tilkaldes gennem de største vindsten, og kun de højst rangerende medlemmer af Tusmørkets Råd må tale med dem. Men ... jeg har fundet en måde at opgradere din forklædning og narre Afgrundsherrerne!\n\nForklædningen kræver en herredømmering, som kun bæres af kultens højeste medlemmer. Jeg kan lave en til dig, hvis du bringer mig store strålende skår og afgrundssignetter.", p="Har du skårene og signetterne, <Name>? Jeg får brug for dem til at lave herredømmeringen.", c="Tak. Vent lige et øjeblik, så er ringen klar til dig ...\n\nDer er den. Nu er du klar.\n\nHusk at bære denne ring sammen med et stationsmedaljon og resten af tusmørkeudstyret, når du aktiverer en større vindsten. Gør du det, vil Afgrundsrådet tro, at du er en af deres tjenere. Så kan du måske lokke en af dem i et baghold!"},
  [8343] = {n="Guldblads Opdagelse", l="Tal med Aurel Guldblad i Cenarion-fæstningen.", d="<Name>, Aurel Guldblad mener, at hun har fundet en måde at tilkalde og besejre et herskende medlem af Afgrundsrådet på! En sådan opgave vil være farlig, men du har fortjent stor respekt blandt Cenarion-kredsen. Vi ved, at hvis nogen kan gøre det, så kan du.\n\nMåtte lykken følge dig, <Name>. Tal med Aurel, når du er klar.", c="Det, Hum siger, er sandt. Jeg tror, jeg ved, hvordan man tilkalder en herre fra Afgrundsrådet! Lyt med, så forklarer jeg ..."},
  [8348] = {n="Hertugernes Signet", l="Bring Afgrundssignetet til Bor Vildmane i Cenarion-fæstningen.", d="Hum fortæller mig, at du har fundet ud af, hvordan man tilkalder Afgrundshertugerne! Det er en rigtig præstation.\n\nVed du hvad, der også ville være en præstation? At smadre en af de ting rigtig godt. Det vil gøre indtryk på deres underordnede, hvis du forstår, hvad jeg mener. Bring dens signet tilbage som bevis på bedriften.", p="Hvordan gik det med Afgrundshertugen? Ramte den hårdt?", c="Jeg vidste, du var en hård <Class>, så snart jeg så dig gå ind i Cenarion-fæstningen. Bliv ved sådan!"},
  [8349] = {n="Bor Vildmane", l="Tal med Bor Vildmane i Cenarion-fæstningen.", d="Nu hvor du har en medaljon og kan tilkalde en Afgrundshertug, så tal med Bor Vildmane. Han vil sætte dig i gang med en opgave mod Afgrundsrådet.\n\nHeld og lykke, <Name>. Og hvis du nogensinde får brug for flere medaljoner, så vend tilbage til mig.", c="Godt at se dig igen, <Class>! Så du fik lavet en medaljon? Godt – den skal du bruge til din næste opgave ..."},
  [8351] = {n="Bor vil tale", l="Tal med Bor Vildmanke i Cenarion-fæstningen.", d="Nu hvor du kan forklæde dig som et styrende medlem af Tusmørkerådet, er jeg sikker på, at Bor Vildmanke vil tale med dig. Gå og se ham, og gør dig klar til en meget svær mission...", c="Ja, sådan er det, <Name>. Jeg har en meget hård opgave foran mig..."},
  [8352] = {n="Rådets scepter", l="Bring et Afgrunds-scepter til Bor Vildmanke i Cenarion-fæstningen.", d="Hum og jeg snakkede lige om dig. Han fortæller mig, at du næsten er klar til at prøve kræfter med en Afgrundsherre!\n\nJeg må sige dig, at det er et meget farligt foretagende. Du bør tage forstærkninger med. Og jeg mener ikke en eller to af dine venner, jeg taler om en førsteklasses, kampklar styrke. Hvis dine venner er lige så gode som dig, kan I måske ligefrem besejre den!\n\nHvis I gør det – og jeg vil have bevis, som altid – giver jeg dig en virkelig stor belønning.", p="Nå, hvordan gik det? Jeg ville gøre hvad som helst for selv at forlade min post og kæmpe med et af de væsener!", c="Du... du gjorde det! Du gjorde det, <Name>! Her! Tag den her. Det er den største kiste, vi havde liggende, og jeg har fyldt den med noget af det bedste, vi fandt."},
  [8361] = {n="Afgrunds-kontakter", l="Bor Vildmanke i Cenarion-fæstningen i Silitus vil have dig til at ødelægge en Afgrunds-tempelridder og bringe ham et Afgrunds-våbenskjold som bevis for gerningen.", d="Vi har set Tusmørkets Hammer-kultister udføre ritualer for at tilkalde mægtige elementar-adelsmænd. Vi ved ikke, om det er de væsener, kultisterne tilbeder, eller om de fungerer som mellemmænd for endnu mægtigere kræfter. Én ting er sikkert: de modtager ordrer fra disse elementarer.\n\nJeg vil have dig til at finde en måde at komme i kontakt med en Afgrunds-tempelridder og give den en ordentlig tæsk! Intet får tropperne til at gå i opløsning som at fjerne kommandokæden. Bring bevis med tilbage, mens du er i gang.", p="Fik du gjort arbejdet færdigt?", c="Hah! Det gjorde du, <Name>! Tusmørkets Hammer bliver snart knust!"},
  [8365] = {n="Sørøver-hatte, ahoi!", l="Hovmodige Modist vil have dig til at samle 20 Sydhavs-pirathatte og bringe dem tilbage til hende i Dampsnedig Portvin i Tanaris.", d="Er du den hjælp, Kartellet sendte? Jeg regner med, at du duer. Lyt godt efter, <Class>. Som du ved, er jeg en indkøber af moderigtig påklædning til Azeroths elite. Konger og dronninger, krigshøvdinge og – tja, hvad Horden nu end kalder deres dronninger – de bærer alle det, jeg har valgt er på mode. Og de betaler et vildt beløb for det, hvilket er det bedste ved det.\n\nSå sådan her gør vi. Du tager ned til Tabt Takkelmester-vig og skaffer en masse pirathatte, på hvilken som helst måde. Tror du, du kan klare det?", p="Har du alle 20 hatte? Jeg tror dig ikke, lad mig se dem. De må være i perfekt stand!", c="Åh, du er et sødt væsen, selvom det tog dig længere tid, end jeg er vant til. Denne forsendelse burde give mig en pæn skilling, når jeg har renset og personaliseret hattene. Og eftersom jeg altid gerne belønner godt udført arbejde, her er en lille gave til dig. Jeg foreslår, at du bruger noget af den på et bad, sødeste."},
  [8366] = {n="Sydhavs-rysteriet", l="Sikkerhedschef Bundsnurr i Dampsnedig Portvin i Tanaris vil have dig til at dræbe 10 Sydhavs-pirater, 10 Sydhavs-fribyttere, 10 Sydhavs-havnearbejdere og 10 Sydhavs-sabelsvingere.", d="Av! De vil have det umulige af mig!\n\nDampsnedig-kartellet vil have mig til at lære Sydhavs-piraterne en lektie. Problemet er, at jeg ikke kan være to steder på én gang; jeg må blive her for at holde freden.\n\nI den seneste tid har piraterne ignoreret de beskyttelsespenge, kartellet regelmæssigt pønser ud med. Så jeg vil gerne midlertidigt gøre dig til min stedfortræder og sende dig derned for at vise dem, hvad det vil sige at rode med os.\n\nDu finder dem i Tabt Takkelmester-vig, som ligger ikke så langt mod syd. Tak, <Name>, jeg står i gæld til dig!", p="Er du tilbage så hurtigt? Jeg håber, du lærte de Sydhavs-slyngler en lektie, de ikke hurtigt glemmer.", c="<Name>! Du er mand for opgaven!!!\n\nJeg er sikker på, at kartellet vil slappe af over for mig, nu hvor du har taklet det Sydhavs-pakket. Lad mig se, hvad jeg kan give dig i belønning? Hvad med en lille skilling, og du kan vælge en af disse for din besvær?"},
  [8367] = {n="For stor ære", l="Bring 3 Alterac-dalens Æresmærker, 3 Arathi-bækkenets Æresmærker og 3 Krigssangskløftens Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="At tjene Horden i en af de store kampe mod Alliancen er en kilde til stor ære! De få, der har tjent Horden på ALLE vores aktive fronter, er dog vores virkelig store krigere. Vi skal besejre vores modstandere, ikke ved at kæmpe isolerede små træfninger, men ved at føre en veloverlagt krig.\n\nGå frem og knus Alliancen i Arathi-bækkenet, Alterac-dalen og Krigssangskløften! For æren! For Horden!", p="Arathi er stadig gennemvædet af store krigeres blod, og stålets klang runger stadig over hele Alterac. Spild ikke min tid, medmindre du bringer nyheder fra fronten!", c="Dine prøvelser har ikke været lette, men dit mod svigtede dig ikke, og din styrke slog ikke fejl. Skil dig af med de gamle sejrstegn, <Class>. Ingen skal have brug for dem som påmindelse om din værdi. Ret ryggen, <Name>. I dag går du med stor stolthed, for du er en helt!"},
  [8368] = {n="Slaget ved Krigssangskløften", l="Bring 3 Krigssangskløftens Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Kampen i Krigssangskløften mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, forsøger Alliancen at nægte Horden en af vores største kilder til træ.\n\nLad ikke det ske, <Name>! Kom tilbage til mig med bevis for, at du har tjent Horden på en værdig måde!", p="Har du nyheder fra Krigssangskløften, <Name>?", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssangskløften! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8369] = {n="Angriberne i Alterac-dalen", l="Bring 3 Alterac-dalens Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Hør efter, <Name>. Uanset hvad du måtte have hørt om slaget, der raser i Alterac-dalen, er én ting stadig sand: Stormspids-ekspeditionen invaderede Frostulvenes Territorium. Den dag, vi lader Alliancen invadere Hordens lande uden et kraftigt svar, er den dag, jeg hænger min økse på væggen og lever resten af mit liv i skam. Gå frem og driv angriberne ud!", p="Hvilke nyheder bringer du fra Frostulvenes lande? Hvordan står det til med kampen om Alterac-dalen?", c="Du har vist stort mod ved at beskytte vores lande i Alterac-dalen! Jeg vil fortælle mine overordnede om dine bedrifter."},
  [8370] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Vores konflikt med Alliancen er eskaleret til en ægte krig. Ingen af siderne bruger eller forventer længere falske påskud for at gå i kamp.\n\nKampen om Arathi-bækkenet handler om ressourcer, ganske enkelt. Enten får Alliancen ressourcerne og bruger dem mod os, eller også får vi dem og bruger dem til at holde vores krigsindsats i gang. Hjælp Skænderne med at holde strømmen af de ressourcer, vi har brug for, <Name>!", p="Er du kommet tilbage med nyheder fra Arathi, <Class>?", c="At sikre vores ressourcer i Arathi er en vigtig opgave! Du har gjort det godt, <Name>."},
  [8371] = {n="Fælles indsats", l="Bring 3 Alterac-dalens Æresmærke, 3 Arathi-bækkenets Æresmærke og 3 Krigssangskløftens Æresmærke til en Alliance-brigadergeneral uden for slagmarkerne.", d="Vi kæmper ikke længere isolerede slag mod Horden, knægt.\n\nSejr på én front betyder at nægte Horden de ressourcer, de ellers ville bruge mod os i et andet slag. På samme måde kan tab i ét slag give vores modstander fordel et helt andet sted i verden.\n\nAlliancen har brug for flere kæmpere med denne slags verdensforståelse... virkelig rutinerede veteraner! <Name>, kom tilbage til mig, når du har kæmpet mod Horden på alle vores aktive slagmarker.", p="Hvordan går rejsen, knægt?", c="Du er ikke en, der skuffer, <Name>! Det, du har lært, rækker længere end små medaljer og anbefalinger. Det, du har lært, er noget, der kun kan komme med erfaring og med at ens temperament hærdes på slagmarken.\n\nDu har gjort det godt, <Class>. Du er en sand helt for Alliancen!"},
  [8372] = {n="Kampen om Krigssangskløften", l="Bring 3 Krigssangskløftens Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forårsager i skoven. Der er dog flere grunde til at forsvare netop denne skov end blot ren kærlighed til naturen.\n\nSkoven udgør en strategisk barriere, der gør Askedalen til et forsvarligt område mod et angreb i stor skala. Uden den ville Stjernelund holde i en dag eller to, før den blev annekteret til Ødemarken.\n\nGør din del i kampen mod Krigssang-forposterne, <Name>! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt gjort, <Name>! Du har tjent Alliancen godt."},
  [8374] = {n="Tilegnelsen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="At vinde en krig handler om mere end at overlister og overkæmpe sin modstander. Sejren kommer ofte ned til simpelthen at producere mere end din fjende.\n\nDet, vi har i Arathi-bækkenet, er en betydelig forsyning af ressourcer til den side, der først formår at tage det.\n\nHvis Alliancen går af med sejren, betyder det flere sværd og spyd til vores tropper. Hvis Horden vinder, ville de sværd og spyd stadig blive lavet, de ville bare blive rettet mod os! Nu er det tid til at hjælpe Alliancen i Arathi-bækkenet, <Name>.", p="Fortæl mig, hvilke nyheder der er fra fronten?", c="Godt arbejde, soldat! Bliv ved sådan, så får vi Horden til at løbe hele vejen tilbage til Orgrimgrad."},
  [8375] = {n="Husk Alterac-dalen!", l="Bring 3 Alterac-dalens Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Lad der ikke være tvivl, <Name>. Horden har ganske ret, når de siger, at Alterac-dalen er Frostulvenes Territorium.\n\nDu ser, Stormspids-ekspeditionen ankom som fredelige besøgende i området på jagt efter malm og relikvier. Frostulvene reagerede med den mest brutale og uciviliserede form for aggression, Alliancen nogensinde har oplevet.\n\nLad os aldrig glemme de modige dværge, der omkom i det feige, uanmeldte angreb. Gå nu, <Class>, og gør din del i kampen om Alterac-dalen. For Alliancen!", p="Hvilke nyheder bringer du, <Name>?", c="Du har gjort din del, <Name>. Alliancen kan ikke lade Hordens uciviliserede handlinger stå uimodsagt!"},
  [8376] = {n="Oprustning til Krig", c="Krigen kommer, <Name>, og med den kommer utallige rædsler. Du har gjort alt, hvad der kunne forventes af dig, og for det bør du belønnes.\n\nSkulle dette... denne profeti nogensinde gå i opfyldelse...\n\n<Geolog Lærkebane bliver bleg.>\n\nFremtiden for os alle kunne være ved at ende.\n\nDenne oprustning vil vise sig uvurderlig for din kampagne i denne ørken."},
  [8377] = {n="Oprustning til Krig", c="Krigen kommer, <Name>, og med den kommer utallige rædsler. Du har gjort alt, hvad der kunne forventes af dig, og for det bør du belønnes.\n\nSkulle dette... denne profeti nogensinde gå i opfyldelse...\n\n<Geolog Lærkebane bliver bleg.>\n\nFremtiden for os alle kunne være ved at ende.\n\nDenne oprustning vil vise sig uvurderlig for din kampagne i denne ørken."},
  [8378] = {n="Oprustning til Krig", c="Krigen kommer, <Name>, og med den kommer utallige rædsler. Du har gjort alt, hvad der kunne forventes af dig, og for det bør du belønnes.\n\nSkulle dette... denne profeti nogensinde gå i opfyldelse...\n\n<Geolog Lærkebane bliver bleg.>\n\nFremtiden for os alle kunne være ved at ende.\n\nDenne oprustning vil vise sig uvurderlig for din kampagne i denne ørken."},
