  [8382] = {n="Oprustning til Krig", c="Krigen kommer, <Name>, og med den kommer utallige rædsler. Du har gjort alt, hvad der kunne forventes af dig, og for det bør du belønnes.\n\nSkulle dette... denne profeti nogensinde gå i opfyldelse...\n\n<Geolog Lærkebane bliver bleg.>\n\nFremtiden for os alle kunne være ved at ende.\n\nDenne oprustning vil vise sig uvurderlig for din kampagne i denne ørken."},
  [8393] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="At vinde en krig handler om mere end at overlister og overkæmpe sin modstander. Sejren kommer ofte ned til simpelthen at producere mere end din fjende.\n\nDet, vi har i Arathi-bækkenet, er en betydelig forsyning af ressourcer til den side, der først formår at tage det.\n\nHvis Alliancen går af med sejren, betyder det flere sværd og spyd til vores tropper. Hvis Horden vinder, ville de sværd og spyd stadig blive lavet, de ville bare blive rettet mod os! Nu er det tid til at hjælpe Alliancen i Arathi-bækkenet, <Name>.", p="Fortæl mig, hvilke nyheder der er fra fronten?", c="Godt arbejde, soldat! Bliv ved sådan, så får vi Horden til at løbe hele vejen tilbage til Orgrimgrad."},
  [8394] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="At vinde en krig handler om mere end at overlister og overkæmpe sin modstander. Sejren kommer ofte ned til simpelthen at producere mere end din fjende.\n\nDet, vi har i Arathi-bækkenet, er en betydelig forsyning af ressourcer til den side, der først formår at tage det.\n\nHvis Alliancen går af med sejren, betyder det flere sværd og spyd til vores tropper. Hvis Horden vinder, ville de sværd og spyd stadig blive lavet, de ville bare blive rettet mod os! Nu er det tid til at hjælpe Alliancen i Arathi-bækkenet, <Name>.", p="Fortæl mig, hvilke nyheder der er fra fronten?", c="Godt arbejde, soldat! Bliv ved sådan, så får vi Horden til at løbe hele vejen tilbage til Orgrimgrad."},
  [8395] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="At vinde en krig handler om mere end at overlister og overkæmpe sin modstander. Sejren kommer ofte ned til simpelthen at producere mere end din fjende.\n\nDet, vi har i Arathi-bækkenet, er en betydelig forsyning af ressourcer til den side, der først formår at tage det.\n\nHvis Alliancen går af med sejren, betyder det flere sværd og spyd til vores tropper. Hvis Horden vinder, ville de sværd og spyd stadig blive lavet, de ville bare blive rettet mod os! Nu er det tid til at hjælpe Alliancen i Arathi-bækkenet, <Name>.", p="Fortæl mig, hvilke nyheder der er fra fronten?", c="Godt arbejde, soldat! Bliv ved sådan, så får vi Horden til at løbe hele vejen tilbage til Orgrimgrad."},
  [8396] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="At vinde en krig handler om mere end at overlister og overkæmpe sin modstander. Sejren kommer ofte ned til simpelthen at producere mere end din fjende.\n\nDet, vi har i Arathi-bækkenet, er en betydelig forsyning af ressourcer til den side, der først formår at tage det.\n\nHvis Alliancen går af med sejren, betyder det flere sværd og spyd til vores tropper. Hvis Horden vinder, ville de sværd og spyd stadig blive lavet, de ville bare blive rettet mod os! Nu er det tid til at hjælpe Alliancen i Arathi-bækkenet, <Name>.", p="Fortæl mig, hvilke nyheder der er fra fronten?", c="Godt arbejde, soldat! Bliv ved sådan, så får vi Horden til at løbe hele vejen tilbage til Orgrimgrad."},
  [8399] = {n="Kampen om Krigssangskløften", l="Bring 3 Krigssangskløftens Æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forårsager i skoven. Der er dog flere grunde til at forsvare netop denne skov end blot ren kærlighed til naturen.\n\nSkoven udgør en strategisk barriere, der gør Askedalen til et forsvarligt område mod et angreb i stor skala. Uden den ville Stjernelund holde i en dag eller to, før den blev annekteret til Ødemarken.\n\nGør din del i kampen mod Krigssang-forposterne, <Name>! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt arbejde, <Name>. Takket være dig vil vores naturlige forsvar i Askedalen forblive intakt i endnu en dag."},
  [8400] = {n="Kamp om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forvolder i skoven. Der er dog flere grunde til at forsvare netop denne skov end blot ren kærlighed til naturen.\n\nSkoven danner en strategisk barriere, der gør Askedalen forsvarlig mod et storstilet angreb. Uden den ville Stjernelund holde ud en dag eller to, før den blev annekteret til Ødemarken.\n\nGør din del i kampen mod Krigssang-forposterne, <Name>! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt gjort, <Name>! Du har tjent Alliancen godt."},
  [8401] = {n="Kamp om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forvolder i skoven. Der er dog flere grunde til at forsvare netop denne skov end den bevaringsfilosofi, Sølvvingerne går ind for.\n\nSkoven danner en strategisk barriere, der gør Askedalen forsvarlig mod et storstilet angreb. Uden den ville Stjernelund holde ud en dag eller to, før den blev annekteret til Ødemarken. Gør din del i kampen mod Krigssang-forposterne! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt arbejde, <Name>. Takket være dig vil vores naturlige forsvar i Askedalen forblive intakt endnu en dag."},
  [8402] = {n="Kamp om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forvolder i skoven. Der er dog flere grunde til at forsvare netop denne skov end blot ren kærlighed til naturen.\n\nSkoven danner en strategisk barriere, der gør Askedalen forsvarlig mod et storstilet angreb. Uden den ville Stjernelund holde ud en dag eller to, før den blev annekteret til Ødemarken.\n\nGør din del i kampen mod Krigssang-forposterne, <Name>! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt gjort, <Name>! Du har tjent Alliancen godt."},
  [8403] = {n="Kamp om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Alliance-brigadergeneral uden for slagmarkerne.", d="Sølvvinge-vagterne er i krig med Krigssang-forposterne på grund af den ødelæggelse, orkerne forvolder i skoven. Der er dog flere grunde til at forsvare netop denne skov end blot ren kærlighed til naturen.\n\nSkoven danner en strategisk barriere, der gør Askedalen forsvarlig mod et storstilet angreb. Uden den ville Stjernelund holde ud en dag eller to, før den blev annekteret til Ødemarken.\n\nGør din del i kampen mod Krigssang-forposterne, <Name>! For Alliancen!", p="Er du kommet tilbage med nyheder fra fronten, <Name>?", c="Godt gjort, <Name>! Du har tjent Alliancen godt."},
  [8409] = {n="Ødelagte Fade", l="Vend tilbage til Mørkeråbet Yanka ved Halmmands-festivalen i Tirisfal-lysningen.", d="De rådne æg er med held blevet placeret i fadet. Fremtidige partier øl fra Sydstrandens Kro er helt sikkert ødelagt!\n\nDu bør nu vende tilbage til Mørkeråbet Yanka ved Halmmands-festivalen i Tirisfal-lysningen og melde din succes.", c="Ah, succes! Du har vist sand Helligaftens Ende-ånd - FORLADT ånd, skulle jeg snarere sige!\n\n<Mørkeråbet Yanka ler og gnider hænderne sammen.>\n\nJeg nyder tanken om, at Sydstranden nu må gilde på dårligt øl eller gå uden! Og du, tag disse godbidder. Jeg tror, du vil finde god brug for dem!"},
  [8410] = {n="Elementar-mestring", l="Saml en prøve af luft, ild, jord og vand til Bath'rah Vindvogteren.", d="Bath'rah Vindvogteren har udsendt et kald efter en shaman med din visdom. Han beder dig om at bringe en prøve af hvert element for at vise, at du er klar.\n\nFor at finde Bath'rah skal du gå til floden øst for Tarrenmølle. Følg floden nordpå, indtil du støder på ruinerne, hvor Bath'rah bor.", p="Hvad har du til mig, <Class>?", c="Fremragende, makker. Nu taler vi sammen."},
  [8411] = {n="Mestring af elementerne", l="Bring elementerne jord, luft, ild og vand til Bath'rah Vindvogteren.", d="Velkommen, makker. Du bringer mig elementerne, og så taler vi sammen.", p="Hvor er elementerne, makker?", c="Det er de elementer, jeg har brug for. Nu taler vi."},
  [8412] = {n="Åndetotem", l="Bring delene til åndetotemet til Bath'rah Vindvogteren.", d="De elementare ånder på dette sted kan ikke længere lide mig.\n\nDu ved mere om totemer end nogen, og jeg har brug for et åndetotem til at beskytte mig. Vi har allerede elementerne, nu skal vi bruge noget mere med mere natur. Mere urkraftigt.\n\nI De Vestlige Pestlande kan du dræbe bjørne for kløer og edderkopper for deres øjne. Ådselfuglene spiser alt, så de har måske begge dele.", p="Ånderne ved, hvad vi har gang i, og de har forsøgt at dræbe mig! Jeg håber, du har delene.", c="Fremragende, makker! Lad os prøve det af...."},
  [8413] = {n="Den Voodoo", l="Bring voodoo-fjerene til Bath'rah Vindvogteren.", d="Åndetotemet er bare ikke nok. Vi skal bruge noget voodoo-magi for at få det til at virke ordentligt.\n\nTrollene i det sunkne tempel har fjer, der er fyldt med voodoo-magi. Tag derhen og dræb Opskærer, Mijanne, Zoloo, Hukkuu, Zul'lør og Lorro. Så har vi magi nok til et ægte åndetotem.", p="Hvor er fjerene, makker?", c="Det var på tide, at denne trold fik en hel nats søvn! Åndetotemet vil vogte over mig.\n\nJeg har samlet ting i lang tid, måske vil du have noget for al besværet?"},
  [8414] = {n="Afsværgelse af det onde", l="Saml 20 Håndlangerens Geislesten og bring dem til Ypperstepræst Thel'dannis i De Vestlige Pestlande.", d="Hilsner, <Class>. Korsfarere som dig er et velkomment syn i disse øde egne.\n\nDin hellige styrke er nødvendig for at hjælpe med at kæmpe mod de endeløse udøde her. Vi har brug for, at du samler et stort antal geislesten og bringer dem til Ypperstepræst Thel'dannis. Ypperstepræsten kan findes og vogter Uthers grav i Sorgbakken, ikke langt herfra.\n\nKun en, der har et Sølvdæmringens Hverv, kan håbe på at finde geislesten, så tal med Officer Renhjerte, hvis du ikke allerede har gjort det.", p="Hvilket ondt har du bragt mig?", c="Der er en risiko ved at fordrive det onde fra en geisleste, for det tiltrækker de udødes opmærksomhed i utallige mil. Men du er stærk i Lyset, <Name>, og jeg frygter ikke for dig..."},
  [8415] = {n="Kuldevind-pegen", l="Tal med Kommandør Ashlam Tapperhedsnæve ved Kuldevind-pegen.", d="Kommandør Ashlam Tapperhedsnæve har udsendt et kald efter en paladin med din renhed og mod, <Name>. Du finder ham ved Kuldevind-pegen i den sydlige del af De Vestlige Pestlande. Søg ham op og hjælp ham i hans sag for Lyset!", c="Meget godt, <Class>! Lad os se, hvad du er gjort af."},
  [8416] = {n="Inerte Geislesten", l="Bring den inerte geisleste til Kommandør Ashlan Tapperhedsnæve i Kuldevind-pegen.", d="Det onde er blevet renset ud af stenene, <Name>.\n\nJeg er klar over Kommandør Ashlams planer, og han har kun brug for en enkelt inert sten. Bring den til ham, så vi kan bade Svøben i retfærdig ild.", p="Var Thel'dannis i stand til at rense geislestenene?", c="Du har gjort, som jeg bad om, uden spørgsmål, <Name>.\n\nTillid er opnået, det synes at være. Måske kan jeg nu afsløre vores plan i flere detaljer for dig."},
  [8417] = {n="En urolig ånd", l="Tal med den Hordens Faldne Helt ved indgangen til Det Sønderrevne Land.", d="I Det Sønderrevne Land findes en urolig ånd, der engang var en stor helt for Horden. En krigers ære dør ikke med kroppen, og det vil gavne dig at tale med ham.", p="Fik Stoley hostet min sprit op?", c="Så, du er kommet for at lindre min smerte. Jeg ønsker, du bare kunne slå mig ned, men sådan er det ikke så enkelt..."},
  [8418] = {n="Smedning af Mægtighedstenen", l="Bring voodoo-fjerene til Ashlam Tapperhedsnæve.", d="Nu må vi kombinere de inerte geislesten og skabe et våben, der kan knuse udøde-rækkerne. Det er ingen triviel opgave, <Name>. Kun trollene i det sunkne tempel bærer den slags sjælden magi, der kan vende noget ondt mod sig selv.\n\nI templet kendes trollene som Opskærer, Mijanne, Zoloo, Hukkuu, Zul'lør og Lorro. Føl ingen anger over deres korrupte sjæle... de er ikke uden ondskab.", p="Har du slået de elendige trolde ihjel?", c="Det her er fremragende, <Name>. Jeg ville sige, at jeg er overrasket, men jeg vidste uden tvivl, at du ikke ville svigte os.\n\nDet er min ære at skænke dig en af de Hellige Mægtighedssten. Brug den godt."},
  [8419] = {n="En dæmonlings anmodning", l="Bring et stykke ondskabsstof til Dæmonsen i Ondskoven.", d="<Name>, en dæmonling i Ondskoven ved navn Dæmonsen har bedt om din tilstedeværelse. Det er lidt mærkeligt, for han har bedt dig om at bringe et stykke ondskabsstof som tegn på god vilje. Når man tager den magt i betragtning, du allerede besidder som hekser, må jeg antage, at du ved, at satyrerne i Ondskoven bærer dette ondskabsstof.\n\nDu finder Dæmonsen lige nord for Blodgift-faldene, som jeg har hørt er ganske smukke på denne årstid.", p="Har du mit ondskabsstof?", c="For en vidunderlig <Class> du er!\n\n<Dæmonsen holder ondskabsstoffet op til ansigtet.>\n\nÅh, hvor jeg elsker følelsen af det, måden det brænder din hud på og væver onde tanker ind i sindet..."},
  [8420] = {n="Hed og kløende", l="Bring et stykke ondskabsstof til Dæmonsen i Ondskoven.", d="Måske lyder det mærkeligt fra en dæmonling, men jeg vil gerne have et kæledyr af mit eget. Det vil jeg virkelig. Det er bare ikke retfærdigt, at Nibby får mig, og jeg får intet!\n\nFaktisk behøver det ikke engang at være et levende kæledyr. Jeg skal bruge noget at begynde at lave det med, som noget ondskabsstof. Satyrerne her i Ondskoven har nogle gange ondskabsstof, så du må bare dræbe nok af dem, indtil du finder noget. Det lyder ikke så slemt, vel?", p="Har du mit ondskabsstof?", c="Wow! Du er for venlig. Især for en hekser!\n\n<Dæmonsen holder ondskabsstoffet op til ansigtet.>\n\nÅh, hvor jeg elsker følelsen af det, måden det brænder din hud på og væver onde tanker ind i sindet..."},
  [8421] = {n="Det Forkerte Stof", l="Bring 10 rådnende træ og 4 Blodgift-essens til Dæmonsen i Ondskoven.", d="Nu hvor jeg har mit ondskabsstof, kan jeg virkelig begynde at lave *mit* kæledyr.\n\nDet får brug for nogle øjne, dog. Måske kunne du rive noget rådnende træ fra jerntræ-folkene for mig, så jeg kan skære nogle dejlige øjne ud. De er oppe mod nord i Jerntræ-skovene.\n\nJeg skal også bruge lidt Blodgift-essens for at give det den nye dæmonlugt. De forurenede slimvæsner bærer essensen, og de hænger ud lige her ved Nibby og mig.", p="Har du varerne?", c="Dette vil virke så utroligt godt."},
  [8422] = {n="Trolde af en fjer", l="Bring i alt 6 Voodoo-fjer fra trolde i det sunkne tempel.", d="Mit kæledyr er næsten færdigt. Nu mangler jeg bare noget at stoppe det med.\n\nKun voodoo-fjerene fra trollene i det sunkne tempel duer. De går under navnene Opskærer, Mijanne, Zoloo, Hukkuu, Zul'lør og Lorro. Dræb dem. Dræb dem alle.\n\nDette er ingen triviel opgave <Name>, så jeg gør det det værd for dig ved at give dig noget af Nibbys -- han har nok ikke brug for det alligevel.", p="Har du bragt fjerene? Denne dukke skal stoppes!", c="Vidunderligt, nu er mit kæledyr færdigt!\n\n<Dæmonsen stopper hurtigt dukken og giver den et dæmonisk kram.>\n\nÅh, hvilken underlig bivirkning voodoo-fjerene har..."},
  [8423] = {n="Krigerslægtskab", l="Dræb 7 helvildsvin i Det Sønderrevne Land og vend tilbage til den Hordens Faldne Helt.", d="<Helten betragter dig.>\n\nDu er en <Class>, uden tvivl. Jeg ville bede dig om en hædefuld opgave, men jeg må først teste din styrke.\n\nDet siges, at Rexar ville måle skarpheden af sine klinger ved at dræbe et helvildsvin med et enkelt, hurtigt hug. Nu vil jeg måle din styrke ved at dræbe dem.", p="De brændende torne fra helvildsvinene efterlader forfærdelige ar. Frygt ikke smerten og lemlæstelsen, kriger, de er ingenting sammenlignet med fængslet, jeg er bundet til.", c="Jeg har intet bevis brug for for at vide, hvad du har gjort, <Class>. Jeg kan se besluttsomheden indgraveret i dit udtryk."},
  [8424] = {n="Krig mod Skyggesvoren", l="Slagt Skyggesvoren i Det Sønderrevne Land og vend tilbage til den Hordens Faldne Helt.", d="Skyggesvorens vedvarende tilstedeværelse i Det Sønderrevne Land bringer mig stor smerte. Deres mørke ritualer og besværgelser forvolder en pine, ulig noget, jeg følte, mens jeg levede.\n\nGennem dig kan jeg overbringe mit eget budskab om smerte. Gå afsted og lever min vrede.", p="Skyggesvoren er ikke let at besejre, vel? Men du er kriger, og du vil triumfere eller gå til grunde under forsøget.", c="Allerede har du dæmpet min smerte og æret mig. Tak, <Class>."},
  [8425] = {n="Voodoo-fjer", l="Bring Voodoo-fjerene fra trollene i Det Sunkne Tempel til den Hordens Faldne Helt.", d="Din ære har bragt lidt fred til mig. Det er kun rimeligt, at jeg tilbyder dig noget til gengæld.\n\nMine våben og rustning var prægtige i livet, men de er ingen nytte for mig nu. De ville være bedre brugt i din besiddelse.\n\nRejs til det sunkne tempel og ødelæg trolde-vogterne Opskærer, Mijanne, Zoloo, Hukkuu, Zul'lør og Lorro. De bærer magiske fjer, der kan genskabe min fysiske krop længe nok til at give dig en belønning.", p="Er du tilbage så hurtigt? Tiden er ikke den samme for mig længere, måske har det virkelig været en lang rejse for dig...", c="Endelig kan jeg mærke stålets kolde berøring igen, selv om det kun er et øjeblik."},
  [8426] = {n="Slaget om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", p="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssang-Gulch! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8427] = {n="Slaget om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", p="Har du nyheder fra Krigssang-Gulch, <Name>?", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssang-Gulch! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8428] = {n="Slaget om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", p="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssang-Gulch! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8429] = {n="Slaget om Krigssang-Gulch", l="Bring 3 Krigssang-Gulch-æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", p="Slaget i Krigssang-Gulch mod Sølvvinge-vagterne er af stor betydning. Under dække af at beskytte en skov, der ikke tilhører dem, søger Alliancen at frakende Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssang-Gulch! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8430] = {n="Slaget om Krigssangskløften", l="Bring 3 Krigssangskløften-æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Kampen i Krigssangskløften mod Sølvvinge-vagterne er af stor betydning. Under påskud af at beskytte en skov, der ikke tilhører dem, forsøger Alliancen at berøve Horden en af vores største kilder til tømmer.\n\nLad ikke dette ske, <Name>! Kom tilbage til mig med bevis for, at du tjener Horden på en værdig måde!", p="Har du nyt fra Krigssangskløften, <Name>?", c="Fremragende! Du har vist din værdi ved at forsvare vores operationer i Krigssangskløften! Må ordet om din ære brede sig vidt og bredt over vores lande."},
  [8436] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Vores konflikt med Alliancen er eskaleret til en ægte krig. Ingen af siderne bruger længere falske påskud for at gå i kamp, og det forventes heller ikke på dette stadie.\n\nSlaget om Arathi-bækkenet handler om ressourcer, rent og skært. Enten får Alliancen ressourcerne og bruger dem mod os, eller også får vi dem og bruger dem til at holde vores krigsindsats i gang. Hjælp Skænderne med at opretholde strømmen af de ressourcer, vi har brug for, <Name>!", p="Du er kommet tilbage med nyt fra Arathi, <Class>?", c="At sikre vores ressourcer i Arathi er en vigtig opgave! Du har klaret det godt, <Name>."},
  [8437] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Vores konflikt med Alliancen er eskaleret til en ægte krig. Ingen af siderne bruger længere falske påskud for at gå i kamp, og det forventes heller ikke på dette stadie.\n\nSlaget om Arathi-bækkenet handler om ressourcer, rent og skært. Enten får Alliancen ressourcerne og bruger dem mod os, eller også får vi dem og bruger dem til at holde vores krigsindsats i gang. Hjælp Skænderne med at opretholde strømmen af de ressourcer, vi har brug for, <Name>!", p="Du er kommet tilbage med nyt fra Arathi, <Class>?", c="At sikre vores ressourcer i Arathi er en vigtig opgave! Du har klaret det godt, <Name>."},
  [8438] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Vores konflikt med Alliancen er eskaleret til en ægte krig. Ingen af siderne bruger længere falske påskud for at gå i kamp, og det forventes heller ikke på dette stadie.\n\nSlaget om Arathi-bækkenet handler om ressourcer, rent og skært. Enten får Alliancen ressourcerne og bruger dem mod os, eller også får vi dem og bruger dem til at holde vores krigsindsats i gang. Hjælp Skænderne med at opretholde strømmen af de ressourcer, vi har brug for, <Name>!", p="Du er kommet tilbage med nyt fra Arathi, <Class>?", c="At sikre vores ressourcer i Arathi er en vigtig opgave! Du har klaret det godt, <Name>."},
  [8439] = {n="Erobringen af Arathi-bækkenet", l="Bring 3 Arathi-bækkenets Æresmærker til en Horde-krigsbringer uden for slagmarkerne.", d="Vores konflikt med Alliancen er eskaleret til en ægte krig. Ingen af siderne bruger længere falske påskud for at gå i kamp, og det forventes heller ikke på dette stadie.\n\nSlaget om Arathi-bækkenet handler om ressourcer, rent og skært. Enten får Alliancen ressourcerne og bruger dem mod os, eller også får vi dem og bruger dem til at holde vores krigsindsats i gang. Hjælp Skænderne med at opretholde strømmen af de ressourcer, vi har brug for, <Name>!", p="Du er kommet tilbage med nyt fra Arathi, <Class>?", c="At sikre vores ressourcer i Arathi er en vigtig opgave! Du har klaret det godt, <Name>."},
  [8446] = {n="Tilsløret i Mare", l="Find en, der er i stand til at tyde betydningen bag det mareomslyngede objekt.\n\nMåske kunne en druide med stor magt hjælpe dig.", d="Fordærvelse sive ud fra dette objekt.\n\nDer kan være en forbindelse mellem dette objekt og de drager, der kommer frem fra Drømmen. Du må finde en, der kan tyde betydningen af denne genstand. Måske kunne druiderne i Månelunden eller Cenarion-fæstningen hjælpe dig yderligere.", p="Ja, <Race>?", c="Jeg må fjerne fordærvelsen fra dette objekt. Det kan kaste lys over mine seneste fiaskoer med at dykke ned i Drømmen. Giv det til mig."},
  [8447] = {n="Vågnende legender", l="Vent på Vogter Remulos i Månelunden, så han kan rense det mareomslyngede objekt.", d="Vandene i Elune'ara-søen bør opløse mareerne, der omslutter dette objekt. Giv mig et øjeblik til at udføre renselsen, <Name>.", c="Tag hans ring, <Name>. Den har tjent sit formål for Malfurjon. Nu skal den tjene et nyt formål for dig..."},
  [8460] = {n="Tømmergab-alliancen", l="Grasle vil have dig til at bevise dig selv ved at dræbe 6 Dødtræ-krigere, 6 Dødtræ-stifindere og 6 Dødtræ-gartnere. Vend tilbage til ham i det sydlige Ondskoven nær Smaragd Fristed, når du er færdig.", d="Tømmergab er den eneste pelsbolg-stamme, der undslap fordærvelsen. Mange andre racer dræber dog pelsbolge uden omtanke nu, uden at bryde sig om, om de er venner eller fjender. Af den grund har Tømmergab-pelsbolgene kun tillid til meget få.\n\nEr du interesseret i at bevise dig selv? Driv den fordærvede Dødtræ-stamme i Ondskoven tilbage, så vil vi måske en dag betragte dig som en allieret. Du finder den første Dødtræ-stamme - krigere, stifindere og gartnere - mod vest herfra.", p="Bliv ved, <Name>. Hvis du skal vinde vores tillid, må du bevise dig over for os.", c="Vi lider meget under fortidens begivenheder. Tak for det, du har gjort for at beskytte Tømmergab. Som et tegn på vores voksende venskab, så modtag venligst dette ydmyge offer."},
  [8461] = {n="Dødtræet i nord", l="Nafjen vil have dig til at dræbe 6 Dødtræ-hulevagter, 6 Dødtræ-hævnere og 6 Dødtræ-shamaner. Vend tilbage til ham i det nordlige Ondskoven nær indgangen til Tømmergab-fæstningen.", d="Der er en lejr med Dødtræ-pelsbolge lige sydvest for os. Fordærvelsen gennemsyrer lejren, og jeg ønsker at gøre ende på den, før de bliver et problem.\n\nDødtræ-stammen er ond, men det er fel-kraften, der forurener deres sind. Deres fjendtlighed er ikke en iboende egenskab, men de kan ikke hjælpes. Det smerter mig, at vi må kæmpe mod vore egne brødre.\n\nVær venlig, <Name> - jeg beder dig om at gøre, hvad der må gøres. Spar mig blot for detaljerne; sådanne besværlige billeder oprører mig alt for meget.", p="Når du har vundet Tømmergabs tillid, er jeg sikker på, at der er noget, vi kan gøre for dig. Tømmergab glemmer ikke deres allierede, især ikke i mørke tider som disse.", c="Jeg fornemmer, at du har opnået sejr. Sejr... et så hult ord, når man tænker på, hvad der måtte gøres. Uanset det har du bevist, at du er værdig til vores tillid.\n\nDet kan tage noget tid, før Tømmergab byder dig velkommen uden fjendtlighed inde i fæstningen. Men din udholdenhed vil udviske enhver mistanke, mine brødre måtte have om dig. Så længe du aldrig forråder os og rejser våben mod os, vil vi finde fælles grund."},
  [8462] = {n="Tal med Nafjen", l="Rejs nordpå ad hovedvejen i Ondskoven og tal med pelsbolgen ved navn Nafjen. Han står vagt uden for indgangen til Tømmergab-fæstningen.", d="Måske er du i stand til at håndtere en større trussel, som vi i Tømmergab står over for. Du har bestemt vist dig dygtig her...\n\nEn anden af mit folk står vagt uden for indgangen til Tømmergab-fæstningen, langs denne vej langt mod nord. Hans navn er Nafjen; selvom han måske virker som et vildt og usympatisk udyr, skal du ikke frygte ham. Han søger blot hjælp mod de onde kræfter, der truer vores hjem.", c="Ah... Jeg har hørt vinden bringe ord om dem, der ikke er af vores stamme, og som søger at alliere sig med Tømmergab-pelsbjørnene. Jeg byder dig velkommen, men du må vide, at min stamme reagerer dårligt på fremmede.\n\nDet er triste tider, og vi kan kun stole på dem, der vælger at kæmpe mod landets fordærvelse side om side med os... og som har bevist sig over for os. Dem, der ikke har gjort det, vil møde åben fjendtlighed, hvis de træder ind i fæstningen."},
  [8464] = {n="Vinterfald-aktivitet", l="Salvie vil have dig til at dræbe 8 Vinterfald-shamaner, 8 Vinterfald-hulevagter og 8 Vinterfald-bjørne. Salvie befinder sig lige uden for indgangen til Tømmergab-fæstningen i Vinterkilde.", d="Tømmergab holder sig for sig selv, <Name>. Selvom vi tillader sikker passage for dem, vi stoler på, forsøger vi at undgå andre pelsbolg-stammer, hvis det overhovedet er muligt.\n\nVinterfald-stammen er på det seneste blevet stadig mere fjendtlig over for os. De synes at være i en raserianfald, fuldstændig opslugt af deres egen frygt og had til alt, de ikke forstår.\n\nJeg må bede dig om at tynde ud i deres rækker for at mindske truslen mod os. Søg dem i Vinterfald-landsbyen, langt mod øst herfra.", p="Vi sætter stor pris på det, du har gjort for Tømmergab, <Name>. Dine fortsatte bestræbelser vil helt sikkert vinde min stammes tillid og respekt.", c="Tak for det, du har gjort, lige så sørgeligt det end er. Modtag dette som et tegn på taknemmelighed.\n\nJeg vil bede dig om at fortsætte med at hjælpe os, <Name>. Vi har meget få allierede at henvende os til, og uden din hjælp ville truslerne mod min stamme helt sikkert være for meget for os at klare alene."},
  [8465] = {n="Tal med Salvie", l="Rejs gennem Tømmergab-fæstningen og gå ud i Vinterkilde. Tal med Salvie, der står vagt uden for indgangen til Tømmergab-fæstningen.", d="Fordærvelsens trussel kommer ikke kun fra Dødtræ-pelsbolgene mod syd, men også fra øst og Vinterfald-pelsbolgene i Vinterkilde. Hvis du ønsker at hjælpe os yderligere, så tal med Salvie på den anden side af fæstningen, ved indgangen til Vinterkilde. Følg stien til venstre for at nå hen til ham.\n\nVær advaret - hvis mit folk inde i fæstningen anser dig for fjendtlig eller hadet, vil de angribe. Rejs så hurtigt du kan, og undgå konflikt. At dræbe en Tømmergab - selv i selvforsvar - vil kun fremmedgøre dig yderligere.", c="Hilsner, <Class> - jeg står vagt her både som talsmand for Tømmergab i Vinterkilde og som forsvarer af stammen.\n\nVores Vinterfald-brødre i dette iskolde land er faldet under samme fordærvende indflydelse som pelsbolgene i Ondskoven. Hvis du er kommet hertil for at tilbyde Tømmergab-pelsbjørnene hjælp, så er vi klar til at modtage et sådant tilbud."},
  [8470] = {n="Dødtræ-ritualtotemet", l="Tag Dødtræ-ritualtotemet med ind i Tømmergab-fæstningen og se, om en af pelsbolgene dér kan finde en anvendelse for genstanden. Tømmergab vil ikke tale med dig, medmindre dit ry hos dem er Neutralt eller højere.", d="Du har fundet et af Dødtræ-pelsbolgenes ritualtotemer. Selve totemet er af ubestemmelig konstruktion, men en håndgribelig fornemmelse af fortvivlelse udstråler fra det. Hvis der fandtes en genstand, der bedst eksemplificerer den fordærvelse, Dødtræ-pelsbolgene lider under, så ville det klart være denne.\n\nEn af pelsbolgene inde i Tømmergab-fæstningen kan måske have en anvendelse for sådan en genstand... forudsat at du har vundet deres tillid nok til, at de vil tale med dig.", p="Ja <Class>, hvordan kan jeg hjælpe dig? Du færdes blandt os fredeligt, men der er uden tvivl noget galt. Jeg fornemmer noget... noget foruroligende...", c="Dette totem... jeg genkender det som et af Dødtræ-pelsbolgenes, men det er tykt af forrådnelsens stank. Hvad end ondskaben er, der har vendt vores brødre mod os, er den helt sikkert til stede i denne genstand.\n\nDu var klog til at bringe dette til os, <Name>. Måske kan vi gennem studier og ritualer afdække, hvad det er, der forurener vores brødres sind. Tak, ven - modtag venligst disse offergaver som vederlag for dit fund."},
  [8471] = {n="Vinterfald-ritualtotemet", l="Tag Vinterfald-ritualtotemet med ind i Tømmergab-fæstningen og se, om en af pelsbolgene dér kan finde en anvendelse for genstanden. Tømmergab vil ikke tale med dig, medmindre dit ry hos dem er Neutralt eller højere.", d="Du har fundet et af Vinterfald-pelsbolgenes ritualtotemer. Selve totemet er af ubestemmelig konstruktion, men det synes at udstråle en næsten påtrængende fornemmelse af frygt og fortvivlelse. Hvis mange af Vinterfald-pelsbolgene virkelig bærer på disse, ville det helt sikkert gå langt i at forklare deres nuværende tilstand.\n\nEn af pelsbolgene inde i Tømmergab-fæstningen kan måske have en anvendelse for sådan en genstand... forudsat at du har vundet deres tillid nok til, at de vil tale med dig.", p="<Class> - du nærmer dig os på en fredelig måde, men jeg fornemmer, at du er her i sager, der er alvorlige og grave... både for pelsbolg og <Race> ligeså. Hvad er det, du er kommet for at fortælle os?", c="Dette her... det har form af et Vinterfald-ritualtotem, men det er blevet forvredet af kræfter, jeg ikke kan begynde at begribe. Hvad end forureningen er, der har sat Vinterfald op imod os, er den helt sikkert til stede i denne genstand.\n\nGudommelig visdom har bragt både dette og dig til os, <Name>. Vi vil studere denne genstand indgående; måske en dag vil Vinterfald ikke længere rase imod os.\n\nTak, ven - modtag venligst disse offergaver som vederlag for din velvilje."},
  [8481] = {n="Roden til alt ondt", l="Plant Dæmonkaldende Fakkel i munden på Overhøvding Vinterfalds hule i Vinterfald-landsbyen. Besejr dæmonen og hent Xandivius' Essens til Gorn Enøje i Tømmergab-fæstningen.", d="<Name>, takket være dig har vi udtænkt en måde at fremkalde roden til alt ondt for Vinterfald-stammen - den fordærvende dæmon, der hersker over dem!\n\nTag denne fakkel til munden af Overhøvding Vinterfalds personlige hule og plant den der. Det vil tvinge dæmonen til at vise sig og undersøge. Det er her, du og dine allierede må slå til! Kun essensen af den faldne dæmon vil begynde den lange helingsproces for Vinterfald-stammen... og frelsen af Tømmergab-fæstningen.", p="Du er vendt tilbage til os, <Name>... betyder det, at dæmonen er blevet slået ihjel?", c="Du... du har reddet os! Din sejr over dæmonen Xandivius har sikret Tømmergab-fæstningens sikkerhed i mange år fremover. Du er virkelig en helt blandt vores art.\n\nModtag venligst dette med vores velsignelse. Selvom helingsprocessen vil gå langsomt blandt pelsbolgene - og konflikten vil stadig fortsætte - har du givet Vinterfald noget, de aldrig før har haft.\n\nDe har nu en chance for at overleve."},
  [8484] = {n="Forhandlingen om fred", l="Bring Tømmergabs fredsoffer til Kong Magni Bronzeskæg i Jernsmede.", d="Dine bedrifter rækker ud over en simpel helts historie, <Name>. Hvis du er en repræsentant for dit folk, så er dit folk nogen, vi ville arbejde på at slutte fred med.\n\nVær venlig - tag dette offer med til den dværgiske konge, der bor i et bjerg af jern; jeg tror, I kalder denne by for Jernsmede. For længe siden forsøgte han at tage kontakt til os på vegne af sin Alliance. Det er nu kun passende at anerkende dig som nøglen i din Alliances bestræbelser på at forhandle fred.", p="<Class>, du er velkommen i mit domæne. Jernsmede bør altid betragtes som et hjem for en helt som dig. Nu, hvad har du at forhandle med mig om?", c="Ja, dette er en yderst heldig vending af begivenhederne. Var der blevet sluttet en varig fred med disse væsener, ville det helt sikkert give os en fordel i Kalimdør... en fordel, som Nattealferne ikke kan støtte alene. Jeg vil straks underrette de andre ledere af Alliancen om dette, og yderligere diplomater vil blive sendt af sted!\n\nSom for dig, <Name>... du har vist mod i både diplomati og handling. Jeg takker dig, og det gør hele Alliancen også."},
  [8485] = {n="Forhandlingen om fred", l="Bring Tømmergabs fredsoffer til Træl i Orgrimgrad.", d="Dine bedrifter rækker ud over en simpel helts historie, <Name>. Hvis du er en repræsentant for dit folk, så er dit folk nogen, vi ville arbejde på at slutte fred med.\n\nVær venlig - tag dette offer med til den orkiske krigshøvding, der residerer i landene i Durdotar; jeg tror, I kalder denne by for Orgrimgrad. For længe siden forsøgte han at tage kontakt til os på vegne af sin Horde. Det er nu kun passende at anerkende dig som nøglen i din Hordes bestræbelser på at forhandle fred.", p="Krigshøvdingens hilsner tilfalder dig, <Class>. Dine bedrifter gør Horden stærkere i disse urolige tider. Nu, hvad har du at forhandle med mig om?", c="Ja, dette er en yderst heldig vending af begivenhederne. Var der blevet sluttet en varig fred med disse væsener, ville det helt sikkert give os en fordel i at sikre Kalimdør mod eksterne trusler. Jeg vil straks underrette de andre ledere af Horden om dette, og yderligere diplomater vil blive sendt af sted!\n\nSom for dig, <Name>... du har vist mod i både diplomati og handling. Jeg takker dig, og det gør hele Horden også."},
  [8492] = {n="Alliancen har brug for kobberstænger!", l="Bring 20 Kobberstænger til Sergent Stenbryn ved Militærværnet i Jernsmede.", d="Hej dér, <Class>, du ser rask nok ud til at bidrage til krigsindsatsen! Vi har brug for al den hjælp, vi kan få her, for at skaffe det materiel, der skal bruges til Ahn'Kiraj-krigen, og det er din heldige dag.\n\nJeg samler kobberstænger i stakke på tyve. Det er for en god sag, hvad siger du? Tror du, du kunne hjælpe Alliancen?", p="Har du samlet de tyve kobberstænger endnu, soldat?", c="Det klarede du, knægt! Vi får de kobberstænger på bunken og bruger dem til at lave krigsmateriellet med det samme. Det er indsatsen fra folk som dig, der gør mig stolt over at tjene Alliancen. Godt arbejde, soldat!\n\nOg hvis du tilfældigvis støder på flere kobberstænger, så sørg for, at de finder vej til mig."},
  [8494] = {n="Alliancen har brug for jernstænger!", l="Bring 20 Jernstænger til Korporal Kødnes ved Militærværnet i Jernsmede.", d="Nå, hej dér, hr. Pralefant, du er da et syn for trætte øjne. Hvis du ikke har hørt det, mens du var derude og \"eventyrede\", så har Alliancen gjort sig klar til krig i Ahn'Kiraj og mangler jernstænger... en hel masse af dem. Bring dem til mig i stakke på tyve. Vi kan regne med dig, ikke, <Class>?", p="Hvis du har de tyve jernstænger, vil jeg ikke vide, hvor du har dem gemt!", c="Nå, nå, hvis det ikke er <Name>. Og du klarede det. Jeg regner med, at jeg nu må holde øje med dig. Det gør ondt at sige, men tak for din indsats. Alliancen vil ikke glemme det, og det vil jeg heller ikke. Nu skal du ud dér og slide dig træt på alt andet, der skal samles ind."},
  [8499] = {n="Alliancen har brug for thoriumstænger!", l="Bring 20 Thoriumstænger til Dame Tvillingfletning ved Militærværnet i Jernsmede.", d="Det er meget venligt af dig at spørge til, hvad Alliancen har brug for. Ud over alle de andre indsamlingsbestræbelser i gang mangler vi en stor mængde thoriumstænger, og det er den opgave, jeg har ansvaret for. Thoriumet vil blive brugt til at skabe mange forskellige ting til krigen, først og fremmest opførelsen af et battaljon dampstridsvogne, der skal luftbåres til Silithus, så snart de er færdige. Kan du hjælpe os i denne bestræbelse, <Class>?", p="Åh, en forsendelse fra min bror? Storartet! Lykken smiler virkelig til mig i dag!", c="Så Gnåhrn stoler ikke på min spejderevne? Jeg undrer mig over hvorfor..."},
  [8503] = {n="Alliancen har brug for kvælertang!", l="Bring 20 Kvælertang til Menig Draxlemåler ved Militærværnet i Jernsmede.", d="Så, <Class>, har jeg allerede fortalt dig om alle de fabelagtige anvendelser, kvælertang har? Det har jeg? Ja, well... under alle omstændigheder har vi brug for en masse af det, og når jeg siger en masse, mener jeg EN MASSE! Tror du, at du kunne hjælpe os? Jeg ved, at det betyder, at du må undvære alle de vidunderlige ting, du kan lave af det, men det er for en god sag!", p="Det er ikke sandt! Jeg ville aldrig snuppe nogen kvælertang fra toppen af stablerne her. Man kunne dog godt blive fristet, eftersom det er et praktisk talt universalmiddel af nyttig anvendelighed. *hoster* Har du ikke tilfældigvis den kvælertang, vi talte om tidligere?", c="Hurra! Det var endnu tyve. Du er den bedste. Jeg må vel få det hele pakket væk, før det visner. Så meget kvælertang, så lidt tid!\n\nTak igen, <Class>!"},
  [8505] = {n="Alliancen har brug for lilla lotus!", l="Bring 20 Lilla Lotus til Mester Natsang ved Militærværnet i Jernsmede.", d="<Class>, den lilla lotus er en blomst med et væld af anvendelser. Jeg er her på Alliancens anmodning som autoritet på disse anvendelser, for at konservere de urter, der er indsamlet, og for at sikre, at deres krigsindsats får nok lilla lotus til at opretholde den funktion, de har planlagt for den.\n\nJeg vil gerne have, at du drager ud i verden og vender tilbage til mig med nogle af disse blomster. Er det noget, du kan gøre?", p="Har du de lilla lotusurter, jeg bad om?", c="Dit bidrag er højt værdsat, <Class>. Det er kun gennem den samlede indsats fra os alle, at vi kan standse silitiderne og den kraft, der driver dem frem. Selv Horden samler deres egen mængde lilla lotus. Hvis du kommer over flere, så vend venligst tilbage til mig her."},
  [8509] = {n="Alliancen har brug for Arthas' Tårer!", l="Bring 20 Arthas' Tårer til Sergentmajor Germine ved Militærværnet i Jernsmede.", d="Jeg holder det enkelt og præcist, <Class>. Alliancen skal indsamle en stor mængde Arthas' Tårer til krigsindsatsen mod Ahn'Kiraj. Spørg mig ikke hvorfor; jeg følger bare ordrer. Men jeg vil gerne have, at du samler så mange af urterne, du kan, og bringer dem tilbage til mig her. Er du villig til at gøre det?", p="Hvad siger du? Tal højere, <Class>! Har du den forsendelse af Arthas' Tårer, jeg bad om?", c="Godt arbejde, <Class>. Jeg må sige, at jeg er behageligt overrasket. Du ville ikke tro, hvor mange der er kommet forbi og har tilbudt at hjælpe, men aldrig er vendt tilbage. Lad mig bare få dem ned i en kasse, talt op med dit navn på, og så kan vi tale igen om, hvorvidt jeg har brug for flere af de planter."},
  [8511] = {n="Alliancen har brug for let læder!", l="Bring 10 Let Læder til Bonnie Stenflåer ved Militærværnet i Jernsmede.", d="Vi Stenflåere har en lang historie som garvere, <Class>. Det er derfor, Alliancen har bedt min familie om at hjælpe med indsamlingen af let læder til Ahn'Kiraj-krigen. Jeg er her for at sikre, at læderet bliver garvet korrekt til det, de end måtte ønske at bruge det til. Men vi har brug for din hjælp.\n\nDa jeg må være her og gøre det, har jeg brug for, at du tager ud og samler skindene og bringer dem tilbage til mig her. Hvad siger du, knægt, vil du prøve?", p="<Class>, jeg håber virkelig, at det er det lette læder, du lovede.", c="Jeg tør påstå, at Alliancen kommer til at være meget glad for dine skind her, <Class>. Jeg vil sørge for, at ikke et eneste går til spilde. Tak, og sørg for at melde dig igen hos mig, når jeg har talt dem op, for at se, om vi har brug for flere."},
  [8513] = {n="Alliancen har brug for middel læder!", l="Bring 10 Middel Læder til Menig Portner ved Militærværnet i Jernsmede.", d="Ja, sir, jeg har fået til opgave at indsamle og holde styr på alt det middel læder, der er samlet til krigsindsatsen. Hvis du har overskud til at samle middel læder, uanset kilde, så bring det til mig her. Jeg ville sætte stor pris på en hjælpende hånd med dette, hvis du kan undvære tiden.", p="Ja, sir, jeg husker dig. Er det det middel læder, du har med dig dér?", c="Wow! Det lyder til, at du lige var her og meldte dig frivilligt. Mange tak for donationen. Jeg får dem pakket og talt op. Du ved virkelig, hvordan man lyser en karls dag op."},
  [8515] = {n="Alliancen Har Brug for Tykt Læder!", l="Bring 10 Tykt Læder til Marta Finespindle ved Militærværnet i Jernsmede.", d="Åh, drenge, det her bliver fantastisk! <Class>, krigsindsatsen mod Ahn'Kiraj er i fuld gang, og jeg er blevet sat til at holde styr på alt det tykke læder, der kommer ind. Vi laver tonsvis af ting af det, men først skal vi have fat i tonsvis af det. Og det mener jeg bogstaveligt talt! Det er her, du kommer ind i billedet.\n\nSå, tror du, du kan tage derud og bringe mig en flot, tyk bunke tykt læder? Gør du, gør du?!", p="Er det det tykke læder, du har der i din rygsæk, <Class>? Er det? Jeg kan ikke vente med at få det overrakt! Alle kommer til at være så glade for os, tror du ikke?", c="Åh, jeg vidste da, du kunne klare det, <Class>, det vidste jeg bare! Jeg får disse over i de rette hænder, så snart jeg kan. Nu, lad os se her. Hmm, det ser ud til, at vores optælling udvikler sig ganske pænt. Du bør tjekke tilbage hos mig om et øjeblik, når jeg er færdig med at tælle, for at se, om vi har brug for mere. For hvis vi gør, er du den, jeg vil have derude og samle det ind til mig!"},
  [8517] = {n="Alliancen Har Brug for Linnedbandager!", l="Bring 20 Linnedbandager til Vagtpost Sølvhimmel ved Militærværnet i Jernsmede.", d="Krigen ved Ahn'Kiraj bliver lang og blodig. Det er en meget klog ting, Alliancen gør, når den får din hjælp, og andre som dig, til at opbygge det nødvendige materiel, før den kaster sig hovedkulds ud i konflikten.\n\nJeg er blevet bedt om at lede indsamlingen af linnedbandager til krigen, og jeg håber, at du vil hjælpe mig med at samle så mange, som vi har brug for. Det er ingen let sag, men linnedbandager er i det mindste de nemmeste at lave. Er du med os, <Class>?", p="Har du de tyve linnedbandager, jeg har brug for, <Class>?", c="Mange er de soldater, der vil få gavn af dit bidrag her i dag, <Class>. Jeg skal personligt sørge for, at Alliancen får øje på din indsats. Giv mig et øjeblik til at opbevare disse bandager ordentligt og opdatere min optælling, og så bør du tjekke tilbage hos mig for at se, om jeg har brug for flere.\n\nMåtte Elunies Lys skinne over dig, <Race>!"},
  [8519] = {n="En Bonde på det Evige Bræt", l="Lær alt, hvad du kan om fortiden, og tal derefter med Anakronos ved Tidens Huler i Tanarisørkenen.", d="Mens du genvinder fatningen og fokuserer blikket, bemærker du, at noget rører sig inde i krystallen. Ved nærmere eftersyn går det op for dig, at du kigger ind i fortiden... en erindring... længe glemt.", c="Efter Hjortehjelms forræderi samlede jeg de knuste stykker af Scepteret fra de Skiftende Sande og vendte tilbage hertil. Jeg havde al hensigt om at beskytte scepteret mod dem, der ville søge at bruge det til at forvolde skade på vores verden – og således blev Drageflugternes ansvar til.\n\nEt scepter delt mellem de fire mægtige Aspekter ville vise sig næsten umuligt at genoprette for dem, der bevidst søger kaos... eller sådan troede jeg. For et fjols jeg var. Selv nu bliver jeg jagtet af den forbandede flugt."},
  [8520] = {n="Alliancen Har Brug for Silkebandager!", l="Bring 20 Silkebandager til Sygeplejerske Stenmark ved Militærværnet i Jernsmede.", d="Med krigen ved Ahn'Kiraj truende må vi gøre alt, vi kan, for at sikre, at vores soldater har alt, hvad de behøver. Det er netop, hvad vi gør her. For min egen del er jeg blevet sat til at sørge for, at vi indsamler nok silkebandager.\n\nKan du tænke dig at hjælpe mig, <Class>?", p="Hej, <Class>, har du fået de tyve silkebandager endnu?", c="<Class>, du klarede det! Takket være dig er vi endnu et skridt tættere på at nå vores mål med silkebandagerne. Jeg får dem lagt væk, og så kan vi snakke mere, hvis du har lyst."},
  [8522] = {n="Alliancen Har Brug for Runeklædebandager!", l="Bring 20 Runeklædebandager til Vogter Månskygge ved Militærværnet i Jernsmede.", d="Diskuter krigens fortjenester, hvis du vil, <Class>, men den er allerede sat i gang. Se dig omkring på din familie og dine venner, og spørg dig selv, hvad du kan gøre for at sikre, at de, hvis de er involveret, får alle fordele, de skal bruge for at overleve ildebranden.\n\nHertil indsamler jeg runeklædebandager herfra, uanset kilde. Har du lyst til at give en donation?", p="Dagene går den ene efter den anden, og vi fortsætter stadig. <Class>, har du de runeklædebandager?", c="Du fortjener ros, <Class>, for din udholdenhed i denne opgave. Jeg vil lægge bandagerne væk, og så vil jeg gerne tale med dig igen om muligheden for, at du samler endnu flere runeklædebandager."},
  [8524] = {n="Alliancen Har Brug for Regnbuefinne-albacore!", l="Bring 20 Regnbuefinne-albacore til Glatte Gourmand ved Militærværnet i Jernsmede.", d="Hej der, ven! Hvis jeg sagde til dig: 'Synes du ikke, at soldater skal have mad at spise ligesom alle andre?', ville du naturligvis svare: 'Jo'. Jeg er 110% enig med dig! Jeg er glad for, at vi er på linje. Alt, hvad jeg skal bruge, er, at du tager derud, fisker en hel masse rå regnbuefinne-albacore op, og så tilbereder det hele og bringer det tilbage til mig lige her. Mmm, mmm, jeg kan allerede smage det.", p="Jeg vil vædde på, at du er vendt tilbage med al den regnbuefinne-albacore, vi talte om før, ikke, <Class>?", c="To til Alliancen, en til mig, to til Alliancen, en til mig. Hej der, fiskehandler, fremragende arbejde. Jeg kan se, at du bliver en rigtig ære for klubben. Det ser dog ud til, at vi nok har brug for mere af den albacore. Hvorfor tager du ikke ud og skaffer en lille smule mere? Jeg kan allerede høre min mave rumle."},
  [8526] = {n="Alliancen Har Brug for Stegt Rovfugl!", l="Bring 20 Stegt Rovfugl til Sarah Tristfløjte ved Militærværnet i Jernsmede.", d="Åh, hvordan går det, <Class>? Jeg ser, at du er interesseret i at samle mad til den kommende krig ved Ahn'Kiraj? Af en eller anden grund syntes min far, at det ville være en god læringsoplevelse for mig at melde mig frivillig til at hjælpe her. Stor fejl. Jeg kan ikke engang lide at spise kød.\n\nUanset hvad, hvis du har lyst, kunne du bringe mig en masse stegt rovfugl. Det ser ud til, at det er, hvad alle soldaterne kommer til at ville have.", p="Har du så al den stegte rovfugl endnu?", c="Jamen, det er jo fint. Tak, fordi du bringer mig alt dette brændte dyrekød, <Class>. Jeg lægger det bare på bunken derovre. Jeg er sikker på, at nogen vil tage sig af det. Jeg regner med, at hvis du har lidt tid til overs, så vil du måske bringe mig mere?"},
  [8528] = {n="Alliancen Har Brug for Plettet Gulhale!", l="Bring 20 Plettet Gulhale til Jægerinde Hurtigflod ved Militærværnet i Jernsmede.", d="Det virker måske ikke heroisk at samle tilberedt fisk, men undervurder ikke værdien af forberedelse, unge <Class>. Soldater skal spise ligesom alle andre, og vi er her for at gøre vores del, så de har, hvad de behøver, når krigen ved Ahn'Kiraj begynder.\n\nDerfor oplagrer jeg plettet gulhale, en alsidig kilde til næring, der holder sig godt og kan bruges i mange forskellige retter. Den har heller ikke lugten af nogle andre saltvandsfisk. Er du villig til at hjælpe mig i denne bestræbelse?", p="Jeg er sikker på, at du er tilbage så hurtigt med den plettede gulhale, vi talte om.", c="Tak for denne gave, <Class>, og så rettidigt desuden. Vores soldater vil helt sikkert ikke mangle noget at spise. Lad mig lige få disse fisk lagt ordentligt væk, og så kan du og jeg drøfte en ny omgang, hvis du er villig."},
  [8530] = {n="Alliancen Har Brug for Svidde Kernesten!", l="Bring 50 svidde kernesten til Kommandør Stærkhammer ved flyvepladsen i Dun Frostbakke.", d="<Class>, jeg har brug for din hjælp. I Lavakernen ligger der nogle sten, svidde kernesten for at være præcis, som vi skal høste til krigsindsatsen mod Ahn'Kiraj. Jeg har fået at vide, at vores smede og ingeniører kan gøre god brug af dem, og det er der, du kommer ind. Jeg skal have dig til at gå ind i Lavakernen og samle så mange af disse kernesten, som du kan. Selvfølgelig vil du nok gerne snakke niogtredive af dine nærmeste venner med dig på vejen."},
  [8532] = {n="Horden Har Brug for Kobberstænger!", l="Bring 20 Kobberstænger til Minearbejder Krumvel ved Åndernes Dal i Orgrimmar.", d="Så glad for, at du har besluttet dig for at hjælpe til her. Ikke alle ville, så jeg må sikre mig, at du forstår, hvad jeg har brug for. Kobberstænger, ikke kobbermalm. Vi har ikke tid eller folk nok til at smelte det hele selv, så hvis du ville være så venlig at tage dig af det, vil din indsats blive behørigt noteret. Er det noget, du kan klare, <Class>?", p="Jeg håber, at det er de tyve kobberstænger, du har med dig der, <Class>.", c="Disse stænger duer, og tak for, at du ikke har pudset dem. Der er ingen mening i at gøre dem pæne, når de skal omformes til det materiel, der skal bygges til krigen. Jeg tager mig af at stable dem, og jeg sørger for, at de bliver brugt rigtigt. Tal med mig igen, hvis du har lyst til at bringe yderligere tyve."},
  [8542] = {n="Horden Har Brug for Tinstænger!", l="Bring 20 Tinstænger til Fodsoldat Maug ved Åndernes Dal i Orgrimmar.", d="Lok'tar, <Race>, jeg er sikker på, at du allerede ved, at vi er på vej i krig ved Ahn'Kiraj mod insekterne. Men først har Krigshøvdingen besluttet, at vi skal gøre noget, der kaldes 'forberedelse'. Selvom jeg hellere ville slibe våben og hamre rustninger i form, er jeg stolt over at være blevet valgt til at stå for indsamlingen af tinstænger her. Men det kan jeg ikke gøre uden din hjælp.\n\nSå jeg har brug for, at du tager derud, laver tinstænger og bringer dem tilbage til mig her. Jeg tror, jeg får brug for flere, end jeg kan tælle.", p="Hvor mange tinstænger har du der, <Class>? Efter krigen tror jeg, at jeg får brug for nogen til at lære mig at tælle.", c="Nå, jeg tror, at det er det rigtige antal tinstænger. Prøv ikke at narre mig, <Class>! Tælling gør mit kranium ondt. Nu går jeg og stabler disse stænger, og du tager derud og bringer mig mere af det samme."},
  [8545] = {n="Horden Har Brug for Mithrilstænger!", l="Bring 20 Mithrilstænger til Seniorsergent T'kelah ved Åndernes Dal i Orgrimmar.", d="<Class>, krigen den kommer, og det eneste, vi kan gøre, er at forberede os. Der er her, du og jeg kan hjælpe hinanden, mon. Se, de har sat mig til at samle alle de mithrilstænger ind, vi skal bruge til at bygge alt, hvad vi får brug for. Og jeg mangler stadig mere!\n\nSå, jeg håber, at du kan tage derud og grave noget mithril op til os og så smelte det til stænger. Lyder det som noget, du kan gøre for os?", p="Det ville sikkert være rart at have alle de mithrilstænger, vi har brug for til krigsindsatsen mod Ahn'Kiraj. Er det derfor, du er tilbage, mon? Har du mine stænger?", c="Det her er en god start for dig og mig, <Class>. Det er endnu tyve mithrilstænger, som jeg kan lægge på stablerne og sætte kryds ud for på listen. Det hele skal bruges til at lave krigsmateriel.\n\nSørg for at tjekke tilbage hos mig, for du ved jo, at det ser ud til, at vi får brug for endnu flere af de mithrilstænger."},
  [8549] = {n="Horden Har Brug for Fredsblomst!", l="Bring 20 Fredsblomst til Urtekyndig Stoltefjer ved Åndernes Dal i Orgrimmar.", d="Det siges, at hver generation må stå over for en afgørende prøvelse. Jeg frygter, at krigen ved Ahn'Kiraj vil blive smeltedigelen, hvori vores mod bliver prøvet. Så vi forbereder os, og på den måde finder vi ud af, hvad vi er lavet af.\n\nJeg har meldt mig frivilligt til at hjælpe Horden med at samle så meget fredsblomst som muligt, så den kan blive lavet til eliksirer til krigen. Jeg håber, at du er her for at yde mig din hjælp. Hvis det er tilfældet, så har jeg brug for, at du bringer mig en god mængde af urten. Vil du hjælpe mig, <Class>?", p="Tilbage så hurtigt med fredsblomsten, <Class>?", c="Og således skubber vores indsats os et stykke tættere på krig. Tak for dit hårde arbejde med at samle denne fredsblomst, <Class>. Jeg forsikrer dig om, at den vil blive brugt godt, og at din indsats er blevet noteret, <Name>. Hvis du finder det rimeligt, så kom tilbage til mig igen med flere af blomsterne. Indtil da, må Moder Jord vejlede dig."},
  [8551] = {n="Kaptajnens Kiste", l="Bring Smudsens Kiste til Hylebury Smudsen i Bytteviken.", d="Jeg plejede at sejle et skib herfra hele vejen til Skralleby i Kalimdør. Jeg var en succesfuld kaptajn med en upåklagelig reputation.\n\nIndtil...\n\nDe forbandede havgiganter ruinerede mig! De knuste mit skib, dræbte min besætning og satte mig i en redningsbåd til Bytteviken. Og en af giganterne, Gorlask, stjal min kaptajnskiste. Han sagde, at han ville have den til en snusdåse. Den frækhed!\n\nJeg har hørt, at Gorlask vandrer langs kysten øst herfra. Find ham og få min kiste tilbage! Gør du det, har du tjent en kaptajns taknemmelighed.", p="Ahoj, <Name>! Fandt du Gorlask? Den kiste var min yndlingskiste, og den har et skjult rum, der rummede mine største skatte!", c="Du fandt den! Åh, en glædelig dag, det her er! Tak, <Name>. At få min kiste tilbage køler noget af ilden i mig.\n\nMen min hævn er ikke fuldendt..."},
  [8552] = {n="Det Monogrammerede Skærf", l="Returner det monogrammerede skærf til dens ejer.", d="Dette fine skærf har bogstaverne \"HS\" broderet langs kanten.", p="Hej. Har du noget at gøre med mig?", c="Du har fundet mit skærf? Så... må du have dræbt Mok'rask havgiganten! Hurra!\n\nJeg er glad for, at den skørbugsramte skurk er død – Mok'rask var en af tre havgiganter, der knuste mine skibe og dræbte min besætning.\n\nTre gange.\n\nDu er en <Class> af værd, <Name>."},
  [8553] = {n="Kaptajnens Kutlas", l="Tal med Sprøgger.", d="Efter jeg mistede mit første skib til de giganter, købte jeg et andet. Det kaldte jeg Smudsens Hævn, og jeg fyldte det med forsyninger og besætning og tog ud for at finde skurkene. Jeg fandt dem, men... de slog mig. De knuste Smudsens Hævn, dræbte min anden besætning og satte mig i endnu en redningsbåd.\n\nDenne gang stjal en anden af giganterne, Negolask, min kutlas.\n\nKonfrontér Negolask og bring mig min kutlas!\n\nTal med Sprøgger. Han var min kok på Smudsens Hævn, og han overlevede det sidste angreb. Han kan hjælpe dig med at finde kæmpen.", c="Hej hej, <Name>. Kaptajnen fortalte mig, at du skal efter Negolask, hva'?"},
  [8554] = {n="Opgør med Negolask", l="Bring 10 Grillede Musvågevinger og 5 flasker Jungleranke-vin til Kaptajn Smudsens Redningsbåd.\n\nDræb Negolask, og bring Smudsens Kutlas til Kaptajn Smudsen i Kvælertorn.", d="Negolask er en sulten kæmpe.\n\nDa giganterne ødelagde vores skib, gik Negolask lige efter mit køkken. Han var ikke sulten efter besætning ligesom de andre giganter. Negolask ville have vin... og mine Grillede Musvågevinger. De er min specialitet, og jeg måtte helt til Ødelandene for at få opskriften!\n\nHvis du vil lokke kæmpen, så skaf noget vin og en stak musvågevinger. Læg dem i vores gamle redningsbåd, sydøst herfra langs kysten. Når Negolask lugter al den mad, kommer han helt sikkert!", p="Fik du min kutlas, <Name>?", c="Du fik min kutlas fra Negolask! Jeg kan ikke tro min lykke, <Name>! At møde dig har vendt min lykke til det bedre, det er der ingen tvivl om!\n\nTak! Og hvis jeg nogensinde får et nyt skib, og du har lyst til at sejle på havet, vil du være min æresgæst."},
  [8555] = {n="Drageflugternes Ansvar", c="Eranikas, Vælastrasz og Azurøs... Ingen tvivl om, at du kender til disse drager, dødelige. Det er derfor ingen tilfældighed, at de har spillet så indflydelsesrige roller som vogtere af vores verden.\n\nDesværre (og min egen naivitet er delvist skyld i det) er hver vogter faldet for en tragedie, hvad enten det skyldes de Gamle Guders agenter eller forræderi fra dem, der kaldte sig venner. Omfanget heraf har næret min egen mistillid til jeres slags.\n\nSøg dem op... Og <Race>, gør dig klar til det værste."},
  [8556] = {n="Signet af Ubøjelig Styrke", l="Bring 1 Qiraji Magistral-ring, 2 Lysende Idoler, 5 Bronzeskarabæer og 5 Elfenbensskarabæer til Vindkalder Jessendra i Silithusørkenen. Du skal også opnå Æret-ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som Qiraji-løjtnanterne bærer, siges at give dem formidable evner. De korrupte ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at lave ukorrumperede versioner af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Bragte du mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil opdage, at effekten er langt mere... behagelig."},
  [8557] = {n="Dække af Ubøjelig Styrke", l="Bring 1 Qiraji Kamp-dække, 2 Onyksidoler, 5 Sølvskarabæer og 5 Knoglebeskarabæer til Kejl Hurtigklo i Silithusørkenen. Du skal også opnå Ærbødig-ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i vores angreb på Ahn'Kiraj, <Name>. Jeg kan lave dig en beskyttende genstand, der vil være til hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende spænde.\n\nJeg lover, at du ikke bliver skuffet.", p="Bragte du materialerne til kappen, <Name>?", c="Ah ja... dette dække er makelløst.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qiraji'ernes ugudelige magi."},
  [8558] = {n="Segl af Ubøjelig Styrke", l="Bring 1 Qiraji Pigget Hjalt, 2 Alabasteridoler, 5 Krystalskarabæer og 5 Stenskarabæer til Opsynsmand Harro i Silithusørkenen. Du skal også opnå Ophøjet-ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Qiraji'erne og deres tjenere bruger genstande lavet af de sjældneste og fineste materialer: knogler fra gigantiske oldtidsvæsener, ædelsten fra jordens dybder, metaller rene og stærke.\n\nBare synet af Qiraji-artefakter fylder mig med trang til at øve mit håndværk med deres knuste og smeltede stykker. Bevis din loyalitet over for Kredsen, <Name>, så laver jeg dig et kraftfuldt våben af de fineste Qiraji-materialer.", p="Bragte du mig de komponenter, jeg har brug for, <Name>?", c="Du har gjort det godt, <Class>. Dette er et mesterværk af et hjalt... balancen er perfekt.\n\nTag dit våben, <Name>. Før det med stor selvtillid og besejr vores fjender!"},
  [8575] = {n="Azurøs' Magiske Regnskabsbog", l="Lever Azurøs' Magiske Regnskabsbog til Narin Spådomsfant i Tanarisørkenen.", d="Du kan ikke forstå et eneste ord i denne regnskabsbog. Du ved ikke engang, hvilket sprog den er skrevet på!", p="Åh! Magisk pulserende ting! Til mig?", c="<Narin undersøger ivrigt brevet.>\n\nFremragende, <Race>! Hvad er det? Jeg kan ikke læse en skid drakonisk."},
  [8576] = {n="Oversættelsen af Regnskabsbogen", c="Først og fremmest, <Name>! Vi må finde ud af, hvad Azurøs skrev i denne regnskabsbog.\n\nSiger du, at han har bedt dig om at lave en arkanit-bøje, og at dette er skematikken? Mærkeligt, at han ville skrive det på drakonisk. Den gamle gedebuk ved godt, at jeg ikke kan læse denne vrøvl.\n\nHvis dette skal lykkes, får jeg brug for mine spåbriller, en fem hundrede pund høj kylling og bind II af \"Drakonisk for Dumrianer\". Ikke nødvendigvis i den rækkefølge."},
  [8577] = {n="Grydevul, Eks-B.V.F.E.", l="Narin Spådomsfant vil have dig til at finde sin eks-bedste ven for evigt (B.V.F.E.), Grydevul, og tage de spåbriller tilbage, som Grydevul stjal fra ham.", d="Hvis jeg skal oversætte noget, får jeg brug for mine spåbriller. Desværre blev de stjålet for ganske længe siden af min eks-bedste ven for evigt, Grydevul. Han knuste mit hjerte fem steder og efterlod mig her for at rådne op.\n\nMed hjælp fra min tro krystalkugle har jeg indsnævret hans opholdssted til enten Gråmanke-muren i Sølvskov eller hvad der ser ud til at være en portalverden i Yderlandet, som i øjeblikket bliver overrendt af Den Brændende Legion. Du bliver nødt til at opspore ham og få mine briller tilbage, <Name>!", c="Jeg kan ikke tro, at han fandt mig. Jeg troede, at jeg havde mistet ham, da jeg var i Yderlandet. Jeg vender ikke tilbage dertil, <Race>! Ingen måde, ingen vej! Jeg er færdig med at være hans deltidsbedste ven for evigt og fuldtidsslave."},
  [8578] = {n="Spåbriller? Ingen Problem!", l="Find Narins Spåbriller og returner dem til Narin Spådomsfant i Tanarisørkenen.", d="<Du hører et suk af lettelse slippe ud af kassen.>\n\nDu vil bare have hans spåbriller? Fantastisk! Det er ingen problem... Giv mig bare et øjeblik til at... Hov! Hvor er den... Pokkers!\n\nNå, der er nogle dårlige nyheder og nogle værre nyheder. De dårlige nyheder er, at jeg har tabt brillerne. De værre nyheder er, at jeg tabte dem, da jeg snusede rundt i Lavakernen sidste måned. Ja, Lavakernen... Jeg gætter på, at det afslutter vores forretning! Farvel!", p="Lavakernen, hva'? Jeg håber, at mine briller stadig er i ét stykke!", c="Fremragende! Hvor lagde jeg nu den 500 pund høje kylling og bind II af \"Drakonisk for Dumrianer???\" Åh, og her er en lille ting for al dit hårde arbejde!"},
  [8579] = {n="Dødelige Mestre", p="Vi fornemmer vores slaverede brødre dybere inde i Ahn'Kiraj; men ikke engang en hær af drager ville være nok til at befri dem, <Race>.\n\nDen samme besværgelse, der fængslede dem, ville placere os fast under Ce'Tuns kontrol, hvis vi kom en eneste smule tættere på ham.\n\nDen Gamle Gud har forudset vores ankomst. Alt håb er ude. Hvad forskel kunne en blot dødelig som dig overhovedet gøre?", c="Jeg kan se, at du ikke er en almindelig dødelig, <Name>. Dine chancer mod Den Gamle Gud, hvor uendeligt små de end er, er større end vores på dette tidspunkt. For mens han venter drager på sin dørtærskel, er han ikke forberedt på nogen som dig.\n\nLige som Anakronos og Hjortehjelm besejrede Qiraji for tusind år siden gennem alliancen mellem dødelige og drage-racer, vil vi også indgå en pagt. Vind den Bronze Drageflugts tillid, så vinder du vores. Først da vil vi gøre dig til en sand mester."},
  [8580] = {n="Horden Har Brug for Ildblomst!", l="Bring 20 Ildblomst til Flagermusrytter Pele'kejki i Ånders Dal i Orgrimmar.", d="Hej, <Class>. Ja, dig, mon! Der er en hel masse ildblomst, som Horden tror, de har brug for til denne Ahn'Kiraj-krigsindsats. Måske putter de den i fine ting, der går boom? Måske giver de den til Alliancen som brændstof til deres dampstridsvogne? Hvem ved? Ikke Pele'kejki!\n\nPele'kejki ved dog dette... han ved, at du vil hjælpe ham og bringe masser af ildblomst tilbage, ik' mon?", p="Du vil ikke gøre Pele'kejki sur. Du gør Pele'kejki glad ved at bringe ham masser af ildblomst, rigtig snart.", c="<Class>! Pele'kejki glad for nu. Pele'kejki tager al den ildblomst og putter den i en kasse, så den holder sig frisk. Pele'kejki sørger for, at al ildblomsten bliver lavet om til gode ting til krigen. Og hvis du skaffer flere, så kom og se Pele'kejki hurtigt. Pele'kejki er nok snart i behov for mere."},
  [8582] = {n="Horden Har Brug for Lilla Lotus!", l="Bring 20 Lilla Lotus til Apoteker Jezel i Ånders Dal i Orgrimmar.", d="Den lilla lotus, <Class>, er et reagens i et stort antal eliksirer, tinkturer og olier, hvoraf nogle vil komme os til nytte ved Ahn'Kiraj. Vi får brug for at lave et umådeligt antal af disse eliksirer til krigsindsatsen. Og jeg vil eksperimentere for at finde flere anvendelser for lotussen. Men for at gøre alt det har jeg brug for en stor mængde af blomsten.\n\nDet er her, du kommer ind i billedet. Gå ud i marken og saml så mange lilla lotusser, du kan. Er det noget, du er villig til at gøre for os?", p="Er du allerede kommet tilbage med den lilla lotus, jeg har bedt om, <Class>? Det er afgørende, at du gør det så hurtigt som muligt, for ellers går alt, hvad jeg forsøger her, til spilde.", c="En prisværdig indsats, <Class>. Jeg vil måle disse prøver for deres passende anvendelse og notere dit bidrag. Den lilla lotus skal så opbevares ordentligt, indtil jeg er klar til dem. Og for dig: Hvis du stadig har tid, må jeg forestille mig, at jeg stadig får brug for mere lilla lotus. Kig venligst forbi igen om et øjeblik."},
  [8584] = {n="Spørg Mig Aldrig Om Min Forretning", l="Narin Spådomsfant i Tanarisørkenen vil have dig til at tale med Klagesang Hurtighugger i Gadgetbyen.", d="Hvis der er én ting, du skal vide om mig, er det her: Spørg ALDRIG mig om min forretning! Jeg arbejder med ting, du simpelthen ikke kan forstå. Som for eksempel: Ved du, hvad en psykotronisk mundkurvdorf er? Selvfølgelig ikke! Og derfor overlader vi planlægningen til mig og hentningen til dig.\n\nSom jeg sagde tidligere, hvis det her skal lykkes, får vi brug for en 500 pund kylling.\n\nTag til Gadgetbyen og tal med Klagesang Hurtighugger - han vil sætte dig i gang med at finde et egnet eksemplar.", c="<Klagesang klør sig i hovedet.>\n\nEn 500 pund kylling? Den findes ikke! Ikke mere i hvert fald. Jeg kendte til en sådan kylling... Dødens Sorte Kylling...\n\n<Klagesangs stemme dør hen.>\n\nMen ja, ingen så nogensinde den kylling og levede for at fortælle det. Jeg har en idé, der kan gavne os begge, knægt."},
  [8585] = {n="Rædsels Ø!", l="Hent Lakmærans kadaver og 20 Kimærok-mørbrad til Klagesang Hurtighugger i Tanarisørkenen.", d="Ifølge sagnet har kimæroken på Rædsels Ø i Vildalas de mest saftige og møre lækkerier, der findes! Nu har disse kimærok også en far, som med ordentlig tilberedning måske eller måske ikke ser ud som en 500 pund kylling.\n\nTag til Rædsels Ø, dræb Herre Lakmæran og bring mig hans friske kadaver. Det burde tilfredsstille gnomen. For at tilfredsstille mig skal du skaffe noget kimærok-mørbrad.\n\nGør du det, får du din 500 pund kylling og lidt ekstra.", p="Mmmmm... Kimærok...", c="Se marmoreringen på de mørbrad! Fantastisk!\n\nNu til den kylling... Hm, lad mig se. Jeg får brug for et par minutter til at udtænke opskriften."},
  [8586] = {n="Klagesangs Sparkende Kimærok-koteletter", l="Klagesang Hurtighugger i Gadgetbyen vil have dig til at bringe ham 20 Nisse-raketbrændstof og 20 Dybstensalt.", d="Min opskrift er færdig! Det, jeg har brug for fra dig nu, er noget raketbrændstof og dybstensalt. Jeg tager mig af krydderierne, og kødet, du bragte mig, dækker resten.\n\nNår du har bragt mig det, jeg bad om, er kyllingen klar til at blive taget med tilbage til Narin.", p="Skynd dig, knægt. Vi vil ikke have, at kødet bliver dårligt.", c="Den er klar! Jeg præsenterer dig for min største skabelse: Klagesangs Sparkende Kimærok-koteletter!"},
  [8587] = {n="Retur til Narin", l="Lever den 500 pund store kylling til Narin Spådomsfant i Tanarisørkenen.", d="Jeg er en nisse af mit ord, knægt. Her er din 500 pund kylling.\n\nHvad en gnom vil med en 500 pund kylling, aner jeg ikke...\n\n<Klagesang mumler noget uforståeligt.>\n\nFormentlig for at sove i den... Beskidte gnomer...", p="Hvad er den lækre duft?", c="<Narin hamrer to næver ned i den enorme kylling og propper sit ansigt fuldt af Klagesangs dejlige delikatesse.>\n\nMMmmm... Det her er utroligt! Den bedste kylling, jeg nogensinde har fået!"},
  [8588] = {n="Horden Har Brug for Tungt Læder!", l="Bring 10 Tungt Læder til Flåeren Jamani i Ånders Dal i Orgrimmar.", d="Da vi forbereder os på krig, er det måske bedst, at vi får alle de varer, vi har brug for, først, synes du ikke, mon? Et af grundstofferne i de krigsmaterialer, vi producerer, er tungt læder. Vi bruger det til næsten alt, fra forstærkning til rustning og gode gamle almindelige presenninger også.\n\nMen først skal vi have fat i mere af det. Det er din opgave, <Class>. Slib din kniv og bring mig et bundt. Så taler vi videre.", p="Jeg har ingen tid til spillerier, hvis du bare er her for at pludre, <Class>. Der er alt for mange stakke tungt læder, der skal garves. Kom tilbage, når du har mindst ti til mig.", c="Åh, så du har det tunge læder, jeg havde brug for. Din klinge er virkelig skarp, <Class>; det her er gode skind! Nu hvor vi har fået en god start sammen, sørger jeg for, at dit bidrag bliver brugt godt. Og hvis du kommer forbi mere tungt læder, så bring det her hen til mig."},
  [8590] = {n="Horden Har Brug for Tykt Læder!", l="Bring 10 Tykt Læder til Sergent Umala i Ånders Dal i Orgrimmar.", d="Jeg er glad for, at du besluttede dig for at tale med mig om dette, <Class>. Det ser ud til, at Hordens forberedelser til den kommende Ahn'Kiraj-krig er i fuld gang. Men du og jeg skal stadig gøre vores del.\n\nJeg er blevet bedt om at samle et stort antal tykke læderskind til alle slags krigsmateriel, og jeg har brug for, at du hjælper mig med at gå derud og samle dem. Der er ære og Hordens taknemmelighed i det for dig, hvis du vælger at hjælpe. Vil du?", p="<Class>, er du kommet tilbage så hurtigt med de ti tykke læder, vi talte om?", c="Godt arbejde, <Class>. Jeg er sikker på, at disse tykke læderskind vil blive brugt til at forstærke zeppeliner og lave alle slags rustninger og våben. Du har min tak, og Hordens. Kom igen, hvis du støder på mere tykt læder på dine rejser, og held og lykke."},
  [8597] = {n="Drakonisk for Dumrianer", l="Find Narin Spådomsfants bog, begravet på en ø i Sydhavet.", d="Jeg vidste, at den bog ville komme til nytte en dag! Heldigvis havde jeg snildheden og forudseenheden til at gemme den et sikkert sted.\n\nBekymr dig ikke, den er et sted, hvor ingen nogensinde kunne håbe på at finde den! Jeg havde brug for en gyrokopter bare for at komme derhen første gang. Desværre styrtede jeg den ned på stranden på vej tilbage. Det var gennem den ulykke, at jeg fik disse supergnomiske psykiske kræfter!\n\nLed efter min styrtede gyrokopter et sted på Verdens Ende-stranden, og svøm sydpå derfra! Du vil kende stedet, når du ser det!", c="Bogen er væk! Oven på jorddyngen ligger en seddel."},
  [8598] = {n="rLøSePeNgE", l="Returner løsepengebrevet til Narin Spådomsfant i Tanarisørkenen.", d="<Teksten på denne seddel er sammensat af forskellige skrifttyper, limet fast på pergamentets overflade.>\n\nVi har din dyrebare bog, gnom. Hvis du nogensinde vil se den igen, gør du præcis, som vi beder om.\n\n<En detaljeret liste med instruktioner er angivet, over 3 sider.>\n\nMed pengene og kom alene!", p="Hør lige, hvad er der i vejen?", c="<Narins ansigt gløder knaldrødt.>\n\nBogkidnappe min... bog, vil de så!? Jeg skal lære dem, hvad det betyder at rode med en psykisk gnom!"},
  [8599] = {n="Kærlighedssang til Narin", l="Tag Meridies kærlighedsbrev til Narin Spådomsfant i Tanarisørkenen.", d="Det er ikke ofte, jeg får besøg. Faktisk var sidste gang, jeg havde besøg, da jeg reddede den kære, søde gnom fra vraget af den styrtede flyvemaskine.\n\n<Meridie stirrer ind i intetheden, fortabt i en erindring.>\n\nKender du ham? Narin? Narin Spådomsfant? Åh, det ville betyde så meget for mig, hvis nogen ville levere en besked til ham for mig. Jeg må fortælle ham, hvordan jeg har det! Jeg ved, det er kærlighed! Jeg ved det bare!\n\nKunne du måske levere en besked til Narin? Jeg ville stå i evig gæld til dig!", p="Du lugter af fisk!", c="Hvad!?\n\n<Narin begynder at fikle.>\n\nTja, øh... Hvad vil du have mig til at gøre??? Hun er en fisk! En FISK siger jeg dig! Og jeg er en gnom. Det kunne aldrig fungere."},
  [8600] = {n="Horden Har Brug for Barsk Læder!", l="Bring 10 Barsk Læder til Læge Serratus i Ånders Dal i Orgrimmar.", d="Jeg synes, at knivens greb i din håndflade er vigtigere end æggen på den. Selv den sløveste klinge kan få til at skære, hvis der bliver lagt det rette tryk igennem den, er du ikke enig, <Class>? Men du og jeg har ikke sådanne problemer, for vi vedligeholder de skarpeste kanter, ikke sandt?\n\nNå, det gør ikke noget, jeg har en opgave til dig. I Hordens tjeneste og for at gøre din del for Ahn'Kiraj-krigsindsatsen vil jeg have, at du vender tilbage til mig med en række barske læderskind. Det er noget, du vil gøre, ikke?", p="Det kan umuligt tage dig så lang tid at skære ti barske læder af til mig! Måske burde du slibe din flåkniv? Eller også tager jeg fejl, og du har dem gemt i din rygsæk?", c="Meget godt, det ser ud til, at du har gjort et ganske anstændigt stykke arbejde, selvom nogle af skindene ser lidt takkede ud i kanterne. Det gør ikke noget, opgaven er fuldført, og du har fortjent din belønning. Hvis du støder på endnu en stak barsk læder, så sørg for at bringe dem til mig hurtigst muligt."},
  [8604] = {n="Horden Har Brug for Uldbandager!", l="Bring 20 Uldbandager til Helbreder Langløber i Ånders Dal i Orgrimmar.", d="Hilsen, <Class>. Som forberedelse til krigen ved Ahn'Kiraj koordinerer jeg her Hordens indsats for at samle uldbandager. Desværre kan vores soldater ude i marken ikke stole på, at en helbreder er til stede for at holde dem i live. Tro mig, jeg ved det af egen erfaring. Derfor samler vi alle disse førstehjælpskasser til dem.\n\nHvis du har tid, har jeg brug for mange uldbandager. Bring dem til mig her, så sørger jeg for, at du bliver ordentligt belønnet.", p="Ah, <Class>, er du kommet tilbage så hurtigt med uldbandagerne?", c="Du har min tak, <Class>, og Hordens taknemmelighed. Hvis du støder på flere uldbandager, så bring dem til mig her, hvis du ønsker at bidrage yderligere til krigsindsatsen. Indtil da må dine forfædre holde øje med dig!"},
  [8606] = {n="Lok!", l="Narin Spådomsfant i Tanarisørkenen vil have dig til at rejse til Vintervår og placere guldposen på afleveringspunktet, som bogtyvene har dokumenteret.", d="Jeg har det! Her er, hvad vi skal gøre. Jeg fylder en sæk med sten, og du skal foretage afleveringen. Jeg ved, der stod, at jeg skulle levere den, og det skal jeg - på en måde.\n\n<Narin kigger dig op og ned.>\n\nJa, du klarer dig fint. Tag den turban, kåben og sækken med sten og tag af sted til afleveringspunktet i Vintervår.\n\nJeg har inkluderet alt, hvad du har brug for i dette særlige sæt. Når de dukker op for at hente varerne, så udslet dem! Det vil lære dem at rode med Narin!", c="Jeg tror, vi har undervurderet disse bogtyve."},
  [8607] = {n="Horden Har Brug for Magevævsbandager!", l="Bring 20 Magevævsbandager til Dame Grøn i Ånders Dal i Orgrimmar.", d="Jeg går ud fra, at du taler til mig, fordi du vil hjælpe med den indsamling, jeg er blevet betroet? Godt! Med hvilke midler som helst, og jeg mener hvilke som helst, ønsker jeg, at du samler et godt antal magevævsbandager. Friske ville være rart, men ikke absolut nødvendigt. Bring dem tilbage til mig her, <Class>, så sørger jeg personligt for, at du bliver ordentligt belønnet.", p="Lad være med at fejle og få mig til at se dårlig ud, <Class>! Kom tilbage så hurtigt som muligt med de magevævsbandager, vi talte om.", c="Overraskende, men acceptabelt. Måske undervurderede jeg dine 'evner', <Class>. Måske. Du klarede en meget simpel opgave, og for det bliver du belønnet langt over proportion. Men lad det ikke gå dig til hovedet. Hvis du virkelig vil bevise dig selv, bør du komme derud og bringe mig et nyt bundt magevævsbandager."},
  [8609] = {n="Horden Har Brug for Runeklædebandager!", l="Bring 20 Runeklædebandager til Stenvagt Lerhov i Ånders Dal i Orgrimmar.", d="Det synes uundgåeligt, at Horden og Alliancen er på kollisionskurs mod krig ved Ahn'Kiraj. Overraskende nok er det ikke en krig med hinanden, men snarere med silithiderne og den kraft, der styrer dem. Også overraskende gør begge sider deres del for at samle de ressourcer, der er nødvendige for at føre en succesrig krig.\n\nJeg samler runeklædebandager for at uddele til soldaterne, men jeg vil ikke få succes uden hjælp, forhåbentlig din. Er det noget, du kan hjælpe mig med, <Class>?", p="Krigen kommer snart, tror jeg, <Class>. Jeg takker dig for din tid og indsats i forbindelse med vores indsamlingsopgaver. Kommer du tilbage, fordi du har fået de runeklædebandager, vi talte om før?", c="Du er en ære for Horden, <Class>. Tak for din indsats; den er værdsat! Jeg må pakke disse friske bandager væk og tælle igen for at se, hvor langt vi er nået mod vores mål. Hvis du vil, kan du samle flere runeklædebandager og bringe dem til mig her."},
  [8611] = {n="Horden Har Brug for Magre Ulvebøffer!", l="Bring 20 Magre Ulvebøffer til Blodvagt Rårtar i Ånders Dal i Orgrimmar.", d="Jeg står ikke her bare for at få en flot solbrun hud, <Class>. Der er krigsforberedelser, der skal træffes. Hvis vi skal knuse de insekter ved Ahn'Kiraj, så må vi være klar, og det omfatter også mad!\n\nDe har sat mig til at samle og salte magre ulvebøffer her til den kommende krig. Men da jeg skal blive her for at passe på alt dette, har jeg brug for, at du går ud, dræber nogle ulve og derefter tilbereder kødet til magre ulvebøffer og bringer dem tilbage til mig her. Har du forstået det hele?", p="Tilbage med de magre ulvebøffer så hurtigt, <Class>? Jeg er ligeglad med, om de er overstegte eller tartar, bare de er velsmagende, og bring dem hurtigt hertil!", c="Ok, denne stak kød ser godt ud for mig. Jeg salter dem og pakker dem væk, og forhåbentlig holder de sig frisk nok til at være spiselige, når tiden kommer.\n\nTak for bidraget, <Class>. Tror du, du kunne bringe mig et nyt parti?"},
  [8613] = {n="Horden Har Brug for Plettet Gulhale!", l="Bring 20 Plettet Gulhale til Fisker Lin'do i Ånders Dal i Orgrimmar.", d="Det er en fin dag til fiskeri, synes du ikke, mon? Godt, for jeg skal vist have brug for en masse fisk, ser det ud til. Horden har bedt mig om at stå for at samle en masse plettet gulhale til dem. De siger, at de har brug for den til krigen, de gør sig klar til ved Ahn'Kiraj. Jeg siger til dem, at jeg gør mit bedste. Så jeg skal have noget hjælp. Vil du hjælpe mig, <Class>?", p="Tilbage så hurtigt med den plettede gulhale, <Class>? Husk du at tilberede den ordentligt? Vi serverer ikke rå fisk for soldaterne ude i den varme ørkensol, det er sikkert.", c="Åh ja, det her er den gode vare. Jeg pakker det pænt, så det ikke går til spilde. Tak for hjælpen. Jeg tænker, du er en førsteklasses fisker for al den plettede gulhale. Og hvis du skulle fange og tilberede endnu mere, så bring det til mig her; jeg sørger for, at alle ved, at du gjorde det!"},
  [8615] = {n="Horden Har Brug for Bagt Laks!", l="Bring 20 Bagt Laks til Høvding Skarpklo i Ånders Dal i Orgrimmar.", d="Ahn'Kiraj-krigsindsatsen er et enormt foretagende, <Class>. Alle materialerne, der bliver samlet her, hvad enten det er metal til våben eller mad at spise, er lige så vigtige som hinanden. For hvis du ikke har spist i flere dage, vil du ikke have styrken til at løfte din økse, når det virkelig gælder.\n\nDerfor samler vi den mad, vi kan. Jeg samler bagt laks, en ret, der blev valgt både for sin næring og for sin evne til at holde sig. Kan du hjælpe mig med denne opgave, <Class>?", p="Sprite-darterne kan være farlige små kræ, når de bliver provokeret. Vær forsigtig, når du har med dem at gøre, <Class>. Og vær endnu mere forsigtig med nattealferne i området. De pågående tosser har også en tendens til at holde sig i skovene.\n\nNår du har fået nok af vingerne, så sig til, så sørger jeg for at belønne dig godt!", c="Vidunderligt, <Class>! Disse vil gøre det fint. Der er nok her til at lave en kappe til Korrin, og måske endda mere! Tak.\n\nJeg håber, rejsen ikke var for farlig? Vildalas er ikke kendt for at være tilgivende, men du har tydeligvis klaret dig godt nok.\n\nTak igen, <Class>."},
  [8617] = {n="Horden Har Brug for Svedede Kernesten!", l="Bring 50 svedede kernesten til General Zog i Durdotar.", d="Tiden er kommet, for dig at bidrage til Ahn'Kiraj-krigsindsatsen, <Class>. Forbi er de glade dage, hvor du fordrev tiden i fritid. Nu er det tid til at tjene mig og Horden, og jeg forsikrer dig om, at jeg ikke er så tilgivende som Krigshøvdingen.\n\nDu skal samle dine styrker, et gilde hvis du har et, og invadere Lavakernen. Inde vil du opdage, at stedets beboere har svedede kernesten. Bring dem tilbage til mig i store mængder."},
  [8619] = {n="Morgendyb den Ældre", c="Det er godt at vide, at folket i dette land stadig ærer de gamle racer. Jeg ønsker dig det bedste, <Name>, og tilbyder dig dette symbol..."},
  [8620] = {n="Den Eneste Recept", l="Hent de 8 tabte kapitler af Drakonisk for Dumrianer, kombiner dem med den Magiske Bogbinding, og returner den færdige bog Drakonisk for Dumrianer: Bind II til Narin Spådomsfant i Tanarisørkenen.", d="Jeg burde have vidst det. Min ærkefjende, Læge Vævil, i gang med sine gamle kneb! Og nu, takket være din fiasko i Vintervår, har Læge Vævil ødelagt min bog! Hvordan skal du nu redde verden, helt?\n\nSeddelen, jeg modtog, sagde, at det eneste kendte eksemplar af \"Drakonisk for Dumrianer: Bind II\" var revet i 8 dele og spredt for vinden! Hvis du på en eller anden måde formår at finde de manglende kapitler, så brug denne magiske bogbinding til at sætte dem sammen igen og vend tilbage til mig.", p="Jeg tager mine bukser på ligesom dig - et ben ad gangen. Bortset fra når mine bukser er på, laver jeg arkanitbøjer. Arkanitbøjer, baby!", c="Fantastisk! Jeg kan ikke tro, at du gjorde den besværlighed! Er du en slags maskine? Hvis det havde været mig, ville jeg nok bare have ladet verden implodere.\n\nJeg løfter min turban for dig, herre. Og ingen god gerning bør forblive ubelønnet."},
  [8635] = {n="Splitsten den Ældre", c="Slagene fra svundne tidsaldre er frø, hvorfra legender vokser. Din tid er heltenes tid, unge. Må din legende slå rødder og trives.\n\nJeg ønsker dig det bedste, <Name>, og tilbyder dig dette symbol..."},
  [8636] = {n="Rumlesten den Ældre", c="Livets stof er dømt til at dø og vende tilbage til jorden, men åndens stof lever evigt. Jeg ønsker dig det bedste, <Name>, og tilbyder dig dette symbol..."},
