  [8688] = {n="Vindløb den Ældre", c="Himlen rummer i sine utallige stjerner svar på jordiske mysterier, <Name>. Mon de kloge og de heldige så kigger op og finder sandheden?"},
  [8689] = {n="Svøb af Uendelig Visdom", l="Bring 1 Qiraji Kamp-dække, 2 Jaspis-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8690] = {n="Kappe af den Samlende Storm", l="Bring 1 Qiraji Kongelig-dække, 2 Sortglas-idoler, 5 Ler-skarabæer og 5 Guld-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8691] = {n="Dække af Hvælvede Hemmeligheder", l="Bring 1 Qiraji Kamp-dække, 2 Alabast-idoler, 5 Sten-skarabæer og 5 Krystal-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8692] = {n="Kappe af Uendeligt Liv", l="Bring 1 Qiraji Kongelig-dække, 2 Cinnober-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8693] = {n="Kappe af Tilslørede Skygger", l="Bring 1 Qiraji Kamp-dække, 2 Azurblå idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8694] = {n="Svøb af Usagte Navne", l="Bring 1 Qiraji Kongelig-dække, 2 Rav-idoler, 5 Elfenben-skarabæer og 5 Bronze-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8695] = {n="Kåbe af Evig Retfærd", l="Bring 1 Qiraji Kongelig-dække, 2 Sortglas-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kåben, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8696] = {n="Kappe af den Usete Vej", l="Bring 1 Qiraji Kongelig-dække, 2 Lysende idoler, 5 Sten-skarabæer og 5 Krystal-skarabæer til Kejl Hurtigklo i Silitus. Du skal også opnå Respekteret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Jeg er glad for at høre, at du hjælper os i angrebet på Ahn'Kiraj, <Name>. Jeg kan lave en beskyttende genstand til dig, som vil være en hjælp i kampen mod vores fjende, <Class>.\n\nJeg skal bruge et Qiraji-dække, som jeg selvfølgelig vil tilpasse til dig. Jeg skal også bruge idoler og skarabæer, som jeg vil bruge til at lave en passende hægte.\n\nJeg lover dig, at du ikke bliver skuffet.", p="Har du bragt materialerne til kappen, <Name>?", c="Ah ja... dette dække er pletfrit.\n\nTag denne kappe, <Name>. Må den beskytte dig mod Qirajis onde magi."},
  [8697] = {n="Ring af Uendelig Visdom", l="Bring 1 Qiraji Ceremoniel-ring, 2 Sortglas-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8698] = {n="Ring af den Samlende Storm", l="Bring 1 Qiraji Magistral-ring, 2 Cinnober-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8699] = {n="Bånd af Hvælvede Hemmeligheder", l="Bring 1 Qiraji Magistral-ring, 2 Azurblå idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8700] = {n="Bånd af Uendeligt Liv", l="Bring 1 Qiraji Magistral-ring, 2 Alabast-idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, kollega-druide.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenene i ringen for dig. Du vil finde, at det færdige stykke er langt mere... behageligt."},
  [8701] = {n="Bånd af Tilslørede Skygger", l="Bring 1 Qiraji Ceremoniel-ring, 2 Onyks-idoler, 5 Sten-skarabæer og 5 Krystal-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8702] = {n="Ring af Usagte Navne", l="Bring 1 Qiraji Ceremoniel-ring, 2 Jaspis-idoler, 5 Sten-skarabæer og 5 Krystal-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8703] = {n="Ring af Evig Retfærd", l="Bring 1 Qiraji Magistral-ring, 2 Cinnober-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8704] = {n="Signet af den Usete Vej", l="Bring 1 Qiraji Ceremoniel-ring, 2 Rav-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Vindkalder Jessendra i Silitus. Du skal også opnå Æret ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Ringene, som qirajiernes løjtnanter bærer, siges at give dem frygtindgydende evner. De fordærvede ædelsten, der pryder dem, kunne i teorien udskiftes med renere materialer for at skabe ufordærvede udgaver af ringene.\n\nÆdelstenene, der pryder Qiraji-idolerne, ville fungere ganske godt, da deres kvalitet er overlegen.\n\nBring mig ringen og idolerne, så laver jeg en kraftfuld ring til dig, <Class>.", p="Har du bragt mig ringen og materialerne, <Name>?", c="Jeg vil udskifte ædelstenen i ringen for dig. Du vil finde, at virkningen er langt mere... behagelig."},
  [8705] = {n="Klubbe af Uendelig Visdom", l="Bring 1 Qiraji Udsmykket Hjalt, 2 Lysende idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Fangevogter Harro i Silitus. Du skal også opnå Ophøjet ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Qirajierne og deres tjenere bruger genstande lavet af de sjældneste og fineste materialer: knogler fra gigantiske oldtidsvæsner, ædelsten fra jordens dybder, metaller rene og stærke.\n\nBlot synet af Qiraji-artefakter fylder mig med lyst til at øve mit håndværk på deres knuste og smeltede stykker. Bevis din loyalitet over for Kredsen, <Name>, så laver jeg et kraftfuldt våben til dig af de fineste Qiraji-materialer.", p="Har du bragt mig de komponenter, jeg har brug for, <Name>?", c="Du har gjort det godt, <Class>. Dette er et mesterværk af et hjalt... balancen er perfekt.\n\nTag dit våben, <Name>. Før det med stor selvtillid og besejr vores fjender!"},
  [8706] = {n="Hammer af den Samlende Storm", l="Bring 1 Qiraji Pigget Hjalt, 2 Rav-idoler, 5 Elfenben-skarabæer og 5 Bronze-skarabæer til Fangevogter Harro i Silitus. Du skal også opnå Ophøjet ry hos Cenarion-kredsen for at fuldføre denne opgave.", d="Qirajierne og deres tjenere bruger genstande lavet af de sjældneste og fineste materialer: knogler fra gigantiske oldtidsvæsner, ædelsten fra jordens dybder, metaller rene og stærke.\n\nBlot synet af Qiraji-artefakter fylder mig med lyst til at øve mit håndværk på deres knuste og smeltede stykker. Bevis din loyalitet over for Kredsen, <Name>, så laver jeg et kraftfuldt våben til dig af de fineste Qiraji-materialer.", p="Har du bragt mig de komponenter, jeg har brug for, <Name>?", c="Du har gjort det godt, <Class>. Dette er et mesterværk af et hjalt... balancen er perfekt.\n\nTag dit våben, <Name>. Før det med stor selvtillid og besejr vores fjender!"},
