  [8727] = {n="Fjernhvisker den Ældre", c="Himlene, med deres utallige stjerner, rummer svar på jordiske mysterier, <Name>. Må så de kloge og de heldige stirre op og finde sandheden?"},
  [8728] = {n="De Gode Nyheder og De Ringe Nyheder", l="Narin Spådomsfant i Tanaris vil have, at du bringer ham 20 Arkanitbarrer, 10 Elementium-malm, 10 Azerothiske diamanter og 10 Blå safirer.", d="Det tog vist lidt længere tid end forventet. Lad mig nu se, hvad denne fortegnelse siger.\n\n<Narin læser stille fortegnelsen og mumler med jævne mellemrum for sig selv.>\n\nDen gode nyhed er, at jeg er 99% sikker på, at jeg er i stand til at lave en arkanit-bøje, der fungerer efter dine specifikationer. Dette afhænger naturligvis helt af den dårlige nyhed.\n\nDen dårlige nyhed er, at jeg får brug for en masse arkanit, elementium-malm og sjældne ædelsten.\n\nBring mig det, jeg har brug for, så laver jeg bøjen.", p="Arkanit-bøjer laver sig ikke selv, <Name>. Og NEJ, du kan ikke låne nogle penge.", c="En aftale er en aftale. Jeg håber virkelig, du ved, hvad du går ind til, <Name>. Det er en hel masse besvær at gå igennem bare for at fiske lidt."},
  [8729] = {n="Neptunors Vrede", l="Brug arkanit-bøjen ved det Hvirvlende Malstrøm i Stormenes Bugt i Azshara.", d="Nævnte jeg den dårlige nyhed endnu? Den hedder Gab: 100 fødder af død og ødelæggelse. Jeg må have glemt den lille detalje.\n\nIfølge min overlegne psyko-psioniske synskhed finder du det bedste sted at kaste bøjen ud ud for kysten af Azsyra, i Stormenes Bugt.\n\nLed efter et hvirvlende malstrøm, sandsynligvis fyldt med vrag.\n\nForresten, jeg håber, du har venner.\n\nHvis du mod alle odds lykkes, så tag scepter-skåret til Anakronos.", p="Tiden løber ud, mester.", c="Godt gået, <Name>. Jeg vil snart kunne reformere Scepteret fra de Skiftende Sande."},
  [8730] = {n="Skurkius' Fordærvelse", l="Dræb Nefarian og find det Røde Scepter-skår. Bring det Røde Scepter-skår tilbage til Anakronos i Tidens Huler i Tanaris. Du har 5 timer til at fuldføre denne opgave.", d="Mester, er det dig? Tusind år er gået, siden jeg fik overdraget skåret, og det er i mit mørkeste øjeblik, at en bør træde frem for at aflaste mig for det... Men hvad ville en tragedie være uden grusomhed?\n\n<Vaelastrasz hoster svagt.>\n\nNe... Nefarius har nu scepter-skåret.\n\nTiden er afgørende. Nefarius planlægger at ødelægge skåret. Du må skynde dig!", p="Endnu en af vores helte tabt til Dødsvingens afkom. Vi vil for evigt være forbandet med denne lidelse...", c="Vaelastrasz' sjæl er i fred, mester. Aspekterne følger alle dine fremskridt med stor interesse. Vid, at du har mægtige allierede.\n\nJeg fik besked på at give dig noget, der kan hjælpe dig i denne kamp. Brug det godt..."},
  [8733] = {n="Eranikas, Drømmens Tyrann", l="Rejs til kontinentet Teldrasil og find Malfurjons agent et sted uden for murene til Darnassos.", d="Dette er en rejse til forløsning, helt. Hvis jeg var blevet dræbt i dag, ville jeg være død for en retfærdig og rigtig sag. Du må hente det grønne scepter-skår. Du må rense Eranikas for det fordærv, De Gamle Guder har lagt på ham.\n\nRejs til Darnassos. Lige uden for byens mure finder du en af mine agenter. Denne agent vil sætte tingene i gang for os og informere Tyrande om vores planer uden at alarmere Staghelm.\n\n<Malfurion sukker.>\n\nEt fald fra nåde, der har taget tusind år om at blive til...", c="Lygteånden er tavs bortset fra en lav summen. Mærkeligt nok kan den kommunikere med dig gennem tanker."},
  [8734] = {n="Tyrande og Remulos", l="Rejs til Månelunden og tal med Vogter Remulos.", d="Tyrande vil blive underrettet, dødelige. Shan'do Stormrasen har forberedt mig på denne eventualitet.\n\nNu skal du begive dig til Månelunden og tale med Remulos. Han vil have yderligere instruktioner om fremkaldelsen af Eranikas.\n\nVi ønsker dig alle stort held.", c="Det ville være umuligt at trække Eranikas ud af Drømmen, hvis han nægter. Hans intentioner kræver dog, at han træder ind i vores verden. Han søger at ødelægge Malfurjons levende manifestation. Det ville betyde enden for en af Drømmens mest mægtige allierede. Mare ville fuldstændig fortære alt, der måtte være tilbage, hvis Malfurion falder..."},
  [8735] = {n="Marens Fordærvelse", l="Rejs til de fire Smaragdgrønne Drøm-portaler i Azeroth og saml et Fragment af Marens Fordærvelse fra hver. Vend tilbage til Vogter Remulos i Månelunden, når du har fuldført opgaven.", d="Du må rejse til Azeroths fire drømmeportaler. Fra hver skal du trække et fragment af Marens fordærvelse. De drageslægtninge, der holder til i disse områder, har sådanne fragmenter. Vend tilbage til mig, når du har samlet fragmenterne.", p="<Remulos er fortabt i dybe tanker.>", c="Er du parat? Er verden parat til det, vi nu er ved at påkalde? Jeg ved det ikke... Jeg er bundet af pligt over for Malfurjon. Pligt og ære..."},
  [8736] = {n="Marens Manifestation", l="Forsvar Nathavn mod Eranikas. Lad ikke Vogter Remulos gå til grunde. Dræb ikke Eranikas. Forsvar dig selv. Afvent Tyrande.", d="Vi må udvise tilbageholdenhed over for Eranikas. Vi skal forløse ham, ikke tilintetgøre ham.\n\nTyrande er allerede på vej for at assistere os i denne opgave. Vi må stå imod drageslagene og redde Nathavn fra sikker ødelæggelse.\n\nVær på vagt! Du og dine allierede er vores eneste håb.", c="Han er forløst, <Name>. Han vender nu tilbage til Drømmen for at rette op på det, han alene har gjort forkert. Eranikas vil blive en mægtig allieret for Malfurjon og min far.\n\nDisse våben er til dig, <Name>; givet til mig af Ysera selv. Du gør klogt i at bruge dem i dine kampe mod Qiraji'erne."},
  [8741] = {n="Mesterens Tilbagevenden", l="Bring grønt scepterskår til Anakronos i Tidens Huler i Tanaris.", d="Vogteren venter din tilbagekomst, <Name>. Tag det grønne scepterskår med til Anakronos i Tidens Huler."},
  [8742] = {n="Kalimdørs Magt", p="Tusind år er gået, og lige som det var skæbnebestemt, står én foran mig. En der skal lede sit folk ind i en ny tidsalder.\n\nDen Gamle Gud skælver, <Name>. Åh ja, den frygter din tro. Knus profetien om C'Thun.\n\nDen ved, at du kommer, mester - og med dig kommer Kalimdørs magt. Du behøver blot at lade mig vide, når du er parat, så skal jeg tildele dig Scepteret fra de Skiftende Sande.", c="Scepteret fra de Skiftende Sande er atter helt, <Name>.\n\nDet må være dig, der bruger scepteret. Det må være dig, der forkynder den næste tidsalder for dit folk.\n\nDu må vente, til Horden og Alliancens hære er ankommet til Silithus, før du må slå på Basse-gongen."},
  [8743] = {n="Slå på gongen!", p="Basse-gongen tårner sig truende op foran dig. Stål dig, <Name>; for når Basse-gongen bliver slået, vil portene til Ahn'Kiraj blive åbnet.\n\nFra udyrets slappe gab kan kun komme kaos og ødelæggelse. Forsvar dit folk!", c="Fra jorden nær gongen springer et særligt krystal frem. Måske en gunst fra Yngelen."},
  [8744] = {n="En Omhyggeligt Indpakket Gave", c="Mærkaten på denne gave lyder:\n\nTil <Name>,\n\nMå dit Festmåltid for Stor-Vinter være lystigt og lyst!"},
  [8745] = {n="Den Tidløses Skat", c="Hilsner, mester. Jeg er Jonatan, vogter af den hellige gong og evig vagt for Den Bronze Flyvning.\n\nDen Tidløse selv har bemyndiget mig til at tildele dig en genstand efter eget valg fra hans tidløse skattekammer. Må den hjælpe dig i dine kampe mod Ce'Tun."},
  [8746] = {n="Metzen Rensdyret", l="Find Metzen Rensdyret. Brug de noter, der er givet dig, som spor til, hvor han holdes fange.\n\nNår du finder Metzen, skal du have Pungen med Rensdyrstøv i din besiddelse, så du kan drysse noget af støvet på ham; det bør befri Metzen fra hans fangenskab.\n\nAflever Pungen med Rensdyrstøv til Kaymard Kobbernyp i Orgrimgrad, når Metzen er befriet.", d="KATASTROFE er indtruffet! Metzen Rensdyret er blevet kidnappet!\n\nMetzen er en af Storfaderen Vinters otte rensdyr - og ejendom for Røgskovs Enge. Vi har modtaget ikke ét, men TO løsesumsbreve fra grupper, der hævder at have Metzen. Med højtiden i fuld gang er vi ved at være trængt op i et hjørne her ved kassen! Vær venlig - find Metzen og bring ham tilbage til os!\n\nTjek løsesumsbrevene for spor, og drys dette rensdyrstøv på ham - det vil befri ham fra alle hans lænker!\n\nSkynd jer, er I venlige!", p="<Name>! Fandt du ham? Var noterne i tasken, jeg gav dig, nok information til at finde Metzen? Jeg kan ikke bære tanken om, hvad de grusomme banditter måske gør ved ham... men vi har ingen mulighed for at betale sådan en urimelig løsesum!", c="Du gjorde det! Hurra!\n\nMetzen fløj tilbage til Storfaderen Vinters stalde - ja, Metzen kan virkelig flyve - for lidt siden! Støvet virkede som en fortryllelse; jeg vidste, at det ville. Du har reddet Vinterslørets Festmåltid såvel som Røgskovs Enge fra katastrofe. Tak, <Name>.\n\nLyt... på grund af det, du har gjort her, vil jeg have, at du får dette. Det er noget MEGET særligt; hvis du har et ridedyr, tror jeg, du vil få en kæmpe fornøjelse af det. Glædelig Vinterslør!"},
  [8747] = {n="Beskytterens Vej", c="Imponerende, lille ven. Du har gjort meget for at vinde Den Bronze Flyvnings gunst. Din hengivenhed er noteret.\n\nBeskytterens signetring vil give overlegen beskyttelse mod ondskabens kræfter.\n\nVær advaret: Når du har valgt din vej, har du ingen mulighed for at fortryde, hvis du skifter mening."},
  [8748] = {n="Beskytterens Vej", p="Din fortsatte forsvar af Kalimdørs børn er blevet anerkendt. Giv mig din signetring, så jeg kan forstærke dens kræfter.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade beskytterens vej!"},
  [8749] = {n="Beskytterens Vej", p="Du ærer mit folk, <Name>. Slå Kalimdørs fjender ned! Vis dem, hvad det betyder at skænde landet med evigt stjerneskin.\n\nDu har fortjent endnu en forstærkning. Giv mig din signetring, så jeg kan styrke dens magt.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade beskytterens vej!"},
  [8750] = {n="Beskytterens Vej", p="Hengivenhed af denne størrelse er sjælden. Du har vist, at din vilje er urokkelig, <Name>. Du skal blive rigt belønnet for din standhaftige vagt over vores verden.\n\nGiv mig din signetring, så jeg kan styrke dens fortryllelse.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade beskytterens vej!"},
  [8751] = {n="Kalimdørs Beskytter", p="Aldrig har jeg set sådan en vedholdenhed! Den Bronze Flyvning tildeler dig en sidste fortryllelse. Den Tidløse selv har anmodet om det!\n\nGiv mig din signetring, så jeg kan foretage de nødvendige justeringer.", c="Rejs dig, Kalimdørs Beskytter! Rejs dig og bliv anerkendt!"},
  [8752] = {n="Erobrerens Vej", c="Imponerende, lille ven. Du har gjort meget for at vinde Den Bronze Flyvnings gunst. Din hengivenhed er noteret.\n\nErobrerens signetring vil i høj grad forstærke dine fysiske angreb.\n\nVær advaret: Når du har valgt din vej, har du ingen mulighed for at fortryde, hvis du skifter mening."},
  [8753] = {n="Erobrerens Vej", p="Din fortsatte forsvar af Kalimdørs børn er blevet anerkendt. Giv mig din signetring, så jeg kan forstærke dens kræfter.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade erobrerens vej!"},
  [8754] = {n="Erobrerens Vej", p="Du ærer mit folk, <Name>. Slå Kalimdørs fjender ned! Vis dem, hvad det betyder at skænde landet med evigt stjerneskin.\n\nDu har fortjent endnu en forstærkning. Giv mig din signetring, så jeg kan styrke dens magt.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade erobrerens vej!"},
  [8755] = {n="Erobrerens Vej", p="Hengivenhed af denne størrelse er sjælden. Du har vist, at din vilje er urokkelig, <Name>. Du skal blive rigt belønnet for din standhaftige vagt over vores verden.\n\nGiv mig din signetring, så jeg kan styrke dens fortryllelse.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade erobrerens vej!"},
  [8756] = {n="Qiraji-erobreren", p="Aldrig har jeg set sådan en vedholdenhed! Den Bronze Flyvning tildeler dig en sidste fortryllelse. Den Tidløse selv har anmodet om det!\n\nGiv mig din signetring, så jeg kan foretage de nødvendige justeringer.", c="Rejs dig, Qiraji-erobrer! Rejs dig og bliv anerkendt!"},
  [8757] = {n="Påkalderens Vej", c="Imponerende, lille ven. Du har gjort meget for at vinde Den Bronze Flyvnings gunst. Din hengivenhed er noteret.\n\nPåkalderens signetring vil i høj grad forstærke dine magiske og naturlige evner.\n\nVær advaret: Når du har valgt din vej, har du ingen mulighed for at fortryde, hvis du skifter mening."},
  [8758] = {n="Påkalderens Vej", p="Din fortsatte forsvar af Kalimdørs børn er blevet anerkendt. Giv mig din signetring, så jeg kan forstærke dens kræfter.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade påkalderens vej!"},
  [8759] = {n="Påkalderens Vej", p="Du ærer mit folk, <Name>. Slå Kalimdørs fjender ned! Vis dem, hvad det betyder at skænde landet med evigt stjerneskin.\n\nDu har fortjent endnu en forstærkning. Giv mig din signetring, så jeg kan styrke dens magt.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade påkalderens vej!"},
  [8760] = {n="Påkalderens Vej", p="Hengivenhed af denne størrelse er sjælden. Du har vist, at din vilje er urokkelig, <Name>. Du skal blive rigt belønnet for din standhaftige vagt over vores verden.\n\nGiv mig din signetring, så jeg kan styrke dens fortryllelse.", c="Din opstigning i Yngelens rækker er meget imponerende, <Name>. Må du aldrig forlade påkalderens vej!"},
  [8761] = {n="Den Storslåede Påkalder", p="Aldrig har jeg set sådan en vedholdenhed! Den Bronze Flyvning tildeler dig en sidste fortryllelse. Den Tidløse selv har anmodet om det!\n\nGiv mig din signetring, så jeg kan foretage de nødvendige justeringer.", c="Rejs dig, Storslåede Påkalder! Rejs dig og bliv anerkendt!"},
  [8762] = {n="Metzen Rensdyret", l="Find Metzen Rensdyret. Brug de noter, der er givet dig, som spor til, hvor han holdes fange.\n\nNår du finder Metzen, skal du have Pungen med Rensdyrstøv i din besiddelse, så du kan drysse noget af støvet på ham; det bør befri Metzen fra hans fangenskab.\n\nAflever Pungen med Rensdyrstøv til Vulmort Klingelomme i Jernsmede, når Metzen er befriet.", d="KATASTROFE er indtruffet! Metzen Rensdyret er blevet kidnappet!\n\nMetzen er en af Storfaderen Vinters otte rensdyr - og ejendom for Røgskovs Enge. Vi har modtaget ikke ét, men TO løsesumsbreve fra grupper, der hævder at have Metzen. Med højtiden i fuld gang er vi ved at være trængt op i et hjørne her ved kassen! Vær venlig - find Metzen og bring ham tilbage til os!\n\nTjek løsesumsbrevene for spor, og drys dette rensdyrstøv på ham - det vil befri ham fra alle hans lænker!\n\nSkynd jer, er I venlige!", p="<Name>! Var noterne i tasken, jeg gav dig, nok information til at finde Metzen? Jeg kan ikke bære tanken om, hvad de grusomme banditter måske gør ved ham... men vi har ingen mulighed for at betale sådan en urimelig løsesum!", c="Du gjorde det! Hurra!\n\nMetzen fløj tilbage til Storfaderen Vinters stalde - ja, Metzen kan virkelig flyve - for lidt siden! Støvet virkede som en fortryllelse; jeg vidste, at det ville. Du har reddet Vinterslørets Festmåltid såvel som Røgskovs Enge fra katastrofe. Tak, <Name>.\n\nLyt... på grund af det, du har gjort her, vil jeg have, at du får dette. Det er noget MEGET særligt; hvis du har et ridedyr, tror jeg, du vil få en kæmpe fornøjelse af det. Glædelig Vinterslør!"},
  [8763] = {n="Højtidens Helt", l="Bring 1 Dybstensalt og 5 guldmønter til en Kristtorn-bevarer-maskine, hvorefter du modtager 5 Konserveret Kristtorn.", d="Hør her... Jeg burde egentlig ikke fortælle dig dette, men siden du er dagens helt og alt det der...\n\nDer er frisk kristtorn overalt på denne tid af året, men den holder aldrig længe. Vi har en maskine, der konserverer kristtorn - den bliver aldrig dårlig! Vi bruger den til at krydre højtiden... og fortjenesten om sommeren!\n\nJeg lader dig bruge bevareren, men kun hvis du er en mester-kok. Du skal bruge noget dybstensalt og to, tre, åh, lad os sige fem guld. Så får du et pænt parti, som er dit at beholde.", p="Maskinen \"Kristtorn-bevarer\" ligner først et destillationsapparat, men en omhyggelig undersøgelse af den afslører nogle kobold-agtige ændringer. Alligevel synes din madlavningsfærdighed at gøre dig i stand til at forstå, hvordan maskinen virker.\n\nDer er allerede frisk kristtorn i maskinen - du skal blot levere noget dybstensalt og fem guldmønter for at få maskinen i gang.", c="Maskinen udsender en lille rumlen og en smule damp, mens den går i gang. Det varer ikke længe, før den stopper, og det markeres af endnu en lille dampstråle, der sprøjter ud af den. En dørlem åbner sig og afslører et parti konserveret kristtorn!"},
  [8767] = {n="En Blidt Rystet Gave", c="Denne gave ser ud til at være blevet rystet et par gange. Mærkaten på den lyder:\n\nTil en meget speciel <Race> <Class>."},
  [8768] = {n="En Glad Indpakket Gave", c="Denne festligt indpakkede gave har dit navn på sig.\n\nVent, bevægede den sig lige?"},
  [8769] = {n="En Tikkende Gave", c="Hav en glædelig Stor-Vinter-festmåltid fra dine venner hos Røgskovs Enge."},
  [8788] = {n="En Blidt Rystet Gave", c="Denne gave ser ud til at være blevet rystet et par gange. Mærkaten på den lyder:\n\nTil en meget speciel <Race> <Class>."},
  [8791] = {n="Ossirisks Fald", l="Lever Ossirisk den Uarredes hoved til Kommandør Mar'alit i Cenarion-fæstningen i Silitus.", d="En forfærdelig trussel er blevet lagt til hvile. Den grusomme Ossirisk er blevet besejret.\n\nKalimdørs indbyggere ville blive lettede over at høre om denne sejr. Tag Ossirisks hoved og aflevér det til Kommandør Mar'alit fra Cenarion-fæstningen.", p="Ah, <Name>, du er vendt tilbage! Og i ét stykke, må jeg tilføje. Hvilke nyheder bringer du fra Ahn'Kiraj?", c="Jeg tilbyder dig min højeste anerkendelse og dit valg af en genstand med kraft, <Name>. Du har gjort Kalimdørs folk en stor tjeneste."},
  [8792] = {n="Horden Har Brug for Din Hjælp!", l="Tal med Krigsherre Grimkuk i Ånders Dal i Orgrimgrad.", d="Hej, jeg er glad for, at du har besluttet dig for at høre mig ud. Horden har brug for al den hjælp, den kan få, for at forberede sig på Ahn'Kiraj-krigen, og det betyder, at vi har brug for dig! Lige nu indsamler officielle samlere det nødvendige materiale til den kommende krig, men vi kan ikke nå vores mål uden din hjælp, <Name>!\n\nDu bør gå og tale med manden med ansvaret, Krigsherre Grimkuk. Hvad siger du, <Class>? Vil du hjælpe med de vitale forberedelser?", c="Hils, <Class>! Dejligt at se så mange af Horden, ligesom dig selv, <Name>, komme ud for at yde jeres støtte til at lægge grundlaget for den kommende Ahn'Kiraj-krig. Indsatsen her vil sikre, at vi sejrer over Silitiderne og deres onde herrer gemt inde i Ahn'Kiraj.\n\nNu hvor du er her, så tal endelig med de forskellige samlere og tilbyd din hjælp til at indsamle de materialer, du er egnet til."},
  [8793] = {n="Horden Har Brug for Din Hjælp!", l="Tal med Krigsherre Grimkuk i Ånders Dal i Orgrimgrad.", d="Hej, jeg er glad for, at du har besluttet dig for at høre mig ud. Horden har brug for al den hjælp, den kan få, for at forberede sig på Ahn'Kiraj-krigen, og det betyder, at vi har brug for dig! Lige nu indsamler officielle samlere det nødvendige materiale til den kommende krig, men vi kan ikke nå vores mål uden din hjælp, <Name>!\n\nDu bør gå og tale med manden med ansvaret, Krigsherre Grimkuk. Hvad siger du, <Class>? Vil du hjælpe med de vitale forberedelser?", c="Hils, <Class>! Dejligt at se så mange af Horden, ligesom dig selv, <Name>, komme ud for at yde jeres støtte til at lægge grundlaget for den kommende Ahn'Kiraj-krig. Indsatsen her vil sikre, at vi sejrer over Silitiderne og deres onde herrer gemt inde i Ahn'Kiraj.\n\nNu hvor du er her, så tal endelig med de forskellige samlere og tilbyd din hjælp til at indsamle de materialer, du er egnet til."},
