  [8795] = {n="Alliancen Har Brug for Din Hjælp!", l="Tal med Feltmarskal Snefald i Militærværnet i Jernsmede.", d="Hej, jeg er glad for, at du har besluttet dig for at høre mig ud. Alliancen har brug for al den hjælp, den kan få, for at forberede sig på Ahn'Kiraj-krigen, og det betyder, at vi har brug for dig! Lige nu indsamler officielle samlere det nødvendige materiale til den kommende krig, men vi kan ikke nå vores mål uden din hjælp, <Name>!\n\nDu bør gå og tale med manden med ansvaret, Feltmarskal Snefald. Hvad siger du, <Class>? Vil du hjælpe med de vitale forberedelser?", c="Hils og velkommen, knægt! Dejligt at se så mange af Alliancen, ligesom dig selv, <Name>, komme ud for at yde jeres støtte til at lægge grundlaget for den kommende Ahn'Kiraj-krig. Indsatsen her vil sikre, at vi sejrer over Silitiderne og deres onde herrer gemt inde i Ahn'Kiraj.\n\nNu hvor du er her, så tal endelig med de forskellige samlere og tilbyd din hjælp til at indsamle de materialer, du er egnet til."},
  [8796] = {n="Alliancen Har Brug for Din Hjælp!", l="Tal med Feltmarskal Snefald i Militærværnet i Jernsmede.", d="Hej, jeg er glad for, at du har besluttet dig for at høre mig ud. Alliancen har brug for al den hjælp, den kan få, for at forberede sig på Ahn'Kiraj-krigen, og det betyder, at vi har brug for dig! Lige nu indsamler officielle samlere det nødvendige materiale til den kommende krig, men vi kan ikke nå vores mål uden din hjælp, <Name>!\n\nDu bør gå og tale med manden med ansvaret, Feltmarskal Snefald. Hvad siger du, <Class>? Vil du hjælpe med de vitale forberedelser?", c="Hils og velkommen, knægt! Dejligt at se så mange af Alliancen, ligesom dig selv, <Name>, komme ud for at yde jeres støtte til at lægge grundlaget for den kommende Ahn'Kiraj-krig. Indsatsen her vil sikre, at vi sejrer over Silitiderne og deres onde herrer gemt inde i Ahn'Kiraj.\n\nNu hvor du er her, så tal endelig med de forskellige samlere og tilbyd din hjælp til at indsamle de materialer, du er egnet til."},
  [8797] = {n="Alliancen Har Brug for Din Hjælp!", l="Tal med Feltmarskal Snefald i Militærværnet i Jernsmede.", d="Hej, jeg er glad for, at du har besluttet dig for at høre mig ud. Alliancen har brug for al den hjælp, den kan få, for at forberede sig på Ahn'Kiraj-krigen, og det betyder, at vi har brug for dig! Lige nu indsamler officielle samlere det nødvendige materiale til den kommende krig, men vi kan ikke nå vores mål uden din hjælp, <Name>!\n\nDu bør gå og tale med manden med ansvaret, Feltmarskal Snefald. Hvad siger du, <Class>? Vil du hjælpe med de vitale forberedelser?", c="Hils og velkommen, knægt! Dejligt at se så mange af Alliancen, ligesom dig selv, <Name>, komme ud for at yde jeres støtte til at lægge grundlaget for den kommende Ahn'Kiraj-krig. Indsatsen her vil sikre, at vi sejrer over Silitiderne og deres onde herrer gemt inde i Ahn'Kiraj.\n\nNu hvor du er her, så tal endelig med de forskellige samlere og tilbyd din hjælp til at indsamle de materialer, du er egnet til."},
  [8798] = {n="En Yeti Helt Din Egen", c="Sig! Ved du hvad?! Du er også ingeniør! Så, da du hjalp mig med at lære mine venner en lektie, vil jeg lære dig, hvordan du laver din egen mekaniske yeti! Nu kan sjovet fortsætte evigt og altid, og du kan skræmme hvem end du vil! Forudsat at du kan skaffe komponenterne til at lave den, altså.\n\nHvad siger du, <Name>? Vil du lære hemmeligheden bag at lave en mekanisk yeti?"},
  [8799] = {n="Dagens Helt", l="Bring 1 Dybstensalt og 5 guldmønter til Kristtorn-bevarermaskinen, hvorefter du får 5 Konserveret Kristtorn.", d="Hør... Jeg burde egentlig ikke fortælle dig dette, men siden du er dagens helt og det hele...\n\nDer er frisk kristtorn overalt på denne tid af året, men det holder aldrig. Vi har en maskine, der konserverer kristtorn - den bliver aldrig dårlig! Vi bruger den til at krydre højtiden... og fortjenesten om sommeren!\n\nJeg lader dig bruge bevareren, men kun hvis du er en mester-kok. Du skal bruge noget dybstensalt og to, tre, åh lad os sige fem guld. Det giver dig en pæn portion, som er din at beholde.", p="\"Kristtorn-bevarer\"-maskinen ligner først en slags destillationsapparat, men en omhyggelig undersøgelse afslører nogle kobold-agtige ændringer på den. Alligevel synes din madlavningsfærdighed at gøre dig i stand til at forstå, hvordan maskinen virker.\n\nDer er allerede frisk kristtorn i maskinen - du skal blot give noget dybstensalt og fem guldmønter for at få maskinen i gang.", c="Maskinen udsender en lille rumlen og en smule damp, når den begynder at arbejde. Det går ikke længe, før den stopper, varslet af endnu en lille dampstråle, der sprøjter ud af den. En dørluge åbner sig og afslører en portion konserveret kristtorn!"},
  [8800] = {n="Cenarion Kampudstyr", l="Tal med Vargusen i Cenarion-fæstningen i Silitus.", d="Når du fuldfører de opgaver, du får tildelt i krigen, skal du tale med Vargusen, smeden. Vis ham de mærker, du har optjent undervejs. Han vil give dig udstyr, der matcher dit niveau af engagement i vores sag.", c="Kaldøn sendte dig? Fint, lad os se, hvad vi kan gøre for dig."},
  [8801] = {n="Ce'Tuns Arv", l="Tag Ce'Tuns Øje med til Kælastrasz i Tempelet i Ahn'Kiraj.", d="Ahn'Kirajs mure ryster. En ondskab, ældre end selve verden, er blevet ødelagt.\n\nNår du ser på resterne af det kolossale monstrum, fryser dit hjerte næsten. Selv i døden kan du mærke Ce'Tuns ondskabs arv omkring dig.\n\nDu har gjort det, man troede var umuligt.\n\nDu griber fat i en øjenstilk fra udyret og gemmer den sikkert i din rygsæk.\n\nTag Ce'Tuns Øje med til dragerne i næste kammer.", p="Herre <Name>, du har befriet os fra dens greb.", c="Vi vil forlade dette sted af egen kraft, Herre <Name> - når vi er sikre på, at det onde indeni er helt udslettet. Din legendariske rejse er næsten ved ende."},
  [8802] = {n="Kalimdørs Frelser", l="Tag Ce'Tuns Øje med til Anakronos i Tidens Huler.", d="Til Tidens Huler går du, Herre <Name>. Anakronos venter på din tilbagekomst. Giv ham Ce'Tuns øje, for han vil uden tvivl ønske at placere det i sin herres samling.", p="Herre <Name>! Det er forbi...", c="Mesteren har efterladt disse til dig, helt. Fra det tidløse depot: En samling artefakter, der spænder over tusinder af år - valget er dit."},
  [8803] = {n="En Festlig Gave", c="Seddelen på denne gave lyder:\n\nTil <Name>,\n\nI håb om, at dette vil hjælpe dig med at sprede varme budskaber og højtidsglæde til hele Azerot.\n\nFra Storfaderen Vinter"},
  [8827] = {n="Vinterens Gaver", l="Tal med Storfaderen Vinter. Han befinder sig nær Røgskovs Enges handelsområde i Jernsmede.", d="Jeg hører, at Storfaderen Vinter - med den generøse støtte fra Røgskovs Enge - har lagt gaver til alle under træet i Jernsmede. Jeg ville ønske, jeg kunne komme, men jeg må passe på PX-238 Vinter-Vidundervolten.\n\nMen du bør helt sikkert tjekke det ud. Jeg er sikker på, at Storfaderen Vinter har nogle gaver med dit navn på.", c="Å, hej der! Du kan kun være her af én grund: for at åbne dine Vinterslør-gaver.\n\nNu skal du ikke bekymre dig, Storfaderen Vinter har ikke glemt sin yndlings-<Race> <Class>. Kig under træet, så finder du dine gaver.\n\nI denne gavegivningens tid vil dine venner måske også nyde at modtage nogle af Røgskovs Enges fremragende produkter?"},
  [8828] = {n="Vinterens Gaver", l="Tal med Stor-faderen Vinter. Han befinder sig nær Røgskovs Enges handelsområde i Orgrimgrad.", d="Jeg hører, at Stor-faderen Vinter - med den generøse støtte fra Røgskovs Enge - har lagt gaver til alle under træet i Orgrimgrad. Jeg ville ønske, jeg kunne komme, men jeg må passe på PX-238 Vinter-Vidundervolten.\n\nMen du bør helt sikkert tjekke det ud. Jeg er sikker på, at Stor-faderen Vinter har nogle gaver med dit navn på.", c="Å, hej der! Du kan kun være her af én grund: for at åbne dine Vinterslør-gaver.\n\nNu skal du ikke bekymre dig, Stor-faderen Vinter har ikke glemt sin yndlings-<Race> <Class>. Kig under træet, så finder du dine gaver.\n\nI denne gavegivningens tid vil dine venner måske også nyde at modtage nogle af Røgskovs Enges fremragende produkter?"},
  [8857] = {n="Kolossens Hemmeligheder - Aschi", l="Tag skallen fra Aschi-kolossen med til Oglethorpe Uopdaget i Bytteviken.", d="Jeg leder efter kampherdede eventyrere, der er villige og i stand til at bringe en frisk skalprøve fra den faldne Aschi-kolos til Oglethorpe i Bytteviken. Nej, nej, jeg vil ikke have, at du kommer i nærheden af det dyrs lig. Tag bare en af mine prøver og gør det hurtigt. Disse ting er ikke gode for ham, hvis de er rådne!", p="Ja? Hvad har du dér?", c="Åh, de kyllinger jeg vil fremstille af denne vidunderlige skal! Godt gået, min dreng!"},
  [8858] = {n="Kolossens Hemmeligheder - Kongelig", l="Tag skallen fra Kongelig-kolossen med til Tilsynsmand Oljefist i Svidningskløften.", d="Der er ikke noget, jeg hellere vil end at proppe denne bille-skal ned i Oljefists fede fjæs... Bortset fra, at jeg sidder fast her og samler prøver fra den overvoksne kakerlak. Jeg bliver her til de små morgentimer, givet størrelsen af det dyr.\n\nTag denne prøve med til Oljefist for mig, og gør det hurtigt, <Class>. Han betaler STORT!\n\nJa, Thorium-peg - den ligger i Svidningskløften.", p="Hmmm...", c="Fremragende. Vi kunne sikkert udtænke en utrolig kraftig rustning af dette kitin. Her er rigdommen, du blev lovet."},
  [8859] = {n="Kolossens Hemmeligheder - Tora", l="Tag skallen fra Tora-kolossen med til Herre Maksvel Tyrønus i Lysets Håb-kapellet i Østlige Pestlande.", d="Mine tjenere blev næsten dræbt i deres forsøg på at hente denne prøve. Du skal absolut skynde dig! Herre Maksvel Tyrønus venter ivrigt på en frisk skalprøve. Han mener, at hemmelighederne i denne kolos kunne hjælpe os i krigen mod Svøben!\n\nHvorfor er du stadig her!? Til Lysets Håb! Ja, du vil blive belønnet rigeligt for din indsats...", p="Du ser en smule tung ud i støvlerne, ven.", c="Fremragende og rettidigt! Godt gået, knægt."},
  [8860] = {n="Nytårsfejringer!", l="Bring Røgskov-forsyningerne til Krovært Ellen i Stormvind.", d="Stormvind holder en fejring af nytåret! Hele dagen i dag kan du få gratis sprut, og om natten laver de et fyrværkeri-show! Det burde være ret hyggeligt... men Bytteviken holder også fest i dag; jeg vædder på, at det bliver endnu bedre!\n\nNå, under alle omstændigheder har Krovært Ellen i Stormvind brug for en forsyning af Røgskovs Enges fødevarer til at mætte alle festdeltagerne. Kan du gøre mig en tjeneste og levere den!\n\nTak, <Name>! Krovært Ellen er i Den Forgyldte Rose, i Handelsdistriktet i Stormvind.", p="Hilsner! Er du her til festen! Eller har du måske bare brug for at hvile de trætte fødder...", c="Åh, mine Røgskov-forsyninger! Storartet! Dem skal jeg bruge til at mætte alle byens folk til festen!\n\nTak, <Name>. Tag venligst dette som betaling, og glem ikke at drikke og danse med festdeltagerne udenfor!"},
  [8861] = {n="Nytårsfejringer!", l="Bring Røgskov-forsyningerne til Krovært Spaden i Tordenklippe.", d="Tordenklippe holder en fejring af nytåret! Hele dagen kan du finde gratis sprut der, og om natten laver de et fyrværkeri-show!\n\nDet burde være ret hyggeligt... men Bytteviken holder også fest i dag; jeg vædder på, at det bliver endnu bedre!\n\nNå, under alle omstændigheder har Krovært Spaden i Tordenklippe brug for en forsyning af Røgskovs Enges fødevarer til at mætte alle festdeltagerne. Kan du gøre mig en tjeneste og levere den!\n\nTak, <Name>! Krovært Spaden er i kroen nær broen til Jægerens Bakke.", p="God dag, <Class>! Er du kommet til Tordenklippe for vores fejringer? Eller er du her for at hvile en træt hov mellem jagterne?", c="Åh, meget godt! Disse forsyninger vil hjælpe med at mætte alle vores folk, her for at fejre nytåret!\n\nJeg takker dig, <Name>. Du står i gæld til mig. Tag venligst disse mønter... og tag mit råd til dig - drik rigeligt af tønderne udenfor, og slut dig til vores festdeltagere i en fejringsdans!"},
  [8862] = {n="Elunes Lys", p="Elunes lys er en artefakt af stor ærbødighed for disciplene ved Månefestivalen. Inde i lyset er lagret ægte måneskin, klar til at blive løsladt!\n\nDette lys er ufarligt for de fleste væsener, men du vil opdage, at Varsel og hans håndlangere bliver brændt og blændet af det.", c="Meget godt så - jeg accepterer disse slægtsmønter. Tag venligst Elunes lys med min velsignelse. Nyd også disse gratis fyrværkerier.\n\nMåtte din Månefestival være glædelig og fyldt med lystighed, <Name>.\n\nOg hvis du vælger at trodse Varsel og hans håndlangere, vil du finde Elunes lys ganske nyttigt..."},
  [8866] = {n="Bronzeskæg den Ældre", c="Det er godt at vide, at landets folk stadig viser ærbødighed over for de gamle racer. Jeg ønsker dig det bedste, <Name>, og tilbyder dig dette tegn..."},
  [8867] = {n="Månefyrværkeri", l="Opsend 8 Månefyrværkerier og 2 Klyngefyrværkerier og vend tilbage til en Månefestival-Varsler i en hovedstad.", d="Hvert år holder druiderne i Månelunden en fejring af vores bys store sejr over en gammel ondskab.\n\nVi hylder vores ældres visdom, deler storslåede gæstebud og selvfølgelig... affyrer fyrværkeri!\n\nFor en lille donation kan du købe farverige raketter hos vores handler. Prøv at bruge nogle af opsendere heromkring, <Name>.", p="Fandt du opsenderne, <Name>?", c="Godt gået, <Name>.\n\nNu hvor du er i festånden, hvorfor så ikke tage denne indbydelse til festivalen i Månelunden.\n\nDet er en ret behagelig fejring, hvis du har tid til overs. Vi deler mad, drikke, historier og selvfølgelig... endnu mere fyrværkeri!\n\nÅbn indbydelsen mens du står inde i cirklen af det store månelys, så bliver du transporteret til Månelunden."},
  [8868] = {n="Elunies Velsignelse", l="Fremkald Varsel, besejr ham og opnå Elunies velsignelse. Vend tilbage til Valadar Stjernesang i Nathavn", d="Udyret Varsel var engang en helt i denne verden. En ulv af stor styrke og held, Varsel kæmpede side om side med heltene fra De Ældgamles Krig, indtil han bukkede under for dæmonisk magi. Han vendte sig mod sine allierede, raserede over Azerot og bragte død og rædsel i sin kølvand.\n\nEndelig besejret her i Månelunden sover Varsel nu blandt mudderet i Elune'ara-søen. Men hvert nyt år, under festivalen, vågner han...\n\nIndsaml følgesvende, <Name>, og fremkald og besejr udyret Varsel. Opnå Elunies velsignelse!", p="Varsel vågner stadig under Elune'ara-søen, <Name>...", c="Meget godt gået, <Name>. Med besejrelsen af Varsel blev hans ånd sendt tilbage til Elune'ara-søens vande. Selvom udyret selv er velsignet af Elunie og derfor ikke kan dø, vil hans vrede aftage for endnu et år.\n\nDin sejr er en fejring, <Name>--en fejring af Varsels styrke, af dig og dine allierede, og af den fred du har givet denne tragiske helt fra vores fortid."},
  [8869] = {n="Sød Ro", l="Rejs til Stratholm og dræb den Karmosinrøde Hammersmed. Genvind den Karmosinrøde Hammersmeds Forklæde og vend tilbage til Lilit.", d="Inden for murene af Skarlagen-bastionen ligger den søde Ro. Den Karmosinrøde Hammersmed vogter opskriften med sit liv. Besejr ham og bring mig hans forklæde. Til gengæld skal jeg træne dig i at blive hammersmed.\n\nForstå dette: Når du først har valgt hammersmedens vej, vil sværdsmedens og øksesmedens veje ikke længere være tilgængelige."},
  [8870] = {n="Månefestivalen", l="Tal med Månefestival-Varslen i Mystiske Afdeling i Jernsmede. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8871] = {n="Månefestivalen", l="Tal med Månefestival-Varslen i Parkdistriktet i Stormvind. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8872] = {n="Månefestivalen", l="Tal med Månefestival-Varslen ved Cenarion-enklaven i Darnassos. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8873] = {n="Månefestivalen", l="Tal med Månefestival-Varslen i Visdommens Dal i Orgrimgrad. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8874] = {n="Månefestivalen", l="Tal med Månefestival-Varslen ved indgangen til Undergrunden. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8875] = {n="Månefestivalen", l="Tal med Månefestival-Varslen ved Ældrehøjen i Tordenklippe. Du kan også tale med Månefestival-Varsler i andre hovedstæder.", d="Det er den tid på året, <Name>! Cenarion-kredsen inviterer alle Azerots indbyggere til at deltage i vores fejring af Månefestivalen. Du vil finde Månefestival-Varslen i netop denne by, på et sted markeret af en velsignet cirkel af månelys. Hun kan fortælle dig mere om højtiden.", c="Velkommen, <Name>. Er du kommet for at deltage i festlighederne?"},
  [8883] = {n="Valadar Stjernesang", l="Brug din Månefestival-indbydelse i månelyset for at rejse til Månelunden. Tal med Valadar Stjernesang i Nathavn, når du ankommer.", d="Nu hvor du har din Månefestival-indbydelse, kan du rejse til Månelunden! Der vil du finde mange festglade, og i landsbyen Nathavn venter Valadar Stjernesang og hans søster Fariel på dem, der er ivrige efter at deltage i festlighederne.\n\nRejs til Månelunden gennem det store månelys og tal med Valadar Stjernesang; se, hvilke præmier du kan vinde under festivalen!", c="<Name>, velkommen til Nathavn, vært for Månefestivalen! Selvom vores landsby normalt er afsondret og isoleret fra Azerots folk, åbner vi i denne festtid vores arme og hjerter for alle.\n\nNyd dit besøg, <Name>, og tal med mig eller min søster igen, når du er klar."},
  [8897] = {n="Kæreste Colara,", l="Lever Løjtnant Heldrics Omhyggeligt Nedskrevne Seddel til Colara Dekan udenfor banken i Stormvind.", d="Jeg skal holde øje her ved porten, men jeg bekymrer mig altid om min kæreste, Colara. Jeg får kun lov at se hende i et par timer, hvis jeg er heldig, og ja, se bare på mig. Jeg har en mindre officersløn, og jeg kan blive kaldt til fronten hvilken som helst dag nu.\n\nVil hun bare glemme mig? Der er mange mænd i byen. Mange rige en af slagsen.\n\nUnder alle omstændigheder har jeg skrevet nogle ting ned... ikke meget, men hvis du kunne tage det med til hende for mig, ville det være fantastisk.", p="Hej der, flotte. Kan jeg hjælpe dig med noget?", c="Åh, er det ikke søde! Det er første gang, han nogensinde har sendt mig noget. Tror du, han bliver seriøs?\n\nColara Heldric? Det lyder vist godt nok. Men åh, jeg løber nok lidt for hurtigt i gang. Tak."},
  [8898] = {n="Kæreste Colara,", l="Lever det Krøllede Brev til Colara Dekan udenfor banken i Stormvind.", d="Jeg mødte en pige i Stormvind, da jeg sidst var der i bankens ærinde. Hun stjal mit hjerte. Nu kan jeg ikke holde op med at tænke på hende! Jeg vil gerne sende hende denne besked - jeg har omskrevet den tolv gange!\n\nPosten er så fuld nu, og jeg vil sikre mig, at den kommer frem.\n\nHvis du er på vej den vej, kunne du så hjælpe mig?", p="Hej der, flotte. Kan jeg hjælpe dig med noget?", c="Tormek? Åh ja, jeg husker ham. Han havde et ret flot skæg og et smil under det.\n\nÅh, jeg kan ikke tro, at han huskede mig!"},
  [8899] = {n="Kæreste Colara,", l="Lever det Uplettede Brev til Colara Dekan udenfor banken i Stormvind.", d="Hvordan beskrive hendes skønhed? Tusinder af års ord, og jeg står målløs.\n\nDisse dødelige forvirrer sindet og gør os til babblende narrer.\n\nJeg har stirret på disse ord for længe. Ingen mere veltalende betydning kan jeg presse ud af dem. Nej, hun må få dem nu, ellers vil en anden frier helt sikkert stjæle hendes blik.", p="Hej der, flotte. Kan jeg hjælpe dig med noget?", c="Jeg har aldrig fået noget lignende før. Hvor er det smukt!"},
  [8900] = {n="Kæreste Elenia,", l="Lever den Let Krøllede Seddel til Elenia Højdon ved banken i Undergrunden.", d="Hun var så trist. Det kunne jeg se, når jeg først kiggede forbi hendes tilstand. Altså, hun virkede trist - ville du ikke også?\n\nMen efter at have talt med hende, var der en forbindelse. Jeg troede ikke, at nogen kunne forstå, hvad jeg tænkte, men hun kunne.\n\nDa jeg fortalte de andre, grinte de ad mig, så jeg talte aldrig med hende igen. Men jeg savner hende. Kan du tage dette brev til hende for mig? Jeg vil gerne være sikker på, at det finder hendes hænder.", p="Åh, og hvad skylder jeg dette besøg?", c="Man skulle ikke tro, at en ork var så veltalende. Men vi har selvfølgelig heller aldrig rigtig haft chancen for at lære dem at kende før nu. Tak, fordi du bragte dette til mig."},
  [8901] = {n="Kæreste Elenia,", l="Lever det Omhyggeligt Skrevne Brev til Elenia Højdon ved banken i Undergrunden.", d="Har du nogensinde kendt kærlighed, unge? Det var noget fremmed for mig indtil for nylig, da jeg mødte en pige fra Undergrunden, Elenia. Det er sjældent nok, at en af mit folk ser udenfor vores egen, endsige en af De Forladte.\n\nMen nu optager tanker om hende mit sind både dag og nat.\n\nHvis du kan, kunne du så tage dette brev til hende? Jeg vil gerne have, at hun kommer hertil til Mulgorr. Jeg håber, at hun siger ja.", p="Åh, og hvad skylder jeg dette besøg?", c="Hvilke venlige ord Temma skriver til mig. Men så meget som hans ord rører mig, kan jeg ikke overveje kærligheden fra et tyrefolk. I tanker, krop og sind er vi for forskellige.\n\nDet er godt, at jeg ikke behøver at modtage hans tanker personligt. Jeg kunne ikke bære at knuse hans hjerte."},
  [8902] = {n="Kæreste Elenia,", l="Lever det Kærligt Forfattede Brev til Elenia Højdon ved banken i Undergrunden.", d="For et liv siden var jeg forlovet med at gifte mig med Elenia, min barndomskæreste. Det er år siden, jeg sidst tænkte på hende, men på det seneste optager hun ofte mine tanker.\n\nMåske kan der, selv med alt det, der er sket, være lidt plads i hinandens liv til vores kærlighed.\n\nJeg er sikker på, at hun også har forandret sig. Kan du levere dette brev til hende for mig? Jeg er for nervøs til at give det personligt.", p="Åh, og hvad skylder jeg dette besøg?", c="Dette bringer minder tilbage fra et liv for længe siden, <Name>. Elenia Tor. Sådan skulle mit navn have lydt, ved du. Vi ville have haft en smuk ceremoni ude ved søens bred. Når han gik på pension, ville vi finde en gård at trække os tilbage til.\n\nSimple drømme, altså.\n\nMen hvis han så mig nu, tvivler jeg på, at han selv ville se Elenia i mig. Kun kold kød og et dødt hjerte..."},
  [8903] = {n="Farlig Kærlighed", l="Hent et Stormvindsvagtens Kort og returner det til Aristan Motter i Stormvind.", d="Der er noget unaturligt ved denne kærlighedsepidemi. Det er ikke passende, det er et torn i øjet, og i værste fald kunne det være en trussel mod selve Alliancens sikkerhed.\n\nTænk bare: Hvad hvis vagterne er blevet grebet af denne mærkelige lidelse? Noget må gøres.\n\nGå hen til en af vagterne her i Stormvind og se, om de er blevet fanget af denne dumhed.", p="Havde jeg ret i at bekymre mig? Er vagterne ramt af denne forelskelsessyge?", c="Så det er sandt. Det er ubegribeligt. Hvordan kan dette være sket? Lad mig tænke et øjeblik. Der må være en grund bag dette."},
  [8904] = {n="Farlig Kærlighed", l="Hent et Vogterens Muggent Kort og bring det til Fenstad Argyl i Undergrunden.", d="Der er noget unaturligt ved denne kærlighedsepidemi. Den er afskyelig, og da den svækker vores forsvar, kunne den være en trussel mod os alle.\n\nDet er slemt nok, at så mange af vores folk er fanget i denne latterlige opførsel. Men jeg tror, at den har spredt sig selv til vores vogtere, som burde være immune over for sådanne ting.\n\nFind en af vores vogtere og se, om de er blevet fanget af denne dumhed.", p="Havde jeg ret i at bekymre mig? Er vores idiotiske vogtere blevet overmandet?", c="Så det er sandt. Det er ubegribeligt. Hvordan kan dette være sket? Lad mig tænke et øjeblik. Der må være en grund bag dette."},
  [8905] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Vildthjerte-armbeskyttere til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om det, dem af dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabeldyrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anselig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde indsatsen værd din tid.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige foreløbig.\n\nHvis du er interesseret i at udføre mere arbejde for mig, kan jeg måske være villig til at give slip på resten af stykkerne."},
  [8906] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Udyrsjægerens Bindinger til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om det, dem af dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabeldyrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anselig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde indsatsen værd din tid.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige foreløbig.\n\nHvis du er interesseret i at udføre mere arbejde for mig, kan jeg måske være villig til at give slip på resten af stykkerne."},
