  [8918] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Bindinger af Elementerne til Mokkevar i Orgrimgrad.", d="Hilsen, <Class>! Jeg kan se på din væremåde, at du har set og forvoldt meget i denne verden. Alligevel vil jeg vædde på, at du aldrig har set et stykke rustning som dette.\n\nUdfør en lille tjeneste for mig, så vil jeg være villig til at bytte det med dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anselig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring den til mig sammen med et par guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Den gamle kobold bliver ganske glad for dette blod.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, vil jeg være villig til at overveje at skille mig af med resten af det."},
  [8919] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Rædselståge-armbeskyttere til Mokkevar i Orgrimgrad.", d="Hilsen, <Class>! Jeg kan se på din væremåde, at du har set og forvoldt meget i denne verden. Alligevel vil jeg vædde på, at du aldrig har set et stykke rustning som dette.\n\nUdfør en lille tjeneste for mig, så vil jeg være villig til at bytte det med dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anselig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring den til mig sammen med et par guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Muks bliver ganske glad for dette.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, vil jeg være villig til at overveje at skille mig af med resten af det."},
  [8920] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Armbeskyttere af Tapperhed til Mokkevar i Orgrimgrad.", d="Hilsen, <Class>! Jeg kan se på din væremåde, at du har set og forvoldt meget i denne verden. Alligevel vil jeg vædde på, at du aldrig har set et stykke rustning som dette.\n\nUdfør en lille tjeneste for mig, så vil jeg være villig til at bytte det med dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anselig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring den til mig sammen med et par guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Muks bliver ganske glad for dette.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, vil jeg være villig til at overveje at skille mig af med resten af det."},
  [8921] = {n="Den Ektoplasmiske Destillator", l="Vend tilbage til Muks Manaforvirrer i Gadgetbyen med 1 Skrøbelig Arkanitomformer, 4 Større Evige Essens, 10 Stenskæl-olie, 25 Vulkansk Aske og 40 guld.", d="Ah, du er her for mit seneste projekt... den ekstra-dimensionelle spøgelsesafslører! Desværre er jeg løbet tør for penge og mandskab.\n\nVil du hjælpe? Fremragende! Vores første opgave er at bygge en enhed, der kan høste selve dødens stof! At bygge en ektoplasmisk destillator bliver ikke let, <Name>.\n\nJeg skal bruge, at du bringer mig en arkanitomformer, nogle større evige essenser og stenskæl-olie. Jeg skal også bruge noget vulkansk aske fra lavasøerne i Brændende Stepper for at bygge et filter.", p="Jeg forstår, at materialerne er lidt dyre... men jeg lover dig, at hvert eneste af dem vil være nødvendigt!", c="Det er netop de materialer, jeg havde brug for. Ganske passende også, <Name>!\n\nOm få øjeblikke har jeg din destillator klar til brug! I mellemtiden, tag dette som belønning for at hjælpe mig med mit projekt."},
  [8922] = {n="En Overnaturlig Enhed", l="Bring den forseglede blodbeholder til Muks Manaforvirrer inde i Gadgetbyen i Tanaris.", d="Jeg må finde en måde at tale med Anthion Harmoni på... eller rettere sagt, hans spøgelse!\n\nJeg kender en ingeniør med en besynderlig interesse for det overnaturlige. Han påstår, at han kan bygge en maskine, der lader ham tale med de døde!\n\nBlodet, du indsamlede, var beregnet til ham; rejs til Gadgetbyen og bring det til ham som betaling for hans tjenester!", p="Har du noget til mig?", c="Fremragende! Lige til tiden, jeg var ved at løbe tør!\n\nSiger du, at Glædiana sendte dig?"},
  [8923] = {n="En Overnaturlig Enhed", l="Tag den forseglede giftbeholder til Muks Manaforvirrer i Gadgetbyen.", d="Du må være ganske modig, siden du blev hængende efter det der. Eller også har jeg vakt din interesse med rustningsstykket, jeg gav dig. Der er mere, hvor det kom fra, hvis du stadig er interesseret i at hjælpe mig.\n\nGiftprøverne, du indsamlede, er til en bekendt af mig, Muks Manaforvirrer, en ingeniør med interesse for det overnaturlige. Hans seneste projekt består af en enhed, der lader dig kommunikere med de døde! Mit sidste håb er at komme i kontakt med Anthion og finde ud af mere om min situation.", p="Ønsker du at tale med mig?", c="Fremragende! Lige til tiden, jeg var ved at løbe tør!\n\nSiger du, at Mokkevar sendte dig?"},
  [8924] = {n="Jagt efter Ektoplasma", l="Brug den ektoplasmiske destillator i nærheden af ikkelegemlige udøde for at indsamle 12 Forkullet Ektoplasma i Silitus, 12 Frossen Ektoplasma i Vinterkilde og 12 Stabil Ektoplasma i de Østlige Pestlande. Bring dem sammen med den ektoplasmiske destillator tilbage til Muks Manaforvirrer i Gadgetbyen.", d="Et fint stykke ingeniørarbejde, hvis jeg selv må sige det! Du bliver desværre nødt til at rejse en del, for at finde de ikkelegemlige udøde, vi har brug for.\n\nDu ser, forskellige klimaer giver forskellig konsistens til de dødes spektrale stof. De pinte nattealferne fra Silitus, åndene fra de højfødte i Vinterkilde og spøgelserne og banshees fra de Østlige Pestlande bør give os de forskellige typer ektoplasma, vi har brug for. Sørg for at placere destillatoren i nærheden, før du høster dem!", p="Har du samlet ektoplasmaet endnu, <Race>?", c="Ja, disse vil gøre det godt!\n\nVed at udnytte de overjordiske energier, der er indeholdt i disse stoffer, kan vi række ud til dem, hvis sjæle endnu ikke helt har forladt denne verden!"},
  [8925] = {n="En Bærbar Kraftkilde", l="Find Magmaherre Bokk i Brændende Stepper, skaf hans Magmakerne og bring den til Muks Manaforvirrer i Gadgetbyen.", d="Dernæst skal vi finde en stabil og bærbar energikilde til at holde ektoplasmaet aktivt. Jeg har hørt rygter om en mægtig elementar ved navn Magmaherre Bokk, hvis hjerte er en kraftfuld magmakerne - en uendelig kilde til varme!\n\nDet siges, at han kan findes i Brændende Stepper, syd for Sortklippebjerget. Bring magmakernen til mig, så har vi nok kraft til at drive den ekstra-dimensionelle spøgelsesafslører!", p="Har du fundet Magmaherren, <Name>?", c="Du har gjort det! Dette vil helt sikkert give nok energi til at drive den ekstra-dimensionelle spøgelsesafslører!"},
  [8926] = {n="Bare Kompensation", l="Bring et Vildthjerte-bælte og et sæt Vildthjerte-handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte den enhed, Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse for at redde mit skind. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover, at dem, jeg giver dig til gengæld, vil være langt bedre.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg beholder de bedste stykker, indtil dit arbejde er færdigt."},
  [8927] = {n="Bare Kompensation", l="Bring et Vildthjerte-bælte og et sæt Vildthjerte-handsker til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne situation, ville det være klogt af mig at belønne dig i henhold til din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge gennemfører det her, gør jeg resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre byttet?", c="Vores aftale står stadig. Husk bare, at dette kun er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
  [8928] = {n="En Snedig Købmand", l="Søg efter en drilling i en hule ved indgangen til Mørkehviskerkløften i det sydlige Vinterkilde, køb en Ond Elementarstang og vend tilbage til Muks Manaforvirrer i Gadgetbyen.", d="Kernen vil give os nok kraft til at drive vores enhed; nu skal vi bare bygge en stang, der kan lede den energi uden at smelte.\n\nJeg mødte en drilling i Vinterkilde, der solgte alle slags eksotiske varer. Han havde en elementarstang, der ville passe perfekt. Jeg sparker mig selv i hovedet lige nu, fordi jeg ikke købte den.\n\nHan bor i en hule ved indgangen til Mørkehviskerkløften. Snig dig derind og prøv at finde ham.\n\nSørg for, at han kun opkræver dig fyrretyve guld; det var prisen, han nævnte over for mig!", p="Har du haft held med at finde drillingen i Mørkehviskerkløften?", c="Du gjorde det! Denne stang vil passe perfekt. Nu skal vi samle det hele..."},
  [8929] = {n="I Eftersøgning af Anthion", l="Brug den ekstra-dimensionelle spøgelsesafslører ved indgangen til Stratholm og tal med Anthion Harmonis spøgelse.", d="Nå, der er ikke andet at gøre end at prøve kobolds opfindelse af. Ryget går på, at Anthion blev slået ned af de udøde legioner i Stratholm, da han forsøgte at træde ind gennem portene.\n\nPrøv at bruge enheden der og find ud af, hvad Anthion vidste.", c="Glædiana fik dig til at kontakte mig? Jeg vil gøre mit bedste for at hjælpe dig, men først må jeg bede dig om en stor tjeneste."},
  [8930] = {n="I Eftersøgning af Anthion", l="Brug den ekstra-dimensionelle spøgelsesafslører ved indgangen til Stratholm og tal med Anthion Harmonis spøgelse.", d="Meget vel, <Name>. Alt, hvad der er tilbage, er at sætte kobolds opfindelse på prøve. Ryget går på, at Anthion blev dræbt af de udøde legioner i Stratholm, da han forsøgte at træde ind gennem portene.\n\nPrøv at bruge enheden der og se, om du faktisk kan tale med de døde!", c="Mokkevar fik dig til at kontakte mig? Jeg vil gøre mit bedste for at hjælpe dig, men først må jeg bede dig om en stor tjeneste."},
  [8931] = {n="Bare Kompensation", l="Bring et Udyrsjægerens Bælte og et sæt Udyrsjægerens Handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte den enhed, Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse for at redde mit skind. Bring mig et almindeligt bælte og et sæt handsker, du ønsker at opgradere.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg beholder de bedste stykker, indtil dit arbejde er færdigt."},
  [8932] = {n="Bare Kompensation", l="Bring et Magisterens Bælte og et sæt Magisterens Handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte den enhed, Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse for at redde mit skind. Bring mig et almindeligt bælte og et sæt handsker, du ønsker at opgradere.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg beholder de bedste stykker, indtil dit arbejde er færdigt."},
