  [8935] = {n="Bare Kompensation", l="Bring et Skyggehåndværks-bælte og et sæt Skyggehåndværks-handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte den enhed, Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse for at redde mit skind. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover, at dem, jeg giver dig til gengæld, vil være langt bedre.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg beholder de bedste stykker, indtil dit arbejde er færdigt."},
  [8936] = {n="Bare Kompensation", l="Bring et Rædselståge-bælte og et sæt Rædselståge-bind til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, at en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde mit skind. Bring mig det bælte og det sæt handsker, du ønsker at opgradere. Jeg lover, at dem, jeg giver dig til gengæld, vil være langt bedre.", p="Er du klar til at gennemføre byttehandelen?", c="Du har holdt din ende af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg gemmer de bedste stykker, indtil dit arbejde er færdigt."},
  [8937] = {n="Bare Kompensation", l="Bring et Bælte med Tapperhed og et sæt Handsker med Tapperhed til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, at en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde mit skind. Bring mig det bælte og det sæt handsker, du ønsker at opgradere. Jeg lover, at dem, jeg giver dig til gengæld, vil være langt bedre.", p="Er du klar til at gennemføre byttehandelen?", c="Du har holdt din ende af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg gemmer de bedste stykker, indtil dit arbejde er færdigt."},
