  [8942] = {n="Bare Kompensation", l="Bring en Snor med Elementer og et sæt Handsker med Elementer til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne knibe, ville det være klogt af mig at belønne dig efter din præstation.\n\nForeløbig vil jeg bytte dit bælte og dine handsker. Hvis vi begge får dette igennem, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at gennemføre byttehandelen?", c="Vores aftale står ved magt. Husk bare, at dette kun er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, og jeg vil belønne dig med genstande af virkelig stor kraft."},
  [8943] = {n="Bare Kompensation", l="Bring et Rædselståge-bælte og et sæt Rædselståge-bind til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne knibe, ville det være klogt af mig at belønne dig efter din præstation.\n\nForeløbig vil jeg bytte dit bælte og dine handsker. Hvis vi begge får dette igennem, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at gennemføre byttehandelen?", c="Vores aftale står ved magt. Husk bare, at dette kun er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, og jeg vil belønne dig med genstande af virkelig stor kraft."},
  [8944] = {n="Bare Kompensation", l="Bring et Bælte med Tapperhed og et sæt Handsker med Tapperhed til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne knibe, ville det være klogt af mig at belønne dig efter din præstation.\n\nForeløbig vil jeg bytte dit bælte og dine handsker. Hvis vi begge får dette igennem, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at gennemføre byttehandelen?", c="Vores aftale står ved magt. Husk bare, at dette kun er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, og jeg vil belønne dig med genstande af virkelig stor kraft."},
  [8945] = {n="De Dødes Bøn", l="Gå ind i Stratholm og red Ysida Harmoni fra Baron Flodfarer.", d="Jeg giver dig de oplysninger, du beder om, <Name>. Men mere presserende sager er på spil.\n\nMin elskede hustru er blevet taget til fange af Flodfarers udøde skarn.\n\nJeg protesterede kraftigt mod, at hun sluttede sig til Sølvdæmringens tåbelige korstog, men det er ikke længere vigtigt. Du må fuldføre det, jeg forsøgte at gøre, du må befri Ysidå fra baronens kløer!", p="Fortæl mig, er Ysidå i live?", c="Tak, fordi du reddede mig... Jeg frygtede for mit liv. Accepter venligst dette som en lille gave af taknemmelighed.\n\nAnthion er... nej... det kan da ikke passe, at han..."},
  [8946] = {n="Bevis på Liv", l="Bring Ysidås Medaljon til Anthion Harmoni i Østlige Pestlande.", d="Det er den grusomste skæbne, at min elskede er omkommet, mens hun forsøgte at redde mig. Alligevel påstår du, at du har evnen til at tale med ham.\n\nBring ham denne medaljon som bevis på, at jeg har det godt. Han må ikke dvæle i denne verden; mit hjerte ville ikke kunne bære det.\n\nFarvel, <Name>. Jeg vil altid stå i din gæld.", p="Ysidå... er hun i live?", c="Den medaljon... du fandt hende! Endelig kan jeg hvile i fred.\n\nJeg vil nu besvare alle de spørgsmål, du måtte have, <Name>. Men skynd dig, min tid i denne verden er ikke lang."},
  [8947] = {n="Anthions Mærkelige Anmodning", l="Bring 3 Mørkejern-stænger, 20 Fortryllet Læder, 3 Månestof og 4 Garvede Barske Huder til Anthion Harmoni i Østlige Pestlande.", d="Vi indså ikke, hvor vigtig Valtalaks medaljon var, så den blev delt sammen med resten af byttet. Det første stykke blev taget af en dværg ved navn Tyldren. Jeg forsøgte at hente det fra ham, og han slog mig næsten ihjel. Du må tage fragmentet med magt.\n\nSidst jeg hørte om ham, var han blevet gladiator for mørkejern-dværgene. Det bliver dog en lille udfordring at få ham til at kæmpe mod dig.\n\nSaml følgende materialer til mig. Du får brug for dem.", p="Fik du de materialer, jeg bad om, <Name>?", c="Fortræffeligt. Jeg vil omdanne disse til noget, der passer bedre til vores behov."},
  [8948] = {n="Anthions Gamle Ven", l="Tag det ufuldstændige Provokationsbanner til Falrøn Træformer i biblioteket i Rædselshammeren.", d="Tyldren er ikke en, der frivilligt deltager i en fair kamp. Jeg har formet dette banner, så det viser hans families farver.\n\nMed lidt ekstra trolddom vil dette banner provokere ham på en måde, han ikke kan modstå.\n\nEn gammel bekendt af mig ved navn Falrøn kender den præcise procedure, der kræves. Han har en særlig måde at... irritere folk på. Du finder ham i biblioteket i Rædselshammeren.", p="Tal op, fremmede, kan du ikke se, at jeg er optaget?", c="Anthion sendte dig, siger du? Jeg troede, han var død. Jeg må have hørt mærkeligere ting i mit liv.\n\nVel, så. Hvad er det, du vil have mig til at gøre med dette banner?"},
  [8949] = {n="Falrøns Blodhævn", l="Saml 25 Oger-krigsperler fra Oger i Rædselshammeren eller Sortklippe-spiret og vend tilbage til Falrøn Træformer i Athenæum i Rædselshammeren.", d="Ja, det er sandt, at jeg er bekendt med den fortryllelse, du har brug for, <Class>. Men jeg er ikke en, der uden videre giver tjenester, selv hvis du blev sendt hertil af en gammel ven.\n\nJeg har intet andet end had og foragt for vores brutale oger-naboer. Og ikke kun dem, jeg hader Omkrogs tilhængere lige så meget, som jeg hader dem, der følger Gordøk.\n\nJeg vil have dig til at dræbe dem. Dræb en masse af dem! Bring mig de perler, de bærer om halsen, som bevis på dit arbejde. Gør du dette, taler vi om din anmodning.", p="Har du udført den tjeneste, jeg bad dig om, <Name>?", c="Hmmm... underligt nok føler jeg mig ikke bedre tilpas over min brors død ved hænderne på de brutale.\n\nNåja, du holdt din ende af aftalen. Lad os se, hvad jeg kan gøre for dig."},
  [8950] = {n="Anstifterens Fortryllelse", l="Bring følgende til Falrøn Træformer i Rædselshammeren: 1 Hånende Spøgelses Essens, 4 Mørke Runer og 8 Store Strålende Skår.", d="Jeg kan nemt placere den fortryllelse, du har brug for, på banneret, <Name>. Desværre har jeg ikke de materialer, jeg skal bruge, for det er meget sjældent, at nogen beder om den slags fortryllelse.\n\nJeg skal bruge essensen fra et af de Ældreth-spøgelser, der hjemsøger disse haller, en håndfuld Skolomance-mørke runer og nogle store strålende skår. Bring mig disse reagenser, så udfører jeg opgaven for dig.", p="Har du samlet de materialer, jeg kræver, <Name>?", c="Ja, disse vil gøre det fint. Når jeg er færdig, vil ingen kraft i verden kunne forhindre dit offer i at acceptere din udfordring."},
  [8951] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Vildthjerte Støvler, en Vildthjerte Kilt og Vildthjerte Skulderstykker.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8952] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Udyrsjægerens Støvler, Udyrsjægerens Bukser og Udyrsjægerens Skulderkappe.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8953] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Magisterens Støvler, Magisterens Benbeskyttere og Magisterens Skulderkappe.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
