  [8955] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Hengivne Sandaler, et Hengivent Nederdel og en Hengivent Skulderkappe.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8956] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Skyggehåndværks Støvler, Skyggehåndværks Bukser og Skyggehåndværks Skulderstykker.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8957] = {n="Anthions Afskedsord", l="Vend tilbage til Mokkevar i Orgrimgrad med et sæt Støvler med Elementer, en Kilt med Elementer og Skulderplader med Elementer.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8958] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Rædselståge Sandaler, Rædselståge Benbeskyttere og en Rædselståge Skulderkappe.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8959] = {n="Anthions Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Støvler med Tapperhed, Benplader med Tapperhed og Skulderstykker med Tapperhed.", d="Valtalaks sjæl blev gemt i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til den forbandelse, der ventede os.\n\nDen eneste måde at stoppe Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for én gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os ordne din belønning.", c="Jeg kan ikke tro, at vores liv næsten er tabt på grund af en dum medaljon! Og du er sikker på, at Anthion nævnte Bodlej?\n\nNå, du har gjort dit arbejde, så lad os få din belønning overstået."},
  [8960] = {n="Bodlejs Uheldige Skæbne", l="Rejs til Sortklippebjerget og brug Den Ekstra-dimensionale Spøgelsesafslører for at finde Bodlej nær Sortklippe-spiret.", d="Så vi må gendanne resten af medaljonen? At finde Bodlej bliver en lille hovedpine. Han vendte tilbage til Sortklippebjerget for at forsøge at gå ind i Sortklippe-spiret igen og kom aldrig tilbage.\n\nJeg vil foreslå, at du tager koboldens spøgelsesafslørende apparat med dig, for jeg frygter, at det værste kan være sket.", c="Jeg er så glad for, at du kan se mig. Endelig nogen at tale med!\n\nVil du hjælpe os, <Name>? Hjælpe med at gøre op for den uret, vi begik, og bringe tingene på plads? Hvis det er sandt, at du allerede har Lord Valtalaks Amuletts Øverste Stykke, så tror jeg, at jeg kan pege dig i den rigtige retning for at skaffe de to andre dele, samle dem igen og få ende på alt dette.\n\nÅh, forresten, hej, mit navn er Bodlej. Dejligt at møde dig!"},
  [8961] = {n="Tre Ildens Konger", l="Saml Incendicit fra Brandius, Glød fra Glødeseer og Glød fra Gløder, sammen med et Helliget Kulbækken, og bring dem tilbage til Bodlej inde i Sortklippebjerget.", d="For at tilkalde Herre Valtalak må vi først skaffe de andre to tredjedele af amuletten. Til det skal vi bruge et kulbækken og nogle særlige kul at brænde i det.\n\nDer er tre adelsmænd af ild: Herre Brandius i Sortklippe-dybderne, Pyrovagten Glødeseer i Sortklippe-spiret og Hertugen af Gløder i Silitus, og de har det, vi behøver. Saml et stykke af hver af deres rester, og vend derefter tilbage til mig med et Helliget Kulbækken, som kan købes hos Sølvdæmringen, hvis de har æret dig.", p="Det var vores dumhed... vores undergang, at vi tog det sidste job. Havde vi bare ikke ved et uheld stjålet Herre Valtalaks ånd, som var fanget i amuletten; havde der bare ikke været dem i vores lejesoldatgruppe, der var så grådige og delte den imellem sig. Jeg ville være i live i dag, måske tømmende en øl eller kastende et af mine børn op i luften.\n\n<Name>, lad ikke de uædles grådighed i vort gamle lejesoldatkompagni blive din undergang også.", c="Jeg er imponeret, <Class>, men der er ingen tid at spilde. Jeg giver dig din næste opgave, for du skal stadig skaffe nogle få flere vigtige komponenter, før vi kan fortsætte.\n\nTal med mig igen, når du føler dig klar til udfordringen, der venter forude."},
  [8962] = {n="Vigtige Komponenter", l="Skaf Druidiske Rester og bring dem tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi har kulbækkenet og midlet til at tænde det, mangler vi stadig en komponent at gennemtrænge det med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nMor Gråhov, vores fremmeste druide, havde mange nære venner blandt Cenarion-kredsen, og nogle af dem er faldet for silitiderne. Jeg vil have dig til at hente nogle Druidiske Rester fra de silitider, der holder til omkring Bikube'Regal i det sydøstlige Silitus.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde restens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at tage til den nederste del af Sortklippe-spiret, til kammeret hvor Krigsmester Voone residerer i Tazz'Alaorsalen, og bruge kulbækkenet til at fremkalde den fordærvede ånd af min tidligere kammerat, Mor Gråhov. Han kan ikke hvile, før amuletstykket er taget fra ham."},
  [8963] = {n="Vigtige Komponenter", l="Skaf en Stjernebrise-landsbyens Relikvie og bring den tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi har kulbækkenet og midlet til at tænde det, mangler vi stadig en komponent at gennemtrænge det med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nIsalin, vores præstinde, voksede op i Vinterkilde ved Stjernebrise-landsbyen. Jeg vil have dig til at hente en Stjernebrise-landsbyens Relikvie fra Frostslæggen-kæmperne i Frostviske-kløften i det sydlige Vinterkilde, som fra tid til anden er kendt for at plyndre mod nord.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde relikviens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at tage til Ældretharrs Helligdom i den østlige fløj af Rædselshammeren og bruge kulbækkenet til at fremkalde min tidligere kammerat Isalins ånd. Hendes ånd er blevet fordærvet af, at hun besidder amuletstykket og den del af Valtalaks sjæl, der er i det."},
  [8964] = {n="Vigtige Komponenter", l="Hent et Strålende Sværd af Nidkærhed og bring det tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi har kulbækkenet og midlet til at tænde det, mangler vi stadig en komponent at gennemtrænge det med; noget der giver et fokus stærkt nok til at kalde resterne af mine afdøde, tidligere kammerater frem.\n\nSøskendeparret, Jarjen og Sothas, var tilhængere af Skarlagenrøde Korstog. De stræbte efter ridderskab inden for den grumme organisation. Gå til Tyrs Hånd i Østlige Pestlande og hent et Strålende Sværd af Nidkærhed fra praetorianerne der.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde sværdets essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at komme ind i Den Karmosinrøde Trone inde i Skarlagen-bastionen i Stratholm og bruge kulbækkenet til at fremkalde resterne af mine tidligere kammerater, Jarjen og Sothas. Deres sjæle er blevet endnu mere vredet af, at de besidder Valtalaks amuletstykke og hans ånd i det."},
  [8965] = {n="Vigtige Komponenter", l="Skaf Sjælsaske fra de Forviste og bring dem tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi har kulbækkenet og midlet til at tænde det, mangler vi stadig en komponent at gennemtrænge det med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nEn oger-nekromant, der rejste med os, Kormøk, nød at tilkalde sjælene fra de forviste døde på Renselsesøen, ud for Hillsbrad-forbjergenes sydkyst. Tag derhen og hent noget Sjælsaske fra de Forviste fra deres rester.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde askens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at komme ind i Skolomance, til Ras Frostviskes kammer, og bruge kulbækkenet til at fremkalde min tidligere kammerat, Kormøk. Amuletstykket og Valtalaks ånd i det har fordærvet ham endnu mere, og han vil ikke hvile, før du med magt tager det fra ham."},
  [8966] = {n="Venstre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Mor Gråhovs ånd og dræb ham. Vend tilbage til Bodlej inde i Sortklippebjerget med Venstre Stykke af Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Min ven, Mor Gråhov, var den første, der faldt offer for besiddelsen af et stykke af Herre Valtalaks amulet og det fordærvende ånde-fragment, det indeholder. Efter at have stjålet Valtalaks besværgelsesbog og amulet flygtede vi for livet fra den øvre del af Sortklippe-spiret. Undervejs faldt Mor ned i den nedre del af spiret.\n\nSenere opdagede vi, at han overlevede faldet, kun for at blive fanget og torteret af Krigsmester Voone. Et par spektrale snigmordere sneg sig ind og dræbte ham lige foran Voone.", p="Er det så gjort? Du har hentet Venstre Stykke af Herre Valtalaks amulet og endelig lagt min gamle kammerat, Mor Gråhovs, ånd til hvile?", c="Du har gjort en stor gerning, <Name>. En ånd hviler i fred, men der er stadig meget arbejde, før vi kan lægge alt dette bag os.\n\nDesværre kender jeg ikke placeringen af den, der døde med højre stykke af amuletten i sin besiddelse. Men frygt ikke; i mit liv var jeg en amatør i spådomskunst, så jeg har en anden opgave til dig, som vil gøre det muligt for os at opspore det sidste stykke."},
  [8967] = {n="Venstre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Isalins ånd og dræb hende. Vend tilbage til Bodlej inde i Sortklippebjerget med Venstre Stykke af Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Det blev os bekendt senere, mens vi gjorde, hvad vi kunne for at overleve, at Isalin, en nattenisse-præstinde i vores kompagni, var draget til nattenissernes stamby, nu kendt som Rædselshammeren. Ud fra det vi samlede op, tog hun derhen både af personlige grunde og for at låse hemmelighederne op om amuletstykket, hun havde i sin besiddelse.\n\nHun nåede dog ikke helt frem. Der kom bud til os om, at hun blev bagholdt ved Ældretharrs Helligdom af Alzzin Vildformeren og hans styrker.", p="Du har vel ikke allerede klaret redningen af Isalins ånd og hentningen af Venstre Stykke af Herre Valtalaks amulet, <Name>?", c="Tak, <Name>, for at have lagt Isalins ånd til hvile. Nu finder hun måske fred hos sin gudinde. Men der venter stadig et stort stykke arbejde, hvis vi skal komme ud af denne fine klemme, vi står i.\n\nDesværre kender jeg ikke placeringen af den, der døde med højre stykke af amuletten i sin besiddelse. Men frygt ikke; i mit liv var jeg en amatør i spådomskunst, så jeg har en anden opgave til dig, som vil gøre det muligt for os at opspore det sidste stykke."},
  [8968] = {n="Venstre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Jarjen og Sothas og dræb dem. Vend tilbage til Bodlej inde i Sortklippebjerget med Venstre Stykke af Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Søskendeparret, Jarjen og Sothas, besluttede at slutte sig til Skarlagenrøde Korstog, da vores lejesoldatkompagni blev opløst. De tog Venstre Stykke af Herre Valtalaks Amulet med sig. Godt så, siger jeg, men vi har brug for det stykke tilbage.\n\nAf det vi kunne samle op, blev de faktisk dræbt af Storslået Korsfarer Dathrovan selv, fordi de dumpede indvielsesritualet i hans kammer i Skarlagen-bastionen.\n\nUnder alle omstændigheder skal vi... altså dig, stadig hente det stykke af amuletten.", p="Betyder det så, <Class>, at du allerede har lagt sjælene af de to tosser til hvile og hentet Venstre Stykke af Herre Valtalaks amulet?", c="Jeg antager, det er det bedste, at de to sjæle endelig er lagt til hvile, selvom jeg ikke kunne lide dem, mens de levede. Under alle omstændigheder har vi det, vi ledte efter, og det er bestemt en god ting!\n\nDesværre kender jeg ikke placeringen af den, der døde med højre stykke af amuletten i sin besiddelse. Men frygt ikke; i mit liv var jeg en amatør i spådomskunst, så jeg har en anden opgave til dig, som vil gøre det muligt for os at opspore det sidste stykke."},
  [8969] = {n="Venstre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Kormøks ånd og dræb ham. Vend tilbage til Bodlej inde i Sortklippebjerget med Venstre Stykke af Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Nu har vi det, vi har brug for, så det er tid til at tale om, hvem det er, du skal tilkalde.\n\nKormøk var ok for en oger, lige indtil han vendte sig mod nekromanti. Derefter blev tingene uhyggelige for stort set alle i kompagniet. Det var så ingen overraskelse, da han tog sit stykke af amuletten og vendte tilbage til sit nye hjem, Skolomance.\n\nMen selv der, eller måske især der, var han ikke sikker for de spektrale snigmordere. De dræbte ham lige foran sin mester, Ras Frostviske.", p="Jeg roser dig, <Name>, hvis du er vendt tilbage med Venstre Stykke af amuletten. Hvis ikke, så tag dig af det, for der er ingen tid at spilde, det forsikrer jeg dig!", c="Godt arbejde, <Name>! Kormøk var ikke så slem for en oger, i hvert fald ikke mens han stadig var i live, så jeg håber, han får den hvile, han fortjener. Men der er mere arbejde forude.\n\nDesværre kender jeg ikke placeringen af den, der døde med højre stykke af amuletten i sin besiddelse. Men frygt ikke; i mit liv var jeg en amatør i spådomskunst, så jeg har en anden opgave til dig, som vil gøre det muligt for os at opspore det sidste stykke."},
  [8970] = {n="Jeg Ser Alcaz-øen i Din Fremtid...", l="Saml 20 Blodtang fra Strashaz-slangefolket og vend derefter tilbage til Bodlej inde i Sortklippebjerget.", d="Som jeg sagde, <Class>, flirtede jeg i mine levende år med at blive spåmand. Men der var egentlig ikke så meget profit i det, som du måske tror, mest fordi det er farligt, og reagenserne er sjældne og dyre. Dog ved jeg nok til at kunne pege på det sidste stykke af amuletten og sammen med det min tidligere kammerats ånd.\n\nDet er her, du kommer ind i billedet, <Name>. Jeg vil have dig til at tage til Alcaz-øen ud for kysten af Støvsumpen og samle Blodtang fra de Strashaz-slangefolk, der lever der.", p="Blodtang, <Name>, en stor bunke af det, er hvad jeg behøver for at drive mine spådomsbesværgelser. Du bliver sandsynligvis nødt til at tage mindst et par venner med til Alcaz-øen for at samle det... de Strashaz er et ondt pak!", c="Ærligt talt, <Name>, er jeg overrasket over, at du kom tilbage i ét stykke. Men igen, jeg gætter på, at Alcaz-øen er det mindste af dine bekymringer lige nu.\n\nOk, giv mig et øjeblik her... spådomskunst er ikke noget, man bare kan knipse med fingrene og forvente præcise svar fra."},
  [8977] = {n="Vend Tilbage til Glædiana", l="Bring den Ekstra-dimensionale Spøgelsesafslører til Glædiana i Jernsmede.", d="Det har været en fornøjelse at arbejde sammen med dig, <Name>. Her er det færdige produkt.\n\nJeg håber, det hjælper dig i dine nuværende bestræbelser. Og hey, hvis du ikke har noget imod det, så hjælp med at sprede budskabet. Jeg ville ikke have noget imod flere kunder!", p="Er du vendt tilbage?", c="Udmærket! Du har klaret dig godt, <Name>. Jeg er ikke sikker på, at jeg stoler på kobolden håndværk, men jeg har ingen andre muligheder."},
  [8978] = {n="Vend Tilbage til Mokkevar", l="Vend tilbage til Mokkevar i Orgrimgrad med den Ekstra-dimensionale Spøgelsesafslører.", d="Det har været en fornøjelse at arbejde sammen med dig, <Name>. Her er det færdige produkt.\n\nJeg håber, det hjælper dig i dine nuværende bestræbelser. Og hey, hvis du ikke har noget imod det, så hjælp med at sprede budskabet. Jeg ville ikke have noget imod flere kunder!", p="Er du vendt tilbage med apparatet?", c="Du er vendt tilbage med apparatet! Jeg er imponeret over din hengivenhed, <Name>. Fremragende arbejde."},
  [8979] = {n="Fenstads Anelse", l="Bring 1 Flaske Kølnervand og 1 Flaske Parfume til Apoteker Zinge i Underbyens Apotekerium.", d="Jeg tror, jeg kender årsagen til denne nylige adfærd. Har du lugtet den nye duft i vinden, over stanken fra kanalerne? De nye kølnervand og parfumer, der er kommet på mode?\n\nVores tankegang er blevet tåget af en kedelig alkymi.\n\nDer er kun én måde at være sikker på - bring en flaske kølnervand og parfume til min ven, Apoteker Zinge. Det Kongelige Apotekerselskab vil finde sandheden.\n\nJeg vil refundere jer for købet, når I vender tilbage.", p="Hvordan kan jeg tjene dig?", c="Endnu en af Fenstads besættelser, ser jeg. Tror han, at Det Kongelige Apotekerselskab ikke har noget bedre at tage sig til, end at udføre hans små undersøgelser?\n\nVel, jeg vil endnu engang imødekomme ham."},
  [8980] = {n="Zinges Vurdering", l="Vend tilbage til Fenstad Argyl uden for banken i Underbyen.", d="Det her er uventet. Det ser ud til, at Fenstad måske alligevel er på noget. Jeg fandt spor af stoffer, der bruges i sindskontrolerende eliksirer.\n\nDet er ikke ukendt, at parfumer indeholder noget af dette, men nogle af ingredienserne, jeg opdagede... Dette er seriøs alkymi, på niveau med et medlem af Det Kongelige Apotekerselskab.", c="Så jeg havde ret. Vi må ikke spilde tid. Vi må finde ud af kilden til disse forurenede dufte.\n\nHer, for at betale dig tilbage for købet af kølnervandet og parfumen."},
  [8982] = {n="Sporer Kilden", l="Tal med Krovært Nordmand i Underbyen.", d="Vi må finde ud af, hvem leverandøren er. Jeg lagde mærke til Apoteker Katrina med en flaske af parfumen gemt i sin pakke. Hun fortalte mig, at hun havde købt den af Nordmand, kroværen.", c="Ah ja, jeg har lige fået nyt lager af parfumen og kølnervandet. Jeg ved ikke, hvor længe jeg kan holde det på hylderne - det ser ud til, at ingen kan få nok af det.\n\nHvis du spørger mig, forstår jeg ikke, hvad det store nummer er."},
  [8983] = {n="Sporer Kilden", l="Tal med Mara Rendesen i skrædderbutikken i Underbyens Magikerkvarter.", d="Er der noget galt med mit produkt? Nå, jeg har aldrig set så mange mennesker ønske sig noget så slemt.\n\nJeg købte mit lager fra en købmand ved navn Mara Rendesen. Hun er ny i byen.\n\nHun nævnte, at hun havde nogle varer, hun skulle levere til skrædderen i Magikerkvarteret.", c="Jeg er bange for, at jeg solgte hele mit lager af parfume og kølnervand til Nordmand, kroværen. Hvis du vil have noget, bør du tale med ham - forudsat at han har noget tilbage.\n\nDu bør dog ikke spilde nogen tid. Jeg tror, du vil finde kølnervandet uimodståeligt."},
  [8984] = {n="Kilden Afsløret", l="Find Apoteker Stavron Lerret i Hillsbrad-forbjergene forbi Ravnehold-herregården.", d="Se, en useriøs apotekers handlinger er ikke min sag. Hvis han underminerer vores bestræbelser, så lad mig være den første til at pege dig i den rigtige retning\n\nHvis han er uskyldig, så har han intet at skjule, ikke?\n\nJeg købte varerne af Apoteker Stavron Lerret. Han arbejder i et afsondret område forbi Ravnehold-herregården i bakkerne over Hillsbrad. For at være ærlig over for dig, syntes jeg, han var lidt underlig.", c="Ja, jeg lavede de dufte. Vidunderlig lugt, ikke? Uimodståelig.\n\nNår Alliancens og Hordens krigere begge bliver forelsket i disse følelser, vil de være magtesløse over for Skyggerådets opstigning.\n\nDe vil blive svækket, uforberedte. Mens de bekymrer sig om deres kære, vil de miste deres skarphed.\n\nLøsningen var så enkel. Hvorfor tog det mig så lang tid at finde den? Alles svaghed går gennem hjertet. Og der er intet, du kan gøre for at stoppe det uundgåelige."},
  [8985] = {n="Flere Vigtige Komponenter", l="Skaf en Stjernebrise-landsbyens Relikvie og bring den tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi kender placeringen af det sidste amuletstykke, mangler vi stadig en komponent at gennemtrænge kulbækkenet med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nIsalin, vores præstinde, voksede op i Vinterkilde ved Stjernebrise-landsbyen. Jeg vil have dig til at hente en Stjernebrise-landsbyens Relikvie fra Frostslæggen-kæmperne i Frostviske-kløften i det sydlige Vinterkilde, som fra tid til anden er kendt for at plyndre mod nord.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde relikviens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at tage til Ældretharrs Helligdom i den østlige fløj af Rædselshammeren og bruge kulbækkenet til at fremkalde min tidligere kammerat Isalins ånd. Hendes ånd er blevet fordærvet af, at hun besidder amuletstykket og den del af Valtalaks sjæl, der er i det.\n\nÅh, i øvrigt havde jeg noget blodtang til overs fra din tur til Alcaz-øen, så jeg lavede det om til nogle eliksirer til dig. Vælg bare!"},
  [8986] = {n="Flere Vigtige Komponenter", l="Skaf Druidiske Rester og bring dem tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi kender placeringen af det sidste amuletstykke, mangler vi stadig en komponent at gennemtrænge kulbækkenet med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nMor Gråhov, vores fremmeste druide, havde mange nære venner blandt Cenarion-kredsen, og nogle af dem er faldet for silitiderne. Jeg vil have dig til at hente nogle Druidiske Rester fra de silitider, der holder til omkring Bikube'Regal i det sydøstlige Silitus.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde restens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at tage til den nederste del af Sortklippe-spiret, til kammeret hvor Krigsmester Voone residerer i Tazz'Alaorsalen, og bruge kulbækkenet til at fremkalde den fordærvede ånd af min tidligere kammerat, Mor Gråhov. Han kan ikke hvile, før amuletstykket er taget fra ham.\n\nÅh, i øvrigt havde jeg noget blodtang til overs fra din tur til Alcaz-øen, så jeg lavede det om til nogle eliksirer til dig. Vælg bare!"},
  [8987] = {n="Flere Vigtige Komponenter", l="Hent et Strålende Sværd af Nidkærhed og bring det tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi kender placeringen af det sidste amuletstykke, mangler vi stadig en komponent at gennemtrænge kulbækkenet med; noget der giver et fokus stærkt nok til at kalde resterne af mine afdøde, tidligere kammerater frem.\n\nSøskendeparret, Jarjen og Sothas, var tilhængere af Skarlagenrøde Korstog. De stræbte efter ridderskab inden for den grumme organisation. Gå til Tyrs Hånd i Østlige Pestlande og hent et Strålende Sværd af Nidkærhed fra praetorianerne der.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde sværdets essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at komme ind i Den Karmosinrøde Trone inde i Skarlagen-bastionen i Stratholm og bruge kulbækkenet til at fremkalde resterne af mine tidligere kammerater, Jarjen og Sothas. Deres sjæle er blevet endnu mere vredet af, at de besidder Valtalaks amuletstykke og hans ånd i det.\n\nÅh, i øvrigt havde jeg noget blodtang til overs fra din tur til Alcaz-øen, så jeg lavede det om til nogle eliksirer til dig. Vælg bare!"},
  [8988] = {n="Flere Vigtige Komponenter", l="Skaf Sjælsaske fra de Forviste og bring dem tilbage til Bodlej inde i Sortklippebjerget.", d="<Class>, lyt godt efter. Nu hvor vi kender placeringen af det sidste amuletstykke, mangler vi stadig en komponent at gennemtrænge kulbækkenet med; noget der giver et fokus stærkt nok til at lokke ånden fra min afdøde, tidligere kammerat.\n\nEn oger-nekromant, der rejste med os, Kormøk, nød at tilkalde sjælene fra de forviste døde på Renselsesøen, ud for Hillsbrad-forbjergenes sydkyst. Tag derhen og hent noget Sjælsaske fra de Forviste fra deres rester.", p="Er du allerede tilbage, <Class>, med det, jeg sendte dig ud for at hente?", c="Veludført stykke arbejde, <Name>. Jeg vil indgyde askens essens i kulbækkenet.\n\nNu er det eneste, der er tilbage, at komme ind i Skolomance, til Ras Frostviskes kammer, og bruge kulbækkenet til at fremkalde min tidligere kammerat, Kormøk. Amuletstykket og Valtalaks ånd i det har fordærvet ham endnu mere, og han vil ikke hvile, før du med magt tager det fra ham.\n\nÅh, i øvrigt havde jeg noget blodtang til overs fra din tur til Alcaz-øen, så jeg lavede det om til nogle eliksirer til dig. Vælg bare!"},
  [8989] = {n="Det Højre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Mor Gråhovs ånd og dræb ham. Vend tilbage til Bodlej inde i Sortklippebjerget med den genforenede Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Min ven, Mor Gråhov, var den første, der faldt offer for besiddelsen af et stykke af Herre Valtalaks amulet og det fordærvende ånde-fragment, det indeholder. Efter at have stjålet Valtalaks besværgelsesbog og amulet flygtede vi for livet fra den øvre del af Sortklippe-spiret. Undervejs faldt Mor ned i den nedre del af spiret.\n\nSenere opdagede vi, at han overlevede faldet, kun for at blive fanget og torteret af Krigsmester Voone. Et par spektrale snigmordere sneg sig ind og dræbte ham lige foran Voone.", p="Er det så gjort? Du har hentet Det Højre Stykke af Herre Valtalaks amulet, samlet amuletten til ét stykke og endelig lagt min gamle kammerat, Mor Gråhovs, ånd til hvile?", c="Tak, <Name>, for at have hjulpet Mor Gråhov. Endnu en ånd hviler i fred, og nu har vi den samlede amulet! Men vi står stadig over for den hårdeste prøve.\n\nFor at kalde Herre Valtalak frem skal kulbækkenet stilles ind, og der er nogle flere ting, der skal samles og bringes tilbage til mig her."},
  [8990] = {n="Det Højre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Isalins ånd og dræb hende. Vend tilbage til Bodlej inde i Sortklippebjerget med den genforenede Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Det blev os bekendt senere, mens vi gjorde, hvad vi kunne for at overleve, at Isalin, en nattenisse-præstinde i vores kompagni, var draget til nattenissernes stamby, nu kendt som Rædselshammeren. Ud fra det vi samlede op, tog hun derhen både af personlige grunde og for at låse hemmelighederne op om amuletstykket, hun havde i sin besiddelse.\n\nHun nåede dog ikke helt frem. Der kom bud til os om, at hun blev bagholdt ved Ældretharrs Helligdom af Alzzin Vildformeren og hans styrker.", p="Du har vel ikke allerede klaret redningen af Isalins ånd og hentningen af Det Højre Stykke af Herre Valtalaks amulet, <Name>? Husk at samle amulettens stykker, før du giver den til mig.", c="Tak, <Name>, for at have lagt Isalins ånd til hvile. Nu finder hun måske fred hos sin gudinde. Og vi har også den samlede amulet! Men vi står stadig over for den hårdeste prøve.\n\nFor at kalde Herre Valtalak frem skal kulbækkenet stilles ind, og der er nogle flere ting, der skal samles og bringes tilbage til mig her."},
  [8991] = {n="Det Højre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Jarjen og Sothas og dræb dem. Vend tilbage til Bodlej inde i Sortklippebjerget med den genforenede Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Søskendeparret, Jarjen og Sothas, besluttede at slutte sig til Skarlagenrøde Korstog, da vores lejesoldatkompagni blev opløst. De tog Det Højre Stykke af Herre Valtalaks Amulet med sig. Godt så, siger jeg, men vi har brug for det stykke tilbage.\n\nAf det vi kunne samle op, blev de faktisk dræbt af Storslået Korsfarer Dathrovan selv, fordi de dumpede indvielsesritualet i hans kammer i Skarlagen-bastionen.\n\nUnder alle omstændigheder skal vi... altså dig, stadig hente det stykke af amuletten.", p="Betyder det så, <Class>, at du allerede har lagt sjælene af de to tosser til hvile og samlet stykkerne af Herre Valtalaks amulet igen?", c="Jeg antager, det er det bedste, at de to sjæle endelig er lagt til hvile, selvom jeg ikke kunne lide dem, mens de levede. Under alle omstændigheder har vi det, vi ledte efter, og nu er amuletten samlet igen! Men vi står stadig over for den hårdeste prøve.\n\nFor at kalde Herre Valtalak frem skal kulbækkenet stilles ind, og der er nogle flere ting, der skal samles og bringes tilbage til mig her."},
  [8992] = {n="Det Højre Stykke af Herre Valtalaks Amulet", l="Brug Kaldende Kulbækken til at fremkalde Kormøks ånd og dræb ham. Vend tilbage til Bodlej inde i Sortklippebjerget med den genforenede Herre Valtalaks Amulet og Kaldende Kulbækken.", d="Nu har vi det, vi har brug for, så det er tid til at tale om, hvem du skal tilkalde næste gang.\n\nKormøk var ok for en oger, lige indtil han vendte sig mod nekromanti. Derefter blev tingene uhyggelige for stort set alle i kompagniet. Det var så ingen overraskelse, da han tog sit stykke af amuletten og vendte tilbage til sit nye hjem, Skolomance.\n\nMen selv der, eller måske især der, var han ikke sikker for de spektrale snigmordere. De dræbte ham lige foran sin mester, Ras Frostviske.", p="Jeg roser dig, <Name>, hvis du er vendt tilbage med den færdige amulet. Hvis ikke, så tag dig af det, for der er ingen tid at spilde, det forsikrer jeg dig!", c="Godt arbejde, <Name>! Kormøk var ikke så slem for en oger, i hvert fald ikke mens han stadig var i live, så jeg håber, han får den hvile, han fortjener. Og nu har vi den færdige amulet! Men vi står stadig over for den hårdeste prøve.\n\nFor at kalde Herre Valtalak frem skal kulbækkenet stilles ind, og der er nogle flere ting, der skal samles og bringes tilbage til mig her."},
  [8994] = {n="Sidste Forberedelser", l="Saml 40 Sortklippe-armbeskyttere og skaf en Kolbe med Overlegen Kraft. Lever dem til Bodlej inde i Sortklippebjerget.", d="Vi er næsten der, <Class>. Alt, der er tilbage, er at hente nogle flere komponenter, så jeg kan indstille kulbækken og gøre den i stand til at kalde Herre Valtalak frem.\n\nTil at begynde med må jeg bede dig drage ud til Sortklippe-spiret og slagte de orker, der findes der. De bærer armbeskyttere, som indeholder spormetaller, jeg får brug for, så jeg skal bruge mere end et par stykker for at udvinde den rette mængde. Og for at fuldføre indgydelsesprocessen skal du bringe mig en Kolbe med Overlegen Kraft.\n\nHeld og lykke, <Name>!", p="Vi er kommet langt, <Name>, og jeg ville bare sige, at uanset hvad der sker, så tak! Du har sat dig selv i dødsfare for at forsøge at hjælpe de overlevende medlemmer af vores lejesoldat-kompagni, Den Tilslørede Klinge, og så vidt jeg er bekymret, er du en af os nu.", c="Så er det vel det. Jeg udvinder metallet fra armbeskytterne og indgyder kulbækken med disse sidste komponenter. Så er den klar til, at du kan tilkalde Herre Valtalak og til sidst returnere hans ånds-amulet til ham.\n\nDu har tilbagelagt en hel del vej, <Name>, så lad ikke modet svigte nu, hvor enden er i sigte!"},
  [8995] = {n="Min Skyld, Herre Valtalak", l="Brug den Kaldende Kulbækken til at tilkalde Herre Valtalak. Slå ham ned, og brug Herre Valtalaks amulet på liget. Returner derefter Herre Valtalaks amulet til Herre Valtalaks Ånd.", d="Alt er nu klar, <Name>.\n\nDa Herre Valtalak levede, residerede han i det, der nu er Udyrets kammer. Gå derhen og brug den Kaldende Kulbækken til at tilkalde Herre Valtalak. Den vil genskabe ham, så han må dræbes igen. Jeg ville tage mig af Udyret først og sørge for at tage nok venner med til at overleve den øverste del af Sortklippe-spiret.\n\nNår du har slået Valtalak ned, skal du bruge amuletten på hans lig. Når hans ånd igen er forenet, vil han sikkert også gerne have sin amulet tilbage.\n\nHeld og lykke!", p="<Class>, du tør forstyrre min hvile!", c="Hvor heldigt for dig, at jeg ved, at du ikke var med i den oprindelige gruppe, der stjal dette fra mig.\n\nJeg tager nu tilbage, hvad der er mit, dødelige! Giv mig amuletten!"},
  [8996] = {n="Retur til Bodlej", l="Vend tilbage til Bodlej inde i Sortklippebjerget og giv ham Den Kaldende Kulbækken.", d="Jeg vil ignorere din uforskammethed denne gang, <Class>, for du har gjort en ædel gerning i dag; ved at returnere den resterende del af min stjålne ånd til mig. Trods din åbenlyst svage natur, <Race>, har du vist mod, der hvor dem, der stjal fra mig, ikke gjorde, og sandsynligvis aldrig ville kunne!\n\nVend tilbage til dem, før jeg skifter mening og slagter dig, hvor du står. Gå tilbage og fortæl dem, at de er i sikkerhed ... for nu.", p="<Name>, du er tilbage og stadig i live! Nå, i det mindste er der én af os, der er det.\n\nDu bliver nødt til at fortælle mig alt om det!", c="Sagde han virkelig alt det? Vildt, jeg kan ikke tro, at han vil kalde de spektrale snigmordere og lurere tilbage, selv om han antydede, at mine levende kammerater måske får mere ondt i fremtiden.\n\nDet er en stor dag, <Name>! Du har udført det, som få nogensinde kunne, og fritaget os, i det mindste delvist, for nogle af vores tidligere synder.\n\nTak! Som tegn på min taknemmelighed vil jeg gerne give dig denne. Du kan bruge den til at fremkalde ånder på de samme hjemsøgte steder, som du allerede kender, og et par andre også."},
  [8997] = {n="Tilbage til Begyndelsen", l="Tal med Glædiana på Højsædet i Jernsmede.", d="Jeg går ud fra, at dette så er farvel, min ven. Men jeg vil altid være her, hvis du vil komme tilbage og tale med mig nu og da. Sikkert mens du dovner rundt og venter på, at dine kammerater slutter sig til dig på en razzia mod Sortklippe-spiret.\n\nGå, før jeg begynder at græde. Gå tilbage til Glædiana i Jernsmede og fortæl hende, hvad der er sket.", c="Jeg er meget glad for at se dig vende sikkert tilbage til mig, <Name>. Du ser godt ud, hvis ikke en smule slidt.\n\nKom, fortæl mig alt, hvad der er foregået."},
  [8998] = {n="Tilbage til Begyndelsen", l="Tal med Mokkevar i Grommash-borgen i Orgrimgrads Visdommens Dal.", d="Jeg går ud fra, at dette så er farvel, min ven. Men jeg vil altid være her, hvis du vil komme tilbage og tale med mig nu og da. Sikkert mens du dovner rundt og venter på, at dine kammerater slutter sig til dig på en razzia mod Sortklippe-spiret.\n\nGå, før jeg begynder at græde. Gå tilbage til Mokkevar i Orgrimgrad og fortæl ham, hvad der er sket.", c="Jeg er glad for at se, at du har overlevet, <Name>. Du ser godt ud, hvis ikke en smule mere garvet.\n\nKom, fortæl mig alt, hvad der er foregået."},
  [8999] = {n="Det Bedste Gemmes Til Sidst", l="Giv Glædiana din Vildthjerte-hætte og Vildthjerte-vest.", d="Det er en fantastisk historie, <Name>! Du har min tak og den inderlige taknemmelighed fra alle, der var involveret. Nu kan jeg måske sove om natten med begge øjne lukket.\n\nAngående din belønning, tror jeg, at jeg har et par ting, du virkelig vil nyde.", p="Som aftalt, er du klar til at aflevere dine Vildthjerte-dele i bytte for din nye Vildhjerte-hætte og -vest?", c="Jeg kommer til at savne dig, <Name>. Jeg står i gæld til dig; jeg tror aldrig, jeg kan betale den tilbage.\n\nJeg håber, at du nyder dit nye hoved- og brystpanser, og at det beskytter dig i lang tid fremover."},
  [9000] = {n="Det Bedste Gemmes Til Sidst", l="Giv Glædiana din Udyrsjæger-hue og Udyrsjæger-tunika.", d="Det er en fantastisk historie, <Name>! Du har min tak og den inderlige taknemmelighed fra alle, der var involveret. Nu kan jeg måske sove om natten med begge øjne lukket.\n\nAngående din belønning, tror jeg, at jeg har et par ting, du virkelig vil nyde.", p="Som aftalt, er du klar til at aflevere dine Udyrsjæger-dele i bytte for din nye Dyrebehersker-hue og -tunika?", c="Jeg kommer til at savne dig, <Name>. Jeg står i gæld til dig; jeg tror aldrig, jeg kan betale den tilbage.\n\nJeg håber, at du nyder dit nye hoved- og brystpanser, og at det beskytter dig i lang tid fremover."},
