  [9271] = {n="Atiesh, Vogterens Storstav", l="Anakronos ved Tidens Huler i Tanaris vil have, at du tager Atiesh, Vogterens Storstav til Stratholm og bruger den på Indviet Jord. Besejr væsenet, der bliver uddrevet fra staven, og vend tilbage til ham.", d="Denne sidste opgave bliver den sværeste af dem alle, <Name>. Du har stået over for og besejret både en Gammel Gud og Liskekongens general, men nu må du møde Sargerås' hånd.\n\nTag staven med til Stratholm. Det er der, du vil finde et stykke indviet jord: jorden, hvor Herrelandenes største riddere blev myrdet. Placer den besmittede stav på den hellige jord og gør dig klar til, at et væsen af enorm kraft bryder ud indefra... Besejr det dæmoniske væsen, der kontrollerer staven, og vend tilbage til mig.", p="Jeg må ikke blande mig, <Race>.", c="Betydningen af denne bedrift må ikke undervurderes, <Name>. Du har gjort, hvad de fleste ville have troet var umuligt. Desværre var det skæbnebestemt. Staven har truffet sit valg..."},
  [9272] = {n="Klæd dig på til rollen", c="Yarrr... hvis du er ivrig efter at nyde selskabet af os erfarne søulke, så må du hellere holde op med at klæde dig som en slyngel! Her, tag noget ordentligt på, før jeg kølhaler dit skind.\n\nDisse passer dig bedre, end de nogensinde passede den gamle hund, Rødøjede Ben. Mistede ham i et helvedes uvejr på havet.\n\nBær dem med stolthed, makker!"},
  [9292] = {n="Revnet Nekrotisk Krystal", l="Bring den Revnede Nekrotiske Krystal til Løjtnant Orrin uden for portene til Stormvind.", d="På liget af den faldne vederstyggelse finder du en revnet krystal, der langsomt pulserer med nekrotisk energi.", p="Er der noget, du har brug for?", c="Hm, tog du denne fra liget af en af de invaderende vederstyggeligheder?\n\nVi har modtaget besked om de nekropolis-basislejre, som Svøben fremkalder. Jeg formoder, at de ville skabe en inde i Stormvind. Det er godt, at de ikke lykkedes."},
  [9295] = {n="Brev fra Fronten", l="Tag det Revne Brev til Protokolvogteren ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Du fandt dette brev på en af de mange Svøbe-håndlangere, du har slagtet. Ud fra dets udseende og lugt har det været hos de udøde i noget tid. Måske ville nogen ved Lysets Håb-kapellet være interesserede i at undersøge det nærmere...", p="Ja? Hvad har du dér?", c="Hvor tragisk. Disse ord, tydeligvis skrevet til en, soldaten elskede, nåede aldrig frem til deres modtager. Begivenhederne, der beskrives, skete for år siden; jeg er ikke sikker på, om den tiltænkte modtager stadig lever.\n\nDer er dog stadig håb. Med navnene og oplysningerne, han giver, kan jeg måske finde familien! Det vil kræve en del research, men bibliotekaren i Stormvind skylder mig en tjeneste...\n\nTak, fordi du bragte dette til mig. Med din hjælp kan vi måske endelig give nogen sindsro."},
  [9299] = {n="Seddel fra Fronten", l="Tag den Medtagne Seddel til Protokolvogteren ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Du fandt dette brev på en af de mange Svøbe-håndlangere, du har slagtet. Ud fra dets udseende og lugt har det været hos de udøde i noget tid. Måske ville nogen ved Lysets Håb-kapellet være interesserede i at undersøge det nærmere...", p="Ja? Hvad har du dér?", c="Hvor tragisk. Disse ord, tydeligvis skrevet til en, soldaten elskede, nåede aldrig frem til deres modtager. Begivenhederne, der beskrives, skete for år siden; jeg er ikke sikker på, om den tiltænkte modtager stadig lever.\n\nDer er dog stadig håb. Med navnene og oplysningerne, han giver, kan jeg måske finde familien! Det vil kræve en del research, men bibliotekaren i Stormvind skylder mig en tjeneste...\n\nTak, fordi du bragte dette til mig. Med din hjælp kan vi måske endelig give nogen sindsro."},
