  [8237] = {n="GENBRUG"},
  [8267] = {n="Offerbånd", l="Bring Offerbåndene til Kaptajn Knuskranie, så Udrykkerne kan belønne dig for at handle på vores vegne.", d="Jeg forstår, at det nogle gange kan være svært at gå sejrrig fra Krigssang-Gulch. Ikke desto mindre er din indsats på vores vegne - selv når sejren udebliver - vigtig.\n\nHvis du gennemfører en af prøverne inde i Krigssang-Gulch uden at opnå sejr, får du stadig et Offerbånd. Bring det til mig, så Udrykkerne kan belønne dig for at handle på vores vegne ... selv om du ikke kunne vinde denne gang.", c="Nå, du flygtede ikke i mødet med nederlaget. Du stod din mand, <Name>, og når det kommer til stykket, er det det, der gør en sand helt. Der er ingen tvivl om, at du vinder næste gang ... men ikke desto mindre takker vi dig for din indsats."},
  [8269] = {n="Offerbånd", l="Bring Offerbåndene til Vagt Fjernsang, så Vagterne kan belønne dig for at handle på vores vegne.", d="Jeg forstår, at det nogle gange kan være svært at gå sejrrig fra Krigssang-Gulch. Ikke desto mindre er din indsats på vores vegne - selv når sejren udebliver - vigtig.\n\nHvis du gennemfører en af prøverne inde i Krigssang-Gulch uden at opnå sejr, får du stadig et Offerbånd. Bring det til mig, så Vagterne kan belønne dig for at handle på vores vegne ... selv om du ikke kunne vinde denne gang.", c="Nå, du flygtede ikke i mødet med nederlaget. Du stod din mand, <Name>, og når det kommer til stykket, er det det, der gør en sand helt. Der er ingen tvivl om, at du vinder næste gang ... men ikke desto mindre takker vi dig for din indsats."},
  [8289] = {n="Fortjenstens Talismaner"},
  [8292] = {n="Æresmærker", p="Du fik kredit for din sidste opgave. Bring mig flere Æresmærker, og bliv belønnet.", c="Tak, <Name>. Dine bedrifter i Krigssang-Gulch runger over hele Askedalen-skoven."},
  [8293] = {n="Æresmærker", p="Du fik kredit for din sidste opgave. Bring mig flere Æresmærker, og bliv belønnet.", c="Nattealferne og deres allierede må ryste ved selv hviskingen af dit navn! For Horden!\n\nDu har bevist din værdi for vores indsats i Krigssang-Gulch. Bliv ved med at rase løs mod Sølvvinge-vagterne! Bring mig flere Æresmærker!"},
  [8296] = {n="Æresmærke"},
  [8298] = {n="Flere Arathi-bækkenets Æresmærker", p="<Name>, Arator-ligaen har en fast opgave til dig: at vende tilbage til Arathi-bækkenet, skaffe flere Æresmærker og bringe dem til mig.", c="Meget godt. Jeg får dem straks sendt til vores kvartermestre, og en anbefaling for dine bedrifter bliver sendt til mine overordnede.\n\nEn gang til, tak <Name>. Dine bidrag til vores kamp bliver lagt mærke til, både af fodsoldaten og feltmarskallen."},
  [8300] = {n="Flere Arathi-bækkenets Æresmærker", p="<Name>, Skænderne har en fast opgave til dig: at vende tilbage til Arathi-bækkenet, skaffe flere æresmærker og bringe dem til mig.", c="Meget godt. Jeg får dem straks sendt til vores kvartermestre, og en anbefaling for dine bedrifter bliver sendt til mine overordnede.\n\nEn gang til, tak <Name>. Dine bidrag til vores kamp bliver lagt mærke til, både af hugger og overhøvdingen."},
  [8514] = {n="Alliancen Har Brug for Mere Middel-læder!", l="Bring 10 middel-læder til Menig Portner ved flyvepladsen i Dun Frostbakke.", d="Ja, sir, det ser ud til, at vi har samlet $2063w stykker middel-læder til dato. Jeg ved, det er meget at bede om, men hvis du stadig er villig, kunne jeg bruge din hjælp til at gøre et hul i resten af min kvote.", p="Ja, sir, det ser ud til, at vi har samlet mange stykker middel-læder, men vi har brug for mere. Jeg kan forsikre dig om, at det hele bliver brugt godt; ikke ét stykke bliver spildt. Jeg ved, det er meget at bede om, men hvis du stadig er villig, kunne jeg bruge din hjælp til at gøre et hul i resten af min kvote.", c="Gud bevare os, det er da en masse middel-læder, du har bragt hertil, sir! Jeg sørger for, at alt det bliver brugt ordentligt, ja det gør jeg. Med din hjælp får vi fyldt vores kvote for middel-læder på et øjeblik!\n\nTak, <Name>!"},
  [8516] = {n="Alliancen Har Brug for Mere Tykt Læder!", l="Bring 10 tykt læder til Marta Finespindle på flyvepladsen i Dun Frostbakke.", d="Jo, stakken er stadig ikke høj nok. <Name>, vi har stadig ikke nået vores mål på $2071w tykt læder. Tænk bare på alle de ting vi kan lave af al det læder! Alle slags rustning og våben. Ting til indvendigt i damp-stridsvognene og riffelsigtene! Ingeniør-briller, og jeg vil vædde på at hvis vi ender med at samle for meget, så kunne vi give resten til Horden til deres zeppeliner!\n\nSkal du bringe mig noget mere tykt læder?", p="Jo, stakken er stadig ikke høj nok. <Name>, vi har stadig ikke nået vores mål for tykt læder. Tænk bare på alle de ting vi kan lave af al det læder! Alle slags rustning og våben. Ting til indvendigt i damp-stridsvognene og riffelsigtene! Og ingeniør-briller, dem er der altid sjov i!\n\nSkal du bringe mig noget mere tykt læder?", c="Du gjorde det igen! Det er simpelthen fantastisk, hvordan du tager derud, samler alt det her og så bringer det tilbage hertil og afleverer det. Jeg siger dig, når de finder ud af, hvor meget du har hjulpet til herude, kan du ikke gå ned ad gaden uden at folk beder dig om din autograf!\n\nTak igen for din meget generøse donation af tykt læder, <Name>."},
  [8521] = {n="Alliancen Har Brug for Flere Silkebandager!", l="Bring 20 silkebandager til Sygeplejerske Stenmark på flyvepladsen i Dun Frostbakke.", d="Det er meget venligt af dig at tilbyde at hjælpe mig igen <Class>. Det ser ud til, at vi har samlet $2082w silkebandager, så vi får brug for flere.", p="Det er meget venligt af dig at tilbyde at hjælpe mig igen, <Class>. Det ser ud til, at vi har samlet et pænt antal af de silkebandager vi er blevet pålagt, men vi har stadig brug for flere. <Name>, kunne du mon finde på at samle endnu et bundt og bringe dem tilbage til mig her? Alliancen og jeg vil være yderst taknemmelige.", c="Du er sådan en uegennyttig person. Tusind tak for dit bidrag til krigsindsatsen. Det er folk som dig, der kommer til at gøre forskellen mellem succes og fiasko ved Ahn'Kiraj. Jeg håber bare, at det hele bliver nok.\n\nTak igen, <Name>."},
  [8565] = {n="Tidligere Sejre i Arathi", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Arathi-bækkenet."},
  [8566] = {n="Tidligere Sejre i Arathi", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Arathi-bækkenet."},
  [8567] = {n="Tidligere Sejre i Krigssang-Gulch", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Krigssang-Gulch."},
  [8568] = {n="Tidligere Sejre i Krigssang-Gulch", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Krigssang-Gulch."},
  [8569] = {n="Tidligere Indsatser i Krigssang-Gulch", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Krigssang-Gulch."},
  [8570] = {n="Tidligere Indsatser i Krigssang-Gulch", c="Ah, ja! Selvfølgelig glemmer vi ikke dine tidligere bedrifter i Krigssang-Gulch."},
