  [9249] = {n="40 Billetter - Skema: Damp-Tonk-kontroller"},
  [9273] = {n="Indløs iKoke-præmiegavekort"},
  [9296] = {n="genbrug", l="Lever den Svage Nekrotiske Sten til NOGEN.", d="Denne sten udstråler en mørk energi. Du bør levere den til NOGEN."},
  [9297] = {n="genbrug", l="Lever den Svage Nekrotiske Sten til NOGEN.", d="Denne sten udstråler en mørk energi. Du bør levere den til NOGEN."},
  [9298] = {n="genbrug", l="Lever den Svage Nekrotiske Sten til NOGEN.", d="Denne sten udstråler en mørk energi. Du bør levere den til NOGEN."},
  [9353] = {n="Indløs iKoke-gavekasse-gavekort"},
  [79360] = {n="Elementarernes Hjælp", l="Besejr Charlga Rasorflanke i Tornekrattet og hent oplysninger om quilboarernes planer.", d="Eftersom du har mestret elementerne, står du i gæld til dem, og dermed til Azerot selv. Vi beder dem om hjælp, vi kræver ikke deres kraft. Nu er det på tide, at du betaler tilbage for de nåder, du har fået. Og jeg tror, jeg ved hvordan.\n\nPindsvinesvinene vrider elementerne til deres egne formål og ser ud til at udvide deres indflydelse inden for disse grænser. Gå ind i deres kraul og sæt en stopper for alle deres ræverier. Disse lande må beskyttes."},
  [86613] = {n="Mineredskaber", l="Returnér 6 Mineredskaber til Magmar Ondhugger.", d="Minernes redskaber, som blev efterladt, da dværgene flygtede fra troggerne, ser for det meste uskadte ud. At give dem tilbage til minearbejderne vil helt sikkert gøre deres arbejde lettere.", p="Vi skal bare, øh, justere vores mine, så er alt i orden igen!", c="Vores redskaber!\n\nDa troggerne overvældede lejren, måtte vi efterlade det meste af vores værktøj. Det bliver til stor hjælp, når vi har fået styr på invasionen, og vi igen kan arbejde!"},
  [86757] = {n="Standsning af Orkernes Fremrykning", l="Bring Shandrine 6 Takkede Ork-sværd og 4 Krumme Ork-dolke.", d="Orkerne har indtaget den østlige skov, og deres spejdere og gruntere gemmer sig nu i hver eneste lund! Det er ikke trygt for vores folk at færdes i Askedalen.\n\nVi må drive orkerne tilbage og sikre skoven. Vi har allerede fået fat i nogle af deres gruntere og spejdere ved at liste forsigtigt langs kanten af deres lejr.\n\nKæmp mod orkerne og bring mig de takkede sværd og krumme dolke, de bruger. Jeg sørger for, at deres våben bliver hentet og genbrugt, så intet går til spilde."},
  [87288] = {n="Saberens Bløde Skind", l="Bring 6 Bløde Skind af Natsabre til Aldria.", d="Hej, rejsende! Jeg håber, du nyder dit besøg i vores landsby. Jeg holder af Dolanår, for den er lille, landlig, og alle er venlige.\n\nJeg er den lokale købmand, og jeg fører alle slags værktøj og småting, som kan være nyttige for dig på dine rejser. Faktisk, hvis du er interesseret i handel, har jeg brug for nogle natsabre-skind. Selvom de majestætiske skabninger er smukke, er de lokale eksemplarer ret aggressive, så du skal ikke have dårlig samvittighed over at forsvare dig.", p="Dejligt at se dig igen! Er du her for at handle?", c="Åh, de er vidunderlige. Det er en skam at ty til vold mod så majestætiske dyr, men det er vigtigt at holde vejene sikre, og disse skind laver smukke tæpper og tørklæder.\n\nHer, lad mig give dig noget som minde. Det er både blødt og solidt."},
  [87491] = {n="Frihedens Gnist", l="Eskortér den fangne ildelementar fra Dun Mødr til friheden.", d="Sss! De usle Mørkjernerne kaldte mig frem og holdt mig i et bur ved siden af deres elendige ildsted!\n\nIlden skal rase frit, fri! Lad mig ud! Jeg må flygte! Jeg må BRÆNDE!\n\nIngen Mørkjern er i sikkerhed! Brænd dem til aske! Brænd deres sorte krudt! Brænd deres fæstning, lunter og dumhed!\n\nLad mig gå, så BRÆNDER JEG DEM ALLE!", c="Sikke et fyrværkeri! Sådan noget har aldrig været set før!\n\nGodt at ildelementaren endelig løb tør for damp, om man så må sige. Det kunne have været farligt, hvis den havde valgt at gå løs på resten af os i stedet for de Mørkjernerne!"},
  [88757] = {n="De Savnedes Personlige Sager", l="Bring Esselins Halskæde, Esselins Besværgelsesbog og Esselins Vandskind.", d="Da jeg flygtede fra de Mørkjernerne, tabte jeg en masse af mine ting!\n\nDet ser ud til, at jeg har tabt... mit grønne læder-vandskind, min besværgelsesbog, mit halsbånd og... ja, jeg har virkelig brug for de ting!\n\nHvis du kan finde dem, mens jeg pakker sammen og får vejret, vil det være en stor hjælp.", p="Jeg binder lige mine støvler! Har du været i stand til at komme forbi de Mørkjernerne og finde mine ting?", c="Du har min bog! Og mit vandskind! Og halskæden! Åh, i dag har lykken fundet mig... tusind tak.\n\nJeg bør sikre mig, at alt er i god behold!"},
  [88758] = {n="De Savnedes Følelser", l="Bring Esselins notits til Corma Vildmand.", d="Jeg skal bare pakke færdig, så kan jeg komme herfra!\n\nHvis du vil gøre mig en tjeneste mere, så tag denne notits og bring den til Corma. Den vil lade hende vide, at jeg lever og er på vej!", p="Har du fundet noget spor af hende?", c="Lever hun? Hun lever!\n\nLad mig se notitsen... „Kære Corma...“ mm... åh, velsignede dag! Tak Lyset!\n\nJeg kan ikke takke dig nok for at have bragt os sammen. Jeg kan ikke vente med, at hun kommer tilbage hertil!\n\nDu har gjort os begge en fantastisk tjeneste."},
  [91738] = {n="Æbledelikatessen", c="Narrer mine øjne mig? Jeg har ikke set en eneste dråbe Torden Æblejack i flere måneder!\nDet burde få soldaterne til at smile. Tak skal du have, YOUR_CLASS7!"},
  [91740] = {n="Croak'os Hoved", l="Lever Croak'os Hoved til Merell Ross ved Ridgepoint-tårnet.", d="Murlocen har uden tvivl terroriseret vejene i området i et stykke tid. Du formoder, at de nærliggende vagtposter gerne vil vide besked om hans død.", p="Ja?", c="Vi mistede to vagtfolk i sidste uge til murlocerne, YOUR_CLASS7. Med deres døde høvding håber jeg, vi kan begynde at drive dem ud af Elvendal."},
  [91746] = {n="Elmpotes Hoved", l="Lever Elmpotes Hoved til Helene Pelsskinner nær Guldshire.", d="Trofæet tjener som en imponerende påmindelse om din sejr over Elmpote. En lokal jæger eller garver vil måske gerne høre historien.", p="Ja?", c="Så du besejrede Elmpote? Meget imponerende, Ingmmar!\n\nLad mig give dig noget til gengæld for dit trofæ - jeg kender nogle samlere, der vil betale rigeligt for at have det på deres hylde, når jeg har fået det gjort i stand."},
  [91859] = {n="Det Mærkelige Par", l="Tal med Dødevagt Baldren om de mystiske rejsende fra Jordringen, som for nylig passerede gennem Sepulchrum.", d="For at sige det rent ud, er de \"diplomater\" ikke almindelige diplomater. Den ene var en tauren. Almindelig nok for Jordringen, men den anden - og du vil næppe tro det - var en alf. *Høj*alf. De var tildækkede, men jeg har set quel'dorai før, og jeg vil vædde på, at det var dem, jeg så.\n\nHvorfor fulgte en alf tauren gennem Hordens område? Ja, din gisning er lige så god som min. Det er alt, hvad jeg ved, så jeg foreslår, at du taler med Dødevagt Baldren nær byens indgang.", c="Jeg bryder mig ikke om jer paladiner, men jeg må sige, at jeres timing er upåklagelig. Det er bedre at være heldig end dygtig, synes jeg?"},
  [91860] = {n="Den Dystre Dola", l="Undersøg Fenris-øen mod øst og find ud af skæbnen for gruppen af rejsende fra Jordringen.", d="Under patruljen i går aften så jeg en flok hyænemænd smide et meget stort lig på et bål på kysten af Fenris-øen. Jeg så ingen alf eller andre mindre lig, men jeg vil sige, at det ikke bebuder godt for dem.\n\nHvis du er modig eller dum, kan du springe ud til Fenris-øen for at finde ud af mere, men hvis du spørger mig, er det meget arbejde at finde en hovmodig alf, som sandsynligvis allerede er død.\n\nJeg ved, at paladiner elsker at sværge eder og tage på tabte sager, men denne er det ikke værd. Stol på mig.", c="<Liget foran dig var helt sikkert en tauren, og du kan se, at det blev gnavet hårdt, før det blev smidt på bålet. Du ser dog ingen spor af den alfekvinde, der blev beskrevet for dig. Måske lever hun stadig et sted dybere inde i den nærliggende fæstning?\n\nDet bliver farligt, men der er kun én måde at vide det med sikkerhed på.>"},
  [91862] = {n="Lumina Vindsang", l="Hent Fenris-øens nøgle fra Rådhud-hyænemændene og brug den til at befri Lumina Vindsang.", d="Quel'dorai? Nej, jeg er ikke \"quel'dorai\". Jeg er Lumina Vindsang, og jeg er shen'dorai. En af de Himmelbårne Vindformere.\n\nJeg kom til disse lande som gæst af Jordringen. Min ledsager Banon og jeg rejste gennem Sølvfyr for at nå Arathi-højlandet, hvor vi skulle undersøge de elementære konvergenser dér. Det er klart, at vi ikke nåede frem.\n\nVi har dog ikke tid til det nu. Dræb hyænemændene i nærheden. Hent nøglen til dette bur og befri mig. Jeg fortæller dig resten, når vi er i sikkerhed.", p="Hyænemænd er det næstværste væsen, jeg er stødt på på Azerot.", c="Tak, YOUR_CLASS7. Desværre er vi stadig ikke ude af fare."},
  [92109] = {n="Min Første Alkymisæt", l="Saml 5 Tomme Hætteglas, 5 Sølvløv og 5 Fredsblomst til den unge, nybegyndende alkymist i laden i Månebæk i Vestfald.", d="Øh... 'Ello, <herre/frue>. Man skal ikke tale med fremmede, men... Hov, hvad er de skinnende små flasker, der stikker op af din rygsæk? Er du alkymist? Hvor er det fedt!\n\nNår jeg bliver voksen, vil jeg være alkymist. Far lader mig ikke lege med nogen af hans urter; for farligt, siger han.\n\nNå, jeg vil lære det nu. Kunne du måske skaffe nogle materialer til mig, tak?", p="'Ello igen! Har du medbragt noget alkymi?", c="Åh, min Gud! Se lige på dem! Har du selv samlet urterne?\n\nWow, tak skal du have, nu skal jeg se, hvad jeg kan lave af dem! Vil du være med og se på?"},
  [92454] = {n="Velkommen!", l="Bring Thendal-lundens Gavekort til Dali Vindbrise.", d="Velkommen til Verden af Krigskunst!\n\nSom tak for dit køb af Verden af Krigskunst Samlerudgaven skal du give dette gavekort til Dali Vindbrise i Thendal-lunden. Så får du en gave: en lille følgesvend, som vil ledsage dig på din rejse mod eventyr og ære.\n\nTak igen, og nyd dit ophold i Verden af Krigskunst!"},
  [92479] = {n="Det Krøllede Brev", l="Læs det Krøllede Brev og tal med Tordrin Stemblade i Nordshire-klosteret.", d="Jeg blev bedt om at bringe dette til din opmærksomhed, så snart du vendte tilbage fra kobold-lejrene, YOUR_NAME. Det ser ud til at være et brev forseglet med Tordrin Stemblades segl, vores lokale jægertræner. Tag dig et øjeblik til at læse det, før du går i gang med andre sager her i klosteret.", p="Ah, ye got me letter, Busch... good.\n\nTime was when ye'd not catch a YOUR_RACE7 dead wit' a bow in their hand--no more, I guess. It's good for Stormvind, but bad for the kobolds and man eatin' beasts in the area.", c="Get yerself squared away, learn the lay o' the land, and come back to me whenever you need training. I'll be here night or day.\n\nThis land is grown' more dangerous, and as ye meet other folk, I think ye'll find they all have problems they could use some help with--help a skilled YOUR_CLASS7 can give 'em. Good luck."},
  [92519] = {n="Forsyning af Troppen", l="Hent kassen med Pakkede Tonika i Jorells laboratorium på Go'shek-farmen og vend tilbage til Doktor Gregor Victor i Hammerfald.", d="Apotekeren Jorell skulle have leveret os en kasse med modgifte og eliksirer for et par dage siden, og vi har stadig ikke fået noget i hånden. Den tosse har sikkert forgiftet sig selv igen, mens han brygger i det dårligt ventilerede skur, han kalder et laboratorium.\n\nHvis du vil fortsætte med at hjælpe vores tropp, ville du være en langt mere pålidelig person til opgaven.\n\nFølg vejen til Go'shek-farmen, mod syd og lidt mod vest herfra. Du finder den sandsynligvis klar til forsendelse, og Jorell er enten forsvundet eller ligeglad med sine pligter."},
  [92707] = {n="Kæmpen i Hulen", l="Bring Goliaths Håndledsskinner til Drum Ondt i Hammerfald.", d="Revet af et enormt goliat-lig er disse håndledsskinner mægtige. Hele din arm, helt op til skulderen, ville kunne være i én af dem uden at røre siderne.\n\nDu bør bringe dem til Hammerfald som en advarsel. Drum Ondt bør vide, hvad han har i vente."},
  [92750] = {n="Fjernsprængning", l="Tal med nogen i Stormvinds Efterretning om at skaffe en fjernudløser.", d="Jeg går ud fra, at du vil have en \"kontrolleret\" eksplosion? Ikke fuld så sjov, men et godt valg, hvis du vil beholde alle dine lemmer.\nJeg er bange for, at jeg ikke har nogen fjernudløser - hvorfor ikke gå og spørge de lumske fyre nede i Stormvinds Efterretning? De burde kunne finde noget til os.", c="Hmm... Du leder efter noget bestemt, ikke?"},
  [92755] = {n="Mystisk Mystik", l="Bevar dit ry hos Gellekis-klanen og bring 3 Større Mystiske Essenser til Halea i Gellekis-landsbyen i Forødelse.", d="For hver dag der går, kommer vores spejdere tilbage med færre våben fra de faldne eventyrere.\n\nSelvom vi ikke kan bruge dem direkte, får vi i det mindste rester ud af dem. De mest magiske stykker ender hos mig, for jeg kan skille dem ad og bruge de mystiske rester til at fortrylle vores våben, især det som vores vindjagere bærer.\n\nJeg har brug for Større Mystiske Essenser, hvis jeg skal udstyre vores næste plyndringstrop med ordentligt udstyr."},
  [92814] = {n="Jeg Har Brug for en Skrædder", l="Bevar dit ry hos Gellekis-klanen og bring en Hvid Bandit-maske til Molkar i Gellekis-landsbyen i Forødelse.", d="Min ledsager, Halea, har til opgave at sikre, at vores våben er fyldt med den rette magiske energi.\n\nFortryllelseskunsten er mig fremmed, men som kentaur, hvis opgave det er at forsyne vores landsby, ved jeg, at Halea ofte ikke kan nå sine pligter, og det er ikke hendes skyld.\n\nJeg vil gerne forære hende simpelt tøj, hun kan øve sit håndværk på. Jeg ser, at eventyrerne vandrer gennem sandstormene i simple ansigtsmasker. Kunne du skaffe mig nogle af dem?"},
  [92817] = {n="Læderarbejdets Teknik", l="Bevar dit ry hos Gellekis-klanen og bring et Barbarisk Seletøj til Talrz i Gellekis-landsbyen i Forødelse.", d="At overbevise mine kentaur-frænder i Gellekis-klanen om at bære rustning grænser til det umulige, trods de mange tab, vi har lidt fra klinger og pile i brystet.\n\nJeg er blevet udpeget til at designe en vest, der giver rimelig beskyttelse uden den påståede 'kløe', de klager så meget over. Forråd er knappe, så jeg tør ikke spilde dyrebart læder på hvad som helst.\n\nFremmede, vil du bringe mig et seletøj, der er værdigt en brutal kentaur? Jeg vil gerne lære din teknik."},
  [92819] = {n="Ødelæggelsen i Dødsminerne", l="Brug detonatoren.", d="Vi er næsten færdige. Brug detonatoren og gør det færdigt.", c="Jeg ved ikke, hvad jeg skal sige, Samelyn. At tænke sig, at Stormvind ville sætte sine militære ambitioner over sit eget folks velfærd..."},
  [92841] = {n="Knogledalen", l="Forbedr dit ry hos Magrom-klanen og find Orgrul nær Knogledalen, syd for Magrom-landsbyen.", d="Tiden er kommet, fremmede, til at du får kendskab til vores store opdagelse... men Vorrug vil ikke være den, der fortæller dig om den!\n\nGå mod syd, til den anden ende af landsbyen. Led efter en stor, stinkende kentaur ved navn Orgrul.\n\nDu vil genkende ham, når du kommer frem.\nDu vil genkende ham, når du ser ham.\nHvis han finder ud af, at du fortjener at vide det, vil du få at vide det.\n\nOg hvis ikke? Ja. Du kan glæde dig over, at Vorrug har en ny krone.", c="Så rygterne er sande. Det er en skam, at Vorrug fik dig til at løbe efter ligegyldige opgaver. Men du har i det mindste bevist din værd.\n\nKig ned i dalen. Hvad ser du? Knogler og kroppe. Vandrende udøde. Og Tvilling-goliather.\n\nDette sted var forbandet længe før vores ankomst, og jeg mistænker, at det vil forblive sådan i mange generationer. Vores klan var den første til at vove sig imod rædslerne dernede, og kun os vil det lykkes at tilegne os dens magt.\n\nEr du lige så ivrig som jeg efter at herske over hele Forødelse?"},
  [92844] = {n="Knoglebjerget", l="Forbedr dit ry hos Magrom-klanen og bring Orgrul, syd for Magrom-landsbyen i Forødelse, 426 Blidt Forbandede Knogler.", d="En nekromantisk energi har gennemsyret hele Knogledalen, af årsager, vi endnu ikke forstår.\n\nDet betyder heller ikke noget for os, hvor magien kommer fra. Nu er den vores, og dem, der ikke kæmper med klinge eller hammer, bliver oplært i denne nye kunst.\n\nHvis du tror, du starter med en svær opgave, tager du fejl. For nu skal du gå til Knogledalen og bringe mig nogle knogler. Jeg er sikker på, at du klarer det.", p="For hver knogle, du mangler til opgaven, tager jeg en af dine for at udligne forskellen.", c="<Orgrul begynder at tælle knoglerne, men farer vild, når tallene har to cifre, og til sidst mister han tråden. Han prøver igen, men midtvejs kigger han over på dig, for dit ansigt krymper, når du betragter ham.>\n\nBah. Jeg tæller dem senere. Det ser ud til at være nok. Du må hellere ikke narre mig.\n\nJeg beholder dem."},
  [92846] = {n="De Udstødte Nekromanter", l="Bevar dit ry hos Magrom-klanen og besejr De Udstødte Nekromanter i Knoglernes Dal.", d="Har du bemærket de elendige centaurer, der roder rundt her uden mål og mening? Det er Gellekisernes efterkommere.\n\nVi, Magrom, har allerede sikret et brohoved dybere inde i kløften. Da Gellekisserne opdagede vores tilstedeværelse, valgte nogle af dem at følge vores spor. Jeg ved ikke, om de vil slutte sig til os eller forsøge at vælte os, men jeg ved, at deres slægtninge har dømt dem alle til eksil.\n\nDe er ensomme ulve, der blander sig i kræfter, som ikke hører til dem. Jeg vil have dem døde."},
  [92847] = {n="Besmittede tårer", l="Bevar dit ry hos Magrom og bring Orgrulf 3 Forstenet Bark og 3 Indgydte Tårer.", d="Fremmede, har du bemærket det våben, de udstødte nekromanter holdt i hænderne? Vi sørger for, at Gellekisserne ikke når at mestre nekromantiens kunst, men deres måde at lede kraften på fangede min opmærksomhed. De bruger endda de samme krystaller, som Vorrug bad dig stjæle.\n\nJeg tror, vi kan vende det til vores fordel. Vend tilbage til dalen og skaf noget træ fra de forbandede træer, så ser vi, om Vorrug vil give os en del af sine krystaller. Jeg vil lave stave af dem."},
  [92867] = {n="Fra jord til fæstning", l="Besejr Klippenæve-, Syndikat- og Visnebark-indtrængerne i Strømgård-fæstningen, og vend derefter tilbage til Vogter Lomær.", d="Vores arv kan forvandles til ruiner, men det er ikke vores sidste fæstning. Vi har forråd, og de må forblive skjult for deres egen sikkerheds skyld.\n\nStøtten vokser til at beskytte vores øvrige statuer og hellige begravelsespladser. Pøblen, der har slået sig ned i vores gamle rige, aner intet om den hævn, der er på vej.\n\nSlå Klippenæve og Syndikatet tilbage. De må lære, at Strømgård ikke kun er en næve, en ørn og nogle sten."},
  [92872] = {n="Trofaste skridt", l="Kast Pungen med Gravstøv i Det Store Hav, og vend derefter tilbage til Beskytter Alarik i krypten under Strømgård-fæstningen.", d="Vi vogter evigt denne gravplads og viden om de ceremonielle riter, der ærer de faldne sjæle.\n\nNu hvor du er gået tre etager ned under jorden, tager du de første skridt tilbage mod solens verden, bærende på hellig visdom.\n\nHver årstid tager vi lidt støv fra denne grav og strør det ud over Azerots have. Det er en symbolsk handling for at fornye cyklusserne.\n\nTag denne lille pung. Gå til klipperne bag Strømgård-fæstningen og kast den i havet."},
  [92873] = {n="Bevis på princippet", l="Oppnå et godt forhold til Magrom-klanen, og bring derefter Orgrulf 426 Brønd Forbandede Knogler fra et vellykket ritual.", d="Vi ved allerede, at disse krystaller kan mere end blot at flå jorden op. Gellekisserne har bevist, at de kan forvrides til nekromantisk kraft. Husker du de knogler, jeg bad dig samle? Jeg satte dem sammen så godt, jeg kunne, lige bag bakken. Det var nok til to fungerende skeletter.\n\n<Orgrulf rækker dig den nylavede stav.>\n\nJeg leverer Nekro-khanens stav, og imens kan du lege med dit nye legetøj. Vend kun tilbage, når du har bevist, at du kan betjene det."},
  [92893] = {n="Ingen nåde for de svage", l="Oppnå et godt forhold til Magrom-klanen og dræb 5 Gellekis-fanger spredt rundt i Knoglernes Dal. Vend tilbage til Orgrulf, når opgaven er løst.", d="Jo længere du bevæger dig ind i Knoglernes Dal, desto oftere møder du Gellekis-vandrere, der har vovet sig ind på vores område. Jeg lod dem holde i live for at fodre knogleorme, der æder i jorden, men de synes ikke at være interesseret i levende bytte.\n\nDet er en simpel opgave. Find fangerne, og tag så deres liv. Giv dem ikke den mindste smule håb om frihed."},
  [92894] = {n="Genopvækkelse af knogler", l="Oppnå et godt forhold til Magrom-klanen og brug Forstærket Nekromanti-stav til fuldt ud at genoplive de udøde, der kæmper for at komme op af jorden i Knoglernes Dal. Vend tilbage til Orgrulf, når Magrom-hæren er vokset.", d="Jeg kan se begejstringen i dine øjne, fremmede. Begynder du allerede at forstå nekromantiens potentiale?\n\nSelvfølgelig gør du. Og netop derfor befaler jeg dig at forbedre dine evner.\n\nNår du bevæger dig dybere ind i Knoglernes Dal, vil du se resterne af mislykkede forsøg på at genoplive de døde. Uden tvivl Gellekisernes værk. De kan knap nok komme op af jorden. Det ville være morsomt, hvis det ikke var så ynkeligt.\n\nJeg har forstærket din stav. Brug den til at udvide vores hær og knuse dem, der gør modstand!"},
  [92910] = {n="Høsten af Høstmaskinerne", l="Bring den Progressive Autokognitionsforsamling til Osvin Jernskruetrækker på Saldeons Gård.", d="Den del, du formåede at redde ud af høstmaskinen, ser nogenlunde intakt ud. Nogen, der er interesseret i golem-høstmaskiner, vil måske gerne se den.", c="Hvad er det her?"},
  [93034] = {n="Knoglernes Dal", l="Forbedr dit ry hos Gellekisserne og find Nerlokk nær Knoglernes Dal, langt mod øst for Gellekis-landsbyen.", d="En af vores spejdere vendte tilbage til landsbyen, mens du var væk, med nyheder, der bekræftede mine frygt.\n\nMagrom planlægger noget, YOUR_NAME. Intet godt.\n\nKnoglernes Dal langt mod øst er et forbandet land, hvor få centaurer har vovet sig ind, og endnu færre er vendt hjem. Vores fjende har fundet noget ondt der, og vi må finde ud af, hvad det er.\n\nLed efter spejderen Nerlokk ved den sydlige indgang, men du bliver måske nødt til at bevise din værdi endnu mere over for Gellekisserne."},
  [93035] = {n="Hærgende Hærgere", l="Oppnå et godt forhold til Gellekis-klanen og besejr 6 Udøde Hærgere, og vend derefter tilbage til Nerlokk ved den sydlige indgang til Knoglernes Dal.", d="Du behøver ikke kigge langt for at se de udøde, der slæber fødderne foran os, men har du bemærket noget usædvanligt ved dem?\n\nDe går på to ben, ikke på fire! Disse skeletter er ikke engang vores faldne slægtninge. Magrom må vanhellige kroppene af dem, der døde langt tidligere, før Forødelse blev vores domæne. Jeg forstår ikke, hvordan de kunne vende ryggen til Moder Terradras og begynde at vanhellige de lig, der har hvilet her i årtusinder.\n\nBring de udøde til evig hvile, YOUR_NAME."},
  [93037] = {n="Afsløring af de udstødte", l="Oppnå et godt forhold til Gellekis-klanen og bring 1 Nekromantisk Dragt til Nerlokk ved indgangen til Knoglernes Dal.", d="Mens jeg ventede på din ankomst, kiggede jeg lidt længere frem mellem buerne og bemærkede noget, som jeg må have dig til at bekræfte.\n\nJeg kan ikke sige det højt. Ikke før mine mistanker er bekræftet.\n\nYOUR_NAME, når du søger rundt i dalen, så dræb nogle af de nekromanter, der virker svagere end de andre. Tag forsigtigt deres rituelle dragter af og bring dem til mig. Jeg må vide, om mit sind og mit syn er klare."},
  [93041] = {n="At se sandheden i øjnene", l="Oppnå et godt forhold til Gellekis-klanen og bring Forbandet Kranium og Gellekis Nekromantisk Dragt til Uthek den Vise i Gellekis-landsbyen.", d="Denne opdagelse er knusende for vores klan, men det er bedst at holde den for dem, der må vide det. Uthek er en af dem, og hun må vide, hvad der foregår her. Jeg formoder, at hun ved, hvad der skal ske nu.\n\nTag den med, så du kan vise hende den. For en sikkerheds skyld bør vi også bringe hende et bevis på selve nekromantien. Find et kranium, der ser ud til at være blevet forbandet for nylig. Jeg tror, de samler dem i gabene på et af goliat-skeletterne."},
  [93044] = {n="Renselsende skrig", l="Oppnå et godt forhold til Gellekisserne og bring Terradras' Tårer tilbage til Uthek den Vise i Gellekis-landsbyen.", d="Når du vender tilbage til Nerlokk i Knoglernes Dal, skal du ikke gå med tomme hænder.\n\nGå ind i hulen i hjertet af vores landsby og find Mularra. Bed om Terradras' Tårer på mine vegne. Vores forråd er lave, men det er vores bedste håb mod Magromernes modbydelige nekromanti!\n\nJeg forbereder et ritual. Vi skaber et våben, der vil forstyrre deres besværgelser."},
  [93045] = {n="Test din teori", l="Oppnå et godt forhold til Gellekisserne og bryd den nekromantiske forbandelse over Forbandet Kranium. Når det lykkes, skal du vende tilbage til Nerlokk nær Knoglernes Dal.", d="Jeg lagde det kranium, du bragte mig, ved siden af nogle knogler, jeg fandt, mens jeg ventede på din tilbagekomst. Jeg så straks et sygeligt lys flyde ud af kraniet og gribe fat i de gamle knogler. Nu forstår jeg, hvorfor nekromantiens kald er så svært at modstå.\n\nHusker du den krystal? Det er en draenetyst. Jeg ved ikke meget om dens kraft, men jeg tror, den kan lede Terradras' kraft. Måske kan du med den få bugt med forbandelsen.\n\nRitualpladsen finder du ved dammen lige øst for landsbyen."},
  [93058] = {n="Redning af vores egne", l="Oppnå et godt forhold til Gellekis-klanen og befri 5 Gellekis-fanger i Knoglernes Dal. Vend tilbage til Nerlokk ved indgangen, når du er færdig.", d="Der var en kort træfning mellem nogle nekromanter lige bag bakken, og jeg benyttede lejligheden til at kigge nærmere på det indre.\n\nYOUR_NAME, ikke alle vores seneste tab er desertører. Der er Gellekisser, som holdes fanget længere inde i dalen! Jeg nåede ikke at undersøge deres situation, for en mægtig Magrom-brute kom mod mig. Jeg anser mig for heldig, for han mistede hurtigt interessen.\n\nDu må vende tilbage til Knoglernes Dal og befri dem. Gellekisserne holder sammen."},
  [93062] = {n="Begravelse af knogler", l="Oppnå et godt forhold til Gellekis-klanen og bryd forbandelserne fra 8 mislykkede besværgelser i hele Knoglernes Dal.", d="Apropos din stav. Jeg kender den igen som en af dem, Uthek har lavet. Du nævnte, at den blev lavet af Terradras' Tårer, forstærket med en draenetyst-krystal, og at den kan opløse mørk magi?\n\nJeg har bemærket skeletter dybt inde i dalen, lige under den stenede jord. Jeg tror, det er mislykkede fremkaldelser af de udstødte nekromanter, måske dømt til en evig eksistens kvalt i jorden.\n\nAt begrave dem igen ville være godt for vores sag og for deres ånder."},
  [93072] = {n="Langsigtede løsninger", l="Oppnå et godt forhold til Magrom-klanen og dræb 2 Udstødte Spejdere, 6 Udstødte Plyndrere og 8 Udstødte Nekromanter, og vend derefter tilbage til Hagjak ved Magrom-fronten.", d="Herfra mod sydvest ligger en anden centaurlandsby. Den tilhører Gellekisserne. Forventer du, at jeg sender dig derhen blot for at udgyde blod, ikke sandt? Fint. Lad det være din første tanke, for ellers begynder jeg at tvivle på din loyalitet over for Magromerne!\n\nHvad venter du på? Af sted! Dræb!"},
  [93122] = {n="Undersøgelse af situationen", l="Oppnå et godt forhold til Gellekisserne og undersøg centaurernes interessesteder i Shen'dralas. Vend derefter tilbage til Nerlokk ved indgangen til Knoglernes Dal og aflæg rapport over det, du fandt.", d="Vi undervurderede alle Magromernes styrke og indflydelse i denne egn, men det kan måske komme os til gavn.\n\nNår så mange af dem er optaget af deres egne sager og nægter at tage imod udstødte fra andre klaner, hvem forsvarer så landsbyen? Og hvad med deres khan?\n\nJeg vil have dig til at gå dybt ind i dalen, længere end nogen har gjort før, og kigge dig omkring. Hvis Magromerne er lige så godt befæstet her, som det virker, har de måske efterladt deres landsby uden forsvar..."},
  [93125] = {n="Hjemvendt", l="Oppnå et godt forhold til Gellekisserne og eskorter Rokrøn fra Udstødtes Skjulested. Informer derefter Nerlokk ved Knoglernes Dal om det, der skete.", d="Du! Jeg så dig kæmpe mod de udstødte. Jeg ved ikke, hvor du kommer fra, men jeg har brug for din hjælp.\n\nMine slægtninge fra Gellekis lokkede mig hertil og lovede mig sikkerhed. Jeg vidste, at krigen i Forødelse var ved at komme ud af kontrol, men jeg havde aldrig forestillet mig, at mit eget folk ville vende sig mod nekromantien i et indviklet forsøg på at gå over til Magrom-klanen. Da jeg protesterede, truede de med at dræbe mig, hvis jeg så så meget som ét hov uden for dette telt!\n\nVær sød at hjælpe mig."},
  [93128] = {n="Khanen Jehn", l="Oppnå et godt forhold til Gellekisserne og dræb Khanen Jehn i Magrom-landsbyen. Når det er gjort, skal du melde dig hos Uthek den Vise i Gellekis-landsbyen på Forødelse.", d="Selvom jeg ville ønske, at Uthek eller Khan Shaka gav ordren, frygter jeg, at vinduet af muligheder er kort. For kort til at rådføre sig med folk fra Gellekis-landsbyen.\n\nJeg tror, at Magromerne med det, der sker i Knoglernes Dal, har efterladt Khanen Jehn med et minimalt forsvar. Hvis der nogensinde har været en chance for at angribe en anden klans khan, så er det nu.\n\nMen YOUR_NAME, man skal ikke tage let på khanen, og Jehn slet ikke. Hvis du er modig nok til at handle, må du være hurtig, men undervurder ham ikke."},
  [93129] = {n="Hungersnødens trussel", l="Oppnå et godt forhold til Magrom-klanen og bring 6 Stjålne Forsyninger til Hagjak ved Magrom-fronten.", d="Siden du så gerne vil hjælpe vores klan, vil du helt sikkert gå med til at medbringe lidt forsyninger, når du er i Udstødtes Skjulested.\n\nAt besejre fjenderne burde være tilstrækkelig motivation for enhver Magrom, men jeg ser ingen grund til, at vi ikke også skal tjene på det.\n\nNår vi har gjort det af med de udstødte, kan vi sikre stedet for Magromerne og samle en hær for at tvinge de andre klaner på knæ!"},
  [93173] = {n="(UBRUGT) Rusten Gadget", l="Returner Rusten Gadget til Den Mærkelige Eremit i Skyggestormsskoven", d="<Når de hvirvlende strømme, der holder Vindhule sammen, begynder at svækkes, falder en lille metalgenstand ned for dine fødder. Den ligner et mekanisk gadget. Den Mærkelige Eremit nævnte, at han stadig mangler nogle dele af sit udstyr. Måske er han interesseret.>"},
  [93188] = {n="Tilbage til Orgrulf", l="Oppnå et godt forhold til Magrom-klanen og meld dig hos Orgrulf ved den nordlige indgang til Knoglernes Dal.", d="Du har allerede gjort nok ved frontlinjen. Vi klarer os selv.\n\nFortæl Orgrulf, at du har udført din opgave. Magrom-fronten er nu stærkere, og når den næste bølge af krigere kommer, har vi udstødtes lejr under opsyn som vores næste mål.\n\nNå, hvad venter du på? Af sted!"},
  [93196] = {n="Khanen Jehn", l="Oppnå et godt forhold til Magrom-klanen og udfør nekromantiritualet for at genoplive Khanen Jehn. Ritualpladsen ligger i teltet ved Magrom-landsbyens centrale sø.", d="Vores klans leder, Khanen Jehn, blev dræbt af en flok fremmede, ligesom dig. De handlede på vegne af Gellekis-klanen.\n\nDu kan holde op med at lade som om, du er overrasket. Et angreb på Magrom-landsbyen, mens vores opmærksomhed var andetsteds, er en forudsigelig krigsstrategi, især når Gellekisserne står bag.\n\nVed du, hvorfor jeg ikke viser vrede eller sorg, fremmede?\n\n<Orgrulf rækker dig et kendt våben, gennemsyret af endnu mere kraft, end sidste gang du holdt det.>\n\nDet er derfor."},
  [93224] = {n="Udskårne kentaur-totemer", l="Saml 5 udskårne kentaur-totemer ved at dræbe centaurer fra en vilkårlig klan i hele Forødelse, og aflever dem derefter til Kaptajn Pentigas ved Nijels Punkt.", d="Det overrasker dig nok ikke, at begge centaurklaner modvilligt tager imod hjælp fra andre end deres egen klan. Det gælder især for dig og mig - du ved, ikke-centaurer.\n\nDet ene, der forbinder os, er troen på, at penge er magt, og vi ved, at de lokale centaurer handler med udskåret træ. Hvis du bringer mig nogle prøver af deres mønstre, kan jeg bestille lignende skulpturer i hast. Måske får vi en fordel på den måde."},
  [93226] = {n="Købe venskab: Magrom", l="Bring en Totempose til kvartermesteren for Magrom-klanen i Magrom-landsbyen på Forødelse for at øge dit omdømme hos klanen betydeligt. Du skal have mindst Neutral omdømme hos Magrom-klankentaurerne.", d="Jeg ville vælge Magrom-kentaurerne. Der er ingen tvivl om, at det er den klan, der dominerer nu, på trods af de gamle vanskeligheder. Jeg har hørt, at de er brutalt fjendtligt indstillet over for Gellekis-kentaurerne.\n\nJeg har medlidenhed med begge de stridende klaner, især Gellekis-kentaurerne, men det er deres krig, ikke vores. Vi bør tage parti for den side, der udgør mindst risiko for vores sag. Jeg mener, at det er Magrom-kentaurerne.\n\nBring den til deres kvartermester i Magrom-landsbyen mod sydøst."},
  [93227] = {n="Købe venskab: Gellekis", l="Bring en Totempose til kvartermesteren for Gellekis-klanen i Gellekis-landsbyen på Forødelse for at øge dit omdømme hos klanen betydeligt. Du skal have mindst Neutral omdømme hos Gellekis-klankentaurerne.", d="Ved første øjekast ville jeg gå ud fra, at Gellekis-kentaurerne har problemer. De er langt færre end Magrom-kentaurerne, og jeg hører sjældent om dem fra vores spejdere.\n\nAlligevel er de en af de dominerende klaner på Forødelse, og de har overlevet til i dag. De må have gjort noget rigtigt.\n\nHvis du vil slutte fred med Gellekis-kentaurerne, så bring totemposen til Gellekis-landsbyen, langt mod sydvest. Selvom de er primitive, har de nok en skatmester et sted."},
  [93429] = {n="Blod af mit blod", l="Dræb 10 Fortabte i Brakkernes Fristed.", d="Selvom de er vores egne frænder, er de Fortabte fra Brakkernes Fristed blevet til væsener af ren vold og had.\n\nDer er ingen forløsning eller frelse for dem. De er dømt til at vandre rundt i dette morads som tankeløse, hadefulde skabninger resten af deres liv.\n\nDette lidelse må ende. Nogen må befri dem fra deres kval. Jeg ved, at det er et dystert hverv, men vil du gøre det for at beskytte dem af os, der er blevet tilbage?"},
  [93430] = {n="Genfangst af agnen", l="Find den Fortabte fisker, der stjal Pelle Luks agn, og bring den tilbage til mig.", d="Nej, se dog! Som om disse usle væsener ikke var nok besvær, har en af dem stjålet min lykkeagn!\n\nI morges fiskede jeg, da en af dem kom op af mudderet, skar min line over og stak af med agnen. Tyven er næsten helt sikkert en af de Fortabte fiskere, som selv vil bruge den.\n\nTja, vores fiskebestand afhænger af den agn, så jeg må have den tilbage. De Fortabte fisker langs bredden lidt længere mod øst herfra. Find den tyv, YOUR_RACE7!"},
  [93464] = {n="Den besøgende magiker", l="Find en magiker i Forødelse, der kender draenetystens kraft.", d="Lad mig indrømme noget, YOUR_NAME. Selvom draenetysten er hellig for os, og det er takket være den, vi bevarer vores sunde fornuft, forstår ingen her den egentlig.\n\nJeg husker en magiker, der engang kom til Tilflugten fra Forødelse. En mand ved navn Azore Gammelmørk. Han frygtede draenetystens kraft; han sagde, at den ikke måtte havne i forkerte hænder.\n\nDengang jagede vi ham væk for at beskytte det, der er vores. Men på det seneste har jeg tænkt over, hvad han egentlig vidste.\n\nFind venligst den magiker, YOUR_RACE7. Hans viden kan være uvurderlig for os."},
  [93465] = {n="Noter om draenetysten", l="Tag Gimaschis noter om draenetysten og bring dem til Azore Gammelmørk.", d="Det ville nok være mere præcist at sige, at jeg kender nogen, der ved en del om draenetysten.\n\nDu ser, sortekunstnerne fra Flammende Klinge forsker i det. Det er et stof, der stammer fra hinsides Den Mørke Portal, så det er forståeligt, at dem, der render rundt med mørk magi, gerne vil bruge det til deres egne formål. Det kan vi naturligvis ikke tillade.\n\nHekserinden, du leder efter, hedder Gimaschi. Du finder hende på toppen af hendes tårn i kløften mod sydøst. Hendes noter vil give dig de svar, du søger."},
  [93585] = {n="Dette Lys Er Mit", l="Eskortér Fader Tuttel til Tilflugten.", d="Ah, takket være Lyset, endelig nogen civiliseret!\n\nJeg er kommet her på vegne af Den Hellige Lys' Kirke for at skabe kontakt til draeneierne i Tilflugten. Alliancen har ingen forpost her, forstår du, og en smule diplomati med de lokale kan hjælpe os med det. Lyset tager jo imod alle i sin favn, ikke sandt?\n\nVejen over broen vrimler dog med de vildere slægtninge til draeneierne. Hvis jeg skal nå Tilflugten sikkert, har jeg brug for beskyttelse. Vil du hjælpe mig, YOUR_CLASS7?"},
  [94004] = {n="Håndværkerens Brev: Ogerstyrke-eliksir", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet, der er markeret på dit kort. Dette certifikat skal være i din besiddelse for at afslutte handlen.", d="<Skrevet med forsvindende blæk beder notatet om X Ogerstyrke-eliksir, sammen med oplysninger om leveringssted og betaling. Nederst står der en tekst, der angiver, at dette certifikat kan overdrages.>"},
  [94212] = {n="Håndværkerens Brev: Visdomseliksir", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet, der er markeret på dit kort. Dette dokument skal være i din besiddelse for at afslutte handlen.", d="<Skrevet med falmet blæk beder notatet om X Visdomseliksir, sammen med oplysninger om leveringssted og betaling. Nederst står der en tekst, der angiver, at dette dokument kan overdrages.>", p="Kom herhen og varm dig ved bålet.", c="Jeg må indrømme, at jeg havde regnet med, at den forræderiske vind fra bjergene ville rive dette brev i stykker. Jeg havde ikke forestillet mig, at nogen ville se min ydmyge anmodning, og slet ikke at den ville blive leveret lige til mig.\n\nDine bestræbelser er høflige og beundringsværdige, YOUR_RACE7. Jeg vil bruge det til at støtte min meditation.\n\nJeg vil opfordre dig til at blive og dele en eller to historier fra dine rejser. Jeg nyder selskabet."},
  [94213] = {n="Håndværkerens Brev: Mindre Manaeliksir", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet, der er markeret på dit kort. Dette dokument skal være i din besiddelse for at afslutte handlen.", d="<Skrevet med falmet blæk beder notatet om X Mindre Manaeliksir, sammen med oplysninger om leveringssted og betaling. Nederst står der en tekst, der angiver, at dette dokument kan overdrages.>", p="God dag, YOUR_RACE7. Jeg sætter pris på selskabet, men min opmærksomhed er et andet sted. Hvis vi ingen forretning har, så vær venlig at gå.", c="Ah, er det den eliksir, jeg bestilte?\n\n<En alvekvinde tager fiolen med respekt fra dig.>\n\nDin ankomst er til tiden, og din generøsitet sætter jeg stor pris på. Jeg accepterer den og tilbyder dig et lille bevis på min taknemmelighed.\n\nTak, jeg håber, vi mødes igen."},
  [94216] = {n="Håndværkerens Brev: Eliksir af Mindre Smidighed", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet, der er markeret på dit kort. Dette dokument skal være i din besiddelse for at afslutte handlen.", d="<Skrevet med falmet blæk beder notatet om X Eliksir af Mindre Smidighed, sammen med oplysninger om leveringssted og betaling. Nederst står der en tekst, der angiver, at dette dokument kan overdrages.>", p="Er du her i forbindelse med...\n\n<Zizz kigger mistænksomt rundt i sin lille hytte og sænker stemmen.>\n\nEliksiren?", c="<Zizz fortsætter samtalen i en hvisken.>\n\nJeg vil ikke fortælle dig hele historien om, hvordan jeg endte her, men her er et råd til dig.\n\nNogle gange er det eneste, du skal gøre for at imponere din nye chef, at tage æren for andres arbejde. Så du vil give mig en eliksir, og jeg vil tale om, hvor meget blod, sved og tårer jeg har lagt i at skabe den.\n\nDet er et nyt job, forstår du? Jeg må gøre et godt første indtryk!"},
  [94217] = {n="Håndværkerens Brev: Mindre Trolleblods-elixir", l="Skaf de genstande, kunden har bedt om, og lever dem til stedet, der er markeret på dit kort. Dette dokument skal være i din besiddelse for at afslutte handlen.", d="<Skrevet med falmet blæk beder notatet om X Mindre Trolleblods-elixir, sammen med oplysninger om leveringssted og betaling. Nederst står der en tekst, der angiver, at dette dokument kan overdrages.>", p="Arr, har du bragt min eliksir?", c="Præcis det, Kort Johan Mithril bestilte!\n\nHer er dine mønter. Hold dem tæt ind til brystet, når du sniger dig væk herfra - arenakæmperne higer efter rigdom lige så meget, som de higer efter blod!"},
