  [4448] = {n="Korrumperet Natdrage", l="Du har fundet en sygelig, korrumperet udgave af det, der ser ud til at være en natdragplante. Frugterne, der hænger fra planten, ser rådne og giftige ud. Den trænger desperat til en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ser ud til at være en natdragplante. Frugterne, der hænger fra planten, ser rådne og giftige ud. Den trænger desperat til en form for behandling, hvis den skal gøres normal igen.", c="Du smører fire Cenarion-plantesalver på natdragen. Den begynder straks at smide sin korrumperede skikkelse og springer ud i en livlig og sund plante."},
  [4461] = {n="Korrumperet Piskerod", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en piskerod-plante. Plantens synlige rødder virker seje og læderagtige, og en slimet hinde hænger fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en piskerod-plante. Plantens synlige rødder virker seje og læderagtige, og en slimet hinde hænger fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører tre Cenarion-plantesalver på piskerodden. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4462] = {n="Korrumperet Natdrage", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en natdragplante. Frugterne, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en natdragplante. Frugterne, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører fire Cenarion-plantesalver på natdragen. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4463] = {n="Eftertanke-libram", l="Fremlæg komponenterne, dødelige.\n\nJeg kræver også betaling i form af tredive guldstykker for denne skabelse.", p="Fremlæg komponenterne, dødelige.\n\nJeg kræver også betaling i form af tredive guldstykker for denne skabelse.", c="Tag din smådims, tosse. Lad mig passe mine studier!"},
  [4464] = {n="Korrumperet Sangblomst", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en sangblomst. En stikkende, usund lugt stiger op fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en sangblomst. En stikkende, usund lugt stiger op fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører lidt Cenarion-plantesalve på sangblomsten. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4465] = {n="Korrumperet Sangblomst", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en sangblomst. En stikkende, usund lugt stiger op fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en sangblomst. En stikkende, usund lugt stiger op fra planten. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører lidt Cenarion-plantesalve på sangblomsten. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4466] = {n="Korrumperet Vindblomst", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en vindblomst. Bærrene, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en vindblomst. Bærrene, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører to Cenarion-plantesalver på vindblomsten. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4467] = {n="Korrumperet Vindblomst", l="Du har fundet en sygelig, korrumperet udgave af det, der ligner en vindblomst. Bærrene, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", p="Du har fundet en sygelig, korrumperet udgave af det, der ligner en vindblomst. Bærrene, der hænger fra planten, virker rådne og giftige. Den har desperat brug for en form for behandling, hvis den skal gøres normal igen.", c="Du smører to Cenarion-plantesalver på vindblomsten. Den begynder straks at smide sin korrumperede form og blomstrer op som en livlig og sund plante."},
  [4481] = {n="Konstitutions-libram", l="Alt i denne verden har sin pris. Prisen for den specifikke genstand, du søger, er tredive guldstykker.\n\nNaturligvis beholder jeg størstedelen af de komponenter, du har samlet. Men frygt ikke, du skal få din smådims.", p="Alt i denne verden har sin pris. Prisen for den specifikke genstand, du søger, er tredive guldstykker.\n\nNaturligvis beholder jeg størstedelen af de komponenter, du har samlet. Men frygt ikke, du skal få din smådims.", c="Det er en skændsel for hans minde... at et dødeligt væsen som dig fuldender hans livs værk.\n\nTag din amalgamation og forsvind!"},
  [4482] = {n="Sejheds-libram", l="Tredive guld, <Race>. Tredive guld og de krævede komponenter.", p="Tredive guld, <Race>. Tredive guld og de krævede komponenter.", c="Det tog Kariel, hvad der svarer til flere af dine levetider, at fuldende libramen, du nu holder, <Race>. Alt for hvad? Så hans discipel kunne stå i Brændende Stepper og forvanske hans forskning for at tilfredsstille en evig arkan trang... Forbandelse over denne skidne afhængighed.\n\nJeg er afsky over din mangel på medfølelse og din umættelige grådighed. Forsvind!"},
  [4483] = {n="Modstandskraft-libram", l="Hvis det er modstandskraft, du ønsker, kræver jeg tredive guld.", p="Hvis det er modstandskraft, du ønsker, kræver jeg tredive guld.", c="Andre librams går tabt i denne verden. Tabt på steder, du ikke ville vove at betræde. Steder, du ville bede om ikke fandtes.\n\nJeg vil opsuge energierne fra disse komponenter. Du får det efterladte spildevand..."},
  [4484] = {n="Fråseri-libram", l="Spild ikke min tid, <Race>. Giv mig det, jeg kræver. Tredive guld og komponenterne.", p="Spild ikke min tid, <Race>. Giv mig det, jeg kræver. Tredive guld og komponenterne.", c="Mit hoved dunker... Energierne fra de enorme vidder, der udgør vores univers... ARGH!\n\n<Mathredis ser pint ud.>\n\nTag, hvad du ønsker, og forsvind!"},
  [4561] = {n="Testning for urenheder - Un'Goro-krateret", l="Du tager en prøve af slim fra Un'Goro-krateret og hælder noget af den i de forskellige rør og bægre på bordet. Mens tingene begynder at koge og sprutte, skifter slimen farve. Når processen aftager og væskerne falder til ro, ser du en lille petriskål med dine rensede Un'Goro-slimprøver i sig sammen med nogle andre rester.", p="Du tager en prøve af slim fra Un'Goro-krateret og hælder noget af den i de forskellige rør og bægre på bordet. Mens tingene begynder at koge og sprutte, skifter slimen farve. Når processen aftager og væskerne falder til ro, ser du en lille petriskål med dine rensede Un'Goro-slimprøver i sig sammen med nogle andre rester.", c="Du løfter petriskålen med slimprøven i. Den eneste måde at afgøre, om prøven er ren nok, er at åbne den og undersøge indholdet selv. Ideelt set finder du en prøve, der lever op til Kemiker Fyrigs kriterier."},
  [4603] = {n="Mere Gnistrematic-action", l="Glimmatic 5200 er tom og venter på en snavsbelagt genstand, der skal renses, samt tre sølvmønter for at starte!", p="Glimmatic 5200 er tom og venter på en snavsbelagt genstand, der skal renses, samt tre sølvmønter for at starte!", c="Glimmatic 5200 vågner til live og vralter frem og tilbage. Indeni bliver den hjælpeløse snavs, der har dækket genstanden placeret i den, knust af maskinens gnomiske rengøringsmiddel.\n\nGlimmatic 5200 kommer til standsning, ledsaget af et velkendt \"klink!\" Maskinens genstandsbeholder spiraler op og afslører en pænt indpakket kasse."},
  [4604] = {n="Mere Gnistrematic-action", l="Glimmatic 5200 er tom og venter på en snavsbelagt genstand, der skal renses, samt tre sølvmønter for at starte!", p="Glimmatic 5200 er tom og venter på en snavsbelagt genstand, der skal renses, samt tre sølvmønter for at starte!", c="Glimmatic 5200 vågner til live og vralter frem og tilbage. Indeni bliver den hjælpeløse snavs, der har dækket genstanden placeret i den, knust af maskinens gnomiske rengøringsmiddel.\n\nGlimmatic 5200 kommer til standsning, ledsaget af et velkendt \"klink!\" Maskinens genstandsbeholder spiraler op og afslører en pænt indpakket kasse."},
  [4661] = {n="Testning for fordærvelse - Ondskoven", l="Du tager en prøve af slim fra Ondskoven og hælder noget af den i de forskellige rør og bægre på bordet. Mens tingene begynder at koge og sprutte, skifter slimen farve. Når processen aftager og væskerne falder til ro, ser du en lille petriskål med dine ændrede Ondskov-slimprøver i sig sammen med nogle andre rester.", p="Du tager en prøve af slim fra Ondskoven og hælder noget af den i de forskellige rør og bægre på bordet. Mens tingene begynder at koge og sprutte, skifter slimen farve. Når processen aftager og væskerne falder til ro, ser du en lille petriskål med dine ændrede Ondskov-slimprøver i sig sammen med nogle andre rester.", c="Du løfter petriskålen med slimprøven i. Den eneste måde at afgøre, om prøven er ren nok, er at åbne den og undersøge indholdet selv. Ideelt set finder du en prøve, der lever op til Kemiker Fyrigs kriterier."},
  [4785] = {n="Fint Guldgarn", l="Her er den, <Name>. Og hils venligst Menara fra os.\n\nVi forventer store ting af dig. Måske, når Legionen falder på knæ, vil dit navn blive nævnt højt og lovprist for din magt. Jeg kan ikke vente!"},
  [4801] = {n="Frostsabel-Ekko", l="I Vinterkilde skal du kæmpe mod store katte kaldet frostsabler. Disse bæster besidder utrolig hastighed og snilde. Hvis du ønsker at få frostsablens hastighed, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde skal du kæmpe mod store katte kaldet frostsabler. Disse bæster besidder utrolig hastighed og snilde. Hvis du ønsker at få frostsablens hastighed, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4802] = {n="Vinterfald-Ekko", l="I Vinterkilde skal du kæmpe mod vildfarne væsener kendt som Vinterfald-pelsbolge. Gennem deres leders ønsker har de opnået utrolig styrke. Hvis du ønsker at få Vinterfalds kraft, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde skal du kæmpe mod vildfarne væsener kendt som Vinterfald-pelsbolge. Gennem deres leders ønsker har de opnået utrolig styrke. Hvis du ønsker at få Vinterfalds kraft, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4803] = {n="Skårtand-Ekko", l="I Vinterkilde vil du finde store bjørne med ekstremt tykke huder. Disse Skårtand-bjørne opnår stor beskyttelse fra det, de kan udholde. Hvis du ønsker at få modstand mod ild, så bring mig den Ekko, du finder fra Skårtanden.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde vil du finde store bjørne med ekstremt tykke huder. Disse Skårtand-bjørne opnår stor beskyttelse fra det, de kan udholde. Hvis du ønsker at få modstand mod ild, så bring mig den Ekko, du finder fra Skårtanden.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4804] = {n="Kuldevind-Ekko", l="I Vinterkilde skal du kæmpe mod store flyvende væsener kaldet Kuldevind. Disse bæster besidder evnen til at udøve frostmagi. Hvis du ønsker at få modstand mod frost, så bring mig den Ekko, du finder fra Kuldevindene.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde skal du kæmpe mod store flyvende væsener kaldet Kuldevind. Disse bæster besidder evnen til at udøve frostmagi. Hvis du ønsker at få modstand mod frost, så bring mig den Ekko, du finder fra Kuldevindene.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4805] = {n="Istidsel-Ekko", l="I Vinterkilde skal du kæmpe mod store væsener kaldet istidsel-yetier. Disse bæster bevæger sig langsomt, men de er i stand til at undvige mange slag takket være den beskyttelse, deres tykke pels giver dem. Hvis du ønsker evnen til at undvige angreb, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde skal du kæmpe mod store væsener kaldet istidsel-yetier. Disse bæster bevæger sig langsomt, men de er i stand til at undvige mange slag takket være den beskyttelse, deres tykke pels giver dem. Hvis du ønsker evnen til at undvige angreb, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4806] = {n="Frostslæggen-Ekko", l="I Vinterkilde har du kæmpet mod de store istitaner kaldet frostslæggen. Ren kraft og styrke står til deres rådighed. Hvis du ønsker at få frostslæggens styrke, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde har du kæmpet mod de store istitaner kaldet frostslæggen. Ren kraft og styrke står til deres rådighed. Hvis du ønsker at få frostslæggens styrke, så bring mig den Ekko, du finder fra dem.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4807] = {n="Vildnisse-Ekko", l="I Vinterkilde skal du kæmpe mod mægtige væsener, der ser ud til at besidde en medfødt magisk evne. Disse vildnisse kan bruge stærke magier. Hvis du ønsker en forøgelse af din intellekt, så bring mig den Ekko, du finder fra en af uglebæsterne, du møder der.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", p="I Vinterkilde skal du kæmpe mod mægtige væsener, der ser ud til at besidde en medfødt magisk evne. Disse vildnisse kan bruge stærke magier. Hvis du ønsker en forøgelse af din intellekt, så bring mig den Ekko, du finder fra en af uglebæsterne, du møder der.\n\nHusk, du skal have Mo'aris Lager i din beholdning, hvis du vil jage efter Ekko.", c="Mo'ari kan udlede juju'en for <Name>... Brug Mo'aris Lager til at besværge dette over dig selv eller dine allierede."},
  [4970] = {n="Frostsabel-proviant", l="Saml 5 Skårtandkød og 5 Kuldevindskød til Rivern Frostvind i Vinterkilde.", d="Hvis du ønsker at bevise dig selv, kan du begynde med en meget simpel, men meget vigtig opgave.\n\nSaml kød fra kimæraerne og fra skårtand-bjørnene i området. Bring det til mig, så jeg kan bruge det til at fodre de frostsabler, der bliver trænet.", p="Disciplin og beslutsomhed er dine mål. Jeg kan bede dig om at udføre en simpel opgave mange gange; du skal yde dit bedste hver gang.", c="Tak for din hjælp, <Name>. Min mening om dig vokser, efterhånden som tiden går."},
  [4973] = {n="Tidens Optælling", l="Find 5 Andorhøj-ure blandt byens ruiner, og vend tilbage med dem til Kromie i Andorhøj-kroen, Vestlige Pestlande.", d="Hvis du er villig til at hjælpe endnu en gang, kan jeg bestemt bruge din assistance. Jeg tager gerne flere ure, du måtte finde i ruinerne af Andorhøj. De hjælper mig med at opretholde en balance over for den onde kraft, der roder med tidslinjen her.\n\nTil gengæld for de ure giver jeg dig endnu en genstand, som jeg formoder, du i fremtiden vil finde ret nyttig.", p="Urene i Andorhøj, ligesom det store ur på rådhusets ruiner, står alle frosset i tiden klokken tre. Det var dengang, pestens fulde virkning først bredte sig over byen og kvalte livet ud af den.\n\nSå meget som vi alle måtte fortryde, hvad der skete den dag, har det formet tidens strøm, som I dødelige opfatter den. Bronzedrageflugten må holde ud i sin beskyttelse af tidslinjen!", c="Igen tak for din hjælp. Venligst accepter denne gave. Selvom du stadig måske ikke ved, hvornår du skal bruge sådan en genstand, vil tiden måske i fremtiden afsløre dens sande hensigter for dig. Du kunne sige, at jeg har set noget lignende ske for dig, <Name>."},
  [5059] = {n="Låst inde", l="Døren til dasset er begyndt at splintre i kanterne af karmen, som om den gang på gang og uophørligt er blevet forsøgt skubbet op. Den er lige nu låst godt og grundigt fast udefra på dasset.\n\nNår du rusker i døren, hører du et gutturalt stønnen indefra! Hvad der end er derinde, lyder bestemt ikke venligt.", p="Døren til dasset er begyndt at splintre i kanterne af karmen, som om den gang på gang og uophørligt er blevet forsøgt skubbet op. Den er lige nu låst godt og grundigt fast udefra på dasset.\n\nNår du rusker i døren, hører du et gutturalt stønnen indefra! Hvad der end er derinde, lyder bestemt ikke venligt.", c="Med nøglen fundet på skelettet af den tidligere Fru Dalsen låser du døren til dasset op. En blodtørstig gravgyser springer ud af dasset, efter at have været fanget derinde i Gud ved hvor lang tid.\n\nDet er tydeligt på gravgyserens blodstivnende skrig ved din tilstedeværelse, at den tidligere Bonde Dalsen nu er ud over al redning."},
  [5063] = {n="Hue fra den skarlagenrøde lærde", l="For at fremstille Hue fra den skarlagenrøde lærde skal du bringe følgende genstande tilbage til Malifus Mørkhammer: 1 Upåklagelig Skind fra Udyret; 5 Frynsede Afskyelighedssting; 8 Arkankrystaller; 5 Fortryllet skarlagentråd.\n\nDu skal også betale 50 guldmønter for fremstillingen af genstanden.", d="Et finere loft får du aldrig at se. Af udyrets upåklagelige skind vil vores ekspert-håndværkere skabe den mest fænomenale hat, en tryllekunstner nogensinde kunne håbe på at pryde sit hoved med!\n\nFemti guldmønter sammen med de nævnte genstande, og dit hoved skal være prydet med Hue fra den skarlagenrøde lærde:\n\n*Det upåklagelige skind fra udyret.\n\n*Frynsede afskyelighedssting.\n\n*Arkankrystaller.\n\n*Fortryllet skarlagentråd.\n\nSE OG BEUNDR!", p="Medmindre du har alt, jeg har brug for, spilder du min tid.", c="Forbløffende! Det må have taget uger at samle de komponenter... og hvordan fandt du et upåklageligt skind?!?\n\nNyd hatten, <Name>!"},
  [5067] = {n="Benbeskyttere af Arkana", l="For at fremstille Benbeskyttere af Arkana skal du bringe følgende genstande tilbage til Malifus Mørkhammer: 1 Upåklagelig Skind fra Udyret; 5 Frynsede Afskyelighedssting; 5 Arkanitstænger; 5 Frostviskes balsameringsvæske.\n\nDu skal også betale 50 guldmønter for fremstillingen af genstanden.", d="Selvom fremstillingen af en sådan genstand aldrig er lykkedes, menes det at være muligt - under de rette omstændigheder.\n\nSkulle arkanum-søgeren ønske at indgyde benbeskytterne med enorm kraft, må de finde følgende:\n\n* Det upåklagelige skind fra Udyret.\n\n* Frynsede afskyelighedssting.\n\n*Arkanitstænger.\n\n*Frostviskes balsameringsvæske.\n\nSE OG BEUNDR!"},
  [5068] = {n="Brystplade af Blodtørst", l="For at fremstille Brystpladen af Blodtørst skal du bringe følgende genstande tilbage til Malifus Mørkhammer: 1 Upåklagelig Skind fra Udyret; 10 Frynsede Afskyelighedssting; 5 Arkanitstænger; 5 Skyggens Hud.\n\nDu skal også betale 50 guldmønter for fremstillingen af genstanden.", d="Det siges, at kun én Brystplade af Blodtørst nogensinde er blevet skabt, og at den blev lavet til den legendariske snigmorder, Garona. Om denne verden nogensinde vil se en til, er tvivlsomt.\n\nUanset det! Vores mester-håndværkere kan genskabe genstanden, givet de nødvendige komponenter:\n\n*Det upåklagelige skind fra Udyret.\n\n*Frynsede afskyelighedssting.\n\n*Arkanitstænger.\n\n*Skyggens hud.\n\nSE OG BEUNDR!", p="Medmindre du har alt, jeg har brug for, spilder du min tid.", c="Jeg troede, jeg ville være død og begravet, før jeg nogensinde så denne dag.\n\nEn præstation af denne størrelse kan kun overskygges af belønningen."},
  [5122] = {n="Troens Medaljon", l="Dette kapels kraft giver mig styrken til at modstå korruptionen i mit hjerte. Hvis jeg forlader det, vil jeg blive en dødsridder. Men der findes en medaljon, Troens Medaljon, der vil give mig den styrke, jeg har brug for, for at gå.\n\nVær venlig, <Name>, hent medaljonen. Den bevogtes af Malor den Nidkære, et gal medlem af Det Skarlagenrøde Broderskab, som residerer dybt i Skarlagen-bastionen i det vestlige Stratholm.", p="Dette kapels kraft giver mig styrken til at modstå korruptionen i mit hjerte. Hvis jeg forlader det, vil jeg blive en dødsridder. Men der findes en medaljon, Troens Medaljon, der vil give mig den styrke, jeg har brug for, for at gå.\n\nVær venlig, <Name>, hent medaljonen. Den bevogtes af Malor den Nidkære, et gal medlem af Det Skarlagenrøde Broderskab, som residerer dybt i Skarlagen-bastionen i det vestlige Stratholm.", c="Du hentede medaljonen! Nu kan jeg forlade kapellet og udføre min pligt.\n\nMin pligt er at dræbe det udyr, der hjalp med at korrumpere mig og så mange af mine brødre og søstre, Baron Flodfarer!"},
  [5150] = {n="Dadånga er sulten!", l="Dadånga kigger op på dig, da du nærmer dig hende. Hun virker til at håbe på noget...\n\nHun er nok sulten!\n\nDer må være noget, der vokser i krateret, som ville være den perfekte snack for en stor planteæder. Dadånga er en stor pige; uanset hvad du bringer hende, skal der være en masse af det!", p="Dadånga kigger op på dig, da du nærmer dig hende. Hun virker til at håbe på noget...\n\nHun er nok sulten!\n\nDer må være noget, der vokser i krateret, som ville være den perfekte snack for en stor planteæder. Dadånga er en stor pige; uanset hvad du bringer hende, skal der være en masse af det!", c="Når hun placerer skuddene foran sig, virker Dadånga tilfreds.\n\nHun skubber en lille brunindpakket pakke hen mod dig, som byttehandel for godbidden!"},
  [5201] = {n="Vinterfald-indtrængen", l="Rivern Frostvind vil have dig til at dræbe 5 Vinterfald-shamaner og 5 Vinterfald-bjørnebeester.", d="Min tilstedeværelse går upåagtet hen for de fleste, <Name>. Der er dog en irritation, der ser ud til at være fast rodfæstet her i Vinterspring: Vinterfald-pelsbolgen.\n\nSelvom jeg aldrig direkte har angrebet pelsbolgerne, virker de gale og frygtsomme over for alt på deres vej. Jeg har set dem slå utallige væsener ihjel, der havde den uheldige fornøjelse at være det forkerte sted på det forkerte tidspunkt.\n\nJeg er træt af deres blanderi -- hjælp mig venligst ved at kæmpe imod. Slå pelsbolgerne ihjel og hold dem væk fra Frostsabel-klippen.", p="Pelsbjørnene virker plaget af sådan en paranoia...", c="Det lettede mig at høre, at vi i et kort øjeblik ikke behøver at bekymre os om Vinterfald-indtrængen.\n\nDu begynder at vise din udholdenhed, <Name>."},
  [5218] = {n="Felsten-markens Gryde", l="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", p="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", c="Når reagenserne tilsættes grydens blanding, begynder skyen, den udspyr, at ændre farve og konsistens. Svøbne, der selv er i nærheden af gryden, virker til at vige tilbage, da de nye komponenter kommer ind i omgivelserne."},
  [5221] = {n="Dalsens Tårers Gryde", l="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", p="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", c="Når reagenserne tilsættes grydens blanding, begynder skyen, den udspyr, at ændre farve og konsistens. Svøbne, der selv er i nærheden af gryden, virker til at vige tilbage, da de nye komponenter kommer ind i omgivelserne."},
  [5224] = {n="Vridende Hjemsøgelse-gryden", l="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", p="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", c="Når reagenserne tilsættes grydens blanding, begynder skyen, den udspyr, at ændre farve og konsistens. Svøbne, der selv er i nærheden af gryden, virker til at vige tilbage, da de nye komponenter kommer ind i omgivelserne."},
  [5227] = {n="Gorrons Visnende Gryde", l="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", p="Svøbens pestgryde står foran dig og sprøjter enorme mængder giftstoffer op i luften. Et lille, uanseeligt adgangspanel ligger i bunden af grydens enorme platform.\n\nEfter at have besejret grydeherren og erhvervet dens nøgle, står du frit til at tilføje de passende reagenser til gryden for at lave et modgift mod pesten.", c="Når reagenserne tilsættes grydens blanding, begynder skyen, den udspyr, at ændre farve og konsistens. Svøbne, der selv er i nærheden af gryden, virker til at vige tilbage, da de nye komponenter kommer ind i omgivelserne."},
  [5402] = {n="Håndlangerens Geislesten", l="En Håndlangers Geislesten er insignia for Svøbens menige rækker. Disse findes nogle gange på de svageste af deres tropper, der er placeret på Pestlandene, selvom ordet \"svagere\" bestemt skal ses i kontekst. Svøben, uanset hvor de er, bør aldrig undervurderes.\n\nSølvdæmringen tilbyder for øjeblikket et modmærke i bytte for tyve af disse insignier - en byttehandel, jeg gerne gennemfører, forudsat at du har tjent nok geislesten!", p="En Håndlangers Geislesten er insignia for Svøbens menige rækker. Disse findes nogle gange på de svageste af deres tropper, der er placeret på Pestlandene, selvom ordet \"svagere\" bestemt skal ses i kontekst. Svøben, uanset hvor de er, bør aldrig undervurderes.\n\nSølvdæmringen tilbyder for øjeblikket et modmærke i bytte for tyve af disse insignier - en byttehandel, jeg gerne gennemfører, forudsat at du har tjent nok geislesten!", c="Til lykke, <Name> - jeg er glad for at kunne tildele dig et Sølvdæmrings-modmærke!\n\nMærkerne tjener to formål. For det første kan de bruges til at styrke din stilling inden for Sølvdæmringen; det kan give dig muligheder og belønninger, der er forbeholdt vores ærede og hyldede allierede. For det andet kan de gives til vores kvartermestre sammen med mønter som betaling for nogle af Dæmringens mere eftertragtede genstande.\n\nUanset hvad du beslutter, så ved, at du fortjener dit hverv. Vel gjort!"},
  [5403] = {n="Angriberens Geislesten", l="En Angribers Geislesten er insignia for Svøbens elitetropper. Disse findes nogle gange på de stærkere af troppene placeret på Pestlandene. At dræbe en sådan skabning er faktisk en udfordring, men en der bør nydes med et hverv om at udrydde det onde.\n\nSølvdæmringen tilbyder for øjeblikket et modmærke i bytte for ti af disse insignier. Bring dem til mig her, og jeg sørger for, at du modtager din retmæssige belønning.", p="En Angribers Geislesten er insignia for Svøbens elitetropper. Disse findes nogle gange på de stærkere af troppene placeret på Pestlandene. At dræbe en sådan skabning er faktisk en udfordring, men en der bør nydes med et hverv om at udrydde det onde.\n\nSølvdæmringen tilbyder for øjeblikket et modmærke i bytte for ti af disse insignier. Bring dem til mig her, og jeg sørger for, at du modtager din retmæssige belønning.", c="Til lykke, <Name> - jeg er glad for at kunne tildele dig et Sølvdæmrings-modmærke!\n\nHvert modmærke, der uddeles til værdige modtagere, er et tegn på, at tidevandet vender mod Svøben. Med flere og flere helte, der kæmper mod Svøben i deres egne lande, vil Sølvdæmringen sikkert være i spidsen, når tiden kommer til at føre krig mod Svøbens ultimative ondskab. Jeg håber, at det mod, du har vist for at opnå dit mærke, også da vil bære dagen!"},
  [5404] = {n="Fordærverens Geislesten", l="En Fordærvers Geislesten er insignia for Svøbens overherrer. Et mægtigt væsen, der har en autoritetsposition over Svøben, vil altid besidde en. At dræbe sådan en ondskabsfuld skabning ville helt sikkert fremme Sølvdæmringens sag, og alle gode sager!\n\nPå Sølvdæmringens vegne vil jeg give dig et modmærke i bytte for blot en enkelt af disse insignier. Vær forsigtig med at skaffe en, <Name> - sådanne mægtige væsener er ikke til at spøge med.", p="En Fordærvers Geislesten er insignia for Svøbens overherrer. Et mægtigt væsen, der har en autoritetsposition over Svøben, vil altid besidde en. At dræbe sådan en ondskabsfuld skabning ville helt sikkert fremme Sølvdæmringens sag, og alle gode sager!\n\nPå Sølvdæmringens vegne vil jeg give dig et modmærke i bytte for blot en enkelt af disse insignier. Vær forsigtig med at skaffe en, <Name> - sådanne mægtige væsener er ikke til at spøge med.", c="Til lykke, <Name> - jeg er glad for at kunne tildele dig et Sølvdæmrings-modmærke!\n\nAt opnå et modmærke på den måde viser, at du er en sand helt i det godes sag. Vi værdsætter al indsats rettet mod Svøben, men at nedlægge en af deres ledere er virkelig at give dem et knusende nederlag!\n\nFor Dæmringen, min bror!"},
  [5406] = {n="Fordærverens Geislesten", l="En Fordærvers Geislesten er insignia for Svøbens overherrer. Et mægtigt væsen, der har en autoritetsposition over Svøben, vil altid besidde en. At dræbe sådan en ondskabsfuld skabning ville helt sikkert fremme Sølvdæmringens sag, og alle gode sager!\n\nPå Sølvdæmringens vegne vil jeg give dig et modmærke i bytte for blot en enkelt af disse insignier. Vær forsigtig med at skaffe en, <Name> - sådanne mægtige væsener er ikke til at spøge med.", p="En Fordærvers Geislesten er insignia for Svøbens overherrer. Et mægtigt væsen, der har en autoritetsposition over Svøben, vil altid besidde en. At dræbe sådan en ondskabsfuld skabning ville helt sikkert fremme Sølvdæmringens sag, og alle gode sager!\n\nPå Sølvdæmringens vegne vil jeg give dig et modmærke i bytte for blot en enkelt af disse insignier. Vær forsigtig med at skaffe en, <Name> - sådanne mægtige væsener er ikke til at spøge med.", c="Til lykke, <Name> - jeg er glad for at kunne tildele dig et Sølvdæmrings-modmærke!\n\nAt opnå et modmærke på den måde viser, at du er en sand helt i det godes sag. Vi værdsætter al indsats rettet mod Svøben, men at nedlægge en af deres ledere er virkelig at give dem et knusende nederlag!\n\nFor Dæmringen, min bror!"},
