  [8192] = {n="Animistens Kærtegn", l="Zanzara kan skabe de oldgamle trolde-fortryllelser med de rette komponenter.\n\nDen første er en urgammel Håkkari-afgud, som skal tages fra den mægtigste af Håkkari-løjtnanterne: Jyn'do og Blodherren.\n\nDen anden er en punkteret voodoo-dukke. De kan findes i skraldebunkerne, der fylder dette ussle sted. Kig ind i de forhekste hokus-pokus-bunker.\n\nBring mig disse ting, så skaber jeg en kraftfuld fortryllelse til dig!", p="Zanzara kan skabe de oldgamle trolde-fortryllelser med de rette komponenter.\n\nDen første er en urgammel Håkkari-afgud, som skal tages fra den mægtigste af Håkkari-løjtnanterne: Jyn'do og Blodherren.\n\nDen anden er en punkteret voodoo-dukke. De kan findes i skraldebunkerne, der fylder dette ussle sted. Kig ind i de forhekste hokus-pokus-bunker.\n\nBring mig disse ting, så skaber jeg en kraftfuld fortryllelse til dig!", c="Brug den godt, <Class>. Vis Håkkarierne ingen nåde!"},
  [8194] = {n="Lærlingefisker", l="Selvom vi allerede har en konkurrencevinder, køber jeg stadig din Lækkerfisk af dig til en rimelig pris. Hva' siger du, hva'!", p="Selvom vi allerede har en konkurrencevinder, køber jeg stadig din Lækkerfisk af dig til en rimelig pris. Hva' siger du, hva'!", c="Handlen passer mig, hvis den passer dig!"},
  [8195] = {n="Zulisk, Rasgaskin og Håkkari-mønter", l="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", p="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", c="Fremragende - dette sæt mønter bliver en fin tilføjelse til vores voksende samling... en, som vi vil bruge i stammens forsvar mod Blodgudens fremmarch. Du har fortjent dette Æresmærke, <Name>, samt stammens tak!"},
  [8196] = {n="Essensmangoer", l="Den yderst potente essensmango vokser på mange af øerne i Sydhavet. En enkelt mango forfrisker dem, der spiser den, både fysisk og mentalt. Hvis du aldrig har smagt en, gør du dig selv en bjørnetjeneste!\n\nVi har nok på lager her på øen til at tilbyde dig en håndfuld i bytte for et Zandalsk Æresmærke. Tal med Vinkaksa, hvis du skal lære, hvordan man får mærker; ellers lad os komme til sagen!", p="Den yderst potente essensmango vokser på mange af øerne i Sydhavet. En enkelt mango forfrisker dem, der spiser den, både fysisk og mentalt. Hvis du aldrig har smagt en, gør du dig selv en bjørnetjeneste!\n\nVi har nok på lager her på øen til at tilbyde dig en håndfuld i bytte for et Zandalsk Æresmærke. Tal med Vinkaksa, hvis du skal lære, hvordan man får mærker; ellers lad os komme til sagen!", c="En fair handel, min ven - nyd venligst de dejlige frugter fra Sydhavet med stammens velsignelse."},
  [8221] = {n="Sjælden Fisk - Keefers Engelfisk", l="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Keefers Engelfisk, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", p="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Keefers Engelfisk, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", c="*Brum*\n\nIdentifikation af Keefers Engelfisk fuldført.\n\nDin belønning er nu tilgængelig.\n\n*klik-klik* *Bzzzz*"},
  [8222] = {n="Lysende Skorpidblod", l="I al den tid, jeg har arbejdet på Marked, har jeg lært en masse om kunder. Her er en af de visdomsperler: kunder elsker ting, der lyser! Det er ligegyldigt, hvad det er - du kunne tage et ødelagt stolben og få det til at lyse, og hvert eneste barn ville komme fra milevidt for at få et!\n\nSå, <Name>, jeg har brug for lysende skorpidblod. Du kan finde det hos Skorpiderne i Sillithus, på Det Sønderrevne Land eller i Brændende Stepper.", p="I al den tid, jeg har arbejdet på Marked, har jeg lært en masse om kunder. Her er en af de visdomsperler: kunder elsker ting, der lyser! Det er ligegyldigt, hvad det er - du kunne tage et ødelagt stolben og få det til at lyse, og hvert eneste barn ville komme fra milevidt for at få et!\n\nSå, <Name>, jeg har brug for lysende skorpidblod. Du kan finde det hos Skorpiderne i Sillithus, på Det Sønderrevne Land eller i Brændende Stepper.", c="Flot klaret, <Name>! Tusind tak! Jeg laver maling af dette blod og forvandler alle mulige billige skrammel til lysende skatte!\n\nHer er dine billetter, og tak igen!"},
  [8223] = {n="Mere Lysende Skorpidblod", l="Det skorpidblod fungerer fantastisk, <Name>! Det er utroligt, hvordan lidt glimmer og glans kan skabe en eftertragtet prydgenstand ud af ellers bare skrammel. Gæsterne elsker det, og kærlighed er jo det hele, er det ikke...\n\nDu har været en stor hjælp for mig, <Name>, og selvom jeg ikke har et stort behov for mere lysende skorpidblod, så bytter jeg dig stadig nogle billetter, hvis du bringer mig mere.", p="Det skorpidblod fungerer fantastisk, <Name>! Det er utroligt, hvordan lidt glimmer og glans kan skabe en eftertragtet prydgenstand ud af ellers bare skrammel. Gæsterne elsker det, og kærlighed er jo det hele, er det ikke...\n\nDu har været en stor hjælp for mig, <Name>, og selvom jeg ikke har et stort behov for mere lysende skorpidblod, så bytter jeg dig stadig nogle billetter, hvis du bringer mig mere.", c="Tak igen, <Name>. Her er dine billetter!"},
  [8224] = {n="Sjælden Fisk - Dezisk Dronningfisk", l="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Dezisk Dronningfisk, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", p="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Dezisk Dronningfisk, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", c="*Brum*\n\nIdentifikation af Dezisk Dronningfisk fuldført.\n\nDin belønning er nu tilgængelig.\n\n*klik-klik* *Bzzzz*"},
  [8225] = {n="Sjælden Fisk - Brunells Blåstribede Væddeløber", l="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Brunells Blåstribede Væddeløber, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", p="*Brum* *Klik*\n\nJeg søger sjældne fisk til Fiskemester Blågælle, så han kan katalogisere dem. Hvis du bringer mig en Brunells Blåstribede Væddeløber, giver jeg dig denne fine belønning.\n\n*Zzzap* *Brum*", c="*Brum*\n\nIdentifikation af Brunells Væddeløber fuldført.\n\nDin belønning er nu tilgængelig.\n\n*klik-klik* *Bzzzz*"},
  [8228] = {n="Kan jeg få en Fiskeri-flyver?", l="Der er en Fiskerikonkurrence i Bytteviken denne søndag! Her er turneringens regler, hvis du vil deltage!"},
  [8229] = {n="Kan jeg få en Fiskeri-flyver?", l="Der skal være en Fiskerikonkurrence i Bytteviken på søndag, makker! Her er reglerne til dig!"},
  [8238] = {n="Gurubashierne, Ondskabsgren og Visnebark-mønter", l="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", p="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", c="Fremragende - dette sæt mønter bliver en fin tilføjelse til vores voksende samling... en, som vi vil bruge i stammens forsvar mod Blodgudens fremmarch. Du har fortjent dette Æresmærke, <Name>, samt stammens tak!"},
  [8239] = {n="Sandraseri, Kraniespalter og Blodskalp-mønter", l="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", p="Jeg søger Kraftens Mønstre, kendt som Stammernes Mønter. De er valuta, som de forskellige indbyggere i Zul'Gurb bruger, og hver enkelt er gennemsyret af subtil, men kraftfuld hokus-pokus-magi.\n\nDer findes ni forskellige slags. Nogle er eftertragtet af mine kompatrioter for de rustninger, de tilbyder Zandalske helte. Har du nogle ekstra, bytter jeg gerne et af vores Æresmærker for et sæt på tre. Du kan bruge Mærkerne hos Rin'vosho Handleren; han tilbyder vores helte særlige genstande for dem.", c="Fremragende - dette sæt mønter bliver en fin tilføjelse til vores voksende samling... en, som vi vil bruge i stammens forsvar mod Blodgudens fremmarch. Du har fortjent dette Æresmærke, <Name>, samt stammens tak!"},
  [8241] = {n="Genoprettende Ildende Fluks-forsyninger via Jern", l="Lad os ikke spilde mere af min dyrebare tid med vrøvl, <Race>. Det er tid til at fokusere på at genopfylde vores svindende forsyning af ildende fluks.\n\nDet, jeg skal bruge fra dig, er følgende:\n\n*Ildosaur-skæl.\n\n*Jernstænger.\n\n*Kul.\n\nJeg tager alt, hvad du kan skaffe!\n\nOg du skal gøre det hurtigt, hvis du vil stå godt med Broderskabet.", p="Lad os ikke spilde mere af min dyrebare tid med vrøvl, <Race>. Det er tid til at fokusere på at genopfylde vores svindende forsyning af ildende fluks.\n\nDet, jeg skal bruge fra dig, er følgende:\n\n*Ildosaur-skæl.\n\n*Jernstænger.\n\n*Kul.\n\nJeg tager alt, hvad du kan skaffe!\n\nOg du skal gøre det hurtigt, hvis du vil stå godt med Broderskabet.", c="Der er altid plads til mere ildende fluks, knægt. Bliv ved med at komme med det... medmindre jeg siger, du skal stoppe."},
  [8242] = {n="Genoprettende Ildende Fluks-forsyninger via Tungt Læder", l="Lad os ikke spilde mere af min dyrebare tid med vrøvl, <Race>. Det er tid til at fokusere på at genopfylde vores svindende forsyning af ildende fluks.\n\nDet, jeg skal bruge fra dig, er følgende:\n\n*Ildosaur-skæl.\n\n*Tungt Læder.\n\n*Kul.\n\nJeg tager alt, hvad du kan skaffe!\n\nOg du skal gøre det hurtigt, hvis du vil stå godt med Broderskabet.", p="Lad os ikke spilde mere af min dyrebare tid med vrøvl, <Race>. Det er tid til at fokusere på at genopfylde vores svindende forsyning af ildende fluks.\n\nDet, jeg skal bruge fra dig, er følgende:\n\n*Ildosaur-skæl.\n\n*Tungt Læder.\n\n*Kul.\n\nJeg tager alt, hvad du kan skaffe!\n\nOg du skal gøre det hurtigt, hvis du vil stå godt med Broderskabet.", c="Der er altid plads til mere ildende fluks, knægt. Bliv ved med at komme med det... medmindre jeg siger, du skal stoppe."},
  [8243] = {n="Zanzas Potente Drikkevarer", l="Med din stigende status blandt stammen følger adgang til nogle af vores mere potente drikkevarer. Se... disse brygge er fulde af mojo - velsignet af Zanza og egnet til eventyrere fra alle samfundslag!\n\nJeg lader dig vælge én af de tre, jeg tilbyder; til gengæld kræver jeg ét Zandalar-æresmærke. Bemærk, at kun virkningen af en enkelt af dem kan flyde gennem din ånd ad gangen.\n\nLad mig vide, når du er klar til at handle!", p="Med din stigende status blandt stammen følger adgang til nogle af vores mere potente drikkevarer. Se... disse brygge er fulde af mojo - velsignet af Zanza og egnet til eventyrere fra alle samfundslag!\n\nJeg lader dig vælge én af de tre, jeg tilbyder; til gengæld kræver jeg ét Zandalar-æresmærke. Bemærk, at kun virkningen af en enkelt af dem kan flyde gennem din ånd ad gangen.\n\nLad mig vide, når du er klar til at handle!", c="En fair handel, min ven - nyd venligst Zanzas velsignelser, med vores komplimenter!"},
  [8246] = {n="Zandalarernes Signeter", l="<Name> - for en, der er så ophøjet blandt Zandalarerne som dig, har jeg noget meget særligt til dig. Direkte fra vores hjem i Sydhavet... Zandalarernes Signeter! Disse signeter bruges til at forbedre enhver skuldergenstand, du måtte besidde. Søger du kraft, mojo eller ro - så har jeg det, du behøver!\n\nJeg beder om femten Zandalar-æresmærker til gengæld for dit valg af ét signet. Har du mærkerne klar, så er jeg klar til at lave en handel!", p="<Name> - for en, der er så ophøjet blandt Zandalarerne som dig, har jeg noget meget særligt til dig. Direkte fra vores hjem i Sydhavet... Zandalarernes Signeter! Disse signeter bruges til at forbedre enhver skuldergenstand, du måtte besidde. Søger du kraft, mojo eller ro - så har jeg det, du behøver!\n\nJeg beder om femten Zandalar-æresmærker til gengæld for dit valg af ét signet. Har du mærkerne klar, så er jeg klar til at lave en handel!", c="En fair handel, min ven - modtag venligst dit signet med stammens velsignelse!"},
  [8302] = {n="Den Retfærdiges Hånd", l="Saml 200 Silitid-skalfragmenter og vend tilbage til Barostolt.", d="Vælg dine stedfortrædere klogt, dødelige. Hver gang du vender tilbage med din opgave fuldført, får du lov til at vælge en ny stedfortræder.\n\nNå, sådan er det. Jeg har brug for flere af skalfragmenterne. Spild ikke tid!", p="Måske bliver hele Cenarion-fæstningen en dag underlagt din kommando.", c="Godt gået, helt. Nu får du evnen til at udnævne endnu en Nosdormus Agent til stedfortræder."},
  [8319] = {n="Krypterede Tusmørketekster", l="Bliv ved med at bringe mig tekster. Vi tvinger snart Tusmørkets Hammer ud af Silithus.", p="Bliv ved med at bringe mig tekster. Vi tvinger snart Tusmørkets Hammer ud af Silithus.", c="Fremragende arbejde! Jeg vil sige et godt ord for dig."},
  [8324] = {n="Stadig Troende", l="Har du fundet flere krypterede tekster? Bring mig en god bunke af dem, dette afkodningsarbejde tager noget tid.", p="Har du fundet flere krypterede tekster? Bring mig en god bunke af dem, dette afkodningsarbejde tager noget tid.", c="Fremragende! Jeg kan ikke vente med at læse dem. Bliv ved med at bringe de krypterede tekster hertil, hvis du finder dem."},
  [8325] = {n="Genvindelsen af Solvandrer-øen", l="Dræb 6 Manaorme; de befinder sig tæt på de Brændende Krystaller, der ligger ved siden af tårnet og lysthuset.", d="Jo før du begynder din uddannelse, <Name>, desto bedre for os alle. Der er lille plads til fejl, så lyt nøje.\n\nDe Brændende Krystaller - de grønne svævende genstande vest for Solspiret her - har længe været brugt til at drive øens eksperimenter. Manaormene var deres vogtere, men Svøbens invasion af Quel'Thalas har drevet dem på afveje, fordi vi ikke længere har magisk kontrol over dem.\n\nDer er kun lidt valg andet end at tynde ud i deres rækker for at genvinde området. Gør dette, og vend så tilbage til mig.", p="Vores arbejde med at genopbygge vores samfund begynder her, <Name>. Når vi kan sikre vores hjem, kan vi se udad og opad.", c="Du har med succes fuldført din første opgave; for det skal du lykønskes. Sådan en succes giver mig tro på, at du vil blive bedre end de unge blodalfer, der ikke lytter til deres mestres lærdomme. Fortsat succes vil blive belønnet - ikke kun med viden, men også med håndgribelige belønninger.\n\nDit arbejde her er dog ikke færdigt. Der er meget mere at lære, min unge ven..."},
  [8326] = {n="Uheldige Foranstaltninger", l="Saml 8 Losehalsbånd fra dræbte Springpote-losser og Springpote-unger. Vend tilbage til Magistrinde Erona på Solvandrer-øen, når du er færdig.", d="Din indsats har gjort noget klart, som jeg ærligt talt ønskede ikke var sandt. Den ukontrollerede magt fra de Brændende Krystaller har forvrænget en meget større del af øens naturlige balance, end jeg troede. Vi må nu tage flere uheldige foranstaltninger for at genvinde kontrollen.\n\nLoserne i nærheden er faldet for krystallernes indflydelse, og de må nedlægges. Bring deres halsbånd, <Name>, for jeg kan måske stadig fremstille en magisk tøjle, så nogle kan vendes tilbage fra at være ukontrollerbare.", p="Det glæder mig ikke at bede dig om at ødelægge disse bæster. Mens vi i gamle dage levede i relativ harmoni med skovens skabninger, er det andre tider nu. Det første til orden for alle sin'dorei er overlevelse; husk det.", c="Tårnet og de omkringliggende områder burde nu være nogenlunde sikre, dog kun for en stund. Du har gjort det godt med at give os en buffer af sikkerhed, men vi må genoprette kontrollen over hele øen, hvis vi skal overleve her på længere sigt. Dette vil indebære at tage fat på langt større trusler end vildfarne manaorme og losser.\n\nTag dette, <Name> - du vil uden tvivl få god brug for det i opgaverne, der venter."},
  [8327] = {n="Rapport til Lanthan Perilon", l="Tal med Lanthan Perilon på Solvandrer-øen; han står tæt på stien, der løber mod vest væk fra Solspiret.", d="Du skal melde dig hos min assistent, Lanthan Perilon. Han vil fortælle dig, hvad der skal gøres nu. Mens vi her ved Solspiret fortsat vil tøjle de Brændende Krystaller, skal du koncentrere dig om en mere presserende sag vedrørende Falthrien-akademiet. Lanthan vil forklare alt, når du taler med ham.\n\nGå blot mod vest herfra langs stien, så skulle du se ham stå i nærheden.\n\nHeld og lykke, <Name> - dine fortsatte succeser skal belønnes.", c="Magistrinde Erona sagde, at du nok ville komme hurtigt nok, <Name>. Falthrien-akademiet mod vest for os - den enorme svævende bygning med de udsmykkede spir - er i dårlig stand. Du kommer til at lede arbejdet med at generobre det fra en af de Forkomne - en <Race>, der for altid er faldet for sine laveste lyster.\n\nJeg håber, du er klar til at arbejde. Dette bliver ikke kun en lektie om fare, men også om, hvad der sker, når man forsager virkeligheden om, hvem man er."},
  [8328] = {n="Magitræning", l="Tal med Julia Solvandrer - Magikerklassens træner - inde i Solspiret på Solvandrer-øen.", d="Når du avancerer i din klasse, vil du gerne drage fordel af den træning, din klassetræner kan give dig. For unge magikere her på Solvandrer-øen er din træner Julia Solvandrer. Tal med Julia og se, hvilken træning hun har til rådighed for dig. Det, hun vil lære dig, koster noget, så tag lidt mønter med.\n\nJulia - ligesom alle trænerne på Solvandrer-øen - befinder sig inde i Solspiret på den nederste etage.", c="Ah, <Name> - jeg tror, du er en af de nye magikere her på øen, ikke? Nå, du er havnet det rette sted. Hvis arkan mestring er det, du søger, så kan jeg give dig den viden - så længe du har midlerne til at betale for træningen og evnen til at fokusere på de lektioner, jeg vil undervise i.\n\nLad os komme i gang!"},
  [8329] = {n="Krigertræning", l="Tal med Deliós, krigerklassens træner, inde i Solspiret på Solvandrer-øen.", d="Når du avancerer i din klasse, vil du gerne drage fordel af den træning, din klassetræner kan give dig. For unge krigere her på Solvandrer-øen er din træner Deliós. Tal med ham og se, hvilken træning han har til rådighed for dig. Det, han vil lære dig, koster noget, så tag lidt mønter med.\n\nDeliós - ligesom alle trænerne på Solvandrer-øen - befinder sig inde i Solspiret på den nederste etage.", c="Velkommen til Solspiret, unge <Class>! Mestring af våben og kampteknik begynder her og nu - alt, hvad jeg beder mine elever om, er, at de dækker de betalinger for træning, der måtte opstå, og at de er lige så gode lyttere, som de er ivrige <Class>. Lektionerne, jeg har at undervise i, er omfattende, og jeg bryder mig ikke om at gentage mig selv unødvendigt.\n\nSå lad os komme i gang!"},
  [8330] = {n="Solanians Ejendele", l="Saml Brøndvogter Solanians Synsorb, hans Rulle med Svøbenmagi og hans Dagbog. De findes på Solvandrer-øen ved dammen, fontænen og et af de Brændende Krystaller. Returner dem til Brøndvogteren ved Solspiret på Solvandrer-øen, når du har samlet dem alle.", d="Med alt kaosset her ved Solspiret har jeg ikke haft mulighed for at samle mine ejendele, som jeg har efterladt udenfor forskellige steder på øen. Jeg må vedligeholde min vagt over Solbrønden her, så jeg beder dig om at samle dem i mit sted.\n\nJeg har brug for mit synsorb, min rulle med Svøbenmagi og min dagbog. Brug denne taske til ekstra plads, for mine ting er ret tunge. Returner dem til mig, så giver jeg dig lidt for din indsats - du ved, for besværet; du må beholde tasken også!", p="Har du haft mulighed for at finde mine ejendele? Når vi genetablerer vores dominans over Solvandrer-øen, får jeg brug for dem i mit arbejde. Indtil da må jeg dog holde vagt over Solbrønden... eller det, der er tilbage af den.", c="Godt gået - jeg vidste, du ville være perfekt til opgaven. Når det bliver sikkert at bruge øens udendørsfaciliteter, vil jeg sætte disse ting til god brug.\n\nSom nævnt må du gerne beholde tasken. Du kan også finde dette stykke rustning nyttigt. Betragt det som rigelig kompensation for en simpel opgave udført med omhu!"},
  [8333] = {n="Stationsmedaljon", l="Hvis du har brug for endnu et tusmørkekultists stationsmedaljon, så vil jeg gerne hjælpe. Jeg skal dog bruge endnu en skinnende splint og nogle afgrundskamme...", p="Hvis du har brug for endnu et tusmørkekultists stationsmedaljon, så vil jeg gerne hjælpe. Jeg skal dog bruge endnu en skinnende splint og nogle afgrundskamme...", c="Her er den, <Name>. Endnu et tusmørke-stationsmedaljon. Brug det godt, og jeg ønsker dig held mod Afgrundsrådet!"},
  [8334] = {n="Aggression", l="Dræb 7 Plejere og 7 Vilde plejere, og vend derefter tilbage til Lanthan Perilon på Solvandrer-øen.", d="Før jeg sender dig til akademiet, vil jeg have dig på en anden opgave, der skal tages hånd om med det samme. Engang brugt til at hjælpe os med havearbejdet på Solvandrer-øen er de dyriske plejere nu vokset os over hovedet. Ryd dem ud med rettidig omhu, men vær advaret - deres mangel på kontrol har gjort dem aggressive. Det er sådan en aggression, der tvinger os til at nedlægge disse engang så venlige tjenere.\n\nDet behager mig ikke at bede dig om at udføre sådan en opgave, men overlevelse er overlevelse. Jeg vil sørge senere.", p="Det er bedre, at du lærer om overlevelse - og overlevelsens pris - nu i stedet for senere. At træffe svære valg er noget, du skal vænne dig til som <Race>.\n\nDer var ingen, der var der for os, da Svøben flængede vores hjem i to. Det var os og kun os, der trak os selv op i universets bootstraps.", c="Selvom plejernes død ingen glæde giver mig, viser det mig, at du er klar til den vigtigste opgave, du vil udføre her på Solvandrer-øen. Tag dette og brug det godt; du får brug for gode genstande og skarpe hjerner til den opgave, der venter. Vores genetablering af kontrollen over øen afhænger af det."},
  [8335] = {n="Felendren den Forviste", l="Dræb 8 Arkane Gengængere og 2 Besmittede Arkane Gengængere samt Felendren den Forviste; de befinder sig på Falthrien-akademiet. Bring Felendrens Hoved til Lanthan Perilon på Solvandrer-øen.", d="En forræder mod vores folk residerer på toppen af Falthrien-akademiet mod sydvest.\n\nFelendren er hans navn, og han blev forvist fra blodalfernes lande, fordi han ikke lyttede til advarslerne fra vores lærere og ældste. Han er det værste i vores samfund, for han lever kun for at mætte sine umættelige magiske afhængigheder. Han nægtede at lære kontrol; han er en skal af sit tidligere jeg - en af de Forkomne - og han er en trussel mod Solspiret.\n\nTilintetgør ham og de gengængere, han bruger som håndlangere.", p="Tag denne advarsel til dig - Felendren den Forviste er kun et symptom på et langt større problem. Hans undergang vil løse vores umiddelbare bekymringer, men alle blodalfer deler den potentielle skæbne med ham, hvis vi lader vores afhængigheder få overtaget.", c="Felendrens hoved... du skal roses, <Name>. Du har lykkedes, der hvor andre, ligesom Felendren, fuldstændig fejlede. Måske er du virkelig klar til at blive et bidragende medlem af <Race>-samfundet.\n\nDin succes her betyder, at du er i stand til at overleve de større trusler, der lurer i Eversong... og tro mig, der er rigeligt at tage fat på."},
  [8336] = {n="En Håndfuld Splinter", l="Saml 6 Arkane Splinter fra et hvilket som helst væsen på øen, der bruger mana, og vend derefter tilbage til Arkanist Ithanas på Solvandrer-øen.", d="Det er en skam, at vi har mistet kontrollen over mange af skabningerne her på øen. Dette var engang et roligt sted for studier og forskning. Nu er alt, hvad vi kan gøre, at undgå at blive angrebet af vores egne skabninger!\n\nJeg vil give dig en chance for at modtage en magisk gave til gengæld for lidt indsamlingsarbejde fra din side. Bring mig en bunke arkane splinter, der findes på de manabrugende skabninger på Solvandrer-øen, så vil jeg kaste en besværgelse på dig, der burde hjælpe dig på dine eventyr på øen.", p="Mange af skabningerne her på øen var engang bundet til ikke-aggression og selvtilfredshed af vores magiske færdigheder. Da Svøben ødelagde Solbrønden, brød vores greb over disse skabninger. Arkane splinter er resterne af den kontrol, vi engang havde, og som sådan kan de måske bruges til at fremstille en ny enhed, der kan hjælpe os med at genvinde deres kontrol.\n\nEndnu bedre, måske kunne splinterne bruges til at se, hvilken uro øen egentlig lider under...", c="Storartet - disse vil gøre det fint. Jeg har tænkt en del over den nuværende uro, som Solvandrer-øen lider under. En mulig handlemåde, jeg havde overvejet, var at samle disse arkane splinter fra bæsterne på øen. Ved at gøre det kunne de eksperimenteres på; det ville give en potentiel kilde til skyld.\n\nUnder alle omstændigheder vil jeg tage mig af forskningen. Lad mig lægge denne besværgelse på dig. Jeg tror, du vil få god brug for den!"},
  [8338] = {n="Besmittet Arkan Splinter", l="Bring den Besmittede Arkane Splinter til Arkanist Helion ved lysthuset i Solspiret på Solvandrer-øen.", d="Du har fundet en underlig splint af krystalliseret mana på liget af den besmittede arkane gengænger. Splinten er anderledes end andre, du måske har set, idet den er lige så mørk og ond at se på som gengængeren, du plyndrede den fra. Bare det at holde den giver dig en fornemmelse af unaturlig forudanelse.\n\nArkanist Helion ved lysthuset i Solspiret på Solvandrer-øen kunne måske være en, der har gavn af splinten.", p="Ud fra din opførsel virker det, som om du er i en sag af en vis hastighed. Er der noget særligt, jeg kan hjælpe dig med?", c="Dette er... meget interessant. Og når jeg siger interessant, mener jeg mere foruroligende end noget andet.\n\nVores bestræbelser på at genetablere kontrollen over øen i tiden efter ødelæggelsen af Solbrønden har været en udfordring. Jeg mistænker, at den onde kilde, der korrumperer øen, er kernen i det hele; denne splint kan være til hjælp med at afdække, hvad der virkelig foregår.\n\nDu var klog til at bringe dette til mig, <Name>. Tag dette som kompensation for din flid. Tak."},
  [8342] = {n="Tusmørke-herredømmeringen", l="<Name>, hvis du planlægger at gå efter Afgrundsrådet igen, så skal du bruge endnu en tusmørke-herredømmering. Bring mig flere splinter og signeter, så laver jeg en til dig.", p="<Name>, hvis du planlægger at gå efter Afgrundsrådet igen, så skal du bruge endnu en tusmørke-herredømmering. Bring mig flere splinter og signeter, så laver jeg en til dig.", c="Ah, jeg kan se, dine overbevisninger er stærke. Ikke mange vil møde det råd af djævle!\n\nHer er din ring, <Name>. Må din vilje og din lykke stå fast."},
  [8344] = {n="Vinduer til Kilden", l="Bring 4 Gengængeressenser og 1 Besmittet Gengængeressens til Kalder Teli'Larien ved Solspiret på Solvandrer-øen.", d="Lyt til mine ord, unge - der er en besmittelse over denne ø, og den er langt mere potent end resterne af Svøben.\n\nJeg tror, der er en sand dæmonisk tilstedeværelse på øen.\n\nMod vest ligger Falthrien-akademiets spir. De arkane gengængere, der hjemsøger det, er et vindue til dæmonmagtens kilde. Du skal bringe mig essenserne fra besmittede og ubesmittede gengængere.\n\nSom tak for din lydighed vil jeg lære dig, hvordan du fremkalder en djævlekammerat - din første af mange som hekseriær. Du vil lære:"},
  [8345] = {n="Dath'Remærs Helligdom", l="Læs pladen på Dath'Remærs Helligdom og vend derefter tilbage til Brøndvogter Solanian ved Solspiret på Solvandrer-øen.", d="Dag efter dag står jeg her og ser, venter. Jeg er blevet beskyldt for at dvæle for meget ved vores fortid, mens mine øjne ser mod horisonten. Men det er min faste overbevisning, at hver besøgende på denne ø bør ære dem, der har ofret alt, så de selv kan fortsætte med at gøre det.\n\nDath'Remær Solvandrer var vores første konge. Han førte os hertil fra Kalimdør gennem Malstrømmen.\n\nSøg hans helligdom mod vest, og vend ikke tilbage til mig, før du har læst pladen på den til hans ære.", c="Ah, <Name> - tak for at dele din oplevelse ved Dath'Remærs Helligdom. Først og fremmest bør du roses for din pligtfølelse og respekt - det vil tjene dig godt, ikke kun her, men også i hele Azeroth.\n\nAngående den underlige fornemmelse, er den uden tvivl en medvirkende del af den besmittelse, der har ramt Solvandrer-øen. Vi vil holde øje med den; tak for at gøre os opmærksomme på den!"},
  [8346] = {n="Tørst Uden Ende", l="Brug din Arkane Torrent-racevne på en Manaorm, og vend derefter tilbage til Arkanist Helion.", d="Hvis der er én lektie, du vil huske fra din tid på Solvandrer-øen, så lad det være denne - kontroller din tørst efter magi. Det er en tørst uden ende, <Name> - det, du absorberer, skal kontrolleres og udløses via Arkane Torrent. Fiasko betyder at blive en af de Forkomne... håbløst afhængig og sindssyg.\n\nSøg en manaorm og slip din Arkane Torrent løs på den. Lær at mestre din kraft. Når du har udløst en Arkane Torrent tilstrækkeligt, skal du vende tilbage til mig.", c="Du har klaret dig godt i dag, <Name>. Din vilje til at lære viser, at du meget vel kan rejse dig over de ubøjelige begær, du må udholde som <Race>.\n\nHvil ikke på dine laurbær, unge, men søg i stedet at mestre det, du har lært. Kun gennem flid vil vi som folk overleve.\n\nTag dette - det kan måske være til nytte for dig. Gå nu, og bring ære til vores folk igen."},
  [8347] = {n="Hjælp til Løberne", l="Tal med Løber Alarion nær broen, der fører syd fra Solvandrer-øen.", d="Magistrinde Erona ville have, at du skulle tage over til Sølvmåne By for at hjælpe vores genetableringsindsats der... altså når du havde håndteret situationen ved Falthrien-akademiet. Du skuffede os ikke, <Name>.\n\nPå vej til Falkevingepladsen, sydfor herfra, skal du tale med Løber Alarion. Hun er ikke langt fra broen.\n\nLøberne sørger for at transportere varer mellem her og fastlandet, og da du har vist dig at være så opfindsom, kunne de bruge din hjælp.", c="Hej der, <Class>! Jeg hørte, at en opfindsom ung <Race>, der tidligere var i Magistrinde Eronas tjeneste, måske er på vej herned for at hjælpe os Løbere. Vi byder bestemt hjælpen velkommen, især fra nogen, der har vist sig at være så kompetent.\n\nJeg håber, du er interesseret i at løbe et ærinde eller to for os."},
  [8350] = {n="Afslutning af Leveringen", l="Lever Eronas Pakke til Krovært Delaniel inde i kroen ved Falkevingepladsen i Eversong-skoven.", d="Døden af endnu en løber er en sand tragedie, men det er en risiko, vi alle accepterer, når vi tager jobbet. Magistrinde Erona ved Solspiret skal have denne pakke til kroen ved Falkevingepladsen, og hun har brug for den der så hurtigt som muligt.\n\nVi er underbemandede, og jeg har ingen andre til rådighed, der kan dække for os.\n\nJeg vil ikke lyve for dig; stien til Falkevingepladsen kan være ekstremt farlig, hvis du forlader sikkerheden på Gryningsstræde. Føler du dig klar til opgaven, <Name>?", p="Velkommen til min kro, <Class>. Skal jeg forstå, at du har noget til mig?", c="Tak, jeg sætter virkelig pris på den prompte levering.\n\nMens du er her, så gør dig selv tilpas. Hvis du ikke allerede har gjort det, så er du velkommen til at skaffe en hjemsten og binde dig her. Ved at bruge en hjemsten kan du vende tilbage til en kro én gang hver halve time. Hvis du nogensinde mister din hjemsten, skal du blot vende tilbage til en hvilken som helst kro - en krovært vil gerne skaffe dig en ny."},
  [8353] = {n="Kyllingeklukken for en Mønthus", l="Lav en kyllingegestus ved Krovært Ildbrygger, og til gengæld får du en Jernsmede-Mønthus!", d="Ah, slikbanker for et sygt barn, er vi? Jeg skulle næsten have sagt, at du er lidt for gammel til at rode rundt efter slik...\n\nNå, for min belønning - en Jernsmede-Mønthus - skal du... klukke som en kylling! Ja, kyllinger elsker mønthuse... nå ja, måske elsker de dem ikke rigtigt... men jeg giver dig ingen mønthus, medmindre du klukker som en kylling for mig!\n\nNå <Class>, er du til udfordringen eller ej?! Tid til at fortjene din belønning!", p="Jeg venter...", c="Virkelig sjovt! Godt gået, <Name>! Her er din belønning.\n\nGlædelig Helligaftens Ende!"},
  [8354] = {n="Kyllingeklukken for en Mønthus", l="Lav en kyllingegestus ved Krovært Nordmand, og til gengæld får du en Underbyen-Mønthus!", d="Ah, slikbanker for et sygt barn, er vi? Jeg skulle næsten have sagt, at du er lidt for gammel til at rode rundt efter slik...\n\nNå, for min belønning - en Underbyen-Mønthus - skal du... klukke som en kylling! Ja, kyllinger elsker mønthuse... nå ja, måske elsker de dem ikke rigtigt... men jeg giver dig ingen mønthus, medmindre du klukker som en kylling for mig!\n\nNå <Class>, er du til udfordringen eller ej?! Tid til at fortjene din belønning!", p="Jeg venter...", c="Virkelig sjovt! Godt gået, <Name>! Her er din belønning.\n\nGlædelig Helligaftens Ende!"},
  [8355] = {n="Ankommende Gummibamse", l="Lav en togtude-gestus ved Talvash del Kisselsen, og til gengæld får du en Nisseborg-gummibamse!", d="En slikbanker! Hurra!\n\nNu, selvom du gør noget ædelt ved at samle slik til et sygt barn, kan jeg ikke slippe dig så let. Jeg har en lækker Nisseborg-gummibamse til det syge barn... hvis du laver en togtude for mig! Haha, ja, det bliver tricket! Prisen for denne gummibamse er én togtude!\n\nTuff-tuff, <Class>!", p="Nå, gå så i gang nu...", c="Uh-uh! Godt gået, <Name>! Her er din belønning.\n\nGlædelig Helligaftens Ende!"},
  [8356] = {n="Bøjning for nougat", l="Lav en bøj-gestus ved Krovært Ellen, så får du til gengæld Stormvind-nougat!", d="Det er et... interessant kostume, du har på. Selvom du er venlig og hjælper et sygt barn med at gå rundt og tigge slik i år, er jeg bange for, at jeg må bede dig om at udføre et puds for mig!\n\nLad os se... du ser så stærk og muskuløs ud i det... kostume... lad os se dig bøje dig! Ja, gå nu i gang og bøj dig for mig, stærke <man/woman>!\n\nDet er først, når og kun når du bøjer dig, at jeg giver dig noget lækkert Stormvind-nougat. Det er en fantastisk godbid til Helligaftens Ende.", p="Intet slik, før du har bøjet dig for mig, <Name>...", c="Du er virkelig mægtig, haha! Godt gået, og tak for at være en så god sportsmand. Her er dit slik.\n\nGlædelig Helligaftens Ende, <Name>!"},
  [8357] = {n="Dans for marcipan", l="Lav en dans-gestus ved Krovært Sælienne, så får du til gengæld Darnassos-marcipan!", d="Selvom du går rundt og tigger slik for et sygt barn, skal du stadig udføre et puds for godbidden! Vi kan jo ikke ændre traditionen nu, kan vi...\n\nJeg tror, prisen for et stykke marcipan i dag er at slå om sig og DANSE! Det er rigtigt, lad mig se dine bevægelser! Dans for mig, så giver jeg dig noget lækkert marcipan!", p="Du kan jo danse, ikke? Prøv ved at sætte højre fod ind... så højre fod ud... højre fod ind... ryst det hele rundt...", c="Du er en ren dansemaskine, <Name>!\n\nHer er din godbid for at være en så god sportsmand. Glædelig Helligaftens Ende, og hils din syge lille ven fra mig! Jeg håber, de snart bliver bedre."},
  [8358] = {n="Kommende gummibamse", l="Lav en træn-gestus ved Kaja Remiks, så får du til gengæld en Mørkspyd-gummibamse!", d="En slikindsamler! Ja, mand!\n\nNå, selvom du gør noget ædelt ved at samle slik til et sygt barn, kan jeg ikke bare lade dig slippe så nemt. Jeg har en lækker Mørkspyd-gummibamse at give det syge barn... hvis du laver en træn-lyd for mig! Haha, ja, det bliver pusten! Prisen for denne gummibamse er én træn-lyd.\n\nTuf-tuf, <Class>!", p="Nå, så gå i gang nu...", c="Tuut-tuut! Godt gået, <Name>! Her er din godbid.\n\nGlædelig Helligaftens Ende!"},
  [8359] = {n="Bøjning for nougat", l="Lav en bøj-gestus ved Grydeska, så får du til gengæld Orgrimgrad-nougat!", d="Det er et... interessant kostume, du har på. Selvom du er venlig og hjælper et sygt barn med at gå rundt og tigge slik i år, er jeg bange for, at jeg må bede dig om at udføre et puds for mig!\n\nLad os se... du ser så stærk og muskuløs ud i det... kostume... lad os se dig bøje dig! Ja, gå nu i gang og bøj dig for mig, stærke <man/woman>!\n\nDet er først, når og kun når du bøjer dig, at jeg giver dig noget lækkert Orgrimgrad-nougat. Det er en fantastisk godbid til Helligaftens Ende.", p="Intet slik, før du har bøjet dig for mig, <Name>...", c="Du er virkelig mægtig, haha! Godt gået, og tak for at være en så god sportsmand. Her er dit slik.\n\nGlædelig Helligaftens Ende, <Name>!"},
  [8360] = {n="Dans for marcipan", l="Lav en dans-gestus ved Spaden, så får du til gengæld Tordenklippe-marcipan!", d="Selvom du går rundt og tigger slik for et sygt barn, skal du stadig udføre et puds for godbidden! Vi kan jo ikke ændre traditionen nu, kan vi...\n\nJeg tror, prisen for et stykke marcipan i dag er at slå om sig og DANSE! Det er rigtigt, lad mig se dine bevægelser! Dans for mig, så giver jeg dig noget lækkert marcipan!", p="Du kan jo danse, ikke? Prøv ved at sætte højre fod ind... så højre fod ud... højre fod ind... ryst det hele rundt...", c="Du er en ren dansemaskine, <Name>!\n\nHer er din godbid for at være en så god sportsmand. Glædelig Helligaftens Ende, og hils din syge lille ven fra mig! Jeg håber, de snart bliver bedre."},
  [8362] = {n="Afgrunds-våbenskjolde", l="Du har bevist, at du kan klare dig i kamp, <Name>. Lad os holde trykket oppe på Tusmørkets Hammer. Gå og kæmp mod nogle flere Afgrunds-tempelriddere, så belønner jeg dig med noget af det, Hum og jeg har fundet i kamp.", p="Du har bevist, at du kan klare dig i kamp, <Name>. Lad os holde trykket oppe på Tusmørkets Hammer. Gå og kæmp mod nogle flere Afgrunds-tempelriddere, så belønner jeg dig med noget af det, Hum og jeg har fundet i kamp.", c="Du har klaret dig godt! Det er færre tempelriddere, jeg skal bekymre mig om.\n\nVær så god, <Name>. Håber der er noget brugbart til dig i den."},
  [8363] = {n="Afgrunds-signeter", l="Du har vist, at du er mere end i stand til at tage dig af en Afgrundshertug, <Name>. Jeg er altid til at fremme gode vaner. Bring mig flere signeter, så giver jeg dig en belønning.", p="Du har vist, at du er mere end i stand til at tage dig af en Afgrundshertug, <Name>. Jeg er altid til at fremme gode vaner. Bring mig flere signeter, så giver jeg dig en belønning.", c="Fremragende, <Name>! Hvis du besejrer de hertuger, vil Tusmørkets Hammer være lidt ude af balance i noget tid. Som lovet, her er din belønning. Det er noget af det bedre, Hum og jeg har fundet."},
  [8364] = {n="Afgrunds-scepterne", l="Du har virkelig overgået alle mine forventninger, <Name>. Du har kastet dig over modstandere, som Hum og jeg ville tænke os grundigt om før at kaste os ud i.\n\nPå dette stadie er det bedste, jeg kan gøre, at blive ved med at belønne din indsats i kampen mod Tusmørkets Hammer og deres overherrer.\n\nBring mig flere afgrunds-scepter, så gør jeg mit bedste for at give dig en passende belønning.", p="Du har virkelig overgået alle mine forventninger, <Name>. Du har kastet dig over modstandere, som Hum og jeg ville tænke os grundigt om før at kaste os ud i.\n\nPå dette stadie er det bedste, jeg kan gøre, at blive ved med at belønne din indsats i kampen mod Tusmørkets Hammer og deres overherrer.\n\nBring mig flere afgrunds-scepter, så gør jeg mit bedste for at give dig en passende belønning.", c="Jeg vidste, du ville klare den, <Name>! Her er din belønning."},
  [8383] = {n="Husk Alterac-dalen!", l="Slaget i Alterac-dalen buldrer videre, <Name>! Har du gjort din del på det seneste, <Name>?", p="Slaget i Alterac-dalen buldrer videre, <Name>! Har du gjort din del på det seneste, <Name>?", c="Du bliver ved med at ære Alliancen, <Name>. Horden vil blive knust inden længe, hvis vi holder vores indsats oppe."},
  [8384] = {n="Erobring af Arathi-bækkenet", l="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", p="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", c="Fremragende arbejde, <Class>! Din indsats vil hjælpe med at forsyne Alliancen med de ressourcer, den har brug for."},
  [8385] = {n="Fælles indsats", l="Ah, <Name>. Jeg håber, du bliver ved med at låne din erfaring til de forskellige slagfronter. Mange af vores drenge og piger ude på marken ser op til erfarne veteraner som dig.", p="Ah, <Name>. Jeg håber, du bliver ved med at låne din erfaring til de forskellige slagfronter. Mange af vores drenge og piger ude på marken ser op til erfarne veteraner som dig.", c="Du lever op til dit ry, <Name>. Uden folk som dig ville Alliancen ikke have en chance mod Hordens vilde styrker."},
  [8386] = {n="Kampen om Krigssang-Gulch", l="Glem ikke, at kampen om Krigssang-Gulch handler om mere end blot at beskytte træer. Det handler om at bevare en naturlig barriere mellem Askedalen og Ødemarken. Har du nogen nyheder fra slagmarken, <Name>?", p="Glem ikke, at kampen om Krigssang-Gulch handler om mere end blot at beskytte træer. Det handler om at bevare en naturlig barriere mellem Askedalen og Ødemarken. Har du nogen nyheder fra slagmarken, <Name>?", c="Godt gået, <Name>. Takket være dig vil vores naturlige forsvar i Askedalen forblive intakt endnu en dag."},
  [8387] = {n="Angribere i Alterac-dalen", l="Slaget om Alterac buldrer videre! Du må vende tilbage til Alterac-dalen og endnu en gang drive angriberne ud af Frostulvenes Territorium, <Name>!", p="Slaget om Alterac buldrer videre! Du må vende tilbage til Alterac-dalen og endnu en gang drive angriberne ud af Frostulvenes Territorium, <Name>!", c="Godt gået, <Name>! Du burde være stolt af dig selv. Alliance-angriberne skal fordrives fra Alterac!"},
  [8388] = {n="For stor ære", l="Mange modige kæmpere ser op til dig, <Name>. Du bliver ved med at være et eksempel for alle i kampen mod Alliancen. Hvilke nyheder bringer du fra dine rejser?", p="Mange modige kæmpere ser op til dig, <Name>. Du bliver ved med at være et eksempel for alle i kampen mod Alliancen. Hvilke nyheder bringer du fra dine rejser?", c="Du bliver ved med at ære Horden, <Name>. Jeg er glad for at se, at du ikke er blevet blød."},
  [8389] = {n="Slaget ved Krigssang-Gulch", l="Slaget i Krigssang-Gulch buldrer videre, <Name>. Gør din del for at drive Sølvvinge-vagterne ud af vores lande!", p="Slaget i Krigssang-Gulch buldrer videre, <Name>. Gør din del for at drive Sølvvinge-vagterne ud af vores lande!", c="Godt gået, <Class>! Du har hjulpet med at sikre Hordens herredømme over Krigssang-Gulch!"},
  [8390] = {n="Erobrende Arathi-bækkenet", l="Krigen mod Alliance-pøblen kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", p="Krigen mod Alliance-pøblen kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", c="Fremragende arbejde, <Name>! Så længe Arathi-bækkenet forbliver under vores kontrol, vil vores forsyninger være godt fyldt op."},
  [8391] = {n="Erobring af Arathi-bækkenet", l="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", p="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", c="Fremragende arbejde, <Class>! Din indsats vil hjælpe med at forsyne Alliancen med de ressourcer, den har brug for."},
  [8392] = {n="Erobring af Arathi-bækkenet", l="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", p="Krigen mod Horden tærer hurtigt på vores forsyninger, <Name>. Det er afgørende at bevare kontrollen over Arathi-bækkenet, så ressourcestrømmen fortsat løber! Har du givet en hånd i Arathi endnu?", c="Fremragende arbejde, <Class>! Din indsats vil hjælpe med at forsyne Alliancen med de ressourcer, den har brug for."},
