  [8405] = {n="Kampen om Krigssang-Gulch", l="Glem ikke, at kampen om Krigssang-Gulch handler om mere end blot at beskytte træer. Det handler om at bevare en naturlig barriere mellem Askedalen og Ødemarken. Har du nogen nyheder fra slagmarken, <Name>?", p="Glem ikke, at kampen om Krigssang-Gulch handler om mere end blot at beskytte træer. Det handler om at bevare en naturlig barriere mellem Askedalen og Ødemarken. Har du nogen nyheder fra slagmarken, <Name>?", c="Godt gået, <Name>. Takket være dig vil vores naturlige forsvar i Askedalen forblive intakt endnu en dag."},
