  [8431] = {n="Slaget ved Krigssang-Gulch", l="Slaget i Krigssang-Gulch raser videre, <Name>. Gør din del for at drive Sølvvinge-vagterne ud af vores lande!", p="Slaget i Krigssang-Gulch raser videre, <Name>. Gør din del for at drive Sølvvinge-vagterne ud af vores lande!", c="Godt gjort, <Class>! Du har hjulpet med at sikre Hordens herredømme over Krigssang-Gulch!"},
