  [8440] = {n="Erobrende Arathi-bækkenet", l="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", p="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", c="Fremragende arbejde, <Name>! Så længe Arathi-bækkenet forbliver under vores kontrol, vil vores forsyninger være godt forsynede."},
  [8441] = {n="Erobrende Arathi-bækkenet", l="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", p="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", c="Fremragende arbejde, <Name>! Så længe Arathi-bækkenet forbliver under vores kontrol, vil vores forsyninger være godt forsynede."},
  [8442] = {n="Erobrende Arathi-bækkenet", l="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", p="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", c="Fremragende arbejde, <Name>! Så længe Arathi-bækkenet forbliver under vores kontrol, vil vores forsyninger være godt forsynede."},
  [8443] = {n="Erobrende Arathi-bækkenet", l="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", p="Krigen mod Alliancens bundfald kræver ressourcer, <Name>! Vi kan ikke tillade, at vores lagre løber tør midt i en kamp. Bliv ved med at sikre, at Arathi-bækkenet forbliver i vores hænder!", c="Fremragende arbejde, <Name>! Så længe Arathi-bækkenet forbliver under vores kontrol, vil vores forsyninger være godt forsynede."},
  [8463] = {n="Ustabile manakrystaller", l="Bring 6 ustabile manakrystaller tilbage til Aeldon Solbrand på Falkevingepladsen.", d="En flok Elendige plyndrede for nylig et lager med ustabile manakrystaller fra et af vores arkane helligdomme. Hvis de ikke håndteres ordentligt, kan krystallerne eksplodere med nok kraft til at slå et hul i bymurene.\n\nNu, <Name>, er det mig ligegyldigt, om de sprænger sig selv i luften, mens de tapper ustabile arkane kilder, men hele episoden ville få mine mænd til at se dumme ud.\n\nBring mig de stjålne krystaller, du måtte finde tilbage; de kan stadig være i deres oprindelige kasser.", p="Har du fået de stjålne varer tilbage endnu?", c="Fremragende arbejde, <Name>."},
  [8466] = {n="Fjer til Grasle", l="Selvom du har bevist dig over for mig, må du muligvis fortsætte med at arbejde på at bevise dig over for mit stammes mistænksomme brødre. Til det formål kan jeg måske fortsætte med at hjælpe dig.\n\nNogle af Dødtræ-pelsbjørnene bærer en karakteristisk hovedbeklædning, som kan bruges som bevis, når deres antal skal reduceres. Bring mig en fjer fra enhver hovedbeklædning, du skaffer; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", p="Selvom du har bevist dig over for mig, må du muligvis fortsætte med at arbejde på at bevise dig over for mit stammes mistænksomme brødre. Til det formål kan jeg måske fortsætte med at hjælpe dig.\n\nNogle af Dødtræ-pelsbjørnene bærer en karakteristisk hovedbeklædning, som kan bruges som bevis, når deres antal skal reduceres. Bring mig en fjer fra enhver hovedbeklædning, du skaffer; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", c="Godt gjort, <Name>! Jeg vil sørge for, at dine bedrifter bliver kendt blandt mit folk.\n\nHusk at bringe mig de fjer, du finder. Jeg vil fortsætte med at modtage dem, så længe det er nødvendigt."},
  [8467] = {n="Fjer til Nafjen", l="Selvom du har bevist dig over for mig, må du muligvis fortsætte med at arbejde på at bevise dig over for mit stammes mistænksomme brødre. Til det formål kan jeg måske fortsætte med at hjælpe dig.\n\nNogle af Dødtræ-pelsbjørnene bærer en karakteristisk hovedbeklædning, som kan bruges som bevis, når deres antal skal reduceres. Bring mig en fjer fra enhver hovedbeklædning, du skaffer; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", p="Selvom du har bevist dig over for mig, må du muligvis fortsætte med at arbejde på at bevise dig over for mit stammes mistænksomme brødre. Til det formål kan jeg måske fortsætte med at hjælpe dig.\n\nNogle af Dødtræ-pelsbjørnene bærer en karakteristisk hovedbeklædning, som kan bruges som bevis, når deres antal skal reduceres. Bring mig en fjer fra enhver hovedbeklædning, du skaffer; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", c="Godt gjort, <Name>! Jeg vil sørge for, at dine bedrifter bliver kendt blandt mit folk.\n\nHusk at bringe mig de fjer, du finder. Jeg vil fortsætte med at modtage dem, så længe det er nødvendigt."},
  [8468] = {n="EFTERLYST: Thaelis Sultneren", l="Bring Thaelis' hoved til Sergent Kan'ren på Falkevingepladsen i Eversong-skoven.", d="Byen Sølvmåne udsteder hermed en belønning for hovedet af Thaelis Sultneren, den berygtede anfører for de Elendige. Han eftersøges for gentagne forbrydelser mod Sølvmåne By's almindelige befolkning, herunder mordet på to byvagter.\n\nMeld dig hos Sergent Kan'ren for at hente belønningen.", p="Har du noget at vise mig?", c="Den skurk Thaelis har endelig mødt sin skæbne. Godt gjort, <Name>. Der burde være roligt med de Elendige et stykke tid."},
  [8469] = {n="Perler til Salvie", l="Du har bestemt fortjent min tillid, <Name>, men du må muligvis fortsætte med at vinde tilliden hos mit mistroiske stamme. Der er noget, du kan gøre for at vinde den tillid.\n\nVinterfald er kendt for at bære åndsperler for at beskytte sig mod onde ånder. Disse perler har tydeligvis svigtet deres formål, for Vinterfald selv er korruptionens redskaber. Bring mig disse åndsperler fra faldne Vinterfald-pelsbjørne; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", p="Du har bestemt fortjent min tillid, <Name>, men du må muligvis fortsætte med at vinde tilliden hos mit mistroiske stamme. Der er noget, du kan gøre for at vinde den tillid.\n\nVinterfald er kendt for at bære åndsperler for at beskytte sig mod onde ånder. Disse perler har tydeligvis svigtet deres formål, for Vinterfald selv er korruptionens redskaber. Bring mig disse åndsperler fra faldne Vinterfald-pelsbjørne; for hvert sæt af fem, du bringer mig, opnår du anerkendelse blandt Tømmerkæberne.", c="Endnu engang beviser du din ære over for os! Jeg vil sørge for, at dine bedrifter bliver kendt blandt mit folk.\n\nHusk at bringe mig de Vinterfald-perler, du finder. For hvert sæt, du fortsætter med at bringe mig, vil jeg tale på dine vegne over for stammen."},
  [8472] = {n="Stor Fejl", l="Saml 6 arkankerner fra de arkane patruljer, der strejfer rundt i ruinerne af Sølvmåne By, og bring dem til Magister Jaronis på Falkevingepladsen i Eversong-skoven.", d="De arkane patruljer, som vores forfædre skabte til at beskytte byen, er faldet i en farlig forfaldstilstand. De genkender os ikke længere som deres herrer og vil angribe os ved første øjekast!\n\nSelvom de blev skabt for mange år siden, er de arkankerner, der driver dem, stadig ret nyttige og værdifulde for os. Jeg vil have dig til at samle disse kerner og bringe dem til mig, så jeg kan bruge dem godt igen. Du finder patruljerne i den ødelagte del af Sølvmåne mod nordvest.", p="Er det lykkedes dig at samle arkankernerne endnu, <Name>?", c="Godt klaret, <Name>. Eftersom vores arkane helligdomme ikke kører med fuld kapacitet, vil disse kraftkerner gå langt i at supplere vores behov."},
  [8473] = {n="En dyster opgave", l="Slå 10 visnet grønne vogtere ned i den Forkullede Lund. Rapportér derefter tilbage til Larianna Flodvind inde i tårnet lige nordvest for den Forkullede Lund i Eversong-skoven.", d="Det er svære tider for os, <Name>. Det var en meget svær beslutning at brænde skovene, der grænser op til Spøgelseslandene, for at forhindre Svøbens ekspansion.\n\nTrætrolde, som har været vores venner i årevis, forsøger nu at fremme genvæksten af skoven ved den Forkullede Lund.\n\nDet er en smertefuld ting at bede dig om, <Class>, men vi har ikke kunnet overtale vores tidligere allierede til at standse deres bestræbelser. Jeg har brug for, at du stopper dem med det eneste middel, der er tilbage for os: magt.", c="Så, det er gjort. Forbandet være disse tider, der har drevet os til desperate midler... og forbandet være vores fjende, Svøben!\n\nLær dette, <Name>. Vores lande skal beskyttes, uanset prisen. Vi skal sejre!"},
  [8474] = {n="Gamle Hvidbarks vedhæng", l="Find den person, der muligvis har lavet Gamle Hvidbarks vedhæng. De kan måske give noget indsigt i genstanden.", d="Vedhænget har initialerne L.R. indgraveret i sig. Måske fører disse bogstaver til vedhængets skaber.", p="Har du noget at vise mig?", c="Dette... dette vedhæng. Jeg gav det til Gamle Hvidbark, efter hans folk hjalp os med at genopbygge vores landsby.\n\nJeg regner med, at det betyder, at han er...\n\n<Den <Race> rydder halsen og genvinder fatningen.>\n\nJeg sætter pris på, at du bringer mig dette, <Name>. Der er noget, jeg gerne vil bede dig om."},
  [8475] = {n="Det Døde Ar", l="Slå 8 pestknoglerøvere ned og rapportér tilbage til Spejder Jaela ved Det Døde Ar i Eversong-skoven.", d="Den sorte jordstribe, der skærer gennem Eversong-skoven, er en evig påmindelse om dagen, da Arthæus førte Svøben ind i vores elskede by.\n\nDette ar er mere end en grim skønhedsfejl, for selv i dag bringer det Svøben fra Spøgelseslandene til Sølvmåne.\n\nGå, <Name>, og giv mine mænd en hjælpende hånd med at dræbe de tankeløse udøde, der vandrer ned ad Det Døde Ar.", p="Du er tilbage, <Name>. Har du kæmpet mod de udøde langs Det Døde Ar endnu?", c="Vi forventer ikke, at Svøben slækker på deres angreb med det første, men vi sætter stadig pris på enhver hjælp, vi får til at vogte Arret."},
  [8476] = {n="Amani-indtrængen", l="Løjtnant Morgenløber ved Fjernvandrer-tilflugtsstedet i Eversong-skoven ønsker, at du dræber 5 Amani-berserkere og 5 Amani-øksekastere.", d="Vores er ikke de store kongeriger hos menneskene og orkerne. Alt, hvad vi har tilbage af vores lande i Azeroth, ligger for det meste foran dine øjne, <Name>.\n\nIndtil vi kan nå Yderlandet, må vi forsvare det lille land, vi har, til enhver pris.\n\nVores uciviliserede naboer mod sydøst, Amani-trollene, har bestemt en anden mening om ejerskabet af disse lande. Deres daglige razziaer er noget, vi ikke længere kan tolerere. Gå til deres bebyggelser, Zeb'Vatha og Tor'Vatha, og lær dem en lektie.", p="Du finder Tor'Vatha og Zeb'Vatha mod sydøst herfra. Kom tilbage, når du har dræbt trollene.", c="Godt arbejde, <Name>. Med flere mennesker som dig vil vi snart genoprette vores lande til deres tidligere herlighed."},
  [8477] = {n="Spydsmedens hammer", l="Eftersøg Tor'Vatha mod sydøst for Fjernvandrer-tilflugtsstedet efter Spydsmeden Otembe og bring Otembes hammer til Arathel Solsmed ved Fjernvandrer-tilflugtsstedet i Eversong-skoven.", d="Amani og Blodalferne har en lang historie med gensidig antipati og åben fjendtlighed. Det forhindrer mig ikke i at værdsætte en fælle håndværkers arbejde, <Name>.\n\nJeg er stødt på stykker af Amani-våbenværk, og jeg må indrømme, at jeg er imponeret over kvaliteten af deres arbejde. Der går rygter om, at Spydsmeden Otembe svinger en magisk hammer, der er så let og velbalanceret, at den lader ham arbejde med stor behændighed og effektivitet.\n\nHvis du bringer mig dette værktøj, vil jeg bruge det til at smede et våben til dig.", p="Har du bragt mig Otembes hammer, <Name>?", c="Der er noget om snakken, <Name>. Denne hammer er let og stærk på én gang; jeg skal nok få afsluttet flere af mine uafsluttede projekter. Og selvfølgelig må du få første valg."},
  [8479] = {n="Zul'Marosj", l="Ven'jashi, trold-fangen i Tor'Vatha, ønsker, at du bringer ham Høvding Zul'Marosjs hoved. Høvding Zul'Marosj findes i Zeb'Vatha, på den anden side af Elrendar-søen.", d="Kom tættere på, mand. Vær ikke bange, Ven'jashi skal ikke gøre dig noget.\n\nVi Mørkespyd er dødsfjender af Amani ligesom jer. Deres boss Zul'Marosj er en ond trold. Han gav mig det dårlige gift og lod mig dø i denne bur.\n\nJeg er ikke bange for at dø, mand. Jeg har set døden i øjnene, og jeg griner ad hende.\n\nJeg kan ikke dø i fred endnu, mand. Ikke før Zul'Marosj også er død. Du finder ham på den anden side af søen i Zeb'Vatha. Jeg holder giften væk, indtil du bringer mig hans store grimme hoved, mand. Først da dør jeg fredeligt.", p="Bringer du mig Zul'Marosjs hoved?", c="Ja, mand. Zul'Marosj havde godt af det. Han brændte Ven'jashis landsby ned. Jeg dræbte mange Amani, før de satte mig i denne bur. Jeg gemte noget i sandet, min gave til dig nu.\n\nAh... ah, giften... den har spredt sig nu, mand. Tid til at hvile..."},
  [8480] = {n="Tabte våben", l="Bring 8 Blodalfe-våben til Velendris Hvidmor i Eversong-skoven.", d="De Elendige bliver modigere for hver dag, <Name>. De har opnået nok koordination til at angribe Solsejl-ankerpladsen.\n\nSom om det ikke var pinligt nok, blev de fleste af vores våben efterladt, da de angreb. Bring mig vores våben tilbage, så vi kan vise de ruffianer, hvem der er boss.", p="Har du samlet de tabte våben endnu?", c="Godt klaret, <Name>. Lad os vise de Elendige, hvad vi er gjort af!"},
  [8482] = {n="Belastende dokumenter", l="Bring de belastende dokumenter til Aeldon Solbrand på Falkevingepladsen i Eversong-skoven.", d="Dokumenterne indeholder detaljerede kort over forskellige strategiske bygninger i Eversong-skoven. En tegning af en arkan helligdom er også skitseret med god detaljeret præcision. Der ser ud til at være adskillige noter på et sprog, du ikke genkender.\n\nDa disse blev båret af en darnassisk spion, kunne det være en god idé at bringe dem til vagtkaptajnen - Aeldon Solbrand.", p="Har du noget til mig? Lad mig se.", c="Er du sikker på, at du fandt disse på en nattenisse? De er tydeligvis skrevet på dværgisk...\n\nUd fra det, jeg kan forstå af dette brev, er det ikke den, der skrev det, der forårsagede funktionsfejlen, men snarere blev sendt hertil som spion for at observere resultaterne af den. De kalder vores bestræbelser uansvarlige og farlige... men hvem?\n\nSelvfølgelig! Den udsending fra Jernsmede! Vi var dumme, da vi stolede på nogen, der tilhørte Alliancen!"},
  [8483] = {n="Den dværgiske spion", l="Bring Prospektor Ambolt-vagts hoved til Aeldon Solbrand på Falkevingepladsen i Eversong-skoven.", d="Hør her, <Name>. Dette er en meget delikat situation; selvom vi har identificeret spionen, kan vi ikke dræbe ham i det åbne. Vi kan heller ikke forsøge at fange ham, da risikoen for, at han slipper væk, er for stor.\n\nJeg vil have dig til at finde Prospektor Ambolt-vagt i Nordhelligdommen og dræbe ham. Gør dette på en diskret måde; vi ønsker ikke, at det spreder sig, at vi lod en spion komme ind i vores by.\n\nBring mig hans hoved som bevis. Jernsmede skal lære ikke at blande sig med Blodalferne.", p="Har du taget dig af indtrængeren?", c="Så er gerningen gjort. Fremragende arbejde.\n\nBudskabet er givet videre til spejdergeneralen, og tro mig, dværgene skal betale dyrt for deres forræderi.\n\nDu har været til stor gavn for dit folk i dag, <Name>."},
  [8486] = {n="Arkan ustabilitet", l="Ley-vogter Velania ønsker, at du dræber 5 Manaspøgelser og 5 Manasnigere.", d="Det er på tide, at den tumpe Caidanis sendte nogen herhen.\n\nJeg advarede om farerne ved at øge belastningen på Vesthelligdommen! Nu er en af vores energiomformere ødelagt, og arkane genfærd vælter ud af helligdommen!\n\nJeg har brug for, at du tager dig af disse væsener, før vi sender nogen ind for reparationer. Skynd dig!", c="Tak, <Name>. Nu hvor vi har genfærdene under kontrol, kan vi sende nogen ind for at vurdere skaden. Forhåbentlig var det ikke noget permanent."},
  [8487] = {n="Forurenet jord", l="Lærling Mirvæda ved den Østlige Helligdom i Eversong-skoven vil have dig til at samle 8 forurenede jordprøver.", d="Dette var en fuldt funktionel arkan-helligdom, før Arthæus og hans hær af Geislen besluttede at pløje sig vej gennem den på vej mod Sølvmåne.\n\nNu er den lige så nyttig for os som enhver del af Det Døde Ar. Jorden er forurenet, de udøde bliver tiltrukket af den, og energien i ley-linjerne er fuldstændig forstyrret.\n\nDet, jeg vil vide, <Name>, er om denne forurening kan vendes eller ej. Jeg vil have dig til at samle jordprøver fra området, så jeg kan studere dem. Måske kan vi med tiden få tingene tilbage til det normale.", p="Er du færdig med at samle de prøver, jeg bad om, <Name>?", c="Fremragende. Jeg vil besværge en forstærkningsbesværgelse på prøverne, så jeg tydeligere kan analysere forureningen i jorden."},
  [8488] = {n="Uventede resultater", l="Tal med Lærling Mirvæda og beskyt hende derefter mod Geislens baghold.", d="Der er noget galt, <Name>. Jeg fornemmer Geislens tilstedeværelse. Vær klar til at kæmpe mod dem!", p="Er det overstået? Er de alle væk?", c="Mine bestræbelser er håbløse, <Name>. Selve jordens natur er blevet ændret... forureningen kan ikke vendes. Tak for din hjælp. Jeg bliver nødt til at bede dig om en sidste opgave."},
  [8489] = {n="En intakt omformer", l="Bring den intakte arkan-omformer til Ley-vogter Velania.", d="Dette objekt ser ud til at være en af de arkan-omformere, Ley-vogter Velania nævnte. Den er ikke blevet beskadiget af ilden, måske kan hun finde en anvendelse for den.Du vil modtage:"},
  [8490] = {n="Drivkraft til vores forsvar", l="Placer den infunderede krystal ved den østlige runesten og beskyt den mod Geislen i 1 minut. Bring den infunderede krystal tilbage til Runevogter Derjan i Eversong-skoven for en belønning.", d="Gamle runesten drev engang en beskyttende barriere hen over Eversong-grænsen. Mange blev ødelagt under Arthæus' angreb; andre blev stjålet.\n\nAf de tre, der er tilbage, har kun denne beholdt sine kræfter. Runestenen mod øst kan måske stadig reddes.\n\nTag denne krystal og indgyd dens energi i den østlige runesten. Processen burde kun tage et minut. Vær dog på vagt, for Geislen i nærheden vil blive tiltrukket af den og vil forsøge at ødelægge den. Lad dem ikke!", p="Er det lykkedes dig at give runestenen kraft endnu, <Name>?", c="Fremragende. Forsvarene burde holde Geislen stangen lidt længere. Tak, fordi du gav os en hånd, <Name>."},
  [8491] = {n="Pelsindsamling", l="Velan Lysegeg ved Frisk Brise-landsbyen i Eversong-skoven vil have dig til at bringe ham 6 springpote-pelse.", d="Springpoterne, der lever i denne region, er kendt for deres pelse af høj kvalitet. Vi har endda set nattenisse-pak rejse til disse lande bare for at krybskytte dem.\n\nVores træfninger med Amanerne har lagt et pres på vores forsyning af udstyr, og vores spejdere har ikke meget tid til at jage pelse mere. Hvis du vil række en hånd ved at samle springpote-pelse, vil jeg gerne belønne dig med et håndlavet stykke rustning. Du vil finde springpote-snigere over alt i skovene nord for her.", p="Du er tilbage. Har du bragt pelsene?", c="Disse er perfekte, <Name>. Tag dette stykke rustning som belønning. Jeg vil kunne lave flere med de pelse, du har bragt mig."},
  [8493] = {n="Alliancen har brug for flere kobberstænger!", l="Bring 20 kobberstænger til Sergent Stenbryn ved flyvepladsen i Dun Frostbakke.", d="Er du tilbage igen, <Class>? Fremragende! Vi har stadig brug for flere stakke kobberstænger, hvis du kan skaffe dem til Ahn'Kiraj-krigsindsatsen. Vil du hjælpe os?", p="Er du tilbage igen, <Class>? Fremragende! De stænger, du har leveret indtil nu, vil virkelig hjælpe med at lave alle slags ting til krigen. Jeg ved for eksempel, at kobberet skal bruges til dele af de dampstridsvogne, der bygges, samt i en lille flåde af gyrokoptere, som vi planlægger at sætte ind, hvis tiden tillader det.\n\nLad dig ikke narre af stakkene her, for vi har stadig brug for flere kobberstænger, hvis du kan skaffe dem til Ahn'Kiraj-krigsindsatsen. Vil du hjælpe os?", c="Fremragende arbejde! At grave efter det kobber og smelte det må have været ganske et eventyr. Medmindre du købte dem på auktionshuset. Det gør ingen forskel for mig. Du fortjener ros for dit bidrag til krigsindsatsen, <Class>. Og tøv ikke med at bringe mig flere kobberstænger, hvis du har dem."},
  [8495] = {n="Alliancen har brug for flere jernstænger!", l="Bring 20 jernstænger til Korporal Kødnes ved flyvepladsen i Dun Frostbakke.", d="Tilbage så hurtigt? Hold op med at tvinge mig til at revurdere min lave mening om dig, <Class>, du får mig til at føle mig helt blød indeni. Som du kan se, har vi stadig ikke nok jernstænger til alle våbnene, rustningerne, dampstridsvognene og hvad det nu hedder, der skal bygges til billejagten. Tror du, du har det i dig til at bringe endnu en stak med tyve jernstænger med, mellem alle dine ture til Zul'Gurk, eller hvor det nu er, I unge hænger ud i dag?", p="Tilbage så hurtigt? Hold op med at tvinge mig til at revurdere min lave mening om dig, <Class>, du får mig til at føle mig helt blød indeni. Som du kan se, har vi stadig ikke nok jernstænger til alle våbnene, rustningerne, dampstridsvognene og hvad det nu hedder, der skal bygges til billejagten. Tror du, du har det i dig til at bringe endnu en stak med tyve jernstænger med, mellem alle dine ture til Zul'Gurk, eller hvor det nu er, I unge hænger ud i dag?", c="Det må være en kold dag i Brændende Stepper. Se her, det er <Name>, og han har bragt mig en gave. Tyve jernstænger! Præcis det, jeg altid har ønsket mig.\n\nMen helt seriøst, tak, <Name>. Du er en ære for dig selv og Alliancen. Kom nu ud igen og bring mere med til krigsindsatsen!"},
  [8496] = {n="Bandager til marken", l="Bring 30 tunge runestofbandager, 30 tunge silkebandager og 30 tunge magevævsbandager til Vindkalder Stolthorn ved Cenarion-fæstningen i Silitus. Du skal også bringe Logistik-opgavebriefing X for at kunne fuldføre denne opgave.", d="Vores forsyning af bandager på slagmarken er faretruende lav efter de seneste tab, vi har lidt. Skaf en portion førstehjælpsudstyr og lever det til Vindkalder Stolthorn i Cenarion-fæstningen.", p="Har du noget til mig, <Name>?", c="Lige i tide. Disse forsyninger vil redde liv, <Name>. Dit arbejde er værdsat. Her er din næste opgave."},
  [8497] = {n="Ørkenoverlevelsessæt", l="Bring 4 vandkugler, 4 kraftfulde modgifter og 4 røgede ørkenboller til Kalandrath ved kroen i Cenarion-fæstningen i Silitus. Du skal også bringe Logistik-opgavebriefing I for at kunne fuldføre denne opgave.", d="Med ankomsten af friske rekrutter til Cenarion-fæstningen følger problemet med at holde dem i live i ørkenen. Dehydrering såvel som talrige giftige væsener udgør en alvorlig trussel mod uerfarne frivillige. Saml de fornødenheder, der skal bruges til et ørkenoverlevelsessæt, og bring dem til Kalandrath i Cenarion-fæstningen.", p="Har du noget til mig?", c="Fremragende! Vi havde brug for disse, <Name>. Tak."},
  [8498] = {n="Tusmørkets kampordrer", l="Skaf Tusmørkets kampordrer og bring dem til Kommandør Mar'alit ved Cenarion-fæstningen i Silitus. Du skal også bringe Taktisk opgavebriefing X for at kunne fuldføre denne opgave.", d="Vores spejdere har rapporteret om nye kampordrer, der udstedes af Tusmørkets Hammers ledere. Ordrerne uddeles af Tusmørkets profeter under tung eskorte. Opsnap ordrerne og bring dem til Kommandør Mar'alit.", p="Har du bragt noget til mig?", c="Fremragende. Det er vigtigt at være et skridt foran fjendens næste træk. Disse oplysninger vil gøre os i stand til at forudse Tusmørkets Hammers angreb."},
  [8500] = {n="Alliancen har brug for flere tordiumstænger!", l="Bring 20 tordiumstænger til Frue Tvillingfletning ved flyvepladsen i Dun Frostbakke.", d="Det er så godt at se dig igen <Name>. Jeg håber, du har klaret dig godt. Det er rigtigt, at vi stadig har brug for tordiumstænger. Hvis du har nogen til overs, samler jeg dem ind til Ahn'Kiraj-krigsindsatsen.", p="Det er så godt at se dig igen, <Name>. Jeg håber, du har klaret dig godt. Det er rigtigt, at vi stadig har brug for tordiumstænger. Hvis du har nogen til overs, samler jeg dem ind til Ahn'Kiraj-krigsindsatsen.", c="Fremragende, <Class>! Et veludført stykke arbejde. Jeg sørger for, at stængerne kommer på pallen og ud i hænderne på de smede og ingeniører, der arbejder hårdt på at opbygge forsyningerne til vores hær. Tak igen, og hvis du støder på flere tordiumstænger, så kig forbi."},
  [8501] = {n="Mål: Bikube'Ashi-stikkere", l="Dræb 30 Bikube'Ashi-stikkere og aflever rapport til Kommandør Mar'alit ved Cenarion-fæstningen i Silitus. Du skal også bringe Kamp-opgavebriefing XII for at kunne fuldføre denne opgave.", d="Efterhånden som krigsindsatsen tiltager, udgør silithiderne i området en stadig større trussel mod vores operationer. Du er blevet udvalgt til at deltage i et angreb på Bikube'Ashi, hvor dit primære mål vil være de luftbårne Bikube'Ashi-stikkere.\n\nAflever rapport til Kommandør Mar'alit, når din opgave er udført.", p="Vil du fortælle mig noget, <Name>?", c="Fremragende arbejde, <Name>. Din andel i angrebet på Bikube'Ashi er blevet noteret."},
  [8502] = {n="Mål: Bikube'Ashi-arbejdere", l="Slå 30 Bikube'Ashi-arbejdere ihjel og aflever rapport til Kommandør Mar'alit ved Cenarion-fæstningen i Silitus. Du skal også bringe Kamp-opgavebriefing III for at kunne fuldføre denne opgave.", d="Efterhånden som krigsindsatsen tiltager, udgør silithiderne i området en stadig større trussel mod vores operationer. Du er blevet udvalgt til at deltage i et angreb på Bikube'Ashi, hvor dit primære mål vil være Bikube'Ashi-arbejderne.\n\nAflever rapport til Kommandør Mar'alit, når din opgave er udført.", p="Har du noget at fortælle mig, <Class>?", c="Fremragende arbejde, <Name>. Uden deres arbejdere vil silithiderne have svært ved at reparere skaden på deres bikubes struktur."},
  [8504] = {n="Alliancen har brug for flere kvælertang!", l="Bring 20 kvælertang til Menig Draxlemåler ved flyvepladsen i Dun Frostbakke.", d="Nå, hej igen der... hvad var det nu? Ah ja, <Name>! Er du kommet for at se, om jeg stadig har brug for mere kvælertang? Nå, så er det din heldige dag, for svaret på dette meget vigtige spørgsmål er et meget bekræftende JA! Tror du, du kunne samle tyve mere?", p="Nå, hej igen der... hvad var det nu? Ah ja, <Name>! Er du kommet for at se, om jeg stadig har brug for mere kvælertang? Nå, så er det din heldige dag, for svaret på dette meget vigtige spørgsmål er et meget bekræftende JA! Tror du, du kunne samle tyve mere?", c="Åh, du godeste, det er en ret stor læs kvælertang, du har dér. Hurtigt, lad os få det i en kasse, så det holder sig friskt. Du har gjort mig... os, Alliancen, en stor tjeneste ved at bringe den bunke. Jeg vil sørge for, at alle får at vide, at det var dig, den store <Name>, der hjalp med at vende vægtskålen i Ahn'Kiraj-krigsindsatsen med dit bidrag af kvælertang!"},
  [8506] = {n="Alliancen har brug for flere lilla lotus!", l="Bring 20 lilla lotus til Mester Natsang ved flyvepladsen i Dun Frostbakke.", d="Velkommen tilbage <Class>. Vores samling vokser, men selv nu har vi brug for flere lilla lotus. Hvis det stadig står i din magt at samle mere af urten, beder jeg dig indtrængende om at gøre det og returnere dem til mig her.", p="Velkommen tilbage, <Class>. Vores samling vokser, men selv nu har vi brug for flere lilla lotus. Hvis det stadig står i din magt at samle mere af urten, beder jeg dig indtrængende om at gøre det og returnere dem til mig her.", c="Jeg modtager med glæde dit bidrag på Alliancens vegne, <Name>. Dine bestræbelser vil direkte føre til fremstillingen af flere eliksirer og olier til støtte for vores mænd og kvinder i marken. Tak, og hvis du kommer over flere, så overvej at vende tilbage til mig."},
  [8507] = {n="Markpligt", l="Mød op til pligt ved Jernsmede-brigadens post nær Bikube'Zora. Forbered dine usignerede markpligtspapirer og skaf signerede markpligtspapirer fra Kaptajn Sortambolt, og bring dem tilbage til Vindkalder Kaldøn ved Cenarion-fæstningen i Silitus.\n\nBemærk: Helbredelse eller positive besværgelser på et medlem af Jernsmede-brigaden vil markere dig for PvP.", d="Hilsner, <Name>. Før jeg tildeler dig mere omfattende opgaver i krigen, skal du gøre din del af markpligten.\n\nDu vil finde Kaptajn Sortambolts Jernsmede-brigade uden for Bikube'Zora.\n\nRapportér til ham eller hans løjtnant, Janela Stærkhammer, og kom så tilbage til mig. Jeg har en mere avanceret opgave klar til dig.\n\nÅh, og gør os den tjeneste at holde dig væk fra Orgrimgrad-legionen. Vi har været tvunget til at holde de to styrker godt adskilt fra hinanden på grund af gensidig fjendskab.", p="Du finder Kaptajn Sortambolts styrke stationeret uden for Bikube'Zora. Tal med hans løjtnant, Janela Stærkhammer, hvis du ikke kan finde ham.", c="Meget godt, <Name>. Jeg har forberedt et sæt opgaver, der burde gøre optimal brug af dine evner.\n\nMed fortsat indsats fra dig og folk som dig vil vores fjende snart være besejret én gang for alle!\n\nHvis du har brug for en ny missionsbriefing, skal du vende tilbage til Kaptajn Sortambolt."},
  [8508] = {n="Markpligtspapirer", l="Jeg går ud fra, at du vil have de papirer underskrevet, knægt?", p="Jeg går ud fra, at du vil have de papirer underskrevet, knægt?", c="Ja, jeg regner med, at den lille træfning kan gå for markpligt i disse dage. Tag disse tilbage til Cenarion-fæstningen, jeg er sikker på, at de har et lunt job klar til dig.\n\nAf sted med dig!"},
  [8510] = {n="Alliancen har brug for flere Arthas' Tårer!", l="Bring 20 arthurs tårer til Sergentmajor Germine ved flyvepladsen i Dun Frostbakke.", d="Ok, så det ser ud til, at jeg stadig har brug for flere Arthas' Tårer. Jeg tænker, at du vil kunne finde dem i det område, hvor du samlede dem for mig sidst. Jo hurtigere vi får dem, jo hurtigere kan vi gå i gang med offensiven mod styrkerne ved Ahn'Kiraj.\n\nSkal du hjælpe os igen <Class>?", p="Ok, så det ser ud til, at jeg stadig har brug for flere arthurs tårer, <Class>. Jeg tænker, at du vil kunne finde dem i det område, hvor du samlede dem sidst. Krigsindsatsen skrider fint frem, men jo hurtigere vi får dem, jo hurtigere kan vi gå i gang med offensiven mod styrkerne ved Ahn'Kiraj.\n\nSkal du hjælpe os igen, <Name>?", c="Simpelthen fremragende, <Name>! Du er en virkelig ære for Alliancen. Jeg sørger for at få disse urter pakket væk, indtil nogen kommer for at lave dem til noget nyttigt for krigen. Du er velkommen til at kigge forbi når som helst, især hvis du har flere arthurs tårer til mig."},
  [8512] = {n="Alliancen har brug for mere let læder!", l="Bring 10 let læder til Bonnie Stenflåer ved flyvepladsen i Dun Frostbakke.", d="Godt at se dig igen <Name>. Det ser ud til, at vi har brug for mere let læder til fremstillingen af forskelligt krigsmateriel. Hvis du kunne bringe mig en stak på ti, ville det være helt perfekt.", p="Godt at se dig igen, <Name>. Det ser ud til, at vi har brug for mere let læder til fremstillingen af forskelligt krigsmateriel. Hvis du ville bringe mig en stak på ti, ville det være helt perfekt.", c="Tak for din generøse donation, <Name>. Jeg lægger dem på bunken lige nu, og om ikke længe er jeg sikker på, at de bliver lavet om til et flot sæt rustning, nogle læderlapper eller brugt til noget andet i vores forberedelser. Det lader altid til, at vi har brug for mere let læder. Kom og besøg mig snart igen."},
  [8518] = {n="Alliancen har brug for flere linnedbandager!", l="Bring 20 linnedbandager til Vagt Sølvsky ved flyvepladsen i Dun Frostbakke.", d="Altid forundres jeg over den uegennyttighed, der vises, når så mange i stedet ville vende sig mod selviskhed. <Class>, jeg har stadig brug for en række linnedbandager, før min opgave her er fuldført. Vil du hjælpe mig endnu en gang med at samle disse bandager?", p="Altid forundres jeg over den uegennyttighed, der vises, når så mange i stedet ville vende sig mod selviskhed. <Class>, jeg har stadig brug for en række linnedbandager, før min opgave her er fuldført. Vil du hjælpe mig endnu en gang med at samle disse bandager?", c="Du fortjener ros, <Name>. Mens der er dem, der ville udnytte økonomien i vores krigsfod til at fylde deres lommer i en feber af grådighed, har du gang på gang vist, at din hengivenhed over for Alliancen, og faktisk over for hele Azeroth, kommer først.\n\nElunies velsignelser være med dig altid!"},
  [8523] = {n="Alliancen har brug for flere runestofbandager!", l="Bring 20 runestofbandager til Vogter Månskygge ved flyvepladsen i Dun Frostbakke.", d="Så det er, at vi igen kommer til at drøfte presserende sager, <Class>. Endnu en gang takker jeg dig for dine tidligere bestræbelser; det er ikke alle, der ville give så uselvisk. Men der er stadig mere arbejde at gøre.\n\n<Name>, vil du endnu en gang samle runestofbandager og returnere dem til mig her?", p="Så det er, at vi igen kommer til at drøfte presserende sager, <Class>. Endnu en gang takker jeg dig for dine tidligere bestræbelser; det er ikke alle, der ville give så uselvisk. Men der er stadig mere arbejde at gøre.\n\n<Name>, vil du endnu en gang samle runestofbandager og returnere dem til mig her?", c="Dette er en god vej, vi rejser sammen, <Name>. Du er en fremragende arbejdskammerat. Endnu en gang takker jeg dig for dine bestræbelser på vegne af hele Alliancen. Kom og tal med mig igen snart."},
  [8525] = {n="Alliancen har brug for flere regnbuefinne-albacore!", l="Bring 20 regnbuefinne-albacore til Smidige Gastronom ved flyvepladsen i Dun Frostbakke.", d="Hvad! Dig igen? Nå, jeg skal være en abes onkel... bortset fra at jeg er en gnom. Smidige Gastronom for at være præcis! Så du er tilbage for at hjælpe igen, hva'? Nå, jeg kan ikke sige, at jeg bebrejder dig. Elsker du ikke lugten af al den mad? <savler>\n\nNok skæven rundt! Ud med dig og bring mig flere regnbuefinne-albacore!", p="Hvad! Dig igen? Nå, jeg skal være en abes onkel... bortset fra at jeg er en gnom. Smidige Gastronom for at være præcis! Så du er tilbage for at hjælpe igen, hva'? Nå, jeg kan ikke sige, at jeg bebrejder dig. Elsker du ikke lugten af al den mad? <savler>\n\nNok skæven rundt! Ud med dig og bring mig flere regnbuefinne-albacore!", c="Jeg vidste, at du havde det i dig, knægt. Du har det udseende af en, der ved, hvad han kan lide. Specifikt at du kan lide at behage mig og de magthavere. Og det har du, det garanterer jeg.\n\nHaha, ok, jeg får bare disse fisk gemt væk ordentligt, og så kan du og jeg tage en lille snak om, at du samler yderligere tyve albacore."},
  [8527] = {n="Alliancen har brug for mere stegt rovfugl!", l="Bring 20 stegt rovfugl til Sarah Tristfløjte ved flyvepladsen i Dun Frostbakke.", d="Hej igen <Class>. Jeg kan se, at du er meget ivrig efter alt dette. Så jeg regner med, at du vil bringe mig endnu tyve stegt rovfugl. Fint. Gør det bare. Jeg tror, jeg ser dig, når du kommer tilbage.", p="Hej igen, <Class>. Jeg kan se, at du er meget ivrig efter alt dette. Så jeg regner med, at du vil bringe mig endnu tyve stegt rovfugl? Fint. Gør det bare. Jeg tror, jeg ser dig, når du kommer tilbage.", c="Wow, du er en rigtig handlekraftig type. Du gør mig træt bare ved at se på dig. Under alle omstændigheder, tak fra Alliancen og alt det der. Jeg sørger for, at alt det døde kød bliver pakket væk. Du kan jo tjekke tilbage hos mig senere for at se, om vi stadig har brug for mere af det, selvom det begynder at stinke her, hvis du spørger mig."},
  [8529] = {n="Alliancen har brug for flere plettet gultail!", l="Bring 20 plettet gultail til Jægerinde Hurtigflod ved flyvepladsen i Dun Frostbakke.", d="Hvis du stadig er villig, vil jeg gerne sende dig ud for at bringe endnu et læs plettet gultail, <Name>. Jeg forestiller mig, at du med ekspertisen fra første gang burde kunne få denne fangst meget hurtigere og lettere. Er du med?", p="Hvis du stadig er villig, vil jeg gerne sende dig ud for at bringe endnu et læs plettet gultail, <Name>. Jeg forestiller mig, at du med ekspertisen fra første gang burde kunne få denne fangst meget hurtigere og lettere. Er du med?", c="Du er et sandt medlem af Alliancen, <Name>. Dine bestræbelser vil ikke gå upåagtet hen, og de bliver heller ikke uværdsat. Og tak for at tilberede fisken også. Jeg sørger for, at de bliver opbevaret ordentligt, og så må jeg opdatere mit tal. Hver en bringer os et lille skridt tættere på at nå vores mål."},
  [8531] = {n="Alliancen har brug for flere svidde kernesten!", l="Bring 50 svidde kernesten til Kommandør Stærkhammer ved flyvepladsen i Dun Frostbakke.", d="Tak for at vende tilbage, <Name>. Hvis du og dine venner stadig har det i jer, skal I vende tilbage til Lavakernen og fortsætte jeres indsamling af svidde kernesten. Hvad siger du?"},
  [8533] = {n="Horden Mangler Flere Kobberstænger!", l="Bring 20 kobberstænger til Minearbejder Krumvel i Durdotar.", d="Allerede tilbage? Du bliver en rigtig minearbejder på ingen tid <Class>. Du kender jo rutinen; jeg skal bruge at du tager ud, graver en hel masse kobbermalm op, smelter det til stænger og bringer det tilbage til mig her. Jeg ved at det er noget du kan klare, spørgsmålet er bare, om du har lyst?", p="Allerede tilbage? Du bliver en rigtig minearbejder på ingen tid, <Class>. Du kender jo rutinen; jeg skal bruge at du tager ud, graver en hel masse kobbermalm op, smelter det til stænger og bringer det tilbage til mig her. Jeg ved at det er noget du kan klare, spørgsmålet er bare, om du har lyst?", c="Du har endnu en gang bevist dig over for mig, <Class>. Jeg sørger for at kobberet bliver brugt på rette tid. Men lige nu skal jeg have kobberstængerne op på pallen og talt op. Hvis du stadig har lyst, kunne jeg nok bruge din hjælp til at samle endnu flere kobberstænger."},
  [8534] = {n="Bikube'Zora-spejderrapporten", l="Kontakt Cenarion-spejder Azenel inde i Bikube'Zora og bring Bikube'Zora-spejderrapporten tilbage til Vindkalder Stolthorn i Cenarion-fæstningen. Du skal også medbringe Taktisk opgave-briefing VI for at kunne fuldføre denne opgave.", d="Vi har sendt vores bedste spejdere dybt ind i silitidernes boer for at indsamle efterretninger. Spejder Azenel har holdt øje med silitidernes bevægelser i Bikube'Zora i flere dage nu. Find hende og få en skriftlig rapport. Vi skal kunne handle på oplysningerne så hurtigt som muligt, <Name>.", p="Du finder Spejder Azenel inde i Bikube'Zora. Skynd dig, <Name>! Tiden er afgørende.", c="Din indsats er højt værdsat, <Name>. Jeg læser disse spejderrapporter med det samme, så er du velkommen til at gå videre til din næste opgave."},
  [8535] = {n="Hvidgrå tempelridder", l="Fremkald og nedlæg en Hvidgrå tempelridder og rapportér tilbage til Bor Vildmanke i Cenarion-fæstningen. Du skal også medbringe Taktisk opgave-briefing IV for at kunne fuldføre denne opgave.", d="Tusmørkets Hammer og de elementære adelsmænd, de tilbeder, udgør en formidabel trussel mod vores operationer i Silitus. Med de nye fjender vi står over for inde i Ahn'Kiraj, har vi ikke råd til at sænke vagten over for fjenderne udenfor.\n\nFind en måde at fremkalde og tilintetgøre en Hvidgrå tempelridder og rapportér til Bor Vildmanke.", p="Er din opgave overstået endnu, <Name>?", c="Godt gået, <Name>. Her er din næste opgave."},
  [8536] = {n="Jordvæsen-tempelridder", l="Fremkald og nedlæg en Jordvæsen-tempelridder og rapportér tilbage til Bor Vildmanke i Cenarion-fæstningen. Du skal også medbringe Taktisk opgave-briefing III for at kunne fuldføre denne opgave.", d="Tusmørkets Hammer og de elementære adelsmænd, de tilbeder, udgør en formidabel trussel mod vores operationer i Silitus. Med de nye fjender vi står over for inde i Ahn'Kiraj, har vi ikke råd til at sænke vagten over for fjenderne udenfor.\n\nFind en måde at fremkalde og tilintetgøre en Jordvæsen-tempelridder og rapportér til Bor Vildmanke.", p="Er din opgave overstået endnu, <Name>?", c="Godt gået, <Name>. Her er din næste opgave."},
  [8537] = {n="Karmosinrød tempelridder", l="Fremkald og nedlæg en Karmosinrød tempelridder og rapportér tilbage til Bor Vildmanke i Cenarion-fæstningen. Du skal også medbringe Taktisk opgave-briefing II for at kunne fuldføre denne opgave.", d="Tusmørkets Hammer og de elementære adelsmænd, de tilbeder, udgør en formidabel trussel mod vores operationer i Silitus. Med de nye fjender vi står over for inde i Ahn'Kiraj, har vi ikke råd til at sænke vagten over for fjenderne udenfor.\n\nFind en måde at fremkalde og tilintetgøre en Karmosinrød tempelridder og rapportér til Bor Vildmanke.", p="Er din opgave overstået endnu, <Name>?", c="Godt gået, <Name>. Her er din næste opgave."},
  [8538] = {n="De Fire Hertuger", l="Find en måde at fremkalde og nedlægge Hertug af Gløder, Hertug af Dybderne, Hertug af Zefyr og Hertug af Skår og rapportér tilbage til Kommandør Mar'alit i Cenarion-fæstningen. Du skal også medbringe Taktisk opgave-briefing V for at kunne fuldføre denne opgave.", d="Forbindelserne mellem Tusmørkets Hammer og Afgrundsrådet viser sig at være vigtigere, end vi havde forventet.\n\nVi mener, at de elementære adelsmænd kendt som Afgrundshertugerne er en af de primære kræfter, der organiserer Tusmørkets Hammers kultister. Find en måde at lokke de fire Afgrundshertuger ind i vores eksistensplan og tilintetgør dem!\n\nDin hengivenhed og dygtighed i tidligere opgaver har fået os til at vælge dig til netop denne opgave. Vi er sikre på, at du vil lykkes med dette forehavende.", p="Er din opgave overstået endnu, <Name>?", c="Du har i dag opnået en stor bedrift for vores sag, <Name>. Du har besejret nogle af vores mest magtfulde fjender. For det roser jeg dig meget."},
  [8539] = {n="Mål: Bikube'Zora-bistoksøstrene", l="Nedlæg 30 Bikube'Zora-bistoksøstre og rapportér tilbage til Kommandør Mar'alit i Cenarion-fæstningen i Silitus. Du skal også medbringe Kamp-opgave-briefing V for at kunne fuldføre denne opgave.", d="Forstærkninger er blevet tilkaldt for at deltage i angrebet på Bikube'Zora. Du er blevet udvalgt til at gå efter Bikube'Zora-bistoksøstrene. Rapportér tilbage til Kommandør Mar'alit, når du har udført din opgave.", p="Har du noget at fortælle mig, <Class>?", c="Fremragende arbejde, <Name>. Du er en værdig allieret."},
  [8540] = {n="Støvler til vagten", l="Bring 3 Udsmykkede Mithril-støvler til Kaptajn Vish Kozus, Vagtkaptajn i Cenarion-fæstningen i Silitus. Du skal også medbringe Logistik-opgave-briefing II for at kunne fuldføre denne opgave.", d="Den monterede afdeling af Cenarion-fæstningens vagt har ikke nok udsmykkede mithril-støvler. Skaf en portion og lever dem straks til Kaptajn Vish Kozus i Cenarion-fæstningen.", p="Har du noget til mig?", c="Fremragende. Vi havde brug for disse, <Name>. Godt arbejde."},
  [8541] = {n="Malesten til vagten", l="Bring 10 Tætte Malesten, 10 Massive Malesten og 10 Tunge Malesten til Kaptajn Vish Kozus, Vagtkaptajn i Cenarion-fæstningen i Silitus. Du skal også medbringe Logistik-opgave-briefing III for at kunne fuldføre denne opgave.", d="Cenarion-fæstningens vagt mangler malesten. Skaf en portion og lever dem straks til Kaptajn Vish Kozus i Cenarion-fæstningen.", p="Har du noget til mig?", c="Fremragende. Vi havde brug for disse, <Name>. Godt arbejde."},
  [8543] = {n="Horden Mangler Flere Tinstænger!", l="Bring 20 tinstænger til Fodsoldat Maug i Durdotar.", d="Meget godt, jeg kan se, at du er seriøs omkring krigen. Jeg er lidt nervøs over at vente på, at den starter, og det betyder, at jeg bliver vred, hvis du ikke begynder at bringe varerne hurtigere. Måske kan jeg bare øve mig på dig i stedet.\n\nHar! Måske ikke, for hvem skulle så bringe mig tinstængerne tilbage?", p="Meget godt, jeg kan se, at du er seriøs omkring krigen. Jeg er lidt nervøs over at vente på, at den starter, og det er jeg sikker på, at du også er, <Class>. Det bliver glorværdigt, når det begynder. Horden, der løber hen over Silitus-ørkenens sand med våben i hånden og stormer ind i insektmasserne. Stor ære vil der være at vinde den dag for alle!\n\nHar! Men først har vi brug for flere tinstænger. Sjovt, hvordan sådan en lille ting kan gøre en så stor forskel, synes du ikke?", c="Throm'ka, <Name>. Du ærer mig og Horden med dine tinstænger. Jeg lægger dem på stakken, og så kommer de og laver ting af dem. Og når det hele er gjort, drager vi i krig og viser de ynkelige Alliancefolk, hvordan man kæmper mod insekterne.\n\nNu skal du bringe mig flere tinstænger tilbage!"},
  [8544] = {n="Erobrerens skulderbeskyttere", l="Bring de Qiraji-bindinger af Kommando, 2 Idoler af Nat, 5 Stenskarabæer og 5 Lerskarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå neutralt ry hos Nosdormus Yngel for at kunne fuldføre denne opgave.", d="Det siges blandt os, at den udsmykkede skulderbeskyttelse, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så former jeg dem til et sæt skulderplader, der er mere frygtindgydende end selv Nefarians vinger!", p="Har du samlet de komponenter, jeg har brug for?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender smeder jeg disse skulderplader til dig, dødelige. Må de give dig den beskyttelse, du behøver, og må synet af dem slå frygt i vores fjender."},
  [8546] = {n="Horden Mangler Flere Mithril-stænger!", l="Jo, jeg er glad for, at du er her, mon. Du hjalp mig før, og nu har jeg brug for din hjælp igen. Vi leder stadig efter at få flere mithril-stænger ind til krigsindsatsen; vi skal bygge masser af rustning og våben og sådan noget til at smadre de kryb ved Ahn'Kiraj.\n\nSå hvis du er en sand ven, så bringer du mig flere stakke mithril-stænger. Jeg tager alt, du har, indtil vi når vores kvote. Har du nogle til mig nu?", p="Jo, jeg er glad for, at du er her, mon. Du hjalp mig før, og nu har jeg brug for din hjælp igen. Vi leder stadig efter at få flere mithril-stænger ind til krigsindsatsen; vi skal bygge masser af rustning og våben og sådan noget til at smadre de kryb ved Ahn'Kiraj.\n\nSå hvis du er en sand ven, så bringer du mig flere stakke mithril-stænger. Jeg tager alt, du har, indtil vi når vores kvote. Har du nogle til mig nu?", c="Det var godt arbejde, <Name>! Tyve stænger mere bringer os så meget tættere på målet og skaffer os mere krigsmateriel. Jeg sørger for, at de bliver lagt væk. Og hvis du får endnu en stak mithril-stænger, mon, så sørg for at bringe dem herhen til mig."},
  [8547] = {n="Velkommen!", l="Bring Falkevingepladsens gavekupon til Marsilla Morgenstjerne på Falkevingepladsen.", d="Velkommen til Warcraft-verdenen!\n\nSom en særlig tak for at købe Warcraft-verdenens Samlerudgave, skal du aflevere denne gavekupon til Marsilla Morgenstjerne på Falkevingepladsen. Du får så en gave: en lille ledsager, der kan følge dig på din jagt efter eventyr og ære.\n\nTak igen, og nyd dit ophold i Warcraft-verdenen!"},
  [8548] = {n="Frivilligt Kampudstyr", l="Bring 5 Cenarion-kampemblemer, 3 Cenarion-logistikemblemer og 7 Cenarion-taktikemblemer til Vargus i Cenarion-fæstningen i Silitus. Du skal også opnå venligt ry hos Cenarion-kredsen for at kunne fuldføre denne opgave.", d="De emblemer, du indsamler ved at udføre kamp-, logistik- og taktikopgaver for Cenarion-fæstningen, er mere end bare pynt, <Name>.\n\nDet vil være klogt at gemme dem. Når du beviser din loyalitet over for vores organisation, kan jeg tilbyde dig noget af det udstyr, vi forbeholder vores nærmeste allierede, til gengæld for disse emblemer.", p="Det er i vores interesse at holde vores mest loyale allierede godt udrustede, <Name>.", c="Godt arbejde, <Name>. Modtag venligst dette på vegne af Cenarion-kredsen. Du har med rette fortjent det, ven!"},
  [8550] = {n="Horden Mangler Mere Fredsblomst!", l="Hej igen, <Name>. Jeg er glad for, at du ønsker at tale med mig igen om vores uophørlige behov for fredsblomst. Krigsindsatsen fortsætter, og med den vores produktion af eliksirer og trylledrikke til at hjælpe i kampene, der venter.\n\nVil du hjælpe os igen, <Class>? Jeg har brug for samme mængde fredsblomst som før, så hvis du kan samle det og bringe det tilbage til mig her, ville jeg være meget taknemmelig. Hvis du naturligvis allerede har det på dig, vil jeg meget gerne modtage det fra dig nu.", p="Hej igen, <Name>. Jeg er glad for, at du ønsker at tale med mig igen om vores uophørlige behov for fredsblomst. Krigsindsatsen fortsætter, og med den vores produktion af eliksirer og trylledrikke til at hjælpe i kampene, der venter.\n\nVil du hjælpe os igen, <Class>? Jeg har brug for samme mængde fredsblomst som før, så hvis du kan samle det og bringe det tilbage til mig her, ville jeg være meget taknemmelig. Hvis du naturligvis allerede har det på dig, vil jeg meget gerne modtage det fra dig nu.", c="Tak for din fortsatte indsats, <Name>. Du bringer stor ære over dig selv og dine forfædre med din uegennyttige gavmildhed, og det skal kendes af alle! Jeg vil gemme disse urter, så de forbliver friske, indtil de bliver nødvendige. Endnu en gang afslører du Hordens sande ånd: kampen for at overvinde, og løftet om, at vi sammen kan gøre det."},
  [8559] = {n="Erobrerens Benskinner", l="Bring de Qiraji-bindinger af Kommando, 2 Idoler af Krig, 5 Elfenbensskarabæer og 5 Guldskarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver også neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mest magtfulde qiraji besidder genstande af en sådan styrke, at de ville få selv en drage til at tøve.\n\nBring mig de qiraji-bindinger af kommando og andre mindre komponenter, så skaber jeg et sæt kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har klaret dig godt, <Name>. Du har bevist, at du ikke er en almindelig dødelig.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de modbydelige qiraji."},
  [8560] = {n="Erobrerens Benskinner", l="Bring Uros intakte skind, 2 Idoler af Død, 5 Bronzeskarabæer og 5 Elfenbensskarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal også opnå venligt ry hos Nosdormus Yngel for at kunne fuldføre denne opgave.", d="Du søger at bevise din værdi over for mit folk, dødelige? Meget vel, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk magt. Det rygtes, at han blev skabt af den Gamle Gud selv som en parodi på livet.\n\nHans hud er unaturlig... tyk, næsten uigennemtrængelig, men alligevel fleksibel, og den lader ham bevæge sig med hurtighed og ynde som en langt mindre skabning.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skaber jeg dig benbeskyttere af stor kraft.", p="Har du bragt de komponenter, jeg skal bruge, <Name>?", c="Ja... ormens hud vil give et fremragende beskyttende lag. Kombineret med de stærkeste dele fra de qiraji, vi har nedlagt på vores vej hertil, bør dette blive et formidabelt stykke rustning. Må det hjælpe dig med at møde de usigelige rædsler, der venter indenfor!"},
  [8561] = {n="Erobrerens Krone", l="Bring Vek'nilashs Pandebånd, 2 Idoler af Solen, 5 Stenskarabæer og 5 Krystalskarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå venligt ry hos Nosdormus Yngel for at kunne fuldføre denne opgave.", d="De Tvillingekejsere... deres uophørlige hvisken tager langsomt sin told af min fornuft. De håner mig, vidende om at jeg ikke kan træde længere ind i deres domæne for at redde min bror Arigos.\n\nI mine visioner ser jeg deres monstrøse ansigter pyntet med magtfulde kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til noget, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg har brug for, <Name>. Så giver jeg dig et hovedstykke af uovertruffen magt.", p="Bragte du mig de ting, jeg bad om, <Name>?", c="Du har klaret det! Hviskene fra De Tvillingekejsere er ophørt.\n\nTag dette som belønning. Blot synet af det vil slå frygt i qiraji-hjerterne... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8562] = {n="Erobrerens Brystplade", l="Bring Den Gamle Guds Skal, 2 Idoler af Krig, 5 Sølvskarabæer og 5 Knogleskarabæer til Vetsera inde i Ahn'Kiraj. Du skal også opnå æret ry hos Nosdormus Yngel for at kunne fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin søvn under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azeroth, kan komme om få dage eller om år; tid har ingen betydning for væsener af hans magt.\n\nNår stjernerne er gunstige, vil han slå ud mod alle levende væsener med forfærdelig vrede. Du skal finde ham, før det sker, og finde en måde at sætte en stopper for hans eksistens.\n\nGør dette, og bring mig et stykke af hans skal. Så skal jeg give dig rustning, som ingen dødelig nogensinde har båret... rustning, der passer til den, der har dræbt en gud!", p="I hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i søvn.", c="Jeg havde ikke forventet, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, der er større end de fleste udødelige væseners.\n\nVed at nedlægge Ce'Tun har du ikke blot reddet hele Azeroth, du har også vippet skalaen i kosmiske begivenheder ud over din forståelse.\n\nModtag denne brystplade som et symbol på den ære og byrde, der vil følge som en konsekvens af dine handlinger.\n\nMå dens kraft hjælpe dig i de udfordringer, der venter dig, gudedræber!"},
  [8563] = {n="Hekseklog-træning", l="Tal med Fremkalder Teli'Larien, klassetræneren for hekseklogs, inde i Solspiret på Solvandrer-øen.", d="Når du avancerer inden for din klasse, vil du gerne udnytte den træning, din klassetræner kan give dig. For unge hekseklogs her på Solvandrer-øen er din træner Fremkalder Teli'Larien. Tal med Fremkalder Teli'Larien og se, hvilken træning han har tilgængelig for dig. Det, han vil lære dig, koster penge, så tag noget mønt med.\n\nDin træner - ligesom alle trænerne på Solvandrer-øen - befinder sig inde i Solspiret på det nederste niveau.", c="<Name> - dit navn har nået mine ører som en, der søger en mester i de veje, som hører til <Class>. Du ser dygtig nok ud, men jeg søger mere end blot udseende hos mine elever. Du skal være klar til at dykke ned, hvor andre frygter at kigge, for at opnå din magt. Jeg vil lære dig, men jeg vil ikke tolerere fiasko.\n\nDer vil være pengemæssige omkostninger forbundet med din træning, men du bør være mere bekymret for den pris, dit sind er villigt til at betale. Hvis du er klar, begynder vi."},
  [8564] = {n="Præsttræning", l="Tal med Matrone Arena, klassetræneren for præster, inde i Solspiret på Solvandrer-øen.", d="Når du avancerer inden for din klasse, vil du gerne udnytte den træning, din klassetræner kan give dig. For unge præster her på Solvandrer-øen er din træner Matrone Arena. Tal med matronen og se, hvilken træning hun har tilgængelig for dig. Det, hun vil lære dig, koster penge, så tag noget mønt med.\n\nMatrone Arena - ligesom alle trænerne på Solvandrer-øen - befinder sig inde i Solspiret på det nederste niveau.", c="Velkommen, <Name> - jeg er Matrone Arena. Jeg tilbyder mine tjenester til dem, der ønsker at lære de veje, som hører til <Class>. Sådan en vej misforstås ofte som en vej til pacifisme; for os blodalfer kunne det ikke være længere fra sandheden. Mens vi både læger ben og ånd, fungerer vi også som en næve af hævn for dem, der overtræder mod os.\n\nJeg vil træne dig, men alt, hvad jeg beder om, er, at du dækker de træningsomkostninger, der måtte opstå, og at du lærer med et åbent sind. Hvis du accepterer dette, kan vi begynde."},
  [8572] = {n="Veteranens Kampudstyr", l="Bring 7 Cenarion-kampemblemer, 4 Cenarion-logistikemblemer og 4 Cenarion-taktikemblemer til Vargus i Cenarion-fæstningen i Silitus. Du skal også opnå æret ry hos Cenarion-kredsen for at kunne fuldføre denne opgave.", d="De emblemer, du indsamler ved at udføre kamp-, logistik- og taktikopgaver for Cenarion-fæstningen, er mere end bare pynt, <Name>.\n\nDet vil være klogt at gemme dem. Når du beviser din loyalitet over for vores organisation, kan jeg tilbyde dig noget af det udstyr, vi forbeholder vores nærmeste allierede, til gengæld for disse emblemer.", p="Det er i vores interesse at holde vores mest loyale allierede godt udrustede, <Name>.", c="Godt arbejde, <Name>. Modtag venligst dette på vegne af Cenarion-kredsen. Du har med rette fortjent det, ven!"},
  [8573] = {n="Mesterens Kampudstyr", l="Bring 15 Cenarion-kampemblemer, 20 Cenarion-logistikemblemer, 20 Cenarion-taktikemblemer og 1 Cenarus' Mærke til Vargus i Cenarion-fæstningen i Silitus. Du skal også opnå ophøjet ry hos Cenarion-kredsen for at kunne fuldføre denne opgave.", d="De emblemer, du indsamler ved at udføre kamp-, logistik- og taktikopgaver for Cenarion-fæstningen, er mere end bare pynt, <Name>.\n\nDet vil være klogt at gemme dem. Når du beviser din loyalitet over for vores organisation, kan jeg tilbyde dig noget af det udstyr, vi forbeholder vores nærmeste allierede, til gengæld for disse emblemer.", p="Det er i vores interesse at holde vores mest loyale allierede godt udrustede, <Name>.", c="Godt arbejde, <Name>. Modtag venligst dette på vegne af Cenarion-kredsen. Du har med rette fortjent det, ven!"},
  [8574] = {n="Standhaftig Kampudstyr", l="Bring 15 Cenarion-kampemblemer, 20 Cenarion-logistikemblemer, 17 Cenarion-taktikemblemer og 1 Remulos' Mærke til Vargus i Cenarion-fæstningen i Silitus. Du skal også opnå respekteret ry hos Cenarion-kredsen for at kunne fuldføre denne opgave.", d="De emblemer, du indsamler ved at udføre kamp-, logistik- og taktikopgaver for Vindkalder Stolthorn, er mere end bare pynt, <Name>.\n\nDet vil være klogt at gemme dem. Når du beviser din loyalitet over for vores organisation, kan jeg tilbyde dig noget af det udstyr, vi forbeholder vores nærmeste allierede, til gengæld for disse emblemer.", p="Det er i vores interesse at holde vores mest loyale allierede godt udrustede, <Name>.", c="Godt arbejde, <Name>. Modtag venligst dette på vegne af Cenarion-kredsen. Du har med rette fortjent det, ven!"},
  [8581] = {n="Horden Mangler Mere Ildblomst!", l="Pele'kejki ved, du kommer for at hjælpe. Bring masser af ildblomst og gør ham meget glad. Pele'kejki kan måske lave store bomber med ildblomst. Smid dem på insekterne fra hans flagermus over Ahn'Kiraj, når krigen kommer. Men Pele'kejki har brug for mere ildblomst, <Class>!\n\nDu skal bringe Pele'kejki den ildblomst, og hurtigt nu. Kom tilbage med mindst lige så meget som sidst, så bliver Pele'kejki glad.", p="Pele'kejki ved, du kommer for at hjælpe. Bring masser af ildblomst og gør ham meget glad. Pele'kejki kan måske lave store bomber med ildblomst. Smid dem på insekterne fra hans flagermus over Ahn'Kiraj, når krigen kommer. Men Pele'kejki har brug for mere ildblomst, <Class>!\n\nDu skal bringe Pele'kejki den ildblomst, og hurtigt nu. Kom tilbage med mindst lige så meget som sidst, så bliver Pele'kejki glad.", c="Er det ikke en vittighed, <Class>? Du bringer Pele'kejki ildblomst så hurtigt? Pele'kejki tæller dem op lige nu, mon! Du gør Pele'kejki så glad, at han fortæller alle, at <Name> er den bedste ildblomstsamler nogensinde! Pele'kejki kan ikke vente på, at krigen starter. Nu lyser vi virkelig op over Silitus, ikke, bruddah?!"},
  [8583] = {n="Horden Har Brug for Mere Lilla Lotus!", l="Det ser faktisk ud til, at vi har brug for endnu mere lilla lotus, <Class>. Mine egne studier har endnu ikke fundet en ny nyttig anvendelse for urten, men der findes gamle, velafprøvede metoder, der endnu ikke er taget i brug.\n\nJeg skal bede dig om endnu engang at tage ud i marken og samle mindst tyve prøver af lilla lotus. Bring dem tilbage til mig her.", p="Det ser faktisk ud til, at vi har brug for endnu mere lilla lotus, <Class>. Mine egne studier har endnu ikke fundet en ny nyttig anvendelse for urten, men der findes gamle, velafprøvede metoder, der endnu ikke er taget i brug.\n\nJeg skal bede dig om endnu engang at tage ud i marken og samle mindst tyve prøver af lilla lotus. Bring dem tilbage til mig her.", c="Fremragende og præcist arbejde, <Name>. Din flid skal roses, ligesom din hurtighed. Jeg vil personligt sørge for, at ingen af disse lilla lotusser går til spilde.\n\nTak igen, og skulle du komme forbi med flere lilla lotusser, så tøv ikke med at bringe dem til mig med største hast."},
  [8589] = {n="Horden Har Brug for Mere Tungt Læder!", l="Det er sandt, <Class>, jeg har stadig brug for mere tungt læder. Anmodningerne fra generalerne og deres kvartermestre synes uendelige. Og det er ingenting mod, hvad zeppelinmestrene efterspørger!\n\nJeg skal have min kvote samlet på et blink. <Name>, bring mig flere stakke tungt læder, så hurtigt du kan!", p="Det er sandt, <Class>, jeg har stadig brug for mere tungt læder. Anmodningerne fra generalerne og deres kvartermestre synes uendelige. Og det er ingenting mod, hvad zeppelinmestrene efterspørger!\n\nJeg skal have min kvote samlet på et blink. <Name>, bring mig flere stakke tungt læder, så hurtigt du kan!", c="Du da mon, mon! Tusind tak for det tunge læder. Hver lille smule bringer os et skridt nærmere. Jeg lægger dem bare op i en stabel, så de andre læderarbejdere kan gå i gang med dem.\n\nTak igen, <Name>, og hvis du støder på flere stakke tungt læder, ved du, hvor du finder mig."},
  [8591] = {n="Horden Har Brug for Mere Tykt Læder!", l="<Class>, som du kan se, mangler jeg stadig at samle mere tykt læder. Endnu engang beder jeg om din hjælp med denne opgave, og jeg lover, at hvis du fuldfører den, vil din indsats blive anerkendt.\n\nTiden er knap! Vend tilbage til mig med det tykke læder, så vi kan færdiggøre vores forberedelser og drage i krig, helt!", p="<Class>, som du kan se, mangler jeg stadig at samle mere tykt læder. Endnu engang beder jeg om din hjælp med denne opgave, og jeg lover, at hvis du fuldfører den, vil din indsats blive anerkendt.\n\nTiden er knap! Vend tilbage til mig med det tykke læder, så vi kan færdiggøre vores forberedelser og drage i krig, helt!", c="Du gjorde det, <Name>, det vidste jeg, du ville! Endnu en gang tak på hele Hordens vegne. Din indsats er blevet bemærket og sættes stor pris på. Og hvis du finder dig selv med mere tykt læder, du gerne vil donere, så bring det til mig her.\n\nLokk'tar Ogar, <Class>!"},
  [8592] = {n="Orakelets Tiara", l="Bring Vek'nilasks Pandebånd, 2 Idoler af Salvie, 5 Sølvskarabæer og 5 Knogleskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hviskenen tærer langsomt på mit sind. De spotter mig, vel vidende at jeg ikke kan trænge længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med mægtige kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til noget, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg behøver, <Name>. Jeg vil give dig et hovedstykke af uovertruffen kraft.", p="Bragte du de komponenter, jeg bad om, <Name>?", c="Du har lykkedes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil indjage frygt i Qirajiernes hjerter... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8593] = {n="Orakelets Bukser", l="Bring Uros Intakte Skind, 2 Idoler af Liv, 5 Guldskarabæer og 5 Lerskarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal desuden opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for min slags, dødelige? Meget godt, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Det siges, at han blev skabt af Den Gamle Gud selv som en parodi på livet.\n\nHans hud er unaturlig... tyk, næsten uigennemtrængelig, men alligevel fleksibel, og den lader ham bevæge sig med hastigheden og elegancen hos et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg smede dig benbeskyttere af stor kraft.", p="Bragte du de komponenter, jeg behøver, <Name>?", c="Ja... ormens hud vil udgøre et fortrinligt beskyttende lag. Sammen med de stærkeste dele fra de Qiraji, vi har tilintetgjort på vejen hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at stå imod de ubeskrivelige rædsler, der venter indenfor!"},
  [8594] = {n="Orakelets Skulderkappe", l="Bring Qiraji-bindingerne af Kommando, 2 Idoler af Genfødsel, 5 Sølvskarabæer og 5 Elfenbensskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Neutral ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Blandt os siges det, at den udsmykkede skulderrustning, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så skal jeg forme dem til et par skulderplader, der er mere frygtindgydende end selveste Nefarians vinger!", p="Har du samlet de komponenter, jeg behøver?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender laver jeg disse skulderplader til dig, dødelige. Må de give dig den beskyttelse, du behøver, og må synet af dem indjage frygt i vores fjender."},
  [8595] = {n="Dødelige Mestre", l="At dræbe én Qiraji-lord er en bemærkelsesværdig bedrift for en dødelig, <Name>. De er dog talrige og mægtige. Fortsæt med at besejre dem for at bevise din værdi som vores mester.", p="At dræbe én Qiraji-lord er en bemærkelsesværdig bedrift for en dødelig, <Name>. De er dog talrige og mægtige. Fortsæt med at besejre dem for at bevise din værdi som vores mester.", c="Du tjener os fortsat godt, <Name>. Vores pagt står fast."},
  [8596] = {n="Orakelets Fodbind", l="Bring Qiraji-bindingerne af Kommando, 2 Idoler af Død, 5 Bronzeskarabæer og 5 Guldskarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver desuden Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mægtigste qiraji bærer genstande af en sådan kraft, at selv en drage ville tøve.\n\nBring mig Qiraji-bindingerne af kommando og andre mindre komponenter, så skaber jeg et par kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har klaret dig godt, <Name>. Du har bevist, at du ikke er en almindelig dødelig.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de forbandede Qiraji."},
  [8601] = {n="Horden Har Brug for Mere Barsk Læder!", l="Forberedelserne til den forestående krig ved Ahn'Kiraj skrider frem, <Class>. Men for at sikre, at vi ikke halter bagefter, eller i det mindste at det ikke er mig, der får os til at halte bagefter, vil jeg bede dig om at bringe endnu en stabel barsk læder. Din hurtige opmærksomhed i denne sag vil blive stærkt værdsat, <Name>.", p="Forberedelserne til den forestående krig ved Ahn'Kiraj skrider frem, <Class>. Men for at sikre, at vi ikke halter bagefter, eller i det mindste at det ikke er mig, der får os til at halte bagefter, vil jeg bede dig om at bringe endnu en stabel barsk læder. Din hurtige opmærksomhed i denne sag vil blive stærkt værdsat, <Name>.", c="Øvelse, øvelse, øvelse. En velslebet kniv og evnen til at bruge den vil tage dig langt i denne verden, <Name>. Det ser ud til, at kanterne på disse skind er bedre end sidst. Købte du en ny kniv?\n\nUnder alle omstændigheder takker vi dig for din indsats. Din donation er blevet noteret, og den vil blive brugt godt, det kan jeg forsikre dig om. Skulle du komme i besiddelse af mere barsk læder, så husk at komme tilbage og tale med mig, for jeg får nok brug for det."},
  [8602] = {n="Stormkalderens Skulderplader", l="Bring Qiraji-bindingerne af Dominans, 2 Idoler af Liv, 5 Guldskarabæer og 5 Krystalskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Neutral ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Blandt os siges det, at den udsmykkede skulderrustning, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så skal jeg forme dem til et par skulderplader, der er mere frygtindgydende end selveste Nefarians vinger!", p="Har du samlet de komponenter, jeg behøver?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender laver jeg disse skulderplader til dig, dødelige. Må de give dig den beskyttelse, du behøver, og må synet af dem indjage frygt i vores fjender."},
  [8603] = {n="Orakelets Messehagel", l="Bring Den Gamle Guds Skal, 2 Idoler af Død, 5 Stenskarabæer og 5 Krystalskarabæer til Vedsera inde i Ahn'Kiraj. Du skal desuden opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin søvn under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azeroth, kan komme om dage eller år; tiden betyder intet for væsner af hans kraft.\n\nNår stjernerne står gunstigt, vil han slå ud mod alle levende væsner med forfærdelig vrede. Du må finde ham, før det sker, og finde en måde at bringe hans eksistens til ende på.\n\nGør dette, og bring mig et stykke af hans skal. Jeg skal give dig rustning, som intet dødeligt væsen nogensinde har båret... rustning, der passer til den, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i søvn.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, der er større end de fleste udødelige væseners.\n\nVed at dræbe Ce'Tun har du ikke blot reddet hele Azeroth, du har også vippet de kosmiske begivenheders vægtskål ud over din forståelse.\n\nModtag disse messehagler som et symbol på den herlighed og byrde, der følger med dine handlinger.\n\nMå deres kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8605] = {n="Horden Har Brug for Mere Uldbandager!", l="Godt at se dig igen, <Class>. Vi arbejder stadig på forberedelserne her til krigsindsatsen, og jeg kan stadig bruge al den hjælp, du kan yde med at samle uldbandager. Enhver hjælp er højt værdsat. Jeg håber blot, at vores indsats bliver god nok. Jeg har mistet for mange ædle sjæle på gårsdagens slagmarker til ikke at gøre alt i min magt for at sikre, at det ikke sker igen.", p="Godt at se dig igen, <Class>. Vi arbejder stadig på forberedelserne her til krigsindsatsen, og jeg kan stadig bruge al den hjælp, du kan yde med at samle uldbandager. Enhver hjælp er højt værdsat. Jeg håber blot, at vores indsats bliver god nok. Jeg har mistet for mange ædle sjæle på gårsdagens slagmarker til ikke at gøre alt i min magt for at sikre, at det ikke sker igen.", c="Du er en ærefuld <Class>, <Name>! Jeg vil sørge for, at disse bandager havner i de rette hænder. Du har min tak og Hordens.\n\nGå i fred, og kom tilbage til mig, hvis du skulle få overskydende uldbandager. Vi kan bruge al den hjælp, vi kan få her."},
  [8608] = {n="Horden Har Brug for Mere Magevævsbandager!", l="Du er tilbage? Interessant. Som du kan se, samler jeg stadig ind til Ahn'Kiraj-'krigsindsatsen'. Hvilket betyder, at jeg igen beder dig om at tage ud og samle en stabel magevævsbandager til mig. Jeg ser frem til din tilbagekomst, <Class>.", p="Du er tilbage? Interessant. Som du kan se, samler jeg stadig ind til Ahn'Kiraj-'krigsindsatsen'. Hvilket betyder, at jeg igen beder dig om at tage ud og samle en stabel magevævsbandager til mig. Jeg ser frem til din tilbagekomst, <Class>.", c="Forbløffende, <Class>, du gjorde det faktisk igen! Nå, man siger jo, at jeg har god smag for dem, jeg vælger at sætte i min tjeneste. Meget godt, din indsats er noteret, og du vil modtage de sociale fordele, din indsats har givet dig. Jeg foreslår dog, at du tager ud og samler endnu et bundt magevævsbandager, hvis du virkelig vil bevise din værdi."},
  [8610] = {n="Horden Har Brug for Mere Runeklædebandager!", l="Tiden nærmer sig stadig, hvor vi vil kaste os hovedkulds ud i ildebranden ved Ahn'Kiraj, <Class>. Men først må vi samle vores styrke og gøre os klar, så vi kan overleve insekternes og deres herskeres anstormning.\n\nHvis du er her igen, så ønsker du vel at yde endnu et bidrag af runeklædebandager til krigsindsatsen? Gør venligst det så hurtigt du kan, og vend tilbage til mig igen.", p="Tiden nærmer sig stadig, hvor vi vil kaste os hovedkulds ud i ildebranden ved Ahn'Kiraj, <Class>. Men først må vi samle vores styrke og gøre os klar, så vi kan overleve insekternes og deres herskeres anstormning.\n\nHvis du er her igen, så ønsker du vel at yde endnu et bidrag af runeklædebandager til krigsindsatsen? Gør venligst det så hurtigt du kan, og vend tilbage til mig igen.", c="Det er en meget uegennyttig gerning, du udfører, <Name>. En, der sandsynligvis vil redde mange kæmpers liv ved Ahn'Kiraj. Tak, og vid at Horden sætter pris på din donation. Skulle du lave eller finde flere runeklædebandager, så overvej at bringe dem til mig her."},
  [8612] = {n="Horden Har Brug for Mere Magre Ulvebøffer!", l="Som du kan se, <Class>, skal vi stadig pakke mere mad til soldaterne. Jeg ved ikke, om du nogensinde har været i krig, men når du først er kommet forbi chokket på slagmarken, kan du blive ret sulten. Du gjorde et godt stykke arbejde sidst, så jeg forventer, at du klarer dig lige så godt, om ikke lidt hurtigere, med at skaffe mig endnu en stabel af de magre ulvebøffer.", p="Som du kan se, <Class>, skal vi stadig pakke mere mad til soldaterne. Jeg ved ikke, om du nogensinde har været i krig, men når du først er kommet forbi chokket på slagmarken, kan du blive ret sulten. Du gjorde et godt stykke arbejde sidst, så jeg forventer, at du klarer dig lige så godt, om ikke lidt hurtigere, med at skaffe mig endnu en stabel af de magre ulvebøffer.", c="Det lugter, som om du, eller nogen du kender, er en ret god kok, <Name>. De magre ulvebøffer får mig til at savle; jeg regner med, at det ikke bliver bemærket, hvis nogle forsvinder. Under alle omstændigheder godt arbejde. Jeg sørger for, at nogen pakker dem ordentligt, så de ikke fordærver for meget.\n\nHvis du støder på flere, ved du, hvor du finder mig."},
  [8614] = {n="Horden Har Brug for Mere Plettet Gulhale!", l="Så som du kan se, så skal vi stadig bruge en hel masse fisk. De kæmpende i den kommende Ahn'Kiraj-krig skal have en masse at spise, så jeg må have fat i så meget plettet gulhale, jeg kan. Du fanger dem, steger dem og bringer dem tilbage til mig her, så takker jeg dig, og Hordens takker dig med.", p="Så som du kan se, så skal vi stadig bruge en hel masse fisk. De kæmpende i den kommende Ahn'Kiraj-krig skal have en masse at spise, så jeg må have fat i så meget plettet gulhale, jeg kan. Du fanger dem, steger dem og bringer dem tilbage til mig her, så takker jeg dig, og Hordens takker dig med.", c="Det er den bedste fangst til dato, <Name>! Godt, ærligt arbejde det dér. Og ingen ben i dem heller! Tak skal du have for denne plettede gulhale, mon. Kom snart tilbage, hvis du steger flere!"},
  [8616] = {n="Horden Har Brug for Mere Bagt Laks!", l="Den sidste portion bagt laks, du donerede til krigsindsatsen, så meget lækker ud, <Class>. Jeg må indrømme, at jeg blev fristet til at tage et par stykker til mig selv. Som du kan se, har vi endnu ikke nået vores kvote her. Jeg håber, du er vendt tilbage, fordi du har endnu en stabel bagt laks med dig.", p="Den sidste portion bagt laks, du donerede til krigsindsatsen, så meget lækker ud, <Class>. Jeg må indrømme, at jeg blev fristet til at tage et par stykker til mig selv. Som du kan se, har vi endnu ikke nået vores kvote her. Jeg håber, du er vendt tilbage, fordi du har endnu en stabel bagt laks med dig.", c="Din donation af tid og energi til krigsindsatsen går langt ud over det forventede, <Name>. Jeg forsikrer dig om, at dit arbejde ikke er gået ubemærket hen. Du har min tak og Hordens taknemmelighed. Kom venligst tilbage til mig igen, hvis du bager endnu en portion."},
  [8621] = {n="Stormkalderens Fodbeskyttere", l="Bring Qiraji-bindingerne af Dominans, 2 Idoler af Salvie, 5 Bronzeskarabæer og 5 Lerskarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver desuden Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mægtigste qiraji bærer genstande af en sådan kraft, at selv en drage ville tøve.\n\nBring mig Qiraji-bindingerne af dominans og andre mindre komponenter, så skaber jeg et par kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har klaret dig godt, <Name>. Du har bevist, at du ikke er en almindelig dødelig.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de forbandede Qiraji."},
  [8622] = {n="Stormkalderens Brynje", l="Bring Den Gamle Guds Skal, 2 Idoler af Salvie, 5 Sølvskarabæer og 5 Knogleskarabæer til Vedsera inde i Ahn'Kiraj. Du skal desuden opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin søvn under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azeroth, kan komme om dage eller år; tiden betyder intet for væsner af hans kraft.\n\nNår stjernerne står gunstigt, vil han slå ud mod alle levende væsner med forfærdelig vrede. Du må finde ham, før det sker, og finde en måde at bringe hans eksistens til ende på.\n\nGør dette, og bring mig et stykke af hans skal. Jeg skal give dig rustning, som intet dødeligt væsen nogensinde har båret... rustning, der passer til den, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i søvn.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, der er større end de fleste udødelige væseners.\n\nVed at dræbe Ce'Tun har du ikke blot reddet hele Azeroth, du har også vippet de kosmiske begivenheders vægtskål ud over din forståelse.\n\nModtag denne brystplade som et symbol på den herlighed og byrde, der følger med dine handlinger.\n\nMå dens kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8623] = {n="Stormkalderens Diadem", l="Bring Vek'lørs Diadem, 2 Idoler af Genfødsel, 5 Stenskarabæer og 5 Krystalskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hviskenen tærer langsomt på mit sind. De spotter mig, vel vidende at jeg ikke kan trænge længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med mægtige kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til noget, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg behøver, <Name>. Jeg vil give dig et hovedstykke af uovertruffen kraft.", p="Bragte du de komponenter, jeg bad om, <Name>?", c="Du har lykkedes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil indjage frygt i Qirajiernes hjerter... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8624] = {n="Stormkalderens Benbeskyttere", l="Bring Skindet fra den Store Sandorm, 2 Idoler af Strid, 5 Bronzeskarabæer og 5 Elfenbensskarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal desuden opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for min slags, dødelige? Meget godt, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Det siges, at han blev skabt af Den Gamle Gud selv som en parodi på livet.\n\nHans hud er unaturlig... tyk, næsten uigennemtrængelig, men alligevel fleksibel, og den lader ham bevæge sig med hastigheden og elegancen hos et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg smede dig benbeskyttere af stor kraft.", p="Bragte du de komponenter, jeg behøver, <Name>?", c="Ja... ormens hud vil udgøre et fortrinligt beskyttende lag. Sammen med de stærkeste dele fra de Qiraji, vi har tilintetgjort på vejen hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at stå imod de ubeskrivelige rædsler, der venter indenfor!"},
  [8625] = {n="Gådeskulderbeskyttere", l="Bring Qiraji-bindingerne af Dominans, 2 Idoler af Genfødsel, 5 Sølvskarabæer og 5 Elfenbensskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Neutral ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Blandt os siges det, at den udsmykkede skulderrustning, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så skal jeg forme dem til et par skulderplader, der er mere frygtindgydende end selveste Nefarians vinger!", p="Har du samlet de komponenter, jeg behøver?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender laver jeg disse skulderplader til dig, dødelige. Må de give dig den beskyttelse, du behøver, og må synet af dem indjage frygt i vores fjender."},
  [8626] = {n="Slagterens Fodbeskyttere", l="Bring Qiraji-bindingerne af Kommando, 2 Idoler af Liv, 5 Stenskarabæer og 5 Knogleskarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver desuden Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mægtigste qiraji bærer genstande af en sådan kraft, at selv en drage ville tøve.\n\nBring mig Qiraji-bindingerne af kommando og andre mindre komponenter, så skaber jeg et par kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har klaret dig godt, <Name>. Du har bevist, at du ikke er en almindelig dødelig.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de forbandede Qiraji."},
  [8627] = {n="Hævnerens Brystplade", l="Bring Den Gamle Guds Skal, 2 Idoler af Salvie, 5 Sølvskarabæer og 5 Knogleskarabæer til Vedsera inde i Ahn'Kiraj. Du skal desuden opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin søvn under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azeroth, kan komme om dage eller år; tiden betyder intet for væsner af hans kraft.\n\nNår stjernerne står gunstigt, vil han slå ud mod alle levende væsner med forfærdelig vrede. Du må finde ham, før det sker, og finde en måde at bringe hans eksistens til ende på.\n\nGør dette, og bring mig et stykke af hans skal. Jeg skal give dig rustning, som intet dødeligt væsen nogensinde har båret... rustning, der passer til den, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i søvn.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, der er større end de fleste udødelige væseners.\n\nVed at dræbe Ce'Tun har du ikke blot reddet hele Azeroth, du har også vippet de kosmiske begivenheders vægtskål ud over din forståelse.\n\nModtag denne brystplade som et symbol på den herlighed og byrde, der følger med dine handlinger.\n\nMå dens kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8628] = {n="Hævnerens Krone", l="Bring Vek'lørs Diadem, 2 Idoler af Genfødsel, 5 Stenskarabæer og 5 Krystalskarabæer til Andorgos i Ahn'Kiraj. Du skal desuden opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hviskenen tærer langsomt på mit sind. De spotter mig, vel vidende at jeg ikke kan trænge længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med mægtige kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til noget, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg behøver, <Name>. Jeg vil give dig et hovedstykke af uovertruffen kraft.", p="Bragte du de komponenter, jeg bad om, <Name>?", c="Du har lykkedes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil indjage frygt i Qirajiernes hjerter... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8629] = {n="Hævnerens Benskinner", l="Bring Den Store Sandormens Hud, 2 Strid-idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for mit folk, dødelige? Fint, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Man siger, at han blev skabt af Den Gamle Gud selv som en hån mod livet.\n\nHans hud er unaturlig... tyk, næsten uovervindelig, men den er fleksibel og lader ham bevæge sig med hastigheden og elegancen af et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg fremstille dig benbeskyttere af stor kraft.", p="Har du bragt de komponenter, jeg kræver, <Name>?", c="Ja... ormens hud vil blive et fremragende beskyttelseslag. Kombineret med de stærkeste dele fra de Qiraji, vi har ødelagt på vores vej hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at trodse de ubeskrivelige rædsler, der venter indenfor!"},
  [8630] = {n="Hævnerens Skulderplader", l="Bring Qiraji-bindingerne af Herredømme, 2 Liv-idoler, 5 Krystal-skarabæer og 5 Guld-skarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå Neutral ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Blandt os siges det, at de udsmykkede skulderpanser, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så former jeg dem til et sæt skulderplader, der er mere frygtindgydende end selveste Nefarians vinger!", p="Har du samlet de komponenter, jeg kræver?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender smeder jeg dig disse skulderplader, dødelige. Må de give dig den beskyttelse, du har brug for, og må synet af dem jage frygt i vores fjender."},
  [8631] = {n="Gådens Benbeskyttere", l="Bring Uros Intakte Hud, 2 Salvie-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for mit folk, dødelige? Fint, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Man siger, at han blev skabt af Den Gamle Gud selv som en hån mod livet.\n\nHans hud er unaturlig... tyk, næsten uovervindelig, men den er fleksibel og lader ham bevæge sig med hastigheden og elegancen af et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg fremstille dig benbeskyttere af stor kraft.", p="Har du bragt de komponenter, jeg kræver, <Name>?", c="Ja... ormens hud vil blive et fremragende beskyttelseslag. Kombineret med de stærkeste dele fra de Qiraji, vi har ødelagt på vores vej hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at trodse de ubeskrivelige rædsler, der venter indenfor!"},
  [8632] = {n="Gådens Pandebånd", l="Bring Vek'nilasks Pandebånd, 2 Nat-idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hvisken tager langsomt sin pris på mit sind. De håner mig, vidende at jeg ikke kan træde længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med magtfulde kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til dem, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg kræver, <Name>. Så giver jeg dig et hovedstykke af uovertruffen kraft.", p="Har du bragt mig de komponenter, jeg bad om, <Name>?", c="Du har lykkes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil jage frygt i Qiraji-hjerterne... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8633] = {n="Gådens Kapper", l="Bring Den Gamle Guds Skal, 2 Sol-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Vedsera i Ahn'Kiraj. Du skal også opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin dvale under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azerot, kan komme om dage eller år; tiden har ingen betydning for væsener af hans kraft.\n\nNår stjernerne er gunstige, vil han slå ud mod alle levende væsener med forfærdelig vrede. Du må finde ham, før da, og finde en måde at bringe hans eksistens til ophør.\n\nGør dette og bring mig et stykke af hans skal. Jeg skal give dig rustning, ingen dødelig nogensinde har båret... rustning, der passer til en, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i dvale.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, større end de fleste udødelige væseners.\n\nVed at slå Ce'Tun har du ikke blot reddet hele Azerot, du har også vippet de kosmiske begivenheders vægtskål ud over din fatteevne.\n\nAccepter disse kapper som et symbol på den herlighed og byrde, der vil følge som en konsekvens af dine handlinger.\n\nMå deres kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8634] = {n="Gådens Støvler", l="Bring Qiraji-bindingerne af Herredømme, 2 Sol-idoler, 5 Sølv-skarabæer og 5 Krystal-skarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver også Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mest magtfulde qiraji fører genstande af en sådan styrke, at de ville få selv en drage til at standse op.\n\nBring mig qiraji-bindingerne af herredømme og andre mindre komponenter, så skaber jeg et sæt kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har gjort det godt, <Name>. Du har bevist, at du ikke er et almindeligt dødeligt væsen.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de onde qiraji."},
  [8637] = {n="Dødsbringerens Støvler", l="Bring Qiraji-bindingerne af Kommando, 2 Strid-idoler, 5 Krystal-skarabæer og 5 Knogle-skarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver også Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mest magtfulde qiraji fører genstande af en sådan styrke, at de ville få selv en drage til at standse op.\n\nBring mig qiraji-bindingerne af kommando og andre mindre komponenter, så skaber jeg et sæt kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har gjort det godt, <Name>. Du har bevist, at du ikke er et almindeligt dødeligt væsen.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de onde qiraji."},
  [8638] = {n="Dødsbringerens Vest", l="Bring den Gamle Guds Skal, 2 Strid-idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Vedsera inde i Ahn'Kiraj. Du skal også opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin dvale under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azerot, kan komme om dage eller år; tiden har ingen betydning for væsener af hans kraft.\n\nNår stjernerne er gunstige, vil han slå ud mod alle levende væsener med forfærdelig vrede. Du må finde ham, før da, og finde en måde at bringe hans eksistens til ophør.\n\nGør dette og bring mig et stykke af hans skal. Jeg skal give dig rustning, ingen dødelig nogensinde har båret... rustning, der passer til en, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i dvale.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, større end de fleste udødelige væseners.\n\nVed at slå Ce'Tun har du ikke blot reddet hele Azerot, du har også vippet de kosmiske begivenheders vægtskål ud over din fatteevne.\n\nAccepter dette brystpanser som et symbol på den herlighed og byrde, der vil følge som en konsekvens af dine handlinger.\n\nMå dets kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8639] = {n="Dødsbringerens Hjelm", l="Bring Vek'lørs Diadem, 2 Krig-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hvisken tager langsomt sin pris på mit sind. De håner mig, vidende at jeg ikke kan træde længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med magtfulde kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til dem, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg kræver, <Name>. Så giver jeg dig et hovedstykke af uovertruffen kraft.", p="Har du bragt mig de komponenter, jeg bad om, <Name>?", c="Du har lykkes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil jage frygt i Qiraji-hjerterne... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8640] = {n="Dødsbringerens Benbeskyttere", l="Bring Uros Intakte Hud, 2 Nat-idoler, 5 Sten-skarabæer og 5 Krystal-skarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for mit folk, dødelige? Fint, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Man siger, at han blev skabt af Den Gamle Gud selv som en hån mod livet.\n\nHans hud er unaturlig... tyk, næsten uovervindelig, men den er fleksibel og lader ham bevæge sig med hastigheden og elegancen af et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg fremstille dig benbeskyttere af stor kraft.", p="Har du bragt de komponenter, jeg kræver, <Name>?", c="Ja... ormens hud vil blive et fremragende beskyttelseslag. Kombineret med de stærkeste dele fra de Qiraji, vi har ødelagt på vores vej hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at trodse de ubeskrivelige rædsler, der venter indenfor!"},
  [8641] = {n="Dødsbringerens Skulderstykker", l="Bring Qiraji-bindingerne af Kommando, 2 Sol-idoler, 5 Sølv-skarabæer og 5 Ler-skarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå Neutral ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Blandt os siges det, at de udsmykkede skulderpanser, som de dødelige racer bærer, oprindeligt var et forsøg på at efterligne en drages vinger.\n\nBring mig de bindinger, som de højeste Qiraji-ledere bærer, så former jeg dem til et sæt skulderplader, der er mere frygtindgydende end selveste Nefarians vinger!", p="Har du samlet de komponenter, jeg kræver?", c="Af de materialer, du bringer, og af skællene fra vores faldne Qiraji-fjender smeder jeg dig disse skulderplader, dødelige. Må de give dig den beskyttelse, du har brug for, og må synet af dem jage frygt i vores fjender."},
  [8655] = {n="Hævnerens Benskinner", l="Bring Qiraji-bindingerne af Herredømme, 2 Salvie-idoler, 5 Bronze-skarabæer og 5 Ler-skarabæer til Kandrostrasz i Ahn'Kiraj. Denne opgave kræver også Neutral fraktion hos Nosdormus Yngel.", d="Qiraji-magi er stærk og gammel. De mest magtfulde qiraji fører genstande af en sådan styrke, at de ville få selv en drage til at standse op.\n\nBring mig qiraji-bindingerne af herredømme og andre mindre komponenter, så skaber jeg et sæt kraftfulde støvler til dig.\n\nDu vil finde dem nyttige i kampen mod fjenden.", p="Har du skaffet de genstande, jeg bad om, <Name>?", c="Du har gjort det godt, <Name>. Du har bevist, at du ikke er et almindeligt dødeligt væsen.\n\nJeg giver dig disse med tillid til, at de vil hjælpe dig med at knuse de onde qiraji."},
  [8656] = {n="Slagterens Brynje", l="Bring den Gamle Guds Skal, 2 Liv-idoler, 5 Guld-skarabæer og 5 Ler-skarabæer til Vedsera inde i Ahn'Kiraj. Du skal også opnå Æret ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Den unævnelige Gamle Gud vågner langsomt af sin dvale under Ahn'Kiraj. Den forfærdelige skæbne, der venter Azerot, kan komme om dage eller år; tiden har ingen betydning for væsener af hans kraft.\n\nNår stjernerne er gunstige, vil han slå ud mod alle levende væsener med forfærdelig vrede. Du må finde ham, før da, og finde en måde at bringe hans eksistens til ophør.\n\nGør dette og bring mig et stykke af hans skal. Jeg skal give dig rustning, ingen dødelig nogensinde har båret... rustning, der passer til en, der har dræbt en gud!", p="Ved hans bolig i Ahn'Kiraj venter den frygtede Ce'Tun i dvale.", c="Jeg forventede ikke, at du ville vende tilbage fra dit forsøg, <Name>.\n\nDu har opfyldt en skæbne, større end de fleste udødelige væseners.\n\nVed at slå Ce'Tun har du ikke blot reddet hele Azerot, du har også vippet de kosmiske begivenheders vægtskål ud over din fatteevne.\n\nAccepter dette brystpanser som et symbol på den herlighed og byrde, der vil følge som en konsekvens af dine handlinger.\n\nMå dets kraft hjælpe dig i de udfordringer, der venter dig, gudsdræber!"},
  [8657] = {n="Slagterens Diadem", l="Bring Vek'lørs Diadem, 2 Strid-idoler, 5 Bronze-skarabæer og 5 Elfenben-skarabæer til Andorgos i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Tvillingkejserne... deres uophørlige hvisken tager langsomt sin pris på mit sind. De håner mig, vidende at jeg ikke kan træde længere ind i deres domæne for at redde min bror Arigos.\n\nI mine syner ser jeg deres monstrøse ansigter pyntet med magtfulde kroner. Men jeg vil have min hævn... jeg vil omdanne disse symboler på Qiraji-magt til dem, der bedre passer til vores behov.\n\nBring mig de komponenter, jeg kræver, <Name>. Så vil jeg lave dig et hovedstykke af uovertruffen kraft.", p="Har du bragt mig de komponenter, jeg bad om, <Name>?", c="Du har lykkes! Hviskenen fra Tvillingkejserne er ophørt.\n\nTag dette som belønning. Blot synet af det vil jage frygt i Qiraji-hjerterne... det vil minde dem om deres faldne ledere og om den dødelige, der dræbte dem."},
  [8658] = {n="Slagterens Benbeskyttere", l="Bring Den Store Sandormens Hud, 2 Sol-idoler, 5 Sølv-skarabæer og 5 Knogle-skarabæer til Kandrostrasz inde i Ahn'Kiraj. Du skal også opnå Venlig ry hos Nosdormus Yngel for at fuldføre denne opgave.", d="Du søger at bevise din værdi over for mit folk, dødelige? Fint, måske kan vi være til gensidig hjælp.\n\nDen gamle sandorm, Uro, er et væsen med legendarisk kraft. Man siger, at han blev skabt af Den Gamle Gud selv som en hån mod livet.\n\nHans hud er unaturlig... tyk, næsten uovervindelig, men den er fleksibel og lader ham bevæge sig med hastigheden og elegancen af et langt mindre væsen.\n\nBring mig en prøve af hans hud sammen med andre mindre komponenter, så skal jeg fremstille dig benbeskyttere af stor kraft.", p="Har du bragt de komponenter, jeg kræver, <Name>?", c="Ja... ormens hud vil blive et fremragende beskyttelseslag. Kombineret med de stærkeste dele fra de Qiraji, vi har ødelagt på vores vej hertil, bør dette blive et formidabelt stykke rustning. Må den hjælpe dig med at trodse de ubeskrivelige rædsler, der venter indenfor!"},
