  [9101] = {n="Frostild-bælte", l="Ærkemager Angela Dosdanske ved Lysets Håb-kapellet i de Østlige Pestlande vil lave et Frostild-bælte, hvis du bringer hende følgende: 1 Vanhelliget Bælte, 8 Krigshærgede Stofrester, 2 Arkankrystaller og 2 Månestof.", d="Som Vagt fik jeg lov til at komme til mange af Medivérs personlige ejendele. Blandt disse genstande fandt jeg bøgerne mest oplysende. Selvom størstedelen af bøgerne var fyldt med - for at sige det rent ud - pjat, var der nogle perler. En af de bøger dokumenterede fremstillingen af et sæt rustning, der passer til en ærkemager: Frostild.\n\n<Angela peger på sit hoved.>\n\nDet står hele her, og jeg er villig til at dele frugterne af den viden med dig, så længe du kan skaffe mig de nødvendige materialer.", p="Med de rette materialer og reagenser kan jeg genskabe den mytiske Frostild-rustning.", c="Glem ikke, at magt uden kontrol er lige så ødelæggende som magt, der ikke bliver brugt, <Class>. Vær besindig, når du tager Frostild på."},
  [9102] = {n="Frostild-bindinger", l="Ærkemager Angela Dosdanske ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Frostild-bindinger, hvis du bringer hende følgende: 1 Vanhelliget Bindinger, 6 Krigshærgede Stofrester, 1 Arkankrystal og 1 Knudepunkt-krystal.", d="Som Vagt fik jeg lov til at komme til mange af Medivérs personlige ejendele. Blandt disse genstande fandt jeg bøgerne mest oplysende. Selvom størstedelen af bøgerne var fyldt med - for at sige det rent ud - pjat, var der nogle perler. En af de bøger dokumenterede fremstillingen af et sæt rustning, der passer til en ærkemager: Frostild.\n\n<Angela peger på sit hoved.>\n\nDet står hele her, og jeg er villig til at dele frugterne af den viden med dig, så længe du kan skaffe mig de nødvendige materialer.", p="Med de rette materialer og reagenser kan jeg genskabe den mytiske Frostild-rustning.", c="Glem ikke, at magt uden kontrol er lige så ødelæggende som magt, der ikke bliver brugt, <Class>. Vær besindig, når du tager Frostild på."},
  [9103] = {n="Pestshjerte-kappe", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande vil lave en Pestshjerte-kappe, hvis du bringer ham følgende: 1 Vanhelliget Kappe, 25 Krigshærgede Stofrester, 4 Månestof og 2 Knudepunkt-krystaller.", d="Jeg foregiver ingenting, kryb. Mørket i Pestshjerte-genstandene kunne meget vel tilintetgøre os begge to. Derfor er prisen så høj. Skal jeg dø, så skal det være som en rig mand.\n\nOg jeg bryder mig ikke en tøddel om, hvordan du dør, bare du gør, som jeg beder dig om. Bring mig det, jeg har brug for, så gavner vi begge to - eller dør; men det har jeg allerede forklaret...", p="Den vanartede gnaver er vendt tilbage! Har du det, jeg kræver?", c="Ser du? Forstår du nu kraften? Rensning... Hvilke tåber...\n\n<Matæus rister misbilligende på hovedet.>\n\nTag den nu og forsvind mig af syne."},
  [9104] = {n="Pestshjerte-benbeskyttere", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Pestshjerte-benbeskyttere, hvis du bringer ham følgende: 1 Vanhelliget Benbeskytter, 20 Krigshærgede Stofrester, 4 Månestof og 2 Knudepunkt-krystaller.", d="Jeg foregiver ingenting, kryb. Mørket i Pestshjerte-genstandene kunne meget vel tilintetgøre os begge to. Derfor er prisen så høj. Skal jeg dø, så skal det være som en rig mand.\n\nOg jeg bryder mig ikke en tøddel om, hvordan du dør, bare du gør, som jeg beder dig om. Bring mig det, jeg har brug for, så gavner vi begge to - eller dør; men det har jeg allerede forklaret...", p="Den vanartede gnaver er vendt tilbage! Har du det, jeg kræver?", c="Ser du? Forstår du nu kraften? Rensning... Hvilke tåber...\n\n<Matæus rister misbilligende på hovedet.>\n\nTag den nu og forsvind mig af syne."},
  [9105] = {n="Pestshjerte-pandebånd", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande vil lave et Pestshjerte-pandebånd, hvis du bringer ham følgende: 1 Vanhelliget Pandebånd, 15 Krigshærgede Stofrester, 3 Månestof og 3 Knudepunkt-krystaller.", d="Jeg foregiver ingenting, kryb. Mørket i Pestshjerte-genstandene kunne meget vel tilintetgøre os begge to. Derfor er prisen så høj. Skal jeg dø, så skal det være som en rig mand.\n\nOg jeg bryder mig ikke en tøddel om, hvordan du dør, bare du gør, som jeg beder dig om. Bring mig det, jeg har brug for, så gavner vi begge to - eller dør; men det har jeg allerede forklaret...", p="Den vanartede gnaver er vendt tilbage! Har du det, jeg kræver?", c="Ser du? Forstår du nu kraften? Rensning... Hvilke tåber...\n\n<Matæus rister misbilligende på hovedet.>\n\nTag den nu og forsvind mig af syne."},
