  [9110] = {n="Pestshjerte-bindinger", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Pestshjerte-bindinger, hvis du bringer ham følgende: 1 Vanhelliget Bindinger, 6 Krigshærgede Stofrester, 1 Arkankrystal og 1 Knudepunkt-krystal.", d="Jeg foregiver ingenting, kryb. Mørket i Pestshjerte-genstandene kunne meget vel tilintetgøre os begge to. Derfor er prisen så høj. Skal jeg dø, så skal det være som en rig mand.\n\nOg jeg bryder mig ikke en tøddel om, hvordan du dør, bare du gør, som jeg beder dig om. Bring mig det, jeg har brug for, så gavner vi begge to - eller dør; men det har jeg allerede forklaret...", p="Den vanartede gnaver er vendt tilbage! Har du det, jeg kræver?", c="Ser du? Forstår du nu kraften? Rensning... Hvilke tåber...\n\n<Matæus rister misbilligende på hovedet.>\n\nTag den nu og forsvind mig af syne."},
  [9111] = {n="Kappe af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave en Kappe af Tro, hvis du bringer ham følgende: 1 Vanhelliget Kappe, 25 Krigshærgede Stofrester, 4 Månestof og 2 Knudepunkt-krystaller.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <dreng/pige>, har du fundet de faldnes klæder? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - frataget alt, herunder deres værdighed.\n\nBring mig de vanhelligedes rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Klæderne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9112] = {n="Benbeskyttere af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Benbeskyttere af Tro, hvis du bringer ham følgende: 1 Vanhelliget Benbeskytter, 20 Krigshærgede Stofrester, 4 Månestof og 2 Knudepunkt-krystaller.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <dreng/pige>, har du fundet de faldnes klæder? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - frataget alt, herunder deres værdighed.\n\nBring mig de vanhelligedes rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Klæderne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9113] = {n="Pandebånd af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave et Pandebånd af Tro, hvis du bringer ham følgende: 1 Vanhelliget Pandebånd, 15 Krigshærgede Stofrester, 3 Månestof og 3 Knudepunkt-krystaller.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <dreng/pige>, har du fundet de faldnes klæder? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - frataget alt, herunder deres værdighed.\n\nBring mig de vanhelligedes rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Klæderne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9114] = {n="Skulderbeskyttere af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Skulderbeskyttere af Tro, hvis du bringer ham følgende: 1 Vanhelliget Skulderbeskytter, 12 Krigshærgede Stofrester, 2 Månestof og 3 Garvede Barske Huder.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <boy/girl>, har du fundet de faldnes messehagler? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - berøvet alt, herunder deres værdighed.\n\nBring mig de vanhellige rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Messehaglerne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9115] = {n="Sandaler af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Sandaler af Tro, hvis du bringer ham følgende: 1 Vanhelliget Sandal, 12 Krigshærgede Stofrester, 2 Månestof og 3 Garvede Barske Huder.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <boy/girl>, har du fundet de faldnes messehagler? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - berøvet alt, herunder deres værdighed.\n\nBring mig de vanhellige rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Messehaglerne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9116] = {n="Handsker af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Handsker af Tro, hvis du bringer ham følgende: 1 Vanhelliget Handske, 8 Krigshærgede Stofrester og 4 Månestof.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <boy/girl>, har du fundet de faldnes messehagler? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - berøvet alt, herunder deres værdighed.\n\nBring mig de vanhellige rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Messehaglerne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9117] = {n="Bælte med Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave et Bælte med Tro, hvis du bringer ham følgende: 1 Vanhelliget Bælte, 8 Krigshærgede Stofrester, 2 Arkankrystaller og 2 Månestof.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <boy/girl>, har du fundet de faldnes messehagler? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - berøvet alt, herunder deres værdighed.\n\nBring mig de vanhellige rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Messehaglerne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9118] = {n="Bindinger af Tro", l="Fader Inigo Montoy ved Lysets Håb-kapellet i de Østlige Pestlande vil lave Bindinger af Tro, hvis du bringer ham følgende: 1 Vanhelliget Bindinger, 6 Krigshærgede Stofrester, 1 Arkankrystal og 1 Knudepunkt-krystal.", d="<Fader Montoy laver nogle mærkelige bevægelser i luften foran dig.>\n\nVelsignede <boy/girl>, har du fundet de faldnes messehagler? De stakkels sjæle, hvis sidste åndedrag blev taget på slagmarken - berøvet alt, herunder deres værdighed.\n\nBring mig de vanhellige rester af de afdøde sammen med renselsesreagenser, så skal du kende troen.", p="Har du bragt mig reagenserne, barn?", c="Messehaglerne er klar, <Name>. Straf dem, der vil skade vores verden, med din retfærdige ild."},
  [9125] = {n="Kryptfjendedele", l="Du gjorde et fortrinligt stykke arbejde med det første bundt, <Name>. Har du flere, tager jeg dem nu. For hvert bundt du afleverer, belønner jeg dig med endnu en insignie.", p="Du gjorde et fortrinligt stykke arbejde med det første bundt, <Name>. Har du flere, tager jeg dem nu. For hvert bundt du afleverer, belønner jeg dig med endnu en insignie.", c="Allerbedst, <Name>! Disse kommer helt sikkert til god brug."},
  [9127] = {n="Knoglefragmenter", l="En mand i min branche kan aldrig have for mange knoglefragmenter, <Name>. Når du har et overskud af fragmenter, så bring dem til mig, så belønner jeg dig med endnu en insignie.", p="En mand i min branche kan aldrig have for mange knoglefragmenter, <Name>. Når du har et overskud af fragmenter, så bring dem til mig, så belønner jeg dig med endnu en insignie.", c="Min drøm om at blive fuldtidsdanser på diskoteket i Gadgetbyen er snart ved at blive virkelighed! Bliv ved med det gode arbejde, <Name>."},
  [9129] = {n="Kerne af Elementer", l="Sandt at sige bruger jeg kernerne til at lave Frostild-rustning. Det er rustningen, magikerne bruger i kampene i Naxxrammas. Uden dig og andre som dig ville vi uden tvivl tabe denne krig.\n\nNu da det er sagt, så bring mig flere kerner, så skal jeg give dig flere insignier.", p="Sandt at sige bruger jeg kernerne til at lave Frostild-rustning. Det er rustningen, magikerne bruger i kampene i Naxxrammas. Uden dig og andre som dig ville vi uden tvivl tabe denne krig.\n\nNu da det er sagt, så bring mig flere kerner, så skal jeg give dig flere insignier.", c="Du yder en stor tjeneste for os, <Name>. Godt gjort!"},
  [9132] = {n="Mørkejernsrester", l="For hver favn af resterne giver jeg dig en insignie - jo flere, jo bedre. Forsvind nu fra mit syn, før jeg deler dig i to!", p="For hver favn af resterne giver jeg dig en insignie - jo flere, jo bedre. Forsvind nu fra mit syn, før jeg deler dig i to!", c="Er det alt, du bragte mig? Måske hørte du mig ikke første gang. Jeg har brug for FLERE!"},
  [9137] = {n="Vilde Bregnblade", l="For hvert bundt bregneblade, du leverer til mig, betaler jeg dig med din valgfri insignie fra Daggry eller Korstoget.\n\nInsignier kan afleveres til Kvartermesteren for forskellige belønninger.", p="For hvert bundt bregneblade, du leverer til mig, betaler jeg dig med din valgfri insignie fra Daggry eller Korstoget.\n\nInsignier kan afleveres til Kvartermesteren for forskellige belønninger.", c="Tak, <Name>. Dit arbejde er afgørende for succesen i vores kampagne mod Svøben."},
  [9142] = {n="Håndværkerens Brev", l="Du kender proceduren, pjok. Et mod-mærke giver dig et Håndværkerens Brev.", p="Du kender proceduren, pjok. Et mod-mærke giver dig et Håndværkerens Brev.", c="Det har du fortjent, pjok. Nu, græd ikke over dine ordrer. Udfyld dem eller ødelæg dem."},
  [9165] = {n="Skrivelse om Boks Passage", l="Lever den underskrevne Skrivelse om Boks Passage til Udsendelseskommandør Mets ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Uden hjælp fra eventyrere var min karavane aldrig kommet igennem! Svøben kom krybende ud af alle kroge for at forsøge at stoppe os i at nå hertil.\n\n<Vagt Didder tørrer panden.>\n\nNu må vi vente her, indtil Feltmarskal Kamrene ankommer. Han skal underskrive din skrivelse om boks passage, som du skal tage tilbage til Udsendelseskommandør Mets ved Lysets Håb-kapellet.\n\nOg <Name>, pas på, hvad du siger over for Kamrene. Han er den 'bid dit hoved af og spyt ned i din luftrør'-type - bortset fra at han faktisk gør det..."},
  [9178] = {n="Håndværkerens Brev - Tæt Vægtsten", l="Lever 120 Tætte Vægtsten og Håndværkerens Brev - Tæt Vægtsten til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre BS-091:\n\n120 Tætte Vægtsten.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Jep, de her kommer til nytte for infanteriets knusende våben."},
  [9179] = {n="Håndværkerens Brev - Kejserlige Pladebryststykker", l="Lever 3 Kejserlige Pladebryststykker og Håndværkerens Brev - Kejserlige Pladebryststykker til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre BS-428:\n\n3 Kejserlige Pladebryststykker.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Mere rustning til troppene! Fantastisk, <Name>!"},
  [9181] = {n="Håndværkerens Brev - Vulkansk Hammer", l="Lever 3 Vulkanske Hammere og Håndværkerens Brev - Vulkansk Hammer til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre BS-697:\n\n3 Vulkanske Hammere.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Disse burde passe godt sammen med de tætte vægtsten, vi samler op."},
  [9182] = {n="Håndværkerens Brev - Kæmpe Thorium Kampøkse", l="Lever 3 Kæmpe Thorium Kampøkser og Håndværkerens Brev - Kæmpe Thorium Kampøkse til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre BS-6020:\n\n3 Kæmpe Thorium Kampøkser.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Disse er ikke så kæmpe, som jeg havde forventet. Men en aftale er en aftale."},
  [9183] = {n="Håndværkerens Brev - Strålende Pandebånd", l="Lever 3 Strålende Pandebånd og Håndværkerens Brev - Strålende Pandebånd til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre BS-80:\n\n3 Strålende Pandebånd.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Jeg kan stadig ikke tro, at Mets forventer, at vores tropper skal bære det her lavkvalitetsskrammel for at beskytte sig mod Svøbens iskolde angreb."},
  [9184] = {n="Håndværkerens Brev - Ond Læderhovedbånd", l="Lever 10 Onde Læderhovedbånd og Håndværkerens Brev - Ond Læderhovedbånd til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre LW-971:\n\n10 Onde Læderhovedbånd.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Disse er... onde."},
  [9185] = {n="Håndværkerens Brev - Barsk Rustningssæt", l="Lever 25 Barske Rustningssæt og Håndværkerens Brev - Barsk Rustningssæt til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre LW-448:\n\n25 Barske Rustningssæt.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="De barske rustningssæt har mange anvendelser, <Name>. De er ikke BARE til at klaske på visse rustningsdele for ekstra beskyttelse. Som denne her - den vil jeg bruge som tekande-cozy."},
  [9186] = {n="Håndværkerens Brev - Ond Læderbælte", l="Lever 9 Onde Læderbælter og Håndværkerens Brev - Ond Læderbælte til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre LW-736:\n\n9 Onde Læderbælter.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Disse bælter er faktisk mere onde end hovedbåndene - hvis man kan tro, at sådan noget er muligt."},
  [9187] = {n="Håndværkerens Brev - Runiske Læderbukser", l="Lever 4 Runiske Læderbukser og Håndværkerens Brev - Runiske Læderbukser til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre LW-8485:\n\n4 Runiske Læderbukser.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Druiderne vil helt sikkert værdsætte det håndværk, der er gået i disse bukser. Mange tak, <Class>."},
  [9188] = {n="Håndværkerens Brev - Lysstofbukser", l="Lever 6 Lysstofbukser og Håndværkerens Brev - Lysstofbukser til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre TR-95:\n\n6 Lysstofbukser.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Jeg kan næsten se mit spejlbillede i de her ting! Det er vanvittigt."},
  [9190] = {n="Håndværkerens Brev - Runestofstøvler", l="Lever 8 Runestofstøvler og Håndværkerens Brev - Runestofstøvler til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre TR-635:\n\n8 Runestofstøvler.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Ved Bronzeskægs skæg! Du bragte mig faktisk runestofstøvler... Jeg tabte vist det væddemål."},
  [9191] = {n="Håndværkerens Brev - Runestoftaske", l="Lever 8 Runestoftasker og Håndværkerens Brev - Runestoftaske til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre TR-9999:\n\n8 Runestoftasker.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Velsignede støvlesnører! Er det dem, jeg tror, de er? Troppene har klaget non-stop over manglen på opbevaringsplads til alt det, der kræves i felten. En af dem tegnede endda et diagram til mig - sådan en kneben type...\n\nDisse vil helt sikkert hjælpe med at mildne noget af klynkeriet."},
  [9194] = {n="Håndværkerens Brev - Runestofkappe", l="Lever 8 Runestofkapper og Håndværkerens Brev - Runestofkappe til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bæreren af dette brev er berettiget til betaling i form af en insignie efter eget valg ved fuldførelsen af den aftalte arbejdsordre.\n\nArbejdsordre TR-7229:\n\n8 Runestofkapper.\n\nAlle udfyldte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig, hvis den er blevet manipuleret eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder du en arbejdsordre, <Class>?", c="Du skulle ikke have! Nej, virkelig, du skulle ikke have. Jeg ved ikke, hvad Mets tænker, men ingen kommer til at bære disse kapper ind i Naxxrammas.\n\n<Pakkemester Stenbryder sukker.>\n\nBah, endnu en bunke skrammel, jeg må få sendt til frontlinjen, og endnu en skideballe, jeg må tage fra Kamrene."},
  [9195] = {n="Håndværkerens Brev - Nisse-minørladning", l="Lever 20 Nisse-minørladninger og Håndværkerens Brev - Nisse-minørladning - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre EN-11:\n\n20 Nisse-minørladninger.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Nu taler du mit sprog, <Class>. Ting der SMADRER!"},
  [9196] = {n="Håndværkerens Brev - Thoriumgranat", l="Lever 20 Thoriumgranater og Håndværkerens Brev - Thoriumgranat - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre EN-7:\n\n20 Thoriumgranater.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="De her må have kostet en pæn kobberskilling at lave. Har jeg ret eller har jeg ret, <Name>?"},
  [9197] = {n="Håndværkerens Brev - Gnomisk Kampkylling", l="Lever 4 Gnomiske Kampkyllinger og Håndværkerens Brev - Gnomisk Kampkylling - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre EN-0:\n\n4 Gnomiske Kampkyllinger.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Hvorfor smiler du? Hvad er så sjovt? Hør her, lille ven, en gnomisk kampkylling er en meget vigtig enhed og skal ikke tages let på - ALDRIG. Vi sender dem ind i områder, der er hårdt plaget eller angrebet, og de rydder op i alle pestinficerede insekter eller åd-maddiker, der stadig flagrer rundt. Alle ved jo, at robotter er immune over for pest.\n\nJeg vædder med, at du ikke føler dig så klog nu, hva'? Store nar..."},
  [9198] = {n="Håndværkerens Brev - Thoriumrør", l="Lever 14 Thoriumrør og Håndværkerens Brev - Thoriumrør - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre EN-558:\n\n14 Thoriumrør.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Thoriumrør? Jamen, tak.\n\n<Pakkemester Stenbryder kaster bunken af Thoriumrør op i en stor hob af forskelligt skrammel.>"},
  [9200] = {n="Håndværkerens Brev - Stor Manaeliksir", l="Lever 10 Store Manaeliksirer og Håndværkerens Brev - Stor Manaeliksir - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre AL-473:\n\n10 Store Manaeliksirer.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Deres nytteværdi burde være selvindlysende."},
  [9201] = {n="Håndværkerens Brev - Større Arkan Beskyttelseseliksir", l="Lever 15 Større Arkan Beskyttelseseliksirer og Håndværkerens Brev - Større Arkan Beskyttelseseliksir - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre AL-1420:\n\n15 Større Arkan Beskyttelseseliksirer.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="<Pakkemester Stenbryder trækker proppen af et af de større arkane beskyttelseseliksirer og tager en slurk.>\n\nWOOT! De har et spark, skat! Et spark, siger jeg!"},
  [9202] = {n="Håndværkerens Brev - Stor Helbredelseseliksir", l="Lever 20 Store Helbredelseseliksirer og Håndværkerens Brev - Stor Helbredelseseliksir - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre AL-169110:\n\n20 Store Helbredelseseliksirer.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Ved du, hvad tropperne på frontlinjen kalder dem? Præster i en flaske...\n\n<Pakkemester Stenbryder synger.>\n\n\"Jeg er din præst i en fla-ske, skat... du skal drikke mig på den rigtige måde...\"\n\nHvad er der galt, lille ven? Det er en meget populær sang i disse egne."},
  [9203] = {n="Håndværkerens Brev - Forsteningskolbe", l="Lever 1 Forsteningskolbe og Håndværkerens Brev - Forsteningskolbe - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre AL-90:\n\n1 Forsteningskolbe.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Ingen kommentar.\n\n<Pakkemester Stenbryder stirrer vredt på dig.>\n\nJeg sagde ingen kommentar! Forsvind nu fra mit syn!"},
  [9204] = {n="Håndværkerens Brev - Stenskæl-ål", l="Lever 40 Stenskæl-ål og Håndværkerens Brev - Stenskæl-ål - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre FS-5:\n\n40 Stenskæl-ål.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Du kunne have brugt dem til noget andet, men det gjorde du ikke, gjorde du? Der er ingen mening i at græde over det nu, <Name>."},
  [9205] = {n="Håndværkerens Brev - Pladeret Rustningsfisk", l="Lever 30 Pladerede Rustningsfisk og Håndværkerens Brev - Pladeret Rustningsfisk - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre FS-12:\n\n30 Pladerede Rustningsfisk.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="Ved du virkelig ikke, hvad de her bruges til?\n\n<Pakkemester Stenbryder griner.>\n\nJeg skal da pokker ikke fortælle dig det!"},
  [9206] = {n="Håndværkerens Brev - Lynål", l="Lever 30 Lynål og Håndværkerens Brev - Lynål - til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Brevets bærer har ret til betaling i form af en insignie efter eget valg, når den aftalte arbejdsordre er udført.\n\nArbejdsordre FS-9:\n\n30 Lynål.\n\nAlle udførte ordrer skal leveres til Pakkemester Stenbryder ved Lysets Håb-kapellet i de Østlige Pestlande.\n\nKontrakten er ugyldig og intet værd, hvis den er blevet pillet ved eller beskadiget.\n\n-Udsendelseskommandør Mets, Sølvdæmringen", p="Udfylder en arbejdsordre, <Class>?", c="De her laver de bedste ålerulleder i verden. Det er rigtigt - I VERDEN."},
  [9208] = {n="Den Vilde Vagt - Arkanum af Beskyttelse", l="Zanza den Rastløse i Zul'Gurb ønsker et Arkanum af Beskyttelse.", d="Zanza kan skabe mange gamle trolde-fortryllelser med de rigtige ingredienser! Har du hørt om Den Vilde Vagt? Nej, selvfølgelig har du ikke. Dit sind er tåget af den ringere alviske magi.\n\nBring mig et arkanum af alvisk skabelse, så jeg kan tilintetgøre afvigelsen. Gør du det, skal Den Vilde Vagt være din.", p="Har du arkanummet?", c="Den værdiløse magi i disse fortryllelser fodrer min vrede. Min vrede giver mig styrke.\n\nBring mig flere, så skal du få endnu en Vild Vagt."},
  [9209] = {n="Den Vilde Vagt - Arkanum af Hurtighed", l="Zanza den Rastløse i Zul'Gurb ønsker et Arkanum af Hurtighed.", d="Zanza kan skabe mange gamle trolde-fortryllelser med de rigtige ingredienser! Har du hørt om Den Vilde Vagt? Nej, selvfølgelig har du ikke. Dit sind er tåget af den ringere alviske magi.\n\nBring mig et arkanum af alvisk skabelse, så jeg kan tilintetgøre afvigelsen. Gør du det, skal Den Vilde Vagt være din.", p="Har du arkanummet?", c="Den værdiløse magi i disse fortryllelser fodrer min vrede. Min vrede giver mig styrke.\n\nBring mig flere, så skal du få endnu en Vild Vagt."},
  [9210] = {n="Den Vilde Vagt - Arkanum af Fokus", l="Zanza den Rastløse i Zul'Gurb ønsker et Arkanum af Fokus.", d="Zanza kan skabe mange gamle trolde-fortryllelser med de rigtige ingredienser! Har du hørt om Den Vilde Vagt? Nej, selvfølgelig har du ikke. Dit sind er tåget af den ringere alviske magi.\n\nBring mig et arkanum af alvisk skabelse, så jeg kan tilintetgøre afvigelsen. Gør du det, skal Den Vilde Vagt være din.", p="Har du arkanummet?", c="Den værdiløse magi i disse fortryllelser fodrer min vrede. Min vrede giver mig styrke.\n\nBring mig flere, så skal du få endnu en Vild Vagt."},
  [9211] = {n="Isvagten", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande ønsker 10 Insignier fra Korstoget og 30 guld.", d="Ah, Isvagten. Det er et tyndt lag beskyttende magi, der dækker visse stykker udstyr. De, der kæmper mod væsener af frost og is, vil få øget beskyttelse mod deres angreb ved at bruge Isvagten.\n\nSom med alt, hvad Vredeskasteren skaber, er der en pris - en pris, som jeg ikke vil sænke, uanset hvor meget du jamrer. Interesseret?", p="Hvis det ikke var for disse Sølvdæmrings-vagter, ville du være en plet på dette gulv.", c="<Matæus stikker guldet i lommen.>\n\nNyd reparationsomkostningerne, <Race>. Naxxrammas er 'ukærlig' over for de uindviede."},
  [9213] = {n="Skyggevagten", l="Matæus Vredeskasteren ved Lysets Håb-kapellet i de Østlige Pestlande ønsker 10 Insignier fra Korstoget og 30 guld.", d="Et geniatext! Ligesom Isvagten bruger Skyggevagten et tyndt lag beskyttende magi, der dækker visse stykker udstyr. Og ligesom Isvagten kommer Skyggevagten til at koste dig en pæn sum penge.\n\n<Matæus rækker hånden frem og gnider fingrene mod hinanden.>\n\nInteresseret?", p="<Matæus gaber.>\n\nVæk dig, insekt, medmindre du har noget til mig.", c="<Matæus stopper guldet ned i sin kåbe.>\n\nHvad står du stadig og laver, <Race>? Vores forretning er afsluttet."},
  [9221] = {n="Overlegen Kampoprustning - Ven af Daggry", l="For 30 Insignier fra Daggry og 30 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nJeg må advare dig; køb foretaget med et venligt ry hos Daggry kommer med et stort tillæg. Jeg vil råde dig til at opnå et bedre ry hos Daggry, før du går videre med dine planer."},
  [9222] = {n="Episk Kampoprustning - Ven af Daggry", l="For 110 Insignier fra Daggry og 110 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med enorm kraft?\n\nJeg må advare dig; køb foretaget med et venligt ry hos Daggry kommer med et ekstremt stort tillæg. Jeg vil råde dig til at opnå et bedre ry hos Daggry, før du går videre med dine planer."},
  [9223] = {n="Overlegen Kampoprustning - Æret blandt Daggry", l="For 20 Insignier fra Daggry og 20 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nJeg må advare dig; køb foretaget med et æret ry hos Daggry kommer med et temmelig afskrækkende tillæg. Jeg vil råde dig til at opnå et bedre ry hos Daggry, før du går videre med dine planer.", p="Vælg med omhu. Der er ingen tilbagebetalinger.", c="God dag, <Name>. Det var en fornøjelse at gøre forretninger med dig."},
  [9224] = {n="Episk Kampoprustning - Æret blandt Daggry", l="For 75 Insignier fra Daggry og 75 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med stor kraft?\n\nJeg må advare dig; køb foretaget med et æret ry hos Daggry kommer med et ekstremt stort tillæg. Jeg vil råde dig til at opnå et bedre ry hos Daggry, før du går videre med dine planer."},
  [9225] = {n="Episk Kampoprustning - Respekteret blandt Daggry", l="For 45 Insignier fra Daggry og 45 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med stor kraft?\n\nJeg må advare dig; episke køb foretaget med et respekteret ry hos Daggry er stadig ganske dyre. Jeg vil råde dig til at opnå et bedre ry hos Daggry, før du går videre med dine planer.", p="Vælg med omhu. Der er ingen tilbagebetalinger.", c="God dag, <Name>. Det var en fornøjelse at gøre forretninger med dig."},
  [9226] = {n="Overlegen Kampoprustning - Respekteret blandt Daggry", l="For 7 Insignier fra Daggry og 7 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nGenstande, der tilbydes dem, som er respekteret blandt Daggry, er prissat ganske rimeligt. Jeg opfordrer dig til at foretage et køb!", p="Vælg med omhu. Der er ingen tilbagebetalinger.", c="God dag, <Name>. Det var en fornøjelse at gøre forretninger med dig."},
  [9227] = {n="Overlegen Kampoprustning - Ophøjet blandt Daggry", l="For 6 Insignier fra Daggry og 6 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nGenstande, der tilbydes dem, som er ophøjet blandt Daggry, er nedsatte. Jeg opfordrer dig til at foretage et køb!", p="Vælg med omhu. Der er ingen tilbagebetalinger.", c="God dag, <Name>. Det var en fornøjelse at gøre forretninger med dig."},
  [9228] = {n="Episk Kampoprustning - Ophøjet blandt Daggry", l="For 27 Insignier fra Daggry og 27 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skattekammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med stor kraft?\n\nDem, der er ophøjet blandt Daggry, får vores største rabatter! Jeg opfordrer dig til at foretage et køb.", p="Vælg med omhu. Der er ingen tilbagebetalinger.", c="God dag, <Name>. Det var en fornøjelse at gøre forretninger med dig."},
  [9259] = {n="Forræder mod Blodsejl", l="Den mangne hund, Tyranbrand, har tilbudt at benåde alle tidligere Blodsejlere, der er villige til at vende kappen mod deres kaptajn! Den bundskidtede sutter bad mig gå hen og slagte mine gamle makkere og bringe deres tørklæder hjem som bevis.\n\nJeg har ikke hjertet til det, og jeg vil heller ikke bede dig om det. Bring mig noget silkeklæde og rød farve, så laver jeg passende kopier. Jeg siger til Baronen, at du er gået over til fjenden, men vær advaret... Blodsejlerne bryder sig ikke om det!", p="Den mangne hund, Tyranbrand, har tilbudt at benåde alle tidligere Blodsejlere, der er villige til at vende kappen mod deres kaptajn! Den bundskidtede sutter bad mig gå hen og slagte mine gamle makkere og bringe deres tørklæder hjem som bevis.\n\nJeg har ikke hjertet til det, og jeg vil heller ikke bede dig om det. Bring mig noget silkeklæde og rød farve, så laver jeg passende kopier. Jeg siger til Baronen, at du er gået over til fjenden, men vær advaret... Blodsejlerne bryder sig ikke om det!", c="Lad os holde et minuts stilhed for vores faldne makkere, <Name>.\n\n\n\nAt være forræder er én ting, men at myrde sine egne bukkes... det ville være rent ud afskyeligt, jo!"},
  [9266] = {n="Gøre Godt Igen", l="Du må have gjort noget virkelig dårligt mod os eller vores venner, <Name>. Under alle omstændigheder er jeg her for at tilbyde dig en måde at få vores gode nåde tilbage på.\n\nSom du ved, er Vinterkilde ret kold. Med så mange af os kobolder, der kommer fra andre byer, kunne vi bruge en hånd til at holde varmen. Bring mig noget runeklæde og kul, så siger jeg et godt ord for dig. Men advaret: vores fjender kommer ikke til at tage pænt imod, at du hjælper os.", p="Du må have gjort noget virkelig dårligt mod os eller vores venner, <Name>. Under alle omstændigheder er jeg her for at tilbyde dig en måde at få vores gode nåde tilbage på.\n\nSom du ved, er Vinterkilde ret kold. Med så mange af os kobolder, der kommer fra andre byer, kunne vi bruge en hånd til at holde varmen. Bring mig noget runeklæde og kul, så siger jeg et godt ord for dig. Men advaret: vores fjender kommer ikke til at tage pænt imod, at du hjælper os.", c="Tak, <Name>. Du er på en hurtig vej til at genvinde din ære i vores fine by."},
  [9267] = {n="Lapning af Gamle Sår", l="Du må hellere tænke dig om, før du sætter fødderne i Skralleby, <Name>! Ryget om dine beskidte gerninger har spredt sig.\n\nDu er dog heldig, for et skib er lige ankommet med mange sårede fra et møde med Blodsejl-fribytterne. Her har du chancen for at bevise, at du ikke er en fuldstændig skurk. Giv os en hånd ved at bringe linnedstof til bandager og tomme hætteglas til eliksirer.", p="Du må hellere tænke dig om, før du sætter fødderne i Skralleby, <Name>! Ryget om dine beskidte gerninger har spredt sig.\n\nDu er dog heldig, for et skib er lige ankommet med mange sårede fra et møde med Blodsejl-fribytterne. Her har du chancen for at bevise, at du ikke er en fuldstændig skurk. Giv os en hånd ved at bringe linnedstof til bandager og tomme hætteglas til eliksirer.", c="Jeg er glad for at se, at du indser dine fejl, <Name>. Bliv ved med at bringe forsyninger; vi glemmer dig ikke så let, makker!"},
  [9268] = {n="Krig på Havet", l="Du ønsker at forsone dig med kobolderne i Tanaris igen, <Name>? Vi mangler materialer til sejl og kanoner, så vi kan drive vores gamle fjender, Blodsejl-fribytterne, på flugt. Bring mig magevæv og stærk flux, så er vi på vej til at benåde dine overtrædelser.", p="Du ønsker at forsone dig med kobolderne i Tanaris igen, <Name>? Vi mangler materialer til sejl og kanoner, så vi kan drive vores gamle fjender, Blodsejl-fribytterne, på flugt. Bring mig magevæv og stærk flux, så er vi på vej til at benåde dine overtrædelser.", c="Bliv ved, <Name>. Vi kobolder glemmer ikke så let!"},
  [9317] = {n="Indviede Slibesten", l="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være en stor hjælp i din kamp mod Liskekongens håndlangere.", p="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være en stor hjælp i din kamp mod Liskekongens håndlangere.", c="Tak, <Name>. Her er dine indviede slibesten. Brug dem klogt."},
  [9318] = {n="Velsignet Troldmandsolie", l="Til gengæld for de nekrotiske runer fra Svøbens invasionsstyrker vil Sølvdæmringen give dig et hætteglas velsignet troldmandsolie.", p="Til gengæld for de nekrotiske runer fra Svøbens invasionsstyrker vil Sølvdæmringen give dig et hætteglas velsignet troldmandsolie.", c="Jeg håber, at du finder disse genstande nyttige i kommende slag."},
  [9320] = {n="Stor Manaeliksir", l="Ud over vores øvrige forsyninger har vi også en del store manaeliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", p="Ud over vores øvrige forsyninger har vi også en del store manaeliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", c="Her er den, <Name>. Pas på dig selv derude. Vores tal er ikke så store, at vi har råd til mange tab på slagmarken."},
  [9321] = {n="Stor Helbredelseseliksir", l="Ud over vores øvrige forsyninger har vi også en del store helbredelseseliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", p="Ud over vores øvrige forsyninger har vi også en del store helbredelseseliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", c="Her er den, <Name>. Pas på dig selv derude. Vores tal er ikke så store, at vi har råd til mange tab på slagmarken."},
  [9333] = {n="Sølvdæmringens Handsker", l="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse til gengæld. Disse bør vise sig værdifulde i vores kamp mod den udøde Svøbe.", p="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse til gengæld. Disse bør vise sig værdifulde i vores kamp mod den udøde Svøbe.", c="Du har klaret det godt, <Name>. Vælg din håndbeskyttelse som tak for din indsats."},
  [9334] = {n="Velsignet Troldmandsolie", l="Til gengæld for de nekrotiske runer fra Svøbens invasionsstyrker vil Sølvdæmringen give dig et hætteglas velsignet troldmandsolie.", p="Til gengæld for de nekrotiske runer fra Svøbens invasionsstyrker vil Sølvdæmringen give dig et hætteglas velsignet troldmandsolie.", c="Jeg håber, at du finder disse genstande nyttige i kommende slag."},
  [9335] = {n="Indviede Slibesten", l="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være en stor hjælp i din kamp mod Liskekongens håndlangere.", p="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være en stor hjælp i din kamp mod Liskekongens håndlangere.", c="Tak, <Name>. Her er dine indviede slibesten. Brug dem klogt."},
  [9336] = {n="Stor Helbredelseseliksir", l="Ud over vores øvrige forsyninger har vi også en del store helbredelseseliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", p="Ud over vores øvrige forsyninger har vi også en del store helbredelseseliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", c="Her er den, <Name>. Pas på dig selv derude. Vores tal er ikke så store, at vi har råd til mange tab på slagmarken."},
  [9337] = {n="Stor Manaeliksir", l="Ud over vores øvrige forsyninger har vi også en del store manaeliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", p="Ud over vores øvrige forsyninger har vi også en del store manaeliksirer, som du måske finder nyttige. Jeg giver dig et i bytte for femten nekrotiske runer.", c="Her er den, <Name>. Pas på dig selv derude. Vores tal er ikke så store, at vi har råd til mange tab på slagmarken."},
  [9338] = {n="Troskab mod Cenarion-kredsen", l="Selvom du ikke har brug for de materielle belønninger, vi tilbyder, så markerer disse mærker stadig vores gensidige tillid og venskab.\n\nBring dem til mig. Jeg noterer din tjeneste omhyggeligt, hvis din indsats overgår det forventede.", p="Selvom du ikke har brug for de materielle belønninger, vi tilbyder, så markerer disse mærker stadig vores gensidige tillid og venskab.\n\nBring dem til mig. Jeg noterer din tjeneste omhyggeligt, hvis din indsats overgår det forventede.", c="Du ærer os, <Name>. Med din fortsatte indsats skal vi overvinde alle forhindringer."},
  [9341] = {n="Sølvdæmringens Kjortel", l="Du har støttet vores sag betydeligt, <Name>. Hvis du ønsker det, kan jeg skaffe dig Sølvdæmringens kjortel. Vi er stolte af at have dig blandt vores allierede.", p="Du har støttet vores sag betydeligt, <Name>. Hvis du ønsker det, kan jeg skaffe dig Sølvdæmringens kjortel. Vi er stolte af at have dig blandt vores allierede.", c="Tag denne kjortel og bær den med stolthed. Måske inspirerer dine bedrifter andre til at tage våben op til støtte for vores kamp mod Svøben."},
  [9343] = {n="Sølvdæmringens Kjortel", l="Du har støttet vores sag betydeligt, <Name>. Hvis du ønsker det, kan jeg skaffe dig Sølvdæmringens kjortel. Vi er stolte af at have dig blandt vores allierede.", p="Du har støttet vores sag betydeligt, <Name>. Hvis du ønsker det, kan jeg skaffe dig Sølvdæmringens kjortel. Vi er stolte af at have dig blandt vores allierede.", c="Tag denne kjortel og bær den med stolthed. Måske inspirerer dine bedrifter andre til at tage våben op til støtte for vores kamp mod Svøben."},
  [9386] = {n="Et Lys på Mørke Steder", l="Find og rør ved bålene, der er placeret i Sortklippe-spiret, Rædselshammeren, Skolomance og Stratholm, og tal derefter med Festivalens Flammevogter.", d="En ivrig en, er du ikke? Hvis du er villig til at træde ned i dybet endnu en gang, belønner jeg dig gerne.\n\nSøg de bål, der brænder i Stratholm, Skolomance, Rædselshammeren og selve Sortklippe-spirets haller; jeg ser frem til din tilbagevenden, <Name>."},
  [65593] = {n="Elskendes Hjerter", l="Bring hjerterne fra Avelina Lilje og Isaac Perlesøn til Carendin Halgaar i De Fordømtes Tempel.", d="En incubus lokkes af elskendes hjerter, og den mest smertefulde kærlighed skaber det mest uimodståelige lokkemiddel.\n\nMin spejlskuning har afsløret to, der vil egne sig fortrinligt.\n\nI Sølvfyrreskoven leverer Avelina Lilje sine skrædderydelser til de faldne troldmænd i Ambermølle. I Ødemarken håber Isaac Perlesøn at sætte sit præg i den kystnære by Skralleby.\n\nDe slider i hver sin ende af verden, og alligevel længes deres hjerter kun efter hinanden. Bring disse hjerter til Carendin.", p="Ah, <Name>, du er tilbage. Lykkedes det dig at skaffe elskendes hjerter?", c="Som ventet. Fortrinligt udført, <Name>.\n\n\n\nIdioter."},
  [65597] = {n="Det Bindende", l="Ved hjælp af elskendes hjerter skal du tilkalde og tæmme en incubus, og derefter returnere elskendes hjerter til Carendin Halgaar i Magikvarteret i Undergrunden.", d="Tiden er endelig kommet. Bring hjerterne til tilkaldelsescirklen nedenfor. Læg dem i midten, og fremkald incubussen.\n\nDæmonen vil ikke være tilfreds, når den indser, at du har lokket den ind i en fælde. Lad dig ikke narre af dens forførelse, <Name>. Du skal tæmme den fuldstændigt.\n\nKun da kan jeg lære dig besværgelsen til at binde den til din vilje.", p="Incubussen besidder krigerisk styrke, men dens illusoriske charme er dens stærkeste våben. Svigter du blot et øjeblik, griber dæmonen chancen til at forhekse dig.\n\nLad den ikke, <Name>.", c="Imponerende. Meget imponerende. Sajaaderne specialiserer sig i at jage dødelige. Mange en <Class> har troet, at de var stærke nok til at befale en, kun for selv at ende med at blive befalet.\n\nDenne prøvelse knækkede dig ikke, <Name>, og din indsats har fortjent din belønning. Jeg vil lære dig besværgelsen til at fremkalde incubussen."},
  [65601] = {n="Kærlighed Gør Ondt", l="Tal med Magnar i Orgrimgrad.", d="En sajaad-han kaldes en incubus. Et væsen af dyb ondskab og enestående sind.\n\nDæmonen skal lokkes ind i vores verden med en lokkende genstand - en genstand, der repræsenterer stor kærlighed og hengivenhed.\n\nHvis du stoler på en blind mand til at lede dig, <Name>, så lyt. Øst for Skyggeklyngen, langs hovedgaden i Orgrimgrad, bor Magnar. Han længes efter sin elskedes tilbagevenden, Krillet.\n\nSøg ham op. Han vil bede dig finde noget kostbart. Det er nøglen, som du skal bringe til Gan'rul.", c="Hvem har fortalt dig om Krillet? Har du kommet med nyheder? Du må hellere ikke lege med mig..."},
  [65603] = {n="Det Bindende", l="Ved hjælp af træfiguren skal du tilkalde og tæmme en incubus, og derefter returnere træfiguren til Gakin Mørkbinderen i Det Slagtede Lam.", d="Tiden er kommet. Tag figuren og stig ned i krypterne nedenunder. En tilkaldelsescirkel er blevet forberedt, og du skal placere figuren i dens midte.\n\nDerefter åbnes porten, og incubussen træder ind i vores verden.\n\nEn sajaad må ikke undervurderes. Dæmonen vil ikke tøve med at angribe, når den gennemskuer dit påfund. Du må trække på alt, hvad du er blevet lært, for at besejre den.\n\nLykkes det dig, så vend tilbage til mig, og jeg binder væsenet til din vilje. Mislykkes du, er din sjæl forbrudt.", p="Incubussen vil forsøge at sænke din vagtsomhed gennem forførelse og bedrag. Dæmonen er dygtig til at svinge menneskers hjerter.\n\nHusk, at alt, den måtte tilbyde dig, er falskt. For dæmonen er du blot bytte.", c="Ikke dårligt, <Name>. Du har overvundet udyret, og din vilje er stadig uknækket.\n\nMange en <Class> har troet sig stærk nok til at binde en sajaad, kun for at blive dæmonens næste måltid i stedet. Jeg er glad for at se, at du ikke er så tåbelig.\n\nSe nøje efter, så lærer jeg dig påkaldelsen, så du kan kalde på din nyligt bundne incubus."},
  [65604] = {n="Det Bindende", l="Ved hjælp af det visnede tørklæde skal du tilkalde og tæmme en incubus, og derefter returnere det visnede tørklæde til Gan'rul Blodøje i Orgrimgrad.", d="Ja... jeg ser. Jeg fornemmer de resterende følelser bundet i disse tråde. Kærlighed er vævet ind i dens sting. Incubussen vil ikke kunne modstå.\n\nTag dette med til tilkaldelsescirklen i Neerus telt, <Name>. Fremkald en ond incubus, og vis den derefter din mestring. Forvent ikke, at den lader sig tæmme stille og roligt. Gør din magi klar, og forbered dig på kamp. At undervurdere en dæmon har været mangen hekses sidste fejltagelse.\n\nNår du har besejret den, skal du bringe klædet tilbage til mig. Jeg vil fortælle Magnar, hvad du fandt.", p="Sajaaderne er herskere over sind og plageånder for sjæle. Deres skikkelse fylder hjertet med glæde og efterlader dig forsvarsløs, når de river dit kød op med pisk og klo.\n\nLad dig ikke friste af incubussens charme, <Name>. Slå den hurtigt ned, og lad det være gjort.", c="Hah! Sejrrig, som forventet!\n\nIncubussen er tæmmet, og det vil være mig en fornøjelse at lære dig at fremkalde dæmonen. Din styrke vokser, og jeg tvivler ikke på, at dette blot er et trin på vejen til endnu større magter.\n\nJeg vil returnere tørklædet til Magnar. Jeg har kendt den ork i mange år, og aldrig havde jeg troet, at han ville holde så meget af nogen, som han holdt af Krillet.\n\nDet er en påmindelse om, hvad der skiller os fra dæmonerne. Vi bruger deres mørke, men de vil aldrig bruge os."},
  [66294] = {n="Bog om Dødssten", l="Bring Bog om Dødssten til Ærkemager Tarsis Kirmoldir i Naxxrammas.", d="Du åbner den gamle og forvitrede tome og opdager tekst, der beskriver et nekromantisk ritual. Måske vil Ærkemager Tarsis være interesseret i at få denne information."},
  [76156] = {n="Forfølg med Jordmoderen", l="Snig dig ind i Ventureselskabets mine sydøst for Tordenklippe, saml 5 Havium-minesprængladninger fra vogne med sprængstoffer, og bring dem derefter til Boarton Skyggetotem i Tordenklippe.", d="Jeg fornemmer et skjult talent for de subtile kunster i dig, sjaman. Brug denne maske til at infiltrere den nærliggende mine hos Ventureselskabet og stjæle deres forsyninger. Den lyder måske ikke som en overbevisende forklædning, men en dygtig snigmorder kan snige sig forbi enhver vagt med intet andet end et vindende smil og en snedig afledning. Jeg tror, at denne evne også ligger i dig.", p="Vi må arbejde på dine snigskjulsfærdigheder, <Class>. Jeg hørte dig nærme dig, så snart du satte fod på højsletten.", c="Hmm... måske er forklædninger ikke din styrke."},
  [76160] = {n="Forfølg med Jordmoderen", l="Saml 8 Vindraseri-kogler nord for Tordenklippe, brug dem sammen med Morter og Stødel, og vend derefter tilbage til Boarton Skyggetotem i Tordenklippe med resultatet.", d="Jeg taler til dig fra din fremtid, hvor Horden står over for trusler, du ikke kan forestille dig. Eftersom de andre ikke kan se mig, stoler jeg på, at du lærer mine færdigheder og videregiver dem til stammen.\n\nMåske ligger dine evner i gifte, ikke forklædninger. Harpyerne mod nord yngler i et træ, der producerer en harpiks med stærk giftighed. Saml de faldne kogler omkring rederne, og knus dem derefter til en salve. Når salven påføres et klinge, vil den brænde din modstanders sår ind i kødet og forvandle deres blod til salt.", p="Vær forsigtig med salven, når du er færdig, <Class>. Selv hudkontakt kan være ret smertefuld.", c="<Class>, dette er ikke den giftige salve, jeg bad om. Det, du har bragt mig, er pinjekernesmør. Er du sikker på, at du fulgte mine anvisninger?\n\nDet vil være langt mere nyttigt smurt på et stykke krydderbrød end på en dolk. Dog ville du være ret formidabel over for en fjende med nøddeallergi."},
  [76240] = {n="Forfølg med Jordmoderen", l="Køb eller fang en rå strålende småfisk, og brug derefter Knivsættet til at filetere den foran Boarton Skyggetotem i Tordenklippe.", d="Jeg har en sidste idé, der måske fører os til succes. Jeg fornemmer stadig et skjult talent i dig, men lad os forsøge at lokke det frem på en mindre direkte måde.\n\nGå og skaf en rå strålende småfisk, og bring den hertil. Brug disse dolke til at rense og filetere den. Tænk ikke for meget over det - gør det, der falder dig naturligt.", p="Har du noget til mig?", c="Det var et ganske syn, <Class>. Ikke den snigmorderiske præcision, jeg håbede på, men du besidder en imponerende ambidekstri.\n\nJeg kan se nu, at du ikke bliver den, der lærer mit folk de subtile kunster, men der er én ting, jeg kan lære dig. Held og lykke på dine rejser, <Class>. Horden får brug for helte som dig."},
  [77568] = {n="En Jægers Styrke", l="Besejr Githyiss den Usle i Skyggetråd-hulen og genvind den tabte rune. Lær runen, og rapportér derefter tilbage til Ayanna Evervandrer i Skyggedalen.", d="En jæger henter styrke fra sin forbindelse til og respekt for alle skabninger, ikke kun sine kæledyr. Du vil jage og slagte mange bæster i Alliancens tjeneste, men selv i kamp skal du respektere din fjende.\n\nMin forrige lærling brugte en mystisk rune til at forbedre sine evner, men tog dumt nok til at øve sig på den største af edderkopperne i hulen mod nord, et væsen vi har kaldt Githyiss den Usle. Hendes ringeagt førte til hendes undergang.\n\nSlå Githyiss - men undervurder ikke dens styrke.", p="Når du har slået Githyiss, så genvind runen og lær dens magi.", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77571] = {n="Kaldoreiernes Relikvier", l="Genvind relikvien fra grellingerne i Skyggedalen. Følg relikviens vejledning for at lære en ny evne, og rapportér derefter tilbage til Mardant Stærkeeg.", d="Nattebørn er et gammelt folk, og vores tabte relikvier kan findes over hele Azerot. Gennem disse relikvier kan åndene lære dig måder at styrke din forbindelse til Drømmen på.\n\nGrellingerne har stjålet en sådan relikvie. Slå dem ihjel og hent relikvien, og følg dens vejledning for at lære en ny kampteknik. Vend tilbage til mig, når du har gjort dette.", p="Hvad har relikvien lært dig?", c="Godt gået, <Name>. Hvis du påfører runen, du har lært, dit udstyr, vil den give dig kraftfulde nye evner.\n\nSøg efter flere af vores tabte relikvier på din rejse."},
  [77573] = {n="Arbejde i Anden Etage", l="Hent runen fra den skjulte afgud, og brug den til at lære en ny evne. Vend bagefter tilbage til Frahun Skyggehvisker.", d="Jeg har forberedt en træningsøvelse til dig, <Name>. Der står en afgud af en ugle på taget af denne bygning. Du burde kunne se den fra den sydlige indgang. Inde i afguden er et skjult rum, der indeholder en indgraveret rune.\n\nFind vej op på taget, find og indprent runen, der er gemt i afguden, og vend tilbage til mig.", p="Har du fundet runen?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77574] = {n="Meditation over Elunie", l="Knæl ved månebrønden og mediter over Elunie, og brug derefter erindringen til at lære en ny evne. Vend bagefter tilbage til Sjanda i Skyggedalen.", d="At slutte sig til Alliancen har styrket vores folk, men vi må ikke glemme, at vi er Kaldorisk. Vores forbindelse til Elunie er kernen i vores væsen.\n\nRyd dit sind, <Name>, og fokusér på min stemme. Jeg vil dele en gammel erindring fra vores art med dig. Gå til månebrønden mod nord, og knæl i de hellige vande for at meditere over Elunies mysterier. Når du har samlet dine tanker, vil du kunne forstå denne erindring og lære en ny teknik. Vend tilbage til mig, når du har gjort dette.", c="Elunie vil sandsynligvis give dig flere erindringer på din rejse. Du kan meditere ved månebrøndene over hele Azerot for at rense dine tanker og tolke disse erindringer.\n\nAt forstå mere komplekse syner kan kræve hjælp fra vores medpræster i Alliancen. Vær ikke bange for at lære af deres tro, <Name>. Tyrande lærer, at det Hellige Let, menneskene tilbeder, og Elunes Lys er nært beslægtede."},
  [77575] = {n="Midt i de Skyggefulde Spind", l="Slå netskov-edderkopper ihjel i Skyggetråd-hulen og genvind den tabte rune. Lær runen, og rapportér derefter tilbage til Alyisia i Skyggedalen.", d="Alliancens krigere har meget at lære dig, men du må også selv søge nye teknikker.\n\nDer er en hule mod nord, som er plaget af netskov-edderkopper. En anden spirende kriger gik ind i hulen for et stykke tid siden og er aldrig vendt tilbage. Han eksperimenterede med at indgravere mystiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind runen blandt edderkopperne, og lær denne teknik selv.", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77582] = {n="En Prøve i Form", l="Find det skjulte lager i klipperne bag Brask. Lær runen i det, og rapportér derefter tilbage til Brask i Prøvernes Dal.", d="Frem for alt skal en kriger fra Horden have en stærk krop. På din rejse vil du gennemgå mange prøver i udholdenhed og udthvilethed.\n\nDertil har jeg gemt et lager blandt klipperne bag mig. Du kan se det, hvis du står ved bålet midt i landsbyen. At nå det bliver ingen let bedrift. Inde i lageret ligger en rune med stor kraft.\n\nDin prøve er at finde denne rune og vende tilbage, når du har lært dens hemmeligheder.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77583] = {n="Oppe på Klipperne", l="Find det skjulte lager i klipperne omkring Prøvernes Dal. Lær runen i det, og rapportér derefter tilbage til Rvag i Hulen.", d="Jeg har forberedt en træningsøvelse til dig, <Name>. Jeg har gemt et lager blandt klipperne i nærheden. Du kan se det, hvis du står ved bålet midt i landsbyen. Inde i lageret ligger en rune med stor kraft.\n\nDin prøve er at skaffe denne rune og vende tilbage, når du har lært dens hemmeligheder.", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77584] = {n="Jagten på Runen", l="Find den tabte rune ved at slå skorpider ihjel i Prøvernes Dal. Lær runens kraft, og rapportér derefter tilbage til Jen Sahnsen.", d="En jæger henter styrke fra sin forbindelse til den naturlige verden. På din rejse vil du spore dit bytte gennem alle slags barske terræner og overleve udelukkende med din snedighed.\n\nFor ikke længe siden mislykkedes en anden spirende jæger desværre i dette. Han gav sig ud for at jage skorpider og er aldrig vendt tilbage. Han eksperimenterede med at indgravere mystiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind hans rune blandt skorpiderne i nærheden, og vend tilbage, når du har lært dens hemmeligheder.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77585] = {n="Kraftens Ikoner", l="Find det stjålne ikon ved at slå skorpider ihjel i Prøvernes Dal. Lær dets kraft, og rapportér derefter tilbage til Skrikrik.", d="Shamanisme er en gammel praksis, <Name>. Mange artefakter, fyldt med åndelig energi, kan findes over hele Azerot. Jeg havde for nylig selv opdaget et ikon med betydelig kraft, men det blev stjålet af de irriterende skorpider.\n\nEn af dem bærer sikkert rundt på det og tror, at det er en blank kuriositet, der kan bruges til at pynte deres rede.\n\nNår du finder ikonet, skal du lære dets kraft og vende tilbage til mig.", p="Har du fundet ikonet, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77586] = {n="Stjålet Kraft", l="Find den stjålne rune inde i Brændende Klinge-hekseriet. Lær dens kraft, og rapportér derefter tilbage til Nartøk i Hulen.", d="Jeg har eksperimenteret med en ny form for magi - en rune, der kan kanalisere dæmoniske energier for at drive kraftfulde besværgelser. Jeg ville dele denne kraft med dig, men den blev stjålet af en af de irriterende Brændende Klinge-familiarer.\n\nGå til deres hekseri mod nord, og se, om du kan finde min rune gemt blandt deres ejendele. Efter min erfaring gemmer familiarerne tit deres bytte på svært tilgængelige steder.\n\nNår du har fundet runen, skal du lære dens magi og rapportere tilbage til mig. Jeg vil gerne se mit eksperiment sat i brug", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77587] = {n="Kraftens Ikoner", l="Find det stjålne ikon ved at slå skorpider ihjel i Prøvernes Dal. Lær dets kraft, og rapportér derefter tilbage til Skrikrik.", d="Shamanisme er en gammel praksis, <Name>. Mange artefakter, fyldt med åndelig energi, kan findes over hele Azerot. Jeg havde for nylig selv opdaget et ikon med betydelig kraft, men det blev stjålet af de irriterende skorpider.\n\nEn af dem bærer sikkert rundt på det og tror, at det er en blank kuriositet, der kan bruges til at pynte deres rede.\n\nNår du finder ikonet, skal du lære dets kraft og vende tilbage til mig.", p="Har du fundet ikonet, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77588] = {n="En Prøve i Form", l="Find det skjulte lager i klipperne bag Brask. Lær runen i det, og rapportér derefter tilbage til Brask i Prøvernes Dal.", d="Frem for alt skal en kriger fra Horden have en stærk krop. På din rejse vil du gennemgå mange prøver i udholdenhed og udthvilethed.\n\nDertil har jeg gemt et lager blandt klipperne bag mig. Du kan se det, hvis du står ved bålet midt i landsbyen. At nå det bliver ingen let bedrift. Inde i lageret ligger en rune med stor kraft.\n\nDin prøve er at finde denne rune og vende tilbage, når du har lært dens hemmeligheder.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77590] = {n="Barsk Terræn", l="Find den tabte rune ved at slå skorpider ihjel i Prøvernes Dal. Lær runens kraft, og rapportér derefter tilbage til Jen Sahnsen.", d="En jæger henter styrke fra sin forbindelse til den naturlige verden. På din rejse vil du spore dit bytte gennem alle slags barske terræner og overleve udelukkende med din snedighed.\n\nFor ikke længe siden mislykkedes en anden spirende jæger desværre i dette. Han gav sig ud for at jage skorpider og er aldrig vendt tilbage. Han eksperimenterede med at indgravere mystiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind hans rune blandt skorpiderne i nærheden, og vend tilbage, når du har lært dens hemmeligheder.", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77592] = {n="Oppe på Klipperne", l="Find det skjulte lager i klipperne omkring Prøvernes Dal. Lær runen i det, og rapportér derefter tilbage til Rvag i Hulen.", d="Jeg har forberedt en træningsøvelse til dig, <Name>. Jeg har gemt et lager blandt klipperne i nærheden. Du kan se det, hvis du står ved bålet midt i landsbyen. Inde i lageret ligger en rune med stor kraft.\n\nDin prøve er at skaffe denne rune og vende tilbage, når du har lært dens hemmeligheder.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77616] = {n="Den Tabte Rune", l="Find den tabte rune inde i Ekkoryg-minen, og brug den til at lære en ny evne. Rapportér derefter tilbage til Lane Beskære i Nordshire.", d="Alliancens krigere har meget at lære dig, men du må også selv søge nye teknikker.\n\nEn anden ung kriger begav sig for nylig ind i Ekkoryg-minen. Hun eksperimenterede med at indgravere mystiske runer i sit udstyr for at forbedre sin kampevne.\n\nJeg mistænker, at hun blev overvældet, da kobolderne tog minen. Find runen blandt kobolderne, og lær denne teknik selv.", p="Fandt du runen?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77617] = {n="Lysets Relikvier", l="Hent helligbogen, og følg dens vejledning for at lære en ny evne. Vend derefter tilbage til Broder Sammuel i Nordshire.", d="Lysets relikvier kan findes over hele Azerot. Disse relikvier - især helligbøgerne, der har vejledt vores orden siden dens grundlæggelse - kan hjælpe dig med at styrke din forbindelse til Lyset.\n\nÉn sådan helligbog blev opbevaret i klosterets arkiver, men den er blevet stjålet af Defias-banditterne mod øst. Hent helligbogen, studér den og følg dens vejledning for at lære en ny kampteknik. Vend tilbage til mig, når du har gjort dette.", p="Hvad har helligbogen afsløret for dig, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen, du har lært, dit udstyr, vil den give dig kraftfulde nye evner.\n\nSøg efter flere af disse relikvier på din rejse."},
  [77618] = {n="Tredobbelt Stjålet", l="Genvind den tabte rune fra Defias-lejrene, og brug den til at lære en ny evne. Vend derefter tilbage til Jorik Kærridan i Nordshire.", d="Jeg skammer mig over at indrømme det, <Name>, men de Defias-idioter fik overtaget over mig. De stjal en magisk rune, som jeg... øh, 'lånte' fra klosterets arkiver. Jeg regnede med, at den ville give mig en slags fordel i en knibe, men jeg kunne ikke finde ud af, hvordan den virkede.\n\nTag dig en tur mod øst og se, om du kan snuppe den tilbage fra deres lager, vil du? Og prøv selv at bruge runen, når du finder den. Du virker som en bogorm. Ingen krænkelse.", p="Noget held, <Name>?", c="Et fint stykke tyveri der, <Name>. Betragt den rune som en gave fra undertegnede.\n\nHvis Broder Paxton spørger, har vi aldrig haft denne samtale, ik'?"},
  [77619] = {n="Meditation over Lyset", l="Slå kobolder ihjel i Ekkoryg-minen for at modtage en erindring. Knæl inde i Nordshire-klosteret for at meditere over Lyset, og brug derefter erindringen til at lære en ny evne. Vend bagefter tilbage til Præstinde Anetta.", d="Lyset har vist mig din fremtid, hvor du kæmper mod kobolderne i Ekkoryg-minen. Inde i minen vil Lyset give dig en erindring om fortiden. Når den er blevet åbenbaret for dig, skal du vende tilbage til klosteret og knæle inde i disse haller for at meditere over Lysets mysterier.\n\nNår du har samlet dine tanker, vil du kunne forstå denne erindring og lære en ny teknik. Vend tilbage til mig, når du har gjort dette.", p="Hvad har Lyset åbenbaret for dig?", c="Når Lyset åbenbarer flere syner for dig, kan du altid meditere ved hellige steder for at rense dine tanker og overveje disse mysterier.\n\nJeg har også set i et syn, at din vej vil føre dig til at stå i forbindelse med vores alviske allierede i Kalimdør. At lære mere om deres særegne månedyrkelsesritualer kan en dag hjælpe os med også at føre dem til Lyset."},
  [77620] = {n="Besværgelsesforskning", l="Genvind forskningsnoter fra Defias-banditterne, og brug dem til at lære en ny besværgelse. Vend derefter tilbage til Kheldén Brygmand i Nordshire.", d="Jeg vil lære dig, hvad jeg kan, <Name>, men din egen forskning vil føre til forbløffende kraft. At studere noter efterladt af Azerots største ærkemagikere er et fortrinligt sted at begynde. Klosterets arkiver plejede at indeholde et utal af arkane forskningsnoter, men de blev stjålet af Defias-agenter.\n\nGenvind besværgelsesnoterne fra banditterne mod øst, og brug denne grundbog til at tyde dem. Vend tilbage til mig, når din forskning er lykkedes.", p="Hvordan skrider din forskning frem?", c="Godt gået, <Name>. Tag disse Forståelsesamuletter. De vil hjælpe dig med at tyde alle yderligere arkane skrifter, du finder.\n\nFortsæt med at søge efter besværgelsesnoter over hele Azerot, og brug dem til at fremme din forskning. Hvis du får brug for flere amuletter, så besøg en reagenshandler."},
  [77621] = {n="Stjålet Kraft", l="Genvind runen fra Defias-lejrene mod øst, og brug den til at lære en ny evne. Vend derefter tilbage til Drusilla Den Salte i Nordshire.", d="Jeg har eksperimenteret med en ny form for magi - en rune, der kan kanalisere dæmoniske energier for at drive kraftfulde besværgelser. Jeg ville dele denne kraft med dig, men mine noter blev stjålet i nat. Jeg mistænker, at banditterne, der kalder sig 'Defias', står bag.\n\nTag mod øst, og se, om du kan finde min rune gemt blandt deres ejendele. Lær dens magi, og rapportér tilbage til mig. Jeg vil gerne se mit eksperiment sat i brug.", p="Nå? Er der fremskridt?", c="Du ser ud til at have taget godt imod denne nye magi, <Name>. Find flere runer som denne, og indgraver dem i dit udstyr, så du kan bruge nye evner mod dem, der vil modarbejde dig.\n\nEn dag overgår din kraft måske endda min egen."},
  [77642] = {n="Loaernes Visdom", l="Knæl ved Loa-alteret i Sen'jin-landsbyen. Kommuniker med Loa-ånden, og brug derefter erindringen til at lære en ny evne. Vend bagefter tilbage til Ken'jaj i Prøvernes Dal.", d="At slutte sig til Horden har givet vores folk et trygt hjem, <Name>, men vi må huske, at det er Loaerne, der altid vogter over os.\n\nRyd nu dit sind, og jeg vil dele en gammel erindring med dig. Gå til Loa-alteret i Sen'jin-landsbyen, og knæl foran det for at kommunikere med den store Loa-ånd. Når du har modtaget Loaernes visdom, vil du forstå den erindring, jeg har givet dig. Gennem denne forståelse vil du opdage en ny kraft.\n\nVend tilbage til mig, når du har gjort dette.", p="Hvad har Loaerne lært dig, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nLoaerne vil give dig mange flere erindringer på din rejse. Du kan bede ved Loa-altre over hele Azerot for at rense dine tanker og tolke dem, ligesom du lige har gjort.\n\nAt forstå mere komplekse syner kan kræve hjælp fra andre præster i Horden. Vær ikke bange for at lære af deres tro, <Name>. Loaernes visdom findes i alle ting."},
  [77643] = {n="Besværgelsesforskning", l="Find de stjålne besværgelsesnoter inde i Brændende Klinge-hekseriet, og brug dem til at lære en ny evne. Vend bagefter tilbage til Mai'aa i Prøvernes Dal.", d="Som magiker vil forskning i det arkane føre dig til forbløffende kraft. At studere noter efterladt af Azerots største magikere er et fortrinligt sted at begynde. Jeg havde for nylig selv opdaget nogle, men de blev stjålet af de irriterende Brændende Klinge-familiarer.\n\nGenvind besværgelsesnoterne fra hekseriet mod nord, og brug denne grundbog til at tyde dem. Vend tilbage, når din forskning er lykkedes.", p="Hvordan skrider din forskning frem, <Name>?", c="Godt gået, <Name>. Tag disse Forståelsesamuletter. De vil hjælpe dig med at tyde alle yderligere arkane skrifter, du finder.\n\nFortsæt med at søge efter besværgelsesnoter over hele Azerot, og brug dem til at fremme din forskning. Hvis du får brug for flere amuletter, så besøg en reagenshandler."},
  [77648] = {n="Taurernes Relikvier", l="Genvind den stjålne relikvie fra Brombærklinge-kløften. Følg relikviens vejledning for at lære en ny evne, og rapportér derefter tilbage til Gart Tågeløber i Narache-lejren.", d="Taurerne er et gammelt folk, <Name>, og vores tabte relikvier kan findes over hele Azerot. Gennem dem kan åndene lære dig måder at styrke din forbindelse til Drømmen på.\n\nDe Børsterygge-tornesvin har stjålet en sådan relikvie fra os. De har sandsynligvis gemt den væk i Brombærklinge-kløften. Hent relikvien, og følg dens vejledning for at lære en ny kampteknik. Vend tilbage til mig, når du har gjort dette.", p="Hvad har relikvien lært dig, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen, du har lært, dit udstyr, vil den give dig kraftfulde nye evner.\n\nSøg efter flere af vores tabte relikvier på din rejse."},
  [77649] = {n="En Jægers Styrke", l="Find den savnede rune ved at slå Børsterygge-kampsvin ihjel i Brombærklinge-kløften. Brug runen til at lære en ny evne, og rapportér derefter tilbage til Lanka Fjernskud i Narache-lejren.", d="Jægere er centrale i taurernes livsform, <Name>. Vores folk ser op til os som både beskyttere og forsørgere. Mange gange på din rejse vil du være alene på fjendtligt territorium og kun overleve med din snedighed.\n\nFor ikke længe siden eksperimenterede en spirende jæger med mystiske runer for at forbedre sin kampevne. Han gav sig ud for at afprøve sine nye evner på Børsterygge-kampsvinene mod øst, men er aldrig vendt tilbage.\n\nFind hans rune, og brug den til at lære en ny kampteknik. Vend tilbage til mig, når du har gjort det.", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77651] = {n="Ind i Tornene", l="Genvind den tabte rune fra Brombærklinge-kløften. Brug runen til at lære en ny evne, og rapportér derefter tilbage til Harrut Tordenhorn i Narache-lejren.", d="Krigerne i Horden har meget at lære dig, <Name>, men du må også selv søge nye teknikker.\n\nSom du måske ved, er der en gruppe fjendtlige tornesvin mod øst. En anden spirende kriger begav sig ind på deres territorium for et stykke tid siden og er aldrig vendt tilbage. Han eksperimenterede med at indgravere mystiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind runen blandt tornesvinene, og lær denne teknik selv. Vend tilbage til mig, når du har gjort det.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer rundt omkring i Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77652] = {n="Kraftens Ikoner", l="Hent det tabte ikon fra Børsterygge-shamanerne i Brombærklinge-kløften. Lær dets kraft, og rapporter tilbage til Harrut Tordenhorn i Narache-lejren.", d="Shamanisme er en gammel praksis, <Name>. Mange artefakter, fulde af åndelig energi, kan findes over hele Azerot. Jeg havde selv for nylig opdaget et ikon med betydelig kraft, men det blev stjålet af tornesvinene.\n\nTag til deres område mod øst, og find det stjålne ikon. Det bæres sandsynligvis af en af deres egne shamaner, som forsøger at forstå dets hemmeligheder.\n\nNår du har fundet ikonet, skal du lære dets kraft og vende tilbage til mig.", p="Har du fundet ikonet, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77655] = {n="Den Tabte Rune", l="Find den tabte rune, som en Frostmanke-troll bærer på i Kuldekam-dalen. Brug den til at lære en ny evne, og rapporter derefter tilbage til Thran Kornmand i Ambolmar.", d="Krigerne i Alliancen har meget at lære dig, <Name>, men du må også søge nye teknikker på egen hånd.\n\nDer er en hule fuld af Frostmanke-trolde syd for her. En anden spirende kriger gik derind for noget tid siden, men vendte aldrig tilbage. Han eksperimenterede med at indgrave magiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind runen blandt trollene, en af dem bærer den sandsynligvis, og lær teknikken selv. Vend tilbage til mig, når du har gjort det.", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77656] = {n="Den Tabte Rune", l="Find den tabte rune, som en Frostmanke-troll bærer på i Kuldekam-dalen. Brug den til at lære en ny evne, og rapporter derefter tilbage til Thran Kornmand i Ambolmar.", d="Krigerne i Alliancen har meget at lære dig, <Name>, men du må også søge nye teknikker på egen hånd.\n\nDer er en hule fuld af Frostmanke-trolde syd for her. En anden spirende kriger gik derind for noget tid siden, men vendte aldrig tilbage. Han eksperimenterede med at indgrave magiske runer i sit udstyr for at forbedre sin kampevne.\n\nFind runen blandt trollene, en af dem bærer den sandsynligvis, og lær teknikken selv. Vend tilbage til mig, når du har gjort det.", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77657] = {n="Lysets Relikvier", l="Hent den stjålne helligbog, som en Frostmanke-troll bærer på i Kuldekam-dalen. Følg dens vejledning for at lære en ny evne, og vend derefter tilbage til Bromos Grumsner i Ambolmar.", d="Lysets Relikvier kan findes over hele Azerot. Disse relikvier - især de helligbøger, der har vejledt vores orden siden dens grundlæggelse - kan hjælpe dig med at styrke din forbindelse til Lyset.\n\nVi havde en sådan helligbog i vores arkiv, men den blev stjålet af Frostmanke-trollene. Tyven bærer sandsynligvis stadig på den. Hent helligbogen, og følg dens vejledning for at lære en ny kampteknik. Vend tilbage til mig, når du har gjort dette.", p="Hvad har helligbogen åbenbaret for dig, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen, du har lært, på dit udstyr, vil den give dig kraftfulde nye evner.\n\nSøg efter flere af disse relikvier på dine rejser."},
  [77658] = {n="Tre Gange Stjålet", l="Hent den stjålne rune fra Frostmanke-trollenes hule i Kuldekam-dalen. Brug den til at lære en ny evne, og vend derefter tilbage til Solm Hårgrin i Ambolmar.", d="Jeg skammer mig over at indrømme det, <Name>, men de Frostmanke-rakkere fik mig på point. De stjal en magisk rune, som jeg... øh, 'lånte' fra skatkammeret. Jeg regnede med, at den ville give mig et forspring, så at sige, men jeg kunne ikke finde ud af, hvordan den virkede.\n\nTag til deres hule mod syd, og se, om du kan snuppe den tilbage fra deres lager, vil du? Når du finder den, så prøv selv at bruge runen. Du virker som en bogorm. Intet ondt ment.", c="Et fint lille tyveri der, <Name>. Betragt den rune som en gave fra din ven.\n\nHvis nogen spørger, har vi aldrig haft denne samtale, ja?"},
  [77659] = {n="Tre Gange Stjålet", l="Hent den stjålne rune fra Frostmanke-trollenes hule i Kuldekam-dalen. Brug den til at lære en ny evne, og vend derefter tilbage til Solm Hårgrin i Ambolmar.", d="Jeg skammer mig over at indrømme det, <Name>, men de Frostmanke-rakkere fik mig på point. De stjal en magisk rune, som jeg... øh, 'lånte' fra skatkammeret. Jeg regnede med, at den ville give mig et forspring, så at sige, men jeg kunne ikke finde ud af, hvordan den virkede.\n\nTag til deres hule mod syd, og se, om du kan snuppe den tilbage fra deres lager, vil du? Når du finder den, så prøv selv at bruge runen. Du virker som en bogorm. Intet ondt ment.", c="Et fint lille tyveri der, <Name>. Betragt den rune som en gave fra din ven.\n\nHvis nogen spørger, har vi aldrig haft denne samtale, ja?"},
  [77660] = {n="Vandring Gennem Hulerne", l="Hent den stjålne rune fra Frostmanke-trollenes hule i Kuldekam-dalen. Brug runen til at lære en ny evne, og rapporter derefter tilbage til Thorgas Grimsen i Ambolmar.", d="Jægere er et robust folkefærd, <Name>, selv blandt dværge. Vi drager ud over Azerot for at udforske ukendte lande og jage alle slags farligt og eksotisk bytte. Mange gange på din rejse vil du finde dig selv alene på fjendtligt territorium, og du overlever kun ved hjælp af dit snilde.\n\nFrostmanke-trollene har stjålet en rune med stor kraft fra os. De har sandsynligvis gemt den i deres hule mod syd. Hent runen, og brug den til at lære en ny kampteknik. Vend tilbage til mig, når du har gjort det.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77661] = {n="Meditation over Lyset", l="Find en erindring fra fortiden inde i en kiste ved trøl-lejren nær Ambolmar. Knæl derefter ved Lysets Alter i Ambolmar for at meditere over Lyset, og brug erindringen til at lære en ny evne. Tal bagefter med Branstock Khalder.", d="Lyset har vist mig din fremtid, <Name>, mens du kæmper mod trøllene mod sydvest. Inde i en kiste vil du finde en erindring om fortiden. Når du har fået den, skal du vende tilbage hertil og knæle ved Lysets Alter. Meditér over dets mysterier.\n\nNår du har samlet dine tanker, vil du kunne forstå denne erindring og lære en ny teknik. Tal med mig, når du har gjort dette.", p="Hvad har Lyset åbenbaret for dig, <Name>?", c="Når Lyset åbenbarer flere syner for dig, kan du altid meditere ved hellige steder for at rydde tankerne og overveje disse mysterier.\n\nJeg har også set i et syn, at din vej vil føre dig til at tale med vores alviske allierede i Kalimdør. At lære mere om deres mærkelige måneforgudelsesritualer kan en dag hjælpe os med også at lede dem til Lyset."},
  [77666] = {n="Stjålet Kraft", l="Hent runen fra flokken af trøl sydvest for Ambolmar, og brug den til at lære en ny evne. Vend derefter tilbage til Alamar Grum i Ambolmar.", d="Jeg har eksperimenteret med en ny type magi - en rune, der kan kanalisere dæmonisk energi for at drive kraftfulde besværgelser. Jeg ville gerne dele denne kraft med dig, men den blev stjålet af et af de irriterende trøl.\n\nDer er en lejr med de Klippekæbe-skadedyr mod sydvest. Se, om du kan finde min rune gemt blandt deres ejendele, sandsynligvis i en kiste af en slags. Når du finder den, skal du lære dens magi og rapportere tilbage til mig. Jeg vil gerne se mit eksperiment sat i brug.", p="Nå, <Name>? Nogen fremskridt?", c="Du ser ud til at have taget godt imod denne nye magi, <Name>. Find flere runer som denne, og indgrav dem i dit udstyr. Før denne kraft mod dem, der vil modarbejde dig.\n\nEn dag vil din kraft måske endda overgå min egen."},
  [77667] = {n="Besværgelsesforskning", l="Find de stjålne besværgelsesnoter i trøl-lejren sydvest for Ambolmar, og brug dem til at lære en ny evne. Vend bagefter tilbage til Gifte Nurribit i Ambolmar.", d="Som magiker vil forskning i det arkane føre dig til forbløffende kraft. At studere noter efterladt af Azeroths største magikere er et fremragende sted at begynde. Jeg havde selv for nylig fundet nogle, men de blev stjålet af de irriterende trøl mod sydvest.\n\nHent besværgelsesnoterne fra trøllenes lejr, og brug denne grundbog til at danne dig et indtryk af dem. Vend tilbage, når din forskning er lykkedes.", p="Hvordan skrider din forskning frem, <Name>?", c="Godt gået, <Name>. Tag disse Forståelsesamuletter. De vil hjælpe dig med at tyde alle de arkane skrifter, du finder.\n\nBliv ved med at søge besværgelsesnoter over hele Azerot, og brug dem til at fremme din forskning. Hvis du får brug for flere amuletter, så besøg en reagenssælger."},
  [77668] = {n="Den Tabte Rune", l="Find runen gemt i Natnet-Hulen, og brug den til at lære en ny teknik, og rapporter derefter tilbage til Dannal Stjerne i Dødsklokken.", d="Den Mørke Dames krigere har meget at lære dig, men du må også søge nye teknikker på egen hånd.\n\nEn anden kriger gik for nylig nordpå ind i Natnet-Hulen. Han eksperimenterede med at indgrave magiske runer i sit udstyr for at forbedre sin kampevne.\n\nJeg formoder, at han blev overvældet af edderkopperne, der hærger minen. Find runen blandt deres spindelvæv, og lær teknikken selv.", p="Hvad har du fundet?", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77669] = {n="Den Skarlagenrøde Rune", l="Lommetyv eller dræb Skarlagenrøde Konvertitter for at finde en rune, og brug den til at lære en ny evne. Vend bagefter tilbage til David Trøsen i Dødsklokken.", d="Hvem var du i livet, <Name>? En spion? En tyv? En kok, der var ekstra dygtig med en kniv? Uanset din fortid er det tid til at omfavne nye taktikker. De Forladtes skurke udnytter enhver fordel, der tilbydes dem.\n\nDe Skarlagenrøde Konvertitter mod øst kæmper, som om de aldrig har set kamp før, men Korstoget har udstedt dem magiske runer for at forbedre deres evner. Stjæl en af disse runer, lær dens magi, og vend derefter tilbage til mig.", p="Har du fundet runen, <Name>?", c="Godt gået, <Name>. Hvis du påfører runen på dit udstyr, vil den give dig kraftfulde nye evner.\n\nDer findes mange sådanne runer over hele Azerot. Søg dem op, for de vil hjælpe dig på din rejse."},
  [77670] = {n="Meditation over Udødeligheden", l="Knæl på kirkegården for at meditere over udødeligheden, og brug derefter runen til at lære en ny evne. Vend bagefter tilbage til Mørk Gejstlig Dyssten i Dødsklokkens kapel.", d="Jeg vil fremkalde en erindring om de levende for dit indre blik - det kan endda være din egen erindring. Gå til kirkegården ved siden af dette kapel og find, hvor dødens kulde er stærkest, og knæl derefter og fokusér dine tanker. Gennem fokus på udødelighedens mysterier vil du finde klarhed i denne erindring og lære en ny teknik. Vend tilbage til mig, når du har gjort dette.", p="Hvis du har svært ved at fokusere på døden, kunne du prøve at dø igen. Det er heller ikke sandsynligt, at det bliver permanent anden gang.", c="De levende klynger sig til Lyset af én grund - de frygter dødens glemsel. Som De Forladte har denne frygt ingen magt over dig længere. Selvom Lyset nu afviser selv dem blandt os, som engang var dets mest hengivne tilhængere, behersker vi mørke kræfter, der ligger hinsides dødens skygge.\n\nNår du bliver stærkere, anbefaler jeg, at du bruger tid sammen med Hordens trolde. Selvom deres kultur er primitiv, har de 'ånder', de ærer, en vis forbindelse til udødeligheden. De kan give indsigt i vores natur."},
  [77671] = {n="Besværgelsesforskning", l="Dræb Skarlagenrøde Novicer for at finde besværgelsesnoter og bruge dem til at lære en ny evne, og vend derefter tilbage til Isobel i Dødsklokken.", d="Arkanisterne fra Det Kongelige Apotekerselskab vier deres udødelighed til besværgelsesforskning i tjeneste for De Forladte. Eventyr kan være dit kald, men du kan tjene Den Mørke Dame ved at sikre og forske i de besværgelsesnoter, du finder på dine rejser.\n\nDræb Skarlagenrøde Korstog-novicerne, der har slået lejr nær Dødsklokken, og tag deres besværgelsesnoter. Brug denne grundbog til at tyde noterne og lære en ny besværgelse, og vend derefter tilbage til mig.", p="Hvad har du lært, <Name>?", c="Godt gået, <Name>. Tag disse Forståelsesamuletter. De vil hjælpe dig med at tyde alle de arkane skrifter, du finder.\n\nBliv ved med at søge besværgelsesnoter over hele Azerot, og brug dem til at fremme din forskning. Hvis du får brug for flere amuletter, så besøg en reagenssælger."},
  [77672] = {n="Den Tabte Rune", l="Hent runen fra Natnet-Hulen, og brug den til at lære en ny evne, og vend derefter tilbage til Maksimillion i Dødsklokken.", d="Jeg har eksperimenteret med en ny type magi - en rune, der kan kanalisere dæmoniske energier for at drive kraftfulde besværgelser. Jeg sendte en lærling for at teste runen mod edderkopperne i minen mod nord, men han er ikke vendt tilbage. Jeg formoder, at vi aldrig ser ham igen.\n\nMåske vil du vise dig mere modstandsdygtig. Tag til minen og hent runen fra edderkoppernes spindelvæv. Lær dens magi, og rapporter tilbage til mig.", p="Hvad har du fundet, <Name>?", c="Du ser ud til at have taget godt imod denne nye magi, <Name>. Find flere runer som denne, og indgrav dem i dit udstyr for at tage nye evner i brug mod dem, der vil modarbejde dig.\n\nEn dag vil din kraft måske endda overgå min egen."},
  [77690] = {n="En Lille Opgradering", l="Skaf Sortehåndens Ånde og Retfærdens Hånd.", d="Hilsen, min ærede <Class>-bekendt! Mit navn er Johan Krambod, verdensberømt rejsende og gådeløser! Har du aldrig hørt om mig? Det gør ikke noget! Jeg er her i Jernsmede på jagt efter to af de mest prestigefyldte smykkestykker, denne side af Azerot nogensinde har set! Det siges, at de danner en gåde!\n\nDesværre går ryget på, at de begge befinder sig i det farlige Sortklippebjerg! Ville en eventyrer af din kaliber vel ikke have problemer med at finde disse stykker for mig?"},
  [78088] = {n="Et Mærkeligt Artefakt", l="Fandt du noget i tårnet?", p="Fandt du noget i tårnet?", c="Du gjorde klogt i at bringe dette til mig, <Name>."},
  [78089] = {n="Råd fra Stormvind", l="Rådfør dig med Stormvinds paladiner om kuglen.", d="Jeg fornemmer en mørk kraft i denne kugle, men dens kilde undslipper mig. Vi har brug for råd fra Stormvinds paladiner. Bring kuglen til dem.", p="Bringer du nyheder fra Kalimdør?", c="<Undersøger kuglen med et bekymret udtryk>"},
  [78090] = {n="En Anden Mening", l="Find heksenes helligdom i Stormvind, og søg råd om kuglen.", d="Jeg er ikke sikker på, hvad jeg skal gøre ud af denne kugle, <Name>. Jeg tror, vi får brug for hjælp fra... en specialist.\n\nVi ved, at en heksesekt opererer fra Stormvind. Officielt afviser vi tilstedeværelsen af hekse i byen. Uofficielt kan deres viden dog være nyttig, når det gælder dæmoniske kræfter.\n\nFind en repræsentant for disse hekse, og søg deres mening om kuglen.", p="Du er langt fra katedralen, <Class>. Jeg håber, du indser, at du ingen autoritet har her.", c="Så Sølvhånden kræver min hjælp? Den bliver ikke billig."},
  [78091] = {n="Fortjen Dit Salt", l="Saml 14 Fremkalderens Salt fra Sortklippe-fremkaldere i Rødryg-bjergene, og vend derefter tilbage til Ursula Trådsen i Stormvind.", d="Jeg vil studere kuglen og fortælle dig, hvad jeg finder, men du må først gøre noget for mig.\n\nHekserne fra Sortklippe-klanen bruger særligt tilberedte salte til at forstærke deres fremkaldelsesritualer. Saml noget fra orkerne i Rødryg.\n\nNår du vender tilbage, vil jeg dele resultaterne af mine studier med dig.", p="<Hekseren studerer kuglen intenst>", c="Ah... saltene. Jeg havde helt glemt dem.\n\nDenne kugle er ulig noget, jeg nogensinde har set, <Name>."},
  [78092] = {n="Den Skal Ødelægges", l="Find en måde at ødelægge kuglen på.", d="Denne kugle er faktisk forbundet med en mægtig enhed, et sted hinsides det snoede Nether. Jeg kan ikke spå om dens natur, men jeg fornemmer, at dens opfattelse når gennem kuglen... og at den studerer mig til gengæld.\n\nJeg er tilbageholdende med at indrømme det, <Name>, men kuglen må ødelægges.\n\nDen synes næsten immun over for de fleste skader, men den kan måske være sårbar over for en mægtig dæmonherres våben. Jeg er usikker på, hvor du finder et sådant våben, men det er stadig din bedste mulighed.\n\nHeld og lykke, <Name>.", p="<Dit hår rejser sig, mens helvedesvæsenets energier omgiver dig>", c="<Du løfter kuglen op mod spydet>"},
  [78093] = {n="Tilbage til Delgren", l="Bring Kuglens Skår tilbage til Delgren.", d="<Kuglens knuste rester ligger for dine fødder. Delgren vil gerne se, at du har lykkedes.>", p="Fandt du en måde at ødelægge kuglen på?", c="Det er en lettelse, <Name>. Men det, der så til Azerot gennem den kugle... jeg har en fornemmelse af, at de ikke bliver glade for, at den er blevet ødelagt.\n\nTag dette som min tak for din indsats. Og... vær forsigtig."},
  [78114] = {n="Vild Vingedrage-tæmning", l="Bring en Hypnotisk Krystal og en Knudret Tryllestav af Vild Magi til Jixo Raketsen i Stenklippe-bjergene.", d="Har du set de Stolthedsvinge-vingedrager, der flyver rundt? Jeg vætter på, at folk ville betale gode penge for at se mig lave et saltoer på en af dem!\n\nDe er en besværlig flok, dog. Man kan ikke tæmme en nok til at ride på - for slet ikke at tale om højtflyvende kunststykker.\n\nJeg har hørt, at man kan lave en særlig tryllestav til at berolige dem. Jeg kunne nok endda gøre det selv. Alt, jeg skulle bruge, er en Hypnotisk Krystal og en Knudret Tryllestav af Vild Magi.\n\nNu er jeg ikke helt sikker på, hvor man skaffer disse, men vi kan tale om detaljerne senere.", p="Er der held med forsyningerne?", c="Flot arbejde! Nu er det tid til en lille feltprøve."},
  [78121] = {n="Tæmning af en Vild Vingedrage", l="Følg Jixo Raketsen, og se ham tæmme en vingedrage.", d="Nu hvor tryllestaven er lavet, er der kun én ting tilbage at gøre. Jeg skal tæmme mig selv en vingedrage!\n\nDu skal med, <Name>. Du får en plads på førsterækken til mit nyeste nummer!", c="Lad mig sige dig, <Name>, at det fald gjorde ondt endnu mere, end det så ud til. Jeg klarer mig, men jeg tror ikke, vingedragetæmning er noget for den gamle Jixo.\n\nMåske skulle jeg bare holde mig til de sikre numre, ved du? Kunststykker som at hoppe over en række på tyve gnomer på en gnomisk kopter. Folk æder den slags op.\n\nTag tryllestaven. Jeg har ingen brug for den mere. Og tag også dette med; en lille ekstra ting for alt besværet."},
  [78132] = {n="Drageslagterens Hjelm", l="Drageslagterens hjelm tilhørte engang en stor kommandant, der faldt i kamp. Det siges, at hans pinte sjæl stadig hjemsøger stedet for hans død.", p="Drageslagterens hjelm tilhørte engang en stor kommandant, der faldt i kamp. Det siges, at hans pinte sjæl stadig hjemsøger stedet for hans død.", c="Storartet arbejde, <Name>! Med dette er jeg et skridt nærmere min vej mod ære."},
  [78133] = {n="Drageslagterens Skjold", l="Rygtet fortæller, at Drageslagterens skjold er i besiddelse af en orkisk krigsherre. Han stjal det, da han plyndrede en menneskebebyggelse.", p="Rygtet fortæller, at Drageslagterens skjold er i besiddelse af en orkisk krigsherre. Han stjal det, da han plyndrede en menneskebebyggelse.", c="Prægtigt arbejde, <Name>! Med dette er jeg et skridt længere ad min vej til herlighed."},
  [78134] = {n="Drageslagterens Lanse", l="Drageslagterens lanse har skiftet hænder mange gange. Nu og da går rygtet om, at den dukker op i våbenhandler på det sorte marked. Måske er lansens nuværende tvivlsomme ejer villig til at skille sig af med den; for en pris.", p="Drageslagterens lanse har skiftet hænder mange gange. Nu og da går rygtet om, at den dukker op i våbenhandler på det sorte marked. Måske er lansens nuværende tvivlsomme ejer villig til at skille sig af med den; for en pris.", c="Prægtigt arbejde, <Name>! Med dette er jeg et skridt længere ad min vej til herlighed."},
  [78144] = {n="Alonzo Drageslagteren", l="Følg med Alonzo og slå dragen.", d="Tiden er kommet, <Name>. Jeg har iført mig rustning, der sømmer sig for en ægte Drageslagter! Du har været en stor hjælp.\n\nJeg må bede dig om at følge med mig nu, som min æresvæbner, og se mig besejre den store drage én gang for alle!", c="Jeg har gjort det, <Name>! Endelig er min fjende besejret!\n\nÅh, lyden af hugtand og metal; af skæl og klinge. Hvilken fare, hvilken spænding! Og gennem det hele rejser jeg mig som en mester.\n\nLad os heller ikke glemme dit ydmyge bidrag! Uden rustningen du hentede, havde jeg bestemt ikke besejret udyret.\n\nDu har været en fremragende væbner, <Name>. Måske vandrer du en dag selv den herlige ridderstig."},
  [78192] = {n="Lysets Hemmeligheder", l="Dræb 7 Forladte Urtesamlere og 9 Forladte Søgere i det nordvestlige Askedalen, og vend derefter tilbage til Maethra Slagehjerte i Darnassos.", d="Så du vil gerne lære mere om Lyset? Du er kommet til den rette dværg! Helin', slaain', beskyttin', jeg klarer det hele!\n\nHvad siger du til en praktisk lektion? Tag ud til Askedalen og sæt de Horde-zombier på plads, der opfører sig, som om stedet tilhører dem. Lyset er godt til mange en ting, men at blæse de udøde væk er mit yndlingsnummer!", c="Godt gået! Der er intet som at svie et par udøde for at få en i et religiøst humør, hva'?"},
  [78193] = {n="Lysets Hemmeligheder", l="Rejs til Stormvind By og tal med Højpræstinde Laurena i Lysets Katedral.", d="Nå, <Name>, lad os blive seriøse. Lyset er ikke en gudinde, du skal imponere, eller en ånd, du skal indynde dig hos. Det er i os alle! Alt du skal lære er, hvordan man mærker det.\n\nUnd dig selv en lille tur til Stormvind og besøg Lysets Katedral. Det er et godt sted at tage sig tid til at bede og lære Lyset at kende. Og arkitekturen er et syn værd!", c="Du behøver ikke bevise noget, <Name>. Lyset byder alle bønnfaldere velkommen i sin varme.\n\nBliv gerne i dette fristed, så længe du vil, og mediter over Lysets mysterier."},
  [78194] = {n="Elunies Hemmeligheder", l="Saml 10 Frygtindgydende Ulvepoter fra ulve i Skumringsskoven.", d="Det er forfriskende at se en <Race> interessere sig for Elunie. Selvom kaldorei er hendes yndlingsbørn, passer hun på alle Azerots folk. Som tak for hendes velsignelser passer vi på landet i hendes navn.\n\nJeg har for nylig fået kendskab til en forstyrrelse i naturens balance - rasende frygtindgydende ulve, set i Skumringsskoven. Vis din respekt for Elunies balance ved at tynde deres antal ud, og vend så tilbage til mig med bevis for dine gerninger.", p="Hvad har du at fortælle?", c="Jeg takker dig, <Name>. Balancen er stærkere takket være din indsats."},
  [78195] = {n="Elunies Hemmeligheder", l="Bring fiolen til Syrnøja ved Auberdins månebrønd.", d="Månebrøndene rummer Elunies velsignelse, men de er også et symbol på de forbindelser, vi alle deler. Tag denne fiol med vand fra Stormvinds månebrønd til den i Auberdin, på kysten af Kalimdør. Når vandene forenes, vil din ånd også forenes med kaldoreiernes.", c="<Syrnøja hælder fiolens vand i månebrønden>\n\nElunes gunst er med dig, <Name>. Når dine rejser fører dig til andre månebrønde, så stands et øjeblik, og du kan måske modtage hendes velsignelse."},
  [78196] = {n="Udødhedens Hemmeligheder", l="Saml 12 Skyggeblade fra elementarer i Skyggekrat i Askedalen.", d="Hvis du søger 'tro' eller 'tilbedelse' blandt de Forladte præster, vil du blive skuffet. Vi har set hinsides døden, og vi ved, at intet venter os der. Vores tro udspringer af kold erfaring, ikke naivt håb.\n\nErfaring... det er måske det, du har brug for. Saml skyggeblade fra sumpvæsnerne i Askedalen, og vend så tilbage til mig. Jeg har en ide, der måske kan besvare dine spørgsmål.", p="Har du samlet skyggebladene?", c="Vent et øjeblik, så forbereder jeg noget til dig..."},
  [78197] = {n="Udødhedens Hemmeligheder", l="Rejs til Gryde-bys kirkegård i Tirisfal-lysningerne og brug Tinkturen af Vækkende Død.", d="Alle De Forladte har set dødens rand. At se tilværelsen få en ende, uden guder hinsides... det lyder skræmmende, men i virkeligheden er det befriende. Vores vilje er vores egen, uden lydighed over for kræfter udenfor os selv.\n\nGå til kirkegården i Gryde-by og drik denne tinktur. Den tager dig til dødens rand og holder dig der. Mød intetheden med beslutsomhed, så finder du vej tilbage til de levende. Jeg kan ikke tænke på en bedre måde at dele, hvad det betyder at være Forladt.", p="Du forsøger at kalde på åndehealeren, men der lyder ingen lyd. Dens blik glider igennem dig uden anerkendelse.", c="Din rædsel føles fjern, mens tinkturen svækker båndet mellem din sjæl og dit sind. En evighed af intet strækker sig foran dig.\n\nEt øjeblik opfatter du hele Azerot, nutid og fremtid. Din skæbnes tråd trækkes ud af gobelinet og kastes til side uden at efterlade et spor. Verden fortsætter med at dreje uden at bemærke din fraværelse.\n\nLangsomt genvinder du sanserne, efterhånden som tinkturen fortager sig. Var det... sådan de Forladte har det hele tiden?"},
  [78198] = {n="Loaernes Hemmeligheder", l="Saml 14 Hillsbrad-menneskeknogler fra mennesker i Hillsbrad-forbjergene, og vend derefter tilbage til Baj'øra i Undergrunden.", d="De mægtige trolde-imperier hos vores forfædre blev bygget på loaernes styrke - ånder med stor magt, der hersker over hele Azerot. Vi tilbeder mange loaer i Mørkspyd-stammen, men hvis du har lyst til at dele vores tro, er der én især, der måske vil forhandle med dig.\n\nFørst skal du forberede et offer. Rejs til Tarren Mølle og slå tilbage mod de mennesker, der udfordrer Hordens krav på området. Saml deres dødes knogler og vend tilbage til mig.", p="Hvordan går kampen mod menneskerne?", c="Fremragende... disse levninger vil blive et fint offer."},
  [78199] = {n="Loaernes Hemmeligheder", l="Rejs til Ekkoøerne og brug offeret ved Bwonsømdis helligdom.", d="Tag offeret med mod syd, til Ekkoøerne. Langs øernes strande finder du en helligdom for Bwonsømdi, dødens loa. Et offer fra en Forladt vil uden tvivl vække hans opmærksomhed.\n\nJeg advarer dog dig, <Name>. Der er altid en pris at betale, når man forhandler med loaerne. Du ved måske ikke, hvad du giver afkald på nu, men Bwonsømdi opkræver altid sin gæld til sidst.", p="Luften omkring dig synes at tykne, mens du placerer dit offer på bunken.", c="Dit offer brister i lilla ild, mens en skygge falder hen over jorden. Du ser ingen, men mærker dødens loas tilstedeværelse, der flirer bag dig.\n\nBilleder fylder dit sind. En mur af masker, der strækker sig uden for synsfeltet og griner ned mod dig. Et tempel i en stor sump, fyldt med de dødes sjæle.\n\nNår synet klarer sig, runger en latter i luften..."},
  [78229] = {n="Ugleprøvelsen", l="Bring symbolerne fra de tre ugler til Ugganaar i Månelunden.", d="Lad mig se det symbol, du bærer, <Name>.\n\nDet ser ud til, at du er begyndt på ugleprøvelsen. Dette markerer et afgørende øjeblik på din vej som druide.\n\nDer er flere symboler som dette, spredt ud over hele Azerot. For at opnå dem skal du udføre store bedrifter, både i sind og krop.\n\nEn ugle sidder under et stort træ i Østkongerigerne. En anden er nær et stort træ her i Kalimdør. Endnu en er på havet ud for kysten af Hillsbrad.\n\nSøg disse ugler, <Name>, og bring deres symboler til mig.", p="Hvordan går din prøvelse, <Name>?", c="Jeg vil gerne lykønske dig, <Name>. Det, du har udført, er ingen lille bedrift.\n\nAt bestå ugleprøvelsen er at vise en harmoni med alle sider af dit druidiske kald.\n\nTag denne rune som et tegn på din bedrift. Jeg håber, den vil tjene dig godt som vogter af Den Smaragdgrønne Drøm."},
  [78265] = {n="Fiskeolie", l="Jeg får brug for fiskeolie - og en masse af den!", p="Jeg får brug for fiskeolie - og en masse af den!", c="Mange tak, <Name>. Jeg skal nok gøre godt brug af den."},
  [78266] = {n="Mørkejern-krudt", l="Jeg får brug for noget Mørkejern-krudt. Hvor finder du Mørkejern-dværge? Det er dit problem!", p="Jeg får brug for noget Mørkejern-krudt. Hvor finder du Mørkejern-dværge? Det er dit problem!", c="Mange tak, <Name>. Jeg skal nok gøre godt brug af den."},
  [78267] = {n="Makulator-turboladere", l="Jeg får brug for nogle af Eventyr-kompagniets Makulator-turboladere. De sidder tæt koblet til hakkersystemerne, så du skal bruge specielt udstyr for at bjærge dem.\n\nNej, det udstyr har jeg ikke.", p="Jeg får brug for nogle af Eventyr-kompagniets Makulator-turboladere. De sidder tæt koblet til hakkersystemerne, så du skal bruge specielt udstyr for at bjærge dem.\n\nNej, det udstyr har jeg ikke.", c="Mange tak, <Name>. Jeg skal nok gøre godt brug af den."},
  [78270] = {n="Nisse-dirkene", l="Find Skelthos' Horn inde i Skyggetandsborgen. Bring det derefter til C's dødt dropsted nær Brandtræ-landsbyen.", d="<En seddel ligger i kisten>\n\nHej igen, <Name>.\n\nJeg higer efter en skat kendt som Skelthos' Horn, som befinder sig et sted inde i Skyggetandsborgen.\n\nAt tage sig ind i fæstningen kræver normalt backup. Men til dette job er det yderst vigtigt at holde en lav profil.\n\nDu må gå alene.\n\nJeg har en kontakt ved navn Vinix i Stenklippe-bjergene. Han burde kunne hjælpe dig forbi gårdsporten. Resten er op til dig.\n\nBring hornet hertil, og din betaling bliver sendt kort efter.\n\n- C", p="Du sagde, du bryder ind i Skyggetand... alene? Du har godt nok mod!\n\nJeg kan skaffe dig sprængstoffer, så du kommer forbi porten, men jeg skal bruge en arbejdsordre for at få det til at se lovligt ud i bøgerne. En medarbejder her omkring bærer sikkert en. Sandsynligvis en, der bruger meget tid på fiflerier eller bygger ting.", c="Godt gået, <Name>. Jeg regner med, at det var en tur i parken for en i din branche.\n\nSom lovet, her er varerne."},
  [78277] = {n="En Gave af Taknemmelighed", l="Det var måske en dum ting at gøre, men Tule, Gunnar og jeg var som familie... brødre. Vi forventede aldrig, at vores verden ville blive revet i stykker, og heller ikke at Tule ville stille sig på Liskekongens side og lade Gunnar og mig kæmpe for vores menneskelighed...\n\nJeg kan mærke besmittelsen fra Svøben sive ind i Tules del af staven. Den vil for evigt være plettet, fordærvet af hans forræderi, men ak, jeg er ikke klar til at give slip... måske med tiden.\n\nVær venlig at modtage denne videnstoken som min sidste tak."},
  [78287] = {n="Lad Mig Give Dig Et Tilbud", l="Tag Våbenforsendelsen til Mester Træ i Stormvind By.", d="Den første forsendelse er pakket, <Name>. Tag den med til Stormvind og få den foran de højere oppe. Nogen, der kan skrive under i dag!", p="En leverance fra Skralleby? Jeg bestilte ikke noget fra Skralleby.", c="En våbenleverandør fra Skralleby? Tja... Alliancen har brug for alle de forsyninger, vi kan få. Og vi vil ikke have Horden til at skrive under på en aftale. Vi må handle hurtigt."},
  [78288] = {n="Lad Mig Give Dig Et Tilbud", l="Tag Våbenforsendelsen til Zel'mæk i Orgrimgrad.", d="Den første forsendelse er pakket, <Name>. Tag den med til Orgrimgrad og få den foran de højere oppe. Nogen, der kan skrive under i dag!", p="En leverance fra Skralleby? Jeg bestilte ikke noget fra Skralleby.", c="En våbenleverandør fra Skralleby? Hmm... Horden har forsøgt at styre nisse-forretningen hen til os og væk fra Alliancen. Vi må handle hurtigt for at sikre denne nye mulighed."},
  [78297] = {n="Du Har Fået Dig En Aftale", l="Returner den underskrevne indkøbskontrakt til Grisby i Skralleby.", d="Jeg har skrevet under de rette steder, <Name>. Tag dette tilbage til Skralleby og fortæl din leverandør, at Alliancen er glad for at gøre forretning.", p="Fik du afsluttet handlen?", c="De skrev under uden engang at forhandle? Ha! Alt vender til gavn for gamle Grisby!\n\nOg du, <Name>, du har været en rigtig ven. Værsgo, en lille gave som tak.\n\nOg nu hvor vi officielt er i forretning, så er du velkommen til at kigge i mit lager af udstyr og se, om noget fanger dit øje. Jeg giver dig endda medarbejderrabatten!"},
  [78304] = {n="Du Har Fået Dig En Aftale", l="Returner den underskrevne indkøbskontrakt til Grisby i Skralleby.", d="Jeg har skrevet under og forseglet kontrakten, <Name>. Fortæl denne nisse, at han nu kun handler med Horden.", p="Fik du afsluttet handlen?", c="De skrev under uden engang at forhandle? Ha! Alt vender til gavn for gamle Grisby!\n\nOg du, <Name>, du har været en rigtig ven. Værsgo, en lille gave som tak.\n\nOg nu hvor vi officielt er i forretning, så er du velkommen til at kigge i mit lager af udstyr og se, om noget fanger dit øje. Jeg giver dig endda medarbejderrabatten!"},
  [78307] = {n="Skelthos' Horn", l="Logbog", d="Beskrivelse", c="<En seddel ligger i kisten>\n\nTil <Name>. Vi ses.\n\n- C"},
  [78506] = {n="Elementarernes Nød", l="Saml partikler af elementarers vrede, og bring dem til Je'neu Helligkrea ved Zoram'gaard Forpost i Askedalen.", d="Hør her, <Name>. Korruptionen, jeg talte om før, rækker ud over Baron Akvanis. Jeg har i nogen tid mærket en vis uro i den elementære verden. Jeg frygter, at noget er alvorligt galt, og Baron Akvanis' korruption bekræfter kun min mistanke.\n\nFind flere af de elementarer, der lider: her i Askedalen og i de nærliggende Stenklippe-bjerge. Bring mig partikler af deres væsen. Måske kan jeg analysere dem og begynde at forstå, hvad deres vrede bunder i.", p="Elementarerne lider meget, <Name>. Jeg må vide hvorfor.", c="Tak, <Name>. Forhåbentlig giver disse nogle svar."},
  [78537] = {n="Indsigtseliksir", l="Bring en Eliksir af Vandånding og en Visdomseliksir til Je'neu Helligkrea ved Zoram'gaard Forpost i Askedalen.", d="Partiklerne, du samlede, er et vigtigt spor, <Name>, men vi har også brug for åndelig vejledning, hvis vi skal forstå situationen fuldt ud.\n\nDer er et ritual, jeg ofte praktiserer, som kræver en Indsigtseliksir. Synerne, den giver, vil afsløre de næste skridt, vi må tage.\n\nJeg kan brygge eliksiren af to andre. En Eliksir af Vandånding for at frigøre kroppen, og en Visdomseliksir for at åbne sindet.\n\nBring disse til mig, så kan vi begynde ritualet.", p="Har du skaffet komponent-eliksirerne, <Name>?", c="Godt gået. Nu kan ritualet begynde."},
  [78561] = {n="Indsigtseliksir", l="Drik Indsigtseliksiren nær bålet ved Zoram'gaard Forpost, og bevidn det syn, den giver dig.\n\nMedfølgende genstand:", d="Eliksiren er klar, <Name>. Gå ned til bålet på stranden og drik den. Lyt til det syn, åndene har givet dig, og vend tilbage til mig med dine fund.", p="Hvad afslørede åndene for dig, <Name>?", c="En Tornesvin-<Class> ... der gør elementarer til slaver? Det er bestemt urovækkende."},
  [78575] = {n="Hirsk", l="Dræb Hirsk ved Sortthorn-højderyggen i Ødemarken, og bring hans stav til Je'neu Helligkrea ved Zoram'gård-forposten i Askedalen.", d="Den pindsvinesvin, du så i din vision; jeg tror, det var Hirsk.\n\nJordringen har kendt til Pindsvinesvinenes rå udgave af shamanisme i nogen tid. Der går dog rygter om, at nogle få for nylig har gjort urovækkende fremskridt. Hirsk er en af dem.\n\nUd fra det, du så, ser det ud til, at han slaver elementarer i stedet for at samarbejde med dem, sådan som du og jeg ville gøre. Uden tvivl forårsager dette uro i elementarplanet.\n\nDu må stoppe ham, <Name>. For shamanernes og elementarernes bedste.", p="Hirsks gerninger er en fornærmelse mod shamanernes måder og selve elementerne. Han må stoppes.", c="<Je'neu Helligkrea tager stavet i sine hænder.>\n\nDu har udført en stor bedrift, <Name>. Jeg er lettet over at vide, at Hirsks torturer er ovre. Dog frygter jeg, at han måske blot er et symptom på en større sygdom. Så mange elementarer på Azerot råber stadig i smerte.\n\nMange spørgsmål står stadig ubesvarede; måske flere end da vi begyndte. Ikke desto mindre takker jeg dig for din tjeneste for Jordringen."},
  [78611] = {n="En forsvunden forsendelse", l="Forsendelsen mangler nogle varer, men den vil stadig være til en vis nytte. Tak, <Name>."},
  [78612] = {n="En fuld forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er på plads! Tak, <Name>. Disse forsyninger er kritiske for frontlinjen."},
  [78680] = {n="Rygterne florerer", l="Der vides ikke meget om, hvor disse knuste våbenfragmenter befinder sig, bortset fra at de begge er i besiddelse af engang store magikere, der holder til i betydningsfulde tårne. Det siges, at det ene findes her mod nord på Kalimdør, mens det andet ligger gemt nær hjertet af Østkongerigerne.\n\nSe om rygterne passer... Find de to savnede halvdele af dette våben og bring dem til mig.", d="Hviskene i skyggerne taler om et våben, der rummer sjælen fra et stort dæmonisk væsen. Mindre dæmoner som Soran'rak er én ting, men langt mere magtfulde væsener, bundet som straf for deres fejl, tilbyder ubegribelig kraft.\n\nDette våben gik tabt for længe siden og blev knust under den tredje krig.\n\nNylig har rygterne sagt, at magikere, der leger med mørk magi langt over deres forståelse, har tilranet sig fragmenter af våbnet, men de kan ikke låse kræfterne op uden at smede det sammen igen.", p="Stadig ingen spor af våbenfragmenterne? Jeg gætter på, at jeg har sendt dig på en vild gåsejagt.", c="Der er stadig meget, der skal gøres, før jeg kan smede et våben med denne kraft sammen igen. Vi er begyndt på denne vej, og nu er der ingen vej tilbage."},
  [78681] = {n="Fremkaldelsen", l="Saml 10 Blod fra Legionen og udfør ritualet for at fremkalde Des'Altæk, så dens sjæl kan fanges igen.", d="Dæmonen Des'Altæk ser ud til at være sluppet fri af sit fængsel, men den er stadig bundet til det, ligesom en fange til sin celle. Vi må fremkalde dæmonen for at fange dens sjæl igen.\n\nMod nord, i Askedalen, hvor store dæmoner faldt, ligger der på højderyggen et sted, som Legionen engang brugte til ofringer. Jorden er for evigt ardet af de grusomheder, der skete her, men hvis vi kan samle Blod fra Legionen fra de dæmoner, der stadig hjemsøger dette land... så er det nøglen.", p="Lav et blodoffer.", c="Brug den mørke ritualsten for at begynde det mørke ritual. Der er ingen vej tilbage nu..."},
  [78684] = {n="Den mystiske rejsende", l="Mød Doan Kanhan og den mystiske rejsende i Ødemarken.", d="Hvad? Hvor er jeg? Hvordan... hvordan kom jeg hertil?\n\n<Manden foran dig snubler rundt, som om han er søsyg. Hans øjne vider sig, hans hænder ryster, og I stirrer på hinanden i et øjeblik af fælles forvirring.>\n\nAh... En medhexer, ser jeg. Måske kan vi tale om, hvad der førte til disse begivenheder, og måske kan vi finde ud af, hvad der gik galt?\n\n<Usikker på, hvad han skal gøre nu, foreslår du, at han vender tilbage for at tale med Doan Kanhan.>", c="Interessant, sandelig... Jeg sendte dig ud for at dræbe en dæmon; aldrig i min vildeste fantasi ville jeg have troet, at du ville vende tilbage med en ven."},
  [78699] = {n="Bhosca's Øje", l="Logbog", d="Beskrivelse", c="<En seddel ligger i kisten>\n\nTil <Name>. Jeg vil holde et \"øje\" med dig.\n\n- C"},
  [78702] = {n="Raszel Andersen", l="Raszel var en ven... En, jeg troede, jeg havde mistet for længe siden, fra en anden tid... Vi var unge lærlinge dengang... Meget har forandret sig.\n\nResultatet af ritualet kan have været et tilbageslag, men jeg tror, vi stadig kan smede våbnet sammen.\n\nRaszel og jeg har meget at drøfte, og sammen finder vi på en plan. Jeg sender bud, når vi ved, hvordan vi skal komme videre.\n\nI mellemtiden, tag dette. Det ser ud til at være noget, du måske vil være interesseret i."},
  [78872] = {n="En fuld forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er på plads! Tak, <Name>. Disse forsyninger er kritiske for frontlinjen."},
  [78909] = {n="Talismanen med de skiftende skæl", l="Bring N'orra Ethvertshjerte følgende materialer sammen med Håndfuld skiftende skæl for at færdiggøre talismanen: En pung med Mærkeligt støv, fem Større magi-essenser, 2 Små glimrende skår og fem guldmønter.", d="Jeg skal bruge en... nominel mængde materialer til talismanen.\n\n<N'orra smiler forlegent til dig>", p="Jeg indrømmer, at jeg ikke er meget af en fortryller, men jeg mener, at jeg har en ret solid forståelse af processen. I princippet, i hvert fald.", c="Jeg ønsker dig det bedste på dine eventyr og håber, du finder vej tilbage til mig, hvis du støder på andre forunderlige opdagelser som denne!"},
  [78914] = {n="Sjælekarret", l="Nu hvor vi har en måde at svække dæmonen på, behøver vi et kar til at binde den i. Den Brændende Klinge har overrendt gamle alviske ruiner i det sydlige Forødelse og bruger dem som udgangspunkt for at fremkalde dæmoner til Azerot.\n\nNår du har fundet et Sjælekar, så mød os i Forødelse, hvor vi fuldender ritualet.", d="Nisse-ingeniører har forsøgt at skabe en syntetisk Sjælesten, men deres metoder var i bedste fald primitive. Uanset deres mangler er de på rette spor.\n\nJeg har hørt, at goblinerne har snydt en fraktion af købmænd til at købe rettighederne til opskriften. Det er usandsynligt, at de ved, at Sjælekarret i sig selv ikke har nogen magiske egenskaber. Der vil helt sikkert være nogen, der er villige til at skille sig af med mønstret, hvis prisen er rigtig.", p="Med Skyggernes gren og Sjælekarret er vi klar til at begynde ritualet.", c="Ah, ja... ja. Det er præcis, hvad vi har brug for."},
  [78916] = {n="Tomrummets hjerte", l="Bring Den Sorte Afgrunds perle til Daggryvogter Selgorm i Darnassos.", d="Det frygtede uhyre Aku'Maj ligger død. Gemt blandt dets indvolde og blod i dets opsvulmede lig ligger en enorm skiftende perle, der vrimler med rå tomrumsenergi.", p="<Name>, hvilke nyheder har du fra Den Sorte Afgrund?", c="De Gamle Guders tjener, Aku'Maj, er død. En sådan bedrift er stoffet, som ægte helte er lavet af.\n\nDenne genstand kan være nøglen til en langt større forståelse af tomrummets natur og dets påvirkning af vores verden. Den skal studeres med det samme. Tak, <Name>."},
  [78917] = {n="Tomrummets hjerte", l="Bring Den Sorte Afgrunds perle til Bashana Rune-Totem i Tordenskrænten.", d="Det frygtede uhyre Aku'Maj ligger død. Gemt blandt dets indvolde og blod i dets opsvulmede lig ligger en enorm skiftende perle, der vrimler med rå tomrumsenergi.", p="<Name>, hvilke nyheder har du fra Den Sorte Afgrund?", c="De Gamle Guders tjener, Aku'Maj, er død. Du har gjort en mægtig tjeneste for Kalimdørs indbyggere med denne bedrift.\n\nPerlen kan også være nøglen til en langt større forståelse af tomrummets natur og dets påvirkning af vores verden. Den skal studeres med det samme. Gå med Jordmoderen, <Name>."},
  [78920] = {n="Baron Akvanis", l="Bring den mærkelige vandkugle til Je'neu Helligkrea ved Zoram'gård-forposten i Askedalen.", d="Det besejrede vandelementar har efterladt en mærkelig vandkugle. Du regner ud, at genstanden på en eller anden måde gav uhyret energi. Inde i kuglen skvulper en rådden udseende vandform rundt. Selve kuglen virker upåvirkelig over for enhver form for fysisk kraft.\n\nHvis nogen kan finde mening i denne genstand, er det Je'neu Helligkrea fra Jordringen. Han befinder sig ved Hordens Zoram'gård-forpost i Askedalen.", p="Ah, hej igen <Name>. Jeg læste lige bølgerne i havet, ligesom jeg altid gør. Hvad fører dig til forposten?", c="Dette... dette er et fund, <Name>.\n\nDu fik det fra Baron Akvanis i Den Sorte Afgrund, siger du? Baron Akvanis har længe været anset for at være en fordærvet elementarkraft; denne kugle vil vise, hvad der præcis fordærvede ham. Hvis det viser sig at være Tusmørkets Hammer, vil det ikke komme bag på nogen, men vores studier vil også vise, hvordan de gjorde det.\n\nDu gjorde det godt ved at bringe mig dette. Værsgo - tag dette, sammen med Jordringens varmeste hilsner."},
  [78921] = {n="Den Sorte Afgrunds skurkestreger", l="Bring hovedet af Tusmørkets Herre Kelrik til Daggryvogter Selgorm i Darnassos.", d="Styrken har forladt mig. Din hjælp er nødvendig!\n\nFor længe siden var dette sted et stort tempel for Elunie. Men uheld førte til ruin, da fordærvelsen fra en Gammel Gud sivede op fra jorden under og plettede den hellige Månebrønd.\n\nAku'Maj, De Gamle Guders tjener, rejste sig af vandet.\n\nTusmørkets Hammers kultister har alliéret sig med slangefolkene for at besætte disse områder. Kultisterne, ledet af Kelrik, ofrer uskyldige til Aku'Maj for magt.\n\nDræb Kelrik og bring hans hoved til Selgorm i Darnassos, <Name>, tak.", p="Tid er en dyrebar vare, <Class>.\n\nMin rolle her i Darnassos er at sikre, at Sølvdæmringen trives, og at de onde kræfter, der trænger ind i Kalimdør, bliver forpurret.\n\nSig hurtigt, hvad du vil, eller tag dig væk.", c="Kelrik har undsluppet os i ganske lang tid.\n\nDet ser ud til, at hver gang det onde viste sig i disse egne, havde Kelrik en finger med i spillet. I nogen tid troede vi, at han var død eller forsvundet.\n\nMen dette giver perfekt mening. Ved at afslutte hans herredømme har du skånet mange uskyldige menneskers liv.\n\nVor Lys! At ofre nogen til en tjener af en Gammel Gud for ens egen vinding er over al kritik!\n\nDu har udført en stor bedrift, <Name>. Jeg hylder dig på vegne af Sølvdæmringen."},
  [78922] = {n="Den Sorte Afgrunds skurkestreger", l="Bring hovedet af Tusmørkets Herre Kelrik til Bashana Rune-Totem i Tordenskrænten.", d="Styrken har forladt mig. Din hjælp er nødvendig!\n\nFor længe siden var dette sted et stort tempel for Elunie. Men uheld førte til ruin, da fordærvelsen fra en Gammel Gud sivede op fra jorden under og plettede den hellige Månebrønd.\n\nAku'Maj, De Gamle Guders tjener, rejste sig af vandet.\n\nTusmørkets Hammers kultister har alliéret sig med slangefolkene for at besætte disse områder. Kultisterne, ledet af Kelrik, ofrer uskyldige til Aku'Maj for magt.\n\nDræb Kelrik og bring hans hoved til Bashana i Tordenskrænten, <Name>, tak.", p="Må Jordmoderen være med dig, <Name>.\n\nFred mellem jorden og alle hendes folk bør være vores mål. Hun har en stor plan for naturen, og vi har alle en rolle at spille i den plan.", c="Kelrik har undsluppet Sølvdæmringen i ganske lang tid.\n\nI nogen tid troede de, at han var død eller forsvundet.\n\nVed at afslutte hans herredømme har du skånet mange uskyldige menneskers liv, <Name>.\n\nJordmoderen være lovet! At ofre en anden til en tjener af en Gammel Gud for personlig vinding er over al beskrivelse modbydeligt!\n\nDu har gjort en stor ting i dag. Kelrik var et ondskabens væsen og søgte at føre verden tilbage til en tid med kaos ved at tilbede sådanne væsener som De Gamle Guder. Tak, <Name>."},
  [78923] = {n="Viden i dybet", l="Bring Lorgalis-manuskriptet til Gerrig Knoglegreb i Det Forladte Hulrum i Jernsmede.", d="Som du måske ved, samler jeg på viden. Gammel viden. Kraftfuld viden. Viden, der åbner døre, og viden, der kan vække Dem, Der Sover.\n\nDer går rygter om et gammelt stykke viden, Lorgalis-manuskriptet, på bunden af Den Sorte Afgrund i Askedalen. Stedet er den gamle bolig for længe døde alfer. Alfer, der besad stor viden, før deres by faldt i ruin.\n\nLed Den Sorte Afgrund efter manuskriptet. Gør dette, så glemmer jeg det ikke. Ikke engang efter ... de sidste dage.", p="Rejsen til Askedalen er lang, og din opgave er ikke let. Men hvis du bringer mig manuskriptet, <Name>... så vil din belønning være stor.", c="Du fandt manuskriptet! For en glædelig dag dette er! Der vil blive lavet kopier og uddelt, og Lorgalis' gamle viden vil endelig blive kendt af mine brødre og søstre!\n\nDin tjeneste for os er mere, end du aner, <Name>. Men jeg håber, at denne gave viser dig den taknemmelighed, vi viser vores allierede."},
  [78924] = {n="På jagt efter Thælrid", l="Opsøg Sølvvagten Thælrid i Den Sorte Afgrund.", d="Der cirkulerer mange rygter i disse dage om foreningen af Tusmørkets Hammer og slangefolkene i Den Sorte Afgrund ved kysten af Askedalen.\n\nMin rolle her hos Sølvdæmringen er at indsamle så meget information, som jeg kan, så vi ved, hvornår og hvor hjælp er nødvendig.\n\nDet er nu flere uger siden, jeg sendte en spejder for at tjekke aktiviteten i Den Sorte Afgrund. Sølvvagten Thælrid har endnu ikke meldt tilbage.\n\nMine andre spejdere har travlt med vigtigere sager.\n\nOpsøg og assister Thælrid for mig, <Name>."},
  [78925] = {n="Tusmørkets fald", l="Bring 10 Tusmørkevedhæng til Sølvvagten Manadøs i Darnassos.", d="Styrket af de gamle ritualer fra de kaotiske Gamle Guder stræber Tusmørkets Hammers medlemmer efter at bringe deres mørke beskyttere tilbage og sprede død og rædsel over hele verden.\n\nVi tror, at Tusmørkets Hammer har alliéret sig med slangefolkene og samler sig i Den Sorte Afgrund ved kysten af Askedalen.\n\nUanset hvilken ond plan der bryggers i dybet af det gamle tempel, må den forpurres.\n\nFør krig mod Hammeren og bring beviser på dine bedrifter tilbage. Din indsats vil blive belønnet rigeligt.", p="Den Sorte Afgrund var engang et gammelt nattealf-tempel. Det husede engang en yderst kraftfuld månebrønd. Hvem ved, hvad der bryggers der nu i Tusmørkets Hammers hænder.\n\nHar du gjort fremskridt med at rydde dem ud?", c="Du er utvivlsomt af modig og ædel æt, <Name>. Sølvdæmringen roser dig for din indsats mod det onde."},
  [78926] = {n="Forskning i fordærvelsen", l="Gershala Natviskning i Auberdin ønsker 8 fordærvede hjernestammer.", d="Tåbelige blodalfer slider med dæmonisk magi. Har de ikke set, hvad der skete med slangefolkene og satyrerne i Kalimdør?\n\nJeg frygter, at blodalferne vil møde en lignende deformation. Azerot har ikke råd til at føde endnu en ond race af monstre.\n\nJeg ønsker at studere satyrernes og slangefolkenes hjernestammer, så jeg kan udlede, hvilken skæbne alferne er på vej mod. I Den Sorte Afgrund, ved kysten af Askedalen, finder du både satyrer og slangefolk.\n\nDet er en lang rejse, <Name>.", p="Når jeg har nok prøver at studere, kan mit egentlige arbejde begynde. Med de fordærvede hjernestammer fra både satyrerne og slangefolkene i Den Sorte Afgrund kan jeg forsøge at drage en sammenhæng mellem mutationerne.\n\nMåske kan vi med den viden forhindre blodalferne i at dykke dybere ned i deformitet og ondskab.", c="Du har rejst langt og har utvivlsomt stået over for stor fare.\n\nDine handlinger har været uegennyttige. Det er til gavn for hele Azerot, at du hjælper mig med min forskning. Tak, <Name>, for alt, hvad du har gjort.\n\nHvis du vil undskylde mig, har jeg meget arbejde at tage fat på...."},
  [78927] = {n="Troskab mod De Gamle Guder", l="Dræb Lorgøs Jet i Den Sorte Afgrund og vend derefter tilbage til Je'neu Helligkrea i Askedalen.", d="Denne følger af Tusmørkets Hammer må ikke få lov til at fuldføre sin plan. Tusmørkets Hammer forstår ikke naturens ånder. De tror på De Gamle Guder - kaosets og ødelæggelsens væsener, der for længe siden blev besejret. Denne Lorgus må ikke få lov til at lykkes. Du må stoppe ham, <Name>. Jeg kan ikke gøre det selv - jeg er for svag.\n\nGå ind i Den Sorte Afgrund, find ham og dræb ham. Vend tilbage til mig her i Zoram'gård, når det er gjort.", c="Meget godt!! Tak, <Name>. Vi har måske ikke stoppet Tusmørkets Hammer fuldstændigt, men du har i det mindste afværget endnu en af deres planer om at bringe De Gamle Guder tilbage til magten.\n\nHvem ved, hvilke andre planer de har under opsejling, men for nu kan vi sove roligt."},
  [78994] = {n="Et solidt fundament", l="Smaragddragerne beskytter flere portaler til Den Smaragdgrønne Drøm rundt omkring i Azerot. Et af disse steder har helt sikkert det, vi har brug for.\n\nNår du har fundet en Skyggernes gren, skal du vende tilbage i en fart.", d="Det har vist sig udfordrende at smede våbnet sammen, og det er stadig uklart, hvorfor ritualet slog fejl, men jeg tror, vi har udtænkt en alternativ løsning.\n\nTil at begynde med har vi brug for et solidt fundament; en Skyggernes gren.\n\nDisse træer er ondartede udvækster af Smaragdmaren, der sivede ind i vores verden. Det siges, at de svækker viljen hos dem omkring dem. Denne magiske egenskab bliver det fundament, vi bruger til at bygge dette våben.\n\nTag denne drik til hjælp under din søgning. Den vil skjule dig for Smaragddragernes håndlangere.", p="Ingen sagde, at dette ville være et let foretagende, men så igen er de fleste ting, der er værd at gøre, heller ikke lette.", c="Ah ja, du har fundet den! Din fornuft ser også ud til at være intakt, så langt, så godt."},
  [79077] = {n="At dele troen", l="Mediter over Lyset, og bed derefter med den knælende nattealf for at dele dine meditationer.", d="Lyset kalder os til retfærdighed og beskyttelse, men også medfølelse. Vores allierede er fremmede i vores lande, og vi har en pligt til at lære dem vores veje.\nDenne nattealf søger Lyset, men har svært ved at meditere. Vil du hjælpe ham?", p="Ja, <Name>?", c="Lyset virker sine velsignelser gennem dig, <Name>. Ær det ved at fortsætte med at dele din visdom med de søgende, du møder på dine rejser."},
  [79078] = {n="At dele troen", l="Mediter over Elunie, og bed derefter med det knælende menneske for at dele dine meditationer.", d="Dette menneske rækker ud efter Elunies lys, men hans syn er tåget. Vil du hjælpe ham?", c="Lyset virker sine velsignelser gennem dig, <Name>. Ær det ved at fortsætte med at dele din visdom med de søgende, du møder på dine rejser."},
  [79079] = {n="At dele troen", l="Mediter over loaerne, og bed derefter med den knælende Forladte for at dele dine meditationer.", d="Denne stakkels Forladte præst kan ikke se ud til at finde en loa, der vil forhandle med ham. Måske kunne du give ham en velsignelse i stedet?", c="De udøde er ikke særlig populære hos loaerne, men det er godt af dig at hjælpe denne. Prøv at vise dem lidt medlidenhed, hvis du møder flere, der har brug for hjælp, ikke?"},
  [79080] = {n="Del Troen", l="Mediter over udødelighed, og bed derefter sammen med den knælende troll for at dele dine meditationer.", d="Denne troll grubler over døden, men mangler en vis... fortrolighed med emnet. Hjælp venligst med at tydeliggøre hans forståelse.", p="Ja, <Name>?", c="Efter min erfaring er vores folk i bedste fald en kuriositet for resten af Horden. Men at dele vores viden er en simpel måde at vinde deres tillid på. Husk det på dine rejser."},
  [79090] = {n="Slå Indtrængerne Tilbage", l="Bring Krigssang-rytterens Mærke til Ondmalm Månestråle, Månens Præstinde, ved Månebrønd-basen i Askedalen.", d="Nogle af Krigssang-rytterne ligger slået ned, men slaget raser stadig...", p="<Name>, hvilke nyheder har du fra fronten?", c="Disse Horden-indtrængere besmitter stadig vores lande og høster fra vores hellige vildmark. Fortsæt med at drive dem ud!\n\nDenne hellige kampsalme kan inspirere dig til at kæmpe imod dem med større beslutsomhed. Tak, <Name>."},
  [79098] = {n="Ryd Skoven!", l="Bring Sølvvinge-vagtens Amulet til Kazragrum, Den Fjerne Seer, ved Bål-basen i Askedalen.", d="Denne er nedlagt, men de rasende forbundsfolk kæmper stadig... hvad er denne amulet?", p="<Name>, hvilke nyheder har du fra fronten?", c="Disse alliancehunde forhindrer os stadig i at høste de ressourcer, Orgrimgrad har brug for. Fortsæt med at drive dem ud!\n\nDenne Krigssang-kampstrommen vil inspirere dig til at kæmpe imod dem med større beslutsomhed. Lok'tar Ogar, <Name>!"},
  [79099] = {n="Baron Akvanis", l="Bring den Mærkelige Vandkugle til Davidus Tomrumsstjerne i Auberdin, Mørkekysten.", d="Hilsner <Class>. Jeg har hørt de mest mærkelige historier fra de lokale om et stort, fordærvet vandelementar ved navn Baron Akvanis, der holder vagt ved indgangen til nattealf-ruinerne kendt som Den Sorte Afgrund. Jeg er her for at hyre eventyrere, modige nok til at hente kernen af Baron Akvanis, en kugle af fordærvet vand. Til gengæld vil jeg være villig til at give dig adgang til et portal direkte til Zoram-strandet, som jeg har brugt til at studere omgivelserne ved ruinerne... fra en sikker afstand, selvfølgelig.", p="Ah, hej igen <Name>. Har du hentet kuglen?", c="Hmm, meget mærkeligt. Dette... er ikke, hvad jeg havde forventet. Meget vel, tak for dette. Som lovet må du nu benytte mit portal til Zoram-strandet."},
  [79100] = {n="En Forsvunden Forsendelse", l="Forsendelsen mangler nogle genstande, men den vil stadig være til en vis nytte. Tak, <Name>."},
  [79101] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er på plads! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [79102] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er på plads! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [79103] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er på plads! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [79235] = {n="På Flugt", l="Find en af Forødelse-plyndrerne.", d="Jeg har fundet et par scener, som du beskriver, <Name>. Altid lejre af mennesker og dværge. Rygtet blandt karavanerne siger, at en gruppe Horden-plyndrere stod bag. Det virker sandsynligt ud fra ofrene, og hvor brutale angrebene var.\n\nTilsyneladende flygtede banditterne fra Forødelse, da en Alliance-marskal blev hed på deres spor.\n\nHvis du vil spore en af dem op, vil jeg tjekke i en havneby. Dem er der altid lyssky typer, der kommer og går. Du kan måske fange en, der prøver at komme væk med en båd.", c="Har du brug for noget? Gør det hurtigt."},
  [79236] = {n="Kirsebær for Dine Tanker?", l="Bring en Kirsebær-grog til Tokkel i Bytteviken for at høre resten af hendes historie.", d="Er du med marskalen? Nej, det ligner du ikke.\n\nDe rygter, du har hørt, er kun halvt sande. Ja, vi plyndrede menneske- og dværgelejre, men vi gjorde det ikke for Horden. Vi var privat ansat.\n\nJeg fortæller dig hele historien, hvis du køber en grog til mig.", p="Hvordan går det med drinken?", c="Ah, det var det ja. Nu, hvor var jeg?"},
  [79298] = {n="Fristende Skæbne", l="Hjælp Raszel Ånder og Doan Kanhan med fremkaldelsesritualet, og fang Des'Altæk inde i staven.", d="Du kan se, at ond magi forgifter vandet og giver det en lilla farve. Den Brændende Klinge har overvældet dette område med mørk energi.\n\nVi skal bruge dette offeralter, som de bruger under fremkaldelsesritualer. Vi kan udnytte den latente mørke energi i området til at forstærke vores ritual.", c="Alt, hvad Raszel Ånder var, var ikke befalende. For en <Class> var han altid på den ydmyge side. Jeg havde en fornemmelse af, at noget ikke var rigtigt, da den bedrager vendte tilbage under dit fremkaldelsesritual, og derfor sendte jeg efter flere akolytter for at hjælpe, men det var ikke nok... Endnu en gang har vi fejlet i at fange vores bytte.\n\nDesværre gik staven i stykker under din kamp, og alt, jeg kunne gøre, var at stå hjælpeløs og se på... men jeg fandt dette i ødelæggelsen."},
  [79348] = {n="Den Tabte Oldtidens", l="Find nogen, der kan fortælle dig mere om det rådne oldtidsfrø.", d="Et rådent frø er alt, der er tilbage af den vandrende Oldtidens. Dens ydre skal er skør, og indmaden udsender en modbydelig lugt.\n\nUd fra dens størrelse må Oldtidens, dette frø kom fra, have været ret ung; i hvert fald efter oldtidsmålestok. Man må undre sig over, hvorfor sådan et væsen blev fundet slæbende rundt i Morads.\n\nFor at finde dine svar bør du tage dette frø til nogen med kendskab til oldtidsvæsnernes viden.", c="Ah, endnu en tabt ungling..."},
  [79364] = {n="En Simpel Beholder", l="Du troede da ikke, jeg ville lave et skørt våben til dig, va'? Nej, nej, nej, min ven, dis er en eliksir mod beskyttelse.\n\nBekæmpe ild med ild er ikke altid den rigtige fremgangsmåde, mon.\n\nBring en Krystalflaske til Bath'rah Vindvogteren i Alterac-bjergene.", d="Du har gjort det godt, mon. Selvom jeg ikke ved, hvad du står over for derude i Tusind Nåle, vil dette helt sikkert give dig en vis beskyttelse mod elementerne, der truer dette land.\n\n<Bath'rah begynder at rode rundt i sine ejendele, og man kan se ham blive lidt frustreret, mens han leder hurtigere og hurtigere, før han kigger op på dig lidt flovt.>\n\nNå, der er lige én ting mere, jeg har brug for fra dig.\n\n<Hans grin bliver bredere, før han taler igen.>\n\nJeg har vist forlagt mine eliksirflasker...", p="Vi har brug for en større flaske, og en af krystalklar renhed, til at indeholde disse elementer.", c="Vidste jeg, jeg kunne regne med dig."},
  [79365] = {n="Med Vinden Under Dine Vinger", l="Vend tilbage til Rau Klippeløber i Tusind Nåle ved Frihvind-posten.\n\nLeveret genstand:", d="Her mon, en Bygebryder-eliksir er præcis, hvad du har brug for. Drik den for at beskytte dig mod stormens elementer, men husk, at den kun holder et kort stykke tid.\n\nNu skal du gå, vend tilbage til dine venner i nød. Der er ikke mere, jeg kan gøre for dig.", c="Vores vindryttere har fundet noget, men de har ikke kunnet komme tæt nok på til at vurdere situationen. Var du i stand til at finde noget, der kan hjælpe os?"},
  [79377] = {n="De Tabte Ungtræer", l="Find de fire tabte ungtræer i Østkongerigerne, og del Elunie'aras Vand med dem. Vend derefter tilbage til Orokai-folket i Månelunden.", d="I urolige tider kan frø slå rod i bitter jord. Oldtidens væsner, der fødes på denne måde, er tilbøjelige til fordærvelse. De vandrer rundt i fjendtlige lande og finder aldrig fred.\n\nJeg har fornemmet fire ungtræer, der måske kan skånes for en sådan skæbne. De er tabt blandt Østkongerigerne, med blade, der ligner hver årstid.\n\nVær venlig at tage dette vand til dem, så de kan blive helbredt.\n\nVær advaret, vandets magi er skrøbelig. Teleportation vil ødelægge det. Dets kraft vil også svinde hen over tid.", p="Skynd dig, <Name>. Mine slægtninge kan endnu blive reddet.", c="Dine gerninger har bevaret århundreders liv, <Name>. Jeg er enormt taknemmelig. Må du bringe endnu mere heling til dette land i tiderne fremover."},
  [79442] = {n="Fang Op", l="Vend tilbage til Bath'rah Vindvogteren i Alterac-bjergene, og se, om han kan finde en brug for Stormens Øje.", d="Vores folk kan ikke takke dig nok, men jeg har ingen reel brug for dette øje. Måske kunne den gamle Vindvogter finde en god anvendelse for det?", p="Ahh! Ser ud til, at du kom tilbage i ét stykke der. Nu, fortæl mig, hvordan gik det med eliksiren?\n\nNå, det er godt, jeg havde tro på dig. For den eliksir var jo ikke andet end en vældig fin slag, bror'dah. Meget lækrere, end den var effektiv mod de storme.\n\nNu, nu... vær ikke vred på mig. Alt, du behøvede, var lidt opmuntring. Tingene endte, som de altid var skabt til at gøre.\n\nMen siden du er her... Jeg lagde mærke til det vældig fine øje, du har med dig...", c="Hør lige her. Ingen flere trick, ingen flere lege. Jeg har noget, du ville være interesseret i.\n\nByt mig det øje, og jeg giver dig denne vældig fine rune, der er klar til at lære dig nye tricks.\n\nHvad siger du?"},
  [79482] = {n="Stjålne Vinterslør-lækkerier", l="Find efterforskeren fra Røgskovs Enge, der er forsvundet i de snedækkede egne af Alterac-bjergene.", d="Hør... jeg vil ikke knuse sæsonens magi her, men Røgskovs Enge kunne bruge lidt hjælp - den slags, I eventyrertyper plejer at give.\n\nVi mangler en vigtig forsendelse af lækkerier, der skulle genopfylde vores lager til sæsonen, og nu mangler vi også agenten fra Røgskovs Enge, som vi sendte ud i marken for at finde den! Venligst - forsendelsen blev sidst set i Alterac-bjergene, og det var der, vores mand gik for at lede efter den.\n\nTjek, om begge er derude, sikre og velbeholdne!", c="D-d-du kan h-h-høre mig! Tak til b-b-bundlinjen!\n\nJeg er ikke r-r-rigtig en snemand - mit n-n-navn er Sække, og j-j-jeg arbejder for Jernsmede-afdelingen af Røgskovs Enge... Jeg b-b-blev sendt herud for at lede efter en m-m-forsvundet pakke, da jeg blev angrebet af et v-v-væsen, jeg aldrig har set f-f-før!\n\nSå v-v-vildt k-k-kold..."},
  [79483] = {n="Stjålne Vinterslør-lækkerier", l="Find efterforskeren fra Røgskovs Enge, der er forsvundet i de snedækkede egne af Alterac-bjergene.", d="Hør... jeg vil ikke knuse sæsonens magi her, men Røgskovs Enge kunne bruge lidt hjælp - den slags, I eventyrertyper plejer at give.\n\nVi mangler en vigtig forsendelse af lækkerier, der skulle genopfylde vores lager til sæsonen, og nu mangler vi også agenten fra Røgskovs Enge, som vi sendte ud i marken for at finde den! Venligst - forsendelsen blev sidst set i Alterac-bjergene, og det var der, vores mand gik for at lede efter den.\n\nTjek, om begge er derude, sikre og velbeholdne!", c="D-d-du kan h-h-høre mig! Tak til b-b-bundlinjen!\n\nJeg er ikke r-r-rigtig en snemand - mit n-n-navn er Sække, og j-j-jeg arbejder for Orgrimgrad-afdelingen af Røgskovs Enge... Jeg b-b-blev sendt herud for at lede efter en m-m-forsvundet pakke, da jeg blev angrebet af et v-v-væsen, jeg aldrig har set f-f-før!\n\nSå v-v-vildt k-k-kold..."},
  [79484] = {n="Du Er En Gnaven En...", l="Find og bring de stjålne lækkerier tilbage til Ulvmort Klingelomme i Jernsmede. De menes sidst at have været i besiddelse af den Afskyelige Grinebider, der befinder sig et sted i de snedækkede egne af Alterac-bjergene.", d="Et væsen kaldet \"Den Afskyelige Grinebider\" er den, s-s-som stjal vores forsendelse af l-l-lækkerier, <Name>. Vær d-d-forsigtig dog! Han er d-d-den, der forvandlede mig til dette s-s-snedækkede rod!\n\nDu k-k-kommer til at få brug for hjælp til at st-st-å over for ham. Jeg har set ham v-v-vandre rundt overalt, hvor y-y-yetierne holder til; han er s-s-givetvis her et sted! F-f-find lækkerierne <Name>, tag dem t-t-tilbage til Røgskovs Enge i Jernsmede, og f-f-fortæl dem, at jeg har b-b-brug for at blive optøet!", p="<Name> - vores Vinterslørets Festmåltid bliver ødelagt uden de lækkerier til genopfyldning! Graccu selv vil gå glip af at dele sine dejlige kødpaier med alle de gode drenge og piger denne sæson...", c="Du fandt den! Du har reddet Røgskovs Enges Vinterslørets Festmåltid!\n\nStakkels Sække... vi sørger for at sende et hold derud og finde en måde at optø ham på. Forhåbentlig er han tilbage i tide til festdagen; han bliver dog nødt til at indhente tabt arbejdstid. Alligevel ville dette slet ikke være muligt, hvis det ikke var for dig!"},
  [79485] = {n="Du Er En Gnaven En...", l="Find og bring de stjålne lækkerier tilbage til Kaymard Kobbernyp i Orgrimgrad. De menes sidst at have været i besiddelse af den Afskyelige Grinebider, der befinder sig et sted i de snedækkede egne af Alterac-bjergene.", d="Et væsen kaldet \"Den Afskyelige Grinebider\" er den, s-s-som stjal vores forsendelse af l-l-lækkerier, <Name>. Vær d-d-forsigtig dog! Han er d-d-den, der forvandlede mig til dette s-s-snedækkede rod!\n\nDu k-k-kommer til at få brug for hjælp til at st-st-å over for ham. Jeg har set ham v-v-vandre rundt overalt, hvor y-y-yetierne holder til; han er s-s-givetvis her et sted! F-f-find lækkerierne <Name>, tag dem t-t-tilbage til Røgskovs Enge i Orgrimgrad, og f-f-fortæl dem, at jeg har b-b-brug for at blive optøet!", p="<Name> - vores Vinterslørets Festmåltid bliver ødelagt uden de lækkerier til genopfyldning! Graccu selv vil gå glip af at dele sine dejlige kødpaier med alle de gode drenge og piger denne sæson...", c="Du fandt den! Du har reddet Røgskovs Enges Vinterslørets Festmåltid!\n\nStakkels Sække... vi sørger for at sende et hold derud og finde en måde at optø ham på. Forhåbentlig er han tilbage i tide til festdagen; han bliver dog nødt til at indhente tabt arbejdstid. Alligevel ville dette slet ikke være muligt, hvis det ikke var for dig!"},
  [79486] = {n="Et Tak Fra Røgskovs Enge!", l="Tal med Storfaderen Vinter i Jernsmede.", d="Vi hos Røgskovs Enge sætter stor pris på genfindelsen af de stjålne lækkerier, <Name>. For det vil vi gerne tilbyde dig en særlig gave... præsenteret af ingen ringere end Storfaderen Vinter selv!\n\nTal venligst med Storfaderen Vinter, så vil han give dig din Vinterslørets Festmåltid-gave fra os her hos Røgskovs Enge. Fra vores gård til din tallerken, det er altid Røgskovs Enges sunde godhed... takket være dig, selvfølgelig!", c="Ho ho hej, eventyrer!\n\nKobolderne fortalte mig, at du har fortjent en særlig gave i denne helligdagssæson, og jeg er glad for at kunne give den til dig. Her er den - hav en vidunderlig Vinterslørets Festmåltid i dag og i alle fremtidige sæsoner."},
  [79487] = {n="Et Tak Fra Røgskovs Enge!", l="Tal med Storfaderen Vinter i Orgrimgrad.", d="Vi hos Røgskovs Enge sætter stor pris på genfindelsen af de stjålne lækkerier, <Name>. For det vil vi gerne tilbyde dig en særlig gave... præsenteret af ingen ringere end Storfaderen Vinter selv!\n\nTal venligst med Storfaderen Vinter, så vil han give dig din Vinterslørets Festmåltid-gave fra os her hos Røgskovs Enge. Fra vores gård til din tallerken, det er altid Røgskovs Enges sunde godhed... takket være dig, selvfølgelig!", c="Ho ho hej, eventyrer!\n\nKobolderne fortalte mig, at du har fortjent en særlig gave i denne helligdagssæson, og jeg er glad for at kunne give den til dig. Her er den - hav en vidunderlig Vinterslørets Festmåltid i dag og i alle fremtidige sæsoner."},
  [79492] = {n="Metzen Rensdyret", l="Find Metzen Rensdyret. Brug de noter, der er givet til dig, som spor til, hvor han holdes fanget.\n\nNår du finder Metzen, skal du have Pungen med Rensdyrstøv i din besiddelse, så du kan strø lidt af støvet over ham; det skulle befri Metzen fra hans fangenskabsbånd.\n\nBring Pungen med Rensdyrstøv tilbage til Ulvmort Klingelomme i Jernsmede, når Metzen er blevet befriet.", d="KATASTROFE har ramt! Metzen Rensdyret er blevet kidnappet!\n\nMetzen er et af Storfaderen Vinters otte rensdyr - og ejendom tilhørende Røgskovs Enge. Vi har modtaget ikke ét, men TO løsepengebreve fra grupper, der hævder at have Metzen. Med helligdagssæsonen i fuld gang er vi her stærkt presset på mønterne! Venligst - find Metzen og bring ham tilbage til os!\n\nTjek løsepengebrevene for spor, og strø dette rensdyrstøv over ham - det vil befri ham fra alle hans bånd!\n\nVenligst, skynd dig!", p="<Name>! Var notesene i tasken, jeg gav dig, nok information til at finde Metzen? Jeg kan slet ikke tænke på, hvad de grusomme slyngler måske gør ved ham... men der er ingen måde, vi har råd til at betale sådan en uhyrlig løsesum!", c="Du gjorde det! Hurra!\n\nMetzen fløj tilbage til Storfaderen Vinters stalde - ja, Metzen kan virkelig flyve - for lidt siden! Støvet virkede som en charme; jeg vidste, det ville. Du har reddet Vinterslørets Festmåltid såvel som Røgskovs Enge fra katastrofe. Tak, <Name>.\n\nHør... fordi du har gjort det her, vil jeg have, at du får dette. Det er noget MEGET særligt; hvis du har et ridedyr, tror jeg, du vil synes, det er sjovt. Glædelig Vinterslør!"},
  [79495] = {n="Metzen Rensdyret", l="Find Metzen Rensdyret. Brug de noter, der er givet til dig, som spor til, hvor han holdes fanget.\n\nNår du finder Metzen, skal du have Pungen med Rensdyrstøv i din besiddelse, så du kan strø lidt af støvet over ham; det skulle befri Metzen fra hans fangenskabsbånd.\n\nBring Pungen med Rensdyrstøv tilbage til Kaymard Kobbernyp i Orgrimgrad, når Metzen er blevet befriet.", d="KATASTROFE har ramt! Metzen Rensdyret er blevet kidnappet!\n\nMetzen er et af Storfaderen Vinters otte rensdyr - og ejendom tilhørende Røgskovs Enge. Vi har modtaget ikke ét, men TO løsepengebreve fra grupper, der hævder at have Metzen. Med helligdagssæsonen i fuld gang er vi her stærkt presset på mønterne! Venligst - find Metzen og bring ham tilbage til os!\n\nTjek løsepengebrevene for spor, og strø dette rensdyrstøv over ham - det vil befri ham fra alle hans bånd!\n\nVenligst, skynd dig!", p="<Name>! Fandt du ham? Var notesene i tasken, jeg gav dig, nok information til at finde Metzen? Jeg kan slet ikke tænke på, hvad de grusomme slyngler måske gør ved ham... men der er ingen måde, vi har råd til at betale sådan en uhyrlig løsesum!", c="Du gjorde det! Hurra!\n\nMetzen fløj tilbage til Storfaderen Vinters stalde - ja, Metzen kan virkelig flyve - for lidt siden! Støvet virkede som en charme; jeg vidste, det ville. Du har reddet Vinterslørets Festmåltid såvel som Røgskovs Enge fra katastrofe. Tak, <Name>.\n\nHør... fordi du har gjort det her, vil jeg have, at du får dette. Det er noget MEGET særligt; hvis du har et ridedyr, tror jeg, du vil synes, det er sjovt. Glædelig Vinterslør!"},
  [79501] = {n="Dagens Helt", l="Bring 1 Dybstensalt og 5 guldmønter til en hvilken som helst Kristtorn-bevarer-maskine, hvorefter du vil modtage 5 Konserveret Kristtorn.", d="Hør... jeg burde egentlig ikke fortælle dig dette, men da du er dagens helt og det hele...\n\nDer er frisk kristtorn overalt på denne tid af året, men den holder aldrig. Vi har en maskine, der bevarer kristtorn - den bliver aldrig dårlig! Vi bruger den til at krydre højtiden... og til at tjene på sommeren!\n\nJeg lader dig bruge bevareren, men kun hvis du er en mesterkok. Du skal bruge noget dybstensalt og to, tre, åh lad os sige fem guld. Det vil give dig en flot portion, som er din at beholde.", p="\"Kristtorn-bevarer\"-maskinen ligner først en slags destillationsapparat, men en omhyggelig undersøgelse af den afslører nogle kobold-agtige ændringer. Alligevel synes dit kogekunstskab at gøre dig i stand til at forstå, hvordan maskinen virker.\n\nDer er allerede frisk kristtorn i maskinen - du skal blot levere noget dybstensalt og fem guldmønter for at få maskinen i gang.", c="Maskinen giver en lille rumlen og en smule damp, da den begynder at arbejde. Der går ikke længe, før den stopper, varslet af endnu en lille dampstråle, der sprøjter ud af den. En dørlem åbner sig og afslører en portion konserveret kristtorn!"},
  [79502] = {n="Dagens Helt", l="Bring 1 Dybstensalt og 5 guldmønter til Kristtorn-bevarer-maskinen, hvorefter du får 5 Konserveret Kristtorn.", d="Lyt... Jeg må egentlig ikke fortælle dig det her, men siden du er dagens helt og det hele...\n\nDer er frisk kristtorn overalt på denne tid af året, men den holder aldrig længe. Vi har en maskine, der konserverer kristtorn - den bliver aldrig dårlig! Vi bruger den til at krydre julen... og fortjenesten om sommeren!\n\nJeg lader dig bruge bevareren, men kun hvis du er en mesterkok. Du skal bruge noget dybstensalt og to, tre, åh, lad os sige fem guld. Så får du en pæn portion, som er din at beholde.", p="\"Kristtorn-bevarer\"-maskinen ligner først en slags destillationsapparat, men en omhyggelig undersøgelse afslører nogle kobold-agtige ændringer på den. Dine kogekunster ser dog ud til at gøre dig i stand til at forstå, hvordan maskinen virker.\n\nDer er allerede frisk kristtorn i maskinen - du skal blot levere noget dybstensalt og fem guldmønter for at få maskinen i gang.", c="Maskinen giver en lille rumlen og lidt damp fra sig, når den går i gang. Det varer ikke længe, før den stopper, og det markeres af endnu en lille dampstråle, der sprøjter ud af den. En dørluge åbner sig og afslører en portion konserveret kristtorn!"},
  [79588] = {n="Små pelsede poter", l="Den første lektion i at samle en menneskemængde er: lok dem med gadgets og nipsgenstande! Kan du hjælpe mig?\n\nJeg har brug for små pelsede poter til præmier. Dem kan du finde på kattene i Ødemarken eller Mørkekysten....\n\nBring mig nogle poter, så bytter jeg en billet til Mørkemånens Marked for dem.", p="Den første lektion i at samle en menneskemængde er: lok dem med gadgets og nipsgenstande! Kan du hjælpe mig?\n\nJeg har brug for små pelsede poter til præmier. Dem kan du finde på kattene i Ødemarken eller Mørkekysten....\n\nBring mig nogle poter, så bytter jeg en billet til Mørkemånens Marked for dem.", c="Super, du fik dem! Vi kan bruge dem til at lave legetøj og nipsgenstande, og det vil lokke flere folk til Marked!\n\nHer er din billet, <Name>. Du har fortjent den!"},
  [79589] = {n="Revne bjørnehuder", l="Børn elsker legetøj! Og uanset race har jeg opdaget, at alle børn elsker pelsede, plyske legetøjsdyr lavet af revne bjørnehuder!\n\nDe huder kan du få fra bjørnene i Askedalen eller Bakkebrad. Bring mig en stak af dem, og tjen dig selv en stak billetter til Mørkemånens Marked!", p="Børn elsker legetøj! Og uanset race har jeg opdaget, at alle børn elsker pelsede, plyske legetøjsdyr lavet af revne bjørnehuder!\n\nDe huder kan du få fra bjørnene i Askedalen eller Bakkebrad. Bring mig en stak af dem, og tjen dig selv en stak billetter til Mørkemånens Marked!", c="Flotte huder, <Name>! Jeg får nogen til at sy dem sammen til en masse plyslegetøj. Med lidt fyld og noget maling tror jeg, at børn i hele Azerot vil misunde dem!\n\nBilletter? Ah ja, din betaling! Her er de!"},
  [79590] = {n="Tung slibesten", l="For at holde mig i form kan jeg lide at placere en stav mellem tunge slibesten og så løfte staven over hovedet. Det er ikke let, men at være verdens stærkeste kvinde, som jeg er, kan ikke opnås ved at sidde ned!\n\nKan du hjælpe mig? Jeg har brug for flere slibesten - bring mig nogle, så bytter jeg Mørkemånens Marked-billetter for dem.", p="For at holde mig i form kan jeg lide at placere en stav mellem tunge slibesten og så løfte staven over hovedet. Det er ikke let, men at være verdens stærkeste kvinde, som jeg er, kan ikke opnås ved at sidde ned!\n\nKan du hjælpe mig? Jeg har brug for flere slibesten - bring mig nogle, så bytter jeg Mørkemånens Marked-billetter for dem.", c="Du bragte stenene! Og de er tunge! Jeg kan allerede mærke, at mine muskler vokser. Tak, <Name>!\n\nVær så venlig at tage disse billetter, og sørg for ikke at spise for mange søde sager, mens du er på Marked. En stor, stærk <Class> som dig skal holde sig i kampform!"},
  [79591] = {n="Surrende bronzedims", l="Min nye bod bliver et syn at se, ja sir! Et syn at se, og... for en heldig håndfuld, at røre ved!\n\nJeg kan allerede høre de surrende bronzedimser synge deres sang af mekanisk ekstase, når gæsterne træder hen til min bod og tester deres dygtighed!\n\nAh... nu mangler jeg selve dimserne for at bringe min drøm tættere på virkeliggørelse. Vær venlig, <Name>, bring mig surrende bronzedimser... så er Mørkemånens Marked-billetterne dine!", p="Min nye bod bliver et syn at se, ja sir! Et syn at se, og... for en heldig håndfuld, at røre ved!\n\nJeg kan allerede høre de surrende bronzedimser synge deres sang af mekanisk ekstase, når gæsterne træder hen til min bod og tester deres dygtighed!\n\nAh... nu mangler jeg selve dimserne for at bringe min drøm tættere på virkeliggørelse. Vær venlig, <Name>, bring mig surrende bronzedimser... så er Mørkemånens Marked-billetterne dine!", c="Du bragte dimserne! Vidunderligt! Selv nu kan jeg høre deres summende, surrende kor i mit hoved! Åh, når denne bod er klar, bliver den verdens vidunder, husk det!\n\nHer er dine billetter, <Name>. Og nyd dit ophold på Marked!"},
  [79592] = {n="Karnevalsvamser", l="Vores Marked-arbejdere gør mere end at feje skrald og slå søm i! De hjælper også med at vogte karnevallet, mens det rejser, og til det formål har de altid brug for gode, solide rustningsvamser.\n\nHvis du laver nogle seje læderrustninger og bringer dem til mig, så sørger jeg for, at de kommer til de rette folk. Jeg skaffer dig også nogle Mørkemånens Marked-billetter som bytte.", p="Vores Marked-arbejdere gør mere end at feje skrald og slå søm i! De hjælper også med at vogte karnevallet, mens det rejser, og til det formål har de altid brug for gode, solide rustningsvamser.\n\nHvis du laver nogle seje læderrustninger og bringer dem til mig, så sørger jeg for, at de kommer til de rette folk. Jeg skaffer dig også nogle Mørkemånens Marked-billetter som bytte.", c="Ah, du bragte vamserne. Storartet. Hvilket dyrs skind brugte du til at lave dem, hvis jeg må spørge? Syarbejdet er meget velgjort, og lædrets tekstur har en robust stil. Jeg kan se, at du er en håndværker med talent!\n\nTak, <Name>, og her er dine billetter."},
  [79593] = {n="Grov vægtsten", l="Det kræver en masse arbejde at være verdens stærkeste kvinde! Mit vægtsæt bliver for let, og hvis jeg skal holde mig i form, har jeg brug for flere vægte!\n\nTror du, du kunne bringe mig nogle vægtsten? Hvis du gør det, giver jeg dig en billet til Mørkemånens Marked.", p="Det kræver en masse arbejde at være verdens stærkeste kvinde! Mit vægtsæt bliver for let, og hvis jeg skal holde mig i form, har jeg brug for flere vægte!\n\nTror du, du kunne bringe mig nogle vægtsten? Hvis du gør det, giver jeg dig en billet til Mørkemånens Marked.", c="Fint! Disse vil fungere perfekt! De er ikke for tunge, men heller ikke for lette. De er ideelle til at opbygge muskelmasse!\n\nTak skal du have, <Name>. Her er din billet til Mørkemånens Marked!"},
  [79594] = {n="Kobbermodulator", l="Jebb udvikler en ny attraktion til Det Bizarre Zoo, en der vil gøre folk gale af undren og fryd! Men det vil kræve en masse arbejde og en masse materialer...\n\nDet inkluderer kobbermodulatorer. Vi har brug for mange modulatorer til attraktionens mekaniske dele. Bring mig kobbermodulatorer, så bytter jeg dem for en billet til Mørkemånens Marked.", p="Jebb udvikler en ny attraktion til Det Bizarre Zoo, en der vil gøre folk gale af undren og fryd! Men det vil kræve en masse arbejde og en masse materialer...\n\nDet inkluderer kobbermodulatorer. Vi har brug for mange modulatorer til attraktionens mekaniske dele. Bring mig kobbermodulatorer, så bytter jeg dem for en billet til Mørkemånens Marked.", c="Aha! Modulatorerne! Storartet!\n\nJeg kan ikke fortælle dig præcis, hvad vi bygger, men disse bliver uvurderlige for konstruktionen. Jeg står i din gæld, <Name>, men tag venligst denne Mørkemånens Marked-billet som tegn på min påskønnelse."},
  [79595] = {n="Karnevalsstøvler", l="Vi på Mørkemånens Marked går meget. Vi går fra den ene markedsplads til den anden... faktisk vil du aldrig se os sidde ned på arbejdet! Så det er ingen overraskelse, at vi slider en hel del støvler op! Vi har brug for støvler, der både er holdbare og stilfulde, og præget læder passer ganske godt til den regning.\n\nDu! Du er læderarbejder; lav mig præget lædersstøvler, så giver jeg dig en billet til Mørkemånens Marked for arbejdet.", p="Vi på Mørkemånens Marked går meget. Vi går fra den ene markedsplads til den anden... faktisk vil du aldrig se os sidde ned på arbejdet! Så det er ingen overraskelse, at vi slider en hel del støvler op! Vi har brug for støvler, der både er holdbare og stilfulde, og præget læder passer ganske godt til den regning.\n\nDu! Du er læderarbejder; lav mig præget lædersstøvler, så giver jeg dig en billet til Mørkemånens Marked for arbejdet.", c="Tak, <Name>. Disse er ganske velgjorte. Håndværket er topklasse! Her er en billet til Mørkemånens Marked... nyd den, min herre."},
  [79624] = {n="Alle kan lave mad", l="Find en oger, der kan læse den ulæselige opskrift.", d="Opskriften ser ud til at være til en slags kødret. Den er skrevet på et sprog, du ikke forstår. Oger er dit bedste gæt, givet kilden og emnet.\n\nOgre er ikke normalt køkkentypen, men hvis du kendte en med sådan en tilbøjelighed, kunne de oversætte opskriften for dig.", c="Har du opskriften? Skonk lytter."},
  [79626] = {n="Bjærgematic 9000!", l="Indsæt en skidt-indkrystalliseret bjærgning i Bjærgematic 9000, og sørg for at have tredive sølvmønter til at starte maskinen.", d="Denne konstruktion ser ud til at få strøm, men kun lige akkurat. En lille plade på apparatet står \"Bjærgematic 9000\", efterfulgt af lidt tekst, der ikke kan tydes på grund af det tykke lag indtørret snavs. Maskinen har en meget stor indtagsbeholder samt en sprække til at indsætte mønter.", p="Maskinen ser ud til at være i en usædvanlig dårlig forfatning. Det ser ud til, at du stadig kan indsætte noget skidt-indkrystalliseret bjærgning i maskinen, men du er ikke sikker på, hvad der sker, hvis du gør det.", c="Du indsætter den skidt-indkrystalliseret bjærgning og tredive sølvmønter i Bjærgematic 9000. Maskinen lyser kort op, begynder at ryste og rasle og spytter så din stadig beskidte bjærgning ud, hvorefter den tier. Den ser ud til at være gået i stykker."},
  [79637] = {n="En tikkende gave", l="Hav en glædelig Festmåltid for Stor-Vinter fra dine venner i Røgskovens Græsgange."},
  [79677] = {n="En hurtig indkøbstur", l="Saml ingredienserne til Skonks ret, og bring dem derefter til ham i Arathi-højlandet", d="Andre oger griner af Skonk, fordi Skonk er mindre end dem. De siger, at lille oger er svag, så Skonk lærte at lave mad i stedet for at kæmpe. Det førte kun til mere drilleri, så Skonk løb væk for at følge drøm.\n\nSkonk kan lave ret, men har brug for ingredienser. Ikke sikker på, hvor de findes. Skonk mere fokuseret på håndværk; ikke rigtig logistik-fyr.", p="Har du fundet ingredienserne endnu? Næsten middagstid.", c="Godt arbejde, <Race>-ven. Vi laver virkelig mad nu!"},
  [79678] = {n="Smagsprøve", l="Smag opskriften med Skonk.", d="Ok <Race>-ven, nu er det Skonks yndlingsdel. Skonk har ild varm og klar, og vil dele ny ret med ny ven. Du gør så store tjenester for Skonk; det er kun rigtigt, at du også får noget!\n\nLad Skonk vide, når du er klar til smagning.", c="Mmm, opskriften er lækker!\n\nSkonk bliver lidt væk i lidenskabens øjeblik, men du var en god hjælper!\n\nHer, dette er din del. Skonk tilføjer endda lidt ekstra for besværet."},
  [79704] = {n="Bjærgematic 9000!", l="Indsæt en skidt-indkrystalliseret bjærgning i Bjærgematic 9000, og sørg for at have tre sølvmønter til at starte maskinen.", d="Indsæt din bjærgning i maskinen, og få fantastiske præmier! Sandsynligvis. Måske.", p="Maskinen ryster og skælver, før den rapser en bunke bjærgede dele ud."},
  [79705] = {n="Bjærgning af Bjærgematic'en", l="Bring Ziri \"Skruenøglen\" 10 Mithrilstænger, 5 Større Mystisk Essens, 3 GG12-082 patronsikringer og en Upåklagelig G-7 C.O.R.E.-processor, så kan hun få Bjærgematic 9000! til at virke for dig. Sandsynligvis. Måske.", d="Jeg tror, den ting er på sine sidste ben, makker. Jeg kunne måske reparere den, men det bliver ikke let... eller billigt. Sådan her: bring mig 10 mithrilstænger, 5 større mystisk essens, 3 GG12-082 patronsikringer og en upåklagelig G-7 C.O.R.E.-processor, så kan jeg nok få den op at køre for dig. Patronsikringerne burde være rigelige her i Nisseborgen, men processorkernen er en ret sjælden genstand og ikke så let at finde. Du virker dog ganske snarrådig, så jeg er sikker på, at du nok skal finde ud af det! Held og lykke!", p="Wow, fik du faktisk slæbt alt det skrammel herhen? Jeg drillede dig mest, men hey, jeg er en gnom af ord, og jeg spilder ikke gode materialer. Giv mig et øjeblik, så får jeg denne lille skat i gang igen!", c="Én Bjærgematic 9000 klar til at rocke, som lovet. Hvis du heldigvis får noget godt ud af den, så kom og se mig. Jeg kan måske lære dig et par ting, for en pris selvfølgelig!\n\n<Ziri smiler bredt og stikker noget ned i sin baglomme>"},
  [79731] = {n="Trolden-rullen", l="Løs rullens gåde. Når du har gjort det, vil Hemmet Jagtvarys måske gerne høre historien.", d="<De gamle glyffer falder til ro og bliver til ord foran dine øjne.>\n\nNår Zul'Kundas kilde løber med den hellige kildes vand, giver guderne deres velsignelse.", c="En magisk kilde skjult i junglen? For en historie, <Name>!\n\nDet giver mig en idé til et nyt kapitel i min bog! Lad mig se, hvor jeg lagde det manuskript..."},
  [79905] = {n="En smagsprøve på viden", l="Med den viden, du har opnået på dine rejser, tror jeg, at du er klar til selv at lære at fremtrylle Forståelsesamuletter. Det vil hjælpe dig med at afdække nye tekster til bibliotekets samling.\n\nRejs trygt, <Name>."},
  [79939] = {n="Den Knækkede Hammer", l="Søg efter spor om, hvad der skete ved Mannorok-hekseriet i Forødelse, og find nogen, der måske ved mere om den knækkede hammer.", d="En ornamenteret knækket krigshammer ligger omgivet af døde Brændende Klinge-kultister og Skarlagenrøde Korstog-krigere. Der har klart været en kamp her, og ganske nylig. Du genkender også dette som våbnet fra en paladin i Sølvhåndens Orden. Selvom du har set mange hammere som denne, er dette våbens kvalitet og udførelse ganske unik. Du bør undersøge området for spor og finde nogen, der måske ved mere om dette våben.", p="Hvad er det, du har dér, min ven?", c="<Katrine sukker tungt> Ja <Name>, jeg kender til dette våben. Jeg havde antaget, at dens ejer var død for længe siden."},
  [79940] = {n="En tabt bror", l="Tal med Katrine den Rene og lær mere om den knækkede hammer.", d="<Katrine krymper sig, mens hun holder de knuste fragmenter af den knækkede hammer>\n\nJeg vil ikke tale om dette våbens herre i detaljer, for fortællingen ville fylde mig med skam, men jeg vil fortælle dig, hvad jeg kan.", c="Du har få spor at gå efter, så det kan blive svært at finde Æonas, men du bør forsøge."},
  [79945] = {n="Ordrer fra Storslået Korsfarer", l="Bring Ordrerne fra Storslået Korsfarer tilbage til Katrine den Rene.", d="Dette ser ud til at være ordrer fra Storslået Korsfarer i Skarlagenrøde Korstog selv, Dathrovan. Det ser ud til, at Æonas er kommet i konflikt med Korstoget. At dømme efter scenen foran dig, ser det ud til, at Korstoget var i stand til at følge Æonas hertil og arrestere ham. Det ser ud til, at han ikke gik ned uden kamp.\n\nAnklagerne mod Æonas er alvorlige, men det ville forklare noget af scenen, du stødte på i Forødelse.", p="Bringer du nyt om Æonas?", c="<Katrine rynker dybt panden, mens hun læser brevet>\n\nÆonas havde nogle radikale synspunkter, da han forlod ordenen, men jeg finder det meget svært at tro, at hans virke i Forødelse involverede omgang med dæmoner, udøde eller noget i den stil. Vi må finde ham og høre hans side af sagen. Der er mere til dette, det er jeg sikker på."},
  [79946] = {n="En bror i nød", l="Tal med Katrine for at lære mere om Æonas, og find derefter ham i Det Skarlagenrøde Kloster", d="På grund af den... uheldige karakter af, hvorfor han forlod ordenen, ville det være dårlig komedie, hvis Æonas døde i Skarlagenrøde Korstogs hænder nu. Korstoget er en organisation af fanatikere og galninge, og de er blevet stadig mere frække i deres villighed til at begå vold mod enhver, de forestiller sig er lysets fjender. Gå til Det Skarlagenrøde Kloster i Tirisfal-gladerne og find ud af, om Æonas stadig lever.", c="<Æonas ser kritisk såret ud. Han kæmper for at hviske nogle få ord.> De spurgte mig slet ikke... om noget..."},
  [79953] = {n="Ludittens vejledning til pleje af dit dæmoniske kæledyr", l="Har du bragt noget til vores samling?", p="Har du bragt noget til vores samling?", c="Tak, <Name>. Vores viden vokser takket være din indsats.\n\nHvis du opdager flere magiske værker, som kunne gavne biblioteket, så bring dem venligst til mig."},
  [79963] = {n="Ved Lysets nåde", l="Helbred Æonas.", d="Æonas har brug for øjeblikkelig heling, ellers dør han. Kald på lyset og red ham.", c="<Æonas ser ud til at trække vejret lettere nu. Han virker stadig ganske svag, men han formår at dreje hovedet mod dig for at tale.>\n\nDu siger, at Katrine sendte dig? Velsign den kvinde. Tak, <Class>. Jeg står i din gæld."},
  [79970] = {n="Æonas den Retfærdiggjorte", l="Mød Æonas i Lysets Katedral i Stormvind.", d="Tak fordi du reddede mig, <Class>. Det ser ud til, at jeg ikke er så ung, som jeg engang var, og jeg tror, jeg får brug for allierede til det, der skal komme. Mød mig venligst i Stormvind, i Lysets Katedral, så snart du kan.\n\nBekymr dig ikke om mig, jeg kan finde vej herfra selv. Jeg har bare brug for et par øjeblikke til at genvinde min styrke", c="Jeg kan ikke takke dig nok for at redde mig fra det lysforladte sted. Desværre frygter jeg, at dette kun er begyndelsen på vores rejse, og resten bliver ikke let. Lad os tale og planlægge vores næste skridt.\n\nÅh, men først... lad denne gamle mand give noget af sin viden videre til den yngre generation. Det er ikke en stor belønning, men jeg håber, du kan bruge den godt alligevel."},
  [79981] = {n="Den Tærede Kerne", l="Find nogen, der kan reparere den tærede G-7 C.O.R.E.-processor.", d="Denne C.O.R.E.-enhed passer helt sikkert til beskrivelsen, Ziri gav dig, men den er slemt beskadiget og dækket af klidder. Du kan knap nok tyde et falmet klistermærke med det, der ser ud til at være kontaktoplysninger til en eller anden garantiordning. Kun få bogstaver er synlige.\n\n\"Limi... garan... krav kontak.... Wi..... nde...ar\"", p="Når nogen bygger et tårn og et værksted oven på et kæmpe spir midt i ingenting, er det næsten, som om de ikke vil have uventede gæster. Hvem skulle have troet det?", c="<Wirdals forstørrelsesbriller giver en lav, mekanisk summen, mens de fokuserer på den tærede G-7 C.O.R.E.-processor i din hånd> Jo, den er en af mine.\n\nJeg vil stærkt anbefale, at du smider den ud i havet og aldrig tænker på den igen."},
  [79982] = {n="Garantikrav", l="Bring Wirdal Vidundergear en Ladet Tomkerne.", d="Jeg kan reparere den processor til dig, men jeg har brug for en noget svær at skaffe genstand: en Ladet Tomkerne. Slangefolk-tryllekunstnere er kendt for at bære dem, og selvom jeg ikke kan være sikker på, hvor slangefolkene får dem fra, eller hvordan de bliver lavet, har de en tendens til at fungere som kraftfulde fokuspunkter for visse typer magiske ritualer. De er nøglekomponenten i min G-7 C.O.R.E.-processor. De er ikke almindelige, så du kan få en hård tid med at finde en.", p="Jeg gyser ved tanken om, hvor mange slangefolk du måtte banke for at få fat i den her ting.", c="Nå, her går det løs.\n\nJeg føler mig nødt til at give dig ansvarsfraskrivelsen, at jeg ikke kan holdes ansvarlig for elektriske brande, elektromagnetiske pulsudbrud, dæmoniske manifestationer eller interdimensionelle hvirvler, der måtte opstå ved installation og brug af denne processor."},
  [79984] = {n="Kvadrangulering", l="Find Wirdal Vidundergears Kvadrangulerings-fyrtårne og afstem dem. Der er fire af dem, og de ligger et sted i Kalimdør.", d="Wirdal? Ja, jeg kender ham. Han er en gnom, men det vil jeg ikke bruge imod ham, for han er en transpolyportions-entusiast ligesom mig selv. Han smuttede herfra for et par måneder siden til et sted i Kalimdør, men han transpolyporterer ind nu og da for at hente forsyninger. Jeg kunne nok transpolyportere dig over til ham, men så skal jeg bruge hans koordinater, ellers ender du nok bare inde i et bjerg eller noget. Hvis du kan finde hans kvadrangulerings-fyrtårne i Kalimdør og afstemme dem, så ville det klare sagen!", p="Fandt du fyrtårnene?", c="Wow, du fandt dem. Giv mig et øjeblik til at slå koordinaterne ind og kalibrere transponderen ....\n\n... og så er vi i gang! Jeg tror, det burde klare sagen."},
  [79985] = {n="Et Fint Rod", l="Eskorter Kernobi til udgangen af Clockwerk-løbet og rapportér derefter til Skuti i Bytteviken.", d="<Kernobi stønner.> Hvad.. Hvad skete der?\n\nSidste ting, jeg husker, er, at en gruppe mørkejern-dværge tog mig til fange, tævede mig, så jeg næsten døde, og så kastede dem mig herned sammen med disse beskidte troggs.\n\nFør mig ud herfra, <Name>!\n\nHer er planen: Før mig til udgangen; hvis vi kommer levende ud, så tag til Bytteviken og lad Skuti vide, at jeg tog til Skralleby for at advare Tinkervismand om mørkejernenes involvering i fremstillingen af den super-rig.\n\nLad os komme afsted!", c="Jeg må vel belønne dig for at bringe Kernobi tilbage til os i ét stykke, <Name>. Hvis du tager tilbage til Nisseborgen, kan de her måske give dig den fordel, du skal bruge for at besejre den nytteløse ryggestikker, Mekgineer Thermaplugg."},
  [79986] = {n="Skidtbelagt Ring", l="Find ud af, hvordan du fjerner skidtet fra den Skidtbelagte Ring.", d="Du har afdækket, hvad der ser ud til at være en ring fra liget af en af mørkejern-dværgene. Det er svært at se, hvilken slags ring det er, for jord og hærdede rester dækker genstanden fuldstændigt, så det er umuligt at bære den. Du tror, du kan skimte det svage skær af ædelt metal og måske endda glimtet fra en ædelsten under restene.\n\nHvis du vil bruge den ring, skal du finde noget, der kan få de hærdede rester af den.", p="Den gnomiske indretning foran dig har en plade, der kalder den \"Glimtematic 5200\". Ifølge instruktionerne under pladen er maskinens formål at skrubbe snavs væk fra en genstand. Maskinen har en møntsprække, der tager tre sølvmønter for at starte processen, når genstanden er lagt indeni.\n\nDet ser ud til, at den skidtbelagte ring, du fandt tidligere, er lige det rigtige at prøve i denne maskine!", c="Du lægger ringen inde i Glimtematic 5200 og smider en sølvmønt i sprækken.\n\nSmertefulde knasende lyde udsendes fra maskinen, mens den begynder at rykke voldsomt. Man kan kun gætte på, hvad der sker med ringen inde i maskinen ...\n\nMaskinen stopper pludselig og fanfarer sit ophør med et enkelt \"Klang!\" Genstandsrummet åbner sig og afslører en lille æske, pænt pakket ind med en rød sløjfe. Det ser ud til, at Glimtematic 5200 også pakker gaver ind!"},
  [79987] = {n="Ringens Tilbagevenden", l="Du kan enten beholde ringen, eller du kan finde den person, der står bag præget og gravéringerne på indersiden af ringen.", d="Når du åbner æsken fra Glimtematic 5200, viser det sig, at du havde mistanke om rigtigt - en blank ring! Når du tager ringen på, mærker du magisk kraft strømme gennem din krop.\n\nInde i ringen er et lille, men alligevel tydeligt aftryk af seglet fra Jernsmede. Ved siden af det er tre små initialer indgraveret: \"TdK\". Det kan betyde enten initialerne på den forrige ejer eller måske initialerne på ringens skaber. Behold ringen ... eller returnér den til denne person. Beslutninger, beslutninger ...", p="Hey, rolig nu, makker - jeg er en meget vigtig forretningsmand! Jeg er sikker på, at budet bare er forsinket med huslejen ... vent ... du er ikke min udlejer.\n\nNåh, selvfølgelig er du ikke - hvor er jeg dum! Du er kommet til mig for at søge den fineste juveler i hele Jernsmede, en der IKKE laver FORBANDEDE genstande! Ja!\n\nÆh ... hvad har du brug for?", c="En ring, siger du? Lad os se ... jo, jeg lavede den ring, ved min sjæl.\n\nFør Nisseborgen gik ned, havde jeg en lille butik der. Måske er det en, jeg efterlod, da jeg løb til bjergene; det er et simpelt design, og jeg lavede flere lignende. Måske er den fra en, der ikke kom ud i live.\n\nMørkejern-dværge havde den her? Nå, det lægger et nyt lag af konspiration oveni de ni forskellige lag, der allerede svæver rundt. Måske vil myndighederne gerne vide det; det er spildt på folk som mig.\n\nNu, tilbage til ringen ..."},
  [79990] = {n="Stranglethorn-tømmer", l="Bring Sergent Maklær en Forsendelse af Stranglethorn-tømmer.", d="Vi har desperat brug for yderligere ressourcer og forstærkninger for at støtte vores mål i Arathi-bækkenet. Passende tømmer har været særligt svært at skaffe, og vi har været nødt til at lede så langt væk som Stranglethorn-dalen for at finde det, vi har brug for. Bring mig en Forsendelse af Stranglethorn-tømmer, så bliver din støtte ikke overset.", p="Har du bragt os friske forsyninger?", c="Tak, <Class>. Det her vil hjælpe os med at vende udviklingen i Arathi-bækkenet."},
  [79991] = {n="Stranglethorn-tømmer", l="Bring Dødsstalker Mortus en Forsendelse af Stranglethorn-tømmer.", d="Vi har desperat brug for yderligere ressourcer og forstærkninger for at støtte vores mål i Arathi-bækkenet. Passende tømmer har været særligt svært at skaffe, og vi har været nødt til at lede så langt væk som Stranglethorn-dalen for at finde det, vi har brug for. Bring mig en Forsendelse af Stranglethorn-tømmer, så bliver din støtte ikke overset.", p="Har du bragt os friske forsyninger?", c="Tak, <Class>. Det her vil hjælpe os med at vende udviklingen i Arathi-bækkenet."},
  [80001] = {n="Genantænd", l="En slukket ildgrube. Veddet er endda tørt nok til at tage ild.", p="En slukket ildgrube. Veddet er endda tørt nok til at tage ild.", c="Du sætter dine spejderevner i brug."},
  [80098] = {n="Nysgerrig Dalarn-relikvie", l="Har du fundet en af de stjålne relikvier?", p="Har du fundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at den bliver sikkert returneret til byen."},
  [80120] = {n="En Tjeneste til Dalarn", l="Du har gjort en stor tjeneste for Dalarn og for Azerot.\n\nVores love forbyder mig at dele Dalarns hemmeligheder med udenforstående, men jeg tror, jeg kan bøje reglerne lidt for at belønne dig for din indsats. Værsgo, tag den her."},
  [80131] = {n="Gnom-forbedring", l="Bring den Strålende Guldring, en Sølvbarre, en Mosagat og 30 sølvmønter til Talvash den Kisselske i Jernsmede.", d="Hør her, <Name>, ringen er din, javel ... men jeg kan lave en bedre til dig! Det design, som jeg sagde, er virkelig simpelt. Jeg er meget mere dygtig nu, og for blot en pris på tredive sølvmønter pynter jeg den op til dig! Nå, lidt mere end tredive, faktisk ...\n\nJeg er i en klemme lige nu; hele mit materialelager er tørret ud. Hvis du bringer mig en sølvbarre og en mosagat, tilføjer jeg et gitter af sølv og agat til ringen, som giver den lidt mere pizzaz!\n\nStol på mig!", p="Har du de materialer, jeg skal bruge? Jeg ville ikke bede dig om dem, hvis jeg ikke var nede med flaget ...", c="Ah, præcis det, jeg havde brug for! Engang, når jeg kommer ud af det hul, jeg uretfærdigt sidder i, vil jeg lave de fineste småting i hele Azerot til dig, til ALLE! Indtil da, tak for at være sport omkring reagenserne. Jeg ville normalt tage ti gange det, jeg har taget af dig, for en ring af denne kvalitet ...\n\nApropos ringe, her er din nye!"},
  [80132] = {n="Rig-krigene", l="Hent Rig-tegningerne og Thermapluggs Boks-kombination fra Nisseborgen og bring dem til Nogg i Orgrimgrad.", d="Gnomisk teknologi - for to år siden var dens mest almindelige brug som en vittighed. Tiderne har bestemt ændret sig. Nu har de bygget en ny rig, der er bedre end alle vores hakkermodeller tilsammen. Jeg skal bruge tegningerne, <Name>!\n\nDesværre er planerne låst inde i en boks nær Mekgineer Thermaplugg. For at gøre tingene værre er kombinationen til boksen kun kendt af Mekgineer Thermaplugg.\n\nGør, hvad du skal for at få fat i den kombination, <Name>. Knæk så boksen op og bring mig de tegninger!", p="Jeg kan ikke se nogen tegninger. Har du gemt dem et sted på din krop, eller står du bare her for at irritere mig?", c="Jeg vidste, du kunne det, <Name>! Tvivlar derimod, han var i tvivl.\n\n\n\nNu hvor vi har tegningerne i vores besiddelse, er det kun et spørgsmål om tid, før vi finder ud af alle de gnomiske innovationer, der gik ind i skabelsen af riggen, og laver dem om til kobold-innovationer til vores nye hakkermodeller."},
  [80133] = {n="Overingeniør Skuti", l="Tal med Skuti i Bytteviken.", d="Så snart vi fik besked fra Kernobi om den nye gnomiske rig, begyndte Skuti og jeg at arbejde på Transpolyportøren 6000: den hurtigste og mest pålidelige vej til Nisseborgen.\n\nDen er endelig klar til passagerer, <Name>. Hvis du vil prøve den, så tag til Bytteviken og tal med Skuti ved vindrytterrederne. For at komme til Bytteviken, tag båden fra Skralleby.\n\nSelvfølgelig kunne du altid prøve at tage turen til Nisseborgen gennem de dværgeinficerede bjerge i Dun Frostbakke!", c="Hun er en skønhed, ikke? Toppen af kobold-transportteknologi - er kun eksploderet et dusin gange.\n\nBare rolig, <Name>, jeg har fået hende repareret. Hun vil ikke springe i luften under dig - og hvis hun gør, så går det hurtigt og smertefrit."},
  [80134] = {n="Gnomer-væææk!", l="Vent på at Skuti kalibrerer Nisse-transponderen.", d="Så længe du har transponderen i din besiddelse, skal du bare træde på pladen, så bliver du transporteret til Nisseborgen.\n\nDu kan opleve nogle usædvanlige bivirkninger, men ingen af dem burde være permanente ... længere.\n\nJeg glemte næsten den vigtigste del - at komme tilbage. Når du er klar til at vende hjem, skal du bare træde på transpolyportpladen i Nisseborgen!\n\nNu skal transponderen kalibreres til din størrelse og vægt.", c="Færdig! Når du er klar, så bare træd på pladen."},
  [80135] = {n="Klockmorts Essentielle Ting", l="Tal med Klockmort Skruespænd i Jernsmede.", d="En gnomisk ven, Klockmort Skruespænd, sendte mig besked fra Jernsmede. Han fortæller, at han har brug for hjælp til et farligt, men essentielt, ærinde ind i Nisseborgen, den engang så store gnomby, som nu er forurenet og fyldt med gale gnomer og deres apparater.\n\nJeg må blive her, men mit hjerte værker over at hjælpe min ven. Hvis du kan gå i mit sted, ville jeg stå i gæld til dig.\n\nDu kan finde Klockmort i Tinkerbyen i Jernsmede.", c="Det gør jeg! Jeg har virkelig brug for hjælp til et ærinde ind i Nisseborgen. Og du er lige den <Class>, der kan klare det!"},
  [80136] = {n="Essentielle Kunstigheder", l="Bring 12 Essentielle Kunstigheder til Klockmort Skruespænd i Jernsmede.", d="En næsten universel mekanisk komponent - den essentielle kunstighed - var af stor nytte for tinkerne og smedene i Nisseborgen. Men under den febrilske flugt fra vores by huskede ingen at tage nogen af disse apparater med sig! Og jeg har brug for en stor forsyning af dem til et arbejde, jeg snart skal i gang med.\n\nVær sød at gå ind i Nisseborgen og skaffe mig nogle essentielle kunstigheder. Du finder dem i byens dybere områder, opbevaret i beholdere kaldet kunstige ekstrapolatorer.\n\nTak, <Name>, og skynd dig venligst!", p="Har du de essentielle kunstigheder?", c="Du fik dem! Nu kan jeg begynde mine nye eksperimenter!\n\nJeg kan ikke takke dig nok, <Name>! Din tapperhed har fremmet gnomisk forskning med et kæmpe spring!"},
  [80137] = {n="Red Teknobottens Hjerne!", l="Bring Teknobottens Erindringskerne til Tinkermester Overgnist i Jernsmede.", d="Da vores elskede by Nisseborgen faldt, må en løbsk gnist have ramt min stakkels skabning, Teknobot. Den hjalp engang mig og mine kolleger med sine utallige gadgets og en grænseløs lagerplads af information, men dens positroniske hjerne er blevet polariseret. Nu er den negatronisk ... og Teknobottens adfærd er vendt om. Den strejfer rundt i Nisseborgen i et raseri!\n\nMen måske kan den reddes. Måske, hvis du kan hente Teknobottens erindringskerne og bringe den til mig, kan jeg finde årsagen til polariseringen og reparere min stakkels Teknobot.", p="Fandt du Teknobot? Hentede du dens erindringskerne??", c="Åh, det er vidunderligt! Tak, <Name>! Jeg går straks i gang!!\n\nStakkels, stakkels Teknobot ... Vær ikke ked af det. Vi får dig fikset.\n\nNu, hvor lagde jeg så proppen til min hydro-jack drejeskruenøgle ..."},
  [80138] = {n="Tinkermester Overgnist", l="Tal med Tinkermester Overgnist i Jernsmede.", d="Tinkermester Overgnist er meget oprevet over skæbnen for sin mekaniske skabning, Teknobot. Jeg husker Teknobot som et venligt og hjælpsomt redskab for gnomerne, men Overgnist fortæller mig, at den er blevet ødelagt.\n\nMeget trist. Men måske kan han med held blive repareret!\n\nTal med Tinkermester Overgnist i Tinkerbyen i Jernsmede. Han vil sætte pris på din hjælp.", c="Ja, det er sandt. Teknobot er blevet løbsk! Kan du hjælpe mig, vær venlig?"},
  [80139] = {n="Gnoginne", l="Brug den Tomme Blyindsamlingsflaske på Bestrålede Indtrængere eller Bestrålede Plyndrere for at samle radioaktivt nedfald. Når den er fuld, skal du tage den tilbage til Ozi Skiftevolt i Kharanøs.", d="Siden ulykken er alt, Gnåhrn tænker på eller taler om, at rense Nisseborgen for troggs-infestationen og finde en kur mod sygdommen, der plager den, <Name>.\n\nHeldigvis er Tumult og jeg tæt på en form for kur - ellers er det opskriften på en virkelig stærk rom. Vi ved det ikke, før vi tester! Naturligvis, for at teste vores teori, får vi brug for nogle få ting; nemlig nedfald fra de bestrålede troggs i Nisseborgen. Fyld denne flaske med det grønne skær og bring den tilbage!", p="Kan du ikke se, at vi prøver at kurere en hel art gnomer her??! Vi har brug for mere af det grønne skær!", c="Fremragende arbejde! Tiden er kommet til at teste den nye formel. Hvis det virker, skulle den fangede spedalske gnom ikke bare være kureret, men jeg burde også få et helt hoved med hår! Træd tilbage!"},
  [80140] = {n="Ringens Tilbagevenden", l="Du kan enten beholde ringen, eller du kan finde den person, der står bag præget og gravéringerne på indersiden af ringen.", d="Når du åbner æsken fra Glimtematic 5200, viser der sig en blank ring! Når du tager ringen på, mærker du magisk kraft strømme gennem din krop.\n\nInde i ringen er et lille, men alligevel tydeligt aftryk af seglet fra Orgrimgrad. Ved siden af er indgraverede bogstaver, men kun de første tre skiller sig ud, selv efter rensning: \"NOG...\"\n\nDet kan betyde enten initialerne på den forrige ejer eller måske initialerne på ringens skaber. Behold ringen ... eller find \"NOG\" - beslutninger, beslutninger ...", p="Man skulle tro, at vi selv kunne finde en måde at overgå de snavsede små gnomer på. Jeg vil endda vædde på, at de stjal riggen fra os i første omgang! Bah, de fedtede, beskidte ... øh, ja? Har du brug for noget?", c="En ring fra Nisseborgen? Lad os se ... ikke min, men interessant.\n\nNisseborg-sagen - den kunne ikke være sket for en pænere flok tossede kujoner. I årevis har de været en vittighed, og nu laver de næsten fra den ene dag til den anden bedre rigge end os?\n\nMørkejern-dværge havde ringen? Det er endnu mere interessant! Måske stjal gnomerne deres sindssyge golem-planer og modificerede dem. De mørkejern-dværge vil helt sikkert have en stor gengældelse. Det er bestemt værd at undersøge.\n\nJa, apropos den ring ..."},
  [80141] = {n="Noggs Ringomarbejdning", l="Bring den Strålende Guldring, en Sølvbarre, en Mosagat og 30 sølvmønter til Nogg i Orgrimgrad.", d="Nej, nej, nej - jeg siger ikke pludselig, at ringen er min. Jeg gør normalt ikke sådan noget, men dine oplysninger om mørkejern-dværgene var meget nyttige. Jeg forbedrer din ring for dig, bedre end nogen, der lavede denne simple lille ting, nogensinde kunne have gjort. Sikkert en eller anden gnom ...\n\nHvis du bringer mig en sølvbarre, en mosagat og tredive sølvmønter for besværet, tilføjer jeg et gitter af sølv og agat til ringen, som styrker magien indeni den. Interesseret?", p="Har du de materialer, jeg skal bruge? Jeg kan ikke forbedre dette design uden alt det, jeg har bedt om.", c="Her er din ring, bedre end før. Tak igen for oplysningerne om mørkejern-dværgene. Det virker som en rimelig ledetråd til, hvordan de gnomer pludselig blev ramt af kobold-lignende inspiration."},
  [80142] = {n="Kastrørs Opgave", l="Tal med Mestermekaniker Kastrør i Jernsmede.", d="Mestermekaniker Kastrør i Jernsmede har brug for eventyrere! Han organiserer hold til at gå ind i Nisseborgen igen på en datahentningsmission af højeste sikkerhed og betydning.\n\nKastrør er måske ikke medlem af Den Oplyste Forsamling for Arkanologi, Alkymi og Ingeniørvidenskab, sådan som jeg er, men han er stadig en klog gnom, så hvis han synes, det er vigtigt, så er der ifølge mine beregninger en sandsynlighed på fireogfirs procent for, at det virkelig er vigtigt!\n\nDet er gode odds!"},
  [80143] = {n="Datareddelse", l="Bring et Prismatisk Hulkort til Mestermekaniker Kastrør i Jernsmede.", d="Da vi flygtede fra Nisseborgen, efterlod vi så mange data! Vitalt vigtige data!\n\nJeg har brug for dataene på et prismatisk slagkort fra en Matrix Hulgraf 3005-D højsikkerhedsterminal, dybt inde i Nisseborgen. Du skal få adgang til terminalen, men for at gøre det skal du først have adgangstilladelse ... og for at få den, skal du tilgå terminaler med lavere sikkerhed - modellerne -A, -B og -C. Og for at gøre DET skal du bruge sikkerhedsslagkort, og de starter med hvide ... og vi efterlod alle slagkortene i byen.\n\nDet er en katastrofe! Kan du hjælpe?", p="Har du det prismatiske hulkort??", c="Du gjorde det! Du fandt det prismatiske hulkort og genfandt de tabte data! Vitalt, kritisk, umådeligt vigtige data, som vi ikke kunne leve et eneste øjeblik mere uden!\n\nDin tjeneste for gnomerne vil blive husket længe, <Name>."},
  [80147] = {n="Nysgerrig Dalarn-relikvie", l="Har du fundet en af de stjålne relikvier?", p="Har du fundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at den bliver sikkert returneret til byen."},
  [80148] = {n="Nysgerrig Dalarn-relikvie", l="Har du genfundet en af de stjålne relikvier?", p="Har du genfundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at denne bliver sikkert returneret til byen."},
  [80149] = {n="Nysgerrig Dalarn-relikvie", l="Har du genfundet en af de stjålne relikvier?", p="Har du genfundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at denne bliver sikkert returneret til byen."},
  [80150] = {n="Nysgerrig Dalarn-relikvie", l="Har du genfundet en af de stjålne relikvier?", p="Har du genfundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at denne bliver sikkert returneret til byen."},
  [80151] = {n="Nysgerrig Dalarn-relikvie", l="Har du genfundet en af de stjålne relikvier?", p="Har du genfundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at denne bliver sikkert returneret til byen."},
  [80152] = {n="Nysgerrig Dalarn-relikvie", l="Har du genfundet en af de stjålne relikvier?", p="Har du genfundet en af de stjålne relikvier?", c="Tak, <Name>. Jeg sørger for, at denne bliver sikkert returneret til byen."},
  [80153] = {n="Den Glimmatic 5200!", l="Indsæt en skidt-indkrystalliseret genstand i Den Glimmatic 5200, og sørg for at have tre sølvmønter for at starte maskinen.", d="Denne grejbank står ud blandt gnomerne, der holder stand mod galskaben uden for rummet. En lille plade på apparatet lyder \"Den Glimmatic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester ødelægger dine glimmerting? Den Glimmatic 5200 får glansen tilbage i glans-fantastisk! Indsæt den genstand, du ønsker at rense, og læg tre sølvmønter i møntsprækken. Giv Den Glimmatic 5200 et øjeblik til at virke, og voilà! Dine skatte vil komme frem rene og blanke!\"", p="Det ser ud til, at apparatet har brug for et skidt-indkrystalliseret objekt til at rense og tre sølvmønter for at få grejet til at virke. Så længe begge er til stede, bør Den Glimmatic 5200 virke...", c="Du indsætter det skidt-indkrystalliserede objekt og tre sølvmønter i Den Glimmatic 5200. Maskinen sprætter til live i et rasende forsøg på at rense skidtet fra det ukendte objekt. Høje, voldsomme rumlelyde buldrer fra maskinens hjerte. Apparatets metalramme knirker og stønner, mens det vakler fra side til side..."},
  [80155] = {n="Mere Gnistrematic-action", l="Den Glimmatic 5200 er tom og venter på et skidt-indkrystalliseret objekt, der skal renses, og tre sølvmønter for at starte!", p="Den Glimmatic 5200 er tom og venter på et skidt-indkrystalliseret objekt, der skal renses, og tre sølvmønter for at starte!", c="Den Glimmatic 5200 sprætter til live og vakler frem og tilbage. Indeni bliver det hjælpeløse skidt, der har indkrystalliseret genstanden placeret deri, knust af maskinens gnomiske rengøringsmiddel.\n\nDen Glimmatic 5200 kommer til standsning, ledsaget af et velkendt \"klink!\" Maskinens genstandsbeholder spiraler op og åbner sig og afslører en pænt indpakket kasse."},
  [80156] = {n="Den Glimmatic 5200!", l="Indsæt en skidt-indkrystalliseret genstand i Den Glimmatic 5200, og sørg for at have tre sølvmønter for at starte maskinen.", d="Denne grejbank står ud blandt gnomerne, der holder stand mod galskaben uden for rummet. En lille plade på apparatet lyder \"Den Glimmatic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester ødelægger dine glimmerting? Den Glimmatic 5200 får glansen tilbage i glans-fantastisk! Indsæt den genstand, du ønsker at rense, og læg tre sølvmønter i møntsprækken. Giv Den Glimmatic 5200 et øjeblik til at virke, og voilà! Dine skatte vil komme frem rene og blanke!\""},
  [80157] = {n="Den Glimmatic 5200!", l="Lige så hurtigt som den startede, standser Den Glimmatic 5200 brat. Et simpelt \"klink\" lyder fra maskinen, og maskinens mund spiraler opad. Inde i Den Glimmatic 5200 ligger en lille kasse, pakket ind i en lille sløjfe. Maskinen ser ud til at pakke en genstand ind, efter at have fjernet dens skidt-indkrystalliserede status. Selvom maskinen ikke virkede, er genstanden i det mindste nu pakket ind i en flot kasse.\n\nNå, der er én måde at finde ud af, om den renser genstanden eller ej..."},
  [80158] = {n="Den Glimmatic 5200!", l="Indsæt en skidt-indkrystalliseret genstand i Den Glimmatic 5200, og sørg for at have tre sølvmønter for at starte maskinen.", d="Denne grejbank står ud blandt gnomerne, der holder stand mod galskaben uden for rummet. En lille plade på apparatet lyder \"Den Glimmatic 5200\", efterfulgt af noget tekst:\n\n\"Skidt og rester ødelægger dine glimmerting? Den Glimmatic 5200 får glansen tilbage i glans-fantastisk! Indsæt den genstand, du ønsker at rense, og læg tre sølvmønter i møntsprækken. Giv Den Glimmatic 5200 et øjeblik til at virke, og voilà! Dine skatte vil komme frem rene og blanke!\"", p="Det ser ud til, at apparatet har brug for et skidt-indkrystalliseret objekt til at rense og tre sølvmønter for at få grejet til at virke. Så længe begge er til stede, bør Den Glimmatic 5200 virke...", c="Du indsætter det skidt-indkrystalliserede objekt og tre sølvmønter i Den Glimmatic 5200. Maskinen sprætter til live i et næsten rasende forsøg på at rense skidtet fra det ukendte objekt. Høje, voldsomme rumlelyde buldrer fra maskinens hjerte. Apparatets metalramme knirker og stønner, mens det vakler fra side til side..."},
  [80160] = {n="Mere Gnistrematic-action", l="Den Glimmatic 5200 er tom og venter på et skidt-indkrystalliseret objekt, der skal renses, og tre sølvmønter for at starte!", p="Den Glimmatic 5200 er tom og venter på et skidt-indkrystalliseret objekt, der skal renses, og tre sølvmønter for at starte!", c="Den Glimmatic 5200 sprætter til live og vakler frem og tilbage. Indeni bliver det hjælpeløse skidt, der har indkrystalliseret genstanden placeret deri, knust af maskinens gnomiske rengøringsmiddel.\n\nDen Glimmatic 5200 kommer til standsning, ledsaget af et velkendt \"klink!\" Maskinens genstandsbeholder spiraler op og åbner sig og afslører en pænt indpakket kasse."},
  [80161] = {n="Den Glimmatic 5200!", l="Lige så hurtigt som den startede, standser Den Glimmatic 5200 brat. Et simpelt \"klink\" lyder fra maskinen, og maskinens mund spiraler opad. Inde i Den Glimmatic 5200 ligger en lille kasse, pakket ind i en lille sløjfe. Maskinen ser ud til at pakke en genstand ind, efter at have fjernet dens skidt-indkrystalliserede status. Selvom maskinen ikke virkede, er genstanden i det mindste nu pakket ind i en flot kasse.\n\nNå, der er én måde at finde ud af, om den renser genstanden eller ej..."},
  [80164] = {n="Store Klyngeraketter", l="Store klyngeraketter kræver enorme ressourcer og færdigheder at skabe, men deres glans og skønhed er den indsats værd! Bring mig forfædremønter, så giver jeg dig kendskabet til deres fremstilling.", p="Store klyngeraketter kræver enorme ressourcer og færdigheder at skabe, men deres glans og skønhed er den indsats værd! Bring mig forfædremønter, så giver jeg dig kendskabet til deres fremstilling.", c="Tak, <Name>. Her er opskriften på store klyngeraketter. Må dine produkter bringe glæde og held til alle, der stirrer op på dem."},
  [80165] = {n="Klyngeraketter", l="Klyngeraketter er en samling af enkelte raketter, og deres skønhed er fantastisk! Bring mig forfædremønter, så deler jeg kendskabet til deres skabelse med dig...", p="Klyngeraketter er en samling af enkelte raketter, og deres skønhed er fantastisk! Bring mig forfædremønter, så deler jeg kendskabet til deres skabelse med dig...", c="Her er de, <Name>. Tag disse opskrifter og lær deres hemmeligheder. Jeg ønsker dig lykke, og jeg ser frem til at se dine storslåede skabelser."},
  [80166] = {n="Små Raketter", l="Jeg besidder hemmelighederne bag at skabe Månefestivalens raketter, og jeg deler gerne min viden med de æredsfulde.\n\nTil gengæld for forfædremønter kan jeg tilbyde dig opskriften på at lave en lille raket...", p="Jeg besidder hemmelighederne bag at skabe Månefestivalens raketter, og jeg deler gerne min viden med de æredsfulde.\n\nTil gengæld for forfædremønter kan jeg tilbyde dig opskriften på at lave en lille raket...", c="Åh, meget godt. Her er dine opskrifter, <Name>, og må Elunie velsigne dig."},
  [80167] = {n="Store Raketter", l="Store festivalraketter lyser himlen strålende op - kun klyngeraketterne kan måle sig med deres storhed!\n\nBring mig forfædremønter, <Name>, så deler jeg kendskabet til deres skabelse.", p="Store festivalraketter lyser himlen strålende op - kun klyngeraketterne kan måle sig med deres storhed!\n\nBring mig forfædremønter, <Name>, så deler jeg kendskabet til deres skabelse.", c="Meget godt - jeg accepterer disse forfædremønter. Her er dine opskrifter, <Name>. Må du bruge dem til at udbrede Elunies herlighed!"},
  [80168] = {n="Fyrværkerikaster", l="Selvom raketter er en vidunderlig måde at fejre på, skal de, for at man kan se deres herlighed... affyres fra en kaster.\n\nBring mig forfædremønter, så kan jeg tilbyde dig kendskabet til at skabe raketkastere som dem, du ser i Månelunden.", p="Selvom raketter er en vidunderlig måde at fejre på, skal de, for at man kan se deres herlighed... affyres fra en kaster.\n\nBring mig forfædremønter, så kan jeg tilbyde dig kendskabet til at skabe raketkastere som dem, du ser i Månelunden.", c="Her er du, <Name>. Her er skematicet til at skabe en fyrværkerikaster. Placér kastere, hvor du ønsker at fejre, og byd så dine venner velkommen til at deltage!"},
  [80169] = {n="Klyngekaster", l="De mest prægtige fyrværkeriopvisninger må inkludere klyngeraketter, og disse klyngeraketter skal affyres fra klyngekastere! Er det ikke logisk, at du lærer hemmelighederne bag at lave klyngekastere? Bring mig forfædremønter, så giver jeg dig denne viden.", p="De mest prægtige fyrværkeriopvisninger må inkludere klyngeraketter, og disse klyngeraketter skal affyres fra klyngekastere! Er det ikke logisk, at du lærer hemmelighederne bag at lave klyngekastere? Bring mig forfædremønter, så giver jeg dig denne viden.", c="Her er dit skematic. Studér det nøje, og lær...\n\nHeld og lykke, <Name>. Må dine fejringer måle sig med Månefestivalens egne!"},
  [80170] = {n="Festlige Opskrifter", l="Kjolerne og dragterne, du ser, er traditionelt tøj fra mange år tilbage. De bæres til ære for gamle skikke og afdøde kære.\n\nHvis du bringer mig forfædremønter, <Name>, så giver jeg dig mønsteret til at skabe traditionelle røde kjoler eller dragter.", p="Kjolerne og dragterne, du ser, er traditionelt tøj fra mange år tilbage. De bæres til ære for gamle skikke og afdøde kære.\n\nHvis du bringer mig forfædremønter, <Name>, så giver jeg dig mønsteret til at skabe traditionelle røde kjoler eller dragter.", c="Her er mønstrene, <Name>. Jeg er sikker på, at du vil finde produktet af denne viden ganske smukt."},
  [80180] = {n="Det Storslåede Forræderi", l="Rejs til Nisseborgen og dræb Mekgineer Thermaplugg. Vend tilbage til Højtinker Mekkatorque, når opgaven er udført.", d="Jeg stolede på Termaplugg, <Race>. Jeg havde aldrig troet, at han ville forråde mig og hele det gnomiske folk. Og for hvad? Magt? Rigdom? Ting, som han ville have fået med tiden. Nu er vi blevet fordrevet fra vores hjem, og den galning er nu i ledelse. Kongen af ingenting....\n\nVi vil generobre Nisseborgen, <Name>. Vi holder ikke op, før byen er tilbage under vores kontrol. Hvis du ønsker at deltage i vores kamp, beder jeg om en simpel opgave: Dræb forræderen. Ødelæg Mekgineer Thermaplugg.", c="Jeg kan godt lide at tro, at det sidste, der gik gennem hans hoved, da han faldt sammen på jorden, var din fod, <Race>. Med Termaplugg død er vores planer om at generobre Nisseborgen et skridt tættere på at blive virkelighed."},
  [80181] = {n="Gyrodrillmatiske Gravemaskiner", l="Bring fireogtyve Robo-mekaniske Indvolde til Skoni i Stormvind.", d="Det er forfærdeligt, <Name>. Vi kommer ikke til at have nok dele til at få vores flåde af gyrodrillmatiske gravemaskiner til Dun Frostbakke.\n\nDet, vi har brug for, er reservedele, <Name>. Hvilket bedre sted at få reservedele til vores køretøjer end Nisseborgen? Jeg hører, at robotter og mekaniske væsener strejfer rundt dér som kvæg på en åben slette.\n\nDet, jeg har brug for, er, at du tager til Nisseborgen og river de robotter fra hinanden. Bring mig deres robotindvolde tilbage. To snese burde være tilstrækkeligt.", p="Hvis dette var et væddeløb, ville du have tabt nu.", c="Det her duer fint, <Name>. Én gyrodrillmatisk gravemaskine repareret; 398 tilbage."},
  [80182] = {n="Den Eneste Kur er Mere Grøn Glød", l="Rejs til Nisseborgen og bring Højpotent Radioaktivt Nedfald tilbage. Vær advaret, nedfaldet er ustabilt og vil kollapse ret hurtigt.\n\nOzi vil også kræve din Tunge Blyindsamlingsflaske, når opgaven er udført.", d="Ikke alene var din prøve utilstrækkelig i mængde, den var også urent.\n\nVi har brug for mere grøn glød. Trogger er åbenlyst ikke bestrålet nok til at opfylde vores behov. Du bliver nødt til at tage ind i Nisseborgen og bringe noget radioaktivt nedfald tilbage, direkte fra hanen. Jeg taler om de bestrålede slimer, lurkere og rædsler. Vær advaret, indeslutningen af denne type nedfald er vanskelig. Du må gøre flere forsøg med fiolen, indtil en passende prøve er indsamlet.", p="Hm, du lyser ikke. Det er et godt tegn.", c="<Ozi undersøger dig.> Imponerende, du har stadig alle dine lemmer. Nu er det tid til at se, hvad det her stof kan gøre!"},
  [80241] = {n="Smedningens Oprindelse", l="Bring seks Gyldne Skæl-armbeskyttere til Hank Hammeren i Stormvind.", d="Da jeg var på din alder, tog en dværg ved navn Galvin mig under sine vinger og oplærte mig i rustningssmedens veje. Før han forlod til Bytteviken, lovede han mig, at jeg ville oplære alle dem med lysten og besluttsomheden til at avancere i smedehåndværket -- så her er jeg -- alle disse år senere.\n\nNu er det din tur til at lære lidt. Lav mig seks gyldne skæl-armbeskyttere, så lærer du, hvor smedning kommer fra, <Name>.", p="Kunne du være Galvins næste discipel?", c="Meget godt, <Name>! Lyt og lær.\n\nSmedning kommer aldrig herfra!\n\nSmedning kommer aldrig herfra!\n\nSmedning kommer kun herfra!\n\nOg nu kender du smedningens oprindelse."},
  [80307] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt for! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [80308] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt for! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [80309] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt op! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [80324] = {n="Den Gale Konge", l="Bring Termapluggs Ingeniørnoter til Højtinker Mekkatorque i Tinkerbyen i Jernsmede.", d="Du finder en snavset, slidt notesbog fyldt med krøllede skemaer og noter. Det står klart, selv ved et hurtigt blik, at hver eneste af disse skabninger kunne bruges til at forvolde frygtelig ravage, hvis nogen var dumme nok til at bygge dem.", p="<Name>, hvad er det, du har dér?", c="Jeg kan ikke takke dig nok for at genvinde disse skemaer. Jeg gyser ved tanken om, hvad der var blevet af Jernsmede, hvis Termaplugg havde kunnet bruge disse skabninger mod os.\n\nDet her kalder på en fest!"},
  [80325] = {n="Den Gale Konge", l="Bring Termapluggs Ingeniørnoter til Nogg i Æresdalen i Orgrimgrad.", d="Du finder en snavset, slidt notesbog fyldt med krøllede skemaer og noter. Det står klart, selv ved et hurtigt blik, at hver eneste af disse skabninger kunne bruges til at forvolde frygtelig ravage, hvis nogen var dumme nok til at bygge dem.", p="Hvad har du til mig?", c="<Noggs øjne lyser op, mens han læser igennem samlingen af noter og skemaer>\n\nJeg skal sprænge så mange ting i luften med det her.\n\nGodt gået, <Name>. Jeg synes, det her kalder på en fest!"},
  [80411] = {n="Kazdør-talismanen", l="Find Kazdør-talismanen inde i Zul'Fjerrak. Bring den derefter til Fårhad i Ravnehold-herregården. Du skal fuldføre opgaven alene.", d="Ud fra det seneste brev vi opsnappede, ser det ud til, at den sidste genstand Kajus ønsker er Kazdør-talismanen. Brevet siger, at talismanen befinder sig et sted inde i Zul'Fjerrak.\n\nJeg vil have dig til at udføre opgaven efter Kajus' instrukser, så han ikke bliver mistænksom. Det betyder, at du skal gå ind i Zul'Fjerrak alene, som vanligt.\n\nMen før du leverer talismanen, skal du bringe den tilbage hertil. Vi kommer til at give Kajus lidt mere, end han har bedt om.", p="Gå nu, tiden er knap.", c="Fint tyveri, <Name>. Nu er det tid til trin to."},
  [80417] = {n="Bløde Buskede Haler", l="Det er utroligt, hvad folk værdsætter! Tag for eksempel en træpind med en blød buskede hale fast på. Du og jeg tænker måske, at sådan noget ikke er synderligt værdifuldt... men hvis du giver det skrammel et flot navn som \"Vild Dun-hale\" og lægger det i en pæn kasse, så vil folk tro, at det er værdifuldt. Skrald bliver til skat!\n\nSkaf mig bløde buskede haler fra ulvene i Forødelse og Ødelandene, så giver jeg dig billetter til Mørkemånens Marked.", p="Det er utroligt, hvad folk værdsætter! Tag for eksempel en træpind med en blød buskede hale fast på. Du og jeg tænker måske, at sådan noget ikke er synderligt værdifuldt... men hvis du giver det skrammel et flot navn som \"Vild Dun-hale\" og lægger det i en pæn kasse, så vil folk tro, at det er værdifuldt. Skrald bliver til skat!\n\nSkaf mig bløde buskede haler fra ulvene i Forødelse og Ødelandene, så giver jeg dig billetter til Mørkemånens Marked.", c="Godt gået, <Name>! Disse haler bliver til fine præmier for vores gæster, og det betyder glade gæster... som taler med deres venner og tager flere gæster med!\n\nHer er dine billetter! Hav det godt på Mørkemånens Marked... og glem ikke at fortælle dine venner om os!"},
  [80421] = {n="Grønjernsarmbeskyttere", l="Jeg arbejder på et nyt kostume, til den dag jeg har min egen bod som verdens stærkeste kvinde! Lige nu leder jeg efter nogle armbeskyttere, jeg kan bære. De må ikke dække meget, for folk vil se mine muskler, men jeg vil stadig gerne vise lidt farve, ved du?\n\nHvad med grønjernsarmbeskyttere, <Name>? Kan du lave grønjernsarmbeskyttere til mig? Hvis du kan, så har jeg en hel masse billetter til Mørkemånens Marked til dig.", p="Jeg arbejder på et nyt kostume, til den dag jeg har min egen bod som verdens stærkeste kvinde! Lige nu leder jeg efter nogle armbeskyttere, jeg kan bære. De må ikke dække meget, for folk vil se mine muskler, men jeg vil stadig gerne vise lidt farve, ved du?\n\nHvad med grønjernsarmbeskyttere, <Name>? Kan du lave grønjernsarmbeskyttere til mig? Hvis du kan, så har jeg en hel masse billetter til Mørkemånens Marked til dig.", c="Ja! Det er præcis, hvad jeg har brug for! Sådan en dejlig farve, og de efterlader stadig mine arme bare, så man kan se, hvor stærk jeg er! Perfekt!\n\nVær så god, <Name>. Her er dine billetter - nyd dem!"},
  [80422] = {n="Grønne fyrværkerier", l="Når jeg endelig får den bod op at køre, vil jeg have reklame! Og hvad er en bedre måde at reklamere på end med fyrværkeri?\n\nNogle tror måske, at lugten af en gryde, der koger med dine fjenders kogende hoveder, er bedre til at trække folk til, men... vi er i blandet selskab. Så det må blive fyrværkeri!\n\nBring mig grønne fyrværkerier, <Name>, så har jeg en stor håndfuld Mørkemånens Marked-billetter til dig.", p="Når jeg endelig får den bod op at køre, vil jeg have reklame! Og hvad er en bedre måde at reklamere på end med fyrværkeri?\n\nNogle tror måske, at lugten af en gryde, der koger med dine fjenders kogende hoveder, er bedre til at trække folk til, men... vi er i blandet selskab. Så det må blive fyrværkeri!\n\nBring mig grønne fyrværkerier, <Name>, så har jeg en stor håndfuld Mørkemånens Marked-billetter til dig.", c="Du bragte fyrværkeriet. Vidunderligt arbejde, <Name>! Jeg kan ikke vente med at tænde dem og fortælle verden, at min bod er klar! Jeg må dog stadig vente, en ret lang tid desværre, men... jeg bliver klar, når jeg er klar, ikke?\n\nHer er billetterne, <Name>. Hav det sjovt!"},
  [80423] = {n="Verdens Største Gnom!", l="Yebb Nebbelgir vil gerne tilføje mere talent til sit show, og han leder vidt og bredt efter verdens største gnom. Kender du nogen gnomer af betydelig størrelse?\n\nLænge før han finder gnomen, vil han have dens kostume klar. Jeg synes, en barbarisk sele ville være et godt grundlag for kostumet; kan du lave nogle seler og bringe dem til mig? Gør du det, så har jeg en stak Mørkemånens Marked-billetter til dig...", p="Yebb Nebbelgir vil gerne tilføje mere talent til sit show, og han leder vidt og bredt efter verdens største gnom. Kender du nogen gnomer af betydelig størrelse?\n\nLænge før han finder gnomen, vil han have dens kostume klar. Jeg synes, en barbarisk sele ville være et godt grundlag for kostumet; kan du lave nogle seler og bringe dem til mig? Gør du det, så har jeg en stak Mørkemånens Marked-billetter til dig...", c="Åh kære, de her er ret store!! Jeg kan ikke forestille mig at finde en gnom, der passer tæt i dem, men bekymr dig ikke - hvis gnomen, vi finder, ikke er stor nok, kan jeg justere hans kostume.\n\nTusind tak, <Name>. Her er de billetter, jeg lovede dig."},
  [80453] = {n="De Bedst Lagte Planer", l="Bring Kazdør-talismanen til Zan Skruespring i kælderen under Ravnehold-herregården.", d="Tag talismanen med ned til Zan Skruespring, i kælderen. Jeg har bedt ham installere en mekanisme i genstanden, der registrerer ethvert forsøg på at kanalisere magisk energi ind i eller ud af den.\n\nMekanismen er næsten usynlig for det blotte øje, og den eksploderer, når den udløses. Med lidt held bliver Kajus dræbt i udbruddet. Og i det mindste bliver hans planer for talismanen forpurret.", p="Ja, <Class>? Har du brug for noget fra mig?", c="Så du er på Fårhads opgave, hm? Meget godt. Giv mig talismanen, så går jeg i gang."},
  [80454] = {n="Ét Sidste Dropsted", l="Tag den modificerede talisman til Kajus' dødt dropsted nær Brandtræ-landsbyen.", d="Lokkemaden er klar, nu må vi lægge fælden. Jeg har modificeret talismanen efter Fårhads instrukser. Det eneste tilbage er, at du leverer den, som du har gjort med de andre genstande før.\n\nGå til hytten nær Brandtræ-landsbyen, og læg den modificerede talisman i Kajus' dødt dropsted.\n\nDet, der følger, er uden for vores kontrol, indtil videre.", p="<Kisten står tom.>", c="<Du lægger den modificerede talisman i kisten.>"},
  [80455] = {n="Vi Venter Og Ser", l="Rapporter tilbage til Fårhad i Ravnehold-herregården.", d="Jobbet er gjort. Du må hellere vende tilbage til Ravnehold og underrette Fårhad.", c="Det ser ud til, at alt er gået efter planen. Godt gået.\n\nAlt, vi kan gøre nu, er at vente på, at Kajus gør sit næste træk. Jeg giver dig besked, når tiden kommer. Dit engagement i herregården er ikke helt indfriet endnu.\n\nMen indtil videre kan du slappe af."},
  [80526] = {n="Nar Mig To Gange", l="Tal med Fårhad, når du er klar til at høre hans plan.", d="Ikke et øjeblik for tidligt, <Name>\n\nHerregården har holdt øje med denne \"C\"-person, du har handlet med.\n\nC's sande identitet er Kajus Sortskov; en magtfuld magibruger, der arbejder for Syndikatet. Vores kilder siger, at han har samlet genstande til et ukendt formål. Først for nylig opdagede vi, at det var *dig*, der leverede dem.\n\nKajus må stoppes, og jeg mener, at ansvaret for det falder på dine skuldre. Heldigvis har jeg udtænkt en plan. Kom og tal med mig, når du er klar til at rense dit navn.", c="Fint, lad os komme til sagen."},
  [81570] = {n="Jarl Mangler en Klinge", l="Bring et Månestål-bredsværd til Jarl i Støvsumpen.", d="Jeg har noget at skære. Jeg kan ikke fortælle dig, hvad jeg skal skære, men... jeg har brug for en klinge til mig selv. En bestemt klinge...\n\nNogle kalder den et månestål-bredsværd. Jeg kalder den en svingklinge.\n\nHjælper du mig? Måske finder du den i byen, måske taler du med en smed, og han laver den specielt.\n\nMen vent ikke for længe. Det, jeg skal skære, varer ikke evigt...", p="Har du min klinge??", c="Det er en god klinge. Den har en god sving. Det er en god svingklinge. Tak. Tak, tak, tak!!! Nu vil jeg prøve den....\n\nSenere. Jeg prøver den senere. Men som jeg sagde... tak."},
  [81682] = {n="Den Gamle Mester", l="Find Kajsind et sted i Azsyra.", d="Denne arena ser måske ikke ud af meget, men jeg siger dig, dette sted plejede at være en stor attraktion. Præmiekæmpere, eventyrere, endda et par kartelfolk, de trådte alle op i ringen for en chance på mønter og ære.\n\nMellem spillet og boderne tjente jeg en formue!\n\nTingene begyndte at dø hen, efter den gamle mester, Kajsind, trak sig tilbage. Han var en virkelig seriøs type; forsvandt til Azsyra en dag uden et ord. Hvis du fandt ham, kunne vi få arenaen i gang igen.", c="<Et vemodigt udtryk krydser kort Kajsinds ansigt>\n\nJa, jeg er den såkaldte \"mester\", du leder efter."},
  [81697] = {n="Tandløs", l="Genvind Kajsinds klinge fra den blå drage, der strejfer sydøst for Forladt Højderyg i Azsyra.", d="Kamp er alt, hvad jeg kender, <Name>. Under den tredje krig faldt utallige for mit sværd. Da krigen var forbi, fandt jeg vej som præmiekæmper. Det var dengang, jeg kom til arenaen i Gadgetbyen.\n\nMine dage dér var herlige, men jeg blev snart træt af at være mester. Jeg kom til Azsyra på jagt efter en større udfordring; en blå drage, der strejfer sydøst herfra. Desværre fik skabningen overtaget over mig. Jeg slap levende fra det, men mit sværd blev taget til dens skat.\n\nHvis du genvinder mit sværd, vender jeg tilbage med dig til Gadgetbyen.", p="Jeg bebrejder ikke din tøven, <Race>. Dragen er en frygtindgydende fjende.", c="Det, jeg engang fejlede i, har du lykkedes med. Du har min dybeste respekt og taknemmelighed, <Name>. Måske slår du mig også i arenaen."},
  [81716] = {n="Hent Indfaldets Feltrapport: Skumringsskoven", l="Dræb dæmoner og returner feltrapporten til Markkaptajn Palandør.", d="Tak Elunie, at du er her, <Name>. Vi er blevet overrendt af dæmoner, der kommer gennem Den Smaragdgrønne Drøms Port. Jeg er blevet afskåret fra min spejder derinde. Find venligst Spejder Karla ved Drømmeporten og kom tilbage med hendes feltrapport. Og undervejs, dræb et par af de sværmende dæmoner. Når du er tilbage med rapporten, giver jeg dig en opfølgende mission, så du kan handle på efterretningerne.", p="Har du rapporten?", c="Tak, <Name>! Baseret på de efterretninger, du har genvundet, har jeg denne opfølgende mission til dig. Tak for al din hjælp!"},
  [81727] = {n="Hent Indfaldets Feltrapport: Askedalen", l="Dræb dæmoner og returner feltrapporten til Markkaptajn Hannala.", d="Tak Elunie, at du er her, <Name>. Vi er blevet overrendt af dæmoner, der kommer gennem Den Smaragdgrønne Drøms Port. Jeg er blevet afskåret fra min spejder derinde. Find venligst Spejder Gemerøn ved Drømmeporten og kom tilbage med hans feltrapport. Og undervejs, dræb et par af de sværmende dæmoner. Når du er tilbage med rapporten, giver jeg dig en opfølgende mission, så du kan handle på efterretningerne.", p="Har du rapporten?", c="Tak, <Name>! Baseret på de efterretninger, du har genvundet, har jeg denne opfølgende mission til dig. Tak for al din hjælp!"},
  [81728] = {n="Hent Indfaldets Feltrapport: Bagland", l="Dræb dæmoner og returner feltrapporten til Markkaptajn Korliam.", d="Tak Elunie, at du er her, <Name>. Vi er blevet overrendt af dæmoner, der kommer gennem Den Smaragdgrønne Drøms Port. Jeg er blevet afskåret fra min spejder derinde. Find venligst Spejder Fallie ved Drømmeporten og kom tilbage med hendes feltrapport. Og undervejs, dræb et par af de sværmende dæmoner. Når du er tilbage med rapporten, giver jeg dig en opfølgende mission, så du kan handle på efterretningerne.", p="Har du rapporten?", c="Tak, <Name>! Baseret på de efterretninger, du har genvundet, har jeg denne opfølgende mission til dig. Tak for al din hjælp!"},
  [81729] = {n="Hent Indfaldets Feltrapport: Vildalas", l="Dræb dæmoner og returner feltrapporten til Markkaptajn Arunnæl.", d="Tak Elunie, at du er her, <Name>. Vi er blevet overrendt af dæmoner, der kommer gennem Den Smaragdgrønne Drøms Port. Jeg er blevet afskåret fra min spejder derinde. Find venligst Spejder Tandros ved Drømmeporten og kom tilbage med hans feltrapport. Og undervejs, dræb et par af de sværmende dæmoner. Når du er tilbage med rapporten, giver jeg dig en opfølgende mission, så du kan handle på efterretningerne.", p="Har du rapporten?", c="Tak, <Name>! Baseret på de efterretninger, du har genvundet, har jeg denne opfølgende mission til dig. Tak for al din hjælp!"},
  [81730] = {n="Skumringsskoven Mission I: Besejr Varulve", l="Besejr 10 Mareløbere og 10 Mare-vævere i Skumringsskovens Mare-indfald i Rådnende Frugthave og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet i Rådnende Frugthave. Besejr varulve der og vend tilbage til mig.", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81731] = {n="Skumringsskoven Mission II: Besejr Oger", l="Besejr 3 Forvirrede Oger og 3 Demente Ildvævere i Skumringsskovens Mare-indfald ved Vul'gol Ogrehøjen og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet ved Vul'gol Ogrehøjen. Besejr oger der og vend tilbage til mig.", p="Har du klaret ogerne?", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81732] = {n="Skumringsskoven Mission III: Besejr Drageslægtning", l="Besejr 3 Ormeslægtning Terrorvandrere og 10 Natskræk-hvalpe i Skumringsskovens Mare-indfald ved Yorgen Gård og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet ved Yorgen Gård. Besejr drageslægtninge der og vend tilbage til mig.", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81733] = {n="Skumringsskoven Mission IV: Oger-efterretninger", l="Indhent efterretninger fra Drømmevagt Talinar i Skumringsskovens Mare-indfald dybt inde i Vul'gol Ogrehøjen og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet ved Vul'gol Ogrehøjen. Hent en efterretningsrapport fra Drømmevagt Talinar der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81734] = {n="Skumringsskoven Mission V: Varulve-efterretninger", l="Indhent efterretninger fra Drømmevagt Dorilær i Skumringsskovens Mare-indfald i laden ved Rådnende Frugthave og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet ved Rådnende Frugthave. Hent en efterretningsrapport fra Drømmevagt Dorilær der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81735] = {n="Skumringsskoven Mission VI: Drage-efterretninger", l="Indhent efterretninger fra Drømmevagt Amalie i Skumringsskovens Mare-indfald i farmhuset ved Yorgen Gård og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Hurtigt, rejs gennem Den Smaragdgrønne Drøms Portal i Tusmørkelunden, og rejs til Mare-indfaldet ved Yorgen Gård. Hent en efterretningsrapport fra Drømmevagt Amalie der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81736] = {n="Skumringsskoven-missionen VII: Genvind Skyggeliet", l="Genvind Skyggeliet i Skumringsskovens Mareindfald, ovenpå i farmhuset ved Rådnende Frugthave, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Rådnende Frugthave. Hent et kraftfuldt artefakt kendt som Skyggeliet, og lever det til mig.", p="Har du Skyggeliet?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81737] = {n="Skumringsskoven-missionen VIII: Genvind Ogermagiens tekst", l="Genvind en Ogermagiens tekst i Skumringsskovens Mareindfald inde i Vul'gol Ogrehøjen, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Vul'gol Ogrehøjen. Hent en Ogermagiens tekst, og lever den til mig.", p="Har du teksten?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81738] = {n="Skumringsskoven-missionen IX: Genvind drageæg", l="Genvind et Uudklækket Grønt Drageæg i Skumringsskovens Mareindfald fra Yorgens Gård nær den store stub i markerne, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet ved Yorgens Gård. Hent et Uudklækket Grønt Drageæg, og lever det til mig.", p="Har du ægget?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81739] = {n="Skumringsskoven-missionen X: Mare-mos", l="Saml 10 Mare-mos i Skumringsskovens Mareindfald, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og indsaml Mare-mos fra Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for en urtekyndig til at hjælpe dig.", p="Har du Mare-mosset?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81740] = {n="Skumringsskoven-missionen XI: Kold Jernmalm", l="Saml 10 Kold Jernmalm i Skumringsskovens Mareindfald, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og indsaml Kold Jernmalm fra Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for en minearbejder til at hjælpe dig.", p="Har du den Kolde Jernmalm?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81741] = {n="Skumringsskoven-missionen XII: Drømmeberørt skæl", l="Saml 10 Drømmeberørte Skæl i Skumringsskovens Mareindfald, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og indsaml Drømmeberørte Skæl fra drageslægtninge i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for en flåer til at hjælpe dig.", p="Har du skællene?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81742] = {n="Skumringsskoven-missionen XIII: Besejr Ylanthrøs", l="Besejr Ylanthrøs i Skumringsskovens Mareindfald på marken ved Yorgens Gård, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet ved Yorgens Gård. Besejr dragen Ylanthrøs der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81743] = {n="Skumringsskoven-missionen XIV: Besejr Vvarc'sul", l="Besejr Vvarc'sul i Skumringsskovens Mareindfald dybt inde i Vul'gol Ogrehøjen, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Vul'gol Ogrehøjen. Besejr ogerkrigsherren Vvarc'sul der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81744] = {n="Skumringsskoven-missionen XV: Besejr Amoksnarok", l="Besejr Amoksnarok i Skumringsskovens Mareindfald ved en lejrplads nær laden i Rådnende Frugthave, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Rådnende Frugthave. Besejr varulvelederen Amoksnarok der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81745] = {n="Skumringsskoven-missionen XVI: Red Kroll Bjergskygge", l="Red Kroll Bjergskygge fra Skumringsskovens Mareindfald i gæstehuset i Rådnende Frugthave, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Rådnende Frugthave. Find den sovende Klo-druide Kroll Bjergskygge der, og led ham i sikkerhed. Vend derefter tilbage til mig.", p="Har du reddet Kroll?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81746] = {n="Skumringsskoven-missionen XVII: Red Alara Lundlapper", l="Red Alara Lundlapper i Skumringsskovens Mareindfald i stalden ved Yorgens Gård, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet ved Yorgens Gård. Find den sovende Klo-druide Alara Lundlapper der, og led hende i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81747] = {n="Skumringsskoven-missionen XVIII: Red Elenora Sumpvandrer", l="Red Elenora Sumpvandrer i Skumringsskovens Mareindfald i ruinerne af et farmhus nær Vul'gol Ogrehøjen, og vend tilbage til Markkaptajn Palandør.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Tusmørkelunden, og drag til Mareindfaldet i Vul'gol Ogrehøjen. Find den sovende Klo-druide Elenora Sumpvandrer der, og led hende i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81762] = {n="Gode nyheder", l="Tal med Katrine den Rene i Lysets Katedral i Stormvind.", d="Hilsner, <Name>. Jeg har gode nyheder. Jeg har fået kontakt til min ven, og jeg rejser snart for at mødes med ham. Hvad mere er, er endnu en kugle dukket op i Kalimdør. Jeg kan ikke være to steder på én gang, så hvis du er villig, vil jeg gerne have, at du tager min plads og følger op på denne nye kugle. Tal med Katrine for yderligere instruktioner.", c="Godt at se dig igen, <Name>. Lad os få dig opdateret."},
  [81764] = {n="Den Mystiske Købmand", l="Rejs til Theramøre og find den mystiske købmand.", d="Velkommen igen, <Name>. Skaw og hans spioner har givet os oplysninger om en mystisk købmand, som lige er ankommet til Kalimdør og vil af med en samling farlige artefakter. Vi er kommet til at tro, at han har en Ekkende Kugle i sin samling. Han bor på Theramøre Kro i Støvsumpen. Rejs hurtigt, hent kuglen, og tal med ingen om dette. Vi sender dig alene ind for ikke at tiltrække vores fjenders opmærksomhed.\n\nVær forsigtig, og gå med lyset.", c="Ah, du er kommet! Katrine sendte mig for at assistere dig i din mission. Vi må dog skynde os, for vores bytte er sluppet væk!"},
  [81765] = {n="Elrik, Paladin af Sølvhånden", l="Tal med Elrik for at lære mere.", d="Paladinen, der står foran dig, er dig ukendt. Tal med ham for at finde ud af, hvad han ved om købmanden og den nuværende situation.", c="Tak lyset for dig, <Class>! Jeg var så bange. Jeg troede, de slyngler ville dræbe os!"},
  [81766] = {n="Det Blodige Missiv", l="Bring missivet til Katrine den Rene i Lysets Katedral i Stormvind.", d="Du finder et missiv på \"paladinens\" lig. Det er dækket af blod og svært at læse, men du kan tyde beskeden på pergamentet. Du bør studere det og derefter vende tilbage til Katrine for yderligere instruktioner.", p="Så det var en fælde... det her er meget bekymrende.", c="Det er en velsignelse, at du er i sikkerhed, <Name>. Jeg håber, at uanset hvor Æonas er taget hen, er han ikke havnet i lignende fare. Han er snarrådig, så jeg må stole på, at han klarer sig. Hvis jeg hører noget fra ham, kontakter jeg dig med det samme. Tak, <Name>.\n\nÅh, og en sidste ting. Han betroede mig dette, så jeg kunne give det videre til dig, når du vendte tilbage. Brug det godt, og gå med lyset."},
  [81768] = {n="Askedalen-missionen I: Besejr satyrerne", l="Besejr 10 Drømmeild-forrædere og 10 Drømmeild-helkaldere i Askedalen-mareindfaldet i Satyrdalen, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Satyrdalen. Besejr satyrerne der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81769] = {n="Askedalen-missionen II: Besejr trætrolde", l="Besejr 7 Hævngerrige Oldtidsfolk i Askedalen-mareindfaldet ved Krigssang-tømmerlejren, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet ved Krigssang-tømmerlejren. Besejr trætrolde der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81770] = {n="Askedalen-missionen III: Besejr drageslægtninge", l="Besejr 3 Ormefolk-natjægere og 10 Rædselsunger i Askedalen-mareindfaldet i Skovsang, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Skovsang. Besejr drageslægtninge der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81771] = {n="Askedalen-missionen IV: Drageintelligens", l="Indhent efterretninger fra Drømmevagt Ellodør i Askedalen-mareindfaldet i Skovsang på broen til det gamle tårn, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Skovsang. Hent en efterretningsrapport fra Drømmevagt Ellodør der, og vend tilbage til mig.", p="Har du rapporten?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81772] = {n="Askedalen-missionen V: Satyr-efterretninger", l="Indhent efterretninger fra Drømmevagt Mandorøn i Askedalen-mareindfaldet ved ritualcirklen i Satyrdalen, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Satyrdalen. Hent en efterretningsrapport fra Drømmevagt Mandorøn der, og vend tilbage til mig.", p="Har du rapporten?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81773] = {n="Askedalen-missionen VI: Trætrold-efterretninger", l="Indhent efterretninger fra Drømmevagt Lanarie i Askedalen-mareindfaldet inde i Kargathia Fæstning ved Krigssang-tømmerlejren, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet ved Krigssang-tømmerlejren. Hent en efterretningsrapport fra Drømmevagt Lanarie der, og vend tilbage til mig.", p="Har du rapporten?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81774] = {n="Askedalen-missionen VII: Genvind drømmemaskinen", l="Genvind Drømmemaskinen i Askedalen-mareindfaldet fra smedjen i Krigssang-tømmerlejren, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet ved Krigssang-tømmerlejren. Hent et kraftfuldt artefakt kendt som Drømmemaskinen, og lever det til mig.", p="Har du Drømmemaskinen?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81775] = {n="Askedalen-missionen VIII: Genvind Azsharan-profetien", l="Genvind Azsharan-profetien i Askedalen-mareindfaldet fra det lille telt i Satyrdalen, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Satyrdalen. Hent en tabt rulle kendt som Azsharan-profetien, og lever den til mig.", p="Har du Azsharan-profetien?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81776] = {n="Askedalen-missionen IX: Genvind drømmeberørt drageæg", l="Genvind et Drømmeberørt drageæg i Askedalen-mareindfaldet fra den centrale ruin i Skovsang, og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm fordærvet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og drag til Mareindfaldet i Skovsang. Hent et Drømmeberørt drageæg, og lever det til mig.", p="Har du ægget?", c="Godt gjort! Dine tjenester skal blive rigeligt belønnet. Måske en ny mission?"},
  [81777] = {n="Askedalen-missionen X: Drømmerod", l="Indsaml 10 Drømmerod i Askedalens Mareindfald og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen og saml Drømmerod fra inde i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for hjælp fra en urtekyndig.", p="Har du Drømmeroden?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81778] = {n="Askedalen-missionen XI: Tåbens Guldstøv", l="Indsaml 10 Tåbens Guldstøv i Askedalens Mareindfald og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen og saml Tåbens Guldstøv fra inde i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for hjælp fra en minearbejder.", p="Har du Tåbens Guldstøv?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81779] = {n="Askedalen-missionen XII: Drømmeinfunderet Drageskæl", l="Indsaml 10 Drømmeinfunderet Drageskæl i Askedalens Mareindfald og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen og saml Drømmeinfunderet Drageskæl fra drageslægtninge inde i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for hjælp fra en skinner.", p="Har du Drømmeinfunderet Drageskæl?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81780] = {n="Askedalen-missionen XIII: Besejr Larsera", l="Besejr Larsera i Askedalens Mareindfald uden for den centrale ruin i Skovsang og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Skovsang. Besejr dragen Larsera der og vend tilbage til mig.", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81781] = {n="Askedalen-missionen XIV: Besejr Zalius", l="Besejr Zalius i Askedalens Mareindfald ved foden af zigguraten i Satyrdalen og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Skovsang. Besejr satyren Zalius der og vend tilbage til mig.", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81782] = {n="Askedalen-missionen XV: Besejr Makulator 9000", l="Besejr Makulator 9000 i Askedalens Mareindfald nær tømmerkranerne i Krigssang-tømmerlejren og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Krigssang-tømmerlejren. Besejr Makulator 9000 der og vend tilbage til mig.", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81783] = {n="Askedalen-missionen XVI: Redd Alyssian Vindkalder", l="Redd Alyssian Vindkalder fra Askedalens Mareindfald ved foden af udkigstårnet i Krigssang-tømmerlejren og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Krigssang-tømmerlejren. Find den sovende Klo-druide Alyssian Vindkalder der og geleid hende i sikkerhed. Vend derefter tilbage til mig.", p="Har du reddet Alyssian?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81784] = {n="Askedalen-missionen XVII: Redd Doran Drømmegren", l="Redd Doran Drømmegren fra Askedalens Mareindfald ved det måneoplyste lysthus i Skovsang og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Skovsang. Find den sovende Klo-druide Doran Drømmegren der og geleid ham i sikkerhed. Vend derefter tilbage til mig.", p="Har du reddet Doran?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81785] = {n="Askedalen-missionen XVIII: Redd Maseara Efterårsmåne", l="Redd Maseara Efterårsmåne fra Askedalens Mareindfald ved teltklyngen i sydøst i Satyrdalen og vend tilbage til Markkaptajn Hannala.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Skyggegrenen, og rejs til Mareindfaldet i Satyrdalen. Find den sovende Klo-druide Maseara Efterårsmåne der og geleid hende i sikkerhed. Vend derefter tilbage til mig.", p="Har du reddet Maseara?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81786] = {n="Bagland-missionen I: Besejr Månekin", l="Besejr 20 Faldne Månekin i Baglands Mareindfald ved Snigeklippe og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Snigeklippe. Besejr månekin der og vend tilbage til mig.", p="Har du klaret månekinene?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81787] = {n="Bagland-missionen II: Besejr Kæmpeskildpadder", l="Besejr 20 Drømmevands-visekæber i Baglands Mareindfald ved Shaol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Shaol'vatha. Besejr kæmpeskildpadder der og vend tilbage til mig.", p="Har du klaret skildpadderne?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81788] = {n="Bagland-missionen III: Besejr Drageslægtninge", l="Besejr 10 Vredesunger og 3 Ormefolk-stjernejægere i Baglands Mareindfald ved Agol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Agol'vatha. Besejr drageslægtninge der og vend tilbage til mig.", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81789] = {n="Bagland-missionen IV: Drageintelligens", l="Indhent efterretninger fra Drømmevagt Laninar i Baglands Mareindfald ved buegangen i Agol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Agol'vath. Hent en efterretningsrapport fra Drømmevagt Laninar der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81790] = {n="Betydningsfulde materialer", l="Find materialerne nævnt i Gregors Seddel og bring dem tilbage til Gregor ved kilden til Blodgift-faldene i Ondskoven.", d="Hver af de Ekkoende Kugler er indstillet på en anden skikkelse af sin herre, og metoden du brugte i Askedalen til at ødelægge Althalaxx-kuglen vil ikke virke på den kugle, vi har. Jeg kender et ritual, der muligvis kan gøre kuglen ustabil, så vi kan ødelægge den, men det kræver komponenter med særlig magisk betydning. Vi har allerede nogle af de nødvendige materialer, men du bliver nødt til at hente resten. Tag den her, den burde hjælpe dig på din søgen.", p="Det må have været et ordentligt eventyr at skaffe disse ting. Godt gået.", c="Nu hvor vi har materialerne, må jeg forberede ritualet. Indtil videre skal du tale med Æonas. Han vil gerne tale med dig."},
  [81801] = {n="Tilbage til arenaen", l="Vend tilbage til Fizbuz Mithril i Gadgetbyen, Tanaris.", d="Jeg er en ork af ord. Du har hævnet mig, og jeg vil gengælde din tjeneste. Tag til Gadgetbyen og fortæl Fizbuz, at han har sin mester tilbage.\n\nJeg håber at se dig i ringen.", c="Fantastisk! Alle bliver helt vilde, når de hører, at den gamle Kajsind er tilbage i byen.\n\nOg sagde du, at du dræbte en drage for fyren!? Det lyder som om, du selv bliver en stor attraktion.\n\nJeg kan mærke det nu, <Name>. Vi er ved at få det mest episke slagsmål nogensinde herinde!"},
  [81817] = {n="Bagland-missionen V: Skildpaddeefterretninger", l="Indhent efterretninger fra Drømmevagt Sanathel i Baglands Mareindfald bag trommen i Agol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Shaol'vath. Hent en efterretningsrapport fra Drømmevagt Sanathel der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81820] = {n="Bagland-missionen VI: Månekin-efterretninger", l="Indhent efterretninger fra Drømmevagt Valori i Baglands Mareindfald ved den underjordiske sø i Snigeklippe og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Snigeklippe. Hent en efterretningsrapport fra Drømmevagt Valori der og vend tilbage til mig.", p="Har du rapporten?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81826] = {n="Bagland-missionen VII: Genvind stjerneberørt drageæg", l="Genvind et stjerneberørt drageæg fra Baglands Mareindfald fra den centrale hytte i Agol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Agol'vatha. Hent et stjerneberørt drageæg og bring det til mig.", p="Har du ægget?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81830] = {n="Bagland-missionen VIII: Genvind Elunsk relikvie", l="Genvind en Elunsk relikvie fra Baglands Mareindfald fra den høje hylde inde i Snigeklippe og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Snigeklippe. Hent en Elunsk relikvie, som månekinene har gemt dér, og bring den til mig.", p="Har du relikvien?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81832] = {n="Bagland-missionen IX: Genvind Drømmeperle", l="Genvind en Drømmeperle i Baglands Mareindfald fra en slangefontæne i Shaol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet i Shaol'vatha. Hent en Drømmeperle, som skildpadderne har gemt dér, og bring den til mig.", p="Har du perlen?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81833] = {n="Bagland-missionen X: Stjerne-lotus", l="Indsaml 10 Stjerne-lotus i Baglands Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal og saml Stjerne-lotus fra inde i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for hjælp fra en urtekyndig.", p="Har du Stjerne-lotussen?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81834] = {n="Bagland-missionen XI: Stjernesølv-malm", l="Indsaml 10 Stjernesølv-malm i Baglands Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal og saml Stjernesølv-malm fra inde i Mareindfaldene. Vi kan udnytte dens magi til at vende skaden. Du får brug for hjælp fra en minearbejder.", p="Har du Stjernesølv-malmen?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81835] = {n="Bagland-missionen XII: Stjerneskaller", l="Indsaml 10 Stjerneskaller i Baglands Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal og saml Stjerneskaller fra de kæmpeskildpadder, der findes inde i Mareindfaldene. Vi kan udnytte deres magi til at vende skaden. Du får brug for hjælp fra en skinner.", p="Har du Stjerneskallerne?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81837] = {n="Bagland-missionen XIII: Besejr Florius", l="Besejr Florius i Baglands Mareindfald på hovedgården i Agol'vatha og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet i Agol'vatha. Besejr dragen Florius der og vend tilbage til mig.", p="Har du klaret Florius?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81838] = {n="Bagland-missionen XIV: Besejr Domslægt", l="Besejr Domslægten i Baglands Mareindfald på den dybe hylde inde i Snigeklippe og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mare. Hurtigt, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og rejs til Mareindfaldet ved Snigeklippe. Besejr den kæmpestore månekin ved navn Domslægten dér og vend tilbage til mig.", p="Har du klaret Domslægten?", c="Godt gået! Dine tjenester skal blive godt belønnet. Måske en mission mere?"},
  [81839] = {n="Bagland-missionen XV: Besejr Ghamoo-Radjah", l="Besejr Ghamoo-Radjah i Baglands Mareindfald på borggården i Shaol'vatha, og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og begiv dig til Mareindfaldet i Shaol'vatha. Besejr den skildpadde-\"konge\" ved navn Ghamoo-Radjah der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81850] = {n="Bagland-missionen XVI: Red Elianar Skyggedrikker", l="Red Elianar Skyggedrikker fra Baglands Mareindfald ved trollefæstningen nær Agol'vatha, og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og begiv dig til Mareindfaldet i Agol'vatha. Find den sovende Klo-druide Elianar Skyggedrikker der, og eskorter ham i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81851] = {n="Bagland-missionen XVII: Red Serlina Stjernelys", l="Red Serlina Stjernelys fra Baglands Mareindfald ved trollefæstningen nærmest Shol'vatha, og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og begiv dig til Mareindfaldet i Shol'vatha. Find den sovende Klo-druide Serlina Stjernelys der, og eskorter hende i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81852] = {n="Bagland-missionen XVIII: Red Veanna Skysøvn", l="Red Veanna Skysøvn fra Baglands Mareindfald i hængekøjen over Snigeklippe, og vend tilbage til Markkaptajn Korliam.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Seradanedal, og begiv dig til Mareindfaldet ved Snigeklippe. Find den sovende Klo-druide Veanna Skysøvn der, og eskorter hende i sikkerhed. Vend derefter tilbage til mig.", p="Reddede du Veanna?", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81855] = {n="Vildalas-missionen I: Besejr Cenarus' Børn", l="Besejr 10 Tabte Døtre og 10 Hævngerrige Sønner i Vildalas' Mareindfald ved Tvillingekolosserne, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet ved Tvillingekolosserne. Besejr de gale sønner og døtre af Cenarus, der findes der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81856] = {n="Vildalas-missionen II: Besejr Harpyjer", l="Besejr 10 Drømmekilde-Skurkefjer og 10 Drømmekilde-Stormkaldere i Vildalas' Mareindfald ved Ruinerne af Ravnevinden, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet ved Ruinerne af Ravnevinden. Besejr harpyjerne der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81857] = {n="Vildalas-missionen III: Besejr Drageslægtninge", l="Besejr 10 Rasende Unger og 3 Ormefolk-berserkere i Vildalas' Mareindfald ved Drømmeros, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet i Drømmeros. Besejr drageslægtningene der, og vend tilbage til mig.", p="Har du klaret drageslægtningene?", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81858] = {n="Vildalas-missionen IV: Drageintelligens", l="Indsaml Intelligens fra Drømmevagt Skjoldryn i Vildalas' Mareindfald ved de sydligste ruiner i Drømmeros, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet i Drømmeros. Hent en efterretningsrapport fra Drømmevagt Skjoldryn der, og vend tilbage til mig.", p="Har du rapporten?", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
