  [81871] = {n="Vildalas-missionen XV: Besejr Slirena", l="Besejr Slirena i Vildalas' Mareindfald nær ziggurat'en i Ruinerne af Ravnevinden, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet ved Ruinerne af Ravnevinden. Besejr harpyje-\"dronningen\" Slirena der, og vend tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81872] = {n="Vildalas-missionen XVI: Red Mellias Jordplejer", l="Red Mellias Jordplejer fra Vildalas' Mareindfald ved trappen ved Jademir-søen i Drømmeros, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet i Drømmeros. Find den sovende Klo-druide Mellias Jordplejer der, og eskorter ham i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81873] = {n="Vildalas-missionen XVII: Red Nerene Bæksang", l="Red Nerene Bæksang fra Vildalas' Mareindfald ved lejrbålet ved Tvillingekolosserne, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet ved Tvillingekolosserne. Find den sovende Klo-druide Nerene Bæksang der, og eskorter hende i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81874] = {n="Vildalas-missionen XVIII: Red Jamniss Træplejer", l="Red Jamnice Træplejer fra Vildalas' Mareindfald ved den nordlige kant af Ruinerne af Ravnevinden, og vend tilbage til Markkaptajn Arunnæl.", d="Mens disse dæmoner distraherer os her, bliver Den Smaragdgrønne Drøm forvandlet til mareridt. Skynd dig, rejs gennem Den Smaragdgrønne Drømmeportal i Drømmegrenen, og begiv dig til Mareindfaldet ved Ruinerne af Ravnevinden. Find den sovende Klo-druide Jamnice Træplejer der, og eskorter hende i sikkerhed. Vend derefter tilbage til mig.", c="Godt gjort! Dine tjenester vil blive godt belønnet. Måske en ny mission?"},
  [81877] = {n="Kampnat", l="Vind sejren i Gadgetbyens Arena.", d="Alt er klar til den store genåbning af Gadgetbyens Arena!\n\nReglerne er enkle: Du skal kæmpe tre gange, og til sidst møder du mesteren. Du får en kort pause mellem kampene, men du må under ingen omstændigheder forlade arenaen. Gør du det, opgiver du.\n\nNår du er klar, så er kampen i gang!", p="Hvordan klarer du dig, <Name>? Sig nu ikke, du har fået nok!", c="Du gav virkelig en forestilling derude. Jeg sad på kanten af stolen, sig'r jeg dig! Overskuddet var heller ikke for ringe.\n\nSom mester får du en andel af mønterne, plus en lille ekstra belønning, fordi du gjorde alt dette muligt. Sejrherren får byttet, som man siger."},
  [81885] = {n="Ritualet", l="Tal med Gregor for at begynde ritualet.", d="Jeg ville takke dig for din indsats, <Name>. Uden dig var jeg nok død nu, og Legionens tjenere ville stadig have besiddelse af denne farlige artefakt. Jeg ved, at det er svært at stole på en agent fra Liskekongen, men mit håb er, at vi, når det her er overstået, kan lokke min ven tilbage til lyset. Det er tydeligt, at manden, jeg holdt af, stadig er derinde. Han har måske kun brug for et lille skub.\n\nKom nu, Gregor har brug for vores hjælp til at fuldføre ritualet. Lad os tale igen, når det er gjort.", p="<Æonas stirrer tomt ud over klippekanten i tydelig chok over det, der lige er sket>", c="Jeg har ingen ord, <Name>. At se Gregor igen fyldte mig med et farligt slags håb. Hans natur blev afsløret i samme øjeblik, vi genforenedes, og der var masser af tegn, der pegede mod denne ende. Jeg var blind for dem.\n\nVær så venlig, tag denne forbandede kugle og lad mig være. Jeg har meget at overveje."},
  [81900] = {n="Det Brændende Udyr", l="Find en ekspert i bæsterne fra Det Sønderrevne Land.", d="Skulpturen foran dig forestiller et tohovedet udyr, der stiger op fra Den Mørke Portal. Ond ild sprøjter ud af dets munde. En plade under billedet lyder: \"Opvarmeren den Løsluppne\".\n\nIntuitionen fortæller dig, at Tusmørke-kultisterne måske har planer om at udnytte dette væsens ødelæggende kraft til deres egne formål.\n\nDu regner ud, at næste skridt i din jagt må gå mod Det Sønderrevne Land. Nogen dér kan vide mere om dette helvedesudyr.", c="Fortæl mig mere om dette udyr, <Race>. Vores interesser kan måske være på linje."},
  [81917] = {n="Lænker, der binder", l="Bring 5 infernalske kæde-led til Blodmager Lynnøre i Det Sønderrevne Land", d="Jeg har set det væsen, I kalder \"Opvarmeren\", mange gange under mine feltstudier. Efter alt at dømme ser det ud til at være en næsten usårlig kernehund skabt af fel-energier.\n\nHvis det, I siger, er sandt, og Tusmørkets Hammer planlægger at gøre den til slave, så findes der måske en måde at tæmme udyret på.\n\nSkyggesvoren mod sydøst er kendt for at udføre mørke ritualer, herunder at gøre fel-skabninger til slaver. Måske bærer medlemmer af deres orden på et fingerpeg om, hvordan man svækker Opvarmeren?", p="Har du fundet et redskab til at svække Opvarmeren, <Race>?", c="Interessant... ja, det kan jeg arbejde med."},
  [81919] = {n="Tøjlet", l="Bring det fel-livsblod fra Opvarmeren den Løsslupne til Blodmager Lynnøre i Det Sønderrevne Land", d="Jeg har smedet et redskab af de kæde-led, du fandt. Dem af din slags kalder det måske en slags \"lasso\".\n\nEnergien i kæden egner sig bedst til at binde dæmoner, men eftersom Opvarmeren måske stammer fra den anden side af det mørke portal, tror jeg, at den også vil virke på ham.\n\nHvis du får ham nedlagt, så bring mig en prøve af hans fel-livsblod. Et så anomalt væsen fortjener yderligere studier.\n\nOpvarmerens nuværende opholdssted blandt disse ødemarker er ukendt, men jeg stoler på, at du sporer ham op, <Class>.", p="Find kernehunden hurtigt, <Name>. Før Tusmørkets Hammer finder ham først.", c="Sikke en udsøgt prøve! Hvem ved, hvilke mysterier der gemmer sig i essensen af et udyr fra den anden side af portalen?\n\nSom tak må du beholde lassoet. Jeg tvivler på, at jeg nogensinde får brug for sådan noget alligevel."},
  [81924] = {n="Visdommen fra Vogterne", l="Bevis dig over for vogterånderne i Vildalas, Azsyra og Bagland, og vend derefter tilbage til Tyrisius den Vise i Vildalas.", d="Uanset hvilken kaldorisk viden du søger, vil du ikke finde den blandt disse ruiner, <Class>. Ikke længere.\n\nMen mens det fysiske ligger i ruiner, består det åndelige.\n\nSøg vogterånderne i Azsyra, Bagland og Vildalas. Du vil kende dem på deres helligdomme. Bevis dig over for dem, og lyt til deres ord. Deres visdom vil blive videregivet til dig, så den ikke går tabt for tiden, som så meget andet her gjorde.", p="Har åndene givet dig deres visdom?", c="Du har vist dig som en hengiven elev, <Name>. Arbejdet med at bevare gammel viden er ofte besværligt, men du har påtaget dig opgaven flot.\n\nDer er mange flere mysterier i denne verden, som du kan afdække. Jeg håber, at disse redskaber vil hjælpe dig på rejsen."},
  [81944] = {n="Et nyopdaget formål...", l="Jeg... kan ikke forklare dette, <Race>, men jeg tror, jeg har noget, du har brug for. Jeg kom til dette land for at søge viden, og den søgen førte mig op ad bjerget derovre til en kæmpe lyssten, faldet fra himlen. Under min eftertanke ved stenen gav Ånd'she mig en lang række gaver. En af dem var en fornemmelse af nyt formål. En anden var et syn af dig og mig, her, i denne samtale. Jeg tror, at jeg gav dig dette.\n\nVær venlig at tage denne totem. Brug den godt i Ånd'shes tjeneste... i lysets tjeneste."},
  [81951] = {n="Tærsklen og det Arkane", l="Har du bragt noget med til at tilføje til vores samling?", p="Har du bragt noget med til at tilføje til vores samling?", c="Tak, <Name>. Vores viden udvides takket være din indsats.\n\nHvis du opdager flere magiske værker, der kan gavne biblioteket, så bring dem til mig."},
  [81960] = {n="Klarende luft", l="Find den plettede Åndesten og drik den Mørke Luftsapta.", d="De ulæselige noter er viklet om nogle sapta. Den er mørkere, end du husker, men den ser ud til at være smeltet sammen med den samme magi. Du føler dig urolig, når du kigger på den, som om den er blevet forurenet af en uretmæssig indflydelse. Der må være en Åndesten i nærheden, selvom du ikke kender til noget helligt sted her i nærheden. Måske kan du komme til bunds i denne mærkelighed ved at finde den.", c="Du giver liv tilbage. Du stærk nok. Forstå... ja... du stopper fordærvelsen.\n\n\nSøg og stop fordærvelsen."},
  [81967] = {n="Skat fra den anden verden", l="Værsgo, chef!"},
  [81968] = {n="Svar på Luftens Kald", l="Saml 3 elementar-essens fra vandelementarerne på Den Glemte Kyst over for Sardor Ø i Vildalas, og kombiner dem med Luftfragmentet for at tilkalde hjælp ved den fordærvede helligdom dér.", d="Du stærk nok. Forstå... ja... du stopper fordærvelsen.\n\n<Elementaret flytter sig utilpas.>\n\nElementarer i Vildalas. Brug Essens til at finde Helligdom.\n\nTag fragment. Vil hjælpe mod fordærvelsen.", p="Du fandt helligdom. Klarg helligdom.", c="Fordærvelse... klarg nu. Hjælp nødvendig. Måske andre... ja... andre elementarer hjælper."},
  [81974] = {n="Mere skrot til Ziri", l="Tal med Ziri \"Skruenøglen\" Lillehjul i Nisseborgen.", d="Du har fundet endnu en G-7 K.E.R.N.-processor. Denne enhed ser ud til at være i værre stand end den sidste, og den sipper en meget ætsende, blæksort væske. Den er nok skrot nu, men Ziri kan måske have en brug for den.", p="Hvad er det, du har dér, <Name>?", c="Åh gud! En G-7 K.E.R.N.-processor! Jeg tror ikke, jeg nogensinde rigtig har set en i virkeligheden før. Du bør nok bare smide den væk. Jeg har hørt, at de er virkelig farlige."},
  [81975] = {n="En bekymrende byttehandel", l="Tal med Ziri.", d="Vent, hvad? Har du slået hovedet? Hvorfor skulle jeg bede dig om at bringe en af disse ting for at reparere den spand skruer? Alt, hvad Bjærgomaten behøvede, var nogle patronsikringer, nogle mithrilstivere og lidt fortryllelsesessens. Hvis jeg skulle putte en G-7-enhed med fuld styrke i den ting... ja, jeg ved ikke, hvad der ville ske. Intet godt, det er sikkert. Eksplosioner, ild, interdimensionale monstre. Et rigtigt rædselsshow, mest sandsynligt.", c="Tænk, at du troede, jeg ville putte en G-7-enhed i en Bjærgomat! Jeg har ikke lyst til at dø, makker.\n\n<Ziri fniser for sig selv og vender tilbage til sit arbejde>"},
  [81977] = {n="IOÆ", l="Leveret genstand:", d="Du finder en lille, glat lilla sten. Den har mange uregelmæssige facetter, hvoraf den største ser ud til at huse en skyet mineraldannelse, som du bemærker ser ud til at glimte og hvirvle en smule i lyset. Når du koncentrerer dig hårdere om den bevægelse, mærker du dog en stigende fornemmelse af uro.\n\nDu er ved at smide den væk, da du får en pludselig fornemmelse, næsten en trang til at beholde den hos dig for nu.Du vil modtage:"},
  [81979] = {n="IOÆ", l="Mød den Skyggefulde Figur i Seradanedal i Bagland", d="En stor del af denne verden er i overhængende fare for undergang. Jeg ved, det lyder meget dramatisk, men at stoppe det burde virkelig ikke være noget problem for en så ressourcestærk person som dig. Mød mig på den fjerne side af broen ind til Seradanedal, i den nordlige del af Bagland. Vi taler mere om det dér.Du vil modtage:"},
  [81980] = {n="IOÆ", l="Find, hvor Mareamalgamationen holder til i Smaragdmaren.", d="Bag mig finder du et ret stort portal, der fører ind i Den Smaragdgrønne Drøm. Desværre er det mere en \"mare\" på den anden side lige nu, og det er uden for min rækkevidde for øjeblikket. Som om det ikke var nok, at marerne manifesterer sig, er der noget derinde, en mareamalgamation lavet af rædselsfulde drømme og profetiske syner om undergang.\n\nSå naturligvis skal du gå derind og finde dens hule for mig. Vurder dette væsen, så vi kan beslutte, hvad vi gør næste gang.Du vil modtage:"},
  [81982] = {n="IOÆ", l="Tal med den Skyggefulde Figur for at lære mere, og find derefter Ziri \"Skruenøglen\" Lillehjul inde i Nisseborgen", d="Det mørke, du trådte ind i... der er det bestemt, den bor. Som du utvivlsomt har gættet, kan dit sind, for ikke at tale om dit kødfulde, dødelige kødkostume, ikke modstå den rædselsaura, der omgiver dette monster. Heldigvis betyder min overlegne forudseenhed og evne til at dyrke positive arbejdsrelationer med en bred vifte af talentfulde personer, at jeg har en løsning, der vil give dig mulighed for at komme tæt nok på udyret til at dræbe det.Du vil modtage:"},
  [81983] = {n="IOÆ", l="Ryst Ziris hukommelse", d="Vent, hvad? En skyggedame? Enhed drevet af tomrummet? Hvad i alverden taler du om?Du vil modtage:"},
  [81986] = {n="Vækker marerne", l="Ødelæg Mareamalgamationen og bring den Skyggefulde Figur al den plyndring, du finder.", d="Nu hvor du har Ziris gadget, bør du have alt, hvad du skal bruge for at tage fat på Mareamalgamationen. Saml så mange allierede, som du kan, og vend tilbage ind i marerne gennem portalen Skyggegrenen i Askedalen. Find og ødelæg Mareamalgamationen i dens hule.\n\nÅh, og en ting mere... udyret er i besiddelse af en bestemt genstand, som er af stor interesse for mig. Bring mig, hvad end du finder på dets lig, så bliver du rigeligt belønnet.", p="Hvordan går jagten?", c="Fantastisk arbejde, <Name>. Nu til din belønning!\n\nSe, alt, hvad jeg ville have, er et lille, lille fragment af en drøm, der gemmer sig i denne kappe, men skallen er en skat i sig selv, og den del er din. Jeg tror, du vil finde, at den har visse unikke egenskaber, og hvis du har de rette færdigheder til det, så tal med mig igen, og jeg er sikker på, at jeg kan hjælpe dig med at finde den helt rigtige måde at bruge den på."},
  [81987] = {n="Nisse-løsninger", l="Bring 5 Nisse-landminer til Maksimilian \"Fedtpanden\" i Glimtende Flad", d="Hey du, kom her, lad mig se på dig. Ja, det troede jeg nok, jeg kan genkende en tilhænger af goblinkunsten på en kilometers afstand. Sodpletter på knoerne, det har vi alle. Hør, jeg har brug for hjælp.\n\nJeg er blevet bedt om at rådgive mine medgoblinere, så de får en fordel herude. Men de her gnomer har også hentet en ekspert, og de begynder langsomt at trække fra. Jeg har nogle ideer, men i mellemtiden, lad os sige, at du bringer mig nogle Nisse-landminer! Du kan lave dem, ja?", p="Som mor altid sagde: \"Hvis du ikke kan vinde en fair kamp, så kæmp ikke en fair kamp.\" Så vi løser dette problem, som mine forfædre gjorde. Vi dækker stedet med yderst følsomme sprængladninger!", c="At tænke på, at disse blev brugt til forsvaret af Hyjal-bjerget mod den Brændende Legion. Det her føles som en lige så god anvendelse."},
  [82001] = {n="Kræver gnomiske problemer", l="Bring Hornet fra en Tordenstamp-stegodon til Maksimilian \"Fedtpanden\".", d="Okay, dårlige nyheder. Denne gnomiske konsulent, de har fået fat i, er et skridt foran mig. Det viser sig, at deres kører slet ikke engang vil være på jorden!\n\nDe lægger væddeløbsbanen med noget, der kaldes \"magneter\", og de vil glide lige over jorden, hvilket betyder ingen eksplosion! Hvis de ikke træder på minen, så tager vi bare minen til dem!\n\nJeg tror, at hvis vi har en elektrisk ladning stor nok, bør det løse vores problem. Tag til Sydvestlige Un'goro-krateret og bring mig et Tordenstamp-stegodon-horn!", p="Jeg vil ikke gå i detaljer om, hvordan magneter virker, for helt ærligt tror jeg ikke, at nogen ved det.", c="Ja, det her burde gøre det! Den perfekte naturlige leder, vi har brug for! Spåner fra denne vil fungere som en perfekt udløser for at få minerne til at gå af."},
  [82002] = {n="Hvad er rødt og lugter af maling?", l="Tag til Hjertedal og find en kasse med skarlagenrød farve.", d="Disse nye landminer virker som en charme, men vi kan ikke bare spille saboteur. Vi bliver nødt til at opgradere vores egne køretøjer, så de ikke kalder det for snyd.\n\nSå vi skal lave den mest oplagte opgradering, der findes, et lækkert malerjob. Og du behøver ikke engang at spørge, hvilken farve vi bruger! Hotrod-rød, baby! Den hurtigste farve, der findes!\n\nHvem ved, hvem der har den perfekte rødtone? De der Skarlagenrøde Korstog-jabronier. Hvorfor sniger du dig ikke ind i Hjertedal og finder mig noget af den pæne skarlagenrøde farve.", p="Det skal være den skarlagenrøde Korstog-rød. Ikke blodrød, ikke ildkuglerød, ikke dæmonisk ork-rød. Skarlagenrøde Korstog-rød eller intet, baby!", c="Nuancen, den smagfulde gradient af rød. Ikke engang et hint af lyserød eller orange. Bare ren rød godhed. Åh ja, jeg kan allerede mærke, at vi kører hurtigere, makker."},
  [82003] = {n="Sejrsrunde for Goblinerne!", l="Tal med Sprøjtbizz Kobberspole om at få udbetalt.", d="Ha! Jeg gjorde det! øh, mener jeg... vi gjorde det!\n\nDen amatørgnomiske konsulent derovre kaster håndklædet i ringen! Han betaler os for at forsvinde fra byen! Hvorfor gør du ikke æren? Du har fortjent det, unge.", c="Jeg har et forslag, som jeg tror vil være i begges interesse."},
  [82004] = {n="Tavshedspenge", l="Accepter bestikkelsen fra Sprøjtbizz Kobberspole", d="Jeg har ikke råd til det tab af ry eller det økonomiske tab, du og din goblinven forårsager. Så her er aftalen: Jeg giver dig insiderinformation om, hvordan gnomiske ingeniører får tingene gjort. Til gengæld skal du forsvinde! Jeg vil ikke se dig her mere!", c="Det er alt, du får lige nu! Kom tilbage om en uge, så har jeg mere til dig."},
  [82008] = {n="Gnomiske løsninger", l="Bring Sprøjtbizz Kobberspole 2 gnomiske skadesforebyggende bælter", d="Hilsner, min agtede kollega! Jeg kan se, at du er en intellektuel af højeste kaliber! Jeg har brug for en person med dine færdigheder. Først og fremmest! Eksplosioner ser ud til at ske langs hele væddeløbsbanen! Lidt mistænkeligt, vil du ikke sige? Vores køreres sikkerhed er vores højeste prioritet. Bring mig et par gnomiske skadesforebyggende bælter! Forhåbentlig vil dette løse vores kortsigtede problem.", p="Har du bæltene? Et væddeløb er ved at starte, og vi har brug for dem NU!", c="Meget godt! Forhåbentlig kommer vores kører over målstregen i ét stykke. Nu til de større problemer."},
  [82009] = {n="Kræver goblinproblemer", l="Bring Sprøjtbizz Kobberspole et Tordenstamp-stegodon-horn", d="Kan du høre eksplosionerne på væddeløbsbanen? Nej, seriøst, kan du? Det meste af min hørelse er væk. Under alle omstændigheder...\n\nMagneter! Ved omhyggeligt at placere magneter langs hele væddeløbsbanen og tilføje den omvendte polaritet til bunden af vores køretøj, vil vi simpelthen svæve over minerne! Tag det, goblinere!\n\nDen sidste brik i puslespillet er, at vi har brug for noget, der kan holde en elektrisk ladning for at styre det komplicerede elektriske panel.\n\nTag til Sydvestlige Un'goro-krateret og bring mig et Tordenstamp-stegodon-horn!", p="Tordenstamp-stegodon-hornet er den perfekte organiske forbindelse til at styre de elektriske felter, der skal til for at få disse magneter til at virke. Eller det håber jeg i hvert fald, for jeg er ikke helt sikker på, hvordan de virker.", c="Det her gør det fint! Det knitrer stadig af energi! Hvis jeg havde noget hår tilbage, ville det stå i alle retninger!"},
  [82010] = {n="Vanding af konkurrencen", l="Tag til Hjertedal og find en kasse med skarlagenrød farve.", d="Forsvarets tid er forbi! Vi vinder ikke, medmindre vi saboterer konkurrencen! Deres brændstof! Lad os se. Ildblomst og rom? ER DET HER, GNOMISK GENIALITET TABER TIL? TRUKKET ALKOHOL?\n\nVi må finde en måde at sabotere fjendens brændstof på, uden at de bemærker det. Der findes en blomst med utrolig rød farve, og forbindelserne i kronbladene er ustabile, når den mindste smule varme tilføres.\n\nDen Skarlagenrøde Korstog bruger denne blomst i deres farvestoffer. Tag til Hjertedal og find mig nogle.", p="Det Skarlagenrøde Korstog er de eneste, der kender blomstens opholdssted! Forbindelserne er stærke nok til, at de burde være tilstrækkeligt koncentreret i deres farver.", c="Du fandt den! Ja, bare det at smutte denne i fjendens benzintank burde skabe et ret stort spektakel! En eksplosion? Ikke værre! De vil kun køre med 76 % kapacitet! Og de opdager det ikke engang!"},
  [82011] = {n="Sejrsrunde for gnomerne!", l="Tal med Maksimilian \"Fedtpanden\"", d="Vi gjorde det, ven! Goblinerne kaster håndklædet i ringen. Faktisk vil konsulenten, som goblinerne har hyret, tale med dig personligt! Prøv ikke at prale for meget nu, vi vil ikke have, at de sprænger en sapper!", c="Jeg er stor nok til at vide, hvornår jeg er slået. Eller i hvert fald, hvornår det ikke længere er umagen værd at kæmpe."},
  [82013] = {n="Tavshedspenge", l="Accepter bestikkelsen fra Maksimilian \"Fedtpanden\"", d="Lad mig fortælle dig, hvordan det her skal gå. Jeg har ikke råd til, at du er her mere, så sådan gør vi. Du skal forsvinde lige nu. Men som gengæld for din meget rettidige udflugt herfra, må du komme tilbage én gang om ugen.\n\nNår du gør det, kan du måske kigge forbi her og se lidt noget-og-noget på jorden, som du måske har lyst til at samle op. Og jeg ville være så taknemmelig for denne tjeneste, at jeg ikke kunne lade være med at føle mig tilskyndet til at belønne dig på en eller anden måde.", c="Vi ses næste uge, tølpe."},
  [82016] = {n="Atal'aj-potente Drikkevarer", l="Jeg tilbyder en skarp handel til dig, mand! Bring mig trylleri, der kun findes hos de Atal'aj-folk, så laver jeg dig et tilbud: kraft ud over din vildeste fantasi. Vær advaret, mand, denne kraft kan kun bruges i de sumpe, den er fundet i. De siger, at Atal'aj praktiserer forbudt hekseri, og jeg ved måske lidt om dem.\n\nLyder godt? Vil du gøre en handel?", p="Jeg tilbyder en skarp handel til dig, mand! Bring mig trylleri, der kun findes hos de Atal'aj-folk, så laver jeg dig et tilbud: kraft ud over din vildeste fantasi. Vær advaret, mand, denne kraft kan kun bruges i de sumpe, den er fundet i. De siger, at Atal'aj praktiserer forbudt hekseri, og jeg ved måske lidt om dem.\n\nLyder godt? Vil du gøre en handel?", c="Ej, du vil ikke fortryde denne handel, mand!"},
  [82017] = {n="En Sammensmeltning af Mareridt", l="Søg Ugganaar i Månelunden", d="Den frygtaura, du oplevede, udgår ikke fra et sted, men fra en skabning. En særdeles dødbringende mørkeskabning, et forvrænget skyggespejlbillede af den værste side af vores verden, smeltet sammen til en blanding af rent mareridt. Jeg kan ikke forklare, hvordan jeg ved det, men jeg... drømte om det. Eller rettere, det blev vist for mig. Det er svært at forklare. Vær venlig, gå til Månelunden og tal med druiden Ugganaar. Der kan stadig være tid til at stoppe det, før det bliver endnu mere magtfuldt.", p="Ja, <Class>?", c="Det her er de mest alvorlige nyheder. Hvis det er, som Hannala sagde, bliver den nuværende krise i drømmen snart meget værre."},
  [82018] = {n="Ithariusen", l="Søg Ithariusen et sted i Sorgernes Sump.", d="Kender du Det Sunkne Tempel? Det har en historie, jeg ikke vil genfortælle her, men det står i øjeblikket under opsyn af en flok mægtige grønne drager. Tempelets øverste vogter er en stor drage ved navn Eranikas, og han er kendt for at være særligt indstillet på drømmen. Mit håb er, at han kan hjælpe os. Gå til Sorgernes Sump og mød rangeren der, som kaldes Ithariusen. Han ved måske, hvordan man kan række ud til Eranikas for at bede om hans hjælp.", p="Hilsner, <Race>.", c="Kommer du for at søge Eranikas? Din komme kan være ubeleilig, <Class>. Jeg frygter, at der er noget galt ved Det Sunkne Tempel. Kom, lad os tale videre."},
  [82019] = {n="Under Overfladen", l="Find ud af mere om, hvad der sker i Det Sunkne Tempel.", d="På sin tid var det såkaldte Sunkne Tempel hjemsted for en sekt af trolde, der var dedikeret til genoplivningen af deres gamle blodgud, Hakar Sjælflåeren. Før Atal'aj kunne virkeliggøre deres dystre ambitioner, slog Yserahs vrede templet ned i mudderet, og hun efterlod dragen Eranikas og hans flok som dets vogtere. På det seneste har jeg hørt mange hvisken om, at trolde igen er aktive der, og jeg frygter, hvad der kan være sket med dragerne.\n\nVær venlig, træd ind i templet og se, hvad du kan lære.", p="Hvilke nyheder bringer du om Eranikas?", c="Scenen, du beskrev, er yderst foruroligende. Det er langt værre, end jeg frygtede. Jeg kan kun håbe, at nogle af dragerne dér endnu lever og kan samles."},
  [82020] = {n="Tilbage til Månelunden", l="Vend tilbage til Ugganaar i Månelunden.", d="Vend tilbage til Ugganaar og fortæl ham, hvad vi har lært. Jeg vil prøve at spejde i templet selv for måske at komme i kontakt med dragerne, eller i det mindste indsamle mere information.", c="<Ugganaar sukker tungt>\n\nFlere dårlige nyheder. Meget vel, jeg takker dig, fordi du risikerede livet for at gå ind i templet for at lære det, du lærte, og for at bringe besked tilbage til mig. Jeg må informere de andre druider, så vi kan afgøre, hvad vi skal gøre næste gang.\n\nTak for nu. Jeg kan måske kalde på dig igen i fremtiden."},
  [82021] = {n="En Heldig Vending", l="Lyt til, hvad den Skyggefulde Figur har at sige.", d="Hej dér <Name>! Jeg stod lige her og nød udsigten, og jeg kunne simpelthen ikke lade være med at høre din klemme. Heldigvis tror jeg, at jeg kan give dig præcis det, du har brug for, til at tage fat på dit lille \"onde mareridtsuhyre-problem\".", p="Jeg må sige, at det ikke kunne have gået bedre, selv om jeg havde planlagt det. Det ser ud til, at skæbnen smiler til dig, ven.\n\n<Du får det tydelige indtryk, at den skyggefulde figur foran dig smiler skævt>", c="Er det ikke opmuntrende at have en som mig i nærheden, der har præcis det, du har brug for, lige når du har brug for det?"},
  [82022] = {n="Den Dårlige Nyhed...", l="Find den eventyrer, som den Skyggefulde Figur beskrev, og hent de Tomrumsdrevne Underarmsskinner.", d="Så den gode nyhed er, at en løsning findes. Den dårlige nyhed er, at det at skaffe det, du skal bruge for at overleve frygten, vil kræve en del besvær. Jeg ved godt, det er uheldigt, at det er så svært at få god hjælp i dag. Hvis denne eventyrer havde formået at gøre den ene simple ting, jeg bad dem om fra starten, ville du nu sidde og nyde et varmt måltid og en kold øl på en kro et sted, uden at vide noget om alt dette lige nu.", p="Hvordan går eftersøgningen?", c="Nå, det ser ud til, at disse er afkraftede. Uheldigt, men let at rette op på. For at genoplade dem skal du finde en tæt koncentration af Slangefolk-besværgere og massakrere dem i stor stil. Sjældent kan de bære noget, der kaldes en \"Tomrumskerne\", så gennemsøg kroppene, bring mig en, og... Haha! Bare for sjov! Hvis du bare kunne se dit eget ansigt...\n\nGiv mig et øjeblik, så burde jeg kunne indgyde disse med lidt kraft.... og så er vi i gang! Du er klar til at slå et mareridt ihjel."},
  [82023] = {n="De Tabte Underarmsskinner", l="Find \"Udyr\"s hule, som den sårede gnom henviste til, og hent de Tomrumsdrevne Underarmsskinner", d="Se, jeg er en riddere af en vis renommé, og jeg tog for nylig på mig opgaven at rense landet for en særligt frygtelig ondskab, der havde sin bolig på en nærliggende ø mod øst. Da jeg fandt det modbydelige væsen, blev der udkæmpet et virkelig episk slag. Vi må have kæmpet i timevis, indtil jeg til sidst drev udyret på flugt, uden tvivl løbet af sted for at dø af sine sår. Jeg var knap i stand til at nå tilbage til byen selv, før jeg kollapsede af udmattelse. Underarmsskinnerne må være glippet af min arm under kampen.", p="<Den unge mudderfisk ser på dig og laver en sød gurglende lyd.>\n\nDu bemærker, at der er en lille dynge jord ved siden af mudderfisken. Måske en slags hule. Du burde måske tjekke den for underarmsskinnerne?", c="Du har fundet en lille hule tilhørende en sød og tilsyneladende venlig ung mudderfisk. Det kan vel ikke være det udyr, gnomen henviste til?\n\n<Den lille mudderfisk laver en lille gurglende lyd og bøvser et par slimdækkede underarmsskinner op for dine fødder>"},
  [82043] = {n="De Vilde Guder", l="Saml en Vildhvisk-drik fra Jintha'alør i Bagland, og brug den øverst i Tornehøjene for at tale med Agamagg'ans ånd.", d="Der er noget galt med Hyjal-områdets loa. De mægtigste naturånder har vogtet over bjerget i tusindvis af år, men de begynder at forsvinde, den ene efter den anden.\n\nAgamagg'an, den største af de gamle loa, døde for længe siden. Men Amanerne har måder at tale med de døde på. Find den voodoo, de bruger, og tag den med til Rasorhegn. Tal med Agamagg'an og spørg ham, hvad der sker med hans slægtninge.", c="Selv hinsides dødens slør har jeg sanset en skygge falde over Hyjal og mine slægtninge.\n\nTag denne, dødelige. Du får brug for den til det, der skal komme."},
  [82044] = {n="De Vilde Guder", l="Lever Vilde Ofre til Skyggetand-udsendingen i Ondskoven. Brug Agamagg'ans Brøl på et Delirisk Oldtidens og besejr det for at få Vilde Ofre.", d="Et mørke har slået rod i Den Smaragdgrønne Drøm, og det har skygget for Hyjal-områdets oldtidsånder med forvirring og frygt.\n\nSøg disse delirøse ånder op, dødelige, og brug mit brøl til at lokke dem ind i kamp.\n\nNår du slår deres fordærvede former ned, bliver deres ånder renset, og de vil blive genfødt på ny.", p="Jeg fornemmer en forandring på bjerget, <Name>. Hvad bringer du mig?", c="Du gør loaerne en stor tjeneste, <Name>. Jeg vil bruge ofrene til at lede dem tilbage til Hyjal.\n\nBring mig flere ofre, så kan jeg måske skille mig af med noget af min klans skatte."},
  [82055] = {n="Mørkemånens Klit-kortstok", l="Returner Klit-kortstokken til Mørkemånens Marked, når det kommer til byen.", d="Nu hvor du har samlet alle Klit-kortene i én kortstok, dukker et niende kort mystisk op med samme bagside som de første otte. På dette kort står der indskrevet: \"Returner disse kort til Mørkemånens Marked, og bliv belønnet.\" Du har hørt, at dette marked skiftevis holder til i Mulgorr og Guldshire hver få uger, så du må vente, til de næste gang er her.", p="Jeg ser, at du har formået at fuldende en kortstok med klitter! Tillykke!", c="Så du har sat en kortstok med klitter sammen. Din gestus med at returnere den til os vil skabe et bånd mellem dig og Mørkemånen, der ikke snart vil blive glemt. Lad mig overrække dig et af de større Mørkemåne-kort som en lille tak for vores påskønnelse."},
  [82056] = {n="Mørkemånens Mare-kortstok", l="Returner Mare-kortstokken til Mørkemånens Marked, når det kommer til byen.", d="Nu hvor du har samlet alle Marekortene i én kortstok, dukker et niende kort mystisk op med samme bagside som de første otte. På dette kort står der indskrevet: \"Returner disse kort til Mørkemånens Marked, og bliv belønnet.\" Du har hørt, at dette marked skiftevis holder til i Mulgorr og Guldshire hver få uger, så du må vente, til de næste gang er her.", p="Jeg ser, at du har formået at fuldende en kortstok med Mare! Tillykke!", c="Så du har sat en kortstok med Marerne sammen. Din gestus med at returnere den til os vil skabe et bånd mellem dig og Mørkemånen, der ikke snart vil blive glemt. Lad mig overrække dig et af de større Mørkemåne-kort som en lille tak for vores påskønnelse."},
  [82057] = {n="Mørkemånens Pest-kortstok", l="Returner Pest-kortstokken til Mørkemånens Marked, når det kommer til byen.", d="Nu hvor du har samlet alle Pestkortene i én kortstok, dukker et niende kort mystisk op med samme bagside som de første otte. På dette kort står der indskrevet: \"Returner disse kort til Mørkemånens Marked, og bliv belønnet.\" Du har hørt, at dette marked skiftevis holder til i Mulgorr og Guldshire hver få uger, så du må vente, til de næste gang er her.", p="Jeg ser, at du har formået at fuldende en kortstok med pester! Tillykke!", c="Så du har sat en kortstok med Pester sammen. Din gestus med at returnere den til os vil skabe et bånd mellem dig og Mørkemånen, der ikke snart vil blive glemt. Lad mig overrække dig et af de større Mørkemåne-kort som en lille tak for vores påskønnelse."},
  [82058] = {n="Mørkemånens Vild-kortstok", l="Returner Vild-kortstokken til Mørkemånens Marked, når det kommer til byen.", d="Nu hvor du har samlet alle Vildkortene i én kortstok, dukker et niende kort mystisk op med samme bagside som de første otte. På dette kort står der indskrevet: \"Returner disse kort til Mørkemånens Marked, og bliv belønnet.\" Du har hørt, at dette marked skiftevis holder til i Mulgorr og Guldshire hver få uger, så du må vente, til de næste gang er her.", p="Jeg ser, at du har formået at fuldende en kortstok med vilde! Tillykke!", c="Så du har sat en kortstok med Vilde sammen. Din gestus med at returnere den til os vil skabe et bånd mellem dig og Mørkemånen, der ikke snart vil blive glemt. Lad mig overrække dig et af de større Mørkemåne-kort som en lille tak for vores påskønnelse."},
  [82062] = {n="Og Lykkeligt Siden", l="<Du får udleveret en lille pakke med en skjorte pænt foldet ned over den.>", d="Vi måtte være sikre på, at vi kunne stole på dig. Den slags venner er svære at finde.\n\nDer vokser en ondartethed frem, en tredje fraktion i Azerot. Både Horden og Alliancen arbejder uforvarende hen imod deres egne mål. At bremse deres fremmarch og danne informationsnetværk er alt, hvad vi har ressourcer til.\n\nTag denne, løft humøret, og tænk tilbage på bedre dage. Der vil snart komme en tid, hvor vi har brug for vores styrkede antal til en magtdemonstration."},
  [82068] = {n="Kamp mod Mareindfaldene", l="Gennemfør et Mareindfald-opdrag i Vildalas eller Bagland, og rapporter derefter til Markkaptajn Korliam eller Markkaptajn Arunnæl.", d="Gennemfør et Mareindfald-opdrag i Vildalas eller Bagland i dag, så får du en ekstra belønning.", p="Har du gennemført et opdrag endnu?", c="Godt gået, <Name>!"},
  [82071] = {n="Renende Ild", l="Find den besmittede Åndesten og drik den Mørke Ildsapta.", d="Der er noget, de brændte sedler er viklet om. En slags sapta. Du husker ikke, at den så eller lugtede helt sådan her, men ellers ligner den det samme. Der er noget ved den, der føles forkert, som om den er blevet besmittet af en anden magi. Der må være en Åndesten i nærheden, selv om du ikke husker, at der var nogen. At finde den kan måske hjælpe dig med at komme til bunds i denne mærkelighed.", c="Du stærk. Du rense ild. Du stop fordærvelse.\n\n\nDu finde og stop fordærvelse."},
  [82072] = {n="Udrensende Jord", l="Find den besmittede Åndesten og drik den Mørke Jordsapta.", d="En velkendt flaske sapta lå viklet ind i de udviskede sedler. Den er mærkeligt mørk, men magien føles for det meste velkendt. Der er en svag fornemmelse af fremmed magi, der besmitter blandingen. Dine instinkter fortæller dig, at der må være en Åndesten i nærheden, selv om du ikke kan huske nogen. At finde den kan hjælpe dig med at komme til bunds i dette mysterium.", c="Liv vokse igen. Styrke behøves.\n\n\nFordærvelse andetsteds. Find og stop."},
  [82073] = {n="Rensende Vand", l="Find den besmittede Åndesten og drik den Mørke Vandsapta.", d="Falmede og opblødte sedler er viklet om en mørk flaske. Sapta. Du kan ikke huske, at den nogensinde har set sådan her ud, men den ligner nok. Den lugter mærkeligt, som om den på en eller anden måde er besmittet. En Åndesten må være i nærheden, selv om den nok har været forladt i lang tid. At finde den kunne være den manglende brik i dette mærkelige puslespil.", c="Du renset. Du genoprettet. Stærk ånd. Du hjælpe.\n\n\nFordærvelse lever stadig. Stop den."},
  [82074] = {n="Svar på Ildens Kald", l="Saml 3 Elementar-essens fra vandelementarerne på Glemte Kyst over for Sardor Ø i Vildalas, og kombiner dem med Ildfragmentet for at tilkalde hjælp ved den fordærvede helligdom der.", d="Du stærk. Stærk nok.\n\n<Elementaren gnister og flimrer.>\n\nElementerne i Vildalas. Essens. Find helligdom.\n\nTag Fragment. Vil hjælpe.", p="Vil rense helligdommen.", c="Behov for hjælp. Andre elementer stærke. Bring dem."},
  [82075] = {n="Svar på Jordens Kald", l="Saml 3 Elementar-essens fra vandelementarerne på Glemte Kyst over for Sardor Ø i Vildalas, og kombiner dem med Jordfragmentet for at tilkalde hjælp ved den fordærvede helligdom der.", d="Liv vokse nu. Behov mere. Behov stoppe fordærvelse.\n\n<Sten skraber mod hinanden, mens elementaren forskydes.>\n\nVildalas. Elementer. Essens og helligdom.\n\nFind. Brug Fragment og find. Hjælp liv vokse.", p="Liv vokse her nu.", c="Liv vokse her nu. Behov mere. Andre elementer. Hjælp."},
  [82076] = {n="Svar på Vandets Kald", l="Saml 3 Elementar-essens fra vandelementarerne på Glemte Kyst over for Sardor Ø i Vildalas, og kombiner dem med Vandfragmentet for at tilkalde hjælp ved den fordærvede helligdom der.", d="Stærk ånd. Du hjælpe stoppe fordærvelse.\n\n<Vandet bruser, mens det hvirvler rundt om elementaren.>\n\nBrødre. Elementer af Vildalas hjælpe. Essens vil finde helligdom.\n\nFragment hjælpe også. Rense fordærvelse.", p="Vil rense helligdommen.", c="Rens helligdom nu. Ikke stærk nok. Behov andre. Andre elementer."},
  [82081] = {n="Et Brudt Ritual", l="Bring Det Faldne Inkarnations Skulderblad til Mølthor på Yojamba Ø.", d="Dette prægtige skulderblad er alt for genkendeligt -- Hakar blev kaldt ind i den fysiske verden og besejret. Trollene på Yojamba Ø vil gerne høre mere om, hvad der skete inde i Det Sunkne Tempel.", p="<Name>, hvilke nyheder har du fra Det Sunkne Tempel?", c="Det kan ikke være... rygterne om Det Sunkne Tempel er sande?\n\nDin sejr inde i de Sunkne Tempel vil blive husket af Zandalarierne i lang tid, mand. Det her ben.. det var et mærkeligt valg at levere til os.. men det var uden tvivl et af dem, der blev brugt til at kalde Hakar ind i den fysiske verden -- det er i gode hænder nu, <Name>. Vi behøver ikke længere bekymre os om, at Hakar vender tilbage takket være din indsats, mand... ikke?"},
  [82083] = {n="Et Brudt Ritual", l="Bring Det Faldne Inkarnations Skulderblad til Mølthor på Yojamba Ø.", d="Dette prægtige skulderblad er alt for genkendeligt -- Hakar blev kaldt ind i den fysiske verden og besejret. Trollene på Yojamba Ø vil gerne høre mere om, hvad der skete inde i Det Sunkne Tempel.", p="<Name>, hvilke nyheder har du fra Det Sunkne Tempel?", c="Det kan ikke være... rygterne om Det Sunkne Tempel er sande?\n\nDin sejr inde i de Sunkne Tempel vil blive husket af Zandalarierne i lang tid, mand. Det her ben.. det var et mærkeligt valg at levere til os.. men det var uden tvivl et af dem, der blev brugt til at kalde Hakar ind i den fysiske verden -- det er i gode hænder nu, <Name>. Vi behøver ikke længere bekymre os om, at Hakar vender tilbage takket være din indsats, mand... ikke?"},
  [82084] = {n="En lektion i læsekunst", l="Dine fremskridt i de arkane kunster har været mønstergyldige, <Name>. Jeg synes, du er klar til at forfatte en besværgelsesbog af din egen.\n\nLad os se... en fjerpen fra Ugleudyrene i Bagland, og blæk fremstillet af silithidharpiks... ja, det duer. Og til siderne: det fineste Farakki-papyrus!", p="Dine fremskridt i de arkane kunster har været mønstergyldige, <Name>. Jeg synes, du er klar til at forfatte en besværgelsesbog af din egen.\n\nLad os se... en fjerpen fra Ugleudyrene i Bagland, og blæk fremstillet af silithidharpiks... ja, det duer. Og til siderne: det fineste Farakki-papyrus!", c="Din besværgelsesbog er klar, <Name>. Må du fylde dens sider med arkane hemmeligheder, der kan måle sig med de gamle biblioteker i Elun'driss og Zuldazaar."},
  [82089] = {n="Transmutationens Mester", l="Bring Crimeon Labblad tre Arkanitstænger", d="Transmutation er en unik færdighed, som alle talentfulde alkymister har adgang til, men kun de mest hengivne til kunsten kan lære at blive ægte mestre i den. Du har måske, hvad der skal til, men du må bevise over for mig, at du er oprigtig i din søgen efter større viden og forståelse.\n\nBring mig tre Arkanitstænger som bevis på din hengivenhed over for kunsten.", p="Tre elendige stænger arkanit skulle da ikke være nok til at få denne viden?", c="Meget godt, jeg kan se din hengivenhed.\n\n<Crimeon proppede stængerne ned i sin rygsæk i hast>\n\nJa? Åh, transmutation. Selvfølgelig. Hold meget stille, jeg har brug for al min koncentration til dette.\n\n<Crimeon vifter dramatisk med hænderne, og en lille gnist skyder ud fra hans højre pegefinger>\n\nJa, øh, sådan. Det burde gøre det. Sikkert."},
  [82090] = {n="Blandekunst for sjov og profit", l="Bring Blandemester Blix 10 Usynlighedstrylledrikke, 10 Dæmondrab-eliksirer og 5 Vismandseliksirer.", d="Enhver alkymist, der er sin salt værd, vil fortælle dig, at kunsten handler om at maksimere fortjenesten. Det handler om at skaffe materialer billigt, fremstille i store mængder og sælge til himmelhøje priser. Hvad hvis jeg fortalte dig, at der findes en måde at få dine materialer til at række meget, meget længere? Nå, som den selverklærede \"Blandemester\" har jeg lige det, du behøver, hvis du vil løfte dit eliksir- og trylledrikspil op på et nyt niveau. Bring mig 10 Usynlighedstrylledrikke, 10 Dæmondrab-eliksirer og 5 Vismandseliksirer, så viser jeg dig tricksene.", p="Se, jeg har en masse potentielle elever, der venter på at lære af mig. Har du det, jeg bad om? Hvis ikke, så skrid.", c="Åh wow, du har faktisk fået de ting med? Nå, godt så. Lad os få kogt den hjerne af din og gjort dig til en ordentlig blandemester."},
  [82093] = {n="Jungle-stinkfrugt", l="Den dristige og stinkende frugt vil holde dit humør oppe, mens du krydser Sorgernes Sump og udforsker Det Sunkne Tempel. Lad dig ikke narre af lugten, makker, dette er en eftertragtet frugt fra mit folk!\n\nHvis du bringer mig noget fristende fra dine eventyr, skal jeg nok gøre det umagen værd, makker. Et bundt af vores fineste stinkfrugt for dine besvær! Skal vi lave en aftale?", p="Den dristige og stinkende frugt vil holde dit humør oppe, mens du krydser Sorgernes Sump og udforsker Det Sunkne Tempel. Lad dig ikke narre af lugten, makker, dette er en eftertragtet frugt fra mit folk!\n\nHvis du bringer mig noget fristende fra dine eventyr, skal jeg nok gøre det umagen værd, makker. Et bundt af vores fineste stinkfrugt for dine besvær! Skal vi lave en aftale?", c="Taz'dingo! Nyd den lækre, søde stinkfrugt, men husk makker... ingen refusion."},
  [82094] = {n="Signeterne fra det Tabte Tempel", l="For den mægtigste eventyrer har jeg de mægtigste handler. Jeg har noget, der forstærker dine skulderstykker, kraft fra selveste Atal'ajerne! <Name>, hvis du har mojo fundet af de stærkeste af dem i da tempel, skal jeg nok gøre det umagen værd.\n\nLad os ikke være for hastige nu, jeg tilbyder de retfærdigste handler...", p="For den mægtigste eventyrer har jeg de mægtigste handler. Jeg har noget, der forstærker dine skulderstykker, kraft fra selveste Atal'ajerne! <Name>, hvis du har mojo fundet af de stærkeste af dem i da tempel, skal jeg nok gøre det umagen værd.\n\nLad os ikke være for hastige nu, jeg tilbyder de retfærdigste handler...", c="Gå nu, makker. Hvis du har brug for flere af varerne, ved du, hvor du finder mig, <Name>!"},
  [82095] = {n="Guden Hakar", l="Bring det fyldte Æg fra Hakar til Yeh'kinja i Tanarisørken.", d="Nu er det tid til at fange essensen af Hakars avatar.\n\nTag Hakars Æg med til Den Faldne Guds Helligdom i Det Sunkne Tempel i Azerot. Påkald æggets kraft for at vække den døde gud.\n\nVær advaret: selv i denne spæde form vil han besidde ubegribelig magt, og han vil modstå dig med hver en dråbe af sit raseri.\n\nBesejr ham, og læg hans essens i Hakars Æg.", p="Har du besejret Hakars avatar, <Name>? Har hans essens endnu styrket ægget, jeg gav dig?", c="Hakars essens er blevet indsamlet! Selv nu vrimler ægget med liv! Kan Hakars myter være sande?\n\nDet må ikke være sandt, for så frygter jeg, hvad Hakar kan gøre, hvis han fødes igen. Jeg vil passe på dette æg og sørge for, at det ikke havner i onde hænder.\n\nDit arbejde for mig er færdigt, <Name>. Du har rørt ved en legende, og dine handlinger kan en dag ændre vores verdens ansigt."},
  [82096] = {n="Ned i Dybderne", l="Find Atal'Hakars Alter i Det Sunkne Tempel i Sorgernes Sump.", d="Inde i templet fandt jeg et cirkulært rum med seks altaner, hver med en slangestatue på kanten. Nysgerrig skubbede jeg til en af dem for at se, hvad der ville ske, og det var en fælde! Jeg var lige ved at falde til min død i eksplosionen. Da jeg lå der på syllen, kiggede jeg ned og bemærkede, at der var endnu en statue i bunden af rummet; et slags alter... Hakar, tror jeg, det hed.\n\nJeg tror, at dette alter er hemmeligheden -- du skal bringe dette tegn til alteret i Det Sunkne Tempel.", p="Da du undersøgte statuen, bemærkede du et hul i dens side, lige stort nok til tegnet, som Marvin gav dig...", c="Du skubber stenringen ind i åbningen, og du hører den låse sig fast.\n\nNu hvor stenen er på plads, kan du fortsætte... men hvad skal du gøre nu?\n\nMåske bør du undersøge dette alter nærmere..."},
  [82097] = {n="Cirklens Hemmelighed", l="Rejs ind i Det Sunkne Tempel og opdag hemmeligheden gemt i cirklen af statuer.", d="Mine minder er tågede, men jeg vil fortælle dig, hvad jeg kan. Cirklen af statuer i Det Sunkne Tempel er farlig, men jeg tror, at de rummer hemmeligheden til at låse op for en endnu større skat.\n\nFra hovedalteret lykkedes det mig at aktivere en række lys. Jeg tror, at hvis du kan finde ud af, hvad disse lys betyder, kan du måske låse op for de hemmeligheder, der gemmer sig i dette rum.\n\nJeg advarer dog dig, <Name>. Stor ondskab ligger i templet. Det er sandsynligt, at alt værdifuldt vil blive voldsomt bevogtet...", c="Idolets øje blinker klart oven på den ødelagte bunke. Dens gennemsigtighed afslører noget blankt bagved. Du flytter nogle store brokstykker og formår at trække det, der ligger under, løs.\n\nAtal'ajernes skat er nu din."},
  [82098] = {n="Ind i Det Sunkne Tempel", l="Indsaml 10 Atal'aj-tavler til Brohann Tøndemave i Stormvind.", d="Ifølge legenden er Det Sunkne Tempel et helligt tilflugtssted viet til den gamle gud Hakar Sjælflåeren. Vedligeholdt af en ondskabsfuld stamme af trolde ved navn Atal'ajerne siges templet at være uigennemtrængeligt.\n\nNu sunket under Tåresøen er det endnu sværere at hente artefakter fra templet. Men det er netop det, jeg har brug for, at du gør, <Name>.\n\nHjælp mig ved at indsamle de intakte Atal'aj-tavler. Bring dem til mig, så vender jeg tilbage til Opdagelsesrejsende-Klan som en helt. Sammen vil vi dele æren.", p="Mens skumringen langsomt sænker sig over min karriere, vender jeg mig mod dig, <Name>, for at hjælpe mig i min sidste søgen efter Opdagelsesrejsende-Ligaen. Hvis mine gamle knogler kunne samle styrken til at trodse Sorgernes Sump og det sunkne tempel, ville jeg kæmpe side om side med dig.\n\nStolthed gør det svært for mig at bede dig om hjælp til at samle Atal'aj-tavlerne. Men alderdommen tvinger nødvendigheden frem.\n\nHjælp mig venligst, <Name>. Jeg vil gerne trække mig fra Opdagelsesrejsende-Ligaen efter at have fuldført deres sidste opgave.", c="Atal'aj-tavlerne! Tak, <Name>!\n\nNår jeg har leveret disse til Opdagelsesrejsende-Ligaen, vil vores navne gå over i historien sammen. Du har hjulpet en gammel dværg med at opfylde hans sidste pligt i livet. For det er jeg evigt taknemmelig."},
  [82099] = {n="Ondskabens Dis", l="Indsaml 5 prøver af Atal'aj-dis, og vend derefter tilbage til Muigen i Un'Goro-krateret.", d="For at fortælle dig sandheden, <Name>, har jeg aldrig set planter som disse på mine rejser. Måske bør jeg tage en tur til dette krater...\n\nUnder alle omstændigheder tror jeg, at jeg ved præcis, hvad Muigen leder efter -- Atal'aj-dis. Det er frygtelig stank, svær at samle, men det er netop, hvad han har brug for for at kontrollere de små monstre.\n\nDu bliver nødt til at besøge Det Sunkne Tempel i Sorgernes Sump. Atal'aj-disen kan indsamles fra de dybe lurere, mudderorme eller slimvæsner, der findes der. Held og lykke, <Name>!", p="Lariøn taler stadig ikke til mig! Han ved virkelig, hvordan man bærer nag.", c="Jeg indrømmer, at jeg er lidt tøvende med at røre ved den stank, <Name>! Men hvis Gregor siger, at det virker, så er jeg villig til at prøve!"},
  [82100] = {n="Det Sunkne Tempel", l="Indsaml 20 Hakar-fetisjer og bring dem til Fel'Zerel i Stenhård.", d="Så han talte om Jammal'ans profeti?\n\nDen åndelige leder af Atal'ajerne mener, at når Hakar vender tilbage til Azerot fra Nether, vil guden give Atal'aj-stammen udødelighed.\n\nDumt bedrageri for at fremskynde en for tidlig dommedag, hvis du spørger mig.\n\nMen siger du, at den udstødte talte om fortryllede fetisjer? Det bekymrer mig meget. Hvis de faktisk er nøglen til Atal'ajernes ritual, der forårsagede dette rod, må vi forstå deres iboende kræfter.\n\nTag ind i templet, og tag fetisjerne!", p="Hvis Atal'aj-fetisjerne rummer kraften til at kalde Hakar frem og opfylde Jammal'ans profeti, skal de tages i besiddelse. Sådanne kræfter må Horden forstå!", c="Modige <Class>, du har bevist dig selv som en stor mester for Horden.\n\nNu skal denne samling af Hakar-fetisjer håndteres med det samme!"},
  [82101] = {n="Billeknuser-brændstof", l="Lever den tømte Billeknuser og 5 prøver af Atal'aj-dis til Lariøn i Marskalkens Fristed.", d="Du er heldig, <Name>! Jeg har arbejdet på nogle af mine egne eksperimenter, mens Marvin har været væk, og et af dem er en kortrækkende billeknuser. Med få justeringer burde den være god til at fjerne dig fra de Blodblad-skadedyr.\n\nJeg kan give dig en af mine billeknuser-prototyper, men du skal stadig samle brændstoffet. Du kan få den nødvendige Atal'aj-dis, som knuseren har brug for, i Det Sunkne Tempel. Det er de dybe lurere, mudderorme eller slimvæsner, du skal hente den fra.", p="Det her er udmattende, <Name>. De ting vil bare ikke lade mig være i fred!", c="Så Marvin var ikke her? Nå, vis mig, hvad du har, alligevel."},
  [82102] = {n="Eranikas' Essens", l="Placer Eranikas' essens i Essens-døbefonten i denne hule i Det Sunkne Tempel.", d="Da du rører ved ædelstenen, runger en dyb stemme i dit sind.\n\n\"Dødelige, hør denne bøn. Jeg er Eranikas fra Den Grønne Drageflugt, vogter af dette forbandede tempel. Min pligt om at sikre, at trolde aldrig igen frembringer deres vederstyggelige gud, er indtil nu endt i fiasko. Mens jeg indgyder denne ædelsten med en del af min essens, mærker jeg, at mit greb om Drømmen forvrides til kaos. Vær venlig -- læg denne ædelsten i essens-døbefonten i min hule, og lad vores magi dér rense plet fra mit sind, så jeg kan hvile.\"", p="Når du nærmer dig essens-døbefonten, som Eranikas fortalte dig om, rører hans stemme igen ved dit sind.\n\n\"Ja, dødelige, denne essens-døbefont vil forløse det ubesmittede element af mit sind, der stadig er indgydt i denne ædelsten. Læg ædelstenen i døbefonten, og lad Den Grønne Drageflugts magi rense korruptionen og smitten fra mit væsen. Først da vil jeg finde ægte forløsning, og først da vil Drageflugten kunne genetablere deres herredømme over Atal'ajerne.\"", c="Du placerer ædelstenen i essens-døbefonten.\n\n\"Tak, dødelige, du har -- nej... dette, dette kan ikke være! Nej! Korruptionen fra denne forbandede gud besmitter selv helligheden i en Grøn Drageflugts essens-døbefont! Nej, vær venlig, jeg mærker min essens rives fra mig! SMERTEN! Jeg mærker en evig mares greb tage fat i mig...\"\n\n\"Dødelige, jeg bønfalder dig! Find en af Den Grønne Drageflugt for at stoppe dette... hjælp mig... Jeg er lænket i mørket... evigt i pine... venligst, tortur mig ikke...\""},
  [82104] = {n="Jammal'an Profeten", l="Den Atal'aj-udstødte i Bagland vil have Jammal'ans hoved.", d="Mine Visnebark-følgesvende bryder sig ikke om fremmede omkring deres hjem.\n\nMig? Jeg har ikke noget hjem længere. Jeg blev forvist fra mit folk, den store Atal'aj-stamme i Sorgernes Sump.\n\nVores åndelige leder, Jammal'an, havde det, han kaldte en profeti. Han tror, at kaldelsen af guden Hakar vil give Atal'ajerne udødelighed.\n\nMen jeg opfordrede til forsigtighed. Hvad nu, hvis profetien ikke var andet end manipulation?\n\nJeg vil have hævn for min forvisning. Bring mig Jammal'ans hoved. Måske kan mit folk så blive frie.", p="Når Jammal'an er fjernet, har jeg en chance for at vende tilbage til mit folk.\n\nMed Jammal'an som deres åndelige leder står Atal'ajerne over for en sikker undergang.", c="Jammal'ans hensynsløse tillid til falske syner førte mit folk mod deres evige undergang.\n\nJeg takker dig, <Class>, for at hævne min forvisning. Jeg sørger over mit folk. Jeg har intet hjem at vende tilbage til."},
  [82106] = {n="Smedning af Mægtighedsstenen", l="Bring hekse-fjerene til Ashlam Tapperhånd.", d="Nu må vi kombinere de inerte svøbesten og skabe et våben, der kan splintre de udødes rækker. Dette er ingen simpel opgave, <Name>. Kun trolde fra det sunkne tempel bærer den slags sjældne magi, der er i stand til at vende ondskaben i noget mod sig selv.\n\nI templet er trollene kendt som Opskærer, Mijanne, Zolo, Hukkuu, Zul'lor og Lorro. Føl ingen anger over for deres korrupte sjæle... de er ikke uden ondskab.", p="Har du slået de elendige trolde ihjel?", c="Det er fremragende, <Name>. Jeg ville sige, at jeg er overrasket, men jeg vidste uden tvivl, at du ikke ville svigte os.\n\nDet er min ære at tildele dig en af de Hellige Mægtighedssten. Brug den godt."},
  [82107] = {n="Hekse-fjer", l="Bring hekse-fjerene fra trollene i Det Sunkne Tempel til Hordens Faldne Helt.", d="Din ære har bragt lidt fred til mig. Det er kun rigtigt, at jeg tilbyder dig noget til gengæld.\n\nMine våben og rustninger var storslåede i livet, men de er ingen nytte for mig nu. De ville være bedre brugt i din besiddelse.\n\nRejs til det sunkne tempel og ødelæg troldevogterne Opskærer, Mijanne, Zolo, Hukkuu, Zul'lor og Lorro. De bærer magiske fjer, der kan genskabe mit fysiske legeme længe nok til at give dig en belønning.", p="Er du allerede tilbage? Tiden er ikke den samme for mig længere, måske har din rejse virkelig været lang...", c="Endelig kan jeg mærke stålets kolde berøring igen, om så bare for et øjeblik."},
  [82108] = {n="Den Grønne Drake", l="Bring Morfaz' tand til Ogtinkt i Azshara. Ogtinkt holder til på klipperne nordøst for Eldaraths ruiner.", d="Nu sender jeg dig på en farlig jagt for at dræbe den grønne drake Morfaz og bringe hans tand til mig. Morfaz holder til dybt i Det Sunkne Tempel, hvis indgang ligger i Sorgernes Sump.\n\nHvis du ønsker at besejre ham, må du ikke gå alene. Denne drake er fjende af mange -- søg andre, der ønsker at tilintetgøre ham.\n\nDrakens tand repræsenterer den styrke, en jæger finder i selskab med andre. Bring den til mig, så har du lært meget.", p="Jeg ser visdom i dine øjne, <Name>. Er din jagt endt?", c="Du har lært de gamle måder, <Name>, og for det tilbyder jeg dig en gave fra mine dage som <Class>."},
  [82110] = {n="Den Azurblå Nøgle", l="Returner den Azurblå Nøgle til Lord Jorak Ravnholdt.", d="Det vil tage noget tid at tyde fragmenterne og fjerne fortryllelsen. Når jeg er færdig, vil jeg personligt levere tasken til Lord Ravnholdt.\n\nDer er stadig spørgsmålet om nøglen, som angiveligt holdes af en grøn drake ved navn Morfaz. Dragen har gjort sit hjem dybt i Det Sunkne Tempel, hvis indgang ligger i Sorgernes Sump.\n\nSaml dine venner og tag ud til hans hule. Lord Ravnholdt venter på din tilbagekomst med nøglen.", p="Tasken er allerede ankommet fra Ærkemager Xylemar, har du fundet nøglen?", c="Nøglen! Jeg troede, den var tabt for evigt. Tag venligst et fortryllet klædningsstykke fra mit lager -- de er forbeholdt skurke af usædvanlig dygtighed og loyalitet. Det skal være kendt, at <Name> ikke er én at lege med!"},
  [82111] = {n="Morfaz' Blod", l="Dræb Morfaz i Det Sunkne Tempel, og bring hans blod til Greta Mosshov i Ondskoven. Indgangen til det sunkne tempel findes i Sorgernes Sump.", d="Nu den sidste del, den anden kur.\n\nDen grønne drake Morfaz er kendt for at være immun over for alle former for gift og smitte -- mange druider døde for at bringe os denne viden. Der er ingen tvivl om, at hans blod er kraftfuldt nok til vores behov.\n\nEn budbringer fra Cenarion-kredsen vil tage de dele, du allerede har samlet, mens du henter den sidste. Kald dine allierede og find dragens hule i Det Sunkne Tempel. Bring hans blod til Greta Mosshov i Ondskoven.", p="Har du Morfaz' blod?", c="Du har dræbt Morfaz og båret hans blod til os... Jeg kan knap tro denne gode nyhed!\n\nVi vil kombinere ingredienserne med det samme og begynde at hele træerne og væsnerne i Ondskoven. Det vil tage en levetid at fortryde det, der er sket her, men du har givet os midlet til at gøre det."},
  [82112] = {n="En bedre ingrediens", l="Hent en råddent ranke fra vogteren i bunden af Det Sunkne Tempel, og vend tilbage til Torwa Stifinder.", d="Det er som jeg frygtede -- giften er simpelthen for svag til så mægtig en skabning.\n\nSkal vi skabe et toksin med tilstrækkelig styrke, må du vove dig til bunden af Det Sunkne Tempel, låse hemmelighederne i alteret op og hente en råddent ranke fra vogteren dér. Templet er farligt, og det ville være klogt at tage venner med.\n\nVend tilbage til mig, når det er gjort.", p="Har du hentet ranken?", c="Endelig kan toksinet fremstilles i fuldt omfang. Jeg tør ikke bede dig om at påføre skabningen det igen, for jeg har allerede bedt om for meget.\n\nDu har min tak og respekt. Må du have det godt på dine rejser, <Name>."},
  [82113] = {n="Da Hekseriet", l="Bring hekse-fjerene til Bath'rah Vindvogteren.", d="Åndetotemet er bare ikke nok. Vi ska' bruge noget hekseri-magi, for at det kan virke rigtigt.\n\nTrollene i det sunkne tempel har fjer, der er fyldt med hekseri-magi. Gå derhen og dræb Opskærer, Mijanne, Zolo, Hukkuu, Zul'lor og Lorro. Så har vi nok magi til et ordentligt åndetotem.", p="Hvor er fjerene, makker?", c="Det var på tide, at denne troll fik en ordentlig nats søvn! Åndetotemet vil våge over mig.\n\nJeg har samlet ting i lang tid, vil du måske have noget for alle dine besvær?"},
  [82114] = {n="Ødelæg Morfaz", l="Hent Arkanskaret fra Morfaz og vend tilbage til Ærkemager Xylemar.", d="Der er en grøn drake dybt i Det Sunkne Tempel ved navn Morfaz.\n\nFor mange år siden overvældede han mig i et dristigt baghold og opslugte min lærling helt. Selvom tabet af en lærling ikke er ukendt for mig, bar denne især et arkant skår af usædvanlig størrelse og kvalitet.\n\nDu må samle mægtige allierede og trænge ind i templet. Ødelæg Morfaz og hent det arkane skår fra hans tidløse mave.", p="Har du slået min gamle fjende ihjel?", c="Utroligt. Skaret er vokset, mens det har absorberet dragens energi gennem de lange år.\n\nDer er ikke mere, jeg kan bede dig om nu. Min fulde evne til at smede det arkane er vendt tilbage med dette skår. Min første skabelse er din, <Name>, og du behøver blot at vælge..."},
  [82115] = {n="Trolde af samme fjer", l="Bring i alt 6 hekse-fjer fra trollene i det sunkne tempel.", d="Mit kæledyr er næsten færdigt. Nu mangler jeg bare noget at stoppe det med.\n\nKun hekse-fjerene fra trollene i det sunkne tempel vil gøre det. De går under navnene Opskærer, Mijanne, Zolo, Hukkuu, Zul'lor og Lorro. Dræb dem. Dræb dem alle.\n\nDet er ingen simpel opgave, <Name>, så jeg gør det umagen værd ved at give dig noget af Nibbys -- han har nok ikke brug for det alligevel.", p="Har du bragt fjerene? Denne dukke skal stoppes!", c="Vidunderligt, nu er mit kæledyr færdigt!\n\n<Impsy stopper hurtigt dukken og giver den et dæmonisk kram.>\n\nÅh, hvilken mærkelig bivirkning disse hekse-fjer har..."},
  [82135] = {n="Håbets Pris", l="Bring Mannorok-Ekkende Kugle til Katrine den Rene i Stormvind.", d="<Aeonas siger intet, han rækker dig blot kuglen og vender sig væk>", p="Velkommen tilbage, <Name>. Hvad er det, du har der...\n\nÅh, herregud.", c="Det er en ret foruroligende historie. Den del af mig, der er <Class>, finder det umuligt at forene, at han frivilligt omgikkes med et medlem af svøben... men den <Race>-del af mig forstår, hvor stærke venskabets bånd kan være.\n\nJeg takker dig for at bringe kuglen hertil. Jeg vil sørge for, at den opbevares i det dybeste hvælv, vi har, for nu.\n\nÅh, en sidste ting: Jeg fik den repareret og havde håbet at kunne overrække den til Aeonas, når han vendte tilbage. Jeg tror, han ville ønske, at du skulle bære den i hans sted."},
  [82209] = {n="Vandposebelønning", l="Tilbage igen, <Name>? Hvis du har fem flere Ødevandrer-vandposer, så har jeg en forsyningspakke med dit navn på!", p="Tilbage igen, <Name>? Hvis du har fem flere Ødevandrer-vandposer, så har jeg en forsyningspakke med dit navn på!", c="Fremragende - jo flere vandposer vi kan genvinde, jo længere væk fra katastrofe er vi alle! Bliv ved med at komme med dem, så belønner jeg dig for hver fem vandposer, du bringer mig."},
  [82210] = {n="Dusør på trold-halskæder", l="Du har gjort det før, men vi vil fortsat modtage alle trold-stammehalskæder, du finder og er villig til at aflevere. Ved at aflevere dem til mig forbedrer du din stilling blandt Vildhamrene; hvis du er villig til at kæmpe for os, så vil vi være villige til at kæmpe for dig!\n\nJeg skal bruge fem trold-stammehalskæder, før de tæller, <Name>.", p="Du har gjort det før, men vi vil fortsat modtage alle trold-stammehalskæder, du finder og er villig til at aflevere. Ved at aflevere dem til mig forbedrer du din stilling blandt Vildhamrene; hvis du er villig til at kæmpe for os, så vil vi være villige til at kæmpe for dig!\n\nJeg skal bruge fem trold-stammehalskæder, før de tæller, <Name>.", c="Endnu et sæt halskæder betyder, at der er færre trolde i Bagland, vi skal bekymre os om! Du har gjort det igen, <Name>. Bliv ved med det gode arbejde!"},
  [82271] = {n="Mere Lysende Skorpidblod", l="Det skorpidblod fungerer fremragende, <Name>! Det er fantastisk, hvordan lidt glimmer og glans kan gøre et skrammel til et eftertragtet krimskrams. Gæsterne elsker det, og kærlighed er jo det hele drejer sig om, ikke sandt...\n\nDu har været en stor hjælp for mig, <Name>, og selvom jeg ikke har et stort behov for mere lysende skorpidblod, så får du stadig billetter, hvis du bringer mig mere.", p="Det skorpidblod fungerer fremragende, <Name>! Det er fantastisk, hvordan lidt glimmer og glans kan gøre et skrammel til et eftertragtet krimskrams. Gæsterne elsker det, og kærlighed er jo det hele drejer sig om, ikke sandt...\n\nDu har været en stor hjælp for mig, <Name>, og selvom jeg ikke har et stort behov for mere lysende skorpidblod, så får du stadig billetter, hvis du bringer mig mere.", c="Tak igen, <Name>. Her er dine billetter!"},
  [82272] = {n="Lysende Skorpidblod", l="I hele min tid på Markedet har jeg lært en masse om kunder. Her er en af de visdomskerner: kunder elsker ting, der lyser! Det er lige meget hvad det er - du kunne tage et knækket stolben og få det til at lyse, og hvert eneste barn vil komme fra milevis for at få et!\n\nSå, <Name>, jeg har brug for lysende skorpidblod. Du kan finde det hos skorpiderne i Sillithus, i Det Sønderrevne Land eller i Brændende Stepper.", p="I hele min tid på Markedet har jeg lært en masse om kunder. Her er en af de visdomskerner: kunder elsker ting, der lyser! Det er lige meget hvad det er - du kunne tage et knækket stolben og få det til at lyse, og hvert eneste barn vil komme fra milevis for at få et!\n\nSå, <Name>, jeg har brug for lysende skorpidblod. Du kan finde det hos skorpiderne i Sillithus, i Det Sønderrevne Land eller i Brændende Stepper.", c="Flot klaret, <Name>! Mange tak! Jeg skal lave maling af dette blod og forvandle alle slags billigt skrammel til lysende skatte!\n\nHer er dine billetter, og tak igen!"},
  [82273] = {n="Flere Flagermusøjne", l="<Name>, attraktionen jeg designer, bliver den mest skræmmende begivenhed siden Nisseborgen blev overrendt! Og det er i høj grad takket være dig og alle de krimskrams, du har bragt mig. Mange, mange tak!\n\nJeg har ikke brug for meget andet, men... hvis du bringer mig flere onde flagermusøjne fra flagermusene i Østlige Pestlande... så har jeg måske flere billetter til Mørkemånens Marked til dig.", p="<Name>, attraktionen jeg designer, bliver den mest skræmmende begivenhed siden Nisseborgen blev overrendt! Og det er i høj grad takket være dig og alle de krimskrams, du har bragt mig. Mange, mange tak!\n\nJeg har ikke brug for meget andet, men... hvis du bringer mig flere onde flagermusøjne fra flagermusene i Østlige Pestlande... så har jeg måske flere billetter til Mørkemånens Marked til dig.", c="Tak igen, <Name>. Her er dine billetter!"},
  [82274] = {n="Onde Flagermusøjne", l="Har du nogensinde fundet dig selv vandrende i en hule sent om natten på jagt efter eventyr? Har du? Virkelig? Så har du set de uhyggelige øjne på flagermus, der stirrer på dig oppefra og venter på, at du slapper af, så de kan suge dit blod!\n\nSkræmmende tanke, ikke sandt? Selvfølgelig! Der er ingen tvivl om, at flagermusøjne er skræmmende!\n\nVil du bringe mig nogle onde flagermusøjne, <Name>? Jeg vil bruge dem til... noget, jeg designer. Noget skræmmende.\n\nDu kan skaffe dem fra flagermusene i Østlige Pestlande.", p="Har du nogensinde fundet dig selv vandrende i en hule sent om natten på jagt efter eventyr? Har du? Virkelig? Så har du set de uhyggelige øjne på flagermus, der stirrer på dig oppefra og venter på, at du slapper af, så de kan suge dit blod!\n\nSkræmmende tanke, ikke sandt? Selvfølgelig! Der er ingen tvivl om, at flagermusøjne er skræmmende!\n\nVil du bringe mig nogle onde flagermusøjne, <Name>? Jeg vil bruge dem til... noget, jeg designer. Noget skræmmende.\n\nDu kan skaffe dem fra flagermusene i Østlige Pestlande.", c="Fantastisk! Du fik øjnene! Jeg håber, jagten på de flagermus var skræmmende for dig, for hvis det skræmte en modig <Class> som dig, så vil de øjne helt sikkert skræmme vores markedsgæster.\n\nTag disse billetter, <Name>, og tak for din tjeneste."},
  [82275] = {n="Stor sort kølle", l="Som min handling som verdens stærkeste kvinde har jeg planer om at modtage genstande fra publikum og knuse dem med en stor, sort kølle!\n\nKan du lave mig en stor, sort kølle, <Name>?", p="Som min handling som verdens stærkeste kvinde har jeg planer om at modtage genstande fra publikum og knuse dem med en stor, sort kølle!\n\nKan du lave mig en stor, sort kølle, <Name>?", c="Ah, perfekt! Denne kølle har et stort, tungt hoved. Jeg tror, jeg kunne knuse næsten hvad som helst med den. Jeg håber bare, at jeg ikke knækker den sammen med det, jeg svinger den mod!\n\nHer er dine billetter, <Name>. Nyd dit ophold på markedet!"},
  [82276] = {n="Styrkens ritualer", l="<Name>, på min jagt efter at blive verdens stærkeste kvinde har jeg rejst verden rundt og lært muskelopbygningshemmeligheder fra fjerne vægtmestre, styrkeguruer og gamle manualer. Nu kender jeg forbudte øvelser, der ville dræbe de svage og lamme de uindviede!\n\nDisse styrke- og konditionsbedrifter kræver træning med de tætteste malesten. <Name>, kan du finde eller lave nogle malesten og bringe dem til mig? Jeg giver dig billetter, hvis du gør det...", p="<Name>, på min jagt efter at blive verdens stærkeste kvinde har jeg rejst verden rundt og lært muskelopbygningshemmeligheder fra fjerne vægtmestre, styrkeguruer og gamle manualer. Nu kender jeg forbudte øvelser, der ville dræbe de svage og lamme de uindviede!\n\nDisse styrke- og konditionsbedrifter kræver træning med de tætteste malesten. <Name>, kan du finde eller lave nogle malesten og bringe dem til mig? Jeg giver dig billetter, hvis du gør det...", c="Tak, <Name>. Jeg vil bruge disse sten i et styrkeøgende ritual, som jeg lærte af en gammel tavle i de dybeste junglen i Kvælerdorn.\n\nDet siges, at hun, der udfører dette hellige ritual korrekt, vil have styrke og udholdenhed som ti Taurer!"},
  [82277] = {n="Flere Tætte Malesten", l="<Name>, tak for al den hjælp, du har givet mig. Jeg kan virkelig ikke takke dig nok!\n\nSelvom mit behov ikke længere er stort... hvis du bringer mig flere tætte malesten, har jeg stadig flere billetter til Mørkemånens Marked til dig.", p="<Name>, tak for al den hjælp, du har givet mig. Jeg kan virkelig ikke takke dig nok!\n\nSelvom mit behov ikke længere er stort... hvis du bringer mig flere tætte malesten, har jeg stadig flere billetter til Mørkemånens Marked til dig.", c="Igen, tak, <Name>. Nyd venligst disse billetter, og fortæl dine venner om Mørkemånens Marked!"},
  [82278] = {n="Flere Thorium-tingester", l="<Name>, du har været så god ved os, idet du uden træthed har bragt mig varer. Du har min evige tak!\n\nSelvom vores behov for thorium-tingester ikke er lige så stort, som det var, kan du stadig bringe dem til mig, og jeg bytter dem gerne til billetter til Mørkemånens Marked.", p="<Name>, du har været så god ved os, idet du uden træthed har bragt mig varer. Du har min evige tak!\n\nSelvom vores behov for thorium-tingester ikke er lige så stort, som det var, kan du stadig bringe dem til mig, og jeg bytter dem gerne til billetter til Mørkemånens Marked.", c="Her er de, <Name>. Her er billetter til Mørkemånens Marked til din fornøjelse. Brug dem ikke alle sammen samme sted, som man siger!"},
  [82279] = {n="Thorium-tingest", l="Yebb Neblegear arbejder, ligesom mig, på en fremtidig attraktion. Så fantastisk er denne attraktion, siger Nebb, at den vil tiltrække folk fra hele verden... og den vil gøre os alle meget, meget rige!\n\nHan siger, at han har brug for thorium-tingester til konstruktionen, og vil have mig til at samle dem til ham. Så hvad siger du, <Name>? Ved du, hvor man kan få thorium-tingester? Hvis du er ingeniør, kan du så lave dem? Vil du bytte dem til billetter til Mørkemånens Marked?", p="Yebb Neblegear arbejder, ligesom mig, på en fremtidig attraktion. Så fantastisk er denne attraktion, siger Nebb, at den vil tiltrække folk fra hele verden... og den vil gøre os alle meget, meget rige!\n\nHan siger, at han har brug for thorium-tingester til konstruktionen, og vil have mig til at samle dem til ham. Så hvad siger du, <Name>? Ved du, hvor man kan få thorium-tingester? Hvis du er ingeniør, kan du så lave dem? Vil du bytte dem til billetter til Mørkemånens Marked?", c="Ah, tak, <Name>! Yebb vil nyde disse tingester. Jeg ved ikke, hvad han har planlagt med dem, men Yebb er en klog lille gnom. Han er klog, og måske lidt snu...\n\nHvis han bare kunne lide smagen af humanoidekød... så ville han blive en fremragende trold!\n\nVær så venlig, <Name>. En aftale er en aftale, og disse billetter er dine."},
  [82280] = {n="Mekaniske reparationssæt", l="Den største grund til, at jeg ikke kan åbne min bod, er, at... alt er gået i stykker! Jeg har brug for mekaniske reparationssæt til at fikse alt det her!\n\nKan du bringe mig de sæt, <Name>? Jeg bytter dig... sæt for billetter til Mørkemånens Marked. Hvad siger du?", p="Den største grund til, at jeg ikke kan åbne min bod, er, at... alt er gået i stykker! Jeg har brug for mekaniske reparationssæt til at fikse alt det her!\n\nKan du bringe mig de sæt, <Name>? Jeg bytter dig... sæt for billetter til Mørkemånens Marked. Hvad siger du?", c="Tak! Nu kan jeg komme i gang med at reparere tingene.\n\nDet kommer til at tage mange reparationssæt og mange sene nætter, før alt er i orden igen. Nogle gange tænker jeg, at det var bedst at vende tilbage til mine rødder og genstarte min karriere som hovedjæger, men... markedet har været godt ved mig.\n\nTag disse billetter, <Name>, og hav det sjovt!"},
  [82281] = {n="Flere Rustningssæt", l="<Name>, jeg må takke dig for al din hjælp. Jeg har masser af forsyninger, takket være ikke så lidt indsats fra din side, men hvis du ønsker at bringe mig flere rustningssæt, så bytter jeg dem gerne til billetter til Mørkemånens Marked.", p="<Name>, jeg må takke dig for al din hjælp. Jeg har masser af forsyninger, takket være ikke så lidt indsats fra din side, men hvis du ønsker at bringe mig flere rustningssæt, så bytter jeg dem gerne til billetter til Mørkemånens Marked.", c="Der er de, <Name>. En god handel. Nyd dem."},
  [82282] = {n="Rustningssæt", l="Du er måske ikke klar over det, men at drive et rejsende cirkus er dyrt! Alt slides så hurtigt, at det er et under, vi overhovedet kan skabe overskud.\n\nPå grund af alle de skjulte omkostninger er vi altid på udkig efter måder at vedligeholde vores udstyr så billigt som muligt. Vores telte for eksempel revner regelmæssigt, men jeg har opdaget, at lædersæt til rustninger laver fremragende lapper. Kan du finde og bringe mig nogle rustningssæt? Det vil spare os for en formue! Gør du det, har jeg en håndfuld billetter til Mørkemånens Marked til dig...", p="Du er måske ikke klar over det, men at drive et rejsende cirkus er dyrt! Alt slides så hurtigt, at det er et under, vi overhovedet kan skabe overskud.\n\nPå grund af alle de skjulte omkostninger er vi altid på udkig efter måder at vedligeholde vores udstyr så billigt som muligt. Vores telte for eksempel revner regelmæssigt, men jeg har opdaget, at lædersæt til rustninger laver fremragende lapper. Kan du finde og bringe mig nogle rustningssæt? Det vil spare os for en formue! Gør du det, har jeg en håndfuld billetter til Mørkemånens Marked til dig...", c="Fantastisk! Det her vil virke glimrende! Jeg har lige bemærket et hul i et telt herovre, og et af disse rustningssæt er netop, hvad jeg har brug for til at lappe det!\n\nTusind tak, <Name>. Disse rustningssæt vil spare os for en masse i reparationsomkostninger. Her er dine billetter - du fortjener dem!"},
  [82283] = {n="Krokolisk-drengen og den skæggede mudderfisk", l="Yebb arbejder på andre attraktioner til sin zoo, blandt andet våde, sumpede boliger til en dreng, der er opvokset hos krokolisker, og måske også til en mudderfisk. Vi får brug for nogle flotte, vandtætte benbeskyttere, så vi ikke bliver gennemblødte under opsætning og nedtagning. Til det job tror jeg, at skildpaddeskæl-benbeskyttere vil gøre det.\n\n<Name>, kan du lave de benbeskyttere? Hvis du gør det, så vil en tyk bunke billetter til Mørkemånens Marked være din belønning...", p="Yebb arbejder på andre attraktioner til sin zoo, blandt andet våde, sumpede boliger til en dreng, der er opvokset hos krokolisker, og måske også til en mudderfisk. Vi får brug for nogle flotte, vandtætte benbeskyttere, så vi ikke bliver gennemblødte under opsætning og nedtagning. Til det job tror jeg, at skildpaddeskæl-benbeskyttere vil gøre det.\n\n<Name>, kan du lave de benbeskyttere? Hvis du gør det, så vil en tyk bunke billetter til Mørkemånens Marked være din belønning...", c="Fantastisk, du lavede dem! Disse vil gøre det fint... Jeg håber bare, at jeg ikke bliver den, der skal rense krokoliskburet, når tiden kommer. De bæster kan være ret bestialske, synes du ikke?\n\nHer er dine billetter, <Name>. Nyd dem, og nyd dit ophold på Mørkemånens Marked!"},
  [82301] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [82302] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [82303] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [82307] = {n="En fuld forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt op! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [82308] = {n="En fuld forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt op! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [82309] = {n="En fuld forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er talt op! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [82316] = {n="Syv øjne søger jeg...", l="Syv skjulte øjne søger jeg... bring dem til mig, og du skal også se.", p="Syv skjulte øjne søger jeg... bring dem til mig, og du skal også se.", c="Du er set..."},
  [82323] = {n="Livlige Fjerpragter", l="Et menneskes fantasi er en utrolig ting. Den kan få den mindste bakke til at virke som det største bjerg. Den kan få den mest harmløse skygge til at se ud, som om den er kastet af et frygteligt mareridt!\n\nVi på Mørkemånens Marked lader vores gæsters fantasi blomstre! Men for at udvide deres fantasi... må vi nogle gange være snedige.\n\nJeg har brug for livlige fjerpragter til en af mine attraktioner. Du kan skaffe dem fra fuglene i de farligste områder af Azeroth. Bring mig pragterne, så er mange billetter din!", p="Et menneskes fantasi er en utrolig ting. Den kan få den mindste bakke til at virke som det største bjerg. Den kan få den mest harmløse skygge til at se ud, som om den er kastet af et frygteligt mareridt!\n\nVi på Mørkemånens Marked lader vores gæsters fantasi blomstre! Men for at udvide deres fantasi... må vi nogle gange være snedige.\n\nJeg har brug for livlige fjerpragter til en af mine attraktioner. Du kan skaffe dem fra fuglene i de farligste områder af Azeroth. Bring mig pragterne, så er mange billetter din!", c="Ah, pragterne! De er fantastiske, synes du ikke! Det ville være let at antænde ens fantasi med sådanne skønheder!\n\nDu udfører så velgørende et arbejde, <Name>. Smilene på vores gæsters ansigter, når de ser showet, er i sig selv en stor betaling, men tag venligst disse billetter også."},
  [82656] = {n="Vild Lædervest", l="Bring 2 Skildpaddeskæl-brystplader, 2 Skildpaddeskæl-handsker og en Vildranke til Klangdor Hurtigskrider i Lejr Mojasje.", d="Vilde lædervester er grundstenen i ethvert vildt lædersæt. Vestens ramme og vildranken, der er vævet ind i den, skaber et produkt, der giver maksimal beskyttelse af torsoen, samtidig med at kraftfuld magi kan finde vej gennem beklædningen.\n\nTil dette mønster kræver jeg to Skildpaddeskæl-brystplader, to sæt Skildpaddeskæl-handsker og en vildranke. Det er ikke en let lektie, men det er en, du helt sikkert har evnerne til at gennemføre.", p="Har du de to Skildpaddeskæl-brystplader og handskerne? Glem heller ikke vildranken!\n\nAllerede med de tidligste mønstre lærer vi, at formens grundprincipper overføres godt til mere vanskelige beklædninger. Selvom det er forskellige ting, forbereder formen af skildpaddeskæl-brystpladerne dig på detaljearbejdet, der kræves for at lave en vild lædervest.\n\nNår du skrider frem i dine lektioner, vil de færdigheder, jeg underviser i, blive til kunst.", c="Dette er nogle meget flotte stykker, <Name>. Håndværket og omhu, der er lagt i at lave dem, viser, at du har valgt at vie dig fuldt ud til disse opgaver.\n\nDu har opfyldt mine krav, og dermed følger din belønning. Kendskabet til at lave vilde lædervester er nu dit!"},
  [82657] = {n="Vild Lædervest", l="Bring 2 Skildpaddeskæl-brystplader, 2 Skildpaddeskæl-handsker og en Vildranke til Pratt McGrubbe i Fjermåne-fæstningen.", d="Vilde lædervester er grundstenen i ethvert vildt lædersæt. Vestens ramme smelter sammen med vildranken for at skabe et produkt, der giver maksimal beskyttelse af torsoen, samtidig med at kraftfuld magi kan finde vej gennem beklædningen.\n\nTil dette mønster kræver jeg to Skildpaddeskæl-brystplader, to sæt Skildpaddeskæl-handsker og en vildranke. Det er en høj ordre, men en du burde have ringe besvær med at udfylde for mig.", p="Har du de to Skildpaddeskæl-brystplader og handsker, jeg bestilte? Glem heller ikke vildranken!\n\nAllerede med de tidligste mønstre lærer vi, at formens grundprincipper overføres godt til mere vanskelige beklædninger. Selvom det er forskellige ting, forbereder formen af skildpaddeskæl-brystpladerne dig på detaljearbejdet, der kræves for at lave en vild lædervest.\n\nOg handskerne... ja, de er bare til min egen fordel. Husk, du arbejder for mig!", c="Dette er nogle meget flotte stykker, <Name>. Håndværket og omhu, der er lagt i at lave dem, ville indbringe flere sølvmønter mere end et gennemsnitligt stykke.\n\nDu har udfyldt min ordre, og dermed følger din belønning. Kendskabet til at lave vilde lædervester er nu dit!"},
  [82662] = {n="Våbensmedens vej", l="For at blive en Våbensmed skal du lave følgende genstande og returnere dem til Jernus: 4 Månestål-bredsværd, 4 Massive Jernøkser, 2 Tunge Mithriløkser og 2 Store sorte køller.", d="Som våbensmed vil du opdage, at helte og eventyrere oftere end ikke kommer til dig efter udstyr. Selvom arbejdsbyrden til tider kan være uudholdelig, opvejer rigdommen fuldt ud ryggen og askelungen.\n\nÅh ja, <Name>, våbensmede er dem med alt guldet!\n\nHvis du ønsker at slutte dig til vores rækker, skal du vise mig, at du kan skaffe mig et par sølvmønter - altså, vise mig, at du har det, der skal til for at blive den <fyr/pige>, folk går til, når de har brug for førsteklasses våben. Kom i gang!", p="<Ironus er optaget af at stable guldmønter i pæne små bunker.>", c="Om tid! Jeg har kunder, der venter.\n\nGiv dem her, og hold godt øje med det. Du er ved at tage det første skridt i din karriere som våbensmed."},
  [82665] = {n="Våbensmedens vej", l="For at blive Våbensmed skal du lave følgende ting og levere dem til Borgøsj: 4 Månestål-bredsværd, 4 Massive Jernøkser, 2 Tunge Mithriløkser og 2 Store Sorte Køller.", d="En dag skal jeg smede et legendarisk hammer. En hammer, der er værdig en Krigshøvding!\n\nDet er mit livs værk, <Name>. Min lidenskab. Jeg kan se, at du har potentialet til at være blandt os, en af os - en våbensmed. Jeg er den, der kan hjælpe dig med at udnytte det potentiale.\n\nEn simpel opgave er alt, du skal klare. Simpelt for en med din usædvanlige færdighed.", p="For Hordens herlighed!", c="Dette er det sidste skridt, før du begynder din nye karriere som våbensmed, <Name>. Skulle du vælge at trække dig, er nu din sidste chance. Ellers så gør dig klar til at blive opslugt af viden!"},
  [82850] = {n="Fiskeolie", l="Fiskeolie holder krigens hjul i gang! Har du noget til mig, ven, så skal jeg nok gøre det umagen værd.", p="Fiskeolie holder krigens hjul i gang! Har du noget til mig, ven, så skal jeg nok gøre det umagen værd.", c="Mange tak, <Name>. Jeg skal nok bruge det godt."},
  [82851] = {n="Mørkejern-krudt", l="Vidste du, at Senatet i mørkejernstraditionen skriver forslag til love på eksplosive granater? Hvis Kejseren ikke kan lide loven... bum!\n\nHvorfor kigger du sådan på mig? Stoler du ikke på din gamle ven Grisby?", p="Vidste du, at Senatet i mørkejernstraditionen skriver forslag til love på eksplosive granater? Hvis Kejseren ikke kan lide loven... bum!\n\nHvorfor kigger du sådan på mig? Stoler du ikke på din gamle ven Grisby?", c="Mange tak, <Name>. Jeg skal nok bruge det godt."},
  [82853] = {n="Makulator-turboladere", l="Det er uheldigt, at forsendelsesruterne tilbage til Kæsan er så upålidelige for tiden. Derhjemme kan man få turboladere i dusinvis for få kobberstykker. Flyver ud af hylderne i hvert eneste maskinværksted. Man kan ikke blive dem kvit hurtigt nok.\n\nUnder alle omstændigheder, hvis du har nogle turboladere, du ikke ved, hvad du skal bruge til, så ville jeg da gerne tage dem af dine hænder!", p="Det er uheldigt, at forsendelsesruterne tilbage til Kæsan er så upålidelige for tiden. Derhjemme kan man få turboladere i dusinvis for få kobberstykker. Flyver ud af hylderne i hvert eneste maskinværksted. Man kan ikke blive dem kvit hurtigt nok.\n\nUnder alle omstændigheder, hvis du har nogle turboladere, du ikke ved, hvad du skal bruge til, så ville jeg da gerne tage dem af dine hænder!", c="Mange tak, <Name>. Jeg skal nok bruge det godt."},
  [83188] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [83189] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [83190] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [83191] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [83192] = {n="Hinsidig skat", l="Værsgo, chef!"},
  [83808] = {n="I en knibe", l="Hent Væbner Kuthberts sværd på marken mod syd og bring det tilbage til ham.", d="Du skræmte mig næsten ihjel! Jeg hørte dig komme og var overbevist om, at de døde endelig havde fået færten af mig! Men alligevel, et syn for trætte øjne er du. Jeg må væk fra dette sted og finde min herre, Ridder Dalton. Vil du hente mit våben til mig? Det blev revet ud af mit greb på marken udenfor, og jeg var tvunget til at flygte ind i denne lade.", p="Har du fundet klingen?", c="Tak, <Class>. Jeg kan ikke udtrykke min taknemmelighed for din hjælp.\n\nJeg har bare brug for et øjeblik til at samle tankerne. Jeg fik et forfærdeligt slag i hovedet derude, og jeg er ikke sikker på, hvor godt jeg kan kæmpe endnu. Åh, lys hjælp mig, jeg håber, Ridder Dalton er i sikkerhed."},
  [83822] = {n="Den Faldne Ridder", l="Før Væbner Kuthbert hen til den faldne ridders lig, som du fandt tidligere, og hjælp ham med at brænde liget.\n\nHvis du mister Væbner Kuthbert, vil han finde vej tilbage til sit skjulested i laden ved Dalsens Tårer og vente på dig der.", d="Siger du, at du fandt hans... lig? Nej... min herre kan ikke være død. Vores arbejde er ikke færdigt endnu.\n\nJeg... tak, <Class>. Jeg kæmper med at ryste chokket af mig, men jeg er glad for, at det var dig, der fandt ham.\n\nDet ser ud til, at hans opgave nu falder på mig. Men først må jeg vende tilbage til hans lig og brænde det, for at han ikke skal blive det, han ville tilintetgøre. Hvis jeg må bede dig om det én gang til, vil du så være venlig at føre mig hen til stedet, hvor Ridder Dalton faldt?", p="<Væbner Kuthberts øjne synes at stirre direkte igennem den faldne ridders lig. Han ryster lidt.>", c="Det ser ud til, at jeg igen står i gæld til dig, <Class>. Selv når jeg ser hans lig sådan, er det svært at tro, at det er virkeligt. Jeg har været i Ridder Daltons tjeneste, siden jeg var dreng, men jeg føler, at jeg stadig har meget at lære, hvis jeg skal fuldføre det, Ridder Dalton begyndte på.\n\nJeg kan ikke håbe på at beholde dig længere. Du har allerede ædret mig ud over alt mål med din venlige hjælp. Lad mig være, og lad mig ikke bede om mere. Jeg finder min vej herfra, på en eller anden måde."},
  [83823] = {n="En lektion i vold", l="Din væbner er blevet dygtigere ved at eventyre sammen med dig!", d="Din teknik er meget interessant,<Name>. Lidt mere røffel i kanterne end Ridder Dalton, men den har en mere \"verdslig\" kvalitet, som jeg synes passer mig godt. Tusind tak, jeg har allerede lært så meget af dig!", p="Din teknik er meget imponerende! Lidt mere røffel i kanterne end Ridder Dalton, men den har en mere \"verdslig\" kvalitet, som jeg synes passer dig godt. Tusind tak, jeg har allerede lært så meget af dig og kan ikke vente med at anvende det mod vores fjende!", c="Din væbner er blevet dygtigere ved at eventyre sammen med dig!"},
  [83934] = {n="Vis mig pengene!", l="Bring en Plettet Undermine-real til Pix Sizzix i Bytteviken.", d="Hej! Du ligner den \"opfindsomme eventyrer\"-type, så måske kan du hjælpe mig. Se, mine brødre og jeg kom fra de Tabte Øer med henblik på at starte en ny forretning, men vi løb ind i nogle pirater, der stjal vores startkapital. De folk, der finansierer vores operation hjemme, er ikke ligefrem det, jeg vil kalde forstående, så vi ville gøre det umagen værd, hvis du kan finde nogle af mønterne og bringe dem tilbage. Det er ingen almindelig guld, men du burde kende det, når du ser det.", p="Hvad har du til mig, <Race>?", c="Hej! Det er fantastisk!\n\nHvis du finder flere af vores mønter, så kom og se mig. Vi har et fantastisk udvalg af varer, og vi vil gerne bytte!"},
  [83935] = {n="Ryd vejen", l="Dræb 5 Pestsmittede zombier, 10 Skeletrædsler og 10 Rådnende lig for at hjælpe med at rydde en vej for Væbner Kuthbert, så han kan flygte.", d="Dunken i mit hoved er aftaget lidt, men jeg tror ikke, jeg kan kæmpe mig ud herfra på egen hånd endnu. Jeg hader at bede dig om mere, men kunne du hjælpe med at tynde ud i rækkerne og rydde en vej, så jeg kan komme væk?", p="Er vejen fri?", c="Tak igen, <Class>. Havde vi nogen som dig med os, da vi blev overfaldet, er jeg helt sikker på, at overfaldet var blevet til en flugt for vores angribere på få minutter!\n\nNu har jeg fået andet vejr og må finde Ridder Dalton. Han er en meget dygtig ridder, men jeg er sikker på, at han har brug for min hjælp. Sig mig, har du set ham derude? Han er svær at overse i sin skinnende hvide pladerustning."},
  [83936] = {n="Daltons opgave", l="Tal med Væbner Kuthbert for at lære mere om Ridder Daltons opgave.", d="<Væbner Kuthbert stirrer tomt på stedet, hvor Daltons lig brænder. Han er tydeligvis i en slags chok. Man kan se, at han ikke er i stand til at fortsætte med den opgave, han og hans herre satte sig for. Måske skulle du tale med ham og se, om du kan være til mere hjælp?>", p="Jeg... tak.", c="Jeg... ved ikke, hvad jeg skal sige. På trods af de dystre omstændigheder er det mere end godt held, at jeg befinder mig i tjeneste hos endnu en sand helt fra Alliancen. Jeg kan kun håbe, at jeg kan tjene dig bedre, end jeg tjente Ridder Dalton.\n\nFør an, helt."},
  [84008] = {n="En lektion i nåde", l="Din væbner er blevet dygtigere ved at eventyre sammen med dig!", d="Din teknik er meget interessant,<Name>. Lidt mere røffel i kanterne end Ridder Dalton, men den har en mere \"verdslig\" kvalitet, som jeg synes passer mig godt. Tusind tak, jeg har allerede lært så meget af dig!", p="Gennem dine lærdomme føler jeg mig mere forbundet med lyset end nogensinde. Jeg begynder at forstå, at rollen som en <Class> er at omfavne nåde lige så meget, som den er at slibe sin krigerske dygtighed. Jeg vil tage denne lektion til mig og anvende det, jeg har lært, til at styrke vores allierede!", c="Din væbner er blevet dygtigere ved at eventyre sammen med dig!"},
  [84011] = {n="Mere Stjerne-lotus", l="Saml 10 Stjerne-lotus i Baglandets Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Vi har stadig brug for mere Stjerne-lotus for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Seradanedal og bring mig nogle tilbage.", p="Har du Stjerne-lotussen?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84012] = {n="Mere Stjernesølv-malm", l="Saml 10 Stjernesølv-malm i Baglandets Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Vi har stadig brug for mere Stjernesølv-malm for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Seradanedal og bring mig nogle tilbage.", p="Har du Stjernesølv-malmen?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84013] = {n="Flere Stjerneskaller", l="Saml 10 Stjerneskaller i Baglandets Mareindfald og vend tilbage til Markkaptajn Korliam.", d="Vi har stadig brug for flere Stjerneskaller for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Seradanedal og bring mig nogle tilbage.", p="Har du Stjerneskallerne?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84014] = {n="Mere Månerod", l="Saml 10 Månerod i Vildalas' Mareindfald og vend tilbage til Markkaptajn Arunnæl.", d="Vi har stadig brug for mere Månerod for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Drømmegrenen og bring mig nogle tilbage.", p="Har du månerod?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84015] = {n="Flere større månesten", l="Saml 10 større månesten i Vildalas' Mareindfald og vend tilbage til Markkaptajn Arunnæl.", d="Vi har stadig brug for flere større månesten for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Drømmegrenen og bring mig nogle tilbage.", p="Har du de større månesten?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84016] = {n="Mere Månedrageskæl", l="Saml 10 Månedrageskæl i Vildalas' Mareindfald og vend tilbage til Markkaptajn Arunnæl.", d="Vi har stadig brug for mere Månedrageskæl for at vende Mareindfaldene. Rejs gennem Smaragdportalen i Drømmegrenen og bring mig nogle tilbage.", p="Har du Månedrageskællene?", c="Godt gjort! Tak. Din tjeneste vil blive husket."},
  [84017] = {n="En tid til at dræbe", l="Find Arkonaas og gør ende på ham.", d="Jeg føler, at jeg har lært så meget på så kort tid. Jeg tror ikke, at nogen nogensinde kan være virkelig klar til at møde det, jeg har tænkt mig at møde, men jeg føler mig så klar, som jeg nogensinde vil blive. Hvad siger du, <Name>? Skal vi gå og gøre ende på denne kamp?\n\nJeg er ikke sikker på, hvor vi skal begynde, men jeg har en fornemmelse af, at vi finder spor et sted i Østlige Pestlande. Vi bør nok starte der, hvor De Fordømtes Kult samles.", p="Hævnen er nær, jeg kan mærke den!", c="Det ser ud til, at vi har fundet vores bytte, men han synes at være uden for vores rækkevidde. Vi må finde en måde at nå ham på, så vi kan slå til."},
  [84124] = {n="Tapperhedens Arv", l="Vend tilbage til Ærefrygtens Alter", d="Den spektrale mester giver sig og bevæger sig mod alteret.", c="På alteret, du ærede, hviler en majestætisk tohånds-økse af guld og sort ved siden af en bog om slagmarkens legender."},
  [84125] = {n="Tæt nok til at røre", l="Dræb Skyggemagikere og Rædselsvævere i den Giftige Lysning og søg i deres lig efter noget, der kan hjælpe dig med at bryde skjoldet, der beskytter Arkonaas.", d="Disse grumme nekromantikere og deres tricks, det er ulækkert. Vi må finde en måde at bryde barrieren, der beskytter Arkonaas, for at gøre ende på ham!\n\nMange af De Fordømtes Kult og Svøbens tryllekunstnere er kendt for at bære på en række onde redskaber og fokusgenstande til mørk magi. Måske har nogle af de nærliggende Skyggemagikere eller Rædselsvævere noget, vi kunne bruge til at trænge igennem skjoldet?", p="Hvad fandt du, <Name>?", c="Ja! Det kan måske netop gøre det. Lad os skynde os tilbage til slagteriet og prøve denne anordning!"},
  [84126] = {n="Afslut Kampen", l="Dræb Arkonaas den Forbandede", d="Det kunne bare være det, <Name>. Dalton studerede længe De Fordømtes Kult og lærte mig en række velsignelser, man kan bruge til at forpurre deres magi. Takket være din flid med at afslutte min træning tror jeg nu, at jeg er stærk nok til at give denne genstand en sådan velsignelse, så dens magi bliver renset, og bruge den til at forstyrre barrieren omkring Arkonaas.\n\nKom, lad os brænde den kujons skjold af og gøre en ende på ham én gang for alle!", p="Endelig hævn.", c="Jeg kan næsten ikke tro, at vi gjorde det. Jeg kan ikke takke dig nok for den hjælp, du har ydet i denne opgave, <Name>.\n\nNu da det er overstået.... Jeg ved ikke rigtig, hvad jeg skal gøre med mig selv. Jeg har været så optaget af vores mission på det seneste, at jeg ikke har stoppet op for at tænke på, hvad der kommer bagefter. Jeg tror, at jeg lige nu gerne vil have lidt tid til at tænke. Indtil videre er jeg tilfreds med at fortsætte vores eventyr sammen, hvis du vil have mig med. Jeg har lært meget, men jeg tror stadig, at jeg har mere at lære af dig."},
  [84135] = {n="Strandrobot", l="Brug en sten eller noget lignende til at løsne dele af den mekaniske maskine.", d="Liggende på kysten, halvt tabt i eftermiddagens sprøjt, står en mærkelig metalkonstruktion. Den ligner en slags mekanisk maskine, men du har aldrig set noget lignende før. Du bemærker en etiket på dens side, der lyder: \"Tilhører D.E.L.T.A.: Dybhavs-Udforskning og Likvefaktions-Teknologi-Alliancen\". Du lægger også mærke til et lille rum, som du måske kan åbne.", c="Med dit våben og dine markfærdigheder får du brækket rummet op, og det afslører et hætteglas med lysende væske indeni."},
  [84136] = {n="Udyrmesteren af Månelunden", l="Rejs til landsbyen Nathavn i Månelunden på Kalimdør. Søg trolden Bantezo, en jæger, og bed hende om indsigt i dyrebeherskelse.", d="Mens jeg sporer Van Amburg, kunne du besøge en gammel forbindelse af mig. Bantezo er i Månelunden, hvor hun studerer dyrs adfærd sammen med druiderne for at forfine træningen af følgesvende. Hun har også kæmpet mod Van Amburg før og har måske nogle gode råd. Sig hej til hende for mig!\n\nNår du er færdig, mødes vi igen i Vinterkilde, hvor jeg planlægger at følge op på nogle spor. Jeg har en gammel lejr i de nordlige bakker, hvor vi kan tale uforstyrret.", c="Siger du, at Estelen siger hej? Underligt, jeg har ikke set den Alliance-møl siden da sidst, vi byttede pile i Kvælerdorn-dalen... nå, uanset hvad, dis sted er neutralt område. Hvis hun sendte dig til mig, så er du her for at snakke om dyr, ja?"},
  [84137] = {n="Mekanisk Romantik", l="Find en anvendelse til Styret Opdriftsfremskynder\n\nLeveret genstand:", d="Du undrer dig over, hvorfor denne mekaniske maskine blev styrtet ned her, og hvad denne væske bruges til. Måske kan du bruge den til at nå de nærliggende øer og olieriggen, der ser ud til at være forbundet med denne mystiske organisation. Hvis der er én ting, du ved, så er det, at magiske eliksirer smager ret godt.", c="Da du når olieriggen, får du øje på en mand i en laboratoriekittel, der fikler med nogle robotter. Han bemærker dig og råber, mens han stadig fikler med kontrollerne. \"Fantastisk! Du kommer lige til tiden. Jeg har ventet på dig. Du er den, der drak min vidunderlige eliksir, ikke? Jeg er Læge Jørgens, og jeg har et forslag til dig.\""},
  [84138] = {n="Frostede Tjenester", l="Forklar bogsituationen over for Læge Jørgens' kollega, Nummi, i Vinterkilde.", d="Jeg er chefingeniør, grundlægger og hovedtekniker for Dybhavs-Udforskning og Likvefaktions-Teknologi-Alliancen. Jeg er næsten færdig med mit seneste eksperiment, og jeg har brug for din hjælp! Jeg arbejder på en særlig enhed, der kan geolokalisere ressourcerige dimensioner. For at fuldføre min konstruktion har jeg brug for noget til gengæld: en bog med arkane formler, som jeg lånte til en gammel kollega af mig, Nummi, der fortsætter sit arbejde i Vinterkilde. Hent bogen til mig, så belønner jeg dig rigeligt!", c="Sebbe har brug for den? Han er et ægte nummer. Du spilder din tid på at bede om bogen. Jeg giver hverken den fra mig eller fortæller dig, hvor den er, endnu. Men måske kan vi lave en aftale."},
  [84146] = {n="Rød Taske-blues", l="Find den Røde Taske, som Nummi i Evigblik tabte i en luftskibsulykke over Brændende Stepper", d="Det, du vil have, er sikkert gemt, og jeg kan kun håbe, at det samme kan siges om det, jeg leder efter. Jeg havde en rød taske med nogle værdifulde exotiske ting, som jeg bruger til elektro-optik. Men jeg tabte den i en luftskibsulykke over Brændende Stepper! Tasken kan stadig være der, men med orker, oger og krybskytter har jeg været nødt til at sætte mit arbejde på pause. Hvis du kan finde den og bringe den tilbage til mig, lader jeg dig få Jørgens' gamle bog.", c="Du finder den røde taske liggende på bordet på en enkel, sorgløs måde."},
  [84147] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Vildthjerte-armbeskyttere til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84148] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Udyrsjægerens Bindinger til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84149] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Magisterens Bindinger til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84150] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Lysssmede-armbeskyttere til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84151] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med 1 sæt Hengivne Armbeskyttere til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
