  [84153] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Rædselståge-armbeskyttere til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84154] = {n="Et Oprigtigt Forslag", l="Skaf 15 Vinterkilde-blodprøver og 20 guld og bring dem sammen med et sæt Armbeskyttere af Tapperhed til Glædiana i Jernsmede.", d="Velkommen, <Class>. Jeg har noget, der måske kunne interessere dig.\n\nJeg har i min besiddelse et sæt rustning, der minder meget om den, som folk i dit erhverv bærer, men af langt højere kvalitet. Jeg ville være villig til at bytte armbeskytterne for almindelige i bytte for en lille tjeneste.\n\nBlodet fra frostsabrene og bjørnene, der lever i Vinterkilde, har egenskaber, jeg har brug for i øjeblikket. Bring mig en anseelig prøve af det sammen med armbeskytterne og en lille mængde guld. Du vil finde det umagen værd.", p="Har du bragt mig det, jeg bad dig om, <Name>?", c="Fremragende! Lad os så gennemføre byttet. Det er svært at skille sig af med denne fremragende rustning, men jeg er bange for, at jeg ikke får brug for den lige med det samme.\n\nHvis du er interesseret i at udføre mere arbejde for mig, er jeg måske villig til at give slip på resten af stykkerne."},
  [84155] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Vildthjerte-armbeskyttere til Mokkevar i Orgrimgrad.", d="Hil dig, <Class>! Jeg kan se på din væremåde, at du har set og gjort meget i denne verden. Alligevel vil jeg vædde på, at du ikke har set en rustning som denne.\n\nUdfør en lille tjeneste for mig, så er jeg villig til at bytte den til dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anseelig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring dette til mig sammen med nogle få guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Muks bliver meget glad for dette.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, er jeg villig til at overveje at give slip på resten af det."},
  [84156] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Udyrsjægerens Bindinger til Mokkevar i Orgrimgrad.", d="Hil dig, <Class>! Jeg kan se på din væremåde, at du har set og gjort meget i denne verden. Alligevel vil jeg vædde på, at du ikke har set en rustning som denne.\n\nUdfør en lille tjeneste for mig, så er jeg villig til at bytte den til dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anseelig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring dette til mig sammen med nogle få guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Muks bliver meget glad for dette.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, er jeg villig til at overveje at give slip på resten af det."},
