  [84162] = {n="Et Oprigtigt Forslag", l="Skaf 15 Silitus-giftprøver og 20 guld og bring dem sammen med et sæt Armbeskyttere af Tapperhed til Mokkevar i Orgrimgrad.", d="Hil dig, <Class>! Jeg kan se på din væremåde, at du har set og gjort meget i denne verden. Alligevel vil jeg vædde på, at du ikke har set en rustning som denne.\n\nUdfør en lille tjeneste for mig, så er jeg villig til at bytte den til dig for et almindeligt sæt armbeskyttere.\n\nJeg mangler en anseelig prøve af gift fra edderkopperne og skorpionerne, der lever i Silitus. Bring dette til mig sammen med nogle få guldmønter, så gennemfører jeg byttet.", p="Har du skaffet de ting, jeg har brug for, <Name>?", c="Ah, ja. Muks bliver meget glad for dette.\n\nDisse armbeskyttere var en del af et større rustningssæt. Hvis du er interesseret i at hjælpe mig yderligere, er jeg villig til at overveje at give slip på resten af det."},
  [84163] = {n="Bare Kompensation", l="Bring et Vildthjerte-bælte og et sæt Vildthjerte-handskerGlædiana i Jernsmede.", d="Du holdt dit ord og bragte enheden, som Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse oppe, så du redder min hud. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover, at dem, jeg giver dig til gengæld, er langt bedre.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg gemmer de bedste stykker, indtil dit arbejde er færdigt."},
  [84164] = {n="Bare Kompensation", l="Bring et Udyrsjægerens Bælte og et sæt Udyrsjægerens Handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte enheden, som Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse oppe, så du redder min hud. Bring mig et almindeligt bælte og et sæt handsker, som du ønsker at opgradere.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg gemmer de bedste stykker, indtil dit arbejde er færdigt."},
  [84165] = {n="Bare Kompensation", l="Bring et Magisterens Bælte og et sæt Magisterens Handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte enheden, som Muks har bygget. Jeg mener, at en belønning er på sin plads, hvis jeg skal holde din interesse oppe, så du redder min hud. Bring mig et almindeligt bælte og et sæt handsker, som du ønsker at opgradere.", p="Er du klar til at udføre byttet?", c="Du har holdt din side af aftalen, og jeg skal holde min.\n\nHusk bare, at jeg gemmer de bedste stykker, indtil dit arbejde er færdigt."},
  [84166] = {n="Bare Kompensation", l="Bring et Lysssmede-bælte og et sæt Lysssmede-hansker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde min hud. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover dig, at dem jeg giver dig til gengæld vil være langt bedre.", p="Er du klar til at udføre byttehandlen?", c="Du har holdt din ende af aftalen, jeg skal holde min.\n\nHusk bare, at jeg holder de bedste stykker tilbage, indtil dit arbejde er færdigt."},
  [84167] = {n="Bare Kompensation", l="Bring et Hengivent Bælte og et sæt Hengivne Handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde min hud. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover dig, at dem jeg giver dig til gengæld vil være langt bedre.", p="Er du klar til at udføre byttehandlen?", c="Du har holdt din ende af aftalen, jeg skal holde min.\n\nHusk bare, at jeg holder de bedste stykker tilbage, indtil dit arbejde er færdigt."},
  [84168] = {n="Bare Kompensation", l="Bring et Skyggehåndværks-bælte og et sæt Skyggehåndværks-handsker til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde min hud. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover dig, at dem jeg giver dig til gengæld vil være langt bedre.", p="Er du klar til at udføre byttehandlen?", c="Du har holdt din ende af aftalen, jeg skal holde min.\n\nHusk bare, at jeg holder de bedste stykker tilbage, indtil dit arbejde er færdigt."},
