  [84170] = {n="Bare Kompensation", l="Bring et Bælte med Tapperhed og et sæt Handsker med Tapperhed til Glædiana i Jernsmede.", d="Du holdt dit ord og bragte apparatet bygget af Muks. Jeg mener, en belønning er på sin plads, hvis jeg skal beholde din interesse i at redde min hud. Bring mig bæltet og det sæt handsker, du ønsker at opgradere. Jeg lover dig, at dem jeg giver dig til gengæld vil være langt bedre.", p="Er du klar til at udføre byttehandlen?", c="Du har holdt din ende af aftalen, jeg skal holde min.\n\nHusk bare, at jeg holder de bedste stykker tilbage, indtil dit arbejde er færdigt."},
  [84171] = {n="Bare Kompensation", l="Bring et Vildthjerte-bælte og et sæt Vildthjerte-handsker til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne klemme, ville det være klogt af mig at belønne dig efter din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge står igennem dette, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre udvekslingen?", c="Vores aftale står ved magt. Husk bare, at dette blot er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
  [84172] = {n="Bare Kompensation", l="Bring et Udyrsjægerens Bælte og et sæt Udyrsjægerens Handsker til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne klemme, ville det være klogt af mig at belønne dig efter din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge står igennem dette, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre udvekslingen?", c="Vores aftale står ved magt. Husk bare, at dette blot er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
