  [84176] = {n="Bare Kompensation", l="Bring en Snor med Elementer og et sæt Handsker med Elementer til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne klemme, ville det være klogt af mig at belønne dig efter din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge står igennem dette, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre udvekslingen?", c="Vores aftale står ved magt. Husk bare, at dette blot er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
  [84177] = {n="Bare Kompensation", l="Bring et Rædselståge-bælte og et sæt Rædselståge-bind til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne klemme, ville det være klogt af mig at belønne dig efter din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge står igennem dette, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre udvekslingen?", c="Vores aftale står ved magt. Husk bare, at dette blot er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
  [84178] = {n="Bare Kompensation", l="Bring et Bælte med Tapperhed og et sæt Handsker med Tapperhed til Mokkevar i Orgrimgrad.", d="Du har vist dig at være et meget pålideligt individ, <Name>. Så meget som jeg stoler på, at du vil hjælpe mig igennem denne klemme, ville det være klogt af mig at belønne dig efter din præstation.\n\nIndtil videre vil jeg bytte dit bælte og dine handsker. Hvis vi begge står igennem dette, vil jeg gøre resten af stykkerne tilgængelige for dig.", p="Er du klar til at udføre udvekslingen?", c="Vores aftale står ved magt. Husk bare, at dette blot er en smagsprøve på, hvad der venter dig. Befri mig fra denne forbandede skæbne, så belønner jeg dig med genstande af virkelig stor kraft."},
  [84179] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Vildthjerte-støvler, en Vildthjerte-kilt og Vildthjerte-skulderstykker.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84180] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Udyrsjægerens Støvler, Udyrsjægerens Bukser og Udyrsjægerens Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84181] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Magisterens Støvler, Magisterens Benbeskyttere og Magisterens Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84182] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Lysssmede-støvler, Lysssmede-benplader og Lysssmede-skulderstykker.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84183] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Hengivne Sandaler, en Hengiven Nederdel og en Hengiven Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
