  [84185] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Rædselståge-sandaler, Rædselståge-benbeskyttere og en Rædselståge-skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84186] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Glædiana i Jernsmede med et sæt Støvler med Tapperhed, Benplader med Tapperhed og Skulderstykker med Tapperhed.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte medaljonen sammen igen. Vend tilbage til Glædiana og fortæl hende, at Bodlej er hendes eneste håb om at finde de resterende stykker. Tal med hende om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er tilbage, <Name>. Du må fortælle mig alt, hvad du har fundet ud af. Men først lad os sørge for din belønning.", c="Jeg kan ikke tro, at vores liv næsten er fortabt på grund af en dum medaljon! Og du er sikker på, at Antion nævnte Bodlej?\n\nNå, du har gjort dit job, så lad os få din belønning overstået."},
  [84187] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Orgrimgrad med et sæt Vildthjerte-støvler, en Vildthjerte-kilt og Vildthjerte-skulderstykker.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved helt sikkert, hvordan man bærer nag.\n\nVi vil bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se på din belønning."},
  [84188] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Orgrimgrad med et sæt Udyrsjægerens Støvler, Udyrsjægerens Bukser og Udyrsjægerens Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved helt sikkert, hvordan man bærer nag.\n\nVi vil bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se på din belønning."},
  [84189] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Orgrimgrad med et sæt Magisterens Støvler, Magisterens Benbeskyttere og Magisterens Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved helt sikkert, hvordan man bærer nag.\n\nVi vil bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se på din belønning."},
  [84190] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Orgrimgrad med et sæt Hengivne Sandaler, en Hengiven Nederdel og en Hengiven Skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt i tre dele, uden at kende til forbandelsen, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har aftalt.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hver en smule af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved helt sikkert, hvordan man bærer nag.\n\nVi vil bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se på din belønning."},
  [84191] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Brølgrimmar med et sæt Skyggehåndværks-støvler, Skyggehåndværks-bukser og Skyggehåndværks-skulderstykker.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt op i tre dele, uden at kende den forbandelse, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har arrangeret.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hvert eneste lille stykke af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved sandelig, hvordan man holder på en vrede.\n\nVi skal bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se efter din belønning."},
  [84192] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Brølgrimmar med et sæt Støvler med Elementer, Kilt med Elementer og Skulderplader med Elementer.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt op i tre dele, uden at kende den forbandelse, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har arrangeret.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hvert eneste lille stykke af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved sandelig, hvordan man holder på en vrede.\n\nVi skal bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se efter din belønning."},
  [84193] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Brølgrimmar med et sæt Rædselståge-sandaler, Rædselståge-benbeskyttere og Rædselståge-skulderkappe.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt op i tre dele, uden at kende den forbandelse, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har arrangeret.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hvert eneste lille stykke af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved sandelig, hvordan man holder på en vrede.\n\nVi skal bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se efter din belønning."},
  [84194] = {n="Anthion Harmonis Afskedsord", l="Vend tilbage til Mokkevar i Brølgrimmar med et sæt Støvler med Tapperhed, Benplader med Tapperhed og Skulderstykker med Tapperhed.", d="Valtalaks sjæl blev opbevaret i denne amulet. I vores grådighed delte vi den tåbeligt op i tre dele, uden at kende den forbandelse, der ventede os.\n\nDen eneste måde at standse Valtalaks besværgelse på er at sætte amuletten sammen igen. Vend tilbage til Mokkevar og fortæl ham, at Bodlej er hans eneste håb om at finde de resterende stykker. Tal med ham om de belønninger, du har arrangeret.\n\nJeg skal for en gangs skyld hvile i fred. Jeg ønsker dig held og lykke; du får brug for hvert eneste lille stykke af det!", p="Du er vendt tilbage, og jeg kan se i dine øjne, at du har meget at fortælle mig, <Name>. Lad os først tage os af din belønning.", c="Denne forbandelse blev lagt over os for blot en medaljon. Herre Valtalak ved sandelig, hvordan man holder på en vrede.\n\nVi skal bestræbe os på at finde de resterende stykker - forhåbentlig før jeg møder en for tidlig død. Men før det, lad os se efter din belønning."},
  [84195] = {n="Det Bedste Gemmes Til Sidst", l="Giv Glædiana din Vildthjerte-hætte og Vildthjerte-vest.", d="Det er en fantastisk historie, <Name>! Du har min tak og den hjertelige taknemmelighed fra alle, der var involveret. Nu kan jeg måske sove om natten med begge øjne lukkede.\n\nAngående din belønning tror jeg, at jeg har et par ting, som du virkelig vil nyde.", p="Som aftalt, er du klar til at overrække dine Vildthjerte-stykker i bytte for din nye Vildhjerte-hætte og -vest?", c="Jeg kommer til at savne dig, <Name>. Jeg står i en enorm gæld til dig; jeg tror aldrig, at jeg kan betale den tilbage.\n\nJeg håber, at du nyder din nye hoved- og brystrustning, og at den beskytter dig i lang tid fremover."},
  [84196] = {n="Det Bedste Gemmes Til Sidst", l="Giv Glædiana din Udyrsjægerens Hue og Udyrsjægerens Tunika.", d="Det er en fantastisk historie, <Name>! Du har min tak og den hjertelige taknemmelighed fra alle, der var involveret. Nu kan jeg måske sove om natten med begge øjne lukkede.\n\nAngående din belønning tror jeg, at jeg har et par ting, som du virkelig vil nyde.", p="Som aftalt, er du klar til at overrække dine Udyrsjæger-stykker i bytte for din nye Dyrebehersker-hue og -tunika?", c="Jeg kommer til at savne dig, <Name>. Jeg står i en enorm gæld til dig; jeg tror aldrig, at jeg kan betale den tilbage.\n\nJeg håber, at du nyder din nye hoved- og brystrustning, og at den beskytter dig i lang tid fremover."},
  [84197] = {n="Det Bedste Gemmes Til Sidst", l="Giv Glædiana din Magister-krone og Magister-kapper.", d="Det er en fantastisk historie, <Name>! Du har min tak og den hjertelige taknemmelighed fra alle, der var involveret. Nu kan jeg måske sove om natten med begge øjne lukkede.\n\nAngående din belønning tror jeg, at jeg har et par ting, som du virkelig vil nyde.", p="Som aftalt, er du klar til at overrække dine Magister-stykker i bytte for din nye Tryllekunstner-krone og -kapper?", c="Jeg kommer til at savne dig, <Name>. Jeg står i en enorm gæld til dig; jeg tror aldrig, at jeg kan betale den tilbage.\n\nJeg håber, at du nyder din nye hoved- og brystrustning, og at den beskytter dig i lang tid fremover."},
