  [85971] = {n="Et Anbefalingssignet", l="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos mine styrker, de Hydraksiske Vandherrer.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Jeg tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, vil jeg acceptere det, hvis I stadig ønsker at aflevere et enkelt signet.", p="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos mine styrker, de Hydraksiske Vandherrer.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Jeg tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, vil jeg acceptere det, hvis I stadig ønsker at aflevere et enkelt signet.", c="Meget vel - jeres gerninger er blevet anerkendt. Bliv ved med det gode arbejde, <Class>.\n\nHvis I har flere signeter at aflevere, vil jeg acceptere dem."},
  [85972] = {n="Et Anbefalingssignet", l="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos mine styrker, de Hydraksiske Vandherrer.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Jeg tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, vil jeg acceptere det, hvis I stadig ønsker at aflevere et enkelt signet.", p="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos mine styrker, de Hydraksiske Vandherrer.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Jeg tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, vil jeg acceptere det, hvis I stadig ønsker at aflevere et enkelt signet.", c="Meget vel - jeres gerninger er blevet anerkendt. Bliv ved med det gode arbejde, <Class>.\n\nHvis I har flere signeter at aflevere, vil jeg acceptere dem."},
  [85973] = {n="Ti Anbefalingssignetter", l="Jeg modtager anbefalingssignetter fra eventyrere, der har fået dem i tjenesten. For hvert sæt på ti, du afleverer til mig, vil du få betydelig anerkendelse fra mine styrker, de Hydraksiske Vandherrer. Jeg modtager også enkelte modmærker, men til en langt mindre anerkendelse. Jeg er langt mere interesseret i større bedrifter i pligten, men ingen bedrift vil blive ignoreret.\n\nDet sagt, vil jeg acceptere dine signeter, hvis du er klar til at aflevere et sæt.", c="Fremragende! Det er ingen lille ofring, I har gjort for at tjene disse signeter, og I vil blive anerkendt for jeres tjeneste, som det sig hør og bør. Det er eventyrere som jer, <Name>, der virkelig gør en forskel.\n\nLad mig vide, hvis I har flere signeter at aflevere; jeg vil gerne acceptere dem."},
  [85974] = {n="Ti Anbefalingssignetter", l="Jeg modtager anbefalingssignetter fra eventyrere, der har fået dem i tjenesten. For hvert sæt på ti, du afleverer til mig, vil du få betydelig anerkendelse fra mine styrker, de Hydraksiske Vandherrer. Jeg modtager også enkelte modmærker, men til en langt mindre anerkendelse. Jeg er langt mere interesseret i større bedrifter i pligten, men ingen bedrift vil blive ignoreret.\n\nDet sagt, vil jeg acceptere dine signeter, hvis du er klar til at aflevere et sæt.", c="Fremragende! Det er ingen lille ofring, I har gjort for at tjene disse signeter, og I vil blive anerkendt for jeres tjeneste, som det sig hør og bør. Det er eventyrere som jer, <Name>, der virkelig gør en forskel.\n\nLad mig vide, hvis I har flere signeter at aflevere; jeg vil gerne acceptere dem."},
  [85975] = {n="Et Anbefalingssignet", l="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos Thorium-broderskabet.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Vi tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, står jeg klar til at hjælpe, hvis I stadig ønsker at aflevere et enkelt signet.", p="For de eventyrere, der kun har et enkelt anbefalingssignet, vil jeg bytte det til en lille anerkendelse hos Thorium-broderskabet.\n\nHusk på, at det er bedre at aflevere en stak på ti signeter på én gang; jeres indsats vil få større anerkendelse, hvis I gør det. Vi tilbyder en byttetjeneste for enkelte signeter til dem, der ikke har nok til en fuld stak på ti.\n\nDet sagt, står jeg klar til at hjælpe, hvis I stadig ønsker at aflevere et enkelt signet.", c="Meget vel - jeres gerninger er blevet indført i protokollen, og I er behørigt anerkendt for jeres indsats. Bliv ved med det gode arbejde, <Class>.\n\nHvis I har flere signeter at aflevere, kan jeg hjælpe jer yderligere med det."},
