  [87439] = {n="Sølvdæmringens Stofhandsker", l="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse som gengæld. Disse bør vise sig værdifulde i vores kamp mod <Race>-Svøben.", p="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse som gengæld. Disse bør vise sig værdifulde i vores kamp mod <Race>-Svøben.", c="Godt gået, <Name>. Vælg den håndbeskyttelse du vil have som tak for din indsats."},
  [87440] = {n="Sølvdæmringens Stofhandsker", l="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse som gengæld. Disse bør vise sig værdifulde i vores kamp mod den udøde Svøbe.", p="Hvis du bringer mig tredive nekrotiske runer, giver jeg dig dit valg af håndbeskyttelse som gengæld. Disse bør vise sig værdifulde i vores kamp mod den udøde Svøbe.", c="Godt gået, <Name>. Vælg den håndbeskyttelse du vil have som tak for din indsats."},
  [87441] = {n="Atiesh, Vogterens Storstav", l="Anakronos ved Tidens Huler i Tanaris ønsker, at du tager Atiesh, Vogterens Storstav til Stratholm og bruger den på Indviet Jord. Besejr væsenet, der bliver uddrevet af stavet, og vend tilbage til ham.", d="Denne sidste opgave bliver den sværeste af dem alle, <Name>. Du har stået over for og besejret både Den Gamle Gud og Liskekongens General, men nu må du møde Sargeråses hånd.\n\nTag stavet med til Stratholm. Der vil du finde et stykke indviet jord: grunden, hvor Herrelandes største riddere blev myrdet. Placer den besmittede stav på den hellige jord og gør dig klar til, at et væsen af enorm kraft bryder ud indefra... Besejr det dæmoniske væsen, der styrer stavet, og vend tilbage til mig.", p="Jeg må ikke blande mig, <Race>.", c="Betydningen af denne bedrift må ikke undervurderes, <Name>. Du har gjort det, de fleste ville have troet umuligt. Desværre var det skæbnebestemt. Stavet har truffet sit valg..."},
  [87442] = {n="Atiesh, Vogterens Storstav", l="Anakronos ved Tidens Huler i Tanaris ønsker, at du tager Atiesh, Vogterens Storstav til Stratholm og bruger den på Indviet Jord. Besejr væsenet, der bliver uddrevet af stavet, og vend tilbage til ham.", d="Denne sidste opgave bliver den sværeste af dem alle, <Name>. Du har stået over for og besejret både Den Gamle Gud og Liskekongens General, men nu må du møde Sargeråses hånd.\n\nTag stavet med til Stratholm. Der vil du finde et stykke indviet jord: grunden, hvor Herrelandes største riddere blev myrdet. Placer den besmittede stav på den hellige jord og gør dig klar til, at et væsen af enorm kraft bryder ud indefra... Besejr det dæmoniske væsen, der styrer stavet, og vend tilbage til mig.", p="Jeg må ikke blande mig, <Race>.", c="Betydningen af denne bedrift må ikke undervurderes, <Name>. Du har gjort det, de fleste ville have troet umuligt. Desværre var det skæbnebestemt. Stavet har truffet sit valg..."},
  [87443] = {n="Atiesh, Vogterens Storstav", l="Anakronos ved Tidens Huler i Tanaris ønsker, at du tager Atiesh, Vogterens Storstav til Stratholm og bruger den på Indviet Jord. Besejr væsenet, der bliver uddrevet af stavet, og vend tilbage til ham.", d="Denne sidste opgave bliver den sværeste af dem alle, <Name>. Du har stået over for og besejret både Den Gamle Gud og Liskekongens General, men nu må du møde Sargeråses hånd.\n\nTag stavet med til Stratholm. Der vil du finde et stykke indviet jord: grunden, hvor Herrelandes største riddere blev myrdet. Placer den besmittede stav på den hellige jord og gør dig klar til, at et væsen af enorm kraft bryder ud indefra... Besejr det dæmoniske væsen, der styrer stavet, og vend tilbage til mig.", p="Jeg må ikke blande mig, <Race>.", c="Betydningen af denne bedrift må ikke undervurderes, <Name>. Du har gjort det, de fleste ville have troet umuligt. Desværre var det skæbnebestemt. Stavet har truffet sit valg..."},
  [87444] = {n="Atiesh, Vogterens Storstav", l="Anakronos ved Tidens Huler i Tanaris ønsker, at du tager Atiesh, Vogterens Storstav til Stratholm og bruger den på Indviet Jord. Besejr væsenet, der bliver uddrevet af stavet, og vend tilbage til ham.", d="Denne sidste opgave bliver den sværeste af dem alle, <Name>. Du har stået over for og besejret både Den Gamle Gud og Liskekongens General, men nu må du møde Sargeråses hånd.\n\nTag stavet med til Stratholm. Der vil du finde et stykke indviet jord: grunden, hvor Herrelandes største riddere blev myrdet. Placer den besmittede stav på den hellige jord og gør dig klar til, at et væsen af enorm kraft bryder ud indefra... Besejr det dæmoniske væsen, der styrer stavet, og vend tilbage til mig.", p="Jeg må ikke blande mig, <Race>.", c="Betydningen af denne bedrift må ikke undervurderes, <Name>. Du har gjort det, de fleste ville have troet umuligt. Desværre var det skæbnebestemt. Stavet har truffet sit valg..."},
  [87459] = {n="Skarlagen-aktiviteter", l="Rejs til området nær Korsfarer-forposten nordvest for Bolværket i Tirisfals Lysninger, og undersøg tegn på nylig aktivitet fra det Skarlagenrøde Korstog. Bring eventuelle oplysninger, du finder, tilbage til Leonid Barthalomæus den Ærværdige.", d="Mens vi holder pænt med de Skarlagenrøde Korsfarere her, opfører de sig fortsat mistænkeligt andre steder. Nogle af mine kontakter i Tirisfal fortæller mig om et dristigt indfald fra det Skarlagenrøde Korstog helt ind i hjertet af selve Undergrunden, og vores spejdere har meldt om store karavaner, der transporterer forsyninger gennem pestlandene. En elitestyrke fra de skarlagenrøde er blevet set nær Korsfarer-forposten i Tirisfals Lysninger, mellem Balnirs Gård og Giftvævsdalen. Vil du være so venlig at tage derhen og se, hvad du kan finde?", p="Hvordan skrider din mission frem, <Name>?", c="Jeg forstår. Så det ser ud til, at Korstoget har bortført nogen fra byen, og endda en vigtig person. Dette er yderst bekymrende. Tak, <Name>. Indtil videre skal du ikke gøre noget og ikke tale med nogen om dette. Vores alliance med det Skarlagenrøde Korstog er skrøbelig, men vi har brug for al den hjælp, vi kan få, for at håndtere truslen fra Naxxrammas lige nu.\n\nJeg vil følge op på dette selv. Jeg kan få brug for dig igen senere for mere hjælp i sagen. Indtil da, gå i lysets vej."},
  [87493] = {n="Uro i Tyrs Hånd", l="Spejd Skarlagen-basislejren vest for Tyrs Hånd i de Østlige Pestlande, og forsøg at finde ud af, hvad der sker med de skarlagenrøde korstogsstyrker derude.", d="Der er sket en interessant udvikling, <Name>. Det ser ud til, at mens det Skarlagenrøde Korstogs fokus var rettet mod Naxxrammas, har der været en slags uro i rækkerne i Tyrs Hånd. Detaljerne er spredte indtil videre, men ud fra det, vi forstår, har der været nogle interne stridigheder blandt korsfarerne.\n\nJeg vil gerne sende dig til lejren vest for Tyrs Hånd for at vurdere situationen for os. Lad os vide, hvad du finder, så hurtigt som muligt.", c="Hilsner, <Name>. Jeg er glad for at se dig igen. Jeg ville dog ønske, det var under bedre omstændigheder."},
  [87497] = {n="Splittelsen", l="Tal med Beatrix for at lære mere om situationen i Skarlagen-enklaven i Tyrs Hånd, og rapporter tilbage til Leonid Barthalomæus den Ærværdige i Lysets Håb-kapellet, når du har fundet ud af, hvad der sker.", d="Jeg skal komme direkte til sagen: Tyrs Hånd-enklaven er ikke længere under vores kontrol. Mens vi var væk ved Naxxrammas, kom en styrke af fjendtlige korsfarere fra byen Stratholm og tog kontrol over fæstningen. Vi er blevet nægtet adgang, og alle udsendinge, vi sender derind, vender ikke tilbage.\n\nJeg er uvillig til at bede om ekstern hjælp, men noget er meget galt, og jeg ved ikke, om vi kan generobre enklaven alene.", p="Hvad har du fundet ud af?", c="Udviklingen i Tyrs Hånd er... bestemt interessant. Abbendis er sandsynligvis død, og Balnazar er vendt tilbage. Der er en del af mig, der helst vil sidde tilbage og se det Skarlagenrøde Korstog høste, hvad de har sået, men jeg føler, at Sølvdæmringen uanset udfaldet sandsynligvis vil blive trukket ind i konflikten. Svage, som vi er efter Naxxrammas-kampagnen, foretrækker Herre Tyrosus, at vores involvering sker på vores præmisser frem for at blive tvunget til det.\n\nSagde du i øvrigt, at Inkvisitor Kaldoran var der?"},
  [87498] = {n="Skarlagen-generobringen", l="Vend tilbage til Kommandør Beatrix i Skarlagen-basislejren vest for Tyrs Hånd.", d="<Leonids udtryk mørkner, når du bekræfter, at Kaldoran er til stede i Skarlagen-basislejren. Efter et øjeblik genvinder han fatningen.>\n\nTak... tak, <Name>. Fortsæt for nu med at hjælpe Beatrix, hvis du er villig. Jeg vil rådføre mig med Herre Tyrosus og udarbejde nødplaner, hvis Sølvdæmringen skal blive direkte involveret. Jeg beder til, at situationen ikke er så slem, som vi er blevet fortalt, men hvis vi må træde til og gøre en ende på det her, vil vi være klar.", c="Så du vil hjælpe os? Jeg må indrømme, at jeg er lettet. Jeg har set dig og dine allieredes evner på nærmeste hold, og jeg er glad for at have dig på vores side i dette. Jeg havde håbet, at Sølvdæmringen selv ville yde bistand, men jeg er ikke desto mindre taknemmelig for din hjælp.\n\nTal med Inkvisitor Kaldoran på bakken i nærheden. Han kan få dig i gang."},
  [87502] = {n="Indsamling af efterretninger", l="Gå ind i Tyrs Hånd i de Østlige Pestlande, og spejd den centrale katedral, samt magikertårnet og fæstningen inde i Nyt Avalon, inden du vender tilbage til Kaldoran i Skarlagen-basislejren.\n\nEt direkte indfald er muligt, men kan være farligt. Tal med Inkvisitor Jocifine i Skarlagen-basislejren, hvis du foretrækker en mere subtil tilgang.", d="Jeg er ikke glad for at bede dig om hjælp. Du omgås kætteren og de urene, og det er under mig og vores hellige orden at tolerere din tilstedeværelse her. Men... du virker tilstrækkelig dygtig og vil vise dig at være et nyttigt redskab for vores behov her.\n\nGå til Tyrs Hånd og spejd katedralen der, før du bevæger dig dybere ind i Nyt Avalon for at spejde fæstningen bagerst og magikertårnet. Vend tilbage hertil uden forsinkelse og rapportér, hvad du finder. Vi må vide, hvad vi står over for.", p="Har du fuldført din mission? Hvis ikke, hvorfor står du så her og taler med mig uden at gøre noget?", c="<Kaldoran brummer kort ad dig, når du er færdig med at aflevere din rapport.>\n\nOpbygningen af styrker i Nyt Avalon er bekymrende, men deres antal er ikke uoverkommeligt.\n\nDet ser også ud til, at Dathrovan, eller skal jeg sige Balnazar, konsoliderer sin magt i den centrale katedral, og hans brug af onde magier til at forsegle indgangen bekræfter, at han er i gang med noget derinde. Det udyr vanhelliger vores hellige grund, og jeg vil se ham død med min egen hånd. Det sværger jeg på mit liv."},
  [87506] = {n="Svækkelse af forsvaret", l="Gå ind i Tyrs Hånd i de Østlige Pestlande, og slå tre Skarlagen-belejringskommandører ihjel.", d="Mens du var væk, færdiggjorde vi vores angrebsplaner mod Tyrs Hånd. Vi vil gennemføre et frontalt angreb samt et flankeangreb, som jeg selv vil lede. Før vi fuldt ud forpligter os, må vi svække de forreste forsvarsværker. Jeg sender dig tilbage ind i Tyrs Hånd for at fjerne så mange af fjendens belejringskommandører som muligt, for de er enklavens nøgleorganisatorer af forsvaret.\n\nJeg forlader nu for at slutte mig til mine styrker ved vores position. Du skal rapportere til Kommandør Beatrix, når du vender tilbage.\n\nSvigt ikke.", p="Lykkedes din mission?", c="Kaldoran og hans vagt har sendt signalet om, at de er på plads og klar til at støtte et direkte angreb.\n\nMens du var væk, ankom et bud fra Sølvdæmringen med en besked og skyndte sig hurtigt væk igen. Det ser ud til, at der er problemer ved Lysets Håb-kapellet, og du er påkrævet der hurtigst muligt. Jeg kan ikke bede dig om mere, da du allerede har været uvurderlig i denne indsats. Tak for din hjælp, <Name>. Vi er så klar, som vi nogensinde bliver."},
  [87508] = {n="Rapporter til Herre Tyrosus", l="Tal med Herre Maxwell Tyrosus ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Vær venlig, <Name>, et bud er netop ankommet. Du må vende tilbage til Lysets Håb-kapellet med det samme! Vi er under angreb, og Herre Maxwell Tyrosus har bedt om din tilstedeværelse med det samme.", c="Vi er blevet angrebet! Et slags drageagtigt... misfoster fløj hurtigt ind fra retningen af Skarlagen-enklaven og ramte os hårdt. Jeg har set drager før, men jeg har aldrig set noget lignende.\n\nDet mærkeligste er, at dragen bare... forsvandt. Den ramte os med et enkelt forfærdeligt udbrud og fløj så væk. Det er en velsignelse, det er sikkert - men det er dybt urovækkende. Vi var fuldstændig uforberedte. Den kunne have forvoldt enorm skade, men det så ud til, at den valgte ikke at gøre det."},
  [87509] = {n="Daggryets Vrede", l="Rapporter tilbage til Kommandør Beatrix i Skarlagen-basislejren i de Østlige Pestlande, og gør dig klar til at generobre Skarlagen-enklaven.", d="Uanset grunden til at det udyr trak sig tilbage til enklaven, vil vi ikke give det endnu en chance for at ødelægge os. Det ser ud til, at vores hånd er tvunget, og vi må nu forpligte Sølvdæmringens fulde vrede på at afslutte truslen fra Skarlagen-enklaven.\n\nGå tilbage til Skarlagen-basislejren og mød Beatrix igen. Lad hende vide, at hun har vores støtte... indtil videre.", p="Jeg så røg stige op fra retningen af Lysets Håb, hvad er sket?", c="Et slags udyr angreb Lysets Håb? Det er da dristigt af Balnazar. For dristigt, for nu har Sølvdæmringen forpligtet sig til vores sag. Jeg vil ikke lyve for dig og sige, at jeg ikke er lettet over at modtage deres hjælp. Jeg tror ikke, vi kan tage enklaven med de styrker, vi har til rådighed nu.\n\nVi er nu i slutspillet, <Class>. Gør dine styrker klar."},
  [87516] = {n="Halshugningsangrebet", l="Gå ind i Skarlagen-enklaven via bjergstien, og engager forsvarerne fra Tyrs Hånd. Ring med klokken inde i klostret for at skabe forvirring og signalere til Beatrix' styrker om at angribe.\n\nNår klokken er blevet ringet, konfronter Balnazar og tilintetgør ham.", d="Vores styrker er samlet, og vi vil bevæge os i position for at begynde det frontale angreb, mens dine styrker sniger sig rundt til katedralens bagside ad bjergstien.\n\nNår du er inde, skal du finde vej til klostret og ringe med klokken for at signalere angrebet.\n\nDu vil stå midt i de hårdeste kampe, indtil vi kommer og aflaster dig, så pas godt på dig selv.", p="Dette var næsten en fuldstændig katastrofe...", c="Vi er blevet forrådt! Efter Balnazar faldt, overtog Beatrix kontrollen over de herreløse forsvarere og vendte straks deres nyligt styrkede tropper imod os! Tabene var store, men vi slog hårdt tilbage og kunne trække os tilbage og samle os igen. Vi frygtede det værste for din styrke, indtil vores spejdere meldte, at du var her.\n\nJeg ved ikke, hvad Beatrix og Kaldoran går og laver, men på nuværende tidspunkt er jeg klar til at slå enhver ned, jeg ser iført rødt, og lade lyset tage sig af resten."},
  [87517] = {n="Rød = Død", l="Deltag i kampen og få adgang til den indre del af Skarlagen-enklaven. Engager Overkommandør Beatrix' styrker og besejr hende, og dræb derefter dragen Solbrandsa inde bag enklavens indre mure.", d="Det ser ud til, at det udyr, der angreb Lysets Håb, er Kaldorans kæledyr, og angrebet på Lysets Håb var blot et påskud for at lokke vores styrker ud og forpligte os til dette angreb. Kaldoran og Beatrix ønskede at bruge os til at skabe en afledning og fjerne en rival i Balnazar, for derefter at vende sig imod os og fjerne os som tilstedeværelse i pestlandene, når de havde genvundet kontrollen.\n\nVi har ikke alle svarene, og det ser dystert ud, men vi vil lægge disse hunde i graven for dette forræderi.", p="Hvad i lysets navn har det Skarlagenrøde Korstog lavet bag disse mure?", c="Det, vi har opdaget her, er ud over alt, hvad man kan acceptere. En ny pest? En lysbundet drage? Udsugning af de fromme sjæle for at drive deres lysindgydte våben? Sådan et misbrug af lyset er kvalmende, og jeg gyser ved tanken om, hvilken anden magt Kaldoran måske stadig har til rådighed. Måden, han tilintetgjorde Balnazar på, fortæller mig, at han har lavet noget. Sådan rå kraft rækker ud over selv de stærkeste paladiner.\n\nUanset alt det her slutter nu. Der vil ikke blive givet nåde. Disse grusomheder er ud over forsoning."},
  [87518] = {n="Den Storslåede Korsfarers Fald", l="Dræb Storslået Korsfarer Baelin Kaldoran i Skarlagen-enklavens indre helligdom.", d="Vejen frem er nu enkel og brutal. Bryd ind i Skarlagen-enklavens indre helligdom, og konfrontér den nye selvudnævnte \"Storslået Korsfarer\" Baelin Kaldoran. Før ham for retten for hans forbrydelser. Vi bliver her og sikrer denne position, så ingen rester af styrker kan genere dig bagfra.\n\nFør det udyr for retten.", c="Kaldoran er ikke mere, men sejren er bittersød. Det har været en blodig dag. Med det Skarlagenrøde Korstogs resterende styrker spredt og Skarlagen-enklaven i flammer har vi udrettet noget stort her. Der er stadig meget arbejde at gøre i pestlandene, men i det mindste har vi én modstander mindre at bekymre os om for nu. Så vidt jeg er bekymret, er det en grund til at fejre.\n\nFor Lyset! For Herrelande! For Daggryet!"},
  [87520] = {n="Lysets Antitese", l="Bring den mærkelige sorte krystal til Herre Maxwell Tyrosus ved Lysets Håb-kapellet.", d="Den glatte sorte genstand foran dig pulserer ildevarslende. Det er, som om denne genstand trækker alt lys i nærheden ind og opsluger det. Din intuition fortæller dig, at genstanden er farlig, og at det ville være uklogt at røre ved den med bare hænder.\n\nDu svøber genstanden ind i et stykke stof og gemmer den i din rygsæk. Herre Maxwell Tyrosus ved Lysets Håb-kapellet er måske interesseret i denne."},
  [88654] = {n="En Fuld Forsendelse", l="Har du noget til mig?", p="Har du noget til mig?", c="Alt er regnskabsført! Tak, <Name>. Disse forsyninger er afgørende for frontlinjen."},
  [88713] = {n="Aldrig i Ro", l="Bring endnu et Dommens Hjerte til Broder Luctus ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bring mig alle de dømte sjæle, der krydser din vej, <Name>.\n\nLad mig rette det - du SKAL bringe dem til mig.\nMIN pligt er at blive og lede de fortabte sjæle. DIN pligt er at bringe dem til mig.\n\nEt godt råd: håndter aldrig mere end én sjæl ad gangen. Tro mig, din sjæl kan kun klare så meget, og dit sind... tja... det kan klare endnu mindre.\n\nByrden er nu din. Fordi du kan, må du.\n\nTænk på det som en moralsk forpligtelse.", p="Svøben hviler aldrig, så vi må heller aldrig hvile, <Name>.", c="Med hvert hjerte returneret, <Name>, står jeg ydmyget. Nogle af sjælene tilhørte mægtige krigere. Nogle virkede ubøjelige... og alligevel... de faldt.\n\nSvøben overvældede dem, korruptionen sivede ind i deres sind, eller i nogle tilfælde - de underkastede sig frivilligt.\n\nSå stor styrke - slukket.\n\nOg takket være dig bevarer de nu deres sidste rest af mod.\n\nUden dig ville rædslerne ved deres død veje tungere end heltedådene i deres liv."},
  [88714] = {n="Aldrig i Ro", l="Bring endnu et Dommens Hjerte til Broder Luctus ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Bring mig alle de dømte sjæle, der krydser din vej, <Name>.\n\nLad mig rette det - du SKAL bringe dem til mig.\nMIN pligt er at blive og lede de fortabte sjæle. DIN pligt er at bringe dem til mig.\n\nEt godt råd: håndter aldrig mere end én sjæl ad gangen. Tro mig, din sjæl kan kun klare så meget, og dit sind... tja... det kan klare endnu mindre.\n\nByrden er nu din. Fordi du kan, må du.\n\nTænk på det som en moralsk forpligtelse.", p="Svøben hviler aldrig, så vi må heller aldrig hvile, <Name>.", c="Med hvert hjerte returneret, <Name>, står jeg ydmyget. Nogle af sjælene tilhørte mægtige krigere. Nogle virkede ubøjelige... og alligevel... de faldt.\n\nSvøben overvældede dem, korruptionen sivede ind i deres sind, eller i nogle tilfælde - de underkastede sig frivilligt.\n\nSå stor styrke - slukket.\n\nOg takket være dig bevarer de nu deres sidste rest af mod.\n\nUden dig ville rædslerne ved deres død veje tungere end heltedådene i deres liv."},
