  [88721] = {n="Overlegen Kampoprustning - Ven af Daggry", l="For 30 Insignier fra Daggry og 30 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nJeg må advare dig; køb foretaget med venlig ry hos Daggry kommer med en kraftig overpris. Jeg vil anbefale, at du opnår et bedre ry hos Daggry, før du går videre med dine planer.", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88722] = {n="Overlegen Kampoprustning - Æret blandt Daggry", l="For 20 Insignier fra Daggry og 20 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nJeg må advare dig; køb foretaget med æret ry hos Daggry kommer med en temmelig afskrækkende overpris. Jeg vil anbefale, at du opnår et bedre ry hos Daggry, før du går videre med dine planer.", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88723] = {n="Overlegen Kampoprustning - Respekteret blandt Daggry", l="For 7 Insignier fra Daggry og 7 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nGenstande tilbudt dem, der er Respekteret blandt Daggry, er prissat ganske rimeligt. Jeg opfordrer dig til at foretage et køb!", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88724] = {n="Overlegen Kampoprustning - Ophøjet blandt Daggry", l="For 6 Insignier fra Daggry og 6 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande med kraft?\n\nGenstande tilbudt dem, der er Ophøjet blandt Daggry, er nedsatte. Jeg opfordrer dig til at foretage et køb!", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88725] = {n="Episk Kampoprustning - Ven af Daggry", l="For 110 Insignier fra Daggry og 110 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande af stor kraft?\n\nJeg må advare dig; køb foretaget med venlig ry hos Daggry kommer med en ekstremt kraftig overpris. Jeg vil anbefale, at du opnår et bedre ry hos Daggry, før du går videre med dine planer."},
  [88726] = {n="Episk Kampoprustning - Æret blandt Daggry", l="For 75 Insignier fra Daggry og 75 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande af stor kraft?\n\nJeg må advare dig; køb foretaget med æret ry hos Daggry kommer med en ekstremt kraftig overpris. Jeg vil anbefale, at du opnår et bedre ry hos Daggry, før du går videre med dine planer."},
  [88727] = {n="Episk Kampoprustning - Respekteret blandt Daggry", l="For 45 Insignier fra Daggry og 45 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande af stor kraft?\n\nJeg må advare dig; episke køb foretaget med respekteret ry hos Daggry er stadig ganske dyre. Jeg vil anbefale, at du opnår et bedre ry hos Daggry, før du går videre med dine planer.", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88728] = {n="Episk Kampoprustning - Ophøjet blandt Daggry", l="For 27 Insignier fra Daggry og 27 Insignier fra Korstoget kan du vælge en genstand fra Sølvdæmringens skatkammer.", d="Hilsner, ven. Har du insignier fra Daggry eller Korstoget, som du gerne vil indløse til genstande af stor kraft?\n\nDem, der er Ophøjet blandt Daggry, får vores største rabatter! Jeg opfordrer dig til at foretage et køb.", p="Vælg omhyggeligt. Der gives ingen refusion.", c="God dag, <Name>. Det var en fornøjelse at gøre forretning med dig."},
  [88729] = {n="Ramaladdis Isnende Greb", l="Korfaks ved Lysets Håb-kapellet i de Østlige Pestlande vil have, at du bringer ham 1 Frossen Rune, 1 Blå safir og 1 Arkanitbarre.", d="At reparere denne ring kan vise sig at være en ganske udfordring, <Name>. Du må vide, at den blev lavet af de samme runer, der dannes inde i Svøbens bygningsværker - som Naxxrammas. Der kræves også yderligere materialer, men din primære bekymring bør være at skaffe de frosne runer. Bring mig det, jeg behøver, så genopretter jeg ringen til dens fordums herlighed.", p="Frosne runer kan nok findes inde i Naxxrammas.", c="Ramaladdi selv kunne ikke have gjort det bedre! Her er ringen, som lovet."},
  [88730] = {n="Den Eneste Sang Jeg Kender...", l="Håndværker Vilhelm ved Lysets Håb-kapellet i de Østlige Pestlande vil have, at du bringer ham 2 Frosne Runer, 2 Vandets Essens, 2 Blå safirer og 30 guldstykker.", d="Du indbilder dig vist, at du er en helt fra Daggry, hva'? Jeg har set vores største soldater blive overrullet af Kel'Tuzads pøbel! Hvor godt mon nogen så uvidende kan klare sig i Naxxrammas?\n\n<Wilhelm sukker.>\n\nBah, hvad har jeg for valg? Du er det bedste, jeg kan opdrive; jeg kan lige så godt hjælpe dig.\n\nOmarjon efterlod mig én opskrift. Det er den eneste sang jeg kender... Jeg kan lave et par variationer af disse bukser; du skal bare skaffe materialerne.", p="Du er vel ikke stødt ind i Omarjon?", c="<Wilhelm tørrer sveden af panden.>\n\nDet var noget hårdt arbejde! Nyd bukserne, <Class>. I det mindste dør du nu i et rent par."},
  [88744] = {n="Under Skyggen", l="Tjek dit kort for at finde et område under angreb fra Svøben. Gå derhen og beskadig en nekropolis ved at besejre Svøben omkring den. Returner 10 af deres Nekrotiske Runer til Kommandør Thomas Hellerann ved Lysets Håb-kapellet i de Østlige Pestlande.", d="De svævende nekropolisser hjemsøger både Horden og Alliancen. Tanaris, Det Sønderrevne Land, Vinterkilde og Brændende Stepper er dækket af skyggerne fra de flyvende fæstninger.\n\nKun gennem vores fælles indsats vil de blive drevet bort.\n\nNekropolisserne understøttes af magiske kredse på forskellige steder i de invaderede områder. Vi har fastslået, at ødelæggelsen af de tankeløse horder, der omgiver disse kredse, vil ødelægge deres forsvar.", p="Det vil tage tid at sejre over denne trussel. Hvordan er det gået dig, <Name>?", c="Du har gjort det godt, <Name>. Gennem disse gradvise nederlag skal vi sejre over Svøbens fornyede trussel.\n\nHvil og restituer dig, men så må du drage ud til fronten igen, for at vi ikke mister den jord, vi har vundet i dag.\n\nFor at hjælpe dig i de videre kampe vil vi gøre nogle af vores særlige genstande tilgængelige for dig i bytte for flere nekrotiske runer."},
  [88745] = {n="Dommens Skygger", l="Gå til en fremkaldelseskreds og dræb en Dommens Skygge, og vend derefter tilbage til Kommandør Thomas Hellerann ved Lysets Håb-kapellet i de Østlige Pestlande.", d="Efter du har brudt forsvaret hos Svøbens fremkaldelseskredse, der er dukket op i de angrebne zoner, kan du konfrontere de akolytter, der beskytter dem.\n\nI sandhed er de ikke mænd. De er skygger, nogle af Liskekongens mest skræmmende væsener. De kan afsløres ved hjælp af de nekrotiske runer, de bærer, og derefter ødelægges med magi eller våbenstyrke.", p="Har du haft held, <Name>?", c="Fremragende arbejde, <Name>. Nu hvor skyggerne er ødelagt, kan det kun være et spørgsmål om tid, før Liskekongen beslutter at kalde sine nekropolisser tilbage og lade os være i fred."},
  [88746] = {n="Indviede Slibesten", l="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være til stor hjælp i din kamp mod Liskekongens håndlangere.", p="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være til stor hjælp i din kamp mod Liskekongens håndlangere.", c="Tak, <Name>. Her er dine indviede slibesten. Brug dem med omtanke."},
  [88747] = {n="Indviede Slibesten", l="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være til stor hjælp i din kamp mod Liskekongens håndlangere.", p="Hvis du bringer mig otte nekrotiske runer fra Svøbens invasionsstyrker, kan jeg give dig en indviet slibesten. Den bør være til stor hjælp i din kamp mod Liskekongens håndlangere.", c="Tak, <Name>. Her er dine indviede slibesten. Brug dem med omtanke."},
  [88748] = {n="Revnet Nekrotisk Krystal", l="Bring den revnede nekrotiske krystal til Løjtnant Orrin uden for portene til Stormvind.", d="På liget af den faldne vederstyggelighed opdager du en revnet krystal, der langsomt pulserer med nekrotisk energi.", p="Er der noget, du har brug for?", c="Hm, tog du den fra liget af en af de invaderende vederstyggeligheder?\n\nVi har modtaget besked om nekropolis-basislejrene, som Svøben er ved at fremkalde. Jeg formoder, at de ønskede at skabe en inde i Stormvind. Det er godt, at de ikke lykkedes."},
  [88749] = {n="Svag Nekrotisk Krystal", l="Bring den svage nekrotiske krystal til Løjtnant Rukag på gårdhaven i Undergrunden.", d="På liget af den faldne gengænger finder du en krystal, der svagt udstråler nekrotisk energi.", p="Kan jeg hjælpe dig med noget?", c="Siger du, at denne blev taget fra en gengænger, der angreb byen?\n\nVi har modtaget besked om nekropolis-basislejrene, som Svøben er ved at fremkalde. Jeg formoder, at de forsøgte at skabe en i Undergrunden. Vi må være årvågne fremover."},
  [88882] = {n="Velsignet Troldmandsolie", l="I bytte for Svøbens invasionsstyrkers nekrotiske runer giver Sølvdæmringen dig ét hætteglas velsignet troldmandsolie.", p="I bytte for Svøbens invasionsstyrkers nekrotiske runer giver Sølvdæmringen dig ét hætteglas velsignet troldmandsolie.", c="Jeg håber, at du finder disse genstande nyttige i fremtidige kampe."},
  [88883] = {n="Velsignet Troldmandsolie", l="I bytte for Svøbens invasionsstyrkers nekrotiske runer giver Sølvdæmringen dig ét hætteglas velsignet troldmandsolie.", p="I bytte for Svøbens invasionsstyrkers nekrotiske runer giver Sølvdæmringen dig ét hætteglas velsignet troldmandsolie.", c="Jeg håber, at du finder disse genstande nyttige i fremtidige kampe."},
  [88968] = {n="Herren over Sortklippe", l="Tal med Højoverherre Øglefang i Orgrimgrad. Han venter på dig i Styrkens Dal.", d="Søg Højoverherre Øglefang i Styrkens Dal.", c="Vælg din belønning, så jeg kan montere udyrets hoved, så alle kan se det."},
  [88969] = {n="Sortklippes Herre", l="Begiv dig til Heltenes Dal i Stormvind By og tal med Feltmarskal Stenbro.", d="Gå til Heltenes Dal og tal med Feltmarskal Stenbro.", c="<Feltmarskal Stenbro bukker.>\n\nVælg din belønning, lad festen begynde!"},
  [89224] = {n="Madmangel", l="Skaf Usmagelige Rester fra hele Nyt Avalon og bring dem tilbage til kokken. Hvis du har svært ved at finde dem spredt rundt omkring, kan du måske have mere held med at løse mangelen med vold.", d="<Kokken begynder at tale, før du overhovedet når at sige en simpel hilsen.>\n\nLys være med dig, hjælpen er endelig kommet! Hverken ovnen eller spisekammeret kan følge med den pludselige flodbølge af bestillinger, der strømmer ind. Noget er sket, der har afskåret vores sædvanlige forsyningslinjer, og jeg går ud fra, at alt skriget udenfor har noget med det at gøre.\n\nUanset årsagen har jeg brug for hjælp. Nu. Hent mig alt, der ser nogenlunde spiseligt ud fra byen, så tager vi den derfra.", p="Lad mig være i fred, indtil du har samlet nogle ingredienser.", c="Åh. Åh... Jeg forventede gammelt brød, overmodne frugter og måske en tallerken halvspiste kager eller noget.\n\nJeg aner virkelig ikke, hvad nogle af disse retter engang var, og jeg lavede dem! Og den... lugt... Prøver du at sabotere mit køkken?\n\nDybe vejrtrækninger, Carrie...\n<Kokken lukker øjnene, indånder langsomt gennem næseborene og puster blidt ud et øjeblik senere.>\n\nLad os prøve igen."},
  [89229] = {n="Den Rette Vej", l="Tal med Leonid Barthalomæus den Ærværdige i Lysets Håb-kapellet for at modtage din belønning.", d="Nu kender du hele historien. Det var smertefuldt at genopleve alt dette, men jeg har udskudt at se det i øjnene alt for længe. Underligt nok føler jeg mig... bedre. Jeg har bedt om retfærdighed så længe, men det er ikke min byrde at bære at udføre den retfærdighed. Jeg har valgt min egen vej, og at lade hævnen trække mig tilbage i mørket vil ikke bringe mig fred, og det vil heller ikke ære min søns ønsker.\n\nJeg er på vej tilbage for at aflevere min rapport til Herre Tyrosus. Vi ses tilbage i Lysets Håb. Jeg har noget til dig der.", c="Caldorans opgør vil komme til sidst, for hans slags ondskab er i sidste ende selvdestruktiv. Jeg har tro på det, ligesom jeg har tro på min søns drøm.\n\nVær så venlig, tag den her. Den blev givet til mig af Liljana, da jeg blev optaget i Sølvhånden, og den tjente mig godt som en påmindelse om mine eder til min familie og mit land under mine år i tjeneste. Jeg håber, den kan tjene som en påmindelse om, at det altid er mørkest før daggry, men daggry vil altid komme."},
  [89232] = {n="Det Første Skridt", l="Tal med Askebringerens Vilje og hør, hvad den har at sige.", d="I Caldorans hovmod troede han, at han kunne tvinge klingen til at underkaste sig sin vilje. Han stjal livet fra sine mest hengivne tilhængere for at brænde sit forsøg på at dominere klingen. Det han ikke indså er, at denne magt ikke kan tages med magt; dens rensning skal fortjenes.\n\nTal med mig videre, hvis du ønsker at se klingen genoprettet. Hvis du er stærk nok, kan du måske lykkes.", p="<Askebringerens Viljes spektrale kontur skifter og ryster på en urovækkende måde.>", c="Så nu ser du? Du må føre dette til ende, og enden er langt fra sikker. Hvis du vil se denne opgave fuldført, må du have mod, selv over for den usikkerhed.\n\nHar du det mod?"},
  [89234] = {n="En Personlig Sag", l="Mød Leonid Barthalomæus den Ærværdige lige uden for tjenesteindgangens port øst for Strædholmes hovedporte.", d="Det, vi talte om i Lysets Håb, og min historie med Kaldoran... Det hele begyndte lige her i Strædholme. Du kender til „udtyndingen“ af Strædholme, der fandt sted tidligt i Den Tredje Krig, ikke?\n\nJa, jeg var her, og det var Kaldoran også. Her begynder vores historie. Hvis du er villig, så mød mig lige uden for Strædholmes tjenesteindgang mod øst.", c="Jeg er glad for, at du kom. Jeg ved ikke, om jeg kunne klare det, der kommer nu, alene."},
  [89235] = {n="Udtyndingen", l="Gå ind i Strædholme, find vej gennem porten til Slagterpladsen, og find Leonid Barthalomæus den Ærværdige der.", d="Byen bag os er et hjemsøgt sted. Jeg tilbragte år her efter min oprindelige død som trællen under Liskekongen, men selv i min trældom bevarede jeg en vis grad af bevidsthed. Utallige gange gik jeg forbi min hustrus lig, frosset for evigt i den frygt, hun følte, da enden kom.\n\nVær venlig at finde vej gennem porten, der fører til området, som nu kaldes Slagterpladsen. Jeg vil møde dig der, når jeg har fundet min besluttsomhed. Du får brug for allierede til dette.", c="Så nu forstår du, hvorfor jeg foragter Kaldoran. Han er en mand med hadefuld fanatisme. Det var han dengang, og det er han nu. Kaldoran fulgte ikke med Arthæus' ekspedition til Nordrend, men jeg ønsker inderligt, at han havde fundet sin ende der, og at dette var enden på vores historie sammen."},
  [89236] = {n="Æblekaos", l="Find æblehaven i den sydlige del af Nyt Avalon for at hente nogle æbler. Vend tilbage til Carrie Ildsted i Nyt Avalons kro, når du er lykkedes. Hvis du finder æblerne for dyre, kan du overveje at lede efter en anden måde at skaffe dem på.", d="Hvis du spørger mig, er frisk frugt det bedste ved ethvert måltid. Æbler er mine yndlingsfrugter, og heldigvis har vi en blomstrende frugthave lige syd for her.\n\nHvis den ikke er blevet antændt endnu - hvilket er en klar mulighed - vil jeg vædde på, at det er ved at være tid til høst!\n\nNormalt vil landarbejderne gerne give mig rabat, men jeg skylder dem stadig en tærte. At få dem billigt er udelukket, men du ser ud til at have råd til dem.", p="På trods af at bo en stenkastes afstand fra en frugthave, er det overraskende svært at få fat i æbler nogle gange.", c="<Carrie inspicerer omhyggeligt hvert æble for ufuldkommenheder. Stilheden imens er lang og pinlig.>\n\nDu har et øje for kvalitet, når du ikke roder i skraldet. Det er de friskeste æbler, jeg har set, siden mine yngre dage i klostret!\n\nJeg må indrømme, at jeg var klar til at inddrage dit medlemskab efter din første levering. Bliver du ved med det, må jeg måske i stedet tilbyde dig en fuldtidsstilling."},
  [89237] = {n="Det Kan Blive Dyrt...", l="Bring Mesterhåndværker Omarjon 20 Arkanitstænger, 20 Sortglas-infunderede Thoriumstænger, 120 Ægtesølvstænger, 10 Kæmpe Smaragder og 20 Retfærdige Kugler.", d="For at skabe denne legering skal vi bruge en masse materialer at eksperimentere med. Jeg har forberedt en liste, og ja, jeg sagde jo nok, at det kunne blive dyrt.\n\n<Omarjon rækker dig en liste, der er næsten lige så lang som din underarm.>", p="Hør, metallurgiske mirakler sker ikke bare ved magi. Du har brug for tid, tålmodighed og nogen med dybe lommer.", c="Når jeg tænker på alt det her, bliver mine øjne lidt våde. Nå, intet vove, intet vinde."},
  [89245] = {n="Fisk i en Tønde", l="Undersøg båden, der ligger fortøjet syd for Nyt Avalon, for en forsendelse fisk, og bring et læs tilbage til Carrie.", d="Jeg tjente i Hjertedal i en periode, og jeg kan ikke fortælle dig, hvor forfærdeligt det var at være afhængig af leverancer fra hele Pestlandene for at holde os mætte. At Nyt Avalon har en stabil forsyningskæde ad søvejen har været en velsignelse, i hvert fald indtil for nylig.\n\nI endnu et tilfælde af „Carrie prøver at fodre en hær med et køkken beregnet til en familie“ har jeg brug for fisk. Tjek molen mod syd for at se, om min bestilling er ankommet.", p="Nævnte jeg, at jeg hader lugten af fisk? Måske burde jeg bede dig om at tage en tøjklemme med, når du er ude.", c="Jeg genkender ikke et par af dem, men en fisk er vel en fisk. Under alle omstændigheder ser jeg allerede frem til at få alt dette ud af mit køkken.\n\nTak for din hjælp, selvom det var en opgave, jeg faktisk håbede, at du ville vende tilbage fra med tomme hænder."},
  [89253] = {n="Hovedretten", l="Skaf kød, der er sikkert for mennesker at spise. Hvis du har svært ved at finde noget i Nyt Avalon, kan du (til sidst) samle nok ved at slå bæster i de Østlige Pestlande.", d="Intet måltid er virkelig komplet uden stjernen i retten - kødet! Som du sikkert kan forestille dig, er jagt efter kød, der er sikkert at spise i Pestlandene, en udfordring uden sidestykke.\n\nFor at gøre det værre spiser vores hunde kun kød! Jeg er sikker på, at du kan se, hvor det her er på vej hen, og jeg er sikker på, at du nu forstår, hvorfor jeg altid er bagud.\n\nNå? Hvad venter du på?", p="Allerede tilbage? Det kan ikke være godt.", c="Din hurtighed er værdsat og mistænkelig; næsten lige så mistænkelig som farven på disse kødstykker. Heldigvis har vi alle opbygget stærke maver under vores tid herude.\n\nNogle få snit her, et strejf af krydderier der, og ingen vil være klogere.\n\nDisse burde være tilstrækkelige, håber jeg. Tak."},
  [89255] = {n="Bevis Din Værdi: Hovedbeklædning", l="Fremstil et stykke Skarlagenrød Hovedbeklædning fra et hvilket som helst rustningsfremstillingserhverv, eller doner et stykke fremstillet udstyr fra Skarlagenrød Uniform.\n\nHvis du vælger at donere, kan du finde en kasse nær kvartermesteren inde i kasernen. Lever den kassede genstand tilbage til Bryon Stålklinge for at modtage kredit.", d="At holde sig på toppen af dit håndværk er afgørende for at opretholde en høj standard af kvalitet. Vores soldater overlader deres liv til ukendte håndværkere, og til mig for at sikre kvaliteten af hvert eneste stykke rustning.\n\nMin opgave til dig er enkel. Hvis du er velbevandret i Skrædderi, Læderarbejds- eller Smedning, så fremstil et stykke hovedbeklædning, udelukkende til din egen fordel. Du må gerne beholde resultatet.\n\nHvis du mangler færdighederne, så bestil og doner et hvilket som helst stykke af korstogets uniform i stedet.", p="Fremstil eller bidrag; valget er dit. Vores våbenkammer er godt udstyret til alt, hvad der kommer vores vej, men det vigtigste er, at vores håndværkere har rigelige muligheder for at øve sig og forfine deres teknik.", c="Fortrinligt udført.\n\nVi er begyndt at gemme konfiskeret skrammel i disse gamle kister, og jeg løber snart tør for plads til at opbevare dem, men du virker til at være den slags, der sætter pris på de små ting. Jeg synes, dette er en passende belønning for et enkelt bidrag.\n\nÅh, og jeg har lagt en værdifuld overraskelse i nogle af dem. Måske bliver du en af de heldige?"},
  [89256] = {n="Bevis Din Værdi: Skulderbeskyttere", l="Fremstil et par Skarlagenrøde Skulderbeskyttere fra et hvilket som helst rustningsfremstillingserhverv, eller doner et stykke fremstillet udstyr fra Skarlagenrød Uniform.\n\nHvis du vælger at donere, kan du finde en kasse nær kvartermesteren inde i kasernen. Lever den kassede genstand tilbage til Bryon Stålklinge for at modtage kredit.", d="At holde sig på toppen af dit håndværk er afgørende for at opretholde en høj standard af kvalitet. Vores soldater overlader deres liv til ukendte håndværkere, og til mig for at sikre kvaliteten af hvert eneste stykke rustning.\n\nMin opgave til dig er enkel. Hvis du er velbevandret i Skrædderi, Læderarbejds- eller Smedning, så fremstil et par skulderbeskyttere, udelukkende til din egen fordel. Du må gerne beholde resultatet.\n\nHvis du mangler færdighederne, så bestil og doner et hvilket som helst stykke af korstogets uniform i stedet.", p="Fremstil eller bidrag; valget er dit. Vores våbenkammer er godt udstyret til alt, hvad der kommer vores vej, men det vigtigste er, at vores håndværkere har rigelige muligheder for at øve sig og forfine deres teknik.", c="Fortrinligt udført.\n\nVi er begyndt at gemme konfiskeret skrammel i disse gamle kister, og jeg løber snart tør for plads til at opbevare dem, men du virker til at være den slags, der sætter pris på de små ting. Jeg synes, dette er en passende belønning for et enkelt bidrag.\n\nÅh, og jeg har lagt en værdifuld overraskelse i nogle af dem. Måske bliver du en af de heldige?"},
  [89257] = {n="Bevis Din Værdi: Bryststykke", l="Fremstil et Skarlagenrødt Bryststykke fra et hvilket som helst rustningsfremstillingserhverv, eller doner et stykke fremstillet udstyr fra Skarlagenrød Uniform.\n\nHvis du vælger at donere, kan du finde en kasse nær kvartermesteren inde i kasernen. Lever den kassede genstand tilbage til Bryon Stålklinge for at modtage kredit.", d="At holde sig på toppen af dit håndværk er afgørende for at opretholde en høj standard af kvalitet. Vores soldater overlader deres liv til ukendte håndværkere, og til mig for at sikre kvaliteten af hvert eneste stykke rustning.\n\nMin opgave til dig er enkel. Hvis du er velbevandret i Skrædderi, Læderarbejds- eller Smedning, så fremstil et bryststykke, udelukkende til din egen fordel. Du må gerne beholde resultatet.\n\nHvis du mangler færdighederne, så bestil og doner et hvilket som helst stykke af korstogets uniform i stedet.", p="Fremstil eller bidrag; valget er dit. Vores våbenkammer er godt udstyret til alt, hvad der kommer vores vej, men det vigtigste er, at vores håndværkere har rigelige muligheder for at øve sig og forfine deres teknik.", c="Fortrinligt udført.\n\nVi er begyndt at gemme konfiskeret skrammel i disse gamle kister, og jeg løber snart tør for plads til at opbevare dem, men du virker til at være den slags, der sætter pris på de små ting. Jeg synes, dette er en passende belønning for et enkelt bidrag.\n\nÅh, og jeg har lagt en værdifuld overraskelse i nogle af dem. Måske bliver du en af de heldige?"},
  [89258] = {n="Bevis Din Værdi: Armbeskyttere", l="Fremstil et par Skarlagenrøde Armbeskyttere fra et hvilket som helst rustningsfremstillingserhverv, eller doner et stykke fremstillet udstyr fra Skarlagenrød Uniform.\n\nHvis du vælger at donere, kan du finde en kasse nær kvartermesteren inde i kasernen. Lever den kassede genstand tilbage til Bryon Stålklinge for at modtage kredit.", d="At holde sig på toppen af dit håndværk er afgørende for at opretholde en høj standard af kvalitet. Vores soldater overlader deres liv til ukendte håndværkere, og til mig for at sikre kvaliteten af hvert eneste stykke rustning.\n\nMin opgave til dig er enkel. Hvis du er velbevandret i Skrædderi, Læderarbejds- eller Smedning, så fremstil et par armbeskyttere, udelukkende til din egen fordel. Du må gerne beholde resultatet.\n\nHvis du mangler færdighederne, så bestil og doner et hvilket som helst stykke af korstogets uniform i stedet.", p="Fremstil eller bidrag; valget er dit. Vores våbenkammer er godt udstyret til alt, hvad der kommer vores vej, men det vigtigste er, at vores håndværkere har rigelige muligheder for at øve sig og forfine deres teknik.", c="Fortrinligt udført.\n\nVi er begyndt at gemme konfiskeret skrammel i disse gamle kister, og jeg løber snart tør for plads til at opbevare dem, men du virker til at være den slags, der sætter pris på de små ting. Jeg synes, dette er en passende belønning for et enkelt bidrag.\n\nÅh, og jeg har lagt en værdifuld overraskelse i nogle af dem. Måske bliver du en af de heldige?"},
